local addonName, addonTable = ...

addonTable.questData['ko'] = {
[1] = {title = "The \"Chow\" Quest (123)aa", objective = "Kill Kobold Vermin, 2 of em.$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAIN다음 주문들이 당신에게 시전될 것입니다:\n\n", description = "$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAIN다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n닭\n\n다음과 같은 것들을 받습니다:\n\n"},
[2] = {title = "뾰족발톱의 발톱", objective = "뾰족발톱의 발톱을 잿빛 골짜기의 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다.", description = "강력한 히포그리프 뾰족발톱의 발톱은 당신의 승리를 나타내는 명백한 증거가 되어 줄 것입니다. 토막나무 주둔지에 있는 세나니 썬더하트에게 이 자랑스러운 전리품을 보여 주십시오.", progress = "<class>|1이여;여;, 당신이 오리라 직감했습니다. 사냥에 대해 저에게 알려줄 소식이 있지 않습니까?", completion = "&lt;name&gt;, 정말 대단합니다... 뾰족발톱의 발톱을 얻기가 쉽지는 않았을 텐데! 잿빛 골짜기 사냥에 성공했군요!\n\n뾰족발톱은 오래전부터 자신의 비행경로에서 눈에 띄는 자들은 모조리 공격했습니다. 때문에 벌목지에서 여기 토막나무 주둔지로 이동하는 일꾼들은 모두 공포에 떨어야 했습니다. 그놈을 처치했다는 이 기쁜 소식이 잿빛 골짜기에 퍼지면 많은 이들이 벌목지에 모닥불을 피워놓고 둘러앉아 당신의 용맹을 칭송할 것입니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5] = {title = "굶주린 지터스", objective = "주방장 그루얼과 대화해야 합니다.", description = "이 유령 마을에 몇 주 동안이나 숨어 지내다 보니 땅벌레와 잡초 외에는 아무것도 먹지 못했어요! 이젠 진짜 음식이 먹고 싶어요. 음식만 제대로라면 충분히 거래할 용의도 있다고요.\n\n맛있는 음식을 가져다주면 후하게 사례하죠.\n\n듣기로는 다크샤이어의 진홍 까마귀 선술집에 있는 주방장 그루얼이 아주 맛있는 갈색 게살 케이크를 만든다고 하던데...", progress = nil, completion = "게살 케이크가 필요하시다고요? 좋습니다. 몇 개 구워 드릴 수 있을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6] = {title = "개릭 패드풋 현상금", objective = "개릭 패드풋을 처치한 후 그 증거로 개릭의 가면을 노스샤이어 수도원 근처에 있는 부관 윌렘에게로 가져가야 합니다.", description = "몇 주 동안 우리 농부들과 상인들을 괴롭혀 온 개릭 패드풋이라는 살인마가 수도원 동쪽 다리 건너편 포도밭 근처에 있는 통나무집에서 목격되었습니다. 그 악당을 처치하고 증거로 그의 가면을 가져오시면 보상을 지급하도록 하겠습니다!\n\n개릭은 주위에 악당 패거리를 거느리고 있어 접근하기 쉽지 않을 것이니 조심하시기 바랍니다.", progress = "개릭의 통나무집은 찾았습니까? 마침내 녀석을 처치한 것입니까?", completion = "오! 결국 처치하셨군요! 엘윈 숲의 치안 확립을 위해 큰 공헌을 해 주셨습니다. 자, 여기 보상을 받으십시오!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n녹색 바지두겹 조끼기장 망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7] = {title = "코볼트 소탕", objective = "코볼트 졸개 10마리를 처치한 다음 치안대장 맥브라이드에게 돌아가야 합니다.", description = "자네에게 맡길 첫 임무는 쓰레기 같은 코볼트 녀석들을 처치하는 일일세. 북쪽의 숲에 가면 코볼트들이 무리를 이루고 있는 걸 볼 수 있을 것일세. 가서 벌레 같은 코볼트 졸개들을 보이는 대로 처치해 주게. 놈들의 수를 점차 줄여나가다 보면 언젠가 노스샤이어에서 완전히 몰아낼 날이 오겠지.", progress = nil, completion = "오, 훌륭하군. 그 코볼트들은 하찮은 겁쟁이와 도둑에 불과하지만 그 수가 워낙 많아서 우리에게 위협이 되고 있었네. 우리 스톰윈드의 인간들은 그런 놈들 따위에 신경을 쓸 상황이 아니라서 말일세.\n\n어쨌든 녀석들을 처리해줘서 고맙네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8] = {title = "도적의 거래", objective = "티리스팔 숲에 있는 여관주인 리니에게 평범한 편지를 가져가야 합니다.", description = "이보시오! 감당하기 힘들만큼 많은 실성한 좀비와 거미들을 상대로 싸워온 젊은이의 청 하나 들어주지 않으시겠소?\n\n여기 이 편지를 브릴에 있는 여관주인에게 가져가야 하는데... 이름이 리니 뭐라고 하더군. 성이야 몰라도 상관없소.\n\n어쨌든 그 여관은 세상을 헤쳐나가려는 역병의 희생자들이 모여있는 아담하고 아늑한 곳이지. 필요하면 휴식을 취하기에도 좋은 장소라오. 한번 다녀와보시오. 돌아오면 수고비는 넉넉히 주겠소.", progress = "어서 오세요, 손님. 무슨 일이신지요?\n\n포세이큰은 식욕도 분명 엄청날 테죠. 내 집처럼 편하게... 지친 몸의 피로를 푸세요. 제 이름은 리니입니다. 필요한 게 있으면 언제든지 불러주세요.", completion = "네? 편지요? 희소식이군요! 안 그래도 데스넬에 사시는 노모의 소식을 애타게 기다리던 참이었는데... 참으로 성인과 같은 분이시죠. 어떻게 지내시는지 궁금했는데.\n\n그런데... 뭐라고요? 내가 파는 물건들이 너무 비싸다고요? 그렇다면 아무것도 사지 않을 생각이로군요.\n\n내 눈앞에서 썩 사라져요. 사실 누가 그 편지를 보냈는지는 별 관심도 없었다고요. 이거나 갖고 어서 가라고요! 꺼져요!\n\n그리고 이 건달 같은 양반아, 돈이 좀 모였다 싶을 때 다시 오라고요...\n\n참, 이건 알아 둬요. 오랫동안 모험을 하거나 사냥을 한 후에는 이곳으로 돌아와 휴식을 취하는 게 신상에 이로울 거예요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n숲버섯맑은 샘물\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[9] = {title = "죽음의 땅", objective = "농부 살딘이 허수아비골렘 보초 20마리를 처치해 달라고 부탁했습니다.", description = "여기 이 꼴을 한번 보세요! 이 땅은 선량한 농사꾼들이 살던 곳이었는데 그 빌어먹을 도적 놈들이 농사꾼들을 모두 쫓아 버렸어요. 그러나 저까지 내쫓진 못했죠! 그런데 저기 허수아비골렘 보초들이 내 밭을 차지해 버린 것 같아요.\n\n괜찮으시면 당신이 가서 놈들을 20마리만 처치해 주지 않으시겠어요? 놈들을 처치하고 돌아오시면 대가를 지급해 드리겠습니다. 우선 제 밭에 있는 놈들부터 처치한 후에 다른 밭에 있는 놈들을 처치하시면 될 겁니다.", progress = nil, completion = "고맙습니다, 정말 친절하신 분이군요. 충분히 사례해 드릴만 하네요. 서부 몰락지대가 다시 번창할 날이 올지 누가 알겠어요. 그때까지 이 땅을 지켜나갈 겁니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n풍요의 바지풍요의 로브\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[10] = {title = "슈섕크 탈출", objective = "후임측량사 슈섕크가 어떻게 되었는지 알아보고 가젯잔에 있는 선임측량사 피즐도저에게 데려오거나 그의 측량 장비라도 찾아서 가져가야 합니다.", description = "이런 끔찍한 일이! 내 수석 조수이자 전 후임측량사였던 슈섕크를 여기서 남동쪽에 있는 사막으로 보냈었소. 우리가 모래지옥 협곡이라고 부르는 곳인데... 그러니까, 그 친구가 실종되어 버리고 말았소. 마지막으로 받은 보고에 의하면 그곳에 이상한 곤충들이 수도 없이 나타났다고 하오. 그렇다면, 벌써 사막의 주요 구역이 두 군데나 점령당한 걸까?\n\n모래지옥 협곡으로 가서 슈섕크를 찾아 주시오, 제발! 아니면 그의 측량 장비만이라도... 남은 거라고는 그것뿐일지도 모르겠소이다.", progress = "그래, 무슨 소식을 갖고 왔소? 보아하니 꽤 힘이 들었나 본데... 슈섕크는 살아 있소?", completion = "그 심성 착한 고블린 청년, 슈섕크가 가다니... 그의 죽음이 헛되이 되지 않기를...\n\n그의 측량 장비를 보니 이 곤충 사태가 상당히 심각한 듯하오. 녀석들은 태생적으로 절대 그렇게 영리할 수가 없는데... 배후에 뭔가 있는 게 분명하오. 지금까지 조사한 바로는 제3의 세력이 조종하고 있는 것 같소이다! 이게 사실이라면 가젯잔뿐만 아니라 온 사막에 불길한 징조요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[11] = {title = "갈퀴발 놀 현상금", objective = "병영에 있는 부관 레이너에게 놀의 화려한 완장 8개를 가져가야 합니다.", description = "이 땅에 어울리지 않는 흉포한 놀들이 엘윈 숲 경계에서 목격되었습니다. 대규모 놀 무리가 저 경비탑 남쪽의 숲을 차지했는데, 우리가 단독으로 상대하기에는 너무 버거운 숫자입니다. 또 다른 무리는 동쪽에 돌무덤 호수 근처 지역에 출몰하고 있습니다.\n\n누구든지 놀을 처치하는데 도움을 주는 자에게는 스톰윈드 군대에서 크게 사례할 것입니다. 단, 증거물로 놀의 화려한 완장을 제게 가져와야 합니다.", progress = "어서 오십시오. 놀들을 처치했습니까?", completion = "수고가 많았습니다! 정말 감사합니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n민병대 버클러민병대 바지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[12] = {title = "백성의 민병대", objective = "그라이언 스타우트맨틀이 데피아즈단 덫사냥꾼 15명과 데피아즈단 밀수업자 15명을 처치하고 감시의 언덕으로 돌아오라고 지시했습니다.", description = "백성의 민병대는 오직 서부 몰락지대의 영토를 지키고 이곳의 평화를 되찾는 것을 목표로 하고 있네. 불행히도 평화는 때로 피를 담보로 하지.\n\n우리 정찰병의 보고에 의하면 데피아즈단 덫사냥꾼들이 가까운 곳에서 파괴를 일삼고 있다고 하네. 펄브로우의 호박밭과 몰센 농장뿐만 아니라 북서쪽에 있는 장고로드 광산 근처에서도 데피아즈단 덫사냥꾼의 출몰 보고가 있었네. 우리 민병대에 지원할 생각이라면 데피아즈단 덫사냥꾼 15명과 데피아즈단 밀수업자 15명을 처치하고 돌아오게.", progress = nil, completion = "잘했네. 우리 정찰병이 귀관의 용감한 활약상을 확인하였다고 하더군. 지금까지 훌륭히 잘해내 주었네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[13] = {title = "백성의 민병대", objective = "그라이언 스타우트맨틀이 데피아즈단 강탈자 15명과 데피아즈단 약탈자 15명을 처치하고 감시의 언덕으로 돌아오라고 지시했습니다.", description = "잔인한 데피아즈단 강탈자 무리가 황금해안 채석장, 문브룩과 알렉스턴 농장을 약탈하는 것이 목격되었네. 백성의 민병대는 절대 이런 행위를 용납할 수 없네. 즉시 그곳으로 가서 서부 몰락지대에 정의가 살아 있다는 사실을 확실히 보여 주고 돌아오게.\n\n황금해안 채석장은 탑 서쪽의 해변 근처에 있다네. 귀관의 다음 훈련 단계는 사악한 데피아즈단 강탈자 15명과 데피아즈단 약탈자 15명을 처치하고 돌아오는 것일세.", progress = nil, completion = "지금까지 보여준 용감한 행동들로 귀관이 백성의 민병대로서 충분한 자격이 있음이 증명되었네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[14] = {title = "백성의 민병대", objective = "그라이언 스타우트맨틀이 데피아즈단 노상강도 15명과 데피아즈단 정찰병 5명과 데피아즈단 복면강도 5명을 처치하고 감시의 언덕으로 돌아오라고 지시했습니다.", description = "데피아즈단 몇 명이 우리의 감시망을 교묘히 피해다니고 있네. 내가 신뢰하는 정찰병의 보고에 따르면 데피아즈단들이 서부 몰락지대 최남쪽에 있는 농가를 약탈하고 다녔다고 하더군. 놈들은 비수 언덕에 숨어서 다음 계획을 도모하고 있는 것이 분명하네. 백성의 민병대의 이름으로 몹쓸 녀석들을 처단해 주게.", progress = nil, completion = "나는 더럽혀진 로데론 땅을 떠나 이곳, 내 고향의 냉혹한 현실 속으로 돌아왔지. 하지만 서부 몰락지대에는 아직 희망이 남아 있다고 믿네. 귀관이 전투에서 보여 준 용맹함을 보건대 민병대의 영광스러운 사명에 동참하기에 부족함이 없군. 귀관과 같이 용감한 &lt;class&gt;|1을;를; 백성의 민병대원으로 임명하게 되어 매우 자랑스럽게 생각하는 바이네. 언제나 정의의 빛이 환하게 비치길...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n백성의 민병대 검백성의 민병대 망치백성의 민병대 불막대\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[15] = {title = "메아리 광산 조사", objective = "코볼트 잡역부 10마리를 처치한 다음 치안대장 맥브라이드에게 돌아와 보고해야 합니다.", description = "정찰병의 보고에 의하면 생각했던 것보다 코볼트가 훨씬 많이 출몰하고 있다고 하네. 코볼트 잡역부 무리가 북쪽의 메아리 광산 근처에 야영지를 건설했네.\n\n광산으로 가서 코볼트 놈들을 처치해 주게나. 파악된 바로는 최소 10마리 이상으로 보이네. 놈들을 처치하고 다른 놈들이 더 있는지 알아본 다음 내게 보고해 주게.", progress = nil, completion = "코볼트 놈들이 우리 광산에 들어와 있다니 불쾌하군... 이래서야 원... 어쨌든, 이건 보상금일세. 그리고 다시 전투에 나갈 준비되는 대로 내게 알려 주게. 자네가 광산에 다시 한번 가 주었으면 하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[16] = {title = "목마른 제라드", objective = "밭에서 일하다 보면 갈증이 나기 마련이죠. 전 항상 시원하게 목을 적셔 줄 시원한 샘물을 찾고 있답니다.\n\n혹시 시원한 샘물을 가지고 계시다면 저와 거래하실래요?", description = nil, progress = "밭에서 일하다 보면 갈증이 나기 마련이죠. 전 항상 시원하게 목을 적셔 줄 시원한 샘물을 찾고 있답니다.\n\n혹시 시원한 샘물을 가지고 계시다면 저와 거래하실래요?", completion = "고마워요! 다시 또 거래를 하고 싶으면 언제든 찾아오세요.", rewards = "다음과 같은 것들을 받습니다:\n\n윤기나는 빨간 사과"},
[17] = {title = "울다만에서 재료 찾기", objective = "텔사마에 있는 가크 힐터치에게 자홍버섯 12개를 가져가야 합니다.", description = "자홍버섯이라는 식물이 새로이 발견되었다는 얘기를 들었다오. 자홍버섯은 울다만 발굴 현장의 깊숙한 곳에서 군생하고 있지. 다른 곳에서도 있을 수 있겠지만 내가 아는 곳은 거기뿐이오. 난 그 버섯이 연금술에 사용할 잠재적인 가치가 있는지 연구하고 싶소. 그래서 당신의 도움이 필요하다오.\n\n자홍버섯을 찾아서 나에게 12개만 가져다주시오. 버섯송이에 가까이 가면 포자에서 독이 발산되니 조심하도록 하시오.\n\n날 위해 이 일을 맡아주시오. 돌아오면 내 당신을 격려하는 의미에서 유명한 나의 복원의 비약을 한 꾸러미 주겠소이다!", progress = "연금술에 쓸 자홍버섯은 가져왔소? 버섯이 없으면 보상도 없소이다!", completion = "수고했소. 다시 한번 자신의 가치를 증명했군! 이 버섯 연구는 틀림없이 흥미로울 것이오.\n\n자, 이제 약속대로 효과가 아주 좋은 비약을 하나 만들어 줄 테니 써보도록 하시오.\n\n당신이 실력 있는 연금술사라면 앞으로 또 거래를 하게 되겠지. 어쨌든 도와줘서 고마웠소!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n복원의 물약"},
[18] = {title = "도둑 떼 소탕", objective = "노스샤이어 수도원 외부에 있는 부관 윌렘에게 붉은 삼베 복면 12개를 가져가야 합니다.", description = "최근에 노스샤이어 근방에 새로운 도둑 떼가 나타났습니다. 스스로 데피아즈단이라 칭하는 이 도둑 떼들은 주로 동쪽 다리 건너편에서 목격되고 있습니다.\n\n놈들이 무슨 짓을 하고 다니는지 정확히 파악되지는 않지만 분명 좋지 않은 일일 겁니다! 놈들이 쓰고 다니는 복면을 가져오시면 그 보상으로 무기를 드리도록 하겠습니다.", progress = "도적 떼의 복면을 모두 모았습니까?", completion = "복면을 모아 오셨군요. 스톰윈드 군대를 대신해 진심으로 감사드립니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n민병대 단검민병대 망치민병대 쇼트소드민병대 전투해머민병대 육척봉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[19] = {title = "타릴준", objective = "붉은마루 산맥에 있는 치안대장 매리스에게 타릴준을 처치한 증거로 타릴준의 머리카락을 가져가야 합니다.", description = "검은바위부족 길잡이와 검은바위부족 보초병들이 이곳과 돌망루 요새 사이에 매복하고 있네. 길잡이들의 우두머리는 타릴준이라는 오크인데 우린 이 오크를 처치하려고 하네. 그의 머리카락을 내게 가져오게나!", progress = "검은바위부족 오크들의 공격이 아직도 거세다네. 타릴준은 제거했나?", completion = "타릴준은 지독하고 교활한 오크였네. 잘했군, 분명 쉬운 상대가 아니었을 텐데. 자, 자네의 공로에 대한 보상일세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n화염으로 단련된 버클러오크 분쇄기\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[20] = {title = "검은바위부족의 위협", objective = "레이크샤이어에 있는 치안대장 매리스에게 마모된 도끼 10개를 가져가야 합니다.", description = "불타는 평원에서 온 검은바위부족 오크들이 북쪽의 돌망루 요새를 장악했네. 오크들은 그곳을 본거지로 삼아 레이크샤이어의 북쪽 지역을 약탈하고 마을의 주민들을 우리 안의 가축처럼 가두어 놓고 있다네.\n\n레이크샤이어에서 오크의 위협을 제거할 수 있게 도와 주게나. 검은바위부족 오크들을 처치하고 내게 그들의 마모된 도끼 10개를 증거로 가져 오게.\n\n돌망루 요새를 장악한 오크뿐만 아니라 붉은마루 산맥 남동쪽의 고립 지대에서도 오크들의 위협에 대한 보고가 들어오고 있네. 그곳에서도 검은바위부족을 발견하면 처치해 주게나.", progress = "오크들을 처치하고 왔는가? 그렇다면 증거를 보여 주게.", completion = "이로써 걱정해야 할 오크의 수가 상당히 줄어든 셈이군, 고맙네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[21] = {title = "메아리 광산 전투", objective = "코볼트 일꾼 12마리를 처치한 다음 노스샤이어 수도원에 있는 치안대장 맥브라이드에게 돌아가야 합니다.", description = "일전에 자네가 조사한 결과를 볼 때 메아리 광산에 있는 코볼트 녀석들을 없애야 할 거 같네. 자네가 광산으로 돌아가서 코볼트를 제거하는 일을 도와주게나.\n\n지체할 시간이 없네. 저런 상태로 코볼트들이 방치되면 방치될수록 녀석들이 노스샤이어 깊숙이 터전을 마련하게 될 테니 말이야.", progress = "힘든 임무인 줄은 알고 있지만 노스샤이어의 안전을 위해서는 불가피한 일일세. 그래, 보고할 준비는 됐나?", completion = "다시 한번 자네에게 경의를 표하네. 또한 스톰윈드 군대를 대신해 감사를 표하는 바이네. 아직 광산에 코볼트들이 남아있겠지만 이제 다른 병사들을 보내도록 하겠네. 그리고 자네에게는 다른 임무를 맡기고자 하네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n여행자용 허리띠여행자용 장화여행자용 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[22] = {title = "뿔엄니멧돼지 간 파이", objective = "뿔엄니멧돼지 간 파이를 만들 수 있도록 살마 살딘에게 뿔엄니멧돼지 간 8개를 가져가야 합니다.", description = "양파 껍질은 다 벗겼고, 마늘은 잘게 저몄고, 로즈메리도 빻았고, 빵은 다 구워졌고, 딜 이파리도 잘라 두었고, 고기 국물은 끓고 있으니, 이제 뿔엄니멧돼지 간 8개만 있으면 제 자랑거리인 고기 파이를 만들 수 있답니다!", progress = "뿔엄니멧돼지 간 8개만 있으면 제 자랑거리인 고기 파이를 만들 수 있어요.", completion = "이거면 완벽해요! 정말 고맙습니다. 오늘 밤 제 남편인 살딘과 푸짐한 만찬을 즐길 수 있겠네요. 수고해 주신 것에 대한 답례로 약소하지만 이걸 드릴게요. 설마 제가 당신처럼 훌륭한 &lt;class&gt;님께 식사도 대접하지 않을 거라 생각하신 건 아니시겠죠?", rewards = "다음과 같은 것들을 받습니다:\n\n뿔엄니멧돼지 간 파이조리법: 뿔엄니멧돼지 간 파이"},
[23] = {title = "우르산고우스의 앞발", objective = "우르산고우스의 앞발을 잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다.", description = "강력한 곰 우르산고우스의 앞발은 이번 잿빛 골짜기 사냥을 성공적으로 마친 당신에게 훌륭한 전리품이 될 것입니다. 앞발에는 작은 초승달 문장이 있으나 그 의미를 아는 자는 없는 것 같습니다.\n\n이 앞발을 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가서 당신이 우르산고우스를 이겼다는 것을 증명해 보이십시오.", progress = "오, <name>. 그렇지 않아도 막 당신 생각을 하던 참이었는데! 사냥은 어떻게 되어가고 있습니까?", completion = "아, 우르산고우스의 앞발이로군요! &lt;class&gt;|1이여;여;, 정말 대단한 실력입니다. 이놈은 꽤 많은 생명을 앗아간 것으로 유명합니다. 앞발에 새겨진 이 초승달 문양은 잿빛 골짜기를 돌아다니는 나이트 엘프가 비밀리에 이놈을 길들였다는 증거가 틀림없습니다. 우르산고우스는 이 부근에서 가장 무시무시한 곰이었는데 그것도 이제 과거의 이야기가 되었군요. 그런 놈을 이겼다는 것은 당신의 결의를 명백하게 보여주는 일입니다.\n\n선조께서 당신을 자랑스럽게 여길 것입니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[24] = {title = "샤둠브라의 머리", objective = "샤둠브라의 머리를 잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다.", description = "한때 날쌘 몸놀림으로 숲을 누볐던 샤둠브라가 지금 당신에게 패해 생명이 빠져나간 상태로 누워 있습니다. 이 죽은 흑호의 머리는 이번 잿빛 골짜기 사냥 대회에서 승리를 거둔 당신에게 멋진 전리품이 될 것입니다. 토막나무 주둔지에 있는 세나니 썬더하트에게 보여주면 이번 잿빛 골짜기 사냥에 성공했다는 것을 인정할 것입니다.", progress = "<name>, 다시 만나서 반갑습니다! 공훈의 증거를 보여 주려고 왔습니까?", completion = "잿빛 골짜기 사냥 대회에서 승리한 것을 축하합니다! 정말 잘하셨습니다. 이 샤둠브라의 머리 정도면 치열한 싸움에 걸맞은 충분한 전리품이 되겠군요.\n\n이곳 주둔지에서 샤둠브라의 포악성은 널리 알려진 사실이었습니다. 그 흑호 때문에 조람 해안으로 걸어서 여행하는 일은 꿈도 꾸지 못할 위험천만한 모험이었지요. 이제 당신 덕분에 안심입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[25] = {title = "돌발톱 산맥의 정체 해결", objective = "돌발톱 토굴길에서 동쪽으로, 그리고 토막나무 주둔지에서 남서쪽으로 있는 미스트랄 호수에서 타락한 물의 정령 12마리를 처치해야 합니다.\n\n미스트랄 호수에 있는 전망대로 가서 얼라이언스 전초기지를 살펴봐야 합니다.\n\n그런 다음 잿빛 골짜기 토막나무 주둔지에 있는 마스토크 윌리히스에게 돌아가십시오.", description = "무슨 일이라도 시작해보고 싶은 모양이군?! 그렇다면, 나와 함께 돌발톱 토굴길 근처에서 벌어지고 있는 일에 대한 대책을 세워 보세...\n\n현재 잿빛 골짜기와 돌발톱 산맥을 오가는 운송 행렬이 정체되어 있네. 호수에서 사는 정령들이 지나가는 이들을 무차별적으로 공격하기 때문이지. 흠, 그냥 물의 정령들을 망치로 내려치고 오는 일은 누구나 할 수 있는 일이지... 거기다 미스트랄 호수에 있는 전망대까지 정찰하고 온다면 금상첨화일 게야. 거기서는 얼라이언스 전초기지가 아주 또렷하게 보이거든.\n\n어때? 자네도 호드에 뭔가 도움이 될 만한 일을 하고 싶지 않나?", progress = nil, completion = "그래, 누군가 불모의 땅을 휩쓸고 다니는 먼지 악령처럼 그 호수를 헤집어 놓았다는 통쾌한 소식은 들었지. 자네의 보고를 들어보니 얼라이언스 놈들의 동태를 살펴볼 관측소를 그곳에 세울 수 있을 것도 같아. 적의 눈에 띄지 않게 아주 나지막하게 만들 수 있다면 말이지만...\n\n이 정보는 우리 호드에 정말 유용한 것이야. 자네의 고생은 헛수고가 아닐세. 게다가 이제 이곳과 돌발톱 산맥 사이를 오가는 운송 행렬이 한결 수월히 다닐 수도 있고 말일세. 자, 이걸 받게나! 땀흘린 대가일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[26] = {title = "귀중한 교훈", objective = "달숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈와 대화하십시오.", description = "<name>, 나는 지금까지 아주 기쁜 마음으로 그대가 발전하는 모습을 지켜봐 왔소. 확실히 그대는 소중한 자연의 수호자로 성장해 가고 있소.\n\n우리는 세나리우스의 축복으로 여러 가지 동물의 형상을 취할 수 있게 되었지. 이제 그중 하나에 대해 자세히 배워야 할 때가 되었소. 바로 수중 세계를 자유자재로 제어할 수 있는 상이오. 이것을 배우려면 달숲에 있는 나이트헤이븐으로 가서, 세나리온 의회의 일원인 덴드리트 스타블레이즈와 얘기해 보시오. 그가 자세히 가르쳐 줄 거요.", progress = nil, completion = "젊은 &lt;class&gt;여, 어서 오십시오. 그대는 이제 바다표범으로 변신하는 법을 배울 때가 됐군요. 이걸 배우면 물속에서 무한정 자유롭게 움직일 수 있습니다. 곧 그대도 알게 될 겁니다. 이 기술은 유용한 도구이자 하나의 축복이라는 것을... 하지만 완전히 통달하기 위해서는 많은 노력이 필요하죠.\n\n반드시 두 가지 시험을 통과해야 하는데, 첫 번째 시험은 물속에서 압력을 견디며, 임무를 수행할 능력이 있는지 가늠하기 위한 것이고, 두 번째 시험은 이 능력의 본질 그 자체를 이해하고자 하는 그대의 결의를 알아보기 위한 것입니다.\n\n시험을 치를 때가 되었으니 준비와 함께 각오를 단단히 하는 게 좋을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[27] = {title = "꼭 배워야 할 교훈", objective = "달숲의 나이트헤이븐에 있는 덴드리트 스타블레이즈와 대화해야 합니다.", description = "나는 지금까지 죽 그대가 발전하는 모습을 아주 기쁜 마음으로 지켜봐 왔네. 확실히 그대는 소중한 자연의 수호자로 성장해 가고 있군.\n\n이제 세나리우스의 축복으로 우리가 그 형상을 취할 수 있게 된 여러 가지 동물의 상 중 하나에 대해 더 자세히 배워야 할 때가 되었네. 바로 수중 형상을 통달하는 것이지. 이를 배우려면 달숲에 있는 나이트헤이븐으로 가서 그곳에 있는 세나리온 의회의 일원인 덴드리트 스타블레이즈와 얘기해 보시게. 그가 더 자세히 가르쳐 줄 걸세.", progress = nil, completion = "어서 오십시오, 젊은 &lt;class&gt;여. 이제는 수중 형상을 취하는 법을 배울 때가 됐군요. 이 형상을 취하면 물 속에서 끝 없이 자유롭게 움직일 수 있답니다. 이 상이 유용한 도구이자 하나의 축복이라는 것을 알게 될 것입니다... 하지만 완전히 통달하기 위해서는 많은 노력이 필요한 상이지요.\n\n그대는 두 가지 시험을 맞아 이를 극복해야 하는데, 첫 번째 시험은 물 속에서 압력을 견디며 임무를 수행할 수 있는 능력을 가늠하기 위한 것이고, 두 번째 시험은 그 형상 자체의 여러 가지 상을 이해하고자 하는 그대의 결의를 알아보기 위한 것이랍니다.\n\n이제 시험을 치를 때가 되었으니 각오 하시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[28] = {title = "엘룬아라 호수의 시험", objective = "엘룬아라 호수에서 제단 구슬을 찾은 후, 달의 숲 북서부에 있는 레물로스의 제단으로 가져가야 합니다. 그곳에 이르면 제단 구슬을 사용하십시오.\n\n그런 다음 제단에 있는 타자리와 대화해야 시험이 끝나게 됩니다.", description = "첫 번째 시험으로, 엘룬아라 호수의 깊은 곳을 뒤져 제단 구슬을 찾도록 하십시오. 제단 구슬은 금방 그 효력이 다하니 서둘러서 레물로스의 제단으로 가져가야 합니다. 제단에서 구슬을 사용한 다음, 그곳에 있는 타자리와 얘기를 나누십시오. 그녀는 달의 숲에서 가장 신임받는 관리인 중 한 명입니다.\n\n이번 임무는 제한된 시간 내에 완료해야 하는데다, 구슬을 찾는 다른 드루이드들과 경쟁을 벌이게 될 수도 있으니 각오를 단단히 하셔야 할 겁니다. 그대의 정신과 신체의 민첩성이 바로 성공의 열쇠가 될 겁니다.\n\n그럼, 행운을 빌겠습니다, <name>.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[29] = {title = "엘룬아라 호수의 시험", objective = "엘룬아라 호수에서 제단 구슬을 찾은 후 달숲 북서부에 있는 레물로스의 제단으로 가져가야 합니다. 그곳에 이르면 제단 구슬을 사용하십시오.\n\n그런 다음 제단에 있는 타자리와 대화를 하면 이 시험을 통과하게 됩니다.", description = "첫 번째 시험으로, 엘룬아라 호수의 깊은 곳을 뒤져 제단 구슬을 찾도록 하십시오. 제단 구슬은 그 효력이 금방 다하니 서둘러서 레물로스의 제단으로 가져가십시오. 제단에서 구슬을 사용한 다음, 그곳에 있는 타자리와 얘기를 해보십시오. 달숲에서 가장 신뢰받는 관리인 중 한 명이죠.\n\n이번 임무는 제한된 시간 내에 완료해야 하는데다가, 구슬을 찾는 다른 드루이드들과 경쟁을 벌이게 될 수도 있으니, 각오를 단단히 하시기 바랍니다. 당신의 정신과 신체의 민첩성이 바로 성공의 열쇠가 될 겁니다.\n\n그럼 행운을 빌겠습니다, <name>.", progress = nil, completion = "아, 또 한 명의 &lt;class&gt;가 엘룬아라 호수의 시험을 성공적으로 마쳤군요! 수고하셨습니다, 젊은 친구여. 정말 잘했어요.\n\n아까도 얘기했듯이 제 이름은 타자리입니다. 달숲에서도, 특히 이 제단의 관리인으로 일하는 것은 제 임무이자 특권이지요. 수호자 레물로스는 세나리온 의회가 자연의 균형을 보존하도록 이끌고 있고, 이 제단은 바로 그의 업적에 대한 한없는 감사의 표시랍니다. 그대는 여기서 구슬을 사용함으로써, 세나리온 의회 내에서 이 장소가 갖는 중요성을 인정한 것이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[30] = {title = "바다표범의 시험", objective = "민첩성의 바다 펜던트 반쪽과 인내의 바다 펜던트 반쪽을 찾아야 합니다. 달숲 주민들과 얘기하여 이 물건들이 있을 만한 곳에 대한 단서를 얻으십시오.\n\n두 개의 반쪽을 찾아 바다표범의 펜던트를 만들어야 합니다. 반드시, 레물로스의 제단 근처에서만 하나로 합칠 수 있습니다.\n\n완성된 펜던트를 달숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈에게 가져가십시오.", description = "이제 두 번째 시험으로 두 개로 쪼개진 바다표범의 펜던트를 찾아야 합니다. 하나는 물에서 미끄러지듯 움직이는 바다표범의 민첩성을, 다른 하나는 엄청난 지구력과 인내로부터 힘을 끌어 모으죠. 우리 드루이드는 이 두 가지 힘을 모아 바다표범으로 변신합니다.\n\n펜던트 조각들이 있는 곳을 알아 보려면 달숲 주민들에게 물어보세요. 두 조각을 이곳으로 가져와서 하나로 합친 다음, 완성된 바다표범의 펜던트를 덴드리트 스타블레이즈에게 가져가도록 하세요.", progress = "<name>, 펜던트는 만들었습니까? 연구해볼 가치가 있는 물건입니다. 두 조각의 위치를 알아내려면 여기 주민들에게 한번 물어보십시오. 그대가 찾는 물건에 관한 정보는 물론 이 불가사의하고 성스러운 숲을 탐험하도록 인도해줄 겁니다.", completion = "&lt;name&gt;, 정말 축하합니다! 바다표범의 시험을 무사히 통과했군요.\n\n그대는 두 펜던트를 구하는 과정에서 물속에서는 민첩성과 인내가 모두 필요하다는 사실을 깨달으셨겠지요. 어느 한쪽이 없으면, 다른 한쪽도 존재할 수 없답니다. 그리고 이는 모두 바다표범의 상을 취하려는 그대의 의지가 없이는 불가능한 일이지요.\n\n자, 제가 한 말을 잘 기억해두십시오. 그리고 바다표범으로 변신할 때면 이 교훈을 믿고 따르시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[31] = {title = "바다표범 변신", objective = "썬더 블러프로 돌아가 투락 룬토템에게 바다표범의 펜던트를 보여 주어야 합니다.", description = "그대는 젊은 드루이드가 바다표범으로 변신하기 위해 배워야 할 교훈을 모두 얻었습니다. 이제 썬더 블러프에 있는 상급 드루이드, 투락 룬토템에게 다시 가보십시오. 그에게 이 펜던트를 보여 주면 그대가 가르침을 받을 준비가 됐다는 걸 믿어 의심치 않을 겁니다. 그에게 물과 하나가 되는 법을 배우면, 그대의 이번 훈련은 끝이 나는 것입니다.\n\n젊은 드루이드여, 안녕히... 훗날을 기약합시다.", progress = "자네가 썬더 블러프로 돌아온다는 소식은 들었네. 바다표범으로 변신하는 법을 가르쳐 주기 전에, 달숲에서 시험을 통과했다는 증거부터 봐야겠어.\n\n바다표범의 펜던트는 가져왔나?", completion = "아주 놀랍군, &lt;name&gt;. 자네가 성장해 가는 것을 보면 선조님께서 매우 기뻐하실 걸세! 그래, 자네는 바다표범으로 변신하는 법을 배울 준비가 됐군. 기꺼이 가르쳐 주지.\n\n그리고 두 가지 시험을 성공적으로 마친 노고를 인정해, 이 물건을 주도록 하겠네. 자연의 수호자이자 균형의 관리자인 자네에게 유용하게 쓰이길 바라네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n바다표범 변신\n\n다음과 같은 것들을 받습니다:\n\n물병자리 허리띠"},
[32] = {title = "실리시드의 전조", objective = "오그리마에 있는 질지빈 드럼로어에게 보고서를 가져가야 합니다.", description = "여기 보고서를 받으시오. 이 보고서는 이런 일에 대해 실제로 잘 아는 사람에게 가져가는 것이 좋겠소.\n\n질지빈 드럼로어라는 트롤 학자를 알고 있는데 아제로스 생태계 고유의 생물들을 연구하며 많은 시간을 보내고 있소. 게다가 역사학에도 조예가 깊다오. 이 보고서를 그에게 전하면 이 위협이 정확히 무엇인지 그리고 그것을 막을 방법이 있는지 알 게 될 테지. 분명 도움을 줄 것이오. 이번 일에는 우리가 만날 수 있는 모든 이의 도움이 필요하오.\n\n내가 마지막으로 들은 소식에 의하면 질지빈은 오그리마의 골목길 2층에 있는 집에 살고 있다고 합디다.", progress = "미안하지만, 난 당신을 잘 모르는데... 하지만 당신은 나에 대해 뭔가 들어 본 것 같군. 그래, 내가 도와줄 일이라도 있소? 내게 뭘 가져온 거요?", completion = "내가 전에 이 보고서에 기록된 것들을 상대한 적 있소. 피즐도저가 이 보고서를 내게 보낸 건 참 현명한 일이었어.\n\n이 생물들은 빠른 속도로 타나리스 사막을 모조리 집어삼키고 말 거요. 우리가 맞서게 될 가장 큰 위협이 될 것이 분명하지. 이 생물들의 이름을 잘 기억해 두시오. 실리시드... 여기에 적힌 곤충의 이름은 실리시드라고 하지. 이들은 호드와 얼라이언스 모두에게 가장 큰 위협이 될 존재라오.\n\n우리가 그것을 미리 알 수 있을 만큼 현명하기만 하다면 좋을 것을...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[33] = {title = "변경의 늑대들", objective = "노스샤이어 수도원 바깥에 있는 이건 펠트스키너에게 질긴 늑대 고기 8덩이를 가져가야 합니다.", description = "저는 불결한 회색 늑대들을 무척 싫어합니다! 하지만 그 맛있는 늑대 스테이크가 회색 늑대들을 잡아서 만드는 것이라니 나원... 그래서 말인데요. 질긴 늑대 고기를 구해다 주시겠습니까? 그럼 사냥에 도움이 될만한 것과 바꿔 드리도록 하죠.\n\n질긴 늑대 고기는 노스샤이어의 변두리 지역을 돌아다니는 회색 늑대와 새끼 늑대를 사냥해서 얻을 수 있을 겁니다.", progress = "으, 배에서 꼬르륵거리며 요동치는 소리가 들리네요. 질긴 늑대 고기는 가져왔나요?", completion = "오, 수고가 많았네요! 어서 늑대 고기를 요리해야겠군...\n\n자, 이 중에서 원하는 것을 하나 골라가세요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n부드러운 모피 신발늑대가죽 팔보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[34] = {title = "불청객", objective = "레이크샤이어의 마티 제인로즈가 서리먹보를 처치해 달라고 부탁했습니다. 마티 제인로즈에게 서리먹보의 어금니를 증거로 가져가야 합니다.", description = "제 정원이 또 짓밟히고 엉망이 되어버려서 속상해 죽겠어요. 범인이 누군지는 알고 있어요. 매리스 치안대장님이 서리먹보라고 이름 붙인 버림받은 멧돼지가 범인이라고 하셨거든요.\n\n이제는 내년까지 나팔수선화를 다시 심을 수도 없단 말이에요. 정말 속상해요! 그 골칫거리 멧돼지 한 마리 때문에 완전히 망했어요. 제발 그 골칫거리를 없애 주세요! 녀석의 어금니를 가져오시면 기꺼이 보답해 드릴게요. 그 멧돼지는 주로 레이크샤이어의 남서쪽 들판에서 어슬렁거리다가 간혹 이곳으로 와서 내 정원을 망가뜨린답니다.", progress = "아직 서리먹보가 살아 있나요? 아니면 당신이 레이크샤이어의 골칫거리를 영원히 없애 버린 건가요?", completion = "드디어 그 짐승이 영원히 잠들었군요! 정말 고맙습니다. 얼마나 큰 도움이 되었는지 모르실 거예요. 아, 올해는 정원에 꽃들이 만개할 거예요!", rewards = "다음과 같은 것들을 받습니다:\n\n붉은 베고니아 꽃다발"},
[35] = {title = "소문의 진상", objective = "치안대장 더그한이 경비병 토마스와 대화해 달라고 부탁했습니다.", description = "멀록에 대한 소문의 진상을 확인하려면 엘윈 숲 동쪽 다리에 있는 경비병 토마스와 이야기를 나눠 보시오. 그는 지난 몇 주간 그 근방에서 근무했었으니까 그 지역의 상황을 잘 알고 있을 것이오.\n\n나에게 그의 보고를 전해주시오.", progress = nil, completion = "맞습니다. 멀록들이 엘윈 숲 동쪽의 강가와 그 주변에 정착했습니다. 멀록들이 왜 이곳에 왔는진 모르겠지만 성질이 난폭하고 어느 정도 지능이 있다는 것은 확실합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[36] = {title = "서부정통 스튜", objective = "베르나 펄브로우가 살마 살딘에게 서부정통 스튜 조리법을 전해 달라고 부탁했습니다.", description = "전 농장을 떠나게 되리라고는 꿈에도 생각지 못했답니다. 하지만, 밭에 작물 도둑들이 들끓으니 이제 이곳은 너무 위험해서 살 수가 없네요. 제 남편인 펄브로우가 마차를 수리하면 바로 떠날 거예요.\n\n제 부탁을 하나만 들어주시겠어요? 제가 서부정통 스튜의 조리법을 적어 드릴 테니 저쪽 농장에 있는 살마 살딘에게 가져다주세요. 살딘 농장은 길이 갈라지는 곳 바로 너머에 있어요.", progress = "하나둘씩 여길 떠나더니 이제 베르나가 떠난다고 하더군요. 아, 베르나가 무척 보고 싶을 거예요. 혹시 이곳으로 오는 길에 그녀를 만난 건 아니겠죠?", completion = "베르나는 정말 한결같은 여자예요. 베르나가 떠나면 서부 몰락지대의 모든 사람들이 베르나를 그리워할 거예요. 사실 우리끼리 하는 말이지만 베르나는 성격이 천상 도시 여자라 스톰윈드에서도 잘 지낼 수 있을 거예요. 자, 이제 수다는 그만 떨고 서부정통 스튜를 만들어야겠네요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[37] = {title = "사라진 경비병 수색", objective = "경비병 토마스가 강 북쪽으로 가서 사라진 두 경비병, 롤프와 말라카이를 찾아달라고 부탁했습니다.", description = "며칠 전 강 주변 정찰을 위해 롤프와 말라카이를 파견했는데 아직 돌아오질 않았습니다. 이들에게 무슨 일이 일어났는지를 알아야 보고를 할 수 있는데 말입니다.\n\n강을 따라 북쪽으로 가서 그 두 경비병을 찾아봐 주시겠습니까? 하다못해 시체라도 말입니다.", progress = nil, completion = "시체의 훼손 정도가 심해 형체를 알아보기 어렵지만 근처에 '보병 말라카이 스톤'이라고 새겨진 목걸이가 떨어져 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[38] = {title = "서부정통 스튜 조리", objective = "살마 살딘이 식인독수리 고기 3개, 뿔엄니멧돼지 주둥이 3개, 멀록 눈알 3개, 그리고 오크라 3개를 구해 달라고 부탁했습니다.", description = "서부정통 스튜 만드는데 재료가 좀 필요한데 좀 도와주세요! \n\n 식인독수리 고기 3개 \n 뿔엄니멧돼지 주둥이 3개 \n 멀록 눈알 3개 \n 오크라 3개를 가져다주세요.", progress = "스튜를 만드는 데 \n\n 식인독수리 고기 3개 \n 뿔엄니멧돼지 주둥이 3개 \n 멀록 눈알 3개 \n 오크라 3개가 필요해요.", completion = "이 오크라 덕분에 제대로 된 진한 국물을 만들 수 있겠네요! 이제 식인독수리 고기와 멀록 눈알, 그리고 맛있는 뿔엄니멧돼지 주둥이만 넣으면... 자, 다 됐어요. 도와 주셨으니 따뜻한 서부정통 스튜를 첫 번째로 맛볼 수 있는 영광을 드리지요!", rewards = "다음과 같은 것들을 받습니다:\n\n서부정통 스튜조리법: 서부정통 스튜살마의 오븐 장갑날카로운 주방용 나이프"},
[39] = {title = "토마스의 보고 전달", objective = "골드샤이어에 있는 치안대장 더그한에게 보고해야 합니다.", description = "더그한 치안대장님께 말라카이와 롤프의 죽음을 말씀드려 주십시오. 그리고 엘윈 숲 동쪽에 있는 멀록들을 견제하기엔 현재 병력만으로는 무리라고 보고해 주시기 바랍니다.\n\n이쪽에 충분한 병력을 배치할 만큼 상황이 여의치 않다는 것은 알지만 더그한님께서 이 지역에 희망이 되어 줄 누군가를 보내주시리라 믿습니다.", progress = nil, completion = "흠, 이거 좋지 않은 소식인 걸. 아직 우리의 방어선이 미약하게 펼쳐져 있는데다가, 멀록에게 롤프와 말라카이까지 희생되었으니 우리를 더 어려운 상황에 처하게 하는군.\n\n이 모든 상황들이 개선되지 못한다면 이번 주말에 골드샤이어에서 전투를 치러야할 것이오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[40] = {title = "멀록의 위협", objective = "말더듬이 레미가 골드샤이어에 있는 치안대장 더그한과 대화해 달라고 부탁했습니다.", description = "에... 엘윈 숲에 위험이 닥쳐오고 있어요! 멀록들이 엘윈 숲 동쪽에 있는 가... 강가를 거슬러 올라가며 무... 물고기를 겁주고 선량한 사람들을 해... 해치고 있어요!\n\n제가 더... 더그한 치안대장님께 분명히 말씀드렸지만 그분은 노... 놀과 도둑을 대수롭지 않게 여... 여기고 계세요. \n\n부디 더... 더그한님께 동쪽으로 병력을 더 보내달라고 서... 설득해 주세요!", progress = nil, completion = "그렇소, 그 문제에 관해 레미와 이야기한 적이 있었지. 레미는 장사 수완은 뛰어난 사람이지만 동쪽에 있는 멀록에 대한 신고 내용 모두 별로 중요치 않았소.\n\n어쨌든 당신이 한 말은 명심해 두겠지만 멀록의 위협에 대한 군사 보고서 없이는 동쪽으로 군대를 더 보낼 수 없소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[45] = {title = "롤프의 생사 확인", objective = "멀록 마을에서 롤프의 생사를 확인해야 합니다.", description = "이 지역을 자세히 조사해 보니 물갈퀴 모양의 발자국이 돌무덤 호수를 따라 동쪽으로 이어져 있는 것을 볼 수 있었습니다. 동쪽으로 멀리 떨어진 곳에는 어렴풋이 멀록 마을이 보입니다.\n\n아마도 롤프는 저곳에서 최후를 맞은 것 같습니다.", progress = nil, completion = "시체의 목에 '보병 롤프 하트포드'라고 새겨진 목걸이가 걸려 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[46] = {title = "멀록 현상금", objective = "엘윈 숲 다리 동쪽에 있는 경비병 토마스에게 찢어진 멀록 지느러미 8개를 가져가야 합니다.", description = "스톰윈드 군대에서는 엘윈 숲에 있는 멀록 잠복꾼과 멀록 채집꾼들에게 현상금을 걸었습니다. 멀록들을 해치우고 찢어진 멀록 지느러미를 나에게 가져오면 스톰윈드 군대에서 충분한 보상을 해줄 것입니다.\n\n멀록 마을은 두 군데가 있는데, 하나는 여기서 북쪽에 있는 돌무덤 호수에 있고, 나머지 하나는 남쪽에 시냇물이 갈라지는 곳에서 볼 수 있을 겁니다.", progress = "사냥은 잘 되어 갑니까?", completion = "지느러미를 가지고 왔습니까? 대단하군요! 더그한 치안대장님께서 엘윈 숲 동부 지역의 멀록들 때문에 걱정이 이만저만이 아니신데 이제 사태가 수습되어 간다고 보고해야겠습니다.\n\n한 몫 단단히 해냈군요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n장총검튼튼한 강철 곤봉낡고 닳은 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[47] = {title = "금가루 거래", objective = "골드샤이어에 있는 말더듬이 레미에게 금가루 10개를 가져가야 합니다. 금가루는 엘윈 숲에 있는 코볼트로부터 얻을 수 있습니다.", description = "이 지역의 코... 코볼트들은 가끔 금가루를 가... 가지고 다녀요. 제겐 정말 유용한 것들인데 말이죠. 제게 금가루를 잔뜩 가져오면 마을에서 가... 가장 높은 값을 쳐 드리겠습니다!\n\n코... 코볼트는 남쪽에 개... 개미굴 광산이나 부... 북동쪽에 서...석영 광산 근처에서 차... 찾을 수 있습니다.", progress = "자... 잠깐! 그... 금가루는 가지고 오셨나요?", completion = "고맙습니다. 여기 다... 당신 몫이에요. 그리고 이건 내 거... 거래 고객이라는 지... 징표인데, 언젠가 유... 유용하게 사용할 수 있을 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n구슬 주머니"},
[48] = {title = "달콤한 황색 맥주", objective = "그림부즈 썬더브루에게 신성한 샘물을 가져가야 합니다.", description = "남쪽 땅 그곳을 휘감는 덩굴 \n그 아래 깊은 곳에 흐르는 샘물 \n빛의 성스러운 딸을 닮은 그 순수 \n내게로 가져다주오 신성한 샘물을", progress = "딸꾹! 호호! 아까 그 노래를 다시 듣고 싶다고? 어렵지 않지. \n\n남쪽 땅 그곳을 휘감는 덩굴 \n그 아래 깊은 곳에 흐르는 샘물 \n빛의 성스러운 딸을 닮은 그 순수 \n내게로 가져다주오 신성한 샘물을", completion = "딸꾹! 허허!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[49] = {title = "달콤한 황색 맥주", objective = "그림부즈 썬더브루에게 보리, 호밀, 옥수수 부대를 가져가야 합니다.", description = "황색은 내 평생 사랑의 색조 \n하늘에 물드는 마지막 황혼을 닮았네 \n내 사랑이 열매 맺도록 가져다주오 \n보리와 호밀 그리고 옥수수 부대를", progress = "앵콜? 좋지!\n\n황색은 내 평생 사랑의 색조 \n하늘에 물드는 마지막 황혼을 닮았네 \n내 사랑이 열매 맺도록 가져다주오 \n보리와 호밀 그리고 옥수수 자루를", completion = "딸꾹! 허허!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[50] = {title = "달콤한 황색 맥주", objective = "그림부즈 썬더브루에게 진은 주괴를 가져가야 합니다.", description = "녹이고 녹여, 섞고 또 섞어 \n아무도 모를 우리만의 비법 \n튼튼한 금속으로 증류기를 만드세 \n진은을 구해 주오, 이 노래를 마칠 수 있도록", progress = "다시 불러 달라고? 물론이지, 친구! \n\n녹이고 녹여, 섞고 또 섞어 \n아무도 모를 우리만의 비법 \n튼튼한 금속으로 증류기를 만드세 \n진은을 구해 주오, 이 노래를 마칠 수 있도록", completion = "딸꾹! 허허!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[51] = {title = "달콤한 황색 맥주", objective = "그림부즈 썬더브루에게 플라타너스 가지 하나를 가져가야 합니다.", description = "아직은 여과 안 된 신선한 증류주 \n경작을 기다리는 농토와 같네 \n숯 한 묶음을 만들어야지 \n이번에 필요한 건 플라타너스 가지 하나", progress = "또 불러 달라고? 친구를 위해라면 뭔들 못하겠나!\n\n아직은 여과 안 된 신선한 증류주 \n경작을 기다리는 농토와 같네 \n숯 한 묶음을 만들어야지 \n이번에 필요한 건 플라타너스 가지 하나", completion = "딸꾹! 허허!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[52] = {title = "변경 방어", objective = "굶주린 늑대 8마리와 새끼곰 5마리를 사냥한 다음 엘윈 숲 동쪽 다리에 있는 경비병 토마스에게 돌아가십시오.", description = "골드샤이어에서 멀어질수록 야생 동물들은 점점 더 난폭해지고 동부 벌목지는 끊임없이 이어지는 늑대와 곰들의 공격으로 골치를 앓고 있습니다!\n\n이곳에서 당신 도움을 좀 받았으면 좋겠습니다.", progress = "곰과 늑대들은 모두 처리했습니까?", completion = "도와줘서 정말 고맙습니다. 틀림없이 숲의 무언가가 야생 동물들을 난폭하게 하고 있는 것 같은데...\n\n그게 뭐든 숲 속에 그대로 머물러 있기를 바랄 뿐입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n하급 치유 물약"},
[53] = {title = "달콤한 황색 맥주", objective = "그림부즈 썬더브루에게 참나무 숯 한 묶음을 가져가야 합니다.", description = "감미로운 액체는 아기 눈물처럼 맑고 \n여러 해가 지나면 깊고 아름다운 황색이 되네 \n하지만 이 술에 흠뻑 취하기 전에 \n참나무 숯으로 맥주통을 만들어야지", progress = "물론, 기꺼이 다시 불러 주지, 친구!\n\n감미로운 액체는 아기 눈물처럼 맑고 \n여러 해가 지나면 깊고 아름다운 황색이 되네 \n하지만 이 술에 흠뻑 취하기 전에 \n참나무 숯으로 맥주통을 만들어야지", completion = "통 속에서 오랜 시간, 숯에 여과되고 \n입술에서 영혼으로 곧바로 스며들지. \n이제 모두 한 잔 하세, 당신과 나를 위해 \n자, 어서 취해 보세, 그림부즈 썬더브루!", rewards = "다음과 같은 것들을 받습니다:\n\n썬더브루의 마개 주머니"},
[54] = {title = "골드샤이어로의 전갈", objective = "골드샤이어에 있는 치안대장 더그한에게 치안대장 맥브라이드의 문서를 가져가야 합니다.", description = "자네는 <class>|1으로서;로서; 노스샤이어의 안전을 위해 애써 왔으니, 이번에는 엘윈 숲 주위의 방어를 맡기도록 하겠네.\n\n이 임무를 맡겠다면 내가 준비한 문서를 골드샤이어의 치안대장 더그한에게 전해 주게나. 남쪽 도로를 따라가다가 방벽을 지나 계속 가다 보면 골드샤이어에 도착할 걸세.", progress = "맥브라이드로부터 소식을 가져왔소? 엘윈 숲에 비하면 노스샤이어는 천국이라고 할 수 있지. 음, 치안대장 맥브라이드가 보고할 일이란 게 무언지 궁금하군.\n\n자, 그의 보고서를 보여 주시오...", completion = "흠, 이 문서에 따르면 당신이 스톰윈드 치안대장의 부관 대리의 자격을 얻었다고 하는군. 축하하오.\n\n그리고 행운을 비오. 엘윈의 안전을 지키는 것은 결코 만만한 일이 아니라오. 대부분의 병사들은 자신들이 누구를 위해 무슨 대의를 위해 일하고 있는지도 모른 채 그저 주어진 임무를 수행하느라 바쁠 뿐이니 말이오!\n\n요즘같이 혼란한 시기에는 정치판이 어떻게 돌아가는지 도통 알 수가 없으니...", rewards = "다음과 같은 것들을 받습니다:\n\n창병 방패"},
[55] = {title = "모벤트 펠", objective = "모벤트 파멸의 불꽃을 사용하여 모벤트 펠을 처치하고 스벤의 야영지에 있는 스벤에게 모벤트 파멸의 불꽃을 돌려줘야 합니다.", description = "모벤트 펠은 까마귀 언덕 묘지가 내려다보이는 동쪽의 언덕 위에 있는 자신의 집에 숨어 있습니다. 이제 이 땅에서 그의 시대는 곧 끝나게 될 겁니다...\n\n모벤트 파멸의 불꽃을 사용하여 그에게 대항하십시오. 불꽃은 그를 보호하고 있는 마법을 무력하게 할 겁니다.\n\n그를 처치하여 우리를 사악한 손길로부터 구해 주시기 바랍니다. 내 복수를 해 주시고 그늘숲의 영웅이 되십시오!", progress = "모벤트 펠이 쓰러졌나요?!", completion = "모벤트 펠이 쓰러졌군요! 흑기사들의 세력은 아직 거대하지만 부질없는 소망으로만 생각했던 일이 드디어 이루어졌습니다.\n\n그야말로 불가능했던 일을 해낸 당신의 업적은 그늘숲의 전설이 되어 영원히 남을 겁니다.\n\n친구여, 평안히 가십시오. 언젠가 운명이 당신을 나에게 이끌겁니다...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n어둠의 순찰대 바지순찰대장의 망토불금속 코이프\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n성화 횃불"},
[56] = {title = "어둠의 순찰대", objective = "다크샤이어의 사령관 알시아 이본로크가 해골 전사 8마리와 해골 마법사 6마리를 처치해 달라고 부탁했습니다.", description = "어둠의 순찰대의 사령관으로서 다크샤이어의 주민을 보호하는 것은 내 본연의 임무요. 스톰윈드에서 이곳에 배치했던 경비병들을 철수했기 때문에 이젠 자체 병력만으로 싸워야 하는 상황이오.\n\n당신의 도움이 절실히 필요하오! 다크샤이어 정남 쪽에 있는 고요의 정원 묘지로 들어가 해골 전사 8마리, 해골 마법사 6마리를 처치해 준다면 어둠의 순찰대에 큰 도움이 될 것이오. 이 언데드 녀석들이 다시는 다크샤이어를 위협하지 못하도록 해야 하오!", progress = nil, completion = "훌륭하오. 다크샤이어 주민들을 위해 큰일을 해 주었으니 그에 걸맞은 보상을 하도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[57] = {title = "어둠의 순찰대", objective = "다크샤이어의 사령관 알시아 이본로크가 해골 악령 15마리와 해골 병사 15마리를 처치해 달라고 부탁했습니다.", description = "숲에 언데드가 출몰한다는 신고가 끊이지 않고 있소! 자신 있다면 까마귀 언덕 묘지로 가서 저 지독한 해골 악령과 해골 병사를 각각 15마리씩 처치해 주시오. 보고에 따르면 다크샤이어 바로 남쪽의 고요의 정원 묘지와 그 주변에서도 출몰한다고 하오. 이 언데드 녀석들을 그늘숲에서 몰아내야만 하오!", progress = nil, completion = "다크샤이어의 모든 주민이 당신에게 감사하게 생각하고 있소. 당신은 어둠의 순찰대의 훌륭한 친구임을 증명하였소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[58] = {title = "어둠의 순찰대", objective = "다크샤이어의 사령관 알시아 이본로크가 까마귀 언덕 묘지 동쪽에 있는 역병걸린 시체 20마리를 처치해 달라고 부탁했습니다.", description = "까마귀 언덕의 상황은 여전히 나아지지 않고 있소. 마을의 안전을 책임질 순찰대원이 부족한 상황이니 이제 다크샤이어의 안녕은 당신 손에 달려있소. 다시 한번 까마귀 언덕으로 가서 묘지 동쪽에 있는 역병걸린 시체 20마리를 처치해 주시오!", progress = nil, completion = "어둠의 순찰대의 사령관으로서, 다크샤이어 주민을 대표해 당신의 용기와 헌신적인 행동에 감사를 표하오. 당신의 앞길에 빛나는 서광이 비추기를...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n어둠의 순찰대 탄약주머니어둠의 순찰대 화살통어둠의 순찰대 자루\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[59] = {title = "천 갑옷과 가죽 갑옷", objective = "사라 팀버레인에게 스톰윈드 갑옷 문장을 주어야 합니다.", description = "당신의 통찰력과 용기를 위해 내가 당신 갑옷에 붙일 좋은 문장 하나를 주리다. 이걸 동부 벌목지에 있는 사라 팀버레인에게 가져다주면 갑옷 한 벌을 만들어 줄 것이오. 갑옷을 받게 되면 엘윈 숲을 지키는 일에 사용하길 바라오.\n\n동부 벌목지는 동쪽에 있는 경비병 토마스의 보초지를 지나서 있소.", progress = "저는 스톰윈드 군대 병사들에게 천 갑옷과 가죽 갑옷을 제공해 주는 일을 맡고 있어요.\n\n만약 문장을 가지고 계시다면 기꺼이 갑옷을 만들어 드리도록 하죠.", completion = "아, 문장이군요. 고마워요. 가죽 갑옷이나 천 갑옷 중 마음에 드는 것으로 골라 보세요.\n\n용맹하신 &lt;class&gt;님, 행운이 함께하기를. 그리고 이 갑옷이 도움이 되길 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n잘짜여진 로브기운 바지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[60] = {title = "코볼트 양초", objective = "큰 양초 8개를 모아 골드샤이어에 있는 윌리엄 페슬에게 가져가야 합니다.", description = "안녕하십니까. 잠깐 시간 좀 있으신가요?\n\n저희 형제는 스톰윈드에서 연금술 가게를 운영하고 있는데 큰 양초를 모아 그 밀랍을 얻으려고 이곳에 왔습니다. 절 좀 도와주실 수 있습니까?\n\n큰 양초는 코볼트들에게 얻을 수 있는데 듣자하니 이 코볼트들은 엘윈 숲의 광산에 출몰한다고 하더군요. 남쪽의 개미굴 광산과 동쪽의 석영 광산에 말이죠. 이 두 곳 중 한 곳에 가서 양초를 구해다 주시면 보상을 해 드리도록 하겠습니다.", progress = "양초를 다 모으셨습니까?", completion = "코볼트를 사냥하느라 바쁘셨죠? 양초를 모아 주셔서 감사합니다. 그리고 이건 약속했던 보상입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n빛나는 양초"},
[61] = {title = "스톰윈드로의 배달", objective = "스톰윈드 상업 지구에 있는 모건 페슬에게 윌리엄의 뱃짐을 가져가야 합니다.", description = "우리 형 모건이 스톰윈드에서 양초가 배달되기를 기다리고 있는데 제가 거기까지 갈 시간이 없답니다. 제 대신 이 짐을 운반해 주시면 형이 충분히 사례해 드릴 겁니다.\n\n지금까지 모은 양초를 다 포장했으니 이걸 가지고 스톰윈드 상업 지구에 있는 우리 상점인 페슬의 약제상에서 형 모건을 찾으시기 바랍니다.", progress = "오, 동생의 물건을 가지고 오셨다고요? 멋지군요! 오늘은 운이 좋은 날입니다, 하하!", completion = "자, 이건 당신께 드리는 보상입니다. 그리고 여기 있는 동안 물건을 둘러보세요. 분명히 당신 마음에 드는 물약이나 물건이 있을 겁니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n폭탄 로켓올라프 기름사자의 힘 비약\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[62] = {title = "개미굴 광산", objective = "개미굴 광산을 조사하고 골드샤이어에 있는 치안대장 더그한에게 돌아가야 합니다.", description = "노스샤이어에 있는 광산에만 문제가 있는 게 아니오! 엘윈의 개미굴 광산도 코볼트의 소굴이 되어 버렸다는 보고를 받았소.\n\n광산을 정찰하여 보고 내용이 사실인지 확인한 후 내게 돌아오시오. 개미굴 광산은 골드샤이어에서 남쪽 방향, 스톤필드 농장과 맥클루어 포도밭 사이에 있소.", progress = nil, completion = "정말 좋지 않은 소식이군. 이러다간 다음엔 용이라도 튀어나오겠군. 그 광산 주위의 순찰을 강화해야 되겠어. 애써 줘서 고맙소. 조금만 기다려주시오... 내 부탁할 일이 또 있을 것 같소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[63] = {title = "물의 부름", objective = "은빛소나무 숲에서 타락한 하급 물의 현신을 물리치고 영원의 샘 제단 위에 타락한 현신의 팔보호구와 얼마 남지 않은 순수한 물을 함께 올려놓아야 합니다.", description = "공동묘지 서쪽, 은빛소나무 숲의 해변을 따라가다 보면 역병 때문에 황폐해진 제단이 있을 거예요. 그곳 정령들은 이제 우리 종족과 말도 섞지 않는답니다. 타락한 하급 물의 현신을 해치우고 연못을 정화하는 것이 당신의 임무예요.\n\n그 정령에게 얻은 현신의 팔보호구와 브린이 만들어준 물병에 남아 있는 순수한 물을 가져가서 화로 위에 올려놓으세요. 그러면 하급 물의 현신을 소환해 정화할 수 있을 거예요.\n\n임무를 완수하면 그 증거를 가져오세요. 그러면 답례로 토템을 드리죠.", progress = "화로는 아직도 주변의 빛을 반사하고 있으며 가까이 다가가자 불꽃이 살짝 흔들립니다.\n\n언덕 주위에 만연한 타락의 기운도 어느 정도 쇠한 듯하며 화로에는 정화된 물의 현신을 소환하기 위한 의식이 모두 준비된 것 같습니다.", completion = "팔보호구를 화로 위에 얹고 브린이 준 물병에 남아 있는 순수한 물을 불꽃 위에 붓자 물방울이 불꽃과 닿으면서 탁탁 튀는 소리를 냅니다. 이슬렌이 가르쳐준 간단한 주문을 외우기 시작합니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[64] = {title = "두고 온 회중시계", objective = "농부 펄브로우가 서쪽의 호박밭에 있는 그의 농가로 가서 옷장 안에 있는 회중시계를 가져다 달라고 부탁했습니다.", description = "어떻게 이런 일이! 내 아내 베르나가 밭에서 시끄러운 소리가 난다며 나를 깨웠습니다. 그래서 밖에 나가봤더니 밭에 불량배 놈들이 떼지어 있는 겁니다. 아내와 함께 서둘러 도망쳐 나오느라 내 회중시계도 챙기지 못했어요. 그 시계는 우리 결혼식 날 장인 어른께서 결혼 선물로 주신 거란 말입니다. 놈들이 그걸 가져갈 거라고 생각하니 도저히 참을 수가 없군요. 회중시계는 우리 농가의 옷장 속에 두고 나왔어요. 서쪽에 있는 호박밭에 찾아가시면 우리 집을 쉽게 찾을 수 있을 겁니다. 시계를 가져다 준다면 정말 고맙겠습니다!", progress = "내 회중시계를 찾아다 주신다고 하지 않으셨나요?", completion = "오, 내 회중시계! 고맙습니다. 이 친절은 잊지 않겠습니다! \n\n가난한 농부에 불과하고 땅마저 잃긴 했지만 감사의 표시로 이걸 드리고 싶군요.", rewards = "다음과 같은 것들을 받습니다:\n\n갓 구운 빵시원한 우유"},
[65] = {title = "데피아즈단", objective = "그라이언 스타우트맨틀이 레이크샤이어의 와일리와 대화하라고 부탁했습니다.", description = "자칭 데피아즈단이라는 비열한 패거리가 서부 몰락지대에서 선량한 사람들을 내쫓고 있네. 귀관이 이 흉악한 조직에 잠입하여 놈들의 우두머리가 누구이며 어디에 숨어 있는지 알아내 주게. 레이크샤이어의 선술집에 가면 와일리라는 건달이 있는데, 내게 진 빚이 있으니 자네를 도와줄 것일세.\n\n엘윈 숲 동쪽의 붉은마루 산맥에 있는 레이크샤이어로 가서 귀관이 할 수 있는 일을 찾아보도록 하게.", progress = nil, completion = "스타우트맨틀 경이 보냈다고요? 뭐, 그에게 빚이 있긴 하지요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[66] = {title = "스탈반의 전설", objective = "다크샤이어 마을 회관에서 서기관 달트리를 찾아야 합니다.", description = "내 손녀 알리사가 큰 위험에 처해 있다는 끔찍하고 불길한 기운을 느꼈네. 그래서 카드로 점을 쳐 보았더니 죽음이 보였어.\n\n난 오랫동안 어두운 최면 상태에 빠져 있다가 이 끔찍한 수수께끼의 단서를 얻을 수 있었다네. 이름이 떠올랐어, 스탈반이라는 이름이 말이야.\n\n마을 회관에서 서기관을 찾아서 이 스탈반이라는 인물에 대해 좀 더 알아보도록 하게. 우리 모두의 운명이 위태로워.", progress = nil, completion = "아! 에바 부인께서 보내셨군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[67] = {title = "스탈반의 전설", objective = "문브룩 학교로 가서 스탈반에 대한 최신 정보를 다크샤이어에 있는 서기관 달트리에게 전해줘야 합니다.", description = "스탈반이요? 흠, 마을 기록을 한번 찾아보죠.\n\n스탈반. . .스탈반. . .어디 보자, 아! 여기 있군요. 스탈반 미스트맨틀이라는 자에 대한 기록이 있습니다. 여기 마지막으로 기록된 주소는 문브룩 학교로군요. 그런데 이런, 너무 오래된 기록이네요.\n\n제 부탁 하나만 들어주시겠습니까? 혹시 문브룩에 가게 되시거든 이 사람에 대한 새로운 정보를 제게 좀 알려 주세요. 기록을 완전하게 정리하고 싶거든요.", progress = nil, completion = "낡은 트렁크가 삐걱거리며 열립니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[68] = {title = "스탈반의 전설", objective = "다크샤이어에 있는 서기관 달트리에게 먼지 투성이의 부치지 않은 편지를 가져가야 합니다.", description = "낡은 트렁크 안에서 먼지 투성이의 부치지 않은 편지를 발견했습니다.", progress = "아, 당신이군요. 스탈반에 대해 물었던 분이죠? 원하던 정보는 찾으셨나요?", completion = "이거 흥미롭군요. 그러니까 결국 이 자는 한동안 문브룩에 머무른 거였군요. 그런데 편지가 배달되지 않은 게 이상하군요. 그건 그렇고 어서 기록을 최신으로 수정해야겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[69] = {title = "스탈반의 전설", objective = "사자무리 여관으로 가서 스탈반에 대해 아는 사람이 있는지 확인해야 합니다.", description = "아니, 이런! 틀림없이 처음에 이걸 빠뜨렸었나 봅니다. 기록에 의하면 스탈반의 첫 번째 주소 바로 밑에 일부분이 지워진 다른 주소가 있어요. 그는 골드샤이어에 있는 사자무리 여관으로 향하고 있었나 봅니다. 그곳을 한번 조사해 보세요.", progress = nil, completion = "스탈반이라고요? 어디서 많이 들어 본 이름인데..", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[70] = {title = "스탈반의 전설", objective = "상자에서 스탈반의 배달되지 않은 편지를 찾아 스톰윈드의 대운하에 있는 누군가에게 전해줘야 합니다.", description = "아! 스탈반이라는 이름이 이제야 생각나는군요.\n\n오래전 폭풍이 몰아치던 날 밤에 전령이 와서는 하룻밤 묵을 곳을 찾았었지요. 그런데 자정이 거의 다 되었을 때쯤 그 사람이 비명을 지르며 계단을 뛰어 내려왔답니다. 얼굴은 두려움에 하얗게 질려 있었고 말입니다. 그리고는 잠옷을 입은 채 폭우 속으로 사라졌어요.\n\n위층 상자 안에 편지도 그대로 둔 채로 말이에요. 그 뒤로 편지를 찾으러 오지도 않았고. 그 편지들 중 하나는 스탈반이라는 사람이 스톰윈드의 대운하로 보내는 것이었어요. 뭐, 원하신다면 편지를 가져가셔도 됩니다.", progress = "그게 뭐요? 어디 한번 봅시다.", completion = "이걸 여기로 가져오다니 용기가 가상하군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[71] = {title = "토마스에게 보고", objective = "엘윈 숲 동쪽 다리에 있는 경비병 토마스에게 롤프와 말라카이의 목걸이를 가져가야 합니다.", description = "발견한 두 목걸이를 다리에서 근무하고 있는 경비병 토마스에게 가져다주고 부하 경비병들이 살해되었음을 알려야 합니다.", progress = "어서 오십시오, 롤프와 말라카이가 어떻게 됐는지 알아냈습니까?", completion = "두려워하던 일이 실제로 벌어졌군요. 멀록은 절대 무시할 수 없는 골칫거리입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[72] = {title = "스탈반의 전설", objective = "뒤에 있는 짐 꾸러미에서 단서를 찾아봐야 합니다.", description = "내 아버지는 내가 이 일을 맡기 훨씬 전에 토지 관리인이셨소. 아버지는 대학살이 있은 후 그 피비린내 나는 걸 다 치워야 했단 말이오. 하지만 그건 문제가 아니지.\n\n플린트리지 신용조합의 마지막 자금이 바닥나 버렸었지. 이제는 가문의 마지막 재산까지 경매에 내놓아야 할 판이었소. 괘씸한 세금 도둑들 때문이지. 더 알고 싶은 게 있다면 저 뒤에 상자에 들어 있는 쓸모 없는 것들이나 마음껏 살펴보시오. 뭐, 뭔가 알아내게 될지도 모를 일이니...", progress = nil, completion = "상자의 뚜껑을 천천히 밀어 엽니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[74] = {title = "스탈반의 전설", objective = "발견한 찢어진 일지 페이지에 다음 단서가 들어 있습니다.", description = "상자 안에는 케케묵은 가족 유품들, 가족 초상화 하나, 사냥 트로피 몇 개, 낡은 책 몇 권 등 여러 가지 물건이 있습니다. 상자의 맨 아래쪽에 있는 도자기 항아리 밑에서 찢어진 일지 페이지를 발견합니다.", progress = "거기, 자네 뭘 가지고 있는 건가? 난 안 보이는군. 눈이 너무 나빠서 말일세. 그걸 내게 좀 줘 보게.", completion = "글자를 거의 알아볼 수가 없군그래. 하지만 이 필체는 눈이 이렇게 나빠지기 전에 어디선가 본 적이 있는 것 같군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[75] = {title = "스탈반의 전설", objective = "치안대장 해거드가 위층의 상자에서 색 바랜 일지 페이지를 가져와 달라고 부탁했습니다.", description = "내가 이곳으로 왔을 때 위층에 있는 상자 안에 양피지 문서 꾸러미가 있었다네. 처음 도착했을 때 그 문서들을 한번 보긴 했지만 눈이 어두워진 후로는 보려고 한 적이 없지.\n\n이 장님에 가까운 늙은이에겐 힘든 일이니, 직접 위층의 상자에서 스탈반이라는 자에 대해 더 알아보는 데 도움이 될 만한 것이 있나 찾아보게나. 젊은이에게 도움이 될 만한 색 바랜 일지 페이지가 있을 걸세. 그걸 가져오면 내가 할 수 있는 한 도와 주도록 하겠네.", progress = "내가 말한 일지 페이지를 찾았나?", completion = "오! 찾아냈군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[76] = {title = "석영 광산", objective = "석영 광산을 탐색한 후 골드샤이어에 있는 치안대장 더그한에게 보고해야 합니다.", description = "당신 덕분에 개미굴 광산에 코볼트들이 우글거린다는 사실을 확인했으니, 이번에는 좀 더 멀리 있는 석영 광산을 조사해 봐야겠소.\n\n석영 광산을 탐색하여 코볼트가 있는지 확인해 주시오. 석영 광산에 가려면 일단 길을 따라 동쪽으로 가다가 아조라의 탑이 나오면 거기서 북쪽으로 가시오. 그러면 구릉에 있는 광산을 발견할 수 있을 것이오.", progress = nil, completion = "석영 광산에 코볼트들이 있다고? 이런 세상에! 점점 상황이 악화되고 있군!\n\n알려주어 고맙소. 당신이 좋은 소식을 가져오길 바랬는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[77] = {title = "까다로운 임무", objective = "굼벵이 바위굴의 버려진 호드 기지 근처에서 상자에 든 동부내륙지 벌꿀 리플 10병을 회수해야 합니다.", description = "내게 드란 드로퍼스가 찾는 리플의 원래 포장 재료가 있소. 말톤 아버지는 맘에 안 들지만 그에게 줄 리플을 포장하는 걸 도와주겠소. 단 리플을 두 병 더 가져와준다면 말이오. 굼벵이 바위굴 근처의 버려진 호드 기지에 가면 상자가 있는데 그 속에 리플이 들어 있소.\n\n아주 힘든 임무가 될 거요. 폐허에는 지독한 수액괴물들이 들러붙어 있거든. 소문을 듣자 하니 우두머리 수액괴물이 지배한다고 하오. 그거야 어쨌든 리플을 구해오면 포장을 해주리다.", progress = "아마 당신이 우리 야영지에 온 이유는 중요한 리플을 전달하기 위해서겠지.", completion = "아주 잘했소. 리플의 맛이 상하지 않도록 신중하게 일을 처리해줘서 기쁘군. 쓸데없이 흔들고 다니지는 않았나보군.\n\n먼저 이 소중한 물건에 나만의 마술을 부리도록 하지. 아니, 진짜 마법이 아니고, 그냥 여분의 벌꿀 리플 포장지로 속임수를 쓰자는 거지. 바로 이 병들을 세기의 술로 만드는 거요.\n\n위대한 술을 위하여!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[78] = {title = "스탈반의 전설", objective = "선술집주인 스미츠에게 색 바랜 일지 페이지를 가져가야 합니다.", description = "자넬 도와줄 만한 사람을 알고 있네. 내가 스톰윈드 경비병을 지휘하던 시절에 우리는 다크샤이어에 있는 진홍 까마귀 선술집에서 술을 마시곤 했지. 선술집주인 스미츠는 그 지역에서 일어나는 일이라면 모르는 게 없었다네. 그에게 이 일지를 보여주고 뭔가 알고 있는지 물어보게나.", progress = "치안대장 해거드 씨가 보냈다고 했습니까? 진작 그렇게 말했어야지요.\n\n아, 그분은 참 좋은 분이죠. 그런데 이제 곧 완전히 눈이 멀 거라니 불쌍하기도 하지... 어쨌든, 뭔지 한번 봅시다.", completion = "이런! 이 필체는 단번에 알아보고 말고요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79] = {title = "스탈반의 전설", objective = "사령관 알시아 이본로크에게 진흙투성이의 일지 페이지를 가져가야 합니다.", description = "난 지난 몇 년 동안 이 스탈반이라는 인물의 이야기를 추적해 다녔지요. 몇 년 전 귀족들이 학살당했을 당시에도 나는 헤거드 씨와 함께 조사를 나갔답니다. 그때 이 낡은 보고서들을 찾았지만 이 필체가 숲 속의 그 미치광이의 것인 줄은 전혀 몰랐군요. 당신이 찾아낸 증거들이 그의 유죄를 입증한 셈입니다. 이걸 즉시 이본로크 사령관께 가져가 당신이 발견한 사실들을 알려 드리세요.", progress = "물론 좋은 소식이겠지, <class>? 자, 뭘 찾아냈는지 한번 보도록 하지. 그리고 빛의 이름으로, 직접 설명해 주기 바라오. 물론, 설명은 짧게 끝내도록 하시오. 내 주된 임무는 다크샤이어를 지키는 것이니 시간 낭비할 겨를이 없소.", completion = "오, 이런! 당신은 탐정으로서도 손색이 없군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n피투성이의 일지 페이지"},
[80] = {title = "스탈반의 전설", objective = "서기관 달트리에게 피투성이의 일지 페이지를 보여 주어야 합니다.", description = "난 오랫동안 그 스탈반이란 녀석을 주시해 왔소. 만약 이 일지를 녀석이 작성했다면 이로써 녀석의 죄가 분명히 입증되는 것이오.\n\n지금까지 마을 등기부를 관리해 오고 있는 서기관 달트리는 필체 감정 전문가의 수준이라고 할 수 있소. 그에게 이 일지를 보여 주고 이 필체가 등록된 서명의 필체와 일치하는지 확인해 보도록 하시오.", progress = "다시 돌아왔군요. 이번엔 무슨 일이죠?", completion = "그래, 맞아요! 이 보고서의 필체가 등록된 서명의 필체와 일치하는군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[81] = {title = "리플 배달", objective = "오그리마에 있는 드란 드로퍼스에게 술통을 가져가야 합니다.", description = "드란에게 가져갈 리플을 술통에 안전하게 잘 담았는지, 또 그 사람이 부탁했던 병도 몇 개 따로 챙겨 뒀는지 한번 더 확인했소. 드란을 좋아해서 한 일은 아니오. 소중한 리플이 흔들리면 맛이 없어지니까... 감사는 접어 두시오.\n\n자, 오그리마의 고물상에 있는 드란 드로퍼스에게 이 술통을 가져다주시오. 그리고 부탁이니, 내 대신 말톤에게 안부 좀 전해 주시오. 좋은 술을 준비해두었으니 술친구가 생각나면 언제든 주저 말고 찾아오라고 말이오.", progress = "여기에 뭘 사러 온 것도 아니고 배달을 하러 온 것도 아니라면 시간 낭비하지 말고 가시오! 주머니에 리플이라도 있다면 이야기가 또 달라지지만...", completion = "그럼, 이 술통에 뭐가 들어 있는지 한번 보자고!\n\n옳지, 옳지. 모두 제대로 들어 있는 것 같군. 자, 여기 수고비요. 이 술을 선술집에다 팔면 제 값의 다섯 배는 받을 수 있지! 하하핫!\n\n덤으로 가져온 이 동부내륙지 벌꿀 리플은 내 따로 챙겨둬야겠구먼. 특별한 때 따서 샴페인에 섞어 마시면 그만일 거야. 칵테일 이름은... 샴피플이라고 해야겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82] = {title = "맹독의 둥지 조사", objective = "맹독의 둥지에서 센티파르 곤충 기관 5개를 구해 가젯잔에 있는 연금술사 페슬저그에게 가져가야 합니다.", description = "그럼, 그간 들어온 보고에 대해서 얘기해 주겠소. 녀석들이 한때 맹독의 둥지가 있던 물 웅덩이에서 물을 모조리 빨아먹고 있다고 하오. 또... 다른 건 아무것도 아는 게 없소.\n\n그러니... 먼저 녀석들에 대해 좀 더 자세히 파악하는 것이 급선무요! 맹독의 둥지로 가서 그 생물들의 신체 기관을 좀 갖다주시오. 센티파르 기관 5개를 구해 연금술사 페슬저그에게 조사를 부탁하시오. 그 친구라면 분명 녀석들의 정체를 알아낼 수 있을 거요!", progress = "혹시 당신이 그 새로 왔다는 후임측량사 <name> 아닙니까? 지금은 위급 상황입니다! 피즐도저가 말한 곤충 기관은 가져오신 겁니까?", completion = "이거면 되겠어... 즉시 분석을 시작하겠습니다! 지금 말해줄 수 있는 건, 이건 일찍이 이 세계에 나타난 적이 없는 형태의 곤충이라는 겁니다. 알 수 없는 외부의 힘에 의해 불쌍한 곤충들이 조종을 받는 것 같아요.\n\n지금 당장 피즐도저에게 가 보십시오. 위급한 일이 생겨 당신의 도움이 절실히 필요한 모양이니까! 정확히는 모르겠지만, 타나리스 사막에 나타난 바로 그 곤충들 때문인 것 같습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[83] = {title = "붉은 리넨 복면", objective = "동부 벌목지에 있는 사라 팀버레인에게 붉은 리넨 복면 6개를 가져가야 합니다.", description = "노스샤이어의 데피아즈 패거리는 삼베 복면을 쓰지만 엘윈의 데피아즈 패거리는 좋은 리넨 복면을 쓴답니다. 리넨은 질 좋은 빨간 리넨 셔츠의 재료로 쓰이죠.\n\n붉은 리넨 복면을 가져오시면 그걸 사용해서 멋진 걸 만들어 드릴께요.\n\n엘윈 숲 도처에 데피아즈 패거리의 야영지가 있습니다.", progress = "리넨이 떨어져 가고 있어요. 혹시 가지고 있는 것 좀 있으신가요?", completion = "아, 약간 거칠기는 하지만 훌륭한 리넨 복면이네요.\n\n자, 이걸 받으세요!", rewards = "다음과 같은 것들을 받습니다:\n\n붉은색 리넨 셔츠붉은 리넨 장식띠"},
[84] = {title = "빌리에게 돌아가기", objective = "맥클루어 포도밭에 있는 빌리 맥클루어에게 돼지 삼겹살 파이를 가져가야 합니다.", description = "여기 있어요. 이 파이를 빌리에게 가져다주세요. 빌리 그 녀석, 이 파이를 먹고 목이라도 막혀 고생이나 했으면 좋겠네요!", progress = "아... 배고파 죽겠어요! 혹시 제게 줄 파이는 가져오셨나요?", completion = "냠냠, 이 파이 정말 맛있군요!\n\n이제 기억이 다시 돌아오는 것 같아요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[85] = {title = "잃어버린 목걸이", objective = "빌리 맥클루어와 대화하십시오.", description = "얼마 전 목걸이를 잃어 버렸는데, 아무래도 내 생각엔 빌리 맥클루어라는 꼬마가 가져간 것 같아요. 그 꼬마는 주로 동쪽에 있는 맥클루어 포도밭에서 놀곤 한답니다.\n\n내 목걸이를 좀 되찾아 주세요. 제발 이 나이 든 과부의 소원을 들어주세요.", progress = nil, completion = "뭘 잃어버리셨다고요? 아녜요, 전 목걸이를 훔친 적 없어요. 전 도둑이 아니란 말이어요!\n\n그렇지만 누가 훔쳤는지는 알고 있어요. &lt;씩 웃으며&gt; 근데 배가 너무 고파서 기억이 안 나네요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[86] = {title = "빌리를 위한 파이", objective = "스톤필드 농장에 있는 보모 버니스 스톤필드에게 멧돼지 고기 4개를 가져가야 합니다.", description = "파이를 하나 가져다주시면 누가 목걸이를 가지고 있는지 알려 드릴 수 있을 거 같은데... 알고 계신지 모르겠지만 저쪽 농장에 있는 버니스 아줌마가 기막힌 돼지 삼겹살 파이를 만들거든요.\n\n우리 농장 주위에 돌아다니는 멧돼지를 잡아서 멧돼지 고기를 몇 개 가져다주시고 파이가 왜 필요한지 얘기하시면 분명히 하나 만들어 주실 거예요.", progress = "내 목걸이를 훔쳐 간 녀석에게 먹을 것까지 해 줘야 하다니 정말 말도 안 되는 일이군요! 그래도 목걸이를 되찾기 위해서라면 어쩔 수 없네요.\n\n멧돼지 고기는 가져오셨나요?", completion = "이 야생 멧돼지 고기는 좀 질기지만 충분히 구우면 맛있는 파이가 된답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[87] = {title = "황금니 코볼트", objective = "버니스의 목걸이를 스톤필드 농장에 있는 보모 버니스 스톤필드에게 가져가야 합니다.", description = "개미굴 광산 근처에서 놀다가 아줌마의 목걸이를 떨어뜨린 것 같아요. 아...아니, 그러니까 아줌마의 목걸이를 봤어요. 목걸이가 왜 거기 있는지는 묻지 마세요. 제가 가져간 게 아니에요!\n\n어쨌든 마지막으로 몸집이 큰 황금니 코볼트가 목걸이를 주워서 광산 안으로 도망치는 걸 봤어요. 그 코볼트를 찾으면 목걸이도 찾을 수 있을 거예요. 진짜예요, 맹세할게요!", progress = "어서 오세요, 내 목걸이를 찾았나요?", completion = "오, 목걸이를 찾았군요! 고맙습니다, 정말 고마워요!\n\n자, 이걸 받으세요. 이건 죽은 남편의 것인데 남편은 항상 이게 행운을 가져온다고 말했었답니다. 마지막 전투에도 이 장갑만 잊지 않고 가져갔더라면! *훌쩍*", rewards = "다음과 같은 것들을 받습니다:\n\n사자무늬 장갑"},
[88] = {title = "공주를 없애라!", objective = "공주를 해치운 후 스톤필드 농장에 있는 스톤필드 부인에게 놋쇠 목걸이를 가져가야 합니다.", description = "브랙웰 집안에는 마을 가축 대회에서 입상한 공주라는 이름의 돼지가 있는데, 몸집도 거대한 이 암퇘지가 이곳으로 와 내 채소를 먹어 버리니 얼마나 속상한 지 모른답니다!\n\n그래서 말인데 그 암퇘지가 우리 땅에 오기 전에 공주를 없애야 합니다! 공주를 없애고 증거물로 암퇘지의 목걸이를 가지고 오면 내 사례를 하겠습니다.\n\n공주는 주로 맥클루어 농장 너머 동쪽에 있는 브랙웰 호박밭에 있습니다. 그 암퇘지가 배가 고파져서 다시 이곳으로 오기 전에 해치워 주세요!", progress = "아직 그 암퇘지를 못 봤나요? 아니면 처치해 버린건가요?", completion = "신이시여, 감사합니다! 그 돼지는 우리 농작물을 다 먹어 치워서 나날이 뚱뚱해 지고 있었답니다. 정말 고마워요.\n\n자, 이것들이 당신에게 맞을는지 모르겠네요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n낡고 해진 장화놋쇠박은 팔보호구농부의 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[89] = {title = "영원의 다리", objective = "레이크샤이어에 있는 현장감독 오슬로우에게 철제 파이크 5개와 철제 리벳 5개를 가져가야 합니다.", description = "마지막으로 오크의 침략이 있었을 때 우리는 모든 철을 녹여 총알, 검, 갑옷을 만들어야만 했네. 스톰윈드에 자재를 새로 보내 달라는 전갈을 보냈지만 붉은마루일족 놀 무리가 중간에 운반차를 가로채 레이크샤이어 뒤쪽의 언덕으로 도망쳐 버렸지.\n\n그래서 이제는 다리를 재건할 수 있는 자재가 부족하네. 내게 철제 파이크 5개와 철제 리벳 5개를 가져다준다면 확실히 보상해 주도록 하지.\n\n자, 어서 출발하게나!", progress = "이 다리가 저절로 만들어지리라 생각하나! 대체 철제 파이크하고 철제 리벳은 어디 있나?", completion = "잘했네. 이 보급품은 다리를 재건하는데 큰 도움이 될 걸세. 멀지 않아 아름다운 다리를 완공할 수 있을 거야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n대장장이의 작업바지교량작업자의 장갑승마용 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[90] = {title = "늑대 양념 케밥", objective = "늑대 살코기 10개와 스톰윈드 향초를 모아 다크샤이어의 주방장 그루얼에게 돌아가야 합니다.", description = "늑대 양념 케밥은 이곳에서 가장 인기 있는 요리 중 하나지요! 손님께서 원하시면 요리해 드릴 수도 있지만 우선 재료가 있어야겠지요? 늑대 살코기 10점과 스톰윈드 향초를 구해 오셨으면 합니다. 이 마을의 숲엔 늑대가 많이 살고 있으니 살코기는 쉽게 구할 수 있을 겁니다. 아, 향초는 스톰윈드 대운하 향기로운 화원에 있는 펠리시아 검프를 찾아가 보세요.", progress = "벌써 늑대 살코기 10점을 구했나요? 스톰윈드의 펠리시아를 만나서 향초도 구해 오셨고요?", completion = "정말 잘하셨어요, 손님! 자, 그럼 늑대 양념 케밥이라는 별미를 한번 맛보세요!", rewards = "다음과 같은 것들을 받습니다:\n\n양념 늑대 케밥조리법: 양념 늑대 케밥"},
[91] = {title = "솔로몬의 법", objective = "레이크샤이어 마을 회관에 있는 집행관 코나처에게 잿빛가죽일족 펜던트 10개를 가져가야 합니다.", description = "이곳 붉은마루 산맥 동쪽 언덕엔 스톰윈드의 적이 우글거리고 있습니다. 한 사악한 녀석이 비전 마술을 사용하여 마을 사람들을 불안과 공포에 떨게하고 있습니다. 이 사악한 일을 벌이고 있는 장본인은 바로 모건스라는 자입니다.\n\n현재 모건스는 잿빛가죽놀을 다스리며 자신의 명령을 따르게 하고 있습니다. 레이크샤이어의 법에 따르면 왕국의 죄인을 돕게 되면 사형에 처하도록 되어 있습니다.\n\n이 사악한 놀들에게 레이크샤이어의 이름으로 처벌을 내려야만 합니다!\n\n그들을 처치하고 잿빛가죽일족 펜던트 10개를 가져다주시면 보상해 드리도록 하겠습니다.", progress = "잿빛가죽일족 펜던트를 10개 가지고 오면 보상해 드리겠습니다.", completion = "레이크샤이어의 법정을 대신해서 당신의 정의로운 행동에 감사를 표하는 바입니다. 당신은 왕국의 법을 성실히 집행하여 이 땅에 정의의 여신의 이름을 드높여 주었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[92] = {title = "붉은마루산 굴라시 스튜", objective = "레이크샤이어의 주방장 브리나가 질긴 독수리 고기 5개, 큰 뿔엄니멧돼지 주둥이 5개, 파삭파삭한 거미 고기 5개를 가져다 달라고 부탁했습니다.", description = "손님께서 주문하신 붉은마루산 굴라시 스튜를 요리해 드릴 수 있다면 좋겠지만 문제가 좀 있어요. 최근에 오크들이 날뛰는 동안 스톰윈드 전체 부대에 식량을 공급하느라 재료 창고가 바닥이 났답니다. 혹시 재료를 구해다 주신다면 정성껏 요리해 드리도록 하죠.\n\n질긴 독수리 고기 5개, 큰 뿔엄니멧돼지 주둥이 5개, 파삭파삭한 거미 고기 5개를 가져다주세요.", progress = "아직도 질긴 독수리 고기 5개, 큰 뿔엄니멧돼지 주둥이 5개, 파삭파삭한 거미 고기 5개가 필요해요.", completion = "재료의 상태도 신선하고 요리하기 안성맞춤이군요! 자, 별미 중의 별미, 붉은마루산 굴라시 스튜를 맛보세요!", rewards = "다음과 같은 것들을 받습니다:\n\n붉은마루산 굴라시 스튜조리법: 붉은마루산 굴라시 스튜"},
[93] = {title = "갈색 게살 케이크", objective = "끈끈한 거미 다리 6개를 모아 다크샤이어에 있는 주방장 그루얼에게 가져가야 합니다.", description = "작은 비밀을 하나 알려 드릴까요? 갈색 게살 케이크는 사실 거미 다리로 만든 거랍니다! 좀 메스껍다는 건 알지만 톡 쏘는 맛이 훌륭하고 씹는 맛도 일품이거든요! 끈끈한 거미 다리를 가져다주시면 케이크를 몇 개 구워 드리도록 하죠.\n\n북쪽에 있는 언덕과 강 사이에 서식하는 그물독거미가 최고의 재료라고 합니다.", progress = "어서 오세요. 벌써 끈끈한 거미 다리를 다 구하셨습니까?", completion = "오, 괜찮은 다리들을 가지고 오셨군요! 이제 이걸 저만의 비밀 양념으로 간을 맞춘 다음... 참, 훔쳐보시면 안됩니다요... 프라이팬에 잠시 구우면 됩니다.\n\n갈색 게살 케이크는 제 전문 요리라 조리법을 알려 드릴 수는 없군요. 대신 그에 버금가는 요리의 조리법을 알려 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n조리법: 쫄깃쫄깃한 거미 케이크"},
[94] = {title = "감시의 눈동자", objective = "아조라의 조각상을 붉은마루 산맥에 있는 일갈라의 탑 근처의 오래된 사자상으로 가져가야 합니다.", description = "내 경쟁자인 모건스라는 강력한 악의 마법사가 붉은마루 산맥의 일갈라의 탑에 살고 있다네. 난 아조라의 눈으로 그자를 몰래 감시할 수 있는 방법을 찾아내어 이제 멀리서도 그를 볼 수가 있게 되었네.\n\n그러나 그의 생각을 연구하려면... 도움이 좀 더 필요하다네.\n\n나를 도와 줄 생각이 있다면 내 아조라의 조각상을 일갈라의 탑으로 가져가 탑 근처의 오래된 사자상 위에 올려놓아 주게나.\n\n그게 끝나면 아조라의 힘은 모건스의 차후 계획을 예견해 줄 수 있을 걸세.", progress = "이 오래된 사자상은 수십 년간 이곳에 우뚝 솟아 악명 높은 일갈라의 탑를 내려다보고 있습니다.\n\n석상의 기단부에는 보석이나 조각상을 끼워 넣을 수 있는 움푹 패인 곳이 있습니다.", completion = "아조라의 조각상을 석상에 놓으니 저절로 고정됩니다. 그리고 조각상에서 테오크리투스의 목소리가 흘러 나옵니다.\n\n\"젊은 용사여, 정말 고맙네. 이제부터는 이 조각상을 이용해서 나와 대화할 수 있을 것일세... 내 경쟁자를 감시하면서 필요하면 자네에게 다른 임무를 맡기도록 하지.\"", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[95] = {title = "스벤의 복수", objective = "요르겐 농장으로 가서 오래된 그루터기 뒤에 묻힌 물건을 찾아야 합니다.", description = "난 남동쪽에 농장을 하나 운영했었습니다. 그런데 내가 없는 사이에 죽음의 고개에서 흑기사들이 농장으로 내려와 내 가족을 모조리 학살해 버렸습니다!\n\n집으로 돌아왔을 때 헛간 근처에서 유령 같이 창백한 얼굴을 한 자가 뭔가를 허겁지겁 묻고 있는 걸 봤습니다. 그자는 내가 다가가기 전에 도망쳐 버렸고, 나도 흑기사의 뒤를 추적해야했기에 그자가 무얼 숨긴 건지 아직까지 모르고 있습니다.\n\n그자가 뭘 묻었는지 알아봐 주면 정말 고맙겠습니다. 숨긴 곳의 위치는 내 헛간 근처의 오래된 그루터기 뒤입니다.", progress = nil, completion = "마치 누군가 무엇을 숨기려고 했지만 시간이 부족해서 급히 쌓아 놓은 것으로 보이는 흙무더기가 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[96] = {title = "물의 부름", objective = "불모의 땅에 있는 이슬렌 워터시어에게 물의 결정을 가져가야 합니다.", description = "이 물의 결정을 받게. 그리고 저들에게 생명을 주게.\n\n생명을 주고 깨닫게. 물은 곧 생명이요... 타락은 생명의 끝이라는 것을!\n\n자, 가서 물의 힘으로 생명을 보호하게.", progress = "돌아왔군요. 훌륭해요!\n\n은빛소나무 숲으로 가는 여행은 어땠나요? 고되고 오랜 길이었나요?\n\n이미 너무 많은 땅이 타락해 버려서 당신이 그곳에서 마친 임무가 우리에게 도움이 됐다고는 말하기 힘들군요. 하지만 때로는 작은 성공이 큰 성공만큼 중요하죠. 그곳 물을 정화한 것은 당신은 물론 모든 <class>들에게 도움이 되는 일이었어요.", completion = "그래요, 내가 말했던 증거를 가져오셨군요. 수고했어요.\n\n정말 축하해요. 당신에게 물의 토템을 주는 게 내가 처음이라니 정말 기쁘네요. 물의 토템을 잘 쓰도록 하세요. 그리고 행운을 빌어요.\n\n다음 시험까지는 조금 시간이 있으니까 당분간은 열심히 배우세요. 순수한 물은 상처 받은 이들을 치유해 줄 뿐만 아니라 수많은 효능을 발휘할 수 있어요. 시간이 나면 상급 &lt;class&gt;를 찾아가보는 것이 좋겠어요. 당신에게 다른 마법을 가르쳐줄지도 모르니까요.", rewards = "다음과 같은 것들을 배웁니다:\n\n치유의 토템\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n치유의 토템\n\n다음과 같은 것들 또한 받습니다:\n\n물의 토템"},
[97] = {title = "스탈반의 전설", objective = "사령관 이본로크 경에게 필체가 일치한다는 소식을 보고해야 합니다.", description = "필체가 일치한다는 사실을 즉시 이본로크 사령관께 전해 주십시오! 사령관님의 의혹이 사실로 밝혀졌다고요!", progress = nil, completion = "내 이럴 줄 알았지! 잘했소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[98] = {title = "스탈반의 전설", objective = "스탈반 미스트맨틀을 처치하고 에바 부인에게 미스트맨틀 가문의 반지를 보여 줘야 합니다.", description = "스탈반 미스트맨틀은 타락한 삶을 살았소. 그자의 손에 선량한 사람들이 희생됐고, 그자가 수없이 많은 범죄를 저질렀다는 건 의심의 여지도 없지. 지금 이 미치광이가 다크샤이어를 위협하고 있지만 또 어떤 추악한 계획을 세우고 있는지는 아무도 모르오. <class>. 마을 바로 북쪽에 있는 그의 오두막으로 가서 스탈반을 없애버리도록 하시오!\n\n그리고 임무를 완수한 후에는 에바 부인에게 가서 미스트맨틀 가문의 반지를 보여 주도록 하시오. 결국 그녀의 예지력 덕분에 이런 소름끼치는 사실을 밝혀낼 수 있었던 거니까 말이오. 그리고 그녀 덕분에 다크샤이어도 더 안전해졌소.", progress = "그래, 무슨 일인가?", completion = "이미 알고 있어. 스탈반이 죽었지? 저 더럽혀진 숲에서 희망의 물결이 이는 것을 느꼈지. 그늘숲은 이제 그의 피비린내 나는 욕망으로부터 해방된 게야. 하지만 그 끔찍한 짐승에게 희생된 사람들이 있으니 기쁨도 잠시일 수밖에. 그럼에도 자넨 참으로 용감하고 명민한 &lt;class&gt;|1이야;야;.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n외로운 영혼의 초승달 도끼외로운 영혼의 반지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[99] = {title = "아루갈의 계략", objective = "공동묘지에 있는 달라 던위버에게 장작나무 족쇄 6개를 가져가야 합니다.", description = "아루갈의 마법에 대한 흑막을 알아갈수록 그 불쌍한 바보가 경멸스럽군. 그자의 치료법이라는 것에 대한 조사가 거의 끝나 가고 있소.\n\n장작나무 마을에서 벌어지고 있는 이상한 일들의 원인이 된 마법만 밝혀내면 모든 걸 알 수 있을 것이오. 그곳 농부들은 낮 동안은 인간의 모습을 하고 있지만 해가 지면 달의분노일족 늑대인간으로 변한다오.\n\n아루갈이 주민들에게 채워 놓은 마법의 족쇄에서 힘을 뽑아내고자 하오. 마법걸린 장작나무 족쇄 6개를 내게 가져오시오.", progress = "장작나무 족쇄는 손에 넣었소?", completion = "의지가 무척이나 강한 친구로군. 당신이 모아 온 정보를 이용해 아루갈을 물리치고 그의 무모한 마법을 풀 수 있을 것이오. 공로를 치하하는 바이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n장작용 도끼뼈가는 막자숯불 마법봉\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n신비한 지능\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[100] = {title = "물의 부름", objective = "은빛소나무 숲에 있는 하급 물의 현신과 대화하십시오.", description = "주문을 다 외우자 눈부신 빛이 뿜어져 나옵니다. 물방울이 불꽃에 닿는 소리가 희미해지고 주위의 타락한 정령들이 죽어가면서 온몸의 감각이 마비되는 것 같습니다.", progress = nil, completion = "고맙소. &lt;class&gt;여, 정말 고맙소.\n\n타락의 기운은 쇠했으나 생명의 기운 역시 점점 빛을 잃어 가고 있소. 생명을 보호하는 일은 &lt;class&gt;들의 몫이니...", rewards = nil},
[101] = {title = "시련의 토템", objective = "다크샤이어의 에바 부인에게 구울 송곳니 10개, 해골 손가락 10개와 거미독 약병 5개를 가져가야 합니다.", description = "서서히 숲에 불길한 조짐이 나타나고 있으니 이제 자신을 방어해야 할 때가 온 게야. 바람이 곧 그대가 처하게 될 크나큰 위험에 대해 알려주고 있네.\n\n고귀한 <class>|1이여;여;, 자신을 보호하고자 한다면 구울 송곳니 10개와 해골 손가락 10개, 거미독 약병 5개를 내게 가져오게. 내 마법의 힘으로 그대를 해하려는 자들을 막아 줄 시련의 토템을 만들어 주도록 하지.", progress = "내게 구울 송곳니 10개와 해골 손가락 10개, 거미 독액이 든 약병 5개를 가져와야 해. 내 마법의 힘으로 그대를 해하려는 자들을 막아 줄 시련의 토템을 만들어 주겠네.", completion = "잘 생각한 게야. 이 시련의 토템이 아제로스와 그 너머에 도사리고 있는 어둠의 세력으로부터 그대를 지켜 줄 걸세. 위험이 느껴질 때 이 토템을 착용하면 신비한 오라가 그대를 구원해 줄게야. 용기를 내게, 유능한 &lt;class&gt;|1이여;여;. 그대의 앞날에는 수많은 위험이 도사리고 있어. 굳센 마음으로 지혜롭게 헤쳐나가야 할 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n시련의 토템"},
[102] = {title = "서부 몰락지대 순찰", objective = "감시의 언덕에 있는 정찰대장 다누빈에게 놀의 앞발 8개를 가져가야 합니다.", description = "서부 몰락지대의 평원을 가로질러 사악한 바람이 불어오고 있소. 스톰윈드는 내 고향 서부 몰락지대를 버렸지만 난 이곳에 남기로 결정한 주민들에게 절대 등을 돌리지 않을 것이오. 그저 농사밖에 몰랐던 우리가 이제 자신을 지키지 않으면 안 되는 시기요.\n\n당신이 우리를 돕겠다면 서부 몰락지대의 초원을 순찰하는 임무를 맡기도록 하지. 죽음의 폐광 도적 떼와 야합한 고약한 놀 무리를 처치해 주시오. 놀의 앞발 8개를 가져오면 당신의 용기에 합당한 보상을 하도록 하겠소.", progress = "저 비열한 놀들의 앞발 8개는 모아 왔소?", completion = "잘했소. 당신처럼 용감한 이가 백성의 민병대와 함께한다면 서부 몰락지대는 다시 예전의 풍요로운 곡창 지대로 돌아갈 수 있을 것이오. 자, 이걸 받아 주시오. 당신의 지칠 줄 모르는 노력에 대한 자그마한 보답이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n백성의 민병대 허리띠백성의 민병대 팔보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[103] = {title = "불꽃을 지키는 자", objective = "서부 몰락지대 등대에 있는 그레이슨 선장에게 기름 주머니 5개를 가져가야 합니다.", description = "등대지기의 가족이 죽던 밤은 정말 끔찍했지. 내 눈 앞에서 늙은 거먹눈 멀록이 공격을 주도하는데 나는 아무것도 하지 못하고 보고만 있었소. 후회하고 있지만 이미 엎질러진 물은 되돌릴 수 없으니 어쩌겠소. 지금은 대해를 항해 중인 선원들의 생명이 걱정이오. 배가 해안선의 거대한 암초에 너무 가까이 접근했소. 그리고 등대의 불꽃을 지키는 사람이 없으니 이제는 내가 그 책임을 져야 하오.\n\n내가 횃불을 밝힐 수 있도록 허수아비 괴물들을 처치하고 기름 주머니 5개를 구해다 주시오.", progress = "기름을 구하지 못하면 불꽃이 오래 버티지 못할 것이오.", completion = "정말 고맙소, 용감한 &lt;class&gt;|1이여;여;. 서부 몰락지대 해안의 암초들도 아마 그대의 노고에 고마워할 것이오. 물론 등대의 횃불이 꺼지지 않는 한 귀중한 생명을 많이 구할 수 있을 것이오.\n\n나도 바로 이 해변에서 허망하게 목숨을 잃었다오. 그래서 죽은 후에 난 다시는 나와 같은 운명을 맞는 사람이 없도록 하겠다고 맹세했다오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n최하급 마나 물약최하급 치유 물약\n\n다음과 같은 것들 또한 받습니다:\n\n지능의 두루마리체력의 두루마리"},
[104] = {title = "해안의 위협", objective = "서부 몰락지대 등대에 있는 그레이슨 선장에게 늙은 거먹눈 멀록의 비늘을 가져가야 합니다.", description = "암초에 배가 침몰해 내 목숨을 잃었을 때는 죽은 후에도 이렇게 산 자들과 함께 지낼 수 있으리라고는 상상도 못했소. 내가 죽던 그날 밤 늙은 거먹눈 멀록이 등대지기의 가족들을 위협하여 쫓아내는 바람에 등대가 꺼져 있었지. 그들은 나중에 다시 돌아와 횃불을 밝혔지만 늙은 거먹눈 멀록이 약한 멀록들을 선동해 다시 등대를 습격하고 말았소. 등대지기의 가족들은 내 눈 앞에서 힘없이 죽어갔지.\n\n해변에서 늙은 거먹눈 멀록을 보거든 처치해 버리고 놈의 비늘 하나를 내게 가져다주시면 내 보상하도록 하겠소.", progress = "그 괴물 같은 늙은 거먹눈 멀록은 처치했소? 놈은 서부 몰락지대 해안에서 어슬렁거리곤 한다오.\n\n그 괘씸한 놈을 처치한 후에 내게 돌아오시오.", completion = "이제야 그 지독한 거먹눈 멀록이 사라졌군. 잘했소. 그대 덕분에 나도 편히 눈감게 됐지만, 그보다 더 많은 생명을 구할 수 있게 되어 더욱 기쁘오. 그대의 영웅적인 행동 덕분에 저 위험한 대해도 오늘 밤엔 조금 안전하겠군그래.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n그레이슨의 횃불바다의 버클러횃불 마법봉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[105] = {title = "리치의 최후", objective = "서부 역병지대의 보루에 있는 고위집행관 델링턴에게 아라즈의 성물함 조각을 가져가야 합니다.", description = "이제 안돌할을 공격해 그곳을 지배하고 있는 리치를 몰아낼 때가 왔네!\n\n도시의 폐허 안쪽에 지배권을 쥐고 있는 소환사 아라즈라는 리치가 있네. 그는 도시 중심부의 폐허 주위에 있는 수많은 스컬지의 보호를 받고 있고, 그에게 직접적으로 결속되어 있는 개인 수행원들은 위협적인 존재들이네. 그와 맞서려면 많은 동료들이 필요할게야.\n\n리치를 처치하고 그 증거로 아라즈의 성물함 조각을 가져오도록 하게!", progress = "난 이미 자네에게 임무를 준 것으로 기억하네만, 임무를 완료한 증거로 리치의 성물함 조각을 가져왔나?", completion = "해냈군! 리치... 아라즈를 드디어 물리쳤어!\n\n자네는 오늘 호드를 위해 큰 공을 세운 것일세. 자네의 용기와 끈기야말로 진정한 영웅이 갖춰야 할 덕목이 무엇인지 잘 보여주는 것이야. 자, 이 보상을 받게나! 모두들 자네가 세상에 둘도 없는 승리를 호드에게 안겨주었다는 것을 알 수 있도록 말이야!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n결심의 징표"},
[106] = {title = "젊은 연인들", objective = "토미 조 스톤필드에게 메이벨의 연애 편지를 가져가야 합니다.", description = "아, 어떡하면 좋죠? 내 마음은 이미 토미 조 스톤필드에게 빼앗겨 버렸는데... 우리 집안은 토미 집안이랑 서로 원수지간이랍니다. 그래서 그의 멋진 얼굴을 보고 싶어도 만날 수가 없어요!\n\n제발, 이 편지를 토미 조에게 전해 주세요. 토미 조는 보통 스톤필드 농장의 서쪽에 있는 강가에 있답니다. 여기서 정서 쪽으로 가시면 돼요.", progress = "뭘 가지고 왔다고요?? 오, 메이벨 내 사랑! 내 무미 건조한 인생에 메이벨은 빛과 같은 존재랍니다. 어서, 그녀의 편지를 이리 주세요!", completion = "아! 더는 이렇게 떨어져 있을 수는 없습니다. 그녀를 보러 가야겠어요!!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[107] = {title = "윌리엄에게 보내는 쪽지", objective = "윌리엄 페슬에게 스톤필드 할머니의 쪽지를 전달해야 합니다.", description = "오, 그래. 윌리엄 페슬이라면 틀림없이 이 두 젊은 연인을 만나게 해 줄 수 있는 물약을 가지고 있을 게야!\n\n자, 이 쪽지를 윌리엄에게 전달해 주게나. 윌리엄은 골드샤이어의 사자무리 여관에 머물고 있다네.", progress = "스톤필드 할머님의 쪽지를 가지고 왔다고 했나요? 밀드레드 할머님을 못 뵌지도 몇 년이 지났군요! 흠, 내게 무슨 할 말이 있으신 건지...", completion = "이 불쌍한 두 연인, 메이벨과 토미 조의 이야기가 내 마음을 울리는군요. 나도 한때는 젊었고 사랑에 빠졌던 적도 있었지요.\n\n어떻게든 이 젊은 연인들을 도와 줄 수 있을 겁니다! 어디, 생각 좀 해 봅시다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[109] = {title = "그라이언 스타우트맨틀에게 보고", objective = "그라이언 스타우트맨틀과 대화해야 합니다. 서부 몰락지대의 중심부에서 길을 약간 벗어난 곳에 있는 감시의 언덕 돌탑으로 가면 그를 만날 수 있습니다.", description = "그동안 전투 경험을 많이 쌓은 것 같군. 아직 그라이언 스타우트맨틀 경께 보고하지 않았다면 어서 그분께 가 보도록 하시오. 그라이언 스타우트맨틀 경께서는 서부 몰락지대의 안전을 위해 결성된 백성의 민병대의 지휘관이시오. 당신이라면 분명히 그분께 도움이 될 것이외다. 서부 몰락지대의 중심부 도로를 약간 벗어난 곳에 위치한 감시의 언덕으로 가면 그분을 만나 뵐 수 있을 것이오.", progress = nil, completion = "아, 내 친구가 귀관을 이곳으로 보냈단 말인가? 친절한 친구 같으니. \n\n현 스톰윈드 정권은 대의를 저버렸네. 이제는 백성의 민병대만이 이 땅의 부패를 막을 수 있네. 우리의 대의에 동참한다면 자유의 이름으로 귀관이 전투 능력을 발휘할 수 있도록 해 주겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[110] = {title = "곤충 기관 분석", objective = "가젯잔에 가서 연금술사 페슬저그를 만나 곤충 기관의 분석이 끝났는지 알아보아야 합니다.", description = "당분간 나는 슈섕크의 업무를 정리하고 또... 그의 측량 장비를 살펴보려고 하오. 어째선지 그 곤충들로 인해 더 피해를 보게 될 것 같군.\n\n연금술사 페슬저그에게 가서 내가 보냈던 곤충 기관을 조사했나 알아봐 주시오. 결과물이 준비됐으면 내게 가져와 주시오.", progress = nil, completion = "결과가 나왔습니다. 그게... 아주 불안한 사실입니다.\n\n처음에 우리가 의심했던 대로 이 곤충들은 외부의 힘에 의해 조종을 받고 있는 게 거의 확실합니다. 그렇다면, 우리는 아주 강력하고도 사악한 미지의 힘에 맞서고 있는 겁니다. 이 곤충들은 완벽한 파괴자로 변해 버렸어요. 나도 이런 건 생전 처음 봤습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[111] = {title = "할머니와 대화", objective = "스톤필드 할머니와 대화해야 합니다.", description = "부탁입니다. 이 문제를 우리 할머니와 의논해 주세요. 내가 메이벨을 만나게 해 줄 수 있는 방법을 아는 분은 우리 할머니밖에 없을 겁니다.\n\n할머니는 여기에서 동쪽에 있는 우리 집 안에 계십니다.", progress = nil, completion = "두 가족 간의 불화가 계속되는 한, 토미 조와 메이벨의 미래는 암울할 뿐이지...하지만 아주 잠시만이라도 둘을 만나게 해 줄 수는 있을 게야.\n\n음, 어떻게 하면 좋을까...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[112] = {title = "해초 수집", objective = "투명한 해초 잎 4개를 골드샤이어의 윌리엄 페슬에게 가져가야 합니다.", description = "내가 메이벨에게 투명 물약을 만들어 주도록 하지요. 그러면 맥클루어 포도밭을 빠져나와 토미 조를 만나러 갈 수 있을 겁니다. 하지만 이 물약을 만들려면 투명한 해초가 필요하답니다.\n\n원래 해초는 큰 바다에서 자라지만... 때로는 수정 호수에 있는 멀록이 수집해 두기도 하지요. 수정 호수는 바로 골드샤이어의 동쪽에 있습니다.", progress = "투명한 해초 잎을 가지고 왔습니까? 지금쯤 메이벨은 애인을 만나기 위해 애태우고 있을 텐데...", completion = "가지고 왔군요. 대단합니다! 물약을 만들 동안 잠시 기다리십시오...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[113] = {title = "곤충 기관 분석", objective = "가젯잔에 있는 선임측량사 피즐도저에게 곤충 분석 보고서를 가져가야 합니다. 연금술사 페슬저그가 요청한 대로 피즐도저로부터 보고서의 사본을 꼭 받아야 합니다.", description = "즉시 이 보고서를 선임측량사 피즐도저에게 보여주어야 합니다. 사실... 글을 읽을 줄 아는 자라면 누구에게든 보여주어야 해요. 그만큼 도움의 손길이 절실한 중대사입니다. 이 심각한 위협은 그대로 방치할 경우 타나리스와 가젯잔뿐만 아니라 칼림도어 전체를 집어삼킬 거예요. 그게 다 뭐야, 아예 아제로스를 통째로 휩쓸어 버릴 수도 있어요. 그 세력은 사그라질 기미가 전혀 보이지 않으니까...\n\n피즐도저에게 이 보고서의 사본을 만들어 달라고 하세요. 그래서 모두에게 알려야 해요. 이 위협에 대해서는 모두 알아야만 합니다!", progress = "아, 후임측량사 <name>|1이로군;로군;. 페슬저그, 그 친구가 보고서를 준비해줍디까?", completion = "고맙소. 여기 가젯잔 수자원개발회사를 위해 부지런히 뛰어준 것에 대한 보수요.\n\n보통 우리는 귀중한 정보를 공짜로 주지는 않소. 돈을 주고 살 사람들도 널렸는걸... 하지만 페슬저그는 한두 해 알고 지낸 친구가 아닌데, 그 친구가 모두에게 알려야 한다고 말했다면 그렇게 해야만 하오. 잠시만 기다려 주시오. 사본을 하나 만들어 주겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[114] = {title = "탈출", objective = "메이벨 맥클루어에게 투명 물약을 가져가야 합니다.", description = "이 투명 물약을 메이벨에게 가져다주십시오. 토미 조를 만나러 가는 데 걸리는 시간 동안은 약효가 지속될 겁니다.", progress = "제 편지를 토미 조에게 전달하셨나요? 그가 뭐라고 하던가요??", completion = "오... 이런... 가족들을 속이는 건 정말 마음 아픈 일이지만 그래도 토미 조를 향한 제 마음을 어쩔 수가 없어요.\n\n감사합니다. 기회가 생기는 대로 이 물약을 마시고 몰래 그를 만나고 올게요.\n\n그리고 이건 수고해주신 당신을 위해 준비한 거랍니다. 받아 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n최하급 치유 물약"},
[115] = {title = "어둠의 마법", objective = "레이크샤이어에 있는 치안대장 매리스에게 암흑의 수정구 3개를 가져가야 합니다.", description = "검은바위부족 오크들이 붉은마루 산맥 공격을 지원하기 위해 흑마술사를 끌어들이고 있네. 이 흑마술사들은 어둠의 힘이 담긴 암흑의 수정구를 사용하고 있지. 이 수정구는 붉은마루 산맥의 경비병들에게 강력한 공격을 퍼붓고 있기 때문에 일차적으로 제거해야 할 물건일세.\n\n검은바위부족 흑마술사를 쓰러뜨리고 암흑의 수정구를 찾아오면 내가 파괴하도록 하겠네. 이 세상에 그런 수정구는 없는 게 더 낫지 않겠나!", progress = "흑마술사를 상대로 한 싸움은 어떻게 되어 가나? 암흑의 수정구는 찾았는가?", completion = "고맙네. 당장 이 수정구를 파괴하도록 지시하겠네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[116] = {title = "떨어져 가는 술", objective = "레이크샤이어의 바텐더 대니얼스가 썬더브루 맥주통과 멀롯 술통, 문샤인 병, 향기로운 럼주 주머니를 가져다 달라고 부탁했습니다.", description = "휴, 술창고에 술이 다 떨어져 가고 있어요. 장사를 할 수 없을 지경이라 큰일이에요. 마지막으로 술을 들여온 지 무척 오래되었는데 사방에서 오크의 침략 때문에 난리가 나서 보급을 받을 수가 없답니다.\n\n혹시 좀 도와 주실 수 있나요?\n\n서부 몰락지대 언덕의 그림부즈 썬더브루에게 썬더브루 맥주통과 스톰윈드에서 멀롯 술통, 다크샤이어에서 문샤인 병, 골드샤이어에서 향기로운 럼주 주머니를 가져다주세요. 제 부탁을 들어주시면 꼭 보답하겠습니다.", progress = "서부 몰락지대 언덕의 그림부즈 썬더브루에게서 썬더브루 맥주통과 스톰윈드에서 멀롯 술통, 다크샤이어에서 문샤인 병, 골드샤이어에서 향기로운 럼주 주머니를 가져다주세요. 제 부탁을 들어주시면 꼭 보답하겠습니다.", completion = "오, 정말 감사드립니다! 술을 구하느라 이곳저곳을 여행하셔서 피곤하시겠네요. 새로 술을 들여온 것을 알면 제 단골손님들이 무척 좋아하실 겁니다! \n\n자랑일진 모르겠지만 제 아내의 재봉 실력이 보통이 아니랍니다. 수고하신 보답으로 제 아내가 만든 옷을 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n잘 짜여진 망토불룩한 동전주머니"},
[117] = {title = "썬더브루 맥주", objective = "특별한 맥주를 완성할 수 있도록 그림부즈 썬더브루에게 홉 열매 5개를 가져가야 합니다.", description = "서두르게 친구여, 어서 서둘러 \n맛 좋은 맥주를 \n스튜같지 않고 진한 맥주로 만들려면 \n홉 열매를 넣어서 맥주를 만드세", progress = "서두르게 친구여, 어서 서둘러 \n맛 좋은 맥주를 \n스튜같지 않고 진한 맥주로 만들려면 \n홉 열매를 넣어서 맥주를 만드세", completion = "홉 열매와 보리, 누룩과 엿기름 \n혀 끝에 전해오는 쌉싸름한 이 맛 \n부탁도 애원도 필요 없도록 \n썬더브루 맥주가 통에 한 가득!", rewards = "다음과 같은 것들을 받습니다:\n\n썬더브루 맥주통"},
[118] = {title = "편자의 가격", objective = "골드샤이어에 있는 대장장이 아거스에게 베르너의 쪽지를 전달해야 합니다.", description = "스톰윈드 경비병들의 장비를 마련하느라 철을 너무 많이 써 버려서 마구간에 있는 말들의 발에 편자를 댈 철이 부족합니다!\n\n이 쪽지를 골드샤이어에 있는 대장장이 아거스에게 전달해 주세요. 현재 겪고 있는 문제와 편자를 좀 공급해 달라는 부탁을 적어 놓았습니다.", progress = "그건 뭡니까? 베르너가 보내서 왔다고요? 그럼 그의 쪽지를 내게 주십시오. 그리고 제발 좀 크게 말해 주세요!", completion = "그러니까 베르너한테 편자 몇 개가 필요하다 이건가요!?!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[119] = {title = "베르너에게 돌아가기", objective = "붉은마루 산맥에 있는 베르너 오스구드에게 돌아가 편자 상자를 전해 주십시오.", description = "좋습니다, 내 그에게 편자 50개를 주도록 하지요...\n\n자, 여기 상자에 넣어 포장했으니 가지고 가면 됩니다! 베르너에게 거래하게 되어 기쁘다는 말과 함께 꼭 상자에 붙여 놓은 쪽지를 읽으라고 전해주세요!", progress = "돌아왔군요! 편자는 가지고 왔나요?", completion = "고맙습니다. 이 편자는 정말 큰 도움이 될 겁니다.\n\n그런데 이건? 아거스가 상자와 함께 쪽지를 보냈네요... 뭣?? 나보고 돈을 내라고? 아이고!\n\n어쨌든 도와 주셔서 정말 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[120] = {title = "스톰윈드로의 전갈", objective = "집정관 솔로몬이 스톰윈드에 있는 장군 마커스 조나단에게 보고서를 전달해 달라고 부탁했습니다. 또한 전달한 후에 즉시 돌아가야 합니다.", description = "우리는 매우 어려운 시기를 겪고 있소, <class>|1이여;여;. 마을이 지속적인 공격을 받고 있어 증원군이 없으면 우리는 패배를 면치 못할 거요. 지금 맡기는 이 전갈은 그 무엇보다도 중요하오. 이 보고서를 즉시 스톰윈드의 장군 마커스 조나단님께 전달해 주시오. 전달한 후에 좋건, 나쁘건 바로 소식을 가지고 돌아와 주시오.\n\n자, 어서 서두르시오!", progress = "무슨 일인가?", completion = "편히 쉬게, &lt;class&gt;.\n\n집정관 솔로몬은 훌륭한 지도자네. 그의 말이라면 그냥 흘려 넘길 수가 없겠군. 내 직접 왕실 의회에 찾아가 상황을 보고하겠네. 어서 가서 집정관에게 스톰윈드 군대의 지원이 있을 것이라고 안심시키도록 하게. 증원군은 전하의 명령이 떨어지는 즉시 출발할 것일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[121] = {title = "스톰윈드로의 전갈", objective = "레이크샤이어의 집정관 솔로몬에게 장군 마커스 조나단의 답장을 전달해 주어야 합니다.", description = "내가 전하의 답변을 기다리는 동안 자네는 이 편지를 집정관 솔로몬에게 전달하게. \n\n자, 그럼 해산하도록!", progress = "장군이 새 소식을 보낸 건가? 증원군은 오고 있소?", completion = "당신의 귀중한 시간을 할애해 줘서 정말 고맙소. 자, 이 돈을 받으시오. 레이크샤이어와 스톰윈드를 도와 준 데 대한 보답이오.\n\n하지만 이 답장을 읽어 보니 뭔가 이상한 점이 있군. 우리 왕국에서 뭔가 심상치 않은 일이 벌어지고 있는 것 같소. 게다가 지금이 대립의 끝이 아니라 시작은 아닐까 하는 두려운 생각이 드는군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[122] = {title = "얇은 새끼용 비늘", objective = "얇은 새끼용 비늘을 6개 모아 붉은마루 산맥에 있는 베르너 오스구드에게 가져가야 합니다.", description = "골드샤이어의 아거스가 보내 온 편자에 대한 비용을 지급하려면 새끼 검은용을 처치하고 얇은 새끼용 비늘을 구해야 합니다. 얇은 새끼용 비늘을 6개 구해다 주시면 몇 개는 아거스에게 지급하는데 사용하고... 나머지는 유용한 걸 만들어 드릴 수 있을 겁니다.\n\n새끼 검은용은 주로 레이크샤이어 남쪽에서 날아다니지만 여기저기 방랑하는 것을 좋아하는 습성이 있습니다. 항상 주위를 살피다가 발견하는 즉시 사냥하는 게 좋을 겁니다.", progress = "아거스는 워낙 욕심이 많아서 비늘을 빨리 보내지 못하면 사람을 보내 올 겁니다. 아직 비늘을 구하지 못했나요?", completion = "고맙습니다! 이걸로 아거스에게 진 빚을 갚을 수 있을 겁니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n새끼 검은용 장화새끼 검은용 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[123] = {title = "징세관", objective = "골드샤이어의 치안대장 더그한에게 가서 징세관의 수금 일정표를 건네 주어야 합니다.", description = "이것은 단지 \"징세관\"이라고만 명시되어 있는 누군가가 엘윈 숲에 있는 광산에서 운송되어 오는 황금을 받는 날짜와 시간을 적어놓은 일정표입니다.\n\n이 일정표에 의하면 징세관은 엘윈 숲 동쪽의 브랙웰 호박밭 근처에 거주하는 것으로 보입니다.\n\n중요한 정보이므로 골드샤이어에 있는 치안대장 더그한에게 보고해야 합니다.", progress = "뭐라고?!? 석영 광산에서 황금 채광을 멈춘 지 벌써 수개월이 지났는데!\n\n그 일정표를 보여 주게...", completion = "흠... 전에 징세관에 대한 이야기는 들은 적이 있지만 누구를 위해 일하는 자인지는 모르겠군. 이 일정표를 가져다 줘서 고맙소. 이 수수께끼를 푸는 데 도움이 될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[124] = {title = "놀의 울음소리", objective = "붉은마루일족 투사 10마리와 붉은마루일족 비술사 8마리를 처치한 다음 베르너 오스구드에게 돌아가십시오.", description = "오크의 공격만 해도 정신이 없는데, 이제는 놀 투사와 놀 비술사까지 소중한 마구간 북쪽의 산마루를 어슬렁거리면서 낙오된 말들을 훔쳐가고 있습니다.\n\n당신이 저 놀들을 해치워 준다면 내 말들도 고마워할 겁니다.", progress = nil, completion = "도와 주셔서 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[125] = {title = "잃어버린 연장통", objective = "레이크샤이어의 현장감독 오슬로가 영원의 호수의 밑바닥에서 그의 연장통을 찾아다 달라고 부탁했습니다.", description = "나 좀 도와 주게나. 마을이 공격받고 있어서 보급품을 얻기가 쉽지 않네. 내 연장통이 골드샤이어에서 마차로 배달되었는데 지금은 다리가 끊어져 버려서 연장통을 배에 실어 운반하던 중 오크들의 투석기에 맞아 침몰해 버렸다네. 후, 연장통이 내 희망과 함께 호수 밑바닥으로 가라앉은 것이지.\n\n내 연장통을 찾아 준다면 충분히 보상해 주겠네.", progress = "혹시 내 연장통을 찾았나?", completion = "정말 고맙네! 이 연장통을 다시 보게 되다니 꿈만 같군.", rewards = "다음과 같은 것들을 받습니다:\n\n일반 방어구 키트"},
[126] = {title = "언덕에서 들려 오는 울음소리", objective = "레이크샤이어에 있는 베르너 오스구드에게 요울러의 앞발을 가져가야 합니다.", description = "아직도 놀들이 저곳에 있습니다. 레이크샤이어 위의 언덕에서 놀들이 사냥하는 울음소리가 들려온단 말입니다. 특히 그들의 우두머리인 요울러의 울음소리가 무척 크게 들립니다.\n\n요울러를 죽이고 그의 무리를 쫓아 주세요! 그리고 요울러의 앞발을 증거로 가져다주십시오.\n\n요울러가 우두머리가 된 데는 분명 이유가 있을 겁니다. 그냥 단순한 싸움꾼은 아닐 테니 조심하시기 바랍니다.", progress = "요울러는 위험한 괴물입니다. 아직 상대할 준비가 안 됐다고 하여도 충분히 이해합니다.", completion = "도와 주셔서 다시 한번 감사합니다. 스톰윈드 군대는 오크를 상대하느라 바빠서 놀 같은 주변 지역의 위협으로부터 붉은마루 산맥을 보호해 줄 병력이 없답니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n결의의 반지민병대의 황금 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[127] = {title = "물고기 매매", objective = "레이크샤이어에 있는 항구주임 바렌에게 점박이 개복치 10마리를 가져가야 합니다.", description = "영원의 호수는 점박이 개복치로 유명하지요. 항상 수요가 넘치는데... 공급이 부족하답니다!\n\n점박이 개복치 10마리를 가지고 오면 좋은 값을 쳐 드리죠. 직접 낚기가 어려우면 멀록에게 빼앗으면 될 겁니다!", progress = "개복치를 좀 가지고 왔나요?", completion = "허허, 거래하게 되어 즐거웠습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n멀록 지느러미 수프조리법: 멀록 지느러미 수프물고기간 오일"},
[128] = {title = "검은바위부족 현상금", objective = "검은바위부족 용사 15명을 처치하십시오. 그러면 레이크샤이어의 경비병 하우가 보상을 해줄 것입니다.", description = "국왕 폐하의 영토를 침범한 저 괘씸한 검은바위부족은 반드시 쓰러뜨려야만 합니다. 보고에 의하면 검은바위부족 각 소대의 지휘관을 용사라고 부른답니다. 북쪽 야영지로 가면 이들을 찾을 수 있을 겁니다. 불타는 평원으로 가는 길의 바로 서쪽에 있지요.\n\n집정관 솔로몬께서는 이 사악한 짐승들을 쓰러뜨리기를 바라고 계십니다. 검은바위부족 용사 15명을 처치하고 이곳으로 돌아와 주십시오.", progress = nil, completion = "옷에 묻은 피를 보니 검은바위부족과 격렬한 전투를 치른 것이 확실하군요. 이토록 마을을 위해 봉사하다니 참으로 훌륭합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[129] = {title = "공짜 점심", objective = "다크샤이어로 가는 도로를 순찰하고 있는 경비병 파커의 도시락을 가져가야 합니다.", description = "제 부탁 하나 들어주시겠어요? 경비병 파커의 점심을 준비해 놓았는데 지금 순찰 중이에요. 파커는 키가 크고 강한 스톰윈드 경비병이니까 자기 몸을 지킬 수 있지만, 저 같이 힘없는 마을 사람이 나가기엔 밖은 너무 위험하답니다.\n\n그러니까 이 점심을 저 대신 배달해 주고 오시면 점심 한 끼를 공짜로 대접할게요! 파커는 그늘숲으로 가는 도로를 따라 순찰하고 있을 겁니다.", progress = "달시가 점심을 보낸 거로군요? 정말 마음씨 고운 아가씨군. 자, 어서 이리 주십시오!", completion = "고맙습니다. 배가 정말 고팠는데 잘됐군요. 오크와 놀들로부터 레이크샤이어를 지키는 건 꽤 힘든 일이랍니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[130] = {title = "약초채집가 방문", objective = "붉은마루 산맥 약초채집가, 마티 제인로즈와 대화하십시오.", description = "달시한테 돌아가기 전에 제 대신 달시에게 꽃을 좀 사다 주시겠습니까? 레이크샤이어에 돌아가서 마을의 서쪽 끝으로 가면 꽃가게가 있답니다.\n\n그런데 말이죠... 꽃을 살 때 꽃가게 아가씨 마티에게는 제가 달시한테 보내는 꽃이라는 걸 절대로 말하면 안 됩니다...", progress = nil, completion = "꽃다발이 필요하다고요? 마을에 온 지 얼마 되지 않았는데 벌써 애인이 생긴 건가요?\n\n제가 꼬치꼬치 캐물을 일은 아니지만 그래도 사랑이라는 감정이 사람들 마음에 아직 남아 있다니 기분 좋네요. 특히 지금처럼 위험한 시기에 말이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[131] = {title = "나팔수선화 배달", objective = "달시에게 나팔수선화 꽃다발을 주어야 합니다.", description = "자, 꽃다발이 완성됐어요. 특별히 제가 제일 좋아하는 나팔수선화로 만들었답니다!", progress = "돌아오셨네요. 파커가 제가 보낸 점심을 좋아하던가요?", completion = "와, 정말 예쁘네요! 얼른 물에 담가 놓아야겠어요!\n\n그런데... 이건 마티가 제일 좋아하는 꽃이네요. 설마 파커가 그 질투심 많은 계집애한테서 이 꽃다발을 사라고 한 건 아니겠죠? 마티한테 파커가 저한테 보내는 꽃이라고 말하지는 않았죠? 그랬다면 분명 이 꽃다발에 독을 발라 놓았을 거예요.\n\n그렇다고 해도 당신 잘못이 아니니 걱정하지 마세요. 어쨌든 감사해요, 그리고 이것은 고마움의 표시이니 맛있게 드시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n살짝 데친 개복치"},
[132] = {title = "데피아즈단", objective = "서부 몰락지대에 있는 그라이언 스타우트맨틀에게 와일리의 쪽지를 전달해야 합니다.", description = "지금부터 하는 얘기는 내 목숨을 걸고 하는 거니 잘 들어요. 데피아즈단은 지금 뭔가 큰일을 꾸미고 있어요. 최근 들은 바로는 그들이 놀, 코볼트, 심지어 고블린과도 손을 잡고 있다더군요.\n\n이 쪽지를 스타우트맨틀에게 전해 주세요. 내가 알고 있는 거라고는 거기 적힌 게 전부에요.", progress = "어서 오게. 그래, 와일리가 뭐라고 했지?", completion = "흥! 아무리 생각해도 그때 그 건달 놈을 살려 주는 게 아니었어. 하지만 덕분에 유용한 정보를 얻었군. 잘했네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[133] = {title = "구울 허수아비", objective = "구울 해골 7개를 모아 통나무집에 있는 에이버크롬비에게 가져가야 합니다.", description = "마을에서 떨어진 외딴곳에 살고 있어 보호를 받을 수 없는데도 구울이나 언데드에게 잡아먹히지 않은 게 신기하지 않나! 사실 어제만 해도 뼈만남은 시체 무리가 내 집 벽을 치는 소리가 들렸다네.\n\n구울을 퇴치할 수 있는 허수아비 같은 걸 만들어야겠어. 허수아비를 만들려면 구울 해골이 필요하네. 구울 해골은 굶주린 시체나 뼈만남은 시체, 걸신들린 시체, 썩어버린 시체, 역병걸린 시체 녀석들에게서 구할 수 있다네.\n\n날 위해 구울 해골을 구해다 준다면 사례를 하도록 하지.", progress = "집 뒤로 구울 무리가 뛰어가는 걸 들은 것 같네. 서둘러 허수아비를 세워야겠어! 구울 해골은 구해 왔나?", completion = "고맙네. 이거면 녀석들을 막을 수 있을 거야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[134] = {title = "오우거 도적 떼", objective = "에이버크롬비에게 에이버크롬비의 상자를 되찾아 주어야 합니다.", description = "몇 주 전 집에서 멀리 떨어진 곳에서 향초를 뜯고 있었는데 오우거 무리가 날 공격했네! 혼비백산해서 도망치느라 귀중한 도구와 향초가 든 상자를 두고 왔지 뭔가.\n\n놈들은 날 멀리 쫓아낸 후에 그늘숲 남쪽의 오우거 언덕으로 사라졌으니 상자는 오우거 언덕 근처에 있을 걸세.\n\n내 상자를 제발 좀 찾아 주게. 내겐 너무 소중한 거야.", progress = "상자는 찾아 왔나? 찾았다면 어... 어서 내게 돌려줘!", completion = "오! 강령... 아니, 고맙네! 자, 받게나. 이 정도면 사례로 충분하고도 남을 걸세.\n\n아! 오늘은 정말 행복한 밤이 되겠군, 음하하!!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[135] = {title = "데피아즈단", objective = "스톰윈드에 있는 마티아스 쇼에게 와일리의 쪽지를 가져가야 합니다.", description = "와일리가 석공 길드에 대해서도 썼는데, 이게 무슨 의미일까? 뭐, 실수로 잘못 적은 것일 수도 있겠지만. 데피아즈단이 석공 길드와 관계가 있다고? 이에 대해 확실히 알 만한 사람은 스톰윈드 SI:7의 단장인 마티아스 쇼밖에 없네. 그에게 와일리의 쪽지를 보여 주고 아는게 있는지 알아보게나. 쇼를 찾는 게 어렵다면, 구 시가지의 병영에 가보도록 하게나.", progress = "나한테 무슨 볼일인가? 굉장히 바쁘네만...", completion = "스타우트맨틀 경이 생각하는 것보다 사태가 훨씬 복잡한 것 같군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[136] = {title = "샌더 선장의 숨겨진 보물", objective = "샌더 선장의 사물함에서 다음 단서를 찾아야 합니다.", description = "누군가 이 글을 읽는다면 이 늙은 선장 샌더가 바다 속에 수장되었다는 뜻이오. 그러니 이제 내 보물은 당신 것이지만 내 보물을 찾으려면 단서를 발견해야 할 것이오.\n\n먼저 내 사물함을 찾아야 하오. 아마 지금쯤 서부 몰락지대 서쪽 해안에 있는 난파선 근처 모래 속에 반쯤 묻혀 있을 것이오. 거기에 있는 많은 난파선 중에서 해변에 녹슨 닻을 내리고 있는 난파선을 발견하면 내 사물함을 찾을 수 있을 것이오. 거기서 다음 단서를 찾도록 하시오.", progress = nil, completion = "사물함이 삐걱거리며 천천히 열립니다. 하지만 그 안에는 모래와 물밖에 없는 것 같습니다. 바로 그 순간, 작은 게가 보물에 대한 단서를 집게발에 쥔 채 사물함에서 재빠르게 기어 나옵니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[138] = {title = "샌더 선장의 숨겨진 보물", objective = "다음 단서를 얻기 위해 굴뚝 잔해 근처에서 낡은 통을 찾아야 합니다.\n\n제공된 아이템: \n", description = "보물의 단서에는 다음과 같이 쓰여 있습니다. \"제법이군 그래, 친구! 이제 정동쪽을 향해 갈 차례요. 동쪽 절벽 위의 길을 따라 동쪽으로 가시오. 길가에서 낡은 굴뚝의 잔해를 발견하게 되면 다음 단서가 들어 있는 낡은 통을 발견하게 될 것이오.\"", progress = nil, completion = "제법이군, 보물 &lt;class&gt; 양반!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[139] = {title = "샌더 선장의 숨겨진 보물", objective = "다음 단서를 찾기 위해 풍차 옆에 있는 빈 단지를 살펴봐야 합니다.\n\n제공된 아이템: \n", description = "발견한 통을 살피던 중에 또 다른 양피지 문서를 발견했습니다. 여기에는 다음과 같이 적혀 있습니다. \"이제 여기에서 북쪽으로 가야 하오. 해안 절벽의 외딴 풍차 옆에 있는 빈 단지가 보일 때까지 곧장 가도록 하시오. 단지를 잘 살펴보면 단서를 발견할 수 있을 것이오.\"", progress = nil, completion = "자, 이제 횡재할 날이 멀지 않았소, 보물 사냥꾼 양반!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[140] = {title = "샌더 선장의 숨겨진 보물", objective = "보물을 얻기 위해 샌더 선장의 보물 상자를 찾아 열어야 합니다.\n\n제공된 아이템: \n", description = "그가 적어 놓은 대로, 낡은 단지 안 깊은 곳에 샌더의 보물에 대한 또 다른 단서가 들어 있습니다. 잉크를 쏟은 자국이 있고 종이에서는 위스키 냄새가 나지만 다음과 같은 내용을 읽을 수 있습니다. \"이제 내 위스키 단지를 찾았으니 보물도 거의 다 찾았다고 할 수 있소! 서쪽으로 간 다음 해변으로 내려가시오. 바다에 이르면 계속 앞으로 가시오! 보물 상자가 있는 섬이 보일 때까지 서쪽으로 계속 헤엄쳐 가시오.\"", progress = nil, completion = "낡은 상자의 경첩은 녹슬었지만 아직 제 구실을 하고 있습니다. 상자를 열고 보물을 얻습니다.\n\n축하합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n은괴샌더 선장의 셔츠샌더 선장의 장식띠샌더 선장의 전리품 자루"},
[141] = {title = "데피아즈단", objective = "서부 몰락지대의 그라이언 스타우트맨틀에게 쇼의 보고서를 가져가야 합니다.", description = "석공 길드는 에드윈 밴클리프라는 자가 운영하고 있네. 밴클리프는 첫 번째 전쟁 중 오크족이 파괴해 버린 스톰윈드의 재건을 책임졌던 인물이지. 재건 사업이 완료된 후, 밴클리프와 그의 동료는 자신들에 대한 왕의 대우에 강한 불만을 가지고 있었네. 이 사실만으로도 어느 정도 짐작이 가지.\n\n자세한 내용은 이 보고서에 썼으니 즉시 서부 몰락지대의 그라이언 스타우트맨틀 경께 전하게!", progress = "단장 마티아스 쇼가 뭔가 얘기해 주었나?", completion = "에드윈 밴클리프... 그 이름이라면 잘 알고 있지. 그렇게 부지런하고 똑똑한 자가 악당이 되어 버렸다니 참으로 당황스럽군. 흠, 몇 가지 더 증거를 얻기 전에는 믿을 수가 없을 것 같네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[142] = {title = "데피아즈단", objective = "서부 몰락지대에서 데피아즈단 전령을 추적하여 그가 전하려던 전갈을 스타우트맨틀에게 전해야 합니다.", description = "데피아즈단의 은신처가 어디인지 알아내야 하네. 우리 정찰병의 보고에 따르면 문브룩, 황금해안 채석장, 그리고 장고로드 광산 사이의 길에서 데피아즈단 전령이 지나가는 것을 목격했다고 하네. 귀관이 가서 놈을 좀 잡아 주게나. 놈이 저항할 경우 처치한 다음 놈이 전하려던 전갈을 내게 가져오게.", progress = "뭔가 정보를 얻었나? 데피아즈단 전령은 찾았고?", completion = "이건 밴클리프가 데피아즈단의 수장이라는 확실한 증거로군. 이제 그들의 은신처가 어디인지만 알아내면 되네.\n\n귀관이 부재 중인 동안 큰 수확이 있었다네. 살딘의 마차를 훔치려던 도적놈을 잡았는데, 놈을 살려 주는 대신 데피아즈단의 은신처로 우릴 안내해 주기로 했네. 놈이 은신처로 우리를 안내할 수 있도록 귀관이 데피아즈단 변절자를 좀 보호해 주게나. 그리고 은신처의 위치를 확인하는 즉시 내게 돌아오게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[143] = {title = "서부 몰락지대로의 전갈", objective = "집정관 솔로몬이 서부 몰락지대에 있는 그라이언 스타우트맨틀에게 자신이 직접 작성한 탄원서를 전달해 달라고 부탁했습니다.", description = "지금쯤이면 보급품이 도착하고도 남았을 텐데 스톰윈드 군대에 무슨 일이 일어난 것이 틀림없소. 어쨌든 우리에겐 더는 지체할 시간이 없소. 그냥 이대로 아무런 도움도 받지 못하고 레이크샤이어의 주민들이 죽는 것을 지켜보고 있을 수는 없소이다. 듣자하니 서부 몰락지대에서 백성의 민병대를 편성하고 있다고 하더군.\n\n자, 이 청원서를 민병대의 지휘관인 그라이언 스타우트맨틀 경께 전달해 주시오. 왕의 증원군이 도착할 때까지 스타우트맨틀 경의 병사들이 어느 정도 도움을 줄 수 있을 거요.", progress = "어서 오게나. 백성의 민병대에 무슨 일인가?", completion = "충실한 전령이여, 귀관은 우리 집정관님을 잘 보필하였군. 솔로몬의 뜻은 잘 알겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[144] = {title = "서부 몰락지대로의 전갈", objective = "그라이언 스타우트맨틀의 답장을 가지고 집정관 솔로몬에게 돌아가십시오.", description = "집정관 솔로몬의 청원서를 읽고 있으려니 마음이 무척 아프군. 하지만, 민병대는 자기 마을을 지키기 위해 소집된 것이라 서부 몰락지대가 아닌 다른 곳으로 파병까지 할 수는 없네. 애초에 민병대의 도움을 바란다는 것 자체가 무리한 요구지. 하기야 스톰윈드가 우리를 이렇게 버리지 않았다면 아예 민병대를 조직할 필요도 없었을 테지만 말일세.\n\n이 답장을 붉은마루 산맥의 솔로몬 집정관님께 전달하도록 하게. 그리고 상황이 이렇게 되어 매우 유감이라고도 전해 주게나.", progress = "그래, 백성의 민병대의 도움을 곧 받을 수 있을 것 같소? 스타우트맨틀 경에게서 좋은 소식을 얻어 왔소?", completion = "솔직히 정말 좋지 않은 소식이 아닐 수 없군. 스타우트맨틀 경의 상황도 이곳 레이크샤이어와 별다를 바 없다는 것을 몰랐소. 도대체 무엇이 그리 중요하기에 스톰윈드 군대는 스톰윈드 주민들을 모른 척한단 말인가? 휴, 이렇게 중얼거려 봐야 무슨 소용이 있겠소.\n\n자, 마을을 위해 전령 노릇을 하느라 고생했으니 이 돈을 받으시오. 그리고 아마 당신을 다시 부르게 될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[145] = {title = "다크샤이어로의 전갈", objective = "집정관 솔로몬이 다크샤이어에 있는 이본로크 경에게 탄원서를 전달해 달라고 부탁했습니다.", description = "염치없으나 다시 당신에게 도움을 청해야겠소. 이본로크 경에게 그늘숲의 정예 병력인 어둠의 순찰대를 파병하여 레이크샤이어의 방어를 도와 달라는 탄원서를 작성하였소. 무엇보다도 이 서신을 그에게 빨리 전달하는 것이 중요하오. 한순간이라도 긴장의 끈을 놓지 마시오. 이본로크 경은 그늘숲의 중심에 있는 다크샤이어라는 도시의 시장이오. 절대 길을 벗어나지 않도록 주의하시오.", progress = "먼길을 여행한 듯 보이오만, 이곳 다크샤이어에는 무슨 일인가?", completion = "이 먼 곳까지 오느라 수고가 많았군. 자네가 가지고 온 정보는 정말 중요한 정보군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[146] = {title = "다크샤이어로의 전갈", objective = "이본로크 경의 답장을 가지고 집정관 솔로몬에게 돌아가야 합니다.", description = "집정관 솔로몬과 개인적 친분이 없었다면 아마 그 사람을 미친 자로 생각했을 것일세. 스톰윈드가 도와 주지 않고 있으니 어둠의 순찰대를 레이크샤이어로 파병해 달라고? 어둠의 순찰대는 이 땅에 사악한 마법이 서서히 번지기 시작했을 때 스톰윈드가 우리를 버렸기에 조직된 것이야. 어둠의 순찰대를 파병한다면 순찰대원이 숲 가장자리에 도달하기도 전에 다크샤이어는 악의 구렁텅이에 빠질 걸세.\n\n이 답장을 레이크샤이어에 있는 집정관 솔로몬에게 전달해 주게나.", progress = "오, 다시 봐서 반갑군. 다크샤이어로부터 어둠의 순찰대가 오고 있다는 기쁜 소식을 치안대장에게 알려도 되겠소?", completion = "이런! 스톰윈드 군대가 서부 몰락지대에서 철수하고 경비대가 이제 다크샤이어를 지켜주지 않는다는 말인가? 분명 어디선가 반역 행위가 이루어지고 있는 것이 분명하오. 어떻게 이럴 수 있단 말인가? \n\n아, 보상을 주는 것을 잊을 뻔했군. 자, 이 돈을 받으시오. 스톰윈드에서 뭔가 벌어지고 있는 것 같은데 무슨 일인지 파헤쳐 봐야겠으니 이만 실례하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[147] = {title = "징세관 수사", objective = "징세관을 찾아서 처치한 다음 징세관의 반지를 가지고 치안대장 더그한에게 돌아가야 합니다.", description = "소위 말하는 징세관이라는 자가 우리 금광에서 황금을 가져가고 있다면 그건 왕국의 재산을 훔치는 행위가 되는 것이오! 정의의 이름으로 징세관을 처단하고 당신이 준 수금 일정표에 적혀 있는 반지를 가져오시오. 징세관이 누구를 위해서 일하는지 밝히는 데 도움이 될 수도 있으니까...\n\n이 수금 일정표에 의하면 징세관은 브랙웰 호박밭에 숨어 있다고 하니 그곳에서 찾아보도록 하시오.", progress = "징세관을 찾았소? 누구를 위해 일하는 자인지 밝혀냈소?", completion = "징세관을 찾았소? 잘했소이다. 이제 다시는 엘윈 근처의 광산에서 허튼 짓을 하지 못하게 되었군!\n\n그리고 당신이 발견한 이 반지 말인데... 흥미롭군. 이건 스톰윈드에 있는 오래된 석공 길드 회원 반지오. 어떻게 이런 좀도둑 같은 자가 장인 길드의 반지를 가지고 있었으며, 데피아즈단 도적들이 우리 광산에서 황금을 가져가는 이유는 무엇일까?\n\n어려운 문제가 아닐 수 없소. 언젠간 이 문제의 해답을 찾을 수 있을 거라 믿소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n스톰윈드 사슬 장갑손목 밴드\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[148] = {title = "다크샤이어로부터의 보급품", objective = "에바 부인과 대화해야 합니다.", description = "오, 이 불쌍한 늙은이는 이제 어쩌란 말인가? 다크샤이어에서 보급품을 가져와야 하는데 마을은 너무 멀고 난 기력이 없으니, 아마 절대 마을까지 가지 못할 걸세.\n\n자네가 다크샤이어로 가서 유령의 머리 가닥을 좀 가져다주겠나? 다크샤이어 광장에 있는 에바 부인의 집으로 가면 얻을 수 있을 걸세.", progress = nil, completion = "오, 그래. 유령의 머리 가닥이 필요하다고? 지금은 가지고 있는 게 없는데... 하지만 유령의 머리카락을 구해 온다면 만들어 줄 수는 있지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[149] = {title = "유령의 머리 가닥", objective = "눈 먼 매리에게 유령의 빗을 가져가야 합니다.", description = "다크샤이어 남쪽 언덕에 있는 오래된 농가에는 불쌍하게 죽어 영혼이 된 눈 먼 매리가 나타나곤 한다네.\n\n자, 여기 이 유령의 빗을 가지고 가서 눈 먼 매리에게 머리카락을 좀 빗어 보라고 해보게. 그런 다음 빗을 내게 다시 가지고 오면 머리 가닥을 만들 유령 머리카락을 얻을 수 있네.\n\n아, 요즘 농가 주변을 어슬렁거리는 사악한 녀석들을 조심하도록 하시게.", progress = "<흐느끼며> 제발 날 쳐다보지 마요! 이 손으로 두 눈을 때내 버려서 앞을 볼 순 없지만 당신이 쳐다보고 있다는 걸 느낄 순 있어요.\n\n난... 나는 흉측해요! 제발 쳐다보지 마요!", completion = "이게 뭐죠? 빗인가요? 아! 너무 예쁘군요. 뻣뻣하게 굳어 윤기 없는 내 머리카락을 이렇게 부드럽게 빗어 내리다니...\n\n아! 거울만 있었더라면...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[150] = {title = "침입자 멀록", objective = "레이크샤이어에 있는 항구주임 바렌에게 멀록 지느러미 8개를 가져가야 합니다.", description = "요즘 멀록이 여간 골칫거리가 아니랍니다. 이 대규모의 물고기 인간 집단이 영원의 호수 기슭에 정착하여 물고기를 떼거리로 잡아내고 있어요! 저들이 호수에 있는 모든 물고기를 다 잡아먹기 전에 쫓아내야 합니다!\n\n멀록을 사냥해 주십시오! 멀록 지느러미를 8개 가져다주면 보상해 드리도록 하죠.", progress = "지느러미를 가지고 왔나요? 서둘러 주세요, 멀록을 호수에서 쫓아내야 하니까요!", completion = "잘하셨습니다. 멀록을 해치우느라 너무 고생하신 건 아닌가요?\n\n그런데 바다와 이만큼이나 먼 곳에서 멀록이 출현하다니 심상치가 않군요. 혹시 무언가에 쫓겨서 이곳으로 도망쳐 온 것은 아닌가 싶네요...", rewards = "다음과 같은 것들을 받습니다:\n\n드워프 작살총"},
[151] = {title = "늙은말 블랑쉬", objective = "서부 몰락지대의 베르나 펄브로우가 귀리 한 줌 8개를 가져다 달라고 부탁했습니다.", description = "늙은말 블랑쉬! 우리를 위해 일하느라 너무 지쳐버린 불쌍한 짐승이죠. 우리가 농장을 떠나오기 전까지는 제가 길렀지만 이제는 마차가 부서져서 정말 기르기가 힘겹군요. 그래서 말인데 귀리를 좀 구해서 불쌍한 블랑쉬에게 가져다주시면 정말 고맙겠어요.\n\n아마 서부 몰락지대의 모든 농장 주위에서 귀리 부대를 발견할 수 있을 거예요. 저 끔찍한 기계들만 어떻게 할 수 있다면 말이죠. 이곳의 남서쪽에 여러 개의 농장이 있으니 그곳들을 찾아 보세요.", progress = "우리 블랑쉬가 죽어가고 있어요. 블랑쉬에게 먹일 귀리를 찾았나요?", completion = "너무 감사해요! 블랑쉬가 무척 좋아할 거예요!", rewards = "다음과 같은 것들을 받습니다:\n\n늙은 블랑쉬의 모포늙은말 블랑쉬의 사료 주머니"},
[152] = {title = "남아 있는 위험", objective = "멀록 바다사냥꾼 7마리, 멀록 전사 7마리, 멀록 점쟁이 7마리, 멀록 길잡이 7마리를 처치하고 서부 몰락지대 등대에 있는 그레이슨 선장에게 돌아가야 합니다.", description = "그대도 아마 위험천만한 대해에서 희생되어 해안에 침몰한 난파선을 본 적이 있을 것이오. 선원들이 이 해변에 안전하게 정박할 수 있도록 서부 몰락지대의 해안에서 위험을 제거해야 하오. 바로 멀록이 문제인데...\n\n멀록 바다사냥꾼 7마리, 전사 7마리, 점쟁이 7마리와 길잡이 7마리를 처치해 준다면 내 반드시 보상하도록 하겠소.", progress = "바다사냥꾼 7마리, 전사 7마리, 점쟁이 7마리, 길잡이 7마리를 처치해 준다면 내 반드시 보상하겠소.", completion = "잘했소. 그대의 전투 능력은 정말 탁월하군. 서부 몰락지대의 해안을 안전하게 정리해 준 것에 대해 깊이 감사하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[153] = {title = "붉은 가죽 복면", objective = "감시의 언덕의 정찰병 갈리안에게 붉은 가죽 복면 15개를 가져가야 합니다.", description = "데피아즈단 전방부대가 계속 이동 중에 있습니다. 나는 오랫동안 놈들의 움직임을 추적해 오면서, 이 패거리들이 붉은 가죽 복면을 쓰고 있기 때문에 복면을 쓴 자들만 뒤쫓으면 추적이 가능하다는 사실을 알아냈습니다.\n\n내게 그 붉은 가죽 복면 15개를 가져오면 반드시 보상을 받을 수 있도록 해 드리겠습니다.", progress = "붉은 가죽 복면 15개를 가져오면 충분히 보상하겠습니다.", completion = "훌륭합니다! 자, 수고에 대한 대가로 이 중 하나를 받아 주십시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n백성의 민병대 망토백성의 민병대 경갑백성의 민병대 다리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[154] = {title = "유령의 빗 돌려주기", objective = "다크샤이어의 에바 부인에게 유령의 머리빗을 다시 가져가야 합니다.", description = "싫어!!!!!\n\n자, 이 빗을 가지고 어서 가버려요!\n\n난 괴물일 뿐이야. 누구도 다시는 날 아름답다고 생각하지 않을 거야!", progress = "그대에게서 눈 먼 매리의 기운이 느껴지는 군. 그래, 빗은 도로 가져왔고...?", completion = "이거면 유령의 머리 가닥을 한 묶음 만들고 여분으로 좀 남겨둘 수도 있겠군. 자, 이건 여분의 머리 가닥 값일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[155] = {title = "데피아즈단", objective = "데피아즈단의 비밀 은신처까지 데피아즈단 변절자를 호위해 가야 합니다. 데피아즈단의 변절자가 밴클리프와 그의 동료가 숨어 있는 곳까지 안내한 이후에 그라이언 스타우트맨틀에게 돌아가 그 위치를 알려야 합니다.", description = "그래, 스타우트맨틀이 나를 보호한답시고 당신 같이 허약한 <race>|1을;를; 보냈단 말이지? 쳇, 당신 잘하는 게 좋을 거요. 보아하니 친구들도 좀 더 부르는 게 좋을 거 같군.\n\n우리 거래에 대해서는 잘 알고 있겠지? 당신은 나를 지켜 주고, 나는 데피아즈단의 은신처로 당신을 안내하고. 데피아즈단이 내 목을 노리고 있으니 내게서 잠시라도 한눈팔면 안 되오, 명심하라고! 그들이 내가 당신과 같이 있는 걸 본다면 날 죽이려 들거요.\n\n당신과 친구들이 준비되면 알려 주시오.", progress = nil, completion = "정말 훌륭하네! 놈이 숨어 있는 곳을 알아냈으니 이제 밴클리프는 잡은 거나 다름없군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[156] = {title = "시든 꽃 모으기", objective = "시든 꽃 8송이를 모아 다크샤이어의 선술집주인 스미츠에게 가져가야 합니다.", description = "제게 시든 꽃을 가져다주시면 좀비 독주를 한 병 만들어 드리겠습니다.\n\n시든 꽃은 낯선 곳에서 자란답니다. 뭐, 손님께서 소문대로 용감하시다면 해골 병사와 해골 악령의 두개골 속에 있는 걸 구해올 수 있겠지만... 어휴, 전 무서워서 감히 쳐다볼 수도 없었습니다요!\n\n까마귀 언덕 묘지와 고요의 정원 묘지에 가시면 그 기분 나쁜 해골들이 우글대고 있을 겁니다. 놈들을 처치하면 시든 꽃을 얻을 수 있을 겁니다. 그리해 주시면 다크샤이어 마을에서도 고마워할 겁니다요.", progress = "어서 오세요. 자, 시든 꽃들은 다 구하셨나요?", completion = "시든 꽃을 구해 오셨군요, 좋습니다. 어둠의 순찰대의 알시아 이본로크 사령관님께 손님께서 해골 녀석들을 처치했다고 전하도록 합죠.\n\n다크샤이어 주민들을 안전하게 지키는 것이 어둠의 순찰대의 임무이니 시민의 도움으로 그늘숲의 해골의 수가 줄었다는 건 정말 반가운 소식일 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[157] = {title = "머리 가닥 전달", objective = "까마귀 언덕 묘지 북쪽의 통나무집에 있는 에이버크롬비에게 유령의 머리 가닥을 가져가야 합니다.", description = "자, 여기 머리 가닥일세. 이 머리 가닥은 사악한 영혼들을 묶어 버릴 수도 있고, 생명이 소실된 물체에 소생의 기운을 불어넣고 봉할 수도 있어서 아주 쓸모가 많지.", progress = "저 달갑지 않은 것들이 들어오지 못하게 막으려면 유령의 머리 가닥을 문과 창문에 매달아야 해. 유령의 머리 가닥은 가져왔나?", completion = "정말 기쁘군! 이거면 충분하겠어.\n\n부탁한 일을 잘해 줬으니 보상을 받는 건 당연하지 않겠나. 자, 이걸 받게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[158] = {title = "좀비 독주", objective = "선술집주인 스미츠와 대화해야 합니다.", description = "이제 특별한 술 한 병이 필요한데... 바로 좀비 독주라는 술이지. 다크샤이어의 진홍 까마귀 선술집주인 스미츠가 좀 가지고 있을 걸세.\n\n서두르게나. 밤 공기가 점점 차가워지고 있어. 난 그 술로 몸을 녹이지 않으면 안 된다네!", progress = nil, completion = "좀비 독주가 필요하다고요? 흠, 정말 독한 술이지요. 전 평소 이 술은 잘 안 마신답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[159] = {title = "좀비 독주 배달", objective = "통나무집에 있는 에이버크롬비에게 좀비 독주를 가져가야 합니다.", description = "자, 여기 좀비 독주입니다...\n\n...그리고 노파심에서 드리는 말입니다만 이 술 조심하세요. 워낙 강해서 죽은 자들을 되살릴 수도 있을 정도니까 말입니다.", progress = "이 춥고 어두운 밤을 견디려면 좀비 독주가 필요하네. 술은 가져왔나?", completion = "정말 고맙네. 흐흐, 자네의 바보 짓, 아... 아니 그러니까, 친절 덕분에 이 늙은이가 가슴을 녹일 수 있겠군.\n\n자, 내 감사의 표시로 이걸 받게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[160] = {title = "시장에게 보내는 편지", objective = "다크샤이어의 시장 엘로 이본로크 경에게 엘로에게 보내는 편지를 전해야 합니다.", description = "이 편지를 다크샤이어의 시장인 엘로 이본로크에게 전하게.\n\n그와는 오랜 친구 사이지... 아, 그리고 이 편지를 전하면 자네가 날 위해 해준 일에 대해 나만큼 이나 기뻐할 거야. 하하하하!", progress = "에이버크롬비...? 그런 이름은 처음 듣는데. 그 에이버크롬비라는 자가 내게 편지를 전하라고 했다고?\n\n어디 그 편지나 한번 보세나...", completion = "&lt;편지를 읽는 엘로&gt;\n\n이건 대체 뭐라고 쓴 건가? 고대 문자인 것 같은데... 난 도통 읽을 수가 없군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[161] = {title = "어둠의 전조", objective = "선임기술자 힌더바이르가 이상한 향기의 가루를 던 모드르에 있는 폭파 전문가 애실런 스톤스머크에게 전달해 달라고 부탁했습니다.", description = "내 느낌이 맞다면 이건 일종의 폭약 가루인 것 같군. 무엇인지 확실히 알아내려면 폭파 전문가에게 분석을 맡겨야 하네. 애실런 스톤스머크라는 폭파 전문가가 던 모드르와 탄돌 교각을 방어하는 연대에 배치되어 있네. 아무래도 당신이 이 중대한 임무를 맡아 어려운 여행을 해줘야 할 것 같아.\n\n알가즈 관문을 통과한 다음 저습지를 가로지르는 길을 따라가 던 모드르에서 스톤스머크를 찾아보게. 내 충고를 명심해야 해. 반드시 길을 따라가야 하고 무슨 일이 있어도 멈추지 마!", progress = "뭐라고? 윙윙거리는 소리 때문에 하나도 안 들려서 말이야. 크게 말해 보라고, 그런데 그건 대체 뭐지?", completion = "이럴 수가! 힌더바이르가 걱정할 만도 하군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[162] = {title = "실리시드의 출현", objective = "다르나서스에 있는 그라시나 스피릿마이트에게 곤충 분석 보고서를 가져가야 합니다.", description = "이 보고서는 이런 일에 대해 잘 아는 사람에게 가져다주는 게 좋겠소.\n\n그라시나 스피릿마이트라는 나이트 엘프 학자를 알고 있는데 그녀는 아제로스 생태계의 생물들을 연구하며 많은 시간을 보내고 있소. 게다가 역사학에도 해박하지. 이 위협이 정확히 무엇인지 알아내고 또 이걸 막을 수 있는 방법을 알아내려면 그녀에게 이 보고서를 가져가 도움을 청하시오.\n\n내가 마지막으로 들은 소식으로는, 다르나서스에 있는 달의 신전에 산다고 합디다.", progress = "낯선 이방인에게 평화와 고요가 함께하기를... 오늘 저를 찾아오신 이유가 무엇인가요?", completion = "이 보고서... 우리 나이트 엘프들은 여기에 적힌 두려운 존재들에 대해 잘 알고 있어요. 피즐도저가 이 보고서를 내게 보낸 건 참으로 현명한 일이었어요.\n\n이 생물들은 빠른 속도로 타나리스 사막을 모조리 집어삼키고 말 거예요. 우리가 맞선 가장 큰 위협 중 하나인 것은 분명해요. 이 생물들의 이름을 잘 기억해 두세요. 실리시드라고 부릅니다. 이들은 호드와 얼라이언스 모두에게 가장 큰 위협이 되는 생물 중 하나입니다.\n\n우리가 그것을 미리 내다볼 수 있었다면 좋았을 것을...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[163] = {title = "까마귀 언덕", objective = "까마귀 언덕에 출몰하는 것이 무엇인지 확인해야 합니다.", description = "까마귀 언덕에서 뭔가 심상치 않은 일이 벌어지고 있습니다. 칼로는 그곳 건물에서 뭔가가 출몰하고 있다고 믿고 있답니다. 며칠 전엔 늦은 밤 창문에서 불빛을 보았다고 하고 이틀 연속으로 그림자가 움직이는 걸 목격했다고 하더군요. \n\n그늘숲의 안전을 걱정하는 분이라면, 까마귀 언덕에서 출몰하는 것이 어떤 괴물인지 확인해 주시기 바랍니다.", progress = nil, completion = "안 돼! 제발 해치지 마세요! 납니다, 지터스라고요! 사방에 놈들이 깔려 있어요. 으, 난 절대 놈들에게서 도망칠 수 없을 거예요! 내가 까마귀 언덕의 괴물이라고요? 아...아...아니에요. 나...난 선량한 지터스라고요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[164] = {title = "스벤에게 보급품 전달", objective = "스벤에게 보급품을 가져가야 합니다.", description = "스벤을 알고 있나요? 그는 정의를 위해 일하고 있는 사람이죠! 그와 그의 수행원이 그늘숲 북서쪽 변방에 야영지를 설치하고 지내고 있답니다.\n\n그런데 안타깝게도 워낙 소수의 인원이다 보니 보급품을 가지러 마을에 사람을 보낼 여력이 없답니다. 그에게 보급품을 전해주시겠어요?", progress = "오, 아주 강한 <class>인 것 같군요. 우리와 함께 싸우러 왔습니까?", completion = "이런, 카레빈 가에서 보낸 보급품이로군요. 안 그래도 보급품이 부족했는데 정말 다행입니다. 한결같은 카레빈 가의 지원에 감사할 따름입니다. 이게 수고해준 당신에게 조금이나마 도움이 되면 좋겠네요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[165] = {title = "은둔자", objective = "까마귀 언덕 묘지 근처 통나무집에 있는 노인이 잘 있는지 확인해야 합니다.", description = "종종 필요한 물건을 사러 마을에 오는 노인이 있었는데 한동안 보지 못해서 무슨 일이 있는 건 아닌지 걱정이에요. 내 기억이 맞다면 그 노인은 까마귀 언덕 공동 묘지가 내려다보이는 통나무집에 살고 있을 거예요. 가서 노인이 무사한 지 확인해 주세요.", progress = nil, completion = "일레인 카레빈이 보냈다고 했나? 허허, 그럼 그렇지. 이렇게 날 신경 써 주는 사람은 물론 카레빈밖에 없지. 아니, 아무 일도 없네. 하지만, 이제 마을에 내려가기가 너무 힘들어서 걱정일세. 길은 위험하고 몸이 노쇠해서 말을 듣지 않으니 어떻게 내려가겠나. 그래서 말인데 자네가 내 부탁 좀 들어주겠나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[166] = {title = "데피아즈단", objective = "에드윈 밴클리프를 처치하고 그 증거로 그의 가면을 그라이언 스타우트맨틀에게 가져가야 합니다.", description = "귀관이 완수해야 할 일이 하나 더 남아있네. 백성의 민병대의 이름으로 에드윈 밴클리프를 처단해야만 하네. 누군가에게 사형을 선고해야 한다는 것이 무척 가슴 아프지만, 서부 몰락지대 주민의 안녕이라는 더 큰 대의를 위해서 밴클리프는 영원히 잠재울 수밖에 없네. 놈을 처치한 후 놈이 신분을 숨기기 위해 사용하던 가면을 가져오게.", progress = "에드윈 밴클리프 암살은 어떻게 돼 가고 있나?", completion = "귀관의 용기는 실로 놀랍군. 백성의 민병대는 서부 몰락지대 주민을 위한 귀관의 노고에 감사하고 있네. 밴클리프를 처치했으니 이제 데피아즈 결사단 소탕의 시작을 알리는 것일세. 곧 이 아름다운 땅에 다시 평화가 찾아오게 될 걸세.\n\n귀관에게 경의를 표하네!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n서부 몰락지대 다리보호구서부 몰락지대 튜닉서부 몰락지대 지팡이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[167] = {title = "형제여...", objective = "스톰윈드에 있는 빌더 시슬네틀에게 시슬네틀의 배지를 가져가야 합니다.", description = "우리는 서부 몰락지대에 문브룩 헛간 밑에 숨겨진 거대한 광산 깊은 곳에 있었지. 그 고약한 데피아즈단 약탈자 놈들이 어디에서 왔는지 도무지 알 길이 없었소. 그건 그렇고, 우리 형제는 갱도가 무너져 광산에 갇히게 되었소. 나는 가까스로 탈출했지만 다른 사람들은... 그 후로 다른 사람들 소식을 들을 수 없었소.\n\n보아하니 당신 운이 좋은 자인 것 같은데... 우리 형을 찾아봐 준다면 정말 고맙겠소이다. 우리 형은 항상 탐험가의 조합 배지를 지니고 다녔소. 형을 찾을 순 없어도 그 배지라도 있다면 조금이나마 위안이 될 것 같소.", progress = "우리 형에 대해서 무슨 표시라도 찾았소이까? 형이 아직 살아 있을 가망이 조금이라도 있는 거요?", completion = "역시 우려하던 대로구려. 불쌍한 우리 형... 나쁜 소식이긴 하지만 어쨌든 형에 대한 소식을 알아봐 줘서 고맙소이다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n광부의 곡괭이"},
[168] = {title = "기억을 더듬어...", objective = "스톰윈드에 있는 빌더 시슬네틀에게 광부 조합의 명함 4장을 가져가야 합니다.", description = "갱도가 무너지던 그 악몽 같던 날, 내 친구들이 많이 죽었소이다. 여행 중에 혹시 문브룩의 갱도를 지나게 된다면 그들을 확인할 수 있는 소지품이 있는지 살펴봐 주시겠소? 그리고 광부 조합의 명함을 하나라도 찾게 된다면, 그들의 가족에게 그 끔찍한 사고를 해명할 수 있도록 내게 가져다주시기 바라오.", progress = "내 옛 동료들의 광부 조합의 명함을 찾았소이까?", completion = "정말 고맙소이다. 당신이 수고해 준 덕분에 비명에 간 내 동료들도 이제 편히 잠들 수 있을 것이오. 이 명함들은 그들 가족에게 잘 전하도록 하겠소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n채굴꾼 장화잿빛 채광용 장갑\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[169] = {title = "가스일조그 현상수배", objective = "가스일조그를 처치하고 그 증거로 그의 머리카락을 레이크샤이어에 있는 집정관 솔로몬에게 가져가십시오. 보상을 받을 수 있을 것입니다.", description = "현상수배를 내린다! 검은바위부족의 우두머리인 가스일조그가 돌망루 요새를 공격하고 레이크샤이어의 마을 회관을 습격하고 있다.\n\n가스일조그는 매우 위험한 인물로서 보고에 의하면, 최근 정복한 요새에 머물면서 다음 공격을 준비하고 있다고 한다. 무슨 수를 써서라도 검은바위 오크의 침략을 막아야 한다. 가스일조그를 처치하고 그 증거를 집정관 솔로몬에게 가져오는 용감한 자에게는 엄청난 보상이 주어질 것이다.", progress = "당신 손에 든 것이 무엇이오?", completion = "정말 대단하군! 가스일조그는 저 짐승 같은 오크들을 이끌고 쳐들어와 무고한 사람들을 수없이 죽였소. 이로써 복수가 이루어진 셈이군. 이번에 당신이 거둔 성과로 인해 스톰윈드 왕국은 그들의 요새를 탈환하는 첫 번째 발걸음을 내딛게 되었소!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[170] = {title = "새로운 위협", objective = "발리르 프로스트해머가 바위턱트로그 6마리와 힘센 바위턱트로그 6마리를 처치해 달라고 부탁했습니다.", description = "우리를 좀 도와 주실 수 있으신가요? 지난번 트로그가 습격한 이후로 경비대의 인원이 부족해서 말입니다. 우릴 도울 생각이 있는 자라면 누구든 대환영입니다.\n\n요즘엔 망할 놈의 트로그들이 사방팔방에서 나타나고 있다던데 여기 눈마루 골짜기도 예외는 아닙니다. 트로그는 주로 남동쪽 언덕 근처나 얼어붙은 호수 근방에 출몰하고 있습니다.\n\n그뿐만이 아닙니다. 며칠 전엔 서쪽에 있는 야영지까지 습격했다고 하더군요... 지금 우리만으론 역부족이니 트로그놈들을 좀 처치해 주시겠습니까?", progress = nil, completion = "여기에서 우리가 겪고 있는 문제를 왕국의 다른 지역에서도 겪게 될 것이라면 이건 정말 큰일입니다. 국왕 폐하와 원로원의 의원들이 트로그 문제를 처리할 방안을 모색하고 있기를 바랄 수밖에...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n곰가죽 망토투박한 허리띠방수 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[172] = {title = "어린이 주간", objective = "오크 고아 호루라기를 사용해 어린이 주간에 돌볼 아이와 대화하십시오.\n\n제공된 아이템: \n", description = "여기 보육원 일을 돕고 싶으시다고요? 어린이 주간 동안 저희를 도와주신다면 너무 감사할 거예요. 당신에게 신의 축복이 있기를!\n\n이 호루라기를 받으세요. 이것은 짧은 시간, 그러니까 어린이 주간에만 사용할 수 있어요. 호루라기를 한 번 불면 당신이 돌돌 아이와 얘기를 나눌 수 있고 한 번 더 불면 그 아이를 보낼 수 있죠.\n\n부디 이 호루라기를 불어 당신이 돌볼 아이를 만나보세요! 우리 아이가 당신의 온정을 기다리고 있으니까요.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[173] = {title = "숲 속의 늑대인간", objective = "다크샤이어의 칼로를 위해 파멸의어둠일족 흑마술사 6마리를 처치해야 합니다.", description = "그늘숲에 피할 수 없는 암흑이 드리워지고 있는 것 같습니다. 대장 카레빈님의 임무는 이단과 악의 세력을 몰아내는 것입니다. 우리의 노력으로 다크샤이어 주민들이 안전하게 지낼 수 있는 것이랍니다.\n\n우리 임무에 동참할 수 있겠습니까?\n\n나도 예전에 당신과 같은 생각을 했었습니다. 어둠의 순찰대의 그 알량한 자기 도취에 환멸을 느꼈었기에 대장 카레빈님과 함께하기로 했습니다. 우리 임무에 동참할 생각이라면 말만 앞세워서는 안 될 겁니다.\n\n밝은숲이라고? 하! 말도 안 돼, 그런 곳을 밝다고 부르다니! 아무튼 그곳과 오염된 과수원에 있는 파멸의어둠일족 흑마술사를 상대로 당신 실력을 한번 증명해 보시기 바랍니다.", progress = nil, completion = "놀랍군요. 당신 실력은 충분한 것 같습니다. 아무래도 당신 능력에 맞는 더 적당한 임무를 찾아보는 게 좋겠군요.\n\n참 이상하단 말입니다... 늑대인간들이 어디서 이렇게 갑자기 나타났는지... 다른 이상한 괴물들도 우리 지역에 자꾸 나타나는 걸 보면 이건 시작에 불과한 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[174] = {title = "별 관측", objective = "다크샤이어의 빅토리 프리즘안트라스가 청동관을 가져다 달라고 부탁했습니다.", description = "나는 나의 노움 친구 코그가 별을 관측하는 장치를 만드는 작업을 도와 주기로 했다오. 이 장치가 완성되면 숲 속에서 일어나고 있는 심상치 않은 변화를 설명해 줄 진실을 알아낼 수 있을 것이오.\n\n코그의 설계도에 따르면 숙련된 기술자가 만든 청동관이 첫 번째 재료라고 하오. 내게 청동관을 하나 가져다주시오.", progress = "청동관을 만들어 줄 숙련된 기술자를 벌써 찾았소?", completion = "그래, 바로 이것이오. 이제 첫 단계는 완료한 셈이군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[175] = {title = "별 관측", objective = "매리를 찾아 빅토리의 작업에 사용할 반사면을 빌려 와야 합니다.", description = "코그의 설계도에 따르면 이번엔 빛을 반사하는 물건이 필요하오. 아, 늘 거울을 가지고 다니는 것으로 유명한 매리라는 여인이 생각나는구려. 당신이 매리를 찾아 이번 작업에 쓸 반사면을 빌려 줄 수 있는지 알아봐 주시겠소? 예전엔 그녀가 그늘숲 남쪽에 살았던 것으로 기억하오만...", progress = nil, completion = "예, 그래요. 전에는 내가 거울을 하나 가지고 있었죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[176] = {title = "들창코 현상수배", objective = "들창코라는 놀을 처치하고 치안대장 더그한에게 그 놀의 큰 발톱을 가져가야 합니다.", description = "들창코 현상수배:\n\n엘윈 남서쪽 숲에서 돌아다니고 있는 거대한 놀 들창코를 포획하려는 시도가 모두 수포로 돌아갔다.\n\n이에 스톰윈드 군대는 이 놀의 목에 상당한 현상금을 걸고 수배하는 바이다. 보상금을 원하는 현상금 사냥꾼은 들창코의 죽음을 증명할 수 있는 증거물을 골드샤이어의 치안대장 더그한에게 제출해야 한다.", progress = "그렇소, 들창코는 나와 내 병사들에게 상당한 골칫거리지. 그 짐승에 대해 보고할 내용이 있소?", completion = "하하! 잘했소! 아무도 이 괴물을 처치할 수 없는 건 아닌가 하는 생각이 슬슬 들고 있었소!\n\n자, 이걸 받으시오, 그리고 고맙소이다. 그 놀이 얼마나 골치를 썩였는지 상상도 못할 거요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n보병대 제복스톰윈드 경비병의 다리보호구다듬어진 전투봉\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[177] = {title = "별 관측", objective = "광기어린 구울에게서 매리의 거울을 찾아 다크샤이어에 빅토리 프리즘안트라스에게 가져가야 합니다.", description = "그 사건이... 일어나기 전까지, 그 거울은 나의 가장 귀중한 보물 중 하나였죠. 하지만 그 일이 있은 후 거울을 헛간 뒤에 버렸어요. 그곳을 어슬렁거리던 광기 어린 구울이 있었는데, 아마 그가 그 거울을 주워 갔을 거예요. 소문을 듣자하니 그 악마 같은 구울은 고요의 정원 묘지에 산다더군요.", progress = "코그에게 우리의 별 관측 기계의 제작 과정을 보여 주었소. 시작 단계일 뿐이지만 꽤 인상적이었던 모양이오. 그건 그렇고, 반사면은 찾았소?", completion = "정말 훌륭하오! 이거면 완벽할 거요. 고맙소이다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[178] = {title = "테오크리투스의 역공", objective = "마법사 테오크리투스에게 잿빛가죽 놀의 빛바랜 펜던트를 가져가야 합니다.", description = "<허공에서 들리는 목소리...>\n\n놀라지 말게. 나는 엘윈 숲에 있는 아조라의 탑의 고위 마법사, 테오크리투스일세. 자네가 가지고 있는 그 펜던트는 잿빛가죽놀과 그들의 수장인 모건스와 교신하는 수단이지.\n\n수개월 동안 연구한 끝에 나도 그 펜던트를 통해 교신하는 방법을 알아냈지. 자네가 내 목소리를 들을 수 있다면 내 주문이 성공한 것일 게야.\n\n그 펜던트를 내게 가지고 오면 보상해 주겠네.", progress = "펜던트를 통해 내 말을 들었다고? 음... 그 펜던트를 내게 주게. 자세히 조사해 봐야겠어.", completion = "고맙네. 몇 주 전에 잿빛가죽일족 펜던트를 통해 교신을 보냈는데 아무 반응이 없기에 내심 실패한 것으로 생각하고 있었네. 그나마 교신을 보낸 지 한참 지나서야 몇몇 펜던트에 주문이 통한 모양이군.\n\n이제는 이 펜던트를 착용하고 있는 모든 잿빛가죽놀을 무력화시키고 타격을 줄 수 있는 방법을 알아내고자 하네.\n\n그러려면 훨씬 더 많이 연구해야 하지 않을까 싶군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n회복의 항유"},
[179] = {title = "드워프 장갑", objective = "스텐 스타우트암이 질긴 늑대 고기 8조각을 구해 달라고 부탁했습니다.", description = "만나서 반갑네. 흠, 그런데 자세히 보니 손이 좀 추워 보이는군. 따뜻하게 해줄 게 필요하겠어.\n\n어디 보자. 그래, 따뜻한 장갑이 좋겠군. 내가 이런 일은 그냥 못 지나치는 성미라서 말이야. 자네 두 손에 꼭 맞는 장갑을 만들어 주겠네. 단 한 가지 조건이 있어.\n\n늑대 고기를 좀 구해다 주겠나? 그러면 동상 따윈 절대 걸리지 않을 따뜻한 장갑을 만들어 줌세. 어떤가?", progress = "늑대 사냥이 생각보다 쉽진 않지? 날카로운 송곳니와 발톱만 잘 피하면 훨씬 수월할 거야.", completion = "오! 훌륭하군. 이거면 정말 맛있는 요리를 만들 수 있겠어. 하하하, 걱정하지 말게. 내가 약속을 잊을 리가 있겠나? 자, 여기 있네. 자네 손에 아주 잘 맞을 거야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n토끼 사육사 장갑늑대 조련사 장갑곰 조련사 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[180] = {title = "부대장 붉은송곳니 현상수배", objective = "부대장 붉은송곳니를 처치한 후 그의 앞발을 가지고 레이크샤이어의 집정관 솔로몬에게 돌아가야 합니다.", description = "현상수배: 부대장 붉은송곳니\n\n부대장 붉은송곳니는 마을과 왕국의 적인 모건스를 위해 일하고 있으며 잿빛가죽놀의 우두머리로 알려져 있다. 집정관 솔로몬의 명에 따라 스톰윈드를 배반한 놀의 목에 현상금을 거는 바이다. 현상금을 원하는 자는 붉은송곳니의 앞발을 집정관에게 증거로 제출해야 한다.", progress = "마을 회관에 어떤 소식을 가지고 온 것이오?", completion = "그러니까 그 사악한 부대장 붉은송곳니가 죽었단 말이오? 거참 속이 다 시원하군그래. &lt;class&gt;, 용기가 대단하군. 레이크샤이어의 마을 회관을 대표하여 도움에 감사하는 바이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[181] = {title = "별 관측", objective = "그늘숲 남쪽의 오우거 언덕에서 짜르크불을 찾아 오우거의 외눈안경을 다크샤이어에 있는 빅토리에게 가져와야 합니다.", description = "이제 한 가지 재료만 더 있으면 장치가 완성되는군. 코그의 설계도에 따르면 마지막 재료로 렌즈 같은 것이 필요하다고 쓰여있소. 장치에 사용할 만큼 큰 렌즈를 하나 알고 있긴 한데, 손에 넣기가 쉽지 않을 것이오.\n\n그늘숲 남쪽에 있는 언덕에 짜르크불이라는 오우거가 살고 있다오. 짜르크불이 쓰고 있는 외눈안경을 렌즈로 사용하면 될 거 같은데... 내게 좀 가져다주지 않겠소?", progress = "짜르크불에게서 실험에 쓸 외눈안경을 가져 왔소?", completion = "오! 결국 구해 왔구려. 드디어 별을 관측하는 기계가 완성됐소! 고맙소, 이제 연구를 계속할 수 있겠소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n별자리 장갑별빛 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[182] = {title = "트롤 동굴", objective = "그렐린 화이트비어드가 어린 서리갈기트롤 14마리를 처치해 달라고 부탁했습니다.", description = "나는 우리 형 세니르와 최근 던 모로에 위협이 되고 있는 트롤 문제를 조사하기 위해 파견 나왔습니다. 원로원은 이미 트로그 문제로 골치를 앓고 있어서 다른 일에 신경 쓸 겨를이 없다는군요.\n\n조사해본 바로는 트롤이 눈마루 골짜기 보다 남쪽에 있는 동굴 부근에 더 많이 출몰하는 것 같습니다. 이번 임무는 부대를 동원해야 할 정도는 아니고 당신같이 용감한 <race> 하나면 충분할 것 같은데 말입니다.\n\n어떻습니까, 저를 좀 도와주겠습니까? 그렇게 해준다면 상부에 요청해서 보상을 내리도록 하겠습니다.", progress = "동굴에 살고 있는 트롤들은 서리갈기부족인 것 같습니다. 더 도움이 될 정보를 주지 못해 유감이군요.", completion = "아, 이런! 저 천박하고 저주받을 트롤들!\n\n&lt;진정을 위해 잠시 숨을 들이쉰 후&gt;\n\n녀석들이 밤에 와서 내 보고서를 훔쳐 갔습니다! 내가 어리석었지, 일개 수습생에게 그걸 맡겨두다니...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n앤빌마 손도끼앤빌마 망치앤빌마 나이프앤빌마 해머\n\n다음과 같은 것들 또한 받습니다:\n\n치료용 약초"},
[183] = {title = "멧돼지 사냥", objective = "탈린 킨아이가 작은 멧돼지 12마리를 처치해 달라고 부탁했습니다.", description = "멧돼지 사냥처럼 재미있는 일도 없을 거야, 안 그런가?\n\n하지만 이곳 눈마루 골짜기에는 멧돼지가 너무 많아서 사냥하는 재미가 떨어진단 말이야. 굳이 성질을 돋구지 않아도 무턱대고 달려들어서 요즘 같아선 그냥 외출하기도 힘들 정도라네.\n\n그래서 말인데 자네가 멧돼지들을 좀 처리해 줬으면 하네. 내 꼭 사례함세.", progress = "사냥은 잘 돼 가고 있나?", completion = "잘했네! 이제야 좀 여유 있는 사냥을 즐길 수 있게 됐어. 정말 고맙네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n드워프족 헝겊 반바지드워프족 가죽 바지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[184] = {title = "펄브로우의 땅문서", objective = "농부 펄브로우에게 펄브로우의 땅문서를 가져가야 합니다.", description = "이 땅문서는 서부 몰락지대의 어느 농지에 대한 등기 권리증입니다. 이 땅문서에는 농부 펄브로우와 그의 아내, 베르나의 서명이 있습니다. 그리고 뒷면에는 다음과 같은 내용이 급히 휘갈겨 쓰여 있습니다.\n\n\"우리는 펄브로우를 위협해 놈에게서 땅문서를 받아 냈다. 이곳 땅 중 일부를 손에 넣으려면 이 방법이 가장 편리할 거라 생각됐다. 펄브로우 가족은 이제 우리에게 문제를 일으키지 않을 것이다. 마지막으로 그들을 본 게 서부 몰락지대를 떠나는 길에 마차가 고장나 꼼짝 못하고 있는 모습이었다.\"\n\n펄브로우 가문은 이 땅문서를 되찾고 싶어할 것입니다.", progress = "땅문서를 가져 오셨다고요? 정말 반가운 소식이군요! 며칠 전 불한당 같은 놈들한테 땅문서를 빼앗겼었지요. 영영 못 찾을 줄 알았답니다!\n\n그 문서를 제게 주시겠습니까? 우리 가족은 서부 몰락지대를 떠나 가까운 시일 내에는 돌아오지 않을 생각입니다만, 혹시라도 돌아온다면 이 땅문서가 필요할 것입니다.", completion = "정말 고맙습니다! 다시 한 번 말씀드리지만 이곳은 더 이상 선량한 사람들이 살 곳이 못 된답니다. 하지만 상황이 나아진다면 이 땅문서로 우리 땅을 되찾을 수 있을 것입니다.\n\n크게 보답할 만한 건 없지만 이거라도 받아 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n잘익은 수박작은 호박"},
[185] = {title = "호랑이 사냥법 익히기", objective = "네싱워리 원정대의 아제크 루아크가 새끼 가시덤불 호랑이 10마리를 처치해 달라고 부탁했습니다.", description = "내가 어린 아이었을 때 아버지는 내게 호랑이 사냥 기술을 가르치셨죠.\n\n어린 고양이과 동물은 추적하거나 사냥하기가 훨씬 쉽답니다. 그러니 쉬운 사냥감부터 시작해보도록 하죠. 야영지 근처에서는 새끼 호랑이를 종종 볼 수 있어요.\n\n당신이 호랑이를 추적해서 몇 마리 사냥할 수 있을지 스스로 한번 시험해 보도록 하죠.", progress = nil, completion = "정말 잘했습니다. 훈련을 계속할 준비가 된 것 같군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[186] = {title = "호랑이 사냥법 익히기", objective = "네싱워리 원정대의 아제크 루아크가 가시덤불 호랑이 10마리를 처치해 달라고 부탁했습니다.", description = "자, 그럼 훈련을 계속해 봅시다. 이제 어미 호랑이로 당신의 사냥 기술을 시험해 보도록 하죠. 가시덤불 호랑이 10마리를 사냥해 보세요.", progress = nil, completion = "정말 대단하군요. 사냥 실력이 놀랍게 향상되고 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[187] = {title = "호랑이 사냥법 익히기", objective = "네싱워리 원정대의 아제크 루아크가 덩치큰 가시덤불 호랑이 10마리를 처치해 달라고 부탁했습니다.", description = "자, 이제 실질적인 시험으로 들어가서 좀 더 어려운 일을 맡겨 보도록 하죠. 덩치큰 가시덤불 호랑이 10마리를 사냥할 수 있는지 증명해 보세요. 이 임무를 수행해 낸다면 네싱워리 스승님 앞에서 당신을 호랑이 사냥의 대가로 임명하기 전에 거쳐야 할 최종 심사를 치르게 될 겁니다.\n\n덩치큰 가시덤불 호랑이는 찾기도 어렵지만 사납기로도 유명하답니다.", progress = "덩치큰 가시덤불 호랑이 10마리를 처치해야 당신이 진정한 호랑이 사냥꾼인지를 판가름할 최종 임무를 결정할 수 있습니다.", completion = "정말 놀랍군요. 이제 준비가 거의 끝난 것 같네요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[188] = {title = "호랑이 사냥법 익히기", objective = "네싱워리 원정대의 아제크 루아크가 신달을 처치하고 그 앞발을 가져다 달라고 부탁했습니다.", description = "자, 이제 마지막 임무군요. 우리는 지난 몇 주 동안 잡기 힘든 호랑이를 쫓고 있어요. 바로 우리가 신달이라 부르는 호랑이죠. 지금껏 어떤 <race>도 잡지 못했던 그 녀석을 당신이 사냥할 수 있을지 한번 보겠습니다. 신달을 추적해서 처치한 다음 그 증거로 놈의 앞발을 가져오세요.\n\n찾는 것만도 만만치 않을 겁니다.", progress = "신달 사냥은 어떻게 되어가나요?", completion = "정말 놀랍다는 말 밖에 나오지 않는군요! 당신은 진정한 호랑이 사냥의 대가입니다!", rewards = "다음과 같은 것들을 받습니다:\n\n호랑이 사냥꾼 장갑"},
[189] = {title = "붉은머리부족의 귀", objective = "붉은머리부족의 귀 15개를 모아 무법항에 있는 케복에게 가져가야 합니다.", description = "괘씸한 트롤들 같으니! 저 트롤놈들이 계속 정글에서 우리 대원들을 해치고 있어요! 이미 놈들과의 전투로 상당수의 훌륭한 경비병들을 잃은데다가 희생자가 계속 늘어나고 있단 말이에요! 이걸 레빌가즈 남작님께 어떻게 설명해야 할지 모르겠어요.\n\n단호한 조치를 취해야 하는데... 방법을 생각해 봐, 케복... 오늘 빈둥거리기나 하라고 일을 맡긴 건 아니잖아... 아! 당신은... <name>|1이;가; 아닌가요? 날 좀 도와주지 않을래요? 보상금이 꽤 많은 일이에요!\n\n내게 붉은머리부족 트롤의 귀 15개를 가져오면 두둑이 보상해 드리죠.", progress = "임무는 완수했나요? 그 지독한 트롤 놈들이 여기저기에서 출몰하고 있다고요.\n\n으, 생각하니 또 화가 치미는군! 어서 동료들에게 도움을 청하라고요. 도움이 많이 필요해요!", completion = "오, 훌륭해, 훌륭해요! 일단은 도움이 될 것 같군요.\n\n&lt;화제를 바꿔, 수익과 비용에 대해 투덜거리며&gt;\n\n뭐라고요? 왜 아직 여기에 있는 겁니까? 보상금? 아, 그렇군. 물론 지급해아죠. 여기 있어요. 그거면 충분할 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n고블린 낚시도구"},
[190] = {title = "퓨마 사냥법 익히기", objective = "네싱워리 원정대의 얼가딘 경이 새끼 퓨마 10마리를 처치해 달라고 부탁했습니다.", description = "헤멧이 결성한 이 일류 원정대에 참가하려면 자네가 퓨마를 사냥할 만한 실력이 있는지를 증명해 보여야 하네. 우선 쉬운 것부터 시작하도록 할 테니 너무 걱정하지는 말게나. 우선 새끼 퓨마 10마리를 사냥해 보게.\n\n놈들을 뒤쫓는 것만으로도 힘들겠지만 그건 그저 시작에 불과하다네.", progress = nil, completion = "시작이 좋군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[191] = {title = "퓨마 사냥법 익히기", objective = "네싱워리 원정대의 얼가딘 경이 퓨마 10마리를 처치해 달라고 부탁했습니다.", description = "이제 한 단계 어려운 임무를 해 볼 차례군그래. 이 대단한 원정대와 어울리려면 자네가 퓨마 10마리를 사냥할 수 있는 실력이 있음을 증명해 보여야 하네.\n\n다 자란 놈들이니 좀 더 힘들 걸세. 이전에 사냥했던 어린 새끼만큼 쉽진 않을 거란 말이지.", progress = nil, completion = "완벽하게 해냈군그래!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[192] = {title = "퓨마 사냥법 익히기", objective = "네싱워리 원정대의 얼가딘 경이 그림자퓨마 10마리를 처치해 달라고 부탁했습니다.", description = "이제 어려운 과제가 기다리고 있네. 그림자퓨마를 쓰러뜨려 실력을 증명해야 진정한 퓨마 사냥꾼이라 할 수 있지. 이 짐승을 10마리 처치해서 실력을 증명해 보이게.\n\n추적이 어렵다고 생각되면 한 놈을 발견할 때까지 기다리도록 하게.", progress = nil, completion = "잘했네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[193] = {title = "퓨마 사냥법 익히기", objective = "네싱워리 원정대의 얼가딘 경이 바그테라의 송곳니를 가져다 달라고 부탁했습니다.", description = "이제 퓨마 사냥의 대가가 될 만한 능력이 있음을 거의 증명해 보인 것 같군그래. 바그테라라는 이름의 퓨마가 정글을 어슬렁거리고 있네. 지금까지는 우리를 잘도 피해다니고 있지. 자네 실력으로 이 거대한 바그테라를 처치할 수 있을지 어디 한번 보겠네.\n\n내게 바그테라의 송곳니를 가져온다면 자네를 인정해 주지.", progress = "바그테라는 좀처럼 잡기 힘든 놈이네. 그래 사냥은 어떻게 되어가나?", completion = "오, 결국 거대한 바그테라를 처치했군! 정말 장하네. 자네는 진정 위대한 &lt;class&gt;일세!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n퓨마 사냥꾼 다리보호구"},
[194] = {title = "랩터 사냥법 익히기", objective = "헤멧 네싱워리가 가시덤불랩터 10마리를 처치해 달라고 부탁했습니다.", description = "스스로 최고의 사냥 기술을 가졌다고 생각하나 보군 그래? 흠, 금방 시험해 볼 수 있지. 정글로 가서 가시덤불랩터 10마리를 처치하게. 자네가 얼마나 대단한 사냥꾼인지 지켜보겠네.\n\n그리고 놈들을 어디서 찾을 수 있는지는 가르쳐 주지 않겠네. 놈들을 찾아내는 게 이 일의 절반에 해당하니까 말이야.", progress = nil, completion = "훌륭하게 해냈군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[195] = {title = "랩터 사냥법 익히기", objective = "헤멧 네싱워리가 채찍꼬리랩터 10마리를 처치해 달라고 부탁했습니다.", description = "그럼 다음 단계도 통과할 수 있을지 한번 보겠네. 정글로 가서 저 지독한 채찍꼬리랩터 10마리를 처치하도록 하게. 실력이 어느 정도인지 보도록 하지!", progress = nil, completion = "역시 자네 명성이 사실이었군 그래! 훌륭한 사냥 솜씨일세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[196] = {title = "랩터 사냥법 익히기", objective = "헤멧 네싱워리가 줄무늬정글랩터 10마리를 처치해 달라고 부탁했습니다.", description = "자, 그럼 다음 과제도 잘해내는지 한번 볼까? 저 밖에는 좀처럼 정체를 드러내지 않는 종류의 랩터가 있지. 우린 놈들을 줄무늬정글랩터라 부르고 있네. 지금까지 자네가 사냥을 시도했던 놈들보다 훨씬 더 추적하거나 사냥하기가 힘든 놈들이라네. 줄무늬정글랩터 10마리를 처치한다면 지금까지와는 비교도 안 되는 최고의 사냥에 대해 귀띔해 주겠네.", progress = nil, completion = "오호! 여기 진정한 랩터 사냥꾼이 탄생하셨군! 잘했네, 대단한 친구야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[197] = {title = "랩터 사냥법 익히기", objective = "헤멧 네싱워리가 가시덤불 골짜기에 있는 잡기 힘들고 위험한 랩터인 테디스를 처치해 달라고 부탁했습니다.", description = "정글에서 뛰어난 실력을 보여주었으니 나조차도 처치하지 못한 포악한 랩터에 대해 알려 주지. 아제크는 이 교활한 랩터를 테디스라 부른다네.\n\n스스로 진정한 대가임을 증명해 보이고 싶다면 테디스를 처치하고 놈의 발톱을 가져오게. 그 어떤 대단한 사냥꾼도 이루지 못한 대단한 위업을 세우는 게 되는 거야.", progress = "테디스 사냥은 어떻게 되어가나? 녀석을 뒤쫓다 보니 다시 야영지로 돌아오게 되기라도 한 겐가?", completion = "사냥의 명수 &lt;name&gt;, 진정한 랩터 사냥꾼!\n\n어떤가, 정말 듣기 좋지 않은가?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n랩터 사냥꾼의 튜닉"},
[198] = {title = "병사 토르센을 위한 보급품", objective = "병사 토르센에게 고블린의 잡다한 보급품을 전달해야 합니다.", description = "흠, 사실 당신에게 부탁할 일이 있긴 한데요. 저 북쪽에 있는 부관 도렌님과 그의 부하들이 우리가 보내 줄 정기 보급품을 기다리고 있어요.\n\n트롤 녀석들의 공격 때문에 아직 보내지 못했는데 누군가 맡아 줄 이가 필요해요. 도렌님의 야영지는 길을 따라 북서쪽으로 그늘숲에서 가시덤불 골짜기로 들어오는 입구에 있어요. 보급품을 병사 토르센에게 전해주세요. 만약 토르센이 야영지에 없다면 거기서 남쪽을 정찰하고 있을 거예요. 당신이 보급품을 가져다주면 그가 보급품을 관리할 거예요.\n\n실패할 경우에는 보급품을 모두 변상해야 한다는 사실을 잊지마세요.", progress = "무슨 일입니까? 오, 고블린의 보급품이로군요. <race>|1이;가; 보급품을 가지고 오다니 좀 이상하긴 하군요. 보통은 그들이 직접 오는데... 뭐, 상관은 없지만... 설마 보급품에 손을 대진 않았겠지요? 좋습니다. 우린 그저 우리 지뢰가 무사하기를 바라는 것뿐이니 기분 나쁘게 생각지는 마십시오.", completion = "이 지뢰들은 그 짐승 같은 쿠르젠과 놈의 부하들로부터 우리 자신을 방어하는데 유용하게 사용될 겁니다. 가져다 줘서 고맙습니다. 다른 일거릴 찾고 있다면 내가 적당한 일거리를 찾아 줄 수도 있습니다만... 그럼 고블린들을 상대하지 않아도 되겠지요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[199] = {title = "어둠의 전조", objective = "선임기술자 힌더바이르에게 돌아가 발견한 단서를 보여 주어야 합니다.", description = "이상한 향기가 나는 가루의 견본을 얻었습니다.", progress = "뭔가 단서를 찾았소?", completion = "이건 정말 놀랄만한 발견이군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[200] = {title = "사서 헤로드", objective = "사서 헤로드의 기록을 찾아야 합니다.", description = "쿠르젠이 토르센의 비밀에 대해 알고 있다면 분명 우리 중에 첩자가 있는 거요. 반드시 이 비밀이 어떻게 새어 나갔는지 밝혀내야 하오!\n\n쿠르젠의 야영지 내에는 사서 헤로드라는 자가 토르센의 연락책이었소. 헤로드는 쿠르젠의 병참 장교로서 쿠르젠 주둔지의 모든 운영 상황에 대해 알고 있소. 당신이 헤로드의 쪽지나 기록을 가져온다면 토르센이 발각된 경위를 알아낼 수 있을 거요.\n\n우리가 쿠르젠의 부대에 속해 있을 당시 그 사서의 사무실은 야영지 내의 유일한 2층짜리 건물의 맨 위층에 있었소. 헤로드의 기록은 아마 아직 거기에 있을 것이오.", progress = nil, completion = "사서 헤로드의 쪽지와 기록입니다.\n\n이 중에는 야영지 내의 보급품 목록, 대령 쿠르젠의 물자 요청서, 여러 가지 편지와 회신 등이 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[201] = {title = "야영지 조사", objective = "사냥꾼 야영지를 찾은 다음 무법항에 있는 크라젝에게 그 위치를 보고해야 합니다.", description = "투자개발회사의 채광 기지가 있는 나즈페리티 호수에서 강기슭을 따라 올라가면 한 사냥꾼 무리가 설치한 야영지가 있다는 보고를 받았어요. 보통은 이런 일에 신경쓰지 않지만, 놀랍게도 그 사냥꾼들 중에는 헤멧 네싱워리도 끼어 있다 하더군요? 그자는 주의해야 할 인물이에요. 그자는 여기저기 연결되어 있는 자인데다가, 당신도 아주 안전할 수만은 없을 거예요.\n\n당신이 그자들의 야영지를 조사해서 무슨 일을 벌이고 있는지 좀 알아봐 줄래요?", progress = nil, completion = "흠, 결국 이번에도 내 정보가 정확했던 셈이군. 흥미롭군요. 뭐, 그들이 우리 작전에 방해가 될 것 같지는 않지만 우리의 뛰어난 제품들을 탐낼 수도 있겠군요. 흠...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[202] = {title = "대령 쿠르젠", objective = "쿠르젠 정예병 6명, 쿠르젠 부대장 4명을 처치하고 그 증거로 쿠르젠의 머리카락을 반란군 야영지에 있는 부관 도렌에게 가져가야 합니다.", description = "당신은 매우 놀라운 능력을 자주 선보이는군. 아마 당신의 능력은 쿠르젠과 비교해도 손색이 없을 것이오. 당신이 쿠르젠과 직접 겨뤄서 이긴다면 우리 반란군에겐 구세주와 같은 존재가 될 것이오!\n\n그는 보급창 동굴 깊은 곳에 숨어서 부하들을 지휘하고 있소. 그 동굴로 들어가 호위병들을 물리치고 쿠르젠과 지휘부를 직접 상대해야 하오이다.\n\n부탁하오. 당신은 나의 유일한 희망이며, 우리의 운명이 당신 손에 달려 있소.", progress = "쿠르젠과 그의 호위병들을 처치한 것이오?", completion = "정말 믿기 힘들지만 이렇게 증거를 가져왔으니... 쿠르젠과 그의 지휘부를 물리쳤다는 사실을 믿을 수밖에 없구려. 당신이 우리를 구했소!\n\n이 정글에는 갖가지 위험이 도사리고 있지만 쿠르젠처럼 지능적이고 잔인한 상대는 없었소. 이제 그가 죽었으니 우리도 마음을 놓을 수 있게 되었소이다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n유산탄총"},
[203] = {title = "제 2의 반란", objective = "쿠르젠 밀림전사 15명을 처치해야 합니다.\n\n반란군 야영지에 있는 하사관 요화에게 돌아가십시오.", description = "우린 대령 쿠르젠과의 전투에서 밀리고 있습니다. 그는 뛰어난 전술가일 뿐 아니라 수적으로도 우리보다 열 배는 우세합니다! 살아남으려면 그의 위장 전술을 역으로 이용해야 합니다.\n\n동쪽에 있는 그의 야영지로 가서 부하들을 처치하시기 바랍니다. 그리고 쿠르젠의 지원군이 오기 전에 빠져나와야 합니다.", progress = nil, completion = "수고했습니다. 밀림&lt;class&gt;들을 처치했으니 우리 야영지에 대한 놈들의 압박도 다소 누그러질 겁니다.\n\n우리가 마주하고 있는 적의 힘을 직접 겪어 보니 어떻습니까? 아직도 우리와 운명을 같이할 생각이 있습니까??", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[204] = {title = "나쁜 약", objective = "반란군 야영지에 있는 하사관 요화에게 밀림 치료제 7개와 독고사리 즙 1개를 가져가야 합니다.", description = "쿠르젠군의 의료 지원을 무력화하면 그들을 물리칠 기회를 얻을지도 모릅니다. 그는 주위에 수많은 약사를 두고는 밀림 치료제로 자신의 병사들을 치료하고 독고사리 즙으로 우리 병사들을 독살하고 있습니다.\n\n상처 입은 우리 병사들을 치료하려면 그 밀림 치료제가 필요합니다. 또 직접 치료법을 개발하려면 연구에 필요한 독고사리 즙 견본도 있어야 함은 물론입니다. 밀림 치료제는 그의 약사들에게 있을 것이며, 독고사리 즙은 야영지의 보급품 상자 중 어딘가에 들어 있을 것이니 쿠르젠 주둔지에 가서 그 두 가지를 가져오십시오.", progress = "당신이 밀림 치료제와 독고사리 즙을 가져오기를 기다리고 있겠습니다.", completion = "수고했습니다. 이 치료제로 많은 우리 병사들이 목숨을 구하고 전력도 증강될 수 있을 것이고, 독고사리 즙을 이용하여 치료제도 개발할 수 있을 겁니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n야자수잎 어깨보호대게릴라 클레버\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[205] = {title = "트롤의 마법", objective = "반란군 야영지에 있는 수사 니메츠에게 백골가루부족 우상 4개를 가져가야 합니다.", description = "<형제/자매>께서 입수한 전설들을 연구할 동안 사악한 트롤의 마법 도구를 모아 주셨으면 합니다. 남쪽 먼 곳에 두 번째 트롤 부족인 백골가루부족의 땅으로 가십시오. 그리고 그들 부족의 의술사들과 비술사들에게서 백골가루부족 우상을 구해서 가져오도록 하시기 바랍니다.", progress = "우상은 구해 왔습니까? 쿠르젠이 타락한 이유를 밝혀내는 데 중요한 열쇠가 될지도 모르는 물건입니다. 그가 타락한 이유를 반드시 알아내야 합니다!", completion = "고맙습니다. 이 우상을 연구해서 쿠르젠이 악마의 손에 들어가게 된 비밀을 밝혀낼 수 있을지 알아보도록 하겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[206] = {title = "마이조스", objective = "반란군 야영지에 있는 수사 니메츠에게 마음의 눈을 가져가야 합니다.", description = "쿠르젠이 죽었을지 모르지만 그를 악의 세력으로 몰아넣은 자는 아직 살아 있습니다! 이번 연구를 통해 몇 가지 알아낸 것이 있는데 가시덤불 골짜기 동쪽 산 내의 오우거 소굴에 마이조스라는 오우거 마법사가 살고 있습니다. 마이조스는 정신을 지배하는 마법을 사용한다고 알려져 있는데, 나는 그 오우거가 쿠르젠을 타락시켰다고 확신하고 있습니다.\n\n마이조스를 살려두면 다른 이들에게까지 악한 영향력을 행사할 테고, 제 2의 쿠르젠이 나타날 수도 있을 겁니다.\n\n그러니 녀석을 처치하고 녀석이 다른 이를 타락시키는 데 사용하는 마음의 눈을 가져오십시오.", progress = "형제님께 신의 가호가 함께하기를... 마이조스의 힘은 그의 사악한 마음만큼이나 강합니다.", completion = "아! 해냈군요! 형제는 실로 역사에 남을 만한 &lt;class&gt;입니다. 그 힘이 영원히 쇠하지 않기를 바랍니다.\n\n이 마음의 눈을 연구해서 선한 목적으로 사용될 수 있을지 알아봐야겠습니다. 그게 불가능하다면 파괴할 수밖에 없겠지만...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n평온의 수정구"},
[207] = {title = "쿠르젠의 비밀", objective = "4개의 서판을 찾아 거기에 기록된 전설을 수사 니메츠에게 가져가야 합니다.", description = "대령 쿠르젠은 한때 훌륭하고 고귀한 존재였습니다. 그랬던 그가 왜 타락해 버렸는지 반드시 알아내야 합니다! 어쩌면 트롤의 마법에 조종 당하고 있는지도 모르겠습니다. 그걸 확인하려면 그들의 전설에 대해 연구해 볼 필요가 있습이다.\n\n가시덤불 골짜기의 트롤 폐허에는 서판이 네개 숨겨져 있습니다. 그 서판에 쓰인 내용을 확인해야 하니 서판의 내용을 필사하여 가져오시기 바랍니다.\n\n첫 번째 서판은 발랄 폐허에 있고, 두 번째는 썩은내 산호초에 그리고 세 번째와 네 번째 서판은 줄쿤다의 폐허에 있습니다.", progress = "트롤의 전설은 가져왔습니까? 그 비밀을 반드시 밝혀내야 합니다!", completion = "고맙습니다. 이 전설에 대해 연구해서 대령 쿠르젠을 조종하고 있는 악의 세력과 트롤이 관련이 있는지 알아보도록 하겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[208] = {title = "대단한 사냥꾼", objective = "헤멧 네싱워리가 거대한 백색 호랑이인 야수왕 뱅갈라시의 머리를 가져다 달라고 부탁했습니다.", description = "자네는 우리 동료로서 손색없는 사냥꾼일세. 로데론의 전장에서 깊은 정글에 이르기까지, 그 어느 곳에서도 자네만큼 무기를 잘 다루는 이를 본 적이 없다네.\n\n결국은 그 사나운 신달과 잡기 힘든 바그테라, 그리고 종잡을 수 없는 테디스까지 처치했으니... 하지만 그 무엇보다 야수왕 뱅갈라시의 머리를 베어야 진정한 목표를 달성했다고 할 수 있지. 나도 그 하얀 호랑이 때문에 이곳에 온 것이지. 지금까지 꽤 오랫동안 놈을 쫓고 있다네. 야수왕 뱅갈라시를 처치한다면 자네의 사냥 솜씨가 그 누구보다 뛰어나다는 것을 입증하게 되는 걸세.", progress = "다시 돌아온 건가, 친구? 야수왕 뱅갈라시 때문에 나도 몇 번이나 야영지로 돌아왔었지. 자네는 한번 끝까지 해보도록 하게.", completion = "정말 잘했네! 아주 좋아! 축하하네. 자네는 어느 누구도 해내지 못한 일을 성공적으로 해낸 거야.\n\n자네를 우리 위대한 원정대의 일원으로 맞이하게 된 것을 영광으로 생각하네. 누구도 자네의 뛰어난 사냥과 추적 기술을 의심하지 않을 걸세.\n\n장하네. 정말 장해!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n전문 사냥꾼의 활전문 사냥꾼의 라이플\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[209] = {title = "백골가루부족 어금니", objective = "백골가루부족 어금니 18개를 모아 케복에게 돌아가야 합니다.", description = "남해의 섬에 수출할 호랑이 송곳니를 충분히 공급할 수 있을 만큼 호랑이를 사냥하는 것은 어렵기도 하고 비용도 만만치 않아요. 다행히 우리는 평범한 뿔 모양의 물건으로 감쪽같이 모조품을 만드는 기술을 개발했죠.\n\n우리가 발견한 가장 비슷한 재료는 놀랍게도 백골가루부족 트롤의 어금니였어요.\n\n이 일에 대해 왈가왈부하지 마세요. 사는 사람들은 아예 이 사실을 모르는 게 약이니까요. 일단 산 후에는 그저 잘 쓸 수만 있으면 되는 것 아니겠어요? 이번 달 수출 물량을 맞출 수 있도록 백골가루부족 트롤의 어금니를 많이 가져다주세요!", progress = "상대하기에 너무 사나운 놈들이었나요? 흠, 구해 오기는 한 거예요? 재촉하는 것 같아서 미안하긴 하지만, 우린 시간이 별로 없어요! 알겠나요?", completion = "아, 좋아요. 정말 수고했어요! 당신이라면 그... 놈들도 쓸어버릴 수 있었을 텐데... 아, 아무것도 아니에요! 고마워요. 당신이 도와준 덕분에 우리 사업이 더욱 번창할 수 있겠군요. 그건 그렇고, 이제 다른 문제에 대해 얘기를 해 봤으면 하는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[210] = {title = "크라젝의 요리 냄비", objective = "고블린 크라젝에게 크라젝의 고물 냄비를 가져가야 합니다.", description = "이 야영지에서 요리는 거의 내 몫이랍니다. 무법항의 고블린 상인에게서 요리 냄비 기계를 구입하기 전까지 요리는 상당한 중노동이었지요. 정말 놀라운 냄비랍니다! 시간도 엄청나게 절약됐었지요... 그런데 그만 망가뜨리고 말았습니다.\n\n당신이 내 대신 이 냄비를 고블린에게 가져가 수리해 주시지 않겠습니까? 그의 이름은 크라젝입니다.", progress = "어서 오세요! 내게 뭘 가져온 모양이군요?", completion = "오, 알겠어요. 내 고물 냄비를 가져왔군요! 정교한 냄비인데 가끔 스프링이나 톱니바퀴가 고장나곤 하지요. 어디가 고장 난 건지 한번 보죠.\n\n아하! 증기충전장치도 녹슬어 버렸고, 접합관도 망가졌고, 증기태엽장치의 이도 빠져 있군. 이런 상태로 야채를 삶았다는 것만 해도 놀랍네요.\n\n고칠 수 있느냐고요? 물론 고칠 수 있죠!\n\n하지만 그 대신 내 부탁을 좀 들어줘요. 그럼요, 세상에 공짜가 어디 있겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[211] = {title = "리치의 최후", objective = "서부 역병지대의 서리바람 야영지에 있는 사령관 아쉬람 발러피스트에게 아라즈의 성물함 조각을 가져다 주어야 합니다.", description = "이제 안돌할을 공격해 그곳을 지배하는 리치를 몰아낼 때가 왔소!\n\n도시의 폐허 안쪽에 권력을 잡고 있는 소환사 아라즈라는 리치가 있소. 도시 가운데 유적들 주위에는 리치를 경호하는 스컬지들이 깔려 있고, 그의 직속 수행원들은 정말 위협적인 존재들이라오. 친구들을 많이 데리고 가야 그와 대등하게 맞설 기회를 잡을 수 있을 거요.\n\n<name>, 가서 리치를 처치하고 그 증거로 아라즈의 성물함 조각을 가져오도록 하시오!", progress = "이미 당신에게 임무를 준 것으로 기억하오. 임무를 완수한 증거로 리치의 성물함 조각을 가져오라고 했을 텐데?", completion = "해냈군! 드디어 리치... 아라즈를 물리쳤어!\n\n&lt;name&gt;, 오늘 얼라이언스를 위해 정말 큰 공을 세우셨소. 당신의 용기와 끈기야말로 진정한 영웅이라면 반드시 갖춰야 할 덕목이 무엇인지 보여준다고 할 수 있소. 자, 이것을 받으시오! 당신이 세상에 둘도 없을 승리를 얼라이언스에게 안겨주었다는 사실을 모든 이들이 알 수 있도록!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n결심의 징표"},
[212] = {title = "식은 음식", objective = "얼음눈 바실리스크를 처치하고 얼린 바실리스크 다리를 얻은 다음 고독한 은둔자 선술집에 있는 앵거스 스턴에게 돌아가야 합니다.\n\n퀘스트 진행 도중 한번이라도 죽게 되면 이 퀘스트를 완수할 수 없습니다.", description = "저의 가장 유명한 요리 중 하나는 라임 드레싱을 곁들인 얼린 바실리스크 요리입니다. 그런데 문제는... 바실리스크 고기는 신선하게 유지하는 것이 불가능한데 오늘 저녁 왕의 만찬에 이 요리를 올려야 한다는 겁니다!\n\n그러니까 얼음눈 바실리스크를 죽이고 그 즉시 얼린 바실리스크 다리를 빨리 가져다주시면 왕의 만찬으로 보답하겠습니다!\n\n얼음눈 바실리스크는 북서쪽 가시덤불 골짜기의 해변 모래 언덕을 따라 돌아다닌다고 합니다. 그러니까 여행을 좀 해야 할 겁니다. 서두르세요!", progress = "얼린 바실리스크 다리를 가져오셨나요? 곧 요리 준비를 시작하지 않으면 연회를 망치게 될 거예요!", completion = "아, 이거면 충분합니다! 정말, 정말 감사합니다!\n\n그럼 이만 실례하겠습니다. 이제 이 얼린 바실리스크 다리를 썰고 매리네이드에 절인 다음 연회 분위기에 맞게 장식해야 합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[213] = {title = "적대적 탈취", objective = "연마된 수정 8개를 찾아 무법항에 있는 케복에게 가져가야 합니다.", description = "흠... 겔리즈가 교역 군주들이 임명한 거물들을 힘으로 밀어붙였다는 나쁜 소식이에요. 이보다 나쁜 소식이 어디 있겠어요? 결국 놈이 일을 내고 말았다고요! 놈은 이제 가장 악랄한 해적이 되려 하고 있으니!\n\n레빌가즈님은 이 일을 직접 처리하려 하시지 않고 나더러 문제를 해결하라고 지시하셨어요. 내 방식대로 해결하라니... 내 방식이라면 도둑질밖에 없는데... 나즈페리티 호수 근처에 있는 투자개발회사 지질학자들이 광산에서 발견되고 있는 이상한 파란 수정에 큰 관심을 보이고 있다고 하더군요. 그 지질학자들에게서 수정 견본을 구해다 주세요. 뭐, 어떻게 구하든 그 방법은 알아서 하세요.", progress = "난 그 수정이 필요해요. 어떻게 해서든 반드시 손에 넣어야 한단 말이에요! 방법은 내 알 바 아니니 어서 구해 오기나 하세요!\n\n중요한 건 결과라고요. 그 이상도 그 이하도 아니에요.", completion = "정말 멋지군요. 이런 과정을 통해 수정을 연마했다면 놈들은 이 수정을 일종의 연료나 촉매로 사용하려는 것 같군요. 내가 아는 건 그 정도가 전부이니 이 표본은 선임 연금술사 기글폰트에게 가져가야 해요.", rewards = "다음과 같은 것들을 받습니다:\n\n보석박힌 장갑"},
[214] = {title = "붉은 비단 복면", objective = "감시의 언덕 탑의 정찰병 리엘이 붉은 비단 복면 10개를 가져다 달라고 부탁했습니다.", description = "이미 알려진 바대로 붉은 복면은 데피아즈단의 상징입니다. 얼마 전 복면의 재질이 놈들의 계급을 나타낸다는 사실을 새로이 알아냈습니다.\n\n자, 이 사실을 알려드렸으니 데피아즈단원 고위 계급자들을 최대한 많이 처치해 주시기 바랍니다. 틀림없이 밴클리프의 비밀 은신처에 가면 최고위 계급 단원들을 찾을 수 있을 겁니다. 놈들을 처치하고 증거물로 붉은 비단 복면 10개를 가져다주시면 보상해 드리도록 하겠습니다. 행운을 빕니다.", progress = "데피아즈단으로부터 우리 영토를 되찾았나요? 그렇다면 그 증거로 붉은 비단 복면 10개를 보여 주시기 바랍니다.", completion = "훌륭하군요! 백성의 민병대를 대표해 당신의 공적에 경의를 표합니다. 당신처럼 용감한 분이 함께하는 한 머지 않아 주민들에게 이 땅을 되돌려 줄 수 있을 것입니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n튼튼한 쇼트소드수공예 단검예리한 도끼\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[215] = {title = "정글의 비밀", objective = "반란군 야영지에 있는 부관 도렌과 대화해야 합니다.", description = "날 구해 줘서 고맙습니다. 좀 의아해 보이는 모양인데 설명해 드리도록 하지요.\n\n도렌 부관님께서 내게 쿠르젠의 부대에 잠입하여 놈들을 염탐하고 반란군에게 꼭 필요한 정보를 가져오라고 명하셨습니다. 그래서 쿠르젠 주둔지에 침투해 들어갈 기회를 엿보다가 지금이 기회다 싶어 실행에 옮기고 있던 참이었습니다. 그런데 내가 또 잘못 생각했던 모양입니다. 다시 한번 구해 주어 고맙습니다.\n\n이 임무는 일급 비밀이니 누구에게도 말해선 안 됩니다. 하지만 도렌 부관님을 만나 보면 설명해 주실 겁니다.", progress = nil, completion = "그렇소, 토르센이 얘기한 대로요. 그리고 이 일에 더는 관여하지 마시오. 예전에 우리 반란군은 대령 쿠르젠의 충직한 부하들이었소. 하지만 쿠르젠이 타락하자 우리의 충성심은 분노로 변했지. 최근 토르센이 쿠르젠의 부하들과 접촉한 사실이 알려진다면 아마 쥐도 새도 모르게 그의 목이 달아날 거요.\n\n내가 아는 한, 이번 토르센의 임무에 대해 아는 이는 하사관 요화와 병사 토르센 그리고 나밖에 없소. 하지만 또 한 명, 이 사실을 알고 있는 배반자가 있는 모양이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[216] = {title = "엉겅퀴 마을 침공", objective = "엉겅퀴일족 복수자와 주술사를 각각 12마리씩 처치해야 합니다. 조람 해안 동쪽에 있는 엉겅퀴 마을에 몰려 있을 것입니다. 임무를 마치면 잿빛 골짜기 조람가르 호드 전초기지로 가서 카랑 아마카르를 만나야 합니다.", description = "괘씸한 엉겅퀴일족 펄볼그들이 우리 앞길을 막고 있소이다! 그러니까 동쪽에 있는 엉겅퀴 마을이 토막나무 주둔지로 가는 길을 가로막고 있소. 아스트라나르 마을을 우회하는 경로이므로 그 길을 잃으면 얼라이언스에 확장로를 넘겨주는 꼴이 되지.\n\n그런 일은 절대 있을 수도, 있어서도 안 되는 일이오!\n\n엉겅퀴 마을로 가서 펄볼그들의 머릿수를 줄이시오. 이 임무를 마치면 충분한 보상이 주어질 것이오. 하지만 너무 잿밥에만 관심을 갖지는 마시오. 호드에 대한 당신의 의무를 다하는 것이 무엇보다 중요하니까!", progress = nil, completion = "&lt;class&gt; 친구, 잘했소. 정말 잘했소이다! 이제 얼라이언스의 간섭을 받지 않고 다른 길을 이용할 수 있게 됐군. 잿빛 골짜기 정복에 박차를 가할 수 있게 되었소! 병력을 추가로 보내 남은 펄볼그들을 모조리 쓸어버려야겠소.\n\n고맙소. 당신의 노고에 경의를 표하는 바이오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[217] = {title = "왕국 수호", objective = "트로그의 우두머리인 그로우머그와 그의 경비병인 내셔와 브롤러를 처치하고 남쪽 경비탑으로 돌아와 경비대장 루겔퍼스에게 보고하십시오.", description = "얼마 전 트로그 습격 때 우리 정찰병이 놈들의 우두머리를 발견했네. 그로우머그라는 녀석인데 모단 호수에서 트로그들을 지휘하고 있지. 이 녀석 옆에는 항상 내셔와 브롤러라는 우수한 경비병 둘이 항상 붙어 다녀서 매우 철저하게 경호를 한다네.\n\n가능하다면 그로우머그와 두 경비병의 암살 임무를 맡아 주게나. 지휘관을 없애면 쉽게 트로그놈들을 다시 땅속으로 보낼 수 있을 거야.", progress = "그로우머그와 녀석의 경비병 내셔와 브롤러가 아직 살아 있네. 이 세 놈을 모두 처치하기 전까지 자네 임무는 끝난 게 아니야. <race> 왕국의 운명이 자네 손에 달려 있네.", completion = "정말 훌륭해! 자네는 모단 호수에 희망을 되찾아 준 거야. 그로우머그를 처치했으니 이 땅에서 트로그를 몰아낼 희망이 생겼네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n개척자의 가죽 바지드워프족 철벽방패행운의 바지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[218] = {title = "도둑맞은 일지", objective = "그렐린 화이트비어드가 냉혈한 그리크니르를 처치하고 일지를 되찾아 달라고 부탁했습니다.", description = "트롤이 내 일지를 훔쳐서 동굴 안으로 도망쳐 버렸습니다. 일지를 가지고 도망친 녀석을 자세히 보진 못했지만 몸과 얼굴에 이상한 문신이 있고 크고 사나워 보이는 놈이었습니다.\n\n당신이라면 내 일지를 되찾아 줄 수 있을 듯해 보이는데 나 좀 도와주시겠습니까?", progress = "그 놈은 찾았나요?", completion = "훌륭합니다! 일지를 찾아 줘서 정말 고맙습니다. 그나저나 이제 눈마루 골짜기의 트롤들은 어느 정도 소탕된 것 같아 크게 걱정하진 않아도 될 것 같군요.\n\n그런데, 이제 곧 보고서가 마무리될 텐데 그걸 세니르 형에게 가져다 줄 사람이 필요한데...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n드워프족 카이트실드매끄러운 보행용 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[219] = {title = "교전 중 실종", objective = "하사관 키샨이 붉은마루 산맥으로 돌아갈 수 있도록 보호하십시오.", description = "드디어 얼라이언스 동지를 만나게 되었군!\n\n제발... 나 좀 도와 주게...\n\n사악한 오크들이 우리 연대를 제압하여 대부분의 병사들이 목숨을 잃었네. 난 머리에 큰 충격을 입고 그 자리에서 의식을 잃고 말았지. 깨어나니 이 동굴에 갇혀 있더군. 아직 상처가 심해 탈출할 수가 없다네. 제발... 날 좀 도와주게. \n\n어서 마을로 되돌아가 치료를 받아야 해... 제발... 자네가 유일한 희망일세...", progress = nil, completion = "자네는 왕국에 큰 도움을 주었네. 하사관 키샨이 무시무시한 검은바위부족 오크에게서 탈출할 수 있도록 도와 줘서 고맙네. 오늘 보여 준 용기는 꼭 보상받게 될 걸세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n솔로몬의 로브부관의 사슬 갑옷뼈장식 가죽 조끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[220] = {title = "물의 부름", objective = "불모의 땅에 있는 이슬렌 워터시어에게 가득 찬 순수한 물을 가져가야 합니다.", description = "이슬렌이 한 가지 임무를 더 준 다음 토템을 상으로 줄 거예요. 그게 어떤 임무든 내가 주는 물병이 꼭 필요할 거예요.\n\n이제 그녀를 찾아가세요. 우린 언젠가 다시 만나게 될 거예요.", progress = "어서 오세요. 좋아 보이는군요.\n\n어떻게 해서 이렇게 빨리 돌아왔나요?", completion = "아, 브린이 만든 순수한 물이 담긴 병이군요. 당신이 직접 모아 주셨군요.\n\n당신에게 드릴 정기를 만들 때 이 병에 담긴 물이 꼭 필요할 거예요. 그리고 이 물은 한 가지 다른 일에도 사용될 거예요.\n\n내가 만들어주는 정기를 사용해서 언더시티의 남쪽, 은빛소나무 숲의 신전에 있는 물의 정령을 만나세요. 그 다음 임무는 그러니까... 당신이 준비가 되었다고 생각되면 그때 말해주도록 하죠.\n\n한번 더 여행을 떠날 준비가 되었나요?", rewards = "다음과 같은 것들을 받습니다:\n\n물의 정기"},
[221] = {title = "숲 속의 늑대인간", objective = "다크샤이어의 칼로를 위해 파멸의어둠일족 암흑길잡이 12마리를 처치해야 합니다.", description = "숲 속에서 파멸의어둠일족 흑마술사와 함께 돌아다니는 큰 늑대인간을 보았겠지요? 우리가 확인한 바로는 늑대인간 무리 중 다수가 이 암흑길잡이들인 것 같습니다.\n\n놈들이 마을 남서쪽의 오염된 과수원을 점령해 버렸다는 사실도 확인했습니다. 이 늑대인간 무리는 지난번에 당신이 상대한 놈들보다 좀 더 강할 겁니다.\n\n조심하세요.", progress = nil, completion = "암흑길잡이들을 잘 처리해 주었습니다. 하지만 놈들의 수가 끝도 없이 많은 것 같습니다. 처치할 때마다 그 숫자만큼 다시 나타나니 말입니다.\n\n대체 이 마을에 어떤 악한 세력이 드리워져 있기에, 안 그래도 힘든 이곳에 왜 이런 놈들까지 나타나서 어지럽히는 건지, 원...\n\n난 대장 카레빈님을 믿어 보려고 합니다. 그가 반드시 문제를 해결해 주리라 믿어 의심치 않습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[222] = {title = "숲 속의 늑대인간", objective = "다크샤이어의 칼로를 위해 파멸의어둠일족 송곳니투사 8마리와 파멸의어둠일족 타락전사 8마리를 처치해야 합니다.", description = "지금까지의 당신의 임무 수행 과정으로 볼 때, 숲에 출몰하고 있는 늑대인간들 중 가장 사나운 놈을 상대해도 될 것 같군요.\n\n이곳에 새로 나타난 늑대인간 중에는 송곳니투사와 타락전사가 가장 위험한 것으로 밝혀졌습니다. 놈들은 동굴 근처나 남쪽의 광산 안에 살고 있습니다.\n\n먼 곳에서도 놈들이 피우는 모닥불 불빛을 볼 수 있을 겁니다.", progress = nil, completion = "솔직히 말해서 당신이 이렇게까지 잘해낼 줄은 몰랐습니다. 당신은 확실히 대단한 &lt;class&gt;|1이요;요;! 공식적으로 대장 카레빈님과 함께 싸워볼 의사가 있다면, 기꺼이 추천서를 써 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[223] = {title = "숲 속의 늑대인간", objective = "조나단 카레빈에게 칼로의 쪽지를 가져가야 합니다.", description = "여기 있습니다. 이 편지를 대장 카레빈께 가져가십시오.\n\n<재빨리 색 바랜 양피지 문서를 건네주는 칼로>\n\n당신 같은 사람이 몇 명만 더 있으면 수적으로 어둠의 순찰대를 능가할 수 있을 겁니다! 그러면 아마 지금 몇 안 되는 인원으로 힘겹게 수행하고 있는 이 임무를 수월하게 완수할 수 있을 것입니다.", progress = "무슨 일이오? 용건이 있으면 빨리 말하시오. 난 할 일이 많은 사람이오.", completion = "내 첫 인사가 다소 차가웠더라도 이해해주길 바라오. 보다시피 워낙 바쁘다 보니 그렇게 됐소. 칼로가 추천장을 써 주다니, 당신이 상당히 맘에 들었나 보군. 칼로는 아무에게나 쉽게 추천장을 써 주는 사람이 아니지.\n\n현재 이 지역에는 불미스러운 일들이 계속 발생하고 있소. 그리고 누구든 실력을 증명해 보인 자라면 우리와 함께 싸울 수 있소. 우리는 악령, 언데드, 그리고 이들을 돕는 자들을 상대로 싸우고 있소. 항상 방심하지 말고 경계하면서, 우리를 돕지 않는 자들은 절대 믿지 말길 바라오.\n\n정의의 편에 승리의 영광이!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n신념의 망토신념의 방패\n\n다음과 같은 것들 또한 받습니다:\n\n신성한 마법봉"},
[224] = {title = "왕국 수호", objective = "남쪽 경비탑의 산악경비대 코블플린트가 가루바위 트로그와 가루바위일족 정찰병을 각각 10마리씩 처치해 달라고 부탁했습니다.", description = "폐하의 이름으로 수많은 병사들은 최전방에서 치열한 전투를 벌이고 있소. 게다가 트로그놈들이 틈만 보이면 굴을 파고 쏟아져 나오고 있는 상황이오. 트로그는 이미 아이언포지의 안녕을 위협하는 심각한 골칫거리가 되었소이다. 이 진절머리나는 돌연변이들을 반드시 물리치고 대호수를 지켜야 하오!\n\n트로그의 위협을 막기 위해서는 당신과 같은 용감한 모험가의 도움이 필요하다오. 가루바위 트로그 10마리와 가루바위일족 정찰병 10마리를 처치하고 돌아와 보고해 주시오.", progress = "모단 호수가 공격 당하고 있소! 얼라이언스에게 지원을 요청해 가능한 모든 병력을 불러와야 하는 실정이오. 아직도 가루바위 트로그 10마리와 가루바위일족 정찰병 10마리를 처치하지 못한 거요?", completion = "잘했소! 당신은 전장에서 보여준 용기는 실로 가상하군. 우린 반드시 전쟁에서 승리하여 트로그를 처단할 거요. 마그니 폐하를 위해 정말 대단한 일을 한 게요.\n\n이런 모험에 자신이 있다면 산악경비대 그레이블고를 찾아가 보시오. 경비대장께서 그에게 위험한 순찰 임무를 부여했으니 도움이 필요할 게요. 경비탑 쪽으로 가면 그를 만날 수 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n달라란의 톡쏘는 치즈"},
[225] = {title = "오래된 무덤", objective = "다크샤이어의 시라 본인디와 대화해야 합니다.", description = "이 오래된 무덤의 비석에는 다음과 같은 글이 새겨져 있습니다.\n\n모건 래디모어\n\n<좀 더 자세히 살펴보면 무덤 위의 흙이 최근 파헤쳐졌으며 상당한 양의 흙이 옮겨졌다는 사실을 확인할 수 있습니다...>", progress = nil, completion = "모건 래디모어라고요?\n\n아, 네, 알고 말고요. 그는 아주 길고 슬픈 이야기의 주인공이랍니다. 그가 전쟁에 나가기 전까지는 그와 알고 지내는 사이었지요. 하지만 그 뒤로는 볼 수 없었습니다. 참으로 기품 있고 좋은 사람이었는데, 비참한 최후를 맞고 말았습니다.\n\n내 얘기를 듣는 것보다 여기 이걸 보는 게 더 정확할 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[226] = {title = "늑대의 위협", objective = "굶주린 그늘숲늑대 12마리와 광포한 그늘숲늑대 8마리를 처치한 다음 그늘숲의 서쪽 변경의 스벤의 야영지에 있는 라스에게 돌아가야 합니다.", description = "스벤과 저는 동쪽에 있는 강령술사들의 공격으로 하루하루가 위험의 연속이랍니다. 게다가 이곳에는 우리 둘밖에 없기 때문에 먹고 살려면 직접 사냥을 해야 하는 형편이지요. 그런데 짐승의 고기나 물고기를 가지고 야영지로 돌아올 때마다 굶주린 그늘숲늑대와 광포한 그늘숲늑대가 숲에서 튀어나와 마치 고기를 내 놓으라는 듯 위협한답니다. 어쩌겠어요, 살려면 고기를 내줄 수밖에요. 이곳에서 지내는 게 이렇게 위험하답니다.\n\n저희를 위해 늑대를 몇 마리 없애 준다면 이곳에서 훨씬 편하게 생활할 수 있을 겁니다. 늑대들은 주로 이곳의 북쪽과 동쪽 강 근처에 자주 출몰합니다.", progress = nil, completion = "수고하셨습니다. 늑대 수가 제법 줄어서 이제 늑대들이 우리를 뒤쫓아 다니지 않겠군요. 이제는 모벤트 펠을 상대하는데 총력을 기울일 수 있게 되었네요.\n\n자, 이 섬광탄 다발을 받으세요. 스벤을 위해 마을에서 만들어서 기증해 준 것입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n섬광탄 다발"},
[227] = {title = "모건 래디모어", objective = "다크샤이어의 사령관 알시아 이본로크와 대화해야 합니다.", description = "<책장 선반에서 가죽 표지의 책을 찾아내며>\n\n더 자세히 알고 싶다면 알시아님께 물어보십시오. 최근 그의... 문제를... 처리한 게 알시아님이니 말입니다.", progress = nil, completion = "모건 래디모어? 그런 이름은 처음 듣는데...\n\n아! 모르라딤 말이로군! 그에 관한 얘길 들어 본 적이 없는 모양이군.\n\n흠, 그럼 내가 간단하게 얘기해 주도록 하지. 지금 그늘숲에 모르라딤이라는 언데드가 돌아다니고 있다는 건 당신도 알고 있겠지? 우리가 입수한 정보에 의하면 모건 래디모어가 언데드가 되어 나타난 것이라고 하오. 이자가 순찰 중인 경비를 공격한다거나 사람을 죽인다거나 하는 온갖 문제의 온상이 되고 있지.\n\n&lt;당신을 훑어보며&gt;\n\n당신이라면 그가 편히 잠들도록 도와줄 수 있을 것 같아 보이는군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n모건 래디모어의 이야기"},
[228] = {title = "모르라딤", objective = "모르라딤을 처치한 다음 그의 해골을 다크샤이어의 사령관 알시아 이본로크에게 가져가야 합니다.", description = "우리 정찰병의 보고에 따르면 모르라딤은 묘지 옆의 낯설고 굽은 길을 따라 그늘숲 여기저기를 돌아다니고 있다고 하오. 우린 그를 언덕 위의 집을 지나서 묻었는데, 당신 그 집이 어디 있는지 알고 있소?\n\n행운을 빌어 주는 것밖에는 내가 도울 수 있는 일이 없는 것 같군.", progress = "그를 처치하는데 어려움을 겪고 있다고 해서 당신을 비난할 생각은 없소. 우리의 가장 강한 순찰대원들도 모르라딤을 놓쳤으니 말이야.", completion = "그를 처치했다고? 대단한 일을 해냈군! 다크샤이어 주민과 어둠의 순찰대를 대신해서 감사를 표하는 바이오.\n\n아... 그런데 작은 문제가 하나 있는데 말이지...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[229] = {title = "살아 남은 딸", objective = "다크샤이어의 순찰대원 사라 래디모어와 대화해야 합니다.", description = "전에 이 얘기도 했어야 했는데... 흠, 어떻게 얘기해야 하나...\n\n모건 래디모어는 자기 가족이 모두 죽었다고 생각했었는지 모르지만, 실은 사라 래디모어라고 그의 딸이 지금 순찰대원으로 일하고 있소. 그녀는 항상 아버지의 죽음...과 관련된 일들 때문에... 많은 어려움을 겪어 왔지. 그러니 당신이 가서 이 소식을 알려 주는 게 좋을 것 같소.", progress = nil, completion = "그래요? 아버지가...\n\n&lt;시선을 떨구며&gt;\n\n전 아버지를 위해 아무것도 할 수가 없었어요. 아버지가 그렇게 가시기 전에 사랑한다고 얘기라도 한 번 했었더라면...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[230] = {title = "스벤의 야영지", objective = "스벤에게 스벤 농장의 책을 가져가야 합니다.", description = "흙무더기를 파 보니 흙으로 뒤덮인 작은 책을 발견했습니다.\n\n책에 제목은 없지만 스벤이 알고 싶어하는 정보가 들어 있습니다.", progress = "뭘 발견했다고요?? 좀 보여 주십시오...", completion = "&lt;읽던 책을 덮는 스벤&gt;\n\n그자가 내 가족의 죽음을 목격했습니다! 그자에게 물어볼 게 있는데… 대체 어디 가면 찾을 수 있단 말입니까!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[231] = {title = "딸의 사랑", objective = "사라 래디모어의 반지를 모건 래디모어의 무덤으로 가져가야 합니다.", description = "여기 이걸 가져다가 아버지의 무덤에 놓아 주세요. 제가 무사하다는 것과 지금까지 있었던 일들에 대해서 아무도 아버지를 원망하지 않는다는 걸 아시도록 말이에요.\n\n<눈에 눈물이 고인 채로 손가락에서 반지를 빼내 손에 건네주며>\n\n그리고... 감사합니다.", progress = "이곳에 잠든...", completion = "&lt;바람과 함께 유령의 목소리 같은 소리가 들리며&gt;\n\n이...이건... 사라? 내 딸이 살아 있는 건가? 이제 내 어깨를 짓누르던 무거운 짐은 던 것 같군.\n\n내 검 아키우스를 받게나. 편히 잠들게 되었으니 내겐 이제 필요 없는 물건이야. 아주 잘 만들어진 검이지만 나에겐 맞지 않은 검이더군. 자네가 정의를 위해 그 검을 사용해 주었으면 하네.\n\n리즈, 내 사랑...", rewards = "다음과 같은 것들을 받습니다:\n\n아키우스"},
[232] = {title = "연금술사 진게의 심부름", objective = "언더시티에 있는 알렉산드로 루카에게 진게의 구입주문서를 가져가야 합니다.", description = "왕립 연금술 학회에서 당신의 도움을 필요로 하고 있습니다. 내 계획대로라면 우리 둘 다 득을 볼 수 있을 것이니 잘 들으세요.\n\n옆방에 있는 연금술사 키버는 좀... 정신이 이상...할진 몰라도 그의 연구는 똑똑한 연구자의 손에 맡기면 좋은 결과를 얻을 수 있을 겁니다. 다행히도 내가 바로 그런 연구자랍니다. 이 구입주문서를 푸른달 골동품점의 주인, 알렉산드로 루카에게 가져다주세요. 그러면 그가 분석 도구를 하나 줄 것이니 그걸 받으면 내게 가져오세요. 그러면 그때 당신의 임무를 더 자세히 설명해 주도록 하겠습니다.", progress = "안녕하시오. 무슨 일로 오셨소? 왕립 연금술 학회 일로 오셨소, 아니면 그저 날 기쁘게 해 주러 온 것이오?", completion = "아, 진게님께서 분석 도구가 필요하신 모양이군? 진게님께서 직접 찾아와 주지 않으시다니 정말 안타깝군.\n\n좋소. 분석 도구를 하나 마련해 드리지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[233] = {title = "눈마루 골짜기 편지 배달", objective = "편지 뭉치를 탈린 킨아이에게 배달해야 합니다.", description = "흠... 이 부탁을 들어줄지는 모르겠지만. 시간이 없어서 오늘 들어온 편지 뭉치를 배달 못했네.\n\n어디 보자, 받는 사람이 탈린 킨아이 앞으로 되어 있군. 탈린 킨아이는 여기서 서쪽 길을 따라 내려가다 보면 나오는 얼어붙은 호수 옆에서 야영을 하고 있을 걸세.\n\n나 대신 편지를 좀 배달해주겠나?", progress = "응? 나한테 줄 게 있다고?", completion = "고맙네. 정말 오랫동안 기다려 온 편지야...\n\n그런데 전부 나한테 온 편지만 있는 것은 아니군. 음, 이 편지는 그렐린 화이트비어드씨 앞으로 온 것이야. 그렐린 씨는 여기서 그리 멀지 않은 곳에 있다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[234] = {title = "눈마루 골짜기 편지 배달", objective = "편지를 그렐린 화이트비어드에게 배달해야 합니다.", description = "내 기억이 맞는다면 그렐린의 야영지는 여기서 남동쪽 방향으로 가면 있을 걸세. 아마 이 편지를 몹시도 기다리고 있을 테니 어서 가보게나.", progress = "나한테 무슨 용무라도 있나?", completion = "아, 나한테 온 편지를 전해주러 온 게로군. 정말 고맙네! 아이언포지에서 편지를 받아 보는 것도 꽤 오랜만이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[235] = {title = "잿빛 골짜기 사냥 대회", objective = "잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트를 만나야 합니다.", description = "젊은 모험가들이여, 내 말을 잘 들으시오! 잿빛 골짜기의 야생이 당신을 기다리고 있소!\n\n우리 호드는 불모의 땅 북쪽에 튼튼한 기지를 세웠소. 토막나무 주둔지와 조람 해안 주둔지에서는 호드의 이름을 빛내려고 고군분투하고 있는 것이오! 자신을 증명하고 싶은 이는 모두 그곳으로 가서 길을 찾으시오. 불모의 땅 바로 북쪽에 있는 토막나무 주둔지의 세나니 썬더하트가 잿빛 골짜기 사냥 대회에 참가할 모험가를 모집하고 있다오!", progress = nil, completion = "&lt;name&gt;. 새로운 개척지로 오신 것을 환영합니다. 잿빛 골짜기는 당신과 같은 젊은 &lt;class&gt;들이 용기를 시험할 기회를 충분히 제공하고 있습니다. 일단 이곳 주둔지를 살펴본 다음 조람 해안으로 나가보는 것도 잊지 마십시오. 거기 또 다른 호드의 주둔지가 있으니까요.\n\n그나저나 여기까지 온 것을 보니 사냥에 대해 더 많은 것을 배우러 온 것 같은데... 가까이 오십시오. 당신이 원하는 바를 기꺼이 가르쳐 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[236] = {title = "파괴전차 연료 공급", objective = "겨울손아귀 요새에 있는 공성 전문가 스타우트핸들이 불길의 가마솥에 있는 호드 전투원에게서 영원의 불씨 10개를 회수해 달라고 했습니다.", description = "<name>! 이제 슬슬 움직일 시간입니다. 이번 전투는 끝났을지 모르지만, 다음 전투를 대비해야 한답니다. 겨울손아귀의 남동쪽에 있는 불길의 가마솥으로 가서 영원의 불씨를 좀 회수해 오십시오.\n\n그 불씨와 석탄을 섞으면 파괴전차와 공성 전차의 연료로 쓸 수 있습니다.\n\n오, 맞아. 그 가마솥에서 호드 녀석들을 만나게 되면, 주저 말고 처치해서 그들이 지닌 불씨를 가져오세요. 녀석들이 다음 전투에서 유리한 위치를 차지하는 꼴은 볼 수 없잖습니까?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[237] = {title = "왕국 수호", objective = "남쪽 경비탑의 산악경비대 그레이블고가 가루바위일족 망치잡이와 가루바위일족 점쟁이를 각각 10마리씩 처치한 후 그에게 돌아와 보고해 달라고 부탁했습니다.", description = "산악경비대 코블플린트가 당신에 대해 입에 침이 마르도록 칭찬하더군, <class> 친구. 그럼 당신을 믿고 아주 중대한 임무를 맡기도록 하겠소. 드워프 형제들이 얼라이언스 최전선으로부터 돌아올 때까지 침략자 트로그들을 계속 밀어붙여야 하오.\n\n남쪽 언덕으로 가서 가루바위일족 망치잡이 10마리와 가루바위일족 점쟁이 10마리를 처치해 주시오. 그러면 얼마간의 시간을 벌 수 있을 테니까 말이오. 임무를 완수하면 내게 돌아와 알려 주시오.", progress = "우린 시간이 더 필요하오. 당신의 임무는 가루바위일족 망치잡이 10마리와 가루바위일족 점쟁이 10마리를 처치하는 거요. 증원군이 도착할 때까지 적을 견제해 주시오. 잠시라도 고삐를 늦춰서는 안 되오.", completion = "임무를 훌륭히 완수했구려. 폐하께서 자랑스러워하실 거요.\n\n들리는 소식에 의하면 얼라이언스 최전방이 아군의 피로 물들고 있어 약속했던 증원군을 보내지 못할 상황이라고 하오. 매우 안타까운 소식이 아닐 수 없소. 우리는 반드시 이 난국을 극복하고 얼라이언스의 영광을 되찾아 동료들의 희생을 헛되게 하지 않을 것이오.\n\n산악경비대 월뱅을 찾아가 새 임무를 받으시오. 지금이야말로 당신의 도움이 절실히 필요한 때라오.", rewards = "다음과 같은 것들을 받습니다:\n\n하급 치유 물약"},
[238] = {title = "연금술사 진게의 심부름", objective = "언더시티에 있는 연금술사 진게에게 휴대용 분석 도구를 가져가야 합니다.", description = "자, 분석 도구가 준비되었소이다. 분명 연금술사 진게님께서는 최대한 빨리 이걸 받고 싶어하실 것이오. 지체하지 말고 어서 가져다 드리고 이 도구의 비용은 학회의 계산서에 첨부하겠다고 전해 주시오. 아, 내 안부도 함께 전해 주구려.\n\n자, 거기 그냥 그렇게 서 있지 말고 어서 가시오. 심부름꾼의 삶이란 항상 움직여 다녀야 하는 것 아니겠소?", progress = "네, 맞아요. 나도 당신처럼 루카를 별로 탐탁히 여기지 않는답니다. 뭐, 중요한 문제는 아니고 휴대용 분석 도구를 이리 주세요. 적합한 기본 재료에 대한 조사를 하려면 약간의 개조가 필요하답니다.\n\n도구는 가지고 왔죠?", completion = "좋아요. 내 시간을 낭비하지 않는 것에 자부심을 느끼는 자와 일하게 되어 기쁘군요.\n\n내가 이 도구를 조금 개조하고 나면 당신이 밖으로 나가서 이 도구를 사용해 이번 임무에 아주 중요한 자료를 수집할 수 있을 겁니다.\n\n개조는 잠깐이면 끝나니 기다리는 동안 사막에 가져가야 할 물건을 생각해 봐야 할 거예요.\n\n네, 맞아요. 당신이 가야할 곳은 사막이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[239] = {title = "서부 주둔지 지원", objective = "서부 주둔지로 가서 부관 레이너와 대화해야 합니다.", description = "서쪽 경계 지역의 주둔지에서 놀과 도적의 활동이 늘고 있다는 전갈을 보내 왔소. 주둔지에서는 스톰윈드 군대를 보내 달라고 요청해 왔지만 우리도 병력이 부족한 형편이오!\n\n당신이 그들을 도와 준다면 고맙겠소. 서부 주둔지로 가서 부관 레이너를 만나 무엇이 필요한지 알아봐 주시오.\n\n주둔지로 가려면 서쪽 길을 따라 내려가시오. 작은 개울의 다리를 건넌 후 오른쪽으로 가면 되오.", progress = nil, completion = "치안대장 더그한께서 보내셨다고요? 흠, 보아하니 당신은 군인은 아닌 것 같은데... 일단 더그한께서 보내셨다면 믿어 보죠.\n\n상황이 별로 좋지 않습니다. 당신이 우리를 도와주셨으면 합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[240] = {title = "지터스에게 돌아가기", objective = "갈색 게살 케이크를 가지고 지터스에게 돌아가야 합니다.", description = "자, 그루얼식 게살 케이크가 완성되었습니다!", progress = "왔군요! 음식은 가지고 왔나요?!?", completion = "아! 고맙습니다. 음...이거 둘이 먹다 하나가 죽어도 모를 맛이군요!\n\n자 여기, 사례비 받으세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[243] = {title = "사막으로", objective = "분석 도구에 사용할 동력원을 얻기 위해 가젯잔에 있는 선임기술자 빌지위즐과 대화해야 합니다.\n\n제공된 아이템: \n", description = "자, 이제 당신은 타나리스 사막으로 나가서 그곳에 사는 바실리스크, 전갈, 그리고 하이에나의 근육 조직 일관성을 시험해 봐야 합니다. 조직 견본을 구해서 가져간 분석 도구를 이용해 보세요. 견본 시험은 여러 번 실패하게 될 겁니다. 각각의 짐승들에게서 얻은 쓸만한 견본이 9개씩 필요합니다.\n\n그리고 이 개조된 도구를 사용하려면 가젯잔 고블린의 동력원이 필요하니까 선임기술자 빌지위즐에게 얘기해서 도구에 사용할 동력원을 하나 얻도록 하세요.\n\n반드시 성공한 후 내게 돌아오세요.", progress = nil, completion = "아, 우리 모델 4711-FTZ 동력원을 말하는 거군! 보통 우리 우물에 동력을 공급하기 위해 사용하지만 그 몹쓸 유목민 녀석들 덕분에 지금은 동력원이 남아돌고 있단 말이지.\n\n물론, 당신이 나 몰래 어떤 사악한 과학 실험에 사용하려고 하는지 모르겠소만 하나 줄 수는 있지. 하지만 공짜는 아니라고, &lt;race&gt; 친구. 가젯잔에서 공짜란 있을 수 없지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[244] = {title = "놀 침략자", objective = "부관 펠던에게 보고해야 합니다.", description = "안녕하십니까. 전 이 도로를 순찰하는 임무를 맡고 있습니다. 아직까진 별 탈 없었는데 며칠 전 북쪽과 동쪽에서 놀 야영지를 목격했습니다.\n\n놀이 병력을 소집하고 있다는 것을 레이크샤이어에 알려야 합니다! 레이크샤이어의 펠던님께 이 사실을 보고해 주시기 바랍니다. 대의원님께서 정찰병 임금 정도는 지급해 주실 테니 걱정하지 마시고요.\n\n펠턴님은 주로 레이크샤이어 다리의 남쪽 지역을 순찰하고 계십니다.", progress = nil, completion = "엘윈에서 그렇게 가까운 곳에 붉은마루일족 놀들이 있다고?? 이런, 이곳으로 공격해 들어올 모양이군. 조만간 레이크샤이어 이외의 인간 지역도 공격을 받게 될 것이 분명하오!\n\n자, 이걸 받으시오. 불길한 소식이긴 하지만 정보를 제공한 대가는 지급해야지. 하필 지금처럼 방어가 취약할 때 이런 일이 일어나다니...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[245] = {title = "거미의 위협", objective = "새끼 그물독거미 15마리를 처치한 후 그늘숲에 있는 순찰대원 도즈에게 보고해야 합니다.", description = "안녕하십니까, <class>|1이여;여;. 서쪽 변방에 들끓는 거미들을 본 적 있습니까? 우리들만으로 다리 여덟 달린 그 괴물들을 처치하기에는 버겁지만 그렇다고 해서 다크샤이어에서 멀리 떨어진 이곳까지 지원군을 보내기에는 사령관님께서 지휘하시는 병력이 턱없이 부족합니다.\n\n이런 부탁을 해서 미안하지만, 놈들을 좀 처치해 주지 않으시겠습니까? 큰 보상을 약속할 수는 없지만, 그 고약한 벌레들을 처리해 준다면 사례는 분명히 하도록 하겠습니다.\n\n아, 그리고 한 가지 충고하지요. 녀석들의 독액을 조심하시기 바랍니다.", progress = nil, completion = "오! 돌아왔군요. 보아하니 심하게 지치진 않은 것같아 다행입니다. 어둠의 순찰대는 당신의 공로에 진심으로 감사하고 있으며 이건 약속한 사례입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n어둠의 순찰대 건틀릿"},
[246] = {title = "탐색전", objective = "붉은마루일족 싸움꾼 10마리, 붉은마루일족 밀렵꾼 6마리를 처치하고 레이크샤이어에 있는 부관 펠던에게 돌아가 보고해야 합니다.", description = "현재 따로 병력을 편성할 수 없는데다가 그 놀들을 그대로 둘 수도 없는 노릇이니 큰일이군.\n\n붉은마루 산맥 남쪽에 있는 놀들의 정보를 수집해 주시오. 정보를 수집하는 동안 눈에 띄는 놈들을 처치하고 가능하면 숫자를 줄여서 적의 병력이 어느 정도이고 얼마나 강한지 보고해 주시오. 붉은마루 산맥 남쪽 길로 쭉 가면 야영 중인 놀들을 찾을 수 있을 것이오.\n\n스톰윈드 군대를 위해 이 임무를 수행해 주면 보상하도록 하겠소.", progress = nil, completion = "&lt;보고를 듣는 부관 펠던&gt;\n\n음... 듣자하니 병력도 제법 되고 만만한 상대도 아닌 것 같군. 이 정도 정보를 알아내기도 쉬운 일이 아니었겠소.\n\n자, 이걸 받으시오. 도와 줘서 고맙소.\n\n혹시 레이크샤이어에 있는 치안대장 매리스님이나 집정관 솔로몬님과 얘기해 보지 않았다면 그 분들을 만나보도록 하시오. 점점 상황이 절망적인 사태로 치닫고 있는 이 시점에서 당신의 도움이 절실할 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[247] = {title = "사냥 대성공", objective = "<name>, 당신은 잿빛 골짜기 사냥 대회의 목표물인 세 마리 야수를 모두 해치웠습니다. 놈들의 죽음을 증명하는 전리품까지 가져왔으니 칭송받아 마땅합니다. 당신이 가진 불굴의 투혼과 강인한 체력은 의심할 여지가 없군요. 당신의 혈관에는 사냥꾼의 피가 흐르고 있는 것이 분명합니다!\n\n오늘 잿빛 골짜기에서 당신이 호드를 위해 세운 업적은 실로 큰 것이었습니다. 그 보답으로 이것을 드리겠습니다. 선조께서 당신의 앞날을 지켜주시기를!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n수렵꾼 망토"},
[248] = {title = "자세한 조사", objective = "돌망루 요새 옆에 있는 감시탑에 올라가야 합니다.\n\n그곳에서 아조라의 조각상을 넣어 두기에 적합한 용기를 찾아야 합니다.", description = "아조라의 조각상을 통해 일갈라의 탑를 지켜보니 모건스가 돌망루 요새의 오크들과 싸우고 있더군. 싸움의 이유를 모르겠네만 자네가 이 비밀을 밝히는 걸 도와 주리라 믿네.\n\n다른 아조라의 조각상을 가지고 돌망루 요새 옆에 있는 감시탑의 꼭대기로 가게나.\n\n그곳에서 적합한 장소를 찾아 그 위에 조각상을 설치하면 된다네. 상자나 단지처럼 조각상이 쉽게 눈에 띄지 않는 장소라면 충분하네.", progress = "이 단지에는 지독한 냄새가 나는 액체가 담겨 있었지만 지금은 비어 있고 통 위에 버려져 있습니다.", completion = "이 단지는 돌망루 요새 내부에 있는 모건스의 의중을 파악하기 위해 테오크리투스가 준 아조라의 조각상을 숨기기에 적합합니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[249] = {title = "모건스", objective = "모건스를 처치하십시오.\n\n엘윈 숲의 아조라의 탑에 있는 테오크리투스에게 그림자 펜던트를 가져가야 합니다.", description = "아조라의 조각상을 통해 좀 더 감시한 결과 드디어 모건스의 계획을 알아냈네.\n\n이미 발견했을 지도 모르지만... 그는 엘룬의 낫을 찾고 있네! 모건스가 엘룬의 낫을 손에 넣었다면 붉은마루 산맥과 스톰윈드 전역에 어두운 힘이 뻗치게 될 걸세.\n\n지금 당장 모건스를 막아야 하네만 불행히도 나는 그와 싸울 준비가 안 되었네. 그러니 자네가 일갈라의 탑으로 들어가 모건스를 상대해 주게나.\n\n그를 쓰러뜨리고 모건스가 지니고 있는 그림자 펜던트를 가져다주게. 그러면 자네 손으로 스톰윈드 왕국을 구하게 될 걸세.", progress = "서두르게. 그렇지 않으면 우려하던 것처럼 모건스의 사악한 힘이 온 세상에 뻗치기 시작할 걸세!", completion = "정말 장하네. 흑마법사 모건스가 죽었으니 이제 스톰윈드는 최악의 상황을 면하게 되었군.\n\n그동안 자네가 고생한 것에는 비교할 수 없겠지만 이 작은 성의를 받아 주게나. 지금이 평화로운 시대라면 자네의 마음이 항상 평온하기를 기원했겠지만...\n\n대신 앞으로의 여정에 행운이 함께하고 전투에서 승리하기를 기원하겠네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n장미 어깨보호대"},
[250] = {title = "어둠의 전조", objective = "댐의 동쪽 사면 근처를 정찰하고 검은무쇠단 드워프의 음모를 밝힐만한 단서를 찾아 선임기술자 힌더바이르에게 가져가야 합니다.", description = "우리 댐의 안전을 걱정해 주는 이가 있다니 얼마나 반가운지 모르겠네. 처음엔 탄돌 교각이 파괴되더니 다음엔 던 모드르가 약탈당하고... 검은무쇠단 드워프의 다음 목표는 분명 댐일 거야. 불행히도 내 상관인 감독관님을 포함해서 방어 병력 대부분이 얼라이언스 최전선에 배치되어 있는 상황이네.\n\n그래서 자네의 도움이 절실히 필요해. 며칠 전 검은무쇠단 공병들이 댐의 동쪽 사면을 굴착하는 것을 보았네. 그 지역을 정찰하고 뭔가 수상한 것이 있으면 가져다주게.", progress = nil, completion = "뭔가 수상스러운 이 통에는 이상한 향기가 나는 가루가 들어 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[251] = {title = "에이버크롬비의 편지 번역", objective = "시라 본인디에게 엘로에게 보내는 편지를 가져가야 합니다.", description = "자네가 가져온 이 편지를 시라 본인디에게 가져가게. 그는 고대 언어와 예술에 능통한 친구지. 이 마을에서 이걸 번역할 수 있는 사람이 있다면 그 뿐일 걸세.", progress = "은둔자 에이버크롬비가 쓴 편지란 말입니까? 난 그를 모르지만 묘지 한복판에 살고 있는 걸 보면 정신이 나간 자가 분명합니다!", completion = "&lt;편지를 번역하기 시작하는 시라...&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[252] = {title = "엘로 이본로크 경에게 편지 전달", objective = "엘로 이본로크 경에게 번역된 편지를 가져가야 합니다.", description = "오, 이런! 이 편지에 쓰인 내용이 사실이라면 에이버크롬비가 뭔가 대단히 사악한 짓을 저지른 게 틀림없습니다.\n\n이 번역된 편지를 서둘러 시장님께 전해주시기 바랍니다. 벌써 우리 마을에 불길한 기운이 찾아들고 있는 것 같으니 서두르세요!", progress = "그래, 편지는 번역됐나? 어디 한번 보세...", completion = "&lt;편지를 읽고 얼굴이 창백해진 엘로 이본로크가 당신을 쳐다보며&gt;\n\n자네가 에이버크롬비를 도운 것은 친절을 베풀기 위한 것이었을 테지만, 그 때문에 우리 마을이 위험에 처하게 됐군.\n\n&lt;생각에 잠기는 엘로 이본로크...&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n장의사가 보낸 번역된 편지"},
[253] = {title = "장의사의 신부", objective = "엘리자의 무덤을 찾아 그녀의 몸에서 장의사의 심장을 찾아 엘로 이본로크 경에게 가져가야 합니다.", description = "아이들 사이에서 전해지는 이야기에는 장의사라는 인물이 등장하네. 그는 원래는 착한 연금술사였지만 아내 엘리자가 죽자 미쳐 버렸지. 그는 아내를 부활시키기 위해 흑마법을 사용하여 자기 심장을 죽은 아내의 몸에 넣었다네.\n\n엘리자가 되살아나긴 했지만... 장의사는 저주를 받아 인육에 굶주려 하는 그녀를 다시 묻을 수밖에 없었다네.\n\n그의 심장은 곧 그의 힘이지. 장의사의 아내 무덤에서 심장을 찾아 박동이 멎기 전에 내게 가져오게. 그러면 그의 힘을 빼앗을 수 있을 걸세.", progress = "벌써 엘리자의 무덤은 찾았는가? 장의사의 심장은 얻었나?", completion = "오, 해냈군그래! 이 심장에 걸려 있는 마법이 장의사의 악행과 다크샤이어에 드리워진 강력한 악의 세력에 대한 증거가 될 걸세.\n\n이곳 시민들을 위해 큰일을 해 주었네. 자네 이름은 우리 역사에 길이 남게 될 걸세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n명예의 어깨보호대다크샤이어 문장방패"},
[254] = {title = "무덤 파기", objective = "반쯤 파헤쳐진 무덤을 파내고 관을 발견합니다.\n\n관 속에서는 날카로운 손톱으로 긁는 소리와 썩은 이빨 가는 소리가 들립니다...\n\n관을 열고 장의사의 심장을 꺼내시겠습니까?", description = nil, progress = nil, completion = nil, rewards = nil},
[255] = {title = "용병", objective = "텔사마의 집정관 블런트노즈가 모그로쉬 오우거 4마리, 모그로쉬일족 투사 4마리와 모그로쉬일족 집행자 4마리를 처치하기 위해 당신을 고용했습니다.", description = "아이언포지에서 이곳을 방어할 소수의 증원군을 보낸다는 확답을 듣는 데 두 달이 걸렸소. 또 그들이 도착하는데는 두 달이 더 걸리지. 이 마을은 무방비 상태인데, 설상가상으로 발굴 지역과 댐까지 공격에 노출돼 있으니 최악의 상황이 아닐 수 없소. 그러니 용병을 고용하는 수밖에 달리 선택의 여지가 없소.\n\n당신은 어떤가? 내가 보기엔 당신이 이 일에 꼭 맞는 <class> 같소만. 오우거 무리의 야영지는 호수 북동쪽에 있소. 당신이 용병들을 더 모집해서 우리 마을의 위협을 제거해 주지 않겠소?", progress = nil, completion = "오, 참으로 훌륭하오! 텔사마의 모든 주민들이 당신의 공로에 진심으로 감사하고 있소. 오우거를 퇴치해준 덕분에 우린 가루바위 트로그 처치에 전념할 수 있을 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[256] = {title = "초크술 현상수배", objective = "초크술을 처치하고 그 증거로 그의 머리카락을 텔사마의 집정관 블런트노즈에게 가져가야 합니다.", description = "텔사마 집정관의 명령:\n\n오우거 우두머리인 초크술이 텔사마를 비롯해 돌다지 댐과 발굴 지역 공격을 지휘하고 있다고 한다. 모든 수단과 방법을 동원하여 그를 처치하라.\n\n집정관에게 초크술을 처치한 증거를 가져오는 이에게는 보상금이 지급될 것이다.\n\n초크술은 모단 호수 북동 지역 오우거 야영지에서 마지막으로 목격되었다.", progress = "내가 도와줄 일이라도 있소?", completion = "윽! 대체 그게 뭐요? 어쩌자고 이런 걸 가져온 거요?\n\n그런 악취가 나는 물건을... 여기 불 좀 비춰봐! 아, 이게 그 괘씸한 오우거 놈의 머리카락이란 말이오? 그렇다면, 대단한 성과인걸! 자, 여기 보상금을 받으시오. 그리고 텔사마 주민을 대신해 정말 감사하오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n튼튼한 사슬 어깨보호구킴브라 장화\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n최하급 집중력의 반지"},
[257] = {title = "사냥꾼의 허세", objective = "산악대머리수리 6마리를 처치한 후 순찰자의 오두막에 있는 풋내기 다릴에게 15분 안에 돌아와야 합니다.", description = "당신이 이 용감한 다릴만큼 뛰어나다고 생각하쇼? 어림 없는 소리! 뭐, 그래도 도전은 언제나 환영입니다. 자, 그럼 내기 하나 할까요? 결국 당신이 능력 부족이라는 사실만 확인하게 되겠지만 말이지. 실패하더라도 너무 상심하진 마슈.\n\n이곳 모단 호수 지역엔 대머리수리 떼가 둥지를 틀고 있습니다. 그걸 몇 마리 잡아와 보시는 게 어떻겠소? 참, 15분 내에 해낼 수 있다면 내 활이나 총을 드리죠.\n\n<거만하게 쳐다보는 다릴>\n\n뭐, 당신이 손해 볼 건 없겠죠?", progress = "운이 따라주지 않나보군요? 너무 상심하지는 마쇼.\n\n나만한 실력을 갖추는 게 그렇게 만만한 일은 아니니까...", completion = "뭐? 성공이라고?\n\n이런! 자, 가져가쇼. 그렇다고 너무 우쭐해 하지는 마시오! 수염도 안 난 어린애라도 활만 있으면 그런 일쯤은 할 수 있으니까. 그리고 대머리수리를 너무 많이 죽이지 말라고. 우린 대머리수리가 멸종하는 건 원치 않으니까.\n\n흠... 행여라도 이 용감한 다릴이 약속을 안 지켰다는 소린 듣기 싫으니, 어서 가지고 가시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n다릴의 사냥활다릴의 사냥용 라이플\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[258] = {title = "사냥꾼의 도전", objective = "덩치큰 산돼지 5마리를 처치한 후 순찰자의 오두막에 있는 풋내기 다릴에게 12분 내에 돌아와야 합니다.", description = "또? 보아하니 첫 번째 도전을 통과했다고 신이 난 모양이군요. 하지만 전에도 말했듯이 그건 자랑삼아 떠벌릴 일도 못됩니다.\n\n그럼 이번엔 산돼지 사냥을 한번 맡겨보도록 하겠습니다. 눈마루 골짜기 멧돼지와는 차원이 다를 테니 조심하는 게 좋을 겁니다. 이번엔 12분을 주도록 하죠.\n\n실패하더라도 너무 상심할 필요는 없습니다. 행여나 성공해 돌아오면 입고 있는 셔츠라도 벗어 드릴 수 있습니다.\n\n제 몸에 난 이 상처에 대해 얘기한 적 있던가요? 2년 전이었는데...", progress = "세상엔 당신보다 뛰어난 사람이 많소. 그러나 너무 풀이 죽어 있을 필요는 없지... 너무 소심할 필요는 없지.\n\n흠, 당신 이름이 <name> 맞던가?", completion = "많이 지쳐 보이는군요. 산돼지 때문에 많이 힘들었습니까? 소문을 내거나 하지는 않을 테니 걱정 마시오. 지금 당신이 얼마나 힘들어 하는지 아는데 창피한 소문까지 낼 수는 없죠.\n\n뭐라고요? 지금 산돼지를 처치했다고 말했습니까? 어.. 난... 뭐... 별로 놀라운 일은 아니군요. 어린애라도 그 정도 내기에는 이길 수 있습니다! 맞아, 내기?\n\n그런데 무슨 내기였지?", rewards = "다음과 같은 것들을 받습니다:\n\n고급 헝겊 셔츠다릴의 쇼트소드"},
[261] = {title = "붉은십자군의 길", objective = "언데드 약탈자 30마리를 처치한 후 나이젤의 야영지에 있는 수사 안톤에게 돌아가야 합니다.", description = "<class>|1이여;여;, 할 얘기가 있으니 이리 가까이 오십시오. 흠... 솔직히 얘기하도록 하겠습니다. 지금 우리는 우리 주민을 타락시키고 우리의 땅을 오염시키는 악의 무리, 스컬지와 전쟁 중입니다. 스컬지가 우리를 괴멸시키고 이 세상을 암흑으로 끌고 가기 전에 막아야 합니다. 우리, 붉은십자군은 몸과 마음을 다해 스컬지와 싸울 것을 맹세했습니다.\n\n<형제/자매>도 우리와 함께하겠다면 용기를 내어 충의를 증명해 보여주십시오. 잊혀진 땅 남쪽에 있는 뼈의 골짜기에서 언데드 약탈자들을 처치해 주십시오.\n\n이를 수행하면 붉은십자군에서 <형제/자매>를 기꺼이 받아들일 것입니다.", progress = nil, completion = "형제의 결심을 증명해 주셨으며 붉은십자군의 칭송을 받을 만합니다.\n\n그러한 학살을 행하고도 부끄럼이 없다면 이제부터 형제는 우리의 일원입니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[262] = {title = "의문의 남자", objective = "다크샤이어의 마을 주민들에게 스벤의 농장에서 발견한 책을 보여 줘야 합니다.", description = "내 가족이 몰살당한 날 밤, 그림자 속에서 서성대던 그자가 누구인지 알아 내야겠습니다!\n\n제발, 한 번 더 당신 실력을 발휘해서 그자를 찾아주십시오. 그가 무엇을 숨기고 있었는지 알아내야 합니다!\n\n당신이 알고 있는 것 말고는 나도 별다른 단서가 없으니 내 농장에서 발견한 책을 가져가십시오. 마을 사람 중에서 이 책의 주인이 누구인지 아는 사람이 있을 수도 있을 겁니다.", progress = "찾고 있다는 그 유령 같은 얼굴을 한 자의 물건이 있다면 어디 한번 볼까? 책의 주인에 대해 무언가 알아낼 수 있을지도 모른다네.", completion = "음... 복수심에 불타는 누군가가 최근에 이 책을 만졌군그래. 이 책에 남아 있는 느낌, 원래 주인의 느낌은 아주 희미해.\n\n그래도 이 책의 원래 주인이 다크샤이어 태생이 아닌 것은 분명하군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[263] = {title = "왕국 수호", objective = "남쪽 경비탑의 산악경비대 월뱅이 가루바위일족 주술사 10명과 가루바위일족 뼈다귀싸움꾼 10명을 처치해 달라고 부탁했습니다.", description = "많은 산악경비원들이 당신을 매우 실력 있는 친구라고 칭찬하더군. 여긴 당신과 같은 용감한 <race>|1이;가; 절실히 필요하다오. 예비 사단은 전방으로 배치되어 가고 여긴 우리들뿐이라오. 그러니 트로그를 상대로 한 싸움은 나아질 기미도 보이지 않을 수밖에... 하지만 이제 자네 같은 유능한 <class>|1이;가; 왔으니 실력을 보여 주시오.\n\n가서 가루바위일족 주술사 10마리와 가루바위일족 뼈다귀싸움꾼 10마리를 처치해주시오. 어디, 명성이 사실인지 한번 보도록 하겠소. 트로그 사냥꾼.", progress = nil, completion = "두 번째로 당신을 봤을 때 두 눈에서 투지가 불타는 걸 엿봤소. 그때 이미 아이언포지의 자랑이 될 거란 사실을 알았지. 마그니 폐하께서도 자랑스러워하실 거요. 이제 자네가 왕국에 얼마나 필요한 사람인지 스스로 증명했으니, 경비대장님을 찾아가 보도록 하시오. 그 분께서 자네를 믿고 더 중요한 임무를 맡기실지 모르니...\n\n당신에게 경의를 표하고 싶군요.", rewards = "다음과 같은 것들을 받습니다:\n\n일반 숫돌"},
[264] = {title = "영원한 이별", objective = "은빛소나무 숲에 있는 유리브의 무덤에 클라리스의 펜던트를 가져다 놓아야 합니다.", description = "나쁜 사람 같으니! 그놈의 십자군때문에 날 두고 가버리다니... \"언데드의 위협에 맞서는데 있어 가장 중요한 건 바로 신성한 정의!\"이기 때문이라고?\n\n그럼, 아이들은 어떻게 되는 거지?! 또 나는? 매일 밤 울면서 기다려 왔는데... 언제나 나보단 그 몹쓸 임무가 먼저라니!\n\n도대체 그놈의 \"정의\"가 우리에게 뭘 가져다주는지 한번 지켜 보겠어! 그이는 죽었고 나는 그이가 막으려던 그 악몽을 견디며 살아야 하다니!\n\n이 쓰레기 같은 물건들을 공동묘지에 있는 그이 무덤에 가져다 줘 버리세요. 이제 내겐 이 물건들도, 그이도 다 필요 없으니까요!", progress = "묘비는 만지기에는 차갑지만 분명히 누군가 함부로 다룬 것 같습니다. 주변에는 쓰레기가 어지럽게 널려 있고 관 위에 양각된 조각은 흠집이 나고 갈라져 있습니다. 그리고 무덤 주위의 나뭇잎이 우거져 무덤 위를 덮기 시작했습니다.\n\n이곳에 누가 묻혀 있는지 신경쓰는 이는 아무도 없습니다. 특히, 역병의 희생자들은...", completion = "쓸모없는 펜던트를 무덤 위에 놓습니다. 펜던트에 박혀 있는 보석은 확연히 빛이 바래 보입니다.\n\n떠나기 위해 일어서면서 펜던트를 내려다봅니다. 펜던트는 관 위에 양각되어 있는 손에 가만히 놓여 있습니다. 공동묘지를 스쳐 지나는 강하고 차가운 바람에 잠시 동안 잠겨 있던 생각에서 벗어납니다. 순간 주변의 모든 것이 정적에 휩싸입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[265] = {title = "계속되는 조사", objective = "다른 마을 주민에게서 의문의 남자에 대한 정보를 알아봐야 합니다.", description = "자, 이 책을 도로 가져가게. 그대가 꼭 그 사람을 찾게 되길 빌어 줌세. 다른 마을 주민에게 물어보면 또 다른 단서를 얻을지도 몰라.\n\n그리고 한 가지 더... 이 책을 쓴 사람은 다크샤이어 외부 사람이지만 책 자체는 이곳에서 구입한 것이야.", progress = "안녕하십니까. 저는 학자와 마법사, 혹은 일기를 쓰려는 사람들에게 백지로 된 책을 종종 팔고 있답니다.\n\n최근 몇 달간 책을 사 간 사람들은 충분히 기억할 수 있습니다만...", completion = "아, 기억납니다. 몇 달 전에 이 책을 수상한 사람에게 팔았어요. 자기 이름도 말하지 않고 신경질적인데다 항상 어깨 너머로 남들을 살펴보는 신경 과민 증상을 보이는 사람이었죠.\n\n이게 도움이 되었으면 좋겠군요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[266] = {title = "여관에서의 조사", objective = "여관에서 의문의 남자에 대한 정보를 얻으십시오.", description = "자, 책 여기 있습니다. 그리고 조사가 잘 이뤄지길 바랍니다.\n\n여관에 가서 더 알아보는 건 어떻습니까? 당신이 찾는 사람이 이 마을에서 지냈다면 누군가 여관에서 그를 보았을 가능성이 있을 테니까 말입니다.", progress = "진홍 까마귀 선술집은 예전만큼 장사가 잘 되지는 않지만, 그래도 여전히 지나가는 여행자들이 투숙을 하곤 하지요.\n\n찾고 있는 분의 인상착의를 설명해 보시면 기억해 낼 수도 있을 겁니다.", completion = "아, 이 책 기억납니다. 이 책의 주인이 며칠 간 방을 빌렸었는데 밤마다 식탁에 앉아 글을 썼었지요.\n\n나중에는 자기가 무언가에 쫓기고 있다고 중얼대며 급히 마을을 떠나더군요. 그를 마지막으로 본 건 새로운 은신처를 찾아 마을 서쪽으로 가는 것이었습니다.\n\n서쪽 방면이었으니 아마 일단은 까마귀 언덕으로 갔을 것 같은데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[267] = {title = "트로그의 위협", objective = "남쪽 경비탑에 있는 경비대장 루겔퍼스에게 트로그의 단단한 이빨 8개를 가져가야 합니다.", description = "자네도 지금 트로그가 드워프의 땅에 위협이 되고 있다는 것을 알고 있겠지? 현재 아이언포지 예비 사단이 얼라이언스 최전선에 배치된 상황이라 이 지역을 방어할 병력이 부족한 상태라네. 내가 지휘하는 연대는 이 문을 지키는 것이 임무라, 언덕에 숨어있는 저 괘씸한 트로그놈들을 처리하고 싶어도 섣불리 나설 수 없는 노릇이네.\n\n저 괘씸한 트로그놈들을 처리해야겠는데... 자네가 이번 임무를 맡아서 트로그놈들에게 뜨거운 맛을 보여주게나. 그리고 증거물로 트로그의 단단한 이빨 8개를 가지고 오게.", progress = "트로그의 단단한 이빨 8개를 가져왔나? 아니라면 자네 임무는 아직 끝난 게 아니야.", completion = "굉장하군. 우리 땅을 지켜줬으니 드워프족에 큰 공을 세운 거네. 마그니 브론즈비어드 국왕께서도 자랑스러워하실 게야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[268] = {title = "스벤에게 돌아가기", objective = "완성된 지터스의 일지를 가지고 스벤에게 돌아가야 합니다.", description = "당신이 발견한 건 반밖에 못 쓴 겁니다. 스벤의 농장에서 도망칠 때 두고 올 수밖에 없어서...\n\n자, 이 완성된 일지를 스벤에게 가져다주시기 바랍니다. 그의 농장에서 일어난 일을 전부 다 기록해 놓았습니다.\n\n이 일지가 지난 몇 주 동안 나와 함께 한 유일한 친구였지만, 이 책을 포기해야만 분노에 눈먼 스벤과 마주치는 것을 피할 수 있다면 두 말 할 필요 없이 내놓도록 하죠!", progress = "그자가 누구인지 알아냈습니까?", completion = "일지를 보니까 다 알겠군요. 흑기사 놈들을 가만두지 않겠어요! 그늘숲에서 녀석들을 봤는데 버려진 흉가에서 모벤트 펠 마법사와 얘기를 나누고 있더군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[269] = {title = "지혜의 추구", objective = "스톰윈드에 있는 주교 파딩에게 완성된 지터스의 일지를 보여 줘야 합니다.", description = "스톰윈드로 가서 빛의 대성당에 있는 파딩 주교님과 대화해 보시기 바랍니다. 그분께 지터스의 일지를 보여 주고 모벤트 펠을 상대하겠다고 얘기하십시오.\n\n스톰윈드는 다크샤이어를 저버렸지만 주교께서는 인도적이고 매우 지혜로운 분이시니 당신이 우리를 구할 수 있도록 도와 주실 겁니다.\n\n당신의 임무는 위험천만하지만 서둘러 주시기 바랍니다. 시간이 지날수록 그늘숲의 그림자는 점점 커져 가고 있습니다.", progress = "편히 쉬시오, 형제여. 먼 길을 여행하고 무거운 책임을 지고 있는 게 보이는구려. 저 어두운 그림자가 무슨 염려를 끼치고 있는지 말해 주시겠소?", completion = "&lt;일지를 읽고 앞으로의 계획을 들은 후...&gt;\n\n이미 악의 손에 넘어간 그늘숲 내부에는 어두운 기운이 확고하게 자리 잡고 있소. 이에 대적할 수 있는 당신과 같은 영웅이 있다는 것만으로도 신께 감사드리오.\n\n하지만 앞으로 다가올 시련에 먼저 준비해야 할 것이 있소. 강령술사 모벤트 펠은 매우 강력하며 어둠의 마법을 이용하여 물리적인 공격으로부터 자신을 보호할 수 있는 자요. 그를 무찌를 계획이라면 이러한 보호 마법을 깨뜨릴 수 있는 무기가 필요하오이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[270] = {title = "저주받은 함대", objective = "저습지에 있는 메네실 항구로 가서 글로린 스틸브로우와 대화해야 합니다.", description = "몇 해 전 쿨 티라스의 제 3함대가 드워프 왕국 아이언포지의 북쪽에 넓게 펼쳐진 저습지의 해안가에서 침몰했소이다. 그 중 한 척의 배에 라이트포지 철이 실려 있었소.\n\n이 금속은 우리에게 매우 중요하오. 라이트포지 철로 만든 물건은 거룩한 진실의 힘을 발휘하기 때문이오이다. <형제/자매>께서 모벤트 펠을 상대할 생각이라면 그런 무기가 필요할 것이오.\n\n메네실 항구로 가서 나의 드워프 동료인 글로린 스틸브로우와 얘기해 보시오. 그 잃어버린 금속을 찾을 수 있다면 그가 위치를 알고 있을 것이오.", progress = nil, completion = "라이트포지 철이 귀중한 금속이기는 하지만 자네 임무는 정말 힘들 것 같군. 어쨌든 먼길을 오느라 수고했네. 행운이 따른다면 찾고 있는 걸 발견할 수도 있겠지!\n\n그리고 자네가 광석을 찾을 수만 있다면 자네가 말한 그늘숲에 있는 그 강령술사에 대적할 수 있는 무기를 만들 수 있는 사람을 내가 알고 있네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[271] = {title = "바이린의 복수", objective = "늙은곰 수티를 처치하고 그 결과를 순찰자의 오두막에 있는 풋내기 다릴에게 보여 주어야 합니다.", description = "거만한 다릴의 콧대를 꺾을 수 있는 일이 있는데 혹시 관심 있으세요? 인정하긴 싫지만 다릴이 잘난 체가 심하긴 해도 기술은 뛰어나잖아요.\n\n1년 전 큰 곰 한 마리가 순찰자의 오두막의 주요 표적이 된 적이 있었지만 어떤 사냥꾼도 그 괴물을 잡지는 못했죠. 물론 다릴도 최선을 다했지만 얻은 거라곤 눈 위의 그 흉한 상처뿐이었어요.\n\n그 곰을 잡으면 다릴도 할 말을 잃을 거예요.\n\n늙은곰 수티라는 그 곰은 텔사마 너머 언덕 주위에 있는 굴 근처에 있어요.", progress = "아, 당신이군! 또 왔습니까? 사냥을 나갔다 왔나 보군요. 뭐, 지금 실력이 모자란다고 너무 낙담하지는 말라니까요. 계속 노력하다 보면 점점 나아질 겁니다.\n\n어쨌든 지금보다 실력이 나쁠 수는 없지 않나요?", completion = "이... 이게 뭐지? 보아 하니 곰의 머리 같긴 한데...\n\n&lt;자신도 모르게 상처를 만지며&gt;\n\n음, 뭔가 재미있는 걸 잡아왔군요. 그게 그... 그 곰일 리는 없어.\n\n&lt;천천히 뒤로 물러나, 몸을 부들부들 떨면서&gt;\n\n아아, 저... 저리 치워, 어서! 그 소름 끼치는 녀석을 어서 치우라고!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[272] = {title = "바다표범의 시험", objective = "민첩성의 바다 펜던트 반쪽과 인내의 바다 펜던트 반쪽을 찾아야 합니다. 달의 숲 주민들에게서 이 물건들이 있을 만한 위치에 대한 단서를 얻으십시오.\n\n두 개의 반쪽을 찾아 바다표범의 펜던트를 만들어야 합니다. 반드시 레물로스의 제단 근처로 와야만 하나로 합칠 수 있습니다.\n\n완성된 바다표범의 펜던트를 달의 숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈에게 가져가십시오.", description = "이제 두 번째 시험으로 반으로 쪼개진 바다표범의 펜던트 두 개를 찾아야 합니다. 하나는 물에서 미끄러지듯 움직이는 바다표범의 민첩성을 끌어 모으고, 다른 하나는 바다표범의 엄청난 지구력과 인내를 끌어 모으죠. 드루이드는 이 두 가지 특징을 모두 모아 바다표범으로 변신합니다.\n\n펜던트 조각들의 위치를 알아보려면 달의 숲 주민들에게 물어 보세요. 두 조각을 이곳으로 가져와서 하나로 합친 다음, 완성된 펜던트를 덴드리트 스타블레이즈에게 가져가도록 하세요.", progress = "<name>, 펜던트는 만들었습니까? 그걸 좀 연구해 볼 필요가 있겠는데... 두 개의 위치를 알아내는 데 도움이 필요하다면, 주민들에게 한번 물어보십시오. 그대가 원하는 정보를 알려줄 뿐만 아니라, 이 불가사의하고 성스러운 숲을 탐험하도록 길을 인도할 테니까요.", completion = "&lt;name&gt;, 바다표범의 시험을 통과한 것을 축하합니다.\n\n펜던트를 얻기 위해 수행한 임무를 통해, 그대는 물속에서는 민첩성과 인내심, 모두 필요하다는 걸 아셨겠지요. 어느 한쪽이 없으면 다른 한쪽도 존재할 수 없습니다. 그리고 바다표범의 상을 닮으려는 그대의 의지가 없이는 불가능하지요.\n\n제 말을 잘 기억하여 바다표범으로 변신하게 되거든 이 교훈을 믿고 의지하도록 하십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[273] = {title = "물자 공급 재개", objective = "훌다르와 대화하십시오.", description = "그리 늦은 건 아니니 지금이라도 훌다르를 찾아 보시오. 무거운 짐을 짊어지고 가는 데다 미란과 사옌 만큼 힘이 센 것도 아니라 멀리 가지는 못했을 거요.\n\n그들은 늘 다니던 길로 가고 있소. 마을의 남쪽으로 가서 모단 호수의 굽은 길을 따라가 보시오.\n\n이미 목적지에 도착하지만 않았다면 쉽게 찾을 수 있을 거요.", progress = nil, completion = "흥, 검은무쇠단 드워프 따위가 매복해 있다고 해서 운반을 포기할 수는 없지!\n\n그런데 사옌이 놈들과 한패였다니... 같이 일한 지 1년이 다 됐지만 전혀 눈치도 못 챘었는데...\n\n음, 내막은 차차 확인해 보도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[274] = {title = "어둠의 전조", objective = "애실런 스톤스머크가 선임기술자 힌더바이르에게 돌아가 새로 발견한 사실을 알려 줄 것을 부탁했습니다.", description = "이건 보통 화약이 아니오. 이 은빛 결정들을 좀 보라고. 이... 특이한 향도 한번 맡아 보시오. 이건 분명 시포리움 화약이오! 보통 상태의 시포리움은 전혀 해롭지 않지만 젖으면 아이언포지 전체를 산 너머로 날려 버릴 정도로 파괴력이 굉장하다오.\n\n럴커의 독액, 모그로쉬 수정 가루, 악어 눈물, 그리고 중화 콜로이드 용액, 이 네 가지 물질을 섞으면 시포리움의 화학 반응을 억제할 수 있소. 자, 너무 늦기 전에 힌더바이르에게 이 사실을 알려주시오, 어서!", progress = "애실런에게서 뭔가 알아왔나?", completion = "시포리움에 사용되는 중화 콜로이드라고? 이거 정말 야단났군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[275] = {title = "대지의 상처", objective = "수렁이끼괴물 12마리를 처치한 다음 저습지에 있는 신록의수호자 레시엘에게 돌아가야 합니다.", description = "이유는 모르겠지만 저습지 전체가 곪아 신음하고 열병을 옮기는 수렁이끼괴물의 수가 늘어나고 있다. 이 땅이 더는 열병으로 신음하지 않도록 하려면 반드시 놈들을 몰아내어 다시 늪으로 돌려보내야 하느니라.\n\n수렁이끼괴물들은 저습지의 수로 한복판을 돌아다니고 있다.", progress = nil, completion = "그대의 노고 덕분에 이 땅에 다시 평온이 찾아왔으니 선물을 하나 주도록 하겠노라.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n늪지 수호자 로브수목의 사슬 갑옷덩굴검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[276] = {title = "파괴의 손길", objective = "이끼가죽 놀 15마리와 이끼가죽일족 싸움꾼 10마리를 처치한 다음 저습지에 있는 신록의수호자 레시엘에게 돌아가야 합니다.", description = "이끼가죽 놀들은 저습지에서 오랫동안 평화롭게 지내왔지만 요즘 그 수가 너무 늘어나고 있다. 이들은 늪의 덤불과 꽃들을 짓밟고 그 고약한 도끼로 수없이 많은 나무를 땔감으로 베어내고 있다.\n\n그 놀은 더 이상 이 땅과 조화를 이루지 못하고 있으니 저습지를 지키려면 놀의 숫자를 줄여야만 할 것이다.\n\n이끼가죽 놀 15마리와 이끼가죽일족 싸움꾼 10마리를 처치하라. 남쪽에 있는 알가즈라는 드워프 관문 근처에 놈들이 있을 것이다. 임무를 완수하고 내게 돌아오너라.", progress = nil, completion = "그대가 놀의 수를 줄였으니 저습지는 다시 건강해질 것이다. &lt;race&gt; 종족에 대한 신뢰를 잃은 지 오래지만 다시 믿음의 싹이 틀지도 모르겠구나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[277] = {title = "화재 예방", objective = "신록의수호자 레시엘에게 조잡한 부싯돌 9개를 가져가야 합니다.", description = "이끼가죽 놀들이 저습지의 나무를 베어 불을 지피는 데 사용하고 있다. 이제 더 이상 두고 볼 수만은 없는 일!\n\n이끼가죽 놀들이 불을 붙이는 데 사용하는 조잡한 부싯돌을 빼앗아 오라. 이끼가죽일족 놀과 이끼가죽일족 싸움꾼을 제외한 모든 이끼가죽일족이 부싯돌을 지니고 있다.", progress = "놀의 부싯돌은 가져왔는가?", completion = "... 고맙구나. 이 부싯돌들을 부수어 바다에 던져 다시는 살아 있는 나무를 태우지 못하도록 할 것이니라.", rewards = "다음과 같은 것들을 받습니다:\n\n곰보버섯"},
[278] = {title = "어둠의 전조", objective = "선임기술자 힌더바이르가 럴커의 독액, 모그로쉬 수정, 악어 눈물을 모아 달라고 부탁했습니다.", description = "중화제를 만드는데 필요한 재료들을 즉시 모아 주게. 럴커의 독액은 모단 호수에 사는 거미에게서 얻을 수 있고, 악어 눈물도 이곳에서 찾을 수 있지... 하지만 모그로쉬 수정은 찾기가 매우 힘들 거야. 모단 호수 북동쪽 광산에서 오우거들이 모그로쉬 수정을 캐고 있기는 하지만 아주 귀한 물건이라서 말이야.\n\n검은무쇠단 드워프의 공격을 막으려면 반드시 이 재료들이 필요하네. 모두 모으면 나에게 돌아와주게. 그러면 혼합하여 중화제를 만들도록 하지.", progress = "필요한 것들을 다 모았나? 우리에게 시간은 귀중한 것이야!", completion = "때맞춰 돌아왔군!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[279] = {title = "멀록과 고블러", objective = "푸른아가미멀록 12마리와 고블러를 처치하고 그 머리를 손에 넣어야 합니다.\n\n메네실 항구의 칼 보란에게 고블러의 머리를 가져가야 합니다.", description = "멀록들이 깊은 물속에서 기어 나와 해안가에 자신들의 소굴을 짓고 있습니다. 그뿐 아니라 어부와 상인들을 괴롭히고 있으니, 놈들을 반드시 막아야 합니다.\n\n이 멀록들 중 고블러란 녀석이 푸른아가미멀록들과 함께 숨어 들어와 지나가는 상인들을 괴롭히고는, 멀록 소굴 근처에 있는 은신처로 도망가 버리곤 합니다. 당신이 이 위험으로부터 우리 상인들을 보호해 준다면 적당한 보수를 지급할 생각입니다.\n\n고블러란 놈은 북쪽의 강 어귀를 배회하는 것으로 알려져 있습니다. 놈을 찾아서 그 무리를 모두 처치한 후에 그놈의 머리를 내게 가져다주시기 바랍니다.", progress = "고블러와 멀록들을 없애지 않으면 우리 상인들이 위험합니다.", completion = "아, 잘해 주었습니다.\n\n해안 경비대와 맺은 계약을 잘 이행해 줬으니 약속대로 이 보수를 받으십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[280] = {title = "어둠의 전조", objective = "선임기술자 힌더바이르가 댐 밑바닥으로 헤엄쳐 가서 화약통에 중화제를 넣어 섞어 달라고 부탁했습니다.", description = "오늘 검은무쇠단 폭도들이 큰 통을 가지고 댐 쪽으로 헤엄쳐 가는 걸 목격했네. 이른 아침이라 그들을 막을 산악경비원은 아무도 없었어! 놈들이 댐 밑바닥에 시포리움을 설치한 건 아닌지 걱정되는군. 만약 그랬다면 곧 폭발할지도 몰라. 이제 모아온 재료들을 혼합해 중화제를 만들어야겠어.\n\n자, 다 됐군.\n\n너무 늦기 전에 이 중화제를 놈들이 가져다 놓은 통 안의 것과 섞어야 하네. 서둘러야 해!", progress = "통 뚜껑은 천천히 돌려서 열어야 합니다.", completion = "시포리움에 중화제가 잘 섞이면 작은 소리가 들릴 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[281] = {title = "뱃짐 되찾기", objective = "해안가의 멀록 소굴에서 상자와 통을 찾아 열어봐야 합니다.", description = "얼마 전에 상선 블라인드 프린세스호가 멀록의 습격을 받았습니다. 다행히 배는 무사했지만 놈들이 이 배에 실려 있던 짐을 강탈해 가 버렸습니다. 그 뱃짐 중에는 귀중한 테레나스의 메네실 조각상도 포함되어 있습니다. 그 조각상을 좀 되찾아 주십시오.\n\n해안가의 멀록 소굴에서 상자나 통 등 잃어버린 짐으로 보이는 것들을 찾아보고, 그 조각상을 찾게 되면 내게 가져오시기 바랍니다.", progress = nil, completion = "이 상자엔 온통 발톱으로 긁힌 자국과 물에 상한 자국 투성이입니다. 힘겹게 상자를 열자 물에 젖은 썩은 지푸라기가 채워져 있는 것으로 보아 안에 귀중한 물건이 들어 있었다는 것을 알 수 있습니다. 지푸라기를 헤치고 살펴봅니다.\n\n그리고 붉은 병 한 아름을 발견합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n치유 물약"},
[282] = {title = "그렐린의 보고서", objective = "산악경비대 탈로스와 얘기를 나누십시오.", description = "원래는 수습생을 시켜 세니르 형에게 보고서를 전달하려 했는데 좀 더 믿음직한 사람이 좋을 것 같아서 말입니다. 당신한테 부탁해도 될까요?\n\n흠, 카라노스로 가려면 앤빌마 동쪽에 있는 터널을 가로질러 가야 합니다... 터널 입구에 가면 산악경비대원인 탈로스가 있을 테니 그와 얘기를 나눠 보십시오. 아마 지금쯤 터널 안엔 트로그들이 잔뜩 진을 치고 있을 겁니다. \n\n앤빌마로 가다가 동쪽 방향의 길을 따라 가면 터널이 나올 겁니다. 탈로스는 그 입구 근처에 있을 겁니다.", progress = "터널로 들어가는 길이십니까? 던 모로로 이어지는 터널 안에는 트로그들이 진을 치고 있어서 아주 위험합니다.\n\n급한 용무가 아니라면 좀 더 안전해질 때까지 앤빌마에 머무르시는 게 좋을 것 같습니다.", completion = "흠, 화이트비어드 씨의 부탁으로 중요한 용무 때문에 던 모로에 가시는 길이란 말씀이죠? 그렇다면 저도 붙잡을 수는 없겠군요.\n\n대신 몇 가지 조언을 해 드리죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[283] = {title = "어둠의 전조", objective = "중화제의 효과가 나타나는 것 같습니다. 선임기술자 힌더바이르에게 돌아가 이 기쁜 소식을 알려 주십시오.", description = "통에서 작은 소리가 납니다.", progress = nil, completion = "정말 고맙네!! 자네가 돌다지 댐을 구했군. 자네가 없었다면 검은무쇠단 녀석들이 우리의 자랑거리인 이 웅장한 댐을 파괴하고 말았을 거야. 동부 왕국과 얼라이언스에서는 자네처럼 용감한 &lt;class&gt;의 용맹을 높이 치하해 마지 않을 것이네.\n\n댐은 당분간 안전할 거야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n드워프족 벌목용 도끼뾰족칼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[284] = {title = "계속되는 수색", objective = "메네실 조각상을 찾아야 합니다.", description = "멀록의 소굴을 계속 뒤져 나가지만 메네실 조각상의 흔적은 보이지 않습니다.\n\n북쪽과 북동쪽에 있는 근처의 멀록 소굴 두 곳 중 한 곳에 단서가 있을지도 모릅니다.", progress = nil, completion = "이 통은 아무도 건드리지 않은 것 같습니다. 호기심에 가득 차 통을 엽니다.\n\n그러자 고약한 치즈 냄새가 코를 찌릅니다. 조금 젖었지만 맛은 괜찮은 것 같습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n드워프의 부드러운 치즈"},
[285] = {title = "다른 소굴 수색", objective = "멀록 소굴에서 메네실 조각상을 계속 찾아봐야 합니다.", description = "이 멀록 소굴을 샅샅이 조사했지만 아무것도 발견하지 못했습니다.\n\n하지만 다음에 찾게 될 단서는 매우 유용할 것이라고 확신합니다.\n\n북쪽에 있는 소굴 중 하나에는 반드시 메네실 조각상이 있을 것입니다!", progress = nil, completion = "이 통은 진흙과 풀 한가운데 반쯤 묻혀 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[286] = {title = "조각상 돌려주기", objective = "칼 보란에게 메네실 조각상을 가져가야 합니다.", description = "흙 속에서 통을 꺼내 열자 깨끗한 지푸라기에 쌓여 있는 은빛 조각상이 나옵니다. 조각상은 해머를 높이 들고 있는 긴 머리의 젊은 성기사의 모습입니다.\n\n이것은 메네실 조각상이 분명합니다! 이제 메네실 항구의 칼 보란에게 돌아가야 합니다.", progress = "조각상은 찾았습니까?", completion = "귀중한 짐을 되찾았으니 블라인드 프린세스호의 선장에겐 무엇보다 반가운 소식일 겁니다. 당신은 이 보상금을 받을 자격이 충분하군요.\n\n이런 시련 속에서 당신처럼 믿음직한 사람을 만난 것이 얼마나 다행인지 모르겠습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n고드름 마법봉뱃사람의 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[287] = {title = "서리갈기 소굴", objective = "서리갈기 소굴을 찾아 서리갈기부족 인간사냥꾼 5마리를 처치한 후 카라노스에 있는 세니르 화이트비어드에게 돌아와야 합니다.", description = "내가 아직 보고서를 완성하지 못한 상황이라서 말인데 자네 도움이 좀 필요하다네. 트롤들이 숨어 있는 곳을 발견했지만 너무 많아서 들어갈 수가 있어야지. 자네가 동굴로 들어가서 트롤을 찾아 몇 놈 처치한 다음에 이곳으로 돌아와 주게.\n\n우선 카라노스 북쪽 외곽 길을 따라 다리가 있는 곳까지 가게. 그리고 거기서 서쪽으로 얼어붙은 강을 따라 얼음 호수가 나올 때까지 계속 가게. 그러면 서쪽 강둑에 브루날 마을이 보일 거야. 서리갈기부족 소굴은 그 마을 남서쪽에 있네.", progress = nil, completion = "아! 내가 그렇게 자세히 설명해 줬는데도 그리 고생할 줄은 몰랐네. 어쨌든 고맙네. 자, 그럼 보고서를 완성해 볼까?\n\n&lt;종이를 가져와 급히 써내려 가며...&gt;\n\n저런! 이거 참 우습게 됐군. 허허... 부탁 한 가지만 더 해도 되겠지?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n따뜻한 겨울 로브돌 버클러\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[288] = {title = "제 3함대", objective = "일등항해사 피츠시몬즈에게 벌꿀술을 한 병 사 줘야 합니다.", description = "난 쿨 티라스 제 3함대의 주력함이었던 웨이브 미스트리스호의 일등항해사였지. 마지막 항해에서 붉은용들의 공격을 받아 전멸하고 말았던 비운의 함대 말이야. 함대를 공격한 그 용들은 오크 놈들이 조종하는 거였어!\n\n용이 뿜어내는 불기운을 버틸 재간이 없었던 함대는 결국 불탄 채로 난파되어 이 해안으로 떠내려 오게 된 거지. 전 함대를 통틀어 내가 유일한 생존자야.\n\n아, 그 생각을 하니 또 머리가 지끈거리는군! 마음을 달래고 얘기를 계속하려면 술을 한 잔 더 걸쳐야겠어.", progress = "아, 목이 너무 마른 걸! 이 가슴 아픈 이야기의 주인공에게 술을 한 잔 사지 않겠나?", completion = "아, 바로 이 맛이야! 혀에서 살살 녹는군. 고마워, 친구!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[289] = {title = "저주받은 선원", objective = "저주받은 선원 13명, 저주받은 해병 5명, 그리고 일등항해사 스넬리그를 처치해야 합니다. 메네실 항구에 있는 일등항해사 피츠시몬즈에게 스넬리그의 연초상자를 가져가야 합니다.", description = "<고무되어 이야기를 계속하는 피츠시몬즈>\n\n내가 바로 북쪽 해안에 난파된 그 쿨 티라스 제 3함대의 유일한 생존자란 말이야, 내가! 그런데 문제는 함대 대원 중에 아직 숨 쉬고 있는 건 나뿐이지만, 이곳에 남아 있는 건 나만이 아니라는 거지! 우리 배들 중 한 척에는 값지고 무시무시한 보물이 숨겨져 있어서, 거기서 뿜어 나오는 기분 나쁜 기운이 우리 동료의 영혼들을 저 썩어가는 선체에 가둬두고 있어.\n\n당신이 우리 동료 몇 명의 영혼을 자유롭게 해 준다면 그 저주를 풀 수 있을 거야.", progress = "가끔 꿈 속에서 동료의 애절한 흐느낌을 듣곤 해! 제발 부탁이야, 친구. 그들을 속박에서 풀어 주고 그 흐느낌을 잠재워 줘.", completion = "고마워, 친구. 저주받은 동료들도 고마워할 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[290] = {title = "저주 풀기", objective = "할린도르 선장을 처치한 후 인트레피드호의 금고 열쇠를 손에 넣어야 합니다.\n\n그 열쇠를 사용하여 인트레피드호의 잠긴 금고를 열어야 합니다.", description = "내 동료들의 저주를 풀고 그들을 모두 자유롭게 하려면 바로 그... 그것... 우리 배에 실었던 그걸 찾아내서 정화해야 해! 그게 무엇인지는 모르지만 할린도르 선장이 애지중지하던 금고에 안전하게 보관되어 있었어.\n\n난파된 인트레피드호에 떠돌고 있는 우리 늙은 선장이 계속 꿈에 나타나고 있어. 그에게서 열쇠를 찾아내 인트레피드호의 금고를 좀 열어 줘.\n\n그리고 그 저주받은 물건을 꺼내서 마을에 있는 사제, 글로린 스틸브로우에게 가져다 줬으면 해.", progress = "이 금고는 단단히 잠겨 있습니다.", completion = "열쇠는 녹이 슬었지만 자물쇠에 꼭 들어맞습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[291] = {title = "보고", objective = "아이언포지에 있는 원로원의원 바린 레드스톤에게 세니르의 보고서를 전달해야 합니다.", description = "내 보고서를 원로원의원이신 바린 레드스톤님께 전해주게. 매우 까다로운 분이니 화나게 해서는 안 될 거야. 아이언포지에 마그니 폐하가 궁정 회의를 하셨던 왕좌 옆에 계실 걸세.\n\n자네, 아이언포지로 가는 길은 알고 있나? 카라노스를 나가서 북쪽 길을 따라 다리를 건넌 다음, 길가에 큰 깃발이 있는 곳에서 동쪽 길을 따라 산허리로 올라가면 된다네.\n\n참, 그분께 자네가 날 돕는다는 사실은 비밀로 해주겠나? 내가 하는 일도 없이 놀고만 있다고 생각하시면 안 되니까 말이야, 알았지?", progress = "이런, 이런... 경비병들이 탄원서를 올리러 오는 이들에게 관대해지는가 보군. 아무 제재 없이 여기까지 들어오게 하다니... 흠, 그나저나 무슨 일로 왔나? 빨리 말하게. 난 바쁜 몸일세.", completion = "&lt;재빨리 보고서를 읽어 내려가는 바린 레드스톤&gt;\n\n폐하의 승인? 폐하께서 정신이 나가셨나? 못난 화이트비어드 녀석... 그 작자가 모든 일을 잘 처리하고 있다고? 원로원에서는 이 보고서의 내용을 전혀 맘에 들어 하지 않을 걸세. 암, 그럴 리 없지.\n\n뭐야, 아직도 여기 서 있었나? 경비병을 불러 쫓아 내기 전에 썩 꺼지게!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[292] = {title = "팔레스의 눈", objective = "글로린 스틸브로우에게 팔레스의 저주받은 눈을 가져가야 합니다.", description = "금고를 열자 기분 나쁜 빛을 발하는 더러워진 수정구가 들어 있습니다. 피츠시몬즈가 말하던 보물, 팔레스의 저주받은 눈입니다.\n\n팔레스의 저주받은 눈을 메네실 항구에 있는 드워프 사제 글로린 스틸브로우에게 가져가십시오. 그리고 그에게 팔레스의 눈에 걸려 있는 저주를 풀어 달라고 부탁해야 합니다.", progress = "그 주정뱅이 피츠시몬즈가 자넬 보냈다고? 흠, 그자에게 내겐 더 이상 에일 맥주가 없다고 전해 주게. 맥주는 이제 다른 사람에게 얻어먹으라고 말이야!", completion = "팔레스의 눈이잖아? 놀랍군! 흠... 그런데 뭔가 이상한 것 같은데. 난파선에서 이걸 찾았다고 했나? 그렇다면 이해가 가는군. 하지만 제 3함대의 잔해에 팔레스의 눈이 있었다니...\n\n피츠시몬즈가 악몽을 꿀만도 했군그래. 분명 팔레스의 저주받은 눈은 기분 좋은 물건이 아니니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[293] = {title = "팔레스의 눈 정화", objective = "대주교 베네딕투스에게 팔레스의 저주받은 눈을 가져가야 합니다. 베네딕투스는 스톰윈드의 빛의 대성당에 있습니다.", description = "미안하지만 난 팔레스의 눈에 걸려 있는 저주를 풀 수 없네. 이건 인간 사제가 만든 물건이니까 스톰윈드로 가서 도움을 줄 만한 사람을 찾아야 해. 대주교 베네딕투스와 한번 얘기해 보게. 그는 스톰윈드에 있는 빛의 대성당의 대표자일세. 그가 자넬 도울 수 있을 거야.\n\n나도 자넬 위해 기도하겠네.", progress = "그 수정구는 뭔가? 매우... 저주스러워 보이는 물건이군.", completion = "팔레스의 눈... 하지만 여기엔 비탄이 서려 있군. 분명히 너무나도 끔찍한 비극을 목격한 게야.\n\n내가 정화해 주도록 하겠네. 원래 팔레스의 눈은 밝은 빛을 발하도록 만들어졌지만, 지금처럼 저주로 가득하다면 매우 위험할 수도 있다네.", rewards = "다음과 같은 것들을 받습니다:\n\n팔레스의 눈"},
[294] = {title = "오머의 복수", objective = "웰가르의 발굴현장에 있는 오머 아이언브레이드가 긴송곳니 줄무늬랩터 10마리와 줄무늬랩터 10마리를 처치해 달라고 부탁했습니다.", description = "상황이 매우 좋지 않소. 우리가 이 뼈들을 발견했을 때는 이미 냄새를 맡은 랩터들이 모여들고 있었소. 이 고약한 짐승들은 내 동료들을 죽이고, 난 메린과 불쌍한 발굴조사단장님과 함께 이곳에 갇히게 되었소.\n\n저습지에서 저 고약한 랩터들을 몰아낼 수 있도록 도와 주시오. 저 절벽 서쪽에 줄무늬랩터와 긴송곳니 줄무늬랩터를 각각 10마리씩 처치해 주시오.\n\n그것으로 놈들에 대한 내 복수가 시작될 거요.", progress = nil, completion = "무언가를 죽인다는 게 유쾌한 일도 아니건만 잘해 주었소. 발굴조사단장님과 메린과 함께 있으라는 명령만 없었어도 나도 당신과 함께 놈들을 처치했을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[295] = {title = "오머의 복수", objective = "웰가르의 발굴현장에 있는 오머 아이언브레이드가 갈퀴발톱 줄무늬랩터 10마리, 무쇠턱 줄무늬랩터 10마리를 처치해 달라고 부탁했습니다.", description = "자, 이제 저 끔찍한 랩터들에게 수많은 피를 흘리게 한 대가가 얼마나 큰 것인지 깨닫도록 해야 할 때요. 바로 저 아래쪽으로 가면 갈퀴발톱 줄무늬랩터와 무쇠턱 줄무늬랩터들이 무리 지어 있소. 이 고약한 짐승들을 각각 10마리씩 처치해 주시오!", progress = "저 갈퀴발톱 줄무늬랩터와 무쇠턱 줄무늬랩터들에게 자신들이 저지른 짓의 대가를 반드시 치르도록 해야 하오. 놈들을 처치했소?", completion = "랩터 놈들을 정말 잘 처치해 주었군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[296] = {title = "오머의 복수", objective = "웰가르의 발굴현장에 있는 오머 아이언브레이드가 살투스를 처치한 후 발톱을 가져다 달라고 부탁했습니다.", description = "당신이 없는 동안 저 짐승들 중 한 놈이 다른 놈들과 다르다는 사실을 발견했소. 이놈은 다른 놈들보다 크고 훨씬 더 사나웠소이다. 아무래도 놈이 무리를 이끌면서 발굴 현장을 어지럽히고 다니는 우두머리인 것 같소.\n\n이번이 내가 부탁하는 마지막 임무가 될 거요. 살투스란 녀석은 죄가 막중하니 정의의 이름으로 처치해 주시오! 내게 놈이 죽었다는 증거로 놈의 발톱 하나를 가져다주시오.", progress = "살투스는 처치했소? 파괴의 대가를 치르도록 했느냔 말이오!", completion = "고맙소. 당신의 노고는 잊지 않겠소이다. 그저 묵묵히 일만 하던 무고한 드워프들이 이곳에서 수도 없이 죽어 갔소. 저 악마 같은 짐승들에게 복수해 주었으니 놈들도 다시는 마그니 폐하의 백성을 함부로 공격하지 못할 거요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n랩터 사냥용 활랩터 사냥꾼의 갑옷발굴 마법봉\n\n다음과 같은 것들 또한 받습니다:\n\n조리법: 진기한 맛의 오믈렛"},
[297] = {title = "조각상 모으기", objective = "마그마 펠휴에게 돌 조각상 8개를 가져가야 합니다.", description = "최근, 그러니까 트로그가 이 지역에 나타나기 직전에 이상한 돌 조각상을 발견했었지. 그런데 우리가 그 조각상들을 발견하자마자 트로그놈들이 우리를 쫓아오는 바람에 황급히 유적지를 빠져나와야 했소. 조각상들을 살펴 볼 겨를도 없었소. 그 조각상들이 트로그에게 영향을 미쳐 놈들이 더 광폭해지는 것 같소!\n\n조각상들이 트로그에 어떤 영향을 미치는지 연구할 수 있도록 돌 조각상 8개를 내게 가져다주시오. 조각상이 트로그놈들 손에 들어가지 못하게 막아야 하오. 이 지역을 배회하고 있는 트로그들에게 조각상을 빼앗을 수 있을 거요.", progress = "조각상들을 손에 넣었소? 우리는 조각상을 연구해서 그 결과를 아이언포지에 보고해야 한단 말이오!", completion = "조각상들을 찾았군! 참 잘했소, 친구!\n\n그 광포한 트로그와 싸우고도 별로 지쳐 보이지도 않는군. 앞으로 당신의 활약을 기대하겠소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n드워프족 불막대트로그잡이 검텔사마 도끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[298] = {title = "발굴 상황 보고서", objective = "텔사마의 예른 혼헬름에게 아이언밴드의 상황 보고서를 가져가야 합니다.", description = "텔사마에 발굴 상황에 대한 보고를 해야 하오. 화약 지원 요청도 해야 하고 말이오. 보고서는 여기 있소. 이걸 텔사마의 연락 담당인 예른 혼헬름에게 갖다주시겠소?\n\n매우 중대한 일이오. 힘든 일은 아니니 꼭 좀 부탁하겠소!", progress = "오, 현장의 상황 보고서로군. 고맙소.", completion = "이런! 아이언밴드가 트로그 때문에 애를 먹고 있군. 발굴 작업 때문에 화약이 필요하다는 건지, 아니면 트로그와 싸우려고 필요하다는 건지 모르겠군. 뭐, 어쨌든 화약을 보내 줘야겠군그래.\n\n그런데 몇 주 전에도 화약을 꽤 많이 보내줬었는데, 이상하군. 그걸 다 어디에 쓴 거지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[299] = {title = "드러난 과거", objective = "발굴조사단장 웰가르가 발굴현장을 정리하고 사라진 아도스 조각, 모드르 조각, 골름 조각, 네루 조각을 가져다 달라고 부탁했습니다.", description = "저 랩터들의 침략이 있기 직전에 고아즈석이라는 큰 석판을 발견했다네. 석판의 내용은 모두 4부분으로 나눠져 있네. 그 내용을 보면 \"신성한 계획\"과 \"운명의 예언\"에 대해 말하고 있다네.\n\n시간이 별로 없네. 내가 직접 가서 저 짐승들을 상대하기엔 너무 늙었지만 자네는 강하고 젊지 않은가.\n\n발굴현장을 정리하고 사라진 4개의 석판 조각을 찾아 주게나. 그 석판 조각들은 각각 아도스, 모드르, 골름, 네루라고 한다네. 고대 유물이나 흙이 패인 곳에서 찾아보면 될 거야. 의문을 풀 수 있도록 내게 그 석판 조각들을 가져다주게!", progress = "네 개의 석판 조각은 찾았나? 아도스, 모드르, 골름, 그리고 네루 말일세.", completion = "드디어 고아즈석이 완성됐군! 훌륭하네, 정말 훌륭해. 이제야 이 티탄 문자를 정확히 번역할 수 있게 되었네. 아, 벌써 새로운 내용이 눈에 띄는군. 흠, 여길 봐. \"옛 신들... 지하에 묶여 있다.\"라고 되어 있어. 이건 마치 무슨 서사시의 시작 부분 같은데...", rewards = "다음과 같은 것들을 받습니다:\n\n감의 비단 어깨보호대"},
[301] = {title = "아이언포지에 보고", objective = "발굴조사단장 스톰파이크에게 아이언밴드의 상황 보고서를 가져가야 합니다.", description = "아이언밴드에게 화약을 더 보내려면 승인을 받아야 하오. 그러려면 그 보고서를 아이언포지 탐험가 연맹 본부로 가져 가야 하오.\n\n여기 보고서를 받으시오. 이걸 발굴조사단장 스톰파이크에게 주면 처리해 줄 거요. 그 사람도 아이언밴드에서 발굴 작업이 지연되는 걸 원치 않을 테니까...\n\n스톰파이크는 탐험가 총회에 가면 만날 수 있소.", progress = "난 사소한 일까지 신경 쓸 만큼 한가하지 않소, <class>. 내 귀중한 시간을 빼앗을 만큼 중요한 소식인가?", completion = "이런, 못난 아이언밴드! 몇 주 전에 화약을 잔뜩 보내줬었는데, 이 보고서엔 그런 기록이 전혀 없군그래.\n\n그럼 그 화약은 다 어디로 간 게야, 대체?!?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[302] = {title = "아이언밴드에게 화약 지원", objective = "텔사마의 예른 혼헬름과 대화하십시오.", description = "그래도 아이언밴드가 화약이 필요하다고 하면 보내 줘야겠지. 이미 전령을 통해 텔사마에 있는 예른 혼헬름에게 승인서를 보냈으니 그가 아이언밴드에게 보낼 화약과 다른 물품들을 준비해 줄 게요.\n\n그리고 한 가지 부탁이 더 있는데, 화약이 제대로 전달되는지 잘 감시해 주시오. 지난번에 보낸 화약은 아이언밴드에게 전달되지 않았으니 철저히 감시해 주길 바라오.", progress = nil, completion = "아, 스톰파이크가 아이언밴드에게 지원 물품이 잘 배달되는지 직접 확인하라고 했소?\n\n뭐, 별 상관은 없지만... 이걸 어쩐다. 이미 훌다르를 미란과 사옌이라는 짐꾼들과 함께 보냈는데... 당신이 오기 바로 직전에 떠났소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[303] = {title = "검은무쇠단과의 전투", objective = "던 모드르의 모틀리 가마슨이 검은무쇠단 드워프 15명, 검은무쇠단 채굴꾼 5명, 검은무쇠단 투사 5명, 검은무쇠단 폭파병 5명을 처치해 달라고 부탁했습니다.", description = "나라 안팎으로 전쟁이 번지고 있소. 강력한 드워프 병사들이 먼 타향에서 얼라이언스의 이름으로 죽어가는 동안, 정작 우리 조국은 검은무쇠단 드워프에게 짓밟히고 있으니... 탄돌 교각에서 우리 병사들이 희생되는 바람에 던 모드르가 그리 허무하게 함락되고 만 거요.\n\n당신도 우리를 도와 병력을 소집해 놈들을 저지해 주었으면 하오. 검은무쇠단 드워프 15명과 채굴꾼, 투사, 폭파병 각각 5명씩을 처치해 준다면 예비 병력이 도착해 놈들을 몰아낼 때까지 버틸 수 있을 거요.\n\n어서 서두르시오!", progress = "로고가 예비 사단과 연락하지 못하고 있어 검은무쇠단 주둔지를 공격해야 하오. 다시 가서 마그니 폐하를 위한 소임을 다하시오!", completion = "명령을 잘 수행해 주었소, &lt;class&gt; 친구. 스스로 용감한 병사이자 마그니 폐하의 충성스런 신하임을 입증해 보인 당신에게 경의를 표하오! 당신이 검은무쇠단 주둔지를 공격해 준 덕분에 이 땅에서 놈들을 영원히 몰아낼 기회가 생겼소이다. 그 빌어먹을 예비 사단만 온다면 말이지.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[304] = {title = "위험한 임무", objective = "불한당 발가라스를 처치하고 그의 귀걸이를 던 모드르 외곽에 있는 결의의 롱브레이드에게 가져가야 합니다.", description = "던 모드르 전투에서 수많은 병사가 목숨을 잃었다네. 내 친동생도 탄돌 교각의 서쪽 다리가 무너질 때 전사하고 말았지. 그렇네, 검은무쇠단 드워프는 악마 같은 녀석들이야. 로고가 수집한 정보에 따르면 저습지의 이 흉악한 무리의 우두머리가 불한당 발가라스라는 흑마법사라고 하네. 녀석은 위험한 전투에 부하들만 내보내고 자기는 숨어 있는 비겁한 겁쟁이지.\n\n그 비겁하고 쓰레기 같은 녀석을 찾아내 처치하고 그 증거를 가져오면 내 보상하지.", progress = "불한당 발가라스를 찾았나, <class> 친구? 녀석은 꽤 오랫동안 우릴 잘도 피해다니고 있다네.", completion = "마침내 불한당 발가라스를 처치했군. 비록 녀석이 죽었다고 해서 그동안 녀석의 손에 무고하게 죽어간 드워프의 목숨을 되돌릴 수는 없지만 살아 남은 이들에게 위안은 될 걸세. 발가라스가 죽었으니 남아 있는 검은무쇠단 드워프들을 격퇴하는 건 어렵지 않겠군. 녀석들에게 새 우두머리가 부임해 오기 전에 쓸어 버려야겠네.\n\n아주 잘해 주었네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n황금사자 방패평온의 반지\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[305] = {title = "발굴단을 찾아서", objective = "타렐 록위버가 발굴 현장으로 가서 메린 록위버를 찾아 달라고 부탁했습니다.", description = "오! 당신이 바로 롱브레이드님이 보낸다던 정찰병이로군! 내가 얼마나 걱정했는지 모를 거요.\n\n웰가르 발굴단의 일원인 내 아내 메린이 지난달 내내 나에게 매주 편지를 보내 줬었소. 그런데 마지막으로 편지를 받은 지 2주가 다 지났소. 아직까지 연락이 없는 걸 보니 무슨 일이 있는 게 분명하오!\n\n롱브레이드님께서 근간에 발굴단에게서 연락이 없으면 정찰병을 보내 확인해 보시겠다고 하셨다오. 아마 그 정찰병이 당신인가 보구려. 동쪽의 발굴 현장에서 메린을 찾아 주시오!", progress = nil, completion = "오, 당신이 와 주셔서 얼마나 다행인지 몰라요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[306] = {title = "발굴단을 찾아서", objective = "타렐 록위버에게 메린의 편지를 가져가야 합니다.", description = "우리는 굉장히 희귀한 유물을 발굴하고 있었는데, 이 거대한 뼈들이 나오기 시작한 거예요. 정말 끔찍했어요!\n\n그런데 우리가 무슨 일이 일어나고 있는지 알아채기도 전에 줄무늬랩터들이 발굴 현장을 공격해 왔어요. 그래서 많은 사람이 목숨을 잃었죠.\n\n우리의 용감한 오머가 발굴조사단장님과 저의 목숨을 구해 줬어요. 오머가 엄호해 준 덕분에 안전한 곳으로 도망칠 수 있었죠. 이젠 여기 갇힌 신세이고 우리가 힘들게 발굴한 것들도 다 버려져 있답니다.\n\n자, 이 편지를 남편 타렐에게 전해 주세요. 편지에 이곳 상황을 자세히 설명해 놨어요.", progress = "메린은 찾았소? 아무 소식도 없는 거요?", completion = "이런 끔찍한 일이... 하지만 적어도 세 명은 살아 있는 거군. 이 지긋지긋한 학살이 언제 끝나는 거지? 마그니 폐하의 선량한 드워프들이 두려움 없이 평화롭게 지낼 수 있는 날이 오기만 간절히 바랄 뿐이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[307] = {title = "더러운 손", objective = "은여울 광산에서 광부의 도구 4개를 모아야 합니다.\n\n그런 다음 산악경비대 스톰파이크에게 돌아가십시오.", description = "여기서 동쪽에 있는 은여울 광산은 오래전 폐광되었소. 광부 조합에서 폐광을 저장고로 사용했는데 지금은 코볼트들이 들어와 살고 있소. 드워프의 훌륭한 소유지가 추악한 괴물들의 손에 들어간 거요!\n\n곧 우리 전사들이 녀석들을 소탕할 계획이지만, 광부 조합에서는 누군가가 광부의 도구를 먼저 찾아 주길 바라고 있소. 아마 부대를 동원해야 할지도 모르는 힘든 임무가 될 거요.\n\n광부의 도구는 동굴 곳곳에 있는 광부 조합 상자에 들어 있다오. 행운을 빌겠소.", progress = "광부의 도구는 가져왔소?", completion = "그래, 동굴 안에 코볼트 놈들이 얼마나 있었소? 이거 몸이 근질거려서 명령이 떨어질 때까지 못 기다리겠는걸. 당장이라도 놈들을 광산에서 쓸어내 버리고 싶소. 그 추악한 손으로 광산을 더럽히고 있을 걸 상상하면 속이다 뒤틀리니 말이오!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n철심장 사슬 갑옷감시자의 로브철제판금 버클러\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[308] = {title = "맥주를 좋아하는 야벤", objective = "우호! 여긴 온통 술로 가득하지. 하지만 절대 손도 대지 말라는 명령이 있었으니 맛을 볼 수도 없고... 썬더 에일을 한 모금만 마실 수 있으면 일을 잘해낼 자신이 있는데 말이야. 정말이라오!", description = nil, progress = "우호! 여긴 온통 술로 가득하지. 하지만 절대 손도 대지 말라는 명령이 있었으니 맛을 볼 수도 없고... 썬더 에일을 한 모금만 마실 수 있으면 일을 잘해낼 자신이 있는데 말이야. 정말이라오!", completion = "나한테 주는 거요? 당신 정말 멋진 친구로군!", rewards = nil},
[309] = {title = "화약 운반", objective = "미란이 발굴 지역까지 무사히 도착할 수 있도록 경호하고 발굴조사단장 아이언밴드에게 가십시오.", description = "<name>, 떠날 준비가 다 된 거요?\n\n무엇보다 먼저 이 화약을 아이언밴드에게 전달해야 하오. 짐도 많고, 게다가 매우 위험할 게야. 검은무쇠단 드워프가 습격할지도 모르고...\n\n당신이 나와 함께 가 준다면 안심할 수 있을 것 같군.", progress = "화약은 어디 있소? 한시라도 빨리 화약이 필요하단 말이오.", completion = "오! 화약을 가져오다니 얼마나 다행인지 모르오. 하지만 유쾌하지 않은 일도 있었다니 유감스럽군... 아마 놈들의 비열한 동조자가 우리 화약을 빼돌렸던 모양이군.\n\n뭐, 그건 내가 신경 쓸 문제는 아니고, 화약도 왔으니 내 할 일이나 시작해야겠소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n현장감독 허리띠진흙탕 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[310] = {title = "숙명의 경쟁자", objective = "카라노스에 있는 썬더브루 양조장의 지하실로 가서 썬더 에일 맥주통을 발리브루 스칼더 맥주통으로 바꿔 놓아야 합니다.", description = "썬더브루의 술이 훌륭하다는 건 저도 인정합니다. 하지만, 자기네들만 좋은 술을 만드는 건 아니라는 걸 가르쳐 주고 싶군요! 그래서 말인데 도움이 좀 필요합니다.\n\n자, 여기 발리브루 스칼더 맥주통을 가지고 카라노스에 있는 썬더브루 양조장 지하실로 숨어 들어가세요. 그리고 이걸 썬더 에일 맥주통 중 하나와 바꿔 놓으세요. 어디, 그 집 단골들이 누구 맥주를 더 좋아하는지 한번 지켜보고 싶군요.\n\n혹시 누군가 그 맥주통을 지키고 있다면 그자의 주의를 다른 곳으로 돌려야 할 겁니다.", progress = "맥주통에 쓰여 있는 날짜를 보니 곧 마개를 따서 마실 때가 된 것 같습니다.", completion = "용케 들키지 않고 말레스의 발리브루 스칼더 맥주통을 썬더브루 맥주통과 바꿔놓는 데 성공했습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[311] = {title = "말레스에게 돌아가기", objective = "브루날 마을에 있는 말레스 발리브루에게 썬더 에일 맥주통을 가져다주어야 합니다.", description = "말레스가 준 스칼더 맥주통을 카라노스 양조장 지하실에 놓고 썬더 에일 맥주통 하나를 챙겼습니다. 바꿔치기에 성공한 증거가 될 것 같습니다.", progress = "맥주통을 바꿔치기 해 놓았나요?", completion = "잘했어요! 몰래 들어가느라 힘들지는 않았나요?\n\n정말 고마워요. 언제라도 제대로 숙성된 스타우트 맥주를 마시고 싶거든 발리브루 집안을 잊지 말고 찾아오세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[312] = {title = "툰드라 맥그란의 고기 상자", objective = "늙은 얼음수염의 동굴에 있는 잃어버린 고기 상자에서 툰드라 맥그란의 말린 고기를 되찾아 와야 합니다.", description = "난 추운 겨울을 대비해서 한 달 치 분량의 말린 고기를 소금에 절여 상자에 넣고 잠가 두었네. 곰들이 가져가지 못하게 말이야! 그런데 사슴 사냥을 나간 사이 늙은 얼음수염이라는 짐승이 그 상자를 훔쳐갔어. 상자는 토륨으로 만들어져 있어서 쉽게 부술 수는 없을 테지만 그 안의 고기를 되찾지 못하면 영락 없이 굶어야 할 판이야.\n\n그래서 말인데, 숨어서 몰래 왔다갔다 하는 건 자네가 나보다 더 잘할 것 같으니 내 상자 좀 찾아 주게나. 내 이 느려 터진 두 다리로는 동굴 안을 재빠르게 들락날락할 수 없을 것 같아.", progress = "내 고기 상자는 찾았나?", completion = "요즘 세상에 보기 드문 착한 사람이군. 덕분에 겨울이 닥쳐 와도 굶어 죽지 않게 되었어.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n두드려 만든 팔보호구양모 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[313] = {title = "은빛 동굴", objective = "웬디고 갈기 8개를 모아 조종사 스톤기어에게 가져다주어야 합니다.", description = "아무나 증기 전차를 조종할 수 있는 건 아니지. 증기 전차를 조종하려면 강철 같은 팔 힘과 큰 담력이 필요하거든. 다행히 난 그 두 가지를 모두 갖추고 있다네. 자넨 어때? 근성이 좀 있나? 내게 한번 증명해 볼 텐가?\n\n좋아... 난 내 트롤플로우 증기 전차를 좀 더 안락하게 꾸미고 싶다네. 카라노스 서쪽에 있는 은빛 동굴에서 웬디고 갈기를 좀 넉넉히 가져다주겠나? 전차 내부에 웬디고 갈기를 깔아 놓으면 아주 멋질 거야!", progress = "이봐. 은빛 동굴에는 갔다 왔나? 웬디고들은 꽤 사나워서 갈기 얻기가 쉽진 않을 거야.", completion = "그래, 이 정도라면 충분하겠군! 담력이 대단하군, &lt;class&gt; 친구. 앞으로 큰일을 할 인물이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[314] = {title = "가축 보호", objective = "루드라 앰버스틸이 바가쉬를 처치한 후 산양 농장으로 바가쉬의 송곳니를 가지고 오라고 부탁했습니다.", description = "한밤중에 짐승 울음소리가 들려서 잠을 설쳤어요. 아침에 일어나자마자 우리로 가봤더니 아니나 다를까 숫양 두 마리가 없어졌지 뭐예요. 그동안 계속해서 바가쉬라고 하는 비열한 짐승이 우리 가축을 해쳐 왔었답니다. 지금은 마그니 폐하의 군대가 대부분 얼라이언스와 함께 원정을 나가 있어서 바가쉬를 처치해 줄 사람이 없어요.\n\n당신이라면 그 짐승을 찾아서 처치할 만큼 용감해 보이네요. 바가쉬의 송곳니를 가지고 오면 보상해 드리죠. 이 목장의 바로 위쪽에 숨어 있어요. 아주 위험하니 조심하셔야 해요.", progress = "바가쉬가 아직도 우리의 가축을 위협하고 있어요! 그 비열한 짐승을 처치해서 제발 발 좀 뻗고 잘 수 있게 해 주세요.", completion = "훌륭하군요! 베론이 이 소식을 들으면 매우 기뻐할 거예요. 바가쉬를 처치하기 쉽지 않았을 텐데 대단하네요. 언젠가는 당신도 얼라이언스 편에서 마그니 폐하의 병사들과 함께 싸우게 될 날이 올 것 같군요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n목동의 반바지부드러운 가죽 튜닉눈마루골짜기 망치\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[315] = {title = "최고급 스타우트 맥주", objective = "브루날 마을에 있는 레욜트 발리브루에게 쉼머위드 6개를 가져다주어야 합니다.", description = "해야 할 일이 하나 있어. 바로 최고급 스타우트 맥주를 만드는 것이지. 우리 집안은 대대로 양조업을 해왔기 때문에 자신 있어. 확실한 제조법만 찾으면 되는데...\n\n서리갈기트롤들이 동쪽에 있는 언덕에서 쉼머위드라는 식물을 재배하고 있다고 들었네. 기이한 부족 의식에 사용하기 위해서지. 우리 드워프한테는 별로 쓸모 있는 식물이 아니지만 독특한 맛이 나거든... 그걸로 술을 한번 담가 보려고.\n\n서리갈기부족 예언자를 처치해서 얻거나 아니면 쉼머위드가 담긴 바구니에서 꺼내다 주지 않겠나?", progress = "내가 말한 쉼머위드는 가져왔나? 지금 스타우트 맥주 한 통을 만들 준비가 거의 다 됐는데, 거기다 쉼머위드를 넣어 보려고.", completion = "좋았어! 얼른 넣어 봐야겠어. 훌륭한 맥주 제조법이 탄생할 거 같아.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n염소 가죽 망토덩굴로 엮은 팔보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[317] = {title = "증기 전차 공급품 비축", objective = "멧돼지 고기 4개와 두꺼운 곰 모피 2개를 모아서 스틸그릴의 정비소에 있는 조종사 벨로우피즈에게 가져다주어야 합니다.", description = "난 이번에 증기 전차 부대에서 맡은 임무를 곧 시작할 계획이네. 시간이 오래 걸리는 임무라 증기 전차에 한 달 치 정도의 보급품을 비축해 둬야 하지. 스틸그릴이 내 탱크를 손보고 있는 동안 날 위해 사냥을 좀 해 주겠나?\n\n깔고 잘 수 있는 것과 우리의 주식인 멧돼지 고기가 필요하다네. 가죽은 멧돼지, 표범, 곰 등을 사냥해서 구하면 되고, 고기는 물론 멧돼지에게서 얻으면 되지... 은빛 동굴 남쪽의 눈 덮인 벌판에 가면 사냥감이 많이 있을 거야.", progress = "여기는 잘 돌아 가고 있네. 사냥은 어떻게 됐나?", completion = "어이구, 사냥을 많이도 해왔군! 정말 고맙네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[318] = {title = "에버샤인", objective = "브루날 마을에 있는 레욜트 발리브루에게서 에버샤인 술통을 얻으십시오.", description = "레욜트 발리브루라는 드워프가 다양한 종류의 술을 만들고 있는데 맛있는 술도 있지만 개중에는 형편 없는 것도 있다네. 그리고 가끔씩 아주 독한 술을 만드는데, 체력이 웬만한 드워프도 한두 잔만 마시면 뻗어 버릴 정도지.\n\n레욜트는 카라노스의 서쪽에 있는 브루날 마을에 살고 있네. 그가 만드는 에버샤인이라고 하는 술이 필요한데... 추운 날 바깥에서 돌아다닐 때 몸을 녹이는 데 그만이지.\n\n게다가 워낙 독한 술이라서 증기 전차 엔진에 넣어도 대단한 화력을 얻을 수 있거든. 그 방법으로 위급한 상황에서 빠져나간 게 한두 번이 아니라네.", progress = nil, completion = "벨로우피즈가 에버샤인을 달라고 했다고? 음...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[319] = {title = "에버샤인 얻기", objective = "얼음발톱흰곰 6마리, 덩치큰 멧돼지 8마리, 눈표범 8마리를 사냥한 다음 브루날 마을에 있는 레욜트 발리브루에게 돌아가십시오.", description = "에버샤인이 한 통 있기는 한데... 내 부탁을 먼저 들어줬으면 하네. 브루날 마을 근처의 눈 덮인 벌판을 배회하는 짐승들을 좀 없애 줬으면 하는데... 가끔 마을까지 넘봐서 말이야.\n\n물론 그 곰이나 표범, 멧돼지 따위가 무서워서 그러는 건 절대로 아닐세. 우리 드워프가 그깟 짐승들을 무서워할 리가 있겠나? 하지만 자네가 그 짐승들을 좀 처리해 준다면 우리는 그만큼 술이나 다른 물건들을 만드는 일에 투자할 시간을 벌 수 있다네.", progress = "짐승들은 다 잡았나?", completion = "고맙네. 마을밖에서 짐승 소리가 덜 들리니까 한결 마음 편히 일할 수 있군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[320] = {title = "벨로우피즈에게 돌아가기", objective = "스틸그릴의 정비소에 있는 조종사 벨로우피즈에게 에버샤인 술통을 가져다주어야 합니다.", description = "여기 에버샤인 술통을 받게. 짐승들을 사냥해 준 것 다시 한번 고맙게 생각하네.", progress = "에버샤인을 가지고 왔나?", completion = "아주 좋아. 이 정도면 충분해. 일단 맛을 좀 볼까...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n날카로운 도끼옹이진 짧은 지팡이야영용 나이프\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[321] = {title = "라이트포지 철", objective = "저습지에 있는 난파된 창공의 물수리호를 찾아야 합니다.", description = "해안에 버려진 난파선들은 지난 대전쟁 중에 붉은용의 공격으로 불에 타 가라앉은 쿨 티라스의 제 3함대의 잔해이네.\n\n그 함대는 로데론 소속이었지만 엘프 군함인 창공의 물수리호와 함께 항해하고 있었지. 이 배는 라이트포지 철을 싣고 제 3함대의 호위를 받던 중이었는데, 호위를 하던 제 3함대에 쏟아진 용들의 공격에 피해를 입어 침몰하고 말았지.\n\n옛날 이야기는 이쯤 하도록 하고, 난파된 창공의 물수리호는 메네실 항구 남쪽에 있네. 그 배에서 라이트포지 철을 찾게 되면 내게 가져다주게.", progress = nil, completion = "이 상자는 물에 흠뻑 젖어 있으며 바깥쪽 판자가 부서져 있습니다. 상자가 손상되어 있고 안팎에 발톱 자국이 무성한 것으로 보아 멀록들이 상자를 뒤져 안에 들어 있던 보물을 훔쳐 간 것 같습니다.\n\n상자 깊은 곳에 라이트포지 주괴가 하나 있습니다. 하지만 무기를 만들기에 충분한 금속을 얻으려면 더 많은 양이 필요합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n라이트포지 주괴"},
[322] = {title = "신성한 무기", objective = "스톰윈드에 있는 그리만트 엘모어에게 라이트포지 주괴가 든 상자를 가져가야 합니다.", description = "스톰윈드에 있는 드워프 지구에 라이트포지 철을 잘 다루는 그리만트 엘모어라는 드워프 대장장이가 있네.\n\n자네가 찾은 주괴를 제련하여 상자에 넣어 두었으니 그걸 그리만트에게 가져가 자네 얘길 해 보게나. 이런 일은 기꺼이 도와줄 친구니까 자네를 위해 무기를 만들어 줄 것이야. 모벤트 펠도 무서워할 만큼의 강력한 무기를!", progress = "내 솜씨로 도울 일이 있소, <class> 친구?", completion = "상당히 흥미로운 얘기군. 게다가 라이트포지 철이라니! 라이트포지 철로 작업해 본 지 몇 년은 된 것 같은데... 이 금속을 다시 다루게 되다니 영광이군. 내가 무기를 만들어 줄 테니 나중에 다시 와서 강령술사와 싸웠던 얘기를 해 준다고 약속해 주시오.\n\n너무 성급한 얘긴 건가? 자, 우선 모벤트 펠에 맞설 무기부터 만들어 보도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[323] = {title = "영웅의 진가", objective = "해골 약탈자 15마리, 해골 치료사 3마리, 해골 문지기 3마리를 처치한 다음 스벤에게 돌아가야 합니다.", description = "모벤트 펠은 강령술사로 흑기사들과 연합한 자입니다. 당신에게 모벤트 펠을 처치해 달라고 부탁하고 싶지만, 당신 실력이 어느 정도인지도 모르면서 그 악당에게 헛되이 목숨을 잃게 할 수는 없습니다.\n\n당신의 용기는 이미 인정합니다만 정말 그 강령술사를 상대하고 싶다면 그의 부하들을 먼저 쓰러뜨리고 실력을 증명해 보이기 바랍니다.", progress = nil, completion = "당신의 전투 능력은 의심할 여지가 없군요. 이제 모벤트 펠을 쓰러뜨려 그 확고한 의지를 보여 주길 바랍니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[324] = {title = "사라진 주괴", objective = "라이트포지 주괴 5개를 모은 다음 저습지에 있는 글로린 스틸브로우에게 돌아가야 합니다.", description = "물에 젖은 상자에 라이트포지 주괴가 하나 있는 것으로 보아 멀록들이 나머지 주괴를 훔쳐 간 것이 분명합니다. 난파된 창공의 물수리호 부근에서 멀록 약탈꾼들을 처치하고 사라진 라이트포지 철을 찾아야 합니다.", progress = "필요한 라이트포지 철은 찾았나?", completion = "아, 찾았군! 자, 그럼 라이트포지 철을 두드려 쓸만한 걸 한번 만들어 볼까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[325] = {title = "무기 완성", objective = "모벤트 파멸의 불꽃을 그늘숲에 있는 스벤에게 가져가야 합니다.", description = "당신이 말했던 악마에게 대항할 무기가 여기 있소. 자, 이제 모든 준비가 끝났군그래. 행운을 비오. 그리고 조만간 승리의 소식을 기다리도록 하지!", progress = "반갑습니다. 마지막으로 본 게 그리 오래되지 않았는데 당신의 눈에서 이전에는 볼 수 없었던 투지가 끓고 있는 게 보이는군요.", completion = "아, 이것은 악마 모벤트 펠에 대항할 증거가 될 것입니다! 잘하셨습니다!\n\n무기를 가져왔으니 준비가 끝났군요. 이제 모벤트 펠은 쓰러지게 될 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[328] = {title = "숨겨진 열쇠", objective = "작은 놋쇠 열쇠로 사서 헤로드의 금고를 열어야 합니다.", description = "헤로드의 장부 묶음 기록들에 병사 토르센에 대한 언급은 없지만 작은 놋쇠 열쇠가 숨겨져 있습니다.\n\n그리고 그의 쪽지를 더 조사한 결과 여러 문서에 \"비밀 금고\"가 언급되어 있는 것을 발견했습니다. 금고는 쿠르젠 주둔지 뒤편에 있는 보급창 동굴 어딘가에 있어 보입니다.\n\n이 비밀 금고를 찾으면 발견한 작은 놋쇠 열쇠를 사용해 열 수 있습니다. 그 안에서 토르센이 발각된 원인을 밝혀 줄 무언가를 찾을 수도 있을 것입니다.", progress = "금고는 겉이 청동으로 만들어져 매우 튼튼하고 무겁습니다.", completion = "금고를 열자 헤로드가 귀중히 여기는 돈과 물품들이 들어 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n사서의 홀"},
[329] = {title = "드러나는 첩자의 정체", objective = "반란군 야영지에 있는 부관 도렌에게 진흙투성이 쪽지를 가져가야 합니다.", description = "금고의 귀중한 물건들 중에는 진흙투성이의 휘갈겨 쓴 쪽지가 있습니다. 알아보기 힘들긴 하지만 병사 토르센의 여행 계획인 것 같습니다. 거기에는 정찰 경로, 접촉할 대상, 그리고 반란군의 임무를 완수하기 위한 시간 계획 등이 적혀 있습니다. 계획서에는 '-M'이라는 한 글자로 된 서명이 있습니다.\n\n이 쪽지를 작성한 것이 누구든지 간에 토르센과 매우 가까운 사이었음이 분명합니다. 또한 그자가 바로 반란군 야영지 내의 배반자일 것입니다.", progress = "토르센의 비밀을 알고 있는 자를 찾아냈소? 우리 중에 정말 배반자가 있는 거요?", completion = "고맙소. 이 쪽지는 배반자를 색출하는데 중요한 단서가 될 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[330] = {title = "정찰 일정", objective = "하사관 세스먼과 대화해야 합니다.", description = "당신이 찾아 준 쪽지에 \"-M\"이라고 서명이 되어 있는데... 누구를 말하는 건지 모르겠소.\n\n하지만... 쪽지에 따르면 이자가 지난주에 토르센과 함께 정찰을 했다는 것을 알 수 있군그래. 그러니 지난주에 토르센과 함께 정찰 임무를 수행한 자가 배반자일 거요!\n\n하사관 세스먼에게 가 보시오. 그가 정찰 일정을 관리하니 토르센과 함께 임무를 수행한 자가 누군지 말해 줄 수 있을 거요.", progress = nil, completion = "아, 예, 확인해 드리지요. 어디 보자... 지난 주라면...\n\n이런, 병사 메를이 토르센과 함께 정찰을 나간걸로 기록되어 있네요. 그들은 지난주 내내 같은 시간에 정찰 임무를 수행했었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[331] = {title = "도렌에게 보고하기", objective = "부관 도렌과 대화해야 합니다.", description = "도렌 부관님께서 이 정찰 정보를 보고하라고 하셨나요?", progress = nil, completion = "메를이 우릴 배반했다니... 마음이 아프군. 그는 언제나 용감하고 정직한 병사였는데... 하지만 우리 중에 있는 배반자를 찾아낸 것은 정말 다행이 아닐 수 없소. 찾아내지 못했다면 쿠르젠 대령에게 곧 무너지고 말았을 테니...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n밀림용 신발한철 어깨갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[332] = {title = "와인 가게 광고", objective = "갈리나 와인 상점으로 가서 수제타 갈리나에게 와인 티켓을 주고 와인 한 병을 무료로 얻으십시오.", description = "스톰윈드 시민들에게 제일 유명한 와인 가게에 대해서 물어보신 적이 있으시다면 우리 갈리나 집안에서 스톰윈드 최고의 와인을 판다는 것을 아실 겁니다. 위치도 멀지 않답니다. 도시의 아름다운 수로를 따라 상업 지구에 있답니다.\n\n자, 이 광고물을 받으세요. 가게에 있는 제 여동생 수제타에게 이 광고물을 가져가시면 저희 가게의 유명한 피노 누아 한 병을 무료로 드릴 겁니다. 절대 후회하시지 않으실 거예요!", progress = "안녕하세요, 어서 오세요. 저희 가게의 맛좋은 와인을 드셔 보셨나요?", completion = "아, 이미 레나토 오빠를 만나셨군요? 자, 받으세요. 저희 가게의 자랑인 피노 누와 와인입니다. 아제로스 어디에서도 이런 와인은 다시 못 보실 겁니다!", rewards = "다음과 같은 것들을 받습니다:\n\n피노 누아 와인"},
[333] = {title = "할란의 새 공급품", objective = "대운하 의류점으로 가서 레마 슈나이더에게 할란 바글리가 보내는 옷감 주문서를 전해줘야 합니다.", description = "최근 들어 사업이 무척 잘 되고 있어 기분이 좋아요. 마치 춥고 거친 계절을 맞이하는 것처럼 사람들이 갑옷과 튼튼한 옷을 구매하고 있는 것 같습니다.\n\n그런데 그거야 나중 일이고... 지금은 팔아야 할 옷감의 재고가 떨어져 가고 있다는 게 걱정입니다. 원단 공급자에게서 물건을 또 받아야 하는 실정이에요.\n\n이 주문서를 대운하 의류점에 있는 레마 슈나이더에게 가져다주면 정말 고맙겠습니다.", progress = "바글리씨로부터 전할 말이 있다고요?", completion = "이곳에서도 할란씨의 사업이 대박을 터뜨리고 있다는 소문이 파다해요. 좋은 소식이기는 한데 사람들이 웬 갑옷을 그리도 구입하는지 정말 의아하군요. 전쟁이 터진다거나 하는 소문도 듣지 못했거든요. 혹시 귀족들이 우리에게 뭔가를 숨기는 건 아닐까요?\n\n어쨌든 주문서를 가져다 줘서 고마워요. 자, 이건 수고해 주신 데 대한 사례니 받으세요. 할란씨에게는 공급품을 보내도록 하겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[334] = {title = "투르만의 준비물", objective = "스톰윈드 마법사 지구에 있는 라슨의 옷가게로 가서 투르만 슈나이더에게 바느질 도구를 주어야 합니다.", description = "제 아들, 투르만은 마법사 지구에 있는 라슨의 옷가게의 수습생이랍니다. 그런데 오늘 너무 서두르다가 그만 가위와 바늘을 놓고 가 버렸어요. 물론 당신처럼 위대한 분은 이보다 훨씬 중요한 일들이 있겠지만 바느질 도구 없이는 투르만이 수습생 일을 할 수가 없답니다!\n\n제발 제 아들에게 바느질 도구를 좀 가져다주시겠어요? 라슨의 옷가게는 마법사 지구에 있는 두 개의 옷 가게 중 하나인데 그 중에서 좀 더 깊숙한 곳, 마법사의 탑 근처에 있는 가게예요.", progress = "어서 오세요, 옷을 사러 오셨나요?", completion = "이런! 바느질 도구를 가지고 오지 않아서 일을 안 해도 될 줄 알았는데... 이제는 꼼짝없이 라슨씨의 일을 도울 수밖에 없게 됐네요.\n\n뭐, 할 수 없네요. 나중에 재미있는 일이 생기겠죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[335] = {title = "귀족을 위한 술", objective = "검은발톱 자데스가 다크샤이어에서 틸로아의 눈물과 저습지에서 사향쥐 뿌리를 가져다 달라고 부탁했습니다.", description = "위쇼크 경이 귀족 평의회에서 다른 사람들을 선동하는 모양이야. 그 친구, 이 작은 선술집에 대한 소문을 들은 후부터 전면적인 조사를 펼쳐야 한다고 설득하고 다니고 있지. 하지만 내게도 계획이 있소. 위쇼크 경에게 다른 곳에 신경쓸 일을 만들어 주면 되는 거 아니겠소? 그런데 당신 도움이 좀 필요할 것 같군.\n\n다크샤이어 변두리에 있는 미스트맨틀 장원의 스탈반의 정원에서 자라는 꽃이 있소. 작은 흰색 꽃인데, 사람들이 틸로아의 눈물이라고 부른다오. 또 저습지의 돌다지 댐 아래 멀리 있는 폭포의 맨 밑바닥에서만 찾을 수 있는 사향쥐 뿌리도 필요하니 좀 가져다주시오.", progress = "곧 있으면 위쇼크 경이 더 많은 지지 세력을 얻어서 훨씬 골치 아파질 거요. 아직 틸로아의 눈물이나 사향쥐 뿌리를 찾지 못했소?", completion = "훌륭하오! 품질이 아주 좋은 것들이군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[336] = {title = "귀족을 위한 술", objective = "왕국 민원실에 있는 보울즈 K. 위쇼크 경에게 검은발톱 스타우트 맥주를 주어야 합니다.", description = "위쇼크 경도 모든 사람과 마찬가지로 약점이 있소. 술을 무척 좋아한단 말이지. 그러고 보면 그 작자의 위선도 참 대단해. 낮에는 이 선술집의 문을 닫게 하려고 노력하면서 밤에는 이곳 위층에서 술을 퍼마신단 말이야. 게다가 계산은 절대 안 하지. 자, 어디 보자. 내가 특별히 준비한 술, 검은발톱 스타우트 맥주를 맘에 들어 할까? 이거 꽤나 독한 술이라오.\n\n이 술을 위쇼크 경에게 가져다주고 얼마나 좋아하는지 살펴보시오. 그 늙은 바보 녀석은 주로 왕국 민원실 근처에서 정처없이 서성거린다오.", progress = "지금 내가 바쁜 거 안 보이나? 그리고 내가 하는 말은 잘 귀담아 듣게! 나는 이 왕국의 미래를 이끌어 갈 중요한 인물이란 말이야!\n\n오… 들고 있는 건 뭔가? 시원한 술 같은데...", completion = "하하! 맛좋아 보이는 스타우트 맥주를 가져다 줘서 고맙군. 자, 이 동전은 팁일세. 그리고 이제 혼자서 술 좀 마시게 어서 사라지라고!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[337] = {title = "오래된 역사책", objective = "스톰윈드 도서관에 스톰윈드의 역사 책을 돌려줘야 합니다.", description = "이 책의 표지는 심하게 긁히고 진흙으로 덮여 있지만 책 등에 '스톰윈드의 역사'라는 단어가 적혀 있는 것은 볼 수 있습니다. 책을 열면 첫 페이지에 스톰윈드 도서관의 인장이 명확하게 찍혀 있습니다.\n\n누군가 이 책을 빌린 후에 반납하지 않은 것 같습니다.", progress = "오! 가지고 계신 그 오래된 책은 뭡니까? 한번 봐도 되겠습니까??", completion = "맙소사! 이 책은 수년 전 스톰윈드를 재건하기 전에도 이곳 도서관에 없었던 겁니다. 물론 지금은 상태가 좋지 않아 복원해야겠지만 희귀 장서 모음에 포함할 만한 가치가 충분합니다.\n\n고맙습니다. 책을 돌려주신 답례로 이걸 받아주시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[338] = {title = "가시덤불 골짜기의 푸른 언덕", objective = "가시덤불 골짜기의 푸른 언덕 원고의 잃어버린 페이지들을 모아야 합니다. 네 개의 장이 모두 완성되면 바닐 스톤팟에게 가져가십시오.", description = "네싱워리 주인님께서 이 사실을 알게 된다면 무척 화내실 거예요!\n\n그분은 저를 믿고 그분의 소설 가시덤불 골짜기의 푸른 언덕의 원고 교정을 맡기셨답니다. 교정 작업은 순조롭게 진행되고 있었는데 야영지에 엄청난 돌풍이 불어 원고가 낱장으로 여기저기로 흩어지고 말았어요!\n\n대부분의 원고를 되찾았지만 아직도 많은 페이지들이 정글에 흩어져 있어요. 네 개의 장을 각각 완성할 수 있도록 흩어진 페이지들을 모아 주세요.\n\n네 개의 장을 모두 모아 제게 가져 오시면 순서에 맞게 정리하는 것을 도와 드리도록 하죠.", progress = "네 개의 장을 모두 모으셨나요?", completion = "오, 정말 골치 아픈 문제를 해결해 주셨군요! 어떻게 감사해야 좋을지 모르겠습니다. 이제 곧 주인님의 책을 전 세계 도서관에서 볼 수 있게 될 겁니다!", rewards = "다음과 같은 것들을 받습니다:\n\n밀림용 장화두꺼운 방어구 키트최상급 치유 물약"},
[339] = {title = "제 1 장", objective = "바닐 스톤팟이 네싱워리의 소설 가시덤불 골짜기의 푸른 언덕의 1장을 완성할 수 있도록 1, 4, 6, 8 쪽을 가져가야 합니다.", description = "1장은 상당히 매력적이랍니다. 1장에서 네싱워리 주인님은 이야기의 배경을 설정하고 그의 사냥 동료들에 대해 묘사하고 있습니다. 물론 저도 포함해서요!\n\n하지만 지금 그게 중요한 게 아닙니다. 아직 찾지 못한 쪽을 한번 확인해 봅시다. 음... 1, 4, 6, 8 쪽이 없군요. 그렇다면 아직 정글 어딘가에 흩어져 있는 것이 틀림없습니다!", progress = "1, 4, 6, 8 쪽을 찾지 못한 것 같군요? 이 네 쪽이 있어야 1장을 다시 완성할 텐데...", completion = "드디어 1장이 완성되었습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n가시덤불 골짜기의 푸른 언덕 - 제1장"},
[340] = {title = "제 2 장", objective = "바닐 스톤팟이 네싱워리의 소설 가시덤불 골짜기의 푸른 언덕의 2장을 완성할 수 있도록 10, 11, 14, 16 쪽을 가져가야 합니다.", description = "2장은 퓨마와 호랑이 사냥에 관한 흥미진진한 이야기로 가득하답니다. 이 장의 쪽들을 바람에 날려 버리고 고작 자책밖에 할 수 없다니...!\n\n10, 11, 14, 16 쪽만 되찾으면 2장의 원고를 모두 복구할 수 있을 것 같습니다.", progress = "10, 11, 14, 16 쪽이 있어야만 2장을 완성할 수 있습니다.", completion = "2장이 마침내 완성되었습니다! 잘하셨습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n가시덤불 골짜기의 푸른 언덕 - 제2장"},
[341] = {title = "제 3 장", objective = "바닐 스톤팟이 네싱워리의 소설 가시덤불 골짜기의 푸른 언덕의 3장을 완성할 수 있도록 18, 20, 21, 24 쪽을 가져가야 합니다.", description = "3장은 제가 가장 좋아하는 부분입니다. 3장에서는 얼가딘 경과 루아크 양이 드워프 라이플 총으로 첫 번째 사냥을 했던 이야기가 실려 있답니다. 3장의 마지막은 정말 손에 땀을 쥐게 하지요!\n\n3장에서는 아직 18, 20, 21, 24 쪽이 빠져 있습니다. 저 밖의 어딘가에 있을 텐데...", progress = "18, 20, 21, 24 쪽은 찾으셨나요? 이쪽들만 찾으면 3장의 원고는 모두 되찾게 되는 겁니다.", completion = "휴! 정말 잘하셨습니다. 이제 3장을 모두 되찾았군요!", rewards = "다음과 같은 것들을 받습니다:\n\n가시덤불 골짜기의 푸른 언덕 - 제3장"},
[342] = {title = "제 4 장", objective = "바닐 스톤팟이 네싱워리의 소설 가시덤불 골짜기의 푸른 언덕의 4장을 완성할 수 있도록 25, 26, 27 쪽을 가져가야 합니다.", description = "아, 대미를 장식하는 4장! 정말 멋진 결말이었답니다.\n\n이 장의 원고는 단 세 쪽이 빠져 있습니다. 25, 26, 27 쪽만 찾으면 4장의 원고를 모두 되찾게 됩니다.", progress = "세 쪽만 있으면 4장을 완성할 수 있습니다. 25, 26, 27 쪽을 찾으셨나요?", completion = "정말 훌륭합니다! 이제 4장의 원고를 모두 모았군요!", rewards = "다음과 같은 것들을 받습니다:\n\n가시덤불 골짜기의 푸른 언덕 - 제4장"},
[343] = {title = "불굴의 의지에 대한 연설", objective = "스톰윈드 왕궁에 있는 왕실 도서관으로 가서 밀턴 시프와 대화해야 합니다. 그는 수사 크리스토프가 연설에 필요로 하는 야금술에 대한 책을 찾아 줄 수 있습니다.", description = "이번 총회에서 불굴의 의지에 대한 연설을 할 예정인데, '철강의 중요성'이라는 야금술에 대한 책에서 몇 구절을 인용했으면 하오. 이 책의 사본이 스톰윈드 왕궁 내의 왕실 도서관에 있을 텐데 가져다줄 수 있겠소? 그렇다면 신의 은총을 받을 것이오!\n\n왕실 도서관은 매우 넓지만 그곳의 수석 사서인 밀턴 시프는 각각의 책 선반을 샅샅이 꿰고 있으니까 그에게 얘기하면 책을 찾아 줄 것이오.", progress = nil, completion = "야금술이요? 아, 예, 야금술에 관한 책이 많이 있지요. 크리스토프 수사님께서 연설하시는 데 도움을 드릴 수 있어 기쁘군요! 자... 수사님이 필요로 하시는 책의 제목은 무엇이던가요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[344] = {title = "수사 팩스턴", objective = "노스샤이어 수도원에 있는 수사 팩스턴과 대화해야 합니다.", description = "철강의 중요성이라고요? 알고말고요. 몇십 년 전에 드워프 광부인 마굴프 블라곤이 쓴 꽤 흥미로운 책이죠. 저자는 대부분의 삶을 카즈 모단의 깊은 산맥에서 광석을 캐면서 보냈다죠. 대단한 친구 아닙니까!\n\n참, 어디까지 얘기했죠? 그렇지, 철강의 중요성! 어떡하죠, 그 책은 지금 노스샤이어 수도원에 있는 것 같네요. 수도원 도서관의 관리자인 팩스턴님이 그 책의 사본을 만들기 위해 가져가셨거든요.\n\n그런데 그게 벌써 몇 달 전의 일인데... 왜 이리 오래 걸리는지 모르겠네요.", progress = nil, completion = "밀턴 씨가 책이 어디 있는지 궁금해하고 있다고요? 이것 참 곤란하게 됐군요. 저에게 그 책이 있기는 하지만 아직 사본을 다 만들지 못했기 때문에 원본을 아직 반납할 수가 없는데 말입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[345] = {title = "잉크 공급", objective = "레이크샤이어에 있는 현장감독 오슬로우와 대화하여 레스밴 철광석을 달라고 부탁해야 합니다.", description = "철강의 중요성의 사본을 완성하려고 했습니다만 보시다시피 전 제가 필사하는 책에 저만의 잉크를 사용한답니다. 제가 직접 만든 잉크인데 퍼지거나 스며들지 않고 매우 빨리 마르거든요. 단점이 있다면 정말 너무 빨리 마른다는 것입니다! 사본을 다 만들기 전에 마지막 잉크가 다 떨어졌는데, 아직 잉크를 더 만들 기회가 없었답니다!\n\n잉크를 만들려면 붉은마루 산맥의 레스밴 광석이 필요합니다. 그 광석은 주로 레이크샤이어에 있는 현장감독 오슬로우님이 공급해 주셨었습니다.", progress = nil, completion = "뭐가 필요하다고 했나?? 아직 이곳 상황을 잘 파악하지 못한 모양이네만, 지금은 레이크샤이어의 방어 병력을 강화하고 최근에 있었던 오크의 공격으로부터 받은 피해를 복구하느라 아주 바쁘단 말일세. 레스밴 광석이 필요하면 직접 가서 캐 가게나!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[346] = {title = "수사 크리스포트에게로", objective = "대성당 광장에 있는 수사 크리스토프에게 돌아가서 '철강의 중요성'을 전달해야 합니다.", description = "자, 책의 사본을 다 완성했습니다. 이게 '철광의 중요성' 원본이니 받으세요. 인내심을 가지고 기다려 줘서 정말 고맙습니다. 아참, 밀턴 씨에게는 시간이 오래 걸려서 미안하다고 전해 주십시오.", progress = "책을 찾아 오셨소?", completion = "바로 이것이로군! 감사하오. 부디 그대의 육체와 영혼이 밝게 빛나기를!", rewards = "다음과 같은 것들을 받습니다:\n\n여행용 장화"},
[347] = {title = "레스밴 광석", objective = "레스밴 광석 5개를 모아서 노스샤이어 도서관에 있는 수사 팩스턴에게 가져가야 합니다.", description = "레스밴 광석은 이 광석을 처음 발견한 바트 레스밴의 성을 따서 이름을 붙인 걸세. 용해할 경우 철처럼 단단하지는 못하지만 어둡고 탁한 색을 내기 때문에 잉크로 사용하는 서기들이 종종 있지. 이곳 북쪽에 있는 레스밴 동굴로 가면 찾을 수 있을 걸세.\n\n평소에는 비축해 놓은 것이 몇 개 있었지만 최근에는 오크의 공격에 대비하느라 채취할 시간이 없었지. 게다가... 지금은 레스밴 동굴에 붉은마루일족 놀도 살고 있고 붉은마루일족 노역꾼들이 그 광석을 캐고 있다네.\n\n그러니까 필요하다면 직접 가서 가져오는 수밖에 없다네.", progress = "레스밴 광석을 가지고 오셨나요?", completion = "오, 훌륭하군요! 이 광석으로 잉크를 만들어서 '철강의 중요성'을 마저 베껴 쓸 수 있을 겁니다.\n\n고맙습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[348] = {title = "가시덤불 골짜기의 열병", objective = "의술사 운바그와를 찾아 흉포한 모크를 불러내도록 해야 합니다. 핀 피즈라켓에게 모크의 심장을 가져가야 합니다.", description = "아...아파...너...너무 아파...\n\n가시덤불 골짜기의 열병에 걸리고 말았어요...지...지독한...바이러스...\n\n유...유일한 치료야...약은...모...모...흉포한 모크의 심장을 머...먹는 건데...그...사납고...자...잡기도 힘든...하얀 짐승...\n\n의술사 운바그와만이...유일하게 부...불러낼 수 있어...요..\n\n남쪽의 곶에 있는 숨겨진 동굴에서 운바그와를 좀 찾아...주...주세요.\n\n빨리요...나...난 죽어 가고...있어요...", progress = "....엄마?\n\n...너무 추워요...\n\n...뒤틀린 황천으로 가고 있어요...어...엄마...날 노...노...놓지 마세요...", completion = "기...기운이 회복되는 것 같아요...\n\n여기는 어디인가요? 무법항? 이런! 정말 이상한 꿈을 꾸었어요.\n\n...아직 몸이 완전히 회복되지는 않은 것 같은데...", rewards = "다음과 같은 것들을 받습니다:\n\n간호용 담요"},
[349] = {title = "가시덤불 골짜기의 열병", objective = "temp text 02 - log", description = "temp text 02 - description", progress = "의술사 운바그와는 흉포한 모크가 어떤 놈인지 알지. 그럼, 아암!\n\n내가 영혼과 얘기하고 그가 오게 해 주지.\n\n하지만 다른 고릴라 짐승도 영혼이랑 얘기하는 것을 좋아하네. 나 의술사 운바그와를 보호하면 그가 오게 해 주지.\n\n우선 나 의술사 운바그가 필요한 게 있지. 고릴라 송곳니 10개 갖고 오면 영혼과 얘기를 시작하지!", completion = "나 의술사 운바그와는 고릴라 송곳니를 좋아해! 너를 위해서 영혼과 대화하지! 흉포한 모크가 오게 해 주겠어.\n\n그래도 다른 고릴라 짐승에게서 나 의술사 운바그와 보호 안 하면 모크는 오지 않아!", rewards = nil},
[350] = {title = "오랜 친구 찾기", objective = "스톰윈드에 있는 엘링 트리아스와 대화해야 합니다.", description = "그 마르존 녀석이 데피아즈 단원과 접촉하고 있었을 테니 라스코발과 연관이 있을 걸세...\n\n밴클리프와 스레드가 죽었으니 라스코발을 법대로 처리하기가 어렵게 됐어. 그들의 증언 없이는 자네 증거도 아무 소용이 없으니까 말이야. 더군다나 라스코발은 귀족이고 고위 인사와 관계도 두텁지. 법 위에 사는 녀석이야.\n\n다른 데서 도움을 받아야 할 것 같아. 정말 내키진 않지만 우리를 도와줄 만한 자가 있네. 이 도시의 상업 지구에 있는 트리아스를 찾아보게.", progress = nil, completion = "농담하시는 겁니까? 쇼가 또 내 도움을 필요로 한단 말입니까? 염치도 없군...\n\n데피아즈단이라고 하셨나요? 정말이지 놀랄 만한 소식만 가지고 오시는군요. 다음에는 데스윙이 아직 살아서 도시를 공격한다는 소식을 가져오시겠군요.\n\n좋습니다. 처음부터 모두 말해주시기 바랍니다. 중요하지 않다고 생각되는 것이라도 빠뜨리지 말고 모조리 다 얘기해 주셔야 합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[351] = {title = "OOX-17/TN 수색", objective = "오글소프의 유도 로봇에게 조난 탐지기를 가져가야 합니다.", description = "금속으로 만들어진 이상한 알처럼 생긴 장치를 찾았습니다. 손잡이 하나를 만지작거리다 보니 장치가 열리면서 노움 로봇 장치가 들어있는 것이 보입니다! 그 속에서 누군가의 목소리가 잡음에 섞여서 들립니다.\n\n\"이름은 오글소프... 내 유도 로봇이 불시착했는데 찾아주면 사례를 하겠소! 이 탐지기를 로봇에게 가져가시오. 다행이군, 방금 로봇의 현재 위치를 산출해 보았는데 타나리스에 있는 모래지옥 협곡 부근에 추락한 것 같소!\"", progress = "로봇의 잔해를 찾은 것 같은데 모양을 보니... 닭인 듯합니다. 알 속에서 다시 목소리가 들려옵니다.\n\n\"잘했소! 그것이 바로 내 유도 로봇이오. 다시 무법항으로 보내 수리를 하려면 급속 시동을 걸어야 할 것 같소. 이 탐지기를 로봇에 넣으시오. 나머지는 탐지기가 알아서 할 거요!\"", completion = "알을... 아니 조난 탐지기를 닭... 아니 유도 로봇에 넣습니다.\n\n로봇이 윙윙거리는 소리를 내면서 일어서려고 합니다. 로봇이 작동을 하자 오글소프의 목소리가 다시 들려오는 데 이번에는 로봇에서 납니다.\n\n\"OOX-17/TN이 작동은 하지만 큰 수리를 해야 할 것 같소! 당신이 들고 오기에는 너무 무겁지... 조금만 더 내 로봇을 봐주지 않겠소? 좋은 생각이 한 가지 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[353] = {title = "스톰파이크에게 소포 배달", objective = "모단 호수에 있는 산악경비대 스톰파이크에게 스톰파이크의 소포를 배달해야 합니다.", description = "스톰파이크 씨는 존경받는 드워프 일원이며 전투 감각이 뛰어나고 무기를 고르는 안목도 대단한 것으로 유명하다오. 이렇다 보니 아이언포지에서 그링거 스톰파이크 씨가 내게 무기를 만들어 달라고 주문한 것도 전혀 놀랄 일이 아니지.\n\n무기는 다 만들었는데... 스톰파이크 씨가 저 멀리 모단 호수에 있어서 말이오. 혹시 북쪽으로 여행할 계획이 있으면 이 물건을 내 대신 배달해 주지 않겠소?\n\n스톰파이크 씨에게 받은 마지막 전갈에 의하면 모단 호수의 북쪽 경비탑에서 근무하고 있다고 하오.", progress = "스톰윈드에서 여기까지 왔다고 했소? 내가 듣기로는 그곳 인간들의 땅에서는 도적과 오크들이 날뛰어서 점점 위험해지고 있다고 하던데... <class>|1이;가; 자신의 가치를 증명해 보이기에는 완벽한 무대겠군그래!", completion = "아하! 그러니까 그리만트 씨가 드디어 내 도끼를 완성한 게군! 새 무기를 손에 잡으니 몸이 근질근질한데... 어서 트로그와 코볼트를 상대로 무기의 성능을 시험해 봐야 할 텐데 말이오!\n\n정말 고맙소, 친구. 이걸 배달하러 그 먼 거리를 여행하기란 쉽지 않았을 텐데... 자, 이 돈을 수고비로 생각해 주시기 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[354] = {title = "가문의 몰살", objective = "브릴에 있는 콜만 파딩에게 그레고르의 유골, 니사의 유해, 투르만의 유골을 가져가야 합니다.", description = "아가만드 가문은 티리스팔 숲에서 가장 부유한 가문이었지요. 역병이 닥치지 전에는 저도 그들의 밀농장에서 일했었고 말입니다.\n\n스컬지가 처음 공격해 왔을 때 아가만드 가문은 가택을 요새화하고 피고용인들을 설득해서 함께 방어하게 했답니다. 그러나 적어도 우리는 충직한 바보였습니다...\n\n그런데 아가만드 가문이 우리를 언데드로 만들어 버렸습니다! 그리고 그들은 이제 스컬지의 앞잡이입니다!\n\n역병에 넘어간 아가만드 가문을 처단하여 포세이큰에 봉사하십시오. 그들의 유골을 제게 가져와 주시기 바랍니다.", progress = "아가만드 가문의 유골을 가지고 왔나요? 드디어 그 저주받은 자들이 처단된 것인가요?", completion = "아, 복수를 하고나니 정말 상쾌하군요. 혹시 아가만드들을 없애버릴 때 그들에게 의식이 조금이라도 남아 있던가요? 제발 그랬었다면 좋겠습니다. 영원한 망각의 나락으로 떨어지기 전에 그들이 소름 끼치는 공포를 느꼈어야 하는데... \n\n어리석은 말인 건 알지만 제 간절한 소망입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[355] = {title = "세브렌과의 대화", objective = "브릴에 있는 집정관 세브렌과 대화해야 합니다.", description = "<class>님께서 아가만드 가문의 유골을 가져다준 덕분에 이제 복수의 욕망은 채워졌습니다. 하지만 아가만드 밀농장은 저뿐만 아니라 모든 포세이큰들에게 위협이 되고 있습니다.\n\n아가만드 가문을 상대로 이룬 <class>님의 공적을 집정관 세브렌님께 말씀드렸더니 만나 보고 싶어하십니다. 그분께 가 보시기 바랍니다.", progress = nil, completion = "콜만이 자네 칭찬을 많이 하더군. 아가만드 밀농장에 가서 콜만의 복수를 해줬다면서?\n\n원한다면 포세이큰을 위해 자네의 실력을 한 번 더 보여줬으면 하는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[356] = {title = "후방 경비", objective = "피투성이 좀비 8명과 떠도는 영혼 8명을 처치한 다음 초소로 돌아가 리니아에게 보고해야 합니다.", description = "역병지대로부터 티리스팔을 방어하는 보루 수비대의 경계 태세가 철통 같긴 하지만, 간혹 스컬지가 몰래 경계를 통과하기도 하오.\n\n정면의 적만 상대하면 뒤에서 공격을 당하거나 수비대에게 보급로가 차단당할 수 있다는 문제가 있어.\n\n그래서 말인데 보루 방어를 좀 도와주지 않겠소? 동쪽으로 순찰을 나가 눈에 띄는 스컬지를 모두 처치해 주시오. 특히 동쪽에 있는 발니르 농장이 이 침략자들의 본거지가 되어 버린 것 같으니 그곳에 있는 스컬지들을 처치해 주시오.", progress = "순찰은 어찌 되어 가오?", completion = "아주 좋아. 당신의 노력 덕분에 스컬지들에 대한 수비가 한층 수월해졌군. 나의 상관이신 자이건드 집행관님 앞으로 추천장을 써 주도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[357] = {title = "마술사의 정체", objective = "언더시티에 있는 베소르 아이스샤드에게 마술사의 마법책을 가져가야 합니다.", description = "북쪽 청명 호수에 섬이 있는데 거기에 마술사가 한 명 살고 있지. 그가 자유의지를 가진 포세이큰이기는 하지만 다른 언데드들은 모두 스컬지 노예라고 여기는 데다, 그에게 접근하는 자는 누구든 졸개들을 시켜 공격한다네.\n\n그가 강령술에 능통하다면 우리에게 큰 도움이 될 것이며 포세이큰의 일원이기에 어둠의 여왕님께 충성해야 마땅하네.\n\n그의 정체와 능력을 알아내려면 그의 마법책이 필요해. 그의 은거지로 숨어 들어가서 마법책을 훔친 다음 내게 가져다주게.", progress = "마법책을 입수했나?", completion = "수고했네. 이 책을 조사하여 그 마술사의 정체를 밝혀내도록 하겠네. 여왕님을 위해 큰일을 해 주었군.\n\n&lt;책을 열어 붉게 빛나는 책장들을 신중히 읽는 베소르...&gt;\n\n놀랍군! 이 책은 바로 군터 아카누스의 것이야! 군터는 생전에 뛰어난 마술사였네. 그와 나는 친구이자 역병 이전에 함께 싸운 전우이기도 하지. 이 책의 내용으로 볼 때 그는 죽고나서 오히려 더 강해진 것 같군.\n\n그의 능력이 우리에게 큰 힘이 될 수 있을 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[358] = {title = "묘지 도굴꾼", objective = "썩은가죽일족 도굴꾼 8마리와 썩은가죽일족 싸움꾼 5마리를 처치해야 합니다.\n\n이들에게서 불변의 영액 8개를 모은 후 브릴에 있는 집정관 세브렌에게 가져가야 합니다.", description = "북쪽 가렌의 흉가의 남서쪽엔 묘지가 하나 있는데, 그 묘지는 역병이 처음 퍼졌을 때 안타깝게 죽은 수많은 티리스팔 주민들을 매장하기 위해 만들어진 곳일세.\n\n이 묘지의 시체들은 지금까지 언데드가 되는 신세를 면해 왔는데 최근 스컬지가 썩은가죽 놀들을 보내 시체를 모아 그들의 군대로 만들려 하고 있어. 절대 이런 일이 일어나서는 안 되지!\n\n자네의 임무는 두 가지네. 가렌의 흉가와 묘지에서 썩은가죽 놀들을 처치하고 그들에게 생명을 불어넣는 불변의 영액을 빼앗아 돌아오게나.", progress = "임무를 완수했나? 그 지저분한 것들을 죽이고 영액을 빼앗았나?", completion = "잘했네. 우리를 상대로 저 시체들을 이용할 수 있다고 생각했다면 스컬지가 단단히 착각하고 있는 것이야. 그리고 자네가 썩은가죽일족 노예들에게 빼앗아 온 영액은 우리 연금술사들이 연구하게 될 걸세. 반대로 우리가 스컬지들을 상대로 역이용할 수 있을지도 모르는 일이니 말이야.\n\n자네 정말 잘해냈어. 어려운 상황이 계속되고 있으니 앞으로도 포세이큰을 위해 자네의 가치를 증명할 수 있는 기회는 자주 있을 거라고 믿네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n차가운 강철 건틀릿좀비 가죽 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[359] = {title = "포세이큰의 의무", objective = "죽음의경비병 리니아와 대화해야 합니다.", description = "동쪽에 있는 죽음의경비병 초소로부터 최근 상황에 대한 보고를 받아야 하네.\n\n스컬지 병력이 보루를 빠져나와 티리스팔로 들어왔는지가 내 관심거리일세. 역병지대 변두리에 대한 경계를 유지하지 않으면 스컬지가 이 지역에 근거지를 구축할지도 몰라!\n\n길을 따라 남쪽으로 이동한 후 세 갈래 길에서 동쪽 길로 가면 초소가 나오네. 죽음의경비병 리니아와 이야기를 나눠보면 필요한 정보를 들을 수 있을 거야.", progress = nil, completion = "집정관 세브렌님이 보고를 원하신다고? 좋아! 그럼 현재 상황을 말해주지. 보루 수비대가 대부분의 스컬지들을 저지하고 있지만 간혹 몇몇이 빠져나가기도 하고 있어.\n\n발니르 농장을 중심으로 이곳의 초소 동쪽에서 스컬지의 활동이 드문드문 발견되고 있는 상황이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[360] = {title = "집정관에게 돌아가기", objective = "브릴에 있는 집정관 세브렌에게 돌아가야 합니다.", description = "이제 내가 알려준 정보들을 집정관 세브렌님께 보고해 주시오. 세브렌님께서 가능한 빨리 보고를 받길 원하실 것이니 최대한 서두르시오.\n\n돌아가는 길에 혹시 스컬지가 눈에 띄거든 없애 버리도록 하시오. 우리 땅에서 그들이 활개치는 걸 볼 순 없으니까 말이오.", progress = nil, completion = "스컬지가 계속해서 보루를 빠져나오고 있다니 골치 아픈 일이군. 리치 왕과 부하 녀석들 정말 끈질긴 놈들이 아닐 수 없어.\n\n그들의 공격을 계속 당하고만 있을 순 없지. 다시 리치 왕이 우릴 조종할 순 없을거야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[361] = {title = "배달되지 않은 편지", objective = "이베트 파딩을 찾아서 투르만 아가만드가 쓴 편지를 전해줘야 합니다.", description = "아가만드가의 장남인 그레고르 아가만드의 장남이 쓴 편지입니다. 수신자가 이베트 파딩으로 되어 있지만 아직 배달되지 못한 것이 분명해 보입니다.", progress = "뭐라고요?", completion = "오... 불쌍한 투르만! 나와 우리 아버지가 아가만드 밀농장을 함께 떠나자고 그리도 설득했건만, 가문에 대한 충성심이 너무나 강한 사람이라 그대로 남아 있었답니다. 이렇게 될 줄 알았어요! 브랜드가 해코지할 줄 알았다고요!! 아, 이 저주스런 역병과 스컬지들!\n\n&lt;이베트의 얼굴이 부드러워졌다가 다시 차가워지며&gt;\n하지만 후회는 약한 자들이나 하는 것이에요. 포세이큰의 일원으로 나에겐 새로운 목표들이 있고, 이제 더 이상 사랑 따위의 감정은 거기에 포함되지 않아요. 이 편지를 배달해 준 건 고맙군요. 옛 애인에게 어떤 일이 일어났는지 그동안 많이 궁금해 했으니까요.\n\n하지만 그때의 인생은 이미 끝났어요, 영원히.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[362] = {title = "밀농장의 유령", objective = "데블린을 처치한 후 그 유골을 브릴에 있는 콜만 파딩에게 가져가야 합니다.", description = "데블린 아가만드는 아가만드 가문의 두 아들 중 막내였는데 형과 그렇게 다를 수 없었답니다. 형인 투르만은 키도 크고 상냥했지만 데블린은 약골에다 입은 매우 거칠었어요.\n\n그래서 아가만드 밀농장에 역병이 퍼졌을 때 데블린이 제일 먼저 죽었다는 소식을 들었지만 인과응보라는 생각에 별로 놀라지도 않았답니다. 아직도 아가만드 밀농장으로 가는 도로 근처에서는 그의 광기 어린 중얼거림이 들린다고 하더군요.\n\n저는 지금 아가만드 가문의 유골을 모으고 있는 중인데 불운한 데블린의 유골이 탐난답니다. 그를 찾아 처치한 후에 유골을 제게 가져다주시기 바랍니다.", progress = "데블린은 찾았습니까?", completion = "감사합니다. 데블린의 유골은 제 손 안에서 편히 쉬게 될 겁니다. \n\n제 차가운 심장이 온기를 찾는다면 그건 아가만드 가문이 완전히 처치되었다는 소식을 들은 이후일 겁니다. 역병이 닥쳐 왔을 때 그들은 저와 제 가족을 속였습니다. 이젠 그들의 유골을 직접 밟아서 부숴 버릴 겁니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[363] = {title = "각성의 시간", objective = "어둠의사제 사비스와 대화해야 합니다.", description = "제때 깨어났구려. 다른 이들과 함께 불 속에 던져 넣으려던 참이었는데...\n\n나는 데스넬의 무덤을 관리하고 있는 모르도라고 하오. 이제 당신은 더 이상 리치왕의 노예가 아닌 포세이큰의 일원으로 다시 태어났소.\n\n언덕 아래쪽으로 내려가다 보면 성당이 나올 거요. 거기에 있는 어둠의사제 사비스님과 얘기해 보시오. 그분이 포세이큰의 일원이 된 자로서 알아야 할 얘기를 자세히 들려주실 것이오.", progress = nil, completion = "걸어다니는 송장이 또 오셨군. 어둠침침한 무덤에서 깨어났더니 반겨주는 거라곤 추위와 모르도 뿐이었을 테니 충격이 컸을 거야, 안 그런가?\n\n자네 얼굴에 혼란의 빛이 역력해. 자, 그럼... 우리의 상황을 설명해 주도록 하지.\n\n우리는 새로운 지도자이신 실바나스 여왕님 덕분에 리치 왕의 수하에서 벗어나게 되었네. 어둠의 여왕이신 실바나스님께서 증오스런 스컬지들과 우리의 뒤를 쫓고 있는 인간들과의 전쟁을 이끌고 계시는 상황이네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[364] = {title = "넋 나간 좀비", objective = "어둠의사제 사비스가 넋 나간 좀비 8명과 흉측한 좀비 8명을 처치해 달라고 부탁했습니다.", description = "우리 포세이큰은 지금 리치 왕의 스컬지 군대와 전쟁 중이라네. 놈들은 마법으로 소환된 언데드, 북쪽의 사악한 짐승들, 그리고 고통받는 유령들로 이루어진 군대야.\n\n이 넋 나간 좀비들이 우리 마을 동쪽 지역을 침범했네. 반드시 놈들을 말살시켜야 해. 설사 그들이 우리의 옛 형제, 자매들이었을지 몰라도 이젠 리치 왕의 노예일 뿐일세. 가차없이 처치하도록 해.", progress = "저런 나약한 좀비들조차 처치하지 못한다면 이곳에서 살아남을 수 없어. 임무를 완수하기 전에는 돌아오지 말게!", completion = "저 많은 숫자의 스컬지들을 우리 편으로 만들 수 있다면 앞으로의 전투에 큰 도움이 될 텐데 아쉬울 뿐이군.\n\n우리 편으로 만들 수 없다면 없애버리는 수밖에...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아마포 장갑닳아해진 망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[365] = {title = "오염된 농장", objective = "데스넬 북쪽에 있는 농장에서 티리스팔 호박을 10개 훔친 다음 브릴에 있는 연금술사 요한에게 가져가야 합니다.", description = "이건 또 뭔가? 아, 풋내기 <class>|1이로군;로군;! 어둠의 여왕님께 능력을 증명해 보이고 싶다면 포세이큰의 방식부터 배우는 게 좋을 거야.\n\n서쪽에 농장이 하나 있네. 인간들이 마치 썩은 시체 위에 곰팡이처럼 그곳을 오염시키고 있지. 게다가 주변에 있는 탑은 붉은십자군 녀석들이 순찰하고 있어.\n\n저 오합지졸들에게 한 수 가르쳐 주고 저들이 소중하게 여기는 호박을 10개 훔쳐 오게. 10개를 다 모으면 브릴에 있는 연금술사 요한에게 가 보라고.", progress = "죽음의경비병 시머가 당신이 필요한 재료를 가지고 올 거라고 연락했더군. 티리스팔 호박 10개는 다 모았소?", completion = "맡은 일을 잘해냈군, &lt;class&gt;. 어둠의 여왕님의 군대에 쓸만한 인재가 되겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[366] = {title = "마법책 반납", objective = "군터의 은거지로 가서 군터의 마법책을 돌려주어야 합니다.", description = "오래전 군터와 나, 그리고 지금은 스컬지 강령술사가 된 까마귀발톱 쑤울은 달라란에 있는 마법사 학회인 키린 토에서 함께 공부하는 사이였네.\n\n군터와 나는 모두 역병에 휘말렸었는데, 난 그가 죽었거나 리치 왕 수하의 귀족이 되었겠거니 하고 생각하고 있었지. 그가 자유로운 몸이라는 사실을 알게 되어 기쁘군.\n\n그를 반드시 우리 편으로 끌어들여야 하네. 이 마법책을 그 친구가 보게 되면 나 역시 리치 왕으로부터 자유로운 몸이라는 걸 그에게 보여 주도록 책에 주문을 걸어 놓았네. 그가 마법책을 본 후 우리에게 동참하길 바라네.", progress = "자네를 여기로 보낸 걸 보니 자네의 주인은 참 어리석군! 난 다시는 스컬지의 노예가 되지 않을 걸세!", completion = "내 책이라고?!? 자네가 바로 책을 훔친 도둑이로군!\n\n그런데 책에 걸려 있는 이 새로운 마법 기운은... 베소르? 그가 로데론에 있다고?\n\n그가 아직 살아 있다면 그 친구도 리치 왕의 손아귀에서 벗어난 모양이군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[367] = {title = "새로운 역병", objective = "브릴에 있는 연금술사 요한이 암흑사냥개 피 5병을 가져다 달라고 부탁했습니다.", description = "실바나스 여왕님께서 왕립 연금술 학회 총회를 소집하셨소. 어둠의 여왕님께서는 우리의 지식과 새로 발견된 마법을 결합하면, 아서스를 파멸로 이끌 수 있는 방법을 찾을 수 있을 거라 믿고 계시오. 그래서 우리에게 아제로스에 알려진 그 어떤 병보다도 치명적인 새로운 역병을 만들어내라고 명령하셨지. 이 새로운 역병은 아서스의 스컬지 군대를 파멸로 이끌게 될 것이오.\n\n연구해 보니 새로운 역병을 만드는 데 짐승의 피가 핵심적인 요소가 될 수도 있을 것 같더군. 내 이론을 시험해 볼 수 있도록 암흑사냥개 피 5병을 가져다주시오.", progress = "암흑사냥개 피 5병을 다 모았소? 서두르시오, 시간이 없소!", completion = "수고했소. 애써 줘서 고맙소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n약한 재생의 물약"},
[368] = {title = "새로운 역병", objective = "브릴에 있는 연금술사 요한이 티리스팔 숲에 있는 썩은지느러미멀록 비늘 5개를 가져다 달라고 부탁했습니다.", description = "당신이 재료를 모아 오는 동안 몇 가지 실험을 해 봤는데 이 새로운 역병을 퍼뜨리기 위해선 몇 가지 재료가 더 필요하다는 걸 알게 됐소. 운 나쁘게 실험용으로 발탁된 녀석들 몇 명을 독살하는 건 쉬운 일이지만 온 세상에 역병을 퍼뜨리는 건 좀 더 복잡하단 말이지.\n\n북쪽이나 서쪽에 있는 해안으로 가면 멀록들이 있을 것이니 그들을 처치하고 썩은지느러미멀록 비늘 5개를 가져다주시오.", progress = "썩은지느러미멀록 비늘 5개를 가지고 왔소?", completion = "이 비늘은 완벽하군. 내가 필요했던 게 바로 이것이야.", rewards = "다음과 같은 것들을 받습니다:\n\n졸음 모래"},
[369] = {title = "새로운 역병", objective = "브릴에 있는 연금술사 요한이 흉포한 검은그물거미의 독 4개를 가져다 달라고 부탁했습니다.", description = "당신이 비늘을 모아 오는 동안 오래된 서적에서 고대의 역병이 수천 명의 무고한 희생자를 냈다는 사실을 발견했지. 그 역병의 치명적인 병원체가 검은그물거미의 독액에 들어 있다고 하는군.\n\n이 실험을 끝낼 수 있도록 흉포한 검은그물거미의 독을 가지고 오시오. 독액의 병원체가 내가 새로 만든 조제약과 잘 어울리는지 봐야겠소. 소문에 의하면 그 거미는 티리스팔 숲 동부 지역에 있다고 하오.", progress = "아직 검은그물거미의 독을 가져오지 못했소? 그 독이 있어야 최종적인 실험 결과를 얻을 수 있소.", completion = "그래, 이 독이면 충분해. 나머지 재료는 이미 다 구해서 끓여 놓은 상태라오. 드디어 이 새로운 병원체를 실험해 볼 수 있겠군!", rewards = "다음과 같은 것들을 받습니다:\n\n수습생 장식띠"},
[370] = {title = "붉은십자군과의 전쟁", objective = "브릴에 있는 집행관 자이건드가 대장 페린, 붉은십자군 광신도 3명, 붉은십자군 선교사 3명을 처치해 달라고 부탁했습니다.", description = "집행관 아렌이 보내 온 전략 문서에는 이 땅에서 인간을 내쫓는 데 필요한 모든 정보가 들어 있네. 이 정보에 따르면 붉은십자군이 페린 대장과 그의 부대를 브릴 남서쪽의 폐허가 된 탑에 배치한 걸로 되어 있군.\n\n페린과 붉은십자군 광신도 3명, 선교사 3명을 처리한 후 보고하도록 하게.", progress = "이봐. 애송이 <class> 친구. 브릴에서 시간 낭비하지 말고 나가서 싸우란 말이야. 자, 어서 무기를 들고 남서쪽의 폐허가 된 탑으로 가서 대장 페린과 붉은십자군 광신도 3명, 붉은십자군 선교사 3명을 처치하라고. 우리가 나선다면 붉은십자군 녀석들쯤이야 가축 도살하듯 할 걸세.", completion = "대장 페린이 죽었으니 어둠의 여왕 폐하께서 분명히 기뻐하시겠군. 정말 잘해냈네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[371] = {title = "붉은십자군과의 전쟁", objective = "브릴에 있는 집행관 자이건드가 대장 바콘과 붉은십자군 수사 5명을 처치하라고 명령했습니다.", description = "우린 여전히 붉은십자군과 전쟁 중이고 적들은 더 강해지고 있다네. 집행관 아렌에게서 받은 보고에 의하면 붉은십자군이 대장 바콘의 지휘 아래 티리스팔 남동부 발니르 농장 근처에 있는 폐허가 된 탑에서 공격해 오고 있다고 하네.\n\n가서 바콘과 붉은십자군 수사를 5명 처치하면 틀림없이 붉은십자군이 크게 흔들릴 것이야!", progress = nil, completion = "대장 바콘이 죽었으니 티리스팔로 향하는 붉은십자군의 진군도 잠시 늦춰지겠군. 하지만 안심하기에는 아직 이르네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[372] = {title = "붉은십자군과의 전쟁", objective = "브릴 마을에 있는 집행관 자이건드가 대장 멜라케와 붉은십자군 경호원 2명을 처치해 달라고 부탁했습니다.", description = "붉은십자군이 파올의 안식처를 지나 티리스팔 북쪽, 그러니까 여기서 북동쪽에 있는 폐허가 된 탑에서 공격해 오고 있네. 정보에 의하면 대장 멜라케라는 무자비한 사령관이 이 사악한 부대를 지휘하고 있다고 하는군.\n\n이 임무 역시 자네가 좀 맡아줬으면 하네. 어둠의 여왕 폐하의 이름으로 멜라케와 그의 두 경호원을 처치해 주게.", progress = nil, completion = "아주 잘했네. 자네처럼 강한 &lt;class&gt;|1이;가; 포세이큰의 이름으로 싸우고 있는 모습을 보니, 아서스를 영원히 잠재워버릴 때가 한층 가까워지고 있는 것 같군. 자네가 점점 마음에 들기 시작했네, 친구.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n의식의 단도전투용 손도끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[373] = {title = "부치지 않은 편지", objective = "스톰윈드에 있는 도시 건축가 바로스 알렉스턴에게 편지를 전달해야 합니다.", description = "에드윈 밴클리프의 몸을 수색하던 도중 다른 물건들과 함께 부치지 않은 편지 한 통을 발견합니다. 편지의 수신인은 대성당 광장, 시청 내 도시계획 사무소에 있는 스톰윈드의 도시 건축가 바로스 알렉스턴으로 되어 있습니다.\n\n편지는 최근에 작성되어 봉인된 것으로 보입니다.", progress = "어서 오십시오. 도와 드릴 일이 있습니까?", completion = "에드윈 밴클리프라고 했습니까? 이건 마치 돌아가신 할머니로부터 편지를 받는 느낌이군요. 그럼 당신이 그를 처치했단 말입니까? 아, 이런 식으로 물어서 미안합니다. 하지만 너무 놀라운 소식이라 말입니다. 그는 젊은 시절 비길 데 없는 싸움꾼이었습니다. 자, 그럼 수년이 지난 지금 그가 갑자기 무슨 일로 내게 편지를 보냈는지 한번 봅시다.\n\n&lt;편지를 읽는 바로스&gt;\n\n에드윈... 세월이 흘러도 그 낭만적 이상주의자의 성격은 조금도 변하지 않았군요. 그는 자신이 해친 사람들에 대해서는 조금도 신경 쓰지 않고 있습니다. 복수가 그를 파멸로 이끌었지만, 글쎄요, 그를 비난하기는 어려울 것 같군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[374] = {title = "죽음의 증거", objective = "브릴에 있는 죽음의경비병 버제스에게 붉은십자군 반지 10개를 가져가야 합니다.", description = "집행관 자이건드님께서 자네가 붉은십자군들을 소탕 중이라고 하시더군. 티리스팔 숲은 붉은십자군 천지야.\n\n어둠의 여왕님의 부관이신 바리마트라스님께서는 아제로스의 쓰레기인 인간 종족을 모두 쓸어 버리고 싶어하시네. 특히 이곳 티리스팔 숲을 더럽히고 있는 붉은십자군들을 말이야.\n\n어서 나가서 그들을 처단해 주게. 바리마트라스님과 어둠의 여왕님을 향한 충성의 증거로 붉은십자군 반지 10개를 가져 오게.", progress = "아직 붉은십자군 반지를 모으지 못했나?", completion = "바리마트라스님께서 기뻐하시겠군. 자네 솜씨가 꽤 쓸 만하군그래.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n좀비 가죽 팔보호구버클 허리띠그물눈 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[375] = {title = "죽음의 한기", objective = "브릴에 있는 그레첸 데드마에게 그늘박쥐 모피 5개와 굵은 실타래 1개를 가져가야 합니다.", description = "흐... 너무 추워요. 제 혈관 속에는 끔찍한 역병이 마치 얼음 뱀처럼 기어다니고 있답니다. 곧 저도 곧 이성을 잃게 되겠죠. 비록 저주받은 운명이라 해도 제가 어둠의 여왕님을 섬기는 것을 막을 수는 없어요. 저는 부름에 따라 실바나스님의 강력한 언데드 군대를 위해 시체 운반 가방을 수선해 왔어요.\n\n이젠 너무 추워 손이 떨릴 지경이에요. 그늘박쥐를 잡아 그늘박쥐 모피 5개를 구하고 상인에게서 굵은 실타래 몇 개를 사 오면 담요를 기워서 덮을 수 있을 텐데 말이에요. 제가 맡은 임무를 계속 수행할 수 있도록 좀 도와 주세요.", progress = "그늘박쥐 모피 5개와 굵은 실타래를 다 모으셨나요?", completion = "애써 줘서 고마워요. 언젠가 당신의 용기가 실바나스님께 인정받는 날이 오기를...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n숙련사제용 망토바느질 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[376] = {title = "저주받은 존재", objective = "수련사제 엘레스가 승냥이 앞발 6개와 그늘박쥐 날개 6개를 구해다 달라고 부탁했습니다.", description = "제가 맡은 일은 부상당한 전사들을 돌보거나, 갑옷과 의복을 짓거나, 어둠의사제 사비스님이 필요로 하시는 모든 일을 돕는 거랍니다.\n\n보아하니 당신도 그분을 도와... 좀비들을 처치하게 될 것 같군요. 제 생각엔 틀림없이 당신을 보호해줄 방어 장비가 필요할 테니 도와 드리도록 하죠. 그런데 재료가 되는 짐승 앞발과 날개가 다 떨어져서 말이에요. 좀 구해다 주시면 갑옷을 만들어 드릴게요. 남쪽으로 가면 늑대와 박쥐들이 많이 있을 거예요.", progress = "제가 방어 장비를 만들어 드리기 전까지 큰 부상을 입지 않도록 조심하셔야해요.", completion = "재료를 가져다 줘서 고마워요. 이 방어구가 도움이 될 거예요.\n\n이왕이면 지금 입고 계신 것보다는 더 좋은 거였으면 좋을 텐데...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아마포 팔보호구오래된 가죽 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[377] = {title = "죄와 벌", objective = "다크샤이어의 원로 밀스타이프가 덱스트렌 워드를 처치한 후 그의 장갑을 가져다 달라고 부탁했습니다.", description = "귀족 평의회는 이본로크 경의 판결대로 덱스트렌 워드를 처형하지 않고 스톰윈드에 수감하도록 했으니, 그늘숲 주민을 멸시하는 것도 모자라 이제 다크샤이어까지 무시하는 처사가 아니면 무엇이겠소?\n\n덱스트렌 워드는 공동 묘지의 시체를 모벤트 펠에게 팔아 넘긴 죄로 잡혔으니 죽어 마땅한 중죄인이 아니오? 하지만 스톰윈드에서는 아직 놈이 자기네 죄수라고 억지를 부리고 있소.\n\n스톰윈드 지하감옥에 있는 덱스트렌 워드를 암살한 다음 놈의 장갑을 내게 가져 오시오. 그러면 내 당신에게 보상하리다.", progress = "덱스트렌 워드 같은 시체 위해범을 살려 두는 한, 정의는 죽은 거나 마찬 가지오. 놈에게 이본로크 경의 사형 판결을 집행한 후 내게 돌아오시오. 그것으로 묘지에 묻혔던 이들의 가족이 겪고 있는 슬픔을 달랠 뿐만 아니라, 스톰윈드의 귀족 평의회에도 우리의 의사를 확실히 전하게 될 것이오.", completion = "마침내 덱스트렌 워드가 자신의 죗값을 치렀단 말이오? 쓰레기 같은 놈을 처리해 버려서 아주 속 시원하군. 고맙소, 다크샤이어의 친구여! 묘지에 묻힌 이들의 가족에게 위안이 되었을 뿐 아니라 귀족 평의회의 저 썩어 빠진 관리들에게도 뼈저린 경고가 되었을 게요. 스톰윈드가 계속 그늘숲 주민들의 요구에 귀를 기울이지 않는다면 우리는 그들의 폭정에서 벗어날 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n대사의 장화다크샤이어 쇠사슬 다리보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[378] = {title = "격노", objective = "딥퓨리를 처치하고 그 증거로 그의 머리카락을 던 모드르에 있는 모틀리 가마슨에게 가져가야 합니다.", description = "마그니 폐하에 대한 당신의 충성심은 이미 잘 알고 있소. 그리고 당신도 나만큼이나 저 검은무쇠단 드워프 쓰레기들을 증오하는 것 같더군.\n\n내가 직접 완수하고 싶은 임무가 있지만, 롱브레이드님 곁을 지켜야 하는 처지라 당신이 대신 좀 맡아 주었으면 하오. 로고가 수집한 정보에 의하면 캄 딥퓨리가 탄돌 교각 공격을 획책한 주범임이 밝혀졌소. 놈의 음모로 롱브레이드님께서는 가족을 잃었지.\n\n딥퓨리는 정치적인 이유로 스톰윈드 지하감옥에 수감돼 있소. 롱브레이드님을 위해 그를 처치해 주시오!", progress = "바보 같은 인간들의 관료주의를 드워프 문제에까지 끼어들게 할 수는 없소이다. 캄 딥퓨리가 탄돌 교각 공격을 계획한 것이 만천하에 밝혀졌고, 딥퓨리의 책략으로 마그니 폐하의 선량한 백성들이 목숨을 잃었소. 인간들은 딥퓨리가 지하감옥에서 썩는 걸로 만족할지 모르지만, 나는 딥퓨리를 처치하기 전까진 두 발 뻗고 편히 잘 수 없을 것 같소.", completion = "결국 캄 딥퓨리도 죽음이 어떤 것인지 직접 맛보았단 말이오? 속이 다 시원하군. 비겁한 검은무쇠단 놈들에게 따끔한 맛을 보여 준 거요. 하지만 전쟁과 동요의 소용돌이 속에서 허망하게 간 탄돌 교각 공격의 희생자들은 어찌할 수 없으니... 그나마 딥퓨리가 죄 값을 치렀다는 걸 알게 되면 희생자 가족들에게 위안이 될 것이오. 롱브레이드님 동생의 죽음에 대한 복수도 한 셈이고 말이오. 정말 잘해 주었소, &lt;class&gt;.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n지지의 허리띠산산조각 철퇴\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[379] = {title = "갈증 해소", objective = "가젯잔에 있는 선임기술자 빌지위즐에게 사막유랑단 물주머니 5개를 가져가야 합니다.", description = "동력원이 필요하다면야 내가 도와줄 수 있지. 내게 필요한 게 뭔지 아나? 바로 마실 거야! 내게 사막유랑단 물주머니 5개를 가져오면 당신에게 4711-FTZ를 주지.\n\n어디... 그 사막유랑단 물주머니들을 어디서 찾을 수 있을 것 같나? 동쪽에 있는 사막유랑단 유목민 한 명에게 가서 하나 달라고 해 보시지. 그리고 그 결과를 내게 알려달라고.", progress = "그래, 그 유목민 녀석들이 \"자발적으로\" 물주머니를 내놓던가?", completion = "대단하군. 자, 동력원은 이제 당신 거요. 이 동력원은 그런 과학 실험 도구에 사용하도록 설계된 것이 아니라서 제한된 시간이 지나면 수집한 자료가 다 날아가 버리게 될 거라고!\n\n당신이 하려는 일에 필요한 것들을 다 모으면 동력원을 내게 가져오쇼. 내가 안전하게 꺼줄 테니까 말이야. 최대 2시간 안에 볼일을 모두 마쳐야 한다고.\n\n시간 내에 다 해내지 못하면 내 언제든 당신에게 동력원을 더 팔도록 하지. 암, 팔고 말고!", rewards = "다음과 같은 것들을 받습니다:\n\n모델 4711-FTZ 동력원"},
[380] = {title = "검은그물 거미굴", objective = "집행관 아렌이 새끼 검은그물거미 10마리와 검은그물거미 8마리를 처치해 달라고 부탁했습니다.", description = "우리의 가장 큰 난관 중 하나는 생존에 필요한 천연 자원을 얻는 것일세. 얼라이언스의 세력이 막강했던 시절조차 금이 부족했었는데 지금 같은 시기에야 오죽하겠나.\n\n북서쪽에 거미들이 득실대는 금광이 있네. 광산에 거미들이 기어다니고 있는 통이라 금을 채굴할 수가 없다네. 게다가 임무를 맡길 만한 인원도 부족한 상황이라 채굴량이 적은 상황이야.\n\n자네가 가서 도와줄 만한 일이 있는지 봐주게.", progress = nil, completion = "흠, 이건 시작에 불과해. 놈들을 모두 없애버리려면 몇 주 아니 몇 달이 걸릴지도 모르네. 놈들을 모두 처치한 후에는 횃불을 가지고 가서 거미집을 모두 불태워 버려야 깨끗이 끝나게 될 거야.\n\n아무튼 임무를 잘 수행해 주었네. 앞으로 자네에게 또 다른 임무를 맡기게 될 것 같군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아마포 조끼튼튼한 쇠사슬 조끼좀비 가죽 다리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[381] = {title = "붉은십자군", objective = "집행관 아렌에게 붉은십자군 순례자와 붉은십자군 견습마법사에게서 붉은십자군 완장 12개를 가져가야 합니다.", description = "자네가 도와준 덕분에 광산 쪽 일은 잘 진행되고 있는 것 같군. 수고해 줘서 정말 고맙네. 이젠 좀 다른 문제에 신경을 써야 하네.\n\n정찰병 보고에 따르면 붉은십자군 파견대가 데스넬의 남동쪽에 야영지를 설치하고 있다고 하네. 붉은십자군은 우릴 위협하고 있는 인간들의 조직인데, 이들은 스컬지든 포세이큰이든 모든 언데드를 파멸시킬 때까지 멈추지 않을 거야. 우리가 당하기 전에 먼저 공격해야 하네!\n\n조심하게, 사악한 신앙 때문인진 몰라도 저들은 아주 위험해.", progress = "바보 같은 것들... 저들은 스스로 무덤을 파고 있어.", completion = "조금만 더 이성적으로 생각해도 대화로 문제를 해결할 수도 있을 텐데 말이야... 안 그런가?\n\n눈먼 바보들 같으니라고!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n포세이큰 단검포세이큰 마울포세이큰 쇼트소드포세이큰 바스타드소드\n\n다음과 같은 것들 또한 받습니다:\n\n맑은 샘물"},
[382] = {title = "붉은십자군 전령", objective = "붉은십자군 야영지에 있는 전령 메븐 코갈을 처치한 다음 입수한 정보를 집행관 아렌에게 가져가야 합니다.", description = "브릴에 계신 내 상관께서 보내신 소식에 따르면 붉은십자군 중 한 명이 붉은십자군 수도원에서 이곳 데스넬로 파견됐다고 하네. 정보에 따르면 그 전령이 중요한 정보를 가지고 있다고 하는데 우리가 아는 건 여기까지야.\n\n이 일은 자네가 적임자야. 그 전령을 찾아내 지니고 있는 정보를 내게 가져오도록 하게.", progress = "내가 맡긴 임무는 어떻게 됐나?", completion = "흠... 어떤 정보를 가져왔는지 한번 볼까...\n\n&lt;가져온 문서를 샅샅이 살펴보며&gt;\n\n우리 적들의 공적이 몇 가지 적혀 있고... 이런 건 쓸모 없지... 정찰 보고, 새 명령 ... \"파괴된 도시 근처에 지속적으로 야영지를 설치하라...\" 흠, 새로운 정보는 없는 것 같은데... 아, 이건 뭐지? 저들의 야전 사령관과 병력의 배치를 표시한 지도로군! 이건 쓸 만하겠어.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n집행관의 지팡이죽음의경비병 버클러\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[383] = {title = "중요한 정보", objective = "브릴에 있는 집행관 자이건드에게 붉은십자군 문서를 전달해야 합니다.", description = "이 정보를 브릴에 있는 내 상관이신 자이건드 집행관님께 보내야 하네. 이 정도 정보라면 붉은십자군에 결정적인 타격을 줄 수 있을 거야. 이곳 데스넬에서도 자네의 도움이 필요하긴 하지만 말이야... 자이건드님께 이 정보를 전달할 자도 필요하고, 그분이 자네한테 더 적합한 임무를 맡겨 주실 거라 믿네.\n\n데스넬을 나가 북쪽으로 길을 따라가게. 티리스팔로 접어들면 곧 교차로가 나오는데 거기서 동쪽으로 돌아 계속 동쪽 길을 따라가도록 해. 길을 따라가다 보면 버려진 장원을 지나가게 될 거야.", progress = "그래, 무슨 일인가?", completion = "오, 정말 훌륭하군. 매우 유용한 정보를 가져왔군. 흠... 티리스팔 숲에 배치된 장교 녀석들의 이름이 기록돼 있군.\n\n이들의 지휘관들을 급습해 처치하면 이 괘씸한 광신도들의 사기를 크게 떨어뜨릴 수 있을 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[384] = {title = "맥주로 양념한 멧돼지 갈비", objective = "카라노스에 있는 라그나르 썬더브루가 멧돼지 갈비 6개와 랩소디 몰트 한 병을 구해다 달라고 부탁했습니다.", description = "우리 가게 손님들이 가장 많이 찾는 건 맥주로 양념한 멧돼지 갈비지! 그런데 내게 멧돼지 고기를 대 주던 사냥꾼 친구가 왕국 군대에 차출되어 얼라이언스 전방 부대로 파견되었다오. 그래서 갈비 재료를 구하기가 어려워졌소이다.\n\n당신이 좀 도와 주겠소? 멧돼지 갈비 6개만 구해 주시오. 그리고 선술집에서 랩소디 몰트도 한 병 사다 주고 말이오. 그러면 우리 가문에서 대대로 내려오는 맥주로 양념한 멧돼지 갈비 조리법을 알려 주도록 하지. 시식용으로 갈비 요리도 해 주고말고! 잊지 마시오, 맛의 비밀은 몰트에 있다오!", progress = "멧돼지 갈비 6개와 랩소디 몰트 한 병이 필요하오.", completion = "잘 익은 몰트와 멧돼지 고기가 준비됐다네~\n요리가 끝나기도 전에 말할 틈도 없이~\n앞 다퉈 서로들 뜯기 바쁘다네~\n맛 좋은 맥주로 양념한 멧돼지 갈비라네~", rewards = "다음과 같은 것들을 받습니다:\n\n맥주로 양념한 멧돼지 갈비조리법: 맥주로 양념한 멧돼지 갈비"},
[385] = {title = "악어 사냥", objective = "순찰자의 오두막에 있는 마렉 아이언하트에게 악어 고기 5개와 악어 가죽 6개를 가져다주어야 합니다.", description = "많은 사냥꾼들이 악어를 사냥하기 위해 이곳 모단 호수로 모여든다네. 악어의 가죽은 옷이나 갑옷 등에 쓰이고 그 고기도 아주 잘 팔리거든.\n\n우리도 악어를 거래하긴 하지만 많은 양은 아니라네. 악어가 워낙 사나운데다가 요즘에는 호수 안의 섬 곳곳에 틀어박혀 지내서 말이야. 그렇다고 포기는 말게. 이 짐승과 싸워 보는 건 좋은 경험이 된다네.\n\n어때, 한번 해 보겠나?", progress = "악어한테 내 손을 잃을 뻔한 적이 있다고 얘기했던가? 아주 끈질긴 놈이었지. 이빨은 마치 칼처럼 날카롭고... 하지만 운이 좋았다네. 내 칼로 그 짐승의 주둥이를 못쓰게 만들어 버렸거든. 그때 쓰던 칼을 여기 어딘가에 뒀었는데...", completion = "자네가 가져온 것들은 질이 아주 좋군. 틀림없이 높은 가격을 받을 수 있을 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n조리법: 악어 스테이크주름진 단망토"},
[386] = {title = "사필귀정", objective = "흉악범 타고르를 처치한 후 그 증거로 그의 머리카락을 레이크샤이어에 있는 경비병 베르턴에게 가져가야 합니다.", description = "흉악범 타고르는 가스일조그 밑에서 일하는 최고의 사형집행인이었습니다. 추악한 오크라는 것은 둘째치고 아주 잔인하기 짝이 없는 자였지요. 그의 변덕에 따라 왕국을 지키기 위해 용감하게 싸운 용사들이 고통을 받아야 했답니다. 지금은 스톰윈드 지하감옥에 갇혀 있으며, 사형 선고를 받은 상태입니다. 하지만 뭔가 일이 잘못 돌아가고 있습니다. 귀족 하나가 그자의 처형을 연기했답니다. 분명히 뭔가 사악한 뒷거래가 있는 게 분명합니다.\n\n이 참에 흉악범 타고르의 숨통을 끊어 주시기 바랍니다. 지하감옥으로 가서 농간이 펼쳐지기 전에 그를 없애 버려야 합니다.", progress = "아직 스톰윈드 지하감옥에 가지 않았습니까? 어떤 귀족의 농간으로 흉악범 타고르가 아직까지 살아 있는지는 잘 모르겠지만, 이렇게 가다가는 결국 풀려날지도 모릅니다. 이미 사형 선고를 받은 자니까 그냥 없애 버리십시오.", completion = "흉악범 타고르의 운도 결국 다했군요. 그 짐승 같은 자에게 죽음이 어떤 건지 알려 주었다니 정말 기쁩니다. 잘하셨습니다. 때로는 법정 밖에서, 그리고 혼탁한 정치의 힘이 미치지 않는 곳에서 진정한 정의가 이루어진답니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n약탈의 롱소드단단한 뿌리 지팡이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[387] = {title = "폭동 진압", objective = "스톰윈드에 있는 교도소장 델워터가 지하감옥에서 데피아즈단 복역수 10명, 데피아즈단 무기징역수 8명, 데피아즈단 반역자 8명을 처치해 달라고 부탁했습니다.", description = "폭동이 일어났네! 이를 진압해야 하니 제발 날 좀 도와 주게. 지하감옥이 죄수들 손에 넘어갔다는 소문이 바깥으로 퍼지기라도 하면 난 분명히 해고되고 말걸세! 생각만 해도 끔찍한 일이야. 하지만 지금 중요한 건 우선 죄수들의 항복을 받아내 스톰윈드를 안전하게 보호하는 것이네.\n\n폭동에 대한 대가는 죽음뿐! 이 일탈자들의 일부를 처단해 주게! 그러면 이곳을 다시 통제할 수가 있을걸세.", progress = nil, completion = "스톰윈드 지하감옥을 위해 정말로 큰일을 해 주었네. 우리끼리 해결하기에는 벅찬 일이었지만 자네가 멋지게 해치웠군. 정말 고맙네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[388] = {title = "피의 색", objective = "스톰윈드에 있는 니코바 라스콜이 붉은 양모 복면을 10개를 모아 달라고 부탁했습니다.", description = "도저히 이 비통한 마음을 억누를 길이 없어요. 내 손자 맥은 정말 좋은 아이었는데... 나이도 열네 살밖에 되지 않았어요. 군대가 전방으로 출병한 후로 맥은 도시를 지키기 위해 무기를 들었죠. 그리고 데피아즈단이 갇혀 있는 지하감옥에서 경비병으로 복무하게 되었지요. 거기서 몇몇 죄수가 양모 담요를 찢어 패거리의 상징인 복면을 만드는 것을 질책했다는 이유만으로 결국 등에 칼을 맞고 말았어요.\n\n난 복수를 원합니다. 그들이 그토록 소중히 여기는 양모 복면을 10개 가져다주세요. 그 복면은 피처럼 붉은 색이랍니다.", progress = "돌아왔군요. 지하감옥에 있는 데피아즈단 놈들에게서 붉은 양모 복면 10개를 구해왔나요?", completion = "그래, 이 복면... 타락의 추악한 징표인 이 복면 때문에 내 손자가 죽어야 했단 말인가요? 이렇게 무의미한... 이토록 비참한 죽음이 어디 있나요? \n\n하지만 어쩌겠어요, 시간을 거슬러 올라갈 수는 없는 법이니. 그래도 당신 덕분에 내 가족의 원수를 갚았다는 사실만은 분명하네요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[389] = {title = "바질 스레드", objective = "감옥에 있는 교도소장 델워터와 대화해야 합니다.", description = "밴클리프와 난 석공 길드의 회원이었습니다. 우리의 주요 계획은 전쟁 후의 스톰윈드를 재건하는 것이었지요.\n\n그런데 맡은 일을 완수한 후 사기를 당하고 말았습니다. 귀족들이 작업에 대한 정당한 대가를 지급하지 않으려고 한 것이지요. 이후 국가에서 석공 길드의 몇몇 수석 건축가에게 일을 맡기려 했으나 밴클리프는 석공 길드에 대한 신의를 지키기 위해 이를 거절했습니다. 그 후 그는 한바탕 소동을 일으킨 후에 복수를 맹세하며 도시를 떠났지요.\n\n밴클리프의 부관인 바질 스레드가 그의 자세한 계획을 알고 있을 겁니다. 바질 스레드는 현재 지하감옥에 죄수로 감금되어 있습니다.", progress = nil, completion = "도대체 원하는 게 뭔가? 자네 눈엔 지금 저 난리가 안 보이는 건가?\n\n바질 스레드라고? 그런 녀석하고 무슨 얘길 하려는 거지? 그리고 자네가 그와 한 패거리가 아니라는 걸 어떻게 증명하려고 그러는 건가? 지금 빈 감방이 하나라도 있었다면 일단 자네부터 가뒀을 것이야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[391] = {title = "감옥 폭동", objective = "바질 스레드를 처치하고 그 증거로 그의 머리카락을 감옥에 있는 교도소장 델워터에게 가져가야 합니다.", description = "한 가지는 분명히 하지. 난 자넬 믿지 않아. 하지만 상황이 이렇다 보니 말이야, 자네 하나 때문에 일이 더 악화될 리는 없겠지만...\n\n자, 그러면 이렇게 하세. 저리 내려가서 스레드와 얘기를 하게. 그리고 정말 자네가 진정 우리편이라면 그를 처치하고 머리카락을 내게 가져오게.\n\n만에 하나 자네가 스레드와 한패라면 돌아오지 않겠지만... 대신 나중에 만나게 되면 나머지 친구들과 자네는 저 세상 구경을 하게 될 테니 명심하게.", progress = "스레드가 죽거나 자네가 죽거나 둘 중 하나일세. 이해하겠나?", completion = "저들의 수장인 스레드가 더는 지휘를 하지 못하니 폭동을 진압하는 게 한결 수월해지리란 희망을 가져볼 수 있겠군... 두고 보면 알게 되겠지.\n\n자네가 내려간 후 30분 동안은 다시 돌아오리라고 생각도 못했네. 내가 잘못 본 모양이야.\n\n어쨌든 이 꼴을 보아 하니 스레드에게서 유용한 정보를 얻어내지는 못했을 것 같군그래? 대신 스레드의 활동에 대해 자네가 관심 있어 할만한 정보 한두 가지를 내가 알고 있다네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[392] = {title = "수상한 면회인", objective = "스톰윈드에 있는 바로스 알렉스턴에게 스레드의 방문객에 대한 봉인된 인상서를 전해줘야 합니다.", description = "스레드가 지하감옥에 들어온 후 처음 몇 년간은 아무도 면회를 오지 않았네. 그래서 난 데피아즈단에서 스레드가 더 이상 쓸모없게 되었다고 생각했지.\n\n그런데 몇 달 전부터 상황이 완전히 바뀌었네. 1주일에 한두 번 정도 정기적으로 면회인이 찾아오기 시작한 것이지. 면회인은 이상한 느낌을 주는 조용한 성격의 남자였네. 심증은 있었지만 서류는 이상이 없었네.\n\n그자의 면회증에는 매릭이라는 이름이 적혀 있었고 인상착의는 여기 적힌 것과 같네. 아무튼 그자가 더 이상 스레드에게 면회올 올 일은 없겠군.", progress = "찾는 게 있으신가요?", completion = "흠, 매릭이요? 아니요, 들어보지 못한 이름인데다가 인상착의 또한 본 적이 없습니다. 석공 길드이었던 사람일 수도 있고, 데피아즈단의 일원일 수도 있고... 델워터씨가 말했듯이 뭔가 일정한 연고가 있는 자라면 분명 누군가 그를 알아볼 수 있는 다른 사람이 더 있을 겁니다. 어디 한 번 생각해 봅시다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[393] = {title = "과거의 그림자", objective = "스톰윈드에 있는 단장 마티아스 쇼에게 스레드의 방문객에 대한 봉인된 인상서를 전해줘야 합니다.", description = "나는 이제 더 이상 알려드릴 단서가 없습니다. 그러나 도움이 될 만한 사람을 한 명 알고 있습니다. 더구나 그 사람은 내게 빚을 진 일이 하나 있어서... 흠, 지금은 그런 얘기를 할 때가 아니군요. 어쨌든 구 시가지에 있는 병영에서 SI:7의 단장 마티아스 쇼를 찾아가 보십시오. 쇼는 도시에서 일어나는 대부분의 비밀스럽고 음흉한 일에 관련되어 있답니다.\n\n쇼가 모르면 아무도 모르는 겁니다.", progress = "반갑네. 내가 도와줄 일이 있나, <class> 친구?", completion = "뭐라고? 이게 뭐지? 아 그래, 이 친구가 누구인지 알 거 같은데 매릭은 그의 본명이 아니네. 암살자들은 수많은 이름과 가면을 쓰고 다니지. 그러다 더 이상 그것들이 쓸모없게 되면 가차없이 버려 버리고 말일세.\n\n그 친구가 사용하는 또 다른 별명은 마르존이라고 알려져 있지만, 이것도 본명인지는 확실치 않네.\n\n그렇지만 그가 암살자인 이상 그에 대해서는 내가 훤히 알고 있지.\n\n마르존은 현재 그레골 라스코발 경의 밑에서 일하고 있네. 그레골 라스코발 경은 스톰윈드의 타락한 귀족들 중에서도 악명이 높은 귀족일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[394] = {title = "잔인한 자의 최후", objective = "스톰윈드에 있는 마티아스 쇼와 대화해야 합니다.", description = "구 시가지로 가서 쇼 단장을 찾으시기 바랍니다. 가서 당신이 라스코발의 위협을 제거한 사실과 그가 꾸몄던 음모를 알아냈다는 소식을 전하도록 하십시오. 마티아스는 스톰윈드 시민 중에 영웅이 또 있다는 사실을 알면 자랑스러워할 겁니다.\n\n그 친군 틀림없이 당신을 왕자님이나 다른 귀족과 만나게 해줄 것입니다. 단 술은 너무 많이 마시지 마세요. 귀족들은 이 도시를 자기들 마음대로 통치할 수 있다고 생각하지만 귀족들이 어찌하지 못하는 일들도 있는 것이지요.", progress = nil, completion = "그러면 그가 제거된 것인가? 아주 신속하게 처리했군. 내가 자네의 목표가 되지 않게 해달라고 신에게 기도하는 이유도 그래서라네, 하하!\n\n&lt;웃으며 당신의 어깨를 두드리는 마티아스 쇼&gt;\n\n비난하는 말은 아니라네. 나도 암살이라면 빠지지 않는데 어떻게 그럴 수 있겠나? 진정 스톰윈드의 주민을 위해 큰일을 해주었군. 내 그 점, 고맙게 생각하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[395] = {title = "데피아즈단의 종말", objective = "스톰윈드에 있는 바로스 알렉스턴과 대화하십시오.", description = "아, 자네가 떠나 있는 동안 알렉스턴이 왔다 갔다는 걸 깜빡했군. 자네와 얘기를 하고 싶다고 하더군. 분명히 데피아즈단의 사태에 대해서 귀족들께 보고하려고 하는 것일게야.\n\n한 가지 조언을 하도록 하지. 누군가 내게 묻거든 모든 것을 자세히 설명해 주도록 하겠네. 물론 자네가 라스코발 경을 처치했다는 것만 빼고 말이야. 날 믿게나. 이런 일에는 이골이 난 사람이라네.\n\n그리고 자네... 트리아스에 대한 얘기는... 아무에게도 하지 말게나.", progress = nil, completion = "다시 만나서 반갑습니다. 얼마 전에 그레골 라스코발 경이 시체로 발견되었다는 소식을 들었습니다만...\n\n아무래도 임무를 성공적으로 완수한 것 같군요. 당신은 나를 포함해서 수많은 사람들을 밴클리프의 복수로부터 구한 겁니다. 고맙습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[396] = {title = "국왕 알현", objective = "스톰윈드 왕궁으로 가서 국왕 바리안 린에게 올릴 알렉스턴의 데피아즈단에 대한 보고서를 전달해야 합니다.", description = "국왕께 보낼 보고서를 준비했습니다. 지금까지 당신이 발견한 것들을 고려해 볼 때 당신이 이 보고서를 전할 적임자라고 생각합니다. 걱정하지 마십시오, 국왕께서도 분명히 스톰윈드의 백성으로서 의무를 다한 당신을 칭찬하실 테니까 말입니다.\n\n알현 일정이 곧 잡혀 있으니 서두르는 게 좋겠습니다. 스톰윈드 왕궁까지는 약간 머니 말입니다.", progress = "오, 그대로군요? 바로스 알렉스턴에게서 그대가 올 것이라는 얘기를 들었습니다. 나는 그대의 말에 매우 관심이 많습니다. 그대의 얘기를 경청하도록 하겠으니 어서 얘기하도록 하세요.", completion = "이제껏 그대가 스톰윈드를 위해 한 일은 칭찬을 받아 마땅합니다. 밴클리프의 음모가 성공했다면 분명히 왕국이 큰 타격을 입었을 것입니다. 결코 일어나서는 안 될 일이지요.\n\n&lt;class&gt;여, 그대의 공적을 높이 사 하사하는 것이니 어서 받도록 하십시오. 국왕께서 외교 활동 중이시기 때문에 얼마간 돌아오지 못하실 것이기에 직접 하사하지 못한 것을 유감스럽게 생각합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n린의 인장"},
[397] = {title = "수고의 대가", objective = "검은발톱 자데스의 하인인 즈기와 대화하여 보상을 받으십시오.", description = "위쇼크 경이 술을 맛있게 먹었다고 하는군, 흐흐.\n\n그동안 수고 많았소. 당신 덕분에 스톰윈드의 흑마법사들이 방해받지 않고 계속 하던 일을 할 수 있게 되었소. 수고한 대가로 특별한 선물을 준비해 두었지. 내 하인, 즈기에게 얘기해서 선물을 받아 가도록 하시오.", progress = nil, completion = "주인님께서 손님께 선물을 드리라고 하셨어요. 자, 여기 있어요. 즈기는 이 멋진 선물을 계속 가지고 있고 싶지만 주인님의 말씀을 거역할 수는 없답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n공포의 마법사 모자"},
[398] = {title = "구더기눈 현상수배", objective = "구더기눈을 처치한 후 브릴에 있는 집행관 자이건드에게 돌아가 구더기눈의 앞발을 증거로 제출하고 보상을 받으십시오.", description = "구더기눈 현상수배!\n\n저 사악한 짐승인 놀 종족의 구더기눈은 우리에게 저지른 범죄의 대가로 처단 받아 마땅하다. 이 비열한 악당은 리치 왕의 군대에 사용할 시체들을 훔치고 있다. 그가 마지막으로 목격된 곳은 브릴 북쪽의 가렌의 흉가 근처이다.\n\n브릴 마을에서는 구더기눈을 처치하는 자에게 현상금을 지급할 것이다. 이 악당을 처치한 자는 그의 앞발을 집행관 자이건드에게 제출하면 된다.\n\n자비는 약자를 위한 것일 뿐임을 명심하라.", progress = "무슨 일인가?", completion = "드디어 구더기눈이 비열한 범죄의 대가를 치렀군. 자네의 용감한 행동 덕분에 앞으로 범죄자들도 마음대로 날뛰지 못할 것이야. 브릴 마을을 대표해 감사를 표하는 바이네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n놋쇠 미늘 바지농사꾼 조끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[399] = {title = "초라한 시작", objective = "서부 몰락지대에 있는 바로스 알렉스턴의 집으로 가서 나침반을 찾은 다음 스톰윈드의 대성당 광장에 있는 바로스 알렉스턴에게 가져가야 합니다.", description = "서부 몰락지대의 농장에서 일하던 어린 시절이 까마득한 옛날일 같군요. 흔히들 과거로 돌아갈 수 없다고 하지 않습니까? 정말 맞는 말이더군요. 특히 내 경우에는 더욱 그렇답니다. 우리 가족의 고향은 다 타버리고 도적들의 소굴이 되어 버렸답니다.\n\n전에 아버지와 그 당시 두고온 물건들에 대해 이야기한 적이 있었는데, 아버지가 사주신 첫 번째 선물인 나침반도 그 중 하나였지요. 아버지는 그것들을 가지고 올 수 없어서 안타깝다고 말씀하시면서 농장 어딘가에 숨겨져 있을 거라고도 하셨습니다.\n\n감시의 언덕 서쪽으로 가면 알렉스턴 농장이 있는데, 혹시 그곳으로 가서 내 나침반을 찾아서 가져다줄 수 있겠습니까?", progress = "나침반은 찾았나요?", completion = "오, 고맙습니다! 실제로 사용할 순 없지만 정겨운 추억이 담긴 아주 소중한 물건이랍니다. 위험을 각오하고 일부러 시간을 내 서부 몰락지대까지 가서 이 물건을 찾아 주셔서 정말 감사합니다. 그리고 감사하는 마음을 담아 이걸 드리고 싶군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[400] = {title = "스틸그릴이 주문한 공구", objective = "벨딘 스틸그릴에게 스틸그릴의 공구를 배달해야 합니다.", description = "벨딘 스틸그릴이라는 친구가 있는데 드워프 최고의 증기 전차 기술자라고 할 수 있지. 그 친구는 정비소를 하나 운영하고 있는데 공구를 워낙 험하게 다루어서 내 속을 좀 썩인다네. 만능 스패너를 보내주는 족족 망가뜨려서 말이야.\n\n그 친구가 최근 주문한 공구를 이제 겨우 다 만들었네. 이 물건을 그에게 배달해 주면 분명히 사례를 할 거야.\n\n스틸그릴의 정비소는 카라노스의 북동쪽에 있네. 노련한 증기 전차 조종사들이 자주 출입하는 곳이니까 그곳에 가면 다른 일을 구할 수도 있을 거야.", progress = "엥? 증기 전차 조종사치고는 좀 어려 보이는데. 하기야 나이야 별 상관없지... 근데 뭔가 수리할 게 있나?\n\n거기 번호표를 뽑고 편히 기다리라고. 지금은 손보아야 할 증기 전차가 여러 대 있어서 한 며칠간은 다른 일을 맡을 시간이 없거든.\n\n아니면 뭐 다른 일 때문에 온건가?", completion = "공구를 가지고 왔다고? 마침 잘 됐군! 한 시간 전쯤에 뾰족 톱니가 망가졌는데, 스톤기어의 증기 전차를 수리하려면 공구 안에 든 뾰족 톱니가 필요했거든. 가져오느라 수고했네.\n\n자, 이건 수고비로 받아두게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[401] = {title = "시라의 번역 기다리기", objective = "잠시 기다렸다가 시라 본인디와 다시 대화해야 합니다.", description = "편지를 거의 다 번역했습니다. 잠시 후에 다시 찾아오면 끝나 있을 겁니다.", progress = nil, completion = "자, 다 됐습니다.\n\n&lt;땅 위로 두껍고 검은 커튼이 드리워진 듯 무거워지는 주변 공기...&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[403] = {title = "썬더브루 맥주통", objective = "이 에일 맥주통은 야벤 썬더브루가 지키고 있습니다. 야벤이 지하실에 있는 동안에는 맥주통에 손을 댈 수도 없습니다.", description = nil, progress = nil, completion = nil, rewards = nil},
[404] = {title = "더러운 임무", objective = "브릴에 있는 죽음의경비병 딜링거에게 썩은 발톱 7개를 가져가야 합니다.", description = "스컬지가 티리스팔 숲에 침투하여 브릴 서쪽 지역에 있는 오래된 다리 근처를 완전히 오염시켰네.\n\n그곳으로 가서 썩어 문드러진 망자와 심하게 훼손된 시체들을 눈에 띄는 대로 처치한 다음 내게 썩은 발톱을 가져오게. 그리하면 죽음의경비대에서 보상이 있을 것이네.", progress = "임무를 완수했나? 썩은 발톱은 가져왔나?", completion = "잘했네. 그 언데드들이 자네에게 박살나는 광경을 구경했어야 하는데 유감이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[405] = {title = "회개한 마술사", objective = "언더시티에 있는 베소르 아이스샤드에게 세브렌의 명령서를 보여 줘야 합니다.", description = "남쪽 언더시티에 계신 강력한 고위 마법사 베소르 아이스샤드님께서 스컬지를 상대할 수 있는 실력 있는 요원을 보내 달라고 명하셨네. 그래서 자네를 보내려고 하는데 말이야.\n\n이 명령서를 베소르님께 드리면 임무를 내리실 걸세. 정확한 내용은 나도 모르지만 대충 듣기로는 마음이 흔들리고 있는 마술사를 포섭하는 것과 관련된 일이라고 하니 위험한 일이 될 거야.\n\n단단히 준비하도록 하고 절대로 실패해서는 안 된다는 것을 명심하게. 베소르님을 찾으려면 언더시티의 마법 지구로 가보도록 하게.", progress = "어서 오게. 자넨 내가 누구인지 모르거나 나에게 급한 용무가 있는 모양이군.\n\n둘 다 아니라면 앞으로는 나를 방해하는 어리석은 짓을 두 번 다시 하지 말도록...", completion = "아, 집정관 세브렌께서 보낸 요원이로군. 그렇다면 나에게 급한 용무가 있었던 게 맞군그래.\n\n세브렌께서 이 임무에 적임자를 보냈으리라 믿지만...결과는 두고 보면 알겠지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[407] = {title = "오염된 농장", objective = "사로잡힌 붉은십자군 광신도에게 줄무늬 호박을 가져다주십시오. 갤로우 선술집 지하실에 갇혀 있습니다.", description = "당신이 가져온 호박들은 겉으론 그냥 호박이지. 하지만 북쪽에서 전진해 오는 아서스의 진군을 막아내고, 남쪽에서 점점 늘어나고 있는 인간의 수를 줄이려면 우리 언데드의 잠재된 능력을 모두 발휘해야 하오.\n\n약간의 재주만 발휘하면 평범한 호박을 어둠의 여왕님의 위대한 계획에 큰 도움이 되는 재료로 만들 수 있소. 방금 이 호박에 내 최신 처방을 했으니 이제 꽤 쓸만한 물건이 될 것이오.\n\n아직 붉은십자군 광신도 중 한 명이 포로로 잡혀서 갤로우 선술집 지하실에 갇혀 있을 거요. 이 호박을 그 얼간이에게 가져다주시오.", progress = "이 사악하고 불결한 괴물, 저리 물러서라! 신이시여, 저를 지켜주소서! 붉은십자군이 아제로스에서 네놈들을 완전히 몰아낼 날이...\n\n... 잠깐, 혹시 내게 줄 음식인가? 배가 너무 고파...", completion = "세상에! 드디어 음식을 보게 되는군! 아, 정말 맛있는 호박이야...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[408] = {title = "아가만드가 납골당", objective = "울부짖는 아가만드 망령 8마리와 썩어가는 아가만드 시체 8마리를 처치해야 합니다.\n\n대장 다르골을 처치하고 그의 해골을 브릴에 있는 집정관 세브렌에게 가져가야 합니다.", description = "자네도 알다시피 아가만드 밀농장 지역이 스컬지의 본거지가 되었네. 이들의 주요 거점은 그 지역 지휘관인 대장 다르골의 본부가 있는 아가만드가 납골당이야. 그는 강령술을 통해 아가만드 가문의 조상을 언데드로 만들어 우리를 공격하려고 계획하고 있네. 절대로 그런 일이 있어서는 안 돼. 자네가 다르골의 계획을 막아 주기 바라네.\n\n아가만드가 납골당으로 가서 언데드로 되살아난 아가만드 조상을 해치우고 다르골의 해골을 내게 가져오게.", progress = "시간이 그리 많지 않네. 시간이 흐를수록 티리스팔 숲에서 스컬지의 지배력이 점점 더 강해지고 있어.", completion = "자네의 활약으로 스컬지가 상당한 피해를 입었네. 이번 공적은 우리 포세이큰에게나 적들에게나 분명히 기억될 것이야.\n\n항상 그렇듯 계속 전력을 다해 분투해 주게. 언젠가 아제로스에서 리치 왕을 쫓아내는 날이 오고야 말 것이야!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n흑단 지팡이뼈곤봉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[409] = {title = "동맹의 증거", objective = "부름의 양초를 얻어야 합니다.\n\n릴리스 네파라를 소환하여 처치해야 합니다.\n\n그 후에 섬에 있는 군터에게 돌아가도록 하십시오.", description = "자네가 리치 왕의 부하가 아니라고 주장하고 있는데다, 베소르가 이 책에 불어넣은 마법이 그 말이 사실임을 증명해 주는군. 하지만 자네가 스컬지의 적이라는 것을 증명해야 믿을 수 있을 것 같군.\n\n이 섬 남쪽 끝에 또 다른 조그만 섬이 있는데 그곳에 오래된 피투성이의 제단이 있네. 강력한 스컬지 요원, 릴리스 네파라가 사용하는 것이지.\n\n여기 있는 상자에서 부름의 양초를 가지고 가서 제단 위에 이 양초를 올려놓고 불을 붙이면 릴리스가 깨어날 걸세. 릴리스를 처치하면 자네가 리치 왕의 졸개가 아니라는 것을 믿어 주지.", progress = nil, completion = "릴리스 네파라를 해치우다니 자네는 스컬지의 적이 확실하군. 정말 믿기 어려운 걸...\n\n언데드 중 자유의 몸은 나 혼자인 줄 알았는데, 자네가 나 말고 리치 왕의 지배를 벗어난 자가 있다는 걸 증명해 보였군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[410] = {title = "잠든 망령", objective = "오래되고 곳곳이 깨진 피투성이 제단입니다.", description = nil, progress = "오래되고 곳곳이 깨진 피투성이 제단입니다.", completion = "제단 위에 부름의 양초를 올려 놓고 불을 붙입니다...", rewards = nil},
[411] = {title = "회개한 마술사의 귀환", objective = "언더시티에 있는 베소르 아이스샤드에게 지옥의 보석을 가져가야 합니다.", description = "이 지옥의 보석을 내 오랜 친구인 베소르에게 가져다주게. 이것으로 내가 그와 교신할 수 있게 될 걸세. 아.. 그에게 할 말이 무척 많군.", progress = "군터에게 책을 돌려주었나? 그가 뭐라고 하던가?", completion = "그를 우리 편에 합류하도록 설득하는데 성공하다니! 자네는 포세이큰을 위해 큰일을 해냈어. 어둠의 여왕께 이 일을 알려드리도록 하겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n뼈 버클러"},
[412] = {title = "작전명 유전자 재결합", objective = "카라노스에 있는 라즐 스프리스프로켓에게 재고정 물림기어 8개와 자이로 기어 8개를 가져다주어야 합니다.", description = "놈리건의 상황을 자세히 분석해 보니 우린 트로그를 박멸하는데 실패했을 뿐 아니라, 대부분의 노움 종족을 끔찍한 방사능에 오염시켜 지각 없이 악행만 일삼게 만들어버렸네.\n\n나와 오지가 최근 발명한 유전자 재결합기를 이용하면 이 끔찍한 상황을 되돌려 놓을 수 있을지도 몰라. 기계는 거의 완성되었는데 재고정 물림기어와 자이로 기어가 무척 부족해서 말이야. 자네가 놈리건 외곽에 있는 오염된 노움들에게 기어를 몇 개 빼앗아 주게.", progress = "재고정 물림기어와 자이로 기어를 충분히 확보하는 대로 유전자 재결합기를 가동할 수 있을 거야.", completion = "이 자이로 기어와 재고정 물림기어는 오지가 설계한 유전자 재결합기와 완벽한 조화를 이루지. 이제 내부 연소 피스톤에 수소 윤활제를 바르고 크랭크축과 전기검 젤의 점도 증가량을 조절하기만 하면 돼. 그러면 &lt;race&gt; 종족은 다시 태어난 것처럼 원상태로 돌아올 거라고.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n운전용 장갑기름 얼룩진 망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[413] = {title = "쉼머 스타우트 맥주", objective = "산악경비대 발리브루에게 쉼머 스타우트 맥주통을 가져다주어야 합니다.", description = "산악경비대에 근무 중인 우리 형 발리브루한테 내가 만든 새 쉼머 스타우트 맥주 맛을 보여줬으면 하는데... 형은 모단 호수의 경계 부근에 있는 두 개의 탑 중 남쪽 경비탑에서 근무하고 있을거야.\n\n형은 발리브루 가문 드워프들처럼 양조업을 하지는 않지만 술을 무척이나 좋아하니 분명 아주 기뻐할 걸세.\n\n이 쉼머 스타우트 맥주통을 나 대신 좀 갖다주겠나?", progress = "이봐, <class> 양반! 여긴 무슨 일로 왔소?\n\n뭔가 흥미진진한 좋은 소식이라도 가져 온 거요? 한 동안 변변한 전투도 없었고 맥주도 거의 바닥이 나서 지루하던 참이었는데...", completion = "&lt;쉼머 스타우트를 맛보는 발리브루&gt;\n\n와, 이거 정신이 번쩍 드는걸! 눈이 밝아진 느낌이야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[414] = {title = "카드렐에게 맥주 배달하기", objective = "산악경비대 카드렐에게 쉼머 스타우트 술통을 가져다주어야 합니다.", description = "내 동생이 만든 쉼머 스타우트, 좀 마셔보니 이거 정말 물건이군! 동료 산악경비원에게도 맛보여 줬으면 좋겠소. 그 친구 이름은 카드렐인데, 주로 모단 호수에서 텔사마를 통과하는 도로를 순찰하고 있소.\n\n텔사마로 가려면 동굴을 따라 남동쪽으로 간 다음 길이 갈라지는 곳에서 북동쪽으로 가시오.\n\n산악경비대 카드렐에게 이 쉼머 스타우트 술통을 전해주고 맛이 어떤지 한번 물어봐 주시오!", progress = "반갑소, <class> 친구. 텔사마에 온 것을 환영하오!", completion = "어디 한번 맛 좀 봐야겠군.\n\n세상에! 머리가 빙빙 도는군! 팔다리도 훨씬 가벼워진 것 같고 말이야.\n\n날아갈 듯한 기분이야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[415] = {title = "레욜트의 새 술", objective = "레욜트 발리브루와 대화하십시오.", description = "브루날 마을의 레욜트 발리브루가 자네를 찾고 있다네. 요즘 만들고 있는 새로운 술에 대해 이야기하고 싶은 모양이더군. 뭐라더라... 자네가 도와 줄 수 있을 거라던데 말이야. \n\n브루날 마을로 다시 돌아가 그의 이야기를 들어 보겠나? 아마 공짜 술은 배불리 얻어 먹을 수 있을 걸세.", progress = nil, completion = "오! 전에 내게 가져다 줬던 쉼머위드 기억나나? 그걸 이용해 몇 가지 술을 제조해 봤는데 그 중 하나에서 정말 독특한 맛이 나왔다네!\n\n자, 맛 좀 보고 어떤지 평가해주게...", rewards = "다음과 같은 것들을 받습니다:\n\n쉼머 스타우트 맥주잔"},
[416] = {title = "코볼트 사냥", objective = "텔사마에 있는 산악경비대 카드렐에게 동굴쥐일족의 귀걸이 12개를 가져다주어야 합니다.", description = "여기서 서쪽으로 정말 심각한 문제가 일어나고 있소. 동굴쥐 코볼트들이 언덕으로 이사를 와서는 함부로 소굴을 만들어서 우리 땅을 더럽히고 있단 말이지!\n\n그 코볼트들을 제거했으면 하오. 코볼트를 사냥하고 귀걸이를 모아오면 보상금을 드리겠소.\n\n동굴쥐 코볼트 소굴은 텔사마 서쪽에 있는 산 중턱에 흩어져 있다오.", progress = "코볼트는 많이 잡았소?", completion = "으웩! 귀걸이를 가져오라고는 했지만 이렇게 고약한 냄새가 날 줄은 생각도 못했는데!\n\n수고했소, 여기 보상을 받으시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n연마된 통가죽 팔보호구기병 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[417] = {title = "조종사의 복수", objective = "썩은발톱을 처치해야 합니다.\n\n그러고 나서 놈의 발톱과 힐델브의 일지를 조종사 해머풋에게 가져다주어야 합니다.", description = "힐델브의 일지에는 썩은발톱의 공격을 받았다고 적혀 있습니다. 힐델브는 그 짐승을 물리치려다 심한 상처를 입은 것 같습니다.\n\n시체의 상태를 보니 썩은발톱이 나중에 다시 돌아와 그를 죽인 것 같습니다.\n\n일지에 그의 마지막 유언이 남아 있습니다.\n\n썩은발톱에게 복수를!", progress = "이 보게. 내 친구 힐델브에 대한 소식을 가지고 왔나?", completion = "정말 슬픈 소식이군. 힐델브는 정말 좋은 친구였는데... 나도 자네와 함께 썩은발톱이라는 짐승에게 복수를 할 수 있었으면 좋았을 텐데!\n\n어쨌든 고맙네. 아이언포지 전차 부대의 조종사들은 자네가 세운 공을 잊지 않을 걸세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n장인의 단검튼튼한 쇠망치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[418] = {title = "텔사마 선지 소시지", objective = "텔사마에 있는 비드라 하트스토브에게 곰 고기 3개, 멧돼지 창자 3개, 거미 수액 3개를 가져다주어야 합니다.", description = "이곳 텔사마에서는 식당이 항상 손님들로 북적대지요. 아이들도 들락날락 거리고, 밤에는 힘든 하루 일과를 마친 채굴꾼들로 붐비고 말이에요. 우리 집은 선지 소시지가 유명하거든요. 당신은 아직 먹어 본 적 없지요?\n\n아마 그렇겠죠. 그런데 이곳에서는 열심히 일한 사람들만이 식사를 할 수 있어요. 당신이 아무리 멋진 <class>|1이라고;라고; 해서 예외가 될 수는 없죠.\n\n곰 고기, 껍질로 사용할 멧돼지 창자, 양념으로 사용할 거미 수액이 필요해요. 당신은 재료만 가져오세요. 요리는 내가 할 테니까!", progress = "요리를 시작할 준비가 다 됐는데, 재료는 가져왔나요?", completion = "보기보다 만들기 훨씬 어렵긴 하지만... 조금만 기다려 보세요.\n\n음, 당신처럼 소시지 만드는 데 많은 관심을 보인 사람은 처음이군요. 만일을 대비해 조리법도 드리죠. 자, 다 됐어요. 따뜻할 때 어서 드세요!", rewards = "다음과 같은 것들을 받습니다:\n\n선지 소시지조리법: 선지 소시지"},
[419] = {title = "실종된 조종사", objective = "조종사 힐델브를 찾아야 합니다.", description = "내 친구이자 동료 증기 전차 조종사 모리 힐델브가 언덕에서 길을 잃었네. 우리 둘은 좋은 화약을 만드는데 필요한 희귀한 광석을 찾아 나섰는데, 힐델브가 전차를 가파른 언덕으로 몰고 가다가 그만 고장이 나 버렸지.\n\n그래도 힐델브는 이 산에 그 광석이 분명히 있다면서, 내게 전차를 지키라고 하고선 광석을 찾으러 갔다네.\n\n밤이면 언덕에서 짐승의 울음소리 같은 것이 들려오는데 벌써 며칠이 지났는데도 돌아오지 않고 있네. 모리가 강한 친구긴 하지만 그래도 걱정이 되어서 말이야.\n\n제발, 그를 찾아 주게.", progress = nil, completion = "썩은 고기를 먹는 산짐승에게 심하게 할퀴고 뜯겨 얼어 붙은 드워프의 시체입니다. 시체의 손에는 책 한 권이 쥐여져 있는데 그 안에는 모리 힐델브가 갈겨 쓴 쪽지가 있습니다. 또한 시체에는 아직 온전한 상태의 전차 부대 조끼가 걸쳐져 있습니다.\n\n아무래도 이 끔찍한 모습이 증기 전차 조종사 힐델브의 최후인 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n전차 부대 조끼"},
[420] = {title = "그렐린의 보고서", objective = "그렐린의 보고서를 카라노스에 있는 세니르 화이트비어드에게 전달해야 합니다.", description = "터널 안에 있는 사나운 트로그들은 누구든 가리지 않고 공격합니다. 하지만 당신 정도라면 큰 걱정은 없을 것 같습니다.\n\n세니르씨를 만나려면 카라노스로 가야 합니다. 터널을 빠져나가서 길을 따라가다 보면 카라노스에 도착하게 될 테니 거기서 세니르를 찾아 보십시오.", progress = "새로운 친구, 반갑네. 한잔 할 텐가? 추위엔 맥주가 제격이지.", completion = "이게 뭔가? 아, 동생이 보낸 보고서로군. 흠...\n\n폐하의 이름을 함부로 쓰지 말라고 얘기했는데 이 녀석이 말을 듣지 않는군. 크게 문제될 건 없겠지만 원로원의 고지식한 몇몇 의원들은 신경 좀 곤두세우겠는걸. 뭐, 그 사람들이야 좀 그럴 필요가 있긴 하지만, 하하!\n\n그나저나 나도 아이언포지에 보고서를 보내야 할 텐데 생각보다 좀 늦어지는군.\n\n자네만 괜찮다면 나중에 그 일을 좀 부탁하도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[421] = {title = "실력 검증", objective = "공동묘지에 있는 달라 던위버가 달의분노일족 백발전사 5마리를 처치해 달라고 부탁했습니다.", description = "실바나스 여왕님께서는 바리마트라스님께 남쪽에 있는 인간과 드워프의 땅을 점령하라고 명하셨소. 그런데 지금은 그림자송곳니 성채의 저주받은 짐승이 되어 버린 그 멍청한 달라란의 협잡꾼 아루갈, 그 바보가 마법을 앞뒤 가지리 않고 남발하여 전략적으로 중요한 은빛소나무 숲의 성채를 난장판으로 만들고 말았소이다.\n\n전투 경험이 많은 노련한 베테랑이 그곳에 가서 아루갈이 저질러 놓은 짓을 정리해야 하는데 말이지... 달의분노일족 백발전사 5마리를 처치하여 당신의 능력을 한번 증명해 보여 주시오. 그 비열한 짐승들은 저 아래 언덕 밑의 길가에 종종 나타나곤 하오.", progress = nil, completion = "그만하면 충분하오. 그 정도면 은빛소나무 숲에서 아루갈의 저주를 푸는 임무도 믿고 맡길 수 있을 것 같군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신비한 지능\n\n다음과 같은 것들을 받습니다:\n\n"},
[422] = {title = "아루갈의 계략", objective = "공동묘지에 있는 달라 던위버에게 아루갈의 치료법을 가져가야 합니다.", description = "아루갈이 애들 장난 같은 마법 능력으로 어떻게 해서 키린 토에서 그리 인정을 받게 되었는지는 나로서도 알 길이 없군.\n\n우선은 아루갈이 사용한 마법이 정확히 무엇인지 알아내어 이를 풀고 어둠의 여왕님을 위해 은빛소나무 숲을 지켜내는 것이 중요하오.\n\n아루갈이 제일 처음 기거한 곳은 저 아래 다리를 건너서 바로 오른쪽에 있는 밀농장, 발간 농장이오. 죽음의추적자들 중 한 명이 마법책을 발견했지만 손에 넣지는 못했다는 보고가 들어왔소. 그 마법책들 중에서 아루갈의 치료법이라는 주문서를 찾아 오시오.", progress = "아루갈의 치료법이라는 주문서를 연구해 보면 정확한 내막을 알 수 있을 것이오. 당장 그 주문서를 가져오지 못한다면 다른 충직한 부하를 찾아볼 수밖에...", completion = "그래, 이게 바로 내가 찾던 주문서요. 어둠의 여왕님의 뜻을 따르기 위한 그 헌신적인 활약이 앞으로도 아무 탈 없이 계속 된다면 포세이큰 일원으로서 미래가 보장될 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신비한 지능\n\n다음과 같은 것들을 받습니다:\n\n"},
[423] = {title = "아루갈의 계략", objective = "공동묘지에 있는 달라 던위버에게 광신도의 족쇄 6개와 검은영혼의 족쇄 3개를 가져가야 합니다.", description = "아루갈의 치료법을 조사해 보니, 역시 내 불길한 예감이 딱 들어맞았더군. 역시 그자는 긴박한 시기에 키린 토를 대표할만한 인물도 아니거니와 달라란에서 큰일을 할만한 인물도 전혀 아니었소. 바보 같으니라고!\n\n아루갈은 마법이 걸린 물건들을 이용하여 자신의 약한 마법을 강화했던 것이오. 우선 조사해봐야 할 물건들이 있소. 어서 가서 달의분노일족 광신도와 달의분노일족 검은영혼들을 처치하고 그들의 마법의 족쇄를 충분히 모아 오시오. 그 역겨운 짐승들은 북쪽과 동쪽 지역에서 목격되었소.", progress = "상황을 파악하고 아루갈 문제에 대한 궁극적인 해결책을 찾으려면 광신도의 족쇄 6개와 검은영혼의 족쇄 3개가 필요하오. 어서 달의분노일족 광신도와 검은영혼을 처치하고 족쇄를 모아오시오.", completion = "몇 개 안 되는 표본으로 충분한 힘을 모을 수 있어야 할 텐데... 흠 더 모아 오라고 할 걸 그랬군.\n\n아무튼, 수고했소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신비한 지능\n\n다음과 같은 것들을 받습니다:\n\n"},
[424] = {title = "아루갈의 계략", objective = "은빛갈기 그림슨을 처치하고 그의 해골을 공동묘지에 있는 달라 던위버에게 가져가야 합니다.", description = "아루갈이 사용한 마법의 흑막을 캐내는 게 생각했던 것보다 시간이 오래 걸릴 것 같소.\n\n그동안 우리 죽음의추적자들이 발견한 작은 문제를 좀 해결해 주겠소? 정보에 의하면 아루갈이 남동쪽 언덕에 있는 심원 광산에 그의 마법을 퍼뜨린 것 같소. 그 광산은 바리마트라스님의 군대에 매우 유용한 자원이 될 것이라 증명되었소.\n\n가서 타락한 은빛갈기 그림슨이라는 광산 우두머리를 처치해 주시오. 그를 처치하면 광산은 우리 손에 들어올 것이오.", progress = "은빛갈기 그림슨은 처치했소? 우리가 바리마트라스님의 명령을 무시한다면 그분의 노여움을 사게 될 것이오.", completion = "정말 훌륭하군. 이 광산의 자원은 은빛소나무 숲과 아제로스 전역으로 퍼져나가는 포세이큰 군대가 아주 유용하게 사용할 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신비한 지능\n\n다음과 같은 것들을 받습니다:\n\n"},
[425] = {title = "포악한 이바르", objective = "포악한 이바르를 처치하고 이바르의 해골을 이바르 호박밭에 있는 레인 요릭에게 가져가야 합니다.", description = "제 오빠 쿠인과 저에게 은빛소나무 숲을 정찰하는 임무가 주어졌었답니다. 그리고 하드렉님께 보고하기로 되어 있었고요. 그런데 농장을 가로질러 이동하던 중에 포악한 이바르로 불리는 구울에게 공격당해 아직 본격적인 정찰을 시작하지도 못했답니다.\n\n이바르에게서 도망치긴 했지만 오빠가 심각한 부상을 입고 말았어요. 가져다주신 물약 덕분에 오빠를 치료할 수 있었지만 오빠가 완전히 회복되기 전에 이바르가 다시 올지도 모릅니다.\n\n오빠가 안전하게 회복될 수 있도록 당신이 이바르를 처치해 주세요. 이바르는 저쪽 헛간에서 공격 기회를 엿보고 있어요.", progress = "이바르는 처치했나요? 저와 오빠를 위해서가 아니더라도, 포세이큰을 위해서 제발 그 녀석을 처치해 주세요.", completion = "고마워요. 정말 감사해요.\n\n상부에 보고할 때 당신에 대한 내용도 포함하겠어요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n누비 팔보호구낡은 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[426] = {title = "밀농장 습격", objective = "톱니모양 늑골 5개와 저주받은 해골 3개를 모은 다음 브릴에 있는 죽음의경비병 딜링거에게 돌아가야 합니다.", description = "스컬지가 아가만드 밀농장에 기지를 구축하려고 하네. 기지를 구축하고 나면 병력을 정비하여 티리스팔의 다른 지역을 공격하려 할 거야.\n\n밀농장에 있는 이 스컬지들을 처치하라는 명령이 내려졌네. 밀농장으로 가서 덜그럭거리는 해골병사와 금이간 해골병사를 처치하여 톱니모양 늑골을 모으고, 검은눈 해골마법사를 처치하여 저주받은 해골을 모아오게.\n\n밀농장으로 가려면 서쪽 길을 따라가다가 다리를 건넌 후에는 세 갈래 길에서 북쪽 길을 택해 계속 북쪽으로 가게. 아가만드 농장의 풍차가 보이면 전투를 준비해야 할 거야.", progress = "우린 스컬지와 전쟁 중이야. 맡은바 임무를 다하여 저주받은 언데드 녀석들을 역병지대로 다시 몰아내 주게!", completion = "자네의 멋진 활약이 우리에게 많은 힘이 돼 주었네. 당연한 일을 했을 뿐이니 따로 고맙다는 말은 하지 않겠지만 티리스팔에 있는 죽음의경비병들은 자네의 이름을 기억할 걸세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n묘지기의 장화질긴 헝겊 바지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[427] = {title = "붉은십자군과의 전쟁", objective = "브릴에 있는 집행관 자이건드가 붉은십자군 전사 10명을 처치해 달라고 부탁했습니다.", description = "집행관 아렌이 보내준 문서 덕분에 이제 티리스팔 숲에 포진한 붉은십자군의 정확한 위치를 알게 되었네. 때문에 저 야비한 붉은십자군과의 전투에서 훨씬 유리해지겠군.\n\n하지만 우리 죽음의경비병들에게 더 큰 걱정거리가 있네. 바로 리치 왕의 군대가 매일 밤 급속도로 늘어나고 있다는 거야. 그래서 붉은십자군 정도는 자네처럼 배포 있는 <class>|1이;가; 처리해 줬으면 좋겠는데...\n\n어둠의 여왕 폐하를 섬길 만한 자격이 있는지 증명해 보여주지 않겠나? 솔리덴 농장을 지나 서쪽의 탑으로 가서 붉은십자군 전사 10명을 처치해 주게.", progress = nil, completion = "대단한 성과로군. 자네 전투 능력이 이 정도라니 ... 아주 훌륭하군, 훌륭해.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[428] = {title = "실종된 죽음의추적자", objective = "죽음의추적자 쿠인 요릭과 레인 요릭을 찾아야 합니다.", description = "몇 주 전 우리 죽음의추적자 중 레인 요릭과 쿠인 요릭이라는 두 병사를 은빛소나무 숲 북부 지역으로 정찰 보냈는데 아직 소식이 없어 걱정일세.\n\n이 둘이 스컬지에게 희생된 건 아닌지 확인할 필요가 있으니 이들을 찾아 주게.\n\n그들의 첫 번째 목표는 은빛소나무 숲 북쪽에 있는 농장을 정찰하는 것이었으니 그곳을 먼저 수색하는 게 좋을 거야.", progress = nil, completion = "아, 우릴 구하려 오셨군요. 이제야 오시다니...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[429] = {title = "늑대의 심장", objective = "변색된 검은늑대 심장 6개를 모아 공동묘지에 있는 연금술사 렌퍼럴에게 가져가야 합니다.", description = "제 오빠 쿠인이 포악한 이바르라는 구울에게 심각한 부상을 입었어요. 적절한 마법 치료 없이는 가망이 없을 것 같아서 걱정이에요. 전 연금술사는 아니지만 그들이 검은늑대의 심장으로 치료 물약을 만들 수 있다는 건 알고 있답니다.\n\n이 짐승들의 심장을 모아서 남쪽의 공동묘지에 있는 연금술사 렌퍼럴에게 가져다주시고 치유 물약이 완성되면 여기로 다시 가져와 주세요. 검은늑대들은 이 근처나 동쪽의 말덴의 과수원에 많이 있을 거예요.", progress = "난 시간이 별로 없네, <class>. 어둠의 여왕께서 중요한 임무를 내리셨네.", completion = "&lt;심장을 건네 받는 렌퍼럴&gt;\n\n우리 죽음의추적자들이 임무에 실패했다니 낭패로군. 이런 실패는 두 번 다시 없어야 할 텐데 말이야.\n\n이번엔 물약을 직접 만들어 주겠지만, 내가 조제법을 일러 줄 테니 다음에 또 물약이 필요할 경우에는 자네가 직접 만들어 주도록 하게.", rewards = "다음과 같은 것들을 받습니다:\n\n조제법: 빛바랜 치유 물약빛바랜 치유 물약"},
[430] = {title = "쿠인에게 돌아가기", objective = "공동묘지 북쪽의 이바르 호박밭에 있는 쿠인 요릭에게 쿠인의 물약을 가져가야 합니다.", description = "자, 쿠인 요릭을 치료할 물약이네.\n\n그럼 난 계속해야 할 중요한 일이 있어서 이만 실례하겠네.", progress = "당신이 우리를 구하러 왔었다고 내 여동생이 말하더군. 사실이오?", completion = "&lt;물약을 건네 받아 마시며&gt;\n\n오! 물약의 효과가 느껴지는군. 곧 정찰 임무를 다시 시작할 수 있을 것 같소.\n\n정말 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[431] = {title = "부름의 양초", objective = "양초를 하나 집어 가방에 넣습니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n부름의 양초"},
[432] = {title = "저주받을 트로그", objective = "골볼라 채석장에서 현장감독 스톤브로우를 위해 바위턱일족 망치잡이 6마리를 처치해야 합니다.", description = "빌어먹을 트로그들, 내 작업장을 난장판으로 만들어 버렸네! 저것 보게, 화약통을 또 하나 가져가고 있잖아! 당장 내려가서 모조리 해치워 버렸으면 좋겠어! 전부 다 말이야!\n\n으... 참아야지. 이렇게 스트레스 받고 화내면 건강에 안 좋아... 그런데 이제 남은 게 뭐가 있지? 젠장, 아무것도 없네!\n\n내 손으로 다 죽여 버렸으면 좋겠지만 이제 나도 늙어서 말일세... 이 보라고, 채석장으로 내려가서 저 더러운 것들을 해치워 주게! 보상은 꼭 해 줄 테니! 눈에 보이는 대로 없애 버리게!", progress = "정말 돌아 버리겠어! 으드득...", completion = "휴, 이제야 기분이 한결 나아졌군...\n\n하지만 저 녀석들을 모조리 해치워 버리기 전까진 안심할 수 없어! 모조리 다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[433] = {title = "공무 수행", objective = "원로원의원 메르 스톤할로우를 위해 골볼라 채석장에서 바위턱일족 뼈다귀싸움꾼 10마리를 처치해야 합니다.", description = "나는 원로원의 의원이자 탐험가 연맹의 회원으로서 현재 우리 땅을 침범한 트로그 문제를 해결하기 위해 노력 중이라네.\n\n골치덩이 트로그들이 뚜렷한 이유도 없이 이 골볼라 채석장을 난장판으로 만들고 있네. 광부들이 땅을 파내려 가고 있는데 트로그들이 수도 없이 쏟아져 나와 장비를 빼앗아 파괴하고 인부들을 몰아냈다는군. 저 트로그들을 처치한 다음 채석장을 재건하고 다시 일을 시작해야 할 텐데...\n\n트로그 처치를 도와 준다면 자네의 수고에 대해 기꺼이 보상하겠네.", progress = nil, completion = "이건 단지 시작일 뿐이야. 이제 산악경비병만 몇 명 보내면 그 지역을 안전하게 지킬 수 있네. 다 자네 덕분이야. 차차 시설을 복구하고 광부들을 다시 보내 일을 시켜야겠지.\n\n도와줘서 고맙네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[434] = {title = "공격!", objective = "그레골 라스코발 경과 소리없는검객 마르존이 대화를 나눌때까지 정원에서 기다려야 합니다. 그후에 모두 처치한 후 스톰윈드에 있는 엘링 트리아스에게 돌아가야 합니다.", description = "첩보로봇을 변장시키고 나면 안으로 들어가서 라스코발에게 말을 걸게 될 거요. 첩보로봇은 경비병들을 문제없이 통과할 수 있을 거야.\n\n당신이 내게 줄 재료를 구해오는 동안 마르존에게 거짓 정보도 좀 흘려놓고 라스코발과 다시 만날 때가 되었다고 알려놓았지.\n\n라스코발은 그의 왕실근위병을 물러가게 하고 이 정원에서 마르존을 기다릴 것이오. 데피아즈단에 대해 얘기하는 기미가 보이거든 행동을 개시하라고. 경비병들이 돌아오기 전에 두 명 다 처치해야 하오!\n\n일이 끝나면 트리아스에게 얘기하라고.", progress = nil, completion = "다 해결했단 말입니까? 잘 됐군요. 일을 맡기로 한 당신의 결정에 감사드립니다. 벌써 여러 차례 당신의 가치를 입증한 셈이군요. 앞으로도 얼라이언스 내에서 당신의 활약상을 눈 여겨 보도록 하겠습니다.\n\n그리고 항상 점잖게 행동하기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[435] = {title = "엘런드 경호", objective = "레인 요릭이 있는 곳까지 늑대들을 물리치고 엘런드를 경호해야 합니다.", description = "밖에 있는 늑대들은 떠날 생각을 않고 날 사납게 노려보고 있소. 내가 저 문으로 한 발짝이라도 내딛으면 놈들이 덤벼 들 거요. 놈들은 너무 굶주린 나머지 나를 맛있는 먹잇감으로 보고 있는 것이 분명하오.\n\n동료인 레인 요릭에게 보고서를 가져다 줘야 하는데, 그러려면 아무래도 누군가 날 좀 보호해 줘야 할 것 같소.\n\n당신이 날 좀 도와주겠소? 늑대들이 너무 많아서 혼자서는 힘들지도 모르니 친구들이 더 있다면 도움이 될 것이오.", progress = nil, completion = "고마워요. 엘런드가 이 위험한 은빛소나무 숲에서 변이라도 당한 건 아닌지 얼마나 걱정했다고요. 당신이 도와준 덕분에 그를 다시 볼 수 있게 되었네요.", rewards = "다음과 같은 것들을 받습니다:\n\n죽음의추적자 쇼트소드"},
[436] = {title = "아이언밴드의 발굴 현장", objective = "탐험가 펠휴와 대화하십시오.", description = "발굴조사단장 아이언밴드가 호수 동쪽의 고대 유적지에서 발굴 작업을 지휘하고 있소. 그런데 최근 작업 진행 속도가 더뎌지고 있소. 지금까지 우리가 제공해 준 보급품의 양을 고려하면 좀 이상한 일인데...\n\n아이언밴드는 결과를 중시하는 완고하고 정직한 드워프라서... 혹시 인부들이 그에게 반발하고 있는 건 아닌지 걱정이 되는군.\n\n아이언밴드의 발굴 현장으로 가서 마그마 펠휴와 이야기해 보시오. 현장의 세부사항을 관리하니까 작업 속도가 느린 이유를 알고 있을 거요. 발굴 현장으로 가려면 호수 남쪽 끝을 돌아 동쪽으로 가면 되오.", progress = nil, completion = "예른이 왜 작업 속도가 느린지 궁금해 한다고?\n\n아이언밴드가 최근의 상황 보고서를 상세히 기록하고 있지만 이것 하나만은 확실히 얘기해 줄 수 있소.\n\n바로 트로그가 문제요!!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[437] = {title = "죽음의 농장", objective = "죽음의 농장에서 썩은가죽 놀들을 처치하십시오. 나이트래쉬가 나타나면 그녀를 처치하십시오.\n\n공동묘지에 있는 고위집행관 하드렉에게 나이트래쉬의 정수를 가져가야 합니다.", description = "은빛소나무 숲의 초기 정찰 보고에 따르면 썩은가죽일족이 북쪽의 오래된 농장인 죽음의 농장을 본거지로 삼고 있다고 하네. 그들에게 산발적인 공격을 시도했지만, 마법을 사용하여 우리 군을 궤멸시키는 밴시 나이트래쉬 때문에 번번이 실패하고 말았네.\n\n나이트래쉬는 반드시 없애야 해. 죽음의 농장으로 가서 썩은가죽일족을 공격하게. 나이트래쉬가 나타날 때까지 썩은가죽일족을 처치하고 그녀가 나타나면 같이 처치하도록 하게.\n\n이제 그녀의 정수를 한낱 먼지로 만들어 버릴 때가 온 게야. 그 증거로 내게 그 정수를 가져오게.", progress = "나이트래쉬는 처치했나? 그녀를 처치해야 썩은가죽일족을 물리칠 수 있네!", completion = "썩은가죽일족에 대한 공격이 매우 성공적이었다고 들었네. 그리고 이 정수는 나이트래쉬의 죽음을 증명해 주는군그래.\n\n요즘은 스컬지의 패전 소식이 자주 들리는 걸. 이제 그대는 포세이큰을 위해 없어서는 안 될 존재가 되어가고 있네.", rewards = "다음과 같은 것들을 받습니다:\n\n정찰대 장화"},
[438] = {title = "오래된 나루터", objective = "오래된 나루터로 가서 그곳에 스컬지가 주둔한 이유를 찾아내야 합니다.", description = "우리는 오래된 나루터에서 새로운 스컬지의 소굴을 발견했네. 그 나루터는 공동묘지 동쪽에 있는데 썩은가죽일족과 다른 언데드들의 경계가 삼엄하다고 하는군.\n\n스컬지가 그곳에 자리 잡은 이유가 분명히 있을 거야. 그 오래된 나루터가 있는 곳으로 가서 스컬지가 그곳에 주둔하고 있는 이유를 알아내도록 하게.", progress = nil, completion = "이 배에는 무언가로 감싼 시체 더미가 쌓여 있습니다. 그리고 로다미어 호수 동쪽 건너편에는 펜리스 섬의 부두가 보입니다.\n\n이 시체들은 펜리스 섬과 관련이 있는 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[439] = {title = "썩은가죽일족의 단서", objective = "공동묘지에 있는 고위집행관 하드렉에게 델리아의 반지를 가져가야 합니다.", description = "시체들 사이에서 손 하나가 밖으로 나와 있습니다. 그 손은 여성의 것으로 역병으로 인한 반점이 있지만 비교적 생기 있어 보입니다.\n\n그리고 손가락에 반지가 끼워져 있습니다. 반지를 빼내 살펴보니 다음과 같은 문구가 새겨져 있습니다.\n\n\"델리아에게\"", progress = "오, 돌아왔군. 그래, 조사 결과 뭔가 소득이 있었나?", completion = "최근에 살해된 여자의 손에 이 반지가 끼워져 있었단 말인가?\n\n이 근처에서 이런 시체를 구할 수 있는 곳은 티리스팔의 묘지뿐이네. 썩은가죽 놀들은 그 시체들을 펜리스 섬으로 가져가려는 것이 분명해!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[440] = {title = "문자가 새겨진 반지", objective = "브릴에 있는 집정관 세브렌에게 델리아의 반지를 가져가야 합니다.", description = "남편인지 연인인지는 모르지만, 델리아에게 반지를 준 이를 찾고 싶다면 브릴에 있는 집정관 세브렌과 얘기해 보게. 아마 최근의 사망 기록이 있을 테니 운이 좋으면 델리아가 누군지 밝혀낼 수 있을지도 모르네.\n\n별로 기대하지는 않지만... 그녀에게 반지를 준 게 누구든 이미 죽었을 걸세. 죽지 않았더라도 더 이상 델리아에게 신경 쓰지 않을 거고 말이야.", progress = "어서 오시게. 여긴 무슨 일로 다시 온 겐가?", completion = "델리아는 얼마 전까지 브릴에 살았었네. 그녀는 공동 묘지에 묻혔지만, 자네 말이 사실이라면 썩은가죽 놀들이 그녀의 시체를 훔쳐 은빛소나무 숲으로 가져간 것이 분명해.\n\n스컬지와 마찬가지로 그 썩은가죽일족도 반드시 없애버려야 해. 자네라면 그들을 없애는 데 일조할 수 있을 거라 믿네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[441] = {title = "랠리와 언더시티", objective = "랠리에게 델리아의 반지를 가져가야 합니다.", description = "델리아에게는 지금 언더시티에 살고 있는 랠리라는 남편이 있었네. 브릴에 살았던 델리아가 이 반지의 주인이 맞다면 랠리가 알고 있을 거야.\n\n랠리는 언더시티 상업 지구 쪽에 있다네.", progress = "누구시오?", completion = "그렇소, 이 반지는 내 아내의 것이었소. 그녀는 이 난세를 이겨내지 못하고 다른 이들과 마찬가지로 희생되고 말았지. 이젠 아내의 죽음이나 그녀의 시체가 사라졌다는 것에 대해서는 아무런 느낌이 없소. 이미 내 안에서 그런 감정은 식은 지 오래니까... \n\n하지만, 내 죽은 심장에서도 아직 열망의 불꽃은 타오르고 있소이다. 바로 복수에 대한 열망 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[442] = {title = "펜리스 섬 공격", objective = "공동묘지에 있는 고위집행관 하드렉에게 쑤울의 머리카락을 가져가야 합니다.", description = "이제 은빛소나무 숲에 있는 스컬지의 본거지인 펜리스 섬을 공격할 때가 되었네.\n\n다시 펜리스 섬으로 돌아가 까마귀발톱 쑤울을 처치해야 하네. 그리고 그의 머리카락을 가져오게! 이번 임무는 매우 중요한 만큼 위험도 커. 반드시 성공해야 하네.", progress = "스컬지가 은빛소나무 숲에서 활개치도록 두어서는 안 되네. 까마귀발톱 쑤울을 죽이기 전까지는 돌아오지 말게!", completion = "까마귀발톱 쑤울을 죽인 것은 굉장한 성과였네. 렌퍼럴이 말하기를 자네가 쑤울을 처치하는 순간, 공동묘지에서도 그걸 느낄 수 있었다고 하더군.\n\n자네의 활약이 포세이큰 지도부에까지 알려지고 있어. 자네는 점점 더 우리에게 없어서는 안 될 존재가 되어 가고 있네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n대심판관의 로브갈퀴발톱 검\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[443] = {title = "썩은가죽일족의 영액", objective = "공동묘지에 있는 연금술사 렌퍼럴에게 썩은가죽일족의 영액 8병을 가져가야 합니다.", description = "펜리스 섬을 공격하기 전에 썩은가죽 놀들을 조종하고 있는 배후 인물이 누구인지 알아내야 하네. 우리 연금술사들은 그 놀들의 근원이 놈들의 몸에서 흘러나오고 있는 이상한 액체와 관련 있다고 믿고 있네.\n\n오래된 나루터 동쪽에 있는 펜리스 섬으로 가서 놀들로부터 썩은가죽일족의 영액을 모아 오게. 그리고 그걸 공동묘지 외곽에 있는 연금술사 렌퍼럴에게 가져가도록 하게.", progress = "썩은가죽일족의 영액은 가져왔나?", completion = "오, 좋아. 이 영액을 통해 썩은가죽일족의 본질과 약점까지도 알아낼 수 있을지 모르겠군...\n\n만약 약점이 있다면 말이지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[444] = {title = "썩은가죽일족의 기원", objective = "언더시티에 있는 베소르 아이스샤드에게 영액 견본을 가져가야 합니다.", description = "자네가 가져온 영액을 변형시켜 기본 구성 요소를 분리해 보았네. 연구 결과는 아직 확실하지 않지만, 이 영액은 흑마법사와 강령술사가 마법을 사용하여 만들어진 것 같네.\n\n내가 영액에 대한 연구를 계속할 동안 자네는 언더시티에 있는 베소르 아이스샤드님께 이 표본을 좀 전해 주게. 베소르님은 연금술사는 아니지만 마법에 대한 그분의 지식이 썩은가죽일족의 비밀을 알아내는 데 도움이 될 것이야.\n\n자, 어서 떠나게. 베소르님께서는 언더시티의 마법 지구에 계실 걸세.", progress = "내 연구는 굉장한 집중력을 요한다네. 그러니 자네가 하찮은 걸로 날 찾지 않았으면 하네만... 무슨 일인가?", completion = "이 물질에는 나도 오랫동안 보지 못한 강력한 주문이 걸려 있군.\n\n잠깐 기다려 보게. 예지의 주문으로 한번 알아내 볼 테니...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[445] = {title = "은빛소나무 숲으로의 배달", objective = "은빛소나무 숲에 있는 연금술사 렌퍼럴에게 요한의 연구 결과를 전달해야 합니다.", description = "지금쯤이면 당신도 확실히 알겠지만 실바나스 여왕님을 모시며 일하는 우리에게는 시간이 무엇보다 중요하오.\n\n왕립 연금술 학회의 회원으로서 내가 알아낸 지식을 동료와 교환해야 하는 것이 내 의무요. 그래야만 언젠가 어둠의 여왕님이 그토록 원하시는 새로운 역병을 만들어낼 수 있을 테니까 말이오.\n\n은빛소나무 숲의 공동묘지에 있는 연금술사 렌퍼럴에게 이 연구 결과를 전달해 주시오. 공동묘지로 가려면 브릴에서 길을 따라 남쪽으로 가다가 언더시티가 나오면 거기서 남서쪽으로 가면 되오.", progress = "내게 무슨 볼일이 있나, <class> 친구?", completion = "아, 연금술사 요한이 보낸 연구 결과는 대단하군. 이곳 은빛소나무 숲에서 워낙 많은 것을 새로 개발하다 보니 로데론과 티리스팔 숲 외부에서 들어오는 연구 결과에 대해서는 거의 잊고 있었네. 그러고 보니 이 견본품은 어서 죽음의 요새로 보내야겠군.\n\n아, 정신없이 굴어 미안하네. 자넨 일단 이곳에 머물러 주게. 자네처럼 쓸모 있는 &lt;class&gt;|1이;가; 필요하거든.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[446] = {title = "까마귀발톱 쑤울", objective = "은빛소나무 숲 공동묘지에 있는 연금술사 렌퍼럴에게 베소르의 두루마리를 가져가야 합니다.", description = "이 영액은 까마귀발톱 쑤울이라는 내 옛 동료가 만든 거라네. 대전쟁 이전에 그는 젊고 전도 유망한 마법사였지만 리치 왕이 권력을 장악하자 형제들을 배신하고 스컬지와 손을 잡았지.\n\n그가 아직 살아있다는 걸 몰랐는데다가 썩은가죽일족의 수장으로 우릴 공격하고 있던 자가 그자라니!\n\n난 그의 마법 주문에 대해 많이 알고 있으니 그 마법에 대항할 물약을 만드는 걸 도울 수 있네. 이 두루마리를 연금술사 렌퍼럴에게 다시 가져가게. 그 안에 물약을 만들기 위해 필요한 주문이 적혀 있네.", progress = "어서 오게. 그래, 베소르님께서 뭐라고 하셨나?", completion = "이 두루마리에는 강력한 마법이 담겨 있군. 지금까지 물약에 이런 힘을 사용해 본 적이 없는데... 아주 강력한 혼합물이 될 것 같네. 펜리스 섬의 요새에 기거 중인 쑤울을 공격할 때 아주 유용하겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n베소르의 물약"},
[447] = {title = "죽음의 비법", objective = "불곰 심장 6개와 땅거미 점액 6개를 모아 언더시티에 있는 수석 연금술사 파라넬에게 가져가야 합니다.", description = "아서스의 군대는 병력면에서 압도적인 우위를 차지하고 있네. 하지만 새로운 역병을 사용한다면 스컬지 군대와 인간의 영토를 모두 초토화할 수 있지. 내 연구 결과에 따르면 거미의 피와 불곰 심장에서 뽑아낸 독을 혼합하면 치명적인 비약을 만들 수 있다네.\n\n북서쪽에 위치한 암흑 땅거미굴의 거미와 은빛소나무 숲 전역에 돌아다니는 곰에게서 표본을 모아오도록 하게. 그리고 그 재료들을 언더시티에 있는 왕립 연금술 학회의 수석 연금술사 파라넬님께 전해 주게.", progress = "어서 오게. 그래, 왕립 연금술 학회에는 무슨 일이신가?", completion = "오, 연금술사 렌퍼럴이 보냈다고? 정말 반갑군. 이 표본들은 우리에게 실로 유용한 것들이네. 어서 표본의 독성과 오염 물질로서의 특성을 연구해 보아야겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n삼인 뿌리"},
[448] = {title = "하드렉에게 보고", objective = "공동묘지에 있는 고위집행관 하드렉에게 보고해야 합니다.", description = "펜리스 섬을 공격하기 전에 고위집행관 하드렉님께 보고하게. 그분이 다른 정보나 필요한 장비를 주실지도 모르네.", progress = nil, completion = "베소르가 말한 것이 사실이라면 까마귀발톱 쑤울은 서둘러 처리해야 할 위험한 인물일세.\n\n이곳에 있는 우리 무기고에서 이번 임무에 필요한 장비를 가져가도록 하게.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n일반 무게추일반 숫돌\n\n다음과 같은 것들 또한 받습니다:\n\n일반 방어구 키트"},
[449] = {title = "죽음의추적자의 보고", objective = "공동묘지에 있는 고위집행관 하드렉에게 죽음의추적자 보고서를 가져가야 합니다.", description = "아직 쿠인 오빠의 상처가 완치되지는 않았지만, 최대한 빨리 고위집행관 하드렉님께 보고를 드려야 해요. 포세이큰이 은빛소나무 숲을 장악하기 위해서 매우 중요한 정보에요.", progress = "죽음의추적자 정찰병들이 어떻게 되었는지 알아냈나?", completion = "은빛소나무 숲에 있는 스컬지들이 어떤 녀석들인지, 그리고 우리 죽음의추적자 정찰병들에게 무슨 문제가 생긴 것인지 알지 못해 답답했었다네.\n\n자네의 도움이 정말 컸네. 상을 받아 마땅해.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[450] = {title = "죽음의 비법", objective = "장작나무 마을에서 베랄드의 일지를 찾아 공동묘지에 있는 연금술사 렌퍼럴에게 가져가야 합니다.", description = "왕립 연금술 학회를 위해 자네가 해 줘야할 일이 더 있네.\n\n아루갈이 숲에 그 비열한 마법을 걸었을 때 장래가 촉망되는 우리의 베랄드라는 약제사도 저주에 걸렸다네. 그 저주로 인해 베랄드는 이제 아루갈의 꼭두각시가 되었으니, 미안한 일이지만 우리에겐 더 이상 이용가치가 없는 인물이야. 하지만 말이지 그의 연구 실적은 가치가 매우 높다네. 그는 수세기 전 로다미어 호수의 수중 생물들을 몰살시킨 고대의 역병에 대해 연구하곤 했었지.\n\n장작나무 마을 여관에 있는 베랄드의 연구실에서 베랄드의 일지를 찾아 연금술사 렌퍼럴에게 가져가게.", progress = "다시 왔군.", completion = "연금술사 베랄드의 일지로군! 역시 대단해. 자, 그럼 베랄드가 정신이 나가기 전에 무얼 하고 있었는지 한번 살펴볼까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[451] = {title = "죽음의 비법", objective = "호수늪지이끼 6개, 호수덤불이끼 6개, 그리고 굳어진 종양 1개를 언더시티에 있는 수석 연금술사 파라넬에게 가져가야 합니다.", description = "베랄드의 일지에 따르면 호수덤불괴물과 호수늪지괴물의 이끼가 새로운 역병 제조에 유용할지도 모르겠군. 이 짐승들은 동쪽의 로다미어 호수에 있는 섬에 살고 있지.\n\n또한 그는 일지에 썩은지느러미멀록에게서 발견되는 매우 희귀한 굳어진 종양에 대해서도 언급하고 있네. 그 종양은 너무 희귀해서 베랄드도 하나밖에 입수하지 못한 듯해.\n\n이끼 표본과 함께 그 희귀하고 단단한 종양을 수집해서 언더시티에 있는 수석 연금술사 파라넬님께 가져가도록 하게.", progress = "그래, 이번에는 무얼 가져왔나?", completion = "아, 역시 베랄드를 잃은 건 왕립 연금술 학회에 크나큰 타격이었어. 하지만 자네의 노고와 연금술사 렌퍼럴의 부단한 연구 덕분에 베랄드의 연구를 어둠의 여왕님을 위해 사용할 수 있게 됐네.\n\n우린 이제 뭔가 엄청난 것을 발견하게 될 걸세. 자네의 전투 능력이 뛰어나지만 않았었다면 우리 학회 회원으로 발탁했을 텐데...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n야광 물약산성 면역 망토\n\n다음과 같은 것들 또한 받습니다:\n\n최하급 인내의 비약신속의 물약"},
[452] = {title = "장작나무 마을 매복", objective = "죽음의추적자 페를레이아를 도와 장작나무 마을 원로원들을 처치해야 합니다.", description = "오, 제때에 와줬군요!\n\n곧 장작나무 원로들이 돌아올 거예요. 아루갈이 성채에 머무르는 데는 다른 이유가 있답니다. 그는 원로들을 꼭두각시로 만들어 장작나무 마을 주민들을 마음대로 조종하면서 부하로 삼고 있어요. 장작나무 마을 원로들만 없다면, 아루갈의 부하 노릇을 하고 있는 마을 주민들도 모두 풀려나게 될 거예요.\n\n하지만 혼자서 모든 원로들을 상대할 수는 없으니 당신 도움이 필요해요. 나와 함께 싸워 주실 수 있나요? 우리 함께 실바나스 여왕님의 이름으로 원로들을 처단하자고요.", progress = nil, completion = "당신은 정말 어둠의 여왕님의 신하로서 잘 싸워주었어요. 원로들을 처치했으니 이제 마을은 우리의 통제하에 있게 되었고 아루갈을 그림자송곳니 성채에서 몰아낼 수도 있을 거예요. 정말 고마워요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n페를레이아의 방패신축성 있는 가죽 바지신비한 어깨망토\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[453] = {title = "의문의 남자 찾기", objective = "의문의 남자를 찾으십시오. 지금까지 얻은 단서는 다음과 같습니다.\n\n다크샤이어에서 태어난 사람이 아닙니다.\n신경질적이고 신경 과민인 사람입니다.\n다크샤이어를 떠나 서쪽 방향으로 갔습니다.", description = "행운이 있기를... 그 사람을 꼭 찾으시기 바랍니다. 그 친구가 살아있어야 할텐데... \n\n다크샤이어의 안전한 울타리를 벗어났으니 야생 짐승들의 먹이가 되었을 수도 있거든요.", progress = "당신은 누굽니까? 날 좀 내버려 두세요!", completion = "&lt;한숨을 쉬며...&gt;\n\n그래요, 내가 그 책을 썼습니다. 결국 날 찾아냈군요?\n\n당신이 내 일지를 다 읽었다고 해도 진실의 반밖에 모르는 겁니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[454] = {title = "훌다르와 미란", objective = "미란과 대화하십시오.", description = "이제까지는 셋이 왔다갔다하면서 화약통을 운반했는데... 이제는 일을 나눠서, 미란이 운반하고 나는 여기서 다른 통들을 지켜야 하겠군.\n\n그런데 미란 혼자 운반하는 게 걱정돼서 말이야. 미란이 준비를 마치고 출발하게 되면 그를 경호해주지 않겠나?", progress = nil, completion = "안녕하시오, &lt;class&gt; 친구!\n\n발굴 현장까지 나를 경호하기로 했다고? 듣던 중 반가운 소리군. 사옌의 배신 행위를 돌이켜보면 검은무쇠단 드워프놈들이 또 무슨 짓을 꾸미고 있는지 그 누구도 알 수 없지.\n\n어쨌든 마지막으로 몇 가지 점검할 것이 있소. 출발할 준비가 되면 내게 다시 말하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[455] = {title = "알가즈의 위기", objective = "던 알가즈를 가로질러 가야 합니다.\n\n용아귀부족 정찰병 8명과 용아귀부족 그런트 6명을 처치해야 합니다.\n\n메네실 항구에 있는 발스탁 아이언조에게 보고하십시오.", description = "용아귀부족 오크들이 저습지를 차지한 것도 모자라, 이제 던 알가즈에까지 손을 뻗어오고 있소! 이곳에 있는 놈들의 거점을 제거하지 않으면 저습지에 있는 우리의 항만 시설과 요새인, 메네실 항구에서 모단 호수에 이르는 길목을 차단당하게 되오.\n\n던 알가즈를 가로질러 저습지 너머로 이동하시오. 그리고 가는 길에 오크 녀석들도 좀 처치해 주시오. 그런 다음 메네실 항구에 있는 발스탁 아이언조에게 보고하도록 하시오.\n\n메네실은 던 알가즈를 지나 길을 따라 북쪽으로 간 다음 갈림길에서 서쪽으로 가면 되오.\n\n우린 당신만 믿겠으니 우릴 실망시키지 마시오.", progress = nil, completion = "정말 나쁜 소식을 가지고 왔군!\n\n알가즈가 붉은용일족들에게 그리도 유린당하고 있다니... 하지만 보통 언덕에 숨어 지내는 용아귀부족들이 왜 알가즈로 몰려들게 되었는지 알다가도 모를 일이군.\n\n어쨌든 고맙소. 그리고 앞으로도 우릴 도와서 오크들과 싸워 줬으면 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[456] = {title = "자연의 균형", objective = "새끼 흑호 7마리와 새끼 엉겅퀴멧돼지 4마리를 처치한 다음 관리인 일사레인에게 돌아가십시오.", description = "어서 오십시오. 저는 관리인 일사레인이라고 합니다. 그늘 협곡에서 자연의 균형을 유지하는 일을 맡고 있습니다.\n\n올해는 유난히 봄비가 많이 내려서 많은 짐승이 피해를 입었답니다. 하지만 어떤 짐승에게는 오히려 좋은 일이 되었습니다. 특히 엉겅퀴멧돼지와 흑호의 수가 눈에 띄게 늘었는데 우리에겐 골칫거리가 아닐 수 없습니다. 그늘 협곡에는 짐승을 먹일 식량이 한정되어 있기 때문에 생태계의 균형을 유지하는 것은 매우 중요한 일이랍니다.\n\n어서 가십시오, 젊은 <class>|1이여;여;. 가서 멧돼지와 흑호의 수를 줄여 자연의 균형을 지켜주십시오.", progress = "그대에게 부탁한 일은 다 끝내셨습니까? 흑호와 엉겅퀴멧돼지들을 처치한 후 다시 오십시오.", completion = "임무를 멋지게 완수해 주셨군요. 정말 고맙습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n궁술 훈련용 장갑열매잎 팔보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[457] = {title = "자연의 균형", objective = "관리인 일사레인이 병든 흑호 7마리와 엉겅퀴멧돼지 7마리를 처치해 달라고 부탁했습니다.", description = "그늘 협곡에 사는 어린 짐승의 수를 줄였으니 일단 출발은 순조롭다고 할 수 있습니다. 하지만 그대가 할 일은 남아 있습니다.\n\n이 문제를 해결하지 않는다면 숲의 자원이 금세 고갈돼 버릴 겁니다. 이 땅을 공유하고 있는 모든 생명을 위해 짐승 사냥은 반드시 시행해야만 하는 필요악입니다. 자연의 균형을 위해 숲으로 가서 병든 흑호와 엉겅퀴멧돼지를 처치해주십시오.", progress = nil, completion = "자연을 위한 헌신의 노력을 보여 주어 고맙습니다. 그대와 같은 젊은 &lt;class&gt;의 앞날은 아주 밝을 것이라 믿습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n주름 망토검은 가죽 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[458] = {title = "숲의 수호자", objective = "타린드렐라라고 하는 드리아드를 찾아야 합니다.", description = "그대를 이곳으로 이끌어 주신 엘룬께 감사를! 숲에 사는 정령들의 속삭임을 통해 이상한 소식을 들었소.\n\n신비한 숲의 수호자 타린드렐라가 그늘 협곡으로 돌아왔다고 하오. 몇 년 동안 칼림도어의 숲에서 이 드리아드의 존재를 느끼지 못했었소. 그녀가 이 땅에 돌아왔다면 필시 무언가 문제가 있는 것이 분명하오.\n\n타린드렐라를 찾아 그녀가 우리 숲에 온 이유를 알아내시오. 파수꾼의 보고에 의하면 알드랏실 남서쪽에서 그녀를 보았다고 하오.", progress = nil, completion = "용케도 나를 찾아냈군요, 젊은 &lt;race&gt;|1이여;여;... 그대를 보낸 걸 보니 멜리타는 현명한 드루이드군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[459] = {title = "숲의 수호자", objective = "악마의 이끼 8개를 모아 타린드렐라에게 가져가야 합니다.", description = "텔드랏실 숲에 사악한 기운이 일고 있어요. 저 언덕 너머를 한번 보세요. 한때는 평화로운 일족이었던 펄볼그들이 고향을 버리고 나무옹이일족이라는 새로운 이름 아래 시시각각 모여들고 있어요.\n\n숲의 생물들도 악마의 이끼에 오염된 것이 분명해요. 그렐과 그렐킨마저 그 지역을 오염시키며 그늘 협곡에 사는 모든 생물들을 위협하고 있으니까요.\n\n그렐과 그렐킨을 잡아 정말로 사악한 악마의 이끼의 마법에 걸렸는지 확인해 보세요.", progress = "내 짐작이 맞는지 증명해 주세요. <name>, 악마의 이끼 8개를 가져오세요.", completion = "&lt;name&gt;, 그늘 협곡에 사는 생물들을 위해 그대가 보여준 노력은 보상받아 마땅해요.\n\n제 두려움이 현실로 드러났군요. 그렐과 그렐킨이 악마의 이끼에 오염됐다면 이곳에 살던 펄볼그 무리인 나무옹이일족이 어떻게 되었을지도 대충 짐작이 가요.\n\n&lt;class&gt;|1이여;여;, 돌라나르로 가서 아스리다스 베어맨틀이라는 박식한 드루이드를 찾아보도록 하세요. 분명 이 숲의 안녕을 걱정하고 있을 테니까요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n무늬가죽 다리보호구추적용 장화덩굴나무 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n치료용 약초"},
[460] = {title = "분리된 몸과 머리", objective = "알라리크의 머리를 그의 무덤으로 데려가야 합니다.", description = "당신은 썩은가죽일족은 아닌 것 같으니 다행이군. 난 완전히 희망을 잃었소.\n\n난 쑤울의 수석 부관이자 경호원이었던 알라리크라고 하오. 쑤울은 끔찍한 역병에서 나를 보호하기 위해 마법을 사용했는데 그가 사용한 주문 때문에 난 살지도 죽지도 못하게 되어 버렸소. 쑤울이 망할 놈의 썩은가죽 놀을 만들어낸 후에 나를 배신한 거야!\n\n제발 나를 내 몸이 있는 곳으로 데려가 주시오. 놀들이 펜리스 요새 근처에 있는 마구간 앞에 내 몸을 묻었을 거요.", progress = "이 무덤은 급하게 판 것 같습니다.", completion = "고맙소. 놀들이 벌써 내 몸을 없애 버렸을까 봐 걱정했는데... 이렇게 온전한 걸 보니 여간 반가운 게 아니군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[461] = {title = "비밀 벽감", objective = "알라리크를 비밀 벽감으로 데려가야 합니다.", description = "성채 안 어딘가에 쑤울과 그의 오랜 동료들이 소중한 물건을 숨겨 놓는 비밀 벽감이 있다고 알고 있소. 거기에는 당신에게 유용한 것도 있을 것이오. 나를 그곳으로 데려가 주시오!\n\n그 벽감은 성채의 남서쪽 탑에 있는 먼지투성이 선반 뒤에 숨겨져 있소. 장화는 신경쓰지 말고 내 몸이나 챙겨주시오. 하도 작아서 신을 수가 있어야지...", progress = "바로 이곳이요! 좀 더 가까이 다가가 주겠소?", completion = "좋아! 열려 있군. 나를 내려 주시오. 이 성채에서 지내던 시절이 내 인생 최고의 순간이었소. 이 성벽 안에서 편히 쉴 수 있으리라 생각했는데...\n\n저 썩은가죽일족 놈들이 나를 발견하면 안 되니까 벽감에 최대한 가까이 붙으시오.\n\n오, 이거 괜찮군... 자, 받으시오. 당신은 그걸 가질 자격이 충분하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[463] = {title = "신록의수호자", objective = "신록의수호자를 찾아야 합니다.", description = "신록의수호자에 대해 들어봤나? 혹시 그 짐승을 찾고 있는 건가? 흠, 그렇다면 당신 정신 나간게야. 뭐, 목숨 아까운 줄 모르는 바보를 구태여 내가 뜯어 말릴 필요는 없겠지.\n\n그 짐승을 찾고 있다면 던 모드르 쪽으로 갈라지는 길 동쪽에 있는 습지 근처에 산다고 하니까 그쪽으로 가 보라고. 악어 사이에 숨어 있다고 하는 친구도 있었지... 그보다 더할 수도 있지!\n\n그리고 참, 돈은 여기 놓고 가라고. 거기 가 봤자 필요 없을 테니까 말이야. 그 늙은 녹색 짐승이 당신을 두 동강내서 씹어 먹을 때 금화에 그 이빨 자국이 남게 되는 걸 바라지 않겠지?", progress = nil, completion = "나무의 뿌리와 고사리들이 너를 칭송하고 있구나. 난 많은 이름이 있지만 내가 응답하는 자는 몇 되지 않는다. 날 레시엘이라고 부르도록 하라.\n\n잘 듣어라. 상처 입은 이 땅이 고통으로 신음하는 소리가 들리지 않는가? 내 그대에게 이 땅을 치유하는 임무를 맡기려 하노라.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[464] = {title = "전쟁 깃발", objective = "메네실 항구에 있는 경비대장 스타우트피스트에게 용아귀부족 전쟁 깃발 8개를 가져가야 합니다.", description = "용아귀부족 오크는 자신들이 부리던 붉은용을 통제할 수 없게 되면서 2차 대전쟁이 종결될 즈음에 거의 섬멸됐었네. 용들은 옛 주인에게 불만이 많았었는지 무서운 기세로 용아귀부족을 공격했지. 얼마 남지 않은 생존자들은 그림 바톨을 탈출하여 웰가르의 발굴 현장 동쪽에 있는 산으로 피신했다네.\n\n그런데 그들이 힘을 길러 지금 메네실 북동쪽에 진을 치고 있네.\n\n자네가 놈들의 주둔지를 공격해 주게. 그리고 임무 완수의 증거로 놈들의 전쟁 깃발을 모아 내게 가져오게나.", progress = "용아귀부족 녀석들의 주둔지는 공격했나?", completion = "잘 싸웠네. 용을 부릴 때에 비하면 용아귀부족 녀석들이 약해지긴 했겠지만, 아직도 충분히 위협적인 적임엔 틀림없지.\n\n지금 용아귀부족은 네크로쉬란 놈이 지휘하고 있는데, 놈은 몇 년 전까지 용아귀부족의 우두머리였던 네크로스의 아들일세. 네크로스는 강력한 마법을 사용하여 붉은용들을 길들였지만, 결국 그 마법이 풀리고나자 용들이 마구 날뛰게 된 걸세.\n\n결국 네크로스는 용들에게 목숨을 잃었고 그의 아들이 아버지를 죽인 용에게 원수를 갚겠다는 맹세를 하고 나섰다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[465] = {title = "용아귀부족 투석기", objective = "용아귀부족 투석기를 파괴해야 합니다.", description = "자네가 용아귀부족과 싸우는 동안 놈들의 계획에 대한 정보를 알아냈네.\n\n네크로쉬가 투석기를 만들어 메네실을 포위 공격하려 한다는 걸세! 던 알가즈도 교전 중이기 때문에 우린 사실상 고립되어 지원병도 기대할 수 없는 상황일세.\n\n자네가 놈들의 투석기를 제거해 주어야겠네. 투석기는 용아귀부족의 주둔지에 있네.\n\n자, 이 부싯깃을 가져가도록 하게. 투석기가 있는 곳까지 접근한 다음 이 부싯깃으로 불을 붙이게. 그런 다음 네크로쉬를 찾아 반드시 처치해야 하네. 네크로쉬의 약점을 잘 찾아서 노리게.", progress = "투석기가 바로 눈 앞에 있습니다. 어서 불을 붙이십시오.", completion = "부싯깃을 투석기에 놓고 불꽃을 일으킵니다.\n\n그러자 불꽃이 일어나 삽시간에 번집니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[466] = {title = "발연 광석을 찾아서", objective = "던 모로에 있는 조종사 스톤기어에게 발연 광석 6개를 가져가야 합니다.", description = "저습지의 알가즈 관문 북서쪽에 있는 동굴에서 발연 광석이라는 희귀한 광석이 발견되었다고 들었네. 발연 광석은 휘발성 물질이라 자칫 잘못 사용하면 폭발 사고를 당할 수 있지만, 제대로 용해한다면 엄청난 화력을 자랑하는 포탄을 만들 수 있을 걸세!\n\n내게 발연 광석을 가져다주면 그 광석으로 실험을 할 용감한 사람을 찾아보도록 하지.\n\n아, 광맥에서 광석을 추출하려면 채광 기술이 있어야 한다네. 자네가 기술을 익히지 않았다면 채광 기술을 익힌 동료를 데려가도록 하게나.", progress = "광석은 찾았나?!", completion = "광석을 찾아내다니... 정말 잘했네! 바로 작업에 들어가도록 하지. 작업 중에 폭발하지 않길 빌어주게나!", rewards = "다음과 같은 것들을 받습니다:\n\n맥주 얼룩진 장갑"},
[467] = {title = "스톤기어의 광석", objective = "조종사 스톤기어와 대화하십시오.", description = "조종사 스톤기어는 여느 조종사들과 마찬가지로 자신의 원격 조종 전차에 대한 애착이 무척 강하다오. 항상 전차의 화력을 올릴 수 있는 새로운 방법을 찾으려고 열심이지.\n\n지금 그는 어떤 희귀한 광석에 대한 소문을 듣고는 자신을 위해 그 광석을 찾아다 줄 이를 구하고 있소. 생각이 있다면 던 모로에 있는 스틸그릴의 정비소로 가서 스톤기어를 만나 그가 뭘 원하는지 알아보도록 하시오.", progress = nil, completion = "반갑네. 내 일을 도와주러 온건가? 자네처럼 혈기왕성한 젊은 &lt;race&gt;|1이;가; 모험에 나서는 모습을 보는 건 기쁜 일이지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[468] = {title = "산악경비대 록가르에게 보고", objective = "산악경비대 록가르와 대화해야 합니다.", description = "산악경비대 록가르가 던 알가즈와 저습지에서 임무를 수행해 줄 지원자를 찾고 있다네.\n\n그 질퍽거리는 북쪽 지역에서 임무를 수행할 의향이 있다면 던 알가즈로 가서 록가르와 한번 얘기해 보게. 길을 따라 북쪽으로 가다 보면 경비탑이 나오는데 던 알가즈는 그 북쪽 경비탑 너머에 있네.", progress = nil, completion = "안녕하시오, &lt;class&gt; 친구! 정찰 임무에 지원하러 온 거요? 정말 반갑소!\n\n이번 정찰 임무는 좀 지저분할 수도 있으니 장비를 잘 손질해 두는 게 좋을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[469] = {title = "가죽 배달", objective = "메네실 항구의 무두장이 제임스 할로란에게 악어 가죽 한 묶음을 전달해야 합니다.", description = "안녕하시오!\n\n메네실 쪽으로 가는 것 같아 보이지는 않는군... 여유가 있다면 메네실에 한번 들러 보시기 바라오. 필요한 물건을 구입하는 건 물론이고 맥주 한 잔 하면서 쉬어가기에도 더할 나위 없이 좋은 곳이지.\n\n메네실 쪽으로 갈 거라면 무두장이 제임스 할로란에게 이 악어 가죽 한 묶음을 가져다주지 않겠소?\n\n내가 직접 가고 싶지만 요즘 우리 집사람 심기가 상당히 불편한 것 같아서 얼굴을 마주치기가 좀 그렇소이다.", progress = "어서 오십시오. 부츠 한 켤레 보여 드릴까요? 아니면 새로 가공한 가죽은 어떻습니까?", completion = "흠, 이건 아이나르가 보낸 거로군요? 벌써 일주일째 직접 가죽을 가져오지 않고 있는 걸 보니 그 드워프 양반 분명히 아내와 말다툼을 한 게 틀림없군요!\n\n집사람한테 시다에게 얘길 좀 해보라고 해야겠네요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[470] = {title = "가방 찾기", objective = "아이언비어드 고분에 돌아다니는 수액괴물 중 하나가 시다의 가방을 갖고 있습니다. 그 가방을 찾아 메네실 항구의 시다에게 가져가야 합니다.", description = "전 매주 아이언비어드의 고분에 방문하는데 한번은 흉측하고 물투성이 진흙괴물로부터 공격을 받았어요! 전 너무 무서워서 제정신이 아니었답니다.\n\n수액괴물 녀석 중 한 놈에게 가방을 던져 봤지만 가방이 바로 빨려 들어가서 아무 소용이 없었어요! 다행히도 그때를 틈타 도망갈 수 있었죠.\n\n그런데 그 가방에는 제게 꼭 필요한 물건들이 들어 있었어요. 수액괴물들은 전부 똑같이 생겨서 어느 놈에게 던졌는지도 알 수가 없네요! 아이언비어드의 고분은 던 모드르 근처, 이곳에서 북동쪽에 있답니다. 제 가방을 찾아주시면 정말 감사하겠어요!", progress = "제 가방을 찾으셨나요?", completion = "오, 고맙습니다! 영영 잃어버린 줄 알고 얼마나 걱정했는지 모른답니다.\n\n&lt;재빨리 수액투성이 자루를 땅에 쏟고 물건을 다시 집으며&gt;\n\n흠, 제게는 더 이상 필요 없게 된 가방이니까 깨끗이 씻은 후에 사용하시면 되겠네요. 자, 받으세요.", rewards = "다음과 같은 것들을 받습니다:\n\n수액투성이 자루"},
[471] = {title = "수습생의 임무", objective = "거대한 악어 가죽 6개를 모아 메네실 항구의 제임스 할로란에게 가져가야 합니다.", description = "이 지역에는 악명 높은 습지악어가 살고 있습니다. 그 녀석의 가죽을 구해 오라고 수습생을 보냈는데 돌아오지 않기에 찾으러 나가 봤더니... 정말 끔찍한 광경이었습니다.\n\n의사 선생님은 그가 잘 견뎌낼 거라고 했지만, 어쨌든 저는 지금 당장 가죽이 필요합니다!\n\n놈들에 대한 복수라고 생각하고 이 짐승을 몇 마리 더 잡아 주시겠습니까? 해안 북쪽으로 멀록 소굴 너머에 가면 거대한 습지악어를 찾을 수 있을 겁니다.", progress = "제 수습생 녀석은 제게는 아들 같은 아이었습니다. 한쪽 다리로 평생을 살아가는 게 그 아이에게는 굉장히 괴로운 일일 겁니다.\n\n그나저나 가죽은 어떻게 되었나요? 구했습니까?", completion = "흠, 혹시 제 밑에서 수습생으로 일하지 않겠습니까?\n\n하하! 농담이었습니다. 일을 배우기엔 너무 나이가 많으시니 곤란하겠군요. 게다가 당신의 모습으로 보아 인생에 대한 또 다른 포부가 있을 것 같군요. 그건 그렇고, 구해오신 이 질 좋은 가죽은 잘 쓰겠습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n유연한 사슬 다리보호구활력의 판초\n\n다음과 같은 것들 또한 받습니다:\n\n조리법: 악어 검보 스튜"},
[472] = {title = "던 모드르의 함락", objective = "던 모드르 마을 근처에서 롱브레이드를 찾아야 합니다.", description = "던... 모드르가 검은무쇠단 드워프의 손에 들어가고 말았소!\n\n우리 부대는 거의 전멸했고, 나... 난 심각한 부상을 입었지. 검은무쇠단 악당들은 우리가 탄돌 교각의 매복지에서 부대를 재편성하기도 전에 공격해 왔소.\n\n우리 지휘관 롱브레이드님께서는 퇴각 나팔을 불 수밖에 없었소. 우리가 마을에서 후퇴할 때 빗나간 도끼가 내 등에 꽂히고 난 정신을 잃었소.\n\n깨어나 보니 이곳 메네실에 와 있었지만 동료들 걱정으로 마음이 편치 않다오. 아직 난 동료들이 무사하다는 희망이 있소. 롱브레이드님께서 아직 살아 계실지도 모르니, 던 모드르 근처에서 그분을 좀 찾아봐 주시오!", progress = nil, completion = "아니 어떤 용감한 &lt;class&gt;|1이;가; 메네실에서 소식을 전해 왔단 말인가? 아! 자네로군.\n\n할로가 아직 살아 있다니 한 줄기 희망과도 같은 소식이 아닐 수 없군. 할로가 우리가 후퇴할 때 중상을 입었을 때 우리는 유일하게 남아 있던 말에 간신히 태워 보내는 것밖에는 아무것도 할 수 없었네.\n\n그러나 지금 우리는 매우 위험한 상황에 처해 있네. 던 모드르는 함락됐고 한때 무적의 부대였던 우리는 이제 역사 속에 그림자처럼 묻히고 말았다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[473] = {title = "경비대장 스타우트피스트에게 보고", objective = "경비대장 스타우트피스트와 대화해야 합니다.", description = "용아귀부족 오크는 알가즈뿐 아니라 다른 지역까지 공격하고 있소. 그래서 스타우트피스트 경비대장님께서 전투에 참가해 오크와 싸울 지원자들을 모집하라고 하셨소. 생각이 있다면 선장님을 만나보시오. 스타우트피스트 경비대장님은 요새 안에 계시오.", progress = nil, completion = "오, 자네로군. 발스탁이 던 알가즈에서 용아귀부족 오크를 처치했던 자네의 공로에 칭찬을 아끼지 않더군. 자네는 실로 훌륭한 &lt;race&gt;|1이네;네;.\n\n그래서 자네한테 임무를 하나 맡길까 하네만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[474] = {title = "네크로쉬 처치", objective = "족장 네크로쉬를 처치해야 합니다.\n\n그런 다음 그 증거로 경비대장 스타우트피스트에게 네크로쉬의 머리카락을 가져가야 합니다.", description = "투석기를 불태웠으니 이제 족장 네크로쉬를 찾아 처치해야 합니다.", progress = "네크로쉬는 처치했나?", completion = "용감하게 잘 싸웠네. 용아귀부족에게 상당한 타격을 줬으니 이제 회복하기 힘들 걸세. 게다가 투석기도 모두 파괴됐으니 메네실 항구도 이제 안전할 테고 말이야.\n\n자넨 참으로 뛰어난 &lt;race&gt;|1이야;야;. 아이언포지 왕국에서 자네 공로에 합당한 포상을 내릴 것일세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n고대 전투검질주의 도끼\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[475] = {title = "혼란의 바람", objective = "별바람 마을에서 게롤라스 탈베드렌을 찾아야 합니다.", description = "숲에서 혼란의 바람이 불어오고 있소.\n\n게롤라스 탈베드렌은 바네실 지하굴에서 에메랄드의 꿈 속에 잠들어 있는 갈퀴발톱의 드루이드들을 지키고 있소. 게롤라스의 임무는 드루이드들의 안전을 보장하여 이세라와 그들 사이의 계약이 지켜질 수 있도록 하는 것이오.\n\n그런데 최근 게롤라스에게서 연락이 통 오질 않아 초조해지고 있소. 동쪽 별바람 마을로 가서 게롤라스의 보고서를 가지고 오도록 하시오. 우리 동족들이 무사하다는 사실을 확인하고 나면 나도 안심할 수 있을 것이오.", progress = nil, completion = "그대를 여기로 이끌어 준 숲의 정령들에게 감사를! 아스리다스가 문제가 생긴 걸 감지하고 그대를 보내주었군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[476] = {title = "나무옹이일족의 타락", objective = "돌라나르에 있는 아스리다스 베어맨틀에게 돌아가십시오.", description = "나무옹이일족이 오염됐소! 원래는 순한 펄볼그였는데 지금은 숲의 수호자들에게 대항하고 있소. 내가 바네실 지하굴로 가고 있을 때 매복해 있던 그들이 날 공격하고는 별바람 마을을 습격했소. 놈들의 우두머리인 투사 우르살은 악마의 이끼의 사악한 힘을 이용해 나무옹이일족을 광란의 상태로 몰아넣고 있소.\n\n난 부상이 심해 아스리다스에게 이 소식을 직접 전하지 못하오. 이제 그 임무를 당신에게 맡겨야겠소, 젊은 <class>. 미쳐 버린 나무옹이일족이 바네실 지하굴에 아직 도착하지 않았길...", progress = nil, completion = "그래? 정말 큰일이군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[477] = {title = "마법사의 상자", objective = "달라란 마술사의 상자 중 하나의 내용물을 찾아 와야 합니다. 장작나무 마을은 남쪽에서 찾을 수 있습니다.", description = "자네도 알고있다시피 앰버밀 마을에서는 대부분 달라란의 마법사들의 지원을 통해 아직 인간의 저항이 계속되고 있네.\n\n그들의 계획이 무엇인지는 모르겠지만, 앰버밀처럼 고립된 마을에 관심을 보이는 것을 보면 그곳에 뭔가 중요한 것이 있는 것이 틀림없어.\n\n놈들은 힐스브래드에서 마차를 이용해 상자들을 실어 나르고 있네. 상자들의 도착지는 장작나무 마을 북쪽에 있는 작은 야영지인 것 같은데, 자네가 상자의 내용물을 입수해 내게 가져와 주게.", progress = nil, completion = "상자의 뚜껑을 열자 정성들여 포장된 물건들이 잘 정돈되어 있습니다. 상자의 윗부분에는 은빛소나무 숲을 포함한 로데론 서부 지역을 묘사한 빛 바랜 지도 뭉치가 있습니다.\n\n지도 밑에는 신비한 모양의 마법 펜던트가 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[478] = {title = "지도와 룬문자 펜던트", objective = "공동묘지에 있는 어둠의사제 알리스터에게 룬문자 펜던트를 가져가야 합니다.", description = "상자에서 재빨리 펜던트를 꺼내고 뚜껑을 닫습니다.", progress = "뭔가 쓸모 있는 거라도 발견했나?", completion = "지도하고... 이건 펜던트 아닌가? 재미있군.\n\n달라란 마술사들이 무슨 이유에서든 앰버밀에 관심을 가지고 있는 건 확실하군. 하지만 그들의 목적이 무엇인지는 여전히 알 수 없네.\n\n이 물건들이 어디에 쓰이는 것인지, 흠...아! 그렇지 달라라면 뭔가 알고 있을지도 모르겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[479] = {title = "앰버밀 조사", objective = "공동묘지의 어둠의사제 알리스터를 위해 달라란 펜던트 8개를 모야아 합니다.", description = "달라는 그 마법사들이 사용하는 마법의 원천을 찾고 있네. 그리고 지금 우리는 모든 방법을 동원하여 놈들의 계획을 지연시켜야 해.\n\n분명히 마법사와 수호병들이 펜던트를 운반하고 있을 걸세.\n\n그 펜던트를 빼앗아 와야 하네. 길을 따라 남쪽으로 간 다음 길이 갈라지는 곳에서 앰버밀로 이어지는 동쪽으로 가게.", progress = "서둘러야 하네. 그들이 계획을 달성하게 되면 은빛소나무 숲을 빼앗길 수도 있어.", completion = "달라가 알아낸 바로는 우리의 방해에도 놈들이 계획을 상당히 진척시킨 것 같네.\n\n위대한 힘을 가진 마법사가 그 마법의 힘을 통제하고 있다는군. 서둘러 그 마법사를 막아야 하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[480] = {title = "대마법사의 지팡이", objective = "달라란 대마법사 아테릭을 처치하고 그의 지팡이를 공동묘지에 있는 어둠의사제 알리스터에게 가져가야 합니다.", description = "엄청난 마력을 가진 대마법사가 초원 에너지 원천의 부활을 감독하고 있다네. 놈들이 이미 상당한 진척을 이루었으니, 우리에게 남은 길은 그를 처치하여 놈들의 계획을 막는 방법뿐이네. 다른 마법사와 보초병들이 그를 호위하고 있을 테니 어려운 임무가 될 거야.\n\n서둘러 그를 저지하도록 하게. 놈을 처치한 후에 그의 지팡이를 찾아 내게 가져와야 하네. 시간이 없으니 어서 가게나.", progress = "서두르게! 시간이 별로 없어!", completion = "마법사들의 마법이 사라졌으니 초원 에너지도 다시 잠들겠군. 자네 큰 성과를 거두었네. 적들과 저 오만한 달라란의 마법사들에게 결정적인 타격을 입혔어.\n\n하지만 초원 에너지의 원천이 거의 밝혀지게 되었으니 방심해서는 안 되네. 이제 앞으로의 계획을 세워야 할 때야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n세나리움 지팡이위장용 튜닉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[481] = {title = "달라의 분석", objective = "공동묘지에 있는 달라 던위버에게 룬문자 펜던트를 가져가야 합니다.", description = "저기 있는 달라 던위버에게 펜던트를 가져가 보게. 그가 마술사들의 계획을 밝혀낼 수 있을지도 모르네.", progress = "무슨 일이오? 그게 뭐지?", completion = "흥미롭군. 키린 토에서 또 무슨 음모를 꾸미고 있는 것 같은데... 이건 강력한 힘을 가진 물건이오. 키린 토의 강력한 마술사들이 마법의 힘을 모으기 위해 자주 사용하는 물건이지.\n\n그런데 이렇게 많은 양을 앰버밀로 운반하는 걸 보니 뭔가 엄청난 계획을 추진하고 있는 모양이오. 저들의 방어막을 뚫고 숨은 의도를 알아낼 수 있을지 한번 시도해 보도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[482] = {title = "달라란의 의도", objective = "공동묘지에 있는 어둠의사제 알리스터와 대화해야 합니다.", description = "그렇지! 내가 이걸 어떻게 지금까지 까맣게 잊고 있었지?\n\n앰버밀에는 잠자고 있는 초원 에너지의 원천이 있기 때문에 키린 토가 일찌감치 주목하고 있던 지역 중 하나요. 마법사들은 에너지의 중심을 부활시켜 뭔가 더 큰 목적에 그 에너지를 사용하려는 게 틀림없소. 이건 절대 그냥 넘길 수 있는 문제가 아니오.\n\n그 지역의 에너지를 활성화하는데는 엄청난 양의 마법이 필요할 테니 마술사들에게서 펜던트를 빼앗으면 놈들의 계획을 지연시킬 수 있을 것이오. 어서 이 정보를 알리스터에게 전하시오. 그럼 그가 조치를 취할 것이오.", progress = nil, completion = "정말 안 좋은 소식을 가져왔군. 달라의 말이 맞다면, 물론 그가 틀릴 리는 없지만, 서둘러 행동을 취해야겠네.\n\n그와 공격 계획을 상의해야겠군. 그동안 놈들의 계획을 지연시켜야 할 것이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[483] = {title = "깨움의 의식을 위한 재료", objective = "드루이드들을 깨우는 의식에 필요한 재료를 찾아 돌라나르에 있는 아스리다스 베어맨틀에게 가져가야 합니다.", description = "나무옹이일족 침략자들이 서쪽 바네실 지하굴을 습격하고 있는 것이 확인되었소.\n\n우리가 손쓰지 않으면 드루이드들은 자신들의 운명을 의식하지도 못한 채 영원히 에메랄드의 꿈 속에 갇히게 될 거요.\n\n바네실 지하굴로 가서 까마귀 발톱 부적과 검은 깃털, 천상의 사파이어, 그리고 안식의 룬을 찾도록 하시오. 드루이드들은 이 물건들을 신성한 상자에 보관하고 있소. 그것들을 찾아 내게 가져오면 그들을 깨우는 의식을 준비하도록 하겠소.", progress = "바네실 지하굴에서 의식에 필요한 재료를 찾지 못하면 갈퀴발톱의 드루이드들은 영원히 에메랄드의 꿈 속에서 깨어나지 못하게 될 거요.\n\n시간을 지체할수록 그들의 운명은 점점 돌이킬 수 없게 되오.", completion = "성공했구려, 젊은 &lt;class&gt;! 수고했소. 늦지 않아 다행이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n나무껍질 다리보호구기골뿌리 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[484] = {title = "새끼 악어 가죽", objective = "메네실 항구의 제임스 할로란에게 새끼 악어 가죽 4개를 가져가야 합니다.", description = "저는 무두장이 제임스 할로란이라고 합니다. 제가 가공한 악어 가죽은 인기가 많아 여기저기서 주문이 들어오고 있답니다. 제 제품들은 배에 실려 전세계로 배달되기도 하지요.\n\n아이나르를 만나셨죠? 아이나르도 저한테 악어 가죽을 납품하는 사냥꾼 중 하나랍니다.\n\n그런데 요즘 새끼 악어의 부드러운 가죽이 좀 부족합니다. 그러니 새끼 악어 가죽을 구해 주신다면 값을 후하게 쳐 드리겠습니다. 마을 바로 바깥쪽에 있는 습지에 가면 새끼 악어를 찾을 수 있을 겁니다.", progress = "가죽은 구해 오셨나요?", completion = "잘해내셨군요. 오, 아주 훌륭한 최상급 가죽이로군요. 서둘러 가공해야겠습니다. 아, 그 전에 당신께 부탁드릴 일이 하나 더 있습니다만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[485] = {title = "OOX-09/HL 수색", objective = "해골 바위굴 근처, 동부 내륙지의 강이 시작되는 곳에 추락한 오글소프의 유도 로봇에게 조난 탐지기를 가져가야 합니다.", description = "금속으로 만들어진 이상한 알 모양의 장치를 찾았습니다. 손잡이 하나를 만지작거리다 보니 작동이 시작되면서 노움 로봇 장치로 변합니다! 로봇 속에서 소음과 함께 목소리가 들려옵니다.\n\n\"나는 오글소프 오브노티쿠스라고 하는데, 불시착한 내 유도 로봇을 찾아주면 사례를 하겠소. 이 탐지기를 로봇이 있는 곳으로 가져가시오!\"\n\n\"방금 로봇의 현재 위치를 산출해 봤는데 해골 바위굴 근처, 동부 내륙지의 강이 시작되는 곳에 추락한 것 같소!\"", progress = "로봇의 잔해를 찾은 것 같은데 닭... 모양을 하고 있습니다. 알 속에서 다시 목소리가 들려옵니다.\n\n\"잘했소! 그것이 바로 내 유도 로봇이오. 다시 무법항으로 보내 수리를 하려면 급속 시동을 걸어야 할 것 같소. 이 탐지기를 로봇에 넣으시오. 나머지는 탐지기가 알아서 할 테니까!\"", completion = "알을... 아니 조난 탐지기를 닭... 아니 유도 로봇에 넣습니다.\n\n로봇이 윙윙거리는 소리를 내면서 일어서려고 합니다. 로봇이 작동을 하자 오글소프의 목소리가 다시 들려오는 데 이번에는 탐지기가 아니라, 유도 로봇에서 납니다.\n\n\"OOX-09/HL이 시동은 걸리지만 크게 손 봐야 할 것 같소! 당신이 들고 오기에는 너무 무겁지... 잠시만 더 내 로봇을 봐주지 않겠소? 좋은 생각이 한 가지 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[486] = {title = "투사 우르살", objective = "투사 우르살을 처치한 다음 돌라나르에 있는 아스리다스 베어맨틀에게 돌아가십시오.", description = "이제 갈퀴발톱의 드루이드들을 구할 때가 되었소. 지금 실패하면 그들은 영원히 에메랄드의 꿈에서 깨어나지 못하게 되오.\n\n난 재료를 준비한 다음 의식을 거행해 그들을 깨워야 하오. 하지만 그 전에 이 끔찍한 상황을 불러온 그 저주 받을 놈을 반드시 처치해야 하오. 그래야 의식을 완료할 수 있다오.\n\n투사 우르살이 우리 동족들의 소명을 방해했소. 놈이 대가를 치러야 그들이 자유로워질 수 있소. 남서쪽에 있는 나무옹이 요새로 가서 놈을 처치하시오.", progress = nil, completion = "그대는 &lt;class&gt;|1으로서의;로서의; 뛰어난 능력을 보여 주었소. 그대처럼 명예로운 길을 걷고 있는 &lt;race&gt;|1이라면;라면; 언젠가 반드시 이 세상에 영광스러운 날을 가져다주게 될 거라 믿소.\n\n그대의 앞길에 숲의 정령들의 가호가 함께하기를...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n수호자의 도끼가시뿌리 곤봉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[487] = {title = "다르나서스에 이르는 길", objective = "나무옹이일족 복병 6마리를 처치한 다음 돌라나르 외곽에 있는 파수꾼 아마라 나이트워커에게 돌아가십시오.", description = "다르나서스로 이어지는 길은 반드시 안전하게 지켜야 합니다. 돌라나르에서 다르나서스로 가는 여행자들이 오염된 나무옹이일족 펄볼그들로부터 잔인하게 공격 받고 있습니다.\n\n매일 이 길을 통해 중요한 소식이 오고 가고 교역이 이루어집니다. 우리는 이 야만적인 악당들의 위협을 그냥 보고만 있을 수 없습니다.\n\n신성한 숲의 이름으로 무기를 들어야 할 때입니다. 그들의 소굴은 이 고갯길 아래 어딘가에 있습니다. 나무옹이일족 복병 6마리를 처치한 다음 내게 알려 주십시오.", progress = nil, completion = "돌라나르와 다르나서스의 선량한 주민들을 위해 큰 일을 해 주었습니다, 용감한 &lt;class&gt;. 텔드랏실 수호대의 일원으로 그대의 노고에 경의를 표하는 바입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[488] = {title = "젠의 부탁", objective = "돌라나르 외곽에 있는 젠 파울후프에게 흑호 송곳니 3개, 스트리기드 올빼미 깃털 3개, 그리고 나무그물 늑대거미의 거미줄 3개를 가져가야 합니다.", description = "일거리를 찾고 있나 보군. 난 항상 내 명령을 수행할 젊은 <class>들을 찾고 있지. 그런 의미에서 당신이 날 만난 건 행운이야.\n\n나한텐 당신이 아주 탐낼만한 장비들이 많이 있는데 하나쯤 넘겨줄 수도 있어. 하지만 그 전에 몇 가지 물건을 구해와야 하네. 내가 숲에서 하고 있는 일들엔 특별한 재료가 필요한 경우가 많거든.\n\n흑호 송곳니 3개, 스트리기드 올빼미 깃털 3개, 그리고 나무그물 늑대거미의 거미줄 3개를 가져오게.\n\n그리고 이건 우리 둘만 아는 걸로 하세나, <race> 친구.", progress = "그래, 부지런히 재료는 구했나? 필요한 재료를 구해 오기를 기다리고 있었네.", completion = "하하! 잘해 주었네.\n\n&lt;race&gt; 친구가 이 젠 파울후프의 명령을 따르게 될지 누가 알았겠나? 이런 날이 올 줄이야... 이 세상은 정말 놀라움으로 가득하단 말이야.\n\n순진한 애송이의 앞날을 위하여!", rewards = "다음과 같은 것들을 받습니다:\n\n부러진 부두교 발톱"},
[489] = {title = "신뢰의 회복", objective = "악의 열매 3개를 모아 돌라나르 외곽에 있는 젠 파울후프에게 가져다주어야 합니다.", description = "그대가 젠 파울후프를 도왔다는 소식이 원로회에 알려졌어요. 사티로스들은 숲을 해치는 족속들이죠. <race>|1으로서;로서; 그대는 자연의 생명체를 죽여 숲을 모독하는 것이 얼마나 잘못된 일인지 알아야 해요.\n\n텔드랏실의 친구로 남고 싶다면 원로들의 신임을 얻어내야 합니다. 파울후프에게 본때를 보여 준다면 신뢰를 얻을 수 있을 거예요.\n\n악의 열매는 나무에서 떨어지는 오염된 씨앗인데 열매에서 녹색 연기가 피어오르죠.\n\n파울후프에게 열매를 좀 가져다주세요. 아마도 그걸 몸에 해롭지 않은 간식거리로 생각할 테니...", progress = "내게 뭐 줄 거라도 있나? 혹시 맛있는 간식거리라도 가져온건가?", completion = "아, 당신은 정말 착한 &lt;race&gt;|1이야;야;! 나한테 도움이 될 줄 진작에 알았다니까!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[491] = {title = "베소르에게 전할 마법봉", objective = "언더시티의 마법 지구에 있는 베소르 아이스샤드에게 결합된 마법봉을 가져가야 합니다.", description = "쑤울은 아주 오래전에 그와 두 명의 동료가 지니고 있던 수습생 마법봉을 결합하여 마법봉을 만들었다고 말했소. 이 마법봉이 그들에겐 우정의 상징이었던 거였지만 쑤울은 그 마법봉을 하찮게 여기면서도 다른 친구들이 소유하는 것을 원치 않았지. 그래서 그는 마법봉을 훔쳐 바로 이곳 펜리스 요새에 숨겼소.\n\n자, 이 마법봉을 쑤울의 옛 친구 중 한 명인 베소르 아이스샤드에게 가져다주시오. 아마 베소르는 마법봉을 원하고 있을 것이오.", progress = "까마귀 발톱 쑤울을 물리친 건가?", completion = "이건 뭐지? 쑤울에게 우리의 결합된 마법봉이 있었단 말인가? 우리의 우정이 깨지고 그가 리치 왕에게 붙었을 때 이 마법봉도 잃어버렸다고 생각했건만!\n\n하지만 그는 이 마법봉의 힘을 끌어내지는 못한 것 같네. 그랬다면 내가 느꼈을 테니까 말이야. 그가 이걸 사용하지 않은 것이 천만다행이군.\n\n아, 이건 정말 놀라운 발견이야. 정말 고맙네. 내 반드시 보답하도록 하지.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n무늬 바지튼튼한 쇠사슬 장갑톱니 나이프\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[492] = {title = "새로운 역병", objective = "산악경비대 포로에게 요한의 특별조제약을 전해줘야 합니다.", description = "경비병들 말로는 멍청한 드워프 산악경비대원 한 녀석이 잡혀 있다고 하더군. 죽음의경비병들은 포로의 처분이 결정될 때까지 갤로우 선술집 지하실에 가둬 두지.\n\n내가 특별히 준비한 이 음료를 산악경비대 포로가 얼마나 맛있게 마시는지 구경해 보지 않겠소? 이 음료로 말하자면... 음, 어둠의 여왕께서 아제로스를 위해 어떤 일을 계획하고 계신지 암시하는 것이지.", progress = "내 소총만 있었다면 넌 죽은 거나 마찬가지야. 두고 봐. 곧 증기 전차 부대가 도착해서 날 구해 줄 테니!", completion = "오, 마실 것이군. 분명 랩소디 몰트는 아니겠지만 지금은 하도 목이 말라서 뭐라도 들이켜야겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[493] = {title = "힐스브래드 구릉지로의 여정", objective = "힐스브래드 구릉지의 타렌 밀농장에 있는 연금술사 라이던에게 렐퍼럴의 연구 결과를 가져가야 합니다.", description = "왕립 연금술 학회는 어둠의 여왕님의 명령에 따라 새로운 역병을 개발하고 있네. 부단히 연구한 결과 현재 상당한 진척을 이루었네만, 학회 회원들이 정보를 공유한다면 훨씬 더 빨리 개발에 성공할 수 있을 것이야.\n\n그러니 자네가 최근 내 연구 결과를 타렌 밀농장에 살고 있는 연금술사 라이던에게 전해 주게나. 타렌 밀농장은 힐스브래드 구릉지에 자리 잡고 있는 작은 마을이니 아마 긴 여행이 될 걸세. 아래로 내려가 길을 따라 남쪽 방향의 길을 따라 계속 가게. 가다가 표지판을 잘 살펴보고!", progress = "내게 무슨 볼일이라도 있소?", completion = "오, 정말 훌륭하군. 연금술사 렌퍼럴님은 정말 존경할 만한 분이오. 어서 그분의 연구 결과를 살펴봐야겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[494] = {title = "공격 개시", objective = "타렌 밀농장으로 가서 고위집행관 다살리아에게 죽음의추적자 레시의 전갈을 전해야 합니다.", description = "<class>님, 잘 들으세요.\n\n나는 힐스브래드 마을을 조사하기 위해 이곳에 파견되었습니다. 당신이 지금 즉시 타렌 밀농장의 고위집행관 다살리아님께 내 보고를 전해 주어야겠습니다. 고위 집행관님께 죽음의추적자 레시가 다음과 같은 전갈을 전했다고 하면 됩니다.\n\n\"서쪽에서 갈까마귀 울음소리가 손짓하고 있다.\"\n\n표지판을 잘 살펴보면서 동쪽으로 길을 따라가시기 바랍니다. 자, 어서 서두르세요! 매우 시급한 사안이니 지금 즉시 타렌 밀농장으로 떠나야 합니다.", progress = nil, completion = "서쪽에서 갈까마귀 울음소리가 손짓하고 있다고?\n\n멋진 소식이군! 드디어 힐스브래드를 공격할 때가 된 거야. 이제 우리의 함락 계획을 실행할 수 있게 됐군. 바리마트라스님께서 기뻐하시겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[495] = {title = "의지의 왕관", objective = "힐스브래드 구릉지의 타렌 밀농장에 있는 멜리사라에게 보고해야 합니다.", description = "무그톨과 그의 오우거 부대가 실바나스 여왕님을 위해 의지의 왕관을 찾는 임무를 띠고 알터랙으로 떠났었지. 그런데 공교롭게 그 바보 같은 자들이 왕관을 찾아오는 대신에 소유욕에 불타오르고 말았어. 오우거들은 값져 보이는 것만 보면 사족을 못 쓰는 모양이더군.\n\n녀석의 바보 같은 행동이 결국 큰 문제를 일으키고 말았지. 의지의 왕관을 가지려는 욕심 때문에 자신의 직분을 잊고 감히 실바나스 여왕님께 대항했던 것이야.\n\n어둠의 여왕님께서는 그자를 여왕님께 반하는 자들에게 본보기로 삼으려 하고 계시다. 힐스브래드의 타렌 밀농장으로 가서 나의 부관인 멜리사라에게 이 사태를 전하라.", progress = nil, completion = "샬린드라님께서 보내셨다고요? 잘 됐군요. 난 잡담으로 시간을 낭비하는 부류가 아닙니다.\n\n자, 그 눈엣가시 같은 무그톨을 신속하고 깔끔하게 처리하도록 하죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[496] = {title = "괴로움의 비약", objective = "타렌 밀농장에 있는 연금술사 라이던이 회색곰 혀 10개와 이끼거미 수액을 구해다 달라고 부탁했습니다.", description = "아, 타렌 밀농장의 무료한 하루가 또 지나가고 있군. 깨끗한 공기는 내 기분을 망쳐 버린다오.\n\n이제 곧 이곳의 인간들에게 역병을 퍼뜨리게 되면 좀 나아질 거야. 빠르면 빠를수록 좋은데 말이지. 내 조제약에 사용할 만한 독극물에 대해 심도 있는 연구를 계속해 왔지만, 실제로 그 성분들을 모두 모을 만한 시간이 없소.\n\n날 도와줄 생각이라면 회색곰 혀 10개와 아주 귀해서 구하기 어려운 이끼거미 수액을 좀 구해주지 않겠소? 회색곰과 숲이끼거미는 타렌 밀농장 외곽에서 찾을 수 있소.", progress = "다시 돌아왔군. 내게 필요한 재료들을 모두 구해 왔으면 하오. 또다시 죽음 없는 하루를 보내려니 몹시 우울할 거 같군.", completion = "정말 완벽한 재료야. 당신은 오늘처럼 무료한 날에 내게 작은 기쁨을 가져다주는군. 당신의 노고에 감사하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[498] = {title = "포로 구출", objective = "타렌 밀농장에 있는 크루스크가 던홀드 요새에서 드럴과 토그타르를 구출해 달라고 부탁했습니다.", description = "나와 오크 전사 몇 명이 대족장님의 명에 따라 던홀드 요새에서 물건을 찾는 임무를 수행했었소. 그 후 비밀결사대에 대한 조사를 벌이기 위해 이곳까지 파견되었지.\n\n우리는 던홀드 요새를 수색하러 갔다가 많은 수의 인간들에게 습격을 당하고 말았소. 우리는 사력을 다해 싸웠지만 그들의 수가 너무 많아 패하고 말았지. 인간들은 우리들 중 몇 명을 포로로 잡았지만 나는 간신히 탈출했소.\n\n여기서 남동쪽으로 강 건너에 던홀드 요새가 있소. 그곳에 드럴과 토그타르가 잡혀 있으니 가서 꼭 그들을 구출해 주시오.", progress = nil, completion = "그래, 인간들이 우리 전사들을 노예로 만들려 했단 말이오? 놈들에게 본때를 보여 줘야겠군!\n\n놈들이 우리의 수장이신 골디르님을 다른 곳으로 데려간 것 같소. 반드시 그분을 찾아서 구출해야 하오. 하지만 지금 우리는 그분이 어디에 계신지 전혀 모르오.\n\n단서를 찾으면 당신에게 알려 주겠소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n그런트 조끼오크족 전투 사슬 갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n조리법: 큰 곰 스테이크"},
[499] = {title = "괴로움의 비약", objective = "개구리 움피에게 괴로움의 비약을 먹여야 합니다.", description = "이제 이 재료들을 혼합하기만 하면 내가 괴로움의 비약이라 이름 붙인 물질이 곧 완성될 것이오.\n\n자, 보라고! 완성되었어! 이 끔찍한 구릉지에서 무료한 날들을 달래기엔 세상에 작은 고통을 선사하는 것만큼이나 좋은 일도 없지.\n\n그럼, 우리 독약의 효과를 한번 확인해 볼까? 어둠의 여왕님께서 인간과 스컬지를 위해 계획해 온 독약을 내 조수 개구리 움피에게 먹이도록 하시오.", progress = "개굴!", completion = "꾸엑!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[500] = {title = "산사태일족 현상금", objective = "알터랙 산맥에 있는 산사태 오우거에게서 더러운 손가락 뼈 9개를 모은 후 사우스쇼어에 있는 치안대장 레드패스에게 가져가야 합니다.", description = "산사태 오우거들이 폐허가 된 알터랙 도시 근처의 알터랙 산맥에 오우거 소굴을 만들었다네. 그리고 우리 정찰병에 따르면 놈들이 알터랙 폐허까지 점령했다고 하는군.\n\n놈들이 그곳에 진을 치도록 내버려 둘 수는 없네. 일단 그곳을 완전히 차지했다고 생각하면, 우리 진영을 공격하는데 전초 기지가 될 수 있는 구릉지까지 넘볼 것이야!\n\n북쪽의 알터랙 산맥으로 가서 오우거들을 처치해 주게나. 그리고 놈들이 가지고 있는 더러운 손가락 뼈를 가져오면 후하게 보상해 주도록 하겠네.", progress = "아직도 오우거를 처치하지 못했나? 내가 부탁한 손가락 뼈는 모아 왔나?", completion = "아주 잘했네. 이 더러운 손가락 뼈를 모으려고 오우거 무리를 한바탕 헤집고 다녔겠군그래.\n\n자네가 수고한 덕분에 놈들이 우릴 귀찮게 하지 않겠군. 적어도 한동안은 말이지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[501] = {title = "고통의 비약", objective = "타렌 밀농장에 있는 연금술사 라이던에게 산사자 피 10병을 가져가야 합니다.", description = "오, 힐스브래드에는 꽃이 만발하고 공기는 청명하고 상쾌하지. 하지만 난 이런 환경 속에서는 견딜 수가 없다니까. 지저분한 창으로 밖을 내다보면서 우리가 만든 새로운 역병이 이 세상에 합당한 죽음과 질병을 퍼뜨리게 될 날을 간절히 바란다오.\n\n내가 하루종일 자리에 앉아 생각하기를 좋아하는 만큼 어둠의 여왕님께서 부여하신 임무를 완수하고 싶은 욕구도 커지지.\n\n나를 좀 도와주겠소? 내 연구 결과, 산사자 피로 가장 효과적인 죽음의 혼합물을 만들 수 있다는 결론에 도달했소. 내게 산사자 피를 좀 가져다준다면 우린 새로운 재미를 찾을 수 있을 것이오.", progress = "아, 당신이로군. 내 마지막 비약 만드는 걸 도와주기로 하지 않았소? 힐스브래드에 거주하는 놈들에게 내가 특별히 제조한 고통을 선사하려면 그 피가 꼭 필요하오.", completion = "훌륭해!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n완력의 장갑투박한 가죽 장화불꽃 장화\n\n다음과 같은 것들 또한 받습니다:\n\n조리법: 매운 사자 고기"},
[502] = {title = "고통의 비약", objective = "스탠리에게 고통의 비약을 먹여야 합니다.", description = "아, 이 구릉지에서 신선한 피 냄새보다 좋은 향기는 없지!\n\n이제 재료들을 조금씩 섞기만 하면 정말 재미있는 일이 시작되는 것이오! 이 피로 만든 나의 멋진 작품을 고통의 비약이라 부르도록 하겠소. 내 계산이 정확하다면 이 혼합물은 실바나스 여왕님을 위해 매우 유용하게 사용될 것이오. 하지만 먼저 시험을 해 봐야지.\n\n이 비약을 남서쪽에 있는 힐스브래드 농장의 북쪽 집앞에 가져가도록 하시오. 과연 농부 레이의 애견 스탠리가 내 작품을 좋아하는지 어디 한번 보자고.", progress = "으르렁...", completion = "손에 비약을 조금 따라 스탠리의 입에 가져갑니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[503] = {title = "골디르", objective = "골디르를 구출하여 타렌 밀농장에 있는 크루스크에게 돌아가야 합니다.", description = "당신이 입수한 문서에 따르면 골디르님은 아마 북쪽의 알터랙 산맥에 있는 대규모의 비밀결사대 기지에 잡혀 있을 거요. 그분은 너무 오랫동안 포로로 잡혀 계셨으니 반드시 구해 내야 하오.", progress = "날 구하러 온 겐가? 그럼 열쇠를 가져다주시게, <class> 친구. 그럼 내가 직접 자물쇠를 열도록 하지.", completion = "고맙네. 난 대족장님의 명령으로 듀로타에서 정찰대를 이끌고 왔지만, 보다시피 우리 계획은 어긋나고 말았네. 놈들은 나를 이 마을에 잡아 두고는 짐을 운반하거나 땅을 파는 등의 강제노역을 시키더군.\n\n하지만 내가 겪은 고통은 중요하지 않소. 당신이 현재 우리 정찰대를 이끌고 있는 이에게 전해 주어야 할 중요한 정보가 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[504] = {title = "산사태일족 전사", objective = "산사태일족 전사 15마리를 처치한 다음 사우스쇼어에 있는 치안대장 레드패스에게 돌아가십시오.", description = "이제 산사태 오우거에 대해서는 자신이 있을 터이니, 놈들의 코를 납작하게 눌러 버릴 차례일세.\n\n알터랙 폐허로 가서 산사태일족 전사들을 찾게나. 자네가 놈들을 많이 처치해야만 그 짐승 같은 놈들이 얼라이언스의 지역을 넘보지 못하게 될 걸세.", progress = nil, completion = "정말 잘했네. 자, 여기 보상금일세.\n\n전사들을 처리하는 동안 알터랙 도시의 상태는 좀 살펴보았나? 내 생각엔 매우 좋지 않을 것 같네만... 오우거들은 청결의 청자도 모르는 놈들이니까 말이야.\n\n고맙게도 자네 노력 덕분에 놈들을 사우스쇼어에서 몰아내게 되었군그래.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n불타는 은마법봉달의 버클러\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[505] = {title = "비밀결사대 암살자", objective = "비밀결사대 노상강도 12명과 비밀결사대 도둑 8명을 처치한 다음 사우스쇼어에 있는 집정관 헨리 말레브에게 돌아가야 합니다.", description = "나는 얼마 전 암살된 전임 집정관의 후임으로 임명된 사우스쇼어의 새 집정관일세. 암살자들을 찾아내진 못했지만, 조사한 바에 의하면 그들은 비밀결사대에서 고용한 자들이 거의 확실하네. 비밀결사대는 지금은 멸망한 알터랙 왕국의 귀족들이 이끄는 도둑 떼라네.\n\n지금까지 발견한 단서에 따르면 비밀결사대들은 호드 영역에 속해있는 타렌 밀농장 북쪽에 있는 야영지에 숨어 있는 것 같네. 그곳으로 가서 눈에 띄는 비밀결사대 일당들을 처치해 주게.", progress = nil, completion = "고맙네. 그 자들이 아직도 살아남아 어딘가에 숨어 있을지도 모르지만, 자네가 처치한 도둑과 노상강도 중에 전임 집정관의 죽음과 관련된 자가 있기를 바라네. 뭐, 그들이 아니더라도 비밀결사대는 인간에게 암적인 존재이니 이 땅에서 없어져야 하겠지만 말이야. \n\n그들이 사라졌으니 사우스쇼어에서 환호해 마지 않을 것이네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n십자군 허리띠은둔자의 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[506] = {title = "블랙무어의 유산", objective = "타렌 밀농장에 있는 크루스크에게 골디르가 수집한 정보를 전해야 합니다.", description = "며칠 전, 비밀결사대의 우두머리가 날 찾아왔었네. 앨리덴 페레놀드란 자인데, 자기가 이 땅의 주인이라고 하더군. 그자는 자신에게 저항하는 오크들을 노예로 삼을 계획이라고 털어놓았네. 그의 아버지이자 스승인 저주스러운 블랙무어가 계획했던 것처럼 말이야.\n\n더 중요한 사실은 그가 엘리사라는 이름의 가녀린 부인을 함께 데려왔다는 점이야. 그녀의 목에 대족장님께서 원하시는 펜던트가 걸려 있었네.\n\n자, 이제 난 여기서 볼일을 끝낸 후에 내갈 길을 가야겠으니 어서 이 소식을 전하도록 하게.", progress = nil, completion = "뻔뻔하고 오만한 인간들 같으니! 우리 오크를 놈들의 뜻대로 할 수는 없다는 걸 똑똑히 보여 줘야 해!\n\n이제 이것이 우리의 사명이오. 물론 대족장님께서 원하시는 장신구도 되찾아야 하고 말이오. 어쨌든 이 중 하나를 완수하면 나머지 하나도 저절로 해결될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[507] = {title = "앨리덴 페레놀드 경", objective = "앨리덴 페레놀드 경을 처치하고 그의 부인 엘리사에게서 타레사의 펜던트에 대해서 물어봐야 합니다.", description = "반드시 앨리덴 페레놀드를 처치하여 더 이상 악행을 일삼지 못하도록 해야 하오. 그의 영지는 여기서 북쪽 방향에 있는 로다미어 호수 근처에 있소. 임무를 완수한 후 대족장님께서 원하시는 펜던트를 찾아 이곳으로 돌아오시오.", progress = "워...원하는 게 뭐죠?", completion = "제발... 절 해치지 마세요! 난 당신들을 해치려 한 적 없어요. 그저 내 의지와 상관없이 남편의 뜻대로 할 수밖에 없었던 것뿐이라고요. 제발... 목숨만은 살려 주세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[508] = {title = "타레사의 선물", objective = "타렌 밀농장에 있는 크루스크에게 타레사의 펜던트를 돌려줘야 합니다.", description = "펜던트 말인가요? 그거라면 기꺼이 드리지요... 자, 가져가세요! 그에 대한 추억은 더 이상 간직하고 싶지 않으니까... 다만 제발 아무 소란도 일으키지 말고 가 주세요...", progress = "오! 돌아왔군. 그래, 좋은 소식을 가져온 거요?", completion = "대족장님께서 이런 하찮은 물건에 왜 그리 집착하시는지 알다가도 모를 일이군. 뭐, 나야 그분의 뜻이 무엇이든 명령을 따를 뿐이지만 말이오. 잘했소. 당신이 세운 공적에 대해 대족장님께서도 분명 기뻐하실 게요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n사마귀 장화약탈자의 어깨갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[509] = {title = "죽음의 비약", objective = "타렌 밀농장에 있는 연금술사 라이던에게 진흙주둥이꽃 6개를 가져가야 합니다.", description = "이제 곧 새로운 비약이 완성될 것이오. 나 같으면 저 불쌍한 인간과 스컬지들이 끝까지 싸우도록 내버려두겠는데... 안 그래도 놈들은 서로 싸울 기세니까 말이오.\n\n아아, 하지만 우리 어둠의 여왕께서는 저들의 멸망을 좀 더 앞당기길 원하시니, 이 암울한 시기에 약간의 죽음과 역병을 퍼뜨린다고 해도 문제될 건 전혀 없지 않겠소?\n\n우리 계획은 이러하오. 당신이 타렌 밀농장의 남쪽, 강과 사우스쇼어의 동쪽에 있는 네산더 농장으로 가서 진흙주둥이꽃 6송이를 모아오면 새 비약을 만들도록 하겠소.", progress = "네산더 농장에서 소득은 있었소?", completion = "으, 진흙주둥이꽃의 악취는 역시 지독해. 굼벵이도 구르는 재주는 있다더니 저 고약한 놀들도 쓸만한 재주가 있군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n신속의 물약치유 물약"},
[510] = {title = "불길한 예감이 드는 계획서", objective = "사우스쇼어에 있는 집정관 말레브에게 불길한 예감이 드는 계획서를 가져가야 합니다.", description = "이 문서들 중에 보급품 요청 목록이 있습니다. 그 목록에는 식량, 무기, 의류 등 평범한 물품 외에도 가면, 기름, 독 등 특이한 물품이 포함되어 있습니다.\n\n하지만 가장 중요한 점은 보급품 요청이 상당히 긴급하다는 사실입니다. 이 물품은 '사우스쇼어 공격 일급 작전'이라 이름 지어진 작전을 시작하기 위해 곧 사용될 예정입니다.", progress = "자네 뭔가 걱정거리가 있는가 보군. 내게 무슨 할 말이라도 있나?", completion = "&lt;말레브가 문서를 읽으며&gt;\n\n이건 심각한데... 이 문서의 정보와 최근 비밀결사대의 움직임으로 미루어 볼 때, 이 살인 집단이 사우스쇼어와 전쟁을 벌이려는 게 분명하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[511] = {title = "암호화된 편지", objective = "사우스쇼어에 있는 현자 딥스에게 복잡하게 암호화된 편지를 가져가야 합니다.", description = "탁자 위에 있는 편지 중 하나는 암호로 쓰여 있어 내용을 알 수 없습니다.", progress = "무슨 일이시오? 내게 무슨 볼일이라도 있소?", completion = "이게 대체 뭐요? 잠깐, 한번 살펴봐야겠군.\n\n...\n\n흠, 처음 보는 형태의 암호인데... 난 아무래도 이 분야의 지식이 좀 부족한 것 같소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[512] = {title = "지휘부 처치", objective = "사우스쇼어에 있는 집정관 말레브에게 알터랙 인장 반지 7개를 가져가야 합니다.", description = "비밀결사대의 지휘부가 사우스쇼어 함락에 혈안이 되어 걱정이네. 놈들이 계획을 실행에 옮기기 전에 놈들의 지휘부에 결정타를 안겨야 하네.\n\n북쪽 알터랙 산맥에 있는 스트란브래드의 폐허로 가 보게. 비밀결사대가 그 지역을 본거지로 삼고 있는 것 같네.\n\n그리고 예전 알터랙의 귀족들이 이 살인 집단을 이끌고 있다는 사실도 이미 밝혀졌다네. 지휘부는 아마 일반 비밀결사대 일당들과 똑같은 모습을 하고 숨어 있겠지만, 놈들이 끼고 있는 인장 반지로 구별이 가능할 걸세.\n\n그 인장 반지들을 내게 가져다주게.", progress = "비밀결사대 지휘부는 어떻게 됐나? 놈들의 반지는 가져왔나?", completion = "비밀결사대의 지휘부들을 제거했으니 놈들의 작전 수행 능력도 형편 없어질 테고, 이제 그저 단순한 불한당 무리에 불과하겠군.\n\n얼라이언스를 위해 큰 일을 해 주었네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[513] = {title = "죽음의 비약", objective = "언더시티에 있는 수석 연금술사 파라넬에게 진흙주둥이 합성물을 가져가야 합니다.", description = "아무 낙 없이 또 하루가 지나간다고 여기던 차에 당신이 내게 멋진 진흙주둥이꽃을 가져다주었군.\n\n자, 그럼 먼저 꽃송이들을 잘 섞어 질 좋은 합성물을 만든 다음에... 언더시티에 계신 수석 연금술사 파라넬님의 부패 콜로이드 용액을 섞기만 하면 아주 재미있는 일이 일어날 것이오.\n\n자, 이 진흙주둥이 합성물을 즉시 수석 연금술사 파라넬님께 전하도록 하시오.", progress = "내가 지금 바쁘게 일하는 게 안 보이나, <class>? 어둠의 여왕님께서 스컬지가 노스렌드로부터 우릴 공격해 오기 전에 새로운 역병을 개발하라고 재촉하고 계시네. 게다가 남쪽에선 인간들이 압박해 오고 있으니 지금 내겐 시간이 금쪽같아. 그러니 중요한 일이 아니라면 돌아가게!", completion = "연금술사 라이던이 보냈다고? 왜 진작 말하지 않았나!\n\n성격이 좀 우울한 친구이긴 하지만 라이던은 가장 헌신적이고 능력 있는 회원 중 한 명이지.\n\n그 기특한 친구가 진흙주둥이 합성물을 보냈군그래! 힐스브래드에서 지금 뭘 하고 있는지 알겠군. 그 친구 생각하는 게 마음에 든단 말이야. 어둠의 여왕님께서도 새 역병 연구에서 그가 이룬 진척에 만족하실 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[514] = {title = "스톰파이크에게 보내는 편지", objective = "아이언포지에 있는 발굴조사단장 스톰파이크에게 복잡하게 암호화된 편지를 가져가야 합니다.", description = "아이언포지에서 일하고 있는 내 동료가 아마 이 편지를 해독할 수 있을 거요. 아이언포지에 있는 탐험가의 전당에 있는 도서관으로 가서 발굴조사단장 스톰파이크를 만나 보시오. 그에게 내가 보냈다고 말하고 편지를 보여 주시오. 검은바위 첨탑의 북부에서 이 편지를 읽을 수 있는 이가 있다면 그건 틀림없이 그 친구밖에 없을 거요.", progress = "사우스쇼어의 딥스가 보냈다고? 그 나이든 책벌레께서는 잘 지내고 계신가?", completion = "오, 암호로군! 이거야말로 내 전문이지. 어디 한번 볼까...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[515] = {title = "죽음의 비약", objective = "타렌 밀농장에 있는 연금술사 라이던에게 진흙주둥이 혼합물, 강한 재생의 물약, 비수가시일족의 비늘 5개, 그리고 너덜지느러미일족의 눈 5개를 가져가야 합니다.", description = "진흙주둥이 합성물이라... 정말 훌륭한 발상이군! 왜 진작 이 생각을 못했을까? 내 부패 콜로이드를 이 악마의 혼합물에 섞어야겠네.\n\n이 진흙주둥이 혼합물의 독성을 활성화하려면 라이던에게 강한 재생의 물약, 그리고 힐스브래드 남쪽 해안에서 구할 수 있는 비수가시일족의 비늘과 너덜지느러미일족의 눈이 필요할 걸세. 자네가 이 실험 재료만 모두 구해다 주면 그가 알아서 할 거야. 이거, 하루빨리 그의 실험 결과를 듣고 싶군!", progress = "다시보니 반갑군. 당신이 없는 동안 무료해서 죽을 지경이었소. 움피에게 독과 병균을 주입했다가 다시 소생시키는 것 외에는 소일거리가 전혀 없으니... 계속 그것만 반복하고 있었소.\n\n언더시티로 간 일은 어떻게 됐소? 가는 길에 운 좋게도 우연히 인간을 처치할 기회는 없었소?", completion = "이 실험은 나를 정말 들뜨게 하는군! 당신 도움이 정말 컸소. 이제 우리가 함께 이 땅에 죽음과 질병을 퍼뜨리게 될 것이오!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n상급 연금술사의 망토명상의 장식띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[516] = {title = "베렌의 동굴", objective = "베렌의 동굴에서 까마귀발톱 노역꾼 6명과 까마귀발톱 수호병 6명을 처치하고 공동묘지에 있는 어둠의사제 알리스터에게 돌아가야 합니다.", description = "리치 왕의 언데드 무리가 우리를 공격하기 위해 숨어서 준비하고 있다는 보고가 들어왔네. 이 정보를 무기로 우리가 먼저 공격하여 허를 찌르면 놈들의 공격을 미리 방지할 수 있을 걸세.\n\n하지만 안타깝게도 내 정보에도 허점이 있어. 놈들은 베렌의 동굴이라는 곳에 숨어 있다고 하네. 정확한 위치는 알 수 없지만, 달라란 마술사들 본거지 근처의 언덕에 있는 동굴 중 한 곳에 숨어 있을 가능성이 크지.\n\n자네의 기지를 발휘해서 놈들을 찾아서 처치해 줄 걸로 믿네.", progress = nil, completion = "우리 정찰병과 요원들이 중요한 정보를 계속 입수해 준다면 곧 우리 땅에서 리치 왕의 스컬지를 몰아낼 수 있을 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n부패의 마법봉"},
[517] = {title = "죽음의 비약", objective = "타렌 밀농장에 있는 연금술사 라이던에게 신디거 스타우트 맥주통을 가져가야 합니다.", description = "드디어 이 새로운 비약을 시험해 볼 준비가 됐소. 하지만 하찮은 개구리나 개에게 이 강하고 훌륭한 역병을 낭비할 필요는 없겠지? 그보다 실바나스 여왕님의 이름으로 진정한 실험의 재미를 맛보도록 하지.\n\n던 가록으로 가시오. 저 고약한 드워프들의 병영이 어디 있는지는 알고 있겠지? 놈들의 신디거 스타우트 맥주통을 훔쳐다 주시오. 그러면 나와 함께 신나는 죽음의 향연을 구경할 수 있을 것이오.", progress = "나는 이곳 타렌 밀농장의 생활이 너무 따분하게 느껴질 때면 포름알데히드 병을 열어 그 기분 좋은 향기를 공기 중에 퍼뜨리곤 하지. 그럴 때면 움피는 잔뜩 겁을 먹는다오.\n\n그건 그렇고, 드워프들에게서 맥주통은 훔쳐 왔소? 이 치명적인 비약을 아무에게도 사용해 보지 못하고, 하루라도 더 기다려야 한다면 난 비명을 지르게 될 것이오.", completion = "오, 드디어! 이제 준비는 다 끝났군!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[518] = {title = "의지의 왕관", objective = "타렌 밀농장에 있는 멜리사라를 위해 산사태일족 싸움꾼 14마리를 처치해야 합니다.", description = "무그톨과 그의 산사태 오우거들이 알터랙 폐허를 짓밟아 왔습니다. 하지만 오우거의 수를 줄이지 않고는 무그톨을 단죄하기 힘들 거예요.\n\n그러니까 먼저 놈들의 전력을 약화시킨 후에 작전을 진행해야 합니다.\n\n알았나요? 자, 어서 가보도록 하세요.", progress = nil, completion = "눈 위에 붉은 꽃이 가득 피었군요. 오우거 몇을 쓰러뜨리는 데 성공하긴 했지만 산사태일족과 그들의 혼을 짓밟아 저 눈밭에 파묻기 전까지는 공격을 멈출 수 없습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[519] = {title = "의지의 왕관", objective = "타르그, 무크라케, 글롬무스를 처치하고 그 증거로 그들의 머리카락을 타렌 밀농장에 있는 멜리사라에게 가져가야 합니다.", description = "타르그, 무크라케, 그리고 글롬무스는 무그톨의 부관입니다. 무엇 때문인지는 모르지만, 이 오우거들은 나름대로 무그톨에게 충성을 다하고 있습니다.\n\n이 부관들을 모두 처치한 후 그 증거를 가지고 돌아오세요. 그런 다음 남는 일은 무그톨을 제거하고 그의 왕관을 빼앗은 다음 나머지를 모두 없애는 것뿐이겠지요.", progress = "변명은 필요 없어요. 내가 원하는 건 놈들을 처치했다는 증거뿐이에요.", completion = "우리의 멋진 계획이 시작됐다고 역겨운 오우거 머리 냄새가 말해주는군요.\n\n무그톨의 머리카락까지 가져오면 네 개의 머리카락 다발을 창에 묶어 알터랙 산맥 높은 곳에 걸어둬야겠어요. 어둠의 여왕님의 뜻을 거스르는 녀석들에게 좋은 경고가 될 테니까요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[520] = {title = "의지의 왕관", objective = "무그톨을 처치하고 그 증거로 그의 머리카락과 의지의 왕관을 타렌 밀농장에 있는 멜리사라에게 가져가야 합니다.", description = "무그톨의 부관들을 처치했으니 이제 무그톨을 처치하고 의지의 왕관을 가져오는 일만 남았군요. 틀림없이 쉽게 왕관을 내놓지는 않을 겁니다. 그 일당들이 사라졌으니 아마 무그톨도 당신이 올 거라고 예상하고 있을 겁니다.\n\n무그톨을 찾아서 처치하세요. 그런 다음 그의 머리카락과 의지의 왕관을 가져오세요. 산사태일족의 저항도 이것으로 종지부를 찍게 될 겁니다.", progress = "머리카락 세 다발은 손에 넣었고, 이제 네 번째 머리카락이 필요합니다. 무그톨의 머리카락을 가져오지 않으면 네 번째 주인공은 당신이 될 거라 내 약속하죠!", completion = "임무를 잘 완수했군요. 나머지 산사태일족 잔당들은 죽음의경비대가 쓸어버릴 겁니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[521] = {title = "의지의 왕관", objective = "언더시티에 있는 샬린드라에게 의지의 왕관을 가져가야 합니다.", description = "이제 의지의 왕관을 언더시티에 계신 샬린드라님께 가져가기만 하면 되는군요. 그러면 실바나스 여왕님께 왕관을 전해 드릴 겁니다. 경고하겠는데 무그톨과 같은 꼴을 당하고 싶지 않다면, 사사로운 목적으로 왕관을 이용할 생각은 안 하는 게 좋을 겁니다.", progress = "무슨 일이지? 뭔가 보고할 거라도 있나?", completion = "그러니까 이게 바로 오우거가 어둠의 여왕님의 뜻을 거스르면서 사용했던 유물이로군그래.\n\n이렇게 평범한 물건이 그런 하찮은 놈들 손에 들어가서 그런 큰 힘을 발휘할 수 있다니 신기한 일이야. 수고했네. 왕관을 실바나스 여왕님께 전해 드리고 당신의 공적에 대해 보고하도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n정기의 부적"},
[522] = {title = "청부업자의 계약서", objective = "사우스쇼어에 있는 집정관 말레브에게 청부업자의 계약서를 가져가야 합니다.", description = "집정관 헨리 말레브 암살 계약서입니다. 이 암살 계약서는 독특한 인장 반지가 찍힌 붉은 밀랍으로 봉인되어 있습니다.", progress = "숨을 헐떡이는 걸 보니 꽤 급한 일인가 보군. 그래, 뭔가 보고할 거라도 있나?", completion = "&lt;계약서의 내용을 확인하는 집정관 말레브.&gt;\n\n흠, 이제야 놈들이 지난번 사우스쇼어를 공격한 이유를 알겠군. 비밀결사대 놈들이 전임 집정관이 그랬던 것처럼 나를 암살하려는 거야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[523] = {title = "바르두스 남작 심판", objective = "바르두스 남작을 처치하고 그 증거로 그의 머리카락을 사우스쇼어에 있는 집정관 말레브에게 가져가야 합니다.", description = "자네가 발견한 계약서는 한때 알터랙 왕국의 귀족이었으나 잔인한 짓을 일삼는 냉혈한으로 알려진 바르두스 남작이 서명한 것이네. 바르두스 남작 같은 자가 배후에 있다는 건 이상할 것도 없는 일이지.\n\n자네가 그자를 찾아서 정의의 이름으로 심판을 해 주게나. 그자는 스트란브래드의 폐허나 그 북쪽의 계곡에 있는 것으로 파악되는 비밀결사대 소굴에 있을 걸세.", progress = "바르두스 남작이 우리의 심판에 대항해 사우스쇼어로 일당을 보내지 못하도록 해야 하네. 어서 놈의 머리카락을 가져와 주게!", completion = "고맙네. 그 악당이 없어졌으니 이제 나는 좀 안전하겠군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[524] = {title = "죽음의 비약", objective = "오염된 맥주통을 사로잡힌 농부들이 있는 방의 양탄자 위에 가져다 놓아야 합니다.", description = "옆 건물에 죽음의경비병들이 사로잡힌 농부들을 인질로 감금해 놓고 있소. 고위집행관 다살리아님께서는 그 포로들 가운데 스톰윈드의 군사 전략가 중 하나가 숨어 있다는 것을 알아채셨지. 그런데 그 군사 전략가 녀석이 어젯밤 역병지대에서 죽은 채로 발견된 모양이오. 항상 날 배려해 주시는 다살리아님께서 이 포로들을 내 손에 맡기셨소.\n\n그러니 이제 그 농부 녀석들에게 죽음의 파티를 선사할 때요. 옛 영광이 다시 찾아온 것 같지 않소?\n\n이 오염된 맥주통을 녀석들이 수감된 방의 양탄자 위에 가져다 놓으시오. 모두 이 역병 맥주를 맛보기를!", progress = "양탄자에서 곰팡이 냄새가 납니다.", completion = "먼지투성이인 양탄자 위에 오염된 맥주통을 놓습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[525] = {title = "깊어지는 의문", objective = "사우스쇼어에 있는 집정관 말레브에게 해독된 편지를 가져가야 합니다.", description = "편지를 해독했지만 무슨 뜻인지는 잘 모르겠군. 이 편지를 알터랙 구릉지대에 있는 도적들에게서 발견했다고 했소? 정말 이상해...\n\n이걸 사우스쇼어의 집정관께 가져가시오. 비록 이 편지 내용이 모호하기는 하지만 사우스쇼어가 알터랙에서 가장 가까운 마을이니, 혹시 위험한 일이 발생할 조짐이 있는 거라면 사우스쇼어의 집정관이 알고 있어야 할 테니까 말이오.", progress = "구릉지와 산을 지나 먼 길을 다녀온 겐가? 그래. 어떤 소식을 가져왔나?", completion = "&lt;편지를 읽는 말레브.&gt;\n\n이것이 자네가 비밀결사대 야영지에서 발견한 편지를 해독한 내용이라고? 이건 도적이 쓴 것도 아니고, 알터랙의 귀족이 쓴 것도 아닐세.\n\n아무래도 비밀결사대가 제 3의 세력과 연합한 것 같네. 생각만 해도 끔찍하군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[526] = {title = "라이트포지 주괴", objective = "라이트포지 주괴 5개를 모은 다음 저습지에 있는 글로린 스틸브로우에게 돌아가야 합니다.", description = "그 상자에서 발견한 라이트포지 주괴 하나만으로는 쓸만한 물건은 만들 수 없네.\n\n그러니 그곳으로 다시 가서 좀 더 찾아 와야 할 거야. 아마 그 난파선 주위에 있는 멀록들이 라이트포지 주괴를 가지고 있을 걸세.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[527] = {title = "힐스브래드 전투", objective = "힐스브래드 농노 6명, 힐스브래드 농부 6명, 그리고 농부 레이와 농부 게츠를 처치한 다음 타렌 밀농장에 있는 다살리아에게 보고해야 합니다.", description = "나와 말을 할 때는 항상 정신 바짝 차리게, <class>.\n\n나는 바리마트라스님의 직속 부관이네. 우리는 연금술사들이 새로운 역병을 개발할 수 있을 때까지 인간들의 침입을 저지해야 하는 임무를 띠고 있지.\n\n정보에 따르면 힐스브래드 마을의 방어가 취약한 것 같더군. 자네의 첫 임무는 놈들의 식량 공급 및 기반 시설을 차단하는 것이야.\n\n서쪽으로 가서 힐스브래드 농장 북쪽에 있는 농장들을 공격하고, 토지 소유주인 농부 레이와 농부 게츠도 처치하네.", progress = nil, completion = "편히 쉬도록, &lt;class&gt;. 전투를 치르고 돌아온 모양이군. 자네가 힐스브래드 전선에서 아주 잘 싸웠다는 보고를 받았지, 수고했네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[528] = {title = "힐스브래드 전투", objective = "힐스브래드 소작농 15명을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다.", description = "북쪽 농장이 공격당했다는 소식으로 인간 마을 주민들이 공포에 떨고 있다더군. 아주 훌륭해.\n\n죽음의추적자의 보고에 따르면 소작농들이 힐스브래드 남쪽 농장으로 피난하고 있다는군. 바보 같은 놈들이 과수원으로 숨으면 안전할 거라 생각하는 모양이야.\n\n가서 놈들이 얼마나 어리석은지 일깨워 주고 오라고. 힐스브래드 농장으로 돌아가서 숨어 있는 농부들을 찾아내도록 하게. 그리고 우리 어둠의 여왕님의 이름으로 놈들을 처단하도록.\n\n이상!", progress = nil, completion = "힐스브래드 마을에 죽음의 그림자가 점점 가까워지고 있군그래. 아주 성공적이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[529] = {title = "힐스브래드 전투", objective = "대장장이 베링턴과 힐스브래드 견습대장장이 4명을 처치해야 합니다.\n\n철괴 상자를 찾은 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고하십시오.", description = "예상치 못한 상황이 발생했네. 힐스브래드의 인간들이 저항을 꾀하고 있는 모양이야. 마을의 대장장이가 힐스브래드 주민들에게 무기를 공급하고 있는 것 같으니 모든 무기 공급선을 차단해야 하네.\n\n자네의 임무는 대장장이 베링턴을 처치하는 것이야. 놈의 수습생들도 함께 처치하고 그곳에 있는 동안 철괴 상자를 가지고 오는 것도 잊지 말도록 하게. 그 보급품은 우리가 힐스브래드를 점령한 후 사우스쇼어 공격을 감행할 때 유용하게 사용할 수 있을 거야.", progress = "명령을 완수했나, <class>? 베링턴과 그의 조무래기들은 처치한 겐가? 그리고 철괴 상자는 어디 있나?", completion = "능숙하게 임무를 완수했군. 아주 잘했네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[530] = {title = "랠리의 복수", objective = "발드레드 모레이를 처치해야 합니다.\n\n그 증거로 언더시티에 있는 랠리 앤드리언에게 발드레드의 장갑을 가져가야 합니다.", description = "한때 나의 좋은 친구였던 발드레드가 내 아내를 살해했소. 이제 더 이상 슬퍼할 수는 없지만 복수에 대한 욕망만은 가득하오. 당신이 그 저주받을 발드레드를 처치하게 되면 그 증거를 가져오시오. 내 그러면 보상해 주겠소.\n\n내가 마지막으로 들은 바에 따르면 그는 은빛소나무 숲 남부의 그레이메인 성벽에서 길니아스 왕국으로 달아나려 하고 있다고 했었소.", progress = "놈의 장갑은 가져왔소?", completion = "오, 이것으로 내 아내를 살해한 놈이 이 세상에서 사라졌군. 그녀의 죽음에 대한 복수만이 나의 유일한 관심사였는데, 당신이 이루어 준 것이오.\n\n자, 일전에 당신이 되찾아 준 이 반지를 받으시오. 델리아가 죽은 지 너무 오래되었기에 이제 더 이상 그녀의 반지는 가지고 있고 싶지 않소. 대신 내 친구의 배신을 똑똑히 기억할 수 있도록 이 장갑을 보관할 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n냉소의 반지"},
[531] = {title = "바이린의 복수", objective = "순찰자의 오두막에 있는 바이린 스위프트윈드에게 늙은곰 수티의 머리를 가져가야 합니다.", description = "그런 물건은 순찰자의 오두막에 가지고 오지 마시오... 불결해, 오금이 저릴 정도로... 재수 없고... 역겹다고!\n\n제발 가지고 나가요. 그런 끔찍한 건 아무도 보고 싶어하지 않을 테니까. 진짜!", progress = "잘했어요! 다릴이 입도 뻥긋 못하게 만들었군요! 그 머리를 주세요. 제가 가지고 있겠어요.", completion = "저를 도와 줘서 고마워요. 그 거만한 허풍쟁이에게 복수하기 위해 몇 달을 별러 왔는데 결국 멋지게 한 방 먹였네요! 자, 이거 받으세요. 수고에 대한 답례예요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n사냥용 탄환 주머니사냥용 화살통\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[532] = {title = "힐스브래드 전투", objective = "집정관 번사이드와 힐스브래드 원로 5명을 처치해야 합니다. 힐스브래드 선언문을 파괴하고 힐스브래드 마을의 기록부를 빼내 와야 합니다. 그런 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고하십시오.", description = "힐스브래드 마을이 혼란에 빠졌으니 이제 곧 함락될 것이야. 하지만 구릉지에서 쓰레기 같은 인간들이 영원히 제거될 때까지 공격의 고삐를 늦춰서는 안 되네.\n\n인간들에게 압승을 거두긴 했지만 이들이 지휘부를 중심으로 재집결하여 저항을 계속하고 있어. 이들을 지휘하고 있는 집정관 번사이드와 마을 의회의 원로를 제거해야 하네. 또한 그들이 하늘같이 떠받드는 성명문인 힐스브래드 선언문도 파괴해 버리고, 힐스브래드 마을의 기록부를 빼내 오도록.", progress = "임무는 어떻게 됐나?", completion = "벌써 힐스브래드에서 자네가 세운 공적에 대한 소문이 자자하더군. 잘했네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[533] = {title = "침투", objective = "타렌 밀농장에 있는 크루스크를 위해 골디르가 어디에 있는지 정보를 찾아야 합니다.", description = "마침내 골디르님이 잡혀 계신 곳에 정보와 증거가 입수되기 시작했소. 인간들이 그분을 여기저기로 끌고 다니고 있지만, 수색 범위를 좁혀 여기서 바로 북쪽에 있는 대규모의 비밀결사대 야영지까지 압축되었소.\n\n그곳으로 가서 정보를 수집해 주시오.", progress = "뭔가 찾아낸 게 있소? 골디르님의 상황이 점점 악화되는 것 같아 걱정이오.", completion = "드디어 골디르님이 잡혀 있는 곳을 알아냈군. 문제의 그 야영지는 이곳에서 그리 멀지 않소. 이번에는 놈들이 처음 우리를 잡았을 때만큼 전열이 다듬어진 상태가 아니어야 할 텐데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[535] = {title = "발릭", objective = "비밀결사대 야영지에 있는 발릭에게 사우스쇼어의 스타우트 맥주 한 잔을 가져가야 합니다.", description = "으... 부상으로 다 죽어가는 마당에 적까지 만나는군.\n\n어쨌든 당신은 날 죽이겠지만, 그 전에 당신네 종족이 마시는 사우스쇼어 스타우트 맥주를 좀 가져다준다면 당신이 원하는 정보를 주겠소.", progress = "술을 가져온 거요, 아니면 날 끝장내려고 다시 온 거요?", completion = "죽음을 앞두고 마시는 이 술 한 잔은 지금껏 맛본 그 무엇보다 달콤하군... 자, 이걸 받으시오. 내가 죽은 뒤에는 아무 쓸모 없을 테니...\n\n잘 사용하도록 하시오!", rewards = "다음과 같은 것들을 받습니다:\n\n비밀결사대 신서"},
[536] = {title = "해안의 위협", objective = "사우스쇼어에 있는 부관 파렌 오리넬이 너덜지느러미멀록 바다사냥꾼 10마리와 너덜지느러미멀록 점쟁이 10마리를 처치해달라고 부탁했습니다.", description = "스톰윈드 근위병에서 사우스쇼어 같은 촌구석으로 전출되다니... 밤낮으로 항구의 비린내가 진동하는 이런 곳으로 말이오.\n\n저 늙은 대장 레드패스에 대해서는 말도 꺼내지 마시오. 날더러 멀록을 상대하라니. 하! 기가 차서... \n\n난 서부 해안에 있는 저 거대한 변종 물고기 주머니 속에 제 발로 걸어 들어갈 생각은 없단 말이오. 그래서 말인데, 당신이 내 대신 가서 놈들을 좀 처치해 준다면 정말 고맙겠소.", progress = nil, completion = "이걸로 내가 레드패스의 명령에 따라 사우스쇼어에서 저 끔찍하고 두려운 멀록을 제거해 버린 것으로 보여야 할 텐데 말이오. 사실 저 거대한 변종 물고기의 공격보다 더 지독한 것도 없을 거요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[537] = {title = "어둠의 의회", objective = "아르거스 재림회 어둠마법사 4명을 처치해야 합니다.\n\n그리고 나가즈를 처치한 증거로 그의 머리카락을 사우스쇼어에 있는 집정관 헨리 말레브에게 가야 합니다.", description = "자네가 가져온 편지는 아르거스 재림회 회원인 나가즈라는 자가 작성한 것이라네. 나도 아르거스 재림회가 어떤 조직인지는 모르지만, 비밀결사대와 연합했다면 위험한 조직이 틀림없네. 자네가 편지에 언급된 나가즈와 아르거스 재림회 어둠마법사를 찾아서 처치해 주게나.\n\n비밀결사대의 세력이 가장 강한 지역인 고원을 수색해 보게. 스트란브래드 북쪽으로 가면 되네.\n\n운이 따라 준다면, 거기서 아르거스 재림회의 사절을 찾을 수 있을 게야.", progress = "아르거스 재림회의 사절들을 찾아냈나?", completion = "수고했네. 아르거스 재림회 같은 조직이 비밀결사대를 조종해서는 안 되지.\n\n자네가 놈들의 우두머리인 나가즈를 처치했긴 하지만, 나가즈도 다른 누군가의 명령을 따르는 하수인일 뿐이네. 아르거스 재림회는 동부 왕국 곳곳에서 활동하고 있는 것 같네.\n\n아니면 전 세계를 무대로 하고 있는지도 모르지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[538] = {title = "사우스쇼어", objective = "사우스쇼어에 있는 현자 딥스와 대화해야 합니다.", description = "혹시 긴 여행도 마다하지 않으신다면 제가 스톰윈드 도서관의 장서를 다시 보충하기 위한 일을 부탁 드렸으면 합니다.\n\n대전쟁 이후 멸망한 옛 알터랙 왕국에는 방대한 양의 장서가 있었답니다. 그 도시가 멸망해 버린 것도 비극이지만 더 큰 비극은 그 방대한 지식이 모든 소실되었다는 것입니다! 우리는 최대한 그 지식을 복원해 내야 합니다.\n\n사우스쇼어는 알터랙의 폐허에서 가장 가까운 마을이랍니다. 그곳으로 가서 현자 딥스를 만나 보십시오. 그가 알터랙 폐허로 가는 길과 거기서 어떤 책을 찾아야 할지를 알려 줄 겁니다.", progress = nil, completion = "아, 그래. 밀턴이라면 기억하지. 정말 지독한 책벌레라오. 그에게 축복이 있기를...\n\n그의 말이 맞소. 알터랙 폐허에는 아직도 많은 양의 지식이 사라져 버릴 위험에 노출된 채 방치돼 있소!\n\n지금 알터랙에는 오우거들이 살고 있는데 그 녀석들은 수준 높은 학식에는 도통 관심이 없지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[539] = {title = "힐스브래드 전투", objective = "현장감독 본즈와 힐스브래드 광부 10명을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다.", description = "힐스브래드 마을의 기록부를 보면 청금석 광산이 얼라이언스 손에 넘어간 것으로 되어 있군. 게다가 그 광산은 얼라이언스의 무기 생산에 필요한 철 광석의 주공급원이지.\n\n힐스브래드 마을에 결정적인 타격을 주긴 했지만, 여전히 얼라이언스는 청금석 광산을 철저히 방어하고 있는 실정이야.\n\n청금석 광산은 힐스브래드 남쪽 방향에 있네. 광산으로 가서 본즈라는 인간 현장감독을 처치하도록 하고 그가 지휘하는 광부들도 함께 처치해야 해. 이번 작전으로 얼라이언스에 커다란 타격을 줄 수 있을 걸세.", progress = nil, completion = "어둠의 여왕님의 전사들의 무기 제조를 위한 원료 공급원이 될 광산을 새로 점령한 사실을 알게 되면 여왕님께서 매우 기뻐하실 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[540] = {title = "지식 보존", objective = "되찾은 학술서 5권과 그리렉의 팔이 들어 있는 낡은 가죽 책을 사우스쇼어에 있는 현자 딥스에게 가져가야 합니다.", description = "저 짐승 같은 오우거들이 지금 알터랙 폐허를 점령하고 있으니 아직 거기 남아 있는 귀중한 책들을 어떻게 할지 정말 걱정이오. 당신이 구할 수 있는 대로 그 책들을 되찾아 줬으면 하오!\n\n알터랙 폐허로 가서 오우거 놈들이 약탈해 간 책들을 찾아봐 주시오. 가능한 많은 책들을 찾아서 내게 가져오되, 반드시 찾아야 할 책이 한 권 있소. 바로 '그리렉의 팔'이라는 책이지. 거기에는 내가 꼭 알아야 할 고대 트롤의 지식이 수록돼 있는데, 세월의 흔적에도 손상되지 않은 사본이 알터랙의 폐허에서 마지막으로 발견되었소.", progress = "내가 직접 폐허를 수색하고 싶지만 저 산을 오르다가는 내 뼈가 성치 않을 것이오. 그건 그렇고, 책은 찾았소?", completion = "오, 찾아냈군! 정말 훌륭하오! 당장 그리렉의 팔에 대한 연구를 시작해야겠소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[541] = {title = "힐스브래드 전투", objective = "던 가록으로 가서 던 가록 산악경비대 10명, 던 가록 소총병 8명, 던 가록 사제 4명과 부대장 아이언힐을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다.", description = "드워프가 인간을 돕고 있다고? 괘씸한 꼬마 짐승들 같으니!\n\n얼라이언스라는 놈들의 전력을 한번 시험해 볼 필요가 있겠군. 우리의 보복에도 그 조그마한 녀석들이 계속 인간을 돕는지 한번 지켜보자고. 이 지역 내에 있는 드워프 놈들의 본거지는 이미 파악되었네.\n\n녀석들은 힐스브래드 남동부에 있는 소라딘의 성벽 주위의 던 가록이라는 지역에 병영을 설치했지. 이번 전투에서 자네의 마지막 임무는 던 가록을 포위 공격하는 것이야. 놈들을 지휘하고 있는 부대장 아이언힐을 반드시 처치하도록 하게.", progress = nil, completion = "전장에서 보여준 자네의 활약상은 최고의 찬사를 받을 만하군그래.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[542] = {title = "밀턴에게 돌아가기", objective = "스톰윈드에 있는 밀턴 시프에게 알터랙의 학술서를 가져가야 합니다.", description = "자네가 찾아다 준 이 그리렉의 팔을 연구하는데는 시간이 좀 걸릴 것이오. 그동안 나머지 책들을 밀턴에게 전해 주지 않겠소? 틀림없이 그는 나머지 책들을 다시 스톰윈드 장서에 넣길 고대하고 있을 거요.\n\n여기, 당신이 알터랙 폐허에서 모아 온 책들을 포장하고 그 목록을 작성해 두었소. 이 책들을 스톰윈드에 있는 밀턴 시프에게 다시 가져다주면 매우 고마워할 것이오.", progress = "오! 다시 돌아오셨군요. 알터랙 수색은 어떻게 됐습니까? 뭔가 찾아 오셨나요?", completion = "오, 이런! 이 책들을 좀 보십시오! 알터랙의 폐허 속에서도 이 책들이 남아 있었다니, 정말 믿기지 않습니다. 더구나 오우거들이 그곳을 점령한 와중에 말입니다!\n\n고맙습니다. 정말 고맙습니다! 선생께서는 인류의 지식을 보존하는데 기여했을 뿐 아니라 스톰윈드 왕실 도서관의 위상을 한층 더 드높이는데 일조하신 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[543] = {title = "페레놀드 티아라", objective = "스톰윈드에 있는 레밍턴 리지웰에게 페레놀드 티아라를 가져가야 합니다.", description = "오, 자네로군. 내 자네에게 맡길 일이 하나 있어 기다리고 있던 참일세.\n\n자네 페레놀드 티아라라고 들어봤는가? 페레놀드 티아라는 알터랙 왕국이 폐허가 되기 전에 알터랙을 다스렸던 페레놀드 귀족 가문의 오래된 가보일세. 아이언포지의 보석 세공 장인이 만들었다고 전해지며 최고의 에메랄드가 박혀 있지.\n\n알터랙이 파괴될 때 티아라도 사라졌지만 최근에 오우거 마법사, 욕심쟁이 그렐볼그가 발견했고 현재 또 다른 보물을 찾아 알터랙 폐허를 방황하고 있다고 하는데 말이야.\n\n자네가 우리를 위해 그 티아라를 찾아 왔으면 하네.", progress = "잘 지내나. 내 바지를 밟지 않도록 조심하게. 새로 맞춘 의상이니까 말이야.", completion = "오, 멋지군그래. 물론 깨끗하게 닦아야겠지만 의외로 일을 훌륭히 처리했군. 사람을 시켜 이 티아라를 닦은 후 우리 가문의 소장품에 추가해야겠네.\n\n자네도 동의해 주겠지? 보상은 충분히 해줄 테니 말일세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[544] = {title = "감옥 습격", objective = "배반자들을 찾아내 유물을 되찾은 다음 타렌 밀농장에 있는 학자 워딘 보이드글레어에게 돌아가야 합니다.", description = "난 원래 연구 목적으로 타렌 밀농장에 왔지만 우선 당면 위기의 해결이 급선무요. 반드시 이 문제를 해결해야 하니 잘 듣도록 하시오.\n\n당신도 알다시피 몇 달 전 포세이큰 네 명이 우릴 배신하고 언더시티를 빠져나갔소이다. 놈들은 우리를 배신한 것뿐 아니라 어둠의 여왕님께서 지니신 뭔가를 훔쳐 가기까지 했지. 이 지독한 배반자들이 비밀 금고에 침입해 연금술사들의 연구에 쓰이는 4개의 유물을 훔쳐 간 것이오. 실바나스님을 위해 그 유물들은 반드시 되찾아야 하오.\n\n그 도둑들은 언더시티를 탈출해 달라란으로 도망갔는데, 마법사들이 그들을 로다미어 포로수용소에 격리 수용해 두었다고 하오.", progress = "도둑놈들을 찾아냈소? 아, 그보다 그들이 훔쳐 갔던 물건들을 찾아 왔소?", completion = "포세이큰을 위해 큰 일을 해 주었군. 이 유물들은 매우 귀한 것들이지.\n\n그리고 케간과 다른 배반자들이 정의의 심판을 받게 되었으니 이보다 더 기쁜 일이 어디 있겠소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[545] = {title = "달라란 순찰", objective = "달라란 소환사 6명과 노예 바위 정령 12마리를 처치한 다음 타렌 밀농장에 있는 학자 워딘 보이드글레어에게 돌아가야 합니다.", description = "달라란의 마법사들이 시가지 중심부에 거대한 마법의 반구를 만들었소. 이 난세에 자신을 보호하기 위해 만들었다고 하는 이도 있고, 그저 세상과 떨어져 연구와 구상에 몰두하기 위한 것이라 말하는 이도 있지.\n\n나야 뭐 이유에는 관심도 없지만... 내 관심은 반구가 아니라 그 폐허가 된 도시 외곽에 귀중한 마법의 보물이 숨겨져 있을지도 모른다는 사실이야.\n\n하지만 마법사들과 그들의 하수인인 노예 바위 정령들이 그 지역을 순찰하고 있다오. 그러니 당신이 그들을 처치해서 놈들의 숫자를 줄이고 내게 다시 돌아와 주시오.", progress = nil, completion = "정말 잘했군. 이제 조금만 주의하면 안전하게 그 폐허를 수색할 수 있을 거요. 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[546] = {title = "죽음의 전리품", objective = "타렌 밀농장에 있는 죽음의경비병 삼사가 힐스브래드 주민의 해골 30개를 가져다 달라고 부탁했습니다.", description = "당신이 다살리아님을 도와 힐스브래드에 있는 인간과 전쟁을 벌였다고 들었습니다. 정말 부럽군요...\n\n인간을 처치하고, 마을을 약탈하고, 또 죄 없는 주민을 공포에 떨게 하고... 당신이 그런 재미를 보는 동안 나는 이곳 타렌 밀농장에 처박혀 경비나 서고 있었단 말입니다.\n\n아마 당신은 나처럼 늙은 죽음의경비병을 불쌍히 여겨 주겠지요? 보다시피 난 인간의 해골을 모으고 있습니다. 당신은 앞으로도 오랫동안 인간들과 싸우게 될 테지요. 그 긴 전투 기간 동안 해골 30개를 모아 준다면 합당한 대가를 지급하도록 하겠습니다.", progress = "행운아 <name>님께서 돌아오셨군요? 자, 오늘은 얼마나 많은 인간을 처치했습니까? 수백 명은 되겠죠!\n\n그나저나 내게 줄 해골은 가지고 왔나요?", completion = "아, 이 소중한 해골들! 정말 아름답지 않나요? 자, 내가 약속했던 보상입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n해골 반지"},
[547] = {title = "험버트의 검", objective = "던 가록에서 죽음의경비병 험버트의 검을 되찾아 타렌 밀농장으로 돌아와 험버트에게 검을 돌려줘야 합니다.", description = "고위집행관 다살리아님께서 던 가록을 정찰하라고 나를 보냈셨습니다. 물론 위험한 곳이라 너무 가까이는 가지 말라고 하셨죠. 난 놈들의 가시거리 밖에서 최대한 근접한 곳에 야영지를 설치했습니다. 그리고 아침이 밝자 물을 끓이기 위해 땔감을 구하러 야영지를 떠났었습니다. 야영지에 돌아와 보니 내 장비들이 보이지 않았습니다.\n\n아무래도 던 가록에서 온 드워프 정찰병 녀석들이 지나가다 내 야영지를 발견하고 가져간 것 같습니다. 다른 건 몰라도 내 검을 꼭 찾아야 합니다! 내 검을 되찾아 주신다면 정말 고맙겠습니다. 던 가록엔 드워프들이 워낙 많아서... 내 검을 가져간 녀석을 찾기가 꽤 어렵긴 하겠지만요.", progress = "내 검은 되찾았나요? 고위집행관 다살리아님께서 이 사실을 아시게 되면 지붕 들보에 내 목을 매다실 겁니다.", completion = "찾았군요!\n\n아, 내 일부나 마찬가지인 이 소중한 검을 다시 찾게 되어 얼마나 기쁜지 모릅니다. 정말 고맙습니다!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n골진 흉갑용병의 다리보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[549] = {title = "비밀결사대원 현상수배", objective = "비밀결사대 도적 10명과 비밀결사대 경비병 10명을 처치해야 합니다. 그런 다음 타렌 밀농장에 있는 고위집행관 다살리아에게 돌아가 보상금을 받으십시오.", description = "실바나스 여왕의 권한으로 비밀결사대라는 조직의 모든 대원을 처치할 것을 명한다. 더불어 이미 구금 또는 수감 중인 해당자는 즉결 처형될 것이다. 이들은 현재 타렌 밀농장 남동쪽에 있는 던홀드 요새의 폐허에 집결해 있는 것으로 파악되고 있다.\n\n위의 범죄자를 처치한 증거를 고위집행관 다살리아에게 가져오는 이에게는 후한 보상금이 지급될 것이다.", progress = nil, completion = "훌륭하군. 이 정도라면 곧 비밀결사대 놈들을 이 땅에서 완전히 몰아낼 수 있겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[550] = {title = "힐스브래드 전투", objective = "언더시티에 있는 바리마트라스에게 다살리아의 봉인된 추천서를 가져가야 합니다.", description = "힐스브래드 전투에서 보여준 자네의 용기와 불굴의 의지에 대해 추천서를 작성해 두었네. 자네의 영웅적인 활약상에 대한 찬사를 아끼지 않았으니 지휘부에서도 자네를 인정해 줄 거야.\n\n자, 이 봉인된 추천서를 언더시티에 있는 바리마트라스님께 가져가도록 하게. 자네가 자랑스럽군!", progress = "무슨 일로 전장에 있어야 할 <class>|1이;가; 언더시티까지 온 것인가?", completion = "그래, 그대가 힐스브래드 구릉지의 얼라이언스에게 결정적인 타격을 주었다는 그 악명 높은 &lt;class&gt;인가? 그대의 대단한 공적에 대한 소문은 벌써 이곳 언더시티에도 자자하지.\n\n전장에서 계속 뛰어난 지도력과 능력을 보여 준다면 앞으로 어둠의 여왕님께서 높은 지위를 얻게 해주실 거야.\n\n우리에게 가장 큰 위협이 되고 있는 것은 북쪽에서 공격해 오고 있는 리치 왕의 스컬지 군대이지만, 인간들도 계속 우리 전투 계획에 지장을 주고 있는 것이 사실이지. 그런데 바로 그대가 이 인간들을 몰락시킬 수 있다는 걸 보여 준 게야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n성지의 바지죽은해골 방패룬문자 암흑검\n\n다음과 같은 것들 또한 받습니다:\n\n언더시티의 반지"},
[551] = {title = "마법의 양피지", objective = "사우스쇼어에 있는 현자 딥스에게 마법의 양피지를 가져가야 합니다.", description = "이 양피지는 마법이 걸려 있어 판독이 불가능합니다. 그러나 양피지의 맨 위에 있는 하나의 단어는 읽을 수 있습니다.\n\n\n 나가즈\n\n", progress = "오. 내게 뭐 보여 줄 거라도 있소? 산 위에서 새로운 무엇이라도 찾아 온 거라면 좋겠소만...", completion = "암호 문서를 또 발견했단 말이오?\n\n알터랙에서 발견되고 있는 기이한 문자들을 모두 판독할 능력이 내게 있으면 좋겠지만 그러기엔 내 지식이 부족하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[552] = {title = "헬쿨라의 복수", objective = "설인에게서 헬쿨라의 마법봉을 되찾아 타렌 밀농장에 있는 수련사 사이반드에게 가져가야 합니다.", description = "헬쿨라님께서 마술사로의 변신을 거의 마쳤을 때 인간 폭도 일당이 언덕에서 의식을 행하는 장소를 발견하고 그분을 잔인하게 죽여버렸습니다. 그것도 모자라 그분의 시체를 사우스쇼어 묘지에 묻어 버렸지 뭡니까.\n\n그분과 같은 위대한 마법사님께 그따위 짓을 하다니 절대로 용서할 수 없습니다. 그분의 수습생으로서 사우스쇼어 마을에 반드시 복수하고 말겠어요!\n\n복수를 위해서는 먼저 헬쿨라님의 마법봉이 필요해요. 그런데 지금은 의식을 행하는 장소를 설인이 점령해 버렸답니다. 틀림없이 놈들 중 하나가 마법봉을 가지고 있을 테니 가져다주세요.", progress = "헬쿨라의 마법봉은 되찾았나요? 이 지역엔 설인이 너무 많아서 아마 찾기 힘들 거예요. 하지만 복수를 위해서는 꼭 찾아야만 합니다.", completion = "찾아냈군요! 정말 훌륭합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[553] = {title = "헬쿨라의 복수", objective = "헬쿨라의 마법봉에 아젤의 불꽃, 베라즈의 불꽃, 우젤의 불꽃의 마력을 불어넣어야 합니다.\n\n힘을 불어넣은 마법봉을 사우스쇼어에 있는 헬쿨라의 무덤으로 가져가야 합니다.", description = "자, 헬쿨라의 마법봉이 필요할테니 받으세요.\n\n헬쿨라님은 그의 가장 강력한 주문에 사용할 의식용 불꽃 3개를 만드셨습니다. 그 중 아젤의 불꽃과 베라즈의 불꽃은 구릉지 동굴에 있고 우젤의 불꽃은 그보다 위, 산에서 북쪽으로 더 들어간 곳에 위치한 동굴에 있죠.\n\n헬쿨라의 마법봉에 이 세 불꽃 모두로부터의 힘을 불어넣어야 해요. 모든 의식이 끝나면 마법봉을 사우스쇼어에 있는 헬쿨라의 무덤으로 가져가야 해요. 무덤은 남쪽에 있는 사우스쇼어에 있는데 그곳은 경계가 삼엄한 인간 마을이에요. 무슨 일이 있어도 반드시 복수를 해야 해요!", progress = "헬쿨라의 무덤은 신비한 기운으로 가득 차 있습니다.", completion = "땅에서 엄청나게 큰 소리가 납니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[554] = {title = "스톰파이크의 판독", objective = "아이언포지에 있는 발굴조사단장 스톰파이크에게 마법의 양피지를 가져가야 합니다.", description = "암호 해독이나 판독이라면 발굴조사단장 스톰파이크만한 전문가도 없을 것이오. 당신이 발견한 양피지를 가져가 보시기 바라오. 운이 좋으면 스톰파이크가 해독할 수도 있을 테니 말이오. 스톰파이크는 지금 아이언포지에 있는 발굴조사 본부에서 연구 중이오.\n\n그를 만나면 내가 보냈다고 하시오. 최근에 내가 그에게 일거리를 많이 보내 주었다오.", progress = "또 누가 날 방해하는 것이오?\n\n아, 이 양피지는 매우 난해하면서도 정교하게 짜 맞춰진 주문들로 가득하군. 물론 해독할 수는 있지만, 시간이 좀 걸릴 거요. 내게 시간은 금쪽보다도 귀하오이다....\n\n아마도 당신에게 시간을 벌어야겠군?", completion = "현명한 결정이오. 난 나 이외에 다른 학자가 이 두루마리를 해석할 수 있다곤 생각치 않소. 만약 담겨진 내용이 흥미로운 것일지라도 염려 마시오. 당신에게 보내주겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[555] = {title = "독특한 거북이 비스크", objective = "사우스쇼어에 있는 주방장 예센에게 거북이 고기 10개와 독특한 양념을 가져가야 합니다.", description = "사우스쇼어 하면 빼놓을 수 없는 것이 바로 스톰윈드 북부 지역에서 최고를 자랑하는 요리랍니다! 저만의 비법으로 만드는 거북이 비스크도 그 중 하나라 할 수 있지요. 오로지 제 요리를 맛보기 위해 멀리 다크샤이어에서 이곳까지 오는 이들도 있을 정도랍니다.\n\n그런데 요즘은 통 거북이 비스크를 만들 수가 없었어요. 전엔 달라란을 지나 로다미어 호수까지 가서 직접 무쇠턱거북을 사냥하곤 했는데, 지금은 너무 위험해서 원 갈 수가 있어야지요. 북쪽 지역에 있는 무쇠턱거북의 거북이 고기와 독특한 양념을 구해다 주시면 금방 거북이 비스크를 만들어 드리도록 하죠.", progress = "재료는 다 구해 오신 건가요? 이곳은 더 이상 예전처럼 평화로운 곳이 아니니 조심해야 할 겁니다. 아, 이렇게 상황이 불안하지만 않았어도...", completion = "주방장 예센의 독특한 거북이 비스크를 다시 맛보게 됐으니 모두 기뻐할 겁니다!", rewards = "다음과 같은 것들을 받습니다:\n\n조리법: 독특한 거북 비스크독특한 거북이 비스크"},
[556] = {title = "징표의 돌", objective = "타렌 밀농장에 있는 관리인 벨바릴에게 닳아해진 징표의 돌 10개를 가져가야 합니다.", description = "달라란 마법사들은 정령을 다루는 데 탁월한 재주가 있습니다. 그 정령들은 다른 차원에서 온 강력한 존재들입니다. 마법사들은 징표의 돌을 사용하여 정령들을 조정하고 있습니다. 학자 보이드글레어님께서 아마 이 돌들을 좀 연구하고 싶어하실 겁니다.\n\n힐스브래드 서쪽에 달라란 마법사의 땅으로 들어가서 징표의 돌을 모은 다음 내게 가져오십시오.\n\n그 지역 내에 있는 달라란 주민에게서도 돌을 얻을 수 있겠지만, 달라란보다는 안전한 로다미어 포로수용소로 가는 게 좋을 겁니다.", progress = "닳아해진 징표의 돌은 가져왔습니까? 보이드글레어님께서는 그 비밀을 밝혀낼 날을 고대하고 계십니다.", completion = "이거면 충분하겠군요. 징표의 돌이 마법의 힘을 잃은 것 같긴 하지만 보이드글레어님의 실험에는 이런 표본이 오히려 더 낫겠지요. 고맙습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[557] = {title = "결속의 팔보호구", objective = "타렌 밀농장에 있는 관리인 벨바릴에게 대지 결속의 팔보호구 4개를 가져가야 합니다.", description = "보이드글레어님께서는 지금 당신이 수집한 징표의 돌을 조사하느라 바쁘실 겁니다. 하지만 곧 대지 결속의 팔보호구도 필요하실 겁니다. 팔보호구는 정령들이 마법사에게 충성을 바치도록 하기 위해 정령의 손목에 채우는 물건입니다.\n\n달라란의 폐허에서 정령들을 찾아 그들의 대지 결속의 팔보호구를 모아 오도록 하십시오. 아마 보이드글레어님께서 매우 기뻐하실 겁니다.", progress = "어서 오십시오. 정령들을 다루는 것이 힘든 일이기는 하지만 당신이라면 충분히 해낼 수 있을 것 같은데... 결속의 팔보호구는 가져왔습니까?", completion = "오! 가져 왔군요. 정령들에게서 이 팔보호구를 빼앗는 거야 식은 개죽 먹기 아니었습니까? 흠... 죽음은 내 심장만 멈추게 한 것이 아니라 유머 감각까지 앗아간 모양이군.\n\n어쨌든 고맙습니다. 보이드글레어님뿐만 아니라 나아가 어둠의 여왕 폐하를 위해 큰 일을 해 주었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[558] = {title = "제이나의 사인", objective = "돌보고 있는 고아를 위해 테라모어로 가서 여군주 제이나 프라우드모어의 사인을 받아야 합니다.", description = "사람들이 테라모어에 계시는 제이나 프라우드모어님은 얼라이언스 최고의 영웅 중 한 분이라던데요. 저도 이 다음에 커서 얼라이언스의 영웅이 되고 싶어요!\n\n제이나님을 아세요? 저, 부탁 한 가지만 들어주실래요? 제이나님의 사인 좀 받아주실 수 있으세요? 제가 제이나님께 음... 무슨 말씀을 드려야 할지도 모르겠고 저 같은 꼬맹이한테 시간을 내줄 만큼 한가하진 않으실 테니까요... 하지만 <형이라면/누나라면> 들어주실 거예요! <형/누나>도 그분 같은 모험가잖아요! <형이라면/누나라면> 금방 사인을 해 주실 거예요!\n\n들어주실거죠?", progress = "언젠가는 저도 꼭 제이나님 같은 영웅이 되고 싶어요... 전 건장한 남자 영웅이 되겠지만요.", completion = "우와! 대단해요! 제이나님의 사인을 받아오셨군요! 정말로 감사합니다! 우와... 여기다가 와... 저한테 글도 써 주셨어요! 전 제이나님이 진짜 멋진 분일 줄 알았다니까요. 언젠가 얼라이언스의 영웅이 되면 그분께 직접 감사하다고 말할 수 있을 거예요!\n\n형은 정말 최고예요. 이렇게 잘해주셔서 정말 고맙습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[559] = {title = "파렌의 증거물", objective = "사우스쇼어에 있는 부관 파렌 오리넬에게 서부 해안에서 멀록을 처치하고 멀록 머리 10개를 모아야 합니다.", description = "이건 정말 말도 안 되지 않소? 레드패스가 지난번 우리가 처치한 멀록만으로는 만족하지 않고 있다니 말이야. 오, 그렇다고 겸손해 할 필요는 없소. 당신의 활약은 정말 대단했으니까... 레드패스가 이번에는 멀록을 처치한 증거로 차갑고 끈적끈적한 멀록 머리를 가져와서 승인을 받으라고 하고 있다오. 당신이 좀 도와주시오.", progress = "멀록 머리는 가져왔소?", completion = "오! 정의의 이름으로... 이런, 바닥에 물이 떨어지는군.\n\n으, 이걸 내 손으로 만져야 하다니... 물고기야 괜찮지만, 거기에 다리가 나고 걸어다니기까지 하면... 그거 아시오? 물고기 말고는 당최 먹을 게 없는 사우스쇼어에서 지난 몇 주 동안 물고기를 한 마리도 못 먹었소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[560] = {title = "파렌의 증거물", objective = "사우스쇼어에 있는 치안대장 레드패스에게 멀록 머리가 든 자루를 전달해야 합니다.", description = "난 도저히 이 멀록 머리를 못 가져가겠소. 어차피 이미 이 머리들에 손을 댄 김에 당신이 내 대신 이것들을 레드패스에게 좀 전해 주지 않겠소?", progress = "어서 오시게. 사우스쇼어의 안전을 위해 지원하려고 왔는가?", completion = "파렌의 심부름꾼인가?\n\n멀록을 처치하는 걸 도왔다니 고맙게 생각하네. 사우스쇼어를 안전하게 지키기 위해서는 충실한 일꾼과 많은 노력이 필요하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[561] = {title = "파렌의 증거물", objective = "사우스쇼어에 있는 부관 파렌 오리넬과 대화해야 합니다.", description = "부관 파렌 오리넬에게 이번에는 동부 해안에 출몰하고 있는 나가를 처리하는데 전념하라고 전해 주게나. 그리고 성과가 있을 때는 직접 와서 보고하라고 하게.", progress = nil, completion = "나가를 처리하라고? 레드패스도 내가 입수한 정보를 이미 알고 있는 모양이군. 하! 그가 내 덕에 승진하는 꼴은 절대 못 보지, 암! 무슨 말인지 설명해 주겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[562] = {title = "아, 스톰윈드!", objective = "사우스쇼어에 있는 부관 파렌 오리넬을 위해 비수가시일족 바다사냥꾼 10마리와 비수가시일족 세이렌 10마리를 처치해야 합니다.", description = "스톰윈드 근위병 시절 내 스승이었던 분이 얼라이언스 총사령관께서 나가의 위협 때문에 염려하고 계시다는 전갈을 보내 오셨소. 스승님이 들으신 바로는 이와 관련해서 능력을 발휘한 이에게는 진급이나 작게는 원하는 곳으로 보직을 변경할 수 있는 기회가 주어진다고 하오.\n\n여기서 한 가지 작은 문제가 있긴 한데... 바로 내가 나가를 감당할 수 없다는 점이오. 술집에서 주정뱅이가 벌이는 소동을 진압하거나 싸움꾼 거지를 체포하는 것쯤이야 자신 있지만 나가는 내게 버거운 상대요. 당신이 좀 도와주시오!", progress = nil, completion = "사우스쇼어에서 나가를 처치했으니 이제 전출은 보장된 거나 다름없군. 하루빨리 이 암울한 항구에서 벗어나 스톰윈드로 돌아가야 할 텐데...", rewards = "다음과 같은 것들을 받습니다:\n\n회뜨는 식칼"},
[563] = {title = "전출", objective = "스톰윈드 왕궁에 있는 상사 사무엘슨에게 파렌의 보고서를 전달해야 합니다.", description = "경비대의 신임 대장인 사무엘슨 상사님은 내가 스톰윈드에 배치되어 있었을 때, 내 스승이셨으니까 보고서를 제출하는 건 문제 없을 거요. 이 보고서는 그분이 나를 다시 도시로 불러들일 수 있는 충분한 사유가 될 거요. 그분께 내 보고서를 가져다주시오. 단, 저 늙은 레드패스가 눈치채지 못하게 해야 하오.", progress = "어서 오시오. 스톰윈드 근위병에게 도움을 요청할 일이라도 있소?", completion = "이게 뭐지? 아... 사려깊은 내 제자가 직접 사우스쇼어의 나가 문제 해결에 공을 세웠다니... 이 보고서를 가져다 줘서 고맙소이다. 다음 달에 병력 배치를 재검토할 때 반드시 이 내용을 참작하도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[564] = {title = "크나큰 위협", objective = "사우스쇼어의 다렌 말뷰가 산사자 8마리와 덩치큰 산사자 10마리를 처치해 달라고 부탁했습니다.", description = "여기 이 아름다운 말들을 잃는 것보다 더 괴로운 일은 없습니다요. 사실 지금까지 저 성가신 언데드 무리와 이 근처를 배회하는 불량배들이나 만고에 도움이 안 되는 비밀결사대 도적에게도 말을 꽤 많이 잃었답니다.\n\n하지만 조상님을 걸고 맹세컨대, 우리 말들에게 저 알터랙의 산사자보다 더 큰 위협이 되는 건 없을 겁니다. 녀석들은 매번 언덕에서 내려와 저를 미치게 한다니까요!\n\n스스로 영웅이라 생각하신다면 가서 녀석들을 어떻게 좀 해 주십쇼.", progress = nil, completion = "정말 반가운 소식입니다요! 애초부터 &lt;class&gt;님 같은 영웅께 부탁해서 그놈의 짐승들을 처치했어야 했는데... 정말 훌륭하십니다요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n목자의 벨트목자의 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n조리법: 맛있는 사자 스테이크맛있는 사자 스테이크"},
[565] = {title = "바르톨로의 설인 모피 망토", objective = "사우스쇼어에 있는 바르톨로 진세티에게 양모 두루마리 1개, 산악인의 망토, 가는 실타래, 그리고 설인 모피 10개를 가져가야 합니다.", description = "나, 위대한 바르톨로가 얼라이언스 내에서 명성이 자자한, 세계적인 설인 모피 망토를 만들어 주겠소!\n\n내 장담하는데, 온 세상을 돌아다녀도 내가 만든 망토만한 건 없을 거요. 오, 뭐라고 했소, 말쑥한 <race> 양반? \"바르톨로, 당신 것보다 나은 망토는 어디에도 없소!\"라고 했소? 아, 그럼, 그렇고말고. 그런 말은 워낙 많이 들었다오.\n\n내게 양모 두루마리 하나, 솜씨 좋은 가죽 세공사가 만든 산악인의 망토 한 벌, 가는 실타래, 그리고 설인 모피를 가져다주시오. 필요한 재료들을 다 구해 오면 멋진 망토를 만들어 드리리다!", progress = "오, 이 위대한 바르톨로를 다시 찾아온 걸 보니, 설인 모피 망토를 만들 재료를 다 구해 왔나 보구려? 아니면 나, 바르톨로의 위대함에 매료된 것이겠군!", completion = "자, 그럼 이 위대한 바르톨로가 귀신같은 솜씨를 한번 부려 볼까나... 잘 보시오. 위대한 바르톨로는 마법사의 지팡이나 마법사의 마법봉 없이도 마술을 부린다오. 바늘과 실만 가지고 말이지!", rewards = "다음과 같은 것들을 받습니다:\n\n설인 모피 망토"},
[566] = {title = "바르두스 남작 현상수배", objective = "바르두스 남작을 처치하고 그 증거로 그의 머리카락을 타렌 밀농장에 있는 고위집행관 다살리아에게 가져가야 합니다.", description = "고위집행관 다살리아의 명에 따라, 바르두스 남작이라는 인간을 포세이큰에 대한 범죄 혐의로 지명 수배한다. 바르두스는 비밀결사대라는 조직의 고위 간부로 알려져 있다.\n\n그는 타렌 밀농장 북쪽에 있는 알터랙 산맥의 고원에서 마지막으로 목격되었다.\n\n위 범죄자를 처치할 것을 명한다. 바르두스 남작을 제거한 증거를 고위집행관 다살리아에게 가져오는 자에게 보상금이 지급될 것이다.", progress = "아, 바르두스 남작에게 걸린 보상금을 받으려고 온 건가?", completion = "아주 훌륭한 일을 했군. 바르두스 남작을 처치했으니 비밀결사대 지도자의 수도 줄어든 셈이군. 놈들의 저항과 악행도 곧 끝이 날 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n지옥의 로브"},
[567] = {title = "위험 인물 수배!", objective = "타렌 밀농장의 고위집행관 다살리아가 서기관 호레이스 화이트스티드, 민간인 윌키스, 광부 하켓, 농부 칼라바에 현상금을 걸었습니다.", description = "위험 인물 수배!\n\n힐스브래드에 있는 다음 인간들은 위험 인물로 간주되므로 고위집행관 다살리아의 이름으로 현상금을 거는 바이다.\n\n서기관 호레이스 화이트스티드: 죽음의추적자 토마 살해 혐의로 수배함.\n\n민간인 윌키스: 연금술사 엘리 살해 혐의로 수배함.\n\n광부 하켓: 죽음의추적자 프라이 살해 혐의로 수배함.\n\n농부 칼라바: 언더시티에서 지급되는 보급품 약탈 혐의로 수배함.\n\n이상의 죄인들은 모두 잠적 중이므로 찾기 힘들 수 있을 것이다. 이들을 처치하고 신고하는 자에게는 보상금을 지급할 것이다.", progress = nil, completion = "자네는 현상금 사냥꾼으로서의 자질이 뛰어나군. 수고했네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n약탈자의 활보초병 버클러불타버린 마법봉\n\n다음과 같은 것들 또한 받습니다:\n\n두건 모자"},
[568] = {title = "그롬골 방어", objective = "그롬골 주둔지의 사령관 아그로고쉬가 채찍꼬리랩터 15마리를 처치해 달라고 부탁했습니다.", description = "트롬카! 그롬골에 온 것을 환영하네. 제때에 잘 도착했군. 나는 위대하신 대족장님 휘하의 주둔지 사령관으로서 이곳 정글에서 전 호드의 안전을 책임지는 영광스러운 임무를 맡고 있다네. 그런데 이곳에 서식하는 짐승 중 일부가 스토나드까지의 보급망의 안전을 지키는 우리의 임무를 방해하고 있어.\n\n자네가 그롬골 외곽에 있는 랩터의 수를 좀 줄이도록 하게. 놈들의 수를 최대한 줄인 후에는 내게 돌아와 다른 임무를 맡도록.", progress = "아직도 이곳 토착 랩터들이 우리의 보급 작업을 방해하고 있네, <class>.", completion = "명예롭게 임무를 잘 수행해 주었네, &lt;class&gt;.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[569] = {title = "그롬골 방어", objective = "그롬골 주둔지에 있는 사령관 아그로고쉬가 모쉬오그일족 투사 10명과 모쉬오그일족 의술사 5명을 처치해 달라고 부탁했습니다.", description = "처음 이 정글에 도착했을 때 우리는 이곳 토착 종족들과 싸울 생각이 전혀 없었네. 스토나드에 보급품을 공급하는 임무가 최우선이었으니 말이지. 하지만 복잡한 문제가 발생하였다네. 이곳의 오우거 무리가 그롬골 남동쪽의 미즈자 폐허를 점령하고 말았으며, 수차례 경고를 했음에도 놈들은 우리 보급 짐마차에 매복 공격을 해 오고 있다네.\n\n호드의 명예로운 일원인 자네에게 이 비협조적인 오우거들을 처리하는 임무를 맡기도록 하지. 미즈자 폐허로 가서 놈들을 그 지역에서 몰아내도록 하게. 적어도 놈들에게 확실한 경고는 될 것이야.", progress = nil, completion = "수고했네. 대족장님을 위해 명예로운 공을 세웠군.", rewards = "다음과 같은 것들을 받습니다:\n\n그롬골 버클러"},
[570] = {title = "모크타르딘의 마법", objective = "그롬골 기지에 있는 예언자 모크타르딘이 그림자퓨마 발톱 8개와 온전한 암호랑이의 송곳니를 가져다 달라고 부탁했습니다.", description = "호드는 지금이라도 정글 마법의 힘을 깨닫고 이용해야 하오. 지금까지 내 마법 의식은 상당한 효과를 보아 왔지. 이제 난 아주 강력한 마법을 사용할 수 있게 되었소. 용감한 <class>|1이여;여;, 당신을 위해 아주 특별한 물건을 만들어 주도록 하지.\n\n내게 그림자퓨마 발톱과 암호랑이의 송곳니를 가져오시오. 아무 송곳니나 사용할 수 있는 게 아니고, 반드시 오염되지 않은 순수한 상태의 송곳니여야 하오.\n\n이 짐승은 보통 정글 여기저기를 어슬렁거리지만 가까운 곳에서도 찾을 수 있을 테니 남동쪽의 미즈자 폐허 강 건너편으로 가 보시오.", progress = "좋은 소식을 가지고 온건가?", completion = "당신은 정글에 대해 잘 알고 있는 것 같군. 가져온 표본들은 정말 훌륭해. 우리 호드를 위해 희생된 이 가여운 짐승들의 영혼에 감사해야겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[571] = {title = "모크타르딘의 마법", objective = "그롬골에 있는 예언자 모크타르딘에게 덩치큰 고릴라의 힘줄을 가져가야 합니다.", description = "자, 다음 재료는 상당히 구하기 어려운 물건이야. 이 깃털, 발톱, 순수한 송곳니를 제대로 한데 묶으려면 마법의 밧줄이 필요하오.\n\n마법의 밧줄로 사용할 수 있는 건 늙은 고릴라의 힘줄밖에 없지. 덩치큰 고릴라의 힘줄은 덩치큰 안개계곡고릴라에게서만 얻을 수 있는데, 놈들은 무법항 동쪽 지역으로 먹을 것을 찾아다닌다고들 하오.\n\n반드시 완벽한 상태의 힘줄을 가져와야 해. 내가 필요로 하는 완벽한 상태의 힘줄을 얻으려면 꽤 여러 마리를 처치해야 할 수도 있겠지만, 그만한 가치는 충분히 되는 물건이야.", progress = "그래, 잘 돼가고 있소? 덩치큰 고릴라의 힘줄을 구해온 것이오?", completion = "정말 최고의 힘줄을 구해 왔군. 노고에 대한 답례는 곧 하도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[572] = {title = "모크타르딘의 마법", objective = "그롬골 주둔지에 있는 예언자 모크타르딘에게 줄무늬정글랩터 깃털 10개를 가져가야 합니다.", description = "강력한 마법 물건을 만들기 위해서는 골짜기의 저 고양이과 동물들에게서 모아 온 재료들 외에도 아직 필요한 물건이 많소. 이 정글 장신구는 내가 주술적인 의식을 통해 결합한 것이지. 호드와 대족장님을 위한 임무에 큰 도움이 될 것이오.\n\n자, 우선 내게 줄무늬정글랩터 깃털을 좀 모아 줘야겠소. 깃털은 보통 놈들의 완장에 사용되지. 대형 투기장에서 멀지 않은, 그롬골 바로 남쪽 지역에 가면 랩터들을 발견할 수 있을 것이오.", progress = "그래, 깃털은 많이 모아 왔소?", completion = "아주 훌륭하군. 지금 당장 이 깃털로 준비를 해야겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[573] = {title = "모크타르딘의 마법", objective = "그롬골에 있는 예언자 모크타르딘에게 신성한 샘물을 가져가야 하며 나가 탐험가 10명을 처치해야 합니다.", description = "이제 마지막 재료 한 가지만 구하면 마법을 완성할 수 있소.\n\n남쪽에 서부 해안 쪽 절벽 높은 곳에 신성한 샘이 있소. 이 샘은 종교학자와 신비주의 학자들 사이에서 뜨거운 논란의 대상이 되고 있소이다. 아제로스의 모든 종족들은 그 샘물이 자기 일족을 위해 신이 주신 신령한 선물이라고 주장하고 있지.\n\n마지막으로 부탁할 일은 바로 그 신성한 샘물을 가져다 달라는 것이오. 나가 탐험가도 그 샘물을 찾아 나섰다고 하니 조심하는 게 좋을 거요. 샘물을 가져오려면 아마 놈들과 부딪쳐야 할 거요.", progress = "마법이 거의 완성되었소. 내가 부탁한 일은 어떻게 됐소?", completion = "신성한 샘물도 구했으니 이제 의식용 목걸이에 마법을 걸 준비가 다 되었군.\n\n대족장님의 이름으로, 그리고 위대한 호드의 수호 아래, 이걸 목에 걸게 된 걸 자랑스럽게 여기도록 하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n고위주술사의 목걸이"},
[574] = {title = "특수 부대", objective = "쿠르젠 특전사 10명과 쿠르젠 심리학자 6명을 처치해야 합니다.\n\n반란군 야영지에 있는 부관 도렌에게 보고하십시오.", description = "쿠르젠의 정규군 수를 많이 줄였으니 이제 고도로 훈련된 그의 특수 부대를 상대해야 합니다. 놈들은 이 밀림에서 우리 반란군을 학살하지 않을 때는, 쿠르젠 주둔지 뒷편에 있는 보급창인 동굴 깊숙한 곳에서 지내고 있습니다.\n\n개인적으로 쿠르젠의 병사들을 많이 알고 있지만 그들은 노련하고, 쿠르젠에게 매우 충성스러우며, 또 잔인하니 이번 임무는 쉽지 않을 겁니다.\n\n그들을 처치한 후에 제 상관이신 도렌 부관님께 보고하도록 하십시오. 당신에게 직접 보고를 듣고 싶어하실 겁니다.", progress = nil, completion = "하사관 요화는 당신의 능력을 믿고 있으며 나는 그녀를 믿소. 당신이 쿠르젠 군대를 물리쳐 준 덕분에 우리에게도 희망이 생겼군. 우리들만으로는 쿠르젠의 능력을 당해내지 못해서 우려하고 있던 차였는데... 아직 우리에게도 한 줄기 서광은 남아 있는 것 같소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[575] = {title = "민물 악어 가죽", objective = "무법항에 있는 드리즐릭에게 민물 악어 가죽 2개를 가져가야 합니다.", description = "모두들 저에게 \"예나 지금이나 남해는 물론 전 세계에서 가장 뛰어난 가죽 세공꾼\"이라 말하죠. 나! 드리즐릭을 말이에요! 가장 뛰어난 가죽... 에헴, 흠. 내 가죽 제품은 아주 훌륭한 것으로 전문가들에게도 그 명성이 대단하죠.\n\n방금 전에도 땜장이 조합의 조합장이신 리들복스님께서 즐겨 신는 익셀시어류 장화 12짝을 주문하셨다니까요. 사실, 그 신발은 저희 집에서 제일 잘 팔리는 신발입죠.\n\n장화의 기본 형태를 잡으려면 우선 가시덤불 골짜기 북부 지역의 강가에서 악어 가죽을 구해와야 하는데 좀 구해다 주시겠어요?", progress = "장비는 다 준비됐습니다요. 이제 그 가죽만 있으면 되는데... 리들복스님을 오래 기다리시게 할 수는 없습죠.\n\n바보가 아니라면 땜장이 조합의 수석 발명가님을 실망하게 하는 짓은 하지 않을 거예요.", completion = "좋은 가죽이군요. 사실 장화의 안감으로 사용할 거니까 가죽의 질은 그리 중요하지 않지만, 대신 편안해야 하죠.\n\n가죽이 너무 딱딱한 경우에는 호랑이 피로 부드럽게 해 준답니다. 이런 게 바로 장사 수완이란 겁니다요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[576] = {title = "잃어버린 눈", objective = "무법항에 있는 애꾸눈 디지가 붉은해적단에게서 그의 눈을 찾아달라고 부탁했습니다.", description = "잠깐, 멈추시오! 거기 누구요?\n\n흑, 난 특수한 마법 눈이 없으면 아무것도 할 수 없다오. 애초에 전투에서 눈을 잃은 것부터가 불행의 시작이었지! 하지만 어찌하다 보니 운 좋게 메네실에 정박하게 되었다오. 그런데, 어떤 떠돌이 마법사가 마법으로 특수한 유리 눈을 만들어 줘서 다시 앞을 보게 되었지.\n\n그런데 지난 밤 밖으로 나가던 길에 붉은해적단 놈들이 나를 덮쳐 내 눈을 가지고 갔지 뭐요! 그 녀석들, 아무래도 무법항 쪽으로 가는 것 같았는데...\n\n이 늙은 뱃사람을 위해 눈을 되찾아 주지 않으시겠소?", progress = "이보시오, 친구! 내 비록 볼 수는 없지만 당신이 항구 건너 중간쯤에 갔다는 건 냄새로 알 수 있소.\n\n내 눈은 되찾아 주지 않을 거요? 내 눈이 저 비열한 붉은해적단 놈들 손에 있다는 걸 알면 선장이 나를 수장시켜 버릴 거란 말이야.\n\n장님이 망을 보다니 그게 무슨 소용 있겠소? 저 까마귀 둥지가 바로 내 자리였었소. 더 이상 선실 하나 없는 신세가 될 텐데... 배 밑바닥에서라도 지낼 수 있다면 다행이겠군.", completion = "오! 이런, 이런! 내 소중한 눈을 되찾았구려. 지금도 잘 맞을지 한번 끼어 봐야겠소.\n\n하하! 야호! 앞이 보여!!", rewards = "다음과 같은 것들을 받습니다:\n\n검은파도 단망토"},
[577] = {title = "무쇠턱 악어 가죽", objective = "무법항에 있는 드리즐릭에게 무쇠턱 악어 가죽 5개를 가져가야 합니다.", description = "자, 이제 장화의 기본적인 형태는 잘 잡혔는데, 이 가죽만으로는 안감을 만들기에 충분하지 않네요.\n\n\"그럼 어떻게 해야 하죠, 드리즐릭?\" 이렇게 물으시려고 했다고요? 그렇다면 걱정 마세요! 이제 이 드리즐릭이 앞으로 해야 할 일을 알려 드릴 테니까요.\n\n안감은 보이는 부분이 아니니까, 질이 떨어지더라도 나즈페리티 호수 부근에 사는 악어의 두껍고 싼 가죽을 사용하면 충분히 장화를 완성할 수 있어요.", progress = "최고의 품질, 100% 고급 악어 가죽으로 만든 드리즐릭의 익셀시어 가죽 장화! 이보다 더 좋을 순 없다!\n\n이보다 더 멋진 광고 문구는 없을 거예요.\n\n가죽은 구해 오셨나요?", completion = "오! 내 장화를 보세요. 꼭 소시지 같지 않나요? 보기 좋고, 맛도 좋고. 가장 좋은 재료와 고기로만 만든 한번 맛을 보면 잊을 수 없는 소시지 말입니다요.\n\n안전성이 아주 뛰어나고 기분을 좋게 해 주는 신발입죠. 제 말을 믿으시라고요. 아, 거참... 진짜 재료가 뭔지 너무 꼬치꼬치 묻진 마세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[578] = {title = "해일의 돌", objective = "무법항에 있는 남작 레빌가즈를 위해 유령의 섬을 찾아야 합니다.", description = "그 섬에 정말로 고블린 마법사와 물의 정령들이 출몰한다면 해일의 돌을 내 손에 넣을 수 있을지도 모르겠군!\n\n자네가 이 유령의 섬을 찾아서 무슨 일이 일어나고 있는지 알아봐 주게. 아, 그리고 해일의 돌에 대해 더 알고 싶다면, 이 증서를 가지고 스톰윈드 도서관으로 가보라고. 그러면 내가 처음으로 그 전설을 접했던 책을 한 권 찾아 줄 거야.\n\n가즈반이 정말로 그 돌을 찾을 수 있었던가...?", progress = nil, completion = "역시 그 이야기는 사실이었어! 정말 놀랍군!\n\n하지만 해일의 돌을 가져오려면 우선 그 돌에 걸려 있는 저주를 푸는 방법을 알아내야 할 걸세. 저주는 마법에 관련된 것이니 마법사 중 한 명에게 도움을 청해야겠는데 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[579] = {title = "스톰윈드 도서관", objective = "안두인 국왕께서는 교육에 큰 비중을 두고 여러 가지 서적과 문서의 복사본을 만들어 대중에게 공개할 수 있도록 예산을 마련해 주셨지요. 이용하시는 방법은 아주 간단합니다. 도서관 증서를 가져오면 이곳에 있는 책의 복사본을 드리고 있습니다.", description = nil, progress = "안두인 국왕께서는 교육에 큰 비중을 두고 여러 가지 서적과 문서의 복사본을 만들어 대중에게 공개할 수 있도록 예산을 마련해 주셨지요. 이용하시는 방법은 아주 간단합니다. 도서관 증서를 가져오면 이곳에 있는 책의 복사본을 드리고 있습니다.", completion = "이 중에서 관심 있는 책이 있으신가요?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n모건 래디모어의 이야기구루바시의 전설 3권"},
[580] = {title = "위스키 슬림의 잃어버린 술병", objective = "무법항에 있는 위스키 슬림이 잃어버린 퍼플리버보스 포트 와인을 찾아 달라고 부탁했습니다.", description = "우린 옛 동부 내륙지가 바라다보이는 전망대 절벽 근처에서 특별 배급된 술로 잔치를 벌이고 있었지. 바다는 곧 우릴 삼켜 버릴 것처럼 사나웠고 말이야.\n\n이 슬림님은 술에 대해서라면 일가견이 있지. 선장에게는 우리가 스톰윈드로 가던 중에 한 사나포선으로부터 빼앗은 퍼플리버보스 포트 와인 한 상자가 있었는데, 나 같은 애주가가 그런 술을 몰라볼 리가 있겠소?\n\n동부 내륙지로부터 폭풍이 몰아칠 때 난 술을 마시느라 정신없었지. 그런데 큰 파도가 밀려와 술병이 모두 배 밖으로 빠져버렸지 뭐요. 당신이 나를 도와 그 술병들을 찾아 주지 않는다면, 선장은 아마 닻을 끌어올리는 도르래로 나를 치려고 할 거야!", progress = "차라리 날더러 바다에 빠져 죽으라고 해! 이제 술도 거의 다 떨어져 간단 말이오. 선장이 곧 출항을 명할 텐데, 그러면 난 저 타나리스 사막처럼 말라 죽게 될 거야. 그리고 포트 와인이 없어진 걸 선장이 아는 날엔... 으으...!", completion = "오, 이런! 선장의 술을 찾았군! 여어, 이거 당신에게 정말 큰 신세를 졌어.\n\n밖에는 폭풍이 몰아치고 있는 것 같군. 폭풍이 지나가길 기다리는 동안 이 술 한 병으로 몸이나 녹여 볼까...", rewards = "다음과 같은 것들을 받습니다:\n\n럼지 럼주"},
[581] = {title = "예니쿠 수색", objective = "그롬골 주둔지에 있는 님보야에게 붉은머리부족의 어금니 9개를 가져가야 합니다.", description = "비극적이야. 우리 족장님의 막내 아드님인 예니쿠의 일은 정말 비극적이오. 우리 일족의 관습에 따라 예니쿠는 줄구룹의 구루바시 트롤에게 보내졌지. 하지만 우리 검은창부족이 오크 스랄님께 편입되면서 불쌍한 예니쿠가 잊혀지고 말았소. 난 족장의 아드님인 예니쿠를 찾기 위해 저 멀리 오그리마에서 가시덤불 골짜기로 파견되었소.\n\n내 생각에 예니쿠는 붉은머리부족 트롤에게 잡혀 있는 게 분명하오. 날 도와줄 생각이라면 붉은머리부족 놈들을 처치해 주시오. 북쪽으로 가면 놈들을 찾을 수 있을 테니 놈들의 어금니를 모아 내게 가져다주시오.", progress = "이보시오, <class>. 붉은머리부족들은 처치했소? 그렇다면 전리품을 보여 주시오.", completion = "좋은 어금니군. 당신은 붉은머리부족을 처치할 만한 실력이 있음을 증명해 보였소.\n\n아주 좋아, 앞으로 당신이 해 줘야 할 일이 많을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[582] = {title = "인간사냥꾼", objective = "그롬골 주둔지에 있는 님보야에게 쭈그러든 해골 20개를 가져가야 합니다.", description = "우린 반드시 예니쿠의 생사를 확인해야 하오.\n\n붉은머리부족 인간사냥꾼들을 처치하고 놈들이 가지고 있는 쭈그러든 해골을 가능한 많이 가져와야 하오. 그래야 그 중에 예니쿠가 있는지 없는지 확인할 수 있으니까 말이오.\n\n만약 붉은머리부족 놈들이 예니쿠를 죽였다면 놈들의 우두머리인 간줄라의 영혼에 600년의 저주가 내려질 것이오!\n\n자, 어서 가시오. 북쪽으로 해안을 따라 줄다이아 폐허와 줄쿤다의 폐허로 가면 인간사냥꾼들이 많이 있을 거요.", progress = "족장님의 아들이 무척 걱정되는군. 내가 조사할 수 있도록 쭈그러든 해골은 가지고 왔소?", completion = "고맙소. 이 해골들을 조사해 불쌍한 예니쿠가 인간사냥꾼의 도끼를 피했는지 확인해 보도록 하지.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n검은창부족 소매장식검은창부족의 팔보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[583] = {title = "정글 탐험", objective = "헤멧 네싱워리와 대화해야 합니다.", description = "가시덤불 골짜기에 온 걸 환영합니다!\n\n눈치챘는지 모르겠지만 저기 있는 드워프께서 바로 그 유명한 얼라이언스의 전쟁 영웅이자 사냥의 대가이신 헤멧 네싱워리님이십니다. 저분은 자신의 야영지에 낯선 자가 들어오는 걸 별로 달가워하지 않지만 <class>, 당신이라면 지금까지의 활약상을 보아하니 괜찮을 것 같군요.\n\n네싱워리 주인님도 많은 전투를 경험한 베테랑인지라 다른 전쟁 영웅들에게는 호의적이시랍니다.\n\n가서 그 분과 얘기해 보세요. 사냥에 대해 조언을 해 주실 수 있을 겁니다.", progress = nil, completion = "자네를 알게 되어 기쁘구먼. 이 부근에서 &lt;class&gt;|1을;를; 본 지가 오래돼서 말이야.\n\n난 한 가지 목적을 위해 이 원정대를 모집했다네. 바로 거대하고 잡기 힘든 짐승을 사냥하기 위해서 말이지. 보아하니 자네는 일종의 영웅 기질이 있는 것 같으니 특별히 사냥에 동참시켜 주겠지만, 그 전에 우선 자네 실력을 증명해 보여야 하네.\n\n내가 직접 자네에게 랩터 사냥을 가르쳐 주겠네. 아제크는 호랑이 사냥을 훈련시켜 줄 테고... 또 얼가딘 경은 퓨마 추적의 달인이지.\n\n자네 실력을 증명해 보이면 더 큰 사냥에 끼워 주도록 함세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[584] = {title = "붉은머리부족의 머리카락", objective = "그롬골 주둔지에 있는 끓고 있는 가마솥에 간줄라와 네즐뤼크의 머리카락을 가져가야 합니다.", description = "다행히 뱀신의 가호로 그중에 예니쿠는 없었소. 하지만 아직 그를 찾을 단서가 전혀 없으니...\n\n반드시 진실을 밝혀내야 하오. 혹시 붉은머리부족의 족장과 그의 의술사만 진실을 알고 있다면 그야말로 곤란한 일이 아닐 수 없군. 검은창부족의 적인 그들이 순순히 털어놓지는 않을 테니, 우선 놈들을 죽인 후 강제로 알아낼 수밖에 없소!\n\n간줄라와 공포의 네즐뤼크를 처치하고 그들의 머리카락을 가져와 이 가마솥 안에 넣도록 하시오. 놈들은 줄쿤다의 폐허 깊숙한 곳 어딘가에 있을 거요. 그 머리카락이 있으면 놈들의 자백을 받아낼 수 있소.", progress = "가마솥에는 녹색 액체가 끓고 있습니다.", completion = "간줄라와 네즐뤼크의 머리카락을 가마솥 안에 넣습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[585] = {title = "네즐뤼크와의 대화", objective = "그롬골 주둔지에 있는 끓고 있는 가마솥으로 발리아마 전리품 해골과 지아타자이 전리품 해골, 줄맘웨 전리품 해골을 가져가야 합니다.", description = "<가마솥에서 들려오는 네즐뤼크의 목소리>\n\n사실이다. 나는 검은창부족의 아이가 끌려간 곳을 알고 있다. 비록 네가 나를 이기고 내 영혼을 묶어 놓긴 했지만 대가 없이 입을 열지는 않을 것이다!\n\n우리 붉은머리부족은 백골가루부족과 전쟁을 치르고 있다. 내게서 원하는 정보를 얻으려면 백골가루부족에게서 놈들의 전리품 해골 3개를 훔쳐 여기 우리가 있는 곳으로 가져와라. 그러면 난 황천에서도 함께할 노예를 얻을 수 있으니... 첫 번째는 발리아마에 있는 놈들의 전리품 더미에서 가져와야 하고, 다른 하나는 지아타자이, 그리고 나머지 하나는 줄맘웨에서 가져온 전리품이어야 한다.", progress = "해골을 가져오면 말하겠다...", completion = "그래, 바로 이거야. 내 영혼이 풀려나면 이 세 노예와 함께 황천으로 들어갈 것이야.\n\n내 요구를 잘 들어주었구나. 너는 &lt;race&gt; 족의 자랑거리가 될 것이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[586] = {title = "간줄라와의 대화", objective = "백골가루부족 사냥꾼 8명, 백골가루부족 인간사냥꾼 6명, 그리고 백골가루부족 광전사 4명을 처치해야 합니다.\n\n그롬골 주둔지에 있는 끓고 있는 가마솥으로 망가진 아나텍의 갑옷을 가져가야 합니다.", description = "<가마솥에서 들려오는 간줄라의 목소리>\n\n너와 너의 조상까지도 저주할 것이야!!\n\n피와 복수만이 내 분노를 달랠 수 있을 것이다. 좋아, 나를 달래고 싶다면 내 말대로 따라야 한다.\n\n동쪽에 백골가루부족이 있는 곳 한복판으로 가서 그중 가장 사나운 놈들을 처치하라. 살아남을 수 있다면 놈들의 족장인 학살자 아나텍과 싸워라. 하하하! 할 수만 있다면 놈의 망가진 갑옷이라도 가져와 보시지!\n\n아마 놈은 너를 썩은 고기를 먹는 짐승의 밥으로 던져주려 할 것이다.", progress = "비록 내 혼이 육신에서 분리되어 끓는 가마솥에 던져진 신세지만 너의 두려움은 느낄 수 있다.\n\n하하! 과연 네가 해낼 수 있을까?", completion = "믿고 싶지는 않지만, 인정할 수밖에 없군. 자네가 해냈어. 학살자 아나텍이 죽었으니 이제 내 분노가 좀 가라앉는군.\n\n앞으로 위대한 업적을 세워갈 것도 같군. 하지만, 언젠가는 자네도 황천에서 만날 날이 있겠지. 그때 우리 둘이 다시 힘을 겨뤄 볼 수 있을 것이다.\n\n그때까지 기다리고 있겠다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[587] = {title = "코담배를 찾아서", objective = "무법항에 있는 디그가 코담배 15개를 가져다 달라고 부탁했습니다.", description = "아... 오늘따라 바닷바람이 새롭군. 특별히 좋은 건 없을지 몰라도 뱃사람의 삶이 바로 나의 삶이지.\n\n난 항구에 정박할 때마다 좋은 술 한 병과 질 좋은 코담배를 찾곤 하지. 별로 좋지 않은 습관이긴 하지만, 해적이라면 해적다운 뭔가 있어야 하지 않나, 안 그래?\n\n그런데 마을의 약초 장수는 떠나 버렸고, 코담배는 이미 다 팔려 물건이 없다는 사실을 알았을 때 내가 얼마나 슬펐겠나? 그 괘씸한 붉은해적단 약탈자 놈들이 약초 장수의 물건을 강탈해 갔다고 하더군.\n\n당신처럼 용감한 <class>|1이라면;라면; 놈들이 강탈해 간 물건 중 일부를 가져올 수 있을 것 같은데, 어떤가?", progress = "물건은 찾았나, 친구?", completion = "정말 대단한 활약이군! 게다가 내가 떠나기 직전에 잘 맞춰 와 줬군그래. 어떻게 감사해야 할지 모르겠어!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[588] = {title = "예니쿠의 생사 확인", objective = "킨윌레이와 대화해야 합니다.", description = "<가마솥에서 들려오는 네즐뤼크의 목소리>\n\n나와 우리 족장의 분노를 달래 주었으니 진실을 알려 주겠다.\n\n예니쿠라는 애송이는 자신의 일족에게조차 잊힌 자이지. 추방자 잔질이라는 의술사가 그를 데려갔지. 이제 잔질이 그의 몸과 영혼을 조종하고 있으니 아주 강력한 마법이 아니면 그를 구할 수 없을 것이다.\n\n<class> 따위는 절대 사용할 수 없는 마법이지.\n\n너의 동맹군인 검은창부족이라면 예니쿠를 구할 수 있을지도 모르겠군. 가능성은 거의 없어 보이지만 말이야.", progress = nil, completion = "추방자 잔질이라고?\n\n예니쿠가 그 사악하고 강력한 트롤 의술사에게 잡혀 있다면 그를 구할 가능성은 거의 없소... 티끌만큼의 가능성이 있을 뿐이란 말이오.\n\n그렇지만 아직 희망은 있지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[589] = {title = "고동치는 푸른 수정", objective = "그롬골 주둔지에 있는 킨윌레이에게 고동치는 푸른 수정 3개를 가져가야 합니다.", description = "가시덤불 골짜기 심장부의 깊은 곳에 보물이 숨겨져 있다는 전설이 전해 오고 있소. 우린 그걸 마음의 눈이라 부르는데, 아주 강력한 힘을 지니고 있소. 당신이 마음의 눈을 찾아와 준다면 예니쿠를 어둠에서 구해낼 수 있을 거요.\n\n난 정글의 영혼들에게 마음의 눈에 대해 물어 보도록 하겠소. 그동안 당신은 남동쪽의 수정 광산으로 가서 무쇠턱 바실리스크들에게서 고동치는 푸른 수정을 구해 오도록 하시오. 그 수정은 매우 희귀하지만 마음의 눈을 우리 의지대로 다루려면 그 수정의 마법이 꼭 필요하오.", progress = "수정은 가지고 왔소? 마음의 눈을 찾은 후에 마지막 의식을 행하기 위해서는 그 수정이 꼭 필요하오.", completion = "수고했소. 잘 형성된 수정을 가지고 왔군. 수정들이 벌써 내게 노래하고 있는 듯하오.\n\n당신이 수정을 구하러 간 동안 정글의 영혼들과 얘기를 나누어 마음의 눈이 있는 곳을 알아냈소.\n\n그리고 그걸 지키고 있는 게 누구인지도...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[590] = {title = "도적의 거래", objective = "데스넬에 있는 캘빈 몬태그와 싸워서 이겨야 합니다.", description = "뭐야?\n\n뭐냐고?!\n\n돈을 달라고? 난 당신에게 빚진 게 없다고.\n\n편지? 무슨 편지? 오호, 덤벼 보시겠다? 좋아, 친구. 한판 붙어보자고! 내가 빚을 졌다니...", progress = nil, completion = "굉장해! 정말 놀라운 기술이군!\n\n당신쯤은 쉽게 처리할 수 있을 줄 알았는데 말이야. 날 보기좋게 때려 눕혔어.\n\n여기 약속한 돈을 주지... 처음 말했던 만큼은 아니겠지만, 뭐 애당초 주려고도 안 했던 거니까 기분 좋게 받으라고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[591] = {title = "마음의 눈", objective = "그롬골 주둔지에 있는 킨윌레이에게 마음의 눈을 가져가야 합니다.", description = "마음의 눈은 동쪽에 있는 모쉬오그 오우거 소굴 안 깊은 곳에 있는 마이조스라는 오우거 마법사가 가지고 있소. 검은창부족이 가시덤불 골짜기에 살던 시절부터 내가 알고 있던 자이지. 그 오우거는 마법 능력이 강하며 아주 사악한 자라오. 게다가 마음의 눈을 가지고 있다면 지금쯤 마법이 더 강력해졌을 거요.\n\n당신이 마이조스를 상대하고 그에게서 마음의 눈을 빼앗아 와야 하오. 위험한 임무지만 그것이 예니쿠를 구할 수 있는 유일한 희망이오.", progress = "어서 오시오. 정글의 영혼들이 당신의 용기를 찬양하는 노래를 부르고 있소. 하지만 마이조스를 상대하는 임무에 대해서는 해줄 얘기가 없다는군.\n\n그래, 마음의 눈은 가져왔소?", completion = "마음의 눈을 가져왔군! 당신은 진정 전설 그 자체요!\n\n마음의 눈을 가져온 걸 보니 틀림없이 마이조스도 물리쳐서 황천으로 보내 버렸겠군. 그래서 영혼들이 그에 대해서는 아무 말도 하지 않으려 했던 것이야, 하하.\n\n이 세계에서 그를 완전히 제거해 버린 것은 정말 다행스러운 일이지만, 이제 그는 영혼의 세계에 존재하게 될 거요. 그곳이 그의 손에 들어가는 일이 없어야 할 텐데...\n\n하지만, 그 걱정은 나중에 하도록 하고... 지금은 우선 마음의 눈을 우리가 원하는 대로 움직이기 위한 의식을 행해야겠소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[592] = {title = "예니쿠 구출", objective = "님보야에게 충만한 영혼의 보석을 가져가야 합니다.", description = "마음의 눈을 영혼의 보석으로 바꾸어 놓았는데 이렇게 한 데에는 두 가지 목적이 있소. 우선 영혼의 보석을 사용해서 예니쿠를 기절시킨 다음 그의 머리 위에 보석을 놓으면 그의 영혼을 가둘 수 있지.\n\n그런 다음 영혼의 보석을 님보야에게 가져가시오.\n\n예니쿠는 여기서 좀 떨어져 있는 가시덤불 봉우리의 수정 해안을 따라가면 나오는 아보라즈의 폐허에 추방자 잔질과 함께 있소.", progress = "킨윌레이가 말하길, 당신이 예니쿠의 영혼을 붙잡으러 갔다고 하던데...\n\n사실이오? 그렇다면 그의 영혼을 가져왔소?", completion = "해냈군! 추방자 잔질의 손아귀에서 예니쿠를 구출하고 내가 가망이 없다고 거의 포기했던 임무를 완수해 내다니...\n\n우리 부족은 당신의 이름을 노래로 만들어 기릴 것이오. 그리고 당신의 무용담을 돌에 새겨 영원히 남기도록 하겠소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n님보야의 신비한 지팡이용맹의 메달\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[593] = {title = "영혼의 보석 채우기", objective = "예니쿠는 당신 앞에 기절해 있지만 그의 영혼은 다른 곳에 있습니다.", description = nil, progress = "예니쿠는 당신 앞에 기절해 있지만 그의 영혼은 다른 곳에 있습니다.", completion = "영혼의 보석을 그의 이마에 올려놓습니다. 예니쿠의 몸이 떨리면서 그의 영혼이 몸에서 빠져나와 보석으로 빨려 들어가고 영혼이 없는 빈 껍데기만 남습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n충만한 영혼의 보석"},
[594] = {title = "쪽지가 든 병", objective = "쪽지가 든 병의 장본인을 찾아야 합니다.", description = "상당히 좋은 필체의 쪽지에는 다음과 같이 적혀 있습니다.\n\n- 누구든 저를 도와 주실 수 있는 분께-\n\n전 지금 도움이 절실히 필요합니다. 거대한 하늘갈기고릴라가 남해에 있는 한 섬에 절 잡아 두고 있습니다.\n\n밤하늘의 별도 저에겐 낯설고 정글의 숲에 가려 잘 보이지 않지만, 아주 맑은 날에는 북서쪽에 거친 해안이 보입니다. 그리고 남서쪽에는 거대한 배로 보이는 것이 있습니다.\n\n제 구세주가 되어 주실 분께 간절히 부탁드립니다. 부디 절 도와주십시오.", progress = nil, completion = "절 구하러 오셨나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[595] = {title = "붉은해적단", objective = "일등항해사 크래즈가 무법항 북쪽의 작은 만을 조사해 달라고 부탁했습니다.", description = "보아하니 일자리를 찾고 있나 보군, 친구. 왜 육지를 좋아하는 <race> <class>|1이;가; 검은바다 해적단을 돕겠다고 하는지는 모르겠지만, 원한다면 말리지는 않겠어.\n\n우리 배가 이곳 무법항에 정박한 지 얼마나 됐다고 우리 적인 고약한 저 붉은해적단 놈들이 가시덤불 골짜기 남쪽 지역에 모여 있다는 소식이 들리고 있네.\n\n동료들은 모두 술 마시고 여자를 찾아 다니느라 정신이 없어! 그래서 지금 정찰병이 필요해.\n\n폭풍 해안을 따라 무법항 북쪽에 있는 작은 만을 조사해 주라고.", progress = nil, completion = "맥주통 위에서 급하게 휘갈긴 글이 적혀 있는 지도와 동전 몇 개를 발견합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[596] = {title = "피묻은 뼈목걸이", objective = "그롬골 주둔지에 있는 킨윌레이에게 피묻은 뼈목걸이 25개를 가져가야 합니다.", description = "난 님보야의 요청으로 그를 돕기 위해 그롬골로 파견되었소. 하지만... 여기까지 오게 된 내 나름의 목적도 있소이다.\n\n바로 우리의 적인 붉은머리부족 때문이지. 적의 전리품을 모으면 그들에 대항할 힘을 얻을 수 있소. 당신이 우리 일족을 도울 생각이라면 우리의 적을 처치해 주시오.\n\n북쪽에 살고 있는 붉은머리부족 트롤을 처치하고 그들에게서 피묻은 뼈목걸이를 가져오시오. 가능한 많이 모아 오면 충분한 사례를 하도록 하겠소.", progress = "붉은머리부족은 언젠가 우리 검은창부족에게 섬멸 당하고 말 것이오! 우리의 숙명의 적에게서 피묻은 뼈목걸이를 빼앗아 왔소?", completion = "오, 훌륭하군. 내가 이 목걸이들을 끓여 힘을 빼낼 거요. 목걸이에서 힘이 사라지면 목걸이 주인의 영혼도 약해지게 되지!\n\n자, 이걸 받으시오. 약속했던 답례요.", rewards = "다음과 같은 것들을 받습니다:\n\n피의 뼈고리"},
[597] = {title = "붉은해적단", objective = "무법항에 있는 일등항해사 크래즈에게 조사 결과를 보고해야 합니다.", description = "지도 상의 무법항에는 정확하게 현재 서 있는 위치에 빨간색으로 \"X\" 표시가 되어 있습니다.\n\n휘갈겨 쓰인 글씨의 내용은 다음과 같습니다.\n\n\"모두 현재 위치에 야영지를 확보하고 소리가 새어 나가지 않도록 하라. 남부 전투 사령부에서 공격 신호가 있을 때까지 기다려라. 접근하는 자는 모두 없애도록.\"", progress = nil, completion = "아, 당신 기억나. 정찰을 마치고 돌아온 거로군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[598] = {title = "부서진 뼈목걸이", objective = "그롬골 주둔지에 있는 킨윌레이에게 부서진 뼈목걸이 25개를 가져가야 합니다.", description = "붉은머리부족의 전리품을 모아 왔으니 이제 다른 임무를 주도록 하지. 우리는 지난 몇 년 동안 남동쪽에 사는 백골가루부족과 전쟁을 치러 왔소. 우리 검은창부족은 더 이상 가시덤불 골짜기에 살지 않지만 백골가루부족과의 충돌은 계속되고 있는 상황이오.\n\n그러니 당신이 놈들을 처치하고 놈들의 부서진 뼈목걸이를 내게 가져다주시오. 우리의 전쟁을 도와준다면 당신과 검은창부족의 관계는 더욱 돈독해질 것이오.", progress = "백골가루부족 놈들은 우리와 전쟁을 시작한 걸 뼈저리게 후회하게 될 것이오! 임무는 완수했소?", completion = "당신의 힘이 이 목걸이들을 모을 정도의 힘을 가졌다니 대단하군. 당신 덕분에 백골가루부족이 바실리스크에게 짓밟힌 우리의 젊은이들과 똑같은 운명을 맞게 되다니!\n\n우리 일족은 당신에게 큰 은혜를 입었소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n검은창부족의 신발검은창부족의 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[599] = {title = "붉은해적단", objective = "함장 시혼에게 붉은해적단의 공격 계획을 보고해야 합니다.", description = "이런 제길! 그래, 붉은해적단 놈들이 무법항을 공격할 모종의 계획을 꾸미고 있다고? 흥! 그 악당 놈들 참 대담하군그래. 무법항은 영원히 우리 검은바다 해적단의 영역인 것을!\n\n이거 생각보다 문제가 심각한 것 같군. 이 사실을 즉시 함장 시혼님께 보고하도록 해 주라고! 저 늙은 바다의 개들이 마을 어딘가에서 기웃거리고 있다니...", progress = nil, completion = "붉은해적단이 무법항을 공격할 거라고 했나? 차라리 전망대 절벽에서 뛰어내리는 편이 놈들에게 나을 텐데 말이야. 어쨌든, 내게 정보를 주다니 자네는 우리 함대에 큰 공을 세운 셈일세. 검은바다 해적단을 대신해서 감사를 표하는 바이네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[600] = {title = "투자개발회사 채광", objective = "무법항에 있는 크랭크 피즐버브에게 노래하는 파란 수정 10개를 가져가야 합니다.", description = "투자개발회사는 가시덤불 골짜기 전역에서 일련의 사업을 벌이고 있죠. 덕분에 열심히 일하는 나 같은 고블린은 정직하게 돈을 벌지도 못한다고요! 당신이 날 좀 꼭 도와줘야겠어요!\n\n투자개발회사는 북쪽의 수정 광산 근처에서 채광하고 있어요. 그들은 바실리스크 때문에 광산에 들어가지 못하고 있지만 주변 언덕에서 여전히 노래하는 수정을 캐내고 있답니다.\n\n그들에게서 수정을 빼앗고, 그들이 정글의 주인이 아니란 걸 깨닫게 해 줘요. 그리고... 험... 그 수정은... 내게 증거로 가져오세요.", progress = "수정은 가져왔나요?? 난 그 수정이 필요해요!\n\n아...아니 그러니까 내 말은 그 사악한 투자개발회사가 가시덤불 골짜기에서 설 땅을 잃었다는 사실을 확인해야 한다는 거죠. 아시다시피 우리처럼 선량한 자들도 먹고 살아야 하지 않겠어요!", completion = "훌륭하군요! 정말 멋져요! 큰돈을 벌 수 있겠군!!\n\n아... 그게 아니라... 뭐... 투자개발회사가 이번엔 정글을 잘못 골랐지 않나요? 녀석들이 이곳을 떠나면 우리 형편도 나아질 거예요. 고마워요. 큰 신세를 졌네요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n고블린 점화장치은제 부삽\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[601] = {title = "물의 정령", objective = "무법항에 있는 남작 레빌가즈를 위해 물의정령 족쇄 6개를 가져와야 합니다.", description = "해일의 돌을 발견했다고 전해지는 가즈반이라는 고블린 마법사가 물의 정령들을 불러낸 것이 분명해. 자네도 알고 있겠지만, 해일의 돌은 그걸 소유하는 자의 존재를 점차 소멸시키거나 사라지게 하는 저주를 내린다네.\n\n달라란의 마법사에게 물의정령 족쇄의 마법 잔재를 분석하게 하면 그 저주를 풀 방법을 찾을 수 있을 것 같군그래. 자네가 다시 그 섬으로 가서 물의정령 족쇄를 좀 찾아 오라고.", progress = "족쇄는 찾았나?", completion = "흠, 조사해 보지는 못하지만 이 족쇄들 중에 분명히 하나는 도움이 될 거야. 이 족쇄들을 달라란으로 가져가 마법사에게 조사해 보라고 하게나.\n\n난 그런 따분한 늙은 마법사와 얘기하기 위해 무법항을 떠날 생각은 추호도 없으니까 말이야.\n\n허허, 내가 없는 동안 누군가 내 자릴 차지하게 될까 봐 걱정하는 건 절대 아니라고. 무법항에는 나 레빌가즈를 싫어하거나 험담을 입에 담는 이조차 없으니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[602] = {title = "마법 분석", objective = "달라란에 있는 마법사에게 물의정령 족쇄가 든 가방을 가져가야 합니다.", description = "달라란의 마법사들이 파괴된 도시를 재건하느라 바쁘다고 들었네만, 시간을 내서 그 족쇄를 살펴봐 줄 마법사는 반드시 찾을 수 있을 거야. 내가 마법사들에 대해서 알고 있는 사실은 그들은 절대 마법적인 수수께끼를 거부하지 못할 거란 것이지.\n\n물의정령 족쇄가 든 가방을 가지고 가서 그들이 해일의 돌에 걸린 저주를 풀 수 있는 실마리를 찾을 수 있을지 알아봐 주게. 대마법사 앤자이럼 룬위버를 찾아가라고. 전에 내가 그와 거래했었고 그의 지식은 무척 방대하니 도움이 될 걸세.", progress = "미안하지만, 내가 지금 좀 바쁘오.", completion = "해일의 돌이? 정말 놀랍군. 당신은 내가 몇 년 전에 구루바시 제국의 전설에 관련된 책을 썼다는 사실을 들으면 아마 깜짝 놀라겠군그래. 난 그 해일의 돌에 대해서도 잘 알고 있소.\n\n이 족쇄들 중 하나엔 내가 분석할 수 있는 마법의 잔재가 남아 있을 것 같군. 어디 한번 살펴보도록 합시다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[603] = {title = "앤자이럼의 열쇠", objective = "무법항에 있는 케이틀린과 대화해야 합니다.", description = "해일의 돌을 소유하고 있는 마법사는 그 돌이 가진 힘을 일종의 제단 같은 곳에 집중되도록 증폭시켜 놓았소. 당신의 힘으로 돌을 깨뜨려 버릴 수 있을 것이오.\n\n내가 아는 바로는 그걸 가능하게 할 수 있는 물건은 고대 트롤 유물 중에 하나인 고대의 단검뿐이오. 그런데 말이오... 내가 가시덤불 골짜기에서 연구하던 시절에 그 단검을 발견했네만 그걸 내 고집 센 딸, 케이틀린에게 줘 버렸소. 그리고 그 애는 해적이 되기 위해 무법항으로 도망쳐 버렸고 말이지.", progress = nil, completion = "내 단검 말인가요? 당신 도대체 뭐죠? 날 웃기러 온 건가요?\n\n뭐라고요? 내가 최고의 검술가에서 무법항의 우스꽝스러운 해적이 되어 버린 사연을 또 얘기하란 말이에요?\n\n비열한 붉은해적단 중 한 녀석과 싸우는 동안 검을 떨어뜨렸는데, 그 녀석이 그걸 전리품으로 가져가 버렸어요.\n\n그 녀석이 단검을 가지고 가 버린 건 내게 검술가로서 모욕적인 말을 듣는 것 이상으로 치욕적인 일이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[604] = {title = "붉은해적단", objective = "무법항에 있는 함장 시혼이 붉은해적단 칼잡이 10명을 처치하고 붉은해적단의 해도와 붉은해적단의 명령서를 가지고 와 달라고 부탁했습니다.", description = "크래즈가 검은바다 해적단을 위한 자네의 노고를 높이 사더군. 내가 믿고 우리 함대에게 매우 중요한 임무를 맡기도록 하겠네.\n\n붉은해적단이 거친 해안에 설치한 소위 남부 사령부에 잠입해 놈들의 야영지를 급습하게. 그 쓰레기 같은 놈들이 무슨 일을 꾸미고 있는지 파악하기 위해 놈들의 해도와 명령서를 가지고 오게.", progress = "이봐. 그래, 남쪽의 붉은해적단 야영지에 대해 뭔가 소식을 가져왔나?", completion = "멋지게 해냈군. 이제 놈들의 계획을 알았으니 처리하는 것은 시간 문제야.\n\n이 만 바로 앞에 닻을 내렸다니 바보 같은 놈들...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[605] = {title = "노래하는 수정 조각", objective = "크랭크 피즐버브에게 노래하는 수정 조각 10개를 가져가야 합니다.", description = "노래하는 수정은 가시덤불 골짜기에서만 나는데다가 어떤 이들에겐 대단히 귀중한 물건이기도 하죠. 나도 수정을 팔 수는 있지만 저 지독한 투자개발회사가 독점하기 때문에 나처럼 선량한 중개상들은 수정을 구경하기도 힘들죠.\n\n그래서 당신을 고용할까 하는데 말이에요. 가시덤불 골짜기에 사는 바실리스크들은 그 수정을 먹고 살죠. 때문에 놈들의 가죽은 매우 단단하고, 또 가끔 놈들 가죽에서 질 좋은 수정을 얻을 수도 있답니다.\n\n아무 바실리스크나 사냥하면 되지만 북쪽으로, 줄쿤다의 폐허 남쪽 해안가를 따라 서식하는 놈들이 그래도 사냥하기 쉬울 겁니다.", progress = "아직 수정은 찾지 못했나요? 가져다주기만 하면 값은 후하게 쳐 드리겠습니다.", completion = "아! 좋습니다, 좋아요.\n\n자, 여기 당신 몫입니다. 당신과 거래하게 되어 매우 기뻤습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[606] = {title = "겁쟁이", objective = "무법항에 있는 겁쟁이 필립에게 안개계곡고릴라 내장 5개를 가져가야 합니다.", description = "내가 정말 참을 수 없는 건 놀음 빚을 안 갚는 자들이야. 지금도 내게 빚지고 있는 자들이 부지기수라니까! 당신이 대신 빚을 좀 받아다 줄 수 있나?\n\n첫 번째는 부두 옆에 사는 \"겁쟁이\" 필립이라는 놈이지. 녀석은 지난주 카드 게임 이후로 내게 빚을 많이 졌단 말이야! 이제 갚을 때가 됐고. 놈에게서 돈을 받으려면 겁을 좀 주면 될 거야.\n\n마을을 나가서 덩치큰 안개계곡고릴라를 잡은 다음에 고릴라의 내장을 좀 꺼내서 그 겁쟁이에게 가져가라고. 그 겁쟁이한테는 그게 짐승의 내장이 아니라 우리 동족의 내장이라고 믿게 해야 한다고. 더 끔찍해 보이도록 말이야.", progress = "이봐요! 왜 그렇게 쳐다보는 거예요.", completion = "악! 이... 이건 어디서 난 거죠? 아니, 말하지 마세요... 알고 싶지 않으니까!\n\n누가 보낸 거죠? 혹시 바다늑대가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[607] = {title = "맥킨리에게 돌아가기", objective = "'바다늑대' 맥킨리에게 겁쟁이 필립의 빚진 돈을 가져가야 합니다.", description = "자, 여기 이 주머니를 맥킨리에게 갖다 줘요. 그리고 그에게 돈은 갚을 생각이었다고 말해 주세요!\n\n술이 취해 길을 잃어서... 뭐, 말 안 해도 알잖아요, 어떻게 된 건지... 그도 아마 이해할 거예요. 그러니 그렇게 겁줄 필요 없다고요!", progress = "이게 누구신가. 그 겁쟁이에게 돈은 받아 왔나?", completion = "헤헤, 잘했군! 그래, 내장을 보여 줬을 때 그 겁쟁이가 어느 정도로 떨어 댔지? 봤어야 하는 건데!\n\n하! 녀석의 패를 읽는 건 식은 죽 먹기니, 녀석과 카드 게임을 하면 절대 지는 법이 없지. 도와 줘서 고맙소. 자, 이건 당신 몫이라고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[608] = {title = "붉은해적단", objective = "무법항에 있는 함장 시혼이 선장 스틸워터, 선장 킬하울과 함장 피랠론을 암살해 달라고 부탁했습니다.", description = "제길, 건방진 피랠론 녀석의 뻔뻔스러움이라니! 녀석은 절대로 전 함대는커녕 배 한 척도 우리 손아귀를 빠져나가 수정 호수를 지날 수 없을 게야.\n\n붉은해적단 놈들은 반드시 경솔한 행동에 대한 대가를 치르게 될 거야. 이제 놈들의 공격 계획을 파악했으니 눈치채기 전에 우리가 먼저 역습할 수 있어. 하지만 모험심이 강하고 용감한 부대의 병사들만으로도 충분한 임무에 전 함대가 움직일 필요는 없지 않은가? 가장 노련한 동료들을 이끌고 피랠론의 상륙 지점으로 가서 붉은해적단의 지휘부를 암살하도록 하게. 그러면 곧 그들의 함대도 침몰하고 말 거야.", progress = nil, completion = "아, 오늘은 검은바다 해적단이 기념할 만한 정말 멋진 날일세! 자네를 위해 만세 삼창!", rewards = "다음과 같은 것들을 받습니다:\n\n검은바다 튜닉"},
[609] = {title = "빚 돌려받기", objective = "무법항에 있는 \"바다늑대\" 맥킨리에게 마우리의 의족, 존존의 황금 망원경과 처키의 큰 반지를 가져가야 합니다.", description = "몇몇한테 돈을 받아내긴 했지만 아직도 받을 돈이 많아.\n\n이제 \"절름발이\" 마우리 윌킨스, \"까마귀\" 존존, 그리고 \"왕손가락\" 처키에게서 돈을 받아 내야 하지.\n\n이 치사한 놈들은 몇 달이나 돈을 안 갚고 있는데, 난 돈을 안 갚으려고 마을에서 도망친 줄 알았지 뭐요! 그런데 전에 놈들이 저주를 받아 마법에 걸려 정글 폐허 주위를 배회하고 있다는 말을 들었소. 뭐 놈들이 어찌 되었건 그건 내 알 바 아니고 난 그저 내 돈만 받아내면 되니까.\n\n놈들은 이곳에서 북동쪽에 있는 아보라즈의 폐허와 주부왈의 폐허에 있소. 그들을 찾아서 돈을 받아 내 주시오.", progress = "그 세 녀석은 찾았소? 놈들한테서 값나갈 만한 건 가져온 건가?", completion = "좋아! 이거면 좋은 값을 받을 수 있겠군. 특히 마우리의 의족에 들어 있는 건 값져 보이는데. 대단히 고맙소!\n\n그 세 녀석이 교훈을 얻었다면 좋겠군. 능력이 안 되면 돈을 걸지 말았어야지. 뭐, 이미 녀석에게는 너무 늦었는지 모르겠지만...노름 상대를 잘 골라야 하는 거라고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[610] = {title = "\"꽃미남\" 던컨", objective = "\"꽃미남\" 던컨에게서 케이틀린의 단검을 되찾아야 합니다.", description = "아버지가 당신을 보냈다고요? 그 괴팍하신 어른께서 이미 날 포기했다고 생각했는데...\n\n내가 도망쳐 온 건 정말 아버지 탓이 아니에요. 그저 아버지가 기대하는 대로 백발이 성성한 그 진부한 마법사들과 어울려 곰팡이 슨 책이나 반복해 읽으면서 지루한 삶을 살기 싫었을 뿐이었다고요!\n\n내 단검이 필요하다면 붉은해적단의 일원인 \"꽃미남\" 던컨에게서 되찾아 와야 할 거예요. 녀석의 약점은 양 어깨 사이니 제대로 한방 먹여주면 아마 단검을 포기할 거예요.", progress = "난 지금까지 한 번도 져 본 적이 없다는 거 알고 있나요? 물론 칼에 벤 적이야 있죠. 그걸 각오하지 않고서야 어떻게 검투를 할 수 있겠어요? 하지만 녀석은 주먹으로 내 머리 옆을 쳐서 기절시켰었다고요. 다시 정신을 차리고 보니 녀석이 내 검을 가져갔더군요.\n\n내 별명에서도 알 수 있듯이 난 내 검이 없으면 싸울 수 없어요.", completion = "던컨을 물리쳤단 말인가요? 첫인상만큼 풋내기는 아닌가 보군요.\n\n나도 당분간은 당신한테 도전해선 안 되겠는데요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[611] = {title = "해일의 저주", objective = "케이틀린의 검으로 해일의 제단을 파괴한 다음 가즈반을 처치하고 해일의 돌과 케이틀린의 검을 남작 레빌가즈에게 가져가야 합니다.", description = "그래서 지금 일종의 제단 같은 것을 찾고 있다는 말인가요? 흠, 난 아버지처럼 트롤 폐허에 대한 전문가는 아니지만, 당신이 찾고 있는 그 섬 근처에 있는 가라앉은 트롤 도시의 폐허에 대해 들은 적이 있어요. 그곳부터 한번 찾아보세요.\n\n내 검을 되찾아 줬으니 한번 빌려 주도록 하죠. 하지만 용무가 끝나면 꼭 돌려줘야 해요!", progress = "해일의 돌은 찾아 왔나? 이미 그 돌을 놓을 자리도 치워 놓았고 돌을 놓을 멋진 진열대도 사 놓았지.", completion = "해일의 돌! 아주 멋지군! 내가 소장하고 있는 고대 트롤 유물 중에서도 최고의 소장품이 되겠군그래. 이 돌 안에 세상의 해일이 모두 들어 있는 것 같아 보이지 않나? 정말 놀라워!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n수정의 로브"},
[613] = {title = "마우리의 의족 열기", objective = "무법항에 있는 \"바다늑대\" 맥킨리에게 마우리의 열쇠를 가져가야 합니다.", description = "이런 젠장! 그 느림보 마우리 녀석이 의족에 자물쇠를 채워 놓았는데 열 수가 없어!. 내가 녀석에게서 받아 내야 할 게 이 의족 안에 있단 말이지!\n\n이 자물쇠를 열 수 있는 열쇠를 찾아야 하오. 마우리는 북동쪽에 있는 오우거 소굴에서 모쉬오그일족 오우거들과 노름을 했었다고 하던데 말이야. 녀석이 아직 살아 있을 때 들은 적이 있는데, 마지막으로 오우거 소굴에 갔을 때 돈을 너무 많이 따서 놈들에게 쫓겼다고 했었어. 그 오우거 놈들이 그 열쇠를 가지고 있을지도 모른다는 거지.\n\n놈들에게 열쇠가 있다면 많은 수를 처치해야 우리가 찾는 열쇠를 얻을 수 있을 거요.", progress = "이봐! 마우리의 열쇠는 찾았소?", completion = "오, 찾았군! 정말로 고맙소. 큰 신세를 졌군!\n\n자, 이건 내 사례라오!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n소장용 판금방패"},
[614] = {title = "선장의 상자", objective = "무법항에 있는 허클베리 스모츠에게 스모츠의 상자를 가져가야 합니다.", description = "난 여기에서 칼림도어의 톱니항까지 배로 항해하곤 했다네. 그래도 꽤 유명한 선장이었다고. 그런데...\n\n저주받은 바다 거인들이 내 인생을 망쳐 놓고 말았어! 거인들이 내 배를 박살내고 부하들을 모두 죽였지. 난 겨우 구명정에 몸을 맡기고 이 무법항까지 흘러 왔다네. 그 거인들 중 고를라쉬라는 놈이 내 상자를 훔쳐 가면서 그걸 코담뱃갑으로 쓸 거라더군. 뻔뻔한 놈 같으니!\n\n들리는 소문에 의하면 고를라쉬는 이곳에서 동쪽에 있는 해안을 어슬렁거린다고 하네. 놈을 찾아서 내 상자를 되찾아 주게! 그렇게 해 준다면 정말 고맙겠군그래.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n혈사단 팔보호구"},
[615] = {title = "선장의 커틀라스", objective = "스프로거와 대화해야 합니다.그 거인들에게 내 첫 번째 배를 잃은 후, 난 다른 배를 샀고 스모츠의 복수라는 이름을 붙였지. 그리고 선원을 모으고 식량을 싣고는 그 악당 놈들을 찾아 떠났다네. 결국 놈들을 찾긴 했지만 또다시 당하고 말았지. 놈은 스모츠의 복수호를 박살내고 내 두 번째 선원들을 모두 죽였다네. 그리고 난 또다시 구명정에 의지하는 신세가 되었지.\n\n이번에는 네골라쉬라는 거인 놈이 내 커틀라스를 훔쳐가 버렸네. 네골라쉬를 찾아 내 커틀라스를 되찾아 주게나.\n\n스프로거와 얘기해 보게. 저 친구는 스모츠의 복수호의 요리사였는데 마지막 공격에서 살아남았으니까 그가 거인 찾는 걸 도와줄 것이야.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "그 거인들에게 내 첫 번째 배를 잃은 후, 난 다른 배를 샀고 스모츠의 복수라는 이름을 붙였지. 그리고 선원을 모으고 식량을 싣고는 그 악당 놈들을 찾아 떠났다네. 결국 놈들을 찾긴 했지만 또다시 당하고 말았지. 놈은 스모츠의 복수호를 박살내고 내 두 번째 선원들을 모두 죽였다네. 그리고 난 또다시 구명정에 의지하는 신세가 되었지.\n\n이번에는 네골라쉬라는 거인 놈이 내 커틀라스를 훔쳐가 버렸네. 네골라쉬를 찾아 내 커틀라스를 되찾아 주게나.\n\n스프로거와 얘기해 보게. 저 친구는 스모츠의 복수호의 요리사였는데 마지막 공격에서 살아남았으니까 그가 거인 찾는 걸 도와줄 것이야.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[616] = {title = "유령의 섬", objective = "무법항에 있는 남작 레빌가즈와 대화해야 합니다.", description = "레빌가즈 남작님께서 내게 무법항과 가시덤불 골짜기에 떠돌고 있는 이상한 소문을 파악하여 그 진상을 캐내라고 당부하셨어요. 보통 난 유령 이야기는 잘 믿지 않지만, 선술집에서 어떤 선원들이 해안 근처에 있는 유령의 섬에 대해 이야기하는 것을 들었다고 하더군요. 물의 정령들과 미쳐 날뛰는 고블린 유령이 있다고 말이에요.\n\n레빌가즈님을 만나게 되면 이 이야기를 좀 전해 주겠어요?", progress = nil, completion = "흥미롭군. 그 이야기를 들으니 예전에 읽었던 책이 떠오르는데...\n\n아, 분명히 트롤의 전설이었지. 크라젝이 보고한 내용이 사실이라면 아마 곧 내가 소장하고 있는 고대 유물과 유적에 해일의 돌도 추가할 수 있겠군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[617] = {title = "아키리스 묶음", objective = "무법항에 있는 선원 블로즈에게 아키리스 갈대 묶음 10개를 가져가야 합니다.", description = "일거릴 찾고 있소? 작은 일이라도 괜찮다면 내가 일거릴 줄 수도 있는데...\n\n내 친구 중에 그로이라고 있는데, 나가를 죽여서 얻는 아키리스 갈대를 팔아 큰 재미를 보고 있다고 하던데. 그게 일종의 비싼 바다 갈대라고 하더군. 무엇에 쓰이는 건지는 모르겠지만 그에게 그 갈대 묶음을 가져가면 값을 후하게 쳐주고 있소.\n\n내게 그 갈대 묶음 10개를 가지고 오면 우리도 돈을 좀 만져볼 수 있을 거요. 나가를 마지막으로 본 건 여기서 북쪽에 있는 해변가였소.", progress = "내게 특별한 볼일이 없다면 저리 비키시오.", completion = "잘했소. 아키리스 갈대 10개를 구하는 건 그리 어렵지 않았을 것 같은데, 어땠소? 뭐, 나가들을 공격하고 싶지는 않았지만, 모두 먹고 살아야 할 것 아니오.", rewards = "다음과 같은 것들을 받습니다:\n\n이글거리는 장식띠"},
[618] = {title = "네골라쉬와의 대적", objective = "선장 스모츠의 구명정에 대머리수리 날개 구이 10개와 밀림포도나무 와인 5병을 가져가야 합니다.\n\n네골라쉬를 처치하고 가시덤불 골짜기에 있는 선장 스모츠에게 스모츠의 커틀라스를 가져가십시오.", description = "네골라쉬는 늘 굶주려 있는 거인이에요.\n\n그 거인들이 우리 배를 파괴했을 때, 네골라쉬는 곧장 제 주방으로 쳐들어 왔었죠. 녀석은 다른 거인처럼 선원들로 배를 채우려 하지 않았어요. 네골라쉬는 와인과... 내가 만든 바베큐를 원하고 있었어요. 그건 제 특별 요리인 데다 재료를 구하려면 황야의 땅까지 가야 하는데 말이죠!\n\n그 거인을 유인하려면 와인과 대머리수리 날개가 많이 필요할 거예요. 여기에서 해안을 따라 남동쪽에 있는 낡은 구명정에 음식을 실어 놓으세요. 네골라쉬가 그 음식 냄새를 맡으면 반드시 나타날 거예요!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n스모츠의 나침반"},
[619] = {title = "네골라쉬 유인", objective = "버려진 구명정입니다. 보트 옆에는 긁히고 빛 바랜 페인트로 다음과 같이 쓰여 있습니다.\n\n\"스모츠의 복수\"", description = nil, progress = "버려진 구명정입니다. 보트 옆에는 긁히고 빛 바랜 페인트로 다음과 같이 쓰여 있습니다.\n\n\"스모츠의 복수\"", completion = "배에 음식과 술을 쌓아 놓습니다.", rewards = nil},
[620] = {title = "이니셜이 새겨진 머리띠", objective = "이니셜이 새겨진 머리띠를 주인에게 돌려줘야 합니다.", description = "이 멋진 머리띠에는 가장자리를 따라 \"HS\" 라는 머리글자가 수놓아져 있습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[621] = {title = "잔질의 비법", objective = "무법항에 있는 크랭크 피즐버브에게 잔질의 혼합물 12개를 가져가야 합니다.", description = "추방자 잔질은 무법항 북동쪽의 주부왈의 폐허와 아보라즈의 폐허에서 그의 부하들과 함께 살고 있어요. 자기 일족에게 추방당했죠. 왜냐고요? 그야... 잔질이 다른 이의 마음을 조종하는 능력이 있어서 일족의 지도자들이 그를 두려워하기 때문이죠.\n\n그는 정글 식물의 혼합물을 사용해 다른 이의 의지는 약화시키고 육체적인 힘은 강하게 만들고 있어요. 잔질의 혼합물은 다른 이를 조종하고자 하는 자들에게 무척 유용할 거예요.\n\n그의 혼합물 견본을 가져오면, 혼합물을 유용하게 사용할 방법을 찾아보죠.", progress = "잔질의 혼합물은 가져왔나요?", completion = "아, 아주 좋아요! 자, 여기 사례금이에요.\n\n그리고 이건 덤으로 드리는 겁니다... 판단력에 도움이 될 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n타락의 허리띠"},
[622] = {title = "하사관 칼레브에게 돌아가기", objective = "반란군 야영지에 있는 하사관 칼레브에게 크라젝의 수리된 냄비를 가져가야 합니다.", description = "당신이 혈석을 구하러 간 동안 냄비 수리를 끝냈어요. 그리고 증기 피리도 부착해 놓았고, 여기 보세요! 바닥에는 다리뼈도 자를 수 있는 신형 칼까지 달아 놓았어요!\n\n보시다시피, 내 오래된 냄비는 이제 완벽한 요리 기계가 됐어요. 냄비 주인도 만족할 거예요.", progress = "어서 오십시오. 무법항에는 다녀온 겁니까? 고블린 크라젝이 내 냄비를 고쳐 주었나요??", completion = "오, 수리했군요! 이제 저녁 식사 준비를 할 수 있겠습니다. 정말 고맙습니다.\n\n무법항에서 무슨 문제는 없었습니까? 그곳은 점점 위험해지고 있는데다가, 가끔 고블린이 술취한 선원들을 포로로 잡아 그들의 노예선으로 끌고 간다는 소문까지 나돌고 있다더군요.\n\n...그리고는 강제로 아무도 모르는 곳으로 데려가서 무슨 일을 시킨다고 하던데...", rewards = "다음과 같은 것들을 받습니다:\n\n조화의 모자"},
[623] = {title = "아키리스 묶음", objective = "테라모어 섬에 있는 선원 그로이에게 아키리스 갈대 한 묶음을 가져가야 합니다.", description = "당신이 없는 동안 그로이로부터 전갈이 왔소. 지난번에 보내준 아키리스 갈대에 상당히 만족했다고 하더군. 그리고 아키리스 갈대를 급하게 더 찾는 고객이 있다고 하오.\n\n그런데 나는 앞으로 일주일 동안은 테라모어 섬으로 갈 계획이 없는데 말이야. 괜찮다면 당신이 내 대신 아키리스 갈대를 가져다주면 좋을 것 같은데... 어떻소, 구미가 당기지 않소?\n\n당신 먼지진흙 습지대가 어딘지 알고 있지 않소? 나도 그곳에 가면 조심하려고 하지만 당신이 테라모어 섬의 친구들의 일원이 아니라면 그곳은 위험할 수 있소.", progress = "뭐요?", completion = "뭐지?! 난 당신 같은 자와 노닥거릴 시간이 없다고. 괜히 귀찮게 하지 말고 저리 가라고.\n\n뭐라고? 블로즈가 보냈다고? 흠, 그럼 물건이나 한번 보실까?\n\n&lt;선원 그로이가 아키리스 갈대 묶음을 주의 깊게 살펴보며&gt;\n\n좋아, 꽤 괜찮군. 아키리스 갈대 한 묶음을 더 구했다고 하면 내 고객이 아주 기뻐할 거요. 그래, 이제 값을 얼마나 쳐줄지 궁금하지 않소, &lt;class&gt;? 물론 그렇겠지!\n\n자, 여깄소. 그리고 덤으로 충고 하나 하겠는데, 어서 내 선창에서 내려가는 게 좋을 거라고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[624] = {title = "코르텔로의 수수께끼", objective = "수수께끼를 풀어야 합니다.", description = "많은 이들이 오가는 화려한 다리가 있지\n죽음의 고개 동쪽, 붉은마루 산맥 남쪽\n그 밑에서 무언가가 당신을 기다리고 있지\n어떤 이는 암시라고, 어떤 이는 단서라 하는 그것\n그것은 영원토록 그곳에 있지\n슬픔의 늪에서 시간을 견디며", progress = nil, completion = "젖은 양피지에는 다음과 같은 단서가 담겨 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[625] = {title = "코르텔로의 수수께끼", objective = "수수께끼를 풀어야 합니다.", description = "칼림도어의 먼 땅 당신을 기다리는 그곳\n위험이 희망과 운명을 꺾어 버리는 곳\n불모의 땅 동쪽 지독한 날씨\n어둡고 위험한 먼지진흙 습지대\n그러나 거기엔 기꺼이 시험에 도전하려는 자들을 위한 단서가 있네\n남서쪽 동굴에서 누군가 찾아 줄 날을 기다린다네", progress = nil, completion = "곰팡이 슨 두루말이를 발견했습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[626] = {title = "코르텔로의 수수께끼", objective = "수수께끼를 풀어야 합니다.", description = "위대한 혼란의 땅 로데론으로!\n용감한 병사들이 죽음에 맞서 싸우는 곳\n그 거대한 혼란을 뚫고 당신의 길을 찾으라\n거기서 이 수수께끼의 결말을 알게 되리\n동부 내륙지의 해안을 따라, 거대한 폭포의 밑바닥\n물밑에서 보물이 당신을 부르고 있다!", progress = nil, completion = "상자를 열어 뭔가를 발견합니다...", rewards = "다음과 같은 것들을 받습니다:\n\n탐험가의 배낭"},
[627] = {title = "크라젝의 부탁", objective = "무법항에 있는 크라젝에게 저급 혈석 광물 4개를 가져가야 합니다.", description = "아라시 고원 북쪽 먼 곳에 있는 마른수염 골짜기에 가면 산 속 동굴이 하나 있어요. 그 동굴에는 혈석이라는 희귀한 광석이 있죠. 그 동굴에 있는 혈석은 일등품은 아니지만, 품질이 좋지 않은 혈석도 그걸 어떻게 사용하는지 아는 이에게는 귀하게 사용될 수 있어요.\n\n나한테 그게 좀 필요해요. 그러니 내가 당신이 가져온 고물 냄비를 수리하고 있을 동안 혈석을 좀 가져다주세요. 충분한 양을 가져다준다면 가격을 맞춰 드리도록 하죠.\n\n아, 그리고 그 광석 채광 방법을 모른다면 채광해 줄 자를 찾아야 할 거예요!", progress = "왔군요. 혈석은 구했나요?", completion = "아, 훌륭해요! 이거 큰 신세를 졌군요.\n\n자, 여기 혈석을 구해다 준 사례금이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[628] = {title = "덩치큰 바다악어 가죽", objective = "무법항에 있는 드리즐릭에게 덩치큰 바다악어 가죽을 가져가야 합니다.", description = "안감을 완성했으니 이제 겉감만 만들면 됩니다요. 겉감에는 최고의 덩치큰 바다악어 가죽만을 사용하죠. 바다악어 가죽이 더 튼튼하면서도 질이 좋기 때문에 저만의 특별한 디자인인 드리즐릭의 익셀시어류 제품을 만들기에 안성맞춤이에요.\n\n완벽한 가죽을 찾기가 어렵긴 하지만 덩치큰 바다악어 가죽이라면 제격이죠. 녀석들은 다른 악어를 지켜야 할 경우에만 밖으로 나오기 때문에 바다악어를 몇 마리 처리해야 놈을 볼 수 있을 거예요.", progress = "바다악어가 점차 멸종돼 가고 있다는 기사를 읽은 적이 있었는데... 제겐 정말 안 좋은 소식이죠.\n\n어쨌든, 덩치큰 바다악어 가죽은 가져왔나요?", completion = "훌륭해요! 손님 덕분에 리들복스 조합장님께서 주문한 장화를 다음 지하광산행 배에 실어 보낼 수 있겠군요. 예정보다도 빨리 말이죠!\n\n수고해 주신 대가로 손님 장화도 한 켤레 만들어 놓았으니 가져가세요. 이 드리즐릭이 공짜로 드리는 겁니다요.\n\n다만, 드리즐릭의 익셀시어류 만한 장화는 없다는 사실만 기억해 주세요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n익셀시어 장화"},
[629] = {title = "썩은내 산호초", objective = "그롬골 주둔지에 있는 킨윌레이에게 서판 조각을 가져가야 합니다.", description = "오래전, 큰 지진으로 오래된 트롤의 도시가 북서쪽 폭풍 해안 앞바다에 잠기고 말았지. 지금은 멀록들이 도시의 폐허 속에 살면서 접근하는 이들을 공격하고 있기에 우린 그곳을 썩은내 산호초라고 부른다오.\n\n그 폐허 속에는 트롤 전설 속의 영웅 그리렉에 대한 옛 이야기가 적혀 있는 오래된 서판이 있소. 그 이야기는 우리 검은창부족에게 신성한 것이오. 비록 서판 자체는 너무 커서 옮길 수 없지만, 그 서판 조각 하나쯤은 반드시 우리의 새로운 고향인 오그리마에 모셨으면 하오. 서판 조각을 내게 가져다줄 수 있겠소?", progress = "서판 조각을 가져오길 기다리고 있겠소.", completion = "좋아. 오그리마에 돌아가면 이 서판 조각을 신성한 곳에 모셔 그리렉의 강한 힘과 명예가 영원히 기억될 수 있도록 하겠소.\n\n고맙소. 당신이 세운 공적은 우리 검은창부족과의 우호 관계가 더욱 돈독해지고 있음을 의미하는 것 아니겠소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[630] = {title = "쪽지가 든 병", objective = "밀림의왕 무클라를 처치하고 공주 푸바에게 열쇠를 가져가 그녀를 구해야 합니다.", description = "당신과 저를 구하기 위해 오신 동료들을 믿겠습니다. 저는 거대한 밀림의왕 무클라에게 잡혀 있답니다. 무클라가 이 섬의 짐승들에게 명령을 내려 제가 이 사슬을 끊고 탈출하지 못하도록 잡아두게 하고 있어요. 당신이 그 고릴라를 처치하고 이 족쇄의 열쇠를 찾아 주신다면 그 은혜 정말 잊지 않겠습니다.\n\n섬의 남동쪽 가장자리에서 무클라의 목소리가 자주 들리곤 해요. 쉬운 상대가 아니니 제발 조심하세요.", progress = "절 구하기 위해 당신을 보내 주신 우리 선조님께 감사드립니다. 절 자유롭게 할 족쇄의 열쇠는 가져오셨나요?", completion = "당신은 큰 치욕에서 절 구해 주셨습니다. 여기가 제 영토였다면 우리 일족과 함께 지내실 수 있도록 살 곳을 제공했겠지만, 지금으로서는 당신이 보여준 용감한 행동과 고귀함에 대한 답례로 드릴 수 있는 거라곤 오로지 이 증표밖에 없다는 게 아쉽군요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n푸바의 코걸이"},
[631] = {title = "탄돌 교각", objective = "라그 가마슨이 러스트로크를 찾아 달라고 부탁했습니다.", description = "언덕에서 끔찍한 폭발이 일어났소. 정말 끔찍한 폭발이었다오!\n\n그 폭발로 탄돌 교각을 방어하던 유능한 병사들을 잃고 말았소. 롱브레이드님께서는 곧바로 검은무쇠단 드워프에 대한 복수를 선언하셨소.\n\n우리는 수세에 몰리고 있고 지원군은 어디에도 보이지 않는 상황이오. 며칠 전에 롱브레이드님께서는 동쪽 다리로 러스트로크를 정찰 보내 다리를 탈환할 수 있을지 알아보도록 하셨소. 던 모드르가 포위된 지금 우리는 그를 찾으러 보낼 만한 병력이 없는 상태요.\n\n그러니 당신이 그를 좀 찾아 주시오.", progress = nil, completion = "체구가 작은 드워프 시체를 찾았습니다. 시체가 쓰고 있는 투구에는 에벤에셀 러스트로크라는 이름이 선명하게 새겨져 있습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[632] = {title = "탄돌 교각", objective = "라그 가마슨에게 돌아가서 러스트로크의 시체에서 발견한 양피지 문서를 보여 줘야 합니다.", description = "가여운 러스트로크는 검은무쇠단 드워프의 매복지까지 들어갔던 것 같습니다. 꽉 쥐고 있는 그의 주먹 옆에서 양피지 문서가 발견되었습니다.\n\n이 슬픈 소식을 라그 가마슨에게 보고하고 발견한 양피지 문서를 보여 줘야 합니다.", progress = "러스트로크의 흔적이라도 찾았소?", completion = "아! 이런 비통한 소식이...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[633] = {title = "탄돌 교각", objective = "탄돌 교각 건너편에 있는 폭발물을 찾아서 파괴해야 합니다.", description = "어떻게 이런 일이! 가엾은 러스트로크. 이건 있을 수 없는 비극이오.\n\n그의 죽음이 헛되게 해서는 안 되오. 당신이 발견한 이 양피지 문서에 따르면 캄 딥퓨리가 탄돌 교각 건너편 아라시 고원에 비밀리에 설치해 놓은 폭약을 감추기 위해 위장 공격을 한 것이라고 되어 있군.\n\n만약 그 폭약으로 다리가 파괴되면 북쪽으로의 주요 보급로를 차단당하게 되오. 그 전에 우리가 폭약을 찾아내 반드시 파괴해야 하오! 임무를 완수하면 여기로 돌아오시오. 당신이 우리의 유일한 희망이오.", progress = nil, completion = "아, 유일하게 남아 있는 다리를 지켜 냈구려! 마그니 브론즈비어드 폐하와 카즈 모단 주민을 위해 대단한 일을 해 주었소.\n\n이제 우리는 지원군이 나타날 때까지만 버티면 되는데...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n드워프 경비병 망토안개구름 바지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[634] = {title = "얼라이언스에 지원 요청", objective = "아라시 고원의 임시 주둔지에 있는 부대장 나이얼스를 찾아야 합니다.", description = "작은 부탁 하나만 더 해도 되겠소, <class> 친구? 우리는 아이언포지로부터 예비 사단을 기다리고 있소. 그런데 로고의 말에 의하면 북쪽 아라시 고원의 임시 주둔지에 얼라이언스 야영지가 있다고 하오.\n\n그곳으로 가서 부대장 나이얼스님을 만나보시오. 그리고 그녀에게 우리가 던 모드르와 탄돌 교각을 탈환하도록 지원 병력을 보내줄 수 있는지 물어봐 주시오.", progress = nil, completion = "롱브레이드님과 그의 용맹한 병사들에게 심심한 조의를 표하는 바입니다. 탄돌 교각의 비극적인 사고와 던 모드르의 함락 소식에 내 마음도 무겁군요.\n\n하지만 스트롬가드 역시 함락됐기 때문에 우리는 이곳 임시 주둔지에 주둔해 있어야 합니다! 우린 곧 우리의 대도시를 탈환할 계획입니다.\n\n스트롬가드에 왕의 깃발이 다시 걸릴 때까지 우리는 아라시 고원을 떠날 수 없습니다. 그것이 우리의 임무이며 또 명예를 지키는 길이니까요. 롱브레이드님께 지원군을 보낼 수 없는 상황이 안타깝군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[635] = {title = "산 속의 수정", objective = "환영에서 보았던 수정을 찾아야 합니다.\n\n제공된 아이템: \n", description = "수정을 손에 쥐자 고동치기 시작합니다.\n\n마치 도움이 필요한 누군가가 자신의 의사를 전달하려 애쓰는 것처럼 수정에서는 간절한 애원이 느껴집니다.\n\n마음속에 아라시 고원 북쪽 산악 지역과 그곳의 땅속에서 튀어나온 빛나는 수정에 대한 환영이 보입니다.\n\n그곳으로 끌려가는 듯한 느낌이 듭니다.", progress = nil, completion = "살아있는 힘이 수정 조각 내부에 갇혀 있는 것 같이 고동칩니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[637] = {title = "설리 발루의 편지", objective = "설리 발루의 편지를 사라 발루에게 전해 주십시오.", description = "편지 봉투 안에는 공들여 쓰인 편지 몇 장이 들어있는데, 물에 젖은데다 전쟁의 모진 상처들로 인해 다 낡아 버려서 편지의 몇 장이 손에 쥐자마자 녹아 없어져 버립니다.\n\n편지는 아이언포지의 사라 발루 부인 앞으로 보내진 것이며 \"사랑하는 사라에게...\"로 시작하고 있습니다.", progress = "먼 곳에서 고생스럽게 이곳까지 온 모양이군요. 요즘 상황을 보면 우리 모두의 영혼을 시험하는 것 같아요. 제게 무슨 소식을 가져오신 거죠?", completion = "편지가 물에 젖었다면 설리가 차가운 물속에 있단 말인가? 제발 사실이 아니라고 해 주세요!\n\n그가 뭐라고 썼는지 읽어 봐야겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[638] = {title = "트롤베인", objective = "아라시 고원의 해머폴로 가서 젠구와 대화해야 합니다.", description = "토라스 트롤베인도 죽었고 스트롬가드도 폐허가 되었으니, 볼진께서 이제 인간의 손에서 전설의 검인 트롤칼라를 빼앗아 앞으로 있을 줄구룹의 트롤과의 전투에 사용할 수 있도록 하라고 지시하셨소.\n\n검 탈취 작전을 감독하기 위해 노련한 사냥꾼 중 하나인 젠구가 아라시 고원 북동부 지역의 해머폴로 파견되었으니 그를 만나보도록 하시오.", progress = nil, completion = "어떻게 지내나, &lt;class&gt;? 볼진께서는 우리에게 상당히 어려운 임무를 부여하셨지. 그래서 말인데 자네의 도움이 필요하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[639] = {title = "스트롬의 인장", objective = "해머폴에 있는 젠구에게 스트롬의 인장을 가져가야 합니다.", description = "고대에 트롤들은 아라토리안 제국에 대항하여 싸웠네. 그 중에는 스트롬의 트롤베인이라는 별명으로 유명한 이그네우스 경이 가장 큰 호적수였지. 그자는 고대어로 트롤 사냥꾼이라는 뜻을 가진 트롤칼라라는 검을 들고 전투에 나섰지.\n\n하지만 지금의 트롤베인의 후예들의 힘은 약해졌고 그들의 성채는 폐허가 되었네.\n\n트롤베인은 지금 스트롬가드의 생존자 몇 명이 나눠 가지고 있는 여러 개의 인장으로 보호되어 있는데 이 인장들을 빼앗아야 하네.\n\n첫 번째 인장은 비밀결사대가 가지고 있는데, 스트롬가드에 있는 녀석들 중 한 명에게 있을 것이야.", progress = "아직 첫 번째 인장을 찾지 못했나? 스트롬가드에 있는 비밀결사대 일원 중 한 명이 가지고 있을 거야.", completion = "잘했군. 시작이 좋아. 트롤베인의 무덤에서 트롤칼라를 빼내려면 인장들을 모두 모아야 해.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[640] = {title = "깨진 인장", objective = "스트롬가드의 수호병들에게서 인장 조각 11개를 빼앗아 해머폴에 있는 토건에게 가져가야 합니다.", description = "토라스 트롤베인의 무덤은 세 개의 인장으로 보호되어 있네. 자네가 비밀결사대로부터 빼앗아 온 것은 이 중 첫 번째이고 나머지 두 개는 철통같이 수비하고 있는 스트롬가드 민병대가 가지고 있으니 구하기가 더 어려울 걸세.\n\n세 개의 인장 중 한 개인 소라딘의 인장은 토라스의 아들인 갈렌이 열한 개의 조각으로 나누어 스트롬가드 수호병들에게 나누어 주었지. 그 조각을 찾아내 우리 트롤 주술사인 토건에게 가져다주면 그가 조각을 결합하여 완전한 인장을 만들 걸세.", progress = "트롬카, <class> 친구. 젠구에게 들었는데 내 도움이 필요하다고?", completion = "아, 이 인장 조각들을 결합해 달라는 건가? 어디보자, 조각은 다 있고 마법적인 구조로 보아 되살리기 쉽게 되어 있으니... 그리 어려운 일은 아닌 것 같군... \n\n잠시 눈을 감아 보게.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[641] = {title = "소라딘의 인장", objective = "해머폴에 있는 젠구에게 소라딘의 인장을 가져가야 합니다.", description = "흠잡을 데 없이 완벽하게 인장을 완성했네. 이제 이 인장을 사용하여 트롤베인의 무덤에 있는 봉인을 깨뜨릴 수 있다네. 젠구에게 가 보게. 분명히 다른 임무가 또 있을 거야.", progress = "두 번째 인장을 가지고 왔나?", completion = "이제 조금만 더 노력하면 트롤베인의 무덤에서 트롤칼라를 꺼낼 수 있게 될 거야. 세 번째 인장의 소유자는 아라시 고원의 여러 곳을 자주 옮겨 다니기 때문에 어디에 있는지 정확하게 알 수 없네. 하지만 자네라면 찾을 수 있을 거라는 확신이 드는군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[642] = {title = "함정에 빠진 공주", objective = "미즈라엘의 결정 파편을 12개 모아서 마른수염 골짜기에 있는 오색 결정에 가져가야 합니다.", description = "제 이름은 미즈라엘입니다. 전 대지의 공주인데 거인들이 나를 잡아서 아라시 고원 땅속 깊이 가두어 놓았답니다. 이 수정 결정이 제가 지상 세계와 교신할 수 있는 유일한 수단이에요.\n\n제발 절 도와주세요. 거인과 한 편인 마른수염 코볼트들에게 동쪽의 마른수염 골짜기에 있는 동굴 안에 이것과 같은 결정이 있어요. 그 결정을 작동시키려면 코볼트들에게서 미즈라엘의 결정 파편을 빼앗아야 합니다.\n\n제발 부탁해요. 절 도와주세요!", progress = "이 결정 덩어리는 미즈라엘의 결정과 매우 흡사하게 생겼습니다. 하지만 미즈라엘의 결정처럼 안전한 느낌이 배어 나오지는 않습니다.", completion = "아! 결정을 작동시켰군요. 벌써 기운이 좀 생기는데요!\n\n하지만 아직 자유로워지려면 멀었어요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[643] = {title = "아라소르의 인장", objective = "아라소르의 인장을 찾은 후 해머폴에 있는 젠구에게 돌아가야 합니다.", description = "아라시 고원 전체는 말할 것도 없고, 스트롬가드 조차도 완벽히 자신의 휘하에 두지 못하고 있는 인간족의 왕자가 자신의 졸개 기병을 데리고 온 지역을 돌아다니고 있네. 도대체 그 이유를 알 수가 없단 말이야. 하기야 인간의 머릿속에 뭐가 들어 있는지 누가 알겠나?\n\n이유야 어쨌든 중요한 건 그가 기병 대장인 부관 밸러콜에게 인장을 맡겼다는 것이야. 부관 밸러콜을 찾아서 처치하고 인장을 내게 가지고 와주게.", progress = "밸러콜은 말을 타고 빠르게 이동하기 때문에 추적하기가 쉽지 않을 거야. 어쨌든 그의 인장이 반드시 필요하네.", completion = "기병대장을 잃었으니 스트롬가드 수호병들에게는 큰 타격이겠군. 더 기쁜 건 이제 인장을 하나만 더 확보하면 트롤칼라를 우리가 가질 수 있게 된다는 것일세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[644] = {title = "트롤베인의 인장", objective = "왕자 갈렌 트롤베인을 처치하고 해머폴에 있는 젠구에게 트롤베인의 인장을 가져가야 합니다.", description = "토라스 트롤베인의 무덤을 여는 데 필요한 마지막 인장은 그의 아들이 가지고 있네. 트롤베인의 아들은 스트롬가드의 깊은 곳, 수호대가 장악하고 있는 지역의 작은 예배당에 숨어 있어. 갈렌 왕자 주위는 경호가 삼엄한 데다가 본인도 막강한 전사이니 이번 임무가 가장 어려울 걸세.", progress = "돌아왔군. 이그네우스 트롤베인의 후손을 처치했나?", completion = "오늘은 아주 기분이 좋은 날이군. 앞으로 트롤베인의 후손이 더 이상 우리를 괴롭히지 못할 것이고, 트롤칼라를 손에 넣기 위해 필요한 인장을 모두 손에 넣었으니 머지 않아 줄구룹이 이끄는 우리의 트롤 적들을 무찌를 수 있게 될 걸세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[645] = {title = "트롤칼라", objective = "스트롬가드에 있는 트롤베인의 무덤에서 트롤칼라를 가지고 와야 합니다.", description = "이건 뭐지? 인장 네 개를 한 곳에 모았더니 하나의 인장으로 결합되었네. 분명 이 인장을 사용하면 트롤베인의 무덤에 설치된 봉인을 깨뜨릴 수 있을 거야.\n\n트롤베인의 유골은 스트롬가드 내부 성소 뒤편에 있는 지하 납골당에 묻혀 있네. 가서 트롤칼라를 되찾아 오게.", progress = "트롤베인의 무덤 앞에 있는 비석의 동판 모양이 이그네우스의 인장에서 나오는 빛 모양과 같습니다.", completion = "이그네우스의 인장에서 나오는 빛을 트롤베인의 무덤 앞에 있는 모양과 맞추자 섬광이 인장을 삼키고 돌로 된 손이 잡고 있던 전설의 검 트롤칼라를 놓습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[646] = {title = "트롤칼라", objective = "해머폴에 있는 젠구에게 트롤칼라를 가져가야 합니다.", description = "빛이 서서히 사라지며 돌로 된 칼집 안에 들어 있는 트롤칼라를 집었습니다.", progress = "검을 가지고 왔나?", completion = "수 세대에 걸쳐 스트롬과 아라소르의 힘이 트롤들을 괴롭혀 왔지. 이제 그들의 위대한 무기가 우리의 손에 들어왔네. 이제는 더 이상 짙은 안개에 쌓인 줄구룹의 숲으로 전진할 필요가 없게 되었군.\n\n자네의 원조가 정말 큰 도움이 되었네. 검은창 트롤이 자네에게 빚을 진 셈이군.\n\n이 검을 그롬골에 있는 님보야에게 보내도록 하겠네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n붉은 갑옷투사의 방패\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[647] = {title = "맥크릴의 위스키", objective = "사우스쇼어에 있는 양조업자 빌저에게 맥크릴의 위스키를 가져가야 합니다.", description = "어제 밤 오래 묵은 문샤인 위스키를 좀 마셨지. 보초를 서는 동안 술에 취해 버린 걸 알면 롱브레이드가 날 죽이려 들 거요.\n\n아, 술 좀 마셨더니 지독히 괴롭군. 머리 위로 전차 부대가 하나 요란하게 지나가는 것 같아.\n\n오, 이런! 시간이 이렇게나 됐군! 사우스쇼어에 있는 양조업자 빌저에게 위스키를 보내 밀린 외상값을 갚기로 했는데...\n\n갚기로 한 시간이 15분밖에 안 남았잖아! 부탁이니 이걸 좀 전해 주시오. 서둘러야 하오!", progress = "무슨 일이오?", completion = "아, 기분 좋은 날에 흥을 돋우는 데는 포기 맥크릴의 위스키만한 게 또 없지! 그 자가 외상값을 떼어 먹을 줄 알았는데... 흠, 어쨌든 정말 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[648] = {title = "OOX-17/TN 구출", objective = "OOX-17/TN을 스팀휘들 항구까지 호위해 간 후, 무법항에 있는 오글소프 오브노티쿠스에게 보고하십시오.", description = "로봇에서 노움의 목소리가 다시 흘러나옵니다.\n\n\"OOX-17/TN을 넓고 안전한 장소로 옮겨가야겠소. 긴 이륙 절차를 시작할 수 있도록 말이오. 은폐 기능이 탑재되어 있긴 하지만 다시 작동시키려면 나도 시간이 좀 필요하오. 그 로봇을 현재 위치에서, 보자... 그러니까, 스팀휘들 항구로 호위해주시오! 그곳이라면 이륙하기에 충분할 거요!\"\n\n\"항구까지 무사히 호위해 간 후에 무법항으로 와서 날 찾으시오! 이상, 오글소프 오브노티쿠스였소!\"", progress = nil, completion = "아, 당신이 OOX-17/TN을 구한 구세주였군! 얼마나 고마운지 이루 말할 수가 없소! 내 유도 로봇 시리즈는 아직 더 개발이 필요한데 당신이 회수해 준 덕분에 제작 비용은 물론이고 시간도 많이 벌게 됐소이다!\n\n자, 내가 가진 이 물건 중 아무거나 골라 보시오. 부디 당신이 유용하게 쓰게 되면 좋겠는데... 다시 한번 감사를 드리오. 나와 내 귀염둥이 꼬꼬가 당신에게 큰 신세를 졌소!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n굴절의 방패자동부화기 타이머\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[649] = {title = "리플 회수", objective = "오그리마에 있는 말톤 드로퍼스와 대화하십시오.", description = "당신이 뭘 좀 찾아와 줬으면 하는데. 당신도 나처럼 리플 애호가라면 이 일이 맘에 쏙 들 거요! 리플이라니까!\n\n술 말이야 술! 이런 바보하고는...\n\n버려진 호드 전초기지에 녀석들이 장사를 할 때부터 숨겨두었던 동부내륙지 벌꿀 리플이 있소이다. 그런 좋은 리플은 이제 더 이상 찾지도 못하지! 말톤의 멍청한 친구 녀석 중 하나가 어디 있는지 안다니까 가서 포장된 리플을 한 상자 가져다주시오. 아, 내 소장품으로 간직하게 두 개 더 가져오고! 말톤에게 얘기하면 자세히 알려줄 거요.", progress = nil, completion = "아, 아버지가 말씀하신 리플이요. 아버지는 여기 오그리마에 있는 선술집에 리플을 팔려고 하시죠. 그런데 포장된 상태로 팔면 돈을 더 받을 수가 있어요. 그 일을 할 줄 아는 자가 하나 있는데, 리플이 있는 동부 내륙지에 있어요. 그런데 그가... 하이 엘프라서요.\n\n뭐, 얼라이언스의 일원은 아니니까 좋은 하이 엘프라고 할 수 있지요. 아니, 늘 술에 취해 있어서 그렇게 좋다고도 할 수 없겠네요. 술을 정말 사랑하거든요. 말 그대로 사랑하지요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[650] = {title = "리플 회수", objective = "길버라딘 선체이서와 대화하십시오. 그의 야영지는 동부 내륙지에 있습니다.", description = "당신이 찾아갈 엘프의 이름은 길버라딘 선체이서라고 해요. 냄새만 맡고도 무슨 술인지 다 알아맞힐 정도의 애주가죠! 리플 포장도 할 줄 아니까 그와 대화해 보세요. 포장할 병은 모두 여섯 개예요. 두 개는 아버지께 드릴 거고요. 그자가 수고비를 얼마나 달라고 할지는 모르겠지만... 좀 요구하긴 할 거예요. 리플을 다 포장하고 아버지 드릴 두 병을 챙기면 여기로 돌아오세요!\n\n길버라딘의 야영지는 동부 내륙지의 어떤 하이 엘프 오두막 근처에 있는데 그곳 하이 엘프들이 조용한 성격은 아니랍니다. 제 말을 믿으세요.", progress = nil, completion = "아, 말톤과 아는 사이요? 내 오랜 술친구지. 나는 인위적인 조약과 동맹의 경계를 초월하는 것을 발견했소. 바로 술이지. 우리 모두 그 기막힌 맛으로 갈증을 해소한다면 영적으로 훨씬 더 평온하게 지낼 수 있을 텐데...\n\n하지만, 애석하게도 당신이 여기 온 이유가 술이 가진 정화의 가치를 배우기 위해서는 아닌 것 같군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[651] = {title = "마법진의 돌", objective = "서부 봉인석, 동부 봉인석, 외부 봉인석에서 각각 불타는 열쇠, 용마루장식 열쇠, 천둥 열쇠를 구해야 합니다.\n\n세 개의 열쇠를 내부 봉인석으로 가져가야 합니다.", description = "아라시 고원 전역에는 4개의 봉인석이 흩어져 있습니다. 이 돌들이 저를 땅속에 묶어 놓고 있는 거랍니다.\n\n4개의 돌을 모두 빼내려면 가장 강한 내부 봉인석을 빼내야 한답니다. 그러기 위해서는 다른 세 개의 돌에서 열쇠를 구해야 합니다.\n\n이 돌들은 수호자가 지키고 있는데, 당신이 머리를 쓰거나 운이 좋다면 수호자를 내쫓을 수 있을 거예요.", progress = "내부 봉인석입니다. 봉인석 중에서 가장 강력한 돌이며, 이 돌을 빼내면 나머지도 모두 열립니다.", completion = "&lt;돌을 통해 말하는 미즈라엘&gt;\n\n결국 해냈군요! 당신이 봉인석을 열었어요! 벌써 족쇄가 느슨해지는 게 느껴지는군요. 조금만 더 있으면 자유의 몸이 될 것 같아요.\n\n당신은 정말로 훌륭한 &lt;class&gt;|1이에요;예요;. 동시에 날 구해준 생명의 은인이시랍니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[652] = {title = "쐐기돌 깨기", objective = "포즈루크를 찾아 처치해야 합니다. 아라시 고원에 있는 쐐기돌에 질서의 마법봉을 가져가야 합니다.", description = "봉인석을 열어서 몸이 훨씬 자유로워졌지만 아직도 족쇄가 채워져 있답니다. 저 원형 모양의 돌 사이에 있는 게 쐐기돌입니다. 열쇠는 저를 가둬 놓은 자 중 한 명인 포즈루크가 가지고 있어요.\n\n거인 포즈루크에게서 저들이 질서의 마법봉이라고 부르는 열쇠를 빼앗은 후 쐐기돌을 열어야 합니다.\n\n지금까지 절 많이 도와 주신 것 알고 있습니다. 이제 조금만 더 도와주시면... 제 감사의 마음이 온 천하에 퍼지게 될 겁니다!", progress = "쐐기돌에는 거대한 대지의 기운이 담겨 있습니다.", completion = "마법봉을 쐐기돌에 넣습니다. 발 아래 땅이 흔들리는 것이 느껴집니다...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[653] = {title = "미즈라엘의 친구들", objective = "아이언포지의 쓸쓸한 뒷골목에 있는 게릭 본그립과 대화해야 합니다.", description = "<미즈라엘의 말>\n\n자유다! 이제 자유야! 저를 사로잡은 자들에게서 벗어나 이제서야 힘을 모을 수 있게 됐답니다. 혹시라도 그들과 다시 마주치면 절 힘으로 장악하여 다시 가둬 놓을 겁니다.\n\n하지만 때가 되면 제가 직접 거인들과 싸울 것이고, 저를 가둬 놓은 대가를 치르게 할 겁니다!\n\n당신은 이제부터 제 친구입니다. 때가 되면 저를 다시 한 번 도와 주시기 바랍니다. 제가 준비되면 지상으로 소환해 주시길 부탁드립니다.\n\n아이언포지의 쓸쓸한 뒷골목에 있는 게릭 본그립과 얘기를 나눠 보시기 바랍니다. 그는 날 소환하는 방법을 알고 있습니다.", progress = nil, completion = "공주님께서 당신이 올 거라고 얘기해 주시더군요. 정의로운 길을 걷는 &lt;class&gt;|1이여;여;, 이곳에 온 걸 환영합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[654] = {title = "타나리스 현장 견본 수집", objective = "타나리스 사막에 사는 바실리스크, 하이에나. 전갈에게서 쓸만한 바실리스크 견본, 쓸만한 하이에나 견본, 쓸만한 전갈 견본을 각 8개씩 구해야 합니다. 동력원이 다 떨어지기 전에 가젯잔에 있는 선임기술자 빌지위즐에게 분석 도구를 가져가야 합니다.", description = "동력원을 가동하자 휴대용 분석 도구가 빛을 발하며 진동하기 시작하는 것을 보니 계획한 대로 작동하는 것 같습니다.\n\n선임 기술자 빌지위즐에 의하면 타나리스 사막에서 필요한 자료를 수집하기 위한 시간이 두 시간 남았습니다. 두 시간 안에 다 수집하지 못하면 모든 자료를 잃게 되어 선임기술자 빌지위즐에게서 또 다른 동력원을 구해야 합니다.\n\n임무를 마치면 그에게 돌아가야 합니다.", progress = "그래, 필요한 건 다 모았나? 다 모으지 못했는데 동력이 다 떨어지면 안에 든 자료가 모두 파괴돼 버려 새로 시작해야만 한다고.\n\n이거, 나한테 동정을 구할 생각은 말아줘. 나는 가젯잔 수자원개발회사의 수익을 올리는 데만 관심이 있으니까 말이야. 그러기 위해 던 모로의 얼음 샘에서 물을 수입해 올 수 있을 때까지 당신에게 동력원을 팔아야만 한다면 그렇게 할 거라고!", completion = "그럼 좋아. 동력원을 제거하는 건 잠깐이면 될 거요. 그 후에는 안에 든 자료를 잃을 걱정 없이 얼마든지 당신이 원하는 대로 할 수 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[655] = {title = "해머폴", objective = "해머폴에 있는 토건과 대화해야 합니다.", description = "마치 어제와도 같이 선명하군... 이 끔찍한 곳에 갇혀서 수많은 해를 절망 속에서 지내왔지. 그러던 중 마침내, 마침내! 대족장님께서 나타나셨네. 검은 갑옷을 입고 워해머를 높이 든... 둠해머님이 말이야.\n\n그러나... 너무나 끔찍한 일이 일어나고 말았네... 비겁한 녀석의 단 한 번의 일격에 가장 위대한 영웅께서 쓰러지시다니... 그 비겁한 놈이 말을 타고 달려와 창으로 뒤에서 둠해머님의 등을 찔러 버리고 말았지... 난 무릎을 꿇고 말았네. 내 눈앞에서 희망이 사라지는 것을 보았어... 도대체 무슨 희망이 있었겠나? 무슨 희망이...", progress = nil, completion = "아, 고르멀을 만났나 보군. 그자는 아직도 둠해머님의 죽음으로 인한 충격 속에서 벗어나지 못하고 있는 모양이야.\n\n고르멀은 오그림 둠해머님과 스랄님께서 이곳을 해방시키기 위해 싸우실 때 포로로 잡혀있던 자이지. 하지만 지진이 일어나고 동지들이 모두 탈출했을 때 홀로 남게 되었네. 우리가 이곳 해머폴에 정착하기 위해 돌아올 때까지 그는 수 년간 정처없이 홀로 방황하고 있었지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[656] = {title = "공주 소환", objective = "미즈라엘의 결정으로 가서 그녀를 소환한 후에 처치해야 합니다.\n\n기괴한 족쇄를 주워서 다시 미즈라엘의 결정에 봉인해야 합니다.", description = "미즈라엘이 힘을 되찾기 전에 처치해야 해. 그렇지 않으면 힘을 회복한 후에 자기를 가둬 놓았던 자들을 해치러 갈 거야! 어떤 녀석들은 미즈라엘을 통제할 수 있다고 생각하는데, 그건 다 착각이라고. 그게 가능하다면 애당초 왜 거인들이 그녀를 묶어 놓았겠어??\n\n말도 안 되지, 안 그래?\n\n미즈라엘을 무찌르려면 그녀와 처음 얘기를 나눈 미즈라엘의 결정에서 이 두루마리로 그녀를 소환해야 해. 그녀를 무찌르고 기괴한 족쇄를 주은 다음 미즈라엘의 결정에 봉인해 놔.\n\n그러면 다시 갇히게 될 거야.", progress = "이제 미즈라엘의 결정은 이상하게도 아무 말이 없습니다.", completion = "기괴한 족쇄를 결정 주위에 두자 인간의 비명소리라고 할 수 없는 울부짖음이 먼 곳에 들려 옵니다. 울부짖음 끝에 으르렁거리는 소리가 들려 옵니다.\n\n이제 더 이상 미즈라엘의 결정에서 예전에 느꼈던 따뜻하고 안전한 느낌을 받을 수 없습니다. 대신 위협적인 분노가 내뿜어져 나오고 있습니다. 마치 아래 갇힌 존재가 지상에 큰 원한이 있는 것처럼...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n고동치는 수정 결정"},
[657] = {title = "새로운 역병의 징조?", objective = "키넬로리와 대화해야 합니다.", description = "<서류를 읽기 시작하는 쿠에>\n\n이건 꽤 흥미롭군요. 연금술사 조렐이 이곳 고셰크 농장에서 치명적인 실험을 하고 있었던 것 같아요. 힐스브래드하고 어떤 관계가 있는지는 확실하지 않지만 핀이 이걸 그대로 내버려 두는 걸 원치는 않을 거예요.\n\n당신이 가 있는 동안 오크 몇 마리와 싸우다가 상처를 좀 입어서 이 몸으로는 키넬로리를 도와 주기 어려워요. 가능하다면 당신이 키넬로리를 보호해 주지 않겠어요? 그러면 그녀가 농장으로 들어가 조렐이 아직 타렌 밀농장에 보내지 않은 물건들을 훔쳐 올 거예요.", progress = nil, completion = "핀이 마음의 평온을 되찾을 수만 있다면 내가 직접 포세이큰을 모조리 없애 버릴 겁니다. 다시는 친구나 가족 같은 이들을 만날 수 없다고 생각했는데 그는 역병이 일어난 이후로 우리에게 너무나 많은 걸 해 준 고마운 사람입니다.\n\n준비가 되면 내게 알려 주세요. 곧바로 시작할 테니까요.", rewards = nil},
[658] = {title = "새로운 역병의 징조?", objective = "포세이큰 급사를 찾아서 봉인된 서류를 고셰크 농장 근처에 있는 쿠에에게 가져가야 합니다.", description = "그러니까 핀이 우리가 잘못되지 않았는지 걱정돼서 당신을 보냈다고요? 하기야 놀라운 일도 아니죠. 핀은 워낙 걱정이 많은 성격이니까요.\n\n우리는 며칠 간 농장을 지켜보고 있었는데, 얼마 전에 키넬로리가 저기 남쪽에 있는 작은 집에서 급사가 빠져나가는 것을 봤다고 하더군요.\n\n키넬로리가 평소에 말이 많긴 하지만 위험한 지역에서는 매우 정확한 감각을 자랑한답니다.\n\n참, 혹시 당신도 실력 있는 수색자인가요? 우리 생각에는 급사가 타렌 밀농장으로 전갈을 가지고 간 것 같아요. 그 서류를 우리 손에 넣을 수 있으면 힐스브래드에서 일어나는 일에 대한 단서를 얻을 수 있을지도 몰라요.", progress = "급사를 찾는데 도움을 줘서 고마워요.\n\n당신이 가 있는 동안 키넬로리가 이곳의 남쪽에 있는 작은 집에서 연금술사가 빠져나가는 것을 봤다고 하네요. 분명히 사악한 일을 꾸미고 있는 게 틀림없어요. 하지만 증거가 필요해요. 그렇지 않으면 괜히 성급하게 행동하는 것일 수 있으니 말이죠.\n\n아직 그 서류는 못 구했나요?", completion = "훌륭하군요! \n\n자, 어떤 내용인지 한 번 볼까요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[659] = {title = "새로운 역병의 징조?", objective = "아라시 고원에 있는 고셰크 농장 근처에서 쿠에와 키넬로리를 찾아야 합니다.", description = "만나서 반갑소. 난 이 지역 안에서 일어나는 이상한 일들을 조사하는 모험가 집단을 이끌고 있소이다.\n\n힐스브래드에 사는 내 사촌은 최근에 기르고 있던 개, 스탠리를 죽여 버릴 수밖에 없었소. 이상하게 개의 몸집이 점점 거대해지더니 근처에 오는 모든 이들을 사납게 공격했기 때문이라오.\n\n내 생각에는 언데드가 이 일에 관련되어 있는 것 같아 이를 증명할 증거를 찾고 있소.\n\n내 동료 중 두 명, 쿠에와 키넬로리가 아라시 고원에 있는 고셰크 농장으로 갔는데 며칠 동안 아무 연락이 없다오. 그들을 찾아봐 주겠소? 점점 걱정이 되기 시작해서 말이오.", progress = nil, completion = "최대한 조용히 하세요.\n\n오크들은 몰래 감시당하는 걸 그냥 넘어가지 않거든요. 게다가 이곳에는 눈에 보이는 것보다 훨씬 많은 오크들이 숨어 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[660] = {title = "새로운 역병의 징조?", objective = "키넬로리가 쿠에에게 돌아갈 때까지 보호해야 합니다.", description = "좋아요. 난 언제나 준비되어 있답니다.\n\n그럼 시작할까요?", progress = "이제 말보다는 행동을 할 때예요. 힐스브래드 주민을 조금이라도 걱정한다면 키넬로리를 엄호해 줘요.", completion = "정말 큰 도움을 받았군요. 고마워요.\n\n키넬로리가 아래에서 말썽을 많이 안 일으켰으면 하네요. 천성이 본래 친절한 성격이긴 하지만 적에게는 아주 사납거든요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[661] = {title = "새로운 역병의 징조?", objective = "사우스쇼어에 있는 핀 오델릭을 찾아가야 합니다.", description = "키넬로리의 현재 모습이 지난번에 선술집에서 하룻밤 묵고 나서의 모습보단 낫군요. 여기까지 정말 잘 호위해 주셨네요.\n\n그녀가 농장에서 가져온 물건을 핀이 보면 이곳 아라시에서 대충 어떤 일이 벌어지고 있는지 짐작할 수 있을 거예요. 보복 공격이 없는지 확인하기 위해 우리는 이곳에 좀 더 남아 있을게요. 먼저 사우스쇼어로 가서 핀에게 얘기해 주겠어요?", progress = nil, completion = "그러니까 결국 두 말썽꾸러기 모두 괜찮다는 거요? 하하, 반가운 소식이구려. 그들의 위치와 상황에 대한 소식을 알려 줘서 고맙소. 둘 다 무사하다는 소식을 들으니 정말 기쁘오. 그 두 아가씨는 나에겐 훌륭한 친구이자 여행 동료라오.\n\n하지만... 지금은 도와 준 데 대한 정당한 대가를 드리는 것이 더 중요한 듯하군. 자, 감사의 표시로 이걸 받으시오.\n\n행운이 따른다면 포세이큰이 어떤 음모를 꾸미고 있는지 알아내고 그 음모를 막을 수 있을 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n가루비 로브빛길 다리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[662] = {title = "심해의 인양 작업", objective = "일등항해사 닐즐릭스가 메이든즈 폴리호와 실버파인 스피릿호에서 해도와 항해일지를 찾아 달라고 부탁했습니다.", description = "여어, 안녕! 오브린 선장님께서 배를 후미로 이동하라고 지시하셨지. 우리는 여기에서 분명히 보물을 찾을 수 있을 거라고 생각했다고. 하빈저호는 무사히 정박했는데 메이든즈 폴리호와 실버파인 스피릿호가 육지에 접근하자 갑자기 조수가 낮아지기 시작했지. 태어나서 여태컷 그때처럼 이상한 일은 처음 봤다니까!\n\n두 배는... 마치 암초 위의 사원 같은 곳에 좌초되었고 순식간에 침몰했지. 비극 그 자체였어.\n\n우린 이곳을 떠나기 전에 그 두 배의 항해일지와 해도를 되찾아야 해. 정보가 남의 손에 들어가서는 안 돼!", progress = "부탁한 일은 잘 되어가고 있나? 메이든즈 폴리호와 실버파인 스피릿호의 항해일지와 해도가 꼭 필요하다고.\n\n만약 그 정보가 적의 손에 들어가면 시혼 함장님이 우리를 바다에 빠뜨려 익사시켜 버릴 거란 말이야.\n\n혹여 이 난장판에서 벗어날 수 있다 하더라도 말이지...", completion = "정보가 유출되지 않았다는 걸 무법항에 있는 함장님이 아시면 어느 정도 안심할 수 있을 거야. 잘했어, 친구.", rewards = "다음과 같은 것들을 받습니다:\n\n검은바다 망치"},
[663] = {title = "육지다!", objective = "팔디르의 만에 있는 선장 오브린과 대화해야 합니다.", description = "롤로 눈에 작은 <race>|1이;가; 보인다! 롤로 항상 망 보고 있다!\n\n팔디르의 만에 온 걸 환영한다. 오브린 선장이 여기 몇 시간만 있으면 된다고 했다. 보물을 모아서 무법항으로 가져가기만 하면 된다고 했다.\n\n하지만 롤로 생각하기에는 시간이 더 오래 걸릴 것 같다. 우리 함대에서 배 두 개 잃었다. 불쌍한 실버파인 스피릿호와 메이든즈 폴리호... 지금은 저 바다 밑에 자고 있을 거다!\n\n여기서 쉴 거면 오브린 선장과 얘기해 보는 게 좋을 거다.", progress = nil, completion = "이보시오, &lt;class&gt; 친구.\n\n아주 난리도 아니었소. 무슨 일이 일어났는지 시혼 함장님이 알아차리면 내 배들을 전부 가져가 버릴 거야.\n\n학자 피즐솔프가 발명한 장치에 의하면 잃어버린 보물이 이 후미 근처에 있다고 하는군. 그래서 난 하빈저호를 항구에 정박하고 실버파인 스피릿호와 메이든즈 폴리호로 하여금 뒤따르라는 신호를 보냈었소.\n\n그런데 그때 바로 바다가 소용돌이치기 시작했고 조수가 낮아져서 이 두 배가 암초에 부딪히고 말았소.\n\n그런데 사실 그냥 암초 같지는 않았고... 저 아래 뭔가 있는 것 같단 말이야... 저기 내 선원들을 도와주면 섭섭하지 않게 보상받을 수 있을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[664] = {title = "비통한 마음", objective = "팔디르의 만에 있는 선장 스틸구트가 비수가시일족 침략자 10마리와 비수가시일족 여마법사 3마리를 처치해 달라고 부탁했습니다.", description = "아, 정말로 끔찍한 삶이로군. 난 지금 여기에 불가에 앉아 맑은 공기로 숨 쉬고 있을 게 아니라 진작에 물속에 빠져 죽었어야 해.\n\n선원들이 아름다운 메이든즈 폴리호를 지키기 위해 그렇게 노력했건만... 그들에게 명복을, 그들의 영혼에 평온이 있기를.\n\n오브린은 해안에 안전하게 다가갈 수 있었지만 우린 운이 나빴어. 바다가 우리를 위에서 덮쳤지, 정말일세.\n\n분명히 수면 위에 있었는데 갑자기 위에서 물이 우리를 덮쳤지 그리고 그 짐승들도! 그 짐승들이 생존자를 모두 죽여 버렸다네. 흉측한 나가 놈들 말일세. 난 정신을 잃었는데 깨어나 보니 이곳에 이렇게 살아 있더군.\n\n제발, 그 짐승들을 좀 죽여 주게.", progress = nil, completion = "잘했네. 그놈들은 죽어 마땅했어.\n\n물론 어떻게 하더라도 내 배나 선원들이 돌아오는 것은 아니지만 그 나가들이 죽었다니 그래도 좀 위안이 되는군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n해적 장갑"},
[665] = {title = "가라앉은 보물", objective = "학자 피즐솔프가 동굴에 들어갔다 나올 수 있도록 호위해야 합니다.", description = "자, 이제 우리도 어엿한 검은바다 해적단이니까 오브린 선장이 잃어버린 엘프의 보물을 찾도록 도와 주어야 한다오.\n\n아무런 도움없이 어두운 바다 속에서 보석을 찾는다는 건 거의 불가능한 일이지. 드랙슬게이지가 고글을 몇 개 만들어 놓았다오. 언덕 바로 위의 동굴 속에 있는 마법의 돌에서 힘을 끌어와 고글에 불어넣어야 한다더군.\n\n그런데 그 동굴에는 저주가 걸려 있다오! 가까이 다가가면 공격을 받을 것이야. 그러니까 당신은 내가 고글에 마법의 돌의 힘을 채울 수 있도록 보호해 주면 된다오.", progress = "더 이상 이야기 나눌 시간은 없다니까! 마법의 돌의 힘을 고글에 불어넣어야 한다고!", completion = "이제 고글이 완벽하게 작동하는군! 잘했소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[666] = {title = "가라앉은 보물", objective = "팔디르의 만에 있는 발명가 드랙슬게이지가 엘프의 보석 10개를 주워 오고 이 일을 끝낸 후 보물찾기 고글을 돌려 달라고 부탁했습니다.", description = "에, 보물이 해저에 가라앉은 지 하도 오래돼서 보석이 전부 단단한 돌로 굳어져 버렸소. 하지만 이 고글에 담긴 힘 덕분에 보석을 쉽게 찾아낼 수 있을 거라오.\n\n이 키 작은 노움의 재간이 정말 뛰어나지 않소?\n\n자, 그러니까 보물찾기 고글을 빌려가서 오브린 선장을 위해 잃어버린 보물을 찾아 오시오.\n\n내가 직접 아래로 헤엄쳐 갈 수도 있지만... 음... 그러니까, 안전한 육지에서 과학적으로 중요한 일이 자주 발생하니까... 그러니까... 난 여기 자리를 지켜야 한단 말이지.", progress = "고글은 어떻게 됐지? 모든 기능이 제대로 작동하나? 필요하다면 손을 좀 볼 수도 있소.\n\n참, 그리고 일을 마친 후에 고글을 돌려주는 것 잊지 말라고. 나중에 오브린 선장이 여러 가지로 유용하게 사용할 수 있을 테니까 말이야.", completion = "훌륭해! 선장이 매우 기뻐하겠군! 그리고 시혼 함장님께 이 사실을 전달할테니 잠시 기다려 달라고!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n노움의 요술봉서보기구 해머\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[667] = {title = "나가의 공격", objective = "나가의 공격으로부터 셰익스 오브린을 보호해야 합니다.", description = "큰일이군. 비수가시일족 녀석들이 공격을 하려고 모이는 모양이야.\n\n나가는 전투에서 잔악하기로 유명한 녀석들이라 내가 죽을 때까지 계속해서 공격할 것이오.\n\n내가 내 선원들보다 내 목숨을 아끼는 건 아니지만 나만큼 바다에 대해 잘 아는 자가 없으니 내가 없으면 어차피 선원들도 무법항까지 돌아가지 못할 것이야. 그러니 날 꼭 지켜 줘야해.\n\n나가 녀석들은 바다에서 접근해 올 것이오. 나와 함께 이 위에 남아 녀석들의 공격을 막아주시오. 배 위에 있는 대포를 이용해서 녀석들을 몰아내시오.\n\n준비는 됐소?", progress = nil, completion = "우린 공격을 막아내고 살아남았소!\n\n당신이 없었다면 해내지 못했을 것이야.\n\n우리는 조수가 차오르면 바로 떠날 것이오. 당신이 그토록 장래가 창창한 영웅이 아니었다면 내 선원으로 삼고 싶지만, 보아하니 더 큰 일을 해야 할 것 같군.\n\n덩치는 작아도 말이야...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n얼음 반지불바다 반지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[668] = {title = "가라앉은 보물", objective = "선장 오브린에게 엘프의 보석을 가져가야 합니다.", description = "오브린 선장이 오래 기다리지 않도록 하라고. 보석을 발견하는 즉시 가져오라고 했단 말이지. 결국은 그것 때문에 우리가 여기 있는 것이지!\n\n그리고 몇 주 동안 해적들과 어울리면서 피즐솔프와 내가 얻은 교훈은 이들의 보물을 오래 가지고 있으면 신상에 절대 이롭지 못하다는 거야.\n\n자, 이 보석들을 오브린 선장에게 가져가라고.", progress = "여어, <class> 친구. 무슨 일로 왔지?", completion = "그러니까 저 작은 &lt;race&gt; 친구들이 결국 실력 발휘를 했다 이건가? 하하, 내 그 꼬맹이들을 데리고 다니면 쓸모가 있을 거라고 짐작했었지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[669] = {title = "가라앉은 보물", objective = "무법항에 있는 시혼 함장에게 엘프의 보석 표본을 가져가야 합니다.", description = "시혼 함장님께 이 사실을 즉시 보고해야 하오.\n\n그런데 당신도 보다시피 이곳을 빠져나가기가 상당히 곤란하단 말이지. 조수가 낮을 뿐만 아니라, 일단 몰아내기는 했지만 빌어먹을 짐승들이 우리를 계속 노리고 있소.\n\n당신이 무법항에 계신 시혼 함장님께 보물을 발견했다는 사실과 현재 계속 끌어올리는 중이라고 보고해 주면 검은바다 해적단에게 정말 큰 도움을 주는 것이야. 증거로 이 표본을 가져가도록 하시오.", progress = "무법항에는 무슨 일인가, <class>?", completion = "아, 노련한 셰익스 오브린이 결국 성공했군! 하하, 그가 이 임무에 적임이란 걸 알고 있었어!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[670] = {title = "가라앉은 보물", objective = "아라시 고원에 있는 셰익스 오브린에게 시혼의 봉인된 편지를 전달해야 합니다.", description = "말해보게, <class>. 자네는 모험을 꽤 즐기는 것 같아. 보급품을 새로 장만할 때까지는 내 함대가 무법항을 벗어날 수 없다네.\n\n그런데 이곳 저곳에서 심각한 문제들이 발생하고 있어서 아라시 해안에 갇혀 있는 셰익스 오브린에게 극비 문서를 보내야 하는데 말이야.\n\n이 편지를 자네가 훔쳐 보지 않고 안전하게 배달해 줄 것을 믿어도 되겠지?", progress = "시혼 함장님께서 감동하셨소? 분명히 입이 귀에 걸릴 정도로 좋아하셨을 테지.", completion = "이토록 길고 험난한 여행을 감내해 주어서 고맙소. 검은바다 해적단의 이름으로 당신에게 경의를 표하는 바이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[671] = {title = "사악한 마법", objective = "해머폴에 있는 토건에게 혈석 아뮬렛 10개를 가져가야 합니다.", description = "지난 밤 뭔가 이상한 기운을 느꼈네. 내 피를 들끓게 하는 기운을... 의심 가는 데가 있긴 하네. 나를 불안하게 하는 기운의 근원을 찾아 보았더니 서쪽의 북부습곡 장원에서 악마를 소환한 흔적이 있더군. 좀 더 가까이 다가가자 피가 끓기 시작했고 분노가 치밀어 오르기 시작했네.\n\n악마를 소환하는데 사용한 혈석 아뮬렛을 바닥에서 주웠지만 내가 발견한 아뮬렛은 이미 그 힘이 고갈되어 있었네. 조사를 계속하려면 다른 아뮬렛이 필요한데, 감히 그곳에 다시 돌아가지는 못하겠군. 자네가 몇 개를 가져다주겠나?", progress = "한때 저주받았던 피가 아직도 내 혈관을 흐르고 있네. 누군가... 누군가 악마를 소환하고 있다면 반드시 막아야 해.", completion = "비밀결사대의 진정한 목적을 파악하는 데는 시간이 걸리겠지만 사악한 암흑의 마법과 결탁했다는 사실은 분명해졌군. 걱정이 되는 일이야. 나중에 더 많은 걸 알게 되면 알려 주도록 하겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[672] = {title = "되살아나는 영혼", objective = "줄무늬 고원랩터와 외뿔 고원랩터에게서 고원 랩터 눈 10개를 구해 해머폴에 있는 토건에게 가져가야 합니다.", description = "우린 그에게 칼림도어의 오그리마라는 우리의 강력한 도시에 대해 이야기해 주며, 진정시키고 위로하려고 노력했지만 아무것도 그의 마음을 움직이지 못했네.\n\n둠해머님의 갑옷과 워해머를 이어받은 우리의 젊은 대족장 스랄님에 대한 이야기도... 하지만 어쩌면... 그래, 그러면 될지도 몰라! 우리가 새로 발견한 주술을 보여 주면 다시 희망을 가지게 될지도 모르겠군. 한 번 시도해 볼 만하군그래!\n\n그를 위해 작은 물건을 하나 만들 수 있을 텐데... 그래! 랩터 눈을 몇 개 가져다주게. 그럼 내가 뭔가 할 수 있을 것 같아.", progress = "고르멀에게 랩터의 힘을 약간 불어넣을 수 있는 아뮬렛을 만들어 주겠네. 어쩌면 이게 그의 마음속 열정을 되살려 줄지도 모르지...", completion = "훌륭하군. 이 눈들의 주인인 랩터의 영혼이 이 아뮬렛을 지니고 다니는 이에게 힘을 불어넣어 줄 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[673] = {title = "사악한 마법", objective = "마레즈 코울의 더럽혀진 혈석 수정구를 빼앗아 해머폴에 있는 토건에게 가져가야 합니다.", description = "스트롬가드의 성벽 내부에 아주 강력한 흑마법사가 있다네. 간혹 이 흑마법사는 신비한 마법의 유물을 사용하여 끔찍한 악마를 대량으로 소환하곤 했지. 우린 그가 가지고 있는 힘의 근원을 파괴해야 하네.\n\n흑마법사를 찾아서 처치하도록 해. 그에게서 발견한 마법 물건을 가지고 오면 내가 직접 파괴하여 더 이상 이 땅을 더럽히는 데 사용하지 못하도록 하지.", progress = "날이 지날수록 내 피가 더욱 들끓고 있네. 흑마법사의 계략을 막아야 해.", completion = "이 수정구를 파괴하면 드디어 발 뻗고 편히 잘 수 있겠군. 고맙네. 헬스크림님께서 그들을 저주에서 벗어나게 해 주기시기 전 악마의 힘에 억눌려 있었던 시절을 기억나게 하는 물건이로군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n흰색 비룡가죽 모자빛나는 은색 팔보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[674] = {title = "되살아나는 영혼", objective = "고르멀에게 랩터 발톱 아뮬렛을 전달해야 합니다.", description = "자, 이 아뮬렛을 고르멀에게 가져다주고 랩터의 힘이 한때 그의 몸 속에 타오르던 용사의 열정을 되살릴 수 있는지 보라고.", progress = "한낱 겁쟁이의 손에 최강의 영웅이 죽는 마당에 대체 무슨 희망이 있단 말인가? 무슨 희망이 있느냔 말이야!", completion = "이건 뭐지? 뼈로 만든 물건이군. 이런 물건을 가지고 뭘 하라는 건가? 하찮은 장신구가 호드를 다시 영광의 시대로 이끌 수 있단 말인가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[675] = {title = "되살아나는 영혼", objective = "토건과 대화해야 합니다.", description = "<고르멀이 아뮬렛을 땅에 버리며>\n\n토건이 자네를 보냈나? 그렇지? 흥, 그가 내게 왜 이런 자비를 베푸는지 도저히 이해할 수 없군. 전투에서 대족장님과 함께 죽지 못했다는 것 자체가 이미 신의 자비가 나를 버린 거야. 너무나 잔인한 운명이지...", progress = nil, completion = "음, 생각대로 되지 않았군. 하지만 주술사의 힘을 계속 보여 주면 고르멀도 결국 원래의 강력한 모습을 되찾을 수 있을 거야. 이 아뮬렛의 힘은 우리가 새로 발견한 힘을 충분히 보여 주지 못한 것 같아.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[676] = {title = "해머폴 함락 위기", objective = "돌주먹 오우거 8마리와 돌주먹일족 집행자 10마리를 처치한 다음 아라시 고원의 해머폴로 가서 드럼 펠을 찾아야 합니다.", description = "전부 약해 빠진 놈들뿐이니... 이봐, 뭘 쳐다보는 거요? 당신은 스스로 뭔가 특별하다고 생각하는 모양이군. 그럼 한번 중명해 보시지 그러시오?\n\n아라시의 해머폴 기지가 공격받고 있소. 서둘러 지원군을 보내지 않으면 곧 붕괴하고 말 거요.\n\n하지만 그 전에 우선 당신의 능력을 시험해 보는 게 좋을 거요. 아라시 고원의 스트롬가드 북동쪽에 있는 오우거 고분에 돌주먹일족이 살고 있소. 그곳의 오우거들과 집행자들을 처치한 후 해머폴에 있는 드럼 펠에게 보고하도록 하시오.", progress = nil, completion = "흠, 우리를 도와 해머폴을 방어할 자신이 있다고 생각하나? 정말 그랬으면 좋겠군.\n\n탈로우가 오우거 소굴로 당신을 보냈다는 것은 당신이 죽고 싶어 안달이 났다고 생각했거나, 당신이 정말 우리를 도울 만큼 강하다는 생각에서였겠지. 어쨌거나 우리야 계속되는 적의 공격에 맞서기 위해서 병사 한 명이라도 아쉬운 마당이니 도와주겠다면 마다할 이유는 없소.\n\n해머폴에 오래 머무를 생각이라면 충분히 휴식을 취한 후에 내게 다시 오시오. 아마 전투라면 질리도록 하게 될 테니.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[677] = {title = "전장으로", objective = "마른나무껍질부족 도끼투척병 10명과 인간사냥꾼 10명, 의술사 8명을 처치하고 해머폴 전초기지에 있는 드럼 펠에게 돌아가야 합니다.", description = "아라시의 마른나무껍질 트롤과 돌주먹 오우거가 우리를 이 땅에서 몰아내려 안간힘을 쓰고 있소. 하지만 이 세상 어느 누구도 우리를 몰아낼 수는 없지. 우린 그들에게 이곳이 우리의 땅이기도 하다는 것을 보여 줄 것이오.\n\n그 트롤들은 우리에게 등을 돌려버렸소. 그리고 오우거들은 우리를 먹잇감 정도로 생각하고 있는데다가 우리의 가죽을 벗겨 침구로 사용하려 하고 있소. 이런 일은 절대 일어나서는 안 되지.\n\n우선 우리는 남쪽에 있는 마른나무껍질 트롤을 공격할 계획이오. 당신도 녀석들을 닥치는 대로 처치하고 녀석들의 야영지가 피로 물들 때까진 돌아오지 마시오.", progress = nil, completion = "옷과 이마에 흐르는 땀을 보니 전투를 치르고 온 모양이군. 잘했어, 아주 잘했어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[678] = {title = "전장으로", objective = "돌주먹일족 투사 10마리와 돌주먹일족 사제 4마리를 처치한 다음 해머폴 전초 기지에 있는 드럼 펠에게 돌아가야 합니다.", description = "당신의 전투 실력은 탁월하군. 그러면 이번에는 더 강한 녀석들을 한 번 상대해 보겠소?\n\n돌주먹일족의 소굴은 이곳의 남서쪽, 드워프 다리 방향에 있소. 그리고 그곳에 있는 돌주먹일족 싸움꾼과 사제는 아주 강력한 상대들이오. 지금까지 우리에게는 그랬었지.\n\n이들을 최대한 많이 쓰러뜨리고 돌아오시오. 살아서 돌아오든가 죽어서 귀신이 되어 돌아오든가... 어떻게 되든 전장에서 벌인 당신의 활약은 칭송을 받을 거요.", progress = nil, completion = "당신은 정말 코도만큼이나 강하군. 전투에 대한 당신의 열정을 높이 사오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[679] = {title = "전장으로", objective = "돌주먹일족 주술사 15마리와 돌주먹일족 우두머리 10마리를 처치한 다음 해머폴 전초 기지에 있는 드럼 펠에게 돌아가야 합니다.", description = "이제 그 짐승들의 우두머리를 해치울 때가 왔소. 지금까지 보여 준 모습을 보면 이 마지막 임무를 수행하는 데는 당신이 적격인 것 같군. 침략자의 우두머리는 인간의 연약함을 상징하는 스트롬가드에 자신들의 소굴을 만들었소.\n\n돌주먹일족 우두머리와 그들의 부하인 주술사를 찾아서 죽이시오. 그들이 우리를 그 땅에서 쫓아낸 자들이오.", progress = nil, completion = "정말 자랑스럽소. 위협이 많이 줄어들었으니 이제 우리도 이곳 아라시 고원에서 세력을 키워나갈 수 있을 거요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n소리없는 사냥꾼 단도전투해골 절단기\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[680] = {title = "거대한 위협", objective = "오르칼라를 처치하고 그 증거로 그의 머리카락을 해머폴 전초 기지에 있는 코린 펠에게 가져가야 합니다.", description = "수고하셨어요. 내 남편이 당신에게 준 임무를 아주 잘 완수해냈더군요. 하지만 그이는 왜 해머폴이 공격 받고 있는지는 잘 모르고 있어요.\n\n스트롬가드에 있는 무그톨의 부하, 오르칼라는 내 남편을 매우 증오하고 있습니다. 몇 년 전부터 내 남편을 없앨 궁리만 하고 있을 정도니까요.\n\n점을 쳐 본 결과 오르칼라가 내 남편을 함정에 빠뜨릴 계획인 모양이더군요. 그래서 난 남편이 오르칼라의 행방을 알 수 없도록 오르칼라에게 마법을 걸어 두었습니다.\n\n내 남편은 오우거만 보이면 무조건 쳐들어갈게 뻔하니까요. 당신이 그 짐승을 대신 없애 주었으면 합니다.", progress = "아라소르의 탑 근처에 가면 오르칼라를 찾을 수 있을 겁니다. 그가 죽으면 해머폴에 대한 공격도 멈출 것이고 내 남편도 무사할 수 있겠죠.\n\n당신 눈을 보니 나를 나약하고 나쁜 아내로 생각하고 있는 듯하군요. 하지만 당신도 언젠가는 내 방식의 사랑이 진정한 사랑이란 걸 알게 될 겁니다. 아마도 당신이 경험한 힘이나 존경의 대상과는 다른 어떤 것이라는 점을 이해하게 될 거예요.\n\n아무튼 부탁한대로 오르칼라를 처치해 주십시오.", completion = "정말 큰 일을 해냈군요. 당신 덕분에 내 남편의 목숨과 해머폴의 안녕이 계속 유지될 수 있게 되었습니다. 자, 이건 노력에 대한 대가라 생각하고 받아 주세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n눈보라 킬트해머폴의 검\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[681] = {title = "북부습곡 장원", objective = "비밀결사대 강도 10명과 비밀결사대 용병 6명을 처치해야 합니다.\n\n임시 주둔지에 있는 부대장 나이얼스에게 돌아가십시오.", description = "우리는 스트롬가드에서 전쟁 중입니다만 요즘 전황이 좋지 않습니다. 오우거, 비밀결사대 그리고 우리 이렇게 세 세력이 한때 거대했던 우리의 도시를 나눠 가지고 있으며 서로 간에 피 튀기는 싸움을 벌이고 있습니다.\n\n하지만 적들은 병력이 점점 많아지는 반면 우리는 점점 줄어들고 있으니...\n\n사우스쇼어 마을의 도움을 받아야 하는데, 비밀결사대가 중간 지역을 장악하고 있기 때문에 보급품을 받기가 어렵습니다.\n\n북부습곡 장원에 있는 비밀결사대 기지로 가 그들을 해치워 주시기 바랍니다. 그러면 우리의 보급 부대가 좀 더 안전하게 통과할 수 있을 겁니다.", progress = nil, completion = "좋습니다. 장원에 있는 비밀결사대 병력을 많이 없앴으니 사우스쇼어에서 보급품을 훨씬 쉽게 운송 받을 수 있을 겁니다.\n\n아직 우리에게 희망이 있는 건지도 모르겠군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[682] = {title = "스트롬가드 휘장", objective = "임시 주둔지에 있는 부대장 나이얼스에게 스트롬가드 휘장 15개를 가져가야 합니다.", description = "스트롬가드의 비밀결사대가 그곳에 파견된 우리의 수비대와 싸우고 있습니다. 비밀결사대 지도자들은 자신들의 부하를 자극하기 위해 우리 병사의 목에 현상금을 걸었습니다. 듣자하니 수비대를 죽이고 스트롬가드 휘장을 가져오면 금화를 준다고 하더군요.\n\n우리는 그 휘장을 되찾아 왔으면 합니다. 저 살인자들이 쓰러진 우리의 용맹한 병사들을 전리품처럼 여기는 꼴을 보고 있을 수는 없습니다!\n\n스트롬가드에서 비밀결사대가 장악한 지역으로 들어가 그들을 없애고 휘장을 되찾아 와 주시기 바랍니다.", progress = "스트롬가드 휘장을 가지고 왔습니까? 비밀결사대 놈들에게 우리 병사들의 시체를 놀림감 삼아서는 안 된다는 것을 가르쳐 주어야 합니다.", completion = "고맙습니다. 죽은 병사들의 유가족에게는 &lt;class&gt; 통보를 해 주어야겠습니다.\n\n견디기 힘든 슬픈 소식이겠지만 사랑하는 이가 죽었는지 살았는지 모르는 것보다야 낫지 않겠습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n스트롬가드 기병대 다리보호구"},
[683] = {title = "사라 발루의 탄원서", objective = "아이언포지에 있는 마그니 브론즈비어드 국왕에게 사라 발루의 탄원서를 전달해야 합니다.", description = "제 작은 부탁을 들어 주시겠어요?\n\n이 탄원서를 아이언포지의 위대한 마그니 브론즈비어드 국왕님께 전해 주세요. 당신처럼 얼라이언스를 위해 위대한 업적을 쌓은 분께 이렇게 사소한 부탁을 드리는 것이 송구스럽긴 하지만...\n\n지금 제가 이렇게 눈물 젖은 모습으로 국왕님을 알현하면 실수라도 하게 될 것 같아서요. 이해해 주시리라 믿습니다.", progress = "그래, 그대가 그 유명한 <class>인가? 얼라이언스를 위해 세운 업적은 실로 모르는 사람이 없을 만큼 널리 퍼져 있더군.\n\n그래, 오늘은 무슨 일로 짐을 찾아왔는가?", completion = "잠시 이 탄원서를 읽어 보도록 하겠다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[684] = {title = "마레즈 코울 현상수배!", objective = "마레즈를 처치하고 그 증거로 그녀의 머리카락을 임시 주둔지에 있는 부대장 나이얼스에게 가져가야 합니다.", description = "비밀결사대의 고문이자 상급 첩자인 마레즈 코울에게 현상금을 거는 바이다. 그녀가 마지막으로 목격된 곳은 스트롬가드에 비밀결사대가 점령한 지역이다.\n\n현상금은 부대장 나이얼스에게서 받을 수 있다.\n\n경고: 마레즈는 악마와 거래하는 것으로 알려진 강하고 교활한 흑마법사이다. 그러므로 그녀를 쫓을 때는 매우 신중하고 조심하도록!", progress = "안녕하십니까, <class>! 보고할 내용이라도 있습니까?", completion = "마레즈 코울을 쓰러뜨렸다고요? 정말 잘했군요!\n\n마레즈는 우리 스트롬가드 수호병을 위협했을 뿐만 아니라 비밀결사대와 다른 어둠의 세력을 이어주는 밀정이라는 소문이 있었습니다. 마레즈 코울이 더는 우리를 위협하지 못하게 되었다니 정말 기쁘군요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n고대 룬문자 팔보호구"},
[685] = {title = "오토와 팰컨크레스트 현상수배!", objective = "오토와 팰컨크레스트를 처치하고 그 증거로 머리카락을 임시 주둔지에 있는 부대장 나이얼스에게 가져가야 합니다.", description = "스트롬가드 민병대는 팰컨크레스트와 그의 경호원인 오토에게 현상금을 거는 바이다. 팰컨크레스트는 아라시 고원에서 비밀결사대의 전투를 지휘하고 있으므로 그를 죽이면 적에게 큰 혼란을 일으킬 수 있을 것이다.\n\n그의 경호원인 오토는 전략적으로는 중요한 인물이 아니지만 매우 강력한 상대로서 이미 십여 명의 아군 수비병을 살해했다.\n\n현상금은 부대장 나이얼스에게서 받을 수 있다.", progress = "어서 오십시오. 보고할 내용이 있습니까?", completion = "팰컨크레스트와 오토라고 했습니까? 정말 놀랍군요!\n\n어서 현상금을 받으십시오. 현상금을 드리는 제 마음도 정말 기쁘군요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n슬픔의 마법막대전투 기수의 팔보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[686] = {title = "왕의 하사품", objective = "마그니 브론즈비어드 국왕이 대석공 마블스텐과 대화하라고 명령했습니다.", description = "발루 부인과 같은 드워프 평민들이 더 큰 행복과 안전을 위해 전쟁을 불사할 수밖에 없는 이유를 이해해 주기를 바라지는 않았네. 하지만 그녀의 남편을 포함해 얼라이언스의 이름으로 싸우다 목숨을 잃은 모든 드워프를 생각하면 짐의 마음이 무겁기 그지 없군.\n\n그녀의 남편을 뒤틀린 황천에서 다시 데려올 수는 없지만 그대신 하사품을 내리겠네. 대석공 마블스텐으로 하여금 설리 발루의 기념비를 세우도록 명하겠네.\n\n당장 그에게 내 말을 전하도록, <class>. 어서 가서 짐의 명을 수행하게.", progress = nil, completion = "그러니까 마그니 폐하께서 직접 당신을 이곳으로 보내셨단 말이오?\n\n맙소사! 보통 중요한 일이 아닌가 보군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[687] = {title = "실성한 텔두린", objective = "실성한 텔두린을 찾아야 합니다.", description = "텔두린은 황혼의망치단의 일원이었네. 그런데 그가 실성한 후 우리의 가르침을 무시해 버렸지. 그는 우리한테서 도망치면서 미즈라엘의 두루마리를 훔쳐 갔네! 우린 그를 잡지 못했지만, 소문에 따르면 황야의 땅에서 실성한 채로 알 수 없는 말을 지껄이며 숨어 있다고 하네.\n\n공주를 다시 모셔오려면 반드시 텔두린을 찾아 그 두루마리를 찾아야 하네.", progress = nil, completion = "안녕. 안녕, 안녕 안녕 안녕 안녕 안녀엉!\n\n아, 미안하오. 아니 하나도 안 미안해! 나한테 무례하게 굴지마!\n\n아, 아니 정신 나간 소릴 했군.\n\n하지만... 가끔은 실성했다는 게 내게 유일한 위안이 돼.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[688] = {title = "미즈라엘의 친구들", objective = "해머폴에 있는 자루크와 대화해야 합니다.", description = "<미즈라엘의 말.>\n\n자유다! 이제 자유야! 저를 사로잡은 자들에게서 벗어나 이제서야 힘을 모을 수 있게 됐답니다. 혹시라도 그들과 다시 마주치면 저를 힘으로 장악하여 다시 가둬 놓을 겁니다.\n\n하지만 때가 되면 제가 직접 거인들과 싸울 것이고, 저를 가둬 놓은 대가를 치르게 할 겁니다!\n\n당신은 이제부터 제 친구입니다. 때가 되면 저를 다시 한 번 도와 주기 바랍니다. 제가 준비되면 지상으로 소환해 주시길 부탁드립니다.\n\n해머폴에 있는 자루크와 얘기를 나눠 보시기 바랍니다. 그는 날 소환하는 방법을 알고 있답니다.", progress = nil, completion = "어서 오시게, &lt;class&gt;. 공주님께서 자네가 올 거라고 알려 주었네. 그녀를 지상으로 다시 모시려면 서로 많은 얘기를 나눠 봐야 할 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[689] = {title = "왕의 하사품", objective = "아이언포지의 대석공 마블스텐이 알터랙 화강암 5개를 가져다 달라고 부탁했습니다.", description = "그러니까 우리의 위대하신 국왕께서 설리 발루라는 병사를 위해 기념비를 세웠으면 하신단 말이오? 그 불쌍한 젊은이가 탄돌 교각 참사에서 죽었단 말이지?\n\n도대체 이 동부 왕국에는 언제쯤 평화가 찾아올는지...\n\n휴, 왕께서 내리신 명령이니 우선 다른 작업은 뒤로 미뤄야겠군. 후세에까지 길이 남을 진정한 영웅의 기념비를 만들려면 최상급 돌이 필요하오. 힐스브래드의 다로우 언덕으로 가서 알터랙 화강암을 좀 가져 오시오.", progress = "<name>! 설리 발루를 기리는 걸작품을 만들 수 있을 만큼 충분한 화강암을 가져왔소?", completion = "아주 훌륭해! 기대했던 것보다 훨씬 좋은 것들이로군!\n\n이 몸은 말이야, 상상력이 무지 풍부하거든...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[690] = {title = "멀린의 요청", objective = "아라시 고원의 임시 주둔지에서 스쿼토를 찾아야 합니다.", description = "안녕하시오. 보아하니 모험가의 분위기가 느껴지는군. 도움이 필요한 일이 있는데 한번 들어 보겠소?\n\n얼마 전에 아라시 고원의 스트롬가드 요새를 떠나신 나의 첫 스승, 대마법사 트렐레인께서 두고 오신 몇몇 물건을 찾는 걸 도와 달라고 하셨소.\n\n그 도시는 함락되었고 스승께서는 아라소르의 탑을 방어하려 했으나 성공하지 못했다오. 이미 아라시 고원에 사람을 보냈으나 그들은 도움을 더 요청해 오고 있소. 어떻소, 관심이 있소?", progress = nil, completion = "그래, 멀린님께서 당신을 보냈다고? 비록 무라딘님이 무덤에서 일어나셔서 당신을 용에 태워 여기에 보냈다고 해도 어쩔 수 없소. 난 지금 바쁘단 말이오! 필요한 게 있거든 저기 크리텐과 얘기하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[691] = {title = "마법 재료 구하기", objective = "임시 주둔지에 있는 견습마법사 크리텐에게 마른나무껍질부족 어금니 10개, 마른나무껍질부족 약초 주머니 4개, 어둠사냥꾼 나이프 1개를 가져가야 합니다.", description = "대마법사 멀린님께서 스쿼토와 저에게 마법 재료를 구해 오라고 부탁하셨답니다. 그런데 그 물건들을 어떻게 구해야 할지 고민 중이었는데 당신이 여기에 왔으니 문제가 해결된 것 같군요.\n\n필요한 물건은 마른나무껍질부족 어금니, 마른나무껍질부족 약초 주머니, 어둠사냥꾼 나이프입니다.\n\n제 대신 구해다 주시겠습니까? 마른나무껍질부족은 주로 아라시 고원의 남동쪽에 살고 있습니다.", progress = "일은 잘 돼 가십니까?\n\n<크리텐이 일지에 글을 적는 동시에 읽어 주며>\n\n제가 조사한 내용이 정확하다면 어금니는 마른나무껍질 트롤에게서 구할 수 있습니다. 약초 주머니는 마른나무껍질부족 의술사에게서 구할 수 있고, 어둠사냥꾼 나이프는 마른나무껍질부족 어둠사냥꾼 중 통과의례를 통과한 가장 강력한 녀석이 가지고 다닙니다. 전투를 시작하기 전에는 어떤 어둠사냥꾼에게 나이프가 있는지는 알 수 없답니다.", completion = "대단하군요! 멀린께서 당신을 우리한테 보낸 이유를 알겠습니다. 정말 잘하셨습니다!\n\n이런 속도라면 스쿼토와 제가 금방 스톰윈드로 돌아갈 수 있겠군요.\n\n지금쯤이면 제 드워프 친구가 돌주먹일족 소굴의 정찰을 마치고 돌아와 있을 겁니다. 준비가 되거든 그에게 말을 걸어 보시기 바랍니다.\n\n아무래도 오우거 때문에 문제를 겪고 있는 것 같습니다만... 하지만 그에게 이 얘기는 하지 마십시오. 스쿼토는 자신의 정찰 실력에 대해 남들이 뭐라고 하는 걸 매우 싫어한답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[692] = {title = "잃어버린 조각", objective = "실성한 텔두린에게 찢어진 두루마리 조각, 구겨진 두루마리 조각, 그을린 두루마리 조각을 가져가야 합니다.", description = "미즈라엘의 두루마리... 미즈라엘의 두루마리?! 설마 그걸 원하는 건 아니겠지! 그 두루마리의 마법을 사용하면 미즈라엘을 지상 세계로 끌어낼 수 있단 말이야. 그러면 모두 다 곤란해진다고!\n\n어쩌면... 벌써 늦은 걸지도 몰라. 벌써 자유의 몸이 되어 힘을 모으고 있는 중일지도 몰라. 그렇다면 그 두루마리가 필요하지!\n\n...하지만 이미 파괴되어 버렸는데 어쩌지? 광포한 바위 정령들이 훔쳐가서 갈기갈기 찢어 버렸어.\n\n하지만 조각을 모두 모아 올 수 있다면 다시 하나로 만들 수 있을지도...", progress = "조각들을 찾았어?!?! 미즈라엘을 다시 가두려면 미즈라엘의 두루마리가 필요해. 너무 늦지 않았다면 좋겠는데!", completion = "아, 드디어 찾았군! 잘했어! 사악한 미즈라엘에 대항할 수 있는 유일한 방법은 이것밖에 없지!\n\n자, 이제 조각을 맞출 내 장비를 찾아 보자고. 장비로 이 조각들을 다시 붙일 수 있어야 할 텐데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[693] = {title = "마법 지팡이 회수", objective = "트렐레인의 마법지팡이를 찾아 임시 주둔지에 있는 스쿼토에게 가져가야 합니다.", description = "어흠...흠. 저기...일전에는 무뚝뚝하게 굴어서 미안하오. 기분 나쁘게 하려고 했던 건 아니니 이해해 주시오.\n\n트렐레인의 첫 번째 물건이 어디로 갔는지 알아냈다오. 돌주먹일족 소굴에 있는 코르그레쉬가 가지고 있더군. 지금은 자신의 종족을 통솔하기 위해 얼음 마법을 사용하고 있는데, 머지 않아 마법 지팡이의 모든 능력을 사용하는 방법을 알아낼 것이오.\n\n돌주먹일족 소굴은 이곳의 남쪽과 탄돌 교각의 동쪽에 있소. 이 오우거를 찾아가 마법 지팡이를 회수해 오시오.\n\n당신이 가 있는 동안 난 스트롬가드 요새에 대해 어떤 조치를 취할 수 있는지 알아 보도록 하겠소.", progress = "우리의 목표는 마법 지팡이요. 지금은 그걸 가져오는 데만 집중하시기 바라오.", completion = "잘했소. 하나 회수했으니 이제 3개를 더 회수하면 되는군. 나머지 세 개의 물건은 모두 스트롬가드 요새에 있다오.\n\n다음 단계 계획은 좀 더 힘들테니 잠시 휴식을 취해 힘을 회복하시오. 따뜻한 식사와 달콤한 휴식을 취한 후 다시 오기 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[694] = {title = "트렐레인의 방어 장치", objective = "푸른색 마노를 찾아서 임시 주둔지에 있는 견습마법사 크리텐에게 가져가야 합니다.", description = "푹 쉬었소?\n\n자, 다음 단계는 이렇소. 스트롬가드에 있는 아라소르의 탑 주위에는 오우거가 사방에 깔려 있소. 오우거를 상대로 살아서 물건을 가지고 오려면 탑의 방어 기능을 작동시켜야 하오. 그러려면 돌주먹일족 주술사가 좋아하는 보석이 좀 필요하오. 돌주먹일족 주술사는 탑에서 이 보석을 가지고 나오지만 실제로 소지하고 있는 시간은 길지 않다오.\n\n보석을 하나 구해서 크리텐에게 가져다주시오. 그러면 그가 마법 주문을 걸어서 열쇠처럼 작동하게 해 줄 것이오.", progress = "다시 만나서 반갑습니다. 아직 푸른색 마노를 찾지 못하셨습니까?", completion = "당신은 절 정말 놀라게 하는군요. 이번에도 잘해내셨습니다.\n\n자, 잠시만 기다려 주십시오. 보석에 제대로 된 마법 주문을 걸기만 하면 됩니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[695] = {title = "수습생의 마법", objective = "스쿼토와 대화해야 합니다.\n\n제공된 아이템: \n", description = "이걸 받으십시오. 탑의 토대 근처에 있는 기둥 중 한 곳에 대고 보석을 누르면 탑의 방어 기능이 작동하게 됩니다. 탑에 들어가서 트렐레인의 유품을 찾을 준비가 되면 사용하시기 바랍니다.\n\n행운을 빕니다. 당신이 야영지로 돌아오기를 기다리고 있겠습니다. 참, 떠나기 전에 스쿼토와 얘기를 나눠 보십시오. 나머지 자세한 내용을 알려 줄 겁니다.", progress = nil, completion = "좋아, 좋아.\n\n자, 이제 별일 없으면 시작해 보는 게 어떻소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[696] = {title = "탑 공격", objective = "트렐레인의 부적, 트렐레인의 수정구, 트렐레인의 붉은 마노를 찾아 임시 주둔지에 있는 스쿼토에게 가져가야 합니다.", description = "당신이 찾아야 할 물건은 트렐레인의 부적, 트렐레인의 수정구, 그리고 트렐레인의 붉은 마노라오.\n\n세 가지 모두 탑 안의 상자에 들어 있는데, 상자를 여는 데는 별문제가 없을 테고... 조심해야 할 건 오우거들이오.\n\n탑의 방어 기능으로는 오우거를 직접 처리할 수 있는 게 없기 때문에 무기를 쓸 준비를 하고 있어야 할 것이오. 당신이 물건을 훔치러 왔다는 걸 오우거들이 알면 분명히 공격해 올 것이오.\n\n조심하고 당신에게 행운이 있기를 바라오.", progress = "이 일에 성공한다면 멀린님께서 매우 기뻐하실 것이오.", completion = "멀린님께서 정말 대단한 친구를 우리에게 보내 주셨군. 정말 잘해 주었소.\n\n우리의 임무가 대성공이라는 걸 알게 되면 멀린님께서 매우 기뻐하실 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[697] = {title = "멀린의 의뢰", objective = "스톰윈드의 마법사 지구에 있는 대마법사 멀린에게 보내는 봉인된 편지를 전달해 주어야 합니다.", description = "이 편지를 스톰윈드에 계시는 멀린님께 전해 드리고 크리텐과 내가 곧 돌아갈 것이라고 전해 주시오. 멀린님께서 이곳에서 우리를 도와 준 것에 대해서 분명히 큰 보상을 해 주실 것이오.\n\n안전한 여행이 되길...", progress = "누구시오? 당신 낯이 꽤 익는데... 미안하지만 전에 우리가 만난 적이 있었소? 허허, 요즘 너무 바빠서 기억력까지 나빠진단 말이야.", completion = "&lt;대마법사 멀린이 편지를 열자 눈동자가 커지며&gt;\n\n세상에, 당신이 해냈구려. 정말 대단하오. 내 스승이신 트렐레인님께서도 매우 기뻐하시겠군. 크리텐과 스쿼토도 스톰윈드로 돌아올 수 있다는 것에 나만큼이나 흥분되어 있을 게 틀림없소.\n\n고맙소. 이걸 받아 두시오. 앞으로의 모험에 도움이 될 거요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n경계의 버클러깃털날개 장화\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[698] = {title = "보급품 보충", objective = "슬픔의 늪에 있는 톡카르에게 신선한 톱니악어 고기 8개를 가져가야 합니다.", description = "난 동쪽 해변 근처에 있는 우리 전초 기지에 보내줄 보급품을 모으는 일을 하고 있소. 톡카르도 할 수 있는데까지 하고 있지만 보초병 일에 병사들 요리까지 해야 하니 남는 시간이 많지 않소. 병사들이 톱니악어 고기를 요리해 먹는 걸 좋아하는데 아직 추가 물량을 보내지 못하고 있소. 그들을 좀 도와주지 않겠소?\n\n새끼 녀석들은 1-2년을 더 있어야 완전히 성장한 톱니악어가 되거든. 새끼 톱니악어는 다 자란 놈들에 비해 맛이 떨어지니 잡지 마시오.", progress = "록타르! 습지를 여행하는 건 만만히 여길 일이 아니지. 이곳에서 자신의 능력을 시험하려 하다니 용감하군.", completion = "아! 훌륭해. 오늘 밤엔 불에 신선한 고기를 요리해 먹을 수 있겠군. 고맙네.\n\n자네 덕분에 앞으로 며칠 밤은 그다지 나쁘지 않게 보낼 수 있게 되었군. 불을 밝게 피우고, 또 배도 가득 채울 수 있을 테니까 말이야.\n\n자네가 우리에게 보급품을 가지고 오다니 정말 놀랍고 반가운 일이야. 다르의 외모는 누가 봐도 매력적이진 않지만 적어도 그의 태도는 풍기는 냄새보단 훨씬 낫지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[699] = {title = "보급품 보충", objective = "슬픔의 늪에 있는 톡카르에게 무쇠턱 톱니악어 발톱 6개를 가져가야 합니다.", description = "우리는 스토나드로 다가오는 모든 위협을 방어하거나, 적의 규모가 대규모일 경우에 아군에게 경고하는 임무를 띠고 이곳에 배치되었네. 해안에서 멀록의 위협이 끊이지 않고 있다 보니 우린 쉴 틈도 거의 없지. 그래서 말인데, 괜찮다면 자네의 도움을 좀 받았으면 하네.\n\n무쇠턱 톱니악어의 발톱을 잘 다듬으면 좋은 무기를 만들 수 있지. 내게 그 발톱을 몇 개 가져다주면 신선한 고기와 좋은 친구에 대한 답례로 우리 무기 중 하나를 주겠네.", progress = "좋은 벌꿀 술과 따뜻한 불, 우리 부대 동료들, 무기로 가득 찬 무기고... 이곳 해안가에서 우리가 정말 필요로 하는 것은 이게 다지. 스토나드를 지키기 위해 이곳에 와 있는 걸 후회하지는 않지만, 언젠가 은신처나 탑이라도 하나 갖게 되면 좋겠군.", completion = "무사히 살아 돌아온 걸 보니 기쁘군.\n\n이 발톱들은 좋은 무기가 될 거요. 공격을 막아낼 무기는 많을수록 좋으니까...\n\n최대한 빨리 당신을 위한 무기 준비에 착수하도록 하지. 이제 꽤 숙련이 되었으니 오래 걸리지는 않을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[700] = {title = "왕의 하사품", objective = "마그니 브론즈비어드 국왕에게 보고해야 합니다.", description = "아, 이렇게 질 좋은 암석들이 나오는 로데론이 폐허로 변해 버리다니 안타까운 일이야.\n\n하지만 기념비는 아주 잘 만들어졌소! 왕께서 아주 기뻐하실 것이오.\n\n자, 그럼 어서 가서 기념비가 완성되었다고 전해 드리도록 하시오.", progress = nil, completion = "위대한 드워프 병사의 목숨에 비하면 그 기념비는 보잘것없는 징표에 불과하지. 하지만 이 세계의 드워프는 언젠가 한번은 죽게 마련이니라.\n\n위대한 동부 왕국의 땅을 밟게 될 이들이 이 기념비를 보고 한 드워프의 영광스런 죽음을 떠올리길 바라네. 설리 발루와 같은 용감한 병사들이 목숨을 내던진 것은 바로 다음 세대를 위한 것이야. 절대 잊지 않도록 해야지.", rewards = "다음과 같은 것들을 받습니다:\n\n아이언포지 기념반지"},
[701] = {title = "랩터의 기민함", objective = "식인 고원랩터에게서 랩터 심장 12개를 얻어 토건에게 가져가야 합니다.", description = "재료가 몇 개 더 있으면 내가 고르멀에게 랩터의 기민함을 불어넣어 주는 물건을 만들어 줄 수 있네! 랩터의 힘이 몸속에 흘러 들어가면 고르멀이 우리의 새로운 힘을 알게 되고 잠들어 있는 용사의 기운을 회복할 걸세!\n\n이 물건과 주술을 완성하기 위해서는 남서쪽에 있는 랩터 심장이 필요하네.", progress = "난 준비가 끝났네. 이제 필요한 건 랩터 심장뿐이야.", completion = "좋아, 그거면 충분하군. 랩터의 힘과 영혼을 이 수정구 안에 불어 넣겠네. 그러면 이 수정구가 고르멀에게 랩터의 강력한 힘과 지능을 불어넣어 줄 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[702] = {title = "랩터의 기민함", objective = "고르멀에게 토건의 수정구를 전달해야 합니다.", description = "고르멀에게 이 수정구를 가져다주어 랩터의 기민함을 사용하게 해 보게. 그럼 분명히 그의 영혼을 고무시키고 새로운 삶의 목표를 찾을 수 있게 해 줄 걸세. 그가 정상으로 돌아오면 그에게 호드의 현재 상황을 설명해 줄 수 있을 테고, 그러면 이 끊임없는 전투에서 노련한 전사의 도움을 받을 수 있게 될 것이야.", progress = "다시 돌아왔나? 하기야 이제는 토건의 자비심 말고는 달리 바랄 것도 없지.\n\n그래 이번에는 무얼 가지고 왔나? 밝게 빛나는 끈인가? 아니면 이 비참한 생을 끝낼 수 있는 기다란 밧줄이라도...", completion = "이번에는 뭔가 흥미로운 걸 가지고 왔군. 이 물건에서 이상한 힘이 솟아나고 있는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[703] = {title = "대머리수리 날개 구이", objective = "리글퍼즈에게 대머리수리 날개 4개를 가져가야 합니다.", description = "오, 물론이야. 대머리수리 날개 구이는 내가 제일 좋아하는 요리라고! 음, 풍부한 소스와 감칠 맛이 나는 고기! 그리고 그 냄새는 멀리 떨어진 곳에서도 당장 달려올 정도라니까!\n\n대머리수리 날개만 빼고 다른 건 준비 다 됐는데... \n\n당신도 맛을 보고 싶다면 대머리수리 날개를 구해달라고. 요리하기에 충분한 양을 구해다 준다면 당신에게 아예 조리법을 전수해 줄 수도 있다고!", progress = "여어. 대머리수리 날개는 구해 왔나?", completion = "좋아, 지금 바로 요리를 시작해야겠군. 벌써 입에 침이 고이는걸!\n\n자, 여기 조리법을 줄 테니 필요할 때 직접 만들어 보도록 하라고!", rewards = "다음과 같은 것들을 받습니다:\n\n대머리수리 날개 구이조리법: 대머리수리 날개 구이"},
[704] = {title = "아그몬드의 운명", objective = "모단 호수에 있는 발굴조사단장 아이언밴드에게 돌조각 단지 4개를 가져가야 합니다.", description = "아그몬드에게서 받은 마지막 보고가 마음에 걸리는군. 이제는 그가 죽어서 더욱 그렇소! 그의 보고서에 의하면 인부들이 울다만 외곽의 발굴 현장에서 '고대의 단지'를 발견했다고 되어있소. 그 현장에서 찾은 단지가 트로그 녀석들을 자극한 게 아닌가 걱정이군. 내가 여기서 찾은 조각상처럼 말이오.\n\n조사를 하려면 단지가 필요한데 울다만 발굴 현장으로 가서 돌조각 단지를 모아 내게 돌아오시오.", progress = "그 단지들은 찾았소? 단지와 트로그 간의 관계를 반드시 알아내야 하오!", completion = "수고했소! 열심히 노력하고 행운이 따라준다면 이 고대 유물들과 트로그의 관계를 알아낼 수 있을 거요.\n\n발굴조사단장들에게 아주 고마운 일을 해주었군. 이번 일과 아그몬드에 대한 당신의 노력은 결코 잊지 않겠소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n발굴조사단장의 장갑"},
[705] = {title = "진주잡이", objective = "황야의 땅에 있는 리글퍼즈에게 푸른 진주 9개를 가져가야 합니다.", description = "황야의 땅은 난폭한 포식자들과 썩은 고기를 먹는 지독한 짐승들이 가득찬 위험한 곳이지. 나 같이 키 작은 고블린에게는... 으... 무서운 곳이 아닐 수 없다니까. 내가 여기서 살아남으려면 절대로 방심해선 안 된다고!\n\n그나마 섬광탄 제조법을 알고 있기에, 그걸 만들어 야생 동물을 쫓는 데 사용하고 있지. 근데 재료가 하나 거의 다 떨어져 가서 말이야. 바로 부셔서 만든 푸른 진주 가루라오. 푸른 진주를 좀 구해다 주면 당신이 수고한 만큼 값지게 쓰도록 하지.\n\n아, 그리고 방수가 잘 되는 질 좋은 장화를 신고 가는 게 좋을 거요. 내가 필요한 푸른 진주는 썩은내 산호초에 있는 조개에서 나니까 말이지. 그래, 바로 가시덤불 골짜기에 있는 그 썩은내 산호초 말이야!", progress = "진주는 가져왔나? 섬광탄이 거의 다 떨어졌단 말이야!", completion = "이거면 충분하겠군! 이제 진주를 부셔서 가루로 만들고... 그 다음에 이것저것 조금씩 섞으면 되지.\n\n자, 이 썩은 고기를 먹는 짐승들아! 섬광탄 맛을 봐라!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n속사용 라이플섬광 마법봉\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n섬광탄"},
[706] = {title = "이글거리는 불꽃의 부적", objective = "시그런 아이언휴를 위해 레슬로 협곡에 있는 새끼 비룡에게서 검은 비룡의 심장을 구해야 합니다.", description = "내가 페라노어 스틸토님의 수습생으로 있을 때 무기에 불의 마법을 불어넣는 특수한 기술을 배웠지. 마지막으로 들은 소식에 의하면 그분이 저 위 로데론에서 사냥꾼 무리와 함께 대장간에서 일하고 계시다는 거요.\n\n자세히 설명해 줄 순 없지만 마법을 불어넣는 과정에는 희귀할 뿐만 아니라, 신중을 기해야만 잡을 수 있는 검은 새끼 비룡의 심장에서 얻은 피가 필요하오이다. 아이언포지에서 연락이 오길 기다리는 동안 할 일도 별로 없으니, 레슬로 협곡에서 검은 새끼 비룡의 심장을 구해 내게 가져다주면 무기에 불의 마법을 불어넣는 기술을 보여 주리다!", progress = "사냥은 잘 되어가오, <class> 친구?", completion = "그래, 이거면 완벽하오. 이제 마법을 불어넣으면 당신의 무기는 뜨거운 불길을 내뿜으며 적을 공격하게 될 것이오!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n이글거리는 불꽃의 부적"},
[707] = {title = "아이언밴드의 호출", objective = "모단 호수에 있는 아이언밴드의 발굴현장에서 발굴조사단장 아이언밴드와 대화하십시오.", description = "모단 호수의 발굴 현장에 있는 발굴조사단장 아이언밴드로부터 보고를 받았소. 다른 발굴 현장에 대한 방문 조사를 해야 한다는군.\n\n내가 아는 정보는 이 정도뿐이니 잠시 머리도 식힐 겸 여행을 해 볼 생각이라면 가서 아이언밴드와 이야기해 보시오.", progress = nil, completion = "그래, 스톰파이크가 당신을 보냈다고? 좋소.\n\n당신에게 부탁할 큰 일이 하나 있는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[708] = {title = "블랙박스", objective = "녹슨 블랙박스를 아이언포지에 있는 전투의 전당으로 가져가야 합니다.", description = "이 검은 금속 상자는 마치 산성 물질에 담가 두었던 것처럼 심하게 부식되어 있습니다. 오랫동안 거대한 대머리수리의 위장 속에 있었던 것이 분명합니다.\n\n상자를 뒤집자 바닥에 도장이 찍혀 있으며 그 도장 아래에 다음과 같이 적혀 있습니다.\n\n'전차 #19 - 아이언포지 증기 전차 부대'다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[709] = {title = "멸망의 해결책", objective = "실성한 텔두린에게 류네의 서판을 가져가야 합니다.", description = "오, 이런, 이런! 멸망이 다가오고 있어. 내 말을 명심해! 멸망이란 말이야!\n\n아냐, 말할 수 없어... 그들의 이름을 입 밖에 내면 놈들이 들을 수도 있단 말이야! 하지만 우리가 놈들에 대해 더 알아낸다면... 그래, 놈들에 대해 더 알아낸다면 그들을 막을 수 있을지도 몰라! 아마도...\n\n울다만으로 가. 악! 내 입으로 말하고 말다니! 반드시... 반드시... 류네의 서판을 찾아야 해. 그래, 그걸 찾아! 그리고 다시는 내가 그 이름을 말하게 하지 말아 줘!\n\n그 서판은 그곳 깊은 곳에 있는 고대의 상자 안에 있어. 거기에 숨겨져 있다고... 드워프들이 만든 그 어떤 것보다도 오래된 그 상자 속에 말이야.", progress = "서판은 찾았나? 틀림없이 비밀은 거기에 숨겨져 있어! 우리를 지켜 줄 비밀이 말이야!", completion = "오, 행운의 여신은 우리 편인 것 같군! 고마워! 아직 살아날 가망이 있을지도 몰라!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n종말론자의 로브"},
[710] = {title = "바위의 정령 연구", objective = "황야의 땅에 있는 로크윌 베리아투스에게 작은 돌조각 10개를 가져가야 합니다.", description = "난 최근에 맡은 정령 봉인의 족쇄 연구를 위해 이곳 황야의 땅은 머물게 되었어요.\n\n이 연구가 완료되면 마법사가 더욱 강력한 정령을 불러내 그 놀라운 능력을 십분 활용할 수 있게 되죠. 하지만 그 전에 먼저 내가 조립한 여러 장치를 사용하여 이번에 만든 최신 공격 주문을 시험해 보기 위해서는 작은 돌조각들을 모아야 해요.\n\n돌조각은 서쪽에 있는 하급 바위 정령들에게서 쉽게 얻을 수 있을 거예요. 날 위해 돌조각을 좀 구해다 주지 않겠어요?", progress = "이 지역은 내 최신 연구 내용을 실험해 보기에 아주 적합한 장소죠. 잠깐만 이것 좀 들고 있어 주시죠? 그래요, 그렇게... 벡터는 정상이고... 흠... 그래, 천연 재료와 넓은 공간... 지적이고 현명한 과학자에게 이보다 더 좋은 환경이 어디 있겠어요?", completion = "이거면 충분하겠군, 고마워요. 흠 기대했던 것보다 조금 더 많은 모래가 들어 있군. 마찰 계수를 맞추어야 하는데... 아니 잠시만 기다려 봐요. 이 냉기 오일과는 여전히 작은 반응이 남아 있군.\n\n&lt;혼자서 중얼거리며 자신의 주먹을 다른 손의 손바닥에 넣고는 마력이 담긴 눈빛으로 그것들을 뚫어지게 쳐다보는 로크윌&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[711] = {title = "바위의 정령 연구", objective = "황야의 땅에 있는 로트윌 베리아투스에게 큰 돌조각 3개를 가져가야 합니다.", description = "당신이 보여준 실력이 내 수습생 모두를 합친 것보다도 낫군요.\n\n다음으로 부탁할 일은 큰 돌조각을 구해와야 하는 좀 더 힘든 일이에요. 충분히 주의한다면 바위 정령에게서 돌조각을 얻을 수 있을 거예요. 아무래도 바위 정령은 몸이 크고 강하기 때문에 내 실험에 사용할 만큼 큰 돌조각이 있을 가능성이 커요. 이곳에서 서쪽으로 더 가거나 산기슭을 따라 남동쪽으로 가면 바위 정령들을 찾을 수 있을 거예요.\n\n당신이 가져온 작은 돌조각을 시험해 보려면 시간이 좀 걸릴 테니 서두르진 않아도 돼요.", progress = "정말 기쁜 소식이 있어요. 예상했던 대로 작은 돌조각에 주문이 걸렸어요. 예상대로 이 실험이 성공하기만 하면 지금까지 불러냈던 모든 정령을 압도하는 강력한 정령들을 조종할 수 있게 될 거라고요!", completion = "대단해요, 그저 놀라울 따름이군요! 이 정도의 돌조각을 구해 오려면 타우렌 6명 정도가 필요할 거라 생각했었는데 말이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[712] = {title = "바위의 정령 연구", objective = "황야의 땅에 있는 로트윌 베리아투스에게 바위 결속의 팔보호구 5개를 가져가야 합니다.", description = "이곳 황야의 땅에 있는 정령에게서 필요한 것이 한 가지 더 있어요. 상급 바위 정령들에게서 바위 결속의 팔보호구를 구해다 주었으면 하거든요. 내 계산에 따르면 그 팔보호구는 내가 만든 족쇄의 힘을 측정하기에 충분해요.\n\n내가 수정점을 쳐 보니 거대한 바위 정령은 여기서 남서쪽에 있는 것으로 나왔어요. 아마 내 기억으론 오우거 근처에 있었던 것 같단 말이죠.\n\n여분까지 해서 팔보호구를 5개만 가져다주세요. 내 조수 세르보가 내 연구 재료와 결과물을 어디 뒀는지 곧잘 잊어버리니... 만일을 대비해서 말이에요.", progress = "당신이 가져다준 돌조각은 정말 완벽하군요. 여기서 실험이 끝나면 루시앙이 나머지 돌조각을 카라노스로 다시 가져 갈 거예요. 그러면 그들이 이 돌의 유용성을 다시 증명할 수 있겠죠.\n\n예를 들면, 고성능의 폭약을 여러 방면으로 연구해서 이 돌조각들을 이용한다면 더욱 좋은 보금자리를 지을 수 있는 좋은 기초를 만들 수 있을 거예요.\n\n<다시 실험을 하기 위해 돌아가면서 서서히 작아지는 로트윌의 목소리>", completion = "내 제자가 될 생각은 없나요? 싫다고요? 머리도 좋고, 호기심도 많고, 힘도 좋고... 이 모든 것을 갖춘 당신 같은 사람의 도움없이 내가 무엇을 할 수 있겠어요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[713] = {title = "최고의 냉각제", objective = "황야의 땅에 있는 로트윌 베리아투스에게 냉기 오일을 가져가야 합니다.", description = "냉기 오일에 대해 가르쳐 줄까요? 엔진이나 기어의 가열을 식히는 데는 냉기 오일 만한 게 없어요.\n\n그 냉각 능력은 놀라울 정도고 윤활유로서의 수명은 그 어떤 것도 따라오지 못하죠. 하지만 이게 전부가 아니에요. 마법이 걸린 물건에 마법 능력을 오래 유지시켜주는 기능도 있다니까요.\n\n내가 소환해낸 정령이 우리 모두를 공격하지 못하게 제어할 수 있을 정도의 족쇄 마법 능력을 높이기 위해서는 냉기 오일 한 병이 필요해요. 알터랙에 있는 내 고블린 친구, 브로킨이 냉기 오일 만드는 법을 가르쳐 줄 거예요.", progress = "내가 부탁한 냉기 오일은 구했나요? 그걸 구해다 준다면 정말 큰 도움이 될 거예요.", completion = "정말 놀라워요! 내 새로운 팔보호구의 냉각제로 사용하기에 완벽하군요. 만약 마법이 한 세기 동안 유지되지 않는다면 세르보에게 내 전 재산을 줘도 좋아요.\n\n이걸 완성하고 나면 학회의 모든 마법사들이 놀라 자빠질 거예요. 자, 이제 지켜보기만 하라고요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[714] = {title = "태엽...장치?", objective = "황야의 땅에 있는 로트윌 베리아투스에게 태엽장치를 가져가야 합니다.", description = "지금까지 정말 잘해 주었어요.\n\n<실험으로 정신없어 보이는 로트윌>\n\n우리가 카라노스에서 만나게 되면 일자리가 필요하거든 언제든지 말만 하라고요.\n\n이런! 얼른 이걸 쥐고 있어 주세요. 네, 그렇게... 고마워요.\n\n이제 작지만 결정적인 재료 한 가지만 더 있으면 되는데... 태엽장치 말이에요. 당신이 태엽장치만 구해다 주면 이 실험을 끝낼 수 있을 거예요.", progress = "아, 그래요, 그래, 잠시만...\n\n<계속 어떤 장치를 만드느라 여념이 없는 로트윌>", completion = "좋았어!\n\n&lt;태엽장치를 받아 드는 로트윌&gt;\n\n완벽해... 이제 거의 다 됐군. 아... 아니지 지금 방금 거의 다 됐어요. 이번 발명은 지금까지 내가 만든 것 중 최고에요. 땅속에 이걸 터뜨려 보죠. 보세요, 당신이 도와줘서 내가 어떤 걸 만들었는지 말이에요. 몇 분만 더 있으면 될거예요... 아마도... 혹시 좀 더 걸릴지도 몰라요. 음, 좀 더 오래 걸리겠네요. 두고 보죠...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[715] = {title = "액체 돌", objective = "황야의 땅에 있는 루시앙 토셀렌치에게 치유 물약과 하급 투명 물약을 가져가야 합니다.", description = "로트윌 선생님을 위해 당신이 구해 온 재료들은 나무랄 데 없는 것 같군요. 단도직입적으로 당신은 로트윌 선생님께서 신성하게 여기시는 과학에 상당한 조예가 있는 듯하니, 저도 좀 도와주시지 않으시겠어요?\n\n로트윌 선생님께서 정령들을 불러내면 곧 투명 물약과 치유 물약 두 가지가 필요하게 될 거예요. 물약을 구해다 주시면 답례로 로트윌 선생님 밑에 있으면서 개발한 이 물약 조제법을 알려 드리지요.\n\n이 조제법은 선생님께서 이곳 황야의 땅에서 하고 계신 연구 중 일부에 기초한 거랍니다.", progress = "선생님의 연구가 거의 끝나가고 있어요. 당신에게 부탁한 일은 어떻게 되어가나요?", completion = "그래, 바로 이거예요!\n\n고맙습니다. 이걸 받으세요. 황야의 땅을 여행하는데 도움이 될 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n조제법: 하급 돌방패 물약하급 돌방패 물약"},
[716] = {title = "돌로 만든 보호구", objective = "황야의 땅에 있는 루시앙 토셀렌치에게 청동 무늬 팔보호구를 가져가야 합니다.", description = "로트윌 선생님이 얼마나 인색한지는 잘 알고 있어요. 그러니 제가 대신 도움될 만한 물건을 만들어 드리지요. 아마 선생님의 새로운 발명으로 발생할 끔찍한 일로부터도 보호받을 수 있을 거예요.\n\n당신이 선생님을 위해 모아온 여분의 돌들을 살펴봤는데 당신이 사용할 만한 괜찮은 팔보호구를 만들 수 있을 것 같더군요. 물론 마법도 걸 수 있죠.\n\n이제 대장장이가 만든 청동 무늬 팔보호구만 있으면 당신에게 줄 팔보호구를 완성할 수 있어요. 제게 청동 무늬 팔보호구를 좀 가져다주세요.", progress = "당신이 그 팔보호구를 가져오기를 마냥 기다릴 수는 없어요.\n\n곧 무슨 일이 일어날지 누가 알겠어요?", completion = "자, 여기 있어요. 한번 착용해 보세요.", rewards = "다음과 같은 것들을 받습니다:\n\n마법의 돌헝겊 팔보호구"},
[717] = {title = "대지의 진동", objective = "대지의 봉인을 사용하여 자수정, 오팔, 다이아몬드의 기둥을 작동시켜 마법석을 모아야 합니다.\n\n마법석들을 대지의 봉인에 놓아 블랙래쉬와 헤마투스의 봉인을 해제해야 합니다.\n\n풀려 난 블랙래쉬와 헤마투스를 처치하고 가렉에게 블랙래쉬의 굴레, 헤마투스의 굴레와 대지의 봉인을 가져가야 합니다.", description = "블랙래쉬와 헤마투스를 계속 레슬로 협곡에 봉인할 수 있을 거라고는 누구도 보장할 수 없는 상황일세. 그 검은용 두 마리는 그곳에 본거지를 마련했고 오우거들은 봉인까지 훔쳤으니 더욱 강력한 조치를 취해야 할 때야.\n\n비룡의 감옥을 유지하고 있는 마법석 세 개는 대지의 봉인을 사용해야만 가져올 수 있네. 그리고 그 마법석들을 사용하면 그들을 가두고 있는 봉인을 깨뜨릴 수 있다네.\n\n그들의 꿈이 영원히 헛된 망상으로 끝나게 해 주게.", progress = "비룡들의 감옥은 강력한 마법과 힘으로 오랫동안 유지되어 오긴 했지만 블랙래쉬와 헤마투스가 풀려날 가능성을 조금이라도 남겨서는 안 되네.", completion = "그대 덕분에 키린 토에서는 갇혀 있는 레슬로의 두 비룡에 대한 걱정을 더 이상 할 필요가 없게 되었네. 나는 이 성공적인 결과를 보고하러 스승님께 돌아가야겠네. 크라서스님께서도 분명 기뻐하실 것일세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n맹렬한 바람의 흉갑프리즘 미늘 갑옷전투철로 흉갑정신 확장의 메달\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[718] = {title = "신기루", objective = "시그런 아이언휴를 위해 보급 상자를 찾아야 합니다.", description = "우리가 울다만 발굴현장을 빠져나오느라 정신이 없어 보급품 마차와 상자 상당수를 길에 두고 올 수밖에 없었소. 그런데 코쉬 야영지에서 온 고약한 오우거들이 시체에 모여드는 독수리들처럼 버려진 우리 물건들에 손을 대고 있소. 고약한 것들...\n\n어쨌든, 놈들이 우리의 무기와 식료품이 실려 있던 마차를 가져가서... 부끄럽게도 먹을 걸 전혀 구하지 못했다오.\n\n그래서 지금 몹시 난처한 입장인데 당신이 좀 도와 주겠소?", progress = "사막에서는 음식을 구하기가 무척 어렵다는 걸 말해주고 싶군, 친구.\n\n그런데... 저기 저건 뭐지...?", completion = "정말 고맙소. 으, 모래를 한 줌은 삼킨 것 같군...\n\n흠, 뭐 그건 그렇고, 오늘 밤엔 나가서 음식을 좀 구해 올까 하오. 오랜만에 배 터지게 먹어 봅시다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[719] = {title = "행운의 곡괭이", objective = "라이돌의 행운의 곡괭이를 찾아 해머토의 발굴현장의 남쪽에 있는 발굴조사단장 라이돌에게 되돌려주어야 합니다.", description = "안녕하시오, <class>. 여기는 검은무쇠단 드워프들이 사방에 깔려 있으니 조심해야 하오. 아마도 어둠괴철로단 드워프 같았소이다.\n\n좀 전에도 내가 작업 중인 발굴 현장을 공격해 난 겨우 목숨을 건졌지만 내 상관인 해머토를 비롯해 거기 있던 거의 모든 이들이 목숨을 잃었소.\n\n발굴 현장은 여기에서 바로 북쪽에 있는데, 우리 보급품들, 특히 내 행운의 곡괭이를 되찾아올 방법을 궁리하는 중이었소.\n\n당신이 나를 좀 도와 주시겠소? 검은무쇠단 드워프 중 한 명에게 내 곡괭이가 있을 거요! 그들 중 한 놈이 분명하오.", progress = "어둠괴철로단 드워프가 뭘 찾고 있었던 건지는 모르겠지만 분명히 무슨 목적이 있었을 거요.", completion = "오, 당신은 내 구세주요. 그리고 어둠괴철로단 드워프에게 뜨거운 맛을 보여 줄 수 있는 이가 있다는 것도 참으로 통쾌한 일이오. 도와 줘서 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n라이돌의 망치"},
[720] = {title = "희망의 전조", objective = "발굴조사단장 라이돌을 찾아 해머토 그레즈가 살아 있다는 사실을 알려야 합니다.", description = "<지도에는 분필로 휘갈겨 쓴 쪽지가 적혀 있습니다.>\n\n\"라이돌, 놈들은 나를 울다만으로 데려가고 있네... 도와 주게.\n-해머토\"", progress = nil, completion = "해머토가 살아 있다고? 오, 정말 다행스러운 일이군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[721] = {title = "희망의 전조", objective = "울다만에서 해머토 그레즈를 찾아야 합니다.", description = "당신이 그를 좀 찾아 주지 않겠소? 울다만에 있는 해머토를 좀 찾아 주시오.\n\n비열한 어둠괴철로단 드워프들이 대규모 발굴 작업에 대해 알아내기 위해, 그를 인질로 잡고 있는 거라면 아이언포지 전체가 큰 위험에 빠질 수도 있소.\n\n저 검은무쇠단 녀석들은 오래전부터 더 강한 골렘을 만들어내기 위해 새로운 마법을 손에 넣으려 하고 있소. 해머토도 그들과 같은 일을 하고 있었지만, 해머토는 놈들을 막기 위해서였지.\n\n놈들은 아마 그가 알고 있는 것을 알아낼 때까지는 그를 살려둘 거요. 그를 구하려면 서둘러야 하오!", progress = nil, completion = "... 뭐라고 했지? 미안하네...&lt;콜록&gt; 이제 힘이 하나도 없구려. 좀 더 가까이 와 주겠나, &lt;class&gt;? \n\n레이돌이 자네를 보냈다고? 그 친구가 생각했던 것보다는 멍청하지 않은 게로군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[722] = {title = "비밀의 아뮬렛", objective = "해머토의 아뮬렛을 찾아 울다만에 있는 해머토에게 가져가야 합니다.", description = "나를 위해... <콜록>...이곳 울다만까지 와 주다니... 정말 용감하군...\n\n이... 늙은 해머토를 도울 생각이라면... <콜록>... 내 아뮬렛을... 좀... 찾아 주시게...\n\n내 아뮬렛을 딥섀도... 마그레간 딥섀도가 가져갔지. 그는 이 근처 어딘가에 있을 게야... 틀림없이 이 폐허 어딘가에... 그를 막지 못하면 아뮬렛이 놈들을... <콜록>... 두루마리가 있는 길로 안내하게 될 것이네. 이제 모든 건 자네에게 달려 있네. 그러니 제발...아뮬렛을 찾아 주게나. \n\n그리고 그 두루마리는 검은무쇠단 드워프들이 보다 강력한 골렘을 만드는데 꼭 필요한 것일 게야. 확실해. 뼛속까지 느껴지는걸 보면...", progress = "어둠괴철로단 드워프들은... <콜록> 위험한 놈들이네. 조심하게나... <콜록> 자네가 반드시 아뮬렛을 찾아야만 해.", completion = "하! &lt;콜록 콜록&gt;\n\n자네가 내 아뮬렛을 되찾아 줄 거라 믿고 있었네.\n\n&lt;헐떡이며&gt; 참으로 잘해 주었네. &lt;콜록&gt;", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[723] = {title = "돈독한 믿음", objective = "황야의 땅에 있는 발굴조사단장 라이돌에게 해머토의 아뮬렛을 가져가야 합니다.", description = "<상처 부위를 감싸며 안정을 되찾은 후 다시 이야기를 시작하는 해머토>\n\n라이돌에게 가게... 그리고 그에게 내 아뮬렛을 가져다주게나. <콜록 콜록> 그러면 그 친구는... <콜록> 해야 할 일을 알 수 있을 거야. 내가 우리의 근원을 찾고 있었다는걸 그는 알고 있고 <콜록> 어둠괴철로단 드워프 녀석들을 막는것 또한 나의 다른 임무였다는 것도 알고 있을걸세. 그들이 그 두루마리를 찾게 해서는 안 될 것이야...<콜록>", progress = "오늘은 정말 운수 나쁜 날이었소. 하지만 뭐, 여기는 황야의 땅이니 하루하루가 운수 없는 날인 것이 당연할지도 모르지.", completion = "해머토의 아뮬렛? 차라리 그가 이미 죽었다고 생각하던 때가 더 마음 편했던 것 같군. 사실을 확인하고 나니 오히려 아픔만 더 커지오. 이 아뮬렛은 그의 필생의 업적이었소. 이대로 그의 죽음을 바라보고만 있을 수는 없소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[724] = {title = "돈독한 믿음", objective = "아이언포지에 있는 역사학자 카르닉에게 해머토의 아뮬렛을 가져가야 합니다.", description = "좋소, 좋아... 그렇다면 우리가 해야 할 일을 알고 있는 게 누굴까?\n\n그렇지! 역사학자 카르닉이 있었지!\n\n그는 아이언포지에 있소. 그라면 우리를 도울 수 있을 거요. 그와 해머토는 울다만에서 사라진 유물을 찾기 위해 함께 일했었지.\n\n아마 어둠괴철로단 드워프 녀석들도 그 두 명이 실제로 말한 것보다 더 많이 알고 있다는 사실을 눈치챘을 거요.\n\n해머토에게 일어난 일을 카르닉에게 설명하고 해머토의 아뮬렛을 전해 주시오. 그러면 그가 다음에 해야 할 일을 알려 줄 거요.", progress = "아... 이런... 또 다른 여행자가 이 드워프의 도움을 구하는군.\n\n이보시게, 정말 미안한데 지금은 아무런 의미 없는 질문에 대답할 시간이 없다네.", completion = "오! 이런. 전혀 다른 용건이었군. 자네는 지금 이 일이 얼마나 중대한 일인지 알고 있는 건가?\n\n해머토의 죽음은 너무나 슬픈 일이야. 하지만 그가 자네에게 아뮬렛을 주고 이리로 보냈다면 그 자신도 사태의 심각성을 알고 있었던 걸 것일세.\n\n그러니 그의 죽음에 대해서 슬퍼하는 건 잠시 미루도록 하세나. 이제 이 아뮬렛이 왜 그토록 중요한지, 그 이유를 알려 주도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[725] = {title = "위협의 경고", objective = "조언자 벨그룸을 찾아 봉인된 쪽지를 전해야 합니다.", description = "우선 최대한 빨리 조언자 벨그룸님을 찾아 가시게. 그리고 그분께 자네가 본 바를 모두 얘기해 준 다음 앞으로 어떻게 해야 할지 물어보아야 할 것이야. 이 쪽지를 보여 주면 그분이 이번 사건에 대해 보다 잘 알 수 있을 걸세.\n\n그동안 나는 해머토의 영혼과 얘기해 보겠네. 그가 가진 정보가 황야의 땅에서 벌이고 있는 어둠괴철로단 드워프의 음모를 막는 데 도움이 될 거야. 일이 잘 되기를 빌어 볼 수밖에...", progress = "흠, 무슨 일이오?", completion = "아, 역사학자 카르닉이 보낸 전갈이로군... 수고했소.\n\n카르닉에 대한 일은 언제든지 가장 먼저 처리해야 할 일이지. &lt;쪽지를 열어 읽기 시작하는 조언자 벨그룸&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[726] = {title = "위협의 경고", objective = "역사학자 카르닉과 대화해야 합니다.", description = "<쪽지를 끝까지 읽는 조언자 벨그룸, 잠시 눈이 휘둥그레지며>\n\n이런...악마들의 세상이 도래했군!\n\n역사학자 카르닉에게 돌아가 왕의 이름으로 이 정보에 따라 신속하고 단호하게 조치를 취하라고 전하시오. 그에게 모든 수단과 방법을 동원해 황야의 땅에서 어둠괴철로단 드워프들의 활동을 저지하라고 전해야 한다고 하시오.", progress = nil, completion = "자네도 이 일이 얼마나 중요하고 급한 일인지 파악하고 있는 것 같군.\n\n좋아, 어둠괴철로단 드워프들을 처리하기 위해서 무엇이 필요한지는 내가 알고 있네.\n\n울다만에 있는 그들의 주둔군에게 타격을 주기 위해서는 그들의 작전기지인 고통의 요새를 파괴해야 해.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[727] = {title = "야그인의 법전을 찾아서", objective = "아이언포지의 쓸쓸한 뒷골목에 있는 게릭 본그립에게 해머의 인장을 가져가야 합니다.", description = "이 서판은 많은 것을 말해 주지. 하지만 아직 부족해! 너무 부족해!\n\n아주 오래전에 야그인이 쓴 법전이 있어. 날... 잡아두었던 자들... 그 자들이 그 법전을 여러 장소에 보관해 두고 있어. 그리고 학자들이 연구를 하지. 그 법전에는 방대한 지식이 담겨 있어. 우리를 보호해줄 지식 말이야!\n\n아이언포지의 게릭 본그립을 찾아가. 그는 아이언포지의 쓸쓸한 뒷골목에 있는 상점에 있어. 이 인장을 보여주면 당신이 같은 편이라고 생각할 거야. 야그인의 법전을 달라고 해서... 내게 가져와 줘!", progress = "안녕하세요. 제 가게에 잘 오셨어요. 하지만 함부로 손은 대지 마세요.\n\n지식이란 아주 위험할 수도 있는 거니까요.", completion = "아, 안녕하세요, 형제님.\n\n지하의 주민들에게 축복을.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[728] = {title = "야그인의 법전을 찾아서", objective = "언더시티에 있는 관리인 벨두거에게 해머의 인장을 가져가야 합니다.", description = "이 서판은 많은 것을 말해 주지. 하지만 아직 부족해! 너무 부족해!\n\n아주 오래전에 야그인이 쓴 법전이 있어. 날... 잡아두었던 자들... 그 자들이 그 법전을 여러 장소에 보관해 두고 있어. 그리고 학자들이 연구를 하지. 그 법전에는 방대한 지식이 담겨 있어. 우리를 보호해줄 지식 말이야!\n\n로데론의 언더시티에 있는 관리인 벨두거를 찾아가. 이 인장을 보여주면 당신이 같은 편이라고 생각할 거야. 야그인의 법전을 달라고 해서... 내게 가져와 줘!", progress = "아, 열정적인 <class>|1이로군;로군;. 좋아. 내 소장품을 공부하고 싶어서 왔소? 좋소!\n\n하지만 경고해 두는데, 지식은 강한 자들에게 힘을 주기도 하지만, 약한 자들을 미치게 만들기도 한다오.", completion = "인장은 따로 보관하시오, &lt;class&gt;|1이여;여;. 우리 서약의 정의로움을 믿지 않는 자들도 있으니까 말이오.\n\n그리고 우리에 대해서 알고 나면 우리가 실패한 것으로 생각할 자들도 있지.\n\n그러니 우리는 항상 조심해야 하오. 경계를 늦추지도 말고 인내를 가져야 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[729] = {title = "정신 없는 발굴조사단장", objective = "남쪽으로 가서 발굴조사단장 렘트레블의 상태를 확인해야 합니다.", description = "수석고고학자 그레이위스커께서 절 위대한 발굴조사단장 렘트레블님 밑에서 일하게 해 주셨으니 이 얼마나 영광인지 모릅니다. 아이언포지의 학교에서는 렘트레블님의 위대한 발견에 대해 모르는 이가 없죠.\n\n하지만 이 저명한 발굴조사단장께서는 주위 상황에는... 음... 그다지 신경 쓰지 않는 것 같아요.\n\n우리는 위대한 고대 문화의 흔적을 찾아냈어요. 그런데 땅에서 끔찍한 골렘들이 나와서 현장을 덮치고 말았죠. 렘트레블께서는 이 사실을 모르고 계신 것 같아요. 전 도움을 요청하러 아우버다인으로 달려왔답니다.\n\n남쪽으로 가서 렘트레블께서 무사한지 좀 봐 주세요.", progress = nil, completion = "호올리, 자넨가? 이 돌을 깨는 걸 좀 도와주게. 거기 털이개 좀 줘. 여기 뭔가 있는 것 같네.\n\n어? 호올리가 아니잖아! 털이개가 어디 있는지는 모르겠군그래?\n\n뭐, 그건 됐고. 내가 발견한 신비한 화석을 보내겠다고 연맹에 약속했는데... 호올리는 어디 간 게지?\n\n해야 할 일이 너무 많아. 아차... 신비로운 화석을 어디 뒀더라. 털이개는 또 어디 갔지? 대체 호올리는 어디 있는 거야.\n\n당신은... 뭐, 도우러 왔다면 누군지는 상관없소만 날 도울 준비가 되면 알려 주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[730] = {title = "어둠의 해안에 생긴 문제", objective = "아우버다인으로 가서 드워프 발굴단의 흔적을 찾아야 합니다.", description = "이 세계의 위대한 고고학적 불가사의에 관심을 가진 <class>|1을;를; 만나게 되어 정말 기쁘오.\n\n얼라이언스 친구들은 우리 일을 단순한 취미 정도로 치부하는 경우가 종종 있지. 그러나 최근 카즈 모단에서 발견된 것들은 어떤 강력한 세력이 로데론에서 칼림도어에 이르는 아제로스 전역을 위협하고 있음을 증명하고 있소. 얼마나 많은 이들이 이걸 깨닫지 못하고 있는지...\n\n지금 가장 큰 근심은 어둠의 해안으로 보낸 우리 대원들이오. 벌써 몇 주 동안이나 소식이 끊겼소. 아우버다인으로 가서 그들의 소재에 대한 단서를 찾아봐 주겠소?", progress = nil, completion = "수석고고학자 그레이위스커께서 우리를 위해 사람을 보내시다니, 이렇게 기쁠 수가...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[731] = {title = "정신 없는 발굴조사단장", objective = "신비로운 화석을 찾는 동안 발굴조사단장 렘트레블을 경호한 후 아우버다인에 있는 고고학자 호올리에게 돌아가십시오.", description = "그러니까 호올리... 아, 맞아. 당신은 호올리가 아니지. 호올리는 어디 있는 게요?\n\n뭐, 그게 중요한 게 아니고... 털이개를 찾아야 하는데... 아니, 신비로운 화석 말이야! 그 화석을 반드시 찾아야 하오. 다르나서스에 있는 탐험가 연맹에서 내 작업의 증거를 보고 싶어할 테니 말이오.\n\n준비가 되면 내게 말하시게나. 같이 털이개를... 아니, 화석을 찾아 봅시다. 연맹이 만족할 만한 보고를 제출해야 하니까 말이야.\n\n준비가 됐소?", progress = nil, completion = "발굴조사단장 렘트레블께서 무사하시다니 정말 다행이군요. 제가 그 분이 정신이 없다고 말했었죠? 그런데도 그 끔찍한 짐승이 들끓는 곳에 계속 계시려고 하다니 믿을 수가 없어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[732] = {title = "대지의 진동", objective = "가렉을 위해 대지의 봉인을 찾아 와야 합니다.", description = "엘룬께 영광을. 그대가 시그런을 많이 도와 줬다고 들었기에 나도 도움을 좀 청할까 하네. 우리 스승님인 키린 토의 크라서스님께서 레슬로 협곡에서 발생한 문제를 해결하라고 나를 이곳에 보내셨지.\n\n이곳에서 내가 맡은 임무에 대해서 자세하게 얘기해 줄 수는 없지만, 매우 중요한 임무라는 것만은 확실히 말할 수 있다네.\n\n보프 야영지 근처에서 가끔 보이는 떠돌이 오우거 무리가 대지의 봉인이라는 물건을 훔쳤는데 그걸 되찾아 와야 해. 그대가 날 위해 그걸 찾아와 준다면 자세한 얘기를 해 주겠네.", progress = "이 오우거들은 황야의 땅을 가로질러 오우거 야영지 사이를 여행하는데, 마른 땅에서 올라오는 열기와 소용돌이치는 바람 때문에 이들을 추적하는데 어려움이 있을 것이야. 내가 듣기론 가끔 보프 야영지를 지나 돌아다닌다고 하더군. 못 찾겠으면 그 야영지를 한 번 살펴 보게.", completion = "대지의 봉인을 가져오다니, 이보다 더 기쁜 소식이 어디 있겠나. 대지의 봉인은 고통의 요새의 검은무쇠단 드워프들이 데스윙의 잔인무도한 부관 블랙래쉬와 헤마투스라는 쌍둥이를 봉인하기 위해 만든 것이네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[733] = {title = "자재 모으기", objective = "시그런에게 금속 조각 7개를 가져가야 합니다.", description = "내가 방어 도구나 기타 다른 필수 장비들을 제작할 자재를 찾아 오지 못하면 이곳 상황이 안 좋아질 수도 있소. 이 지역의 오우거들은 금속 조각들을 방어구로 사용하여 단단히 무장하고 있는 것 같소. 그러고 보니 황야의 땅에 증기 전차가 있다는 이야기가 헛소문이 아닐지도 모르겠군.\n\n아무튼, 발굴조사단장은 이 작은 야영지의 상황을 걱정하고 있소. 그래서 가능한 빨리 작업을 시작해야 할 것 같은데...\n\n오우거의 주 야영지는 서쪽으로 멀리 떨어져 있는 먼지목도리 소굴에 있으니 금속 조각을 좀 가져다주시오.", progress = "할 수 있는 한 최선을 다했지만... 역부족인 것 같소. 금속은 좀 더 구해 왔소?", completion = "이제 시작이군. 아이언포지나 탐험가 연맹에서 기별이 있을 때까지는 버텨야 하오.\n\n이제 내 냉각통에 사용할 소금만 좀 구하면 되는데...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n무쇠벽 방패철굽 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[734] = {title = "불길한 예감", objective = "황야의 땅에 있는 루시앙 토셀렌치와 대화해야 합니다.", description = "훌륭해, 정말 훌륭해...\n\n<다시 족쇄 만들기에 몰두하기 전에 잠시 올려다보는 로트윌>\n\n루시앙에게 가 봐요. 그리고 5번 기어가 필요하다고 말하고 그걸 내게 좀 가져다줄래요?", progress = nil, completion = "5번 기어라고요? 알겠어요. 어쩐지 불길한데...", rewards = nil},
[735] = {title = "별, 손, 그리고 심장", objective = "아이언포지, 쓸쓸한 뒷골목에 있는 게릭 본그립에게 본그립의 노트에 적힌 물건들을 가져가야 합니다.", description = "야그인의 법전? 드워프 역사의 새로운 장이라도 쓸 생각인가? 아니, 그건 내가 물어볼 질문이 아니로군.\n\n내게 여분이 한 권 있으니 자네를 도와 주도록 하지. 서로 도와 가며 사는 게 도리 아닌가? 그래야 발전이 있는 법이지.\n\n하지만 그전에 내가 원하는 3개의 강력한 물건들을 가져와야 하네. 확인 후 법전을 주도록 하지.\n\n쉿! 지금 누가 엿듣고 있을지도 모르니 물건들의 이름을 소리 내어 말하지는 않겠어. 대신 여기 적어 주지.", progress = "부탁한 유물들은 가져왔나?", completion = "재주가 좋군, &lt;class&gt; 친구. 자네 정도 실력이면 우리 드워프 역사의 새로운 장을 집필한다 하더라도 별문제가 없겠어.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[736] = {title = "별, 손, 그리고 심장", objective = "언더시티에 있는 벨두거에게 벨두거의 노트에 적힌 물건들을 가져가야 합니다.", description = "야그인의 법전이 필요하다고? 그렇다면 당신 계획은 또 다른 무리를 모으는 것인가? 당연히 그럴 테지... 물론, 도와주도록 하겠소. 하지만 당신도 날 도와줘야겠소.\n\n내가 요구하는 세 가지 강력한 물건을 가져오면 법전을 주도록 하지. 이 물건들의 이름은 입에 올리지는 못하니 노트에 적어 주도록 하겠소.\n\n이 목록에 적힌 이름의 물건들을 가져올 수 있을 정도라면 당신은 정말 우리 포세이큰에 새로운 역사를 기록할 만한 자격이 있는 것이오.", progress = "임무는 어떻게 되어가고 있소?", completion = "이 유물들을 찾아오다니 대단하군! 당신 솜씨가 아주 뛰어나거나 운이 특별나게 좋은 거겠군그래. 어느 쪽이든 당신은 우리에게 큰 도움이 되었소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[737] = {title = "금지된 지식", objective = "텔두린에게 야그인의 법전을 가져가야 합니다.", description = "자, 받게. 이 법전을 소중히 다루어야 하네. 또한 적의 손에 넘어가지 않도록 하길 바라네.\n\n이 법전에는 많은 진실이 담겨 있지...\n\n...저절로 타버릴 수도 있는 진실 말이야.", progress = "호! 꽤 오래 걸렸군그래. 법전은 가져왔나?", completion = "가져왔군! 아, 희망이 보여!\n\n덕분에 우리가 목숨을 구하게 될지도 모르겠어. 이거 기념비라도 세워야 하는데! 제단도 만들고! 그리고 대대손손 그 이름을 기려야겠지.\n\n하지만... 놈들이 풀려 나 땅 위로 나오면 모두 끝장이야. 그러면 대대손손이고 뭐고 없단 말이야.\n\n놈들이 풀려나면 우린 한낱 식사거리밖에 안 될 테니까...", rewards = "다음과 같은 것들을 받습니다:\n\n절망의 해골"},
[738] = {title = "아그몬드 찾기", objective = "아그몬드를 찾아야 합니다.", description = "발굴조사단장 아그몬드는 여기서 남서쪽에 있는 황야의 땅에서 발굴 현장을 지휘하고 있었소. 있었다라고 말한 건... 그게, 몇 주째 그에게서 아무 소식도 듣지 못해서요. 난 그의 보고를 받아야 하니 아그몬드를 찾아주시오.\n\n들은 바로는 아그몬드가 황야의 땅의 고통의 요새를 지나 최남단에 있는 조그마한 발굴현장에서 마지막으로 있었다고 하오. 우선 거기서부터 그를 찾아보시오.", progress = nil, completion = "유감스럽게도 이 뼈는 분명 아그몬드의 시체입니다. 시신은 온통 만신창이가 되어 있고 뼈는 새들이 모두 쪼아먹어 버렸습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n발굴조사단장의 찢어진 허리띠비취금 광석"},
[739] = {title = "멀달록", objective = "아그몬드를 살해한 멀달록을 처치해야 합니다.\n\n바위동굴일족 뼈다귀싸움꾼 12마리를 처치해야 합니다.\n\n그 후 모단 호수에 있는 발굴조사단장 아이언밴드에게 보고하십시오.", description = "아그몬드의 자취가 서쪽에서 이어지고 있습니다. 바위와 모래에 피가 묻어 있는 것으로 보아 이 드워프는 죽기 전에 얼마간의 거리를 기어와서 이곳에서 죽은 것으로 보입니다.\n\n자세히 살펴보니 황야의 땅 사암 조각에 \"멀달록\"이라는 단어가 휘갈겨 쓰여 있습니다. 아마도 아그몬드가 죽기 직전에 쓴 것으로 보입니다.\n\n이 단어가 쓰인 바로 옆에는 죽은 아그몬드의 손이 있습니다.", progress = nil, completion = "정말 안타까운 소식이군. 그러나 아그몬드는 그 강한 팔로 사납게 망치를 휘두를 수 있었던 강한 드워프였으며 트로그들 만큼이나 단단히 무장하고 있었소이다! 비록 그가 저주받은 트로그에게 죽었다고 해도 난 그가 수많은 트로그들을 저승 가는 길동무로 함께 데리고 갔으리라 믿소.", rewards = "다음과 같은 것들을 받습니다:\n\n바위 분쇄기"},
[741] = {title = "정신 없는 발굴조사단장", objective = "다르나서스에 있는 수석고고학자 그레이위스커에게 신비로운 화석을 가져가야 합니다.", description = "발굴조사단장께서 신비로운 화석을 다르나서스에 있는 탐험가 연맹으로 보내시길 원하신단 말인가요? 하지만 저 혼자 이 어둠의 해안을 떠날 수는 없답니다.\n\n자, 이 신비로운 화석을 다르나서스에 있는 수석고고학자 그레이위스커님께 전해주세요.", progress = "무슨 일이오, <race>?", completion = "오! 그 정신 없는 발굴조사단장 렘트레블이 이렇게 굉장한 발견을 하다니!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n망치주먹 장갑바람숨결 장갑유물사냥꾼 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[742] = {title = "잿빛 골짜기 사냥 대회", objective = "잿빛 골짜기의 토막나무 주둔지에 있는 세나니 썬더하트를 만나야 합니다.", description = "젊은 모험가들이여, 잘 들으십시오! 잿빛 골짜기의 야생이 당신을 기다리고 있습니다!\n\n호드는 불모의 땅 북쪽에 튼튼한 전초 기지를 세웠습니다. 토막나무 주둔지와 조람 해안에 있는 주둔지에서는 호드의 이름을 빛내려 노력하고 있습니다! 자신을 증명하고 싶은 이는 그곳에서 안내를 받으시기 바랍니다. 불모의 땅 바로 위에 있는 토막나무 주둔지의 세나니 썬더하트가 잿빛 골짜기 사냥에 참가할 모험가를 찾고 있으니 참고하시기 바랍니다!", progress = nil, completion = "새로운 개척지로 온 것을 환영합니다. 잿빛 골짜기는 당신 같은 젊은이들이 용기를 시험할 기회가 대단히 많은 곳입니다. 일단 이 주둔지를 살펴본 다음 조람 해안으로 나가면 또 다른 호드의 주둔지가 있으니 그곳에 가 보는 것도 잊지 마십시오.\n\n그나저나 여기로 온 것을 보니 사냥에 대해 더 많은 것을 배우러 온 것 같은데... 내 말을 잘 들으십시오. 그러면 배우고자 하는 바를 기꺼이 가르쳐 주겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[743] = {title = "성난바람하피의 위협", objective = "블러드후프 마을에 있는 루울 이글탈론에게 성난바람하피의 갈퀴발톱 8개를 가져가야 합니다.", description = "내 이야기를 들어줄 시간을 내줘서 고맙네. 나는 전사지만 가르치는 일도 겸하고 있고 이름은 루울이라고 하네.\n\n<형제/자매>도 이제 멀고어 밖으로 모험을 떠날 준비가 되었는지 자신을 시험해 봐야 할 시기가 된 것 같군.\n\n자신의 힘을 시험해 보고 싶다면, 남동쪽에 있는 성난바람하피부터 시작해 보도록 하게. 그들은 길에서 떨어져 있는 산자락 주변에 서식하고 있네.\n\n이 짐승은 이곳 멀고어에서 우리의 천적 중 하나이며 물론 <형제/자매>의 능력을 판단할 수 있는 좋은 기준이 될 걸세.", progress = "성난바람 하피들은 결코 살려 둬서는 안 될 적일세. 신선한 고기에 대한 그들의 갈망만큼이나 전투에서 그들의 힘은 막강하다네.", completion = "수고했네. 형제는 모험을 계속할 준비가 되어 있는 것 같군. 언제나 자신이 옳다고 생각하는 길로 가길 바라네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[744] = {title = "의식을 위한 준비", objective = "하늘색 깃털 6개와 청동색 깃털 6개를 모아 썬더 블러프에 있는 이얀 이글탈론에게 가져가야 합니다.", description = "나에게는 형님이 한 분 계시다오. 그 형님께서 곧 블러드후프 족장님을 만나는 의식을 치르게 되는데, 형님의 의식을 위해 머리 장식을 만들어 드리려 하오.\n\n내가 이 가죽끈을 다듬는 동안 당신에게 부탁할 일이 있는데... 내가 충분한 양의 깃털을 모아 올 시간이 없으니, 날 위해 깃털을 좀 모아 주겠소?\n\n썬더 블러프 멀리 북쪽과 북서쪽에 사는 하피들에게서 적당한 크기의 깃털을 얻을 수 있을 것이오. 하늘색 깃털과 청동색 깃털이 각각 6개씩만 있으면 원하는 모양의 머리 장식을 완성할 수 있을 것 같소.", progress = "이 머리 장식은 분명 형님께 좋은 선물이 될 것이오.", completion = "도와 줘서 고맙소.\n\n형님의 의식을 위한 선물이 이제 거의 완성되었군. 나에겐 형님을 위해 머리 장식을 만들고 의식을 지켜볼 의무가 있소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n끈으로 엮은 멜빵부족 전사의 방패\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[745] = {title = "대지의 공유", objective = "회색갈기일족 무두장이 10마리와 회색갈기일족 가죽장이 8마리, 회색갈기일족 밀렵꾼 5마리를 처치한 다음 블러드후프 마을에 있는 바인 블러드후프에게 돌아가십시오.", description = "이 땅은 많은 반목과 대립으로 상처받고 있네. 내가 알고 있는 많은 것들처럼 자네는 더 이상의 충돌을 목격하지 않기만을 바랄 뿐이지. 그럼에도 자네에게 부탁할 일이 하나 있네. 이 땅에서 일어나는 아주 작은 위협이라도 빨리 손을 쓰지 않으면 얼마나 끔찍한 결과를 가져올 수 있는지 이번 일을 통해 알게 될 걸세.\n\n회색갈기일족 놀들이 블러드후프의 남쪽과 서쪽에 있는 바위굴에 정착했네. 그들은 대화로 해결하려는 우리의 노력을 무시하고 평화롭게 초원을 뛰노는 멀고어의 야생동물들을 무참히 학살하고 있어.\n\n이제는 대화로 문제를 해결하기에는 너무 늦은 것 같네.", progress = nil, completion = "내가 부탁한 임무를 진지하게 받아들여 준 점 고맙게 생각하네. 이 땅과 여기에 살고 있는 생물들을 존중하는 것은 중요한 일이지. 삶과 죽음은 순환되는 것이고, 또 필연적인 것이야. 그리고 모든 생물은 다른 생물들 없이는 존재할 수 없는 것이네. 이 점을 시간을 가지고 숙고하고 절대 잊지 말도록 하게.", rewards = "다음과 같은 것들을 받습니다:\n\n섬광 탄환"},
[746] = {title = "드워프 발굴지", objective = "발굴조사단장의 곡괭이 5개를 모아야 합니다.\n\n가열로에서 발굴조사단장의 곡괭이를 부러진 곡괭이로 만들어야 합니다.\n\n블러드후프 마을에 있는 바인 블러드후프에게 부러진 곡괭이 5개를 가져가야 합니다.", description = "북서쪽에 드워프들이 준비하고 있는 발굴지가 있네. 그 키작은 녀석들은 땅속에 비밀이 묻혀 있다고 생각하고 있지. 그게 사실이긴 하지만 대지를 파헤치고 더럽힌다고 해서 그걸 알아낼 수 있는 건 아니라네.\n\n드워프들의 발굴도구를 모아서 박살내고 놈들의 부러진 곡괭이들을 가지고 내게 돌아오게.\n\n가열로 부근에서 놈들의 곡괭이를 부술 수 있을 걸세. 썬더 블러프에 가열로가 하나 있긴 하지만 어떤 가열로라도 상관없다네. 아마 드워프 야영지에 있는 가열로만으로도 충분할 것이야.", progress = "어서 오게. 부러진 곡괭이는 가져왔나? 드워프 놈들의 발굴 작업은 멀고어에 서식하는 코도들을 자극할 걸세. 반드시 놈들을 막아야 하네!", completion = "고맙네. 이제 멀고어의 짐승들은 평온해질 걸세. 그리고 드워프들 역시 대지를 파헤치는 것만으론 아무것도 알 수 없다는 걸 배우는 계기가 되었길 바라네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n강화된 손목보호구투박한 코도 다리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[747] = {title = "사냥의 시작", objective = "나라체 야영지에 있는 그룰 호크윈드가 초원타조 깃털 7개와 초원타조 고기 7덩이를 가져다 달라고 부탁했습니다.", description = "당신은 전도 유망한 풍모를 지니고 있으며, 우리 부족에서 스스로 가치를 증명하게 될 것이오. 아마 머지않아 위대한 도시 썬더 블러프에서 당신이 환영 받을 날이 올 거요. 하지만 그 전에 먼저 우리 아버지이신 호크윈드 족장님께 당신의 능력을 증명해 보여야 하오.\n\n이곳 붉은구름 고원의 타우렌들은 자신의 훌륭한 사냥 실력에 대해 자부심을 가지고 있소. 우리 타우렌은 필요에 의해 사냥을 하기도 하고, 실력을 겨루기 위해 사냥을 하기도 하지. 그런데 지금 마을에 고기는 거의 바닥났고 옷을 만들 깃털도 필요한 상황이오. 근처에 있는 초원타조를 사냥해 마을에 필요한 물자를 보충하여 당신의 능력을 증명해 보시오.", progress = "우리 부족을 위해 고기와 깃털을 마련해 준다면 족장님께 사냥꾼으로서 당신의 능력을 증명해 보이는 첫 걸음이 될 거요.", completion = "나라체의 타우렌들을 대신해 감사를 전하오. 당신은 우리에게 믿음을 심어 주었소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n유목민의 허리띠채색한 사슬 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[748] = {title = "오염된 우물", objective = "블러드후프에 있는 멀 썬더혼에게 초원늑대 앞발 6개와 초원타조 갈퀴발톱 4개를 가져가야 합니다.", description = "고블린과 놈들의 부하들이 우리의 신성한 우물들을 점령하고 더럽히고 있소! 이건 절대 용납할 수 없는 일이오.\n\n우물을 정화하기 위해서는 각 우물을 위한 정화의 토템상을 만들어야 하오. 그러고 나서 당신이 그 토템상을 우물로 가져가 정화의 의식을 수행해 주시오.\n\n우선 윈터후프 우물을 위한 정화의 토템상을 만들어야 하는데, 그러기 위해서는 대지의 도움을 받아야 하오. 토템상에 필요한 재료는 남서쪽에 서식하는 초원늑대의 앞발과 다자란 초원타조의 발톱이오. 앞발과 발톱을 구해 내게 돌아오시오.", progress = "앞발과 발톱은 가져왔소, 형제여?", completion = "잘했소. 이제 내가 이 재료들의 힘을 정화의 토템상에 불어넣도록 할 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[749] = {title = "습격당한 짐마차 행렬", objective = "모린 클라우드스토커가 습격당한 짐마차 행렬에 실려 있는 보급상자의 내용물을 확인해 달라고 부탁했습니다.", description = "며칠 전, 투자개발회사의 짐마차가 경호를 받으며 황소바위 호수의 북쪽 가장자리를 따라 이동하는 것을 발견했소. 우린 이전 전투에서 병사 둘을 잃었기 때문에 재빨리 짐마차를 공격해 파괴했소.\n\n우린 짐마차의 잔해에 불을 지르곤 놈들의 보급 상자를 확인하지 못하고, 상자들이 모두 불타 버릴 거라고 생각했소. 하지만 투자개발회사의 구조대가 불에 탄 마차 근처에서 목격된 걸 보니 우리 생각이 틀렸던 모양이오.\n\n짐마차가 있는 곳으로 가서 상자의 내용물을 좀 확인해 주시오.", progress = nil, completion = "상자의 모든 면에는 '투자개발회사 채광부'라는 도장이 찍혀 있습니다. 한쪽 면에는 상자의 내용물이 투자개발회사의 중앙 공장에서 가공하기 위한 물품임을 나타내는 내용이 정성스럽게 인쇄되어 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[750] = {title = "계속되는 사냥", objective = "나라체 야영지의 그룰 호크윈드가 산지퓨마 모피 10필을 가져다 달라고 부탁했습니다.", description = "사냥에 능한 타우렌이라면 단순히 과시하기 위해 사냥을 하는 것은 아님을 알고 있을 것이오. 평야에 서식하는 짐승들은 우리에게 곧 생존 수단이기도 하기 때문이지. 혹시 당신이 산지퓨마 모피를 구해올 수 있다면 마을의 장로들에게 깊은 인상을 심어줄 수 있을 거요. 산지퓨마들은 남쪽 언덕으로 가면 찾을 수 있소.\n\n지금 우리에겐 아이들의 옷을 만들고 천막을 수리할 가죽이 필요하오.", progress = "부족을 위해 가죽을 구해 준다면 내 아버지, 족장 호크윈드께 당신의 공로를 전하겠소.", completion = "나라체의 타우렌들을 대신해 감사를 전하는 바이오. 당신의 사냥술이라면 틀림없이 썬더 블러프에서도 인정받을 날이 올 거요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n유목민의 팔보호구채색한 사슬 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[751] = {title = "습격당한 짐마차 행렬", objective = "블러드후프 마을 근처에 있는 모린 클라우드스토커에게 투자개발회사의 문서를 가져가야 합니다.", description = "뚜껑을 열자 잘 분류된 광석과 광물, 그리고 투자개발회사가 멀고어에서 채굴 작업을 진행 중임을 나타내는 물건들이 빼곡히 들어 있습니다. 광석과 광물 위에서 단단히 묶여 있는 종이 뭉치를 꺼냅니다.\n\n동쪽의 작은 언덕에서 작업하는 소리가 희미하게 들리고 큰 불에서 나는 연기가 보입니다.", progress = "어서 오시오. 우리 땅에서 투자개발회사가 벌이고 있는 일들에 관해 새로운 소식이 있소?\n\n놈들이 다른 곳에서처럼 이 땅을 부당하게 착취할 계획이라면 우리의 정찰병들이 즉시 이를 저지할 것이오.", completion = "이건 투자개발회사가 우리의 천연 자원을 훔치려는 것이 사실이라는 것을 말해주는군. 다행히 미리 알았으니, 이제 조치를 취해야 할 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[752] = {title = "작은 부탁", objective = "족장 호크윈드가 나라체 야영지 남동쪽에 있는 우물 근처에서 그의 어머니를 찾아봐 달라고 부탁했습니다.", description = "우리 부족원들은 조화로운 삶을 공유하며 살아가고 있지. 삶도 같이 하고 일도 함께 하면서 말일세.\n\n부족이 서로 조화롭게 어울려 살아가기 위해서는 그에 따른 책임이 따른다네. 그런 의미에서 그대에게 작은 부탁 하나 하지.\n\n우리 어머니께서 오늘 아침 나라체 남동쪽에 있는 우물로 물을 길러 떠나셨지. 벌써 출발하신 지 꽤 되었다네. 내가 여기서 부족 일을 돌보는 동안 자네가 어머니를 찾아 무슨 일이 생기신 건 아닌지 좀 알아봐 주겠나?", progress = nil, completion = "이 노파를 돕기 위해 여기까지 왔단 말인가? 이런, 이런. 참으로 고마우이.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[753] = {title = "작은 부탁", objective = "우물에 있는 물병을 집어서 우물에서 북서쪽에 있는 나라체 야영지의 족장 호크윈드에게 가져가야 합니다.", description = "내 소싯적에는 여행도 많이 다니곤 했지만 이젠 몸이 예전같지 않구먼. 그래도 아직은 부족을 위해 내 소임을 다할 정도는 된다네. 나이 든 노파이니 때론 예전보다 시간이 좀 더 걸리는 편이긴 하지만 말이야.\n\n자네는 의욕이 넘치는 <class> 같군. 그 젊은 혈기로 부탁 하나만 들어주지 않겠나? 우물에 있는 물병을 내 아들, 나라체 야영지의 족장에게 좀 가져다주게나.\n\n보잘것 없는 부탁이지만 잘해내 준다면 마을 장로들의 인정을 받을 수 있다는 사실을 잊지 말게.", progress = "초원에서 막 돌아온 모양이군. 내 어머니께서 전하신 말씀이 있으신가?", completion = "우리 어머님의 부탁으로 이 물병을 가져다준 것이로군. 고맙네.\n\n다른 이들을 흔쾌히 도와 주고 나라체 야영지의 타우렌들을 위해 수고를 아끼지 않는 모습을 보니 언젠가 그대가 썬더 블러프에서 부족의 자랑거리가 될 거라는 확신이 드는군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[754] = {title = "윈터후프 정화", objective = "윈터후프 우물에서 윈터후프 정화의 토템상을 사용한 후 멀 썬더혼에게 돌아가야 합니다.", description = "윈터후프 우물을 정화할 토템상이 완성되었소. 이제 이 토템상을 우물로 가져가 정화의 의식을 수행하도록 하시오. 윈터후프 우물은 남동쪽에 있는데 괘씸한 고블린 녀석들이 지키고 있소.\n\n쉽지 않은 일이겠지만 우물을 다시 사용하려면 반드시 해야 할 일이오.\n\n행운이 함께하기를 비오.", progress = nil, completion = "방금 전에 형제의 활약에 대한 소식을 들었소. 벌써 우물 주위의 동물들이 마음껏 우물물을 마시고 있다고 하오.\n\n이 땅을 위해 큰 일을 해 주었소. 이는 곧 &lt;race&gt; 주민을 위한 일이기도 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[755] = {title = "대지모신의 의식", objective = "나라체 야영지 정남쪽에 있는 언덕에 사는 예언자 그레이텅을 찾아가야 합니다.", description = "나라체의 타우렌들을 위해 작은 일도 마다하지 않는 마음과 배우고자 하는 열의는 아주 고귀한 성품일세. 그대라면 언젠가 썬더 블러프에서도 위대한 <class>|1으로서;로서; 이름을 떨칠 수 있을 거라 믿네.\n\n그 전에 먼저 세 가지로 이루어진 대지모신의 의식을 수행해야 하네.\n\n첫 번째 시험은 힘의 의식일세. 예언자 그레이텅을 찾아가 족장 호크윈드가 보냈다고 전하게.\n\n나라체 야영지 남쪽으로 곧장 가면 언덕에 숨겨진 그의 거처를 찾을 수 있을 걸세.", progress = nil, completion = "호크윈드 족장님께서 보냈다고 했소? 대지모신의 의식을 수행하는 것은 결코 쉬운 일이 아니오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n야생의 징표\n\n다음과 같은 것들을 받습니다:\n\n"},
[756] = {title = "썬더혼 토템상", objective = "멀 썬더혼에게 긴발톱 초원늑대 발톱 6개와 평원퓨마 발톱 6개를 가져가야 합니다.", description = "썬더혼 정화의 토템상을 만들기 위해서는 멀고어 평야에 살고 있는 포식 동물의 발톱을 모아 와야 하오. 긴발톱 초원늑대와 평원퓨마를 잡아 발톱을 구해 돌아오시오.\n\n긴발톱 초원늑대와 평원퓨마는 이곳의 동쪽과 서쪽에서 발견할 수 있을 거요.", progress = "내가 부탁한 발톱은 구해 왔소? 시간이 지날수록 썬더혼 우물의 오염이 점점 더 심해지고 있소!", completion = "고맙소, 형제여. 정화의 토템상을 만드는 데는 짐승을 사냥할 때의 활기찬 기운이 가장 중요하오.\n\n고블린들은 대지와 조화를 이루며 사는 것과 대지에 맞서는 것의 차이를 절대 알지 못할 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[757] = {title = "힘의 의식", objective = "칼날가시 협곡에 있는 뾰족털일족들을 처치하고 나라체 야영지에 있는 족장 호크윈드에게 뾰족털일족 허리띠 12개를 가져가야 합니다.", description = "대지모신의 의식은 젊은 타우렌이 썬더 블러프에서 인정을 받기 위해 반드시 거쳐야 할 과정이요.\n\n우선 그대는 이번 힘의 의식을 통과해야만 하오. 이 시험을 통해 그대는 부족의 적을 처치하여 자신의 용맹함을 증명해야 하오.\n\n동쪽에 있는 칼날가시 협곡의 뾰족털일족들이 우리 부족의 땅을 침범하고 있소. 그들은 우리 사냥꾼들을 매복하여 공격하고 어둠을 틈타 마을을 약탈하고 있소.\n\n이 악당들을 처치하여 그대의 용맹함을 보이고, 그 증거로 그들의 허리띠를 나라체 야영지의 족장님께 가져가도록 하시오.", progress = "힘의 의식은 완수했는가? 우리 부족의 적, 뾰족털일족 놈들에게 맞서 싸울만한 용기가 있다는 걸 보여 줄 증거가 필요한데...", completion = "그대는 대지모신의 의식 중 첫 번째 시험을 통과했네. 부족 전체가 그대를 자랑스럽게 여길 것이야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n바위 철퇴무딘 토마호크조각용 나이프장로의 지팡이용사의 도끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[758] = {title = "썬더혼 정화", objective = "썬더혼 우물에서 썬더혼 정화의 토템상을 사용하십시오. 그런 다음 멀 썬더혼에게 돌아가야 합니다.", description = "토템상이 준비되었소. 다시 한번 말하지만, 정화의 의식을 수행하는 건 <형제/자매>의 몫이오.\n\n마을 북쪽에 있는 썬더혼 우물로 가서 썬더혼 정화의 토템상을 사용하여 의식을 수행하시오. 의식을 마친 후에는 내게 돌아와야 하오.\n\n정령들의 가호가 함께하기를...", progress = nil, completion = "꿈에서 썬더혼 부족의 선조가 내게 와 형제가 우물에서 행한 일을 칭찬했다오.\n\n또한 그들의 감사를 전하기 위해 형제에게 이걸 전해주길 바라고 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n썬더혼 망토"},
[759] = {title = "와일드메인 토템상", objective = "블러드후프 마을에 있는 멀 썬더혼에게 우두머리 초원늑대 이빨 8개를 가져가야 합니다.", description = "이제 남은 우물 하나, 와일드메인 부족의 이름을 딴 우물을 정화하는 일만 남았소. 이 우물을 깨끗이 정화하려면 이 땅의 난폭한 포식자인 우두머리 초원늑대 이빨이 필요하오. 북쪽에서 우두머리 초원늑대를 찾아 사냥해 돌아오시오.\n\n우두머리 초원늑대들은 종종 위대한 도시 썬더 블러프의 기슭을 돌아다니곤 하오.", progress = "부탁한 이빨은 구해 왔소?", completion = "수고했소, 형제여. 나는 이를 통해 대지의 희생을 느낄 수 있소. 그리고 내 영혼에 슬픔과 자랑스러움이 함께 복받치고 있소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[760] = {title = "와일드메인 정화", objective = "와일드메인 우물에서 와일드메인 정화의 토템상을 사용한 다음 멀 썬더혼에게 돌아가야 합니다.", description = "윈터후프와 썬더혼 우물을 정화한 <형제/자매>의 공적은 이미 많은 이들에게 회자되고 있소. 와일드메인 토템상이 만들어졌으니 이제 <형제/자매>가 수행할 마지막 임무가 남아 있소.\n\n와일드메인 우물은 썬더 블러프 북쪽에 있소. 그곳에서 의식을 수행하고 고블린의 독으로 오염된 땅을 정화하도록 하시오! 다시 한번 깨끗한 물이 흘러나올 수 있도록 하시오!", progress = nil, completion = "해냈구려. 우물들을 정화하고 우리 영토를 치유해 준 데 대해 블러드후프 마을을 대표해 감사를 전하오.\n\n형제의 업적은 오랫동안 바람을 타고 전해지며 멀고어의 물은 영원히 깨끗하게 보존될 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n의식의 토마호크꿈의 감시자 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[761] = {title = "검독수리 사냥", objective = "블러드후프 마을에 있는 하큰 윈드토템에게 검독수리 깃털 8개를 가져가야 합니다.", description = "검독수리는 교활한 새라 녀석들을 찾아 사냥한다는 건 쉬운 일이 아니지. 때문에 검독수리 깃털을 수집하는 것은 사냥꾼에게 유능함과 결단력을 상징하고 있소.\n\n이 일을 해볼 생각이 있다면 평야로 가서 검독수리들을 사냥해 보시오. 내게 검독수리 깃털을 가져오면 <형제/자매>의 명예가 높아질 거요.\n\n검독수리들은 멀고어 어디에나 서식하고 있소. 하지만 눈을 크게 뜨고 살펴야만 찾을 수 있으며, 발이 빨라야 녀석들을 잡을 수 있다는 것을 명심하시오.", progress = "검독수리들은 찾았소? 놈들의 깃털을 가져온 거요?", completion = "이 깃털을 모으는 게 쉽지 않았을 거란 걸 잘 알고 있소. 이 일을 통해 형제가 뛰어난 &lt;class&gt;임을 입증한 셈이오. 블러드후프 마을에 형제 같은 이가 오다니 자랑스러운 일이 아닐 수 없소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[762] = {title = "악의 사자", objective = "고통의 요새에 있는 사자 인페르누스를 처치하고 아이언포지에 있는 조언자 벨그룸에게 그의 죽음에 대한 증거를 가져가야 합니다.", description = "라그나로스는 울다만에서 사라진 유물을 찾고 있는 어둠괴철로단 드워프들을 보호하기 위해 사자 인페르누스를 고통의 요새로 보냈지.\n\n이미 우리 종족에게 무서운 참사가 일어났지만 그 위력은 우리의 예상보다는 미비한 것이었네. 하지만 놈들이 얼마나 많은 양의 유물을 찾아 아이언포지 공격에 사용할지 생각하기조차 싫군.\n\n우리의 목표는 간단하네, <class>. 황야의 땅으로 돌아가 사자 인페르누스를 처치하게. 위협이 제거되면 승리의 증거를 가지고 조언자 벨그룸님께 돌아가면 되네.\n\n이제 모든 건 자네 손에 달렸어.", progress = "시간이 없네. 라그나로스는 우리가 준비될 때까지 기다려 주지 않을 거야.", completion = "아이언포지와 드워프들을 위한 자네의 헌신에 대해서는 반론의 여지가 없소. 당신의 도움에 감사하는 바이오.\n\n역사학자 카르닉에게 모든 일이 잘 처리되었다고 알리도록 하지. 그리고 가능한 빨리 발굴현장을 복구할 수 있도록 황야의 땅으로 지원 병력을 보내도록 하겠소.\n\n다시 한번 감사하오.\n\n참, 떠나기 전에 브론즈비어드 폐하의 이름으로 당신에게 한가지 더 부탁할 일이 있는데...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n드워프 경비대장의 검"},
[763] = {title = "대지모신의 의식", objective = "블러드후프 마을에 있는 바인 블러드후프에게 호크윈드의 토템을 가져가야 합니다. 나라체 야영지 외곽의 길을 따라가십시오.", description = "대지모신의 의식을 계속 수행하려면 두 가지 시험을 더 통과해야 하네. 그대의 경험을 넓힐 때가 된 것이야.\n\n블러드후프 마을로 가서 케른 블러드후프님의 아들이자 족장인, 바인 블러드후프를 찾도록 하게. 거기서 모험을 계속하다 보면 썬더 블러프 장로들의 신임을 얻을 수 있을 걸세.\n\n이 토템을 바인에게 가져가도록 하게. 그 친구가 내 목각품이라는 것을 알아보고 그대를 도와줄 걸세.\n\n서둘러 나라체 야영지 외각의 길을 따라 가도록 하게. 한눈 팔면 길을 잃을 수도 있으니 조심하게.", progress = "우리 마을엔 어쩐 일이신가, <class> 친구?", completion = "내 절친한 친구 호크윈드가 보낸 게로군! 오, 그의 토템을 보낸 걸 보니 자넨 특별한 자로군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[764] = {title = "투자개발회사", objective = "블러드후프 마을에 있는 모린 클라우드스토커를 위해 투자개발회사 노역꾼 14명과 투자개발회사 현장감독 6명을 처치해야 합니다.", description = "흠, 이제 멀고어에서 투자개발회사 직원들과 장비들이 점점 더 많이 목격되고 있는 이유를 알 것 같소. 저 고블린 녀석들... 투자개발회사가 이익을 위해 사업을 너무 급하게 확장하고 있소. 그들은 자신들이 고블린을 위해 대단한 일을 하고 있다고 말하고 있지만 어림없는 소리요. 저들의 목적이 무엇인지는 충분히 짐작하고도 남지.\n\n놈들은 탐욕스러운 난쟁이들에 불과하오. 그들의 사업에는 안 된 일이지만, 우리 타우렌들은 놈들이 우리 땅에서 사업을 벌이는 걸 두고 볼 수 없소. 습격당한 짐마차 행렬의 동쪽에 있는 놈들의 광산으로 가서 우리의 뜻을 전하시오.", progress = nil, completion = "이번엔 놈들도 우리의 뜻을 잘못 이해하거나 무시할 수 없을 거요, 안 그렇소? 이젠 우리 &lt;race&gt;들을 가볍게 여기진 못하겠지. 우리 땅에서 그들이 천연 자원을 훔쳐가는 걸 그냥 두고만 볼 거라 믿을 만큼 거만할 순 없을 테니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[765] = {title = "감독관 피즈스프로켓", objective = "감독관 피즈스프로켓을 처치하고 블러드후프 마을의 모린 클라우드스토커에게 피즈스프로켓의 서류철을 가져가야 합니다.", description = "당신이 짐마차에서 가져온 문서에 따르면 투자개발회사는 이 땅에서 우리를 몰아내고 우리 땅을 마음껏 약탈하기 위해 많은 계획을 세웠군.\n\n목표한 바를 이루기 위해 수단과 방법을 가리지 않는 그들을 보면 혐오감에 몸이 오싹해지기까지 하는군그래. 그 계획을 세운 배후의 지도자를 처치해야 하오. 바로 감독관 피즈스프로켓이라는 자인데, 습격당한 짐마차 행렬 동쪽에 있는 투자개발회사 광산으로 가면 찾을 수 있을 거요. 뭔가 유용한 정보를 얻을지도 모르니, 내게 그 자의 서류철을 가져다주시오.", progress = "투자개발회사 놈들이 오로지 이익만을 위해 우릴 상대로 극악무도한 일을 꾸미고 있다고 생각하니 화가 치밀어 참을 수가 없군.", completion = "그 피즈스프로켓이라는 악당이 죽었다는 소식에 화가 다소 누그러진 것 같소. 나는 이제 녀석의 개인적인 영향력과 투자개발회사의 앞으로의 계획에 대한 추가적인 정보가 있는지 알아보도록 하겠소. 수고했소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n소형 전투용 나이프고블린 분쇄기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[766] = {title = "마즈라나체", objective = "블러드후프 마을에 있는 마우르 레인콜러에게 초원늑대 심장, 평원퓨마 다리뼈, 초원타조 비늘과 검독수리 내장을 가져가야 합니다.", description = "우리 할아버지께서는 내게 마즈라나체라는 타조 녀석과 싸웠던 얘기를 해 주시곤 했지. 할아버지는 마즈라나체의 악마 같은 붉은 눈과 면도날처럼 날카로운 발톱, 독을 뿜는 이빨에 대해 얘기해 주셨어.\n\n그런데 마치 그게 예언이었던 것처럼 평야를 여행하다 우연히 놈과 마주쳤고 놈에게 어깨를 물리고 말았네. 놈은 할아버지께서 말씀하신 그대로 정말 끔찍한 놈이었지. 놈에게 물린 상처의 감염을 막으려면 몇 가지 재료가 필요한데 좀처럼 얻기 힘든 것들이지. 늑대 심장, 퓨마의 다리뼈, 초원타조 비늘, 그리고 검독수리 내장이 필요하다네.\n\n시간이 부족하니 서둘러 주게.", progress = "점점 열이 높아지고 의식이 혼탁한 악몽 속으로 빠져들고 있네... 애초에 할아버지께서도 처치하지 못한 그 짐승을 내가 상대하려 했던 게 실수였지...\n\n치료약을 만들 재료는 구했나? 감염 부위를 빨리 치료하지 않으면 나에게 죽음이 엄습하게 될 걸세.", completion = "아, 고맙네. 자네가 구해 온 재료로 치료약을 만들어 독이 퍼지는 걸 막고 상처를 완전히 치료할 수 있을 거야. 덕분에 목숨을 건졌군. 내 생명을 구해줘서 정말 고맙네.\n\n하지만 마즈라나체가 날 공격할 때 냈던 그 날카로운 울음소리와 나를 향해 달려들던 불타는 듯한 부리의 색은 절대 잊지 못할 걸세.\n\n자네도 놈을 조심하길 바라네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n절벽 등산용 장화초원 사냥꾼 손목보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[767] = {title = "예언의 의식", objective = "블러드후프 마을에 있는 잘만 투문과 대화해야 합니다.", description = "대지모신의 의식 중 하나인 예언의 의식은 썬더 블러프 장로들의 신임을 얻는 데 도움이 될 걸세.\n\n우리 타우렌들은 대지가 우리의 가장 신성한 부양자라는 사실을 배워 왔지. 의식에서 예언을 직접 얻으려면 마을의 정신적 지도자인 잘만 투문을 만나야 할 게야.", progress = nil, completion = "젊은 &lt;class&gt;|1이여;여;, 그대가 올 줄 알고 있었지. 나는 언제나 대지모신의 의식을 수행하려는 자를 알아볼 수 있다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[768] = {title = "가죽 수집", objective = "썬더 블러프에 있는 베렌 톨스트라이더에게 얇은 가죽 12개를 가져가야 합니다.", description = "어서 오시오, 젊은이. 당신 눈빛을 보니 평야로 돌아가 사냥하고픈 욕망이 가득하군. 당신이 부족의 명예를 빛내게 되기를 진심으로 바라오!\n\n나는 썬더 블러프 마을 주민들을 위해 짐승 가죽으로 평상복과 갑옷을 만들고 있소.\n\n당신도 짐승을 사냥하게 되면 가죽을 내게 가져다주시오. 그러면 당신을 위해 무언가 만들어 주도록 하겠소.", progress = "다시 봐서 기쁘오. 사냥은 했소? 그럼, 가죽은 가져왔겠지?", completion = "오, 좋은 가죽이로군. 괜찮은 가죽 제품을 만들 수 있겠어.\n\n자, 대가로 이걸 받으시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n동물 가죽 허리띠두겹 가죽 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[769] = {title = "코도 가죽 자루", objective = "썬더 블러프에 있는 베렌 톨스트라이더에게 얇은 가죽 4개와 굵은 실타래 4개를 가져가야 합니다.", description = "멀고어에 사는 코도는 힘이 세고 용맹해서 우리에겐 동경의 대상이지. 혹 당신이 가죽 세공을 익혔고, 코도 가죽 자루를 만드는 기술을 익히고 싶다면 거래에 필요한 물품을 좀 구해다 주시오.\n\n그렇게 해준다면 내가 방법을 알려 주겠소.", progress = "가죽은 가져 왔소?", completion = "아, 훌륭하군. 고맙소. 당신처럼 가죽 세공에 관심 있는 젊은이를 만나는 건 언제나 기분 좋은 일이오.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 코도 가죽 가방"},
[770] = {title = "악마의 흔적이 남은 가죽망토", objective = "유령울음늑대에 대해 아는 이를 찾아야 합니다.\n\n제공된 아이템: \n", description = "해진 유령울음늑대의 가죽에는 아직도 불타는 군단과의 전투에서 입은 끔찍한 상처가 남아 있습니다.\n\n블러드후프 마을에 유령울음늑대의 죽음에 대해 아는 이가 있을지도 모릅니다...", progress = nil, completion = "내 눈을 믿을 수가 없군! 거대한 유령울음늑대를 쓰러뜨렸단 말인가? 이거, 다시 보게 됐군, 젊은 &lt;class&gt; 양반. 놀라운 능력을 지닌 사냥꾼이구려!\n\n젊은이에게 주고 싶은 게 있네. 비록 난 이제 사냥을 나갈 수 없지만 젊은이가 내 무기를 사냥에 사용해 준다면 영광이겠네. 이 사실이 알려지면 자네 명성이 드높아질 게야.\n\n그리고 유령울음늑대의 영혼도 이제 마침내 안식을 찾기를 젊은이도 함께 빌어주시게.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n스코른의 망치스코른의 라이플\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[771] = {title = "예언의 의식", objective = "우물돌 2개와 대지열매 2개를 모아 블러드후프 마을에 있는 잘만 투문에게 가져가야 합니다.", description = "예언의 의식을 행하려면 예언의 물을 만들기 위해 필요한 재료들을 모아야 하네.\n\n우선 멀고어의 우물 주위에서 볼 수 있는 우물돌이 필요하지. 또 우리 땅에서 자라는 거대한 나무 밑 여기저기 떨어져 있는 대지열매를 주워 우물돌과 결합해야 하네.\n\n이 재료들은 마법 성분이 있어 부족의 불로 끓여 마시면 미래를 예견할 수 있을 것이야. 그 예견을 따르면 이 신성한 임무의 다음 단계에 다다르게 될 것이네.", progress = "우물 주위의 우물돌과 나무 밑에 있는 대지열매를 충분히 모아 오면 내가 예언의 물을 준비해 주도록 하겠네.", completion = "이제 우리의 신성한 땅에서 재료를 구하는 방법을 터득한 것 같군. 이제 예언의 물을 만들어 주도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[772] = {title = "예언의 의식", objective = "블러드후프 마을에 있는 부족의 불 앞에서 예언의 물을 마시고 나타나는 예언을 따라가야 합니다.\n\n제공된 아이템: \n", description = "자, 예언의 물을 받게.\n\n준비가 되면 부족의 불 근처에서 그 물을 마시도록 하게나. 예언의 물을 마신 후 조금 있으면 불 앞에 미래의 예언이 나타날 것이야.\n\n바로 그때, 그것을 운명으로 따를 것인지는 그대에게 달려 있네.", progress = nil, completion = "두려워 말게, &lt;class&gt;|1이여;여;. 그대는 성공적으로 예언의 의식을 통과했네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n가죽 방수 장화햇빛 차단 망토\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야생의 징표\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[773] = {title = "지혜의 의식", objective = "썬더 블러프 동쪽에 있는 붉은 바위 언덕으로 가서 고대의 영혼과 대화해야 합니다.", description = "썬더 블러프의 장로들에게 인정을 받으려면, 다음으로 지혜의 의식을 완수해야만 하네.\n\n이제 예언의 의식을 잘 통과했으니 붉은 바위 언덕에 잠들어 계시는 선조님들의 가호를 받을 자격은 있을 것이지만, 오직 예언의 물을 마신 자만이 그 가호를 받을 수 있다네.\n\n썬더 블러프 동쪽에 있는 붉은 바위 언덕으로 가서 고대의 영혼을 찾도록 하게.", progress = nil, completion = "지금까지 그대는 대지모신의 의식을 통과하기 위해 부단히 노력하는 모습을 보여 주었도다.\n\n우리 고대의 영혼들은 위대한 도시 썬더 블러프를 건설하고 수호하기 위해 용감하게 자신의 생명을 바친 &lt;race&gt;을 상징하는 존재이니라. 이제 우리의 자손인 그대에게 그 수호 임무를 넘겨 주도록 하겠노라.\n\n젊은 &lt;class&gt;|1이여;여;, 이제 지혜의 의식을 통과하였으니 자랑스럽게 썬더 블러프로 입성하도록 하라.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[775] = {title = "썬더 블러프로의 여정", objective = "썬더 블러프에 있는 케른 블러드후프와 대화해야 합니다.", description = "이제 우리의 위대한 도시에서 그대는 존경과 찬양을 받게 될 것이로다. 대지모신의 의식을 완수할 만한 능력이 있는 <race>|1이라면;라면; 그 영광을 얻을 자격이 있음에 틀림없도다.\n\n그대에게 마지막 임무를 부여하노니, 썬더 블러프의 가장 높은 벼랑 꼭대기에 살고 있는 고귀한 지도자 케른 블러드후프를 찾도록 하라.", progress = nil, completion = "어서 오게, 젊은 &lt;class&gt;|1이여;여;. 내가 있는 곳을 용케 찾아냈군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[776] = {title = "대지모신의 의식", objective = "썬더 블러프에 있는 케른 블러드후프가 알라치아의 뿔을 가져다 달라고 부탁했습니다.", description = "그대는 대지모신의 의식을 충실히 수행하여 썬더 블러프에서 당당한 지위를 얻었네.\n\n그러나 애써 얻은 지위를 유지하기 위해선 주민들에게 그대의 능력을 계속 증명해 보여야만 하지.\n\n그대도 알다시피 우리는 사냥꾼들이네. 그러니 우리의 사냥 능력을 계속 보여줘야 하네. 멀고어 아래에는 알라치아라는 거대한 코도가 살고 있지. 그대의 능력을 증명해 보이려면 알라치아를 추적해 처치한 다음 알라치아의 뿔을 내게 가지고 오게.", progress = "알라치아는 찾았는가?", completion = "잘해냈네! 훌륭한 사냥이었어.\n\n일꾼들을 보내 시체에서 가죽과 고기를 가져오도록 하지. 그대의 공이 크네.", rewards = "다음과 같은 것들을 받습니다:\n\n코도 사냥꾼 다리보호구"},
[777] = {title = "불길한 예감", objective = "로트윌 베리아투스에게 5번 기어를 가져가야 합니다.", description = "자, 여기 있습니다.\n\n전 이 덮개 뒤에 몸을 숨길 거예요.\n\n이리 와서 여기 숨으세요.", progress = "<족쇄를 보지 못하게 하기 위해서 손을 뻗어 저으며 조급한 목소리로...>\n\n기어, 기어가 필요해!", completion = "좋아, 완벽하군. 조금 뒤로 물러나요, 새로운 역사를 만들 준비를 해야지!\n\n&lt;광기가 가득한 상태로 일을 계속하는 로트윌&gt;", rewards = nil},
[778] = {title = "불길한 예감", objective = "팜레터 수호정령을 물리치고 로트윌 베리아투스에게 로트윌의 정령 봉인 족쇄를 되찾아 가야 합니다.", description = "하하! 드디어 다 됐군! 족쇄가 완성되었단 말이야!\n\n루시앙! 세르보! 준비해!\n\n연금술, 공학, 그리고 불가사의의 완벽한 결정체를 직접 볼 준비가 됐나요?\n\n이제 강력한 정령을 불러낼 거예요. 오늘은 우리 모두 새로운 걸음을 내딛는 뜻 깊은 날이 될 거라고요.", progress = "이... 이건 예상했던 결과와는 좀 다른데... 내 족쇄는 되찾아 왔나요?", completion = "고마워요. 큰일 날 뻔했군요.\n\n뭐가 잘못된 건지는 확실히 모르겠지만, 그래도 내 마법으로 괴물들을 자신들이 왔던 차원으로 되돌려 보낼 수 있었으니 천만 다행 아닌가요?\n\n이걸로 당신의 도움에 대한 작은 감사의 표시가 되었으면 좋겠군요...", rewards = "다음과 같은 것들을 받습니다:\n\n신기한 초시계"},
[779] = {title = "대지의 봉인", objective = "여기 자수정 마법석, 오팔 마법석, 다이아몬드 마법석을 놓기 위해 세 군데가 움푹 파여 있는 대지의 봉인이 있습니다.", description = nil, progress = "여기 자수정 마법석, 오팔 마법석, 다이아몬드 마법석을 놓기 위해 세 군데가 움푹 파여 있는 대지의 봉인이 있습니다.", completion = "해당하는 자리에 각각의 마법석을 놓자 격렬한 소음이 대지를 흔들어 봉인이 파괴됩니다.", rewards = nil},
[780] = {title = "전투멧돼지", objective = "나라체 야영지에 있는 그룰 호크윈드가 전투멧돼지를 처치하고 전투멧돼지 주둥이 8개와 전투멧돼지 갈비살 8점을 가져다 달라고 부탁했습니다.", description = "동쪽에 있는 칼날가시 협곡의 전투멧돼지들이 우리 부족의 사냥터를 침범하고 있소. 그 전투맷돼지들은 우리와 전쟁 중인 뾰족털 가시멧돼지 놈들이 조련시킨 것이오.\n\n이 괘씸한 짐승들을 처치하고 우리 아이들을 위해 스튜를 만들 수 있도록 주둥이와 갈비살을 몇 점 가져다주시오.", progress = "전투멧돼지들의 침략이 심해지고 있소. 놈들을 처치하고 주둥이와 갈비살을 가져왔소?", completion = "정말 훌륭하군. 당신이 준 재료들로 맛있는 스튜를 만들 수 있을 것이오. 또한 전투멧돼지들의 손실이 사악한 뾰족털일족 놈들에겐 좋은 교훈이 되었을 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n유목민의 조끼질긴 빵"},
[781] = {title = "나라체 야영지에 대한 공격", objective = "나라체 야영지에 있는 족장 호크윈드에게 뾰족털일족의 작전도를 가져가야 합니다.", description = "지도를 꼼꼼히 살펴보니 뾰족털 대족장이 나라체 야영지에 대한 대대적인 포위 공격을 계획하고 있다는 사실을 알아냅니다.\n\n이는 분명히 족장 호크윈드에게 유용한 정보가 될 것입니다!", progress = "무슨 걱정거리라도 있는 얼굴이군. 안 좋은 소식이라도 있는 것이오?", completion = "이거 정말 위급한 소식이군! 하지만 그대가 알려준 정보 덕분에 우리 이웃인 블러드후프 마을에 도움을 요청할 수 있을 것 같네. 그대가 많은 &lt;race&gt;들의 목숨을 구했네.", rewards = "다음과 같은 것들을 받습니다:\n\n두꺼운 나무껍질 버클러"},
[782] = {title = "깨어진 동맹", objective = "우두머리 토그룬을 처치하고 카르가스에 있는 고른에게 대지의 봉인을 가져가야 합니다.", description = "2차 대전쟁 때 용 데스윙과 동맹을 맺었던 호드에게서 데스윙의 부관인 블랙래쉬와 헤마투스가 저 먼 동쪽 레슬로 협곡에 갇혀 있었다는 사실을 우리는 익히 알고 있소. 우리는 반드시 타락한 옛 동지를 처단하여 호드라는 이름의 명예를 회복하여야 하오!\n\n우리는 토그룬과 그의 오우거 용병 부대를 고용해 비룡의 감옥을 여는 열쇠인 대지의 봉인을 찾고 있었소.\n\n그런데 토그룬이 우리를 배신하고 봉인을 가져가 버렸으니 보프 야영지로가서 봉인을 되찾아 오시오!", progress = "토그룬의 배신으로 이제 오우거들이 호드의 일원이 아님이 분명한 사실이 되었소. 놈을 처치하고 대지의 봉인을 손에 넣는다면 무척 기쁠 것이오.\n\n아직 토그룬을 처치하지 못했다면, 시간 낭비하지 말고 보프 야영지로 가시오. 보프 야영지는 카라노스의 남동쪽에 있소.", completion = "토그룬의 시체는 사막의 바람과 사막의 청소부인 대머리수리가 깨끗이 청소할 것이오. 이제 놈이 죽었으니 오우거들은 혼란에 빠지겠지. 이 작은 승리로 앞으로 더 큰 승리를 얻게 될 것이오.\n\n대지의 봉인을 되찾았으니 레슬로 협곡에 있는 검은 비룡의 감옥을 열 수 있소. 이제 우리는 그들을 끝없는 감옥에서 해방시켜 영원한 안식을 줄 수 있게 되었소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[783] = {title = "내부의 위협", objective = "치안대장 맥브라이드와 대화해야 합니다.", description = "젊은 <class>|1이여;여;. 노스샤이어에 오신 것을 환영합니다. 이곳에서 해야 할 임무가 있으니 각오를 단단히 하셔야 할 겁니다.\n\n스톰윈드 경비대는 노스샤이어의 평화를 지키기 위해 밤낮으로 노력하고 있습니다. 하지만 지금은 병사들이 변방으로 파견된 상황이고 수많은 크고 작은 위협들이 다가오고 있어 평화를 유지하기가 쉬운 일이 아닙니다. 그래서 현재는 고향과 자신의 동맹국을 지키려는 뜻이 있는 자라면 누구든지 지원자로 받아들이고 있습니다.\n\n이러한 부름에 응하고자 이곳에 오셨다면 제 상관이신 치안대장 맥브라이드님을 만나 보시기 바랍니다. 그분은 뒤로 보이는 수도원 안에 계십니다.", progress = nil, completion = "오, 좋아. 지원자가 또 한 명 늘었군. 요즘 들어 지원자가 늘어나고 있네. 이 병력으로 충분해야 할 텐데...\n\n대부분의 병사들이 타지역으로 소집되어 가는 바람에 노스샤이어는 치안이 거의 무방비 상태라고 할 수 있네. 그 결과, 타락한 무법자들이 우리 영토 안에서 활개를 치고 있네.\n\n우리가 치르고 있는 전쟁에는 전후방이 따로 없으니 이제부터 기나긴 전투를 각오해야 할 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[784] = {title = "배신자 처단", objective = "쿨 티라스 선원 10명과 쿨 티라스 해병 8명, 그리고 부대장 베네딕트를 처치한 다음 칼바위 언덕에 있는 가르톡에게 돌아가십시오.", description = "프라우드무어 함장이 이끄는 쿨 티라스의 인간들이 몇 년 전 아키몬드를 물리치기 위해 듀로타를 선공했네. 제이나 프라우드무어는 대족장님과 맺은 불가침 조약도 깨고 말이지.\n\n하지만 사악한 인간들의 침략 행위는 저지당했고 타이라가드 요새도 함락됐어. 그런데 최근 살아남은 프라우드무어 함장의 병력들이 부대장 베네딕트의 지휘 아래 타이라가드 요새를 탈환하기 위해 우리 땅을 넘보고 있네. 이 자들은 외교 조약을 완전히 무시하고 있지.\n\n남쪽의 타이라가드 요새로 가서 침략자 인간 무리를 처단해주게나.", progress = nil, completion = "자네의 용감한 활약상에 대한 소문이 이미 자자하다네. 타이라가드 요새에서 거둔 승리는 오그리마에 널리 알려질 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[785] = {title = "전략적 동맹", objective = "센진 마을 서쪽 측면 지역에서 라르 프라울터스크를 찾아야 합니다.스랄님은 지혜롭고 훌륭한 지도자시지. 뛰어난 외교적 수완만큼이나 전장에서 집념도 대단하시고 말일세.\n\n이제 우리에게 있어 검은창 트롤은 연합군으로서 대단히 중요한 힘이 되주고 있지. 우리는 충성과 명예를 담아 그들과 보호 협정을 맺었네.\n\n그래서 대족장님께서는 센진 마을에 있는 검은창 연합군에게 직접적으로 가해지는 위협들을 모두 제거하라는 명령을 내리셨네. 검은창 부족의 가장 믿음직한 정찰병인 라르 프라울터스크가 서쪽 측면 지역을 엄중히 감시하고 있네.\n\n라르를 찾아 도움을 주도록.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "스랄님은 지혜롭고 훌륭한 지도자시지. 뛰어난 외교적 수완만큼이나 전장에서 집념도 대단하시고 말일세.\n\n이제 우리에게 있어 검은창 트롤은 연합군으로서 대단히 중요한 힘이 되주고 있지. 우리는 충성과 명예를 담아 그들과 보호 협정을 맺었네.\n\n그래서 대족장님께서는 센진 마을에 있는 검은창 연합군에게 직접적으로 가해지는 위협들을 모두 제거하라는 명령을 내리셨네. 검은창 부족의 가장 믿음직한 정찰병인 라르 프라울터스크가 서쪽 측면 지역을 엄중히 감시하고 있네.\n\n라르를 찾아 도움을 주도록.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[786] = {title = "콜카르일족 침략 저지", objective = "센진 마을 외곽에 있는 라르 프라울터스크가 콜카르 바윗골에 있는 3개의 공격 계획서를 없애 달라고 부탁했습니다.", description = "목소리를 낮춰. 콜카르 켄타우로스들이 콜카르 바윗골 서쪽 능선을 넘어 공격해 오고 있어.\n\n어젯밤 놈들이 습격하는 동안 나는 놈들의 마을로 숨어 들어가 이 더러운 짐승들이 듀로타의 트롤과 오크에 대한 삼중 공격을 계획하고 있다는 사실을 알아냈지.\n\n반드시 놈들의 계획을 막아야 해. 당신이 병사들을 소집해 콜카르 바윗골에 잠입하여 놈들의 공격 계획서를 없애 주지 않겠나?\n\n내가 마지막으로 확인한 바로는 네 명의 우두머리가 있었고 그 중 세 명이 세 개의 공격 계획서를 각각 하나씩 가지고 있었어.", progress = nil, completion = "물론 콜카르 켄타우로스와 싸우게 되더라도 호드의 승리야 자명한 일이지만, 공격을 사전에 막아 우리 전사들의 피를 아낄 수 있게 되었군.\n\n이 어려운 시기를 헤쳐 나가는 동안 많은 피를 흘리게 될 것이라는 건 타나리스 사막에 모래가 있다는 사실만큼 당연한 것이니...\n\n어쨌든 당신은 많은 형제들의 목숨을 구한 거야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n투사의 망토골진 두꺼운 팔보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[787] = {title = "호드 신병", objective = "동굴 막사에 있는 고르넥과 대화하십시오.트롬카! 난 스랄님으로부터 신병 훈련 임무를 받은 아이트리그라 하네.\n\n지금의 호드는 예전과 많이 달라졌네. 한 때 권력에 굶주린 불타는 군단과 결탁한 앞잡이들이 세력을 불렸다네. 나는 환멸을 느껴 호드를 떠났던 적이 있네. 그 후 인간 무리에 포로로 잡혔었는데 대족장님께서 나를 구해 주셨다네. 나는 대족장님의 뜻에 공감하여 다시 돌아왔다네. 그분께서는 주술사들의 지도하에 악마의 세력에서 벗어난 자유로운 호드를 꿈꾸셨지.\n\n동굴 막사에 있는 고르넥이 자네에게 앞으로의 훈련 내용을 자세히 알려줄 걸세.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "트롬카! 난 스랄님으로부터 신병 훈련 임무를 받은 아이트리그라 하네.\n\n지금의 호드는 예전과 많이 달라졌네. 한 때 권력에 굶주린 불타는 군단과 결탁한 앞잡이들이 세력을 불렸다네. 나는 환멸을 느껴 호드를 떠났던 적이 있네. 그 후 인간 무리에 포로로 잡혔었는데 대족장님께서 나를 구해 주셨다네. 나는 대족장님의 뜻에 공감하여 다시 돌아왔다네. 그분께서는 주술사들의 지도하에 악마의 세력에서 벗어난 자유로운 호드를 꿈꾸셨지.\n\n동굴 막사에 있는 고르넥이 자네에게 앞으로의 훈련 내용을 자세히 알려줄 걸세.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[788] = {title = "몸 풀기", objective = "점박이멧돼지 10마리를 처치한 다음 동굴 막사에 있는 고르넥에게 돌아가십시오.", description = "우선 당신의 굳어진 몸을 풀어줄 만한 일부터 시작하도록 하지. 사실 곧바로 불모의 땅으로 보내 코도를 잡아오라고 하고 싶지만 그러다 당신이 죽어버리기라도 하면 곤란한 일이지. 아무래도 살아 있는 것이 죽는 것보단 우리한테 도움이 될 테니 말이오.\n\n우선은 점박이멧돼지가 당신에게 적합한 상대일 거요. 멧돼지들은 북쪽으로 가면 많이 있소.", progress = "설마 벌써 임무를 완수했다고 말하려고 돌아온 거요? 그런 거라면 당신 다시 봐야겠는걸.", completion = "흠, 나쁘진 않군. 하지만 자만은 금물이오. 앞으론 멧돼지보단 거친 상대를 만나야 할 테니.\n\n어쨌든 이번 훈련은 잘해냈소. 다음 훈련은 조금은 더 위험할 테니 아마 방어구가 더 필요할 거요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n부드러운 양모 장화마모된 가죽 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[789] = {title = "전갈의 독침", objective = "동굴 막사에 있는 고르넥을 위해 일꾼전갈 꼬리 10개를 모아야 합니다.", description = "고참 전사나 서툰 풋내기나 할 것 없이 모두 무릎을 꿇게 만드는 것이 바로 전갈의 독침이지. 당신의 용기를 증명해 보이고 싶다면 북서쪽에 있는 전갈들을 처치하고 그 증거로 일꾼전갈 꼬리 10개를 가져오시오.\n\n그 꼬리에서 독액을 추출하면 전갈 독침의 해독약을 만들 수 있소. 부상병을 치료하려면 많은 양의 해독약을 미리 준비해 놓고 있어야 하지. 하지만 당신과 같이 강한 자라면 해독약 같은 건 필요 없을 거라 믿지만...", progress = "전갈 껍질이 아무리 두껍다 해도 용맹함을 갖춘 전사에겐 큰 문제가 되지 않는다오. 이길 수 있다는 마음가짐으로 강하게 내리치다 보면 전갈도 어려운 상대가 아니란 걸 곧 알게 될 거요.", completion = "전갈과의 전투에서 반드시 기억해 두어야 할 중요한 교훈이 있소. 당신의 몸집이 크든 작든 일침에 쓰러질 수 있다는 사실이지. 그리고 전투에서 적이 많고 적음에 상관없이 언제나 당신이 패할 가능성은 있다는 사실을 명심하시오.\n\n이제 더 이상 가르칠 게 없군. 지금까지 잘해 왔으니 앞으로도 당신의 활약을 관심 있게 지켜보도록 하겠소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n부드러운 양모 허리띠마모된 단망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[790] = {title = "사르코스", objective = "사르코스를 처치하고 그의 발톱을 하나주아에게 가져가야 합니다.", description = "오, <class> 친구를 만나다니! 여기서 나 혼자 아무도 모르게 죽게 되는 줄만 알았는데... 아까 골짜기에서 전갈을 사냥하던 중에 유난히 사악해 보이는 녀석을 하나 발견했었지. 그래서 놈에게 뛰어들어 녀석의 발톱을 힘껏 내리쳤지만 곧 내 다리 가까이로 기어오더군.\n\n그놈의 독침에 대해서는 무방비 상태였던 터라, 녀석이 순식간에 다가와 내 가슴을 찌르는 바람에 피를 많이 흘리고 말았소. 제발 날 위해 그 전갈 녀석을 처치해 주시오! 그래서 반드시 내 잃어버린 명예를 되찾아 주었으면 하오. 여기에서 남쪽에 있는 언덕에서 녀석과 싸웠었소.", progress = "아버지는 항상 내가 위대한 영웅은 절대로 되지 못할 거라고 말씀하셨는데, 이렇게 나무 밑에서 죽음을 기다리고 있자니 그 말씀이 옳았다는 생각이 드는구려.\n\n하지만 죽기 전에 적어도 내 원수가 없어졌다는 걸 확인하고 싶소.", completion = "내 직접 그 녀석을 처치하지는 못했지만 어느 정도 타격은 준 듯하니 그거라도 자랑스럽게 생각할 수 있게 되었소. 이 작은 승리가 이렇게 죽어가는 마당에 유일한 위안거리라니... 내 생에 이뤄 놓은 업적이 이다지도 보잘것없다는 사실이 정말 화가 나는구려.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[791] = {title = "보급품 조달", objective = "칼바위 언덕 감시탑에 있는 펄 스콘브로우가 캔버스 천조각 8개를 가져다 달라고 부탁했습니다.", description = "세월은 내 전투 능력을 앗아가고 기력도 쇠해 이제 나는 다른 일을 맡고 있다네.\n\n바로 이 고지에서 침략자가 없는지 감시하는 일이지. 이곳에서 우리의 세력이 커짐에 따라 내가 전쟁 나팔을 부는 횟수도 나날이 줄고 있네.\n\n그래서 우리 땅을 지키는 젊은이들을 돕기 위한 장비를 만들며 무료함을 달래고 있지.\n\n내 자네를 위해 소지품을 보관할 수 있는 가방을 만들어 주도록 하지. 그러려면 약간의 천 조각이 필요하니 좀 가지고 오게. 천 조각은 인간과 켄타우로스들이 즐겨 사용하니, 그들에게 구할 수 있을 거야.", progress = "이 땅을 개척할 시절, 난 대족장님과 함께 용감히 싸웠지. 내 몸에 난 이 상처들도 다 그 전투의 흔적들이지.\n\n아키몬드가 전쟁에 패한 분노의 눈물과 이 도끼로 호드의 명예를 지켜 왔지. 인간과 엘프들의 사사로운 욕망을 위해 결성된 그 더러운 얼라이언스에 패했던 시절 흘린 눈물로...\n\n지금은 경비와 물품 조달을 맡으면서 새로운 보람을 찾고 있지.", completion = "정말 훌륭하군. 이 가방은 전장에서 위용을 떨칠 뛰어난 &lt;class&gt;의 것일세.\n\n호드를 위해서라면 목숨이라도 내 던지는 그 의지와 용기에 경의를 표하네!", rewards = "다음과 같은 것들을 받습니다:\n\n수제 가죽 가방"},
[792] = {title = "악마의 하수인", objective = "악마의 하수인 12마리를 처치해야 합니다.\n\n임무를 완수한 뒤 동굴 막사 바깥에 있는 주리타 파게이즈에게 돌아가십시오.", description = "여기 시험의 골짜기에서 많은 걸 배울 수 있을 거라 믿어요. 난 당신을 지도하기 위해 이곳으로 파견되었습니다.\n\n얼마 전 이곳에서 점점 커가고 있는 악의 세력을 발견했어요. 자칭 불타는칼날단이라는 일족이 시험의 골짜기에 소굴을 마련했더군요. 놈들은 북동쪽 동굴 안에 숨어서 악마의 하수인을 내보내 대혼란을 야기하려 하고 있어요.\n\n첫 임무로 놈들의 하수인을 처치하도록 하세요. 언젠가는 불타는칼날단을 완전히 소탕하러 가야겠지만... 지금은 될 수 있는 한 많이 처치하고 돌아오세요. 살아남을 수 있다면 말이죠.", progress = nil, completion = "수고했어요. 악마의 하수인은 불타는칼날단의 졸개에 불과하지만... 이번 임무를 성공적으로 완수한 걸 보면 앞으로 더 큰 일도 해낼 분인 것 같군요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n구식 곤봉구식 손칼구식 손도끼구식 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[793] = {title = "깨어진 동맹", objective = "대지의 봉인을 사용하여 다이아몬드, 오팔, 자수정의 기둥을 작동시켜 마법석을 모아야 합니다.\n\n마법석을 대지의 봉인에 놓아 블랙래쉬와 헤마투스의 봉인을 풀어줘야 합니다.\n\n블랙래쉬와 헤마투스를 처치하고 고른에게 블랙래쉬의 굴레, 헤마투스의 굴레와 대지의 봉인을 가져가야 합니다.", description = "대지의 봉인은 레슬로 협곡에 있는 다이아몬드 기둥, 오팔 기둥, 자수정 기둥에 보관된 세 개의 마법석에 의해 유지되고 있소. 대지의 봉인을 해제하려면 대지의 봉인을 사용하여 기둥 안에서 작동되고 있는 마법석을 제거해야만 하오.\n\n검은 비룡 블랙래쉬와 헤마투스는 만만한 상대가 아니니 조심하시오. 놈들을 처치하고 놈들이 차고 있는 굴레를 내게 가져다주시오.\n\n레슬로 협곡으로 가려면 황야의 땅의 동쪽 먼 곳으로 여행해야 하오. 협곡은 헤아릴 수 없이 많은 비룡의 서식지이니 조심하도록 하시오.", progress = "용족만큼 위험한 상대는 없으며 그 중에서도 블랙래쉬와 헤마투스만큼 사나운 놈들은 없었소.", completion = "검은용군단이 우리를 배신한 검은바위부족 오크들과 동맹을 유지하고 있소. 양쪽 모두 교화되거나 제거되어야 할 대상이지. 이제 블랙래쉬와 헤마투스를 처치했으니 우리의 힘을 서쪽의 검은바위 첨탑에 집중할 수 있게 되었소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n맹렬한 바람의 흉갑프리즘 미늘 갑옷전투철로 흉갑정신 확장의 메달\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[794] = {title = "불타는칼날단 메달", objective = "동굴 막사 외부에 있는 주리타 파게이즈에게 불타는칼날단 메달을 가져가야 합니다.", description = "내가 점을 쳐본 바에 의하면 불타는칼날단 소굴 깊숙한 곳에 강한 힘을 지닌 무언가가 숨겨져 있는 게 보여요. 짐승들과 흑마법이 그것을 지키고 있지요.\n\n불타는칼날단 메달이라 불리는 것인데, 당신의 다음 임무는 소굴 안에서 그 물건을 찾아 가져오는 거예요.\n\n하지만 그 물건을 가지고 있는 놈은 이전에 당신이 상대했던 하수인들보다 훨씬 강할 테니 조심하도록 하세요.\n\n가세요. 그들의 소굴은 북서쪽으로 가면 찾을 수 있을 거예요.", progress = "임무는 완수했나요? 불타는칼날단 메달은 손에 넣었나요?", completion = "찾아왔군요! 수고했어요!\n\n불타는칼날단 소굴에서 보여 준 당신의 활약은 시험의 골짜기에서 저 이교도 집단의 뿌리를 뽑는 데 중요한 열쇠가 될 거예요. 하지만 놈들이 우리 영토에서 또 다른 뭔가를 꾀하고 있는 것은 아닌지 걱정이 되는군요.\n\n아직 완전히 놈들을 섬멸한 건 아니니까요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n먼지투성이 다리보호구톱니 사슬 조끼찢어진 바지\n\n다음과 같은 것들 또한 받습니다:\n\n최하급 치유 물약"},
[795] = {title = "대지의 봉인", objective = "여기 자수정 마법석, 오팔 마법석 및 다이아몬드 마법석을 놓을 수 있도록 세 군데가 움푹 파여 있는 대지의 봉인이 있습니다.", description = nil, progress = "여기 자수정 마법석, 오팔 마법석 및 다이아몬드 마법석을 놓을 수 있도록 세 군데가 움푹 파여 있는 대지의 봉인이 있습니다.", completion = "해당하는 자리에 각각의 마법석을 놓자 격렬한 소음이 대지를 흔들어 봉인이 파괴됩니다.", rewards = nil},
[804] = {title = "사르코스", objective = "동굴 막사에 있는 고르넥에게 하나주아의 현재 상황을 전해야 합니다.", description = "당신이 나를 위해 해준 용감한 행동에 크게 감명 받았소. 내가 이렇게 쉽게 죽을 수는 없지 않겠소! 반드시 이겨 낼 것이오!\n\n하지만 다른 이의 도움 없이는 동굴 막사로 돌아갈 수 없다는 게 문제구료. 동굴 막사로 돌아가 고르넥에게 내 상황을 좀 전해 주시오. 아마 그는 날 도와 줄 수 있을 거요.", progress = nil, completion = "흠, 당신 설명을 들어 보니, 당신이 죽인 전갈은 사르코스임이 분명하오! 그렇다면 하나주아가 당할 만도 하지. 즉시 구조대를 보낼 테니 당신은 더 이상 그에게 신경 쓰지 않아도 되오.\n\n어쨌든 사르코스를 처치했다니 정말 놀랍소. 당신은 아주 자랑스러운 일을 해낸 거요. 그리고 바쁜 와중에 기꺼이 낯선 이의 명예를 위해 싸웠다는 건 당신의 명성을 한층 드높인 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n부드러운 양모 조끼마모된 사슬 다리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[805] = {title = "센진 마을에 보고", objective = "센진 마을에 있는 가드린 장로와 대화하십시오.", description = "이곳 시험의 골짜기에서 불타는칼날단을 상대로 한 시험은 이것으로 끝났어요. 하지만 당신이 발견한 사실들을 보고해 줬으면 좋겠는데...\n\n트롤들의 마을인 센진 마을로 가서 장로 가드린을 찾도록 하세요. 센진 마을은 시험의 골짜기 밖으로 나가 동쪽으로 가다 보면 나오는 갈림길에서 오른쪽에 있습니다.\n\n가드린에게 불타는칼날단이 시험의 골짜기까지 넘보고 있다고 전하세요. 녀석들이 벌써 센진 마을에까지 이른 것은 아닌지 그에게 알아보세요.\n\n가세요, <name>. 서둘러야 합니다. 불타는칼날단의 소굴의 악이 더 큰 위협을 예고하는 건 아닌지 걱정이군요.", progress = nil, completion = "흠... 지금은 이런 보고를 받기는 좋지 않은 때인데... 이곳 센진 마을에서는 아직 불타는칼날단을 보지 못했네. 하지만 녀석들의 사악함이 해안밖에 퍼지기 시작했네. 메아리 섬 말이야.\n\n오크족은 검은창 &lt;race&gt; 부족의 친구지. 훌륭한 친구이고 말고. 우리도 오크들을 돕고 싶네만... 우리가 도움을 청해야 할 판국이라네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[806] = {title = "다크스톰", objective = "칼바위 언덕에 있는 오르그닐 소울스카에게 피즐의 발톱을 가져가야 합니다.", description = "불타는칼날단이 듀로타에까지 발을 들여 놓게 할 수는 없네. 악의 세력이 퍼지기 전에 밟아 줘야 돼!\n\n내 알아본 바에 의하면 피즐 다크스톰이라는 고블린 흑마법사가 북서쪽 천둥 골짜기에 야영지를 설치했네. 거기에서 피즐 다크스톰은 그 숭배자들과 함께 혼란과 재앙을 불러 일으키고 있어.\n\n피즐 다크스톰을 찾아 처치하고 놈의 발톱을 가져오게.", progress = "피즐이란 녀석은 찾았나? 그 녀석과 불타는칼날단의 잔당들을 죄다 우리 땅에서 쫓아내야 해!", completion = "오! 놈을 처치하다니!\n\n자네가 자랑스럽네. 덕분에 듀로타에서 악마의 앞잡이를 또 하나 제거했군.", rewards = "다음과 같은 것들을 받습니다:\n\n호랑이 가죽 장화"},
[808] = {title = "민시나의 해골", objective = "메아리 섬에 있는 힘의 마법진에서 민시나의 해골을 찾아와야 합니다.\n\n센진 마을에 있는 장로 가드린에게 민시나의 해골을 가져가야 합니다.", description = "꿈에서 나를 부르는 우리 형 민시나의 목소리를 들었네.\n\n형은 동쪽에 있는 메아리 섬의 흑마법사, 잘라제인에게 잡혀가서 죽고 말았지.\n\n하지만 형은 죽어서도 자유로울 수 없었어. 잘라제인은 형의 영혼에 마법을 걸어 민시나의 해골에 가두어 놓았네. 꿈속에서 난 민시나의 해골을 보았네. 메아리 섬 일대에서 가장 큰 섬에 있는 힘의 마법진에 다른 해골들과 함께 있었어. 해골이 거기에 있는 한, 형의 가혹한 운명은 끝나지 않을 거야.\n\n제발 그 마법진을 찾아 민시나의 해골을 내게 가져다주게.\n\n부디 형을 자유롭게 해 줘!", progress = "형의 해골은 가져왔나? 이제 형은 자유롭게 된 건가?", completion = "고맙네. 자네가 우리 형 민시나를 구한 거야. 형의 영혼을 해방시킨 거야!", rewards = "다음과 같은 것들을 받습니다:\n\n희미하게 빛나는 해골"},
[809] = {title = "아크젤로스", objective = "불모의 땅에 있는 아크젤로스와 대화하십시오.", description = "불타는 군단이 패한 최후의 대전쟁 이후, 나는 오크 사회 내에서 마력이 불러온 타락과 부정을 연구해 왔네. 자네가 가져온 이글거리는 목걸이를 통해 그동안 걱정해왔던 것이 사실이었음을 확인했지.\n\n이 목걸이는 악마의 씨앗이라고 하는 마력의 물건을 중심으로 결성된 불타는칼날단 이교도 집단의 것이야. 그 씨앗은 반드시 파괴되어야만 하네! 불모의 땅, 공포의 안개봉우리 꼭대기에 있지.\n\n여기서 서쪽으로 가면 불모의 땅 경계 부근에 전초 기지가 보일 거야. 그곳에서 내 조수인 아크젤로스를 만나 보게. 앞으로 당신이 할 일을 알려줄 게야.", progress = nil, completion = "네루님께서 악마의 씨앗을 파괴하라고 하셨단 말인가? 이상하군...\n\n아무튼 좋소이다. 네루님께서 원하신다면 방법을 알려 드리리다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[812] = {title = "해독약 구하기", objective = "오그리마에서 코간을 찾아서 해독약을 받은 다음, 불모의 땅과 인접한 듀로타 변두리에 있는 리나그에게 맹독전갈 해독약을 가져가야 합니다.", description = "마침 잘 왔군. 자네에게 급한 부탁이 있네.\n\n난 이 근처에서 맹독전갈 몇 마리와 싸우고 있었는데, 부주의로 그만 한 놈에게 깊이 찔리고 말았어. 당신에게 얘기하고 있는 지금도 몸 속에 독이 퍼져 나가는 게 느껴져. 이런 속도라면 아마 한 시간도 채 견디지 못할 것 같아. 그래서 도움이 필요해.\n\n오그리마에 있는 코간에게 가면 해독약을 만들어 줄 거야.\n\n제발 코간을 빨리 찾으라고. 서둘러 줘. 난 오래 버틸 수 없을 것 같아. 코간은 어둠의 틈이라는 곳에서 찾을 수 있을 거야.", progress = "이런 모습으로 센진에 돌아가느니 차라리 못 가게 된 것이 잘 된 일인지도 모르겠군. 모두 나의 어리석음과 나약함을 조롱할 테니...", completion = "당신은 내 생명을 구했어. 고맙소.\n\n이걸 받아줘. 돈이 되는 물건은 아니더라도 조금이라도 도움이 됐으면 해. 사양하지 말아줘, 나는 당분간은 사용할 일이 없을 것 같으니. 코간은 내가 실력을 입증할 때까지 나를 더 밀어붙일 거야. 멧돼지도 더 잡아야 하고 전갈들의 꼬리도 더 모아야 하겠지. 휴우...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n돌격용 버클러가벼운 전갈 갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[813] = {title = "해독약 구하기", objective = "오그리마에 있는 코간에게 맹독전갈 독주머니 4개를 가져가야 합니다.", description = "맹독전갈은 듀로타에 서식하는 가장 위험한 전갈 중 하나지. 해독약 없이 놈들을 사냥하러 나간 것 자체가 리나그의 잘못이지만, 지금 그를 탓해 봤자 아무 소용없는 일이고...\n\n오그리마 입구 근처에서 맹독전갈 독주머니 몇 개를 구해오면 내가 해독약을 만들어 주도록 하지.\n\n서둘러 움직이라고. 호드의 일원이 도움을 필요로 하고 있으니.", progress = "어떤 짐승이든, 사냥하기 전에 그들의 행동 양식에 대해 알아 두는 것이 좋다는 걸 명심하라고. 그 지식이 생명을 구할 수도 있단 말이지.", completion = "자, 여기 해독약. 그걸 빨리 리나그에게 가져다 줘. 당신도 조심하고.", rewards = "다음과 같은 것들을 받습니다:\n\n맹독전갈 해독약"},
[815] = {title = "알 요리", objective = "칼바위 언덕에 있는 요리사 토르카에게 붉은발톱랩터 알 3개를 가져가야 합니다.", description = "이런! 아침 식사 준비를 깜빡 잊을 뻔했군.\n\n어서 가서 붉은발톱랩터 알을 몇 개 구해 오게. 내일 식사 준비를 하려면 적어도 3개는 필요하단 말이야.\n\n붉은발톱랩터는 안 그래도 사납지만, 특히 알을 보호하기 위해서라면 죽음을 불사하기도 하지. 그리고 알을 땅속 깊이 숨겨 두기도 한다네. 하지만 센진 마을에서 남동쪽에 있는 메아리 섬으로 가면 곳곳에서 놈들을 쉽게 찾을 수 있을 거야.", progress = "아침이든 점심이든 저녁이든 그게 어떤 음식인지 누가 신경이나 쓰나? 하지만 누군가는 요리를 해야만 한다고! 그게 바로 나지!", completion = "당신은 약한지는 모르겠지만 손재주가 없지는 않군그래.\n\n자, 이걸 가지고 얼른 내 앞에서 사라지라고. 요리할 게 산더미 같이 밀렸으니까.", rewards = "다음과 같은 것들을 받습니다:\n\n질긴 빵질긴 쇠고기"},
[816] = {title = "크론의 흔적", objective = "칼바위 언덕의 북서쪽 농장에 있는 미샤 토크렌에게 크론의 흔적을 가져가야 합니다.", description = "제발, 제발 저를 도와 주세요. 내 아들 크론이 며칠 전 사냥을 나가서 아직 돌아오지 않고 있어요. 크론은 불모의 땅 서쪽의 분노의 강으로 악어 사냥을 떠났어요. 제발 아무 일도 없어야 할 텐데...\n\n강한 아이지만 겁도 없고 고집도 세서 늘 문제랍니다.\n\n악어는 힘도 세고 포악하다고 그렇게도 주의를 줬건만... 원래 거친 아이라서 제 말은 잘 듣지 않는다니까요.\n\n그 아이의 흔적이라도 찾아다 주세요. 분노의 강 강둑에 있는 악어를 다 죽여서라도...", progress = "크론이 무사히 돌아오기만을 기도하고 있지만, 그 아이에게 나쁜 일이 생긴 것 같은 느낌을 지울 수가 없군요.", completion = "오, 내 아들이... 사랑스런 내 아가...\n\n난 그 아이가 떠난 후 생사도 확인하지 못하고 지금껏 괴롭게 살아 왔어요. 이제 아이의 장례를 준비할 수 있겠어요.\n\n감사합니다. 그리고 이걸 받아 주세요. 크론이 살아 돌아오면 선물하려 했던 거였어요. 이제 그걸 받을 내 자식이 떠났으니, 이걸 보고 있으면 가슴이 아파 견딜 수가 없을 거 같네요.", rewards = "다음과 같은 것들을 받습니다:\n\n수제 망토"},
[817] = {title = "유용한 사냥감", objective = "센진 마을에 있는 벨린 팡에게 듀로타 호랑이 가죽 4필을 가져가야 합니다.", description = "우리가 사용하는 가죽의 상당 수는 듀로타 호랑이에게서 얻고 있소. 모포, 갑옷, 천막... 정말 쓰임새가 다양하지. 그게 바로 우리가 이 짐승을 사냥함과 동시에 보호하는 이유라오.\n\n말하자면, 지금이 놈들의 머릿수를 좀 추려내야 할 시기라는 거요. 주민의 수가 늘면서 비축해둔 가죽의 양보다 수요가 많아지기 시작했기 때문이지. 좀 더 사냥해 질 좋은 가죽을 준비해 놓는 수밖에 없소.\n\n당신이 듀로타 호랑이 가죽 4필을 가져다주면 보상을 해 주도록 하지. 호랑이는 남쪽에 있는 섬에서 찾을 수 있소.", progress = "처음 호랑이 사냥을 나갔던 때가 아직도 생생하군. 메아리 섬의 제일 큰 섬에서 사냥감을 골랐지. 그리고 거의 하루를 꼬박 풀숲에 숨어 있었어. 완전히 몸을 숨긴 채 앉아 주위를 살피면서 기다리고 또 기다리고...\n\n모든 근육의 긴장을 늦추지 않고 사냥감을 덮칠 순간만을 기다리고 있었지. 드디어 호랑이가 미끼를 물었고... 내 인생에서 가장 위대한 승리의 순간을 맛보았지.", completion = "정말 기쁘군. 당신 도움으로 이제 우리 주민들은 보호받을 수 있을 것이고 계절이 바뀌어도 추위에 떨지 않을 것이오.\n\n고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[818] = {title = "나약한 정신", objective = "센진 마을에 있는 장로 보르날에게 온전한 마크루라의 눈 4개와 붉은톱니게 점액 8병을 가져가야 합니다.", description = "눈이 많이 나빠지긴 했지만 완전히 안 보이는 건 아니야. 그래도 예전과 달리 먼 곳을 보려면 연금술을 이용해 마법의 힘을 자주 빌려야 하지. 그래도 수습생은 받아들이지 않았네. 수습생이 되기를 자청한 이들 중에 그만한 자격이 되는 트롤이나 오크는 없었거든.\n\n물론 자네도 나라면 충분한 자격이 있다고 생각하겠지.\n\n그래서 말인데 내가 몇 가지 필요한 게 있다네. 자네가 좀 구해다 줄 텐가?\n\n온전한 마크루라의 눈과 붉은톱니게 점액이 필요하다네. 마크루라나 붉은톱니게는 바닷가에서 찾을 수 있을 거야. 그럼 또 보게 되길...", progress = "진정한 힘과 의지는 시간이 증명해 주는 법이지. 인내심을 잃거나 의지가 약해 굴복한다면 자네의 참모습이 드러날 게야.", completion = "잘했네. 참으로 잘했어.", rewards = "다음과 같은 것들을 받습니다:\n\n끈끈한 아교"},
[819] = {title = "첸의 빈 술통", objective = "첸의 빈 술통에 대해 아는 이를 찾아야 합니다.", description = "맥주통의 한쪽 귀퉁이에 붙여진 꼬리표에는 다음과 같은 문구가 적혀 있습니다.\n\n\"첸 스톰스타우트-\n\n원기를 북돋아 언제나 활기차게!\"", progress = "무슨 일이오?", completion = "음, 내가 좀 알긴 아는데...\n\n이것은 첸 스톰스타우트가 제조한 맥주 중 하나요. 그는 오래전 렉사르와 여행을 떠나서 한동안 그를 봤다는 소식도 듣지 못했지. 이 반가운 맥주통을 다시 보게 될 줄이야... 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[821] = {title = "첸의 빈 술통", objective = "톱니항에 있는 양조업자 드론에게 사바나 사자 어금니 5개, 초원타조 신장 5개와 천둥도마뱀의 뿔 1개를 가져가야 합니다.", description = "첸의 이름을 딴 이 걸작품을 한번 맛보겠소? 스톰스타우트 맥주는 독한 술이오. 내 스승께서 첸의 양조 방법을 배워 내게 전수하셨지. 이 술을 만들려면 당신이 몇 가지를 준비해야 하는데, 그 정도 수고쯤은 할 만한 가치가 충분히 있는 술이오.\n\n사바나 사자 어금니 5개, 초원타조 신장 5개, 그리고 천둥도마뱀의 뿔 1개를 구해다 주시오. 불모의 땅 전역에 거주하는 동물들에게서 이 재료들을 찾을 수 있을 거요.", progress = "재료 구하는 일은 어떻게 돼 가고 있소?", completion = "하하... 다시 이 술을 만들리라고는 꿈에도 생각해 본 적이 없었어.\n\n당신 덕분에 그리운 맥주 냄새를 맡을 수 있게 됐군. 왠지 지난번 트로그 에일 맥주를 너무 많이 마셔서 완전히 정신을 잃었을 때가 생각나는데... 고맙소. 생각만해도 얼큰하게 취하는군.", rewards = "다음과 같은 것들을 받습니다:\n\n스톰스타우트 맥주"},
[822] = {title = "첸의 빈 술통", objective = "톱니항에 있는 양조업자 드론에게 번개 분출선 5개, 천둥매 타액 분비선 1개, 코도 간 1개를 가져가야 합니다.", description = "스톰스타우트 맥주 맛 어떻소? 정말 일품이지 않소이까?\n\n첸의 또 다른 양조법도 배운 적이 있는데, 구미가 당기지 않소? 만드는 데 그리 오래 걸리지도 않고 당신의 여행 길에 아마 도움이 될 거요.\n\n폭풍도마뱀의 번개 분출선 5개, 거대한 천둥매의 천둥매 타액 분비선 1개, 그리고 저 불모의 땅 코도 간 1개를 가져다주시오.\n\n아까도 말했지만, 정말 훌륭한 술이 나올 거요. 내가 전에 얘기했던 그 트로그 에일 맥주라오.", progress = "재료는 열심히 찾고 있소, <name>?", completion = "하하! &lt;class&gt; 당신도 이 맥주 맛을 보고 싶어할 줄 알고 있었소. 더 마시고 싶을 땐 언제든 찾아 오도록 하시오. 내가 말한 재료들만 다시 모아 오면 얼마든지 만들어 줄 테니까!", rewards = "다음과 같은 것들을 받습니다:\n\n트로그 에일 맥주"},
[823] = {title = "오르그닐에게 보고", objective = "칼바위 언덕에 있는 오르그닐 소울스카와 대화하십시오.", description = "우리 센진 마을에도 나름대로 문제가 있다네. 자네의 도움에 감사하네. 하지만 자네가 가져온 불타는칼날단 소식은 모두에게 나쁜 소식이 될 거야.\n\n칼바위 언덕에 주둔하는 오르그닐 소울스카라는 오크가 있는데 불타는칼날단과 같은 악의 무리로부터 듀로타를 지키는 임무를 맡고 있네! 오르그닐에게 가서 시험의 골짜기에서 온 소식과 함께 우리가 곤경에 처했다고 얘기해주게. 아마 소식을 기다리고 있을 거야.\n\n칼바위 언덕은 북쪽에 있네.", progress = nil, completion = "그래? 보고할 것이 있다고? 그럼 어서 보고해 보게!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[824] = {title = "속세의 고리회 제네우", objective = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 더럽혀진 물구슬을 가져가야 합니다.", description = "속세의 고리회는 자연의 원소를 연구, 보존하는 데 헌신하는 주술사 단체라네. 그들은 정신 나간 고대 신이나 전설, 구전에 관해서라면 대부분의 학자가 아는 것보다 훨씬 더 많은 내용을... 잊어 버렸지.\n\n자네는 운이 좋은 편이군. 내가 이곳 잿빛 골짜기에 사는 속세의 고리회 일원을 하나 알고 있으니까 말일세. 조람 해안에 있는 조람가르 전초기지로 가서 제네우 생크리에게 자네가 찾은 걸 보여 주게. 그 구슬의 중요성을 알아낼 자는 제네우 밖에 없을 테니까.", progress = "오, 안녕하신가. 나는 물뿐만 아니라 이 세상 모든 원소를 연구하면서 많은 시간을 보내는데, 일단 시작하면 무아지경에 이를 정도라 때로는 주위에 누가 있는 것도 알아차리지 못할 때가 있지...\n\n내가 도와 줄 일이라도 있나?", completion = "이 구슬... 아주 불안정하군... 강한 정령의 대부분이 이런 물건을 통해 힘과 에너지를 받고 있다네. 그런데 자네가 찾아온 이 구슬... 손상이 거의 없는 것도 그렇지만 이렇게 심하게 타락해 있다니 큰일이로군.\n\n속세의 고리회에서 이 구슬을 연구할 수 있도록 잘 보존해두겠네. 잘하면 이런 원소의 타락에 종지부를 찍을 수 있을지도 몰라. 그리고 이건 속세의 고리회에 이 구슬을 가져온 데 대한 대가이니 받아두게나.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n숙련자 허리띠구름늪 방패버드나무 망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[825] = {title = "난파선", objective = "칼바위 언덕의 가르톡이 해안에 있는 난파선에서 노움 공구 3개를 찾아 달라고 지시했습니다.", description = "우리의 유능한 정찰병의 보고에 의하면 프라우드무어 함대의 잔해가 타이라가드 요새 바로 동쪽 듀로타 해안에 남아 있다고 하네.\n\n인간과 동맹을 맺고 있는 노움이라 알려진 작고 비열한 종족이 기계에 대한 뛰어난 지식을 보유하고 있다는 것은 너무나 유명하지. 적을 알고 나를 알면 백전백승이라 하지 않나. 적을 잘 파악해서 그들이 보유한 신기술을 역으로 활용할 수만 있다면 크게 도움이 될 거야.\n\n난파선으로 가서 얼라이언스가 사용하는 도구를 찾아오도록.", progress = "인간이 사용하는 이상한 기계 장치의 작동 방법을 알아낸다면 앞으로의 전투에서 유리한 고지를 점령할 수 있을 거야.\n\n새로운 지식을 습득하면 호드는 더욱 강해질 것이고 말이지.", completion = "임무를 성공적으로 완수했군, &lt;class&gt;. 이 도구들은 다음번 짐마차에 실어 오그리마로 보내도록 하겠네.\n\n수고했어.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n지저분한 장화사막의 손목보호구넓은 금속 벨트\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[826] = {title = "잘라제인", objective = "잘라제인을 처치해야 합니다.\n\n부두교 트롤 8명과 주술에 걸린 트롤 8명을 처치해야 합니다.\n\n가드린에게 잘라제인의 머리카락을 가져가야 합니다.", description = "의술사 잘라제인은 동쪽의 메아리 섬에 살고 있네. 그 섬들은 바로 우리의 고향이지.\n\n거기에서 그는 육지로 트롤들을 보내 우리 주민들에게 마법을 걸어 노예로 삼기 위해 납치해 가고 있네.\n\n놈을 막아야 하네.\n\n잘라제인과 이젠 그의 앞잡이가 된 검은창 부족 트롤들을 처치하게. 그리고 악의 지배가 끝났음을 확인할 수 있도록 그 증거를 가져오게.", progress = "잘라제인은 처치했나?", completion = "잘라제인도 사라졌으니 우리 부족도 이제 두 다리 쭉 뻗고 잘 수 있겠군.\n\n고맙네! 검은창 부족이 자네에게 큰 빚을 졌군. 만약 자네가 질병에라도 걸리면 저 뒤에 있는 내 조수 봄베이를 찾게나. 그의 부두 마법은 정말 강력하니...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n가벼운 장화망사 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[827] = {title = "해골 바위굴", objective = "해골 바위굴에 있는 숭배자들을 처치하고 이글거리는 목걸이를 모아야 합니다.\n\n야영지에 있는 마르고즈에게 수집한 목걸이를 가져가야 합니다.", description = "불타는칼날단은 오그리마 동쪽에 있는 해골 바위굴이라는 동굴에서 출몰하고 있소. 놈들은 그 동굴 안에서 고약한 의식을 거행하며, 이글거리는 목걸이로 자신들의 살을 태우고 있지.\n\n내 생각으론 놈들이 착용한 이글거리는 목걸이가 마력의 열쇠인 것 같소. 하지만 그 이글거리는 목걸이를 수집해서 직접 연구해 보기 전까지는 단정할 수 없겠지.\n\n해골 바위굴로 가서 숭배자들을 처치하고 이글거리는 목걸이를 모아 오시오. 그러면 놈들의 비밀을 밝혀내는데 큰 도움이 될 거요.", progress = "해골 바위굴에는 가 봤소? 이글거리는 목걸이는 어디 있소?", completion = "좋아! 이 이글거리는 목걸이에 숨겨진 비밀이 바로 불타는칼날단의 음모를 밝혀낼 열쇠가 될 거요. 내 반드시 밝혀내고야 말 거요...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n톱니 단검견고한 바스타드소드뾰족 철퇴\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[828] = {title = "마르고즈", objective = "마르고즈와 대화하십시오.", description = "우리 주술사 마르고즈가 불타는칼날단의 음모에 대한 새로운 사실을 하나 알고 있네. 그가 오그리마 외곽의 산 속에 있는 해골 바위굴에 대해 알려 주었지. 그곳에는 수많은 불타는칼날단 이교도들이 숨어 있다고 하네.\n\n해골 바위굴로 가기 전에 마르고즈를 만나 얘기해 보도록 하게. 그는 현명한 자이니까 분명 도움이 될만한 조언을 얻을 수 있을거야.\n\n지금 북쪽에 있는 모래바람 협곡과 해안가 사이에서 야영을 하고 있네.\n\n그의 조언을 따르게, 하지만 그가 뭐라고 하든 자네가 그 숭배자 놈들을 처치해야 한다는 사실은 변함이 없네!", progress = nil, completion = "어서 오시오. 당신이 날 찾아올 거란 소식은 이미 들어 알고 있었소. 그리고 듀로타에서의 활약상에 대해서도...\n\n당신의 실력과 명성은 날로 높아 가더군.\n\n정의로운 길을 이어 간다면 당신의 미래는 참으로 밝게 빛날 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[829] = {title = "네루 파이어블레이드", objective = "오그리마에 있는 네루 파이어블레이드에게 목걸이 견본을 가져가야 합니다.", description = "당신이 가져온 이글거리는 목걸이는 강력한 악마의 도구요. 안타깝게도 이글거리는 목걸이의 비밀을 알아내는 건 주술사로서 내 능력 밖이라오. 흑마법사에게 이글거리는 목걸이를 조사해 달라고 해야 할 것 같소.\n\n이 목걸이를 오그리마에 있는 네루 파이어블레이드에게 가져가시오. 그는 흑마법사로서 상당한 실력을 갖고 있는데, 자신의 힘으로 악마를 상대하겠다고 초자연적인 현상에 대한 연구 결과를 내놓기도 한다는군. 이게 사실이든 아니든 듀로타에서 벌어지는 마력의 의식에 대항하기 위해서는 반드시 그의 도움이 필요하오.\n\n네루는 오그리마에 있는 어둠의 틈에서 찾을 수 있을 거요.", progress = "어서 오게, <race>의 <class> 형제여. 내게 무슨 볼일인가?", completion = "아, 이걸 어디에서 얻었다고 했나? 칼바위 언덕의 마음씨 좋은 마르고즈가 내게 보낸 건가?\n\n흠, 그럼 어디 살펴볼까...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[830] = {title = "함장의 명령서", objective = "칼바위 언덕에 있는 가르톡에게 함장 프라우드무어의 명령서를 가져가야 합니다.", description = "낡고 빛 바랜 봉투를 열자 공문서처럼 보이는 문서가 나옵니다. 그 안에는 프라우드무어 함장의 인장이 찍혀 있습니다.\n\n중요한 문서인 것 같아 보입니다. 칼바위 언덕에 있는 사령관 가르톡에게 유용한 정보가 될 것 같습니다.", progress = "표정을 보니 뭔가 걱정거리가 있는 것 같은데... 무슨 일이지?", completion = "이거 좋은 소식은 아니로군. 이런 정보를 내게 갖고 오다니 영리한 친구로군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[831] = {title = "함장의 명령서", objective = "오그리마에 있는 스랄의 요새로 가서 함장 프라우드무어의 명령서를 나즈그렐에게 전달해야 합니다.", description = "인간들은 믿을 수 없어. 그 나약한 족속들이 언젠가 우릴 배신할 걸 알면서도 그들과 함께 싸워왔지.\n\n프라우드무어 함장은 죽어서도 속임수를 쓰는군. 그가 죽기 전 비열한 인간들이 그의 계획을 완성시켜 놨네.\n\n그가 죽은 후에도 그의 영향력은 베네딕트와 함께 살아 있는 것 같네. 그러니 프라우드무어의 병사들이 우리 해안을 당장에라도 공격해 오지 않으리라고 누가 장담할 수 있겠나?\n\n서둘러 이 명령서를 오그리마에 있는 나즈그렐님께 가져가야 하네! 그 분은 스랄의 요새에서 찾을 수 있을 걸세.", progress = "지금 내가 얼마나 바쁜지 보면 모르겠나? 급한 일이 아니라면 방해하지 말라고.", completion = "대족장님께 인간을 믿지 말라고 수없이 경고했지만, 이제 보니 개인적인 자존심 따위는 문제도 아니었군그래.\n\n젊은 &lt;class&gt;|1이여;여;, 호드를 위해 명예로운 일을 해주었네.\n\n자, 그럼 난 서둘러 이 문제에 대해 스랄님과 상의해 봐야겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[832] = {title = "이글거리는 그림자", objective = "이 눈을 네루 파이어블레이드에게 가져가야 합니다.", description = "<펜던트 모양의 눈에서 목소리가 흘러 나오며...>\n\n가즈우즈?\n\n가즈우즈... 어서 보고해!\n\n네가 해골 바위굴에서 뭔가 발견했단 소릴 들었는데. 각오해야 할 거야!\n\n가즈우즈, 어서 대답해! 아니면 네루 파이어블레이드에게 자네가 여기 있다고 일러 버리겠어. 그럼 아마 그가 자네를 무자비하게 공격할 걸.\n\n네루에게는 함부로 맞서지 않는 게 좋을 거야.\n\n가즈우즈, 듣고 있는 거야?", progress = "내게 보고할 중요한 일이 있는 모양이군. 당신 눈을 보면 알 수 있지.", completion = "&lt;이글거리는 그림자의 눈을 살펴보며...&gt;\n\n이상한 일이군. 당신이 들은 목소리가 내 이름을 언급했단 말이오? 내가 대족장님을 위해 적을 물리쳐 온 것으로 좀 이름을 떨치긴 했지만 아무래도 이상하군. 이 펜던트를 빼앗아 갔던 불타는칼날단 이교도에 나와 같은 이름을 가진 자가 있다고 해도 말이오.\n\n이 펜던트를 연구해 봐야겠군. 그리고 그 메시지가 무얼 말하는지 생각해 보아야겠소.\n\n펜던트를 가져다 줘서 고맙소이다. 당신은 호드에 큰 도움을 주었소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[833] = {title = "신성한 묘지", objective = "현자 레인토템이 붉은 바위 언덕에 있는 뾰족털일족 약탈자 8명을 처치해 달라고 부탁했습니다.", description = "가장 용감한 타우렌만이 우리의 신성한 묘지인 붉은 바위 언덕에 잠들 수 있네. 썬더 블러프를 건설하고 수호하는데 기여한 위대한 전사들과, 부족 및 지도자들의 더 큰 대의를 위해 자신의 생명을 바친 자들에게 주어지는 대단한 영광이지.\n\n하지만 우리의 신성한 땅에 악한 위험이 드리워지고 있는 것 같네. 뾰족털일족 약탈자 무리가 이 묘지를 황폐하게 하고 있어. 한창때였다면 모르겠지만, 난 이미 놈들을 몰아내기에는 너무 늙어 버렸네.\n\n반드시 놈들을 처단해야 하네.", progress = nil, completion = "수고했네. 저 고약한 뾰족털일족 놈들에게 확실한 경고가 됐을 걸세. 다시는 이 신성한 곳을 쉽게 건드리지 못할 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[834] = {title = "사막의 바람", objective = "보급품 부대 5개를 찾은 다음 오그리마 근처에 있는 레즐락에게 돌아가십시오.", description = "나는 가즈로님의 부하 레즐락이라 하오. 두목께서 오크족을 도우라고 이곳 듀로타로 날 보내셨지. 지금까지 모든 일이 순조롭게 풀리고 있었소. 짐마차를 제외하고... 그걸 안전하게 관리하는 일은 정말 어렵단 말이야! 때문에 지금 좀 어려움을 겪고 있다오.\n\n무사히 도착하리라 믿었던 지난번 짐마차가... 어디 보자, 그게 어디였더라... 아마 칼바람 협곡이었을 거요. 아무튼 그곳 먼지바람일족 하피들 손에 넘어가고 말았소.\n\n짐마차에 실려 있던 보급품을 찾지 못하면 난 아무 일도 할 수 없다오! 거대한 협곡을 따라 남쪽으로 가면 암벽을 가로지르는 계곡이 보일 거요.", progress = "난 임무 수행 능력이 탁월하오. 그러니 내 잘못이라는 말은 마시오. 단지 재수 없게 터무니 없는 일을 맡은 것 뿐이란 말이오! 대체 이런 곳에서 내가 뭘 어떻게 할 수 있겠소?", completion = "그것 보시오. 내가 어떻게 할 수 있는 일이 아니었잖소? 이제 보급품을 되찾았으니 운반해 줄 자만 찾으면 나도 하던 일을 계속할 수 있을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[835] = {title = "보급로 확보", objective = "레즐락을 위해 모래바람 협곡 근처에 있는 먼지바람일족 여전사 12명과 먼지바람일족 폭풍마녀 8명을 처치해야 합니다.", description = "가즈로님이 언젠가 이런 말씀을 하신 적이 있었소. \"레즐락, 인생을 살면서 마음에 깊이 새겨 두어야 할 사실이 한 가지 있다네. 무슨 일이든 제대로 하려면 직접 해야 한다는 거지.\"\n\n짐마차를 모두 잃는다면 그때는 정말 손을 쓸 수도 없을 지경이 될 테니, 직접 나서서 문제를 해결할 참이었소. 정말이오. 모래바람 협곡은 칼바람 협곡에서 동쪽 방향으로 가면 있다오. 그곳 하피들을 모두 처치한다면 안전하게 그쪽 길을 이용할 수 있을 거요.\n\n가즈로께서는 이런 말도 하셨소. \"대가를 치를 각오만 되어 있다면 불가능한 일은 없네.\" 어떻소, <name>, 나를 좀 도와 주겠소?", progress = nil, completion = "하피 놈들이 더 이상 우리 보급품 짐마차를 괴롭히지 못할 테니 이제야 안심이군. 한동안은 다시 나타나지 않을 테니... 그런데 다음 보급품이 올 때 무언가 좋은 걸 내게 보낼 것이라 들었소.\n\n당신의 능력은 탁월하니 톱니항에 있는 우리 두목을 한번 찾아가 보시오. 틀림없이 당신에게 임무를 맡기실 거요.\n\n참, 그리고 나를 도와 준 은혜는 절대 잊지 않고 있겠소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n하피 날개 검히코리 단궁얼룩진 나무 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[836] = {title = "OOX-09/HL 구출 작전", objective = "전망대 절벽 너머 해안까지 OOX-09/HL을 호위해 간 후 무법항에 있는 오글소프 오브노티쿠스에게 보고해야 합니다.", description = "노움의 목소리가 다시 로봇에서 흘러나옵니다.\n\n\"긴 활주로로 사용할 수 있을 만한 넓고 안전한 장소로 OOX-09/HL을 옮겨가야겠소. 은폐 기능이 탑재되어 있지만 다시 작동할 수 있도록 하려면 나도 시간이 좀 필요하오. 로봇을 현재 있는 곳에서, 보자 그러니까, 전망대 절벽 너머 해안까지 호위해주시오. 그곳이라면 이륙하기에 충분할 거요!\"\n\n\"해안까지 무사히 호위해 간 후에 무법항으로 와서 날 찾으시오! 오글소프 오브노티쿠스, 이상!\"", progress = nil, completion = "아, 당신이 OOX-09/HL을 구한 구세주였군! 얼마나 고마운지 이루 말할 수가 없소! 내 유도 로봇 시리즈는 아직 개발을 더 해야 하는데 당신이 회수해준 덕분에 제작 비용은 물론이고 시간도 벌게 됐소이다!\n\n자, 내가 가진 이 물건 중 아무거나 고르시오. 다시 한번 도와줘서 고맙소이다. 나와 내 귀염둥이 꼬꼬가 당신에게 큰 신세를 졌소!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n노움 발명가 장화노움 수중작업용 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[837] = {title = "영토 침범", objective = "칼바위 언덕의 가르톡을 위해 서슬갈기 가시멧돼지 4 마리와 서슬갈기일족 정찰병 4 마리, 서슬갈기일족 사막길잡이 4 마리, 서슬갈기일족 전투호위병 4 마리를 처치해야 합니다.", description = "우리가 이 땅에 도착했을 때 서슬갈기 가시멧돼지들이 대부분을 점령하고 있었지. 우리 입장에서 놈들은 눈엣가시 같은 존재였어. 각고의 노력 끝에 대부분 몰아냈지만, 아직 일부 지역에 살아남은 것들이 완강히 저항하고 있네.\n\n이런 상황이 너무 오래 지속되고 있는 것도 문제고, 또 전략적인 측면으로 봤을 때도 더 이상 서슬갈기일족이 우리 땅에 남아 있는 걸 용납할 수 없지. 여기에서 서쪽으로 가면 놈들의 야영지가 있네. 가시덤불이 보이는 곳에서 놈들을 찾을 수 있을 걸세. 지금은 듀로타에 있는 놈들만 상대해야 하지만 나중엔 칼림도어 전지역에서 놈들을 섬멸해야 할 걸세.", progress = nil, completion = "가시멧돼지 무리가 전멸했고 그들의 본거지도 불타서 없어졌다는 소식을 널리 알리겠네. 듀로타 근방에서 서슬갈기일족이 사라졌으니 우리의 고향 땅을 안전하게 지켜내는 데 한 발짝 다가서게 되었군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[838] = {title = "스칼로맨스", objective = "서부 역병지대의 보루에 있는 연금술사 디더스와 대화하십시오.", description = "카엘 다로우의 섬에는 스컬지의 요새 역할을 하는 학교, 스칼로맨스가 있다네. 우리의 적들은 그 요새 안에 머무르면서 자신들의 힘을 강화할 연구를 진행하고 있지. 그곳에는 문 하나가 길을 막고 있는데, 아무리 들어가려고 애를 써도 올바른 열쇠가 없으면 들어갈 수 없다네.\n\n스칼로맨스에 대해서라면 연금술사 디더스가 아주 잘 알고 있는데, 어떻게 하면 열쇠를 구할 수 있는지도 알고 있지. 자네는 주어진 임무를 아주 잘 수행하는 자라는 것을 내게 입증했으니 자네에게 이 임무를 맡기기로 함세. 연금술사 디더스와 이 일에 대해 얘기해 보게.", progress = nil, completion = "그래, &lt;class&gt;. 고위집행관님께서 열쇠 문제를 자네에게 맡기게 될지도 모르겠다고 말씀하셨었지. 최근 나는 스칼로맨스에 대한 연구에 상당한 시간을 투자해 왔네. 마침내 자유자재로 스칼로맨스의 정문을 드나들 수 있는 방법을 하나 알아낸 것 같단 말이야.\n\n이번 임무가 결코 쉽지 않을 거야. 하긴 이런 일이 쉬운 경우는 거의 없지. 그 누구보다 자네가 이 사실을 제일 잘 알고 있을 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[840] = {title = "호드의 징병", objective = "칼바위 언덕에서 서쪽 길을 따라 다리 건너의 불모의 땅으로 가야 합니다.\n\n다리 건너에 있는 오크 전초 기지에 멈추십시오.\n\n불모의 땅 전초 기지에 있는 카르갈 배틀스카에게 징병 추천서를 전달하십시오.", description = "흠, 꽤 강해 보이는 <class> 친구로군.\n\n내 둘도 없는 친구인 카르갈이 불모의 땅에서 임무를 수행할 신병을 모집 중이지. 호드를 위해 정의로운 일을 하고 싶지 않나? 지금이 좋은 기회라네.\n\n이 징병 추천서를 카르갈에게 가져가서 그의 서명을 받을 수 있을지 알아보게.", progress = "무슨 일이오, 젊은이? 신병으로 지원하러 온 게 아니라면 괜히 아까운 시간 뺏지 말고 가보라고.", completion = "그러니까, 타크린이 보냈단 말이지? 타크린... 아주 훌륭한 정찰병이지. 그가 없으면 아무것도 할 수 없을 정도라고.\n\n내 당장 징병 추천서에 서명해 주겠네. 마침 우린 크로스로드에 보낼 병력이 절실히 필요한데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[841] = {title = "추가 동력원 필요?", objective = "가젯잔에 있는 선임기술자 빌지위즐에게 사막유랑단 물주머니 10개를 가져가 다른 동력원과 맞바꿔야 합니다.", description = "내가 한번 맞혀 보지. 어디... 당신이 하려던 그 무슨 세계 종말적인 사악한 일을 시간 안에 마치지 못한 거 아닌가? 아니지, 그게 아니라, 아마... 모래 속에 떨어뜨려 버렸겠지! 뭐, 이유야 어쨌든 당신에게 팔 여분의 동력원이 있긴 한데, 이번에는 열 개. 그렇지, 사막유랑단 물주머니 10개가 필요하다고!\n\n요즘은 모두 사정이 좋지 않은데다 동력원이 나무에서 자라는 것도 아니라서 말이야. 흠, 하지만 정말로 나무에서 자란다면 어떨까? 아예 동력원 나무를 만들어 버릴까...", progress = "그래, 물주머니 10개는 갖고 왔나?", completion = "아주 좋아. 여기 다른 동력원이 있소. 또다시 동력원을 얻기 위해 물주머니 10개를 가져오는 일을 하고 싶지 않다면 이번에는 동력원을 제대로 사용하라고.", rewards = "다음과 같은 것들을 받습니다:\n\n모델 4711-FTZ 동력원"},
[842] = {title = "크로스로드의 징병", objective = "카르갈의 전초 기지로부터 서쪽 길을 따라가십시오.\n\nT자형 갈림길에서 왼쪽 길을 따라 남쪽으로 가십시오.\n\n크로스로드의 교차로에서 셀그라 다크쏜을 찾아야 합니다.", description = "내가 서명한 이 징병 추천서를 크로스로드로 가져가도록 하게.\n\n저주스러운 셀그라 다크쏜이 그곳 책임자지. 그 악랄한 주술사는 아마 자네에게 임무를 맡기기 전에 혼을 쏙 빼놓을 거야. 스랄께서는 그녀에게 뭔가 특별한 것이 있다고 믿고 있네만, 글쎄... 난 잘 모르겠어.\n\n뭐, 판단은 자네 몫이니까...", progress = "이런, 이런, 이건 또 누구신가? 카르갈이 내가 병사를 필요로 한다고 생각한 모양이군?", completion = "좋아. 호드에 참여해서 생활비라도 벌어볼 생각인가? 뭐, 여기엔 할 일이 넘쳐 나니까. 하지만 내 말을 잘 따르는 게 좋을 거야.\n\n그런데 그 눈빛이 상당히 거슬리는군. 내가 그런 오만한 태도를 용서하리라 생각하는 건 아니겠지? 스랄께서 이제 호드의 여성들도 자네 남성들과 동등한 지위를 얻게 될 거라 공언하셨어. 그런데도 내게 계속 무례를 범한다면 진정한 고통이 어떤 건지 가르쳐 주겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[843] = {title = "갠의 땅 회복", objective = "갠 스톤스파이어가 바엘던 발굴인부 15명과 바엘던 현장감독 5명을 처치해 달라고 부탁했습니다.\n\n그리고 카즈고름의 보고서를 갠 스톤스파이어에게 가져가야 합니다.", description = "난 지금 슬픔에 빠져 홀로 이 길을 걷고 있네.\n\n바엘 모단의 드워프들이 우리의 땅을 망치고 있어. 기계들이 굉음을 내며 언덕을 갈라 버리고 끔찍한 폭발 소리와 함께 깊은 구멍이 곳곳에 나고 있지. 이 땅은 우리 부족의 옛 고향이자 다양한 자원의 산지였는데 이제 저 드워프들의 파괴에 의해 엉망이 되고 있네.\n\n외교적인 노력도 실패하고 말았으니 이제 단호한 행동을 취할 때야.\n\n바엘 모단 발굴지에서 드워프 놈들을 몰아내고 그들의 우두머리인 발굴조사단장 카즈고름의 보고서를 가져다주게.", progress = "바엘 모단의 드워프들이 들어오면서 선량한 타우렌들이 무수하게 목숨을 잃었고 선조로부터 물려받아 태어나고 자란 이 터전에서 쫓겨나고 말았네. 우리 땅을 반드시 되찾아야 해!", completion = "카즈고름이 결국 자신이 저지른 죄에 걸맞은 운명을 맞았군. 이 땅에 무례했던 그 바보 녀석의 죽음에는 조금도 양심의 가책을 느끼지 않네.\n\n그의 죽음이 생명을 위협하고 파괴하려는 모든 자들에게 경고가 된다면 좋으련만...\n\n자, 그럼 난 이제 카즈고름의 보고서를 살펴봐야겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[844] = {title = "초원타조의 위협", objective = "초원타조 부리 7개를 모은 후 크로스로드에 있는 셀그라 다크쏜에게 돌아가십시오.", description = "당신의 첫번째 희생양이 될 상대는 아마 손쉬운 놈들일 거야.\n\n동쪽에서 초원타조가 우리의 보급 식량을 계속 훔쳐 먹고 있어 골칫거리가 되고 있지.\n\n초원타조를 처치하고 그 부리를 가져와 줘.", progress = "초원타조 부리를 모아 왔나?", completion = "아주 좋아. 초원타조들이 사라졌으니 우리 식량 보급망도 다시 원활히 작동할 거야. 이번 사냥을 통해 불모의 땅에서 살아가는 방법을 조금이나마 배웠기를 바라네. 다음 상대는 초원타조보다는 조금 강한 놈들이 될 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[845] = {title = "얼룩말", objective = "굶주린 얼룩말이나 사나운 얼룩말을 처치하여 얼룩말 발굽 4개를 모아 크로스로드에 있는 셀그라 다크쏜에게 가져다주어야 합니다.", description = "얼룩말들은 불모의 땅에서 그렇게 사나운 짐승은 아닐지 몰라도 초원타조보다는 까다로운 골치거리들이지. 겨우 얼룩말이라니 실망했나? 걱정마, 다음엔 충분히 강한 놈들을 상대하도록 해줄 테니 우선 이놈들부터 처리해줘.\n\n북쪽이나 남쪽으로 가서 얼룩말들을 해치우고 발굽을 가져와. 그 다음에는 좀 더 강한 놈들을 붙여주지.", progress = "얼룩말들을 얼마나 해치웠는지 궁금하군.", completion = "나쁘진 않군. 얼룩말들의 힘은 그들의 강한 뒷다리에서 나오지. 한번 제대로 놀렸다 하면 덩치 큰 타우렌들 조차 한 방에 날라간단 말이야.\n\n하지만 당신의 힘도 만만치 않아 보이는 걸. 자, 이제 진짜 도전을 해볼 준비가 됐나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[846] = {title = "갠의 복수", objective = "갠 스톤스파이어가 니트로글리세린 6병, 나무 펄프 6묶음, 질산나트륨 표본 6개를 가져다 달라고 부탁했습니다.", description = "지금도 저들이 폭약과 시끄러운 기계를 이용해 땅을 파헤치고 있다는 것은 명백한 사실일세. 곧 새로 부임할 현장감독이 잔인한 파괴를 계속하겠지...\n\n난 저 괘씸한 드워프 놈들에게도 폭발의 맛을 제대로 한번 보여주고 싶어. 그러려면 니트로글리세린과 나무 펄프, 질산나트륨을 혼합하여 폭발물을 만들어야 하지. 요새에 있는 소총병, 병사, 그리고 장교들에게 이 재료가 있다는군.\n\n이 물건들을 모아 내게 가져오게. 그러면 드워프들에게 잊지 못할 선물을 안겨 주겠어!", progress = "돌아왔군... <name>!\n\n카즈고름의 죽음으로 우리 조상님의 땅을 파헤치는 짓거리가 어느 정도 지체되고 있기는 하지만 완전히 끝난 건 아니야.\n\n바엘 모단에 있는 요새의 병력이 계속 늘어나고 있어. 처음에 그 요새를 건설한 이유는 발굴 현장을 방어하기 위해서였지만 이젠 공격 기지로 쓰고 있지.\n\n내가 말한 재료를 구해 오면 저 경솔한 드워프들에게 경고의 선물을 안겨주겠어. 녀석들 불모의 땅에서의 발굴 작업을 다시 한번 생각해 보게 될 걸!", completion = "꽤 성실한 &lt;race&gt;|1이로군;로군;.\n\n자, 보라고. 이제 저 드워프들이 화들짝 놀라게 될 일이 벌어질 테니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[847] = {title = "랩터의 기민함", objective = "토건과 대화해야 합니다.", description = "이... 이 힘은... 이게 토건이 내게 보여 주고 싶어했던 주술사의 힘인가? 정말... 정말 흥미롭군. 토건에게 가서 내가 크게 감동했다고 전해 주게. 물론 지금 당장 이야기일 뿐이지만. 그가 무슨 이야기를 하는지 들어 보겠네.", progress = nil, completion = "마법의 효과가 사라지면 고르멀과 이야기를 나누어 봐야겠군. 고르멀이 원래의 모습을 되찾도록 도와 줘서 고맙네. 고르멀 자신도 틀림없이 고마워할 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n랩터의 뿔나팔"},
[848] = {title = "버섯 포자", objective = "크로스로드에 있는 연금술사 헬브림에게 버섯 포자 4개를 가져다주어야 합니다.", description = "불모의 땅에 있는 오아시스엔 신비한 비밀이 숨겨져 있네. 물속에서 생명의 힘이 흘러 나와 이 물을 마시면서 사는 식물과 짐승들에게 생기를 불어넣어 주고 있지.\n\n뿐만 아니라 종 자체를 변화시키는 경우도 있네.\n\n이 신비의 오아시스 근처에서 자라는 버섯이 있는데, 우리 로데론의 연금술사들은 이 버섯 포자에 매우 유용한 성분이 들어 있는 것으로 보고 있지.\n\n내게 이 포자를 가져다주면 정말로 고맙겠네.", progress = "포자는 가지고 왔나? 썬더 블러프에 있는 내 동료에게 조제약을 보내 주어야 하는데, 그걸 만들려면 포자가 필요하네...", completion = "음, 이 정도면 훌륭한 표본이지. 효능이 아주 좋겠어.\n\n난 위대한 포세이큰의 일원으로서 한번 한 약속은 반드시 지키지. 자, 이건 내가 약속한 보상일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[849] = {title = "갠의 복수", objective = "바엘 모단에 있는 비행기를 파괴하고 갠 스톤스파이어에게 돌아가십시오.", description = "카즈고름의 보고서를 보니, 폭발을 일으키는 건 별로 어렵지 않겠어.\n\n흠... 이제 완성됐네.\n\n그대에게 특별한 임무를 맡기겠네. 이 폭탄을 가지고 가서 바엘 모단에 있는 비행기를 폭파시켜 버리게.\n\n그 비행기는 그곳 기반 시설의 핵심일 뿐 아니라 전쟁 무기로도 사용되고 있네. 하지만 더욱 중요한 것은 그것이 드워프들의 힘의 상징이자 우리 타우렌의 명예를 더럽힌 기계라는 점이지.\n\n이 명예로운 임무를 완수해 준다면 그대에게 충분히 보답하겠네.", progress = nil, completion = "잘해 주었네. 신성한 타우렌 땅의 수호자로서, 또한 잊혀진 부족의 전사로서 자네의 이름이 썬더 블러프의 대지에 영원히 기억되길!", rewards = "다음과 같은 것들을 받습니다:\n\n토템 반지"},
[850] = {title = "콜카르 지도자", objective = "바라크 코도베인을 처치하고 그 증거로 그의 머리띠를 크로스로드 서쪽에 있는 렉타르 데스게이트에게 가져가야 합니다.", description = "켄타우로스는 수년간 타우렌들을 괴롭혀 왔어. 최근에는 불모의 땅에 위협이 느껴질 정도로 콜카르 켄타우로스의 수가 늘어났지. 예전에는 오합지졸처럼 돌아다녔는데 지금은 이들을 하나로 통합한 지도자가 생긴 것 같아.\n\n이곳에 있는 우리 세력을 지키기 위해서는 켄타우로스 지도자를 없애야 하네.\n\n북쪽의 잊혀진 웅덩이 근처로 가서 바라크 코도베인을 처치하고 지도자의 상징인 머리띠를 가져오게.", progress = "바라크의 머리띠를 가지고 왔나?", completion = "잘했네. 켄타우로스는 지능이 낮고 야만적인 생명체지만 그 중에는 지도자의 덕목과 지혜를 갖춘 이들도 있지.\n\n바라크가 바로 그런 켄타우로스였어. 그가 이제 죽었다니 정말 다행이로군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[851] = {title = "광신자 베로그", objective = "베로그를 처치하고 그 증거로 그의 머리띠를 크로스로드 서쪽에 있는 렉타르 데스게이트에게 가져가야 합니다.", description = "광신자 베로그, 그는 불모의 땅 전역을 돌아다니지. 그래서 그를 찾아내기란 쉬운 일이 아니야. 하지만 그의 본거지라 할 수 있는 남동쪽의 죽은 오아시스 부근 지휘 천막에서 그를 유인해내는 건 가능할지도 모르네.\n\n남동쪽의 죽은 오아시스로 가서 지휘 천막 주변의 켄타우로스들을 공격하게. 매우 위험한 일이긴 하지만 켄타우로스를 상당수 처치하면 분명히 경계 태세로 접어들 거야. 그러면 베로그가 몸소 공격하러 나오겠지.\n\n그의 머리띠를 가지고 오면 바라크 코도베인의 머리띠와 나란히 두도록 하지.", progress = "베로그를 찾았나?", completion = "아주 잘했네. 켄타우로스 진영을 아예 쑥대밭으로 만들어 놓은 모양이더군. 수비병에게서 죽은 오아시스 근처에서 일어난 치열한 전투에 대해 보고를 받았는데 자네의 활약일 거라 생각했지.\n\n자네의 용맹은 정말 대단해. 이 일을 자랑스럽게 여기게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[852] = {title = "헤즈룰 블러드마크", objective = "헤즈룰을 처치하고 그 증거로 그의 머리띠를 크로스로드 서쪽에 있는 렉타르 데스게이트에게 가져가야 합니다.", description = "헤즈룰 블러드마크는 불모의 땅에 있는 콜카르 켄타우로스의 최고 지도자일세. 사납고 잔인하고 아주 교활하기 이를데 없는 녀석으로 알려져있지. 그를 처치하면 콜카르족을 혼란에 빠뜨려 분열시킬 수 있을 테고, 그러면 우리에 대한 녀석들의 위협도 크게 줄어들 거야.\n\n그래서 말인데, 녀석을 좀 처치해줄 수 있겠나?! 바라크나 베로그와 마찬가지로 헤즈룰의 머리띠를 내게 가져다주게.\n\n녀석은 여기서 남쪽에 있는 푸른 오아시스에서 일족을 거느리고 있네.", progress = "헤즈룰은 처치했나?", completion = "정말 훌륭하네. 이 켄타우로스들은 제대로 된 훈련을 받지 않아서 오크들처럼 힘을 한곳에 집중할 수도 없지만 강하고 사나운 녀석들임은 틀림없지. 녀석들을 처치했으니 자네의 용맹함이 증명되었군.", rewards = "다음과 같은 것들을 받습니다:\n\n현상금 사냥꾼의 반지"},
[853] = {title = "연금술사 자마", objective = "제한 시간 내에 썬더 블러프에 있는 연금술사 자마에게 정제된 포자를 가져가야 합니다.", description = "자네가 준 포자를 유액으로 정제했네. 이제 이걸 우리의 동료인 연금술사 자마에게 보내야 해. 가져다주면 가지고 있는 연금술 물품 중에서 무언가를 줄 거야.\n\n자마는 썬더 블러프의 주술사들이 모여 있는 곳의 아래 쪽에 있는 예언의 웅덩이라는 동굴에 있네. 이 동굴은 깊숙이 숨겨져 있지만 정기의 봉우리로 올라가는 길에서는 쉽게 찾을 수 있을 걸세.\n\n그런데 이 유액은 효력이 오래 지속되지 않아. 반드시 그 전에 봉인을 풀어 처리해야 하네. 그러니 발길을 재촉해야 할거야.", progress = "연금술사 헬브림이 무엇을 보내 온건가요?", completion = "아, 헬브림이 불모의 땅에서 포자를 모아 보냈군요. 그가 전해달라고 부탁했나 보죠? 잘 됐어요.\n\n유액이 아직 효력을 가지고 있는 걸 보니 바쁘게 달려온 모양이군요. 수고했어요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n최하급 인내의 비약최하급 민첩의 비약최하급 회복 물약신속의 물약\n\n다음과 같은 것들 또한 받습니다:\n\n요리용 가마솥 막대기"},
[854] = {title = "크로스로드로의 여정", objective = "불모의 땅에 있는 톨크과 대화해야 합니다.", description = "그대가 이곳에 오리란 걸 알고 있었네, 젊은 <class>|1이여;여;. 이젠 더 이상 젊기만 한 숙맥은 아니니 말일세.\n\n이제 그대가 보다 넓은 곳으로 떠나야 할 시간이 온 것 같군. 그대가 지금까지와는 다른 큰 일을 할 운명임을 느낄 수 있다네.\n\n그대가 탐험해야 할 땅은 크로스로드라네. 오크족과 우리의 교류가 이루어지는 곳이자 그들이 우리의 도움을 필요로 하는 곳이지. 길을 따라 동쪽으로 가다가 북쪽으로 방향을 바꾸어 계속해서 가다 보면 크로스로드에 닿을 것이네. 그곳에서 대지모신께서 축복을 내리신 톨크를 찾아가게.", progress = nil, completion = "이렇게 고마울 데가! 우리의 동맹 &lt;race&gt;족 &lt;class&gt;|1이;가; 썬더 블러프와 같이 머나먼 곳으로부터 우리를 지원하러 와 주다니 말일세. 정말 환영하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[855] = {title = "켄타우로스의 팔보호구", objective = "크로스로드 서쪽에 있는 렉타르 데스게이트에게 켄타우로스의 팔보호구 15개를 가져가야 합니다.", description = "불모의 땅에 있는 켄타우로스들은 항상 호드를 위협하는 골칫거리라네. 반드시 그 무리의 수를 줄여야 해. 그래서 현상금이 걸린 임무를 자네에게 맡기려 하네.\n\n콜카르 지역으로 들어가서 켄타우로스의 팔보호구를 모아오게. 팔보호구를 충분히 구해온다면 그에 합당한 보상을 해 주겠네.", progress = "켄타우로스 놈들을 처치하는 일은 어떻게 되어가나?", completion = "아주 잘했네! 살아남은 켄타우로스 놈들도 겁을 먹었을 게 확실해. 생각이 조금이라도 있다면 이제 공격은 그만두고 조용히 숨어 지낼 텐데...\n\n하지만 그럴 것 같지는 않으니 불행한 일이야.\n\n물론 내 말은 그놈들에게 불행한 일이 될 거란 말이지...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n오크족 전투활뾰족한 도끼돌나무 해머\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[857] = {title = "달의 눈물", objective = "추방자 피글리가 달의 눈물을 되찾아 달라고 부탁했습니다.", description = "그 힘은 내 것이었어! 바로 내 손 안에 들어와 있어야 한단 말이지. 그걸 되찾아야 해. 되찾아야 한다고!\n\n저 더러운 굴착자들이 그걸 발견했지... 얼마나 아름다웠는지 몰라. 달의 눈물은 바엘 모단에서 우리가 처음으로 이루어낸 위대한 발견이지.\n\n그건 내 것이었어야 했어. 내 것이어야 했다고!\n\n트윈브레이드 장군은 달의 눈물이 지닌 힘을 탐내어 요새 깊숙한 곳에 숨겨 버렸어. 그 저주 받을 자가 그랬다고! 바보 같은!\n\n괘씸한 트윈브레이드가 나를 쫓아내 버렸어. 다른 자들도 그걸 노리고 있어. 그들 역시 막아야 해!\n\n이제 그걸 되찾아야 해. 되찾아야 한다고!", progress = "달의 눈물은 어디 있나? 난 지금 당장 그게 필요해! 꼭 필요하다고!", completion = "아, 결국 나의 힘을 되찾았어. 되찾았다고!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[858] = {title = "시동", objective = "위즐크랭크에게 시동 열쇠를 가져다주어야 합니다.", description = "설마 스퍼터밸브가 보낸 건가? 난 이 안에 꼼짝없이 갇히게 됐네. 처음엔 이 벌목기를 타고선 좋아라 했지... 시동축을 풀려면 열쇠가 필요하다는 것도 모르고 말이야. 다른 벌목기 조종사가 내게 무슨 문제가 있냐고 물어 봤는데, 그만 당황해서... 그냥 기계에 이상이 좀 있는 것 같다고 말했지 뭐야. 그 때 열쇠를 잃어버렸다고 했어야 하는데...\n\n빨리 여길 벗어나야 해! 관제탑 꼭대기 층의 관제실에 있는 관리자가 이 벌목기의 열쇠를 가지고 있을 거야.\n\n여기서 도망갈 수 있게 나 좀 도와 달라고!", progress = "서둘러줘! 의심 받기 전에 이곳을 떠나야 한다고!", completion = "그래, 이 열쇠가 맞는 것 같군. 잠깐만 기다려 봐. 이걸 어떻게 작동하는지 생각 좀 해보게 말이야.\n\n음... 이건 회전 제어장치고... 이건 속도와 수평을 조절하는 거고... 와! 이 팔 제어장치는 정말 대단한 걸! 이것 봐! 투자개발회사에서 이렇게 우수한 벌목기를 설계했다는 게 믿어지지 않아. 우리 것보다 훨씬 좋잖아! 이걸 톱니항으로 가져가야겠어!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[860] = {title = "셀그라 다크쏜", objective = "크로스로드에 있는 셀그라 다크쏜과 대화해야 합니다.", description = "사냥꾼의 길을 가기 원한다면 그 여정은 불모의 땅으로 이어질 것이오. 그곳에 사는 야수들은 집념이 강하고 아주 사납지. 그곳에서 사냥을 하면 많은 것을 배우게 될 것이고 그대의 영혼이 성장하게 될 거요.\n\n불모의 땅에서의 첫 번째 안내자가 될 셀그라 다크쏜과 얘기해 보시오.\n\n셀그라는 크로스로드에 있소이다. 그녀에게 가려면 블러드후프 마을에서 동쪽으로 가서 불모의 땅에 들어서면 길이 갈라지는 곳에서 북쪽으로 가시오. 불모의 땅은 준비가 되지 않았거나 부주의한 이들에게는 아주 위험한 곳이니까 가는 길에 조심하도록 하시오.", progress = nil, completion = "불모의 땅에서 사냥을 하고 싶다고?\n\n눈이 열정과 젊음에 차 있군. 하지만 곧 이 땅의 메마른 평원을 가로질러 사냥감을 추적하게 되면 그 눈을 찌푸리게 되는 날이 많을 거야.\n\n그렇다고 걱정할 필요는 없어. 우리가 몸과 마음을 모두 강하게 만들어 줄 테니까. 그리고 사냥이란 단지 사냥감을 찾고 처치하는데 그치지 않는다는 것을 배우게 될 거야.\n\n준비하라고. 이제 여행이 시작되니까. 바로 지금.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[861] = {title = "사냥꾼의 길", objective = "썬더 블러프에 있는 멜로르 스톤후프에게 굶주린 평원퓨마 발톱 4개를 가져가야 합니다.", description = "자네는 모험에 굶주려 있는 것 같군. 내 한 눈에 알 수 있지. 예전에 나도 젊은이처럼 모험을 즐기던 때가 있었네.\n\n수색과 사냥... 우리 타우렌에게 사냥은 최고의 영예라네.\n\n정말 사냥꾼의 길을 가고 싶다면 멜로르 스톤후프를 만나 보게나. 그가 사냥꾼의 길에 대해 알려줄 걸세. 그는 썬더 블러프의 수렵의 봉우리에 있다네.\n\n그에게 젊은이의 능력과 결의를 보여주려면 멀고어에 있는 굶주린 평원퓨마 발톱을 가져가길 권하네. 그 짐승은 사납고 교활한데, 사냥꾼의 길을 가려는 젊은 <class>에게는 더 없이 좋은 사냥감이지.", progress = "어서 오시오. 그대에 대한 얘기는 많이 들었지. 나에겐 무슨 용무인가?", completion = "스코른 화이트클라우드는 현명한 타우렌이지. 비록 몸은 늙었지만 그는 강한 정신력으로 오랫동안 사냥을 계속해 왔지. 우리 타우렌에 그와 같은 이가 있다는 건 영광이 아닐 수 없소.\n\n스코른이 보냈다면 그대에게도 역시 사냥꾼의 정신이 있겠군. 그리고 모아온 이 발톱들을 보니 기본적인 기술은 있는 것 같군그래.\n\n사냥꾼의 길을 가기 위한 준비는 된 것 같소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[862] = {title = "들쥐 고기 스튜", objective = "크로스로드 동쪽에 있는 그럽에게 들쥐 고기 8개를 가져가야 합니다.", description = "당신 같은 <class>|1은;는; 이곳 불모의 땅에서 배고픔으로 고생하는 경우가 많지. 나? 나도 하루종일 배가 고프다오.\n\n당신이 좋아할 만한 얘기를 하나 들려줄까? 내 당신을 위해 맛있는 스튜를 만들어 주겠소. 들쥐 몇 마리만 있으면 되지.\n\n그런데 아, 글쎄, 바엘 모단의 그 추악한 드워프 놈들이 모두의 일용할 양식인 들쥐를 죄다 먹어치우고 있는 모양이오. 자, 남쪽의 바엘 모단으로 가서 들쥐를 잡아 그 고기를 가져다주시오.\n\n들쥐 사냥을 해보지 않은 자는 호드의 노련한 <class>|1이라고;라고 할 수 없지! 암!", progress = "들쥐 고기는 충분히 가져 왔소?", completion = "나는 사실... 막 잡은 들쥐로 만든 음식은 별로 좋아하지 않소. 몇 주 동안 썩혔다가 먹어야 제 맛이 나지... 하지만 지금 당신이 너무 허기져 보이니...\n\n당장 들쥐 고기 스튜를 만들어 대령하리다.\n\n자, 여기... 맛 좀 보시오.", rewards = "다음과 같은 것들을 받습니다:\n\n조리법: 들쥐 스튜들쥐 스튜약제사 장갑"},
[863] = {title = "탈출", objective = "위즐크랭크와 그가 훔쳐 낸 고블린 벌목기를 톱니항에 있는 스퍼터밸브에게로 호위해 가야 합니다.", description = "톱니항으로 가는 동안 죄다 알아낼 수 있을 거야... 뭐, 그리 어렵진 않을 것 같은데... 여기에 단추 몇 개랑 레버 한두 개를... 흠, 떠날 준비는 다 되었나?", progress = nil, completion = "부서진 벌목기 원형에서 뭔가 중요한 걸 알아낼 수 있어야 할 텐데... 시간이 별로 없다는 게 문제군. 즉시 위즐크랭크가 있는 곳으로 구조대를 보내도록 하지.\n\n아, 그리고 당신에게 줄 것이 있어.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n불타는 지휘봉땜장이의 기름얼룩 바지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[864] = {title = "연금술사 진게에게 돌아가기", objective = "언더시티에 있는 연금술사 진게에게 봉인된 분석 도구를 가져가야 합니다.", description = "\"자, 됐소. 동력원은 안전하게 제거됐고 안에 든 자료는 그대로 남아 있소. 그럼, 잘 가라고. 그 사악한 과학 실험이 잘 풀렸다면 좋겠군.\"\n\n빌지위즐이 등을 돌리고 가젯잔 수자원개발회사의 일에 집중합니다. 봉인된 분석 도구를 잘 챙겨서 언더시티로 되돌아갈 준비를 합니다. 그곳에서 연금술사 진게가 당신이 봉인된 분석 도구를 가져오기를 기다리고 있습니다.", progress = "돌아왔군요. 봉인된 분석 도구를 갖고 돌아온 것이라면 환영해요. 그게 아니라면, 당신의 무능함을 모른 체하고 주어진 임무를 완수할 때까지 화를 참도록 하죠.", completion = "즉시 이 자료를 분석하도록 하겠어요. 어쩌면 키버의 광기 덕에 내가 천재가 되겠군요.\n\n당신은... 내겐 아주 능력있는 일꾼이었어요. 난 언제나 변함없이 내게 도움이 된 자에게는 보상을 아주 후하게 한답니다. 자, 이 돈도 받고 내 감사의 마음도 함께 받으세요.\n\n나중에 가끔 내게 들리도록 하세요. 이번 임무만으로 우리의 관계가 끝나지는 않을 테니까요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n숙련자의 장갑수석 연금술사 단망토지식껍질 어깨보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[865] = {title = "랩터 뿔", objective = "온전한 랩터 뿔 5개를 모아 톱니항에 있는 메보크 미지릭스에게 가져가야 합니다.", description = "이곳 불모의 땅 랩터들은 다른 곳에 사는 랩터보다 특출나게 영리하지. 놈들의 명석함은 전부 그 뿔에서 나오는 게 틀림없다고. 그렇다면, 놈들의 뿔을 갈아 가루로 내서 포도주에 타면 영리해지는 음료를 만들 수 있을지 몰라. 그걸 팔면 큰돈을 벌 수 있을 테고 말이지!\n\n좀 도와줘. 갈퀴발톱 열대초원랩터들을 처치해 온전한 랩터 뿔을 구해다 주게. 놈들은 불모의 땅 남쪽 지역과 잿빛 골짜기 숲 가장자리 부근, 불모의 땅 북쪽 지역을 돌아다니고 있어!", progress = "뿔은 구해 왔나? 그 뿔만 있으면 큰돈을 만질 수 있단 말이야!", completion = "뿔을 구해 오다니 정말 대단하군! 이제 이 뿔들을 갈아서 포도주에 섞기만 하면 음료가 완성되지.", rewards = "다음과 같은 것들을 받습니다:\n\n랩터 펀치바텐더 망토"},
[866] = {title = "뿌리 표본", objective = "톱니항에 있는 메보크 미지릭스에게 뿌리 표본 8개를 가져가야 합니다.", description = "이곳 불모의 땅의 향초는 다른 땅에 것과는 달리 좀 독특하지. 대부분의 특성이 비슷하긴 하지만... 이곳에서 자라는 향초는 조금 달라. 오아시스의 물이 이곳 식물들을 약간 변질시켜서 그런 것 같아. 아주 약간이긴 하지만...\n\n만약 그 내용물을 추출할 수 있다면 그 차이에 대해 연구해 보고 싶은데.\n\n약초 채집에 자신이 있다면 불모의 땅에서 발견되는 향초의 뿌리 표본을 좀 모아 줘. 표본을 가져다주면 다른 지역에서 나는 향초와 비교해 볼 수 있을 테니까.", progress = "뿌리 표본은 구해 왔나?", completion = "훌륭해, 이 표본은 정말 훌륭해! 이 뿌리에서 향초 표본을 길러 연구할 거야. 향초에서 새로운 특성을 알아낼 수 있으면 좋겠는데... 전에 없던 귀한 특성을!\n\n알아낸다면 제일 먼저 자네에게 알려줄 테니 염려 말아. 나도 향초를 더 많이 구해다 줄 일손이 필요할 테니까...", rewards = "다음과 같은 것들을 받습니다:\n\n이끼 덮인 튜닉"},
[867] = {title = "하피의 습격", objective = "칼날바람하피의 갈퀴발톱을 8개 모아야 합니다.\n\n크로스로드에 있는 달소크 스위프트대거에게 돌아가십시오.", description = "하피가 우리의 짐마차 보급품을 습격해 온 것은 아주 오래전부터지. 이제 그 마녀 같은 것들의 숨통을 조여야 할 때야.\n\n그동안 하피 소굴을 조사하면서 지휘관이 누구인지 알아냈지. 일단 하급 지휘관들을 먼저 처치해 놓은 후에 상급 지휘관들을 해치우도록 해.\n\n너무 서두를 필요는 없어. 일단 북서쪽에 있는 칼날바람하피와 칼날바람일족 약탈자를 사냥해서 칼날바람하피의 갈퀴발톱을 8개 가져오도록 해. 그 정도면 우리 일의 시작치곤 괜찮을 거야.", progress = "하피들을 해치웠나? 칼날바람하피의 갈퀴발톱 8개를 가져오라고.", completion = "오, 잘했어. 아주 좋아, 정말 잘했어. 앞으로 많은 활약을 기대하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[868] = {title = "알 사냥", objective = "크로스로드에 있는 코란에게 실리시드의 알 12개와 갈퀴발톱 장갑을 가져가야 합니다.", description = "난 이 땅에서 일어나고 있는 일을 조사해서 상사들에게 보고해야 하는 임무를 띠고 오그리마에서 이곳 크로스로드로 파견되었소.\n\n그 임무 중 하나는 거인의 들판에 출몰하는 곤충 같이 생긴 어떤 생물을 조사하는 것이오. 그런데 정보가 거의 없단 말이지... 그 어떤 생물보다도 높은 지능을 지닌 듯 하다는 것밖에... 앞으로 더 자세히 조사해봐야 하오.\n\n이 갈퀴발톱 장갑을 가지고 놈들이 살고 있는 언덕에서 알을 좀 모아 주시오. 놈들에게 발각되면 공격을 받을 수 있으니 들키지 않도록 조심하시오.", progress = "<name>, 알이 깨져버리면 아무 쓸모가 없으니까 조심해서 다루어야 하오.", completion = "알을 채집해 주고 쓰고 난 장갑까지 돌려주어서 정말 고맙소.\n\n자, 이건 수고에 대한 답례요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n익살꾼의 로브보라색 미늘 갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[869] = {title = "도둑 랩터", objective = "크로스로드에 있는 가즈록에게 랩터 머리 12개를 가져가야 합니다.", description = "얼마 전 경비탑에서 은화 상자를 도둑맞았소. 그 상자에 든 은화는 크로스로드 경비병들의 봉급이니 반드시 되찾아야 하오.\n\n그런데 이상한 점은... 도둑맞던 날 밤에 범인을 하나를 붙잡았는데, 그게 바로... 랩터였다니 믿을 수 없는 일이오!\n\n랩터들이 왜 은화를 훔쳐간 건지 도통 모르겠단 말이야... 어쨌든 랩터를 처치해 다시는 우리 물건을 훔치지 못하도록 해야 하오.\n\n불모의 땅에 살고 있는 랩터를 처치하고 놈들의 머리를 가져오시오.", progress = "놈들의 머리는 가져왔소?", completion = "랩터들을 처치했군!\n\n고맙소. 당신은 정말 훌륭한 호드의 &lt;class&gt;|1이요;요;.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[870] = {title = "잊혀진 웅덩이", objective = "통가 룬토템에게 발견한 내용을 보고해야 합니다.", description = "먼 옛날 이곳 불모의 땅은 수풀이 우거지고 생명의 활기가 넘치는 지역이었지. 하지만 전쟁의 대혼란이 휩쓸고 가면서 초토화되어 이제는 메마른 대지만 남았을 뿐이야. 슬프기 짝이 없지만 세상 이치가 그러한 걸 어쩌겠나?\n\n그런데 몇 년 전부터 이 땅에 새로운 오아시스가 생겨나 활기를 되찾기 시작했어. 우리 드루이드들은 어떠한 힘이 대지로부터 솟아나오고 있는 것을 어렴풋이 느낄 수 있었지.\n\n그 근원을 찾아내야 하네. 크로스로드의 북서쪽에 있는 잊혀진 웅덩이로 가게. 그곳 물속에서 힘의 근원을 찾아낸 후 돌아오게나.", progress = nil, completion = "밑바닥에 있는 바위에 갈라진 틈이 있고 그곳에서 기체 방울이 올라오고 있다고? 이상하군... 그것이 우리가 찾는 답일 수도 있겠지만 아직 확신할 수는 없군그래.\n\n자네가 알아온 내용이 힘의 근원을 추적하는데 필요한 정보는 될 것 같군. 다녀와줘서 고맙네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[871] = {title = "공격 저지", objective = "서슬갈기일족 풍수사 8마리, 서슬갈기일족 가시마술사 8마리 및 서슬갈기일족 사냥꾼 3마리를 처치한 후에 크로스로드에 있는 톨크에게 돌아가십시오.", description = "모든 가시멧돼지는 우리의 적이야. 특히 그중 몇 녀석이 큰 골칫거리가 되고 있지.\n\n요즘 서슬갈기일족이 듀로타로부터 이어지는 우리 보급로를 계속 공격하고 있네. 정찰병을 보내 놈들의 지휘관이 누구인지 조사하고 있는 중인데, 그동안 당신이 이 성가신 멧돼지 놈들을 손봐준다면 우리에게 도움이 될 거야.\n\n먼저 북동쪽 듀로타 방향으로 가면서 놈들을 찾아보게. 놈들의 소굴은 땅속에서 올라온 아주 큰 덩굴들로 이루어져 있어서 쉽게 알아볼 수 있을 거야. 놈들을 찾아 처치해 주기 바라네.", progress = nil, completion = "잘했네. 저 오만한 가시멧돼지 놈들도 호드의 힘을 무시할 수 없다는 교훈을 깨우치게 됬을 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[872] = {title = "습격의 종결", objective = "서슬갈기일족 흙점쟁이 8명과 서슬갈기일족 파수병 8명, 크리니그 스날스나웃을 처치해야 합니다.\n\n그런 다음 크로스로드에 있는 톨크에게 크리니그 스날스나웃의 어금니를 가져가야 합니다.", description = "우리 정찰병 중 한 명이 듀로타에서 오던 짐마차가 습격당하는 걸 목격했소. 이런 짓을 할 녀석들은 서슬갈기일족 가시멧돼지 뿐이오. 가시멧돼지 놈들 중 크리니그 스날스나웃이라는 녀석이 습격을 지휘하고 있었다하오. 녀석은 이곳에서 북동쪽이자, 듀로타로부터 오는 길 바로 남쪽에서 목격되었소. 놈들의 위협에 종지부를 찍으려면 이 크리니그란 놈을 반드시 처치해야 하오.\n\n그런 다음 놈들이 다시 공격할 엄두도 내지 못하게 하려면 놈들을 혼내 주고 심한 모욕감도 심어주어야 할 것이오. 그러니 크리니그와 함께 그 일족들을 처치한 다음 녀석의 어금니를 가지고 내게 돌아오시오.", progress = "잊지 마시오! 어떤 무리던 우두머리를 처치하면 혼돈이 뒤따르게 마련이라는 것을... 언제든 도움이 될만한 진리지.\n\n놈들이 방향을 잃고 허둥대게 되면 불모의 땅을 원래대로 만들 수 있을 것이오.", completion = "수고했소. 크리니그를 처치했으니 이제 다시 우리 짐마차를 공격하는 일은 없을 거요.\n\n당신은 분명 &lt;race&gt;의 자랑거리가 될 것이 분명하군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n결속의 벨트뱃대끈 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[873] = {title = "이샤 아와크", objective = "마렌 스카이시어에게 이샤 아와크의 심장을 가져가야 합니다.", description = "이 해안의 지배자인 거대한 이샤 아와크는 자존심이 강하고 엄청난 힘을 자랑하지요. 그동안 놈은 해변에 살고 있는 많은 인간들을 해쳤기 때문에 모두 두려워하고 있죠.\n\n하지만 난 놈이 두렵지 않아요. 오히려 놈이 이곳에 있다는 사실에 감사하고 있죠. 도전할 만한 가치가 있는 훌륭한 사냥감이니까요.\n\n자, 준비가 됐다면 저 바다를 헤엄쳐 가서 이샤 아와크를 찾도록 하세요.\n\n놈의 영혼이 담긴 심장이 뛰는 소리를 들으면 당신의 운명을 알 수 있을 거예요.", progress = "물을 두려워해선 안 돼요!", completion = "이제 그의 영혼이 당신과 함께할 거예요. 이샤 아와크는 당신의 눈 안에 스며들어 당신과 하나가 되었어요.\n\n언젠가 그의 영혼이 담긴 눈으로 세계를 볼 수 있게 될 거예요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n낙인의 마법봉골짜기의 수호방패\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n이샤 아와크의 힘\n\n다음과 같은 것들 또한 받습니다:\n\n조련사 벨트"},
[874] = {title = "마렌 스카이시어", objective = "마렌 스카이시어와 대화하십시오.", description = "지금껏 불모의 땅의 짐승들을 사냥한 것을 보면 자네는 기백이 상당한 친구일세. 하지만 진정한 <race>|1은;는; 항상 어떠한 곳에서도 사냥감을 쫓을 수 있는 준비가 되어 있어야 하네. 험한 산이라도, 깊은 늪도 문제가 되어서는 안 돼지. 심지어 바다까지도 쫓아가야 해.\n\n내 누이인 마렌을 찾아 가게. 그녀는 해안을 따라 물에 사는 짐승들을 사냥하고 있지. 누이가 녀석들을 어떻게 사냥하는지 방법을 알려줄 거야.\n\n그런데 누이를 찾아가는 동안 조심해야 할 거야. 불모의 땅의 해안은 인간들이 장악하고 있으니까 말이야.", progress = nil, completion = "오라버니가 당신을 보낸 거 맞지요? 그렇다면 실력이 상당한 분이겠군요. 조른의 인정을 받은 분이라면 대우해 드려야 마땅하지요.\n\n사냥할 준비는 됐나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[875] = {title = "하피 부대장", objective = "칼날바람일족 암살자들에게서 하피 부대장의 반지 6개를 모아 크로스로드에 있는 달소크 스위프트대거에게 가져가야 합니다.", description = "하하하, 또...? 좋아, 자세가 아주 마음에 드는군.\n\n이번에는 메마른 언덕에 있는 하피 부대장들을 좀 처치하도록. 칼날바람일족 암살자들만이 부대장이 될 수 있지. 놈들이 끼고 있는 반지가 바로 계급을 알려 주지. 그 추잡한 것들이 그곳에서 조무래기들을 지휘하고 있지. 여섯 마리 정도는 처치해야 놈들의 뿌리를 뒤흔들어 놓을 수 있을 거야.\n\n반드시 죽음의 고통을 선사하여 호드에 대항하는 것이 얼마나 어리석은 짓인지 일깨워 주도록 해.", progress = "아직 하피 부대장의 반지 6개를 모으지 못 했나? 감히 호드에 잔인한 공격을 감행한 그들에게 정의의 처단을 내려야 해.", completion = "아주 잘했어. 앞으로 호드의 큰 영웅이 될 재목이로군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[876] = {title = "붉은깃털 세레나", objective = "붉은깃털 세레나를 처치하고 그 증거로 그녀의 머리카락을 크로스로드에 있는 달소크 스위프트대거에게 가져가야 합니다.", description = "부대장들과 그 부하들을 잘 처리해 주었으니 이제 마지막으로 한 가지만 더 부탁하지.\n\n붉은깃털 세레나는 오래전 렉사르가 처치한 블러드페더라는 이름의 하피와 자매 사이야. 놈들이 이번에 호드의 짐마차를 공격한 것도 언니의 죽음에 대한 복수라고 하네.\n\n그녀를 처치하고 내게 증거를 가져오도록. 다음번 짐마차에 그 증거를 실어 보내고 싶단 말이야. 부디 저 하피들에게 따끔한 맛을 보여 주도록.", progress = "세레나를 처치한 증거를 가져오기 전엔 아무 얘기도 하지 않겠어.", completion = "오! 훌륭하군! 아주 훌륭해... 처음엔 자네가 이 임무를 잘해낼 수 있을지 확신이 들지 않았는데... 자네의 실력이 충분히 증명되었어. 자, 이건 보상이야. 도움이 되었으면 좋겠군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n세련된 쇼트소드하피 가죽칼조부르 도끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[877] = {title = "죽은 오아시스", objective = "죽은 오아시스를 조사한 후 크로스로드에 있는 통가에게 돌아가야 합니다.", description = "잊혀진 웅덩이에서 발견한 것과 같은 틈을 불모의 땅에 있는 다른 오아시스에서도 볼 수 있을 지 모르네. 그렇다면 아마 그 틈이 오아시스 생명의 근원이 맞을거야. 내 그 틈을 한번 실험해 보고 싶군.\n\n자, 이 씨앗을 받게. 말라 비틀어져 이미 죽어버린 씨앗이지... 이걸 남동쪽에 있는 죽은 오아시스로 가지고 가보게. 그곳에도 틈이 있다면 씨앗을 그 안에 심고 어떻게 되는지 지켜보고 다시 와서 알려주게.", progress = "죽은 오아시스에 다녀왔나? 그곳의 물 밑바닥에도 틈이 있던가?", completion = "정말 놀라운 사실을 발견해 냈군! 알다시피 내가 준 씨앗은 말라서 죽은 거였네. 대체 오아시스 밑에 있는 게 무엇인지는 모르겠지만, 아무튼 무에서 생명을 창조해내는 힘이 있다는 건 확실한 것 같네!\n\n좀 더 연구해 볼 필요가 있겠군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[878] = {title = "부족 간의 전쟁", objective = "뾰족털일족의 풍수사 6명, 가시마술사 12명, 흙점쟁이 12명을 처치해야 합니다. 임무를 완수한 후 불모의 땅, 타우라조 야영지에 있는 뻐드렁니에게 돌아가십시오.", description = "적을 처치해주게. <킁> 이 뻐드렁니와 서슬갈기일족을 도와 뾰족털일족을 공격해줘. 두 부족 모두 신앙심이 아주 깊어서 땅의 힘을 부릴 수 있지. <킁킁> 땅은 언제나 우리에게 큰 힘을 주지. 특히 전쟁에서!\n\n이 뻐드렁니를 도와 주면 톨크와 <킁> 호드의 고민이 뭔지 알 수 있을걸! 북쪽으로 가서 뾰족털일족의 정신적 지도자들을 처치해. 그때 우리 서슬갈기일족은 이 불모의 땅을 지배할 수 있네.", progress = nil, completion = "그래, 그래... &lt;race&gt;, 드디어  뾰족털일족에게 우리 일족의 앙갚음을 했으니 아주 기뻐해야겠지. 그렇지만 뻐드렁니는  하나도 안 기뻐.\n\n자네는 종족을 위해 일하고 칭찬을 듣지만, 뻐드렁니는 뭐야? 나도 우리 일족을 위해 힘써왔지만, 도움은커녕 등을 돌릴 뿐이었어. 나를 까맣게 잊어버리고 이 우리 속에서 썩게 만들잖아!\n\n나는 이렇게 갇혀 있으면서도 종족을 위해 애를 쓰지만 아무도 구출해줄 생각조차 안 해!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[879] = {title = "내부의 배반자", objective = "나크와 쿠즈, 로크를 처단하여 그들의 해골을 불모의 땅의 타우라조 야영지에 있는 뻐드렁니에게 가져가야 합니다.", description = "일족 세 명이 감옥에서 탈출해 약탈을 일삼고 있어. <킁킁> 잔인하고 교활하기 짝이 없는 녀석들... 처치할 수만 있다면 크로스로드 뿐만 아니라 불모의 땅 전체가 평화로워질 거야... <킁> 최소한 우리 서슬갈기일족이라도 말이지. <킁킁>\n\n자네가 처리해야 할 놈들은 나크와 쿠즈, 로크 일행이야. 불모의 땅에서 남쪽으로 멀리 떨어진 곳에서 찾을 수 있을 거야. 한 놈은 마법사이고 다른 놈은 사냥꾼, 그리고 우두머리 로크는, <킁킁> 전사야. <race>, 그들에게 쓴맛을 보여주게. 마지막 눈을 감으며 우리 일족에게 저지른 끔찍한 짓을 후회하도록...", progress = "<race>, 일은 잘 돼가고 있나? \n\n톨크는 누가 일족을 약탈하는 지 안다고 생각하지만,  자네가 성공한다면 자기가 틀렸음을 깨닫게 되겠지.\n\n비록 뻐드렁니는 이 안에서 죽어갈 운명이지만 자네가 나 대신 그놈들을 처치해주었으면 죽어도 후회는 없을 것 같아.", completion = "뻐드렁니가 원하던 결말이군. 또한 뻐드렁니가 바라던 방식이기도 하고... &lt;킁킁&gt; 날 배신했을 때, 죽이지 않고 &lt;킁킁&gt; 이 버려진 우리 속에 가두어 둔 게 &lt;킁킁&gt; 놈들의 가장 큰 실수지.\n\n&lt;race&gt;, 이제 자네에게 마지막으로 한 가지 더 부탁할 게 있어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[880] = {title = "변화된 생물", objective = "크로스로드에 있는 통가 룬토템에게 변형된 무쇠턱거북 등껍질 8개를 가져다주어야 합니다.", description = "자네가 발견한 것은 정말 놀라운 사실이야. 이 오아시스에는 외부의 어떠한 근원으로부터 오는 뭔가가 있는 것 같아. 아니, 어쩌면 내부 세계의 것일 수도 있고...\n\n그 틈이 오아시스 물을 마시는 짐승에게 어떤 영향을 미치는지 알고 싶네.\n\n푸른 오아시스와 죽은 오아시스의 물속에 사는 무쇠턱거북을 사냥해서 등껍질을 몇 개 가지고 오게.", progress = "그래, 일은 어떻게 돼 가나? 등껍질을 다 모았나?", completion = "고맙네. 이 지역의 짐승들을 연구해 보면 더 많은 정보를 얻을 수 있겠지. 이 껍질이 내게 무엇을 알려 줄지 어디 한번 보자고.\n\n노고의 대가로 여기 내 성의의 표시를 받아주기 바라네... 아마 자네에게는 이 돈이 도움이 될 걸세. 내게는 쓸모 없는 쇳덩이에 불과하지만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[881] = {title = "에체야키", objective = "크로스로드에 있는 셀그라 다크쏜에게 에체야키의 통가죽을 가져가야 합니다.", description = "사바나 사자 무리의 왕은 에체야키라는 놈인데 타우렌어로 하얀안개라는 뜻이지. 몰래 먹잇감에 접근해 사냥하는 모습이 마치 대지 위에 옅게 깔린 하얀안개와도 같아서 그런 이름이 붙었어. 녀석은 먹잇감이 두려움이나 고통을 느낄 새도 없이 빠른 속도로 달려와 처치해 버리지.\n\n이곳 타우렌들은 녀석이 곧 자비이자 죽음 그 자체라고 하지. 당신도 에체야키를 상대하다보면 그 말의 의미를 알게 될 거야. 녀석의 소굴은 크로스로드의 북동쪽에 있는 커다란 코도의 뼈 근처에 있어.\n\n어서 떠나도록 해. 그 소굴에 가까이 가서 이 뿔피리를 불면 녀석이 나타날 거야.", progress = "사자의 왕이 당신을 부르고 있어.", completion = "에체야키를 처치했으니 녀석이 더 이상 사냥은 못할 테지만... 그 영혼은 당신 속에 남아 있을 거야. 에체야키의 영혼은 당신에게 날카로움을 지닌 힘과 자비로운 명예를 가지게 해줄 거야.\n\n당신 앞에는 아직 긴 여정이 남아 있으니 그 길을 잘 헤쳐나가길 바라네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n에체야키의 은총\n\n다음과 같은 것들을 받습니다:\n\n"},
[882] = {title = "이샤무헤일", objective = "타우라조 야영지에 있는 조른 스카이시어에게 이샤무헤일의 송곳니를 가져가야 합니다.", description = "강철이빨 이샤무헤일은 불모의 땅에서 가장 사나운 열대초원 랩터일세. 놈이 사냥을 하는 이유는 먹기 위한 것도 재미를 위해서도 아니지. 순수한 사냥에 대한 열정 때문이야. 그것이 놈의 본성이기 때문에 다른 생물들을 죽이는 거야.\n\n이샤무헤일을 쫓다 보면 자네도 놈의 본성을 알게 될 걸세.\n\n어서 사냥을 떠나게. 그가 가장 좋아하는 먹이인 얼룩말을 처치하고, 그 시체를 톱니항 북서쪽에 있는 고목으로 가져가게. 이샤무헤일은 시체의 냄새를 맡고 나타날 거야.\n\n그가 나타나면 마음의 준비를 하도록 하게.", progress = "이샤무헤일은 처치했나?", completion = "이 송곳니는 그저 전리품에 불과하지만 그 의미는 그리 하찮은 게 아닐세.\n\n바로 이샤무헤일의 힘이 그대 안에 있음을 나타내지. 이 송곳니 의미를 항상 기억하도록 하게. 그것이 적의 죽음에 대한 그대의 의무이며 그대의 명예이기도 하다네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n이샤무헤일의 격노\n\n다음과 같은 것들을 받습니다:\n\n"},
[883] = {title = "라코타마니", objective = "타우라조 야영지에 있는 조른 스카이시어에게 라코타마니의 발굽을 가져가야 합니다.", description = "라코타마니의 발굽은 위대한 코도의 힘을 상징합니다.", progress = "내게 다가오는 그대의 힘찬 걸음에서 새로운 힘을 느낄 수 있었네. 말해 보게. 그대의 영혼이 저 위대한 라코타마니를 만난 건가?", completion = "우리는 라코타마니를 '천둥소리'라 부르네. 놈의 발소리는 천둥과 같지. 이제 그 천둥소리가 그대의 영혼과 함께하니 그 용맹함도 그대의 것일세. 이제 어떠한 난관이라도 헤쳐나갈 수 있을 거야.\n\n당당하게 걸어나가게. 당당하게 말이야, 천둥소리...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n라코타마니의 우레\n\n다음과 같은 것들을 받습니다:\n\n"},
[884] = {title = "오와탄카", objective = "타우라조 야영지에 있는 조른 스카이시어에게 오와탄카의 꼬리가시를 가져가야 합니다.", description = "오와탄카의 꼬리가시에 손을 대자 불꽃이 일어납니다.", progress = "자네 눈 너머에서 새로운 힘이 느껴지네. 이미 오와탄카를 만난 게로군, 그렇지?", completion = "타우렌들은 천둥도마뱀 오와탄카를 '푸른벼락'이라고 부르지. 놈이 덩치에 어울리지 않게 빠른 속도를 가지고 있기 때문이지. 오래전에 번개가 오와탄카를 내리쳤고 그 하늘의 분노를 흡수해 이 거대한 짐승의 에너지가 한계를 초월하게 되었다고 전해지네.\n\n이제 그런 에너지가 자네의 몸에 흐르고 있어. 앞으로 나아가게. 오와탄카처럼 빠르게 말일세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n오와탄카의 신속\n\n다음과 같은 것들을 받습니다:\n\n"},
[885] = {title = "워시트 포우니", objective = "타우라조 야영지에 있는 조른 스카이시어에게 워시트 포우니의 깃털을 가져가야 합니다.", description = "워시트 포우니의 깃털에 손을 대자 고통이 느껴집니다.", progress = "자네에게서 새로운 결의가 느껴지는군. 고통으로부터 얻은 결의가...\n\n워시트 포우니를 처치한 건가?", completion = "불모의 땅에서 새끼 천둥매는 희귀한 짐승이지. 그러한 짐승의 죽음은 큰 행운이나 불행의 전조가 될 수 있네.\n\n하지만 타우라조에서 '영혼의 고통'이라고 불리는 워시트 포우니는 행운과 동시에 불행을 가져다주거나, 아무것도 아닐 수 있지.\n\n그 영혼의 고통을 사냥하면서 자네가 느낀 아픔은 큰 것을 얻기 위해 커다란 대가를 치르는 이들이라면 모두 느끼는 것일세. 아까 자네가 깃털을 만지면서 느낀 아픔은 바로 후회의 고통이지.\n\n하지만 자네는 그 모두를 이겨낸 것 같군. 후회가 지혜로 바뀌고 고통을 통해 힘을 얻게 된다는 사실을 배우지 않았는가.\n\n자네는 많은 걸 얻은 것일세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n워시트 포우니의 결의\n\n다음과 같은 것들을 받습니다:\n\n"},
[886] = {title = "불모의 땅 오아시스", objective = "크로스로드에 있는 통가 룬토템과 대화해야 합니다.", description = "썬더 블러프의 드루이드들이 멀고어 동쪽, 불모의 땅으로 흘러 들어오는 이상한 기운을 느끼고 있네.\n\n그 힘의 근원을 찾기 위해 통가 룬토템을 보냈지만 그에게 도움이 필요한 것 같네.\n\n불모의 땅에 있는 통가를 찾아가게. 그는 아마 크로스로드에 있을 걸세. 그곳으로 가려면 블러드후프 마을에서 바깥으로 이어지는 동쪽 길을 따라가다가, 불모의 땅에 들어선 후 갈림길이 나오면 북쪽 길로 계속 가게. 그러다 보면 크로스로드에 다다르게 될 거네.\n\n불모의 땅은 험난한 지역이니 길을 벗어나지 않도록 조심해야 하네.", progress = nil, completion = "썬더 블러프에 있는 나의 형제가 자네를 내게 보내 주었군. 불모의 땅의 수수께끼는 나 혼자서는 알아낼 수가 없었네.\n\n자네의 도움으로 우리의 의문에 대한 해답을 찾을 수 있으면 좋으련만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[887] = {title = "남쪽바다 해적단", objective = "톱니항에 있는 가즈로를 위해 남쪽바다 해적단 약탈자 12명과 남쪽바다 해적단 포병 6명을 처치해야 합니다.", description = "바다에 있는 우리 교역선들을 생각하면 늘 마음이 놓이지 않아. 그레즐릭 부제독님이 좀 더 안전하게 지켜줬으면 하지만... 우리 교역선에 교역 군주들이 실은 그 수많은 금을 생각하면, 해적들이 막무가내로 날뛰며 내 배에서 물건을 훔쳐가지 않을까 정말 걱정이 된단 말이지!\n\n남쪽바다 해적단이 이곳의 바로 남쪽에 기지를 건설했다는 얘기를 들었는데, 이 녀석들 때문에 항상 불안해 죽겠단 말이야. 만약 그레즐릭님께서 처리해 주지 않겠다면... 자네가 대신 좀 도와줄 수는 없겠나?", progress = nil, completion = "고맙네, 젊은 친구. 자네의 도움으로 내 걱정거리가 그나마 조금 줄어들었네. 아마 녀석들도 기지를 다른 곳으로 옮겨야겠다는 생각이 들었을 거야.\n\n이렇게 잘해주었으니, 다음엔 녀석들이 내게서 훔쳐간 물건을 되찾는 일을 맡기고 싶네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[888] = {title = "도난당한 전리품", objective = "톱니항에 있는 가즈로를 위해 장화가 든 뱃짐과 망원경 렌즈를 찾아 와야 합니다.", description = "내 물건을 모두 다 되찾고 싶지만 불가능하다는 걸 잘 알고 있네. 그래도 몇 가지 물건은 반드시 찾아야만 해!\n\n보다시피 내 관측소는 이제 가동할 준비가 거의 다 되었는데, 작은 렌즈 두 개가 더 필요하네. 하나는 듀로타에서 온 짐마차에 실려 도착했지만 다른 하나는 배에 실려 오기로 했는데 도착할 때가 훨씬 지났지. 그리고 무법항의 드리즐릭이 보낸 장화가 든 뱃짐도 아직 못 받았어.\n\n해적 야영지로 가서 내 물건들을 좀 찾아봐 주게.", progress = "내 물건들은 찾았나?", completion = "이 물건들을 찾아서 얼마나 다행인지... 도와줘서 고맙네. 자네 같은 용감한 &lt;race&gt;|1이라면;라면; 이곳에서 내 일을 도울 수 있을 것 같은데... 일자리가 필요하면 언제든지 날 찾아오게. 알다시피 나 가즈로는 보수 하나는 두둑히 주니까 말일세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n여행용 장갑솜댄 박판 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[889] = {title = "바람의 정기", objective = "뻐드렁니에게 혈석 파편 10개를 가져오면 축복을 내려 두 발이 아주 빨라지게 해주지. 얼룩말과 함께 달릴 것이고, 바람은 자네를 질투할 거야.\n\n오래 지속되지는 않겠지만 드넓은 불모의 땅을 돌아다니는 데는 충분히 도움이 될 거라고.", description = nil, progress = "뻐드렁니에게 혈석 파편 10개를 가져오면 축복을 내려 두 발이 아주 빨라지게 해주지. 얼룩말과 함께 달릴 것이고, 바람은 자네를 질투할 거야.\n\n오래 지속되지는 않겠지만 드넓은 불모의 땅을 돌아다니는 데는 충분히 도움이 될 거라고.", completion = "땅을 박차고 달려나가라. 아감마간의 영혼이 인도하시리라... &lt;race&gt;|1이여;여;, 아감마간의 마법을 더 원하거든 내게 돌아오도록.", rewards = "다음과 같은 것들을 배웁니다:\n\n바람의 정기"},
[890] = {title = "사라진 뱃짐", objective = "부두주임 디지위그에게 가즈로의 장부를 가져가야 합니다.", description = "무법항에서 보낸 마지막 뱃짐을 목이 빠져라 기다리고 있는데 아직도 안 왔어! 해적이 중간에서 가로챈 것이 분명해. 하지만 혹시 내가 모르니, 부두로 내려가 물건이 창고로 들어간 건 아닌지 디지위그에게 물어봐 주게.\n\n여기 내 장부를 줄 테니, 디지위그에게 보여주고 내 재고 기록과 그의 기록표를 대조해 보라고 전해 줘.", progress = "다음 배로 실어 보낼 짐을 가지고 온건가?", completion = "아, 가즈로가 보내서 온건가? 잠깐 기다려 보게. 혹시 가즈로의 뱃짐을 엉뚱한 곳에 보내지는 않았나 내 기록표에서 확인해 보지.\n\n내 생각에 가즈로는 드리즐릭이 보낸 장화를 기다리고 있는 거 같은데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[891] = {title = "전초기지의 대포", objective = "톱니항에 있는 선장 탈로타스 브라이트썬이 테라모어 휘장 10개를 모으고 경비대장 페어마운트, 포병 훼산, 포병 스미스를 처치해 달라고 부탁했습니다.", description = "지금 우리 함대의 또 다른 배 한 척이 북부 전초기지의 저 미치광이 인간들에게 나포되었네.\n\n저 괘씸한 놈들에게 반드시 본때를 보여 줘야 해. 놈들은 헛된 망상에 완전히 빠져 미쳐 날뛰고 있어. 시야에 들어오는 건 무조건 다 쏴버리고 있단 말일세.\n\n우리 함대를 위해 무역 해안을 따라 남쪽에 있는 전초기지로 가서 놈들을 포위해 공격하고 놈들의 휘장을 가지고 오게. 또 경비대장 페어마운트와 그녀의 미치광이 포병들을 처치해주게!", progress = "경비대장 페어마운트와 그녀의 고약한 포병들이 북부 전초기지에서 계속 포를 쏴 대며 우리 함대를 곤경에 빠뜨리고 있네. 우리도 따끔한 맛을 보여 주어야 해. 희생당한 우리 선원들에 대한 복수를 확인할 수 있도록 놈들을 처치하고 휘장을 모아 주게.", completion = "아아, 얼라이언스의 정의로운 대포들이 잠들어 버렸군. 그대의 공로에 합당한 보답을 해야겠지.\n\n다음으로는 죽은 자들의 몸을 부활시키는 조금은 섬뜩한 임무를 맡길까 하는데...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n개척자의 머스킷총해적단원 반바지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[892] = {title = "사라진 뱃짐", objective = "톱니항에 있는 가즈로에게 가즈로의 장부를 돌려주어야 합니다.", description = "내 기록표를 꼼꼼히 확인해 봤는데 실수로 다른 곳에 보낸 짐은 없네. 모두 정확해! 가즈로에게 가서 안됐지만 물건이 중간에 사라진 것 같다고 전하게. 해적들이 물건을 가로채는 일이 종종 있거든.\n\n나도 더 이상 어떻게 해 줄 수가 없군. 참... 지하광산에서 그 앞으로 온 물건이 있으니까 짬이 날 때 여기로 와서 가져가라고 전해 줘.", progress = "음, 디지위그가 뭐라고 하던가?", completion = "기록표에 없다고? 그렇다면 분명히 해적이 가로채 간 거야... 디지위그는 정직하기 때문에 이런 일로 날 속일 리가 없거든. 돈까지 받고 하는 일인데 절대 속일 리 없지...\n\n어쨌든 물건을 다시 찾아야 할 것 같은데, 자네 생각은 어떤가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[893] = {title = "최고의 무기", objective = "불모의 땅, 타우라조 야영지에 있는 테터낵 스틸포지에게 서슬갈기일족의 기습용 단검, 불타는 마법봉, 그리고 전투용 방패를 가져가야 합니다.", description = "거인의 들판 너머 남쪽 지역에 사는 서슬갈기일족 가시멧돼지 중에는 솜씨 좋은 대장장이가 없는 것으로 아는데, 최근 들어 꽤 괜찮은 무기들을 생산하기 시작했단 말이야. 가능하다면 그들의 무기를 몇 가지 살펴보고 그 기술을 배웠으면 좋겠소.\n\n호드에 충성을 바치고 싶다면 그들의 무기를 몇 개 구하여 내게 가져오시오. 서슬갈기일족 정찰꾼에게서 단검을, 점쟁이로부터 마법봉을, 그리고 광전사에게서는 방패를 구해오시오. 뭐, 그 정도면 충분할 것 같소!", progress = "미개한 서슬갈기일족이 그 정도 수준의 기술을 보유하고 있다는 사실이 믿기진 않지만, 대족장님 말씀대로 누구에게든지 배울 점이 있다면 뭐든지 배울 거요.\n\n아무리 구차한 일이라도 우리 오크족을 돕는 일이라면 발 벗고 나서야지!", completion = "훌륭하오, 참으로 훌륭한 물건들이군.\n\n생각보다 가시멧돼지들의 기술은 훨씬 더 진보한 것 같소.\n\n자, 이걸 받고 길을 떠나시오. 난 이 무기들을 좀 더 연구해야겠소. 아마도 적을 과소평가했던 실수가 지금의 참혹한 결과로 나타나는 것이 아닌지 모르겠군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n파괴의 해머영원의 등불\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[894] = {title = "사모플랜지", objective = "투자개발회사 연구 시설의 제어장치로 접근해야 합니다.\n\n제공된 아이템: \n", description = "투자개발회사가 여기서 북쪽 멀리, 그러니까 진흙늪에 있는 기름 발굴 현장의 남서쪽에 작은 연구 시설을 건설했어. 정확히 어떤 일을 하고 있는지는 잘 모르겠지만 '사모플랜지'라는 걸 가지고 실험을 하고 있다는 것만 알아냈지.\n\n그런데 대체 사모플랜지라는 게 뭔지 모르겠단 말이야. 누군가 구해다 주기만 해준다면 한번 조사해 보고 싶은데...\n\n제어장치 조작설명서를 한 부 구했으니까 사모플랜지를 어떻게 분리해내야 하는지 알 수 있을 거야.", progress = nil, completion = "제어장치의 앞면에 다양한 단추와 레버가 산만하게 배치되어 있고 불빛이 깜빡이고 있습니다. 현재 장치는 최적 수준 내에서 작동 중이며 제어 밸브가 1번에서 3번까지 열려 있음이 작은 눈금에 표시되어 있습니다. 제어판의 오른쪽 하단에 작은 열쇠 구멍이 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[895] = {title = "롱쇼어 남작 현상수배", objective = "롱쇼어 남작을 처치하고 그 증거로 그의 머리카락을 톱니항에 있는 가즈로에게 가져다주어야 합니다.", description = "현상수배!\n\n히드리스호의 선장, 롱쇼어 남작\n\n남쪽바다 해적단의 함대를 이끌고 있는 길니아스 왕국의 롱쇼어 선장을 해적질 혐의로 현상수배하는 바이다. 신원 확인이 가능한 증거가 있어야 한다!\n\n-가즈로", progress = "무슨 일인가? 내가 도와 줄 일이라도? 배에 짐을 싣고 싶나? 아니면 섬세한 기술자의 손길이 필요한가?", completion = "아! 현상수배 건을 해결했단 말이군? 사실 저 넓은 바다에서 히드리스호를 딱 한번 본 적 있었지. 굉장히 겁나는 모양의 배였지... 아니 해적선이라 해야 하나? 선원들도 아주 특이했어!\n\n어쨌든 물 위를 미끄러지듯 이동하는 모습은 정말 장관이었지. 그 배의 악명 높은 선장이 더 이상 나를 괴롭히지 못하게 됐다니 어찌 기쁘지 않겠나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[896] = {title = "광부의 행운", objective = "톱니항에 있는 부두주임 디지위그가 투자개발회사 감독이나 투자개발회사 집행자로부터 고양이눈 에메랄드를 가져다 달라고 부탁했습니다.", description = "톱니항처럼 분주한 항구의 부두주임을 맡다 보니 항상 난 정보의 흐름을 죄다 파악하고 있지. 나는 이곳과 무법항 간의 모든 상품 거래와 돈의 흐름에 정통하다네.\n\n최근 수집한 정보에 의하면 진흙늪 북동쪽에 있는 투자개발회사의 돌무더기 광산에서 한 광부가 자네의 주먹 크기만한 에메랄드를 발견했다더군. 내가 그런 물건에 관심을 보일 만한 구매자를 좀 알고 있는데... 자네가 그 에메랄드를 찾아오면 그걸 팔아 이익을 50 대 50으로 나누어 가지는게 어떻겠나?", progress = "고양이눈 에메랄드를 발견한 광부가 누군지만 알 수 있다면 일이 훨씬 수월할 텐데...", completion = "우와! 에메랄드 큰 것 좀 봐! 우린 이제 부자야! 어디 보자... 내가 지하광산의 보석 시세에 따라 자네 몫으로 반을 떼어 줄 테니 걱정 말라고!\n\n그럼 어디 볼까? 음... 이 정도가 적당할 것 같은데... 자네와 함께 일하게 되어 즐거웠네.", rewards = "다음과 같은 것들을 받습니다:\n\n동전 주머니"},
[897] = {title = "여왕 실리시드", objective = "조른 스카이시어에게 여왕 실리시드의 머리를 가져다주어야 합니다.", description = "벌레같이 생긴 이 이상한 생명체는 자연계의 생물이 아닌 것으로 보이며 불모의 땅의 생태계에 속하지 않습니다.", progress = "문제가 있는 것처럼 보이는군. 불모의 땅에서의 훈련은 어떻게 돼 가나? 뭔가 골치 아픈 일이라도 생긴 건가?", completion = "이 짐승의 특성에 대해서는 전혀 알 수가 없군. 이미 영혼이 육체를 떠났으니 말일세. 하지만 자네의 추측 대로 이건 불모의 땅의 생태계에 속하는 것이 아니야. 우리 타우렌의 어두운 미래를 암시하는 건 아닌가 우려되는군...\n\n하지만 지금은 방비를 해 놓고 기다리는 수밖에 없지. 시간이 지나면 이 생명체의 비밀이 밝혀질 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[898] = {title = "요새 탈출", objective = "길사레즈 파이어바우를 톱니항에 있는 브라이트썬 선장에게 데려가야 합니다.", description = "아! 드디어 날 구하러 왔군!\n\n저 수많은 경비병들을 따돌릴 수 있는 자는 없을 줄 알았소. 테라모어에서 온 저 광신도들은 정말 미치광이들이오. 우리 배를 침몰시키고 유일한 생존자인 나를 이곳에 가뒀지. 나를 얼라이언스를 위협하는 적으로 취급하면서 말이오.\n\n톱니항과 무법항 간에 밀주를 실어 나르는 배의 선원일 뿐인 내가 얼라이언스에 위협이 된다고? 말도 안 되는 소리...\n\n쓸데 없는 말을 너무 많이 한 것 같군. 톱니항으로 돌아가도록 도와주시오. 준비가 되면 함께 빠져나갑시다.", progress = "무슨 일이지?", completion = "파이어바우는 이미 오래전에 죽었다고 생각했었는데!\n\n자네의 이 영웅적인 활약은 탈로단 선원들의 존경을 받기에 충분하네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n버클 장화리벳 건틀릿\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[899] = {title = "타오르는 증오", objective = "크로스로드에 있는 만크릭에게 뾰족털 가시멧돼지 어금니 60개를 가져가야 합니다.", description = "당신이 이 고통스러운 마음을 이해할지 모르겠지만, 이건 알아두시오. 난 매일 이곳에서 해가 뜰 때부터 질 때까지 야수들을 찾아 헤매고 있소.\n\n지금까지 가시멧돼지들을 만나는 족족 처치했지만 그래도 성이 차지 않는구려. 차라리 크로스로드로 오지 말고 타우라조로 가야 했는데 후회 막심이오.\n\n당신이 나를 좀 도와주시오. 놈들을 가능한 많이 처치해 주시오. 그리고 그 어금니를 가지고 와 용맹스러운 사냥을 함께 축하했으면 하오.", progress = "가시멧돼지 놈들은 반드시 그 대가를 치러야 하오.", completion = "내 부탁을 들어 주어 고맙소.\n\n아직 복수는 끝나지 않았지만 사악한 가시멧돼지 놈들에게 고통을 안겨 준 것은 내게 큰 위안이 될 것 같군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n멧돼지 사냥꾼의 단망토초원의 장식띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[900] = {title = "사모플랜지", objective = "연료 제어 밸브, 압력 조절 밸브, 주제어 밸브를 잠근 다음 제어장치로 돌아가십시오.", description = "현재 세 개의 제어 밸브가 열려 있습니다. 제어판의 눈금을 살펴본 결과 제어 밸브를 모두 잠가야 제어장치를 끌 수 있을 것 같습니다.", progress = "제어장치가 깜빡 거리고 있습니다. 주제어 밸브가 아직 잠기지 않은 것입니다.", completion = "세 개의 제어 밸브가 닫히면서 제어판의 녹색 불빛이 천천히 노란색으로 바뀌면서 불빛이 희미해집니다. 이제 장치를 제어하는 스위치를 움직일 수 있게 됩니다. 밸브가 완전히 닫혔으므로 장치를 끌 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[901] = {title = "사모플랜지", objective = "땜장이 스니글즈에게서 제어장치 열쇠를 구해야 합니다.", description = "제어장치가 완전히 꺼졌으므로 제어판을 연 다음 사모플랜지를 꺼낼 수 있습니다. 이제 다른 것은 필요 없고 열쇠만 구하면 됩니다.", progress = "제어장치의 불빛이 희미해지고 모든 눈금과 다이얼이 0을 가리킵니다. 작동을 멈춘 것입니다.", completion = "열쇠를 꽂고 돌리자 제어장치가 열립니다. 제어장치 맨 위의 빨간색 불빛이 꺼지고 본체에서 모든 에너지가 빠져나갑니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[902] = {title = "사모플랜지", objective = "톱니항에 있는 스퍼터밸브에게 사모플랜지를 가져가야 합니다.", description = "제어장치의 덮개를 열자 전선과 이상한 관, 기타 기계 부품들이 복잡하게 얽혀 있습니다. 하지만 대부분이 실제로는 별다른 용도가 없는 것 같습니다. 부품들을 헤집고 제어장치의 안으로 팔을 깊숙이 넣자 사모플랜지가 있습니다. 그것을 잡아 당겨 장치에서 빼냅니다.", progress = "오, 돌아왔군! 사모플랜지는 가져왔나?", completion = "이건... 정말이지 흥미롭군. 그래, 이걸 지하광산에 있는 땜장이 조합 본부에 보내야겠어! 그들이라면 이 물건에 대해 뭔가 알아낼 수 있을 거야.\n\n하지만 우선은 내가 잠시 살펴봐야 할 것 같군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n기술자의 망치이어붙인 방패\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[903] = {title = "불모의 땅의 굶주린 사자", objective = "불모의 땅의 굶주린 사바나 사자에게서 굶주린 사자의 발톱 7개를 모아 크로스로드에 있는 셀그라 다크쏜에게 돌아가십시오.", description = "이제 진짜 센 놈들을 상대할 때가 된 것 같군. 불모의 땅을 어슬링거리는 굶주린 사자들이 좋겠어. 강하면서도 교활하고 날카로운 놈들이지. 크로스로드 남서쪽으로 가면 많이 있을 거야. 넓은 풀숲 근처를 주로 돌아다고 있지.\n\n자칫 방심하다간 사냥하러 나갔다가 먹이가 될 수도 있으니까 놈들을 상대할 땐 조심하도록 해.", progress = "사냥은 어떻게 되어가나? 굶주린 사자들을 발견했나?", completion = "수고했어, 풀숲에 숨어 굶주린 사자들을 사냥하느라 바빴겠군. 자, 이젠 사자들의 우두머리를 상대할 차례로군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[905] = {title = "성난 갈퀴발톱 열대초원랩터", objective = "열대초원랩터를 처치하고 그들의 깃털을 모아야 합니다. 이 깃털을 열대초원랩터 둥지 3개에 사용한 다음 크로스로드에 있는 셀그라 다크쏜에게 돌아가십시오.", description = "사냥이 점점 흥미로워지고 있군. 이번엔 사냥감들을 물리쳐야 할 뿐만 아니라 놈들의 소굴까지 들어가야 해.\n\n남쪽으로 가서 열대초원랩터들을 처치하고 그들의 깃털을 벗기도록 해. 그런 다음 그 깃털들을 죽은 오아시스 근처에 있는 열대초원랩터 둥지에 올려놓도록. 랩터 무리에게 당신이 그들을 무서워하지 않는다는 걸 보여줘.", progress = nil, completion = "둥지에 깃털을 올려놓았군그래. 꽤 용기가 필요한 일이었을 거야.\n\n스스로 조금씩 용감해지고 있다는 게 느껴지나? 내가 보기엔 처음 여기 왔을 때보다 확실히 강해 보이는군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[906] = {title = "내부의 배반자", objective = "불모의 땅, 크로스로드에 있는 톨크에게 로크의 해골을 가져가야 합니다.", description = "<race>, 로크의 해골을 크로스로드에 있는 톨크에게 가지고 가게. <킁킁> 그러면 아무 말 안 해도, 우리 일족에게 어떤 일이 일어났는지 대강 알아차릴 거야. 뻐드렁니가 이런 일을 했다는 건 믿지 않겠지만... <킁> 자네가 이렇게 큰 일을 도운 걸 알면 보답을 할 거야. <킁킁>\n\n뻐드렁니가 이 안에서 살아 있는 한 아감마간님께서 자네에게 능력을 주시길 기도하겠네. 다시 만날 때까지 안녕...", progress = "무슨 일인가?", completion = "자네 혼자 서슬갈기일족의 우두머리들을 처치했단 말인가? 놀라워... 정말 할 말을 잃게 만드는군.\n\n무엇보다 먼저 고맙다는 말을 해야겠네. 크로스로드 주민들은 모두 그 용기에 존경을 표할 것이네.\n\n난 어리석게도 다른 가시멧돼지가 우리 보급로 습격을 지휘한다고 생각하고 있었으니, 내 실수를 인정해야겠군. 다시 한번 감사하네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n나무껍질 튜닉마른 이끼 튜닉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[907] = {title = "분노한 천둥도마뱀", objective = "천둥도마뱀 피 3개를 모아 타우라조 야영지에 있는 조른 스카이시어에게 가져다주어야 합니다.", description = "자, 이젠 천둥도마뱀을 상대할 차례야. 몸집이 하도 커서 놈들이 평원을 한발한발 걸을 때면 지축이 흔들리는 소리가 나곤 하지. 놈들을 상대할 땐 조심해야 하네. 한 발짝이라도 잘못 디뎠다간 밟혀버리는 수가 있거든.\n\n천둥도마뱀들은 불모의 땅 남쪽에 있다네. 천둥뿔도마뱀, 폭풍도마뱀, 그리고 천둥꼬리도마뱀들이 모두 천둥도마뱀과라고 알려져 있네. 놈들을 처치하고 내게 돌아오게.", progress = "천둥뿔도마뱀 피가 든 약병을 가지고 왔나? 모두 세 병이 필요하네.", completion = "자네가 승리의 증거를 가지고 돌아온 걸 보니 반갑군. 게다가 상처 하나 없이 무사히 돌아왔으니 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[908] = {title = "폐허 사이로", objective = "심연의 핵을 잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 가져가십시오.", description = "황혼의망치단은 검은심연의 나락에 있는 달의 제단 폐허로 이동했소. 그들로 인해 그곳의 정령들도 우리에게 반기를 들고 있소. 아무 것도 하지 않으면 이 지역이 영원히 그들의 손아귀에 들어가게 될 것이오.\n\n검은심연에서 심연의 돌을 찾으시오. 아마 물 가까이에 있을 것이오. 제대로 읽어내기가 쉽진 않겠지만 심연의 돌에는 모든 정령들의 역사와 관련된 심연의 핵이 들어 있소. 내게 그걸 가져오면 속세의 고리회의 힘을 빌어 황혼의망치단을 저지할 수 있을 게요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[913] = {title = "천둥매의 울음 소리", objective = "천둥매를 찾아 처치하고 천둥매 날개를 타우라조 야영지에 있는 조른 스카이시어에게 가져가야 합니다.", description = "천둥매는 위험한 맹금들이지. 이제 자네가 그들을 상대할 때가 됐군. 그들이 주로 다니는 곳을 찾아가 처치한 다음 내게 사냥의 증거를 가져오게.\n\n내가 부탁하는 마지막 사냥이 될 테니 잘해주게나.", progress = "천둥매는 처치한 건가?", completion = "천둥매들을 처치해낸 자네가 스스로도 자랑스러울 게야. 지금까지 내 부탁대로 모든 적들을 훌륭히 소화해냈고, 힘과 용기, 그리고 명예를 내게 충분히 보여줬네.\n\n하지만 자네의 갈 길은 아직 끝나지 않았어. 진정한 &lt;race&gt;|1이라면;라면; 지금 보여준 것과 같은 자신감으로 끝까지 자신의 길을 가야지.\n\n자, 이젠 길을 떠날 시간일세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n코발트 버클러바람기수의 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n청월 장갑"},
[914] = {title = "송곳니의 드루이드 우두머리", objective = "코브란, 아나콘드라, 피타스, 서펜티스의 보석을 모아 썬더 블러프에 있는 나라 와일드메인에게 돌아가야 합니다.", description = "통곡의 동굴에 있는 송곳니의 드루이드들은 미쳐버렸습니다. 처음에는 불모의 땅을 치유하려던 드루이드 귀족이었지만, 지금은 자신들의 비뚤어진 야망을 채우기 위해 이 땅의 판을 새로 짜려하고 있습니다.\n\n송곳니의 드루이드들은 4명의 지도자가 이끌고 있으며, 각기 꿈의 보석을 지니고 있습니다. 꿈에서 본 그들의 얼굴이 지금도 생생합니다! 그들을 처치하고 꿈의 보석을 제게 가져오면 불모의 땅에 다시금 평화를 가져올 수 있을 겁니다.\n\n통곡의 동굴 깊은 곳으로 가세요. 그들을 발견할 수 있을 겁니다. 어서 떠나세요.", progress = "생생한 악몽의 기억이 절 괴롭히고 있습니다. 송곳니의 우두머리들을 처치하고 보석들을 가져왔나요?", completion = "해냈군요. 당신이 송곳니의 드루이드 지도자들을 처치했어요. 이제 그 사악한 얼굴들이 나타나는 악몽에서 해방이에요. 당신이 불모의 땅의 앞날에 저주가 내리는 것을 막아준 겁니다.\n\n고맙습니다. 저와 썬더 블러프의 드루이드들, 그리고 이 땅을 위해 힘 써줘서 정말 고맙습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n초승달 지팡이날개검\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[916] = {title = "나무그물거미의 독", objective = "알드랏실에 있는 길스할란 윈드워커에게 나무그물거미의 독주머니 10개를 가져가야 합니다.", description = "난 그늘 거미굴에 서식하는 나무그물거미를 관찰하기 위해 그늘 협곡에 왔소. 거미류 중에서도 아주 큰 종이지. 난 세계수가 놈들에게 뭔가 큰 영향을 미쳤다고 생각하오. 표본을 채취해 내 가설이 맞는지 확인하고 싶소.\n\n그러자면 먼저 나무그물거미의 독이 좀 필요하지. 북쪽에 있는 그늘 거미굴 주변과 내부에 있는 거미들에게서 나무그물거미의 독주머니를 모아 주시오. 그러면 그들의 사촌 뻘 되는 작은 종의 거미들과 비교할 수 있을 거요.", progress = "독주머니는 가져왔소?", completion = "고맙소. 다르나서스로 돌아가 이 독주머니와 다른 거미의 독을 비교해 볼 참이오. 생태계의 변화는 최근 나무가지를 상상할 수 없을 만큼 멀리까지 드리우고 있는 세계수와 분명 어떤 관련이 있을 거요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n엉겅퀴나무 마울엉겅퀴나무 단검엉겅퀴나무 지팡이엉겅퀴나무 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[917] = {title = "나무그물거미의 알", objective = "알드랏실에 있는 길스할란에게 나무그물거미알을 가져가야 합니다.", description = "거미의 독도 구했으니 이제 살아 있는 표본이 필요하오. 거대한 거미를 산 채로 잡아다 달라는 무리한 부탁을 하지는 않겠소이다. 젊은 <class>, 그렇다고 늙은 내가 직접 그 거대한 놈을 상대할 수도 없는 노릇이니...\n\n하지만 아직 부화하지 않은 거미 알을 찾을 수 있다면 훨씬 쉽게 표본을 손에 넣을 수 있을 거요. 부화하지 않은 거미라면 안전하게 가둘 수도 있을 것이고...\n\n그늘 거미굴로 깊숙이 들어 가면 그들의 둥지가 있을 거요. 둥지에서 알을 찾아 내게 가져다주시오.", progress = "그늘 거미굴 안으로 들어가 보았소? 거미 알은 찾았소?", completion = "오, 훌륭하오. 먼저 이 알과 독을 다르나서스로 보낸 후 이곳의 연구를 신속히 끝내고 나도 돌아가도록 할 것이오. 이 표본에서 중요한 발견을 할 수 있어야 할 텐데 말이오. &lt;name&gt;, 그대의 도움이 컸소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n어둠숲의 방패어둠숲의 튜닉어둠숲의 로브\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[918] = {title = "나무괴물 씨앗", objective = "알아메스 호수에 있는데날란에게 나무괴물 씨앗 8개를 가져가야 합니다.", description = "텔드랏실의 나무괴물들은 자연의 정령이오. 어떤 면에서 이 나무괴물은 우리 생태계의 동식물에 대한 자연의 질서를 반영하고 있소. 그러니 이러한 나무괴물들이 사나워졌다는 것은 우려할 만한 일이 아닐 수 없소.\n\n난 토양에 무언가 문제가 있다고 믿고 있소. 그래서 여러 가지 방법으로 식물을 재배해 보고 그 결과를 나무괴물 씨앗에도 적용해 보고 싶소. 그러니 그대가 알아메스 호수 주위의 나무괴물들에게서 씨앗을 모아서 내게 좀 가져다주시겠소?", progress = "씨앗은 가져왔소? 어서 그것들을 심어보고 싶소.", completion = "가져왔구려. 훌륭하오!\n\n이 씨앗을 내가 준비해둔 특수한 토양에서 재배해 볼 생각이오. 그러면 아마 훨씬 순한 나무괴물이 자라날 거요. 그대도 나중에 그 결과를 볼 수 있을 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n숲버섯"},
[919] = {title = "나무괴물 씨눈", objective = "알아메스 호수에 있는 데날란에게 나무괴물 씨눈 12개를 가져가야 합니다.", description = "작은 나무괴물들이 알아메스 호수 주변에 자라고 있소. 이 씨눈들이 우리가 손쓸 수 없을 정도로 오염된 것 같아 걱정스럽소. 문제의 소지가 되기 전에 그 땅에서 씨눈들을 제거해야 하오.\n\n호숫가를 지나다가 나무괴물 씨눈을 발견하면 모두 가져다주시오. 우리의 영토가 깨끗하게 유지될 수 있도록 도와주시오!", progress = "그래, 물가에서 나무괴물 씨눈들을 발견했소?", completion = "많이도 가져왔구려! 이 씨눈들이 무서운 속도로 퍼지고 있는 건 아닌지 걱정이오. 나무괴물을 오염시킨 원인이 무엇인지 밝혀낸다면 좋으련만...\n\n도와줘서 고맙소. 그대 덕분에 이 땅이 좀 더 깨끗해졌소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n정원사 장갑회암석 팔보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[920] = {title = "테나론의 부름", objective = "그늘 협곡, 알드랏실 꼭대기에 있는 테나론 스톰그립과 대화하십시오.", description = "그대 이름이 <name> 맞소? 테나론이 찾고 있다고 들었소. 알드랏실 꼭대기, 가장 높은 곳에 있는 방으로 가면 그를 만날 수 있을 거요.\n\n비록 우리의 수명이 길긴 하지만 그를 너무 오래 기다리게 하지 않는 것이 좋을 거요.", progress = nil, completion = "&lt;name&gt;, 그대가 내 부름에 속히 응해 주기를 기다리고 있었습니다. 그대에게 맡길 중요한 임무가 있소만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[921] = {title = "대지의 왕관", objective = "수정 약병에 물을 채워서 알드랏실 꼭대기에 있는 테나론 스톰그립에게 돌아오십시오.", description = "<name>, 이제 그대도 자신의 운명을 찾아 나설 때가 되었소. 하지만 축복받은 우리의 숲을 넘어 미지의 세계로 떠나기 전에 최근의 역사에 대해 알아 두어야 할 것이 많이 있소.\n\n하이잘 산에서의 전투 이후로 우리에겐 많은 변화가 있었소. 놀드랏실은 예전처럼 그 어스레한 그림자를 드리우고 있고, 그 힘은 아키몬드를 물리치고 불타는 군단을 몰아내는데 사용되고 있다오.\n\n우선 그대에게 맡길 임무가 하나 있소. 알드랏실 북쪽에 있는 달샘으로 가서 물을 한 병 담아 와 주시오.", progress = "달샘의 물은 사실 영원의 샘에서 온 것입니다. 그 샘은 우리 세계에 수많은 비극을 불러왔던 고대 마법의 원천이지요.\n\n드루이드들은 그 물의 특성을 이용하고 있고 센티널에서는 그 샘을 엘룬의 제단으로 신성시하고 있지만, 그 물 안에 담긴 마법은 아직 그 누구에게도 알려지지 않았소.", completion = "그대는 하이잘 산에서의 전투 이후의 역사의 첫 부분만 조금 들었을 뿐이오. 앞으로 텔드랏실을 통과해 다르나서스로 들어가는 여정 동안 계속해서 얼라이언스를 위한 임무를 수행하고 지난 영웅들의 이야기에 귀를 기울여야 할 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[922] = {title = "레엘리안 그린스파이어", objective = "다르나서스에 있는 레엘리안 그린스파이어에게 나무괴물 씨앗을 가져가야 합니다.", description = "그대가 가져온 이 씨앗 중 하나를 레엘리안 그린스파이어라는 내 친구에게 좀 전해 줄 수 있겠소? 그는 다르나서스에 살고 있는 드루이드인데, 지난번 그 친구와 얘기를 나누었을 때 나무괴물에 대한 내 연구에 관심을 보였소. 그도 나름대로 아이디어가 있을 테니 연구에 필요한 씨앗 표본을 갖다준다면 기뻐할 거요.\n\n고맙소. 그대는 지금까지 내게 큰 도움이 되었소. 언젠가 그대도 내 연구의 결실을 보게 되길 바라오.\n\n레엘리안은 다르나서스에 있는 세나리온 자치령 오솔길로 가면 찾을 수 있을 것이오.", progress = "안녕하시오, 내가 도울 일이라도 있소?", completion = "아, 나무괴물 씨앗이라고 했소? 데날란의 연구를 돕기 위해 한번 재배해 보고 싶었는데...\n\n하지만 많은 나무괴물에게서 오염 징후가 확산되고 있어 그 씨앗도 오염된 채로 자라나지 않을까 우려되오. 내 능력으로는 오염된 나무괴물을 치료할 방도가 없소.\n\n데날란은 식물 재배에 아주 능하오. 그라면 앞으로 자라날 나무괴물을 치유할 방법을 찾아낼 수 있을 거요. 그가 유일한 희망인 셈이지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[923] = {title = "종양", objective = "다르나서스에 있는 레엘리안 그린스파이어에게 이끼 낀 종양 5개를 가져가야 합니다.", description = "나무괴물에서 사악한 악의 기운이 자라나고 있소. 나는 지금 그 근원을 조사하는 중이오. 이것이 밝혀질 때까지 텔드랏실의 안전을 위해 오염된 나무괴물들을 처치해야 하오. 텔드랏실 북부 지역에 있는 생명의 호수 주위를 어슬렁거리는 놈들이 가장 심하게 오염된 것 같은데 우선 그놈들을 제거하는 것이 좋을 것 같소.\n\n그 지역에서 발견되는 나무괴물들을 처치하고 놈들에게서 자라고 있는 이끼 낀 종양을 모아 오도록 하시오. 내게 가져오면 태워버리도록 하겠소.", progress = "생명의 호수에는 다녀온 거요? 나무괴물들을 처치했소?", completion = "수고했소. 나무괴물들이 감염된 질병에 걸리면 이런 종양이 돋아나는 증상이 생긴다오. 이 종양에 가득 찬 독이 우리의 새 영토에 퍼지기 전에 어서 이 종양들을 태워 버려야겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n정원사의 나이프"},
[924] = {title = "악마의 씨앗", objective = "우선 혼란의 마법석을 손에 넣으십시오. 마법석의 힘이 다하기 전에 불의 제단에 가져다 놓은 후 아크젤로스에게 돌아가십시오.", description = "악마의 씨앗은 불타는 군단이 사용하는 강력한 도구요. 그 씨앗은 공포의 안개봉우리의 동굴에 있는 악마의 불제단 위에 놓여 있소.\n\n이 앞 탁자 위에 내가 준비해 놓은 마법석을 가지고 가야 하오. 악마의 씨앗 근처에 가져다 놓으면 불타는 군단과의 연결이 끊어지면서 파괴될 거요.\n\n자, 공포의 안개봉우리에 있는 불의 제단으로 가시오. 서쪽으로 가다가 길이 갈라지는 곳에서 북쪽으로 가면 되오. 그러면 왼쪽에 공포의 안개봉우리가 보일 것이오. 가장 안전한 북쪽 면을 타고 꼭대기까지 올라가도록 하시오.\n\n시간이 지날수록 마법석의 힘이 점점 약해지니 서두르는 게 좋을거요.", progress = "악마의 씨앗이 아직도 존재하고 있어. 난 그 힘을 느낄 수 있지...", completion = "당신의 임무는 끝났소. 네루님의 소망대로 악마의 씨앗을 파괴했지만 이게 끝은 아니오.\n\n악마의 씨앗이 파괴될 때 강력한 힘이 파동을 일으키며 공중으로 날아가는 걸 보았겠지... 나도 그걸 느낄 수 있었으니 분명 다른 자들도 느꼈을 거요. 그 중에는 그 악마의 씨앗을 창조한 자들도 있겠지...\n\n하지만 악마의 씨앗을 다시 만든다고 해도 그건 나중에 걱정할 문제이고... 지금은 당신에게 줄 것이 있소. 네루님께서 이걸 상으로 보내 왔소. 고맙다는 말과 함께 전해 달라고 하더군.\n\n정말 고맙소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n밴시 갑옷"},
[926] = {title = "혼란의 마법석", objective = "마법의 힘이 깃들어 있는 이 마법석은 누군가 의도적으로 부여한 결함을 가지고 있습니다. 이 마법석은 매우 불안정하여 제단을 벗어나면 급속도로 힘이 약해집니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n혼란의 마법석"},
[927] = {title = "이끼로 덮인 심장", objective = "이끼로 덮인 심장을 알아메스 호수에 있는 데날란에게 가져가야 합니다.", description = "악취나는 검은이끼괴물의 심장은 검은 색의 끈적한 이끼에 묻혀 있습니다. 느리지만 일정한 박동이 느껴지는 것으로 보아 이것이 심장이라는 것을 알 수 있을 뿐입니다. 심장의 박동은 지금까지도 멎지 않고 있습니다.\n\n데날란이 이 심장을 보고 싶어할이지도 모릅니다.", progress = "내게 뭔가 보여줄 거라도 있소?", completion = "이게 뭐요? 나무괴물 심장? 온통 더러운 이끼로 덮여 있군!\n\n운이 좋으면 이 심장을 조사해 이 이끼의 특성을 알아낼 수 있을 것이오. 내게 이걸 가져다주어서 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[928] = {title = "대지의 왕관", objective = "돌라나르에 있는 코리드라스 문레이지에게 반쯤 찬 유리병을 가져가십시오.", description = "달샘과 텔드랏실에 대해 들려 줄 이야기가 더 있긴 하지만, 이제 그대를 보내야 하오. 코리드라스 문레이지가 그대를 기다리고 있을 거요. 그대가 채워온 약병에 든 물을 이 유리병에 옮겨 담아놓았소.\n\n돌라나르에 있는 달샘 근처에서 코리드라스를 찾도록 하시오. 그늘 협곡 외곽에 있는 이곳 알드랏실에서 남쪽으로 이어진 조약돌 길을 따라가다가 길이 서쪽으로 향해도 계속해서 숲길을 따라 남쪽으로 가면 돌라나르에 도착할 거요.\n\n길을 잘 따라가야 하오. 근래 들어 숲에 위험한 짐승들이 자주 출몰하고 있소이다.", progress = "어서 오시오, <class>. 무슨 일로 이렇게 날 찾아왔는지 말해 주시겠소?", completion = "아, 알겠소. 테나론이 그대를 보냈군. 그렇다면 할 이야기도 많고 착수해야 할 일들도 많은데... 시간이 별로 없소.\n\n어서 시작하는 게 좋겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[929] = {title = "대지의 왕관", objective = "비취 약병을 채운 다음 돌라나르에 있는 코리드라스 문레이지에게 가져가야 합니다.", description = "그대가 우선적으로 완수해야 할 임무에 대해 말씀드리리다. 다르나서스의 드루이드들은 텔드랏실에 있는 달샘의 물을 사용하고 있소. 그 달샘은 때때로 보충해 주어야 하오. 특별히 제작된 이 약병을 사용하면 달샘의 물을 모을 수 있소.\n\n이 병을 가지고 동쪽의 별바람 마을 외곽에 있는 달샘으로 가서 물을 채운 다음 내게 가져오면 되오. 이 임무를 완수하면 테나론이 그대에게 미처 해주지 못한 얘기를 계속 해드리겠소.", progress = "다시 만나 반갑소, <name>. 임무는 완수했소?", completion = "하이잘 산의 전투 이후 우리는 갈 곳을 잃고 정처 없이 떠도는 신세가 되었소. 놀드랏실은 전투로 불타 버리고 우리는 불사의 생명을 잃고 말았소.\n\n이 혼란한 시기를 틈타 배신자가 감옥에서 탈출하고 샨도 스톰레이지는 사라지고 말았지. 실로 모두에게 암울한 시기요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[930] = {title = "빛나는 과일", objective = "알아메스 호수에 있는 데날란에게 빛나는 과일을 가져가야 합니다.", description = "이 빛나는 식물의 널찍한 잎 아래 크고 둥근 과일이 달려 있습니다.\n\n데날란이 이 과일을 연구하고 싶어할 것이 분명합니다.", progress = "내게 무슨 할 말이라도 있는 것 같소. 나무괴물에 관한 새로운 소식이라도 있는 거요?", completion = "이걸 텔드랏실에서 발견했단 말이오? 흥미롭군... 이 과일은 외부에서 온 종인 것 같소. 아마 먼 곳에서 씨앗이 흘러 들어온 모양이군. 저 먼 동부 왕국에서 왔을지도 모를 일이지. 그리고 이 과일엔 뭔가 특별한 점이 있소. 텔드랏실의 흙에 아주 이상하게 반응하는 것 같소.\n\n아무튼 고맙소. 이제 난 이 과일을 좀 더 연구해 봐야겠는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[931] = {title = "희미하게 빛나는 잎", objective = "알아메스 호수에 있는 데날란에게 희미하게 빛나는 잎을 가져가야 합니다.", description = "이 식물의 잎은 숲 속의 빛을 받아 희미하게 빛나며 고동치는 듯한 기운을 발합니다.\n\n데날란이 이 식물의 표본을 원할 것입니다.", progress = "내게 무슨 볼일이라도 있소?", completion = "이걸 어디서 발견했소? 수십 년 전 슬픔의 늪에 머물던 때 이후 이런 식물은 본 적이 없소. 이 식물이 어떻게 텔드랏실까지 흘러 들어와 그렇게 크게 자랐는지 놀라울 따름이오.\n\n고맙소. 자, 난 이제 이 잎에 한 가지 실험을 해봐야겠으니 괜찮다면 이만 실례하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[932] = {title = "뒤틀린 증오", objective = "제왕 멜레나스를 처치한 다음 돌라나르에 있는 탈론카이 스위프트루트에게 멜레나스의 머리띠를 가져가야 합니다.", description = "그대에게 알려줘야 할 것이 있소, 이 문제는 우리 둘만의 비밀로 해야 하오. 사티로스들은 이미 우리에겐 상당한 골칫거리지만 이번 건은 특히 문제요.\n\n제왕 멜레나스라는 사티로스가 있는데 그는 상당수의 그렐족 병사들을 모아서 악마 바위굴 근처에서 지내고 있소. 그의 사악함은 칠흑 같은 저 어둠에도 비할 바가 아니며 가장 음흉하고 더러운 음모만 획책하는 자요.\n\n북쪽에 있는 동굴에서 놈을 찾아 처치한 다음 녀석의 머리띠를 가져다주시오.", progress = "멜레나스를 처치했소? 그를 신속하고 조용하게 처리하는 일은 매우 중요하오. 그가 존재하는 한 우리에게 큰 골칫거리가 될 테니 말이오.", completion = "제왕 멜레나스를 처치했으니 이제 나도 다른 일들을 처리할 수 있겠군. 고맙소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n야생의 팔보호구덩굴 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[933] = {title = "대지의 왕관", objective = "전기석 약병을 채운 다음 돌라나르에 있는 코리드라스 문레이지에게 가져가야 합니다.", description = "다르나서스 입구 남동쪽의 아리스리엔 연못 근처에 또 다른 달샘이 있소. 센티널에서는 나무옹이일족 펄볼그들의 공격과 횡포로 이 지역 정찰에 어려움을 느끼고 있소.\n\n달샘을 찾는 동안 항상 무기를 사용할 태세를 갖추도록 해야 할 것이오.", progress = "처음에 펄볼그들의 공격에 대한 보고는 완전히 무시됐었소. 그 평화를 사랑하고 온순했던 종족이 미치광이로 돌변할 수 있다고 누가 생각이나 했겠소? 또한 우리의 새 보금자리인 이곳 돌라나르에는 그밖에도 우리를 괴롭히는 문제가 산적해 있으니...", completion = "샨도 스톰레이지는 결국 돌아오지 않았고 드루이드들은 혼란에 빠지고 말았소. 그리고 지금까지도 우리는 그에게 무슨 일이 생긴 건지 모르고 있소. 말퓨리온이 사라지고 나서, 대드루이드 판드랄 스테그헬름께서는 어둠의 해안 고대 의회에서 지금이야말로 종족을 재건하고 불사의 생명을 되찾을 때라고 설득하셨소. 그때부터 그분이 드루이드를 지휘하게 되었소.\n\n스테그헬름께서는 의회의 승인 하에 가장 강한 드루이드들의 힘을 모아 세계수, 텔드랏실을 새로이 키워오신 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[934] = {title = "대지의 왕관", objective = "자수정 약병을 채운 다음 돌라나르에 있는 코리드라스 문레이지에게 가져가야 합니다.", description = "하지만 텔드랏실은 모든 면에서 문제가 많았소. 세계수에 대한 스테그헬름님의 신중한 계획은 그분이 바라는 대로 실행됐지만 작은 문제가 있었소. 그리고 그 문제로 인해 텔드랏실에 또 다른 문제들이 꼬리를 물고 발생하게 된 것이오.\n\n지금은 다른 문제들은 제쳐 두겠소. 우선 그대는 북서쪽 신탁의 숲에 위치한 마지막 달샘으로 가도록 하시오. 신탁의 나무 가지 아래 우리의 최초의 달샘이자 가장 강력한 샘이 하나 있소. 그 물을 이 약병에 담아 내게 가져오시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[935] = {title = "대지의 왕관", objective = "다르나서스에 있는 대드루이드 판드랄 스테그헬름에게 가득 찬 유리병을 가져가야 합니다.", description = "생명의 어머니 알렉스트라자와 시간의 지배자 노즈도르무의 축복을 받지 못한 텔드랏실은 불안정한 상태로 성장할 수밖에 없었소. 나무 뿌리 밑으로부터 기괴한 짐승들이 올라오고 미쳐버린 펄볼그들은 이곳을 지나가는 여행자들을 공격하고 있소.\n\n나로서는 이곳에서 대드루이드님이 찾고 계신 해결책이 빨리 나타나기를 바라는 수밖에 없지만... 그대가 가져온 달샘의 물을 다르나서스로 가져갈 수 있도록 모두 이 병에 옮겨 담겠소.\n\n이걸 드루이드 숲에 계시는 판드랄 스테그헬름께 가져가도록 하시오.", progress = "부르지도 않았는데 도대체 왜 내게 와서 말을 거는지 모르겠군.\n\n내게 무슨 볼일이 있는 거라면 빨리 말하도록 하게.", completion = "아, 그래. 내가 요청한 그 샘물이군. 흠, 테나론과 코리드라스가 이렇게 늦게 보낸 걸 보면 지금까지 일을 맡은 자들이 모두 시원찮았던 건지...\n\n어쨌든 이제야 내 본연의 일로 돌아갈 수 있겠군. 텔드랏실이 겪고 있는 모든 문제들이 내 어깨를 짓누르고 있다네. 하루 빨리 벗어 버리고 싶은 멍에와도 같지.\n\n이걸 받도록 하게. 쓸모가 있을 걸세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n잿빛나무 활덤불 망치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[936] = {title = "대드루이드 룬토템 돕기", objective = "썬더 블러프에 있는 대드루이드 하뮬 룬토템과 대화해야 합니다.", description = "손님, 괜찮으시다면 잠시만 시간을 내주시겠습니까?\n\n썬더 블러프의 세나리온 의회에서는 아주 중요한 조사 작업 때문에 당신처럼 노련한 모험가들을 찾고 있다고 합니다. 자세한 내용은 모르지만 이 연구 조사를 다름 아닌 하뮬 룬토템님께서 직접 지휘하고 있다는 것만은 자신 있게 말씀드릴 수 있습니다.\n\n혹시 관심이 있으시다면 썬더 블러프에 있는 장로의 봉우리에서 그분과 직접 얘기를 나눠 보십시오.", progress = nil, completion = "어서 오게. 우리 연구를 돕는 데 관심을 가져 줘서 기쁘군. 할 일이 많다네. 별로 위험하지 않은 일이라고 하면 거짓말이 될 테고... 그대가 겁부터 먹고 도망가지는 않았으면 좋겠군. 하지만 그대의 모습을 보아하니 이 정도 일쯤은 많이 해봤을 것 같군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[937] = {title = "마법의 터", objective = "붉은깃털일족 허리띠 6개를 구해 신탁의 숲에 있는 파수꾼 아리니아 클라우드브레이크에게 가져가야 합니다.", description = "전 곳곳에 둥지를 튼 하피들로부터 신탁의 나무를 지키기 위해 소수의 센티널 대원들과 함께 이곳으로 파견되었습니다. 우리는 조금씩이나마 그들을 몰아내고 있는 중입니다.\n\n그런데 다르나서스로 보고서를 전달하러 떠난 전령이 그만 하피 무리에게 습격을 받아 죽임을 당했습니다.\n\n가능하면 그대가 하피 둥지로 가서 그들을 처치한 다음 증거물로 그들의 허리띠를 가져다주십시오.", progress = "그들의 강한 발톱과 날카로운 부리는 그대의 능력의 한계를 시험할 만큼 힘든 상대일 겁니다. 하지만 그대라면 이 임무를 잘해내리라 믿습니다.", completion = "그대가 그 짧은 시간에 이곳에서 해낸 일은 정말 놀랍다고밖에 할 수 없군요. 이곳에 남아 제 임무를 도와달라고 부탁할 수 있다면 좋겠지만, 그대에겐 더 큰 사명이 있다는 걸 알고 있습니다.\n\n조금 전 신탁의 나무에서 껍질이 하나가 벗겨져 떨어지는 걸 봤습니다. 분명, 완수되어야 할 임무가 있다는 뜻입니다. 신탁의 나무의 뜻을 따르시길 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n사슬 벨트소나기 단망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[938] = {title = "미스트", objective = "신탁의 나무 근처의 달샘에 있는 파수꾼 아리니아 클라우드브레이크에게 미스트를 데려가야 합니다.", description = "이 퓨마의 털은 특이한 회색을 띠고 있어서 주변 숲과 구별해내기가 어렵습니다. 등과 배 전체에 깊이 찢긴 심한 상처를 입은 것이 보입니다.\n\n머리를 들어 당신을 바라보고 있는 푸른 눈이 밝고 빛나서 매우 총명해 보입니다. 당신과 함께 어디론가 가고 싶어하는 것 같습니다.", progress = "미스트... 미안해. 내가 잘못했어. 잠시 방심한 틈에... 너를 데려가지 못하도록 막아야 했는데...", completion = "&lt;name&gt;, 감사합니다! 다시는 우리 미스트의 부드러운 털을 쓰다듬을 수 없을 줄 알았는데... 필경 죽은 줄로만 알았던 충성스러운 제 애완동물을 찾아주셔서 정말 감사해요. 말로 다 할 수 없을 만큼 고맙습니다. 이 은혜는 죽어도 잊지 못할 거예요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n골진 팔보호구단단한 버클러정찰자의 망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[939] = {title = "사바릭의 플룻", objective = "사바릭의 플룻과 악의 비취불꽃 매듭 5개를 악령의 숲 남쪽의 에리단 블루윈드에게 가져가야 합니다.", description = "사바릭을 퇴치한 후 얻은 단순한 모양의 나무 플룻을 관찰합니다.\n\n단단해 보이는 구조로 단면에 그려진 문양들이 돌아가는 것처럼 보이고, 뒤집어 보니 움직이고 있었습니다. 갑자기 오한이 느껴지며 몸이 떨립니다...\n\n기분 탓이라는 생각에 고개를 흔듭니다. \n\n사티로스라면 당신이 느낀 이상한 현상에 대해서 알고 있을 것 같습니다. 악령의 숲 남쪽에 살고 있는 드루이드, 에리단 블루윈드에게 당신이 찾은 것들을 가져가십시오.", progress = "<class>, 이게 다 무엇이란 말이오? 지금 떨고 있는 것이오?", completion = "고대인들의 고통이 느껴지는군...\n\n이 물건들을 몸에 지니는 건 위험하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[940] = {title = "텔드랏실", objective = "다르나서스에 있는 대드루이드 판드랄 스테그헬름에게 글씨가 새겨진 나무껍질을 전해야 합니다.", description = "숲에서 그대의 용감한 업적을 숭배하는 속삭임이 바람을 통해 들려오는군요. 하피들이 둥지에서 쫓겨나면서 숲에 조용한 평화가 찾아오고 생물들이 안정을 되찾고 있는 게 느껴집니다. 대드루이드께 또 전갈을 보내기가 두려웠는데, 이제 마음 놓고 보낼 수 있겠습니다.\n\n이걸 그분께 전하도록 하세요. 바위의 숲에 다다를 때까지 숲의 정령들이 그대를 안전하게 지켜줄 겁니다.", progress = "흠... 숲의 정령들의 보호 아래 이곳까지 온 모양이군. 이 칼도레이의 대드루이드에겐 무슨 볼일인가?", completion = "왜 그렇게 오랫동안 신탁의 나무로부터 연락이 없는지 의아해 하고 있었네. 그나마 해결된 문제들도 있고 또 점점 커지고 있는 문제들도 있나 보군.\n\n텔드랏실에 대한 내 노력이 허사가 되고 원래 우리가 가졌던 불사의 생명도 회복하지 못하는 게 아닐까 우려하던 중이었네.\n\n어쨌든 신탁의 나무가 맡긴 임무를 잘 완수해 주었으니 마땅히 보상을 해야지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[941] = {title = "오염된 심장 재배", objective = "데날란의 화분에 오염된 심장을 심어야 합니다.", description = "심장에서 해로운 이끼를 제거하긴 했지만 아직도 오염된 채로 남아 있소.\n\n심장을 내 화분에 넣어 주시오. 화분에는 이 심장을 정화하고 치유할 수 있는 영양분이 풍부한 흙으로 채워져 있소.", progress = "이 화분은 데날란이 특별히 준비한 흙으로 채워져 있습니다.", completion = "오염된 심장을 화분 안에 넣자 순식간에 스스로 땅속으로 파고들어 갑니다.\n\n몇 초 후 심장은 정화된 상태로 꿈틀거리며 밖으로 나옵니다. 심장이 약하게 고동치며... 당신에게 가져가 달라고 신호를 보냅니다.", rewards = "다음과 같은 것들을 받습니다:\n\n정화된 나무괴물 심장"},
[942] = {title = "정신 없는 발굴조사단장", objective = "메네실 항구에 있는 고고학자 플라곤구트에게 신비로운 화석을 가져가야 합니다.", description = "이 화석은 내가 전에 아이언포지에서 봤던 것과 상당히 유사하군그래. 플라곤구트라는 고고학자가 탐험가 연맹 연례 총회에 가지고 나온 것이었소. 그는 그 화석이 봉인을 해제할 수 있는 힘을 지니고 있다고 믿었소.\n\n플라곤구트에 대해 마지막으로 들은 소문에 따르면 웰가르의 발굴 현장까지 자신을 호위해 줄 이를 기다리며 메네실 항구의 깊은바다 선술집에 숨어 지낸다고 하오. 당신이 그를 찾아 렘트레블의 화석을 보여 주시오. 아마 그가 과거의 비밀을 밝혀줄 수도 있을 거요.\n\n메네실로 향하는 배는 아우버다인에서 출발하오.", progress = "무슨 일이오, 친구?", completion = "그 먼 칼림도어 땅으로부터 이걸 가져왔다고 했소?\n\n놀랍구려, 그저 놀라울 따름이오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[943] = {title = "정신 없는 발굴조사단장", objective = "메네실 항구에 있는 고고학자 플라곤구트가 렐루의 돌과 플라곤구트의 화석을 가져다 달라고 부탁했습니다.", description = "원본 화석은 지금 발굴조사단장 웰가르가 저습지에 있는 그의 발굴 현장에 보관하고 있소. 그의 발견 이후 나는 화석의 신비를 밝혀낼 열쇠로 추정되는 렐루의 돌을 모단 호수에서 찾아냈소.\n\n그런데 웰가르를 만나러 가는 도중 줄무늬랩터의 공격을 받아 그 유물을 잃고 말았다오.\n\n그 얼룩덜룩한 짐승들 중에 어느 녀석이 돌을 삼켜 버렸는지는 모르지만, 당신이 그걸 찾아 온다면 화석의 힘을 끌어낼 수 있을 거요.\n\n내게 렐루의 돌과 웰가르가 갖고 있는 원본 화석을 가져다주시오.", progress = "렐루의 돌이 있으면 렘트레블이 어둠의 해안에서 발견한 화석뿐만 아니라 내 화석에 숨겨진 비밀도 밝혀낼 수 있을 거요.", completion = "정말 훌륭하오!\n\n이제 이 돌로 화석에 어떤 힘이 숨겨져 있는지 알아내야겠소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n유물 단검해골깎이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[944] = {title = "지배자의 무덤", objective = "정보를 수집한 다음 수정점의 유리병을 사용하여 수정점 그릇을 만드십시오. 만들어진 그릇을 사용하여 오누와 대화하십시오.", description = "이곳 어둠의 해안에 나가가 나타났다는 건 이상한 일이 아닐 수 없군. 그런데 더 이상한 건 바로 황혼의망치단이야. 그 이교도들은 이 땅의 고대 신을 섬기고 있지. 아주 예전에 죽은 지배자를 말이야.\n\n남쪽에 있는 지배자의 무덤은 그 지배자가 전투에서 패배한 장소야. 그곳으로 가서 황혼의망치단 이교도들이 더 있는지 찾아 봐. 참, 이 수정점의 유리병을 가져가야 해. 지배자의 무덤을 찾은 후 이걸 사용하면 수정점 그릇을 만들 수 있을 거야. 그 그릇을 사용하면 나와 말을 할 수 있지.", progress = nil, completion = "지배자의 무덤에 황혼의망치단이 있다고?\n\n좋지 않은 소식이군.\n\n그 지배자는 오래전에 검에 찔려 죽었지만 그의 강력했던 힘의 파편들은 아직 남아 있을 수도 있어.\n\n틀림없이 황혼의망치단은 그 힘을 찾고 있을 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[945] = {title = "테리루네의 탈출", objective = "테리루네의 탈출을 도운 다음 아에시나의 제단에 있는 테리실에게 그녀가 무사하다는 사실을 알려야 합니다.", description = "도와주세요!\n\n저는 지배자의 무덤 근처를 산책하고 있었는데 더러운 이교도들에게 포위당하고 말았어요. 그나마 내가 숨는 데 능숙해서 다행이었죠.\n\n이곳을 탈출하도록 도와줄 수 있나요? 그리고 우리 언니 테리실에게 내가 무사하다고 알려야 해요. 그녀는 남쪽의 잿빛 골짜기에 있는 아에시나의 제단에 있어요.", progress = nil, completion = "동생이 어디 있다고요? 테리루네는 지저분해지는 걸 별로 신경 쓰지 않긴 하지만, 그래도 그런 곳에 가다니! 지배자의 무덤은 산책을 즐기기엔 너무 먼 곳인데다 저절로 기분이 나빠지는 곳인데...\n\n어쨌든 감사해요. 동생이 무사하다는 사실을 알려 줘서 얼마나 다행인지 몰라요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[947] = {title = "동굴 버섯", objective = "아우버다인에 있는 바리스라스 문셰이드에게 껄껄이그물버섯 5개와 알광대버섯 1개를 가져가야 합니다.", description = "내가 연구 중인 물약에는 특정한 동굴에서만 자라는 희귀한 버섯이 필요하오. 그 동굴은 여기서 동쪽으로 가면 나오는 산맥의 약간 북쪽에 위치한 절벽 폭포 뒤에 있소.\n\n그곳에 직접 가보려 했지만 고대정령의 숲이 그곳에 가까이 가지 말라고 충고하더군. 우리의 오랜 친구인 그들은 느꼈나 보오. 그 동굴이 어둠의 해안에 새로이 생겨난 악의 세력이 숨어 있는 은신처라는 걸 ...\n\n부디 날 위해 버섯을 좀 모아 주시오. 그리고 동굴을 정찰하여 고대정령이 우려하는 바가 사실인지 확인해주기 바라오.", progress = "버섯은 구해 왔소? 동굴에는 다녀 온 거요?", completion = "정말 고맙소. 이 버섯들은 실로 훌륭한 견본이오.\n\n그리고 혹시 절벽 폭포에 있는 동안 고대정령의 경고가 사실인지 확인할 만한 건 발견하지 못했소?\n\n현명한 고대정령들의 말이지만 이번만은 그냥 그들의 지나친 근심 때문이었으면 좋겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n바람 망토붉은반점버섯"},
[948] = {title = "오누", objective = "고대정령의 숲에서 오누와 대화하십시오.", description = "고대정령의 숲에 사는 지식의 고대정령 오누가 절벽 폭포에서의 모험에 대해 듣고 당신과 얘기를 나누길 원하고 있소. 고대정령의 숲은 남쪽 산맥 근처에 있소.\n\n고대정령들은 원래 지혜롭고 인내심이 많기로 유명한데, 오누가 당신을 불러 절벽 폭포에서 본 것을 묻고자 한다면 뭔가 급한 일일지도 모르겠소.", progress = nil, completion = "오, 드디어 왔군.\n\n상의할 게 있어. 자네와 나, 단 둘이서 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[949] = {title = "황혼의망치단 야영지", objective = "지배자의 무덤에 있는 황혼의망치단 야영지에서 단서를 찾아야 합니다.", description = "지배자의 무덤에서 황혼의망치단이 무엇을 하려는지는 아직 알 수 없군. 하지만 분명 좋은 일은 아니겠지.\n\n그곳에 있는 야영지를 수색해서 황혼의망치단의 의도를 짐작할 만한 단서를 찾아야 해. 그들이 계획을 실행에 옮기기 전에 그 의도를 알아내야만 해.", progress = nil, completion = "고대 언어로 쓰인 이 책은 손으로 직접 쓴 것이며 위대한 화가의 삽화가 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[950] = {title = "오누에게로의 귀환", objective = "오누에게 광기의 양피지 문서를 가져가야 합니다.", description = "황혼의 마법책을 자세히 읽어본다는 건 참으로 어려운 일입니다. 잠시만 보고 있어도 그 내용이 꿈틀대며 움직이고 아름다운 무늬가 기괴한 모양으로 뒤틀려 정신이 혼미해집니다.\n\n정신을 거의 잃어버리게 만드는 이 광기의 양피지 문서에서 겨우 한 장을 찢어낼 수 있었습니다.", progress = "돌아왔구나, <name>.", completion = "혼란과 원시의 마법이 이 양피지 문서에 감돌고 있어. 이걸 보니 그들이 한 짓이 느껴지는군.\n\n이 양피지 문서가 어둠의 해안에서 황혼의망치단이 무슨 짓을 꾸미고 있는지 밝혀주면 좋을 텐데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[951] = {title = "마시스트라의 유물", objective = "고대정령의 숲에 있는 오누에게 마시스트라 유물 6개를 가져가야 합니다.", description = "자네가 지배자의 무덤에서 발견한 양피지는 고대 문서 중 한 장으로... 엘프들에 의해 작성된 것이지! 그런데 타락한 황혼의망치단에 의해 심하게 저주받고 오염되어 버렸어. 이 이교도 집단은 고대 엘프의 마법을 사용하여 그들의 옛 주인을 이 세상에 다시 불러오려고 하는 것 같아.\n\n북동쪽에 있는 마시스트라의 폐허로 가서 풀과 깨진 돌 사이에서 고대 유물을 찾아봐. 그 유물들을 연구해 보면 황혼의망치단이 엘프의 마법을 어떻게 이용하려는지 알아낼 수 있을 거야.", progress = "<name>, 마시스트라의 폐허에서 뭔가 찾아냈나?", completion = "고맙구나. 이 유물들은 마시스트라의 전성기 때 만들어진 것들이지. 이제 엘프의 거대한 성은 사라지고 그 마법의 잔재만 이렇게 남은 거지. 그 망치단 녀석들보다 먼저 그 비밀을 밝혀내야 할 텐데...\n\n부디 조심해, &lt;name&gt;...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n단단한 나무 곤봉숲 요정의 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[952] = {title = "고대정령의 숲", objective = "어둠의 해안, 고대정령의 숲에 있는 오누에게 판드랄의 전갈을 전해야 합니다.", description = "그대가 신탁의 나무를 위해 전갈을 전할 시간이 있었다면, 어둠의 해안에 있는 고대정령의 숲으로 전갈을 가져가는 임무도 맡아줄 수 있을 거라 생각하네.\n\n히포그리프를 타고 이동하는 중에는 안전에 각별히 유의해야 하네. 하지만 그대라면 잘해낼 거라 믿네. 이걸 지식의 고대정령 오누께 전하게. 내가 신탁의 숲에 대한 소식을 기다린 만큼이나 그분도 내게서 소식이 오기를 기다리고 있다네.", progress = "이 오누에게 무슨 볼일이라도 있나?", completion = "아. 고맙네. 하지만 이상하군. 대드루이드는 항상 무언가 쫓겨 서두르는 것 같단 말이야. 모든 일에는 정해진 때가 있다는 사실을 숲은 잘 알고 있지. 샨도 스톰레이지도 그 사실을 잘 알고 있어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[953] = {title = "아메스아란의 멸망", objective = "멸망한 아메스아란의 역사가 기록되어 있는 서판의 내용을 알아낸 다음 어둠의 해안에 있는 파수꾼 티샤 문블레이드에게 돌아가십시오.", description = "여기서 동쪽으로 가면 아메스아란의 폐허가 보일 겁니다. 지금 그곳은 성에 살던 명가의 원혼들이 차지하고 있지만, 한때는 아즈샤라의 부하들이 자유롭게 마법을 익히던 곳이었답니다.\n\n저는 멸망한 아메스아란의 역사가 기록된 커다란 서판 두 개를 찾기 위해 폐허를 수색하는 임무를 띠고 파견되었습니다. 그런데 제가 서판의 룬 문자를 읽고 있는 동안 원혼들이 접근해 오는 바람에 거기서 도망칠 수밖에 없었습니다.\n\n괜찮다면 저 대신 폐허로 가서 서판에 있는 내용을 판독해 주시길 부탁 드립니다.", progress = "그대가 서판의 내용을 판독해 아메스아란의 멸망에 대해 알아오는 대로 그 정보를 아우버다인으로 가져가 고대 의회에 보고하겠습니다.", completion = "고대의 전쟁이 발생했던 시기에 대한 기록은 지금 거의 남아 있지 않습니다. 특히, 영원의 샘이 파괴되던 시기에 대한 기록은 더더욱 그렇죠. 당시의 혼란과 격동을 생각하면 기록이 남아 있지 않다는 것이 사실 그리 놀라운 일은 아닙니다.\n\n고맙습니다. 그대가 도와준 덕분에 임무를 완수하고 의회에 보고할 수 있게 되었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[954] = {title = "바샬아란", objective = "바샬아란의 폐허에 감도는 이상한 푸른 기운의 근원을 찾아야 합니다.", description = "동쪽에 있는 바샬아란의 폐허가 악마의 앞잡이들에게 점령당하고 말았소. 마귀들과 사티로스들은 그곳을 장악하고 마법 에너지를 흡수해 나날이 강해지고 있소.\n\n그런데 아직 그들이 접근조차 하지 못한 제단이 하나 있다고 하오. 폐허의 서쪽 가장자리에 작은 절벽이 있는데, 그 꼭대기에서 이상한 기운이 뻗어나온다고 하더군. 그곳으로 가면 이 악마들의 저항에 대해 알아낼 수 있을 거요.\n\n그대가 좀 조사해 주시오.", progress = nil, completion = "아... 그대처럼 훌륭한 &lt;race&gt;|1이;가; 여기까지 오게 되다니 이 영광을 어디에 비하리. 여기 내 친구들, 저 고귀하신 그렐과 사티로스들도 이제 그대를 두려워하겠군.\n\n내 무례한 혀가 그대의 기분을 상하게 했다면 용서해주게. 문명의 냄새를 맡은 지 너무 오래되어서 말이네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[955] = {title = "바샬아란", objective = "바샬아란에 있는 아스테리온을 위해 그렐족 귀걸이 8개를 구해야 합니다.", description = "내가 살아온 얘기를 한다면 아마 그대는 믿지 못할 걸세. 내 삶은 아주 길고 고통스러운 것이었다네. 그리고 이렇게 실체 없는 모습이 되어버린 건 그 중 가장 고통스러운 일이지.\n\n난 마법에 의해 여기에 갇히게 되었다네. 내 얘기가 믿기 어려울지도 모르지만, 그대가 날 구속하고 있는 도구를 찾아 준다면 그 고마움은 말로 다 하지 못할 만큼일 게야. 마귀들과 그렐들을 조사해 보면 날 가두고 있는 이 봉인에 대해 뭔가 단서를 발견할 수 있을 거야.", progress = "귀걸이만 있으면 주문을 사용해 날 구속하고 있는 봉인을 찾아낼 수 있을 거야. 수 세기 동안 나는 봉인만 깬다면 자유를 얻을 수 있을 거라고 생각해 왔네. 돌이킬 수 없는 그 시간은 내게 아무런 보상도 해주지 않으려나 보군.", completion = "이럴 수가... 바샬아란의 그렐들에겐 내가 찾는 봉인에 대한 단서가 없었어. 하지만 최근 그들이 봉인에 접촉했네. 최근이라 함은... 그러니까 나의 시간이 아니라 그대의 시간을 기준으로 말일세. 과거의 시간은 내게 있어 지옥이었네. 한 세기 만큼이나 긴...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[956] = {title = "바샬아란", objective = "고대 월장석 봉인을 찾아 바샬아란에 있는 아스테리온에게 가져가야 합니다.", description = "그렐이 날 무한정 구속하고 있는 봉인에 접근한 이유를 알 것도 같군그래. 이제 그들을 이끌고 있는 사티로스가 봉인을 가지고 있는 것이 분명해졌네.\n\n그게 사실이 분명하다는 확신이 드네. 저 사티로스 중 누군가 분명히 봉인을 가지고 있을 걸세. 그대가 그 봉인을 찾아 준다면 난 자유를 찾을 수도 있을 지도 몰라. 내 눈에서 감격의 눈물이 흐를 날이 올지도 모르겠군그래.", progress = "이 제단의 기둥은 마치 날 가두고 있는 감옥의 빗장과 같아. 이걸 힘으로 부술 수도 마법으로도 파괴할 수도 없지.\n\n수천 년 동안 나는 저 기둥들을 쳐다보면서 저 돌처럼 오랜 시간을 이런 모습으로 남게 되는 게 아닌가, 다시 자유로울 수 있을까... 이런 생각을 해왔다네. 그리고 날 가두고 있는 보이지 않는 빗장이 있는 건 아닐까...", completion = "지... 지금 내 손에 들고 있는 것이 그 오랜 시간 날 구속해왔던 봉인이라니... 믿을 수가 없군. 어서 서둘러야겠네. 더 이상 시간을 낭비하고 싶지 않아. 봉인을 파괴하면 나는 이 땅의 숲을 다시 자유롭게 거닐 수 있을 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[957] = {title = "바샬아란", objective = "아메스아란에 있는 고대의 불꽃으로 고대 월장석 봉인을 파괴한 다음 바샬아란에 있는 아스테리온에게 돌아가십시오.", description = "이 감옥의 봉인을 만든 건 가장 강력한 명가 중 하나의 솜씨였다네. 이곳과 똑같이 생긴 남쪽의 폐허 아메스아란에는 아직까지도 녹색 빛이 나는 고대의 불꽃이 남아 있다더군. 그 불꽃으로 이 봉인을 깰 수 있을 걸세.\n\n폐허에 가게 되면 부디 조심하도록 하게.", progress = nil, completion = "이제 난 자유를 찾았네! 지금까지 이 틈으로만 보였던 세상의 달라진 모습을 내 두 눈으로 똑똑히 보겠어. 마지막으로 내 두발로 자유롭게 거닐 수 있었던 그때, 영원의 샘은 아직 건재했고 지금 구천을 떠돌며 살생을 일삼는 명가는 우리 친애하는 여왕 아즈샤라 폐하와 함께 왕실을 운영하는 귀족이었지.\n\n이전엔 내 스승이었지만 지금은 날 가둔 장본인 애스리쿠스가 아직 살아 있다는 게 느껴지는군. 지금까지의 내 절망은 이제 복수에 대한 열망으로 변해 가고 있어.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n탐험가의 조끼방랑자의 가죽 바지엘프의 마법봉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[958] = {title = "명가의 도구", objective = "아우버다인에 있는 툰드리스 윈드위버를 위해 명가의 유물 7개를 찾아 와야 합니다.", description = "부탁할 일이 하나 있소. 혹시 아메스아란의 폐허를 본 적이 있소? 남쪽으로 가다 보면 나오는 큰 길 동쪽편에 있을 거요.\n\n한 때 그곳은 기세등등한 명가들의 고향이었는데, 지금은 과거 그들이 사소한 이유로 벌인 일에서 비롯된 파멸이 흔적처럼 남아 있소.\n\n센티널에서 들은 바로는 명가의 영혼들이 아직 남아 고대의 마법 도구들을 사용하고 있다 하오. 그 유물들을 압수해 파괴해야 하오.", progress = "우리 세계를 파멸로 이끈 그 혼란 속에서 그들이 사용한 파멸의 도구만 없애버렸더라면... 어쨌든 앞으로는 과거의 끔찍한 일이 되풀이되지 않도록 모든 노력을 기울여야 하오.", completion = "나 혼자만의 상상일지도 모르지만, 이 유물에서 끔찍한 마법의 흔적이 느껴지는 듯하오. 이 유물들을 파괴하여 오랫동안 잠들어 있는 악의 기운이 다시는 깨어나지 못하도록 하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n덩굴 소매장식"},
[959] = {title = "99년 묵은 와인", objective = "톱니항에 있는 기중기 기사 비글퍼즈가 통곡의 동굴에 숨어 있는 광기의 매글리시에게서 99년 숙성된 포트 와인을 되찾아 달라고 부탁했습니다.", description = "보시다시피 작은 문제가 발생했소. 아침에 무법항에서 막대한 양의 뱃짐이 배달됐소. 정말 엄청난 규모지! 내 생전에 그렇게 많은 상자들은 본 적이 없단 말이야. 난 일을 신속히 처리하려고 평소보다 조금 무리해서 짐을 부리기 시작했소. 바로 그 때 문제가 발생한 거요.\n\n광기의 매글리시라는 악당이 나타나 눈 깜짝할 사이 99년이나 숙성된 포트 와인 병을 들고 달아나고 있었소. 죽기살기로 통곡의 동굴까지 달아나는 그 자를 쫓아갔지. 그런데 그 안으로는 들어갈 수가 없어서 밖에서 발만 동동 굴렀지.\n\n당신이라면 들어갈 만한 용기가 있을 것 같은데 내게 그 와인을 되찾아 주지 않겠소?", progress = "광기의 매글리시가 99년 숙성된 포트 와인을 가지고 달아난 후 항구주임이 내 임무를 맡고 있지. 내 생각에 그 와인은 남작 레빌가즈 자신이 손수 가즈로에게 보내는 선물인 것 같소.\n\n당신의 용기와 인내심으로 광기의 매글리시를 처치하고 포도주를 되찾아 준다면, 그에 걸맞은 보상을 하도록 하지.", completion = "훌륭하오! 조금만 늦었으면 난 직장도 잃을 뻔했소. 이 선물을 바로 가즈로에게 전하도록 하겠소.\n\n고맙소. 정말 잘했소!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[960] = {title = "생각 중인 오누", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n수정점의 유리병"},
[961] = {title = "생각 중인 오누", objective = "황혼의망치단 이교도가 나타난 건 그냥 넘어갈 수 없는 문제야. 난 그자들의 의도를 알아내야만 해.\n\n정보를 더 입수하게 되면 수정점 그릇을 통해 내게 연락해. 그릇을 만들 수정점의 유리병이 더 필요하다면, 자, 여기.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n수정점의 유리병"},
[962] = {title = "불뱀꽃", objective = "썬더 블러프에 있는 연금술사 자마가 불뱀꽃 10개를 모아 달라고 부탁했습니다.", description = "로데론의 위대한 도시 언더시티에 있는 왕립 연금술 학회에서 매우 특별한 임무를 위해 날 이곳으로 보냈소. 아마 당신은 포세이큰의 발전을 위해 노력 중인 나와 어둠의 여왕님을 도와줄 거라고 생각하오.\n\n최근에 나는 불뱀꽃이라는 희귀한 식물의 표본에 대해 연구했소. 이 향초의 잠재력은 아주 크다고 믿소.\n\n하지만 불행하게도 불뱀꽃은 불모의 땅에 있는 위험한 동굴인 통곡의 동굴의 가장 어둡고 깊은 곳에서만 자라오. 통곡의 동굴로 가서 불뱀꽃을 구해다 주시오.", progress = "당신이 통곡의 동굴에서 불뱀꽃을 충분히 모아 올 수 있을지 기대하고 있겠소. 난 많은 이들을 보내 봤지만 아무도 돌아오지 못했소이다.", completion = "아, 훌륭한 표본이군. 수고했소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n약제사 장갑"},
[963] = {title = "영원한 사랑", objective = "아나야 돈러너의 영혼을 자유롭게 한 다음 그녀의 펜던트를 아우버다인에 있는 셀렐리안 화이트클로에게 가져가야 합니다.", description = "영원의 샘에서 벌어진 전투로 인해, 아메스아란이 멸망하고 내 사랑 아나야와 그곳 주민들이 모두 죽었다고 들었소.\n\n수천 년이 지난 지금에도 아나야에 대한 기억이 꿈속에서 날 괴롭힐 줄은 생각지도 못했소. 무의식 중에 어둠의 해안의 숲을 거닐다가 나도 모르는 사이에 아메스아란의 폐허에 와 있는 나 자신을 발견하게 되고... 거기서 내가 사랑하는 아나야의 유령을 보곤 한다오.\n\n그녀를 자유롭게 해 주어야 하지만 차마 내가 직접 그렇게 할 용기가 나지 않는다오. 부디 그대가 그녀의 영혼을 자유롭게 해주시오.", progress = "난 가슴에 큰 슬픔을 안고 샨도 스톰레이지님을 따라 에메랄드의 꿈으로 들어갔고 수천 년 동안 그 속에서 흐느끼며 잠들어 있었소.", completion = "고맙소. 내 손으로 그녀를 자유롭게 해 줄 수 있었다면 더 좋았을 테지만 수천 년이 지난 지금도 내가 사랑하는 이를 다치게 할 수는 없었소.\n\n이제 혼자 이 슬픔을 달래고 싶소. 미안하오만 그만 가주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n고뇌의 눈물"},
[964] = {title = "뼈조각", objective = "서부 역병지대의 보루에 있는 연금술사 디더스에게 뼈조각 15개를 가져가야 합니다.", description = "스칼로맨스로 가는 열쇠를 해골 열쇠라고 부르지. 해골 열쇠는 물론 해골로 만드는데 가장 단단한 금속을 적당한 거푸집에 넣고 굳혀서 만들지. 사실 해골이 여러 개 필요하다네. 그리고, 스칼로맨스로 가는 차원의 문을 자유로이 드나들 수 있는 존재에게 힘의 인장을 얻어야 열쇠를 완성할 수 있어.\n\n꽤 복잡하지? 우선 생각나는 것부터 시작하세. 우선 열쇠의 재료가 되는 뼈조각이 필요해. 안돌할 안쪽에 있는 해골들에게서 얻을 수 있을 걸세. 하지만 성벽 밖에 있는 해골도 상관은 없어.", progress = "죽여. 다 죽여 버리게, <class>|1이여;여;. 열쇠를 만들려면 온전한 뼈조각이 꽤 많이 필요하다고. 왜 세상에 많고 많은 이름을 놔두고 해골 열쇠라고 부르겠나?", completion = "이거면 되겠어! 수고했네, &lt;name&gt;. 이제 내 차례군. 적당한 마력을 불어넣어 격렬한 주조 과정을 견딜 수 있게 하는 거지.\n\n다음 단계는 열쇠를 뜰 거푸집을 구하는 일이야. 과거에 해골 열쇠 같이 으스스한 물건을 만들었던 고블린 대장장이를 하나 알고 있지. 그 역시 대부분의 고블린처럼 자신이 만든 물건에 최고의 값을 쳐주는 고객을 위해 일하고 있네. 타나리스에서...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[965] = {title = "알살락스의 탑", objective = "어둠의 해안에 있는 알살락스의 탑 근처에서 발툴 섀도스트라이크를 찾아야 합니다.", description = "안녕하십니까, 젊은 <race>|1이여;여;... 전 엘리자 스타브리즈라고 합니다. 이곳 아우버다인을 안전하게 지키는 게 제 임무입니다.\n\n얼마 전 발툴 섀도스트라이크를 북동쪽 알살락스의 탑으로 보내 그 주변에서 일어나고 있는 심상치 않은 일들을 조사하도록 했답니다.\n\n그가 돌아와야 할 때가 한참이나 지났는데... 숲에서 불의의 사고라도 당한 것이라도 아닌가 걱정이 됩니다. 그대가 그를 찾아 무사히 임무를 수행했는지 확인해 준다면 정말 고맙겠습니다.", progress = nil, completion = "엘리자님께서 보내셨소? 마침 엘리자님께 보고할 소식이 있는데 도무지 전할 방도가 없었는데, 때맞춰 오셨소. 그런데 그다지 기쁜 소식은 아니라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[966] = {title = "알살락스의 탑", objective = "알살락스의 탑 근처에 있는 발툴 섀도스트라이크를 위해 낡은 양피지 문서 4개를 모아야 합니다.", description = "한 무리의 소환사들이 탑 안팎에 모여 있소. 내가 좀 더 일찍 아우버다인으로 돌아가 엘리자님께 보고했어야 하지만 자리를 비운 사이 뭔가 중요한 것을 놓치게 될 것만 같아 여기를 떠날 수가 없었소.\n\n델그렌님께서는 이자들이 탑으로 모여들 것 같다고 하셨지만 그 이유까지는 모르셨소.\n\n소환사들이 가진 양피지 문서를 약간 손에 넣었지만 의문을 완전히 풀기 위해선 몇 개 더 필요한데 그대가 좀 도와주시겠소? 하지만 탑 안으로는 들어가지 않는 게 좋을 거 같소. 탑 안에 있는 소환사들은 훨씬 더 강력하니까 말이오!", progress = "양피지 문서를 더 찾아왔소? 그대가 도와준다면 이 이교도 집단의 윤곽을 좀 더 확실히 파악할 수 있을 것이오.", completion = "정말 고맙소. 이제 소환사들이 모여든 이유를 밝혀낼 수 있을 것 같소.\n\n흠... 암흑이교도라... 이런 무리에 대해서는 들어 본 적이 없는데... 내가 알고 있는 바가 없으니 그들의 계획이 무언지도 알 수가 없소.\n\n더 이상 지체할 시간이 없소. 당장 델그렌님께 이 사실을 알려 드려야겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[967] = {title = "알살락스의 탑", objective = "잿빛 골짜기 숲에 있는 수호자 델그렌에게 발툴의 편지를 전해야 합니다.", description = "내 스승이신 수호자 델그렌께서는 숲을 악마와 언데드의 손으로부터 지키기 위해 기꺼이 도움을 주고 계신 성기사이시오. 그분은 내게 성스러운 빛과 전투 기술에 대해 많은 걸 가르쳐 주셨다오. 델그렌이시라면 이 집단이 대체 무엇을 하고 있는 건지 바로 알아내실 것이오.\n\n이곳에서 남쪽으로 멀리 떨어진 잿빛 골짜기 숲의 마에스트라 주둔지로 가면 그분을 만날 수 있을 거요. 아... 암흑이교도의 위협이 시시각각으로 커지고 있는 것 같소. 서두르시오.", progress = "내게 무슨 볼 일이라도 있나?", completion = "자네는 전령으로서 자질이 뛰어난 것 같군. 발툴이 이 편지를 믿고 맡길 만했겠어. 자, 어디 한번 읽어 볼까?\n\n흠... 별로 좋은 소식은 아니로군. 나는 센티널을 도와 언데드나 악마의 세력이 발견되는 족족 놈들을 처치하고 있지.\n\n처음엔 나이트 엘프들의 방식에 익숙하지 않았지만 지금은 동맹으로서 상당히 존경하게 되었다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[968] = {title = "힘의 저편", objective = "아이언포지에 있는 게릭 본그립에게 '힘의 저편'이라는 책을 가져가야 합니다.", description = "워낙 낡은데다 심하게 긁히긴 했지만 이 책의 표지에 적힌 제목은 아직 읽을 수 있습니다.\n\n'힘의 저편'\n\n펼쳐보니 어떻게 읽어야 할지 아리송한 이름들과 함께 예언의 제목, 경배 의식의 절차, 희생 제물들의 순위가 적혀 있습니다. 그림을 보니, 희생 제물의 대부분은 인간과 비슷한 형상을 한 살아있는 생명체들입니다.\n\n책 표지 안쪽에는 '아이언포지의 쓸쓸한 뒷골목, 본그립의 룬과 운명 서점, 소유자: 게릭 본그립'이라는 글귀가 찍혀 있습니다.\n\n본그립의 서점에서 이런 종류의 책을 취급한다면 이 책을 다시 사들일지도 모릅니다.", progress = "어서 오십시오, 손님.\n\n찾으시는 책이라도 있으신지?", completion = "아, '힘의 저편'... 참 흥미로운 책이죠. 유용하기도 하고요.\n\n그런데 심하게 손상됐군요. 여기 좀 보세요! 거의 모든 페이지에다 무언가 적어 두었군요!\n\n흠... 이 책은 작년에 볼가르에게 팔았는데... 혹시, 그의 친구 분이신가요? 아... 그럴 줄 알았습니다. 당신의 눈에도 똑같은 불꽃이 서려있으니 말입니다.\n\n어쨌든 볼가르의 친구는 곧 저의 친구이기도 합니다. 자기 친구는 자기가 챙겨야 하지 않겠습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[969] = {title = "행운이 함께하기를", objective = "눈망루 마을의 의술사 마우아리에게 서리망치거인조각 10개를 가져가야 합니다.", description = "허어, 자네 눈을 들여다 보기만 해도 뭘 원하는지 알 것 같군. 행운의 부적을 만들어 달라는 게지? 말하지 않아도 이 마우아리는 다 알고 있네!\n\n남쪽으로 가게. 그곳에 가면 얼음으로 만들어진 거인들을 볼 수 있을 게야. 가끔 놈들이 갖고 다니기도 하고, 아니면 자네가 직접 산맥을 뒤져 조각들을 찾아올 수도 있겠지. 이곳에서는 질이 아주 좋은 것들이 나오니까...\n\n서리망치거인조각 10개를 가져오게, 그러면 내 행운의 부적을 자네에게 줌세.", progress = "자세한 것은 조각을 가져오면 알려 주지.", completion = "좋아, 좋아... 내 지금 자네에게 줄 부적을 만들지. 자넨 그냥 기다리기만 하면 돼!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[970] = {title = "알살락스의 탑", objective = "빛나는 영혼의 보석을 모아 마에스트라 주둔지에 있는 수호자 델그렌에게 가져가야 합니다.", description = "발툴의 편지가 매우 긴급한 내용을 담고 있군. 내게 이 암흑이교도는 반드시 없애버려야 할 눈엣가시와 같다네. 일전에 북동쪽에 있는 오르딜아란에서 암흑이교도 녀석 몇 명을 상대한 적이 있다네. 그런데 놈들 중 하나가 가진 영혼의 보석이란 것이 이 이교도가 가진 불가사의한 힘의 비밀을 밝히는 열쇠가 될 거라 생각되네.\n\n그걸 내게 가져다주게. 그러면 내가 그 안에 숨겨진 비밀을 밝혀내도록 하지.", progress = "영혼의 보석은 손에 넣었나?", completion = "흠... 이 영혼의 보석에는 알 수 없는 어둠의 마법이 걸려 있군. 자, 어떤 비밀이 숨겨져 있는지 어디 한번 보겠나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[971] = {title = "심연의 지식", objective = "아이언포지, 쓸쓸한 뒷골목에 있는 게릭 본그립에게 로르갈리스 초본을 가져가야 합니다.", description = "이미 알고 있을지 모르겠지만, 난 고대 지식이나 강력한 힘을 지닌 정보, 새로운 차원의 문을 여는 지식, 그리고 잠든 자들을 깨우는 지식을 모은다네.\n\n소문에 의하면 잿빛 골짜기에 있는 검은심연의 나락 깊숙한 곳에 로르갈리스 초본이라는 오래된 지식서가 있다고 하던데... 그곳은 이미 오래전에 죽은 엘프들이 점령해 거처로 삼고 있지. 도시가 파멸되기 전에는 위대한 지식을 가졌던 귀족들이라네.\n\n검은심연의 나락에서 그 초본을 찾아오면 은혜는 잊지 않겠네. 이 세상을 떠나더라도... 잊지 않을 거야.", progress = "잿빛 골짜기로 가는 길은 험난하고 이번 임무가 쉽진 않겠지만 초본을 가져와 주기 바라네. 그러면 그에 합당한 사례가 있을 것이네.", completion = "초본을 찾았군! 이렇게 기쁜 날이 또 있을까! 우리 형제 자매들에게 로르갈리스의 고대 지식을 전할 수 있게 되다니! 어서 사본을 만들어 배포해야겠네.\n\n자네가 한 일이 얼마나 큰 의미가 있는지 모를 거야. 이 선물이 우리가 전하는 감사의 마음을 제대로 표현해줬으면 좋겠군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n지탱의 반지"},
[972] = {title = "물의 정기", objective = "물의 정기를 가지고 은빛소나무 숲의 타락한 연못으로 가세요, <name>. 당신이라면 잘해낼 수 있으리라 믿어요.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n물의 정기"},
[973] = {title = "알살락스의 탑", objective = "마에스트라 주둔지에 있는 수호자 델그렌에게 일크루드 마그스룰의 마법책을 가져가야 합니다.", description = "일크루드 마그스룰... 이 자에 대해서는 좀 알고 있지. 그는 잿빛 골짜기 남서부 지역에 있는 거대한 악의 장소인 불타버린 신전에 살고 있는 강력한 오크족 흑마법사라네.\n\n지금까지는 조금 성가신 존재에 지나지 않아서 별다른 조치를 취하지 않았는데, 이제 놈을 상대해야 할 시간이 온 것 같군.", progress = "조금 떨리는 것 같아 보이는군. 괜찮은가?", completion = "오늘 정말 큰 일을 해냈네. 자넨 그런 강력한 힘을 지닌 흑마법사와 맞서 싸웠다는 사실을 아주 자랑스럽게 생각해야 할 게야.\n\n이제, 일크루드가 무엇을 써 놓았는지 한번 살펴볼까?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n성직자의 반지정화의 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[974] = {title = "앗! 뜨거!", objective = "운고로 분화구에 있는 크래클이 불기둥 마루에서 가장 뜨거운 자리를 찾도록 요청했습니다.\n\n뜨거운 열점을 찾을 때마다 온도계측장치를 오른쪽 클릭해 온도를 재십시오. 가장 뜨거운 열점을 찾을 때까지 계속 재야 합니다.", description = "이곳의 온천은 참 수수께끼야. 도대체 열이 어디서 나오는 걸까?\n\n불기둥 마루에 가깝다는 점으로 미루어 보아 화산과 어떤 관련이 있는 게 아닐까... 화산의 온도를 잴 수 있는 온도계측장치를 만들었으니 당신이 가서 가장 뜨거운 곳을 찾게나. 온도는 섭씨도, 화씨도 아니라 크래클씨로 표시되지!\n\n자, 받게나. 불기둥 마루에서 뜨거운 열점을 찾을 때마다 온도를 재 주게.", progress = "내가 직접 갔으면 좋겠지만... 그곳에 있는 불의 정령들이 좀 무서워서 말이야!", completion = "그렇지. 화산의 온도와 온천의 온도 간의 관련성이 확실히 보이는군. 방정식이 틀림없나 다시 한 번 확인해야겠어. 거리에 비례한 온도 전달률은... 흠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[975] = {title = "마우아리의 부적", objective = "행운의 부적을 얻기 위해 다시 한번 의술사 마우아리에게 말을 걸어야 합니다.", description = "이 부적을 지금 자네에게 주기 전에 사용 방법을 먼저 알려 줘야겠지?\n\n이 부적을 가지고 다니면 자네의 사냥감들은 특별한 물건들을 떨어뜨릴 걸세. 부적이 없다면 상상도 못할 얘기지만 말이야.\n\n그 물건들의 이름은 에코라고 한다네. 만약 찾게 되면 이 마우아리를 찾아오게. 내 도와 줄 터이니...\n\n여기서 좀 기다리게. 내 부적을 만들어 주지.", progress = nil, completion = "&lt;name&gt;, 이걸 받게. 꼭 몸에 지니고 다녀야 하네. 가서 한번 시험해 보게. 놀라운 것을 찾게 될 테니까...", rewards = "다음과 같은 것들을 받습니다:\n\n마우아리의 부적"},
[976] = {title = "아우버다인으로의 보급품", objective = "피로가 안전하게 잿빛 골짜기를 통과하도록 경호한 뒤 마에스트라 주둔지에 있는 수호자 델그렌과 대화하십시오.", description = "델그렌님께서 아우버다인에 있는 파수꾼 스타브리즈에게 보급품과 서신을 전해 달라고 말씀하셨지만 난 혼자서 길을 떠나고 싶지 않다네. 숲 속엔 위험한 적들이 어슬렁거리는데 이 보급품과 중요한 정보가 혹시라도 나쁜 놈들의 손에 넘어가면 어쩌나?\n\n만약 자네와 동료들이 나를 경호해 준다면 지금 당장이라도 출발할 수 있겠네만... 그러면 이 물품을 안전하게 아우버다인으로 수송하리라 믿어 의심치 않네.", progress = nil, completion = "&lt;class&gt;|1이여;여;, 정말 고맙습니다. 우리가 아우버다인에 보낸 물품은 오염된 숲에 도사리고 있는 어둠의 위협과 맞서 싸우는데 즉시 사용될 것입니다.\n\n진정 어린 감사의 표시로 이걸 받아 주세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n영원의 등불코르의 흉갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[977] = {title = "깜짝 기계설인 대작전", objective = "눈망루 마을에 있는 우미 럼플스니커에게 온전한 설인 뿔 2개를 가져가야 합니다.", description = "움직이는 기계설인의 부품을 덮을 것들이 모두 있는데, 단 한 가지만 없지 뭐예요... 사실은 두 개요. 뿔 두 개!\n\n얼음엉겅퀴 설인은 암컷, 수컷 가릴 것 없이 큰 뿔을 갖고 있어요. 그놈들의 뿔이면 되겠는데... 여기서 남동쪽에 있는 동굴에서 살고 있으니 한번 가보세요. 엄청나게 많이 있으니까 그리 힘들지는 않을 거예요.\n\n제일 좋은 뿔을 가져다주세요. 부러지거나 망가진 뿔은 절대로 싫다고요!", progress = "이제 막 기계설인에게 털옷을 입힐 참이었어요. 제발 뿔을 빨리 가져와 주세요! <name>.", completion = "친구들에게 빨리 보여주고 싶군요! 잠깐, 이것들을 여기에 달면...\n\n완벽해!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[978] = {title = "달빛의 올빼미야수", objective = "여명의 설원에서 달빛 깃든 깃털을 10개 모아서 루테란 마을의 에릴라스 엠버스카이에게 가져와야 합니다.", description = "동부 내륙지에 사는 올빼미야수의 깃털에는 마법의 흔적들이 엿보입니다. 올빼미야수는 선천적으로 마력을 타고난 것 같아요. 그러니까... 태어날 때부터 그러한 성질을 지니고 나왔다는 얘기예요.\n\n풍문에 의하면 여명의 설원에도 올빼미야수들이 많이 서식하고 있다는데, 거기 사는 놈들도 그런 힘이 있을지 궁금하네요. 그 해답을 찾도록 도와 주실 수 없을까요, <name>? 여명의 설원으로 가서 땅에 떨어진 깃털을 모아 제게 가져다주세요.", progress = "대체 그 힘은 어디서 유래된 걸까요? 이제 우리가 그 해답을 찾을 수 있을 것 같군요.", completion = "이제 깃털들을 비교해볼 수 있겠네요! 어디 보자...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[979] = {title = "란샬라 찾기", objective = "여명의 설원 동부에 있는 란샬라를 찾아야 합니다.", description = "그래, 그래! 이전에 봤던 것처럼 이 깃털에는 어떤 마법이 걸려있는 듯하오... 그게 무엇인지는 잘 모르겠지만 당신이 계속해서 도와준다면 해답을 찾을 수 있을 거요.\n\n최근에 내 동료 하나가 올빼미야수 서식지를 관찰하러 여명의 설원으로 갔소이다. 그 친구를 찾아 뭘 알아냈는지 한번 알아보지 않겠소?", progress = nil, completion = "안녕하세요! 에렐라스가 보냈다고요? 잘 됐군요. 이제 막 동굴로 떠날 준비를 하던 참이었는데, 같이 갈 사람이 필요하거든요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[980] = {title = "새로운 온천", objective = "여명의 설원으로 가서 도노바 스노우덴과 대화하십시오.", description = "여기서 북쪽 멀리 여명의 설원이라는 곳에도 온천이 있다고 들었는데, 한가지 이상한 점은 그 근처 어디에도 화산이 없다는 거지. 꽤 재미있지 않나?\n\n더 자세히 알고 싶으면 여명의 설원으로 가서 내 친구와 얘기해 보게나. 도노바 스노우덴이라는 이름의 여자인데, 지금 그 온천 옆에서 지내고 있네.\n\n참, 온도를 재는 걸 도와줘서 고마웠수! 그럼, 또 보세!", progress = nil, completion = "안녕하세요, &lt;name&gt;. 네, 크래클이 말씀드린 대로입니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[981] = {title = "알살락스의 탑", objective = "마에스트라 주둔지에 있는 수호자 델그렌과 대화하십시오.", description = "그대가 행한 모든 일을 칭송하건대 그대는 충분한 보상을 받아 마땅하오. 델그렌님께 돌아가 애스리쿠스 나라신을 그대 손으로 잠재운 것과 암흑이교도들이 공격을 받아 뿔뿔이 흩어진 사실을 전해주시기 바라오.", progress = nil, completion = "난 자네가 임무를 완수해내리라 짐작하고 있었네.\n\n그동안 훌륭히 수행해 온 임무를 보건대 자네가 우리 땅에 깃든 많은 재앙을 바로잡으리라고 느꼈네. 자네의 앞길에 축복을! 그리고 이 선물도 함께 받게나.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n신앙의 바지대천사의 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[982] = {title = "깊고 푸른 바다", objective = "아우버다인에 있는 골볼트 스틸핸드에게 은빛 새벽호의 금고와 안개 장막호의 금고를 가져가야 합니다. 모두 마을의 북쪽에 있는 난파선에서 찾을 수 있을 것입니다.", description = "여기서 북쪽으로, 어둠의 해안 근처에 난파선이 두 척 있소. 은빛 새벽호와 안개 장막호... 모두 얼마 전 아우버다인으로 들어가는 대해 위에서 몹쓸 멀록 녀석들과 충돌하였다오. 이제는 악마들의 전리품이 되어 바다 밑바닥에 가라앉았지.\n\n그날 밤, 두 배의 선장들은 모두 살아 나오지 못했소. 항해일지와 선장들의 소지품들도 금고에 든 채 가라앉아 있소. 당신이 가서 가져와 준다면... 아직 잔해 부근에 머무르고 있는 선원들에게 큰 위안이 될 거요.", progress = "그 두 배의 선장들은 모두 훌륭한 나이트 엘프였고, 그보다 좀 더 나은 임종을 맞이했어야 하는데... 그들의 물건을 되찾아 잘 돌보는 것이 불쌍한 영혼들을 달랠 최선의 방법일 것 같소.", completion = "당신은 이곳 아우버다인에서 우리에게 아주 큰 도움을 주었소. 이 물건들을 반드시 잘 보관하도록 하겠소이다.\n\n자, 이걸 받으시오. 잘못된 일을 올바르게 바로잡아 줄 용기가 있는 자에게 내가 해줄 수 있는 최소한의 보답이요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n물방울 장갑매듭죔쇠 건틀릿\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[983] = {title = "버즈박스 827", objective = "집게다리 6개를 모아 버즈박스 827에 넣어야 합니다.", description = "이봐요! 내가 이번에 발명한 버즈박스라는 기계가 있는데, 그건 멀리 떨어진 이들과 얘기를 할 수 있게 해주는 장치죠. 레버가 달린 상자 같은 건데 혹시 본 적이 있을지도 모르겠군요. 이 장치의 유일한 문제점은 꾸준히 유지 보수를 해줘야 한다는 거예요.\n\n뭐, 세상에 모든 기계에 문제점이 한두 가지씩은 있겠지만 내가 아주 기발한 해결책을 찾았어요. 문제를 해결해 주는 부품을 가진 짐승 서식지 근처에 각 장치들을 설치하는 거였답니다.\n\n그런데 지금 버즈박스 827이 고장났어요. 아우버다인 남쪽, 아주 가까운 곳에 있죠. 그걸 고치려면 집게다리 6개가 필요해요. 내 부탁을 들어준다면 답례를 하죠.", progress = "버즈박스 827은 스산한 정적 속에 있습니다. 상자 안에 집게다리 6개를 넣어야 함을 알리는 불빛이 깜빡이고 있습니다.", completion = "집게다리 8개를 기계에 넣자 기어가 돌아가는 소리가 들립니다. 기계에서 나는 굉음으로 미루어 보건대 집게 다리를 제대로 넣은 것 같습니다. 기계가 소음을 내기 시작하자마자 그 안에서 누군가를 부르는 희미한 소리가 들립니다.\n\n\"여보세요? 어... 여보세요? 장치를 수리했군요! 저 위즈뱅이에요. 정말 고마워요. 혹시 다른 장치도 좀 고쳐줄 수 있나요?\"", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[984] = {title = "거대한 위협", objective = "어둠의 해안에서 오염된 펄볼그 야영지를 찾은 다음 아우버다인에 있는 테렌디스에게 돌아가십시오.", description = "우리 동료 중 일부가 텔드랏실의 오염된 펄볼그에게 잡혀 죽을 뻔 한 적이 있소. 그때부터 난 우리 종족이 더 이상 희생되거나 아니면 그보다 더 끔찍한 일이 발생하기 전에 이 사태를 막겠다고 맹세했소.\n\n이미 어둠의 해안에서 오염의 단서가 될만한 것을 몇 가지 발견했지만, 광범위한 징후는 아직 찾아내지 못했소. 펄볼그들에 대한 조사를 계속하는 게 좋을 것 같소. 놈들의 야영지를 정찰하다가 오염의 징후를 발견하게 되면 내게 좀 알려 주겠소?", progress = nil, completion = "정말 끔찍한 소식이군.\n\n펄볼그 녀석들이 아우버다인에 이렇게나 가까이 접근했으니 전투 준비는 불가피할 것 같소.\n\n알려줘서 고맙소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[985] = {title = "거대한 위협", objective = "검은나무일족 길잡이 8마리와 풍수사 5마리를 처치한 다음 아우버다인에 있는 테렌디스에게 돌아가십시오.", description = "그대의 정찰 실력은 충분히 입증되었소. 그렇다면 이제 적들에 맞서 싸우는 능력을 보여주는 건 어떻소? 정면 공격보다는 잠행과 침투가 더 적성에 맞을 수도 있지...\n\n임무를 맡을 자신이 있다면 현재 우리에게 가장 큰 위협이 되고 있는 아우버다인 남쪽 펄볼그 야영지로 가시오. 그곳에는 검은나무일족들이 있을 것이오. 검은나무일족 길잡이 8마리와 검은나무일족 풍수사 5마리를 처치한 다음 내게 돌아오시오.", progress = nil, completion = "옷에 묻은 피를 깨끗이 닦으시길! 임무를 위해 저질러야 했던 살생에 대해서도 애통해 하지 마시오. 그대 덕분에 이곳 아우버다인 주민들은 안심할 수 있게 되었소. 진심으로 감사드리오. 비록 악마의 이끼로 인한 위협이 어둠의 해안에 아직 남아 있긴 하지만 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[986] = {title = "사라진 주인", objective = "고급 달표범 모피 5필을 찾아 아우버다인에 있는 테렌디스에게 가져가야 합니다.", description = "그대는 이미 내게 큰 도움을 주었소. 미안하지만 한 가지 부탁이 더 있는데... 그림클로와 그의 주인 볼코르를 좀 도와 주시겠소? 그 일을 하려면 그대에게 마법 망토가 필요하오. 볼코르를 찾아다니는 동안 어둠의 해안에 사는 짐승들에게 방해를 받지 않고 다닐 수 있도록...\n\n망토를 만들려면 달표범이나 덩치큰 달표범을 잡아 고급 달표범 모피 5필을 구해와야 하오. 여기서 남쪽에 있는 성난굽이 강 근처로 가거나 아니면 더 멀리 남쪽으로 잿빛 골짜기 근처에 가면 그 맹수들을 찾을 수 있을 거요.", progress = "망토를 만들어 주기 전까진 볼코르를 찾아 나서게 할 수 없소.", completion = "이거면 훌륭하오. 즉시 망토를 만들도록 하겠소. 조금만 기다려 주시오.\n\n참, 그리고 일단 망토의 마법을 사용하고 나면 다른 이와의 접촉에 제약을 받게 되오. 가능하면 대화 외에는 다른 이들과 부딪히지 않도록 하시오. 그 이상 접촉할 경우 환영이 사라지고 말 테니까...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[990] = {title = "잿빛 골짜기로의 여정", objective = "잿빛 골짜기에 있는 레이네 울프러너를 찾아가야 합니다.", description = "반갑습니다. 레이네 울프러너님께서 잿빛 골짜기 내의 도시 아스트라나르에서 그대를 기다리고 계십니다. 그곳의 상황이 그대의 도움으로 조금은 나아졌으면 합니다.\n\n남쪽으로 길을 잘 따라가시면 문제 없이 아스트라나르를 찾아갈 수 있을 것입니다.", progress = nil, completion = "아, 어둠의 해안에서 온 &lt;class&gt;|1이시군요;시군요;. 그대를 이렇게 빨리 이곳으로 보내다니 셀라린이 아주 잘 판단했군요. 이곳까지 오는 동안 기력이 많이 떨어지지 않았길 바랍니다. 그대가 우리를 도와준다면 이곳 상황도 많이 나아질 것입니다.\n\n우선 전 아스트라나르 시민들과 얘기부터 좀 해야 할 것 같군요. 이 사람들에겐 당신의 도움이 절실할 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[991] = {title = "레이네의 정화", objective = "잿빛 골짜기에서 테로니스를 찾아야 합니다.", description = "내 오랜 친구 한 명도 이곳 잿빛 골짜기에서 센티널을 돕고 있습니다. 그런데 그가 며칠째 돌아오지 않고 있답니다.\n\n이곳 주민들을 공격하는 펄볼그를 막을 수 있는 물건이 있는데, 그것은 지금은 죽고 없는 한 사악한 마법사가 만든 마법봉이랍니다. 그는 마법봉을 찾는 일에 앞장섰었답니다.\n\n이곳을 떠나기 전, 그는 마법봉을 사용하는데 꼭 필요한 보석을 찾아야 한다고 말했습니다.\n\n그리고 그 보석이 서쪽 산기슭에 있는 팔라딤 호수의 제단에 숨겨져 있을지도 모른다고 했다는군요. 그곳이 침략당하기 전부터 보석은 거기 있었다는군요.\n\n제발, 내 친구를 좀 찾아 주세요.", progress = nil, completion = "테로니스의 상처 입은 시체가 섬 가운데 놓여 있습니다.\n\n그의 시체에 나 있는 깊은 상처는 멀록의 무기와 발톱이 만든 것이 분명합니다. 무슨 이유에서인지 멀록들이 시체를 버리고 갔습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[992] = {title = "가젯잔 수자원 측량", objective = "슬픈모래 감시탑의 물 웅덩이 부근에서 추출 전의 탐사장치를 사용하십시오. 다 채웠으면 가젯잔에 있는 선임측량사 피즐도저에게 추출한 탐사장치를 가져가야 합니다.", description = "가젯잔 수자원개발회사에 임시 후임측량사 자리가 비어 있는데 혹시 관심 있소?\n\n유목민들이 우리 우물을 몽땅 차지하는 바람에 새로운 수원을 찾아야만 살 판이오! 황량한 사막에도 물은 있지만, 머리를 잘 굴려야만 차지할 수 있지.\n\n이 탐사장치를 슬픈모래 감시탑 근처에 있는 물 웅덩이에 갖고 가서 물 견본을 받아 오시오. 아마 그 주변에 가면 트롤들이 있을 거요. 다 끝나거든 추출한 탐사장치를 내게 가져오시오!", progress = "어서 오시오, 후임측량사! 벌써 임무를 완수했소?", completion = "뭐라고? 기어다니는 괴상한 생물들에게 습격을 받았다고? 아, 가젯잔 수자원개발회사에 불안한 조짐인데, 아주 불안해...\n\n미리 괴상한 곤충형 생물들이 있다는 소문을 말해줄 걸 그랬나 보군. 사막에 그나마 남은 물을 모조리 빨아들이고 다니고 있다네. 처음에는 그냥 헛소린 줄로만 알았거든. 그렇지 않아도 유목민들 때문에 골치가 아픈데 말이야... 또 허튼소리를 해대는 줄 알았지. 뭐, 이제 사실인 걸 확인했으니 그나마 다행이지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[993] = {title = "사라진 주인", objective = "어둠의 해안에 있는 볼코르를 찾아서 마법 달표범 망토를 주어야 합니다.", description = "망토가 완성됐소. 이제 볼코르를 찾으러 떠날 때가 왔소. 부디 너무 늦지 않았기를 바랄 뿐이라오.\n\n망토의 마법은 5분 정도로 오래가지 않는다오. 그러니 신중하게 사용하도록 하시오. 내 생각엔 그림클로를 찾은 후에 사용하는 게 좋을 것 같소만...\n\n그림클로가 말한 게 사실이라면 여기서 남쪽에 있는 동굴에 가면 볼코르를 찾을 수 있을 거요. 그림클로가 길가에서 그대를 기다리고 있을 거요. 그를 만나면 손을 흔들어 신호를 보내시오. 그러면 볼코르가 있는 방향을 알 수 있을 것이오.", progress = nil, completion = "다행이오! 테렌디스님께서 날 도와 줄 이를 보내셨구려...\n\n달표범 망토도 보내시다니...&lt;콜록&gt; 고맙소, 으... 고통스럽군...\n\n어떻게 피할 새도 없이 펄볼그들에게 당하고 말았소. 미안하지만 잠시만 기다려 주겠소? 조금 쉬고 나면 얘기를 계속할 수 있을 것 같소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[994] = {title = "무력 탈출", objective = "길에 이를 때까지 볼코르를 보호한 다음 아우버다인에 있는 테렌디스와 대화하십시오.", description = "그래요, 그렇게 합시다. 일단 준비가 되는 대로 즉시 이곳을 빠져나간 다음, 적진을 뚫고 그림클로가 기다리고 있는 길까지 가는 거요. 그곳에 이르면 각자 가도록 합시다.\n\n테렌디스님께서 그대의 얘기를 듣고 싶어할 테니 이곳을 빠져나간 다음 아우버다인으로 곧장 가도록 하시오.", progress = nil, completion = "무사히 돌아와 줘서 기쁘군. 그대가 볼코르를 도와준 걸 보니 앞으로 이 어둠의 해안과 그 밖의 다른 곳에서 겪게 될 다른 문제들도 잘 극복할 수 있으리란 믿음이 생기는구려.", rewards = "다음과 같은 것들을 받습니다:\n\n견실한 허리띠"},
[995] = {title = "은밀한 탈출", objective = "펄볼그 동굴을 탈출한 다음 아우버다인에 있는 테렌디스를 만나십시오.", description = "좋소, 그럼 여기서 몰래 빠져나갑시다. 준비가 되면 바로 출발합시다.\n\n탈출한 후에는 아우버다인으로 돌아가 테렌디스님을 만나야 한다는 걸 명심하시오. 나는 따로 그곳으로 가겠소. 아마 당신보다는 빨리 도착할 것이오.", progress = nil, completion = "무사히 돌아와 줘서 기쁘군. 그대가 볼코르를 도와준 걸 보니 앞으로 이 어둠의 해안과 그 밖의 다른 곳에서 겪게 될 다른 문제들도 잘 극복할 수 있으리란 믿음이 생기는구려.", rewards = "다음과 같은 것들을 받습니다:\n\n스카라베 반바지"},
[996] = {title = "오염된 바람꽃", objective = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩은 것 같고 독성을 품고 있는 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩은 것 같고 독성을 품고 있는 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "바람꽃에 세나리온 식물 고약 두 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[997] = {title = "데날란의 흙", objective = "알아메스 호수에 있는 데날란에게 귀한 흙을 가져가야 합니다.", description = "남쪽으로 가는 길이신가요? 알아메스 호수로요? 그렇다면 그대에게 부탁할 일이 있는데...\n\n우리 동료인 데날란이 그 호수의 동쪽 가장자리 부근에 야영지를 설치하고 텔드랏실의 식물 생태를 연구하고 있어요. 그는 다르나서스에서 가져온 귀한 흙 한 꾸러미를 보내 달라고 요청했는데 물건이 최근에야 이곳 돌라나르에 도착해서 많이 늦어지고 말았죠.\n\n이 꾸러미를 그에게 좀 가져다주시겠어요?", progress = "내게 볼일이라도 있소?", completion = "아, 이제야 왔군! 오랫동안 이 귀한 흙이 도착하기를 기다렸소. 아직 깨끗해야 할 텐데...\n\n참 고맙소이다. 기꺼이 귀한 시간을 내어 우릴 도와 주다니 그대는 참 친절하신 분이구려.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[998] = {title = "오염된 바람꽃", objective = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩은 것 같고 독성을 품고 있는 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩은 것 같고 독성을 품고 있는 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "바람꽃에 세나리온 식물 고약 두 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[999] = {title = "꿈이 악몽으로 바뀌면", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1000] = {title = "새로운 미개척지", objective = "썬더 블러프의 장로의 봉우리에 있는 대드루이드 하뮬 룬토템을 찾아가 세나리온 의회의 칼림도어 미개척지 탐험 지원자 모집에 대해 얘기를 나눠야 합니다.", description = "주목하시오!\n\n세나리온 의회에서는 칼림도어의 광활한 미개척지를 탐험할 건장하고 능력 있는 자들을 찾고 있소! 타나리스와 가젯잔에서 서쪽으로 멀리 떨어진 곳에는 상상도 못할 위험이 도사리는 금단의 황무지가 펼쳐져 있는데, 세나리온 의회에서는 그 일을 대신해줄 명예롭고 뜻 있는 지원자들을 찾고 있는 것이오.\n\n관심이 있는 자들은 모두 세나리온 의회에 알현을 요청하도록 하시오. 더 자세한 얘기를 듣고 싶은 자는 썬더 블러프의 장로의 봉우리에 있는 대드루이드 하뮬 룬토템을 찾아가 보시오!", progress = nil, completion = "어서 오게, &lt;class&gt;|1이여;여;.\n\n자네 같은 인물이 자연의 안녕에 관심을 가지고 있다니 기쁘군. 그대가 이룬 업적에 대해서는 익히 들은 바 있어 환영하는 바이네. 그대가 이렇게 내 앞에 서 있으니 세나리온 의회에서 도와줄 사람을 제대로 찾은 것 같다는 확신이 서는군.\n\n달숲에 있는 세나리온 의회와 우리의 관계는 종족이나 정치적인 차이를 초월하는 것이라네. 세나리온 의회를 위해 일하는 동안 이 사실만 명심한다면 아주 잘 해낼 수 있을 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1001] = {title = "버즈박스 411", objective = "버즈박스 411 근처 깊은 바다에 있는 어둠의해안 트레샤돈에게서 트레샤돈의 눈 3개를 모아야 합니다.", description = "기계에서 작은 소리가 들립니다.\n\n\"위즈뱅이에요! 다음 버즈박스는 아우버다인 북쪽의 해변 어딘가에 있어요.\n\n그 버즈박스의 번호는 411이고 수리하려면 트레샤돈의 눈 3개가 필요해요. 해안 주변에서 찾을 수 있죠. 어둠의해안 트레샤돈들... *딸꾹* 너무 수고스러운 부탁을 하는 것 같군요.\n\n지난번처럼 버즈박스에 눈 3개를 넣으면 기계에서 뭔가 좋은 게 보상으로 튀어나올 거예요. *딸꾹* 네? 아, 아녜요. 전 괜찮아요!\"", progress = "기계의 덮개가 열려 있는 것이 마치 트레샤돈의 눈 3개를 넣어 주기를 기다리는 것 같습니다.", completion = "트레샤돈의 눈을 안에 넣자 버즈박스가 작동하는 소리가 들립니다. 그리고 곧 익숙한 목소리가 작게 들립니다.\n\n\"햐... 역시 게살 와인이 최고라니까...\" *딸꾹!*\n\n\"어? 벌써 고쳤군요. 정말 빠르네요. 고칠 게 또 있는데 계속 도와줄 수 있나요?\"\n\n술을 따르는 소리와 꿀꺽꿀꺽 목으로 넘기는 소리가 들리는 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1002] = {title = "버즈박스 323", objective = "달표범 송곳니 6개를 모아 버즈박스 323에 넣어야 합니다.", description = "버즈박스에서 들리는 잡음에 위즈뱅의 목소리가 섞여 있습니다.\n\n\"다음 버즈박스는 323번이고, 아우버다인 북쪽에 있죠. 그런데 내 술병이 어디 갔더라? 이런... 참, 다리 근처에 있으니까 쉽게 찾을 수 있을 거라고요.\"\n\n위즈뱅이 무언가 잘 알아들을 수 없는 말을 한 후에 술 따르는 소리가 크게 들립니다.\n\n\"이번에는 달표범 송곳니...6개...\"", progress = "아직 달표범 송곳니 6개를 기계 안에 넣지 않았는데도 기계에서 잡음과 알아듣기 힘든 노움의 목소리가 들립니다. 다른 누군가가 이 기계를 벌써 고친 것일까요?", completion = "버즈박스가 갑자기 작동하기 시작하고 감이 먼 음성이 들리기 시작합니다.\n\n\"이번에도 잘 고쳤군요. 정말 훌륭한... 딸꾹... 또 다른 걸 수리할 생각이 없다면 그만 갈 길이나 가 보세요!\"", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1003] = {title = "버즈박스 525", objective = "아우버다인 남쪽에 있는 엉겅퀴불곰에게서 불곰 가죽 4개를 모아 버즈박스 525에 집어넣어야 합니다.", description = "기계에서 나는 끓는 듯한 소리와 물 떨어지는 소리 너머 위즈뱅의 혀 풀린 목소리가 들려 옵니다.\n\n\"다음 거는 힉... 길을 따라 딸꾹... 남쪽으로 한참 가야 해요. 찾기가 그리 힘들진 딸꾹... 않을 거예요. 길 옆 딸꾹... 울타리 근처에 있거든요. 내가 덤불 속에 힉... 숨겼던 것 같아요. 덤불 속에... 딸꾹... 헤헤헤... 그래요, 딸꾹... 버즈박스 525에는 엉겅퀴불곰의 가죽을 딸꾹... 집어넣어야 해요. 딸꾹... 버즈박스 525는 꽤나 많이 먹어야 한다고요. 힉... 헤헤헤...\"\n\n기계가 멈추었다가 꿀꺽거리는 소리가 더 나더니 갑자기 기계가 다시 돌아가기 시작합니다.\n\n\"4개는 있어야지!\"", progress = "버즈박스 525에서 노랫소리가 들려 옵니다.\n\n\"게살 와인은 달콤하고, 트레샤돈 맥주는 시원하고, 달표범 위스키는 톡 쏘지. 하지만 엉겅퀴곰 맥주만큼 좋은 건 없다네. 곧 이 술을 모두 맛보게 되리!\"\n\n노래는 계속 반복되고 버즈박스의 입구는 불곰 가죽 4개를 기다리는 듯 열려 있습니다.", completion = "\"가죽은 다 집어 힉... 넣으셨어요? 아주 잘했어요... 에? 뭐, 기계 속에 딸꾹... 재료를 넣지 않아도 당신한테 말을 할 수 있다는 걸 딸꾹... 알아차리셨겠군요. 그래도 고장났다고 한 건 힉... 정말이었어요!\n\n버즈박스는 통신 도구일 뿐 아니라 술을 만드는 데도 쓸 수 있거든요. 딸꾹... 속여서 기분 나쁘다면 미안해요. 하지만 나이트 엘프들은 딸꾹... 자기네 마을 안에서 제가 술을 만들어 파는 걸 탐탁지 않게 여겨서요. 수고에 대한 감사의 표시로 이 상자 안에 힉... 뭔가 특별한 걸 넣어 놓았어요. 잘 쓰시라고요!\"", rewards = "다음과 같은 것들을 받습니다:\n\n위즈뱅의 자루위즈뱅의 특별주"},
[1004] = {title = "새로운 미개척지", objective = "썬더 블러프, 장로의 봉우리에 있는 대드루이드 하뮬 룬토템을 찾아가 세나리온 의회의 칼림도어 개척 지원자 모집에 대한 얘기를 나눠야 합니다.", description = "영웅은 들으십시오!\n\n세나리온 의회에서는 칼림도어의 광활한 땅을 개척할 건장하고 실력있는 모험가들을 찾고 있습니다! 타나리스와 가젯잔에서 서쪽으로 멀리 떨어진 곳에 펼쳐져 있는 금단의 황무지에는 상상도 못할 위험이 도사리고 있습니다. 세나리온 의회를 대신해 개척 임무를 맡아줄 용맹스럽고 뜻있는 지원자들을 찾고 있는 것입니다.\n\n관심이 있는 이들은 모두 세나리온 의회에 알현을 청하십시오. 썬더 블러프, 장로의 봉우리에 있는 대드루이드 하뮬 룬토템을 찾아가면 자세한 얘기를 들을 수 있습니다!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1005] = {title = "문 너머에 있는 적", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1006] = {title = "문밖의 적", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1007] = {title = "고대 조각상", objective = "조람 해안 근처에서 야영하고 있는 탈렌에게 고대 조각상을 가져가야 합니다.", description = "<class>|1이여;여;, 그대에게 부탁할 일이 있소.\n\n일전에 작은 배를 타고 물속에 가라앉은 조람의 폐허 위를 지나고 있을 때 나가들이 물속에서 튀어나와 발톱으로 날 공격했소. 몸에 지닐 수 있는 보급품만 갖고 이 보잘것없는 야영지로 도망쳤소.\n\n하지만 해변에 이르러 달리는 동안 내 소중한 물건을 잃어버리고 말았소.\n\n북쪽 해안가를 따라 내가 숨었던 장소를 찾아 고대 조각상을 되찾아 주시오. 내가 조람 해안의 위험을 무릅썼던 건 바로 그 조각상 때문이라오.", progress = "조각상은 찾았소?", completion = "조각상을 찾았구려! 고맙소!\n\n조람의 고대 도시는 많은 비밀을 간직하고 있소. 그리고 이 조각상은 그 중 많은 비밀에 대한 열쇠가 될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1008] = {title = "조람 해안", objective = "아스트라나르에 있는 신드렐 스위프트파이어에게 성난지느러미일족의 머리 20개를 가져가야 합니다.", description = "조람 해안으로 알려진 북서쪽 바닷가에 악당들이 숨어 있습니다.\n\n그곳은 대륙이 분리되는 동안 파괴되어 바다 밑에 가라앉은 도시, 조람이 잠들어 있는 곳이랍니다. 오랜 세월 동안 나이트 엘프는 조람을 생각하지 못하고 지내 왔습니다. 아니, 조람이라는 도시에 대해 거의 잊어 버렸었다고 할 수 있겠군요.\n\n그런데 지금, 무슨 이유에서인지 모르지만 나가들이 다시 돌아왔습니다. 그들이 돌아온 이유는 별로 중요하지 않습니다만 반드시 그들을 섬멸해 버려야 합니다!\n\n임무를 완수한 후 내게 돌아와 주십시오.", progress = "나가들이 우리 해안을 침범하도록 놔둘 수는 없습니다. 따라서 그대가 조람 해안으로 가서 임무를 완수하는 것은 아주 중요한 일입니다.", completion = "잘하셨습니다. 조람 해안에서 나가를 상대로 펼친 그대의 활약은 칭송할 만합니다.\n\n그대의 공적이 쉽게 이루어진 게 아니라는 건 잘 알고 있습니다. 나가의 힘과 지략은 나이트 엘프 사이에서도 잘 알려져 있답니다. 우리는 그들과 오랜 역사를 같이해 왔기 때문에 매우 잘 알고 있지요.\n\n다시는 되풀이하고 싶지 않은 역사이지만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1009] = {title = "루젤", objective = "조람 해안 근처에 있는 탈렌에게 조람의 반지를 가져가야 합니다.", description = "그대가 이 고대 조각상에 있는 자물쇠의 열쇠를 찾지 못하면 이 조각상의 비밀은 영원히 풀리지 않을 것이오.\n\n사실 그 열쇠는 조람의 반지라고 한다오. 그 반지는 대륙이 분리되서 이 도시가 물속에 수장되기 전, 도시의 지배자가 소유하던 것이오.\n\n최근 나가들이 몇 년 동안이나 행방이 묘연했던 그 반지를 발견했소.\n\n그들의 우두머리인 루젤은 조람의 북쪽 변방에 있는 한 섬에 살고 있소. 날 위해 반지를 꼭 좀 찾아 주시오.", progress = "조람의 반지는 도시 안의 모든 자물쇠를 열 수 있는 열쇠라고 전해지고 있소. 반지는 찾아왔소?", completion = "반지를 찾았구려! 고맙소. 답례로 이걸 받아 주시오. 또한 그대가 해준 일을 영원히 잊지 않을 거란 걸 알아 주시기 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n고대의 로브"},
[1010] = {title = "배스랜초", objective = "잿빛 골짜기에 있는 오렌딜 브로드리프에게 배스랜초 5개를 가져가야 합니다.", description = "북쪽에 있는 배스랜 서식지의 오래된 폐허에서만 자라는 풀이 있소. 배스랜초라는 약초인데 영혼의 병을 치료한다고 알려져 있다오.\n\n마을에 병든 아이가 하나 있는데 내가 보기엔 단순히 몸에만 병이 든 것은 아닌 것 같소. 그대가 배스랜 서식지로 가서 배스랜초를 좀 찾아다 주지 않으시겠소? 그 병을 제대로 치료하려면 배스랜초가 필요할 것 같소.\n\n배스랜 서식지는 마에스트라 주둔지 북쪽, 어둠의 해안 남쪽 경계에 있다오.", progress = "배스랜초는 모으셨소? 시간이 갈수록 아이의 건강이 나빠지고 있소.", completion = "아, 배스랜초를 가져왔구려! 이제 아이를 위한 치료제를 만들 수 있겠군. 부디 약효가 있어야 할 텐데...\n\n그런데 배스랜 서식지에 포세이큰들이 있다고 했소? 저런, 큰 문제로군. 참으로 큰 일이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1011] = {title = "포세이큰의 역병", objective = "숲의 노래에 있는 케이네스 스틸윈드에게 역병 견본 하나를 가져가야 합니다.", description = "언데드 호드 군대인 포세이큰이 잿빛 골짜기로 숨어들어와 이곳 폐허와 언덕을 어슬렁거리고 있소. 우리 생각엔 그들이 나이트 엘프의 땅에 질병을 퍼뜨리려는 것 같소. 이건 꼭 확인해 봐야 할 문제요.\n\n포세이큰들은 남쪽의 도르다닐 지하굴 근처에 야영지를 설치하고 독약과 질병을 만들어 병 안에다 담고 있소. 그 야영지로 들어가 역병 견본을 훔쳐 가져다주시오. 그러면 내가 실험을 통해 그 용도를 밝혀내겠소.", progress = "그들의 야영지는 발견했소? 역병 견본도 가져왔소?", completion = "수고했소. 이제... 이 병의 내용물을 몸소 시험해 보면 포세이큰의 계략을 밝혀낼 수 있을 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1012] = {title = "미쳐버린 드루이드", objective = "드루이드 지도자인 타닐 다크우드, 우실 문콜, 마보리스 클라우즈브레이크를 처치한 다음 숲의 노래에 있는 케이네스 스틸윈드에게 돌아가십시오.", description = "포세이큰의 독에 감염되어 괴로워하던 중 환영을 보았소. 도르다닐 지하굴 안의 드루이드들을 보았는데, 그들은 온몸에 독이 퍼진 상태에서... 언데드들에게 죽임을 당하고 있었소! 이제 그들은 영혼이 육체에서 분리된 떠돌이 유령이 된 데다가 미쳐 버리기까지 했다오.\n\n드루이드의 영혼들이 안식을 찾을 수 있도록 도르다닐 지하굴로 들어가서 한 때는 위대한 지도자였던 타닐 다크우드, 우실 문콜과 마보리스 클라우즈브레이크를 처치해 주시오.\n\n모두 처치한 다음 내게 돌아오시오.", progress = nil, completion = "도르다닐 드루이드들의 고통이 약해진 게 느껴지는 걸 보니 그대가 임무를 완수해 주었구려.\n\n어려운 임무를 잘 수행해 주었소. 그대가 처치한 영혼들은 사악한 포세이큰에 의해 미쳐버린 것일 뿐... 이제 불쌍한 나머지 다른 영혼들이 안식을 찾기를 바랄 뿐이오.", rewards = "다음과 같은 것들을 받습니다:\n\n에밀의 검"},
[1013] = {title = "우르의 책", objective = "언더시티의 연금술 실험실에 있는 관리인 벨두거에게 우르의 책을 가져가야 합니다.", description = "그림자송곳니 성채에 우르의 책이 보관되어 있소. 그 책은 내 소장 목록에 포함할 만한 가치가 충분한 것이지. 우르는 스컬지가 도래하기 전 달라란에서 가장 훌륭한 마법사였소이다. 다른 세계에 대한 그의 연구는 포세이큰의 몇몇 무리에게는 매우 가치가 높지.\n\n그림자송곳니 성채에 들어가 이 책을 찾아 주시오. 그걸 내게 가져오면 학문 연구에 공헌한 당신에 대해 어둠의 여왕님께 보고하도록 하겠소이다.", progress = "책은 찾았소?", completion = "아주 좋아. 내가 수집하고 있는 우르의 연구 서적 목록에 추가하기에 손색이 없군. 그의 지식은 위대했지만 대단한 자제력으로 진정한 힘을 사용하지 않도록 자신을 다스렸소. 그 후 스컬지가 그의 힘을 시험했을 때는 이기지 못하고 그들에게 넘어갔지.\n\n우리 포세이큰은 그런 나약함을 용납할 수 없소. 살아남기 위해... 그리고 정복하기 위해서 말이지.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n불곰 장화강철죔쇠 팔보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1014] = {title = "아루갈의 최후", objective = "아루갈을 처치하고 그 증거로 그의 머리카락을 공동묘지에 있는 달라 던위버에게 가져가야 합니다.", description = "아루갈이 아직 그림자송곳니 성채에 버젓이 살아 있소.\n\n아루갈을 처치하기 전에는 은빛소나무 숲을 어둠의 여왕님을 위한 전략 요새로 차지할 수 없소. 그의 마법은 내가 완전히 없애겠지만, 아루갈이 한 짓에 마땅한 형벌을 받도록 하는 것은 당신 손에 맡기겠소.\n\n그림자송곳니 성채로 가서 아루갈의 사악한 마법 주문을 영원히 잠재워 버리시오. 그리고 그 사악한 마법사의 머리카락을 내게 가져오도록 하시오.", progress = "아루갈을 처치하면 로데론에서 어둠의 여왕님의 세력을 확장할 수 있을 것이오.", completion = "마침내 은빛소나무 숲이 그 비열한 아루갈의 악으로부터 자유로워졌군. 당신은 어둠의 여왕님을 위해 큰 공을 세웠으니 반드시 노고에 대한 보상이 있을 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신비한 지능\n\n다음과 같은 것들을 받습니다:\n\n실바나스의 인장"},
[1015] = {title = "새로운 미개척지", objective = "다르나서스의 세나리온 자치령에 있는 대드루이드 판드랄 스테그헬름을 찾아가 세나리온 의회의 칼림도어 미개척지 탐험 지원자 모집에 대한 얘기를 나눠야 합니다.", description = "영웅은 들으십시오!\n\n세나리온 의회에서는 칼림도어의 광활한 땅을 개척할 건장하고 실력 있는 모험가들을 찾고 있습니다! 타나리스와 가젯잔에서 서쪽으로 멀리 떨어진 곳에 펼쳐져 있는 금단의 황무지에는 상상도 못할 위험이 도사리고 있습니다. 세나리온 의회를 대신해 개척 임무를 맡아줄 용맹스럽고 뜻있는 지원자들을 찾고 있습니다.\n\n관심이 있는 이들은 모두 세나리온 의회에 알현을 청하십시오. 다르나서스에 있는 대드루이드 판드랄 스테그헬름을 찾아가면 자세한 얘기를 들을 수 있습니다!", progress = nil, completion = "자네 같은 일개 &lt;class&gt;|1이;가 말을 걸어줬으면 하고 기다리는 것처럼 내가 한가해 보이는가? 아니... 일단 오늘 끝내야 할 중요한 일은 접어두고 자네가 어딘가에서 뭔가를 찾는 걸 도와주기로 하지. 어쨌든 자네는 다르나서스... 아니, 텔드랏실 전체의 안녕보다는 하찮은 물건 찾는 일이 더 중요할 테니까.\n\n달숲에 사는 바보 같은 녀석들, 허구한 날 도움을 요청하면서 내 귀한 시간을 빼앗더니만 이제는 이런 일까지 맡긴단 말이야?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1016] = {title = "정령의 족쇄", objective = "온전한 정령의 족쇄 5개를 모아서 예언의 두루마리를 사용한 후, 실바람 산장에 있는 파수꾼 벨레네 스타스트라이크에게 예언된 두루마리를 가져가야 합니다.", description = "이 예언의 두루마리를 받으십시오. 이것으로 저 정령들을 만든 게 누군지 알아낼 수 있을 겁니다. 단, 정령들에게서 두루마리의 마법을 강화할 재료를 빼앗아 와야 합니다. 아마 그들의 족쇄 정도면 쓸만할 겁니다.\n\n온전한 족쇄 몇 개면 충분하죠. 그 외의 다른 족쇄는 이 임무에는 쓸모가 없겠지만 상인들이 관심을 보일 만한 물건들입니다. 팔 생각이 있다면 모아 오셔도 좋겠죠. 온전한 족쇄를 손에 넣으면 두루마리를 사용해 보십시오. 그 결과를 가지고 저를 다시 찾아오시면 이후의 일을 계속 진척시켜 나가도록 하죠.", progress = "예언의 두루마리를 예언된 두루마리로 바꿀 수 있는 온전한 족쇄를 찾기는 쉽지 않을 겁니다. 정령들을 처치할 때 족쇄가 쉽게 부서지기 때문이죠. 다른 이와 족쇄를 교환해서 필요한 족쇄를 모을 수도 있습니다만, 혹시 이미 두루마리의 비밀을 밝혀낸 것인가요?", completion = "훌륭합니다. 이거라면 필요한 정보를 얻을 수 있을 겁니다. 우리의 샘을 타락한 정령들로 더럽히고 있는 마법사를 처단하는 것에 대해 어떻게 생각하십니까? 저는 잿빛 골짜기와 그 너머까지 퍼진 타락을 생각하면 속이 다 뒤틀릴 지경입니다. 고작 마법사 하나가 활개를 치며 우리의 땅을 파괴하려 하다니 참을 수가 없군요. 반드시 대가를 치르게 하고야 말 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1017] = {title = "물의 정령 배후의 마법사", objective = "사릴루스 파울본을 처치하고 그 증거로 그의 머리카락을 실바람 산장에 있는 파수꾼 벨레네 스타스트라이크에게 가져가야 합니다.", description = "불모의 땅에서 이렇게 많은 물의 정령을 조종할 수 있는 언데드 마법사는 한 명밖에 없습니다. 이런 짓을 하려 들 만큼 어리석은 자도 그자뿐이고... 바로 사릴루스 파울본이라는 자인데, 아마 지금 공포의 안개봉우리 꼭대기에 앉아 날 비웃고 있을 겁니다.\n\n적진으로 가서 이 악당을 반드시 처치하고, 파수대를 괴롭히면 어떻게 되는지 똑똑히 보여 줘야 합니다. 이미 그자의 바보 같은 만행은 충분히 겪었으니까요.\n\n사릴루스를 처치하고 그 증거를 가지고 오십시오. 하지만 조심하시기 바랍니다. 호드가 그대를 노리고 있을지도 모르니...", progress = "임무를 완수했습니까? 사릴루스 파울본을 처치했나요?", completion = "이제 그자의 불쾌한 미소를 볼 일은 영원히 없겠군요. 정말 잘하셨습니다. 여기 이 엘룬의 빛을 받으십시오. 동지들을 모두 잃어버리고 그대의 생명조차 위급하다고 생각될 때 이걸 마시도록 하십시오. 엘룬의 가호가 그대를 지켜줄 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n엘룬의 빛"},
[1018] = {title = "새로운 미개척지", objective = "썬더 블러프의 장로의 봉우리에 있는 대드루이드 하뮬 룬토템을 찾아가 세나리온 의회의 칼림도어 미개척지 탐험 지원자 모집에 대해 얘기를 나눠야 합니다.", description = "주목하시오!\n\n세나리온 의회에서는 칼림도어의 광활한 미개척지를 탐험할 건장하고 능력 있는 자들을 찾고 있소! 타나리스와 가젯잔에서 서쪽으로 멀리 떨어진 곳에는 상상도 못할 위험이 도사리는 금단의 황무지가 펼쳐져 있는데, 세나리온 의회에서는 그 일을 대신해줄 명예롭고 뜻 있는 지원자들을 찾고 있는 것이오.\n\n관심이 있는 자들은 모두 세나리온 의회에 알현을 요청하도록 하시오. 더 자세한 얘기를 듣고 싶은 자는 썬더 블러프의 장로의 봉우리에 있는 대드루이드 하뮬 룬토템을 찾아가 보시오!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1019] = {title = "새로운 미개척지", objective = "다르나서스의 세나리온 자치령에 있는 대드루이드 판드랄 스테그헬름을 찾아가 세나리온 의회의 칼림도어 미개척지 탐험 지원자 모집에 대해 얘기를 나눠야 합니다.", description = "영웅은 들으십시오!\n\n세나리온 의회에서는 칼림도어의 광활한 땅을 개척할 건장하고 실력 있는 모험가들을 찾고 있습니다! 타나리스와 가젯잔에서 서쪽으로 멀리 떨어진 곳에 펼쳐져 있는 금단의 황무지에는 상상도 못할 위험이 도사리고 있습니다. 세나리온 의회를 대신해 개척 임무를 맡아줄 용맹스럽고 뜻있는 지원자들을 찾고 있습니다.\n\n관심이 있는 이들은 모두 세나리온 의회에 알현을 청하십시오. 다르나서스에 있는 대드루이드 판드랄 스테그헬름을 찾아가면 자세한 얘기를 들을 수 있습니다!", progress = nil, completion = "자네 같은 일개 &lt;class&gt;|1이;가 말을 걸어줬으면 하고 기다리는 것처럼 내가 한가해 보이는가? 아니... 일단 오늘 끝내야 할 중요한 일은 접어두고 자네가 어딘가에서 뭔가를 찾는 걸 도와주기로 하지. 어쨌든 자네는 다르나서스... 아니, 텔드랏실 전체의 안녕보다는 하찮은 물건 찾는 일이 더 중요할 테니까.\n\n달숲에 사는 바보 같은 녀석들, 허구한 날 도움을 요청하면서 내 귀한 시간을 빼앗더니만 이제는 이런 일까지 맡긴단 말이야?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1020] = {title = "오렌딜의 치료제", objective = "아스트라나르에 있는 펠투러스 화이트문에게 오렌딜의 치료제를 가져가야 합니다.", description = "병든 아이를 위한 치료제를 만들었소. 이걸 아스트라나르로 가져가 그 애 아버지인 펠투러스 화이트문이라는 이에게 전해 주시기 바라오.\n\n아스트라나르로 가려면 남쪽으로 길을 따라 가다가 동쪽으로 가면 되오.", progress = "누구신지는 모르겠지만, 죄송합니다. 지금은 이야기를 나눌 시간이 없군요. 우리 딸 렐라라가 큰 병을 앓고 있어서요.", completion = "이게 오렌딜이 보낸 거란 말인가요?\n\n그의 약초술과 치료술은 정말 훌륭하죠. 이 치료제가 제게 사라졌던 희망을 되살려 주는군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1021] = {title = "사악한 사티로스와 위험에 처한 드리아드", objective = "잿빛 골짜기 북동쪽에 있는 사비안에서 아닐리아를 찾아야 합니다.", description = "저기요, 당신이 누군지는 모르겠지만 전 도움이 필요해요. 우리 자매들이 사티로스에게서 세나리우스의 가지를 되찾으러 갔어요. 금방 돌아올 거라면서 갔지만 벌써 꼬박 이틀이나 지났거든요.\n\n<name>, 우리 자매들을 좀 찾아봐 주지 않겠어요? 무슨 일이 있는 건 아닌지 너무 걱정이 돼요. 그들은 멀리 북동쪽의 사비안에 있는 달샘으로 갔어요. 아무래도 무슨 문제가 생긴 것 같은데... 아닐리아를 찾아보세요. 그녀가 자매들을 이끌고 갔으니까요.", progress = nil, completion = "옆구리에 난 깊은 상처로 볼 때 아닐리아는 곧 숨이 끊어질 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1022] = {title = "울부짖는 골짜기", objective = "울부짖는 골짜기로 가서 멜탄드리스의 마법책을 찾아 읽어 본 다음 아에시나의 제단에 있는 파수꾼 멜리리아 프로스트섀도에게 돌아가십시오.", description = "북쪽 악령의 숲에 남아 있는 악마들을 몰아내기 위해 많은 자원과 시간을 투자해왔지만 아직 이렇다 할 성과를 거두지 못하고 있습니다. 어쨌든 악마로부터 잿빛 골짜기를 지켜낼 수는 있었지만 말입니다.\n\n북쪽 악령의 숲 가장자리 부근에 폐허가 된 멜탄드리스의 제단이 있는데 괴이한 늑대 인간들에게 점령당하고 말았습니다. 그들의 무시무시한 울음 소리 때문에 그 지역은 울부짖는 골짜기라고도 한답니다. 그 제단에 보관된 멜탄드리스의 마법책을 손에 넣으면 늑대 인간들이 온 이유를 알아내는데 도움이 될 겁니다.", progress = nil, completion = "멜탄드리스의 마법책은 이상한 방식으로 작동합니다. 직접 보고 오신대로 이 책에 기록된 마법들은 눈 앞에서 벌어집니다. 이 책이 어떻게 그런 힘을 얻게 됐는지는 아무도 모릅니다.\n\n하지만 엘룬의 낫을 받은 여사제 스타송이 틀림없이 더 자세한 내막을 알고 있을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1023] = {title = "레이네의 정화", objective = "빛나는 보석을 찾아 테로니스의 일지와 함께 아스트라나르에 있는 레이네 울프러너에게 가져가야 합니다.", description = "테로니스의 소지품을 뒤져보니 아직 상태가 양호한 일지가 나왔습니다.\n\n테로니스의 시체는 그대로 두고 일지만 챙깁니다.\n\n이제 테로니스가 찾고 있던 보석만 찾으면 됩니다. 레이네는 그 보석이 이 지역에 있다고 말했습니다. 어쩌면 지금은 멀록들이 가지고 있을지도 모릅니다.", progress = "아, 돌아왔군요.", completion = "정말 끔찍한 소식이군요. 테로니스가 죽다니...\n\n하지만 슬픔을 잠시 접어 두고 지금은 우리가 해야 할 일에 전념해야 합니다. 그리고 가능한 빨리 파수꾼 몇 명을 보내 테로니스의 시체를 수습하도록 해야겠습니다.\n\n이제 테로니스의 일지와 그가 찾던 보석도 구했으니, 그대가 그대신 임무를 완수할 수 있지 않을까요? 그의 죽음이 헛되지 않기를 바라는 마음입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1024] = {title = "레이네의 정화", objective = "북동쪽에 있는 달샘에서 셸드린을 찾아야 합니다.", description = "물론 그대가 직접 조사를 해봐야 알겠지만, 테로니스의 일지 내용에 따르면 이제 다르톨이 만든 마법봉의 나머지 조각들을 찾아야 할 때입니다. 우선 아이리스 호수 동쪽의 달샘으로 가 보십시오. 떠날 채비가 되는 대로 길을 따라가다가 왼쪽에 조그만 쉼터가 보이면 북쪽으로 가도록 하십시오.\n\n그곳에서 셸드린이라는 드리아드를 찾으면 그대에게 큰 도움을 줄 겁니다.\n\n보석을 잘 챙겨가도록 하십시오. 셸드린의 도움으로 마법봉을 다시 만들려면 반드시 필요할 테니...", progress = "엘룬께 영광을! 안녕하신가요?", completion = "아, 레이네가 그대를 보냈군요? 정말 심각한 일인가 보군요. 제가 어떻게 도와드리면 될까요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1025] = {title = "공격적 방어", objective = "썩은나무일족 보초 1마리, 썩은나무일족 펄볼그 2마리, 썩은나무일족 토템술사 10마리 및 썩은나무일족 전사 12마리를 처치한 다음 아스트라나르에 있는 레이네 울프러너에게 돌아가십시오.", description = "달샘으로 출발하기 전에 잿빛 골짜기 주민들의 안전을 위해 제 부탁을 들어주시지 않겠습니까? 그대의 능력을 시험해 보길 원한다면 말입니다.\n\n동쪽으로 난 길을 따라 가다가 팔파렌 강에 못 미친 곳에서 펄볼그들이 여행자들을 공격하고 있습니다. 그들의 비뚤어진 영혼은 공포를 즐기며 무고한 희생자들의 피로 배를 불리고 있답니다.\n\n그들을 처치해 지금까지 우리에게 해온 죗값을 치르게 해주십시오. 우리 센티널이 이 땅을 지킬 수 있도록 좀 도와주시기 바랍니다.\n\n길 남쪽에 놈들의 본거지가 있을 겁니다. 부디 조심하시길...", progress = nil, completion = "정말 수고 많았습니다. 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n촉촉한 옥수수 빵멜론 주스"},
[1026] = {title = "레이네의 정화", objective = "나무 열쇠와 다르톨의 변신마법봉의 조각을 찾아 달샘에 있는 셸드린에게 돌아가십시오.", description = "좀 더 좋은 소식이었으면 좋았을 것을...\n\n레이네의 말이 맞습니다. 전 다르톨이 만든 마법봉과 이 지역 내에 있는 나무정령에 대해 잘 알고 있답니다. 하지만 지금은 그 성질이 변질되고 오염되어 예전에 제가 알고 있던 것과는 많이 다릅니다.\n\n마법봉의 다른 조각을 구하려면 우선 그 조각이 들어 있는 상자의 열쇠를 찾아야 합니다.\n\n나무로 만들어진 그 열쇠는 이곳에서 북동쪽 방향, 악령의 숲 근처에 있는 나무정령 중 하나가 가지고 있습니다. 열쇠를 구하면 악령의 숲 가장자리에 있는 길 서쪽에서 작은 빈 터를 찾아보시기 바랍니다. 상자는 거기 어딘가에 숨겨져 있을 겁니다.", progress = "나무정령들이 오염됐단 사실은 정말 참을 수 없답니다. 어떻게라도 손쓸 방법이 있으면 좋을 텐데...", completion = "무사히 다시 돌아오시니 기쁘군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1027] = {title = "레이네의 정화", objective = "다르톨의 마법봉을 만들기 위한 마지막 조각을 찾아 달샘에 있는 셸드린에게 돌아가십시오.", description = "마법봉의 마지막 조각은 도르다닐의 드루이드들이 안전하게 보관하고 있습니다. 하지만 어디에다 숨겨뒀는지는 모르겠습니다. 큰 도움이 되지 못해 죄송하군요.\n\n제가 말씀드릴 수 있는 건 불모의 땅으로 향하는 길을 따라가야 한다는 것뿐입니다. 그 길 동쪽에 드루이드들의 거처가 있지만 방문해도 큰 도움은 얻지 못 할 겁니다. 왜냐하면... 정말 생각하기도 싫은 일이지만 그들은 최근에 살해되었기 때문입니다.\n\n마지막 조각을 찾으면 제게 가져와 주십시오. 마법봉을 복구하는 걸 도와드리겠습니다.", progress = "마법봉의 마지막 조각은 찾으셨습니까?", completion = "마지막 조각을 찾으셨군요? 그대와... 레이네를 위해서 정말 잘 됐습니다.\n\n드디어 마법봉을 복구할 수 있게 됐습니다. 그럼 이제 시작해볼까요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1028] = {title = "레이네의 정화", objective = "숨겨진 제단을 찾아 다르톨의 마법봉에 다시 마력을 불어 넣어야 합니다.", description = "자, 여기 완성된 마법봉을 받으십시오. 마법봉을 복구하는 건 별로 어렵지 않았지만 마법봉에 다시 마력을 불어넣을 수 있는 제단을 찾는 건 쉽지 않을 겁니다.\n\n하지만 이미 많은 일을 해낸 그대와 같은 분이 조금만 더 노력하면 이번 일도 그리 어렵지는 않을 것 같군요.\n\n이곳에서 남동쪽으로 가면서 계속 북쪽을 잘 살펴보도록 하십시오. 길을 찾기 힘들 테니 말입니다. 제단은 빈 터를 둘러싼 산 속에 숨겨져 있답니다.\n\n그곳에 도착한 후에는 마법봉을 제단 안에 놓기만 하면 됩니다. 나머지는 마법에 의해 저절로 이루어질 테니... 후훗.", progress = "제단과 이를 둘러싸고 있는 나무에서 은은하면서도 강력한 힘을 느낄 수 있습니다.\n\n마법봉을 제단 안에 놓자 제단이 빛나기 시작하면서 주위에서 신비로운 종소리가 납니다.", completion = "빛이 사라진 후 제단 바닥에 다시 마력이 부여된 마법봉이 놓여 있는 것이 보게 됩니다.", rewards = "다음과 같은 것들을 받습니다:\n\n다르톨의 변신마법봉"},
[1029] = {title = "레이네의 정화", objective = "아스트라나르에 있는 레이네 울프러너에게 돌아가십시오.\n\n제공된 아이템: \n", description = "레이네를 찾아 마법봉이 완성되었다고 알려 주시기 바랍니다. 그대가 해야 할 다음 일은 레이네가 알고 있을 겁니다.\n\n행운을 빕니다.", progress = nil, completion = "테로니스가 찾으러 갔던 마법봉을 복구했다고요? 정말 반가운 소식이 아닐 수 없군요.\n\n자신이 비극적인 최후를 맞은 후에도 그가 완수하려던 일이 계속 수행되고 있다는 걸 알면 테로니스도 자랑스럽게 생각할 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1030] = {title = "레이네의 정화", objective = "오염되지 않은 펄볼그를 찾아 다르톨의 변신마법봉의 힘을 사용하여 그와 대화하십시오.\n\n제공된 아이템: \n", description = "안타깝게도, 다르톨이 다음으로 하려던 일이 확실히 무엇이었는지는 모르겠군요.\n\n그가 마법봉의 힘에 대해 했던 말이 사실이라면 마법봉은 그대를 완전히 다른 모습으로 바꿔 줄 겁니다. 그런데 그게 어떤 모습인지는 몰라요.\n\n어쩌면 그는 마법봉의 힘을 빌어 오염된 펄볼그들에게 접근하려 했는지도 모릅니다. 하지만 아무리 그렇다고 해도 조심하지 않으면 그 짐승들에게 죽임을 당할 수도 있었을 텐데... 다르톨은 마법봉으로 자신의 모습을 바꿔 악마의 이끼에 오염되지 않은 펄볼그와 대화하려고 한 것 같습니다.\n\n미스트랄 호수의 남동쪽부터 찾아보세요.", progress = nil, completion = "그래, 우리 종족이 틀림없군. 그것도 아직 오염되지 않은 채 온전한...\n\n나이트 엘프들이 저지른 그 잔인 무도한 만행을 어떻게 피했는지는 모르겠지만 나 혼자만 무사한 게 아니라니 참 기쁘오.\n\n그 오만한 나이트 엘프들에 의해 우리 일족은 갓난아이들까지 죄다 오염되었소. 나 홀로 이렇게 일족으로부터 떨어져 지내게 된 것도 바로 놈들 때문이고 말이오. 전부 나이트 엘프 짓이지... \n\n지금도 밤이면 어둠을 밝히며 타고 있는 모닥불들이 보인다오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1031] = {title = "세나리우스의 가지", objective = "겔타리스를 처치하고 아에시나의 제단에 있는 일리야나에게 세나리우스의 가지를 돌려줘야 합니다.", description = "아닐리아는 떨리는 손으로 당신의 어깨를 잡아 끌어당깁니다. 가쁜 숨을 몰아쉬며 북쪽의 아치형 문을 가리킨 후 결국 숨을 거둡니다. \"겔타리스... 그가 갖고 있어요...\" 드리아드에게 세나리우스의 가지를 찾아 주는 것이 아닐리아의 마지막 소원이라는 것을 마음으로 느낄 수 있습니다.", progress = "자매들을 찾았나요? 아닐리아가 뭐라고 하던가요? 그런데 아닐리아는 어디에 있나요?", completion = "아닐리아가 죽었다고요? 아, 그럴 수가! 함께 숲 속에서 뛰놀던 때가 엊그제 같은데...\n\n이제 즐겁던 나날들도 모두 끝이군요...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n요정의 어깨보호대빛나는 미늘 벨트\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1032] = {title = "사티로스 처치", objective = "아에시나의 제단에 있는 일리야나에게 사티로스의 뿔 16개를 가져다주어야 합니다.", description = "아닐리아가 죽었다는 게 믿기지가 않는군요... 우리는 늘 숲 속에서 함께 뛰놀고는 했답니다. 정말 슬퍼요.\n\n저의 슬픔을 달래줄 만한 것이 하나 있다면, 바로 복수랍니다. 부디 제게서 아닐리아를 빼앗아간 그 사티로스들을 처치해 주세요. 복수의 증거로 놈의 뿔을 가져다주신다면 평생 당신의 은혜를 잊지 못할 거예요.", progress = "아무 죄없이 죽은 아닐리아의 복수를 할 수 있도록, 제발 도와주세요.", completion = "고마워요, 친절하신 &lt;race&gt;|1이여;여;. 이제야 눈물이 좀 마르는군요. 제 자매의 영혼도 당신에게 감사하고 있을 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1033] = {title = "엘룬의 눈물", objective = "아스트라나르에 있는 펠투러스에게 엘룬의 눈물을 가져가야 합니다.", description = "오렌딜의 치료제로 렐라라가 깨끗이 낫기를 바랬지만, 렐라라가 앓고 있는 병의 진행 속도만 늦출 뿐인 것 같습니다. 더 확실한 치료제를 찾아야 합니다! 오렌딜이 이 치료제가 듣지 않을 경우 다른 걸 먹여 보는 게 좋다고 얘기해 줬답니다.\n\n엘룬의 눈물은 아스트라나르 동쪽에 있는 아이리스 호수의 섬에서만 나는 일종의 돌입니다. 오렌딜은 그 돌이 병을 치료해 줄 거라고 했어요. 제발 엘룬의 눈물을 가져다주십시오. 그리고 제 딸의 병이 치유될 수 있도록 기도해 주세요.", progress = "아이리스 호수는 찾았나요? 엘룬의 눈물은 가져온건가요?", completion = "오! 찾아냈군요! 엘룬의 눈물을 스튜에 넣고 이것으로 내 딸의 병이 낫기를 기도해야겠습니다.\n\n고맙습니다! 정말 고맙습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1034] = {title = "별가루의 폐허", objective = "아스트라나르에 있는 펠투러스에게 별가루 5줌을 가져가야 합니다.", description = "엘룬의 눈물로 우리 딸의 병이 좀 나았어요. 딸을 괴롭히던 악몽도 사라졌구요. 신께 감사할 따름입니다. 하지만... 아직 열이 내리지 않고 있어요.\n\n오렌딜이 별가루의 폐허에 있는 얼어 붙은 별가루에 대한 얘기를 해주었어요. 그걸로 렐라라의 열을 내릴 수 있을 겁니다. 별가루를 좀 모아서 제게 가져다주세요.\n\n별가루의 폐허는 남쪽에 있어요. 엘룬께서 당신이 속히 다녀올 수 있도록 인도해 주시길...", progress = "별가루는 가져왔나요?", completion = "별가루를 가져왔군요! 이걸로 찜질약을 만들면 렐라라의 열을 내릴 수 있을 거예요.\n\n다시 한번 감사합니다. 당신의 도움이 없었다면 내 딸은 살지 못했을 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1035] = {title = "유성 호수", objective = "그늘덤불 나무현자에게서 유성 월장석을 빼앗아서 아스트라나르에 있는 펠투러스에게 가져가야 합니다.", description = "열은 내렸지만 렐라라의 몸이 아직 많이 쇠약한 상태예요. 시간이 지난다고 우리 딸의 기력이 회복될 것 같지는 않군요. 딸이 완쾌하려면 월장석의 힘이 필요해요.\n\n예전에는 남동쪽에 있는 유성 호수에서 월장석을 캐곤 했답니다. 그늘덤불일족들이 나타나기 전까지는요.\n\n놈들의 우두머리인 그늘덤불일족 현자가 유성 월장석을 독차지하고 있어요. 그 현자에게서 월장석을 좀 빼앗아다 주세요.\n\n월장석을 얻으려면 그를 처치해야 할 것입니다.", progress = "그늘덤불 나무현자는 처치했나요? 그랬다면, 제발 유성 월장석을 주세요. 우리 렐라라의 숨이 곧 멎을 것 같아요! 흑...", completion = "오! 당신이 내 딸의 목숨을 살렸어요! 월장석의 힘이 딸의 기력을 회복시켜 줄 거예요.\n\n당신이 베풀어 주신 은혜를 어찌 다 갚을 수 있겠습니까만... 이거라도 받아주세요. 이건 제가 렐라라 다음으로 아끼는 물건입니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n인내의 갑옷야수의 족쇄얼음수정 아미스\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1036] = {title = "붉은해적단과의 만남", objective = "가시덤불 골짜기 해안에 정박해 있는 크림슨 베일호에서 함장 피랠론과 대화해야 합니다.", description = "<name>... 그래. 당신 얘기를 들은 적이 있지. 당신도 우리 붉은해적단처럼 무법항에서 환영을 받지 못한다지? 피랠론 함장님은 당신처럼 원기 왕성한 <남자/여자>를 찾아 특별 임무를 맡기고 싶어하시오.\n\n관심 있거든 크림슨 베일호로 가서 갑판 아래 있는 피랠론 함장님과 얘기를 나누어보시오. 크림슨 베일호는 동쪽 거친 해안에 정박해 있는데 그 옆에 립타이드호와 담셀의 행운호가 있소.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1037] = {title = "벨린데 스타송", objective = "다르나서스의 전사의 정원에 있는 신텔 블레이드위버와 대화하십시오.", description = "벨린데 스타송은 이곳 잿빛 골짜기 숲에서 내 전임자로 일했어요. 처음에는 악령의 숲을 그런대로 잘 수호했던 것 같지만 조금씩 그녀의 노력도 소용없어 지게 되었습니다. 그러던 어느 날 그녀가 사라져 버렸고 그녀의 후임자로 내가 여기에 오게 된 것이죠.\n\n하지만 난 그 여사제에 대해서 아는 게 없습니다. 센티널 사령관 중 한 분인 신텔 블레이드위버께서는 그녀의 실종에 대해 내가 모르는 진실을 알고 있을지도 모르겠군요.", progress = nil, completion = "벨린데 스타송? 얼마 전에 그 여사제가 사라졌다는 사실은 이제 모르는 이가 없을 텐데... 그녀의 실종을 둘러싼 자세한 내막을 듣고 싶다는 말인가요?! 그대에게 그 얘기를 들어야만 하는 타당한 이유가 있어야 합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1038] = {title = "벨린데의 영향", objective = "벨린데의 상자에서 일지를 찾은 다음 열쇠와 함께 다르나서스에 있는 신텔 블레이드위버에게 돌려주어야 합니다.", description = "멜탄드리스의 마법책을 보았단 말인가요? 그렇다면 그대가 벨린데송의 물건을 조사해도 괜찮을 것 같군요. 그녀의 물건들은 파수꾼 합숙소에 있는 상자 안에 넣어 두었습니다. 여기 그 상자의 열쇠를 드리지요. 그녀는 일을 하는 중에 일지를 계속 적었으니, 그걸 조사해 보면 뭔가 알아낼 수도 있을 것 같군요.\n\n한 가지 말해 둘 건, 센티널에서는 그녀에게 그래야 할 이유가 있었기 때문에 떠났지만 곧 다시 돌아올 거라고 믿고 있습니다. 이 여사제는 오랫동안 많은 업적을 쌓아왔기 때문에 큰 신뢰를 얻고 있어요.", progress = "일지를 찾았나요?", completion = "벨린데의 실종이 생각보다 심각한 문제인 모양이군요. 그렇다 해도 아직도 난 그녀에게 안 좋은 일이 있으리라는 생각은 들지 않아요. 그녀에게 연락을 취해 보는 게 좋을 것 같군요.\n\n당신은 이 사건에 대해 관심이 큰 것 같으니 기꺼이 당신에게 이 일을 맡기도록 하겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1039] = {title = "불모의 땅 항구", objective = "톱니항에 있는 부두주임 디지위그와 대화하십시오.", description = "불모의 땅에서 항구는 톱니항 하나뿐이에요. 십중팔구 벨린데는 톱니항에서 상선을 얻어 타고 동부 왕국의 검은바다 만으로 갔을 거예요. 그 항구를 운영하는 고블린들과 우리는 제한적인 정보만 주고 받기 때문에 잘 모르지만, 항구의 주임은 분명 출입했던 승객에 대한 정보를 가지고 있을 거예요.\n\n잿빛 골짜기를 통해 남서쪽으로 길을 따라가면 불모의 땅에 이르게 될 거예요. 그 지역에는 호드의 병사들이 순찰을 돌고 있으니 조심하세요. 하지만 항구에서는 안전할 거예요.", progress = nil, completion = "당신은 &lt;race&gt;|1이;가; 맞나? 이해하게. 이곳에서는 당신네 종족을 보기가 좀처럼 힘들어서 말이야. 누굴 찾고 있는 건가? 잠시만 기다려 보게. 장부 어디엔가 적어 두었을 테니.\n\n이곳을 거치는 여행자들이 워낙 많아서... 잠시만 기다려 보라고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1040] = {title = "무법항으로의 여정", objective = "무법항으로 배를 타고 가서 행상 러즈고트와 대화하십시오.", description = "아! 드디어 찾았네. 그녀가 이곳을 지나간 지 이렇게 오래됐다고 말해 줬더라면 더 빨리 찾았을 것 아닌가. 어디 보자...\n\n벨린데라... 무법항행 검은 물수리호를 예약했었구먼. 여기 다른 기록은 없으니 배가 항구에 무사히 도착했을 거라고 생각되네.\n\n큰 도움이 못 되어 미안하지만, 그녀가 그 지역으로의 육로 여행에 대해 물었고 내가 무법항에 주로 다니는 행상 러즈고트에 대해 이야기해 준 게 기억이 나는군. 이 벨린데라는 여자가 그와 함께 여행을 했을지도 모르겠군.\n\n이제 어서 가 보게. 나도 이렇게 하루종일 자네와 노닥거리고 있을 수만은 없으니...", progress = nil, completion = "무슨 일이오? 실어 보낼 물건이 있는 상인은 아닌 것 같고... 우리 짐마차에서 일자리를 구하려는 거요? 지금은 일자리도 없지만... 아니면 내가 아닌 다른 고블린을 찾아온 것 같은데?\n\n용건이 대체 뭐요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1041] = {title = "행상길", objective = "다크샤이어에 있는 서기관 달트리와 대화하십시오.", description = "내가 오해를 했네요. 이런 일이 자주 있는 게 아니라서...\n\n당신이 찾는 벨린데라는 여자는 기억하고 있지. 이 짐마차는 더럽고 낡았지만 물건을 실어 나르는 데 더할 나위 없소. 하지만 나이트 엘프 여사제가 이런 짐마차를 타고 여행을 하는 일은 거의 없으니까 말이야.\n\n북쪽 길에서 헤어졌는데 그 여사제는 다크샤이어 쪽으로 갔지. 그 곳에 있는 서기관이 모든 기록을 관리하고 있으니 당신에게 도움이 될 만한 사실을 알고 있을지도 모르겠군.\n\n정글에서는 몸조심하시오. 가장 평화로운 때조차도 아주 위험한 곳이니까.", progress = nil, completion = "지난 몇 년 동안 이상한 사건들이 하도 끊임이 없길래, 전 낯선 이들에 대해 가능한 자세하게 기록해 두려 한답니다. 성가신 일이긴 하지만 언제 필요할지 모르니까요. 찾고계신 벨린데라는 분에 대해서도 이름만 있으면 다 찾아볼 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1042] = {title = "카레빈 일가", objective = "다크샤이어에 있는 조나단 카레빈과 대화해야 합니다.", description = "다크샤이어에 머물고 있는 벨린데 스타송이라는 이에 대한 기록은 없습니다. 하지만 어느 날 밤에 엘프 여사제가 여관에 방을 잡았던 일이 어렴풋이 기억나긴 하는데...\n\n그래도 당신이 말한 그 늑대인간에 대해서는 들은 바가 있어요. 요 전날 칼로가 녀석들을 처치한 증거를 들고 마을로 왔었죠. 그는 악마나 언데드 같은 괴물을 사냥하는 카레빈 일가와 함께 일하고 있어요. 카레빈 일가의 수장인 조나단과 얘기해 보시죠.", progress = nil, completion = "요즘은 정말 암울한 시기요. 숲의 사방에서 나쁜 소식들이 들리고 곳곳에 악이 숨어 있소이다.\n\n이런 때에 낯선 자가 내 집에 들어와서는 늑대인간에 대해 물으니... 당연히 이상하게 생각되지 않겠소? 내가 의심한 것에 대해서 굳이 사과하지는 않겠지만 당신의 질문에 대답은 하도록 하겠소.\n\n그리고 내가 궁금한 것에 대해서도 들어야겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1043] = {title = "엘룬의 낫", objective = "엘룬의 낫의 흔적을 찾은 다음 다크샤이어에 있는 조나단 카레빈에게 돌아가야 합니다.", description = "당신 이야기는 사실인 듯하군. 당신의 목적이 뭔지는 모르지만, 숲에서 늑대인간을 몰아내기 위해 이곳 그늘숲에 왔다면 우리로선 나쁠 것 없소.\n\n남쪽에 늑대인간들이 들끓는 광산이 하나 있소이다. 놈들은 모습을 잘 드러내지 않지만, 우리가 아는 한 그곳이 놈들을 처음 발견한 장소요.\n\n자, 이제 가서 할 일을 하시오. 하지만 한 가지 말해둘 건, 뭔가 중요한 걸 발견하면 내게도 알려줘야 한다는 거요. 악의 무리에 맞서기 위해 어떠한 정보나 도움이든 환영이요.", progress = nil, completion = "흥미로운 얘기로군. 이런 문제들의 원인을 찾아 영원히 제거할 만큼 우리 카레빈 일가의 영향력이 크진 않지만 그늘숲의 늑대인간의 수를 줄이기 위해 우리가 할 수 있는 최선을 다하고 있소이다. 이미 칼로에게 그 일이 최우선이라고 지시도 했소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1044] = {title = "해결된 의문", objective = "다르나서스에 있는 신텔 블레이드위버에게 돌아가야 합니다.", description = "늑대인간 문제는 우리가 해결할 것이니 걱정할 것 없소. 당신의 친구가 우리 숲에 몰고온 악의 세력은 제거될 테고, 그녀의 행동에 대해 반감을 갖고 있지도 않소.\n\n요즘은 이상한 일들이 자주 일어나고 있소이다. 어둠의 세력은 휴식이라는 걸 모르는가 보오. 이제 가 보시오. 당신이 그늘숲의 광산에서 발견한 사실에 대한 얘기를 반드시 들어야 할 이들이 있을 것이오.", progress = nil, completion = "그래, 이것이 벨린데가 맞이한 운명이란 말인가요? 그녀가 사라지기 전 그녀의 절친한 친구였던 고위 여사제께서 이 얘길 들으시면 무척 실망하시겠군요. 어쨌든 그녀가 엘룬의 가호로 엘룬의 낫을 가지게 되었다는 건 분명한 것 같군요. 그녀의 하인이 그 물건을 잃어버렸다는 사실이 불안하긴 하지만 말입니다.\n\n하지만 한 가지씩 해결해 나가야겠지요. 당신이 해 준 일에 대해선 뭐라고 감사해야 할지 모르겠습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n초승달 활달빛 마법봉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1045] = {title = "레이네의 정화", objective = "랜 블러드투스와 붉은송곳니 경비병 4명을 처치하고 미스트랄 호수 근처에 있는 크롤그에게 돌아가십시오.", description = "비록 나이트 엘프는 역사가 오래되었지만 천성이 오만하여 스스로 파멸을 불러왔소. 급기야는 우리 목숨까지 앗아가기 시작했지. 이제 더는 막을 수도 없소...\n\n나이트 엘프들은 비난 받아 마땅하지만 우리에게도 책임은 있소. 이제 우리는 타락의 수준을 넘어 어마어마한 악행을 저지를 수도 있소.\n\n랜 블러드투스가 그런 악행의 표본이지. 힘과 욕망에 굶주린 그는 타락으로 인해 더욱 강해졌소. 내 가슴은 아직 나이트 엘프에 대한 증오심으로 불타고 있지만 죄 없는 그들의 자손까지 고통받는 건 원치 않소. 우리 펄볼그들은 스스로 잘 단속해야 하오.", progress = nil, completion = "잘해 주었소, 친구.\n\n여전히 숲은 오염되어 있지만 적어도 예전의 영광을 되찾는 데 조금은 이바지했으니... 당신이 돌아올 때쯤엔 나도 우리 종족과 함께 있으면 좋으련만...\n\n부디 몸조심하시오. 언젠가 우리도 평화의 시대에 다시 만나겠지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1046] = {title = "레이네의 정화", objective = "아스트라나르에 있는 레이네 울프러너에게 랜 블러드투스의 해골과 다르톨의 변신마법봉을 가져가야 합니다.", description = "당신 일족에게로 돌아가 이곳에서 당신이 거둔 승리에 대해 알리시오.\n\n이 전리품을 갖고 돌아가 자랑하면서 마음껏 기쁨을 누리시게...", progress = "센티널이 이곳 잿빛 골짜기를 지키기 위해 최선을 다하고 있긴 하지만, 그대와 같은 <race>들이 없었다면 지금과 같은 터전은 마련하지 못했을 겁니다.", completion = "이것이 잿빛 골짜기를 위협했던 그 사나운 펄볼그의 해골이군요.\n\n그대의 능력에 정말 감탄했습니다. 센티널 전체를 대신해 감사드립니다. 앞으로도 우리를 도와주길 바랍니다.\n\n이 해골과 다르톨의 마법봉은 다른 이들이 볼 수 있도록 성스러운 곳에 보관하겠습니다.\n\n테로니스가 당신을 자랑스러워 할 겁니다. 정말 감사드립니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n빙하의 돌지하굴 칼도끼\n\n다음과 같은 것들 또한 받습니다:\n\n순은 반지"},
[1047] = {title = "새로운 미개척지", objective = "다르나서스의 세나리온 자치령에 있는 대드루이드 판드랄 스테그헬름을 찾아가 세나리온 의회의 칼림도어 미개척지 탐험 지원자 모집에 대한 얘기를 나눠야 합니다.", description = "영웅은 들으십시오!\n\n세나리온 의회에서는 칼림도어의 광활한 땅을 개척할 건장하고 실력 있는 모험가들을 찾고 있습니다! 타나리스와 가젯잔에서 서쪽으로 멀리 떨어진 곳에 펼쳐져 있는 금단의 황무지에는 상상도 못할 위험이 도사리고 있습니다. 세나리온 의회를 대신해 개척 임무를 맡아줄 용맹스럽고 뜻있는 지원자들을 찾고 있습니다.\n\n관심이 있는 이들은 모두 세나리온 의회에 알현을 청하십시오. 다르나서스에 있는 대드루이드 판드랄 스테그헬름을 찾아가면 자세한 얘기를 들을 수 있습니다!", progress = nil, completion = "자네 같은 일개 &lt;class&gt;|1이;가; 말을 걸어줬으면 하고 기다리는 것처럼 내가 한가해 보이는가? 아니... 일단 오늘 끝내야 할 중요한 일은 접어두고 자네가 어딘가에서 뭔가를 찾는 걸 돕기로 하지. 어쨌든 자네는 다르나서스... 아니, 텔드랏실 전체의 안녕보다는 하찮은 물건 찾는 일이 더 중요할 테니까.\n\n달숲에 사는 바보 같은 녀석들, 허구한 날 도움을 청하면서 내 귀한 시간을 빼앗더니만 이제는 이런 일까지 맡긴단 말이야?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1048] = {title = "붉은십자군 수도원으로", objective = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 붉은십자군 용사 헤로드와 사냥개조련사 록시를 처치한 후 언더시티에 있는 바리마트라스에게 돌아가 보고해야 합니다.", description = "어둠의 여왕님께서는 북쪽으로 전진해 오고 있는 리치 왕의 군대에 대한 급박한 상황에 신경을 쏟고 계시다. 난 그동안 좀 포세이큰 내적인 일들을 돌보고 있지.\n\n두말할 것 없이, 자칭 붉은십자군이라는 말썽꾸러기 인간들이 우리 지역 내에서 가장 큰 골칫거리가 되고 있단 말이야. 티리스팔 숲은 말 그대로 이 조그만 불개미 같은 녀석들로 우글거리고 있어.\n\n수도원으로 가라, <class>|1이여;여;. 가서 종교재판관 화이트메인과 그녀의 고위 부관들을 제거하도록 하라.", progress = nil, completion = "어둠의 여왕님의 명을 받들어 잘해 주었군, &lt;class&gt;. 쉽지 않은 임무였는데 말이야.\n\n자네의 포세이큰에 대한 충성심과 끈질김을 기억하도록 하지.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n징조의 검예언의 지팡이용의 피 목걸이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1049] = {title = "타락의 개요", objective = "티리스팔 숲의 붉은십자군 수도원에서 타락의 개요를 찾아 썬더 블러프에 있는 현자 트루스시커에게 가져가야 합니다.", description = "속세의 고리회에서는 역병에 걸린 우리의 새로운 동맹에게 순수한 의도를 갖고 있었지. 하지만 장로 회의의 귓전에 대고 속닥거리는 자들의 의도를 어떻게 안단 말인가?\n\n우리가 동맹을 맺은 포세이큰은 기만으로 가득 찬 역사가 있다네. 너무 서둘러서 조약을 맺었지. 케른님께서 오그리마의 경고를 듣는 게 좋았을지도 몰라.\n\n붉은십자군 수도원 깊숙한 곳에 인간 광신도들이 보호하는 타락의 개요라는 책이 있네. 그들의 방식은 광기에서 비롯된 것이지만 그 연구 내용은 쓸모가 있을 것일세.", progress = "나는 용맹하고 숭고한 지도자이신 케른님을 목숨을 다 바쳐 따를 것이네. 하지만 이러한 정세 속에서는 다른 이들을 믿지 못하겠군.\n\n내가 수집할 수 있는 지식을 모두 모으면 족장님께 적절한 자문을 드릴 수 있을 걸세.\n\n티리스팔 숲엔 가 봤나? 붉은십자군 수도원 말일세. 그 타락의 개요야말로 이 난해한 수수께끼를 완성할 수 있는 마지막 조각일세.", completion = "타락의 개요로군! 이 책이 정말로 존재하는지 회의가 들기 시작했었는데 말이야!\n\n$g그대는 썬더 블러프의 타우렌에게 큰 일을 해 주었네. 내 그대의 헌신을 잊지 않겠네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n암흑의 수호방패마력석 버클러최후의 보주\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1050] = {title = "티탄 신화", objective = "수도원에서 티탄 신화라는 책을 찾아 아이언포지에 있는 사서 메이 페일더스트에게 가져가야 합니다.", description = "미래는 피할 수 없습니다! 우리는 대해에 떨어지는 빗방울처럼 미래를 향해 힘차게 나아가야 합니다.\n\n하지만 과거를 알기 때문에 앞일을 내다보고 미지의 세계에 좀더 안전하게 대비할 수 있는 것인지도 모릅니다.\n\n로데론에 비극적인 분란이 일어나기 전 티리스팔 숲에는 지식의 보루가 안치되어 있었습니다. 소문에 의하면 티탄 신화라는 책이 옛 수도원의 도서관에 소장되어 있었다고 합니다.\n\n그 책을 저에게 가져오면 함께 과거의 수수께끼를 풀 수 있을지도 모릅니다!", progress = "한때 수도원은 예비 성기사들이 수련을 쌓는 신학교였답니다. 하지만 빛의 요새였던 이곳은 붉은십자군 광신도들의 손아귀에 넘어가 버렸지요.\n\n십자군은 언데드 역병이 퍼진 땅을 정화하려는 자신들의 사명이 숭고하다고 믿었죠. 하지만 지금은 그 숭고한 목적이 광기로 얼룩져 모두의 적이 되어 버리고 말았답니다.\n\n티탄 신화를 가져오세요. 그러면 제가 연구용으로 이곳 아이언포지에 잘 보관해 두겠습니다.\n\n타락한 수도원에 그런 역사의 보물을 두어서는 안 되죠.", completion = "신성한 서적을 찾아오셨군요!\n\n길도 멀고 이 책을 손에 넣기도 쉽지 않았을 테지만 당신 덕분에 아이언포지의 드워프들은 큰 힘을 얻었습니다.\n\n탐험가 연맹을 대신해 감사를 드립니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n탐험가 연맹 증표"},
[1051] = {title = "보렐의 복수", objective = "타렌 밀농장에 있는 모니카 센구츠에게 보렐의 결혼반지를 가져가야 합니다.", description = "비록 내 의지는 자유롭다 하나 더 이상 어둠의 여왕님을 섬길 수가 없소. 아제로스에서의 내 명은 다 끝난 것 같군. 내 생명의 힘도 쇠한 것 같소.\n\n심문관 비샤스가 내게 이런 짓을 했소! 수 주간 고문을 하고 내 결혼 반지를 빼앗아 자기 아내에게 줘 버린 몹쓸 녀석! 복수... 난 복수를 원하오!\n\n그 바보 같은 녀석이 로다미어 호수에 사는 자기 아내 낸시에 대해 자랑을 늘어놓았소. 그 여자를 찾아 처치하고 내 결혼 반지를 타렌 밀농장에 사는 아내 모니카에게 되돌려주시오.\n\n내 마지막 소원이오...", progress = "무슨 일로 오셨나요?", completion = "보렐은 아주 힘든 인생을 살았어요. 아주 좋은 남편이었는데...\n\n더러운 인간 녀석들! 보렐은 가버렸어요. 다시는 언데드의 삶을 즐길 수가 없게 되었군요. 당신이 그의 이름으로 행한 복수로 위안으로 삼아야겠네요. 감사드립니다.\n\n이제 혼자 남편을 애도하게 해 주세요...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n비애의 어깨보호대한철 단망토\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n보렐의 장화"},
[1052] = {title = "붉은십자군의 길", objective = "사우스쇼어에 있는 경건한 신자 랄레이에게 수사 안톤의 추천서를 가져가야 합니다.", description = "우리 붉은십자군은 하스글렌에서 티리스팔 숲에 이르기까지 여러 요새에 대한 소유권을 주장하고 있습니다. 또한 우리는 로데론 곳곳에 있는 정화의 보루들을 매우 자랑스럽게 생각합니다.\n\n<형제/자매>께서 잊혀진 땅에서 언데드를 상대로 잘 싸워 주었지만 정말 큰 위협은 로데론에 있습니다.\n\n동부 왕국에 있는 사우스쇼어의 마을로 가십시오. 그리고 경건한 신자 랄레이라는 십자군을 찾도록 하시기 바랍니다. 그에게 내 인장이 있는 이 추천서를 주면 우리 붉은십자군 수도원에 있는 영예로운 장소로 <형제/자매>를 안내해 줄 것입니다.", progress = "거기 누구요? 내게 무슨 볼일이오?", completion = "수사 안톤님이 아직도 붉은십자군의 뜻을 전파하고 있단 말이오? 이런...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1053] = {title = "빛의 이름으로!", objective = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 붉은십자군 용사 헤로드와 사냥개조련사 록시를 처치한 후 사우스쇼어에 있는 경건한 신자 랄레이에게 돌아가 보고하십시오.", description = "나도 한때는 자부심을 갖고 명예롭게 충성을 바쳐 붉은십자군을 따랐었소. 아제로스에서 언데드를 몰아낸다는 그들의 목표가 고귀한 것이라고 믿었으니까 말이오.\n\n하지만 티리스팔 숲의 수도원에서 지내면서 그들이 갈수록 현실을 제대로 파악하지 못하고 있다는 것을 깨닫게 되었소. 이제 그들은 붉은십자군 외투를 입지 않은 이는 모두 악의 세력에 물든 것이라고 믿고 있지. 무고한 남녀가 악의 세력에 물들었을 거라는 이유로 고문을 당했소.\n\n빛의 이름으로 붉은십자군을 처단해야 하오. 당신이 이 미친 집단을 꼭 처치해 주시오.", progress = nil, completion = "빛의 신도들이 살생을 보고 기뻐해서는 안 되지만 때로는 왕국과 이 세상 전체의 대의를 위해 희생이 불가피하다는 것을 받아들여야 하오. 당신이 수도원에서 세운 공을 통해 수많은 무고한 생명들이 구제되었소이다. 당신의 끈기에 경의를 표하는 바이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n평온의 검각골의 도끼검은 위협로리카의 보주\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1054] = {title = "위협 제거", objective = "아스트라나르에 있는 레이네 울프러너에게 달 블러드클로의 해골을 가져가야 합니다.", description = "아스트라나르 바로 북쪽에 엉겅퀴일족 펄볼그가 있습니다. 우리 정찰병에 따르면 지난 몇 달 사이 그 수가 크게 늘어났다고 합니다. 너무 많이 늘어나면 아스트라나르를 직접 공격하려 들 수도 있어 위험합니다.\n\n우선 펄볼그들을 가능한 많이 처치하고 그 우두머리의 해골을 가지고 와 주십시오. 진압해주신 대가는 후히 드릴 것입니다.\n\n난 이곳 아스트란나르에 남아 그대의 승전 소식을 기다리도록 하겠습니다. 엘룬께서 그대와 함께하시기를...", progress = "펄볼그의 타락으로 잿빛 골짜기는 예전의 영광을 잃어만 가고 있습니다.", completion = "훌륭하십니다, &lt;name&gt;!\n\n아시다시피 펄볼그들은 이곳에 침략을 계속해 왔습니다. 이번 성과로 좀 조용히 지낼 수 있으면 좋으련만...", rewards = "다음과 같은 것들을 받습니다:\n\n회복의 항유"},
[1055] = {title = "레이네의 정화", objective = "달샘에 있는 셸드린에게 돌아가십시오.", description = "이제 완성된 마법봉이 당신 손 안에 있습니다. 셸드린이 당신이 성공했다는 것을 듣고 싶어할 것입니다.", progress = nil, completion = "해냈군요! 훌륭합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1056] = {title = "돌발톱 봉우리로의 여정", objective = "돌발톱 봉우리에 있는 수호자 알바고름을 찾아가십시오.", description = "숲의 정령들이 그대는 모험을 두려워하지 않을 만큼 용맹스럽다고 말해주더군.\n\n남쪽으로 미스트랄 호수에서 그리 멀지 않은 곳에 돌발톱 토굴길이 있소. 이 길을 통과하면 돌발톱 산맥의 칼바람 바위산이라는 곳에 이르게 되오. 그곳에 도착해 남서쪽으로 가다가 바위웅덩이 호수를 지나 북쪽으로 가파른 언덕을 오르도록 하시오. 그러면 돌발톱 봉우리에 다다를 거요.\n\n그곳에 수호자 알바고름이 그대를 기다리고 있으니 그의 말을 잘 따르도록 하시오. <race>|1이여;여;!\n\n위험이 도사리고 있는 힘든 여행이 될 것이오.", progress = nil, completion = "드디어 도착하셨군. 팔드리즈가 숲의 정령들이 하는 이야기를 귀 기울여 들었나 보오. 여기까지 오느라 수고가 많았소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1057] = {title = "잿더미 계곡 복원", objective = "돌발톱 봉우리에 있는 수호자 알바고름이 혈폭풍하피 7마리, 혈폭풍일족 복병 7마리, 혈폭풍일족 암살자 7마리, 그리고 혈폭풍일족 약탈자 7마리를 처치해 달라고 부탁했습니다.", description = "그대는 내가 숲의 정령을 지키는 자로써 왜 지금의 사태를 우려하는지 잘 알고 있을 거요.\n\n산맥을 넘어 이 봉우리까지 오는 동안 이 땅에 행해진 가혹한 일들을 보았을 걸로 아오. 이 신성한 언덕까지 탐욕의 손길에 의해 더럽혀져서 파멸의 길로 치닫고 있소. 투자개발회사에서 보낸 기계가 남쪽 잿더미 계곡을 불태운데다가 혈폭풍일족들이 이 땅을 침범해 숲을 가꾸기 위한 노력을 무참히 짓밟고 있는 실정이오.\n\n이 괘씸한 하피들을 당장 몰아내도록 하오!", progress = nil, completion = "잘했소. 혈폭풍일족에게 큰 타격을 주었으니 본격적으로 이 땅의 복원 작업을 시작해도 될 것 같군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1058] = {title = "진질의 숲의 마법", objective = "말라카진에 있는 의술사 진질이 돌발톱 수액 5개, 황혼의 수염 5개, 순록의 눈 30개와 마룡 비늘 1개를 가져다 달라고 부탁했습니다.", description = "정말 흥분되는군!\n\n저기 갇혀 있는 세 마리 귀여운 엘프들 좀 보라고! 음, 저 사랑스러운 친구들로 뭘 할 수 있을까? 흠, 저들이 숲의 마법이라 부르는 것을 조금... 맛보여 주는 건 어떨까...!\n\n그러려면 돌발톱 수액이 꽤 많이 필요하겠군. 그리고 무시무시한 황혼의 흑표범에게서 황혼의 수염을 구해오고... 참! 순록의 눈도 있어야 해. 순록의 눈은 많으면 많을수록 좋지. 그리고 귀한 마룡 비늘도 잊으면 안 돼.\n\n자, 어서 돌발톱 봉우리로 가서 내가 말한 것들을 구해오도록 해. 어서 숲의 마법을 써보고 싶단 말이야!", progress = "저기 저 작은 엘프 친구들을 좀 봐. 가련해 보이지 않나? 숲에서 뛰놀아야 할 녀석들이 우리에 갇힌 신세가 되었잖아!\n\n수액은 구해왔나? 황혼의 흑표범의 수염은? 아직 마룡 비늘은 못 구했겠지?\n\n그리고 순록의 눈은 아주 많이 필요한 거 알지?! 순록의 눈이 모자라면 강력한 숲의 마법 약을 만들어낼 수가 없단 말이야!", completion = "아, 이 특별한 마법 약으로 이 친구들은 고향에 온 것 같은 기분을 느끼게 될 거야. 이 작은 숲의 요정들이 얼마나 행복해 할까! 하하하!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n부두교 어깨보호대마술걸린 팔보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1059] = {title = "잿더미 계곡 복원", objective = "버섯구름 봉우리와 페랄라스의 경계에 있는 팔핀델 웨이워더를 찾아가야 합니다.", description = "일단 혈폭풍일족을 제압하기는 했지만 다른 조취를 취하지 않으면 곧 다시 규합할 거요.\n\n불모의 땅에서 남쪽으로 멀리 버섯구름 봉우리라는 곳이 있소. 그곳에서 서쪽으로 가다가 페랄라스의 울창한 숲 경계에 이르면 팔핀델 웨이워더라는 드루이드를 만나게 될 거요. 이 현명한 드루이드는 잿더미 계곡의 복원을 도울 위대한 숲의 정령을 소환할 수 있소.\n\n가서 우리가 그의 도움을 필요로 한다는 사실을 전하시오! 자, 어서 그를 찾아 떠나도록 하시오!", progress = nil, completion = "수호자 알바고름이 당신을 급파하다니 매우 현명한 처사로군.\n\n늦지 않게 잿더미 계곡에 위대한 숲의 지원군들을 보내야 할 텐데...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n유연한 팔보호구장관의 버클러\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1060] = {title = "진질에게 보내는 편지", objective = "돌발톱 산맥의 동굴에서 야영을 하는 진질에게 달소크의 편지를 전달하십시오.", description = "지금까지 임무를 아주 훌륭히 수행해 줬어. 자네는 행운을 부르는 자로군. 자, 이제 먼길을 가야할 때일세.\n\n원래 하피는 불모의 땅에 살지 않았어. 멀리 북서쪽에 있는 돌발톱 산맥이라는 곳에서 왔지. 위험한 일이란 건 알지만 이 편지를 거기 사는 내 오랜 벗, 진질이라는 의술사에게 전해주겠나?\n\n붉은깃털 세레나가 죽었다는 소식을 들으면 그도 아주 기뻐할 거야. 그리고 자네도 돌발톱 산맥이 얼마나 흥미로운 곳인지 알게 될 것이고...", progress = "수상해 보이는데... 내게 뭔가 줄 거라도 있는 건가?", completion = "아, 달소크의 편지를 가지고 왔군. 소식 들은 지가 몇 년은 된 것 같은데...\n\n그래, 붉은깃털일족 최후의 하피가 죽었단 말이지? 거 희소식이로군. 내 친구 록한이 정신 나간 모크나탈이란 놈과 함께 세레나의 언니를 처치하러 갔던 때가 생각나는군. 아, 다시 젊은 시절로 돌아갈 수만 있다면... 지금의 자네처럼 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1061] = {title = "돌발톱 산맥의 정령", objective = "돌발톱 산맥에 있는 시리스 스톤브레이크와 대화하십시오.", description = "고블린들과 그 하수인들이 약탈과 방화를 일삼는 것에 대해 돌발톱 산맥의 정령들이 분노하고 있네. 그로 인해 땅은 울부짖고 있고, 이러한 사실은 자연의 소리를 듣는 모든 이들에게 전해졌다네.\n\n그래서 호드의 촉망 받는 주술사, 시리스 스톤브레이크가 돌발톱 산맥으로 파견되었네. 그녀는 고블린들이 저지르고 있는 대규모 삼림 훼손에 대해 보고하면서 도움을 청했지.\n\n지금 돌발톱 산맥으로 가서 시리스를 만나게. 불모의 땅의 크로스로드에서 서쪽 길을 따라 가면 되지. 큰소나무 계곡 근처에서 야영을 하고 있다네.", progress = nil, completion = "아, &lt;class&gt;|1을;를; 보냈군요. 좋아요. 이 약탈자들을 상대하려면 당신 도움이 필요해요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1062] = {title = "고블린 침략자", objective = "투자개발회사 나무꾼 15명을 처치한 다음 돌발톱 산맥과 불모의 땅의 경계에 있는 시리스 스톤브레이크에게 돌아가십시오.", description = "고블린이 운영하는 투자개발회사가 돌발톱 산맥으로 몰려와 함부로 나무를 베고 숲을 태우고 있어요. 숲의 정령들은 고통과 분노로 눈이 멀 지경이니 투자개발회사를 반드시 막아야 해요!\n\n북서쪽으로 가세요. 큰소나무 계곡 너머 칼바람 바위산까지 말이예오. 고블린과 그 하수인들이 일하고 있을 테니, 녀석들에게 우리 호드가 돌발톱 산맥에서 그들이 행한 악행을 그냥 두고만 보지는 않으리라는 걸 똑똑히 일깨워 줘요. 가장 확실히 깨우칠 수 있는 방법으로...\n\n호드의 힘을 보여줘요!", progress = nil, completion = "역시 호드의 일원답군요.\n\n하지만 이미 분노한 돌발톱 산맥의 정령들을 달래려면 타우렌들의 지혜를 빌려야겠지만...\n\n일단 투자개발회사 놈들을 몰아냈다는 건 좋은 출발이라 할 수 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1063] = {title = "원로 마가타", objective = "썬더 블러프에 있는 마가타와 대화하십시오.", description = "돌발톱 산맥의 정령들을 수호하려면 우리의 동맹인 타우렌에게 조언을 구해야 해요. 원로들이라면 지혜를 나눠줄 거예요.\n\n타우렌 족장들을 많이 알지는 못하지만 나이 많고 지혜로운 마가타라는 족장은 알고 있답니다. 그녀에게서 타우렌 종족의 지혜를 얻을 수 있을 거예요.\n\n마가타는 타우렌의 수도 썬더 블러프의 북동쪽 절벽에 있는 장로의 봉우리에 살고 있어요. 그분을 만나거든 위험에 처한 돌발톱 산맥의 상황에 대해 전해 주세요.", progress = nil, completion = "어서 오시게. 조언을 구하러 왔나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1064] = {title = "포세이큰의 원조", objective = "썬더 블러프의 예언의 웅덩이에 있는 연금술사 자마와 대화해야 합니다.", description = "타우렌은 이 땅을 지켜야 할 의무가 있네. 그래서 더더욱 돌발톱 산맥의 상황에 대한 소식은 내겐 고통스럽군그래. 이 땅을 치유하려면 먼저 만연한 질병을 제거해야만 하네.\n\n이러한 상황에 포세이큰이 우리 동맹이란 사실이 다행스럽지 않은가? 그들은 질병에 대한 지식이 해박하니 우릴 도울 수 있을 걸세. 그렇게 함으로써 서로 간의 신뢰를 강화할 수 있게 될 테고 말이야.\n\n연금술사 자마를 만나 보게. 그녀는 학자이자 포세이큰의 밀사이기도 하지. 정기의 봉우리 아래에 있는 예언의 웅덩이에 가면 만날 수 있을 걸세.", progress = nil, completion = "마가타님께서 당신이 올 거라고 전하더군. 내 심장의 박동은 이미 멎었으나 돌발톱 산맥의 정령들이 슬퍼하고 있다는 건 느낄 수 있소.\n\n포세이큰은 기꺼이 이 문제의 해결에 도움이 되도록 하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1065] = {title = "타렌 밀농장으로의 모험", objective = "타렌 밀농장에 있는 연금술사 라이던에게 자마의 쪽지를 가져가야 합니다.", description = "돌발톱 산맥에서 투자개발회사를 몰아내려면 극단의 조치를 취해야만 하오. 피를 흘리지 않으면서도 더 없이 강력한 방법을 말이지.\n\n우리 동료 중 하나가 이 일에 꼭 알맞은 도구를 가지고 있소. 그의 이름은 라이던, 먼 로데론 땅의 힐스브래드 구릉지에 있는 타렌 밀농장 마을에 살고 있소이다.\n\n힐스브래드로 가려면 비행선을 타고 우리의 수도인 언더시티로 가시오. 그런 다음 북쪽의 티리스팔 숲으로 가서 남서쪽의 은빛소나무 숲으로 간 후 다시 남쪽의 힐스브래드로 가면 되오.\n\n라이던을 찾아 이 쪽지를 전해 주시오. 우리가 필요로 하는 사항에 대해 자세히 적어 두었소이다.", progress = "음, 내게 새로운 실험 과제라도 가져온 건가?", completion = "자마가 보낸 쪽지라고? 그 먼 곳에서 전갈을 보낸 걸 보니 뭔가가 절실히 필요한 모양이로군. 어디 뭐라고 썼는지 한번 볼까...\n\n아, 좋아! 자, 내가 할 일은 확실한 것 같군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1066] = {title = "순결한 피", objective = "타렌 밀농장에 있는 연금술사 라이던에게 순결한 피가 든 유리병 5병을 가져가야 합니다.", description = "내가 투자개발회사 놈들에게서 폭력적인 성향을 뽑아내 놈들을 약하고 순하게 할 독약을 만들 것이오. 그러면 돌발톱 산맥에서 호드가 당면한 문제를 해결할 수 있지 않겠소?\n\n하지만 독약을 만들려면 순결한 자들의 피가 필요한데 상당히 얻기 힘든 재료지. 다행히도 이 지역에 비밀결사대라는 인간 도둑 무리가 어둠마법사를 고용하고 있는데... 그들은 뭔가 불순한 목적에 사용할 순결한 피를 모으고 있소.\n\n비밀결사대 어둠마법사 녀석들은 남동쪽에 있는 던홀드 요새에서 찾을 수 있을 거요.", progress = "비밀결사대 어둠마법사를 찾아 피를 모아왔나?", completion = "훌륭하군! 비밀결사대를 상대하는 건 어렵지 않았소?\n\n전에도 말했지만 순결한 피는 구하기 어려운 재료지. 우리가 비밀결사대 어둠마법사 덕분에 쉽게 얻은 건 정말 행운이야.\n\n이제 독약을 만들 동안 좀 기다리시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1067] = {title = "썬더 블러프로의 귀환", objective = "썬더 블러프에 있는 연금술사 자마에게 라이던의 독약을 가져가야 합니다.", description = "자, 여기 독약이 있소. 투자개발회사 놈들에게 이 독약을 사용하면 좋은 결과를 얻게 될 거야. 잘하면 놈들 사이에서 전염될지도 모르고... 내가 조제한 독약이 현장에서 실제로 사용되는 걸 보는 건 정말 신나는 일이지!\n\n하지만 사용하기 전에 일단 연금술사 자마에게 가져가도록 하시오. 그녀가 독약의 효과를 극대화할 수 있는 운반 방법을 마련해 줄 것이오.", progress = "돌아왔군. 연금술사 라이던에게서 도움이 될 만한 걸 받아왔소?", completion = "연금술사 라이던이 만든 독약이라고? 훌륭하군. 라이던이 만든 거라면 이 독약은 투자개발회사 녀석들에게 확실한 효과를 발휘할 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1068] = {title = "벌목기", objective = "벌목기 XT:4와 XT:9를 파괴한 다음 돌발톱 산맥과 불모의 땅의 경계에 있는 시리스 스톤브레이크에게 돌아가십시오.", description = "주술사의 영적 마법과 드루이드의 자연 마법에는 연관이 있어요. 그렇기 때문에 우리 주술사들은 돌발톱 산맥의 정령들이 하는 말을 들을 수 있는 거죠. 자연의 정령들이 속삭이는 말들을 다 알아들을 수는 없지만, 한 가지 계시... 그 환영만은 아주 또렷하게 기억해요.\n\n큰소나무 계곡 북서쪽의 칼바람 바위산에서 인간 모양을 한 기계 두 대가 무서운 속도로 나무를 쓰러뜨리는 것을 보았어요.\n\n그리고 기계에는 각각 XT:4와 XT:9라는 식별번호가 표시되어 있었어요. 이 기계들은 반드시 파괴되어야만 해요!", progress = nil, completion = "XT:4와 XT:9를 파괴하여 돌발톱 산맥에 있는 많은 정령들의 슬픔을 조금이나마 달래주었군요. 이제 그 기계들을 잃은 투자개발회사가 돌발톱 산맥에서 떠나기를 한번 기대해 보죠.\n\n그들이 떠나지 않는다면 지금까지 이 산에 벌어졌던 만행과는 비교도 안 될 만큼 끔찍한 일이 앞으로도 계속 일어날 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1069] = {title = "동굴이끼거미알", objective = "톱니항에 있는 메보크 미지릭스에게 동굴이끼거미알 15개를 가져가야 합니다.", description = "거미 알 오믈렛은 무법항에서 새로 유행하고 있는 음식이지. 그런데 문제는... 거미 알 공급이 시원찮단 거야.\n\n그래서 난 이걸 기회로 삼으려고 해!\n\n여기서 북서쪽으로 돌발톱 산맥의 칼바람 바위산과 시쉬르 협곡에는 동굴이끼거미들이 살고 있어. 내게 그 거미의 알을 가져다준다면 값을 두둑이 쳐 주지.\n\n칼바람 바위산에서 그 거미들은 나무 아래 모여 있을 거야.\n\n시쉬르 협곡에는... 흠, 자네 비위가 무지 좋은 편이 아니라면, 칼바람 바위산에서나 열심히 일하라고.", progress = "거미 알은? 이미 부두주임 디지위그와 알 수송 거래 계약을 마쳤단 말이야!", completion = "거미 알을 가져왔군! 고마워!\n\n이 알들을 디지위그에게 보내 무법항으로 수송하도록 하지. 흐흐, 벌써 돈 냄새가 나는 것 같군그래.\n\n자, 이건 자네 몫! 자네가 없었다면 이 거래는 성사되지 못했을 테니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1070] = {title = "돌발톱 산맥에서의 임무", objective = "돌발톱 산맥에 있는 칼바람 바위산 입구에 계곡이 내려다보이는 곳에 캘라 섀도스피어를 찾아야 합니다.", description = "엘룬께 영광을...\n\n방랑벽이 꽤 있어 보이는데 혹시 돌발톱 산맥에 가본 적이 있습니까? 그곳은 투자개발회사와 다른 적들에 의해 심하게 훼손당한 땅이랍니다.\n\n얼마 전 레이네 울프러너가 제 친구 캘라 섀도스피어를 그리로 보내 그 땅에서 무슨 일이 일어나고 있는지 조사하도록 했지만 아직 그녀로부터 아무 소식이 없습니다. 그녀를 보낼 때 얼라이언스에서 노움 마법사 한 명도 붙여 보냈기 때문에 더 걱정입니다. 노움들은 항상 문제를 일으키니까요.\n\n그녀를 찾은 다음 내게 알려 주시겠습니까?", progress = nil, completion = "아, 타라의 부탁으로 잿빛 골짜기에서 온 거군요. 그녀와, 그리고 제 고향이 얼마나 그리운지 몰라요. 타라가 임무를 수행할 모험가들을 보내는 걸 보니 그녀와 센티널이 잘해나가고 있는 것이 분명하군요. 무척 자랑스럽네요.\n\n만나뵙게 되서 정말 기뻐요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1071] = {title = "노움의 부탁", objective = "투자개발회사 나무꾼 10명 및 투자개발회사 벌채꾼 10명을 처치하고 돌발톱 산맥에 있는 각심 러스트피즐에게 돌아가십시오.", description = "보다시피 난 비전술, 연금술 및 기계공학 연구회의 회원이지. 내 목표... 아니, 내 임무는 나이트 엘프에게 마법과 약물, 그리고 과학을 합치면 숲을 더 안전하게 수호할 수 있다는 사실을 보여 주는 것이오.\n\n하지만 이건 매우 버거운 전쟁인데다 고블린은 쥐새끼들처럼 그 수가 불어나고 있소. 그래서 난 요즘 머릿속에서 설계한 물건들을 제작할 시간조차 없지 뭐요!\n\n그래서 내가 발명 계획을 짜고 준비를 좀 할 수 있도록 당신이 좀 도와줬으면 하는데 어떻소? 동쪽에 있는 칼바람 바위산의 고블린 놈들을 꼼짝 못하도록 주시오.", progress = nil, completion = "고맙소. 딱 제때 돌아왔군. 그동안 난 완벽한 계획을 짰는데... 다른 게 아니라 폭탄이지. 아... 그게 다는 아니고 계획의 일부요.\n\n보다시피 아주 강력한 폭탄으로 고블린 놈들에게 겁을 좀 줄 생각이오. 아, 흔히들 생각하는 것만큼 위험하지는 않으니 걱정 마시오. 산 능선을 따라 몇 군데만 폭발시키면 놈들을 확실히 쫓아낼 수 있을 거요. 그런데 지난 며칠 동안 보급품이 떨어져서...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1072] = {title = "오랜 동료", objective = "아이언포지에 있는 로막 기어스트립과 대화하십시오.", description = "내가 생각하고 있는 건 최신형 폭탄이란 말이오. 하지만 특별한 물약이 필요하지. 이번이 마지막 부탁이 될 거요. 이제 곧 근사한 걸 만들어낼 거란 말이지.\n\n니트로미르글리세로니움... NG-5이라는 폭발성 물질이 필요해...\n\n이 NG-5를 만들 수 있는 유일한 인물은 로막 기어스트립이라는 내 오랜 친구뿐이지. 땜장이 마을에 찾아가 보시오.\n\n그에게 NG-5를 만들어 달라고 해서 가져오면 내 당장이라도 제작을 시작할 수 있지.", progress = nil, completion = "아... 각심이 보냈단 말이오? 참말인지 거짓말인지 어떻게 알지? 흠...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1073] = {title = "어리석음 + 화학 물질 = 재미", objective = "아이언포지에 있는 로막 기어스트립에게 최하급 마나 물약 4개와 최하급 인내의 비약 2개를 가져가야 합니다.", description = "하하하... 고블린이 숲을 파괴하는 것을 막기 위해 니트로미르글리세로니움이 필요하단 말이오?\n\n당신이 각심을 얼마나 잘 아는지 상관없으니... 내 니트로미르글리세로니움을 주지. 폭발로 산산조각 나는 게 당신이 될지 놈들이 될지 갑자기 보고 싶어졌거든.\n\n그런데 문제는 니트로미르글리세로니움이 다 떨어졌다는 거요. 하지만 당신이 적당한 물약들을 가져다 준다면 즉시 만들어 주도록 하겠소.\n\n내 발명품 중 가장 훌륭한 것을 얻으려면 적어도 연금술사로서의 자질을 조금은 보여 줘야 하지 않겠소?", progress = "물약이 없으면 니트로미르글리세로니움을 만들 수 없소. 꼭 필요하단 말이오.", completion = "이거면 됐소.\n\n이방인 친구, 당신을 잘 알지 못했더라면 연금술에 조예가 깊은 줄 알았겠소. 아무튼 잘했소이다. 그리고 알고 있는지 모르겠는데 세상엔 검과 마법이 전부가 아니라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1074] = {title = "어리석음 + 화학 물질 = 재미", objective = "돌발톱산맥에 있는 각심 러스트피즐에게 니트로미르글리세로니움을 가져가야 합니다.", description = "자, 다 됐소. 이방인 친구여, 까딱하면 폭발하는 물질이니까... 오, 조심... 살살 다루라고.\n\n당신이 정말 각심의 친구라면 내가 안부 전하더라고 해주시오. 아니면 폭발 구경이나 잘하시구려. 당신이 날아가 버릴지도 모르지만...", progress = "어이, 멋진 친구... 돌아왔군.", completion = "아주 잘했수다. NG-5가 있으면 다이너마이트를 실은 마차에 단번에 불을 붙일 수 있지.\n\n아니... 그렇소, 다이너마이트... 마차마다 가득 실은... 정말 완벽한 계획이라 할 수 있지... 지켜보기나 하슈.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1075] = {title = "마우렌의 두루마리", objective = "스톰윈드에 있는 콜린 마우렌을 찾아야 합니다.", description = "자, 이제 계획을 완성하려면 원격 폭파 장치가 남았는데... 아, 아직 그 부분을 설명을 안 해 줬군.\n\n간략하게 이렇다오. 약간의 마법을 사용하면 당신이 몸을 피한 후 폭발이 나도록 할 수 있다고. 쉼호흡 한번 하고 단추를 누르면 NG-5가 폭발하도록 장치를 만들어 주겠다는 뜻이오.\n\n하지만 그러려면 스톰윈드에 있는 친구의 마법 주문이 필요해. 그 친구의 이름은 콜린 마우렌이라 하오. 스톰윈드 마법사 지구로 가면 그를 만날 수 있지. 그는 인간이니까 쉽게 알아볼 수 있을 거라오.", progress = nil, completion = "그러니까 지금 먼 거리에 있는 목표물을 폭파시키도록 하는 주문이 필요하단 말이군요. 흠...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1076] = {title = "서부 몰락지대의 악령", objective = "스톰윈드에 있는 콜린 마우렌에게 먼지 악령의 파편을 가져가야 합니다.", description = "아, 내게 그런 주문이 있는 것 같습니다. 교신이라는 주문인데... 그가 찾는 마법 주문이 맞을 겁니다.\n\n두루마리를 만들어 그 주문을 걸어야 할 것 같군요. 그러려면 먼지 악령으로부터 파편을 얻어야 합니다.\n\n내가 다른 재료를 준비하는 동안 서부 몰락지대로 가서 그 사악한 것들을 사냥하고 파편을 구해다 주시면 고맙겠군요. 위험한 녀석들이긴 하지만 각심의 실험에 기꺼이 동참할 정도의 담력을 지녔다면 쉽게 상대하리라 믿습니다.\n\n여기서 다시 만나도록 합시다.", progress = "돌아왔군요. 내가 부탁한 재료는 구해 왔습니까?", completion = "잠시만 기다리세요. 두루마리를 준비하도록 하겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1077] = {title = "각심을 위한 특별한 선물", objective = "돌발톱 산맥에 있는 각심 러스트피즐에게 교신의 두루마리를 가져가야 합니다.", description = "자, 다 됐습니다. 이거면 될 겁니다.\n\n각심을 만나면 안부나 전해 주십시오. 이번 모험의 결과가 어떨지 기대하고 있겠습니다.\n\n부디 몸조심하십시오.", progress = "하하, 돌아왔군! 내가 부탁한 건? 마법 주문 말이오.", completion = "좋아! 수고했소. 이 주문을 NG-5와 함께 사용하면 완벽한 원격 폭발을 실행할 수 있다오.\n\n그래서 녀석들이 우왕좌왕할 때 당신은 놈들 본거지에 숨어 들어가 투자개발회사의 편지와 토목 공사 계획서를 훔쳐내면 되는 거지.\n\n그러면 녀석들의 벌채 작업을 지연시킬 수 있을 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1078] = {title = "마우렌 돕기", objective = "스톰윈드에 있는 콜린 마우렌에게 비늘 결정체 8개를 가져가야 합니다.", description = "여행자들이 계속 내게 돌발톱 산맥에 대해 묻는걸 보니 모험가들에게는 유명한 곳인가 본데... 와이번을 찾는 이, 정령을 찾는 이, 아니면 투자개발회사에 볼일이 있는 이, 정말 다양하답니다.\n\n예전에 돌발톱 산맥 깊은 곳, 잿더미 계곡에 바실리스크들이 살았는데 그 비늘을 가루로 만들면 내가 만든 몇 가지 주문에 맞는 훌륭한 시약이 될 겁니다. 아직 그 바실리스크들이 살고 있다면 내게 그 비늘을 좀 구해다 주십시오.\n\n급할 건 없으니 서두르지 않아도 됩니다만 사례는 후하게 해 드리도록 하죠.", progress = "다시 보는군요. 벌써 돌발톱 산맥의 잿더미 계곡에서 비늘을 구해 돌아온 것인가요?", completion = "완벽하군요. 정말 고맙습니다.\n\n당신이 나를 도와줬듯이 앞으로 언젠가 나도 당신을 도울 날이 있을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n화염술사의 마법봉"},
[1079] = {title = "비밀 작전 - 1단계", objective = "칼바람 바위산에 있는 제재소에서 투자개발회사의 토목 공사 계획서를 찾아 와야 합니다.", description = "이제 다 됐소. 사용 방법을 설명할 테니 잘 들으시오.\n\n이 설명서를 받으시오. 폭탄과 기폭 장치뿐만 아니라 설치 장소까지 자세히 나와 있소. 이번 임무의 성패는 폭파량에 의해 결정되는 게 아니란 사실을 명심하시오. 바위웅덩이 호수 남쪽에 있는 제재소에서 투자개발회사의 토목 공사 계획서를 빼내 오느냐 아니냐에 모든 것이 달려 있다오.", progress = "녀석들의 토목 공사 계획서는 가져왔소?", completion = "정말 훌륭하오! 녀석들에겐 엄청난 타격이었을 게요.\n\n이걸로 투자개발회사 녀석들이 사용하는 기계의 약점을 알아내고 놈들의 설계 기술을 역이용할 수 있겠군. 오늘은 정말 대단한 날이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1080] = {title = "비밀 작전 - 2단계", objective = "칼바람 바위산의 동쪽 끝에 있는 칼바람 광산에서 투자개발회사의 편지를 찾아와야 합니다.", description = "2단계 작전은 1단계와 비슷하오. 혼란을 야기시킨 다음 녀석들에게서 중요한 편지를 빼내 오는 것이지.\n\n이번 계획의 핵심은 녀석들의 편지를 입수하는 것임을 명심하시오. 이미 당신에게 준 설명서에 폭탄을 설치할 장소가 표시되어 있다오. 편지를 가지고 무사히 돌아오길 바라오.", progress = "임무는 어떻게 잘 되어가오?", completion = "놀랍군! 당신의 출중한 능력과 내 발명품이 만나니 세상에 두려울 게 없어. 센티널과 캘라가 무척 기뻐할 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1081] = {title = "티란데의 환대", objective = "다르나서스에서 티란데 위스퍼윈드를 찾아야 합니다.", description = "티란데 위스퍼윈드께서 그대가 이 임무에 동참해 준 데 대한 감사를 직접 표하고 싶어하십니다.\n\n그대의 도움은 겉으로 확실히 드러나는 것은 아니지만 돌발톱 산맥에서 우리의 발판을 아주 확고히 해 줬습니다.\n\n그대가 두 눈으로 확인한 끔찍한 일들에 맞서 우리와 함께할 생각이라면 다르나서스에 있는 달의 신전에서 티란데님을 만나 보도록 하세요.", progress = nil, completion = "엘룬께 영광을... 전에 그대의 이름을 들은 적 있습니다. 아직 젊은 나이에 벌써 자신의 길을 확고히 정한 걸 보니 대단하군요.\n\n감사와 존경의 표시로 이 선물을 받아 준다면 영광이겠습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n개화의 로브불곰 조끼원시림의 사슬 갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n고결한 엘프의 고리"},
[1082] = {title = "파수꾼 테니실", objective = "잿빛 골짜기에 있는 파수꾼 테니실에게 돌아가십시오.", description = "그대는 이곳에서 정말 큰 도움이 되었어요.\n\n잿빛 골짜기에 주둔하고 있는 센티널에 각심과 제가 살아 있다는 소식을 전해주세요. 우리가 투자개발회사를 저지하고 이 땅을 치유하는 임무를 잘 수행하고 있다고 전하면 그대에게 충분한 보상을 해 줄 거예요.\n\n아스트라나르에 가서 테니실을 찾아 보세요. 이 소식을 가지고 돌아가면 그녀가 무척 기뻐할 거예요.", progress = nil, completion = "고맙습니다. 센티널을 대신해 감사드립니다.\n\n캘라... 그리고 각심까지 모두 잘해주고 있다니 무척 기쁘군요. 우리 모두 그대에게 신세를 졌습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1083] = {title = "분노한 정령들", objective = "돌발톱 산맥에 있는 캘라 섀도스피어에게 잿더미 계곡에 있는 불의 정령들로부터 얻은 꺼져 가는 불씨 8개를 가져가야 합니다.", description = "투자개발회사가 잿더미 계곡에서 한 짓이 뭔지는 확실치 않지만 그곳에 살고 있는 존재들에게 제압당하고 있는 것이 확실한 것 같아요.\n\n그들은 숲에 불을 지르고 기계를 사용해 닥치는 대로 계곡을 파괴했죠. 이 무지한 놈들이 저질러 놓은 일 때문에 난폭한 불의 정령들과 화염의 파괴자, 화염의 약탈자들이 풀려나고 말았어요.\n\n그 정령들이 활개를 치는 한 이제 그 땅에서 엘룬의 미소를 다시는 볼 수 없을 거예요.\n\n이들을 처치하고 그 증거로 그들의 꺼져 가는 불씨를 가져오도록 하세요.", progress = "잿더미 계곡을 처음 봤을 때 가슴이 너무 아파 울음을 터뜨릴 뻔 했답니다.", completion = "적들이 죽고 남긴 것을 내 눈으로 확인하니 마음이 놓이는군요. 잘해 주었어요. 고마워요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1084] = {title = "상처 입은 고대정령", objective = "돌발톱 산맥에 있는 캘라 섀도스피어에게 부식된 파편 1개를 가져가야 합니다.", description = "잿더미 계곡의 수호자 고대정령들이 투자개발회사를 몰아내기 위해 뭔가 행동을 취하려 했던 게 확실합니다. 하지만 불행히도 위대한 고대 수호자였던 그들이 오염되고 말았어요.\n\n각심의 말에 의하면 그들이 오염된 건 고블린이 후퇴하면서 사용한 어떤 무기와 관련이 있다고 해요.\n\n그것이 사실인지 확인하고 싶어요. 고대정령들에게서 무기의 파편을 모아 주세요. 각심에게 연구용으로 보내야 해요.\n\n이렇게 부탁드립니다. 뭔가 알아낼 수 있도록 제게 파편을 좀 가져다주세요.", progress = "각심이라면 과거에 투자개발회사가 이 파편을 어떻게 사용했는지 분명 알아낼 수 있을 거예요.", completion = "고마워요.\n\n이거면 고대정령들이 오염된 원인을 밝혀낼 수 있을 거예요. 지금 바로 각심에게 이걸 가져다 줘야겠군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1085] = {title = "돌발톱 산맥에서의 임무", objective = "각심과 대화하십시오.", description = "이 땅의 안전을 위해 함께 일하는 나이트 엘프와 노움에게 있어 지금 돌발톱 산맥의 상황은 걱정스럽기만 해요.\n\n우리는 이 땅을 황폐화시키고 있는 투자개발회사를 막기 위해 이곳에 온 것이랍니다. 우릴 도울 생각이라면 각심과 먼저 얘기해 보세요. 각심의 겉만 보고 너무 나쁘게만 보지 마세요. 그래도 협력의 필요성은 잘 알고 있으니까요.\n\n타라에게 좋은 소식을 전하지 못해 유감이군요. 하지만 곧 그럴 수 있을 거예요.", progress = nil, completion = "불안... 온통 불안과 위험... 그게 지금 이 땅의 상황이외다.\n\n난 나이트 엘프에게 뛰어난 공학과 약간의 마법만 있으면 좀 더 안전할 수 있다는 걸 보여 주러 왔지. 저것 보슈, 마법을 못 쓰게 하는 건 아무 도움이 안 되잖소? 이 세상엔 마법이 필요한 법이지. 그리고 기계공학과 연금술의 도움을 받는다면 절대 실패란 없다우... 오히려 무궁무진한 가능성이 생기지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1086] = {title = "비행장", objective = "투자개발회사의 비행장에 독가스통을 갖다 놓고 연금술사 자마에게 돌아와야 합니다.", description = "당신이 가져다준 독약으로 독가스통을 만들었소. 이제 갖다 놓기만 하면 되는데 이 일은 당신이 해 주시오.\n\n투자개발회사에는 분명 본부와 돌발톱 산맥에 있는 작업장 사이에서 전갈이나 수화물을 전달하는 수단이 있을 것이오. 조그마한 비행장 같은 게 아닐까 싶은데... 큰 비행선이 드나들 만큼 크지는 않지만 아마 작은 비행기라면 가능할 것이오. 돌발톱 산맥에서 투자개발회사가 관할하는 지역을 수색해서 이 비행장이 정말로 있는지 찾아내시오.\n\n비행장을 찾으면 이 독가스통을 그곳에 놓아두시오. 독가스통을 놓고 재빨리 빠져나와야 하오.", progress = nil, completion = "비행장을 찾았다고? 잘했소! 분명 당신이 갖다 놓은 독가스통 때문에 고블린들이 많이 놀랐을 것이오! 그 독가스통이 본부까지 가길 빌어보도록 하지.\n\n당신의 종족에게 좋은 일을 한 것이니 투자개발회사에 독을 퍼뜨린 것에 대한 죄의식 따위는 버리도록 하시오. 그들은 독가스보다 더한 것을 받아도 마땅한 자들이니까.\n\n포세이큰이 동맹들에게 전하는 조그만 지혜가 하나 있다면 바로 이것이오. 승리로 가는 길이라면... 어둠의 길이라도 피하지 말라.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1087] = {title = "세나리우스의 유산", objective = "해바위 야영지 근처에 있는 브랠린 파이어핸드를 위해 세나리우스의 후예, 세나리우스의 딸, 그리고 세나리온 식물학자들을 각각 4명씩 처치해야 합니다.", description = "제가 이 비참한 땅을 얼마나 혐오스러워하는지 모를 거예요. 산봉우리에 있는 세나리우스 일족과 나이트 엘프 드루이드들이 그 알량한 힘으로 마법의 흐름을 막고 있어요. 그들이 그렇게도 아끼는 저 남쪽 멀리 있는 숲에 이르기까지 말이에요.\n\n직접 자에데나르로 돌아가서 그 녀석들을 처리하고 싶지만, 임무를 완수하지 못하면 돌아올 생각은 꿈에도 꾸지 말라는 스승님 말씀 때문에 발길이 떨어지질 않네요.\n\n당신도 나만큼이나 나이트 엘프와 그 동맹들을 미워하는 것 같으니, 날 도와서 이 임무를 좀 완수해주세요.", progress = nil, completion = "이 아름다운 힘... 격렬한 흐름... 벌써 느껴지는군요. 나이트 엘프는 바보들이에요. 마법의 저주가 혈관을 타고 흐를까봐 두려워 이 땅의 선물을 거부하다니... \n\n자신의 육체와 정신 안에서 마법을 느끼지 못하는 삶은 보잘것없고 헛된 것이랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1088] = {title = "오르다누스", objective = "오르다누스를 처치하고 그 증거로 그의 머리 장식을 해바위 야영지 근처에 있는 브랠린 파이어핸드에게 가져가야 합니다.", description = "그들은 마법의 흐름을 막을 수 있다고 자신했지만 오산이었어요. 그리고 오르다누스도 숨길 수 있다고 생각하는 모양이지만 반드시 찾아내고 말 거예요!\n\n마법의 힘으로 제 마음의 눈이 떠졌으니 그 능력을 이용해 보도록 하죠.\n\n어디 보자... 그가 있는 곳이 보이는군요. 교차로가 있고... 잿빛 골짜기 숲에 있는 거대한 나무가 보여요... 아, 그 꼭대기에 있군요. 그 나무의 이름은 라이네라고 해요. 숲의 정령들이 섬기는 신이 낳은 첫 번째 아들이죠. 이런, 벌써 그 꼭대기에서 다른 곳으로 이동했군요. 시간이 얼마 지나지 않았으니 멀리 가지는 못했을 거예요.\n\n제게 오르다누스의 머리 장식을 가져다주면 큰 선물을 드리지요.", progress = "스승님의 지시대로 이곳 해바위 야영지로 왔을 때는 신성한 아즈샤라님의 고대 신전을 더럽히는 나이트 엘프만 처치하면 될 줄 알았었죠. 그런데 오르다누스가 그만 내 손을 벗어나고 말았으니...", completion = "사실 아주 오래전부터 저는 오르다누스의 존재를 알고 있었어요. 대부분의 세나리우스가 그렇듯 오만했고, 자신을 엘프 귀족보다 더 우월한 존재로 여겼답니다. 자만심이 하늘을 찌를 정도였으니까요. 하지만 이제 그 오만함이 더 커지지는 못하겠군요.\n\n자, 당신에게 약속한 보상을 주겠어요. 그런데... 그전에 드릴 말씀이 있으니 잘 들으세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1089] = {title = "갈퀴발톱굴", objective = "돌발톱 봉우리에 있는 갈퀴발톱굴로 가야 합니다. 문지기의 열쇠를 이용해 드루이드의 숨겨진 물건을 얻어야 합니다. 그 물건을 이용해 갈퀴발톱굴 저장고를 여십시오.", description = "드루이드들은 돌발톱 봉우리에 갈퀴발톱굴을 건설하고 강력한 마력이 담긴 물건들을 다량으로 보관하고 있어요.\n\n그들은 그 물건이 다른 이들의 손에 들어가는 것을 막기 위해 복잡한 건축기법을 이용해 미로를 설계했죠. 전 운 좋게도 그 건축가 중 한 명에게서 굴의 구조에 대한 정보를 좀 빼냈어요.\n\n갈퀴발톱굴의 입구 바로 옆에 놓인 작은 등불에 문지기의 열쇠가 보관되어 있을 거예요. 그 열쇠만 있으면 동굴 곳곳에 있는 은닉처를 열 수 있답니다. 그 안에 있는 어떤 물건을 사용하면 동굴 중앙에 있는 저장고를 열 수 있어요.", progress = "돌에 세 개의 열쇠구멍이 나 있습니다.", completion = "각각의 열쇠구멍에 맞는 열쇠를 꽂자 눈부신 빛이 쏟아지며 그 가운데 많은 물건들이 모습을 드러냅니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n신성한 고리표범 갑옷무력의 다리보호구"},
[1090] = {title = "게렌조의 지시", objective = "피즈닉이 미확인 광석을 캐내면 그 광석을 받아야 합니다.", description = "이곳에서 한때 난 2인자 위치에까지 올랐지만 게렌조가 부임하면서 모든 게 변했소. 그는 내 상관 지즈 피직스님을 해고하고 나는 광산에서 광물이나 캐라고 내려보냈지. 지즈님께서 여기 남아서 정보를 수집하라고 하셨기에 참고 있는 것이야. 새로운 상관은 게렌조를 수상히 여기고 그가 꾸미고 있는 계획이 무엇인지 밝혀낸다면 충분한 보상을 하신다고 했소.\n\n어쨌든 내가 아는 건 게렌조가 황녹색 빛 광석을 다량 채굴하도록 지시했다는 거요. 지즈님께 보낼 표본을 구해 볼 테니 그동안 순찰하는 녀석들이 오는지 망을 좀 봐 주시오.", progress = nil, completion = "고맙소. 잠시 위험했던 것 같소. 주위의 시선을 너무 끌었던 것 같군.\n\n어쨌든 광석의 표본을 구했으니 이걸 가능한 빨리 지즈님께 보내야 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1091] = {title = "캘라를 위한 새로운 정보", objective = "캘라 섀도스피어에게 투자개발회사의 편지를 가져가야 합니다.", description = "센티널에서는 이번 일에 대해 확실히 알고 싶어할 테니 이 편지를 캘라에게 가지고 가시오.\n\n그녀에게 우리가 얼마나 성공적으로 일을 처리했는지, 그리고 마법의 힘을 조금 빌리지 않았더라면 결코 성공할 수 없었으리란 점도 전하도록 하시오.", progress = "무슨 일인가요? 제가 도와 드릴 일이 있나요?", completion = "정말 흥미로운 소식이군요.\n\n그대와 각심이 모두 정말 잘해 주었어요. 고마워요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1092] = {title = "게렌조의 지시", objective = "돌발톱 산맥에 있는 지즈 피직스에게 미확인 광석을 가져가야 합니다.", description = "이제 여기서 빠져 나갈 궁리를 하는 게 좋을 것 같군. 이곳에서 일어난 일이 곧 윗선까지 알려질 것이고 다시는 나를 우호적으로 맞아 주지 않을 것이오.\n\n나는 여기서 나가 지즈님을 만날 생각이오. 지즈님이 내게 새로운 일을 맡겨 준다면 좋으련만...\n\n난 이 쓰레기들을 좀 치울 테니 당신은 지금 바로 광석 표본을 지즈님에게 가져가시오. 지즈님은 칼바람 바위산 서쪽 어딘가에 야영지를 세우셨다고 들었소. 행운을 빌어요.", progress = "내가 도와줄 일이라도 있나?", completion = "아, 역시 피즈닉에게 남아 있으라고 한 건 바른 판단이었군. 틀림없이 지하광산의 기술자들이 이 광석에 큰 관심을 가질 거야.\n\n내 것도 물론 조금은 챙겨 놓아야지. 뭐, 그들만 모른다면 아무 문제 없을 테니까. 안 그런가?", rewards = "다음과 같은 것들을 받습니다:\n\n채굴용 장화"},
[1093] = {title = "슈퍼 절단기 6000", objective = "돌발톱 산맥에 있는 지즈 피직스를 위해 슈퍼 절단기 6000 설계도를 입수해야 합니다.", description = "투자개발회사가 이곳에 한 짓은 정말 끔찍하지 않나? 고블린 조합에서 노움을 고용하다니 말이야! 대체 무슨 생각을 하고 있었던 건지...\n\n천재를 알아보는 안목을 갖추신 스퍼터밸브님을 만난 건 정말 행운이었어. 해고된 날 바로 고용해 주셨으니까 말이야!\n\n스퍼터밸브께서 투자개발회사 놈들이 거대한 벌목 기계를 만들었으니 그 설계도를 훔쳐내 달라고 부탁하셨지. 하지만 게렌조, 그 괘씸한 놈이 내 목숨을 노리고 있으니 갈 수가 있어야 말이지... 당신이 날 위해 놈들의 그걸 좀 훔쳐다 주겠나? 아마 운전수 중 누군가 가지고 있을 거야.", progress = "설계도는 손에 넣었나? 나의 새로운 상관께 깊은 인상을 심어주고 싶은데 말이야. 고블린의 명예를 아시는 분이니 내 충성심을 인정하게 된다면... 내 놀라운 천재성을 믿고 더 높은 자리를 맡기지 않겠나?", completion = "그거 혹시 내가 부탁한 설계도인가? 오, 훌륭하군!\n\n자, 보자... 으... 이거 도대체 무슨 내용인지 알 수가 없군. 노움들의 사고방식은 도무지 이해할 수가 없어서 말이야. 그들이 하늘을 나는 기계에다가 바퀴까지 만들어 낼 수 있다는 사실이 놀라울 뿐이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1094] = {title = "또 다른 지시 사항", objective = "불모의 땅에 있는 스퍼터밸브에게 봉인된 편지를 전달해야 합니다.", description = "이 봉투에는 내가 해고되기 전에 입수한 투자개발회사의 내부 문서와 몇 가지 기계의 조작설명서, 기술 자료 같은 방대한 정보가 들어 있어. 아, 물론 슈퍼 절단기 6000 설계도도 물론 넣었지.\n\n불모의 땅에 있는 톱니항에 가면 체구가 작으신 녹색 고블린, 스퍼터밸브님의 거처가 있을 거야.", progress = "안녕하신가! 뭘 도와드릴까?", completion = "피직스라고? 난 그 녀석을 별로 신임하진 않지만 이 정보는 꽤 쓸만한 걸? 게다가 투자개발회사 놈들을 처리할 수만 있다면 무슨 짓인들 못하겠나.\n\n놈들이 그 굉장한 기계를 개발해낸 기술을 이용한다면 우리에게 큰 도움이 될 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1095] = {title = "추가 지령", objective = "돌발톱 산맥에 있는 지즈 피직스에게 새로운 명령을 전해야 합니다.", description = "투자개발회사에 고용된 게렌조라는 노움이 지하광산을 휘젓고 다니면서 문제를 일으키고 있지. 교역 군주들은 라즈덩크가 이 게렌조란 자와 손잡은 것을 탐탁지 않게 여기고 있다네.\n\n조합장 리들복스께서는 내게 이 문제를 처리해 달라고 하셨고, 아마 그분께서도 교역 군주들에게 지시를 받았을 거야. 물론 감독관이 따로 내게 이런 사실을 말해 주건 아니지만 뭐, 내 육감이라고 해 두지.\n\n어쨌든 게렌조는 반드시 처치해야 하니, 피직스에게 맡기면 그를 시험해 볼 수 있는 좋은 기회도 될테니까...", progress = nil, completion = "게렌조를 처치하라고? 이제 내게도 기회가 주어지는군그래.\n\n노움들은 원래 나쁘지만 그 중에서 게렌조는 특히 나쁜 녀석이지. 게렌조는 놈리건에서 수석 기술자로서 비밀 계획을 실행하고 있는 것 같소. 던 모로에 한 번도 침투에 성공한 적이 없어서 자세한 정보는 알아낼 수 없었소. 정말 안타까운 일이지. 우리 보고서에 따르면 뭔지 모를 것이 말 그대로 바로 그들 눈앞에서 폭발했다고 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1096] = {title = "게렌조 렌치휘슬", objective = "돌발톱 산맥에 있는 지즈 피직스에게 게렌조의 기계팔을 가져가야 합니다.", description = "전에 게렌조를 만난 적이 있는데 솔직히 좀 못생겼더군. 살은 썩어 들어가는 것처럼 보였고, 몸 곳곳에는 금속과 기계 장치가 이식되어 있는데다가 팔다리의 일부가 완전히 기계로 대체되어 있었지.\n\n게렌조는 이곳에서 북동쪽 방향으로 바위웅덩이 호수 너머에 있는 물레방아 근처 지역 전체를 감독하고 있지. 난 게렌조를 상대하기는커녕 그곳까지 갈 엄두조차 내지 못했지만 당신이라면 해낼 수 있을 것 같은데...\n\n날 위해 그를 처치해 준다면 넉넉히 사례하도록 하지!", progress = "스퍼터밸브님께서는 게렌조가 죽었다는 증거를 원하실 거야. 그의 기계팔 정도면 될 것 같은데...", completion = "이 기계팔을 좀 보라고... 노움 녀석들만이 이런 걸 생각해 낼 수 있을 거야. 도대체 왜 팔을 잘라내고 거기다 기계팔을 붙이는 건지 이해할 수가 없단 말이지. 그냥 기계팔을 등 뒤에다 붙이면 될 걸 가지고... 쩝, 노움 녀석들이란...\n\n아무튼 이제 게렌조는 일손을 영원히 놓게 되었군. 그나저나 스퍼터밸브님께서 가젯잔이나 지하광산의 땜장이 조합 작업장에 한 자리 마련해 주신다면 좋겠는데...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n기술자의 망토땜장이의 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1097] = {title = "엘모어의 임무", objective = "그리만트 엘모어와 대화해야 합니다.", description = "스톰윈드에 그리만트 엘모어라는 드워프 무기 대장장이가 있답니다. 그가 물건을 전달해 줄 이를 구하고 있다고 알려 왔습니다. 아마 북쪽에 있는 고향에 짐을 보낼 모양입니다.\n\n보아하니 당신은 단련되어 다리가 튼튼한 것 같군요! 다리품 파는 일이라도 관심 있다면 그리만트를 만나 보도록 하시기 바랍니다. 이곳에도 당신 손을 빌릴 일이 있긴 하지만 드워프와의 관계도 돈독히 해야만 한답니다.\n\n스톰윈드 북동쪽에 있는 드워프 지구의 무기 상점에 가면 그리만트 엘모어를 만날 수 있을 겁니다.", progress = nil, completion = "내 짐을 배달하는 걸 도와주러 온 거요? 아주 잘 됐군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1098] = {title = "그림자송곳니 성채의 죽음의추적자", objective = "죽음의추적자 아다만트와 죽음의추적자 빈센트를 찾아야 합니다.", description = "그림자송곳니 성채에 대한 공격을 준비하면서 첩보 수집을 위해 죽음의추적자 2명을 그리로 보냈네. 그들이 떠난 지 여러 날이 지났지만 아직 돌아오지 않고 있어. 우리의 공격이 성공하려면 그들의 보고 내용이 반드시 필요하다네!\n\n그러니 자네가 남쪽에 있는 그림자송곳니 성채로 가서 죽음의추적자 아다만트와 빈센트를 찾아봐 주게. 그들을 찾아서 도움이 필요하다면 도와주고 말이야.\n\n중요한 임무이니만큼 위험이 크지만 절대 실패해서는 안 돼.", progress = nil, completion = "빈센트의 시체입니다.\n\n죽음의추적자 아다만트가 하드렉에게 보고를 하긴 할 테지만 빈센트가 수집한 추가 정보가 있다면 아직 그가 지니고 있을 것입니다.\n\n하지만 그의 손에는 작은 장신구 하나가 쥐여져 있을 뿐입니다...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n유령의 어깨보호대"},
[1099] = {title = "고블린 승리!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n고블린 상품"},
[1100] = {title = "론브로우의 일지", objective = "헨리그 론브로우의 일지를 읽으십시오.", description = "헨리그 론브로우의 빛 바랜 일지를 천천히 열어 봅니다.", progress = "당신의 걱정스러운 눈빛을 보아하니 뭔가 잘못된 모양인데...", completion = "죽은 드워프에게서 이 일지를 발견했단 말이오? 잠시 읽어 볼 시간을 좀 주시오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1101] = {title = "가시덩굴 우리의 대모", objective = "탈라나르에 있는 팔핀델 웨이워더에게 차를가의 메달을 가져가야 합니다.", description = "불쌍한 헤랄라스! 그리고 이 드워프, 론브로우... 정말 용감했는데...\n\n이들의 용맹스러운 죽음을 헛되이 할 수는 없소. 서슬깃 차를가라는 대모를 처치해야만 하오.\n\n두말할 필요도 없이, 가시덩굴 우리에 침투하는 것은 위험한 일일 것이오. 하지만 다르나서스로 소식을 전할 시간이 없소. 병력을 좀 모아서 대모를 처치해 주시오.\n\n그리고 그 증거로 차를가의 메달을 내게 가져오시오.", progress = "서슬깃 차를가가 가시덩굴 우리에서 계속 병력을 모으는 한 이 땅은 아주 큰 위험의 소용돌이에 빠져 있는 것이오.", completion = "드디어 해치웠군. 대단히 기쁜 소식이오.\n\n이렇게 힘든 시기에 당신처럼 용감한 이를 보게 되어 정말 기운이 나는구려.\n\n서슬깃 차를가와 그 졸개들을 처치했으니 나는 이곳에서 조사를 계속할 수 있게 되었소. 어쩌면 이제 아감마간의 안식처가 타락한 정확한 원인을 알아낼 수 있을지도 모르겠군.\n\n하지만, 그 해답을 얻기가 쉽지는 않을 것 같소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n담녹색 어깨보호대돌주먹 벨트대리석 버클러\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n\"백발백중\" 나팔총"},
[1102] = {title = "운명의 복수", objective = "썬더 블러프에 있는 아울드 스톤스파이어에게 차를가의 심장을 가져가야 합니다.", description = "이곳 썬더 블러프에서 우리 종족을 단결시킨 케른님이야말로 훌륭한 지도자시지.\n\n하지만 우리 조상들의 땅에서 우릴 몰아낸 자들은 용서할 수가 없네. 우리 타우렌들은 불모의 땅 남부에서 수십 년 동안 살아왔지. 우리에게는 신성한 땅이었지만 여러 적들에 의해 쫓겨나고 말았다네.\n\n가시덩굴 우리 내에서 사악한 군단의 병력을 모으고 있는 노파, 서슬깃 차를가에게는 반드시 복수를 해주어야만 해.\n\n내가 죽더라도 두 눈을 편히 감을 수 있도록 차를가의 심장을 내게 가져다주게.", progress = "난 가시덩굴 우리에 있는 저 사악한 짐승들을 더러운 은신처에서 몰아낸 후에나 복수를 했다는 생각에 편히 잠들 수 있을 것 같네.\n\n가시덩굴 우리에서 가시멧돼지들을 쫓아냈나? 서슬깃 차를가의 심장을 들고 내게 기쁜 소식을 전하러 온 건가?", completion = "이제서야 그 고약한 가시덩굴 우리의 일족도 우리 종족이 겪었던 고통을 맛보았군. 더러운 짐승 놈들, 아주 잘 됐어.\n\n성스러운 땅에서 사는 이들을 몰아내는 것은 무서운 복수를 받아 마땅한 죄지.\n\n곤경에 처한 나를 도와줘서 고맙네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n담녹색 어깨보호대돌주먹 벨트대리석 버클러\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1103] = {title = "물의 부름", objective = "하급 물의 현신과 대화하지 못했으면 은빛소나무 숲에 있는 티에브 모르둔에게 물의 정기를 가져다주어야 합니다.", description = "만나서 반갑네! 그대도 이곳의 물을 정화시키셔 이슬렌에게 능력을 증명해 보이려고 왔나?\n\n방금 내 손으로 타락한 물의 정령을 물리치고 팔보호구와 순수한 물의 나머지 분량을 화로에 넣으려던 참이었지.\n\n뭐라고? 이 티에브는 뭔가 잘못되면 바로바로 알 수 있지. 기꺼이 도와줌세. 하급 물의 현신을 다시 불러내야 할 거야.\n\n자네는 이슬렌에게서 물의 정기를 다시 받아오게. 그러면 나도 내 몫을 하지.", progress = nil, completion = nil, rewards = nil},
[1104] = {title = "소금기 있는 전갈 독", objective = "소금 평원에 있는 피즐 브라스볼츠에게 소금기 있는 전갈 독 6개를 가져가야 합니다.", description = "난 다양한 모양의 로켓 자동차를 아주 많이 설계해 놓았소! 내 사랑스러운 차들을 전부 다 경주에 출전시킬 거요!\n\n지금은 새로운 연료를 연구하고 있소이다. 정말 아주 아주 활활 타는 연료 말이오! 아직 완벽한 혼합물을 만들어 내지는 못했지만 뭐가 필요한지는 알고 있소.\n\n소금 평원에 돌아다니는 전갈들은 소금이 아주 많이 함유된 독을 가지고 있다오. 전갈에서만 구할 수 있는 아주 독특한 것이오! 바로 그게 필요하단 말이지!\n\n내가 연구를 계속 할 수 있도록 그 독만 구해다 준다면 우리 차는 날아다닐 정도로 빨라질 거요!", progress = "하하! 또 보는군! 독은 구해 왔소?", completion = "좋았어! 이 독은 굉장한 효과를 발휘할 거요! 정말 고맙소!\n\n이제 이걸 끓여서 졸인 다음 경화 촉진제를 넣고 음촉매제까지 넣으면... 이런! 그런데 내 비법이 담긴 노트가 어디 갔지!?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1105] = {title = "단단한 등껍질", objective = "소금 평원에 있는 위즐 브라스볼츠에게 단단한 거북 등껍질 9개를 가져가야 합니다.", description = "우리 형 피즐은 로켓 자동차에 사용할 새로운 연료를 연구하고 있다오. 형은 정말 똑똑하지. 너무 똑똑해서 탈이지만... 형이 연구 중인 새 연료는 너무 강력해서 차체가 견뎌 낼 수 있을지 걱정이오!\n\n폭발이라도 일어나면 큰 일이지. 그래서 연료 탱크를 강화하고 싶은데 말이지.\n\n소금 평원에 사는 거북이들의 등껍질은 아주 단단하다오. 그걸 이용해서 로켓 자동차에 사용할 새 연료 탱크를 만들어 보고 싶소이다. 형이 만들 새 연료를 담을 수 있는 연료 탱크를 말이오.\n\n보아하니 당신은 믿음이 좀 가는데, 그 등껍질을 좀 가져다주겠소이까?", progress = "형이 새로운 연료의 개발을 거의 완성해 가고 있소. 한시라도 빨리 거북 등껍질 연료 탱크를 제작해야 하는데... 점점 더 걱정이 되는군.\n\n등껍질은 아직 안 가져왔소?", completion = "가져왔구려! 고맙소!\n\n이야, 이 등껍질은 내가 생각했던 것보다 훨씬 더 단단하군! 하하, 내 연장이 전부 남아나지 않겠는 걸!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1106] = {title = "망명자 마르텍", objective = "황야의 땅에 있는 망명자 마르텍에게 피즐의 편지를 가져가야 합니다.", description = "지금 엄청난 속도를 낼 수 있는 새로운 자동차 엔진을 개발하는 중이오. 내가 장담하는데 분명히 자동차가 날아다닐 정도로 빨라질 거요! 그러려면 엄청나게 강한 압력을 견딜 수 있는 피스톤을 만들어야 하는데... 지금까지의 피스톤은 강도가 충분하지 않아서 다 실패하고 말았소!\n\n이 문제를 해결할 수 있는 자를 알고 있소.\n\n망명자 마르텍이라는 친구인데, 금속에 대한 지식이라면 누구도 따라 올 수 없는 유능한 대장장이라오. 그라면 충분히 우릴 도울 수 있을 테니 그에게 이 편지를 전해 주시오!\n\n그자는 아주 아주 먼 동부 왕국의 황야의 땅이라는 곳에 있는 야영지에서 고블린들과 함께 살고 있다오.\n\n그를 찾아봐 주시오!", progress = "흠, 용케도 날 찾아냈군.\n\n가스일조그에게 주려고 만든 도끼를 구하러 온건가? 아니면 공작부인 파메이의 명예를 되찾으러 온건가?\n\n사실, 무슨 일로 왔든 나야 상관없지만... 싸우러 온건가? 그럼 바로 시작하지!", completion = "피즐이 보냈다고? 그렇다면 얘기가 달라지지. 기꺼이 도움을 드리겠소이다! 암, 피즐과 그의 동생은 내가 죽지 않기를 바라는 몇 안 되는 이들 중 하나니까...\n\n음... 그러니까 지금 피즐이 피스톤을 만들고 싶어한다는 얘기요? 그 어떤 압력도 견딜 만큼 강력한 피스톤이라... 피즐이라면 마치 바퀴에 불이 날 정도로 어마어마한 힘을 내뿜는 차를 만들어 낼 수 있을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1107] = {title = "딱딱한 꼬리지느러미", objective = "소금 평원에 있는 위즐 브라스볼츠에게 딱딱한 꼬리지느러미 10개를 가져가야 합니다.", description = "우리가 만든 로켓 자동차는 소금 평원에서 최고로 빠르지! 하도 빨라서 마찰 때문에 차체가 산산조각 나지 않을까 걱정될 정도랍니다!\n\n그래서 새로 합성물을 만들어 자동차에서 움직이는 부품의 표면에 입혀야 하오. 그 합성물은 단단하고 안정적이면서도 소금에 부식되지 않아야만 하지. 안 그러면 소금 평원 같은 곳에서는 차체가 남아 나질 않을 거요.\n\n썩은내 산호초라는 곳에 대해 들어 봤소? 가시덤불 골짜기 해안 근처에 있지. 그곳에는 소금비늘멀록들이 살고 있는데 놈들의 꼬리 지느러미가 내가 만들려는 이 합성물의 중요한 재료라오.", progress = "꼬리 지느러미는 가져 왔소? 차체가 빠른 속도를 견디어 내야만 경주에서 오래 살아남을 수 있소.", completion = "고맙소이다! 이걸 갈아서 몇 가지 다른 원료들과 함께 녹이면 합성물이 완성될 것이오. 드디어 아무리 빠른 속도라도 견딜 수 있는 안전한 차를 만들 수 있겠군. 조종사는 다칠 걱정이 전혀 없게 되었소! \n\n흠... 어디에다 들이받지만 않는다면 말이지...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1108] = {title = "인듀리움 광석", objective = "황야의 땅에 있는 망명자 마르텍에게 인듀리움 조각 10개를 가져가야 합니다.", description = "내가 그저 속세를 떠나려고 이곳으로 온건 아니었다오. 황야의 땅은 금속 자원의 무한한 보고요. 당신도 배짱만 있다면 황야의 땅에서 인듀리움이라는 금속을 얼마든지 가져갈 수 있소.\n\n그 금속은 열과 압력에 아주 강하다고 알려져 있소. 그러니 피즐의 피스톤에 사용하면 아주 그만일 거요.\n\n하지만 확실히 해 두는 게 좋겠지. 내게 인듀리움 견본을 가져다주면 그 특성을 시험해 보겠소.\n\n순수한 성분의 인듀리움 광석은 울다만의 깊숙한 곳에 매장되어 있지만, 황야의 땅의 바위동굴 트로그들이 그 광석의 조각을 지니고 있는 경우도 종종 있다고 하오. 내게 그 조각을 가져다주시오.", progress = "인듀리움 조각은 구해 왔소? 노를 달구고 시험해 볼 준비도 다 해 놨소.", completion = "아, 그래. 이거면 되겠군. 이제 이 조각에 열을 좀 가해 어떻게 되는지 보도록 하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1109] = {title = "조분석을 나에게!", objective = "언더시티에 있는 수석 연금술사 파라넬에게 가시덩굴 조분석을 가져가야 합니다.", description = "자네도 알겠지만 우린 왕립 연금술 학회에서 재미있는 실험을 하고 있다네.\n\n나는 이곳의 수석 연금술사로서 우리가 가장 야심 차게 진행하는 연금술 실험을 감독하고 있지. 일이 많으니 시간이 부족할 수밖에 없다네!\n\n자네는 여행을 자주 하는 것 같으니 나를 좀 도와 줄 수 있을 걸세.\n\n내게 필요한 재료가 희귀한 것이라 문제야. 그게 좀 지저분한 물건인데 가시덩굴 우리라는 오물 구덩이에만 사는 희귀한 종류의 박쥐에게서 얻을 수 있지. 실험을 시작할 수 있도록 동굴박쥐의 조분석을 좀 가져다주게나.", progress = "돌아왔군. 가시덩굴 조분석을 구했나?", completion = "훌륭해! 이제야 일을 시작할 수 있겠군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1110] = {title = "로켓 자동차 부품", objective = "소금 평원의 크레이블 콜비어드에게 로켓 자동차 부품 30개를 가져가야 합니다.", description = "헤헤, 이곳에서 경주를 구경하다 보면 종종 불행한 사고가 일어나곤 하지. 아마 소금 평원을 돌아다녀 보면 과거에 있었던 충돌 사고의 흔적들을 볼 수 있을 거요. 로켓 자동차 부품의 잔해가 곳곳에 흩어져 있거든.\n\n노움과 고블린에게는 그 부품들이 곧 돈이오. 그들은 늘 자신의 차에 장착할 새로운 장치를 찾느라 혈안이 되어 있소.\n\n그러니 가서 그 부품들을 가져오시오. 많이 가져다 준다면 값을 후하게 쳐 주도록 하겠소.", progress = "소금 평원을 돌아봤소? 내가 말한 부품은 다 가져왔고?", completion = "와, 이것들 좀 보라고! 그 쓰레기 더미 속에 쓸만한 것들이 좀 있군. 이걸 저당 잡히면 꽤 큰돈을 만질 수 있겠어.\n\n그런데... 저 철판 사이에 짓눌려 있는 건 거북이 꼬리 아니오?? 흐익! 난 저렇게 되고 싶지는 않다고!\n\n고맙소이다. 여기 당신 몫이오. 그리고 삶에 도움이 될 조언도 공짜로 좀 해주지. 살다 보면 다른 자의 불행이 나에게는 행복이 될 경우도 가끔 생길 수 있지... 아니, 나는 항상 그랬군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1111] = {title = "부두주임 디지위그", objective = "톱니항에 있는 부두주임 디지위그에게 크레이블의 부품주문서를 가져가야 합니다.", description = "사람들에게 필요한 물건을 구해다 주는 게 내 일인데, 여기서 멀리 떨어진 곳에 있는 노움들이 부품을 주문해 왔소. 그 부품이 일주일 전 톱니항에 도착했는데 바빠서 아직 못 찾아 왔소.\n\n그래서 말인데 발품 파는 일거리를 원한다면 톱니항으로 가서 이 부품주문서를 부두에 있는 부두주임 디지위그에게 보여 주도록 하시오.\n\n이 일을 해 준다면 앞으로 더 많은 일을 맡기도록 하겠소.\n\n꽤 짭짤한 이익을 볼 수 있는 일거리를 말이오.", progress = "좀 큰 소리로 말하라고! 도대체 물건을 보내러 온건가, 찾으러 온건가?", completion = "아, 그렇군. 크레이블이 주문한 부품이라... 마침 잘 왔어. 그 물건들이 며칠째 이곳에 방치되어 있던 터라 녹이 슬지나 않을까 걱정하던 참이었네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1112] = {title = "크레이블의 부품", objective = "소금 평원에 있는 크레이블 콜비어드에게 크레이블의 부품을 가져가야 합니다.", description = "크레이블 앞으로 도착한 짐은 여기 있소. 그리고 그에게 물건을 전해 줄 때 이 말도 좀 전해 주시오. 특별 주문을 하려면 외상값이나 먼저 갚고 하라고 말이오!", progress = "톱니항에 가서 부품을 가져왔소?", completion = "제대로 가져왔군. 잘했소! 이제 그걸 노움들에게 전해야 하오. 하지만 그 전에...\n\n작은 거 하나를 좀 빼놓고...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1113] = {title = "열정의 증거", objective = "언더시티에 있는 수석 연금술사 파라넬에게 열정의 증거 20개를 가져가야 합니다.", description = "왜 희귀한 조분석이 필요한지 궁금하겠지? 나는 이 실험에서 서로 상반되는 두 화학 물질이 어떤 영향을 주고 받는지 알고 싶다네. 특히 두 물질을 독극물과 결합하면 어떤 무서운 결과가 나올까...\n\n티리스팔 숲 북동쪽에 붉은십자군 수도원이 있네. 붉은십자군 광신도들이 있는 곳이지. 그들을 해치우고 열정의 증거를 가져오게.\n\n최고로 무시무시한 화합물이 될 것이야!", progress = "붉은십자군 수도원에서 돌아왔나? 이 재미있는 실험을 위해선 재료가 많이 필요하네.\n\n바리마트라스님과 어둠의 여왕 폐하께서도 붉은십자군 쓰레기들이 사라져 좋아할 걸세.", completion = "정말 많이도 가져왔군! 자네는 최고일세!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1114] = {title = "노움에게 배달", objective = "소금 평원에 있는 피즐 브라스볼츠에게 정밀한 부품을 가져가야 합니다.", description = "내가 필요한 건 챙겼으니 이제 이 부품들을 피즐 브라스볼츠에게 가져다 주시오. 오랫동안 목 빠지게 기다리고 있었으니까... 아마 주문한 물품 중에서 내가 일부러 하나를 빼서 줬다는 것도 금방 알아차릴 테지.\n\n그래, 그걸 굳이 말할 필요는 없을 거요. 작고 쓸모없는 물건이니까.\n\n날 믿으시오.", progress = "내게 뭔가 줄 게 있다고 했소? 그거 잘됐군! 어디 한번 봅시다!", completion = "아, 드디어 도착했군! 내가 주문한 수력래칫, 그리고 연발볼트! 이거면 완벽해... 정말 고맙소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1115] = {title = "소문을 퍼뜨리는 자", objective = "무법항에 있는 크라젝과 대화하십시오.", description = "우린 지금껏 노움을 위해 일해 왔으니 이제 고블린을 위해 일할 때가 됐소! \n\n내가 듣기로 고블린 조종사 나즈 스팀보일은 다른 이름을 하나 더 갖고 있다고 하오. 난 그가 왜 이름을 바꿨는지 궁금하고 그게 왜 비밀인지도 궁금하오. 또한 그가 그 비밀을 왜 중요하게 생각하는지도 알고 싶소.\n\n진실을 알 만한 이는 가시덤불 골짜기의 남쪽 끝, 무법항에 있는 크라젝뿐이오. 크라젝을 만나 이 고블린 조종사에 대해 물어보도록 하시오.\n\n그에게서 유용한 정보를 얻을 수 있다면 돈을 좀 벌 수도 있을 테니까.", progress = nil, completion = "나즈 스팀보일에 대해 알고 싶다고요? 소금 평원의 경주용차 조종사 아닌가요?\n\n뭔가 알아낼 수 있을지도 모르겠지만 쉽지는 않을 거예요. 시간도 많이 걸리고...\n\n비용도 만만찮게 들 텐데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1116] = {title = "습지의 꿈가루", objective = "무법항에 있는 크라젝에게 꿈가루 10줌을 가져가야 합니다. 꿈가루는 슬픔의 늪에 있는 용들에게서 얻을 수 있습니다.", description = "나즈에 대한 정보를 수집하는 건 쉬운 일이 아니죠. 그럼요, 만만히 볼 일은 아니랍니다. 하지만 당신은 저 멀리 소금 평원에서 이곳까지 정보를 얻으러 올 정도의 끈기를 지닌 분이니... 흠, 발품을 조금만 더 팔아 보시겠어요?\n\n내게 뭐라도 좀 구해다 주는 건 어떨까요? 난 그동안 정보원들과 연락을 해야 하니까요.\n\n흠... 뭐가 좋을까? 그래, 꿈가루! 그게 좋겠어요. 슬픔의 늪에 있는 용들에게서 꿈가루를 구해다 주세요. 그걸 코담배 주머니에 몇 줌씩 담아 가지고 다니며 향을 맡으면 정말 환상적이랍니다!\n\n제게 그걸 구해다 주면 당신이 원하는 정보를 드리죠.", progress = "벌써 돌아왔어요? 부탁 드린 꿈가루는 구했나요?", completion = "오, 정말 꿈가루로군요!\n\n그래, 그 늪지는 어땠나요? 거기서 사냥하는 게 쉽지는 않았을 텐데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1117] = {title = "크레이블을 위한 소문", objective = "소금 평원에 있는 크레이블 콜비어드에게 고블린의 소문을 가져가야 합니다.", description = "여기저기 물어도 보고, 귀한 엘프 와인도 한 병 구해서 정보의 대가로 주고, 또 나 스스로도 열심히 추론을 한 끝에, 마침내 당신이 원하는 정보를 입수했어요.\n\n자, 나즈 스팀보일이라는 친구에 관한 아주 재미있는 정보를 이 편지에 적었어요. 내가 써먹기에는 너무 위험하니 당신이 알아서 하세요.\n\n어디서 구했는지는 아무에게도 말하지 말고요!", progress = "나즈 스팀보일에 대해 좀 알아냈소? 그의 비밀이 대체 뭐라든가요?", completion = "이런, 이런! 이거 재미있군... 아주 재미있어. 허허, 다음에 이 고블린 조종사를 만나면 웃음보가 터져 참을 수 없겠어.\n\n이거면 충분하오. 나즈 그 친구, 아마 자기 비밀이 들통난 걸 알면 내 손에 한두 푼이라도 쥐어 주려고 할 거요... 입막음을 하려고 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1118] = {title = "무법항으로의 귀환", objective = "피즐버브에게 보내는 편지를 무법항에 있는 크랭크 피즐버브에게 가져가야 합니다.", description = "당신은 정말 믿을 수 있는 <class>|1이요;요;. 날 위해 일을 완수해 준 것도 그렇고, 그 일을 하는 동안 입이 무거웠던 것도 그렇고...\n\n난 새로운 계획을 구상하던 참이오. 위험 부담은 있지만, 성공하면 우리 둘 다 큰돈을 만지게 될 거요! 그 일엔 당신이 적격이라고 생각하오.\n\n우리의 계획을 시작하려면 다시 무법항으로 돌아가야 하오. 미안하오, 좋은 친구. 지난번 부탁한 일로 멀리 그곳까지 다녀왔는데 이렇게 고단한 길을 다시 가도록 만들어서 말이오. 이번에는 크랭크 피즐버브를 만나 보시오.\n\n그에게 이 편지를 전하고 그가 도움을 필요로 하면 최선을 다해 그를 도와주길 바라오. 그럴 만한 가치가 있는 일이니까.", progress = "하하, 안녕하신가요! 귀하신 <race>께서 무법항엔 어쩐 일이신지요?", completion = "음, 알겠습니다. 크레이블이 아주 대단한 일을 꾸미고 있군요... 그는 성품이 못 됐지만 뭐, 전 그런 성격이 아주 마음에 든답니다.\n\n어디 보자, 그러니까 정신을 흐리게 만들 뭔가가 필요하단 얘기지요? 뭔가 강력한 것으로...\n\n잔질이 그의 좀비들에게 먹이는 혼합물을 사용하면 어떨까 싶은데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1119] = {title = "잔질의 혼합물과 멍텅구리 스타우트 맥주", objective = "소금 평원의 크레이블에게 멍텅구리 스타우트 맥주를 가지고 돌아가야 합니다.", description = "스타우트에 잔질의 혼합물을 섞으면 아주 강력한 효과를 낼 수 있다는 사실을 알아냈습니다. 바로 멍텅구리 스타우트라는 것이 탄생했죠. 바로 이게 크레이블에게 꼭 필요할 겁니다. 써보고 효과가 어땠는지 알려 주세요.\n\n그리고 너무 오래 두지는 마세요. 시간이 지나면 상하니까요. 잔질의 혼합물 때문에 스타우트의 효소가 기형적으로 변했답니다.", progress = "그래, 피즐버브가 도움을 주었소?", completion = "좋았어! 피즐버브가 해냈구려! 기억해 두었다가 다음에 만나면 고맙단 말이라도 해야겠소.\n\n그리고 당신에게도 정말 고맙소. 큰일을 해주고 있소. 이제 우리 둘 다 진짜 큰돈을 만지게 될 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1120] = {title = "노움 취하게 하기", objective = "노움 정비주임에게 멍텅구리 스타우트 맥주를 가져가야 합니다.", description = "이 멍텅구리 스타우트 맥주를 정비공 하나에게 먹여봐야겠군. 노움에게 먹여볼 생각이라면... 자, 받으시오. 이 스타우트 맥주를 노움 정비주임에게 갖다주시오.\n\n너무 오래 지체하지 않는 게 좋을 거요. 스타우트 맥주의 맛이 변할지도 모르니까 말이오.", progress = "안녕하세요! 제게 줄 거라도 있나요?", completion = "스타우트 맥주? 뭘 이런 것까지... 아무튼 고마워요!\n\n슬슬 경주할 때도 되어가고 해서 술은 자제하고 있는 중이지만... 정비공이 운전을 하는 것도 아닌데 조금쯤은 괜찮겠죠. 그리고 맥주가 그렇게 독한 술도 아니잖아요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1121] = {title = "고블린 취하게 하기", objective = "고블린 정비주임에게 멍텅구리 스타우트 맥주를 가져가야 합니다.", description = "이 멍텅구리 스타우트 맥주를 정비공 하나에게 먹여봐야겠군. 고블린에게 먹여볼 생각이라면... 자, 받으시오. 이 스타우트 맥주를 고블린 정비주임에게 갖다주시오.\n\n너무 오래 지체하지 않는 게 좋을 거요. 스타우트 맥주의 맛이 변할지도 모르니까 말이오.", progress = "뭘 훔쳐 보는 겐가?", completion = "이게 뭐야? 술이로군.\n\n뭐, 근무 중이긴 하지만 조금 맛만 본다면 괜찮겠지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1122] = {title = "피즐버브에게 돌아가기", objective = "무법항에 있는 크랭크 피즐버브에게 멍텅구리 스타우트 보고서를 가져가야 합니다.", description = "멍텅구리 스타우트 맥주는 그 이름처럼 효과도 끝내 주는군! 바로 다음 경주에 돈을 걸었네... 하하! 이제 그걸 마신 정비공들이 술기운에 정비를 어떻게 하는지만 앉아서 지켜보면 되겠지.\n\n이제 마지막으로 한 가지 일만 더 해 주시오. 무법항에 있는 크랭크 피즐버브에게 다시 가서 이 쪽지를 전해 주시오. 그자도 이 실험이 성공했는지 궁금할 테니까...\n\n그리고 앞으로 있을 경주를 위해 멍텅구리 스타우트를 좀 더 얻고 싶은데...", progress = "오랜만이군요. 그 스타우트 맥주의 효과는 어땠나요? 정말 강력하죠?", completion = "멍텅구리 스타우트 맥주의 효과가 아주 끝내준다고 적혀 있군요. 정말 기쁜 소식입니다!\n\n더 필요하면 언제든지 말씀하세요. 당신이 잔질의 혼합물만 더 구해다 주면 되니까, 저야 항상 대환영이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1123] = {title = "라빈 사투르나", objective = "달의 숲의 나이트헤이븐에 있는 라빈 사투르나와 대화해야 합니다. 달의 숲은 악령의 숲과 여명의 설원 사이에 있으며 나무구렁 요새에서 나가는 길을 통해 갈 수 있습니다.", description = "이번 임무를 위해 달의 숲에 있는 수호자 레물로스의 청지기인 라빈 사투르나가 타나리스에서 서쪽으로 멀리 떨어진 광활한 황무지를 탐험하는 데 도움을 줄 자를 찾고 있네. 운고로의 서쪽으로 훨씬 더 멀리 떨어져 있는 곳이지. 라빈은 달의 숲에서 제일 큰 마을인 나이트헤이븐에 살고 있다네.\n\n내 그대에게 그대가 가는 것이 중요하다는 걸 강조하고 싶군. 다르나서스의 나이트 엘프와 달의 숲의 세나리온 의회 간에 긴장감이 날로 커져가고 있어서 말이야. 그곳의 세나리온 의회와 상대할 때에는 종족 간의 차이를 떠나 그대 선조들의 지혜를 빌리도록 하게나. 행운을 빌겠네.", progress = nil, completion = "내가 라빈 사투르나요. 수호자 레물로스님과 이 신성한 숲의 모든 주민들을 대신해 그대를 환영하는 바이오.\n\n그대가 관심과 열의를 가지고 세나리온 의회를 돕고자 하니 감사할 따름이오. 타우렌 종족은 지금까지 세나리우스의 교리를 충실히 따라왔기에 타우렌 종족의 대리자라면 호드도 이 숲의 안전을 해치지 않는 한 환영이오이다. 우리는 아제로스의 보존이라는 공통된 목표를 가지고 있소.\n\n여기서는 모두 친구니 안심해도 좋소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1124] = {title = "황무지", objective = "실리더스의 묘지인 용사의 안식처 근처에 있는 라요 스타스트라이크를 찾아가 라빈의 편지를 보여주어야 합니다.", description = "북서쪽 산등성이를 타고 운고로 분화구의 서쪽으로 가면 실리더스라는 거친 황무지가 있소. 먼 옛날 그곳에서 우리 나이트 엘프가 사악한 외계 세력에 맞서 전쟁을 치렀다는 사실을 아는 이는 몇 없지. 그때 사악한 힘은 봉인되었지만 누군가... 말로 다 표현할 수 없을 만큼 커다란 공포를 다시 퍼뜨리려는 것 같소.\n\n실리더스에 우리 동지인 라요 스타스트라이크가 있소. 황무지에서 숨을 거둔 이들의 최종 정착지인 용사의 안식처에 가면 그를 찾을 수 있을 거요. 라요에게 이 편지를 전해주면 그대를 믿을 것이오.", progress = "이곳은 그냥 여행 삼아 오기에는 너무 위험한 곳인데... <class>|1이여;여;, 무슨 일로 이 실리더스 황무지까지 온 거요?", completion = "라빈이 보낸 거로군... 어서 오시오. 내 비록 이 버려진 적막한 땅에서 누군가를 환영할 처지는 못 되지만 말이오.\n\n사실 이곳에 커다란 재난이 닥쳤을 때 난 아직 태어나지도 않았지만, 이 사막은 잊혀진 과거를 떠올리게 하는 오싹한 단편이라고 할 수 있지. 그대의 도움만 있다면 우리 세나리온 의회에서는 벌써 오래전에 제거했어야 할 위협을 완전히 없애버릴 수 있을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1125] = {title = "마파람의 영혼", objective = "마파람 마을에서 고통받는 드루이드 8명과 고통받는 파수꾼 8명의 영혼을 해방한 후, 실리더스, 용사의 안식처 묘지에 있는 라요 스타스트라이크에게 돌아가야 합니다.", description = "<name>! 여기서 남서쪽으로 조금만 가면 마파람 마을이라는 비극의 장소가 있소. 바로 그곳이 우리가 일을 시작해야 할 곳이오...\n\n우리가 알아낸 바에 의하면 그 마을은 한 때 나이트 엘프가 실리더스의 거점으로 삼았었지만 오래전 황무지에 들끓고 있는 실리시드 무리에게 점령당했소. 마을이 처음 산산조각났을 때의 공포가 어땠을지 짐작이 가고도 남소...\n\n죽은 드루이드와 파수꾼의 고통 받는 영혼이 그 폐허에서 방황하고 있소. 마을을 조사해 이 비극의 영혼들을 해방해주시오.", progress = nil, completion = "나는 마을의 폐허 근처에 있는 거대한 벌집 모양의 소굴이 이 파멸과 관련이 있지 않을까 생각했었소. 이번 일로 미루어 보건대 내 추측이 옳았던 것 같소. 그 소굴은 우리가 앞으로 하려는 일에 큰 장애가 될 것이 분명하오.\n\n망자들의 영혼을 자유롭게 해준 그대의 노고에 감사를 표하고 싶소. 그런 일은 결코 쉬운 게 아니라는 걸 나도 잘 알고 있소이다. 다른 일을 맡을 준비가 됐다면 또 한 번 도움을 청하고 싶군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1126] = {title = "탑 속 소굴", objective = "마파람 마을에 있는 탑 위로 올라가 실리시드 소굴을 들쑤셔 놓을 방법을 찾아야 합니다. 그러는 가운데 뭔가 알아낸 것이 있으면 실리더스의 용사의 안식처 묘지에 있는 라요 스타스트라이크에게 보고해야 합니다.", description = "마파람 마을에 있는 소굴을 처리해야 하는데, 내게 한 가지 방법이 있소. 내 경험에 의하면 실리시드 소굴은 주변 환경에 매우 민감하오. 죽음으로 울부짖는 영혼의 소리가 들리면 공격을 해대는 것도 그 때문이지.\n\n말벌 떼가 둘러싸고 있는 탑에 실리시드가 가장 많소. 탑에 올라가서 소굴을 들쑤셔 놓으시오. 뭐라도 알아내거든 알려주고, 조심하기 바라오! 도움이 될만한 걸 찾거든 내게 가지고 돌아 오시오.", progress = "그래, 됐소? 무사한 걸 보니 다행입니다만 뭔가 찾아낸 거라도 있소?", completion = "도대체 이게... 이게 뭐지?\n\n모양이... 상자 같은데? 뭔가 지독한 것에 뒤덮여 있군. 가만, 이쪽에 덮여 있지 않은 부분이 있군. 이... 끈적끈적한 것에 덮여 있는 것이 책인가?\n\n뭔가 굉장한 걸 찾아온 것 같소. 적어도 그랬으면 좋겠소. 고대 시절에 쓴 일기나 일지 같은 게 이 껍질 속에 보존된 것일지도 모르고 말이오\n\n이게 뭔지 알아낼 방법이 하나 있긴 하지만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1127] = {title = "멍텅구리 스타우트 맥주", objective = "무법항에 있는 크랭크 피즐버브에게 잔질의 혼합물 12개를 가져가야 합니다.", description = "멍텅구리 스타우트 맥주가 더 필요하단 말씀이죠? 다시 경주에 돈을 거시려고...?\n\n좋습니다. 잔질의 혼합물만 더 가져다주면 스타우트 맥주를 얼마든지 더 만들어 드리지요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n멍텅구리 스타우트 맥주"},
[1130] = {title = "멜로르의 전갈", objective = "썬더 블러프에 있는 멜로르 스톤후프와 대화하십시오.", description = "멜로르 스톤후프가 자네의 활약상을 듣고서 일을 맡기겠다고 하네.\n\n생각이 있다면 썬더 블러프로 가서 멜로르를 만나 보게나. 수렵의 봉우리에서 그를 찾을 수 있을 게야.", progress = nil, completion = "바로 당신이 그 용감하다던 &lt;race&gt;|1이로군;로군;. 자, 머나먼 땅으로 여행할 준비는 됐소?\n\n그럼, 이제부터 잘 들으시오.", rewards = nil},
[1131] = {title = "무쇠이빨 하이에나", objective = "썬더 블러프의 멜로르 스톤후프에게 무쇠이빨 하이에나의 갈비뼈를 가져가야 합니다.", description = "우리는 때로는 식량을 구하기 위해서나 명예와 대지모신의 가르침을 얻기 위해 사냥을 하오.\n\n하지만, 지금 그대 앞에 놓인 사냥 과제는 그런 것과는 차원이 다르오. 바로 대지모신의 저주를 받은 짐승을 처치하는 것이지.\n\n불모의 땅 남쪽 버섯구름 봉우리에는 무쇠이빨 하이에나라는 놈이 돌아다니고 있소. 이 야수는 주변의 다른 하이에나를 강압적으로 지배하면서 평화로이 지내는 동물들을 살육하고 공포를 퍼뜨리고 있지.\n\n무쇠이빨 하이에나를 찾아 처치해 버리도록 하시오.", progress = "그 사악한 무쇠이빨 하이에나는 처치했소?", completion = "이제 무쇠이빨 하이에나를 처치했으니 버섯구름 봉우리에서 끔찍한 악을 하나 제거했군.\n\n이번 사냥이 그대에게 교훈이 되었기를 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1132] = {title = "피오라 롱이어즈", objective = "테라모어에 있는 피오라 롱이어즈와 대화해야 합니다.", description = "오, 다시 한번 바다에 갈 수 있다면! 신선한 바닷바람을 느끼고 포근한 어머니의 품 같은 파도에 몸을 맡겨 본 게 대체 얼마나 됐는지!\n\n오, 나도 당신처럼 장차 바다를 보게 볼 수 있었으면 좋겠소이다!\n\n부푼 야망을 품은 이들에게 기회의 땅 칼림도어에 대해 얘기해 주는 게 내 일이라오! 바다에서 자신의 운을 시험해 보고 싶다면 여기에서 배를 타고 아름다운 항구 테라모어로 떠나시오. 거기서 내 동료인 피오라 롱이어즈라는 엘프를 만나 보시오.\n\n그녀가 당신이 칼림도어에서 모험을 시작할 수 있도록 해 줄 거요.", progress = nil, completion = "엘룬께 영광을! 메네실 항구에 있는 플린트 씨가 보낸 분인가요? 플린트씨는 보는 눈이 상당히 까다롭죠. 그분이 그대를 보냈다면 틀림없이 그대는 칼림도어를 여행할 만한 자격이 충분한 겁니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1133] = {title = "아스트라나르로의 여정", objective = "아스트라나르에 있는 신드렐 스위프트파이어와 대화하십시오.", description = "이제 막 메네실에 도착했다면 그대가 첫 번째 해야 할 일은 아스트라나르로 가는 것입니다. 그대처럼 의욕 넘치는 얼라이언스의 일원이라면 그곳에서 훌륭한 일을 해낼 수 있을 겁니다. 신드렐 스위프트파이어를 만나 도움을 주시기 바랍니다.\n\n누가 보냈는지는 그녀에게 말해봐야 소용없을 겁니다. 신드렐은 날 모르니까요...", progress = nil, completion = "얼라이언스를 돕기 위해 이곳에 왔다는 말입니까? 도움이라면 언제든지 환영합니다. 잿빛 골짜기 숲이 아직 아름답기는 하지만 예전처럼 평화롭지는 않으니까요.", rewards = nil},
[1134] = {title = "돌발톱 산맥의 사자날개", objective = "아스트라나르에 있는 신드렐 스위프트파이어에게 사자날개 와이번 독주머니 12개를 가져가야 합니다.", description = "아직 우리가 호드와 전면전을 벌이고 있진 않지만 일촉즉발의 상황입니다. 호드에서 우리를 상대로 작전을 펴는 걸 알아낼 때도 있지만 워낙 은밀히 진행하는 터라...\n\n얼마 전 테라모어의 비밀 첩보원에 의해서 그들의 기습 계획이 드러났습니다. 그 보고에 따르면 오크들이 남쪽 돌발톱 산맥에 있는 땅거미 호수 근처에서 사자날개의 독을 모으고 있다고 합니다. 그리고 오크 암살자들이 그 독을 이용해 얼라이언스를 급습할 거라고 합니다.\n\n이 정보가 사실이라면 반드시 이를 막아내야 합니다. 그들이 독을 얻지 못하도록 그 원천을 봉쇄해야 합니다.", progress = "사자날개 와이번 독주머니는 가져왔습니까? 오크들이 그 짐승의 독을 우리에게 사용하는 걸 막아야 합니다!", completion = "고맙습니다. 하지만 그 동물들이 적에게 이용 당한 것 뿐인데... 죄 없는 동물들을 처치하라고 명령해야 하는 건 가슴 아픈 일입니다. 얄궂게도 그게 바로 내 임무이니...\n\n그대 역시 가슴이 아프겠지만, 적어도 얼라이언스의 많은 이들이 사자날개 와이번의 독으로부터 안전해졌으니 그것으로 마음의 위안을 삼길 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1135] = {title = "마루둥지 와이번의 독", objective = "테라모어에 있는 피오라 롱이어즈에게 마루둥지 와이번 독주머니 10개를 가져가야 합니다.", description = "오크들이 주로 와이번을 탈것으로 길들인다는 것은 알고 계시겠지만, 어떤 계통의 와이번 독은 와이번 자체보다도 더 값지다는 것은 잘 모르실 거예요. 혹시 와이번 사냥을 한번 해보시겠다면... 드릴 만한 일거리가 있습니다.\n\n여기서 서쪽으로 가면 버섯구름 봉우리에 마루둥지라는 장소가 있어요. 마루둥지 와이번은 아주 강한 독을 지니고 있습니다. 아주 강하고 값진 독을...", progress = "마루둥지는 찾으셨나요? 그곳에서 와이번은 사냥하셨고요?", completion = "와, 아주 독이 넘쳐 흐르는 것들을 가져오셨군요. 이런 것들은 보통 어린 와이번이나 새끼를 잘 낳는 암컷들에게서만 찾을 수 있는데... 마루둥지에서 굉장히 큰 싸움을 벌이셨겠군요!", rewards = "다음과 같은 것들을 받습니다:\n\n산들바람 허리띠"},
[1136] = {title = "서리갈기 설인", objective = "썬더 블러프에 있는 멜로르 스톤후프에게 서리갈기 설인의 갈기를 가져가야 합니다.", description = "그대도 이제 머나먼 땅으로 여행을 할 때가 되었군.\n\n알터랙 산맥에 사는 서리갈기 설인을 사냥하도록 하시오. 놈의 털은 흰색이라 산맥에 쌓인 눈과 섞여 알아보기가 힘들 뿐만 아니라 항상 숨어 다니는 습성 때문에 찾기가 힘들다오. 좀처럼 모습을 드러내지 않기로 유명하지.\n\n하지만 내 그놈을 꾀어내는 방법을 가르쳐 주지. 이 두루마리를 받으시오. 거기다 서리갈기 설인을 꾀어낼 수 있는 방법을 적어 놨소.\n\n이제 가보시오. 멀고도 험난한 여정이 될 거야. 반드시 서리갈기 설인의 갈기를 가지고 돌아와야만 하오.", progress = "알터랙 산맥에는 다녀왔소? 그 찾기 힘들다는 서리갈기 설인은 잡았고?", completion = "서리갈기 설인을 찾아 쓰러뜨리는 데는 힘과 뛰어난 솜씨, 두 가지가 모두 필요했소. 그대는 모두 지닌 것 같군.\n\n이번 여행길은 버섯구름 봉우리의 계곡과 알터랙의 높은 산맥까지 이어졌었소. 그대는 언젠가 대지모신의 모든 땅을 밟아 보게 될 것이오. 그것이 칼림도어 &lt;class&gt;|1으로서의;로서의; 운명이니까...", rewards = "다음과 같은 것들을 받습니다:\n\n정령사냥꾼 머리장식"},
[1137] = {title = "피즐에게 전할 소식", objective = "소금 평원에 있는 피즐 브라스볼츠와 대화하십시오.", description = "인듀리움은 열에 아주 강하오! 틀림없이 피즐의 엔진 피스톤에 쓸 수 있을 거요. 하지만 이 조각들만으로는 부족하고 알짜배기 인듀리움 광석이 필요할 거요.\n\n그 광석은 황야의 땅의 북쪽 경계에 있는 울다만의 깊숙한 곳에서 캐내야만 하오. 그곳이 인듀리움의 진짜 원산지니까.\n\n피즐 브라스볼츠에게 내 안부를 좀 전해 주시오. 그리고 내가 당신에게 해준 말도 전해주고.\n\n부디 안전한 여행 되길 바라오. 그리고 아마 우리는 다시 만나게 될지도 모르오. 피즐이 인듀리움에 대해 알게 되면 분명 당신을 울다만으로 보내 그걸 가져오게 할 테니까!", progress = nil, completion = "돌아왔구려! 마르텍은 찾았소? 얘기는 해봤고? 그가 뭐라고 했소? 도와줄 수 있다고 합디까??\n\n어서, 어서 말해 주시오, 어서!!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n피즐의 지피 라이터노움 수리공의 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1138] = {title = "바다의 열매", objective = "맛좋은 게살 6개를 모아서 아우버다인에 있는 구버 블럼프에게 가져가야 합니다.", description = "저는 게가 좋아요. 게는 바다의 열매라고 할 수 있지요! 구워도 되고, 바베큐를 해도 되고, 끓여도 되고, 석쇠 구이를 해도 그만이죠. 팬에 살짝 볶아도 되고, 기름을 잔뜩 넣고 튀겨도 되고, 튀길 때 약간 휘저어 주면 맛이 더 기가 막히지요. 게 샐러드, 게 수프, 게 스튜, 후추 게 요리, 레몬 게 요리, 채찍뿌리 게 요리, 그리고 아이언포지 깜짝 게 요리도 있어요. 뭐, 그 정도랍니다.\n\n지금 낚시 중이라 자리를 비울 수 없지만, 당신이라면 모레톱게나 등껍질 왕바닷게에게서 맛좋은 게살을 구해올 수 있겠지요. 그걸로 다양한 요리를 만들 수 있답니다. 구워도 되고, 바베큐를 해도 되고, 끓여도 되고...", progress = "레몬 게 요리, 채찍뿌리 게 요리, 아이언포지 깜짝 게 요리... 뭐, 그 정도지요.\n\n아, 제가 부탁드린 맛좋은 게살은 가져오셨어요?", completion = "우와, 딱 제가 찾던 맛좋은 게살이로군요. 고맙습니다! 얼마 전 낚시를 하다가 이걸 발견했는데, 저한테는 쓸모가 없군요. 이거로는 맛난 게 요리를 만들 수가 없거든요. 당신이라면 쓸 데가 있을지도 모르겠네요.\n\n게에 대해서 전부 다 말씀드린 거 맞죠?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n나무껍질 장갑등딱지 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1139] = {title = "잃어버린 결의의 서판", objective = "결의의 서판을 찾아 아이언포지에 있는 조언자 벨그룸에게 가져가야 합니다.", description = "검은바위 첨탑에서 어둠괴철로단 드워프의 진로를 끊어 그들의 진군은 늦추었지만, 해머토의 꿈은 아직 이루어지지 못했소. 절대 그의 죽음을 헛되이 해서는 안 되오. 해머토는 늘 결의의 서판을 찾기를 꿈꾸었지. 전설에 의하면, 그것은 티탄들이 자신의 의지를 가진 생명체를 창조하는데 사용하려고 몸소 마법으로 돌에 새긴 서판이라고 하더군.\n\n아무튼 어둠괴철로단 드워프들이 발견하기 전에 우리가 먼저 그걸 되찾아와야 하오.\n\n울다만으로 돌아가서 그 서판을 찾는 즉시 다시 이곳으로 돌아오시오.", progress = "해머토의 꿈을 반드시 이루어내야만 하오. 나는 그에게 그만한 빚을 졌어.\n\n당신이 울다만으로 돌아가는 것은 그러한 목표의 완수뿐 아니라 전 드워프 종족의 안녕이 걸린 중요한 문제야. 그 서판이 검은무쇠단 드워프의 손아귀에 들어가 버린다면 그들의 골렘 군대는 그야말로 무적의 세력이 될 것이오.", completion = "&lt;서판을 건네 받고 믿을 수 없다는 듯이 고개를 흔드는 조언자 벨그룸&gt;\n\n정말 놀랍군. 가능한 한 빨리 이 서판을 폐하의 직속 마법사들에게 전달하도록 하겠소. 이 서판을 연구해 그 전설이 사실인지 알고 싶어할 테니... 그건 나중 얘기고... 당신은 내 기대 이상으로 우리 종족에게 크나큰 힘이 되어 주었어. 고맙소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n용맹의 메달"},
[1140] = {title = "알살락스의 탑", objective = "어둠의 터와 사티로스나르에 갇혀 있는 명가의 영혼들을 구출하고 마에스트라 주둔지에 있는 수호자 델그렌에게 돌아가십시오.", description = "오크 놈들의 글씨는 정말 아이들의 낙서보다 나을 게 없다니까... 내가 그들의 말을 배우기로 했을 때 많은 동료들이 비웃었지. 하지만 적에 대해서 많이 알면 알수록 유리하다는 사실을 알게 되었네.\n\n일크루드가 쓴 글을 읽어보니, 아직 애스리쿠스가 갖고 있는 영혼의 보석 두 개가 잿빛 골짜기 북동쪽의 사티로스 점령지인 어둠의 터와 사티로스나르에 있다는 사실을 확인했네.\n\n조심하게. 피로 물든 사티로스의 사원은 자네처럼 노련한 <class>|1라도;이라도; 흔들리게 할 수 있으니까.", progress = nil, completion = "사티로스들이 숲을 휘젓고 다니도록 너무 오래 방치했던 것 같군. 다음에 아우버다인에 가면 이 문제에 대해 엘리자와 상의해 봐야겠네.\n\n그건 그렇고, 영혼의 보석이 파괴됐으니 애스리쿠스의 힘도 크게 약화되겠지. 이번 기회를 놓치지 말고 놈과 그 일당을 섬멸해야겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1141] = {title = "블럼프가의 낚싯대", objective = "어둠의해안 농어 6마리를 잡아서 아우버다인에 있는 구버 블럼프에게 가져가야 합니다.", description = "저는 구버 블럼프라고 합니다. 낚시를 무척 좋아하죠. 저희 블럼프가는 타고난 낚시꾼의 명가랍니다.\n\n이 근처에서 꼭 잡고 싶은 물고기가 있어요. 어둠의해안 농어라고, 전에는 배를 타고나가서 낚고는 했는데, 저 괘씸한 멀록 녀석들이 들어온 후로는 한 번도 배가 나간 적이 없답니다. 농어도 녀석들이 다 먹어 치우고 있을 게 뻔해요.\n\n혹시 어둠의해안 농어 낚시를 도와 주실 생각 없으신가요? 그래 주신다면 진품 블럼프가의 낚싯대를 드리겠어요! 아주 훌륭한 물건이죠.", progress = "어둠의해안 농어만 있으면 아주 맛난 요리를 다양하게 만들 수 있지요. 먹기에도 좋긴 하지만 낚시로 잡는 게 더 재미있는 것 같아요.\n\n어둠의해안 농어는 좀 잡으셨나요?", completion = "썩 괜찮은 농어들이네요! 도와 주셔서 정말로 고맙습니다!\n\n당신 낚시 실력은 최소한 제 사촌 여동생, 그라운 블럼프 정도는 되는군요. 그라운은 여자이지만 수염도 나고 이상야릇한 냄새도 납니다만, 낚시에 대한 열정만큼은 최고죠. 아무튼 당신은 블럼프가의 낚싯대를 가질 만한 자격이 있는 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n블럼프가의 낚싯대"},
[1142] = {title = "꺼져가는 생명의 불씨", objective = "트레샬라의 펜던트를 찾아 다르나서스에 있는 트레샬라 팰로우브룩에게 돌려주어야 합니다.", description = "이렇...게 힘이 없어...서야 오래 살...아 있지 못할 것 같...소.\n\n팔핀델에게... 주의를 주...기 위해 론브로우...라는 용...용감한 드워프를 보냈...소.\n\n하지만 주..죽기 전에... 내... 아내... 트레샬라... 와 연결되어 있는... 펜던트를... 그 비...비열한 녀석이 빼앗...아 가 버렸소...\n\n제...제발... 펜던트를 찾아서 다르나서스에 있는... 트레샬라에게... 돌려... 주시오...\n\n...쓸쓸히... 죽어간 나의... 소...소식...도... 함께...", progress = "<race>께서 저희 집에는 무슨 일로 오셨나요?", completion = "안 돼!\n\n이건 너무 불공평해요! 아, 잔인하고 혹독한 세상이여! 이제 전 슬픔을 짊어지고 헤랄라스가 한 일을 기리면서 살아야만 하겠죠.\n\n그렇게나 위험한 곳에서 여기까지 오시다니 참 용감하시군요. 이제 혼자 있게 해 주시겠어요? 그를 마음에 묻어야 하겠네요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n애도의 망토창기병 장화\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1143] = {title = "알살락스의 탑", objective = "애스리쿠스 나라신을 처치한 다음, 그 증거로 그의 머리 장식을 알살락스의 탑 근처에 있는 발툴 섀도스트라이크에게 가져가야 합니다.", description = "흠... 그대의 말이 사실이라면 지금이 최적의 공격 시기요. 난 애스리쿠스가 분명 탑 꼭대기에 있을 것이라 믿지만 조심하시오. 그의 주위에는 강력한 소환사들이 많이 있을 텐데, 지금까지 그대가 상대해 온 적들보다 훨씬 강한 자들이니...", progress = "애스리쿠스 나라신은 강력한 소환사요. 델그렌님의 도움을 기다려야 할지도 모를 일이지만, 아무튼 이렇게 그대를 혼자 보내신 걸 보면 크게 신임하고 계신 게 분명하오.", completion = "이제 애스리쿠스를 처치했으니 이 지역에 있는 악의 세력이 모두 사라지기만을 간절히 바랄 뿐이오. 그자들은 다시 돌아올 테지만 그동안 우리도 그들에게 맞설 대비책과 방어력을 더욱 강화할 수 있을 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1144] = {title = "수입업자 윌릭스", objective = "수입업자 윌릭스를 호위해 가시덩굴 우리에서 나가야 합니다.", description = "아, 드디어 구세주가 왔군!\n\n내가 이곳에 얼마나 오래 갇혀 있었는지 모를 거요. 마지막으로 바깥 세상 구경한 게 언제인지 기억도 나질 않으니...\n\n보다시피, 나는 사업가요. 사람들은 돈벌레라고도 부르지. 메보크 미지릭스가 여기 이 돼지우리 같은 곳에서 나는 청엽수를 후한 값에 사들인다는 소문을 듣고 왔다오. 쉽게 들어왔다 빠져나갈 수 있을 줄 알았는데, 보다시피 잘못 생각했던 모양이오.\n\n어쨌든, 여기서 나갈 수 있도록 도와준다면 후하게 보상하리다.", progress = nil, completion = "도와줘서 고맙소, 친구! 약속한 대로 수고한 대가를 주겠소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n원숭이 반지뱀고리호랑이 고리\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1145] = {title = "곤충 떼의 위협", objective = "오그리마에 있는 벨그롬 록마울에게 코란의 봉인된 쪽지를 전해야 합니다.", description = "크로스로드로 오는 많은 여행자들이 내게 거인의 들판에서 찾은 알들을 주면서 하는 말이 그곳 짐승들은 정말 위험한 존재라고 하더군. 얼마나 강조하는지 처음에 우리가 생각했던 것보다 훨씬 위험한 곤충이라는 생각이 든다오.\n\n오그리마로 가서 벨그롬 록마울을 만날 급사가 필요한데... 쉬운 일은 아니지. 이 임무를 확실하게 처리해 줄 자가 필요하오.\n\n벨그롬은 오그리마 명예의 골짜기에 있는 용사의 전당 입구에 있는 것으로 알고 있소.", progress = "당신은 오그리마밖에서 오랫동안 모험을 즐긴 것 같아 보이는군... 부럽소.\n\n나도 스랄님의 명으로 이 도시에 있지만 않았더라도 아마 지금쯤 여기저기 모험을 하며 돌아다니고 있었을 것이오. 하지만 나는 호드의 지도자 스랄님의 판단을 믿소. 그분이 날 필요로 하시는 한 여기에 남아서 그분을 도울 것이오.", completion = "아, 코란이 보낸 쪽지로군. 오랫동안 충직하게 일해 주고 있는 친구지. 안 그래도 크로스로드에서의 임무를 어떻게 진행하고 있는 중인지 궁금하던 참이었는데 잘 됐군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1146] = {title = "곤충 떼의 위협", objective = "버섯구름 봉우리에 있는 목타르 크린에게 벨그롬의 봉인된 쪽지를 전해야 합니다.", description = "음... 그 곤충에 대해서 코란도 나와 같은 생각인 것 같군. 생각보다 훨씬 더 위험한 녀석들인 것 같소.\n\n며칠 전, 한 사냥꾼을 만났소. 버섯구름 봉우리에서 초주검이 되어 왔더군. 그는 소금 평원에서 드워프 발굴단을 몰아내기 위해 파견된 공격대원이었소. 그런데 공격 도중 발굴 현장의 동굴 안에서 곤충들이 쏟아져 나오는 바람에 부대가 거의 전멸하고 말았다오.\n\n목타르 크린이 지휘하던 그 부대는 소금 평원 변경으로 대피한 모양이니 그에게 이 쪽지를 좀 전해 주시오.", progress = "나와 우리 부대는 전쟁을 위해 이곳 소금 평원까지 흘러들어왔다. 자네는 무슨 일로 이곳까지 온 거지?", completion = "산을 울릴듯한 우레와 같은 소리에 놀랄 것 없네. 소금 평원으로 온 고블린과 노움들이 자칭 과학의 산물이라고 부르는 고약한 기계를 타고 경주를 벌이는 소리일 뿐이니까. 하지만, 이곳 버섯구름 봉우리에는 그보다 더 큰 위협이 도사리고 있어. 우리 부대원 절반 가량의 목숨을 앗아간 무서운 놈들!\n\n우리는 오그리마의 벨그롬님으로부터 철수 명령이 하달되기 전까지는 이곳에 계속 머무를 것이네. 철야로 경계를 서면서 이곳을 사수해야지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1147] = {title = "곤충 떼의 위협", objective = "탐색꾼 실리시드 5마리, 일꾼 실리시드 5마리, 병정 실리시드 5마리를 처치하고 버섯구름 봉우리에 있는 목타르 크린에게 돌아가야 합니다.", description = "흠. 벨그롬은 저 괴물들을 꽤 위협적인 존재로 생각하고 있는 것 같군. 놈들을 다시 땅속으로 되돌려 보내길 원하고 있다는 말인 것 같은데...\n\n탐험가 연맹 소속의 드워프들을 처치하는 것만으로는 성이 안차나 보군. 그렇다면 반쯤 남은 우리 부대를 또 다른 전투에 투입해야만 하는데... 이런 상황에서는 도저히 꿈도 꿀 수 없는 일이야. 발굴 현장은 이곳에서 남쪽에 있는데 아마 더 이상 드워프는 남아 있지 않을 것이오. 우릴 위해 대신 싸워 줄 수 있겠소?", progress = nil, completion = "하하하! 그 진액을 뒤집어 쓰고 있는 모습이 더 멋져 보이는군! 으, 악취가 진동을 하는군. 코도 녀석들을 자극할 수 있으니 가까이 가지 말도록.\n\n우리 동료들도 당신 몸에서 나는 그 냄새만으로도 당신이 우리 대신 저 곤충 괴물들을 처치했다는 사실을 믿어 의심치 않을 것이오. 대단하군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1148] = {title = "실리시드 등껍질", objective = "크로스로드에 있는 코란에게 실리시드의 심장 1개, 실리시드의 갈퀴발톱 5개, 온전한 실리시드의 등껍질 3개를 가져가야 합니다.", description = "껍질을 손에 들고 살펴 보다가 뒤집어 보니 그물처럼 얽혀 있는 키틴질 표면 때문에 껍질이 놀랄 만큼 단단하다는 사실을 발견합니다. 지금까지 이런 물건은 본 적이 없습니다. 다른 부분을 더 살펴 보면서 이 짐승이 고도로 진화된 종이라는 것을 깨닫게 됩니다.\n\n시체를 다시 내려다보니 문득 코란이 이 짐승에 대해 연구해 보고 싶어할 것 같다는 생각이 듭니다. 자세한 연구를 통해 이 동물의 정체와 출처를 알아낼 수도 있을 것 같습니다.", progress = "아, 오랜만이군. 오늘은 무슨 일이오? 방금 치열한 전투를 치르고 온 것 같아 보이는데... 호드를 위해서나 자네를 위해서나 좋은 일이지... 전투를 많이 치를수록 더 큰 명성과 힘을 얻게 될 테니까 말이오.", completion = "아, 근래에 목타르를 만났었단 말이오? 그자는 무슨 일만 생기면 항상 나를 찾더군. 큰 전투가 아니라 항상 자신의 작은 부대를 돌보는 데 시간을 허비하고 있다는 게 유감스럽긴 하오. 하지만 지금쯤 아마 탐험가 연맹 놈들을 처치하고 있을 테니 그나마 다행이지.\n\n이 견본들을 내게 가져온건 정말 잘한 일이오. 거인의 들판에서 발견한 알과 함께 이 견본을 조사해 보면 이 곤충의 정체를 밝혀내는데 많은 도움이 될 것 같소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1149] = {title = "믿음의 시험", objective = "믿음이 있다면 버섯구름 봉우리가 내려다보이는 높은 곳에서 판자 아래로 뛰어내리십시오.", description = "나를 일부러 찾아온건가, 아니면 그저 운명에 이끌려 나한테까지 오게 된 건가? 뭐, 상관없네. 그대가 지금 여기 있고 이제 새로운 여정이 시작되려 한다는 사실이 중요한 거니까...\n\n육체와 정신, 그리고 영혼이라는 여러 요소가 합쳐져 하나의 존재를 이루지. 이중 일부는 한 문화의 전통에 의해 가늠될 수 있네. 하지만 일부는 그저 우리 안에 존재하길 바라는 수밖에... 만약 내 말이 맞다고 생각한다면 그대의 내면을 시험해 보게.\n\n이 시험에 통과한다면 더욱 강해질 것이고 실패한다면 지옥이 얼마나 광대한지를 깨닫게 될 것이네. 첫 번째는 믿음의 시험일세.", progress = "믿음은 흔히들 생각하는 것 이상으로 굉장히 중요하다네.\n\n때로는 그대가 무엇을 믿는가는 중요하지 않아. 그보다는 무언가 믿는다는 사실 자체가 중요하지.", completion = "갑작스러운 역경에 부딪혔을 때 자신의 영혼이 얼마나 강한지 알 수가 있다네. 무사하리라는 보장이 없음에도 불구하고 그대는 믿음의 도약을 했네. 이제 자네의 마음은 열렸고 그대의 영혼은 앞으로 부딪치게 될 많은 일들을 겪을 준비가 된 것이네.\n\n원한다면 바로 다음 시험을 시작할 수 있네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1150] = {title = "인내의 시험", objective = "버섯구름 봉우리에 있는 도른 플레인스토커에게 그렌카의 발톱을 가져가야 합니다.", description = "시험을 통해 그대의 변치 않는 용기를 확인하니 내 마음이 기쁘군. 그대의 확고한 믿음은 확인했으니 이제 육체의 힘을 시험할 때가 됐네.\n\n첫 번째는 인내의 시험이지. 친구들과 함께 높새바람 봉우리 서쪽 하피 동굴 깊은 곳까지 들어가서 보급품을 파괴하게. 그러면 놈들의 화를 돋우게 될 테고 살아남는다면 끝으로 그렌카 블러드스크리치가 직접 자네를 상대하러 나타날 걸세. 그녀를 처치하고 그 발톱을 가져오면 이번 시험은 끝나지.", progress = "앞으로 남아 있는 시험을 통과하려면 영혼과 신체, 그리고 마음의 무장을 단단히 해야 하네.\n\n우리는 때때로 아무 준비도 없이 무모하게 달려드는 경우가 있지. 호드의 모든 종족을 막론하고 젊은이들이 고향을 떠나 부딪치게 될 역경을 잘 극복할 수 있도록 지도하는 게 내 사명일세.", completion = "&lt;race&gt;에게도 그렌카는 상대하기 힘든 강한 존재였지. 그러니 오늘 그대가 이뤄 낸 바를 자랑스럽게 여기게나.\n\n믿음의 시험을 통해 그대는 영혼의 힘을 보여 주었어. 그리고 이제 약탈자 하피와의 전투에서 인내력도 보여 주었네. 하지만 아직 또 다른 시험이 자네를 기다리고 있네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1151] = {title = "용기의 시험", objective = "버섯구름 봉우리에 있는 도른 플레인스토커에게 로크알림의 파편을 가져가야 합니다.", description = "옛날 고대 신들의 시대엔 이 땅에 많은 정령들이 살고 있었지. 그들은 고대 신들을 섬겼고, 신들은 정령들을 이 세상에 속박해 두었네. 그런데 고대 신들이 이 땅을 뜨자 정령들은 세상에서 사라졌고, 이제는 강력한 마법사만이 다시 그들을 소환해 불러낼 수 있게 되었지.\n\n하지만 어디에나 예외는 존재하는 법... 일부 정령들은 강한 힘을 갖고 있어서 이 땅에 스스로 남아 있을 수 있었지. 로크알림도 그 중 하나야. 자, 그대의 힘을 시험하려면 버섯구름 봉우리에서 로크알림을 찾아 처치하게.", progress = "버섯구름 봉우리의 켄타우로스 부족은 로크알림을 돌주먹이라고도 부른다네. 그의 앞을 막아서는 무모하고 어리석은 놈들을 내리칠 때 그의 주먹에서 나는 우레 같은 소리 때문이지.", completion = "이제 용기의 시험이 끝났네. 이 시험을 통해 그대는 힘과 용기를 증명해 보였군그래. 이제 마지막 시험을 통과하면 이 의식이 완료된다네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1152] = {title = "지혜의 시험", objective = "돌발톱 산맥에 있는 돌발톱 토굴길 입구 근처에서 브라우그 딤스피릿을 찾아야 합니다.", description = "이제 나와 함께할 시간도 거의 끝나 가는군. 다른 이에게 다음으로 그대가 수행할 지혜의 시험을 맡기겠네. 이 세상에는 배울 일도 많고 가봐야 할 곳도 많지.\n\n놀라운 지혜를 가진 주술사 브라우그 딤스피릿을 찾아 가도록 하게. 그가 지혜의 시험에 대해 알려줄 테니 그의 말에 귀를 기울이도록...\n\n준비가 되는 대로 돌발톱 산맥과 잿빛 골짜기를 잇는 토굴길을 찾아 가게. 브라우그는 그곳에 살고 있지. 나이트 엘프들이 자네의 시험을 방해하려 할 것이니 조심하게.", progress = nil, completion = "고블린이 이 땅을 침범하고 나이트 엘프가 신흥 종족들을 견제하고 있는 지금 세상의 밤과 낮은 점점 더 싸늘해지고 있네. 그러니 칼림도어와 로데론이 겪고 있는 이 고난에 대해 포세이큰과 오크만 탓할 수는 없지. 지성이 있는 많은 종족들까지 이 고난에 일조하고 있는 상황이네. 도른 역시 이 사실을 알고 있었고 그대가 이러한 사실을 이해할 만한 품성을 보여 주었기에 이곳으로 보낸 것이지.\n\n그래서 그대가 지금 이 브라우그 앞에 서 있게 된 거라네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1153] = {title = "새로운 광석 견본", objective = "자갈주둥이일족 채굴꾼이나 흙점쟁이가 가지고 있는 정제하지 않은 광석 견본을 찾아 불모의 땅, 타우라조 야영지에 있는 테터낵 스틸포지에게 가져가야 합니다.", description = "<class> 친구, 지금까지 나에게 큰 도움이 되어 주었소. 대족장님께서 내가 한 일들에 대해 매우 기뻐하시면서 앞으로도 새로운 결의로 임무를 완수해 내기를 바라시고 있소. 나를 도와준 당신이 합당한 보상을 받을 수 있도록 대족장님께 말씀을 드리려 하는데, 그 전에 부탁이 하나 더 있소.\n\n최근 남쪽에 있는 버섯구름 봉우리라는 곳에서 여행자들이 왔소. 그곳에서 코볼트를 하나 해치우고 아주 희귀한 광석 견본을 손에 넣었다는데, 절대 팔 수는 없다더군. 그 광석 견본을 조사해보고 싶으니 좀 구해다주시오.", progress = "광석 견본을 손에 움켜쥐고 팔지 않는 여행자들을 또 보았지... 대족장님을 돕지 않는 자들에겐 경멸뿐이외다.\n\n그런 자들에게 용감한 호드의 전사다운 명예로운 죽음은 어울리지 않지... 저 겁쟁이 얼라이언스처럼 비굴한 죽음과 마주하면 좋겠소.", completion = "좋은 견본이야. 정말 아주 괜찮은 견본을 가져왔소.\n\n당신이 이 임무를 성공적으로 완수했으니 이제 더 이상 여행자들에게 광석을 팔라고 들볶을 필요는 없군.\n\n즉시 연구를 시작해야겠어. 이 광석이 충분히 강한 것으로 확인되면 이것으로 만든 무기를 대족장님께 바쳐서 우리의 성공을 직접 보여드리겠소.\n\n당신의 도움을 절대 잊지 않겠소, &lt;class&gt; 친구.", rewards = "다음과 같은 것들을 받습니다:\n\n오크족 전투검"},
[1154] = {title = "지혜의 시험", objective = "고대의 유산을 찾아 돌발톱 산맥에 있는 돌발톱 토굴길 입구 근처에서 브라우그 딤스피릿에게 가져가야 합니다.", description = "도른의 시험을 잘 통과했으니 이제 다음 시험을 치를 때가 되었네. 지금까지의 시험은 아이들 장난에 불과하지. 육체의 힘을 시험하는 건 어렵지 않지만 마음을 시험하는 건 차원이 완전히 다른 문제지.\n\n쉽게 설명해주지. 내가 말하는 책을 찾아서 탐독하고 그 내용에 대한 내 질문에 답하도록 하게.\n\n무슨 책인지 궁금하겠지? 고대의 유산이라는 책일세. 잿빛 골짜기 남쪽에 있는 도르다닐의 아래쪽으로 가면 찾을 수 있을 걸세. 그곳은 죽은 드루이들과 그들의 노예가 지키고 있으니 조심해야 하네.", progress = "책을 찾아서 읽은 다음 내게 가져오도록 하게. 그 전까지는 질문하지 않을 걸세.", completion = "그래, 이게 바로 내가 말한 책이야. 내용을 숙지했겠지? 내 질문에 제대로 대답할 수 있길 바라네.\n\n준비가 되면 질문을 하도록 하겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1159] = {title = "지혜의 시험", objective = "언더시티에서 파쿠알 핀탈라스를 찾아야 합니다.", description = "잘했네. 지혜의 시험의 첫 단계를 잘 통과했군. 아직 답해야 할 질문이 남아 있지만 그 질문은 내가 하지 않겠네.\n\n로데론의 폐허에 있는 파쿠알 핀탈라스를 찾아가도록 하게. 그는 역병이 휩쓸고 지나가기 전에는 인간들의 위대한 역사가였지. 지금도 타인들을 교화하기 위해 힘쓰고 있지만 예전에 하던 일과는 성격이 다르지.\n\n아마 그가 문제를 내기 전에 그대에게 무언가를 요구할 걸세. 하지만 지금까지 잘해 왔으니 그의 시험도 무사히 통과하리라 믿네.", progress = nil, completion = "브라우그가 보냈다고? 그럴 리가...\n\n&lt;아래 위로 훑어보며&gt;\n\n용맹한 도르다닐에게 맞서고 믿음의 시험을 통과하고 또 강력한 정령을 물리쳤단 말인가? 흠... 분명 지금 연극을 하고 있는 거지? 아니면 선술집에서 엿들은 남의 이야기를 하고 있나? 그래, 내 시험을 통과할 만큼 대단한 실력을 가졌다고 생각하나? 그럼 한번 시작해 볼까, &lt;class&gt; 친구?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1160] = {title = "지혜의 시험", objective = "언데드 위협의 기원을 찾아 언더시티에 있는 파쿠알 핀탈라스에게 가져가야 합니다.", description = "그럼 자네가 찾아야 할 것을 말해 주지. 질문은 그것을 찾아온 후에 할 거야. 힘보다 지식이 훨씬 중요하지. 세상엔 자네보다 더 뛰어난 능력을 갖춘 이들도 많이 있겠지. 하지만 이 세상에 대한 지식을 쌓아 간다면 그게 훨씬 더 가치 있는 일이야.\n\n티리스팔 숲 북쪽에 있는 수도원으로 가게. 그곳 도서관에는 '언데드 위협의 기원'라는 책이 있지. 그 책은 지금은 타락해 버린 성기사들이 우리 종족과 싸우기 위한 훈련에 사용하던 교본일세.\n\n그걸 내게 가져오도록 하게.", progress = "책을 훔쳐내기 전에 붉은십자군을 좀 처치해 주길 바라네.\n\n한때 붉은십자군은 정의의 이름을 외쳤을지 모르지만 지금은 그들의 신앙을 따르지 않는 이들은 전부 해치고 있어. 놈들은 포세이큰을 비롯한 모든 언데드를 정화해야만 할 대상으로 여기고 있네. 게다가 자신들의 땅으로 들어오는 자는 모두 제정신이 아니거나 언데드의 강력한 마법에 의해 조종당하고 있다고 생각하지. 바보들, 전부 정말 바보 멍청이들이야.", completion = "그래, 이게 바로 내가 찾아오라고 한 책이야.\n\n&lt;책을 내려다보면서 손으로 책의 윗부분을 천천히 어루만지며&gt;\n\n자, 이제 자네의 신체와 영혼만큼 자네의 정신도 강하다는 걸 증명해 보이고 싶겠지. 책을 충분히 읽었을 것으로 알고 질문을 시작하지. 그럼 이 모든 시험들이 끝나게 되는 것이네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1164] = {title = "지나비의 복수", objective = "케나타, 파델, 그리고 마셸 다비리를 처치하고 그 증거로 그들의 머리카락을 언더시티에 있는 지나비 칼로에게 가져가야 합니다.", description = "케나타! 그 돼지 같은 계집이 아직도 살아 있다니! 고통 속에 보낸 그 세월 동안 그 계집의 가족은 잘 먹고 잘살고 있다고요!\n\n전 역병으로 가족을 잃고 전쟁 중에 재산도 도둑맞거나 불타 버렸죠. 그 후 케나타 계집과 그 악랄한 자식들은 뻔뻔스럽게도 제게 남은 유일한 귀중품마저 훔쳐 갔어요.\n\n훔쳐간 물건에는 더는 관심이 없으니 그들을 처치해 주세요! 아라시 고원에 있는 임시 주둔지 북동쪽의 다비리 농장으로 가면 돼요.", progress = "그들을 모두 처치하고 증거를 가져다주세요!", completion = "대신 복수를 해주시다니 머리 숙여 감사합니다.\n\n그들이 죽었으니 아제로스에서 그 계집의 자손들을 볼 일이 더는 없겠군요. 덕분에 이제 저는 돈벌이에 집중할 수 있겠어요. 그런데 그들을 모두 처치한 후 농장을 약탈하는 건 잊지 않았겠죠?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n냉혹의 어깨갑옷호화로운 소매장식\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1166] = {title = "대군주 모크모로크의 근심", objective = "담쟁이 마을의 대군주 모크모로크가 먼지진흙 습지대에서 자신의 그로그주, 코담배통, 그리고 금고를 찾아 와 달라고 부탁했습니다.", description = "나, 대군주 모크모로크 앞에 머리 숙여라!\n\n렉사르님이 나를 돌망치일족의 강력한 지도자로 임명하셨다!\n\n나는 실력 있는 지도자. 내 부족을 안전하게 해준다.\n\n큰 용들이 와서 옛 고향을 다 태워 버렸다. 하지만 나는 똑똑한 오우거. 우리 부족의 새 집을 여기에 마련한다.\n\n너무 급히 옛 집을 떠나 오는 바람에 두고 온 것들이 있다. 가서 내 물건들을 가져와라, 꼬마 <race>. 남쪽으로 가서 내 맛있는 그로그주와 코담배통, 그리고 금고를 찾아 오면 너 기특하게 여겨 준다. 화염의 둥지와 돌망치일족 폐허를 찾아봐라, 날 믿어!", progress = "나 그로그주 마시고 싶다. 내 코담배도 그립고. 내 금고는 어디 있는 거야? 나, 대군주 모크모로크에게 그것들을 가져와라.\n\n남쪽으로 우리 일족의 옛 고향을 찾아 가라. 난 오우거들을 다스리느라 너무 바빠서 직접 가지 못한다.", completion = "참 착한 &lt;race&gt;|1이로군;로군;. 이것들이 아주 많이 그리웠어. 나 이제 너 마음에 든다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n거대한 오우거 장화"},
[1167] = {title = "알살락스의 탑", objective = "알살락스의 탑 근처에 있는 발툴 섀도스트라이크와 대화하십시오.", description = "애스리쿠스에 맞서기 전에 발툴과 상의하는 게 좋을 걸세. 그는 분명 탑을 계속 감시하고 있었을 테니, 그곳으로 가면 분명 최근에 밝혀진 정보를 알 수 있을 걸세.", progress = nil, completion = "아, 다시 만나 반갑소! 이곳에서는 이상한 일들이 계속 일어나고 있었는데, 이런 때 그대가 이렇게 와 주어서 얼마나 기쁜지 모르겠소!\n\n일전에 정말 기묘한 일이 일어난 적이 있소. 갑자기 탑 위쪽에 있는 방에서 눈부신 빛이 났소. 그리고는 비명 소리가 들렸다오. 그리고 몇 번인가 고함 소리가 공기를 가르고 땅에 번개가 내리쳤소. 대체 무슨 일이 일어나고 있는 건지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1168] = {title = "검은용군단", objective = "담쟁이 마을의 타르그가 화염갈기혈족 정찰병 15마리, 화염갈기혈족 불꽃술사 10마리, 화염갈기혈족 맹독전사 5마리를 해치워 달라고 부탁했습니다.", description = "렉사르님이 모크모로크를 대군주로 임명하셨다. 그는 우리 오우거일족을 돌보는 것보다는 힘을 얻는 데 관심이 많지.\n\n검은용들이 오우거들을 많이 죽였다. 타르그의 아내도 죽였다. 모크모로크는 모두에게 도망치라고 해서 이곳으로 오게 했다.\n\n오우거는 싸워야 한다. 오우거는 도망치는 건 잘할 줄 모른다. 모크모로크는 자기 걱정만 한다.\n\n나는 돌망치일족 폐허를 고향이라 부른다. 난 남쪽이 좋다. 여기는 고향이 아니다.\n\n우리 오우거들이 검은용군단과 싸우는 걸 도와라. 난 복수하고 싶다. 고향으로 가고 싶다.", progress = nil, completion = "검은용군단을 많이 처치했군. 당신, 아주 용감한 &lt;race&gt;|1이다;다;.\n\n타르그를 기쁘게 한다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n타르그의 신발끈타르그의 원반\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1169] = {title = "근원 추적", objective = "담쟁이 마을에 있는 드라즈질브가 화염 혓바닥 15개와 화염 심장 15개를 가져다 달라고 부탁했습니다.", description = "그 겁 많은 바보 모크모로크는 권력의 맛에 흥청대고 있고 타르그는 슬픔과 복수의 악마들과 악전고투하며 부족의 지도권을 얻기를 바라는데, 우리 옛 고향을 침략한 무리의 어떤 녀석들인지 어디서 온건 지 알아내려고 하는 건 나 혼자뿐인 것 같다.\n\n어째서 어리둥절한 얼굴을 하고 있지? 내가 오우거라고 해서 거친 난봉꾼 같은 말투를 쓸 거라 생각했나?\n\n그럼 다시 원래의 본론으로 돌아가겠다. 갓 부화한 화염 새끼용과 화염 새끼용의 심장과 혓바닥을 내게 가져와라. 내가 이 악의 뿌리를 추적할 것이다...", progress = "검은용군단 새끼들의 심장과 혀가 있으면 어떤 괴물이 녀석들을 우리 고향으로 보냈는지 알 수 있다. 이 침략자들에 대해 더 잘 알게 되면 혹시 녀석들을 완전히 물리치고 돌망치일족 마을을 폐허에서 다시 일으켜 세울 수 있을지도 모른다.\n\n당연히 모크모로크가 그 쓰레기통 밖으로 무기력하고 뚱뚱한 몸뚱어리를 움직이도록 하는 것 자체가 대장정이 되겠지만...", completion = "이 심장과 혀들을 모으는 것은 분명 아주 위험한 일이었을 거다. 우리 옛 고향을 침략한 검은용군단의 근원을 찾기 위해 이 수수께끼를 깊이 탐구해 볼 것이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n그을린 단망토소도둑 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1170] = {title = "오닉시아 일당", objective = "담쟁이 마을에 있는 대군주 모크모로크와 대화해야 합니다.", description = "돌망치일족 마을이 오닉시아 일당에게 침략당했다. 하지만 왜 검은용군주 데스윙의 딸이 우리 땅에 내려온 거지?\n\n이건 정말 큰일이다. 분명 오닉시아가 겨우 오우거 몇 마리를 포위 공격하러 여기 온 건 아닐 거고 그 이상의 뭔가가 있다.\n\n즉시 모크모로크에게 알려야 한다! 반드시 조치를 취해야 해.", progress = nil, completion = "왜 내게 용에 대해 말하는 거지? 난 용 싫다. 난 여기 좋아. 여긴 용 없다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1171] = {title = "오닉시아 일당", objective = "담쟁이 마을에 있는 드라즈질브와 대화해야 합니다.", description = "이제 나 혼자 있게 해 줘. 드라즈질브한테 가서 우린 여기 있을 거라고 말해. 여기에 검은용은 없어.", progress = nil, completion = "이런 게으른 겁쟁이 같으니!\n\n모크모로크는 렉사르님께서 우리를 이끌 당시 자신의 힘을 보여 줬었다. 하지만 렉사르님께서 떠나신 직후 모크모로크는 권력의 유혹에 넘어가고 말았지. 그는 우리를 이끌기보다는 자신이 원하는 걸 요구하기만 했다. 스스로 백성들에게 봉사하기보다는 우리가 자신을 위해 봉사하길 기대하고 있다.\n\n뭔가 조치를 취해야 한다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1172] = {title = "오닉시아 일당", objective = "담쟁이 마을에 있는 드라즈질브가 오닉시아의 알 5개를 파괴해 달라고 부탁했습니다.", description = "오닉시아 일당은 용의 늪 전역에 흩어져 있다. 더 이상 새끼를 치도록 놔둬선 안 된다.\n\n서둘러 먼지진흙 습지대 남쪽에 있는 용의 둥지로 가라. 틀림없이 그곳에 오닉시아의 소굴이 있을 거다. 그 사악한 용의 알을 찾아서 부숴 버려라.\n\n돌망치일족 폐허는 그 주변이 용의 번식지로 남아 있는 한 되찾을 수 없을 것이다.\n\n모크모로크에 대해서는... 내가 다른 계획을 세워 놓겠다.", progress = nil, completion = "훌륭하군! 오닉시아가 다시 알을 낳기까지는 시간이 좀 걸릴 거다. 내 일족을 대신해 감사를 표한다.\n\n지금까지 우리를 많이 도와줬지만 돌망치일족을 위해 마지막으로 한 번만 더 도와줬으면 한다.\n\n모크모로크는 우리를 다스릴 만한 오우거가 못 된다. 타르그가 적임이겠지만 부상을 입은 데다 나이도 있어 무리다. 무력으로라도 모크모로크를 이곳에서 쫓아내라. 그렇게 해야만 남쪽에 있는 우리 일족의 옛 고향으로 데려다 줄 새 지도자를 뽑을 수 있으니까.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n엔카민 장화주아텍의 장화\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1173] = {title = "대군주 모크모로크에게 도전", objective = "모크모로크에게 이긴 후 담쟁이 마을에 있는 드라즈질브에게 이 소식을 보고해야 합니다.", description = "너 감히 이 대군주 모크모로크에게 도전하나?\n\n크하핫!\n\n이 조그만 <race> 녀석, 짓뭉개 준다!\n\n실컷 두들겨 맞고 싶으면 언제라도 와라.", progress = nil, completion = "덩치가 산만한 모크모로크 녀석이 겁먹은 어린애처럼 줄행랑을 쳤군. 수고 많았다.\n\n이제 우리 고향을 영원히 되찾아 줄 새로운 지도자를 뽑을 수 있게 됐어.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n극악의 비수얼음발톱 파편\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1174] = {title = "노움 승리!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n노움 상품"},
[1175] = {title = "경주 중의 충돌", objective = "소금 평원에 있는 경주로관리인 제린을 위해 소금바위 바실리스크 10 마리, 소금바위 수정바실리스크 10 마리 및 소금바위 큰눈바실리스크 6 마리를 처치해야 합니다.", description = "고블린의 경주용차 붉은 번개호와 바실리스크가 충돌하는 큰 사고가 일어난 후 크론크라이더가 경주로 관리를 위해 날 고용했네. 도대체 소금 평원의 모든 짐승들이 뭘 먹고 그렇게 거대해졌는지 모르지만, 어쨌든 우리는 놈들의 수를 최대한 줄여 경주가 진행되는 동안 경주로에 들어오는 일이 없도록 해야 하네.\n\n돈벌이를 찾고 있다면 이 지역에 있는 바실리스크를 좀 처치해 주시게나.", progress = nil, completion = "경주가 없을 때 경주로 안에 들어온 바실리스크는 다른 곳으로 이동하면 처치해주길 바라네. 그놈들의 시체가 썩으려면 시간도 오래 걸리고, 그걸 치우는 건 정말 귀찮은 일이니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1176] = {title = "하중 줄이기", objective = "소금 평원에 있는 포직을 위해 가벼운 독수리 뼈 10개를 구해야 합니다.", description = "경주에는 모든 요소가 다 중요하지! 출력을 세부적으로 조정하거나 인장 고리를 조금 느슨하게 하거나 차체 하중을 낮출 때에도 모든 점을 고려해야 한단 말이오.\n\n우리는 경주용차의 세밀한 구조를 변경하는데 독수리 뼈를 많이 사용하고 있지. 독수리 뼈는 강도와 중량의 균형을 완벽하게 맞춰주는 재료라오. 게다가 이곳엔 독수리들이 우글거리니 구하기도 쉽고 말이오.\n\n내게 독수리 뼈를 좀 구해다 주면 값을 후하게 쳐 주도록 하겠소.", progress = "뼈는 구해 왔소? 막 조종 장치의 하중을 줄이는 작업을 시작하려던 참이었는데, 필요한 부품을 구하기 전까지는 차체를 분해하고 싶지는 않다오.", completion = "좋아! 지금 바로 일을 시작해야겠어. 고맙소이다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1177] = {title = "배고픈 오우거", objective = "먼지진흙 습지대 북쪽에 있는 머드크러쉬 더트피트가 진흙아가미 멀록의 머리 12개를 가져다 달라고 부탁했습니다.", description = "머드는 덩치 큰 오우거.\n\n머드 배고프다.\n\n물고기 잡아 줘. 머드 먹을 거 갖다줘.\n\n머드 먹을 거 안 주면 머드가 너 잡아먹을 거야.", progress = "내게 먹을 것 줘, 아님 너 먹을 거야.", completion = "난 물고기 머리를 좋아해!\n\n지금은 너 잡아먹지 않아.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n진흙바위 장갑진흙바위 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1178] = {title = "고블린 후원", objective = "톱니항에 있는 가즈로와 대화하십시오.", description = "우리 경주팀은 어딜 가나 고블린의 자랑거리지. 다양한 방법으로 우리팀을 후원하는 사람들의 얘기를 들으면 아마 깜짝 놀랄 것이오.\n\n가즈로를 아시오? 그자는 우리를 위해 곳곳에서 부품을 구해다 주고 있소. 한번은 직접 와서 장치를 손봐 준 적도 있을 정도지.\n\n몇 주 전에 그가 새로운 연료 조절 장치의 원형을 보낸다고 했는데 물건이 아직 도착하지 않고 있소. 절대 늦는 법이 없었는데... 당신이 톱니항으로 가서 그에게 좀 물어봐 주겠소? 뭐, 강요하는 건 아니지만 노움에게는 절대로 지기 싫단 말이오.", progress = nil, completion = "포직이 보냈다고? 포직은 경주용차를 만드는 일을 시작하기 전에도 지하광산에서 가장 뛰어난 수리공이었어. 그는 팀에 들어가자마자 두 가지 모형의 엔진을 탑재한 경주용차들을 만들었지. 땜장이 조합에서는 그 같은 인재를 놓쳐서 애석하겠지만... 어쩌겠나? 경주만큼 신나는 일도 없으니까 말이야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1179] = {title = "브라스볼츠 형제", objective = "소금 평원에 있는 위즐 브라스볼츠에게 충격방지 헬멧 상자를 가져가야 합니다.", description = "소금 평원에 대해 들어 본 적 있소? 칼림도어의 버섯구름 봉우리 협곡 남쪽에 넓게 펼쳐져 있는 염분이 침전된 평지지. 평탄한 지대라 경주를 하기에는 그만이라오.\n\n그곳에서 내 친구 노움 형제가 새로운 로켓 자동차를 만들고 있소. 내가 들은 바로는 정말 빠르다고 하오. 너무 빨라서 계속 충돌 사고를 일으켜 조종사들이 부상을 입을 정도라지.\n\n그래서 내게 보호용 헬멧을 부탁했는데, 난 해야 할 일이 있어서 이곳을 떠날 수 없소.\n\n당신이 나 대신 좀 가 주겠소?", progress = "조심해! 뭘 밟는 거요! 조심, 조심하라고! 이곳에 있는 것들은 섬세한 부품들이오. 우리가 승리하려면 하나라도 고장나서는 안 된다고!", completion = "아! 롱비어드가 보낸 헬멧을 가지고 온 친구였군! 만세! 이제 조종사에게 마음 놓고 우리 차를 몰아달라고 부탁할 수 있겠어. 머리를 다칠 일은 없을 테니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1180] = {title = "고블린 후원", objective = "무법항에 있는 부두주임 로즈길과 대화하십시오.", description = "자, 이제 자네가 여기 온 용건에 대해 얘기해보자고. 그래, 내가 포직에게 새로운 연료 조절 장치를 보내 주겠다고 약속한 건 맞아. 그런데 나도 아직 물건을 받아보지 못했다네. 무법항에 있는 레빌가즈가 그걸 배에 실어 보냈다는데 아마 어딘가에 빠져버린 모양이야.\n\n그게 사실이라면 어쩔 수 없지. 우선 물건이 무법항에서 발송된 게 맞는지 확인해 봐야 할 것 같아.\n\n그곳 부두주임 로즈길을 만나 보라고. 그가 뱃짐 기록을 확인해 줄 거야.", progress = nil, completion = "톱니항으로 가는 화물 말입니까? 어디... 일지를 한번 확인해 봅시다.\n\n없군요. 기록에 따르면 최근에 톱니항으로 발송된 화물은 드리즐릭이 보내는 장화였습니다. 특별히 다른 건 없는데... 건축 자재하고 연장들이 전부입니다. 당신이 찾는 경주용 부품은 없습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1181] = {title = "고블린 후원", objective = "무법항에 있는 남작 레빌가즈와 대화하십시오.", description = "도움이 되지 못해 죄송합니다. 좀 더 조사해 보려면 남작께 한번 여쭤 보십시오. 레빌가즈님께서 하시는 일은 본인이 가장 잘 아실테니까 말입니다.\n\n지금쯤 부두 건너편 선술집의 맨 꼭대기 층에 계실 겁니다.", progress = nil, completion = "오, 그 물건에 대해서는 물론 잘 알고 있지. 하지만 나도 큰 도움은 못될 것 같군... 애석하게도 내 부하들이 연료 조절 장치의 설계도를 찾아 오기로 했었는데 실패하고 빈 손으로 돌아왔단 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1182] = {title = "고블린 후원", objective = "무법항에 있는 남작 레빌가즈에게 연료조절장치 설계도를 가져가야 합니다.", description = "가시덤불 골짜기 북쪽 나즈페리티 호수에 있는 투자개발회사의 벌목기에 새로운 모델의 연료조절장치가 장착되어 있네. 포직이 가서 자세한 정보를 캐낼 줄 알았는데, 그곳 감독관 코즐이란 자가 생각보다 영리하단 말이야.\n\n보아하니 당신도 그 설계도를 꼭 찾고 싶어하는 것 같은데... 그 감독관이 집안 어딘가에 설계도를 보관하고 있다는 건 확실하네. 하지만, 아마 자물쇠로 단단히 채워져 있을 거야.", progress = "인정하긴 싫지만 노움의 실력이 상당하단 말이지. 우리 고블린은 모든 노력을 기울여서 그들을 능가해야만 해.", completion = "오, 설계도를 구해왔군. 복사해서 나도 하나 갖고 있어야겠어. 이제 이 설계도를 포직에게 가져가도록. 후원자 중 한 사람이 완전히 지원을 끊었다고 생각하면 곤란하니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1183] = {title = "고블린 후원", objective = "소금 평원에 있는 포직에게 연료조절장치 설계도를 전해야 합니다.", description = "자, 준비가 다 됐으니 어서 떠날 채비를 하게. 포직에게 날 대신해 안부를 전하고 필요한 게 있으면 망설이지 말고 얘기하라고 전해 주라고. 머지않아 그가 경주 기록을 갱신했다는 소식을 들을 수 있기를 기대하지.", progress = "연료 조절 장치의 행방은 찾았소?", completion = "고맙소. 아쉽군! 이미 조립되어 있기를 바랬는데... 하지만 처음부터 하나하나 조립하면서 조금씩 개선해 나가는 재미 얻을 수도 있겠군. 몇 가지를 고친 다음 곧 장착해서 완성하도록 하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1184] = {title = "실리시드 등껍질", objective = "오그리마에 있는 벨그롬 록마울에게 돌아가십시오.", description = "오그리마에 있는 벨그롬님에게 돌아가서 목타르가 버섯구름 봉우리에서 명령을 잘 수행하고 있더라고 전해 주시오. 그리고 내 연구에도 진척이 있어 곧 더 많은 것을 알게 될 거라고도 전해 주시오. 벨그롬님이 크게 기뻐하실 거요.", progress = nil, completion = "수고해 줘서 고맙소, &lt;class&gt; 친구. 이토록 성실하게 임무를 완수하는 자가 있다는 것을 아시면 대족장님께서 크게 기뻐하실 거요.\n\n아, 물론 당신 이름을 대족장님께 말씀드리리다. 나와 자주 얘기를 나누시고 내 의견을 꽤 존중해 주시는 분이시지.\n\n자, 나는 할 일도 잔뜩 있고 하니 이제 가 보시오. 코란을 만나서 그가 이 생물들에 대한 소식을 전해 주거든 내게 다시 돌아와 주시오. 신중히 대처해야 할 위협적인 생물들인 것 같으니...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n마른잎사귀 바지피투성이 초승달 도끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1185] = {title = "껍질 속에 담긴 비밀", objective = "안녕하시오! 다시 보게 되는군! 그래, 당신 이름이 아마 <name>|1이였지;였지;?\n\n자, 인사는 그만 하고 이제 본론으로 들어가겠소.\n\n당신이 실리더스에서 찾은 물건은 사실... 이제는 우리가 다르나서스 언어라고 부르는 고대 언어로 기록된 책이었소. 시간이 얼마나 오래 걸릴지는 나도 모르겠지만 아주 철저히 연구해 볼 작정이라오. 당신이 발견한 이 책이 우리 세나리온 의회에 얼마나 귀중한 것인지 알고 있으리라 믿소.\n\n여기에는 우두머리 엉겅퀴곰까지 놀라게 할만한 사실이 담겨 있으니 말이오.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1186] = {title = "18번째 조종사", objective = "소금 평원에 있는 래저릭과 대화하십시오.", description = "이제 좀 바빠지겠군. 이 새로운 연료 조절 장치를 우리 경주용차의 설계에 적용하려면... 만약 우리 팀을 도와줄 의향이 있다면 저기 래저릭과 얘기해 보라고. 그는 우리 팀에서 정확하게18번째 조종사라오. 아무튼 그가 경주용차를 조금 개조하고 싶어하지.\n\n그자는 정신이 약간 이상하니까 너무 놀래키지는 말라고.", progress = nil, completion = "당신은 포직을 돕고 있는 &lt;race&gt; 아닌가요? 나도 한때는 당신처럼 험한 곳을 다니며 기계공들이 시키는 일이라면 뭐든지 했었지요.\n\n하지만 지금의 나를 보라고요! 이제는 명실공히 고블린 경주 팀의 최우수 조종사라고요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1187] = {title = "래저릭의 호기", objective = "소금 평원에 있는 래저릭에게 시포리움 부스터를 찾아다 줘야 합니다.", description = "포직은 훌륭한 기술자죠. 저도 그건 인정하지만 원체 겁이 많아서 저 엄청난 출력을 자랑하는 차에 한번 타보지도 못하고 있다니까요. 하지만 난 달라요.\n\n보통 포직이 완성한 경주용차를 제가 약간 손보곤 해요. 제어 장치를 좀 느슨하게 풀고, 차체의 군더더기를 제거해서 속력을 빠르게 만들지요!\n\n가젯잔의 기즈모리움에 있는 쉬리브에게 시포리움 부스터를 주문해 두었어요. 그런데 그걸 싣고 오던 비행선이 먼지진흙 습지대에서 추락한 것 같아요. 그게 꼭 필요해요.", progress = "속력을 높여 주는 추가 장치도 없이 어떻게 경주에 얼굴을 내밀 수 있겠어요? 말도 안 되는 소리지.", completion = "좀 보세요! 중량 7Kg의 견고한 시포리움 장치가 내는 힘이 얼마나 대단한지... 이걸 내 경주용차에 장착하기만 하면 노움들 코를 납작하게 할 만큼 엄청난 속도로 경주로를 돌 수 있을 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1188] = {title = "안전 제일", objective = "가젯잔에 있는 쉬리브에게 시포리움 부스터를 가져가야 합니다.", description = "잠깐, 이게 뭐지? 쉬리브가 안전 장치를 켜 놓았군. 이러면 부스터에서 얻을 수 있는 힘이 줄어들잖아. 분명히 꺼 달라고 말했는데! 흠... 이 상태로는 안 되겠군요.\n\n이걸 타나리스 사막에 있는 가젯잔 기즈모리움으로 가져가서 쉬리브에게 안전 장치를 제거해 달라고 해 주세요.", progress = "이 기즈모리움에서는 뭐든지 수리할 수 있다는 사실은 세 살배기도 알고 있습죠. 뭘 도와 드릴까요?", completion = "어리석은 래저릭... 이걸 들여다보고 안전 장치라고 하다니요. 이 부스터는 시포리움이 가히 폭발적인 힘을 낼 수 있게 해주죠. 이미 고쳐 놓은 상태니까 일단 장착만 하면 출력을 늘어나겠지만, 11에 도달 할 때까지 래저릭은 절대 만족하지 못할 겁니다요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1189] = {title = "안전 제일", objective = "소금 평원에 있는 래저릭에게 개조된 시포리움 부스터를 다시 가져가야 합니다.", description = "자, 래저릭이 부탁한 그대로 고쳤습니다. 시동을 걸 때 조심하라고만 전해 주세요. 작은 실수라도 하면 앞으로 나가기는커녕 경주로 위에서 잿더미가 돼 버릴 테니...\n\n그렇게 돼 버린다면 정말로 부끄러운 일일 거예요. 그나마 그 다음 19번째 조종사가 잘해내서 따라잡을 수 있다면 다행이지만... 그건 아무도 장담할 수 없잖아요?", progress = "이럴 수가... 포직이 경주용 차에 모래를 한 양동이 씩이나 달아 놓은 거 있죠. 그렇게 운전석 밑에 무거운 모래가 실려 있으면 어떻게 최고 속력을 낼 수가 있겠어요?", completion = "그래, 이 정도는 돼야지! 내가 이 경주용 차를 몰 때 노움 녀석들의 놀란 표정이나 한번 봤으면 좋겠는데...\n\n하지만 난 경주 기록을 깨느라 정신 없을 것 같아서 말이에요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n래저릭의 특수안전벨트래저릭의 경주용 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1190] = {title = "속도 유지", objective = "소금 평원에 있는 포직을 위해 자멕이 리즐의 주의를 다른 곳으로 돌리는 동안 그의 설계도를 훔쳐야 합니다.", description = "브라스볼츠 형제의 차가 훨씬 빨라졌는데 설계나 주행에 관한 모든 자료들은 이전과 동일하단 말이지. 뭔가 새로운 자재를 발견한 게 분명해. 그것밖에는 이 상황을 설명할 길이 없군. \n\n우리가 아는 건, 리즐 브라스볼츠가 지속적으로 새로운 뭔가를 발견하기 위한 계획에 힘써 왔다는 사실이야.\n\n자멕이 놈들의 주의를 다른 곳으로 돌리면 당신이 그의 계획서를 좀 빼내 달라고.", progress = nil, completion = "급하게 갈겨 쓴 쪽지 두루마리 하나와 원자재의 강화를 위한 설계도가 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1191] = {title = "자멕의 교란", objective = "자, 갑시다!", description = nil, progress = nil, completion = nil, rewards = nil},
[1192] = {title = "인듀리움 광석", objective = "우리 경주용차의 부품에 인듀리움 광석을 사용하고 싶지만 그러려면 상당히 많은 양이 필요하다오.\n\n하지만, 카즈 모단의 바다를 건너 황야의 땅에 있는 울다만 발굴지에 가면 인듀리움 광석을 충분히 찾을 수 있을 거요.\n\n노움 녀석들도 부지런히 모으고 있을 테니 우리도 뒤질 순 없지...", description = nil, progress = "우리 경주용차의 부품에 인듀리움 광석을 사용하고 싶지만 그러려면 상당히 많은 양이 필요하다오.\n\n하지만, 카즈 모단의 바다를 건너 황야의 땅에 있는 울다만 발굴지에 가면 인듀리움 광석을 충분히 찾을 수 있을 거요.\n\n노움 녀석들도 부지런히 모으고 있을 테니 우리도 뒤질 순 없지...", completion = "아주 잘했소! 당장 일손을 모아 다음 경주에 사용할 부품을 만들어야겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1193] = {title = "부서진 함정", objective = "커다란 부서진 함정이 앞에 놓여 있습니다. 겉으로 보아하니 오우거들이 수리를 하려다 실패한 것 같습니다. 옆에는 서둘러 적은 듯한 메모가 있는데, 기묘하게도 함정을 수리하는 데 필요한 것이 정확히 무엇인지 쓰여있습니다. 수리하려면 토륨 부품과 냉기 오일이 필요하며, 다 고치면 오우거가 지나가다가 걸릴 수도 있으니 조심해야 한다고 적혀있습니다.\n\n글을 읽을 줄 아는 오우거는 몇 되지 않는다는 사실은 확실히 큰 행운입니다.\n\n확실히 말입니다.", description = nil, progress = "커다란 부서진 함정이 앞에 놓여 있습니다. 겉으로 보아하니 오우거들이 수리를 하려다 실패한 것 같습니다. 옆에는 서둘러 적은 듯한 메모가 있는데, 기묘하게도 함정을 수리하는 데 필요한 것이 정확히 무엇인지 쓰여있습니다. 수리하려면 토륨 부품과 냉기 오일이 필요하며, 다 고치면 오우거가 지나가다가 걸릴 수도 있으니 조심해야 한다고 적혀있습니다.\n\n글을 읽을 줄 아는 오우거는 몇 되지 않는다는 사실은 확실히 큰 행운입니다.\n\n확실히 말입니다.", completion = "토륨 부품이 제자리에 꼭 들어맞아 냉기 오일을 붓는 데 필요한 도관이 됩니다. 냉기 오일을 마지막 한 방울까지 부어 넣자 함정이 작동됩니다.\n\n무심코 이곳을 지나가는 부주의한 오우거에게 화가 있을지니!", rewards = nil},
[1194] = {title = "리즐의 설계도", objective = "소금 평원에 있는 포직에게 인듀리움 광석 견본을 가져가야 합니다.\n\n제공된 아이템: \n", description = "리즐의 설계도에는 인듀리움 광석으로 부품을 강화하는 과정이 설명되어 있습니다. 그가 써 놓은 내용으로 보아 황야의 땅의 울다만에 있는 드워프의 발굴지에서 인듀리움 광석을 구해 온 것 같습니다.\n\n다른 쪽지는 대부분 내화 특성에 관한 것들입니다.\n\n그 쪽지는 설계의 사전 단계에서 사용된 것으로, 제련되지 않은 인듀리움 광석에 대해 상당한 내용이 담겨 있습니다.", progress = nil, completion = "인듀리움? 아주 흥미로워. 그래서 최근 노움들의 차가 그렇게 빨라졌군... 그 정도로 강한 열을 견딜 수 있는 광물을 찾았으니 말이야.\n\n당신이 가져온 이 견본은 너무나 값진 것이오. 이걸로 몇 가지 실험은 할 수 있겠어. 하지만 실제로 경주용차에 사용하려면 광물이 더 많이 필요할 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1195] = {title = "신성한 불꽃", objective = "썬더 블러프 상층에 있는 잔겐 스톤후프에게 가득 찬 청옥 약병을 가져가야 합니다.", description = "버섯구름 봉우리에 있는 갈라크 켄타우로스들은 켄타우로스가 창조되던 시기의 유물을 보호하고 있네. 우린 그걸 찾고 싶어! 그러려면 나이트 엘프의 달샘에서 떠온 물 한 병이 필요하다네.\n\n샘물을 모으려면 잿빛 골짜기 숲 중심부에 있는 라이네나무 은신처 근처의 드리아드들이 가지고 다니는 병 중 하나를 손에 넣어야 하네. 약병을 채울 수 있는 달샘은 대로 남쪽에 있는 팔파렌 강의 서쪽 둑 근처에 있네.", progress = "가득 찬 약병을 구하면 버섯구름 봉우리에 있는 우리 동료 라우에게 보내야 하네. 약병을 부탁한 자이니 사용 방법에 대해 잘 알고 있을 거야.", completion = "수고했네. 이거면 라우도 만족할 거요. 이걸 그에게 좀 가져다주겠소? 버섯구름 봉우리에서 즐거운 시간을 보낼 수 있을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1196] = {title = "신성한 불꽃", objective = "높새바람 봉우리에 있는 라우 클리프러너에게 가득 찬 청옥 약병을 전해야 합니다.", description = "가득 찬 약병을 버섯구름 봉우리 남동쪽 높새바람 봉우리에 있는 라우 클리프러너에게 가져다주게. 불모의 땅 남쪽 끝에 있는 구름 승강기를 타면 버섯구름 봉우리로 갈 수 있을 걸세.\n\n자네가 앞으로 우리에게 큰 도움이 될 것이라는 것은 의심할 여지가 없군.", progress = "혹시 잔겐이 보내서 왔나?", completion = "흠, 그렇네. 이 약병은 우리 목적을 이루는 데 사용할 수 있을 것일세. 드리아드와 켄타우로스의 조상이 같기 때문에 달샘의 물은 켄타우로스의 유물을 둘러싸고 있는 영원한 불꽃의 보호를 깨뜨릴 수 있게 해 줄 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1197] = {title = "신성한 불꽃", objective = "높새바람 봉우리에 있는 라우 클리프러너에게 갈래 발굽을 가져다주어야 합니다.", description = "당신이 가져온 물로 켄타우로스 유물을 감싸고 있는 불꽃을 일시적으로 누그러뜨릴 수는 있을 거요. 하지만 영구적인 게 아니니 서둘러야만 하오.\n\n여기서 북쪽으로 가면 갈라크일족 켄타우로스의 주둔지인 갈래발굽 바윗골을 찾을 수 있을 거요. 불꽃은 경비가 삼엄한 갈래발굽 바윗골 안에 있소이다.\n\n조심하시오. 이곳에는 갈라크 켄타우로스가 아주 많은데다 자신들이 소중하게 여기는 것을 그렇게 쉽게 내놓으려고 하지 않을 테니까.", progress = "어서 빨리 갈래 발굽을 손에 넣었으면 좋겠소. 아직 구하지 못했소?", completion = "이 발굽에서 이상한 힘이 흘러나오는 게 느껴지오... 연구를 해보면 틀림없이 켄타우로스에 대한 놀라운 정보를 새로 얻을 수 있을 것이오.\n\n고맙소이다. 나는 이제 당신이 가져온 이 수수께끼를 푸는 작업을 시작해야 할 것 같소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n클리프러너의 활청금석 장식띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1198] = {title = "타엘리드 찾기", objective = "검은심연의 나락에서 은빛경비병 타엘리드를 찾아야 합니다.", description = "요즘 잿빛 골짜기 해안, 검은심연의 나락에 있는 나가와 결탁한 황혼의망치단에 대한 많은 소문이 나돌고 있소.\n\n은빛 여명회에서 내 임무는 가능한 많은 정보를 수집하고, 그것이 언제 어디에 필요한지 파악하는 것이오.\n\n검은심연의 나락에서의 동태를 살피려고 정찰병을 보낸 지 몇 주가 지났소. 그런데 아직도 은빛경비병 타엘리드로부터 보고를 받지 못했소. 다른 정찰병들은 이미 긴급 임무에 투입된 상태이니, 당신이 타엘리드를 찾아 그를 좀 도와주시오.", progress = nil, completion = "새벽감시자 섀드라스께서 그대를 보낸 건 정말 다행스러운 일이오. 이 저주받은 곳에서는 정말 사악한 음모가 진행되고 있소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1199] = {title = "황혼의망치단의 몰락", objective = "다르나서스에 있는 은빛경비병 마나도스에게 황혼의 펜던트 10개를 가져가야 합니다.", description = "혼돈의 고대 신을 위한 고대 의식으로 힘을 얻은 황혼의망치단 단원들이 사악한 후원자들을 환생시켜 전 세계에 죽음과 공포를 퍼뜨리려 하고 있소.\n\n이들은 나가와 동맹을 맺고 잿빛 골짜기 해안에 있는 검은심연의 나락에 집결하고 있다고 하오.\n\n그들이 그 오래된 신전 깊은 곳에서 어떤 사악한 음모를 꾸미고 있든지 이를 반드시 좌절시켜야 하오.\n\n황혼의망치단과 결전을 벌이고 승리의 증거물을 가지고 돌아오시오. 수고에 대한 보상은 후하게 해 드리리다.", progress = "검은심연의 나락은 한때 나이트 엘프의 고대 신전이었소. 가장 강력한 힘을 지닌 달샘이 안치되어 있던 곳이었지. 그런데 이제 황혼의망치단의 손아귀에 떨어졌으니 그곳에서 어떤 사악한 음모가 꾸며지고 있을지 알 길이 없소이다.\n\n그들을 제거하는 일은 진전이 있었소?", completion = "당신은 용맹스럽고 고귀한 혈통을 타고 태어난 것이 틀림없소. 은빛 여명회는 악을 물리친 당신의 노고를 칭송하고 있소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n빛구름 장화심재 벨트"},
[1200] = {title = "검은심연의 음모", objective = "황혼의 군주 켈리스를 처치하고 그 증거로 머리카락을 다르나서스에 있는 새벽감시자에게 가져가야 합니다.", description = "이제 난 아무 힘이 없소. 당신의 도움이 필요하오!\n\n아주 오래전 이곳은 위대한 엘룬의 신전이었소. 하지만 불행히도 한 타락한 고대 신의 기운이 땅 밑에서 솟아나와 성스러운 달샘을 오염시키면서 폐허가 되어 버렸다오.\n\n고대 신의 시녀인 아쿠마이가 물 위로 올라왔소.\n\n황혼의망치단 이교도들은 이 땅을 점령하기 위해 나가와 동맹을 맺었는데, 켈리스를 따르는 이 이교도 집단은 죄 없는 자들을 아쿠마이에게 희생 제물로 바쳐 힘을 얻고 있소.\n\n켈리스를 해치우고 그의 머리카락을 다르나서스의 셀고름에게 가져다주시오!", progress = "시간은 소중한 것!\n\n이곳 다르나서스에서 내 임무는 우리 은빛 여명회의 번성을 위해 칼림도어를 침략하는 악의 무리를 막는 것이오.\n\n어서 용건을 이야기하든지 아니면 가 보시오.", completion = "켈리스 녀석은 꽤 오랫동안 우리의 추적을 피해 왔소.\n\n이 부근에 모습을 드러내던 사악한 세력들은 모두 켈리스와 끈이 닿아 있었던 모양이오. 한동안 우리는 그가 죽었거나 실종된 줄로만 알았소이다.\n\n이것으로 모든 게 해결되었소. 그의 권세가 끝났으니 무고한 자들의 목숨을 구하게 된 것이오.\n\n한 개인의 이익을 위해 고대 신의 시녀에게 희생 제물을 바치다니, 정말 말도 안 되는 일이지!\n\n아주 훌륭한 일을 해주셨소. 은빛 여명회를 대신해 진심으로 감사하오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n묘비의 홀북극의 버클러\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1201] = {title = "테라모어 첩보원", objective = "테라모어 첩보원 9명을 처치한 다음 담쟁이 마을에 있는 나지르 블러드파이크에게 돌아가야 합니다.", description = "호드와 얼라이언스는 불안정한 휴전 협정을 맺고 있네. 서로 외진 곳에서 접전을 벌이고 은밀한 공작을 펼치고 있는 이러한 시기에 호드의 승리를 확고히 하는 것이 바로 우리 임무라네. 지금이 바로 그 임무를 위한 절호의 기회라 할 수 있지!\n\n얼라이언스 첩보원들이 담쟁이 마을 동쪽 지역을 장악하고 있네. 녀석들은 마을을 염탐하고 우리의 움직임을 테라모어에 보고하고 있지. 이건 용납할 수 없는 행위야.\n\n첩보원 놈들을 찾아 처치하도록 하게. 첩보원 녀석들이 활개치는 것을 그냥 보고만 있지 않을 거란 걸 놈들의 지휘관들에게 똑똑히 보여 주게!", progress = nil, completion = "잘했네. 첩보원들이 노련하긴 하지만 그래도 우리 호드의 눈을 피할 순 없지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1202] = {title = "테라모어 부두", objective = "담쟁이 마을에 있는 나지르 블러드파이크에게 선장의 서류를 가져가야 합니다.", description = "우리 첩보원 중 두 명이 테라모어 부두에 있는 배에서 서류를 훔쳐오는 임무를 띠고 파견되었는데, 서류를 입수했으나 발각되고 말았네. 그래서 서류를 바다에 던질 수밖에 없었지.\n\n한 명은 나중에 도망쳤지만 서류는 되찾지 못했네. 그는 내게 임무 실패 사실을 보고했고 이제 그 임무를 자네에게 맡기려고 하네.\n\n문서는 테라모어 부두 밑의 물속 어딘가에 가라앉아 있는 작은 상자 안에 있네. 그 서류를 찾아 내게 가져오도록 하게.", progress = "서류는 찾았나? 그 서류에는 얼라이언스의 안전에 매우 치명적이고, 따라서 나아가 호드의 안전에도 매우 중요한 정보가 들어 있다네.", completion = "정말 수고 많았군. 쉬운 임무가 아니었을 테지만... 자네가 가져온 서류는 우리의 지휘관들에게는 매우 중요한 것일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1203] = {title = "자를의 검", objective = "먼지진흙 습지대에 있는 자를에게 달의 강철 브로드소드를 가져가야 합니다.", description = "내가 뭘 좀 잘라야 하는데... 뭘 자를 건지는 말해 줄 수 없지만... 아무튼 난 검이 좀 필요하오. 좀 특별한 검인데...\n\n어떤 이들은 그 검을 달의 강철 브로드소드라고 부르고 있지. 하지만 난 스윙 블레이드이라고 부른다오.\n\n날 좀 도와주겠소? 어쩌면 마을 안에서 찾을 수도 있을 거요. 아니면 대장장이에게 얘기해서 특별히 만들 수 있을지도 모르지.\n\n하지만 시간을 너무 지체하지 마시오. 내가 자르려는 게 영원히 그대로 있지는 않을 테니까...", progress = "검은 가지고 왔소??", completion = "정말 좋은 검이야. 휘두르는 느낌이 아주 좋지. 정말 훌륭한 스윙 블레이드야. 다시 한번 감사, 감사 또 감사하오!!! 이제 한번 사용해 봐야겠군.\n\n아니, 나중에 사용해 보도록 하지. 다시 한번 말하지만... 정말 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n갈대매듭 반지예술가의 바지"},
[1204] = {title = "진흙바위거북 수프와 벌레", objective = "테라모어에 있는 모건 스턴에게 진흙바위거북 혓바닥 8개를 가져가야 합니다", description = "지금 전 '진흙바위거북 수프와 벌레'라고 하는 저만의 특별 요리를 만드는 중이지요. 그런데 아직 주재료가 부족하답니다. 그리고... 전 먼지진흙 습지대를 가로지를 만큼 오래 걸을 수 없을 거 같습니다.\n\n그러니 제 대신 사냥을 좀 해주시겠어요? 먼저 진흙바위거북 혓바닥이 필요해요. 대해로 이어지는 만 근처의 해안가에 가시면 진흙바위거북을 찾을 수 있을 거예요.\n\n하지만 아무 혓바닥이나 사용할 수는 없습니다! 일부 진흙바위거북의 혀는 갈래가 져 있다고 들었어요.\n\n그들 말로는 그 혓바닥이 독특한 맛이 난다고 하던데, 제 요리에 그 맛을 내고 싶어요.", progress = "갈래진 혓바닥은 구해 오셨나요?", completion = "이거면 훌륭해요! 고맙습니다!\n\n이제 이 혓바닥으로 색다른 조리법을 시도해서 맛을 최고로 이끌어낼 방법을 찾아봐야겠군요.\n\n기필코 스톰윈드의 고독한 은둔자 선술집에서 내놓을 만한 훌륭한 요리를 만들어낼 거예요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1205] = {title = "붉은눈늪지악어", objective = "썬더 블러프에 있는 멜로르에게 붉은눈늪지악어 이빨을 가져가야 합니다.", description = "이제 먼지진흙 습지대에 살고 있는 고대 악어인 붉은눈늪지악어를 처치할 때가 되었소.\n\n녀석이 늪 속에서 거대한 몸을 움직일 때마다 녀석의 늙은 뼈들이 삐걱거리며 갈리고 있소. 녀석은 젊었을 때처럼 여전히 힘이 넘치고 빠르지만, 점점 늙어가는 몸이 그 안에 있는 위대한 영혼을 괴롭히고 있소이다. 영원히 꺼지지 않을 불꽃 같은 영혼을 말이오.\n\n아직도 그는 미칠 듯한 고통 속에 살고 있소. 그대가 붉은눈늪지악어가 안식을 얻을 수 있도록 이끌어 줘야 하오. 이 고귀한 생명의 삶을 끝내고 내게 그의 이빨을 가져 오시오.", progress = "붉은눈늪지악어 이빨은 가지고 왔소? 그 악어의 고통을 없애 준 것이오?", completion = "아주 잘했소.\n\n이번 사냥은 쉽지 않았겠지만 드디어 그 악어의 고통이 끝났다는 소식을 들으니 기쁘기 한이 없군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1206] = {title = "자를의 부탁", objective = "늪지기 오두막에 있는 \"늪지눈알\" 자를에게 터지지 않은 암흑안개거미의 눈 40개를 가져가야 합니다.", description = "눈알 주스는 좋은 음료지. 대부분의 동물에게 눈이 두 개밖에 없다는 게 참으로 애석할 뿐이라오.\n\n하지만 거미는 많은 눈을 가지고 있지. 엄청나게 많고 또 많은 수의 눈을 말이오. 그리고 암흑안개 거미 눈 주스는 맛이 가장 좋다오. 부드럽고 짭짤하지! 터지지 않은 거미의 눈... 난 이미 맛본 적이 있소.\n\n암흑안개 거미는 서쪽에 있는 암흑안개 거미굴에 살고 있다오. 당신도 그 동굴에서 거미 이름을 따왔다는 걸 눈치챘을 거요. 아니면... 반대로 거미 이름에서 동굴 이름을 따온 건가?", progress = "내가 말한 눈은 어디 있소?", completion = "구해 왔군! 구해 왔어! 맛있고, 맛있는 거미 눈이로고!\n\n어떤 눈은... 빤히 쳐다보고 있으면 마찬가지로 이쪽을 빤히 쳐다보는 게 있을 거요. 그런 눈은 마지막에 먹도록 하시오. 그 눈들이 늪에서 당신을 지켜 줄 테니까 말이오.\n\n안녕, 작은 거미 눈들아. 안녕! 닭고기 맛이 나는 거미 눈. 쫄깃쫄깃하고 짭짤한 닭고기 맛이 나지!\n\n으음...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1218] = {title = "독특한 양념", objective = "먼지진흙 습지대에 있는 \"늪지눈알\" 자를에게 독특한 양념 3개를 가져가야 합니다.", description = "나는 요리하는 걸 아주 좋아하지. 맛있는 늪지 요리 말이오. 바로 청개구리 뒷다리 튀김 같은 것이라오.\n\n요리를 하려면 독특한 양념이라는 향료가 필요하오. 향료를 가져오면 스튜를 만들고 잘 끓여서 나도 맛있게 먹고 또 당신한테도 좀 나누어 드리리다.\n\n스튜 좋아하시오?", progress = "향료라... 누구든 삶에 향료 같은 게 조금씩은 필요하지. 안 그렇소?", completion = "아, 내가 원하던 향료가 바로 이거요! 이 늪지 스튜 맛이 기가 막히는군.", rewards = "다음과 같은 것들을 받습니다:\n\n개구리 뒷다리 스튜"},
[1219] = {title = "오크 보고서", objective = "테라모어 부관에게 밀정의 보고서를 가져가야 합니다.", description = "푸석푸석한 흙 사이에 오크의 손만이 드러나 있습니다. 꽉 쥔 손에는 뼈를 깎아 만든 관이 쥐여 있습니다. 그리고 관 안에는 흙 묻은 양피지 문서가 들어 있습니다.\n\n양피지 문서는 오크어로 쓰여 있으며... 중요한 문서 같아 보입니다.", progress = "보고할 사안이라도 있소?", completion = "흠... 오크어를 아주 잘 읽진 못하지만, 이건... 오크 밀정이 쓴 보고서인 것 같군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1220] = {title = "사령관 바임스", objective = "사령관 개런 바임스에게 밀정의 보고서를 가져가야 합니다.", description = "당신이 발견한 오크 보고서는 반드시 바임스 사령관님께 보여 드려야 하오. 그분은 누구보다도 오크어를 잘 아시는데다가 테라모어 근방에 호드 첩보원이 있다는 사실도 아셔야 하오!\n\n사령관님은 테라모어 섬 북동쪽에 있는 병영에 계시오.", progress = "내게 볼일이 있나?", completion = "오크 밀정이 쓴 보고서로군! 이걸 어떻게 찾았나? 음, 그건 중요하지 않지. 어디, 뭐라고 써 있는지 볼까...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1221] = {title = "청엽수 줄기", objective = "구멍 난 상자를 집어야 합니다.\n땅다람쥐 지휘봉도 챙겨야 합니다.\n땅다람쥐 설명서를 찾아서 읽어야 합니다.\n\n가시덩굴 우리에서 구멍 난 상자를 사용해 땅다람쥐를 소환하고 지휘봉을 사용해 땅다람쥐에게 청엽수 줄기를 찾아내도록 해야 합니다.\n\n톱니항에 있는 메보크 미지릭스에게 청엽수 줄기 6개와 사용한 땅다람쥐 지휘봉과 구멍 난 상자를 가져가야 합니다.", description = "청엽수 줄기는 세계적인 별미지! 하지만 희귀해. 아주 희귀해. 청엽수 줄기는 불모의 땅 깊숙한 곳에 있는 가시덩굴 우리에서만 찾을 수 있어.\n\n그곳에서도 청엽수 줄기가 있는 곳을 정확히 알지 못하면 하늘에서 별 따기라니까! 내가 이 땅다람쥐를 조련하는 것도 바로 그 때문이지. 후각이 워낙 뛰어나 오십보 밖에서도 청엽수 줄기 냄새를 맡을 수 있거든.\n\n쉽지는 않을 테지만 내게 청엽수 줄기를 좀 가져다주면 후하게 보답할 거야.", progress = "청엽수 줄기는 가져왔나?", completion = "훌륭해, 가져왔군그래! 이 청엽수 줄기를 내다 팔면 목돈깨나 만질 수 있겠어!\n\n힘들게 가져와 줘서 정말 고마워, &lt;name&gt;! 자네는 아주 훌륭한 동업자야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n보석 상자"},
[1222] = {title = "말썽꾼의 탈출", objective = "\"말썽꾼\" 이그나츠를 호위한 다음 테라모어에 있는 모건 스턴과 대화해야 합니다.", description = "오, 감사합니다. 이제야 날 잡아먹으려 들지 않는 이를 만나다니!\n\n이 주변에 있는 짐승들을 처리하는 일을 도와줄 이가 필요한데, 마침 당신이 이 일에 안성맞춤일 것 같군요.\n\n요리사 모건 스턴이 새로운 조리법을 연구하고 있는데, 그가 진흙콩 잎을 모아오라고 날 여기로 보냈지요. 아마 그 잎이 요리에 안성맞춤이라고 생각하는 것 같아요.\n\n아무튼, 진흙콩 식물을 찾던 중... 그만 포위되어 버리고 말았지 뭡니까! 여기서 탈출하도록 날 좀 도와주겠어요? 그리고 내가 진흙콩을 찾는 동안 내 뒤를 좀 지켜 주시지 않으시겠어요?", progress = nil, completion = "방금 이그나츠가 진흙콩 잎을 가지고 여기 왔었는데, 당신이 그가 큰 위험에서 빠져나올 수 있도록 도왔다고 하더군요.\n\n고맙습니다. 다음에 당신이 스톰윈드의 고독한 은둔자 선술집에 가게 되면 당신에게 잔치를 베풀어 주시라고 우리 삼촌께 부탁 드리도록 하지요.", rewards = "다음과 같은 것들을 받습니다:\n\n인내의 비약"},
[1238] = {title = "사라진 보고서", objective = "담쟁이 마을에 있는 나지르 블러드파이크에게 밀정의 보고서를 가져가야 합니다.", description = "푸석푸석한 흙 사이에 오크의 손만이 드러나 있습니다. 꽉 쥔 손에는 뼈를 깎아 만든 관이 쥐여 있습니다. 그리고 관 안에는 흙 묻은 양피지 문서가 들어 있습니다.\n\n양피지 문서는 몇 주 동안 테라모어 도시를 염탐한 오크에 의해 작성된 보고서입니다.\n\n양피지 문서를 자세히 살펴본 결과, 담쟁이 마을에 있는 오크 나지르 블러드파이크에게 전달해야 할 보고서였던 것이 분명합니다.", progress = "내게 무슨 볼일이라도 있나?", completion = "잘했군. 마그 나이트아이는 테라모어 외곽에 배치되었던 우리 요원일세. 그는 그 도시를 염탐하는 임무를 맡고 있었지.\n\n이건 그의 최근 보고서인데, 자네 얘기대로라면 동시에 그의 마지막 보고서가 되겠군. 흠, 마그가 늪에서 최후를 맞이한 건 아닌가 싶어 걱정이 되는군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1239] = {title = "무서운 가면", objective = "담쟁이 마을에 있는 나지르 블러드파이크에게 험상궂은 오크 가면을 가져가야 합니다.", description = "열심히 땅을 파자 거칠게 보이는 남자 오크의 가면이 나왔습니다. 입술은 으르렁거리며 굳은 듯, 다소 반항적인 눈동자로 당신을 노려보는 형상입니다.", progress = "보고할 또 다른 사항이라도 있나?", completion = "이건 마그 나이트아이의 쓰던 가면이군! 걱정했던 대로 그는 죽은 것이야.\n\n여기를 좀 보게! 도대체 어떤 무기로 당했기에 이 지경이 된 거지? 혹시 야수에게 당한 것인가?\n\n우리는 반드시 알아내야 하네. 마그가 얼라이언스 손에 죽은 것인지 반드시 알아내야만 해!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1240] = {title = "트롤 의술사", objective = "가시덤불 골짜기의 그롬골 주둔지에 있는 킨윌레이에게 혼이 깃든 오크의 가면을 가져가야 합니다.", description = "반드시 마그의 죽음을 둘러싼 사건들에 대해 알아내야 하네! 트롤의 마법을 통해서만 가능할 거야.\n\n마그의 가면을 가시덤불 골짜기의 그롬골 주둔지에 있는 킨윌레이에게 가져가게.\n\n킨윌레이는 가장 강력한 검은창부족 의술사일세. 마그 나이트아이의 영혼과 이야기할 수 있는 자가 있다면 바로 그 친구일 거야.", progress = "분노에 가득 찬 영혼이 당신 주위를 떠돌고 있군. 무슨 일로 이 킨윌레이를 찾아왔지?", completion = "아, 이제 알겠군. 이 오크의 영혼은 이 세계에 묶인 채, 아직 완수하지 못한 임무로 인한 분노로 끓어오르고 있군.\n\n자, 그럼 분노에 찬 오크와 대화를 나눠 보도록 할까...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1241] = {title = "실종된 사신", objective = "스톰윈드에서 요르겐을 찾아야 합니다.", description = "최근 테라모어에 사신을 보내 제이나 프라우드무어님을 만나 보도록 했었소. 그런데 그 사신이 그곳에 도착하지 않은 모양이오.\n\n나는데피아즈단이 이 음모와 관련이 있다고 보지만 자세한 내막은 확실하지 않소. 아직은 주민들에게 사신의 행방불명 소식이 알려지지 않았으나, 언제까지나 비밀로 묻어 둘 수는 없는 일이오.\n\n이미 폐하의 신하들이 단서를 찾기 위해 도시를 조사하고 다니고 있지만, 나는 내 나름의 인맥을 이용해 보려고 하오.\n\n영웅의 계곡에서 낚시를 즐기길 좋아하는 요르겐이라는 내 옛 친구가 있소. 그를 찾아 이 편지를 전하고 그의 지시를 따르도록 하시오.", progress = "흠, 당신 내가 고기 잡는 걸 방해할 정도로 중요한 일이 있어야 할 거요. 난 거지뿐 아니라 행상인에게도 친절을 베풀어 본 적이 없는 사람이오.", completion = "흠... &lt;곁눈질로 당신을 올려다보는 요르겐&gt;\n\n좋소. 당신을 돕도록 하지. 하지만 이건 내가 원해서가 아니라 친구의 부탁에 대한 의무감 때문이라는 걸 알아두시오.\n\n그리고 한 가지 확실히 해 둡시다. 당신은 이미 알아야 할 사실보다 훨씬 더 많은 걸 알고 있소. 이건 우리끼리의 작은 비밀로 하는 게 좋겠소. 당신이 알게 된 내용에 대해 선술집에서 함부로 떠들지 않도록 하시오, 알겠소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1242] = {title = "실종된 사신", objective = "스톰윈드 내에 있는 엘링 트리아스에게 엘링에게 보내는 봉인된 쪽지를 전해야 합니다.", description = "이 쪽지를 엘링 트리아스에게 전하시오. 하지만 그에게 그 외의 다른 말은 절대 하지 마시오. 그저 예의바르게 그가 대답할 때까지 기다리기만 하면 되오. 기다리면 대답이 있을 테니 걱정은 하지 말고 말이오.\n\n다시 한번 강조하지만, 이번 일은 진지하게 임해야 하고 반드시 입 조심 해야 하오.\n\n트리아스는 상업 지구에 그가 운영하는 트리아스 치즈 상점에 있을 거요.", progress = "어서 오세요. 무엇을 도와드릴까요? 특별히 만든 트리아스 체더 치즈를 맛보시겠어요? 아니면 다르나서스 브루 치즈 한 덩어리는 어떻습니까?", completion = "죄송합니다만, 저한테 온 편지라고요? 글쎄요, 제가 하는 일이라곤 치즈 파는 일밖에 없는데다 상자나 통이 아닌 다른 건 자주 받는 편이 아니라서 말입니다. 어디, 뭐에 관한 내용인지라도 좀 봅시다.\n\n&lt;편지를 열며 당신을 올려다보는 엘링&gt;\n\n좀 긴장하신 것 같아 보이는데, 괜찮습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1243] = {title = "실종된 사신", objective = "그늘숲에 있는 순찰대원 바커스에게 봉인된 쪽지를 가져가야 합니다.", description = "요르겐, 이 몹쓸 친구 같으니라고... 그래, 결국 이렇게 되는 것인가?\n\n괜찮습니다. 이 정도는 감당할 수 있습니다. 요르겐 그 친구가 어서 빨리 뒤틀린 황천에나 가 버렸으면 좋겠군요!\n\n앞으로 어떻게 될 것인지 말씀드리죠. 여기서는 내 인맥을 이용해 보겠지만, 발로 뛰어다녀야 할 일의 대부분은 직접 맡아 주셔야겠습니다. 그래야 돈을 좀 절약할 수 있으니까요.\n\n그늘숲의 다크샤이어로 가서 순찰대원 바커스를 찾으세요. 그는 주로 마을 바로 외곽의 북쪽 도로를 순찰한답니다. 날 위해 데피아즈단의 활동에 대해 조사 중이라고만 말하면 그가 아는 모든 정보를 알려 줄 겁니다.", progress = "숲 속을 돌아다니는 것은 위험합니다. 조심하도록 하시고 의심스러운 일이나 위험한 것을 보면 즉시 순찰대원에게 알려주시기 바랍니다. 혼자서 해결하려고 하지 마시고요. 당신에게 끔찍한 일이 일어나더라도 우린 책임이 없으니까요.\n\n그러나 당신이 내 말을 무시하고 어둠 속에서 나타나는 것이라면 그것이 무엇이든 맞서 싸우리라는 것을 우리 모두 알고 있지요. 내 말이 틀렸습니까? 하하, 그래요, 당신은 모험가 같이 보이니까...", completion = "아, 트리아스가 당신을 보낸 거였군요? 그렇다면 얘기가 달라지지요.\n\n어둠 속에서 당신 앞에 그 어떤 극악무도한 것이 다가오더라도 맞서 싸우도록 하십시오. 트리아스 같은 친구들과 어울릴 정도라면 아무리 위험한 일이라도 간단히 처리할 수 있을 거라 믿습니다.\n\n그래, 요즘처럼 우울한 날에 내 친구는 내게 대체 뭘 원하는 겁니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1244] = {title = "실종된 사신", objective = "데피아즈단의 일정표를 찾아 그늘숲에 있는 순찰대원 바커스에게 가져가야 합니다.", description = "데피아즈단의 활동? 글쎄요, 그들은 항상 무슨 일을 꾸미고 있지요. 설사 그들이 조용히 지낸다 하더라도 위협으로 간주해야 할 정도니...\n\n아, 이제 생각해 보니 최근에 이상한 일을 목격한 적이 있습니다. 몇 주 전에, 그들 요원 중 몇몇이 에이들의 은신처 근처에 모였던 적이 있었습니다. 이에 대한 보고를 듣고 뭔가 큰 일이 아닐까 싶은 생각이 들더군요.\n\n우선 그곳을 확인해 보고 뭔가 발견하게 되면 내게 가져와 보는 게 어떻겠습니까? 그 농장은 당신이 그늘숲으로 들어올 때 지나온, 서부 몰락지대로 이어진 도로의 남쪽에 있습니다.", progress = "조심하십시오. 트리아스가 보낸 이라고 해도 숲 속에 숨어 있는 것들로 인해 화를 당하지 말라는 법은 없으니까요. 특히, 당신처럼 데피아즈단을 조사할 때는 더욱 그렇습니다.", completion = "무사히 돌아왔군요. 더 이상 뭘 바라겠습니까, 안 그렇습니까?\n\n자, 그럼 뭘 입수했는지 한번 볼까요. 흠, 그간 보아온 것과 비교해보면 이 문서는 진짜가 맞는 것 같군요. 하지만, 무엇이든 당신이 찾고 있는 것으로부터 당신을 따돌리기 위한 속임수일 수도 있답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1245] = {title = "실종된 사신", objective = "스톰윈드에 있는 엘링 트리아스에게 데피아즈단의 일정표를 가져가야 합니다.", description = "이런, 당신을 따돌리기 위한 물건이라고 하기엔 지나치게 복잡하군요. 난 이런 건 제대로 보지도 못하겠습니다. 이걸 트리아스에게 가져가도록 하십시오. 그라면 이해할 수 있을 겁니다. 그리고 그 누구도 당신을 방해하지 못하도록 해야 합니다. 이건 내가 감당할 수 있는 것 이상이군요. 트리아스도 감당할 수 없을지 모르지만 두고 볼 일이죠.\n\n그리고 내 부탁 하나 합시다. 아무에게도 내가 당신을 도왔다는 말은 하지 말아 주시기 바랍니다. 내 상관들이 내가 이 일에 대해 조금이라도 알고 있으면서, 그들에게 알리지 않았다는 걸 알게 되는 날에는 틀림없이 난 교수형을 당하게 될 겁니다.", progress = "어디 한 군데 다친 데 없이 무사히 돌아오셨군요. 당신이 치즈를 사러 온 게 아니라는 건 자명하니까, 농담은 그만두기로 하고... 바커스가 좀 도움이 되던가요? 아니면 아직 그늘숲으로 떠나지도 않은 건가요?", completion = "이것 참... 흥미로운 내용이군요. 요르겐과 드라베이가 이 일에 날 끌어들이다니 정말 빈틈없군요.\n\n데피아즈단이 이 계획을 완수하기 위해 아주 열성적으로 노력해 온 것 같군요. 흠... 이건 뭐지? \"주먹\"? 낯익은 이름인데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1246] = {title = "실종된 사신", objective = "스톰윈드에 있는 다셸 스톤피스트와 대화해야 합니다.", description = "아, 제 기억으론... 다셸... 다셸 뭔데... 이름이 뭐였더라? 아! 그래요, 피스트! 다셸 스톤피스트. 어떤 이들은 그를 '돌주먹'이라고 부른답니다. 아마 그가 싸움질을 좋아하기 때문일 겁니다.\n\n그는 주로 구 시가지 중앙에서 바로 오른쪽에 위치한 곳에 주로 있답니다. 그를 만나 보시는 게 좋겠군요. 필요하다면 검이나 다른 묵직하고 단단한 것을 사용해 자백을 받아내도록 하십시오. 그리고 주저해서는 안 됩니다. 이 문서에 나와 있는 대로 정말 그가 이 일에 깊이 관여하고 있다면 어떠한 정보도 쉽게 내주진 않을 테니까 말입니다.", progress = nil, completion = "뭐라고?!\n\n이 골목에 날 밀어넣곤 내 개인적인 일에 관해 질문을 하겠다고? 분명히 당신과는 아무 관계도 없는 일일 텐데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1247] = {title = "실종된 사신", objective = "스톰윈드에 있는 엘링 트리아스와 대화해야 합니다.", description = "좋아, 음, 에이들의 은신처에서 있었던 회의에 대해 좀 알고 있지. 몇 주 전이었던 거 같은데, 난 절대 거기에 참여하진 않았소. 1차 작전이 실패했을 때 내 임무는 이미 끝났다고... 그놈의 모험가들 때문에...\n\n2차 작전을 위해 내부에서 포섭한 홀쭉이라는 자가 메네실에서 왔었소. 2차 작전에 관해서 이게 내가 아는 전부요.", progress = nil, completion = "아직까지 살아있는 걸 보니 정말 기쁩니다. 그래, 다셸과는 이야기가 잘 된 겁니까?\n\n그들이 벌이고 있는 이 계획에 대해 좀 더 읽어 봤습니다. 그들이 쫓고 있는 사신의 이름이 거론되진 않았지만, 그 사신을 납치하려는 첫 번째 시도가 실패한 후 진행 중인 이번 2차 작전에 대해 언급하고 있습니다.\n\n다셸이 얘기한 이 홀쭉이란 자가 여기에 다른 이름으로 거론되지 않았지만, 그가 메네실에 있다면 거기부터 시작하면 될 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1248] = {title = "실종된 사신", objective = "저습지에 있는 미크헤일과 대화해야 합니다.", description = "내가 아는 이 중 하나가 저습지에 메네실 항구 도시에 칩거하고 있습니다. 당신이 날 위해 일하고 있다는 얘기만 하면 기꺼이 도와줄 겁니다. 그의 이름은 미크헤일이라고 합니다. 몇 해 전 스톰윈드를 떠나기 전에는 바텐더가 되겠다고 말했었지요.\n\n그와 얘기한 다음 이 홀쭉이란 자를 찾도록 하세요. 그리고 이 납치된 사신에 대한 다른 정보가 있는지 찾아 보시기 바랍니다. 우리는 그를 어디로 데려갔는지, 아니면 최소한 그가 누구인지 라도 알아내야 합니다. 이 일정표에는 사신을 납치한 후의 계획에 대해선 어떠한 언급도 없습니다.", progress = nil, completion = "어서 오세요, 반갑습니다. 저희 가게를 찾아 주셔서 대단히 감사합니다. 오늘은 에일 맥주로 드릴까요? 아니면 양고기를 좀 드시겠습니까?\n\n원하시는 걸 말씀만 하시면 성심 성의껏 모시도록 하겠습니다. 제 이름은 미크헤일이며 손님을 모시게 되어 기쁩니다.\n\n흠? 그게 뭐죠? 트리아스? 목소리를 낮춰주세요, 손님. 이건 이 선술집에 있는 이들이 모두 들어야 할 얘기가 아닙니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1249] = {title = "실종된 사신", objective = "타포케 잔이 도망가기 전에 그를 제압한 다음 메네실에 있는 미크헤일에게 돌아가야 합니다.", description = "엘링 씨가 여기로 보냈다고 하셨습니까? 흠, 그렇다면 열 배로 더 환영입니다. 필요한 게 있으면 뭐든 말씀만 하세요. 최선을 다해 돕겠습니다.\n\n흠, 홀쭉이라고요? 그 이름을 들어 본 적이 있는지는 확실치 않지만, 힘 닿는 대로 그를 찾아 보도록 하겠습니다.\n\n지금은 이리저리 둘러보지 마십시오. 출구 옆의 저 신사분이 이쪽을 보고 있습니다. 우리 대화를 좀 지나치게 집중하면서 듣고 있어요. 무슨 말인지 아시죠? 만약 제가 손님이라면 저자가 문으로 도망가기 전에 그를 잡아 버릴 겁니다.", progress = nil, completion = "그를 잡았다고요? 잘하셨습니다. 그가 홀쭉이었다니 저도 놀랐습니다.\n\n솔직히 말하면, 제가 비밀 지하 활동의 짜릿한 스릴을 그리워하게 될 거라고는 생각지도 못했습니다. 세 살 버릇 여든까지 간다는 속담처럼 오래된 습관은 버리기 어려운 것 같군요. 오, 엘링씨에겐 말하지 마세요. 제가 그런 일을 그리워한다는 얘기를 들으면 틀림없이 절 스톰윈드로 다시 데려가려고 할 겁니다.\n\n손님께서 메네실에 계시는 동안 제가 작게나마 도움이 될 수 있어서 기쁩니다. 또 더 필요한 게 있으면 말씀만 하세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1250] = {title = "실종된 사신", objective = "저습지에 있는 미크헤일과 대화해야 합니다.", description = "데피아즈단이 놈들을 위해 목숨을 걸 만큼 충분히 많은 돈을 내게 지급한 건 아니니까... 놈들은 왕을 납치한 거야. 그래, 하찮은 사신 따위가 아니라 스톰윈드의 왕을 말이야. 왕은 제이나 프라우드무어를 만나기 위해 테라모어로 가는 길이었지. 뭔가 대단히 중요하고도 비밀스러운 목적이 있는 것 같았어. 하지만 이 일에 관련된 건 데피아즈단만이 아니야. 데피아즈단은 다른 누군가와 함께 일하고 있어. 아마 놈들이 혼자 감당하기에는 벅찬 일이라는 걸 알았던 것 같아.\n\n내가 한 일은 그저 배가 출항하기 전 항구에 있을 때 놈들이 보낸 헨델이라는 자를 왕의 배에 몰래 태운 것뿐이야. 맹세코 이게 내가 아는 전부라고!", progress = nil, completion = "왕이라고요? 정말... 왕 말입니까? 진짜 왕 말입니까? 농담이신 거죠? 왕을 납치한 납치범들을 찾고 있단 말은 하지 않았잖습니까! 왕께서 실종됐다는 얘기는 듣지도 못했는데... 그렇다면 왕의 아드님이 왕관을 쓰고 있는 것이 설명되는군요.\n\n지금 바로 엘링씨에게 이 소식을 전하도록 하겠습니다. 엘링씨도 단서를 찾았다는 소식을 듣고 싶어할 테니까요.\n\n잔이 더러운 돈을 위해 스톰윈드를 배신할 줄은 꿈에도 몰랐습니다. 제 아무리 악당이라도 최소한의 명예는 지키게 마련인데 말입니다.\n\n이제 문제의 열쇠는 이 헨델이라는 자를 찾는 거로군요. 그건 제가 도울 수 있을 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1251] = {title = "검은 방패", objective = "담쟁이 마을에 있는 크로그에게 타락의 철제 방패를 가져가야 합니다.", description = "그늘 쉼터 여관 건물의 얼마 남지 않은 부분 중 하나인 허물어진 굴뚝에 여관 전체를 휩쓸어 버린 불로 검게 그을린 철제 방패가 붙어 있습니다.\n\n굴뚝의 벽돌에서 방패를 떼어낼 수 있습니다.", progress = "가지고 있는 게 뭐지? 그늘 쉼터 여관 잔해에서 무슨 단서라도 찾은 것이오?", completion = "인간들의 장식 취향이 독특한 건 인정하지만, 벽난로 위에 평범한 철제 방패를 장식했을 리는 없을 텐데? 아마 이 방패는 여관에 불을 지른 자들이 두고 간 걸 것이오.\n\n경고 아니면 위협의 표시인가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1252] = {title = "부관 파발 리테", objective = "테라모어에 있는 사령관 개런 바임스에게 리테의 배지를 가져가야 합니다.", description = "잔해 밑에서 뭔가가 반짝이는 것이 눈에 띕니다. 그 물건을 덮고 있는 잔해와 재를 털어내자 표면에 에나멜을 입힌 흰색 바탕에 황금 닻이 그려진 배지가 드러납니다. 바로 테라모어의 상징입니다.\n\n닻 아래에는 '부관 파발 리테'라는 이름이 새겨져 있습니다.", progress = "그늘 쉼터 여관에서 뭔가 흥미로운 단서라도 찾았나?", completion = "경비병의 배지가 내게 전해진다는 것은 언제나 좋지 않은 소식을 의미하지.\n\n전장에서 전사했을 경우 슬퍼할 가족에게 소식을 전해야 하는 건 나니까 말일세. 그 경우가 아니라면 배지의 주인에게 무슨 일이 일어난 것인지 우리로서는 알 수가 없다네. 아니면 그보다도 더 나쁜 경우도 있고 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1253] = {title = "검은 방패", objective = "테라모어에 있는 사령관 개런 바임스에게 타락의 철제 방패를 가져가야 합니다.", description = "그늘 쉼터 여관 건물의 얼마 남지 않은 부분 중 하나인 허물어진 굴뚝에 여관 전체를 휩쓸어 버린 불로 검게 그을린 철제 방패가 붙어 있습니다.\n\n굴뚝의 벽돌에서 방패를 떼어 낼 수 있습니다.", progress = "그늘 쉼터 여관의 화재 현장에서 무슨 단서라도 찾았나?", completion = "흠, 무기나 갑옷 만드는 일에 대해서는 잘 모르는데... 어떻게 사용해야 하는지는 잘 알고 있지만 만드는 건 내 전문이 아니니까 말일세.\n\n이 방패는 여관에 일어난 화재로 손상되었다는 것 외에는 아주 평범해 보이는군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1258] = {title = "... 그리고 벌레", objective = "테라모어에 있는 모건 스턴에게 온전한 집게 다리 12개를 가져가야 합니다.", description = "새로 시도해 보는 이번 요리에 들어갈 또 다른 재료로는 거대한 게의 딱딱한 다리가 있습니다. 그런데 먼지진흙 습지대에서 서식하는 진흙껍질마크루라는 게로는 안 됩니다! 아무래도 적합한 게를 찾으려면 멀리 슬픔의 늪까지 가야만 할 것 같아요.\n\n게 다리의 껍질이 이번 요리의 모양을 결정하는 핵심적인 요소니까 긁히지 않은 온전한 다리가 필요해요. 다 큰 게에는 그런 다리가 한 개 내지는 두 개밖에 없는데 제 요리를 연구하려면 많이 필요하답니다.\n\n그러니까... 여행 한번 해보실 생각 없으신가요?", progress = "진흙바위거북의 혓바닥으로 만드는 요리의 연구는 순조롭게 진행되고 있습니다. 사냥은 잘 되어가시겠죠?", completion = "기가 막히게 좋은 견본을 가져오셨군요! 껍질은 손상되지 않은 완벽한 상태를 유지하고 있고 살은 분홍색을 띠고 아주 야들야들하네요. 당신 몸에는 요리사의 피가 흐르고 있는 게 틀림없어요!", rewards = "다음과 같은 것들을 받습니다:\n\n바로크식 의복"},
[1259] = {title = "부관 파발 리테", objective = "테라모어에 있는 부관 테소렌으로부터 리테에 대해 알아내야 합니다.", description = "부관 파발 리테라는 이름은 처음 들어 보는데... 부관 테소렌을 만나 확인해 보는 게 현재로선 가장 현명한 선택일 듯하네. 테소렌은 개인 신상 정보에서 장비에 이르기까지 테라모어 경비병에 대한 모든 기록을 보관하고 있으니까 말일세.\n\n그라면 이 리테라는 자가 누구인지 자료를 찾아 금방 확인해 줄 수 있을 것일세.", progress = nil, completion = "안녕하시오. 테라모어 경비병에 대한 정보가 필요하다고 했소? 리테, 맞소이까?\n\n잠시만 기다려 보시오. 어느 장부에 기록이 있는지 찾아보도록 하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1260] = {title = "모건 스턴", objective = "테라모어에 있는 모건 스턴과 대화해야 합니다.", description = "전 식당에서 선보일 새로운 메뉴를 개발하고 있습니다. 호수를 주제로 한 전원풍의 요리들로 구성할 참이지요. 아마 고독한 은둔자 선술집에 있는 우리 단골이 아주 좋아할 거예요!\n\n조카 모건을 먼지진흙 습지대 가장자리에 있는 도시인 테라모어로 보냈지요. 그 지역의 조리법을 수집하고 있는데, 지금까지 얼마나 수집했는지 궁금하네요.\n\n테라모어까지는 아주 먼 길입니다. 제게는 너무나도 먼 길이지요. 하지만 당신처럼 젊은 <class>|1이라면;라면; 이런 여행 기회를 마다하리라 생각되지 않는데... 어떻습니까?", progress = nil, completion = "오, 삼촌이 보내셨다고요?\n\n음, 조리법을 조사해서 몇 가지 실마리를 얻긴 했지만 도움이 필요하답니다.\n\n발이 젖는 것쯤은 마다 않고 기꺼이 도와줄 이가 필요한데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1261] = {title = "말하는 마그", objective = "담쟁이 마을에 있는 나지르 블러드파이크에게 보석 펜던트를 가져가야 합니다.", description = "괘씸한 진흙껍질 녀석들!! 누구도 이 마그를 죽일 순 없어! 아, 그렇지만 난 죽어버렸어. 틀림없이 놈이 나를 죽인 거야.\n\n하지만 내 임무! 내 임무는 어떻게 하지? 당신이 내 임무를 완수해 줬으면 해.\n\n테라모어 근처에 있는 동안 난 해변에 있는 얼라이언스 병사들을 염탐했었지. 그들 중 한 명이 펜던트를 걸고 있었는데... 보통 병사들은 가질 엄두도 못 낼 만큼 많은 보석이 박힌 펜던트였어.\n\n그날 밤 난 놈들의 야영지에 몰래 숨어 들어 펜던트를 훔쳤지만 기지로 돌아오는 길에 진흙껍질 게 인간 녀석이... 날 죽이고 말았어!\n\n그 진흙껍질을 찾아 반드시 펜던트를 찾아와야 해!", progress = "마그의 운명에 대해서는 알아냈나?", completion = "이 펜던트가 스톰윈드의 병사가 지니고 있던 거라고??\n\n고맙네. 자네는 마그의 죽음에 얽힌 비밀을 밝혀 주었어. 하지만 이 펜던트는 풀어야 할 또 다른 의문 거리로군. 얼라이언스와 호드에 끔찍한 영향을 미치게 될지도 모르는 그런 의문 거리 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1262] = {title = "조르에게 보고하기", objective = "오그리마에 있는 조르 론트리에게 보석 펜던트를 가져가야 합니다.", description = "마그가 훔친 펜던트가 일개 병사들의 수중에 있다니 이상한 일이군. 어쩌면 그 주인이 변장을 하고 있었던 것일 수도 있고 아니면 그 병사들이 직접 훔친 것일 수도 있네!\n\n어느 쪽이 사실이든지 간에 이것은 귀족의 펜던트이고 이 펜던트의 수수께끼를 풀려면 진짜 주인을 찾아야 하네.\n\n오그리마에 있는 조르 론트리에게 그 펜던트를 가져다주게. 얼라이언스 정치학을 오래 공부한 자라 이 펜던트가 스톰윈드의 귀족들 간에 유서가 깊은 물건인지 알 수 있을 걸세.", progress = "자네 먼지진흙 습지대의 담쟁이 마을에서 온 겐가? 나지르는 어떤가? 습지대 일은 잘 되어 가고 있나?", completion = "이 펜던트는 상당히 수준 높은 기술로 정교하게 만들어졌네. 오크는 이런 보석을 탐내지 않지... 인간이라면 모를까...\n\n난 이 펜던트를 연구하겠네. 조만간 이 펜던트의 비밀이 드러나기를 기대해 보세나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1263] = {title = "불타는 여관", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1264] = {title = "실종된 사신", objective = "먼지진흙 습지대에서 사령관 사마울을 찾아야 합니다.", description = "매월 초 모든 쿨 티라스 해병들은 대개 월급을 받고 테라모어를 떠나 다른 곳으로 갑니다. 그들 중 많은 이들은 술과 여자를 찾아 흥청망청 놀기 위해 이곳으로 오곤 하죠. 이 선술집의 단골 손님이라 할 수 있는 그런 무리 중 하나에 이 헨델이란 자도 있었던 것 같군요.\n\n헨델이 아직 테라모어에 배치돼 있다면 그곳의 사령관 사마울님이 그를 찾는 걸 도와줄 수 있을 겁니다. 사마울님은 프라우드무어님께 충성심이 아주 대단하지만, 그래도 엘링의 이름을 대면 아마 따로 도와줄 겁니다.", progress = nil, completion = "만나서 반갑소. 나는 사령관 사마울이오. 난 이곳 테라모어에 있는 프라우드무어님의 군대를 이끌고 있소.\n\n내 비록 아주 바쁜 몸이긴 하지만 질문이 있다면 주저 말고 물어보도록 하시오. 오래 시간을 내지는 못하겠지만 당신이 내 도움을 필요로 한다면 모른 척하지 않을 테니까.\n\n이 도시를 벗어나 여행할 생각이라면 조심하는 게 좋을 거요. 오우거나 오크, 멀록뿐만 아니라 습지 남쪽엔 검은 용이 우글거리니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1265] = {title = "실종된 사신", objective = "감시초소에서 병사 헨델에 대한 단서를 찾아야 합니다.", description = "헨델? 물론 알고 있소만 내 병사는 왜 찾는 거요?\n\n엘링이 그를 찾기 위해 당신을 보냈다고? 흠, 별로 마음에 들지 않는 소린데... 일이 잘못되지 않았다면 엘링이 먼저 당신을 내게 보냈을 리가 없소. 무슨 일인지 말해줄 수 없다는 건 이해하겠소. 하지만 이건 알아 두시오. 나에게는 이 땅을 보호할 책임이 있소. 그러니 당신이 문제를 일으킬 거라면 내게 미리 알려 주기 바라오.\n\n헨델은 테라모어 외곽의 첫 번째 탑에 있을 거요. 조심하시오.", progress = nil, completion = "당신이 찾는 헨델이라는 자는 여기 없습니다. 당신이 이미 알고 있으리라 생각되는 정보가 다른 출처를 통해 프라우드무어님께 전해졌습니다. 프라우드무어님께서는 내게 당신을 찾아 도움을 주라고 부탁하셨습니다. 당신이 내 도움을 받아들인다면 그에게 심판을 내릴 수 있도록 내가 헨델이 있는 곳을 알려 주도록 하겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1266] = {title = "실종된 사신", objective = "먼지진흙 습지대에서 병사 헨델을 찾아야 합니다.", description = "병사 헨델은 이곳에서 북서쪽으로 가면 찾을 수 있습니다. 지금 그는 테라모어의 첩보원들 중 일부가 휴식을 취하는 동안 그들을 보호하는 경비 임무를 수행하고 있답니다. 그들은 호드 기지인 담쟁이 마을을 주시하면서 우리 영토의 경계를 위협할지 모를 다른 적들을 수색하고 있습니다.\n\n도로변에 있는 야영지만 찾으면 그를 쉽게 볼 수 있을 겁니다.\n\n난 처리해야 할 다른 일이 있어서 이만... 하지만 곧 당신을 따라잡을 수 있을 겁니다. 문제가 언제든지 생기면 테라모어에 있는 프라우드무어님의 탑으로 날 찾아오시기 바랍니다.", progress = nil, completion = "안녕하시오. 이곳은 돌아다니기에 위험한 곳이오. 목숨이 아깝다면 너무 오랫동안 어슬렁거리지 않는 게 좋을 거요.\n\n질문을 짧게 끝낸다면 내가 도와줄 수 있을지 한번 생각해 보겠소. 이 습지 어딘가에 호드의 기지가 있다는 소문이 있소. 첩보원들이 그걸 찾기 위해 최선을 다하고 있지만 진행 상황이 너무 느리고 진척이 별로 없었소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1267] = {title = "실종된 사신", objective = "먼지진흙 습지대에 있는 제이나 프라우드무어와 대화하십시오.", description = nil, progress = nil, completion = "우선, 수고해 줘서 매우 고맙게 생각합니다. 그대는 우리와 스톰윈드의 주민들에게 너무나도 큰 축복이었습니다. 좀 더 나은 상황에서 만나지 못한 것이 아쉽군요. 그대의 공로를 널리 알리지 못하는 점 또한 이해해 주길 바랍니다. 하지만 정말 너무 감사하게 생각하고 있습니다.\n\n앞으로 테라모어에 들리게 되면 나를 찾아오시기 바랍니다. 계속 상황을 잘 파악할 수 있도록 알려드리도록 하겠습니다.\n\n다시 한번 감사드립니다, &lt;class&gt;|1이여;여;.", rewards = "다음과 같은 것들을 받습니다:\n\n제이나의 인장 반지"},
[1268] = {title = "수상한 발굽 자국", objective = "담쟁이 마을에 있는 크로그에게 그늘 쉼터 여관의 수상한 흔적에 대해 보고해야 합니다.", description = "아직도 연기가 피어나는, 잔해만 남은 그늘 쉼터 여관에서 나와 이어져 있는 발굽 자국이 있습니다. 최소한 몇 개는 눈으로 확인할 수 있지만 다른 자국들은 습지의 부드러운 흙에 묻혀 알아보기 어렵습니다.", progress = nil, completion = "발굽 자국이라... 내 생각엔, 어쩌면 가시멧돼지일지 모르겠군. 아니면 켄타우로스일지도... 불모의 땅에서 그들은 무시할 만한 존재가 아니오. 그러나 아직은 행동을 취할 단계가 아닌 것 같군.\n\n내가 말하지 않았던가? 그냥 단순히 여관이 불타 버린 게 다가 아니라, 여관 주인의 아내와 아이들이 살해당했소. 정말 안됐지.\n\n어쨌든, 카고로를 보내 흔적이 어디로 이어져 있는지 알아보도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1269] = {title = "부관 파발 리테", objective = "담쟁이 마을에 있는 크로그에게 리테의 배지를 가져가야 합니다.", description = "잔해 밑에서 뭔가가 반짝이는 것이 눈에 띕니다. 그 물건을 덮고 있는 잔해와 재를 쓸어내자 표면에 에나멜을 입힌 흰색 바탕에 황금 닻이 그려진 배지가 드러납니다. 바로 테라모어의 상징입니다.\n\n닻 아래에는 '부관 파발 리테'라는 이름이 새겨져 있습니다.", progress = "그늘 쉼터 여관에서 일어난 사건에 대한 단서를 찾았나?", completion = "난 이 파발 리테라는 인간을 알고 있소. 아무리 인간들의 일이라 해도 참 안 된 일이지. 그는 동료 병사들을 버리고 지금 숲 속에 숨어 있소.\n\n난 오그론을 보내 그를 뒤쫓도록 했지. 다른 이들 중 일부는 그가 우리 보급품을 훔쳐 왔다고 의심하고 있소. 내가 오그론이 남동쪽을 향해 가는 걸 본 것 같소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1270] = {title = "말썽꾼의 탈출", objective = "\"말썽꾼\" 이그나츠를 호위한 다음 톱니항에 있는 메보크 미지릭스와 대화해야 합니다.", description = "오, 감사합니다. 이제야 날 잡아먹으려 들지 않는 이를 만나다니!\n\n이 주변에 있는 짐승들을 처리하는 일을 도와줄 이가 필요한데, 마침 당신이 이 일에 안성맞춤일 것 같군요.\n\n톱니항에서 온 메보크 미지릭스라는 고블린이 진흙콩 잎이 필요하다더군요. 물약을 만드는 데 쓴다나 뭐라나... 뭐, 솔직히 나야 뭘 위한 거든 상관없고... 그가 꽤 넉넉히 돈을 쳐주는데다가 내가 이 늪지 지리에는 밝거든요. 그래서 여기 온 거랍니다.\n\n그런데 안타깝게도 진흙콩을 찾기도 전에 온통 짐승들에 둘러싸여 버렸답니다! 내가 메보크에게 가져다줄 잎을 찾는 동안 내 뒤를 좀 지켜 주지 않겠어요?", progress = nil, completion = "말썽꾼 이그나츠가 내가 부탁했던 약초들을 가지고 왔었지. 자네가 궁지에서 구해 줬다고 하더군. 잘했어! 이그나츠의 친구는 곧 나의 친구지!\n\n나더러 자네를 보게 되면 이걸 전해 달라고 하고는 곧바로 다시 남쪽으로 늪지를 향해 가 버렸어.", rewards = "다음과 같은 것들을 받습니다:\n\n인내의 비약"},
[1271] = {title = "고독한 은둔자 선술집에서의 잔치", objective = "제 조카 말이, 당신이 먼지진흙 습지대에서 조카의 요리 연구를 도왔다고 하더군요. 또 조카의 동료들을 힘든 상황에서 구해 내 주셨다고요? 음, 우리 스턴 가문은 결속력이 대단합니다. 그리고 결코 우릴 도와준 친구를 푸대접하는 일이 없지요!\n\n그래서 당신을 위한 잔치를 준비했으니 와서 손을 씻고 마음껏 즐기시기 바랍니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n물수건"},
[1273] = {title = "리테 심문", objective = "오그론과 함께 가서 리테를 심문한 다음 담쟁이 마을에 있는 크로그에게 돌아가야 합니다.", description = "시간은 오래 걸렸지만 리테를 찾아냈다. 인간치고는 잘 숨어 다니더군.\n\n이 오그론은 늪지에 그렇게 오래 머물다 미쳐 버리게 될까 봐 걱정했다고. 당신 나랑 같이 그 녀석을 심문하러 가자.", progress = nil, completion = "흠, 더 이상 리테 녀석이 늪지 주변을 어슬렁거리지 않게 된 건 다행이지만, 인간이란 게 화살에 맞은 작은 부상 하나 극복하지 못할 정도로 나약한 존재라니...\n\n이번 단서로는 이번 사건의 실마리를 찾지 못했으니 다른 단서를 찾아보는 수밖에 없겠군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n눈송곳돌풍 나팔총\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1274] = {title = "실종된 사신", objective = "스톰윈드 성에서 주교 드라베이를 찾아야 합니다.", description = "실례합니다. 드라베이 주교님께서 제게 까다로운 일을 도와줄 수 있을 만한 모험가를 찾아보라고 말씀하셨어요.\n\n괜찮으시면 가능한 한 빠르고 조용히 스톰윈드 성으로 가셔서 그분을 만나 보세요. 여행자분께서 도와주신다면 주교님이 정말 고마워하실 겁니다. 다시 한번 말씀드리지만 중요한 일이니 신중하셔야 해요.", progress = nil, completion = "어서 오시오. 나는 주교 드라베이라 하오.\n\n이 성에서 내가 하고 있는 일에 대해 묻는 걸 보니 귀여운 토마스가 형제에게 우리 왕국을 도와 달라고 부탁하는 데 성공했나 보군. 그 아이는 언제나 내 말을 잘 따르는 착한 아이라오.\n\n자세히 설명할 시간이 없으니 무례를 범하는 걸 이해해 주시오... 그리고 이 일은 절대로 발설해서는 안 되는 것이니 명심하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1275] = {title = "타락에 대한 연구", objective = "아우버다인에 있는 게르샬라 나이트위스퍼가 변이된 뇌간 8개를 가져다 달라고 부탁했습니다.", description = "바보 같은 블러드 엘프들이 악마의 마법을 써 대다니... 칼림도어에서 사티로스와 나가들에게 어떤 일이 일어났는지 보지 못했단 말인가?\n\n블러드 엘프들도 그처럼 기형으로 변해 버릴까 걱정스럽소. 아제로스에 더 이상 사악한 종족이 태어나선 안 되오.\n\n블러드 엘프들의 운명이 앞으로 어떻게 될지 추론해 볼 수 있도록 사티로스와 나가의 뇌간을 연구해 보고 싶소. 잿빛 골짜기 해안에 있는 검은심연의 나락에서 사티로스와 나가를 모두 찾을 수 있을 거요.\n\n아주 먼 길이 될 것이오.", progress = "일단 표본을 충분히 확보하면 연구를 시작할 수 있을 것이오. 검은심연의 나락에 있는 사티로스와 나가의 변이된 뇌간을 손에 넣게 되면 돌연 변이 간의 상호 관계에 대한 결론을 내려 볼 셈이오.\n\n새롭게 얻은 그 지식으로 어쩌면 블러드 엘프들이 기형과 악의 길에 더 깊이 빠지는 것을 막을 수 있을지도 모르겠소.", completion = "멀리까지 가서 분명 큰 위험에도 처했을 거요.\n\n당신의 행동은 아주 헌신적이었소. 내 연구를 도와주는 것은 아제로스 전체의 이익을 위한 일이오. 많은 수고를 해주어서 고맙소.\n\n자, 이제 나는 해야 할 일이 많이 있으니 이만 실례하겠소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n딱정벌레 팔보호구고위성직자의 단망토\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1276] = {title = "검은 방패", objective = "썬더 블러프에 있는 모사른에게 타락의 철제 방패를 보여 주십시오.", description = "아, 이제 기억나는군! 모사른은 썬더 블러프에서 존경 받는 대장장이요. 전에 어디에선가 그의 이름을 들은 기억이 있다 했어.\n\n영광스럽게도 나는 속세의 고리회의 이름으로 모사른이 만든 갑옷을 얻을 수 있었지. 그건 정말 잘 만들어진 갑옷이었소.\n\n그가 만든 방패에 대해서는 그에게 직접 듣는 편이 나을 거요.\n\n큰 단서는 아니지만 리테에게서 별다른 걸 알아내지 못했으니 이제 이것이 우리가 가진 유일한 단서요.", progress = "안녕하신가, <class>. 내가 도울 일이라도 있나?", completion = "그렇네, 자네 말이 맞아. 이 방패는 내가 만든 걸세.\n\n하지만 내가 해줄 수 있는 얘기가 별로 없군. 난 워낙 다양하고 많은 방패와 갑옷을 만들다 보니 일일이 다 기억할 수가 없어서 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1281] = {title = "짐의 노래", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1282] = {title = "유쾌한 짐이라 불리는 사나이", objective = "테라모어에 있는 사령관 개런 바임스와 대화해야 합니다.", description = "저 늙은 짐만 생각하면 불쌍해서 견딜 수가 없습니다. 예전엔 저런 모습이 아니었는데... 그는 한동안 습지에 있는 여관을 운영했었는데 정말 훌륭한 여관이었습니다.\n\n흠, 그에 대해서는 더 이상 얘기하고 싶지 않습니다. 정 원한다면 바임스 사령관님께 가 보시기 바랍니다.", progress = nil, completion = "그의 진짜 이름은 제임스 하이얄일세. 그는 불모의 땅 변두리에 여관을 열었지. 여행자들이 쉬어 갈 수 있는 멋진 곳으로 만들기를 원하면서 말일세.\n\n아마 그의 꿈이 너무 컸던 것 같지만 한동안 그 여관은 정말 잘됐었지. 그런데 우리가 습지의 도로를 오우거들에게 내주고 만 것일세.\n\n하지만 고집이 센 제임스는 꿈을 포기하고 성 안으로 안전하게 피신하려 하지 않았지. 결국 그늘 쉼터 여관은 잿더미가 되고 말았네. 지금 조사 중이긴 하지만 아직 별로 알아낸 게 없다네. 우릴 도와줄 생각이 있다면 불타고 남은 잔해에 뭔가 단서가 있는지 찾아봐 주게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1283] = {title = "그늘 쉼터 여관 화재 사건", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1284] = {title = "수상한 발굽 자국", objective = "테라모어에 있는 사령관 개런 바임스에게 그늘 쉼터 여관의 수상한 흔적에 대해 보고해야 합니다.", description = "아직도 연기가 피어나는, 잔해만 남은 그늘 쉼터 여관에서 나와 이어져 있는 발굽 자국이 있습니다. 최소한 몇 개는 눈으로 확인이 가능하지만 다른 자국들은 습지의 부드러운 흙에 묻혀 알아보기 어렵습니다.", progress = nil, completion = "발굽 자국이라고? 먼지진흙 습지대 주변 지역에서 켄타우로스의 활동이 심상치 않은 것이 사실이네. 불모의 땅에서의 짧은 원정 중에 우리는 켄타우로스의 야영지와 소유지가 지역 곳곳에 산재해 있는 걸 발견했다네.\n\n우리 수색병 중에 팰그런 해스틸이라는 자를 보내 그 흔적이 어디로 연결되는지 알아보도록 하겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1285] = {title = "대린의 부하", objective = "테라모어에 있는 사령관 개런 바임스에게 돌아가 리테에 대한 정보를 전해야 합니다.", description = "레드돈... 레드패스... 아, 여기 있군! 부관 파발 리테.\n\n프라우드무어님과 함께 바다를 건너온 대부분의 신병들과 함께 테라모어 경비병으로 지원했소이다. 16세 때 쿨 티라스의 해병대에 입대했고... 뛰어난 전과와 진급...\n\n실종된 것으로 기록되어 있소.", progress = nil, completion = "실종이라고? 테소렌은 배반자를 그렇게 표현하는가보군.\n\n그가 총사령관 대린에게 맹목적인 충성을 바치다 배반자로 전락한 저 바보 같은 자들 중 하나라는 사실은 분명하네. 참으로 기막힌 아이러니가 아닌가? 탈영병들이 우리더러 얼라이언스를 배반했다고 뒤집어 씌우다니 말일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1286] = {title = "탈영병", objective = "먼지진흙 습지대에 있는 밸로스 제킨과 탈영병들로부터 리테에 대한 정보를 알아내야 합니다.", description = "습지에 주둔하여 군대를 유지하는 건 힘든 일이지만 우리의 불굴의 의지로 지역 내에 방어를 위한 몇 개의 감시탑을 만들어 유지해 올 수 있었네.\n\n최신 정보와 정찰 보고에 따르면 탈영병 무리가 여관 남동쪽의 버려진 경비탑에 숨어든 것 같네.\n\n탈영병의 우두머리는 제킨이라는 자일세. 그에게서 정보를 캐내 보도록 하게.\n\n그는 만만한 상대가 아닐 테니 조심하게.", progress = nil, completion = "바임스가 보낸 자인가? 그자는 자신의 일도 직접 나서서 하지 못하나 보군, 흥...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1287] = {title = "탈영병", objective = "테라모어에 있는 사령관 개런 바임스와 리테에 대해 대화해야 합니다.", description = "리테? 그 겁쟁이 말인가?\n\n자꾸 담쟁이 마을에서 오우거의 보급품을 약탈하자고 해서 야영지에서 내쫓아 버렸어. 우리는 그런 생각 없는 망나니들을 상대할 만큼 여유롭지 않으니까 말이야.\n\n넘어서는 안 될 선을 너무 많이 넘은 놈이었지. 그래서 혼자 살아가도록 내버려뒀어.\n\n내가 당신을 도와주었으니 이제 당신이 우릴 도와주면 어떨까? 뭐, 갑자기 당신이 불쑥 들이닥친 건 피차 잊어버리고 말이야...", progress = nil, completion = "내 부관 칼드웰을 보내 버려진 경비탑에 있는 탈영병들을 처리하도록 하겠네. 또한 그에게 리테를 찾으라고 일러두지. 습지는 그다지 넓지도 않고 발자국도 잘 남으니까 그를 찾는 건 별로 어렵지 않을 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1301] = {title = "제임스 하이얄", objective = "메네실 항구에 있는 빈센트 하이얄과 대화해야 합니다.", description = "이곳 고독한 은둔자 선술집에서 일하기 전에 전 지금까지 만나 본 중에 가장 뛰어난 요리사이자 여관 주인이었던 분에게서 교육을 받았죠. 제임스 하이얄이라는 분인데, 일생 동안 제가 가진 것, 지위는 모두 그분 덕분이라 할 수 있습니다.\n\n잘 지내고 계시는지 궁금하네요. 그분의 형제인 빈센트와 함께 선술집에서 일하시기 위해 메네실 항구로 가셨는데 한동안 소식을 듣지 못했습니다.\n\n혹시 그쪽으로 가시게 되면 그분께 제 안부를 좀 전해 주시겠습니까?", progress = nil, completion = "제임스? 아, 제임스는 오래전에 떠났는데...\n\n아마 그놈의 애국심이 다시 발동했던 게지요. 그가 그러는 것도 이해할만합니다. 로데론은 온통 제정신이 아니었으니까 말입니다. 수많은 사람이 제이나 프라우드무어님이 바다를 건너 항해하는데 따라나섰답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1302] = {title = "제임스 하이얄", objective = "테라모어에 있는 서기관 렌드리와 대화해야 합니다.", description = "내 동생 제임스가 프라우드무어님과 함께 바다를 건너갔습니다. 내가 마지막으로 들은 건 그곳에서 전투가 끝나 제임스가 어딘가에서 여관을 열었다는 소식이었지요. 그 녀석은 어디에 있든 잘해낼 겁니다. 정말 요리 하나는 끝내주게 잘하거든요.\n\n그러고 보니 소식을 들은 지도 꽤 됐는데... 아마 여관 일이 너무 바쁜가 봅니다만 테라모어의 서기관에게 가면 틀림없이 그가 어디에 있는지 알려줄 겁니다.", progress = nil, completion = "제임스 하이얄, 제임스 하이얄... 왜 그 이름이 이렇게 낯이 익지?\n\n아, 그렇지! 그늘 쉼터 여관 사건! 거기서 무슨 일이 일어났었는지 조금이라도 알고 있다면 바임스 사령관님을 만나 얘기해 보는 게 좋을 것 같습니다. 그분께서 조사를 맡고 계시니 말입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1318] = {title = "고르독 일 마무리", objective = "권력의 고르독 건틀릿을 찾아 혈투의 전장에 있는 대장 크롬크러쉬에게 가져가야 합니다.\n\n크롬크러쉬의 \"옛날 얘기\"에 따르면 자칭 왕자라는 토르텔드린이라는 이름의 \"기분 나쁜\" 엘프가 고르독 왕에게서 빼앗아갔다고 합니다.", description = "이제 당신 새 왕이다, 토르텔드린이라고 하는 기분 나쁜 엘프에게서 소중한 고르독 유물 빼앗아줘! 이전 왕은 실패했고, 토르텔드린이 아주 오래 전 왕에게서 유물 훔쳐간 뒤로 다른 임금들 다 실패했다!\n\n그 유물은 권력의 고르독 건틀릿이라고 한다. 옛날 얘기에는 진짜 고르독 왕만이 갖고 올 수 있다고 한다. 옛날 얘기에는 기분 나쁜 엘프가 아직도 이 근처에 있다고 한다. 그 유물 찾으면 평생 왕이 끼고 있게 될 거다! 그래, 내가 보여준다!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n고르독의 손보호대고르독의 건틀릿고르독의 장갑고르독의 손장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1319] = {title = "검은 방패", objective = "테라모어에 있는 카즈 투스프로켓에게 타락의 철제 방패를 보여줘야 합니다.", description = "크게 도움을 주지 못해 미안하네. 내 도움이 될 만한 이를 알려 주도록 하지. 이곳에서 가장 뛰어난 대장장이 중에 카즈 투스프로켓이라고 하는 자가 있는데, 가열로 근처에서 일하고 있네.\n\n그에게 그 방패를 가져가 보도록 하게. 그 친구라면 뭔가 알고 있을 걸세.", progress = "내게 보여 줄 거라도 있나요?", completion = "흠... 이것 참 흥미로운 물건이군요. 분명 내가 아는 한 이 대륙의 대장장이가 만든 물건은 아니네요. 아, 물론 내가 만든 것도 아니고요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1320] = {title = "검은 방패", objective = "테라모어에 있는 사령관 개런 바임스와 대화해야 합니다.", description = "아, 잊어버릴 뻔했는데 말이죠... 분명 뒤에 달린 가죽끈은 불에 타 없어졌겠지만, 몸집이 큰 친구에 맞게 만들어진 것 같네요. 아마 타우렌들이 사용하던 게 아닌가 싶은데...\n\n내가 말해 줄 수 있는 건 그게 다에요. 바임스 사령관님께는 큰 도움이 못 돼 죄송하다고 전해 주세요.", progress = nil, completion = "조사를 진행할 만큼 큰 정보는 아니지만 기억은 해둬야 할 것 같군. 이 사건에 대한 다른 단서들이 드러나서 대체 무슨 일이 있었는지 좀 더 확실히 알 수 있게 되면 좋으련만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1321] = {title = "검은 방패", objective = "담쟁이 마을에 있는 도골에게 타락의 철제 방패를 보여 주십시오.", description = "흠... 이 방패에 이상한 점은 없는 것 같은데... 대장장이 도골에게 가져가서 이에 대해 뭔가 아는 바가 있는지 알아봐야 할 것 같군. 특별한 기대는 하지 않는 게 좋겠지만 말이야.", progress = "볼일이 있나, <class>?", completion = "좋은 방패다. 아주 단단하고, 무겁고, 좋다. 하지만 이 도골에게는 필요 없다. 난 방패를 만들기만 할 뿐, 사지는 않으니까.\n\n그걸 알아야지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1322] = {title = "검은 방패", objective = "담쟁이 마을에 있는 도골을 위해 산성 독주머니 6개를 구해야 합니다.", description = "흐음, 바로 여기 방패 테두리에 글자가 새겨져 있지만 불에 타서 읽기가 어렵다.\n\n방패를 닦아낼 산성 용액이 필요하다. 습지에 사는 검은송곳니 독주머니를 사용하면 될 거다. 녀석들의 독주머니를 구해 오면 방패를 깨끗이 닦아낼 수 있을 거다.", progress = "거미의 독주머니는 구해 왔나?", completion = "난 밟아 죽일 수 없을 정도로 큰 거미는 정말 싫다.\n\n독주머니를 구해다 줘서 고맙다. 이제 독주머니를 열고 방패 위에 붓도록 하지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1323] = {title = "검은 방패", objective = "담쟁이 마을에 있는 크로그와 대화해야 합니다.", description = "오, 방패에 산성 독액을 너무 많이 떨어뜨린 것 같은데... 조금 닦아내 봐야겠다...\n\n흠, 읽기 어렵긴 하지만, 모사른이라는 이름 같군. 그런 이름은 들어 본 적이 없는데... 아마 크로그가 알 거다. 크로그는 아는 사람이 많으니까.", progress = nil, completion = "모사른? 많이 들어 본 이름 같은데... 지금은 잘 기억이 나질 않는군. 나중에 생각날지도 모르지.\n\n아마 별로 중요한 이름은 아닐 것이오. 방패야 어딜 가나 흔하고 별로 중요하지 않은 물건이니까...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1324] = {title = "실종된 사신", objective = "먼지진흙 습지대에 있는 병사 헨델과 싸워서 이겨야 합니다.", description = "뭐라고?! 내가 데피아즈단과 손잡았다는 걸 밝혀내려고 여기까지 왔다고? 당신은 내가 이런 모욕을 당하고도 가만히 있을 거라 생각하는 거요? 참을 수가 없군! 아무리 생각해도 당신은 진작에 죽어야 했어!", progress = nil, completion = "우리 모두 현재 일어나고 있는 일련의 사건들 때문에 심기가 불편한 것은 사실입니다. 하지만 우리가 그를 테라모어로 데려가 몇 가지 조사하고 왕을 찾아볼 수 있도록 우리의 뜻을 따라 주시기 바랍니다.\n\n프라우드무어님께서도 틀림없이 당신의 도움에 고마워하실 것입니다. 언제 시간이 나거든 프라우드무어님을 만나 얘기해 보도록 하십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1338] = {title = "스톰파이크의 주문서", objective = "스톰윈드에 있는 푸렌 롱비어드에게 스톰파이크의 주문서를 가져가야 합니다.", description = "내가 아주 존경하는 드워프 방어구 제작자가 한 명 있소. 푸렌 롱비어드라고 하는데, 그의 기술은 타의 추종을 불허하지. 난 그가 만든 새 방패를 원한다오!\n\n그런데 문제는... 그가 남쪽으로 멀리 떨어져 있는 스톰윈드 내의 드워프 지구에 살고 있다는 거요. 인간의 땅에 말이오! 그가 왜 아이언포지에서 그렇게 멀리 떨어진 곳에 사는지 도무지 모르겠소. 필시 그곳 인간들이 그를 잡아두기 위해 거액을 쏟아 붓고 있겠지!\n\n여행도 하고 돈도 벌 생각이 있다면 푸렌 씨를 찾아가 내 방패를 좀 주문해 주겠소?", progress = "드워프의 땅에서 온 편지라고 했나? 그 먼 북쪽 땅에서 누가 날 찾는 건지 궁금하군...\n\n어디 주문서를 한번 보세.", completion = "아, 스톰파이크 일가 중 한 명이 보낸 주문서로군그래. 스톰파이크 집안은 뛰어난 드워프들을 많이 배출한 훌륭한 집안이지. 부자들이기도 하고...\n\n고맙네. 오늘 내로 산악경비대 스톰파이크에게 줄 방패를 만들어야겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1339] = {title = "산악경비대 스톰파이크의 임무", objective = "산악경비대 스톰파이크와 대화하십시오.", description = "산악경비대 스톰파이크가 심부름꾼을 찾고 있다고 들었소. 그를 위해 잠시 여행을 다녀올 자를 말이지. 어떻소? 당신이야말로 이 일에 적격이라고 생각하는데...\n\n북쪽 경비탑 꼭대기로 가서 스톰파이크를 만나 보시오.", progress = nil, completion = "그렇소. 내가 경비 임무를 수행하는 동안 누군가 내 대신 해줘야 할 일이 있소. 모단 호수를 떠나 멀리까지 가야 하는 일이오.\n\n모험을 즐길 절호의 기회지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1358] = {title = "헬브림에게 가져갈 견본", objective = "불모의 땅에 있는 연금술사 헬브림에게 늑대 심장 견본을 가져가야 합니다.", description = "칼림도어에 있는 동료인 연금술사 헬브림은 로데론 독소가 칼림도어의 야수들에게 미치는 영향을 연구하고 있어요. 렌퍼럴이 내게 보내준 늑대 심장 견본에 큰 관심을 보일 거예요.\n\n헬브림은 불모의 땅의 크로스로드라는 마을에서 지내고 있답니다. 그에게 가려면 비행선을 타고 오크족 수도인 오그리마까지 간 다음 남쪽으로 듀로타까지 걸어 가야 해요. 그곳에서 서쪽으로 가면 불모의 땅인데 곧 크로스로드에 도착하게 될 거예요.", progress = "내게 전할 물건이라도 있나?", completion = "아, 아주 잘 됐군. 초기 보고서 내용이 정말이라면 이 심장의 독성은 독에 대한 우리의 지식을 더욱 발전시켜 줄 거야.\n\n아주 반가운 물건을 가져왔군그래. 자네는 이런 보상을 받을 자격이 충분해.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n양조장이 장갑긴주름 단망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1359] = {title = "진게의 소포", objective = "언더시티에 있는 연금술사 진게에게 늑대 심장 견본을 가져가야 합니다.", description = "자네가 가져온 이 늑대 심장들은 다른 비슷한 견본들에서는 보지 못한 성질을 갖고 있네. 이 심장에는 심장이 뛰고 있는 늑대 자신에게 치명적인 영향을 미치는 독성이 있어!\n\n정말 놀라운 일이야. 반드시 더 연구해 봐야겠어. 자네가 가져온 심장 중 몇 개는 내가 견본으로 갖고 있네. 그것들을 내 동료인 연금술사 진게에게 가져다주게. 언더시티에 있는 우리 본부에서 진게를 만날 수 있을 걸세.", progress = "어서 오세요. 내게 전할 것이 있나요?", completion = "아, 렌퍼럴이 말하던 바로 그 심장 견본이로군요. 어서 이걸로 실험을 해보고 싶군요... 새로운 형태의 독소를 발견하는 것은 언제나 왕립 연금술 학회에서 관심을 갖는 일이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1360] = {title = "보물 찾기", objective = "울다만의 북쪽 대전당에 있는 궤짝에서 크롬 스타우트암의 보물을 찾아서 아이언포지에 있는 크롬 스타우트암에게 가져다주어야 합니다.", description = "한때 나는 황야의 땅에 있는 울다만 발굴 현장에서 꽤 이름난 채굴꾼으로 일했지... 그 몹쓸 트로그놈들이 나타나기 전까지는 말이오. 난리통에 겨우 목숨만 건져서 나오는 바람에 가장 아끼는 물건을 그만 두고 왔지 뭐요! 그 물건은 놈들이 우글대는 곳에 있소! 단단히 잠긴 궤짝 안에 있어서 트로그 놈들, 아직 보물 구경도 못했을 거야...\n\n그걸 찾아와 준다면 당신에게 큰 빚을 지는 거지! 북쪽 대전당의 끝에 가면 내 이름이 적힌 궤짝이 있는데 그 속에 보물이 들어 있소.", progress = "궤짝에 든 내 보물은? 트로그놈들은 상대할 만했소?", completion = "아, 이제야 진정한 내 모습을 찾은 것 같군. 정말로 고맙소.\n\n어떤 드워프는 빛나는 금속을 좋아하고 어떤 드워프는 빛나는 보석을 사랑하지만, 이 술잔이 손에 없으면 나 스타우트암은 스타우트암이 아니라오!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1361] = {title = "렉타르 데스게이트", objective = "렉타르 데스게이트와 대화해야 합니다.", description = "명예로운 호드의 전사인 렉타르 데스게이트가 잊혀진 땅에서 임무를 수행할 대원을 모집하고 있소. 그는 불모의 땅에 있는 크로스로드의 서쪽 언덕 감시탑 아래에 있소.\n\n잊혀진 땅은 전쟁으로 고통받고 있는 곳이니 준비를 단단히 해 가도록 하시오.", progress = nil, completion = "그렇네. 난 대원을 모집하고 있지. 이번 임무는 잊혀진 땅에서 켄타우로스를 상대하는 것일세. 빨리 임무를 시작할 수 있도록 간단히 설명하도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1362] = {title = "잊혀진 땅의 콜카르", objective = "잊혀진 땅의 침묵의 초소에 있는 펠굴 투커츠와 대화해야 합니다.", description = "콜카르 켄타우로스는 잊혀진 땅에 살고 있으며 그들의 군대는 불모의 땅 전역에 퍼져 있네. 이 때문에 우리 호드 대원들이 놈들을 상대하고 있는 것이지.\n\n하지만 잊혀진 땅에서 켄타우로스가 힘을 행사하는 이상, 놈들은 항상 위협적인 존재가 될 것이야. 이제 그 위협을 제거할 때가 되었네.\n\n잊혀진 땅의 침묵의 초소에 있는 펠굴 투커츠를 만나 보게. 그는 켄타우로스에 대한 정보를 수집하기 위해 파견되었으니 잊혀진 땅의 콜카르를 처리할 최선의 방법을 알고 있을 거야.", progress = nil, completion = "렉타르의 명령으로 이곳에 온 거요? 그렇다면 켄타우로스를 상대하러 온 거겠군. 좋아.\n\n충분히 휴식을 취했길 바라오. 켄타우로스에 대한 우리 작전의 결과가 어떨지는 모르겠지만, 긴 싸움이 될 것이오.\n\n자, 앉아서 내 말을 들어 보시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1363] = {title = "마젠의 부탁", objective = "스톰윈드에 있는 수행사제 델리스와 대화해야 합니다.", description = "이곳 비전술 학회의 도서관 관리인으로서, 모든 마법 서적과 두루마리들을 항상 잘 관리하는 것이 내 임무요. 이 마법 문서 중 일부가 나쁜 자들 손에 들어가는 어리석은 일이 일어나지 말란 법도 없잖소?\n\n내 조수 델리스가 지난주에 저지른 끔찍한 실수가 다시 떠오르는군... 그는 도서관 일은 꽤 잘해내고 있지만 스톰윈드 성문 밖으로만 나가면 무능해져 버린다오. 당신이 델리스를 돕는 영웅이 되어 주지 않으시겠소?", progress = nil, completion = "그건 내 잘못이 아니었어요. 정말입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1364] = {title = "마젠의 부탁", objective = "차원의 집합점에 대한 카드가의 평론을 찾아 네더가드 요새에 있는 감시자 마할 바에게 전해야 합니다.", description = "마젠님의 지시는 아주 분명했습니다. 네더가드 요새에 있는 감시자 마할 바에게 중요한 문서를 전달하라는 것이었지요.\n\n하지만 저는 저주받은 땅에 가 본 적이 한 번도 없었다고요! 여행은 아주 끔찍했죠.\n\n슬픔의 늪에서 길을 잘못 드는 바람에 식물처럼 생긴 무시무시한 괴물들에게 둘러싸였었거든요. 절 공격할 것처럼 다가오기에 도망쳤어요. 그렇게 서두르다가 문서를 떨어뜨렸죠. 분명히 그 괴물 중 하나가 집어 갔을 겁니다.\n\n문서를 되찾아서 마할 바에게 전해 주시지 않겠어요?", progress = "네더가드 요새에는 무슨 용건으로 온 겁니까?", completion = "아, 아주 잘 됐군!\n\n한동안 비전술 학회의 마젠이 차원의 집합점에 대한 카드가의 평론을 보내 달라는 내 요구를 잊어 버린 게 아닌가 걱정했었습니다.\n\n여러 가지 이상한 일들이 벌어지고 있어 마젠도 여러 가지 요청에 시달리는 것 같군요.\n\n자, 나는 지금 바로 연구를 시작해야 하니 이만 실례하겠습니다. 드디어 카드가 같이 위대한 분의 평론을 공부하게 되다니 정말로 흥분이 되는군요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n교사의 장식띠방랑의 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1365] = {title = "칸 데즈헤파", objective = "칸 데즈헤파를 처치하고 그 증거로 그의 머리카락을 잊혀진 땅에 있는 펠굴 투커츠에게 가져가야 합니다.", description = "잊혀진 땅엔 콜카르일족 켄타우로스만 있는 게 아니오. 수많은 부족이 이 메마른 평원을 누비고 다니며 서로 싸우고 죽이곤 하지. 워낙 강하고 거친 녀석들이라 자기들끼리 싸우는 게 천만다행이라오. 만약 녀석들이 손을 잡고 우리를 공격한다면 아주 끔찍한 적이 될 테니까 말이야. 녀석들이 뭉치기 전에 손봐 놓아야만 하오.\n\n당신이 해줘야 할 첫 번째 임무는 콜카르일족을 분열시키는 것이오. 그러려면 녀석들의 우두머리인 칸 데즈헤파를 처치하면 될 것이오.\n\n콜카르 마을은 여기서 북동쪽에 있으니 어서 가시오. 행운을 빌겠소.", progress = "칸 데즈헤파는 해치웠소?", completion = "잘했군. 당신이 보여준 재빠른 행동은 콜카르에게 우리의 힘을 보여주기에 충분했소. 켄타우로스는 힘으로 얘기해야 제일 잘 알아들어서 말이야.\n\n콜카르 지도자를 처치했으니 일족이 분열되는 건 물론이고 다른 이들에게 휴식을 취할 시간을 주게 될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1366] = {title = "켄타우로스 현상금", objective = "잊혀진 땅의 펠굴 투커츠에게 켄타우로스의 귀걸이 15개를 가져가야 합니다.", description = "켄타우로스 부족들에게 공포감은 충분히 심어 주었으니 이제는 녀석들에게 우리의 힘을 보여 줄 차례군. 잊혀진 땅을 여행하는 동안 켄타우로스를 사냥해 주시오. 어느 부족을 사냥하든 상관없으니 녀석들에게서 귀걸이를 가져 오시오.\n\n녀석들의 수를 줄여서 기를 꺾어 놓으면 영토 확장은 꿈도 꾸지 못하게 될 거요. 그럼 즐거운 사냥이 되길 빌겠소.", progress = "귀걸이 모으는 건 잘 되어가오? 많이 모았소?", completion = "이제는 켄타우로스 사이에 당신 이름이 잘 알려졌을 거요. 당신을 두려워하며 우러러볼 것이오. 그리고 당신이 호드를 위해 일하는 영예로운 자라는 것도 알고 있을 거요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n라일락 장식띠죔쇠 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1367] = {title = "마그람 동맹", objective = "마그람에게서 우호적인 평판을 얻은 다음 와루그와 대화해야 합니다.", description = "켄타우로스를 물리치려면 반드시 서로에 대한 증오를 이용해야 합니다. 우리는 그들 부족 중 하나와 동맹을 맺은 후에 그들을 통해 모든 부족을 물리칠 수 있는 방법을 알아내려고 합니다.\n\n마그람과 동맹을 얻으려면 그들의 숙적인 겔키스들을 처치해야 합니다. 마그람의 신뢰를 쌓은 후에 잊혀진 땅 남동쪽의 마그람 마을 외곽에 있는 마그람 대변인 와루그를 만나 보도록 하십시오.", progress = nil, completion = "이제 겔키스 놈들은 네 이름만 들어도 벌벌 떨고 있어. 너를 두려워하고, 또 증오하지. 놈들이 우리 마그람을 증오하는 것처럼 말이야!\n\n넌 우리 마그람처럼 강할지도 모르겠군. 두고 보도록 하지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1368] = {title = "겔키스 동맹", objective = "겔키스에게서 우호적인 평판을 얻은 다음 현자 우텍과 대화해야 합니다.", description = "켄타우로스를 물리치려면 반드시 서로에 대한 증오를 이용해야 합니다. 우리는 그들 부족 중 하나와 동맹을 맺은 후에 그들을 통해 모든 부족을 물리칠 수 있는 방법을 알아내려고 합니다.\n\n겔키스와 동맹을 맺으려면 그들의 숙적인 마그람을 처치해야 합니다. 겔키스의 신임을 얻은 후에 잊혀진 땅 남서쪽의 겔키스 마을 외곽에 있는 겔키스 주술사인 현자 우텍을 만나 보도록 하십시오.", progress = nil, completion = "땅이 네가 다수의 마그람을 처치했다고 말해주는군. 좋아.\n\n네가 겔키스의 친구라면 잘 듣도록 해. 네게 맡길 임무가 더 있으니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1369] = {title = "눈물의 파편", objective = "마그람에게 우호적인 평판을 유지하면서 마그람 마을에 있는 와루그에게 눈물의 파편 3개를 가져가야 합니다.", description = "겔키스들은 우리 켄타우로스 어머니, 테라드라스님께서 우릴 지켜 주신다고 생각하지. 놈들은 멍청이들이야. 누구도 켄타우로스를 지켜 주지 않아. 그리고 마그람은 보호 같은 건 필요 없다고! 우린 가장 강한 부족이니까!\n\n겔키스들에게 그 어리석음을 일깨워 주도록 해. 놈들 마을에 있는 동굴로 가. 놈들이 모아 둔 수정, 테라드라스의 눈물이 그 동굴에 있지. 테라드라스의 눈물을 파괴한 다음 부서진 조각들을 내게 가져와.", progress = "네가 우리의 적이 아니라면 내가 부탁한 일을 해 주겠지!", completion = "눈물을 가져왔군! 이제 겔키스들이 테라드라스님께서 그들을 돕지 않는다는 사실을 알게 되겠지. 우리가 놈들을 처치할 때 테라드라스님께서는 눈물을 흘리지 않을 거야. 마그람의 세상이 올 거라고!\n\n우릴 돕는 건 현명한 일이야. 우리가 제일 강하니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1370] = {title = "보급품 훔치기", objective = "겔키스 마을에 있는 현자 우텍에게 말린 고기 6개를 가져가야 합니다.", description = "우리가 전쟁을 치르지 않을 때는 고기를 얻기 위해 사냥을 하지. 고기는 우리에게 힘을 주고 배가 든든해야 잘 싸울 수 있는 법이니까 말이야.\n\n마그람도 마찬가지야. 놈들은 사냥하지 않고도 오래전쟁을 치를 수 있도록 여분의 고기를 저장해 두고 있지. 네가 동쪽에 놈들 마을을 습격해서 저장되어 있는 고기를 빼앗는다면 놈들은 힘을 잃게 될 거야.", progress = "네가 겔키스에 충분히 도움이 된다는 것을 더 잘 증명하고 난 후에 돌아오도록 해!", completion = "좋아. 저 멀리 놈들의 마을에서 마그람들의 배가 꼬르륵대는 소리가 크게 들리는군그래!\n\n이 고기는 우리 겔키스들에게 주도록 하지. 그러면 쉬지 않고 오래 싸울 수 있을 거야.\n\n겔키스를 위해 좋은 일을 해 주었군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n은색 표창깃 달린 화살폭발 탄환\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1371] = {title = "와루그의 물건", objective = "마그람에게 우호적인 평판을 유지하면서 잊혀진 땅의 마그람 마을에 있는 와루그에게 고급 표적 허수아비를 가져가야 합니다.", description = "오래전에 작은 노움 녀석이 잊혀진 땅으로 왔었지. 그 녀석은 말과 마차가 있었고 마차에는 처음 보는 물건들이 실려 있었어. 괴상한 것들 말이야. 여러 가지 색깔로 불에 탄 물건들, 움직이지만 살아 있지는 않은 것들, 난 그 작은 노움 녀석을 처치해 버렸는데... 그 전에 그 녀석이 나를 웃게 했어.\n\n녀석의 마차에서 가장 마음에 드는 물건 하나를 내가 가졌지. 나무로 만든 인간이었는데 내가 때려 부수기 전까지 계속 나에게 손을 흔들었어.\n\n그게 새로 하나 더 있었으면 좋겠어. 새로 하나 구해다 줘!", progress = "네가 우리의 적이 아니라면 내가 부탁한 일을 해 주겠지!", completion = "그래, 바로 이거야! 이걸 다시 움직이도록 만들 거야. 정말 재미있거든!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1372] = {title = "진실의 물약", objective = "부랑자 소굴에 있는 연금술사 파우스틴과 대화해야 합니다.", description = "우리 원정 부대는 바리마트라스님의 명령으로 아제로스 저지대를 조사하기 위해 파견되었네.\n\n정찰 중에 나는 인간 첩보원이 부랑자 소굴을 염탐하고 있는 것을 발견했지. 내가 녀석을 잡기도 전에 우리 오크 형제 중 한 명이 그를 스토나드의 슬픔의 늪에 있는 요새로 끌고 갔네.\n\n우리의 오크 동맹군을... 돕고... 싶다네. 그들은 이곳에 우리가 야영하고 있는 것을 보지 못했지만 어쨌든 그들을 돕고 싶네.\n\n이곳에 있는 파우스틴을 도와 스토나드의 우리 친구들을 위해... 그... 진실의 물약을 만들도록 하게.", progress = nil, completion = "당신이 도착하기 조금 전에 즈레더스에게 성가신 첩보원에 대해 들었는데 말이야.\n\n정말 골칫거리가 아닐 수 없군. 부랑자 소굴 주변을 기웃거리는 참견꾼은 정말 필요 없는데 말이지.\n\n스토나드의 오크들은 꼭 놈에게서 자백을 듣고 싶어할 거요. 그들은 우리 동맹이니, 에헴, 그 인간에게서 정보를 얻어내도록 도와야 하오. 나를 도와주시오. 진실의 물약을 만들어 스토나드로 보낼 거요.\n\n호드를 위하여!\n\n...내가 맞게 말한 거요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1373] = {title = "온게쿠", objective = "겔키스에게 우호적인 평판을 유지하면서 잊혀진 땅의 겔키스 마을에 있는 현자 우텍에게 드레니시스트 파편 하나를 가져가야 합니다.", description = "넌 아직 좀 더 증명해 보일 게 있어. 다음 임무를 수행하려면 먼 곳까지 가게 될 테니 당분간 겔키스는 너의 도움 없이 마그람과 싸우게 되겠지.\n\n땅은 귀를 기울여 듣는 자에게 수많은 비밀을 속삭여 주지. 내가 들은 것 중 하나는 붉은 수정에 대한 것이야. 그것은 드레니시스트라고 불리는데 이 땅에는 처음 발견되었지. 원래는 산들이 날아다니고 악마들이 지배하는 곳에서 나는 수정이지.\n\n드레니시스트 파편을 내게 가져오라고. 그러면 내 마법이 강력해질 테니! 드레니시스트 파편은 드레노어 난민 온게쿠가 차지하고 있는 슬픔의 늪이라는 곳에서 찾을 수 있을 거야.", progress = "네가 겔키스의 친구라는 것을 내게 보여줘.", completion = "그래, 이것이 땅이 내게 속삭여 말해 준 그 파편이야. 이 속에서 강한 마법이 느껴지는군! 내가 이 마법으로 겔키스의 적들을 물리치겠어.\n\n우리를 위해 또 하나의 임무를 완수해 주었군. 어쩌면 곧 너를 친구라고 부르게 될지도 모르겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1374] = {title = "칸 젠", objective = "칸 젠을 처치하고 그 증거로 그의 머리띠를 잊혀진 땅의 겔키스 마을에 있는 현자 우텍에게 가져가야 합니다.", description = "땅이 내게 말을 하고 있어. 마그람이 약해져 가고 있다는군. 지금이 바로 그들의 우두머리를 처치할 때야!\n\n마그람의 우두머리 칸 젠의 머리띠를 가져와!", progress = "네가 겔키스의 친구라는 것을 내게 보여줘.", completion = "칸 젠은 강했지만 어리석었어. 자기 힘이 대단하다고 생각할 뿐 땅의 마법이 더 강하다는 건 알지 못했지. 이제 우두머리를 잃은 마그람 켄타우로스는 곧 쓰러질 것이고 겔키스가 지배할 날이 올 거야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1375] = {title = "칸 샤카", objective = "마그람에게 우호적인 평판을 유지하면서 칸 샤카를 처치하고 그 증거로 그의 머리띠를 잊혀진 땅의 마그람 마을에 있는 와루그에게 가져가야 합니다.", description = "넌 마그람을 돕는 자로군. 난 네가 맘에 들어. 자, 이제 겔키스의 우두머리를 처치해 줘! 칸 샤카의 머리띠를 가져오라고! 녀석의 머리띠를 손에 들고 비웃어 주고 싶단 말이다!", progress = "마그람을 위해 일해 준다면 내가 너를 도와주지.", completion = "칸 샤카가 죽었다! 녀석이 마그람의 강력함을 똑똑히 볼 수 있도록 그의 머리띠를 창 끝에 매서 항상 지니고 다니리라!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1380] = {title = "칸 흐라사", objective = "겔키스에게 우호적인 평판을 유지하면서 겔키스 마을에 있는 현자 우텍에게 마라우돈 열쇠 파편을 가져가야 합니다.", description = "넌 우리가 마그람 녀석들을 물리치는 것을 도와줬다. 이제 마라우돈일족을 물리치는 것을 도와줘. 마라우돈일족의 우두머리 칸 흐라사를 처치해!\n\n그와 맞서려면 마라우돈 전쟁 뿔피리를 불어야 해. 뿔피리는 뾰족바위 골짜기에 있는 높은 절벽 꼭대기에 있다.\n\n하지만 그 전쟁 뿔피리를 불려면 먼저 전쟁 뿔피리 파이프가 필요하지. 그것은 신임받는 마라우돈 켄타우로스들만이 지니고 있는 희귀한 물건이다.\n\n그 전쟁 뿔피리를 불면 켄타우로스들이 올 거다. 흐라사가 나타날 때까지 녀석들을 처치해.\n\n칸 흐라사에게 그... 열쇠 조각이 있어. 그 열쇠 조각을 내게 가져와라...", progress = "칸 흐라사를 처치했나? 열쇠 파편은 손에 넣었고?", completion = "녀석이 죽었군! 칸 흐라사가 죽었어! 이제 마라우돈일족도 무너지게 될 거야! 겔키스가 이 땅을 지배하는 날, 너를 반드시 기억하도록 하지. 그리고 대지의 영혼들이 언제나 너의 이름을 노래할 것이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n겔키스일족 사슬 갑옷우텍의 손가락\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1381] = {title = "칸 흐라사", objective = "마그람에게 우호적인 평판을 유지하면서 잊혀진 땅의 마그람 마을에 있는 와루그에게 마라우돈 열쇠 파편을 가져가야 합니다.", description = "겔키스의 우두머리가 죽었으니 이제 마라우돈일족을 무너뜨릴 차례로군! 마라우돈일족의 우두머리 칸 흐라사를 처치해!\n\n그와 맞서려면 뾰족바위 골짜기의 높은 절벽 위에 있는 전쟁 뿔피리를 불어야 해. 하지만 그 전쟁 뿔피리를 불려면 파이프가 필요하지. 파이프를 구하려면 마라우돈 켄타우로스를 처치해야 해. 파이프를 발견하게 될 때까지 계속 처치하라고. 찾은 다음에는 그걸로 전쟁 뿔피리를 불어.\n\n전쟁 뿔피리를 불면 탑으로 마라우돈 켄타우로스들이 올 거야. 칸 흐라사가 나타날 때까지 그들을 계속 처치해. 흐라사에게는 열쇠 조각이 있어. 이 열쇠 조각을 나에게 가져와라...", progress = "내가 얘기한 대로 하라고. 네가 마그람의 동맹이라는 것을 내게 증명해 봐!", completion = "칸 흐라사가 죽었다! 이제 마그람이 가장 강한 켄타우로스야! 나머지도 모두 처치해서 잊혀진 땅을 지배하리라!\n\n우린 너를 기억할 것이고 네가 다른 모든 것을 짓밟을 때 우리의 발굽들이 너와 함께할 것이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n마그람 사냥꾼의 허리띠의식의 켄타우로스 담요\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1382] = {title = "이상한 동맹", objective = "겔키스에게서 우호적인 평판을 얻은 다음 현자 우텍과 대화해야 합니다.", description = "켄타우로스 부족들이 자기들끼리 서로 싸운다는 것이 우리에겐 행운이 아닐 수 없소. 저들이 하나의 군대로 뭉치게 되면 아무도 막을 수 없을 테니 말이오. 그렇소, 정말 운이 좋은 거지. 그러니 반드시 그런 점을 잘 이용해야 하오.\n\n켄타우로스 부족의 하나인 겔키스일족이 마그람일족과 격렬한 전쟁을 치르고 있소. 우리가 마그람을 공격한다면 겔키스와 동맹을 맺을 수 있게 될 거요.\n\n잊혀진 땅 남서쪽의 겔키스 야영지 외곽에 있는 현자 우텍을 만나 보시오. 아마 그녀를 통해 겔키스와 동맹을 맺을 수 있을 거요.", progress = nil, completion = "겔키스들 사이에서 네 이름이 오르내리더군. 네 손으로 많은 마그람을 처치했다고? 훌륭한 일이야.\n\n너와 대화해 보는 것도 좋을 것 같군. 겔키스를 위해서 네가 해줄 수 있는 일과 우리가 너를 위해 해줄 수 있는 일에 대해서 얘기해 보자.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1383] = {title = "진실의 물약", objective = "부랑자 소굴에 있는 연금술사 파우스틴에게 흑표범 심장 5개, 우두머리 늪괴물 곰팡이, 그리고 깊은바다거인의 종양을 가져가야 합니다.", description = "내가 아주 완벽한 물약을 생각해 냈는데 말이야. 이 물약은 마땅히 이루어져야 할 일을 실현되도록 만들 거요.\n\n이 물약을 만들려면 늪지에서 흑표범 심장을 몇 개 가져와야 하고, 또 그곳에 사는 우두머리 늪괴물에게서 마법에 걸린 곰팡이도 가져와야 하는데... 당신처럼 능력 있는 자라면 곰팡이를 얻어올 수 있을 거요.\n\n어려운 건 저 머나먼 잊혀진 땅에서 깊은바다거인의 종양을 찾는 것일 텐데... 그곳의 거인들이 병들거나 그들에게 종양이 생기는 건 아주 드문 일이거든.\n\n자, 이제 가 보시오!", progress = "내 특별한 물약을 마시고 나면 스토나드의 그 첩보원 녀석도 분명... 입을 열 테지. 하하!\n\n이 물약에 필요한 재료는 결코 모으기가 쉽지 않을 거요. 슬픔의 늪에서 흑표범은 흔한 동물이긴 하지만 필요한 만큼 심장을 모으기는 힘들 수 있지. 또 우두머리 늪지괴물은 정말 다루기 까다로운 짐승이고 말이오.\n\n게다가 깊은바다거인의 종양이야 워낙 찾기 어려운 거니까. 하지만 종양으로 발생하는 화학 반응은 비할 데가 없지.", completion = "훌륭하군! 시간도 제때에 잘 맞춰 왔어. 즈레더스가 얘기한 바로는 그 첩보원이 부상에서 회복돼 오크들이 심문할 모양이라고 하더군.\n\n잠깐만 기다려 주면 그 독... 아니 그러니까, 진실의 물약을 만들어 주겠지.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n파멸의 망토돌나무 마울\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1384] = {title = "콜카르 습격", objective = "겔키스에게서 우호적인 평판을 유지하면서 잊혀진 땅의 겔키스 마을에 있는 현자 우텍에게 조잡한 부적 10개를 가져가야 합니다.", description = "콜카르 켄타우로스는 자신들의 마법이 강하다고 생각하지. 하지만 놈들은 마법에 대해서 하나도 몰라! 마법으로 인해 구속을 당하게 되더라도 아무것도 모를 걸!\n\n네가 놈들에게 자신들의 마법이 얼마나 약한지 가르쳐 주도록 해. 북동쪽으로 가서 콜카르 놈들을 처치해. 그리고 놈들의 부적을 가져와. 내게 부적을 가져오면 불 속에 처넣고 웃어 주도록 하지, 하하!", progress = "부적은 가져왔나? 콜카르에게 놈들이 얼마나 약한지 일깨워 줬나?", completion = "겔키스를 위해 훌륭한 일을 해 주는군. 콜카르 녀석들은 약해 빠졌어. 놈들은 곧 죽음을 맞이할 거야. 놈들의 마법은 자신들을 구하지도 못할 정도로 한심스럽지. 이 사실을 일깨워 줬으니 아마 놈들은 두려움으로 더욱더 약해졌을 거야!\n\n우리 땅에서 약한 것들은 오래 살아남지 못해.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1385] = {title = "야비한 정책", objective = "마그람에게서 우호적인 평판을 얻은 다음 와루그와 대화해야 합니다.", description = "잊혀진 땅은 전쟁에 휩싸여 있소. 켄타우로스들이 서로 전쟁을 벌이고 있고 그들 중 승리하는 쪽이 세를 확장해 우리 본거지를 위협하게 될 거요. 그런 일이 일어나도록 내버려둬서는 안 되오.\n\n우리는 켄타우로스를 격퇴할 방법을 찾아야 하오. 그리고 그러기 위해서는... 놈들 부족 중 하나와 동맹을 맺어야 하오. 마그람 켄타우로스들이 겔키스와 전쟁을 벌이고 있소. 당신이 겔키스에 대항해 싸운다면 마그람이 동맹을 고려할지도 모르오.\n\n마그람의 호감을 산 다음 잊혀진 땅 남동쪽의 마그람 마을에 있는 와루그를 만나 보시오.", progress = nil, completion = "많은 겔키스 놈들이 네 앞에 무릎을 꿇었군. 마음에 들어. 넌 우리에게 더 큰 도움을 줄 수 있을 것 같군. 너와 마그람은 친구가 될 수 있겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1386] = {title = "콜카르 공격", objective = "마그람에게서 우호적인 평판을 유지하면서 콜카르 켄타우로스 12명, 콜카르일족 척후병 12명, 콜카르일족 투사 6명을 처치한 다음 잊혀진 땅의 마그람 마을에 있는 와루그에게 돌아가야 합니다.", description = "콜카르 놈들은 자신들이 강하다고 생각하지만, 정말 웃기는 얘기지! 우리는 놈들을 비웃으며 처치해 버릴 거야! 너도 놈들을 처치해야 해. 너도 우리처럼 콜카르를 처치할 능력이 있다는 걸 보여 줘. 북쪽으로 가서 그들을 모두 처치해!", progress = nil, completion = "이제 콜카르 녀석들이 너를 두려워하는군! 놈들을 처치할 때 비웃어 주었겠지? 적을 처치할 때는 비웃어 주는 게 좋아. 놈들이 자신의 나약함을 깨달을 수 있도록 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1387] = {title = "켄타우로스 현상금", objective = "잊혀진 땅의 나이젤의 야영지에 있는 하사관 멜킨스에게 켄타우로스의 귀걸이 15개를 가져가야 합니다.", description = "켄타우로스는 여러 부족으로 이루어져 있소. 각 부족마다 우두머리가 있고 자기들만의 방식이 있지만, 그들 모두 잔인하다는 공통점이 한 가지 있지.\n\n우리가 평화를 되찾으려면 반드시 켄타우로스들을 제거해야만 하오. 그리고 바로 이 일을 당신에게 맡기려고 하오.\n\n잊혀진 땅을 두루 돌아다니며 켄타우로스 녀석들을 처치하고 녀석들의 귀걸이를 가져오시오. 많으면 많을수록 좋소.\n\n얼라이언스를 위해 이 일을 해주시기 바라오. 그러면 전쟁의 끝에 한걸음 더 가까워지게 될 거요.", progress = "보고할 것이 있소?", completion = "아, 켄타우로스의 귀걸이로군. 잘했소.\n\n얼라이언스에 대한 당신의 충성은 의심의 여지가 없소. 당신이 잊혀진 땅에서 흘린 피는 틀림없이 수많은 이들의 목숨을 구하게 될 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n고요의 반지"},
[1388] = {title = "진실의 물약", objective = "부랑자 소굴에 있는 죽음의추적자 즈레더스에게 파우스틴의 진실의 물약을 가져가야 합니다.", description = "모든 것이 계획대로 진행되고 있소. 당신이 죽음의추적자 즈레더스에게 이 진실의 물약을 가져다주길 바라오. 그러면 그가 그걸 어떻게 사용하는지 알려 줄 거요. 제대로... 사용하는 방법 말이지.\n\n하하!", progress = "우리의 소중한 친구 연금술사 파우스틴을 잘 도와주었기를 바라네.", completion = "노련한 파우스틴이 대단한 걸 만들어낼 줄 알았다니까! 자네의 도움이 정말 컸다는 건 의심할 여지가 없군.\n\n이제 작전을 시작하도록 하도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1389] = {title = "드레니시스트 수정", objective = "슬픔의 늪의 피난처에 있는 막투르에게 드레니시스트 수정 6개를 가져가야 합니다.", description = "드레노어 성역에 사는 드레나이들의 겉모습은 우리와 같지만 아제로스에 이르는 고된 여정으로 인해 미쳐 버렸소. 한때는 우리 형제였지만 지금은 동쪽의 드레노어 성역에 살면서 주위에 나타나는 이들은 전부 잡아가거나 죽이고 있다오.\n\n그리고 우리에게 매우 신성한 물건인 드레니시스트 수정을 훔쳐 간 적도 있지.\n\n드레노어 성역으로 들어가 그들의 오두막과 모닥불 사이에서 도난 당한 드레니시스트 수정을 되찾아 오기에는 우리 병력이 부족하오. 하지만 그 수정이 없으면... 우리까지 미쳐 버릴지도 모르오.", progress = "수정은 찾아 왔소?", completion = "고맙소. 우리가 그대에게 신세를 졌소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1391] = {title = "진실의 물약", objective = "스토나드에 있는 첩보원 마크슨에게 즈레더스의 맥주를 가져가야 합니다.", description = "이 일은 신중을 기해서 수행해야 하네. 그곳에서 왈츠나 추면서 그 바보에게 파우스틴의 물약을 마시도록 점잖게 설득하려는 건 아니니까 말이야, 그렇지 않나?\n\n하지만 인간들이 약한 게 하나 있다면 바로 술이지. 파우스틴의 물약을 가져가서 이 에일 맥주에 탈 생각이네. 그 불쌍한 바보가 이 맥주통 소리를 들으면 주저 없이 마시리라고 확신하네.\n\n서둘러 슬픔의 늪의 스토나드로 가서 조용하고 깔끔하게 우리의 임무를 처리하도록 하게.", progress = "부디 내게 자비를 베풀어 줘! 나는 얼라이언스 외부에 대한 정보도 가지고 있다고. 비록 내가 호드의 동조자는 아니지만 밝혀져야 할 정치적 배신 행위가 있단 말이야!", completion = "내게 술을 주는 건가? 이런, 이렇게 친절할 데가... 저 자들이 술을 마지막으로 준 지 며칠이 지났는데 잘 됐군. 이 술을 마신 후에 내가 알아낸 사실을 말해 주지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1392] = {title = "곤봉잡이 노보루", objective = "슬픔의 늪에 있는 피난처의 우두머리에게 노보루의 곤봉을 가져가야 합니다.", description = "노보루는 피난처의 드레나이를 여러 달 동안 괴롭혀 왔습니다. 그의 곤봉은 드레노어 난민에 의해 그들이 겪어야 했던 야만스러운 고통의 상징입니다.", progress = "어서 오시오. 피난처에 잘 오셨소.", completion = "그 끔찍한 노보루의 무기를 손에 넣었단 말이오? 그럼 놈이 죽은 거요?\n\n피난처에는 정말 경사스러운 날이군. 늪지대를 돌아다니며 닥치는 대로 드레나이를 해치던 노보루와 그 일당은 우리에게 두려운 존재였소. 그는 우리의 생존에 직접적인 위협이었지만 우리에겐 그를 상대할 만한 힘이 없었소.\n\n당신을 친구로 둔 것이 우리에겐 크나큰 행운이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1393] = {title = "갈렌 구출", objective = "갈렌이 위험에서 벗어나도록 호위한 다음 슬픔의 늪에 있는 그의 야영지를 찾아 갈렌의 금고를 열어야 합니다.", description = "살려 주세요! 이 짐승들이 날 잡아먹으려고 해요!\n\n여기서 빠져나가게 도와주신다면 귀한 보물을 드릴게요! 보물은 스토나드 북쪽 늪지에 있는 제 야영지에 있어요. 금고 안에 들어 있는데, 저만 알고 있는 방법을 통해 열 수 있답니다.\n\n제가 빠져나갈 수 있도록 도와주신다면 여는 방법을 가르쳐 드리겠어요.", progress = nil, completion = "이 금고의 열쇠 구멍이 검은 나무 진으로 막혀 있어 열 수가 없습니다.\n\n그러나 갈렌이 금고 밑에 숨겨진 걸쇠가 있다고 말해 주었습니다...\n\n...곧 걸쇠를 찾아내 풀자 금고가 열립니다...", rewards = "다음과 같은 것들을 받습니다:\n\n환상의 버클러"},
[1394] = {title = "최후의 시험", objective = "버섯구름 봉우리에 있는 도른 플레인스토커와 대화하십시오.", description = "잘했네. 지금까지의 시험들을 잘도 치러냈군. 이제 버섯구름 봉우리의 도른에게 돌아가 보게. 그가 자네의 몸과 마음, 그리고 영혼에 일어난 변화를 느끼고, 충분히 강해졌다는 것을 알아볼 거야. 그동안의 수고에 대해 보상을 받아야 할 만큼이라는 것도...\n\n지금까지의 시험에서 보여 준 것처럼 계속 자신에게 충실하도록 하게. 그러면 언젠가 도른이 다시 자네를 시험하게 될 테니까...", progress = nil, completion = "아. 아주 오랜만에 보는군. 자네가 스스로 길을 선택해 첫걸음을 내디딘 이후 꽤 오랜 세월이 흐른 것 같아.\n\n그리고 이제 예전보다 더욱 강해져서 나에게 돌아와 주었어... 보다 많은 것을 깨우친 모습으로 말이야. 정말 기쁘군. 자, 내 시험을 끝까지 꿋꿋이 치른 것에 대해 마땅히 받아야 할 보상일세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n폭풍 해머춤추는 불꽃\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1395] = {title = "네더가드 요새 보급품", objective = "마법석의 힘이 다하기 전에 병참장교 룬겔츠에게 마법석 상자를 가져가야 합니다.", description = "마법석이 들어있는 이 상자를 저주받은 땅에 있는 네더가드 요새로 가져가야 하네. 마법석은 오랫동안 그 힘을 유지하지 못할 테니 다음 짐마차가 올 때까지 기다릴 수는 없네.\n\n자네가 마법석을 빨리 가져가야해. 이걸 네더가드 요새에 있는 병참장교 룬겔츠에게 전해주게.\n\n요새에 가려면 동쪽의 죽음의 고개를 통과한 후 또 동쪽으로 슬픔의 늪에서 남쪽에 있는 저주받은 땅으로 들어서야 하네.\n\n자네가 가는 길은 위험이 도사리고 있으니 조심하게나. 그렇지 않으면 실패할 거야.", progress = "안녕하십니까! 이곳의 소란스러움에 마음쓰지 마십시오. 네더가드 요새에서는 늘상 있는 일이니까요.\n\n그런데, 저에게 뭔가 전해주실 게 있으신가요?", completion = "아, 마법석이로군요! 마법사들이 이걸 보면 무척 기뻐할 겁니다!\n\n다크샤이어에서 이곳으로 오는 게 쉽지 않았으리라는 걸 압니다. 대단히 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1396] = {title = "야생 짐승의 공격", objective = "새끼 톱니악어 8마리, 늪그물거미 10마리, 늪지재규어 10마리를 처치한 다음 슬픔의 늪에 있는 파수병 비그스에게 돌아가야 합니다.", description = "내 짐마차는 동쪽 해안으로 갈 예정이었지만 목적지에 다다르지 못했소이다. 드레노어 난민들이 우리를 공격하여 경비병들을 죽이고 보급품을 다 박살내 버렸소. 나만 놈들의 공격에서 살아남았지.\n\n난 남은 보급품을 지켜 내기로 마음 먹었지만 주위에 야생 짐승들이 숨어 있어서 쉽지 않소. 부디 짐승들로부터 내 야영지를 지킬 수 있도록 도와주시오!", progress = nil, completion = "이제 짐승의 소리가 잦아들었군. 고맙소. 이제 놈들이 다시 돌아오지 않기를 바랍시다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1398] = {title = "유목", objective = "슬픔의 늪에 있는 파수병 비그스에게 볕에 말린 유목 8개를 가져가야 합니다.", description = "정말 큰 신세를 졌소. 당신 안에는 명예로운 심장이 뛰고 있군. 그래서 말인데 부탁했으면 하는 일이 하나 더 있소.\n\n내가 어떻게든 네더가드로 가려면 이 마차를 수리해야만 하오. 마차를 수리하려면... 습지의 무르고 뒤엉킨 나무 말고 튼튼하고 잘 마른 나무가 필요하오.\n\n동쪽의 해변으로 가서 햇볕에 잘 마른 유목을 좀 찾아서 내게 가져다주시오.", progress = "유목은 구해 왔소?", completion = "이 목재는 가벼우면서도 튼튼하군. 이 정도면 훌륭하오. 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1418] = {title = "니카 블러드스카", objective = "니카 블러드스카와 대화해야 합니다.", description = "황야의 땅은 거친 땅이며 얼라이언스의 영토인 모단 호수와 가깝지. 그래서 스토나드와 카르가스의 황야의 땅 전초 기지 간의 연락이 종종 두절되곤 하오.\n\n자, 당신의 능력을 한번 증명해 보시오. 황야의 땅으로 가서 카르가스 전초 기지의 정찰 대장인 니카 블러드스카를 만나 그녀와 대화한 다음 그녀의 보고 내용을 내게 다시 전하도록 하시오.", progress = nil, completion = "헬그럼이 보고를 기다리고 있다고? 스토나드로 정찰병을 보낸 지 채 3일도 안 됐는데... 그가 임무에 실패한 건가? 스토나드에 내 보고가 전해지지 않았다면 그가 실패했다는 뜻이겠군.\n\n다음에 보내는 자는 능력이 더 좋던가 아니면 운이라도 더 좋기를 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1419] = {title = "도둑 코요테", objective = "카르가스에 있는 니카 블러드스카에게 코요테 턱뼈 30개를 가져가야 합니다.", description = "황야의 땅에서 지낸 지 오래되었습니까, <class>? 그 열기를 느껴본 적 있나요? 저 먼지 가득한 평원을 어슬렁거리는 짐승들과 마주친 적이 있습니까? 이제 당신이 직접 겪어 봐야 할 때가 됐군요.\n\n바위산코요테는 사나운 종일뿐 아니라 카르가스로 기어 들어와 우리의 식량을 훔쳐 갈 만큼 대담하기도 하답니다. 이 도둑들의 근거지를 제거하는 일 좀 도와주시기 바랍니다!\n\n바위산코요테를 사냥하여 그 턱뼈를 내게 가져오세요. 충분한 양을 가져오면 당신이 황야의 땅에 대해서 잘 알고 있다는 걸 믿도록 하겠습니다.", progress = "턱뼈는 가져왔습니까?", completion = "턱뼈를 많이 모아 왔군요. 이제 저 코요테들이 우리 식량에 손을 댈 수조차 없겠군요.\n\n황야의 땅의 코요테는 쉬운 사냥감이 아닌데... 훌륭합니다. 이렇게 잘해내다니 당신이라면 충분히 이곳에서 살아남을 수 있겠군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1420] = {title = "헬그럼에게 보고", objective = "스토나드에 있는 날쌘돌이 헬그럼에게 니카의 보고서를 가져가야 합니다.", description = "스토나드의 헬그럼에게 보낼 새로운 보고서를 작성했습니다. 이걸 그에게 전해 주시기 바랍니다.\n\n그리고 당신이 스스로 길잡이가 될 생각이라면 방향을 잃지 않도록 조심하세요. 그렇지 않으면 적의 손아귀에 떨어질 수도 있으니까 말입니다.", progress = "돌아왔군. 보고서를 가져왔나?", completion = "고맙군. 흠, 니카의 보고서를 보니 얼라이언스도 나름대로 문제를 겪고 있는 것 같아. 그리고 일부 우리와 공통의 적을 상대하고 있는 것 같고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1421] = {title = "사라진 짐마차", objective = "드레노어 성역에서 마법사들의 재료가 들어 있는 짐마차 상자를 찾아 파수병 비그스에게 가져가야 합니다.", description = "나는 드레노어 난민들이 공격하는 동안 기절해 있었지만 정신을 잃기 전에 짐마차를 끌던 말 한 마리가 두려움으로 날뛰며 북쪽에 드레노어 난민의 마을인 드레노어 성역으로 끌려가는 것을 보았소.\n\n그 마차에는 귀중한 재료들이 들어 있는 짐마차 상자가 있었는데, 네더가드 요새의 마법사들의 연구에 중요한 재료들이 들어 있었소. 그 보급품들을 찾아서 내게 가져다주시오.", progress = "마법사들의 재료들은 찾았소?", completion = "아, 찾아냈구려! 이 보급품들을 되찾았으니 네더가드의 마법사들이 일을 계속할 수 있을 거요. 나는 그들이 하는 일이 뭔진 모르지만, 아무튼 저주받은 땅의 어둠의 문과 관련이 있으며 얼라이언스의 안전을 위해 매우 중요한 일이요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1422] = {title = "바다의 위협", objective = "슬픔의 늪에 있는 카타르와 대화해야 합니다.", description = "내가 자네 무기를 만드는 일을 시작할 동안 카타르와 얘기해 보는 게 어떤가? 그는 해안 순찰을 도와줄 일손을 찾고 있다고 했었네. 그리고 이곳의 별 볼일 없는 다른 이들과 어울려 술이나 마시는 것보다는 자네의 전투 감각과 무기를 잘 단련해 두는 게 낫지 않겠나?", progress = nil, completion = "잠시만 조용히 해 봐, &lt;class&gt; 친구. 단조로운 파도 소리 위로 물고기 인간이 목을 울려 대는 저 역겨운 소리를 들을 수 있을 테니까 말이야.", rewards = nil},
[1423] = {title = "잃어버린 보급품", objective = "병참장교 룬겔츠에게 잃어버린 보급품을 가져가야 합니다.", description = "이 맥주통은 작지만 튼튼합니다. 나무가 이어진 부분은 자극적인 냄새가 나는 노란색 왁스로 봉해져 있습니다. 그리고 맥주통 밑바닥에는 다음과 같은 글귀가 찍혀 있습니다.\n\n병참장교 룬겔츠\n\n네더가드 요새", progress = "내게 볼일이 있습니까?", completion = "아, 고맙습니다! 다크샤이어에서 여기로 오던 도중 매우 많은 보급품들이 분실되었지요. 그나마 이렇게 일부를 되찾아서 다행이군요.", rewards = "다음과 같은 것들을 받습니다:\n\n보급품 상자"},
[1424] = {title = "눈물의 연못", objective = "스토나드에 있는 펠제룰이 아탈라이 유물 10개를 모아 달라고 부탁했습니다.", description = "대족장님께서 아탈학카르 신전에서 일어나고 있는 이상한 일들에 대해 조사하라고 우릴 보내셨소.\n\n아탈라이 트롤은 금지된 마법을 행하는 것으로 알려진, 사악한 마법사들로 이루어진 부족이지. 우리가 이곳에 도착해서 신전이 가라앉았다는 사실을 알고 얼마나 놀랐을지 생각해 보시오.\n\n지금은 녹색 용혈족들이 아제로스의 수호자를 자청하며 그곳을 지키고 있소.\n\n무슨 일이 일어난 건지 반드시 알아내야 하오. 눈물의 연못 주변을 조사하고 아탈라이 유물을 모으도록 하시오. 그러면 이 수수께끼의 조각들을 짜맞춰 보는 작업을 시작할 수 있을 것이오이다.", progress = "아탈학카르 신전 내에서 어떤 사악한 음모가 진행되고 있는지는 아무도 모르지만, 거대하고 강력한 마법의 힘이 사용된 것만은 분명하오.\n\n그 마법에 대해 가능한 많은 정보를 얻어야 하오. 어쩌면 아탈라이의 마법 주문이 호드에게 도움이 될 것 같군.\n\n우선 당신이 눈물의 연못 주위에서 아탈라이 유물을 충분히 모아 오면 도대체 그 트롤 녀석들이 무엇을 하려는 것인지, 또 뭐가 그렇게 크게 잘못된 것인지 조금씩 알아낼 수 있게 될 것이오.", completion = "부지런하게 아탈라이 유물을 모아 오다니... 칭찬할 만한 일이 아닐 수 없군, &lt;class&gt; 친구.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1425] = {title = "보급품 전달", objective = "네더가드 요새에 있는 병참장교 룬겔츠에게 네더가드 뱃짐을 가져가야 합니다.", description = "내가 마차를 수리하는 동안 당신에게 마지막으로 부탁할 일이 있소.\n\n오우거의 공격에서 지켜 낸 매우 중요한 보급품을 네더가드 요새로 가져가 주시오. 네더가드 요새는 어둠의 문이 내려다보이는 저주받은 땅의 북쪽 언덕에 자리 잡고 있소.\n\n네더가드로 가려면 동쪽으로 길을 따라가시오. 길이 갈라지는 곳이 나오면 남쪽을 향해 저주받은 땅으로 가다가 왼쪽으로 가면 되오. 조심해서 길을 잘 따라가야 하오.", progress = "무슨 일이십니까?", completion = "뭐라고요? 비그스의 짐마차에 실려 있던 짐이라고 했습니까? 짐과 비그스를 다시는 찾을 수 없을 줄 알았는데...\n\n고맙습니다. 운이 좋다면 이 짐에 우리에게 절실하게 필요한 재료인 아조란 수정이 들어 있을지도 모르겠군요. 우리가 가지고 있는 물량은 거의 바닥나서 말입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1426] = {title = "바다의 위협", objective = "늪지멀록 10마리, 늪지멀록 먹물쟁이 10마리, 늪지멀록 청소부 10마리를 처치한 다음 슬픔의 늪에 있는 카타르에게 돌아가십시오.", description = "난 바다를 전혀 좋아하지 않는데다가 그 속에서 나타난 생물들 역시 좋아하지 않지. 바다는 강력하지만 냉담하고 잔인한 눈이 먼 여왕이라 할 수 있어. 내게 그럴 힘만 있다면 저 물고기 인간들을 수백씩 처치해 버렸을텐데 말이야. 하지만 호드의 대의를 행하는 이의 손에 놈들이 처치되는 걸 보는 것 또한 기쁜 일이 아닐 수 없지.\n\n우리가 당신에게 바라는 것도 바로 이 때문 아니겠나, <class>? 얼마나 많은 놈을 처치할 수 있을까? 놈들 중 가장 강력한 종에 맞서 자신을 한번 시험해 보겠나?", progress = nil, completion = "바다는 광활하고 무자비해 보이지만, 당신은 그 바다가 낳은 짐승들의 피로 바다를 얼룩지게 했군. 이제 물고기 인간들은 고통이 어떤 것인지 알게 됐을 것이야. 하지만 놈들은 어리석기 때문에 당신이 놈들에게 준 타격에서 일어나 군대를 다시 강화하려고 할 것이지.\n\n물론 우리에겐 좋은 일이야. 밤새도록 놈들의 비명 소리가 바다의 파도 소리 위에 울리도록 놔두는 것이야. 난 놈들의 비명 소리가 하나씩 잠잠해지는 걸 들으며 미소를 짓게 되겠지.\n\n물고기 인간을 더 처치하고 싶거든 언제든 내게 돌아오라고. 난 또 기꺼이 당신에게 보답할 테니 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1427] = {title = "바다의 위협", objective = "슬픔의 늪에 있는 톡카르와 대화해야 합니다.", description = "쉬기 전에 톡카르와 한 번 더 얘기해 보라고. 당신이 없는 동안 무기를 몇 개는 만든 것 같더군. 아마 여기서 도와준 것에 대한 보답으로 하나 줄 거야. 언제든 준비가 되면 받은 무기의 힘을 저 물고기 인간들에게 한번 시험해 보면 좋을 거요. 단 나를 위해서 말이지...", progress = nil, completion = "아, 돌아왔군. 잘됐네. 자네가 멀록과 싸우는 데 도움이 될 만한 무기들을 더 완성했지. 신선한 톱니악어 고기를 가져온 것과 카타르의 얼굴에 다시 미소를 심어준 것에 대한 보답으로 내 하나 주도록 하겠네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n톡카르의 멀록잡이 단도톡카르의 멀록잡이 곤봉톡카르의 멀록잡이 도끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1428] = {title = "계속되는 위협", objective = "늪지멀록 먹물쟁이 10마리, 늪지멀록 청소부 10마리, 늪지멀록 점쟁이 10마리를 처치한 다음 슬픔의 늪에 있는 카타르에게 돌아가야 합니다.", description = "물고기 인간에 대한 당신의 증오도 나만큼이나 커지고 있다니 기쁘군.\n\n해변에서 놈들을 더 찾아내 원하는 만큼 충분히 전투를 치른 다음 내게 돌아오면 당신에게 줄 보상에 대해 얘기하도록 하지.", progress = nil, completion = "잘해냈군, &lt;class&gt;. 아직 놈들을 더 처치해야 해. 물고기 인간이 모두 사라져 버리도록 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1429] = {title = "추방된 아탈라이 트롤", objective = "동부 내륙지에 있는 추방된 아탈라이트롤에게 아탈라이 유물 자루를 가져가야 합니다.", description = "당신이 눈물의 연못에서 위험에 맞서 용감하게 임무를 수행하는 동안, 우리 정찰병 중 한 명이 말린 고기에 피로 쓰인 두루마리를 가지고 돌아왔소. 아마도 아탈라이부족의 사제에 대한 판결문인 것 같은데...\n\n이 사제는 아탈라이부족에게 있어 죽음보다 더한 형벌을 선고받았지. 그는 마른나무껍질 트롤과 함께 동부 내륙지 북쪽 먼 곳으로 추방당했소.\n\n이 유물들을 싸 줄 테니 그 추방된 트롤을 찾아 유물의 진정한 용도를 알아내어 여행이 다 끝나면 내게 돌아오도록 하시오.", progress = "여기까지 오다니 용기가 가상하군. 용감한 것이든가, 아니면 어리석은 것이겠지...", completion = "아탈라이의 소환 유물을 가져온 것인가?\n\n예언자 잠말란이 피의 집회 신봉자들을 그들이 선택한 운명으로 이끌고 있나 보군. 학카르는 신전으로 돌아온 건가? 그들이 결국 운명을 다 한 건가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1430] = {title = "싱싱한 고기", objective = "슬픔의 늪에 있는 다르에게 괴물게 집게발 10개를 가져가야 합니다.", description = "내 고객들은 육즙이 많은 게살을 많이 찾는데 특히 괴물게의 살이 인기가 좋소이다.\n\n해안으로 갈 일이 있거든 괴물게 집게발을 좀 구해 와서 다시 오그리마로 운송할 수 있도록 해 주시기 바라오. 보상은 충분히 하겠소.\n\n해안은 이곳에서 동쪽에 있소. 괴물게들은 해변과 바다 아래를 종종걸음으로 돌아다니니 찾기 쉬울 것이오.", progress = "게 다리를 가지고오면 와인을 한 통 주겠소. 대신에 고객들에게 보내기 전에 내가 꼭 맛을 봐야겠소.", completion = "아, 이거면 딱 좋겠군. 어서 불 위에서 요리해 맛을 보고 싶군그래. 가는 길에 맛을 보게 몇 개 가져가도록 하시오. 정말로 맛있다오.", rewards = "다음과 같은 것들을 받습니다:\n\n왕괴물게 집게발 구이주방장의 가죽 허리띠"},
[1431] = {title = "동맹 관계", objective = "오그리마에 있는 켈드란과 대화하십시오.", description = "목소리를 낮추시오. 우리 주민과 관련된 중요한 얘기를 당신과 나누고 싶소. 아직 분명한 계획은 아니지만...\n\n우리는 긍지를 지닌 종족이오. 그런데 인간과의 전쟁이 이제 위대한 스랄님의 인내심까지 시험에 들게 하고 있소. 당신도 알다시피, 우리 대족장님께서는 현명하고 신중한 분이시오. 항상 자신의 백성들을 먼저 생각하고 계시오. 그 분은 외교의 직무도 맡으셨기에 오랜 기간 인간을 대하면서 결국 그들의 방식을 알게 되셨지.\n\n내 이야기에 관심이 있다면 이 도시의 서쪽 출구 근처에 있는 켈드란을 만나 보시오. 그곳에 그의 오두막집이 있소.", progress = nil, completion = "푸타니, 고귀한 &lt;class&gt;|1이여;여;. 나는 이곳에서 마법과 신비한 기술을 수련하고 있는 켈드란이라고 하오.\n\n크라벤 드록이 당신을 보냈군. 내가 당신에게 맡길 임무는 지금까지의 그 어떤 임무보다 훨씬 더 신중하고 깔끔하게 처리해야 하오. 힘들겠지만 그렇다고 불가능한 정도는 아니오.\n\n지금부터 대족장님께서 나와 당신의 도움을 필요로 하는 이유를 설명해 줄 테니 편안한 마음으로 들으시오.\n\n먼저 정황을 얘기해 주겠소. 호드가 자신들을 어떻게 생각하는지, 우리의 동맹이 우리를 어떻게 여기고 있는지, 그리고 가장 중요한 우리 적이 우리를 어떻게 생각하고 있는지에 대한 것들이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1432] = {title = "동맹 관계", objective = "잊혀진 땅에 있는 타카타 스틸블레이드와 대화하십시오.", description = "얼라이언스가 칼림도어로 세력을 점점 확장함에 따라 호드가 맺은 불타는 군단과의 조약이 불행한 결과를 낳을 수도 있소. 대족장님께서는 그런 일이 일어나도록 용납하지 않으실 것이오. 그리고 나는 그분의 은혜로 지휘관을 맡아 그들을 제거하는 일을 하게 되었지.\n\n나는 대원들을 잊혀진 땅의 거대한 코도 무덤에서 북쪽으로 가면 있는 침묵의 초소에 배치해 두었소. 돌발톱 산맥의 잿더미 계곡에서 남쪽으로 가면 그곳에 다다르게 될 거요. 도착하면 타카타 스틸블레이드를 찾도록 하시오.", progress = nil, completion = "반갑소이다. 오그리마에서 소식을 가져온 거요? 잘됐군.\n\n악마들이 켄타우로스 배설물 냄새보다도 더 지독하게 이 지역을 유린하고 있소. 그 반인반마의 족속들은 이 땅이 자기들 땅이라 주장하고 있지... 그런데 분명 그들이 제어할 수 없는 세력이 존재하오. 뭔가 조치를 취하지 않는다면 그 세력이 켄타우로스들을 몰살해 버릴 거요.\n\n켄타우로스를 돕는 건 그리 기분 좋은 일은 아니지만 호드를 위한 일이니 대족장님을 위해 기꺼이 임무를 수행할 것이오. 그것이 호드에 속한 흑마법사들을 돕는 길이라면 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1433] = {title = "동맹 관계", objective = "잊혀진 땅에 있는 마우린 본스플리터와 대화하십시오.", description = "불타는칼날단이 노리고 있는 것은 여러 가지지. 근본적으로 녀석들의 영혼은 악하고 타락했기 때문에 녀석들을 막기 위해서는 파멸시키는 수밖에 없소.\n\n켈드란이 마우린을 나와 함께 이곳으로 파견했소. 마우린은 불타는칼날단과 그들의 흑마법사에 대해 잘 알고 있기 때문이요.\n\n나는 잊혀진 땅에 있는 악의 위협들을 처리하는 동안, 그는 불타는칼날단에 대한 우리 계획을 조정하는 일을 맡아 왔소.\n\n그를 만나 얘기해 보시오. 아마 상세한 계획을 알려 줄 것이오.", progress = nil, completion = "아, 아주 좋아! 대족장님께 충성하는 자들의 도움이라면 언제나 환영이지.\n\n내 이름은 마우린이오. 나는 켈드란과 젊으신 대족장 스랄님의 명령으로 이곳에 왔지. 나는 젊고 패기에 찬 지도자를 보좌하여 악의 무리를 제거하는 것이 소망이오.\n\n부패의 온상인 불타는칼날단을 제거하기 위한 내 계획을 설명해 줄 테니까 이리 가까이 와 보시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1434] = {title = "사티로스의 출몰", objective = "서릿발분노의 암살자 7명, 서릿발분노의 악마추종자 7명, 서릿발분노의 배반자 7명, 그리고 서릿발분노의 지옥소환사 7명을 처치한 후 잊혀진 땅에 있는 타카타 스틸블레이드에게 돌아가십시오.", description = "악마가 만연하는 것은 반드시 무언가 다른 세력이 배후에 있다는 뜻이오. 세상에 악이 움틀 수 있도록 돕고 있는 어떤 존재가 있다는 것이지.\n\n나약해진 영혼, 또는 힘에 대한 부질없는 욕망으로 시작되기도 하오. 어쩌면 그것은 복수에 대한 갈망이거나 궁극적인 정의에 대한 호소일 수도 있소. 우리에게 고통이 닥쳐오면 사티로스 같은 악마의 세력이 우리를 이용하게 될지도 모르지.\n\n사티로스들이 불타는칼날단 무리와 손을 잡은 이후 스랄께서는 이들의 위협을 걱정하고 계시오. 여기서 북동쪽으로 가 그들을 찾아서 제거한 후에 다시 내게 돌아오시오.", progress = "내 타우렌 친구가 사티로스가 겉보기와는 다르니 조심하라는 말을 했었소. 그 친구 생각으로는 사티로스들에게 무언가 이상한 일이 있었고, 그들의 본성이 왜곡되어 지금처럼 사악해진 것 같다고 했었지. 하지만 내 눈으로 직접 보지 못했으니 모를 일이오.\n\n내게 보이는 거라곤 약한 자들에 대한 무자비한 살상과 어둠의 힘을 갈구하는 자들의 타락뿐이오.\n\n나는 대족장님께서 달리 명령을 내리시기 전까지는 계속해서 녀석들을 제거하는 임무에 총력을 기울일 것이오. 결코 놈들에게 자비를 베풀지 않겠소.", completion = "아주 잘했소. 당신은 명예와 헌신을 몸소 보여 주었소.\n\n잊혀진 땅에서의 임무가 완수되면 대족장님께서도 당신의 공적을 알게 되실 거요. 당신이 그분의 계획을 실현하는데 일조했다는 것을 말이지.\n\n고맙소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1435] = {title = "불타는 영혼", objective = "잊혀진 땅에 있는 마우린 본스플리터에게 빌린 불타는 보석 하나와 영혼이 깃든 불타는 보석 15개를 가져가야 합니다.", description = "사사로운 욕심을 위해 자신의 군주를 배반한 천한 짐승들은 죽어 마땅하지. 하지만 스스로 어둠 속에 내던진 자들에게는 죽음만으로는 부족하지.\n\n자, 이 보석을 받으시오. 불타는칼날단 중 하나가 거의 죽음에 이르렀을 때 그 보석의 마법을 사용하도록 하시오. 그러면 그들의 몸에서 타락한 영혼이 나와 보석 안으로 빨려 들어가게 될 것이오.\n\n영혼이 깃든 불타는 보석을 내게 가져오면 알아서 처리하도록 하지.\n\n이제 가 보도록 하시오. 죽지 않도록 조심하고...", progress = "난 마법을 되도록 간단하게 만들려고 했소. 부상 당한 적의 몸에서 쉽게 영혼을 빼낼 수 있도록 말이지. 보석의 힘에 의존해 적의 목숨을 완전히 끊어서는 안 되오. 상대가 거의 죽음에 이르렀을 때에 보석을 사용해야지, 그렇지 않으면 아무 소용도 없다는 것을 명심하시오.", completion = "아, 무사히 돌아왔군. 정말 다행이야. 안전한 곳에 보관할 테니 보석을 내게 주시오.\n\n이제 내가 당신에게 맡길 임무는 더 이상 없소. 타카타가 다른 임무를 맡길지도 모르니까 휴식을 좀 취한 뒤 그를 만나 보도록 하시오. 아니면 오그리마로 돌아가 이곳 잊혀진 땅에서의 진척 상황을 켈드란에게 알려 주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1436] = {title = "동맹 관계", objective = "오그리마에 있는 켈드란과 대화하십시오.", description = "전투가 순조롭게 진행되어 가고 있소. 계속해서 악마와 그 졸개들을 상대로 한 전투에서 혁혁한 성과를 거둔다면 계절이 바뀌기 전에 대족장님께서 우리를 고향으로 돌려보내 주실지도 모르겠소.\n\n켈드란님께 돌아가서 우리가 한 일을 보고해 주시오. 틀림없이 당신이 이곳에서 수고한 것에 대해 보상을 해 주실 거요. 대족장님께서 자기를 알아 주신다는 것을 알면 아주 자랑스러워할 거요. 그만큼 모든 일에 동기를 중요하게 여기는 자니까...", progress = nil, completion = "잊혀진 땅에서 아주 큰 성공을 거두고 돌아왔군그래. 고맙소.\n\n시간을 내서 수고를 해주고 또 나를 도와줘서 너무나도 고맙소. 스랄께서도 나를 알아주시고 호드와 얼라이언스 간의 평화를 원하시니, 이제 더 이상 불필요한 폭력을 쓰진 않을 생각이오. 우리가 지내는데 불편함이 없을 정도의 조치만 취하고 말이오.\n\n내 당신에게 큰 빚을 졌군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n카펠란의 장갑질주의 단망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1437] = {title = "발라리엘의 수색", objective = "잊혀진 땅에서 티라니스 말렘과 달린다 말렘의 마차를 찾아 조사해야 합니다.", description = "만나서 반갑소. 난 발라리엘이라고 하오. 난 나이트 엘프 상인 가문인 말렘가의 실종된 두 아이를 찾으러 여기 왔소이다. 아이들 아버지는 최악의 상황이 벌어진 게 아닌가 싶어 걱정이 이만저만이 아니오. 난 모든 수단을 동원해서라도 실종된 아이들을 찾아야 합니다. 티라니스나 달린다를 찾는 일을 아직 시작하지 않았지만 다행히 여기 오래 있지는 않을 것 같소.\n\n몇 주 전 아이들이 돌발톱 산맥을 지나갔다는 것이 마지막으로 들은 소식이오.\n\n그대가 아이들의 마차를 찾게 되면 즉시 내게 돌아와 주시기 바라오.", progress = nil, completion = "마차의 잔해를 뒤져보니 마법과 무기로 공격을 받은 것이 분명합니다. 혈흔도 없고 시체도 없는 것으로 볼 때 순식간에 일방적으로 당한 듯합니다.\n\n이 마차를 공격한 자들은 아주 유능하고 재빠른 자인 듯 합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1438] = {title = "발라리엘의 수색", objective = "잊혀진 땅에서 달린다 말렘을 찾아야 합니다.", description = "가능하다면 달린다와 티라니스 둘 다 찾아 내게 돌아오시오. 이 성채부터 수색해 보도록 하시오. 나는 다르나서스에 있는 상관들께 연락해 상황을 알리겠소.\n\n아, 얘기할 게 더 있소이다. 내 상관께서 티라니스가 이곳에 오게 된 동기가 무엇인지 걱정하고 계시오. 달린다를 찾아 안전하게 데려 오는 것이 더 중요하오. 티라니스는 집에 데리고 가기 전에... 잘 판단해야 하오.", progress = nil, completion = "드디어 엘룬께서 도와줄 분을 보내주셨군요. 제발 절 좀 도와주세요, &lt;class&gt;님. 티라니스 오빠랑 저는 불타는칼날단에게 붙잡혀 여기로 왔어요. 그들이 저를 그들이 섬기는 악마 군주에게 제물로 바칠 건가 봐요!\n\n전 잊혀진 땅으로 오면 안 되는 걸 알았지만 티라니스 오빠가 요즘 들어 사람들의 기대를 저버리고 신비술에 몰두하기 시작했어요. 오빠는 이 땅에 악마가 득실거린다는 것을 알고도 여기로 온 거예요.\n\n전 오빠가 잘못될까 봐 걱정이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1439] = {title = "티라니스 수색", objective = "잊혀진 땅에서 티라니스 말렘을 찾아야 합니다.", description = "오크들이 경비병이랑 하인들을 모두 죽이고 저희를 여기로 끌고 왔어요. 오, 얼마나 끔찍한 짓을 하던지! 우리도 그 자리에서 죽겠구나 싶었는데 다른 속셈이 있는 것 같았어요.\n\n티라니스 오빠는 오크들과 대화를 하려고 했어요. 왜 그랬는지는 잘 모르겠지만... 자기가 신비술에 대해 얼마나 알고 있는지 보여주려고 했던 거 같아요.\n\n부탁이에요. 오빠가 어떻게 됐는지 알지 못하면 여기를 떠날 수가 없어요. 오빠를 찾아서 무슨 일이 있었는지 알게 되면 다시 절 데리러 와주세요.", progress = "티라니스 오빠가 불타는칼날단의 비밀을 익혀서 그 무리에 가담할까 걱정이 돼요. 오빠는 마법에 심취한 자들이 얻게 되는 힘을 항상 동경했거든요.\n\n티라니스 오빠의 영혼이 그렇게 위험한 마법에 빠졌다는 소식을 가족들에게 전할 자신이 없네요. 우리 나이트 엘프가 끔찍한 죄악으로 여겨 멀리하려는 그런 마법을 추구하려 하다니... 이해할 수가 없어요.", completion = "그런 끔찍한 일이! 하지만 어쩔 수가 없었겠죠. 당신이 직접 처단하지 않았다면 우리 나이트 엘프들이 처단했을 테니까요. 감사를 드려야겠네요. 저의 감사가 진심으로 느껴지지 않더라도 용서해주세요. 기분 나쁘게 하려는 생각은 아니었어요.\n\n오빠가 어떻게 됐는지 알았으니 이제 이곳에서 탈출할 때가 된 것 같네요. 아직 도와주실 생각이 있으면 이 끔찍한 곳에서 벗어나는데 도움을 받고 싶군요.\n\n준비가 되셨으면 이제 안전한 곳으로 가도록 하죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1440] = {title = "발라리엘에게 돌아가기", objective = "천둥도끼 요새에서 달린다 말렘을 호위해 잊혀진 땅에 있는 발라리엘 데몬슬레이어에게 돌아가야 합니다.", description = "그럼 이제 떠날까요? 수고해 주셔서 정말로 감사해요. 후에 상황이 여의치 않을 때를 대비해서 미리 저와 제 가족에게 해주신 일에 감사드릴게요. 준비가 되셨다면 더 이상 여기에 있을 이유는 없으니 때가 되면 떠나도록 하죠.", progress = nil, completion = "고맙소. 달린다는 이곳 나이젤의 야영지까지 무사히 잘 도착했소. 예상보다 상태도 훨씬 좋고 말이오. 혼자 힘으로 이곳까지 왔다는 건 좋은 조짐이지. 그대도 무사한 것이길 바라오.\n\n티라니스와 달린다가 함께 돌아오지 못했다는 건 가슴 아픈 일이오. 티라니스가 내린 결정에 달린다도 많이 당황스러워 하고 있지만 그건 달린다가 견뎌내야 할 문제요. 다르나서스로 돌아가서 그 애가 감당해야 할 문제란 말이라오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n격투가의 허리띠통찰의 장갑수비대 망토달빛 아미스\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1442] = {title = "코르석을 찾아서", objective = "어둠의 해안에 있는 툰드리스 윈드위버에게 코르석을 하나 가져가야 합니다.", description = "안녕하시오, <name>. 거룩한 길을 걷는 그대에게 어떻게 도움을 주면 되겠소? 아, 그렇군. 스틸웰... 오래전부터 알고 지내던 그 대장장이 말이로군. 그 친구의 이름을 들어 본지도 꽤 오래됐지만 아직 기억하고 있소.\n\n절대로 그 사람에게서 경솔하다는 인상을 받은 적이 없었으니, 이번에 그가 코르석을 얻으려는 것도 분명 숭고한 이유 때문일 거라고 생각되는군.\n\n진정으로 그 보석을 원한다면 잿빛 골짜기에서 북서쪽으로 가야 하오. 거기서 어느 고대 폐허 안쪽에 검은심연의 나락이 있을 거요. 그 아래 살고 있는 나가들이 아직도 그 보석을 사용하고 있다고 하오. 그곳에 절대로 혼자서는 가지 마시길...", progress = "거룩한 길에서 벗어난 자가 코르석을 찾아왔다면 의심했겠으나, 난 그대의 일족을 우리 일족의 몇몇보다도 더 신뢰하고 있소이다. 단 한 명의 이탈자의 비행으로 그대의 일족 전체를 판단하지는 않소.", completion = "이것이 스틸웰이 원하는 바로 그 보석이 맞긴 하지만, 그에게 가져가기 전에 오염된 보석을 깨끗이 정화해야 하오이다. 나가들이 그들의 사악한 힘을 보석에 불어넣었으니 말이오.\n\n가서 스틸웰에게 보석의 힘은 손상되지 않았으니 어떤 곳에 쓰이든 아무 문제 없을 거라고 전해 주시오.\n\n&lt;class&gt;|1이여;여;, 준비를 단단히 하는 것이 좋겠소. 이건 평범한 이가 지닐 수 있는 물건이 아니니까.", rewards = "다음과 같은 것들을 받습니다:\n\n정화된 코르석"},
[1444] = {title = "펠제룰에게 돌아가기", objective = "스토나드에 있는 펠제룰에게 돌아가야 합니다.", description = "예언자 잠말란은 내게 아탈학카르 신전에서 추방한다고 선고했다. 한때 그 대사제를 훌륭한 지도자라고 생각한 적도 있었지.\n\n잠말란 자신의 예언에 대한 단호한 믿음은 아탈라이부족에게 파멸을 가져오게 할 것이다. 아직 아탈라이부족이 파멸을 맞지 않았다면 말이지.\n\n내가 이러한 염려를 표명하자, 나를 이단자로 몰아 신전에서 내쫓아 버리더군.\n\n당신이 내게 가져온 유물들은 해롭지 않은 것이지만 잠말란이 소환 의식을 위해 완벽한 숭배 마법을 발견했다면 세상은 큰 위험에 놓인 것이야...", progress = nil, completion = "오랜만에 얘기 나누는군, &lt;class&gt; 친구. 임무를 성공적으로 완수했기를 바라오.\n\n그래, 동부 내륙지에 있는 추방된 아탈라이에게서 뭘 알아냈나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1445] = {title = "아탈학카르 신전", objective = "스토나드에 있는 펠제룰에게 학카르의 우상 20개를 가져가야 합니다.", description = "잠말란의 예언에 대해 얘기했다고?\n\n아탈라이 부족의 영적 지도자는 학카르가 황천에서 아제로스로 다시 돌아오면 아탈라이 부족에게 불멸의 생을 선사해 줄 것이라 믿고 있는 모양이군. 내가 보기에는 멸망의 지름길일 뿐이야.\n\n그런데 그 유배자가 마법의 우상에 대해 얘기했다고? 흠, 매우 걱정스럽군. 이것이 정말로 이 난장판을 만든 아탈라이 의식에 대한 해답이라면 내재한 힘을 알아야만 하오.\n\n신전으로 가서 그 우상들을 가져오시오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n수호 부적"},
[1446] = {title = "예언자 잠말란", objective = "잠말란을 처치하고 그 증거로 그의 머리카락을 동부 내륙지에 있는 추방된 아탈라이트롤에게 가져가야 합니다.", description = "우리 마른나무껍질부족은 자기 집에 이방인이 들락거리는 걸 싫어한다.\n\n나? 난 이제 고향이 없어. 난 우리 부족인 슬픔의 늪의 위대한 아탈라이 부족으로부터 추방당했다.\n\n우리 부족의 영적 지도자 잠말란이 자칭 예언이란 걸 받았다고 주장했는데, 학카르를 소환해 아탈라이 부족을 불사의 존재로 만들 수 있다고 하더군.\n\n하지만 나는 부족 주민들에게 경고했다. 혹시 그 예언이 조작된 것이라면...\n\n내가 왜 추방당해야 했지? 난 복수를 하고 싶다. 잠말란을 처치하고 그의 머리카락을 가져와. 그렇게만 하면 우리 부족은 그의 압제에서 해방될 거야.", progress = "잠말란만 죽어 없어진다면 난 우리 동족들에게 돌아갈 수 있을 거야.\n\n잠말란이 영적 지도자로 남아 있는 한 아탈라이 부족은 멸망을 벗어날 수 없다.", completion = "잠말란은 무모하게 헛된 선견지명을 좇아 우리 부족을 영원한 멸망으로 이끌려고 했다.\n\n복수를 해줘서 고맙다, &lt;class&gt; 친구. 나는 우리 동족에 대해 애통하게 생각해. 이제 난... 돌아갈 고향이 없다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n폭우의 다리보호구추방자의 투구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1447] = {title = "실종된 사신", objective = "스톰윈드에 있는 다셸 스톤피스트와 싸워 이겨야 합니다.", description = "하! 스톰윈드에 올 정도로 어리석은 <class>|1이;가; 틀림없는데다가 이제는 절대 여기서 살아나가지 못한 바보 중의 바보가 되겠군.\n\n우리 애들은 아직 못 만난 모양이지?", progress = nil, completion = "그래, 날 찾아온 이유가 있을 텐데... 필요한 게 뭐요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1448] = {title = "신전을 찾아서", objective = "스톰윈드에 있는 브로한 캐스크벨리가 아탈학카르 신전을 찾아 달라고 부탁했습니다.", description = "나도 자네처럼 젊고 혈기 왕성했던 시절이 있었지, <class> 친구. 하지만 지금은 나이가 들어 예전처럼 자유롭게 세상을 탐험할 수는 없다네. 아, 정말 많은 것들을 봤었는데 말이야!\n\n그런데 아직도 해결하지 못한 일이 하나 있네. 탐험가 연맹에서는 마지막 임무로 내게 아탈학카르 신전을 찾을 것을 지시했었지. 소문에 의하면 그 신전은 슬픔의 늪에 있다고 전해지고 있네.\n\n내 몸이 허약해졌기에 그리핀을 타고 하늘을 날며 신전을 찾아 다녀봤지만 결국 찾지 못했네.\n\n이 늙은 드워프를 좀 도와주겠나? 직접 걸어다니면서 찾아 보면 찾을 수 있을지도 모르니까 말이야.", progress = nil, completion = "아탈학카르 신전이 눈물의 연못 밑으로 가라앉았다고? 그리고 그 주변을 녹색용군단들이 둘러싸고 있단 말인가?\n\n놀라운 발견이로군, &lt;class&gt;. 하지만 뭔가 크게 잘못된 게 분명하네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1449] = {title = "동부 내륙지로", objective = "동부 내륙지 맹금의 봉우리에 있는 대영주 폴스타트 와일드해머와 대화해야 합니다.", description = "전에 말했듯이, 나는 직접 하늘에서 그 신전을 찾아보려고 했었네. 흠, 정확히 말해 혼자는 아니었지만...\n\n그 때 나는 동부 내륙지의 맹금의 봉우리에 있는 그 유명한 그리핀 출격장까지 갔다네. 거기서 그들 중 가장 뛰어난 조종사 중 한 명의 도움을 얻을 수 있었지. 그 조종사는 자신이 운전하던 그리핀에서 떨어져 늪으로 추락하고 말았지...\n\n난 이제 늙어서 그 불쌍한 친구의 이름조차 기억이 나지 않아. 틀림없이 그 출격장의 조련사가 기억하고 있을 거야.\n\n그곳으로 가서 폴스타트 와일드해머를 찾도록 하게. 그 조종사가 어떻게 됐는지 알아내야 해.", progress = nil, completion = "원하는 게 뭐요, &lt;class&gt; 친구? 내가 해결해야 할 문제가 이렇게 쌓여 있는 게 안 보이오? 수다쟁이 &lt;race&gt;|1과;와; 떠들고 있을 시간은 없소이다.\n\n저 숲 속에서 트롤 놈들이 몰려 나오고 있단 말이오! 뭔지 몰라도 빨리 얘기해 보시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1450] = {title = "그리핀 조련사 탈론액스", objective = "맹금의 봉우리 출격장 안에 있는 그리핀 조련사 탈론액스와 대화해야 합니다.", description = "그래, 당신은 탐험가 연맹의 작자가 보낸 잘난 심부름꾼이란 말이지?\n\n흠, 내 말 잘 들으시오. 난 당신의 늙은 친구가 아제로스를 누구랑 같이 비행했었는지 모르오. 당신 눈엔 내가 그리핀 조련사 탈론액스로 보이오? 그런 거요?\n\n비행 임무에 그렇게 관심이 많다면 그리핀 조련사에게 물어보지 그러시오? 계속 이 주변에서 얼쩡거리고 있는 게 내 눈에 띄면 정말 힘든 일을 시킬 거요.\n\n어서 가 보시오.", progress = nil, completion = "아, 브로한 캐스크벨리를 돕도록 우리 그리핀 조종사 중 한 명을 보냈던 일은 물론 기억하고 있습니다.\n\n난 항상 탐험가 연맹에 대해 호감이 있었답니다. 사실, 우리 아버님께서 울다만을 발견한 초기 발굴조를 도왔었지요. 그래서 난 당시 최고의 그리핀 조종사를 브로한에게 보냈었습니다. 바로 랩소디 신디거라는 친구였지요.\n\n그는 정말 대단한 그리핀 조종사였습니다. 흠, 그 일이 있기 전까지는 말이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1451] = {title = "랩소디 신디거", objective = "동부 내륙지에서 랩소디 신디거를 찾아야 합니다.", description = "랩소디는 술을 아주 좋아했습니다. 정확히 말해, 이곳 출격장의 우리 드워프들은 누구나 시간만 있으면 에일 맥주 마시길 좋아하는 걸 당신도 알고 있을 겁니다.\n\n하지만 신디거, 그 친구는 그리핀이 하늘을 나는 횟수만큼이나 자주 술을 마셨죠. 정말 부끄러운 일이었지요. 그러나 누구도 랩소디처럼 비행하지는 못할 겁니다.\n\n그가 당신 친구 브로한과 함께 수행하던 임무에서 비틀거리며 돌아오던 날, 처음으로 문제의 조짐이 나타났었습니다. 그 이후로 상황은 빠르게 악화되었지요. 그래서 그를 보낼 수밖에 없었습니다.\n\n마지막으로 들은 바로는, 이곳 동쪽에 양조장을 차렸다고 하던데...", progress = nil, completion = "딸꾹!\n\n난 당신을 똑바로 쳐다보고 있는데, 왜 자꾸 위아래로 움직이는 거요? 어지럽게시리... 호호!\n\n딸꾹!\n\n우어! 방금 그거 느꼈소? 땅이 흔들리고 있군, 친구. 술을 마셔야겠어.\n\n딸꾹!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1452] = {title = "랩소디의 칼림도어 칵테일", objective = "동부 내륙지에 있는 랩소디 신디거가 로크 모래주머니 3개, 그로독 고릴라 간 3개, 무쇠곰 간 3개를 가져다 달라고 부탁했습니다.", description = "딸꾹!\n\n그래, 그 정신 나간 브로한이 당신을 보냈단 말이지? 그럼, 우린 정말 끝내 주는 모험을 했었지... 딸꾹!\n\n늪에서 무슨 일이 있었는지 듣고 싶다면 독한 술이 좀 필요한데... 그게 그러니까, 맨 정신으로 얘기할 만큼 좋은 기억이 아니거든... 딸꾹!\n\n자, 이렇게 하자고... 내가 칼림도어 칵테일을 만들 수 있도록 재료를 구해 오면 그 얘길 전부 다 해주지.\n\n타나리스의 로크 모래주머니... 그리고, 보자... 페랄라스에 있는 그로독 고릴라 간과 무쇠곰 간이 좀 필요하다고...\n\n제대로 된 칼림도어 칵테일 한 잔이면... 다 얘기해 준다니까!", progress = "랩소디 몰트를 마셔본 적이 있나? 이게 말하자면 내가 만드는 최고의 맥주 중 하나지. 딸꾹!\n\n하지만 늪... 딸꾹... 상공을 날던 그 운명적인 사건을 두려움 없이 얘기할 수 있으려면 그보다 더 독한 게 필요하다고... 딸꾹!\n\n내 칼림도어 칵테일을 좀 더 독하게 만들기 위해 필요한 모래주머니와 간을 다 구해 온 것 같지는 않은데?\n\n딸꾹!", completion = "그 재료를 다 구하는 일도 당신에겐 별로 큰 일이 아니었던 것 같군, 딸꾹! 칼림도어에서 멀리 떨어진 그곳에서 당신에게 아주 딱 맞는 일을 맡아 해냈군.\n\n이 모래주머니와 간에서 내가 필요한 걸 추출해 내는 데는 얼마 안 걸릴 거요, 딸꾹!\n\n그런 다음 멋지고 독한 술을 증류해 내고 나서, 당신이 알고 싶어하는 바로 그 얘기를 해 주도록 하지.\n\n딸꾹!\n\n그 오래된 늪에 대해 생각하는 것만으로도 몸이 다 떨리는군.\n\n딸꾹! 그럼 내 금방 술을 준비하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1453] = {title = "잊혀진 땅에서의 회수 임무", objective = "잊혀진 땅에 있는 크렐디그 운고르와 대화해야 합니다.", description = "잊혀진 땅에서 끝낼 일이 좀 있다네, <class> 친구. 그곳은 켄타우로스와 다른 나쁜 놈들에 의해 더럽혀진 끔찍한 곳이지. 좀 어려운 상황이긴 하지만 자네가 한 일주일쯤 걸릴만한 괜찮은 일거리를 찾고 있다면 크렐디그 운고르를 만나 내가 보냈다고 전하게.\n\n그는 나이젤의 야영지라는 잊혀진 땅 북쪽의 산속에 숨겨진 작고 아늑한 야영지에 있네. 돌발톱 산맥을 통해 들어가서 똑바로 동쪽으로 가면 된다네. 가다가 지나치기 쉬우니 주위를 잘 살피는 게 좋을 거야.", progress = nil, completion = "회수전문회사의 일거리가 부족하지 않다는 사실이나 도움을 주려는 모험가를 만나게 되는 건 기쁜 일이 아닐 수 없군요.\n\n내가 크렐디그입니다. 당신이 회수전문회사를 돕기로 한 건 현명한 일입니다. 요즘은 누구나 뭔가를 필요로 하고 있지요. 그들은 가족의 재산, 소중한 물건과 사랑하는 이들을 잃은 이가 대부분입니다. 이루 다 말할 수 없지만 회수전문회사에서는 합당한 가격이라면 잃어버린 걸 되찾도록 돕고 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1454] = {title = "카니톨 난파선", objective = "잊혀진 땅에서 카니톨의 궤짝을 찾아야 합니다.", description = "내가 첫 번째로 처리해야 할 일은 스톰윈드의 귀족 중의 한 명인 마법사 카니톨이 의뢰한 일입니다. 그분의 배가 잊혀진 땅의 북서쪽 바다에 출항 중인 동안 바다 거인의 공격을 받았나 보더군요. 그분과 그의 부하들이 귀중한 궤짝 중 하나를 해변으로 가져오려 했지만 바다 거인이 떼로 공격하는 바람에 궤짝을 포기하고 안전 지대로 공간 이동을 할 수밖에 없었다고 합니다.\n\n그분은 그 상자와 내용물을 찾아 스톰윈드로 가져다주길 원하고 있습니다.", progress = nil, completion = "상자를 살펴보니 물에 의한 손상은 전혀 없는 것 같습니다.\n\n그리고 오래전에 누군가 궤짝의 상단을 억지로 열어 궤짝을 보호하고 있던 어떤 마법 함정이 작동했던 것으로 보입니다. 궤짝 가장자리에 불에 탄 자국이 있는 것으로 보아 확실한 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1455] = {title = "카니톨 난파선", objective = "잊혀진 땅에 있는 크렐디그 운고르에게 돌아가야 합니다.", description = "누가 상자를 열었는지 알아내기 위해 잠시 살피다가 궤짝의 양 옆과 위에 길고 깊게 긁힌 자국이 있음을 발견합니다. 이것으로 보아 사람이나 거인이 아닌 다른 누군가가 상자에 관심을 가졌던 것 같습니다. 자국은 검이나 단검에 의해 생긴 자국으로 보이지 않습니다.\n\n궤짝을 자세히 살펴본 후 상자가 완전히 비어 있다는 사실을 알게 됩니다.\n\n더 이상 살펴보지 않고 궤짝을 닫은 후에 떠날 채비를 합니다. 크렐디그가 실망할 것 같습니다.", progress = nil, completion = "나이젤의 야영지에 돌아온 것을 환영합니다. 그래, 뭘 찾아냈습니까?\n\n뭐라고요!? 아무것도 없었단 말입니까? 빈 궤짝은 가져가 봤자 보수도 못 받을 텐데...\n\n당신이 보았다는 그 긁힌 자국에 대해 자세히 얘기해 보세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1456] = {title = "카니톨 난파선", objective = "카니톨의 가방을 찾아 잊혀진 땅에 있는 크렐디그 운고르에게 가져가야 합니다.", description = "흥미롭군. 흠, 아직 희망이 완전히 사라진 건 아닌 것 같습니다.\n\n그 쪽 해안을 따라 북쪽으로 라나즈자르 섬 근처로 가면 바다 밑바닥에 나이트 엘프 폐허가 있습니다. 지금은 나가인 뱀갈퀴 일족이 그곳에 자신들의 터전을 만들었지요. 아무래도 놈들의 짓일 가능성이 제일 큰 것 같군요.\n\n정찰대가 남쪽으로 그렇게 멀리 왔었다면 굉장히 강한 녀석들일 겁니다. 카니톨님의 물건들을 찾을 생각이라면 나가들 중에서 특히 강한 바다사냥꾼이나 바다마녀들부터 조사해 보는 게 좋을 겁니다.", progress = "나이젤이 누군지는 모르지만 이 야영지는 밤을 지내기에 썩 편한 곳은 못 되는군요. 당신도 느끼고 있겠죠?", completion = "훌륭합니다! 카니톨님의 물건들을 찾았군요. 회수전문회사를 위해 정말 큰 일을 해 주었습니다.\n\n저 괘씸한 나가들은 늘 문제를 일으킨단 말이야. 놈들을 상대하느니 차라리 호드와의 전쟁에 내 인생을 바치는 게 낫겠네요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1457] = {title = "카니톨 난파선", objective = "아이언포지에 있는 로이튼 스톤해머에게 카니톨의 가방을 가져가야 합니다.", description = "카니톨님의 물건들을 아이언포지에 있는 로이튼에게 가지고 돌아가면 대가를 지급해 줄 겁니다.\n\n하하, 자칫하면 로이튼이 당신이 너무 맘에 든 나머지 당신더러 우리 회사에 눌러앉으라고 할지도 모르겠는걸요.\n\n두말하면 잔소리겠지만, 정말 일을 잘 처리해 주었습니다.\n\n돌아오는 길에 조심하도록 하고 너무 오래 지체하지 마세요. 카니톨님은 <race>들을 썩 좋아하지는 않지만 특별히 인색하지도 않으니까요.", progress = "사업이 워낙 잘 되다 보니 질문에 대답해 줄 시간이 별로 없군. 자, 회수전문회사에 볼일이 있거든 어서 말해 보게. 나한테 할 말이 없으면 내 아래 직원들에게 가 보지 그래. 우리 직원들도 여기서 웬만한 일은 다 처리할 줄 아니까 말이야.", completion = "아, 잊혀진 땅의 카니톨 일이로군. 아주 잘 됐어!\n\n그러니까, 상자는 부서졌지만 내용물은 모두 무사히 돌아왔단 말이지? 뭐, 그거야 그가 직접 봐야 알 일이고. 여기서 진행 중인 이 사업의 장점은 의뢰자가 만족하지 않더라도 물건을 떠맡으라고 할 수 있다는 것이야! 그들은 우리가 자기들 물건을 찾아 주길 바라는 거지만... 찾았을 때 모든 물건이 반드시 온전하고 상태가 좋도록 해달라는 건 아니거든.\n\n수고했으니 이제 사례를 하지.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n폭군 장화핏빛 어깨갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1458] = {title = "회수전문회사를 위한 재료", objective = "잊혀진 땅에 있는 크렐디그 운고르에게 서릿발분노의 사티로스 발톱 10개와 서릿발분노의 사티로스 뿔 10개를 가져가야 합니다.", description = "이곳에서의 내 임무 중 하나는 카라노스에 있는 노움 마법사인 레프트위치를 위해 재료를 모으는 일입니다. 로이튼은 이미 우리가 이곳에 온 이상 재료를 구하는 건 식은 죽 먹기라고 생각하는 것 같아요. 그는 보다시피 일손이 부족하다는 사실은 별로 신경 쓰지 않는다니까요.\n\n그의 목록에서 처음 몇 가지는 구하기도 쉬울 것이고 내 대신 다른 이가 하더라도 아주 수월하게 일을 마칠 수 있을 겁니다.\n\n동쪽에 있는 서릿발분노의 사티로스 뿔과 발톱이 필요하니 좀 가져다주세요. 우선 그 일을 마친 후 나머지 재료를 찾도록 하죠.", progress = "사티로스는 비열한 짐승입니다. 놈들이 나이트 엘프와 무슨 관련이 있다는 이야기가 있지만 난 그다지 믿지 않는 편입니다.\n\n내 생각엔 몇 해 전에 놈들을 전쟁에 끌어들인 한 엘프 때문에 그런 이야기가 나오게 된 것 같아요. 그때 이후로 세상은 훨씬 더 위험하고 무서운 곳으로 변했지요.", completion = "좋아요, 좋아. 가져온 재료의 품질이 좋은지 어떤지는 잘 모르겠습니다. 레프트위치가 특별한 종류를 원했다면 회수전문가를 이곳에 보내 임무를 시작하기 전에 미리 말해 줬어야 하는 거였으니까...\n\n그의 목록에 있는 다른 것들도 찾아보겠습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1459] = {title = "회수전문회사를 위한 재료", objective = "잊혀진 땅에 있는 크렐디그 운고르에게 스콜파시 독 7병과 늙은 코도 통가죽 3개를 가져가야 합니다.", description = "레프트위치가 필요로 한 목록의 다음 항목은... 어디 보자... 흠. 아, 여기 있군요.\n\n간단한 항목이지만 그의 지시 사항이 까다롭습니다. 그는 스콜파시의 독액과 코도의 통가죽을 필요로 하고 있어요. 그런데 둘 다 특정한 생물에서 취한 것이어야만 한다고 되어 있습니다. 독액은 아무 스콜파시 전갈에게서나, 그리고 통가죽은 죽어가는 코도나 고대 코도의 것이 아니라, 반드시 늙은 코도의 것을 가져와야 합니다.\n\n당신한테니까 하는 얘기지만, 마법사들이 찾는 것들 중에는 별 희한한 게 다 있단 말입니다, 쩝...", progress = "코도나 스콜파시를 어디서 찾아야 할지 얘기해 주지 못해 미안합니다. 안타깝게도 난 이 지역에 그렇게 익숙하지도 않고 탐험해 볼 시간도 없었답니다.", completion = "당신의 도움은 내게 큰 힘이 되는군요. 당신 덕분에 내가 이곳 잊혀진 땅에 머물러야 할 시간이 최소한 반 이상은 줄어든 것 같습니다. 덕분에 곧 아이언포지로 돌아가 따뜻하게 발을 녹일 수 있겠군요.\n\n이 목록에 있는 것들을 다 구하고 나서 내가 고향으로 돌아가면 나를 찾아오세요. 내 꼭 에일 맥주라도 한잔 대접하도록 하죠.\n\n그때까지 나머지 재료들을 어서 모읍시다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1462] = {title = "대지의 정기", objective = "예언자 레이븐페더에게 대지의 정기를 하나 더 부탁해야 합니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n대지의 정기"},
[1463] = {title = "대지의 정기", objective = "카나가 어스콜러에게 대지의 정기를 하나 더 달라고 부탁하십시오.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n대지의 정기"},
[1464] = {title = "불의 정기", objective = "텔프 줄람에게 불의 정기를 하나 더 부탁하십시오.", description = nil, progress = nil, completion = "자네의 가슴 속에 불길이 타오르기를...\n\n자연의 원소들이 자네를 기다리고 있네.", rewards = "다음과 같은 것들을 받습니다:\n\n불의 정기"},
[1465] = {title = "발라리엘의 수색", objective = "잊혀진 땅에 있는 발라리엘 데몬슬레이어에게 말렘 펜던트를 가져가야 합니다.", description = "계속해서 마차를 수색하다가 남쪽으로 향하는 발자국과 팬던트를 발견했습니다. 멀리 큰 성채에서 연기가 피어 오르는 것이 보입니다. 건물이 타면서 나는 것이 아니라 누군가 일부러 피워놓은 불에서 나는 연기로 보입니다. 본능적으로 말렘가의 아이들이 아직 살아있으며 연기가 나는 방향으로 잡혀갔다는 느낌이 듭니다.\n\n나이젤의 야영지에 있는 발라리엘에게 발견한 펜던트와 남쪽으로 향하는 생명의 흔적에 대해서 알려야 할 거 같습니다.", progress = nil, completion = "그럴 수가! 정말 낭패로군!\n\n그 아이들에게 여기 오는 건 위험하다고 그렇게나 일렀었는데. 이제 둘 다 잃어버렸군. 어쩌면 더 큰 일이 일어난 것인지도...\n\n근처에 있는 성채로 발자국이 나 있었다고 했소? 거기에 희망을 걸어봐야겠소이다.\n\n이 지역 주민들 말로는 그 성채에는 악마의 뜻을 따르는 오크 무리인 불타는칼날단 무리가 득실거린다고 하오. 대부분의 호드는 그렇지 않을지도 모르지만 그 녀석들은 워낙 사악해서 당신이 염탐하는 걸 보면 즉시 죽이려 들 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1466] = {title = "회수전문회사를 위한 재료", objective = "잊혀진 땅에 있는 크렐디그 운고르에게 지옥사냥개 뇌 10개, 황천의 날개 10개, 파멸의경비대 혈액 10병을 가져가야 합니다.", description = "이제 마지막 항목들입니다. 그리고 솔직히 말해서 이번엔 쉬운 대상이 아닙니다. 아마 다른 것들보다 시간도 더 걸릴 겁니다.\n\n자, 경고는 충분히 했으니 이제 시작해 봅시다. 레프트위치가 필요하다고 한 것들은 다음과 같습니다. 마나먹는 지옥사냥개나 마법사 사냥개, 또는 평원의 지옥사냥개의 뇌 10개, 황천의 요녀나 마녀, 여마법사에게서 황천의 날개 10개, 그리고... 파멸의경비대 부대장이나 우두머리의 혈액 10병입니다.\n\n간단하지 않습니까? 뭐, 당신이 이번 건 그만두겠다고 해도 내 이해하도록 하죠.", progress = "난 이런 악마 같은 존재들이 잊혀진 땅에 있다는 사실조차 몰랐답니다. 내가 마지막으로 읽은 건 몇 해 전 나이트 엘프들이 짐을 챙겨 떠난 후에 켄타우로스가 이 땅의 꽤 많은 부분을 차지했다는 소식이었습니다.\n\n난 그들이 왜, 그리고 어떻게 이곳을 차지하게 되었는지 궁금하답니다.", completion = "솔직히 얘기하자면, 당신이 해내리라고는 생각하지 않았습니다. 당신 정말 대단하군요. 마법사의 실험을 위해 악마들을 상대하고, 게다가 무사히 돌아오다니... 정말 훌륭합니다!\n\n아이언포지에 돌아가면 개인적으로 로이튼에게 당신 이야기를 해야겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1467] = {title = "회수전문회사를 위한 재료", objective = "아이언포지에 있는 로이튼 스톤해머에게 레프트위치의 소포를 가져가야 합니다.", description = "보수를 받으려면 아이언포지로 가서 로이튼에게 직접 말해 보세요. 어쨌든 그는 레프트위치의 소포를 빨리 처리하고 싶어할 테니까요. 이걸 그에게 건네 주기만 하세요. 그럼 반드시 당신 보수를 줄 겁니다.\n\n그리고 내가 돌아가면 당신에 대해 잘 얘기해 둘 테니 걱정 마세요. 난 잊혀진 땅에 그리 오래 머무르진 않을 겁니다.", progress = "만나서 반갑네. 사업은 잘 되지, 망치로 모루를 두들기는 소리가 아이언포지 전체에 쩌렁쩌렁 울려 대고 있지, 대장간에서는 불이 활활 타오르는데다가, 집에서는 마누라가 오늘 저녁 식사 후에 디저트로 파이를 구워준다는군. 이보다 더 멋진 삶이 있겠나?", completion = "아, 잊혀진 땅에서 레프트위치에게 전해 줄 소포를 가져왔군. 아주 잘 됐어. 제때에 물건을 가져와 줘서 고맙네, &lt;class&gt;. 비록 간단한 일이지만 자네가 우릴 도와줘서 기쁘군.\n\n자, 여기 자네에게 주는 보수일세. 회수전문회사에서는 항상 열심히 일한 대가를 넉넉히 지급한다고 소문 좀 내 주게나.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n황금 팔보호구불폭풍 건틀릿\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1468] = {title = "어린이 주간", objective = "인간 고아 호루라기를 사용해 어린이 주간 동안 돌보게 될 아이와 대화하십시오.\n\n제공된 아이템: \n", description = "여기 보육원 일을 돕고 싶으시다고요? 하늘의 축복이 있으시길. 어린이 주간 동안 도와주신다면 정말 너무 감사할 거예요.\n\n이 호루라기를 받으세요. 이 호루라기는 어린이 주간에만 사용할 수 있어요. 호루라기를 한 번 불면 당신이 돌봐주기로 한 아이와 얘기를 나눌 수 있고 다시 한 번 더 불면 아이를 보낼 수 있죠.\n\n부디 이 호루라기를 사용해 당신이 돌볼 아이와 만나보세요! 누구보다 당신을 만나고 싶어할 거예요.", progress = nil, completion = "어... 안녕하세요. 제 이름은 랜디스라고 해요. 절 돌봐주실 분이죠? 우리 엄마, 아빠처럼 모험가시네요. 형을 만나게 돼서 무척 좋아요.\n\n함께 재밌는 거 많이 했으면 좋겠어요. 실은 하고 싶은 일이 몇 가지 있거든요. 우리 원장님이 그러시는데 이번 주에 제 형이 되어주신다면서요? 헤헤, 정말 너무 좋아요.", rewards = nil},
[1469] = {title = "랩소디의 이야기", objective = "스톰윈드에 있는 브로한 캐스크벨리에게 아탈라이 서판 조각을 가져가야 합니다.", description = "비행하기 전에 난 스타우트 맥주 한 통을 전부 다 마셨었지. 딸꾹!\n\n정말 대단한 비행이었어. 힘차게 날았지. 브로한은 내 뒤에서 따라오고 있었고... 그런데 신전이라곤 어디에도 보이지도 않는 거야. 딸꾹!\n\n흠, 너무 심하게 취해서 조종석에서 떨어지기 전까지는 신전 코빼기도 못 봤단 말이지. 난 곧장 물속으로 떨어져 가라앉았어. 그리곤 섬뜩한 트롤 무리가 날 둘러싸고 있다는 걸 알게 됐지. 물론 재빨리 헤엄쳐 나왔지! 게다가 이 트롤 기념품까지 가지고 나왔다고. 자, 이걸 브로한에게 가져다주고 그 깊은 곳에 정말 신전이 있다고 알려 주라고. 딸꾹!", progress = "마침내 돌아왔군. 정말 오랜만이야... 난 자네가 내 부탁을 잊은 줄 알았지.\n\n그래, 그 그리핀 조종사는 찾았나? 그가 뭔가 얘기해 주던가?", completion = "랩소디 신디거! 그래 맞아... 어떻게 그 이름을 잊을 수가 있었지?\n\n그래, 그는 신전이 가라앉았다는 사실을 전부터 알고 있었단 말이지? 흠, 덕분에 자네는 직접 걸어서 신전을 찾아 헤매야 할 수고를 덜었겠군.\n\n그리고 이 아탈라이 유물! 아, 이건 정말 엄청난 발견일세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1470] = {title = "저 너머의 세계", objective = "벤야 말선드에게 덜그럭거리는 해골 3개를 가져가야 합니다.", description = "어서 오세요. 흑마법사치고는 아직 미숙해 보이는군요. 아직 흑마법의 힘을 자기 것으로 만들지 못했으니 당연한 겁니다. 배우고자 하는 열의가 대단하군요. 이제 곧 흑마법의 힘을 제대로 배우게 될 겁니다.\n\n무지한 자는 힘을 가질 수 없으며 지식이야말로 우리의 가장 큰 힘입니다. 지식을 사용해 혼란스러운 마법과 허공에 떠도는 존재들을 제어하고 우리 의지대로 조종할 수 있게 되는 것이지요.\n\n자, 그럼 이제 종복을 자신의 의지대로 조종하는 방법을 보여 주겠어요. 하지만 먼저 버려진 대장간 근처에서 덜그럭거리는 해골 세 개를 내게 가져와야 합니다.", progress = "당신의 힘은 아직 미약하지만 스스로 가능성을 직감하고 있을 겁니다.\n\n우리 안에 흐르는 그 힘을 통해 죽은 자들도 살아 숨 쉬는 것처럼 느끼게 될 겁니다.", completion = "당신의 실력은 아직 검증되지 않았으며 배우기 시작한 지도 얼마 되지 않았습니다. 그러나 임프를 소환하는 방법과 결속을 익히기에 충분한 능력이 있다는 것을 보여 주었습니다. 임프의 크기만 보고 섣불리 판단해서는 안 됩니다. 신체적인 힘은 부족할지 몰라도 당신에게 큰 도움이 될 마법과 영특함을 지니고 있는 존재니까요.\n\n내 말을 잘 새겨들으세요. 다시 온다고 해도 같은 가르침은 받지 못할 것이며 기술을 익히는 건 당신의 몫이니까요.", rewards = "다음과 같은 것들을 배웁니다:\n\n임프 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n임프 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1471] = {title = "결속", objective = "소환의 룬을 사용하여 보이드워커를 소환하여 제압한 다음 언더시티의 마법 지구에 있는 카렌딘 할가르에게 소환의 룬을 가지고 돌아가야 합니다.", description = "우리 뒤에 있는 소환의 마법진은 이미 보았겠지? 그곳에서만 구속되지 않은 보이드워커를 끌어낼 수 있네.\n\n이 룬을 사용하여 보이드워커를 끌어낸 다음 자네가 지닌 무기와 마법의 힘으로 제압해야 하네.\n\n그런 후에 자네의 명령을 따르게 되면 내게 다시 오게. 자네가 원하는대로 보이드워커를 부릴 수 있도록 해주는 소환 주문을 알려 주도록 하지.", progress = "자네가 성공했다는 소식을 기대하고 있네. 하지만 만약 실패한다면 단순히 내 기대에 미치지 못하는 게 문제가 아니라 더 큰 화를 입게 될 거야.", completion = "잘했네. 이제 보이드워커 소환에 사용되는 주문을 알려 주겠네.\n\n소환된 보이드워커는 이제 자네의 명령을 따르게 될 거야. 그 힘을 현명하게 사용하게.", rewards = "다음과 같은 것들을 배웁니다:\n\n보이드워커 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n보이드워커 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1472] = {title = "영혼에 굶주린 자", objective = "저주의 사원에 있는 고드릭 파선과 대화해야 합니다.", description = "세이야드는 영혼을 사로잡고, 의지를 지배하며, 마음을 쥐락펴락하는 존재일세. 깊은 악으로 가득 차 있고 기이한 정신을 소유한 피조물이야.\n\n전설에 따르면 정의로운 자와 악한 자 모두 같은 이름으로 그들을 부른다네. 여자 악마는 서큐버스, 남자 악마는 인큐버스라고 하지.\n\n악마를 우리 세계로 데려오려면 자극제가 필요해. 순수한 사랑으로 가득한 필멸자들의 심장 말이야. 세이야드도 탐내지 않고는 못 배길 거야. 그런 다음 자네에게 복종시키면 부릴 수가 있지.\n\n사원 안에 있는 내 조수 고드릭 파선과 얘기해 보게. 그가 미끼 찾는 걸 도와줄 거야.", progress = nil, completion = "카렌딘님께서 보내셨다고요? 그렇다면 당신이 &lt;name&gt;씨군요.\n\n내 눈이 안 보인다고 해서 얕보지는 마세요. 이제는 눈이 보였던 때보다도 더 뚜렷하게 사물을 볼 수 있으니까요. 저주라고 생각했던 게, 오히려 이제 축복이 된 거죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1473] = {title = "공허의 피조물", objective = "에갈린의 흑마법서를 되찾아 저주의 사원에 있는 카렌딘 할가르에게 가져가야 합니다.", description = "여러 면으로 보아 이제 자네도 보이드워커 소환을 배울 때가 된 것 같네.\n\n보이드워커는 저 너머의 혼돈에서 만들어진 존재지. 자네가 보이드워커를 소환하고 나서 제어하지 못한다면 자네는 갈가리 찢기고 말 거야.\n\n최초로 보이드워커를 소환한 건 에갈린님이셨는데, 그분의 흑마법서에 소환 과정에 대해서 기술되어 있다네.\n\n안타깝게도, 그 흑마법서는 한 붉은십자군 녀석에게 도둑맞았는데, 놈은 그걸 서쪽 탑에 있는 그의 기지에 숨겨 놓았어. 그걸 내게 가져오면 자네에게 그 방법을 가르쳐 주지.", progress = "에갈린님께서는 나의 스승이셨네. 그분은 눈을 감고도 소환한 보이드워커를 제어할 수 있었어.\n\n나도 시도해 보았지만 지나친 자만심일 뿐이었네. 자네의 힘을 함부로 사용하지 말게나. 신중을 기하더라도 자칫 화를 당할 수가 있으니 말이야.", completion = "아주 훌륭하군. 페린은 우리에게서 훔쳐 간 낡은 책이 지닌 진정한 힘에 대해 모르고 있었어.\n\n다시는 이 책이 우리 손을 떠나는 일이 없을 거야. 보게, 주문의 구조, 자네의 힘을 가해야 할 방식이 적혀 있군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1474] = {title = "결속", objective = "순수한 심장을 사용하여 서큐버스를 소환하여 제압한 다음, 언더시티에 있는 마법 지구에 있는 카렌딘 할가르에게 순수한 심장을 가져가야 합니다.", description = "이 심장들을 가지고 소환 마법진으로 가서 서큐버스가 나올 수 있는 입구를 열도록 하게. 이제 자네의 힘은 예전보다 강하니 그 힘을 모두 발휘해서 서큐버스를 이겨 내야 해.\n\n아무리 정신력이 강한 이들도 서큐버스에게 지배되어 버리는 경우가 많았으니 서큐버스의 매력에 현혹되지 않도록 조심하도록 하게. 서큐버스의 유혹을 견뎌내면 허공으로 돌아가게 될 거야. 그러면 자네의 명령에 따르도록 하는 소환 주문을 가르쳐 주겠네.", progress = "저 공허한 공간 너머의 세력들 중에서 서큐버스는 가장 위험한 존재 중 하나라네. 나약한 이들은 너무나 쉽게 그 손아귀에 싸여 넘어가 버리니까 말이야.\n\n지금부터 항상 이 사실을 명심하도록 하게.", completion = "또 잘해냈군. 자네처럼 재주가 뛰어난 젊은 &lt;class&gt;는 오랫동안 보지 못했네. 계속 자네의 성장 속도를 주의 깊게 지켜보도록 하지. 그리고 앞으로의 모험을 위해 자네가 성장할 수 있도록 도와주겠네.\n\n우선 지금은 자네가 새로 부리게 된 서큐버스 소환 주문을 가르쳐 주지.", rewards = "다음과 같은 것들을 배웁니다:\n\n서큐버스 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n서큐버스 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n작은 영혼의 가방"},
[1475] = {title = "아탈학카르 신전으로", objective = "스톰윈드에 있는 브로한 캐스크벨리에게 아탈라이 서판 10개를 가져가야 합니다.", description = "전설에 의하면 아탈학카르 신전은 고대 신, 학카르를 모시는 신성한 제단이라고 하네. 소문에 듣기로 이 신전은 아탈라이라는 사나운 트롤 부족이 지키고 있는 난공불락의 요새라고 하더군.\n\n이제는 슬픔의 늪 아래로 가라앉아 버렸으니 신전에서 유물을 되찾는 일은 더욱 힘들어졌군. 그러나, 바로 이것이 자네가 해주어야 할 일이야.\n\n나를 도와 손상되지 않은 아탈라이 서판을 가져와 주게. 그걸 가져오면 나는 영웅이 되어 탐험가 연맹으로 돌아갈 수 있을 거야. 나와 자네가 함께 그 영광을 누릴 수 있을 걸세.", progress = "이제 일을 계속해 나갈 희망이 점점 사라지고 있어. 탐험가 연맹에서의 마지막 임무를 마치기 위해선 자네의 도움이 필요하네. 늙은 몸이지만 슬픔의 늪과 가라앉은 신전을 용기있게 헤쳐나갈 힘만 있다면 자네 바로 옆에서 함께 싸울 텐데...\n\n자존심 때문에 아탈라이 서판을 모아 달라고 도움을 청하는 게 쉽지는 않지만 나이가 들어 어쩔 수가 없군.\n\n제발 날 도와주게. 마지막 임무를 마친 후 연맹에서 은퇴했으면 하네.", completion = "아탈라이 서판이군! 고맙네!\n\n이것들을 탐험가 연맹에 가져다준다면 우리의 이름과 함께 역사에 남게 될 거야. 이 늙은 드워프가 생의 마지막 임무를 완수하는 것을 도와주었으니 영원히 자네에게 감사하는 마음을 간직하도록 하겠네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n수호 부적"},
[1476] = {title = "선한 자의 유품", objective = "저주의 사원에 있는 카렌딘 할가르에게 달린의 유품과 코마의 유품을 가져가야 합니다.", description = "서큐버스를 회유하려면 순수한 자의 물건이 필요해요. 하지만 악함이 없는 필멸자가 세상에 존재할까요?\n\n우연히 듣게 된 얘기에서 그럴 만한 사람을 두 명 알아냈어요.\n\n첫 번째는 자신들의 일가로부터 버림받은 로데론 난민들을 헌신적으로 보살피고 있는 달린 포지라이트라는 자로 그레이메인 성벽에 있어요.\n\n두 번째는 사라진 아내의 흔적을 찾아 저습지를 헤매며 잃어버린 아내에 대한 사랑을 여전히 간직하고 있는 코마 빌라드라는 자죠.\n\n그들의 유품을 카렌딘님께 가져가세요. 하지만 먼저 이 목표물들을 보여 드리지요.", progress = "지금까지의 자네의 놀라운 성장 속도를 보니 유쾌하군. 자, 유품을 가져와서 다시 나를 감동시켜 보라고.", completion = "이 유품을 보니 순수한 자의 소지품도 다른 이들과 별로 다를 게 없어 보이는데, 안 그런가?\n\n뭐, 우리가 좀... 다른... 관점으로 바라봐서 그럴지도 모르겠지만 말이야. 어쨌든 이거면 충분하겠어. 서큐버스는 분명 그들의 순수함에 끌리게 될 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1477] = {title = "중요한 보급품", objective = "순찰대장 소리갈을 만나 이야기를 나눠야 합니다.", description = "내 밑의 마법사들을 저주받은 땅으로 보냈네. 거기서 네더가드 요새를 탐색하여 어둠의 문에 대한 비밀을 밝히는 데 반드시 필요한 정보를 찾으라고 지시했지. 그들에게 보급품을 지속적으로 보내줘야 하는데... 요즘은 네더가드 요새로 가는 이를 구하기가 하늘의 별 따기란 말이지.\n\n흠, 자네라면 네더가드 요새로 보급품을 전달해줄 수도 있을 듯하네만. 다크샤이어의 순찰대장 소리갈을 찾아서 보고하게. 아마 그가 직접 자네에게 지시를 내릴 거야. <name>, 그곳에는 적들이 득실거리고 있으니 정신 바짝 차려야 하네.", progress = nil, completion = "안드로매스가 보냈다고? 흠, 아주 잘 왔네... 마침 중요한 일을 맡아줄 이를 찾고 있었는데 자네가 딱 적임자 같군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1478] = {title = "할가르의 부름", objective = "언더시티에 있는 카렌딘 할가르와 대화해야 합니다.", description = "아! 방금 카렌딘 할가르님께서 앞으로의 훈련을 위해 당신을 만나고 싶다는 소식이 왔습니다.\n\n할가르님께서 개인적으로 직접 당신과 같은 젊은 흑마법사를 훈련하시다니 매우 자랑스럽겠군요.\n\n언더시티의 저주의 사원 근처에 있는 마법 지구에 가면 그분을 만날 수 있을 겁니다.", progress = nil, completion = "좋아. 마침내 아제론이 자네를 찾아냈군. 잠시 즐겁게 이런저런 얘기를 좀 나누고 나서 본격적으로 훈련에 들어가도록 하지. 아직 배워야 할 게 많다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1479] = {title = "영원의 줄기", objective = "랜디스를 다르나서스 은행에 데려다 주어야 합니다. 은행 자체는 영원의 줄기라고 알려진 나무 안에 있습니다.", description = "나이트 엘프들은 곰처럼 생긴 나무 안에 은행을 두고 있다는 얘기를 들은 적이 있어요! 너무 근사하지 않아요? 나이트 엘프들이 자연을 좋아하는 것도 멋진데, 곰 모양이라니 정말이지 너무 멋져요!\n\n그 곰나무를 볼 수 있게 절 다르나서스에 데려다 주지 않으실래요? 그 근처로 가는 배도 있으니 그리 오래 걸리지는 않을 거예요. 제발, 제발, 제발요!", progress = nil, completion = "우와. 상상했던 것보다 훨씬 멋지네요. 이게 영원의 줄기군요! 이렇게 클 줄은 몰랐어요! 그 위에 있던 새도 보셨어요?! 어떻게 나뭇가지를 그런 모양으로 만들었을까요?\n\n다르나서스에 데려다 줘서 고맙습니다. 형은 정말 멋져요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1480] = {title = "타락자", objective = "잊혀진 땅에 있는 마우린 본스플리터에게 악마의 가죽을 가져다주십시오.", description = "부드러운 가죽은 찢겨져 있고 썩은 냄새가 진동하고 있습니다.\n\n가죽을 펼치자 한쪽 면에 어떤 언어로 쓰인 붉은 색 표시가 선명히 보입니다. 맨 아래쪽에는 일종의 서명으로 추측되는 기호가 선명히 새겨져 있습니다.\n\n어쩌면 마우린이 이 가죽에 대해 좀 더 자세히 알려줄 수 있을지도 모릅니다.", progress = "불타는칼날단이 자신들이 실로 얼마나 나약한 존재인지 깨닫기 시작하는군. 사실 놈들의 마법은 보잘것없고 힘도 약하다오.\n\n놈들이 섬기는 자들이 힘을 주지 않으면 한낱 허수아비에 불과하지. 그들의 힘과 지식은 스스로 얻은 게 아니오.", completion = "흠, 이 룬은 일종의 언어, 아주 오래된 언어가 틀림없소. 언뜻 보면 에레둔어와도 유사한 듯하지만 차이가 상당히 크군. 내 생각이 맞다면 일종의 계약서 같은데... 그래, 여기, 여기 이 기호는 제왕 아즈레토크라는 악마의 서명이군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1481] = {title = "타락자", objective = "잊혀진 땅에 있는 마우린 본스플리터에게 그림자추적자 머릿가죽을 가져가야 합니다.", description = "적합한 재료만 구할 수 있다면 이 악마 군주를 찾아낼 수도 있을 것 같소.\n\n그 악마가 내 생각만큼 강력하다면 사납고 무서운 짐승들로부터 여러 가지 재료를 구해야지. 당신은 대족장님의 이름을 걸고 활동하고 있는 만큼 기꺼이 이 임무를 맡으리라 믿소.\n\n우선 군주가 사용하는 방벽을 모두 파괴해 수정점을 피해야 하오. 이를 위해서는 사티로스의 가죽이 필요하지. 하지만 아무 사티로스의 가죽이나 사용할 수 있는 건 아니오.\n\n서릿발분노의 그림자추적자에게서만 구할 수 있지. 잊혀진 땅 북동쪽에 있는 고대의 유적지로 가면 찾을 수 있을 거요.", progress = "제대로 된 가죽을 가져와야 하오, <class>. 조그만 실수에도 우리는 죽임을 당할 수 있소. 악마 군주가 그에게 수정점을 치려는 이들을 처치하려다가 실수로 자신의 부하들에게 치명적인 주문을 걸었을 수도 있단 말이오.\n\n운명은 이미 내게 충분한 고통을 주었소. 더 이상은 원하지 않아...", completion = "그림자추적자들도 당신 적수는 못 됐나 보군. 훌륭해... 정말 훌륭해!\n\n이 가죽이라면 딱이야! 당신이 가죽을 구하러 간 동안 나는 주문에 필요한 재료 몇 가지를 더 구해 두었소.\n\n이제 준비도 거의 끝났으니 나는 주문을 완성하는데 집중해야겠소. 악마 군주의 실체와 그 본거지를 볼 수 있게 해줄 주문을...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1482] = {title = "타락자", objective = "잊혀진 땅에 있는 마우린 본스플리터에게 예언의 수정구를 가져가야 합니다.", description = "예언의 수정구만 있다면 좋을 텐데... 예언의 수정구는 나가들이 계시를 받기 위해 만드는 것이오.\n\n해안을 따라 북서쪽으로 가면 해안 근처에 나가들이 살고 있는 거대한 산호초가 있소. 거기서 수정구를 구할 수 있을 거요. 뱀갈퀴 나가족들은 매우 위험하고 당신이 침입하면 그냥 보고만 있지는 않을 테니 조심해서 일을 처리한 후 신속히 돌아오도록 하시오.\n\n당신이 돌아오면 제왕 아즈레토크를 찾을 수 있을 거요.", progress = "예언의 수정구를 사용할 준비를 해두었소, <class>. 제왕 아즈레토크를 찾아 처치한다면 대족장님께서 우리 둘 모두에게 큰 상을 내리시겠지. 우리가 힘을 합쳐 신속히 일을 처리한다면 분명 대족장님의 신임을 얻게 될 거요.", completion = "귀하디 귀한 예언의 수정구... 흠집 하나 없고 정말 아름답군.\n\n즉시 시작해야겠소. 악마 군주를 찾아내는 것이 우리의 최우선 과제이고, 그를 처치하기 위해서는 할 수 있는 한 최선을 다해야 하오.\n\n뒤로 한 발 물러서시오, &lt;class&gt;. 이제 이 악마가 어떤 모습인지, 그리고 어디에 있는지 한번 봅시다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1483] = {title = "지즈 피직스", objective = "칼바람 바위산에 있는 지즈 피직스와 대화하십시오.", description = "투자개발회사에서 최고의 고블린들을 포섭해 다수 빼내 갔지만 우린 그들을 되찾아 올 수 있는 기회를 노리고 있지.\n\n얼마 전 돌발톱 산맥에 있는 투자개발회사 지부에서 게렌조 렌치휘슬이라는 노움을 새로 고용했다네. 이에 위기의식을 느낀 다른 기술자 지즈 피직스가 내게 땜장이 조합을 위해 일하게 해 달라고 간청하지 않았겠나? 그래서 그에게 몇 가지 임무를 맡겼는데, 아마 도움이 필요할 거야.\n\n자네가 날 위해 그를 찾아서 좀 도와주겠나? 그는 칼바람 바위산의 서쪽 경계에 배치되어 있다네.", progress = nil, completion = "안 그래도 투자개발회사의 상관들이 아랫사람을 노예처럼 부린다고 생각하던 중에 하필 그 중 제일 지독한 스퍼터밸브를 만나게 된 거요!\n\n일자리가 없는 것보다야 낫지만... 그렇지 않으면 게렌조와 함께 일을 해야 할 판이었으니까 말이오. 그건 더 못할 짓이지... 혹시 날 도와주러 여기 온 거라면 당신이 해줬으면 하는 일이 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1484] = {title = "타락자", objective = "잊혀진 땅에 있는 타카타 스틸블레이드와 대화하십시오.", description = "이 악마는 내가 생각했던 것보다 훨씬 더 위험하오. 방금 일어났던 일에 대한 소식을 타카타에게 알리지 않으면, 분명 그의 자존심이 다칠 것이오. 듣고 나면 그런 악마를 다룰 능력이 내게 있는지 의심하겠지만...\n\n타카타를 만나서, 만약 그가 허락한다면 당신이 그 악마를 처치하고 싶다고 말하시오. 하지만 너무 무리하게 주장하지는 마시오. 그의 기를 살려 주려면 그가 생각해 낸 계획에 따르는 것처럼 하는 게 더 낫지...", progress = nil, completion = "방금 마우린과 악마 군주에 대한 소식을 들었소. 그 짐승은 유령이 된 상태에서도 우리 흑마법사 친구보다 더 강한 것 같더군. 그가 과연 그 괴물을 처치할 만큼의 능력을 가지고 있는지 의심스럽군. 내가 직접 가서 대족장님의 명예를 위해 처리하는 게 옳겠지만, 이곳에서의 내 임무를 저버린 채 개인적인 명예를 위해 악마를 처치하러 자리를 비우는 것은 우리 종족에게 등을 돌리는 행위라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1485] = {title = "악마의 하수인", objective = "루잔에게 악마의 하수인 머리 6개를 가져가야 합니다.", description = "칼림도어의 흑마법사들은 언제나 호드의 의심을 사 왔네. 호드는 흑마법사들을 묵인하고 있지만 결코 우호적이라고는 할 수 없지.\n\n그렇다고 해서 흑마법사들끼리 뭉치게 된 것은 아니라네. 많은 흑마법사들이 홀로 마법을 연구하며 숨어 지내기 때문이지. 자네가 가야 할 길을 일일이 안내해 주지는 못하겠지만 자네를 훈련시켜 줄 수는 있네.\n\n북동쪽 동굴에서 악마의 하수인 머리 6개를 가지고 오게. 그 후에 소환 기술을 가르쳐 주도록 하지.", progress = "마법으로 소환한 존재들을 통제할 수 있는 방법을 깨우치는 것이 무엇보다 중요하지. 요즘은 <class>의 길을 가려는 이들이 너무 적으니, 자네가 아직 준비가 덜 되었다고 해도 일단 가르칠 수밖에 없네. 자네의 목숨이 위험할지도 모르지만...", completion = "&lt;class&gt;로서의 훈련을 받는 동안 여러 존재들을 소환해 내는 방법을 배우게 될 걸세. 쓸모 없어 보이는 것들도 있을지 모르지만 알고 보면 모두 유용한 친구들이지.\n\n임프의 덩치가 작다고 얕보면 안 되네. 지내다 보면 알게 되겠지만, 작아도 만만찮은 상대니까.", rewards = "다음과 같은 것들을 배웁니다:\n\n임프 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n임프 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1486] = {title = "돌연변이 통가죽", objective = "통곡의 동굴에 있는 날팍이 돌연변이 통가죽 20개를 가져다 달라고 부탁했습니다.", description = "나랄렉스가 악몽에 깊이 빠질수록 불모의 땅 깊은 곳으로부터 솟아나온 온갖 이상한 짐승들이 통곡의 동굴에 출몰하고 있소.\n\n이 기이한 짐승들은 알 수 없는 초자연적 특성을 지니고 있소. 사악한 것들이긴 하지만 내 생각엔 그들이 이곳 칼림도어에 존재하는 한 좋은 방향으로 이용할 수도 있을 것 같소. 그들의 가죽을 잘 가공하면 특별한 용도에 쓸 수 있을지도 모른단 거요.\n\n이 일을 맡을 자신이 있다면 아래에 있는 동굴로 가서 돌연변이 통가죽을 좀 구해다 주시오.", progress = "동굴에 출몰하고 있는 기이한 짐승들의 가죽을 조사해 보고 싶소. 그래, 통가죽은 좀 모아 왔소?", completion = "통가죽을 모아 준 당신의 노고는 잊지 않겠소.\n\n정말 감사하오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n돌연변이 가죽 다리보호구돌연변이 통가죽 배낭\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1487] = {title = "돌연변이 짐승 섬멸", objective = "통곡의 동굴에 있는 에브루가 돌연변이 약탈자랩터 7마리, 돌연변이 독사 7마리, 돌연변이 늪괴물 7마리, 돌연변이 송곳니천둥매 7마리를 처치해 달라고 부탁했습니다.", description = "우리의 위대한 지도자, 나랄렉스께서는 숭고한 목표를 가지고 계셨습니다.\n\n에메랄드의 꿈 속으로 들어가 이 황량한 땅을 예전의 풍요로운 숲으로 되살려 놓기를 갈망하셨지요. 하지만 뭔가 크게 잘못된 게 분명합니다.\n\n나랄렉스께서 꿈꾸시던 것들은 악몽으로 바뀌었고 타락한 짐승들이 동굴에 출몰하기 시작했습니다.\n\n나랄렉스의 신도 몇분들이 지도자를 깨울 방법을 찾기 위해 애쓰는 동안, 나는 이 동굴에서 사악한 짐승들을 몰아내야 합니다.\n\n동굴로 가서 기이한 짐승들을 섬멸해 주시기 바랍니다.", progress = nil, completion = "나랄렉스의 신도로서 그대의 용기를 칭송하는 바입니다.\n\n그대 덕분에 동굴이 정화되었으니 불모의 땅을 회복시키기 위한 첫걸음을 내디딘 셈입니다.\n\n그대의 앞길에 나랄렉스께서 축복을 내리실 것입니다. 감사합니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n도안: 돌연변이 비늘 허리띠불타는 나뭇가지수렁늪 건틀릿\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1488] = {title = "타락자", objective = "제왕 아즈레토크와 죽카르 그림로드를 처치하고 잊혀진 땅에 있는 타카타 스틸블레이드에게 돌아가십시오.", description = "이 제왕 아즈레토크라는 자에 대해 아는 바는 없지만 나 역시 마우린과 같은 생각이오. 그 자를 처단해야 하오. 만약 그가 불타는칼날단을 손아귀에 넣고 주물러 자신의 목표를 달성하려 한다면 더욱더 그렇소.\n\n당신은 대족장님을 돕고자 한다는 것을 이미 우리에게 보여 주었으니, 이제 병력을 모아 저 악마 군주와 그의 흑마법사 부하들을 제거해 줄 것이라 믿겠소.\n\n준비가 끝나면 남쪽으로 곧장 가시오. 그들을 제거한 후에 내게 돌아오시오.", progress = nil, completion = "당신이 우리 모두를 위해 거둔 크나큰 성공을 함께 기뻐합시다. 이제는 이곳에서의 우리 미래가 예전처럼 어둡지만은 않을 것이라는 믿음을 갖게 됐소.\n\n악마들은 사라질 것이고, 불타는칼날단의 노력은 수포로 돌아갈 것이며, 우리는 언젠가 고향이라 부를 만큼 편안한 보금자리를 되찾게 될 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n현무암 버클러집행자의 어깨갑옷\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1489] = {title = "하뮬 룬토템", objective = "하뮬 룬토템과 대화하십시오.", description = "자네가 가져온 등껍질에 한 번도 본 적 없는 오염된 자국이 있었네. 분명 오아시스의 물이 원인일 거야. 그 물이 이 땅에 혼란을 일으키고 있다는 것을 느낄 수 있어. 마치 땅이 깨어날 수 없는 악몽을 꾸고 있는듯 해.\n\n그 오염의 근원은 틀림없이 통곡의 동굴일 걸세. 하지만 그곳으로 가기 전에 하뮬 룬토템이라는 드루이드 원로를 만나 보게나. 불모의 땅에서 일어나는 일들에 대한 소식을 전해 들어 알고 있을 거야. 지혜로운 자이니 조언을 구할 수 있을 걸세.\n\n썬더 블러프에 있는 장로의 봉우리로 가면 만날 수 있을 걸세.", progress = nil, completion = "어서 오시게. 반갑군! 내... 자네에게 힘든 임무를 맡길 참이니, 마음의 준비를 단단히 하도록 하게.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1490] = {title = "나라 와일드메인", objective = "나라 와일드메인과 대화하십시오.", description = "나는 꿈의 세계로 들어가 통곡의 동굴에 사는 드루이드 이교도 집단에 대한 환상을 보았네. 원래 그들에겐 숭고한 목표가 있었지만, 지금은 완전히 잘못된 길로 접어들고 말았지. 이제 그들은 불모의 땅 전역에서 나타나고 있는 타락한 악의 신하들일 뿐이네.\n\n나는 늙어서 기운이 쇠했어. 그래서 꿈의 세계에 오래 머물 수 없었고, 그 오염된 드루이드들에 대해 많은 것을 알아내지는 못했네. 하지만 나라는 젊고 강한 영혼을 지녔지. 내가 그 꿈속에서 도망쳐 나온 후에도 그녀는 계속 머물러 있었네.\n\n천막 안에 있는 나라에게 가 보게나.", progress = nil, completion = "룬토템님의 말이 사실입니다. 난 통곡의 동굴에 있는 드루이드들에 대해 많은 것을 알고 있죠. 뒤틀리고 비늘에 덮인 그들의 얼굴을 똑똑히 보았답니다. 그리고 그들이 저지른 죄와 앞으로의 계획을 알고 있습니다.\n\n반드시 그들을 막아야 합니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1491] = {title = "영리해지는 음료", objective = "톱니항에 있는 메보크 미지릭스에게 통곡의 정수 6병을 가져가야 합니다.", description = "흠, 랩터 뿔은 별 소용이 없었어. 하지만 첫술에 배부르란 법 없으니까 괜찮아. 그리고 더 좋은 재료를 찾았거든!\n\n통곡의 정수라는 물질이 있는데 내 생각엔 그것이 불모의 땅에 특이한 동식물이 나타나는 원인인 것 같단 말이야. 내게 이 물질을 구해다 주면 꼭 영리해지는 음료를 만들고야 말겠어.\n\n서쪽 통곡의 동굴에 있는 외형질 생물들의 몸 안에 통곡의 정수가 쌓인다고 하더군. 그 생물들을 사냥해서 정수를 모아 달라고.", progress = "통곡의 정수는 가져 있나? 어디 좀 보자고.", completion = "훌륭해, 구해 왔군! 어서 빨리 넣어 봐야겠어. 틀림없이 이걸로 한 몫 단단히 잡을 수 있을 거야!\n\n고마워. 자, 이걸 받아. 내가 돈 많이 벌고 나면 더 보내 주겠어. 절대 빈 말이 아니라고!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1492] = {title = "부두주임 디지위그", objective = "톱니항에 있는 부두주임 디지위그에게 단단히 잠긴 상자를 가져가야 합니다.", description = "동부 왕국에 있는 우리 동료에게 여러 재료와 물약과 시약이 담긴 상자를 보급해야 하네. 최대한 빨리 이 상자를 톱니항에 보내야 하는데 마지막 짐마차가 이미 떠나 버려서 곤란한 상황이야. 가능하다면 자네가 이 상자를 부두주임 디지위그에게 전해 주었으면 한다네.\n\n일처리 솜씨가 재빠른 그라면 이 상자를 검은바다 만으로 떠나는 다음 배에 실어줄 거야.", progress = "다음 배에 승선하려는 건가, 아니면 실어 보낼 물건이 있는 거야?", completion = "작은 상자로군. 알겠네... 배에 이 정도 상자를 실을 만한 공간은 남아 있을 거야. 배는 다음 조류를 타고 출항할 걸세. 어때?! 이 정도면 내가 얼마나 속전속결로 일을 처리하는지 알겠지? 아주 좋아. 그럼 장부에 이 내용을 기록해야지.\n\n자, 다 됐군. 그럼 잘 가게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1498] = {title = "수호자의 길", objective = "불모의 땅의 전초 기지에 있는 우제크에게 그슬린 비늘 5개를 가져가야 합니다.", description = "전사로서 우리의 가장 중요한 임무 중 하나는 바로... 보호라네. 우리는 호드의 수호자로서 약한 친구들을 안전하게 보호하고 있지. 진정한 수호자의 대열에 합류하고 싶다면 내게 자네의 기개를 증명해 보여야 하네.\n\n번개도마뱀과 천둥도마뱀이 살고 있는 듀로타의 천둥 골짜기로 가게. 그리고 그 짐승들을 사냥하도록! 자네가 그들보다 강하다는 걸 내게 보여 주게! 그 증거로 놈들의 그슬린 비늘을 몇 개 가져오게.\n\n이 일을 해낸다면 내 자네에게 가르침을 주도록 하지.", progress = "비늘은 가져왔나? 천둥도마뱀의 공격조차 견뎌내지 못하는 자라면 내 가르침을 받을 자격이 없네.", completion = "천둥도마뱀을 처치했으니 자네의 능력은 입증되었군. 지금부터 다부진 몸과 빈틈없는 움직임으로 철통 같은 방어막을 형성하는 방법을 가르쳐 주겠네.\n\n잘 배우도록 하고 앞으로의 훈련에 대한 마음의 준비도 단단히 해두도록 하게.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n방어의 길\n\n다음과 같은 것들을 받습니다:\n\n"},
[1499] = {title = "악마의 하수인", objective = "주리타 파게이즈와 대화하십시오.", description = "자네가 악마의 하수인과 싸웠던 장소 근처의 동굴로 가보게. 자네 같은 풋내기들을 보내 많은 짐승을 몰아내는 일을 하고 있는 주리타가 있을 걸세.\n\n그녀를 도우면서 경험을 쌓는 게 좋을 것 같군. 그녀에게 임프를 다루는 일을 도왔다고 꼭 말하게. 아마 보상을 해줄 테니까.", progress = nil, completion = "잘했어요.\n\n악마의 하수인은 불타는칼날단 내부의 사악한 세력이 부리는 졸개에 불과하긴 하지만, 이번 임무를 성공적으로 완수한 걸 보니 앞으로 더 큰 일도 잘해낼 수 있을 것 같군요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n구식 손칼구식 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1500] = {title = "깨어나는 나랄렉스", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1501] = {title = "공허의 존재", objective = "오그리마에 있는 간룰 블러드아이가 베르가의 서판을 되찾아 오라고 부탁했습니다.", description = "남아 있는 흑마법사가 별로 없는 이 상황에 우리는 피할 수 없는 큰 위험에 직면하고 있네. 그러니 호드와 대족장님을 위해 일하려면 한시라도 빨리 기량을 키워 놓아야 하네.\n\n이제 새로운 소환 주문을 배울 때가 되었네.\n\n우선 불타는칼날단의 흑마법사들에게 도난 당한 베르가의 서판을 되찾아 오도록 하게. 지금은 도시 동쪽 해골 바위굴에 있는 놈들의 소굴에 보관돼 있을 거야. 서판을 가져오면 보이드워커를 소환하는데 필요한 룬을 가르쳐 주도록 하지.", progress = "베르가의 서판은 가져왔나? 서판을 되찾아 오기 전까진 자네와 얘기하고 싶지 않네.", completion = "좋아. 서판을 찾으러 가서 불타는칼날단 놈들을 좀 처치하고 왔나?\n\n그들은 대족장님을 매우 성가시게 할 뿐만 아니라 &lt;class&gt; 전체에게 눈엣가시 같은 존재라네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1502] = {title = "툰그림 파이어게이즈", objective = "불모의 땅에 있는 툰그림 파이어게이즈와 대화하십시오.", description = "전사에게는 훌륭한 무기가 필수적이지. 툰그림 파이어게이즈라는 오크가 있는데 이 시대에 보기 드문 장인이지. 그는 크로스로드 동쪽 언덕 꼭대기에서 은둔 생활을 하고 있어.\n\n쓸만한 무기를 찾고 있다면 툰그림을 만나 보게. 서쪽의 크로스로드로 간 다음 동쪽 언덕으로 곧장 가게. 언덕 위에 그의 야영지가 있을 거야.", progress = nil, completion = "용광로의 불꽃 때문에 눈이 멀어버렸지만 아직 볼 수 있는 것들도 많이 있지. 내가 보기에 당신은 뭔가를 원하고 있는 것 같은데...\n\n이곳까지 날 찾아 온 걸 보면 뭘 원하는지도 알겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1503] = {title = "단조된 강철", objective = "불모의 땅에 있는 툰그림 파이어게이즈에게 단조된 강철 주괴를 가져가야 합니다.", description = "먼저 날 좀 도와준다면 내 당신에게 무기를 만들어 주겠어. 며칠 전 서슬갈기 가시멧돼지들이 밤에 내 야영지로 쳐들어 왔지. 놈들은 내게 싸움을 걸지도 않았는데 내가 앞을 잘 보지 못한다는 사실을 알고 있었어. 몇 녀석이 킁킁 거리며 내 주의를 끄는 동안 나머지 놈들이 내 물건을 훔쳐갔소! 비겁한 놈들!\n\n놈들은 철로 만든 상자를 가져갔소. 바로 그 안에 단조된 강철 주괴가 들어있소. 그걸 되찾아 준다면 당신에게 무기를 주도록 하지.\n\n가시멧돼지들의 야영지로 가서 철 상자를 찾아 단조된 강철 주괴를 가져다주시오.", progress = "내 강철 주괴를 찾아 왔소?", completion = "찾아왔군! 다행히 내 예상대로 주괴가 그대로 있군. 서슬갈기일족이 이런 질 좋은 강철을 다룰 수 있을 거라고는 생각지도 않았고 말이오.\n\n고맙소. 자, 보상으로 이걸 받으시오. 전투에 큰 도움이 되길 바라오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n툰그림의 도끼툰그림의 철퇴툰그림의 단검툰그림의 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1504] = {title = "결속", objective = "소환의 문양을 사용해 보이드워커를 소환하여 굴복시킨 다음 오그리마에 있는 간룰 블러드아이에게 사용한 소환의 문양을 가지고 돌아가십시오.", description = "자, 베르가의 서판을 잘 살펴보게. 그 안에 소환에 사용되는 문양이 포함되어 있으니까. 그걸 반대쪽 네루의 막사에 있는 소환 마법진으로 가져가도록 하게. 그곳에서 보이드워커를 소환할 수 있을 거야.\n\n자네가 가진 모든 힘과 마법으로 보이드워커를 물리쳐야 하네. 그런 다음 소환의 문양을 가지고 돌아오면 보이드워커를 자네의 의지에 결속시키는 방법을 알려 주도록 하겠네.", progress = "보이드워커는 강한 생물이야. 내가 예전에 지금의 자네처럼 보이드워커 소환을 배우던 때가 생생히 떠오르는군. 시간이 지나면서 내 보이드워커는 점점 더 온순해졌지. 물론, 주인을 방심하게 하려고 일부러 복종하는 척한다는 걸 눈치채고 있지만 말이야.\n\n자네도 이 사실을 명심하게.", completion = "&lt;name&gt;, 잘했네. 이제 방금 물리친 보이드워커와 유사한 보이드워커를 소환하는 방법을 가르쳐주겠네.\n\n우리가 자네에게 거는 기대가 크다는 걸 명심하게. 지금까지는 지금까지 그럭저럭 잘해왔지.\n\n그렇다고 거기에 자만하고 안주해서는 안 돼. 자네 앞에는 훨씬 더 막중하고 어려운 임무들이 놓여 있으니까.", rewards = "다음과 같은 것들을 배웁니다:\n\n보이드워커 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n보이드워커 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1505] = {title = "노련한 우제크", objective = "전초 기지에 있는 우제크과 대화하십시오.", description = "호드의 전사들은 압도적인 힘으로 명성을 얻고 있지. 하지만 진정 위대한 전사라면 힘과 동시에 언제나 겸손하게 배우는 자세를 가져야 하오.\n\n우제크를 만나보도록 하시오. 그는 셀 수 없이 많은 전투를 치른 노련한 전사인데, 지금은 젊은 전사들에게 전투 방식을 가르치고 있지. 불모의 땅과 듀로타 접경 지역에 있는 오크 주둔지, 전초 기지의 남쪽으로 가면 그를 만날 수 있을 것이야.", progress = nil, completion = "반갑네, 젊은이. 가르침을 받으러 온건가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1506] = {title = "간룰의 소환", objective = "오그리마에 있는 간룰 블러드아이와 대화하십시오.", description = "이런, <name> 아닌가?\n\n지금 바쁘지 않았으면 좋겠군. 간룰님께서 지금 당장 당신을 보자고 하시니까 말이네. 어둠의 틈에 있는 상급 흑마법사들에게 가서 간룰님을 찾아 보도록 하게.\n\n이제까지 내 경험에 비추어 보면 간룰님께서 부르시는 건 아주 좋은 일 아니면 아주 나쁜 일 중 하나일 거야.", progress = nil, completion = "좋아. 오페크가 자네를 찾지 못할까 봐 걱정했었네.\n\n이제 &lt;class&gt; 훈련을 더 받아야 할 때니 하던 일은 모두 뒤로 미루도록 하게.\n\n물론 별문제는 없겠지?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1507] = {title = "영혼을 삼키는 존재", objective = "어둠의 틈에 있는 카줄과 대화하십시오.", description = "자, 이제 소환 마법에 대해 한층 더 깊이 공부할 때가 되었네. 정신력이 놀랄 만큼 강한 세이야드를 소환하는 방법을 배우게 될 거야. 세이야드는 정신적으로 나약한 이들을 자신의 노예로 삼을 수 있지. 하지만 두려워하지 말라고! 자네라면 충분히 감당할 수 있을 테니까.\n\n세이야드는 위대한 헌신과 사랑을 상징하는 물건으로 유인해야만 소환할 수 있네. 자네가 직접 찾아보도록 해.\n\n힌트를 조금 주자면... 카줄을 한번 만나 보게. 그 늙은 흑마법사는 모르는 게 없으니까.", progress = nil, completion = "흠... . 자네는 아직 걸음마 수준이지만 커다란 잠재력이 숨겨져 있는 게 느껴지는군.\n\n자네는 타고난 재능을 갖고 있어. 부디 그 능력을 썩히지 말게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1508] = {title = "눈 먼 카줄", objective = "오그리마에 있는 잔카자와 대화하십시오.", description = "간룰이 보낸 거라면 세이야드 종족의 여자 악마, 서큐버스를 소환하기 위해서일 테고 유인하는 데 쓸 물건이 필요해서 온 거겠지.\n\n흠... 내가 눈이 멀긴 했지만 날 믿고 따를 생각이라면 잘 듣도록. 와이번 횃대가 있는 탑 서쪽으로 오그리마의 절벽에 잔카자라는 여인이 살고 있네. 그녀는 남편이 돌아오기를 기다리고 있지.\n\n가서 그녀를 만나 보게나.", progress = nil, completion = "혹시 도그란의 소식을 가지고 왔나요? 벌써 며칠 전에 돌아왔어야 하는데 아무 소식도 없네요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1509] = {title = "도그란의 소식", objective = "크로스로드에 있는 가즈록과 대화하십시오.", description = "제 남편 도그란은 얼마 전 임무를 수행하기 위해 크로스로드로 파견되었어요. 그건 바로 진급을 뜻하는 거였기 때문에 그는 무척 자랑스러워했어요.\n\n물론 전 걱정되고 슬펐지만 내색하지 않았어요. 불모의 땅은 오그리마보다 훨씬 더 위험한 곳이니 무슨 일이라도 일어나 그를 다시 보지 못할까봐 두려웠던 거랍니다.\n\n그가 돌아왔어야 할 날짜가 벌써 일주일이나 지났는데 아직 아무런 기별조차 없으니...\n\n크로스로드로 가서 그의 소식을 좀 알아봐 주시겠어요? 남편은 가즈록이라는 사람과 함께 일했어요. 그는 아마 아직 그곳에 있을 거예요.", progress = nil, completion = "잔카자? 도그란의 부인이 아니오?\n\n그의 소식은 들어 알고 있소만, 차마 그의 부인에게 전할 만한 게 아니라서...\n\n아, 그가 죽은 건 아니오. 하지만 부상을 당해 가시멧돼지일족의 포로가 되고 말았소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1510] = {title = "도그란의 소식", objective = "말라카진에 있는 켄지글라와 대화하십시오.", description = "도그란은 가시멧돼지를 섬멸하기 위해 타우라조 야영지에 배치되었소. 몇 명의 그런트들을 이끌고 놈들의 소굴로 들어갔는데 그곳에서 큰 부상을 입고 말았소. 다른 이들이 후퇴하면서 그를 구해 내려고 했지만 부상이 심하고 상처가 곪아 먼저 치료부터 하지 않고는 옮길 수가 없었소.\n\n전령이 가져온 소식에 의하면 돌발톱 산맥 아래 말라카진에 있는 트롤에게서 치유의 술을 구해야 한다더군. 이미 그곳으로 병사 하나를 보냈는데 아직 돌아오지 않고 있소.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1511] = {title = "켄지글라의 술", objective = "타우라조 야영지에 있는 그런트 로그마르에게 켄지글라의 술을 가져가야 합니다.", description = "또 다른 누군가 술을 구하러 올 줄 알고 미리 준비해 놓았지.\n\n자, 받으시오. 단 환자에게 절반만 먹여야 한다는 것을 명심하시오! 그러면 움직일 수 있을 만큼의 기력은 회복될 거야. 피도 너무 많이 흘리지는 않게 될 것이고. 하룻밤이 지난 다음에 나머지 반을 먹이도록 하시오.\n\n아무튼, 이걸 타우라조 야영지에 있는 로그마르에게 가져가면 될 거요. 처음 왔던 병사의 말로는 그가 도그란이 있는 곳을 알고 있을 거라더군.", progress = "그래, 무슨 일이오?", completion = "좋아, 제때 잘 왔군! 도그란이 아주 위태로운 상황이라 한시라도 빨리 이 술이 필요했소.\n\n즉시 이 술을 그에게 보내야 하지만 이곳에 배치된 대부분의 그런트들은 지금 식량 조달 임무를 수행하고 있는 중이라 여력이 부족하다오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1512] = {title = "사랑의 선물", objective = "오그리마에 있는 간룰 블러드아이에게 진흙투성이 목걸이를 가져가야 합니다.", description = "내 아내 잔카자는 아직 젊고 아름답지. 나 같은 불구자에게 얽매이도록 할 수는 없소... 죄 없는 그녀를 불행하게 할 수는 없단 말이오.\n\n차라리 나를 두고 가시면 고맙겠소. 생기를 잃어버린 껍데기만으로 사느니 차라리 명예롭게 전사할 것이오.\n\n그리고 제발... 잔카자에게는 이 사실을 알리지 마시오. 그녀가 부질없는 죄책감으로 괴로워하는 건 원치 않소.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1513] = {title = "결속", objective = "도그란의 목걸이를 사용해 서큐버스를 소환하여 처치한 다음 오그리마에 있는 간룰 블러드아이에게 도그란의 목걸이를 가지고 돌아가십시오.", description = "이 목걸이를 네루의 막사에 있는 소환 마법진으로 가져가게. 사악한 서큐버스를 소환한 다음 처치해야 하네. 자네가 가진 마법의 힘을 믿어 보도록 하지. 장래가 촉망되던 많은 흑마법사들이 과도한 자만으로 인해 무너지고 말았다는 사실을 항상 명심하게.\n\n서큐버스를 물리친 다음 목걸이를 내게 다시 가져오도록 하게. 그러면 내가 잔카자에게 남편의 소식을 전하도록 하지.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n서큐버스 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n서큐버스 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n작은 영혼의 가방"},
[1514] = {title = "오염된 바람꽃", objective = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어서 독성을 품게 된 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어서 독성을 품게 된 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "바람꽃에 세나리온 식물 고약 두 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[1515] = {title = "포로가 된 도그란", objective = "불모의 땅에 있는 도그란에게 켄지글라의 술을 가져가야 합니다.", description = "지금까지 일을 진척해 왔으니 당신이 끝까지 임무를 완수해주었으면 좋겠소. 하지만 다른 대원을 차출해 줄 수는 없으니 혼자 가야 하오.\n\n도그란은 북쪽에 있는 가시멧돼지 소굴에 붙잡혀 있소. 두 채의 오두막이 붙어 있는 곳을 찾도록 하시오. 경계가 삼엄할 거요. 놈들이 이미 그를 죽였거나 부상이 심해 죽음을 맞이하지 않았다면 구해낼 수도 있겠지.\n\n행운을 빌겠소.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1516] = {title = "대지의 부름", objective = "시험의 골짜기에 있는 카나가 어스콜러에게 하급 지옥사냥개 발굽 2개를 가져가야 합니다.", description = "젊은 <class>|1이여;여;, 이제 때가 되었네. 자네의 힘은 강해졌고 자네 영혼은 대지와 같은 인내를 갖게 되었으니 말이야. 주술사의 길을 선택했다는 것은 자네가 이미 지혜를 가지고 있다는 것을 나타내는 거야.\n\n준비가 되면 대지의 원소가 자네의 운명을 인도하여 자네의 일부가 될 거야. 하지만 자네가 대지 앞에 직접 나서야만 하지. 때가 되면 주술사만이 알 수 있는 것들을 보게 될 것이야.\n\n북쪽으로 가서 하급 지옥사냥개들을 찾아 처치한 후 놈들의 발굽 두 개를 가져오도록 하게. 그걸 가지고 내게 돌아온 다음 자네의 미래에 대해 좀 더 얘기해 보자고.", progress = "대지의 가장 큰 미덕은 인내일세. 대지는 만물의 순환을 지켜보고 있지. 산이 사막이 되고, 강이 협곡이 되는 그 모든 과정을 말일세. 대지는 자연의 모든 원소들 중 가장 완고하고 현명하며, 성급함을 용납하지 못한다네.\n\n대립의 시기가 가까워지고 있기 때문에 대지가 자네를 손짓하여 부르고 있는 걸세. 임무에 성공하고 내게 돌아오면 온전한 존재가 되는 길에 훨씬 더 가까이 다가서게 될 거야.\n\n다른 이들이 자신들의 무지 때문에 자네의 지혜를 시샘하고 미워하게 될 걸세.", completion = "훌륭하네. 성공한 걸 보니 이제 준비가 된 것 같군.\n\n모든 자연의 원소들 중에서 대지는 만물의 토대가 되지. 대지는 곧 자네의 힘이자 인내력이지. 대지를 존중하기만 하면 대지도 자네를 보호해 줄 걸세. 다른 원소들과 마찬가지로 대지도 변덕을 부릴 수 있으니 조심하게. 대지는 생명의 기초이고, 대지의 법칙을 지킴으로써 더 큰 지혜를 얻게 되는 것이야. 대지가 일러 주는 비밀을 절대 잊지 말게나.\n\n이제 자네를 위해 정기를 만들어 주지. 이 정기를 마시면 앞으로 자네가 가야 할 길을 알게 될 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1517] = {title = "대지의 부름", objective = "정기 바위를 찾아 대지의 정기를 마셔야 합니다.\n\n제공된 아이템: \n", description = "정기란 우리의 영혼을 자연의 원소에 결속시키기 위해 만들어진 자연이 주는 음료이지. 거기 담겨 있는 마법은 의지가 강한 이들에게 힘을 준다네. 평범한 이들에게는 보이지 않는 자연의 정령을 볼 수 있는 힘 말이야. 선택된 소수의 주술사들만이 정기를 만드는 법을 알고 있네. 자네의 영혼은 각 정기에 맞는 정령과 연결될 거야.\n\n정기는 반드시 신성한 장소에서 마셔야 해. 다른 장소는 절대로 안 되니 그걸 명심하게.\n\n여기서 남서쪽에 있는 정기 바위를 찾아가게. 비밀의 길을 따라가다 보면 나올 거야. 그곳에서 정기를 마시도록 하게. 그러면... 보게 될 거야.", progress = nil, completion = "아... 네가 이곳에 오니 대지가 기뻐하도다.\n\n육체와 영혼이 한데 결속되어 산맥이 곧 너의 힘이고, 평원은 너의 인내이며, 세계 자체가 바로 네 정수라는 사실을 차차 알게 될 것이노라.\n\n이 의식을 통과하기 위해 필요한 것은 오직 대지 앞에서 겸허히 자신을 낮추는 것뿐... 하지만 자연의 다른 정령들은 그리 조용하지 않으며 때로는 혼돈스럽고 때로는 폭력적이다. 그게 바로 자연의 본성이니까. 이 두 가지 본성은 서로 대립하는 동시에 조화를 이루는 것이니, 너도 언젠가는 이 관계를 이해하게 될 날이 올 것이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1518] = {title = "대지의 부름", objective = "시험의 골짜기에 있는 카나가 어스콜러에게 천연 석영을 가져가야 합니다.", description = "우리가 만났다는 증거로 이 천연 석영을 받아 카나가 어스콜러에게 가져가도록 하라. 자네를 위해 토템을 만들어 줄 것이다. 이 작은 조각이야말로 토템의 가장 중요한 재료이니 신중히 전달하도록 하라. 비록 보기에는 작아도 크기는 문제가 되지 않는다는 걸 깨닫게 될 것이다. 가장 작은 것이 다른 것들보다 더 오래 존속할 수도 있는 법이니까.\n\n인내심을 가져라. 언제나 강한 힘을 소유하고 지혜를 추구하라. 이것이 대지가 너에게 요구하는 전부다. 대지가 너를 존중하듯 너도 대지를 존중하라. 그러면 언젠가 대지와 하나가 될 것이다.", progress = "자네의 운명을 영원히 이끌어 줄 네 가지 길 중에서 첫 번째 길에 접어들었군. 내가 제일 먼저 축하해 주고 싶어.\n\n대지가 준 석영을 가져왔다면 대지가 자네에게 약속한 토템을 만들어 주겠네.\n\n가져오지 못했다면 자네의 길을 찾을 때까지는 내 앞에 나타나지 말게나.", completion = "훌륭해!\n\n내가 만들어 줄 토템은 단순히 &lt;class&gt;의 지위를 상징하는 장신구 따위가 아니야. 큰 힘을 가지고 있지. 토템의 용도 중 하나는 주문으로 사용하는 것이지. 그러한 주문은 대지에 결속되어 더 많은 능력을 사용할 수 있게 해준다네. 자네는 점점 더 큰 지혜를 얻을 수 있을 걸세.\n\n자네가 더 큰 지혜를 얻을 준비가 되었는지는 상급 &lt;class&gt;들만이 알 수 있지.\n\n하지만 지금은 우선 이 대지의 토템을 받도록 하게.", rewards = "다음과 같은 것들을 배웁니다:\n\n돌가죽 토템\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n돌가죽 토템\n\n다음과 같은 것들 또한 받습니다:\n\n대지의 토템"},
[1519] = {title = "대지의 부름", objective = "나라체 야영지에 있는 예언자 레이븐페더에게 의식의 물약 2개를 가져가야 합니다.", description = "때가 되었습니다, 젊은 <class>|1이여;여;. 그대의 몸은 시간이 지날수록 강해지고 그대의 영혼은 대지와 같이 앞으로 닥칠 시련을 견뎌낼 것입니다. 그대는 이미 지혜롭다는 걸 난 알 수 있답니다.\n\n대지가 우리 종족을 이끌고 우리에게 말을 하고 있습니다. 물론, 때가 되면 그대에게도 말을 할 겁니다. 하지만 시험을 거쳐야만 하지요. 준비가 되었다면 우리 종족만이 알고 있는 일들을 보게 될 겁니다.\n\n동쪽 지역에서 뾰족털일족 주술사들을 찾아 그들이 의식에 사용하는 물약을 구해오도록 하세요. 그대가 사용하기에 충분한 양을 모은 후에 내게 돌아오십시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1520] = {title = "대지의 부름", objective = "코도 바위를 찾아 대지의 정기를 마셔야 합니다.\n\n제공된 아이템: \n", description = "정기는 우리 영혼을 자연의 원소에 결속하기 위해 만들어진 것입니다. 열린 마음을 지닌 이들이 이 마법의 물약을 마시면 다른 이들은 볼 수 없는 자연의 원소들을 볼 수 있게 되죠. 그대의 영혼은 각 정기에 해당하는 자연의 원소에 영원히 결속될 겁니다. 우리 종족 중 선택된 소수만이 정기를 만드는 비법을 알고 있지요.\n\n정기는 반드시 신성한 장소에서 마셔야 합니다. 여기서 동쪽에 있는 주술의 제단을 찾아가 그곳에서 정기를 마시도록 하시기 바랍니다.", progress = nil, completion = "아... &lt;name&gt;... 네가 이곳에 오니 대지가 기뻐하도다.\n\n육체와 영혼이 한데 결속되어 산이 곧 네 힘이고, 평원이 네 인내이며, 세계 자체가 바로 네 정수라는 사실을 차차 알게 될 것이로다.\n\n이 의식을 통과하기 위해 필요한 것은 오직 대지 앞에서 겸허히 자신을 낮추는 것뿐. 하지만 다른 자연의 원소들은 그렇게 수동적이지 않고 혼돈스럽거나 때로는 폭력적이지. 그게 바로 자연을 이루는 원소들의 본성이니라. 두 가지 본성이 서로 대립하는 것이니 언젠가 반드시 이런 복잡한 관계를 알게 될 것이로다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1521] = {title = "대지의 부름", objective = "나라체 야영지에 있는 예언자 레이븐페더에게 천연 석영을 가져가야 합니다.", description = "우리가 만났다는 증거로 이 천연 석영을 받아 예언자 레이븐페더에게 가져가도록 하라. 그녀가 너를 위해 토템을 만들어 줄 것이며 이 작은 돌이 토템의 가장 중요한 재료가 될 것이다. 비록 보기에는 작아 보이지만 크기는 문제가 되지 않는다는 걸 알게 될 것이다. 미물이 태산보다 더 오래 존속할 수도 있는 법이니라.\n\n인내심을 가져라. 언제나 강한 힘을 유지하고 지혜를 추구하여라. 이것이 대지가 너에게 요구하는 전부니라. 대지가 너를 존중하듯 대지를 존중하라. 그러면 마침내 대지와 하나가 될 것이다.", progress = "다시 보니 반갑군요. 임무를 완수하기 전까지는 내게 돌아와서는 안 됩니다. 앞으로 영원히 그대의 여정을 지배하게 될 네 가지 길 중 첫 번째 길에 접어들 때 내가 가장 먼저 크게 먼저 축하해 주고 싶군요.\n\n대지가 준 돌을 가져왔다면 대지가 약속한 토템을 만들어 주겠습니다. 가져오지 못했다면 안 된 일이지만 대지가 준 돌을 가져왔다면 대지가 약속한 토템을 만들어 주겠습니다. 자연의 원소들에 온전히 헌신했을 때 큰 영광이 따를 겁니다.", completion = "아주 훌륭하군요.\n\n내가 만들어 줄 토템은 단지 상징적이기만 한 물건이 아닙니다. 훨씬 더 큰 힘을 가지고 있지요. 토템의 용도 중 하나는 주문에 초점을 맞추는 것입니다. 그러한 주문들은 대지에 결속되어 그대의 지혜가 깊어질수록 더 많은 대지의 능력을 사용할 수 있게 되는 것입니다. 그대가 더 많은 지식을 얻을 준비가 되면 칼림도어 전역에 퍼져 있는 스승들이 그 사실을 알고 그대가 그들을 방문하면 하나씩 알려주게 될 겁니다.\n\n자, 이제 그대에게 첫 번째 능력을 가르쳐 줄 대지의 토템을 받도록 하십시오.", rewards = "다음과 같은 것들을 배웁니다:\n\n돌가죽 토템\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n돌가죽 토템\n\n다음과 같은 것들 또한 받습니다:\n\n대지의 토템"},
[1522] = {title = "불의 부름", objective = "불모의 땅에 있는 크라날 피스를 찾아야 합니다.", description = "불의 힘이 함께 하기를... 자네는 땅의 주술에 능통해졌으니 이제 크라날에게 가볼 때가 된 거 같군.\n\n크라날은 불모의 땅의 크로스로드 북쪽에 살고 있네. 그는 자연의 원소들을 다루는 데 있어 강력한 힘을 가졌으니 자네에게 불의 주술을 가르쳐 줄 수 있을 거야. 준비가 되었다면 한번 가보게나.\n\n크라날을 찾는 건 쉬워. 너무 멀리만 가지 않으면 되지. 엘프의 땅에 발을 들여놓지 않도록 조심하라고.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1523] = {title = "불의 부름", objective = "불모의 땅에 있는 크라날 피스를 찾아야 합니다.", description = "<name>, 마지막으로 당신의 실력을 시험해 본 지도 오래전 일이군. 지금까지 끈기 있게 잘해왔지만 이제 더 많은 것을 배워야 할 때가 왔소. 이제는 파괴... 그리고 혼돈에 대해 배워야 하오. 배움을 위해서 어떤 대가라도 치를 준비가 되었다면 불이라는 자연의 원소에 대해 배울 때가 된 것이지.\n\n불모의 땅에 있는 크라날 피스를 찾아가 보시오. 크로스로드의 북쪽에 있는 작은 거처가 머물고 있는데, 너무 멀리 가면 나이트 엘프의 땅에 이르게 되니 조심하시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1524] = {title = "불의 부름", objective = "듀로타에 있는 텔프 줄람에게 희미한 불씨의 횃불을 가져가야 합니다.", description = "자네는 불의 토템을 사용할 수 있을 정도로 강하지만 아직 준비가 덜 되었네.\n\n듀로타의 분노의 강을 따라가다 보면 대해에 못 미쳐서 숨겨진 오솔길이 있는데, 그 길을 따라 올라가면 이 땅에서 가장 높은 봉우리 중 하나에 이르게 된다네. 그 꼭대기까지 올라가게. 그러면 텔프 줄람이 지키는 희미한 불꽃의 제단이라는 성지를 발견하게 될 거야.\n\n자네가 불을 길들이려 한다는 표시로 이 횃불을 그에게 주게. 제단에 있는 화로를 타오르게 하여 내게 가져오면 불의 토템을 주겠네.", progress = "안녕하신가. 이곳이 바로 희미한 불꽃의 제단이라네. <class>의 지식을 충분히 익힌 자들만이 이곳의 비밀과 힘을 알게 될 자격이 있네. 먼길을 왔는데 그냥 돌려보내 미안하군그래. 여기까지 올라오는 것이 결코 쉽지 않았겠지만 이 제단을 수호하는 자로서 아무나 함부로 이곳을 휘젓고 돌아다니게 할 수는 없지.", completion = "아, 이런. 내가 실수를 했군. 사과하겠네. 자네에게 횃불이 있는지 몰랐어. &lt;name&gt;, 만나서 반갑네.\n\n많은 모험가들이 잃어버린 보물이나 신비한 생물을 찾아 왔다가는 텅 빈듯이 보이는 이 제단을 보고 그냥 돌아가 버리곤 하지. 하지만 우리는 진실을 알고 있지. 안 그렇나?\n\n이 제단에는 평범한 호드의 일원은 알지 못하는 큰 비밀이 있어. 우리에게는 성스러운 비밀이지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1525] = {title = "불의 부름", objective = "듀로타에 있는 텔프 줄람에게 불붙인 타르 1개와 시약 주머니 1개를 가져가야 합니다.", description = "자네는 영원한 불꽃의 횃불과 불의 토템을 얻으러 온 것이지, 역사의 비밀을 알아내려는 것은 아니지 않나?\n\n첫 단계는 정기를 만들어 불꽃에 자기 자신을 구속하는 것이야.\n\n내게 두 가지 재료를 가져오면 불의 정기를 만들어 주겠네. 첫 번째 재료를 구하는 일은 간단해. 불붙인 타르라는 것으로 불모의 땅 서슬갈기일족 중에서 마법을 사용하는 놈들에게서 구할 수 있지.\n\n두 번째 재료는 구하기가 조금 더 힘들 거야. 불타는칼날단 이교도들 중 한 명에게서 시약 주머니를 빼앗아 오게나. 칼바위 언덕 북동쪽에 있는 협곡 위의 한 동굴로 가면 그들을 만날 수 있을 걸세.", progress = "시약 주머니와 불붙인 타르만 찾을 수 있다면 불의 정기를 만들 재료는 다 준비된 거야. 그렇게 멀리까지는 안 가도 될 걸세. 보통 불타는칼날단 광신자들이 지니고 다니는 주머니 안에는 내가 말한 재료들뿐만 아니라 대부분의 마법 주문에 필요한 재료들이 가득 들어있거든.\n\n모든 정기는 각각의 원소와 밀접하게 연결된 재료로 만든다네. 즉 불의 주술과 흑마법사의 밀접한 관계 때문에 우리 일이 더욱 수월한 거라고.", completion = "그래, 이거면 충분하지.\n\n불은 혼동과 파괴에만 그치지 않고, 그 이상의 존재라는 것을 잘 기억해 두게. 불은 생명과 창조와도 밀접한 관련이 있으니까. 만물은 이러한 방식으로 서로 연결되어 있는 것일세. 서로 다른 힘은 대립하는 동시에 어느 한쪽이 없으면 나머지 한쪽도 존재할 수가 없지. 양쪽은 서로 파괴하지만 그러면서 서로에게 의미를 부여하는 것일세. 이 점을 항상 기억하게.\n\n서로 다른 힘을 섞어 주술을 사용하는 것은 진정한 기술뿐 아니라 크나큰 지혜를 요구하지.", rewards = "다음과 같은 것들을 받습니다:\n\n불의 정기"},
[1526] = {title = "불의 부름", objective = "하급 불의 현신을 물리친 다음 희미한 불꽃의 화로에 타오르는 불꽃을 넣어야 합니다.", description = "불의 정기가 완성됐네. 이제 불꽃과 맞설 차례일세. 이제 불의 정기를 마시고 이 산의 꼭대기까지 올라가 그곳에 있는 불의 현신에 맞서도록 하게. 녀석이 당장 공격하지는 않겠지만 준비를 서둘러야 할 거야. 곧 자네가 자기를 볼 수 있다는 것을 알아차릴 테니...\n\n재빨리 그를 해치우게. 오래 끌면 끌수록 그의 힘은 더 강해지게 될 테니까. 그를 물리친 후에는 그의 타오르는 불꽃을 화로에 넣고 횃불에 불을 붙이게.", progress = "높이가 허벅지 정도까지 올라오는 화로는 매끄러운 금속으로 만들어져 있는데 둥근 접시에 새겨진 문양을 제외하고는 평범해 보입니다. 비바람에 마모된 흔적이 전혀 없으며, 화로 위에 손을 대어 보니 차가운 기운이 느껴집니다.", completion = "불꽃을 화로 안에 넣자 하얀 불길이 타오르면서 주위가 뜨거워집니다. 정기의 마법 효과가 온몸에 소용돌이치고 있는 것이 느껴지고 눈앞에서는 불길이 춤추듯 너울거립니다.\n\n횃불을 화로 안에 집어넣자 곧바로 불이 붙습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n영원한 불꽃의 횃불"},
[1527] = {title = "불의 부름", objective = "불모의 땅에 있는 크라날 피스에게 영원한 불꽃의 횃불을 가져가야 합니다.", description = "횃불을 손에 꼭 쥔 채 화로에서 등을 돌려 듀로타를 내려다 봅니다. 바람이 일어 불길이 심하게 흔들리면서 말할 수 없는 전율이 느껴집니다.\n\n크라날 피스를 찾으러 다시 불모의 땅으로 길을 내려가기 시작합니다.", progress = "돌아왔군. 가지고 온 게 뭔가?", completion = "자네의 영혼은 이제까지 내가 봐 온 그 어떤 횃불보다도 밝게 타오르는군. 뿌듯하게 여기게나.\n\n자네가 계속해서 길을 가면서 자연의 원소들이 자네의 부름에 응하게 될 것이고, 우리 종족도 자네에게 지혜와 지도력을 구하게 될 거야. 내가 누구보다도 먼저 축하해 줘야지. 그리고 여기 자네에게 새로운 토템을 선물하겠네.", rewards = "다음과 같은 것들을 배웁니다:\n\n불타는 토템\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n불타는 토템\n\n다음과 같은 것들 또한 받습니다:\n\n불의 토템"},
[1528] = {title = "물의 부름", objective = "불모의 땅에서 이슬렌 워터시어를 찾아야 합니다.", description = "자네의 미래에 물이 흐르는 것이 보이는군. 이미 불의 도에는 능통해졌으니 이제 이슬렌을 만나러 갈 때가 된 거 같군그래.\n\n이슬렌은 불모의 땅의 해안가에서 살지. 분노의 강을 따라 남쪽으로 가면 틀림없이 만나게 될 거야. 큰 상어를 찾아 보라고! 이슬렌은 자연의 원소들을 다루는 데 있어 강력한 힘을 가졌으니 자네에게 물의 능력을 가르쳐 줄 수 있을 거야... 준비가 됐다고 생각하면 한번 가 보라고.\n\n이슬렌은 쉽게 찾을 수 있을 거야. 톱니항을 지나면 바로 있을 테니까 남쪽으로 너무 멀리 가지만 않으면 돼.", progress = nil, completion = "당신 가까이 바람이 불어오고, 발 밑의 땅은 굳건하며, 당신의 영혼은 불꽃의 온기로 따스하니 이제는 물의 순수함을 배워야 할 때이군요.\n\n당신의 행로가 여기까지 당신을 이끌어 왔으니 이제는 당신의 영혼이 더 멀리 나아갈 수 있는 힘을 줄 것입니다. 하지만 첫 번째 발걸음을 내딛는 것은 당신의 몫입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1529] = {title = "물의 부름", objective = "불모의 땅에서 이슬렌 워터시어를 찾아야 합니다.", description = "<name>, 마지막으로 당신의 실력을 시험해 본 지도 벌써 오래전 일이군. 지금까지 끈기 있게 잘해왔지만 이제 더 많은 것을 배워야 할 때가 왔소. 이제는 순수한 물에 대해 배워야 하오.\n\n불모의 땅에 있는 이슬렌 워터시어를 찾아가시오. 동쪽 해안을 따라 분노의 강과 톱니항의 남쪽에 있는 오두막에서 물고기 낚을 준비를 하고 있는 그녀를 찾을 수 있을 거요. 행운을 빕니다, <name>.", progress = nil, completion = "바람이 불어와 당신의 두뺨을 스치고, 발 밑의 땅은 굳건하며, 영혼은 불의 온기로 따스하니 이제 물의 순수함을 배워야 할 때이군요.\n\n당신의 행로가 여기까지 당신을 이끌어 왔으니 이제는 영혼이 더 멀리 나아갈 수 있는 힘을 줄 것입니다. 하지만 첫 번째 발걸음을 내딛는 것은 당신의 몫입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1530] = {title = "물의 부름", objective = "불모의 땅 남쪽에 있는 브린을 찾아야 합니다.", description = "물에서 배워야 할 가장 중요한 교훈이라면 물은 곧 소생을 의미한다는 것이랍니다.\n\n그 힘으로 만물이 흐르고, 침식되고, 정화되는 것입니다. 물이 지닌 치유력과 재생력은 그 어느 것과도 비교할 수 없다는 걸 알게 될 거예요. 하지만 그것은 물이 순수한 상태일 때만 가능합니다.\n\n오염된 물은 모든 것을 황폐하게 하는 파괴력이 있다는 것을 이해해야 물이 얼마나 중요한 자원인지 느낄 수 있을 겁니다.\n\n물의 정기를 원한다면 불모의 땅 남쪽 깊은 곳에 사는 브린을 찾아가세요. 그녀의 집을 가시멧돼지들이 끊임없이 위협하고 있답니다.", progress = nil, completion = "무엇이 궁금한가요?\n\n흠... 알 것 같기도 하군요. 불모의 땅 깊은 곳에서 어떤 보호도 받지 않고 가시멧돼지의 위협을 받으면서 살아가는 이유가 뭐냐는 거겠죠? 글쎄요... 모든 일에는 다 그만한 이유가 있는 법이죠. 진짜로 의아한 일은 어째서 당신 같은 &lt;race&gt;|1이;가; 제 몸 다치는 것 아랑곳하지 않는 나 같은 여자와 얘기를 나누러 불모의 땅 가장 깊은 곳까지 오게 되었나 하는 거겠죠.\n\n분명 당신과 나 모두 그 이유를 알고 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1531] = {title = "바람의 부름", objective = "버섯구름 봉우리에서 프레이트 클라우드시어를 찾아야 합니다.", description = "점점 발전해 나가고 있군. 바람의 부름에 응할 준비가 된 것 같아. 우선 버섯구름 봉우리에 있는 프레이트 클라우드시어를 찾아야 하네. 그녀의 도움을 얻어 바람의 부름을 구할 수 있을 거야.\n\n불모의 땅에서 남쪽으로 가면 버섯구름 봉우리가 나오지... 거기서 동쪽으로 가보게. 아마 지금쯤 애인이랑 굴 속에 숨어 있을 걸세. 은둔 생활로 잔뜩 예민해져 있을 테니... 신경은 건드리지 말고.", progress = nil, completion = "때가 되었으니 당신의 마력을 집중시켜 바람의 부름에 응하는 방법을 가르쳐 드리겠어요. 자, 이 토템을 받으세요. 준비가 되면 다른 배움도 구하도록 하시고요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n돌풍\n\n다음과 같은 것들을 받습니다:\n\n바람의 토템"},
[1532] = {title = "바람의 부름", objective = "버섯구름 봉우리에서 프레이트 클라우드시어를 찾아야 합니다.", description = "칼림도어의 바람이 당신을 향해 불어오고 있소. 당신은 우리 호드의 가장 강력한 일원 중 하나로 여겨질 것이오. 정말 뿌듯하군. 지금껏 잘해왔는데다 많은 이들에게 귀감이 되어 앞날에 대한 희망과 기대까지 심어 주고 있으니...\n\n바람은 제어하기 쉽지 않지만 당신만한 실력이라면 눈앞에 놓인 어떤 장애도 극복할 수 있으리라 믿어 의심치 않소.\n\n불모의 땅 남쪽에 있는 버섯구름 봉우리로 가도록 하시오. 동쪽으로 한참 가다 보면 프레이트 클라우드시어를 만날 수 있을 거요. 나보다 더 많은 것을 가르쳐 줄 테니 가르침을 구하시오.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n돌풍\n\n다음과 같은 것들을 받습니다:\n\n바람의 토템"},
[1534] = {title = "물의 부름", objective = "잿빛 골짜기에 있는 별가루의 폐허에서 빈 파란색 물주머니를 채워 불모의 땅에 있는 브린에게 가져가야 합니다.", description = "이 물주머니를 가지고 나이트 엘프들이 잿빛 골짜기라고 부르는 울창한 숲으로 가세요. 그 곳으로 가려면 일단 불모의 땅의 북쪽 끝으로 가세요.\n\n그리고 숲에 들어서거든 서쪽으로 가세요. 돌발톱 산맥과 잿빛 골짜기 사이에 있는 산을 따라 가다가 미스트랄 호수를 지나면 성지가 있을 거예요. 별가루의 폐허라고 하는데 호수 가운데 작은 샘이 있죠.\n\n그 샘물을 가져오세요. 이슬렌에게 돌아가기 전에 필요한 마지막 물건이에요.", progress = "물을 가져왔나요? 들리는 이야기에 의하면 그 폐허는 외부인을 반기지 않는 거대한 자연의 생물들이 보호하고 있다고 해요. 하지만 나이트 엘프들이 겁을 주어 침입을 막아내려고 지어낸 이야기일지도 모르죠.\n\n어쨌든 조심하세요.", completion = "굉장하네요. 세 가지 견본을 모두 모았으니, 이제 아무도 본 적이 없는 순수한 물을 만들어 드리지요. 이 물은 다음 단계의 통과 의식에 쓰일 거예요.\n\n당신이 우리 일원이라는 게 자랑스럽군요. 당신은 우리 &lt;class&gt; 모두의 자랑이에요. 훗날 당신의 위업에 대한 이야기가 널리 퍼져 이곳에서도 듣게 되길 기대하죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1535] = {title = "물의 부름", objective = "브린의 거처 아래에 있는 물 구멍으로 가서 빈 갈색 물주머니에 물을 채우십시오. 그런 다음 불모의 땅에 있는 브린에게 가져가야 합니다.", description = "물에 대해 깨우침과 정기를 받고 싶다면 가장 순수한 형태의 물을 찾아야 해요. 견본을 가져올 때는 주변 환경을 잘 기억해 두세요. 이 땅의 생명체들은 물에 의존하는 동시에 그것을 수호하지요. 또한, 물이 숲과 사막에 어떠한 영향을 미치는지도 잘 보시고요. 그리고 생명의 원천인 물이 어떻게 생명을 앗아가는지도 똑똑히 봐두세요.\n\n그럼, 간단한 임무부터 시작하죠. 이곳 바로 아래, 귀한 물이 고인 연못이 있답니다. 이 주머니에 그 물을 가득 담아 가져오세요.", progress = "당신에게 다른 임무를 맡길 준비를 하고 있었어요. 물 주머니는 채워왔나요?\n\n가시멧돼지들은 온 힘을 다해 물을 지킬 겁니다. 가시멧돼지에게는 적은 양의 물이라도 엄청난 가치가 있으니까요. 그래서 불모의 땅에 비가 조금이라도 오는 날이면 가시멧돼지들은 성대한 잔치를 벌인답니다. 이곳은 물이 귀하거든요. 그들에게 물이란 신성한 것이죠. 이해하시겠어요?", completion = "그곳에서 물을 뜨려고 하면 분명 유혈 사태가 벌어지리라 예상했어요. 모든 생명이 연결되어 있다는 사실을 가시멧돼지들이 이해하지 못한다는 사실이 참으로 안타깝군요. 욕심은 끝없는 고통과 괴로움만 안겨줄 뿐인데 말이죠. 모든 종족이 서로 작은 차이점은 잊고 협력한다면 많은 일을 해낼 수 있을 텐데...\n\n당신이 해주신 일은 가시멧돼지들에게는 안타깝지만 불모의 땅에 사는 다른 모든 종족에게는 잘된 일이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1536] = {title = "물의 부름", objective = "타렌 밀농장에 있는 우물에서 빈 빨간색 물주머니를 채워 불모의 땅에 있는 브린에게 가져가야 합니다.", description = "오래전 동료 몇을 따라 힐스브래드 구릉지에 갔답니다. 그런데 그곳에 사는 끈질긴 인간들의 추격에 쫓기다가 포세이큰이 정복한 작은 마을까지 밀려났어요. 그곳이 바로 타렌 밀농장이었죠.\n\n그런데 그 농장에서 아주 특이한 걸 보게 되었답니다. 마을 한복판에 맑은 물이 솟아나오는 조그마한 우물이 있었어요. 마을 주민들은 역병에 걸려서 아마 그 안에 담긴 물이 어떤 가치를 지니고 있는지도 모르고 있을 거예요. 그 물은 지금은 그 신성함을 잃어 버린 바다에서 온 것이라서 이 땅에 흔적처럼 남아 있는 신성하고 순수한 결정체랍니다.\n\n이 물주머니에 그 물을 담아오세요.", progress = "그 마을에 순수한 우물이 남아있다니 어릴 적에 들은 이야기가 하나 생각나는군요. 아무리 큰 고통과 슬픔이 닥쳐와도 실낱 같은 희망만 있다면, 딛고 일어설 수 있어요. 오크족이 스랄을 높이 평가하는 이유도 그 때문이죠. 아주 불리한 조건 속에서도 살아남아 타에 모범을 보이며 우리 종족을 이끌어 갈 강인한 지도자로 일어섰으니까요.\n\n스랄만큼 힘들게 살아온 오크가 또 있을까 싶네요. 또 한편으로 생각해 보니 그만큼 강한 오크도 없는 것 같아요.", completion = "잘했어요, &lt;name&gt;. 주어진 임무에 대한 사명감과 필요한 것을 찾을 줄 아는 능력을 지녔군요.\n\n이제 한 가지 견본만 더 있으면 당신께 드릴 물의 정기에 필요한 시약을 만들 수 있겠어요. 이슬렌도 기뻐할 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1558] = {title = "돌다지 댐", objective = "랜디스를 모단 호수에 있는 돌다지 댐에 데려다 줘야 합니다. 거대한 폭포를 볼 수 있도록 댐 중간까지 데려다 주십시오.", description = "드워프와 노움이 살고 있는 아이언포지 근처에 모단 호수라는 데가 있다는데, 드워프들이 거기에 엄청나게 큰 댐을 지었대요. 지금까지 만든 것 중 제일 크다나봐요. 와아, 보고 싶다!\n\n저를 모단 호수로 데려가서 그 댐을 보여주지 않으시겠어요? 이름이... 돌... 음... 돌다리 댐이었나? 돌다지 댐이었나? 어쨌든 엄청나게 크대요. 그 큰 폭포를 내려다보고 싶어요. 위험할 정도로 많이 내다보진 않을게요!", progress = nil, completion = "와아! 제가 생각했던 것보다 훨씬 큰데요! 물 떨어지는 소리 때문에 말소리가 거의 들리지 않을 정도예요! 그런데 물이 다 떨어지거나 하는 일은 없겠죠? 혹시 이 댐이 부서진다거나 하면... 우와. 진짜 무섭겠다!\n\n댐에 데려다 주셔서 고맙습니다. 형은 정말로 친절하신 분이네요. 히히, 위험할 정도로 많이 내다보지 않겠다고 약속했었죠!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1559] = {title = "섬광탄 제조법", objective = "오호, 당신 기술자로군? 그 진주를 찾는 걸 도와줬으니 여기 섬광탄 설계도를 주도록 하지.\n\n행운을 빌겠어. 장님이 안 되도록 조심하라고!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n설계도: 섬광탄"},
[1560] = {title = "길 잃은 투가", objective = "투가를 아내 토르타에게 데려다 주어야 합니다.", description = "길을 잃어버렸어요!\n\n제 아내 토르타가 저녁거리를 구해 오라고 보냈는데 어디에선가 길을 잘못 든 것 같아요.\n\n저를 토르타에게 데려다 주시지 않으시겠어요? 스팀휘들 항구 바로 남쪽에서 저를 기다리고 있답니다.", progress = "투가 어디 있어요?", completion = "혼자서는 집을 못 찾아왔단 말이죠? 내 그럴 줄 알았지.\n\n아무튼 수고해 주신 보답을 해 드려야겠네요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n거북 소매장식큰 거북 고리\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1578] = {title = "전방 보급품 조달", objective = "모단 호수 남쪽 방어탑에 있는 토발트에게 가서 구리 도끼 6개와 구리 사슬 허리띠 6개를 주어야 합니다.", description = "모단 호수의 산악경비대는 트로그와의 싸움으로 항상 바쁘다오. 그들에게 방어구와 무기를 지속적으로 보급해 줘야 하오.\n\n바로 그 때문에 내 동료 토발트가 거기 상주하면서 산악경비대에 제대로 된 보급품을 전달하도록 힘쓰고 있다오. 구리 도끼와 구리 사슬 허리띠를 만들어 그에게 가져다주면 아주 고마워할 거요. 어쩌면 자기가 알고 있는 기술을 알려줄지도 모르겠군.\n\n토발트는 모단 호수 남쪽에 있는 방어탑에 가면 찾을 수 있소.", progress = "잡담할 시간 없소이다. 내게 볼 일이라도 있는 거요?", completion = "아, 미안하게 됐소! 경비대에 보급품을 전달하려고 온 분인지 몰랐군요. 당신이 준 물건들은 아주 큰 도움이 될 거요!\n\n여기 방어구 제작법을 받으시오. 유용하게 쓰길 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n도면: 구리 사슬 조끼"},
[1579] = {title = "개퍼 잭", objective = "아우버다인에 있는 위즈뱅 크랭크토글에게 개퍼 잭 8개를 가져가야 합니다.", description = "전 아우버다인이 조용한 게 마음에 들어 이곳으로 왔답니다. 이렇게 조용한 곳에서 발명에 열중하고 싶어서 말이에요. 아이언포지에서는 특히 술이라도 한잔 걸친 다음날에는 그 소음을 견디기 힘들거든요!\n\n그래서 아우버다인으로 가는 배를 탔는데 도중에 술을 좀 과하게 마시는 바람에 개퍼 잭이 든 상자를 밖으로 떨어뜨려 버렸어요. 작업에 꼭 필요한 물건인데!\n\n정확히 어디에 떨어뜨렸는지는 모르겠지만, 바다에서 낚시를 하다가 운 좋게 건질 수 있을지도 몰라요.", progress = "제 개퍼 잭은 찾으셨어요? 개퍼 잭이 없으면 스틴틀 볼트를 조절할 수가 없다고요!", completion = "이걸 찾다니 믿어지지 않는군요! 당신은 칼림도어에서 제일 운 좋은 &lt;race&gt;|1이;가; 틀림없어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1580] = {title = "전력추진기", objective = "아우버다인에 있는 위즈뱅 크랭크토글에게 전력추진기 12개를 가져가야 합니다.", description = "당신은 운이 참 좋은 것 같은데... 어디 한번 더 확인해 볼까요?\n\n어느 날 전 맥주를 좀 마시고서 어둑어둑한 어둠의 해안을 거닐고 있었어요. 자체 추진력이 있는 폭탄형 오리 미끼를 시험할 만한 강이나 호수를 찾고 있었거든요. 그런데 제가 조금 취했었나 봐요. 몇 시간 동안 정신을 잃었다가 아우버다인에서 깨어났죠. 깨어나 보니 머리카락은 온통 새카맣게 그을려 있고 전력추진기 주머니는 온데간데 없지 뭐예요! 분명 물속에 빠뜨린 게 틀림없어요!\n\n그 전력추진기는 정말 중요한 물건이에요. 어둠의 해안에 있는 호수나 시내에서 낚시를 하시다가 행여라도 전력추진기를 건지면 가져다주시겠어요?", progress = "전력추진기를 하나라도 찾으셨나요? 오리 미끼를 계속 연구하려면 그게 꼭 필요한데...", completion = "믿을 수가 없네요! 이걸 찾아내시다니 지금까지 제가 본 중 최고의 낚시꾼이로군요!\n\n고맙습니다! 그리고 여기, 이거 받으세요. 솜씨가 워낙 좋아서 필요하지 않으실 테지만 그래도 낚시를 수월히 하시는 데 도움이 될 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n액체역학 낚시용 렌즈"},
[1581] = {title = "블레이드리프를 위한 비약", objective = "돌라나르에 있는 시랄 블레이드리프에게 사자의 힘 비약 6개와 최하급 방어의 비약 2개를 가져가야 합니다.", description = "요즘 우리 연금술 가게가 아주 호황이랍니다. 하지만 남편은 물약을 만드느라 너무 바빠서 둘이 함께 하는 시간이 거의 없어요. 그래서 말인데 저를 좀 도와주지 않겠어요?\n\n미리 조제된 비약을 좀 가져다주시면 당신과 기꺼이 거래를 하겠어요. 유용하게 쓰일 만한 희귀한 약초들이 좀 있거든요.", progress = "안녕하세요. 거래할 비약을 가져오셨나요?", completion = "혼합이 잘 됐네요. 당신은 굉장히 신중하게 거래를 하시는군요. 이 비약은 연금술사에게 아주 중요한 거랍니다.\n\n여기 갓 채집한 약초들이 있어요. 이것들이 당신에게 유용하게 쓰였으면 좋겠군요.", rewards = "다음과 같은 것들을 받습니다:\n\n뱀뿌리마법초 꽃잎"},
[1582] = {title = "달빛 조끼", objective = "다르나서스에 있는 로서리아스에게 새김무늬 가죽 장갑 1개, 새김무늬 가죽 장화 5개, 새김무늬 가죽 망토 5개를 가져가야 합니다.", description = "다르나서스에 사는 우리 장인들은 아주 바쁘답니다. 열성이 대단한 젊은 모험가들이 자신의 능력을 시험해보고 싶어 황야로 모여들고 있습니다. 그들은 꾸준히 우리의 보급품을 필요로 하고 있답니다.\n\n이번에 주문받은 가죽 제품을 보충할 수 있도록 도와준다면 고급 가죽세공술을 가르쳐 드리도록 하죠.", progress = "또 보게 되는군요.", completion = "좋군요, 물건의 품질이 아주 좋습니다. 손재주도 있고 보는 눈도 꼼꼼하니 장차 유명한 가죽 세공인이 될 자질이 충분하군요.\n\n그럼, 약속대로 달빛 조끼를 만드는 방법을 가르쳐 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 달빛 조끼"},
[1598] = {title = "도난 당한 책", objective = "드루실라 라 살르를 위해 공허의 힘을 찾아 와야 합니다.", description = "거기! <name>|1이;가; 아니오?\n\n흑마법사가 될 마음의 준비가 단단히 되어 있길 바라오. 스스로 자신의 길을 꿋꿋이 지켜나가지 못한다면 적에게 당해 버릴 것이 뻔하니까 말이야.\n\n앞으로 내가 당신을 가르치게 될 테지만 먼저 실력이 어떤지 시험해 봐야겠소.\n\n노스샤이어 수도원에서 공부를 하던 수련사제 하나가 도망쳐 데피아즈단에 합류했소. 나 같은 흑마법사가 왜 이 일에 신경 쓰냐고? 도망친 녀석이 중요한 책 몇 권을 훔쳐갔기 때문이야.\n\n그 중 하나가 내가 아끼는 공허의 힘이라는 책이오. 녀석들은 포도밭에 있는 막사에 그 책을 숨겨 놓았으니 그걸 훔쳐오시오.", progress = "내가 직접 그 책을 훔쳐내려고 했지만 눈에 너무 잘 띄어서 말일세. 마침 어수룩한 수련자 녀석이 내 대신 책을 훔쳐내 주니 이 얼마나 운이 좋은가.", completion = "훌륭해... 내가 이 책을 손에 넣는다는 것은 불가능했지. 도서관 내의 보호 구역에 보관되어 있어서 내가 주변을 어슬렁거리면 수상히 여겼을 테니까 말이야.\n\n자, 이 책을 가져오는 임무를 수행했으니 임프 정도는 부릴 수 있을 거야. 그러니 임프를 소환하는 방법을 가르쳐주지 않을 이유가 없지.", rewards = "다음과 같은 것들을 배웁니다:\n\n임프 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n임프 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1599] = {title = "시작", objective = "앤빌마에 있는 알라마 그림에게 깃털 부적 3개를 가져가야 합니다.", description = "사람들이 수군거리던 흑마법사가 자네로군. 날 보고 하던 연구를 미루고 자네를 가르치라는 요청이 들어온 걸 보면, 누군가 자네를 상당히 마음에 들어 하는 모양이야. 걱정 말게, 그렇다고 괴롭히진 않을 테니까.\n\n자, 소환 주문 중 가장 쉬운 것부터 시작하지. 임프 소환 주문을 가르쳐 주겠네. 하지만 그 전에 자네가 흑마법사로서 필요한 마법 능력과 신체적 조건을 갖추고 있다는 것을 보여주게.\n\n남서쪽의 동굴에서 서리갈기부족 견습마법사 몇 마리를 잡아 깃털 부적 3개를 가져오게.", progress = "서리갈기부족 견습마법사들이 지니고 있는 깃털 부적에는 트롤 녀석들에겐 기대 못했던 신비한 마력이 깃들어 있지. 연구를 해보면 아주 흥미로울 거야.", completion = "아주 좋아! 잘해냈어! 자네 정말 세간의 주목을 끌 만하군.\n\n아주 유능한 &lt;class&gt;가 되겠어. 자네가 소환해낸 임프를 통제하지 못하고 죽임을 당하지만 않는다면 말이야. 어쨌든 지금은 자네가 몇 달간 흑마법 기본 훈련에서 살아남을 수 있단 사실에 만족해야지.\n\n그리고 임프에 대해 한마디 하겠는데 덩치만 보고 과소평가해서는 안 되네. 임프의 마법은 잠재력이 대단해서 아주 위험하단 말이야.", rewards = "다음과 같은 것들을 배웁니다:\n\n임프 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n임프 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1618] = {title = "붉은마루산맥 무기 조달", objective = "토르무스 딥포지가 붉은마루 산맥에 있는 베르너 오스구드에게 구리 룬문자 허리띠 4개와 무거운 구리 마울 4개를 가져다 달라고 부탁했습니다.", description = "요새는 우리 드워프들 뿐만 아니라 얼라이언스의 일원인 인간들도 바빠 죽을 지경이지!\n\n붉은마루 산맥은 검은바위부족 오크들로부터 지속적으로 공격받고 있어 항상 장비가 부족한 형편이오. 당신이 이 물건들을 가져다 준다면 붉은마루 산맥에 있는 인간 대장장이 베르너 오스구드가 쓸만한 기술을 몇 가지 가르쳐 줄 거요.", progress = "아이언포지에서 좋은 소식을 가져오신 거라면 좋겠네요. 나도 지금 어찌할 바를 모르겠으니까요!", completion = "오, 감사합니다. 이거면 아주 큰 도움이 될 겁니다. 돌망루 요새는 검은바위부족 오크들의 공격을 항상 받고 있고 북쪽 언덕에는 붉은마루일족 놀들이 잠복하고 있어서, 쉴 새 없이 우리 군의 갑옷을 고쳐 주고 새로운 무기를 만들어 주고 있답니다.\n\n당신이 제 일손을 덜어주셨으니 그나마 좀 쉴 시간이 있겠네요. 그 시간에 보답으로 뭔가 가르쳐 드리고 싶습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n도면: 아이언포지 흉갑"},
[1638] = {title = "전사 훈련", objective = "해리 벌가드와 대화하십시오.", description = "당신은 꽤 솜씨 좋은 전사로군요. 하지만 아직은 젊고 배워야 할 것이 많이 남아 있습니다.\n\n해리 벌가드에게 가서 얘기를 나눠 보시기 바랍니다. 그는 보통 스톰윈드의 구시가지에 있는 돼지와 휘파람 선술집에 있습니다. 해리는 경험이 풍부한 좋은 스승이니 전장에서 목숨을 구해줄 기술을 몇 가지 가르쳐 줄 겁니다.", progress = nil, completion = "오호! 젊은이, 나랑 한잔 하세나. 겉보기엔 튼튼해 뵈는데 어디 돼지와 휘파람 선술집에서 가장 독한 술을 얼마나 잘 받아 마시는지 함 볼까!!\n\n아니면... 나한테 가르침을 받으러 온 겐가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1639] = {title = "주정뱅이 바틀비", objective = "바틀비와 대화하십시오.", description = "그럼, 가르쳐 줄 수 있고 말고. 하지만 먼저 지금까지 어떤 기술을 익혔는지 보도록 할까?\n\n저기 끝에 앉아 있는 주정뱅이 바틀비가 보이지? 저 녀석의 술잔을 가져오게나.\n\n하하, 알고 있는지 모르겠지만 바틀비가 순순히 술잔을 넘겨줄 사람은 아니라네.", progress = nil, completion = "안녕하쇼, 도련님! 고상하신 분이 돼지와 휘파람 선술집에는 어쩐 일이쇼? 손톱 부러지지 않도록 조심하슈...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1640] = {title = "바틀비와의 대결", objective = "바틀비와 싸워 이긴 후 그와 대화하십시오.", description = "뭐를 달라고?? 자네 미쳤군!\n\n내 눈에 흙이 들어가기 전에는 이 술잔을 넘겨줄 수 없어...", progress = "내 눈에 흙이 들어가기 전에는 이 술잔을 넘겨줄 수 없다니까...", completion = "당신, 보기보다는 꽤 센데!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1641] = {title = "신앙의 고서", objective = "이곳 스톰윈드에서 나는 <class>들을 인도하는 임무를 맡고 있네. 정의를 수호하고 아제로스를 위협으로부터 보호하는 진정한 빛의 길로 말이지.\n\n이제 자네도 진정한 빛의 미덕을 갖추기 위해 한걸음 내디딜 때가 되었군. 자, 이 신앙의 고서를 받게. 이 책에는 정의로움과 <class>가 나아가야 할 방향에 대한 내용이 수록되어 있다네. 책을 잘 이해하고 몸소 실천할 실력이 쌓이면 더 큰 능력을 얻을 수 있을 거야.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n신앙의 고서"},
[1642] = {title = "신앙의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화하십시오.", description = "성기사는 모든 일을 행함에 있어 언제나 빛과 함께해야함을 잊지 말아야 한다. 우리가 추구하는 것은 스스로 신성한 존재가 되기 위함이 아니라 모든 일을 행함에 의로워야 하는 것이다.\n\n이 혹독한 시대에 악을 물리치기 위해 부름을 받았다고 해도 성기사로서의 진정한 길은 타인을 돕는 것임을 항상 명심해야 한다. 자비와 인내, 용기와 같은 덕목을 소중히 여기는 것은 전투에서 힘을 발휘하는 것만큼이나 중요하다.\n\n진정한 성기사가 되기 위해서는 이를 명심하고 절대 잊지 않아야 한다.", progress = nil, completion = "다시봐서 기쁘군. 신앙의 고서에 대한 공부는 잘 되어 가는가?\n\n그럼 자신을 시험해 볼 준비가 되었겠군. 이 도시를 비롯한 곳곳에는 항상 도움을 필요로 하는 사람들, 처치해야 할 짐승들, 이해와 자비로움을 요하는 일들과 같이 해야 할 일들이 많이 있다네.\n\n특히 불우한 사람들을 도울 수 있는 인내심을 발휘한다면 &lt;class&gt;로서 정의를 따르며 빛의 정신을 이어가고 있다는 것을 증명해 보이는 길이 될 것일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1643] = {title = "신앙의 고서", objective = "스톰윈드의 상업 지구에서 스테파니 터너를 찾아야 합니다.", description = "자, 이제 자네가 해야 할 일은 이곳 스톰윈드에서 도움의 손길이 필요한 사람을 찾는 것일세. 순수한 마음과 동기를 가진 이를 말이지. 또 다른 이를 돕는 자이거나, 안내가 필요한 자일 수도 있다네. 누구이든 의도가 숭고하며 자네의 친절한 도움이 반드시 필요한 사람이라야 함을 명심하게.\n\n그런 사람을 찾아 도와준 후에 나에게 돌아오도록 하게나. 그 후에 자네가 앞으로 가야 할 길과 빛의 정의를 실천하는 성기사가 되는 것이 무엇을 말하는 지에 대해서 더 얘기하도록 하지.", progress = nil, completion = "아, 안녕하세요. 모험은 어떠신가요? 오, 잘 되어간다니 정말 기쁘네요.\n\n아, 저요? 제 안부까지 물어봐 주시다니 감사합니다. 전 그럭저럭 괜찮답니다.\n\n상인들이 늘어나는 바람에 요즘에는 사람들이 내놓는 가죽이나 천을 얻기가 아주 힘들어요. 그래서 보육원에 있는 아이들에게 옷을 만들어 주기가 더 힘들답니다. 그래도 남편과 저는 괜찮을 거예요. 지금 그이가 아이언포지에 가서 도움을 얻을 수 있을지 알아보고 있거든요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1644] = {title = "신앙의 고서", objective = "스톰윈드에 있는 스테파니 터너에게 리넨 옷감 10개를 가져가야 합니다.", description = "보육원에 있는 불쌍한 아이들은 지난 십 년 동안 스컬지의 침공으로 가족을 잃은 아이들이랍니다.\n\n제 남편 존이 저에게 옷감을 갖다주면 제가 아이들이 입을 속옷이나 바지를 만들지만 최근에는 그럴 시간도 없었어요. 아이들을 먹이고 입히는데 온 신경을 다 쏟았었거든요.\n\n네? 저를 도와주시겠다고요? 아, 신이시여, 감사합니다! 정말 고마우신 분이시군요!\n\n옷을 좀 만들 수 있도록 리넨 옷감을 더 구할 수만 있다면 정말 큰 도움이 될 거예요.", progress = "아이언포지에 있는 제 남편 존의 일이 잘 풀렸으면 좋겠네요. 그이는 저랑 아이들만 남겨두고 가야 해서 여행가는 걸 굉장히 싫어한답니다. 하지만 꼭 해야 하는 일이라는 걸 알고 있는 너무나 착한 사람이죠.\n\n도움 받기가 좀 더 쉬운 해도 있고, 좀 어려운 해도 있지만 올해는 다른 때보다 훨씬 더 힘이 드네요. 꼭 앞으로 뭔가 큰일이 벌어질 징조인 것 같아요. 세상일이야 아무도 모르지만 말입니다.", completion = "감사합니다. 너무나도 감사드려요!\n\n아이들이 웃는 얼굴이 눈에 선하네요. 도와주신 덕분에 제가 시간을 많이 절약하게 되었어요. 이제 아이들에게 더 신경 쓸 수 있게 되었습니다. 그리고 제 남편 존이 생각했던 것보다 일찍 돌아오게 될지도 모르겠어요.\n\n다시 한번 감사드립니다. 이젠 다른 사람들의 손길을 믿을 수 있게 될 거 같네요. 빛이 함께하시기를 빌겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1645] = {title = "신앙의 고서", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n신앙의 고서"},
[1646] = {title = "신앙의 고서", objective = "아이언포지에 있는 타이자 배틀포지와 대화하십시오.", description = "성기사는 모든 일을 행함에 있어 언제나 빛과 함께 해야함을 잊지 말아야 한다. 우리가 추구하는 것은 스스로 신성한 존재가 되기 위함이 아니라 모든 일을 행함에 의롭기 위한 것이다.\n\n이 혹독한 시대에 악을 물리치기 위해 부름을 받았다고 해도 성기사로서의 진정한 길은 타인을 돕는 것임을 항상 명심해야 한다. 자비와 인내, 용기와 같은 덕목을 소중히 여기는 것은 전투에서 실력을 발휘하는 것 만큼이나 중요하다.\n\n진정한 성기사가 되기 위해서는 이를 명심하고 절대 잊지 않아야 한다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1647] = {title = "신앙의 고서", objective = "아이언포지의 외곽 지역에 있는 존 터너를 찾아야 합니다.", description = "자, 이제 해야 할 일은 이곳 아이언포지에서 당신의 손길을 기다리는 자를 찾는 것입니다. 순수한 마음과 동기를 가진 이를 말이에요. 안내자를 필요로 할 수도 있고, 또 당신의 도움으로 다른 누군가를 돕고자 하는 자일 수도 있습니다. 누구든 의도가 숭고하고 당신의 도움이 반드시 필요한 사람이라야 합니다.\n\n이 사람을 도와준 후 나에게 돌아오시기 바랍니다. 그 때 당신이 앞으로 가야 할 길과 빛의 정의를 실천하는 성기사가 되는 것이 무엇인지에 대해 좀 더 얘기하도록 합시다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1648] = {title = "신앙의 고서", objective = "아이언포지에 있는 존 터너에게 리넨 옷감 10개를 가져가 기부해야 합니다.", description = "전 스톰윈드에서 아내와 함께 보육원을 운영하고 있습니다. 저희 보육원 아이들은 지난 십 년 동안 스컬지의 침공으로 부모를 잃은 아이들이 대부분이랍니다. 저는 한 달에 한번 정도 이곳 아이언포지에 와서 후원을 받을 수 있을지 알아보고, 여러 단체에 도움의 손길을 청하고 있습니다.\n\n그런데 이번에는 일이 쉽지 않네요.\n\n제 집사람이 아이들 옷을 만들 리넨을 더 구할 수만 있다면 고향으로 부칠 수 있을 텐데 말입니다.", progress = "동부 왕국 전역에서 상인들이 밀어닥치는 통에 옷감 구하기가 너무 힘들어요. 집사람이 보육원 아이들을 위한 새 옷을 만들 수 있도록 리넨을 모아주시다니 정말 친절한 분이로군요. 감사드립니다.\n\n고향으로 돌아가 집사람과 아이들 얼굴을 볼 생각을 하니 무척이나 행복하군요. 하하하!", completion = "이렇게 훌륭한 일을 해 주시니 감사하다는 말밖에 드릴 수가 없네요.\n\n역시 정의를 수호하시는 분답습니다. 어떻게 해서든지 이 은혜를 갚고 싶은데... 네? 이것밖에 못해 줘서 미안하시다고요? 아니 얼마나 많은 도움을 주셨는데 그런 말씀을 하시다니... 겸손하기까지 하시군요.\n\n긴 여정 동안 항상 평안하시고 성스러운 빛이 지켜 주시기를 빕니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1649] = {title = "용맹의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화해야 합니다.", description = "용맹과 그에 수반되는 다른 모든 미덕은 귀한 광물과 같다. 귀한 광물은 각고의 노력을 기울여 캐내 정제하여 아껴두어야 하는 것과 마찬가지이다. 귀한 광물은 다른 재료들과 융합하면 아주 강한 합금이 만들어지며 어떠한 막강한 힘에도 부서지지 않게 된다.\n\n바로 이 힘과 본인의 정의로움과 용기를 시험해야 한다. 어떠한 고난이 닥쳐도 정의로움을 잃지 않는 법을 배우며, 빛의 힘으로 범인들이 극복하지 못하는 것을 극복할 수 있다는 것을 깨달아야만 한다.", progress = nil, completion = "아, 용맹함을 시험하기 위해 나에게 온 것이군. 좋아, 아주 좋아.\n\n이 도시 전역에는 해야할 수많은 일들이 있고 주변 땅에도 많은 난관이 도사리고 있네. 자네와 같은 &lt;class&gt;의 능력이 필요한 일들 말이지.\n\n이 시험을 가벼이 여기지 말게나. 이 시험 또한 저 밖의 수많은 적들과의 전투처럼 우리의 목숨을 앗아갈 수 있는 것이니 말이야. 대성당에서는 항상 더 많은 &lt;class&gt;를 지원하고자 하지만, &lt;class&gt;로서의 자격을 증명하기 위해 필요한 희생에 대해서도 잘 알고 있네.\n\n준비는 되었는가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1650] = {title = "용맹의 고서", objective = "서부 몰락지대에 있는 대프니 스틸웰을 찾아야 합니다.", description = "좋아! 주저하지 않는 것을 보니 준비도 되었고 자신을 시험해 보고 싶은 마음이 간절한 모양이군. 그럼 시작하도록 하지.\n\n서부 몰락지대의 기나긴 해안 끝에 해변이 내려다보이는 자그마한 집이 한 채 있네. 그곳에 스틸웰 부부가 살고 있지. 남편인 조던은 아주 유능한 대장장이인데, 드워프들을 만나기 위해 잠시 아이언포지에 가 있다네. 그 바람에 그의 아내 대프니는 대책 없이 혼자 두려움에 떨고 있지.\n\n보고받은 바에 의하면 데피아즈단이 그 지역을 거의 점령했다고 하네. 그 악당들로부터 대프니를 보호해야 하니 그곳으로 가게.", progress = nil, completion = "누구시죠? 제 땅을 빼앗으러 오신 분인가요, 아니면 남편이 없는 동안 절 보호해 주실 분이신가요? 오, 이런 대성당에서 오신 분이시군요.\n\n제 소개를 하도록 하죠. 저는 대프니 스틸웰이라고 합니다. 만나서 반가워요.\n\n다행히 너무 늦진 않으셨네요. 오늘은 데피아즈단 놈들을 6명밖에 처치하지 못했어요. 녀석들은 저 위에서 준비하느라 좀 지체하곤 있지만 아마 당신이 오는 걸 봤을 거예요. 그러니 이제 곧 여기로 들이닥칠 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1651] = {title = "용맹의 고서", objective = "데피아즈단의 공격으로부터 대프니 스틸웰을 보호하십시오.\n\n둘 중 하나라도 죽으면 실패하게 됩니다.\n\n성공한 후에 대프니 스틸웰과 다시 대화해야 합니다.", description = "이제, 틀림없이 곧 녀석들이 들이닥칠 테니 단단히 준비하세요.\n\n집에 총이 하나 있으니 그걸로 도와드리긴 하겠지만 아무래도 대부분은 상대해 주셔야 할 거예요.\n\n몇 명이나 공격해올진 저도 모르지만, 아까보다는 더 보내겠죠.\n\n빛의 축복을 구하는 기도를 올리는 게... 방금 들으셨어요? 녀석들이 오고 있는 모양이에요.\n\n집 가까이에서 막아내 보도록 하죠!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1652] = {title = "용맹의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화하십시오.", description = "두소리안님께 돌아가서 제가 이제 안전하다고 전해 주세요. 당신과 대성당에 감사를 드립니다.\n\n두소리안님께서 아이언포지에 있는 제 남편 조던에게 제 걱정은 하지 않아도 된다고 소식을 전해 주실 거예요.\n\n아, 보고 싶은 조던... 남편이 빨리 돌아왔으면 좋겠네요.", progress = nil, completion = "또 보는군. 아주 기분이 좋아 보이는군...\n\n스틸웰 부인이 또 하루를 무사하겠군그래. 얘기를 들어 보니 정말 대단히 위험했었군. 잘했네.\n\n대프니와 조던은 대성당을 많이 도와 왔지. 이번에 그들의 재산과 목숨을 구한 것은 우리가 그들에게 할 수 있는 최소한의 것이었네.\n\n자네의 무훈을 치하하며 보상을 주도록 하지.", rewards = "다음과 같은 것들을 배웁니다:\n\n언데드 감지\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n언데드 감지\n\n다음과 같은 것들 또한 받습니다:\n\n스톰윈드 수호방패"},
[1653] = {title = "정의의 시험", objective = "아이언포지에 있는 조던 스틸웰과 대화해야 합니다.", description = "틀림없이 조던이 직접 자네에게 감사의 말을 전하고 싶어할 걸세. 마침 그 친구에게 아내가 무사하단 소식을 전해줄 사람이 필요한데, 자네가 이 일에 적당하겠군.\n\n조던은 부친의 가업을 이어받아 대장장이가 되기 전까지만 해도 빛의 성기사가 될 사람이었지. 그래서 성기사로서의 삶의 자세와 방식에 대해서 아주 잘 알고 있는데다가 우리 중에서 가장 신앙심이 깊은 친구지.\n\n그 친구는 분명 아직도 아이언포지에 있을 걸세. 차가운 산 공기가 좋다면서 낮에는 성문밖에서 일하기를 좋아한다네.", progress = nil, completion = "안녕하세요. 빛이 함께하시길...\n\n네? 두소리안님이 보냈다고요? 제 아내는 어떻게 됐나요? 이런, 내가 떠나면 문제가 생길 줄 알았다니까. 제발 아내가 무사하... 오, 신께 감사드립니다. 아내가 무사하다니 정말 다행이에요. 우리 땅을 공격하기 전부터도 데피아즈단은 위협적인 존재였지요. 이제는 폐하의 참모들도 이 사실을 부인할 수 없을 겁니다.\n\n두소리안님이 또 뭐라고 전하라던가요? 당신이 제 아내를 보호하러 파견됐던 분이라고요? 오, 정말 감사합니다. 용맹의 시험에 딱 맞는 과제였을 것 같군요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1654] = {title = "정의의 시험", objective = "조던의 쪽지를 참고해 흰돌참나무 재목, 조던의 제련된 광석 상자, 조던의 대장장이 망치, 그리고 코르석을 찾아 아이언포지에 있는 조던 스틸웰에게 가져가야 합니다.", description = "괜찮으시다면 보상을 해 드리고 싶습니다. 아, 오해는 하지 마세요. 당신이 도움을 주는 만큼 보상을 해 드리는 거니까요. 그렇다고는 해도 이런 협력 관계가 우리 모두에게 유익할 것 같군요.\n\n제가 당신이 해낸 일에 걸맞은, 성기사와 빛을 상징하는 무기를 제작해 드리죠. 하지만 먼저 필요한 재료들을 가져오셔야 합니다. 벌써 다 적어 놓았습니다. 이제 이 물건들을 가져올 만큼 용감하고 솜씨 있는 친구만 있으면 되는데, 한번 해보시겠어요?", progress = "찾고 있는 물건들을 구하기는 어려울 것이지만, 제가 만들어 드릴 무기는 대단히 가치가 높을 것이라는 걸 장담하죠.\n\n분명 제 생애에 최고의 무기가 될 것입니다. 당신이 저를 위해 해 준 수고에 대한 보답으로 기꺼이 드리고 싶습니다.", completion = "대단합니다! 모두 찾으셨군요.\n\n이거라면 거뜬히 근사한 무기를 만들 수 있겠는데요. 사실 언젠가 꼭 이걸 만들어 보려고 벼르고 있었지만, 재료를 찾으러 다닐 겨를이 없었답니다. 고맙습니다.\n\n아버지의 망치를 다시 쥐게 되다니 감개무량하군요... 이 코르석도 직접 보게 되리라고는 생각지도 못했답니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1655] = {title = "조던의 광석 상자", objective = "모단 호수에 있는 베일러 스톤핸드에게 조던의 광석 상자를 가져가야 합니다.", description = "으앗! 놀래라! 지금 한참 생각에 몰두 중인 게 안 보이는 거요?\n\n뭐라고? 아이언포지의 조던이 주문한 물건이라... 아아, 맞아! 뭘 얘기하는 건지 알겠소. 모그로쉬 오우거들... 바로 그 녀석들이 조던 그 친구가 주문한 물건을 빼앗아 가 버렸소. 저습지에서 이곳으로 물품을 운송해 오던 짐마차가 습격을 당했다오. 겨우 살아서 빠져나온 경비병은 사제들이 때맞춰 오지 못해 며칠 전에 숨을 거두었소이다.\n\n그 물건들을 찾으려면 대호수 건너편 북동쪽으로 보시오. 그곳 어딘가에 분명히 있을 거요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n조던의 제련된 광석 상자"},
[1656] = {title = "완수하지 못한 임무", objective = "블러드후프 마을에 있는 여관주인 카우스에게 모피 묶음을 가져가야 합니다.", description = "여행자분, 절 좀 도와주실 수 있으신가요? 제발, 간곡히 부탁드려요. 지금 힘의 의식을 수행하는 중인데 아직 이곳 고원에서 임무를 마치지 못했답니다. 그런데 아버지께서 제게 이 모피를 블러드후프에 있는 여관에 가져다주라고 하셨지 뭐에요.\n\n지금 이렇게 지친 몸으로는 의식도 마치고 아버지의 심부름까지 하기엔 역부족이랍니다. 제 대신 모피를 전해주시겠어요?\n\n그 여관은 아주 편안한 곳이라서 오랜 여행 중에 휴식을 취하기엔 그만이랍니다. 여관에 가 보시면 분명 그렇게 느끼실 거예요.", progress = "이 카우스에게 무슨 일이신가요, 젊은 모험가분?\n\n어떤 이들은 붉은 구름 구원에서 여기까지 오는 길을 무척이나 부담스럽게 여기지만, 어떤 이들은 오히려 좋은 경치구경이라 생각을 한답니다. 젊은 모험가께서는 어떻게 생각하시는지 궁금하군요.", completion = "아, 기다리던 모피로군요. 고맙습니다.\n\n예상보다 빨리 도착했군요. 이곳에 머무는 손님들에게 좋은 담요를 만들어 줄 수 있게 되어 다행입니다.\n\n여기서 쉬시면서 지친 몸을 달래시기 바랍니다. 저희 여관은 항상 열려있고 우리 종족은 누구든지 환영이니까 말입니다. 하룻밤 휴식을 아무것도 아니라고 생각하지 마세요. 여행할 때는 하룻밤의 휴식이 엄청난 도움이 된답니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n질긴 빵맑은 샘물\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1657] = {title = "사우스쇼어에 구린내 폭탄 투하", objective = "힐스브래드에 있는 사우스쇼어 한가운데에 3개의 포세이큰 구린내 폭탄을 던진 후, 티리스팔 숲의 밀짚인형 축제가 열리는 곳에 있는 암흑의 소환사 얀카에게 돌아가야 합니다.", description = "사우스쇼어에 있는 적에게 슬픔을 안겨 준다면 훨씬 더 의미 있는 할로윈 축제가 될 거야!\n\n여기 특수 제작된 구린내 폭탄을 하나 골라 보게. 이 안에는 인간은 물론 의지가 약한 생물은 견딜 수 없을 정도로 고약한 악취가 가득 차 있지. 확실한 효과를 얻으려면 구린내 폭탄을 사우스쇼어 한가운데 던져야 해. 그러니까 얼라이언스와의 전투에 대비해 두게!\n\n이것은 우리의 해방을 축하하는 좋은 선물이 될 것이네. 일을 마치면 내게 돌아오게나!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n할로윈 축제 호박"},
[1658] = {title = "밀짚인형 축제 정탐", objective = "티리스팔 숲에서 포세이큰의 밀짚인형 축제가 열리고 있는 곳을 찾아 정탐한 후 사우스쇼어에 있는 하사관 허트만에게 돌아가야 합니다.", description = "티리스팔 숲으로 가서 밀짚인형 축제에 대한 정보를 수집해 올 용감한 정찰 요원이 필요하오. 솔직히 말하는데 그곳으로 가는 길은 무척이나 위험하다오. 그리고 그곳 경비병들은 아주 사악한 놈들이지. 하지만 올해 밀짚인형 축제의 규모가 어느 정도이고, 또 할로윈 축제 동안 포세이큰이 어떤 계략을 꾸미고 있는지도 꼭 알아내야 하오.\n\n티리스팔로 가서 밀짚인형 축제를 정탐해 보겠소? 성공하고 돌아오면 내 후하게 보상하겠소.", progress = nil, completion = "잘했소. 그 지독한 포세이큰 놈들이 로데론의 폐허에 남아있는 한 밀짚인형 축제는 계속 우리의 골칫거리로 남을 것 같소. 한때 영광스러운 왕국이 있던 자리에서 그런 녀석들이 활개를 치도록 내버려 둘 수는 없는데...\n\n여기 돈을 좀 줄 테니 수리비로 쓰도록 하시오. 그리고 축제 기간이고 해서 재미 좀 볼 물건도 드리겠소. 즐거운 할로윈 축제 보내시오. 그리고 우리 이곳 사우스쇼어는 되도록 안전하게 지키도록 합시다.", rewards = "다음과 같은 것들을 받습니다:\n\n할로윈 축제 호박"},
[1661] = {title = "고결함의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화해야 합니다.", description = "다시 만나게 되는군. 자네를 <형제/자매>라고 부를 수 있다는 사실이 그 어느 때보다도 자랑스럽네. 자네의 헌신은 우리 모두에게 큰 힘이라네.\n\n이제 자네에게 큰 선물을 줄 때가 되었군. 하지만 이것만은 알아두게나. 지금은 이걸 아무런 대가 없이 주지만 후에 때가 되면 내 임무를 수행하기로 결정한 모든 성기사들에게 훨씬 더 큰 도전이 될 걸세.\n\n다시 날 찾아오게나. 그러면 아주 큰 보답을 해주겠네.", progress = nil, completion = "축하하네. 성스러운 빛의 가호가 있기를.", rewards = "다음과 같은 것들을 배웁니다:\n\n군마 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n군마 소환"},
[1665] = {title = "바틀비의 술잔", objective = "벌가드에게 바틀비의 술잔을 가져가야 합니다.", description = "알았다고. 여기 있소. 잠깐! 그 안에 든 술이나 마저 마시고... 자, 이제 가져가쇼.", progress = "바틀비와 싸우는건 잘 봤네. 잘했어! 그래, 술잔은 가져왔나?", completion = "가져왔군! 녀석이 술잔 넘겨주기를 굉장히 아까워하던데 당신 실력이 썩 좋군그래. 잘했네.\n\n자, 그럼 훈련을 시작하세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n방어의 길\n\n다음과 같은 것들을 받습니다:\n\n"},
[1666] = {title = "치안대장 해거드", objective = "치안대장 해거드와 대화하십시오.", description = "어디보자, 기술은 익혔으니 이제 쓸만한 무기가 필요하겠군그래. 치안대장 헤거드를 찾아가면 분명히 자네를 도와줄 걸세.\n\n치안대장 해거드는 엘윈 숲에 있는 동부 벌목지의 저택에 살고 있다네. 지금은 은퇴했지만 현역에 복무하는 동안 많은 장비를 수집했지.\n\n가서 내가 보내더라고 말하면 자네에게 알맞은 무기를 줄 거야.", progress = nil, completion = "거기 누군가? 벌가드, 자넨가? 좀 더 가까이 와 보게. 이제는 눈이 침침해서 잘 안 보여서 말이야. 걸음걸이가 그러니 놀인 줄 알았잖나!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1667] = {title = "썩은니 잭", objective = "썩은니 잭의 야영지에서 치안대장 헤거드의 휘장을 찾아 치안대장 해거드에게 돌아가십시오.", description = "벌가드가 보냈단 말이지? 그래, 여분의 무기가 좀 있네만, 먼저 자네에게 맡길 임무가 있다네...\n\n얼마 전에 썩은니 잭이라는 데피아즈단의 악당이 날 속였어. 어두운데다가 스톰윈드의 휘장을 걸치고 있길래 치안대장 더그한인 줄 알았지. 내 스톰윈드 치안대장 휘장을 빌려달라고 해서 그 녀석에게 줬다네... 그랬더니 녀석이 날 비웃고는 달아나 버렸지 뭔가!\n\n내 휘장을 되찾아 주게! 틀림없이 썩은니 잭이 남쪽에 있는 자신의 야영지에 숨겨 놓았을 걸세.", progress = "내 휘장은 찾았나? 그걸로 녀석이 일으키게 될 말썽을 생각하면 끔찍하네.", completion = "훌륭해! 찾았구만! 나는 그걸 영영 잃어버리고 데피아즈단이 스톰윈드의 관리인 체하고 다니게 될까 봐 두려웠다네. 뭐, 자네 덕에 이제 그럴 일은 없겠군. 고맙네.\n\n내가 치안대장일 때 쓰던 무기 몇 가지가 여기 있네. 손질은 잘해 왔으니 맘에 드는 것을 골라 보게!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n해거드의 도끼해거드의 망치해거드의 단검해거드의 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1678] = {title = "베즈렉", objective = "베즈렉을 처치하고 그 증거로 그의 머리카락을 아이언포지에 있는 무렌 스톰파이크에게 가져가야 합니다.", description = "전사로서 신분을 높이려면 강해져야 하네. 새로운 기술을 가르쳐 주기 전에 자네가 정말 강한 적들과 싸울 준비가 되어 있다는 것을 보여 주게나.\n\n이 근방에서 제일 강한 트롤인 베즈렉을 꺾고 돌아오게. 그는 서리갈기 소굴의 바로 남쪽 구릉지에 있는 오두막에 있네.\n\n베즈렉을 처치하고 그 증거를 가져오면 자네의 배짱을 알게 되겠지.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n방어의 길\n\n다음과 같은 것들을 받습니다:\n\n"},
[1679] = {title = "무렌 스톰파이크", objective = "무렌 스톰파이크와 대화하십시오.", description = "안녕하신가, 전사 친구! 재능이 많아 보이는 전사로군. 하지만 아직 배워야 할 것이 많으니 무렌 스톰파이크라는 드워프에게 배움을 청하는 게 제일 좋을 거야.\n\n무렌은 아이언포지의 군사 지구에 있는 전투의 전당으로 가면 만날 수 있지. 전사로서의 길이 어떤 것인지 배울 준비가 되었다면 그를 만나보도록 하라고.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1680] = {title = "토르무스 딥포지", objective = "토르무스 딥포지와 대화하십시오.", description = "이제 몇 가지 기술을 배웠으니 쓸만한 무기를 한번 찾아보게. 토르무스 딥포지를 찾아가면 분명 자네가 좋아할 만한 무기를 만들어 줄 수 있을 걸세.\n\n토르무스는 이곳 아이언포지의 대용광로에 있네.", progress = nil, completion = "무렌이 보냈단 말이오? 괜찮은 무기야 물론 만들어 줄 수 있지만... 그 전에 한 가지 부탁이 있소.\n\n위험천만하여 목숨을 내놓게 될지도 모르는 일이니 당신과 같은 &lt;class&gt;에게는 적당한 부탁이 아니겠소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1681] = {title = "아이언밴드 야영지", objective = "아이언포지에 있는 토르무스 딥포지에게 움브랄 광석을 가져가야 합니다.", description = "내 스승이신 스투르기 아이언밴드께서는 던 모로 동부, 투구바닥 호수 남쪽에 야영지를 하나 갖고 계셨지. 스승께선 그곳에서 제철공학을 가르치셨는데 그 분야에선 최고셨소.\n\n그러던 어느 날, 제자들 중 하나가 이상한 광석을 가져왔소. 아이언밴드 선생님께서는 그것을 움브랄 광석이라 부르셨는데, 그 광석을 무척 연구하고 싶어하셨지. 그런데 그 광석을 가져온 지 얼마되지 않아... 검은무쇠단 드워프 패거리들이 나타나 야영지를 공격하여 모두 죽여 버렸소!\n\n아이언밴드 야영지로 가시오. 가서 내 스승님의 복수를 해 주시오. 그리고 이 비극의 원인이었던 움브랄 광석을 내게 가져와 주시오.", progress = "아어언밴드 야영지에는 들어가 봤소? 거기서 움브랄 광석을 찾은 거요?", completion = "찾았군! 잘 했소!\n\n광석을 찾는 동안 검은무쇠단 드워프 패거리에게 복수했다면 좋겠군. 그렇지만 녀석들이 아이언밴드 야영지에만 출몰하는 것은 아닐 것 같소이다.\n\n어쨌거나 광석을 가져다 줘서 고맙소. 열심히 연구해 이 광석의 성분을 알아내야겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1682] = {title = "움브랄 광석 무기", objective = "당신이 내게 가져온 새 움브랄 광석을 사용해 갓 만들어 낸 무기들이 여기 있소!\n\n자, 어디 한번 골라 보시오!", description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n움브랄 도끼움브랄 철퇴움브랄 단검움브랄 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1683] = {title = "볼루스 바일후프", objective = "다르나서스에 있는 엘라나리아에게 볼루스의 뿔을 가져가야 합니다.", description = "먼저 내게 당신의 결의를 확인해 보고나서 훈련을 시작하겠어요.\n\n볼루스 바일후프라는 사티로스가 바네실 지하굴에서 남동쪽으로 멀리 떨어진 우리 달샘 하나를 찾았어요. 지금 그 안에서 텀벙거리며 달샘의 순수한 물을 더럽히고 있죠.\n\n달샘에서 볼루스를 찾아 처치하세요. 증거로 그의 뿔을 내게 가져오면 전사 상급 훈련을 시작하도록 하겠어요.\n\n달샘으로 가는 길은 찾기 어렵지만, 한눈 팔지 않고 잘 살피면 찾을 수 있을 거예요.", progress = "뿔을 가져왔나요? 달샘에서 그 요물 볼루스를 제거했나요?", completion = "잘했어요. 볼루스가 제거되고 이제 달샘이 정화됐다니 안심이군요. 젊은 &lt;class&gt;들이 우리가 사랑하는 텔드랏실을 타락으로부터 지키려고 노력하는 모습은 늘 보기 좋군요.\n\n자, 이제 훈련을 시작하죠.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n방어의 길\n\n다음과 같은 것들을 받습니다:\n\n"},
[1684] = {title = "엘라나리아", objective = "엘라나리아와 대화하십시오.", description = "전사여, 당신의 기술은 점점 늘어가지만 전사의 길은 생각만큼 단순한 게 아닙니다. 이제 스승을 찾아 기술을 더 향상시켜야 할 때입니다.\n\n다르나서스의 전사의 정원에 있는 엘라나리아라는 전사를 찾아가 보십시오. 당신에게 좋은 스승이 될 테니...다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1685] = {title = "게이킨의 부름", objective = "스톰윈드의 마법사 지구에 있는 대흑마법사 게이킨에게 보고해야 합니다.", description = "어떻게 항상 이런 식이지? 내가 하루종일 당신을 찾아 다닐때는 코빼기도 보이지 않더니, 이젠 포기하고 있으니 이렇게 불쑥 나타난단 말이야.\n\n당신 때문에 시간 낭비는 충분히 했으니 바로 본론으로 들어갑시다. 게이킨님께서 추가 훈련을 위해 당신을 찾고 계시오. 내 생각엔 당장 찾아가 뵙는 것이 좋을 것 같소.\n\n그 분은 어둠의 희생양 선술집 지하실에 계실 것이오. 가면서 사람들 눈에 띄지 않도록 언행을 조심하는 게 좋을 거요. 위치가 탄로나거나 소문이 나면 곤란하니까 말이오.", progress = nil, completion = "이제서야 나타났군그래. 하긴 자네를 찾는 일을 레멘에게 맡기지 말고 더 유능한 다른 친구를 보내야 했었어. 뭐, 상관없네.\n\n자네는 너무 오랫동안 훈련을 받지 않았네. 훈련을 하지 않는 &lt;class&gt;는 곧 죽어도 할 말이 없다는 건 알고 있겠지?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1686] = {title = "엘룰라의 유령", objective = "다르나서스에 있는 엘라나리아에게 엘루니트 광석 상자 8개와 엘루라의 메달을 가져가야 합니다.", description = "이제 무기를 하나 만들기로 해요.\n\n전사를 위한 무기를 말이에요. 그러기 위해서는 먼저 어둠의 해안으로 가야 해요. 오래전, 아우버다인 등대 근처에서 난파된 배 한 척에서 엘루니트 광석이 든 수많은 상자가 바다 밑으로 가라앉았죠.\n\n엘루니트의 수호자인 엘루라의 유령을 물리쳐야 해요. 그는 원래 그 배의 선장이었지만 자신의 뱃짐을 지키기 위해 영원히 바다 깊은 곳을 누비도록 스스로 저주를 걸었죠. 그녀를 물리치고 그녀의 메달을 빼앗은 후 잃어버린 엘루니트 상자를 가져오세요.", progress = "엘루라의 유령을 물리쳤나요? 잃어버린 엘루니트 광석은 가져왔고요?", completion = "용감히 해냈군요.\n\n그대의 힘으로 엘루라의 유령에게 안식을 선사한 거예요. 이 엘루니트 광석들로 그대를 위해 좋은 무기를 하나 만들어 드리죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1687] = {title = "무서운 등대", objective = "랜디스를 서부 몰락지대 해안에 있는 등대로 데려가야 합니다.", description = "보육원에서는 가끔 밤 늦게 선생님들이 무서운 얘기를 들려주곤 하는데, 진짜 재미있어요! 그 중 하나는 서부 몰락지대에 있는 등대에서 나타나는 유령에 관한 거예요. 그 유령은 원래 해적 선장이었는데, 다른 해적에게 자기 배를 빼앗겼다나 봐요. 굉장하죠!\n\n서부 몰락지대에 있는 그 등대로 저를 데려가 주실래요? 그 해적 선장 유령이 있나 보고 싶어요! 혼자서 달아나지 않고 옆에 바싹 붙어 있을게요!", progress = nil, completion = "우와! 진짜 유령이었어요! 정말 멋져요. 빨리 보육원에 있는 아이들에게 말해주고 싶어 죽겠어요. 그레이슨 선장이랬죠... 모습까지도 해적이었다니까요! 저도 이 다음에 커서 유령 해적 선장이 되고 싶어요!\n\n서부 몰락지대로 데려다 주셔서 고맙습니다. 서부 몰락지대 황야에는 무서운 것들이 돌아다닌다고 알고 있는데, 제가 너무 귀찮게 하지 않았다면 좋겠네요. 형은 정말로 친절한 분이세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1688] = {title = "슈레나 캘리돈", objective = "슈레나의 목걸이를 찾아 스톰윈드에 있는 대흑마법사 게이킨에게 가져가야 합니다.", description = "내겐 슈레나 캘리돈이라는 이름의 제자가 있었네. 바로 지금 자네가 서 있는 자리에 서 있었지. 흑마법을 간절히 배우고 싶어하는데다가 마법적인 재능도 보통이 아니었어. 게다가 젊고 인물도 아주 빼어난 녀석이었지. 몹쓸 녀석같으니! 내가 그때 알아봤어야 했는데...\n\n그 도둑 같은 제자 녀석이 데피아즈단의 일원인 엘런 드러지무어라는 녀석과 달아나 버렸네. 그 녀석을 잃은 건 그리 중요하지 않지만 내가 그 녀석에게 소중한 혈석 목걸이를 선물로 줘 버렸었네.\n\n그 녀석은 브랙웰 호박밭에 있을 걸세. 그 녀석의 목숨이야 이제는 내 알 바 아니니 내 물건이나 좀 되찾아 주게나.", progress = "나이 많고 지혜로운 자마저도 젊음과 아름다움의 유혹에 빠져들 수 있다네. 이 충고를 명심하면 일생 도움이 될 거야.", completion = "슈레나는 재능이 있었지만 흑마법을 스스로 통달할 정도는 아니었네. 그 재능이 낭비된 건 아깝지만 때로는 이렇게 하는 것도 필요하지.\n\n이번에는 지난번과는 다른 결과를 낳았으면 좋겠군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1689] = {title = "결속", objective = "혈석 목걸이를 사용하여 보이드워커를 소환해 제압한 후, 스톰윈드에 있는 대흑마법사 게이킨에게 혈석 목걸이를 돌려주어야 합니다.", description = "슈레나를 물리치고 내 목걸이를 찾아왔으니 자네가 그녀만큼은 재능이 있다는 것을 증명해 보였군.\n\n그렇다고 해도 자네는 아직 많은 수련이 필요해. 마법의 흐름은 다룰 줄 아는 것만으로 진정한 흑마법사가 되는 것은 무리가 있네.\n\n내 보이드워커를 다루는 법을 보여 주도록 하지. 그 전에 소환 마법진에서 보이드워커를 불러내 물리적이든 마법적이든 자네가 갖고 있는 무기를 써서 제압해야만 하네. 아래층에 있는 소환 마법진으로 가서 이 목걸이의 마법을 사용하도록 하게.", progress = "자네가 보이드워커를 이기기 전엔 녀석을 다루는 방법을 가르쳐줄 수 없네.", completion = "기대했던 것보다는 잘해냈지만 아직 멀었군그래. 자, 이제 자네가 사로잡은 보이드워커를 다루는 법을 배워 보도록 하지. 보이드워커는 앞으로 자네가 난관을 헤쳐나갈 때 아주 귀중한 친구가 돼 줄걸세.\n\n지금 당장에는 더 이상 가르쳐 줄 것이 없지만 아직 훈련이 많이 남아있다는 것을 명심하게나.", rewards = "다음과 같은 것들을 배웁니다:\n\n보이드워커 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n보이드워커 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1690] = {title = "사막유랑단 처단", objective = "가젯잔의 동쪽에서 10명의 사막유랑단 약탈자와 좀도둑을 처치한 후, 선임기술자 빌지위즐에게 돌아와 보고하십시오.", description = "이 보시오, <race>! 당신이 가젯잔 수자원개발회사에 큰 도움을 줄 때가 됐소.\n\n타나리스 사막을 떠돌아다니는 사막유랑단 녀석들이 우물을 거의 다 빼앗아 버렸소! 우물을 사용하지 못한다면 우리의 수자원 공급은 곧 모두 바닥나 버릴 거요. 우리와 돈독한 관계를 맺고 싶다면 그 유목민 녀석들에게 정의의 처단을 내리시오!\n\n여기서 동쪽으로 가서 10명의 사막유랑단 약탈자와 좀도둑을 처치한 다음 즉시 내게 돌아와 보고해 주시오. 이곳 사람들... 아니, 고블린들의 정의를 위해서 어서 서두르시오!", progress = nil, completion = "당신이 그 떠돌이 놈들의 수를 줄여 주었으니, 이제 우리의 우물을 되찾을 수 있게 되었소. 이게 바로 효율성이라는 것이오!\n\n가젯잔 수자원개발회사를 대표해 감사를 표하겠소. 하지만 그 몹쓸 유목민 녀석들 문제를 완전히 끝내 버리려면 아직도 멀었소. 잘 들으시오. 이제부터 우리가 해야 할 일은 이런 거요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1691] = {title = "사막유랑단 추가 처단", objective = "가젯잔에 있는 선임기술자 빌지위즐을 위해 사막유랑단 도적 8명, 사막유랑단 암살자 6명, 그리고 사막유랑단 어둠마법사 10명을 처치해야 합니다.", description = "이제 당신은 그 사막의 떠돌이들 중에서도 좀 더 강한 녀석들을 상대해야 하오. 지금까지도 큰 도움이 됐지만 좀 더 합리적인 전략을 세웠다오. 가능한 적은 수를 처치해서 우물을 되찾을 수 있다면 좋지 않겠소!\n\n그러니 이번에는 사막유랑단 도적, 암살자, 어둠마법사를 처치해 주시오. 여기서 동쪽과 남동쪽으로 가면 녀석들을 찾을 수 있을 거요.\n\n녀석들은 아주 지독한 놈들이오. 괜한 허풍이 아니오. 이 일만 잘해주면 애초부터 우리 소유였던 자원을 확실히 되찾을 수 있을 거요!", progress = "그래, 내가 부탁한 대로 그 유목민 녀석들을 처치했소? 가젯잔 수자원개발회사에서는 당신이 이곳에서 성공을 거둔 임무를 기초로 모든 일을 계획하고 있소! 그러니 실망시키지 말아 주시오...", completion = "당신은 일처리 솜씨가 정말 최고요, 최고! 덕분에 우리가 직접 싸움을 걸 수 있을 정도로 녀석들의 수가 크게 줄었소!\n\n아까 유목민 녀석들을 처단하면서 사막유랑단 물주머니를 발견했다면, 지금 내 옆에 있는 양수기기사 루글룬켓과 얘기해 보시오. 아마 현상금을 두둑이 줄 거요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1692] = {title = "대장장이 메시엘", objective = "엘루니트 상자를 대장장이 메시엘에게 가져가야 합니다.", description = "당신이 가져온 엘루니트 광석을 상자에 넣어 놓았어요. 이 상자를 갖고 대장장이 메시엘을 찾아가면 엘루니트로 무기를 하나 만들어 줄 거예요.\n\n메시엘은 여기서 남쪽, 이 건물의 반대편에 있어요.", progress = "안녕하시오, 젊은 <class>. 내가 어떻게 도와 드리면 되겠소?", completion = "아, 엘루니트 광석이로군. 엘룬 여신께서 직접 축복을 내리신 아주 신성한 금속이오. 이 광석으로 무기를 만든다는 건 대장장이로서 큰 영광이오.\n\n잠시만 기다려 주시오...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1693] = {title = "엘루니트의 무기", objective = "당신이 가져온 엘루니트 광석으로 이 무기들을 만들었소. 가장 잘 맞는 것을 골라 가지시오.\n\n그리고 당신에게 감사하오. 엘루니트로 작업을 하는 것은 대장장이로서 영광이자 기쁨이니까.", description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n엘루니트 도끼엘루니트 망치엘루니트 단검엘루니트 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1698] = {title = "요루스 발리브루", objective = "요루스 발리브루와 대화하십시오.", description = "요루스 발리브루가 얼라이언스의 우수한 전사들에게 도전해 오고 있소. 그는 붉은마루 산맥에 있는 레이크샤이어 여관에서 기다리고 있는데, 자신의 시험을 통과하는 자에게는 후하게 보상할 것이라 공언하고 있소.", progress = nil, completion = "흠! 내가 낸 도전에 대해 들은 모양이군.\n\n그럼 앉아서 얘기를 들으며 술이나 한잔 하시오. 마지막으로 술 맛을 보는 걸지도 모르니 천천히 쭉 들이켜도록.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1699] = {title = "레스밴 도전", objective = "주어진 시간 내에 레스밴 동굴의 첫번째 분기점까지 들어갔다가 요루스 발리브루에게로 되돌아와야 합니다.\n\n죽어서 영혼이 빠져나가서는 안 됩니다.", description = "이 과제는 레스밴 도전이라고 하네. 도전에 성공하려면 레스밴 동굴의 첫번째 분기점까지 들어갔다가 되돌아오기만 하면 되네. 아주 간단하지 않나! 단, 몇 가지 규칙이 있네.\n\n레스밴 동굴로 가는 길에 널린 붉은마루일족 놀들을 뚫고 여기로 1시간 내에 되돌아와야만 하네. 또 시작하기 전에 우리 가문 특유의 술인 발리브루 스칼더 맥주도 한잔 쭉 들이켜야하지!\n\n어디 한번 해보겠나? 레스밴 동굴은 레이크샤이어 북쪽의 구릉지대에 있네. 자, 준비됐나?", progress = nil, completion = "해냈군! 잘했네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1700] = {title = "그리만트 엘모어", objective = "그리만트 엘모어에게 푸렌의 쪽지를 가져가야 합니다.", description = "자네에게 줄 갑옷을 만들면서 터득한 요령을 적어 놓았는데, 이 쪽지를 그리만트 엘모어에게 갖다주었으면 하네. 그는 이곳 드워프 지구에 있는 무기 상점에 있을 걸세.\n\n이 쪽지를 전해 주고는 재빨리 피하게. 그는 자기 실력에 대한 자부심이 대단해서 나한테서 뭔가를 배운다는 걸 아주 못마땅해 할 거야...", progress = "안녕하시오. 만나서 반갑소이다. 뭘 도와드릴까?", completion = "푸렌이 적은 거라고? 그자가 어찌 감히! 이런, 그자가 알고 있는 건 전부 내가 가르쳐 준 거요! 내게 뭔가를 가르칠 수 있다고 생각하다니! 이런 괘씸한 녀석을 봤나! 암! 괘씸하고 말고!\n\n흠... 나도 한번 써먹어 볼까...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1701] = {title = "불에 달궈 만든 갑옷", objective = "스톰윈드에 있는 푸렌 롱비어드에게 그가 필요로 하는 재료들을 모아서 가져가야 합니다.", description = "내 자네에게 좋은 방패를 주었네만 여기서 그칠 수는 없지. 내가 굉장히 단단한 쇠사슬 갑옷을 만드는 비기를 알고 있다네. 아주 희귀한 재료가 필요하고 만들기도 쉽지 않지만 다리품을 좀 팔아도 괜찮다면 내가 하나 만들어 주도록 하지.\n\n어떤가? 생각이 있다면 어디로 가서 뭘 구해 와야 하는지 적은 목록을 주겠네.", progress = "재료를 모으는 건 어떻게 되어가고 있나? 다 모아 왔는가?", completion = "다 모아 왔다고? 굉장하군! 분명 저 키메라 녀석들에게 잡아먹힐 거라고 걱정하고 있었는데 말이야!\n\n자, 그럼 당장 갑옷 만드는 작업을 시작하도록 하지...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1702] = {title = "방패 상인", objective = "푸렌 롱비어드에게 스칼더 술통을 가져가야 합니다.", description = "자네는 레스밴 도전을 치르면서 실력을 제대로 보여 주었네. 나는 약속을 어기는 일이 없는 정직한 드워프이니 약속한 대로 보상을 주도록 하지. 그런데 그게... 스톰윈드에 있단 말이야.\n\n스톰윈드의 드워프 지구에 있는 내 친구 푸렌 롱비어드를 찾아가 보시게. 둘째 가라면 서러워할 방어구 제작자인데, 나한테 큰 빚을 진 적이 있지.\n\n자, 푸렌에게 이 발리브루 스칼더 맥주통을 가져가서 방패를 하나 달라고 해보시오. 아주 괜찮은 놈으로 골라 줄 테니까 말이야.", progress = "안녕하시오! 요즘 날씨가 꽤 건조하지 않소?", completion = "아, 발리브루 스칼더 맥주로군. 좋은 술이지! 요루스를 만나고 오신 모양이로군.\n\n당연히 방패를 하나 주도록 하지! 어디가도 이보다 더 나은 방패는 찾지 못할 거요!", rewards = "다음과 같은 것들을 받습니다:\n\n푸렌의 방패"},
[1703] = {title = "메시엘", objective = "메시엘에게 푸렌의 쪽지를 가져가야 합니다.", description = "자네에게 줄 갑옷을 만들면서 터득한 요령을 적어 놓았는데 이 쪽지를 대장장이 메시엘에게 갖다주게나. 자네가 멀리 다르나서스까지 돌아가야 하겠지만 내가 터득한 걸 알게 되면 분명히 아주 고마워할 걸세.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1704] = {title = "클락몰트 스패너스판", objective = "클락몰트 스패너스판에게 푸렌의 쪽지를 가져가야 합니다.", description = "자네에게 줄 갑옷을 만들면서 터득한 요령을 적어 놓았는데, 이 쪽지를 클락몰트 스패너스판에게 갖다 줄 사람이 필요하네. 아이언포지에 사는 노움 대장장이인데 내가 이번에 터득한 요령을 가르쳐 주면... 분명 흥분해서 자기 수염을 쥐어뜯을 거야.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1705] = {title = "불타는 혈액", objective = "스톰윈드에 있는 그리만트 엘모어에게 불타는 혈액 20개와 불타는 보석 1개를 가져가야 합니다.", description = "인정하고 싶진 않지만, 정말로 푸렌이 쓸만한 기술을 발견한 모양이군. 하지만 확실하게 확인해 보기 위해 내 방어구에다가 푸렌이 고안한 기술을 써 보도록 하지. 재료를 모으는 것을 도와주면 내 방어구를 가져가도록 해 주겠소.\n\n갑옷을 만들려면 약간의 불타는 혈액과 불타는 보석이 필요하오.\n\n내가 알고 있기로는, 그것들을 찾을 수 있는 곳은 그늘숲 밖에 없소. 롤랜드 광산에 사는 파멸의어둠일족 늑대인간들이 불타는 혈액을, 그들의 두목인 거트스필이 불타는 보석을 가지고 있을 거요.\n\n행운이 있기를 빌겠소.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1706] = {title = "그리먼트의 갑옷", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n화염 경화 코이프"},
[1707] = {title = "물주머니 현상금", objective = "가젯잔에 있는 양수기기사 루글룬켓에게 사막유랑단 물주머니 5개를 가져가야 합니다.", description = "반갑소. 내 이름은 루글룬켓이오. 관심이 있다면 중요한 임무를 하나 맡기고 싶소! 하하!\n\n사막에서 사막유랑단 물주머니를 구해준다면 숙달된 양수기기사로서 그보다 더 기쁜 일은 없지. 그 물은 원래 우리 소유였으니까. 그 유목민 녀석들이 훔쳐갔을 뿐이오! 5개씩 모아올 때마다 가젯잔 수자원개발회사가 선물세트를 하나 증정할 거요. 물론 제일 중요한 보상은 당신이 가젯잔 고블린들을 도왔다는 사실 그 자체라오!", progress = "사막유랑단 물주머니 5개는 어디 있소? 구해왔다면 가젯잔 수자원개발회사 선물세트, 모델 103-XB는 당신 것이오!", completion = "아주 잘했소. 물주머니를 더 많이 찾을수록 우리는 끔찍한 갈증 걱정을  안 해도 되지! 계속 더 가져오면 고맙겠소. 물주머니 5개마다 반드시 보상이 따를 테니까.", rewards = "다음과 같은 것들을 받습니다:\n\n가젯잔 수자원개발회사 선물세트"},
[1708] = {title = "철산호", objective = "아이언포지에 있는 클락몰트 스패너스판에게 철산호 20개를 가져가야 합니다.", description = "푸렌 롱비어드의 새 기술을 내가 만들 방어구에 써 보고 싶어요. 당신이 푸렌을 도와줘서 푸렌이 새 기술을 알려준 거니까, 방어구가 완성되면 가져가도 좋아요!\n\n작업을 마치려면 철산호라는 특수한 산호가 필요해요. 이 산호는 저습지의 메네실 항구 남쪽 해안가에서만 자란답니다\n\n이 철산호를 충분히 가져오면 즉시 방어구를 완성할 테니 서둘러 주세요. 지금 내 발가락이 다 꼬이고 있는 거 보이세요? 어서 작업에 착수하고 싶어요!", progress = "안녕하세요, 다시 만나 반가워요! 철산호는 가져오셨나요? 어서 빨리 작업을 시작하고 싶어요!", completion = "바로 이거예요! 좋았어! 이제 이걸 녹이고 망치로 두들겨서 푸렌이 가르쳐 준 기술을 내 방어구에 적용하면 어떻게 될지 한번 보자고요!\n\n아, 정말 흥분되네! 틀림없이 무진장 단단한 방어구가 될 거예요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1709] = {title = "클락몰트의 창작품", objective = "자, 당신 갑옷이 여기 있어요. 푸렌의 제조법은 아주 훌륭하고 완벽하네요! 정말 놀랍도록 효과가 좋았다고요!\n\n증기 전차가 이 갑옷 위를 밟고 지나가더라고 멀쩡할 거예요!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n화염 경화 건틀릿"},
[1710] = {title = "바짝 마른 알껍질", objective = "다르나서스에 있는 메시엘에게 바짝 마른 알껍질 20개를 가져가야 합니다.", description = "내 동료 푸렌 롱비어드가 발견한 걸 어서 시험해 보고 싶소. 지금 연구 중인 방어구에 쓰면 좋은 결과가 나올 거요.\n\n좀 도와주지 않겠소? 필요한 재료를 모아 주면 방어구 하나를 만들어 드리리다.\n\n버섯구름 봉우리의 마루둥지에서 서식하는 마루둥지 와이번의 바짝 마른 알껍질이 필요하오. 둥지 아래에서 알껍질을 찾아서 내게 가져다주오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1711] = {title = "메시엘의 방어구", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n화염 경화 다리보호구"},
[1712] = {title = "사이클로니안", objective = "알터랙에 있는 바람의감시자 바스라에게 바스라의 양피지에 적혀 있는 물건들을 가져가야 합니다.", description = "나는 이곳에서 일어나는 일들을 지켜보며 오랜 세월을 보냈다네. 이러다 보면 언젠가 거대한 사이클로니안이 쓰러지는 것을 볼 수 있을 테니까 말이야. 하지만 아직도 그 바람의 군주를 쓰러뜨릴 만한 강자를 찾지 못했다네. 그 강자가 내 앞에 서 있는 바로 자네일지도 모르겠군.\n\n나에게 자네의 능력을 보여주게나. 사이클로니안을 소환하는데 필요한 물건들을 모아 오게. 그러면 자네가 훌륭한 전사라는 것을 알게 되겠지. 그러다가 혹시 사이클로니안을 쓰러뜨리고 그의 소용돌이 심장을 얻을 수 있을지도 모르는 일 아니겠나.\n\n그렇게만 된다면 그 심장의 힘을 불어넣은 무기를 자네에게 주도록 하지.\n\n여기 이 양피지에 필요한 물건의 목록을 적어 두었네.", progress = "물건들을 가져왔나? 그 물건들을 모아 와야만 자네가 사이클로니안을 상대할 힘을 지녔다는 증거가 될 것일세.", completion = "내 마법 주문에 필요한 물건을 모두 모아왔군. 자네의 힘과 능력이 대단해. 하지만 이 일의 다음 단계는 훨씬 더 위험하다네.\n\n자네의 그 넘치는 힘이 쇠하지 않길 바라세나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1713] = {title = "소환", objective = "바람의감시자 바스라에게 소용돌이의 눈을 가져가야 합니다.", description = "이제 사이클로니안을 소환하는 의식을 행할 준비가 되었네. 소환이 되면 녀석을 물리치고 녀석의 소용돌이의 눈을 꺼내야 하네. 그것으로 무기에 사이클로니안의 힘을 넣을 수 있을 걸세.\n\n바람의 군주에게 맞설 준비가 되었는가?", progress = "꼭 소용돌이의 눈을 가져와야 하네!", completion = "해냈군! 사이클로니안을 물리치고 소용돌이의 눈을 손에 넣었어!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1714] = {title = "떠도는 정령의 정수", objective = "가마솥이 끓고 증기가 하늘거립니다...", description = nil, progress = "가마솥이 끓고 증기가 하늘거립니다...", completion = "부적이 서서히 가마솥 깊숙이 가라앉습니다...\n\n큰 방울이 액체 표면으로 올라와 터집니다...\n\n...그리고 끓고 있는 녹은 돌이 드러납니다.", rewards = "다음과 같은 것들을 받습니다:\n\n떠도는 정령의 정수"},
[1715] = {title = "어둠의 희생양", objective = "스톰윈드의 마법사 지구에 있는 대흑마법사 게이킨에게 보고하십시오.", description = "흠... 그 옛날에 카즈 모단의 모든 흑마법사들은 우리의 놈리건에서 훈련을 받았었죠. 그러나 이젠 아이언포지의 이 쥐구멍 같은 곳으로 밀려나 마그니의 감시를 받는 신세니, 신참들을 훈련시키려면 스톰윈드로 보내는 수밖에 없어요.\n\n다행히도 게이킨님은 유능하신 분이라 당신을 잘 가르쳐 줄 거요. 하지만 생각할수록 억울하군요!\n\n어쨌거나, 스톰윈드로 가서 어둠의 희생양이라는 선술집의 지하실에 가서 게이킨님을 만나보도록 하세요.", progress = nil, completion = "블랙렌치가 보냈다고? 아이언포지의 그 바보 같은 &lt;class&gt; 녀석들은 정신 좀 차려야 돼. 스톰윈드가 얼마나 좁은지를 모르는 모양이군. 이렇게 신참들을 막무가내로 보내오면 언젠가는 이 은신처가 적에게 들통나 버리고 말 거라고!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1716] = {title = "영혼에 굶주린 자", objective = "불모의 땅에 있는 현자 타카르와 대화하십시오.", description = "세이야드는 영혼에 굶주린 자이자 의지의 지배자이며 마음을 유혹하는 자라네. 악으로 가득 찬 피조물이지.\n\n추잡한 이야기들을 들어 보면 이 악마들을 공통적인 이름으로 부른다네. 여자 악마는 서큐버스, 남자 악마는 인큐버스라고 하지.\n\n이 존재들을 불러들이려면 자극제가 필요할 게야. 사랑의 징표를 미끼로 사용한다면 분명히 자네의 부름에 응할 걸세. 그러고 나서 놈을 제압하여 자네의 것으로 만들게나.\n\n하지만 이런 성질을 지닌 자극제는 찾기가 어려울 거야. 칼림도어의 타우라조 야영지 근처 불모의 땅에 있는 현자 타카르라면 조언을 해줄 수 있을 걸세.", progress = nil, completion = "이곳으로 오는 데 별일 없었소? 나를 만나러 멀리 왔군그래. 허허, 걱정하지 마시오. 게이킨이 왜 자네를 보냈는지 알고 있으니까 말이오. 그 친구가 자넬 나에게 보내길 잘한 것이지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1717] = {title = "게이킨의 부름", objective = "스톰윈드의 마법사 지구에 있는 대흑마법사 게이킨에게 보고하십시오.", description = "오 <class>|1이로군;로군;! 이곳에서 당신을 보게 될 줄은 정말 몰랐는데... 어쨌거나 난 당신을 찾아오라는 명을 받았소.\n\n수련을 쌓아야 할 때가 지났으니 스톰윈드에 들러 게이킨님을 찾아가 보시오. 당신을 기다리고 계실 거요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1718] = {title = "섬 사람", objective = "클라녹 맥클라우드와 대화하십시오.", description = "전사로서의 명성이 점점 커져 가고 있군요. 이제는 당신의 동료전사들과 실력을 겨루어 볼 때가 되었습니다.\n\n톱니항의 남쪽, 불모의 땅 해안에서 조금 떨어진 곳에 섬이 하나 있습니다. 그곳을 격투의 섬이라고 하는데, 전사들이 만나 서로 실력을 겨루는 곳이지요.\n\n격투의 섬의 교관인 클라녹 맥클라우드와 대화를 나눠 보세요. 클라녹이 당신에게 자격이 있다고 판단하게 되면 더 강한 전사의 길로 인도해 줄 것입니다.\n\n격투의 섬으로 가려면 무역 해안을 따라 얕은 모래 언덕을 찾아 따라가보도록 하세요.", progress = nil, completion = "어서 오시오, &lt;class&gt;여. 이 먼 격투의 섬까지 발걸음을 하다니 반갑군. 이곳이 마음에 들었으면 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1719] = {title = "격투장", objective = "싸움꾼 윌을 꺾고 격투의 섬에 있는 클라녹 맥클라우드과 대화하십시오.", description = "나에게서 광전사로서의 자세를 배우고 싶다면 먼저 격투에서 이겨야만 하오. 이곳 격투의 섬은 자신이 강하다고 생각하는 유망한 전사들이 모여 있는 곳이오. 격투에서 승리하게 되면 만천하에 자신의 강함을 증명해 보이게 되는 것이지.\n\n격투를 시작하려면 저기 모인 관중 중앙의 격투장 위에 서시오. 그러면 트위기 플랫헤드가 당신이 준비된 것으로 알고 도전자들을 내보낼 거요.\n\n도전자들을 모두 이기면 싸움꾼 윌이 나올 테니 그를 꺾고, 주어진 시간 안에 내게 돌아오시오.", progress = nil, completion = "잘했소. 격투의 시험을 통과했군!\n\n과연 당신은 훌륭한 &lt;class&gt;요. 당신을 가르치게 되어 영광이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n광전사의 길\n\n다음과 같은 것들을 받습니다:\n\n"},
[1738] = {title = "사랑나무", objective = "잿빛 골짜기에서 사랑나무를 찾아 스톰윈드의 마법사 지구에 있는 대흑마법사 게이킨에게 가져가야 합니다.", description = "당신이 올 것을 예감하고 나는 투시력을 사용하여 시간의 안개를 뚫고 세상을 살펴보았소. 그래서 당신이 찾고 있는 게 무엇인지 알아냈지.\n\n고대인의 전쟁 당시 서로 사랑하던 두 연인이 전투 중 함께 목숨을 잃고 말았소. 그리고 그들이 숨을 거둔 곳에서 불멸의 사랑을 상징하는 사랑나무가 자라났소.\n\n그거라면 서큐버스 하나 정도는 충분히 꾀어낼 수 있을 거요. 사랑나무는 잿빛 골짜기 숲의 북서쪽에 있는 오르딜아란의 폐허에서 찾을 수 있을 거요.", progress = "구해 왔소?", completion = "좋아, 이거면 될 것 같군. 잠시 살펴보자고...\n\n타카르는 곁에 두면 참 도움이 되는 친구인데... 다시 속세로 나오도록 설득할 수만 있다면 좋으련만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1739] = {title = "결속", objective = "사랑나무 줄기를 사용하여 서큐버스를 소환해 제압한 후, 어둠의 희생양 선술집에 있는 대흑마법사 게이킨에게 사랑나무 줄기를 가져가야 합니다.", description = "이 사랑나무 줄기를 사용해 아래층에 있는 소환 마법진에서 서큐버스를 불러올 문을 여는 마법을 시전할 수 있을 걸세.\n\n조심하게나. 서큐버스들은 정신력이 아무리 강한 사람이라도 쉽게 압도해 버릴 만한 능력이 있으니 말이야.\n\n서큐버스를 이겨 황천으로 돌려보낸 후 다시 나에게 돌아오면 서큐버스를 부리는 방법을 가르쳐 주도록 하지.", progress = "가끔 생각해 보면 슈레나는 내 정신을 헤집어 놓으려고 변장한 서큐버스가 아닌가 싶어... 흠, 내가 그녀를 너무 과신했던 모양이지.", completion = "잘했네, 잘했어. 자네를 가르친 보람이 있군그래. 솜씨가 보통이 아니야.\n\n내 기꺼이 서큐버스를 부리는 방법을 가르쳐 주도록 하지. 잘 봐 두게.", rewards = "다음과 같은 것들을 배웁니다:\n\n서큐버스 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n서큐버스 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n작은 영혼의 가방"},
[1740] = {title = "소랜루크 수정구", objective = "소랜루크 조각 3개와 큰 소랜루크 조각 1개를 찾아 불모의 땅에 있는 도안 카르한에게 가져가야 합니다.", description = "전투 중 불타는 군단 악마들은 생명이 소실되었고 쓸모 없어진 그들의 영혼은 수정구 안에 갇히게 됐어요. 그리고 군단 내 마법사와 흑마법사들의 손에 넘겨졌지요. 아제로스에 있는 불타는 군단의 수하들이 이 수정구들을 지니고 다녔는데, 수정구가 산산조각으로 깨져도 그 안에 담긴 악마의 힘은 그대로 유지되었답니다.\n\n소랜루크 수정구는 두 조각으로 깨졌는데 그 중 한 조각은 더 잘게 부서져 검은심연의 나락에 있는 황혼의망치단 수행사제들이 쓰고 있지요. 그리고 좀 더 큰 나머지 조각은 그림자송곳니 성채에 있는 마술사가 갖고 있습니다. 그 조각들을 찾아서 가져오면 다시 원래 모양으로 만들어 보겠습니다.", progress = "내가 오랜 세월에 걸쳐서 힘들게 모은 잘가인의 수정구 조각들은 정말 큰 도움이 되어 주었답니다. 틀림없이 당신에게도 소랜루크의 수정구가 아주 유용할 거요.", completion = "그나마 다행이군... 수정구가 아주 여러 조각으로 깨진 것은 아니었어. 부탁 드린 조각들을 전부 가져왔군요. 이 조각들을 붙여서 소랜루크의 수정구를 다시 완전한 형태로 만드는 건 간단한 일입니다.\n\n제 평생을 불타는 군단의 수정구를 재생하기 위한 연구에 바쳤습니다. 수정구 조각을 모아 주다니 제 연구에 큰 보탬이 될 거예요. 당신의 은혜에 어떻게 보답해 드려야 할지... 자, 원하시는 형태에 맞게 완전히 복원된 수정구나 지팡이를 드릴 테니 받아 주십시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n소랜루크 수정구소랜루크의 지팡이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1758] = {title = "비밀의 고서", objective = "아이언포지에 있는 크롬 스타우트암과 대화해야 합니다.", description = "지옥사냥개를 소환하려면 단순한 소환 마법진으로는 어림도 없소.\n\n나와 나의 수행사제 세 명이 함께 마법진 만드는 것을 도와줄 거요. 음... 그러려면 비밀의 고서가 필요한데 잃어버린 지가 꽤 오래된 물건이지. 그 책에는 누구의 도움도 받지 않고 처음으로 지옥사냥개를 소환해낸 흑마법사들의 기록이 들어있소.\n\n크롬 스타우트암이 당신을 도와줄 수 있을지도 모르겠군. 요즘은 여기저기 유랑을 하며 고대 서적들을 찾고 있다던데... 사람들의 눈을 피해 아이언포지의 도서관에서 나타난다고도 하오.", progress = nil, completion = "비밀의 고서라고? 흠... 들어 본 적은 있는데 여기서는 못 봤네. 난 한번 읽은 책은 절대 잊어버리지 않거든.\n\n흠...\n\n참, 맞아! 도서관 서적 일람표에서 그 책을 본 기억이 나는군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1778] = {title = "신앙의 고서", objective = "아이언포지에 있는 타이자 배틀포지와 대화하십시오.", description = "어서 고향으로 돌아갈 준비를 해야겠네요. 제 아내 스테파니가 스톰윈드에서 잘 지내고 있었으면 좋겠어요. 아, 어서 빨리 보고 싶어요. 그럼, 다음에 또 만납시다.", progress = nil, completion = "정말 빨리 돌아왔군요! 이곳을 떠나서 따뜻한 도움의 손길을 베풀었나요?\n\n도움이 필요한 자의 숭고한 목적을 이루는 것을 도와주었나요? 자비의 가치와 동부 왕국의 자랑스러운 시민으로서의 의무에 대해 배웠을지도 모르겠군요. 자, 얘기해 주세요. 누구를 어떻게 도와주었는지... 대단하네요. 그것이야말로 빛을 수호하는 자의 자세입니다.\n\n그러한 희생정신은 언젠가 반드시 보상을 받게 된답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1779] = {title = "신앙의 고서", objective = "생명의 징표를 가지고 가서 아이언포지에 있는 뮈레돈 배틀포지와 대화하십시오.\n\n제공된 아이템: \n", description = "자, 받으세요. 생명의 징표라고 하는 물건입니다.\n\n이제까지 당신은 자비로운 마음과 굳센 인내심을 보여주었으니 이제 전투에서 버틸 힘이 얼마나 강해졌는지 증명해 보여야 해요.\n\n제 남편 뮈레돈이 최근 검은무쇠단 드워프들과 마주친 일이 있었는데 겨우 목숨만 건져서 도망쳐 왔답니다. 저쪽에서 사제에게 치료를 받고 있지요.\n\n이 생명의 징표를 가지고 가서 남편과 얘기해 보세요. 남편을 도와줄 수 있다면 곧 다시 얘기하도록 하죠. 빛의 서광이 언제나 당신께 환하게 비치기를...", progress = nil, completion = nil, rewards = nil},
[1780] = {title = "신앙의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화하십시오.", description = "오늘 당장 아이들에게 옷을 만들어줘야겠어요. 친절하신 <class>님, 살펴가세요. 이 삭막한 도시에서 당신처럼 인품이 좋은 분을 만났다는 건 행운입니다. 당신은 이곳 스톰윈드의 성기사들이 도움이 필요한 사람들에게 등을 돌리지 않는다는 것을 보여주셨어요.\n\n안녕히 가세요.", progress = nil, completion = "오, 생각보다 일찍 돌아오는군. 빛의 대성당을 떠나 있는 동안 어떤 일을 했는가?\n\n누군가의 숭고한 목적을 이루는 것을 도와주었는가? 자비의 가치를 배웠거나 아제로스 시민으로서의 의무에 대해 좀 더 배웠을지도 모르겠군. 자, 말해 보게. 누구를 어떻게 도와주었는지... 굉장하군. 그것이야말로 빛을 수호하는 자의 행동일세.\n\n그러한 희생정신은 언젠가 보상을 받게 된다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1781] = {title = "신앙의 고서", objective = "스톰윈드에 있는 가쟁 테놈에게 생명의 징표를 가져가야 합니다.\n\n제공된 아이템: \n", description = "자, 받게나. 생명의 징표라고 하는 물건이네.\n\n자네가 자비롭고 인내심이 강하다는 것을 증명하였으니, 이제는 자네가 빛의 정의로움이 선사하는 가장 큰 선물 중 하나에 힘을 집중할 수 있는지를 시험해 볼 때가 되었네.\n\n내 친구 가쟁이 최근 수호영웅의 안식처 근방에 있는 엘윈 숲 정찰을 나갔다가 데피아즈단과 맞닥뜨렸다네. 그는 겨우 목숨만 건져서 돌아왔지. 저 위 제단 옆에서 우리 사제가 상처를 치료해 주고 있네.\n\n생명의 징표를 가지고 가서 그와 얘기를 나누어 보게. 그를 도와줄 수 있으면 다시 또 얘기하도록 하지. 빛의 서광이 자네를 비추기를...", progress = nil, completion = "*쿨럭*\n\n만나서 반갑소. 친절하신 사제께서 이 가쟁을 돌봐주실 테니 내 상처는 걱정하지 마시오. 당신이 갖고 있는 그 생명의 징표의 힘을 빌릴 필요는 없을 거요. 적어도 아직은...\n\n그래, 두소리안이 보낸 모양이구려. 좋소, 나와 내 친구 헨즈에게 무슨 일이 있었는지 얘기해 주지. 그리고 당신이 &lt;class&gt;로서 솜씨가 좀 있고 운이 좀 따른다면 우리 모두를 도와줄 수 있을지도 모르겠소이다.", rewards = nil},
[1782] = {title = "푸렌의 갑옷", objective = "여기 자네 갑옷일세. 이 갑옷에 구멍이 난다면 내 이름은 푸렌 롱비어드가 아닐세. 내 장담하지!\n\n그리고 자네한텐 고마운 마음뿐이야. 자네가 가져온 재료로 작업을 하면서 많은 것을 배웠다네. 언젠가 또 큰 발전을 이루게 될 것 같단 말이지!\n\n내가 배운 것을 얼라이언스의 다른 대장장이들에게도 보내도록 하겠네.\n\n자네가 아주 큰 도움이 됐다고 얘기해 주도록 하지. 그러면 혹시 그들이 자네에게 보답을 할지도 모르니까 말이야, 허허!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n화염 경화 갑옷"},
[1783] = {title = "신앙의 고서", objective = "생명의 징표를 가져가서 던 모로에 있는 나름 폴크를 되살려야 합니다.", description = "우리는 투구바닥 호수 남쪽에 숨어 있는 검은무쇠단 드워프들을 감시하고 있었네. 아무래도 문제가 있는 듯해 나는 나름과 함께 더 가까이 가보기로 했지. 두목 녀석이 부하들에게 명령을 내리는 것이 보이더군.\n\n우리 둘이서 그 녀석들 몇 명을 해치우려고 했지만 생각보다 강했네. 지원군들이 나타나 우리를 덮치는 게 아닌가. 나름이 나더러 먼저 도망쳐서 지원을 요청하라고 했기에 여기 오게 된 것일세.\n\n난 나름을 도와야 해. 그 친구가 무사히 돌아올 때까지 쉬지 않을 걸세.\n\n날 도와줄 수 있겠나?", progress = nil, completion = "뭐라고 감사의 말을 해야 할지 모르겠군, &lt;class&gt; 친구!\n\n생명의 징표가 있는 것을 보니 타이자와 뮈레돈이 부탁한 모양이오.\n\n그래, 난 검은무쇠단 문서 하나를 빼내려다 놈들에게 당했소. 뮈레돈이 빠져나갈 동안 가까스로 버틸 수 있었지만, 당신이 와주지 않았다면... 이제 성스러운 빛이 나를 충만하게 감싸고 있소. 생명의 징표를 사용할 수 있다는 건 당신이 그만큼 강해졌다는 걸 뜻하지. 그 얘기는 나중에 다시 하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1784] = {title = "신앙의 고서", objective = "투구바닥 호수 근처에 있는 검은무쇠단 드워프들에게서 검은무쇠단 문서를 빼앗아 아이언포지에 있는 뮈레돈 배틀포지에게 돌아가십시오.", description = "전투에서 쓰러지기 전 뮈레돈과 나는 작은 집 근처에 있던 검은무쇠단 비밀 요원을 거의 해치웠었소. 두목이 그 자에게 명령을 내리는 것을 목격한 나는 그를 해치우고 문서를 낚아챌 생각이었지.\n\n아이언포지의 일부 원로들은 아직 던 모로에 검은무쇠단 드워프가 있다는 사실을 믿지 않고 있소. 그 문서 중 하나만이라도 손에 넣을 수만 있다면, 그들의 동태에 대한 증거도 얻고 무슨 음모를 꾸미고 있는지도 알 수 있을 것이오.\n\n문서를 빼내 뮈레돈에게 돌아가시오.", progress = "돌아왔나? 무사히 돌아와서 다행이네. 이제 상처도 다 나았고 곧 투구바닥 호수로 돌아갈 수 있도록 채비를 마쳤네. 물론 그 전에 우리 집사람이 걱정하지 않도록 설득시켜야 하지만 말일세.", completion = "하하! 해냈구려! 나름을 구해내고 집사람이 원로들에게 가져갈 증거물도 가져왔군. 당신이야말로 내가 본 중의 최고로 눈부신 빛의 축복이네. 당연히 우리 집사람은 빼고 말이야.\n\n다시 한번 감사하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1785] = {title = "신앙의 고서", objective = "아이언포지에 있는 타이자 배틀포지와 대화하십시오.", description = "집사람이 벌써 기쁜 표정을 짓고 있군그래. 당신과 얘기를 나누고 싶어할 테니 얼른 가 보게.\n\n빛의 가호를 비네, 강한 <class>|1이여;여;. 때가 되어 스컬지와 검은무쇠단 드워프들에게 맞서 싸우게 되면 내 꼭 전장에서 당신을 찾아보리다.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n구원\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n구원\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1786] = {title = "신앙의 고서", objective = "생명의 징표를 가져가서 엘윈에 있는 헨즈 폴크를 되살려야 합니다.", description = "나와 헨즈는 엘윈 북동부에 있는 돌무덤 호수의 한가운데에 위치한 섬인 수호영웅의 안식처까지 갔소. 데피아즈단이 우리 경계를 넘었다는 소식을 듣고 폐하의 참모들에게 가져갈 증거를 확보하고 싶었지.\n\n문서를 훑어보고 있는 데피아즈단 놈 두어 명을 발견하고 우린 그들을 공격했소. 곧 데피아즈단의 지원병들과 마법사들이 나타나 우린 꼼짝없이 당하고 말았지.\n\n헨즈는 내가 도망칠 수 있도록 뒤를 맡아 주었소... 무모한 짓을 하다니 바보 같은 친구.\n\n헨즈, 그 친구는 아직 그곳에 있소. 우릴 도와주겠소?", progress = nil, completion = "고맙소, 자매여.\n\n생명의 징표를 지닌 것을 보니 두소리안이나 가쟁이 보낸 것 같군.\n\n난 가쟁과 함께 데피아즈단의 문서를 빼내오는 도중 마술사 녀석들에게 당했소. 가쟁이 빠져나갈 동안은 버틸 수 있었지만 결국 녀석들의 마법에 당하고 말았지.\n\n하지만 자매가 날 되살려 주었소. 그 생명의 징표는 아무나 쓸 수 있는 게 아니오. 스스로 빛의 힘으로 생명의 징표를 사용할 수 있었다는 건 굉장한 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1787] = {title = "신앙의 고서", objective = "엘윈 숲에 있는 데피아즈단 견습마술사들에게서 데피아즈단 문서를 빼앗아 스톰윈드에 있는 가쟁 테놈에게 가져가야 합니다.", description = "징표에 관한 이야기는 나중에 계속하기로 하고 이제 데피아즈단 녀석들이 읽고 있던 문서를 빼내는 것이 좋겠소. 문서를 빼낼 수 있다면 데피아즈단의 엘윈 침략을 증명할 수 있으며, 녀석들의 계략이 어떤 것인지도 파악할 수 있게 될 거요.\n\n지금 내 상태로는 전투에 참여할 순 없을 거 같군. <형제/자매>가 이곳 섬에 있는 데피아즈단에게서 그 문서를 빼앗아 올 수 있겠소?\n\n문서들을 손에 넣으면 가쟁에게 가지고 돌아가시오. 내가 무사하다는 소식과 함께 말이오.", progress = "헨지는 무사한 거요? 임무는 성공적으로 마쳤소?\n\n당신의 무기를 다루는 솜씨와 빛의 힘이라면 수호영웅의 안식처는 그 어떠한 데피아즈단의 위협에도 걱정 없다고 생각하지만, 폐하와 그 참모들은 어떻게 생각할지 모르겠소이다.", completion = "좋았어! 문서를 가져오고 헨지도 구해냈군! 빛의 힘이 당신과 함께하는 게 분명하오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1788] = {title = "신앙의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화하십시오.", description = "이 문서는 두소리안에게 보여 준 후 폐하의 참모들에게 가져가겠소. 그동안 두소리안과 대화를 나누는 게 좋겠소. 그 친구는 분명 이번 일을 칭찬하며 자네 등을 두드려줄 거요!\n\n다시 한번 고맙다는 말을 전하오이다. 다시 만날 기회가 있었으면 좋겠군. 당신은 정말 자랑스러운 나의 친구이자 동지요.", progress = nil, completion = "오늘 아주 잘해 주었네. 대단하군그래.\n\n아무나 사용할 수 없는 생명의 징표의 힘을 끌어냈다는 것에 대해서 자부심을 가지게나. 빛의 힘을 사용해 죽은 이를 되살릴 수 있다는 것은 &lt;class&gt; 최고의 영예 중 하나인 부활의 힘을 지닐 자격이 있다는 뜻일세.\n\n그러면 자네가 헨지를 되살린 것처럼 전장에서 쓰러진 동료를 되살릴 힘을 지니게 될 것일세.\n\n몸조심하게나. 빛의 서광이 자네를 비추고 있으니 그 힘을 모두 받아들이게나.", rewards = "다음과 같은 것들을 배웁니다:\n\n구원\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n구원\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1789] = {title = "생명의 징표", objective = "생명의 징표를 사용해 나름을 돕는 일에 실패하면 내게 되돌아오세요. 생명의 징표를 하나 더 드리겠습니다.\n\n당신의 성공에 내 남편과 저의 모든 것이 달려 있어요. 부디 서둘러 주시기 바랍니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n생명의 징표"},
[1790] = {title = "생명의 징표", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n생명의 징표"},
[1791] = {title = "바람의감시자", objective = "바람의감시자 바스라와 대화하십시오.", description = "이제 광폭 태세를 배웠으니 이에 걸맞은 괜찮은 무기가 있어야겠지.\n\n알터랙 산맥과 서부 역병지대 사이에서 은둔하여 지내는 트롤인 바람의감시자 바스라를 찾아가시오. 그는 아주 솜씨 좋은 무기 제작자이자 강한 주술사지.\n\n바스라를 찾으려면 타렌 밀농장의 동쪽 강둑을 따라 흐르는 강으로 가면 되오. 바스라는 강을 따라 북쪽으로 가면 강의 동쪽 둑에 있는 폐허 근처에서 야영하고 있을 것이오.", progress = nil, completion = "멀리서 왔군, 젊은 &lt;class&gt;여. 자네 눈 속에 타오르는 불꽃이 보이네. 강한 무기를 찾고 있는 것 아닌가?\n\n내가 자네를 도와줄 테니 자네도 날 좀 도와주게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1792] = {title = "소용돌이 무기", objective = "소용돌이의 눈도 있고 이제 자네가 선택할 무기에 그 힘을 불어넣을 준비가 되었네.\n\n자, 고르게나. 이 힘은 사이클로니안의 힘일세.", description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n소용돌이 도끼소용돌이 검소용돌이 전투망치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1793] = {title = "용맹의 고서", objective = "이미 빛의 힘이 자네와 함께한다는 것은 증명되었네. 그러나 세상이 위험해질수록 신체의 힘을 길러 자신을 지키는 것도 중요하네. 악마, 용, 그리고 다른 악이 우리의 땅을 침략해 오면 자네의 용기를 시험하게 될 것이야. 자신이 충분히 강하다고 생각하나?\n\n어떤 상황에서든 빛의 힘과 방어구, 무기처럼 용기도 <class>의 일부분일세. 약한 자를 보호하고 정의로운 마음을 잃지 않는 것 역시 빛의 대성당에서 수련하는 동안 배워야 할 가르침일세.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n용맹의 고서"},
[1794] = {title = "용맹의 고서", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n용맹의 고서"},
[1795] = {title = "결속", objective = "비밀의 고서를 사용해 지옥사냥개를 소환해 제압한 다음 톱니항에 있는 스트라드 파선에게 사용한 고서를 돌려주어야 합니다.", description = "준비되었으면 이제 시작하도록 할 테니 설명을 잘 듣도록 하시오.\n\n먼저 내가 기본적인 소환 마법진을 만들겠소. 마법진이 완성되면 내 수행사제들이 정신 집중의 마법봉을 사용해 더 큰 마법진을 만들 것이오.\n\n마법진이 구성되면 비밀의 고서에 쓰인 주문을 읽으시오. 그러면 지옥사냥개가 소환되어 나올 것이오. 지옥사냥개는 아주 강하니 조심하는 게 좋을 거요. 꼭 살아남길 바라오.", progress = "<class>라면 지옥사냥개 한 마리 정도는 거느려야지. 길들이기는 힘들어도 고생한 보람을 느낄 만큼 강력하다오.", completion = "이제 인정하지 않을 수 없군. 당신 정말 대단해. 지난날, 내가 지옥사냥개와 맞섰을 때는 간신히 목숨만 건졌는데. 이 시대 최강의 &lt;class&gt;가 될 소질이 보이는군.", rewards = "다음과 같은 것들을 배웁니다:\n\n지옥사냥개 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n지옥사냥개 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n영혼의 용기"},
[1796] = {title = "흑마법사의 로브", objective = "불모의 땅에 있는 미네라 보이드렌더에게 아카나의 로브를 가져가야 합니다.", description = "먼저 로브를 만들어 드릴 테니 조금 도움을 주셔야 해요. 당신이 필요한 물건들을 모아 오는 데 성공하면, 전투에서 당신을 더욱 강하게 만들어줄 첫 번째 물건을 얻을 수 있어요.\n\n전에 아카나의 로브를 만들어 보았을 거예요. 재봉사가 대신 만들어 주었을 수도 있고, 다른 이에게서 구입할 수도 있겠지만 당신이 손수 만들 수 있다면 좋겠네요. 뭐, 어쨌든 당신이 그 로브를 하나 가져오면 다음 일을 계속하도록 하죠.", progress = "로브를 찾는 일은 어떻게 돼가고 있나요, <name>? 직접 만들었나요? 직접 물건은 마법부여가 더 잘 되는 것 같아요. 성취감도 더 크고요. 하지만 더 간편한 길을 택해서 다른 이에게 시켰다고 하더라도... 더 빨리 강해지고 싶은 당신의 야망은 이해합니다.", completion = "이거면 되겠어요.\n\n마법이 담긴 모든 물건은 반드시 품질이 뛰어난 것부터 사용하기 시작해야 해요. 더 많은 노력과 기술을 투자해서 만들수록 그만큼 더 강력한 마법을 갖게 되죠. 희귀하거나 값 비싼 재료들을 사용하면 마력이 더 잘 유지된답니다. 나중에 로브를 받아 보면 방금 수고하신 시간과 노력이 전혀 아깝지 않을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1798] = {title = "스트라드를 찾아서", objective = "불모의 땅에 있는 스트라드 파선과 대화해야 합니다.", description = "이제는 당신도 지옥사냥개 소환을 배울 때가 되었군. 이곳에는 당신을 가르치기 위해 필요한 물품이 없으니 당신이 우리 동지인 스트라드 파선을 찾아가야 할 것이야.\n\n그는 톱니항의 고블린 항구에서 살고 있소. 미리 당신이 찾아갈 것이라고 연락을 취해 두도록 하겠소.", progress = nil, completion = "아, 당신이로군? 우리가 가장 최근에 발견한 신동이로군. 하지만 언제나 실상은 전설을 못 따라가는 법이지.\n\n뭐, 그렇다고 해도 상관없소. 나한테 배우러 온 것이지 내가 농담하는 거나 들으러 온 건 아니니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1799] = {title = "오라힐 보주의 파편", objective = "톱니항이 내려다보이는 탑 안에 살고 있는 미네라의 조수들과 대화하고 그들이 제시하는 길 중 하나를 따라가야 합니다.\n\n그 후엔 지옥의 보주를 구해 먼지진흙 습지대의 타베사에게 가져가야 합니다.", description = "좋아요, 그럼 시작하죠.\n\n먼저 저 안으로 들어가 내 조수들과 대화를 해보세요. 그들이 안내하는 길 중 하나를 선택해 따라가세요. 자세한 설명은 그들에게 들으시고요\n\n그 후엔 잊혀진 땅으로 가서 만노로크 소굴의 흑마법사들 중 하나가 지니고 있을 지옥의 보주를 찾으세요. 그 보주는 먼지진흙 습지대 남부에 있는 마법사 타베사의 도움을 받아서 정화해야 합니다. 그녀는 나를 봐서라도 당신을 도와 줄 거예요.\n\n다시 한 번 말하지만 내가 부탁한 일을 모두 처리하기 전엔 돌아올 생각을 하지 마세요.", progress = "순수한 마법사가 아닌 당신을 믿어야 할지 모르겠군요. 게다가 비전 마법의 냄새까지 나는 걸... 하지만 당신과 같은 <class>에게 꼬여 드는 타락의 힘을 이겨낸 것 같군요.\n\n그래요, <class>... 내게 도움을 청하러 왔군요.\n\n자, 내가 무엇을 도와드릴까요, <name>?", completion = "그렇군요. 미네라가 보낸 거로군요. 좋아요... 내 손님으로 맞아들이죠. 그런데 당신은 뭔가 해야 할 일이 있지 않나요? 혹시 잃어버린 힘을 찾기 위해 여기까지 온건가요? 내가 착각한 건지도 모르겠군요. 어쩌면 당신은 머지않아 저 밖의 타락한 존재들과 같아질지도 모르겠네요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1801] = {title = "비밀의 고서", objective = "언더시티에 있는 조라 애니슨과 대화해야 합니다.", description = "당신이 맞설 지옥사냥개를 소환하려면 단순한 소환 마법진으로는 안 되오.\n\n세 명의 수행사제와 내가 마법진 만드는 것을 도와줄 것이오. 음, 비밀의 고서가 필요한데 잃어버린 지가 꽤 된 물건이지. 아무런 도움도 없이 최초로 지옥사냥개를 소환해낸 흑마법사들이 쓴 책이라오.\n\n조라 애니슨이 당신을 도와줄 수 있을지도 모르겠군. 요즘은 언더시티의 지도 제작자로 고용되어 일을 하고 있다지만 고대 서적에 대해서는 나보다 더 잘 안다오.", progress = nil, completion = "지도 제작? 현실 세계를 그림과 수치로 표현하는 것? 그 따위 것들은 아무 쓸모도 없지.\n\n진실은 설화, 소설, 일대기! 그런 것들 안에 존재하는 거라오. 강령술의 부흥이나 어둠의 여왕님이 승리하시는 이야기 한 권만 있으면 이 상점에 있는 지도 따위는 전부 다 줘 버릴 수 있지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1802] = {title = "비밀의 고서", objective = "아이언포지에 있는 크롬 스타우트암에게 곰팡이 슨 고서와 너덜너덜한 필사본을 가져가야 합니다.", description = "잃어버리긴 했지만 어디서 찾을 수 있을지는 대충 알고 있지.\n\n그 책은 딱 한 권밖에 만들지 않았는데 언젠가 한 부분이 크게 찢겨 나가 버렸네. 소문에 의하면 어쩌다 보니 버섯구름 봉우리에 사는 켄타우로스의 손에 떨어졌다는군.\n\n나머지 부분은 사우스쇼어의 서부 해안을 떠나 메네실 항구까지 배로 운송하기로 되어 있었는데 아직도 배가 도착하지 않았다고 하네.\n\n알려준 대가로 청이 하나 있는데 그걸 찾게 되거든 내게 가져와서 한 번만 보여주게나.", progress = "소문이 사실이던가?", completion = "멋지군! 나도 이 책을 본 소수에 포함되는 것이군.\n\n어서 이 책을 읽어 보고 싶어 못 견디겠군. 오늘은 행운의 날이야! 잠깐, 가기 전에 조금만 더 보여주게나. 스트라드가 분명 내게 사본 한 권을 보내 주겠지만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1803] = {title = "비밀의 고서", objective = "곰팡이 슨 고서와 너덜너덜한 필사본을 찾아 언더시티에 있는 조라 애니슨에게 가져가야 합니다.", description = "아! 당신도 나랑 취향이 비슷한 흑마법사인 모양이군. 비밀의 고서를 입수하는 것은 참으로 당찬 야심이오. 그 고서가 한때는 로데론 내에 보관되어 있었다는 건 알고 있소? 하지만 거의 절반이나 찢어져 버렸지. 대체 누가 그런 못된 짓을 했는지...\n\n그 찢어진 반쪽은 잃어버렸소. 하지만 소문을 듣자 하니 그것이 버섯구름 봉우리의 켄타우로스들 손에 들어갔다고 하오.\n\n나머지 부분은 아이언포지로 운송하기로 되어 있었는데 사우스쇼어의 서부 해안에서 운반 도중 사라졌다고 하더군.", progress = "당신은 동화 같은 얘기에 불과한 것을 쫓고 있는 것인지도 모르오. 하지만 말도 안 되는 소문 안에서 진실을 찾게 되는 법이지.", completion = "이런, 이런! 이게 대체 뭐요?\n\n정말로 놀랍군. 지금 내가 들고 있는 게 완전한 비밀의 고서란 말이오? 불가능할 거라고 생각했는데...\n\n떠나기 전에 잠시만 살펴보게 해주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1804] = {title = "비밀의 고서", objective = "톱니항에 있는 스트라드 파선에게 복원된 고서와 정신 집중의 마법봉 3개를 가져가야 합니다.", description = "벌써 돌려주려니 아쉽군. 하지만 분명 자네는 더 중요한 일에 써야 할 테니 어쩔 수 없군. 다만 잊지 말고 스트라드에게 내가 사본을 한 권을 꼭 갖고 싶어하더라고 전해주게나.\n\n그나저나 자네가 이곳을 떠나 있는 동안 새로운 전갈이 왔더군. 수행사제들이 소환을 도와주려면 정신 집중의 마법봉 세 개가 필요하다고 했다네.\n\n그는 어디서 마법봉을 찾야아 할지 모를 거야. 하지만 걱정말게. 얼마 전에 내가 최신 정보를 얻었으니까! 저습지에 있는 용아귀부족의 오크들이 마지막으로 정신 집중의 마법봉을 사용했다니 그곳으로 가보게. 그동안 난 용아귀부족에서 마법을 시전하는 자들을 확인해 볼 거야!", progress = "꽤 오랜만에 보는군. 그 고서와 마법봉은 찾아왔소?", completion = "잘했소! 비밀의 고서와 정신 집중의 마법봉 3개를 구해왔군. 마법봉이 약간 긁히긴 했지만 상태는 괜찮군그래.\n\n젊은 &lt;class&gt;가 지옥사냥개를 소환해 지배하려고 온건 정말 오랜만이오. 이거... 아주 재미있겠는걸.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1805] = {title = "비밀의 고서", objective = "톱니항에 있는 스트라드 파선에게 복원된 고서와 정신 집중의 마법봉 3개를 가져가야 합니다.", description = "이 책은 최근 몇 년간 내가 읽은 것들 중에 가장 흥미로운 책 중 하나로군. 이곳 책장에는 고리타분한 지리서밖에 없는데다가 난 벌써 다 읽어 봤다오. 스트라드가 기회가 되는 대로 사본을 한 권 보내 줬으면 좋겠군.\n\n아, 그 친구 얘길 하니 생각나는데 당신이 없는 동안 그에게 전갈을 받았소. 당신의 임무에 정신 집중의 마법봉이 필요하다고 하더군.\n\n이 책을 보게 해줬으니 한 가지 비밀을 알려 주리다. 저습지에 용아귀부족의 오크가 마법봉을 가지고 있으니 그리로 가 보시오.", progress = "내가 도와줄 일이라도 있나?", completion = "잘했소! 비밀의 고서가 약간 긁히긴 했지만 이 정도면 상태는 양호하군. 게다가 정신 집중의 마법봉도 가져왔군그래.\n\n이거 재미있겠는걸. 젊은 &lt;class&gt;가 지옥사냥개를 소환해 지배하려고 하는 건 오랜만이니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1806] = {title = "정의의 시험", objective = "조던 스틸웰이 무기를 다 만들 때까지 기다려야 합니다.", description = "여기 대장간에 가서 작업을 시작하도록 하죠. 얼마 전부터 당신이 오기를 기다리며 준비를 하고 있었으니 오래 걸리진 않을 겁니다.\n\n무기를 얻게 되면 그 어느 때보다 더 굳건히 정의를 수호할 수 있을 겁니다. 그것만은 보장해 드리죠.\n\n솔직히 얘기하자면 당신이 세운 공훈의 결과를 보니 좀 부럽네요. 하지만 나도 내 나름대로 당신의 모험에서 큰 역할을 해낼 수 있다는 것이 무척 기쁩니다.", progress = nil, completion = "여기 있습니다. 당신 같은 정의의 수호자에게 걸맞은 무기죠. 이 무기의 이름은 내 친구였던 한 위대한 &lt;race&gt; &lt;class&gt;의 이름을 따서 지었습니다. 그의 이름은 베리간, 보쉬 베리간이었습니다. 자, 저와 제 아내를 위해 이걸 받아 주세요. 당신께 아주 큰 신세를 졌습니다. 당신처럼 훌륭한 솜씨를 가진 분이 이 땅을 누빈다면 언젠가 이 세상은 보다 평화스러운 곳이 될 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n베리간의 망치"},
[1818] = {title = "딜링거와의 대화", objective = "브릴에 있는 죽음의경비병 딜링거와 대화하십시오.", description = "죽음의경비병 딜링거가 당신 같은 사람에게 줄 일거리가 있다고 하오. 어둠의 여왕님의 위대한 군대에게 당신의 가치를 증명해 보이려거든 즉시 딜링거에게 보고하도록 하시오.\n\n죽음의경비병 딜링거의 초소는 브릴의 서쪽 끝, 공동 묘지 근처에 있소.", progress = nil, completion = "임무 때문에 왔나? 좋아. 아주 중요한 임무가 있네. 이번 임무는 자네의 전투 능력과 포세이큰 수호에 대한 의지를 시험하는 임무가 될 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1819] = {title = "학살자 울라그", objective = "학살자 울라그를 처치한 후 죽음의경비병 딜링거와 대화하십시오.", description = "스컬지가 티리스팔 숲을 휩쓸고 지나갈 때, 우리는 연구 목적으로 한 녀석을 붙잡았었지. 녀석은 자유 의지가 있었고 자신을 학살자 울라그라고 하더군. 자유 의지를 가지긴 했을지 몰라도 여전히 리치 왕의 노예였네.\n\n우린 울라그를 리치 왕의 손아귀에서 빼내려고 노력해봤지만 실패했어. 이제야 울라그를 해방시킬 때가 되었네.\n\n울라그를 해방시키고 처치해버리게.\n\n내 뒤쪽 입구로 들어가 북쪽 묘지로 가서 큰 건물 근처 바닥에 있는 묘지 제동 장치를 사용하게. 그러면 그를 구속하고 있는 마법의 봉인이 풀어질 거야.\n\n그럼... 준비 하라고.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n방어의 길\n\n다음과 같은 것들을 받습니다:\n\n"},
[1820] = {title = "콜만과의 대화", objective = "콜만 파딩과 대화하십시오.", description = "어둠의 여왕님께 자신의 가치를 증명해 보였으니 이제 그분의 신하에게도 스스로 가치를 증명할 수 있겠군그래.\n\n콜만 파딩이 포세이큰의 적들에게 복수하는데 도움을 줄 전사를 기다리고 있네.\n\n브릴 동쪽에 있는 갤로우 선술집에 가면 그를 찾을 수 있을 거야.", progress = nil, completion = "네, 그렇습니다. 당신의 전투 실력이 필요합니다. 가진 것은 별로 없지만 제 임무는 저와 포세이큰의 대의를 이루는 것입니다. 이 임무를 완수하면 보상을 두 배로 해드리도록 하겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1821] = {title = "아가만드 가문의 가보", objective = "콜만 파딩에게 아가만드 가문의 도끼, 아가만드 가문의 검, 아가만드 가문의 철퇴, 그리고 아가만드 가문의 단검을 가져가야 합니다.", description = "저는 평생을 아가만드 가문을 위해 일했지요. 하지만 저는 아가만드 가문 때문에 죽임을 당했습니다. 아가만드 가문이 리치 왕의 어리석은 졸개가 되었다는 사실은 그리 놀랄만한 일도 아닙니다.\n\n이제 그들이 가진 마지막 명예의 증거를 빼앗고 싶습니다. 아가만드가 납골당으로 들어가 무기 선반에서 그들의 가보인 검, 도끼, 단검, 철퇴를 훔쳐다 주세요!\n\n아가만드가 납골당은 아가만드 밀농장의 북쪽 끝에 있는데 잠복한 스컬지와 죽은 아가만드 가족들이 지키고 있습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1822] = {title = "가보 무기", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n계승자의 도끼계승자의 망치계승자의 단검계승자의 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1823] = {title = "루가와의 대화", objective = "루가 레이지토템과 대화하십시오.", description = "명성이 자자한 실력 있는 전사로군. 루가 레이지토템의 시험에 도전할 준비가 됐는가? 그렇다면 불모의 땅에 있는 타우라조 야영지에 가서 루가를 찾게.\n\n자신의 부름에 답할 전사들을 기다리고 있으니.", progress = nil, completion = "내 시험 때문에 왔다고?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1824] = {title = "거인의 들판에서의 시험", objective = "타우라조 야영지에 있는 루가 레이지토템에게 꿈틀거리는 더듬이 5개를 가져가야 합니다.", description = "좋아, 이 시험을 통과하려면 남쪽에 있는 거인의 들판으로 가야 하네. 그곳에는 거대 곤충들이 득실거리고 있다네. 불모의 땅에 새로 온 녀석들인데 하는 짓이 영 마음에 들지가 않는단 말이지.\n\n녀석들의 꿈틀거리는 더듬이를 내게 가져오게. 잘라낸 더듬이는 금세 꿈틀거림을 멈추니 서둘러야 할 거야. 주어진 시간 안에 더듬이를 가져오면 시험을 통과하게 될 걸세.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n루가의 보루방패"},
[1825] = {title = "툰그림과의 대화", objective = "불모의 땅에 있는 툰그림 파이어게이즈와 대화하십시오.", description = "유명한 오크 대장장이인 툰그림 파이어게이즈가 자네가 호드를 위해 열심히 싸워준 얘기를 들었다네. 자네에게 갑옷을 하나 만들어주고 싶으니 즉시 자기를 찾아오라더군.\n\n툰그림은 불모의 땅 크로스로드 동쪽에 위치한 야영지에 있다네.", progress = nil, completion = "옳지, 왔군. 잘 왔어. 당신과 할 얘기가 아주 많아.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1838] = {title = "투사의 방어구", objective = "툰그림 파이어게이즈에게 연기나는 철제 주괴 15개, 아주라이트 가루 10개, 철 주괴 10개, 연소 약병 1개를 가져가야 합니다.", description = "당신의 힘과 용맹에 대해서는 익히 들은 바가 있어 쓸만한 갑옷을 만들어주고 싶소. 당신이 위대한 업적을 하나씩 이룰 때마다 당신을 도와줄 동반자 같은 갑옷 말이지.\n\n하지만 이 갑옷은 만드는 것 자체만으로도 큰 임무요. 당신의 도움은 물론 호드의 다른 대장장이들의 도움도 필요하지.\n\n자, 이 두루마리를 받으시오. 잘 보이지도 않는 눈으로 며칠 밤을 지새면서 갑옷을 만드는 데 필요한 재료들을 적어놓았소. 이 두루마리에 적힌 물건들을 가져오면 첫 번째 갑옷을 만들어주도록 하지.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1839] = {title = "울라엘레크와 투사 건틀릿", objective = "듀로타에 있는 울라엘레크와 대화하십시오.", description = "트롤 대장장이 울라엘레크가 당신에게 투사 건틀릿을 만들어 줄 것이오. 그 친구는 듀로타에 있는 센진 마을에서 검은창부족 형제들과 살고 있는데 당신이 오기를 기다리고 있소이다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1840] = {title = "오름 스톤후프와 투사 투구", objective = "썬더 블러프에서 오름 스톤후프와 대화하십시오.", description = "오름 스톤후프는 그가 가진 기술 때문에 많은 존경을 받고 있지. 그를 찾아가면 당신에게 투사 투구를 만들어줄 것이오.\n\n썬더 블러프에 가서 도시의 거대한 중앙 토템 옆에 있는 연못 근처에서 그를 찾도록 하시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1841] = {title = "벨로라 나이틀리와 투사 다리보호구", objective = "언더시티에 있는 벨로라 나이틀리와 대화하십시오.", description = "들리는 바에 의하면 죽기 전 벨로라 나이틀리는 로데론에서 으뜸가는 갑옷 제작자였다는군. 죽음마저도 그녀의 재능을 퇴색시키지는 못한 것 같네. 벨로라를 만나 대화를 해 보도록 하시오. 당신에게 투사 다리보호구를 만들어 줄 것이오.\n\n벨로라는 로데론의 언더시티에 있는 상업 지구에서 부지런히 장사를 하고 있소이다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1842] = {title = "사티로스 발굽", objective = "듀로타의 센진 마을에 있는 울라엘레크에게 사티로스 통발굽 7개를 가져가야 합니다.", description = "내 자네에게 강력한 마법이 깃든 투사 건틀릿을 한 쌍 만들어주지. 그 전에 먼저 이 마법을 모아서 내게 가져와야 하네.\n\n자네 혹시 알고 있나? 사티로스들이 잿빛 골짜기 북동부에서 사는 건 그 숲의 힘 때문이라네. 녀석들은 숲의 순수한 힘을 거머리처럼 빨아들이면서 숲을 오염시키고 있네. 어느 사티로스가 잿빛 골짜기의 마법을 가장 많이 빨아먹었는지는 다부진 통발굽을 보면 알 수 있지.\n\n그 발굽에는 강한 힘이 깃들어 있는데 자네에게 줄 건틀릿을 만들려면 그 발굽이 필요하네.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1843] = {title = "투사 건틀릿", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n투사 건틀릿"},
[1844] = {title = "키메라의 뿔", objective = "썬더 블러프에 있는 오름 스톤후프에게 번개 뿔을 가져가야 합니다.", description = "투구를 만들어주기 전에 그대가 쓸 자격이 있다는 것을 보여주어야만 하오이다.\n\n돌발톱 산맥의 북서부 지역에 잿더미 계곡이 자리 잡고 있소. 한때는 푸르렀던 곳이지만 이제는 오염되어 잿빛으로 변해버렸고 남은 생물들도 고통과 절망에 미쳐버렸지.\n\n바로 그곳으로 그대를 보내려고 하오.\n\n잿더미 계곡으로 가서 우두머리 키메라를 찾으시오. 우두머리 키메라를 처치해 고통에서 해방시키고, 키메라의 번개 뿔을 가져오면 투구를 만들어주도록 하겠소이다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1845] = {title = "투사 투구", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n투사 투구"},
[1846] = {title = "용아귀부족 다리뼈", objective = "언더시티에 있는 벨로라 나이틀리에게 단단한 용아귀부족 다리뼈 8개를 가져가야 합니다.", description = "투사 다리보호구를 만들려면 단단한 다리뼈로 만든 버팀대가 필요해요. 저습지의 용아귀부족 오크들은 다리뼈가 무척 두텁고 단단하지요. 바로 그 다리뼈가 필요해요.\n\n반드시 단단한 것이라야 되니 다리뼈를 모으면서 확인을 해 보도록 하시기 바랍니다. 맨손으로 우지끈 부러뜨릴 수 있는 것이면 방어구를 만들기에 적합하지 못한 것이랍니다. 호호!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1847] = {title = "투사 다리보호구", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n투사 다리보호구"},
[1848] = {title = "투사 갑옷", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n투사 갑옷"},
[1858] = {title = "검은손 도적단", objective = "타잔의 열쇠를 훔쳐 가방을 열고 그 속에 든 물건들을 오그리마의 어둠의 틈에 있는 테르조크에게 가져가야 합니다.", description = "자네가 타잔의 가방을 열어 그 안에 든 물건들을 나에게 꺼내줘야겠네. 자물쇠를 보아하니 아주 견고하고 복잡해서, 열쇠를 찾는 것이 그나마 가장 쉬운 방법이 아닐까 싶군.\n\n타잔에게 없었다면 다른 사람이 갖고 있겠지... 아, 그래! 타잔에게 가몬이라는 조수가 하나 있었지. 항상 술을 달고 사는 자이니 술집에 가면 찾을 수 있을 거야. 운 좋게도 술에 취해 있다면 열쇠를 몰래 빼내 오기 쉬울 걸세.", progress = "원하는 것이 바로 눈 앞에 있는데도 손에 넣을 방법이 없다니 참으로 답답한 노릇이 아닌가?", completion = "흠, 재미있군. 이것으로 자네의 가치는 충분히 확인했네. 아주 잘했어. 이제 검은손 &lt;class&gt;단의 일원이 되었다고 생각하고 이것을 받도록 하게. 앞으로 자네에게 큰 도움이 될 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n기민함의 단검"},
[1859] = {title = "테르조크", objective = "오그리마의 어둠의 틈에 있는 테르조크와 대화하십시오.", description = "쉿, 목소리를 낮추라고! 당신 이름이야 물론 잘 알고 있지. 사실은 당신과 닮은 오크를 찾아오라는 지시를 받았거든.\n\n소문을 듣자 하니 싸움 실력도 좋고 가끔씩 비밀스러운 일도 맡는다던데, 맞나?\n\n어쨌거나 오그리마에 있는 테르조크를 찾아가 보라고. 당신에게 제안할 게 있다고 하니까 말이야.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1860] = {title = "제니아와의 대화", objective = "스톰윈드에 있는 제니아 캐논과 대화하십시오.", description = "우리 마법사들이 꼭 해야 할 임무가 있소. 스톰윈드와 엘윈 숲의 안전을 위해 아주 중요한 임무지.\n\n자세한 내용은 제니아 캐논이 알고 있소. 스톰윈드의 마법사 지구에 있는 마법사의 성소에서 공부를 하고 있으니 서둘러 찾아가 보시오.", progress = nil, completion = "내 임무를 도우러 온 건가요? 잘 왔어요. 우리와 뜻을 함께 하고자 하는 젊은 &lt;class&gt;들을 보니 기운이 나는군요...\n\n우리의 뜻이 뭔지 궁금한가요? 머지 않아 알게 될 거예요, 젊은 친구. 머지 않아... 알게 될 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1861] = {title = "거울 호수", objective = "스톰윈드에 있는 제니아 캐논에게 거울 호수 견본을 가져가야 합니다.", description = "이 세계는 거대하고 신비로운 힘들간의 전쟁에 피해를 받았습니다. 이 전쟁으로 인해 한때는 안정적이던 마법의 흐름에 커다란 문제가 생겼답니다. 우리는 이러한 변화가 가져온 결과를 알아내기 위해 노력하고 있는데 일부 마법사들은 최악의 결과가 아닐까 우려하고 있습니다!\n\n지금은 정보를 모아야 하니 자세한 얘기는 나중에 하도록 하겠습니다.\n\n자, 이 물통을 받으세요. 스톰윈드 성문의 남서쪽에 거울 호수 폭포 밑으로 가서 물을 담아 오세요. 그 물을 내게 가져오면 나쁜 마법에 오염되지 않았는지 실험해 보도록 하겠습니다.", progress = "견본을 가져왔나요? 스톰윈드와 엘윈에서 마법의 흐름이 변했어요. 그 변화가 물속에 스며들고 있는지 알아야만 합니다.", completion = "고맙습니다. 이 물에 마법적인 특성이 있는지 실험해 봐야겠습니다. 바라건대 이 물에 마법적인 성질이 없었으면 좋겠군요. 그렇지 않으면 거울 호수의 물을 오랫동안 마셔온 사람들이 나쁜 질병에 걸릴 수 있으니 말입니다.\n\n자, 받으세요. 임무를 충실히 수행했으니 이 수정구나 지팡이를 선물하도록 하죠. 유용하게 쓰이길 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n초원의 보주초원의 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1878] = {title = "물주머니 현상금", objective = "부지런한 <name> 양반, 또 오셨군. 사막유랑단 물주머니 5개를 더 가져왔다면 선물세트를 주겠소! 이름도 큼직하게 새겨서 말이오.", description = nil, progress = "부지런한 <name> 양반, 또 오셨군. 사막유랑단 물주머니 5개를 더 가져왔다면 선물세트를 주겠소! 이름도 큼직하게 새겨서 말이오.", completion = "잘했소. 물주머니를 더 많이 찾을수록 우리는 끔찍한 갈증 걱정을 안 해도 되지! 계속 더 가져오면 고맙겠소. 물주머니를 5개마다 반드시 보상이 따를 테니까.", rewards = "다음과 같은 것들을 받습니다:\n\n가젯잔 수자원개발회사 선물세트"},
[1879] = {title = "빙크와의 대화", objective = "아이언포지에 있는 빙크와 대화하십시오.", description = "이보시오! 아이언포지에 있는 빙크라는 노움 친구가 소식을 전해왔소. 해야 할 임무가 있다는데 마법사가 아니면 맡기질 않겠다고 하오! 당신은 마법사지 않소?\n\n그렇다면 빙크와 대화해 보시오. 그녀는 아이언포지의 마법 지구에 있는 신비의 전당에서 주로 시간을 보내니 그 쪽으로 가면 만날 수 있을 것이오.", progress = nil, completion = "아, 당신이라면 가능성이 있겠군요. 그래요, 가능해요! 하지만 훌륭한 &lt;class&gt;는 가능성만으로 되는 게 아니죠. 그런데 훌륭한 &lt;class&gt;가 아니라면 형편없는 &lt;class&gt;지요. 형편없는 &lt;class&gt;들이 문제에요. 정말 문제죠!\n\n이런. 쓸데 없는 얘기를 했군요. 그럼 처음부터 시작하죠!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1880] = {title = "마법사의 기억장치", objective = "빙크에게 마법사의 기억장치를 가져가야 합니다.", description = "우리 마법사들은 손가락 하나 까딱거린다고 화려한 마법을 쓸 수 있는 게 아니에요! 이 세계를 이루는 기본 요소인 마법을 제어하는 것이죠! 그러려면 아주 신중해야 하고 굳건한 의지와 방대한 지식이 필요하지요!\n\n내 장치 중 마법사의 기억장치는 이처럼 방대한 양의 지식을 수집하고 보관할 수 있답니다! 그런데 그 장치를 잃어버렸지 뭐에요! 고향인 놈리건에서 도망 나오다 도시 외곽에 있는 숙소의 연장통 속에 숨겨 놨어요. 하지만 지금 그곳엔 오염된 노움들이 득실거리고 있어서 찾기가 어렵답니다!\n\n부탁이에요. 내 기억장치를 찾아주세요!", progress = "기억장치를 찾았나요? 힘이 다 떨어지기 전에 반드시 찾아야 해요!", completion = "해냈군요! 기억장치를 만들었을 때는 이렇게까지 이것에 의존하게 될지 몰랐죠. 이제 연구를 새로 시작할 수 있겠군요!\n\n고마워요! 그리고 여기, 내가 &lt;class&gt;로서 처음 사용하던 도구들이랍니다. 조금 긁히긴 했지만 다 쓸만 해요. 둘 중에 어떤 것이든 유용할 테니 하나 골라보세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n신비의 보주비전 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1881] = {title = "아나스타샤와의 대화", objective = "아나스타샤 하트웰과 대화하십시오.", description = "아나스타샤 하트웰이 당신 같은 재능을 지닌 마법사에게 맡길 임무가 있다고 합니다. 언더시티의 마법 지구에서 그녀와 얘기를 나누고 포세이큰의 마법사들을 위한 첫 임무를 준비하도록 하시기 바랍니다.", progress = nil, completion = "총명한 &lt;class&gt;분이여, 반갑습니다. 내 부름에 응하다니 현명한 결정이로군요. 하지만 지금부터 내가 하는 말을 잘 들어야 할 것입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1882] = {title = "발니르 농장", objective = "언더시티의 마법 지구에 있는 아나스타샤 하트웰에게 발니르 금어초를 가져가야 합니다.", description = "동쪽에 있는 역병지대는 오염 정도가 심각해요. 리치 왕이 만들어낸 마법이 땅속에 퍼지면서 살아있는 것들을 모조리 오염시키고 죽이고 있어요. 역병의 파괴력을 막아주는 주문이 있긴 하지만 우리 포세이큰의 마법사들도 그 주문을 통제하기가 어려워 주문의 힘을 줄여야 한다고 생각하고 있지요.\n\n하지만 먼저 역병이 티리스팔에 얼마나 깊숙이 침투했는지 알아야 해요. 티리스팔 동쪽에 있는 발니르 농장에 가면 정원에 금어초가 있을 거예요. 그것들을 모아서 가져오세요.", progress = "금어초를 가져왔나요? 그 화종은 마법력을 워낙 잘 흡수하기 때문에 역병지대 가까이 있는 금어초를 조사하면 티리스팔 숲에 역병이 침투했는지 알 수 있어요.", completion = "아, 좋은 표본을 가져왔군요. 이것들을 연금술사에게 보내 역병지대에 역병이 어디까지 뻗쳤는지 조사해보도록 해야겠습니다.\n\n수고했어요. 답례로 이 수정구와 지팡이 중 하나를 드리도록 하죠. 어느 것을 고르든 아주 유용할 겁니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n신비의 보주비전 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1883] = {title = "운투와와의 대화", objective = "운투와와 대화하십시오.", description = "센진 마을의 부족 마법사인 운투와가 듀로타의 마법 흐름을 방해하는 요소가 있다면서 도움을 요청하고 있습니다. 운투와와 대화를 하고 어떻게 해서든 그를 도와주도록 하십시오.\n\n그렇게 하면 머잖아 더 많은 비밀을 알게 될 것입니다.", progress = nil, completion = "반갑소. 내 요청을 듣고 온 것이로군. 와줘서 고맙소. 이번 임무를 맡아주면 좋겠는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1884] = {title = "주주 해골", objective = "주주 해골 4개를 파괴하고 센진 마을에 있는 운투와에게 돌아가야 합니다.", description = "메아리 섬에 사는 흑마법사 잘라제인이 듀로타의 정상적인 마법 흐름을 흐트려뜨려 놓았네. 그는 주주 해골이라는 오염된 우상으로 이런 일을 벌이고 있는데 메아리 섬의 오두막에 그 우상을 두었다네.\n\n그 우상은 야생의 동물과 식물들을 타락시키고 어둡고 외진 곳에 사는 흑마법사와 지옥의 생물들에게 힘을 부여하고 있지.\n\n그 주주 해골을 파괴해야 하네. 마법의 흐름이 영원히 바뀌어버리기 전에...", progress = nil, completion = "잘라제인의 주주 해골이 파괴된게 느껴져... 시간이 흐르고 운이 좋으면 언젠가 듀로타의 마법의 흐름도 정상으로 되돌아오겠지.\n\n자네는 동족에게 아주 훌륭한 일을 한 걸세, &lt;name&gt;. 호드의 상급 &lt;class&gt;인 우리에게도 자네의 가치를 입증한 것이고 말이야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n초원의 보주초원의 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1885] = {title = "메넷 칼카드", objective = "언더시티의 도적 지구에 있는 메넷 칼카드와 대화해야 합니다.", description = "음? 칼카드님께서 당신에게 관심을 가지고 계시기에 어떤 자일까 궁금했는데 생각했던 거랑 좀 다르군요. 하기야 겉모습이 그 사람의 본 모습은 아니니까요, 그렇죠?\n\n어쨌거나 가능한 빨리 그분을 찾아가보세요. 마지막까지 그분의 소환을 거역한 자들이 어떻게 됐는지 알고 싶지 않다면 말이에요.", progress = nil, completion = "흠. 물론 내가 소환했다는 소식을 듣자마자 왔겠지? 그래, 그래. 죽음의추적자라면 그 정도는 돼야지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1886] = {title = "죽음의추적자", objective = "도적 지구에 있는 메네세 칼카드에게 아스토르의 소개장을 가져가야 합니다.", description = "바리마트라스님의 최정예 근위대인 죽음의추적자에 지원할 생각이라면 먼저 자네의 능력을 증명해야 할 거야.\n\n흠, 솔직히 말하지. 이 임무는 자네의 목숨을 앗아갈 수도 있네.\n\n내가 손을 써야 할 일이 좀 있는데, 은빛소나무 숲과 언더시티를 오가며 소식을 전하는 아스토르 하드렌이라는 전령의 소지품이 필요하네. 소지품을 가져오는 방법은 자네의 판단에 맡기지.\n\n이 일에 대해서는 자세히 알지 않는 편이 좋을 걸세. 성공하고 돌아오면 자세한 얘기를 들려주겠네.", progress = "해냈는가?", completion = "잘했네. 자네는 시험의 첫 관문을 통과한 걸세. 안드론이 자네가 한 일에 대해 아무런 낌새도 눈치채지 못했으면 좋겠군. 그러면 자네가 바로 그가 기다리고 있는 전령이라고 설득할 수 있을 테니 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1898] = {title = "죽음의추적자", objective = "언더시티에 있는 안드론 건트와 대화해야 합니다.", description = "소개장만 가지고 있다면 자네가 바로 안드론이 기다리던 그 전령이라고 설득할 수 있을 거야. 전에 안드론을 만나본 적이 있는데 그런 의심을 할 만큼 똑똑한 위인은 아니더군.\n\n바리마트라스님께서는 안드론이 다른 단체를 도와주고 있다고 의심하고 계시네. 그래서 그 단체에 대해 알아보고 안드론이 그 단체를 돕고 있다는 증거를 찾아오라 지시하셨지.\n\n가서 안드론을 만나 증거를 찾아 오게. 연금술 실험실 근처에 있는 상점에 가면 그를 찾을 수 있을 거야.", progress = "안녕하시오. 뭐 도와드릴 일이라도?", completion = "아, 왔군. 그렇지않아도 기다리고 있었소. 우리야 서로 알고 있는 사람들이니 지금까지 내가 제공한 정보에 흡족 해하리라 생각하는데, 어떻소?\n\n이런, 쓸데없는 질문을 했군. 그 친구들이 이 정보로 당신에게 부담을 주지나 않을까 싶소. 왜 그렇게까지 그 사신을 믿는 거요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1899] = {title = "죽음의추적자", objective = "언더시티에 있는 메넷 칼카드에게 안드론의 장부를 가져가야 합니다.", description = "당신 고용주가 찾는 정보가 담긴 장부가 내 뒤로 보이는 책장에 있소. 갖다 드리면서 내 안부도 좀 전해 주시오. 그리고 정보가 맘에 들어 앞으로도 계속 거래를 하겠다면 당신을 보내줬으면 한다고 전해주시오.", progress = "성공했나?", completion = "음. 안드론에게서 기대했던 것보다 많은 정보를 가져왔군. 잠시 살펴보고 나서 다음 임무를 주겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1918] = {title = "타락한 정령", objective = "잿빛 골짜기 토막나무 주둔지에 있는 마스토크 윌리히스에게 더럽혀진 물구슬을 가져가야 합니다.", description = "쓰러진 정령에게서 강렬한 빛을 발하는 물구슬이 나왔습니다. 구슬 안에 든 내용물은 정말이지 역겹습니다. 미스트랄 호수를 오염시킨 성분이 무엇이든 이 구슬에 든 물에도 들어있을 것이 분명합니다.\n\n이런 물건에 관심을 가질 만한 게 정확히 누구인지는 알려지지 않았지만 애초에 이곳으로 오도록 지시했던 토막나무 주둔지의 마스토크 윌리히스라면 알지도 모릅니다.", progress = "그래, 무슨 일로 왔나?", completion = "썩은 물이 든 구슬을 찾았는데 내게 가져오고 싶더란 말인가? 내가 뭐 속세의 고리회 일원이라도 되는 줄 알아?\n\n가만, 그러고 보니... 이건 속세의 고리회에 가져다주는 게 좋겠어. 호수에서 벌어지고 있는 사태를 완전히 수습해 버리는 데 도움이 된다면 난 대찬성이지.\n\n&lt;name&gt;, 설마 속세의 고리회의 일원이 누군지 모르고 있는 건 아니겠지?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1919] = {title = "제니아에게 보고", objective = "스톰윈드에 있는 제니아 캐논과 대화하십시오.", description = "마법에 대한 지식이 점점 늘어가고 있군, 젊은 마법사여. 이제 진짜 훈련을 시작할 준비가 되었소? 우리가 치르고 있는 비밀 전쟁에 동참할 준비가 되었는가 말이오?\n\n그렇다면 스톰윈드 마법사 지구의 마법사의 성소에 있는 제니아 캐논과 대화하도록 하시오. 그녀가 보이지 않는 세계의 첫 창문을 열어 줄 임무를 알려줄 것이오.", progress = nil, completion = "당신에게 줄 임무가 있어요. 바로 여기 &lt;class&gt; 지구에서요. 시간이 없으니 잘 듣도록 하세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1920] = {title = "고독한 은둔자 선술집 조사", objective = "제니아 캐논의 뒤에 있는 현신의 주문서와 속박의 상자를 집으십시오. 마법사의 성소에 있는 제이나에게 채워진 속박의 상자 3개를 가져가야 합니다.", description = "마법사 지구에 있는 고독한 은둔자 선술집에서 소란이 있었다는 보고가 들어왔습니다. 눈에 보이지 않는 괴이한 생물들이 선술집을 어슬렁거린다는데 그곳에 마력의 균열이 생긴 게 아닌지 걱정입니다.\n\n가서 선술집을 조사해보고 그 생물들을 잡아오도록 하세요. 선술집에서 현신의 주문서를 사용해 생물들이 보이게 해서 제압한 다음 속박의 상자를 사용해 붙잡으세요. 충분히 잡았으면 정령이 든 속박의 상자와 빈 상자, 그리고 주문서를 가지고 제게 돌아오도록 하세요.", progress = "그 정령들은 잡았나요? 정령들을 조사해서 왜 이곳에 나타났는지 알아봐야 해요.", completion = "정말 잘 했어요! 이 정령들을 연구해봐야겠어요. 연구하다 운이 좋으면 이 세계에 어떻게 들어왔는지 알 수 있겠죠.\n\n&lt;class&gt; 사회에서 당신의 가치가 점점 빛을 발하는군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1921] = {title = "재료 수집", objective = "스톰윈드에 있는 위니 라슨에게 리넨 10개와 충만한 균열석 6개를 가져가야 합니다.", description = "동료 마법사들을 위해 좋은 일을 해주었으니 이제 마법사의 로브를 입을 때가 되었군요. 위니 라슨이 로브를 만들 수 있지만 그러려면 필요한 재료를 찾아서 그녀에게 가져다 줘야 해요.\n\n로브를 만들려면 리넨이 있어야 하는데 리넨은 찾기가 쉬워요. 문제는 충만한 균열석이에요. 지금까지 이 보석이 있다고 알려진 곳은 모단 호수의 은여울 광산뿐이에요. 드워프 광부 조합에서 상자 안에 보관해 두었죠.\n\n리넨과 보석을 모아 마법사 지구의 라슨의 의상실에 있는 위니 라슨에게 가져 가세요.", progress = "안녕하세요. 제니아가 당신이 올 거라고 그러더군요. 제게 줄 게 있나요?", completion = "아주 좋은 리넨이군요. 멋진 로브를 만들 수 있겠어요. 거기에다 이 충만한 균열석까지 달면 아주 멋진 &lt;class&gt; 로브가 되겠는걸요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1938] = {title = "우르의 흑마법 논문", objective = "스톰윈드에 있는 고위마술사 안드로매스에게 우르의 흑마법 논문을 가져가야 합니다.", description = "오래전 세 명의 마법사가 이 탑에서 공부를 했었는데 그 중 하나가 어둠의 마법에 빠져 타락해 버렸다네. 주위에서는 그 사악한 마법에서 손을 떼라고 설득했지만 그는 사악한 힘을 뿌리칠 수가 없었지. 그리고 그는 추방을 당했다네.\n\n타락한 마법사는 붉은마루 산맥에 있는 일갈라의 탑을 새로운 영역으로 삼았는데, 우르의 흑마법 논문이라는 강력한 마법서를 가져가 버렸어.\n\n우리 스톰윈드의 마법사들은 그 책을 되찾길 원하네. 일갈라의 탑으로 들어가서 그의 서재에서 책을 찾아 내게 가져오게.", progress = "책을 가져왔는가? 그 책의 비밀이 마법의 힘에 미숙한 자들에게 노출되어선 안 되네. 그 책에 빠지면 파멸할 수도 있으니까 말이야.", completion = "모건스가 책을 다른 곳에다 숨겨버렸거나 책을 열어 내용을 읽은 것이 아닌가 걱정하고 있었다네.\n\n우리가 우르의 흑마법 논문에 붙인 봉인이 그대로인 것도 그렇고 책을 읽지 않았다니 다행스럽군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1939] = {title = "고위마술사 안드로매스", objective = "고위마술사 안드로매스와 대화하십시오.", description = "고위마술사 안드로매스님께서 당신과 얘기를 나누고 싶어하세요. 그분은 스톰윈드 마법사 지구에 있는 마법사의 성소 최상층에 계시답니다.\n\n그분과 얘기를 나누는 게 좋을 거예요. 안드로매스님께서는 달라란에 붙잡혀있지 않는 마법사 중 가장 강한 분이시거든요. 그분과의 대화는 말 그대로 고위 회담이랍니다.", progress = nil, completion = "어서 오게. 만나서 반갑군. 이 늙은이의 얘기를 들어줄 시간이 있다면 좋겠는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1940] = {title = "온전한 거미줄", objective = "스톰윈드에 있는 위니 라슨에게 온전한 거미줄 8개를 가져가야 합니다.", description = "자네는 항상 기대에 어긋나지 않게 임무를 완수하는군. 이제는 숙련된 마법사인 자네의 지위에 어울리는 로브를 하나 더 입어야 할 때가 아닌가 싶군. 필요한 재료를 모아오면 로브를 하나 만들어 주기로 하지.\n\n그늘숲으로 가서 청소부그늘거미를 사냥해 그 거미줄을 뽑아와야 하는데 가장 가늘고 온전한 거미줄이라야만 하네. 거미줄을 충분히 모으거든 이곳 마법사 지구의 라슨의 의상실에 있는 위니 라슨에게 가져가면 로브를 만들어줄 걸세.", progress = "아, 오셨군요. <class>의 성소의 <class>들께서 당신이 올 거라고 하더군요. 거미줄은 가져오셨나요?", completion = "상태가 아주 좋군요. 당장 일을 시작해야겠어요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1941] = {title = "마나매듭 로브", objective = "자, 로브 여기 있어요. 지금까지 만든 것 중 최고랍니다! 자부심을 갖고 입으시고 어디서 만든 거냐고 묻거든... 라슨의 의상실에서 만든 거라고 말해주세요!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n마나매듭 로브"},
[1942] = {title = "별매듭 로브", objective = "자, 옷이 다 됐어요! 당신이 모아온 비단이 얼마나 좋은지 몰라요. 저, 당신 옷을 좀 짧게 만들고 남은 비단으로 제 옷을 만들어도 될까요?\n\n호호, 농담이에요. 이 로브는 모험을 할 때나 격식을 갖춘 만찬에 참석할 때나 모두 잘 어울리고 잘 맞을 겁니다. 잘 입으세요!", description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n별매듭 로브별매듭 블라우스\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1943] = {title = "다이노와의 대화", objective = "다이노와 대화하십시오.", description = "트롤 마법사 다이노가 당신의 도움이 필요합니다. 그녀는 오그리마의 검은장미 오두막에 있으니 찾아가 보도록 하세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1944] = {title = "사비안의 폭포수", objective = "오그리마에 있는 다이노에게 사비안 폭포수 견본을 가져가야 합니다.", description = "전설적인 사비안 도시는 잿빛 골짜기 동부 깊은 곳에 자리 잡고 있습니다. 학식이 있는 자들 사이에서는 사비안의 고대 지식에 대한 이야기가 잘 알려져 있죠. 전해지는 바에 의하면 사비안의 물에는 거대한 마법의 힘이 있다고 합니다.\n\n그 물의 근원지를 찾아 견본을 가져와야 합니다. 이 병을 가지고 사비안으로 가세요. 폭포의 가장 높은 곳에서 가장 낮은 곳까지 물을 담아 내게 가지고 오도록 하세요. 그 고대 도시를 돌아다닐 때는 조심해야 합니다. 현재 폐허가 된 그곳을 점령한 사티로스는 자신들의 일에 간섭하는 마법사를 싫어하니 말입니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1945] = {title = "미소띤 자매", objective = "크로스로드에 있는 킬할라에게 미소띤 자매의 머리카락 12개를 가져가야 합니다.", description = "당신의 공로에 대한 보답으로 필요한 재료를 모아오면 새로운 로브를 만들 수 있도록 준비 해두었습니다.\n\n이 로브를 만들려면 잿빛 골짜기로 돌아가 미소띤 자매의 머리카락을 구해와야 해요. 그들은 드리아드로, 라이네나무 은신처 근처에 모여있습니다.\n\n머리카락을 구해 불모의 땅 크로스로드에 있는 트롤 재봉사 킬할라에게 가져다주면 당신의 로브를 만들어줄 겁니다. 킬할라가 당신을 기다리고 있을 거예요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1946] = {title = "황천의 로브", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n황천의 로브황천의 튜닉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1947] = {title = "습지대로의 여행", objective = "타베사와 대화하십시오.", description = "이제 마법사의 지팡이를 받을 때가 된 것 같군요. 이 임무를 시작하기 전에 먼저 먼지진흙 습지대에 사는 인간 은둔자 타베사와 얘기를 나누어보도록 하세요. 테라모어 서쪽, 습지대 깊숙한 곳에 있는 오두막집에 있을 겁니다.\n\n그녀는 지식이 아주 풍부한 사람이니 얘기를 나누면 도움이 될 거예요. 돌망치일족 폐허의 바로 북쪽, 테라모어 서쪽에 타베사의 작은 집을 찾을 수 있을 겁니다.", progress = nil, completion = "조용히 하세요! 지금 아주 중요한 시점이라 얘기를 나눌 수 없어요!\n\n잠시만 기다리세요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1948] = {title = "강력한 물건", objective = "먼지진흙 습지대에 있는 타베사에게 비취 1개와 벼락 맞은 나뭇가지를 가져가야 합니다.", description = "마법사의 지팡이를 만드는 건 쉬운 일이 아니죠. 다량의 희귀한 재료가 필요하고 많은 양의 마법력을 담을 수 있는 용기도 만들어야 한답니다. 이런 것들을 모아서 내게 가져오도록 하세요.\n\n이 양피지에 필요한 물건의 이름과 구하는 방법을 적어놓았어요. 이 목록에 적은 물건들을 그대로 가져오고 지시사항도 반드시 따르도록 하세요. 그렇지 않으면 지팡이를 만들 때 일이... 잘못될 수도 있으니...", progress = "다시 보는군요. 필요한 물건들은 가져왔나요?", completion = "오호! 비취도 구하고 나뭇가지도 만들어 왔군요! 수고했어요!\n\n지금 당신 귀에서 연기가 피어 오르는 건가요? 토템 막대에 벼락이 떨어질 때 너무 가까이에 있었던 것 같군요. 하지만 걱정할 거 없답니다. 벼락을 맞는 건 행운이니까요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1949] = {title = "숨겨진 비밀", objective = "소금 평원에 있는 학자 틸스와 대화하십시오.", description = "당신에게 줄 지팡이를 만들려면 어떤 책에서 중요한 구절을 읽어야 합니다. 학자 틸스가 쓴 마력의 의식이라는 책이지요.\n\n이 세계의 거대한 도서관에도 없으며 내게도 이 책의 사본이 없답니다. 그래서 학자 틸스에게 직접 얘기를 하고 받아와야 해요.\n\n행운을 빌겠어요. 틸스는 한때 훌륭한 마법사이자 학자였는데 지금은 소금 평원에 있는 노움과 고블린 경주장에서 술과 노름에 빠져 지내고 있답니다.", progress = nil, completion = "뭐라고? 더 크게 말해보게! 늙어서 귀가 예전 같지 않단 말이야.\n\n흠... 어디 신선한 맥주와 다음 경기에 대한 화끈한 정보를 가져 온 건가? 만약 그런 게 아니라면 방해 말고 얼른 사라지는 게 좋을 거야. 꾸물거리고 있다간 내 변신 지팡이가 자넬 가만두지 않을 거라고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1950] = {title = "주문 알아오기", objective = "틸스의 금고를 여는 주문을 알아서 틸스에게 돌아가야 합니다.", description = "책 찾는 거야 도와줄 수 있지만 먼저 날 도와줘야 하겠어!\n\n자네가 찾는 그 책은 마법으로 잠긴 금고에 들어있지. 그 금고를 열려면 특별한 주문을 외워야 하는데 도무지 기억이 나질 않는단 말이야! 보통은 내 조수가 주문이 기억나게 와주곤 하는데 어디 있는지 찾을 수가 없군.\n\n내 책을 원하거든 내 조수를 찾아보라고! 운 좋으면 경주장 근처 친구들 중에 아는 사람이 있을지도 모르니 수소문해 보도록 하게. 녀석을 찾으면 여기로 끌고 오던가 아니면 내 금고를 여는 주문을 알아오게!", progress = nil, completion = "아, 이제야 기억나는군...\n\n존슨에게 걸었던 그 작은 저주를 잊고 있었어. 왜 저주를 걸었는지 기억은 나지 않지만 분명 그럴 만한 일을 저질렀을 거야, 배은망덕한 녀석!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1951] = {title = "마력의 의식", objective = "먼지진흙 습지대에 있는 타베사에게 마력의 의식을 가져가야 합니다.", description = "흠... 지금 생각해보니 책이 없군! 그렇지... 전에 노름으로 진 빚이 있어 그걸 갚느라 마지막 마력의 의식 사본을 성직자 친구에게 팔아버렸지...\n\n그 친구 붉은십자군의 일원이었는데 분명히 티리스팔 숲에 있는 붉은십자군 수도원의 도서관으로 가지고 갔을 게야!\n\n그 책을 원한다면 그 수도원으로 가서 찾아야 할 거라고. 수고를 끼쳐 미안하군그래. 요즘 제정신이 아니라서...", progress = "오, 돌아왔군요? 책은 찾았나요?", completion = "바로 그거예요! 당신의 지팡이를 만드는 의식을 준비하는데 꼭 필요한 물건이죠! 이걸 찾느라 고생이 심했던 건 아닌지 모르겠군요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1952] = {title = "마법사의 마법봉", objective = "의식이 끝나면 타베사와 대화하십시오.", description = "당장 마법봉을 만들어야겠군요.", progress = nil, completion = "자, 방금 만든 마법봉들이니 원하는 걸 골라보도록 하세요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n맹위의 얼음마법봉황천의 마법봉맹위의 화염마법봉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1953] = {title = "다시 습지대로", objective = "타베사와 대화하십시오.", description = "이제 먼지진흙 습지대의 은둔자 타베사와 얘기를 나눌 때가 되었군요. 타베사가 강력한 마법사의 도구를 만드는 법을 가르쳐줄 겁니다.\n\n타베사의 오두막집은 테라모어 서쪽, 먼지진흙 습지대 깊은 곳에 있습니다.", progress = nil, completion = "어서 오세요. 수정구나 지팡이 때문에 온 게로군요? 좋아요. 내가 만드는 걸 돕도록 하죠.\n\n미리 경고해두는데 만드는 절차가 워낙 위험해서 당신이 죽을 수도 있다는걸 알아두도록 하세요.\n\n아니면 내가 죽을 수도 있겠지만, 분명 누군가는 죽게 됩니다...\n\n다만 그 사람이 다른 사람이기를 기도하도록 하죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1954] = {title = "지옥의 보주", objective = "먼지진흙 습지대에 있는 타베사에게 지옥의 보주를 가져가야 합니다.", description = "수정구를 만들기 위한 첫 단계는 힘이 깃든 수정구를 얻는 것입니다. 불타는칼날단의 흑마법사들이 고급 수정구를 지니고 있답니다. 그런데... 수정구 속에 악마를 묶어두고 있으니 문제가 아닐 수 없습니다! 하지만 우리가 상황을 바로잡을 거예요. 그럼요, 물론이죠.\n\n잊혀진 땅으로 가서 불타는칼날단 소환사에게서 지옥의 보주 하나를 빼앗아오세요. 소환사들은 만노로크 소굴에 있을 겁니다.\n\n보주를 손에 넣으면 내게 돌아오도록 하세요.", progress = "지옥의 보주를 가져왔나요?", completion = "오, 무척 좋은 보주로군요! 아니, 아니에요. 더운 날의 시원한 음료수처럼 '좋다'는 말은 아니지요.\n\n지금 생각해 보니 전혀 좋다라는 느낌이 안드는군요. 이런, 음료수 말고 보주 말이에요!\n\n집중하도록 하세요! 이 임무를 끝내려면 집중을 해야 합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1955] = {title = "악마 퇴치", objective = "보주의 악마를 물리치고 타베사와 대화하십시오.", description = "소환사의 보주를 손에 넣었으니 이제 보주 안에 있는 악마를 쫓아내야 합니다. 악마를 쫓아내는 건 쉬운 일이니 이것은 내가 하도록 하죠.\n\n당신이 어려운 부분을 맡아줘야 하겠습니다. 악마가 풀려나오면 당신이 물리쳐야 합니다. 시간을 너무 오래 끌게 되면 악마가 다시 보주로 들어가게 되고 처음부터 다시 시작해야 하니까 재빨리 물리쳐야 합니다!\n\n자, 악마와 맞설 준비를 하도록 하세요. 가장 강한 마법을 준비하고 물약도 꺼내 놓도록 하세요. 엄청난 소동이 벌어질 테니 도와줄 친구가 있으면 데려오도록 하세요.", progress = nil, completion = "잘해냈군요! 녀석이 단단히 혼이 났으니 금세 나타나지는 않을 겁니다.\n\n자기를 내쫓은 당신을 찾기 위해 그 못생긴 얼굴을 이 세계에 다시 들이밀 때도 한번 더 생각해보겠죠. 흠, 다시 올 때는 동료를 데리고 올지도 모르겠는데... 당신을 없앨 생각으로만 가득한 덩치 크고 비늘 많은 친구들 말이에요.\n\n내가 겁을 준건 아니죠... &lt;class&gt; 친구?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1956] = {title = "울다만의 마력원천", objective = "흑요석 마력원천을 구해서 먼지진흙 습지대에 있는 타베사에게 가져가야 합니다.", description = "이제 악마를 제거했으니 마력원천을 찾아야 하겠군요. 유감스럽게도 마력의 원천의 힘이 클수록 대개 오래되고 얻기가 힘들답니다. 운명의 장난이란 게 때론 참 웃기지, 그렇지 않나요?\n\n울다만으로 가서 흑요석 파수꾼을 물리치도록 하세요. 녀석은 덩치도 크고 힘도 장사인데다가 녀석의 마력원천에는 엄청난 마력이 들어있습니다!\n\n행운을 빌겠어요. 운이 없다면, 뭐... 다시 볼 수 없겠네요. 만나서 반가웠어요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[1957] = {title = "마력의 폭풍", objective = "주어진 시간 안에 마력의 폭풍 12마리를 물리쳐야 합니다.", description = "이제 거의 다 끝났는데 이 마지막 단계가 제일 위험합니다.\n\n비어있는 소환사의 수정구도 있고 힘을 부여할 준비도 되었어요. 이것엔 마력의 균열 에너지를 이용해 힘을 부여할 겁니다. 내가 주문을 걸어 일시적으로 균열을 열면 그곳에서 마력의 폭풍이라는 피조물들이 쏟아져 나올 겁니다. 당신이 마력의 폭풍을 물리치고 그들의 힘이 풀려나오면 내가 그 힘을 모으도록 하지요.\n\n균열이 닫히기 전에 마력의 폭풍을 물리쳐서 그 녀석들의 힘을 모두 수정구에 불어넣으면 됩니다.", progress = nil, completion = "해냈군요! 틀림없이 해낼 거라고 믿었어요! 솔직히 조금 의심은 했지만... 그렇게 많이 의심하지는 않았어요.\n\n호호, 정말이랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1958] = {title = "천공의 힘", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n천공의 보주천상의 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[1959] = {title = "아나스타샤에게 보고", objective = "아나스타샤 하트웰과 대화해야 합니다.", description = "언더시티의 마법사들이 도시 내에 마법 장애가 발생했다면서 이를 조사해 줄 호드의 마법사를 찾고 있다고 전갈을 보내왔습니다.\n\n자세한 내용은 언더시티의 마법사 지구에 있는 아나스타샤 하트웰이 얘기해 줄 겁니다. 그녀를 찾아가 보시기 바랍니다.", progress = nil, completion = "네, 사실입니다. 우리 도시에서 마법 장애가 감지되었어요. 이러한 장애가 어디서부터 발생했는지, 혹은 좋은 것인지 나쁜 것인지 아직은 확실하지 않습니다. 따라서 먼저 정보를 더 모아야 해요.\n\n바로 그것이 당신이 해줄 일이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1960] = {title = "연금술 상점 조사", objective = "아나스타샤 하트웰의 뒤에 있는 현신의 주문서와 속박의 상자를 집어야 합니다. 언더시티에 있는 아나스타샤 하트웰에게 채워진 속박의 상자 3개와, 속박의 상자, 현신의 주문서를 가져가야 합니다.", description = "연금술 실험실 입구에 있는 알게르논이 근무하는 연금술 상점 근처에서 알 수 없는 기운이 감지되고 있습니다. 무슨 이유에서인지 모르겠지만 마법으로 구성된 보이지 않는 생물들이 상점을 돌아다니고 있어요.\n\n이들이 활보하는데는 분명 이유가 있을 테니 그 이유를 알아내야 합니다! 가서 이 소란을 조사하고 그 생물들을 잡아오도록 하세요. 내 뒤에 있는 속박의 상자와 주문서를 가져가세요. 연금술 상점에서 현신의 주문서를 사용하면 마법 생물들이 보이게 될 겁니다. 생물들을 제압한 다음 상자를 사용해 붙잡도록 하세요. 그 다음 채워진 속박의 상자와 빈 상자, 주문서를 가지고 돌아오세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1961] = {title = "재료 수집", objective = "조셉 그레고리안에게 리넨 10개와 달라란 마나석 6개를 가져가야 합니다.", description = "자, 이제 첫 번째 마법사의 로브를 입을 때가 되었군요. 마법사의 로브는 지위의 상징이자 당신의 가치를 입증하는 것이랍니다.\n\n이 로브를 얻으려면 은빛소나무 숲의 달라란 마법사들에게서 마나석을 모아와야 합니다. 우리와 비슷한 믿음을 추구하고 있는 자들이라 죽이는 것이 썩 내키지는 않지만, 우리에게 대항할 힘마저 없다면 살 가치가 없죠.\n\n마나석과 리넨을 구해 마법 지구의 의류점에 있는 재봉사인 조셉 그레고리안에게 가져다주세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1962] = {title = "마법불꽃 로브", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n하급 마법불꽃 로브"},
[1963] = {title = "검은손 도적단", objective = "타잔을 죽이고 그의 가방을 오그리마의 어둠의 틈에 있는 테르조크에게 가져가야 합니다.", description = "대족장님께선 너무 생각이 많으셔서 탈이야. 호드의 세력을 확장하는 문제도 굉장히 조심스러워하시지. 한 때 우리 호드는 모두 강력한 정복자들이었는데 말이야. 과거의 영광을 반드시 되찾아야만 해. 검은손 도적단은 반드시 그렇게 하고 말거야.\n\n우리 도적들은 음지에서 힘을 길러 양지의 적을 은밀하게 쓰러뜨리지. 이번 임무를 수행하여 도적으로서 자네의 가치를 증명해야 하네.\n\n타잔이라는 트롤이 톱니항의 해적들과 거래를 하고 있는데 나한테 꼭 필요한 정보를 가지고 있어. 녀석을 해치우고 그의 가방을 가져오게.", progress = "대낮에 도끼로 공격하는 자들이 몰래 숨어서 단검으로 찌르는 자보다 더 위험하다는 것은 어리석은 생각이지.", completion = "타잔 녀석이 없어졌다는 건 기쁜데 말이야. 가방이 이렇게 잠겨 있으면 아무짝에도 쓸모가 없잖아. 우리는 바로 이 속에 든 정보가 필요하단 말일세.\n\n흠... 이것을 검은손 &lt;class&gt;단에 지원한 자네를 시험할 두 번째 임무로 맡기면 되겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1978] = {title = "죽음의추적자", objective = "언더시티의 실바나스의 전당에 있는 바리마트라스에게 안드론의 장부를 가져가야 합니다.", description = "비밀결사대라고? 생각도 못했던 일이군. 그들의 배반이 있은 후 몇 년 사이 알터랙의 지배자들이 세력을 크게 잃은 모양이야.\n\n바리마트라스님께서 이걸 아시면 아주 흡족해 하실 걸세. 자네의 공으로 이 사실을 알아냈으니 직접 가서 바리마트라스님께 전해드리는 것이 좋겠군.\n\n아, 내 정신 좀 보게. 죽음의추적자에 합류하게 된 걸 축하하네.", progress = "뭔가?", completion = "흠. 재미있군. 죽음의추적자들이 아주 일을 잘했군.\n\n듣자하니 그대도 칭찬받을 만한 일을 했다고? 앞으로도 포세이큰을 위해 분연히 노력할 기회가 자주 있을 게야. 내 죽음의추적자들은 항상 그대와 같이 뛰어난 인재를 필요로 하거든.", rewards = "다음과 같은 것들을 받습니다:\n\n기민함의 단검"},
[1998] = {title = "펜윅 타트로스", objective = "펜윅 타트로스를 처치하고 그 증거로 그의 머리카락을 언더시티의 도적 지구에 있는 메넷 칼카드에게 가져가야 합니다.", description = "바리마트라스님께서 방금 포세이큰을 위협하는 자가 있으니 당장 그자를 제거하라고 내게 서한을 보내셨네. 이름은 펜윅 타트로스라고 하는데 바리마트라스님께서는 은빛소나무 숲에 근거지를 두고 있는 언데드의 우두머리로 생각하고 계시네.\n\n이 소식을 들으니 자네 이름이 떠오르더군. 자네 실력이라면 이 임무를 훌륭하게 완수하리라 믿네.\n\n은빛소나무 숲에 있는 죽음의추적자들이 최근에 보고해온 바로는 타트로스가 로다미어의 낡은 부두 근처에 있는 것 같다더군.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[1999] = {title = "거래의 도구", objective = "달라란 상황 보고서를 찾아 언더시티의 도적 지구에 있는 메넷 칼카드에게 가져가야 합니다.", description = "앰버밀에 있는 키린 토의 마법사들은 달라란의 현재 상황에 관련된 중요 문서들을 보관하고 있네. 우리 죄수 중 하나가 실토해서 알게 됐지. 바리마트라스님께서 그 문서를 찾아 죽음의추적자들에게 건네주라고 지시하셨네.\n\n이 임무를 자네에게 맡기겠네. 하지만 자물쇠 따는 기술과 약간의 장비가 필요할 거야. 장비를 담당하는 에스텔 젠드리와 얘기를 해 보고 떠나기 전에 도구를 받도록 하게.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2038] = {title = "사라진 빙글스의 물건들", objective = "빙글스의 물건들을 찾아서 돌아와야 합니다.\n\n빙글스의 스패너, 빙글스의 드라이버, 빙글스의 망치, 빙글스의 깡그리싸그리 폭탄을 찾아야 합니다.", description = "나를 모단 호수에 추락시킨 것으로는 성이 안 찼는지 근처 섬에 살던 트로그들이 나를 덮쳤소. 도구들과 특제 깡그리싸그리 폭탄을 훔쳐가 버렸지 뭐요. 자이로콥터와 폭탄이 없으니 우리 노움에게 가망은 없소!\n\n자이로콥터를 수리할 수 있도록 내 도구들과 깡그리싸그리 폭탄을 찾아주시오. 놈리건을 위해서 말이오.", progress = "내 물건들은 어디 있소?!", completion = "큰 일을 해주었군, &lt;class&gt; 친구! 놈리건을 침략한 트로그와 오염된 노움들에게 이몸이 곧 공중 폭격을 선사할 거요!", rewards = "다음과 같은 것들을 받습니다:\n\n빙글스의 비행용 장갑"},
[2039] = {title = "빙글스 찾기", objective = "모단 호수에서 빙글스 블라스텐하이머를 찾아야 합니다.", description = "빙글스에게서 연락이 끊겼소! 놈리건 정찰 임무를 띠고 수색을 나갔는데 일주일이 넘도록 아무런 보고가 없소이다. 어딘가에서 봉변을 당한 게 분명하오.\n\n그가 모단 호수 위를 날아가는 모습이 마지막으로 목격됐다 하는군. 당신이 빙글스를 찾아봐 주면 좋겠소.", progress = nil, completion = "노아른이 내 정찰 실력을 미덥지 않게 여기나 보군? 이유가 뭘까...\n\n그건 그렇고 당신의 도움이 필요하오! 아니! 우리 지하 조직에서 당신의 도움을 필요로 하고 있소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2040] = {title = "지하 공격", objective = "죽음의 폐광에서 노암 톱니구동장치를 찾아 스톰윈드에 있는 쇼니에게 가져가야 합니다.", description = "놈리건이 저 비열한 트로그 녀석들의 손아귀에 들어가다니! 위험한 상황이긴 하지만 어쩌면 당신이 우리를 도와주실 수 있을지도 모르겠군요.\n\n죽음의 폐광 깊은 곳에 아직 쓸 수 있는 고블린 벌목기가 있어요. 그 벌목기를 찾아 구동장치를 그대로 가져다주세요. 벌목기 구동장치의 전력을 우리의 회전천공식 발굴기에 사용해서 놈리건의 바위투성이 지하 경계를 부수고 공격 진입로를 뚫어야겠어요!", progress = "노암 톱니구동장치를 찾았나요?", completion = "수고하셨어요. 감사합니다. 이제 놈리건 해방의 길에 한 발짝 더 다가선 거예요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n북극의 건틀릿칠흑의 마법봉\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2041] = {title = "쇼니와의 대화", objective = "스톰윈드에 있는 쇼니와 대화하십시오.", description = "어쩌면... 어쩌면 말이오. 당신이 놈리건을 되찾기 위한 전투에서 우리를 도울 수 있을 거요.\n\n스톰윈드에 가면 지하 공격조 지휘관인 쇼니가 있소. 쇼니가 회전천공식 발굴기를 사용하도록 도와주시오.\n\n아마 스톰윈드의 드워프들과 함께 있을 거요. 행운을 빌겠소.", progress = nil, completion = "본부에서 전갈을 가져왔나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2078] = {title = "자이로마스트의 복수", objective = "겔카크의 일등항해사인 망나니탈곡기 4100을 찾아서 겔카크에게 데리고 오거나 처치해야 합니다.", description = "애송이 친구, 내 일등항해사를 찾아주면 고맙겠네.\n\n일등항해사가 다시 일을 시작해 멀록 녀석들이랑 그 두목을 붙잡으면 녀석들도 계속해서 그렇게 즐겁게 물장구를 치진 못할 걸!\n\n이 열쇠를 가져 가서 선장을 다시 모시라고 전해주게나. 하지만 말을 듣지 않는다면 그때는 자네의 판단에 모든 걸 맡기겠네.", progress = "내 일등항해사는 어디 있나? 당장 내놓지 않으면 족쇄를 달아서 상어한테 던져 버릴 걸세!", completion = "이야, 이 애송이 친구가 진짜 뱃사람보다 판단력이 빠르군.\n\n이런 식으로만 하면 이 겔카크 선장님께서 자네의 승진을 한번 고려해 보도록 하겠네! 갑판 화장실 청소 담당으로 말이야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n수중 호흡의 비약"},
[2098] = {title = "자이로마스트의 수색", objective = "겔카크의 열쇠 조각 3개를 찾아 겔카크 자이로마스트에게 가져가야 합니다.", description = "해적의 삶이란 쉬운 게 아냐, 애송이 친구. 약탈한 돈으로 술을 마시며 흥청대는 게 전부가 아니란 말이지! 아아... 내 배가 트레샤돈 녀석들 때문에 해안 바로 앞에서 침몰됐네. 빨리 다시 일을 시작해야 하는데!\n\n내가 해안으로 밀려왔을 때 일등항해사의 열쇠가 바위에 떨어져 부서졌지. 어둠의 해안에 사는 짐승들이 그걸 훔쳐간 게 분명하다네. 사나운 모래톱게, 거대한 숲타조, 그리고 멀록들이 난파된 우리 배를 휘젓고 다니는 걸 슬쩍 봤거든.", progress = "내 부서진 열쇠는 찾았나, 애송이 친구?", completion = "이럴 수가! 찾아왔군! 곧 다시 일을 시작할 테고 그러면 그 짐승 놈들도 쓸어버려야지. 아마 뭐에 당했는지도 모를 걸세!\n\n그런데 혹시 일등항해사는 보지 못 했나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2118] = {title = "역병에 걸린 땅", objective = "광포한 엉겅퀴곰을 생포해 타나리운에게 데리고 와야 합니다.\n\n광포한 엉겅퀴곰을 생포하는 데 실패하고 덫을 잃으면, 타나리운 트리텐더에게 돌아가 다른 덫을 받아야만 합니다.", description = "어둠의 해안 전역에 역병이 퍼지면서 모든 이들의 몸과 마음을 앗아가고 있소.\n\n엉겅퀴곰들이 이 역병으로 가장 큰 타격을 받았다오. 한때는 고귀하던 짐승이 지금은 미친 듯이 날뛰는 파괴의 앞잡이가 되어 버렸소. 내 이 역병을 치료할 수 있을 것도 같소.\n\n이 덫을 숲으로 가지고 가서 땅에 놓으시오. 광포한 엉겅퀴곰이 덫에서 발하는 빛에 닿으면 잠시 동안이나마 온순하게 변할 거요. 곰이 온순해지면 잘 달래어 여기로 데려와 주시오.", progress = nil, completion = "이제부터가 진짜 시작이오. 다음 임무를 수행할 준비는 되었소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2138] = {title = "병든 엉겅퀴곰 처치", objective = "숲에서 광포한 엉겅퀴곰 20마리를 처치한 후 어둠의 해안에 있는 타나리운 트리텐더에게 돌아가야 합니다.", description = "우려했던 대로 치료를 해도 소용이 없군.\n\n자연에서 살아가는 짐승들의 목숨을 빼앗는다는 게 너무 마음 아픈 일이지만 병들고 타락한 엉겅퀴곰은 반드시 처치해야 하오.\n\n숲으로 돌아가 광포한 엉겅퀴곰 스무 마리를 처치하시오. 그래도 역병을 막기에는 역부족이겠지만 그 짐승들이 숲과 동식물을 파괴하는 것은 잠시나마 늦출 수 있을 거요.", progress = nil, completion = "아우버다인을 위해 큰 일을 해주었소. 하지만 아직 임무가 완전히 끝난 것은 아니오.\n\n푹 쉰 다음 나를 다시 찾아오시오. 그 때는 더 많은 피를 보게 될 테니 마음의 준비도 해 두는 게 좋겠지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2139] = {title = "타나리운의 희망", objective = "우두머리 엉겅퀴곰을 찾아서 처치해야 합니다.", description = "우리 종족은 이 땅에서 생존을 위해 너무나 큰 희생을 치르고 있소.\n\n자연의 수하들, 수많은 병든 동물들이 그대의 손에 피를 흘리며 죽어갔소. 그래도 아우버다인의 주민들은 그대에게 은혜를 입은 셈이지. 비록 잠시 동안이긴 했지만 숲의 고통을 덜어주었으니 말이오.\n\n그대의 마지막 임무가 하나 남았소만 또 살생을 해야 한다는 것을 미리 말해 두겠소. 이런 일로 그대를 부르는 것이 마지막이었으면 하는 바람이오.\n\n바샬아란 근처의 북동쪽 동굴에 우두머리 엉겅퀴곰이 살고 있소. 그 곰을 처치해주시오.", progress = "역병에 걸린 우두머리 엉겅퀴곰을 처치하면 우리 땅에 들어오는 광포한 엉겅퀴곰의 수도 줄어들 거요. 지체하지 마시오.", completion = "그대는 아우버다인을 위해 용기와 정의로 싸워주었소. 전쟁으로 상처 입은 이 땅에 죽음과 절망이 퍼져 있다오. 많은 이들이 새로운 고향에서 역경을 헤쳐나가려고는 하지 않고 집안에 숨어 지내거나 안전한 얼라이언스 땅으로 탈출하려 할 것이오.\n\n고맙소. 어쩌면 머지 않아 다른 적을 상대로 그대와 우리가 힘을 합해 싸우게 될 날이 있을지 모르겠군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n상록수 장갑초원의 단망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2158] = {title = "평안과 휴식", objective = "사자무리 여관에 있는 여관주인 팔레이와 대화해야 합니다.", description = "어떤 모험가든 힘이 떨어지면 휴식을 취해야지요. 편안히 쉴 곳이라면 사자무리 여관만한 곳이 없습니다!\n\n내 절친한 친구 팔레이가 사자무리 여관을 운영하고 있습니다. 내가 당신을 보냈다고 말하면 특별히 가격을 깎아 줄지도 모릅니다.\n\n사자무리 여관으로 가려면 여기서 길을 따라 남쪽으로 가면 바로 보일 겁니다.", progress = nil, completion = "춥고 지친 여행자분들께 평안과 휴식을. 이것이 우리 여관의 좌우명이죠! 자, 피곤하실 테니 불 옆에 앉아서 몸을 좀 추스르세요.\n\n우리 여관 음식 한번 드셔보시겠어요?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n작은 호박맑은 샘물\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2159] = {title = "돌라나르로의 배달", objective = "여관주인 켈다미르에게 돌라나르 배달물을 가져가야 합니다.", description = "안녕하시오, 젊은 <class> 양반. 좀 도와주지 않겠소? 돌라나르 마을에 약초 보따리를 배달해야 하는데 그늘 협곡에서 드루이드와 볼일이 남아 아직 떠날 수가 없소이다.\n\n나 대신 이 배달물을 좀 전해주지 않겠소? 돌라나르 여관의 주인 켈다미르에게 가져다 줘야 하오. 남쪽으로 가는 길에 돌라나르 여관이 보일 거요.", progress = "뭘 도와 드릴까요? 여관에서 쉬려고 왔나요? 아니면 귀환석이라도 필요하신가요?", completion = "참, 그렇지. 그늘 협곡에서 약초가 오기로 했었는데... 안 그래도 포르타니우스와 의논할 게 많은데 직접 안 온 게 아쉽군. 어쨌든 약초를 받아서 다행이요. 당신을 만나게 된 것도 기쁜 일이고...\n\n여기 있는 동안 푹 쉬시오. 영웅은 항상 강인한 체력을 유지해야 하니 쉴 수 있을 때 충분히 휴식을 취하면서 피로를 풀어야지. 몸과 마음의 평안을 소홀히 하는 것은 실패의 지름길이니까...\n\n푹 쉬시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n다르나서스 브루 치즈맑은 샘물\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2160] = {title = "탄노크에게 보급품 전달", objective = "카라노스에 있는 탄노크 프로스트해머에게 여관 보급품 상자를 전해 주어야 합니다.", description = "안녕하세요! 무척 마음씨 좋은 모험가분이신 거 같군요. 혹시 위험을 무릅쓰고 여행을 하실 계획이시라면 카라노스에 있는 여관으로 이 소포를 좀 전해주지 않겠어요?\n\n도착하면 그 여관에서 좀 머무는 것도 좋을 거예요. 먼 길이라 피곤하실 테니까요.\n\n어쨌든, 이걸 여관 종업원 탄노크 프로스트해머에게 가져다주세요. 저는 이곳에서 멀리 갈 수 없는 몸인데다 며칠 후 도착할 산악경비대 호위병을 기다려야 해서 곤란하거든요.", progress = "어서 오십시오, 손님! 불가에 앉아 따끈한 차나 한 잔 드시면서 몸을 녹이시기 바랍니다.", completion = "드디어 핸즈에게서 보급품이 왔군요! 트로그들이 길을 점령한 이후 앤빌마에서 소식이 뜸해 마침 걱정하던 참이었답니다.\n\n소포를 갖다주셔서 대단히 고맙습니다. 자, 먼 길 오시느라 피곤하실 테니 편히 쉬시기 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n질긴 쇠고기맑은 샘물\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2161] = {title = "일꾼의 짐", objective = "칼바위 언덕에 있는 여관주인 그로스크에게 우코르의 짐을 가져가야 합니다.", description = "저기요, 저 좀 도와주시겠어요?\n\n여기 식량 보따리가 하나 있어요. 전 이걸 들고 전갈, 거미, 그보다 더 끔찍한 것들과 싸우면서 걸었어요! 시험의 골짜기에 음식이 필요할 것 같아 돕고 싶은 마음에 가져갔죠. 그런데 음식은 필요하지도 않더라고요! 이제 칼바위 언덕으로 다시 가져가야 하는데 또 짐승들을 만날까봐 무서워서...\n\n저 대신 이 짐을 가져다주실 수 있나요? 저는 일개 짐꾼에 불과하지만 당신은 용감한 영웅이잖아요. 아무것도 두려워하지 않는 영웅!\n\n칼바위 언덕의 여관주인 그로스크에게 가져다주세요. 고맙습니다!", progress = "안녕하세요. 칼바위 언덕에 오신 걸 환영합니다.", completion = "아니, 이건 우코르가 시험의 골짜기에 가져갔던 음식인데, 필요 없다던가요? 훈련을 받는 자들을 굶겨 죽일 생각인가 보군. 아마 배가 고프면 정신력이 높아진다는 말도 안 될 소릴 해대겠지!\n\n아무튼 음식을 가져와 주셔서 감사합니다. 다시 선반에 올려둬야겠군요. 수고하셨으니... 식사라도 좀 내오도록 하죠.\n\n그리고 여기 여관에서 꼭 쉬다 가세요. 아무리 세상 전체를 상대할 만한 용감한 &lt;class&gt;|1이라도;라도; 기력이 없으면 제대로 실력을 발휘하기가 힘들 테니까요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n질긴 빵맑은 샘물\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2178] = {title = "간단한 타조 요리", objective = "아우버다인에 있는 알란다리안 나이트송에게 타조 고기 5개를 가져가야 합니다.", description = "맛있는 냄새 안 나세요? 저만의 특제 요리 신선한 타조 스튜라는 건데 맛이 아주 일품이랍니다!\n\n혹시 조리법을 배워볼 생각이 있으신가요? 그렇다면 요리에 쓸 짐승들을 다루는 방법을 아는지 증명해야 한답니다.\n\n그렇다고 밖에 나가 한 마리를 길들여 타고 오라는 건 아니랍니다. 그냥 몇 마리 잡아서 촉촉한 고깃덩어리를 조금만 가져다주시면 됩니다. 그러면 타조 스튜의 조리법을 가르쳐 드릴게요.", progress = "배도 고프고 저장고도 텅 비었는데 왜 이리 오래 걸리시나요?", completion = "기막힌 맛이로군! 자, &lt;name&gt;. 한번 드셔보시고 어떤지 말해주세요!", rewards = "다음과 같은 것들을 받습니다:\n\n조리법: 타조 스튜타조 스튜"},
[2198] = {title = "부서진 목걸이", objective = "부서진 목걸이의 잠재적 가치를 알아내기 위해 원 제작자를 찾아야 합니다.", description = "빛바랜 목걸이를 찾았습니다. 비록 겉은 더럽혀져 있지만 정교하고 신비한 기술로 만들어진 것 같습니다. 목걸이는 부서졌는데 모양을 보아하니 보석 세 개가 사라진 듯합니다. 목걸이의 아래 부분에는 아이언포지의 도시 인장이 희미하게 찍혀 있습니다. 인장 밑에는 \"탈바쉬\"라는 작은 글씨가 새겨져 있습니다.\n\n이 목걸이에 대해 알려면 목걸이의 근원에 대해서 알아야 합니다. 인장과 작은 글씨가 그 출발점이 될 것 같습니다.", progress = "잘못 찾아온 거라니까, 친구! 난 절대 거기 간 적이 없소! 내가 거기 갔다는 증거를 대 보시오!\n\n잠깐만... 당신 누구지? 아니... 이 목걸이는 어디서 찾은 거요?", completion = "그렇소... 내가 이 목걸이를 만든 보석세공사요. 또한 난 정보를 공짜로 마구 알려주는 일도 하지 않지. 공짜 정보란 없는 법이지, 친구. 그러니 내 도움이 필요하다면 먼저 나를 도와야 하오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2199] = {title = "정보의 대가", objective = "아이언포지에 있는 탈바쉬 델 키젤에게 은괴 5개를 가져가야 합니다.", description = "나는 이곳 아이언포지에서 꽤 유명한 보석세공사요! 그러니까, 전에 꽤 유명했지... 지금은 경쟁자의 거짓말 때문에 어렵게 지내고 있다오! 이 바닥에서 평판이 나빠지면 곧장 돈줄이 끊기게 되지. 그러다 보니 한때는 유명했지만 지금은 더럽혀진 명성에 무일푼으로 지내고 있소, 흑흑.\n\n우선 수주한 주문 하나를 마무리할 수 있게 은괴 다섯 개를 가져다주시오. 이게 얼마 만에 받아보는 주문인지 모르겠다니까.\n\n당신이 이 은괴 다섯 개를 가져다주면 목걸이에 대한 질문에 답해주겠소.", progress = "내가 부탁한 은괴 다섯 개는 가지고 왔소? 당신이 가지고 있는 목걸이에 얽힌 서글픈 이야기를 해주고 싶지만... 그건 은괴를 받고 나서요! 제발 이 불쌍한 노움을 좀 도와주라고.", completion = "당신 상당히 괜찮은 자인 것 같군. 다른 사람이 당신을 뭐라 그러던지 말이오... 하하, 농담이오, 농담! 정말로 고맙소, 친구.\n\n자, 당신이 가지고 있는 목걸이는 내가 만든 걸작 중 하나라오. 하지만 지금은 마법의 힘을 결속시키는 보석 세 개가 없어졌소. 그 목걸이는 오래전 성기사에게 주기 위해 만들었던 것인데 그 친구는 독단으로 임무를 정해 그걸 수행하고 있었소. 바로 황야의 땅에 있는 울다만이라는 발굴 현장에서 \"사악한 기운\"을 제거하는 것이었지.\n\n그런데 그만... 울다만에서 죽어버렸소. 그것이 내 고난의 시작이었지.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2200] = {title = "울다만으로 돌아가기", objective = "울다만 안에서 탈바쉬의 목걸이의 행방에 대한 단서를 찾아야 합니다. 탈바쉬가 말했던 성기사가 그 단서를 가진 최후의 인물일 것입니다.\n\n제공된 아이템: \n", description = "내 경쟁자 녀석이 내 목걸이가 그 성기사에게 저주를 내린 거라며 소문을 퍼뜨리기 시작했소! 저주받은 물건을 사려고 하는 자가 없으리라는 것은 말할 것도 없지.\n\n내 제안하나 하지. 만약 당신이 잃어버린 보석들을 찾아오면 목걸이를 다시 복원해주는 대신 나 탈바쉬 델 키젤이 절대로 저주받은 물건을 만들지 않는다고 선전해 주시오!\n\n울다만에서 단서를 찾아보도록 하시오. 만약 그곳에서 성기사의 유해를 보게 된다면 아마도 그가 목걸이의 행방을 아는 최후의 인물이었을 것이오! 보석을 찾게 되면 이걸 쓰시오. 그러면 이곳 아이언포지에 있는 나와 연락을 할 수 있을 거요.", progress = nil, completion = "일지를 읽어보니 성기사가 엄청난 고생 끝에 세 보석의 위치를 모두 알아낸 것 같습니다.\n\n먼저 루비는 어둠괴철로단 드워프들이 울다만을 점령하기 위해 트로그들과 싸우면서 쳐 놓은 방어진에 숨겨두었습니다.\n\n트로그들이 울다만에서 얼라이언스 드워프들이 있는 곳 근처의 항아리에 숨겨두었습니다.\n\n마지막으로 사파이어는 트로그 우두머리에게 있습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2201] = {title = "보석 찾기", objective = "울다만에 흩어져 있는 루비, 사파이어, 토파즈를 찾아야 합니다. 모두 찾으면 탈바쉬가 준 수정점 유리병을 사용하여 그에게 연락해야 합니다.\n\n일지에 의하면... \n*루비는 어둠괴철로단 드워프들이 있는 지역에 숨겨져 있습니다.\n*토파즈는 얼라이언스 드워프들이 있는 곳 근처에 트로그 지역에 있는 항아리 중 하나에 숨겨져 있습니다.\n\n*사파이어는 트로그 대장인 그림로크가 가지고 있습니다.", description = "성기사의 일지에 적힌 목걸이의 보석 위치가 울다만에서 찾을 수 있는 유일한 단서인 듯합니다. 이 성기사가 적어놓은 정보가 정확하다면 발굴 현장을 차지하기 위해 싸우고 있는 어둠괴철로단 드워프들과 트로그들을 처치해야 합니다.\n\n이 정보를 얻었으니 이제 본격적인 보석 찾기가 시작된 것입니다. 보석을 모두 손에 넣으면 탈바쉬의 지시대로 수정점 유리병을 사용하여 아이언포지에 있는 그에게 알려야 합니다.", progress = "수정점 그릇에 담긴 물에서 탈바쉬의 모습이 차츰차츰 뚜렷하게 나타납니다.\n\n\"오. 아직 살아 있군! 보석들은 찾았소? 내 명성을 되살려 주리라 바라던 구세주가 정녕 당신이란 말이오? 제발 그냥 얘기나 하려고 유리병의 마법을 낭비하는 건 아니라고 말해주시오. 그건 절대로 싼 물건이 아닌데다가 나는 이미 금전적으로 몹시 곤란한 상황이란 말이지.\"", completion = "맞소. 바로 이게 그 보석들이오. 수고했소! 하지만 아직 일이 완전히 끝난 게 아니오.\n\n아니, 속이려던 했던 것은 아니오, 성급하기는... 이번 일은 탈바쉬 델 키젤의 고급 마법 보석을 만드는 것과 관련된 거요! 보석에 마력을 불어 넣기 위해서는 강력한 마력원천이 필요하지. 그런데 그 목걸이에는 마력이 남아있질 않소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2202] = {title = "울다만에서 재료 찾기", objective = "카르가스에 있는 자칼 모스멜드에게 자홍버섯 12개를 가져가야 합니다.", description = "얼마 전에 자홍버섯이라는 새로이 발견된 식물에 대한 얘기를 들었다네. 자홍버섯은 울다만 발굴 현장의 깊숙한 곳에서 군생하지. 다른 곳에서도 군생할 수도 있지만 내가 알고 있는 곳은 거기뿐이라네. 난 그 버섯이 연금술에 사용할 잠재적인 가치가 있는지 연구하고 싶기에 자네의 도움이 필요하다네.\n\n자홍버섯을 찾아서 12개만 나에게 가져다주시게. 버섯송이에 가까이 가면 포자에서 독이 발산되니 조심하도록 하게나.\n\n나를 위해 이 일을 맡아주게. 그리고 내 자네를 격려하는 의미에서 유명한 복원의 비약 한 꾸러미도 줄 것일세!", progress = "내 연금술 작업에 쓸 자홍버섯은 가져왔나? 버섯이 없으면 보상도 없네!", completion = "수고했네. 다시 한번 자네의 가치를 증명했군! 이 버섯 연구는 틀림없이 아주 흥미로울 걸세.\n\n자, 이제 약속했던 대로 내가 만든 효과가 좋은 복원의 비약을 한 번 맛보게나...\n\n자네가 실력 있는 연금술사라면 앞으로 또 거래를 하게 되겠지. 어쨌든 도와줘서 고마웠네!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n복원의 물약"},
[2203] = {title = "황야의 땅에서 재료 찾기", objective = "빈 요술 유리병을 황야의 땅에 있는 화염의 수호비룡에게 사용해야 합니다. 세 개를 다 채우면 카르가스에 있는 자칼 모스멜드에게 가져가야 합니다.", description = "자네는 지금까지 내게 아주 큰 도움이 되었네. 내 자네에게 보상으로 전에 자네에게 준 적 있는 비약의 조제법을 알려 주도록 함세. 단, 꽤 위험한 임무 한 가지만 완수해 주면 말이야... 내 얘기를 들어 보게.\n\n이 금고에는 빈 요술 유리병 세 개가 들어 있다네. 화염의 수호비룡의 피를 빨아들일 조화의 오라가 담겨 있는데, 그걸 그 비룡에 사용하면 비룡이 크게 노하게 될 테니 조심하게. 그 유리병 세 개를 다 채우거든 내게 가져오게나.\n\n이 임무를 완수해 주면 조제법은 자네 것이 되는 걸세.", progress = "요술 유리병으로 내가 필요로 하는 화염의 수호비룡 피를 모아 왔나? 그래, 위험한 임무라는 것은 나도 아네... 하지만 내 치유 물약 조제법이 자네가 성공하길 기다리고 있다네. 고생 끝에 낙이 온다네, 친구... 고생 끝에 낙이...", completion = "같은 연금술사로서 자네에게 경의를 표하네. 자, 이 조제법을 받아 잘 기억해 두게. 그 조제법이 오랜 세월 동안 내게 성공과 보상을 가져다주었듯이 자네에게도 그러길 바라네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n복원의 물약\n\n다음과 같은 것들을 받습니다:\n\n"},
[2204] = {title = "목걸이 복원", objective = "울다만에서 가장 강력한 피조물을 찾아 부서진 목걸이의 마력원천을 손에 넣은 다음, 아이언포지에 있는 탈바쉬 델 키젤에게 목걸이와 함께 가져가야 합니다.", description = "이제 목걸이에 필요한 \"마력\"을 찾아야 하오. 아마도 그 일에는 울다만이 최고의 장소일 거요. 그곳에 피조물들이 꽤 많이 돌아다닐 텐데, 그렇지 않소? 그 중에서 제일 덩치 크고 악독해 보이는 놈을 잡아서 놈의 마력원천을 빼앗으시오! 내가 그 마력원천을 목걸이에 불어넣을 수 있을 거요.\n\n그 마력원천이 없이 목걸이를 고친다는 것은 불가능하오. 그러니 마력원천을 찾으면 여기 아이언포지로 다시 돌아오시오. 당신을 위해 모두 고쳐주겠소!", progress = "울다만을 떠난 후로 옷을 갈아입을 시간도 없었던 모양이군. 아직까지 던전 냄새가 나는 걸 보니 곧장 달려왔군그래. 어쨌든 이번 방문이 정말 무엇인가 냄새가 나는 방문이기를 바라오. 아무 의미 없는 방문이 아니라 말이야.\n\n목걸이에 쓸 마력원천은 가지고 있소?", completion = "마력원천을 잘 가지고 와서 다행이군. 이제 목걸이와 보석을 다시 결합하였으니 잠시만 있으면 마법으로 목걸이에 마력원천을 불어넣을 수 있을 것이오. 다 끝나면 목걸이는 당신에게 주겠소!\n\n흥분되지 않소? 가슴도 떨리고 말이오. 어디 보자. 그 주문의 초점을 어디다 뒀더라...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2205] = {title = "SI: 7 찾기", objective = "스톰윈드 병영에 있는 단장 마티아스 쇼에게 소포를 가져가야 합니다.", description = "배지요? 오, 아무것도 아니에요. 당신이 처리할 수 있는 건 아니니까 신경쓰지 마세요. 마티아스님께서 당신 행색을 보면 진짜 도적보다는 치즈 배달원으로 착각하시겠군요. 그건 그렇고, 내게 일이 하나 주어졌는데 그 일을 끝내겠다고 약속을 했어요.\n\n말이 나와서 말인데 이 소포를 마티아스님께 전해주세요. 그러면 마티아스님께서 소일거리 한두 개 정도를 맡길 거예요.\n\n어서 가세요.", progress = "무슨 일인가?", completion = "나를 찾았군그래. 보아하니 여기저기 돌아다니면서 찾아다니느라 심신이 많이 지친 것 같군.\n\n렌직에게 자네를 여관으로 데려다 주라고 할까 아니면 일을 좀 하겠나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2206] = {title = "선적 일정 입수", objective = "데피아즈단 부두주임에게서 데피아즈단 선적 일정표를 빼앗아 단장 마티아스 쇼에게 가져가야 합니다.", description = "현장에 있는 우리 요원들로부터 골드샤이어 남쪽에서 데피아즈단이 대거 활동하고 있다는 보고가 들어왔네. 보고에 의하면 데피아즈단이 제로드 선착장을 정복하고 그곳을 통해 붉은마루 산맥에서 서부 몰락지대까지 대량의 밀수품을 운반하고 있는 모양이야.\n\n그 부두에 침투해서 선적 일정표를 빼내오게. 아마 부두주임이 주머니에 단단히 넣어 다닐 걸세.\n\n그리고... 혹시라도 발각되면 SI:7에서는 자네의 존재를 일체 부인할 것일세.", progress = "자네가 병영에서 어슬렁거리면서 헛되이 보내는 매 순간마다 생명이 약해진다네.", completion = "놀랍군... 케린이 마침내 제대로 된 &lt;class&gt;이 될 만한 재목을 찾았다는 게 놀라워. 이 칼을 받게, 친구. 언젠가 다시 SI:7을 위해 부름을 받을 날이 있을 걸세. 열심히 실력을 갈고 닦게. 항상 정신을 바짝 차리고 칼날을 잘 다듬어 두어야 해.\n\n때가 되면 우리의 모습은 보이지 않더라도 자네의 직감으로 알아차릴 수 있을 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n기민함의 단검"},
[2218] = {title = "구원의 길", objective = "아이언포지에 있는 훌프단 블랙비어드와 대화하십시오.", description = "인도받길 바라는 또 한 명의 길 잃은 영혼이시군? 당신은 목표를 찾고 싶은 거겠지. 난 영웅이 되고자 임무를 찾는 젊은이들을 천 명은 더 보았을 거요.\n\n그나저나 오늘 운이 좋군, 젊은 친구. 이 호그럴님이 당신의 갈증을 해소해 줄 수 있으니 말이오.\n\n자, 나가서 길을 따라 아이언포지로 가서 쓸쓸한 뒷골목으로 가시오. 거기에 도착하면 상급 도적 훌프단 블랙비어드님과 대화를 나누는 게 당신이 할 일이오. 그분이 당신을 구원의 길로 이끌어 주실 거요.", progress = nil, completion = "그러니까 자네가 적격이라고 생각한단 말이지? 이 블랙비어드의 선택을 받아 비밀 집회의 간부가 될 운명이라 이거지?\n\n별 볼일 없는 녀석들이나 자신을 그렇게 과대평가하는 법이지.\n\n하지만 우리는 바로 그런 녀석들을 찾고 있었네! 한 식구가 된 걸 축하해!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2238] = {title = "순진한 핑계", objective = "놈리건에서 오닌 맥해머를 찾아야 합니다.", description = "알다시피, 마그니 폐하께서 채석장에서 광석과 보석을 죄다 캐내라고 명하셨네. 드워프가 열 번을 살아도 만져보지 못할 엄청난 양이지.\n\n비밀 집회는 대단해. 우리는 귀금속의 가치를 평가한다네. 무슨 말인지 이해하겠나? \n\n우리는 그 고약한 국왕이 우리가 보석을 빼돌린다는 사실을 눈치채지 않았으면 하네. 그 광석과 보석은 모두 나누어 가져야 한다고. 내 말이 무슨 뜻인지 알겠나?\n\n가서 놈리건에 있는 오닌 맥해머와 얘기를 해보고 무슨 소식이든지 가져오게나. 그 드워프는 약삭 빠른 자라서 오염된 노움들 틈에 숨어있으니 조심하게.", progress = nil, completion = "쉬잇! 어리석기는... 목소리를 낮추라고! 놈들한테 들키겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2239] = {title = "오닌의 보고서", objective = "아이언포지에 있는 훌프단에게 오닌의 보고서를 가져가야 합니다.", description = "채석장? 맞아, 그 괴물 같은 증기 전차가 이곳을 거의 매일 지나가지.\n\n동쪽에 있는 내 연락책이 말하길 그 증기 전차는 아이언포지에서 출발해 골볼라 채석장에서 물건을 싣고, 카라노스에 잠깐 들러 연료를 채운 다음 무슨 이유 때문인지 멀리 돌아서 놈리건을 지나 아이언포지에 도착해 물건을 내려놓는다더군.\n\n모두 이 보고서에 기록되어 있으니 훌프단께 가져가면 그분이 다음 조치를 취할 거요.", progress = "오염된 노움이 풍기는 고약한 냄새가 좋았나? 묘한 미소를 띄고 있길래 물어본 것뿐이네.\n\n오닌에게서 어떤 소식을 가져왔는가?", completion = "예까지 오래 걸렸나? 물론 그랬겠지!\n\n수고했네. 이 단검을 갖고 길을 떠나게. 세 번째 단계를 행동에 옮길 준비가 되면 비밀 집회에서 자네를 또 부를 거야.\n\n세 번째 단계가 뭐냐고? 그야 두 번째 단계 다음이지. 내가 자네 등짝을 걷어차는 것 말이야.\n\n한번 맛보고 싶나?", rewards = "다음과 같은 것들을 받습니다:\n\n기민함의 단검"},
[2240] = {title = "비밀 석실", objective = "밸로그의 일지를 읽고 비밀 석실을 조사한 후 발굴조사단장 스톰파이크에게 보고해야 합니다.", description = "자, 그럼 임무 얘기를 하지.\n\n카즈뮬의 석실이라는 비밀 석실이 있는데 그곳을 조사해야 하네. 문제는 이 방으로 들어가는 커다란 문이 잠겨져 있다는 것인데, 다행히 내가 그 문을 여는 방법을 알고 있지.\n\n내가 이 탁자 위에 있는 일지에 모두 적어뒀지. 지금 나와 내 동료는 이곳에서 꼼짝할 수가 없다네... 그러니 자네가 우리를 대신해 카즈뮬의 석실을 찾아야 하네!\n\n내 일지를 읽고 그 석실을 조사한 후 아이언포지에 있는 탐험가 연맹으로 가서 발굴조사단장 스톰파이크에게 보고하도록 하게.", progress = nil, completion = "카즈뮬의 석실을 봤단 말이오? 놀랍군! 밸로그는 비밀 석실이 존재한다고 확신했었지만 솔직히 나는 의심을 했었소.\n\n고맙소. 당신이 비밀 석실을 찾았다는 소식이 전해지면 울다만을 되찾으려는 우리 지도자들이 더욱 힘을 얻게 될 거요. 그리고 울다만을 다시 아이언포지가 지배하게 되면 카즈뮬의 석실에 숨겨진 비밀은 우리 것이 되는 거지!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n드워프족 돌격 도끼탐험가 조합 등불\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2241] = {title = "짝사랑", objective = "다르나서스에 있는 시우르나에게 잔노크의 장미를 가져가야 합니다.", description = "무슨 뜻인지는 잘 모르겠지만 주위 친구들이 날더러 '상사병'에 걸렸다고 하더군요.\n\n그래요. 눈만 뜨면 언제나 시우르나 생각뿐이오. 집안 벽은 온통 시우르나의 초상화로 가득 차 있소. 그래요... 며칠씩 뜬 눈으로 밤을 지새며 먹지도 마시지도 않고 우리가 못 다한 사랑을 슬퍼하지. 그게 그렇게 잘못된 것이오?\n\n이제 그녀는 날 만나려고도 하지 않는단 말이오. 그렇게 사랑했던 나를! 그녀에게 서신을 보내려고도 해봤지만 도적이 아니면 그 누구에게도 말을 하지 않는단 말이오.\n\n이 꽃을 그녀에게 좀 전해주지 않겠소? 이 잔노크가 보냈다고 말하는 것도 잊지 마시오.", progress = "어머나, 이런 기막힌 일이... 당신 장례식에 쓸 꽃이라도 가져온 건가요?", completion = "그 바보 같은 잔노크가 보낸 꽃을 다 모았더라면 꽃집을 열고도 남았을 거예요. 하지만 이번에 보낸 꽃은 쓸모가 있을지도 모르겠군요.\n\n혹시 저와 손 잡고 일 해볼 생각이 있나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2242] = {title = "운명의 부름", objective = "고대정령 세시르를 찾아 시우르나에게 가져갈 만한 어떤 단서든지 찾아와야 합니다.", description = "텔드랏실의 숲에 일어나고 있는 일을 이해하는 데 도움을 줄 수 있는 존재가 있다고 합니다. 하지만 유감스럽게도 그 존재의 도움을 받으려다 모두들 엄청난 재앙만 겪었죠.\n\n그는 신탁의 숲 주변에 있는 나뭇가지에 숨어 살고 있어요. 지금까지 온갖 방법을 사용해 봤지만 아무런 소용이 없고 그 사티로스에게 접근한 자는 모두 죽어버리고 말았답니다. 은신한 상태에서 접근하는 것이 해답일지도 모르겠군요.\n\n고대정령 세시르의 가방에 무엇이 있는지 알아내서 내게 알려주세요.", progress = "고대정령 세시르에 대해 알아온 게 있소?", completion = "기분 나쁜 소식이군요. 어둠의 해안 전역을 덮친 질병이 우리 고향까지 힘을 뻗친 것 같네요.\n\n수고를 해줘서 고맙습니다. 하지만 이제는 더 이상 이곳에서 할 일이 없을 것 같군요. 텔드랏실을 위해 일한 답례이니 이 검을 받아주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n기민함의 단검"},
[2258] = {title = "황야의 땅에서 재료 찾기", objective = "황야의 땅에서 자칼 모스멜드에게 대머리수리 모래주머니 5개, 바위산코요테 송곳니 10개, 바위 정령 파편 5개를 가져가야 합니다.", description = "이보게, 자네만 괜찮다면 도움이 좀 필요하네. 나는 이름이 좀 알려진 연금술사인데 자네가 황야의 땅에서 재료 찾는 일을 도와주었으면 하네.\n\n재료를 넉넉히 비축해 두어야 하는데 몇 가지가 부족해서 말이야. 대머리수리 모래주머니 5개, 바위산코요테 송곳니 10개, 바위 정령 파편 5개가 필요하네. 물론 짐승들에게서 직접 얻어와야 하는 것도 있으니 자네가 싸움에 익숙한 체질이 아니라면 싸울 줄 아는 친구들을 찾아 보도록 하게나.\n\n이 물건들을 가져오면 돈을 좀 주겠네. 해보겠나?", progress = "내가 말한 물건들은 가져왔는가? 그 재료들을 가져와야 돈을 줄 수가 있네.", completion = "아, 수고했네! 당분간은 이걸로 버틸 수 있겠군. 자, 여기 약속한 수고비일세.\n\n관심이 있는지 모르겠지만 아직 필요한 재료가 더 있다네. 그런데 이것들은 울다만 발굴 현장 깊숙한 곳에서만 찾을 수 있지. 구하기가 쉽지는 않을 테지만 날 한번 더 도와준다면 그 대가는 톡톡히 하도록 하지.\n\n어쩌면 반짝이는 동전보다 더 좋은 걸 줄 수도 있고 말이야. 어떤가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2259] = {title = "에리온 셰이드위스퍼", objective = "다르나서스에 있는 에리온 셰이드위스퍼를 만나야 합니다.", description = "걱정 마시오. 당신을 시우르나에게 보내진 않을 테니까. 에리온이 세나리온 자치령에서 당신을 기다리고 있소. 서둘러 가 보시오!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2260] = {title = "에리온의 부탁", objective = "스톰윈드로 가서 칼잡이 렌직에게 조언을 구해야 합니다.", description = "그대의 공적에 대한 이야기가 자자하더군요. 사실 너무 멀리까지 퍼져 스톰윈드 첩보기관에서도 그대의 이름을 대며 찾고 있습니다.\n\n고생스럽고 위험한 여행이 되겠지만 SI:7 밑에서 훈련 받을 기회를 놓쳐서는 안됩니다.\n\n스톰윈드의 구 시가지로 가서 SI:7 본부에 있는 칼잡이 렌직과 얘기를 나누십시오. 새로운 세상이 그대를 기다리고 있습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2278] = {title = "백금 원반", objective = "바위감시자와 대화하고 그가 알고 있는 고대의 지식을 배우십시오. 지식을 배운 후에는 노르간논의 원반을 가동하십시오.", description = "이 보물의 방 중앙에는 네 개의 거대한 백금 원반이 놓여 있는데, 각 원반은 근원을 알 수 없는 무수한 인장으로 꾸며져 있습니다. 이 원반을 손으로 건드리면 따끔거리는 느낌이 전해지면서 거대한 바위감시자의 모습이 앞으로 튀어나옵니다.\n\n\"안녕하십니까. 저는 지식의 파수꾼입니다. 창조주의 토석인 창조와 관련된 정보가 이 노르간논의 원반에 기록되고 보관되어 있습니다.\"\n\n당신은 이 세상에서 일찍이 발견된 적 없는 지식을 알게 된 것입니다!", progress = "바위감시자의 목소리가 몸속에서 울려 퍼지는 듯합니다.\n\n\"먼저 노르간논의 원반의 자료를 이해하는데 필요한 조건을 충족해야 합니다. 그래야만 저장된 자료를 휴대용 자료로 보관하여 가져갈 수 있습니다. 먼저 이 저장소에 든 정보를 모두 살펴보십시오.\"", completion = "바위감시자의 지시에 따라 토석인, 트로그, 드워프의 역사를 배웠으니 다시 한번 노르간논의 원반에 접속합니다. 원반 안에서 윙윙거리는 희미한 소리가 짧게 들리며 바위감시자이 말합니다.\n\n\"원반이 만들어졌습니다. 노르간논의 원반에 한번 더 접속하여 개인용 사본을 받아가십시오.\"", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2279] = {title = "백금 원반", objective = "아이언포지에 있는 탐험가 연맹에 노르간논의 소형 백금 원반을 가져가야 합니다.", description = "노르간논의 원반을 만지자 다시 손이 따끔거립니다. 하지만 이번에는 원반 내부에서 이상한 마찰음이 들립니다.\n\n가방이 갑자기 무거워져서 안을 보니 소형 원반이 들어있습니다!\n\n분명히 아제로스의 고대 역사에 관심 있는 자들에게 아주 값진 물건이 될 것입니다. 얼라이언스에 널리 알려져 있는 아이언포지의 탐험가 연맹이 그러한 단체 중 하나입니다. 그들이라면 원반을 유용하게 사용할 수 있을 것입니다.", progress = "어서 오게나, 뭐 도와 줄 일이라도 있나? 지금은 굉장히 바빠서 말이야. 하지만 탐험가 연맹에 중요한 일이라면 무슨 얘기든 들어주도록 하지!", completion = "뭘 가지고 온 겐가...? 맙소사. 이걸 어디서 찾았단 말인가?\n\n정말인가?\n\n누구한테 뭘 물어봤다고?\n\n진정 진실인가?!\n\n대단한 &lt;class&gt;|1이여;여;, 자네는 올해의 고고학적 발견에 해당하는 유물을 찾은 걸세! 아니. 그걸로는 부족하지. 세기의 발견이야! 이 원반이 내가 생각하는 그것이라면 지금까지 찾고 있었던 바로 그 열쇠가 될 수 있을 것일세. 바로 &lt;race&gt;의 마법적 창조에 대한 정당성을 확증할 수도 있단 말이지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2280] = {title = "백금 원반", objective = "썬더 블러프에 있는 현자 중 하나에게 노르간논의 소형 원반을 가져가야 합니다.", description = "노르간논의 원반을 만지자 다시 손이 따끔거립니다. 하지만 이번에는 원반 내부에서 이상한 마찰음이 들립니다.\n\n가방이 갑자기 무거워져서 안을 보니 소형 원반이 들어있습니다!\n\n분명히 아제로스의 고대 역사에 관심 있는 자들에게 아주 값진 물건이 될 것입니다. 호드에 널리 알려져 있는 썬더 블러프의 현자들이 그러한 역사가들입니다. 그들이라면 원반을 유용하게 사용할 수 있을 것입니다.", progress = "어서 오게, 젊은이. 천막으로 걸어 들어오는 모습을 보니 걸음걸이에 힘이 넘치는군... 그대의 목표를 이루기 위한 결의로 가득 차 있어. 호드에게 극히 중대한 문제로 내 조언을 들으러 온 것일 테지? 자네 앞에 밝혀진 우주의 수수께끼를 알고 싶은 건가?", completion = "여기 이것은 뭐란 말인가?\n\n놀랍군, 젊은이! 이 원반들, 이 속에 오랜 세월 동안 대지가 지녀온 비밀이 느껴지네. 자네 아주 현명한 친구로군. 내게 가져오길 잘했네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2281] = {title = "붉은마루 집결", objective = "붉은마루 산맥의 레이크샤이어로 가서 루시우스와 대화해야 합니다.", description = "지금 당신을 전장에 내보내는 것은 자살 행위요. 이 렌직은 또다시 도적을 잃고 싶지 않거든. 아.. 아, 이 렌직이 당신 실력을 부쩍 키워줄 테니 걱정마시오.\n\n붉은마루 산맥으로 가서 루시우스라는 이름의 SI:7 요원을 찾으시오. 레이크샤이어 부두에서 수상한 다른 녀석들과 함께 있을 거요.", progress = nil, completion = "아, 그러니까 솜씨가 좀 녹슬었다는 것이군? 걱정 말라고. 당신보다 더 형편없는 &lt;class&gt;들도 훌륭하게 키워냈으니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2282] = {title = "앨더의 제재소", objective = "루시우스의 금고를 열고 도적의 징표를 회수한 다음 레이크샤이어에 있는 루시우스에게 가져가야 합니다.", description = "우리는 이곳에서 여러 해 동안 도적들을 훈련시켜 오고 있소! 어쨌거나, 당신 같은 악한들이 모두 이 늙은 루시우스 같은 품위와 솜씨를 갖고 태어나는 건 아니니까 말이외다.\n\n여기서 길 위로 좀 떨어진 곳에 앨더의 제재소를 찾을 수 있을 거요. 난 그곳에서 안에 무언가 중요한 게 들어있는 상자를 얻었지. 가서 그걸 나에게 가져오시오! 그 징표를 가지고 돌아오면 도적 증명서를 받게 될 거요!", progress = "내가 오크에 대해 말해 주지 않았던가?\n\n그 제재소 근처에서 어슬렁대고 있다고 들었는데...", completion = "금고를 열었군그래! 잘했소.\n\n이제 당신이 죽는다 해도 그게 당신의 어리석음 때문이지 경험 부족 때문이 아니란 걸 알고 있으니 이제 우린 두 다리 쭉 뻗고 잠들 수 있겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n도적 증명서"},
[2283] = {title = "목걸이 회수", objective = "울다만 발굴 현장에서 값진 목걸이를 찾아 오그리마에 있는 드란 드로퍼스에게 가져다주어야 합니다. 목걸이는 파손된 것이라도 괜찮습니다.", description = "당신에게 줄 일거리가 있소. 배짱이 있다면 말이오!\n\n황야의 땅 깊은 곳에 울다만 발굴 현장이 있소. 최근 그곳에서 죽은 어떤 멍청한 성기사에 대한 얘기를 들었는데... 우리가 그 얘기에 관심을 갖는 이유는 그 성기사가 아주 값진 목걸이를 갖고 있었기 때문이지. 그 목걸이에는 루비, 사파이어, 토파즈 이렇게 세 가지 큰 보석이 박혀 있었다고 하오.\n\n우리는 바로 그것을 원하오. 보수를 최고로 줄 생각이오. 파손됐을지도 모르지만 긁힌 흠집은 우리가 다 고칠 수 있으니까 말이오.", progress = "목걸이는 가져왔소? 목걸이를 가져오지 않으면 한 푼도 줄 수가 없소이다!", completion = "음. 구해왔군! 목걸이 냄새가 나... 어디 얼마나 예쁜지 볼까...\n\n이 보시오, 지금 뭐 하자는 거요? 목걸이에 보석이 없지 않은가! 우리가 그걸 모를 거라 생각했소? 저 멍청한 말톤 녀석도 보석이 없다는 것쯤은 알아챌 거요.\n\n음... 설마 당신이 챙긴 건 아닐 테고... 하지만 목걸이는 그 보석들이 없으면 아무런 쓸모가 없어! 당신 임무는 덜 끝났소. 끝나려면 아직 멀었다고!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2284] = {title = "목걸이 회수 - 2차 시도", objective = "울다만 깊은 곳에서 보석의 행방에 대한 단서를 찾아야 합니다.", description = "그 보석들이 울다만 어딘가에 있는 건 멍청이 말톤도 알고 있을 만큼 확실한 사실이오. 다시 돌아가서 찾아보도록 하시오.\n\n전에도 말했지만 우리가 입수한 정보가 정확하다면 이 목걸이에는 루비, 사파이어, 토파즈가 붙어있었소. 보석들을 찾아서 목걸이에 다시 붙이도록 하시오.\n\n보석들이 어디 있는 지야 누가 알겠소? 운이 좋으면 그 성기사의 유해에서 찾을 수 있을지도 모르지. 벌써 모두 털려버리지 않았다면 시체에 보석들이 남아 있지 않겠소?", progress = nil, completion = "드란이 말했던 성기사의 시체를 찾은 것 같습니다. 성기사의 시체를 뒤지다 일지처럼 보이는 책을 발견합니다. 그런데 책의 상태가 좋지 않습니다. 피가 말라붙어 대부분의 내용을 제대로 볼 수 없습니다. 제대로 보이는 부분도 이해할 수가 없으며, 보아하니 인간의 언어로 쓰인 것 같습니다.\n\n책에서 정보를 얻으려면 먼저 책을 번역해야만 합니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2298] = {title = "왕의 철저한 수색", objective = "스톰윈드로 가서 칼잡이 렌직을 찾아야 합니다.", description = "그러니까 거기에서 3단계를 구상하려던 참이었는데 마그니의 얼간이 두 놈이 쳐들어와서는 강도가 어쩌고 하면서 비밀 집회 단원 몇을 잡아가더란 말이지.\n\n하지만 이 노련한 블랙비어드는 아무에게나 잡히는 몸이 아니지! 말싸움이 거세지면서 자네 이름이 튀어나왔는데 말이야.\n\n내가 충고 한 마디 할까? 아이언포지에서 그리핀을 타고 스톰윈드로 가게. 거기서 다시 구 시가지로 가서 칼잡이 렌직이라는 내 오랜 벗과 얘기를 해보게나.", progress = nil, completion = "훌프단의 &lt;class&gt; 친구라면 언제나 대환영이오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2299] = {title = "훌프단에게로!", objective = "아이언포지로 가서 훌프단 블랙비어드와 대화하십시오.", description = "어디 갔다 온 거요? 훌프단께서 당신을 찾아 온 사방을 뒤지고 다녔단 말이오. 국왕이 당신을 감옥에 잡아넣은 건 아닌가 걱정하고 있었소.\n\n당장 아이언포지로 가서 훌프단님과 얘기해 보시오!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2300] = {title = "SI:7", objective = "스톰윈드로 가서 칼잡이 렌직을 찾아야 합니다.", description = "렌직이 당신을 찾고 있습니다.\n\n나라면 마티아스의 부사령관을 기다리게 하지는 않을 겁니다.", progress = nil, completion = "일할 준비는 되었소? 아니면 그 전에 낮잠이라도 자야 하는 거요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2318] = {title = "일지 번역", objective = "성기사의 일지를 번역할 수 있는 이를 찾아야 합니다. 그런 자가 있을만한 가장 가까운 곳은 황야의 땅에 있는 카르가스입니다.\n\n제공된 아이템: \n", description = "이제는 책을 이해할 수 있는 언어로 번역하는 길밖에 없습니다. 번역을 할 수 있는 이들은 많이 있습니다. 하지만 가장 가까운 곳은 황야의 땅에 있는 카르가스 전초기지입니다. 그곳에서 찾아보기 시작하는 게 좋을 것 같습니다.", progress = nil, completion = "안녕하신가, &lt;class&gt;. 나는 이 황야의 땅에서 당신이 무슨 일을 하고 있는지 알고 있지. 지금은 내 언어적 재능이 필요해 온 것이겠지? 당신은 울다만에서 발견한 목걸이의 부속을 찾고 있군.\n\n놀랐는가? 놀랄 것 없어. 그런 일을 캐내는 게 내 직업이니까. 내가 일지를 번역해 주면 그 대가로 뭘 해줄 것인지부터 얘기해 봅시다. 이 근방에서 번역을 할 줄 아는 건 나뿐이오. 날 믿으시오.\n\n드란 드로퍼스와 그 멍청한 아들이 제안한 것보다 더 멋진 제안을 하나 하겠소. 내 제안을 받아들이더라도 그들과의 거래는 마칠 수 있고... 어떻소? 구미가 당기지 않소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2338] = {title = "일지 번역", objective = "자칼에게 목걸이를 빌려주면 그에 대한 보답으로 일지를 번역해 줄 것입니다.", description = "드로퍼스 부자는 목걸이의 마법을 복원할 수 있을 만한 지혜가 없지만 나는 달라. 그리고 난 욕심 때문이 아니라 단지 목걸이를 연구해서 직접 만드는 법을 알아내고 싶은 것뿐일세. 그러니 내게 목걸이를 빌려주게. 자네의 목걸이가 필요하오. 그 대가로 내 그 일지를 번역해주겠네. 보석을 찾아 헤매느라 아까운 시간을 낭비하느니 내게 번역을 맡겨서 무엇을 해야 하는지 알아내는 게 어떻나?!\n\n간단한 거래지. 아주 현명한 거래이기도 하고. 어떻게 할 텐가?", progress = "생각해봤나? 현명한 자라면 이 거래를 받아들여야지. 자네와 내가 원하는 것을 모두 얻게 되니 말일세. 그리고 드란과 말톤 부자들 역시 원하는 걸 얻게 되리라 생각하겠지.", completion = "현명한 결정이야. 자네는 믿을만하리라는 걸 진작에 알고 있었지. 잠깐만 시간을 주면 마법을 이용해 인간의 언어를 자네가 이해하는 언어로 번역할 수 있다네. 나는 신용을 제일로 여기는 트롤이지. 호드의 아무나 붙잡고 이 자칼 모스멜드에 대해 물어도 똑같은 대답이 나올 걸세. 자, 그럼 시작하겠네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2339] = {title = "보석과 마력원천 찾기", objective = "울다만에서 목걸이에 필요한 보석 3개와 마력원천을 회수한 후 카르가스에 있는 자칼 모스멜드에게 가져다주어야 합니다. 자칼의 말에 의하면 울다만에서 가장 강한 피조물을 처치하면 마력원천을 얻을 수 있다고 합니다.\n\n일지의 내용을 보니 루비는 어둠괴철로단의 방어진에 숨겨져 있습니다.\n\n토파즈는 얼라이언스 드워프 근처에 있는 트로그 구역 중 하나에 있는 항아리에 숨겨져 있습니다.\n\n사파이어는 트로그의 우두머리인 그림로크가 가지고 있습니다.\n\n마력원천은 울다만에서 가장 강한 피조물을 처치하면 얻을 수 있습니다.", description = "일지 여기 있네. 번역도 다 됐지.\n\n내용을 보니 루비는 드워프가, 토파즈는 트로그가, 그리고 사파이어는 그림로크라는 트로그가 가지고 있다는군.\n\n목걸이의 효력을 되찾으려면 마력원천이 필요한데, 드란 드로퍼스는 이 사실을 모르고 있지. 마력원천을 찾으려면 이렇게 하게. 울다만 깊숙이 들어가 강력해 보인다 싶은 피조물들은 모조리 물리치게. 그러다 보면 분명히 마력원천을 얻을 수 있을 걸세.\n\n모든 걸 다 찾거든 내게 가지고 오고.", progress = "목걸이에 힘을 넣어 줄 수 있는 보석들과 마력원천을 찾지 못했다면 다시 울다만의 깊은 곳으로 들어가게.\n\n자네는 보석들을 되찾아 오그리마에 있는 그 바보들에게 가져가면 되고 마력원천은 내가 보관하도록 하지... 가장 먼저 목걸이에 힘을 불어 넣는 건 마력원천일 테니까...", completion = "아주 잘했네. 이제 우리 계획이 큰 성과를 보일 걸세. 목걸이는 거의 다 조사해서 제조 공정을 알아냈으니 내 소기의 목적은 달성한 것이지.\n\n자네가 보석들과 목걸이를 오그리마로 가져가기 전에 먼저 내가 특별히 준비한 마법으로 분석을 좀 해보겠네. 잠깐이면 될 거야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2340] = {title = "보석 전달", objective = "오그리마에 있는 드란 드로퍼스에게 회수한 목걸이와 보석을 가져다주어야 합니다.", description = "재질이 같기만 하면 목걸이에 아무 보석이나 부속품을 써도 상관없지. 목걸이에 마법을 부여하려면 이 마력원천의 힘이 필요하다네. 아마도...\n\n마력원천이 실제로 힘을 발휘한다면 자네에게 목걸이에 필요한 보석들을 기꺼이 내놓겠네.\n\n오그리마로 가서 드로퍼스 부자 고물상과 거래를 끝내게. 우리 거래에 대해서는 아무 말 하지 말고... 자네가 돌아올 때쯤이면 아주 멋진 선물을 받을 수 있도록 준비해놓고 기다리겠네.", progress = "아니, 이게 누군가! 신수가 훤해졌군. 여기까지 오면서 무슨 기분 좋은 일이라도 있었나 보지?! 희소식을 가져 왔길 바라오. 부탁한 물건들을 모두 가져오기 전까지는 돈을 주지 않을 테니까. 분명히 말해두는데 두 번이고 세 번이고 확인해볼 거요!", completion = "옳지, 다 가져왔군. 그런데 이 가방도 함께 받아도 되겠는가? 그러라고? 정말로 고맙소! 하하!\n\n이 목걸이는 지금까지 우리가 손에 넣은 것 중 최고일 거야! 너무 아까워하지는 마시오. 어차피 당신 목에는 맞지도 않을 테니까... 하하!\n\n약속은 약속이니까 여기 수당이오. 우리 거래는 일단 여기서 끝내자고. 다음에 다른 일거리가 있는지 알아보러 오시오. 아니면 얼씬도 하지 말고!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2341] = {title = "목걸이 회수 - 3차 시도", objective = "카르가스에 있는 자칼 모스멜드를 만나 그의 실험이 성공했는지 알아보십시오.", description = "드란 드로퍼스와 말톤 드로퍼스가 새로 들어온 고물을 두고 다투기 시작합니다. 이제 여기서 볼 일은 끝났습니다. 카르가스의 자칼 모스멜드가 줄지도 모를 보상을 받으러 황야의 땅으로 떠날 만반의 준비가 갖추어졌습니다.", progress = nil, completion = "자네가 준 마력원천은 나의 기대를 초월하는 것이더군. 그래서 내 것과 자네 것, 이렇게 두 개나 만들었다네. 아직도 세 개는 더 만들 수 있는 분량이 남았지. 드로퍼스 부자 고물상은 그리 영리하지 못하니까 수입이 아주 짭짤할 게야.\n\n자, 받게. 일을 훌륭하게 끝마쳐줘서 고맙네. 자네가 수고한 보답으로 주는 아주 특별한 상일세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n자칼의 마법 목걸이"},
[2342] = {title = "보물 되찾기", objective = "울다만의 남쪽 대전당에 있는 궤짝에서 가레트가의 보물을 찾아 언더시티에 있는 그에게 가져가야 합니다.", description = "가레트 가문의 사람이 이런 빗자루로 박쥐 우리나 쓸고 있다니 말도 안 돼요! 이 지긋지긋한 일로 모은 몇 푼 안 되는 돈을 당신에게 투자하겠으니 제 신분을 좀 올려 주세요.\n\n우리 가레트 가문이 채굴꾼으로 열심히 일했을 때부터 울다만의 남쪽 대전당에는 가레트 가문의 무기가 든 궤짝이 있어요. 그게 없으면 전 영원히 이곳에서 이 지긋지긋한 박쥐들을 따라다니며 청소나 하게 될 거예요.\n\n우리 가문의 보물을 찾아 제게 가져와 주세요! 제가 타고난 권리를 회복하도록 도와주세요!", progress = "쓸어도 쓸어도 끝이 없군... 이놈의 박쥐들 때문에 쓸어봐야 헛수고랍니다. 저희 가문의 가보를 찾아오셨나요? 답례로 돈을 드리겠다고 했는데 그거면 충분하지 않을까요?", completion = "마침내 가레트 가문의 자손에게 어울리는 빗자루를 찾았군. 당신에게 전 재산을 투자한 보람이 있었네요!\n\n들었느냐, 이 더러운 박쥐들아? 이제 내게는 가레트 가문의 무기가 있다고! 두려워해라, 박쥐들아, 벌벌 떨라고!!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2358] = {title = "네즈라의 뿔", objective = "레이크샤이어에 있는 아란티르의 그림자에게 네즈라의 뿔을 돌려줘야 합니다.", description = "몇 년 전, 라벤홀트 장원에서 네즈라의 뿔이 도난당했소. 나는 대륙과 바다를 가로지르며 수색을 했지만 이 보잘 것 없는 야수들이 계속 갖고 있었다는 사실을 알아내는 데 그쳤소.\n\n거치적대는 검은바위부족 오크를 모두 해치우고 네즈라의 뿔을 찾아 레이크샤이어로 날 찾아오시오.\n\n일이 잘 되면 당신의 이름이 라벤홀트가에 알려지게 될 거요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n엉겅퀴 차"},
[2359] = {title = "클라벤의 탑", objective = "데피아즈단 탑 열쇠를 훔쳐 데피아즈단 탑으로 숨어 들어간 후, 그늘숲 궤짝에 무엇이 들어 있는지 밝혀 내야 합니다. 알아낸 모든 정보를 가지고 스톰윈드에 있는 마티아스 쇼에게 돌아가야 합니다. 켈넌의 보고서을 읽고 탑에 대한 정보를 얻으십시오.", description = "저는 이 탑에서 몇 주째 잠복을 하고 있었습니다. 최근 그늘숲에서 많은 짐이 도착했는데 그와 함께 경비병들도 오더군요.\n\n그들이 무슨 종족인지는 모르겠어요. 아마 당신도 마찬가지겠지만 한가지 확실한 것은 그들은 인간이 아니라는 거예요.\n\n어쨌든, 그 짐 중에는 궤짝도 있었어요. 아마 저 흉측한 것들은 그 궤짝을 지키는 것이겠지요. 저들 중 얼굴에 못이 잔뜩 박혀 있는 좀비 녀석이 우리에게 필요한 열쇠를 지니고 있어요.\n\n그 열쇠를 얻어 탑으로 들어간 다음, 궤짝에 들어 있는 것이 무엇인지 알아내어 마티아스님께 돌아가서 보고하도록 하세요.", progress = "첩보원 켈넌에게서 소식이 있나?", completion = "흠, 일지를 읽어보니 탑 밖에서 데피아즈단 일꾼들이 돌아다니는 것이 설명이 되는군. 그리고 투자개발회사가 데피아즈단과 관련이 있다는 것과 그늘숲으로부터 이상한 짐이 도착하는 것도 말이야.\n\n이 일지에 의하면 가시덤불 골짜기의 잔질 트롤이 물약으로 언데드를 만드는 방법을 발견한 것 같군... 더 정확히 말하자면 독약이지.\n\n독에 대한 해박한 지식 없이는 자네는 우리 SI:7에 아무 쓸모가 없네. 더군다나 언데드를 만드는 독 조제법이 우리 손에 있으니 말이야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n독 조제\n\n다음과 같은 것들을 받습니다:\n\n조리법: 엉겅퀴 차"},
[2360] = {title = "마티아스와 데피아즈단", objective = "서부 몰락지대로 가서 첩보원 켈넌을 찾아 보고를 받아야 합니다.", description = "때를 딱 맞춰 왔군. SI:7 정찰대의 보고에 의하면 서부 몰락지대에서 데피아즈단의 활동이 보통 때와 달리 잦아지고 있다고 하네.\n\n감시의 언덕 남동쪽에 있는 버려진 얼라이언스 감시 탑을 점령하여 작전 기지로 사용하면서 붉은마루 산맥 보급로로부터 물자를 밀수하는 모양이야.\n\n서부 몰락지대로 가서 탑 근처에 잠복하고 있는 첩보원 켈넌을 만나 보고를 받도록 하게.\n\n그리고 말일세... 혹시라도 자네가 발각되면 SI:7에서는 자네의 존재를 일체 부인할 것일세.", progress = nil, completion = "드디어 마티아스님께서 절 지원해 줄 또 다른 요원을 보내셨나 보군요. 그분께서 나쁜 소식을 들을 준비가 되셨으면 좋겠네요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2361] = {title = "목걸이 복원", objective = "이 목걸이를 기꺼이 당신에게 주겠소. 당신은 나에게 헤아릴 수 없이 귀중한 일을 해 주었소. 정말 고맙소이다. 자, 자랑스럽게 걸고 다니시오. 그리고 누가 만든 것인지 크게, 그리고 많이 말해 주시오!\n\n실제로 목걸이가 저주받지 않았다는 사실도 곁들여주면 더 고맙겠군.", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n탈바쉬의 마법 목걸이"},
[2378] = {title = "검은손 도적단을 찾아서", objective = "오그리마로 가서 어둠의 틈에 있는 셴툴과 대화해야 합니다.", description = "지금까지 자네는 죽음의추적자들을 위해 열심히 일해 왔네만 이제는 저 밖으로 모험을 떠날 때가 된 것 같군. 이제까지는 은신과 속임수에 소질을 보여 왔지만 아직 더 배워야 할 게 많다네.\n\n죽음의추적자들에게는 검은손 도적단 내부에 동지들이 있네. 우리를 도와줄 이를 찾게. 바로 오그리마에 있는 셴툴일세.", progress = nil, completion = "그래, 당신이 우리의 잘난 동지들이 셴툴에게 보낸 자란 말이지? 뭐, 그다지 감동적이진 않은데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2379] = {title = "잔도잔", objective = "어둠의 틈에 있는 잔도잔과 대화하십시오.", description = "당신의 결심만으로는 우리 앞에 놓인 난관을 극복하기엔 부족하다.\n\n잔도잔을 만나 검은손 도적단 요원으로서의 훈련을 받도록.\n\n은신술과 도적술을 깨우쳐야 비로소 당신의 운명을 향한 다음 발을 내디딜 수 있다.", progress = nil, completion = "어쩌면 잔도잔이 틀렸을지도 모르겠군. 잔도잔이 사과하겠소.", rewards = nil},
[2380] = {title = "오그리마로!", objective = "오그리마의 어둠의 틈에 있는 셴툴과 대화하십시오.", description = "당신이 은신술과 속임수의 달인은 아니지만 그런 거야 바뀔 수도 있고 또 분명 바뀌게 될 것입니다. 아직은 덜 익은 솜씨로나마 윗사람들을 상당히 놀라게 한 모양이군요. 위대한 셴툴이 직접 당신의 이름을 대며 찾고 있는 걸 보면 말입니다.\n\n여기서 북쪽으로 나 있는 길을 따라 오그리마로 가서 어둠의 틈에 있는 셴툴과 얘기해 보시기 바랍니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2381] = {title = "약탈자 약탈하기", objective = "톱니항에 있는 비운의 레닉스에게 남쪽바다해적단 보물을 가져가야 합니다. 레닉스의 기계장치에서 E.C.A.C.와 도둑 도구를 얻는 것도 잊지 마십시오. 임무를 완수하려면 이 두 가지가 모두 필요합니다.\n\n유별나게 공격적인 앵무새에게 맞서게 되면 E.C.A.C.를 사용하십시오!", description = "어이, 겁 주려는 게 아니야. 하지만 남쪽바다 해적단이 숨겨놓은 보물을 훔쳐 오라고 보낸 다섯 명의 도적이 모두 갈가리 찢겨 되돌아왔단 말이지.\n\n해안을 따라 남쪽으로 가다 보면 해적선 타이드 레이저호가 보일 거야. 바로 그 안에 남쪽바다 해적단의 보물이 들어 있지. 그 배 2층에는 녀석들이 도적들을 길러내는 해적 소굴이 있어.\n\n올라가서 보물을 훔쳐서 가져오라고. 도적 기술은 해적의 소굴에서 배울 수 있을테지만, 조심해야해!", progress = "흠... 아직까지는 몸이 성하군. 보물은 찾았소?", completion = "믿어지지 않는군! 정말! 그저 놀라울 따름이야! 당신 재주가 좋군. 아니면 살아 있는 자 중에서 최고로 운이 좋던가!\n\n여기 당신 몫이오. 틀림없이 당신이 나보다 더 유용하게 사용하게 될 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n엉겅퀴 차"},
[2382] = {title = "톱니항의 레닉스", objective = "톱니항으로 가서 비운의 레닉스와 대화하십시오.", description = "이 잔도잔은 보았다! 암, 그 날은 온다니까! 스랄이 죽는 날... 등에는 비수가 꽂히고 독이 핏줄을 따라 퍼지면서... 잔도잔이 말을 너무 많이 한 것 같군.\n\n<race>, 잔도잔이 당신에게 줄 임무가 있다! 이제 크로스로드 동쪽에 있는 톱니항에 가서 비운의 레닉스와 얘기를 하도록!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2383] = {title = "간결한 양피지", objective = "간결한 양피지를 읽어보고 프랑에게 양피지를 가져가야 합니다.", description = "당신이 없는 동안 양피지가 하나 도착했소, <name>.\n\n시간이 있다면 읽어보시오. 내가 착각한 것이 아니라면 이건 상급 전사, 프랑이 보낸 거요. 준비가 되는 대로 그에게 가보시오. 당신과 이야기를 나누고 싶은 것 같소. 동굴 밖에 있는 그늘에서 당신이 오기를 기다리고 있을 거요.", progress = "손에 들고 있는 게 뭔가? 양피지? 골치 아프게 하는 학자는 아니었으면 좋겠는데...", completion = "그건 내가 보낸 양피지가 맞군. 자네가 시험의 골짜기로 온다는 소식을 듣고 쓴 거라네, &lt;name&gt;. 여기까지 와주어서 기쁘군. 앞으로 닥칠 고난도 잘 이겨내길 바라네. 점점 더 힘이 강해진다는 생각이 들 때마다 내게 오게. &lt;class&gt;의 길을 가르쳐주겠네\n\n&lt;name&gt;, 행운을 비네, 가르침을 받을 준비가 되면 언제든지 이곳으로 와서 나를 찾게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2398] = {title = "길 잃은 드워프", objective = "울다만에서 밸로그를 찾아야 합니다.", description = "울다만에 있는 발굴현장이 항상 침략을 당한 건 아니오. 한때는 우리 아이언포지 드워프들이 그 지역을 다스렸었지. 하지만... 그건 트로그 녀석들이 오기 전이었소. 엄청난 숫자의 트로그들이 갑자기 밀어닥치는 바람에 우리 드워프들도 녀석들을 막아내지 못했소이다!\n\n사실 너무나 갑작스러운 공격에 우리 주민 일부가 빠져나오지 못하고 적의 경계선 너머에 갇혀있는 것 같소.\n\n트로그들이 나타나기 바로 전 내 친구 밸로그가 드워프 몇을 데리고 발굴현장 깊이 들어갔다오. 만약 살아있다면 당신이 그들을 찾아주기 바라오.", progress = nil, completion = "오, 이제야 나타났군! 올라프와 내기를 했는데 하마터면 질 뻔했군그래!\n\n올라프가 자기 수염이 무릎까지 자라기 전에는 살아있는 다른 &lt;race&gt;|1을;를; 볼 수 없다고 장담했었지. 휴, 이제 자네가 왔고 올라프의 수염이 무릎에 닿으려면 아직 한 뼘이 남았으니 다행이야.\n\n고맙네. 내가 내기에서 딴 돈을 좀 나누어 주도록 하지.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2399] = {title = "싹튼 잎", objective = "데날란이 정원에 심은 잎에서 싹이 트고 자랐습니다. 바르르 떠는 모습이 마치 누군가 뽑아주기를 바라고 안달하는 듯 합니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n싹튼 잎"},
[2418] = {title = "마법석", objective = "황야의 땅에 있는 리글퍼즈에게 덴트리움 마법석 8개와 안알레움 마법석 8개를 가져가야 합니다.", description = "얼마 전 어둠괴철로단 드워프들과 만난 일이 있지. 그들은 나를 고통의 요새로 데리고 가더니 울다만에서 캐낸 두 개의 이상한 마법석을 연구하게 하더군. 나는 그 마법석을 잘 다루기만 한다면 지속적이고 안정된 마력의 원천으로 사용할 수 있다는 것을 알게 됐지. 그 오래된 발굴 현장에서는 별 걸 다 찾게 된다니까!\n\n그건 그렇고, 내가 그 마법석의 비밀을 말해줬더니 녀석들은 날 고통의 요새에서 쫓아내고 울다만에서 더 많은 마법석을 찾기 시작했지.\n\n나도 그 돌을 갖고 싶다고! 그 두 가지 마법석을 모두 가져오면 후하게 사례하지!", progress = "마법석은 가지고 왔나? 내게 전력공급이 필요한 로봇 생쥐가 있는데...", completion = "대단해. 찾았군! 정말로 고마워. 당신은 여태껏 만나본 &lt;race&gt; 중에 가장 믿을만한 자야!\n\n어서 손보고 있던 장치에 써봐야겠군. 제대로 된 환경만 갖추어진다면 이 마법석을 사용한 장치들은 계속 돌고, 돌고, 또 돌겠지...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n활력의 돌버클러듀라신 팔보호구불변의 장화\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2438] = {title = "에메랄드의 꿈 흡입기", objective = "돌라나르에 있는 탈론카이 스위프트루트에게 에메랄드의 꿈 흡입기를 가져다주어야 합니다.", description = "나는 한때 바네실 지하굴에 사는 드루이드의 수호자 게롤라스 탈베드렌에게서 에메랄드의 꿈 흡입기를 받았었소. 이 강력한 아뮬렛은 에메랄드의 꿈에서 에너지를 빨아들일 수 있기 때문에 지니고 다니는 이에게는 행운이 따르지.\n\n안타깝게도... 그걸 별바람 마을에 있는 옷장에 두고 왔소. 별바람 마을도 한때는 평온한 곳이었지만 지금은 펄볼그의 타락으로 몰락해 버렸소.\n\n혹시 내 꿈 흡입기를 찾아와주지 않겠소?", progress = "서둘러 주시오. 펄볼그가 에메랄드의 꿈 흡입기에 손대지 않았기만 바랄 뿐이오.\n\n아직 찾아오지 못했소, <name>?", completion = "이 에메랄드의 꿈 흡입기는 내게 아주 소중한 거요. 소수에게만 주어지는 특별한 선물이지. 되돌려줘서 고맙소이다, &lt;name&gt;.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2439] = {title = "백금 원반", objective = "아이언포지 은행에 있는 디니타 스톤맨틀에게 사례 보증 서류를 가져가야 합니다.", description = "이 원반은 엄청난 발견이라네. 이 원반에 든 지식이 정확하다면 고대 티탄, 그러니까 창조주께서 우리의 마법적 창조와 연관이 있다는 말이 되네! 이 원반에 대해 가능한 많이 조사해 봐야겠네.\n\n이렇게 훌륭한 영웅적인 일을 해준 자네에게 보답을 해야겠지. 은행에 있는 디니타 스톤맨틀에게 이 사례 보증 서류를 가져다주면 원하는 보상을 받을 수 있을 걸세!\n\n준비가 되면 나한테 곧장 돌아오게. 탐험가 연맹을 위해 해야 할 일이 잔뜩 있네!", progress = "어서 오세요. 아이언포지 은행입니다. 무엇을 도와드릴까요?", completion = "아. 탐험가 연맹에서 발행한 사례 보증 서류군요. 음, 아주 좋은 보상을 받으실 수 있을 만한 것이네요.\n\n제 권한으로 탐험가 연맹의 은행에서 원하시는 만큼의 보상을 직접 드리도록 하겠습니다. 최상급 치유 물약 5개와 상급 마나 물약 5개 중 마음에 드는 것을 고르도록 하시기 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n최상급 치유 물약상급 마나 물약\n\n다음과 같은 것들 또한 받습니다:\n\n완화의 자루"},
[2440] = {title = "백금 원반", objective = "썬더 블러프에 있는 베나 윈터후프에게 사례 보증 서류를 가져가야 합니다.", description = "우리는 변치 않는 자세로 대지의 비밀을 알아내기 위해 정진해야만 하네. 내 힘을 이 원반에 집중하도록 하겠네. 때가 되면 진정한 원리가 밝혀지겠지.\n\n이 원반을 내게 가져와준 데 대한 사례를 하도록 하지. 썬더 블러프의 숙련 연금술사인 베나 윈터후프에게 이 사례 보증 서류를 가져가게. 그러면 그곳에 있는 내 물건 중에서 하나를 고르도록 해줄 걸세.\n\n그리고는 나한테 곧장 돌아오게. 이번 발견과 관련해서 해야 할 일이 매우 많을 것 같군그래.", progress = "안녕하세요! 연금술 훈련을 받으러 오셨나요, 아니면 다른 이유로 오셨나요?", completion = "아, 트루스시커께서 본인의 물건 중 하나를 선물로 줄 정도면 당신이 그분을 굉장히 기쁘게 해드린 것 같군요.\n\n여기 최상급 치유 물약 5개와 상급 마나 물약 5개 중 마음에 드는 것을 고르세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n최상급 치유 물약상급 마나 물약\n\n다음과 같은 것들 또한 받습니다:\n\n완화의 자루"},
[2458] = {title = "잠입", objective = "진흙늪 북쪽에 있는 투자개발회사 탑으로 가서 검은손 도적단의 비밀 요원인 감독관 피줄과 접촉해야 합니다.\n\n탑이 보이면 섬광탄포를 사용해 감독관 피줄에게 당신이 도착했음을 알리십시오. 섬광탄은 2번 발사해야 하며, 그 후 감독관 피줄에게 다가가 검은손 도적단 /경례를 해야 합니다.\n\n피줄은 자기가 모르는 자는 무조건 처치하려 들기 때문에 정확한 순서대로 수행해야 합니다.\n\n제공된 아이템: \n", description = "투자개발회사라고... 혹시 들어 본 적 있나?\n\n난 그 회사 내부에 요원 하나를 심어두기 위해 1년간 공을 들였다네. 신중한 계획을 세워 꾸준히 노력한 덕분에 성공은 했지.\n\n그런데 최근 투자개발회사에서 뭔가 대규모 사업을 계획하고 있다는 정보가 입수됐네. 진흙늪 북쪽에 있는 투자개발회사로 가서 우리측 비밀 요원인 감독관 피줄을 만나보게.\n\n탑을 찾으면 이 섬광탄포를 사용한 후 피줄에게 다가가서 검은손 도적단 /경례를 하도록.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n피줄의 호루라기"},
[2459] = {title = "꿈을 먹어치우는 페로시타스", objective = "돌라나르에 있는 탈론카이 스위프트루트가 나무옹이일족 비술사 7명을 처치하고 잃어버린 보석을 찾아달라고 부탁했습니다.", description = "에메랄드... 에메랄드가 사라졌소! 내 꿈 흡입기가 고장났어!\n\n별바람 마을 북쪽에는 나무옹이일족 비술사 한 무리가 살지. 그들의 우두머리인 꿈을 먹어치우는 페로시타스의 목에 걸린 목걸이가 밤에 녹색으로 빛난다고 하오. 꿈 흡입기가 고장나다니 분명히 놈이 에메랄드를 훔쳐갔어... 에메랄드의 힘이 자기에겐 아무짝에도 쓸모가 없다는 사실을 꿈에도 모르겠지.\n\n잃어버린 보석을 찾아주시오, <name>. 그리고 간 김에 타락한 비술사도 제거해 주시오.", progress = "나무옹이일족 비술사들과 페로시타스에게서 내 물건을 돌려받아야겠소. 에메랄드를 찾아야만 내 에메랄드의 꿈 흡입기를 고칠 수 있소.", completion = "이제 내 꿈 흡입기를 고칠 수 있겠군. 고맙소, &lt;name&gt;!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2460] = {title = "검은손 도적단 경례", objective = "셴툴에게 검은손 도적단 /경례를 해 보이십시오.", description = "검은손 도적단의 도적이라면 검은손 도적단 /경례를 반드시 배워두어야 한다. 당신이 도적단의 일원임을 증명할 수 있는 유일한 수단이니까 말이지.\n\n보고 배운 뒤 반복해서 연습하도록.", progress = nil, completion = "잘했다. 이제 다음 단계로 넘어가도 되겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2478] = {title = "미션 임파서블: 잘하면 가능", objective = "현장감독 실릭시즈에게서 실릭시즈의 탑 열쇠를 훔쳐낸 다음, 돌연변이 투자개발회사 일꾼 2명과 투자개발회사 순찰대원 2명, 그리고 투자개발회사 망꾼 2명을 처치해야 합니다.\n\n총감독 갤리윅스를 암살하고 그의 머리카락을 손에 넣은 후, 갤리윅스의 금고를 열고 잔질의 변화된 혼합물을 훔쳐내야 합니다. 그 혼합물과 갤리윅스의 머리카락을 오그리마에 있는 셴툴에게 가져다주고 다음 지시를 받으십시오.", description = "현장감독 실릭시즈에게서 탑 열쇠를 훔쳐내시오. 나중에 꼭 필요할 테니 열쇠를 손에 넣으면 잘 지니고 있으시오.\n\n이 탑에는 독이 퍼져 모든 것이 약해져 있다는 사실을 잊지 말고 이 탑에 사는 놈들을 인정사정 볼 것도 없이 처치하시오!\n\n반드시 갤리윅스를 암살하고 그 증거로 머리카락을 가져오시오. 그런 다음 그의 금고를 열고 잔질의 혼합물을 훔치시오. 갤리윅스의 머리카락과 혼합물을 오그리마에 있는 셴툴에게 가져가시오.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n조리법: 엉겅퀴 차"},
[2479] = {title = "히노트의 도움", objective = "힐스브래드 구릉지의 타렌 밀농장으로 가서 서지 히노트에게 잔질의 혼합물 견본을 전해야 합니다.\n\n타렌 밀농장으로 가려면 먼저 비행선을 타고 언더시티로 가야 합니다. 도착하면 남쪽 길을 따라 은빛소나무 숲을 지나 힐스브래드 쪽으로 가야 합니다. 표지판을 따라 가십시오!", description = "혼합물 견본을 타렌 밀농장에 있는 서지 히노트에게 가지고 가도록!\n\n당신을 치유할 수 있는 자가 있다면 그건 바로 서지일 것이다. 그곳까지 살아서만 도착할 수 있다면 서지가 독극물 제작 방법과 사용법을 가르쳐 줄 것이다.", progress = "이게 뭡니까???", completion = "피부를 보니 신선해 보이긴 하는데 당신에게서 무슨 냄새가 이리 지독하게 나는 겁니까? 말씀해 주세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2480] = {title = "히노트의 도움", objective = "서지 히노트가 해독제를 만드는 동안 기다려야 합니다.", description = "독에서 이렇게 놀라운 효과가 나오는 건 처음 보는군요. 잔질이라고 했습니까? 들어본 적은 없지만 이 독을 만들어 낸 실력만큼은 칭찬해주고 싶군요.\n\n그러니까 내가 이 독에 걸린 당신을 치료해주고 이 독을 어떻게 사용하는지 가르쳐줘야 한단 말입니까?\n\n이 독을 조사할 동안 잠시만 기다리도록 하세요.", progress = nil, completion = "해독제를 다 만들었습니다! 이 해독제를 마시면 점점 다가오는 광기를 막을 수 있을 겁니다. 하지만 냄새는 나도 어떻게 할 수가 없군요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n독 조제\n\n다음과 같은 것들을 받습니다:\n\n히노트의 물약"},
[2498] = {title = "데날란에게 돌아가기", objective = "레엘리안 그린스파이어가 알아메스 호수에 있는 데날란과 대화할 것을 부탁했습니다.", description = "알아메스 호수에 있는 데날란이 나무괴물들에게 퍼지고 있는 종양의 원인을 알아냈다는 소식을 방금 들었소. 가서 내가 보내더라고 말하고 얘기를 나눠 보시오.\n\n서두르시오. 그는 우리의 도움을 필요로 하고 있으니까.", progress = nil, completion = "아, 레엘리안이 날 돕기 위해 당신을 보낸 모양이군. 이렇게 빨리 와 주어서 다행이오.\n\n상당히 근심스러운 것을 발견했소이다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2499] = {title = "오크나무괴물", objective = "알아메스 호수에 사는 데날란이 오크나무괴물에게서 거대한 종양을 모아 달라고 부탁했습니다.", description = "남쪽 강둑 주변 동굴에 있는 오크나무괴물이라는 것이 알아메스 호수를 보금자리로 삼고 살아가는 생물들을 오염시키고 있소.\n\n너무 무서워서 감히 가까이 다가가진 못했지만 멀리서 보아도 한눈에 알아볼 수 있었소. 오크나무괴물이 지금까지 한 번도 본 적 없는 큰 종양에 걸렸다는 것을... 거대하다고 불러도 좋을 만큼 큰 종양이었소.\n\n이미 당신으로부터 너무나도 많은 도움을 받았지만 한 가지만 더 부탁하겠소. 오크나무괴물을 찾아 종양을 모아오시오. 부디 내 고향에서 악의 근원을 제거해 주시오.", progress = "오크나무괴물은 찾았소?", completion = "당신이라면 분명 호수에서 그 끔찍한 괴물을 몰아낼 수 있으리라 믿었소.\n\n참으로 비참한 일이오. 오크나무괴물은 한때 대자연의 지도자였는데... 하지만 타락이란 귀천을 가리지 않는 법이지.\n\n이 종양의 크기가 심히 걱정이오. 어서 조사를 해서 나무괴물을 괴롭히는 이 질병에 대해 더 알아봐야겠소. 고맙소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n흙나무 허리띠이끼로 덮인 건틀릿\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2500] = {title = "황야의 땅에서 재료 찾기", objective = "황야의 땅에서 필요한 재료를 구한 후 텔사마에 있는 가크 힐터치에게 돌아가야 합니다.", description = "<class>|1이여;여;, 당신의 도움이 필요하오. 나는 이름이 제법 알려진 연금술사인데 당신이 황야의 땅에서 재료 찾는 일을 도와주었으면 하오.\n\n재료를 넉넉히 비축해 두어야 하는데 몇 가지가 부족해서 말이오. 대머리수리 모래주머니 5개, 바위산코요테 송곳니 10개, 바위 정령 파편 5개가 더 필요하다오. 물론 짐승들을 죽여서 직접 얻어와야 하지. 그러니 맞서 싸우는 체질이 아니라면 싸움 꽤나 할 줄 아는 친구들을 찾아보도록 하시오.\n\n재료들을 찾아오면 수고비를 좀 주도록 하지... 어때, 해보겠소?", progress = "내가 말한 물건들은 가져왔소? 그 재료들을 가져와야 돈을 내줄 수가 있소.", completion = "오, 수고했소. 당분간은 이걸로 버틸 수 있겠군. 여기 약속한 수고비요.\n\n관심이 있는지는 모르겠지만 아직 필요한 재료가 더 있소이다. 그런데 이것들은 울다만 발굴 현장 깊숙한 곳에서만 찾을 수 있지. 구하기가 쉽지는 않을 테지만 날 한번 더 도와준다면 그 사례는 톡톡히 치르도록 하지.\n\n어쩌면 반짝이는 동전보다 더 좋은 걸 줄 수도 있고 말이오. 어떻소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2501] = {title = "황야의 땅에서 재료 찾기", objective = "빈 요술 유리병을 황야의 땅에 있는 화염의 수호비룡에게 사용해야 합니다. 3개를 다 채우면 텔사마에 있는 가크 힐터치에게로 가져가야 합니다.", description = "<name>, 당신은 지금까지 내게 아주 큰 도움이 되었소. 그 보상으로 전에도 한번 당신에게 준 적 있는 물약의 조제법을 드리겠소. 단, 위험한 임무 한 가지만 완수해 주면 말이오.\n\n이 금고에는 빈 요술 유리병 3개가 들어 있소. 화염의 수호비룡의 피를 빨아들일 수 있는 조화의 오라가 담겨 있는데, 그걸 비룡에게 사용하면 크게 노할 테니 조심해야 하오. 그 유리병 3개를 다 채우거든 내게 가져오시오.\n\n이 임무를 완수하면 조제법은 당신 것이 되는 거요.", progress = "요술 유리병으로 화염의 수호비룡 피를 모아 왔소? 그래, 위험한 임무라는 것은 나도 알고 있소... 하지만 내 복원의 물약 조제법이 당신의 성공을 기다리고 있소이다. 고생 끝에 낙이 오는 거요. 친구, 고생 끝에 낙이...", completion = "같은 연금술사로서 당신에게 경의를 표하겠소. 자, 이 복원의 물약 조제법을 받아 잘 기억해 두시오. 그 조제법이 오랜 세월 동안 내게 그랬듯이 당신에게도 성공과 보상을 가져다줄 거요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n복원의 물약\n\n다음과 같은 것들을 받습니다:\n\n"},
[2518] = {title = "달의 눈물", objective = "다르나서스의 달의 신전에 있는 여사제 아무라가 여왕거미 사스라의 은빛 돌기를 가져다 달라고 부탁했습니다.", description = "여왕거미 사스라는 한때 엘룬의 총애를 받았었지요. 우아하고 순수한 그녀는 달빛 아래에서 저녁 안개를 모아 은빛 실을 잣던 거미였어요. 그 은빛 이슬이 담긴 실에는 강력한 치유력이 있어 이 신전에 보관하고 있었답니다.\n\n하지만 최근, 사스라는 광적으로 변해 버렸어요. 이제는 그녀의 후손들마저도 위협을 받고 있어요.\n\n여왕거미 사스라를 찾아 그녀의 고통을 끝내 주세요. 그녀는 텔드랏실의 북쪽 경계 지역, 생명의 호수 근처에 살고 있답니다. 그녀의 은빛 돌기를 제게 가져와 주세요.", progress = "당신께 부탁 드린 임무에 대해서는 저도 유감이에요. 하지만 여왕거미 사스라에겐 더 이상 희망이 없어요.\n\n그 돌기를 엘룬께 제물로 바치고자 합니다. 엘룬께서 제물을 받으시고 사스라에게 축복을 내리실 테니 그녀는 다시 태어나 평화를 누리게 될 거예요.", completion = "숲이 여왕거미 사스라의 죽음을 애통해 하고 있어요. 하지만 어쩔 수 없는 일이었죠.\n\n고맙습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2519] = {title = "달의 신전", objective = "수녀 아퀴네가 달의 신전에 있는 여사제 아무라와 대화할 것을 부탁했습니다.", description = "한때는 위대했던 숲의 생물들이 도움을 필요로 하고 있어요. 당신이 꼭 맡아줘야 하는 임무가 있답니다.\n\n아무라 여사제님을 찾아가 보세요. 그분이 무슨 일인지 설명해주실 거예요. 여기서 남동쪽에 있는 달의 신전 안에서 그분을 찾아보세요.", progress = nil, completion = "아퀴네 수녀가 보냈다고요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2520] = {title = "사스라의 제물", objective = "여사제 아무라가 달의 신전 중앙에 있는 샘에 사스라의 은빛 돌기를 제물로 바치고 돌아와 달라고 부탁했습니다.", description = "이제 당신에게 주어진 임무도 완전히 끝나가는군요. 이 사스라의 돌기를 엘룬께 제물로 바치세요. 그 위대한 거미가 편히 쉴 수 있도록...\n\n이 신전 중앙에 분수대가 있는 샘에 제물을 두고 오세요. 그 안의 성수가 사스라를 미치게 만들었던 타락을 정화해 줄 거예요.\n\n이 일을 다 끝내거든 다시 제게 오세요.", progress = "샘에 제물을 올리셨나요?", completion = "사스라를 잃은 것은 슬픈 일이지만 이렇게 해야만 그녀가 새로운 영혼으로 다시 태어날 수 있어요.\n\n엘룬께서 당신이 바친 제물을 기쁘게 받으시기를...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n레이스 바지쿠션 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2521] = {title = "굼이샤의 지시", objective = "저주받은 땅을 돌아다니다가 완전무결한 드레니시스트 구슬을 발견하면 수집가 굼이샤에게 가져가야 합니다.\n\n이 보석은 아제로스를 통틀어 가장 희귀한 수정 중 하나로써 이곳 생물들이 지니고 있을 가능성도 있습니다.\n\n완전무결한 드레니시스트 구슬을 수집해 갈 때마다 각각에 대해 보상을 받게 됩니다.", description = "<race>의 그 조그마한 두뇌로 귀하디 귀한 드레니시스트 구슬의 완전무결함을 어찌 이해할 수 있겠어요? 드레나이는 이 결정 하나를 찾아 헤매는 데 평생을 바치다 결국 목적도 이루지 못한 채 허무한 최후를 맞이 했어요.\n\n자, 이제 이 굼이샤가 무얼 원하는지 알고서도 계속 도와주겠다고 나서는 건가요? 그렇다면 좋아요... 이 땅을 돌아다니다가 완전무결한 드레니시스트 구슬을 찾으면 내게로 가져오세요. 그 대가로 꿈도 꾸지 못할 부와 명예를 누리게 해드리죠.", progress = "나는 완전무결한 드레니시스트 구슬을 연구하는데 내 평생을 바쳤어요... 평생을!", completion = "내가 지금 헛것을 보고 있나? 말도 안 돼! 대체 어디서... 어떻게...\n\n어쩌면 이제 차원의 틈을 열어서 고향으로 돌아갈 수 있을지도 모르겠군요.", rewards = "다음과 같은 것들을 받습니다:\n\n에메랄드박힌 상자"},
[2522] = {title = "굼이샤의 노력", objective = "수집가 굼이샤에게 완전무결한 드레니시스트 구슬을 가져가야 합니다.", description = "비록 차원의 문을 열어 고향으로 돌아가는 데는 실패했지만 다음번에는 꼭 성공할 거예요.\n\n드레나이의 소망이란 싸구려 보석을 사랑하는 당신들의 욕심만큼이나 강하죠. 이 저주받은 땅에서 다시 한번 완전무결한 드레니시스트 구슬을 찾아오세요.\n\n물론 이 임무를 맡고, 안 맡고는 전적으로 당신에게 달렸죠! 훗...다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n에메랄드박힌 상자"},
[2523] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[2541] = {title = "잠자는 드루이드", objective = "바네실 지하굴에 있는 오벤 레이지클로에게 부두교 주술사 부적을 가져다주어야 합니다.", description = "이곳에 사는 나무옹이일족 주술사가 잠자는 드루이드의 영혼과 육체를 분리하는 방법을 발견했소. 내 육체를 마음대로 조종해 바네실 지하굴에 들어오는 자들을 공격하고 있소. 이제 나는 에메랄드의 꿈에 갇혀 이들을 막을 힘이 없다오.\n\n나를 도와주시오. 나무옹이일족 주술사들이 지니고 다니는 이상한 부적이 이 의식에 사용되는데 그걸 한번 살펴보고 싶소. 제발 나에게 이 부적을 하나만 가져와 주시오.", progress = "부적을 살펴보면 사악한 주문을 풀 방법을 찾을 수 있을 것 같소. 그 부적은 찾았소?", completion = "고맙소, &lt;name&gt;.\n\n참으로 기묘하게 생긴 물건이군... 사악한 기운이 뿜어져 나오는 것을 느낄 수 있소. 아주 강력한 주문이로군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2561] = {title = "발톱의 드루이드", objective = "오벤 레이지클로가 영혼을 잃어버린 그의 육체를 죽인 후 부두교 부적을 사용하라고 부탁했습니다.", description = "이 부적을 보고 나니 무엇을 해야 할지 알겠소. 이걸 받고 내 말대로 해주시오.\n\n이제 당신은 바네실 지하굴에서 가장 깊은 곳을 조사해야 하오. 그곳에 영혼을 잃어버린 내 육체가 있을 거요... 이런 말을 하려니 마음이 아프지만 달리 나무옹이일족에게서 내 자신을 해방시킬 방법이 없소.\n\n나무옹이일족에게서 벗어나려면 당신이 내 육체를 죽여줘야 하오. 그런 다음 쓰러진 내 육체에 부두교 부적을 사용하시오. 이 임무를 완수하면 다시 돌아와주시오.", progress = "내 육체에 접근할 때는 조심하시오. 아주 강력한 주문이 걸려 있을 테니까 말이오.", completion = "드디어 나무옹이일족의 손아귀에서 벗어났소. 고맙소.\n\n이제 내 영혼은 에메랄드의 꿈 속에서 영원한 단잠을 잘 수 있을 거요.\n\n언젠가 다시 만날 수 있을지도 모르겠소. 지금은 내 감사의 표시로 이걸 받아주시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n동면의 로브잎나무 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2581] = {title = "칼송곳니하이에나 턱", objective = "혈법사 드라지알에게 칼송곳니하이에나 턱 3개, 손상된 멧돼지 허파 2개, 스콜포크 집게발 1개를 가져가야 합니다.", description = "하이에나 턱이 엄청나게 강하다는 것은 누구나 알고 있는 사실이지. 그런데 두께가 한 뼘이나 되는 토륨 강철도 물어뜯을 수 있다면? 거짓말처럼 들리겠지만 내가 이 두 눈으로 직접 봤소이다.\n\n저주받은 땅으로 가서 칼송곳니하이에나 턱 3개를 가지고 오시오. 그리고 눈을 크게 뜨고 멧돼지와 스콜포크도 잘 찾아보시오. 첫 가루약에는 손상된 멧돼지 허파 2개와 스콜포크 집게발 1개도 필요하니까 말이오.", progress = "냄새가 지독하군. 멧돼지 우리에라도 빠졌다 나온 거요? 부탁한 재료는 어디 있소?!", completion = "그래... 야수를 무찌른 기분이 어떻소? 당신 주위에 칼송곳니하이에나의 오라가 빛나는군. 당신의 힘은 어떤 평범한 생명체와도 비교할 수 없소!\n\n한데 유감스럽게도 당신이 구한 재료로는 알약 하나밖에 못 만들겠군. 알약이 더 필요하면 재료를 더 가져와야 하오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n시대의 분노\n\n다음과 같은 것들을 받습니다:\n\n근육 촉진제"},
[2582] = {title = "시대의 분노", objective = "혈법사 드라지알에게 칼송곳니하이에나 턱 3개, 손상된 멧돼지 허파 2개, 스콜포크 집게발 1개를 가져가야 합니다.", description = "아, <name>. 잘 돌아왔소. 칼송곳니하이에나에게서 얻은 엄청난 힘이 꽤나 즐거웠나 보군. 당장은 힘이 솟아나는 효과를 볼 수 있지만 장기적으로는 당신의 영혼과 지능에 치명적인 효과를 미칠 수 있소. 그러니 조심하시오.\n\n분명 그 힘이 위험하다고 경고했는데도 또 얻고 싶단 말이오? 어쩔 수 없지... 다시 가서 칼송곳니하이에나 턱 3개와 손상된 멧돼지 허파 2개, 그리고 스콜포크 집게발 1개를 구해 오시오.", progress = "짐승 내장은 가져왔소?", completion = "여기 있소... 단, 아껴서 사용하도록 하시오. 지금 가진 걸 다 쓰고 난 다음 더 필요하다면 언제든지 날 다시 찾아 오시오.", rewards = "다음과 같은 것들을 받습니다:\n\n근육 촉진제"},
[2583] = {title = "멧돼지의 생명력", objective = "혈법사 드라지알에게 손상된 멧돼지 허파 3개, 스콜포크 집게발 2개, 바실리스크 뇌 1개를 가져다주어야 합니다.", description = "이 저주받은 땅에는 두 종류의 멧돼지가 살고 있소. 잿빛갈기멧돼지와 지옥멧돼지...\n\n이 야수들은 체력이 너무 강해 아무리 공격해도 상처 하나 입지 않을 정도요. 그래서 다른 짐승들은 이들을 상대할 수 없다고 느끼고 감히 덤비지조차 못하고 있소.\n\n이 멧돼지들을 더 분석해 봐야겠소. <name>, 당신의 도움이 필요하오. 내게 손상된 멧돼지 허파 3개와 스콜포크 집게발 2개, 바실리스크 뇌 1개를 가져다주시오. 그걸 분석한 다음 남은 걸로 신성한 비약을 만들어주리다. 그러니까, 당신이 나의 첫 실험 대상이 되는 거지!", progress = "내가 청한 것들은 가져왔소!?", completion = "멧돼지의 영혼이 당신을 비추고 있소! 혹시 당신 자신이 그 야수들만큼 강하다고 믿는 건 아니오?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n곰의 기백\n\n다음과 같은 것들을 받습니다:\n\n허파즙 칵테일"},
[2584] = {title = "멧돼지의 혼", objective = "혈법사 드라지알에게 손상된 멧돼지 허파 3개, 스콜포크 집게발 2개, 바실리스크 뇌 1개를 가져가야 합니다.", description = "내가 이 비약을 당신에게 처음 줬을 때부터 한두 개로는 당신의 욕심을 채울 수 없다는 것을 느꼈소. 지금도 당신의 두 눈에 굶주림의 빛이 역력하오. 이 약은 중독성이 아주 강해서 아무리 정신력이 강한 자라고 해도 이겨낼 수 없소.\n\n당신에겐 허파즙 칵테일이 더 필요한 것 같군. 그러니 다시 저주받은 땅으로 돌아가 손상된 멧돼지 허파 3개, 스콜포크 집게발 2개, 바실리스크 뇌 1개를 구해 오시오.", progress = "내가 말한 내장들은 어디 있소!?", completion = "경고하는데... 내가 조제해준 약들을 함부로 섞어서 복용하지 마시오. 최근 당신이 복용한 약들은 화학적 성분이 너무 강해서, 다른 약의 효력을 모두 사라지게 만들 테니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n허파즙 칵테일"},
[2585] = {title = "민첩한 스콜포크", objective = "혈법사 드라지알에게 스콜포크 집게발 3개, 독수리 모래주머니 2개, 손상된 멧돼지 허파 1개를 가져가야 합니다.", description = "녀석들이 싸우는 모습을 본 적 있소? 스콜포크 말이오. 나비처럼 우아한 자태로 날렵하게 움직이고 벌처럼 과감하게 공격하는 모습을 본 적이 있느냔 말이오.\n\n그 민첩성을 추출해 알약으로 정제할 수만 있다면 우린 떼돈을... 아! 그러니까... 과학사에 큰 업적을 이룰 거란 말이지.\n\n그러려면 그 약의 견본부터 만들어야 하는데... 용맹스런 <race>|1이여;여;, 날 좀 도와주시오.\n\n쓸만한 견본을 만들려면 스콜포크 집게발 3개, 독수리 모래주머니 2개, 손상된 멧돼지 허파 1개가 필요하오.", progress = "부탁한 내장들은 가지고 왔소?", completion = "아주 흥미롭군. 이 약은 지금껏 조제해 온 중 가장 까다로웠소.\n\n여기 이 가루약을 조금 집어서 혀 밑에 넣어보시오. 기분이 좋아지는 게 느껴지면 확실히 몸이 민첩해질 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n스콜포크의 충격\n\n다음과 같은 것들을 받습니다:\n\n스콜포크 가루약"},
[2586] = {title = "스콜포크의 가루약", objective = "혈법사 드라지알에게 스콜포크 집게발 3개, 독수리 모래주머니 2개, 손상된 멧돼지 허파 1개를 가져가야 합니다.", description = "살아 있었소?! 이거야말로 경사로군. 스콜포크 가루약을 더 받으러 온 거겠지?\n\n좋소, 저주받은 땅으로 다시 가서 스콜포크 집게발 3개, 독수리 모래주머니 2개, 손상된 멧돼지 허파 1개를 구해 가져오시오.", progress = "내가 말한 내장은 구해 왔소!?", completion = "잘했소. 여기 가루약을 하나 주겠소. 나머지 아홉 개는 내 연구에 쓸 거요.\n\n스콜포크 가루약이 더 필요하면 언제라도 내게 오시오. 서로 돕고 사는 게 좋지 않겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n스콜포크 가루약"},
[2601] = {title = "바실리스크의 내장", objective = "혈법사 린노어에게 바실리스크 뇌 10개와 독수리 모래주머니 2개를 가져가야 합니다.", description = "이 황무지는 붉은바위 바실리스크 때문에 온통 벌집투성이가 되었습니다. 이 바실리스크는 이 지역에 서식하는 다른 어떤 야생 생물보다 적응력이 강해서 그 수가 많이 늘었어요.\n\n먼 곳에서 녀석들이 사냥하고, 생활하는 모습을 지켜본 적이 있습니다. 놀랍게도 이 짐승들은 일부 인간형 생물보다도 높은 수준의 사고 과정을 보이더군요.\n\n꼭 녀석들의 뇌를 조사해봐야겠습니다!\n\n용맹스러운 <class>|1이여;여;, 녀석들의 뇌 10개를 가져다주세요. 그리고 물약의 기본 재료가 되는 독수리 모래주머니 두 개가 있어야 혼합물을 완성할 수 있으니 잊지 마십시오.", progress = "제가 부탁한 내장들은 가지고 왔습니까?", completion = "제대로 챙겨 오셨군요! 이제 보답으로 붉은바위 바실리스크의 내장을 맛보게 해드리죠.\n\n제가 드린 혼합물이 마음에 들면 언제라도 더 만들어 드릴 테니 들러주십시오. 단 공짜는 아니랍니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n확고한 신념\n\n다음과 같은 것들을 받습니다:\n\n대뇌 피질 혼합물"},
[2602] = {title = "흔들리지 않는 정신", objective = "혈법사 린노어에게 바실리스크 뇌 10개와 독수리 모래주머니 2개를 가져가야 합니다.", description = "아니, 벌써 집중력이 떨어지셨나요? 아직 연구에 필요한 재료를 더 구해야 해요!\n\n아, 수고하신 대가는 물론 똑같이 드려야죠. 저주받은 땅으로 가서 붉은바위 바실리스크 뇌 열 개와 독수리 모래주머니 두 개를 가지고 오세요.", progress = "제가 부탁한 내장들은 가지고 왔나요?", completion = "&lt;name&gt;, 이제 됐어요. 잠시만 기다리면 물약을 더 많이 만들어 줄 수 있어요.\n\n여기 받으세요. 그런데 이 실험용 물약을 너무 빨리 연달아 마시려고 하지 마세요. 아주 끔찍한 결과를 가져올 수도 있으니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n대뇌 피질 혼합물"},
[2603] = {title = "독수리의 면역력", objective = "혈법사 린노어에게 독수리 모래주머니 10개와 칼송곳니하이에나 턱 2개를 가져가야 합니다.", description = "이 저주받은 땅에서는 정말 죽음이 날개라도 돋친 듯 활개를 치죠. 저는 검은 독수리들이 잔치라도 하듯 죽은 모험가의 시체에 모여 살점을 뜯고 뼈를 쪼아대는 것을 보아왔죠. 때로는 심하게 부패하고 질병으로 뒤덮인 시체를 먹는 것도 보았고요. 그렇기 때문에 녀석들의 내부 기관이 어떻게 이 땅을 뒤덮고 있는 질병을 견딜 수 있는지 궁금할 수밖에 없답니다.\n\n용맹스런 <race>|1이여;여;, 절 도와주세요!! 제 연구에는 모래주머니가 필요해요! 물약의 기본 재료인 칼송곳니하이에나 턱도 두 개 있어야 해요.\n\n부탁한 물건을 가져오면 두 배로 보답해 드리겠어요.", progress = "제 시간을 뺏지 마세요. 연구할 시간도 부족하답니다. 제가 부탁한 물건을 가지고 올 때까지는 아무 할 말도 없어요.", completion = "아주 훌륭해요! 지금 당장 일을 시작할 수 있겠군요. 어쩌면 이 세계의 수많은 질병을 치료할 수 있는 길이 열릴 지도 모르겠어요!\n\n아참, 사례로 이걸 받아주세요. 더 필요하면 언제든지 찾아오세요. 임무를 더 드리겠어요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n정신의 통제\n\n다음과 같은 것들을 받습니다:\n\n모래주머니 껌"},
[2604] = {title = "영적 지배", objective = "혈법사 린노어에게 독수리 모래주머니 10개와 칼송곳니하이에나 턱 2개를 가져가야 합니다.", description = "당신의 내면의 열정이 꺼져가는 것 같군요. 정신적인 행복감이 한 시간 정도 지속됐다고 했나요?\n\n모래주머니 껌을 더 갖고 싶으시면 모래주머니를 가져다주셔야 해요. 다시 저주받은 땅으로 가세요. 그리고 모래주머니 열 개와 턱 두 개를 찾아 오세요.", progress = "제 시간을 뺏지 마세요. 연구할 시간도 부족하답니다. 제가 부탁한 물건을 가지고 올 때까지는 아무런 할 말도 없습니다.", completion = "언젠가 이 약에서 활성 효소를 분리해 더 강력한 약을 만들어낼 수 있을지도 모르겠군요. 유감스럽게도 지금은 일단 제가 만들 수 있는 것으로 만족하셔야겠어요. 모래주머니 껌이 더 필요하면 절 다시 찾아오세요.", rewards = "다음과 같은 것들을 받습니다:\n\n모래주머니 껌"},
[2605] = {title = "목마른 고블린", objective = "가득 찬 이슬샘을 모아 가젯잔에 있는 마린 노겐포저에게 가져가야 합니다.", description = "나에게 좋은 생각이 하나 있소. 여기서 남서쪽에 이슬먹는 덤불나무괴물이라는 희한한 녀석들이 산다고 들었는데, 녀석들은 특이하게도 몸안의 샘에다 물을 저장할 수 있다는구먼.\n\n그 샘 하나만 있으면 이 끔찍한 갈증을 해소할 음료를 만들 수 있을 거요! 나를 도와주지 않겠소?\n\n선인장 주변을 찾아보시오. 그곳에서 이슬먹는 덤불나무괴물들을 찾을 수 있을 거요.", progress = "그래, 이슬먹는 덤불나무괴물들은 찾았소?", completion = "좋았어! 얼른 한 모금 축이게 이리 주시오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2606] = {title = "맛의 달인", objective = "마린 노겐포저가 가젯잔에 있는 스프링클과 대화할 것을 부탁했습니다.", description = "우웩! 무슨 맛이 이렇담! 이건 안 되겠는데...\n\n잠깐, 뭐라고 했소? 아, 알고 있소. 포기는 하지 말라는 거지. 그럼 좋소.\n\n보자... 아주 좋은 생각이 있소! 내 친구 스프링클에게 이걸 가져 가시오. 그녀는 아주 훌륭한 요리사인데, 가서 우리 사정을 얘기하고 도움이 필요하다고도 전해 주시오.\n\n그러니까, 맛이 그렇게 이상하면 적어도 뭔가 톡 쏘는 맛이라도 있어야지... 안 그렇소?", progress = "마린이 또 시작이군... 이건 또 뭐죠?", completion = "오해는 마세요. 마린은 좋은 사람이에요. 약간 괴짜이기는 하지만...\n\n분명 제 도움이 필요할 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2607] = {title = "잔질의 손길", objective = "병영 지하실에 있는 닥 믹실픽실과 대화해야 합니다.", description = "내가 기대했던 것보다 더 많은 정보를 가져온 것 같군. 분명 일이 이상하게 돌아가고 있네.\n\n아, 자네가 걸린 독의 해독제 말인가? 흠... 지하실로 내려가서 닥 믹실픽실과 이야기해 보게. 그 친구가 도와줄 수 있을지도 몰라.", progress = nil, completion = "식사 시간이군! 치즈는 탁자 위에 어서 가 보시오. 나가는 길에 오스본이 값을 지급할 거요.", rewards = nil},
[2608] = {title = "잔질의 손길", objective = "닥 믹실픽실에게 검사를 받으려면 \"/누워\"야 합니다. 믹실픽실은 원인도 모르는 병의 치료법을 어떻게 찾을 수 있을까요?", description = "아, 이런. 당신 안색이 꼭 죽을 상이군. 아니지... 송장은 많이 봐왔지만 당신 얼굴은 상태가 더 안 좋아 보이는데... 그러니까 당신은 귀신보고 놀래 쓰러진 얼굴이라고나 할까...?\n\n하하! 방금 내가 한 말 들었니, 노암? 그거 꼭좀 적어 두라고!\n\n*콜록* 에헴, 그러니까... 내가 당신을 도와주려면 피를 좀 뽑아야 하겠소. 걱정하지 마시오. 아주 쪼오금... 많이 아플 뿐이니까... 치료 받을 준비가 되거든 /누워 주시오.", progress = nil, completion = "내가 동료들과 의논을 해야겠으니 잠시만 기다리시오. 몽고메리 박사, 노암, 회의 시간이오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2609] = {title = "잔질의 손길", objective = "닥 믹실픽실에게 수수한 야생화, 가연 약병 1개, 청동관 1개, 그리고 밝은 황록색 비단 실타래 1개를 가져가야 합니다. '그것'은 저절로 낫지 않는 병인 것 같습니다.", description = "만장일치로 결론이 났소. 당신은 '그것'에 걸린 것 같소. 그것 말이오.\n\n다행히도, 내가 '그것'을 치료할 수 있소. 그러려면 필요한 게 몇 가지 있소이다. 수수한 야생화 한 묶음, 가연 약병 1개, 청동관 1개, 그리고 마지막으로 중요한 재료인 밝은 황록색 비단 실타래 1개라오. 올엠마가 날 위해 '최고급 실타래' 상점에 비단 실타래 하나를 남겨 뒀을 거요. 운하를 따라가다 보면 그 상점을 찾을 수 있을 거요.\n\n어서 서두르시오. 다 나을 때까지 아무도 건드리지 말도록 하시오. 아, 그리고 몽고메리 박사가 말하길 당신은 샤워를 좀 해야 한답디다. 내가 한 게 아니고 저 사람이 한 말이오.", progress = "'그것'을 치료하고 싶다면 그보다 더 열심히 노력해야 할 거요. 해독제를 만들 재료는 어디 있소?", completion = "내가 뭘 하고 있냐고? 내가 뭘 하고 있는 것처럼 보이오? 당신이 걸린 '그것'을 치료할 해료제를 연구하고 있지 않소? 나한테 화내지 마시오!\n\n몇 초만 더 기다리면 되오. 됐다! 음... 그러니까... 대단히 향기 좋은 약을 온몸에 뿌리기만 하면 아주 깨끗이 나을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n오 드 믹실픽실"},
[2621] = {title = "명예를 잃은 자", objective = "스토나드에 있는 파견사령관 루아그와 대화하십시오.", description = "지금 내게는 후회밖에 남지 않았소. 나의 잘못된 판단이 처참한 결과를 낳고 말았소. 명령을 기다렸어야 했소! 그랬다면 저주받은 땅에서 우리를 기다리고 있던 공포를 미리 알 수도 있었을 텐데! 아니면 다른 곳으로 파견됐을지도 모르지. 결국 내 잘못이었소. 모든 게 내 잘못이야.\n\n그렇기 때문에 나는 눈도 감지 못하고 여기에 서서 오지 않는 명령서를 기다리고 있소. 나는 꼭 알고싶소. 오지 않은 그 명령서도 받아야겠소.\n\n스토나드에 파견사령관 루아그란 자가 살고 있소. 그를 찾아 어떻게 된 일이었는지 알아봐주시오.", progress = nil, completion = "스랄님의 직속부대... 아직도 생생하게 그 이야기가 기억나는군.\n\n&lt;고개를 젓는 루아그&gt;\n\n그 부대가 당한 일은 참으로 끔찍했지. 부대가 참패하면서 호드는 최정예 군사 일부를 잃게 됐거든.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2622] = {title = "잃어버린 명령서", objective = "벤고르와 대화하십시오.", description = "명령서? 어째서 당신이 명령서를 찾는 거요?\n\n지금 뭘 모르고 하는 소리 같은데, 당연히 난 명령서를 보냈다고. 그런데 내가 보낸 전령들이 그만 잔인한 멀록의 습격을 받았단 말이오. 모두 죽고 딱 한 명만이 살아남았지. 그 꼴을 보면 살아남았다고 하기도 어렵긴 하지만... 말도 거의 못하고 걸을 수도 없는 데다, 음식도 관을 통해서 먹는다오. 그 명령서가 어떻게 되었는지 알고 싶으면 벤고르와 얘기해 보시오. 이 근처 어딘가에 있을 거요... 그리고 <name>, 쓸데없는 간섭 같은 건 그만두시오. 그러다 크게 당할 수가 있으니...", progress = nil, completion = "수... 수다... 쟁이 늪지멀...록...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2623] = {title = "수다쟁이 늪지멀록", objective = "대족장의 명령서를 회수해 호드 영웅의 넋에게 가져가야 합니다.", description = "파견사령관에게서 명령서를 받은 우리는 저주받은 땅...으로 가는 길에 습격을 당했소.\n\n멀록... 수많은 멀록들... 그 중 수다쟁이 늪지멀록이라는 녀석이 내 손에서 명령서를 낚아챘고 내 머리에 창... 동쪽... 동굴...\n\n<기절하는 벤고르>", progress = "명령서를 기다리고 있소.", completion = "내가 상상했던 것보다 훨씬 더 심각하군. 그렇게 섣불리 행동하지 않았더라면, 지금 내 부하들 열 아홉은 그 끔찍한 고통을 겪지 않아도 될 텐데... \n\n그들을 도와주시오, &lt;name&gt;! 육신이 없는 나는 아무것도 할 수 없소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2641] = {title = "스프링클의 비밀 재료", objective = "가젯잔에 있는 스프링클이 제비수염버섯을 하나 구해 가지고 올 것을 부탁했습니다.", description = "제가 꼬마였을 때는 언니가 요리를 도맡아 했었죠. 그런데 얼마나 맛이 없던지... 아예 먹을 수도 없는 음식도 있었어요. 저는 참다 못해 이른바 저만의 \"비밀\" 재료를 찾게 됐죠! 그걸 집어넣기만 하면 무엇이든지... 음, 정말 기절할 정도로 맛있어진다고요!\n\n그게 뭐냐고요? 바로 제비수염버섯이에요. 이 구역질나는 음료를 마실 만한 걸로 만들고 싶다면 동부 내륙지로 가서 작은 호수를 찾아보세요.\n\n참! 제비수염버섯은 물속에서만 자란다는 것도 기억하시고요.", progress = "제비수염버섯은 그 호수 속에서만 구할 수 있어요. 수영 잘하시나요?", completion = "바로 이거예요. 훌륭하군요! 정말 수고하셨어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2661] = {title = "마린에게 배달", objective = "스프링클이 가젯잔에 있는 마린 노겐포저에게 제비수염 가루를 가져가라고 부탁했습니다.", description = "여기 제비수염 가루를 받으세요. 마린에게 가져가서 나한테 고마워 하라고 전해 주세요! 이걸로 마린은 내게 큰 빚을 지게 된 거예요.", progress = "아, 드디어 돌아왔군. 뭘 가져온 게요?", completion = "제비수염 가루라고? 어디 한번 써 봅시다. 어쨌든 지금보다 더 나빠지진 않을 테니!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2662] = {title = "노겐포저의 비약", objective = "마린 노겐포저가 비약이 완성되길 잠시 기다렸다가 다시 말을 걸어 달라고 부탁했습니다.", description = "자, 이제 이 가루를 이슬에 섞겠소.\n\n잠시 후 다시 와주시오... 내가 멋진 노겐포저 비약을 완성할 테니까 말이오!", progress = nil, completion = "이걸 한 모금 마셔 보시오! 정말 환상적이오!!!\n\n분명 내가 해낼 줄 알았다니까... 아, 다시 한번 감사하오. 그런데 좀 옆으로 비키지 않겠소? 장사하는데 길을 막고 섰으면 어떡하자는 거요? 이 멋진 노겐포저의 비약을 팔아 난 백만장자가 될 거요, 백만장자!\n\n뭐라고요? 스프링클이 내가 자기한테 큰 빚을 진 거라고 했다고요? 그 친구, 농담하고는!", rewards = "다음과 같은 것들을 받습니다:\n\n노겐포저의 비약"},
[2681] = {title = "속박의 돌", objective = "라젤리크의 하수인 9명, 세바인의 하수인 3명, 알리스타즈의 하수인 3명, 그롤의 하수인 3명을 해방시킨 후, 호드 영웅의 넋에게 돌아가야 합니다. 돌 가까이 있지 않으면 임무에 실패하게 됩니다.", description = "당신 혼자 힘으로 라젤리크와 그 부하들을 상대한다는 것은 무리요.\n\n실력 있는 모험가들을 모아 우리 부하들을 끝이 없는 고통의 나락에서 해방시켜 주시오! 모두 18개의 돌을 부수어야만 하오.\n\n부디 용맹스럽게 싸우다 명예롭게 죽으시오.", progress = "쉬운 임무는 아닐 것이오. 하지만 절대 포기하지는 마시오!", completion = "해냈군! 영원한 고통 속에서 헤매던 불쌍한 영혼들이 이제야 편히 쉴 수 있겠구려.\n\n하지만 우리 임무는 아직 끝나지 않았소. 할 이야기도 많지만 그 전에 완수해야 할 일들이 훨씬 많이 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2701] = {title = "과거의 영웅", objective = "궤짝을 열고 보상을 받으십시오.", description = "자, 이 유물을 받으시오. 속세에서 멀어진 우리에겐 더 이상 쓸모가 없는 것이라오.\n\n부디 불타는 군단과의 싸움에서 도움이 되기를 바라겠소.", progress = nil, completion = "눈부신 광채에 잠시 앞이 보이지 않습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n갈래발굽 결정"},
[2702] = {title = "과거의 영웅", objective = "하사관 선드 스플릿후프와 대화하십시오.", description = "<race> 친구, 당신은 그 숭고함과 영웅심으로 나에게 명예를 다시 안겨 주었소.\n\n그리고 이제 저세상으로 간 그들의 명예도 되찾아 준 거요.", progress = nil, completion = "과연, 당신은 우리 모두의 명예를 되찾아 주었소. 말로만 감사하다고 해서는 부족하겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2721] = {title = "키리스", objective = "키리스 부관이 어떻게 되었는지 알아보십시오.", description = "모험의 장 하나가 막을 내리면서 또 다른 막이 오르고 있소.\n\n내 부하 한 명의 행방이 아직까지 묘연하오. 키리스 부관 말이지... 그는 저주받은 땅 어딘가에서 실종됐소.\n\n전에도 얘기했지만 우리 둘은 알리스타즈에게 붙잡혀 감옥에서 고문을 받았었소. 하지만 불쌍한 키리스는 결국 의지력을 잃고 말았지. 내가 갇혀 있던 곳까지 고문 하는 소리가 들렸소. 고통스러워하는 비명 소리가 동굴 전체를 울려퍼졌지. 그것이 내가 본 키리스의 마지막 모습이오.", progress = nil, completion = "트레보르? 트레보르가 보냈다고 했소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2741] = {title = "고성능 자동부화기", objective = "고성능 자동부화기는 커글 크랭크홉의 최신 발명품으로 상당히 멋진 기계입니다.\n\n고성능 자동부화기의 제어판에 다가가자 거친 소리가 납니다.", description = nil, progress = "고성능 자동부화기는 커글 크랭크홉의 최신 발명품으로 상당히 멋진 기계입니다.\n\n고성능 자동부화기의 제어판에 다가가자 거친 소리가 납니다.", completion = "히포그리프 알을 기계에 넣자 일련의 신호음과 함께 이상한 기계 소리가 들립니다.\n\n고성능 자동부화기가 알의 무게와 크기를 측정하고 포장을 한 것 같습니다. 정말 신속한 서비스로군요!", rewards = "다음과 같은 것들을 받습니다:\n\n알 상자"},
[2742] = {title = "갇혀 있는 린지", objective = "린지를 호위해 쿠엘다닐 오두막을 빠져나간 후 그가 동쪽에 전망대 절벽에 숨겨두었다는 비밀 물건을 찾아내십시오.", description = "거기 <race> 친구!\n\n린지가 도끼를 잃어버리고 여기 갇혔소. 제발 이곳을 빠져나가게 도와주시오. 당신 같은 <race>|1이;가; 우리 일족을 좋아하지 않는다는 건 알지만 이 린지가 이렇게 부탁하오! 여길 꼭 나가야 하오!\n\n린지를 도와주는 마음 착한 <race>한테는 꼭 보답하겠소.\n\n참, 그리고 나 린지가 전망대 절벽에 아무도 몰래 숨겨둔 것이 하나 있는데...", progress = nil, completion = "이 트롤 서판이 린지의 \"비밀\"이 틀림없습니다.\n\n서판에 이상한 표시가 뒤덮여 있어 내용을 판독할 수가 없습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2743] = {title = "어둠의 엄습", objective = "호드 영웅의 넋에게 돌아가서 키리스로부터 알아낸 정보를 보고해야 합니다.", description = "있는 사실 그대로 다 말하겠소. 시간이 없으니 바로 본론으로 들어가지.\n\n악마의 군주, 라젤리크를 보호하는 마력의 3인조를 물리쳐야 하오. 이건 저주받은 영혼 하나를 해방시키는 일처럼 쉬운 일은 아니오.\n\n<묘한 미소를 지어 보이는 키리스>\n\n라젤리크의 심복들은 라젤리크가 손수 만든 아뮬렛을 삼등분하여 하나씩 목에 두르고 있소. 이것들이 있어야 가장 사악한 악마를 소환할 수 있지.\n\n트레보르에게 돌아가서 라젤리크를 소환하는데 무엇이 필요한 지 말해주면 그가 더 자세히 얘기해줄 거요.", progress = nil, completion = "그 악마의 군주는 잔학하기도 하지만 그만큼 교활하기도 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2744] = {title = "악마사냥꾼", objective = "아즈샤라에 있는 로라무스 탈리뻬데스와 대화하십시오.", description = "그 3인조는 라젤리크의 보호를 받고 있소.\n\n라젤리크는 자신을 섬기는 대가로 그들에게 저주받은 땅에서 무한한 권한을 휘두를 수 있도록 해주었지. 아뮬렛 조각들이 그들에게 불멸의 힘을 주고 있소. 그 조각은 주인의 생명력에 맞게 조절되지. 맨몸으로 처치할 가능성은 거의 없소. 저주받은 땅에 머무르는 한 녀석들은 영원히 죽지 않기 때문이지... \n\n당신을 도와줄 만한 자가 하나 있긴 하오. 아즈샤라로 가서 악마사냥꾼, 로라무스 탈리뻬데스를 찾으시오. 섬을 뒤져보면 될 거요.", progress = "이곳엔 무슨 일로 왔는가?", completion = "도와주기야 하겠네만... 자네가 지금 도전할 상대가 누구인지나 알고 있나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2745] = {title = "성 잠입", objective = "스톰윈드 성에 있는 티리온과 대화해야 합니다.", description = "흠. 재미있는 얘기지만 가볍게 여겨서는 안 될 얘기로군요. 좋습니다, 당신을 도와드리도록 하지요. 그런데 당신이 해야 할 일은 정의로운 행동이지만, 그러니까... 합법적이지 못하게 정의를 실현하는 것입니다. 끝까지 해내려고 한다면 말입니다.\n\n라스코발과 마르존을 신속하게 처리해야 합니다. 할 수 있을 것 같습니까?\n\n자, 결정하시기 바랍니다. 이 일을 하시겠다면 서둘러 성으로 가서 내 오랜 노움 친구 티리온을 찾으시기 바랍니다. 그 친구는 지금 2주째 라스코발을 감시하고 있답니다. 그 친구라면 당신을 도와줄 수 있을 겁니다.", progress = nil, completion = "뭐지...?! 그렇게 몰래 접근하니까 놀랐잖아! 그리고 목소리 낮추라고! 도대체 무슨 속셈으로 그렇게 소리도 없이 다가오는 거지? 바쁜 거 안 보이나? 어리석은 친구 같으니라고.\n\n뭐하고 있느냐는 건 또 무슨 소리야? 다음 어둠의 문이 열리길 기다리는 중인데 내가 뭘 하는 것으로 보이나? 조용히 용건만 말하고 사라지라고. 경비병들이 수풀 속에 같이 숨어 있는 걸 알아채기 전에 말이야. 평판을 잃게 되면 곤란하다고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2746] = {title = "변장에 필요한 물건", objective = "스톰윈드에 있는 티리온에게 비단 옷감 3개와 클라라의 싱싱한 사과 2개를 가져가야 합니다.", description = "티리아스가 일을 더 빨리 진행하기를 원하는 거군? 좋아. 그렇게 하도록 하지. 하지만 난 아직 준비가 안 됐고 이건 알아두라고. 어려운 일은 내가 하겠지만 손을 더럽히는 일을 하는 건 당신이오. 알겠소? 좋아.\n\n자, 계획을 실행하기 전에 우선 당신이 가지고 와야 할 물건이 몇 가지 있지. 난 저 첩보로봇을 이용해 근위병을 지나갈 수 있을만한 완벽한 변장술의 대가요.\n\n비단이랑 사과 두 개를 가지고 오시오. 비단을 구하는 건 당신 몫이지만, 도시를 막 벗어나면 클라라의 조그만 농장이 있는데 그곳에 딱 알맞은 용도의 사과가 있다오.", progress = "난 2주째 라스코발을 지켜보고 있었소. 트리아스는 절대 라스코발 녀석을 믿지 않았지만, 우리는 녀석이 데피아즈 결사단과 관계가 있을 거라고는 생각해보지도 못했다오. 우리는 녀석과 황혼의망치단과의 관계에 대한 단서를 추적하고 있었거든. 어쨌든 녀석은 이 도시의 힘으로 처리할 수 없을 만큼 큰 위협이 되어버렸소. 바로 우리가 나서야 할 때지.\n\n필요한 물건들을 가져오면 내 계획을 실행하도록 하지.", completion = "이 정도면 쓸 만하겠어. 수고했소.\n\n나머지 필요한 도구는 내 가방에 들어있지. 재봉사 친구에게 비단 가방을 만들어 달라고 했는데 얼마나 잘한 일인지 모르겠단 말이야. 가방에 도구를 넣을 자리가 부족하던 참이었거든.\n\n자, 첩보로봇이 들어가기 전에 당신이 할 일이 무엇인지 알 수 있도록 정리를 해 보도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2747] = {title = "비범한 알", objective = "페랄라스에서 비범한 알을 구해오는 경우는 별로 보지 못했어요. 너무 희귀한 알이라서...", description = nil, progress = "페랄라스에서 비범한 알을 구해오는 경우는 별로 보지 못했어요. 너무 희귀한 알이라서...", completion = "맙소사, 하나 가져오셨네요. 놀랍군요!\n\n오늘 하신 일이 얼마나 놀라운 것인지 항상 기억하시길 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n귀중품 상자"},
[2748] = {title = "좋은 알", objective = "좋은 알이란 이상적인 조건에서 골두니 오우거의 나쁜 마법의 영향을 받지 않고 부화할 수 있는 알이랍니다.", description = nil, progress = "좋은 알이란 이상적인 조건에서 골두니 오우거의 나쁜 마법의 영향을 받지 않고 부화할 수 있는 알이랍니다.", completion = "잘 하셨어요. 이 알을 다르나서스로 보내서 얼른 부화시켜야겠어요!\n\n감사의 표시로 이걸 받아 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n두루마리 상자"},
[2749] = {title = "평범한 알", objective = "평범한 히포그리프 알은 절반 정도가 부화를 하죠. 우리가 최선을 다해 뒷바라지를 하고 운이 좋으면 부화를 하게 된답니다.", description = nil, progress = "평범한 히포그리프 알은 절반 정도가 부화를 하죠. 우리가 최선을 다해 뒷바라지를 하고 운이 좋으면 부화를 하게 된답니다.", completion = "평범한 알을 구해 오셨네요? 저한테 주세요... 이제 잘 부화되기만을 빌어야죠.\n\n제가 가진 건 별로 없지만 답례로 이걸 받아 주세요. 다시 페랄라스로 가실 일이 있거든 그곳에서 알들을 찾아보세요. 저는 항상 여기 있으니까 언제든지 가져 오세요.", rewards = "다음과 같은 것들을 받습니다:\n\n식량 상자"},
[2750] = {title = "상해버린 알", objective = "이 알은 되살릴 수 없습니다. 그러니까 절대 부화되지 않는단 말이죠.", description = nil, progress = "이 알은 되살릴 수 없습니다. 그러니까 절대 부화되지 않는단 말이죠.", completion = "이 알은 너무 상했군요. 원하신다면 뒤처리는 제가 해 드리겠습니다. 고생하셨는데 좋지 않은 소식이죠?\n\n너무 상심 마세요. 모든 알들을 부화시킬 수 있는 건 아니랍니다. 혹시 페랄라스에 가게 되거든 다시 알을 찾아 보세요. 다른 알을 가져오시면 고성능 자동부화기에 넣어 볼게요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2751] = {title = "야만전사의 갑옷", objective = "오그리마에 있는 오로크 오모쉬에게 청동 무늬 팔보호구 2개, 청동 대검 2개, 날카로운 발톱 2개를 가져다주어야 합니다.", description = "오모쉬 집안은 20대째 망치를 들어 왔소. 그동안 다듬은 금속만 해도 십만 톤이나 되지. 하지만 불행히도 이 오로크가 이 전통의 맥을 끊게 생겼다오. 나는 오모쉬 집안의 수치요. 친척도 없는데다 자식을 낳지도 못했거든.\n\n오모쉬 집안의 비법을 내 죽음과 함께 사라지게 할 수는 없소! 이 유산은 오모쉬 집안 사람이든 아니든 누군가 계속 이어가야 하오!\n\n당신이 할 수 있다는 것을 이 오로크에게 증명해 주시오. 청동 무늬 팔보호구 2개, 청동 대검 2개, 날카로운 발톱 2개를 이 오로크에게 가져오시오. 얘기는 그 다음에 계속하겠소.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n도면: 야만전사의 철제 흉갑"},
[2752] = {title = "강철 어깨갑옷", objective = "오그리마에 있는 오로크 오모쉬에게 청동 전투도끼 4개와 청동 전투해머 4개를 가져다주어야 합니다.", description = "당신 눈에는 열의가 있어 보이는군. 마치 화선지가 먹물을 빨아들이듯이 오모쉬 집안의 지혜를 흡수하고 있어.\n\n앞으로 세 가지를 더 가르쳐줄 것이오!\n\n모루로 돌아가 청동 전투도끼 4개와 청동 전투해머 4개를 만들어 이 오로크에게 가져오시오. 가열로의 뜨거운 열기 때문에 살이 익는 것처럼 느껴지겠지만 강철 어깨갑옷 만드는 법을 배우려면 꼭 구해와야 하오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n도면: 야만전사의 철제 어깨보호구"},
[2753] = {title = "발 밑의 적", objective = "오그리마에 있는 오로크 오모쉬에게 녹색 철제 투구 4개, 녹색 철제 팔보호구 4개, 녹색 철제 다리보호구 2개를 가져다주어야 합니다.", description = "이제 두 가지만 더 가르쳐 주면 되오. 온몸이 쑤시는 것은 알겠지만 이 오모쉬 집안을 위해서 조금만 더 참아주시오!\n\n이 오로크에게 녹색 철제 투구 4개, 녹색 철제 팔보호구 4개, 녹색 철제 다리보호구 2개를 가져오시오. 그러면 당신은 실력이 늘 것이고 당신의 적은 고통 받게 될 것이오!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n도면: 야만전사의 철제 장화"},
[2754] = {title = "광란의 뿔", objective = "오그리마에 있는 오로크 오모쉬에게 튼튼한 철제 마울 2개, 은도금한 청동 장화 2개, 그리고 은도금한 청동 장갑 2개를 가져다주어야 합니다.", description = "이제 한 가지만 더 가르쳐주면 되겠군. 성스러운 모루와 괴철로로 돌아가는 거요! 그리고 이 오로크에게 튼튼한 철제 마울 2개, 은도금한 청동 장화 2개, 은도금한 청동 건틀릿 2개를 가져오시오.\n\n당신이 접근하면 그들의 눈에 공포가 서릴 것이오!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n도면: 야만전사의 철제 투구"},
[2755] = {title = "오모쉬의 기쁨", objective = "오모쉬가 추는 기쁨의 춤을 보고 배워야 합니다.", description = "이 오로크는 우는 게 아니오. 눈에 먼지가 들어갔을 뿐.\n\n<눈물을 훔쳐내는 오로크>\n\n이 오로크가 당신에게 가르쳐줄 오모쉬 집안의 마지막 비밀이 하나 남았소. 덕분에 이 오로크 행복하게 눈을 감을 수 있겠소.\n\n오모쉬 집안에 대대로 내려오는 기쁨의 춤을 따라하면 철제 장갑을 만드는 법을 가르쳐 주리다!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n도면: 야만전사의 철제 장갑"},
[2756] = {title = "과거의 방식", objective = "오그리마에 있는 무쇠모루 아투르크에게 강철 흉갑 4개와 강철 판금 투구 4개를 가져다주어야 합니다.", description = "전설의 시대에 이 아투르크는 적의 두개골을 박살내고 뼈를 잘게 빻아 가는 실을 만드는 데 쓰곤 했지. 이제는 모두 옛날 얘기가 되어 버렸지만 말이야. 대족장님께서는 부족 간의 평화를 천명하시고 이제는 지친 눈으로 오래된 적을 바라보실 뿐이지!\n\n믿기 힘들다는 건 나도 알지만 스랄님의 뜻이 그런 걸 어쩌겠나.\n\n넋두리는 이제 그만 하세. 자네가 여기 온 목적은 뭔가 배우러 온 거겠지? 꼭 그렇게 될 걸세... 그전에 내게 강철 흉갑 4개와 강철 투구 4개를 가져다주게. 자네에게 전쟁을 맛보게 해주지!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n오크족 전투 다리보호구\n\n다음과 같은 것들을 받습니다:\n\n"},
[2757] = {title = "무법항으로!", objective = "무법항에 있는 맥개번과 대화하십시오.", description = "이봐, 여기서 어슬렁대봤자 얻을 건 아무것도 없다니까.\n\n내가 어떤 녀석을 아는데 발이 꽤나 넓은 놈이지. 지금쯤 무법항의 대장간 주위를 돌아다니고 있을 거야. 가서 이 배지를 보여주면 미스릴에 대해 모두 말해줄 거야.\n\n그런 애들 물건은 기저귀 찬 아가들에게나 줘버리라고. 이제는 더 큰 물에서 놀아야지. 어쩔 텐가?\n\n혹시 생각이 있으면 맥개번을 찾아봐. 그에게 이 표장을 보여주면 누가 보냈는지 알아볼 거야.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2758] = {title = "대장기술의 근원", objective = "스톰윈드에 있는 쇠망치 행크에게 황금 미늘 팔보호구 6개를 가져가야 합니다.", description = "내가 당신 나이 정도였을 때 드워프이신 갈반께서 나를 수하에 데리고 있으면서 방어구 제작의 도를 가르쳤지. 그분은 무법항으로 떠나기 전에 날더러 대장기술 솜씨를 향상시키려는 야망과 결단력을 갖춘 모든 이들을 가르치겠다는 약속을 하게 하셨소. 그래서 오랜 세월이 지난 지금도 이러고 있는 것이지.\n\n그래, 이제는 당신이 배워야 할 때로군. 황금 미늘 팔보호구 6개를 만들어 오면 대장기술의 근원에 대해 가르쳐 주겠소.", progress = "당신이 갈반님의 다음 수련생이 될 자격이 있겠소?", completion = "아주 잘했소! 그럼, 잘 듣고 배우시오.\n\n&lt;자신의 망치를 가리키며&gt; 대장기술은 여기서 나오는 게 아니오! &lt;모루를 가리키며&gt; 여기서 나오는 것도 아니라오!\n\n&lt;자신의 가슴을 가리키며&gt;대장기술은 바로 여기서 우러나오는 것이오! 이제 당신은 대장기술의 근원을 깨달은 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n도면: 황금 미늘 건틀릿"},
[2759] = {title = "갈반을 찾아서", objective = "무법항에 있는 맥개번과 대화해야 합니다.", description = "갈반님께서 무법항을 떠난 지는 오래되었지만 아직도 그의 동료가 마을에 남아 있소. 언젠가 갈반의 지도를 받을 만한 이가 나타날 것을 기다리면서 말이지.\n\n이 미스릴 표장을 가지고 가서 무법항에 있는 맥개번에게 보여 주시오.\n\n그곳까지 간 것만으로도 당신이 자격이 있다는 걸 알 거요. 난 당신을 믿소!", progress = "이보라고 친구, 이 부근에서는 당신 같은 부류를 보기 어려운데 말이야. 어디 그 표장을 한번 보여 주시오.", completion = "이런, 맙소사! 드디어 미스릴 대장조합에 들어올 만한 자격이 있는 자가 왔군그래!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2760] = {title = "미스릴 대장조합", objective = "가시덤불 골짜기에 있는 전설의 대장장이 갈반과 대화해야 합니다.", description = "무법항까지 오는 데 성공하는 신참들은 그리 많지 않소. 그 표장의 광채를 보면 아무리 착실한 대장장이라도 욕심이 생기게 마련이지. 어리석은지고... 그 표장 따위는 앞으로 보게 될 물건에 비하면 아무것도 아닌데!\n\n전설의 대장장이, 갈반님을 찾아가 이 펜던트를 보여주시오. 그분은 여기서 한참 북쪽으로 줄구룹과 모쉬오그 오우거 소굴 사이에서 지내고 계신다오.", progress = "어서 오게! 좀 더 가까이 오게나. 이 갈반에게 자네가 뭘 가져왔는지 보여주게.", completion = "미스릴 대장조합에 입문할 자격이 있는 자를 만난 게 실로 몇 년만인지 모르겠군. 당장 시작하세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2761] = {title = "대장기술과 채광", objective = "가시덤불 골짜기에 있는 전설의 대장장이 갈반에게 미스릴 주괴와 철 주괴를 각각 40개씩 가져가야 합니다.", description = "많은 대장장이들이 채광과 대장기술은 상관없는 일이라고 생각하지. 하지만 채광 없이 대장기술이 있을 수 있겠는가? 그렇지, 불가능한 일이지! 솜씨 좋은 대장장이는 기술 좋은 광부도 돼야 하는 법...\n\n자네라면 해낼 수 있다는 것을 이 갈반에게 보여주게나. 철 주괴 40개와 미스릴 주괴 40개를 가져오면 이 갈반이 화려한 미스릴 바지의 제작 방법을 가르쳐 주지!", progress = "그렇게 채광을 하고 나면 근육이 땡기고 몸이 쑤실 거야!", completion = "자네의 작업에는 흠잡을 곳이 없군! 이제 갈반의 광물학을 이해하기 시작하는 게야! 자, 이걸 받고 자네가 할 수 있는 한 최대한 익히도록 하게.", rewards = "다음과 같은 것들을 받습니다:\n\n도면: 화려한 미스릴 바지"},
[2762] = {title = "훌륭한 가짜배기 은", objective = "가시덤불 골짜기에 있는 전설의 대장장이 갈반에게 미스릴 주괴 40개와 진은 주괴 5개를 가져가야 합니다.", description = "진은은 미스릴보다도 더 강하고 튼튼하다고들 하지. 이 갈반도 광물에 대한 이러한 분석에는 반대하지 않네. 하지만 진은은 이름과는 달리 진정한 것이 아니라네! 미스릴이 훨씬 더 고귀한 광물이지! 하! 그거야 어쨌든, 이번 수업을 받으려면 그 훌륭한 가짜배기 은을 가져와야 한다네.\n\n내게 미스릴 주괴 40개와 진은 주괴 5개를 가져오게. 그걸 가져오면 화려한 미스릴 장갑의 비밀을 배우게 되거니와 진은이 가짜배기라는 것을 배우게 될 것일세!", progress = "그렇게 채광을 하고 나면 근육이 부풀고 몸이 쑤실 거야!", completion = "아주 잔인하지 않은가? 물론, 진은 말일세. 그래, 이 갈반도 알터랙 산맥에서 10년이 넘게 걸려 이걸 배웠다네. 이걸 받고 배울 수 있는데까지 최대한 익히도록 하게나!", rewards = "다음과 같은 것들을 받습니다:\n\n도면: 화려한 미스릴 장갑"},
[2763] = {title = "보석 채취", objective = "가시덤불 골짜기에 있는 전설의 대장장이 갈반에게 미스릴 주괴 40개와 황수정 4개를 가져가야 합니다.", description = "귀한 보석을 채취하는 것은 우리 작업에서 가장 중요한 일이라네. 황수정보다 더 귀한 보석은 몇 되지 않지. 우리가 만든 물건들에 부여하는 마법 속성은 이 황수정이 있을 때 크게 증폭된다네.\n\n이 수업을 위해서는 미스릴 주괴 40개와 황수정 4개가 필요하네. 이 수업을 받고 나면 마법 보석학을 더 잘 이해하고 화려한 미스릴 어깨보호구를 만드는 방법을 알게 될 거야.", progress = "그렇게 채광을 하고 나면 근육이 부풀고 몸이 쑤실 거야!", completion = "이 화려함에서 눈을 떼기란 무척이나 힘든 일이지. 그래, 황수정은 영광의 보석이야.\n\n잘 보고 이러한 발견이 우리에게 가르쳐 주는 것을 배우도록 하게나!", rewards = "다음과 같은 것들을 받습니다:\n\n도면: 화려한 미스릴 어깨보호구"},
[2764] = {title = "갈반의 수제자", objective = "가젯잔에 있는 트렌튼 라이트해머와 대화해야 합니다.", description = "이 갈반과의 수업을 마칠 준비가 되었으면 가젯잔으로 가게나.\n\n그곳에서 내 수제자, 트렌튼 라이트해머를 찾을 수 있을 걸세. 그 녀석이 화려한 미스릴의 도에 대해 많은 것을 가르쳐줄 게야. 아니면, 여기 남아서 배우든지!\n\n참, 물론 가젯잔은 타나리스에 있다네!", progress = nil, completion = "전설의 대장장이 갈반님께서 보내셨다고??\n\n&lt;허리 숙여 인사하며&gt;\n\n스승님의 또 다른 제자를 만나는 것은 큰 영광이지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2765] = {title = "고급 대장기술", objective = "전설의 대장장이 갈반에게서 보상을 받으십시오.", description = "자네가 내게 처음 왔을 때 나는 자네가 내 최고의 제자 중 하나가 될 줄 알아봤다네! 자네는 주저하지 않고 맥개번에게 마법 장신구를 내주었고, 그것도 단지 나를 만나기 위해서 그런 것이니 말일세. 대장기술에 대한 그런 맹목적인 믿음과 헌신은 보상을 받아야 마땅하지.\n\n자네는 고급 대장기술을 터득했네. 자, 보상을 받게나!", progress = nil, completion = "여기에 오기 위해서 써버린 장신구보다는 훨씬 더 강력한 걸 받아야 마땅하지. 잘 쓰도록 하게.", rewards = "다음과 같은 것들을 받습니다:\n\n전문 기술의 인장"},
[2766] = {title = "OOX-22/FE 수색", objective = "거친흉터 골짜기에 있는 오글소프의 유도 로봇에게 조난 탐지기를 가져가야 합니다.", description = "금속으로 만들어진 이상한 알 모양의 장치를 찾았습니다. 손잡이 하나를 만지작거리다 보니 알이 작동하면서 노움 로봇 장치로 변합니다! 로봇 알 속에서 소음과 함께 목소리가 들려옵니다.\n\n\"나는 오글소프 오브노티쿠스라고 하오, 내 유도 로봇이 불시착을 했는데 로봇을 찾아주면 사례를 하겠소. 이 탐지기를 로봇에게 가져가 주시오!\"\n\n\"방금 로봇의 현재 위치를 산출해 봤는데 거친흉터 골짜기 근처의 동굴에 있소!\"", progress = "로봇의 잔해를 찾은 것 같은데 모양을 보니... 닭 로봇입니다. 알 속에서 다시 목소리가 들려옵니다.\n\n\"옳지. 잘했소! 그것이 바로 내 유도 로봇이오. 다시 무법항으로 가져와 수리를 하려면 급속 시동을 걸어야 할 것 같소. 이 탐지기를 로봇에 넣으시오. 나머지는 탐지기가 알아서 할 거요!\"", completion = "알을... 아니 조난 탐지기를 닭... 아니 유도 로봇에 넣습니다.\n\n로봇이 윙윙거리는 소리를 내면서 일어서려고 합니다. 로봇이 작동을 하자 오글소프의 목소리가 다시 들려오는데 이번에는 로봇에서 납니다.\n\n\"OOX-22/FE가 작동하긴 하지만 큰 수리를 해야 할 것 같소! 당신이 들고 오기에는 너무 무겁지만... 좋은 생각이 한 가지 있소. 잠시만 더 로봇을 봐주지 않겠소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2767] = {title = "OOX-22/FE 구출!", objective = "잊혀진 해안에 있는 부두까지 OOX-22/FE를 호위해 간 후 무법항에 있는 오글소프 오브노티쿠스에게 보고해야 합니다.", description = "로봇에서 다시 노움의 목소리가 흘러나옵니다.\n\n\"긴 활주로로 사용할 수 있을 만한 넓고 안전한 장소로 OOX-22/FE를 옮겨야겠소. 로봇에 위장 기능이 있기는 하지만 다시 작동하려면 시간이 필요하오. 그 로봇을 현재 있는 곳에서 잊혀진 해안에 있는 부두까지 호위해주시오. 그곳이라면 이륙하기에 충분할 거요!\"\n\n\"부두까지 무사히 호위해 간 후에 무법항으로 와서 나에게 알려 주시오! 오글소프 오브노티쿠스, 이상!\"", progress = nil, completion = "아, 당신이 OOX-22/FE의 구세주였군! 당신이 도와 줘서 얼마나 고마운지 이루 말할 수가 없소! 내 유도 로봇 시리즈는 아직 개발을 더 해야 하는데 당신이 회수해 준 덕분에 제작 비용은 물론이고 추가 제작 시간도 많이 벌게 됐소이다!\n\n자, 내가 가진 이 물건 중 아무거나 고르시오. 다시 한번 도와 줘서 고맙소이다. 나와 내 로봇이 당신에게 큰 신세를 졌소!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n실패한 비행 실험 장치쇠사슬 수건\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2768] = {title = "자동 탐사막대", objective = "가젯잔에 있는 선임기술자 빌지위즐에게 자동 탐사막대를 가져가야 합니다.", description = "하사관 블라이가 내가 아끼는 물건을 훔쳐갔소! 처음엔 빌려간다고 해놓고는 내 자동 탐사막대를 아예 훔쳐가 버린 거요!! 그 막대가 없으면 어떻게 새로운 위치를 찾아서 우물을 팔 수 있겠소?!\n\n블라이를 찾아서 내 막대를 되찾아 주시오! 듣기로는 평판이 좋지 않은 일단의 모험가들을 이끌고 서쪽에 있는 줄파락으로 보물을 찾으러 갔다고 하오. 분명 거기서 블라이를 찾을 수 있을 거요.\n\n이미 트롤들이 녀석을 처치했다면 좋겠군... 막대를 쉽게 되찾을 수 있을 테니... 직접 싸워야 한다면 분명 아주 큰 싸움이 벌어질 거요.", progress = "하사관 블라이는 찾았소? 내 자동 탐사막대는 가져왔고?", completion = "찾았군! 정말 수고했소. 이걸 찾으려고 블라이와 싸웠소? 그랬다면 그 무리에게 제대로 본때를 보여줬길 바라오!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n석공 조합 반지기술자 조합 모자\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2769] = {title = "브라스볼츠 형제", objective = "소금 평원에 있는 위즐 브라스볼츠와 대화하십시오.", description = "브라스볼츠 형제를 만나 보셨나요? 칼림도어의 소금 평원에서 고블린들과 로켓 자동차 경주를 하면서 지내는데, 늘 그들 형제가 이긴답니다. 그리 놀랄 만한 일도 아닌 게 고블린 로켓 자동차는 워낙 폭발이 잦아서 결승선까지 가는 일이 드물거든요!\n\n하지만 그렇다 해도 브라스볼츠 형제는 늘 자기들 로켓 자동차를 더 빨리 달리게 할 방법을 연구하고 있죠. 위즐 말로는 아주 희귀한 부품이 필요하다고 하더군요.\n\n틀림없이 당신의 도움이 필요할 거예요. 위즐에게 가서 알아보세요.", progress = nil, completion = "아, 날 돕겠다고? 그것 참 반가운 소리요!\n\n내가 지금 하고 있는 실험에 필요한 부품이 하나 있는데 당신처럼 용감한 &lt;class&gt;의 도움이 필요하오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2770] = {title = "가즈릴라", objective = "소금 평원에 있는 위즐 브라스볼츠에게 가즈릴라의 전기 비늘을 가져가야 합니다.", description = "타나리스에는 줄파락이라고 하는 트롤들의 모래 도시가 있소. 깊숙이 들어가면 신성한 웅덩이가 하나 있소. 트롤 녀석들은 이 웅덩이에서 커다란 괴물을 소환한다오! 가즈릴라! 이 광포한 녀석은 비늘조차도 에너지가 넘쳐 흐른다오. 바로 그 힘을 내 차에 이용하고 싶소!\n\n가즈릴라의 전기 비늘을 가져와 주시오!\n\n가즈릴라를 소환하는 법은 트롤이 철저히 비밀로 지키고 있으니 녀석과 맞서려면 먼저 트롤에게서 비밀을 캐내야 할 거요.", progress = "비늘은 가져왔소? 어서 빨리 그 에너지를 여러 가지 방법으로 이용해 보고 싶소!", completion = "정말로 비늘을 가져왔군! 고맙소, &lt;name&gt;. 지금 당장 시작해 보고 싶군!\n\n그래, 가즈릴라는 직접 봤소? 소문대로 그렇게 덩치가 큽디까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n당근 달린 지팡이"},
[2771] = {title = "지혜로운 스승", objective = "트렌튼 라이트해머에게 미스릴 코이프 2개와 화려한 미스릴 어깨보호구 1개를 가져가야 합니다.", description = "마치 스승님께서는 처음부터 계획이 있으셨던 것 같구먼. 자네가 배운 것은 내가 배우지 않았고 내가 배운 것은 자네가 배우지 않았어.\n\n과연 스승님은 지혜로우셔. 우리는 서로 가르칠 수 있다네!\n\n미스릴 코이프와 화려한 미스릴 어깨보호구 만드는 법을 가르쳐 주면 내가 화려한 미스릴 투구 만드는 법을 가르쳐 주지!", progress = "물건은 다 만들었나?", completion = "아주 좋았어! 내가 보기에 아주 공평한 거래인 것 같군. 자, 잘 보고 배우게!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n화려한 미스릴 투구\n\n다음과 같은 것들을 받습니다:\n\n"},
[2772] = {title = "화려한 미스릴 장화", objective = "트렌튼 라이트해머에게 견고한 미스릴 장화 2개와 화려한 미스릴 바지 1개를 가져가야 합니다.", description = "작년에 대장장이 선수권 대회를 본 자라면 모두 알고 있을 거야. 투자개발회사 주물 공장에서 대표 선수로 나온 비겁한 녀석이 내 다리를 걸어 넘어뜨리는 걸! 하지만... 후후, 아무도 내가 그 시합에서 우승할 줄은 몰랐겠지. 비밀은 바로 화려한 미스릴 장화라네!\n\n올해에도 우승하려면 반드시 화려한 미스릴 바지를 만드는 법을 알아야 해. 왜냐하면 투자개발회사 벌목기가 출전을 하거든! 내게 바지 만드는 법을 가르쳐 주면 나는 장화 만드는 법을 가르쳐 주겠네!", progress = "물건은 다 만들었나?", completion = "미스릴 장화만 있으면 전 세계가 자네 발 아래 있게 되지! 적들에게 마음껏 다리를 후려쳐 보라고 하게! 이제 자네는 결코 쉽게 쓰러지지 않을 테니!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n화려한 미스릴 장화\n\n다음과 같은 것들을 받습니다:\n\n"},
[2773] = {title = "미스릴 천재", objective = "트렌튼 라이트해머에게 견고한 미스릴 흉갑 2개와 화려한 미스릴 장갑 1개를 가져가야 합니다.", description = "이 부근에서는 모두 나를 미스릴 천재라고 부르지. 전 세계에서 온 모험가들에게 화려한 미스릴을 공급해 주니까 말이야.\n\n<목소리를 낮춰 속삭이며...>\n\n하지만 내가 화려한 미스릴 장갑 만드는 법을 모른다는 건 아무도 모른다네. 쉿! 우리끼리 비밀이니까 꼭 지켜주게.\n\n내게 화려한 미스릴 장갑 만드는 법을 가르쳐 주게. 그러면 내가 갈반의 슬하에서 배운 기술의 결정체를 보여줄 테니까. 바로 화려한 미스릴 흉갑의 비밀을 말일세.", progress = "물건은 다 만들었나?", completion = "정말 고맙네.\n\n자, 잘 보고 배우게! 자네는 곧 화려한 미스릴 방어구의 달인이 될 거야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n화려한 미스릴 흉갑\n\n다음과 같은 것들을 받습니다:\n\n"},
[2781] = {title = "현상수배: 칼리프 스콜피드스팅", objective = "칼리프 스콜피드스팅을 처치하고 그 증거로 그의 머리카락을 칼리프 스콜피드스팅의 머리카락을 가져다주어야 합니다.", description = "범죄자 칼리프 스콜피드스팅을 현상수배한다.\n\n타나리스의 가젯잔 수자원개발회사는 사막유랑단 무법자들의 두목인 칼리프 스콜피드스팅를 처치하는 자에게 두둑한 현상금을 지급할 것이다. 범죄자 칼리프 스콜피드스팅을 아래 죄목으로 현상수배하는 바이다.\n\n1. 가젯잔 수자원개발회사 직원 살해!\n2. 가젯잔 수자원개발회사 자원 탈취!\n3. 가젯잔 수자원개발회사 자산 불법 점유!\n\n칼리프 스콜피드스팅의 머리카락을 선임기술자 빌지위즐에게 가져오는 자에게는 엄청난 현상금을 지급할 것이다.", progress = "그렇소, 내가 가젯잔 수자원개발회사의 선임기술자요. 도울 일이라도?", completion = "이제야 정의가 실현되는군! 그 나쁜 떠돌이 녀석들에게 본때를 보여줬어! 스콜피드스팅이 죽었으니 이제 그 불청객들을 모두 가젯잔의 우물에서 몰아낼 수 있겠어!\n\n가젯잔 수자원개발회사를 대신해 이 현상금을 지급하겠소. 당신은 우리 모두에게 아주 큰 도움을 주었소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2782] = {title = "린지의 비밀", objective = "마른나무껍질 트롤에 관해서 누구보다 잘 알고 있는 저명한 학자인 오란 스네이크레이드라면 이 서판을 해독할 수 있을지도 모릅니다. 그녀는 언더시티의 마법 지구에 살고 있다고 합니다.", description = "이 서판은 마른나무껍질 트롤 종족의 독특한 문양으로 온통 뒤덮여 있습니다. 린지의 비밀은 참으로 수수께끼입니다.\n\n당신의 손에 든 것이 아주 값진 물건이 있을 수도 있고 그 반대일 수도 있습니다. 궁지에 몰린 마른나무껍질 트롤은 온갖 수단 방법을 가리지 않을 테니까...", progress = "흠, 어디 보자... 이건 뭐죠?", completion = "이 서판은... 아주 보기 드문 물건이로군요. 이걸 어디서 찾으셨지요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2783] = {title = "사소한 말다툼", objective = "저주받은 땅과 늪의 경계에 있는 호드 영웅의 넋과 대화하십시오.", description = "우리는 엉뚱한 적과 싸우고 있소.\n\n우리가 저주받은 땅을 두고 오크족과 옥신각신하는 동안에 이 땅의 진정한 적이 그 힘과 수를 불려 가고 있소.\n\n호드와 전쟁만 치르다가 어느 날 불타는 군단에 참패를 당하는 꼴을 그냥 두고만 봐야겠소? 백해무익이오.\n\n서로 생각 차이는 제쳐 두고 호드 영웅의 넋과 이야기해 보시오. 저주받은 땅에 숨겨져 있는 진실을 알고 있을 테니까...", progress = nil, completion = "얼라이언스가 우릴 돕겠다고?\n\n이런 날은 결코 다시는 오지 않을 줄 알았소. 호드와 얼라이언스가 공동의 적에 맞서 어깨를 나란이 하고 싸울 줄은!\n\n음... 우린 함께 싸워야 할 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2784] = {title = "명예 실추", objective = "호드 영웅의 넋이 하는 이야기를 들어야 합니다.", description = "<race>|1이여;여;, 내 얘기를 좀 들어 보게.", progress = nil, completion = "나는 육체가 없기 때문에 아무런 힘이 없소, &lt;name&gt;. 날 도와주시오. 내가 명예를 되찾을 수 있도록 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2801] = {title = "슬픈 이야기", objective = "호드 영웅의 넋이 하는 이야기를 들어야 합니다.", description = "먼저 내가 지금부터 하는 이야기를 잘 들어 보시오.", progress = "내가 하는 이야기를 잘 들으시오.", completion = "바로 지금이 우리 계획을 시작할 때요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2821] = {title = "최고의 품질", objective = "페더문 요새에 있는 프랫 맥그루벤에게 두꺼운 설인 가죽 10개를 가져가야 합니다.", description = "나의 가죽세공 철학은 가능한 품질이 최상인 제품을 만들어야 한다는 것입니다. 이 점에는 절대 타협이란 있을 수 없지요. 품질은 중요하지 않다고 말하는 자는 던 모로에서 바닷가 별장을 팔려고 하는 자입니다!\n\n얼마 전 고품질 가죽 재료를 찾다가 두꺼운 설인 가죽을 발견하게 되었습니다. 그 설인은 거친흉터 골짜기에 많이 서식하는 페랄라스의 토착민입니다. 그 가죽이 좀 필요한데, 두꺼운 설인 가죽 10개를 가져다주면 내 가죽세공품 중 하나를 주도록 하죠. 조건이 마음에 들면 거래하게 되는 겁니다.", progress = "두꺼운 설인 가죽 10개를 가져오면 내가 만든 제품 중 하나를 주겠습니다. 나는 품질을 중요하게 생각하는 세공사이니 당신은 분명 질 좋은 물건을 받게 될 겁니다!\n\n설인들을 찾는 게 쉽지 않을 것 같다면 거친훙터 골짜기 주위에 잊혀진 해안의 섬에서 찾아보도록 하십시오.", completion = "이런 가죽 본 적 있습니까? 제대로 세공하기만 하면 무쇠보다 더 튼튼하게 만들 수 있겠군요. 이 가죽에 대해 알고 있는 사람은 그리 많지 않습니다. 내가 알고 있는 여러 가지 처리 약품을 잘 이용하면 정말 고품질의 제품을 만들 수 있을 겁니다. 물론 당신 덕이지요!\n\n자, 당신의 수고에 대한 답례니 이 물건들 중 하나를 골라보도록 하십시오!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n프랫의 수제 장화프랫의 수제 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2822] = {title = "품질 표시", objective = "모자케 야영지에 있는 장도르 스위프트스트라이더에게 두꺼운 설인 가죽 10개를 가져가야 합니다.", description = "나는 내 가죽세공술에 자부심이 있으며 내 기술이 증명되고 있다고 생각하오. 품질에 타협이란 절대 있을 수 없지. 품질이 중요하지 않다고 말하는 자는 대지가 비밀을 지킬 줄 모른다고 우기는 자나 마찬가지요!\n\n얼마 전 고품질 재료를 찾다가 두꺼운 설인 가죽을 발견하게 되었지. 원시설인은 페랄라스의 토착민으로 대게 이곳의 서쪽, 거친흉터 골짜기에서 발견할 수 있소. 두꺼운 설인 가죽 10개를 가져다주면 내 가죽세공품 중 하나를 주겠소. 조건이 마음에 든다면 거래는 성립된 거요!", progress = "두꺼운 설인 가죽 10개를 찾은 거요? 내 가죽세공품은 그야말로 으뜸이지. 당신이 그 가죽을 가지고 왔다면 견본 제품을 하나 주리다.\n\n설인을 찾는 게 쉽지 않을 것 같다면 내가 어디 있는지 알려줄 수 있을 것이오. 거친흉터 골짜기 주위에 잊혀진 해안의 섬에서 찾아보도록 하시오.", completion = "아, 훌륭하군! 이 가죽을 특수 처리하면 무쇠만큼 튼튼하게 만들 수도 있겠소! 무두질하기에 알맞은 혼합물을 만들려면 여러 번 시도를 해야겠지만 분명히 내 품질의 수준을 한층 높일 수 있을 거요.\n\n당신의 도움은 너무나 값진 것이었소. 자, 내가 만든 이 물건 중 하나를 골라보시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n장도르의 수제 장화장도르의 수제 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2841] = {title = "기술 전쟁", objective = "놈리건에서 장치 설계도와 텔마플러그의 금고 암호를 찾아서 오그리마에 있는 노그에게 가져다주어야 합니다.", description = "노움의 기술이라... 2년 전만 해도 농담으로나 하던 소리였는데... 시대가 많이 변했죠. 이제 노움은 우리 벌목기를 다 모은 것보다 더 좋은 장비를 가지고 있어요. 녀석들의 설계도가 필요해요!\n\n유감스럽게 그 설계도는 금고에 보관되어 있는데 멕기니어 텔마플러그가 항상 근처를 지키고 있어요. 게다가 그만이 금고 암호를 알고 있답니다.\n\n무슨 수를 써서라도 금고 번호를 알아내세요. 번호를 알아내면 금고를 열고 설계도를 가져오세요!", progress = "설계도는 안 보이는데? 몸에다 숨긴 건가요, 아니면 날 짜증 나게 하려고 꾸물거리는 건가요?", completion = "&lt;name&gt;, 당신이라면 해낼 줄 알았어요! 소빅은 미심쩍어 했지만 말이죠.\n\n\n\n이제 설계도를 손에 넣었으니 장치 제작에 사용된 노움의 기술을 알아내는 건 시간문제예요. 그걸 우리 고블린 기술에 접목하면 혁신적인 벌목기를 만들 수 있겠죠!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n선민의 로브출장용 작업복이중 강화 다리보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2842] = {title = "선임기술자 스쿠티", objective = "무법항에 있는 스쿠티와 대화하십시오.", description = "케르노비에게서 새 노움 장치에 대한 소식을 듣자마자 스쿠티와 나는 순간이동기 6000을 만들기 시작했습니다. 순간이동기 6000은 가장 빠르고 안전하게 놈리건에 가는 방법이랍니다.\n\n드디어 승객들을 태울 준비가 됐군요. 한번 타보고 싶으시다면 무법항으로 가서 와이번 횃대에 있는 스쿠티와 얘기를 나눠보시기 바랍니다. 무법항으로 가려면 톱니항에서 배를 타야 한답니다.\n\n물론 드워프가 득실거리는 던 모로의 산맥을 지나서 놈리건까지 뛰어가도 상관없지만요!", progress = nil, completion = "아주 멋진 장치지 않소? 아직 열 두 번밖에 폭발한 적이 없는 고블린 순간이동 기술의 최고봉이라오.\n\n내가 다 고쳐놓았으니까 걱정 마시오. 당신이 탔을 때는 폭발하진 않을 거요. 혹시 폭발하더라도 순식간에 고통 없이 끝날 거라오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2843] = {title = "놈리거어어어언!", objective = "스쿠티가 고블린 응답장치를 조절하는 동안 기다려야 합니다.", description = "응답장치를 갖고 발판에 올라서는 즉시 놈리건으로 이동하게 될 거요.\n\n부작용이 좀 생기겠지만 영구적인 것은 아니오.\n\n아, 제일 중요한 걸 잊을 뻔했군. 귀환 말인데 돌아오려면 놈리건에 있는 순간이동기 발판에 올라서면 되지.\n\n이제 응답장치를 당신의 키와 체중에 맞게 조절하겠소.", progress = nil, completion = "모두 끝났소! 떠날 준비가 되거든 발판 위에 올라서시오.", rewards = "다음과 같은 것들을 받습니다:\n\n고블린 응답장치"},
[2844] = {title = "거대한 수호자", objective = "길 잃은 나이트 엘프 소녀를 찾아야 합니다.", description = "난 쓸모없다. 내 친구 샤이를 지켜 주기로 했었는데 샤이가 날 떠나버렸다. 무슨 일이 일어난 건지 모르겠다. 샤이를 마지막으로 본 건 우리가 북쪽에 있는 폐허를 지나고 있을 때였다. 모든 게 다 괜찮았는데 뒤돌아보니까... 샤이가 없었다.\n\n이제 뭘 어떡해야 할지 모르겠다. 무슨 좋은 방법 없을까? 샤이가 걱정된다.\n\n샤이를 좀 찾아봐 줬으면 한다. 너는 나보다 훨씬 더 빨리 걸어다닐 수 있을 거다.", progress = nil, completion = "아, 절 찾아주시다니 정말 다행이에요! 솔직히 길을 좀 잃었지만... 여기 너무 아름답지 않나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2845] = {title = "방황하는 샤이", objective = "궤짝에서 샤이의 종을 집어야 합니다.\n\n샤이 리프러너를 무쇠이빨의 야영지까지 호휘해야 합니다.", description = "제 친구 무쇠이빨에게 절 다시 데려다 주지 않으시겠어요? 절 지켜 주기로 했었는데... 전 가끔 이리저리 헤매어 엉뚱한 곳으로 가는 경향이 좀 있거든요. 여기저기 볼 것도 너무 많고 해서 쉽게 주의가 산만해진답니다.\n\n단 한 가지 항상 제 주의를 집중시키는 게 있긴 해요.\n\n이 궤짝 안에, 제가 무척 아끼는 종이 있어요. 소리가 얼마나 예쁜지 몰라요. 이걸 드릴 테니 또 엉뚱한 곳으로 가 버리면 종을 울려주세요. 당신이 이 종만 울리면 다시 되돌아오겠다고 약속할게요.", progress = "샤이, 네 걱정 무진장 했어! 샤이를 데려다 줘서 정말 고맙다.", completion = "뭐라고? 샤이가 없어지면 이 종을 울리면 된다고? 정말 신기하네!\n\n나를 도와 주었으니 이걸 받아.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n화강암 장갑덩굴울타리 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2846] = {title = "심연의 티아라", objective = "먼지진흙 습지대에 있는 타베사에게 심연의 티아라를 가져가야 합니다.", description = "오래전에 난 아름다운 보물을 하나 갖고 있었어요. 심연의 티아라라는 물건인데, 아주 아름다울 뿐만 아니라 제대로 사용할 줄 아는 이에게는 엄청난 힘을 주었죠.\n\n그 소문이 유체술사 벨라타의 귀에 들어가자 욕심을 낸 거예요. 그래서 내가 집을 비운 사이에 부하들을 보내 훔쳐 가 버렸어요. 망할 놈의 도둑들 같으니!\n\n내 티아라를 되찾고 싶어요! 타나리스에 있는 트롤 도시, 줄파락에 가서 벨라타를 찾아 그 티아라를 빼앗아 주세요. 그걸 갖다주면 보상을 해 드리겠어요.", progress = "티아라는 찾은 거예요, <name>? 날 화나게 한 대가가 어떤 것인지 벨라타에게 확실히 가르쳐 줬겠죠?", completion = "멋지군! 찾았어! 이제 더 이상 욕심쟁이 벨라타가 티아라를 볼 수 없겠지... &lt;name&gt;, 평생 다 못 갚을 큰 은혜를 입었군요! 설마 당신도 욕심이 났던 건 아니겠죠?\n\n아, 내 말이 좀... 거슬리나요? 신경 쓸 것 없어요. 내 물건을 훔치지 않은 자들한테는 상냥하다는 걸 알게 될 테니까.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n주술 마법봉혈암 어깨갑옷"},
[2847] = {title = "야생 가죽 방어구", objective = "페더문 요새에 있는 프랫 맥그루벤에게 두꺼운 가죽 10개를 가져가야 합니다.", description = "당신, 가죽 세공인으로서 솜씨가 점점 좋아지고 있군요! 당신이 흥미를 가질 만한 도안을 몇 가지 알고 있습니다. 바로 야생 가죽 방어구이지요! 야생 가죽은 풀이 무성하게 자라는 지역과 그곳에 사는 생물들에게서 볼 수 있는 야생덩굴의 강력하고 혼돈스러운 특성을 지니고 있습니다. 그걸로 만든 방어구는 당신 같은 솜씨를 가진 사람들에게는 최고의 것입니다. 내 보증하죠.\n\n당신에게 이걸 가르쳐 주는 대가로 한동안 나와 함께 일을 해야 할 겁니다. 먼저 해야 할 일은 두꺼운 가죽 10개를 가져오는 겁니다. 더 자세한 얘기는 그 후에 하도록 합시다.", progress = "내가 말했듯이, 야생 가죽 방어구에 대해 배우려면 한동안 나를 위해 일을 해야 할 겁니다. 야생덩굴은 강력하기도 하고 혼돈스럽기도 해서 당신이 만들 강한 방어구에 무작위로 더 강력한 성질을 부여하게 될 것이기 때문입니다. 그러나 내가 이러한 지식을 쉽게 얻은 건 아니었습니다.\n\n이걸 배우려면 그 대가로 두꺼운 가죽 10개를 가져와야 합니다.\n\n그게 일단락되면 그 도안을 만들기 위한 일을 시작하도록 하겠습니다.", completion = "같이 일을 시작하게 돼서 기쁩니다. 당신은 가죽 세공인으로서 아주 현명한 판단을 내린 겁니다. 일단 어떠한 야생 가죽 방어구든 만드는 방법을 배우기만 하면 가죽 방어구를 착용하는 사람들이 죄다 당신에게 몰려들게 될 겁니다.\n\n자, 그럼 시작합시다. 어디서부터 시작하고 싶습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2848] = {title = "야생 가죽 어깨보호구", objective = "페더문 요새에 있는 프랫 맥그루벤에게 두꺼운 방어구 키트 6개와 야생덩굴 1개를 가져가야 합니다.", description = "야생 가죽 어깨보호구는 착용하는 자의 골격을 아주 잘 받쳐 주기 때문에 팔 위쪽과 어깨를 보호하는데 최고라고 할 수 있습니다. 다른 야생 가죽 방어구와 마찬가지로 야생덩굴을 바느질해 붙이면 강력한 효과가 무작위로 더해지게 됩니다.\n\n이 도안을 얻으려면 두꺼운 방어구 키트 6개와 야생덩굴 하나가 필요합니다. 당신한테 그리 어려운 임무는 아닐 겁니다.", progress = "두꺼운 방어구 키트 6개와 야생덩굴을 가져왔습니까?\n\n방어구 키트 만드는 것을 지루한 일이라고 생각하지 마시기 바랍니다. 키트 만드는 일을 열심히 하면서 꾸준한 제작 방법을 익히면 야생 가죽 방어구를 만들기 위해 필요한 복잡한 작업을 할 수 있는 기술이 좋아지게 될 겁니다.\n\n내가 그것들을 만들라고 하는 데는 다 이유가 있단 말입니다.", completion = "아주 견고한 방어구 키트를 만들었군요. 내가 나 자신에게나 내가 고용한 사람들의 작업에서 요구하는 단 한 가지가 있다면 그건 바로 품질입니다.\n\n당신은 이 도안을 얻어도 충분할 만큼 훌륭하게 해냈군요. 내가 얻었던 만큼의 보람을 당신도 얻게 되기를 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 어깨보호구"},
[2849] = {title = "야생 가죽 조끼", objective = "페더문 요새에 있는 프랫 맥그루벤에게 거북 껍질 흉갑 2개, 거북 껍질 장갑 2개, 야생덩굴 1개를 가져가야 합니다.", description = "야생 가죽 조끼는 모든 야생 가죽 방어구 세트의 기본입니다. 조끼의 틀이 야생덩굴과 잘 섞여 조끼 전체에 강력한 마법이 흐르게 되기 때문에 몸통을 최대한으로 보호할 수 있답니다.\n\n이 도안을 얻으려면 거북 껍질 흉갑 2개와 거북 껍질 장갑 2개, 그리고 야생덩굴 1개가 필요합니다. 단순한 임무는 아니지만 그리 어렵진 않을 겁니다.", progress = "내가 지시한 거북 껍질 흉갑과 장갑을 2개씩 가져왔습니까? 아, 야생덩굴도 잊지 마시기 바랍니다!\n\n최초의 도안들만 봐도 기본적인 형태의 틀이 고급 방어구에도 모두 적용된다는 것을 알 수 있습니다. 서로 다른 물건이긴 하지만 거북 껍질 흉갑의 형태는 야생 가죽 조끼를 만드는 데 필요한 세부 작업을 위한 준비가 될 겁니다.\n\n그리고 장갑은... 그게, 장갑은 그냥 내가 좀 필요해서 말입니다. 당신은 나를 위해 일하고 있다는 걸 잊으면 안 됩니다!", completion = "아주 쓸 만한 것들을 가져왔군요. 이것들을 만드는 데 들어간 장인 정신과 정성만으로도 보통의 방어구보다 돈을 더 많이 받을 수 있겠군요.\n\n내가 지시한 것들을 다 가져왔으니 보상을 해야겠군요. 야생 가죽 조끼 제작 기술은 이제 당신 겁니다!", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 조끼"},
[2850] = {title = "야생 가죽 투구", objective = "페더문 요새에 있는 프랫 맥그루벤에게 밤하늘 튜닉 2개, 밤하늘 머리띠 2개, 야생덩굴 1개를 가져가야 합니다.", description = "야생 가죽 투구는 편안하면서도 머리의 중요한 부위를 아주 우수하게 보호해 줍니다. 모든 야생 가죽 방어구와 마찬가지로 여기에 포함된 야생덩굴이 투구의 기본틀에 강력한 효과를 무작위로 부여하게 되지요. 가죽 방어구를 착용하는 사람들은 틀림없이 이런 투구를 원할 겁니다!\n\n이 도안을 얻으려면 밤하늘 튜닉 2개, 밤하늘 머리띠 2개와 야생덩굴 1개가 필요합니다. 지시대로 완수하면 이 도안은 당신 것이 될 겁니다!", progress = "그 튜닉과 머리띠, 그리고 야생덩굴이 있어야 야생 가죽 투구 제작 방법을 가르쳐줄 수 있습니다.\n\n모험가들 사이에서는 머리에 착용하는 거라면 머리 일부만을 가리는 단순한 머리띠든 머리를 완전히 덮어쓰는 투구든 상관없이 장비가 아주 인기랍니다. 장비의 겉모습이야 어떻든 값진 머리 장비 제작의 기본은 언제나 한결같습니다.", completion = "당신이 가져온 이 밤하늘 장비는 지시한 내용에 아주 딱 맞는군요. 당신 정도의 가죽 세공인이라면 이쯤은 할 줄 알아야지요.\n\n당신은 분명 이 도안을 얻을 자격이 있으니 기꺼이 드리겠습니다. 앞으로 이 도안으로 많은 이득을 볼 수 있게 되기를 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 투구"},
[2851] = {title = "야생 가죽 장화", objective = "페더문 요새에 있는 프랫 맥그루벤에게 밤하늘 바지 2개, 밤하늘 장화 2개, 야생덩굴 2개를 가져가야 합니다.", description = "지금까지 꽤 많은 기술을 배웠지만 아직 더 배울 게 있습니다. 다음은 모든 세트의 기초가 되는 야생 가죽 장화를 만들 차례입니다.\n\n이 장화는 발을 편안하게 해 주고 위험한 것들로부터 발을 보호하도록 고안되었답니다. 부드러운 밑창은 움직일 때 소리가 나지 않는 신발을 찾는 여행자들에게는 아주 딱입니다.\n\n이 도안을 얻으려면 밤하늘 바지 2개와 밤하늘 장화 2개와 야생덩굴 2개가 필요합니다. 이번엔 야생덩굴 1개가 아니라 2개입니다. 모두 다 구하거든 나에게 다시 오도록 하세요.", progress = "도안을 얻기 전에 바지, 장화와 야생덩굴에 대한 지시를 그대로 완수해야 합니다. 다 끝냈나요?\n\n우리는 맨 처음 장화 제작법을 배울 때부터 품질 좋은 장화란 편안함과 기능성 사이에 칼날 같이 정확한 균형을 유지할 수 있어야 한다는 것을 배우게 됩니다. 편안함과 기능성을 모두 갖추면 저품질의 장화를 신은 사람이 느끼는 피로 따위는 걱정하지 않아도 되는 겁니다.", completion = "또 한번 이렇게 복잡한 지시를 노련한 전문가의 솜씨로 완성했군요. 당신은 내 감사와 함께 이 도안을 받을 자격이 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 장화"},
[2852] = {title = "야생 가죽 다리보호구", objective = "페더문 요새에 있는 프랫 맥그루벤에게 거북 껍질 투구 2개, 거북 껍질 팔보호구 2개, 야생덩굴 2개를 가져가야 합니다.", description = "기본을 잘 익혔으니 이제 좀 더 복잡한 것을 배울 때가 되었군요. 야생 가죽 다리보호구는 가죽 장비 중에서도 가장 튼튼하고 강력한 것에 속한답니다. 허리, 허벅지, 종아리에 이르기까지 모두 강력한 보호를 받게 되는 겁니다. 야생덩굴에서 얻을 수 있는 강력한 효과까지 합치면 이걸 가진 모험가들이 당신을 볼 때마다 감사를 표하게 될 겁니다.\n\n이 도안을 얻으려면 거북 껍질 투구 2개, 거북 껍질 팔보호구 2개와 야생덩굴 2개가 필요합니다.", progress = "거북 껍질 팔보호구와 투구는 다 준비됐나요? 야생덩굴 2개도 잊지 마시기 바랍니다!\n\n지금쯤 아마 당신도 야생 가죽 방어구의 잠재되어 있는 힘을 실감하기 시작했을 겁니다. 착용에 제한이 없는 방어구는 가죽 세공인에게 있어 거의 값을 헤아릴 수 없을 정도로 귀중하지요. 제한이 있다면 그 방어구를 만드는 데 필요한 재료의 수량에 있을 뿐입니다. 완성된 제품의 품질은 물론 최고입니다!", completion = "또다시 흠 하나 없이 완벽하게 지시 사항을 완수했군요. 어쩌면 언젠가 청출어람격으로 내가 당신에게 찾아가 배우게 될지도 모르겠군요. 안 그렇습니까?\n\n자, 다리보호구의 도안과 함께 내 감사의 마음도 함께 받아주십시오. 이 가르침을 깊이 새겨두고 당신이 완성한 제품에 놀라운 솜씨를 담아내도록 하시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 다리보호구"},
[2853] = {title = "야생 가죽 세공의 대가", objective = "다르나서스에 있는 가죽 세공의 대가인 텔로니스에게 프랫의 편지를 가져가야 합니다.", description = "음, 당신이야말로 근면 그 자체군요. 나머지는 모두 터득했고 야생 가죽 방어구 도안이 딱 하나 남았습니다. 이 도안은 굳이 고생을 해서 얻을 필요가 없습니다. 당신 스스로 받을 자격을 충분히 증명해 보였고 또... 내가 줄 수는 없습니다. 나를 가죽 세공의 길로 이끌어 주신 내 스승께서 직접 당신에게 보상을 해주셔야만 합니다.\n\n텔로니스님께 이 편지를 가져가십시오. 그분께서는 다르나서스에서 가죽 세공술을 가르치시고 계십니다. 그분께 이 편지를 보여 드리고 나와 마찬가지로 당신도 그분께 동등한 동료로 인정받도록 하시기 바랍니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 망토"},
[2854] = {title = "야생 가죽 방어구", objective = "모자케 야영지에 있는 장도르 스위프트스트라이더에게 두꺼운 가죽 10개를 가져가야 합니다.", description = "당신의 가죽 세공 기술은 빠르게 발전하는군! 당신이 익히면 도움이 될 가죽 세공 기술을 내가 알고 있는데... 바로 야생 가죽 방어구요! 야생 가죽은 풀이 무성하게 자라는 지역과 그곳에 사는 생물들에게서 볼 수 있는 야생덩굴의 강력하고 혼돈스러운 특성을 이끌어내지. 내 보증하건대 그걸로 만든 방어구는 당신 같은 솜씨를 가진 세공인에게는 최고의 것이오.\n\n내 그 기술을 가르쳐 주는 대신 한동안 나와 함께 일을 해야 할 것이오. 먼저 해야 할 일은 두꺼운 가죽 10개를 가져오는 것이니 자세한 얘기는 그 후에 하도록 하겠소.", progress = "분명히 말하는데 야생 가죽 방어구 기술을 배우는 동안 내 수습생이 되어야 하오. 야생덩굴은 강력하기도 하고 혼돈스럽기도 해서 당신이 만들 강한 방어구에 무작위로 더 강력한 성질을 부여하게 될 것이오. 그렇지만 내가 이러한 지식을 쉽게 얻은 건 아니었소이다.\n\n이걸 배우려면 그 초기 대가로 두꺼운 가죽 10개를 가져와야 하오. 그게 일단락되면 그 도안을 만들기 위한 일을 시작하도록 하겠소.", completion = "당신이 내 수습생이 되어 기쁘군. 가죽세공인으로서 아주 현명한 판단을 내린 것이오. 일단 야생 가죽 세공술을 터득하는 방법만 배우면 가죽 방어구를 사용하는 사람들이 죄다 당신에게 몰려들게 될 것이오.\n\n자, 그럼 시작합시다. 어디서부터 시작하고 싶소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2855] = {title = "야생 가죽 어깨보호구", objective = "모자케 야영지에 있는 장도르 스위프트스트라이더에게 두꺼운 방어구 키트 6개와 야생덩굴 1개를 가져가야 합니다.", description = "야생 가죽 어깨보호구는 착용하는 자의 골격을 아주 잘 받쳐 주기 때문에 팔 위쪽과 어깨를 보호하는데 최고라고 할 수 있지. 다른 야생 가죽 방어구와 마찬가지로 야생 포도 덩굴을 바느질해 붙이면 강력한 효과가 무작위로 더해지게 되는 것이오.\n\n이 도안을 얻으려면 두꺼운 방어구 키트 6개와 야생덩굴 하나가 필요하오. 당신한테 그리 어려운 임무는 아닐 것이오.", progress = "필요한 두꺼운 방어구 키트 6개와 야생덩굴을 가져왔소?\n\n방어구 키트를 만드는 작업을 한결같고 신뢰할 수 있는 세공 작업을 위한 기초 수업이라 생각하시오. 키트 만드는 일을 열심히 하면서 일관된 제작 방법을 익히면, 야생 가죽 방어구를 만들기 위해 필요한 복잡한 작업을 할 수 있는 기술이 좋아지게 될 것이니 말이오.\n\n모든 수업에는 다 이유가 있는 것이니 각각의 수업에 즐겁게 임하길 바라오.", completion = "아주 견고한 방어구 키트를 만들었군. 내가 나 자신에게나 내가 지도하는 사람들의 작업에서 요구하는 단 한 가지가 있다면 그건 바로 품질이오.\n\n당신은 이 도안을 얻어도 좋을 만큼 훌륭하게 해냈소. 내가 이 도안을 얻었던 만큼의 보람을 당신도 얻게 되기를 바라오이다.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 어깨보호구"},
[2856] = {title = "야생 가죽 조끼", objective = "모자케 야영지에 있는 장도르 스위프트스트라이더에게 거북 껍질 흉갑 2개, 거북 껍질 장갑 2개, 야생덩굴 1개를 가져가야 합니다.", description = "야생 가죽 조끼는 모든 야생 가죽 방어구 세트의 기본이지. 조끼의 틀과 야생덩굴이 한데 잘 엮여 조끼 전체에 강력한 마법이 흐르게 되기 때문에 몸통을 최대한으로 보호할 수 있소이다.\n\n이 도안을 얻으려면 거북 껍질 흉갑 2개와 거북 껍질 장갑 2개, 그리고 야생덩굴 1개가 필요하오. 쉬운 수업은 아니지만 당신 실력이라면 이 정도는 틀림없이 해낼 수 있을 것이오.", progress = "내가 말한 거북 껍질 흉갑과 장갑을 2개씩 가져왔소? 야생덩굴도 잊지 마길 바라오!\n\n최초의 도안들만 봐도 기본적인 형태의 틀이 만들기 고급 방어구에도 모두 적용된다는 것을 알 수 있소. 서로 다른 물건이긴 하지만 거북 껍질 흉갑의 형태는 야생 가죽 조끼를 만드는 데 필요한 세부 작업을 위한 기초가 될 것이오.\n\n수업이 계속 진행되면서 내가 가르쳐 주는 기술들은 예술의 경지에 이르게 될 것이오!", completion = "아주 쓸 만한 것들을 가져왔군. 이것들을 만드는 데 들어간 장인 정신과 정성만으로도 당신이 이 일에 자신을 완전히 헌신하기로 결정했음을 보여 주는구려.\n\n내가 요청한 것들을 다 가져왔으니 보상을 해야겠지. 야생 가죽 조끼 제작 기술은 이제 당신 것이오!", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 조끼"},
[2857] = {title = "야생 가죽 투구", objective = "모자케 야영지에 있는 장도르 스위프트스트라이더에게 밤하늘 튜닉 2개, 밤하늘 머리띠 2개, 야생덩굴 1개를 가져가야 합니다.", description = "야생 가죽 투구는 편안하면서도 머리의 중요한 부위를 아주 우수하게 보호해 주지. 모든 야생 가죽 방어구와 마찬가지로 여기에 포함된 야생덩굴이 투구의 기본틀에 강력한 효과를 무작위로 부여하게 되는 것이오. 가죽 방어구를 착용하는 사람들은 틀림없이 이런 투구를 원할 것이오!\n\n이 도안을 얻으려면 밤하늘 튜닉 2개, 밤하늘 머리띠 2개, 그리고 야생덩굴 1개가 필요하오. 이 수업을 마치면 이 도안은 당신 것이 될 것이오!", progress = "그 튜닉과 머리띠, 그리고 야생덩굴이 있어야 야생 가죽 투구 제작 방법을 가르쳐줄 수 있소이다.\n\n모험가들 사이에서는 머리에 착용하는 거라면 머리의 일부만을 가리는 단순한 머리띠든 머리를 완전히 덮어쓰는 투구든 상관없이 장비가 아주 인기랍니다. 장비의 겉모습이야 어떻든 값진 머리 장비 제작의 기본은 언제나 한결같소이다.", completion = "당신이 가져온 이 밤하늘 장비는 지시한 내용에 아주 딱 맞는군. 당신 정도의 가죽 세공인이라면 이쯤은 할 줄 알아야지.\n\n당신은 야생 가죽 투구를 제작하는 영광을 얻을 자격이 충분하오. 내 기꺼이 이 도안을 줄 테니 앞으로 이 도안으로 많은 이득을 볼 수 있게 되기를 바라오이다.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 투구"},
[2858] = {title = "야생 가죽 장화", objective = "모자케 야영지에 있는 장도르 스위프트스트라이더에게 밤하늘 바지 2개, 밤하늘 장화 2개, 야생덩굴 2개를 가져가야 합니다.", description = "당신의 야생 가죽 방어구에 대한 지식은 날로 늘어가고는 있지만 아직 배워야 할 게 더 있소.\n\n모든 세트의 기초가 되는 야생 가죽 장화요. 이런 장화는 발을 편안히 하면서도 모험에서의 위험을 견뎌낼 수 있도록 고안되었소. 부드러운 밑창은 움직일 때 소리가 나지 않는 신발을 찾는 사람들에게는 아주 딱이지.\n\n이 도안을 얻으려면 밤하늘 바지 2개와 밤하늘 장화 2개, 야생덩굴도 2개가 필요하오. 이번엔 야생덩굴이 1개가 아니라 2개요. 재료가 다 갖춰지면 수업을 계속 진행하도록 하겠소.", progress = "도안을 배우기 전에 그 바지, 장화 그리고 야생덩굴을 가져와야 하오. 내가 얘기한 대로 다 끝냈소이까?\n\n우리는 맨 처음 장화 제작법을 배울 때부터 품질 좋은 장화란 편안함과 기능성 사이에 칼날 같이 정확한 균형을 유지할 수 있어야 한다는 것을 알게 된다오. 편안함과 기능성을 모두 갖추면 저품질의 장화를 신은 사람이 느끼는 피로 따위는 걱정하지 않아도 되는 것이지.", completion = "다시 한번 노련한 전문가의 솜씨로 물건들을 완성했군. 당신은 내 축하와 함께 이 도안을 받을 자격이 충분하오.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 장화"},
[2859] = {title = "야생 가죽 다리보호구", objective = "모자케 야영지에 있는 장도르 스위프트스트라이더에게 거북 껍질 투구 2개, 거북 껍질 팔보호구 2개, 야생덩굴 2개를 가져가야 합니다.", description = "이제 좀 더 복잡한 기술을 익힐 때가 되었군. 야생 가죽 다리보호구는 가죽 장비 중에서도 가장 튼튼하고 강력한 장비에 속하오. 허리, 허벅지, 종아리에 이르기까지 모두 강력한 보호를 받게 되는 것이지. 거기에 야생덩굴에서 얻을 수 있는 강력한 효과까지 합치면 이걸 가진 모험가들이 당신을 볼 때마다 감사를 표하게 될 것이오.\n\n이 도안을 얻으려면 거북 껍질 투구 2개, 거북 껍질 팔보호구 2개, 야생덩굴 2개가 필요하오.", progress = "거북 껍질 팔보호구와 투구는 다 준비됐소? 야생덩굴 2개도 필요하다는 걸 잊지 마시기 바라오!\n\n지금쯤 아마 당신도 야생 가죽 방어구의 잠재되어 있는 힘을 실감하기 시작했을 것이오. 착용에 제한이 없는 방어구는 가죽세공인에게 있어 거의 값을 헤아릴 수 없을 정도로 귀중하오. 제한이 있다면 그 방어구를 만드는 데 필요한 재료의 수량 제한이 있을 뿐이지 완성된 제품의 품질은 최고지!", completion = "또 이렇게 흠 하나 없이 내가 요구한 일을 해냈군. 어쩌면 언젠가 거꾸로 내가 당신에게 찾아가 배우게 될지도 모르겠소. 안 그렇소?\n\n자, 내 감사의 마음과 함께 이 다리보호구 도안을 받으시오. 이 가르침을 깊이 새겨두고 완성한 제품에 당신의 놀라운 솜씨를 담아내도록 하기 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 다리보호구"},
[2860] = {title = "야생 가죽 세공의 대가", objective = "썬더 블러프에 있는 가죽 세공의 대가인 우나에게 장도르의 편지를 가져가야 합니다.", description = "내가 가르칠 수 있는 모든 것을 당신에게 가르쳤지만 아직 야생 가죽 방어구 도안 하나가 남아있소. 이 도안은 특별히 고생을 해서 얻을 필요가 없소. 당신 스스로 이미 받을 자격을 충분히 증명해 보였지만... 내 마음대로 줄 수 있는 게 아니오. 나를 가죽 세공의 길로 이끌어 주신 내 스승께서 직접 보상을 해주셔야 하오.\n\n썬더 블러프에서 가죽세공술을 가르치고 계신 우나님께 이 편지를 가져가도록 하시오. 가서 이 편지를 보여 드리고 나와 마찬가지로 당신도 그분께 동등한 동료로 인정받도록 하시오.", progress = "만나서 반갑습니다. 보아하니 당신도 나처럼 가죽 세공사인 것 같군요. 내 기술을 배우러 왔나요, 아니면 혹시 나에게 다른 볼일이 있는 건가요?", completion = "아, 장도르가 보낸 거로군요. 내가 가르친 가장 우수한 제자 중 하나가 이제 자신의 제자를 가르치다니 정말 기쁩니다.\n\n장도르의 가죽에 대한 헌신과 재능은 참으로 놀랍지요. 그가 이 편지에서 이토록 당신을 칭찬하다니 이것은 존중의 표시임을 나도 인정하지 않을 수 없군요.\n\n장도르가 야생 가죽의 도를 당신에게 가르친 것 같군요. 이 도안을 당신에게 주어 그 훈련을 마무리 짓도록 하겠습니다. 야생 가죽 망토의 비밀을 아는 이는 이 세계에서 아주 극소수뿐이니 유용하게 쓰도록 하시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 망토"},
[2861] = {title = "타베사의 임무", objective = "먼지진흙 습지대에 있는 타베사와 대화하십시오.", description = "듣자 하니, 먼지진흙 습지대 깊은 곳에 사는 동료 마법사 타베사가 줄파락에 사는 어떤 트롤과 해결할 문제가 있다고 해요. 타베사에게 가면 더 자세히 얘기해 줄 거예요.\n\n참, 친구도 몇 명 데리고 가세요, <name>. 타베사가 당신을 줄파락으로 보낼지도 몰라요. 그렇다면 혼자 가는 것은 바람직하지 않아요.\n\n타베사의 오두막은 테라모어 서쪽, 돌망치일족 폐허의 바로 북쪽에 있어요.", progress = nil, completion = "그래, 그 트롤 녀석과 결판을 내야 할 일이 좀 있죠. 몇 가지... 아니 전부 다!\n\n도와줄건가요?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2862] = {title = "덩굴발일족과의 전투", objective = "모자케 야영지에 있는 아도겐 스위프트스트라이더에게 덩굴발일족 갈기 10개를 가져가야 합니다.", description = "놀 녀석들... 단순히 거슬리기만 하는 게 아니오. 바로 이 야영지의 존속 자체에 끊임없는 위협이 되고 있소이다! 녀석들이 페랄라스의 토착민이든 아니든 상관없소. 우리가 좀 더 강한 결의로 녀석들과 맞서지 않으면 언젠가 우리는 이 지역에서 완전히 쫓겨나게 될 것이오.\n\n요즘 들어 놀 녀석들이 야영지를 더 거세게 공격하고 있소. 녀석들의 수를 줄이는 데 당신의 도움이 필요하오. 녀석들의 갈기 10개를 내게 가져오면 그 수고에 대해 후하게 보상하도록 하겠소.\n\n어서 가시오!", progress = "아무리 몰아내도 다시 달려드는 걸 보니 분명 누군가가, 아니면 무엇인가가 녀석들을 광포해지도록 만들고 있는 게 분명해... 아, 당신 돌아왔군? 보상을 받을 수 있을 만큼의 갈기를 가져왔소?", completion = "순조로운 출발의 증거로군. &lt;class&gt;|1으로서;로서; 당신 실력은 과연 칭찬할 만하오.\n\n이 임무를 당신에게만 맡긴 것은 아니오. 이전에 많은 이들이 녀석들과 싸웠고 그러한 과거의 노력으로 녀석들을 만에 묶어 둘 수 있었소. 하지만 최근에 들어서는 우리 영역권 내로 북향하려는 녀석들의 시도가 급격히 증가해 왔고 공격도 훨씬 더 사나워졌소. 거의 모든 것을 걸기라도 한 듯이 말이지...\n\n하지만 녀석들을 영원히 잠재워 버릴 수 있는 계획이 내게 있소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2863] = {title = "우두머리 공격", objective = "1시간 안에 덩굴발일족 우두머리 5마리를 처치하고 아도겐 스위프트스트라이더에게 되돌아와야 합니다.", description = "이번 계획은 우두머리라고 자칭하는 여럿의 놀 지도자 녀석들을 아주 짧은 시간 안에 진압하는 것이오. 우리가 재빠르고 정확하게 공격을 가할 수만 있다면 놈들 간에 혼란을 불러올 수 있을 것이며, 또한 우리가 그들을 짓밟을 수 있다는 걸 멍청한 놈들 머릿속에 확실히 새겨 넣게 될 것이오!\n\n바로 당신이 이러한 내 뜻을 전달하는 사자가 되어 줬으면 하오. 이 일을 제대로 수행하려면 한 시간 안에 우두머리 다섯을 처치해야만 하오. 그렇지 않으면 우린 계속 이 곤경에 빠져 있게 될 것이오!", progress = nil, completion = "내 계획대로 임무를 완수해 준데 대해 경의를 표하는 바이오. 당신의 수고에 대한 답례로 이 작은 보상을 받아 주시기 바라오.\n\n녀석들의 수가 줄어든 데다 우두머리들까지 죽었으니 이제 놀 녀석들도 함부로 이 야영지를 공격해 오지는 못할 것이오. 하지만 아직 이 문제가 완전히 종결된 것은 아니오...\n\n놀 녀석들이 그렇게 광포해지게 된 데는 분명 무슨 이유가 있을 것이오. 녀석들이 재편성을 마치기 전에 그 원인이 뭔지 알고 싶소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2864] = {title = "트란렉", objective = "가젯잔에 있는 트란렉과 대화해야 합니다.", description = "내 사촌, 트란렉이 곤경에 빠졌어요. 왕쇠똥구리 껍질을 한 짐 보내겠다고 약속한 지가 벌써 몇 주나 됐는데 아직 도착하지 않았거든요. 사촌이라 가젯잔으로 누구를 보내서 독촉을 하기가 좀 그런데...\n\n나 대신 트란렉과 얘기해 볼래요? 내가 허튼 짓을 하기 전에 빨리 보내라고 했다고 말에요.\n\n가젯잔은 칼림도어의 타나리스 북부에 있어요.", progress = nil, completion = "안녕하세요!\n\n오, 제 사촌 크라젝을 만났군요? 사촌은 잘 지내나요? 무법항에서 무사히 지내면 좋겠는데...\n\n왕쇠똥구리 껍질이라고요? 엄... 어떻게 된 건지 얘기해 드리죠...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2865] = {title = "왕쇠똥구리 껍질", objective = "가젯잔에 있는 트란렉에게 온전한 왕쇠똥구리 껍질 5개를 가져가야 합니다.", description = "타나리스의 왕쇠똥구리들은 단단한 껍질을 갖고 있지요! 건축 자재로 쓸 수 있을 만큼 아주 단단해요. 그 외에도 정말 여러 가지로 쓰이지요!\n\n사실, 그 껍질이 얼마나 유용한지, 왕쇠똥구리가 거의 멸종될 정도로 사냥을 해댔답니다!\n\n저는 그 귀한 왕쇠똥구리의 서식지를 알죠. 껍질을 제게 가져오겠다고만 약속하신다면 어딘지 가르쳐 드리지요. 약속하시겠어요?\n\n그럼, 좋아요. 왕쇠똥구리들은 줄파락에 무리를 지어서 살아요. 다행히 그곳 트롤들이 껍질을 노리고 녀석들을 사냥하지는 않는 것 같아요.\n\n당신이라면 할 수 있죠! 줄파락으로 가서 온전한 껍질을 가져오세요!", progress = "껍질은 가져오셨나요? 무법항에 있는 제 사촌에게 한 보따리 보내주겠다고 약속했는데, 더 이상 기다리기 힘든가 봐요!", completion = "아, 훌륭해요! 찾으셨군요!\n\n감사합니다, &lt;name&gt;. 당신은 정말 제 구세주예요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2866] = {title = "솔라살 폐허", objective = "솔라살 폐허를 탐사하고 그곳에 있는 나가의 실태를 조사해야 합니다.", description = "여기서 남쪽으로 가면 현시대가 되기 훨씬 이전부터 있었던 솔라살 폐허가 위치해 있습니다. 처음 그 유적지를 조사했을 때는 특별히 눈에 띄는 것이 없기에 건드리지 않고 그대로 두었지요.\n\n그런데 최근 들어 엄청난 수의 증오의갈기일족 나가들이 그 유적지를 점령했습니다. 처음에는 녀석들이 공격 준비를 하는 것이라 생각했습니다. 지금도 그럴 가능성이 있긴 하지만 뭔가 다른 일이 벌어지고 있는 게 아닌가 싶군요.\n\n가서 유적지를 탐사하고 눈에 띄는 것이 있으면 뭐든지 가지고 와주십시오. 엘룬께서 행운을 가져다주시길.", progress = nil, completion = "이 전망대를 조사해보니 주위의 유적지에 비해 흥미롭고 특이한 것들이 눈에 띕니다.\n\n첫째로, 이 전망대는 유적지의 다른 건물에 비해 아주 최근에 지어졌습니다. 둘째로, 이 전망대의 옆면에는 일련의 조그마한 문양이 새겨져 있습니다. 문양은 일정하게 반복되는데 그 근원이나 의미는 알 수가 없습니다. 셋째로, 이 전망대의 돌을 만져보니 따뜻합니다\n\n이는 분명 유적 탐사에서 눈에 띄는 발견입니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2867] = {title = "페더문 요새로 돌아가기", objective = "페더문 요새에 있는 샨드리스 페더문에게 돌아가 발견한 것에 대해 보고해야 합니다.", description = "솔라살 폐허의 중심부에서 기이한 전망대를 찾았으니 페더문 요새로 돌아가 여기서 발견한 것을 샨드리스 페더문 장군에게 보고해야 합니다.", progress = nil, completion = "그대의 보고에 있는 이 전망대는 무척... 느낌이 안 좋군요. 그곳의 나가들이 공격을 계획하고 있지 않더라도 녀석들이 계속 그곳에 남아있다면 우리의 페랄라스 진격에는 좋지 않지요. 그건 그렇고, 이건 유적지를 조사해준 답례입니다.\n\n증오의갈기일족 나가를 처치하려면 페더문 요새에 더 많은 지원이 절실히 필요할 듯 합니다. 원한다면 그대에게 이 임무를 맡기고 싶습니다. 우린 할 일이 무척 많답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2869] = {title = "증오의갈기일족과의 전투", objective = "페더문 요새에 있는 라트로니쿠스 문스피어에게 증오의갈기 나가 비늘 10개를 가져가야 합니다.", description = "이 시점에서 가장 좋은 방책은 나가의 속셈이 무엇이든 녀석들이 언젠가는 섬을 차지하기 위해 움직일 것이라 가정하고, 너무 늦기 전에 공격 조치를 취해 위협을 막아야 하는 것이오.\n\n상태가 양호한 증오의갈기 나가 비늘 10개를 가져오시오. 비늘을 어떻게 손에 넣는지는 알고 있을 거라 믿소. 그대는 나가와의 전투에서 경험을 쌓고 우리는 살도르 섬의 나가 수를 좀 줄일 수 있으니 모두에게 득이 되는 일일 것이오. 자, 어서 가시오.", progress = "임무를 다시 확인하러 온 것이라면 다시 알려주겠소. 이번 임무는 증오의갈기 나가 비늘 10개를 가져오는 것이오. 그냥 잡담을 나누러 온 것이라면 난 그런 일에 낭비할 시간이 없소이다.\n\n우리 나이트 엘프는 전쟁을 좋아하지 않는다는 것을 잘 알아두시기 바라오. 우리 종족은 평화와 공존을 지키기 위해 노력하는 것뿐이지만 그렇다고 해서 우리 종족을 보호하는데 필요한 사전 행동도 취하지 않는다는 것은 아니오. 이것이 페더문 장군님과 요새에 대한 나의 임무인 것이오.", completion = "좋아, 좋아. 이 비늘이면 충분하고도 남겠군. 아예 이것들을 프랫에게 보내 한번 봐달라고 하는 게 나을 것 같군. 이것들로 그 친구가 뭔가 쓸만한 것을 만들 수 있을지 모르니까 말이오.\n\n그대에게 줄 다른 임무가 있기는 하지만 먼저 이번 임무에 대한 보상부터 받으시오. 그대가 계속해서 장군님과 페더문 요새를 위해 힘을 써주니 정말 이 어려운 시기에 큰 힘이 되고 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2870] = {title = "군주 샬자루와의 전투", objective = "군주 샬자루를 처치하고 그가 찾아낸 신비한 유물을 페더문 요새에 있는 라트로니쿠스 문스피어에게 가져가야 합니다.", description = "새로운 정찰 보고를 받고 나가의 명령 체계를 더 자세히 알 수 있게 되었소. 듣자하니 나가 종족 중에는 왕족이 있는데 이 왕족이 모든 일을 결정하고 있다고 하는군.\n\n그 중에서도 유독 잔인한 군주 샬자루라는 자가 있다는 것을 확인하였소. 정찰병의 보고에 의하면 샬자루는 최근 나가들이 발굴하고 있는 공포의 섬에 수로를 건너 주 유적지의 남쪽 동굴에서 특이한 유물을 찾았다고 하오.\n\n그를 처치해 발굴을 저지하고 그 유물을 연구할 수 있게 내게 가져오시오.", progress = "군주 샬자루를 처치하면 몇 달까지는 아니지만 몇 주라도 그들의 계획을 늦출 수 있을 것이오. 게다가 그가 찾은 유물이라는 것을 우리도 꼭 한번 보고 싶소.\n\n내가 준 임무는 완수했소?", completion = "잘했소! 군주 샬자루의 죽음으로 나가들은 한동안 혼란에 빠질 것이오. 어쩌면 영원히 혼란에서 벗어나지 못할지도 모르지. 이제 나가의 위협에는 어느 때보다도 잘 대처할 수 있게 되었소이다. 그대에게 감사의 마음을 전하오.\n\n자, 요새 금고에서 가져온 보상금이 여기 있소. 그대는 이 돈을 받을 자격이 충분하오. 우리 페더문 요새는 그대와 그대의 동료라면 언제나 대환영이오이다, 나의 친구여.\n\n그런데 떠나기 전에... 한 가지 더... 부탁할 것이 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2871] = {title = "유물 전달", objective = "페더문 요새에 있는 베스티아 문스피어에게 신비한 유물을 가져가야 합니다.", description = "이 유물을 내 아내 베스티아에게 가져다주면 고맙겠소. 내 아내는 우리 종족의 훌륭한 여사제일 뿐만 아니라 가장 박식한 학자 중 한 사람이기도 하오. 이 유물을 여는 방법에 내기가 걸려 있다고 해도 도무지 어떻게 돌아가는 건지 알 수가 없군. 내 아내라면, 그러니까 누군가 이 물건에 대해 아는 사람이 있다면 아마 내 아내일 것이오. 게다가 우리는 이 물건에 대해 꼭 알아내야만 하오!\n\n이 길을 꺾어 돌아가면 틀림없이 아내가 연구를 하고 있을 것이오. 고맙소, 친구.", progress = "안녕하세요. 제가 도와드릴 일이라도 있나요?\n\n가만, 당신이 페더문 장군님과 라트로를 도와 나가의 위협을 물리친 <class>|1이시죠;시죠;? 전 베스티아라고 합니다. 라트로의... 그러니까... 라트로니쿠스의 아내죠. 만나서 반갑습니다!\n\n오, 이런 죄송해요. 볼 일이 있어 오셨을 텐데 제가 쓸데없는 소리를 했네요. 혹시 라트로니쿠스에게서 뭘 가지고 오신 건가요?", completion = "재미있군요... 이게 솔라살 폐허에서 나온 것이라고요? 라트로 말이 내가 이걸 봐야 한다고 했었는데 그 말이 맞았군요. 한눈에 봐도 그 유적지에서 나올만한 물건이 아니에요. 나가가 만든 것도 아니고... 이런 물건은 정말 처음이네요.\n\n조사해보려면 시간이 좀 걸리겠어요. 조사가 끝난 후에도 이 근처에 계시면 그대의 재능을 빌려야 할지도 모르겠습니다.\n\n자, 이 물건 중 하나를 가져가도록 하세요. 그대에게 유용한 것을 찾을 수 있길 바랍니다!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n새벽기수의 흉갑파수꾼의 머리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2872] = {title = "스톨리의 빚", objective = "스팀휘들 항구에 있는 스톨리와 대화해야 합니다.", description = "내 오랜 친구 스톨리는 나에게 아주 특별한 럼주 한 병을 빚졌다오. 그 친구는 칼림도어의 타나리스에 있는 스팀휘들 항구에서 술집을 운영하는데 그곳의 럼주는 무법항에서 찾을 수 있는 다른 어떤 것보다 더 독하다고 하더군. 얼마나 자신 있어 하는지, 내가 그 술을 마셔 보고 그의 말에 동의하지 않는다면 내게 빚진 돈을 두 배로 갚겠다고 하는 거요!\n\n뭐, 지금은 우리가 지난번 얘기를 나눌 때만큼 그렇게 자신 있어 하는 것 같진 않지만 말이야. 이제는 내게 그 럼주를 주는 것을 꺼려하고 있다니까. 그렇지만 나는 내기에서 물러서는 성격이 못되니 내 대신 그 친구와 얘기를 나누어 보지 않겠소?", progress = nil, completion = "아, 맥킨리와 얘기를 한 거요?\n\n그건 그 친구가 생각하는 것과는 달라! 그 친구에게 스팀휘들 럼주를 주지 않으려는 게 아니라...\n\n사실은 럼주가 다 떨어졌거든!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2873] = {title = "스톨리의 뱃짐", objective = "스팀휘들 항구에 있는 스톨리에게 뱃짐을 찾아다 주어야 합니다.", description = "지금 럼주가 다 떨어지고 없소! 무법항의 바다 늑대, 맥킨리랑 건 내기에서 이기려면 럼주를 좀 줘야 하는데 말이오. 최근에 쿠에르고 선장이 내 뱃짐을 훔쳐서 해적 마을에 숨겨 두고 있다오. 성벽으로 둘러싸인 그 마을은 여기에서 남쪽에 있소.\n\n럼주가 들어 있는 내 뱃짐을 찾아와 준다면 칼림도어의 술이 무법항 것보다 훨씬 낫다는 걸 맥킨리에게 확실히 보여줄 수 있소이다!", progress = "럼주가 든 내 뱃짐은 찾았소?", completion = "아, 잘됐구먼. 뱃짐을 찾아다 줘서 고맙소! 드디어 맥킨리가 내기에서 진 걸 깨끗이 승복하겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2874] = {title = "맥킨리에게 배달", objective = "무법항에 있는 \"바다늑대\" 맥킨리에게 칼림도어산 럼주가 든 스톨리의 병을 가져가야 합니다.", description = "다시 한번 도와줘서 고맙다는 말을 하고 싶소. 여기 스팀휘들 럼주가 한 병 있소. 이걸 맥킨리에게 갖다주면 그 친구도 마침내 무법항 술에 대한 그 맹목적인 믿음을 버릴 수 있을 거요.", progress = "스톨리가 내 술을 내놓습디까?", completion = "흠, 어디 한번 마셔 볼까...\n\n믿을 수 없군! 이 술... 아주 독하군! 이거 훌륭한 걸!\n\n뭐, 내기에서 스톨리에게 완전히 졌고 돈도 받을 수 없지. 스팀휘들 럼주에 대한 그의 말이 사실이었으니... 이 술은 정말 진하고 화끈하군!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n모험가 장식띠통발굽 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2875] = {title = "현상수배: 앙드레 파이어비어드", objective = "앙드레를 처치하고 그 증거로 그의 머리카락을 스팀휘들 항구에 있는 보안과장 빌지위즐에게 가져가야 합니다.", description = "스팀휘들 항구와 가젯잔을 휩쓸고 다니는 사악한 해적 앙드레 파이어비어드를 현상수배한다.\n\n이 글을 읽는 모든 이에게 허가한다! 의회의 판결에 따라 앙드레와 공범들을 체포할 때 죽음을 불러올 정도의 힘을 사용해도 좋다.\n\n앙드레가 죽거나, 심하게 다쳐서 보안과장 빌지위즐에게 호송하지 못할 경우 그의 머리카락을 잘라서 증거로 가져가도 현상금을 받을 수 있다.", progress = "당신 표정이 좀 어리둥절해 보이는데... 우리 법률 문서 나부랭이를 읽고 있었던 거요?", completion = "아, 앙드레의 머리카락 아닌가? 결국, 그가 죽음으로 심판을 받게 됐군.\n\n정말로 고맙소. 여기 서명만 하시오. 그래야, 현상금을 지급해 줄 수 있으니까.\n\n깨알같은 글자로 적힌 내용은 신경 쓰지 마시오. 손해가 되는 내용은 없으니... 그리고 요렇게 조그만 글씨를 확대할 만한 돋보기도 없지 않소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2876] = {title = "선적 일정표", objective = "스팀휘들 항구의 관계자에게 선적 일정표에 대해 보고하십시오.", description = "이 두루마리에는 스팀휘들 항구와 무법항 간의 뱃짐 운송 일정이 기록되어 있습니다. 처리를 완료한 일정과 앞으로 예약된 일정들이 선박의 이름 옆에 적혀 있습니다. 일부 항해 일정 옆에는 크게 X자로 표시가 되어 있고 어떤 것에는 \"대단한 전리품\"이나 \"치열한 전투\"와 같은 주석이 달려 있습니다.\n\n스팀휘들 항구의 누군가가 이 문서를 보고 싶어할 것입니다.", progress = "숨이 턱까지 찼군요. 무슨 일이 있나요?", completion = "이런, 이건 선박의 출입항 목록 같은데... 정확한 날짜와 시간이 모두 적혀 있군요! 해적단 선장이 이걸 손에 넣게 되면 아주 횡재하겠어요!\n\n아니, 이걸 해적에게서 찾았다고요? 그렇다면 불안한 소식이군요...\n\n아무튼 감사합니다, &lt;name&gt;. 당신이 이걸 빼앗아 와서 다행이에요. 그리고 해적단에게도 한 방 먹였다니 너무 고소하군요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2877] = {title = "굼벵이 바위굴 청소", objective = "녹색 녹괴물 10마리와 비취 수액괴물 10마리를 처치한 후 맹금의 봉우리에 있는 프라가르 썬더맨틀에게 돌아와 보고하십시오.", description = "우리 와일드해머는 아이언포지의 형제들보다 과거를 더 잘 기억한다네. 여기서 친구를 사귀고 싶다면 우리 대신 지저분한 일을 좀 맡아 줘야겠어!\n\n동부 내륙지에 있는 굼벵이 바위굴에서 호드가 물러났네. 이제 그곳은 고약한 녹괴물과 수액괴물이 득실거리지. 우리에게 그 지역에 대한 계획이 있네. 우리가 그곳으로 가기 전에 일꾼을 시켜 먼저 청소를 해놓는 거지.\n\n바로 자네가 적임자일 것 같군! 그곳으로 가서 녹색 녹괴물 10마리와 비취 수액괴물 10마리를 제거한 후에 돌아와 내게 보고하게. 출발!", progress = nil, completion = "와일드해머를 돕다니 정말 장한 일이야! 자네는 행동으로 의지를 보여 줄 줄 아는 &lt;class&gt;|1이야;야;. 그야말로 우리가 존중하는 태도지.\n\n자네 생각처럼 청소라는 것이 시시한 일은 아니라네. 훨씬 더 중요하지. 수액괴물과 녹괴물이 줄어들고 있으니 머지않아 우리의 영향권을 확장할 수 있을 걸세. 자, 이걸 받아두게. 자네가 맹금의 봉우리에서 새로 사귄 친구, 이 프라가르님이 주는 것이야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2878] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[2879] = {title = "에퀴넥스의 지팡이", objective = "트로야스의 지팡이에 힘을 불어넣고 에퀴넥스 비석탑을 찾아야 합니다.", description = "이 지팡이는 에퀴넥스의 지팡이일지도 모르겠군. 에퀴넥스의 지팡이는 꿈나무의 중앙 지역 서쪽에 있는 까마귀바람 폐허에 에퀴넥스 비석탑을 열 수 있는 열쇠요.\n\n그 폐허에서 아직도 타오르고 있는 삼하, 임벨, 빌탄, 라하사의 네 가지 불꽃을 찾아 그 정기를 받으시오. 그 후 에퀴넥스 비석탑 곁에 서서 그 정기를 사용하여 이 지팡이에 힘을 불어넣으시오. 이것이 정말 에퀴넥스의 지팡이라면 그 비석탑을 열고 안에 든 성스러운 유물을 얻을 수 있을 것이오.", progress = "폐허 가운데 에퀴넥스 비석탑이 고요히 서 있습니다. 안에 무엇이 든 것일까요?", completion = "힘을 불어넣은 지팡이를 들고 있는 것은 거의 불가능합니다. 그 힘이 몸 전체를 뒤흔듭니다.\n\n에퀴넥스 비석탑의 차가운 표면에 손을 뻗습니다...\n\n작은 문이 열린 곳 속으로 손을 뻗어 그 안에 든 유물을 꺼낼 수 있게 됩니다.\n\n빛의 광선이 에퀴넥스 비석탑 주변을 가득 채웁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n반짝이는 돌"},
[2880] = {title = "트롤 목걸이 현상금", objective = "맹금의 봉우리에 있는 프라가르 썬더맨틀에게 트롤 전통 목걸이 5개를 가져다주어야 합니다.", description = "이것만은 분명히 알아두게. 우리는 엄밀히 말해서, 얼라이언스의 일원이 아니야! 와일드해머 부족은 독립된 부족으로서 개인의 가치를 행동과 업적으로 평가하지. 실제로는 아무 일도 안 하면서 실속없이 입만 살아있는 자들은 쳐주지 않는단 말이지!\n\n우리의 친구가 되고 싶다면 먼저 자네의 가치를 증명해 보이게! 동부 내륙지의 언덕 부근에 득실거리는 더러운 트롤 녀석들은 종종 전통 목걸이를 지니고 다닌다네. 내게 그 목걸이 5개를 가져오게. 그러면 한 단계 통과한 것으로 인정해 주지.", progress = "트롤 녀석들이 지니고 다니는 전통 목걸이 5개를 가져다주게. 더 자세히 설명해야 하나? 놈들을 처치하면 목걸이를 얻을 수 있을 걸세!\n\n우리 와일드해머에 자네의 가치를 증명해 보게!", completion = "그렇지, 바로 이거야! 이 목걸이는 자네가 기꺼이 손에 피를 묻힐 의지가 있다는 것을 증명해 주고 있네. 우리 와일드해머는 그런 점을 높이 평가하지.\n\n앞으로도 계속 이런 자세를 보여준다면 우리의 친구가 될 수 있겠는 걸.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2881] = {title = "트롤 목걸이 현상금", objective = "트롤 전통 목걸이를 더 찾아서 가지고 온다면 계속해서 받아주겠네. 목걸이를 가져온다면 자네는 와일드해머에서 명성을 쌓을 수 있을 걸세. 계속해서 우리를 위해서 싸울 의지를 보여준다면 언젠가 우리도 자네를 도울 날이 있을 걸세!\n\n트롤 전통 목걸이는 적어도 5개씩 가져와야 하네.", description = nil, progress = "트롤 전통 목걸이를 더 찾아서 가지고 온다면 계속해서 받아주겠네. 목걸이를 가져온다면 자네는 와일드해머에서 명성을 쌓을 수 있을 걸세. 계속해서 우리를 위해서 싸울 의지를 보여준다면 언젠가 우리도 자네를 도울 날이 있을 걸세!\n\n트롤 전통 목걸이는 적어도 5개씩 가져와야 하네.", completion = "목걸이를 또 가져왔다는 건 동부 내륙지에서 성가신 트롤의 수가 그만큼 줄었다는 뜻이지! 또 해냈군, &lt;name&gt;. 계속 수고해주면 고맙겠네!", rewards = nil},
[2882] = {title = "쿠에르고 골드", objective = "쿠에르고 골드를 찾으십시오.", description = "이 지도에는 남쪽을 향해 넓게 펼쳐진 해변이 그려져 있습니다. 지도 아래 쪽에는 우아한 필체의 글이 쓰여 있습니다.\n\n\n스팀휘들 항구의 남쪽...\n내 고향의 남쪽...\n돛대와 깃발, 그리고 뼈를 찾아라!\n\n용기가 있는 자여, 그곳을 파라.\n쿠에르고 골드를 손에 넣어라!\n열쇠를 찾아라.\n\n적들의 피를 보리라.", progress = "궤짝이 잠겨 있습니다!", completion = "쿠에르고의 숨겨진 보물이 당신을 기다리고 있습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n쿠에르고의 숨겨진 보물"},
[2902] = {title = "덩굴발일족 조사", objective = "모자케 야영지 남쪽에 있는 놀 야영지에서 덩굴발일족 전투계획서를 찾아야 합니다.", description = "놀들은 머리가 썩 좋은 편은 아니지만 적어도 최근 활동에 대한 전략 문서 같은 것을 분명 갖고 있을 것이오. 우리가 그 계획서를 손에 넣는다면 녀석들을 그렇게 흥분하게 만든 원인에 대해 좀 더 확실히 알 수 있을 것이오.\n\n덩굴발일족 녀석들의 야영지로 되돌아가서 전투 계획서처럼 보이는 것이 있으면 뭐든 가져오시오. 전투 계획서가 없이 감행한 공격이라고 보기에는 무척 계획적이었으니 분명 뭔가 갖고 있을 거야. 가서 찾아보고 계획서를 손에 넣거든 내게 가져오시오.", progress = nil, completion = "작전도를 살펴보니 이것이 아도겐 스위프트스트라이더가 원하는 전투계획서라는 것을 알 수 있습니다. 작전도에는 군대의 움직임을 나타내는 듯한 수많은 화살표가 그려져 있는데 대부분 모자케 야영지가 있는 북쪽이 아니라 남쪽을 향하고 있는 듯합니다.\n\n작전도의 다른 부분에는 커다란 곤충 같은 것의 그림이 있고 그 밑에 여러 종류의 표시가 있습니다. 놀 모양으로 보아 정체불명의 벌레들에게 당한 놀 피해자들을 나타내는 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2903] = {title = "전투 계획서", objective = "모자케 야영지에 있는 아도겐 스위프트스트라이더에게 덩굴발일족 전투계획서를 가지고 가야 합니다.", description = "놀의 전투계획서를 찾았으니 이제는 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 가져가는 일만 남았습니다. 아도겐 스위프트스트라이더나 모자케 야영지에 있는 누군가가 놀의 의도를 더 정확히 파악할 수 있을 것입니다.", progress = "돌아왔군. 놀의 계획과 관련한 증거는 입수했소?", completion = "아, 우리가 원하던 게 바로 이것이오. 이 지도에 휘갈긴 것들이 무엇인지 이해할 만큼 내 솜씨가 좋은 건 아니지만, 그동안 전투 계획서를 많이 접해봤으니 놀에게 무슨 일이 일어나고 있는지 정도는 알아낼 수 있을 것이오. 음, 녀석들은 현재 양면전을 하고 있는 것 같군. 한쪽은 우린데... 보아하니 남쪽에 있는 적에게 주력을 가하고 있는 것 같소.\n\n이 지도에는 보기보다 훨씬 중요한 정보가 있군. 놀들이 맞서고 있는 다른 적이 무엇인지 알아야 할 때일지도 모르겠소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n흙걸쇠 철벽방패산마루 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2904] = {title = "곤경에 빠진 케르노비", objective = "태엽장치 통로 입구까지 케르노비를 호위한 후 무법항에 있는 스쿠티에게 가서 보고해야 합니다.", description = "<신음하는 케르노비> 어... 어떻게 된 거죠?\n\n마지막으로 기억나는 건 검은무쇠단 드워프들에게 붙잡혀 거의 죽을 만큼 얻어맞고, 여기 이 더러운 트로그놈들 무리에 내동댕이쳐진 것뿐인데...\n\n제발 여기서 빠져나가게 도와주세요!\n\n이렇게 하죠. 출구로 절 데려다 주세요. 그리고 출구까지 살아나가면 무법항으로 가세요. 거기서 스쿠티를 만나 제가 톱니항의 팅커위즈에게 가더라고 전해주세요. 그 거대한 장치를 만드는 데 검은무쇠단 드워프가 관련됐다는 사실을 알려야 하거든요.\n\n어서 가죠!", progress = nil, completion = "케르노비를 무사히 구출해준 공로에 대해 보답을 해야겠군. 놈리건으로 돌아갈 때 이걸 가져가면 그 배신자 멕기니어 텔마플러그 놈을 물리치는 데 도움이 될 거요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n용접 팔보호구요정날개 어깨보호대\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2922] = {title = "고장난 첨단로봇 수리", objective = "아이언포지에 있는 수석땜장이 오버스파크에게 첨단로봇의 기억회로를 가져가야 합니다.", description = "우리가 사랑했던 도시 놈리건이 무너졌을 때, 불행하게도 내가 만든 첨단로봇이 전기 불꽃에 맞아 충격을 입은 모양이오. 한때 수많은 장치와 무제한의 저장 공간으로 우리를 도왔는데 지금은 녀석의 양전자 두뇌가 분극화된 모양이오. 이제는 음전자 성질을 띠어... 첨단로봇의 행동이 완전히 거꾸로 바뀌어 버린 거요. 녀석은 놈리건에서 광포한 행동을 일삼으며 돌아다니고 있소이다!\n\n하지만 녀석을 구할 수 있을지도 모르오. 당신이 첨단로봇의 기억회로를 내게 가져오면 그 분극 작용의 원인을 알아내서 불쌍한 첨단로봇을 고칠 수 있을지도 모르오.\n\n", progress = "첨단로봇은 찾았소? 기억회로는 어떻게 됐소??", completion = "아, 아주 잘 됐군! 고맙소! 곧바로 작업을 시작하겠소이다!!\n\n저런, 불쌍한 첨단로봇... 조금만 참거라. 우리가 고쳐 줄 테니까 말이야.\n\n어디 보자, 유압잭 회전 고리 스패너 플러그를 어디에 뒀더라...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2923] = {title = "수석땜장이 오버스파크", objective = "아이언포지에 있는 수석땜장이 오버스파크와 대화하십시오.", description = "수석땜장이 오버스파크가 자신이 만든 첨단로봇 때문에 매우 속상해 하고 있소. 내가 기억하기로 첨단로봇은 노움들에게 아주 쓸모 있는 도구였던 것 같은데 오버스파크 얘기로는 그 로봇이 완전히 고장났다고 하더구먼.\n\n아주 슬픈 일이야. 하지만 재수가 좋으면 고칠 수 있을지도 모르지!\n\n아이언포지의 땜장이 마을에 있는 수석땜장이 오버스파크와 얘기해 보시오. 당신을 아주 반길 거요.", progress = nil, completion = "사실이오. 첨단로봇이 말썽을 부리고 있다니까! 나 좀 도와 주지 않겠소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2924] = {title = "필수 인공장치", objective = "아이언포지에 있는 클락몰트 스패너스판에게 필수 인공장치 12개를 가져가야 합니다.", description = "필수 인공장치라는 부품은 다양한 곳에 두루 사용되기 때문에 놈리건 땜장이와 대장장이들에게는 없어서는 안 될 물건이죠. 그런데 고향에서 정신 없이 탈출해 나올 때 모두 깜박 잊고 그 장치들을 놓고 나온 거예요! 곧 착수해야 하는 일에 그 장치가 많이 필요하답니다.\n\n제발 부탁이에요. 놈리건으로 가서 필수 인공장치를 좀 가져다주세요. 깊숙이 들어가면 인공장치 검출기라는 것에서 꺼낼 수 있을 거예요.\n\n부디 서둘러 주세요. 도움을 주시면 감사하겠어요!", progress = "필수 인공장치를 가져왔나요?", completion = "가져왔군요! 이제 새로운 실험을 시작할 수 있게 됐어요!\n\n뭐라고 감사의 말을 해야 할지 모르겠네요! 예부터 당신과 같이 용감한 분의 도움이 있었기에 노움의 연구도 이만큼 진척된 것이랍니다!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2925] = {title = "클락몰트에게 꼭 필요한 것", objective = "아이언포지에 있는 클락몰트 스패너스판과 대화하십시오.", description = "내 노움 친구, 클락몰트 스패너스판이 아이언포지에서 소식을 전해 왔소. 극히 중요한 임무를 수행하기 위해 놈리건으로 위험을 무릎 쓰고 떠나는데 도움이 필요하다는 거요. 놈리건은 한때 위대한 노움 도시였지만 지금은 오염되어 버렸고 제정신이 아닌 노움들과 여러 가지 기괴한 장치들로 가득 차 있소.\n\n나는 이곳을 떠날 수 없지만 내 친구를 꼭 도와 주고 싶소. 당신이 내 대신 가 준다면 정말로 고맙겠소.\n\n클락몰트는 아이언포지의 땜장이 마을에 있소.", progress = nil, completion = "그래요! 중대한 임무를 수행하기 위해 놈리건으로 떠나는데 도움이 필요해요! 당신 같은 &lt;class&gt;|1이라면;라면; 아주 딱이죠!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2926] = {title = "폐기물 수집", objective = "빈 가연채집병에 오염된 침략꾼이나 오염된 약탈자에게서 얻은 방사성 폐기물을 담아야 합니다. 채집병이 가득 차면 카라노스에 있는 오지 토글볼트에게 가지고 가야 합니다.", description = "그 사고가 난 뒤부터 노아른은 놈리건에 남아 있는 트로그 녀석들을 쫓아내고 그곳에 퍼진 질병을 치료할 방법을 찾는 데만 온 신경이 쏠려 있소.\n\n다행히도 라즐과 내가 치료약 비슷한 걸 만들어 냈지. 잘 되면 치료약이 될 테고 못해도 독한 럼주가 되는 액체인데 실험을 해보기 전까지는 아무것도 알 수 없소! 따라서 우리 가설을 확인해보려면 몇 가지 물건이 필요하오. 우선 놈리건에 있는 오염된 트로그들에게서 녹색 방사성 폐기물을 채취해 이 병에 채워다 주시오!", progress = "노움족 전체를 치료할 비약을 만들고 있는 게 안 보이는 거요?? 그 녹색 폐기물이 꼭 필요하단 말이오!", completion = "잘했소! 새 약품을 시험해볼 때가 되었군. 성공하기만 하면 여기 사로잡힌 오염된 노움을 치료할 수 있을 뿐만 아니라 내 대머리 증세도 치료할 수 있소! 물러서 있으시오!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2927] = {title = "그날 이후", objective = "카라노스에 있는 오지 토글볼트와 대화하십시오.", description = "내 머리숱이 항상 이렇게 적었다고 생각하는 건 아니겠지? 절대 아니오! 이 비극적인 탈모 증상은 놈리건에서 발생한 방사선 유출 때문이라오. 그전에는 내가 아제로스에서 최고로 풍성한 머리를 한 노움이었는데!\n\n<허공에 대고 주먹을 휘두르는 노아른>\n\n망할 놈의 트로그들, 모두 없어져 버려라!\n\n어쩌면 너무 늦지 않았을지도 몰라. 구할 수 있을지도... 아, 내 머리숱 말고 우리 고향 말이오! 카라노스에 있는 오지 토글볼트와 얘기를 해보시오. 그와 라즐이라는 친구가 치료약을 만들고 있소.", progress = nil, completion = "그 친구, 멋진 머리카락이 다 빠진 후 완전히 끝장난 줄 알았는데 아직 살아 있군그래!\n\n노아른이 방사능 광선을 맞을 때 바로 옆에 내가 서 있었소. 그 숱 많던 갈색 머리카락이 모두 엉켜 붙더니 바닥에 툭 떨어지지 뭐요. 다발 채로 말이오! 그 친구가 완전히 실성을 하면서 사태는 더욱 심각해졌소. 말도 마시오! 노아른 그 친구, 믿지 못하겠다는 표정으로 완전히 벗겨진 자기 정수리를 쓰다듬더니 눈에 복수의 살기를 번득이더군! 그러더니 그 분노를 트로그들에게 돌렸다오!\n\n&lt;얼굴을 찡그리는 오지&gt;", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2928] = {title = "회전천공식 발굴기", objective = "스톰윈드에 있는 쇼니에게 기계장치 부속품 24개를 가져가야 합니다.", description = "정말 암울하네요. 우리 회전천공식 발굴기 부대를 던 모로로 보낼 수 있을 정도로 부품이 충분하지 못할 것 같답니다.\n\n여분의 부품이 필요합니다. 우리 발굴기를 위한 여분의 부품을 얻기에 놈리건보다 더 좋은 곳은 없죠. 그곳에서는 로봇과 기계들이 넓은 초원에 소떼 돌아다니듯 한다고 들었어요.\n\n놈리건으로 가서 그 로봇들을 분해해 부속품을 가져와 주세요. 24개면 충분할 거예요.", progress = "이게 경주였다면 당신은 벌써 지고 말았을 거예요.", completion = "이거면 되겠네요. 회전천공식 발굴기 하나 수리 완료. 앞으로 398개 남았군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n쇼니의 작업용 연장망설임의 장갑\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2929] = {title = "대배반", objective = "놈리건으로 가서 멕기니어 텔마플러그를 처치해야 합니다. 임무가 끝나면 땜장이왕 멕카토크에게 돌아와야 합니다.", description = "나는 텔마플러그를 믿었는데, 설마 노움족 전체를 배반하리라고는 꿈에도 생각하지 못했네. 도대체 이유가 뭐란 말인가? 부? 권력? 시간이 지나면 모두 다 가질 수 있었을 것을... 쯔쯔... 지금 우리는 고향에서 쫓겨난 신세라네. 그 미치광이 독불장군이 그곳을 점령했지.\n\n우리는 놈리건을 되찾을 것이고 그때까지 결코 멈추지 않을 걸세. 우리의 투쟁을 도울 생각이 있다면 자네가 꼭 해줬으면 하는 임무가 있네. 반역자 멕기니어 텔마플러그를 처치하게.", progress = nil, completion = "녀석의 머리가 자네의 발 끝을 스치며 땅에 쓰러질 때를 내 눈으로 봤어야 하는 건데... 텔마플러그가 죽었으니 놈리건을 되찾기 위한 우리의 계획이 한걸음 더 현실에 가까워졌네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n선민의 로브출장용 작업복이중 강화 다리보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2930] = {title = "자료 회수", objective = "아이언포지에 있는 수석수리공 캐스트파이프에게 오색 천공 카드를 가져가야 합니다.", description = "놈리건에서 도망쳐 나올 때 대량의 자료를 두고 나왔다네! 굉장히 중요한 자료인데 말이야!\n\n놈리건 깊숙이 있는 행렬 천공기록기 3005-D의 고급 보안 터미널을 통해 자료를 오색 천공 카드에 담아 와야 해. 터미널에 접근하려면 보안 허가가 필요한데... 보안 허가를 받으려면 하급 보안 터미널인 모델 A, B, C에 먼저 접근해야 하지. 그리고 그 하급 터미널에 접근하려면 보안 천공 카드가 필요하고. 그 카드는 흰색인데 말이야... 놈리건에서 찾을 수 있다네.\n\n어떤가, 정말 철통 같은 보안 아닌가? 도와 줄 수 있겠나?", progress = "오색 천공 카드는 가져온건가?", completion = "해냈군! 오색 천공 카드를 찾아서 잃어버린 자료를 회수했어! 우리 노움의 사활이 걸린 정도로 필수적이고, 중요하고, 방대한 자료를 말이야!\n\n자네가 해준 이번 일은 우리 노움의 역사에 길이 남을 것이네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n수리공의 단망토수리공의 파이프망치"},
[2931] = {title = "캐스트파이프의 임무", objective = "아이언포지에 있는 수석수리공 캐스트파이프와 대화하십시오.", description = "아이언포지에 있는 수석수리공 캐스트파이프가 일손을 필요로 하고 있소! 극비 임무로 자료를 회수하기 위해 놈리건으로 다시 들어갈 모험가들을 모집하고 있다고 하더군.\n\n캐스트파이프는 나처럼 비전술, 연금술을 비롯해 기계공학 연구회의 회원은 아니지만, 아주 영리한 노움이라서 그가 중요하다고 하면 정말로 중요한 일일 가능성이 내 계산으로는 84%요!\n\n아주 높은 확률 아니겠소?", progress = nil, completion = "난 놈리건에서 자료를 회수할 임무를 준비하고 있는 중일세. 그것 때문에 이곳에 왔다면 내 말 잘 듣도록 하게!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2932] = {title = "준엄한 메시지", objective = "동부 내륙지에서 마른나무껍질부족 해골을 모은 후, 님보야의 창을 동부 내륙지에 있는 마른나무껍질 마을 중 한곳에 박아 놓아야 합니다. 그런 다음 가시덤불 골짜기에 있는 님보야에게 돌아가십시오.", description = "한때 마른나무껍질 트롤들은 호드의 동지였지만 지금은 스랄님을 배반했소이다... 반드시 응징해야 하오!\n\n자, 내 창을 줄 테니 멀리 북쪽에 있는 동부 내륙지로 가지고 가시오. 우리 호드의 동지 포세이큰들이 살고 있는 타렌 밀농장에서 북동쪽으로 가시오.\n\n동부 내륙지에 들어서면 마른나무껍질부족 트롤들이 눈에 뜨이는 족족 잡으시오. 녀석들의 해골을 모으고 내 창을 그들의 작은 마을인 히리와타나 준와타 중 한 곳에 박아 놓으시오.\n\n사악한 행동에는 반드시 처벌이 따른다는 것을 보여 주시오!", progress = nil, completion = "임무를 성실히 수행했다고 들었소. 준엄하면서도 명예로운 행동이오. 당신이 전한 메시지를 마른나무껍질부족이 가슴 깊이 새겼기를 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2933] = {title = "독병", objective = "타렌 밀농장에 있는 연금술사에게 독병을 가져가야 합니다.", description = "이 병 안에는 사악한 녹색 독이 들어 있습니다.\n\n이 마을에 깔려 있는 독병의 수를 감안하면 마른나무껍질부족이 상당히 중요하게 여기는 것 같습니다. 근처의 타렌 밀농장에 있는 연금술사가 견본을 원할지도 모릅니다.", progress = "안녕하시오, <class> 양반. 하루종일 애써 봤지만 하나도 성공한 실험이 없구려... 당신이 즐거운 소식을 가져온 거라면 좋겠소.", completion = "아, 이게 뭐요? 독인 것 같은데... 거미류 생물에게서 추출한 것 같군. 그런데 이걸 어디서 구한 거요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2934] = {title = "온전한 독주머니", objective = "타렌 밀농장에 있는 연금술사 라이던에게 온전한 독주머니를 가져가야 합니다.", description = "당신이 가져온 것보다 신선한 독의 견본이 필요하오. 이 독은 분명 동부 내륙지에 서식하는 거미에서 추출했을 거요. 녀석들을 잡아서 온전한 독주머니를 찾아 내게 가져와 주시오. 트롤들의 도시인 샤드라알로에 가면 거미를 많이 볼 수 있을 거요.\n\n늑장 부리지 마시오. 독주머니는 반드시 신선한 상태로 가져와야 하니까.", progress = "온전한 독주머니는 가져오셨소? 난 반드시 신선한 상태의 독으로 실험을 해보고 싶소. 실험용으로 쓸 끔찍하게 귀엽고 작은 동물들도 벌써 주문해 놓았단 말이오!", completion = "아, 아주 훌륭하오! 이 독은 상당히 신선하군. 분명 아주 치명적인 독일 거요. 고맙소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2935] = {title = "가드린 장로와 상의", objective = "센진 마을에 있는 가드린 장로와 대화하십시오.", description = "혈거미에게서 얻은 독은 당신이 애초에 가져왔던 것만큼 독성이 강하지 않았소. 아마 처음 것은 다른 거미에게서 얻은 것 같소.\n\n그 독의 신선한 견본이 있었으면 좋겠소. 그 독이 어디서 난 것인지 알려면 마른나무껍질부족을 잘 아는 트롤과 상의를 해야 할 거요. 센진 마을의 가드린 장로라면 그 부족에 대해 많은 걸 알려 줄 거요. 듀로타로 가서 가드린과 얘기해 보시오. 운이 좋으면 마른나무껍질부족이 어디서 그 독을 구하는지 그가 알고 있을지도 모르오.", progress = nil, completion = "아, 그러니까 마른나무껍질부족의 거미에게서 신선한 독을 구하고 싶단 말이지? 자, 앉아 보게... 내가 해줄 말이 그렇게 반갑지는 않을 테니...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2936] = {title = "거미 신", objective = "데카의 서판을 읽고 마른나무껍질부족 거미 신의 이름을 알아낸 후, 가드린 장로에게 돌아가십시오.", description = "마른나무껍질부족은 거미 신을 숭배한다네. 그 거미 신에게서 아주 강한 독을 모으지. 그러니 그 독을 원한다면 그들의 신을 소환해야만 하네!\n\n그렇게 하려면 그 거미 신의 진짜 이름을 알아야 하는데 그 이름은 타나리스의 트롤 도시, 줄파락에 묻혀 있는 서판에 적혀 있어. 이 서판은 순교자 데카가 지키는 무덤 안에 있지.\n\n데카를 물리치고 서판에서 거미 신의 이름을 알아내게. 이름을 알아내거든 내게 돌아오게나.", progress = nil, completion = "엘로르타 노 샤드라... 이 이름은 반드시 속삭이듯 작은 소리로만 말해야 하네. 영혼의 세계에서는 이 이름을 부르는 것이 큰 의미를 지니는 일이니 말일세.\n\n양피지에 이름을 적어서 소환 마법을 하나 만들어 줌세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2937] = {title = "샤드라 소환", objective = "샤드라알로 제단에서 샤드라를 물리친 후, 그녀의 독을 타렌 밀농장에 있는 연금술사 라이던에게 가져가야 합니다.", description = "이 양피지를 받게. 동부 내륙지에 있는 마른나무껍질부족 영토 깊숙이에 있는 샤드라알로 제단에서 이걸 읽으면 거미 신 샤드라가 소환될 걸세.", progress = "독은 가져오셨소?", completion = "드디어 가져오셨군!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2938] = {title = "언더시티로 독 가져가기", objective = "언더시티에 있는 수석 연금술사 파라넬에게 파라넬의 소포를 가져가야 합니다.", description = "마른나무껍질부족의 거미 신에게서 얻은 이 독은 아주 대단한 물건이오! 한 방울로 족히 20마리가 넘는 토끼를 죽일 수 있으니까 말이오. 토끼야 물론 맨주먹으로 잡을 수 있을 만큼 작은 것들이라 분명 독에 대한 저항력도 낮겠지만, 그래도 이 독이 강력하다는 건 부인할 수 없는 사실이오!\n\n언더시티 연금술 실험실에 계시는 내 상관인 파라넬 연금술사께 이 독의 견본을 보내고 싶소. 그 분도 이 독을 직접 시험해 보고 싶어하실 거요.", progress = "자네가 온다는 소식을 들었네. 소포를 가져온 모양이지?", completion = "아, 잘 됐군. 라이던 얘기로는 이 소포 안에 든 독은 자기가 보던 것들 중에서 가장 강한 것이며 새로운 응용 방법을 연구하느라 바쁘다고 하더군.\n\n운이 따라 주면 여러 가지 방법을 찾게 되겠지.\n\n고맙네. 왕립 연금술 학회를 위한 자네의 노고를 치하하는 바이네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n왕실 의복의장병 흉갑전투의 아이기스\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2939] = {title = "지식을 찾아서", objective = "루테란 마을에 있는 다린 라이트윈드와 대화해야 합니다.", description = "엘룬께 영광을. 페랄라스의 폐허는 매우 위험할 수 있지만 이곳에서 일어났던 일들에 대해 많은 것을 알아낼 수 있소...\n\n며칠 전 남쪽에 있는 부스러기 더미를 뒤지다 평범해 보이는 지팡이 하나를 발견했는데 단순히 평범한 지팡이가 아닐지도 모른다는 생각을 떨칠 수가 없소이다. 안젤라스와 내가 여기 있는 책이란 책들은 다 뒤져 봤지만 아무것도 알아낼 수가 없었소.\n\n다르나서스에 있는 내 동료라면 이게 무엇인지 얘기해 줄 수 있을 것이오. 그녀가 우리를 도울 수 있는지 가서 그녀를 만나서 얘기해 보는 게 어떻겠소?", progress = nil, completion = "아, 트로야스 문브리즈가 보냈다고요?\n\n&lt;중얼거리며&gt;... 그 친군 항상 중요한 걸 찾았다며 말도 안 되는 소리나 늘어놓으면서 귀찮게 군단 말이지...\n\n보세요, 솔직하게 얘기하죠. 트로야스는 항상 그 폐허에서 뭔가 중요한 걸 찾았다고 생각한답니다. 하지만 실상 정말로 값진 것들은 이제 그곳에서 사는 오우거나 하피들이 오래전에 다 챙겨갔을 텐데 말이에요.\n\n얼마든지 둘러보아도 괜찮지만 여기에 도움이 될 만한 책이 있을지는 모르겠군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2940] = {title = "페랄라스의 역사", objective = "다린 라이트윈드에게 책을 빌려도 좋은지 물어봐야 합니다.", description = "이 책은 오랫동안 아무도 펼쳐 보지 않은 것 같아 보입니다. 표지는 꽤 낡았고 책장은 누렇게 변색하였지만 잘 살펴보니 바로 이것이 트로야스가 찾고 있는 것이라는 걸 알게 됩니다.\n\n책을 집어듭니다. 하지만 빌리기 전에 먼저 주인에게 물어 봐야할 것입니다.", progress = nil, completion = "'페랄라스의 역사'란 책을 빌리고 싶다고요?\n\n잠깐 생각해 보죠...\n\n좋습니다, 그 책을 빌려가도록 하세요. 하지만 먼저 내 부탁을 들어줘야겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2941] = {title = "사진기 대여", objective = "타나리스에 있는 커글 크랭크홉에게 짧은 쪽지를 가져가야 합니다.", description = "나는 그동안 많은 것들을 연구했답니다. 최근에는 동부 내륙지의 해변을 점령하고 있는 무쇠턱거북에 푹 빠져 있지요. 특히 감메리타라는 거대한 무쇠턱거북을 직접 가서 보고 싶은데 연구해야 할 게 있어 이곳을 떠날 수가 없군요. 그 거북의 사진을 보는게 제일 좋을 것 같은데 말이죠.\n\n이 쪽지를 타나리스에 있는 커글 크랭크홉에게 가져가도록 하세요. 그녀가 날 위해 단숨에 사진을 찍을 수 있는 발명품을 만들었답니다. \"즉석사진기\"라고 불렀던 것 같은데...", progress = "편지요? 저한테요?", completion = "다린의 실습생 중 한 분이신가 보죠? 다린은 지식이 아주 풍부한 역사가죠. 그녀 밑에서 수학하는 걸 감사하게 생각해야 한다고요.\n\n자, 슈퍼 찰칵이 FX를 가져오도록 하죠. 마음에 쏙 들 거예요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2942] = {title = "반짝이는 돌", objective = "페더문 요새에 있는 트로야스 문브리즈에게 반짝이는 돌과 에퀴넥스의 지팡이를 가져가야 합니다.", description = "비석탑에서 유물을 꺼내자마자 에퀴넥스의 지팡이의 힘이 사라지기 시작하는 것이 느껴집니다.", progress = "돌아온 걸 보니 기쁘오. 뭘 찾았는지 어디 한번 들어 보고 싶소.", completion = "그대가 떠난 이후 난 계속 책을 읽고 있었소. 그대가 찾아 온 이 돌은 여명의 돌이라고 하는데 용도가 뭔지는 아직 나도 잘 모르겠소이다. 그런 식으로 에퀴넥스 비석탑 안에 숨겨져 있을 정도면 상당히 중요한 것이라는 건 확실하군.\n\n계속해서 조사를 진행하는데 앞으로도 그대의 도움을 받을 수 있었으면 좋겠소. 도와줘서 고맙소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n묘석 은마법봉새싹 고리\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2943] = {title = "트로야스에게 돌아가기", objective = "페더문 요새에 있는 트로야스 문브리즈에게 책을 가져가야 합니다.", description = "여기 있습니다. 내 책을 조심해서 다루도록 하세요.\n\n자, 트로야스가 당신이 돌아오길 무척 기다리고 있을 테니 서두르도록 하세요.", progress = "어서 오시오. 다르나서스에는 가 봤소?", completion = "책을 가져왔군. 아주 잘했소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2944] = {title = "슈퍼 찰칵이 FX", objective = "슈퍼 찰칵이 FX로 감메리타의 즉석사진을 찍은 후, 루테란 마을에 있는 다린 라이트윈드에게 돌아가야 합니다.", description = "제가 새로 발명한 물건을 한번 보세요. 사진을 찍고 싶은 대상을 선택하고 단추를 누르기만 하면 돼요.\n\n동부 내륙지에서 찾겠다던 그 생물 이름이 뭐라고 했죠? 감메리타? 뭐, 잘 찾아보세요. 즉석사진을 찍어서 가져가면 다린이 아주 기뻐할 거예요.\n\n어쨌든, 슈퍼 찰칵이 여기 있어요. 잘 쓰세요!", progress = "드디어 돌아왔군요. 오, 커글이 나를 위해 만든 찰칵이도 함께 가져왔군요. 완벽해요.", completion = "오! 커글의 발명품이 기대한 만큼 쓸모가 있었군요.\n\n너무 흥분할 것까진 없지만 이 일로 내가 무척 기쁘다는 것만 알아주세요.\n\n자, 이제 책을... 음, 그 책을 어디 뒀더라...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2945] = {title = "꼬질꼬질한 반지", objective = "꼬질꼬질한 반지에서 찌꺼기를 제거할 방법을 찾아야 합니다.", description = "검은무쇠단 드워프 한 놈의 시체에서 반지처럼 보이는 것을 찾았습니다. 하지만 흙과 단단하게 굳은 찌꺼기가 완전히 뒤덮고 있어 어떤 종류의 반지인지 알아보기 어렵고 끼어 볼 수도 없습니다. 찌꺼기 밑에서 무언가 귀한 금속의 광택이 살짝 보이며 보석이 반짝이는 것 같기도 합니다.\n\n이 반지를 사용하려면 단단하게 굳은 찌꺼기를 제거해야 합니다.", progress = "앞에 있는 <race> 장치에는 '삐까뻔쩍세척기 5200'이라고 쓰인 명판이 붙어 있습니다. 그 아래 적힌 사용법을 읽어 보니 어떤 물건에 묻은 찌꺼기를 세척하는 데 쓰는 기계인 것 같습니다. 기계 안에 물건을 넣고 앞에 있는 동전 투입구에 3실버를 집어 넣으니 작동하기 시작합니다.\n\n방금 전에 찾은 꼬질꼬질한 반지를 넣으면 깨끗해질 것 같습니다!", completion = "삐까뻔쩍세척기 5200 안에 반지를 넣고 동전 투입구에 3실버를 넣습니다.\n\n심하게 흔들거리기 시작하며 삐걱거리는 소리가 새어 나와 듣기가 거북할 지경입니다. 속에 든 반지에 무슨 일이 일어나고 있을지는 아무도 모르는 일입니다.\n\n갑자기 기계가 멈추고 \"띵!\"하는 소리를 내며 종료를 알립니다. 반지를 넣었던 곳이 열리면서 깨끗이 포장되어 빨간 나비 리본까지 달린 작은 상자가 나옵니다. 삐까뻔쩍세척기 5200은 선물 포장도 해주는가 봅니다!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치"},
[2946] = {title = "위험한 시도", objective = "소형 백금 원반을 타나리스에 있는 울둠의 문으로 가져가서 이 둘 사이의 연관성에 대한 단서를 찾아야 합니다.", description = "당신이 발견한 소형 원반을 갖고 울둠의 봉인된 문으로 찾아가게. 어떤 일이 일어날지는 아무도 모르지...\n\n위험할지 모른다는 건 물론 우리도 인정하지만 아무 일도 일어나지 않고 무사할 수도 있네. 이 원반을 다른 무엇인가에 사용해야 할지도 모르네. 이 원반을 소지하고 있으면 문이 열릴지도 모르고. 뭐든지 시도할 준비를 해두고 어떤 불상사에도 대비할 수 있도록 준비하게.\n\n그리고 무슨 일이 일어나는지 알게 되면 아이언포지로 돌아오게. 일이 다 끝나고 나면 분석할 게 엄청나게 많을 테니까!", progress = "이 낯익은 받침대 모양의 대좌는 뜨거운 모래 사이로 삐죽 나와 있습니다. 이것이 여기 있는데는 어떤 이유가 있는 것 같습니다.", completion = "대좌를 건드리자 울다만에서 가져온 소형 원반이 가방 속에서 빛나며 윙윙거리는 소리가 납니다. 전에도 느껴 본듯한 찌릿한 느낌이 손을 휩쓸며 울둠의 문 앞에 또 다른 바위감시자의 영상이 나타납니다.\n\n\"안녕하십니까. 저는 이 문을 지키는 문지기입니다. 방금 사용하신 원반에는 올바른 출입용 원반인 울둠의 원반이 빠져 있습니다. 이 원반들을 제대로 조립하신 후 다시 한번 출입 절차를 진행해 주시기 바랍니다. 감사합니다.\"", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2947] = {title = "반지의 귀환", objective = "반지를 그냥 가지거나, 반지 안쪽 부분에 새겨진 인장 자국의 주인을 찾아야 합니다.", description = "삐까뻔쩍세척기 5200에서 나온 상자를 열자 생각했던 대로 반짝이는 반지가 들어 있습니다! 반지를 끼자 마법의 힘이 몸 전체를 휩쓰는 것이 느껴집니다.\n\n반지 안쪽 면에는 아이언포지의 봉인 자국이 작지만 읽을 수 있을 정도로 깨끗이 새겨져 있습니다. 그 옆에는 '탈바쉬'라는 세 글자가 조그맣게 새겨져 있습니다. 아마 예전 주인이나 이 반지를 만든 사람의 이름인 듯합니다. 반지를 간직하거나... 이 사람에게 돌려주어야 합니다. 또다시 결정의 시간이 돌아왔습니다.", progress = "좀 진정하시라니까. 난 신용 있는 사업가란 말이오! 임대료를 부친 게 좀 지연이 되고 있을 뿐이... 잠깐, 당신은 우리 집주인이 아닌데...\n\n이런, 정말로 아니군. 내가 바보 같은 소릴 했군! 저주받은 물건 따위는 절대로 만들지 않는 아이언포지 최고의 보석 세공인을 찾아온 손님이시군그래!\n\n음... 무엇이 필요하신 게요?", completion = "반지라고 했소? 어디 봅시다... 그래, 내가 그 반지를 만들었소.\n\n놈리건이 오염되기 전에, 난 그곳에서 작은 상점을 하나 운영했었소. 아마도 그 반지는 내가 놈리건에서 도망치다가 두고 나온 것일 거요. 단순한 디자인의 반지인데 똑같은 것을 여러 개 만들었소. 이건 놈리건을 미처 탈출하지 못한 노움의 것일 거요.\n\n검은무쇠단 드워프의 주머니에서 찾았다고? 흐음, 그렇다면 이 음모를 둘러싸고 있는 9개의 단서에 새로운 단서가 추가겠군. 아마도 당국에선 관심 있어 할 것이오. 이런 얘길 해 봤자 시간 낭비일 뿐이겠지.\n\n자, 그럼 반지 얘기로 돌아가서...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2948] = {title = "노움의 실력 향상", objective = "아이언포지에 있는 탈바쉬 델 키젤에게 은괴 1개, 태마노 1개와 반짝이는 금반지와 30실버를 주어야 합니다.", description = "내 말 좀 들어 보시오. 그 반지야 당연히 당신 게 맞겠지만, 내가 훨씬 더 멋지게 만들어 줄 수 있다오! 디자인이 너무 단순하지 않소? 이젠 나도 솜씨가 많이 늘었으니까... 30실버만 주면 반지를 더 멋지게 만들어주겠소! 솔직히... 30실버면 너무 싸지.\n\n그런데 요즘 사정이 좋질 않아서 재고가 모두 바닥나 버렸다오. 내게 은괴 1개와 태마노 1개만 가져다주면 반지에 격자 모양의 은과 태마노를 붙여서 세공을 좀 더 화려하게 해주겠소!\n\n한번 믿어보시오!", progress = "내가 말한 재료는 가져왔소? 내 주머니 사정이 조금만 나았어도 당신에게 그런 부탁을 하지는 않았을 텐데...", completion = "아, 필요한 재료를 모두 찾아왔군! 억울한 이 난관을 벗어나면 언젠가 당신과 세상 모든 이들을 위해 아제로스에서 가장 훌륭한 장신구를 만들어 주겠소! 아무튼 고맙소. 이 정도 반지라면 당신에게 부른 것보다 열 배는 비싸야 제 값이지만...\n\n아, 반지 말인데, 여기 새 걸로 만들었소!", rewards = "다음과 같은 것들을 받습니다:\n\n탈바쉬의 금반지"},
[2949] = {title = "반지의 귀환", objective = "반지를 그냥 가지거나, 반지 안쪽 부분에 새겨진 인장 자국의 주인을 찾아야 합니다.", description = "삐까뻔쩍세척기 5200에서 나온 상자를 열자, 생각했던 대로 반짝이는 반지가 들어 있습니다! 반지를 끼자 마법의 힘이 온몸을 휩쓸고 내려가는 게 느껴집니다.\n\n반지 안쪽에는 오그리마의 봉인 자국이 새겨져 있습니다. 작지만 읽을 수 있을 정도로 깨끗합니다. 그 옆에 새겨진 내용에서는 '노...'라는 맨 앞글자만 알아볼 수 있습니다.\n\n아마 예전 주인이나 이 반지를 만든 사람의 이름인 듯합니다. 반지를 간직하거나... 이름이 '노'로 시작하는 이에게 돌려주어야 합니다. 또다시 결정의 시간이 돌아왔습니다.", progress = "당신 생각은 어때요? 우리가 저 더럽고 조그만 노움들의 코를 납작하게 눌러 줄 방법을 스스로 찾을 수 있을까요? 애초에 우리에게서 그 장치를 훔쳐간 게 분명해. 틀림없다고요! 쳇! 기름투성이에 때묻은... 네? 도와드릴 일이라도 있나요?", completion = "놈리건에서 반지를요? 어디 볼까요... 아니오. 내 것은 아니지만 흥미로운 물건이군요.\n\n놈리건 말이 나왔으니 말인데, 바보 같은 노움 녀석들에게는 과분했죠. 오랫동안 장난감만 만들어대던 놈들이 갑작스레 우리보다 더 발달한 장치를 만들다니!\n\n그런데, 검은무쇠단 드워프들이 갖고 있었다고요? 흠... 점점 더 흥미가 땡기는군! 어쩌면 노움 녀석들이 골렘 도안을 훔쳐서 개조를 했는지도 몰라요. 검은무쇠단 드워프들은 분명 복수를 하고 싶어할 겁니다. 음, 조사를 해 볼 만하군요.\n\n아, 물론 그... 반지에 대한 조사 말이죠.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2950] = {title = "노그의 반지 수리", objective = "오그리마에 있는 노그에게 반짝이는 금반지, 은괴 1개, 태마노 1개, 그리고 30실버를 가져다주어야 합니다.", description = "아니, 아니, 아니, 그 반지가 내 거라고 하는 게 아니고... 보통 이런 일은 잘 하지 않지만 당신이 주신 검은무쇠단 드워프에 대한 정보가 아주 유용해서 그 보답으로 반지를 더 멋지게 만들어주려는 겁니다. 이 작고 단순한 모양의 반지를 누가 만들었는지는 모르지만 훨씬 멋지게 만들어 줄게요. 아마 노움이 만든 게 아닐까 싶지만...\n\n은괴 1개, 태마노 1개, 그리고 수고비로 30실버를 가져오면 반지에 격자 모양으로 은을 붙여 마법을 더 강화시켜 주도록 하죠. 어때요... 해보고 싶으시죠?", progress = "내가 말한 재료는 가져왔나요? 부탁한 것들을 모두 가져오지 않으면 반지를 더 멋지게 세공할 수 없어요.", completion = "자, 받으세요. 전보다 훨씬 나아졌답니다. 검은무쇠단 드워프에 대한 정보를 줘서 다시 한번 감사드려요. 노움이 어째서 갑자기 고블린 같은 사고를 하게 되었는지 이해할 만한 단서인 듯 하네요.", rewards = "다음과 같은 것들을 받습니다:\n\n노그의 금반지"},
[2951] = {title = "삐까뻔쩍세척기 5200!", objective = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 넣으십시오. 3실버를 투입하면 작동할 것입니다.", description = "완강히 저항하고 있는 노움들 사이에서 이 장치가 눈에 띕니다. 장치 앞면에 붙은 작은 판에 \"삐까뻔쩍세척기 5200\"이라는 이름과 함께 다음과 같은 글귀가 적혀 있습니다.\n\n\"귀중품에 찌꺼기가 끼었습니까? 삐까뻔쩍세척기 5200이 말끔히 닦아 드립니다! 세척할 물건을 장치에 넣고 투입구에 3실버를 넣으십시오. 잠시만 기다리시면, 짜잔! 당신의 귀중품이 깨끗한 모습으로 반짝이게 됩니다!\"", progress = "세척기가 작동하려면 꼬질꼬질한 물건과 3실버가 필요합니다. 두 가지를 모두 가지고 있어야 삐까뻔쩍세척기 5200이 작동합니다.", completion = "꼬질꼬질한 물건과 3실버를 삐까뻔쩍세척기 5200에 넣습니다. 장치가 요동치기 시작하면서 중심부에서 요란하고 시끄러운 소리가 들려옵니다. 물건에서 찌꺼기를 닦아내는 것 같습니다. 장치가 좌우로 흔들리면서 내부의 금속 구조물들이 서로 부딪히며 삐걱거리는 소리가 납니다.", rewards = nil},
[2952] = {title = "삐까뻔쩍세척기 5200!", objective = "삐까뻔쩍세척기 5200이 갑자기 멈추어 버립니다. \"땡\" 소리가 나더니 원통형 입구가 회전하면서 위로 올라와 열립니다. 그 안에는 조그만 리본 장식으로 포장된 작은 상자가 있습니다. 물건의 찌꺼기를 세척하고 난 후 포장까지 한 모양입니다. 찌꺼기가 제대로 없어졌는지는 모르지만 적어도 물건은 예쁘게 포장되어 있습니다.\n\n제대로 세척됐는지 알아보는 방법은 단 한 가지 뿐...", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n삐까뻔쩍세척기 포장 상자"},
[2953] = {title = "삐까뻔쩍세척기 재사용", objective = "빈 삐까뻔쩍세척기 5200이 꼬질꼬질한 물건과 3실버를 기다리고 있습니다!", description = nil, progress = "빈 삐까뻔쩍세척기 5200이 꼬질꼬질한 물건과 3실버를 기다리고 있습니다!", completion = "삐까뻔쩍세척기 5200이 작동하며 앞뒤로 마구 흔들립니다. 안에서는 노움 세척제가 물건에 찌든 찌꺼기를 말끔히 닦아내고 있습니다!\n\n삐까뻔쩍세척기 5200이 갑자기 멈추더니 \"땡\" 하는 소리가 납니다. 입구가 열리면서 예쁘게 포장된 상자가 모습을 드러냅니다.", rewards = "다음과 같은 것들을 받습니다:\n\n삐까뻔쩍세척기 포장 상자"},
[2954] = {title = "바위감시자", objective = "타나리스 사막에 있는 노르간논의 바위감시자와 대화한 후 울둠 대좌를 건드리십시오.", description = "\"안녕하십니까. 저는 이 입구를 지키는 문지기입니다. 원반 세트에 울둠의 원반이 결합되어 있지 않으면 울둠으로 들어갈 수 없습니다.\"\n\n이 노르간논의 바위감시자가 출현할 것을 기대하고 당신에게 백금 원반만을 들려 타나리스 사막으로 보낸 것 같습니다. 먼저 지시를 받은 대로 노르간논의 바위감시자에게 숨겨진 이야기가 무엇인지 알아보아야 할 것 같습니다.", progress = "우선 바위감시자의 이야기를 들어야 합니다.", completion = "바위감시자의 울려 퍼지는 듯한 목소리에서 힘과 권위가 느껴집니다.\n\n\"이제 대좌를 건드리시면 원반을 돌려드리겠습니다. 울둠의 원반을 기존 원반 세트에 결합하시면 울둠에 들어오실 수 있습니다.\"", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2962] = {title = "유일한 치료법", objective = "놈리건으로 가서 고농축 방사성 폐기물을 가져와야 합니다. 이 폐기물은 불안정하여 성분이 금방 변할 수 있으니 주의하십시오.\n\n임무를 완수한 후 빈 대형 가연채집병을 오지에게 돌려줘야 합니다.", description = "당신이 가져온 견본은 양도 부족한데다 불순물까지 섞여 있었소.\n\n우리는 녹색 폐기물이 더 많이 필요하오. 그 트로그들의 몸에는 우리가 원하는 만큼의 방사선이 없으니 곧장 놈리건으로 가서 방사성 폐기물을 가져와야겠소. 오염된 진흙괴물, 오염된 폐기물을 말이오. 경고해 두겠는데, 이런 종류의 방사성 폐기물은 채취하기가 매우 어렵소. 그러니 쓸만한 견본을 채취할 때까지 이 약병을 여러 번 사용해야 할 거요.", progress = "흠, 다행이군. 당신은 아직 방사선을 쐬지 않은 것 같아.", completion = "&lt;자세히 살펴보는 오지&gt;\n굉장해. 아직도 멀쩡하게 살아 있다니! 자, 그럼 이제 물건이 어떤지 한번 볼까!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2963] = {title = "울둠의 전조", objective = "아이언포지의 탐험가의 전당에 있는 역사학자 카르닉과 대화하십시오.", description = "또 만나게 되어 반갑네! 자네가 울다만 안에서 발견한 것 때문에 탐험가 연맹 전체가 떠들썩하다네. 탐험가 연맹에서는 자네가 찾아온 소형 백금 원반의 비밀을 캐내려고 안간힘을 쓰고 있지. 자네가 건진 게 뭔가 중요한 것이었다고 알려주고 싶었는데 마침 여기 왔군그래.\n\n역사학자 카르닉이 타나리스 사막에 있는 감시자의 골짜기에 얽혀 있는 진정한 근원에 대한 중요한 단서를 발견했다네. 가능한 빨리 자네와 얘기를 나누고 싶어하니 찾아가 보게나.", progress = nil, completion = "탐험에 대한 흥미를 아직도 잃지 않고 있다니 다행이군! 자네의 타고난 재능과 활력으로 많은 것들을 캐낼 수 있을 것이야! 우리가 절대로 캐낼 수 없다고 생각했던 비밀들을 말일세.\n\n울다만에서 가져온 노르간논의 원반은 대량의 정보를 저장하는 저장소지. 말하자면 자네는 전체 정보의 가장 윗부분만 볼 수 있었던 게야. 창조주들이 아제로스 도처에 저장소를 마련해 그러한 정보를 저장해두었다는 소문이 있었는데 이중 하나가 울둠에 있는 것이 아닌지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2964] = {title = "미래의 임무", objective = "아이언포지에 있는 선임탐험가 마겔라스와 대화하십시오.", description = "음... 지금 우린 잠시 막다른 골목에 부닥친 것 같네. 울둠의 원반이 필요하다는 것은 알았지만 그것들이 어디에 있을지는 아무도 모르니까. 제대로 된 계획을 세우려면 방대한 조사가 필요하겠군. 다행스럽게도 어디부터 시작할지 대충 짐작 가는 곳이 두 군데 있네. 곧 자네더러 가서 그것들을 회수해 오라고 하게 될지도 모르겠네.\n\n이 일을 선임탐험가께 보고하게. 다시 한번 우리 탐험가 연맹을 도와준 데 대한 감사의 표시를 직접 하고 싶어하실 게 분명해.", progress = nil, completion = "그러면 모두 찬성하는 것이로군. 최선의 방법은 이 원반들이 있을 만한 곳을 더 자세히 알아낼 때까지 보류하는 것이라고 말일세. 자네는 우리를 위해 이렇게까지 일을 진척시켜 주었네. 그리고 언젠가 자네가 그곳으로 되돌아가서 우리 모두를 위해 울둠의 비밀을 밝혀 주기 바라네.\n\n자, 이 사례금을 받게나. 우리를 도와주는 데 들었던 비용을 채우고도 조금 남을 걸세. 다시 와주길 바라네... 울둠이 손짓하며 부르고 있으니까!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2965] = {title = "울둠의 전조", objective = "썬더 블러프의 장로의 봉우리에 있는 나라 와일드메인과 대화해야 합니다.", description = "아, 다시 와주어서 다행이군. 울다만 발굴현장에서 찾은 것 때문에 우리 현자들 간에 많은 논의가 있었다네. 드루이드들 중 한 명인 나라 와일드메인과 바로 그런 논의를 하고 있었지. 그녀의 예전 탐험 경험이 우리가 앞으로 취해야 할 행동에 큰 도움이 될 것이라고 생각해서였네.\n\n자네가 나라를 만나 그녀의 타나리스 사막에 있는 감시자의 골짜기에서의 모험에 대해 얘기를 나눠 봤으면 좋겠군. 그녀는 장로의 봉우리에서 기다리고 있다네.", progress = nil, completion = "타나리스 사막 깊숙이 감시자의 골짜기라는 곳이 있어요. 당신이 발견한 원반들... 거기에 그려진 상형 문자를 해석해 보면 울둠이라는 곳을 언급하고 있죠.\n\n사람들은 대부분 이곳이 전설이라고 생각한답니다. 난 울둠은 존재하고 그곳에 직접 가 보기도 했기 때문에 그게 단지 전설만은 아니라는 걸 알고 있어요. 그게... 적어도 울둠의 외곽 지역까지는 가 봤어요.\n\n요점은, 우리는 그 원반들과 울둠 간에 어떤 관계가 있다고 생각하니 당신이 그곳에 가 줬으면 한다는 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2966] = {title = "위험한 시도", objective = "소형 백금 원반을 타나리스에 있는 울둠의 문으로 가져가서 이 둘 사이의 연관성에 대한 단서를 찾아야 합니다.", description = "현자 트루스시커님과 나는 당신이 이 소형 원반을 가지고 울둠의 봉인된 문으로 찾아갔으면 합니다. 당신이 그렇게 하면 어떻게 될지는 아무도 몰라요.\n\n위험할 것 같다는 건 우리도 물론 인정하지만 아무 일도 일어나지 않을 수도 있어요. 당신이 이 원반을 무엇인가에 사용해야 할지도 몰라요. 이 원반을 소지하고 있으면 문이 열릴지도 모르겠어요. 뭐든지 시도할 준비를 해두고 어떤 불상사에도 대비하도록 하세요.\n\n알아낼 수 있는 만큼 알아낸 후에 다시 날 찾아오세요. 다 끝난 뒤에는 의논할 게 많을 거예요.", progress = "어디서 많이 본 것 같은 받침대가 뜨거운 모래에서 삐죽 나와 있습니다. 이것이 여기에 있는데에는 어떤 이유가 있는 것 같습니다...", completion = "대좌를 건드리자 울다만에서 가져온 소형 원반이 배낭 속에서 웅웅거리며 빛납니다. 익숙한 저린 느낌이 손을 휩쓸며 울둠의 문 앞에 또 다른 바위감시자의 영상이 나타납니다.\n\n\"안녕하십니까. 저는 이 문을 지키는 문지기입니다. 당신이 사용하신 원반 중에 올바른 출입용 원반인 울둠의 원반이 빠져 있습니다. 원반 구조물과 이 원반들을 조립하신 후 다시 한번 출입 절차를 진행해 주시기 바랍니다. 감사합니다.\"", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2967] = {title = "썬더 블러프로의 귀환", objective = "썬더 블러프에 있는 나라 와일드메인과 대화해야 합니다.", description = "받침대를 다시 건드리자 갑자기 백금 원반이 다시 가방에 들어있는 것을 알게 됩니다.\n\n바위감시자에 대해서 알았고 원반도 다시 얻었으니 썬더 블러프로 돌아가 나라 와일드메인에게 보고해야 할 때입니다.", progress = "어서 오세요. 원반은 사용해 봤나요? 아니면 허탕만 치고 오게 되었나요?", completion = "빠진 원반이 있다고요? 재미있네요. 노르간논의 원반도 어떤 한 세트의 일부인 것 같아요. 열쇠 고리에 달린 여러 개의 열쇠들처럼 말이에요.\n\n울둠의 원반을 찾을 수만 있으면 실제로 울둠 내부에 들어갈 수 있을 거예요. 이 사실에 기뻐해야 할지 두려워해야 할지 모르겠군요.\n\n어쩌면 그 땅의 비밀이 밝혀지면 우리 모두를 파멸시킬 지도 몰라요. 우리의 전부를 걸어서라도 비밀을 지켜야 하는지도...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2968] = {title = "미래의 임무", objective = "썬더 블러프에 있는 현자 트루스시커와 대화해야 합니다.", description = "이거... 곤경에 부닥친 것 같네요. 울둠의 원반이 필요하다는 것은 알았지만 아무도 어디에 있는지는 몰라요. 먼저 조사를 한 다음 제대로 된 계획을 세워야겠군요. 어디서부터 시작할지 대충 짐작이 가는 곳이 두 군데 있어요. 곧 그곳으로 가셔야 할지도 모르겠네요.\n\n어서 이 일을 현자 트루스시커님께 보고해야 해요. 분명 당신이 부름에 응해 준 데 대해 감사를 표하고 싶어하실 거예요.", progress = nil, completion = "그러면 모두 찬성하는 것이로군. 그 원반들이 있을 만한 곳을 알아낼 때까지 모든 행동을 보류하는 것이 최선이라고 말이야. 일을 이렇게까지 진척시켜 주었군. 언젠가 우리 모두를 위해 현장으로 돌아가서 울둠의 비밀을 밝혀 주기를 바라네.\n\n이 사례금을 받아 주게. 우리를 돕기 위해 그대가 치렀던 비용을 채우고도 남을 걸세. 곧 다시 찾아 주길 바라네... 울둠이 우리 모두를 손짓하며 부르고 있으니...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2969] = {title = "모든 생명에 자유를", objective = "대나무 우리 열쇠를 사용하여 그림토템부족 야영지의 우리에 갇힌 화살요정용들을 풀어 줘야 합니다. 최소 6마리의 화살요정용과 킨달 문위버가 살아남아야 합니다.\n\n6분이 지나면 킨달이 후퇴할 때가 되었다고 할 것이며 임무에 실패하게 됩니다.", description = "쉿, 조용히 하고 저 밑을 좀 보세요. 저 더러운 그림토템부족 녀석이 요정용을 잡아들이고 있어요. 저들이 무슨 일을 저지르려는 건지 정확히는 모르겠지만 분명 못된 짓을 벌이려는 속셈일 겁니다.\n\n우리 힘만으로는 야영지로 쳐들어가 붙잡힌 용들을 풀어줄 수가 없지만 그대가 도와준다면 혹시...\n\n친구들 몇 명과 함께 이 일을 맡아볼 생각이 있다면, 이 열쇠로 우리에 갇힌 용들을 풀어주고 살아서 도망칠 수 있도록 도와주세요. 제가 옆에서 지원하죠. 그리고 만약에 대비해 제르카이는 여기 남을 겁니다.", progress = nil, completion = "엘룬께 영광을! 그대는 화살요정용들과 우리에게 위대한 축복과 같은 존재예요. 제르카이와 저만으로는 결코 성공할 수 없었을 겁니다. 그림토템부족에게 맞서 절 도와준 일은 결코 잊지 않겠어요.\n\n전 복수할 준비를 해야 하니까 제르카이와 얘기해 보세요. 요정용들이 풀려났다고 해서 계속 안전하리라는 보장은 없거든요. 이제 제르카이와 나는 공격을 할 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2970] = {title = "정의의 실현", objective = "그림토템부족 식물학자 12명, 그림토템부족 침략자 10명, 그리고 그림토템부족 주술사 6명을 처치한 후, 페랄라스에 있는 제르카이 문위버에게 돌아가야 합니다.", description = "엘룬께 영광을. 벌써 얘기를 들으셨겠지만, 킨달과 저는 이제 그림토템부족을 공격할 작정입니다. 힘을 합한다면 큰 위험 없이 타우렌 녀석들을 일부 제거할 수 있을 거예요. 하지만 당신이 도와주실 수 있으시다면 그 도움을 받고 싶군요.\n\n우리 밑에 있는 야영지를 보셨겠지만 동쪽에 야영지가 또 있답니다. 당신만의 전략으로 타우렌 녀석들에게 되도록 많은 피해를 주시기 바랍니다. 킨달의 화살과 당신의 무기로 쓴맛을 좀 보여준 후에 여기서 다시 만나기로 하죠.", progress = nil, completion = "당신이 이런 일에 소질이 있다는 킨달의 말이 옳았네요. 당신은 우리 둘보다 더 용감한 모험가시군요. 감사합니다.\n\n그림토템부족은 대부분의 타우렌들보다 훨씬 더 사납답니다. 전 그들의 동족들조차도 그들을 싫어하는지 궁금해요. 그렇다 해도 그다지 놀랄 만한 건 없겠지만요. 이미 알아차리셨겠지만 아제로스의 많은 종족들은 더 사나운 종족과 상호 간에 연관되어 있어요.\n\n하지만 그 얘기는 다음으로 미루도록 하죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2972] = {title = "정의의 실현", objective = "다르나서스에 있는 대여사제 티란데 위스퍼윈드에게 제르카이의 인장 반지를 가져가야 합니다.", description = "이런 황폐한 곳에서는 킨달과 제가 제대로 된 보상을 드리기가 어럽군요. 하지만 당신의 수고에 대해 감사의 표시를 꼭 하고 싶으니 제 인장 반지를 받아 두세요. 혹시 텔드랏실에 가시게 되거든 다르나서스 중심부에 있는 달의 신전으로 가서 대여사제이신 티란데 위스퍼윈드님을 찾아뵙도록 하세요. 이 반지를 보여드리면 우리가 무사하다는 것을 알고 당신의 얘기를 믿으실 겁니다.\n\n킨달과 저, 우리 둘의 마음을 담아 감사드려요.", progress = "엘룬께 영광을. 이 신전에 그대처럼 강한 모험가가 찾아오니 기쁘군요. 혹시 시간이 있다면 더 젊은 모험가들에게 모험담 한두 가지 들려 주지 않겠어요? 그들이 그대의 지혜에서 많은 것을 배울 수 있을 겁니다.\n\n이런. 미안합니다. 내가 너무 무례하게 구는군요. 달의 신전으로 우리의 도움을 받으러 온 것일 텐데 이런 부탁이나 하고 있으니... 용서하세요. 빛의 신하인 우리가 도와드릴 일이 있으면 어서 말씀하세요.", completion = "놀라운 얘기로군요. 그대가 용족을 도와줬을 뿐만 아니라 우리 여사제들도 도와줬다니 기쁩니다. 제르카이가 그대를 내게 보낸 것은 잘 한 일이에요. 곧 페랄라스로 떠나는 정찰병들이 있으니 이 반지를 꼭 되돌려주도록 하겠습니다. 정찰병들이 임무를 수행하는 동안 조사해야 할 것이 하나 더 늘어나게 된 것이죠.\n\n다시 한번 감사 드립니다. 그리고 이곳에 머무르는 동안 부디 편히 지내시기 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n버드나무 손목띠밤비늘 벨트\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2973] = {title = "화려한 새 망토", objective = "모자케 야영지에 있는 크루엑 스컬스플리터에게 오색 화살요정용 날개 10개를 가져가야 합니다.", description = "만나서 반갑소. 난 오그리마 지도자 어르신들의 명을 받아 친구들과 함께 이곳 페랄라스까지 왔지...\n\n내 아내 코린은 새 옷을 정말 좋아해... 하늘하늘한 요정용의 날개를 장식으로 단 새 망토를 만들어줄까 하는데 날 좀 도와줄 수 있겠소? 모자케 야영지에서 서쪽으로 멋들어진 날개를 단 화살요정용들이 있소.", progress = "화살요정용들은 화가 나면 아주 위험하니 조심하시오. 그리고 혹시 있을지 모르는 나이트 엘프들은 더더욱 조심하고. 또 숲에 성가신 바보 녀석들이 어슬렁거릴 지도 모르오.\n\n날개를 다 모았으면 말해주시오. 아주 후히 사례하겠소!", completion = "좋아! 이거면 딱 맞겠소. 코린에게 망토를 새로 만들어주고도 남을 만큼 모아왔군! 고맙소이다.\n\n날개를 모으는 일이 그렇게 험하지 않았길 바라오. 페랄라스는 아주 거친 곳이라서... 하지만 아주 잘해냈소.\n\n다시 한번 감사하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2974] = {title = "불길한 발견", objective = "모자케 야영지에 있는 크루엑 스컬스플리터에게 그림토템일족 뿔 20개를 가져가야 합니다.", description = "뭐요!? 그 지역에 있는 타우렌들과 마주쳤단 말이오? 어떻게 생겼소?!\n\n음... 그림토템부족이로군! 드디어 녀석들을 발견했단 말이지... 벨그롬 장로님께서 그 부족에 대해 관심이 있으시오. 현상금까지 걸어놓았지.\n\n<class>|1이여;여;, 다시 그곳으로 가시오. 이번엔 녀석들의 뿔을 되도록 많이 모아오시오. 그림토템부족은 섣불리 상대하거나 과소평가해서는 안 될 녀석들이오. 놈들을 처치해주시오. 페랄라스의 강이 놈들의 피로 시뻘겋게 물들도록!", progress = "내 말을 새겨들으시오. 그림토템부족은 사악하기 그지없는 놈들이오. 녀석들의 소재를 파악했다면, 그곳으로 돌아가서 선제공격을 가해야 하오. 놈들이 쳐들어와 마을을 불사르고 우리 영토를 빼앗기 전에... 모두 당신에게 달렸소.", completion = "수고했소. 아주 괜찮은 뿔들이로군. 난 이걸 가지고 오그리마로 출발해 도착하는 즉시 벨그롬님께 가도록 하겠소. 벌써 두 번이나 날 도와주다니 아주 고맙게 생각하고 있다는 걸 알아주시오. 언젠가 내가 당신을 도울 일이 있다면 좋겠군. 행운을 빌어주리다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2975] = {title = "페랄라스의 오우거", objective = "모자케 야영지에 있는 로크 올한이 골두니 오우거 10명, 골두니일족 오우거 마법사 10명, 골두니일족 투사 5명을 처치해달라고 부탁했습니다.", description = "이 지역에서는 골두니 오우거일족의 영향력을 느끼지 않을 수가 없습니다. 주위를 둘러보세요. 녀석들의 존재는 이 땅에 상처를 입히고 있습니다. 녀석들이 페랄라스에서 세력을 더 확장하기 전에 몰아내야만 합니다.\n\n강을 따라 북쪽으로 가면 녀석들의 전초기지가 있으니 녀석들의 수를 줄여주시기 바랍니다. 녀석들에게 이 땅에서 환영받지 못하는 존재임을 알려주도록 하세요.", progress = nil, completion = "좋습니다. 시간이 흐르면 땅도 회복될 것입니다. 절대 포기해서는 안 됩니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2976] = {title = "불길한 발견", objective = "오그리마에 있는 벨그롬 록마울에게 그림토템일족 뿔 상자를 가져가야 합니다.", description = "뭐요?!\n\n그러니까 내가 현상금 얘기를 했었단 말이지. 아차... 앞으로 입 조심 해야겠군.\n\n수고를 한 건 당신이니 당신이 가장 큰 사례를 받아야 마땅하지. 뿔을 가져가시오. 내가 상자 안에 넣어두겠소. 그리고 명예의 골짜기로 벨그롬 록마울님을 찾아가 보시오. 이번 일에 대해서도 알고 싶어하실 테고 당신의 노고에 대해서도 보상해 주실 거요.\n\n건강히 지내시오, <class> 친구. 그리고 당신이 해준 모든 일에 대해 다시 한번 감사를 전하오.", progress = "어서 얘기하게, <class>. 오늘 할 일이 아주 많거든.", completion = "그림토템부족이라고? 재미있군. 그러니까 페랄라스에서 사냥을 하다가 마주쳤단 말이오? 정말이오?\n\n내 친구들도 당신 얘기를 듣고 싶어할 거요. 더 얘기해 보시오. 들으면서 난 당신에게 줄 현상금을 챙겨 놓아야겠군.\n\n오늘 당신이 전해준 정보를 고맙게 생각하고 있소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n결전의 단망토달비취 보주\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2977] = {title = "아이언포지로의 귀환", objective = "아이언포지에 있는 역사학자 카르닉과 대화하십시오.", description = "대좌를 다시 건드리자 갑자기 백금 원반이 가방에 다시 나타납니다.\n\n바위감시자에 대해서 알았고 원반도 다시 갖게 되었으니 아이언포지로 돌아가 탐험가 연맹에 보고해야 할 때입니다.", progress = "어서 오시게. 원반은 쓸모가 있었나? 아니면 허탕만 치고 돌아온건가?", completion = "빠진 원반이 있다고? 재미있군. 노르간논의 원반도 어떤 한 세트의 일부인 것 같군. 고리에 달린 여러 열쇠들처럼 말이네.\n\n울둠의 원반을 찾을 수만 있으면 실제로 울둠 내부에 들어갈 수 있을 거야! 삽질 한번 안하고 창조주들이 작업을 하던 곳을 탐방한다고 상상해 보게!\n\n뭐, 삽질이 잘못됐다는 건 아니지만...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2978] = {title = "골두니 두루마리", objective = "모자케 야영지에 있는 로크 올한에게 골두니 두루마리를 가져가야 합니다.", description = "더럽혀진 두루마리를 주워 읽어 보니 이것이 어떤 회합이나 의식을 묘사하고 있는 두루마리 같습니다. 로크 올한이 이 두루마리가 골두니일족에게 어떤 의미가 있는지에 대해 알고 싶어할 것입니다.", progress = "이게 뭡니까?", completion = "이 두루마리는... 이걸 골두니 전초기지에서 찾았다고요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2979] = {title = "암흑의 의식", objective = "모자케 야영지에 있는 로크 올한이 골두니 수정구를 찾아 와 달라고 부탁했습니다.", description = "음... 이 두루마리는 일종의 암흑의 의식을 위한 계획서인 것 같군요. 내가 보기에 이 의식은 골두니일족 오우거 대마법사들이 행하는 것 같습니다.\n\n이 오우거 대마법사들 중 하나를 찾아 수정구를 빼앗아 오세요.\n\n마법사의 수정구에는 굉장한 마력이 들어 있어 이 암흑의 의식과 골두니일족이 사용하는 마법에 대해 더 자세히 알아보는 데 도움이 될 겁니다.", progress = "골두니일족이 무엇 때문에 이곳에 온 건지 더 자세히 밝혀 내야만 합니다.", completion = "이 수정구가 골두니일족에 대해 더 많은 정보를 제공해 줄 겁니다... 그러면 그 정보를 가지고 녀석들을 쓰러뜨리기 위한 계획을 세울 수 있을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2980] = {title = "페랄라스의 오우거", objective = "모자케 야영지에 있는 로크 올한이 골두니일족 주술사 10명, 골두니일족 흑마법사 10명, 그리고 골두니일족 싸움꾼 5명을 처치해 달라고 부탁했습니다.", description = "이제 당신이 스스로 진정한 투사라는 것을 입증해 낸 만큼 주어진 임무를 계속 수행해 나갈 용기가 있을 거라 믿습니다.\n\n여기서 남서쪽에 있는 높은벌로 가십시오. 한때 나이트 엘프들이 살았던 땅 위에 버려지고 파괴된 구조물들이 널려 있답니다. 이 폐허를 찾아가서 시들어 버린 나무와 더럽혀진 땅을 보게 되면 곧 골두니일족을 발견하게 될 겁니다. 녀석들을 몰아내도록 하세요.\n\n이 오우거들은 당신이 전에 상대했던 녀석들보다 훨씬 더 강하니까 조심하십시오.", progress = nil, completion = "당신은 정말로 믿고 의지할 수 있는 동지로군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2981] = {title = "페랄라스의 위협", objective = "벨그롬 록마울이 모자케 야영지에 있는 로크 올한과 대화해 달라고 부탁했습니다.", description = "페랄라스는 실력 있는 <class>|1이;가; 그 가치를 증명하기에 딱 좋은 장소지. 그곳은 골두니라는 오우거일족이 막강한 군사력을 발휘하고 있는데 녀석들의 수가 갈수록 늘어나고 있소. 녀석들이 페랄라스에 주둔하고 있는 우리 동맹에게 위협을 가하기 전에 막아야 하오.\n\n페랄라스의 모자케 야영지에 있는 로크 올한이라는 전사를 알고 있는데 그녀에게 가보시오. 당신이 도착하면 그녀가 현재 상황에 대해 자세히 설명해줄 거요.", progress = nil, completion = "벨그롬이 보냈군요. 때맞춰 잘 도착했습니다.\n\n상황을 설명할 테니 임무를 맡을지는 그 후에 결정하도록 하시기 바랍니다. 하지만 벨그롬이 보냈으면 당신의 용맹함에 대해서는 굳이 물어보지 않아도 되겠군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2982] = {title = "높은벌", objective = "안젤라스 문브리즈가 골두니일족 흑마법사 8명, 골두니일족 주술사 8명, 골두니일족 투사 8명을 퇴치해 달라고 부탁했습니다.", description = "트로야스와 나는 위험한 줄 알면서도 폐허가 된 페랄라스 숲을 조사해 왔습니다.\n\n그런데 요즘 들어 트로야스가 자꾸 혼자서 높은벌로 가는 게 너무 걱정이 되네요. 그곳은 골두니 오우거들이 판을 치고 있는데다 녀석들은 자기들 영토에 침입하는 자에게는 몹시 사납게 굴거든요.\n\n그대가 섬 너머 남동쪽에 있는 폐허로 가서 그 오우거들을 좀 처치해 줬으면 합니다. 우리 트로야스를 위해서 그곳을 조금 더 안전하게 해 주면 정말 고맙겠어요.", progress = nil, completion = "부탁을 들어주셔서 너무 감사해요.\n\n트로야스에게는 아무런 얘기도 하지 말아주세요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2983] = {title = "불의 부름", objective = "불모의 땅에 있는 크라날 피스를 찾아야 합니다.", description = "마지막으로 자네의 실력을 시험해 본지도 꽤 됐군, <name>. 지금까지도 끈기 있게 잘해왔지만 이제는 더 큰 힘을 배울 때가 왔네... 진정한 힘을 배울 때가 온 것이지. 어떠한 대가라도 치를 준비가 되었다면 불의 원소는 자네의 것이네.\n\n불모의 땅에 있는 크라날 피스를 찾아가 보게. 크로스로드 북쪽에 있는 작은 거처에 머물고 있네. 하지만 조심하게. 너무 멀리 가면 그 괘씸한 나이트 엘프의 땅에 이르게 되니...", progress = nil, completion = "흠, 스워트가 자네를 나에게 보낸 모양이군, 그렇지?\n\n그는 언제나 믿을 만한 친구였으니 자네가 이제 불의 정기를 마실 준비가 되었다는 뜻이겠지.\n\n벌써 자네 눈에서 타오르는 욕망이 보이는군. 이미 힘의 맛을 보았고 이제 더 많은 힘을 원하게 된 거야. 하지만 너무 서두르진 말라고, &lt;name&gt;. 땅의 가르침을 기억하게. 힘과 파괴는 쉽게 얻을 수 있지만 언제 힘을 자제해야 하는지 또한 배워야만 하니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2984] = {title = "불의 부름", objective = "불모의 땅에 있는 크라날 피스를 찾아야 합니다.", description = "마지막으로 자네의 실력을 시험해 본지도 꽤 됐군, <name>. 지금까지 끈기 있게 잘해왔지만 이제는 더 큰 힘을 배울 때가 왔네... 진정한 힘을 배울 때가 온 것이지. 어떠한 대가라도 치를 준비가 되었다면 불의 원소는 자네의 것이네.\n\n불모의 땅에 있는 크라날 피스를 찾아가 보게. 크로스로드 북쪽에 있는 작은 거처에 머물고 있네. 하지만 조심하게. 너무 멀리 가면 그 괘씸한 나이트 엘프들의 땅에 이르게 되니...", progress = nil, completion = "흠, 나름이 자네를 나에게 보낸 모양이군, 그렇지?\n\n그는 언제나 믿을 만한 친구였으니 자네가 이제 불의 정기를 마실 준비가 되었다는 뜻이겠지.\n\n벌써 자네 눈에서 타오르는 욕망이 보이는군. 이미 힘의 맛을 보았고 이제 더 많은 힘을 원하게 된 거야. 하지만 너무 서두르지 말라고, &lt;name&gt;. 땅의 가르침을 기억하게. 힘과 파괴는 쉽게 얻을 수 있지만 언제 힘을 자제해야 하는지 또한 배워야만 하니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2985] = {title = "물의 부름", objective = "불모의 땅에서 이슬렌 워터시어를 찾아야 합니다.", description = "이제 다음 시험을 치를 준비가 된 것 같군. 지금까지 끈기 있게 잘해왔지만 이제 더 많은 것을 배워야 할 때가 왔네. 이제는 물의 순수함에 대해 배워야 해.\n\n불모의 땅에 있는 이슬렌 워터시어를 찾아가게. 동쪽 해안을 따라 분노의 강과 톱니항의 남쪽으로 가게. 고기잡이 오두막에 가면 그녀를 찾을 수 있을 거야. 행운을 비네.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2986] = {title = "물의 부름", objective = "불모의 땅에서 이슬렌 워터시어를 찾아야 합니다.", description = "마지막으로 자네의 실력을 시험해 본 것도 오래전 일이군. 지금까지 끈기 있게 잘해왔지만 이제 더 많은 것을 배워야 할 때가 왔네. 이제는 물의 순수함에 대해 배워야 해.\n\n불모의 땅에 있는 이슬렌 워터시어를 찾아가게. 동쪽 해안을 따라 분노의 강과 톱니항의 남쪽으로 가게. 그곳의 고기잡이 오두막에 가면 그녀를 찾을 수 있을 거야. 행운을 비네.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2987] = {title = "골두니 코발트", objective = "모자케 야영지에 있는 올윈 기즈믹이 골두니 코발트 12개를 가져다 달라고 부탁했습니다.", description = "난 페랄라스에 온 지 얼마 되지 않았지. 듣자 하니 이곳에 사는 골두니 오우거들이 아주 흥미로운 광석을 갖고 있다 하더군. 녀석들이 무슨 짓을 꾸미고 있는지는 모르겠지만 그 물건을 끔찍이 챙기는 건 확실해! 녀석들은 그 물건을 그냥 바닥에 버려두지 않고, 아니, 아예 나 같은 자가 손대지 못하게 묻어두고 있다니까.\n\n혹시 생각이 있다면 내 삽을 줄 테니 북쪽에 있는 골두니 전초기지로 가서 골두니 코발트를 좀 파오라고. 삽을 사용하여 파란빛이 나타나면 땅을 파 보라고. 그럼 흙고분 안에서 코발트를 캘 수 있을 거야!", progress = "서둘러 가서 파오라고! 난 가야 할 곳도 있고 만나야 할 사람도 있단 말이야. 시간은 돈이라구!", completion = "좋았어! 이걸 갖고 여행을 계속 해야겠군. 이 코발트를 괜찮은 값에 사려는 자들이 분명 있을 거야.\n\n자, 수고해줬으니 이걸 받으라고.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n지도자의 장화별바라기 망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2988] = {title = "마른나무껍질부족 우리", objective = "마른나무껍질 마을 두 곳에 있는 우리들을 확인한 후, 그리핀 조련사 탈론액스에게 돌아가십시오.", description = "가장 강하고 어린 그리핀, 바람날개의 후계자 뾰족부리가 없어졌소! 며칠 전 어미와 함께 사냥을 나갔다가 실종됐다오. 내 생각으로는 트롤들이 잡아간 것 아닌가 싶은데...\n\n우리를 좀 도와 주십시오! 마른나무껍질 트롤 마을 두 곳에 있는 우리들을 뒤져서 뾰족부리가 있는지 알아봐 주십시오.", progress = nil, completion = "뾰족부리가 두 마을에도 없었다고? 흠... 안 좋은 소식이로군요. 그 그리핀은 다음 세대를 이끌 운명을 타고 난 녀석입니다. 녀석이 없으면 우리의 힘과 사기가 크게 꺾일 텐데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2989] = {title = "줄의 제단", objective = "줄의 제단 위를 확인한 후, 그리핀 조련사 탈론액스에게 돌아가십시오.", description = "마른나무껍질 트롤들이 뾰족부리를 납치한 것이 아니라면 썩은가지 트롤들이 데리고 간 건지도 모르겠군요. 썩은가지일족 영토의 서쪽 끝에 있는 줄의 제단으로 가서 녀석을 찾아봐 주십시오.", progress = nil, completion = "뾰족부리가 거기 없었다고? 흠, 그다지 좋은 소식은 아니군. 하지만 한편으로는 다행입니다.\n\n썩은가지 트롤은 희생 제물을 바치는 것으로 유명한 부족이니 줄의 제단에 없었다는 건 아직 무사할 수도 있다는 것...\n\n지금까지 도와줘서 정말 고맙습니다. 하지만 아직 더 큰 임무가 남아 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2990] = {title = "샤디우스 그림섀이드", objective = "뾰족부리의 깃털을 저주받은 땅에 있는 샤디우스 그림섀이드에게 가져가야 합니다.", description = "이 깃털을 샤디우스 그림섀이드라는 점쟁이에게 가져가십시오. 그는 암흑의 지식을 찾아 오래전 맹금의 봉우리를 떠났지만 마음만은 아직도 와일드해머에 속해 있지!\n\n그의 재능이 뾰족부리를 찾는 데 도움이 될 수 있을지도 모릅니다.\n\n이 깃털은 그 어린 그리핀이 잠을 자는 둥지에서 가져온 겁니다. 샤디우스에게 이 깃털을 전해 주면 그의 점치기 마법을 사용해 뾰족부리를 찾을 수도 있을 겁니다.\n\n행운을 빕니다. 저주받은 땅에 있는 네더가드 요새의 마법사 탑에서 샤디우스를 찾을 수 있을 겁니다.", progress = "선물을 가지고 온건가?", completion = "아, 그래. 이 깃털은 아주 훌륭한 그리핀의 것이로군. 아주 위대한 일을 하게 될 운명을 지닌... 무사히 성년이 될 때까지 살아남을 수 있다면 말이지만...\n\n그를 찾고 싶은 건가? 그렇다면 내가 하는 말을 귀 기울여 듣게, 용감한 &lt;class&gt; 친구...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2991] = {title = "네크룸의 메달", objective = "네크룸의 메달을 저주받은 땅에 있는 샤디우스 그림섀이드에게 가져가야 합니다.", description = "먼저 자네가 내 부탁을 좀 들어 주면 그 그리핀이 있는 곳을 알아봐주겠어. 줄파락에 네크룸 거트츄어라는 트롤이 사는데 내가 꼭 연구해 보고 싶은 메달을 갖고 있네. 그 메달을 가져오면 점을 쳐서 뾰족부리를 찾아 주겠어.\n\n줄파락은 바다 건너 서쪽으로 있는 타나리스 사막에 있지.", progress = "네크룸의 메달은 가져온 건가? 그 메달 안에 숨겨진 힘을 꼭 알아내야 하네.", completion = "아, 네크룸의 메달이로군. 소문에 의하면 이 메달이 트롤에게 자연의 한계를 뛰어넘는 기나긴 생명을 주었다고 하네. 물론 대가는 치렀지만 말이야. 나는 그... 마음에 안 드는 부작용 없이 메달의 힘을 사용할 방법을 찾으려고 하네.\n\n자네가 내 부탁을 들어 주었으니 이제 나도 약속한 바를 이행해야겠군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2992] = {title = "점치기", objective = "그림섀이드가 점치기 의식을 행하는 동안 기다리십시오.", description = "점치기 의식을 수행하도록 좀 물러서 있게나. 자네가 가져온 깃털과 그 주인 사이에 연결된 끈을 찾아서 뾰족부리가 있는 곳을 찾을 거야.\n\n그야 물론... 모든 것이 계획대로 잘 풀릴 때의 얘기지. 잘 되지 않는다면... 차라리 눈을 감아 버리는 게 좋을 거야.", progress = nil, completion = "점치기 의식이 성공했네. 뾰족부리를 보았으니 어떻게 찾을 수 있는지 말해 주지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2993] = {title = "동부 내륙지로 돌아가기", objective = "그리핀 조련사 탈론액스와 대화하십시오.", description = "뾰족부리는 동부 내륙지, 진타알로 꼭대기에 있는 절벽 위 우리 안에 갇혀 있네. 그런데 그 우리를 열 수 있는 열쇠는 타락한 여사제 헥스라는 썩은가지 트롤 부족의 대사제가 가지고 있지.\n\n자, 이제 약속을 지켰군. 자네가 임무를 완수할 수 있도록 행운을 빌겠네.", progress = nil, completion = "그림섀이드와 얘기해 봤습니까? 뭐라고 하던가요?\n\n...뭐라고요? 썩은가지 트롤들이 뾰족부리를 데리고 있다고요? 이거 큰 일이군! 군대를 소집해서라도 뾰족부리를 찾으러 가야겠습니다!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[2994] = {title = "뾰족부리 구출", objective = "진타알로의 꼭대기까지 올라가 타락한 여사제 헥스를 처치하고 뾰족부리가 갇혀 있는 우리의 열쇠를 빼앗은 다음 뾰족부리를 구출해야 합니다.", description = "뾰족부리를 구해야만 합니다!\n\n썩은가지부족 영토 중심부에 있는 진타알로의 꼭대기까지 올라가서 타락한 여사제 헥스에게서 뾰족부리가 갇혀 있는 우리 열쇠를 빼앗은 다음 뾰족부리를 구해 오십시오!", progress = nil, completion = "뾰족부리의 부모 그리핀인 날쌘바람과 서슬발톱이 처음 새끼를 품었을 때처럼 호들갑을 떨고 있습니다. 그리핀 가족이 다시 함께 있게 된 걸 보니 이 늙은 드워프의 눈에도 눈물이 핑 도는군요...\n\n뭐라고 감사를 드려야 할지 모르겠습니다. 맹금의 봉우리에 있는 그리핀들과 조련사들은 오래오래 당신의 이름을 노래하게 될 겁니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n그리핀 기수 폭풍망치그리핀 기수 다리보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[2995] = {title = "연락망", objective = "언더시티에 있는 오란 스네이크레이드가 동부 내륙지로 가서 깊은골짜기 기록문, 깊은골짜기 보고서, 그리고 깊은골짜기 쪽지를 태워달라고 부탁했습니다.", description = "쿠엘다닐 오두막은 동부 내륙지 하이 엘프들의 연락 장소입니다. 하이 엘프 사절들은 다른 종족과 유대 관계를 쌓기 위해 노력하면서 동부 내륙지 남부에 사는 마른나무껍질 트롤에 대한 정보를 공유하고 있죠. 연락 정보와 관련된 모든 문서들이 그 오두막에 보관되어 있어요.\n\n깊은골짜기 일족이 다른 종족과 동맹을 맺는 걸 그냥 두고 볼 수만은 없습니다. 깊은골짜기 일족의 문서를 모두 없애버리세요. 그들의 연락망을 완전히 끊어놓아야 합니다.", progress = nil, completion = "잘했어요. 깊은골짜기 일족이 잃어버린 정보를 되찾는 동안 녀석들의 연락망을 확실하게 차단할 수 있을 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2996] = {title = "스트라드를 찾아서", objective = "톱니항에 있는 스트라드 파선과 대화하십시오.", description = "예전에 내가 자네를 가르쳤던 적이 있지만, 이제 자네는 다른 이의 가르침을 받을 때가 되었네. 톱니항에 사는 이인데 이름은 스트라드라고 하네. 비록 인간이긴 하지만 지레 나약할 거라고 생각하진 말게. 덩치는 작아도 무척 강하다네. 그가 더 강한 소환 기술을 가르쳐 줄 수 있을 걸세. 자네는 이미 배울 준비가 된 것 같아. 지금 가 보게. 톱니항... 항구 마을 위에 있는 탑 옆에 있을 걸세.", progress = nil, completion = "오늘은 톱니항이 참 북적대지 않소? 나는 항구 도시의 바쁜 일상을 바라보는 걸 즐기지. 너무나 많은 수수께끼, 모험, 그리고 무지...\n\n당신 눈에서 증오가 번득이고 있는 것 같군. 잘 됐소. 바로 내가 찾던 눈이군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2997] = {title = "신앙의 고서", objective = "아이언포지에 있는 타이자 배틀포지와 대화하십시오.", description = "안녕하시오. 당신이 던 모로의 주민들을 돕느라 바쁘다는 것은 알고 있소. 하지만 시간이 나면 아이언포지에 들러 우리 시대 가장 존경받는 성기사 중 하나인 타이자 배틀포지를 찾아가 보시오. 젊은 성기사들이 성스러운 빛과 성기사의 의무에 대해 배울 때가 되면 그녀를 찾아간다오.\n\n신비의 전당 위층으로 가면 그녀를 찾을 수 있을 거요. 신비의 전당에 처음 가본다면 마법 지구를 먼저 찾아가면 될 거요. 그럼 행운을 빌겠소.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2998] = {title = "신앙의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화하십시오.", description = "안녕하십니까, <형제/자매>님. 우리 성기사 가운데 가장 영향력 있는 두소리안 랄께서 최근 <형제/자매>님 얘기를 하시더군요. 언뜻 들으니 이제 시험을 치를 때가 되었다는 얘기와 지금까지 잘해왔다는 칭찬도 하시더군요.\n\n나라면 시간 있을 때 스톰윈드로 가서 그분을 만나 뵙겠습니다. 그분은 대부분의 시간을 빛의 대성당에서 보내시니 분명 그곳에 계실 겁니다.", progress = nil, completion = "이곳 스톰윈드는 참 아름답지 않나?\n\n자넨 때를 너무도 잘 맞춰 와주었군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[2999] = {title = "신앙의 고서", objective = "아이언포지에 있는 타이자 배틀포지와 대화하십시오.", description = "안녕하시오. 당신이 던 모로의 주민들을 돕느라 바쁘다는 것은 알고 있소. 하지만 시간이 나면 아이언포지에 들러 우리가 가장 존경하는 성기사 중 하나인 타이자 배틀포지를 찾아가 보시오. 젊은 성기사들이 성스러운 빛과 성기사의 의무에 대해 배울 때가 되면 그녀를 찾아간다오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3000] = {title = "신앙의 고서", objective = "아이언포지에 있는 타이자 배틀포지와 대화하십시오.", description = "안녕하신가. 자네가 동부 왕국의 주민들을 돕느라 바쁘다는 것은 알고 있네만 시간이 된다면 아이언포지에 들러 당신 고향에서 가장 존경 받는 성기사 중 하나인 타이자 배틀포지를 만나 보도록 하시게나. 젊은 성기사들이 성스러운 빛과 성기사의 의무에 대해 배울 때가 되면 그녀를 찾아간다네.\n\n아이언포지의 마법 지구에 있는 신비의 전당 위층에서 그녀를 찾을 수 있을 걸세.", progress = nil, completion = "어서 오세요, 정말 반가워요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3001] = {title = "스트라드를 찾아", objective = "톱니항에 있는 스트라드 파선을 찾아가야 합니다.", description = "예전엔 자네가 내게서 기술을 배웠지만 이제는 다른 이에게서 배울 때가 되었네. 자네가 만나봐야 할 친구의 이름은 스트라드라고 하고 톱니항에 살고 있다네. 비록 인간이긴 하지만 나약하다거나 적이라고 생각하는 일은 없도록 하게나. 적어도 지금은 말이야. 아주 강한 사람이니 존중해주어야 해. 이제 자네는 준비가 된 것 같으니 그 친구가 더 강한 소환 마법을 가르쳐줄 걸세. 자, 어서 가보게. 톱니항 마을 위, 탑 옆으로 가면 그가 있을 걸세.", progress = nil, completion = "오늘은 톱니항이 참 북적대지 않소? 항구 도시의 이 고된 일상을 바라보는 게 얼마나 즐거운지 모른다오. 너무나 많은 수수께끼, 모험... 그리고 무지함...\n\n당신 눈에서 증오가 번득이고 있군? 좋아, 그걸 아주 잘 이용하게 될 테니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3002] = {title = "골두니 수정구", objective = "오그리마의 검은장미 오두막에 있는 우텔나이에게 골두니 수정구를 가져가야 합니다.", description = "비록 적을 잘 안다고는 해도 난 전사일 뿐입니다. 나로서는 이 수정구가 얼마나 강력한 것인지 전혀 말 해줄 수가 없군요.\n\n이 수정구에 대해 더 자세히 말해 줄 수 있는 마법사를 하나 알고 있습니다. 오그리마에 사는 우텔타이에게 이걸 가져가도록 하세요.", progress = "나에게 뭘 가져온 것입니까, <race>|1이여;여;?", completion = "이거 정말 흥미롭군요...\n\n이 수정구는 굉장히 강력하지만 매우 위험하기도 합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3022] = {title = "취급 주의", objective = "루테란 마을에 있는 에렐라스 앰버스카이에게 조심스럽게 포장된 상자를 가져가야 합니다.", description = "<name>, 뜻 깊은 일을 위해 몸과 마음을 아끼지 않으시는군요. 저를 더 돕고 싶으시다고요? 물론 해 주실 일이야 더 있죠!\n\n이 상자를 에렐라스 앰버스카이에게 가져다주세요. 그 드루이드는 이 알을 돌보고 부화시켜 히포그리프로 조련하죠. 텔드랏실 남부에 있는 루테란이라는 작은 마을에서 찾을 수 있을 거예요.", progress = "커글이 또 알을 부친 모양이군그래.", completion = "도와줘서 고맙소이다, &lt;name&gt;. 우리가 아니면 히포그리프가 지금처럼 번성하지는 못했을 거요. 그대도 페랄라스에서 골두니 오우거들이 숲을 완전히 망가뜨리는 현장을 보았을 테니 잘 아시겠지요.\n\n이제 그만 가보시는 게 좋겠소. 보다시피 지금 어린 히포그리프들에게 먹이를 주려던 참이라 말이오.\n\n다시 한번 감사드리오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3042] = {title = "트롤 경화제", objective = "가젯잔에 있는 트렌튼 라이트해머에게 트롤 경화제 20병을 가져가야 합니다.", description = "줄파락의 성난모래부족 트롤들은 사암에서 담금질용 경화제를 만들고는 하는데, 내 작업에도 그걸 좀 썼으면 하네. 감정가들이 아주 비싼 값을 부르는 물건이니 충분히 가지고 오면 후하게 사례하겠네.\n\n줄파락은 가젯잔의 북서쪽에 있지. 행운을 비네.", progress = "경화제는 가지고 왔나, <name>?", completion = "아주 좋은 물건이군그래! 게다가 이렇게 잔뜩 가지고 올 줄이야! 이걸 다 쓰려면 며칠은 계속 일해야겠어!\n\n고맙네, &lt;name&gt;. 자, 이건 약속한 사례금일세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3062] = {title = "검은 심장", objective = "모자케 야영지에 있는 탈로 쏜후프가 에다나의 검은 심장을 가져다 달라고 부탁했습니다.", description = "에다나 헤이트탈론은 서쪽에 있는 폐허에 사는 바람계곡일족 하피들의 여왕이라네. 그녀야말로 완전한 악의 세력이지. 소문에 듣자하니 그 하피의 심장은 수정으로 되어 있다고 하더군. 다른 모든 이들에게 느끼는 증오를 빼면 아무런 감정도 없다고 하지. 에다나에게 맞서 싸우고 그녀의 검은 심장을 가지고 내게 돌아와 주게.\n\n전에 하피들이 지니고 다닌다는 뿔에 대해 들은 적이 있는데, 폐허의 북쪽에 있는 헤이트탈론 비석 곁에서 그 뿔을 불면 그 하피 여왕이 나타난다고 하네.\n\n자신의 동족이 아니라 죽음의 사자가 자신을 부른 것이라는 걸 알게 되었을 때 그녀가 얼마나 놀랄지 상상해 보게.", progress = "에다나가 이 땅에 퍼뜨리는 증오를 반드시 멈추어야 하네.", completion = "이제 에다나가 정말로 죽었군, 고맙네. 이 심장은 자네가 날 위해 해준 일을 기리는 뜻으로 잘 간직하겠네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n날개깃 장갑강뿔 벨트\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3063] = {title = "바람계곡일족에 대한 복수", objective = "탈로 쏜후프가 바람계곡일족 하피 4마리, 바람계곡일족 약탈자 4마리, 바람계곡일족 바람마녀 4마리, 그리고 바람계곡일족 암살자 4마리를 처치해 달라고 부탁했습니다.", description = "나는 소싯적에 아주 능숙한 사냥꾼이었지. 어딜 가도 내가 두려워하는 짐승이라고는 없었네. 그 일이 있기 전까지는...\n\n난 힘겨운 전투를 치른 뒤 숲 속에 앉아 칼을 갈고 있다가 습격을 당하고 말았다네. 나를 포위했던 하피들을 피해 가까스로 위기를 모면했지. 지금도 놈들의 울음소리가 메아리치는 게 들려...\n\n그 후로 나는 변했지. 그러나 내 안에서는 증오가 끓어오르고 있네. 이렇게 오랜 세월이 흘렀지만 난 복수를 해야만 하네.\n\n바람계곡일족 하피들은 여기서 서쪽에 있는 까마귀바람 페허로 가면 찾을 수 있네. 날 위해 복수를 해 주게.", progress = nil, completion = "고맙네. 이 늙은 타우렌의 가슴에 평안을 되찾아 주었군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3065] = {title = "간결한 서판", objective = "간결한 서판을 읽어보고 시험의 골짜기에 있는 프랑과 대화하십시오.", description = "당신이 없는 동안 서판이 하나 도착했소, <name>.\n\n시간이 있다면 읽어보시오. 내가 착각한 것이 아니라면 이건 상급 전사, 프랑이 보낸 거요. 준비가 되는 대로 그에게 가보시오. 당신과 이야기를 나누고 싶은 것 같소. 동굴 밖에 있는 그늘에서 당신이 오기를 기다리고 있을 거요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3082] = {title = "글이 새겨진 서판", objective = "글이 새겨진 서판을 읽어보고 시험의 골짜기에 있는 젠샨과 대화하십시오.", description = "<name>, 당신이 자리를 비운 사이, 서판이 하나 도착했소.\n\n시간이 날 때 한번 읽어보시오. 내 기억이 맞다면 상급 사냥꾼, 젠샨이 보낸 것일 게요. 당신이 준비가 되면 이야기를 나누고 싶은 것 같소.", progress = "이 젠샨 앞에 강한 <class>이 서 있는 걸 영혼들도 인정하는군요.\n\n<class>의 역사는 호드가 가장 오랫동안 걸어온 길 중 하나예요. 아제로스에서 살아남기 위해 발버둥 칠 때 호드는 바로 우리에게 도움을 청했죠. 우리에게 가르침을 받고 수많은 비밀을 배우길 원했답니다. 호드에는 강한 주술사와 전사들이 이미 충분했지만, <class>에 대해서는 잘 몰랐던 거죠. 적어도 그 당시에는요.", completion = "이제 우리 종족은 호드의 다른 종족들에게 &lt;class&gt;의 기술을 가르치고 그들도 우리에게 다른 것들을 가르쳐 준답니다. 마치 하나의 종족인 것처럼... 지금까지 오랜 세월 동안 우린 동맹을 맺어왔어요. 그러니 당신도 호드의 일원으로서 도움이 되는 일을 하세요. 그러면 이 젠샨도 당신을 꼭 돕겠어요.\n\n이제 &lt;class&gt;의 길을 가르쳐주죠. &lt;class&gt;은 부족에게서 큰 존경을 받는다는 걸 잊지 마요. 훗날 큰 일을 해야 한다는 것도... 절대 잊지 마요.\n\n필요하다 싶으면 언제든 이 젠샨을 찾아와요. 당신이 배울 준비가 되었다면 힘 닿는 데까지 가르쳐줄 테니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3083] = {title = "암호화된 서판", objective = "암호화된 서판을 읽어보고 시험의 골짜기에 있는 르와그와 대화하십시오.", description = "<name>, 당신이 자리를 비운 사이, 서판이 하나 도착했소.\n\n시간이 날 때 한번 읽어보시오. 내 기억이 맞다면 상급 도적, 르와그가 보낸 것일 게요. 당신이 준비가 되면 이야기를 나누고 싶은 것 같소.", progress = "시험의 골짜기에 온 것을 환영하오, <name>. 내 서판을 받지 않았다면 여기 오지도 않았을 테니 바로 본론으로 들어가겠소.\n\n나는 르와그라고 하는데, 이 시험의 골짜기에서 <class>이나 소매치기를 양성하는 임무를 맡고 있소. 당신이 하는 모든 일에 검은손 <class>단이 일일이 간섭하지는 않을 테니 걱정하지 마시오. 대신 그 자들이 당신의 솜씨를 꼭 필요로 할 때는 손을 잡는 게 신상에 좋을 거요.", completion = "그런 날이 올 때까지 당신은 내가 가르치겠소. 한 수 가르쳐주겠단 말이지. 준비가 됐다 싶으면 언제라도 날 찾아오시오. 그때 수련을 더 받아도 되겠는지 보겠소. 날 보러 올 때까지 솜씨가 녹슬지 않도록 열심히 갈고 닦으시오. 아무리 보잘것없는 능력이라도 언제 어디에서 필요할지 모르는 법이니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3084] = {title = "룬으로 새겨진 서판", objective = "룬으로 새겨진 서판을 읽어보고 시험의 골짜기에 있는 시크리크와 대화하십시오.", description = "<name>, 당신이 자리를 비운 사이, 서판이 하나 도착했소.\n\n시간이 날 때 한번 읽어보시오. 내 기억이 맞다면 상급 주술사, 시크리크가 보낸 것일 게요. 당신이 준비가 되면 이야기를 나누고 싶은 것 같소.", progress = "아, 어서 오세요. 이제는 가르칠 제자들이 많아져서 하루종일 바쁘답니다. 그래도 당신 같은 사람들이 절 찾아오면 큰 보람을 느낀답니다. 제가 처음 주술을 배우기 시작할 때가 생각나거든요.", completion = "벌써 알고 있는지는 모르겠지만 자연은 우리에게 힘을 준답니다. 불과 물, 대지, 그리고 공기... 이것들이 모두 우리의 도구가 되는 것이죠.\n\n우리의 힘은 선조의 영혼에서 오는 거예요. 우리 &lt;class&gt;들이야말로 동족의 지도자라고 할 수 있죠. 스랄님이 호드를 다스리듯 말이에요. 모두 우리에게서 지혜와 보호를 구하지요. 제게 자주 수련을 받아 매사에 준비를 철저히 하도록 하세요. 힘을 더 길렀다는 생각이 들면 이리로 찾아오세요. 제가 알고 있는 모든 것을 가르쳐 드릴게요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3085] = {title = "성스러운 서판", objective = "성스러운 서판을 읽어보고 시험의 골짜기의 동굴 막사 밖에 있는 켄자이와 대화하십시오.", description = "<name>, 당신이 자리를 비운 사이, 서판이 하나 도착했소.\n\n시간이 날 때 한번 읽어보시오. 내 기억이 맞다면 상급 사제, 켄자이가 보낸 것일 게요. 당신이 준비가 되면 이야기를 나누고 싶은 것 같소.", progress = "왔군... 잘 왔네! 자네가 곧 이 켄자이를 보러 올 거라고 영혼들이 그러더군. 시험의 골짜기에 온 것을 환영하네. 이곳에 오래 머물지는 않게 되겠지만 있는 동안만은 편히 쉬게.", completion = "자네의 실력을 시험하면서 영혼을 조종하는 능력이 점점 커가는 걸 느낄 수 있을 거야. 더 크고 위대한 일을 해내기 위해 영혼을 소환하는 능력 말이야... 바로 그때가 이 켄자이가 나설 때지. 준비가 됐다 싶으면 이 늙은 켄자이를 찾아오게. 더 강력한 기술을 가르쳐줄 수 있을 거야. 하지만 그건 영혼들이 찬성할 때의 얘기지.\n\n가서 시험의 골짜기에 사는 주민들과 얘기를 나눠보게. 그리고 나중에 다시 날 찾아오게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3086] = {title = "상형 문자로 된 서판", objective = "상형 문자로 된 서판을 읽어보고 시험의 골짜기의 동굴 막사 입구 근처에 있는 마이아와 대화하십시오.", description = "<name>, 당신이 자리를 비운 사이, 서판이 하나 도착했소.\n\n시간이 날 때 한번 읽어보시오. 내 기억이 맞다면 상급 마법사, 마이아가 보낸 것일 게요. 당신이 준비가 되면 이야기를 나누고 싶은 것 같소.", progress = "벌써 이 마이아를 기쁘게 해주는군요, <name>. 좋은 일이에요. 마이아를 존중하면 이 마이아도 당신을 존중해 드리죠. 이 얘긴 일단 접어두죠. 당신은 마법을 배우러 온 거지 얘기를 나누러 온 게 아니니까요.\n\n단 이 마이아도 가르쳐줄 수 없는 마법이 한 가지 있는데, 그건 바로 이 세계에 만연하기 시작한 타락을 멈추는 방법이에요.", completion = "당신은 이 세계에서 가장 강한 존재들 가운데 하나죠, &lt;name&gt;. 그건 확실해요. 모두가 알고 있죠...\n\n하지만 조심해야 해요! 당신이 두려워해야 할 것은 엘프도, 드워프도 아닌 보이지 않는 것들이기 때문이에요. 마법은 강해요. 하고 싶지 않은 일도 하게 만들 수 있죠. 그리고 자신이 실제보다 더 강하다는 착각이 들 게도 만들죠. 인내심을 갖고 현명하게 대처하세요.\n\n수련을 받을 준비가 되면 마이아를 찾아와요. 당신에게 꼭 필요한 것들을 가르쳐줄 테니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3087] = {title = "글이 새겨진 양피지", objective = "글이 새겨진 양피지를 읽어보고 시험의 골짜기에 있는 젠샨과 대화하십시오.", description = "<name>, 당신이 자리를 비운 사이, 양피지가 도착했소.\n\n시간이 날 때 한번 읽어보시오. 내 기억이 맞다면 상급 사냥꾼, 젠샨이 보낸 것일 게요. 당신이 준비가 되면 이야기를 나누고 싶은 것 같소.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3088] = {title = "암호화된 양피지", objective = "암호화된 양피지를 읽어보고 시험의 골짜기에 있는 르와그와 대화하십시오.", description = "<name>, 당신이 자리를 비운 사이, 양피지가 하나 도착했소.\n\n시간이 날 때 한번 읽어보시오. 내 기억이 맞다면 상급 도적, 르와그가 보낸 것일 게요. 당신이 준비가 되면 이야기를 나누고 싶은 것 같소.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3089] = {title = "룬으로 새겨진 양피지", objective = "룬으로 새겨진 양피지를 읽어보고 시험의 골짜기에 있는 시크리크와 대화하십시오.", description = "<name>, 당신이 자리를 비운 사이, 양피지가 하나 도착했소.\n\n시간이 날 때 한번 읽어보시오. 내 기억이 맞다면 상급 주술사, 시크리크가 보낸 것일 게요. 당신이 준비가 되면 이야기를 나누고 싶은 것 같소.", progress = "오셨군요. 언제 오시려나 궁금해 하던 참이었어요. 그 양피지를 보낸 지 꽤 오래돼서 잘 도착했는지 걱정하고 있었거든요.\n\n이제 잡담은 그만하고... 당신이 여기에 온 이유는 선택을 받았기 때문이에요. 우리 종족의 영적인 삶을 이끌도록 선택을 받은 것이죠.", completion = "우리 선조는 당신을 통해 뜻을 전해주실 거예요. 당신은 자유자재로 자연의 힘을 불러내는 힘을 갖게 될 겁니다. 그러면 마치 애들 장난처럼 적을 간단히 처치하고, 숨을 쉬는 것만큼 쉽게 동료를 치유할 수 있게 되죠. 새로운 난관에 부닥칠 때면 항상 이러한 사실을 염두에 두시도록 하고, 원하면 언제든지 절 찾아오세요. 준비가 됐을 때 여기로 저를 찾아오시면 새로운 마법을 가르쳐주고 올바른 길로 인도해 드리겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3090] = {title = "오래된 양피지", objective = "오래된 양피지를 읽어보고 시험의 골짜기의 동굴 막사에 있는 나르톡과 대화하십시오.", description = "<name>, 당신이 자리를 비운 사이, 양피지가 하나 도착했소.\n\n시간이 날 때 한번 읽어보시오. 내 기억이 맞다면 상급 흑마법사, 나르톡이 보낸 것일 게요. 당신이 준비가 되면 이야기를 나누고 싶은 것 같소.", progress = "드디어 왔군... 그것도 혼자서 말이야. 좋았어.\n\n지금은 바보 천치들의 세상이라네. 심지어는 그 강대하다는 스랄마저도 다른 이들이 생각하는 것보다 더 큰 결점이 있어. 그는 이 땅을 완전히 우리 것으로 만드는 데 반드시 필요한 힘을 외면하고 있다네! 이제 우리는 뒤틀린 황천에서 온 존재들에게 휘둘리고 이용당하던 때와는 달라졌어. 우리는 자부심과 주인 의식도 있고, 아주 강해졌다고.", completion = "이제 자네도 우리와 한 식구가 됐군. 그렇다고 오해는 하지 말게. 많은 자들이 부러워하는 힘을 이용할 수 있다는 이유만으로 어디서나 쉽게 받아들여지는 것은 아니니까... 스랄이 우리 종족을 오그리마에 머무르게 하는 이유는 그래도 같은 동족이기 때문이지. 스랄이 등을 돌리면 우리는 스랄을 노예로 삼았던 인간들처럼 불쌍한 존재가 될 테니까. 그러니까 내 말을 잘 듣게. 몸은 강해질 수 있어. 하지만 정신이 어리석다면 이미 죽은 몸이나 마찬가지야.\n\n마법을 배우려거든 날 다시 찾아오도록 하게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3091] = {title = "간결한 쪽지", objective = "간결한 쪽지를 읽고 나라체 야영지에 있는 하루트 썬더혼과 대화해야 합니다.", description = "이보시오. 바로 몇 분전에 전령이 그대를 찾았었소. 내 생각엔 상급 전사인 하루트 썬더혼님이 보낸 것 같소이다. 내용이 그리 길지 않은 것 같으니 어서 읽어 보는 게 좋겠소.", progress = "아. 드디어 왔군. 내가 쪽지에 적은 내용은 사실이라네. 우리 부족의 드루이드나 주술사들처럼 우리도 특별한 부류이며 똑같이 중요하다네. 우린 우리 부족의 영토를 지키고, 켄타우로스를 사냥하며, 전쟁터에 나가도록 부름을 받은 자들이지.", completion = "우리는 모두 각각 부족 내에서 해야 할 역할이 있고 모두 똑같은 의식을 통과해야 하지. 자만심에 빠져 달리 생각하는 일이 없도록 하게.\n\n전투의 영광을 추구하고 우리의 가장 오래된 선조의 길을 따르려는 새로운 &lt;class&gt;들을 훈련하기 위해 내가 여기 남아 있는 거라네. 준비가 됐다고 생각될 때 내게 돌아오게. 전력을 다해 자네를 훈련시켜 줄 테니. 부족의 축복이 함께하기를 바라네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3092] = {title = "글이 새겨진 쪽지", objective = "글이 새겨진 쪽지를 읽고 붉은구름 고원에 있는 랑카 파샷과 대화해야 합니다.", description = "이보시오. 바로 몇 분전에 전령이 그대를 찾았었소. 내 생각엔 상급 사냥꾼인 랑카 파샷님이 보낸 것 같소이다. 내용이 그리 길지 않은 것 같으니 어서 읽어 보는 게 좋겠소.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3093] = {title = "룬으로 새겨진 쪽지", objective = "룬으로 새겨진 쪽지를 읽고 나라체 야영지에 있는 밀라 던스트라이더와 대화해야 합니다.", description = "이보시오. 바로 몇 분 전에 전령이 그대를 찾았었소. 내 생각엔 상급 주술사인 밀라 던스트라이더님이 보낸 것 같소이다. 내용이 그리 길지 않은 것 같으니 어서 읽어 보는 게 좋겠소.", progress = "하늘에서 물이 떨어지듯 재빨리 나타나셨군. 서둘러 와 주어서 기쁘오. 당신이 여기에서 나를 만나는 것의 중요함을 깨달았다는 것이니 말이오. 나는 지도자는 아니지만 자연의 원소를 이해하고 우리 부족의 영혼들과 대화를 나눌 수 있소. 당신도 그렇게 할 수 있도록 가르치겠소.", completion = "우리는 앞으로 여러 번 만나게 될 것이오. 매번 올 때마다 더 강해져서 좀 더 준비가 되어서 떠날 수 있기를 바라오. 영원의 불꽃처럼 당신의 영혼은 밝고 뜨겁게 타오르게 될 것이오.\n\n자, 가시오. 가서 자신을 시험해 보시오. 난 여기 있을 테니 필요할 땐 날 언제든지 찾아오시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3094] = {title = "푸른 쪽지", objective = "푸른 쪽지를 읽고 나라체 야영지에 있는 가트 미스트러너와 대화해야 합니다.", description = "이보시오. 바로 몇 분전에 전령이 그대를 찾았었소. 내 생각엔 상급 드루이드인 가트 미스트러너님이 보낸 것 같소이다. 내용이 그리 길지 않은 것 같으니 어서 읽어 보는 게 좋겠소.", progress = "도착했군. 잘 왔소. 우리 선조의 영혼이 멀고어와 그 너머에서 동요하고 있는데 그 이유를 알 수가 없소. 자연의 영혼들이 말하는 소리에 귀를 기울이고 그들의 화신으로서 행동하는 것은 당신의 영원한 임무가 될 것이니 명심하시오.", completion = "비록 자연에 대해 나이트 엘프들과 공통된 유대 관계가 있다고는 하나 그들에게서 따뜻한 환영을 받을 거라는 생각은 버리시오. 자만으로 인해 그들의 시야가 더욱 좁아지고 있으니까 말이오. 하지만 그건 우리가 관여할 바 아니지. 당신은 대지모신의 가르침에만 귀를 기울이면 되는 것이오. 당신의 지혜가 깊어지면 내가 알고 있는 것들을 가르쳐 주지.\n\n나를 종종 찾아오시오. 대지모신께서는 마음을 다해 헌신하는 자들에게 어마어마한 능력을 내리신다는 것을 알게 될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3095] = {title = "간결한 두루마리", objective = "간결한 두루마리를 읽고 데스넬에 있는 다날 스턴과 대화해야 합니다.", description = "아, 자네가 어리석은 스컬지 놈들을 상대하러 나간 동안 이 간결한 두루마리가 도착했네. 두루마리에 상급 전사인 다날 스턴의 인장이 찍힌 것으로 보아 중요한 문제가 있는 것 같네. 다시 여행을 떠나기 전에 시간을 내서 이 두루마리를 읽어보는 게 좋겠네.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3096] = {title = "암호화된 두루마리", objective = "암호화된 두루마리를 읽고 데스넬에 있는 데이비드 트리아스와 대화해야 합니다.", description = "아, 자네가 어리석은 스컬지 놈들을 상대하러 나간 동안 이 암호화된 두루마리가 도착했네. 두루마리에 상급 도적 데이비드 트리아스의 인장이 찍힌 것으로 보아 중요한 문제가 있는 것 같네. 다시 여행을 떠나기 전에 시간을 내서 이 두루마리를 읽어보는 게 좋겠네.", progress = "그래, 두루마리를 본거로군? 잘 왔소. 앞으로 더 많은 <class>이 필요할 테니 말이야. 때가 되면 그림자추적자가 당신을 찾아올 테니 가서 실수를 한다든가 후회할 짓은 하지 마시오. 그들이 원하는 건 실력 있는 요원이야... 소매치기나 멍청이들이 아니란 말이지.", completion = "나는 주로 이 여관에서 지내면서 새로운 인재를 찾거나 실력이 괜찮은 자들이 있는지 알아보겠소. 얌전하게만 지내면 당신에게 몇 가지 가르쳐줄 수도 있소이다. 필요할 때 언제든지 찾아오시오. 새로운 기술 한두 가지쯤 익힐 준비가 됐는지 보도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3097] = {title = "성스러운 두루마리", objective = "성스러운 두루마리를 읽고 데스넬의 교회에 있는 어둠의 사제 듀스텐과 대화해야 합니다.", description = "아, 자네가 어리석은 스컬지 놈들을 상대하러 나간 동안 이 성스러운 두루마리가 도착했네. 두루마리에 상급 사제 어둠의사제 듀스텐의 인장이 찍힌 것으로 보아 중요한 문제가 있는 것 같네. 다시 여행을 떠나기 전에 시간을 내서 이 편지를 읽어보는 게 좋겠네.", progress = "아. 화재, 역병, 폭동, 그보다 더 심각한 일들이 일어나는 이 와중에도 또 하나의 충실한 신도가 날 찾아왔군. 어서 오게나, <class>|1이여;여;. 자네가 뭔가 자극이 될 만한 것을 찾아 나서기로 결정을 내리기 전에 잠시 내가 몇 가지만 말하도록 하지. 이제 성스러운 빛은 자네와 아무 상관이 없다네. 선조의 영혼이란 것도 동화에 불과하고 황천의 생물들도 자네를 원치 않아.\n\n무슨 말인지 알겠나?", completion = "우리가 자유 의지 하나로 살아남았다는 것 한 가지만 알고 있으면 되네. 우리가 다른 이들과 다른 이유는 자신을 믿는다는 것이야. 그리고 우리는 우리의 힘으로 아제로스 전체에 큰 변화를 가져올 것일세. 약한 자들은 자네에게 기대려고 할 거야. 부패한 자들은 자네를 주인님이라 부를 것이고, 무지한 자들은 자네의 인도를 받으려고 할 것일세. 때가 되면 이용할 수 있도록 자네에게 필요한 기술을 가르쳐주는 것이 내 임무지. 경험을 쌓거든 날 찾아오게나. 준비가 되면 더 큰 기술을 가르쳐주도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3098] = {title = "상형 문자로 된 두루마리", objective = "상형 문자로 된 두루마리를 읽고 데스넬 교회에 있는 이자벨라와 대화해야 합니다.", description = "아, 자네가 어리석은 스컬지 놈들을 상대하러 나간 동안 이 상형 문자로 된 두루마리가 도착했네. 두루마리에 상급 마법사 이자벨라의 인장이 찍힌 것으로 보아 중요한 문제가 있는 것 같네. 다시 여행을 떠나기 전에 시간을 내서 이 두루마리를 읽어보는 게 좋겠네.", progress = "찾아올지 알고 있었습니다, <class>|1이여;여;. 당신이 혼자 힘으로 길을 갈 의지가 없어서가 아니라 우리는 같은 계열이기 때문이죠. 우린 둘 다 고통을 느끼고 경험했으며, 우리 것을 되찾기 위한 힘을 원하고 있습니다. 이 땅, 우리의 삶, 그리고 우리의 숙명을 말이죠. 하지만 당신은 아직 배워야 할 게 많답니다.", completion = "우리에게 맞서는 자들을 쓰러뜨릴 만큼 강해지려면 나를 자주 찾아와야 합니다. 마법의 규칙은 아직 당신에게 해당됩니다. 앞으로 계속해서 타락이 한밤의 굶주린 늑대처럼 당신을 따라다닐 거예요. 타락의 유혹은 마치 중독과 같죠. 항상 당신 곁에 있고 싶어하는 오랜 연인처럼 말이에요. 하지만 이런 것들은 모두 물리칠 수 있습니다. 당신이 허락하지 않는 한 당신을 넘보지 못할 거예요.\n\n자, 가세요. 더 강해졌을 때 다시 찾아오세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3099] = {title = "오래된 두루마리", objective = "오래된 두루마리를 읽고 데스넬에 있는 맥시밀리언과 대화해야 합니다.", description = "아, 자네가 어리석은 스컬지 놈들을 상대하러 나간 동안 이 암호화된 두루마리가 도착했네. 두루마리에 상급 흑마법사 맥시밀리언의 인장이 찍힌 것으로 보아 중요한 문제가 있는 것 같네. 다시 여행을 떠나기 전에 시간을 내서 이 두루마리를 읽어보는 게 좋겠네.", progress = "어서 오시오. 당신이 올 줄 알고 있었소. 오는 건 시간 문제였으니까 말이야.\n\n내가 한 얘기가 꽤 흥미롭지 않았소? 내 말이 적중한 것이지. 당신의 내면에서 내가 말한 것이 옳다고 느낀 거요. 잘 됐소이다.\n\n나는 실바나스 여왕님을 배신하는 것이 아니라는 것만 알아두시오. 그분의 믿음이 포세이큰을 지금과 같은 상황에 처하도록 했으니 오히려 내 주장을 반기실 거요.", completion = "주인이 누구던 간에 노예는 노예라고 말했었지. 기억나오? 우리 둘 모두 그러한 지배력이 우리를 움직이는 힘이라는 걸 알고 있소. 우리는 생물들을 다스리려고 하지. 우리는 더 강하기에 지금보다 더 많은 존경을 받을 자격이 있다는 사실도 알고 있소. 이제 그 존경을 받을 때가 왔소.\n\n이 투쟁에서 내가 당신의 동지가 되어주겠소. 우리의 자유, 우리에게 충성을 바칠 자들을 찾을 수 있는 자유를 위한 투쟁 말이오. 준비가 되면 내게 되돌아오시오. 그러면 내가 아는 것을 모두 가르쳐주겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3100] = {title = "간결한 편지", objective = "간결한 편지를 읽고 노스샤이어 수도원에 있는 레인 비셰어와 대화해야 합니다.", description = "자네가 코볼트 야영지에서 돌아오자마자 이 상형 문자로 된 편지를 전해 달라는 부탁을 받았네. 이 서신은 상급 전사인 레인 비셰어가 보낸 것일세. 다른 볼일을 보러 가기 전에 어서 편지를 읽어 보는 게 좋겠네.", progress = "아, 내 편지를 받은 모양이군... 잘 됐네.\n\n요즘 들어 엘윈에 수많은 <class>들이 몰려들고 있네. 스톰윈드로서는 좋은 소식이지만 이 지역의 코볼트나 데피아즈단 녀석들에게는 나쁜 소식이지, 하하.", completion = "가서 싸울 준비를 하고 지형을 익힌 후에 훈련이 필요할 때면 언제든지 다시 날 찾아오게. 난 밤낮 가리지 않고 여기 있을 테니까 말이야.\n\n은빛 성기사단이 이곳을 꽤 안전하게 잘 지키고는 있지만, 다른 주민들을 만나 보면 모두 &lt;class&gt;가 도울만한 일들이 있을 걸세. 자, 그럼 행운을 빌겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3101] = {title = "신성한 편지", objective = "신성한 편지를 읽고 노스샤이어 수도원에 있는 수사 사무엘과 대화해야 합니다.", description = "자네가 코볼트 야영지에서 돌아오자마자 이 신성한 편지를 전해 달라는 부탁을 받았네. 이 서신은 상급 성기사인 수사 사무엘이 보낸 것일세. 다른 볼일을 보러 가기 전에 어서 편지를 읽어 보는 게 좋겠네.", progress = "드디어! 얼굴을 보게 됐군. 노스샤이어에 잘 왔소. 일이 어떻게 돌아가는지 배우는 짧은 기간 이곳이 당신 고향이 될 것이오. 하지만, 알아 두시오. 조만간 당신도 여기서 그리 멀지 않은 곳에 있는 스톰윈드로 가게 될 것이란 사실을... 은빛<class>단의 기사여, 그때까지는 인내심을 갖고 참아야 하오.", completion = "여기 있는 동안 몇 가지 알아두어야 할 것이 더 있소. 이 땅에 사는 수많은 이들에게 있어 당신은 하나의 상징적 존재이니 그에 맞게 처신하도록 하시오. 당신 안에서 성스러운 빛이 빛나고 있고 그것은 우리 동지와 적 모두에게 분명히 드러날 것이오.\n\n또한 지혜로움과 힘이 커지면 그에 따라 새로운 능력을 익히기 위해 훈련이 필요하오. 바로 그때 내가 도움을 줄 것이오. 이곳 노스샤이어에서 어느 정도 경험을 쌓았다고 생각되면 다시 나를 찾아오시오. 당신이 배울 때가 되었다고 생각되는 것들을 가르쳐 주도록 하겠소. 행운을 비오, 은빛 &lt;class&gt;여!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3102] = {title = "암호화된 편지", objective = "암호화된 편지를 읽고 노스샤이어 수도원 뒤 마구간에 있는 요리크 케리던과 대화해야 합니다.", description = "자네가 코볼트 야영지에서 돌아오자마자 이 상형 문자로 된 편지를 전해 달라는 부탁을 받았네. 이 서신은 상급 도적인 요리크 케리던이 보낸 것일세. 다른 볼일을 보러 가기 전에 어서 편지를 읽어 보는 게 좋겠네.", progress = "무사히 여기까지 왔군그래. 보아하니 사람들의 눈에도 그다지 많이 띄지 않은 것 같고... 그 정도면 만족스럽소. 난 이 뒤에 있으면서 그다지 시선을 끌고 싶지는 않거든... 조용히 지내는 게 좋지. 무슨 말인지 당신도 알 거요.\n\n아직 아무 소동도 일어나지 않았소? 다행이군. 좀 있으면 그것도 달라질 거요.", completion = "당신도 우리의 실력을 필요로 하는 단체가 꽤 있다는 사실을 곧 알게 될 거요. 모험가들, SI:7... 흠, 심지어는 데피아즈 결사단도 스톰윈드 내에 첩자 한둘은 마다하지 않을 거요. 하지만 당신은 당신 자신의 길이 있다는 사실만은 명심하시오. 그 누구도 당신이 하고 싶지 않은 일에 억지로 밀어넣게 내버려두지 마시오! 게다가 현재 주도권을 쥐고 있는 것은 우리들이니까... 적어도 게임이 끝나기 전까지는 그렇지. 무슨 말인지 알겠소?\n\n어쨌든, 난 내 소개를 하고 뭐든 훈련이 필요하면 내가 여기 있다는 것을 기억하라는 말을 하고 싶었소. 언제든지 환영하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3103] = {title = "성스러운 편지", objective = "성스러운 편지를 읽고 노스샤이어 수도원에 있는 여사제 아네타와 대화해야 합니다.", description = "자네가 코볼트 야영지에서 돌아오자마자 이 상형 문자로 된 편지를 전해 달라는 부탁을 받았네. 이 서신은 상급 사제인 여사제 아네타가 보낸 것일세. 다른 볼일을 보러 가기 전에 어서 편지를 읽어 보는 게 좋겠네.", progress = "아, 드디어 왔군요. 날 찾아올 줄 알고 있었습니다. 성스러운 빛이 당신과 당신이 선택한 길을 비추고 있답니다. 이 시대는 가혹합니다. 아직도 불타는 군단의 세력이 아제로스에 남아 있고 칼림도어 전체가 그 자신의 시련으로부터 자신을 보호할 새로운 방법을 찾고 있어요. 그리고 가능한 많은 이들을 돕는 것은 당신의 소임입니다.", completion = "경험이 쌓여 가면서 나를 찾아오면 최선을 다해 내 지식을 전수하도록 하겠습니다. 그전까지 가슴에 동정심을 품고 지혜의 인도를 받으십시오. 당신이 실천하면 이 세계는 좀 더 나은 곳이 되어갈 것이라는 사실을 명심하도록 하세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3104] = {title = "상형 문자로 된 편지", objective = "상형 문자로 된 편지를 읽고 노스샤이어 수도원 안에 있는 켈덴 브레멘과 대화해야 합니다.", description = "자네가 코볼트 야영지에서 돌아오자마자 이 상형 문자로 된 편지를 전해 달라는 부탁을 받았네. 이 서신은 상급 마법사인 켈덴 브레멘이 보낸 것일세. 다른 볼일을 보러 가기 전에 어서 편지를 읽어 보는 게 좋겠네.", progress = "안녕하시오. 난 상급 <class> 켈덴이라고 합니다. 무슨 일이시오?", completion = "하하, 내가 쓴 편지를 보면 당신이 &lt;class&gt;의 길을 포기하지 않으리란 걸 알고 있었소. 그럼 이제 당신의 운명을 받아들일 준비가 되었소? 당신이 지식과 힘을 추구하는 것을 방해하는 신들과 다른 모든 세력들에 도전할 준비가 되었소?\n\n솔직히 말하지. 사람들은 당신을 존경하는 것만큼이나 당신을 두려워하게 될 것이오. 하지만 언제든 훈련이 필요할 때 내가 여기서 기다리고 있다는 것도 알아두시기 바라오. 좀 더 강해지게 되면 나를 찾아오기만 하면 되오. 당신의 마법이 당신을 지켜줄 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3105] = {title = "오래된 편지", objective = "오래된 편지를 읽고 노스샤이어 수도원 옆에 있는 드루실라 라 살르와 대화해야 합니다.", description = "자네가 코볼트 야영지에서 돌아오자마자 이 상형 문자로 된 편지를 전해 달라는 부탁을 받았네. 이 서신은 상급 흑마법사인 드루실라 라 살르가 보낸 것일세. 다른 볼일을 보러 가기 전에 어서 편지를 읽어 보는 게 좋겠네.", progress = "아, 왔군. 그것도 아주 제때에 딱 맞춰 찾아왔어. 조금 전에 경비병 몇이 여기 와서 나를 희한하다는 듯이 쳐다보고 가더군. 형편없는 것들...", completion = "힘이 점점 강해지면 당신은 유혹을 받게 될 것이니 항상 자신을 제어할 줄 알아야 하오. 비전술을 익힌 자라면 누구에게나 타락이 찾아올 수 있는 법이라는 건 거짓말이 아니오. 뒤틀린 황천에서 온 생물들을 다루는 자라면 더욱 그렇지. 인내심을 가지고 신중하게 행동해야만 하오... 하지만 그렇다고 해서 그게 당신의 야망을 억누르게 하진 마시오.\n\n힘이 더 강해져 가거든 우리의 길에 대해서 더 가르쳐 줄 테니 날 다시 찾아오시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3106] = {title = "간결한 룬", objective = "간결한 룬을 읽어보고 눈마루 골짜기에 있는 스란 코르만과 대화하십시오.", description = "자네가 날 도우러 간 사이, 이 룬이 자네 앞으로 도착했네. 시간을 내서 한번 읽어보게. 상급 전사, 스란이 보낸 것 같아. 쭉 훑어 봐뒀다가 짬이 나면 앤빌마로 가서 만나보도록 하게.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3107] = {title = "신성한 룬", objective = "신성한 룬을 읽어보고 눈마루 골짜기에서 브로모스 그럼너를 찾아 대화해야 합니다.", description = "자네가 날 도우러 간 사이, 이 룬이 자네 앞으로 도착했네. 시간을 내서 한번 읽어보게. 상급 성기사, 브로모스가 보낸 것 같아. 쭉 훑어 봐뒀다가 짬이 나면 앤빌마로 가서 만나보도록 하게.", progress = "제시간에 딱 맞춰 왔군. 이곳 눈마루 골짜기는 물론 그 너머에도 당신이 할 일은 무척이나 많소. 당신이 내 도움을 필요로 하는 만큼이나 나도 당신의 도움이 필요하오!\n\n은빛<class>단의 일원으로서 임무를 수행할 준비를 하시오.", completion = "인간들은 우리에게 성스러운 빛에 대해 가르쳐 주었고, 그들의 질서가 인간들 자신과 동부 왕국 전체를 수호하는데 얼마나 중요한 것인지 가르쳐 주었소. 우리는 뿌리 깊은 전통을 존중하고, 한 사람의 희생이 고통을 구원으로 바꿀 수 있다는 사실을 믿고 있지.\n\n한동안 우리 둘은 함께할 것이오. 언제든지 수련할 준비가 됐다 싶으면 내게 돌아오시오. 그러면 당신에게 가르칠 것이 있는지 보겠소. 당신을 무방비 상태로 위험한 세상에 내보낼 수는 없는 일이니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3108] = {title = "글이 새겨진 룬", objective = "글이 새겨진 룬을 읽어보고 눈마루 골짜기에 있는 토르가스 그림슨과 대화하십시오.", description = "자네가 날 도우러 간 사이, 이 룬이 자네 앞으로 도착했네. 시간을 내서 한번 읽어보게. 상급 사냥꾼, 토르가스가 보낸 것 같아. 쭉 훑어 봐뒀다가 짬이 나면 앤빌마로 가서 만나보도록 하게.", progress = "왔군! 여길 찾아 오다니 다행이오! 내 뒤를 밟지는 않았겠지. 하하!\n\n<class>은 상당히 전통이 깊은 직업이지. 대지의 법칙을 배우는 것이나 산 속에서 곰을 추적하는 것, 심지어 살아남는 것 자체에도 굉장한 용기와 재간이 필요하지. 할 수 있겠소?", completion = "한 가지 꼭 명심해야 할 게 있다면 자신이 살고 있는 세상을 존중할 줄 알아야 한다는 거요. 곳곳에 널린 야수들, 무기의 광택, 탄환의 무게감, 살을 에는 듯한 추위와 성난 바람... 이 모든 것들과 아주 친숙해져야 하오.\n\n나도 힘 닿는 데까지야 돕겠지만 대부분 당신의 손에 달렸소. 준비가 되었다고 생각되면 언제든 내게 다시 오시오. 필요한 게 있으면 얼마든지 가르쳐줄 테니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3109] = {title = "암호화된 룬", objective = "암호화된 룬을 읽어보고 눈마루 골짜기에 있는 솔름 하르그린과 대화하십시오.", description = "자네가 날 도우러 간 사이에 자네 앞으로 이 룬이 도착했네. 시간을 내서 한번 읽어보게. 상급 도적, 솔름이 보낸 것 같아. 쭉 훑어 봐뒀다가 짬이 나면 앤빌마로 가서 만나보도록 하게.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3110] = {title = "성스러운 룬", objective = "성스러운 룬을 읽어보고 앤빌마에 있는 브란스토크 칼더와 대화하십시오.", description = "자네가 날 도우러 간 사이, 이 룬이 자네 앞으로 도착했네. 시간을 내서 한번 읽어보게. 상급 사제, 브란스토크가 보낸 것 같아. 쭉 훑어 봐뒀다가 짬이 나면 앤빌마로 가서 만나보도록 하게.", progress = "아핫! 왔군... 잘 왔습니다!\n\n조금만 더 늦었으면 당신이 오리라는 믿음이 무너질 뻔했군요. 믿음이 무너진다니... 웃으라고 한 소리니 신경 쓰지 마세요. 어찌 됐건 재미없는 농담이나 듣자고 여기 온건 아닐 테니 말입니다.", completion = "&lt;class&gt;의 길을 찾을 수 있도록 눈마루 골짜기에서 수련을 도와주는 자가 바로 납니다. 준비가 됐다 싶으면 다시 오세요. 몹쓸 트로그 녀석들을 눈마루 골짜기에서 몰아낼 마법을 한두 가지 가르쳐도 되겠는지 보도록 하지요.\n\n성스러운 빛이... 그리고 아이언포지 전체가 당신과 함께하고 있습니다. 영웅이 되라고 부담을 주는 건 아니지만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3112] = {title = "간결한 쪽지", objective = "간결한 쪽지를 읽어보고 눈마루 골짜기에 있는 스란 코르만과 대화하십시오.", description = "자네가 날 도우러 간 사이, 이 쪽지가 자네 앞으로 도착했네. 시간을 내서 한번 읽어보게. 상급 전사, 스란이 보낸 것 같아. 쭉 훑어 봐뒀다가 짬이 나면 앤빌마로 가서 만나보도록 하게.", progress = "임무가 적힌 쪽지를 받은 <race>이 또 하나 찾아왔군... 희한한 일이야.\n\n아니, 아니. 당신을 놀리는 게 아니오. 당신네 <race>들 끈기 하나는 높이 평가할 만하지. 그건 확실해. 나라도 검은무쇠단 드워프들이 내 고향 아이언포지를 점령했다면 약이 올랐을 거요. 그러니까 내가 당신네가 처한 곤경에는 아랑곳하지 않는다는 생각은 마시오.", completion = "요즘엔 이런 걸 뭐라고 부르는지 모르겠소만 이게 당신들에겐 절대 사명과 같으니, 당신네 &lt;race&gt;들이 고향을 되찾을 수 있도록 최선을 다해 도와주겠소.\n\n준비가 된 것 같으면 내가 가진 기술을 기꺼이 나누어줄 테니 이 스란을 다시 찾아오시오. 내게 수련을 받으려면 비용이 조금 들기는 하지만 그리 비싸진 않을 거요. 행운을 빌겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3113] = {title = "암호화된 쪽지", objective = "암호화된 쪽지를 읽어보고 눈마루 골짜기에 있는 솔름 하르그린과 대화하십시오.", description = "자네가 날 도우러 간 사이, 이 쪽지가 자네 앞으로 도착했네. 시간을 내서 한번 읽어보게. 상급 도적, 솔름이 보낸 것 같아. 쭉 훑어 봐뒀다가 짬이 나면 앤빌마로 가서 만나보도록 하게.", progress = "내 쪽지를 받고 찾아와줘서 기쁘군. 높은 사람이 보낸 쪽지처럼 보이게 위조한 것은 미안하게 생각하오. 기분 나쁘게 할 생각은 없었소이다. 그냥 다른 종족끼리도 힘을 합해야 한다고 알려주고 싶었을 뿐이오.\n\n당신 종족과 우리 종족이 같은 도시에서 지내는 것은 좋지 않다고 생각하는 자들도 있지만 나는 우리가 공생할 수 있다고 생각하는데... 당신 생각은 어떻소?", completion = "나는 소소한 분실 사건에 의심을 받아 휘말리지 않으려고 이곳에서만 조용히 지내고 있소. 혹시라도 수련이라던가 다른 것들이 필요하면 언제든지 찾아오시오.\n\n우린 마음이 통하는 것 같군. 마지막까지 믿을 수 있는 거라곤 결국 가족밖에 없소. 우리도 바로 그런 관계가 되는 게 아니겠소? 놈리건이... 침략당했든, 우리에게 어떤 고난이 닥쳐오든 간에 우리는 서로에게 힘이 돼주는 거요. 좋은 게 좋은 거 아니겠소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3114] = {title = "상형 문자로 된 쪽지", objective = "상형 문자로 된 쪽지를 읽어보고 눈마루 골짜기 위 앤빌마에 있는 마릭 너리빗과 대화하십시오.", description = "당신이 절 도우러 간 사이, 이 쪽지가 당신 앞으로 이 쪽지가 도착했습니다. 시간을 내서 한번 읽어보도록 하세요. 상급 마법사, 마릭이 보낸 것 같으니, 쭉 훑어 봐뒀다가 짬이 나면 앤빌마로 가서 그를 만나보도록 하세요.", progress = "응, 뭐라고 했소? 더 크게 말해주지 않겠소? 술 몇 잔만 들어가면 귀까지 어두워져서 말이야.", completion = "아, 그렇지! 비전술... 물론이지.\n\n그런데 한 가지 알아두시오. 문제 일으키지 말고 돈이나 좀 모아서 나한테 술 한잔 대접하던가... 아니면 당신이 원하는 마법을 하던가 하시오. 그리고 놈리건 근처에는 얼씬도 하지 말고. 그것 말고는 다른 할 말이 없으니 좋은 하루 보내시오! 내가 보고 싶다던가 수련을 받고 싶으면 여기로 날 찾아오시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3115] = {title = "오래된 쪽지", objective = "오래된 쪽지를 읽고 눈마루 골짜기 위의 앤빌마에 있는 알라마 그림과 대화하십시오.", description = "자네가 날 도우러 간 사이, 이 쪽지가 자네 앞으로 도착했네. 시간을 내서 한번 읽어보게. 상급 흑마법사, 알라마가 보낸 것 같아. 쭉 훑어 봐뒀다가 짬이 나면 앤빌마로 가서 만나보도록 하게.\n\n하지만 신중하게 행동해야 할 거야. <name>, 자네 종족은 그 부근에서 별로 환영받지 못하니까.", progress = "잘 왔소! 보아하니 내 쪽지를 받았군.\n\n다른 멍청이들에게는 신경 쓸 것 없소. 성스러운 빛?! 검과 방패?! 이런 것들은 우리처럼 생각이 깨인 자들이 갈 길이 아니오. 그 '강력한' 마법이란 것이 우리의 고향을 어떻게 만들었는지 보시오. 우리 종족은 거의 말살될 뻔했지. 그 망할 놈의 기계와 함께... 이제 우린 드워프들에게 의지해야 하는 신세야. 드워프 녀석들은 우리가 고향을 재건하는 것을 돕기보다는 인간들과 동맹을 맺는 데 시간을 보낼 것이오. 우리는 그들의 하급 시민이나 다름없소. 녀석들이 우리를 어떤 눈으로 보는지 알겠소?", completion = "하지만 그런 것들은 중요하지 않지. 중요한 건 바로 당신이 당신만의 성스러운 빛을 보게 되었다는 거야! 당신은 진정한 힘의 근원을 알고 있소. 그리고 우리만의 동맹을 갖는 것이 훨씬 더... 현명하다는 것도 알고 있지. 주어진 임무가 어떤 것이든 마지막 숨을 거둘 때까지 함께하는 그런 특별한 친구 말이야.\n\n그래서 내가 바로 여기에 온 것이오. 당신에게 그런 특별한 힘의 기본에 대해 가르쳐줄 수 있으니 종종 날 찾아오시오. 그럼 내가 아는 한 모든 마법을 가르쳐주겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3116] = {title = "간결한 도장", objective = "간결한 도장을 읽어보고 그늘 협곡에 있는 알리시아와 대화하십시오.", description = "이 도장은 상급 전사 알리시아께서 전령을 통해 전달한 것입니다. 시간이 날 때 한번 도장을 읽고 그분을 찾아가 보십시오. 알리시아께서 하실 말씀이 있는 것 같습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3117] = {title = "글이 새겨진 도장", objective = "글이 새겨진 도장을 읽어보고 그늘 협곡 알드랏실 꼭대기에 있는 아얀나 에버스트라이드와 대화하십시오.", description = "이 도장은 상급 사냥꾼 아얀나께서 전령을 통해 전달한 것입니다. 시간이 날 때 한번 도장을 읽고 그분을 찾아가 보십시오. 아얀나가 당신에게 할 말이 있는 것 같습니다.", progress = "드디어 도착했군요. 그늘 협곡에 오신 걸 환영합니다. 그대의 몸과 마음이 모두 평안하실 것으로 믿습니다.\n\n전에도 말했듯이, 여기서 저는 짐승을 길들여 전투에 이용하는 법, 한치의 오차도 없이 활을 쏘는 법, 우리가 고향이라고 부르는 이 땅과 이 너머에 있는 땅을 존중하는 법 등 <class>으로서 갖추어야 할 기술을 그대에게 가르칠 것입니다.", completion = "그늘 협곡에서 가르침을 받아 경험이 더 쌓이면 저를 찾아오세요. &lt;class&gt;의 길을 더 깊이 이해할 수 있도록 제가 도와드리겠습니다.\n\n지금은 아주 위험한 시기랍니다. 그대의 야수가 지닌 능력을 과대평가하지 마십시오. 이 세계에는 그대가 생각하는 것보다 더 위험한 일들이 존재하고 있습니다. 엘룬께서 늘 함께하시길 바랍니다. 다음에 다시 만나기를 기대할 게요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3118] = {title = "암호화된 도장", objective = "암호화된 도장을 읽어보고 그늘 협곡에 있는 프라훈 섀이드위스퍼와 대화하십시오.", description = "이 도장은 상급 도적 프라훈께서 전령을 통해 전달한 것입니다. 시간이 날 때 한번 도장을 읽고 그분을 찾아가 보십시오. 프라훈께서 하실 말씀이 있는 것 같습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3119] = {title = "성스러운 도장", objective = "성스러운 도장을 읽어보고 알드랏실에 있는 샨다와 대화하십시오.", description = "이 도장은 상급 사제 샨다께서 전령을 통해 전달한 것입니다. 시간이 날 때 한번 도장을 읽고 그분을 찾아가 보십시오. 샨다께서 하실 말씀이 있는 것 같습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3120] = {title = "푸른 도장", objective = "푸른 도장을 읽어보고 그늘 협곡, 알드랏실에 있는 마르단트 스트롱오크와 대화하십시오.", description = "이 도장은 상급 드루이드 마르단트께서 전령을 통해 전달하신 것입니다. 시간이 날 때 도장을 읽고 그분을 한번 찾아가 보십시오. 마르단트께서 하실 말씀이 있는 것 같습니다.", progress = "아, 젊은 <class> 친구... 어서 수련을 받고 싶은 모양이군. 좋아.\n\n혹시 벌써 에메랄드의 꿈에서 오랜 시간을 보내고 오는 길은 아니오? 하긴 그대는 아직 그럴 단계가 아닐지도 모르겠군. 곧 때가 되겠지.\n\n하지만 그때까지는 다른 문제들부터 얘기하기로 하지.", completion = "지금부터 내가 그대의 스승이자 안내자가 될 거요. 영혼들과 이야기하는 방법을 비롯한 에메랄드의 꿈에 관련된 비밀들을 가르치는 것이 내 임무지.\n\n더욱 많이 배우고 강해지면 에메랄드의 꿈에 대해 어렴풋이나마 깨닫게 될 날이 올 거요. 그런 경지에 이르기 전에는 언제든지 날 찾아와 배우시오. 우리 &lt;class&gt;의 방식을 아는 데까지 가르쳐줄 테니...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3121] = {title = "이상한 부탁", objective = "오그리마에 있는 네루 파이어블레이드에게 구겨진 가면을 가져가야 합니다.", description = "오그리마에 있는 네루 파이어블레이드가 내가 이곳에서 일을 시작하기 위해 필요한 물건을 가지고 있다네! 그 친구가 물약을 하나 만들었는데 그걸로 내... 그러니까 그게... 어디에 필요한지는 나중에 알게 될 걸세.\n\n지금 당장 오그리마로 떠나게. 자, 내가 약초와 맞바꾸기로 약속했던 구겨진 가면을 가져가게. 비록 좀 구겨졌지만 정말 드워프 가면 같아서 그 친구도 놀랄걸쎄. 이걸 받아든 네루의 표정이 궁금하군.\n\n어둠의 틈으로 가면 네루를 찾을 수 있을 걸세.", progress = "무슨 일인가?", completion = "우제리가 이걸 보내기를 기다리고 있었지...\n\n그 친구의... 그러니까... 그의 실험을 위해 내가 준비한 약초 혼합물을 주겠네...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3122] = {title = "의술사 우제리에게 돌아가기", objective = "페랄라스에 있는 의술사 우제리에게 네루의 약초 주머니를 가져가야 합니다.", description = "약초 여기 있네. 이걸 의술사 우제리에게 가져가게.\n\n내가 보내준 가면에 만족해 한다는 것도 전해 주시기 바라네.", progress = "네루와 얘기해 봤나?", completion = "뮤세크 단지를 만드는 데 바로 이게 필요한 거라네. 내 최신 주문이 실제로 내가 기대해 온 것만큼 강력한지 곧 보게 되겠군.\n\n잠시만 기다리게. 의식을 행하고 약초를 써야 하니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3123] = {title = "단지 실험", objective = "동부 내륙지로 가서 올빼미야수를 찾아 10마리를 처치하고 뮤세크 단지를 사용해 죽은 올빼미야수를 갈무리해서 담아와야 합니다.\n\n페랄라스에 있는 의술사 우제리에게 올빼미야수 뮤세크 10개와 올빼미야수 뮤세크 단지를 가져가야 합니다.", description = "이건 내가 행한 의식과 자네의 능력 모두에 대한 시험이 될 걸세. 이 단지를 받게나. 이게 있으면 생물을 갈무리한 다음 이 안에 담아 잡을 수 있지.\n\n동부 내륙지로 가면 한때 나이트 엘프의 여신, 엘룬의 애완 동물이었던 올빼미야수라는 생물을 찾게나. 이 포악하고, 원시적이며, 야만스러운 올빼미야수들이 자네의 목표라네. 열 마리를 처치하고 그들의 영혼이 빠져나가기 전에 뮤세크 단지를 사용해서 갈무리해서 담아 오게나.", progress = "올빼미야수는 잡았나?\n\n자네가 성공한다면 우린 페랄라스 생물들의 뮤세크를 갈무리해서 담아올 준비가 되는 거라네.", completion = "극도로 잔인한 죽음을 맞은 생물의 경우 그 뮤세크가 몸에서 빠져나와 복수를 꾀할 수도 있다네. 하지만 자네가 한 것처럼 생물을 갈무리하면 뮤세크가 빠져나가는 것을 막을 수 있지. 이제 우리가 원하는 대로 얼마든지 단지를 쓸 수 있겠군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3124] = {title = "히포그리프 뮤세크", objective = "종에 상관없이 공작날개 히포그리프 10마리를 처치한 다음 뮤세크 단지를 사용해 갈무리해서 담아와야 합니다.", description = "자네는 신뢰할 만한데다가 뮤세크 단지를 쓰는 솜씨도 아주 그만이니 이제 또 다른 생물을 좀 잡아 줬으면 하네.\n\n오랜 세월 동안 나이트 엘프의 충실한 벗이 되어 준 히포그리프의 영혼은 충성스럽고도 굳건하지.\n\n자네의 임무는 공작날개 히포그리프를 10마리 처치해서 재빨리 단지에 그들을 잡아 갈무리해서 담아오는 것이네. 그렇게 해야 뮤세크가 보존될 수 있으니까 말이야. 히포그리프는 여기서 남쪽에 있는 높은벌에서 찾을 수 있다네.", progress = "히포그리프들은 잡았는가?", completion = "동물을 죽인 후에 뮤세크가 빠져나가도록 내버려두면 그 뮤세크는 더 큰 생물 형태를 취하게 된다네. 그렇게 되면 우리는 그 뮤세크의 복수로부터 결코 안전하지 못할 걸세.\n\n내가 자네에게 위험한 일을 맡겼던 것이지. 이번에도 역시 잘 완수해 주었군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3125] = {title = "요정용 뮤세크", objective = "화살요정용이나 요정용 8마리를 처치하여 뮤세크 단지를 사용해 죽은 요정용을 갈무리해서 담아와야 합니다.", description = "이번에는 보기에는 아주 나약해 보여도 아주 강한 영혼을 지니고 있는 생물을 잡아야 하네. 내가 말하는 요정용은 나이트 엘프의 동지라네. 녀석을 한 마리 잡아서 호드도 그 영혼의 힘으로부터 이익을 얻어야만 하네.\n\n자, 뮤세크 단지 여기 있네. 화살요정용이나 요정용을 8마리 처치해서 그들의 뮤세크를 손에 넣게. 요정용들은 여기서 서쪽으로 가면 찾을 수 있다네.", progress = "요정용들의 뮤세크를 잡아 왔나?", completion = "고맙네. 이제 호드도 요정용의 영적인 힘을 사용할 수 있게 되었군.\n\n자네가 한 가지 일을 더 해줬으면 좋겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3126] = {title = "나무정령 뮤세크", objective = "떠도는 숲정령 3마리를 처치하여 뮤세크 단지를 사용해 죽은 숲정령을 갈무리해서 담아와야 합니다.", description = "우리의 다음 목표는 숲을 어슬렁거리는 떠도는 숲정령일세. 나이트 엘프들은 호드에 맞서기 위해 나무정령들을 동지로 받아들였지. 나무정령들이 움직이는 속도는 느릴지 몰라도 수호자로서의 역할을 훌륭히 해낸다는 것은 부인할 수가 없는 사실일세. 곧 이 힘을 우리가 사용할 수 있게 될 것이야.\n\n떠도는 숲정령을 찾아 3마리를 죽이고 뮤세크 단지로 갈무리해서 담아 오게나.", progress = "떠도는 숲정령들은 잡아왔는가?", completion = "고맙네. 이제 우리 뮤세크 수집이 거의 끝나 가는군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3127] = {title = "산악거인 뮤세크", objective = "평지거인이나 절벽거인 7마리를 처치하여 뮤세크 단지를 이용해 죽은 산악거인을 갈무리해서 담아와야 합니다.", description = "마지막으로 자네에게 부탁할 일은 북서쪽으로 가서 마지막 적을 찾아내는 것일세.\n\n산악거인들은 불타는 군단이 이 세계에 나타났을 때 나이트 엘프 녀석들을 돕기 위해 산을 떠나 내려왔지. 자네가 그들의 암석투성이인 땅을 돌아다니다가 땅이 흔들리기 시작하는 걸 보면 거대한 덩치의 산악거인을 알아볼 수 있을 걸세.\n\n그 거대한 덩치의 힘을 손에 넣고 싶다네. 산악거인 7마리를 죽이고 뮤세크 단지를 사용해 그들의 강력한 뮤세크를 담아 오게나.", progress = "산악거인들은 잡았나?", completion = "지금 우리가 갖고 있는 것들의 가능성을 상상해 보게. 자네가 모아 온 재료들을 사용하면 내가 원하는 어떤 것에든지 이 생물들의 뮤세크를 영원히 가둘 수 있게 될 거야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3128] = {title = "천연 재료", objective = "모자케 야영지에 있는 의술사 우제리에게 쪼개진 통나무 2개, 보석박힌 광석 6개, 질긴 힘줄 20개, 그리고 금속 파편 40개를 가져가야 합니다.", description = "내가 하던 일을 마치려면 특정 재료가 필요하다네... 내가 자네에게 맡길 다른 일들과 함께해도 좋아.\n\n페랄라스의 나무정령에게서 쪼개진 통나무를 하나 가져와야 하고, 서쪽에 있는 산악거인과 요정용에게서 보석박힌 광석도 가져와야 하네. 그리고 동부 내륙지의 올빼미야수나 페랄라스의 히포그리프에게서 질긴 힘줄도 구해다 주게. 마지막으로, 내가 언급한 이 생물들 중 누구에게서나 얻을 수 있는 금속 파편을 많이 가져오게.", progress = "필요한 재료는 다 모았나?", completion = "좋았어! 이 재료들과 뮤세크를 결합하면 우리가 원하던 결과를 얻을 수 있을 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3129] = {title = "영혼의 무기", objective = "의술사 우제리가 무기를 준비하는 동안 잠시 기다려야 합니다.", description = "무기에 뮤세크를 불어넣는 것은 아주 까다로운 과정이지. 이제 필요한 재료도 다 있고 자네가 갈무리해 온 여러 생물들의 뮤세크도 있으니 의식을 시작할 수 있네. 곧 돌아올 테니 잠시 기다리게나.", progress = nil, completion = "약속한 대로, 원하는 걸 골라 갖게. 자네가 잡아온 생물들의 뮤세크가 이 무기들의 힘에 영원히 봉인되어 있다네.\n\n이제 그 힘을 자네 마음대로 사용할 수 있을 것이야. 잘 쓰도록 하게.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n히포그리프의 기세요정용의 정기나무정령의 힘산악거인의 결의\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3130] = {title = "증오의갈기일족과의 전투", objective = "페더문 요새에 있는 라트로니쿠스 문스피어에게 보고해야 합니다.", description = "이제 그대를 내 부관, 라트로니쿠스에게 안내하도록 하겠습니다. 그는 나가 군대의 동태를 철저히 감시하는 임무를 수행중에 있답니다. 나는 여기서 나가에 대한 총체적인 상황을 평가하고 있도록 하지요. 전군을 동원해서 녀석들을 치고 싶은 마음이야 굴뚝같지만 요새를 비워 두고 호드나 그보다 더한 적들이 공격할 수 있는 기회를 주는 것은 최선의 방법이 아니니까요.\n\n아무튼, 라트로니쿠스가 그대를 기다리고 있습니다. 지금까지 잘해주었으니 앞으로도 계속 잘해주시기 바랍니다. 자, 이만 가보도록 하세요!", progress = nil, completion = "아주 잘 됐습니다. 나는 \"하면 된다\"라는 생각을 가진 자의 자세를 높이 평가합니다. \n\n페더문 장군께서는 내게 나가 문제를 직접적인 방법으로 처리하라고 명하셨습니다. 내 계획은 첫째, 녀석들의 수와 명령 체계를 약화시키는 것, 둘째, 녀석들이 폐허에서 무슨 음모를 꾸미고 있는지 알아내는 것입니다. 그대의 도움으로 요새의 전체적인 안전을 해치지 않고도 나가 세력에 맞설 수 있게 될 것입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3141] = {title = "로라무스", objective = "로라무스 탈리뻬데스의 이야기를 들으십시오.", description = "그러니까 악마들과 싸우기로 결심을 굳혔단 말이지? 그럼 내 얘기를 잘 듣는 게 좋을 걸세.", progress = nil, completion = "그럼... 그렇게 하도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3161] = {title = "가즈리디안", objective = "타나리스에 있는 마본 리벳시커가 가즈리디안 장신구 30개를 모아 달라고 부탁했습니다.", description = "나는 과학자이지만 보물 사냥꾼이기도 하지!\n\n오래전 이 땅을 점령했던 트롤들은 그들이 섬기던 히드라 신, 가즈릴라의 모양을 본 따 많은 장신구를 만들었소. 그 장신구는 그 신의 이름을 딴 \"가즈리디안\"이라는 재료로 만들어졌지.\n\n내가 직접 찾은 게 좀 있긴 하지만 더 모아서 연구를 해봤으면 하오. 당신이 좀 찾아다 주지 않겠소?\n\n가즈리디안을 쉽게 찾도록 탐지기까지 개발해 놓았소! 그냥 걸치기만 하면 곧바로 탐색을 할 수 있지!", progress = "무슨 문제라도 있소?\n\n가즈리디안은 타나리스 어디서나 찾을 수 있소. 눈 크게 뜨고 한번 찾아보시오!", completion = "옳지. 이 정도면 내 연구에 딱 알맞겠군. 도와줘서 정말 고맙소.\n\n아, 지금 머리에 쓰고 있는 내 탐지기는 돌려주시겠소?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n측량사의 튜닉지식의 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3181] = {title = "야수의 뿔", objective = "산악경비대 페블비티에게 마르골의 거대한 뿔을 가져가야 합니다.", description = "이 거대한 뿔에는 긁힌 자국과 깨진 곳이 수도 없이 많으며 거친 표면에 이상한 금속이 박혀 있습니다.\n\n더 자세히 살펴보니 이 금속은 실제로 도끼 날이 부러져 박힌 것임을 알 수 있습니다. 금속 위에는 다음과 같은 글귀가 새겨져 있습니다.\n\n\"산악경비대 페블비티 소유\"\n\n부러진 도끼 날을 빼려고 하자 날이 산산조각이 납니다.\n\n아뿔싸!", progress = "안 돼요, 문을 열지 않겠어요.", completion = "거기 뭘 갖고 있는 것이죠? 가짜가 분명해!\n\n내가 마르골과 맞서 봐서 아는데 마르골의 뿔은 당신이 들고 있는 것보다 적어도 여덟 배는 더 크단 말이에요. 보나마나 불모의 땅의 천둥뿔도마뱀에게서 얻은 거겠지. 이 페블비티의 눈을 속일 수는 없어요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3182] = {title = "무훈의 증서", objective = "아이언포지에 있는 도서관장 소리우스에게 마르골의 거대한 뿔을 가져가야 합니다.", description = "그런 꾸며낸 얘기를 나보고 믿으라는 건가요? 그 뿔이 진짜라면 표면에 부러진 내 도끼 날이 아직도 박혀 있었을 텐데요.\n\n이봐요, 잘 들으세요. 그런 너무 뻔한 가짜는 아이언포지에 있는 도서관장 소리우스에게나 가져가세요. 그가 당신 얘기가 정말 사실이라고 판단한다면 무훈의 증서를 받게 될 겁니다. 그 증거물을 가지고 내게 돌아오면 이글거리는 협곡으로 통하는 열쇠를 주도록 하죠.\n\n어서 가 보세요!", progress = "안녕하시오. 우리 박물관을 한번 둘러보지 않으시겠소?", completion = "이건 뭐요?\n\n맙소사! 말도 안 돼! 이게 뭔지 알기나 하시오? 이건 난폭한 마르골의 뿔이란 말이오! 이글거리는 협곡에 발을 들여놓는 모든 고고학자들의 천적, 마르골 말이외다.\n\n이걸 내가 가져도 되겠소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3201] = {title = "이글거리는 협곡의 열쇠", objective = "산악경비대 페블비티에게 무훈의 증서를 가져가야 합니다.", description = "페블비티가 이 뿔이 진품인지 의심했다니 믿어지지 않는군. 우리끼리만 하는 얘기지만, 페블비티가 질투하고 있는 것 같소이다. 내가 알기로 페블비티는 그 야수를 자기가 직접 해치우고 싶어했었소. '사건' 같은 것도 있었고 해서 말이지.\n\n그래, 무훈의 증거가 필요하다고 했소? 우리 박물관에 큰 기여를 했는데 그 정도야 문제없지.\n\n<큰 문서를 작성하기 시작하는 도서관장 도리우스.>\n\n여기 있소! 이걸 가지고 페블비티에게 돌아가시오.", progress = "믿어지지 않는군요.", completion = "어떻게 당신처럼 허약한 자가 마르골을 이겨냈는지는 모르겠지만 약속은 약속이니 열쇠를 주도록 하죠.\n\n앞으로 무슨 일이 생기든 그건 당신 책임이에요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n이글거리는 협곡 열쇠"},
[3221] = {title = "렌퍼럴과 대화", objective = "공동묘지에 있는 연금술사 렌퍼럴과 대화해야 합니다.", description = "자네가 우리 죽음의추적자들을 도우러 떠난 사이에 렌퍼럴이 자네를 찾았다네. 자세한 얘기는 하지 않았지만 자네가 준 늑대 심장에 대해서 얘기를 나누고 싶어하더군. 가서 그를 만나보도록 하게.", progress = nil, completion = "아, 잘 왔네. 이전에 자네가 나에게 가져다준 늑대 심장에 대해 우리가 주목해야 할 것이 있어서 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3261] = {title = "조른 스카이시어", objective = "타우라조 야영지에 있는 조른 스카이시어와 대화하십시오.", description = "이제 나와는 작별이군. 더 이상 가르칠 게 없군. 남쪽에 있는 타우라조 야영지로 가서 조른 스카이시어와 얘기를 나눠보게. 앞으로 어떻게 해야 할지 알려줄 걸세.", progress = nil, completion = "어서 오게, 젊은 &lt;race&gt;. 앞으로 있을 전투를 위해 훈련을 받으러 온 게군.\n\n아주 좋아. 시작해 보세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3281] = {title = "도둑맞은 은화", objective = "크로스로드에 있는 가즈록에게 도둑맞은 은화를 가져가야 합니다.", description = "랩터들을 처치했다니 마음이 조금 놓이는군. 하지만 도둑맞은 은화도 반드시 되찾아야 하오! 톱니항 남쪽에 거대한 랩터 소굴들이 여럿 있다는 보고가 들어왔소. 랩터 서식지라는 데 아마도 랩터들이 훔친 은화를 그곳으로 가지고 갔을 거요.\n\n이 랩터 소굴로 쳐들어가서 도둑맞은 은화를 찾아보시오. 은화를 찾거든 내게 다시 돌아오시오.", progress = "은화는 찾아 왔소?", completion = "아하! 랩터 녀석들이 정말로 자신들의 소굴에 은화를 숨겨놓았었군! 그런 짐승들조차 은화를 가지고 싶어한다는 게 믿어지지가 않는군. 어쩌면 녀석들의 지능이 우리가 생각하는 것보다 훨씬 높다는 이야기가 사실일 지도 모르겠소.\n\n어쨌든 고맙구려. 이건 우리를 도와준 대가요. 크로스로드 경비병들이 다음달 봉급을 받을 수 있는 건 모두 당신 덕분이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n떠돌이 장화개척자의 다리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3301] = {title = "무라 룬토템", objective = "공동묘지에 있는 무라 룬토템과 대화하십시오.", description = "내 아내, 무라 룬토템은 우리의 동맹인 언데드를 돕기 위해 은빛소나무 숲으로 갔다네. 아내는 병들어 죽어가는 은빛소나무 숲을 되살리는 데 도움을 주고자 했지. 여기 불모의 땅에만 사는 생명체를 가져가면 무라가 은빛소나무 숲에서 하고 있는 일에 도움이 될 게야.\n\n자네가 모아온 등껍질의 견본을 은빛소나무 숲에 있는 무라에게 가져다주게. 아마 공동묘지에 있을 걸세. 등껍질을 연구해서 죽어가는 숲을 살리는 데 필요한 것을 알아낼 수 있을 거야.", progress = "당신에게서 불모의 땅 냄새가 나는군요. 아주 먼 길을 오셨네요.", completion = "아, 이 등껍질은...? 마치 안에서 생명이 고동치는 듯 빛을 발하고 있군요. 놀라워요! 더 자세히 조사해 봐야겠어요.\n\n고마워요. 운만 따라 준다면 이 껍질에서 병들어 가는 은빛소나무 숲을 치유하는데 도움이 될 만한 비밀을 캐낼 수 있겠어요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n열매씨앗 허리띠열매씨앗 망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3321] = {title = "잃어버린 물건", objective = "트렌튼이 일을 마칠 동안 기다리십시오.", description = "자네는 대장조합을 위해 많은 일을 해주었네. 보통 사람이 그만큼 하려고 했다면 벌써 포기하고 돌아갔을 걸세. 나도, 그리고 갈반도, 자네가 우리 대장조합의 일원이 될 자격이 있다고 생각한다네.\n\n그래서 조그만 상이라도 주어야겠어. 뭐 그리 대단한 것은 아니고 장신구라네. 그 장신구의 특성은 자네도 익히 알고 있을 걸세. 애초에 이것 때문에 여기를 찾아온 것이 아니었는가?", progress = nil, completion = "당당히 일어나시오. 미스릴 대장조합의 자랑스러운 대장장이, &lt;name&gt;|1이여;여;.", rewards = "다음과 같은 것들을 받습니다:\n\n빛나는 미스릴 배지"},
[3341] = {title = "암네나르 처치", objective = "앤드류 브로넬이 혹한의 암네나르를 처치하고 혹한의 해골을 가져다 달라고 부탁했습니다.", description = "불모의 땅에는 가시덩굴 구릉이라고 불리는 끔찍한 덩굴 지대가 있소. 그곳을 처음 조사했을 때는 그다지 큰 위협이랄 것이 없었는데, 최근에 조사한 바로는 훨씬 심각한 조짐이 보이고 있소...\n\n가시덩굴 구릉에 사는 가시멧돼지들이 스컬지와 동맹을 맺었소. 혹한의 암네나르라는 리치가 거대한 의식을 이용해 가시멧돼지들의 모든 행동을 지배하고 있는 것이오.\n\n암네나르는 넬쥴과 텔레파시로 직접 연결되어 있는데, 이 연결을 끊어놓아야만 하오. 혹한의 암네나르를 끝장내 주시오.", progress = "이번 일은 정말 중요하오. 스컬지 녀석들의 세력이 확장되는 것을 반드시 막아야만 하오.", completion = "리치의 충성은 확고부동하오. 그러한 충성은 파괴를 가져올 뿐이라는 것을 확실히 가르쳐줬을 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n정복자의 검적열의 부적"},
[3361] = {title = "망명자의 곤경", objective = "앤빌마에 있는 펠릭스 윈들볼트에게 잃어버린 펠릭스의 상자, 펠릭스의 궤짝, 펠릭스의 나사통을 찾아줘야 합니다.", description = "우린 놈리건에서 트로그들을 몰아내는데는 성공했지만 그 때문에 더 큰 일이 벌어지고 말았소! 이제 우리 고향은 방사능으로 완전히 오염되어 버렸고, 우리 노움들은 던 모로 곳곳에 뿔뿔이 흩어지게 되었다오.\n\n서둘러 방사능을 피해 도망쳐 나오다가 그만 내 소중한 소지품과 연장을 몽땅 잃어버렸소. 트롤들이 내 소지품을 가져갔소. 그 녀석들이 내 궤짝, 상자, 그리고 나사통을 훔쳐갔단 말이오. 분명히 앤빌마 남서쪽 야영지로 가져갔을 거요.\n\n난 좀 겁이 나서 그러는데 내 물건들을 좀 찾아다줄 수 있겠소?", progress = "정말 이 마을은 깔끔한 내겐 어울리지 않는다니까... 여기는 더럽고 냄새 나는 놈들이 침략해 우글우글거리던 시절의 놈리건이랑 거의 비슷한 수준이라오!\n\n<name>, 내 물건들을 찾아 온 거요? 아직까지 그 무식한 트롤 녀석들의 손에 있다면 성하지는 못할 텐데...", completion = "만세! 찾았군! 당신은 정말 내 구세주요. 자, 후하게 주지는 못하지만 수고해 준 대가요! 고맙소이다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3362] = {title = "덤불나무 골짜기", objective = "가젯잔에 있는 트란렉이 옹이진 덤불나무괴물 8마리와 억센뿌리 덤불나무괴물 8마리를 처치해달라고 부탁했습니다.", description = "덤불나무 골짜기에 가본 적 있나요? 그곳은 굉장히 위험한 곳이에요.\n\n그곳에는 괴상한 짐승들이 있어서 잠시도 마음을 놓을 수가 없답니다! 이름이... 옹이진 덤불나무괴물과 억센뿌리 덤불나무괴물이었던 거 같아요...\n\n어쨌든, 그 골짜기로 들어가고 싶은데 덤불나무괴물들이 그렇게 진을 치고 있으니... 바로 이 때문에 당신의 도움이 필요한 거예요. 녀석들을 좀 처치해주면 제가 다시 돌아가기가 훨씬 수월할 거예요. 어때요? 도와주시겠어요?", progress = nil, completion = "그렇게나 큰가요? 계획을 다시 짜야 할지도 모르겠군요...\n\n하지만 당신은 할 일을 제대로 했으니 약속한 걸 드리죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3363] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[3364] = {title = "뜨거운 새벽주 배달", objective = "앤빌마의 두르난 퍼커터에게 뜨거운 새벽주를 전해줘야 합니다. 새벽주는 5분이 지나면 식어버리니 그전에 가져가야 합니다.", description = "여보시오. 앤빌마에 있는 두르난 퍼커터가 주문한 이 맛있는 뜨거운 새벽주를 갖다줘야 하는데 지금에야 생각났지 뭐요! 나는 그렐린이 부탁한 술을 먼저 가져다줘야 하는데다 앤빌마까지 배달을 가면, 새벽주가 식어버려서 항상 불평을 듣고는 했소.\n\n당신은 나보다 빨라 보이는데, 이 뜨거운 새벽주를 두르난에게 갖다주겠소? 새벽주는 5분 동안만 뜨거운 상태가 유지되니 빨리 가져다 줘야 하오. 두르난은 '차가운' 새벽주를 주문한 게 아니니까. 앤빌마는 저 너머 북동쪽 첩첩산중 안에 있는 마을이오.\n\n그럼 부탁하겠소, <name>. 그리고, 빈 잔을 찾아오는 것도 잊지 마시오!", progress = "내가 바로 두르난 퍼커터가 맞는데, 뭘 가지고 온 거요?", completion = "그래, 뜨겁군. 이 정도면 딱 맛있겠는 걸. 난 잠시 이 뜨거운 새벽주 맛 좀 보겠소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3365] = {title = "빈 머그잔 가져가기", objective = "노리 프라이드드리프트에게 노리의 머그잔을 가져가야 합니다.", description = "어, 좋다! 이렇게 귀신이라도 얼어죽을 만한 추운 겨울날에는 소주... 아니, 이 뜨거운 새벽주만한 게 없지. 덕분에 잘 마셨소이다.\n\n<name>, 수고스럽겠지만 여기 이 빈 술잔을 노리에게 되돌려주지 않겠소?", progress = "뜨거운 새벽주를 두르난에게 때맞춰 배달해 주었소? 내 잔도 챙겨왔고?", completion = "정말 잘했소! 배달을 자청했다가 빈 술잔을 챙겨오는 간단한 일조차 잊어버리는 자들이 얼마나 많았는지 알면 놀랄 거요. 술잔이 하늘에서 뚝 떨어지는 것도 아닌데 말이오.\n\n여기, 많진 않지만 수고한 대가로 일당을 드리겠소. 추운데 다녀 오느라 수고 많았소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3366] = {title = "빛나는 조각", objective = "톱니항으로 가서 악몽의 조각에 숨겨진 의미를 밝혀내야 합니다.", description = "이 조각은 밝은 녹색을 띠고 있습니다. 겉은 단단해 보이지만 그 안에는 연기 같은 것이 소용돌이치고 있습니다. 수정 안의 연기는 눈길을 끌며 뭔가 굉장히 불길한 예감이 듭니다.\n\n혹시 이 이상한 조각에 대한 얘기를 해줄 이가 있는지 톱니항에서 찾아보는 게 좋을 것 같습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3367] = {title = "선타라 비석", objective = "도리우스가 아이언포지로 돌아가는 것을 도와야 합니다.", description = "<신음하는 도리우스>\n\n난... 깊은 상처를 입었소, <race> 친구. 현...현기증이 나는군... 세상이 빙글빙글 돌아... 속에서 피가...\n\n아이언포지로 돌아가야만 하오. 날 좀 도와 주시오.", progress = nil, completion = "이 편지는 도리우스가 저격 받을 때 떨어뜨린 것입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3368] = {title = "선타라 비석", objective = "아이언포지의 탐험가의 전당에 있는 소리우스에게 그을린 편지를 가져가야 합니다.", description = "아우야,\n\n네가 이 편지를 읽고 있다면 나는 이미 이승을 뜬 것이란다. 이 편지가 어떤 경로로 너한테 전달되었는지는 모르겠구나. 하지만 이 편지를 네게 가져다준 사람에게 감사를 표하고 합당한 보상을 해주길 바란다.\n\n선타라 비석 말인데, 그 돌은 정말 존재하며 검은무쇠단 드워프들이 가지고 있단다. 녀석들의 두목인 검은 라소릭이 선타라 비석의 마력을 이용해 내 발굴단을 노예로 만들고는 용광로로 끌고 가 버렸단다. 그들은 정신이 홀린 채 흑요암이라는 것을 완성하기 위해 밤낮없이 일하고 있다.\n\n그들을 도와 다오, 아우야. 내가 남기는 마지막 부탁이다.\n\n- 도리우스", progress = "<흐느끼는 소리우스>", completion = "&lt;눈물을 닦는 소리우스&gt;\n\n내 반드시 형의 소원을 이루어 주겠어. 맹세하지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3369] = {title = "악몽", objective = "장로의 봉우리에 있는 하뮬 룬토템에게 악몽의 조각을 가져가야 합니다.", description = "이 조각에는 엄청난 비밀이 숨겨져 있어요. 이건 바로 에메랄드의 꿈을 이루는 순수한 정수죠. 하지만 내가 이 조각에서 본 것은 꿈이 아니로군요. 이런 환영을 악몽이라고 하지요.\n\n당신을 놀라게 할 생각은 없었어요. 아무래도 가능한 빨리 이 조각을 현명한 드루이드에게 전해주는 것이 좋겠어요.\n\n장로의 봉우리에 있는 하뮬 룬토템을 찾아야 해요. 썬더 블러프로 가세요. 더 이상은 말해줄 사실이 없군요.", progress = "무슨 일로 왔는가?", completion = "팔라가 보냈다고? 그녀가 말하기 조차 꺼린다는 조각을 가져왔다고? 내가 좀 보세...\n\n&lt;조각 속을 들여다 본 후&gt;\n\n아, 이런...\n\n전해줘서 고맙네. 하지만 이것에 대해 언급하는 것은 좋지 않다는 걸 알아두게. 이런 문제는 자네와 상관없은 일이야.\n\n그냥 에메랄드의 꿈에서 일어나는 일은 우리 생각과는 다르다고만 해두지...\n\n어쩌면 훗날 자네를 다시 만나게 될지도 모르겠군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n탈바르 어깨보호대습지대 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3370] = {title = "악몽", objective = "다르나서스에 있는 마스렌길 베어워커에게 악몽의 조각을 가져가야 합니다.", description = "이 조각에는 엄청난 비밀이 숨겨져 있어요. 이것은 바로 에메랄드의 꿈을 이루는 순수한 정수죠. 하지만 내가 이 조각에서 보는 것은 꿈이 아니로군요. 이런 환영을 악몽이라고 하지요.\n\n아, 당신을 놀라게 할 생각은 없었습니다. 아무래도 가능한 빨리 이 조각을 현명한 드루이드에게 전해주는 것이 좋겠군요...\n\n세나리온 의회의 마스렌길 베어워커를 찾아야 해요. 다르나서스로 가세요. 더 이상은 말씀드릴 게 없군요.", progress = "무슨 일로 왔나요?", completion = "방금 팔라가 보냈다고 그랬습니까? 그럼 팔라가 말하기 조차 꺼린다는 그 조각을 좀 보여 주세요.\n\n&lt;조각을 들여다보는 마스렌길&gt;\n\n아... 이런, 그게...\n\n전해줘서 고맙습니다. 하지만 이런 것들에 대해 언급하는 것은 당신의 신상에 별로 좋지 않아요. 이러한 문제는 세나리온의 드루이드들이 해결할 문제예요.\n\n당신에게는 그냥 에메랄드의 꿈에서 일어나는 일들은 우리의 생각과 다르다고만 해두겠습니다.\n\n어쩌면 훗날 다시 만나게 될지도 모르겠군요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n탈바르 어깨보호대습지대 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3371] = {title = "드워프식 정의", objective = "이글거리는 협곡으로 돌아가서 도리우스의 발굴단 고고학자를 찾아야 합니다.", description = "내 가슴이 텅 비어 버렸소. 형을 잃었다는 사실을 쉽게 극복할 수 없을 것 같군. 반드시 형의 마지막 소원을 이루어 줘야겠소. 이 냉혈한 살인마들에게 정의의 처단을 내려야 하오.\n\n이글거리는 협곡으로 돌아가서 형의 마지막 소원을 들어주시오. 형의 발굴단을 자유롭게 해 주시오.", progress = nil, completion = "나... 나는 그냥 두고 다른 이들을 도와 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3372] = {title = "해방", objective = "이글거리는 협곡의 북서쪽에 있는 황혼의망치단 우상숭배자들이 보호하고 있는 불가사의한 유물을 찾아야 합니다.", description = "발굴단을 자유롭게 해 주세요. 그들의 몸이 쇠진해 버린 뒤에도 선타라의 마력이 강제로 임무를 완수하도록 하고 있습니다.\n\n선타라의 제단이 바로 그 열쇠입니다. 북서쪽으로 가세요. 채석장 위 언덕에... 황혼의망치단이 유물을 지키고 있습니다. 그 유물을 회수해 선타라의 제단 위에 올려놓으시기 바랍니다.\n\n<죽어 가는 듯 쓰러지는 고고학자>", progress = "제단이 비어 있습니다.", completion = "불가사의한 유물을 선타라의 제단 위에 올려 놓습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3373] = {title = "에라니쿠스의 정수", objective = "가라앉은 사원의 이 안식처에 있는 정수의 샘에 에라니쿠스의 정수를 놓아야 합니다.", description = "보석을 만지자 굵은 목소리가 마음속까지 울려 퍼집니다.\n\n\"필멸의 생명이여, 내 청을 들어다오. 나는 녹색용군단의 에라니쿠스라하며 이 저주받은 사원의 감시인이다. 내 임무는 두 번 다시 트롤이 그들의 흉측한 신을 이곳에 모시지 못하도록 하는 것이었는데 실패하고 말았다. 내 정수를 이 보석에 부여하니 꿈을 지배하는 나의 힘이 혼돈으로 뒤틀리는구나. 부탁이니 이 보석을 내 안식처에 있는 정수의 샘에 넣어주었으면 한다. 그곳의 마력이 내 영혼에서 악을 씻어내 내가 편히 쉴 수 있도록 해다오.\"", progress = "에라니쿠스가 말한 정수의 샘에 다가가자 그의 목소리가 다시 한번 울립니다.\n\n\"그래. 이 정수의 샘이 이 보석에 깃들어 있는 오염되지 않은 내 영혼을 회복시켜줄 것이다. 녹색용군단의 마력이 내 존재에서 타락과 오염을 씻어낼 수 있도록 샘에 그 보석을 담가 다오. 그렇게 해야만 내가 진정한 해방을 누릴 수 있고, 그렇게 해야만 용군단이 다시 아탈라이를 다스릴 수 있느니라.\"", completion = "보석을 정수의 샘에 담급니다.\n\n\"필멸의 생명이여, 고맙구나. 덕분에... 아냐. 이... 이럴 리가 없어! 안 돼! 저주받은 신의 타락이 녹색용군단 정수의 샘의 신성함까지 더럽히는구나! 제발, 안 돼. 내게서 정기가 찢겨 나가고 있어! 고통스럽구나!!! 끊없는 악몽이 나를 휘어잡고 있어...\"\n\n\"필멸의 생명이여, 간청하니 녹색용군단의 일원을 찾아 이를 멈추도록 해다오... 나를 도와다오... 그렇지 않으면 암흑에 갇혀... 영원히 고통받게 될 것이다... 제발 이 고통을... 멈추어...\"", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n속박된 에라니쿠스의 정수"},
[3374] = {title = "에라니쿠스의 정수", objective = "슬픔의 늪에 있는 이타리우스에게 이세라 용군단의 서약의 돌과 속박된 에라니쿠스의 정수를 가져가야 합니다. 이세라의 용군단을 도울 것인지 돕지 않을 것인지는 그곳에서 결정하게 됩니다.", description = "서약의 돌을 사용하자 이타리우스가 돌을 통해 마음속으로 말을 전합니다.\n\n\"이 서약의 돌에 담긴 임무를 받아들임으로써 그대는 나의 대의와 이세라 용군단의 대의를 받들어 에라니쿠스의 타락한 영혼을 구제하는데 동의하는 것이니라. 앞으로 그대와 나는 많은 희생을 치르게 될 것이니, 그 첫 번째는 에라니쿠스의 정신에 남아 있는 자유 의지를 구속해온 그 보석을 내게 넘기는 것이니라.\"\n\n\"이를 행하도록 하라. 그리하면 우리가 힘을 모아 구원받아야 할 영혼을 구원할 수 있으리니.\"", progress = "또다시 갈림길에 서게 되었구나. 또 다른 선택을 할 때가 왔느니라. 그대는 어느 쪽을 선택하겠는가?", completion = "선택을 했으니 이제 그 선택이 시작되노라. 지금까지 그대의 선택은 내가 올바르다고 생각하는 것들이었느니라. 앞으로 그대의 행동과 업적으로 이 올바른 선택이 계속 이어질지 결정될 것이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3375] = {title = "수정점의 유리병 다시 받기", objective = "아이언포지에 있는 탈바쉬 델 키젤에게 마나 물약과 석탄, 달콤한 과즙을 가져다주고 새로운 수정점의 유리병을 얻어야 합니다.", description = "음... 수정점의 유리병이 또 필요하단 말이오? 당신 농담하는 거지? 처음에 준 건 어떻게 된 거요?! 가뜩이나 할 일이 많은데, 그 유리병이 하늘에서 뚝 떨어지기라도 하는 줄 아시오?! 정말로 그랬으면 좋겠군. 지금은 더 이상 없으니까 말이외다!!\n\n다시 만들려면 마나 물약과 석탄, 달콤한 과즙이 필요하오. 왜 그런지 묻지 말고 그냥 내가 부탁한 물건들이나 가져다주시오. 그러면 유리병을 새로 하나 만들어주리다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n탈바쉬의 수정점 유리병"},
[3376] = {title = "족장 뾰족어금니 처치!", objective = "족장 뾰족어금니를 처치한 후 그 증거로 그의 머리카락을 붉은구름 고원에 있는 용사 윈드페더에게 가져가야 합니다.", description = "당신에 대한 얘기를 많이 들었습니다, 젊은 타우렌이여. 다른 이들은 실패했지만 어쩌면 당신이 우리를 도울 수 있을지도 모르겠군요.\n\n우리 타우렌은 이 땅에서 삶의 터전을 개척했지만 대가가 따랐습니다. 칼날가시 협곡의 뾰족털 가시멧돼지들이 계속된 전쟁은 우리 삶을 고통스럽게 하고 있습니다. 녀석들의 두목이라는 족장 뾰족어금니를 처치하는 임무를 맡기겠습니다!\n\n녀석은 동쪽에 있는 칼날가시 협곡 안에 뾰족털 가시멧돼지들의 임시 마을에서 찾을 수 있을 겁니다.", progress = "뾰족어금니를 처치하면 더는 우리를 괴롭히지 못할 겁니다. 내가 원하는 것은 녀석이 쓰러졌다는 증거입니다.\n\n우리 <race>은 사냥을 위해 삽니다. 우리를 사냥할 수 있을 정도로 영리한 상대를 좇는 것보다 더 위대한 사냥은 없습니다. 젊은 <race>이여, 이 임무를 완수하게 되면 내 말의 의미를 알게 될 겁니다.", completion = "오늘, 당신의 재빠른 행동으로 정의가 실현되었습니다. 당신의 업적은 우리 고향을 위협하려는 모든 자들에게 경고가 되게 하겠습니다.\n\n젊은 &lt;class&gt;|1이여;여;, 당신은 이 보상을 받을 만한 일을 했어요. 여기에 묵는 동안 이걸 쓰시기 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n채색한 사슬 다리보호구유목민의 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3377] = {title = "엘룬께 올리는 기도문", objective = "잠마엘이 하는 이야기를 들으십시오.", description = "날 도와 주지 않겠소? 내 얘기를 좀 들어 보시오.", progress = "얘기 도중에 방해하지 말아 주시오.", completion = "나는 우리에 갇힌 내 운명을 받아들였지만 그 기도문만큼은 꼭 찾아야 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3378] = {title = "엘룬께 올리는 기도문", objective = "엘룬께 올리는 기도문을 찾아 다르나서스에 있는 아스타리 스타시커에게 가져가야 합니다.", description = "날 도와 엘룬께 올리는 기도문을 찾아 주지 않겠소?\n\n내가 말했듯이, 기도문은 금으로 된 서판에 새겨져 있소. 우상숭배를 하는 이 황혼의망치단 불한당들 중 하나가 지니고 있는 게 틀림없소.\n\n내 기도문을 찾거든 다르나서스에 있는 아스타리 스타시커에게 가져가 주시오. 내가 이 세계에 수도 없이 악한 짓을 하고 난 후에 믿음을 회복했다는 사실은 중요치 않소. 하지만 내 기도문만큼은 반드시 전달해야 하오. 어짜피 사면 같은 건 기대하지도 않소이다.", progress = "달의 신전에는 무슨 일이십니까?", completion = "엘룬께서 오늘 밤 그대에게 미소를 지어 보이시는군요. 그대는 길 잃은 영혼을 그분께 다시 이끈 겁니다. 감사의 표시로 이걸 받아 주시기 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n카일라리 어깨보호구룬강철 완갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3379] = {title = "그림자매듭", objective = "이글거리는 협곡을 돌아다니는 그늘거미 밀렵꾼을 처치해야 합니다. 닐리스는 다섯 명 정도는 처치해야 한다고 생각하고 있습니다. 임무를 완수하면 이글거리는 협곡에 있는 닐리스에게 돌아가십시오.", description = "이글거리는 협곡에 사는 거미들은 귀하디 귀한 그늘 거미줄의 원천이랍니다. 아시다시피, 그늘 거미줄은 우리 같은 직업을 가진 사람들이 많이 찾는답니다.\n\n최근에 밀렵꾼 패거리들이 이 땅을 침략해서 자신들의 행동에 대한 장기적인 영향 같은 건 고려하지도 않고 마구잡이로 거미들을 해치고 있어요. 당신에게 맡길 첫 임무는 간단합니다. 녀석들을 찾아서... 끝장내 주세요.\n\n북쪽에서 그 침략자들을 찾아보도록 하세요. 지원이 필요하면 라제와 얘기해 보세요.", progress = nil, completion = "아주 잘했어요.\n\n이건 당신이 아직 한 번도 본 적 없는 그림자매듭일 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n그림자 팔보호구"},
[3380] = {title = "가라앉은 사원", objective = "타나리스에서 마본 리벳시커를 찾아야 합니다.", description = "이 세계에는 편히 쉬지 못하는 영혼들이 있다네. 아주 오래전부터 악에 속박되고 고립되어 오염된 영혼들이지. 전에 땅속 깊은 곳에 어떤 사원이 묻혀있다는 얘기를 들은 적이 있네. 지금까지 내가 보지 못한 강력한 존재들에 의해 추방되었다고 하더군.\n\n가라앉은 사원이라고 불리는 이곳에 대해 더 알고 싶으면 마본 리벳시커라는 고블린을 찾아가보게. 그 친구는 이 세계의 수많은 고대 유적지를 조사했지. 최근에는 톱니항에 있는 집을 떠나 타나리스의 트롤 유적지를 조사하러 갔다고 하니 그를 찾아가보게.", progress = nil, completion = "아, 가라앉은 사원 말이로군. 내가 이 두 눈으로 직접 봤죠. 한번 들어보겠소?\n\n모험을 좋아할 것 같은데, 당신의 흥미를 끌만한 걸 몇 가지 알고 있소...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3381] = {title = "사나스의 스승", objective = "사나스 림요의 주인과 대화하려면 아즈샤라에 있는 사나스 림요에게 온전한 히포그리프 깃털 2개를 가져가야 합니다.", description = "아이구, 이 사나스를 몸소 찾아 오시다니, 이렇게 황송할 때가! 직접 예까지 찾아와 주시니 영광입니다. 와 주셔서 정말로 감사합니다!\n\n설마 비꼬는 말을 칭찬으로 알아듣고 거만하게 구는 건 아니겠지? 한 가지만 분명히 해두지. 난 당신이 맘에 안 들어. 하지만 지금 우리가 얘기하는 건 우리 관계와는 상관없고 우리 대마법사님과 상관이 있지.\n\n내 화살에 쓸 히포그리프 깃털 두 개만 가져다주면 그분을 뵈러 갈 수 있게 해주지. 대마법사님께서 좀 쓸만한 모험가들을 보내달라고 하셔서 말이야.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n아즈샤라 탑으로 순간이동\n\n다음과 같은 것들을 받습니다:\n\n"},
[3382] = {title = "위험에 처한 선원", objective = "선장 바네사 벨티스와 그녀의 선원들, 그리고 지평선 정찰함의 승객들을 나가의 공격으로부터 보호해야 합니다. 적어도 선장 바네사 벨티스는 반드시 살아남아야 합니다.", description = "우리는 해안에서 정박할 만한 안전한 곳을 찾고 있었죠. 그런데 해가 떨어진 지 한 시간도 채 안 돼 그 괘씸한... 나가 녀석들이 우리를 공격했어요!\n\n녀석들이 뭘 가지러 온 것인지는 모르겠지만 찾지 못한 건 분명해요. 벌써 한번 되돌아 왔었거든요. 또 공격하러 올 경우를 대비해 계곡 입구에 정찰병 두 명을 배치해 뒀어요.\n\n하필 당신이 지금 같은 때에 나타난 건 안타까운 일이지만 목숨을 걸고 싸울 준비를 하시는 게 좋겠네요.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[3385] = {title = "암거래상단", objective = "대상 코빅과 그의 부하 딸깍이를 처치하고 그 시체에서 대상의 가방을 회수하여 닐리스에게 가져가야 합니다.", description = "자칭 암거래상단이라고 적당한 가격만 받으면 판매, 이주, 거래 등등 뭐든지 하는 학살 전문 상인 집단이 있습니다.\n\n더 심각한 건, 그들이 이 이글거리는 협곡에 사업 본부를 세웠다는 겁니다. 대상 코빅이 운영을 하면서 그 구역의 검은무쇠단 드워프들과 친밀한 관계를 맺고 있습니다.\n\n우리가 그들에게 본때를 보여 주고 녀석들의 지도부에 메시지를 전달해야 합니다. 대상 코빅과 그 부하 딸깍이를 해치우고 일을 마치면 대상의 가방을 가지고 돌아오세요.\n\n자, 어서 용광로로 출발하세요!", progress = "대상 코빅이 아직 살아 있나요?", completion = "이걸로 당신이 암거래상단에 결정타를 먹인 겁니다. 앞으로 녀석들의 지도부는 이글거리는 협곡에 함부로 졸개들을 보내지 못하겠죠.\n\n아, 그리고 이 대상의 가방은 내겐 쓸모가 없습니다. 당신이 이 안에 든 걸 가지도록 하세요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n그림자 허리띠코빅의 거래용 가방"},
[3402] = {title = "암거래상단", objective = "가젯잔에 있는 비즈클릭과 대화해야 합니다.", description = "당신이 직접 가젯잔에 있는 비즈클릭에게 코빅을 물리쳤다는 소식을 전해 주었으면 합니다. 비즈클릭이 코빅이 죽었다는 소식을 들으면 굉장히 기뻐하면서 분명 당신에게 크게 보상해 줄 겁니다.", progress = nil, completion = "코빅이 죽었다고?? 유후! 오늘은 참으로 기쁜 날이 아닐 수 없군! 그 불한당 녀석은 오랜 세월 동안 뒷거래를 하고 전 세계의 근면 성실한 상인들에게 사기를 쳐 온 악질 같은 녀석이지.\n\n오, 물론 이 공적에 대한 보상을 해 드려야지! 아주 괜찮은 보상을 말이야!", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 그림자매듭 복면"},
[3421] = {title = "귀환", objective = "지금 사나스의 야영지로 보내 드리겠습니다.\n\n녀석의 버르장머리 없는 태도는 신경 쓰실 것 없습니다. 저희 주인님을 제외하고는 누구한테든 그렇게 버릇없이 구니까요. 사나스도 언젠가는 철이 들겠지요.", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n아즈샤라 탑에서 순간이동"},
[3441] = {title = "성스러운 복수", objective = "벨라로크 윈드블레이드가 하는 이야기를 들으십시오.", description = "모험가여, 내 얘기를 좀 들어 보시오.", progress = "이야기 도중에 방해하지 말아 주시오... <race> 친구.", completion = "내 얘기는 충분히 들었소? 그럼 준비는 된 거요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3442] = {title = "완전무결한 불꽃", objective = "화염의 심장 4개와 골렘 기름 4개를 모아 벨라로크 윈드블레이드에게 가져가야 합니다.", description = "잘 결정했소.\n\n우린 가장 타격을 크게 입을 만한 곳인 네 개의 감시탑을 노려야 하오. 그 네 개의 탑을 불길에 휩싸이게 하면 녀석들이 응전을 할 준비가 되기 전에 우리가 공격을 펼칠 수 있소이다.\n\n그 탑들을 불태우려면 적당한 도구가 있어야 하는데 그 도구를 만들려면 몇 가지 재료가 필요하오.\n\n화염의 심장 네 개와 골렘 기름 네 개를 내게 가져오면 내가 완전무결한 불꽃으로 타오르는 횃불을 만들어 주지.\n\n먼저 이 땅에 사는 골렘과 정령들을 사냥하도록 하시오.", progress = "재료는 모아왔소?", completion = "수고했소. 이제 준비가 거의 다 됐군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3443] = {title = "횃불 자루 만들기", objective = "벨라로크 윈드블레이드에게 토륨 도금 단검 8개를 가져가야 합니다.", description = "완전무결한 불꽃을 만들려면 자루와 불꽃을 담을만한 테두리가 필요하오. 우선 적당한 자루를 찾아야 하오.\n\n용광로에 있는 검은무쇠단 감독관과 검은무쇠단 노예상인은 마법이 걸린 토륨으로 만든 무기를 사용하지. 토륨은 대단히 튼튼한 합금인데, 토륨 도금 단검 여덟 개를 가져오면 내가 녹여서 자루로 만들 수 있소.", progress = "여덟 개요. 여덟 개가 필요하오!", completion = "당신 아주 훌륭한 일꾼이로군. 혹시 직업을 바꿀 생각 해 본 적 없소? 형사라든가, 아니면 쓰레기 수집가라든지 말이야. 아, 아제로스 해변에서 금속 탐지 장치를 들고 잃어 버린 보물을 찾아다니는 바보 같은 노움 녀석들 중 하나를 알지. 암, 당신한테 적격이겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3444] = {title = "돌무리", objective = "톱니항에 있는 마본 리벳시커의 작업장에서 마본의 궤짝에 담긴 아탈라이 돌무리를 회수해야 합니다.", description = "난 가라앉은 사원의 기분 나쁜 방에 들어가 본 적이 있소. 그곳의 사악한 기운은 피부를 뚫고 들어오지. 이제는 바닥을 덮어버린 진흙을 헤치며 간신히 빠져나왔지만, 기억나는 것이라곤 뱀 석상들이 즐비한 커다란 원형 방에 들어갔다는 것뿐이오...\n\n그런데 최근에 바로 그 뱀 문양이 새겨진 동그란 돌을 찾았소. 난 그걸 포장해서 톱니항에 있는 내 작업장으로 부쳤는데, 그 돌을 가져오면 더 자세한 얘기를 들려줄 수 있을지 모르겠군.", progress = "톱니항은 여기서 그리 멀지 않으니 그렇게 오래 걸리지 않을 것이오.", completion = "맞아... 바로 이게 그 돌무리요.\n\n이제 기억이 나기 시작하는군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3445] = {title = "가라앉은 사원", objective = "타나리스에서 마본 리벳시커를 찾아야 합니다.", description = "전에 땅속 깊은 곳에 있는 어떤 장소에 대해 들은 적이 있어요. 지금까지 내가 보지 못했던 강력한 존재들에 의해 버려졌다고 해요.\n\n가라앉은 사원이라고 불리는 이곳에 대해 더 알고 싶으면 마본 리벳시커라는 고블린을 찾아가보세요. 나나 트로야스처럼 그 친구도 이 세계의 수많은 고대 유적지를 조사했답니다. 그 친구가 타나리스의 트롤 유적지를 조사하려고 톱니항의 집을 떠났다는 게 가장 최근에 들은 소식이에요.\n\n그 친구 소식이 끊어진 지 꽤 됐지만 찾을 수 있길 바랄게요.", progress = nil, completion = "아, 가라앉은 사원 말이로군. 내가 이 두 눈으로 직접 봤지. 한번 들어보겠소?\n\n당신은 모험을 좋아할 것 같은데, 흥미 있을 만한 걸 몇 가지 알고 있소...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3446] = {title = "심연의 늪", objective = "슬픔의 늪에 있는 가라앉은 사원에서 학카르 제단을 찾아야 합니다.", description = "사원 안에서 난 발코니가 여섯 개 있는 원형 방을 찾았소. 발코니마다 가장자리에 뱀 석상이 하나씩 있었지. 난 호기심에 그 중 하나를 밀어보았는데, 그게 함정이었던 것이오! 난 폭발로 떨어져서 죽을 뻔했소이다. 발코니 끄트머리에 쓰러진 채 아래를 내려다보니 방 바닥에 다른 석상이 있었소. 일종의 제단 같은 것이었는데, 이름이 학카르였던 것 같군.\n\n그 제단에 비밀이 숨겨져 있는 것 같으니 이 돌무리를 가라앉은 사원의 제단으로 가져가도록 하시오.", progress = "석상을 살펴보니 옆면에 움푹 들어간 곳이 있습니다. 마본이 준 돌의 크기랑 꼭 맞습니다...", completion = "돌무리를 움푹 들어간 자리에 집어넣자 딸각하는 소리가 나며 들어갑니다.\n\n이제 돌을 집어넣었으니 그 다음에는 무엇을 해야 할까요?\n\n이 제단을 좀 더 살펴보아야 할 것 같습니다...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3447] = {title = "돌무리의 비밀", objective = "가라앉은 사원으로 가서 원 모양으로 서 있는 석상들에 감춰진 비밀을 알아내야 합니다.", description = "자세히 기억이 나진 않지만 아는 대로 말해주겠소. 가라앉은 사원에 원 모양으로 서 있는 석상들은 위험하기는 하지만 더 큰 보물로 통하는 비밀을 간직하고 있소.\n\n중심 제단에서는 불을 켤 수 있었는데 이 불의 의미가 무엇인지 알아내면 그 방에 숨겨진 비밀도 알아낼 수 있을지 모르오.\n\n하지만 그 사원에는 엄청난 악이 도사리고 있으니 조심하도록 하시오. 아마도 귀중한 보물이 철통같은 보안 속에 숨겨져 있을 거야...", progress = nil, completion = "절반이 어둠에 묻힌 사원 안에서도 신상의 눈만큼은 밝게 빛나고 있습니다. 투명한 눈 뒤에 뭔가 반짝이는 것이 있습니다. 눈을 옆으로 밀어내고 손을 집어넣어 신상 안에 든 것을 거머쥡니다.\n\n아탈라이 보물은 이제 당신 것입니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n학카르의 단지"},
[3448] = {title = "티모르의 협조", objective = "아이언포지에 있는 티모르와 대화하십시오.", description = "최근에 난 한때 엘프들의 고향이라 불리던 아름다운 곳, 아즈샤라를 조사하는 임무를 맡게 되었네. 엘프들이 마법을 사용하던 때의 얘기지. 이제는 아름답다기보다는 위험한 곳이지만, 그러한 위험에도 굴하지 않고 우리는 과거에 대한 해답을 파헤쳐 나가야해.\n\n이런 일에 특히 관심이 많은 티모르라는 친구가 날 도와 주기로 했지.\n\n그는 이 도시의 신비의 전당 오른편에 있는 작은 집에 살고 있네.", progress = nil, completion = "아, 카르닉이 보냈단 말이오? 그 친구에게서 곧 소식이 오기로 되어 있었지. 난 아즈샤라에 대해서 아주 멋진 것들을 알아냈소이다... 모두 나이트 엘프의 수명이 엄청나게 길다는 것은 알아도 그들에게 일어난... 비극적인 사건들에 대해서는 잊고 있지. 비판을 하려는 게 아니라 단지 내가 그렇게 느꼈다는 거요.\n\n오래전, 마법의 힘과 지금은 잃어버린 지식으로 가득 찬 엘프 도시들이 있었소. 그런 걸 연구하는 입장이라 조사를 시작했는데, 내가 알아낸 것들은 굉장히 흥미진진한 것이었소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3449] = {title = "고대 룬", objective = "탁본 도구를 사용해 베스아마라 룬, 진야엘 룬, 마크리 룬, 그리고 샤엘하이 룬의 탁본을 만든 후, 아즈샤라의 남부 반도에서 조금 떨어진 작은 섬으로 가서 신호를 보내 조종사 시그스 퓨즈라이터가 가지러 오도록 하십시오.", description = "한때 일부 엘프들은 마법을 그들의 여신, 엘룬만큼이나 경외했던 적이 있었소. 그들 중 가장 강한 힘을 지닌 마법사들 중 일부는 룬을 만들고 마법의 규칙과 새로운 발견에 대한 통찰을 기록한 서판을 만들었소이다. 그들은 이 룬을 공공 장소에 배치해 모든 이들이 읽을 수 있도록 했었소.\n\n난 꼭 엘다라스 폐허에서 이 룬의 탁본을 떴으면 하오. 탁본을 만드는 데 쓸 도구는 나에게 있지만 룬을 찾는 건 당신 몫이오. 하지만 조심하시오. 엘다라스에 관심을 가지는 것은 탐험가 연맹만이 아니니까 말이오.", progress = "이런, 이런, 이런, 여기까지 무사히 온 걸 보니 반갑군. 티모르씨에게 배달할 탁본은 가져왔소?\n\n이곳이 위험하다고는 해도 해안에서는 별다른 일이 없었소이다. 아마 나가들이 물 밑에서 헤엄치고 있기 때문이겠지만, 그거야 내가 신경 쓸 일이 아니지... 나는 하늘을 정찰하니까 말이오.", completion = "이렇게 무사히 보게 돼서 다행이군. 당신에게 너무 힘든 일이 아니었다면 좋겠소이다.\n\n이 탁본들은 즉시 티모르씨에게 가져가겠소. 티모르가 이걸 보면 아주 기뻐할 거요.\n\n아, 그 신호탄은 버리시오... 어차피 더 이상 쓸모 없을 테니까. 나는 새 것이 있고 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3450] = {title = "간편한 배달 방법", objective = "아이언포지에 있는 시그스 퓨즈라이터와 대화하십시오.", description = "내 탑으로 탁본을 배달했으면 좋겠는데 당신이 그곳까지 갈 필요는 없소. 아즈샤라에서 항공편을 통해 가져오도록 하면 될 테니까 말이오.\n\n시그스 퓨즈라이터가 나한테 신세를 좀 진 게 있는데 해안 정찰을 맡게 되어 곧 그곳에 간다고 하더군. 떠나기 전에 그와 얘기를 나눠 보시오. 그가 신호탄을 줄 거요. 탁본을 다 만들거든 그 친구가 가라고 하는 곳으로 가서 신호를 한 다음 탁본을 건네주시오. 그 친구가 내 탑까지 무사히 배달해 줄 거요. 그는 군사 지구의 격납고에 있을 거요.", progress = nil, completion = "무슨 일로 오셨소? 지금은 긴 여정을 준비하느라 좀 바쁜데... 조종석에 깔아놓을 웬디고 갈기가 필요한데 전차 조종사들이 보통 여분을 가지고 다니기에 전차 조종사들을 좀 보러 온 것뿐이오.\n\n할 말이 간단한 내용이면 잠깐 짬을 낼 수 있소. 내 조수 중 하나가 갈기 여분을 얻으러 스틸그릴의 정비소로 갔으니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3451] = {title = "배달 신호", objective = "아이언포지에서 시그스 퓨즈라이터와 대화하고 그에게서 기본지급품 신호탄을 받아야 합니다.", description = "아, 그러니까 티모르씨가 보냈단 말이오? 그에게 신세를 좀 진 일이 있지. 그게 뭐냐고? 이런 약삭빠른 친구 같으니. 당연히 도와 줘야지. 그러니까 신호탄을 쏘고 탁본을 건네줄 곳이 있어야 한다는 것이군... 간단하지.\n\n아즈샤라의 남부 반도에서 조금 떨어진 곳에 작은 섬이 있소. 그곳에 착륙장을 만들어 뒀는데, 이 신호탄을 갖고 가서 쏘시오. 당신이 보낸 신호를 보고 내가 그거... 그러니까 그 친구가 원하는 그 물건을 가지러 갈 테니까.", progress = nil, completion = "자, 내 기본지급품 신호탄이오. 하나에 두 발만 장전되니까 한번 쏘고 나서는 좀 참고 기다리시오. 내가 바다 멀리 나가 있으면 가는 데 시간이 좀 걸릴 수도 있소. 신호를 보낸 다음 바다 쪽을 바라보며 기다리도록 하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n기본지급품 신호탄"},
[3452] = {title = "불꽃의 테두리", objective = "벨라로크 윈드블레이드에게 라그나로스의 상징 1개를 찾아 가져가야 합니다.", description = "횃불을 완성하는데 마지막으로 한 가지가 더 필요하오.\n\n북서쪽의 산으로 가면 황혼의망치단이 있는 대규모 야영지가 있소. 소문에 의하면, 자신들의 신에게 경의를 표하는 상징을 지니고 다닌다고 하더군. 거기엔 마법 테두리를 만들 수 있을 만큼 충분한 마력이 담겨 있을 수 있소. 라그나로스의 상징 하나를 내게 가져오면 그 마법을 추출해 테두리를 만들 수 있을 거요.", progress = "적합한 마력의 원천 없이는 응보의 횃불을 완성할 수가 없소.", completion = "이 상징은 사악한 마력을 뿜어내고 있군. 우리 일에 아주 딱이군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3453] = {title = "응보의 횃불", objective = "벨라로크 윈드블레이드가 응보의 횃불을 완성할 동안 기다려야 합니다.", description = "이 재료들을 다 결합하고 필요한 주문을 걸 테니 잠시만 기다리시오.", progress = nil, completion = "이제 당신이 완수해야 할 임무가 하나 남았소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3454] = {title = "응보의 횃불", objective = "응보의 횃불을 집어 드십시오.", description = "이제 이 횃불은 그 주인에게 결속되어야 하오. 횃불을 집어 드시오.", progress = nil, completion = "횃불을 양손으로 거머쥡니다. 증오와 분노의 파도가 몸 전체에 고동칩니다.", rewards = "다음과 같은 것들을 받습니다:\n\n응보의 횃불"},
[3461] = {title = "티모르에게 돌아가기", objective = "아이언포지에 있는 티모르에게 탁본 도구를 돌려주어야 합니다.", description = "티모르로부터 당신에게 보상을 주라는 이야기는 듣지 못했으니 아이언포지로 돌아가거든 그와 얘기를 해보시오. 틀림없이 아직 마법 지구에 있을 거요. 찾아가서 보상을 넉넉히 받아내시오. 이곳에서 한 일이 결코 쉬운 일은 아니었으니까... 암, 그렇고말고.\n\n아무튼 고맙소이다. 행운을 빌겠소.\n\n아, 난 탁본 도구 필요 없소. 티모르를 찾아가거든 돌려주시오.", progress = "돌아왔군! 아주 잘했소. 내 탁본 도구도 가지고 왔겠지?", completion = "대단해! 정말 다행이야.\n\n내 탑으로 가서 탁본을 조사할 생각을 하니 정말 흥분되는군. 당신이 참 부럽소이다... 아즈샤라 같은 곳에도 가고. 마법을 연구하는 이들의 공통된 꿈 아니겠소?\n\n탐험가 연맹을 위한 자원봉사와 같은 일이었기 때문에 보상 얘기 같은 건 꺼내지도 않았지만, 듣고 보니 보상을 받을 자격이 충분하군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n강철세공 경갑해골마법 수정구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3462] = {title = "견습기사 몰트레이크", objective = "견습기사 몰트레이크와 대화해야 합니다.", description = "내 대신 견습기사 몰트레이크와 얘기해 보시오. 몰트레이크가 응보의 횃불의 사용 방법에 대해 더 자세히 가르쳐 줄 것이오.", progress = nil, completion = "공격 준비는 다 되셨습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3463] = {title = "불 공격!", objective = "북쪽, 남쪽, 동쪽과 서쪽 감시탑 내부에서 응보의 횃불을 사용해 불을 지르십시오.", description = "잘 들으세요. 그 네 개의 감시탑은 절대 파괴할 수 없지만 응보의 횃불을 사용해 아주 오랫동안 불태울 수는 있습니다. 어떤 자연의 힘이나 마법으로도 끌 수 없는 불로 말이죠.\n\n탑이 불타는 동안에는 경비병들이 경비초소에 올라갈 수 없으니 첫 번째 방어선이 무너지게 될 겁니다.\n\n그 때 각 탑 안으로 들어가 녀석들의 요새 내부에서 응보의 횃불을 사용하도록 하십시오. 그리고 검은무쇠단의 정예 경비병들을 조심하시기 바랍니다.", progress = nil, completion = "정말 대단하군요! 굉장하지 않습니까, 주인님?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n용군단 다리보호구비룡불꽃 머리보호구검은비룡 도끼\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3481] = {title = "만물 상자...", objective = "궤짝을 여십시오.", description = "궤짝은 잠긴 듯합니다.", progress = nil, completion = "손을 대자 궤짝이 열립니다. 이 안에 음식이 얼마나 들어있을까요? 알아낼 수 있는 방법은 단 한 가지뿐입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n검은용군단의 보물"},
[3483] = {title = "배달 신호", objective = "아, 신호탄을 하나 더 달라고? 물론 드릴 수 있지.\n\n그리고 절대 잊지 마시오. 아즈샤라 남쪽 끝에 있는, 착륙장으로 만든 작은 섬이오. 제대로만 가면 못 보고 지나치는 일은 없을 거요.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n기본지급품 신호탄"},
[3501] = {title = "불완전한 드레니시스트 조각", objective = "굼이샤에게 불완전한 드레니시스트 조각을 가져다주고 각 파편에 대해 보상을 받으십시오.", description = "완전무결한 드레니시스트 구슬을 찾기란 하늘에서 별을 따는 것처럼 힘들겠지만 부서진 조각들이라면 이 땅을 탐험하면서 많이 찾을 수 있을 거예요.\n\n이 굼이샤가 불완전한 드레니시스트 조각을 사용해 고향으로 돌아갈 수 있을지는 솔직히 모르겠어요. 하지만 드레나이에게는 다른 용도라도 유용하게 쓰일 거예요.\n\n그러니 불완전한 드레니시스트 조각을 찾게 되면 제게 가지고 오세요. 사례를 해드리죠.", progress = "탐험을 하면서 좀 찾았나요?", completion = "정말 고맙... 그런데 여기 잡동사니에 뭐가 떨어졌죠?! 다 큰 남자가 침이나 흘리다니! 아이고, 더러워라! 이거 받고 얼른 사라져요.", rewards = "다음과 같은 것들을 받습니다:\n\n굼이샤의 잡동사니"},
[3502] = {title = "어느 드레나이의 잡동사니...", objective = "굼이샤에게 불완전한 드레니시스트 조각을 가져가십시오. 그 조각은 저주받은 땅에 있는 모든 야수가 지니고 있을 수도 있습니다.", description = "탐욕스러운 모습을 보면 구역질이 나요.\n\n견딜 수가 없어요. 이제부터 물질에 대한 <race>들의 집착에는 신경 안 쓰겠어요.\n\n불완전한 드레니시스트 조각을 가져올 때마다 제 잡동사니를 드리겠어요. 제 잡동사니 더미는 줄어들고 당신 잡동사니 더미는 늘어나니, 이런 걸 보고 드레노어 속담에 '누이 좋고 매부 좋고'라고 하지요.", progress = "좋아요, 조각은요? 설마 잊으신 건가요?\n\n<주먹으로 <name>에게 꿀밤을 먹이는 굼이샤>\n\n제발 정신 좀 차리세요!", completion = "정말 고마운... 그런데 여기 잡동사니에 뭐가 떨어졌죠?! 다 큰 남자가 침이나 흘리다니! 아이고, 더러워! 이거나 받고 얼른 사라져요.\n\n어디서 많이 들어 본 소리 같지 않아요? 당연히 그렇겠죠. 하루에도 골백번은 하니까...\n\n아, 이 세계가 왜 이리도 싫은지...", rewards = "다음과 같은 것들을 받습니다:\n\n굼이샤의 잡동사니"},
[3503] = {title = "사나스의 스승", objective = "왕년에는 스승님께 안내하는 조건으로 모험가들에게 대가를 요구한 적이 있었지. 하지만 지금은 부탁만 한다면 스승님께 안내해 주겠소.\n\n썩 내키는 일은 아니지만 스승님의 명령이니 어쩔 수 없지. 내가 할 수 있는 일이라곤 당신의 우스꽝스러운 복장이나 비굴해 보이는 표정을 비웃는 것뿐이지. 사실 지루하기 짝이 없는 일이지만 말이야...\n\n슬슬 이 대화도 지루해지기 시작했어! 자, 이제 말해보시지. 내 스승님을 만날 거야 말 거야?", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n아즈샤라 탑으로 순간이동"},
[3504] = {title = "배신", objective = "아즈샤라에 있는 아그토르 블러드피스트에게 아그토르에게 보내는 봉인된 편지를 전해야 합니다.", description = "배신자, 도둑! 나는 그녀를 그렇게 부르지. 그 정도밖에 안 되는 여자니까 말이오!\n\n블러드 엘프의 말만 믿은 내가 바보지.\n\n아즈샤라에 엄청난 재물과 귀한 물건들이 있으니 그녀를 보호할 전사 몇을 보내면 그 대가로 보상을 받기로 했었단 말이오. 이런, 그녀가 그 전사들을 모조리 죽여 버렸으니!\n\n복수를 해야겠소. 하지만 병력을 보낼 여력은 없소이다. 할다르 야영지의 북쪽에 있는 발로르모크에서 아그토르를 찾아보시오. 그 친구가 더 자세한 얘기를 해줄 거요.", progress = "아, 벨그롬이 이제는 지친 나머지 자기 동료도 아닌 사람을 보낸 모양이군.\n\n한때 이 야영지는 많은 전사들이 지키고 있었는데 지금은 모두 죽어 버렸소. 림토리라는 마법사가 모두 그들을 죽인 거요. 그녀는 벨그롬을 이리저리 가지고 노는가 하면 유혹하기까지 하더군. 내가 간섭할 바는 아니지만 당신이니까 내 말하리다. 그녀는 상당한 요부요. 그런 상황이었다면 나도 아마 똑같은 짓을 했을 테지... 그를 이해하기에 아직도 난 이곳에 남아 벨그롬을 돕고 있다오.", completion = "그녀와 일꾼들을 처단하기 위해 우리 병력 모두를 보냈지만 허사였소. 워낙 강한 녀석들이라 아무도 돌아오지 못했다오. 몇몇은 용감히 전사했겠지만 나머지는 그냥 도망쳐 버린 게 틀림없소. 겁쟁이들 같으니...\n\n이제는 증원군이 도착했으니 어쩌면 아직 손쓸 방법이 있을지도 모르겠소. 벨그롬에게 거짓말을 하고 배신한 것에 대한 벌을 그녀에게 내릴 수 있을지도...\n\n어떻소? 해보겠소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3505] = {title = "배신", objective = "블러드 엘프 수색꾼 10명과 블러드 엘프 감정관 10명을 처치한 후, 학자 림토리의 야영지를 찾아내십시오. 야영지를 찾으면 그녀를 싸움으로 유인하는데 사용할 수 있을 만한 것을 찾아보십시오. 림토리가 중요하게 여기는 것이라야 합니다.", description = "우선 아즈샤라 북부 반도의 남부 절벽을 따라 그녀의 일꾼들을 처치하는 것부터 시작합시다. 피의 분노를 담아 녀석들을 처치하시오. 배신은 옳지 않다는 사실을 뉘우치게 하시오.\n\n림토리는 신경 쓰지 않아도 될 것이오. 자신의 호위병들을 거느리고 아즈샤라를 수색하는데 바쁠 테니 말이오. 그녀의 개인 야영지는 그 일꾼들을 처치한 후에 찾는 게 더 신중한 처사일 거요. 그녀를 어디서부터 공격하는 게 좋을지 미리 파악해두는 것도 현명한 일이겠지. 그리고 그곳엔 아마도 그녀를 자극하는데 쓸 만한 물건이 있을지 모르오.", progress = "나이트 엘프 소환의 고서'라는 이 책의 제목은 검은 가죽 표지에 금빛 잎으로 장식되어 있습니다. 책장을 넘겨 보니 아주 오래된 것이지만 최고의 상태로 보존되었다는 것을 알 수 있습니다.\n\n이 책의 글은 어떤 고대 언어로 쓰인 듯합니다. 어쩌면 나이트 엘프의 언어일지도 모릅니다.\n\n블러드 엘프들의 배신에 대한 보복을 한 후 이곳으로 돌아와야겠다는 생각이 본능적으로 듭니다.", completion = "책장을 넘기며 훑어보다가 얇고 검은 비단 헝겊 조각으로 표시되어 있는 페이지를 찾았습니다.\n\n적혀 있는 글을 해독하려고 애쓰다 보니 한 페이지의 아래 부분에 도형이 그려져 있는 것이 보입니다. 앞을 둘러보니 수정과 원, 그리고 다른 재료들이 도형과 비슷한 문양으로 땅에 놓여져 있는 것을 알 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3506] = {title = "배신", objective = "학자 림토리와 연결된 비전 집중의 수정을 파괴하고 그녀를 처치하십시오. 그런 다음 그 증거로 아즈샤라에 있는 아그토르 블러드피스트에게 학자 림토리의 머리카락을 가져가야 합니다.", description = "곰곰이 생각하다 보니 좋은 생각이 떠오릅니다. 어쩌면 앞에 놓인 수정들을 파괴하면 벨그롬을 배신하고 수많은 오크를 학살한 블러드 엘프를 화나게 할지도 모릅니다.\n\n계속 책 안의 글과 그림들을 해독하다 보니 이 수정들 중 하나는 이 원을 만든 자와, 다른 것은 그보다 훨씬 더 사악한 존재와 연결되어 있음을 알 수 있습니다.\n\n책을 덮고 어느 수정을 파괴할지 결정합니다.", progress = "블러드 엘프 배신자들을 처치하는 일은 잘 진행되고 있소? 얼마나 진척되고 있소?\n\n당신이 그 괘씸한 요부를 무릎 꿇릴 만큼 강하다면 좋겠소! 그녀가 한 일을 생각하면 고통스러운 죽음 외에는 선물할 게 없으니까!", completion = "굉장하군!\n\n해냈어! 벨그롬이 무척 기뻐할 거요. 드디어 수많은 우리 전사들의 영혼이 편히 쉴 수 있을 거요. 정말 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3507] = {title = "배신", objective = "오그리마에 있는 벨그롬 록마울과 대화하십시오.", description = "오그리마에 있는 벨그롬에게 돌아가시오. 이 머리카락을 직접 보고 싶어할 테니까! 우리도 곧 그곳으로 돌아가겠소.\n\n아, 오늘은 참으로 기쁜 날이군. 도와줘서 고맙소.", progress = "아, 당신을 기억하오, <class> 친구. 아즈샤라로 가서 날 배신한 그 나쁜 것을 처치해 달라고 부탁했었지! 엄청나게 긴 시간이 흐른 것 같군. 설마 아그토르와 다른 전사들도 다 죽어 버린 것은 아니겠지?", completion = "하하, 꼴 좋군! 이 요부 같으니라고!\n\n고맙소. 진정으로 고맙소! 오늘은 정말로 기쁜 날이 아닐 수 없소!\n\n내게 힘만 있다면 왕국 하나를 손에 쥐어 주고 싶지만 이거라도 받아 주시오.\n\n하하, 불쌍한 이 블러드 엘프... 그러니 애초에 이 벨그롬을 배신하지 말았어야지!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n장작불 수정구벨그롬의 망치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3508] = {title = "보호막 파괴", objective = "로라무스가 깨우침의 마법을 마칠 때까지 기다려야 합니다.", description = "정말 무모한 <race>|1이로군;로군;. 하지만 그런 점이 바로 자네 같은 종족에게서 본받을 만한 점이야. 성공할 가능성이 턱없이 낮은데도 맹목적으로 뛰어드는 그 무모함 말이네. 라젤리크의 부하를 하나만이라도 쓰러뜨릴 수 있다면 내, 기꺼이 도움을 주지.\n\n라젤리크의 심복들을 감싸고 있는 보호막을 깨뜨리려면 시간도 오래 걸리고 희귀한 유물도 얻어야 한다네.\n\n움직이지 말고 가만히 있게나. 깨우침의 의식부터 수행해야 하네. 먼저 정보를 모아서 엄청난 힘을 지닌 무기를 만들어야 해.", progress = nil, completion = "그 악마의 이름을 알아야 하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3509] = {title = "악마의 이름", objective = "아즈샤라에 있는 제왕 아크코로크와 대화해야 합니다. 아크코란의 신전을 찾으려면 물가부터 조사해 보십시오.", description = "악마의 군주와 그의 심복들을 해치울 수 있는 방법은 단 한 가지뿐이지. 악마의 진짜 이름이 새겨진 마력의 무기를 만드는 거야.\n\n그 무기만이 악마의 군주와 그를 따르는 모든 부하들을 처치할 수 있지.\n\n아즈샤라에 제왕 아크코로크라는 하급 신이 살고 있네. 그를 만나서 얘기를 들어야 하는데, 그 부하들이 자네를 보면 즉시 해치려고 덤벼들 테니 조심하게.\n\n그에게 정보를 얻으려면 합당한 대가도 치러야 할 거야.", progress = nil, completion = "악마의 군주라고?\n\n&lt;비웃으며&gt;\n\n신이 그대에게 모든 것을 알려 줄 수도 있지만 그보다 먼저 그대가 신을 도와야 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3510] = {title = "악마의 이름", objective = "헤타에라를 물리치고 헤타에라의 훼손된 머리, 헤타에라의 피묻은 머리, 헤타에라의 으깨진 머리를 제왕 아크코로크에게 가지고 가야 합니다.", description = "나의 아이들을 죽이는 자가 있소. 스스로 바다의 제왕이라 칭하고 있지. 하지만 그녀는 가짜 신일 뿐 그 이상은 아무것도 아니오. 그녀를 물리치고 머리를 모두 가져오시오.\n\n그리하면 그대가 찾고 있는 이름은 물론이고 그보다 더 중요한 다른 것도 주겠소.\n\n그녀는 자신의 보금자리를 배회하고 다니는데 이름은 헤타에라라고 하오.\n\n<남서쪽을 가리키며>\n\n가시오!", progress = "<허리를 굽혀 자세히 살펴보며>\n\n머리는 어디 있소?", completion = "드디어 이 아크코로크의 지혜를 받을 만한 자가 나타났군!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3511] = {title = "악마의 이름", objective = "헤타에라의 피를 로라무스 탈리뻬데스에게 가져가야 합니다.", description = "약속대로 악마의 군주, 파멸자 라젤리크의 진짜 이름을 가르쳐주겠소. 그 전에 그대의 여정에 없어서는 안 될 것을 준비해주지.\n\n그대에게 무기를 만들어줄 텐데... 담금질할 피가 필요하오. 그대가 가져온 머리에서 피를 짜내는 동안 잠시만 기다리시오.\n\n<거대한 두 손으로 머리를 쥐어짜 피를 빼낸 후>\n\n이 피를 로라무스에게 가져다주면서 악마의 이름도 함께 알려주시오. 라크리크...다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3512] = {title = "에라니쿠스의 말", objective = "여명의 설원의 동쪽으로 가서 영매 엄브런스를 만나야 합니다.", description = "우리는 보석을 통해 에라니쿠스와 대화하는 방법을 가장 먼저 알아내야 하노라. 그는 지금 악몽과 죽음 사이의 불확실한 상태에서 악몽 속에 갇혀 있느니라. 그대가 준 정수가 심하게 오염되었기는 하나 그에게 다가갈 방법이 있을 것이다.\n\n여명의 설원 동쪽의 눈덮인 골짜기로 먼 여행을 떠나 우리의 인간 동지인 영매 엄브런스를 찾아라. 그는 죽은 자를 대신하여 말하는 인간 영매이니라. 에라니쿠스가 완전히 죽은 것은 아니지만 영매의 도움을 받을 수 있을 것인즉... 자, 떠나거라.", progress = nil, completion = "이타리우스님께서 당신을 내게 보낸 건 현명한 판단이셨소. 에라니쿠스님은 당신이 생각하는 것처럼 죽은 것은 아니지만 그가 직접 우리에게 조언을 해 주실 것이오. 하지만 지금 난 당신을 직접 도울 수가 없소.\n\n대신 죽은 자와 이야기 할 수 있는 내 능력을 빌려 주도록 하겠소이다. 하지만 먼저 노쇠한 육체로는 할 수 없는 일을 해줄 젊은이가 필요하오. 내게 가장 중요한 점을 치는 도구를 빼앗겼는데 그게 없으면 에라니쿠스님을 도울 수가 없소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3513] = {title = "룬문자 두루마리", objective = "불모의 땅의 북쪽 방어탑으로 룬문자 두루마리를 가지고 가야 합니다.", description = "공문으로 보이는 두루마리가 은색 리본으로 단단히 감겨있습니다. 이 두루마리에 관심을 보일 만한 자가 분명 있을 텐데, 그게 과연 누구일까요?\n\n잿빛 골짜기의 북쪽 경계 근처에 전초기지가 하나 있습니다. 이 두루마리의 내용이 나이트 엘프와 관련된 것이라면 바로 그곳으로 가져가는 것이 옳을 것입니다.", progress = "가져온 게 뭐요?", completion = "흠... 이걸 어디서 찾았소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3514] = {title = "호드의 존재", objective = "갈퀴발톱굴의 우두머리인 열쇠지기 린타리엘을 처치해야 합니다.", description = "이 두루마리는 돌발톱 봉우리, 갈퀴발톱굴의 열쇠지기 린타리엘의 것이로군.\n\n당신이 두루마리의 전령을 처치했으니 한 시름 덜었소. 흠... 하지만 우리는 이곳에 기반을 세워야 하오. 호드는 린타리엘의 졸개들을 두고 보지만은 않을 것이오.\n\n갈퀴발톱굴로 가서 린타리엘을 처치하고 모든 이들이 볼 수 있도록 증표를 세워두시오. 이 호드 깃발을 가지고 가서 갈퀴발톱굴에 세워두시오. 다시는 우리 영토에 전령을 보내지 못하도록!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n개척자의 장화황마 장갑\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3517] = {title = "서판 훔치기", objective = "베스아마라 서판, 진야엘 서판, 마크리 서판, 샤엘하이 서판을 찾아 아즈샤라에 있는 제디가에게 돌아가야 합니다.", description = "이 아즈샤라에서 나도 내 나름대로 최선을 다했습니다. 벨그롬의 처벌도 나름대로 도움이 됐지요.\n\n내가 떠나기 전에 몇 가지 조사를 했었는데 주위에 값진 물건들이 얼마나 많이 널려 있는지 알면 놀랄 거예요.\n\n내 제안에 대해 더 얘기하도록 하죠. 그 물건 중 일부를 모아오면 조금 나누어 주도록 하죠.\n\n여기서 동쪽으로 가면 엘다라스 폐허라는 곳이 있는데, 그곳에 내게 필요한 서판들이 있습니다. 네 개 모두 명가의 마법사들의 이름을 딴 서판들이지요. 일단은 그것들을 가지고 온 후에 더 얘기하기로 하죠.", progress = "당신에게 모아오라고 부탁한 서판은 적당한 사람에게 팔면 꽤 짭짤한 수입을 올릴 수 있어요. 서판을 찾아오면 누구에게 가져가야 할지 알려 주겠어요. 하지만 당신이 서판을 전달했다는 증거를 가지고 온 후에 당신 몫을 주도록 하죠... 난 바보가 아니거든요.\n\n하루도 안 남았으니 서두르세요. 안 그러면 다른 사람에게 부탁할 수밖에 없겠네요.", completion = "서판의 상태도 아주 양호하고 완벽하군요. 이 서판에 관심 있어 할 자들에게 가져가면 상당히 괜찮은 가격을 받을 수 있겠어요.\n\n여기서는 더 이상 시간을 낭비하지 않는 게 좋겠네요. 이제 돈을 벌러 가야죠?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3518] = {title = "마가타에게 전달", objective = "썬더 블러프에 있는 마가타에게 베스아마라 서판을 가져가야 합니다.", description = "첫 번째 서판은 마가타라는 타우렌에게 가져가야 해요. 마가타는 썬더 블러프 장로 중 한 명이며, 타우렌과 포세이큰 간 동맹을 지지하는 자 중 하나이기도 하죠. 다른 어떤 장로들보다도 그녀는 타우렌과 타우렌의 방식이 포세이큰이 다시 인간으로 돌아가는 길을 찾는 데 도움을 줄 것이라 믿고 있습니다.\n\n그녀에게 베스아마라 서판을 가져다주세요. 이 서판은 그녀가 포세이큰을 도울 방법을 찾는 데 실마리가 될 거예요. 적어도 그녀 말로는 그렇다고 해요.", progress = "무슨 일로 온 겐가? 돌봐야 할 것들이 무척 많으니 어서 용건을 말해줬으면 하네만...", completion = "아, 드디어 베스아마라 서판을 찾았군. 혹시나 제디가가 실패했거나, 아즈샤라에서 죽은 것이 아닌가 걱정하고 있던 참이었다네. 그녀가 성공했다니 다행이군.\n\n베스아마라는 명가의 가장 영향력 있는 연금술사 중 한 명이었지. 그 마법사는 여러 가지 일을 했지만 그 중에서도 금속을 변형할 줄 아는 자는 그뿐이었다고 하더군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3519] = {title = "친구의 도움", objective = "그늘 협곡에 있는 디라니아 실버샤인과 대화하십시오.", description = "으으... 여기서 아주 가까이에 있는 거미 굴을 조사하다가 기시이스라는 흉측한 거미에게 물렸어요. 독이 심하게 퍼진 것 같으니 좀 도와주세요.\n\n디라니아 실버샤인에게 제 상황을 좀 전해 주세요. 그녀라면 도울 수 있을 거예요.\n\n서둘러 주세요... 너무 어지러워요...", progress = nil, completion = "이런, 왜 오늘은 이베론이 보이지 않나 하고 어쩐지 좀 불길한 생각이 들었는데... 제 느낌이 맞았군요. 그 거미를 조심하라고 늘 주의를 줬는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3520] = {title = "계곡천둥매의 영혼", objective = "페랄라스에 있는 3마리의 계곡천둥매의 영혼을 모은 후 스팀휘들 항구에 있는 예킨야에게 돌아가야 합니다.", description = "나는 페랄라스에 사는 계곡천둥매의 영혼을 찾고 있소. 계곡천둥매는 고대 신과 혈연이 맺어져 있지... 그들의 영혼은 고대 신과 연결되어 있소.\n\n이 나뭇가지를 들고 페랄라스로 가보시오. 페랄라스 남부와 중부에 살고 있는 계곡천둥매를 쓰러뜨린 후 시체 위에서 이 나뭇가지를 흔드시오. 그러면 그들의 영혼이 소환될 거요. 영혼을 건드려 모아오도록 하시오.\n\n영혼과 함께 사용한 나뭇가지를 갖고 돌아오면 고대 신에 대해 자세히 말해주리다.", progress = "계곡천둥매의 영혼은 모았소?", completion = "수고했소. 이제 자세한 얘기를 할 때가 된 것 같군...\n\n트롤의 고대 예언에 의하면 영혼의 약탈자라고도 불리는 신, 학카르가 언젠가 환생할 것이라고 하오. 어떤 이들은 학카르의 도래가 우리 트롤족에게 기쁨과 영광을 안겨줄 것이라고도 하고, 또 어떤 이들은 그의 환생이 만물의 종말이 가져올 것이라고도 하지.\n\n이 신화를 전부 믿는 것은 아니지만 학카르의 정수가 엄청난 힘을 가지고 있다는 것은 확실하오. 이 힘이 무책임한 자들의 손에 넘어가서는 안 되는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3521] = {title = "이베론을 위한 해독제", objective = "그늘 협곡에 있는 디라니아 실버샤인에게 히아신스 버섯 7개, 달봉우리 백합 4개, 나무그물거미 영액 1개를 가져가야 합니다.", description = "거미 독을 해독할 비약을 만들 수 있으니 이베론을 도와줄 수 있을 거예요. 하지만 그 해독제를 만들려면 몇 가지 재료를 구해와야 해요.\n\n우선 히아신스 버섯이 필요해요. 나무 밑에서도 자라고, 남쪽에 사는 그렐들에게서도 찾을 수 있어요. 녀석들이 그 버섯을 즐겨먹는 모양이에요. 그리고 달봉우리 백합도 필요한데 이건 물웅덩이 근처에서만 자라죠.\n\n마지막으로 구할 재료는 아마 구하기가 제일 힘들 거예요. 바로 이베론을 문 그 거미들에게서 나무그물거미 영액을 구해와야 해요.", progress = "부디 그 재료들을 모아 주세요. 이베론은 우리의 도움이 필요해요.", completion = "이렇게 빨리 재료를 모아서 참 다행이에요!\n\n잠시만 기다리시면 해독제를 만들어 드리겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3522] = {title = "이베론을 위한 해독제", objective = "제한 시간이 지나기 전에 이베론에게 해독제를 가져다줘야 합니다. 이베론은 북쪽에 있는 동굴 옆에서 찾을 수 있습니다.", description = "해독제를 다 만들었어요. 이베론에게 가져가 먹이도록 하세요.\n\n한 가지 알아두셔야 할 게 있는데 이 해독제는 5분 동안만 효력을 유지한답니다. 그러니 그 시간 안에 이베론에게 가져가야 해요.\n\n부디 빨리 도착하시길 바랄게요.", progress = "아... 돌아와 주다니 정말 기쁘군요.", completion = "뭐죠?\n\n오, 역시 디라니아 밖에 없어!\n\n&lt;해독제를 마시는 이베론&gt;\n\n난 항상 말썽만 피우고 디라니아는 내 뒤치다꺼리만 하죠.\n\n기분이 훨씬 좋긴 했는데 완전히 나을 때까지 여기 좀 앉아 있어야겠어요. 그건 그렇고... 제가 지나갈 수 있도록 저 못된 나무그물거미들을 좀 처치해주시겠어요?!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n사초줄기 반바지나무껍질 조끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3523] = {title = "가시덩굴 구릉의 스컬지", objective = "그가 당신에게 서약의 돌을 줄 것입니다. 벨리스트라즈의 계획을 돕는 것에 동의하면 다시 그와 대화하여 그에게 서약의 돌을 돌려주십시오.", description = "훌륭합니다! 내 이름은 벨리스트라즈입니다. 구해 줘서 고맙습니다. 필경 죽음을, 아니 그보다 더한 일을 당하게 될 줄 알았답니다. 이 쓰레기 같은 스컬지 노예들의 먹이가 된다든지... 네, 스컬지 말입니다. 녀석들이 이곳 가시멧돼지와 모종의 거래를 맺어 이런 참사가 일어난 것이지요.\n\n들어 보세요... 여기서 그냥 도망칠 수도 있지만, 그보다 모두를 위해 뭔가 보탬이 되는 일을 하고 싶습니다. 당신이 좀 도와 줄 수 없겠습니까? 아마 위험한 일이 될 테지만 당신은 그런 것에 대해 크게 걱정할 것 같지는 않아 보이는군요. 나를 좀 도와주시기 바랍니다.", progress = "난 정치적 분쟁 따위에는 그다지 관심이 없습니다. 당신이 호드이든 얼라이언스이든 상관하지 않습니다. 무슨 말인지 알겠습니까? 나는 모든 종족에 대한 직접적이고 위험한 악을 제거하고 싶을 뿐입니다.\n\n모든 종족을 위한 진정한 아제로스의 영웅이 되고 싶거든 내가 당신에게 준 서약의 돌을 약속의 표시로 내게 주십시오. 나는... 이 지역 출신이 아니랍니다. 사실 우리 종족에게 있어 서약의 돌이란 계약의 결속력을 상징하는 중요한 물건입니다.", completion = "대단하군요, 당신에게선 영웅의 자질이 보인다고 생각했습니다! 솔직히 말하지만, 이건 아주 고된 일이 될 겁니다. 하지만 정신만 바짝 차리면 이길 수 있습니다.\n\n자, 지금까지 무슨 일이 있었는지 말해 드리죠...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3524] = {title = "해변으로 올라온 바다 생물", objective = "아우버다인 바로 남쪽에 있는 떠내려온 바다 생물에게서 바다 생물 뼈를 회수한 후, 아우버다인에 있는 그웨니스 블리레곤드에게 가져가야 합니다.", description = "어둠의 해안 연안에서 거대한 바다 생물들이 뛰어올라 해변에서 죽는다고 알려져 있죠. 그런데 이렇게 해변으로 밀려와 죽는 생물의 수가 최근 부쩍 늘었어요. 달의 신전에서 조사를 위해 저를 이곳에 파견했지만 물가에 멀록들이 있어서 어려움을 겪고 있답니다.\n\n아우버다인 바로 남쪽에 해변으로 밀려 올라온 거대한 생물이 하나 있는데 잿빛안개멀록들이 둥글게 둘러싸고 있어요. 그곳으로 가서 그 생물의 뼈를 가져다주실 수 있나요?", progress = "최근에 들어서 부쩍 많은 생물이 어둠의 해안 근처 해변으로 올라와 죽기 시작했습니다. 아주 불길한 징조라고 볼 수밖에 없어요. 남쪽에 있는 바다 생물의 뼈 견본이 있으면 다르나서스에서 이 상황을 분석하는데 도움이 될 겁니다.", completion = "뼈를 채취하는데 멀록들이 너무 성가시게 굴지는 않았나요?! 이것은 다르나서스로 떠나는 히포그리프 편에 꼭 보내도록 하겠어요. 조사에 도움을 받으면 사례를 하도록 달의 신전에서 제게 자금을 좀 주었답니다. 감사의 표시이니 이것을 받아 주세요.\n\n이번 일에 성공하셨으니 관심이 있으시다면 달의 신전을 더 도울 수 있는 기회를 드리고 싶습니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3525] = {title = "우상 진화", objective = "가시덩굴 구릉에 있는 가시멧돼지의 우상까지 벨리스트라즈를 호위해야 합니다.\n\n우상을 진화하는 의식을 수행하는 동안 벨리스트라즈를 보호해야 합니다.", description = "입구 근처에 가시멧돼지들이 화덕으로 사용하는 무시무시한 우상이 하나 있습니다. 녀석들은 불모의 땅에서 납치한 자들을 모조리 먹어 치우지요. 그 우상의 불을 꺼 다시는 녀석들이 불을 피우지 못하게 해야 하는데 그러려면 당신의 도움이 필요합니다. 제 계획을 말해 드리겠습니다. 저를 우상까지 호위해 주세요. 우상에 도착하면 즉시 진화의 의식을 시작할 겁니다. 의식이 시작되면 당신과 얘기를 나누기는 고사하고 제 몸 하나 보호하는 것도 어려울 테니, 제가 의식을 진행하는 동안, 부디 절 보호해 주십시오. 제가 녀석들에게 당하면 모든 게 끝장입니다.\n\n무슨 말인지 아시겠습니까?!", progress = nil, completion = "벨리스트라즈가 홀연히 사라진 자리에 불타는 화로가 갑자기 나타났습니다. 타오르는 불길 속을 응시하고 있으려니... 큰 날개를 가진 붉은 용의 형상이 머릿속을 메웁니다. 평소보다 더 깊게 울리는 벨리스트라즈의 목소리가 들립니다.\n\n\"언젠가는 죽어 흙으로 돌아갈 생명이여... 기대한 대로 과연 영웅이라 할만 하다. 네 덕분에 이 야수들이 저지르던 처참한 학살은 이제 종결되고 너 같은 평범한 생명체들에 대한 내 믿음도 다시 한번 살아났도다. 영웅에게 걸맞은 보상을 받을 지어다.\"", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n용발톱 반지"},
[3526] = {title = "고블린 기계공학", objective = "고블린 기계공학에 대해 더 알고 싶으면 가젯잔에 있는 닉스 스프로켓스프링에게 기계공학 설명서를 가져가야 합니다.", description = "고급 기계공학은 노움과 고블린의 두 가지 학문으로 분류된답니다. 의심할 여지없이, 똑똑한 모든 기술자들은 고블린 기계공학을 선택한답니다. 화력이 대단한 폭발물과 뛰어난 장비를 현명하게 사용하여 세계를 완전히 장악하는 것이죠!\n\n자, 이 설명서를 읽어 보세요. 고블린 기계공학을 배우고 싶거든 가젯잔에 있는 닉스 스프로켓스프링에게 이 설명서를 가져가도록 하세요. 회원 가입은 영구적이며 다른 학문을 배우지 못하게 한다는 사실을 명심하세요. 그러니까 그가 주는 임무를 완료하기 전에 당신이 정말 원하는 것이 무엇인지 확실히 하도록 하세요!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3527] = {title = "모쉬아루의 예언", objective = "타나리스에 있는 예킨야에게 첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 가져가야 합니다.", description = "모쉬아루의 고대 예언은 죽은 신, 학카르의 정수를 담는 방법에 대해 얘기하고 있소. 서판 두 개에 나뉘어 쓰여 있는데, 가젯잔 서쪽에 있는 트롤의 도시인 줄파락에 있소.\n\n내게 모쉬아루 서판을 가져오시오!\n\n첫번째 서판은 오래전 순교한 데카라는 트롤이 가지고 있소. 일설에 의하면 순교자 데카를 박해한 자들은 저주를 받아 왕쇠똥구리로 변해 데카의 묘지를 떠돌고 있다고 하오.\n\n두번째 서판은 가즈릴라의 신성한 웅덩이 근처에 있는 유체술사 벨라타가 가지고 있소.\n\n서판들을 찾거든 내게 가져오시오.", progress = "모쉬아루의 예언이 담긴 서판들은 가져왔소?\n\n그 서판들을 연구해 보면 학카르의 정수를 담는 방법을 알아낼 수 있소!", completion = "아, 잘 됐군. 이 고대 서판들을 하나로 합치면 그 안에 숨겨진 비밀을 연구해 볼 수 있소.\n\n당신에게 점점 신세를 지게 되는군. 앞으로도 부탁할 일이 많을 거요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3528] = {title = "학카르의 화신", objective = "타나리스에 있는 예킨야에게 충만한 학카르의 알을 가져가야 합니다.", description = "이제 학카르 화신의 정수를 모을 차례요.\n\n이 학카르의 알을 동부 왕국의 가라앉은 사원에 있는 죽은 신의 성소로 가지고 가시오. 그리고 알의 힘으로 죽은 신을 깨우시오.\n\n아마 학카르는 졸개들을 보내 당신을 처치하려 할 거요. 그들을 물리치고 학카르의 피를 반드시 손에 넣어야 하오. 그 피로 학카르의 영혼이 깃든 영원의 불꽃들을 꺼야 하니까. 불꽃이 모두 꺼지면 학카르의 화신이 나타날 거요.\n\n그를 물리치고 학카르의 알에 그의 정수를 담아오시오.", progress = "학카르의 화신은 물리쳤소, <name>? 내가 준 알에 그의 정수를 담아온 거요?", completion = "학카르의 정수를 모아왔군! 지금 이 순간에도 충만한 알이 살아 움직이는 게 느껴져! 학카르의 전설이 사실인 것 같소?\n\n전설은 이야기일 뿐일테... 하지만 사실이라면 학카르가 환생하여 무슨 일이라도 저지를까 두렵소. 내 이 알을 잘 간직해 사악한 무리의 손에 들어가지 않도록 하겠소.\n\n이제 끝났소, &lt;name&gt;. 이번 일로 당신은 전설에 손을 댄 거요. 그 용감한 행동이 언젠가 아제로스의 모습을 바꾸어놓으리라 믿소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아방가드 투구생명력의 단검금은보석 머리장식\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3541] = {title = "제스리몬에게 전달", objective = "오그리마에 있는 제스리몬에게 진야엘 서판을 가져가야 합니다.", description = "오그리마에 친구가 하나 있는데 골목길에 살고 있어요. 그를 어디 가서 찾아야 하는지 모르면 상당히 애를 먹겠지만 높은 건물들을 뒤지다 보면 별문제 없이 찾을 수 있을 거예요.\n\n한 가지만 당부하죠. 우리 둘 모두에게 안 좋으니까 칼림도어에 사는 자들에게 그 친구가 칼림도어에서 뭘 하는지 말하고 다니지 말아줘요.\n\n진야엘 서판을 가지고 가면 그가 후하게 값을 쳐줄 거예요. 이유는 모르겠지만 그 서판의 행방을 듣고는 무척 흥분하는 기색이었거든요.", progress = "그래, 뭣 때문에 온 거지? 그렇지 않아도 오늘 할 일이 많은데 자네는 오늘 일정에 없는 걸. 날 자꾸 귀찮게 하면 가만두지 않겠네.", completion = "아하, 그 먼 아즈샤라에서 제디가가 물건을 보내왔군그래. 기다리고 있었는데, 잘 됐어.\n\n제디가, 아주 괜찮은 여자지. 게다가 날카롭기도 하고. 그보다 더 바랄 게 어디 있겠나?\n\n이것 좀 보라고... 서판의 상태가 완벽하군. 자네, 꽤 괜찮은 배달부로군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3542] = {title = "안드론 건트에게 전달", objective = "언더시티에 있는 안드론 건트에게 마크리 서판을 가져가야 합니다.", description = "다음에 만날 사람은 언더시티 연금술 실험실 근처에 있는 안드론 건트라는 언데드예요.\n\n그 친군 이 서판이 왜 필요한지에 대해서는 쉽게 입을 열더군요. 언더시티의 일부 마법사들이 명가에서 사용하던 신비술을 연구하려는데 이 서판이 도움이 될 거라고 생각한다나 봐요. 마크리는 생물, 특히 정령을 소환하는데 능통했죠.\n\n마크리 서판을 가져다주고 내게 돌아와서 사례금을 받도록 하세요.", progress = "어이구... <딸꾹>... 이게 웬일이야? 모험가...로군. <딸꾹>!\n\n그런데 무슨 일이지... <딸꾹>?", completion = "여기 동전 몇 개...를 줄 테니... &lt;딸꾹&gt;... 새 갑옷 같은 거라도 사... 입으라고...\n\n제대로 팔면 금화 두어 개는... &lt;딸꾹&gt; 받을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3561] = {title = "대마법사 실렘에게 전달", objective = "아즈샤라에 있는 대마법사 실렘에게 샤엘하이 서판을 가져가야 합니다.", description = "이 마지막 서판은 아주 위험한 인물에게 가져다 줘야 해요. 지금까지 당신에게 만나보라고 말했던 자들보다 훨씬 믿지 못할 자라는 사실을 명심하세요.\n\n대마법사 실렘은 아즈샤라를 내려다보는 언덕 위 탑에 있습니다. 인간이긴 하지만 하는 행동을 보면 내가 지금까지 만났거나 처치한 인간들과는 굉장히 달라요. 그의 몸에서는 힘이 배어 나오죠. 이 서판으로 뭘 할 계획인지는 감히 물어보지도 못해요.\n\n그는 나를 찾아와서는, 자기를 만날 준비가 되면 경호원인 사나스가 탑으로 데려다 줄 것이라고 말하더군요. 북쪽으로 가서 사나스를 찾아보세요.", progress = "무슨 일인가?", completion = "아. 샤엘하이 서판이로군. 얼마나 오래전부터 이걸 연구해 보고 싶었는지 모른다네.\n\n고맙네. 제디가에게 가서 내가 칭찬하더라고 전해주게. 이 서판이라면 그녀가 요청한 값을 지급할 가치가 있지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3562] = {title = "제디가에 대한 마가타의 답례", objective = "아즈샤라에 있는 제디가에게 마가타의 쪽지를 가져가야 합니다.", description = "이 쪽지를 제디가에게 전해 주고 그녀가 이곳에 돌아오면 사례하겠다고도 말해 주시게. 일을 잘 끝마쳐서 기쁘다는 말도 함께 말이야.\n\n어서 가보게나. 가서 내가 여기서 기다리겠다고 전해주게.", progress = "그래, 마가타가 뭐라든가요? 그 늙은 대모... 분명 거만하게 굴었겠지.", completion = "아. 잘 됐네요. 생각보다 훨씬 사리 분별이 있는 여자군요... 적어도 당신에게는 말이에요. 거만하게 직접 오지 않고 다른 사람을 보냈다면서 당신을 처벌할 줄 알았거든요. 그 서판을 몹시도 원했던 모양이네요. 재미있는데요.\n\n다음 기회에 한번 깊이 생각해볼 문제로군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3563] = {title = "제디가에 대한 제스리몬의 답례", objective = "아즈샤라에 있는 제디가에게 제스리몬의 쪽지를 가져가야 합니다.", description = "이 쪽지를 제디가에게 가져다주고 우리 거래가 아주 유익했고 내가 그녀의 일에도 만족스러워하더라고 전해 주시게.\n\n오그리마로 빨리 돌아오면 이 제스리몬이 아주 후하게 대접해 줄 것이라고도 전해 주고 말이야.\n\n제디가에게 그렇게 전해주고, 언젠가 내가 다시 자네를 부를 일이 있을지도 모르겠네.", progress = "제스리몬은 만나봤나요?\n\n트롤 친구들 중에서도 좀 거칠긴 하지만 그 친구 정보는 그런 대로 정확하고 사례도 후하거든요.\n\n그 친구 태도를 받아들일 수 있을 정도면 앞으로 그와 거래해 보세요. 수입이 짭짤할 거예요.", completion = "이 쪽지를 보니 그가 상당히 기뻐한 모양이군요... 너무 기뻐하는 것 같네요.\n\n언제 한번 시간을 내서 그의 관심에 내가 얼마나 감사하고 있는지도 알려줘야겠네요. 그러고 보니, 아즈샤라에서 더 머물 이유가 적어도 하나는 생긴 셈이네요.\n\n자, 여기 당신 몫이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3564] = {title = "제디가에 대한 안드론 건트의 보답", objective = "아즈샤라에 있는 제디가에게 안드론의 쪽지를 가져가야 합니다.", description = "자... 여기... <딸꾹> 이걸 제디가에게 전해주시오. 행운을 비오!", progress = "아직 안드론을 못 만났나요? 언더시티를 좀처럼 떠나지 않는 친구라 찾는 게 그리 어렵진 않을 거예요.", completion = "좋았어요... 잠깐만 기다려요.\n\n하하! 서판을 가져다주니 뭐라고 하던가요? 보답이 너무 과한 거 같은데요! 물론 불평하는 건 아니에요. 거래가 변경됐다고 말해줬나요? 아니면 또 만취해 있던가요?\n\n뭐, 상관없죠... 자, 당신 몫이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3565] = {title = "제디가에 대한 실렘의 보답", objective = "아즈샤라에 있는 제디가에게 실렘의 쪽지를 가져가야 합니다.", description = "이게 뭐지? 아, 그렇군. 사례금. 당연히 줘야지.\n\n이걸 가지고 어서 가보게. 제디가가 자네가 돌아오길 애타게 기다리고 있을 테니 말이야.", progress = "실렘이 뭐라고 하던가요? 실렘이 마법을 쓴다든가 자기를 위해 일을 하지 않겠느냐고 한다든가 당신에게 무슨 짓을 하지는 않았나요?", completion = "아무 문제 없었다고요? 전혀요? 그것 참 신기한 일이로군요. 좀 꺼리는 기색을 보이거나 거래를 파기할 줄로 알았는데... 흠, 어쩌면 믿을만한 사람인지도 모르겠군요.\n\n뭐, 그 문제 때문에 너무 고민할 필요는 없죠. 여기 당신 몫이에요. 도와줘서 고마워요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3566] = {title = "일어나라, 흑요암이여!", objective = "검은 라소릭과 흑요암을 쓰러뜨리고, 그 증거로 검은 라소릭의 머리카락과 흑요암 심장을 아이언포지에 있는 소리우스에게 가져가야 합니다.", description = "모... 모든... 모든 것이 함정이었습니다.\n\n날 용서...해 주십시오.\n\n우리... 우리를 위해... 소리우스를 위해... 놈을 처치해 주십시오.", progress = "믿을 수가 없어! 증거를 보여 주시오!", completion = "&lt;얼굴이 창백해 지는 소리우스&gt;\n\n말... 말도 안 돼. 우리 형이 이 모든 함정을 판 거라고?\n\n&lt;분노로 얼굴이 일그러지는 소리우스.&gt;\n\n형이 날 배신했구나. 아이언포지를 배신했어! 이 땅에 고대 신들의 영향이 아직도 깊이 남아 있는 것 같소. 한때 고귀하고 명예로운 드워프였던 우리 형이 그토록 쉽게 라그나로스의 뜻을 받들도록 변했다면 안전할 자가 아무도 없소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n백인대장 다리보호구로드렉 투구인내의 반지\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3567] = {title = "높은 곳", objective = "쌍둥이 바위산 꼭대기에서 경치 구경 좀 하시겠어요? 제가 보내 드릴 수 있답니다.\n\n다만 어떻게 내려올지는 잘 생각해 두세요. 올려드릴 수만 있거든요.", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n쌍둥이 바위산으로 순간이동"},
[3568] = {title = "스며드는 타락", objective = "아즈샤라에 있는 엘다라스 폐허의 해변을 따라 가면서 4개의 빈 약병에 해일의 구덩이의 물을 모두 채운 후, 연금술사 큘리에게 돌아가야 합니다.", description = "내 뒤에 금방이라도 쓰러질 듯한 모습의 타우렌이 보이시오? 최근에 아즈샤라에 다녀왔다고 하는데, 엘다라스 폐허를 지나는 길에 나가에게 부상을 당했다고 하는군.\n\n나가를 몇 마리 처치한 후에 해변에 앉아 쉬면서 해일의 웅덩이의 물을 마신 모양인데... 구토가 나고 다른 증상도 보인다는군.\n\n저 타우렌이 뭘 마신 것인지 알고 싶으니 이 상자를 가져가서 약병에 붙여놓은 이름표를 보고 각각 웅덩이에서 물을 채워오시오.", progress = "이제 어떻게 될지 알겠소? 저 타우렌은 살아날 가망이 없소... 보시오. 이제 그녀가 해줄 수 있는 일은 이 질병의 치료제를 찾을 수 있도록 우릴 도와주는 것뿐이지. 그녀가 마신 이 물에 치료제를 찾을 수 있는 단서가 들어있을지도 모르오. 어차피 죽을 거라면 우리 종족을 위해 숭고한 일을 하고 죽는 편이 낫지 않겠소?", completion = "저 타우렌이 죽기 전에 돌아와서 정말 다행이야. 정말 잘 됐어. 그럼 작업을 시작합시다.\n\n지금까지 저 타우렌의 증상을 쭉 연구하고 있었는데 어찌나 심각한지 아직까지 두 발로 설 수 있다는 사실이 놀라울 뿐이오. 게다가 여기저기 서너 차례 구토를 해놓았는데, 냄새가 상당하더군.\n\n이제 우리... 타우렌 친구에게 시험할 약을 만들 테니 잠시만 기다리시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3569] = {title = "스며드는 타락", objective = "언더시티에 있는 테레사 윈드송에게 큘리의 비약을 줘야 합니다.", description = "이걸 테레사에게 줘보시오. 어쩌면 병이 나을 수도 있고... 어쩌면 낫지 않을 수도 있소. 테레사가 이 약을 마셔봐야 알 수 있을 거요.", progress = "제가 언더시티에 오게 된 것은 이곳의 연금술사들이 자신들의 질병을 치유할 방법을 찾기 위해 오랫동안 연구해 왔다는 얘기를 들어서랍니다. 어쩌면 제 병을 고칠 수도 있을지 모른다는 얘기를 들었죠.\n\n이곳에서 환영받지 못하는 것 같긴 하지만 달리 어쩔 수가 없었어요. 이번에 걸린 병이 속을 찢어놓는 것만 같아 한 시라도 빨리 도움이 필요했거든요.", completion = "연금술사 큘리는 마음씨가 아주 좋군요... 사실 좀 불안하리만큼 좋아요. 하지만 이 비약이 도움이 될 거라고 했다면 어쩔 수가 없겠군요. 다른 해결책을 찾아볼 시간도 없고 말이죠. 사제나 주술사 친구들에게는 벌써 다 얘기해봤지만 어느 누구도 도움을 주진 못했습니다.\n\n대지모신이 제 영혼을 굽어 살피시기를 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3570] = {title = "스며드는 타락", objective = "비약이 저렇게 잘 들을 줄은 꿈에도 생각하지 못했군. 고맙소이다. 나머지 견본들도 즉시 작업에 착수해야겠소. 곧 실바나스 여왕님과 포세이큰이 사용할 수 있을 거요.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3601] = {title = "킴야엘", objective = "탈라시안 주둔지에서 킴야엘의 나침반, 망원경, 박제한 닭, 그리고 땅콩까개를 찾은 후, 아즈샤라에 있는 킴야엘에게 돌려주어야 합니다.", description = "블러드 엘프들이 이 킴야엘을 어떻게 생각하는지 아시오? 겨우 쥐새끼 정도로 생각하지. 덩치만 커다란 깡패들 같으니라고!\n\n놈들은 나를 고용해서 무슨 잃어버린 \"보물\"을 찾아 지역을 정찰하는 일을 도와 달라고 했소. 나야 물론 보물에다 넉넉한 보수 얘기에 귀가 솔깃해 뛰어들었지만, 녀석들은 날 배신하고 죽이려고 했지. 감히 이 킴야엘을!\n\n이건 정말 블러드 엘프란 못 믿을 족속이라는 걸 단적으로 보여 주는 거요.\n\n그런데 문제는, 녀석들이 아직도 내 장비들을 가지고 있는데 나 혼자서는 그걸 되찾아올 수가 없다는 거요. 날 좀 도와 주지 않겠소?", progress = "돼 먹지 못한 블러드 엘프 놈들 같으니. 내가 당신만큼 강했어도 지금 당장 달려가서 톡톡히 본때를 보여 줬을 거요! 하지만 당신에게 대신 처리해 달라고 하는 수밖엔 없겠네요.", completion = "하하! 아주 혼쭐을 내준 모양이군!\n\n좋아 죽겠는걸! 블러드 엘프 녀석들, 동업자를 배신한 대가가 어떤 건지 아주 잘 알았겠지... 고블린 상인처럼 충직한 친구를 배신하다니! 흥, 망할 블러드 엘프 녀석들...!\n\n참, 당신한테는 최소한 시간을 뺏은 것에 대한 보상 정도는 해야지. 내가 처음부터 약속했듯이 말이오.\n\n자, 받으시오. 꽤 유용할 거요.", rewards = "다음과 같은 것들을 받습니다:\n\nM73 수류탄"},
[3602] = {title = "아즈샤리트", objective = "아즈샤라 남부 지역에서 결정화된 아즈샤리트 20개를 회수해야 합니다. 교묘하게 숨겨져 있는 아즈샤리트의 위치는 지옥사냥개에게 냄새를 맡게 해서 찾을 수 있습니다.", description = "아즈샤라 남부 지역의 고대 절벽거인은 그 지역의 바위와 건물들을 먹고살지. 그 절벽거인의 배설물을 아즈샤리트라고 하는데, 굉장히 튼튼하면서도 아주 유연한 수정이라네.\n\n남부에 있는 반도에는 아즈샤리트가 널려있지만 절벽거인들이 워낙 난폭한지라 회수하기가 무척 힘들지.\n\n자네가 남쪽으로 가서 무기에 쓸 아즈샤리트를 충분히 구해오게. 내 지옥사냥개들이 수정을 회수하는 걸 도와줄 걸세.", progress = "악이란 결코 잠들지 않는 법일세. 죽으면 얼마든지 쉴 수 있을 테니까 지금은 그 수정이나 구해오게.", completion = "아즈샤라에서 자네의 할 일은 끝났네. 나는 이제부터 자네의 모험에 필요한 물건들을 제작해야겠네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3621] = {title = "퇴마 무기 제작", objective = "가시덤불 골짜기에 있는 갈반에게 상자를 가져가야 합니다.", description = "무기를 만들 준비가 다 됐네. 이제 담금질한 아즈샤리트를 가지고 악마의 힘을 다스릴 수 있는 자를 찾아가야 하네.\n\n가시덤불 골짜기에 그런 일을 할 수 있는 대장장이가 하나 살고 있네. 미스릴 대장조합의 지도자인 전설의 대장장이 갈반이 자네의 요구대로 무기를 제작해 줄 것이네. 그자의 야영지는 줄구룹과 모쉬오그 오우거 소굴 사이에 있네.\n\n자네의 결의와 의지로 이 고난을 헤쳐나갈 수 있기를 바라네. 설사 실패한다 해도 여신께서는 미소를 지어줄 것이라는 점을 잊지 말게.", progress = "로라무스라고 했나? 오랜만에 듣는 이름이군그래.", completion = "맙소사. 이 재료들을 구하느라 얼마나 고생했을지 알 만하네. 아즈샤라에 들어갔다가 살아나오는 자는 거의 없는 것으로 알고 있지. 거인들과 반은 신과 같은 존재들과 대적하는 게 얼마나 힘들지는 두말 안 해도 알고말고!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3625] = {title = "마력이 깃든 아즈샤리트 퇴마 무기", objective = "갈반이 무기를 다 만들 때까지 기다려야 합니다.", description = "무기 하나하나를 만드는 데 시간이 좀 걸릴 거야.\n\n게다가 퇴마 저주의 힘은 3분에 한 번씩밖에 사용할 수 없지. 파멸자 라젤리크와 그의 부하들을 약하게 만드는 능력은 지속 시간이 일정하지 않고 말이야. 그렇기 때문에 기회다 싶으면 즉시 사용해야 하네!\n\n무기를 만드는 동안 잠시만 기다려 주게.", progress = "무기를 제작하는 동안 방해를 받으면 상태가 불량한 무기가 나올 수도 있네. 급한 건 알지만 참고 기다리게.", completion = "&lt;이마의 땀을 닦으며&gt;\n\n이보다 훌륭한 퇴마 무기는 일찍이 존재하지 않았을 거야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n마력이 깃든 아즈샤리트 퇴마단검마력이 깃든 아즈샤리트 퇴마지팡이마력이 깃든 아즈샤리트 퇴마검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3626] = {title = "저주받은 땅으로의 귀환", objective = "호드 영웅의 넋에게 돌아가야 합니다.", description = "구원의 시간이 가까워졌네, <name>. 새 무기를 들고 저주받은 땅으로 돌아가 호드 영웅의 넋에게 최후의 지시를 받도록 하게.", progress = nil, completion = "전투력이 더욱 강해진 것 같소, &lt;name&gt;. 라젤리크와 그의 심복들에게 맞설 준비는 되었소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3627] = {title = "조각난 아뮬렛 재결합", objective = "파괴자 그롤, 여군주 세바인, 대마법사 알리스타즈를 해치우고 그들의 시체에서 그롤의 아뮬렛, 세바인의 아뮬렛, 알리스타즈의 아뮬렛을 회수해야 합니다.\n\n마력이 깃든 아즈샤리트 퇴마 무기를 사용하여 3인조의 힘을 약화시켜야 그들을 처치할 수 있다는 것을 명심하십시오. 반드시 현명하게 사용해야 합니다.", description = "파멸자 라젤리크에게 맞서려면 먼저 그의 심복 3인조부터 처치한 다음 그들이 지닌 아뮬렛 조각을 회수해야 하오. 세 개의 조각을 전부 모으면 내게 돌아오시오. 그러면 다음 지시를 주겠소.\n\n가시오, <name>! 저주받은 땅으로! 세바인과 알리스타즈, 그리고 그롤을 모두 쓰러뜨려야 하오!", progress = "셋이 모여 하나가 되고 그 하나가 길을 밝히리니.", completion = "파멸자 라젤리크의 아뮬렛이 다시 결합했지만 그가 자신의 지배 체계에 문제가 생긴 것을 느끼고 있다오. 바로 당신이 자신을 처치하러 온다는 것을 알고 있소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3628] = {title = "악마 라크리크와의 대결", objective = "파멸자 라젤리크를 해치우고 파멸자의 부러진 뿔을 호드 영웅의 넋에게 가져가야 합니다. 파멸자의 수호물도 호드 영웅의 넋에게 돌려주어 파괴하도록 해야 합니다. 그래야 사악한 자들의 손에 들어가는 것을 막을 수 있습니다.", description = "라젤리크의 소굴은 저주받은 땅에서 가장 높은 산꼭대기에 있소. 그 소굴로 가는 유일한 방법은 산 근처에 있는 순간이동 룬을 이용하는 것이오. 아뮬렛을 지니고 있으면 그 소굴에 자유롭게 드나들 수 있을 거요. 소굴에 들어서면 그 괴물을 불러내야 하오. 이 아뮬렛이 그 열쇠요. 파멸자의 제단에서 사용하도록 하시오.\n\n파멸자 라젤리크를 물리치면 그의 뿔을 가져오시오. 라젤리크의 뿔은 모든 이들에게 희망의 상징은 물론, 전쟁으로 상처받은 이 세계에 아직도 영웅이 존재한다는 증거가 될 것이오.", progress = "... 더 이상 두려워할 것이 뭐가 남아 있겠소.", completion = "오늘은 영원히 기억해야 할 날이오. 저주받은 땅에서 마침내 악마의 대군주가 쓰러졌으니까 말이오!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n성역의 목걸이악마의 피악마 가죽 배낭"},
[3629] = {title = "고블린 기계공학", objective = "고블린 기계공학에 대해 더 알고 싶으면 가젯잔에 있는 닉스 스프로켓스프링에게 기계공학 설명서를 가져가야 합니다.", description = "고급 기계공학은 노움과 고블린의 뚜렷한 두 가지 분야로 분류되오. 나는 공정한 전문 기술자이니 고블린 기계공학에 대해서만 언급하도록 하겠어요. 고블린들은 뭐든지 폭발시키기를 좋아하는데, 중간에 어떤 장애물이 있든 아랑곳하지 않죠. 설사 그 장애물이 자기 자신들이라 하더라도 말이죠!\n\n자, 이 설명서를 읽어 보세요. 폭발 기술을 배우고 싶거든 가젯잔에 있는 닉스 스프로켓스프링에게 이 설명서를 가져가세요. 회원 가입은 영구적이며 다른 학문을 배우지 못하게 한다는 사실을 명심하도록 하시고요. 그러니까 그가 주는 임무를 완료하기 전에 이것이 정말 당신이 원하는 것인지 확실히 결정하도록 하세요!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3630] = {title = "노움 기계공학", objective = "노움 기계공학에 대해 더 배우고자 한다면 아이언포지에 있는 수석땜장이 오버스파크에게 기계공학 설명서를 가져가야 합니다.", description = "고급 기계공학은 두 가지 학문으로 분류된답니다. 바로 노움기계공학과 고블린 기계공학인데, 물론 이 둘 중에서도 노움기계공학이 훨씬 더 우수하죠! 삶을 더 편리하게 하는 멋진 도구와 장치를 만드니까 말이죠!\n\n이 설명서를 읽어 보세요. 노움 기계공학에 대해 더 배우고 싶거든 이 설명서를 아이언포지에 있는 수석땜장이 오버스파크님께 가져다주세요. 아, 회원 가입은 영구적이며 다른 학문을 배우지 못하게 한다는 사실을 명심하세요. 그러니까 그분이 주는 임무를 완료하기 전에 확실한 마음의 결정을 내리도록 하세요!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3631] = {title = "지옥마 소환", objective = "불모의 땅에 있는 스트라드 파선과 대화하십시오.", description = "흥. 내가 보기에 당신은 아직 준비가 덜 된 것 같은데 그건 내가 판단할 일이 아니지. 스트라드의 생각은 다른가 보니까. 게다가 이건 그가 내릴 결정이고... 적어도 이번에는 말이야.\n\n스트라드는 하루 빨리 당신과 얘기를 나누고 싶어하지. 그는 아직 불모의 땅, 톱니항에 있는 작은 탑에 수행 사제들과 함께 있소.\n\n여기서 지체하지 말고 어서 가보시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3632] = {title = "노움 기계공학", objective = "노움 기계공학에 대해 더 알고 싶으면 아이언포지에 있는 수석땜장이 오버스파크에게 기계공학 설명서를 가져가야 합니다.", description = "고급 기계공학은 두 가지로 분류되오. 바로 노움기계공학과 고블린 기계공학인데, 물론 이 둘 중에서도 노움기계공학이 훨씬 더 우수하죠! 삶을 더 편리하게 하는 멋진 도구와 장치를 만드니까 말이죠!\n\n이 설명서를 읽어 보세요. 노움 기계공학에 대해 더 배우고 싶거든 이 설명서를 이곳 아이언포지에 있는 수석땜장이 오버스파크님께 가져다주세요. 아, 회원 가입은 영구적이며 다른 학문을 배우지 못하게 한다는 사실을 명심하세요. 그러니까 그분이 주는 임무를 완료하기 전에 확실한 마음의 결정을 내리도록 하세요!", progress = "그래, 그래. 오늘은 내가 뭘 도와주면 좋겠소? 내가 하는 일이라곤 우리가 사랑하던 도시가 방사선 구름에 뒤덮여 죽어 가는 동안 여기서 서성대는 것뿐이니 말이오.", completion = "아, 젊은 기술자가 유일하게 진정한 기계공학을 추구하려고 결정을 내렸군! 너무 감상적으로 나와서 미안하오, 친구. 우리 상황이 절박하긴 해도 진정한 기계공학의 톱니 굴러가는 소리에 응하는 또 다른 기술자를 보는 것은 언제나 아주 기쁜 일이라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3633] = {title = "고블린 기계공학", objective = "고블린 기계공학에 대해 더 알고 싶으면 가젯잔에 있는 닉스 스프로켓스프링에게 기계공학 설명서를 가져가야 합니다.", description = "고급 기계공학은 두 가지 갈래로 분류되오. 바로 노움 기계공학과 고블린 기계공학이지. 단연코, 뛰어난 기술자라면 누구나 고블린 기계공학을 선택하지. 대단한 화력의 폭발물과 뛰어난 장비를 사용해서 세계를 완전히 장악할 수 있다오!\n\n이 설명서를 읽어 보시오. 고블린 기계공학을 배우고 싶거든 가젯잔에 있는 닉스 스프로켓스프링에게 이 설명서를 가져가시오. 명심하시오. 회원 가입은 영구적이고 일단 가입하면 다른 기계공학은 배우지 못하게 된다는 사실을. 그러니까 그가 주는 임무를 완료하기 전에 이것이 정말 당신이 원하는 것인지 확실히 판단하도록 하시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3634] = {title = "노움 기계공학", objective = "노움 기계공학에 대해 더 알고 싶으면 아이언포지에 있는 수석땜장이 오버스파크에게 기계공학 설명서를 가져가야 합니다.", description = "고급 기계공학은 두 가지 갈래로 분류되오. 바로 노움 기계공학과 고블린 기계공학이지. 노움 전문 기술은 배워 봐야 아무 소용 없지만 그래도 알아 두기는 해야 할 거요. 그들은 세계의 혁신을 불러올 각종 물건과 장치들을 만들어 낸다고 하지만, 제대로 작동하는 일은 별로 없지.\n\n이 설명서를 읽어 보시오. 금속 장비들을 만드는 방법을 배우고 싶거든 그 설명서를 아이언포지에 있는 수석땜장이 오버스파크에게 가져가시오. 명심하시오. 회원 가입은 영구적이고 일단 가입하면 다른 갈래의 기계공학은 배우지 못하게 된다는 사실을! 그러니까 그가 주는 임무를 완료하기 전에 확실한 마음의 결정을 내리도록 하시오!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3635] = {title = "노움 기계공학", objective = "노움 기계공학에 대해 더 알고 싶으면 무법항에 있는 오글소프 오브노티쿠스에게 기계공학 설명서를 가져가야 합니다.", description = "고급 기계공학은 두 가지 갈래로 분류됩니다. 바로 노움 기계공학과 고블린 기계공학이지요. 개인적으로 노움 전문 기술은 배워 봐야 별 쓸모 없다고 생각하지만 그래도 알아 두기는 해야 할 거예요. 그들은 세계를 변화시킨다고 주장하는 각종 물건과 장치들을 만들어 내지만, 제대로 작동하는 일이 거의 없죠.\n\n이 설명서를 읽어 보세요. 금속 서진을 만드는 방법을 배우고 싶거든 그 설명서를 무법항에 있는 오글소프 오브노티쿠스에게 가져가세요. 회원 가입은 영구적이며 다른 학문을 배우지 못하게 한다는 사실을 명심하세요. 그러니까 그가 주는 임무를 완료하기 전에 확실한 마음의 결정을 내리도록 하세요!", progress = "안녕하시오! 혹시 유도 로봇이 당신 집 벽을 뚫고 들어와 처박힌 일이 있었던 거라면 미리 내 변호사에게 그 일을 위임해 놓겠소. 엥? 그게 아니라면, 무슨 일로 왔소?", completion = "노움 기계공학을 배우러 왔단 말이오? 그렇다면 제대로 찾아온 거요. 놈리건의 통치 세력들은 지적으로 우수한 자들을 정치에 이용한 다음 추방할 수는 있어도, 지식 그 자체는 자신들이 제어할 수 없다는 사실을 알고 있소.\n\n내가 놈리건을 떠남으로써 그들은 현존하는 가장 위대한 노움 기술자 중 한 명을 잃은 거요. 이건 나뿐만 아니라 그들도 인정하는 사실이지. 당신의 이해력이 허락하는 한, 내가 알고 있는 모든 것을 가르쳐 주리다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3636] = {title = "빛의 힘", objective = "대주교 베네딕투스가 가시덩굴 구릉에 있는 혹한의 암네나르를 처치해달라고 부탁했습니다.", description = "스컬지가 얼라이언스를 끈질기게 위협하고 있다는 것은 <형제/자매>도 잘 알고 있는 얘기지. 그런데 최근 들어 우린 아주 이상한 것을 발견했다네.\n\n불모의 땅에는 가시덩굴 구릉이라는 무시무시한 가시덤불이 있지. 한때는 그저 가시멧돼지가 살던 곳이었네만 지금은 이 녀석들이 스컬지와 어떤 조약을 맺어선지 훨씬 더 흉측한 생물들을 만들어내고 있네... 녀석들은 이제 혹한의 암네나르라는 리치의 지배를 받고 있지.\n\n빛의 힘으로 이 사악한 무리를 처치해주게.", progress = nil, completion = "고맙네. 앞으로 스컬지 녀석들이 함부로 수를 늘리지 못할 걸세.\n\n빛의 은총이 함께하기를.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n정복자의 검적열의 부적"},
[3637] = {title = "노움 기계공학", objective = "노움 기계공학에 대해 더 알고 싶으면 무법항에 있는 오글소프 오브노티쿠스에게 기계공학 설명서를 가져가야 합니다.", description = "고급 기계공학은 두 가지 갈래로 분류되오. 바로 노움 기계공학과 고블린 기계공학이지. 노움 전문 기술은 배워 봐야 소용이 있을지는 잘 모르겠지만 그래도 알아 두기는 해야 할 거요. 노움들은 자신들이 발명한 각종 물건과 장치들이 세계를 변화시킨다고 주장하지만, 제대로 작동하는 일은 거의 없지.\n\n이 설명서를 읽어 보시오. 금속 장비들을 만드는 방법을 배우고 싶거든 그 설명서를 무법항에 있는 오글소프 오브노티쿠스에게 가져가시오. 명심하시오. 회원 가입은 영구적이고 일단 가입하면 다른 갈래의 기계공학은 배우지 못하게 된다는 사실을. 그러니까 그가 주는 임무를 완료하기 전에 확실한 마음의 결정을 내리도록 하시오!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3638] = {title = "비밀유지서약서", objective = "고블린 기술자가 되는 데 동의하면 닉스의 비밀유지서약서를 마우스 오른쪽 단추로 클릭한 후 가젯잔에 있는 닉스 스프로켓스프링과 대화해야 합니다.", description = "고블린 기계공학은 높은 수익과 더 큰 폭발력을 가져올 실용적인 기술이지! 우리 설계도에 나와있는 장치들을 이용하면 강력한 폭탄과 엄청난 무기들을 만들 수 있는데, 이 점에 대해서는 설명서에도 나와 있소.\n\n또한 설명서에는 우리 설계도의 비밀에 대한 아주 오래된 서약에 대해서 나와 있자. 한 번 고블린 기술자가 되면 그걸로 끝이오. 노움 기계공학에는 전혀 손을 댈 수 없게 되는 것이지.\n\n그래도 고블린 기술자가 되기를 원한다면 평생 동안 비밀을 지킬 것을 서약하는 이 문서에 서명한 후에 다시 나와 얘기하도록 합시다. 신중히 생각하도록 하라고.", progress = "문서에 서명을 하고 내게 건네줄 준비가 됐다면 그걸로 끝인 거요. 한 번 서명하면 한 길뿐이라는 건 이미 말해 줬소이다. 준비가 됐으면 고블린 기계공학의 배에 탑승하라고!", completion = "축하하오, 고블린 기술자 &lt;name&gt;! 당신은 곧 아제로스에서 가장 강력한 기계공학 설계도를 사용할 수 있게 될 거요.\n\n고블린 기계공학 지식을 추구하기로 결정을 내렸으니 이제는 고블린 지향 기계공학 작업을 조사할 때요. 이제부터는 우리가 당신의 고블린 기계공학 소질을 극대화시키기 위한 계획을 수립하는 것을 도와주도록 하겠소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3639] = {title = "직접 만든 물건", objective = "가젯잔에 있는 닉스 스프링스프로켓에게 대형 철제 폭탄 20개, 조밀한 다이너마이트 20개, 그리고 양 폭탄 5개를 가져가야 합니다.", description = "당신의 지도교사로서 당신이 만든 물건의 견본을 좀 보고 싶소. 당신은 두말할 나위 없이 솜씨 좋은 기술자이지만 나는 앞으로의 작업에 고블린 지향 기술을 강조할 방법을 찾기 위해 당신의 작품들을 분석하려는 거라오. 내게 대형 철제 폭탄 20개, 조밀한 다이너마이트 20개, 양 폭탄 5개를 가져오시오. 물론 안전 장치는 꼭 잠가야 하오!\n\n이 물건들을 내게 제출하면 당신에게 고블린 기술자 회원권을 발급해 주겠소. 모든 고블린 전문 기술자들과 만나려면 이 회원권이 반드시 필요하다오!", progress = "내가 검토할 수 있도록 당신이 만든 기계공학 물건들을 주면 당신에게 정품 고블린 기술자 회원권을 주겠소! 그 회원권이 유효 기간 동안은 아제로스 어디에서든 모든 고블린 전문 기술자를 무제한으로 만날 수 있소.", completion = "자, 여기 당신의 첫 번째 고블린 기술자 회원권이오!\n\n이 회원권은 회비를 선불로 내고 14일 동안 사용할 수 있소. 모든 회원권은 발급 받은 지 2주 후에 기간이 만료되는데, 만기가 되면 어떤 고블린 전문 기술자에게나 다음번 회비를 내고 새 회원권을 받도록 하시오. 회원권이 없으면 회원 자격이 일시 정지되어 새로운 설계도를 볼 수가 없소이다.\n\n회원 자격이 정지되어도 당신이 이미 알고 있는 것에는 아무런 영향을 주지 않소. 한번 고블린 기술자는 영원한 고블린 기술자니까 말이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n고블린 기계공학\n\n다음과 같은 것들을 받습니다:\n\n고블린 기술자 회원권"},
[3640] = {title = "비밀유지 서약서", objective = "노움 기술자가 되는 데 동의하면 비밀유지서약서를 마우스 오른쪽 단추로 클릭해 서명을 한 후 아이언포지의 수석땜장이 오버스파크와 다시 한번 대화하십시오.", description = "노움 기계공학은 모두의 삶에 필요한 모든 것들을 만들 수 있는 이론이라오! 설계도를 이용해, 세계를 제어할 수 있는 장치를 만들 수도 있는데, 이 점에 대해서는 당신에게 드리는 설명서에도 자세히 나와 있소이다.\n\n또한 그 설명서에는 우리 설계도의 비밀에 대한 아주 오래된 서약에 대해서도 나와 있소. 그러니까 한번 노움 기술자가 되면 그걸로 끝이오. 고블린 기계공학에는 전혀 손을 댈 수 없게 되지.\n\n그래도 노움 기술자가 되기를 원한다면 평생 동안 비밀을 지킬 것을 서약하는 이 문서에 서명한 후 다시 나와 얘기합시다. 신중히 생각하도록 하시오.", progress = "서약서에 서명을 하고 내게 건네주면 그걸로 끝이오.\n\n내가 당신에게 알려줄 비밀은 엄청나게 중요한 것이라서 이 비밀유지서약서라는 것은 매우 중요하오! 나도 서명을 했고 내 형제, 자매 기술자들도 다들 서명을 했소이다. 이걸로 당신은 앞으로 아주 전망 있는 단체에 속하게 되는 거요, 기술자 <name>!", completion = "노움 기술자가 된 것을 축하하오! 당신도 이제 아제로스에서 가장 우수한 기계공학 설계도를 사용할 수 있소.\n\n노움 기계공학을 선택하기로 결정을 내렸으니 이제는 노움 지향적인 작업을 연구할 때요. 이제부터 우리가 당신의 계획 수립을 도와 노움 기계공학 기술을 최고 수준으로 올려 놓고야 말겠소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3641] = {title = "직접 만든 물건", objective = "아이언포지에 있는 수석땜장이 오버스파크에게 미스릴관 6개, 정밀한 조준경 1개, 그리고 고급 표적 허수아비 2개를 가져가야 합니다.", description = "당신의 지도 교사로서 손수 만든 물건의 견본을 좀 보고 싶소. 당신이 솜씨 좋은 기술자라는 건 두말할 나위 없지만 작업을 분석해 앞으로 노움 지향 기술을 강조하기 위한 길을 찾으려는 것이라오. 내게 미스릴관 6개, 정밀한 조준경 1개, 고급 표적 허수아비 2개를 가져오시오.\n\n이 물건들을 내게 가져오면 당신에게 노움 기술자 회원권을 발급해 주도록 하겠소. 모든 노움 전문 기술자들과 만나려면 이 회원권이 꼭 필요하다오!", progress = "당신이 만든 기계공학 물건들을 검토할 수 있도록 나에게 주면 노움 기술자 회원권을 주겠소! 그 회원권의 유효 기간 동안 세계 어디에서든 모든 노움 전문 기술자를 무제한으로 만날 수 있소.", completion = "자, 여기 당신의 첫 번째 노움 기술자 회원권이오!\n\n이 회원권은 회비를 선불로 내고 14일 동안 사용할 수 있소. 발급 받은 지 2주 후에 기간이 만료되는데, 만기가 되면 아무 노움 전문 기술자에게 가서 회비를 내고 새 회원권을 발급 받도록 하시오. 회원권이 없으면 회원 자격이 일시 정지되어 새로운 설계도를 볼 수가 없소이다.\n\n회원 자격이 정지되어도 당신이 이미 알고 있는 것에는 아무런 영향을 주지 않소. 한번 노움 기술자는 영원한 노움 기술자니까!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n노움 기계공학\n\n다음과 같은 것들을 받습니다:\n\n노움 기술자 회원권"},
[3642] = {title = "비밀유지서약서", objective = "노움 기술자가 되는 데 동의하면 비밀유지서약서를 마우스 오른쪽 단추로 클릭한 후 무법항에 있는 오글소프 오브노티쿠스와 다시 한번 대화하십시오.", description = "우리의 기계공학은 노움 종족의 모든 요구를 충족시킬 수 있도록 잘 다듬어져 온 이론이오. 우리 설계도들을 이용하면 세계를 우리의 필요에 따라 제어할 수 있는 장치들을 만들 수 있는데, 이 점에 대해서는 당신이 읽은 설명서에도 나와 있소이다.\n\n그리고 한가지 서약에 대해서도 나와 있소. 설계도의 비밀에 대한 아주 오래된 약속이지. 그러니까... 한번 노움 기술자가 되면 그걸로 끝이오. 고블린 기계공학에는 손도 댈 수 없지.\n\n그래도 노움 기술자가 되기를 원한다면 평생 동안 비밀을 지킬 것을 서약하는 이 문서에 서명한 후에 다시 나와 얘기합시다. 신중히 생각하도록 하시오.", progress = "문서에 서명을 하고 내게 건네면 그걸로 끝이오.\n\n놈리건의 바보들, 특히 수석땜장이 오버스파크와는 정치적인 면에서 결코 동의할 수 없지만, 비밀유지서약서는 그 모든 것을 초월하오! 하나의 길을 선택하고 평생 그 길을 충실히 걸어나갈 것에 동의를 하는 것이오.", completion = "노움 기술자가 된 것을 축하하오! 당신도 이제 곧 아제로스 최고의 기계공학 설계도를 사용할 수 있게 될 거요.\n\n노움 기계공학을 배우기로 결정했으니 우선 당신이 알고 있는 노움 기계공학 지식으로 만든 물건을 좀 보도록 하겠소. 그런 다음 당신의 재능을 극대화시키기 위한 계획을 수립해야겠소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3643] = {title = "직접 만든 물건", objective = "무법항에 있는 오글소프 오브노티쿠스에게 미스릴관 6개, 정밀한 조준경 1개, 고급 표적 허수아비 2개를 가져가야 합니다.", description = "당신의 지도 교사로서 손수 만든 물건의 견본을 좀 보고 싶소. 당신이 지금도 솜씨 좋은 기술자라는 것은 두말할 나위 없지만, 작업을 분석해서 앞으로 당신의 기술에 노움만의 특성을 부여하는 길을 찾으려는 거요. 내게 미스릴관 6개, 정밀한 조준경 1개, 고급 표적 허수아비 2개를 가져오시오.\n\n이 물건들을 내게 제출하면 당신에게 노움 기술자 회원권을 발급해 주겠소. 노움 전문 기술자들과 만나려면 이 회원권이 꼭 필요하오.", progress = "내가 검토할 수 있도록, 당신이 만든 기계공학 물건들을 주면 당신에게 정품 노움 기술자 회원권을 주겠소! 그 회원권의 유효 기간 동안은 세계 어디에서든 노움 전문 기술자를 무제한으로 만날 수 있소.", completion = "자, 여기 당신의 첫 번째 노움 기술자 회원권이오!\n\n이 회원권은 회비를 선불로 내고 14일 동안 사용할 수 있소. 발급받은 지 2주 후에 만료되는 데, 만기가 되면 아무 노움 전문 기술자에게나 회비를 내고 새 회원권을 받을 수 있소. 회원권이 없으면 회원 자격이 일시 정지되어 새로운 설계도를 볼 수 없다오.\n\n하지만 당신이 이미 습득한 지식에는 아무런 영향을 주지 않소. 한번 노움 기술자는 영원한 노움 기술자니까!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n노움 기계공학\n\n다음과 같은 것들을 받습니다:\n\n노움 기술자 회원권"},
[3644] = {title = "회원권 갱신", objective = "회원권을 갱신하려면 갱신 비용으로 2골드를 내야 하오.", description = nil, progress = "회원권을 갱신하려면 갱신 비용으로 2골드를 내야 하오.", completion = "당신은 고블린 기계공학 기술자로 활동을 잘하고 있으니 내가 2골드에 만료된 회원권을 갱신해 주도록 하겠소. 비용을 내는 즉시 새로운 회원권을 발급 받게 될 거요. 그렇게 하면 전문 기술자들에게서 고블린 기계공학 설계도를 받을 수 있지.\n\n이 회원권은 2주간 유효하니 그 후에는 다시 회비를 내야 하오! 설계도를 보려면 먼저 회비를 내고 회원권을 갱신해야 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n고블린 기술자 회원권"},
[3645] = {title = "회원권 갱신", objective = "회원권을 갱신하려면 2골드를 갱신 비용으로 내야 합니다.", description = nil, progress = "회원권을 갱신하려면 2골드를 갱신 비용으로 내야 합니다.", completion = "&lt;race&gt; 기계공학 기술자로서의 자세가 됐으니 내가 2골드에 만료된 회원권을 갱신해 주도록 하겠소. 비용을 내는 즉시 새로운 회원권을 발급받게 될 거요. 그러면 전문 기술자들에게서 &lt;race&gt; 기계공학 설계도를 받을 수 있지.\n\n이 회원권은 2주 동안만 유효하니 그 후에는 다시 회비를 내야 하오! 설계도를 보려면 먼저 회비를 내고 회원권을 갱신해야 하니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n노움 기술자 회원권"},
[3646] = {title = "회원권 갱신", objective = nil, description = "[\n]다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n고블린 기술자 회원권"},
[3647] = {title = "회원권 갱신", objective = "회원권을 갱신하려면 2골드의 갱신 비용을 내야 합니다.", description = nil, progress = "회원권을 갱신하려면 2골드의 갱신 비용을 내야 합니다.", completion = "당신은 노움 기계공학 기술자로서 활동을 잘 하고 있으니 내가 2골드에 만료된 회원권을 갱신해 주도록 하겠소. 비용을 내는 즉시 새로운 회원권을 발급받게 될 거요. 이제 전문 기술자들에게서 노움 기계공학 설계도를 받을 수 있을 거야.\n\n이 회원권은 2주간 유효하니 그 후에는 다시 회비를 내야 할 거요! 설계도를 보려면 먼저 회비를 내고 회원권을 갱신해야 하니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n노움 기술자 회원권"},
[3661] = {title = "엘룬의 피조물", objective = "에렐라스 앰버스카이를 위해 동부 내륙지에서 올빼미야수 깃털 15개를 모아야 합니다.", description = "올빼미야수는 정말 예측할 수 없는 생물이오. 한없이 순하다가도 자신들이 중요하게 여기는 것이 위협을 받게 되면 극도로 포악해지거든.\n\n들리는 소문에 의하면 올빼미야수는 엘룬이 창조했다고 하오. 그게 사실인지 정말 궁금하오.\n\n동부 내륙지에 올빼미야수 무리가 서식한다는 소리를 최근에 들었는데 그들에 대해서 좀 더 알고 싶다오. 가서 올빼미야수 깃털 15개를 모아 내게 가져다주지 않겠소?", progress = "될 수 있으면 올빼미야수에 가까이 가지 마시오. 당신의 관심을 자신들을 해치려는 의도로 오해할 수 있으니까 말이오.", completion = "깃털을 가져와 줘서 고맙소.\n\n올빼미야수에 대해서는 뭘 좀 알아냈소?\n\n이 깃털을 조사하면 좀 더 많은 것을 알 수 있을 것이오. 천성이 포악한 괴물인지 아니면 단지 잘못 길들여진 탓인지... 꼭 진실을 알고 싶소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3681] = {title = "신앙의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화하십시오.", description = "길 가는데 방해해서 미안하오만, 스톰윈드에서 훈련을 받도록 성기사들을 소환하고 있다고 하던데, 혹시 알고 있어야 하지 않을까 싶어서 불렀소.\n\n내가 보기에 당신의 때가 무르익어 이제 신앙의 고서를 배우기 시작할 때가 된 것 같소이다.\n\n스톰윈드에서 계시는 두소리안 랄님을 찾아가 보시오. 그분은 보통 빛의 대성당에서 성기사들을 훈련하고 계시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3701] = {title = "불타는 타우릿산의 폐허", objective = "불타는 평원, 타우릿산의 폐허에 있는 타우릿산 유물에서 정보를 얻어야 합니다. 정보를 발견하면 왕실사학자 아케소누스에게 돌아가야 합니다.", description = "불타는 평원에 있는 타우릿산의 불타는 폐허로 가서 가능한 많은 정보를 수집해 오십시오.\n\n소문에 의하면 그곳에는 신비한 유물들이 널려 있다고 하니 수색해 보는 게 좋겠습니다. 그 폐허를 지키고 있는 타우릿산의 수호병들을 조심하십시오. 아직 그곳에 묻혀 있는 모든 비밀을 보호하고 있는 암살자들이랍니다.", progress = nil, completion = "맙소사! 타우릿산이 품고 있는 많은 비밀들이 당신이 가져 온 정보로 설명이 되는군요.\n\n하지만 아직도 알아내야 할 게 무척 많습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n귀족의 반지"},
[3702] = {title = "불타는 타우릿산의 폐허", objective = "왕실사학자 아케소누스가 들려 주는 타우릿산의 역사를 들어야 합니다.", description = "검은무쇠단 드워프의 역사를 간단히 들어 보지 않으시겠습니까?", progress = "먼저 타우릿산의 이야기부터 들으시지요.", completion = "이제 당신이 할 일을 말씀드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3721] = {title = "선물로 받은 OOX", objective = "당신은 내 OOX 유도 로봇 세 개를 되찾아 주었소! 기대했던 것 이상으로 수고를 해 주었으니 특별한 사례를 하겠소이다. 당신과 정이 들게 된 바로 그 닭... 아니 로봇, OOX를 소형으로 만들어 주리다!\n\n아무에게도 이렇게 치명적인 잠재력을 지닌 물건을 내준 적이 없지만 당신은 정말 큰 도움을 주었으니 예외로 하지. 게다가 이 축소판에는 전투 기능과 유도 기능이 해제되어 있고 말이야.\n\n그 외에는 모두 OOX 시리즈 로봇의 기능과 똑같소!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n기계닭"},
[3741] = {title = "힐러리의 목걸이", objective = "힐러리의 목걸이를 찾아 레이크샤이어에 있는 힐러리에게 가져가야 합니다.", description = "제 친구 힐러리가 목걸이를 잃어버렸는데 찾을 수가 없어요. 여기서 하루종일 낚시도 해 보고 벌써 이 주변도 샅샅이 찾아보았거든요. 어쩌면 호수에 빠졌을지도 몰라요. 그런데 엄마 아빠가 호수에서 헤엄치지 말래요... 물 밑에 나쁜 괴물들이 산다고 엄마가 그러셨어요. 그렇지만 <name>님은 그런 나쁜 괴물들이 겁나지 않죠?\n\n제발 목걸이를 찾아 주시겠어요?", progress = "안녕하세요. 제 목걸이를 다시 찾고 싶어요. 아빠가 사 주신 건데, 호수에는 나쁜 괴물들이 산다고 하셨어요. 괴물들을 혼내 주셨나요?", completion = "목걸이를 찾아 주셔서 고맙습니다, &lt;class&gt;님... 정말 친절하세요! 제 고양이도 고맙대요. 그치, 나비야?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3761] = {title = "운고로 토양", objective = "썬더 블러프에 장로의 봉우리 있는 게드에게 운고로 토양 20개를 가져가야 합니다.", description = "보고된 바에 의하면 운고로 분화구의 토양에는 마법 성질이 풍부하다고 하네. 세나리온 의회에서는 이 토양을 대량 가져와 조사하려 하고 있지. 우리가 계속 조사를 할 수 있도록 운고로의 황야로 가서 토양을 좀 가져와 주게나.\n\n그 비옥한 토양은 더미로 불쑥 튀어나오는 경우도 있고, 몇몇 짐승들에게 쓸만한 견본이 있을 수도 있네. 그것들을 모두 밖에 있는 게드에게 가져가게. 흙더미를 옆에 두고 큰소리로 명령을 내리는 타우렌을 찾아보게나. 그렇게 소리를 지르는 게 듣기 싫겠지만 그를 화나게는 하지 말게!", progress = "편히 쉬시오. 운고로의 토양을 내려놓으러 온 거라면 잘 왔소! 아니면 썩 물러가시오.", completion = "아, 그거야. 참, 일부러 이 흙더미 위에 퍼올리는 걸 도와줄 생각은 말라고! 고대의 영혼들께서 진정 원하시는 일이라면 기적적으로 퍼올려질 테니까 말이지.\n\n대&lt;class&gt; 룬토템님께서 당신과 다시 얘기하고 싶어하시오. 하지만 다음 임무를 수행하려면 적어도 중급 정도의 약초학 지식은 갖추고 있는 게 좋을 거야. 혹시 그게 아니더라도 당신이 대&lt;class&gt;님께 전혀 쓸모 없는 친구는 아닐테니 어서 가보라고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3762] = {title = "대드루이드 룬토템 돕기", objective = "썬더 블러프에 있는 대드루이드 하뮬 룬토템과 대화해야 합니다.", description = "실례하겠습니다. 괜찮으시다면 잠시만 시간을 내주시겠습니까?\n\n썬더 블러프의 세나리온 의회에서는 아주 중요한 조사 작업 때문에 당신처럼 노련한 모험가에게 큰 관심을 가지고 있습니다. 전 자세한 내용은 모르지만 이 연구 조사를 다름 아닌 하뮬 룬토템님께서 직접 지휘하고 있다는 것만은 말씀드릴 수 있습니다.\n\n혹시 관심이 있으시다면 썬더 블러프 내에 있는 장로의 봉우리에서 그분과 직접 얘기를 나눠 보십시오.", progress = nil, completion = "어서 오게. 우리 연구를 돕는 데 관심을 가져 줘서 기쁘군. 할 일이 많다네. 별로 위험하지 않은 일이라고 하면 거짓말이 될 테고... 그대가 겁부터 먹고 도망가지는 않았으면 좋겠군. 하지만 그대의 모습을 보아하니 이 정도 일쯤은 많이 해봤을 것 같군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3763] = {title = "대드루이드 스테그헬름 돕기", objective = "다르나서스에 있는 대드루이드 판드랄 스테그헬름과 대화하십시오.", description = "실례하겠습니다. 괜찮으시다면 잠시만 시간을 내 주시겠습니까?\n\n다르나서스의 세나리온 의회에서 아주 중요한 조사 작업 때문에 당신처럼 노련한 모험가들을 찾고 있습니다. 자세한 내용은 모르지만 이 연구 조사를 다름 아닌 대드루이드 판드랄 스테그헬름께서 직접 지휘하고 있다는 것만은 말씀드릴 수 있습니다.\n\n혹시 관심이 있으시다면 다르나서스 내에 있는 세나리온 자치령에서 그분과 직접 얘기를 나눠 보십시오.", progress = nil, completion = "아, &lt;class&gt; 친구... 내가 이 연구 조사를 지휘하고 있다는 소식을 듣고 재빨리 달려온 것이 분명하군.\n\n여기까지 왔으니 내가 하는 얘기를 한번에 잘 새겨 들으시오. 같은 말을 여러 번 하고 싶진 않으니.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3764] = {title = "운고로 흙", objective = "다르나서스의 세나리온 자치령에 있는 제날에게 운고로 토양 20개를 가져가야 합니다.", description = "보고에 의하면 운고로 분화구의 흙에는 강력한 마법 성분이 풍부하다고 하오. 뭐가 진실이고, 뭐가 거짓인지 확실히 파악하고 싶으니 우리가 조사를 할 수 있도록 운고로의 황야로 가서 질 좋은 토양 견본을 좀 가져다 주시오.\n\n수집 임무 따위를 맡기에는 자신의 힘이 아깝다고 생각할진 모르지만, 그런 자세로는 나를 비롯한 세나리온 의회의 신임을 얻지 못할 거요. 견본을 제날에게 가져다주도록 하시오. 제날은 이 나무 뒤에서 얼쩡대고 있을 게 분명하오. 흙더미를 파면서 말이지... 당신이 흙을 가져오면 처리는 그가 알아서 할 거요.", progress = "아, 흙 얘기로군. 대드루이드님께선 모험가가 올 때마다 토양 견본 20개를 원하시니 당신 역시 20개를 가져와야 하오. 우리를 해치려고 음모를 꾸미는 자들은 돌부리에나 걸려 넘어져라!", completion = "그 짐은 여기에 내려놓으시오, 고귀한 &lt;class&gt; 양반... 상당히 무거웠을 텐데... 내가 몽상가로서 지고 있는 짐과 별다를 바는 없소만... 참, 이건 대드루이드께서 하사하라고 직접 내리신 사례금이오.\n\n대드루이드 스테그헬름께서 당신과 다시 얘기하고 싶어하시오. 그런데 그분께서 맡길 다음 임무를 수행하려면 적어도 중급 이상의 약초학 지식은 갖추는 게 좋을 거요. 하지만, 혹시 실력이 부족하더라도 세나리온 의회에 도움이 될 다른 방도는 있을 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3765] = {title = "먼 곳에 퍼진 타락", objective = "아우버다인에 있는 게르샬라 나이트위스퍼를 찾아가야 합니다.", description = "스톰윈드라... 아주 북적대는 도시로군.\n\n난 저 먼 칼림도어에서 도움을 청하러 왔소이다. 이 도시의 거리에는 용감한 모험가들이 자주 다닌다는 소식을 들어서 말이오.\n\n어둠의 해안에서 내 형, 게르샬라가 도움을 필요로 하고 있소. 우리 형은 해안 마을 아우버다인에서 살고 있소이다.\n\n아주 기나긴 여정이 될 것이기에 그대처럼 노련한 <class>에게 도움을 청하는 것이오.", progress = nil, completion = "아, 내 동생 아르고스가 보낸 거요? 먼길을 오느라 많이 피곤할 테지만 할 얘기가 무척이나 많소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3781] = {title = "여명초 연구", objective = "다르나서스의 세나리온 자치령에 있는 마스렌길 베어워커에게 대드루이드의 씨앗 교환권을 가져가야 합니다.", description = "우리는 늘푸른 주머니라는 곳에 운고로 분화구에서 가져온 흙을 넣고 탈렌드리스 씨앗을 재배하고 있소. 이 씨앗에서는 여러 가지 강한 약초가 무작위로 싹을 틔우는데, 여명초는 그 중 하나요. 지금까지 거의 알려진 바가 없는 수수께끼의 약초인데, 내가 이 수수께끼를 풀고자 하외다.\n\n이걸 아래층에 있는 마스렌길에게 가져가면 그 친구가 씨앗을 좀 줄 거요. 씨앗이 다 떨어지면 그에게서 추가로 더 구입하면 되오.", progress = "평화와 고요함이 당신과 함께하기를 바랍니다, 친구여. 대드루이드께서 직접 보내서 온 거요?", completion = "그래, 이 교환권이라면 씨앗 꾸러미를 20개 내줄 수 있겠군요. 그대에게 씨앗이 다 떨어졌을 때도 더 내줄 수는 있지만, 유감스럽게도 탈렌드리스 씨앗은 대량 생산하기에는 너무 값이 비싸요. 그래서 세나리온 의회에서는 우리를 돕는 모험가들이 약간의 비용을 내주기를 바라는 것입니다.\n\n여명초를 가지고 돌아간다면 대드루이드께서 제공하는 보상이 그 비용보다 훨씬 더 크다는 것을 알게 될 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n탈렌드리스 씨앗 꾸러미"},
[3782] = {title = "여명초 연구", objective = "썬더 블러프에 있는 바샤나 룬토템에게 씨앗 교환권을 가져가야 합니다.", description = "우리는 늘푸른 주머니라는 곳에 운고로 분화구에서 가져온 흙을 넣고 탈렌드리스 씨앗을 재배하고 있다네. 이 씨앗들은 무작위로 여러 가지 강한 약초로 꽃을 피우는데, 여명초는 그 꽃 중 하나지. 여명초는 거의 알려진 바가 없는 수수께끼의 약초인데, 바로 이 수수께끼를 풀고자 한다네.\n\n이 교환권을 내 딸 바샤나에게 가져가면 그 애가 씨앗을 좀 줄 걸세. 씨앗이 다 떨어지면 그 애에게서 추가로 더 구입해야 할 거야.", progress = "평화가 그대와 함께하기를. 대드루이드님이 직접 보내셔서 여기 오신 건가요?", completion = "네. 이 교환권이라면 씨앗 꾸러미를 20봉 내드릴 수 있겠군요. 씨앗이 다 떨어졌을 때도 추가로 더 내줄 수는 있습니다만, 유감스럽게도 탈렌드리스 씨앗은 대량 생산하기에는 너무 값이 비싸거든요. 그래서 세나리온 의회에서는 우리를 돕는 모험가들 자신이 약간의 비용을 지급하기를 바라는 것이고요.\n\n하지만 여명초를 가지고 돌아간다면 대드루이드님이 제공하는 보상이 그 비용보다 훨씬 더 크다는 것을 알게 될 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n탈렌드리스 씨앗 꾸러미"},
[3783] = {title = "깜짝 기계설인 대작전", objective = "두꺼운 설인 모피 10개를 모아 눈망루 마을에 있는 우미 럼플스니커에게 갖다주어야 합니다.", description = "언제나 친구들이 먼저 기발한 아이디어를 생각해내곤 해서 저는 절대로 따라갈 수 없을 거라고 생각했거든요... 하지만 오늘은 달라요! 아주 멋진 계획을 짜냈거든요! 아무한테도 말하지 않겠다고 약속을 해주시면 그 비밀을 살짝 가르쳐 드릴게요...\n\n바로 기계설인을 만드는 거예요! 친구들이 보면 처음에는 무진장 겁을 먹게 될 테고, 기계라는 것을 알게 되면 아주 놀랄 거예요!\n\n먼저 얼음엉겅퀴설인에게서 두꺼운 설인 모피를 구해야 하는데, 도와주시겠어요? 남동쪽으로 가보면 설인들이 있답니다.", progress = "시작할 일거리가 많으니 되도록 서둘러서 모피를 갖고 오세요!", completion = "이 모피면 딱 되겠어요, &lt;name&gt;. 출발이 아주 좋은데요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3784] = {title = "대드루이드 룬토템 돕기", objective = "썬더 블러프에 있는 대드루이드 하뮬 룬토템과 대화해야 합니다.", description = "손님, 괜찮으시다면 잠시만 시간을 내주시겠습니까?\n\n썬더 블러프의 세나리온 의회에서는 아주 중요한 연구 작업에 당신처럼 노련한 모험가들을 찾고 있다고 합니다. 자세한 내용은 모르지만 이 연구 조사를 다름 아닌 하뮬 룬토템님께서 직접 지휘하고 있다는 것만은 말씀드릴 수 있습니다.\n\n혹시 관심이 있으시다면 썬더 블러프에 있는 장로의 봉우리에서 그분과 직접 얘기를 나눠 보십시오.", progress = nil, completion = "어서 오게. 우리 연구를 돕는 데 관심을 가져 줘서 기쁘군. 할 일이 많다네. 별로 위험하지 않은 일이라고 하면 거짓말이 될 테고... 자네가 겁부터 먹고 도망가지는 않았으면 좋겠군. 하지만 그대의 모습을 보아하니 이 정도 일쯤은 많이 해봤을 것 같군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3785] = {title = "여명초 연구", objective = "탈렌드리스 씨앗 꾸러미와 늘푸른 주머니를 운고로 토양 2개에 사용하여 여명초 견본을 재배하십시오.\n\n다르나서스에 있는 마스렌길 베어워커에게 여명초 10개를 가져가야 합니다.", description = "탈렌드리스 씨앗을 배양할 때 이 늘푸른 주머니가 필요할 것이오. 그리고 거름으로 쓸 운고로 토양도 필요하게 될 거요. 필요한 물건을 다 마련했거든 주머니를 사용해 보시오. 나머지는 이 주머니가 다 알아서 할 테니...\n\n여명초를 충분히 구하거든 이곳 세나리온 자치령에 있는 내게 가져오시오. 대드루이드님은 워낙 바쁘시니까 그분을 귀찮게 하지 말고. 누가 여명초 한 묶음을 가져올 때마다 방해를 해서는 안 되지!", progress = "대드루이드님의 중요한 연구에 사용할 여명초는 재배했습니까? 그분이 세나리온 의회를 위해 하고 있는 이 연구는 아주 중요한 거예요. 그리고 그대의 도움을 쉽게 여기실 분은 절대 아닙니다!", completion = "수고했어요. 대드루이드님이 필요로 하실 때 내가 꼭 가져다 드리도록 하겠습니다. 그리고 세나리온 의회를 대신해 드리는 감사의 표시로 이걸 받아 두세요.\n\n여명초는 앞으로도 계속 필요한 것이니 계속 우릴 돕고 싶다면 여명초를 더 구해서 절 찾아오세요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 의회의 저장품"},
[3786] = {title = "여명초 연구", objective = "탈렌드리스 씨앗 꾸러미와 늘푸른 주머니를 운고로 토양 2개에 사용하여 여명초 견본을 재배하십시오.\n\n썬더 블러프에 있는 바샤나 룬토템에게 여명초 10개를 가져가야 합니다.", description = "여기 탈렌드리스 씨앗을 사용하는데 필요한 늘푸른 주머니가 있어요. 이 주머니뿐 아니라 이 씨앗에 줄 거름으로 쓸 운고로 토양 견본도 필요하게 될 거예요. 필요한 물건을 다 마련했거든 씨앗 꾸러미를 사용해 보세요. 나머지는 이 주머니가 다 알아서 할 거예요.\n\n여명초를 충분히 구하거든 이곳 장로의 봉우리로 절 다시 찾아오세요. 대드루이드님은 연구뿐 아니라 여러 근심거리들 때문에 워낙 바쁘시니까 그분을 귀찮게 하지 마시고요.", progress = "대드루이드님의 중요한 연구에 사용할 여명초는 좀 재배해 보셨나요? 도와주시는 덕분에 운고로 분화구의 신비한 마법 성질은 날이 갈수록 분명히 밝혀지고 있답니다.", completion = "수고하셨어요. 대드루이드님이 필요로 하실 때 제가 꼭 가져다 드리도록 하겠어요. 그리고 세나리온 의회에서 드리는 감사의 표시로 이걸 받아 주세요.\n\n여명초는 앞으로도 계속 필요한 것이니 계속 우릴 돕고 싶다면 여명초를 더 재배하여 절 다시 찾아오세요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 의회의 저장품"},
[3787] = {title = "존스피레의 요청", objective = "페더문 요새에 있는 쿠인티스 존스피레와 대화해야 합니다.", description = "실례합니다, 손님...\n\n제 동료 하나가 당신이 세나리온 의회와 함께 진행하고 있는 연구에 대해 당신과 얘기를 나누고 싶어한답니다. 쿠인티스 존스피레라는 이름의 드루이드인데 페더문 요새에서 지내고 있습니다. 그 친구는 여명초에 대해 당신과 의논하고 싶어하는데... 이 얘기는 대드루이드님의 귀에 들어가는 일이 없기를 바라고 있습니다.\n\n혹시 관심이 있다면 그 친구와 얘기해 보세요. 일단 얘기를 해 보면 틀림없이 모든 게 밝혀질 테니까 말입니다.", progress = nil, completion = "와줘서 고맙소이다, 여행자 친구! 내 소개를 하겠소. 나는 세나리온 의회와 말퓨리온님의 신하이자 드루이드인 쿠인티스 존스피레라 하오. 아마 우리, 샨드리스 페더문 장군님과 섭정에 대해 들어본 적이 있을 거요. 내 동료와 나는 그대가 다르나서스에서 판드랄 스테그헬름님과 함께 진행하고 있는 작업에 대해 그대와 얘기를 나누고자 하오.\n\n더 깊은 얘기를 하기 전에 우선 이 얘기는 우리끼리만 알고 있는 걸로 했으면 하오이다. 그대가 여기에 동의한다면 계속해서 얘기하도록 하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3788] = {title = "존스피레의 요청", objective = "페더문 요새에 있는 쿠인티스 존스피레와 대화하십시오.", description = "실례합니다, 손님...\n\n제 동료 하나가 당신이 세나리온 의회와 함께 진행하고 있는 연구에 대해 당신과 얘기를 나누고 싶어하십니다. 쿠인티스 존스피레라는 이름의 드루이드인데 페더문 요새에서 지내고 있습니다. 그 친구는 여명초에 대해 당신과 의논하고 싶어하는데... 이 얘기는 대드루이드님의 귀에 들어가는 일이 없기를 바라고 있습니다.\n\n혹시 관심이 있다면 그 친구와 얘기해 보십시오. 일단 얘기를 해 보면 틀림없이 모든 게 밝혀질 테니까 말입니다.", progress = nil, completion = "와 줘서 고맙소이다! 먼저 내 소개를 하겠소. 나는 세나리온 의회와 말퓨리온의 비천한 신하인 드루이드 쿠인티스 존스피레라 하오. 아마 그대도 내 동료들인 샨드리스 페더문 장군과 섭정들에 대해 들어 본 적 있을 거요. 우리는 그대가 다르나서스에서 판드랄 스테그헬름을 위해 수행하고 있는 작업에 대해 얘기를 나누고 싶소.\n\n얘기를 시작하기 전에 우선 이 얘기는 우리끼리만 알고 있는 걸로 합시다. 그대가 비밀을 지킬 수 있다면 계속해서 얘기하죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3789] = {title = "대드루이드 스테그헬름 돕기", objective = "다르나서스에 있는 대드루이드 판드랄 스테그헬름과 대화해야 합니다.", description = "실례하겠습니다, 손님. 괜찮으시다면 잠시만 시간을 내주시겠습니까?\n\n다르나서스의 세나리온 의회에 아주 중요한 연구 때문에 손님과 같이 노련한 모험가들을 찾고 있습니다. 자세한 내용은 모르지만 이 연구 조사를 다름 아닌 대드루이드 판드랄 스테그헬름님께서 직접 지휘하고 있다는 것만은 말씀드릴 수 있습니다.\n\n혹시 관심이 있으시다면 다르나서스 내에 있는 세나리온 자치령에서 그분과 직접 얘기를 나눠 보십시오.", progress = nil, completion = "아, 그대로군... 내가 이 연구 조사를 지휘하고 있다는 소식을 듣고 최대한 빨리 달려온 것이 분명하군그래.\n\n이제 여기 왔으니 내가 하는 자세한 얘기를 한 번에 잘 들어 보도록 하게. 같은 말을 반복하고 싶은 생각은 없으니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3790] = {title = "대드루이드 스테그헬름 돕기", objective = "다르나서스에 있는 대드루이드 판드랄 스테그헬름과 대화하십시오.", description = "손님. 괜찮으시다면 잠시만 시간을 내 주시겠습니까?\n\n다르나서스의 세나리온 의회에서 아주 중요한 조사 작업 때문에 손님과 같이 노련한 모험가들을 찾고 있습니다. 자세한 내용은 모르지만 이 조사를 다름 아닌 대드루이드 판드랄 스테그헬름께서 직접 지휘하고 있다는 것만은 분명히 말씀드릴 수 있습니다.\n\n혹시 관심이 있으시다면 다르나서스 내에 있는 세나리온 자치령에 계시는 그분과 직접 얘기를 나눠 보십시오.", progress = nil, completion = "아, 내가 이 조사를 지휘하고 있다는 소식을 듣고 최대한 빨리 달려온 것이 분명하군그래.\n\n이제 여기 왔으니 내가 하는 자세한 얘기를 잘 새겨 두도록 하게. 같은 말을 반복하고 싶은 생각은 없으니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3791] = {title = "여명초의 비밀", objective = "페더문 요새에 있는 쿠인티스 존스피레에게 여명초 10개를 가져가야 합니다.", description = "그렇다면 얘기를 해드리겠소. 솔직히 나는 다르나서스의 대드루이드들이 최근 보이는 움직임에 관심이... 아니 염려하고 있소. 그들은 세나리온 의회의 자원은 물론, 의회의 이름으로 어마어마한 양의 여명초를 확보하려고 하고 있소. 그 이유가 도대체 뭔지... 나도 연구를 하는 사람으로서... 그 중에서도 저주가 내 특기지. 여명초는 특정한 조건에서 원시적인 저주에 사용되는 약초 같은 성질을 띠는 것으로 알고 있소.\n\n이에 대해 더 연구하고 싶소. 그러자면 당신의 도움이 필요하오. 여명초 10개를 내게 가져오면 반드시 대가를 치르겠소.", progress = "여명초 10개가 필요하오. 그 정도면 적어도 연구를 시작할 수는 있을 거요. 분명 실패를 거듭하면서 여명초를 많이 태워 먹겠지만 연구란 본래 그런 것 아니겠소?", completion = "윽, 이 여명초는 기분을... 이상하게 만드는군. 도대체 스테그헬름이 이걸로 뭘 어쩔 속셈인지 알 수가 없군.\n\n어쨌든 도와줘서 고맙소. 작지만 이걸 받아 두시오. 이 여명초를 연구하는 데는 시간이 좀 걸릴 테고 분명 앞으로도 더 많은 여명초가 필요할 거요. 연구를 하는 김에 짬을 내서 여명초를 연금술용으로도 쓸 수 있는지 알아볼 수 있겠지만... 휴, 곁에 두고 있는 것만으로도 불쾌해지는군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n쿠인티스의 실험용 장갑껍질강철 어깨갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3792] = {title = "페더문 요새로 여명초 가져가기", objective = "또 보는군. 내 연구는 순조롭게 진행 중이오. 하지만 여명초 5개만 더 있다면 정말 기쁠 것 같소. 뭐, 기뻐한다는 건 일종의 은유적인 표현이지. 곁에 오래 두면 둘수록 기분이 더 언짢아져서 말이오. 하지만 꾹 참고 이 연구를 끝내야만 하오.", description = nil, progress = "또 보는군. 내 연구는 순조롭게 진행 중이오. 하지만 여명초 5개만 더 있다면 정말 기쁠 것 같소. 뭐, 기뻐한다는 건 일종의 은유적인 표현이지. 곁에 오래 두면 둘수록 기분이 더 언짢아져서 말이오. 하지만 꾹 참고 이 연구를 끝내야만 하오.", completion = "고맙소. 일단 이것들은 창고에 보관해야겠소. 내게 스테그헬름이 원하는 만큼의 자원은 없지만, 당신이 수고해준 데 대한 작은 사례 정도는 해줄 수 있소. 그런데 스테그헬름이 계속 여명초를 모아서 어떻게 하려는지 모르겠소. 뭔가 수상쩍은 낌새가 느껴져...\n\n나도 항상 여명초가 필요하다는 걸 기억해 주시오. 한번에 5개 단위로 받겠소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n탈렌드리스 씨앗 꾸러미"},
[3801] = {title = "검은무쇠단 유물", objective = "도시 주요 지역으로 통하는 열쇠를 얻고 싶다면 프랑클론 포지라이트와 대화하십시오.안녕하시오. 나는 프랑클론 포지라이트라고 하오. 그렇소, 돌다지 건축 방식을 개발한 바로 그 프랑클론 포지라이트라오. 틀림없이 당신도 이 전쟁으로 상처 입은 세계를 여행하며 돌아다니던 중에 내가 만든 건축물을 스쳐 지나갔거나 그 위에 서 본 적이 있었을 거요.\n\n아마 내가 왜 여기에 있고 당신에게 무엇을 바라는지 궁금해 하고 있겠지? 물론 둘 다 당연한 궁금증이오.\n\n나는 당신의 도움이 절실히 필요하오. 당신이 도와주는 대가로 내 저주받은 도시 깊은 곳으로 들어갈 수 있는 열쇠를 주리다.", description = "안녕하시오. 나는 프랑클론 포지라이트라고 하오. 그렇소, 돌다지 건축 방식을 개발한 바로 그 프랑클론 포지라이트라오. 틀림없이 당신도 이 전쟁으로 상처 입은 세계를 여행하며 돌아다니던 중에 내가 만든 건축물을 스쳐 지나갔거나 그 위에 서 본 적이 있었을 거요.\n\n아마 내가 왜 여기에 있고 당신에게 무엇을 바라는지 궁금해 하고 있겠지? 물론 둘 다 당연한 궁금증이오.\n\n나는 당신의 도움이 절실히 필요하오. 당신이 도와주는 대가로 내 저주받은 도시 깊은 곳으로 들어갈 수 있는 열쇠를 주리다.", progress = nil, completion = "당신이 이곳에 오게 된 것이 욕심 때문이든, 지위를 생각하지 않는 헌신 때문이든 간에, 당신이 곧 수행하게 될 임무는 우리 모두에게 득이 될 거요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3802] = {title = "검은무쇠단 유물", objective = "파이너스 다크바이어를 처치하고 거대한 망치, 무쇠지옥을 회수해야 합니다. 무쇠지옥을 타우릿산의 제단으로 가져가서 프랑클론 포지라이트의 석상에 두어야 합니다.", description = "장인의 전당의 법의 심판장 너머로 가면 파이너스 다크바이어를 찾을 수 있을 거요. 그 저주 받을 놈을 처치하고 무쇠지옥을 회수해 오시오.\n\n무쇠지옥을 타우릿산의 제단으로 가져가서 마땅히 있어야 할 자리에 두시오. 나를 기리는 뜻에서 세워진 석상의 손 안에 말이오.\n\n이 일을 마치면 내가 열쇠를 넣어 둔 부분이 열릴 거요. 이 일에서 더 중요한 건, 무쇠지옥이 내 손 안에 영원히 남아 있게 된다는 것이지. 녀석들이 그 망치를 빼내려고 하면 석상과 망치가 모두 산산조각나 영원히 되찾을 수 없게 될 것이오. 그럼 행운을 빌겠소.", progress = "석상이 불길한 모습으로 높이 서 있습니다.", completion = "망치가 이 거대한 검은무쇠단 기념비의 손 안에 꼭 들어맞습니다. 석상의 기저부에서 작은 공간이 열립니다. 그 안에는...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n어둠괴철로단 열쇠"},
[3803] = {title = "다르나서스로 여명초 가져가기", objective = "대드루이드께서는 세나리온 의회에서 진행 중인 연구에 사용할 여명초를 항상 찾고 계십니다. 한번에 10개씩 받는데, 가져온 이에게는 유용한 물건으로 보상해 주고 있어요. 10개를 구할 때마다 내게 알려 주면 그에 맞는 보상을 해드리지요.", description = nil, progress = "대드루이드께서는 세나리온 의회에서 진행 중인 연구에 사용할 여명초를 항상 찾고 계십니다. 한번에 10개씩 받는데, 가져온 이에게는 유용한 물건으로 보상해 주고 있어요. 10개를 구할 때마다 내게 알려 주면 그에 맞는 보상을 해드리지요.", completion = "아주 좋아! 이 여명초를 대드루이드께서 보시면 분명 기뻐하실 거예요. 하지만... 솔직히 말해서 나는 여명초 가까이 있는 것만으로도 좀 불편해요. 그런데 대드루이드님은 그렇게 엄청난 양의 여명초를 손수 다루시니 얼마나 힘드실지 정말 생각만 해도 끔찍한 일이지!\n\n이건 그대에게 드리는 보상이예요. 그대의 지속적인 도움에 세나리온 의회에서는 매우 감사하고 있답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 의회의 저장품"},
[3804] = {title = "썬더 블러프로 여명초 가져가기", objective = "대드루이드님께서는 세나리온 의회의 운고로 분화구에 대한 연구에 쓸 여명초를 항상 찾고 계세요. 한 번에 10개씩 받는데, 가져온 이에게는 유용한 물건으로 보상해 주고 있답니다. 10개를 구할 때마다 제게 알려 주면 그에 맞게 보상해 드리겠어요.", description = nil, progress = "대드루이드님께서는 세나리온 의회의 운고로 분화구에 대한 연구에 쓸 여명초를 항상 찾고 계세요. 한 번에 10개씩 받는데, 가져온 이에게는 유용한 물건으로 보상해 주고 있답니다. 10개를 구할 때마다 제게 알려 주면 그에 맞게 보상해 드리겠어요.", completion = "아주 좋아요. 이 여명초는 분명 때가 되면 큰 도움이 될 거예요. 나이트 엘프들 역시 이 약초에 대해 비슷한 연구를 벌이고 있다고 들었지만, 그들이 뭔가 발견한다면 대체 그걸 어디에 쓸지는 의문이군요. 대드루이드님께서는 이 약초에 숨겨진 수수께끼를 밝혀낼 때까지는 계속해서 여명초가 필요할 거라고 하셨답니다.\n\n이건 그대의 수고에 대한 보상이에요. 그대의 지속적인 도움에 세나리온 의회의 일원으로서 감사를 전합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 의회의 저장품"},
[3821] = {title = "우레망치 바위굴", objective = "불타는 평원으로 가서 샤니 프라우드터스크에게 무슨 일이 있었는지 확인해야 합니다.", description = "샤니가 불타는 평원의 불자루 오우거들이 이상한 의식을 하고 있다는 보고를 듣고 이를 조사하기 위해 떠난 지 3주가 훨씬 지났소.\n\n고어투스 장군께서는 떠난 우리 소대의 누구에게서도 아무런 소식도 듣지 못했다시며 그 일은 잊어버리고 주어진 임무에나 열중하라고 하시지만, 그게 말이나 되오? 샤니는 내 아내란 말이오!\n\n나는 주둔지를 떠날 수 없지만 샤니에게 무슨 일이 일어났는지 꼭 알아야만 하오. 불타는 평원으로 가서 그녀를 찾아봐 주시오.", progress = nil, completion = "오, 불쌍한 탈트라크.\n\n이번 임무가 끝나면 우리 부모님과 함께 동부 내륙지로 이사를 하기로 했었는데, 이제 그럴 수가 없게 되었군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3822] = {title = "크롬그룰", objective = "크롬그룰에게서 샤니의 코걸이를 찾아 카르가스에 있는 탈트라크에게 가져가야 합니다. 우레망치 바위굴에 있는 여러 광산과 동굴을 찾아봐야 합니다.", description = "나를 제외한 우리 부대원 모두가 잡혔고, 모두가 살해당했습니다. 녀석들의 두목인 크롬그룰이 어떤 의식에 사용할 목적으로 날 살려뒀었죠.\n\n내 몸은 이 제단에 묶여서 그 짐승 같은 녀석에게 고문당했습니다. 그렇게 고문을 받은 지 한 시간 만에 내 몸은 기능을 멈췄고, 그 나쁜 녀석은 내 얼굴에서 결혼 코걸이를 뜯어내서는 자기 손가락에 끼더군요. 그런 흉악한 짓은 본 적이 없었습니다!\n\n크롬그룰을 찾아 처치하고 내 반지를 탈트라크에게 돌려주세요. 그리고 사랑하는 남편에게... 다음 생에서 다시 만나자고 전해 주세요.", progress = "내 아내 샤니는 찾았소? 무사하오?", completion = "&lt;슬픔으로 털썩 주저앉는 탈트라크&gt;\n\n동부 내륙지로 이사 가기로 했었는데... 그 사람이 얘기합디까? 이번이 마지막 임무가 될 거였소.\n\n&lt;흐느끼는 탈트라크&gt;\n\n그 결혼 코걸이는 필요 없소. 난 상관없으니 가지든지 버리든지 당신 마음대로 하시오! 그녀 없이는 그 결혼 코걸이는 이제 내게 아무 의미도 없소이다...", rewards = "다음과 같은 것들을 받습니다:\n\n샤니의 코걸이"},
[3823] = {title = "불자루 오우거 처치", objective = "불자루일족 오우거마법사 15마리, 불자루 오우거 7마리, 불자루일족 투사 7마리를 처치한 후 랄리우스에게 돌아가야 합니다.", description = "우리는 적이 우리를 공격하기 전에 적을 쳐야 한다!\n\n간단히 설명하도록 하겠다, 병사.\n\n불타는 평원의 불자루 오우거들이 검은바위부족 오크들과 동맹을 맺었다. 그 사악한 오크들과 손을 잡은 이 오우거들은 광석이 풍부한 우레망치 바위굴을 지키고 보급로를 항상 열어 두고 있는 상황이다.\n\n가서 본때를 보여줘야 해. 녀석들의 세력을 꺾어 버리고 일이 끝나면 내게 다시 돌아오도록 해.\n\n<공기를 움켜쥐고 목이 멘듯한 몸짓을 보이는 랄리우스>\n\n없애주마, 윙키!", progress = nil, completion = "아주 잘했다, 병사! 그 오크와 오우거들은 이번 타격으로 한동안 휘청거리게 될 것이야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3824] = {title = "포악한 군주 고르테쉬", objective = "우레망치 바위굴의 서쪽 어딘가에서 고르테쉬를 찾아 처치하고 고르테쉬의 가면을 얻어 불타는 평원에 있는 랄리우스에게 가져가야 합니다.", description = "지난번 공격으로 틀림없이 녀석들은 휘청거리고 있을 거야! 우리의 다음 공격은 결정타여야만 해.\n\n포악한 오우거 군주 고르테쉬를 반드시 제거해야 해. 하지만 그보다 더 중요한 것은 불자루 오우거들에 대한 제3단계 공격을 준비할 수 있도록 녀석의 가면을 내게 가져오는 것이야.\n\n조심하도록 해, 병사. 고르테쉬는 우레망치 바위굴이 아니라 그곳에서 서쪽에 있는 검은바위부족 오크의 건물에 지내며 통치하고 있으니까 말이야.\n\n자네가 이번에 해야 할 임무는 피둥피둥 살찐 고르테쉬를 찾아 처치하는 것이야. 임무를 마치면 내게 돌아오도록 해.\n\n윙키, 좀 조용히 해!", progress = "아, 영광스러운 날이로군! 놈의 가면을 갖고 왔나?", completion = "이걸 보라고, 병사. 정말 역겹군! 놈의 가면을 창에 꽂아 놈들이 있는 산 꼭대기에 매달아 둔 걸 나머지 불자루 오우거들이 보게 되면 집단 히스테리를 일으키게 될 거야!\n\n&lt;큰 소리로 웃는 랄리우스&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3825] = {title = "창에 꽂은 오우거 가면", objective = "고르테쉬의 가면을 가지고 가서 우레망치 바위굴의 꼭대기에 꽂아야 합니다. 창을 꽂을 부드러운 흙으로 덮인 고분을 찾도록 하십시오.", description = "마지막으로 할 일이 하나 더 남았다, 병사.\n\n내가 고르테쉬의 가면을 창에 꽂아 두었으니 이 창을 가지고 우레망치 바위굴 꼭대기로 올라가 땅에 잘 고정시켜 놓기만 하면 돼. 그렇게 한 후에 겁 많은 오우거들이 나 살려라 하며 도망치는 꼴을 지켜보라고! 이번 임무를 즐겁게 마친 후 내게 돌아와서 지금까지 한 수고에 대한 보상을 받도록 하게, 병사.\n\n<현실 세계와의 결속이 약해지는 것 같은 랄리우스>", progress = "그래, 이번 임무의 광경을 그림에 담아 온 게 있나?", completion = "아주 잘했군, 병사! 정말 놀라워! 자네에게 용맹의 메달을 하사하기로... 아니... 아낌없이 포상하도록 하지!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n광기의 건틀릿억제의 고리\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3841] = {title = "집을 찾고 있는 고아", objective = "버섯구름 봉우리에 있는 켄튼과 대화해야 합니다.", description = "아, 안녕하세요. 또 보게 돼서 반가워요. 다르나서스에 가는 길은 어땠나요?\n\n그대가 없는 동안 일이 꽤 진척되었지요. 우린 알이 가득한 둥지를 구해 냈는데, 안타깝게도 우리가 돕기도 전에 어미가 죽어 버렸답니다.\n\n혹시 한 마리 애완 동물로 길러 볼 생각 없나요? 곧 부화할 테니 좋은 <아빠/엄마>가 필요할 거예요. 어떠세요?\n\n정말로 관심이 있으면 이 알을 소금 평원에 있는 켄튼에게 가져가 보세요. 그 친구가 더 자세한 얘기를 해줄 겁니다.", progress = "안녕하시오, <class> 친구.\n\n여기 경주를 구경하러 온 게 아니니 오해하지 마시오. 뭐, 경주가 재미있기는 하지만 말이외다.\n\n난 이 땅의 구제 가치를 알아보려고 갖은 조사를 하러 버섯구름 봉우리에 온 것이오. 이 지역을 활력이 넘치고 비옥한 땅으로 되살리는 건 내게 일종의 신성한 임무가 되어 버렸소. 어쩌면 근처에서 수자원을 발견할지도 모르는 일이지.\n\n페랄라스와 버섯구름 봉우리 사이의 변화가 얼마나 기이한지 보지 않았소? 이런 일이 발생했을 때는 이상한 마법이 관련된 것이오.", completion = "아, 이건 화살요정용 알이로군. 보아하니 거의 부화할 것 같소이다. 알의 상태가 이리도 좋은 것은 물론이고, 페랄라스에서는 거의 보지 못하는 것을 하나라도 찾았다는 것 자체가 놀랍소. 이 지역에서 여러 밀렵꾼들이 갖은 이유로 화살요정용을 잡아 죽이려고 하고 있어 말이오. 참 안타까운 일이지... 어른이 되면 아주 아름다운 생물들인데 말이오.\n\n그런데 이건 어떻게 해서 찾은 거요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3842] = {title = "짧은 부화", objective = "버섯구름 봉우리에 있는 켄튼에게 인내의 비약 2개를 가져가야 합니다.", description = "문위버 자매가 줬단 말이오? 재미있군. 화살요정용들이 그 자매들이 자신들을 보살펴 주는 게 얼마나 고마운 일인지 알았으면 좋겠군. 그 둘은 솜씨가 아주 좋지.\n\n그러니까 이 알을 선물로 줬단 말이군. 그렇다면 당신이 더 이상 원하지 않을 때까지 책임을 져야 하오. 보아하니 거의 부화할 때가 된 것 같지만 알이 건강하고 아무런 손상이 가지 않았다는 것을 확실히 해야겠소.\n\n알을 보호하는데 사용할 인내의 비약 2개와 주문이 좀 필요하오. 나머지 재료는 내가 가지고 있소이다.", progress = "여기에 오래 있으면 오래 있을수록 저 경주에 가담하고 싶어진다오. 정말로 놀랄 만한 일이지...\n\n그 비약은 찾았소? 이 알이 건강한지 아닌지 알 수만 있으면 부화할 때까지 당신이 갖고 있도록 되돌려주리다.\n\n비약을 찾거든 내게 알려주시오.", completion = "좋소. 이거면 될 거요. 재료를 섞을 동안 잠시만 기다리시오. 이 알이 얼마나 튼튼할지 곧 알게 될 테니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3843] = {title = "새로운 가족의 탄생", objective = "동부 내륙지로 깨지기 쉬운 화살요정용 알을 가져가서 아그나르 비스테이머와 대화하십시오. 1시간 내에 아그나르를 찾지 못하면 알 속의 새끼가 죽게 되니 서둘러야 합니다.", description = "아주 훌륭한 견본이군. 이 생물이 잉태 기간 동안 살아 남는다면 정말 건강한 애완동물이 될 거요!\n\n이 일을 마저 끝낼 계획이라면 마지막으로 한 가지 더 해 줬으면 하는 일이 있소. 동부 내륙지에 있는 맹금의 봉우리로 가서 그곳에 있는 아그나르 비스테이머라는 드워프와 얘기해 보시오. 그는 동물을 다루는 데는 달인이라 부화의 마지막 단계에 대해 잘 지도해 줄 수 있을 거요.\n\n이 알은 약해서 제대로 돌보지 못하면 오래가지 못하니까 서두르시오.", progress = "안녕하신가. 내가 도와 줄 일이라도 있나?", completion = "이런, 이런, 이런... 용에게서는 이런 걸 본 적이 없는데.... 내 생각에는 요정용인 것 같군. 내가 틀리지 않았다면 화살요정용 변종 중 하나인 것 같네. 좋아, 정말 잘 됐어.\n\n자, 이제 부화를 무사히 마치고 강하고 튼튼하게 자랄 수 있도록 하려면 먹일 걸 좀 가져와야 하네. 제시간에 날 잘 찾아와서 다행이군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3844] = {title = "아무도 모르는 비밀", objective = "연못을 둘러보고 이 난파된 나룻배의 주인에 대한 단서를 찾아야 합니다.", description = "물가에 부서진 나룻배가 있습니다. 작은 연못일 뿐이라는 점을 감안할 때 이 나룻배가 어떻게 여기까지 오게 됐는지는 확실하지 않지만 나무들을 살펴보니 수심이 일정하지 않은 것 같습니다.\n\n이 일대를 좀 더 살펴보면 단서를 더 찾을 수 있을지도 모릅니다.", progress = nil, completion = "물에 젖은 가방이 연못 바닥에 놓여 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3845] = {title = "아무도 모르는 비밀", objective = "가방 안에 든 물건을 조사해 그 주인에게 되돌려주어야 합니다.", description = "가방을 잡아 물가로 끌어냅니다. 이 가방 안의 물건들을 조사해 보면 주인에 대한 단서를 더 찾을 수 있을지도 모릅니다.\n\n마샬의 야영지에서 길을 잃은 여행자들이 몇몇 있는데, 아마 그곳에서 단서를 더 찾을 수 있을지도 모릅니다.", progress = "안녕하세요. 우리 초면이죠?", completion = "오... 맞아요. 낯이 익은 물건들이네요... 뭐, 조금...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3861] = {title = "꼬꼬댁!!!", objective = "특별 닭모이를 찾아 친구가 된 닭에게 돌아가야 합니다. 특별 닭모이를 주기 전에 닭을 찾으면 /환호해야 합니다.", description = "꼬... 꼬꼬... 꼬... 꼬꼬대액!\n\n꼬... 꼬... 꼬꼬.\n\n닭이 당신을 올려다 본 후 발톱으로 땅을 긁기 시작합니다. 무언가를 땅에다 쓰고 있는것 같지만 무엇인지 확실하지 않습니다. 아마도 ' 살-딘' 이라고 쓴 것 같습니다. 하지만 물어보기도 전에 닭이 다른 곳으로 시선을 돌리고 자기 볼 일을 보기 시작합니다.", progress = "<검고 차가운 눈으로 배고프다는 듯이 올려다보는 닭>\n\n꼬꼬대애액!\n\n꼬... 꼬꼬꼬...", completion = "꼬꼬댁!!!\n\n&lt;모이를 내려놓자 게걸스레 먹기 시작하는 닭&gt;\n\n잠시 후에 닭이 놀란 듯이 주위를 둘러봅니다. 불편한 듯이 앞뒤로 뒤뚱거리는데, 알을 밴 것일까요? 밑을 조사해 보는 것이 좋겠습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n달걀 소환"},
[3881] = {title = "원정대 구조", objective = "운고로 분화구에 있는 윌리덴 마샬에게 식량 상자와 탐사 장비를 가져가야 합니다.", description = "당신이 어떻게 여기까지 무사히 왔는지는 모르겠지만 아무튼 정말로 반갑소이다! 나는 윌리덴 마샬이라하며 독립 원정대를 이끌고 있소. 우리 원정대가 최근 벌였던 최고의 시도가 헤아릴 수도 없을 만큼의 재앙만 불러온 것 같소이다. 그 중 가장 심각했던 것은 우리가 운고로 분화구의 험난함을 과소평가한 것이었소!\n\n분화구 남서쪽과 북동쪽 지역에 있는 우리 주둔지에서 빠져나오면서 아주 중요한 보급품들을 두고 왔는데, 당신은 능력이 충분한 것 같으니 우리 대신 좀 가져다주지 않겠소?", progress = "우리가 여기서 살아서 빠져나갈 기회라도 얻으려면 그 큰 식량 상자가 필요하오. 그리고 최소한 탐사 장비의 일부라도 되찾게 된다면 그거야말로 불행 중 다행인 셈이지.", completion = "식량 상자와 탐사 장비 둘 다 가져왔구려! 당신은 원정대뿐 아니라 우리 목숨도 구해 준 거요. 우리가 대체 어떻게 감사를 해야 할지 모르겠소이다. 덕분에 여기서 좀 더 있을 수도 있겠소이다.\n\n가진 것은 많지 않지만 당신이 우리에게 베푼 귀한 도움에 대해 모르는 척 그냥 넘어가는 일은 절대 없을 거요. 고맙소. 이제 당신은 우리 왕국 원정대에 친구를 얻은 것이오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3882] = {title = "뼈 수집", objective = "운고로 분화구에 있는 스파크 닐마이너에게 공룡 뼈 8개를 가져가야 합니다.", description = "당신은 내가 왕국 원정대의 수석 발굴조사원인 만큼 땅 파는 것을 좋아하는 줄 알겠지만, 천만의 말씀이오. 뭐 세상에 그보다 더 고생스러운 일이 있을지도 모르긴 하지만 말이오... 아무튼 요즘은 아무것도 맘에 들지 않소!\n\n공포의 터, 아주 멋진 이름이지. 그 부근에서 죽은 스테고돈과 디메트로돈을 찾아 발굴 작업을 하기로 되어 있었는데 말이오. 세상에! 살아있는 것들도 잔뜩 있지 않겠소? 윌리덴과 홀라니에, 저 친구들은 아직도 이 지옥 같은 곳에서 연구를 할 배짱이 있는 모양이니 우린 그 공룡 뼈가 필요하오. 우리끼리만 하는 얘기지만, 살아 있는 녀석들에게서 뼈를 구해 와도 될 거요.", progress = "나에 대해 뭐라고 비난을 하든 상관없소이다. 하지만 연구하는데 쓸 뼈가 고대 스테고돈 녀석들과 디메트로돈에게서 나온 것이든 우리가 진을 치려고 할 때 우리를 숫제 통째로 집어삼키려고 했던 녀석들에게서 가져온 것이든 상관하지 않을 거란 말이오. 나는 그저 살아서 여길 빠져나갈 수만 있으면 그걸로 족하니까...", completion = "아주 좋소. 이거면 될 거요. 그리고 잠깐만 실례를...\n\n이 뼈들을 땅에서 파내고 살아있는 스테고돈에 해를 전혀 입히지 않아 줘서 아주 고맙소이다!!!\n\n당신이 정말로 땅을 파서 가져왔든 그렇지 않았든 나는 알고 싶지 않소. 그냥 그렇게 비밀로 간직하도록 합시다. 어때 괜찮겠지? 자, 이거면 이번 일에 대해서 당신이 완전히 입을 다물어 줄 수 있을 거요. 여기서 살아서 빠져나갈 수만 있다면야!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n고고학자의 작업용 장화발굴인부의 연장허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3883] = {title = "외래 생태계", objective = "운고로 분화구에 있는 고리쉬 부화장에서 채집 약병을 사용해 고리쉬집 벽면 견본을 채취하십시오. 유충알이 매달려 있는 방을 찾아야 합니다.\n\n운고로 분화구에 있는 홀라니에 마샬에게 고리쉬집 벽면 견본을 가져가야 합니다.", description = "장애가 있다고 해서 연구를 그만둬야 한다는 법은 없어요! 여기로 오게 되기 전에 우리는 분화구 남부에 있는 고리쉬를 조사하고 있었답니다. 녀석들은 운고로 생태계 토착 곤충이 아니에요. 우린 그 이유를 알아내고 싶습니다.\n\n녀석들의 서식지 내부에는 유충 부화장이 있을 겁니다. 그 곳에 매달려 있는 유충알이 그 곳에 있을테니 쉽게 확인할 수 있을 겁니다. 이 약병을 사용해서 아무 부화장 근처에 있는 거주지 벽 견본을 채취하도록 하세요. 연구를 할 수 있도록 제게 가져오셔야 하는데, 조심해야 합니다!", progress = "연구할 고리쉬 거주지의 견본은 가져왔나요?", completion = "네, 이거면 됐습니다. 당신은 아주 큰 도움이 되었어요... 사례를 이보다 더 후하게 해 드리고 싶지만 험난한 오지 한가운데서 오도가도 못하게 되면 다른 이에게 줄 수 있는 게 줄어들게 마련이죠. 하지만 이곳에서 진행된 연구는 당신의 도움이 아니었으면 정말 불가능했을 겁니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3884] = {title = "윌리덴의 일지", objective = "운고로 분화구 어딘가에 있는 윌리덴 마샬에게 일지를 돌려줘야 합니다.", description = "구겨진 일지를 발견했습니다. 그 중 일부는 읽을 수 있는데 이 내용을 기록한 것이 윌리덴 마샬이라고 되어 있습니다. 만약 이 일지가 정확하다면 분화구 북부 어딘가에서 윌리덴을 찾을 수 있을 것입니다. 일지에 따르면 그와 그의 동료들은 주둔지가 분화구의 흉포한 짐승들에게 짓밟힌 후 그들을 피해 좀 더 높은 지대로 이동한 것 같습니다.", progress = "안녕하시오! 덩치만 큰 흉포한 짐승들 말고 살아 있는 자를 보게 되니 반갑기 그지없소이다! 운고로 분화구에는 무슨 일로 오셨소?", completion = "이런! 내 일지잖아! 운고로로 가져온 다른 모든 물건들처럼 이것도 잃어버린 줄 알았소. 돌려줘서 고맙소이다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3901] = {title = "덜그럭거리는 해골 처치", objective = "덜그럭거리는 해골 12명을 처치한 후, 데스넬에 있는 어둠의사제 사비스에게 돌아가야 합니다.", description = "자네는 평범한 상황에서 자신의 잠재성을 포세이큰에 보여 주었네. 이제 압박을 받는 상황에서는 어떤지 보도록 함세.\n\n리치 왕의 어리석은 부하인 덜그럭거리는 해골들은 자네가 지금까지 맞서 싸운 좀비들보다 더 강한 적이라네. 녀석들의 수를 줄여 다시 한번 자신의 가치를 포세이큰에 증명해 보이게. 일이 끝나면 지체하지 말고 다시 날 찾아오게.", progress = nil, completion = "내가 자네에게 해 줄 수 있는 일은 이걸로 끝일세. 자네는 자네가 얻은 자유를 마음껏 누릴 자격이 있음을 증명해 보였어. 지금까지 보여 준 실력 덕분에 앞으로 자네에게 수많은 자들이 대항해 오겠지만 그 자들이 어떤 짓을 하든 우리는 자유로운 존재이고 두 번 다시 노예가 되지는 않을 것이라는 걸 명심하게나.\n\n자, 자넨 해야 할 일이 무척 많으니 이걸 받고 어서 길을 떠나게.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아마포 장화승냥이 튜닉방랑자의 다리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3902] = {title = "데스넬에서의 폐품 수집", objective = "데스넬과 그 주변에서 쓸만한 물건 6개를 찾아 죽음의경비병 살테인에게 돌아가야 합니다.", description = "이봐, 당신! 뭔가 쓸모 있는 일을 하고 싶다면 잘 들으라고!\n\n우리는 막 깨어난 언데드 시체들을 데스넬로 보내 장비들을 모두 찾아 보도록 하고 있다. 아마도 상자 더미 속에 뭔가가 있을 것이다. 곧 시체들이 더 깨어날 테고 그 시체들이 발가벗은 체로 어슬렁거리게 하지 않으려면 당장 폐품 수집을 시작해야 해!\n\n당장 시작해, 이 형편없는 친구 같으니! 서둘러 일하지 않으면 보상도 주지 않을 거야.", progress = "쓸 만한 물건들을 좀 가져왔나? 버려진 물건을 재활용하는 걸 부끄럽게 여길 필요는 없어. 누가 우리에게 동냥을 줄 것도 아니고 말이야. 우리 포세이큰은 자신의 힘으로 살아갈 거라고!", completion = "잘했어, 친구. 당신이 쓸모 있을 줄 알았다니까. 자, 지금까지 수집한 물건 중 그나마 괜찮은 걸 골라 놨으니 하나 골라 가지라고.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아마포 허리띠녹슨 팔보호구그늘박쥐 단망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3903] = {title = "밀리 오스워드", objective = "밀리 오스워드와 대화해야 합니다.", description = "당신은 믿음직한 분이시라는 걸 보여주셨군요. 그뿐만 아니라 궂은 일도 마다지 않으시는 분이시죠?\n\n제게 밀리 오스워드라는 친구가 있는데, 문제가 좀 생겼답니다. 그 친구는 수도원 뒤편, 마구간 근처에 있는 그녀의 마차 곁에 있습니다. 틀림없이 당신 같은 분의 도움을 받고 싶어할 겁니다.", progress = nil, completion = "오, 윌렘 부관님께서 저와 얘기해 보라고 했다고요? 그분은 용감하고 언제나 남을 도와 주려고 하지만 임무 때문에 노스샤이어 수도원에 묶여 계시는 분이라 지금의 제 문제는 어떻게 해 줄 수 없을 것 같아요.\n\n혹시 당신이 도와 주실 수 있으세요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3904] = {title = "밀리의 수확물", objective = "노스샤이어 수도원에 있는 밀리 오스워드에게 밀리의 수확물 8 상자를 가져가야 합니다.", description = "제가 노스샤이어 포도밭에서 포도를 따고 있는데 데피아즈단이라는 도적떼가 몰려오더군요! 그래서 전 노스샤이어 경비병들에게 신고했고 그들이 사태를 수습해 주겠다고 약속하긴 했지만... 제 포도가 걱정이에요! 데피아즈단 녀석들이 포도를 훔쳐 가지 못한다 해도 경비병들이 녀석들을 쫓아내면서 포도를 다 짓밟아 버릴까 봐 걱정이랍니다.\n\n제발 절 좀 도와 주세요! 전 제 포도 대부분을 양동이에 담아 두었는데 그것들을 남동쪽에 있는 포도밭에 두고 와 버렸어요.\n\n그걸 제게 가져다주세요! 제가 거둔 포도 수확물을 지켜 주세요!", progress = "제 포도는 가져오셨나요?", completion = "오, 제 포도 수확물을 가져 오셨군요! 감사합니다! 데피아즈 녀석들에게 이 근처에서는 소동을 피울 수 없다는 걸 똑똑히 보여 주셨다면 좋겠네요.\n\n요즘 들어 경비병들이 좀 부족한 듯도 한데 당신 같은 영웅들이 우리를 보호해 주니 얼마나 다행인지 모른답니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3905] = {title = "포도 수확 목록", objective = "노스샤이어 수도원에 있는 수사 닐스에게 포도 수확 목록을 가져가야 합니다.", description = "이제 제 포도 수확물이 안전해졌으니 이 포도 수확 목록을 수사 닐스님께 가져다주세요. 그분은 노스샤이어의 식품 및 음료 상점을 관리하시는데, 싱싱한 포도가 있다는 걸 알면 분명 아주 기뻐하실 거예요.\n\n닐스님은 수도원 안에 있는 종탑에서 찾으실 수 있을 겁니다. 그분은 그곳에서 본인이 만든 포도주의 맛을 보곤 하신답니다.", progress = "선한 기운이 느껴지는 분이시군요. 이리 오세요. 앉아서 한잔 하시죠!", completion = "어디 보자...\n\n오호! 밀리의 포도를 구해 내셨군요! 도적떼가 포도밭에 침입했다는 밀리의 얘기를 듣고 거의 절망에 빠져 있었는데 말입니다. 하지만 성스러운 빛에 대한 제 믿음은 흔들리지 않았답니다!\n\n그리고 형제의 용기 덕분에 이제 포도주를 더 담글 수 있는 포도가 생겼습니다! 성스러운 빛이 형제를 축복하시고 안전하게 지켜 주시기를!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n와인 얼룩진 망토빗장 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3906] = {title = "화염의 부조화", objective = "검은바위 산에 있는 채석장으로 가서 멸망의 파이론을 처치해야 합니다. 이 임무를 완수한 후 썬더하트에게 돌아가십시오.", description = "장로들께서는 자연의 원소들에게서 심상치 않은 기운을 느끼셨습니다. 검은무쇠단 드워프들이 우리 땅을 영원한 가뭄으로 병들게 하려고 위협하는 사악한 영혼을 우리 세계로 불러냈습니다. 이 화염의 부조화를 반드시 조사해야 합니다.\n\n검은바위 산으로 가서 작열하는 교각을 지나 채석장으로 가십시오. 그곳에서 이 화염의 군주, 멸망의 파이론을 찾을 수 있을 겁니다.\n\n이 혼란을 끝내고 내게 돌아오시기 바랍니다.", progress = nil, completion = "이럴 리가 없는데... 이래서는 안 되는데. 파이론을 처치한 것은 이제 겨우 겉에 덮여 있던 덮개를 벗긴 정도밖에 되지 않습니다. 검은바위 나락 내에는 훨씬 더 사악한 타락의 근원이 도사리고 있는 것입니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3907] = {title = "불의 부조화", objective = "검은바위 나락에 들어가 불의군주 인센디우스를 찾아, 그를 처치한 후 얻게 되는 모든 정보를 썬더하트에게 가져가야 합니다.", description = "당신을 둘러싸고 있는 대기에서 사악한 기운이 느껴지는군요. 검은바위 나락에 숨어서 이 사악함을 지휘하고 있는 자가 또 있습니다.\n\n바람과 땅의 군주 인센디우스의 이름을 부르짖고 있습니다... 하지만 누군가... 무엇인가가 그를 지배하고 있습니다. 그는 심부름꾼에 불과할 뿐입니다.\n\n그를 찾아 그의 주인이 어디에 숨어 있는지 알아내고 정보를 알아내면 내게 돌아오십시오.", progress = "곧 화염이 이 대지를 뒤덮게 될 겁니다. 서두르십시오!", completion = "&lt;쿠르니아의 서판을 거머쥐는 썬더하트&gt;\n\n라그나로스가... 이곳에...\n\n장로들이 검은바위 산에서 뿜어져 나오는 타락을 걱정한 것이 옳았습니다. 고대 신들의 장군이라니! 우리의 세계에!!! 우린 카르가스에서의 우리 입지를 다시 세워야 합니다. 여기에 남아서 싸울 것인가 아니면 새로운 세계의 분리를 두려워하여 도망칠 것인가 반드시 결정해야 하는 겁니다.\n\n검은바위 산으로 다시 탐험을 떠나게 되면 조심하도록 하시기 바랍니다. 이 세계에 현존하는 그 어떤 것보다도 훨씬 더 큰 악이 그 불의 심연 속에 살고 있습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n해무리 단망토땅거미 장갑지하 악마의 팔보호구튼튼한 벨트\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3908] = {title = "아무도 모르는 비밀", objective = "여명의 설원에 있는 도노바 스노우덴에게 링쿠의 훈련용 검을 가져가야 합니다.", description = "보시다시피 전 제가 어떻게 여기까지 오게 됐는지 전혀 모르겠어요. 아무도 몰라요. 모두에게 비밀이거든요! 아무것도 기억할 수 없어요...\n\n그렇지만 당신이 가져온 물건을 보니... 뭔가 기억이 나네요.\n\n제 칼. 제 칼을 어떻게든 연마하려고 했던 것 같은데, 왜 그랬는지는 확실히 기억이 나질 않네요. 더 자세한 얘기를 못 해드려서 죄송하지만 도저히 기억이 나질 않아요!\n\n어쨌든 이 칼을 가져가야 할 곳은 알고 있어요. 여명의 설원에 있는 도노바 스노우덴을 찾아가세요. 온천 근처에 있을 텐데 도노바가 그곳에서 칼을 손질할 수 있을 겁니다.", progress = "어이구... 이제서야 링쿠 녀석이 칼을 보냈군요, 빠르기도 하지.", completion = "칼이야 당연히 연마할 수 있죠. 작업을 하는 동안 링쿠 녀석이 왜 이렇게 시간을 끌었는지 설명이나 해주세요. 이런 일은 잘 잊지 않는 녀석인데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3909] = {title = "앞날의 비약", objective = "페랄라스 북쪽에서 그레간 브루스퓨를 찾아야 합니다. 그에게서 앞날의 비약을 얻는 방법을 배워 여명의 설원에 있는 도노바 스노우덴에게 돌아가야 합니다.", description = "뭐라고요? 링쿠가... 까먹었다니요?\n\n아, 기억을 잊어버렸다는 거군요...\n\n자, 여기 칼 받으세요. 다 완성된 건 아닙니다. 완성할 수 있는 사람을 내가 알고 있긴 한데, 그 사람이랑 대화를 하는 게 좀 힘들 거예요.\n\n당신을 도와줄 수 있는 사람이 있으니까 잘 들어 두세요. 지금 모두 설명하기에는 좀 벅찬데, 어떻게든 앞날의 비약을 구해야 해요. 그일을 도와줄 수 있는 사람이라면 그레간 브루스퓨 밖에 없어요. 그 친구는 좀 찾기가 힘든데, 내가 마지막으로 봤을 때는 페랄라스의 숲에 있었어요.", progress = "벌써 오셨어요?", completion = "이게 정말로 그 비약인지 알아보려면 약병 하나가 있어야 하는데... 네... 정말로 그 비약이군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3911] = {title = "마지막 원소", objective = "검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것이 기억납니다.", description = "깊은 곳을 탐험하는 이들에게는 일거리가 생기게 마련이랍니다.\n\n검은무쇠 녀석들이 소름이 돋을 정도로 강력한 골렘을 만들어 내는 방법에 통달했어요.\n\n우리 밀정들로부터 들어온 보고 내용에 의하면 검은무쇠 드워프들은 자신들이 만들어 내는 골렘에 고유한 마력 원천을 이용해, 비할 데 없이 엄청난 살생력을 부여한다고 해요.\n\n우리가 그 원소의 정수를 손에 넣게 될 경우 우리의 누더기골렘으로 어떤 일을 할 수 있을지 한번 상상해 보세요! 도시를 뒤엎어야 한다면 그렇게라도 하세요. 대신 그 정수를 찾기 전에는 돌아와선 안 됩니다! 보상은 위험 부담에 걸맞을 정도로 하겠어요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n라그레이브의 인장"},
[3912] = {title = "무덤에서의 만남", objective = "가젯잔 밖에 있는 무덤으로 가서 앞날의 비약을 사용하십시오. 도노바의 지시에 따라 개리얀을 찾아야 합니다.\n\n제공된 아이템: \n", description = "이 비약이 있으면 보통 눈으로는 볼 수 없는 자와 대화를 할 수 있답니다...\n\n앞날의 비약과 링쿠의 강화된 검을 지니고 타나리스의 가젯잔 바로 밖에 있는 무덤으로 가 보세요. 그곳에서 비약을 마시면 물약의 효과에 놀라겠지만 긴장할 건 없어요.\n\n당신이 \"다른\" 형태가 되면 북쪽으로 산에 도착할 때까지 쭉 가세요. 바위 틈새를 뒤지다 보면 개리얀이라는 자를 만날 수 있을 겁니다.\n\n당신이 \"다른\" 형태일 때만 말을 하니까 명심하도록 하세요.", progress = nil, completion = "누가 나와 얘기를 나누러 온 것도 참으로 오랜만의 일이로군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3913] = {title = "무덤의 상태", objective = "부활한 후, 개리얀이 말한 묘비를 찾아야 합니다.", description = "자네가 묘지로 되돌아가면 묘비가 하나 있을 걸세... 평범한 묘비가 아니라 다른 묘비들 사이에서도 눈에 띌 게야. 그 안에 비밀이 담겨 있지.\n\n묘비를 밀어 보게. 그 속에 든 비밀을 알게 될 테니...", progress = "이 묘비가 개리얀이 말한 묘비가 틀림없습니다...", completion = "묘비를 강하게 밀자 묘비가 미끄러지며 아래에 움푹하게 패인 땅이 드러납니다.\n\n링쿠의 검을 집어넣어 보니 모양이 딱 들어맞습니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3914] = {title = "링쿠의 검", objective = "운고로 분화구에 있는 링쿠에게 링쿠의 명검을 가져가야 합니다.", description = "눈부신 빛이 번쩍하고 지나가니 다시 검을 집을 수 있습니다. 검이 변신하였습니다!", progress = "아! 당신을 본 적이 있어요! 이름이... 잠깐만요. 제가 말해 볼게요!", completion = "내 검... 완성됐네!\n\n근데 왜 이 검이 필요했는지 기억이 나지 않네요...\n\n자, 적어도 수고해 주신 보답을 해 드려야죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3921] = {title = "웨니키 볼트버킷", objective = "웨니키 볼트버킷에게 부서진 사모플랜지를 가져가야 합니다.", description = "내가 사모플랜지를 망가뜨려 버린 것 같아. 이거 정말 큰일이야! 벌써 지하광산의 동료들에게 말해 놓았는데... 다들 관심을 보이면서 보고 싶어 하더란 말이지. 어떻게든 고칠 방법을 찾아야 하네!\n\n부서진 사모플랜지를 웨니키 볼트버킷에게 가져가게나. 불모의 땅과 잿빛 골짜기 사이의 호드 전초기지인 몰샨의 망루 바로 남쪽에 있네. 호기심이 많고 아주 영리한 여자지. 부서진 사모플랜지를 보여 주기만 하면 당장 달려들어 고쳐보려고 할 걸세.", progress = "지금 무척 바쁘거든요. 나한테 뭔가 줄 게 있는 게 아니라면 어서 가 보시는 게 좋을 거예요.", completion = "아, 이게 뭐죠? 사모플랜지라고요? 사모플랜지는 또 뭐예요??\n\n음... 이걸 건드리면 이 부분이 움직이고... 또 속에서 아주 복잡한 기계 소리가 나네요. 세상에! 제대로 한번 고쳐서 뭐 하는 물건인지 알아보고 싶군요. 당신도 그렇죠??", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3922] = {title = "용접용 철괴", objective = "불모의 땅에 있는 웨니키 볼트버킷에게 용접용 철괴 15개를 가져가야 합니다.", description = "이 사모플랜지를 고치고 싶긴 한데, 그러려면 필요한 게 좀 있어요. 17.5 게이지 규격 용접용 철괴가 다 떨어졌는데 작업을 진행하려면 그게 있어야 하거든요.\n\n그걸 구할 수 있는 가장 가까운 장소는 동쪽에 있는 진흙늪이에요. 보통 투자개발회사에서 연장통에 담아 두곤 하니까 진흙늪으로 가서 그곳에 있는 연장통 안을 뒤져 보세요. 용접용 철괴를 충분히 모았으면 제게 돌아오세요.", progress = "용접용 철괴를 가져오셨나요, <name>? 이 사모플랜지를 계속 쳐다보고 있으려니 얼른 고치고 싶어서 안달이 나네요.", completion = "좋아요, 가져오셨군요! 이제 작업을 시작할 수 있겠어요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3923] = {title = "릴리 그리지가브", objective = "오그리마에 있는 릴리 그리지가브에게 부서지고 찌그러진 사모플랜지를 가져가야 합니다.", description = "흠... 작동이 안 되네요. 사모플랜지에 게이지를 장착해서 구조 무결성을 측정해 봤는데, 최하치로 나타나는군요. 눈금판 몇 개에 지레 한두 개만 더 있다면 고쳐 볼 수도 있겠지만... 그러다 상태가 더 안 좋아질까봐 걱정이 되네요.\n\n사모플랜지를 릴리 그리지가브에게 가져가는 게 좋겠어요. 예전에 투자개발회사에서 일했던 적이 있는데, 이걸 고칠 수 있는 이가 있다면 바로 그 사람이죠.\n\n오그리마 명예의 골짜기에 있는 노그의 작업소에서 그를 찾을 수 있을 거예요.", progress = "머리 조심해! 비켜! 작업하는데 거치적거리잖아!", completion = "이게 뭐지? 아니, 사모플랜지잖아! 이걸 어디서 구한 거요? 불모의 땅에서 투자개발회사 소유지를 여기저기 들쑤시고 다니기라도 한 거요?\n\n당신은 아주 용감하든가 아니면 아주 어리석은 &lt;race&gt;임에 틀림없소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3924] = {title = "사모플랜지 설명서", objective = "오그리마에 있는 릴리 그리지가브에게 사모플랜지 설명서를 가져가야 합니다.", description = "사모플랜지를 고칠 수는 있겠지만 먼저 설명서가 필요하오. 내가 투자개발회사에서 일할 적에 코퍼플러그라는 사장 놈과 경쟁 관계에 있었소. 그는 사모플랜지의 비밀을 긁어모아 자신이 신뢰하는 이들에게만 조금씩 말해주곤 했는데, 난 그 선택된 소수에 끼지 못했지...\n\n예전에 코퍼플러그 사장은 불모의 땅 북동쪽에 있는 돌무더기 광산에 머물렀소. 그에게서 설명서를 가져와 주시오. 그가 설명서 중 몇 장을 다른 이에게 주었을 수도 있소. 그것들까지 전부 모아와야 하오.", progress = "설명서는 가져왔소?", completion = "가져왔구려! 당장 설명서를 읽고 사모플랜지 고치는 방법을 알아내야지! 톱니항에 있는 스퍼터밸브와 얘기했는데 당신에게 도와줘서 고맙다는 인사와 함께 수고에 대한 보상을 주고 싶어하더군.\n\n나도 정말 감사하오. 일단 이 물건을 다 고치게 되면 당신에게도 알려주도록 하지.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n토르크 스패너사모플랜지 나사돌리개\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[3941] = {title = "노움의 도움", objective = "마샬의 야영지에 있는 동굴에서 J.D. 콜리를 찾아야 합니다.", description = "가만있자... 분명히 무슨 중요한 일이 있었는데... \n\n아, 한 가지 생각이 났어요. 저기 있는 동굴에는 J.D. 라는 이름의 노움이 있는데요, 제가 처음 여기에 도착했을 때 아주 친절하게 대해 준 친구에요. 제가 제정신이 아니었을 때 J.D.에게 뭔가 얘기했는지도 몰라요.\n\n가서 J.D.가 뭘 알고 있는지 한 번 물어봐 주시겠어요? 아, 하지만 조심하셔야 해요. 제가 빛을 발하는 수정들을 분화구에서 봤는데, J.D.는 그 이상한 수정들로 작업을 한답니다. 그 동굴에서 뭘 하는 건지 확실히 모르겠거든요!", progress = nil, completion = "제자리에서 잠깐만 기다리세요... 새로운 수정 조합을 실험하는 중이거든요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3942] = {title = "링쿠의 기억", objective = "악령의 숲 남부에 있는 에리단 블루윈드를 찾아가야 합니다.", description = "아, 링쿠요? 맞아요, 재미있는 친구죠. 여기 처음 왔을 때는 온갖 이상한 말들을 중얼대더라고요. 아마 머리를 꽤나 심하게 다친 모양이에요.\n\n음, 링쿠가 말한 것 중에 기억나는 게 하나 있는데, 자기는 어떤 토템을 만들고 있다며 에리단 블루윈드라는 사람을 만나야 한다더군요... 악령의 숲이라는 곳에 있다나?\n\n아마 지금은 링쿠가 잘 기억하지 못할 거예요. 더 자세한 내막은 에리단을 직접 찾아가 보시는 게 좋지 않겠어요?", progress = nil, completion = "엘룬께 영광을. 내가 도와줄 일이 있소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3961] = {title = "링쿠의 모험", objective = "마샬의 야영지에 있는 링쿠에게 아쿠에멘타스의 은토템을 가져가야 합니다.", description = "링쿠가 애초에 여기 온 이유가 불바람을 없애기 위해서였다는 걸 생각하면... 그냥 평범하게 보이는 친구지만 다른 노움 같지 않게 내 실험이나 장치에 전혀 관심이 없다는 걸 눈치채긴 했었어요. 마음부터가 진정한 전사인 게 틀림없다는 거죠.\n\n이 토템을 링쿠에게 가져다주세요. 자기가 이곳에 온 이유가 뭔지 기억하는데 도움이 될 수 있게 말이에요.", progress = "안녕하세요. 또 보네요!", completion = "J.D.가 도와주던가요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[3962] = {title = "혼자서 가기 무서운 곳", objective = "마샬의 야영지 남쪽에 있는 불기둥 마루로 가야 합니다.\n\n불바람을 찾아 토템을 이용해 오라를 제거하십시오. 정령을 물리친 후, 동굴에서 황금 불길을 손에 넣어야 합니다.", description = "아, 이제야 기억이 나는군요... 전 정말 불바람과 싸우려고 이곳에 왔어요. 그게 제 여행의 마지막 단계였죠.\n\n하지만 저는 더 이상 영웅이 아니에요. 당신이 바로 그 영웅이거든요. 지금까지 당신은 많은 일을 했는데, 이 일을 마칠 사람은 제가 아니라 바로 당신이에요.\n\n불바람은 황금 불길이라는 유물을 보관하고 있는데, 제가 아는 그 어떤 것보다 훨씬 더 굉장한 힘을 준답니다. 사악한 마음을 가진 자의 수중에 두기에는 너무나도 위험한 물건이에요.\n\n다른 사람과 함께 가도록 하세요. 혼자서 가기에는 매우 위험하니 제 조언을 듣도록 하세요.", progress = "불바람은 황금 불길을 이용해 오라를 치고 있어 거의 불사신이나 다름없어요. 아쿠에멘타스의 은토템을 가진 당신만이 그 보호막을 제거할 힘을 지니고 있답니다.", completion = "감사해요.\n\n이제 황금 불길을 제 고향에 돌려줄 수 있겠군요. 그곳에서 보호를 받으며 다시는 사악한 목적으로 사용되지 않을 겁니다.\n\n당신이 아니었다면 전 아직도 제가 누군지 전혀 몰랐을 거예요! 저를 너무나 많이 도와 주셨으니, 뭔가 특별한 걸 드렸으면 하는데... \n\n원하시는 걸 아무거나 가져가세요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n링쿠의 용자검아쿠에멘타스의 정기\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n링쿠의 부메랑"},
[3981] = {title = "사령관 고르샤크", objective = "검은바위 나락에서 사령관 고르샤크를 찾아야 합니다.\n\n조잡하게 그려진 오크 그림에 쇠창살이 그려져 있던 것이 생각납니다. 감옥 같은 곳을 찾아봐야 할 것 같습니다.", description = "불쌍한 가르갈 녀석... 뭐가 날아오고 있다는 것조차 몰랐을 거요. 화살이 머리 정수리 급소에 퍽하고 꽂혔으니까 말이오. 원래 똑똑한 녀석은 아니었지만 이젠...\n\n<인상을 찌푸리는 갈라마브>\n\n우리가 화살을 뽑아 보니 화살대에 쪽지가 붙어 있었소. 그 쪽지에는 쇠창살 뒤로 보이는 오크를 그린 조잡한 그림과 함께 사령관 고르샤크님의 서명이 들어 있었소. 사령관님이 검은바위 나락에 아직 살아 있는 거라면 당신이 찾아 줘야 하오.\n\n함정이라고 했소? 그야 그렇지, 이 답답한 친구야! 그러니까 당신이 가는 거요!", progress = nil, completion = "시간이 많이 없으니 잘 듣게. 내가 지금부터 할 얘기는 극비 사항이고 자네만 알고 있어야 하네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[3982] = {title = "사태 파악", objective = "고르샤크를 보호해야 합니다.", description = "나는 스랄님의 비호로 이곳으로 오게 되었다네. 이 바보 같은 것들이 정말로 나를 붙잡을 수 있었을 거라고 생각하나? 난 정보를 모으기 위해 일부러 잡힌 것이야.\n\n<낮은 목소리로 속삭이는 고르샤크>\n\n아이언포지의 공주가 제왕 타우릿산에게 납치를 당했다네. 브론즈비어드 공주가 바로 이 도시에 있는 것이지! 마그니 영감이 이 소식을 듣고는 심장마비라도 걸릴 뻔했을 걸.\n\n<크게 웃는 고르샤크>\n\n쉿! 방금 들었나? 경비병들이 오는군! 방어 태세를 갖추게!", progress = nil, completion = "아슬아슬했군. 자네 때문에 온 것이었을 거야... 분명 더 쳐들어올 걸세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4001] = {title = "사태 파악", objective = "카란 마이트해머와 대화하여 공주 모이라 브론즈비어드의 납치에 대한 정보를 모은 후, 그 정보를 오그리마에 있는 스랄에게 가져가야 합니다.\n\n고르샤크가 카란이 근처 감방에 갇혀 있다고 말했던 것이 기억납니다.", description = "여태까지는 복도 맞은 편 감방에 있는 카란이라는 드워프와는 얘기를 많이 나누지 못했네. 하지만 간신히 나는... 아니, 우리는 그 사람을 해칠 생각이 없다는 것을 설득하는 데 성공했지.\n\n가서 그 친구와 얘기를 나누고 공주와 그녀를 체포한 자들에 대해 가능한 많은 정보를 모아서 대족장님께 돌아가 전하도록 하게.\n\n스랄님께서는 공주가 해를 입는 걸 원하지 않으시네. 대신 뭔가 원대한 계획을 세우고 계시는데 공주를 아이언포지로 무사히 돌려보내도록 하는 일이 포함된 것 같더군. 카란이 이런 일들을 벌써 다 알고 있다네. 자, 가 보게!", progress = nil, completion = "이건 전쟁으로 분열된 우리 세계의 정치적 기후를 호드가 영원히 바꾸어 놓을 수 있는 기회일세. 잘 듣도록 하게나.\n\n이번 임무는 절대로 실패해선 안 되네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4002] = {title = "동부 왕국", objective = "스랄이 계획한 임무를 맡을 준비가 되었으면 스랄과 다시 한번 대화하십시오.", description = "아주 훌륭한 정보를 가져왔군.\n\n호드에게 유익한 일을 하는 것이 대족장으로서의 내 의무라네. 다음 세대가 절망적인 삶을 강요당하는 일이 없도록 말이지.\n\n미래의 동맹 관계를 형성할 수 있는 기회가 우리 손 안에 들어온 것일세. 드워프들을 도와 주면 동부 왕국과의 관계가 크게 강화될 거야. 그렇기 때문에 자네가 절대로 실패해서는 안 되는 것일세!\n\n준비는 됐는가?", progress = nil, completion = "지금 이후 이 결정에 대한 번복은 있어서는 안 되는 일이라는 것을 명심하게나.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4003] = {title = "공주 구출", objective = "제왕 다그란 타우릿산을 처치하고 그의 사악한 마법에서 공주 모이라 브론즈비어드를 해방시켜야 합니다.", description = "이번 검은무쇠단 드워프들에 대한 공격 작전이 성공할 경우 녀석들의 왕국 전체에 큰 여파를 일으키게 될 걸세.\n\n브론즈비어드 공주가 제왕 다그란 타우릿산에게 잡혀 있네. 반드시 제왕을 제거해 그녀를 해방시켜 주어야 해. 경고해 두겠는데, 이 임무는 지금까지의 일과는 비교도 안 될 정도로 위험하네. 브론즈비어드 공주는 제왕의 조종을 받고 있어서 자네를 보는 즉시 공격할 거야. 그러나 절대로 그녀를 다치게 해선 안 되네!!!", progress = nil, completion = "해내셨군요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4004] = {title = "구출된 공주?", objective = "스랄에게 돌아가야 합니다!", description = "넌 내 남편을 죽인 거야, <race>! 이제 내 아이는 아버지도 없이 이 세상에 태어나게 될 거라고.\n\n<당신을 지목하는 모이라 공주>\n\n분명히 말해 두는데, 이 아이가 아이언포지 왕국의 다음 통치자가 될 거다. 이 그릇된 행동에 대한 대가로 너와 너희 족속을 세상 끝날까지 샅샅이 찾아 처치하고 말 거야!\n\n<제왕 타우릿산이 공주에게 건 마법의 효과가 아직 완전히 가시지 않은 것이 아닌가 생각됩니다.>\n\n날 혼자 있게 내버려둬, <race>. 너희 대족장이 분명히 이 일에 대해서 듣고 안달일 거야.", progress = nil, completion = "&lt;소식을 전해 듣고 당황해 하는 스랄&gt;\n\n이제 새로운 위협의 조짐이 보이는군. 마그니의 시대는 저물어 가고 아직 태어나지 않은 검은무쇠단 드워프가 아이언포지의 통치자가 될 게야.\n\n그대는 내가 지시한 임무를 잘 완수했으니 그에 대한 보상을 받을 것이야.\n\n이제 가 보도록! 난 실바나스와 케른과 상의해야겠다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n스랄의 결의오그리마의 눈\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4005] = {title = "아쿠에멘타스", objective = "아쿠오르의 책, 은백색 발톱, 그리고 강철나무 심장을 가지고 타나리스로 가십시오.\n\n아쿠오르의 책을 사용해 아쿠에멘타스를 소환해야 합니다.\n\n토템을 완성하면 마샬의 야영지에 있는 J.D. 콜리에게 가져가야 합니다.", description = "이 보급품 가방을 가지고 타나리스로 가시오. 해적단 소굴이라는 곳으로 가서 원형으로 놓인 돌을 찾아야 하오. 가장 동쪽에 인접한 반도에서 그 비밀을 찾을 수 있을 것이오.\n\n그 원 안에서 아쿠오르의 책을 읽으면 어떤 생물이 나타나는데, 그대가 모아온 물건을 불바람과 싸울 때 필요한 토템으로 만들어 줄 것이오.\n\n아쿠에멘타스가 잠에서 깨어나면 아주 불쾌해 하겠지만 그가 토템을 만들려면 그대는 반드시 그 원 안에 있어야 한다는 것을 명심하시오.", progress = "돌아오셨군요. 흠... 그 토템을 잠깐 보여주세요.", completion = "불바람이라...\n\n네. 까맣게 타버린 분화구 중심부에 강력한 정령이 살고 있다는 것은 알고 있어요. 누구도 그 정령을 둘러싼 강력한 오라 안으로 파고들지 못해 우린 그저 멀리하기만 하지요. 많은 친구들이 그와 맞서다 길에서 밑에 있는 땅으로 떨어져 버렸어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4021] = {title = "반격!", objective = "크로스로드 서쪽에 있는 렉타르 데스게이트에게 크롬자르의 깃발 조각을 가져가야 합니다.", description = "콜카르일족에 대한 자네의 성공은 호드에서 크게 치하하는 바일세. 하지만 살아남은 콜카르일족이 완전히 미쳐 버렸다네. 콜카르 파견대가 복수를 위해 그들의 고향인 잊혀진 땅을 떠나 불모의 땅으로 왔다는 보고가 들어왔네. 최근에 받은 보고에 의하면 녀석들이 지금 서쪽에서 이곳 감시탑 쪽을 향해 달려 오고 있다고 하네!\n\n콜카르 침입자들에 맞서 불모의 땅을 지켜내야 하네. 놈들을 계속 처치하다 보면 그들의 우두머리인 장군 크롬자르가 나타날 걸세. 그를 해치우고 그 증거로 내게 녀석의 깃발 조각을 가져오게.\n\n우린 자네를 믿네, <name>.", progress = "깃발을 가져왔나?", completion = "해냈군! 콜카르를 물리쳤어!\n\n자네가 이곳에서 세운 공은 내 반드시 스랄님께 보고하도록 하지.\n\n어깨를 당당히 펴, 용맹스런 &lt;class&gt; 친구! 자네는 자기 자신은 물론이고, 호드 전체를 명예롭게 한 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4022] = {title = "화염의 맛", objective = "벨라로크 윈드블레이드에게서 받은 검은용군단 허물을 키루스 테레펜터스에게 보여줘야 합니다.", description = "용군단은 네가 이글거리는 협곡에서 한 일에 대해 알고 있다.\n\n내게 보여 줘. 허물 말이야, 이 바보 같은 <race>.", progress = "<두 눈이 불타는 구의 형상이 되는 키루스>", completion = "&lt;허물을 살펴보는 키루스&gt;\n\n너는 네가 완전히 쓸모없지는 않다는 사실을 입증했다, 나약한 &lt;race&gt;|1이여;여;.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4023] = {title = "화염의 맛", objective = "키루스 테레펜터스에게 자신의 가치를 증명해 보여야 합니다.\n\n키루스가 이미 당신이 가치가 없다는 사실을 알고 있는 것 같은 느낌이 듭니다.", description = "용군단을 찾는 것인가? 내게 너의 가치를 입증하라, 나약한 <race>.", progress = "<두 눈이 불타는 구의 형상이 되는 키루스>", completion = "&lt;허물을 살펴보는 키루스&gt;\n\n너는 네가 완전히 쓸모없지는 않다는 사실을 입증했다, 나약한 &lt;race&gt;|1이여;여;.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4024] = {title = "화염의 맛", objective = "검은바위 나락으로 가서 밸가르를 처치하십시오.\n\n이 거인이 검은바위 나락 내에 살고 있다는 것만 알고 있으며 밸가르의 시체에 변형된 검은용군단 허물을 사용해 불의 정수를 추출해야만 합니다.\n\n키루스 테레펜터스에게 담겨진 불의 정수를 가져가야 합니다.", description = "난 불의 산에서 나오는 격렬한 화염을 맛보고 싶다. 검은바위가 녹아 들어가는 화염의 폭포를 직접 맞아 보고 싶다. 그 정기, 그 격렬한 화염이 바로 내가 원하는 것이다.\n\n검은바위 나락에는 라그나로스의 불로 태어난 밸가르라는 순수한 화염의 존재가 살고 있다. 밸가르를 처치하고 그의 불타는 시체에서 그 내면의 불 일부를 내게 가져와라.\n\n그의 시체에 검은용군단 허물을 사용해 내면의 화염을 안전하게 추출하도록 해라. 성공하면 보상받게 될 것이다.", progress = "거인을 쓰러뜨렸나?", completion = "&lt;불의 정수를 낚아채는 키루스&gt;\n\n그래!\n\n보상을 가지고 어서 가라. 내 눈 앞에서 당장 사라져!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n혈암 단망토고룡가죽 어깨갑옷떡갈나무 장식띠\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4041] = {title = "앞날의 비약", objective = "에보뿌리만 가져오쇼. 그럼 당장 앞날의 비약을 만들어 줄 테니까 말이야.\n\n약초 채집과 연금술에 대해서라면 이 몸이 또 일가견이 있거든. 못 믿겠소? 이거 원, 점심으로 먹으려던 치즈를 금으로 바꾼 이야기를 들려줘야 믿을라나... 어이, 이보라고. 어딜 가는 거요?", description = nil, progress = "에보뿌리만 가져오쇼. 그럼 당장 앞날의 비약을 만들어 줄 테니까 말이야.\n\n약초 채집과 연금술에 대해서라면 이 몸이 또 일가견이 있거든. 못 믿겠소? 이거 원, 점심으로 먹으려던 치즈를 금으로 바꾼 이야기를 들려줘야 믿을라나... 어이, 이보라고. 어딜 가는 거요?", completion = "그러니까 그 늙은 미블론에게 단단히 박혀 있던 이놈을 뽑아 왔단 거 아니오?", rewards = "다음과 같은 것들을 받습니다:\n\n앞날의 비약"},
[4061] = {title = "기계들의 봉기", objective = "불타는 평원으로 가서 제사장 테오도라 뮬바다니아에게 가져갈 부서진 원소 파편 10개를 모아야 합니다.\n\n그 지역의 골렘과 정령들에게서 이 파편을 구할 수 있을 거라고 테오도라가 말했던 것이 기억납니다.", description = "우리가 이글거리는 협곡에 처음 급습했을 때 기계들이 나타났었네. 더 자세히 조사한 결과, 그 기계들이 불타는 평원에서 수입되고 있다는 사실을 알게 됐지. 아마 검은바위 나락에서 오는걸게야. 바로 이 때문에 자네가 필요한 것일세.\n\n자네의 첫 임무는 불타는 평원으로 가서 그 지역의 바위 골렘류나 하급 바위 정령류에게서 원소 파편을 구해 오는 것이야. 충분한 양을 모아 내게 가져오면 녀석들의 근원을 파악할 수 있을 것일세.", progress = "이번 임무를 가볍게 여기지 말게!", completion = "&lt;파편을 자신의 앞에 늘어놓는 테오도라&gt;\n\n&lt;커다란 단안경으로 파편을 꼼꼼히 살펴보는 테오도라&gt;\n\n재미있군. 이 파편들 각각의 구조적 기초에... 약자가 새겨져 있어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4062] = {title = "기계들의 봉기", objective = "로트윌 베리아투스에게 원소 파편 견본을 가져가야 합니다.\n\n테오도라가 로트윌은 동쪽 야영지에 있다고 얘기했던 것이 기억납니다.", description = "G.L.A.\n\n이 '약자'가 정령 파편에 새겨져 있군. 약자 밑에는 어떤 계급 표시 같은 게 있네. 자네가 불타는 평원에서 파괴한 기계들은 'IV 계급' 이었지만 아마도 이건 낮은 계급일 것일세.\n\n이 파편 견본을 동쪽 야영지에 있는 로트윌 베리아투스에게 가져가 보시게. 그는 정령과학 분야에서 꽤 이름이 높은 학자이니 우리 연구를 도와 줄 수 있을지 모르네.", progress = "뭘 가져온 거죠?", completion = "&lt;얼굴이 하얗게 변하는 로트윌&gt;\n\n나... 난 이 표시들이 뭔지 알아요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4063] = {title = "기계들의 봉기", objective = "골렘 군주 아젤마크를 찾아 처치하고 그 증거로 그의 머리카락을 로트윌에게 가져가야 합니다. 그리고 아젤마크를 호위하는 재앙의 피조물과 맹위의 전투골렘들에게서 온전한 원소핵 10개도 모아야 합니다.", description = "이건... 아젤마크일 리가 없어! 아젤마크는 10년 전에 살해당했단 말이에요. 어떻게 확신하느냐고요? 아젤마크를 처치한 자가 바로 나니까요.\n\n녀석은 아주 비열한 드워프였죠. 내가 평생 동안 이룬 업적을 자신의 사악한 목적에 악용하려고 수단 방법을 가리지 않았어요. 사악한 자들은 항상 정의를 피해 가는 길을 찾아내는 것 같군요.\n\n이게 분명 아젤마크의 솜씨라면 녀석을 반드시 없애야 해요. 그러려면 녀석이 가장 최근에 만든 것들의 견본이 필요해요. 제대로 된 견본만 있다면 이 봉기를 제압할 수 있을지도 몰라요. 검은바위 나락에 아젤마크가 부하들의 경호를 받으며 있을 거예요.", progress = "그 친구가 맞던가요? 녀석이 정말로 살아 있던가요?", completion = "이게 뭐야?!? 이 머리카락은 왠지 자연스럽지 않잖아. 이건 검은무쇠단이 만든 아젤마크의 그림자, 또 다른 기계로군요! 당신이 이 아젤마크를 처치했으니 얼마 가지 않아 이 기계의 자리를 메울 새 기계가 나타나겠군요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n푸른달 아미스기우제 망토현무암 미늘 갑옷용암 판금 건틀릿\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4081] = {title = "죽음의 본보기: 검은무쇠단 드워프", objective = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오!\n\n장군 고어투스가 성난모루단 보초 15명, 성난모루단 교도관 10명, 성난모루단 보병 5명을 처치해 달라고 부탁했습니다. 임무를 완수하면 장군 고어투스에게 돌아가십시오.", description = "카르가스 원정대의 사령관, 장군 고어투스의 명령:\n\n검은바위 나락 내에서 사령관 앵거포지의 세력을 섬멸하라.\n\n앵거포지의 부하들은 무자비한 살인마들로, 카르가스 원정대의 제 109 사단을 대량 학살한 장본인들이다. 영웅들은 이 짐승 같은 놈들을 상대할 때 극히 조심하기 바란다.\n\n검은바위 나락에 있는 사령관 앵거포지의 부대의 최전선을 무너뜨리는 자에게는 포상을 내릴 것이다.", progress = nil, completion = "이번 첫 공격으로 앵거포지가 아주 놀랐을 걸세. 자, 어서 가 보게, 병사. 나는 해야 할 일이 있고, 세워야 할 전투 계획과 쳐부수어야 할 적이 있단 말일세!\n\n일을 더 구하려면 현상수배 표지판을 찾아보게.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4082] = {title = "죽음의 본보기: 검은무쇠단 고위 관리", objective = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오!\n\n장군 고어투스가 성난모루단 간호병 10명, 성난모루단 병사 10명, 그리고 성난모루단 장교 10명을 처치해 달라고 부탁했습니다. 임무를 완수하면 고어투스에게 돌아가십시오.", description = "카르가스 원정대의 사령관, 장군 고어투스의 명령:\n\n카르가스 원정대 정찰 사단의 지휘관, 암살단장 렉스로트가 검은무쇠단 고위 관리들의 소재에 대한 소식을 입수하여 돌아왔다. 나락의 잠겨진 문을 지나, 도시 중심부에서 우리 군대를 전멸하기 위한 군사 훈련을 하고 있다. 검은바위 나락으로 가서 녀석들을 제거하라!\n\n이번 임무를 완수하면 보상을 받게 될 것이다.", progress = nil, completion = "앵거포지는 분명... 화가 나 있을 거야. 세 번째 보상을 받게 되거든 날 다시 찾아오도록 하게. 그때 앵거포지 척살 작전을 개시하도록 하지. 이 작전의 세부 내용은 아직 말할 수 없지만 분명히 누군가 죽게 된다는 것만은 알아 두게나.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4083] = {title = "유령의 성배", objective = "유령의 성배가 마치 죽어가는 심장의 고동에 맞추어 춤을 추듯이 천천히 움직이면서 공중에 떠다닙니다.", description = nil, progress = "유령의 성배가 마치 죽어가는 심장의 고동에 맞추어 춤을 추듯이 천천히 움직이면서 공중에 떠다닙니다.", completion = "보석들이 아무 소리도 내지 않고 성배 안으로 떨어집니다...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4084] = {title = "은색 심장", objective = "악령의 숲에 있는 에리단 블루윈드에게 은백색 발톱 11개와 강철나무 심장 1개를 가져가야 합니다.", description = "그대가 말하는 사람이 누구인지 모르겠군.\n\n하지만 그 친구가 나를 찾아오는 길이었다면 무엇을 원했는지 알고 있으니 걱정하지 마시오.\n\n운고로 분화구 중심부에는 가장 순수한 형태의 악이 살고 있소. 이 악은 불바람이라 불리는 정령의 모습을 하고 있는데, 오라로 보호되어 있어서 아무도 이 오라를 제거하지 못하지...\n\n아무도 제거하지 못하지만 충분한 힘을 가진 사람이라면 할 수 있소. 내가 이 힘을 그대에게 알려 줄 수 있소.\n\n먼저 내가 시키는 대로 악령의 숲에 사는 생물들에게서 은백색 발톱 11개와 강철나무 심장 1개를 구한 후 다시 돌아오시오.", progress = "불바람을 물리치는 데 필요한 힘에 대해 더 자세히 설명하려면 먼저 내가 필요로 하는 것들을 가져와야 하오.", completion = "좋소. 그대가 친구를 도우려 한다는게 진심이라는 게 확인됐군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4101] = {title = "악령의 숲 정화", objective = "악령의 숲에 있는 아라탄드리스 실버스카이에게 핏빛 호박석 15개를 가져가야 합니다.", description = "현재 악령의 숲에 생명을 주는 식물들이 타락에 찌들어 고통 받고 있어요. 제가 타락을 정화하는 방법을 알고 있지만 그 방법에 대해 전혀 무지하거나 믿음이 없는 자들에게는 알려줄 수 없어요. 그대가 진정 세나리온 의회의 대의에 따르고자 한다면 제게 입증해 보이세요!\n\n북쪽으로 가면 강철나무 굴이 있어요. 그곳에 있는 굽이나무 정령들은 정화로도 구제할 수 없는 지경에 이르렀지요. 가서 핏빛 호박석이라고 하는 정령의 수액을 가지고 오세요. 그걸 연구하면 숲의 다른 생명들을 구할 수 있을지도 몰라요.", progress = "악령의 숲이 괴로워하고 있다는 건 제가 잘 알아요. 저도 똑같이 고통을 겪기 때문이에요! 저는 신념을 굳게 지켜야 해요. 제가 알고 있는 지식이 악당들의 손에 넘어간다면 악령의 숲 전체에 재앙이 닥칠 거예요.\n\n굽이나무 정령들을 물리친 후 그들에게서 핏빛 호박석을 뽑아오면 그대를 믿고 이 재앙에 맞설 방법을 함께 찾아보도록 하죠.", completion = "이 핏빛 호박석은 악령의 숲의 타락을 정화할 방법을 연구하는데 사용할 거예요. 그대는 세나리온 의회를 위해서라면 어떤 일이라도 감수하겠다는 것을 입증해 보였어요. 이제 당신을 믿겠어요.\n\n정령을 해치는 것이 그대의 뜻을 증명해 보일 수 있는 방법이라는 게 이상했겠지만 수많은 생명체들을 구하려면 결국 우리가 선택한 방법이 최선이었다는 걸 알게 될 거예요. 드디어 고약을 만들어 그대와 함께 생명을 보존할 수 있겠군요.\n\n 이제 악령의 숲을 정화할 때가 온 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4102] = {title = "악령의 숲 정화", objective = "악령의 숲에 있는 메이베스 리버브리즈에게 핏빛 호박석 15개를 가져가야 합니다.", description = "현재 악령의 숲에 생명을 주는 식물들이 타락에 찌들어 고통 받고 있어요. 제가 타락을 정화하는 방법을 알고 있지만 그 방법에 대해 전혀 무지하거나 믿음이 없는 자들에게는 알려줄 수 없어요. 당신이 진정 세나리온 의회의 대의에 따르고자 한다면 제게 입증해 보이세요!\n\n북쪽으로 가면 강철나무 굴이 있어요. 그곳에 있는 굽이나무 정령들은 정화로도 구제할 수 없는 지경에 이르렀지요. 가서 핏빛 호박석이라고 하는 정령의 수액을 가지고 오세요. 그걸 연구하면 숲의 다른 생명들을 구할 수 있을지도 몰라요.", progress = "악령의 숲이 괴로워하고 있다는 건 제가 잘 알아요. 저도 똑같이 고통을 겪기 때문이에요! 만약 제가 알고 있는 지식이 악당들의 손에 넘어 가기라도 한다면 악령의 숲 전체에 재앙이 닥칠 거예요. 그래서 저는 신념을 굳게 지켜야 해요.\n\n굽이나무 정령들을 물리친 후 그들에게서 핏빛 호박석을 뽑아오면 그대를 믿고 이 재앙에 맞설 방법을 함께 찾아보도록 하죠.", completion = "이 핏빛 호박석은 악령의 숲의 타락을 정화할 방법을 연구하는데 사용할 거예요. 그대는 세나리온 의회를 위해서라면 어떤 일이라도 감수하겠다는 것을 입증해 보였어요. 이제 그대를 믿겠어요.\n\n정령을 해치는 것이 그대의 뜻을 증명해 보일 수 있는 방법이라는 게 이상했겠지만 수많은 생명체들을 구하려면 결국 우리가 선택한 방법이 최선이었다는 걸 알게 될 거예요. 드디어 고약을 만들어 그대와 함께 생명을 보존할 수 있겠군요.\n\n 이제 악령의 숲을 정화할 때가 온 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4103] = {title = "사냥을 통한 고약 확보", objective = "세나리온 등불을 지니고 있으면 정의를 위해 처치한 타락한 짐승들에게서 오염된 영혼의 조각를 볼 수 있어요. 이 조각을 갈아서 세나리온 식물 고약을 만드는 재료로 쓰죠. 그 고약을 사용하면 오염된 식물들을 다시 건강하게 되살릴 수 있을 거예요.\n\n그 조각을 가져오면 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "세나리온 등불을 지니고 있으면 정의를 위해 처치한 타락한 짐승들에게서 오염된 영혼의 조각를 볼 수 있어요. 이 조각을 갈아서 세나리온 식물 고약을 만드는 재료로 쓰죠. 그 고약을 사용하면 오염된 식물들을 다시 건강하게 되살릴 수 있을 거예요.\n\n그 조각을 가져오면 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", completion = "훌륭해요. 여기 약속한 세나리온 식물 고약을 드릴게요. 악령의 숲을 샅샅이 뒤져 오염된 식물을 찾으세요! 그리고 발견되는 즉시 제가 드린 고약을 사용해 정화시켜 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4104] = {title = "채광을 통한 고약 확보", objective = "악령의 숲에서 채광할 때 세나리온 등불을 가지고 있으면 광맥을 오염시키는 황산을 볼 수 있어요. 제가 그 황산을 정화시켜 세나리온 식물 고약의 재료로 바꾸는 방법을 알고 있어요. 숲에서 오염된 식물들을 찾으면 이 고약을 사용하여 정화하시면 되요.\n\n제게 오염된 황산을 모아 주시면 그 대가로 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "악령의 숲에서 채광할 때 세나리온 등불을 가지고 있으면 광맥을 오염시키는 황산을 볼 수 있어요. 제가 그 황산을 정화시켜 세나리온 식물 고약의 재료로 바꾸는 방법을 알고 있어요. 숲에서 오염된 식물들을 찾으면 이 고약을 사용하여 정화하시면 되요.\n\n제게 오염된 황산을 모아 주시면 그 대가로 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", completion = "좋아요. 여기 약속한 세나리온 식물 고약을 드리죠. 악령의 숲에 있는 광산에서 광석을 채집하다가 황산을 더 찾게 되면 모아두었다가 나중에 제게 가져다주세요! 많이 찾아올수록 고약을 더 많이 만들 수 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4105] = {title = "약초채집을 통한 고약 확보", objective = "숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있어요. 악령의 숲의 타락이 낳은 부산물이죠. 저는 이곳에서 일하다가 지옥덩굴을 정화용 시약으로 만드는 방법을 알아냈어요. 세나리온 식물 고약이라는 이름을 붙였답니다.\n\n악령의 숲에서 등불을 들고 약초를 모으다 보면 지옥덩굴을 찾게 될 거예요. 지옥덩굴을 가지고 오면 제가 미리 만들어둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있어요. 악령의 숲의 타락이 낳은 부산물이죠. 저는 이곳에서 일하다가 지옥덩굴을 정화용 시약으로 만드는 방법을 알아냈어요. 세나리온 식물 고약이라는 이름을 붙였답니다.\n\n악령의 숲에서 등불을 들고 약초를 모으다 보면 지옥덩굴을 찾게 될 거예요. 지옥덩굴을 가지고 오면 제가 미리 만들어둔 세나리온 식물 고약을 드리겠어요.", completion = "아주 잘하셨어요. 이 지옥덩굴을 정화하면 악령의 숲을 원래대로 되돌려 놓을 수 있을 거예요. 자, 세나리온 식물 고약을 들고 숲으로 가보세요. 지금 대지모신은 타락으로부터 구해줄 &lt;race&gt;의 도움을 절실히 기다리고 있어요!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4106] = {title = "무두질을 통한 고약 확보", objective = "숙련된 무두장이가 세나리온 등불을 지니고 있으면 악령의 숲에서 모은 짐승의 가죽에서 오염된 부분을 찾아낼 수 있어요. 저는 이 쓸모 없어 보이는 조각들을 두꺼운 반죽으로 만들어 세나리온 식물 고약의 촉진제로 사용하지요. 이 악령의 숲에서 사냥한 짐승들의 가죽을 벗길 때는 꼭 이 등불을 지니고 계세요!\n\n오염된 가죽 조각을 모으면 제게 가지고 오세요. 그러면 제가 미리 만들어둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "숙련된 무두장이가 세나리온 등불을 지니고 있으면 악령의 숲에서 모은 짐승의 가죽에서 오염된 부분을 찾아낼 수 있어요. 저는 이 쓸모 없어 보이는 조각들을 두꺼운 반죽으로 만들어 세나리온 식물 고약의 촉진제로 사용하지요. 이 악령의 숲에서 사냥한 짐승들의 가죽을 벗길 때는 꼭 이 등불을 지니고 계세요!\n\n오염된 가죽 조각을 모으면 제게 가지고 오세요. 그러면 제가 미리 만들어둔 세나리온 식물 고약을 드리겠어요.", completion = "맞아요! 바로 이거예요. 이 세나리온 식물 고약을 가지고 가서 악령의 숲을 타락에서 구해주세요. 인내가 필요할 거예요!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4107] = {title = "마력 추출을 통한 고약 확보", objective = "마력이 풀린 물건의 힘은 그 안에서 만들어지는 정수로 느낄 수 있지요. 저는 마법부여사들이 사용하는 천연 정수를 세나리온 식물 고약을 만드는 데 알맞은 시약으로 바꾸는 방법을 알아냈어요. 여기에는 세나리온 등불이 필요하지 않아요. 마력이 풀려 하급 황천의 정수가 나오는 물건이면 되죠.\n\n하급 황천의 정수만 있으면 정말 좋을 텐데! 그 정수는 굉장히 강력해서 조금만 구해도 큰 일을 해낼 수가 있거든요. 가져다주시면 보답으로 세나리온 식물 고약을 드리죠.", description = nil, progress = "마력이 풀린 물건의 힘은 그 안에서 만들어지는 정수로 느낄 수 있지요. 저는 마법부여사들이 사용하는 천연 정수를 세나리온 식물 고약을 만드는 데 알맞은 시약으로 바꾸는 방법을 알아냈어요. 여기에는 세나리온 등불이 필요하지 않아요. 마력이 풀려 하급 황천의 정수가 나오는 물건이면 되죠.\n\n하급 황천의 정수만 있으면 정말 좋을 텐데! 그 정수는 굉장히 강력해서 조금만 구해도 큰 일을 해낼 수가 있거든요. 가져다주시면 보답으로 세나리온 식물 고약을 드리죠.", completion = "여기 세나리온 식물 고약을 조금 드리죠. 이 정도에는 하급 황천의 정수가 하나만 들어간답니다. 위험하고 날카로운 칼을 무딘 쟁기로 만들어 버리는 데는 이 정수만큼 강력한 물건도 없지요. 고약이 더 필요하면 절 다시 찾아오세요!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4108] = {title = "사냥을 통한 고약 확보", objective = "세나리온 등불을 지니고 있으면 정의를 위해 처치한 타락한 짐승들에게서 오염된 영혼의 조각를 볼 수 있어요. 이 조각을 갈아서 세나리온 식물 고약을 만드는 재료로 쓰죠. 그 고약을 사용하면 오염된 식물들을 다시 건강하게 되살릴 수 있을 거예요.\n\n그 조각을 가져다주면 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "세나리온 등불을 지니고 있으면 정의를 위해 처치한 타락한 짐승들에게서 오염된 영혼의 조각를 볼 수 있어요. 이 조각을 갈아서 세나리온 식물 고약을 만드는 재료로 쓰죠. 그 고약을 사용하면 오염된 식물들을 다시 건강하게 되살릴 수 있을 거예요.\n\n그 조각을 가져다주면 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", completion = "훌륭해요. 여기 세나리온 식물 고약을 드릴게요. 악령의 숲을 샅샅이 뒤져 오염된 식물을 찾으세요! 그리고 발견되는 즉시 제가 드린 고약을 사용해 정화시켜 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4109] = {title = "채광을 통한 고약 확보", objective = "악령의 숲에서 채광할 때 세나리온 등불을 가지고 있으면 광맥을 오염시키는 황산을 볼 수 있어요. 제가 그 황산을 정화시켜 세나리온 식물 고약의 재료로 바꾸는 방법을 알고 있어요. 숲에서 오염된 식물들을 찾으면 이 고약을 사용해 정화해 주세요.\n\n오염된 황산을 모아오면 그 대가로 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "악령의 숲에서 채광할 때 세나리온 등불을 가지고 있으면 광맥을 오염시키는 황산을 볼 수 있어요. 제가 그 황산을 정화시켜 세나리온 식물 고약의 재료로 바꾸는 방법을 알고 있어요. 숲에서 오염된 식물들을 찾으면 이 고약을 사용해 정화해 주세요.\n\n오염된 황산을 모아오면 그 대가로 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", completion = "좋아요. 여기 약속한대로 세나리온 식물 고약을 드릴게요. 악령의 숲에서 채광을 하다가 황산을 더 찾게 되면 나중에 제게 꼭 전해 주세요! 많이 찾아올수록 고약을 더 많이 만들 수 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4110] = {title = "약초채집을 통한 고약 확보", objective = "숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있어요. 악령의 숲의 타락이 낳은 부산물을 말이에요. 저는 이곳에서 일하다가 지옥덩굴을 정화용 시약으로 만드는 방법을 알아냈어요. 지금은 세나리온 식물 고약이라는 이름으로 사용되죠.\n\n악령의 숲에서 등불을 들고 약초를 모으다 보면 지옥덩굴을 찾게 될 거예요. 지옥덩굴을 가지고 오면 제가 미리 만들어둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있어요. 악령의 숲의 타락이 낳은 부산물을 말이에요. 저는 이곳에서 일하다가 지옥덩굴을 정화용 시약으로 만드는 방법을 알아냈어요. 지금은 세나리온 식물 고약이라는 이름으로 사용되죠.\n\n악령의 숲에서 등불을 들고 약초를 모으다 보면 지옥덩굴을 찾게 될 거예요. 지옥덩굴을 가지고 오면 제가 미리 만들어둔 세나리온 식물 고약을 드리겠어요.", completion = "아주 잘하셨어요. 이 지옥덩굴을 정화하면 악령의 숲을 원래대로 되돌려 놓을 수 있을 거예요. 여기 약속대로 세나리온 식물 고약을 드리지요. 얼른 숲으로 가보세요. 타락의 위험에 처한 이 땅은 한 명이라도 많은 &lt;race&gt;의 도움을 절실히 기다리고 있으니까요!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4111] = {title = "무두질을 통한 고약 확보", objective = "숙련된 무두장이가 세나리온 등불을 지니고 있으면 악령의 숲에서 모은 짐승의 가죽에서 오염된 부분을 찾아낼 수 있어요. 저는 이 쓸모 없어 보이는 조각들을 두꺼운 반죽으로 만들어 세나리온 식물 고약의 촉진제로 사용하지요. 이곳 악령의 숲에서 사냥한 짐승들의 가죽을 벗길 때는 꼭 등불을 지니고 계세요!\n\n오염된 조각들을 모으면 제게 가지고 오세요. 그러면 제가 미리 만들어둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "숙련된 무두장이가 세나리온 등불을 지니고 있으면 악령의 숲에서 모은 짐승의 가죽에서 오염된 부분을 찾아낼 수 있어요. 저는 이 쓸모 없어 보이는 조각들을 두꺼운 반죽으로 만들어 세나리온 식물 고약의 촉진제로 사용하지요. 이곳 악령의 숲에서 사냥한 짐승들의 가죽을 벗길 때는 꼭 등불을 지니고 계세요!\n\n오염된 조각들을 모으면 제게 가지고 오세요. 그러면 제가 미리 만들어둔 세나리온 식물 고약을 드리겠어요.", completion = "제대로 구해오셨군요. 약속한 세나리온 식물 고약을 드릴 테니 악령의 숲으로 가지고 가서 그곳의 무고한 생물들을 타락의 위험에서 구해주세요. 인내심을 가져야 할 거예요. &lt;race&gt;|1이여;여;!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4112] = {title = "마력 추출을 통한 고약 확보", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[4113] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 고약한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 고약한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4114] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4115] = {title = "오염된 바람꽃", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[4116] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4117] = {title = "오염된 채찍뿌리", objective = "채찍뿌리인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 땅 위로 드러난 뿌리는 거칠고 단단한 가죽처럼 보입니다. 식물에는 끈적끈적한 실 같은 것도 매달려 있습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "채찍뿌리인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 땅 위로 드러난 뿌리는 거칠고 단단한 가죽처럼 보입니다. 식물에는 끈적끈적한 실 같은 것도 매달려 있습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "채찍뿌리에 세나리온 식물 고약 세 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4118] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4119] = {title = "오염된 어둠용풀", objective = "어둠용풀인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어서 독성을 품게 된 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "어둠용풀인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어서 독성을 품게 된 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "어둠용풀에 세나리온 식물 고약 네 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4120] = {title = "타락의 힘", objective = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프가 악령의 숲에 있는 성난발톱불곰 12마리와 갈퀴발톱 악령발늑대 12마리를 처치해 달라고 부탁했습니다.", description = "난 사냥꾼으로서 내 적들에게서 힘으로 우열을 다투는데 지지 않으려고 애쓴다네. 단지 적을 잘 아는 것만으로 전투의 승기를 잡을 수도 있지.\n\n잿빛 골짜기의 북쪽에 악령의 숲이라고 하는 곳이 있는데, 그곳의 생물들은 악이라 불리는 물질에 의해 오염되었다네. 그곳에 사는 곰과 늑대들이 그것 때문에 미쳐 버렸는데 내 생각에는 힘도 더욱 세진 것 같네.\n\n자, 가게나. 악령의 숲으로 가서 이 야수들과 직접 맞서 보게. 녀석들이 정말 내가 생각하는 것만큼 강한지 자네 힘으로 직접 알아보게.", progress = nil, completion = "자네가 묘사한 대로라면 이 짐승들은 지각없이 흉포한 것 같군...\n\n정신 바짝 차리게. 이 타락에 대해서 더 자세히 알아보는 것이 자네에게 좋을 걸세. 언제나 자신의 적을 알아두란 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4121] = {title = "곤경", objective = "포로인 그랄크 로크럽을 호송해 불타는 평원을 지나고 검은바위 산을 넘어 이글거리는 협곡으로 가야 합니다.\n\n반대편에서 렉스로트의 부하들이 기다리다가 그랄크 로크럽을 인계받도록 하겠다고 렉스로트가 말했던 것이 기억납니다.\n\n또한 토륨 족쇄를 렉스로트에게 전해주어야 합니다.", description = "정말 나를 포박한 채로 집결지까지 갈 수 있을 것 같나? 네가 정말 경비가 삼엄한 검은바위 요새로 침입해서 그 누구에게도 들키지 않고 그들의 귀중한 정보 제공자를 납치해 갈 수 있을 거 같나?\n\n그러기도 전에 아마 네가 죽게 될 거다!", progress = "이 쓰레기 같은 물건은 내가 가져 가지.", completion = "자네의 영웅적인 행위는 널리 알려지게 될 걸세. 자네는 충분히 이 보상을 받을 자격이 있군. 이제 장군께서 마지막 임무에 대해 자네와 대화하고 싶어하실 걸세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4122] = {title = "그랄크 로크럽", objective = "불타는 평원으로 가서 그랄크 로크럽을 찾아야 합니다. 렉스로트가 그를 마지막으로 거대한 검은바위 요새에서 보았다고 말했던 것이 기억납니다.\n\n그랄크 로크럽을 찾으면 토륨 족쇄를 사용해 그를 포박한 뒤 다시 검은바위 산을 지나 이글거리는 협곡으로 데려가야 합니다. 렉스로트의 부하들이 반대편에서 기다리고 있다가 그랄크를 인계받을 것입니다.\n\n제공된 아이템: \n", description = "나는 이글거리는 협곡을 가로지르고 산을 넘어 불타는 평원까지 녀석을 추적해 갔지. 그 반역자 그랄크 로크럽은 검은바위부족 오크의 평상시 활동에 대한 중요한 정보를 유출하다가 현장에서 걸려 버렸고 말이야.\n\n이제 녀석은 불타는 평원에서 검은무쇠단의 보호를 받으며 편안히 지내고 있네. 적어도 녀석은 그렇게 생각하지.\n\n이 족쇄를 받게. 그랄크를 찾아 이 족쇄를 채운 다음, 녀석을 데리고 검은바위 산을 통과하게. 그렇게만 하면 보상은 자네 것일세.", progress = nil, completion = "검은바위부족 군단에 참여하여 우리가 얻게 되는 힘을 모르겠나?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4123] = {title = "산의 정수", objective = "불타는 평원에 있는 맥스워트 우버글린트에게 산의 정수를 가져가야 합니다.", description = "나는 수년 동안 어떤 특별한 보석을 찾아다녔지. 산의 정수라는 보석인데, 크기가 당신 주먹만하다구! 검은무쇠단 드워프 녀석들이 자기들 금고에 그 보석을 넣고 금고를 잠가 버렸지. 내가 아무리 사정을 해도 내게 팔려고 하지를 않을 것이라서 힘으로라도 빼앗을 작정이오.\n\n검은바위 나락의 지하층까지 싸워 내려가서 비밀 금고를 열고 산의 정수를 손에 넣으시오. 그러려면 보초 둠그립을 처치해야 하는데 녀석은 검은 금고의 유물 상자를 모조리 열어 보기 전에는 나타나지 않을 것이오!\n\n행운을 빌겠소이다.", progress = "산의 정수를 가져왔나? 내게는 값으로 따질 수 없을 만큼 귀한 물건이라구.", completion = "산의 정수를 가져왔군! 놀라워! 내가 상상했던 것보다도 더 아름답군!\n\n자, 이건 수고에 대한 대가니 받으라구!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4124] = {title = "실종된 안내원", objective = "페더문 요새에 있는 긴로 하트킨들과 대화해야 합니다.", description = "내 동료 중 한 명인 긴로 하트킨들이 어떤 안내원과 그가 가지고 있던 소포의 행방을 찾고 있는데 도움이 필요하오. 안내원이 실종된 지는 약 일 주일 정도 됐고, 우리가 직접 찾아도 봤지만 모두 허사였소이다. 그래서 지금 전혀 손을 못 쓰고 있는 상황이오. 진작에 안내원이 실종된 사실을 밝혔어야 했는데 그러질 못했소.\n\n시간과 여력이 있다면 긴로와 얘기를 나눠보도록 하시오. 그 친군 이 요새 안 어딘가에 있을 것이오. 어쩌면 자기 방에 있을지도 모르겠군.", progress = nil, completion = "라트로니쿠스 친구가 보낸 모양이군. 지금 와서야 별 승산이 없어 보이기는 하지만 그대가 도움을 주겠다면 기꺼이 받겠소. 솔직히... 이번 일에 전심할 수 있었으면 좋겠소. 날마다 페랄라스의 황무지로 나가 라스칼의 행방을 찾아다니지만 그럴 때마다 돌아오는 것이라고는 놀 이빨과 실망감뿐이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4125] = {title = "실종된 안내원", objective = "페랄라스 해안에서 안내원의 배를 찾아야 합니다.", description = "안내원인 라스칼이 탈라나르로 떠난 지는 대략 일 주일 정도 지났군. 그 친구는 페더문 장군님이 원정대를 이끌고 이곳에 왔을 때부터 우리와 함께했기에 페랄라스를 잘 알고 있소. 내가 알기로 라스칼은 페랄라스 남부를 지날 때 호드 야영지를 피해가기 위해 해안을 따라 배를 타고 내려가려는 계획이었소.\n\n나는 그 친구의 배를 찾지 못했지만 당신이라면 찾을 수 있을 것이오. 어쩌면 어딘가에 숨겨져 있을 수도 있고, 어쩌면 가라앉아 버렸을지도 모르지. 하지만 어쨌거나 그 친구의 행방을 찾는 단서가 될 거요. 뭔가 찾게 되거든 부디 내게 알려주시오.", progress = nil, completion = "난파된 나룻배를 찾았습니다. 약간의 진흙이 섞여 뿌연 바닷물속으로 배의 좌현에 커다란 구멍이 여러 개 난 것이 보입니다. 나무 뼈대만 남은 걸 보니 심한 공격을 받은 듯합니다. 배를 공격한 것이 무엇인지는 모르겠으나 배를 두 동강내려고 한 것은 분명합니다. 우현에는 페더문 요새의 작은 문장이 새겨져 있습니다.\n\n배의 밑바닥에 깔린 진흙 사이로 반짝이는 금속 같은 것이 눈에 띕니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4126] = {title = "헐레이 블랙브레스", objective = "카라노스에 있는 라그나르 썬더브루에게 잃어버린 썬더브루 제조법을 가져가야 합니다.", description = "헐레이 블랙브레스라는 악당이 이끄는 검은무쇠단 드워프 녀석들이 썬더브루 가문의 최고 양조법인 썬더브루 맥주 양조법을 훔쳐가 버렸소. 나쁜 놈들! 그런 녀석들은 그렇게 좋은 술을 마실 자격이 없어!\n\n내 어려운 부탁 한 가지만 합시다. 불타는 평원에 있는 검은바위 나락으로 가서 눈에 띄는 썬더브루 맥주통을 모조리 부숴버리고 우리 썬더브루 맥주 양조법을 되찾아주시오!\n\n검은바위 나락을 온통 다 뒤집어 엎어도 좋으니 제발 그 양조법을 찾아다 주시구려!", progress = "양조법은 가지고 왔소? 우리 가문의 술을 검은무쇠단 녀석들이 마시는 꼴을 상상하면 참을 수가 없소!", completion = "찾았군! 수고하셨소! 당신이 그 검은무쇠단 녀석들과 헐레이 블랙브레스 녀석에게 아주 혼을 내줬다면 좋겠군!\n\n우리 썬더브루 가문이 당신에게 큰 신세를 졌소. 당신이야말로 영웅 중의 영웅이오, 하하!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n일격의 곤봉절단의 클레버\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n검은 드워프 맥주잔"},
[4127] = {title = "난파된 나룻배", objective = "페더문 요새로 돌아가 긴로 하트킨들에게 잃어버린 나이프를 보여주어야 합니다.", description = "진흙에 손을 넣어보니 칼 손잡이가 느껴집니다. 손질이 잘 된 것으로 보아 이 배에 타고 있던 사람이 잃어버린듯 합니다. 배가 심하게 부서진 것과 칼을 잃어버린 것이 관련이 있을지도 모릅니다.\n\n칼을 집어 들면서 페더문 요새에 있는 긴로 하트킨들이 어떤 단서라도 찾게 되거든 자기를 찾아오라고 한 말을 기억합니다. 그런데 물속에 무언가 있는 것 같은 느낌이 듭니다...", progress = "아, 어서 오시오. 아주 비극적이더라도 라스칼의 운명이 어찌 되었는지 알 수 있는 단서를 찾아온 거라면 좋겠구려.", completion = "재미있군... 이건 라스칼의 칼이 맞소. 물 밑바닥에 배와 함께 가라앉아 있었단 말이오? 음... 이 칼만으로는 라스칼의 행방불명과 어떤 관련이 있는지 알아내기가 쉽지 않을 것 같소. 흔한 방법은 아니지만 좀더 알아볼 수 있는 방법이 있긴 하오.\n\n사이코메트리라고 들어봤소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4128] = {title = "라그나르 썬더브루", objective = "라그나르 썬더브루와 대화해야 합니다.", description = "오호호호, 안녕하세요. 듣자 하니, 라그나르 썬더브루가 맥주를 도둑맞았다며 굉장히 흥분하고 있다네요. 그는 씩씩하고 용감한 모험가들을 찾고 있고 후한 보상을 할 의향도 있답니다.\n\n혹시 관심 있으면 라그나르와 얘기해 보세요. 그는 던 모로의 카라노스에 있는 썬더브루 양조장에 있을 거예요.", progress = nil, completion = "당연히 화가 났지! 도둑질을 당했단 말이오! 그것도 우리 가문의 양조법을 말이야! 어떻게 감히 그런 짓을! 그렇지 않아도 검은무쇠 &lt;race&gt; 녀석들이 싫어 죽겠는데 말이오! 녀석들... 이제 가만두지 않겠어!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4129] = {title = "드러나는 칼의 비밀", objective = "페더문 요새에 있는 쿠인티스 존스피레에게 잃어버린 나이프를 가져가야 합니다.", description = "이 요새에 거주하는 쿠인티스 존스피레라는 드루이드는 좀... 특이한 능력들을 지니고 있소. 그 중 하나가 사이코메트리인데, 어떤 물건을 만져보고 그 물건에 어떤 일이 일어났는지 알아내는 능력이오. 그 친구가 어떻게 그런 일을 할 수 있는지는 묻지 마시오. 나는 이해하지 못하거나 이해하고 싶지 않은 것들은 무조건 마법이라고 생각하니까 말이오. 하지만 그 능력이 정말로 효력이 있다는 것이과, 그 친구가 나한테 신세를 졌다는 것, 이 두 가지는 알고 있소.\n\n이 칼을 작은 통나무집 위에 살고 있는 쿠인티스에게 가져다주고 그가 가진 능력으로 이 칼에 대해 알려주면 칼림도어 홀뎀 빚은 갚은 걸로 치겠다고 전해주시오.", progress = "긴로가 보낸 것이로군요, 그렇지요?\n\n내 사이코메트리는 정신적으로 많은 힘을 필요로 하는 기술이지만... 칼림도어 홀뎀에서 내가 잃은 것도 마찬가지요. 카드 놀이할 때는 운이 안 따라주고 자연의 비밀을 터득하는데는 운이 따라줘서 이곳 페더문 요새에서는 나를 \"박치의 제왕\"이라고 부르고 있소.\n\n어쨌든 기꺼이 해드리도록 하겠소. 이것이야말로 라스칼의 운명을 밝히는 데 결정적인 단서일지도 모르니까 말이오. 칼을 건네주면 즉시 시작하겠소.", completion = "칼을 건네줘서 고맙소.\n\n사이코메트리란 게 반드시 정확하기만 한 것은 아니지만, 예전에 이 능력을 사용해 가망이 없다고 포기해 버린 일들을 새롭게 이해한 경우도 있었소이다. 이 능력을 당신이 찾은 이 칼에 사용하면 라스칼에게 무슨 일이 있었는지 조금은 알 수 있을 것이오.\n\n이 능력을 사용하는 시간은 잠깐이지만 시전하는 자에게는 아주 혹독한 주문이니 미리 양해를 구하겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4130] = {title = "심령측정", objective = "페더문 요새에 있는 긴로 하트킨들과 대화해야 합니다.", description = "아, 아직 좀 어지럽군. 미안하오. 그나저나 도움이 될 만한 영상을 보았소.\n\n라스칼은 커다란 가죽 가방 두 개를 메고 배에서 내려 육지로 가다 배로 되돌아왔소. 놀의 가죽이 보이오... 몇 마리 놀과 마주쳤군. 덩굴발일족이라고 하는 녀석들인 것 같소. 라스칼이 뭔가에 대해 굉장히 걱정하고 있고... 거의 공포에 질려 있소. 걱정을 하느라 등 뒤에서 물의 정령이 나타나는 것도 보지 못하는군. 영상은... 거기가 끝이오.\n\n미안하지만 좀 쉬어야겠소. 긴로에게 내가 본 것들에 대해 전해 주시오. 그 친구가 꼭 알아야 할 내용이오.", progress = nil, completion = "쿠인티스가 본 것에 대해 알려줘서 고맙소. 다음번에 카드 놀이를 할 때는 조금 봐주면서 해야겠군.\n\n라스칼은 싸움이라면 일가견이 있는 친구니 놀 정도라면 걱정하지 않았을 거요. 아니 공포에 질리지 않았을 거요. 어쩌면 그대와 그대의 동료가 이 새로운 정보를 가지고 우리에게 절실하게 필요한 해결책을 찾아낼 수 있을지도 모르겠구려.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4131] = {title = "덩굴발일족 놀", objective = "페랄라스 남부에 있는 덩굴발일족 놀 야영지를 수색해 안내원이나 그의 소지품에 대한 증거를 찾아야 합니다.", description = "우리의 덩굴발일족 \"친구\"들이 끝내는 라스칼을 처치했을지도 모르지만 왠지 그건 아닐 거라는 기분이 드는군. 그래도 덩굴발일족을 먼저 살펴보는 것이 좋겠소.\n\n무엇을 해야 하는지 분명히 알면 좋겠지만 지금 당장에는 덩굴발일족 야영지를 수색해야 한다는 것밖에는 모르겠소이다. 녀석들이 전리품을 모아두고 서로 다투는 곳이 어딘지는 알고 있소. 어쩌면 쿠인티스가 말한 가방을 녀석들이 찾았을지도 모르고 말이오. 과거에는 수색을 할 때 정면 충돌을 피했지만 쿠인티스가 말한 영상대로라면 그대로 치고 들어가는 수밖에 없겠군.", progress = nil, completion = "근처의 나무에 커다란 가죽 가방 두 개가 못에 박혀 있습니다. 두 가방의 앞면에는 작은 페더문 요새 인장이 새겨져 있습니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4132] = {title = "앵거포지 척살 작전", objective = "검은바위 나락으로 가서 사령관 앵거포지를 처치한 후 장군 고어투스에게 돌아가야 합니다.", description = "임무를 아주 훌륭히 완수해 주었군. 이제 자네에게 마지막 임무를 맡길 때가 되었네.\n\n카르가스 원정대 제 109 사단에 대한 공격 작전을 지휘하고 우리 군대를 대량 학살한 검은무쇠단의 사령관 앵거포지에게 정의의 처단을 내려야만 하네.\n\n이번 임무는 틀림없이 자네의 임무 중 가장 힘든 것이 될 걸세. 하지만 성공하면 아주 후한 보상을 받게 될 거야.", progress = nil, completion = "드디어! 그 악당을 정의의 이름으로 처단했군! 자네는 정말 실력이 뛰어나군. 자네가 호드와 카르가스 원정대에 보여 준 확고부동한 헌신에 대한 징표로 이 메달을 걸도록 하게.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n정복자의 메달"},
[4133] = {title = "비비안 라그레이브", objective = "카르가스에 있는 비비안 라그레이브와 대화해야 합니다.", description = "어둠마법사 비비안 라그레이브가 당신의 도움을 필요로 하고 있습니다. 그녀는 황야의 땅에 있는 오크 전초기지, 카르가스에서 검은바위 나락에 사는 검은무쇠단 드워프들이 어떤 술을 만들고 있다는 소문을 쫓고 있어요.\n\n비비안이 당신을 기다리고 있을 것이니 가서 그녀와 얘기해 보세요.", progress = nil, completion = "와줘서 고마워요. 이곳도 나름대로 매력은 있지만 연금술 실험실의 쾌적함은 없군요.\n\n인사는 이 정도로 그치고 본론으로 들어갈까요?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4134] = {title = "잃어버린 썬더브루 제조법", objective = "카르가스에 있는 비비안 라그레이브에게 잃어버린 썬더브루 제조법을 가져가야 합니다.", description = "소문에 의하면 헐레이 블랙브레스라는 검은무쇠 드워프가 맥주 제조법을 훔쳤다고 해요. 이 썬더브루 맥주는 마시는 사람에게 엄청난 힘과 용기를 준다고 하는군요. 우리는 이 술을 연구하고자 합니다. 어쩌면 이 술의 효력을 다른 곳에 응용할 수 있을지도 몰라요... 포세이큰의 목적에 부합하는 그런 곳 말입니다.\n\n검은바위 나락에 침입해 헐레이를 찾은 다음 썬더브루 맥주 제조법을 빼앗아 내게 가지고 오세요.\n\n헐레이를 찾으려면 녀석이 아끼는 술로 위협해서 유인해내야 할 거예요.", progress = "썬더브루 맥주 제조법은 가지고 왔나요?", completion = "수고하셨어요. 이 제조법을 연금술 실험실에 보내 연구하도록 해야겠어요. 시간이 흐르면 비밀을 캐낼 수 있을 거예요. 언젠가는 얼라이언스의 드워프들이 이 술의 효력에 되레 당하게 되겠죠!\n\n정말 웃기는 일이죠. 죽음은 유머 감각에도 영향을 미치는 것 같아요. 안 그런가요?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n일격의 곤봉절단의 클레버\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n최상급 치유 물약상급 마나 물약"},
[4135] = {title = "고통의 구덩이", objective = "라스칼의 마지막 행방을 알아냈으니 고통의 구덩이에서 그를 찾아야 합니다. 그의 쪽지에 따르면 고통의 구덩이는 덩굴발일족 놀 야영지의 남쪽에 있습니다.\n\n제공된 아이템: \n", description = "가방 안에는 두 가지 물건이 들어 있습니다. 하나는 탈라나르로 배달할 소포고, 다른 하나는 누구에게 쓴 것인지 알 수 없지만 급히 쓴 쪽지입니다.\n\n쪽지에는 놀 야영지 남쪽에 있는 고통의 구덩이라는 곳에서 곤충과 같은 생물을 발견했다는 얘기가 적혀 있습니다. 이 쪽지를 쓴 자는 이것이 마치 페랄라스 전체에 심각한 위협이라도 되는 듯, 자신이 직접 조사해 봐야겠다고 생각한 것 같습니다. 이 쪽지에는 \"페더문의 라스칼\"이라는 서명이 있습니다.\n\n라스칼의 행방을 찾아낸 것 같습니다.", progress = nil, completion = "특이하게 생긴 커다란 고치를 찾았습니다. 고치의 표면은 끈적끈적하고 군데군데 딱딱한 돌기가 튀어나와 있습니다. 고치의 높이와 넓이로 보아 인간형 생물 하나가 쉽게 들어갈 수 있는 크기입니다... 그리고 고치 속에서 인간형 생물의 모습이 희미하게 보이는 것으로 미루어 보아 고치 안에 정말로 인간형 생물이 들어있는 것 같습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4136] = {title = "리블리 스크류스피곳", objective = "리블리를 처치하고 그 증거로 그의 머리카락을 불타는 평원에 있는 유카 스크류스피곳에게 가져가야 합니다.", description = "동생인 리블리는 가족에게 언제나 골칫덩어리였어요. 무슨 계획에 투자한답시고 걸핏하면 집안의 돈을 가져다 날려버리곤 했죠.\n\n그중에서도 마지막 계획이 제일 심했어요. 무법항의 레빌가즈 남작이 불쌍한 리블리에게 현상금을 걸었으니 말이에요. 스크류스피곳 가문에는 경사가 난 거죠! 우리의 꼬마 리블리가 마침내 무언가 가치 있는 존재가 되는구나 하고 말이에요!\n\n그런데 지금 리블리는 검은바위 나락 어딘가에 숨어버렸어요. 부디 리블리를 찾아서 데려와 주세요!\n\n순순히 오지 않으려고 해도 상관없으니 머리카락이라도 가져오시면 돼요.", progress = "리블리를 데려왔나요? 아니면 리블리의 소지품이라도 가져 온 건가요?", completion = "아하! 리블리를 찾았군요! 그런데... 동생이 순순히 따라오지 않은 것 같군요. 흠, 안타깝네요. 레빌가즈에게 넘기겠다고 말하면 어떤 표정을 지을까 궁금했는데 말이에요.\n\n고마워요. 당신은 우리 집안을 아주 기쁘게 해줬어요. 리블리도 그 어느 때보다 평온할 거예요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n원한의 장화고행의 어깨갑옷강철미늘 갑옷\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4141] = {title = "무이긴과 라리온", objective = "붉은꽃잎 15개를 모아 무이긴에게 돌아가야 합니다.", description = "저기 라리온이 보이시오? 우리가 여기로 온 건 저 친구 잘못이란 말이오!\n\n분명히 길을 잘못 들었다고 경고를 해 줬지만 들은 체도 않더니, 게다가 지금에 와서는 자기가 나한테 말을 걸지 않겠다고 하고 있으니 이게 될 법이나 한 말이오? 저 친구가 생각을 고쳐먹을 때까지 장난이나 좀 쳐야겠소.\n\n이 근처에서 자라는 식물 비슷한 생물들을 보셨소? 녀석들은 골칫덩어리일 뿐이지만 잘만 길들이면 내 명령을 따르도록 할 수 있을 것도 같소.\n\n하지만 먼저 조사를 할 견본이 필요하니 당신이 좀 모아 주지 않겠소?", progress = "라리온 그 친구 아주 혼이 날 거요!", completion = "녀석들이 당신한테 너무 까다롭게 굴지 않았으면 좋겠군. 녀석들이 야생 식물들이라 사나워서 나는 근처에 가지 않소.\n\n한번은 한 마리를 뛰어넘으려고 했는데 날 공격하지 뭐요! 식물은 원래 그런 식으로 행동을 하면 안 되는 건데 말이오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4142] = {title = "그레간 방문", objective = "페랄라스에 있는 그레간 브루스퓨에게 붉은꽃잎을 가져가야 합니다.", description = "어떻게 해야 할지 모르겠소. 이 식물들은... 뭔가 약간의 지능이 있는 것 같소이다.\n\n난 이런 면에서는 전문가는 아니지만 전문가를 하나 알고 있지!\n\n페랄라스 북쪽으로 가서 그레간 브루스퓨라는 내 친구를 찾아보시오. 이런 일이라면 그 친구 전문이니까 말이오.\n\n그레간이 분명 도와줄 수 있겠지. 그 친구는 큰 도시에서 사는 걸 좋아하는 친구가 아니라서 야외에서나 찾을 수 있을 거요.", progress = "나는 이 숲에서 살고 있소... 아주 평화롭지.\n\n뭐, 평화로운 줄 알았다고 해야 할까. 내가 아이언포지에서 살고 있을 때보다 방문객이 더 많이 찾아오니, 원!", completion = "엥? 붉은꽃잎이라고? 흠... 나에게 당신 계획이 뭔지 말해주는 게 좋을 거요. 그래야 내가 도와줄 수 있는지 어떤지 말해줄 수 있으니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4143] = {title = "악의 아지랑이", objective = "아탈라이 아지랑이 5개를 모은 후 운고로 분화구에 있는 무이긴에게 돌아가야 합니다.", description = "솔직히 말하면 여행을 다니면서 이런 식물을 본 건 처음이오. 아무래도 운고로 분화구에 한번 가봐야겠군...\n\n어쨌든, 무이긴이 뭘 찾는지 알 것 같소. 아탈라이 아지랑이라는 건데, 아주 고약한 물질이지. 모으기가 쉽진 않지만 그 조그만 괴물들을 조종하려면 꼭 필요한 것이라오.\n\n슬픔의 늪에 있는 아탈학카르 신전으로 가시오. 그곳에서 지하껍질괴물, 진흙구렁이, 진흙괴물을 처치하면 아탈라이 아지랑이를 구할 수 있을 거요. 행운을 빌겠소!", progress = "라리온이 아직도 나랑 얘기하지 않으려고 하는군! 그 친구 원한을 품는 방법 하난 확실히 아는군.", completion = "맞소. 그 물건들에 손을 대기가 좀 꺼려지긴 하는군! 하지만 그레간이 된다고 하니 시도는 해보고 싶소!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4144] = {title = "붉은꽃잎 씨앗", objective = "계획은 이렇소. 가서 붉은꽃잎 씨앗을 채집해 오시오. 그러니까, 아직 완전히 싹트지 않은 식물 말이오. 그걸 가지고 오시오. 그러면 아탈라이 아지랑이로 뭘 할 수 있나 보겠소.\n\n당신은 내가 복수심에 불타고 있다고 생각하겠지만... 아니, 사실은 정말 복수하고 싶소!\n\n솔직히 말해 여기서 빠져나가는 길도 알고 있지만 내가 옳다는 걸 라리온이 인정하기 전까지는 여기서 나가지 않을 거요!\n\n자, 이제 가보시오. 붉은꽃잎 씨앗을 가지고 와서 한번 재미있게 놀아봅시다!", description = nil, progress = "계획은 이렇소. 가서 붉은꽃잎 씨앗을 채집해 오시오. 그러니까, 아직 완전히 싹트지 않은 식물 말이오. 그걸 가지고 오시오. 그러면 아탈라이 아지랑이로 뭘 할 수 있나 보겠소.\n\n당신은 내가 복수심에 불타고 있다고 생각하겠지만... 아니, 사실은 정말 복수하고 싶소!\n\n솔직히 말해 여기서 빠져나가는 길도 알고 있지만 내가 옳다는 걸 라리온이 인정하기 전까지는 여기서 나가지 않을 거요!\n\n자, 이제 가보시오. 붉은꽃잎 씨앗을 가지고 와서 한번 재미있게 놀아봅시다!", completion = "자, 그럼 한번 해봅시다! 이거면 라리온의 관심을 끌 수 있을 거요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4145] = {title = "라리온과 무이긴", objective = "마샬의 야영지에 있는 라리온에게 채찍줄기 붉은꽃잎덩굴손 5마리, 덩이줄기 붉은꽃잎덩굴손 5마리, 칼날가시 붉은꽃잎덩굴손 5마리, 질긴뿌리 붉은꽃잎덩굴손 5마리를 사냥해야 합니다.", description = "저기 무이긴이 보이십니까? 우리가 길을 잃은 건 저 친구 잘못입니다!\n\n나는 길을 분명히 알고 있었는데 계속해서 자기가 지름길을 안다며 우기다가 결국 이곳으로 오게 된 겁니다!\n\n설상가상으로 이제는 이상한 식물 괴물을 보내서 나를 괴롭히고 있습니다. 얼마나 화가 나는지 저 친구랑 한동안 얘기도 하지 않을 생각이지만 이 괴물들은 가만히 참고 내버려두지 못하겠군요.\n\n먼저 저 친구의 보급 물자를 좀 끊어보는 게 어떻겠습니까? 가서 붉은꽃잎덩굴손 녀석들을 좀 사냥하고 내게 돌아와 주십시오.", progress = nil, completion = "도와줘서 고맙습니다. 하지만 나쁜 소식이 좀 있습니다만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4146] = {title = "구제장치 연료", objective = "마샬의 야영지에 있는 라리온에게 충전 안된 구제장치와 아탈라이 아지랑이 5개를 가져가야 합니다.", description = "운이 좋으시군요! 마본님이 안 계신 동안 저도 나름대로 실험을 하고 있었거든요. 그중 하나가 수동 잡초 구제장치인데요, 약간만 조정하면 그 붉은꽃잎덩굴손 잡초 녀석들을 제거할 수 있을 거예요.\n\n제가 구제장치 원형을 하나 드릴 수는 있지만 연료를 좀 모으셔야 할 거예요. 구제장치 연료로 쓸 아탈라이 아지랑이는 아탈학카르 신전으로 가면 찾을 수 있죠. 아탈라이 아지랑이는 지하껍질괴물이나 진흙구렁이, 아니면 진흙괴물에게서 얻을 수 있을 거예요.", progress = "정말 피곤하군. 저것들이 날 그냥 두질 않는다니까!", completion = "마본이 없었단 말입니까? 뭐, 그래도 뭘 가져왔는지 보여주십시오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4147] = {title = "마본의 작업장", objective = "톱니항에 있는 마본 리벳시커의 작업장으로 가야 합니다.", description = "무이긴이 뭘 하는지 간신히 알아냈는데 말입니다. 그 몹쓸 것들을 거기서 기르고 있는게 아니겠습니까!\n\n이제 유일한 해결책은... 아니요, 대화로 해결할 게 아니라요... 무슨 생각을 하는 겁니까? 싸우는 게 상책입니다!\n\n톱니항에 작업장이 있는 내 친구 마본의 도움이 필요합니다. 그 친구라면 분명 우리에게 도움이 될만한 장치를 만들어줄 수 있을 겁니다.", progress = nil, completion = "아, 마본님을 만나러 오셨나요? 저도 마본님을 못 뵌지 꽤 됐어요. 마본님은 고대 트롤 유적지를 조사하러 타나리스로 갔거든요.\n\n근데 뭐가 필요하다고 하셨죠?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4148] = {title = "붉은꽃잎 구제장치", objective = "이 구제장치를 작동시키려면 대상 생물의 견본이 필요합니다. 분화구로 가서 붉은꽃잎 씨앗을 모아 주십시오. 그러면 이 구제장치를 측정해서 무이긴의 조그만 친구들에게 사용할 수 있을 겁니다.\n\n그 친구가 그렇게 고집을 부리지만 않았어도 벌써 집으로 돌아가고 있었을 텐데... 하지만 그때까지는 그의 사소한 장난이 나한테는 아무런 소용이 없다는 걸 보여줄 겁니다!", description = nil, progress = "이 구제장치를 작동시키려면 대상 생물의 견본이 필요합니다. 분화구로 가서 붉은꽃잎 씨앗을 모아 주십시오. 그러면 이 구제장치를 측정해서 무이긴의 조그만 친구들에게 사용할 수 있을 겁니다.\n\n그 친구가 그렇게 고집을 부리지만 않았어도 벌써 집으로 돌아가고 있었을 텐데... 하지만 그때까지는 그의 사소한 장난이 나한테는 아무런 소용이 없다는 걸 보여줄 겁니다!", completion = "이 구제장치가 완벽하게 작동할 것 같군요. 자, 그 잡초들이 보이면 주저하지 말고 이 구제장치를 사용하시기 바랍니다!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n붉은꽃잎 구제장치"},
[4161] = {title = "칼도레이 조리법", objective = "작은 거미 다리 7개를 모아 돌라나르에 있는 자린에게 갖다주어야 합니다.", description = "아주 오래전, 나이트 엘프는 칼도레이... 즉, \"별의 후예들\"이란 이름으로 불렸습니다. 과거를 배우는 것은 <class>의 길을 걸어가는 데 있어 매우 중요한 절차지요. <name>, 그러니 지금부터 제가 드리는 말씀을 귀 기울여 들으십시오.\n\n칼도레이는 자연과 조화로운 관계를 맺고 있는 것을 늘 자랑스러워 했습니다. 즉 우리는 자연에서 꼭 필요한 것만을 취하고, 그 대가는 반드시 돌려준다는 뜻입니다. 우리는 이렇게 자연과의 균형을 통해 번성해 왔습니다.\n\n<name>, 가서 작은 거미 다리를 더도 말고 7개만 모아 오십시오.", progress = "늘 자연의 균형을 기억하며 살아가십시오, <name>. 숲을 살아있는 생명체로 이해하는 마음의 자세와 강한 영감을 키우시길 바라겠습니다.", completion = "&lt;name&gt;, 제가 오늘 그대에게 해드린 말을 잘 기억하십시오. 그대 또한 자연의 일부입니다. 아무리 어려운 시기에도 우리 나이트 엘프들이 지켜내기 위해 애쓰는 숭고한 대상이란 말이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n조리법: 나이트 엘프 거미 케밥나이트 엘프 거미 케밥"},
[4181] = {title = "고블린 기계공학", objective = "고블린 기계공학에 대해 더 알고 싶으면 가젯잔에 있는 닉스 스프로켓스프링에게 기계공학 설명서를 가져가야 합니다.", description = "고급 기계공학은 노움과 고블린의 두 가지 분야로 명확히 분류되오. 그중 뛰어난 고블린 기계공학에 대해서 알려주도록 하죠. 사회적 지위가 있는 전문 기술자이니 매사에 공평해야지... 고블린들은 뭐든지 폭발시키기를 즐겨 하는데, 중간에 어떤 장애물이 있든 아랑곳하지 않아요. 설령 그 장애물이 자기 동족이라 하더라도 말이에요!\n\n이 설명서를 한번 읽어보세요. 폭발 기술을 배우고 싶거든 가젯잔에 있는 닉스 스프로켓스프링에게 이 설명서를 가져다주세요. 하지만 명심해요. 일단 둘 중 하나를 선택해 회원으로 가입하면 다른 학문은 절대로 배우지 못해요. 그러니까 그가 주는 임무를 완료하기 전에 확실한 마음의 결정을 내려야 해요!", progress = "나는 뛰어난 화약 냄새를 맡는 것 같이 새파란 풋내기의 냄새를 아주 멀리서도 잘 맡는다오. 그래, 폭발 기술을 숙배우러 온 거요?", completion = "내 밑에서 배우기로 한 건 현명한 선택이오! 기계공학의 기본만 알면 어떤 풋내기라도 전문가가 될 수 있소. 그들의 방사선으로 오염된 노움들의 고향, 놈리건이 그 증거지. 노움과 굳건한 정신력과 뼈를 깎는 듯한 꾸준한 노력이 있어야 고블린 기계공학 분야에 통달할 수 있소.\n\n내 말을 귀 기울여 듣도록 하시오. 분명 뭔가 배울 수 있을 테니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4182] = {title = "용혈족의 위협", objective = "검은 새끼용 15마리, 검은용혈족 10마리, 검은고룡족 4마리와 검은 비룡 1마리를 처치한 후, 헬렌디스 리버혼에게 돌아가야 합니다.", description = "불타는 평원에서의 삶은 온통 투쟁으로 가득하오.\n\n주위를 둘러보시오! 이 건물들이 어떻게 된 것인지는 아는 바가 별로 없지만 한때는, 그러니까 대폭발이 일어나기 전에는, 이곳이 붉은마루 산맥의 일부였소이다.\n\n넋두리는 이쯤 해 두고 문제가 한 가지 있소. 이 산맥 아래서 용혈족 녀석들을 봤을 거요. 녀석들을 몰아내야 하는데 도움이 필요하오. 녀석들을 가능한 많이 처치한 후 내게 돌아오시오. 성공하면 다른 일들에 대해서도 얘기를 나눌 수 있을 거요.", progress = nil, completion = "잘 하였소이다. 용혈족을 처치할 수 있는 실력이 있다는 걸 알았으니 이제 더 심각한 문제에 대해 얘기해 봅시다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4183] = {title = "진정한 지도자", objective = "레이크샤이어로 가서 집정관 솔로몬에게 헬렌디스 리버혼의 편지를 전달해야 합니다.", description = "우리는 늘 검은바위부족 오크 녀석들이 야만적인 훈련을 받아 그렇게 된 것이라고 생각해 왔소. 하지만 녀석들의 고향인 이곳에서 찾은 걸 보면 또 다른 이유가 있다는 걸 알 수 있소.\n\n물론 녀석들에게 힘을 주는 것은 피와 투쟁에 대한 열망과 목마름이지만 검은바위부족 오크들을 지배하는 것은 검은용군단이오. 그래서 우리는 검은바위부족이 분노로 가득 찬 포악한 존재로 변하는 원인이 검은용군단 때문일 것이라 생각하고 있소.\n\n이 편지를 집정관 솔로몬에게 전하시오. 이 편지를 보면 무엇을 해야만 하는지 알게 될 것이오.\n\n<봉인된 편지를 건네주는 헬렌디스>", progress = "안녕하시오. 우리가 전에 만난 적이 있던가? 굉장히 낯이 익군.", completion = "&lt;헬렌디스가 보낸 편지를 뜯어서 읽기 시작하는 집정관 솔로몬&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4184] = {title = "진정한 지도자", objective = "스톰윈드로 가서 대영주 볼바르 폴드라곤에게 볼바르에게 보내는 솔로몬의 탄원서를 전해주어야 합니다.\n\n볼바르는 스톰윈드 왕궁에 있습니다.", description = "흠, 무척 안 좋은 소식이오. 우리의 적이 그보다 훨씬 더 위협적인 존재의 졸개일 뿐이라는 사실을 알고 나니 힘이 다 빠지는군. 레이크샤이어는 검은바위부족과 검은용군단의 공격을 버텨낼 방법이 없소이다. 이 위협으로 레이크샤이어가 멸망한다면 다음에는 다크샤이어가 멸망할 테고 그 다음은? 골드샤이어? 아니면 스톰윈드?\n\n스톰윈드에 있는 대영주 볼바르 폴드라곤님께 이 사실을 즉시 전해주시오! 이것으로 스톰윈드의 원조를 받을 수 없다면 그 어떤 도움도 소용이 없을 것이고 결국 모든 게 끝장나고 말 것이오.", progress = "스톰윈드 왕궁에는 무슨 일인가?", completion = "용이라고? 무슨 터무니 없는 소릴 하는 건가!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4185] = {title = "진정한 지도자", objective = "여군주 카트라나 프레스톨과 얘기를 나눈 후, 대영주 볼바르 폴드라곤과 대화하십시오.", description = "솔로몬이 아주 심각한 소식을 전해왔군. 하지만 추측만 가지고 여기저기 산재해 있는 군대를 레이크샤이어에 보낼 수는 없네. 무엇보다 이 주장을 증명할 수 있는 증거가 있어야 해.\n\n여군주 프레스톨님과 얘기해 보게나. 해박하신 분이시니 용과 용혈족에 대해 잘 아신다네. 그녀라면 이번 사태에 대해 더 자세히 말해줄 수 있을지도 모르겠군.", progress = "<뚫어져라 쳐다보는 볼바르>", completion = "&lt;손으로 턱을 받치고 뭔가를 깊이 생각하는 듯한 볼바르&gt;\n\n여군주 프레스톨님의 입장은 존중하지만 이번 난국으로 인해 부딪히게 된 모든 문제들을 해결할 방법이 있을 거라 믿네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4186] = {title = "진정한 지도자", objective = "레이크샤이어에 있는 집정관 솔로몬에게 볼바르의 명령서를 가져가야 합니다.", description = "자네를 스톰윈드의 부관 대리로 임명하겠네.\n\n레이크샤이어에 있는 집정관 솔로몬에게 돌아가 이 명령서를 전하게.", progress = "볼바르님에게서 무슨 전갈이라도 가져왔소?", completion = "더 나빴을 수도 있었겠지...\n\n&lt;훑어보는 집정관 솔로몬&gt;\n\n이제 레이크샤이어의 운명은 당신의 손에 달린 것 같군.\n\n&lt;눈을 빠르게 깜빡이는 것이 울고 있는 것 같은 집정관 솔로몬&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4201] = {title = "사랑의 묘약", objective = "검은바위 나락에 있는 여왕 나그마라에게 그롬의 피 4개, 거대한 은 광석 10개, 가득 찬 나그마라의 약병을 가져가야 합니다.", description = "아. 사랑의 고통이란! 나의 매력이 사랑스런 락노트에게는 아무런 힘도 쓰지 못하나봐요. 내가 퇴짜를 맞다니! 미칠 것 같아요!\n\n절 좀 도와주세요! 우리 서큐버스는 사랑에 대해 잘 알고 있죠. 저는 락노트의 마음을 둘러싸고 있는 철벽을 무너뜨릴 물약을 만들 수 있답니다. 그 물약을 만들려면 그롬의 피, 아즈샤라에 사는 절벽거인에게서 얻을 수 있는 거대한 은 광석, 그리고 운고로에 있는 골락카 간헐천의 물이 필요해요. 물은 이 약병에 담아와 주세요.\n\n부디 행복을 찾아 헤매는 이 불쌍한 영혼을 구해주세요.", progress = "재료는 가져오셨나요? 마음에 입은 상처가 절 아프게 하고 있어요!", completion = "아, 해내셨군요! 이제 물약을 만들어 락노트에게 사용할 수 있겠어요. 드디어 그 사람도 내 매력에 빠진 희생자가 되는 거예요!\n\n감사합니다. 당신은 사랑의 투사예요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n속박의 소매장식나그마라의 채찍 허리띠\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4221] = {title = "오염된 바람꽃", objective = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어서 독성을 품게 된 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어서 독성을 품게 된 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "바람꽃에 세나리온 식물 고약 두 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4222] = {title = "오염된 바람꽃", objective = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어서 독성을 품게 된 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어서 독성을 품게 된 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "바람꽃에 세나리온 식물 고약 두 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4223] = {title = "진정한 지도자", objective = "불타는 평원에 있는 치안대장 맥스웰과 대화하십시오.", description = "<한숨을 쉬는 집정관 솔로몬>\n\n불타는 평원으로 돌아가시오. 당신은 스톰윈드의 부관으로서 치안대장 맥스웰에게 보고해야 할 것이오. 행운을 빌겠소.", progress = nil, completion = "&lt;큰 소리로 웃는 치안대장 맥스웰&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4224] = {title = "진정한 지도자", objective = "털보 존을 만나 치안대장 윈저의 행방에 대해서 알아낸 다음 치안대장 맥스웰에게 돌아가 보고해야 합니다.\n\n치안대장 맥스웰은 북쪽에 있는 동굴에서 털보 존을 찾아보라고 했습니다.", description = "왜?당신이 처음인 줄 알았소? 도대체 얼마나 많은 병사가 더 죽어야 스톰윈드가 행동을 취하려는 거지?\n\n우리는 검은바위부족의 위협과 관련된 엄청난 양의 정보를 모으다 사령관이신 치안대장 윈저님을 잃었소. 윈저님과 함께 우리의 소중한 정보도 모두 잃어버렸지.\n\n우리에게 필요한 것이 바로 그 문서요. 털보 존을 찾아 얘기해 보시오. 그는 윈저님께서 검은바위부족 녀석들에게 습격을 받았을 때 함께 있던 자요. 그는 마지막으로 북쪽 동굴에서 목격되었소.", progress = nil, completion = "그 친구에 대해 미리 주의를 줄 수도 있었지만, 그러면 재미가 없지 않소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4241] = {title = "치안대장 윈저", objective = "북서쪽에 있는 검은바위 산으로 가서 검은바위 나락으로 들어가십시오. 치안대장 윈저에게 무슨 일이 있었는지 알아내야 합니다.\n\n털보 존은 윈저가 감옥으로 끌려갔다고 했습니다.", description = "그러니까 아무짝에도 쓸모없는 그 겁쟁이 녀석이 윈저님께서 아직 살아계신다고 했단 말이오?\n\n준비하시오, 부관 대리. 당신이 윈저님을 찾아야 하오. 윈저님께서 살아계신다면 당신이 구출해오고, 죽었다면 증거를 가져오시오.\n\n<웃는 맥스웰>\n\n이 말을 듣는 것도 이젠 지겹지 않소?", progress = nil, completion = "어디 있는 거야! 죽여버리고 말 거야!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4242] = {title = "실망", objective = "치안대장 맥스웰에게 나쁜 소식을 전해줘야 합니다.", description = "볼바르 녀석은 멍청이야. 녀석의 소중한 증거를 모아 그 목구멍에 쑤셔 넣을 생각이었지.\n\n그 작자는 눈 먼 원숭이 같은 자요. 증거를 코앞에 두고도 전혀 모르니까 말이오.\n\n내 자료를 찾고 있는 거라면 나도 잃어버렸소. 없어졌다고. 회수할 수 없단 얘기요.\n\n무쇠폭군을 찾아 이 미궁에서 빠져나가기만 하면 스톰윈드에 들러서 그 파충류 같은 볼바르 녀석에게 내 망치 맛을 보여주고 말겠어.\n\n이제 가보라고, 친구.", progress = nil, completion = "그 녀석 미쳐버린 게로군.\n\n&lt;고개를 떨구고 애도하는 맥스웰.&gt;\n\n한 때는 자랑스럽고 고결하던 전사가 이제는 미치광이가 되어버리다니 안타까운 일이야. 이제 끝까지 온 것 같군...\n\n지금까지 수고해준 데 대한 사례를 해야지.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n보호자의 투구강철 판금 발덮개칼바람 다리보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4243] = {title = "에이미 01 추적", objective = "운고로 분화구에서 에이미 01을 찾아야 합니다.", description = "유감스럽게도 제가 만든 가장 훌륭한 발명품에 뭔가 문제가 생겼어요. 기계 다람쥐는 본 적이 있죠? 그러니까 저는 운고로 분화구에 사는 유인원들에게 접근하기 위해 녀석들의 모습과 비슷하게 생긴 기계 유인원을 만들어서 에이미 01이라고 이름을 지어주었답니다.\n\n에이미는 수정점을 칠 때 사용하는 수정으로 눈을 만들었기 때문에 에이미가 볼 수 있는 건 저도 모두 볼 수 있어요. 여기서 동쪽으로 가면 유인원의 소굴인 버섯 바위굴이 있는데 거기서 그만 연락이 끊겨 버렸어요. 마지막으로 본 거라고는 우두머리 수컷 고릴라가 인사를 하려고 달려드는 것이랍니다!\n\n에이미 01을 찾는 걸 도와주시겠어요?", progress = nil, completion = "에이미 01을 훑어보니 카르나가 우수한 기계공학 작품이라고 말하는 이 기계에 커다란 홈이 두 군데 패여 있습니다. 그 중 하나는 에이미 01의 어깨에 있고 다른 하나는 머리에 있습니다.\n\n더 조사해보니 전원이 전혀 들어오지 않는 듯합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4244] = {title = "에이미 01 추적", objective = "미스릴 형틀을 찾아 운고로 분화구에 있는 에이미 01에게 돌아가야 합니다.", description = "더 조사해보니 미닫이 형식의 계기판이 보입니다. 전깃줄 위에는 \"미스릴 형틀을 갈아 끼우고 전원을 껐다가 켜십시오\"라고 쓰여 있습니다.\n\n계기판을 교체하면서, 에이미 01을 수리한 다음 마샬의 야영지 근처에 있는 카르나 렘트래블에게 데려가는 것이 과연 쉬운 일일까 생각해 봅니다.\n\n시도를 해봐야 알 것 같습니다.", progress = "미스릴 형틀이 들어가는 계기판은 아직 닫혀있습니다. 에이미 01의 나머지 부분도 여전히 스스로 움직이지 못합니다.", completion = "에이미 01의 등에서 계기판을 다시 꺼낸 다음 타버린 듯한 낡은 미스릴 형틀을 조심스럽게 빼냅니다. 새로운 형틀이 쉽게 들어갑니다. 미스릴 형틀이 문제였다고 가정한다면 이제 마지막으로 할 일은 전원을 껐다가 다시 켜는 일뿐입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4245] = {title = "에이미 01 추적", objective = "운고로 분화구에 있는 카르나 렘트래블에게로 에이미 01을 호위해 가야 합니다.", description = "이제 카르나 렘트래블에게 에이미 01을 데리고 갈 준비가 되었는지 확인하면서 전원을 끕니다. 주변에 고릴라가 없는지 다시 한번 확인한 후, 전원을 켰을 때 일어날 상황에 대해 단단히 각오를 합니다.\n\n이게 마지막 기회입니다... 정말로 이렇게 해야 할까요?", progress = "에이미를 수리하셨나요? 미스릴 형틀이 부서졌을 거라는 추측은 아주 훌륭했어요. 그걸 교체하면 다시 작동할 테니 에이미를 쉽게 데리고 올 수 있을 거예요.", completion = "오, 해내셨군요! 굉장해요! 정말 감사합니다.\n\n아, 불쌍한 우리 에이미. 움푹 패인 이 자국 좀 봐. 조금만 손을 보면 완전히 고칠 수 있을 거예요.\n\n다시 한번 감사 드립니다. 정말로 고마워요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4261] = {title = "고대의 정령", objective = "아레이를 안전하게 호위해야 합니다. 그리고 잿빛 골짜기 동쪽에 위치한 숲의 노래에 살고 있는 케이네스 스틸윈드와 얘기를 해야 합니다.", description = "악령의 숲은 원래 평화롭고 고요한 땅이었다네... 불타는 군단이 점령하기 전까지는 말이야. 지옥불정령들, 그리고 파괴와 혼돈...\n\n굴단의 해골은 아무것도 살려두려고 하지 않았어. 모두 사악한 기운을 받아 변해버렸다네.\n\n고대의 정령인 나는 아직도 발목이 붙잡힌 채, 이 땅의 고통을 견뎌내고 있네. 제발 고향으로 돌아갈 수 있도록 도와주게, <name>. 이곳에서 벗어나 마침내 안식을 찾을 그곳으로 갈 수만 있다면...\n\n내가 자유의 몸이 되도록 도와준 다음 숲의 노래에서 살고 있는 주술사 케이네스 스틸윈드를 찾아가게나.", progress = nil, completion = "고맙소, &lt;name&gt;. 당신이 직접 본대로 악령의 숲은 엄청난 고난을 겪고 있소.\n\n하지만 모두의 도움이 있다면 언젠가는 악령의 숲을 타락의 수렁에서 건져낼 수 있을 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n하늘안개 단망토뜬구름 어깨보호대\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4262] = {title = "멸망의 파이론", objective = "멸망의 파이론을 처치한 후 잘린다 스프리그에게 돌아가야 합니다.\n\n잘린다가 말하기를 파이론은 채석장을 지키고 있다고 하니 그곳을 수색해야 할 것 같습니다.", description = "검은바위 산을 염탐하러 갔던 내 마지막 마법사 다섯이 주황색 파마 머리를 해서 돌아왔더군요. 아니면 그보다 더 심한 일을 당했던가.\n\n<땅에서 재를 한 줌 집어 공중에 뿌리는 잘린다>\n\n멸망의 파이론이라는 녀석은 특히 고약한데, 꽤 문제를 일으키는 모양이에요. 우리 원정대가 검은바위 나락에 들어갈 수 있도록 그 정령을 처치해야만 해요!\n\n녀석은 검은바위 채석장 입구를 지키고 있어요.", progress = nil, completion = "인센디우스라고요? 맙소사...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4263] = {title = "인센디우스!", objective = "검은바위 나락에서 불의군주 인센디우스를 찾아 처치해야 합니다.", description = "파이론이 죽으면서 \"인센디우스\"라고 한 게 분명한가요?\n\n<침을 꿀꺽 삼키는 잘린다>\n\n군주 인센디우스는 라그나로스의 수하라고 하던데! 맙소사. 이런 맙소사. 어떡하지?\n\n임무를 하나 더 맡을 수 있겠어요? 달리 보낼 사람이 없네요!\n\n인센디우스가 재에서 계속해서 파이론을 환생시키면 우린 원정대를 절대 보내지 못할 거예요.\n\n군주 인센디우스를 찾아서 처치해주세요!", progress = nil, completion = "이런! 인센디우스가 분명히 \"라그나로스\"라고 했단 말이죠?\n\n&lt;뭔가를 건네주며 손목을 다독거려주더니 깊은 생각에 빠지는 잘린다&gt;", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n해무리 단망토땅거미 장갑지하 악마의 팔보호구튼튼한 벨트\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4264] = {title = "꼬깃꼬깃한 쪽지", objective = "방금 우연히 치안대장 윈저가 보고 싶어할 듯한 물건을 찾은 것 같습니다. 어쩌면 희망이 있을지도 모릅니다.", description = "이 쪽지 표면은 얼룩으로 뒤덮여 있습니다. 글은 거의 읽을 수 없을 정도지만 다음과 같은 글귀를 알아볼 수 있습니다.\n\n...아름다운 아이러니...\n\n...깨져 버린 얼라이언스의 몰락...\n\n...앵거포지 사령관의 노고가 아니었던들 암호를 절대 해독할 수 없었을 것...\n\n...아젤마크가 윈저의 쪽지를 거의 다 해독했다.\n\n우리 군주께서 심연에서 일어나시어 잔존하는 자들을 쳐부술...\n\n- 제왕 다그란 타우릿산.", progress = "<손에 들고 있는 쪽지를 쳐다보는 치안대장 윈저>\n\n손에 들고 있는 건 뭐요?", completion = "&lt;쪽지를 받아 읽기 시작하는 치안대장 윈저&gt;", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4265] = {title = "고치 탈출", objective = "주크애쉬 소굴에서 라스칼을 풀어줘야 합니다.\n\n페더문 요새에 있는 긴로 하트킨들에게 돌아가 라스칼이 무사히 살아 있다는 소식을 전해 주십시오.", description = "고치에 손을 대자 고치가 갈라져 열립니다. 그 안에는 놀랍게도 아직 살아 있는 나이트 엘프 남자가 들어 있습니다. 그는 심히 멍해진 것 같기는 하지만 건강은 양호해 보입니다. 고치에서 내려오는 것을 도와 주자 그가 정신을 차립니다.\n\n\"엘룬께 감사를. 당신이 날 구해 주었소, 친구. 나... 나는 라스칼이라고 하는데 이 곤충들이 나를 덮친 후 깨어나 보니 마비된 채로 이 고치 안에 갇혀 있었소. 당신 페더문 요새에서 온 거요?\"\n\n실종된 급사를 찾은 거 같습니다!", progress = nil, completion = "잘 돌아왔소. 조금 전 라스칼이 돌아와 무슨 일이 있었는지 말해 주었소이다.\n\n그대가 세운 큰 공로에 내가... 아니, 페더문 요새 전체가 어떻게 감사해야 할지 모르겠소. 그대가 그렇게 제때에 도와 주지 않았다면 라스칼은 벌써 죽었을 거요. 게다가 그대는 대가를 바라지 않고 우리를 도와 주었소이다. 그대에겐 진정한 영웅의 면모가 있군. 이 긴로 하트킨들은 언제나 그대의 친구가 될 것이라는 걸 기억해 주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4266] = {title = "영웅 환영", objective = "페더문 요새에 있는 샨드리스 페더문과 대화해야 합니다.", description = "샨드리스 페더문 장군께서 그대와 개인적으로 얘기를 나누고 싶어하시오. 장군께서는 분명 이번에 그대가 도움을 준 것에 대한 감사를 표하시려는 것일 거요. 그리고 페랄라스 남부에서 그대와 라스칼이 접했던 곤충들에 대해서도 말씀을 나누고 싶어하시오. 그 주크애쉬 곤충들에 대한 보고 내용은... 정말이지 두렵지 않을 수 없군.\n\n페더문 장군께서 기다리고 계시니 어서 가 보시오.", progress = nil, completion = "이번에 도와 준 것에 대해 정말 감사하게 생각합니다. 절망적인 상황에 맞서 보여 준 그대의 용맹함은 이보다 천 배는 더 큰 보상을 받을 만한 자격이 있지만 미미하게나마 페더문 요새 전체를 대신해 드리는 이 감사의 표시를 받아 주길 바랍니다.\n\n자, 그런데... 다시 한번 더 그대의 도움을 청하고 싶습니다. 이곳 페랄라스에서 주크애쉬 소굴을 발견했다는 점에서 내 생각에는 그대가 이번 임무에 최적격자일 것 같습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n의식의 엘프 비수독신자의 마법봉\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4267] = {title = "실리시드의 출현", objective = "다르나서스에 있는 그라시나 스피릿마이트에게 라스칼의 보고서를 가져가야 합니다.", description = "페랄라스 남동부의 상황에 대한 라스칼의 보고서 사본 한 부를 그대에게 맡기겠습니다. 주 보고서는 다르나서스에 제출 중이니 그동안 이 사본을 섭정의 일원 중 한 명에게 전해 주었으면 하오. 그라시나 스피릿마이트라고 하는, 다르나서스의 달의 신전에 사는 여사제지. 그녀는 이러한 종류의 생물들에 대해서는 아주 박식하니 이 보고서를 가져다준다면 우리 모두에게 득이 될 것입니다.\n\n그럼 이만 가 보세요! 행운을 빌겠습니다. 우리 모두에게 엘룬의 가호가 있기를.", progress = "나이트 엘프의 친구여, 이 축복받은 신전에 오신 걸 환영합니다. 그대가 페더문 요새에서 이곳으로 올 것을 예시를 통해 미리 알고 있었답니다. 샨드리스 페더문이 가져가라고 한 보고서는 있나요?", completion = "우리 나이트 엘프들은 이 보고서에 적힌 두려운 존재들에 대해 알고 있습니다. 샨드리스가 그대와 이 보고서를 내게 보낸 건 참 현명한 일이었어요.\n\n이 생물들은 빠른 속도로 페랄라스를 모조리 집어삼키고 말 겁니다. 우리가 맞선 가장 큰 위협 중 하나인 것은 분명해요. 그대와 그 안내원이 접한 곤충의 이름은 실리시드라고 합니다. 이들은 호드와 얼라이언스 모두에게 가장 큰 위협이 될 겁니다.\n\n이 곤충들이 우리를 덮치기 전에 우리가 먼저 녀석들을 물리치기 위한 결의를 굳히게 되기를 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4281] = {title = "탈라나르 배달", objective = "탈라나르에 있는 팔핀델 웨이워더에게 배달되지 않은 꾸러미를 가져가야 합니다.", description = "덩굴발일족 놀 야영지에서 발견한 이 꾸러미는 페랄라스 남동쪽의 탈라나르라는 작은 기지로 배달되어야 할 것이었습니다. 실종된 안내원의 운명이야 어찌되었든 소포 배달 임무는 아직 끝나지 않았습니다.\n\n소포를 자세히 살펴보니 포장 겉면에 손으로 \"팔핀델 웨이워더\"라고 쓰여 있은 것이 보입니다. 아마 이 꾸러미의 수취인인 것 같습니다.", progress = "탈라나르에 온 걸 환영하오. 내가 도와 줄 일이라도 있소?", completion = "엘룬께 영광을! 페더문 요새에서 마침내 배달이 왔군!\n\n그대가 여기로 온 것을 보아하니 평소에 오던 안내원, 라스칼에게 무슨 안 좋은 일이라도 생긴 모양이군. 일이 다 잘 풀렸으면 좋겠는데... 요즘 들어 덩굴발일족 놀들이 남쪽에서 발생한 무언가 때문에 몹시 격앙되어 있다는 건 알고 있소이다. 어쩌면 라스칼이 그곳에서 당했을지도 모르는 일이오. 나라면 조심하겠소, 친구.\n\n어쨌거나, 다시 한번 감사 드리오. 이건 이 꾸러미를 배달해 준 데 대한 보상이니 받아 주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4282] = {title = "잔존하는 희망", objective = "치안대장 윈저의 잃어버린 단서를 가져 와야 합니다.\n\n치안대장 윈저는 골렘 군주 아젤마크와 사령관 앵거포지가 이 정보를 가지고 있을 것이라 생각합니다.", description = "<쪽지를 흔들며 흥분하는 치안대장 윈저>\n\n이게 무슨 뜻인지 알기나 하오?\n\n어쩌면 모두 다 잃은 건 아닐지도 모르오! 내가 확인할 수 있는 바로는, 검은무쇠단 드워프인 사령관 앵거포지와 골렘 군주 아젤마크가 그 정보를 지니고 있소. 우리가 친절하게 부탁한다 해도 그냥 순순히 정보를 건네 주진 않을 것 같소.\n\n당신이 싸울 준비가 돼 있다면 좋겠군.\n\n가서 이 두 악당을 찾아내시오! 녀석들을 쳐부수고 내 잃어버린 단서를 다시 가져와 주시오!", progress = "이 대단한 속임수도 곧 끝나게 될 거요.", completion = "&lt;손에 든 두 개의 서판을 낚아채는 치안대장 윈저&gt;\n\n이제 여기서 빠져나가야 하오!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4283] = {title = "50개의 메달", objective = "랄리우스가 검은바위부족 메달 50개를 가져다 달라고 부탁했습니다. 불타는 평원에 있는 오크들에게서 메달을 구할 수 있는 가능성이 큽니다.", description = "한 가지 작은 비밀을 알려 주지, 병사. 좀 더 가까이 오게.\n\n나는 여기서 유일하게 제정신일세!\n\n이 사람들을 한번 보라고! 다들 미친 것 같지 않은가? 다들 미쳤어! 돌았지! 제정신이 아냐!\n\n<목소리를 낮추는 랄리우스>\n\n우리끼리만 아는 걸로 하자고. 나, 자네, 그리고 내 친구 윙키 선장, 이렇게만 말일세.\n\n<허공을 붙들고 쥐어짜는 랄리우스>\n\n어쨌든... 내 오우거 귀 수집품에 어울릴 만한 메달을 모으고 있다네. 오늘은 오크 메달이야. 50개만 가져오라고. 자, 시작!\n\n<뿔피리를 부는 랄리우스>\n\n가져오라고!", progress = "<꽤 큼직하게 절단된 오우거 귀에다 대고 말하는 랄리우스>\n\n여기는 불타는 평원, 본부 나와라, 오버.", completion = "해냈군! 자네에게 줄 보상은 바로 내 배를 문지를 수 있는 이용권일세! 자! 문질러 보라고!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4284] = {title = "마력의 수정", objective = "붉은 마력의 수정, 푸른 마력의 수정, 노란 마력의 수정, 녹색 마력의 수정을 각각 7개씩 모아 마샬의 야영지에 있는 J.D. 콜리에게 가져가야 합니다.", description = "당신도 오고 가면서 봤을 거예요. 여기 저기 널려있거든요!\n\n무슨 얘기냐고요? 당연히 수정 얘기죠!\n\n수정들이요... 분화구 주변에 널려 있잖아요. 대부분의 친구들은 관심도 주지 않지만 난 왠지 그 수정 안에 어떤 힘이 들어있을 것 같은 예감이 들어요. 여기서 그 수정들로 실험을 하고 있었지만 아무것도 알아낼 수가 없었어요. 뭐, 언젠가는 알아내겠죠.\n\n그래서 말인데요, 지금 수정이 별로 없으니까 당신이 가서 좀 모아 줄래요?", progress = "수정에 분명히 뭔가가 있어요!", completion = "이제 실험을 계속해야겠네요! 고마워요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4285] = {title = "북쪽 수정탑", objective = "운고로 분화구에 있는 북쪽 수정탑의 위치를 알아내야 합니다.", description = "무엇에 쓰이는 걸까? 도저히 생각을 떨쳐버릴 수 없네요!\n\n악! 미쳐버릴 거 같아요! 수정탑에 대한 소문은 분명 사실이라고요. 순진한 노움이라고 불러도 좋아요. 난 사람들이 하는 말은 죄다 믿거든요.\n\n그거야 어쨌든 여기서 꽤 가까운 곳에 수정탑이 하나 있다고 들었어요. 북쪽 어딘가에 있다던데... 그 위치를 찾아주세요. 분명히 있다니까요.", progress = nil, completion = "이 소문들은 분명 사실이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4286] = {title = "좋은 물건", objective = "검은바위 나락으로 가서 검은무쇠단 벨트주머니 20개를 얻어야 합니다. 이 임무를 완수하면 랄리우스에게 돌아가십시오. 검은바위 나락 안에 사는 검은무쇠단 드워프들이 이 '벨트주머니'라는 물건을 지니고 다닐 것입니다.", description = "윙키 선장이 그러는데, 검은바위 나락에 있는 검은무쇠단이 좋은 물건을 온통 다 차지하고 있다고 하는군. 그렇지, 윙키?\n\n<나름대로 최선을 다해 해적 흉내를 내는 랄리우스>\n\n어이, 친구. 그럼, 물론이지!\n\n봤나? 검은바위 나락에 들어가서 그 좋은 물건을 좀 가져오게.\n\n가서 돈을 잔뜩 벌어 오라고!", progress = "방해하지 말라고. 나랑 윙키는 지금 회의가 있어서 말이야.", completion = "&lt;산더미처럼 쌓인 벨트주머니를 뒤지기 시작하는 랄리우스&gt;\n\n오, 장난이 아니군!\n\n&lt;벨트주머니 더미에 그 큰 코를 박고 크게 숨을 들이쉬는 랄리우스&gt;\n\n맛있겠는걸! 이것들 좀 보라고!\n\n자네도 하나 가져가, 친구. 나누어 줄 수 있는 게 얼마든지 있으니까 말이야, 하하.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n때묻은 자루"},
[4287] = {title = "동쪽 수정탑", objective = "운고로 분화구에 있는 동쪽 수정탑의 위치를 알아내야 합니다.", description = "이곳에서 지내는 동안 분화구 외곽에 있는 수수께끼의 수정탑에 대한 이상한 소문을 들었어요. 수정탑 내부에 수정이 늘어서 있는 상당히 큰 수정탑인가 봐요.\n\n직접 본 적은 없지만 이 소문이 사실이라는 생각이 자꾸 드는군요. 그리고 그 수정탑이 우리가 찾은 수정과 관련이 있다는 생각이 드네요.\n\n내 궁금증을 해소하도록 좀 도와주지 않겠어요? 듣자 하니 분화구의 동쪽 지역에 수정탑이 하나 있는 것 같아요. 그걸 찾을 수 있겠어요?", progress = nil, completion = "운고로는 참 괴상한 곳이에요. 분화구에 들어서면 꼭 다른 세계에 있는 기분이라니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4288] = {title = "서쪽 수정탑", objective = "운고로 분화구에 있는 서쪽 수정탑의 위치를 알아내야 합니다.", description = "내 실험이 아직 성공하지 못했는데 말이죠. 소문으로 들은 수정탑 하나를 찾을 수만 있으면 실험에 성공할 수 있을지도 모르겠다는 생각이 자꾸 드네요.\n\n혹시 특정 색을 조합한다면... 내가 너무 성급한 판단을 내리는 것 같군요. 수정탑부터 찾도록 하죠!\n\n분화구의 서쪽 지역에서 찾아 보세요. 소문에 의하면 그 지역 어딘가에 있다고 해요.", progress = nil, completion = "분화구 옆을 따라가다 보면 숨겨진 장소가 군데군데 있는데, 더 이상 찾아볼만한 곳이 없으면 꼬불꼬불한 길을 조사해 보세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4289] = {title = "운고로의 유인원", objective = "운고로 분화구 입구에 있는 토르와 패스파인더에게 운고로 고릴라 모피 2개, 운고로 우레고릴라 모피 2개, 운고로 천둥고릴라 모피 2개를 가져가야 합니다.", description = "이 분화구에는 많은 생물들이 살고 있는데, 내 고향 땅과 그 너머에 살고 있는 생물들보다 더 고귀한 것 같소. 구체적으로 설명할 순 없지만 이곳은 대지모신의 존재가 강하게 느껴지는 곳이오. 나는 이곳에서 대지모신의 아름다운 생물들을 접할 때마다 대지모신에게 경의를 표하곤 한다오.\n\n그대도 그러한 위업을 달성하는 힘을 느끼고 싶다면 북쪽으로 가보시오. 그곳에 사는 유인원은 평범한 생명체가 지닌 힘의 한계를 시험할 수 있는 좋은 대상이지. 녀석들의 모피를 가져와 그대의 힘을 입증해 보이시오.", progress = "벌써 그들에게 패하고 돌아온 건가?\n\n그렇게 쉽게 포기하지 마시게. 훌륭한 사냥꾼에게도 운고로의 유인원을 추적하고 물리치는 것은 쉬운 일이 아니까 말이야.", completion = "잘했군. 그대는 운고로의 거대한 유인원들을 물리칠 수 있을 정도로 강하다는 것을 입증했소. 라르코르위에 비하면 유인원이 힘든 상대는 아니지만 이 위대한 승리를 그대에게서 앗아가진 않겠소.\n\n이 모피는 우리 부족에게 멋진 옷이 되어줄 거요. 그대는 나도 돕고 그대의 가치도 입증했소.\n\n그대가 다른 임무를 맡아 떠나기 전에 대지모신에게 찬미를 드리고 그대에게 목숨을 잃은 유인원의 영혼에 감사하도록 하시오. 그들도 자신들의 죽음이 헛되지 않았음을 알아야 하니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4290] = {title = "라르코르위의 먹이", objective = "라르코르위가 막 잡은 사냥감을 찾아 트레샤돈 시체 덩이를 훔친 후 운고로 분화구에 있는 토르와 패스파인더에게 돌아가야 합니다.", description = "아주 오래전, 내 형이 라르코르위가 잡은 사냥감에서 고기를 조금 뜯어간 적이 있었소. 그 때 형은 몰랐지만 라르코르위는 숲에서 형을 봤던 거요. 라르코르위는 며칠 동안 형을 따라다니며 형이 손대는 것은 뭐든지 부숴버렸지. 겁에 질린 형은 결국 라르코르위를 피하기 위해 운고로 분화구에서 도망쳤소.\n\n하지만 여기서 멀지 않은 곳에서 끝내 라르코르위에게 목숨을 잃고 말았소.\n\n라르코르위를 자극하려면 녀석이 죽인 신선한 사냥감에서 고기를 좀 가져가면 되오. 고깃덩이를 가지고 다시 내게 돌아오시오.", progress = "내 말을 가벼이 여기지 마시오. 진정 이 짐승과 맞서고 싶다면 굉장히 신중해야 하고 머리를 잘 써야 하오. 라르코르위를 끌어내 물리치려면 많은 힘과 지혜가 필요할 것이오.", completion = "이거면 되오. 요즘은 라르코르위가 잘 먹는 모양이군. 그런데 이 지역 어디서 트레샤돈을 잡았는지 궁금하군그래.\n\n어쨌든 그대가 라르코르위와 맞설 준비가 될 때까지 내가 이 고기를 보관하고 있겠소. 내 신변은 걱정하지 마시오. 그대가 라르코르위를 흥분시켜놔서 그대의 살을 맛보기 전에는 날 해치지 않을 테니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4291] = {title = "라르코르위의 냄새", objective = "운고로 분화구 입구에 있는 토르와 패스파인더에게 라바사우루스 페로몬샘 2개를 가져가야 합니다.", description = "라르코르위가 아직까지 그대를 잡으러 오지 않았다니 참으로 의외로군. 하지만 이 괴물을 유인할 마지막 계획이었으니 문제없소.\n\n라르코르위는 가장 힘이 센 수컷이라 녀석이 원하는 어떤 암컷과도 교미를 할 수 있지. 녀석은 여러 암컷과 교미를 하오. 여기서 서쪽으로 가면 라바사우루스 알이 잔뜩 있을 거요. 알에 가까이 다가가면 암컷들이 공격하려고 달려들 것이오. 라르코르위의 짝은 머리에서 지독한 냄새를 풍겨 수컷에게 교미할 준비가 되었음을 알리는데, 그 페로몬샘 2개를 내게 가져오시오.", progress = "알이 든 둥지에 다가가면 분명 어미들이 공격할 테니 조심하시오. 그대가 이미 페로몬샘 하나를 얻었다 해도 말이지. 어미들이 자기 새끼를 보호하려고 싸울 때는 라르코르위만큼이나 위험하오. 하지만 성공한다면 틀림없이 라르코르위를 유인할 수 있을 것이오.", completion = "아. 아주 좋은 종이로군. 그대가 가져온 이 두 개면 충분히 라르코르위를 밖으로 유인해낼 수 있을 거요. 그대와 그 괴물의 싸움이 어떻게 끝날지 무척 기대되는군. 녀석은 덩치도 크고 손톱도 마치 잘 간 칼날처럼 예리하지. 눈 속만 들여다봐도 죽음을 느낄 수 있을 정도라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4292] = {title = "라르코르위를 위한 미끼", objective = "토르와의 주머니에 든 물건들로 라르코르위를 불러내 물리친 후 라르코르위의 머리를 운고로 분화구 입구에 있는 토르와 패스파인더에게 가져가야 합니다.", description = "이번 임무는 계획에 조금 복잡한 면이 있어 가장 어려운 부분이 될 것 같소. 여기서 북쪽으로 가면 산으로 들어가는 좁은 길이 있는데 내가 마지막으로 라르코르위를 본 곳이지. 한 때 그 일대를 돌아다니던 거대한 짐승들의 뼈가 널려 있다면 제대로 간 것이오. 그대가 회수한 고깃덩이를 그곳에 내려놓고 내가 만든 이 혼합물을 고기에 문지르시오. 이 두 가지 미끼를 모두 다 썼는데도 라르코르위가 나타나지 않는다면 그 때는 나도 달리 방법이 없다오.", progress = "공포를 두려워하지 마시오. 공포란 아주 큰 배반자요... 마음을 굳게 먹어야 하오!\n\n고기를 가지고 가서 계곡에다 내려놓고 페로몬샘을 문지르시오. 그래야만 라르코르위가 그대와 맞서려고 나타날 거요.", completion = "대지모신께 영광을! 해냈군! 그것도 정정당당히 말이야. 그대는 자신이 훌륭한 사냥꾼임을 입증했소. 그대의 정신은 굳세고 용기는 비할 데가 없으며 힘은 더욱 강해졌소. 그대의 솜씨에 경의를 표하는 바이오.\n\n내 조상 중에서도 가장 위대한 분만이 이토록 엄청난 업적을 이룰 수 있었을 거요. 축하하오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n평원추적자 튜닉척후병 다리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4293] = {title = "진흙괴물 견본...", objective = "악령의 숲에 있는 진흙괴물에게서 악령의숲 진흙괴물 견본을 모은 후 언더시티의 연금술사 퓰리 옆에 있는 실험 기구를 사용해 어느 견본이 가장 부패한 것들인지 알아내야 합니다. 부패한 악령의숲 견본 5개를 찾으면 연금술사 퓰리에게 가져가야 합니다.", description = "악령의 숲은 불모의 땅 북쪽에 있는 숲으로 잿빛 골짜기보다 더 멀리 있소. 그곳에는 악마의 손길이 닿은 웅덩이 주변에 진흙괴물들이 득실거리고 있소. 스컬지는 지옥불정령과 다른 악마의 마법으로 그 숲을 공격했는데 이 때 진흙괴물들이 땅 위로 올라온 것 같소.\n\n악령의 숲 진흙괴물의 견본을 모아오면 내 옆에 있는 이 실험 장비를 사용해 실험 대조 표준을 만들어 당신이 모아온 다른 견본들과 비교해 볼 것이오.", progress = "대조 표준을 만들려면 적어도 부패한 악령의숲 견본 5개가 필요하오. 우리에게 필요한 양을 줄 수 있을 때까지 계속해서 악령의숲 진흙괴물 견본을 모으도록 하시오. 실바나스 여왕님의 명령이외다...", completion = "아. 훌륭하군. 이 견본들이면 되겠소. 도와줘서 고맙소이다.\n\n진흙괴물의 견본을 모두 모았으니 더 많은 것을 알아낼 수 있을 거요. 실바나스 여왕님의 예감이 적중하기도 했지만 그분 자신조차도 예측하지 못할 만큼 깊은 식견이 있었던 게 아닌가 생각되오. 이 견본들은 아주 흥미롭군. 내 혼합물들에 반응하는 모양을 보니... 흠. 그래. 분명 더 조사해봐야겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4294] = {title = "... 그리고 한 무리의 수액괴물", objective = "운고로 분화구에 있는 진흙괴물과 수액괴물에게서 운고로 진흙괴물 견본을 모은 후 언더시티의 연금술사 퓰리 옆에 있는 실험 기구를 사용해 어느 견본이 가장 순수한 것인지 알아내야 합니다. 순수한 운고로 견본 5개를 찾으면 연금술사 퓰리에게 가져가야 합니다.", description = "운고로 분화구라고 들어본 적 있소? 타나리스 사막 근처에 있는데 아주 화려한 곳이지. 푸르고 활기가 넘쳐 각종 동식물이 서식하는 곳이오.\n\n당신이 그곳에 가줘야겠소. 그곳은 외부의 손길이 닿지 않은 순수한 곳이라고 들었소. 탐험가들도 이제 막 그 비밀을 밝혀내기 시작했지.\n\n그곳에 서식하는 진흙괴물과 수액괴물을 실험해보고 싶소. 타락되지 않는 게 사실이라면 어떻게 그런 생물들이 진화하게 되었는지 알고 싶소이다.", progress = "그래, 실험은 어떻게 되어가오?", completion = "정말 놀랍군. 운고로 분화구는 생각했던 것보다 훨씬 많은 비밀을 간직하고 있는 것 같군. 실험을 더 하면 또 어떤 사실이 밝혀질까 궁금하군그래.\n\n정말 놀라워... 이 견본의 순수함을 보시오. 흠... 이게 무슨 의미인지 궁금하군. 자연의 힘 같은 걸 지니고 있는 듯하지만 무언가 더 있는 것 같소. 이걸 보니... 고대 신들이 생각나는군. 아제로스 각지에서 고대 신들의 흔적을 찾았는데, 이 생물들이 그들과 관련이 있지 않을까 하오.\n\n좀 더 실험을 해봐야겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4295] = {title = "락노트의 에일 맥주", objective = "아, 에일 맥주! 검은무쇠단 에일 맥주가 마시고 싶어 죽겠군! 어서, 술이 깨려 하고 있다고! 어떻게 아느냐고? 난 술이 깨면 눈 앞이 흐려진단 말이지... 그리고 눈 앞이 흐려지니 당신이 마치 내가 지난주에 처치한 <race>처럼 보이고 있다고!", description = nil, progress = "아, 에일 맥주! 검은무쇠단 에일 맥주가 마시고 싶어 죽겠군! 어서, 술이 깨려 하고 있다고! 어떻게 아느냐고? 난 술이 깨면 눈 앞이 흐려진단 말이지... 그리고 눈 앞이 흐려지니 당신이 마치 내가 지난주에 처치한 <race>처럼 보이고 있다고!", completion = "이게 뭐지? 오호라! 이 냄새는 검은무쇠단 에일 맥주 같은데! 술 때문에 눈은 나빠졌어도 당신이 내 진정한 친구라는 건 알겠군, 하하!", rewards = nil},
[4296] = {title = "일곱 현자의 서판", objective = "불타는 평원에 있는 맥스워트 우버글린트에게 서판 사본을 가져가야 합니다.", description = "나는 일곱 현자의 전설을 쫓아 불타는 평원에 왔지. 그들은 대단한 힘과 지식을 지닌 드워프들이었는데, 당신에게도 힘과 지식이 있으면 부도 따라오는 법이라구.\n\n내가 원하는 게 바로 그거야. 부자 말이지!\n\n일곱 현자에 대해 더 알아낼 수 있다면 우리 둘 다 부자가 될 수 있을 거요. 타우릿산의 폐허에 이 고대 드워프들의 지식이 기록되어 있는 일곱 현자의 서판이 있다는 소문이 있지. 이 서판을 찾아 거기에 쓰여 있는 글의 사본을 내게 가져와. 그 서판의 비밀을 함께 알아내자구!", progress = "일곱 현자의 글을 가져왔소? 그들의 서판에서 비밀을 알아낸 거요?", completion = "아, 서판을 찾았군! 사본도 아주 훌륭해! 당신, 정말 &lt;class&gt; 맞소? 혹시 사본을 만드는 필경사 아니야?\n\n자, 받으라구. 내가 약속했던 사례요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4297] = {title = "먹이 찾기", objective = "동부 내륙지에 있는 아그나르 비스테이머에게 긴발톱 은빛갈기늑대 갈비살 5개를 가져가야 합니다.", description = "화살요정용들은 잡식 동물이라 고기와 채소를 모두 먹는다네. 자네의 알들이 곧 부화할 테니 미리 준비를 해 두는 게 좋겠네. 믿거나 말거나, 이런 어린 녀석들에게는 즙 많은 날고기 조각 같은 게 좋지. 어째서 그런지는 나도 알아낼 수 없었는데, 엘프들을 위한 엘룬의 계획과 상관이 있네... 아마 수호자나 뭐 그런 게 되는 거였겠지.\n\n이제 알은 내가 돌볼 테니 이 녀석이 부화하면 먹을 수 있도록 괜찮은 긴발톱 은빛갈기늑대 갈비살이나 좀 가져오는 게 어떻겠나?", progress = "고기는 찾아 온 건가? 자네의 작은 알은 이제 부화할 때가 거의 다 됐네. 처음 먹는 음식을 좋은 것으로 먹이지 않으면 한 주도 넘기지 못할지 모르네. 그런 일이 일어나서는 안 되지.\n\n음, 더 이상 거짓말하지 않겠네. 난 애초에 당신이 이 알을 손에 넣었다는 것부터가 부럽네. 자네를 이렇게 도와 준 걸 후회하지 않도록 해 주게나.", completion = "이거면 충분하겠군. 그리고 내 생각이 맞다면 이 알은 곧 부화할 걸세. 기분이 어떻나? 이제 곧 아빠가 될 텐데 말이야. 하하, 그런 막중한 책임을 지게 될 줄은 몰랐겠지? 안 그런가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4298] = {title = "부모 되기", objective = "동부 내륙지에 있는 아그나르 비스테이머와 대화해야 합니다.", description = "어어, 생각했던 것보다 훨씬 더 일찍 부화하겠는걸...", progress = nil, completion = "자, 알을 받게나... 새끼가 처음으로 자네를 보고 아빠로 인식하도록 해야 하니까 말이야.\n\n축하하네. 자네는 이제 아빠가 된 걸세... 말하자면 말이지.", rewards = "다음과 같은 것들을 받습니다:\n\n화살요정용 알"},
[4300] = {title = "발톱으로 만든 무기", objective = "오그리마에 있는 제스리몬에게 라바사우루스의 흰발톱 8개를 가져가야 합니다.", description = "흠, 지금 생각해 보니 당신이 검은손 도적단을 위해 할 만한 일이 있겠군. 그래, 이 제스리몬이 자네의 도움을 꼭 얻었으면 해.\n\n운고로 분화구에 가보면 아주 날카로운 발톱을 지닌 랩터들이 살고 있지. 그런데 새까만 발톱만이 아니라, 어떤 놈들은 하얀 발톱을 하고 있다네. 검은손 도적단의 고객 중에는... 이 흰발톱으로 만든 무기를 아주 좋아하는 이들이 있다네. 그 발톱을 많이 가져오면 아주 짭짤하게 값을 쳐주지. 일을 빨리 해치우면 내가 다른 일을 도와 줄 수도 있고 말이지.", progress = "내 고객들은 성질이 꽤 급하지. 발톱은 좀 구한 건가?", completion = "아, 이거면 좋겠군. 고맙네. 예정보다 더 빨리 가져왔군. 아주 좋아.\n\n이 발톱으로 자네에게 맞는 무기를 하나 만들어 줄 수도 있는데, 생각 있나?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n백골 고리백골 갈퀴백골 창\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4301] = {title = "강대한 우차", objective = "운고로 분화구 입구에 있는 토르와 패스파인더에게 우차의 모피를 가져가야 합니다.", description = "운고로를 탐험하는 동안 그대처럼 강한 사냥꾼이 흥미를 가질만한 녀석을 보았소. 그 중 하나는 북쪽에 사는 고릴라인데 다른 고릴라에 비해 덩치가 무척이나 컸소. 전에 그대도 가본 적이 있는 동굴이지만 이번에 내 임무를 맡으면 살아서 돌아올 수 없을지도 모르겠군.\n\n나는 녀석을 우차라고 부르는데, 대지모신의 위대한 아들 중 하나임이 분명하오. 우차를 물리치고 그 가죽을 가지고 오시게. 그러면 그대가 위대한 사냥꾼이라는 사실을 내가 증명해주지.", progress = "우차... 그 야수는 아주 굉장하지. 붉은 털로 덮인 거대한 몸집에 단검 크기만한 이빨을 가지고 있소. 팔은 나무통만큼이나 굵고, 속도는 지금까지 보아온 어느 산사자에도 뒤지지 않을 만큼 빠르다오. 그대는 그러한 존재를 대상으로 용기를 시험할 수 있다는 사실을 감사히 여겨야 하오. 우리 동족도 그러한 생물을 만나려면 수십 년을 보내야 할 테니까 말이야.", completion = "수고했소. 참으로 기쁘군. 그대는 오늘 아주 큰 일을 해냈소.\n\n우차는 내가 본 유인원 중 가장 거대한 녀석이었지. 그대가 그런 녀석을 쓰러뜨렸다는 사실은 그대의 힘은 물론이고 용기에 대해서도 잘 증명해주는 것이오.\n\n경의의 표시로 이걸 주겠소. 그대라면 이걸 받을 자격이 있소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n야수 분쇄기야수잡이 도끼\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4321] = {title = "수정탑 정보 수집", objective = "잠시 기다린 후, J.D. 콜리와 대화해야 합니다.", description = "당신이 전해준 수정탑 정보는 매우 재미있군요...\n\n계산을 좀 할 테니 잠깐만 기다려 주세요. 잠시 후에 다시 찾아오시면 우리가 찾고 있던 해답을 해 줄 수도 있겠네요.", progress = nil, completion = "다 됐어요. 아주 재미있군요... 이 도형이 틀리지 않았으면 좋겠네요! 모든 것을 이 책자에 수록했는데, 당신이 가지세요.\n\n이제 수정탑에 대한 질문은 모두 대답할 수 있을 것 같네요.", rewards = "다음과 같은 것들을 받습니다:\n\n수정탑 사용설명서"},
[4322] = {title = "탈옥!", objective = "치안대장 윈저가 자신의 장비를 되찾고 갇힌 동료들을 풀어 주는 것을 도와야 합니다. 성공하면 치안대장 맥스웰에게 돌아가십시오.", description = "여기서 빠져나가야 하오. 보급 구역에서 내 장비를 되찾고 갇혀 있는 동료들을 풀어 주는 걸 도와 주시오. 살아서 출구까지 도착하면 모건의 망루로 가서 맥스웰 치안대장을 만나도록 하시오. 그가 추가적인 지시를 내릴 것이오.", progress = nil, completion = "놀랍군. 정말 놀라워. 윈저님이 조금 전에 급하게 여길 떠나셨소. 윈저님은 뭔가 대단한 요구를 하실 것 같아. 하지만 자신이 가지고 있는 증거가 확실하게 뒷받침을 해 줄 것이라고 말씀하셨소이다. 그 분은 지금 스톰윈드로 볼바르님과 프레스톨님을 만나러 가고 계실 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n징벌의 검숙련의 전투 단도\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n정기의 수호물"},
[4324] = {title = "유카 스크류스피곳", objective = "불타는 평원에 있는 유카 스크류스피곳과 대화해야 합니다.", description = "내 남동생 리블리는 평생 아무짝에도 쓸모없는 녀석이었는데, 이제 드디어 조금이나마 쓸모가 있게 된 것 같아요! 하지만... 새로 찾아낸 리블리의 가치를 이용하려면 당신의 도움이 필요하겠어요.\n\n내 여동생 유카가 몇 주째 리블리 녀석을 찾아다니다 불타는 평원에까지 이르렀죠. 유카가 소식을 보내왔는데 용병의 도움이 필요하다고 하더군요.\n\n자, 어떻게 하시겠어요? 도와 주시겠어요? 그렇다면 내 여동생과 얘기를 해 보세요. 동생은 우레망치 바위굴에서 북서쪽에 있는 화염 마루라는 동굴에 있을 겁니다.", progress = nil, completion = "맞아요, 남동생을 찾고 있어요. 어서 찾아서 데리고 가야 해요. 제발...\n\n만약 몸 성히 데려갈 수 없다면... 머리만이라도 상관없어요.", rewards = nil},
[4341] = {title = "카란 마이트해머", objective = "검은바위 나락으로 가서 카란 마이트해머를 찾아야 합니다.\n\n국왕은 카란이 그곳에 포로로 잡혀 있을 것이라고 말했습니다. 그곳 감옥을 찾아보는 것이 좋겠습니다.", description = "연기가 피어 오르는 타우릿산의 폐허에 가 보았다고? 혹시 카란 마이트해머라는 한심한 녀석을 만나지 못했나? 그는 내 사랑스런 딸을 지키기로 했던 드워프였지!\n\n<흐느끼는 국왕>\n\n그런데 지금 내 딸이 사라져 버렸어!\n\n병사들을 보내 불타는 평원을 샅샅이 뒤져 보았지만, 그 아이의 행방에 대해 얻은 유일한 단서는 검은바위 나락 안에 있을지도 모른다는 것뿐이야. 이... 이미 죽었을지도 몰라!\n\n카란은 그곳에 포로로 잡혀 있는 것 같네. 가서 그를 찾게! 어떻게 된 것인지 내 꼭 알아야겠네!", progress = nil, completion = "제발 내 말 좀 들어 주시오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4342] = {title = "카란의 이야기", objective = "카란 마이트해머가 하는 이야기를 들어야 합니다.", description = "판결을 내리기 전에 내 얘기를 들어 보시오!", progress = "내 얘기를 마칠 수 있게 해 주시오.", completion = "보다시피, 나는 어떻게 할 도리가 없었소이다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4343] = {title = "오염된 바람꽃", objective = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어 있고 독성을 품고 있는 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어 있고 독성을 품고 있는 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "바람꽃에 세나리온 식물 고약 두 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4361] = {title = "나쁜 소식 전달", objective = "아이언포지로 돌아가 국왕 마그니 브론즈비어드에게 이 나쁜 소식을 전해야 합니다.", description = "이 정보를 반드시 마그니 국왕께 전달해야 하오. 그분이라면 어떻게 해야 할지 아실 거요!", progress = nil, completion = "&lt;마그니 국왕이 분노하며 주먹을 내리칩니다.&gt;", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4362] = {title = "왕국의 운명", objective = "검은바위 나락으로 돌아가 제왕 다그란 타우릿산의 사악한 손아귀에서 공주 모이라 브론즈비어드를 구출해야 합니다.", description = "내 오랜 적, 다그란 타우릿산이 내 왕국을 마음대로 주무를 수 있게 돼 버린 것 같네.\n\n그대가 내 마지막 희망일지도 모르는 일이지, <name>. 내 소중한 딸, 모이라를 구출하게!\n\n타우릿산이 모이라에게 건 마법을 확실하게 해제하는 길은 단 한 가지뿐이네. 그를 처치하는 것!\n\n절대 모이라는 해치지 말게! 그 아이는 타우릿산의 조종을 받고 있다는 사실을 명심해야 할 것이네! 모이라가 하는 행동이나 말은 모두 타우릿산이 건 사악한 마법 주문의 결과일 뿐이니!", progress = nil, completion = "&lt;제왕 다그란 타우릿산이 죽은 것을 보고 흐느껴 우는 브론즈비어드 공주&gt;\n\n도대체 왜???", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4363] = {title = "브론즈비어드 공주", objective = "아이언포지로 돌아가서 국왕 마그니 브론즈비어드와 대화해야 합니다.", description = "오, 이럴 수가! 타우릿산은 위대하고 명예로운 드워프였어요. 당신은 내 삶과 아직 태어나지 않은 내 아이의 삶을 망친 거라고요!\n\n<제왕 타우릿산이 공주에게 건 마법의 효과가 아직 완전히 가시지 않은 것이 아닌가 생각됩니다.>\n\n아이언포지로 돌아가서 내 아버지께 아이언포지 왕국의 상속자는 검은무쇠단 드워프가 될 거라고 전하세요.\n\n아버지께서 허락을 하시든 하지 않든 그렇게 될 거라고요.", progress = nil, completion = "&lt;몹시 분노하고 있다는 것 같은 마그니 브론즈비어드 국왕&gt;\n\n타우릿산 녀석이 죽어서까지도 이긴 모양이군.\n\n이제 가 보게. 떠나기 전에 왕실 보물창고에서 그대가 원하는 보상을 골라 가도록 하게.\n\n&lt;왕좌에 축 늘어져 이 기이한 상황 전개에 대해 깊이 숙고하는 브론즈비어드 국왕&gt;", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n마그니의 결의아이언포지의 노랫돌\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4381] = {title = "회복의 수정", objective = "이 수정탑 도식판에서 녹색 마력의 수정과 노란 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 자신이나 동료를 치유할 수 있습니다.", description = nil, progress = "이 수정탑 도식판에서 녹색 마력의 수정과 노란 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 자신이나 동료를 치유할 수 있습니다.", completion = "탁자 위에 수정을 올려놓고 신중하게 색을 맞춥니다. 마지막 하나를 밀어 넣자 빛이 터져 나오면서 수정이 융합됩니다.\n\n이제 융합된 결과물을 얻었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n회복의 수정"},
[4382] = {title = "정신력의 수정", objective = "이 수정탑 도식판에서 녹색 마력의 수정과 푸른 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 자신의 정신력을 증가시킬 수 있습니다.", description = nil, progress = "이 수정탑 도식판에서 녹색 마력의 수정과 푸른 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 자신의 정신력을 증가시킬 수 있습니다.", completion = "탁자 위에 수정을 올려놓고 신중하게 색을 맞춥니다. 마지막 하나를 밀어 넣자 빛이 터져 나오면서 수정이 융합됩니다.\n\n이제 융합된 결과물을 얻었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n정신력의 수정"},
[4383] = {title = "수호의 수정", objective = "이 수정탑 도식판에서 녹색 마력의 수정과 붉은 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 물리적인 피해에 대한 보호를 강화할 수 있습니다.", description = nil, progress = "이 수정탑 도식판에서 녹색 마력의 수정과 붉은 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 물리적인 피해에 대한 보호를 강화할 수 있습니다.", completion = "탁자 위에 수정을 올려놓고 신중하게 색을 맞춥니다. 마지막 하나를 밀어 넣자 빛이 터져 나오면서 수정이 융합됩니다.\n\n이제 융합된 결과물을 얻었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n수호의 수정"},
[4384] = {title = "굴복의 수정", objective = "이 수정탑 도식판에서 붉은 마력의 수정과 푸른 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 적의 방어력을 약화시킬 수 있습니다.", description = nil, progress = "이 수정탑 도식판에서 붉은 마력의 수정과 푸른 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 적의 방어력을 약화시킬 수 있습니다.", completion = "탁자 위에 수정을 올려놓고 신중하게 색을 맞춥니다. 마지막 하나를 밀어 넣자 빛이 터져나오면서 수정이 융합됩니다.\n\n이제 융합된 결과물을 얻었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n굴복의 수정"},
[4385] = {title = "발화의 수정", objective = "이 수정탑 도식판에서 붉은 마력의 수정과 노란 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 거대한 폭발을 일으켜서 적에게 피해를 입힐 수 있습니다.", description = nil, progress = "이 수정탑 도식판에서 붉은 마력의 수정과 노란 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 거대한 폭발을 일으켜서 적에게 피해를 입힐 수 있습니다.", completion = "탁자 위에 수정을 올려놓고 신중하게 색을 맞춥니다. 마지막 하나를 밀어 넣자 빛이 터져나오면서 수정이 융합됩니다.\n\n이제 융합된 결과물을 얻었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n발화의 수정"},
[4386] = {title = "돌기의 수정", objective = "이 수정탑 도식판에서 푸른 마력의 수정과 노란 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 적에게 피해를 입히는 보호막을 만들어낼 수 있습니다.", description = nil, progress = "이 수정탑 도식판에서 푸른 마력의 수정과 노란 마력의 수정을 조합할 수 있습니다.\n\nJ.D.의 설명서에 따르면 이 둘을 조합하여 적에게 피해를 입히는 보호막을 만들어낼 수 있습니다.", completion = "탁자 위에 수정을 올려놓고 신중하게 색을 맞춥니다. 마지막 하나를 밀어 넣자 빛이 터져나오면서 수정이 융합됩니다.\n\n이제 융합된 결과물을 얻었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n돌기의 수정"},
[4401] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨 나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨 나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4402] = {title = "갈가르의 선인장 사과 별미", objective = "갈가르에게 선인장 사과 10개를 가져가야 합니다. 선인장 근처에서 찾을 수 있다고 한 말이 기억납니다.", description = "여기 시험의 골짜기는 확실히 더워요.\n\n<이마의 땀을 닦는 갈가르>\n\n선인장 사과만 좀 있으면 저만의 특제 선인장 사과 별미를 만들 수 있을 텐데 말입니다! 그 맛있는 간식 한 조각만큼 빨리 열기에 지친 몸을 식힐 수 있는 것도 드물지요.\n\n이렇게 하는 게 어떻겠습니까? 선인장 사과 10개를 가져오시면 여행 길에 드실 수 있도록 선인장 사과 별미를 몇 개 만들어 드리지요. 생각이 있으시다면 이곳 주변에 자라난 선인장에서 선인장 사과를 따오세요.", progress = "선인장 사과를 다 모으셨습니까?", completion = "좋았어요! 약속한 대로 선인장 사과 별미와 또 약간의 사례를 추가로 하겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n선인장 사과 별미"},
[4403] = {title = "오염된 바람꽃", objective = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어 있고 독성을 품고 있는 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려있는 열매는 썩어 있고 독성을 품고 있는 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "바람꽃에 세나리온 식물 고약 두 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4421] = {title = "비취불꽃의 오염", objective = "비취불꽃의 악마추종자 11명, 그림자추적자 9명, 도적 9명과 사바스라스를 처치해야 합니다. 임무를 완수하면 에리단 블루윈드에게 돌아가야 합니다.", description = "모험을 찾아 여기까지 오는 사람은 흔치 않은데... 악령의 숲에 사악한 기운과 오염은 이미 널리 퍼져버렸소.\n\n나는 에메랄드 의회의 일원으로서, 이 땅을 치유하고자 하오. 그런데 어떤 존재들은 이 땅이 더욱 오염되기를 바라고 있으니...\n\n그 존재들은 바로 북서쪽, 콘스텔라스 폐허에 도사리고 있는 비취불꽃 사티로스들이지. 그 사티로스들의 우두머리는 잔인하기 짝이 없는 사바스라스라는 자요. 그들은 마주치는 족족 모든 생명체들을 오염시키고 있다오.\n\n한때는 아름다웠던 우리 땅을 지켜야 하오. 제발 사바스라스와 그의 부하들을 처치해주시오.", progress = nil, completion = "사바스라스를 악령의 숲에서 몰아낸 것은 긴 여정의 시작일 뿐이오. 그 악마가 입힌 피해를 복구하는 데 많은 노력을 기울여야 할 거요.\n\n이곳에 그 사티로스 말고 훨씬 더 사악한 존재가 있다는 것이 느껴지지만 때가 되기 전엔 알 수 없는 거지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4441] = {title = "저주받은 고대 수호자", objective = "다르나서스에 있는 달의 신전으로 가서 에리단의 유리병을 사용하여 축복받은 물을 담아 와야 합니다. 꽉 찬 물병을 에리단에게 가져와야 합니다.", description = "당신이 발견한 그 플룻은 고대 수호자의 뼈를 깎아 만든 거요. 고대 수호자는 나이트 엘프족을 충실히 지켜온 나무정령들이지.\n\n그런데 눈에 보이는 모든 것에 저주를 내리는 사티로스가 그 고대 수호자들에게도 저주를 내려 악령의 숲을 빼앗아 버렸소. 저주받은 고대 정령들은 사악한 저주에 의해 영원히 고통에서 해방될 수 없게 되었소.\n\n우리가 플룻을 정화해야 하오. 다르나서스에 있는 달의 신전에서 축복받은 물을 가져다주시오.", progress = "축복받은 물로 고대 정령들을 속박에서 풀어 안식을 얻게 해줄 수 있다면 좋겠는데...", completion = "고맙소, &lt;name&gt;. 이제 그 오래된 저주가 풀리기를 기도하는 일만 남았군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4442] = {title = "정화", objective = "잠시 후 에리단과 다시 얘기해야 합니다.", description = "당신이 담아다 준 엘룬의 샘물로 플룻을 정화할 거요. 이런 비극은 여기서 끝나야만 하오.\n\n엘룬께서 내게 능력과 용기를 주셔야 할 텐데...\n\n잠시 기다려 보시오.", progress = nil, completion = "축복받은 물로 플룻에 속박된 고대 정령을 해방시켰소. 이제 이 플룻을 신성한 장소에서 사용하면 고대의 정령을 소환할 수 있을 거요.\n\n서쪽 강철나무 숲에 있는 폐허가 적당할 것 같군. 예전에 그곳에는 저주받은 나무정령들이 많이 살고 있었으니 죽은 후에도 그곳을 떠돌고 있을지 모르오.", rewards = "다음과 같은 것들을 받습니다:\n\n고대의 플룻"},
[4443] = {title = "오염된 채찍뿌리", objective = "채찍뿌리인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 땅 위로 드러난 뿌리는 거칠고 단단한 가죽처럼 보입니다. 식물에는 끈적끈적한 실 같은 것도 매달려 있습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "채찍뿌리인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 땅 위로 드러난 뿌리는 거칠고 단단한 가죽처럼 보입니다. 식물에는 끈적끈적한 실 같은 것도 매달려 있습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "채찍뿌리에 세나리온 식물 고약 세 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
