[4447] = {title = "오염된 어둠용풀", objective = "어둠용풀인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어서 독성이 있는 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "어둠용풀인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어서 독성이 있는 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "어둠용풀에 세나리온 식물 고약 네 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4448] = {title = "오염된 어둠용풀", objective = "어둠용풀인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어서 독성이 있는 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "어둠용풀인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어서 독성이 있는 것 같습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "어둠용풀에 세나리온 식물 고약 네 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4449] = {title = "화장실에 갇힌 사람", objective = "검은무쇠단 지질학자 8명을 처치하고 이글거리는 협곡의 화장실에 갇힌 사람에게 비단 옷감 15개를 가져가야 합니다.", description = "이봐! 이보라고, 자네! 이리 좀 와보게!\n\n나 좀 꺼내주게. 검은무쇠단 드워프 녀석들에게서 도망치다가 이곳에 숨게 됐지. 머저리 같은 지질학자들! 또 그 마법은 어떻고! 녀석들이 내가 숨는 걸 본 모양이야. 녀석들이 언제 왔다 갔는지도 모르게 와서는 문을 잠가 버리고 날 이 좁은 곳에 가둬버렸지 뭔가.\n\n저 지질학자 녀석들에게 따끔한 맛을 보여주란 말이야! 아. 그리고 그, 뭐냐... 비단 옷감 몇 조각만 구해줄 수 있나? 그... 쓸 데가 있어서 말이야.", progress = "난 하루종일 기다릴 순 없네! 빨리 비단 옷감을 구해달란 말이야! 아니, 그러니까... 그 지질학자들 말이네! 그 지질학자들을 혼내 주라고! 녀석들에게 나의... 아니, 자네의 분노를 보여줘!", completion = "이야, 좋은걸! 감촉도 그만이고!\n\n뭐라고? 아, 그렇지. 지질학자들. 손 좀 봐줬나? 뭐라고 감사해야 할지 모르겠군. 이제 여기서 볼 일을 마저 끝낼 시간이 생겼군... 정말 고맙네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4450] = {title = "타나리스의 장부", objective = "굿스틸 장부를 가지고 거기에 적힌 물건들을 다 모은 다음 타나리스에 있는 크린클 굿스틸을 찾아가야 합니다.", description = "아, 그러고 보니 생각이 나는군.\n\n내가 타나리스에 있을 때 맡은 작은 임무를 끝내주지 않겠나? 아주 쉬운 일이야...\n\n가젯잔의 크린클 굿스틸이 이 이글거리는 협곡과 다른 몇 군데서 나는 무언가를 찾고 있었네. 자네가 목록을 한번 훑어보고 굿스틸에게 그 물건들을 가져다줄 수 있겠나?\n\n관심이 있다면 굿스틸 장부를 문 밑으로 넣어주지. 굿스틸이 원하는 물건들을 다 모으면 이 장부와 함께 가져다주게.", progress = "오, 음? 무슨 일이지, <race> 친구? 손님이 워낙 밀려서 엄청나게 바쁘단 말이야. 당신만 아니면 일을 더 빨리 끝낼 수 있을 것 같은데 말이지. 기분 나쁘게 할 생각은 아니지만 지금 내 일을 다 마칠 시간도 없는 판이라고.", completion = "오, 내가 요청했던 일을 좀 해냈군. 훌륭해. 나는 당신이 내게 와서 뭔가를 만들어달라고 할 줄 알고 있었는데 말이야.\n\n음.. 물건들은 모두 완벽하군... 하나도 빠짐없이 다 있어. 고마워, &lt;class&gt; 친구.\n\n무슨 보답이라도 해야겠는데... 흠, 어떤 게 좋을까?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n충전된 벼락 막대보복의 벨트\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4451] = {title = "자유의 열쇠", objective = "이글거리는 협곡을 탐색해서 검댕가루 화장실 열쇠의 용도를 알아내야 합니다.", description = "이 작은 놋쇠 열쇠는 굉장히 단순해 보입니다. 특별히 눈에 띄는 것이라곤 열쇠 머릿부분에 새겨진 글뿐입니다.\n\n\"검은무쇠단 간이 화장실용 - 복제 금지.\"\n\n이게 무슨 뜻이고 앞으로 어떤 일이 생길지 전혀 알 수 없습니다.", progress = "*험험*\n\n누구요? 사람 있다고!", completion = "세상에! 어떻게 이런 일이!? 자네가 열쇠를 찾았군! 저 괘씸한 검은무쇠단 녀석들이 날 여기에 가두고 열쇠를 어딘가에 숨겼을 거라 생각하고 있었지! 정말로 고맙네. 자네 최고로군! 자, 이제 그 열쇠로 이 불쌍한 로키드를 여기서 꺼내 주게!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4461] = {title = "오염된 채찍뿌리", objective = "채찍뿌리인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 땅 위로 드러난 뿌리는 거칠고 단단한 가죽처럼 보입니다. 식물에는 끈적끈적한 실 같은 것도 매달려 있습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "채찍뿌리인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 땅 위로 드러난 뿌리는 거칠고 단단한 가죽처럼 보입니다. 식물에는 끈적끈적한 실 같은 것도 매달려 있습니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "채찍뿌리에 세나리온 식물 고약 세 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4462] = {title = "오염된 어둠용풀", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[4463] = {title = "숙고의 고서", objective = "재료를 보여 주시오, 나약한 존재여.\n\n그리고 이 창조물의 대가로 골드 30개도 내놓아야 할 것이오.", description = nil, progress = "재료를 보여 주시오, 나약한 존재여.\n\n그리고 이 창조물의 대가로 골드 30개도 내놓아야 할 것이오.", completion = "어서 장신구를 가져가시오, 어리석은 생명이여. 내가 연구를 할 수 있도록 내버려두란 말이오!", rewards = "다음과 같은 것들을 받습니다:\n\n하급 숙고의 영약"},
[4464] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨 나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨 나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4465] = {title = "오염된 노래꽃", objective = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨 나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨 나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "노래꽃에 세나리온 식물 고약을 약간 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4466] = {title = "오염된 바람꽃", objective = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어 있고 독성을 품은 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어 있고 독성을 품은 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "바람꽃에 세나리온 식물 고약 두 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4467] = {title = "오염된 바람꽃", objective = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어 있고 독성을 품은 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", description = nil, progress = "바람꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에 달려 있는 열매는 썩어 있고 독성을 품은 듯 합니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.", completion = "바람꽃에 세나리온 식물 고약 두 개를 바릅니다. 그러자 즉시 병든 모양이 사라지면서 싱싱하고 건강한 식물로 변합니다.", rewards = nil},
[4481] = {title = "골격의 고서", objective = "이 세계의 모든 것에는 그에 대한 대가가 있게 마련이오. 그대가 찾는 바로 그 물건의 값은 30골드요.\n\n물론 그대가 모은 재료의 대부분을 내가 갖게 될 것이오. 하지만 장신구는 갖게 될 테니 걱정 마시오.", description = nil, progress = "이 세계의 모든 것에는 그에 대한 대가가 있게 마련이오. 그대가 찾는 바로 그 물건의 값은 30골드요.\n\n물론 그대가 모은 재료의 대부분을 내가 갖게 될 것이오. 하지만 장신구는 갖게 될 테니 걱정 마시오.", completion = "그대와 같이 나약한 종족이 그분의 일생의 일을 마치다니, 그분께 수치가 아닐 수 없군.\n\n결정체를 받고 썩 가 버리시오!", rewards = "다음과 같은 것들을 받습니다:\n\n하급 골격의 영약"},
[4482] = {title = "불굴의 고서", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n하급 불굴의 영약"},
[4483] = {title = "탄력의 고서", objective = "원하는 게 탄력의 고서라면 30골드를 내놓아야 하오.", description = nil, progress = "원하는 게 탄력의 고서라면 30골드를 내놓아야 하오.", completion = "다른 고서들은 이 세계에서 분실됐소. 그대가 감히 들어가지도 못할 장소에서 분실됐단 말이오. 그대라면 차라리 존재하지 않는 편이 좋았을 거라고 생각할 곳 말이지.\n\n이 재료들의 힘은 내가 흡수하겠소. 나머지 찌꺼기 힘은 그대가 가지도록 하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n하급 탄력의 영약"},
[4484] = {title = "탐욕의 고서", objective = "내 시간을 낭비하지 말고 어서 30골드와 필요한 재료들을 가져오시오.", description = nil, progress = "내 시간을 낭비하지 말고 어서 30골드와 필요한 재료들을 가져오시오.", completion = "머리가 지끈거리는군... 우리 우주를 구성하는 거대한 공간의 힘이... 으아아아악!\n\n&lt;고통스러워하는 것 같은 마스레디스&gt;\n\n원하는 걸 가지고 얼른 떠나시오!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n하급 탐욕의 영약하급 탐욕의 영약하급 탐욕의 영약하급 탐욕의 영약하급 탐욕의 영약"},
[4485] = {title = "고결함의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화해야 합니다.", description = "안녕하세요. 당신의 헌신은 신앙만큼이나 강하군요.\n\n이제는 스톰윈드에 있는 두소리안 랄님과 얘기를 나눌 때라고 생각됩니다. 내가 보기에는 당신은 더 많은 기술과 능력을 배울 준비가 된 것 같습니다.\n\n스톰윈드의 빛의 대성당에서 두소리안님을 찾으세요. 그리고 이제부터 받게 될 훈련을 진지하게 받아들이세요. 지금 당신이 서 있는 자리는 겸손과 노력을 통해 오른 자리니만큼 오만해져서 우리를 실망시키는 일이 없어야 합니다.\n\n그럼, 빛이 함께하시길.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4486] = {title = "고결함의 고서", objective = "스톰윈드에 있는 두소리안 랄과 대화해야 합니다.", description = "이런, 이런, 이런. 명성이 자자한 성기사님께서 납셨군.\n\n오, 미안하오. 기분 나쁘게 하려는 건 아니오... 그냥 가끔씩 당신이 세운 공적을 볼 때면 부러워서 그러는 것이지. 타이자님은 그게 바로 나의 약점이라고 말씀하신다오. 그래서 나도 그 점을 고치겠다고 맹세했지. 하지만 때로는 그게 잘 안 된단 말이지.\n\n당신과 얘기를 나누고자 한 건 스톰윈드에 있는 두소리안 랄님께서 소식을 전해왔기 때문이오. 당신이 준비가 됐을 때 빛의 대성당으로 찾아오라고 했는데 중요한 일인 것 같았소. 꼭 무슨 일이라도 일어나고 있는 것처럼 말이오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4487] = {title = "지옥마 소환", objective = "톱니항에 있는 스트라드 파선과 대화하십시오.", description = "잘 왔소! 당신의 주의를 끌기 위해 <서큐버스/지옥불정령> 한 마리를 보내 당신 뒤를 좇도록 했는데, 당신이 먼저 날 찾아온 것 같군. 뭐, 그건 그렇다 치고.\n\n요즘 들어 당신의 힘이 커지는 것에 대해 여기저기서 말들이 많소. 당신에게는 좋은 소식이지만 다른 이들에게는 나쁜 소식일 수 있겠지. 하지만 그런 건 상관없는 일이니 접어 두고, 내가 하고 싶은 얘기는, 당신은 실력을 증명해 보였으니 이제... 헤헤... 일종의 작은 선물 같은 걸 받을 만한 자격이 있단 말이지.\n\n불모의 땅에 있는 톱니항 위에 스트라드라는 이가 있소. 아마 전에 서로 만난 일이 있을 거요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4488] = {title = "지옥마 소환", objective = "톱니항에 있는 스트라드 파선과 대화하십시오.", description = "아, <name>. 이런 몸소 납시셨군요. 이렇게 기쁠 데가!\n\n하지만 제가 당신 수발까지 들어줄 거란 기대는 마세요. 당신은 빠른 속도로 강해져 가고 있을지 모르지만 진정한 지식을 이해하는 데 있어 당신은 아직 애송이에 불과해요. 조심하지 않으면 타락이 당신의 약한 의지를 압도해 버릴 거예요.\n\n그럼, 이제 요점만 얘기하죠. 스트라드가 당신과 얘기를 나누고 싶어 해요. 아직 불모의 땅에 있는 톱니항이 내려다보이는 탑에 살고 있어요. 너무 지체하지 않는 게 좋을 겁니다.", progress = nil, completion = "이렇게 다시 찾아와 나의 존재를 빛내주다니. 참으로 친절하시구려.\n\n내 수행사제들은 당신이 안 오는 것이 아닌가 궁금해 하고 있었소. 하지만 나는 분명히 올 거라고 했지. 당신은 힘과 관련된 일이라면 마치 불을 향해 날아드는 나방처럼 끌리게 되어 있으니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4489] = {title = "지옥마 소환", objective = "톱니항에 있는 스트라드 파선과 대화하십시오.", description = "이 보게. 잠깐 이리 와보게!\n\n당신이 그 유명한 <name> 맞나?\n\n역시 맞았군. 용건만 간단히 말하지. 당신의 힘은 점점 커가고 있고 그 사실은 많은 이들에게 인정을 받았소. 이제 그 노고에 대한 보상을 받을 때가 된 거지.\n\n불모의 땅으로 가게. 톱니항 위에서 스트라드 파선이라는 자를 찾을 수 있을 걸세. 혹시 그자가 누군지 기억나는가? 스트라드가 얘기를 나누고 싶어하네. 서두르는 게 좋을 거야.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4490] = {title = "지옥마 소환", objective = "톱니항에 있는 스트라드 파선과 대화해 지옥마 소환 능력을 배워야 합니다.", description = "당신의 인내와 노고에 대한 보상을 주겠소. 하지만 이걸 알아두시오. 앞으로는 지옥마를 소환하는 능력을 갖기가 훨씬 더 어려워질 것이오. 반드시 그 능력을 얻어야 하겠지만... 쉽지만은 않을 게요.\n\n일단은 지옥마를 소환해서 원하는 대로 사용하도록 하시오.", progress = nil, completion = "행운을 빌겠소, &lt;name&gt;. 앞으로 또 만나길 기대 하겠소.", rewards = "다음과 같은 것들을 배웁니다:\n\n지옥마 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n지옥마 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4491] = {title = "내 친구의 작은 도움", objective = "마샬의 야영지에 있는 스프래글 프록에게 링고 스타를 데려다 주어야 합니다.\n\n링고 스타가 기절하면 스프래글의 수통을 사용해 깨워야 합니다.", description = "으... 너무 덥군...\n\n난 이 지역을 조사하고 있었는데 갑자기 견딜 수 없을 정도로 열이 났어요. 열사병에 걸린 게 분명해요.\n\n부탁인데 마샬의 야영지에 있는 내 친구 스프래글에게 날 좀 데려가 주세요. 거기까지라면 내가 따라갈 수 있을 것 같아요.\n\n정신이 좀 없으니 내가 또 기절하면 스프래글이 준 수통에 있는 물을 얼굴에 뿌려주세요. 그거라면 될 거예요... 아마도...", progress = nil, completion = "링고의 상태가 좋진 않지만 그래도 살아 돌아와서 다행이에요!\n\n찾아주셔서 감사합니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n보석박힌 다리보호구우듬지 다리보호구흙마루 투구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4492] = {title = "링고 찾기", objective = "불기둥 마루에서 링고 스타를 찾아야 합니다.", description = "절 좀 도와주세요! 제 친구 링고가 아까 남쪽에 있는 화산을 조사하러 갔는데, 시간이 지나도 돌아오지 않네요. 정말로 걱정 되서 죽겠어요.\n\n당신이 링고를 찾을 수 있을까요? 제 수통을 가지고 가세요. 링고를 찾으면 이게 분명히 필요할 거예요.", progress = "으... 누구죠?", completion = "아... 누군가 날 찾아줘서 다행이에요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4493] = {title = "실리시드의 행진", objective = "가젯잔에 있는 연금술사 페슬저그와 대화하십시오.", description = "실리시드의 의도, 아니, 실리시드의 존재 이유는 생태계의 질서를 벗어나 자신들에게 방해가 되는 모든 생명체들을 집어삼켜 버리는 것 같아요. 이 한 가지 목표에만 맹렬히 달려드는 존재들이다 보니 아제로스의 모든 생명체에 심각한 위협이 되고 있습니다.\n\n지금까지 우리가 보아 온 것은 시작에 불과해요. 녀석들의 힘은 칼림도어의 깊숙한 곳으로부터 나오는 것 같습니다. 바로 운고로 분화구 말입니다. 타나리스 사막에 있는 가젯잔으로 가서 연금술사 페슬저그와 얘기해 보십시오. 그에게 제 생각을 얘기해 주면 반드시 우리가 실리시드와 싸우는 데 도움을 줄 겁니다.", progress = nil, completion = "네, 그라시나가 보낸 건 줄 알고 있었습니다. 당신이 이 야수들과 싸운 것은 아주 귀중한 경험입니다. 내가 알기에는 전에 아무도 이런 녀석들과 감히 대적해 본 일이 없으니까요. 운고로 분화구가 그들의 중심지일지도 모른다는 그라시나의 생각은 그럴 듯 하군요. 운고로는 여기서 서쪽에 있는 신비롭고 위험한 밀림인데, 실리시드의 정체를 알아내는데 한걸음 더 다가서게 될지도 모르겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4494] = {title = "실리시드의 행진", objective = "가젯잔에 있는 연금술사 페슬저그와 대화하십시오.", description = "실리시드의 존재 이유는 눈 앞에 보이는 모든 생명체들을 동족이 아닌 한 모조리 집어삼켜 버리기 위함인 것 같소. 이 단 한 가지 목표에만 열중하는 녀석들이다 보니, 지금 아제로스 전체에 심각한 위협이 되고 있소.\n\n지금까지 우리가 보아 온 것은 초기 단계일 뿐이오. 녀석들의 힘은 칼림도어의 깊숙한 곳, 운고로 분화구로부터 나오는 듯하오. 타나리스 사막에 있는 가젯잔으로 가서 연금술사 페슬저그와 얘기해 보시오. 그에게 이 사실을 얘기해 주면 반드시 우리가 실리시드와 싸우는 데 도움을 줄 거요.", progress = nil, completion = "그래, 질지빈이 보낼 줄 알고 있었소. 당신이 이 괴물들과 싸운 경험은 아주 귀중한 거요. 내가 알기에는 전에 아무도 그들과 맞서 본 일이 없으니까 말이오. 운고로 분화구가 그들의 중심지일지도 모른다는 질지빈의 생각은 그럴 듯하군. 운고로는 여기서 서쪽에 있는 신비롭고 위험한 밀림이오. 그곳에 가면 실리시드의 정체를 밝혀내는데 한걸음 더 다가서게 될지도 모르겠소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4495] = {title = "죽마고우", objective = "북쪽의 동굴 근처에서 이베론을 찾아야 합니다.", description = "이베론이라는 친구가 매일 같은 시간에 저를 찾아오곤 하죠. 그런데 오늘은 코빼기도 안 보이니 이상한 일이에요. 벌써 몇 시간 전에는 왔어야 정상인데 말이죠.\n\n뭐, 제 걱정이 좀 지나치다는 건 인정해요, <name>. 이베론은 여기에서 북쪽에 있는 동굴 근처에서 많은 시간을 보내곤 해요. 거기는 사방에 거미들이 득실거리는 위험한 곳이죠.\n\n혹시 그곳을 지나게 되면 그가 무사한지 한번 찾아봐 주시겠어요?", progress = nil, completion = "당신이 나를 찾아오다니 얼마나 다행인지 모르겠소. 내가 여기 있는 건 어떻게 알았소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4496] = {title = "밀림 속 생물", objective = "가젯잔에 있는 연금술사 페슬저그에게 고리쉬 향낭 1개와 운고로 토양 견본 5개를 가져가야 합니다.", description = "조사해본 결과 실리시드는 벌과 비슷했습니다. 그리고 여왕을 제거하면 나머지는 모두 혼돈에 빠지게 된답니다. 여왕을 유인할 미끼를 만들어줄 테니 해치워 주십시오.\n\n하지만 먼저 미끼를 만들 재료가 좀 필요합니다. 아무런 준비도 없이 섣불리 밀림으로 들어갈 수는 없지 않소. 서쪽, 운고로 분화구에 있는 실리시드 소굴로 가 녀석들에게서 향낭 하나를 가져 오십시오. 그리고 운고로 토양 견본도 좀 필요합니다.", progress = "향낭에 상처가 나서는 안 됩니다. 쉽게 얻을 수 있는 게 아니니까. 향낭을 찾으려면 시간이 좀 걸릴지도 모릅니다. 그리고 토양은 찾기 쉬울 겁니다.\n\n그건 그렇고, 미끼를 만들 재료들은 가지고 왔소?", completion = "좋았어. 이 향낭들은 세포막도 온전하고, 좋아! 흙은... 그렇지. 이거면 딱 되겠습니다. 여기에 나의 특수 첨가물을 넣어서 갈면 완벽한 미끼를 만들 수 있습니다.\n\n내가 미끼를 만드는 동안 잠시만 기다리십시오. 미끼가 완성되면 다음 단계를 실행해 실리시드를 저지할 수 있을 겁니다. 녀석들이 가젯잔과 칼림도어 전체를 집어삼키기 전에...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4501] = {title = "테러닥스 주의", objective = "테러닥스 10마리와 광포한 테러닥스 15마리를 처치한 후 마샬의 야영지에 있는 스프래글 프록과 대화해야 합니다.", description = "현상수배: 운고로 분화구에 서식하는 테러닥스를 처치할 능력 있는 투사를 찾습니다. 현재 테러닥스의 수가 늘어나 이 지역 행인들에게 큰 위협이 되고 있습니다.\n\n테러닥스 10마리와 광포한 테러닥스 15마리를 처치하고 임무가 끝나면 스프래글 프록을 찾아가 현상금을 받도록 하십시오.", progress = nil, completion = "이곳에 사는 테러닥스는 정말 너무 무서워요! 녀석들의 수를 줄여주셔서 감사합니다. 이제야 안심하고 마샬의 야영지 밖으로 나갈 수 있겠네요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n석판 장갑바위 판금 경갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4502] = {title = "화산 활동", objective = "운고로 분화구의 화산 주위에 있는 불의 정령에게서 운고로 재 견본 9개를 모아 톱니항에 있는 리브 리즐픽스에게 가져가야 합니다.", description = "마본 리벳시커씨의 수습생으로 일하면서 많은 것을 배웠어요. 하지만 리벳시커씨가 너무 오래 자리를 비우고 계셔서 이제 직접 몇 가지 실험을 해볼까 생각 중이죠.\n\n가장 최근에 읽은 책이 운고로 분화구 중앙부에서 일어나고 있는 심상치 않은 화산 활동에 관한 것이었어요. 제 생각에 그곳의 정령들에게서 재를 조금만 구해온다면 많은 사실을 알아낼 수 있을 것 같아요.\n\n혹시 그곳으로 가실 계획이라면 절 위해서 재를 좀 구해다 주시겠어요?", progress = "운고로의 화산이 활화산이라는 게 사실인가요? <name>씨, 그 화산의 재만 있으면 많은 사실을 알아낼 수 있을 거예요.", completion = "이 견본은 완벽한 연구 자료가 될 거예요. 고마워요. 연구 결과가 나오면 가장 먼저 알려 드릴게요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4503] = {title = "쉬즐의 비행선", objective = "마샬의 야영지에 있는 쉬즐에게 갈퀴 달린 디메트로돈 비늘 8개와 갈퀴 달린 테러닥스 비늘 8개를 가져가야 합니다.", description = "난 지금 비행선을 만들고 있지!\n\n난 여기서 오도가도 못하게 된 상황인데 워낙 길눈이 어두워서 말이야. 그리핀이나 박쥐를 타고 가젯잔으로 돌아갔으면 하는데, 그 녀석들을 타면 죽을까 무서워서 원...\n\n그래서 말인데 좀 도와주지 않겠나? 이제 날개만 만들면 되는데 테러닥스와 디메트로돈의 갈퀴 달린 비늘이면 딱 좋겠단 말이야. 나는 녀석들과 싸울만한 실력이 전혀 없지만 당신은 잘 싸울 수 있을 것 같으니 당신이 한 번 시도해 보지 않겠나?", progress = "훌륭한 비행선에는 꼭 이름을 지어 줘야지... 이름을... 퓨니드라고 하는 게 어떨까 하는데!", completion = "아, 이 비늘이면 완벽하겠군. 이 비늘이라면 분명 비행선을 이륙시킬 수 있을 거야!\n\n고맙다고, 친구!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n쉬즐의 비막이 덮개쉬즐의 구멍마개쉬즐의 기름걸레\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4504] = {title = "초강력 접착제", objective = "매우 끈적거리는 타르 12개를 모아 가젯잔에 있는 트란렉에게 갖다 주어야 합니다.", description = "언제나 전 어떻게 하면 빨리 돈을 벌 수 있을까 고민한답니다. 참신한 아이디어가 하나 떠올랐는데 도움이 필요해요. 아, 물론 얼마간의 이익은 꼭 챙겨드리지요. 어때요?\n\n그래요! 제 청을 흔쾌히 들어주실 줄 알았어요!\n\n자, 그럼 운고로 분화구 북부에 있는 잿구덩이로 가서 타르를 좀 구해다 주세요. 아무 타르나 되는 건 아니고 반드시 그 잿구덩이 근처에서 사는 송진괴물들의 것이라야 합니다. 일반 타르는 점성이 부족한지 좀처럼 끈적거리지가 않거든요.\n\n그 식물처럼 생긴 생명체들의 피부에는 엽록소가 들어있기 때문에 질이 아주 좋은 끈적거리는 타르를 얻을 수 있다고요! 그걸로 초강력 접착제를 만들어 볼 생각이에요!", progress = "이 트란렉이 생각해낸 아이디어 정말 기발하지요?! 이번에 초강력 접착제를 만들어 내면 분명 엄청난 히트를 칠 거라고요!", completion = "아, 이 타르면 딱 좋아요...\n\n어라, 이런! 내 손이... 손이 안 떨어지네...\n\n그렇게 좋은 생각이 아니었나 보군. 아냐, 잠깐! 초강력 접착제를 녹이는 용해제! 그걸 만들면 진짜 돈벌이가 될 거야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4505] = {title = "오염된 달샘", objective = "비취불꽃의 사티로스가 지키는 달샘에서 오염된 물 견본을 채취하여 피멍울 초소에 있는 위나 해저드에게 가져가야 합니다.", description = "뭐, 내가 무자비하고 물불을 안 가린다고 말하는 사람도 있지만, 다 우리 호드가 얼라이언스보다 조금이라도 우세하기를 간절히 바라는 마음에서 그런 거지.\n\n그건 그렇고 요새 내 흥미를 끄는 것이 바로 남쪽, 콘스텔라스 폐허에 비취불꽃의 사티로스들이 지키는 달샘이란 것인데... 그 샘은 한때 지긋지긋한 나이트 엘프족에게 부활의 상징이었지만 지금은 저주를 받아 사티로스 서식지로 오염됐다더군.\n\n내게 좋은 생각이 있어. 일단 내 고양이에게 그 샘의 물을 먹여 시험을 해봤으면 해. 당신이 가서 달샘의 물을 조금 가져다 줬으면 좋겠는데, 어떻게 생각하나?", progress = "이건 정말 중요한 일이니까 꾸물거리지 말고 어서 출발하는 게 좋을 거야.", completion = "좋아, 아주 좋아! 이제 샘물에 걸린 저주를 적에게 이용할 방법만 찾으면 되겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4506] = {title = "오염된 고양이", objective = "위나의 고양이를 오염된 달샘으로 데려가서 풀어 준 다음 위나에게 다시 데려가야 합니다.\n\n위나에게로 데려간 후 클릭하면 위나에게 돌아갈 것입니다.", description = "잘만 하면 이 오염된 물을 이용할 수 있겠어. 흐흐흐... 고양이에게 샘물을 조금 먹여봤더니 어쩐 일인지 몸집이 두 배로 커지고 힘도 세졌잖아. 바로 그 점을 이용할 수도 있을 것 같단 말이지.\n\n자, 콘스텔라스 폐허로 이 고양이 가방을 가져가서 달샘 옆에 고양이를 풀어 놓아봐. 하하, 아마 만족스러운 결과가 나올 거야. 기대하라고...\n\n고양이를 다시 데려오면 내가 유용하게 써먹을 수 있을 거야.", progress = "설마 거기 다시 못 가겠다는 건 아니지? 아님 어서 안 가고 뭘 꾸물거리는 게야?", completion = "훌륭해!\n\n얼라이언스를 물리칠 수 있다면 수단, 방법 가리지 않는 것이 바로 우리 포세이큰의 방식이야. 오염된 물은 앞으로 유용하게 이용할 수 있겠어.\n\n달샘에 또 고양이를 데려가고 싶으면 언제든지 말만 하게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4507] = {title = "여왕의 뇌", objective = "여왕 고리쉬를 불러내 처치해야 합니다.\n\n가젯잔에 있는 연금술사 페슬저그에게 여왕 고리쉬 뇌를 가져가야 합니다.", description = "여기, 미끼를 받으십시오. 놈들의 소굴에 들어가면 수정 같은 걸 찾을 수 있을 겁니다. 소굴 안에 있는 부화장을 한번 살펴보십시오. 실리시드들은 그 수정을 일종의 순응 장치로 사용하는 것 같습니다.\n\n수정에 미끼를 바르면 여왕이 나타날 겁니다. 부하 몇을 데리고 나올 테니 조심하십시오. 여왕을 처치한 후에는 뇌를 꺼내와야 합니다. 끔찍한 소리처럼 들리겠지만 반드시 조사해봐야 하니까요. 행운을 빌겠습니다, <name>!", progress = "여왕의 뇌는 연구에 절대적으로 중요한 물건입니다. 우리가 알아낸 바에 의하면 어떤 사악하고 교활한 존재가 실리시드들을 조종하고 있는 것 같습니다. 실리시드처럼 악랄한 녀석들을 조종할 수 있는 존재라면 상상만 해도 소름이 끼칩니다.", completion = "멋집니다! 오늘은 그야말로 대승을 거두었군요, &lt;name&gt;. 이 뇌를 완전히 분석하는 데는 시간이 좀 걸리겠지만 유용하게 쓸 테니 걱정 마십시오.\n\n그런데 실리시드 말입니다. 전 왠지 녀석들의 세력이 그게 전부가 아니라는 생각이 듭니다. 이런 말 하긴 죄송하지만 이번 일은 너무 쉽게 끝나버린 듯한 느낌입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4508] = {title = "폭풍전야", objective = "다르나서스에 있는 그라시나 스피릿마이트에게 페슬저그의 운고로 보고서를 가져가야 합니다.", description = "오늘 얻은 정보는 내가 최근에 발견한 사실들과 함께 이런 일에 정통한 자의 손에 넘겨야 합니다. 이곳 가젯잔에서도 불가능한 것은 아니지만 우리 힘만으로는 무리지요.\n\n내 최신 보고서를 다르나서스에 있는 그라시나 스피릿마이트에게 가져다주십시오. 아직도 달의 신전에 있는 걸로 아는데, 안 그렇습니까? 그녀는 얼라이언스의 거물급을 친구로 두고 있으니 그들까지 이 일에 끌어들인다면 이 상황에서 무사히 빠져나갈 수 있을지도 모릅니다.", progress = "그 자들은 정말 한심합니다! 주변에 더 큰 위협이 있는지 찾아볼 생각도 않는다니까요. 가슴 속에 맹목적인 증오를 키우고 있는 호드의 손에 의해 결국 우리 모두 끝장나고 말 겁니다. 실리시드 소굴로 데리고 가서 직접 보여 주는 것 말고는 달리 어떻게 실리시드의 위협을 알려야 할지 모르겠습니다!\n\n아, 죄송합니다. 제게 무슨 소식을 가져온건가요?", completion = "정말 고맙긴 하지만 이게 우리에게 무슨 도움이 될지는 모르겠군요. 얼라이언스는 호드가 아닌 다른 위협은 그냥 무시해 버리니까 말입니다. 다르나서스에 있는 우리 지도자들조차도 이 위협이 정확히 무엇인지에 대해서는 의견이 분분해요. 판드랄 스테그헬름 같은 바보들은 실리시드가 고대의 위협이라는 제 주장을 믿지 않습니다. 무식한 데다 오만하기까지 하지요.\n\n당신은 그 위협을 직접 보셨으니 이해하리라 믿습니다. 우리는 계속해서 실리시드를 물리치는 데 전념해야 합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4509] = {title = "폭풍전야", objective = "오그리마에 있는 질지빈 드럼로어에게 페슬저그의 운고로 보고서를 가져가야 합니다.", description = "내가 최근에 발견한 사실과 오늘 여기서 얻은 정보는 이런 일을 다룰 줄 아는 자의 손에 넘겨져야 하오. 이곳 가젯잔에서도 처리할 수 없는 것은 아니지만 우리 힘만으로는 무리요.\n\n내 최신 보고서를 오그리마에 있는 질지빈 드럼로어에게 가져다주시오. 아직도 골목길 위쪽에 있는 집에 사는 걸로 아는데, 그렇지 않소? 그는 호드 고위층에 친구를 두고 있으니 그 자들도 이 일에 끌어들인다면 이 상황에서 무사히 빠져나갈 수 있을지도 모르오.", progress = "그 자들은 정말 한심하네! 주변에 더 큰 위협이 있는지 찾아볼 생각도 하지 않는다니까. 얼라이언스의 맹목적인 증오 때문에 결국엔 우리 모두 끝장나고 말 걸세. 실리시드 소굴로 데리고 가서 직접 확인시켜 주는 것 말고는 달리 어떻게 실리시드의 위협을 알려야 할지 모르겠군!\n\n아, 미안하네. 내개 소식을 가져온겐가?", completion = "정말로 고맙긴 하지만 이게 우리에게 무슨 도움이 될지는 모르겠네. 게다가 호드는 얼라이언스의 위협이 아닌 다른 위협은 그냥 무시해 버리고 있지. 확실한 증거만 있다면 스랄님께서 직접 행동을 취할 수도 있지만 제각기 다른 조언들을 해오니 누구 말을 들어야 할지 난감한 상황일세. 이 바보 같은 녀석들은 얼라이언스를 덮칠 수만 있다면 땅에다 박치기라도 하라고 할 자들이라네.\n\n자네도 그 위협을 직접 보았잖나? 우리는 계속해서 실리시드를 물리치는 데 전념해야 하네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4510] = {title = "폭풍전야", objective = "다르나서스 은행에 있는 이드리아나에게 은행 증서를 가져가야 합니다.", description = "그대는 지금까지 너무나도 큰 도움을 주었습니다. 분명 언젠가 다시 한번 실리시드에 맞서 싸우는 데 도움을 요청하게 될 겁니다. 운고로에서 알아낸 사실들을 반드시 기억해 두어야 합니다. 이제 보니 실리시드가 운고로에서 나왔을지도 모른다는 제 가설은 틀렸던 것 같군요... 다른 어떤 곳에 훨씬 더 강한 존재가 있을 겁니다.\n\n이 쪽지를 은행에 있는 이드리아나에게 가져다주십시오. 금고에서 제가 부탁한 감사의 선물을 꺼내 드릴 겁니다. 도와 주셔서 감사합니다, 용감한 <class>|1이여;여;.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n망각의 보주괴물숲 어깨갑옷회피의 경갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4511] = {title = "폭풍전야", objective = "오그리마 은행에 있는 카루스에게 은행 증서를 가져가야 합니다.", description = "자네가 아니었으면 이만큼 해내지 못했을 걸세. 분명 언젠가 다시 실리시드와의 전쟁을 위해 자네의 도움을 요청할 날이 있을 걸세. 운고로에서 알아낸 것들을 반드시 잘 기억해두어야 하네. 이제 보니 실리시드가 운고로에서 나왔을지도 모른다는 내 가설은 틀렸던 것 같군. 다른 어떤 곳에 훨씬 더 강한 악의 근원이 존재하겠지.\n\n이 쪽지를 은행에 있는 카루스에게 가져다주게. 감사의 표시로 내 금고에서 뭔가를 꺼내 줄 걸세. 도와 줘서 고맙네, 강한 <class>|1이여;여;.", progress = "저그 저그! 뭘 도와 드릴까요?", completion = "이 은행 증서로 질지빈 드럼로어의 계좌에서 물건 하나를 인출해 그대에게 드릴 수 있습니다. 축하를 드리는 게 순서겠군요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n망각의 보주괴물숲 어깨갑옷회피의 경갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4512] = {title = "수액괴물 견본 수집", objective = "아이언포지에 있는 라리스 기어더들에게 가득찬 저주받은 수액괴물 병 6개와 가득찬 부패한 수액괴물 병 6개를 가져가야 합니다.", description = "이상하게 들리겠지만 내가 가장 많이 조사해 생물은 수액괴물이오. 온 천지에 깔려 있는 걸!\n\n얼마 전 메네실에서 잃어 버린 가방을 찾는 한 아가씨를 도와 주었소. 수액괴물이 먹어버렸더군. 언더시티의 왕립 연금술 학회에서도 수액괴물 견본을 모으는 걸 봤소. 그 이유가 뭘까? 그리고 도대체 수액괴물은 어디서 나오는 거야?\n\n악령의 숲에 더 있다고 들은 적이 있소. 연구를 더 진행하는데 쓸 수액괴물의 견본이 필요하오. 내가 주는 병에다 죽은 수액괴물의 견본을 모아주시오.", progress = "몇 가지 실험은 아주 흥미진진하오. 조금만 더 있으면 이 생물들의 본질과 아제로스의 생명체 출현과 어떤 관련이 있는가를 알아낼 것도 같소... 애초에 어떤 관련이 있다면 말이지.\n\n나의 가장 대표적인 학설 중 하나는 수액괴물들이 세계 창조와 관련이 있다는 건데, 그러니까 세계 창조의 분비물이 바로 수액괴물이라는 가설이오. 별로 환영받지 못하는 이야기지만.\n\n견본을 더 구해 이 학설이 진실인지 아닌지 확인하고 싶소.", completion = "놀라운 성과요, &lt;name&gt;! 그 오염된 괴물들에 가까이 가서 견본을 채취하고도 멀쩡하다니! 고맙소. 아, 이 견본이라면 딱 좋소. 어서 실험을 시작하고 싶어.\n\n만약 내 가설이 옳다면 나는 탐험가 연맹 사상 가장 위대한 과학자들의 반열에 오를 수 있소!\n\n그래서 놈리건 사태 이후, 아이언포지에 노움을 받아들인 것이 잘한 일이었다는 것을 모든 &lt;race&gt;에게 몸소 증명해 보일 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4513] = {title = "수액괴물 견본 수집", objective = "아이언포지에 있는 라리스 기어더들에게 가득찬 순수한 견본 병10개를 가져가야 합니다.\n\n찾기 어려우면 라리스에게서 단서를 더 얻어 보십시오.", description = "견본이 더 있어야 할 것 같소, <name>. 하지만 그게... 뭐라고 말을 해야 하나... 순수한 견본이어야만 하오. 아아, 알고 있소. \"순수하다는 게 무슨 뜻입니까?\" 하고 묻고 싶은 거겠지. 나도 잘 모르겠소. 다만 이것들이 오염된 것이라는 건 확실하오. 악령의 숲처럼 말이지. 그렇기 때문에 내가 깨달은 사실이 그만큼 중요한 거요. 수액괴물들은 자신들이 사는 장소에 적응해... 거기에 동화되어 버리는 것 같소. 오염되지 않은 견본을 찾아야 하는데 대체 어디서... 어디서 찾아야 하는 건지!\n\n이것 참! <name>, 혹시라도 찾게 될 때를 대비해서 이 병을 가지고 계시오.", progress = "생각해 봐야 할 게 너무나도 많소. 하지만 그게 무슨 뜻일까? 그리고 그게 아제로스 종족들의 삶에 어떻게 영향을 미친다는 거지?", completion = "찾았소? 당신은 보석 같은 존재요, &lt;name&gt;. 당신의 헌신과 도움이 얼마나 대단한지 뭐라고 감사의 말을 해야 할지 모르겠소.\n\n자, 수고에 대한 보상으로 이걸 받으시오. 지금은 내가 할 일이 좀 있지만 나중에 다시 날 찾아오면 틀림없이 또다시 당신의 도움이 필요하게 될 거요.\n\n고맙소. 정말 고맙소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n바람막이 장화놋쇠 건틀릿\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4521] = {title = "사나운 수호병", objective = "악령의 숲에 있는 트룰 페일베인이 흉포한 올빼미야수 15마리, 그리고 털복숭이 올빼미야수 15마리를 처치해달라고 부탁했습니다.", description = "이곳 악령의 숲에서 북동쪽, 나무구렁 요새 너머 여명의 설원이란 곳이 있지. 혹시 가본 적 있나?\n\n그 지역에는 올빼미야수라는 짐승이 득실대는데, 이 야수들은 비밀을 수호하고 있다고 하네. 바로 나이트 엘프들의 비밀 말일세.\n\n여명의 설원에 숨겨진 것이 무엇인지 알아내야 하네. 길에서 남쪽으로 가면 털복숭이 올빼미야수가 나오고, 여명의 설원의 중심 지역에는 흉포한 올빼미야수라는 녀석들이 설치고 있다고 들었네. 녀석들을 처치해 여명의 설원으로 가는 길을 열도록 하게.", progress = nil, completion = "이거 희소식이로군. 이 야수들을 몰아냈으니 이제 여명의 설원으로 더 깊숙이 들어갈 수 있겠어. 그런데 혹시 다른 임무를 맡을 수 있겠는가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4542] = {title = "높새바람 봉우리", objective = "긴급 전갈을 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 가져가야 합니다.", description = "최근 이 일대에서 켄타우로스의 침략이 늘어나고 있소. 높새바람 봉우리에 이 사실을 즉시 알려야 하오! 남동쪽에 있는 높새바람 봉우리로 가서 절벽파수꾼 롱혼을 찾아 이 긴급 전갈을 전해 주시오.\n\n가는 길에 근처에 보이는 그림토템부족은 피하도록 하시오... 요즘 들어 우리에게 이상한 행동을 보이고 있으니 말이오.", progress = "무슨 일인가? 긴급 전갈이라고? 나한테 말인가?", completion = "또 좋지 않은 소식이로군! 이 켄타우로스 녀석들이 도를 넘어섰군! 내 수송 마차 하나를 공격해 사람들을 모두 죽여버린 모양이네. 말도 안 돼... 꼭 응징하고야 말겠어!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4561] = {title = "불순물 실험 - 운고로 분화구", objective = "운고로 분화구에서 진흙괴물 견본을 채취해 그 일부를 탁자 위에 놓인 갖가지 튜브와 비커에 담습니다. 내용물이 부글부글 끓기 시작하면서 진흙괴물의 색이 변합니다. 실험이 끝나고 액체가 잦아들자 작은 페트리 접시에 순화된 운고로 진흙괴물 견본과 다른 찌꺼기가 남았습니다.", description = nil, progress = "운고로 분화구에서 진흙괴물 견본을 채취해 그 일부를 탁자 위에 놓인 갖가지 튜브와 비커에 담습니다. 내용물이 부글부글 끓기 시작하면서 진흙괴물의 색이 변합니다. 실험이 끝나고 액체가 잦아들자 작은 페트리 접시에 순화된 운고로 진흙괴물 견본과 다른 찌꺼기가 남았습니다.", completion = "진흙괴물 견본이 담긴 페트리 접시를 집어 듭니다. 이 견본이 충분히 순수한지 알아보는 방법은 견본을 열어 내용물을 직접 조사하는 것뿐입니다. 연금술사 퓰리가 원하는 견본이었으면 좋겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n검사를 마친 운고로 견본"},
[4581] = {title = "케이네스 스틸윈드", objective = "숲의 노래에 있는 케이네스 스틸윈드에게 신드렐의 쪽지를 가져가야 합니다.", description = "드루이드 케이네스 스틸윈드로부터 연락이 왔습니다. 이곳 아스트라나르 주변 숲 속과 해안가에서 일어나고 있는 일에 대해 보고를 받길 원하고 있습니다. 잿빛 골짜기에 어떤 타락이 퍼지고 있는 게 아닌가 걱정이 되는 모양입니다. 그의 생각이 옳을지도 모르죠.\n\n자, 제 보고서를 그에게 가져다주십시오. 그는 동쪽의 별빛노래 숲, 숲의 노래에 있는 제단에서 찾을 수 있을 겁니다.", progress = "내게 무엇을 가져온 거요?", completion = "아, 신드렐의 보고서로군! 대단히 고맙소이다, &lt;name&gt;. 신드렐은 용감하고 훌륭한, 빈틈없는 파수꾼이오. 여기 적혀진 내용을 통해 잿빛 골짜기에 퍼지고 있는 타락에 대한 단서를 알아내야겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4601] = {title = "삐까뻔쩍세척기 5200!", objective = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 넣으십시오. 3실버를 투입하면 작동할 것입니다.", description = "완강히 저항하고 있는 노움들 사이에서 이 장치가 눈에 띕니다. 장치에 붙은 작은 판에는 \"삐까뻔쩍세척기 5200\"이라는 이름과 함께 다음과 같은 글귀가 적혀 있습니다.\n\n\"귀중품에 찌꺼기가 끼었습니까? 삐까뻔쩍세척기 5200이 말끔히 닦아 드립니다! 세척할 물건을 장치에 넣고 투입구에 3실버를 넣으십시오. 잠시만 기다리시면, 짜잔! 당신의 귀중품이 깨끗한 모습으로 반짝이게 됩니다!\"", progress = "세척기가 작동하려면 꼬질꼬질한 물건과 3실버가 필요합니다. 두 가지를 모두 가지고 있어야 삐까뻔쩍세척기 5200이 작동합니다.", completion = "꼬질꼬질한 물건과 3실버를 삐까뻔쩍세척기 5200에 넣습니다. 장치가 요동치기 시작하면서 중심부에서 요란하고 시끄러운 소리가 들려옵니다. 물건에서 찌꺼기를 닦아내는 것 같습니다. 장치가 좌우로 흔들리면서 내부의 금속 구조물들이 서로 부딪히며 삐걱거리는 소리가 납니다.", rewards = nil},
[4602] = {title = "삐까뻔쩍세척기 5200!", objective = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 넣으십시오. 3실버를 투입하면 작동할 것입니다.", description = "완강히 저항하고 있는 노움들 사이에서 이 장치가 눈에 띕니다. 장치에 붙은 작은 판에는 \"삐까뻔쩍세척기 5200\"이라는 이름과 함께 다음과 같은 글귀가 적혀 있습니다.\n\n\"귀중품에 찌꺼기가 끼었습니까? 삐까뻔쩍세척기 5200이 말끔히 닦아 드립니다! 세척할 물건을 장치에 넣고 투입구에 3실버를 넣으십시오. 잠시만 기다리시면, 짜잔! 당신의 귀중품이 깨끗한 모습으로 반짝이게 됩니다!\"", progress = "세척기가 작동하려면 꼬질꼬질한 물건과 3실버가 필요합니다. 두 가지를 모두 가지고 있어야 삐까뻔쩍세척기 5200이 작동합니다.", completion = "꼬질꼬질한 물건과 3실버를 삐까뻔쩍세척기 5200에 넣습니다. 장치가 요동치기 시작하면서 중심부에서 요란하고 시끄러운 소리가 들려옵니다. 물건에서 찌꺼기를 닦아내는 것 같습니다. 장치가 좌우로 흔들리면서 내부의 금속 구조물들이 서로 부딪히며 삐걱거리는 소리가 납니다.", rewards = nil},
[4603] = {title = "삐까뻔쩍세척기 재사용", objective = "빈 삐까뻔쩍세척기 5200이 꼬질꼬질한 물건과 작동에 필요한 3실버를 기다리고 있습니다!", description = nil, progress = "빈 삐까뻔쩍세척기 5200이 꼬질꼬질한 물건과 작동에 필요한 3실버를 기다리고 있습니다!", completion = "삐까뻔쩍세척기 5200이 작동하며 앞뒤로 마구 흔들립니다. 안에서는 &lt;race&gt; 세척제가 물건에 찌든 찌꺼기를 말끔히 닦아 내고 있습니다!\n\n삐까뻔쩍세척기 5200이 갑자기 멈추더니 \"땡\" 하는 소리가 납니다. 입구가 열리면서 예쁘게 포장된 상자가 모습을 드러냅니다.", rewards = "다음과 같은 것들을 받습니다:\n\n삐까뻔쩍세척기 포장 상자"},
[4604] = {title = "삐까뻔쩍세척기 재사용", objective = "빈 삐까뻔쩍세척기 5200이 꼬질꼬질한 물건과 작동에 필요한 3실버를 기다리고 있습니다!", description = nil, progress = "빈 삐까뻔쩍세척기 5200이 꼬질꼬질한 물건과 작동에 필요한 3실버를 기다리고 있습니다!", completion = "삐까뻔쩍세척기 5200이 작동하며 앞뒤로 마구 흔들립니다. 안에서는 노움 세척제가 물건에 찌든 찌꺼기를 말끔히 닦아 내고 있습니다!\n\n삐까뻔쩍세척기 5200이 갑자기 멈추더니 \"땡\" 하는 소리가 납니다. 입구가 열리면서 예쁘게 포장된 상자가 모습을 드러냅니다.", rewards = "다음과 같은 것들을 받습니다:\n\n삐까뻔쩍세척기 포장 상자"},
[4605] = {title = "삐까뻔쩍세척기 5200!", objective = "삐까뻔쩍세척기 5200이 갑자기 멈추어 버립니다. \"땡\" 소리가 나더니 원통형 입구가 회전하면서 위로 올라와 열립니다. 그 안에는 조그만 리본 장식으로 포장된 작은 상자가 있습니다. 물건의 찌꺼기를 세척하고 난 후 포장까지 한 모양입니다. 찌꺼기가 제대로 없어졌는지는 모르지만 적어도 물건은 예쁘게 포장되어 있습니다.\n\n제대로 세척됐는지 알아보는 방법은 단 한 가지 뿐...", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n삐까뻔쩍세척기 포장 상자"},
[4606] = {title = "삐까뻔쩍세척기 5200!", objective = "삐까뻔쩍세척기 5200이 갑자기 멈추어 버립니다. \"땡\" 소리가 나더니 원통형 입구가 회전하면서 위로 올라와 열립니다. 그 안에는 조그만 리본 장식으로 포장된 작은 상자가 있습니다. 물건의 찌꺼기를 세척하고 난 후 포장까지 한 모양입니다. 찌꺼기가 제대로 없어졌는지는 모르지만 적어도 물건은 예쁘게 포장되어 있습니다.\n\n제대로 세척됐는지 알아보는 방법은 단 한 가지 뿐...", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n삐까뻔쩍세척기 포장 상자"},
[4621] = {title = "붉은해적단의 제독", objective = "무법항에 있는 함장 시혼과 남작 레빌가즈를 처치한 후, 가시덤불 골짜기의 해안에 정박해 있는 크림슨 베일호의 함장 피랠론에게 돌아가야 합니다.", description = "잘 듣게. 우리 붉은해적단은 무법항의 지도층 때문에 항해도 마음대로 못하고 약탈자의 권리도 자유롭게 누리지 못하고 있네. 함장 시혼을 처치하면 무법항의 배와 부닥칠 일이 없을 테고, 레빌가즈 남작을 처치하면 녀석들의 법을 따를 필요도 없겠지.\n\n우리 무리에 끼어 명예 제독 자리를 얻고 싶다면... 그래, 제독 말이야. 내가 말한 둘을 처치하게. 이제 가보라고. 일을 마치거든 곧장 되돌아오게.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n붉은해적단장 모자"},
[4641] = {title = "할 일 찾기", objective = "고르넥과 대화하십시오. 칼툰크가 지도를 가리키며 서쪽에 있는 동굴 막사에 있다고 한 것이 기억납니다.", description = "드디어 자네도 나이가 찼군... 이제 호드의 이름을 걸고 대족장님의 영광을 위한 전쟁에 나가 싸워도 되겠네.\n\n그래...\n\n<위아래로 훑어보는 칼툰크>\n\n자네라면 딱 되겠어.\n\n분명 당장 용이나 악마를 찾아 목을 졸라 없애 버리고 싶겠지만, 처음 시작할 때는 조금... 덜 위험한 것이 좋을 걸세.\n\n<웃는 칼툰크>\n\n고르넥에게 가보게. 젊은 <class>에게 적합한 임무를 줄 테니까. 고르넥은 서쪽에 있는 동굴 막사에서 찾을 수 있을 걸세.", progress = nil, completion = "칼툰크의 새로운 신병인가?\n\n흠, 위대한 호드의 신병 수준이 이 정도밖에 안 되다니 안타까운 일이군. 하지만 자네가 이곳을 떠날 때쯤이면 아마도 훌륭한 호드의 전사가 되어 있을 것으로 믿네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4642] = {title = "반응의 결합", objective = "언더시티에 있는 연금술사 퓰리에게 합쳐진 수액괴물 견본을 가져가야 합니다.", description = "여기 이 상자에 든 수액괴물은 당신이 가져온 악령의 숲 견본으로 만든 것이오. 이 상자를 들고 운고로 분화구로 가서 순수한 수액괴물을 찾으시오... 원시 수액괴물이 좋을 것이오. 수액괴물에게 가까워지면 상자 안에 든 수액괴물을 풀어놓고 둘이 어떤 반응을 보이는지 보시오.\n\n이곳 연금술 실험실에서 기다릴 테니 실험이 끝나면 남은 것을 내게 가지고 오시오.", progress = "실험은 어떻게 돼가고 있소? 나는 계속 당신이 가져온 견본을 조사하고 있겠소. 실바나스 여왕님께서 왜 이 생물들에 그렇게 관심을 가지시는지 알 것도 같소. 이것들이 정말로 고대 신의 일부라면 우리에게 어떤 득이 될지 누가 알겠소.", completion = "아. 정말 잘 됐군. 정말로 굉장하오.\n\n아주 재미있는 일이 벌어졌군그래. 이 둘이 그런 반응을 보일 줄이야... 이 생물들을 변화시키는 환경적 요인에 대해 좀 더 조사해봐야겠소.\n\n나는 당분간 연구를 계속할 것이오. 조만간 다시 얘기를 나눌 날이 오겠지. 그 때까지 몸조심하시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n약제사의 반지약제사의 작업복\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4661] = {title = "타락 실험 - 악령의 숲", objective = "악령의 숲에서 진흙괴물 견본을 채취해 그 일부를 탁자 위에 놓인 갖가지 튜브와 비커에 담습니다. 내용물이 부글부글 끓기 시작하면서 진흙괴물의 색이 변합니다. 실험이 끝나고 액체가 잦아들자 작은 페트리 접시에 변화된 악령의숲 진흙괴물 견본과 다른 찌꺼기가 남았습니다.", description = nil, progress = "악령의 숲에서 진흙괴물 견본을 채취해 그 일부를 탁자 위에 놓인 갖가지 튜브와 비커에 담습니다. 내용물이 부글부글 끓기 시작하면서 진흙괴물의 색이 변합니다. 실험이 끝나고 액체가 잦아들자 작은 페트리 접시에 변화된 악령의숲 진흙괴물 견본과 다른 찌꺼기가 남았습니다.", completion = "진흙괴물 견본이 담긴 페트리 접시를 집어 듭니다. 이 견본이 충분히 순수한지 알아보는 방법은 견본을 열어 내용물을 직접 조사하는 것뿐입니다. 연금술사 퓰리가 원하는 견본이었으면 좋겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n검사를 마친 오염된 견본"},
[4681] = {title = "해변으로 올라온 바다 생물", objective = "아우버다인 서쪽 바다에 있는 바다 거북 유해에서 바다 거북 잔해를 회수한 후, 아우버다인에 있는 그웨니스 블리레곤드에게 돌아와 대화하십시오.", description = "바다 생물들이 해변에 올라와 죽는 것은 이곳 어둠의 해안만의 문제가 아닙니다. 해안선을 따라, 그리고 심지어 물속에도 많아요. 한 마리를 더 조사해 주셨으면 합니다. 이번 생물은 아우버다인에서 정서 쪽, 침몰한 배 근처의 물속에 있다는 보고를 받았어요. 우리 조사에 도움이 될 만한 거라면 뭐든지 가져와 주세요.\n\n그리고 가는 길에 마주치는 다른 생물들에게서도 뭐든 발견하게 되면 꼭 가져와 주십시오.", progress = "여기서 서쪽에 있는, 물속 생물의 유해를 조사해 주시면 다르나서스에 있는 달의 신전에 제대로 된 보고서를 보낼 수 있을 겁니다. 그러면 이 불쌍한 생물들이 어째서 어둠의 해안 해변까지 올라와 자신들의 삶을 끝내는지에 대해 좀 더 많은 걸 알 수 있겠지요.", completion = "너무나도 큰 도움을 주셨습니다. 이제는 이 생물들이 왜 어둠의 해안 해변으로 올라오는지 알아낼 수 있을 거예요. 그 생물들이 텔드랏실 부근에서 도망치고 있을지도 모른다는 생각을 하니 기분이 좋지 않군요. 다니는 길에 다른 생물들을 보게 되면 제게 알려 주세요. 이곳에서의 연구는 이제 초기 단계일 뿐입니다.\n\n수고에 대한 감사의 표시를 하고 싶습니다. 달의 신전을 대신해 드리는 것이니 부디 이것을 받아 주세요. 감사합니다, &lt;name&gt;!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n모래파도 장화마른줄기 허리띠조개껍질 팔보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4701] = {title = "검은늑대 위협의 근원 파괴", objective = "검은바위 첨탑으로 가서 검은늑대 위협의 근원을 파괴해야 합니다. 헬렌디스를 떠날 때 헬렌디스가 오크들이 특정한 검은늑대를 부르는 말인 할리콘이라는 이름을 외치는 것을 들었습니다.", description = "당신도 검은바위부족 오크들이 다스리는 검은늑대들을 보았을 거요.\n\n참 신기한 게, 아무리 많이 없애도 녀석들의 수가 결코 줄어들지 않는다는 거요. 정찰병들의 보고에 의하면 이 검은늑대들은 검은바위부족 오크들의 수도인 검은바위 첨탑에서 길러지고 훈련되어 결국 외부로 퍼뜨려진다고 하오. 당신이 검은바위 첨탑으로 가서 이 위협의 근원을 파악해야 하오. 그런 다음... 그 근원인 할리콘을 없애 주시오.\n\n행운을 빌겠소. 세나리우스의 가호를...", progress = nil, completion = "그 늑대는 흑마법의 산물로, 타락한 존재였으니 그 짐승의 고통은 신경쓰지 마시오. 당신은 얼라이언스를 위해 큰 일을 해 주었고 그에 따른 보상을 받게 될 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아스토리아 로브올가미 웃옷비취비늘 흉갑\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4721] = {title = "사나운 수호병", objective = "악령의 숲에 사는 트룰 페일베인이 여명의 설원에서 광포한 올빼미야수 10마리를 처치해 달라고 요청했습니다.", description = "여명의 설원에서 돌아온 정찰꾼들로부터 남부 지역에 작은 동굴들이 몰려 있다는 보고를 받았네. 그 동굴 근방에 올빼미야수들이 있는 모양일세. 올빼미야수들이 뭔가 귀중한 걸 수호하고 있다면 바로 그곳에 숨겨둔 게 아닐까 생각하네.\n\n이전에 싸운 올빼미야수들보다는 훨씬 더 상대하기가 어려울 걸세, <name>. 자신들이 수호하려던 것이 누군가에게 노출됐다는 위기감에 미쳐버린 것 같아.", progress = nil, completion = "나는 열심히 일하는 사람을 아주 높이 평가한다네, &lt;name&gt;. 이제 자네 덕에 여명의 설원에 대한 우리 계획을 실행할 수 있게 됐어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4722] = {title = "떠내려온 바다 생물", objective = "아우버다인에 있는 그웨니스 블리레곤드에게 바다 거북 잔해를 가져가야 합니다.", description = "어둠의 해안에서 얼마 전에 해변에 올라와 죽은 듯한 바다 거북의 시체를 찾았습니다. 생물의 유해 근처에 진을 친 멀록들이 시체를 파먹어 버렸지만 아우버다인에 있는 그웨니스 블리레곤드가 조사에 사용할 수 있을 정도는 남아 있는 것 같습니다.", progress = "안녕하세요, <name>. 해변으로 올라온 생물들에 대해서 또 보고할 것이 있나요?", completion = "우리가 연구할 내용을 또 발견하셨군요. 수고하셨어요! 이 유해는 다르나서스로 보내져 철저한 조사를 받게 될 겁니다. 많지는 않지만, 조사에 쓸 유해를 구해 오신데 대한 사례금을 받아 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4723] = {title = "떠내려온 바다 생물", objective = "아우버다인에 있는 그웨니스 블리레곤드에게 바다 생물 뼈를 가져가야 합니다.", description = "어둠의 해안에서 볼 수 있는 것보다 훨씬 더 거대한 트레샤돈의 유해가 안개 해안의 해변에 올라와 있습니다. 이 생물이 어떻게 해서 이곳에 오게 됐는지는 알 수 없습니다. 그 시체를 뜯어 먹고 있는 멀록들이 아무리 많다고 하더라도 이 거대한 생물을 잡기에는 너무 약한 존재들입니다.\n\n이 생물의 잔해는 멀록들에게 깨끗이 먹힌 편이지만 아직 아우버다인의 그웨니스 블리레곤드가 조사할 견본용으로는 충분한 만큼의 잔해가 남아 있습니다.", progress = "아마 언젠가는 불쌍한 생물들이 어둠의 해안 해변에서 부질없이 죽어 가는 것을 막을 방법을 찾게 되겠지... 그때까지는 계속 조사를 해야만 해!\n\n안녕하세요, <name>. 어떤 소식을 가져오셨나요?", completion = "또 발견하셨군요. 수고하셨어요! 이 유해는 다르나서스에 보내 정확한 조사를 할 겁니다. 많지는 않지만, 조사에 도움을 주신 것에 대한 사례금을 받아 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4724] = {title = "검은늑대 무리의 어미", objective = "도끼부대 검은늑대 무리의 어미, 할리콘을 처치해야 합니다.", description = "어떤 이들은 검은바위부족 오크가 부리는 검은늑대들이 초자연적인 세력의 피조물이라고 하고, 또 다른 어떤 이들은 그 검은늑대들이 진짜 검은늑대가 아니라 타락한 지옥의 군주가 검은바위부족 오크들에게 하사한 지옥개의 한 부류라고 하오.\n\n실제로는 그렇지 않지만 그만큼이나 무서운 일이 벌어지고 있는 게 사실이오. 검은바위부족의 검은늑대들은 할리콘과 그 짝 사이에서 나온 녀석들이오. 할리콘은 이 검은늑대들의 거대한 어미인데, 그 짝인 수컷에 대해서는 아직까지 살아 돌아온 자가 없어 아무도 모르고 있소.\n\n검은늑대 무리의 핵심이라고 할 수 있는 할리콘을 물리치시오... 그리고 등 뒤를 조심하시오.", progress = nil, completion = "맹렬한 기세의 검은늑대들과 흉포한 기즈룰에 맞서 싸웠다고? 그런데도 살아 돌아왔단 말이오? 정말 놀랍군! 당신은 보상을 받을 만한 자격이 충분하오!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아스토리아 로브올가미 웃옷비취비늘 흉갑\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4725] = {title = "떠내려온 바다 생물", objective = "아우버다인에 있는 그웨니스 블리레곤드에게 이상한 표식이 된 상자를 가져가야 합니다.", description = "해안선을 따라 다른 바다 거북의 잔해가 널려 있습니다. 이 유해의 거북이 등껍질에는 버려진 듯한 운반용 기구가 부착되어 있습니다. 어쩌면 이 생물들은 스스로 해변으로 올라온 것이 아니라 알 수 없는 어떤 존재에 의해 해안가로 쫓겨난 것 같습니다. 지금은 잿빛안개멀록들이 이 생물의 잔해를 집으로 삼고 그 썩은 고기를 뜯어 먹고 있습니다.\n\n운반용 기구에는 이상한 표시가 있는 상자 하나가 있습니다. 어쩌면 아우버다인에 있는 그웨니스 블리레곤드가 이것이 어떤 물건인지 알지도 모릅니다.", progress = "다시 만나 반갑군요, <name>. 거대한 바다 생물들이 왜 어둠의 해안으로 올라와 죽는지 조사하는 일은 큰 진척을 보이고는 있지만, 한 가지 질문의 답을 구하면 두 가지 질문이 더 생기는 것 같아요.\n\n우리 조사를 더 도와 주기 위해 오신 건가요?", completion = "그대가 발견한 거북이 등에 붙어 있던 운반용 기구에 대해 들은 적이 있어요. 나가의 운반용 기구인 것 같은데, 전투에 쓰이기도 하고 보급품을 육지로 보내기 위해 쓰기도 한답니다. 상자에 있는 표시는 나가들의 것이에요. 이것으로 어둠의 해안 최북부에서 나가들이 출몰한다는 게 밝혀지게 되었군요.\n\n그대가 발견한 다른 것들과 함께 이 상자를 다르나서스로 보내겠습니다. 이것을 받으세요. 도와 주신 것에 대해 다시 한번 감사 드립니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4726] = {title = "새끼용의 정수", objective = "불타는 평원의 화염 마루에 있는 팅키 스팀보일에게 새끼용의 정수 8개와 새끼용 속박장치 900을 가져가야 합니다.", description = "난 몇 주째 불타는 평원의 용혈족을 연구해 왔는데 드디어 뭔가 돌파구가 생긴 것 같아요! 내가 새끼용 속박장치 900이라고 부르는 장치를 하나 만들었는데, 이 장치로 새끼용의 정수를 뽑아낼 수 있거든요! 아니 저... 적어도 그럴 수 있을 거라고 생각해요.\n\n자, 이 장치를 가지고 불타는 평원에서 새끼용을 공격해 보세요. 이 장치의 영향을 받고 있는 새끼용을 처치하면 새끼용의 정수가 풀려날 거예요.\n\n정수가 풀려난다면 아주 멋지게 잘 된 거죠! 나에게 연구할 견본을 좀 가져다주세요!", progress = "새끼용의 정수를 가져왔나요? 당장 연구해 보고 싶어서 못 기다리겠어요.\n\n게다가... 내 고용주는 실망시켜서는 안 될 분이거든요.", completion = "장치가 효과가 있었군요! 당신이 정수를 가져왔어요! 아주 잘했어요! 멋져요!\n\n이 정수는 내 연구에 아주 귀중한 거랍니다. 언젠가 살아 있는 새끼용이나 녀석들의 알을 포획하는 법을 알아내고 싶어요. 그렇게 할 수 있는 방법을 알아내면 전 세계의 용 전문학자들의 부러움을 사게 되겠죠!\n\n내 고용주도 기뻐하시겠군요. 그리고 전에도 말했듯이 내 고용주는 항상 기쁘게 해 드리지 않으면 안 될 분이랍니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4727] = {title = "떠내려온 바다 생물", objective = "아우버다인에 있는 그웨니스 블리레곤드에게 바다 거북 잔해를 가져가야 합니다.", description = "어둠의 해안 북부 모래 해변에 바다 거북 잔해가 널려 있습니다. 아직 잿빛안개멀록들의 눈에 띄지 않은 모양이에요. 아니면 알 수 없는 이유로 멀록들마저 접근하지 않는 것일지도... 어쨌든 견본으로 가져갈 만큼은 충분히 남아 있습니다. 아우버다인에서 달의 신전을 위한 연구를 하고 있는 그웨니스 블리레곤드에게 가져가면 좋을 것 같습니다.", progress = "<name>, 또 뵙게 돼서 반갑습니다. 떠내려온 생물들은 더 찾으셨나요? 반드시 달의 신전에 알려야 합니다.", completion = "그곳에 멀록이 없었다고요?! 정말 흥미롭군요. 이 유해를 조사할 때 꼭 염두에 두어야겠어요! &lt;name&gt;, 수고해 주셔서 감사합니다. 이건 이 임무를 위해 애써 주신 수고에 대하여 달의 신전에서 내리는 보상입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4728] = {title = "떠내려온 바다 생물", objective = "아우버다인에 있는 그웨니스 블리레곤드에게 바다 생물 뼈를 가져가야 합니다.", description = "거대한 바다 포유류인 듯한 생물의 시체가 해변에 있는데, 내장이 일부 파헤쳐져 있습니다. 시체 주변에는 누군가가 조사를 다녀가기라도 한 듯, 손수레와 여러 가지 연장들이 버려져 있습니다. 이미 멀록들이 유해를 파헤쳐 먹었지만 아우버다인의 그웨니스 블리레곤드에게 가져가기에 충분한 견본이 남아 있습니다.", progress = "어서 오세요, <name>! 아우버다인에는 또 무슨 일로 오셨나요? 혹시 무언가 발견해서 제게 보고하러 오신 건가요?", completion = "아, 원래 탐험가 연맹에서 조사 중이던 걸 발견하신 모양이군요. 어둠의 해안에도 탐험가 연맹이 있는데, 그들 말로는 떠내려온 바다 생물 중 하나를 조사하다가 멀록에게 쫓겨났다고 하더군요. 우리가 모두 실패했는데 그대는 성공하셨네요. 자, 달의 신전에서 드리는 이 사례금을 받아 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4729] = {title = "키블러의 진귀한 애완동물", objective = "검은바위 첨탑으로 가서 새끼 도끼부대 검은늑대를 찾아야 합니다. 우리를 사용하여 이 사나운 야수들을 운반하여 키블러에게 사로잡은 새끼 검은늑대를 가져가야 합니다.", description = "당신은 내가 지금 여기서 뭘 하고 있는 건지 궁금하겠죠. 이 우리들을 보세요! 뻔하지 않나요?\n\n나는 누구보다도 동물을 사랑하는 고블린이기도 하지만, 애완동물을 판매하는 상인이랍니다. 난 부유하고 유명한 이들을 위해 진귀한 동물들을 잡고 들판의 야수들을 길들여 예의 바른 야수로 만들죠.\n\n당신은 지금 아마 \"내가 도와줄 일이 있나요?\" 라고 묻고 싶을 거예요. 답은 간단해요. 이 늑대 우리를 가져가서 새끼 검은늑대들을 좀 잡아 오세요. 그렇게 하면 당신을 위해 검은늑대 한 마리를 길들여 드리도록 하죠.", progress = "<큰부리앵무새 스탄과 말싸움하느라 바쁜 오푸스>", completion = "아주 때 맞춰 잘 잡아 왔군요. 조금만 더 늦었어도 훈련을 시킬 수 없었을 거예요! 잠시만 시간을 주면 이 쬐끄만 녀석을 길들여서 당신이 데려갈 수 있도록 해 드리죠.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n검은늑대 우리"},
[4730] = {title = "떠내려온 바다 생물", objective = "아우버다인에 있는 그웨니스 블리레곤드에게 바다 생물 뼈를 가져가야 합니다.", description = "거대한 바다 포유류인 듯한 생물의 시체가 반쯤 먹힌 채로 해변에 널려 있습니다. 아우버다인 근처에 사는 것들보다 훨씬 더 강한 멀록 무리가 이 죽은 생물 근처에 터를 잡고 살고 있습니다. 하지만 아우버다인에 있는 그웨니스 블리레곤드에게 가져갈만한 양은 남아 있습니다.", progress = "안녕하세요, <name>! 또 다른 발견 내용에 대해 보고하러 오셨나요?", completion = "그대가 가져오신 뼈는 텔드랏실의 기층을 둘러싼 바다에 서식하는 것으로 알려진 온순한 바다 포유류의 것입니다. 이 생물들은 지금까지 과격한 트레샤돈처럼 해변으로 올라와 죽는 일이 전혀 없었는데, 어째서 이런 짓을 한 걸까요? 이 유해를 조사해 보면 우리가 원하는 답을 찾을 수 있을지도 모르겠네요.\n\n다시 한번 도와 주셔서 감사 드립니다. 달의 신전에서 드리는 이 사례금을 받아 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4731] = {title = "떠내려온 바다 거북", objective = "아우버다인에 있는 그웨니스 블리레곤드에게 이상한 표식이 된 상자를 가져가야 합니다.", description = "또 다른 바다 거북 유해가 해변에 널려 있습니다. 이 유해의 거북이 등껍질에는 버려진 운반용 기구가 허술하게 묶여 있습니다. 다른 유해들을 보고 추정했던 것과는 달리, 어쩌면 이 생물은 스스로 해변으로 올라온 것이 아니라 알 수 없는 존재에 의해 해안가로 쫓겨난 것 같습니다. 힘센 잿빛안개멀록들이 이 생물의 유해를 거처로 삼고 있습니다.\n\n운반용 기구에는 이상한 표시가 있는 상자 하나가 있습니다. 어쩌면 아우버다인에 있는 그웨니스 블리레곤드가 이것이 어떤 물건인지 알지도 모릅니다.", progress = "또 뵙는군요, <name>. 그대가 달의 신전을 대신해 용감하게 조사해주신 모든 일들이 아주 큰 도움이 되었습니다. 또 다른 내용을 가지고 오신 건가요?", completion = "그 거북이 등에 붙어 있던 운반용 기구에 대해 들은 적이 있어요. 나가의 운반용 기구인 것 같은데, 전투에 쓰이기도 하고 보급품을 육지로 보내기 위해 쓰기도 한답니다. 상자에 있는 표시는 나가의 것이에요. 아마 그대가 찾은 생물은 거기서 남쪽을 향해 가던 중, 죽임을 당한 것 같군요... 잿빛 골짜기로 가고 있던 걸까요?\n\n이 상자를 그대가 발견한 다른 것들과 함께 꼭 다르나서스로 보내겠습니다. 이것을 받으세요. 도와 주신 것에 대해 다시 한번 감사 드립니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4732] = {title = "떠내려온 바다 거북", objective = "아우버다인에 있는 그웨니스 블리레곤드에게 바다 거북 잔해를 가져가야 합니다.", description = "어둠의 해안에서 얼마 전에 해변에 올라와 죽은 듯한 바다 거북의 시체를 찾았습니다. 시체 근처에 진을 친 잿빛안개멀록들이 거의 다 파먹어 버렸지만 아우버다인에 있는 그웨니스 블리레곤드가 조사용으로 쓸 수 있을 만한 견본이 조금 남아 있는 것 같습니다.", progress = "또 오셨군요, <name>. 달의 신전에 추가로 보고할 내용을 발견하신 건가요?", completion = "떠내려온 바다 생물을 더 찾으셨다고요? 바다 거북은 죽기 전에 놀드랏실 근처에서 장난치며 노는 일이 흔했는데, 텔드랏실이 생긴 후부터는 그 수가 점점 줄어들고 있습니다. 그리고 그대의 발견처럼 바다 거북들이 알 수 없는 이유로 자살하는 사례도 생기고 있죠.\n\n그대의 도움으로 우리 앞에 놓인 이 수수께끼를 풀 수 있을지도 모르겠군요. 연구에 필요한 유해를 제공해 주신 데 대한 보답으로 이걸 받으세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4733] = {title = "떠내려온 바다 생물", objective = "아우버다인에 있는 그웨니스 블리레곤드에게 바다 생물 뼈를 가져가야 합니다.", description = "거대한 트레샤돈의 것인 듯한 유해가 황혼의 해안의 바위투성이 후미에 밀려와 있습니다. 이 트레샤돈은 이 부근의 다른 트레샤돈보다 몇 배는 더 큽니다. 이 생물이 어디서 왔든지, 어둠의 해안에서 태어난 것은 아닌 것 같습니다.\n\n시체가 군데군데 파먹혔지만 아우버다인에 있는 그웨니스 블리레곤드에게 가져갈 만한 견본은 조금 남아 있습니다.", progress = "엘룬께 감사를... 다시 보게 돼서 반가워요, <name>. 달의 신전은 계속해서 이곳 어둠의 해안에서 일어나고 있는 이 이상한 현상에 대해 조사를 하고 있답니다. 저희에게 더 주실 것이 있는지?", completion = "그대가 말하는 트레샤돈의 크기는 정말이지 굉장하군요. 이 지역에서 가장 오래된 트레샤돈도 그 크기의 절반에 미치지 못합니다. 텔드랏실 가까이로 가면 좀 큰 것들을 볼 수 있다고 알려져 있지만, 그 수가 계속 줄어들어 왔답니다. 이 사실과 해변으로 올라와 죽는 생물들이 어떻게든 관련이 있다는 생각을 지울 수가 없군요.\n\n그대가 가져오신 뼈를 분석하겠습니다. 달의 신전을 대신해서 드리는 이 사례금을 받아 주세요. 감사합니다, &lt;name&gt;.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4734] = {title = "알껍질 냉동", objective = "알껍질급속냉각기 견본을 둥지에 있는 알에 사용해야 합니다.", description = "난 여태 알껍질급속냉각기라는 새로운 기계를 만들고 있었어요! 냉기를 발사해 검은용의 알을 얼리기 위해서 만든 녀석이죠. 한 번 시험해 볼래요?\n\n검은바위 첨탑 꼭대기에 검은용들이 알을 낳는 둥지가 있다고 들었어요. 거기 가서 알껍질급속냉각기를 시험해 보고 내게 결과를 보고해 주세요!\n\n아, 걱정 마요. 냉동된 용의 알은 위험할 리가 없으니까 말이에요. 얼어 있지 않은 녀석들이나 걱정하세요!", progress = "알껍질급속냉각기를 시험해 봤나요?", completion = "성공했어요? 좋았어!! 작동할 줄 알았다고!\n\n당신이 가 있는 동안 난 알껍질급속냉각기의 새로운 버전을 만들고 있었어요. 이 녀석은 사정거리가 훨씬 길답니다.\n\n자, 검은바위 첨탑에 다시 갈 때를 대비해서 하나 가지고 가도 좋아요.", rewards = "다음과 같은 것들을 받습니다:\n\n알껍질급속냉각기"},
[4735] = {title = "알 수집", objective = "불타는 평원의 화염 마루에 있는 팅키 스팀보일에게 수집한 용의 알 8개를 가져가야 합니다.", description = "드디어 용의 알을 수집할 준비가 됐어요! 자, 이 수집전자 모듈을 가지고 가세요. 이것은 용의 알을 추출하고 전송하기 위해 고안되었답니다. 일단 부화장에 돌아가서 이 모듈로 알을 수집하세요.\n\n아, 수집하기 전에 알을 얼리는 것도 잊지 마시고요. 가져가기 전에 알이 부화해버리면 낭패잖아요!\n\n충분히 알을 채집하면 내게 가져오세요!", progress = "알을 가져왔나요? 내 의뢰인이 당신이 날 위해 알을 채집하고 있다는 것을 들은 모양이네요. 그분은 하루라도 빨리 그 알을 손에 넣고 싶어하는 눈치였어요!", completion = "와우, 가지고 왔군요! 수집전자 모듈이 작동했군! 나는 천재야!\n\n고마워요. 내 의뢰인께서 이 알을 보시게 되면 매우 기뻐할 거예요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4736] = {title = "미네라 보이드렌더를 찾아서", objective = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", description = "아, 안녕하시오, <name>. 당신의 훈련은 아주 잘 진행되고 있소이다. 사실 아주 잘 하고 있어서 그 노고에 대해 포상이라도 내려야 할 것 같군. 그리고 아직 비전 마법에 의해 타락되지 않았다는 사실도 매우 훌륭하오.\n\n혹시 관심이 있거든 톱니항에 있는 미네라 보이드렌더를 찾아가 보시오. 지금 마을이 내려다보이는 스트라드 파선의 탑에 머무르고 있소.\n\n그리 상냥한 성격은 못 되는 분이니 칭찬 같은 건 바라지 마시오. 하지만 열심히 하는 자세만 보인다면 당신을 잘 챙겨 주리라 장담하지.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4737] = {title = "미네라 보이드렌더를 찾아서", objective = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", description = "흥, 아직도 더 강해지려고 기를 쓰는군. 내가 보기에는 당신이 정복하려고 하는 타락에 오히려 중독되어 노예가 되고 마는 건 시간문제일 거요.\n\n쳇! 바보 같으니! 시간이 지나야만 내 말이 옳다는 걸 알게 되겠지... 시간이 지나야...\n\n하지만 이 제브로스트의 말에 다들 찬성하는 건 아닌 것 같소. 미네라에 가면 당신이 더욱 강하게 해줄 도구를 만들어줄 거요. 관심이 있다면 불모의 땅에 있는 톱니항으로 가 보시오. 미네라는 마을이 내려다보이는 높은 곳에 있을 거요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4738] = {title = "미네라 보이드렌더를 찾아서", objective = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", description = "한 가지 확실히 해 두고 싶소, <name>. 나는 당신이 이런 중대한 책임을 질 준비가 되었다고 생각하지 않는다오. 강력한 힘을 가진 물건은 아직 수련 중인 이의 소관이 돼서는 안 된다고 보지. 더군다나 어려움을 전혀 겪어 보지 않은 이라면...\n\n하지만 그건 내가 결정할 일이 아니오. 강력한 힘을 지닌 자가 당신에게 그런 선물을 주고자 하니까 말이오.\n\n더 자세히 알고 싶으면 톱니항으로 가서 미네라 보이드렌더를 만나시오. 보통 항구 마을이 내려다보이는 탑에 머무니까 그쪽을 찾아 보시오.", progress = nil, completion = "아, 드미제트가 보냈군요. 좋아요. 그건 멀리까지 나에 대한 소문이 났다는 뜻이니 앞으로 배움을 구하는 자들이 이곳에 몰리겠군요. 참 기쁜 일이 아닐 수 없네요.\n\n우리 같은 이들에게는 종족을 막론하고 한데 뭉치는 게 아주 흔한 일이죠. 우리의 적은 사악하기 이를 데 없고 허술히 상대할 자가 아니라서, 한데 뭉치는 게 특히 중요하거든요.\n\n당신은 지금까지 아주 많은 것을 배운 것 같군요. 혹시 생각이 있다면 당신의 기술을 한층 더 높여 줄 도구를 만들어 보는 게 어때요? 제가 도와 드리겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4739] = {title = "미네라 보이드렌더를 찾아서", objective = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", description = "<class> 양반! 그래, 당신!\n\n제대로 된 장비는 갖추지 못했지만 준비된 마음의 자세가 내 눈에는 분명히 보이는군. 강한 자신감이 뿜어져 나오고 있으니 말이네. 그래, 지금 같은 그런 눈빛 말이네.\n\n스스로 준비가 되었다고 생각한다면 미네라 보이드렌더를 찾아가게. 몇 가지 가르쳐 주고 싶어할 게야. 그녀는 젊은 제자들에게 비전 마법을 가르치며 지내는데, 자신이 마련한 시험을 통과하는 이들에게는 선물도 준다는군.\n\n관심이 있거든 불모의 땅에 있는 톱니항으로 가보게. 미네라는 마을이 내려다보이는 스트라드의 탑에 있네.", progress = nil, completion = "아, 카알이 보냈군요. 좋아요. 그건 나에 대한 소문이 아주 먼 곳까지 퍼졌다는 뜻이니 앞으로 배움을 구하는 자들이 이곳에 몰려들겠군요. 참으로 기쁜 일이 아닐 수 없네요.\n\n우리 같은 이에게는 종족을 막론하고 한데 뭉치는 게 아주 흔한 일이죠. 우리의 적은 사악하기 이를 데 없고 만만히 상대할 자가 아니라서, 힘을 한데 뭉치는 게 특히 중요하거든요.\n\n당신은 지금까지 아주 많은 것들을 배운 것 같군요. 혹시 생각이 있다면 당신의 기술을 한층 높여 줄 도구를 만들어 보는 게 어때요? 제가 도와 드리겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4740] = {title = "현상수배: 먹구렁", objective = "먹구렁이라는 멀록을 찾아서 처치해야 합니다. 이 괴물은 아우버다인 남쪽, 해안에서 멀록 오두막을 보호하고 있는 것으로 추정됩니다.\n\n먹구렁을 처치하면 아우버다인에 있는 파수꾼 글린다 날셰에게 보고하십시오.", description = "주목!\n\n'먹구렁'이라고 하는 멀록을 처치하는 이에게는 보상을 내린다. 이 사악한 괴물은 최소한 한 명의 파수꾼을 살해한 용의자로 지목되었으며, 어둠의 해안 부근에서 두 척의 화물선을 가라앉게 한 장본인으로 추정된다!\n\n먹구렁은 아우버다인 남쪽에 있는 멀록의 오두막 야영지에서 마지막으로 목격되었으며 그 오두막들을 보호하고 있는 것으로 보인다. 먹구렁을 잡은 용맹스런 자는 아우버다인에 있는 파수꾼 글린다 날셰에게서 현상금을 수령하기 바란다.\n\n아우버다인 마을 의회", progress = nil, completion = "아, 단순히 문의를 하러 오신 게 아니었군요! 마을 주민들이 아주 기뻐할 겁니다. 오늘 밤부터는 편안히 단잠을 잘 수 있으니 말입니다.\n\n그대는 아우버다인 주민을 위한 정의의 수호자로서 활약하셨습니다, &lt;name&gt;. 그에 합당한 보상으로 이것을 드리지요... 아우버다인의 주민들이 진정한 영웅에게 드리는 보상입니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n초원의 손목보호대마루벼랑 팔보호구갈래바다 벨트\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4741] = {title = "사나운 수호병", objective = "악령의 숲에 사는 트룰 페일베인이 달빛 깃든 올빼미야수 13마리를 처치해 달라고 요청했습니다.", description = "더욱 사나운 올빼미야수들이 여명의 설원 북부 지방에 출몰하여 호드를 성가시게 하고 있다네. 이 녀석들도 처치해야 해.\n\n여명의 설원에서 달빛 깃든 올빼미 야수들을 처치하고 녀석들이 서식하는 장소를 탐험하게.\n\n위험한 곳이긴 하지만 당신이라면 썩 잘해낼 수 있을 거라 믿네. 올빼미야수 13마리를 처치한 후 다시 날 찾아오도록 하게.", progress = nil, completion = "일을 즐기는 것 같군. 그런데 우리가 뭔가 짚은 것 같아.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4742] = {title = "승천의 인장", objective = "사령관의 세 가지 보석인 가시불꽃부족 보석, 뾰족바위일족 보석, 도끼부대 보석을 찾아, 가공하지 않은 승천의 인장과 함께 밸란에게 가져가야 합니다.\n\n밸란이 말한 장군들은 가시불꽃부족의 대장군 부네, 뾰족바위일족의 대군주 오모크와 도끼부대의 대군주 웜타라크입니다.", description = "보다시피 이 승천의 인장에는 세 개의 홈이 있다. 각 홈에는 지도부의 사령관을 상징하는 보석을 채워 넣어야 하고, 마지막으로 하부 요새의 지배자, 대군주 웜타라크가 검은용군단의 화염으로 인장을 단조해야 한다.\n\n잘 들어라, 나약한 <race>|1이여;여;. 하부 요새의 이 세 장군이 보석을 몸에 지니고 다니는 일은 드물다. 포기하지 말고 계속 잘 찾아보아야 한다. 처음의 결의를 잃지 말도록 하라!", progress = "다른 무엇보다도 용기와 인내가 필요하도다!", completion = "&lt;잠시 흐릿해지는 밸란의 형상&gt;\n\n&lt;지금까지 모았던 조각들이 사라졌습니다.&gt;\n\n벼려지지 않은 승천의 인장이 준비되었다. 이제 마지막 단계를 행할 시간이도다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4743] = {title = "승천의 인장", objective = "먼지진흙 습지대에 있는 용의 둥지로 가서 고대 비룡, 엠버스트라이프를 찾아 그의 의지가 꺾일 때까지 무자비하게 공격을 펼쳐야 합니다.\n\n바로 그때 거대한 엠버스트라이프 앞에 벼려지지 않은 승천의 인장을 가져다 놓으십시오. 그리고 약해진 엠버스트라이프에게 재빨리 용력의 보주를 사용해 그의 정신력을 조종해야 합니다. 엠버스트라이프를 조종해 검은용군단의 화염을 벼려지지 않은 승천의 인장에 뿜어야 합니다!", description = "하부 요새에 있는 검은용혈족을 제외하고 자신들의 화염 숨결로 이 인장을 벼릴 수 있는 능력이 있는 검은용혈족은 드물다. 웜타라크가 바로 그런 용혈족 중 하나인데, 그의 의지는 누구도 꺾을 수 없을 정도다.\n\n먼지진흙 습지대에 있는 용의 둥지로 가라. 그곳에서 엠버스트라이프라는 고대 비룡을 찾을 수 있을 것이다. 그대는 반드시 그의 의지를 꺾어야만 한다. 그의 의지를 꺾고 그가 약해져 있을 때 이 수정구를 사용하라. 단 몇 초밖에 되지 않는 짧은 시간 동안 그의 의식을 조종함으로써 그의 화염을 일으켜 인장을 벼릴 수 있을 것이다.", progress = "시간을 낭비하지 말라. 네파리안이 우리 세계에 악을 풀어놓기 위해 분주히 노력하고 있다.", completion = "내가 최후의 보호 기원을 행하는 동안 잠시 기다리도록 하라.\n\n&lt;두 개의 화염 수정구로 변하는 밸란의 눈&gt;\n\n승천의 인장이 완성되었다...\n\n내가 이 유물에 강력한 보호 효과를 불어넣어 두었다는 것을 기억하도록 하라. 가장 암울한 시간에, 모든 것이 절망적일 때 붉은용군단의 힘을 사용할 수 있을 것이다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n승천의 인장"},
[4761] = {title = "툰드리스 윈드위버", objective = "아우버다인에 있는 툰드리스 윈드위버와 대화하십시오.", description = "그대가 가져온 펄볼그 야영지 정찰 정보는 툰드리스 윈드위버가 반드시 알아야 할 사항이오. 그는 아우버다인의 장로로서 마을의 일상적인 일에 대해 높은 식견을 제공하고 공정하게 일을 처리하시는 훌륭한 분이지. 부디 서둘러 펄볼그 상황에 대한 보고를 해주시오.\n\n펄볼그가 타락한 배후의 원인이 무엇인지에 대해 그 나름의 견해가 있을 거요. 어쩌면 그대가 툰드리스와 함께 이곳 자연의 균형을 되찾기 위한 계획을 세울 수 있을지도!", progress = nil, completion = "어서 오시오. 때를 아주 잘 맞춰 이곳 아우버다인에 있는 우리에게 펄볼그 상황에 대한 정찰 정보를 가져와 주시는군. 이제 숲의 생물이 우리에게 노골적인 적의를 보이는 것뿐만 아니라, 숲 자체가 완전히 타락해 가는 것을 보고 한동안 우리 나름대로 대처해 왔소. 그대가 이 험난한 시기에 아우버다인에 도움을 줄 수 있으면 좋겠소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4762] = {title = "폭포수 강", objective = "아우버다인 북쪽으로 가서 폭포수 강 가장자리에 있는 첫 번째 폭포에서 물 견본을 채취해야 합니다.\n\n폭포수 강물 견본을 가지고 아우버다인에 있는 툰드리스 윈드위버에게 돌아가십시오.", description = "폭포수 강이 오염되어 타락하기 시작한 것은 큰 걱정거리가 아닐 수 없소. 그 강은 안개 해안으로 흘러들어 가기 때문에 머지 않아 아우버다인까지 그 영향이 미칠 게 틀림없소. 강 상류에 있는 검은나무일족 펄볼그들이 이 오염의 원인인 것 같지만 또 한편으로는 그 녀석들도 근본적인 원인이 아닐지 모른다는 생각도 든다오.\n\n이 견본 시험관을 가지고 북쪽에 있는 강어귀로 가시오. 내륙 쪽으로 가면 첫 번째 폭포가 있는데 그곳에서 물 견본을 가져와 주시오. 머리 위로 다리가 하나 보일 거요. 견본을 채취하면 다시 아우버다인으로 날 찾아오시오.", progress = "폭포수 강의 오염은 이곳 어둠의 해안에 퍼지고 있는 불길한 움직임의 시작에 불과하오. 그대가 견본을 가져오면 어떤 계획이라도 세울 수 있을 거요. 아마도 공격 계획이 되겠지.", completion = "이 물이 오염되었다는 사실이야 별반 놀랍지 않지만 이 정도로 심하게 썩어 있다니! 즉시 행동을 취해야 할 것 같소.\n\n여기서 동쪽으로 가면 악령의 숲이 있는데, 그곳이 이 타락의 진정한 근원이오. 난 전에도 가본 적이 있지. 이 견본으로 그 사실을 확인하게 될 것 같소. 타락의 치유제를 여기서 만들 수 있을지도 모르지만 시도라도 해보려면 도움이 필요하오. 그때가 오면 그대가 도움을 줄 수 있기를 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4763] = {title = "타락한 검은나무일족", objective = "아우버다인 달샘의 물로 빈 정화의 그릇을 채우십시오.\n\n검은나무일족 펄볼그 북부 야영지에서 검은나무일족 과일 견본, 검은나무일족 열매 견본, 검은나무일족 곡식 견본을 모으십시오.\n\n물과 음식을 한데 섞어 북부 야영지의 폭포수 강에서 가장 가까운 화톳불 근처에 두면 사티로스 타락자를 불러낼 수 있습니다.\n\n부패의 부적을 손에 넣은 후 아우버다인에 있는 툰드리스 윈드위버에게 가져가십시오.", description = "펄볼그를 타락시킨 장본인 중 하나가 사티로스라는 것을 알아냈소. 그들은 마법의 부적을 이용해 펄볼그들을 지배하고 있소. 펄볼그들을 정화하기 위해서는 사티로스 타락자를 유인해 그 부적을 빼앗아야만 하오!\n\n달샘의 신성한 물을 이 그릇에 담고 펄볼그 북부 야영지에서 음식 견본을 채취한 후, 그 둘을 섞어 강가에 있는 화톳불 근처에 두시오. 펄볼그들이 그 음식을 먹으면 잠시나마 정화될 테고 그동안 사티로스 타락자를 유인해낼 수 있을 거요... 그때 사티로스를 처치해야 하오!", progress = "부패의 부적은 자연의 균형을 깨뜨리는 사악한 물건이오. 펄볼그들을 괴롭히고 있는 사티로스에게서 이 물건을 손에 넣거든 내게 가져와 주시오. 그걸 부숴 버릴 수만 있다면 우리는 큰 승리를 거둘 수 있소!", completion = "타락의 세력으로부터 우리의 숲을 되찾기 위한 이 기나긴 전쟁은 이제 막 시작되었소. 하지만 오늘의 승리를 축하할 시간은 있지! &lt;name&gt;, 아우버다인 주민들은 그대에게 큰 은혜의 빚을 진 거요. 감사의 표시로 이걸 받아 주시오. 오늘 우리가 알게 된 이 사실이 언젠가 펄볼그 친구들을 고통의 족쇄에서 자유롭게 풀어 주게 될지도 모르오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n월장석 마법봉야생의수호자 다리보호구돌풍의 다리보호대\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4764] = {title = "파멸의 기념물", objective = "불타는 평원에 있는 마야라 브라이트윙에게 파멸의 기념물을 가져가야 합니다.", description = "검은바위 첨탑 높은 곳에는 한때 운명의 전당이라고 불리던 방이 있어요. 바로 검은무쇠단 드워프들이 유물, 전리품, 그리고 예술품 따위를 보관하던 곳이죠.\n\n그건 아주 오래전 얘기이고 지금은 그 전당이 무너져서 그 장소가 좀... 꺼림칙한 일에 쓰이고 있다고 해요. 하지만 아직도 오래된 드워프 유물이 좀 남아 있으리라 믿어요.\n\n그런 유물 중 하나가 파멸의 기념물이라는 것인데, 표면에 희귀한 보석들이 얼마나 많이 박혀 있는지 그걸 쳐다보는 드워프는 누구나 울게 된다고 하죠.\n\n그 기념물이 바로 우리의 목표이니 그걸 가져오세요.", progress = "기념물을 가져오셨나요? 제 고용주이신 백작님께서 아주 후한 보상을 해 줄 겁니다.", completion = "찾으셨군요! 소문이 사실이었어요!\n\n고맙습니다. 제 고용주, 레밍턴 리지웰 백작님께서 자신의 수집품에 추가하게 된 이 물건을 보시면 크게 기뻐하실 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4765] = {title = "리지웰에게 가져가기", objective = "스톰윈드에 있는 레밍턴 리지웰에게 리지웰의 상자를 가져가야 합니다.", description = "스톰윈드로 가져갈 수 있도록 파멸의 기념물을 상자에 넣어 포장을 마쳤습니다. 이번 일에 당신 도움이 아주 컸습니다. 그런데 마지막으로 한 가지만 더 부탁을 드려도 될까요?\n\n이 상자를 레밍턴 리지웰 백작님께 전해 주세요. 스톰윈드 왕궁에서 그분을 찾을 수 있을 겁니다. 백작님께 이걸 가져가면 분명 크게 기뻐하실 거예요.", progress = "검은바위 첨탑에서 전령이 선물을 가지고 올 거라는 소식을 들었는데... \n\n자네가 바로 그 심부름꾼인가?", completion = "아, 그게 자네였군! 정말 고맙네. 그리고 말이지... 아직 모르고 있었다면 말해 주겠는데, 리지웰 가의 귀족이 표하는 감사는 왕의 보상과 거의 맞먹는다네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n날쌘발 장화명멸의 손목보호대\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4766] = {title = "마야라 브라이트윙", objective = "불타는 평원에 있는 마야라 브라이트윙과 대화해야 합니다.", description = "폐허가 된 타우릿산 도시를 탐색하기 위해 불타는 평원으로 마야라 브라이트윙이라는 내 개인 요원을 한 명 보냈다네. 그 파괴된 검은무쇠단 드워프 도시에 아주 값진 물건들이 숨겨져 있을지도 모르지... 우리 가족 박물관에 꼭 들어맞을 만한 물건들 말일세.\n\n마야라 얘기로는 뭔가를 찾았다고 하는데, 그 물건을 가져오려면 도움이 필요할 거라고 전해왔네. 그런데 그 물건이 타우릿산에 있는 게 아니라, 검은바위 첨탑으로 쳐들어가야 하는 모양이야.\n\n나는 자세한 내용을 모르겠네만 혹시 관심이 있거든 불타는 평원으로 가서 마야라와 얘기해 보게.", progress = nil, completion = "스톰윈드에서 오셨다고요? 잘 됐군요. 레밍턴 리지웰 백작님께서 자신의 박물관에 두려고 안달을 할 만한 예술품을 알고 있는데, 꺼내 오는 게 쉽지 않을 거예요.\n\n바로 이 일에 당신 도움이 필요한 거랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4767] = {title = "와이번 조련사", objective = "높새바람 봉우리에 있는 엘루에게 마루둥지 와이번 알 10개를 가져가야 합니다.", description = "저는 와이번 조련사들을 위해 와이번을 모으는 임무를 맡았습니다. 언젠가는 저도 와이번을 타보고 싶어요. 와이번이 점점 늘고는 있지만 당장 탈 수 있는 와이번의 수요는 따라가지 못하고 있어요. 조련할 시간이 필요하거든요. 저를 좀 도와주세요.\n\n마루둥지로 가서 와이번 알을 좀 구해다 주세요. 여기서 북서쪽으로 협곡 절벽을 따라가다 보면 마루둥지로 올라가는 길이 보일 거예요. 와이번은 침입자에게 호락호락하지 않은데다 자기 알에 대한 보호 본능이 아주 강하니 조심하셔야 해요.", progress = "부탁한 와이번 알을 가지고 오셨나요? 하루라도 빨리 와이번을 조련해야 해요.", completion = "대단하군요! 어서 이 와이번 알들을 부화시켜 조련까지 성공할 수 있으면 좋겠어요. 감사의 표시로 이걸 드리지요. 앞으로 풍성한 사냥을 하시길 빌겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n고급 방어구 키트"},
[4768] = {title = "다크스톤 서판", objective = "카르가스에 있는 어둠마법사 비비안 라그레이브에게 다크스톤 서판을 가져가야 합니다.", description = "다크스톤 서판에는 이미 오래전에 죽은 우르헬트 다크스톤이라는 드워프의 글이 기록되어 있어요. 우르헬트 다크스톤은 솜씨가 아주 뛰어난 연금술사였는데 그와 동시대를 살았던 이들은 그가 미쳤다고 생각했기에 그의 연구 내용을 아무에게도 알리지 않았답니다.\n\n하지만 그는 그 내용을 서판에 새겨 놓았어요. 난 그런 서판 중 하나가 검은바위 첨탑 안, 한때 운명의 전당으로 불리던 방에 있다고 생각합니다. 검은바위 첨탑에 들어갔다 돌아오는 이가 거의 없어서 지금은 그 방을 뭐라고 부르는지 모르겠군요.\n\n하지만 위험을 무릅쓰고 내게 서판을 가져다주실 의사가 있다면 후하게 보상하도록 하겠습니다.", progress = "다크스톤 서판은 찾았나요? 어서 그 서판에 담긴 비밀을 알아내고 싶군요.", completion = "훌륭합니다. 이 서판에 새겨진 조제법을 연구하는 데는 여러 날이 걸리겠지만 분명 연구 결과는 아주 훌륭할 겁니다.\n\n고마워요. 우리에게 아주 큰 도움을 주었습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n날쌘발 장화명멸의 손목보호대\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4769] = {title = "비비안 라그레이브와 다크스톤 서판", objective = "어둠마법사 비비안 라그레이브와 대화해야 합니다.", description = "황야의 땅에 있는 카르가스에서 비비안 라그레이브가 소식을 전해 왔어요. 비비안이 연구한 바에 의하면, 우리 연구 조사에 도움이 될 만한 고대 기록이 검은바위 첨탑 내부에 있는 것 같다고 하더군요. 이 사실을 확인하기 위해서는 검은바위 첨탑에서 그 기록을 빼내올 이가 필요할 거라고 합니다. \n\n쉬운 일이 아니지만 혹시 관심이 있다면 카르가스로 가서 비비안과 얘기해 보세요.", progress = nil, completion = "사실입니다. 난 검은바위 첨탑 안에 오래된 연금술 조제법이 적혀 있는 서판이 있다고 믿습니다. 그 서판을 가져오는 일을 도와줄 이가 필요한데 당신이 와줘서 다행이군요.\n\n편하게 앉아서 내 설명을 들으시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4770] = {title = "집으로", objective = "마루둥지에 있는 파오카 스위프트마운틴을 호위해 간 다음 백사장 야영지에 있는 모테가 파이어메인과 대화하십시오.", description = "제발 저를 좀 도와주세요. 여기 마루둥지에 숨어 있는 동안 <race>의 얼굴을 본 지도 며칠이나 되었습니다. 저는 와이번을 조사하러 이곳에 왔는데 너무 가까이 다가갔던 모양입니다. 와이번 둥지에서 쫓겨난 후로 길을 잃고 말았지요.\n\n백사장 야영지로 돌아가야 합니다. 모테가는 제가 없어진 줄 모르고 있어요. 제가 혼자서 마루둥지에 간 걸 알면 엄청 화를 낼 거예요.\n\n백사장 야영지는 바로 동쪽에 있습니다. 저를 좀 데려다 주세요.", progress = nil, completion = "아니!? 파오카 스위프트마운틴 녀석이 마루둥지를 기웃거릴 줄 알았으면 토템에다 사슬로 묶어두는 건데. 파오카의 아버지는 녀석이 나와 함께 버섯구름 봉우리에 오는 걸 탐탁지 않게 여기셨죠. 우리는 이 아름다운 땅에서 서식하는 다양한 생물들을 조사하러 온 겁니다.\n\n아무튼 파오카를 도와주셔서 고맙습니다. 이걸로 충분한 답례가 되었으면 좋겠네요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4771] = {title = "여명의 계략", objective = "스칼로맨스의 스칼로맨스 강당 문에 여명의 계략을 놓아두고 벡투스를 처치한 후 베티나 비글징크에게 돌아가야 합니다.", description = "당신이 용의 알을 담아 가져온 용기에 여명의 계략을 넣어 두었어요. 이제 당신은 이 장치를 스칼로맨스 내부 깊숙이 가져가야 해요.\n\n벡투스라는 언데드 마법사가 스컬지 학자 팀 하나를 이끌고 있어요. 스칼로맨스 강당 문이라고 하는 그들의 방에 여명의 계략을 놓아두세요. 그곳에서 언데드를 감지하면 여명의 계략이 반응을 일으켜, 잘 하면 녀석들을 없애 버릴 수도 있을 거예요!\n\n그 후 벡투스를 처치하는 거야 간단하겠죠. 안 그래요?", progress = nil, completion = "해냈군요! 벡투스를 물리쳤어요! 여명의 계략이 작동을 하던가요?\n\n음... 내 장치가 바라던 만큼 성공적으로 작동하지는 않은 모양이지만, 그래도 사태를 수습하실 수 있었다니 다행이군요. 수고했어요!\n\n은빛 여명회와 아제로스의 선량한 주민들이 당신에게 큰 빚을 졌군요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n바람도끼춤추는 은마법봉\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4781] = {title = "흑마법사의 로브", objective = "가시덤불 골짜기에 있는 시즈크 굿스티치에게 금괴 하나를 가져가야 합니다.", description = "첫 번째 임무처럼 이번 임무도 어렵지는 않을 테지만, 다른 이의 도움이 조금 필요합니다.\n\n로브에 수를 놓을 금빛 실타래가 필요한데, 구하기 쉽지 않을 뿐 아니라 만드는 방법을 아는 이도 아주 극소수죠. 다행히도 우리와 뜻을 같이하는 충성스러운 자 하나가 숭고한 흑마법사의 길을 가는 자들을 돕고 싶어 해요.\n\n무법항에 있는 시즈크 굿스티치에게 금괴 하나를 가져가세요. 그는 전문 재봉사인데, 당신을 위해 기꺼이 금빛 실타래를 만들어줄 겁니다. 금괴는 솜씨 좋은 광부들이 제련하고 있으니 그들에게 도움을 청하도록 하세요.", progress = "금괴라... 그렇지, 좋소. 금괴 하나를 내게 주면 실을 만들어 주겠네. 그리고 내 말을 잘 들어 두게. 아주 힘겨운 시험들이 기다리고 있으니... 그때까지 자신을 더 강하게 만드는 데 주력해야 하네. 지금 자신이 얼마나 강하다고 생각하든, 나중에 준비를 좀 더 철저히 해둘 걸 하고 후회할 날이 분명 있을 테니까.", completion = "딱 이거면 되겠군. 그렇게 빨리 광부를 찾아 도움을 받을 수 있었다니 다행이군. 아니면 당신이 직접 한 건가? 어찌 됐든 아주 잘했어. 이거라면 실을 만드는 데 아주 안성맞춤이야.\n\n실을 만들려면 시간이 오래 걸리니 나중에 다시 와야 할 것 같네. 탑 안에 갇혀 금실만 잣고있는 어떤 공주에게 이 금괴를 보내야 하거든... 아... 진짜라니까, 진짜라고... 아! 알았네. 농담이었어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4782] = {title = "흑마법사의 로브", objective = "불모의 땅에 있는 미네라 보이드렌더에게 돌아가십시오.", description = "시간은 좀 걸릴 테지만 내가 꼭 실타래를 만들어줄 거라고 미네라에게 돌아가서 전해 주게. 그동안 당신은 로브에 필요한 나머지 재료들을 모아 와야 할거야. 그때까지는 실을 다 만들 수 있을 테니 여기로 다시 와서 실을 가져가도록 하게.\n\n행운을 비네, <name>. 아, 그리고 거기 간 김에 스트라드를 찾아가 내 안부도 전해 주게. 그 친구, 톱니항 바로 옆에다 탑을 세우다니... 제정신이 아닌 게지.", progress = nil, completion = "아, 돌아왔군요, &lt;name&gt;. 실은 어디 있나요?\n\n아, 그래요? 걱정 마세요. 그 고블린 친구는 아직 우릴 실망시킨 일이 없으니까. 그 자리에서 바로 만들어 주지 않았다 해도 괜찮을 거예요. 기다리죠... 뭐, 그동안 다른 일도 해야 하니까.\n\n다음 단계로 넘어갈 준비는 됐나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4783] = {title = "흑마법사의 로브", objective = "불모의 땅에 있는 미네라 보이드렌더에게 서릿발분노의 사티로스 피 10병과 하급 지옥정령석 1개를 가져가야 합니다.", description = "다음 재료는 불모의 땅에서 서쪽으로 멀리 떨어진, 돌발톱 산맥을 넘어야 보이는 잊혀진 땅에서 구할 수 있어요.\n\n그곳은 세계가 분리된 이후에도 여전히 혼돈이 지배하고 있는 곳이죠. 당신의 힘과 재치가 모두 필요할 겁니다. 영혼이 증오로 가득 찬 생물들뿐만 아니라 불타는 군단까지도 만나게 될 테니까요.\n\n북동부에 있는 서릿발분노 사티로스의 피를 가져오세요. 그리고 만노로크 소굴에 있는 하급 지옥불정령에게서 하급 지옥정령석을 가져오시고요.\n\n당신의 로브를 만드는 데 이 두 가지 물건을 모두 사용할 거예요.", progress = "잊혀진 땅은 험난하기 짝이 없는 곳이에요. 나가, 거인, 사티로스에 불타는 군단까지... 거기에다 켄타우로스 부족들이 전쟁을 벌이는 통에 조심하지 않으면 아주 위험한 곳이랍니다.\n\n전에도 얘기했듯이 힘과 재치가 모두 필요할 뿐 아니라 인내심도 있어야 할 겁니다. 그 땅에서는 부디 조심하셔야 해요, <name>.", completion = "아주 좋아요, &lt;name&gt;. 이거라면 충분하겠군요. 이제 마지막으로 몇 가지 재료만 더 구해오면 돼요. 저는 그동안 이것들을 로브를 제작하는 데 적당한 상태로 준비해 두도록 하겠어요. 준비됐나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4784] = {title = "흑마법사의 로브", objective = "불모의 땅에 있는 미네라 보이드렌더에게 고급 금빛 실타래와 이글거리는 석탄 2개, 그리고 영혼의 조각 1개를 가져가야 합니다.", description = "이제 세 가지만 더 있으면 당신을 위한 로브를 완성할 수 있어요.\n\n우선, 시즈크가 만들고 있는 고급 금빛 실타래가 필요해요. 무법항으로 다시 가서 그에게 실을 받아오도록 하세요.\n\n두 번째로, 아라시 고원에 있는 불의 정령들에게서 이글거리는 석탄 두 개를 가져오세요. 제 기억이 맞다면 서쪽에 있는 소라딘의 성벽 근처에 있을 거예요.\n\n마지막으로, 당신이 영혼의 조각 하나를 만들어 주셔야 해요.\n\n이 재료를 다 모은 후, 이 탑 앞으로 돌아오면 로브를 완성해 드리죠.", progress = "곧 완성돼요! <name>, 약속하죠. 그 로브는 기대 이상으로 우수하기 때문에 어떤 전투에서든지 승산을 높여 줄 거예요.", completion = "이제 다 끝났어요. 재료도 다 모았고 만들 준비도 다 됐어요.\n\n분명히 아주 맘에 들 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4785] = {title = "고급 금빛 실타래", objective = "자, 받으시오, <name>. 미네라에게 우리 대신 안부나 전해 주게.\n\n우리 형제는 당신에게 큰 기대를 걸고 있어. 언젠가 불타는 군단이 굴복하게 되면 모두들 당신의 이름을 크게 칭송하게 될 거야. 그날이 정말 기대되는 걸!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n고급 금빛 실타래"},
[4786] = {title = "완성된 로브", objective = "미레나 보이드렌드가 로브를 완성할 때까지 기다린 다음 그녀와 다시 대화하십시오.", description = "잠시만 기다려 주세요. 금방 로브를 완성해 드릴게요. 어디 멀리 가지 마세요.", progress = nil, completion = "이제 됐어요. 자, 받아요, &lt;name&gt;. 자부심을 갖고 입으세요.\n\n열심히 노력한 당신의 앞날에 위대한 역사가 놓여 있는 게 보이는군요. 당신은 분명 큰 성공을 거두게 될 겁니다. 기억해 두세요. &lt;class&gt;의 길을 가면서 만나게 될 타락을 물리치기 위해서는 굳건한 의지와 꿋꿋한 인내가 필요하다는 것을!", rewards = "다음과 같은 것들을 받습니다:\n\n마법의 황금 혈로브"},
[4787] = {title = "고대의 알", objective = "고대의 알을 타나리스에 있는 예킨야에게 가져다주어야 합니다.", description = "모쉬아루의 예언서에는 어떤 고대의 알에 대해 적혀 있는데, 이 알은 트롤족이 거대한 제국을 다스리던 때의 유물로 학카르의 정수를 담을 수 있는 힘이 있다고 하오. 어쩌면 학카르의 마수에서 아제로스를 지킬 수 있는 유일한 방법일지도 모르오.\n\n그 고대의 알을 가져다주시오, <name>. 동부 내륙지 진타알로 깊숙한 곳에 숨겨져 있다고 하오. 도시 꼭대기에 있는 원형 극장 뒤에 있는 동굴 안을 조사해 보는 게 좋을 것 같소.", progress = "고대의 알은 가져왔소? 거대한 마력의 움직임이 느껴지오. 시간이 별로 없는 것 같소.", completion = "알을 가져왔군! 당신에게 경의를 표하겠소, &lt;name&gt;. 그 힘과 용기는 오래오래 기억될 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4788] = {title = "마지막 서판", objective = "다섯 번째와 여섯 번째 모쉬아루 서판을 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다.", description = "내가 세 번째와 네 번째 모쉬아루 서판을 조사하는 동안 다섯 번째와 여섯 번째 서판을 찾아 오게! 쉽지는 않을 거야. 검은바위 첨탑에 있는 가시불꽃부족 트롤들이 갖고 있어. 검은바위 첨탑은 불타는 평원과 이글거리는 협곡 사이에 있는 용암이 이글거리는 산에 있지.\n\n행운을 빌어주지, <name>. 검은바위 첨탑은 매우 험난한 곳이야...", progress = "첨탑에는 다녀왔나, <name>? 다섯 번째와 여섯 번째 서판은 가져온 거야?", completion = "서판을 찾았다니 믿기지 않는걸! 당신은 진정한 영웅이야, &lt;name&gt;!\n\n잘 됐지, 뭐... 당신이 전에 가져온 서판들을 읽어보았는데 앞으로 일어날 사태를 막아내려면 영웅이 필요할 것 같아...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4801] = {title = "눈호랑이의 에코", objective = "여명의 설원으로 가면 눈호랑이라는 거대한 고양잇과 동물과 싸우게 될 거야. 엄청나게 빠르고 영리한 짐승이지. 눈호랑이와 같은 속도를 얻고 싶다면 놈들에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 몸에 지니고 있어야 한다는 사실을 명심하게.", description = nil, progress = "여명의 설원으로 가면 눈호랑이라는 거대한 고양잇과 동물과 싸우게 될 거야. 엄청나게 빠르고 영리한 짐승이지. 눈호랑이와 같은 속도를 얻고 싶다면 놈들에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 몸에 지니고 있어야 한다는 사실을 명심하게.", completion = "마우아리가 부적을 만들어 주겠네. 이 부적을 사용하여 자기 자신이나 동료들에게 마법을 걸어 보게.", rewards = "다음과 같은 것들을 받습니다:\n\n돌풍의 부적"},
[4802] = {title = "눈사태일족의 에코", objective = "여명의 설원으로 가면 눈사태일족 펄볼그라는 괴상한 족속과 싸우게 될 거야. 그들은 우두머리 덕에 엄청난 힘을 갖게 되었지. 눈사태일족과 같은 힘을 얻고 싶다면 그들에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 반드시 몸에 지니고 있어야 하네.", description = nil, progress = "여명의 설원으로 가면 눈사태일족 펄볼그라는 괴상한 족속과 싸우게 될 거야. 그들은 우두머리 덕에 엄청난 힘을 갖게 되었지. 눈사태일족과 같은 힘을 얻고 싶다면 그들에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 반드시 몸에 지니고 있어야 하네.", completion = "마우아리가 부적을 만들어 주겠네. 이 부적을 사용하여 자기 자신이나 동료들에게 마법을 걸어 보게.", rewards = "다음과 같은 것들을 받습니다:\n\n마력의 부적"},
[4803] = {title = "톱니이빨곰의 에코", objective = "여명의 설원으로 가면 가죽이 엄청나게 두꺼운 큰 곰을 만나게 될 거야. 톱니이빨곰이라고 하는 이 짐승은 견뎌낼 수 있는 최대한의 자극을 스스로 가해서 엄청난 내성을 얻는 능력을 지니고 있지. 불에 대한 저항력을 얻고 싶다면 이 곰에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 지니고 있어야 한다는 사실을 명심하게.", description = nil, progress = "여명의 설원으로 가면 가죽이 엄청나게 두꺼운 큰 곰을 만나게 될 거야. 톱니이빨곰이라고 하는 이 짐승은 견뎌낼 수 있는 최대한의 자극을 스스로 가해서 엄청난 내성을 얻는 능력을 지니고 있지. 불에 대한 저항력을 얻고 싶다면 이 곰에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 지니고 있어야 한다는 사실을 명심하게.", completion = "마우아리가 부적을 만들어 주겠네. 이 부적을 사용하여 자기 자신이나 동료들에게 마법을 걸어 보게.", rewards = "다음과 같은 것들을 받습니다:\n\n불꽃의 부적"},
[4804] = {title = "서리바람 키메라의 에코", objective = "여명의 설원으로 가면 서리바람 키메라라는 거대한 날짐승과 싸우게 될 거야. 서리바람 키메라는 냉기 마법 능력을 지니고 있지. 냉기에 대한 저항력을 얻고 싶다면 놈들에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 지니고 있어야 한다는 사실을 명심하게.", description = nil, progress = "여명의 설원으로 가면 서리바람 키메라라는 거대한 날짐승과 싸우게 될 거야. 서리바람 키메라는 냉기 마법 능력을 지니고 있지. 냉기에 대한 저항력을 얻고 싶다면 놈들에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 지니고 있어야 한다는 사실을 명심하게.", completion = "마우아리가 부적을 만들어 주겠네. 이 부적을 사용하여 자기 자신이나 동료들에게 마법을 걸어 보게.", rewards = "다음과 같은 것들을 받습니다:\n\n냉기의 부적"},
[4805] = {title = "얼음엉겅퀴설인의 에코", objective = "여명의 설원으로 가면 얼음엉겅퀴설인이라는 거대한 짐승과 싸우게 될 거야. 이 짐승은 몸놀림이 둔하지만 두꺼운 모피 덕분에 여러 차례의 충격에도 견딜 수 있지. 공격에 대한 방어력을 얻고 싶다면 이 짐승에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 지니고 있어야 하지.", description = nil, progress = "여명의 설원으로 가면 얼음엉겅퀴설인이라는 거대한 짐승과 싸우게 될 거야. 이 짐승은 몸놀림이 둔하지만 두꺼운 모피 덕분에 여러 차례의 충격에도 견딜 수 있지. 공격에 대한 방어력을 얻고 싶다면 이 짐승에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 지니고 있어야 하지.", completion = "마우아리가 부적을 만들어 주겠네. 이 부적을 사용하여 자기 자신이나 동료들에게 마법을 걸어 보게.", rewards = "다음과 같은 것들을 받습니다:\n\n회피의 부적"},
[4806] = {title = "서리망치거인의 에코", objective = "이미 여명의 설원에서 서리망치거인이라는 얼음 거인을 상대한 적이 있지? 그들의 무기는 오직 순수한 힘뿐이네. 서리망치거인의 괴력을 갖고 싶다면 그들의 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 지니고 있어야 한다는 사실을 명심하게.", description = nil, progress = "이미 여명의 설원에서 서리망치거인이라는 얼음 거인을 상대한 적이 있지? 그들의 무기는 오직 순수한 힘뿐이네. 서리망치거인의 괴력을 갖고 싶다면 그들의 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 마우아리의 부적을 지니고 있어야 한다는 사실을 명심하게.", completion = "마우아리가 부적을 만들어 주겠네. 이 부적을 사용하여 자기 자신이나 동료들에게 마법을 걸어 보게.", rewards = "다음과 같은 것들을 받습니다:\n\n힘의 부적"},
[4807] = {title = "올빼미야수의 에코", objective = "여명의 설원으로 가면 천부적으로 마법의 능력을 타고난 족속과 싸우게 될 거야. 올빼미야수라고 하는 이 족속은 강력한 마법을 부리지. 자신의 지능을 향상시키고 싶다면 올빼미야수에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 반드시 마우아리의 부적을 지니고 있어야 하네.", description = nil, progress = "여명의 설원으로 가면 천부적으로 마법의 능력을 타고난 족속과 싸우게 될 거야. 올빼미야수라고 하는 이 족속은 강력한 마법을 부리지. 자신의 지능을 향상시키고 싶다면 올빼미야수에게서 에코를 구해 오게.\n\n그리고 에코를 손에 넣으려면 반드시 마우아리의 부적을 지니고 있어야 하네.", completion = "마우아리가 부적을 만들어 주겠네. 이 부적을 사용하여 자기 자신이나 동료들에게 마법을 걸어 보게.", rewards = "다음과 같은 것들을 받습니다:\n\n계략의 부적"},
[4808] = {title = "펠노크 스틸스프링", objective = "팅키의 편지를 펠노크 윈터스프링에게 가져다주어야 합니다.", description = "당신에게 부탁하고 싶은 것이 있어요.\n\n당신이 가져다준 정수를 연구한 결과, 새끼용의 알도 냉동 보관할 수 있을 것 같아요! 이 가설을 실험해 보고 싶지만, 특별 제작한 기계 부품이 필요할 것 같네요. 내 동기인 펠노크 스틸스프링이 그것들을 만들 수 있을 거예요.\n\n여기, 이 편지를 펠노크에게 가져다주세요. 거기에 내가 필요한 게 뭔지 적혀있어요. 여명의 설원에 있는 눈망루 마을에서 펠노크를 만날 수 있을 거예요.", progress = "엄청나게 춥군! 이불 좀 가져다 주면 좋겠는데!", completion = "이불이 아니잖아! 근데 이건 뭐지? 팅키의 편지? 무슨 일로 편지까지 썼을까 궁금하군...\n\n오, 불타는 평원에서 연구를 하고 있는 모양이군. 거기서는 새끼용을 쉽게 구할 수 있을 테니까 말 되는군. 오호? 이것 봐라! 원하는 것을 만들기 위해서 몇 가지 부품이 필요하다고 써 있군. 그래서 내 생각이 난 거로군?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4809] = {title = "서리바람 키메라의 뿔", objective = "펠노크 윈터스프링에게 온전한 서리바람 키메라의 뿔 8개를 가져가야 합니다.", description = "팅키가 필요로 하는 거의 모든 부품을 가지고 있지만 하나가 모자라는데 말이야. 바로 중요 부품인 서리바람 키메라의 뿔이지. 여명의 설원에 서식하는 서리바람 키메라의 뿔은 상당한 냉기를 품고 있지. 다만 멀쩡하고 금이 가지 않은 뿔에 한해서지만 말이야. 그것들이 좀 있어야 팅키의 부탁을 들어줄 수 있다고!\n\n온전한 서리바람 키메라의 뿔을 내게 가지고 와 줘. 그러면 내 팅키가 주문한 부품들을 준비하지.", progress = "서리바람 키메라의 뿔을 가지고 왔나?", completion = "아주 좋은 재료로군. 냉기를 가득 품고 있어! 장갑을 좀 끼고 와서 팅키의 짐을 포장해 주지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4810] = {title = "팅키에게 돌아가는 길", objective = "불타는 평원의 팅키 스팀보일에게 펠노크의 소포를 가져가야 합니다.", description = "좋아, 모든 것이 준비됐고 이제 배달하기만 하면 되는군! 당신의 여행에 행운이 있기를 빌어 주지. 팅키가 내게 신세졌다는 걸 꼭 말해주라고!", progress = "당신이군요! 펠노크와 얘기해 봤나요? 내가 필요한 부품들을 가져왔겠죠?", completion = "가져왔군요! 좋아요! 바로 일을 시작해야겠네요! 백만 스물하나만큼 고마워요!\n\n당신은 정말 큰 도움이 되었어요. 나중에 이것보다 더 중요한 일을 맡게 될 거예요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n전격의 도끼죽음의 홀\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4811] = {title = "붉은 수정", objective = "어둠의 해안의 동쪽 산맥을 따라 아우버다인 동쪽으로 가서 거대한 붉은 수정을 찾은 다음 아우버다인에 있는 파수꾼 글린다 날셰에게 보고해야 합니다.", description = "이곳에서 동쪽에 난폭한 달빛야수들이 출몰하고 있는데 그 수가 계속 늘어나고 있습니다. 한 때 달빛야수는 온화하고 신성한 동물로 여겨지기도 했습니다. 일부에서는 달빛야수를 여전히 신성시하고 있지만 저는 아우버다인의 안전을 위해 좀 더 현실적인 판단을 내려야 합니다.\n\n보고에 의하면 달빛야수들이 어둠의 해안, 동쪽 산맥을 따라 거대한 붉은 수정으로 향하고 있다고 합니다. 그런데 어느 누구도 그 수정이 어떤 물건인지, 심지어 실제로 존재하는지 여부조차 모르고 있습니다. 그곳으로 가서 수정을 찾아 저에게 보고해 주셨으면 합니다.", progress = nil, completion = "&lt;name&gt;, 어쨌든 임무를 잘 마치셨군요. 훌륭해요! 수정이 실제로 거기 있더란 말이죠? 흥미롭네요...\n\n그 수정은 정확하게 어떤 물건일까요? 이것 말고도 궁금한 점이 아주 많습니다. 왜 달빛야수들이 그 수정에 끌려가는 것일까요? 그리고 그 수정이 좋은 징조일까요? 아니면 사악한 목적에 이용되고 있는 것일까요?\n\n수정을 좀 더 자세히 조사해 보고 수많은 의문의 해답을 알아내는 것이 좋겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4812] = {title = "수정에 물이 흐르면", objective = "빈 시험관에 아우버다인의 달샘 물을 채운 후 어둠의해안의 동쪽 산에 있는 붉은 수정을 찾아 조사하십시오.", description = "이 빈 시험관에 아우버다인의 달샘 물을 채우세요. 강력한 마법이 깃든 달샘의 물이라면 수정의 성분에 대한 단서를 얻을 수 있을 겁니다. 당신은 달샘의 물을 떠서 수정에 붓기만 하면 됩니다. 그 다음은 달샘의 마법이 알아서 할 테니까.\n\n여기서 동쪽으로 올라가면 악령의 숲입니다. 그리 위험하진 않겠지만 그래도 조심하는 게 좋을 겁니다. 만약 제 생각대로 수정이 악령의 숲에 결속되어 있다면 아주 위험할 수도 있습니다.", progress = "이 수정은 수풀이 우거진 어둠의 해안 부근의 경치와는 매우 이질적으로 보입니다. 수정 안으로부터 아주 나지막하게 콧노래 소리가 들리는 것만 같습니다.", completion = "신비한 수정과 다시 만나게 되었습니다. 시험관의 마개를 따고 그 안에 든 달샘의 물을 수정 위에 붓습니다. 달샘의 물이 수정에 흘러내리자, 흐릿한 표면이 투명하게 변합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4813] = {title = "수정 안의 뼈", objective = "아우버다인에 있는 파수꾼 글린다 날셰에게 알아 낸 사실을 보고해야 합니다.", description = "달샘 물을 수정에 부어본 결과, 내부에 반밖에 안 남은 턱뼈와 작은 뼛조각 몇 개가 있다는 것을 알아냈습니다. 턱뼈는 인간의 것으로 보이지만 수정을 깨서 눈으로 확인해보기 전에는 확신할 수 없습니다. 이 수정은 최강의 마법으로도 깰 수 없는 거의 완전무결에 가까운 위대한 작품인 것 같습니다.\n\n일을 마친 후 아우버다인에 있는 파수꾼 글린다 날셰에게 돌아가 보고해야 합니다.", progress = nil, completion = "수정에 대해 좀 더 알아냈다고 해도 여전히 많은 의문이 남습니다!\n\n당신이 알아낸 정보는 아우버다인의 의회에 알리겠습니다. 원로들이라면 이 신비한 수정을 어떻게 처리할지 알고 계실지도 모릅니다. 대책을 발견한다면 동부 왕국은 미지의 위험으로부터 벗어날 수 있을 것입니다.\n\n&lt;name&gt;, 이걸 받아 주십시오. 임무를 완수한 대가라고 생각하시면 됩니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n가시강철 쇼트소드굽이나무 단검떡갈나무 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4821] = {title = "괴상한 알", objective = "높새바람 봉우리에 있는 하가르 라이트닝후프에게 괴상한 알을 가져가야 합니다.", description = "이곳 버섯구름 봉우리에 괴상한 알이 있다는 소문이 돌기 시작했소. 그런데 이 알을 봤다는 자들도 가까이 접근하지는 못했기 때문에 자세히 살펴본 이는 아무도 없다고 하는군. 독사들이 마치 자기가 낳은 알인 양 보호하고 있기 때문이지.\n\n내가 조사를 좀 해볼 수 있게 그 괴상한 알을 가져와 주시오. 보고에 의하면 이 알은 뱀 동굴에 있다고 하오. 높새바람 봉우리의 남쪽으로, 그리고 북동쪽과 절벽을 따라가다 보면 그 밑부분에 뱀 동굴이 몇 개 있을 거요.", progress = "이 수수께끼 같은 알에 대해 반드시 알아내야 하오. 그 알에서 뭐가 부화할지 아무도 모르는 일이니.", completion = "아. 드디어 수수께끼의 괴상한 알을 찾아오셨군. 자세히 좀 볼까. 아니... 이게 뭐지?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4841] = {title = "켄타우로스 처치", objective = "갈라크일족 척후병 12명, 갈라크일족 사냥꾼 10명, 갈라크일족 바람전사 6명을 처치한 후, 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 돌아가야 합니다.", description = "이 켄타우로스들을 처치하는 일을 부디 맡아주게. 분노한 우리가 복수를 맛볼 수 있게 해주게나. 높새바람 봉우리 북쪽에 있는 켄타우로스 야영지를 공격하게! 분노의 힘이 영웅의 손을 이끌어 줄 걸세!", progress = nil, completion = "고마움이 담긴 내 성의 표시를 받아 주게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4842] = {title = "이상한 근원", objective = "도노바 스노우덴의 지시를 따라 탐색을 한 후 되돌아오십시오.", description = "솔직히, 이곳 여명의 설원은 화산도 없는데 이 온천들이 생겨난 걸 보면, 어떤 이상한 이유가 있지 않나 싶어요...\n\n직접 눈으로 확인하시는 게 더 좋겠군요. 여명의 설원을 쭉 따라서 남쪽 끝까지 가보세요. 공기가 텁텁해지고 하늘이 어두워지면 바로 제가 말씀드린 온천의 근원이라는 것을 찾은 겁니다.\n\n한번 가보세요. 되돌아오실 때에는 아마 질문거리들이 잔뜩 생길 거예요.", progress = nil, completion = "제 생각도 같습니다. 검은속삭임 협곡에 사는 악마들로 인해 이 땅이 나쁜 영향을 받고 있는 거라고요. 저는 계속해서 이곳의 온천을 조사하면서 뭔가 더 알아낼 수 있는지 보겠어요.\n\n검은속삭임 협곡으로 가보실 생각이라면 좀 더 강해질 때까지 기다리는 게 좋겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n깊은여울 망토"},
[4861] = {title = "성난 올빼미야수", objective = "여명의 설원 남부 지역에서 야론 스톤셰이퍼의 야영지를 찾아서 부서진 보급품 상자를 되찾아 와야 합니다.", description = "나는 여명의 설원 남부에서 야영을 하다가 광폭한 올빼미야수들에게 쫓겨나고 말았소! 올빼미야수들이 지키고 있던 뭔가에 너무 가까이 접근했던 모양이오.\n\n나는 그곳에서 간신히 빠져나왔지만 내 친구는 그렇게 운이 좋지 않았소. 위험을 무릅쓰고 내 야영지로 가볼 생각 없소? 보급품도 필요한 데다 어제 발굴 현장에서 캐낸 아뮬렛도 되찾고 싶소.", progress = nil, completion = "야영지의 물품들은 거의 다 심하게 파괴되어 있습니다. 그 중에서도 아주 심하게 부서진 상자가 눈에 띕니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4862] = {title = "더러운 거미알", objective = "검은바위 첨탑으로 가서 키블러를 위해 첨탑 거미알 15개를 수집해야 합니다.\n\n들리는 소문으로는 그 알들은 거미들이 서식하는 근처에서 찾을 수 있다고 합니다.", description = "믿거나 말거나 길들어진 흉악한 괴물들을 사려고 하는 자들이 있어요!\n\n검은바위 첨탑의 거미알들을 채집하려고 비쥬를 보냈는데, 웬일인지 소식이 없어요. 어쩌면 당신이 나를 도와 줄 수 있을지도 모르겠군요?\n\n이봐요. 검은바위 첨탑으로 가서 거미 알들을 채집해다 주지 않겠어요? 그것들을 가지고 오면 보수도 주겠거니와, 괴물 한 마리를 길들여 주도록 하죠!", progress = "가방 안에 거미알들을 가지고 온 건가요, 아니면 그저 날 보는 게 좋은 건가요?", completion = "와, 엄청난 양이군! 이 알들 좀 봐! 이놈들은 돈이 좀 되겠군.\n\n약속한 대로 당신의 애완 동물이 여기 있어요. 물리지 마세요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n불그물거미 알주머니"},
[4863] = {title = "성난 올빼미야수", objective = "야론 스톤셰이퍼의 부서진 마차를 찾아야 합니다.", description = "주위를 둘러보니 야론이 원할 만한 물건은 별로 없지만, 방금 찾은 부서진 상자는 열려 있어 마치 올빼미야수들이 유독 이 상자만을 노린 것 같습니다...\n\n동쪽으로 조금 떨어진 곳에 버려진 듯한 마차가 아련히 보입니다. 그곳에서 야론의 물건을 찾을 수 있을지도 모르니 한번 조사해보는 것이 좋겠습니다.", progress = nil, completion = "마차에 다가가보니 여기도 야론이 원할만한 물건은 별로 없는 것 같습니다. 하지만 아직 부서지지 않은 상자가 눈에 반쯤 묻혀 있는 것이 보입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4864] = {title = "성난 올빼미야수", objective = "눈 속에서 야론의 보급품을 회수한 다음, 야론이 찾는 아뮬렛을 훔친 올빼미야수들을 찾아야 합니다.\n\n여명의 설원, 별똥별 마을에 있는 야론 스톤셰이퍼에게 야론의 보급품과 푸른 깃털달린 아뮬렛을 갖다주어야 합니다.", description = "당신은 조심스레 상자의 내용물을 조사합니다. 안에 든 도구들과 다른 물건들을 야론에게 가져가는 게 좋겠습니다. 하지만, 아무리 찾아도 아뮬렛은 없습니다.\n\n이곳의 북쪽과 동쪽에는 올빼미야수들이 서식하는 것 같습니다. 그들과 싸우다 보면 아뮬렛을 되찾을 수 있을지도 모릅니다.", progress = "아, 어떻게 됐소?", completion = "내 그럴 줄 알았소. 그 미친 짐승들이 내 물건들을 몽땅 부숴버렸을 거라 짐작했지...\n\n하지만, 도구들도 찾았고, 무엇보다 아뮬렛을 찾아서 천만다행이오! 올빼미야수들이 어째서 이 물건을 그토록 열심히 지켰는지 궁금하군... 어쨌든 이제부터 그쪽으로는 발길도 돌리지 않을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4865] = {title = "뱀의 복수", objective = "발견한 사실을 모테가 파이어메인에게 보고해야 합니다.", description = "이 두 눈으로 직접 보지 않았으면 절대 사실이라고 믿지 않았을 거요. 버섯구름 봉우리에 복수의 물결이 들이 닥치고 있소!\n\n<이마의 땀을 닦는 하가르>\n\n서둘러 모테가 파이어메인을 찾아가시오. 높새바람 봉우리에서 길을 따라 북서쪽으로 가면 백사장 야영지가 있는 곳에 모테가가 있소이다. 그라면 지금 어찌 해야 할지 알 거요!", progress = nil, completion = "복수라고! 아리카라의 전설이 정말로 사실이었군요. 이건 정말로 시급히 해결해야 할 문제입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4866] = {title = "여왕 거미의 독", objective = "검은바위 첨탑 중심부에서 여왕 불그물거미를 찾을 수 있습니다. 여왕 불그물거미를 공격하거나 접근하여 그 독에 중독되어야 합니다. 독에 걸릴 확률을 높이기 위해서는 거미를 죽여야 할 수도 있습니다. 중독되면 털보 존에게 돌아가서 그가 그 독을 추출하게 해야 합니다.", description = "그건 세상에서 가장 강력한 독 중에 하나라고 할 수 있지!\n\n내가 첨탑에 갔을 때 검은바위부족 녀석들이 이 독의 위력에 대해서 얘기하고 있던 것을 엿들었소. 그들은 그것을 그물걸이 통로의 거대하고 흉포한 여왕 불그물거미의 이름을 따서 '여왕의 독'이라고 부른다오.\n\n당신이 내게 구해다 주어야 할 것이 바로 그거요. 당신의 혈관에 '흐르는' 살아 있는 독 표본이지. 그저 분비물만으로는 충분하지 않을 테니까! 그 여왕 거미의 독에 걸린 상태로 내게 돌아오시오!\n\n그럼 그 독을 짜내도록 하지!\n\n<기대에 차서 손을 비비는 존>", progress = nil, completion = "이걸로 최고의 맥주를 만들 수 있겠군!\n\n음? 내가 이걸 가지고 뭘 할 거라고 생각했던 거지? 독이라도 만들 거라고 생각했소?\n\n정신 나간 친구로군...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n털보 존의 마법 술잔"},
[4867] = {title = "우로크 둠하울", objective = "와로쉬의 두루마리를 읽어야 합니다. 와로쉬에게 그의 부적을 가져가야 합니다.", description = "으악! 말하기가 힘들다!\n\n이 쪽지를 가지고 가라! 내 부적을 가져와!", progress = "아! 내 부적을 가지고 왔나?", completion = "아하! 벌써 내 힘이 돌아오는 것을 느낄 수 있군. 내 영혼도 우로크의 저주에서 벗어났고.\n\n고맙다! 난 겸손과 어울리진 않지만 너의 도움을 내 절대 잊지 않겠다.\n\n그리고 검은바위 첨탑을 지나는 너의 여정에 행운이 깃들기를 빌어주지. 넌 꼭대기까지 혼자서 올라갈 수 있다고 믿는 어리석은 자이지만 용기 하나만은 정말 가상하군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n오색 부적"},
[4881] = {title = "암살 음모", objective = "백사장 야영지에 있는 카나티 그레이클라우드에게 가서 암살 음모에 대해 경고해 주어야 합니다.", description = "감히 카나티 그레이클라우드라는 타우렌이 버섯구름 봉우리에 사냥용 야영지를 세웠다. 우리가 가서 그를 처치하고 야영지와 그를 따르는 자들을 모두 없애 버려야 한다. 구름 승강장 남서쪽에 있는 작은 전초기지에서 모이도록 하라.", progress = nil, completion = "허, 날 죽이러 온다고? 타우렌이 싸우는 방식을 제대로 보여 주겠어!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4882] = {title = "수호에 대한 비밀", objective = "피멍울 초소에 있는 트룰 페일베인에게 푸른 깃털달린 목걸이를 갖다주어야 합니다.", description = "얼마 전 쓰러뜨린 올빼미야수의 목에서 떨어진 목걸이가 얼마나 중요한 것인지는 확실치 않습니다. 목걸이는 주기적으로 밝게 빛났다 흐려졌다 합니다.\n\n올빼미야수들에 박식한 트룰 페일베인이 더 자세한 얘기를 해줄 수 있을지도 모릅니다. 그에게 물어보는 것이 좋겠습니다.", progress = "또 다른 임무를 맡고 싶어 왔나?", completion = "중요한 발견이라고?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4883] = {title = "수호에 대한 비밀", objective = "푸른 깃털달린 목걸이를 나라 와일드메인에게 갖다주어야 합니다.", description = "자네가 여명의 설원에서 처치한 올빼미야수들에 관해서 많은 것을 알고 있다고 자부하는 편이지만, 사실 녀석들의 마법에 대해서는 잘 모른다네. 하지만 그 목걸이가 대체 무엇인지 말해줄 만한 사람을 하나 알고 있지.\n\n이 분야에서는 썬더 블러프에 사는 나라 와일드메인이 전문가이니 그녀를 찾아가 보게. 행운을 빌어주지, <name>.", progress = "무슨 일이신가요, <name>?", completion = "이 목걸이에서 나오는 힘의 근원은 한 군데밖에 없어요.\n\n&lt;눈을 감고 잠시 생각에 빠지는 나라&gt;\n\n혼란에 빠져 비뚤어진 올빼미야수들은 예전에는 그런 존재가 아니었답니다. 신성한 목적을 지니고 엘룬을 섬기도록 인도받은 생명체였죠. 나이트 엘프의 여신 엘룬은 이 생물들을 창조해서 신성한 지역을 수호하는 임무를 맡겼답니다.\n\n이 사실이 그다지 중요해 보이지는 않는 것 같지만, 더 자세히 조사해 봐야할 필요가 있을 겁니다.\n\n그 이유는 때가 되면 알게 될 거예요. 아무튼 이 목걸이를 갖고 와줘서 고마워요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n물보라 팔보호구빛나는 팔보호대\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4901] = {title = "제단의 수호자", objective = "엘룬의 제단을 여는 과정에서 란샬라를 보호해야 합니다. 성공하면 루테란 마을에 있는 에렐라스 앰버스카이에게 발견한 내용을 보고해야 합니다.", description = "저는 올빼미날개 숲 꼭대기에 여신 엘룬의 제단이 있다는 전설을 믿고 있어요. 그곳에 있는 다섯 개의 동굴에서 엘룬의 불꽃을 모두 밝히면 제단을 열 수 있을 것 같아요.\n\n제가 고대 켈테릴의 폐허에 있는 돌에 새겨진 주문을 떠왔어요. 아무래도 이 주문이 제단을 여는 비밀을 간직하고 있는 것 같아요. 제가 주문을 외울 동안 그대가 불을 밝혀 주시면 좋겠어요.\n\n그리고 일이 잘 되면 에렐라스에게 발견한 내용을 보고하시고요.", progress = nil, completion = "란샬라를 만나셨소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4902] = {title = "엘룬의 올빼미야수", objective = "다르나서스에 있는 대드루이드 판드랄 스테그헬름과 대화해야 합니다.", description = "정말 대단한 사실을 알아냈구려!\n\n난 항상 진실을 알고 싶었소. 그런데 이 귀중한 지식을 가능하면 많은 이와 나누는 것이 당연하지 않겠소? 서둘러 대드루이드 판드랄 스테그헬름에게 가시오. 다르나서스의 세나리온 의회에 있소이다. 방금 저에게 말씀하신 사실을 그에게 설명해 주시오. 그 역시 깊은 관심을 가질 테니까.\n\n이건 아주 중요한 정보요, <name>!", progress = nil, completion = "뜸들이지 말고 여기 온 이유를 말해보시오.\n\n아, 그런 일이 있었소? 흠...\n\n나에게 알려줘서 고맙소. 중요한 일은 언제나 최고 결정권자에게 바로 보고하는 게 제일이지. 그런데... 그래! 세나리온 의회의 드루이드가 한동안 올빼미야수를 알고 지냈지. 올빼미야수는 엘룬의 애완동물이며 가장 신성한 장소를 지키도록 선택받은 생물이라오.\n\n그대가 전해준 소식도 별로 새로운 것은 아니지만 그 노고는 칭찬을 받아 마땅하오. 자, 이것을 받으시오. 이 정도면 적당할 듯싶소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n찔레가시 활유리 목걸이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4903] = {title = "장군의 명령", objective = "대군주 오모크와 대장군 부네, 대군주 웜타라크를 처단해야 합니다. 검은바위의 중요한 문서들을 확보해야 합니다. 임무를 완수하는 대로 카르가스의 장군 고어투스에게로 돌아가야 합니다.", description = "고어투스 장군의 명을 받들어 검은바위 첨탑의 거주자들을 처단해야 한다. 처단해야 하는 자들은 다음과 같다.\n\n크나큰 골칫거리, 대군주 오모크,\n\n흉포하고 무자비한 트롤, 대장군 부네,\n\n하부 도시의 책임자, 대군주 웜타라크\n\n또한 중요한 문서들은 발견하는 대로 모두 가져와야 한다. 성공하면 영예가 함께할 것이며, 실패한다면 역사의 뒤편으로 사라질 것이다.", progress = "<경례하는 장군 고어투스>", completion = "&lt;일순간 창백하게 변하는 장군 고어투스의 연녹색 피부&gt;", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n웜타라크의 족쇄오모크의 허리죔쇠할리콘의 재갈보쉬가진의 허리끈부네의 사술 장갑\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4904] = {title = "마침내 자유를", objective = "라코타 윈드송을 먹구름 봉우리에서 구출한 후, 높새바람 봉우리에 있는 탈리아 앰버하이드와 대화하십시오.", description = "아르낙은 우리가 꼭 결혼할 걸로 혼자 착각하고 있었어군요... 하지만 제가 청혼을 거절했더니 바로 그날 밤 절 납치했어요. 제 동생이 아르낙을 막으려 했지만 워낙 힘이 세서... 동생을 죽이고 절 여기로 납치해왔어요. 불쌍한 내 동생...\n\n<name>, 먹구름 봉우리에서 절 좀 구출해 주지 않으시겠어요? 부탁입니다. 탈리아에게 가야 해요! 지금 제 걱정에 안절부절 못하고 있을 거예요.", progress = nil, completion = "감사합니다, &lt;name&gt;. 전 라코타가 언젠가는 반드시 돌아오리라 믿고 있었어요. 당신이 구해주었다고 하더군요. 이 물건은 원래 라코타의 동생 것이었지만 그녀도 당신께 드리기를 원할 겁니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n바람노래 허리띠바람노래 망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4906] = {title = "오염의 확산", objective = "에리단 블루윈드를 위해 비취불꽃 지옥소환사 8명과 배반자 8명, 그리고 요술사 8명과 사바릭을 처단해야 합니다. 임무가 완수되는 대로 에리단에게 돌아가십시오.", description = "사바릭이 이끄는 사티로스 잔당들이 악령의 숲 북쪽 땅을 넘보고 있소. 비열한 배반자와 요술사들은 악령의 숲에서 서식하고 있는 오염된 동물들로 배를 채우고 있다오.\n\n사바스라스와 그 졸개들은 사실 졸개였을 뿐이지. 오염된 달샘들을 확보하고 약탈한 것들을 사바릭에게 바치는 수하들이었소.\n\n사바스라스도 없애버렸으니 이제 이 일의 끝을 보시오. 북쪽으로 가서 사바릭을 처치하시오.", progress = nil, completion = "이렇게 도와줘서 정말 고맙소, &lt;name&gt;. 엘룬께서 그대를 보호하고 길을 인도해줄 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n뭉게구름 팔보호구"},
[4907] = {title = "팅키 스팀보일", objective = "팅키 스팀보일과 대화해야 합니다.", description = "여어, <class> 친구. 팅키 스팀보일을 기억하나? 그녀는 당신을 기억하고 있다고! 팅키가 나를 보내서 당신이 무엇을 하고 있는지 보라고 했지. 당신의 도움이 또다시 필요한 모양이야. 내 생각엔 그녀의 용 연구에 관한 일인 것 같다고.\n\n불타는 평원의 화염 마루에서 그녀를 만나보라고.", progress = nil, completion = "펠노크의 말이 맞아요! 당신의 도움이 필요해요. 이번엔... 정말로 위험할지 몰라요.\n\n준비됐나요??", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4921] = {title = "전쟁으로 잃은 아내", objective = "크로스로드에 있는 만크릭을 위해 그의 아내의 흔적을 찾아 돌아가야 합니다.", description = "조그마한 타우렌 마을에서 전투를 벌이고 있을 때 아내와 떨어지게 됐소. 그녀는 혼자서 뾰족털일족들 세 명을 상대했지. 그러다가 적이 우리를 압도하기 시작했소. 난 후퇴를 지시했지만 새로 몰려온 적들이 아내를 완전히 에워싸고 말았소. 분노에 차서 필사적으로 검을 휘둘렀지만 결국 머릿수에 밀리고 말았소이다.\n\n정신을 잃었다가 깨어나 보니 한 타우렌 드루이드가 내 상처를 치료하고 있었소. 쓰러진 나를 그 드루이드가 업고 황금길을 건넜다더군.\n\n제발 내 아내의 흔적을 찾아주시오, <class>|1이여;여.", progress = nil, completion = "그렇게 됐군그래... 어쨌든 고맙소, &lt;class&gt;.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4941] = {title = "아이트리그의 지혜", objective = "오그리마의 스랄의 요새에 있는 아이트리그와 대화해야 합니다. 아이트리그의 얘기를 듣고 난 후에는 대족장 스랄과 상의해야 합니다.", description = "렌드가 살아있다고?\n\n그럴 리가 없네!\n\n그는 몇십 년 전에 이미 죽었다고 생각했는데...\n\n아이트리그의 지혜를 구해보도록 하게. 그는 누구보다 검은바위부족의 사정에 대해서 많이 알고 있고, 만약 여기에 쓰인 내용이 사실이라면 아이트리그도 알고 있을 것일세. 그 누구도 복수의 권리를 부정하지 못해.\n\n오그리마로 가서 아이트리그를 만나보게. 그의 이야기를 들어보고 그가 이 문제에 대해서 어떻게 할 것인지 대족장님께 알려드리도록 하게.", progress = "내가 방해받아서는 안 된다는 것을 모르는가!", completion = "&lt;가져온 급보에 당혹스러워 하는 모습을 보이는 스랄&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4961] = {title = "오라힐 보주의 정화", objective = "보주의 악마를 물리치고 타베사와 대화하십시오.", description = "호오, 소환사의 보주로군요. 바로 여기서 어둠의 기운이 흘러나오고 있던 거였어요. 이것을 쓰고 싶다면 먼저 이 보주에 깃든 악마를 내쫓아야 해요. 그건 나 정도 되면 쉽게 할 수 있는 일이에요.\n\n하지만 당신의 역할은 쉽지 않죠. 내가 여기서 악마를 뽑아 내자마자 그 악마를 처리해야 합니다.\n\n최대한 빨리해야 해요. 너무 오래 걸리면 그 악마는 보주로 돌아가서 처음부터 다시 시작해야 하니까.\n\n그러니 단단히 준비하세요, <name>. 가장 강력한 기술과 회복약들을 준비해 두세요. 친구가 있다면 불러 오시고요. 만만히 볼 일이 아니니까요.", progress = nil, completion = "잘했어요, &lt;name&gt;! 이걸로 한동안 그놈이 찝쩍거리지 않겠죠. 당신에겐 대단한 힘과 기술이 있군요. 이제 정화된 보주를 가지고 미네라에게 돌아가야겠죠? 그걸 제대로 쓸 수 있게 만들려면 말이에요.\n\n행운을 빌어요, &lt;class&gt;. 어쩌면 우린 다시 만날지도 모르겠네요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n정화된 지옥의 보주"},
[4962] = {title = "지옥사냥개의 영혼", objective = "지옥의 루비를 가지고 가서 잊혀진 땅에 서식하는 지옥사냥개 중 한 마리에게 사용해야 합니다. 성공하면 지옥의 루비와 사로잡은 지옥사냥개의 영혼을 불모의 땅에 있는 미네라에게 가져가야 합니다.", description = "흐음, 지옥사냥개의 영혼을 사로잡기로 결정한 거군. 좋아.\n\n이 루비를 가지고 가게. 이게 있으면 그놈의 영혼을 사로잡을 수 있네. 이건 자네가 이미 알고 있는 방식으로 사용하면 되지. 먼저 녀석을 거의 초주검 상태로 몰아넣은 다음 그걸 쓰게. 그럼 나머지는 루비가 알아서 해줄 거야.\n\n잊혀진 땅으로 가서 지옥사냥개 한 마리를 잡아 오게. 그놈들이라면 괜찮을 거야.\n\n성공하면 사로잡은 영혼과 루비를 미네라에게 가지고 가게.", progress = "자, <name>? 선택했나요? 지옥불정령인가요, 지옥사냥개인가요?\n\n각각의 선택은 당신의 강점과 약점을 반영합니다. 사실 <class>가 약점을 보완하는 대신 강점을 살리는 경우도 상당하죠. 때로는 적을 압도하는 힘이 균형 잡힌 마법이라기보다는 강력한 그 무엇을 강조한 전술이 될 수 있거든요.", completion = "오, 지옥사냥개의 영혼이군요. 잘했어요, &lt;name&gt;.\n\n정화된 보주와 영혼, 둘 다 있으면 합쳐주겠지만, 그 전까지는 안 돼요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4963] = {title = "지옥불정령의 영혼", objective = "지옥불 에메랄드를 가지고 가서 잊혀진 땅의 지옥불정령 중 하나에게 사용해 영혼을 사로 잡아야 합니다. 성공하면 지옥불 에메랄드와 사로잡은 지옥불정령의 영혼을 불모의 땅에 있는 미네라에게 가져가야 합니다.", description = "흐음, 지옥불정령의 영혼을 잡기로 결정한 거군. 좋아.\n\n이 에메랄드를 가지고 가게. 이게 있으면 놈의 영혼을 사로잡을 수 있네. 이건 자네가 이미 알고 있는 방식으로 사용하면 되지. 먼저 녀석을 거의 초주검 상태로 몰아넣은 다음 그걸 쓰게. 그럼 나머지는 에메랄드가 알아서 해줄 거야.\n\n잊혀진 땅으로 가서 지옥불정령 하나를 찾아서 써보는 게 좋을 거야.\n\n성공하면 사로잡은 영혼과 에메랄드를 미네라에게 가지고 가게.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4964] = {title = "완성된 다르오라힐의 보주", objective = "미네라 보이드렌더가 다르오라힐의 보주를 완성시킬 때까지 기다렸다가 그녀에게 말을 걸어야 합니다.", description = "이제부터 보주를 제련하고 거기에 당신의 새로운 악마를 깃들게 하는 작업을 시작하도록 하죠. 끝나면 당신은 지팡이와 보주 중 한 가지를 선택할 수 있어요. 항상 난 흑마법사에게 그가 선택한 무기를 제공하는 것이 중요하다고 생각해 왔어요. 이번에도 다를 것은 없겠죠.", progress = nil, completion = "이제 끝났어요, &lt;name&gt;. 둘 중에 어떤 쪽이 좋은지 말해줘요. 두 손으로 사용해야 하는 지팡이가 좋아요, 아니면 단검이나 검을 함께 쓸 수 있는 보주가 좋아요?\n\n지옥사냥개를 잡는 데 노고가 컸으니 마땅히 받으셔야죠. 그 물건이 앞으로의 여정에 큰 도움이 되리라 믿어요. 계속 정진하세요, &lt;name&gt;. 당신의 무용담을 기다리고 있을 테니까.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n다르오라힐의 수정구다르오라힐의 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4965] = {title = "오라힐 보주의 지혜", objective = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", description = "좋아... 아주 좋아요! 꾸준히 강해지는 모습이 마음에 드는군요. <name>, 당신이 불모의 땅에 있는 미네라 보이드렌더의 앞에 설 준비가 되었다는 것에 제 전 재산을 걸어도 좋아요. 아직 그녀와 대화한 적이 없다면... 제가 보장하죠. 그녀는 보주를 만드는 데 가히 당대 최고의 실력자라고 불릴만해요! 그녀의 보주는 악마라도 부릴 정도로 강력하거든요.\n\n관심이 있다면 불모의 땅 톱니항 위쪽에 있는 스트라드의 탑으로 가보세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4966] = {title = "카나티 그레이클라우드 보호", objective = "켄타우로스의 공격으로부터 카나티 그레이클라우드를 보호해야 합니다.", description = "하지만 녀석들의 수가 내가 생각했던 것보단 많을지도 모르겠군. 부탁이니 <name>, 이 사악한 암살자들을 물리칠 수 있도록 도와주게.", progress = nil, completion = "도와줘서 고맙네, &lt;name&gt;. 당신이 없었다면 녀석들을 물리치지 못했을 거야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n낮은굽 장화모래조각 팔보호구사막횡단 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4967] = {title = "오라힐 보주의 지혜", objective = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", description = "아직도 인간들이 만든 조잡한 물건이나 찾아 헤매다니, 어리석은 것들! 그토록 우매한 행동을 보고 내가 어찌 웃지 않을 수 있겠소? 참으로 애처롭소!\n\n사실 이것은 내 생각이 아니라 당신이 만나게 될 분들의 생각이라오. 힘이 있는 그분들은 당신이 더 큰 것을 가질 권리가 있다고 느끼는 모양이오.\n\n원한다면 톱니항 위쪽의 탑에서 미네라 보이드렌더를 만나보시오. 아마 전에 한번쯤 만난 적이 있을 거라 생각하는데...다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4968] = {title = "오라힐 보주의 지혜", objective = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", description = "호오, 여기까지 오다니... 정말 놀랍군그래. 마나의 균열이 당신의 영혼까지 스며들어 지금쯤 미쳐버렸을 것이라 생각했었는데 말이오. 그렇다면, 좀 더 세게 나가 보는 건 어떻소?\n\n당신의 힘을 시험해보고 싶다면 톱니항 위쪽에 있는 스트라드의 탑에서 미네라 보이드렌더를 찾아보시오. 그녀가 도와 줄 거요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4969] = {title = "오라힐 보주의 지혜", objective = "불모의 땅에 있는 미네라 보이드렌더와 대화하십시오.", description = "하하하! 혼자서도 아주 잘하고 있는 젊은 <class>|1이여;여;...\n\n시간이 흐른 뒤엔 지옥불정령과 공포의 군주까지 모두 자네 앞에 무릎을 꿇을 것이야.\n\n허나 그때가 오기 전엔 현세의 종족들이 만든 무기에 의존해야겠지.\n\n새로운 무기를 찾는 모양인데, 내킨다면 미네라 보이드렌더를 찾아가 보는 것은 어떤가? 그녀는 톱니항을 내려다보고 있는 스트라드의 탑 근처에 있다네. 준비가 되면 그쪽으로 가보게나.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4970] = {title = "눈호랑이의 먹이", objective = "톱니이빨곰 고기 5개와 서리바람 키메라 고기 5개를 여명의 설원에 있는 리베른 프로스트윈드에게 갖다주어야 합니다.", description = "스스로 실력을 증명하고 싶나? 간단한 일부터 시작하세. 쉽게 처리할 수 있지만 아주 중요한 일이야.\n\n이 지역에 사는 톱니이빨곰과 키메라 고기를 모아 오게. 지금 조련하고 있는 눈호랑이의 먹이가 필요하네.", progress = "현재 자네가 목표로 삼아야 할 것은 훈련을 통해 의지와 인내를 배우는 거지. 이 임무를 여러 번 맡길 수도 있는데, 그때마다 최선을 다하기 바라네.", completion = "도와줘서 고맙네, &lt;name&gt;. 시간이 지날수록 자네를 높이 평가하게 되는 걸.", rewards = nil},
[4971] = {title = "시간 문제", objective = "안돌할 저장고 근처에서 시간의 재배열기를 이용해 시간의 기생충들을 찾아내십시오.\n\n시간의 기생충 15마리를 처치한 후, 서부 역병지대의 안돌할 여관에 있는 크로미에게 시간의 재배열기를 가져가야 합니다.", description = "안돌할에서 어떤 사악한 세력이 시간을 조작하고 있어요! 아마도 스컬지일 거예요. 내가 이곳에서 시간의 흐름을 유지하면서 손상된 부분을 고칠 수는 있겠지만 방해를 받지 않고 작업하려면 당신의 도움이 필요해요.\n\n안돌할의 저장고에는 변경된 시간의 흐름을 먹고 사는 시간의 기생충이 들끓고 있어요. 푸른 파장이 시간의 기생충들을 알아볼 수 있는 표시랍니다. 녀석들이 내 의식을 더디게 만들고 있으니 시간의 재배열기로 그 해충들을 제거해 주세요.", progress = "시간의 기생충은 시간의 흐름을 조작할 때마다 생기는 흔한 부작용이에요. 근데 여러 마리가 있는 게 느껴져 걱정이 되는군요.\n\n녀석들을 찾아내 제거하면 쇠퇴해가는 시간의 흐름을 회복하는 데 도움이 될 겁니다. 시간의 흐름이 회복되면 내가 그걸 느낄 수 있을 거예요.", completion = "시간을 회복하는 일이 훨씬 수월해졌어요. 고마워요. 당신은 시간의 흐름에 금이 가면 그 결과가 어떤 것인지 정확히 이해하지는 못하겠지만, 이번 상황의 위급함을 생각해 볼수록 스컬지의 소행이라고 여겨지는 사태를 수습해줘서 정말 고마워요.\n\n도와준 데 대한 보답을 하는 게 좋겠네요. 당신은 앞으로 더욱 위대한 업적을 이룰 것이니 조그마한 보상을 해 준다 해도 당신의 미래는 바뀌지 않을 것입니다. 하지만 나와 용군단은 계속해서 당신의 도움을 받았으면 합니다...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n연보랏빛 아미스황금 고리 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4972] = {title = "시간을 거슬러", objective = "안돌할 도시의 폐허에서 안돌할 시계 5개를 찾아 서부 역병지대의 안돌할 여관에 있는 크로미에게 가져가야 합니다.", description = "다시 한번 저 밖의 세계로 가 주세요. 자세히 설명해 주도록 하지요.\n\n당신은 이 방이 안돌할의 다른 곳과 다르다는 것을 알 겁니다. 내 용군단은 여러 시간 차원에서 여러 가지 방법으로 임무를 수행하고 있지요. 나도 안돌할의 피해를 수습하기 위해서 다른 시간 차원에서 이동하여 안돌할을 지나치게 오염시키지 않으려고 합니다. 하지만 계속해서 피해를 수습하려면 역병이 들이닥쳤을 때부터 멈춘 시간의 장식품이 필요합니다. 안돌할의 폐허에서 찾을 수 있는 잠긴 상자에서 이 시간의 장식품들을 찾아서 내게 가져오세요.", progress = "내가 찾는 시간의 장식품은 단순한 장치랍니다. 주로 시계인데, 안돌할에 처음 역병이 들이닥쳤을 때 시계 침이 멎어버린 것들이지요.\n\n시간은 결코 멈추지 않고, 당신이 가져오는 시계들은 모두 제 집으로 되돌아가게 될 겁니다. 물론 이곳의 소동이 계속된다면 말이지만...", completion = "내게 딱 필요한 것들이로군요. 고맙습니다.\n\n이것으로 당신의 수고에 답례를 하도록 하죠. 당신은 이것이 어디에 쓰는 장치인지도 잘 모르고 이 장치의 정체조차 모를 겁니다. 안타깝게도 난 어떤 곳에 가장 유용하게 쓰일지는 말해줄 수가 없네요. 언젠가 미래에 이 장치를 아주 유용하게 사용하리라는 사실만 알뿐이에요. 그때까지 이 장치를 계속 지니고 있을지는 당신의 자유입니다, 내 친구여.", rewards = "다음과 같은 것들을 받습니다:\n\n특수 약화장치"},
[4973] = {title = "시간을 거슬러", objective = "안돌할 도시의 폐허에서 안돌할 시계 5개를 찾아 서부 역병지대의 안돌할 여관에 있는 크로미에게 가져가야 합니다.", description = "음, 한번 더 당신의 도움이 필요해요. 이곳에서 시간 차원을 조작하는 세력에 대항해 의식을 행하는 동안 당신이 안돌할 폐허에서 시계를 더 가지고 오세요. 그 대가로 미래에 유용하게 쓸 물건을 하나 더 드리도록 하죠!", progress = "안돌할의 시계들은 마을회관 폐허의 큰 시계와 마찬가지로 모두 3시에 멈춰 있어요. 바로 안돌할에 처음 역병의 효과가 완전히 퍼져 도시의 생명을 쥐어짜던 때이죠.\n\n그때 일어난 일이 아무리 안타까워도 그때의 사건이 지금 당신이 느끼는 시간의 흐름을 형성한 것이랍니다. 우리 청동용군단은 시간의 차원을 보호하는 데 전력을 쏟아야만 한답니다!", completion = "도와줘서 정말 고맙습니다. 이 선물을 받아주세요. 이 물건을 어디에 쓰는지 아직 모를지도 모르지만 미래에 시간의 길이 이 물건의 진정한 목적을 드러내 줄지도 모르겠군요. 내가 당신에게 그러한 일이 일어나는 것을 보았다고 해도 좋겠지요.", rewards = "다음과 같은 것들을 받습니다:\n\n특수 약화장치"},
[4974] = {title = "호드를 위하여!", objective = "검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다.", description = "렌드가 감히 검은용군단의 힘만 믿고 엄청난 짓을 꾸미고 있군.\n\n가서 승천의 전당에 이르는 길을 찾도록 하라. 그리고 호드의 이름으로 대족장 렌드 블랙핸드를 찾아내 처치하도록!\n\n<주먹으로 왕좌를 내리치는 스랄>\n\n이곳으로 돌아올 때는 반드시 내게 놈을 처치한 증거를 가져와야 한다. 그대는 호드의 영웅이 되리라.", progress = "<호통치는 스랄>", completion = "그대는 검은바위부족의 군대에 치명적인 피해를 주었다. 대족장을 처치했으니 검은바위부족 군대는 다시 혼란에 빠질 것이다.\n\n그대는 영웅적인 공훈을 세워 칼림도어의 백성에게 큰 영광을 안겨주었다!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n폭정의 징표괴수의 눈블랙핸드의 팔찌\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4975] = {title = "완성된 노오라힐의 보주", objective = "미네라 보이드렌더가 노오라힐의 보주를 완성하길 기다렸다가 그녀에게 말을 걸어야 합니다.", description = "이제부터 보주의 제련하고 거기에 당신의 새로운 악마를 깃들게 하는 작업을 시작하도록 하죠. 끝나면 당신은 지팡이와 보주 중 한 가지를 선택할 수 있어요. 난 항상 흑마법사에게 자신이 원하는 무기를 제공하는 것이 중요하다고 생각해 왔어요. 이번에도 다를 것은 없겠죠.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n노오라힐의 수정구노오라힐의 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4976] = {title = "정화의 보주 가져가기", objective = "정화된 지옥의 보주를 불모의 땅의 미네라에게 가져가야 합니다.", description = "정화된 보주를 톱니항의 미네라에게 돌려주세요, <name>. 가시는 길 조심하시고 그녀에게 안부도 좀 전해주세요. 당신에게 닥칠 유혹과 타락을 잘 이겨낼 수 있기를 진심으로 바랍니다.\n\n행운을 빌어요.", progress = "타베사와 보주를 찾는 일은 잘되었나요, <name>?\n\n타베사는 신비로운 힘에 관해서라면 상당한 조력자가 되어왔죠. 그녀를 찾을 수 있었다면 당신에게도 분명 큰 도움을 주었을 거라 생각해요.", completion = "잘했어요, &lt;name&gt;. 이 정도면 충분할 거예요.\n\n이제 남은 일은 내가 정화된 보주에서 어떤 악마를 풀어줄지 당신이 결정하는 것만 남았네요. 그렇게 하면 당신은 꽤나 훌륭한 물건을 얻을 수 있을 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4981] = {title = "요원 비쥬", objective = "검은바위 첨탑으로 가서 비쥬에게 무슨 일이 생겼는지 알아봐야 합니다.", description = "고블린을 믿지 말게. 고블린을 믿는다는 건 몰락의 지름길이야.\n\n우리의 사고뭉치 요원 중 한 명의 이름은 비쥬라네. 난 그녀가 불타는 평원 출신의 희귀종 애완 동물 암거래상인 키블러의 사주를 받아 일하고 있었다는 것을 알아냈네. 말하자면 우리를 배신했을 뿐만 아니라 그녀는 자기 활동 자금으로 호드의 공금을 빼돌리고 있었다네.\n\n그녀를 생포해서 여기로 데려오게. 그녀는 검은바위 첨탑으로 들어가는 모습을 끝으로 종적을 감추었다네. 첨탑으로 가서 그녀를 찾아서 데려오게.\n\n그리고 말이네. 그녀의 사탕발림에 넘어가지 말게나.", progress = nil, completion = "거짓말은 하지 않겠어요, &lt;race&gt; 친구. 난 돈이 필요했다고요! 키블러는 보수를 정말 정말 후하게 준다고요, 카르가스 원정대보다 훨씬 많이요!\n\n하지만 내 충성심을 의심하진 마세요! 내가 왜 여기까지 온 것 같죠? 그 미치광이 고블린에게 희귀종 애완 동물의 알들을 찾아다 바치는 것과 같이 어리석은 짓을 하고 있는 것 같나요? 틀렸어요, 진짜 바보들이나 여기 검은바위 첨탑까지 와서 애완 동물들을 수집해갈 뿐이죠. 엄, 굳이 그 많은 수의 사람들의 이름을 대고 싶진 않아요.\n\n\n\n우리에게 정말로 필요한 것은 그런 자들이 많아지는 거죠.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4982] = {title = "비쥬의 물건들", objective = "비쥬의 소지품을 찾아서 그녀에게 돌아가야 합니다. 비쥬가 도시의 바닥에 소지품을 숨겼다고 했습니다.", description = "경계가 느슨해지는 밤이면 나는 도시 곳곳을 몰래 돌아다녀요. 카르가스 원정대에게 전략적인 가치가 있을만한 요소들에 대해 적으면서 말이죠. \n\n그런데 어젯밤은 정말 무서웠어요. 올가미 철사를 넘어가다가 경보 장치가 울리고 만 거예요. 난 수색용품들을 묻고 냅다 달렸죠! 운이 없게도 내 물건들을 가지러 돌아갈 수가 없어요. 경계가 두 배, 세 배로 강화되었거든요! 내가 모은 모든 정보들을 잃어버린 거예요.\n\n내 물건들을 찾아다주면 카르가스 원정대로 얌전히 돌아갈게요.", progress = "내 소지품은 찾았나요?", completion = "해냈군요! 렉스로트가 이것들을 본다면 내게 내리려고 했던 벌들을 거둘 거예요.\n\n오, 당신은 내 구세주에요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[4983] = {title = "비쥬의 정찰 보고", objective = "비쥬의 정찰 보고서를 가지고 카르가스의 렉스로트에게 가야 합니다.", description = "이 보고서를 렉스로트에게 가져다주세요. 이걸로 나도 오명을 씻을 수 있을 테고, 카르가스 원정대에게도 그 오크들을 상대로 큰 전략적인 우위를 점할 수 있을 거예요.\n\n따라오라고요? 오, 난 아직 너무 할 일이 많아요. 어서 가요, 그들에게 가능한 한 빨리 이 보고서를 전달해야만 해요!", progress = "그 고블린은 어디 있나?", completion = "흠, 그녀를 믿을 수밖에 없겠군. 이번에도 비쥬는 목을 죄오는 악조건에서 무사히 빠져나가는군. 이 정찰 보고서는 우리가 검은바위부족의 오크들을 상대하는 데 있어 아주 귀중한 가치를 갖고 있다네.\n\n물론 자네도 힘든 일에 대한 보상을 받을 것이야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n높새바람 장갑바다말뚝 허리띠\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[4984] = {title = "야생 동물들의 고통", objective = "역병에 걸린 늑대 8마리를 처치한 후, 서부 역병지대의 고통의 흉가에 있는 멀그리스 딥리버에게 돌아가야 합니다.", description = "난 혼자서는 스컬지를 물리칠 수 없었지만, 이곳으로 와서 자연이 입은 피해를 치유하려고 하네. 계속해서 이 대지의 목을 조르는 역병 때문에 짐승들이 고통을 겪으며 안식을 찾지 못하고 있네. 내가 여기서 하던 일을 자네가 마저 끝내 주게나.\n\n고통에 시달리는 이 짐승들을 구제할 방법은 자비로운 해방뿐일세. 근처에 있는 역병에 걸린 늑대를 찾아 처치해 주게나. 제발 그들의 고통을 끝내 주게. 그러면 내 마음이 편해질 것이야.", progress = nil, completion = "자네가 처치한 늑대들의 영혼이 안식을 찾은 것이 느껴지는군. 그 늑대들을 대신해 감사의 마음을 전하네.\n\n이 저주받은 땅에서 고통을 겪는 것은 그 늑대들뿐만이 아니라네. 다시 한번 자네의 도움이 필요하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4985] = {title = "야생 동물들의 고통", objective = "오염된 불곰 8마리를 처치한 후, 서부 역병지대의 고통의 흉가에 있는 멀그리스 딥리버에게 돌아가야 합니다.", description = "여기서 동쪽으로 가면 동부 역병지대가 시작되는 곳이 있는데, 그 근처에서는 한때 당당하고 위엄있던 불곰들이 길가를 돌아다니곤 했지. 이 짐승들도 스컬지가 풀어놓은 역병에 걸려버리고 말았던 것일세. 이제 그들은 굳어 가는 근육과 썩어 가는 털과 살 때문에 고통을 받으며 괴로워하고 있다네.\n\n그들의 고통도 끝내주시게. 그들의 고통에 대한 유일한 치유법은 빨리 죽여주는 것뿐이네. 자네의 손으로 직접 치유해 주게.", progress = nil, completion = "\"불곰들을 처치해 그들의 고통을 끝내 주었군. 따... 딱 한 가지만 더 부탁하겠네. 이 세계에서의 내 시간이 다한 것을 느껴 이 가... 가지에 적어 두었네.\n\n진정... 내 시간이 다했군. 다시 한번 고맙네, 친구... 이 저주받은 땅의 생물들이 안식을 취하게 되었으니... 나도 안식을 취하겠군.\"\n\n그 말을 남기고 드루이드는 숨을 크게 내쉬더니 가래 끓는 소리를 냅니다. 오두막 바닥에 그의 몸이 꼼짝도 하지 않고 누워 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[4986] = {title = "문자가 새겨진 떡갈나무 가지", objective = "문자가 새겨진 떡갈나무 가지에 걸린 문자로 미루어볼 때 타우렌 드루이드가 이 가지를 가져가려고 한 장소는 다르나서스에 있는 세나리온 의회입니다. 그곳에서 드루이드를 한 명 찾아 도움을 요청하십시오.", description = "숨을 거둔 타우렌 드루이드의 손에는 놀랍도록 싱싱한 떡갈나무 가지가 들려 있습니다. 가지를 조사해 보니 껍질에 드루이드 문자 같은 것이 새겨져 있는 것을 알 수 있습니다.\n\n가지를 집어들자 이상할 정도로 따뜻한 것이 느껴집니다. 텔드랏실의 형상이 머릿속에 펼쳐지면서, 다르나서스가 보이고 입에서는 \"세나리온 의회\"라는 말이 나오려고 합니다. 이 가지를 가져가야 할 장소에 대한 내용이 담겨 있는 모양입니다.", progress = "세나리온 의회를 대신해 자치령에 오신 것을 환영합니다. 무슨 용건이신지요?", completion = "음...이 드루이드란 자가, 그것도 타우렌 드루이드가 스컬지의 역병에 대한 귀중한 정보를 당신에게 맡겼다니 참 이상하군요. 타우렌이 우리 얼라이언스의 일원에게 그런 정보를 선뜻 줬다니 놀랐습니다. 저희 세나리온 의회에서 이 정보를 소중히 보관하겠다고 약속드리겠습니다. 어쩌면 타우렌족은 판드랄님께서 생각하는 것처럼 심하게 타락하지 않은 것일지도 모르겠군요...\n\n어... 어쨌거나, 세나리온 의회에서 드리는 이 감사의 표시를 받아 주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n진홍색 외투"},
[4987] = {title = "문자가 새겨진 떡갈나무 가지", objective = "문자가 새겨진 떡갈나무 가지에 걸린 문자로 미루어볼 때 타우렌 드루이드가 이 가지를 가져가려고 한 장소는 썬더 블러프에 있는 세나리온 의회입니다. 그곳에서 드루이드를 한 명 찾아 도움을 받도록 하십시오.", description = "숨을 거둔 타우렌 드루이드의 손에는 놀랍도록 싱싱한 떡갈나무 가지가 들려 있습니다. 가지를 조사해 보니 껍질에 드루이드 문자 같은 것이 새겨져 있는 것을 알 수 있습니다.\n\n가지를 집어들자 이상할 정도로 따뜻한 것이 느껴집니다. 멀고어에 있는 썬더 블러프의 형상이 머릿속에 펼쳐지면서, 장로의 봉우리가 보이고 입에서는 \"세나리온 의회\"라는 말이 나오려고 합니다. 이 가지를 가져갈 장소에 대한 내용이 담겨 있는 모양입니다.", progress = "세나리온 의회를 대신해 자치령에 오신 것을 환영합니다. 무슨 용건이신지요?", completion = "멀그리스가 준 것이라고요? 그 사람이 역병지대에 고통을 받고 있는 생물들을 보살피려 했다는 소식은 들었지만 이건 의외로군요... 그리고 아주 슬픈 일이네요. 멀그리스는... 아주 좋은 벗이었습니다. 저는 그의 죽음을 깊이 애도할 겁니다.\n\n당신의 부지런함 덕분에 그의 노고는 헛되지 않았군요. 이 가지에는 스컬지가 이 땅에 퍼뜨리는 역병에 대한 많은 지식이 담겨 있어요. 저희 세나리온 의회에서 부지런히 조사하도록 하겠습니다. 부디 이걸 받아 주세요. 당신의 수고에 대해서 저희가 할 수 있는 최소한의 보답입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n진홍색 외투"},
[5001] = {title = "비쥬의 소지품", objective = "비쥬의 소지품을 찾아 그녀에게 돌려줘야 합니다!", description = "난 보통 당신과 같은 <race>들과는 거래를 하지 않지만 지금 난 트롤에 둘러싸인데다가 높은 곳에 있으니 이번엔 어쩔 수 없군요. 여기에서 내 임무는 호드를 위한 가장 중요한 임무 중 하나에요. 근데 내가 수집한 정보는 얼라이언스의 안위에 대한 것이랍니다. 그렇다고 내가 얼라이언스의 추종자는 아니라고요. 그렇지만 역시 검은바위 일족의 위협은 그저 수많은 오크들의 위협과는 비교가 안 된다고요.\n\n내 물건을 찾는 것을 도와 주면 나 역시 당신과 같은 사람에게 도움이 될 만한 정보로 보답하죠.\n\n그렇게 하실래요?", progress = "내 물건은 찾았나요?", completion = "좋아요! 그것들이 어디 있었던거죠??", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5002] = {title = "멕스웰에게의 전보", objective = "불타는 평원에 있는 치안대장 맥스웰에게 비쥬의 정보를 전해야 합니다.", description = "나는 내가 한 말에 책임을 지는 고블린이에요, <race>. 잘 들어요.\n\n이 오크들은 그저 짐만 되는 존재이고 검은용군단의 희생물일 뿐이에요!\n\n그들의 진정한 우두머리는 데스윙의 피를 이어받은 네파리안이라고 할 수 있죠. 또한 첨탑에 머물고 있는 그의 직속 부하들이 어디 있는지도 발견했어요.\n\n이 지도를 불타는 평원의 맥스웰 치안대장에게 전해주세요. 그 녀석들의 위치를 알아보기 쉽게 표시해두었어요.", progress = "오오, 당신이로군. 오랜만이오.", completion = "이 정보는 우리가 알던 것과 일치하는 부분이 많군. 이 지도는 의심할 여지 없이 흥미로운 정보인 동시에 만만찮게 나쁜 소식이기도 하오.\n\n지도에 표시되어 있는 곳은 검은바위부족의 횡포를 방해하는데 대단히 유용할 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5021] = {title = "늦어버린 소포 배달", objective = "유령 여인의 두서없는 말을 들으니 소포를 전달해야 했던 것 같습니다. 자신의 말이 있던 곳에 소포가 있다고 했는데, 말이 어디 있는지, 그리고 소포를 어디로 전달해야 하는지에 대해서는 이해할 수 없는 말만 늘어놓습니다.", description = "\"소포를 반드시 전해야만 해... 내가 여기 갇히기 전에 전해야 해!\"\n\n당황해 어쩔 줄 모르는 여자의 한탄이 마치 속삭임처럼 집 안의 허공을 떠돕니다. 위층의 구석에는 여자 유령이 있는데 자신의 주변 환경을 정확히 인식하지 못하는 듯하고 당신만을 어렴풋이 인식하고 있습니다.\n\n\"제 소포를 전달하러 오셨나요? 사태가 악화되기 전에 부디 갖다주세요! 전 말을 타고 떠나려고 했으니까 소포를 제 말 옆에 두었을 거예요... 아니면 이미 늦어버린 건가요?\"", progress = nil, completion = "외양간에서 온갖 쓰레기에 묻혀 이전에는 그냥 무심코 지나쳤을 소포가 눈에 띕니다. 이게 바로 재니스 펠스톤의 유령이 언급했던 소포일지도 모릅니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5022] = {title = "늦어버린 소포 배달", objective = "스톰윈드의 왕실 조사원과 대화하여 엠마 펠스톤의 행방을 알아내십시오. 인구조사국 담당자는 보통 스톰윈드 시청에 있습니다.", description = "소포를 들고 그 위에 내려앉은 먼지와 때를 털어냅니다. 급하게 적은 수취인 주소에는 스톰윈드의 엠마 펠스톤이라는 이름이 있습니다. 이 소포를 보낸 날짜는 이미 4년 전입니다.\n\n엠마 펠스톤이 살아있는지 확실치 않지만 스톰윈드 시청에서 주민들에 대한 기록을 보관한다고 알려져 있습니다. 인구 기록은 스톰윈드 인구조사국의 왕실조사원들이 담당하고 있습니다.", progress = "스톰윈드 인구조사국에 오신 걸 환영합니다. 스톰윈드의 인구 기록 정보가 필요하시면 제가 도와드리도록 하겠습니다.", completion = "엠마 펠스톤에게 보낸 소포라고 하셨습니까? 4년 전 마지막 주소가 스톰윈드라고요? 어디 한번 보지요...\n\n우리 기록에 의하면 4년 전에 엠마 펠스톤이라는 여성이 스톰윈드에서 살았군요. 제가 보고 있는 기록은 5년 전 것이라 확실하지는 않지만 도시를 떠난 기록은 없습니다. 그렇다고 해서 엠마 펠스톤이 반드시 이곳에 있다는 뜻은 아닙니다.\n\n잠깐... 혹시 이 소포가 올엠마의 것은 아닐까요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5023] = {title = "늦어버린 소포 배달", objective = "언더시티의 왕실감독원과 대화하여 제레미어 펠스톤의 행방을 알아내십시오. 인구조사국 담당자는 보통 길드 사무소 근처에 있습니다.", description = "소포를 들고 내려앉은 먼지와 때를 털어냅니다. 급하게 적은 수취인 주소에는 로데론의 제레미어 펠스톤이라는 이름이 있습니다. 이 소포를 보낸 날짜는 이미 4년 전입니다.\n\n제레미어 펠스톤이 살아있는지는 확실치 않지만 이전에 로데론이었던 언더시티에서는 주민들에 대한 기록을 보관한다고 알려져 있습니다. 인구 기록은 언더시티 인구조사국의 왕실감독원들이 담당하고 있습니다.", progress = "언더시티 인구조사국의 도움이 필요한 건가 아니면 아는 친구가 죽었는지 알고 싶은 건가? 난 그런 질문을 무척 많이 받지.", completion = "제레미어 펠스톤이라는 자에게 보내는 소포란 말인가? 마지막 주소가 로데론이었다라... 내가 도와줄 수 있겠군그래.\n\n제레미어 펠스톤은 로데론에 역병이 퍼지기 전에 살았군. 그러니까 전 제레미어 펠스톤이라고 해야 하나... 어떤 포세이큰은 살았을 때의 모습을 없애기 위해 성을 바꾸기도 했으니 말이야. 이 경우도 예외는 아닌 것 같군. 전 제레미어 펠스톤은 이제 제레미어 페이슨으로 이름을 변경했네.\n\n가만... 그 친구는 바퀴벌레 상인일 텐데?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5041] = {title = "크로스로드의 보급품", objective = "크로스로드 보급품 상자를 찾아서 불모의 땅의 톨크에게 가져가 주어야 합니다.", description = "우리가 절실하게 필요로 하는 보급품들을 싣고 있던 운반차가 습격 당했다네.\n\n이제껏 자네는 용맹하게 서슬갈기일족과 맞서왔지. 그래서 말인데, 이번에도 비슷한 일을 맡아 주었으면 하네. 다만 잃어버린 물자를 찾는데 집중해달라고 부탁하고 싶군. 그들의 진영 내 어딘가에서 찾을 수 있을거야.\n\n크로스로드의 주민들은 자네에게 큰 빚을 지게 될 걸세.", progress = "보급품 수색은 어떻게 진행되고 있나, <name>? 자네의 힘이라면 가시멧돼지들은 여지없이 나가떨어질 거라고 믿네.", completion = "하하하! 고맙네, &lt;name&gt;! 이것은 우리에게 큰 도움이 될 거야. 자네는 크로스로드 주민 모두, 아니 호드 전체의 은인일세. 만약 내가 자네를 위해 해줄 수 있는 일이 있다면 주저하지 말고 말해보게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5042] = {title = "아감마간의 힘", objective = "아감마간의 힘을 얻으려면 4개의 혈석 파편이 필요하네, <race>. 자네를 보면 적들이 두려움에 벌벌 떨게 될 걸. \n\n서슬갈기일족의 용맹한 전사들은 모두 이런 힘을 가지고 있지!", description = nil, progress = "아감마간의 힘을 얻으려면 4개의 혈석 파편이 필요하네, <race>. 자네를 보면 적들이 두려움에 벌벌 떨게 될 걸. \n\n서슬갈기일족의 용맹한 전사들은 모두 이런 힘을 가지고 있지!", completion = "이 뻐드렁니... 당신이 배신자들을 처단하는 것을 지켜볼 수만 있다면! &lt;킁&gt;\n\n혈석들을 모으면서 뾰족털일족들도 처치해줘서 고맙네. 앞으로도 부탁해. 그럼 나도 계속 도와 주지. &lt;킁킁&gt;", rewards = "다음과 같은 것들을 배웁니다:\n\n아감마간의 힘"},
[5043] = {title = "아감마간의 민첩성", objective = "우리 일족 정찰병들의 화살 솜씨는 그 누구도 따를 자가 없다고 정평이 나 있지. <킁킁> 우리 도적들 또한 전장에서 내로라할 만큼 몸놀림이 빠르지.\n\n혈석 4개를 내게 가져오면 자네를 어떤 가시멧돼지보다 더 민첩하게 만들어주지.", description = nil, progress = "우리 일족 정찰병들의 화살 솜씨는 그 누구도 따를 자가 없다고 정평이 나 있지. <킁킁> 우리 도적들 또한 전장에서 내로라할 만큼 몸놀림이 빠르지.\n\n혈석 4개를 내게 가져오면 자네를 어떤 가시멧돼지보다 더 민첩하게 만들어주지.", completion = "이제 어떤 적도 자네의 빠른 화살과 검을 피할 수 없을 걸.\n\n아감마간님의 영혼이 자네와 함께하고 있으니. &lt;킁&gt; 원한다면 언제든지 내게 오게. 위대한 가시멧돼지 신께서 이 뻐드렁니를 버리지 않으신다면 자네에게 축복이 내릴 거야. &lt;킁킁&gt;", rewards = "다음과 같은 것들을 배웁니다:\n\n아감마간의 민첩성"},
[5044] = {title = "아감마간의 지혜", objective = "우리 가시멧돼지 주술사나 풍수사들은 <킁킁> 전투에서 아감마간님의 힘을 빌린다네, <race>.\n\n아감마간님의 축복을 입어 마법의 위력을 높이고자 한다면 혈석 4개를 가져오게. 그러면 이 뻐드렁니가 도와 주지.", description = nil, progress = "우리 가시멧돼지 주술사나 풍수사들은 <킁킁> 전투에서 아감마간님의 힘을 빌린다네, <race>.\n\n아감마간님의 축복을 입어 마법의 위력을 높이고자 한다면 혈석 4개를 가져오게. 그러면 이 뻐드렁니가 도와 주지.", completion = "적들이 자네를 보면 두려움에 몸서리를 칠 걸, &lt;race&gt;. \n\n다음에 만날 때는 전투에서 자네의 영리한 머리로 짜낸 교묘한 작전과 무용담을 이 뻐드렁니에게 들려주게나.  현생에서든, 다음 생에서든...", rewards = "다음과 같은 것들을 배웁니다:\n\n아감마간의 지혜"},
[5045] = {title = "정신력 상승", objective = "모든 <race>들은  강인한 정신력을 필요로 하지. 그래야 희망 없는 시기에 빛을 발할 수 있어. 우리 서슬갈기일족도 잘 알고 있는 사실이야.  우리는 영적인 부족이지. 사실 전투에서의 용맹함보다 아감마간님과 함께라는 사실에 더 큰 자부심을 느끼네. \n\n4개의 혈석을 가지고 오면, 전투에서 강인한 정신력을 잃지 않도록 자네의 영혼을 축복해주겠네.", description = nil, progress = "모든 <race>들은  강인한 정신력을 필요로 하지. 그래야 희망 없는 시기에 빛을 발할 수 있어. 우리 서슬갈기일족도 잘 알고 있는 사실이야.  우리는 영적인 부족이지. 사실 전투에서의 용맹함보다 아감마간님과 함께라는 사실에 더 큰 자부심을 느끼네. \n\n4개의 혈석을 가지고 오면, 전투에서 강인한 정신력을 잃지 않도록 자네의 영혼을 축복해주겠네.", completion = "우리 일족에서 가장 강한 전사도, 그리고 가장 위대한 &lt;class&gt;도 자네의 강한 의지를 흠모할 것이네.\n\n&lt;race&gt;! 뾰족털일족들을 격퇴하게! 이미 자네를 막지 못하리라는 것을 알고 벌벌 떨고 있다네.", rewards = "다음과 같은 것들을 배웁니다:\n\n정신력 상승"},
[5046] = {title = "서슬가죽", objective = "전투에 임하는 모든 자들은 <킁킁> 방어력을 갖추고 있어야 하네. 적이 내리칠 도끼를 막아내려면 뼈도, 살갗도 탄탄하고 두꺼워야 하지. <킁킁> 우리 일족도 이 사실을 잘 알고 있다네. 가죽과 털 외에 다른 무언가가 더 필요하다는 것을. <킁킁> 우리는 전쟁에 나가기 전 아감마간님으로부터 보호의 축복을 받곤 해.\n\n4개의 혈석을 가져오면 내 자네에게도 축복을 내려주지.", description = nil, progress = "전투에 임하는 모든 자들은 <킁킁> 방어력을 갖추고 있어야 하네. 적이 내리칠 도끼를 막아내려면 뼈도, 살갗도 탄탄하고 두꺼워야 하지. <킁킁> 우리 일족도 이 사실을 잘 알고 있다네. 가죽과 털 외에 다른 무언가가 더 필요하다는 것을. <킁킁> 우리는 전쟁에 나가기 전 아감마간님으로부터 보호의 축복을 받곤 해.\n\n4개의 혈석을 가져오면 내 자네에게도 축복을 내려주지.", completion = "가서 싸우게, &lt;race&gt;", rewards = "다음과 같은 것들을 배웁니다:\n\n서슬가죽"},
[5047] = {title = "핍 퀵윗, 명을 받듭니다!", objective = "눈망루 마을에 있는 말리퍼스 다크해머와 대화해야 합니다.", description = "눈망루 마을에 가시면 말이죠, 말리퍼스 다크해머를 찾으실 수 있을 거예요. 그에게 제 안부와 옷이 아주 잘 작동하고 있다고 전해주세요. 그리고 이걸 좀 전해 주실래요?\n\n<괴수의 살덩이를 건네 주는 핍>\n\n'휴가' 동안 괴수의 뱃속에서 이걸 훔쳐왔어요. 장담하건대 말리퍼스가 이런 것들로 뭘 할 수 있는지 보여줄 거예요!\n\n아, 혹시 눈망루 마을이 어디있는지 알고 계신가요? 바로 여명의 설원이랍니다! 그럼 안녕히 가세요.", progress = "무슨 일입니까?", completion = "핀클이 살아있다고요? 옷이 제대로 작동한 건가? 아, 당신은 무슨 일로 날 찾아왔나요?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5048] = {title = "착한 엠마", objective = "스톰윈드에서 올엠마를 찾아 그녀가 엠마 펠스톤인지 확인하십시오. 그녀가 정말 엠마 펠스톤이라면 재니스 펠스톤이 보낸 소포를 원할지도 모릅니다.", description = "그녀는 무척 고집이 세죠. 아마 미친 것 같아요... 하지만 올엠마라는 사람의 인상착의로 볼 때 엠마 펠스톤일 가능성이 큰 것 같군요.\n\n혹시 혼잣말을 하며 마을을 돌아다니는 올엠마를 본 적이 있는지 모르겠군요. 항상 알 수 없는 혼잣말을 중얼거리면서 다니죠. 그래도 다른 이들에게 해를 주지는 않기 때문에 마을 사람들은 그녀를 그냥 내버려 두고 있답니다.\n\n모든 정황으로 볼 때 전 그 올엠마가 엠마 펠스톤이라고 확신합니다. 그녀의 성이 펠스톤인지 직접 가서 물어보세요.", progress = "당신에게 잔디에서 나가라고 말하고 싶은데 보시다시피 난 잔디밭이 없군그래.", completion = "그래요. 내 이름이 엠마 펠스톤이에요. 지난 몇 년 동안 날그렇게 부른 사람은 없었는데... 당신은... 누구죠?\n\n내... 여동생을 안다고 했나요? 동생은 아직 살아 있나요? 이런, 내가 무슨 정신 나간 소리를 하는 거지. 걔가 살아있을 리가 없는데... 로데론에 역병이 퍼졌을 때 모든 희망을 버리게 되었어요. 가족들은 모두 죽어갔고... 난 이렇게 미친 올엠마로 혼자 살아가고 있어요. 당신은 대체 누구에요? 다음 범행 대상을 물색하는 도굴꾼인가요?\n\n뭐라고요? 동생이 내게 보내는 소포를 가져왔다고요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5049] = {title = "우울한 제레미어", objective = "언더시티에서 제레미어 페이슨을 찾아 그가 정말로 제레미어 펠스톤인지 확인하십시오. 그가 정말로 제레미어 펠스톤이라면 재니스 펠스톤이 보낸 소포를 원할지도 모릅니다.", description = "증거들을 보니 당신이 찾는 사람 즉, 이 소포의 주인이 누군지 알겠네. 바로 언더시티 바퀴벌레 상인, 제레미어 페이슨이야.\n\n난 그... 바퀴벌레로 장사를 하는 것도 아주 특별한 재주라고 늘 생각했지. 자네는 분명 어떤 역사의 중심에 서 있는 것일 테니 자네의 세상을 변화시키는 일을 하도록 해 주지. 하지만 자네의 대업적에 나도 일부가 되도록 제레미어가 어디 있는지 말해 주겠네. 제레미어는 은행 근처에 있는데, 그 사람답게 길바닥에서 구걸을 하고 있다네.", progress = "사람들이 바퀴벌레를 짓밟을 때마다 난 슬퍼집니다. 날 슬프게 하지 말아 주세요.", completion = "그 이름을 안 쓴지는 벌써 몇 년이나 지났지만... 그렇습니다. 이 언데드의 삶을 살기 이전, 내 살아 생전에는 펠스톤, 그게 내 성이었습니다.\n\n당신은 내 여동생을 알았다고, 아니, 최근에 내 여동생과 얘기를 나누었다고 주장을 하는데 말입니다. 내 여동생은 죽었습니다.\n\n4년 전에 말입니다. 내 뼈가 이렇게 상하지만 않았어도 발로 당신 엉덩이를 차 주고 싶은 심정입니다. 사기꾼 같은 친구로군요.\n\n뭐...? 내 여동생이 보낸 소포라고요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5050] = {title = "행운의 부적", objective = "서부 역병지대에 있는 재니스 펠스톤에게 행운의 부적 조각을 되돌려줘야 합니다.", description = "내가 사람을 잘못 본 것 같군요. 사과하겠습니다. 내 여동생이 우습게도 펠스톤 농장의 토지 소유문서를 포함한 개인 소지품 몇 가지를 보냈군요. 지금은 농장을 되찾는 일은 다음으로 미루는 게 좋겠습니다.\n\n내 여동생의 영혼이 농장에 구속되어 잠들지 못하다니... 부탁인데, 이걸 그 애에게 갖다주지 않겠어요? 이전에 동생이 지니고 있던 행운의 부적 조각인데, 다른 절반은 그 애 남편이 지니고 있답니다.\n\n이 물건을 내가 갖고 있다는 걸 알면 그 애의 영혼이 편히 쉴 수 있을 겁니다.", progress = "존. 여보... 당신인가요? 갑자기 추워졌어요...", completion = "부적 조각을 유령에게 건네주자 그 부적을 보고는 기대감이 가득한 눈빛으로 다시 올려다봅니다.\n\n\"여보. 다른 조각은 어디 있어요? 반쪽을 두 개 다 갖고 있지 않으면 다시 만날 수가 없어요. 여보... 제가 보이세요?\"", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5051] = {title = "두 개의 조각이 하나되어", objective = "서부 역병지대에 있는 펠스톤 농장에서 행운의 부적 목줄을 찾아 붙이십시오.\n\n서부 역병지대의 펠스톤 농장에 있는 재니스 펠스톤에게 행운의 부적을 가져가야 합니다.", description = "불쌍한 이 유령은 계속해서 두서없는 말을 늘어놓습니다.\n\n\"너무 추워요, 존. 당신 부적 조각도 갖고 오면 다시 만날 수 있을 거예요! 서둘러요, 존. 이 역병이 우리를 포악한 짐승으로 만들어버리기 전에! 당신이 보이지는 않지만 가까이에 있는 건 알아요. 당신이 가까이 있다는 게 느껴져요.\"\n\n재니스 펠스톤은 부적의 반대 조각을 찾아 다시 붙이기를 원하는 것 같습니다.", progress = "존. 구울을 조심하세요... 절 혼자 두지 마세요... 고약한 구울들... 부적만 있으면 안전할 거예요.", completion = "다시 붙인 행운의 부적을 재니스 펠스톤의 유령에게 건네줍니다. 부적을 거머쥐자 재니스가 금세 변합니다. 재니스의 유령 형태가 빛을 발하며 슬프지만 또렷한 눈으로 바라봅니다.\n\n\"나를 해방시켜 주었군요... 전 더 이상 이 부적이 필요 없어요. 자, 가지세요. 이 부적이 내게 준 평안함을 당신에게도 주기를 바랍니다. 안녕히...\"", rewards = "다음과 같은 것들을 받습니다:\n\n펠스톤 행운의 부적"},
[5052] = {title = "아감마간의 혈석 파편", objective = "불모의 땅의 타우라조 야영지에 있는 뻐드렁니에게 혈석을 가져가야 합니다.\n\n아감마간의 힘을 빌린 축복을 받고 싶다면 최대한 많이 수집해야 합니다.", description = "그분의 피는 <킁킁> 가시 덩굴처럼 이 땅에 많은 영향을 끼쳤어. 혈석은 다른 광물과 섞였지. 뾰족털일족은 그 파편들을 발굴해서 일종의 부적처럼 가지고 다녀. <킁킁> 그것을 토템으로 가지고 다니면 전장에서 힘이 솟고 마력도 올라간다는군.<킁킁>\n\n나는 그 물건의 비밀을 알고 있지.\n\n그게 뭔지 가르쳐줄 테니 그 조각 하나를 뻐드렁니에게 가져오게. 많이 가지고 온다면 이 뻐드렁니가 가시멧돼지의 신, 아감마간님의 마법으로 자네를 축복해주지! <킁킁>", progress = "우리 일족은 불모의 땅 전역에 걸쳐서 가시 덩굴이 우거진 장소에 모여 살아. <킁킁> 왜냐하면 우리에게는 성역이기 때문이지. 그중에서도 가시덤불을 가장 신성한 장소로 꼽는다네. 아감마간님의 성체로 만들어졌기 때문에 더더욱 중요하지. <킁킁> 그곳에서 경비가 가장 삼엄한 곳은, 가시덩굴 구릉이야. 입구가 아감마간님의 입으로 만들어졌지! <킁킁> 아감마간님께 충성하지 않는 자들을 삼키고 뼈를 뱉어낸다네! <킁킁> \n\n아감마간께서는 우리를 지키기 위해서 자신의 몸을 남기고 가셨네. 그리고 우리는 그분의 영혼을 수호하지. <킁킁>", completion = "내 말을 한 귀로 흘린 것은 &lt;킁&gt; 아니었군, &lt;race&gt;. 비록 이 뻐드렁니는 이렇게 가둬 놓을 수 있을지라도 아감마간님의 힘을 가둘 수는 없지! \n\n이 촉감, 이 느낌... 정말 오랜만이군.\n\n힘을 잃어버리는 것이 어떤 느낌인지 아나?\n\n뭐, 이건 나중에 얘기하지. 난 자네가 알고 싶어하는 정보와 아감마간님의 힘을 주기로 약속했네. 우리 일족이 뻐드렁니에게 등을 돌렸으니, 대신 자네라도 도와야겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5054] = {title = "톱니이빨곰 우르시우스", objective = "여명의 설원 눈망루 마을에 있는 스톰 섀도후프가 우르시우스를 처치해달라고 요청했습니다.", description = "여기서 북서쪽으로 눈 덮인 여명의 설원의 산맥에서는 솜씨가 아주 뛰어난 사냥꾼이 지금도 먹이를 쫓고 있다네... 톱니이빨곰 우르시우스라는 놈인데, 아주 재빠르고 영리한 짐승이지.\n\n이제 자네를 녀석에게 보내겠네. 눈망루 마을 북서쪽에 있는 경사진 언덕에서 돌아다니고 있을테니 녀석을 찾아 살금살금 다가가 처치하게.\n\n지금까지 우르시우스와 대적하려고 한 자들은 모두 녀석의 사냥감이 되어 쫓기게 됐지. 그러니 항상 경계를 늦추지 말게나.", progress = nil, completion = "결코 쉬운 일은 아니었지만 잘 해냈군. 하지만 그걸로 내가 감동했으리라고 섣불리 단정짓지 말게, &lt;name&gt;.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5055] = {title = "서리바람 브룸랜", objective = "여명의 설원 눈망루 마을에 있는 스톰 섀도후프가 브룸랜을 처치해 달라고 요청했습니다.", description = "재빠르고 영리한 브룸랜은 여명의 설원 남부의 눈 내린 땅 위를 조용히 미끄러져 다닌다네. 하지만 그 우아한 자태만 보고 해롭지 않을 거라는 착각은 말게. 그녀와 마주친 자들은 모두 크나큰 대가를 치러야 했고 종종 목숨을 잃는 경우도 있었으니까.\n\n서리바람 키메라들 사이에서 브룸랜을 찾아 처치하고 내게 돌아오게.", progress = "브룸랜이 자네를 부르고 있네, <name>.", completion = "음, 돌아왔군. 이제야 자네가 타고난 사냥꾼이라는 걸 알겠어. 나의 예상을 깨고 가장 사나운 짐승을 처치하고 돌아왔으니 말이야.\n\n이제 내 마지막 청을 할 때가 된 것 같군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5056] = {title = "샤이로탐", objective = "여명의 설원 눈망루 마을에 있는 스톰 섀도후프가 샤이로탐을 처치해 달라고 요청했습니다.", description = "여명의 설원 북부, 눈호랑이 바위란 곳에 거대한 호랑이들이 모인다네. 호랑이들의 우두머리는 바로 샤이로탐이라는 녀석인데, 이놈을 해치우면 자네 동료 <race>들 사이에서 꽤 자랑거리가 될 걸세.\n\n거친 설원으로 가서 눈호랑이들을 처치하고 신성한 눈호랑이 고기를 하나 구하게. 샤이로탐의 돌을 찾아 그곳에 고기를 놓게. 동족의 피냄새를 맡고 분노한 샤이로탐이 나타날 걸세.\n\n각오 단단히 하고 성난 호랑이를 물리치게나.", progress = nil, completion = "자네는 뛰어난 힘과 정신력, 모두를 입증했네. 더 이상 가르칠 게 없어. 앞으로도 숱한 모험이 자네를 기다리고 있을 거야...\n\n행운을 빌겠네, &lt;name&gt;.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n야수사냥꾼의 단검야수추적자의 검\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5057] = {title = "과거의 업적", objective = "썬더 블러프에 있는 멜로르 스톤후프에게 스톰 섀도후프의 문장을 가져가야 합니다.", description = "자네는 지금까지 <class>|1으로서;로서; 능력을 시험하기 위해 많은 난관을 극복해왔다고 들었네. 자네를 직접 보니 그 말이 사실인 것 같군.\n\n그 눈물겨운 노력과 탁월한 능력은 보상 받아 마땅하다고 생각하네. 자, 이 문장을 썬더 블러프에 있는 내 친구에게 가져가면 당신이 어떤 인물인지, 그리고 어떤 업적을 이루었는지 기억할 거야. 그리고 최근에 거둔 승리에 대한 무용담을 얘기해 주면 아주 좋아할 것이고... 참, 오늘 겪은 일도 잊지 말고 얘기해 주게.", progress = nil, completion = "당신이 걸어온 길은 우리에게 참으로 큰 교훈이 되고 있소, &lt;name&gt;. 이 문장을 보아하니 당신은 전보다 훨씬 더 강하고 현명해진 모양이오.\n\n자, &lt;race&gt; &lt;class&gt;|1으로서;로서; 당신이 이루어낸 수많은 공적을 기리는 의미에서 주는 것이니 받아 주시오. 그걸 볼 때마다 당신에 대한 내 존경과 찬사를 기억해 주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n사냥꾼의 휘장 목걸이"},
[5058] = {title = "달슨 부인의 일기", objective = "책장이 누렇게 변해 가는 일기장의 마지막 페이지가 펼쳐진 채로 있습니다.\n\n\"해럴드가 언데드로 변해버려 이제 무슨 일이 벌어질지 모르겠다. 안간힘을 써서 그를 가두고 문을 잠갔다. 열쇠를 감춰뒀는데, 효과가 있었으면 좋겠다...\n\n여기서 빠져나가고 싶지만 그러려면 돈이 든다. 우리 물건은 모두 장롱에 넣어 둔 것 같다... 그러고 보니 해럴드에게도 열쇠가 있지 않나?\n\n그건 일단 쉬고 나서 생각해야겠다. 너무 피곤하다.\"", description = nil, progress = nil, completion = nil, rewards = nil},
[5059] = {title = "잠긴 화장실", objective = "화장실문을 계속해서 억지로 열려고 한 듯, 가장자리가 쪼개지기 시작했습니다. 지금은 밖에서 단단히 잠겨 있습니다.\n\n문을 흔들어 보니 안에서 누군가 쉰 목소리로 신음하는 소리가 들립니다! 안에 있는 것이 무엇이든 간에 사나운 것 같습니다.", description = nil, progress = "화장실문을 계속해서 억지로 열려고 한 듯, 가장자리가 쪼개지기 시작했습니다. 지금은 밖에서 단단히 잠겨 있습니다.\n\n문을 흔들어 보니 안에서 누군가 쉰 목소리로 신음하는 소리가 들립니다! 안에 있는 것이 무엇이든 간에 사나운 것 같습니다.", completion = "달슨 부인의 시체에서 찾은 열쇠로 화장실문을 엽니다. 안에서 피에 굶주린 구울이 뛰쳐나옵니다. 이 안에 얼마나 오래 갇혀 있었는지 알 수도 없습니다.\n\n구울의 등골이 오싹해 지는 비명소리로 보아 구울로 변해버린 농부 달슨은 이제 구제할 수 없는 것이 분명합니다.", rewards = nil},
[5060] = {title = "잠긴 장롱", objective = "아주 튼튼해 보이는 장롱이 앞에 있습니다. 장롱에 달린 자물쇠로 단단히 잠겨 있습니다. 장롱의 앞 부분은 군데군데 찍힌 것으로 보아 누군가 안에 든 비밀을 꺼내려고 시도했던 것 같습니다.\n\n이 장롱을 열려면 열쇠가 있어야 합니다.", description = nil, progress = "아주 튼튼해 보이는 장롱이 앞에 있습니다. 장롱에 달린 자물쇠로 단단히 잠겨 있습니다. 장롱의 앞 부분은 군데군데 찍힌 것으로 보아 누군가 안에 든 비밀을 꺼내려고 시도했던 것 같습니다.\n\n이 장롱을 열려면 열쇠가 있어야 합니다.", completion = "구울로 변해버린 농부 달슨의 시체에서 찾은 열쇠가 자물쇠에 꼭 들어맞습니다. 장롱의 문이 활짝 열리고 안에 들어 있던 귀중한 물건들은 온전한 것처럼 보입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n농부 달슨의 산탄총달슨 가문 결혼반지"},
[5061] = {title = "바다표범 변신", objective = "다르나서스로 돌아가 마스렌길 베어워커에게 바다표범의 펜던트를 보여 주어야 합니다.", description = "그대는 이제 젊은 드루이드가 바다표범으로 변신하기 전에 배워야 할 교훈을 모두 얻었습니다. 이제 다르나서스에 있는 상급 드루이드, 마스렌길 베어워커에게 다시 가보십시오. 그에게 이 펜던트를 보여주면 그대가 가르침을 받을 준비가 됐다는 것을 믿어 의심치 않을 겁니다. 그에게 물과 하나가 되는 법을 배우면 이번 훈련을 완전히 마치는 것입니다.\n\n안녕히... 젊은 드루이드여. 훗날 다시 만나도록 합시다.", progress = "그대가 다르나서스로 돌아온다는 소식은 들었어요. 바다표범으로 변신하는 법을 가르쳐 주기 전에 달의 숲에서 시험을 통과했다는 증거부터 봐야겠군요.\n\n바다표범의 펜던트는 가져왔습니까?", completion = "아주 놀랍군요, &lt;name&gt;. 이제 그대는 바다표범으로 변신하는 법을 배울 준비가 됐어요. 기꺼이 가르쳐 드리지요.\n\n그리고 두 가지 시험을 성공적으로 통과한 그대의 노고를 인정해 이것을 드리도록 하겠습니다. 자연의 수호자이자 균형의 관리자인 그대에게 유용하게 쓰이길 바라겠어요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n바다표범 변신\n\n다음과 같은 것들을 받습니다:\n\n물병자리 허리띠"},
[5062] = {title = "신성한 불", objective = "불꽃 용설란 10포기를 모아 썬더 블러프 장로의 봉우리에 있는 마가타 그림토템을 찾아가야 합니다.", description = "아리카라는 매우 치명적인 생명체라 재빨리 처치해야 합니다. 신성한 생명의 불을 밝혀 아리카라를 소환한 다음 그녀를 쓰러뜨려야만 합니다.\n\n우선 희귀한 불꽃 용설란이라는 식물을 채집하십시오. 용설란을 충분히 채집한 후에는 썬더 블러프 장로의 봉우리로 가서 마가타 그림토템의 조언을 구하십시오. 마가타는 아주 강력한 힘을 지닌 주술사니까 용설란에 마법을 걸어 신성한 생명의 불을 밝힐 가루를 만들어 줄 겁니다.\n\n북동쪽에 있는 끓어오르는 웅덩이로 가서 불꽃 용설란부터 구하십시오.", progress = "모테가 파이어메인이 아리카라를 언급했단 말이지... 참으로 좋지 않은 소식이로군.\n\n<주위를 둘러보는 마가타>\n\n아리카라는 두려운 생명체일세. 사악한 행위를 저지른 이들에 대한 복수의 열망에만 불타고 있지.\n\n<어두운 미소를 짓는 마가타>", completion = "불꽃 용설란을 충분히 모았군. 버섯구름 봉우리에서만 나는 이 희귀한 식물로 꺼져버린 신성한 생명의 불을 밝힐 수 있을 거야.\n\n&lt;불꽃 용설란에 주문을 걸기 시작하는 마가타&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5063] = {title = "붉은 학자의 모자", objective = "붉은 학자의 모자를 얻으려면 말리퍼스 다크해머에게 다음 재료를 갖다주어야 합니다. 온전한 괴수의 가죽 1개, 닳아해진 누더기골렘 조각 5개, 신비한 수정 8개, 마력 깃든 붉은 실타래 5개\n\n제작비로 50골드도 가져가야 합니다.", description = "이보다 더 훌륭한 모자는 없습니다. 온전한 괴수의 가죽을 재료로 써서 장인의 손으로 빚어낸 이 걸작품은 명품을 아는 분만이 쓸 수 있는 최고의 모자입니다!\n\n50골드와 몇 가지 필요한 재료만 모아서 가져오면 당신의 머리 위에서 붉은 학자의 모자가 빛날 것입니다.\n\n- 온전한 괴수의 가죽\n\n- 닳아해진 누더기골렘 조각\n\n- 신비한 수정\n\n- 마력 깃든 붉은 실타래\n\n잘 기억해두십시오!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n붉은 학자의 모자"},
[5064] = {title = "그림토템부족 염탐", objective = "먹구름 봉우리에 있는 비밀 쪽지 3개를 찾아 와야 합니다.", description = "지금까지 우리를 잘 도와 주었으니 이제 아주 중요한 임무를 맡기도록 하겠네. 그림토템부족이 뭔가 수상한 꿍꿍이가 있는 것 같네. 지난 몇 주 동안 소속이 불분명한 첩자 세 명이 그림토템부족을 방문했다네. 우리가 알아낸 사실에 의하면 먹구름 봉우리에 있는 궤짝들 안에 그 쪽지들이 들어있는군.\n\n이 위험한 임무를 완수하면 내 꼭 후하게 보상하겠네.", progress = "그림토템부족이 무슨 일을 꾸미고 있는지 알아냈는가?", completion = "맙소사! 아주 안 좋은 소식이로군. 당장 이 사태를 막을 준비를 해야겠어.\n\n자, 약속했던 보상이네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n사막 어깨보호구툰드라 장화경종의 손목보호대\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5065] = {title = "모쉬아루의 잃어버린 서판", objective = "세 번째와 네 번째 모쉬아루 서판을 찾아 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다.", description = "당신과 대화를 나눈 트롤은 진실을 말하지 않았네. 그자에게 갖다준 두 개의 서판에 학카르의 정수를 담는 방법이 쓰여 있긴 하지만 그것이 전부가 아닐세. 내가 오랫동안 조사한 결과, 모쉬아루 서판은 모두 여섯 개야!!! 두 개가 아니라 여섯 개란 말이야!\n\n나머지 네 개의 서판에 쓰여 있는 비밀이 불길한 내용을 담고 있을지도 모르겠네.\n\n세 번째와 네 번째 모쉬아루 서판을 가져다주게. 동부 역병지대의 이끼껍질부족 트롤들이 갖고 있네.", progress = "서판은 가져왔나? 서판에 쓰인 글이 머지 않아 아제로스에 닥친 크나큰 위협에 대해 알려 줄지도 모르네.", completion = "찾았군! 좋았어!\n\n고마워, &lt;name&gt;. 이 글을 꼼꼼히 조사해 그 뜻을 해독하겠네.\n\n당신에게 또 다른 임무를 주려고 하는데...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5066] = {title = "역병지대 징집령!", objective = "사령관 아쉬람 발러피스트를 찾아야 합니다. 그의 주둔지는 알터랙 산맥 북쪽의 서리바람 야영지입니다.", description = "모두 주목하십시오! 모든 영웅들은 지금부터 내 말을 잘 들으시기 바랍니다!\n\n스톰윈드 왕국에 징집령이 내렸습니다! 싸울 수 있는 이들은 모두 동부 왕국의 서부 지역을 침략한 스컬지에 맞서 분연히 일어서 주시기 바랍니다. 지금 역병지대의 폐허에서 뭔가 새로운 위험이 다가오고 있다는 소문이 있습니다.\n\n여러분께서 이 땅의 영웅임을 자처한다면 알터랙 산맥 북쪽, 서리바람 야영지에 있는 아쉬람 발러피스트 사령관님을 찾아가시기 바랍니다.", progress = nil, completion = "잘 와 주었소, 영웅이여. 이곳은 아제로스 변경에서도 가장 위험한 지역 중의 하나지. 특히 북쪽과 북동쪽에서 스컬지의 위협이 시시각각 다가오고 있는 현재로써는 그 위험이 더하오. 왕국의 부름을 모른 척하지 않고 이렇게 달려와 준 당신이 정말 자랑스럽군.\n\n이 역병지대의 최전방에는 영웅들이 해야 할 일이 많으니 싸울 준비가 되었다면 당장에라도 가보도록 하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5067] = {title = "아카나의 다리보호구", objective = "아카나의 다리보호구를 얻으려면 말리퍼스 다크해머에게 다음 재료를 갖다주어야 합니다. 온전한 괴수의 가죽 1개, 닳아해진 누더기골렘 조각 5개, 아케이나이트 주괴 5개, 프로스트위스퍼의 불변의 영액 5개.\n\n제작비로 50골드도 가져가야 합니다.", description = "이 다리보호구는 성공적으로 제작한 사례는 거의 없지만 가능하다고는 알려져 있는 귀하디 귀한 물건입니다. 단 모든 재료가 준비되어야 합니다.\n\n신비하고 엄청난 마력을 부여한 다리보호구를 찾는 분이라면 다음 재료를 찾아보시기 바랍니다.\n\n- 온전한 괴수의 가죽\n\n- 닳아해진 누더기골렘 조각\n\n- 아케이나이트 주괴\n\n- 프로스트위스퍼의 불변의 영액\n\n잘 기억해 두십시오!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n아카나의 다리보호구"},
[5068] = {title = "핏빛갈증의 흉갑", objective = "핏빛갈증의 흉갑을 얻으려면 말리퍼스 다크해머에게 다음 재료를 갖다주어야 합니다. 온전한 괴수의 가죽 1개, 닳아해진 누더기골렘 조각 10개, 아케이나이트 주괴 5개, 어둠의 허물 5개.\n\n그리고 제작 비용으로 50골드도 갖고 가야 합니다.", description = "핏빛갈증의 흉갑을 제작하는 데 성공한 적은 단 한 번뿐이며, 바로 전설적인 암살자, 가로나를 위해 만들었다고 합니다. 그러므로 이 세계에서 똑같은 흉갑을 입은 자를 볼 확률은 거의 희박합니다.\n\n특별한 당신을 위해!!! 우리 전문 세공인들이 가로나의 것과 똑같은 것을 만들어 드리겠습니다. 필요한 재료만 가져오시면 됩니다.\n\n- 온전한 괴수의 가죽\n\n- 닳아해진 누더기골렘 조각\n\n- 아케이나이트 주괴\n\n- 어둠의 허물\n\n잘 기억해 두십시오!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n핏빛갈증의 흉갑"},
[5081] = {title = "맥스웰의 임무", objective = "검은바위 첨탑으로 가서 대장군 부네와 대군주 오모크, 그리고 요새의 대군주 웜타라크를 처치해야 합니다. 임무를 완수하면 맥스웰 치안 대장에게 돌아가십시오.", description = "이 정보로 검은바위 첨탑에 대한 모든 정보를 갖게 되었소.\n\n이번 공격으로 결정적인 피해를 입혀야만 하오.\n\n먼저 그들의 트롤 대장군 부네를 처리해야 하오. 녀석의 전술이 없다면 검은바위부족 오크들은 혼란에 빠질 수밖에 없소.\n\n그 후엔 오우거 대군주 오모크를 처단하시오. 그의 지휘가 없다면 비겁한 오우거들은 힘없이 쓰러질 것이오.\n\n마지막으로 첨탑의 대군주, 웜타라크를 처치하시오. 웜타라크가 죽는다면 중앙 지휘부는 도랑으로 굴러 떨어질 수밖에 없을 것이오.", progress = nil, completion = "아주 잘했소. 위급한 때에 당신이 우리에게 소중한 시간을 벌어주었소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n웜타라크의 족쇄오모크의 허리죔쇠할리콘의 재갈보쉬가진의 허리끈부네의 사술 장갑\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5082] = {title = "눈사태일족의 위협", objective = "여명의 설원에 있는 도노바 스노우덴이 눈사태일족 길잡이 8마리, 눈사태일족 보초 8마리, 눈사태일족 토템술사 8마리를 처치해달라고 요청했습니다.", description = "저는 프로스트파이어 간헐천을 조사하러 여명의 설원에 왔어요. 이곳 온천수는... 좀 이상한 성질을 띠고 있더군요. 아직 그 원인을 알아내지 못했는데, 솔직히 말해서 요즘에는 눈사태일족 펄볼그들 때문에 어려움을 겪고 있어요.\n\n녀석들도 저처럼 그 온천에 끌린 것인지... 얼마나 사납게 보호를 하는지 여기서 북쪽에 있는 큰 온천 두 군데는 아예 근처에 얼씬도 못하게 하더군요.\n\n조사를 계속하고 싶은데, 당신이 도와주지 않으시겠어요?", progress = nil, completion = "정말로 감사합니다, &lt;name&gt;! 이제 작업을 계속할 수 있겠군요.\n\n그런데 혹시 눈사태일족 야영지에서 뭔가 눈에 띄는 건 발견하지 못했나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5083] = {title = "눈사태일족 화주", objective = "여명의 설원에 있는 도노바 스노우덴에게 빈 화주 시험관을 갖다주어야 합니다.", description = "눈사태일족 펄볼그에게서 찾은 물병은 거의 비어있지만 이상한 녹색 액체 몇 방울이 남아있습니다. 빛을 발하는 것 같기도 합니다.\n\n중요한 것일까요?\n\n여명의 설원에 있는 온천 부근에서 한동안 야영을 해본 도노바 스노우덴이라면 더 자세한 얘기를 해줄 수 있을 것입니다.", progress = "뭘 찾으셨나요?", completion = "이걸 눈사태일족에게서 찾았다고요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5084] = {title = "타락에 빠지다", objective = "악령의 숲 북부에 있는 마른가지일족 펄볼그 야영지에서 단서를 찾아야 합니다.", description = "이 녹색 액체를 보니 제가 악령의 숲을 지나가면서 본 녹괴물이 생각나요. 그리고 나무구렁 요새로 가던 눈사태일족 정찰꾼들 생각도 나네요... 어쩌면 이 액체와 관련이 있을지도 모르겠네요.\n\n악령의 숲에 있는 나무구렁 요새를 지나가다 보면 펄볼그 무리가 모여있을 거예요. 마른가지일족이라고 하는데, 악령의 숲의 어떤 물질 때문에 오염되어 미쳐버렸죠. 어떤 것이라도 좋으니 거기로 가서 눈사태일족과 마른가지일족 간의 거래에 대한 증거를 한번 찾아보세요.", progress = nil, completion = "가마솥 안에 담긴 어떤 물질이 썩어가면서 역겨운 냄새를 풍기고 있습니다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5085] = {title = "신비한 액체", objective = "발견한 사실을 도노바 스노우덴에게 알려야 합니다.", description = "가마솥 안에 든 녹색 액체는 병 속의 것과 비슷합니다. 이 이상하고 걸쭉한 액체는 이 물질을 만들어낸 펄볼그 만큼이나 타락했을 수 있습니다...\n\n눈사태일족이 이 액체를 사용하고 있다면 그들도 머지않아 마른가지일족처럼 타락하게 된다는 뜻일까요?\n\n가마솥 안의 액체를 담아 도노바를 찾아가 얘기를 해보는 것이 좋겠습니다.", progress = "뭐라도 찾으셨으면 좋겠군요, <name>. 눈사태일족이 점점 더 난폭해지고 있어요!", completion = "재주가 좋으시군요, &lt;name&gt;. 눈사태일족이 마른가지일족과 만난 것 같나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5086] = {title = "맹독 정령", objective = "여명의 설원에 있는 도노바 스노우덴에게 맹독 정령 수액 3개를 갖다주어야 합니다.", description = "당신이 가져오신 액체를 조사해보았는데, 뭐라고 단정지을 수는 없지만 유독 성분이 있는 것 같아요. 확실하게 밝혀내려면 반드시 비교할만한 물질을 찾아야 해요.\n\n마른가지일족은 악령의 숲에 사는 타락한 생물들에게서 이 유독 성분을 모으는 것 같아요. 특히 강철나무 숲에 사는 정령, 맹독 정령들에게서 말이죠.\n\n제가 비교를 할 수 있도록 견본을 몇 개 구해주세요. 하지만 아주 위험한 곳이니 부디 조심하세요!", progress = "무슨 일이 일어나고 있는지 우리가 서서히 알아내고 있는 것 같네요, <name>.", completion = "이 물질을 가마솥에서 가져온 것과 비교를 해봐야 하겠어요. 그러면 분명 뭔가 더 알아낼 수 있을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5087] = {title = "눈사태일족 정찰꾼", objective = "눈사태일족 정찰꾼들을 찾아 눈사태일족 마을로 물건을 전달하는 것을 막아야 합니다.", description = "매우 흥미롭군요...\n\n여기에 온천수를 섞으니 유독 성분이 사라져요. 효과는 일시적이지만요. 그래서 눈사태일족이 온천을 그렇게 맹렬히 지키는가 봐요. 화주를 정화하는 데 필요할 테니까요.\n\n이 사태는 당장 막아야 합니다. 눈사태일족과 마른가지일족 간의 접촉을 끊어야 해요. 정찰꾼 한 무리가 눈사태일족 마을과 악령의 숲을 지나다니곤 하는데, 이들을 처치하고 가지고 있는 물건을 빼앗아오세요.", progress = "화주가 없으면 눈사태일족이 어떻게 되는가 한번 두고 보자고요!", completion = "&lt;상자 안에 든 물건을 조사하는 도노바&gt;\n\n펄볼그들이 이 물질을 섭취해 더욱 사나워지는 건 아닌지 궁금하군요. 확실히 덩치가 더 커진 것 같긴 한데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5088] = {title = "아리카라", objective = "아리카라를 처치하고 그 증거물로 아리카라의 가죽과 불꽃 가루를 백사장 야영지에 있는 모테가 파이어메인에게 가져가야 합니다.", description = "여기 정화하여 곱게 빻은 불꽃 가루를 버섯구름 봉우리로 갖고 가서 신성한 생명의 불에 집어던지게. 그 불은 망자들을 묻는다는 먹구름 봉우리라는 외딴 봉우리에 있다네.\n\n불꽃 가루에 걸어 놓은 마법 주문 때문에 아리카라가 나타날 게야.\n\n혹시 아리카라가 케른 블러드후프님을 노리고 있는지도 모르겠군. 아리카라에 대한 전설을 타우렌 종족이 너무 많이 변질시켜서 그녀의 분노를 산 모양이야. 자, <class>... 늦기 전에 어서 가 보게!", progress = "그 악독한 독사 아리카라를 처치하셨습니까?", completion = "뭔가 이해가 안 되는군요. 아리카라가 왜 케른 블러드후프님을 노린답니까? 가장 강력한 주술사이신 마가타님이 틀렸을 리도 만무하고...\n\n&lt;머리를 가로 젓는 모테가&gt;\n\n어쨌든 당신은 호드에 크나큰 업적을 세운 것이니 그에 대한 답례를 드리죠. 자, 하나 고르십시오. 정말 감사합니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n투사의 망치쐐기돌 마법봉모래알 방패\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5089] = {title = "사령관 드라키사스의 명령서", objective = "불타는 평원에 있는 치안대장 맥스웰에게 사령관 드라키사스의 명령서를 가져가야 합니다.", description = "격퇴한 용의 시체에서 뭔가 중요한 기밀 문서 같은 것을 찾았습니다. 자세히 들여다 보니 그것은 웜타라크 상관인 드라키사스 장군의 편지였습니다.\n\n이것을 치안대장 멕스웰에게 보여줘야 한다는 생각이 듭니다.", progress = "들고 있는 게 무엇이오?", completion = "일이 복잡해지는군...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5090] = {title = "역병지대 징집령!", objective = "아쉬람 발러피스트 사령관을 찾아가야 합니다. 그의 본진은 알터랙 산맥 북부 서리바람 야영지에 있습니다.", description = "들으시오! 모든 영웅들은 귀를 기울여 내 말을 들으시오!\n\n스톰윈드 왕국에서 용병을 모집하고 있소! 신체 건강한 모든 이들에게 고하건대 어서 무기를 들고 동부 왕국의 남쪽을 위협하고 있는 사악한 스컬지 세력에 맞서 분연히 일어서 주기를 바라오! 지금 역병지대의 폐허로부터 뭔가 새로운 위험이 다가오고 있다는 소문도 있소!\n\n동부 왕국의 영웅들이여, 알터랙 산맥 북부 서리바람 야영지에 본진을 세운 아쉬람 발러피스트 사령관을 찾아가시오!", progress = nil, completion = "역병지대에 온 것을 환영하는 바이오. 이곳은 아제로스 변방에서도 가장 위험한 지역 중 하나지. 특히 북쪽과 북동쪽에서 스컬지의 위협이 시시각각 다가오고 있어서 더욱 위험한 형세라오. 왕국의 부름을 모른 척하지 않고 이렇게 달려와 준 그대가 정말 자랑스럽소.\n\n이곳 역병지대 최전방에는 영웅이 해야 할 일이 많으니 싸울 준비가 되었다면 당장에라도 나서 보시오. 당신과 똑같은 각오를 한 용사들이 함께할 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5091] = {title = "역병지대 징집령!", objective = "아쉬람 발러피스트 사령관을 찾아가야 합니다. 그의 본진은 알터랙 산맥 북부 서리바람 야영지에 있습니다.", description = "들으시오! 모든 영웅들은 귀를 기울여 내 말을 들으시오!\n\n스톰윈드 왕국에서 용병을 모집하고 있소! 신체 건강한 모든 이들에게 고하건대 어서 무기를 들고 동부 왕국의 남쪽을 위협하고 있는 사악한 스컬지 세력에 맞서 분연히 일어서 주기를 바라오! 지금 역병지대의 폐허로부터 뭔가 새로운 위험이 다가오고 있다는 소문도 있소!\n\n동부 왕국의 영웅들이여, 알터랙 산맥 북부 서리바람 야영지에 본진을 세운 아쉬람 발러피스트 사령관을 찾아가시오!", progress = nil, completion = "역병지대에 온 것을 환영하는 바이오. 이곳은 아제로스 변방에서도 가장 위험한 지역 중 하나지. 특히 북쪽과 북동쪽에서 스컬지의 위협이 시시각각 다가오고 있어서 더욱 위험한 형세라오. 왕국의 부름을 모른 척하지 않고 이렇게 달려와 준 그대가 정말 자랑스럽소.\n\n이곳 역병지대 최전방에는 영웅이 해야 할 일이 많으니 싸울 준비가 되었다면 당장에라도 나서 보시오. 당신과 똑같은 각오를 한 용사들이 함께할 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5092] = {title = "통로 확보", objective = "슬픔의 언덕에 있는 해골 타작꾼 10마리와 걸신들린 구울 10마리를 처치해야 합니다.\n\n그런 다음 서부 역병지대의 서리바람 야영지에 있는 사령관 아쉬람 발러피스트에게 돌아가십시오.", description = "안돌할의 서쪽과 북쪽 통로는 모두 요새화되어 있어 요새화되지 않은 동쪽 통로에서 공격을 할 생각이오. 슬픔의 언덕에 있는 언데드 무리가 최전방 방어선이고 스컬지는 이 녀석들에게 의존하고 있으니 안돌할로 진격하려면 슬픔의 언덕을 통과해서 가야 하오.\n\n당신의 첫 임무는 슬픔의 언덕에 통로를 확보하는 것이오. 그 지역을 돌아다니는 해골과 구울의 수를 줄이고 임무가 끝나면 내게 돌아오시오!", progress = "최악의 상황에 대비하고 깊숙이 파고 드시오. 우리 앞에 놓인 임무는 결코 쉽지 않을 것이오. 우리 군단을 집결해 마침내 스컬지를 칠 때가 되면 당신은 최전선에 가담하게 될 것이오! 당신이 슬픔의 언덕에서 수행하는 임무는 우리의 승리로 향하는 길을 열게 되는 것이오!", completion = "임무 완료로군! 수고했소, 아주 수고했어.\n\n스톰윈드 국세에서 이번 임무에 대한 보상금을 지급해 주겠소. 그 돈으로 다음 임무에 필요한 장비를 구입해 두는 게 좋을 거요... 다음 임무를 수행하려면 안돌할의 폐허까지 직접 들어가야 하니까 말이지.\n\n준비를 단단히 하고 경계를 소홀히 하지 마시오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5093] = {title = "역병지대 징집령!", objective = "고위집행관 델링턴을 찾아가야 합니다. 그의 주둔지는 티리스팔 숲과 언더시티의 동쪽에 있는 보루에 있습니다.", description = "이 땅의 영웅들은 들으시오. 호드는 여러분의 힘이 필요하오. 즉각적인 행동을 보여주시오!\n\n신체 건강한 자들은 모두 분연히 일어나 스컬지와 맞서 싸우라는 징집령이 떨어졌소. 지금 동부 왕국의 폐허로부터 새로운 위험의 바람이 불어오고 있다는 소문도 있소. 언더시티 동쪽에서 봉기한 적들로 인해 북쪽 지방이 역병지대가 되고 말았소.\n\n그대가 이 땅의 영웅을 자처한다면 티리스팔 숲 동쪽 보루에 있는 델링턴 고위집행관의 주둔지로 찾아가시오!", progress = nil, completion = "잘 와 주었네. 이곳은 아제로스 변방에서도 가장 위험한 지역 중의 하나지. 특히 현재 스컬지가 동쪽으로 계속 손을 뻗치고 있는 형국이라 그 위험이 더욱 크다고 할 수 있지. 호드의 부름을 모른 척하지 않고 이렇게 달려와 주다니 정말 자랑스럽군.\n\n이 역병지대의 최전방에는 영웅이 해야 할 일이 많으니 싸울 준비가 되었다면 당장에라도 나서 보도록 하게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5094] = {title = "역병지대 징집령!", objective = "고위집행관 델링턴을 찾아가야 합니다. 그의 주둔지는 티리스팔 숲과 언더시티의 동쪽에 있는 보루에 있습니다.", description = "이 땅의 영웅들은 들으시오. 호드가 여러분의 힘을 필요로 하고 있소. 즉각적인 행동이 필요한 상황이오!\n\n신체 건강한 자들은 모두 분연히 일어나 스컬지와 맞서 싸우라는 징집령이 떨어졌소. 지금 동부 왕국의 폐허로부터 새로운 위협의 바람이 불어오고 있다는 소문이 있소. 언더시티 동쪽에 역병지대가 바로 그 곳이오.\n\n당신이 이 땅의 영웅임을 자처한다면 티리스팔 숲 동쪽 보루에 있는 델링턴 고위집행관님의 주둔지로 찾아가시오!", progress = nil, completion = "잘 와 주었네. 이곳은 아제로스 변방에서도 가장 위험한 지역 중의 하나지. 특히 동쪽 지역으로 계속해서 스컬지가 손을 뻗치고 있는 현재로써는 그 위험이 더 크다고 할 수 있지. 호드의 부름을 모른 척하지 않고 이렇게 달려와 주다니 정말 자랑스럽군.\n\n이 역병지대의 최전방에는 영웅들이 해야 할 일이 많으니 싸울 준비가 되었다면 당장에라도 나서 보도록 하게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5095] = {title = "역병지대 징집령!", objective = "고위집행관 델링턴을 찾아가야 합니다. 그의 주둔지는 티리스팔 숲과 언더시티의 동쪽에 있는 보루에 있습니다.", description = "이 땅의 영웅들은 들으십시오. 호드에서는 그대들의 도움을 원하고 있습니다. 즉각적인 행동이 필요한 상황입니다!\n\n신체 건강한 자들은 모두 무기를 들고 스컬지에 맞서 싸우라는 징집령이 떨어졌습니다! 지금 동부 왕국의 폐허에서 새로운 위협이 떠오르고 있다는 소문이 들려오고 있습니다. 동부 왕국의 북쪽, 언더시티의 동쪽에 있는 역병지대라고 합니다!\n\n당신이 이 땅의 영웅임을 자처한다면 티리스팔 숲 동쪽 보루에 있는 델링턴 고위집행관님의 주둔지로 찾아가십시오!", progress = nil, completion = "잘 와 주었네. 이곳은 아제로스 변방에서도 가장 위험한 지역 중의 하나지. 특히 동쪽 지역으로 계속해서 스컬지가 손을 뻗치고 있는 현재로써는 그 위험이 더 크다고 할 수 있지. 호드의 부름을 모른 척하지 않고 이렇게 달려와 주다니 정말 자랑스럽군.\n\n이 역병지대의 최전방에 당장에라도 나서 보도록 하게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5096] = {title = "붉은십자군의 주의 끌기", objective = "펠스톤 농장과 달슨의 눈물 사이에 있는 붉은십자군의 야영지로 가서 지휘 막사를 파괴하십시오.\n\n기지에 스컬지 깃발을 세운 후, 서부 역병지대의 보루에 있는 고위집행관 델링턴에게 돌아가야 합니다.", description = "안돌할에 가기 전에 하스글렌에서 붉은십자군을 저지해야 하네. 붉은십자군 녀석들이 펠스톤 농장과 달슨의 눈물 사이에 진을 쳐 자칫하면 우리가 스컬지와 붉은십자군을 한꺼번에 상대해야 할지도 모르네.\n\n난 녀석들이 서로 싸우도록 할 계획이었는데, 자네를 보내 붉은십자군의 지휘 막사를 파괴해야겠네. 이 화염병 상자에서 화염병을 꺼내 가지고 가게. 지휘 막사를 파괴한 후에는 이 스컬지 깃발을 꽂아 놓게. 잘만 하면 녀석들이 우리는 무시한 채 복수를 하려고 스컬지에게 달려들 거야.", progress = nil, completion = "잘 했네. 자네가 붉은십자군에 가한 습격으로 우리는 시간을 벌 수 있을 걸세. 내가 정찰병 하나를 보내서 기지를 염탐하며 붉은십자군 증원군이 미끼를 무는지 확인하도록 했네.\n\n이제 압력이 좀 줄었으니 드디어 안돌할로 쳐들어갈 수 있을 거야. 그것도 아주 중요한 임무를 수행하러 가는 거지. 지금까지 자네가 임무를 척척 수행한 것을 봐서 다음 임무도 맡아줬으면 하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5097] = {title = "감시탑 공격 준비", objective = "신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다.\n\n네 개의 감시탑에 모두 표시했으면 신호 횃불을 서부 역병지대의 서리바람 야영지에 있는 사령관 아쉬람 발러피스트에게 가져가십시오.", description = "자, 이걸 받으시오. 이 신호 횃불이라는 마법 장치를 이용하면 우리 부대의 다음 임무 대상을 선택해 표시할 수 있소. 스컬지는 안돌할의 감시탑을 이용해 우리 부대의 동태를 파악하고 있는 것 같소.\n\n당신의 임무는 이렇소. 안돌할의 방어선을 뚫고 들어가 네 개의 감시탑 모두에 신호 횃불을 설치하시오. 신호 횃불을 설치하려면 각 탑의 문턱으로 들어서야 하는데, 그러면 신호 횃불이 작동하여 탑을 표시하게 될 것이오. 신호 횃불은 다섯 번만 사용할 수 있으니 신중하게 사용하도록 하시오!", progress = nil, completion = "우리 사제들이 네 개의 감시탑 모두에서 극히 강력한 신호를 받고 있다고 보고하고 있소! 이번에도 당신이 임무를 매우 성공적으로 완수했군! 정말 잘했소!\n\n탑에 표시했으니 우리 군이 공격할 준비가 다 된 것이오. 이제 스컬지를 몰아붙일 때가 온 것이야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5098] = {title = "감시탑 공격 준비", objective = "신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다.\n\n네 개의 감시탑에 모두 표시했으면 신호 횃불을 서부 역병지대의 보루에 있는 고위집행관 델링턴에게 가져가십시오.", description = "자, 이걸 받게. 이 신호 횃불이라는 마법 장치를 이용하면 우리 부대의 다음 임무 대상을 선택해 표시할 수 있네. 스컬지는 안돌할의 감시탑으로 우리 부대의 동태를 파악하고 있는 것 같다네.\n\n자네의 임무는 다음과 같네. 안돌할의 방어선을 뚫고 들어가 네 개의 감시탑 모두에 신호 횃불을 설치하게. 신호 횃불을 설치하려면 각 탑의 입구에 들어서야 하는데, 그러면 신호 횃불이 작동하여 탑을 표시하게 될 것이야. 신호 횃불은 다섯 번만 사용할 수 있으니 신중하게 사용하도록 하게!", progress = nil, completion = "우리 흑마법사들이 네 개의 감시탑 모두에서 극히 강력한 신호를 받고 있다고 보고하고 있네! 이번에도 자네가 임무를 매우 성공적으로 완수했군! 정말 잘했네!\n\n탑에 표시했으니 우리 군이 공격할 준비가 다 된 것이야. 스컬지를 몰아붙일 때가 왔네!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5101] = {title = "Lee's Ultimate Test Quest... of Doom!", objective = "Kill 6 sheep for Benny and then run like hell!\n\n\n\n\nJust kidding... about the running part.", description = "Bah! What do think this is, some kind of Test Quest? I be there even be typos in it!\n\nIf ya be thinkin' my quest is goin' ta be easy, then ya got another thing coming!\n\nKill me ten sheep (1933) and don't come back until you do!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n기사검"},
[5102] = {title = "사령관 드라키사스 처치", objective = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치해야 합니다. 임무를 완수하면 치안대장 맥스웰에게 돌아가야 합니다.", description = "우리는 두 지역에서 그 괴물들을 상대할 작정이오. 우리의 수도인 스톰윈드의 안과 밖에서, 이곳 불타는 평원에서는 그들의 앞마당에서 상대할 것이오. 신중해야 하오. 저들이 우리의 고향과 가족들을 하나도 살려두지 않은 것처럼 누구도 살려두지 않을 것이야.\n\n드라키사스 장군을 찾아서 처단하시오!\n\n이번 임무는 물론 쉽지 않을 테지만, 보상은 엄청날 것이오.", progress = nil, completion = "아주 잘해 주었소. 물론 다음 목표는 그들의 용군주들이 될 것이오. 얼라이언스의 용맹한 군인이여! 정말 잘해주었소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n폭정의 징표괴수의 눈블랙핸드의 팔찌\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5103] = {title = "뜨거운 화형", objective = "아제로스 어딘가에 누군가가 이 건틀릿으로 뭘 해야 하는지 알고 있을 겁니다. 행운을 빕니다!", description = "이 인간의 흔적은 불에 그슬린 뼈쪼가리들 뿐입니다. 불타지 않은 판금 건틀릿을 집으려고 하다 팔을 뻗은 채로 죽은 것 같습니다.\n\n건틀릿을 집고 용암에서 벗어나는 게 좋겠습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5121] = {title = "대족장 눈사태", objective = "여명의 설원에 있는 도노바 스노우덴이 대족장 눈사태를 처치해 달라고 부탁했습니다.", description = "눈사태일족이 이 이상한 물질을 섭취하는 이유는 아직 잘 모르지만, 손을 써볼만 할 때 이 사태를 막아야겠어요.\n\n보통 눈사태일족은 사납지 않은데, 이렇게 이상하게 행동하는 까닭은 족장이 명령을 내렸기 때문이라고 생각합니다. 이미 입은 피해는 어쩔 도리가 없지만 우두머리를 처치하면 사태가 더 악화되지는 않겠죠.\n\n눈사태일족 마을은 여기서 동쪽입니다.", progress = nil, completion = "고마워요, &lt;name&gt;! 이제 습격당할 걱정 없이 연구를 계속해도 괜찮겠네요. 고마움의 표시이니 받아 주세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n수정실바람 어깨보호대고사리 웃옷버드나무매듭 갑옷\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5122] = {title = "신념의 메달", objective = "난 이 교회의 힘으로 내 가슴 속의 타락에 저항하고 있소. 내가 이곳을 떠나면 죽음의 기사로 변해 버리게 될거요. 하지만 신념의 메달만 있으면 내가 이곳을 떠날 수 있는 힘을 줄 거요.\n\n부탁이니 그 메달을 가져다주시오. 그 메달은 광신자 말로가 지키고 있는데, 이 미친 녀석은 스트라솔름 서쪽에 있는 붉은십자군 성채에 사는 붉은십자군의 일원이라오.", description = nil, progress = "난 이 교회의 힘으로 내 가슴 속의 타락에 저항하고 있소. 내가 이곳을 떠나면 죽음의 기사로 변해 버리게 될거요. 하지만 신념의 메달만 있으면 내가 이곳을 떠날 수 있는 힘을 줄 거요.\n\n부탁이니 그 메달을 가져다주시오. 그 메달은 광신자 말로가 지키고 있는데, 이 미친 녀석은 스트라솔름 서쪽에 있는 붉은십자군 성채에 사는 붉은십자군의 일원이라오.", completion = "메달을 가져왔군! 이제 이 교회를 떠나 임무를 수행할 수 있게 됐소이다.\n\n내 임무는 나와 내 수많은 동지들을 타락시키는데 한몫을 한 리븐데어 남작을 처치하는 거요!", rewards = nil},
[5123] = {title = "마지막 단서", objective = "여명의 설원에 있는 도노바 스노우덴에게 휘갈겨 쓴 일지를 가져다주어야 합니다.", description = "대족장에게서 찾은 일지는 아주 상세한 내용을 담은 것 같이 보이는데, 몇 페이지를 넘기고 보니 글자를 전혀 알아볼 수 없습니다. 문자가 워낙 허술하고 산만하게 쓰여 있어 아무도 읽을 수 없을 것 같습니다.\n\n하지만 도노바라면 무슨 뜻인지 해독할 수 있을는지도 모릅니다.", progress = "이건 뭐죠, <name>?", completion = "이게 다 무슨 뜻일까요... 아무것도 알아볼 수가 없네요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5124] = {title = "불꽃의 판금 건틀릿", objective = "마력 깃든 토륨 주괴 6개, 불의 정수 2개, 별루비 4개를 말리퍼스 다크해머에게 갖다주어야 합니다. 불타지 않은 판금 건틀릿도 주어야 합니다.", description = "세상에!\n\n그것들은 대체 어디서 찾은 겁니까?\n\n아니, 그것보다, 좀 나눠 줄 생각은 없소? 물론 고귀한 선물에 대한 대가를 지급해야지.\n\n이렇게 합시다, <name>. 그 불타지 않은 판금 건틀릿을 주면 당신에게 제작법을 가르쳐주겠소. 내가 정확한 제작법을 찾아 도면을 만들 수 있도록 부품을 찾아주기만 하면 되는 거요.\n\n한번 해 보겠소?\n\n필요한 물품 목록을 읽어 보시오. 나는 그동안 마력이 깃들지 않은 토륨을 찾아보겠소.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n도면: 불꽃의 판금 건틀릿불꽃의 판금 건틀릿"},
[5125] = {title = "아우리우스의 복수", objective = "난 죽어가지만... 내 영혼은 구제되었소. 당신에게 뭐라 말로 표현할 수 없는 신세를 진 거요. 부디 이걸 받아주시오. 그리고 계속 싸우시오, 용맹한 <class>|1이여;여;!", description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n순교자의 결의순교자의 피\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5126] = {title = "로락스의 이야기", objective = "로락스와 대화를 해서 그가 하는 이야기를 들어야 합니다.", description = "거대한 사티로스가 왔다 갔다 하면서 혼자 중얼거리고 있습니다. 말을 걸어 보십시오.", progress = nil, completion = "&lt;로락스가 껄껄 웃습니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5127] = {title = "악마의 룬", objective = "검은바위 첨탑으로 가서 고랄루크 앤빌크랙을 찾아 처치한 후, 핏물이 깃든 창을 그의 심장에 꽂으십시오. 창이 그의 영혼을 흡수하면 영혼이 깃든 창으로 변합니다.\n\n벼려지지 않은 룬문자 흉갑도 찾아야 합니다.\n\n영혼이 깃든 창과 벼려지지 않은 룬문자 흉갑을 여명의 설원에 있는 로락스에게 갖다주십시오.", description = "로락스는 미천한 생명체들과는 거래를 하지 않노라.\n\n하지만 너와는 하겠다. 이 창을 받아라. 아주 강력한 악의 에너지가 깃들어 있다. 고랄루크 앤빌크랙을 찾거든 그를 처치하고 그의 꺼져 가는 심장에 이 창을 꽂아라. 그는 영혼을 내게 팔았으니 내가 가지겠다. 내 창과 그 도둑놈이 훔쳐간 흉갑을 가져오면 그자에게 주기로 한 가르침을 너에게 주겠다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n도면: 악마의 룬 흉갑악마 사냥 전문화의 비약악마의 가방"},
[5128] = {title = "대족장의 기록", objective = "악령의 숲 남부에 있는 켈레크 스카이키퍼에게 휘갈겨 쓴 일지를 갖다주어야 합니다.", description = "눈사태일족은 더 이상 위협이 되지 않지만, 어째서 이 이상한 화주를 만들어 마시게 됐는지 알고 싶으면 켈레크 스카이키퍼를 한번 찾아가 보세요.\n\n에메랄드 의회에 소속된 사람이죠. 그 단체는 악령의 숲에 퍼진 타락을 치유하기 위해 헌신하는 드루이드들의 모임이랍니다.\n\n켈레크는 악령의 숲에 사는 펄볼그들에 대한 지식과 경험이 풍부해 이 일지에 대해 더 자세히 말해줄 수 있을 거예요.\n\n다시 한번 감사 드립니다, <name>.", progress = "에메랄드 의회는 모두를 환영하오. 어쩐 일로 오셨소?", completion = "잠시 조사해보면 무슨 뜻인지 해독해줄 수 있겠소.\n\n&lt;책장을 넘기며 훑어보는 켈레크&gt;\n\n이 일지를 다 조사해본 후에 그대에게 다시 연락을 취하도록 하겠소.\n\n이 일지를 보게 해줘서 고맙소이다. 눈사태일족에 대해서는 알려진 바가 그리 많지 않아서 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5141] = {title = "용비늘 가죽세공", objective = "단단한 전갈 흉갑 2개와 단단한 전갈 장갑 2개, 닳아해진 용비늘 10개를 아즈샤라에 있는 피터 갈렌에게 가져가야 합니다.\n\n이 임무를 완수하면 용비늘 가죽세공술을 배우지만...\n\n원소 가죽세공술과 전통 가죽세공술은 영영 익힐 수 없게 됩니다. 그러므로 피터가 준 임무를 수행하기 전에 정말로 이 길을 가고 싶은지 확실히 결정하십시오.", description = "용비늘 가죽세공은 쉬운 일이 아니지만, 분명 엄청난 보상이 따른다오. 몇 가지만 약속하면 이 우수한 사슬 방어구 만드는 기술을 가르쳐 드리겠소.\n\n먼저 이 길을 선택하면 원소 가죽세공술이나 전통 가죽세공술을 익히지 않을 것을 약속하시오. 절정에 이를 수 있는 기술은 세 가지 중 하나뿐이기 때문이오. 그리고 실력을 평가할 겸, 전갈의 껍질로 훌륭한 작품을 만들어 가져오시오. 마지막으로 재료 조달 능력을 검증해보고 싶군. 이 세공술의 주재료가 되는 용비늘을 구해오시오.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n용비늘 가죽세공\n\n다음과 같은 것들을 받습니다:\n\n"},
[5142] = {title = "꼬마 파멜라", objective = "파멜라 레드패스를 찾아야 합니다.", description = "다로우샤이어 전투에서 많은 가족들이 죽었답니다. 정말 많이 죽었죠.\n\n그런데 더 안타까운 것은 전투가 시작될 때 내 조카 파멜라를 숨겨 놨었는데, 그 아이에게 무슨 일이 생겼는지 모르겠어요. 전 이러저리 떠돌아 다닐 수밖에 없는 원혼이지만, 그래도 파멜라의 행방을 알고 싶어요.\n\n제발, 관대하신 <class>님. 다로우샤이어로 가서 그녀를 찾아 주시겠어요? 다로우샤이어는 가론의 흉가를 지나서 동쪽으로 가면 됩니다.", progress = nil, completion = "안녕하세요. 제 이름은 파멜라에요. 당신은 누구세요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5143] = {title = "전통 가죽세공", objective = "페랄라스에 있는 카리시아 문헌터에게 야생 가죽 조끼와 야생 가죽 투구를 가져가야 합니다.\n\n이 퀘스트를 완료하면 전통 가죽세공술을 배울 수 있지만 용비늘 가죽세공술과 원소 가죽세공술을 배울 수 없습니다.\n\n퀘스트를 시작하기 전에 어떤 가죽 세공술을 배울지 결정하시기 바랍니다.", description = "나이트 엘프 전통의 가죽세공술을 배우려면 자연의 본질을 이해해야 해요. 그대가 야생 가죽 방어구 제작 기술은 이미 통달했다는 건 알지만 이제는 그 기술을 완성의 경지로 끌어올릴 때가 된 것 같군요. 내가 그대의 기술을 완성시켜 주겠어요.\n\n그런데 한 가지 알아두어야 할 게 있어요, <class>. 전통 가죽세공인의 길을 가게 되면 절대 용비늘 가죽세공술이나 원소 가죽세공술은 배울 수 없게 되죠. 세 가지 기술 중에 한 가지만 배우기도 벅차니까요. 그리고 내게 당신이 만든 야생 가죽 방어구 중에 가장 품질이 좋은 것을 가져오도록 하세요. 그때 수업을 시작하도록 하겠어요.", progress = "그대가 만드는 가죽 세공품에 자연이 순응하도록 하려면 먼저 자연의 힘을 제어할 수 있어야 해요. 그 힘을 어떻게 제어할 것인지 당신이 만든 세공품을 가져와서 보여 주세요. 내 말을 잘 이해했는지 그걸로 판단하도록 하겠어요.", completion = "그대가 가져온 야생 가죽 세공품들을 보니 곧 자연이 그대에게 순응하게 될 것 같군요. 내 수업이 끝나면 그대의 세공품에 자연의 힘이 깃들게 될 거예요.\n\n차후에 수업을 받으려면 언제든지 내게 오도록 하세요. 그러면 당신이 가진 지식을 실제로 이용하는 방법을 가르쳐 주겠어요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n전통 가죽세공\n\n다음과 같은 것들을 받습니다:\n\n"},
[5144] = {title = "원소 가죽세공", objective = "이글거리는 협곡에 있는 사라 터너에게 불의 심장 2개, 물의 보주 2개, 대지의 핵 2개, 바람의 숨결 2개를 가져가야 합니다.\n\n이 퀘스트를 완료하면 원소 가죽세공술을 배울 수 있지만 용비늘 가죽세공술과 전통 가죽세공술을 배울 수 없습니다.\n\n퀘스트를 시작하기 전에 어떤 가죽 세공술을 배울지 결정하시기 바랍니다.", description = "내가 아는 건 원소 가죽세공에 관한 것밖에 없으니 원소의 위대한 힘을 받아들일 준비가 되어 있다면 내가 아는 모든 걸 가르쳐 주겠어요.\n\n하지만 알아두어야 할 게 있어요, <class>. 원소 가죽세공인의 길을 걷게 되면 용비늘 가죽세공술이나 전통 가죽세공술은 배울 수 없어요. 세 가지 기술 중에 한 가지를 통달하기도 벅차니까요. 그리고 당신이 자연을 이루고 있는 원소와 조화를 이루고 있는지 시험해 봐야겠어요. 내게 순수한 불, 물, 대지, 바람의 정수를 가지고 오세요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n원소 가죽세공\n\n다음과 같은 것들을 받습니다:\n\n"},
[5145] = {title = "용비늘 가죽세공", objective = "단단한 전갈 흉갑 2개와 단단한 전갈 장갑 2개, 그리고 닳아해진 용비늘 10개를 황야의 땅에 있는 토르카프 드래곤아이에 가져가야 합니다.\n\n이 임무를 완료하면 용비늘 가죽세공술을 익히게 되지만 원소 가죽세공술과 전통 가죽세공술은 익힐 수 없게 됩니다.\n\n일을 시작하기 전에 어떤 가죽세공술을 배울지 결정하시기 바랍니다.", description = "용비늘 가죽세공은 확실히 쉬운 일은 아니네만 분명 엄청난 보상이 따르는 일이지. 몇 가지만 약속해 준다면 내 자네에게 이 질 좋은 사슬 방어구를 어떻게 만들 수 있는지 가르쳐줌세.\n\n이 길을 선택했다면 원소 가죽세공술이나 전통 가죽세공술을 익히지 않을 것임을 약속하게. 세 가지 중 통달할 수 있는 기술은 한 가지 뿐이네. 그리고 실력 평가를 할 겸, 전갈의 껍질로 만든 자네 최고의 가죽세공품도 좀 필요하네. 마지막으로 자네가 재료를 조달할 수 있는 능력이 있다는 것을 증명하기 위해 용비늘 가죽세공의 주재료인 녹색용혈족의 비늘을 구해오게.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n용비늘 가죽세공\n\n다음과 같은 것들을 받습니다:\n\n"},
[5146] = {title = "원소 가죽세공", objective = "아라시 고원에 있는 브룸 윈터후프에게 불의 심장 2개, 물의 보주 2개, 대지의 핵 2개, 바람의 숨결 2개를 가져가야 합니다.\n\n이 퀘스트를 완료하면 원소가죽 세공술을 배울 수 있습니다. 이 퀘스트를 완료하면 용비늘 가죽세공술과 전통 가죽세공술을 배울 수 없습니다.\n\n퀘스트를 시작하기 전에 어떤 가죽 세공술을 배울지 결정하시기 바랍니다.", description = "내가 하는 일은 원소 가죽세공이네. 자네가 진정으로 물질의 강대한 힘에 관심이 있다면, 내가 아는 모든 것들을 가르쳐줄 생각이야.\n\n이 길을 선택한 이상 용비늘 가죽세공이나 전통 가죽세공을 익히려고 해서는 안 된다는 것을 알아두길 바라네. 세 가지 기술 중에 한 가지를 통달하기도 벅차니까 말이야. 그리고 자네가 자연의 속성과 연관되어 있다는 것을 증명하기 위한 적절한 증거가 필요하다네. 내게 순수한 불, 물, 대지, 바람의 정수를 가지고 오게나.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n원소 가죽세공\n\n다음과 같은 것들을 받습니다:\n\n"},
[5147] = {title = "현상수배 - 아르낙 그림토템", objective = "아르낙 그림토템을 처치하고 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 그 증거물을 갖다주어야 합니다.", description = "현상수배: 아르낙 그림토템\n\n추방자 아르낙을 극악무도한 살상과 납치 혐의로 현상수배한다. 이 범죄자에게 정의의 처단을 내리는 용감한 자에게는 후한 보상을 내릴 것이다.\n\n아르낙을 마지막으로 목격한 장소는 먹구름 봉우리다. 그를 처치한 증거물을 들고 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 가서 보상을 받기 바란다.", progress = "살인자 아르낙 그림토템에 대한 소식을 들었는가?", completion = "하하! 이거 희소식이로군! 사실 녀석에게 정의의 처단을 내릴 수 있을지 자신 없었네!\n\n자, 받게나. 그리고 고맙네. 아르낙이 저지른 일에 대해 들었을 때 내 피가 끓었는데 말이야!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n억센가죽 갑옷초원지기 다리보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5148] = {title = "전통 가죽세공", objective = "가시덤불 골짜기에 있는 세지브에게 야생 가죽 조끼와 야생 가죽 투구를 가져가야 합니다.\n\n이 퀘스트를 완료하면 전통 가죽세공술을 배울 수 있지만 용비늘 가죽세공술과 원소 가죽세공술을 배울 수 없습니다.\n\n퀘스트를 시작하기 전에 어떤 가죽세공술을 배울지 결정하시기 바랍니다.", description = "트롤 전통의 가죽세공술을 배우려면 자연의 본질을 이해해야 하오. 당신의 야생 가죽 방어구 제작 기술은 이미 통달했다는 건 알지만 이제는 그 기술을 완성의 경지로 끌어올릴 때가 된 것 같군. 내가 당신의 기술을 완성시켜 주겠소.\n\n그런데 한 가지 알아두어야 할 게 있소이다, <class>. 전통 가죽세공인의 길을 가게 되면 절대 용비늘 가죽세공술이나 원소 가죽세공술은 배울 수 없게 되오. 세 가지 기술 중에 한 가지만 배우기도 벅차니까 말이오. 그리고 내게 당신이 만든 야생 가죽 방어구 중에 가장 나은 것을 가져오도록 하시오. 그때 수업을 시작하도록 하겠소.", progress = "당신이 만드는 가죽 세공품에 자연이 순응하도록 하려면 먼저 자연의 힘을 제어할 수 있어야 하오. 그 힘을 어떻게 제어할 것인지 당신이 만든 세공품을 가져와서 보여 주시오. 내 말을 잘 이해했는지 그걸로 판단하도록 하겠소.", completion = "당신이 가져온 야생 가죽 세공품들을 보니 곧 자연이 순응하게 될 것 같군. 내 수업이 끝나면 당신의 세공품에 자연의 힘이 깃들게 될 것이오.\n\n앞으로 기술을 연마하려면 내게 말하도록 하시오. 그러면 당신이 가진 지식을 실제로 이용하는 방법을 가르쳐 주도록 하겠소.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n전통 가죽세공\n\n다음과 같은 것들을 받습니다:\n\n"},
[5149] = {title = "파멜라의 인형", objective = "파멜라의 인형을 찾아야 합니다.", description = "말레네 고모가요, 저한테요, 우리 아빠는 나가서 싸워야 하니까 나더러 여기 있으라고 했어요. 우리 아빠는 전세계에서 가장 용감한 사람이라구요!\n\n근데 아무리 여기서 기다려도 아직 안 오시구요, 가끔 나쁜 사람들이 와서 내게 귓속말을 하거든요. 아빠가 그들을 좀 쫓아냈으면 좋겠는데, 아빠는 아직도 돌아오지 않았어요!\n\n가끔 어두워질 때면 내 인형하고 놀고 싶은데, 마을에 두고 와서 그러지도 못하고 있어요.\n\n제 인형 좀 찾아다 주실래요?", progress = "제 인형은 찾으셨나요?", completion = "찾았군요! 내 인형을 찾아주셨어요! 야호, 정말 고맙습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5150] = {title = "배고픈 다단가!", objective = "다단가에게 다가가자 다단가가 당신을 올려다봅니다. 뭔가를 원하는 것 같습니다..\n\n아마 배가 고픈 것일 겁니다!\n\n거대한 초식 동물이 간식으로 먹기에 적합한 뭔가가 분화구에서 자라고 있습니다. 다단가는 덩치가 크기 때문에 뭘 가져오든지 많이 가져와야 합니다!", description = nil, progress = "다단가에게 다가가자 다단가가 당신을 올려다봅니다. 뭔가를 원하는 것 같습니다..\n\n아마 배가 고픈 것일 겁니다!\n\n거대한 초식 동물이 간식으로 먹기에 적합한 뭔가가 분화구에서 자라고 있습니다. 다단가는 덩치가 크기 때문에 뭘 가져오든지 많이 가져와야 합니다!", completion = "씨앗을 다단가의 앞에 갖다 놓자 다단가가 기뻐하는 듯합니다.\n\n간식에 대한 대가로 갈색으로 포장된 꾸러미를 이쪽으로 밀어줍니다!", rewards = "다음과 같은 것들을 받습니다:\n\n포장된 갈색 상자"},
[5151] = {title = "초전도 장치", objective = "퓨마를 처치하고 초전도 장치와 퓨마 우리 열쇠를 위즐로 베어링샤이너에게 돌려주어야 합니다.", description = "켄타우로스가 우리 짐마차를 공격했을 때 저만 간신히 살아남았어요! 희귀하지만 힘이 아주 센 퓨마가 제가 가장 아끼는 장치를 목에 걸고 있어요. 흥! 켄타우로스 놈들도 그 사나운 짐승 앞에서는 벌벌 기더군요!\n\n여기 퓨마 우리 열쇠를 드릴게요. 켄타우로스 녀석들이 다 훔쳐가도 퓨마한테는 손도 못 댔죠. 가서 퓨마를 처치하고 제 초전도 장치를 가져다주면 보상을 드리겠습니다.\n\n여기서 바로 북쪽에 부서진 짐마차가 있어요.", progress = "내 초전도 장치는?", completion = "내 초전도 장치! 이걸 뭐에 쓸지 알아내려면 한동안 꽤나 정신 없겠어...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n발명가조합 반지"},
[5152] = {title = "말레네 고모", objective = "안돌할 폐허 남쪽에서 말레네와 대화해야 합니다.", description = "으앙, 전 너무 외로워요! 우리 가족들은 다 어디 있는거죠? 말레네 고모는 나더러 여기 있으라고 했지만 아직도 돌아오지 않고 있어요! 그리고 아빠는... 우리 아빠를 본 적이 있으세요?\n\n어쩌면 말레네 고모는 아빠가 어디 계시는지 알지도 몰라요. 고모는 안돌할 근처 남쪽에 있는 집에 살고 있어요. 음, 고모 집은 언덕 위에 있었던 것 같아요... 고모가 그렇게 말했어요.\n\n 제발요. <오빠/언니>는 내 친구니까 우리 고모한테 물어봐 주실 거죠?", progress = nil, completion = "파멜라를 봤다고요? 그 아이는 어떤가요? 살아 있나요? 오, 불쌍한 파멜라! 그저 어리고 착한 아이일 뿐인데...\n\n그 아이가 자기 아빠가 어떻게 되었는지 알고 있던가요? 우리 오빠, 조셉 말이에요.\n\n안 되요... 그 아이는 조셉 오빠에게 무슨 일이 일어났는지 이해할 수 없을 거예요. 이해할 수 있다고 해도 난 도저히 말 못하겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5153] = {title = "이상한 역사가", objective = "조셉의 결혼반지를 크로미에게 가져가야 합니다.", description = "조셉 오빠가 딸과 함께할 수 있기를 바랬지만 부질없답니다. 그의 영혼은 스컬지에 의해 망가졌고, 이제 그는 괴물이 되어버렸어요. 오, 오빠는 정말 불쌍한 사람이에요! 그래도 그의 불행한 운명을 바꿀 수 있는 방법이 있을지도 몰라요.\n\n밖의 공동묘지에서 조셉의 묘비를 찾아보세요. 그의 시체는 이미 몇 년 전에 짓밟히고 망가져서 찾을 수 없겠지만, 묘비 안에는 그의 결혼 반지가 있을 거예요. 그 반지를 크로미에게 가져가세요. 크로미는 이상한 힘을 지닌 알 수 없는 노움 친구에요.\n\n크로미는 안돌할의 북서쪽 구석에 있는 한 여관의 폐허에 기거하고 있어요.", progress = "때마침 잘 왔네요. 당신 미래에서 온 것은 아니죠?", completion = "이게 뭐죠? 결혼 반지인가? 어디보자...\n\n오! 이 반지는 한때 훌륭한 자의 수중에 있었지만 그의 과거는 엄청난 비극의 흔적이 묻어 있군요.\n\n당신은 그를 돕기 위해 여기까지 온 건가요? 이미 늦어버렸지만... 어쩌면 과거로 돌아가서 우리가 그를 도울 수 있을지도 몰라요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5154] = {title = "다로우샤이어 연대기", objective = "안돌할에 있는 다로우샤이어 연대기를 크로미에게 갖다주어야 합니다.", description = "조셉 레드패스를 구하기 위해선 그의 과거를 알아야만 해요. 다로우샤이어의 기록에서 뭔가를 알 수 있을 것 같은데... 안돌할의 마을회관에 있는 그 책 말이에요.\n\n내게 그 책을 가져다주세요. 그러면 우리가 조셉의 운명을 알 수 있을 테고, 운이 좋다면... 바꿀 수 있을지도 몰라요!", progress = "책은 찾았나요?", completion = "찾았군요! 잘했어요.\n\n그 책을 읽어봤나요? 혹시 조셉 레드패스에 대한 내용이 있지 않던가요? 만약 있다면 우리는 그를 도와줄 수 있을 거예요!\n\n흐음, 다로우샤이어 연대기는 불안한 이야기의 연속이군요. 여기에 쓰여있기를 조셉 레드패스는 타락했고, 스컬지의 고위직으로 편입되었다는군요! 그리고는 다로우샤이어의 병사들을 배신했다고 하네요.\n\n이건 정말 괴로운 운명이군. 할 수 있다면 그의 운명을 바꿔봐야 하지 않을까요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5155] = {title = "자에데나르의 힘", objective = "자에데나르에 가서 자에데나르 사냥개 4마리, 자에데나르 수호병 4명, 자에데나르 숙련사제 6명, 자에데나르 이교도 6명을 처치하고 그레타 모스후프에게 돌아가야 합니다.", description = "제가 당신을 믿어야 한다면 먼저 스스로 증명해 보이세요.\n\n아제로스 전역에 깔린 악마들의 수괴인 어둠의 의회와 당신이 친구인지 적인지 전 알아야겠어요.\n\n악령의 숲 중앙으로 더 들어가 보세요. 서쪽에 보면 자에데나르로 가는 길이 있을 겁니다. 그곳에서 어둠의 의회는 불타는 군단과 합세하여 음모를 꾸미고 있어요.\n\n어둠의 의회가 거처로 삼고 있는 지하굴 속으로 들어가 그들을 모조리 처단하세요. 일을 마친 후 제게 돌아오면 그때는 당신을 믿을 수 있겠지요.", progress = nil, completion = "멋지군요. 그들의 머릿수도 줄었으니 이제 몰아붙일 수 있을 거예요.\n\n실제로 보니 어떻던가요? 예상대로 강하던가요? 상상보다 훨씬 더 무시무시했나요? 아니면 시시한 졸개들일 뿐이라고 느꼈을지도 모르겠군요. 정말 그렇다면 좋은 일 아닌가요?\n\n자세한 무용담은 나중에 듣기로 하죠. 신경 쓸 일이 너무 많아서요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5156] = {title = "오염 확인", objective = "불벼락 골짜기를 탐색하는 동안 혼돈의 불길 2마리와 혼돈의 소산물 2마리를 처치해야 합니다. 분화구를 조사해 아직도 부패한 물이 남아 있는지 확인하고 악령의 숲의 타론 레드페더에게 돌아가야 합니다.", description = "여기서 동쪽으로 나가 길을 따라 북쪽으로 가다 보면 불벼락 골짜기라는 곳이 나오지. 지난 대전쟁 당시 지옥불정령들이 소환된 자리일세. 그들이 내려온 흔적이 아직도 그 땅 위에 상처로 남아 있다네.\n\n그런데 궁금한 것이, 아직도 그 지역에 혼돈의 존재들이 남아 있을까? 그리고 몇 년 전에 지옥불정령들이 추락할 때 생긴 분화구에 악취가 나는 부패한 물이 고였었는데 아직도 남아 있을까? 나를 좀 도와주지 않겠나, <name>? 조심해야 할 걸세. 지옥불정령들은 눈앞에 있는 모든 것들을 파괴하는 존재이니...", progress = nil, completion = "살아있어서 다행이네, &lt;name&gt;. 그 더러운 물이 아직도 남아 있다는 것은 솔직히 마음에 걸리지만... 나는 여기 악령의 숲에서 단 한 곳이라도 순수한 물을 얻을 수 있는 장소를 찾으려고 했었네. 하지만 실패한 것 같군. 그런 곳이 있다면 이 땅이 훨씬 쉽게 되살아날 수 있었겠지.\n\n한때 아름다웠던 이 숲을 여행자들은 그냥 지나쳐 갈 뿐이지만 난 이곳에 남아 숲을 파괴하고 있는 존재들을 처치하고 생물들을 타락으로부터 지켜내겠네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5157] = {title = "부패한 물 채취", objective = "빈 수통을 자에데나르 중심부의 달샘으로 가져가서 채운 다음 악령의 숲에 있는 그레타 모스후프에게 가져 가야 합니다.", description = "자에데나르로 깊숙이 들어가면 어둠의 요새가 있어요. 모든 사악한 기운과 악의 근원이죠...\n\n어둠의 의회는 분명 방어 계열의 마법으로 요새의 성벽을 보호하고 있을 거예요. 내가 점을 쳐서 자세한 정보를 알 수만 있다면 저들의 마법 방어막을 무너뜨릴 수 있어요. 그렇게 되면 어둠의 의회를 정탐하여 누가 수장인지 알 수도 있을 거예요.\n\n가능하다면 이 빈 수통을 들고 가서 자에데나르 중심부에 있는 달샘의 물을 모아 주세요.", progress = "부패한 달샘 물을 채취해 왔다면 먼저 정화시켜야 해요. 그런 다음 어둠의 요새를 감싸고 있는 방어막에 부어야 무너뜨릴 수 있습니다. 그러면 충분한 시간을 벌어서 그 안의 방들을 확실하게 살펴보고 누가 이 광신도들을 주도하는지 알아낼 수 있을 거예요.\n\n대지모신이 우리와 함께하길...", completion = "이거면 됐어!\n\n이제 이 부패한 달샘의 물을 정화시키기만 하면 방어막을 파괴할 수 있어요. 조금 발 품만 팔면 되요. 그렇게 힘들진 않을 테니까.\n\n빨리 빨리 하자고요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5158] = {title = "영혼의 도움을 찾아서", objective = "부패한 달샘 물을 불모의 땅에 있는 이슬렌 워터시어에게 가져 가야 합니다.", description = "이 부패한 물을 불모의 땅으로 가지고 가세요. 내 친구, 주술사 이슬렌 워터시어는 톱니항 남쪽 해안에 은밀한 장소에 있습니다. 그녀는 강력한 주술로 우리를 도와줄 거예요. 그녀는 물의 정령들과 언제나 친밀했으니까... 정의를 위한 일이라면 그녀와 물의 정령들을 설득할 수 있을 거예요.\n\n해안 끝자락을 따라 은밀한 곳에 위치한 조그만 야영지를 발견할 수 있을 거예요. 그리고 해적들은 무시하세요... 그들은 하찮고 성가신 존재일 뿐, 당신에게 큰 해를 끼칠 수는 없을 테니까.", progress = "당신은 그저 톱니항으로 가는 평범한 여행자로는 보이지 않는군요. 이리 오셔서 우리 야영지에서 좀 쉬었다 가세요. 그런데 혹시 긴히 하실 말씀이라도 있으신가요?", completion = "아, 이 부패한 달샘의 물을 정화하셔야 하는군요. 악령의 숲에서 악의 힘을 몰아내는 것은 물론 정의로운 일이지만, 물을 정화하는 것은 제 일이 아니에요. 내 친구인 물의 정령들에게 물어보도록 하죠. 선한 목적을 위해서라면 그들도 기꺼이 도울 겁니다.\n\n조금 기다리시면 그들에게 당신의 사정을 전해 드리지요. 그들도 나와 뜻을 같이 한다면 참 좋겠네요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5159] = {title = "악령의 숲으로 정화된 물 가져가기", objective = "정화된 달샘 물을 악령의 숲에 있는 그레타 모스후프에게 가져가야 합니다.", description = "제게 감사할 것까지는 없어요. 정령들에게 고마워 해야죠. 몸소 헌신해 당신을 도왔잖아요?\n\n여기 정화된 물을 드릴께요. 그레타에게 안부를 전해주세요. 그녀는 우리들보다 더 큰 악을 상대로 싸우고 있군요... 장담컨대 그녀는 반드시 해낼 거예요.\n\n하지만 어둠의 의회는 만만하지 않다는 걸 잊지 마세요.\n\n자, 어서 가서 그레타에게 물을 가져다주세요.", progress = "아, 돌아왔군요, <name>. 불모의 땅에서 이슬렌을 찾을 수 있었나요? 아니면 다른 방법으로 물을 정화하셨나요?", completion = "이 정도의 물이라면 우리 일에 쓰고도 남을 거예요.\n\n이슬렌이 도와주다니 정말 다행이군요. 정령들과 함께하는 그녀의 힘은 항상 강력했죠. 게다가 현명하기까지 하니까. 그래서 정령들도 그녀를 따르죠. 그들 모두 우리의 일을 지원해 준다니, 우리가 가는 길이 정의롭다는 믿음을 주니... 기쁘군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5160] = {title = "대섭정", objective = "여명의 설원으로 가서 헬레를 찾아 그녀에게 아우비의 비늘을 전해야 합니다.", description = "칼림도어로 가세요. 여명의 설원의 지독한 추위도 우리의 비행을 방해할 수는 없을 거예요. 여명의 설원에 다다르면 마즈소릴의 동굴을 찾으세요.\n\n마즈소릴의 빙판 마루 위에서 코볼트 룬들을 찾을 수 있을 거예요. 그 위에 서서 저의 비늘을 쥐고 있으면 우리의 대섭정이신 헬레님께로 이동하게 될 거예요.\n\n그분께 비늘을 건네주면 비늘로 저주받은 곳에서 무엇을 보고 느꼈는지 점 칠 수 있을 거예요.", progress = "만나서 반갑습니다.", completion = "점괘에는 죽을 운명의 자들의 일에 관여하지 않는 게 좋다고 나오는군요. 하지만 이 세계에선 항상 그렇게 할 수는 없습니다. 특히 우리들 중의 한 명이 이런 명령을 몹시 경멸하고 대항하고 있는 것을 보면 말입니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5161] = {title = "푸른용군단의 분노", objective = "계속하려면 헬레와 대화하십시오.", description = "우리는 데스윙의 졸개들이 무슨 일을 저지르려는지 알고 있고 그걸 반드시 막아야 한다는 것도 잘 안다.\n\n네파리안은 검은바위 산의 보호를 받고 있어 우리가 끼어들기가 굉장히 힘들어졌다.\n\n하지만 네가 원한다면 우리가 힘을 줄 수도 있느니라, 평범한 생명체여.\n\n네 앞에 펼쳐진 길은 위험으로 가득한 길이니라. 우리의 도움을 수락할 것인지는 네가 결정해야 하니 잘 생각한 후에 결정이 서면 나와 다시 대화를 하도록 하라.", progress = nil, completion = "그러면 그렇게 하도록 하지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5162] = {title = "푸른용군단의 분노", objective = "역병지대로 가서 안돌할에 사는 제지바와 대화하십시오.", description = "나는 마법력을 관할하고 이 마법력으로 너를 다음 목적지까지 보내주겠다.\n\n준비가 다 됐으면 여정을 시작하도록 하라. 서부 역병지대로 가서 제지바라는 자와 대화를 하라.\n\n고대 신들만큼이나 지혜롭고 확고부동한 땅만큼이나 인내심이 있는 자이니라. 안돌할에서 그를 찾아라.", progress = nil, completion = "나는 제지바. 사람들이 흔히 조각사라고 부르는 사람이오. 하지만 내가 조각을 하는 것은 석상 같은 것이 아니라 영웅들이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5163] = {title = "깜짝 기계설인 대작전", objective = "우미의 기계설인을 가지고 가서 아래 친구들에게 겁을 주어야 합니다.\n\n여명의 설원, 눈망루 마을에 있는 레각키\n타나리스의 가젯잔에 있는 스프링클\n운고로 분화구, 마샬의 야영지에 있는 퀵실\n\n모두에게 겁을 주고 나서 기계설인을 도로 우미에게 데리고 가야 합니다.", description = "다 끝났어요, <name>!\n\n벌써 친구들에게 편지를 보내 놀라게 해줄 게 있다고 알렸거든요?! 당신의 도움이 필요해요!\n\n기계설인을 드릴 테니 제 친구들을 방문해 설인이 제 친구들이 있는 쪽으로 걸어가게 작동시켜주세요.\n\n눈망루 마을에 있는 레각키, 가젯잔에 있는 스프링클, 그리고 마샬의 야영지에 있는 퀵실에게 설인을 보여준 후 제게 돌아와 어땠는지 좀 전해주세요!\n\n참, 그리고 제 기계설인도 다시 데리고 와주세요. 꼭이요!", progress = "제 친구들이 어떤 반응을 보일지 알고 싶어 죽겠어요!\n\n꿈에도 상상하지 못했을 거예요!", completion = "헤헤! 두 번 다시는 저를 놀리지 못할 거예요!\n\n도와줘서 고맙습니다, &lt;name&gt;. 당신 없이는 이렇게 큰 재미를 보지 못했을 거예요!", rewards = "다음과 같은 것들을 받습니다:\n\n기계설인"},
[5164] = {title = "무법의 시대 일람", objective = "제지바의 뒤에 있는 무법의 시대 일람을 읽어야 합니다.", description = "헬레님은 가장 훌륭한 정의의 도구를 선택하신 것입니다. 무법의 시대 일람을 읽고 깨우치시기 바랍니다.\n\n인내를 갖고, 주어진 임무를 수행하며, 생존한다면, 그대는 영웅이 될 것입니다.", progress = nil, completion = "이 책은 알아볼 수 없는 글귀와 기호로 가득한 수백 장의 페이지로 이루어져 있습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5165] = {title = "방어막 파괴", objective = "정화된 달샘 물을 써서 악령의 숲에 있는 어둠의 요새를 감싸고 있는 화로 4개를 파괴한 후 에메랄드 성소에 있는 그레타 모스후프에게 돌아가야 합니다.", description = "이제 자에데나르로 다시 가야 해요. 아마 어둠의 요새 전체를 방어막이 감싸고 있을 거예요. 화로를 파괴해 불을 끄면 어둠의 의회가 만든 방어막이 잠깐 동안이라도 사라질 거예요. 저는 그때까지 기다리겠어요. 방어막이 없어지면 요새 내부를 둘러보고 그 괴물들의 수괴가 누구인지 밝혀 내도록 하죠. 그렇게 한 후에야 그들을 칠 수 있을 테니까.", progress = nil, completion = "마지막 화로의 불이 꺼지자마자 당신의 얼굴을 볼 수 있었죠. 정말 수고했어요, &lt;name&gt;.\n\n어둠의 의회의 흑마법사들, 그들이 마법의 방어막을 다시 펼치기 전에 몇 가지 사실을 알아냈어요. 이 정보가 유용하게 쓰여야 할 텐데...\n\n지금은 좀 쉬도록 하세요. 방금 알아낸 것들을 말해드리죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5166] = {title = "오색용군단 흉갑", objective = "오색용군단 흉갑을 제작하려면 다음 재료를 모아 \"조각사\" 제지바에게 가져가야 합니다.\n오색 등껍질 1개\n반짝이는 오색 비늘 10개\n영웅의 피 10개\n닳아 해진 누더기골렘 조각 10개", description = "오색용군단의 무자비한 공격을 막아낼 흉갑은 아이러니하게 만들어졌다.\n\n우리가 상대하는 바로 그 야수들의 비늘을 나이 든 오색비룡이나 오색용의 껍질에 꿰매야 하는데, 이 나이 든 용들은 이제 이 세상에 존재하지 않는 것으로 알려져 있고 앞으로도 존재해서는 안 된다.\n\n마지막으로 필요한 재료는 영웅의 피로 아마도 가장 구하기 어려운 것일 것이다.\n\n흉갑은 조각사가 만들어야 한다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n오색용군단 흉갑"},
[5167] = {title = "오색 파멸자의 다리갑옷", objective = "오색 파멸자의 다리갑옷을 제작하려면 다음 재료를 모아 \"조각사\" 제지바에게 가져가야 합니다.\n오색 등껍질 1개\n반짝이는 오색 비늘 10개\n영웅의 피 10개\n어둠의 허물 5개", description = "다리보호구의 기초 형태를 잡는데 성숙한 오색 비룡의 껍질이 필요하다. 그 다음 철사 뼈대 위에 반짝이는 오색 비늘을 깔아 영웅의 피로 마법을 부여하고 마지막으로 안쪽 경갑에 어둠의 허물을 충분히 붙이면 된다.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n오색 파멸자의 다리보호대오색 파멸자의 다리갑옷\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5168] = {title = "다로우샤이어의 영웅", objective = "카를린 레드패스에게 다빌의 성서와 레드패스의 방패를 가져가야 합니다.", description = "당신이 가져다 준 다로우샤이어 연대기에서 다로우샤이어의 영웅들의 이야기를 읽었소. 다로우샤이어의 영웅은 내게 깊은 감명을 주는군.\n\n그 책에는 성기사 다빌 라이트파이어에 대한 이야기며 십자군이 어떻게 그의 성서를 하스글렌 마을회관으로 가져갔는지에 대한 이야기가 나와 있다오.\n\n내 형제인 경비대장 레드패스에 대한 구절도 있었소. 레드패스가 배신한 이후 그의 방패는 부서진 채 내버려져 전혀 어울리지 않는 장소인 가론의 흉가의 헛간 근처에 방치되어 있다오.\n\n그 방패는 운명과 비극에 휩싸여 있으니 가서 회수해 오시오.", progress = "유물을 가져왔소?", completion = "성서와 방패를 가져왔군!\n\n이들의 역사는 다로우샤이어의 역사와 밀접한 관련이 있소. 운명이 그들을 다시 이어줄 것이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5181] = {title = "다로우샤이어의 악당들", objective = "희망의 빛 예배당에 있는 카를린 레드패스에게 호르구스의 해골과 부러진 마르두크의 검을 가져가야 합니다.", description = "다로우샤이어 연대기에는 다로우샤이어 전투의 악당들에 대해서 적혀 있소. 전투가 진행되는 동안 얼라이언스 군대가 구울 군주인 약탈자 호르구스를 처치하고 그 시체를 코린 삼거리 북서쪽에 있는 호수에 던져 넣었으며, 그 해골이 아직도 그 호수에 남아 있다고 쓰여 있소.\n\n검은 마르두크는 물리치지 못했지만 그의 이름난 검은 산산이 부서져 분실되었는데, 코린 삼거리 서쪽에 있는 골짜기 밑바닥에 있다고 하오.\n\n이 물건들을 회수해 오시오. 왠지 모르겠지만, 그 물건들의 운명이 당신에게 달려 있다는 확신이 드는군.", progress = "해골과 검은 찾았소?", completion = "찾았군! 수고했소! 이 유물들에는 나도 완전히 이해하지 못하는 힘이 담겨 있소. 언젠가 당신이 이용하게 될 힘이지.\n\n또한 이 유물들은 내게 어두운 기억을 불러일으키는군. 죽음과 배반의 기억, 그리고 다로우샤이어 최후의 밤에 대한 기억을 말이오...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5201] = {title = "눈사태일족의 침략", objective = "리베른 프로스트윈드가 눈사태일족 주술사 5마리와 눈사태일족 펄볼그 5마리를 처치하도록 요청했습니다.", description = "대부분은 내 존재를 느끼지 못하는 이곳 여명의 설원에는 성가신 녀석들이 아주 깊게 뿌리내리고 있다네. 바로 눈사태일족 펄볼그들이지.\n\n그 펄볼그들을 직접 공격해본 적은 없지만, 미친데다가 눈 앞에 보이는 모든 것들을 죄다 겁내는 모양이야. 때를 잘못 맞춰 지나가는 길에 녀석들을 만난 운 나쁜 생명체들이 수도 없이 죽임을 당하는 것을 보았다네.\n\n녀석들의 소동에 진절머리가 나는군. 부디, 녀석들을 물리치도록 도와주게. 그 펄볼그들을 해치우고 녀석들이 이곳 눈호랑이 바위에 접근하지 못하도록 해주게.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[5202] = {title = "이상한 붉은 열쇠", objective = "자에데나르를 뒤져 이 붉은 열쇠의 용도를 알아내야 합니다.", description = "이 자그마한 붉은 열쇠는 어떤 뼈로 만들어진 것 같습니다. 아주 약해 보이지만 손에 쥐여보니 제법 묵직합니다. 왜 어둠의 의회에 속한 자가 이런 물건을 지니고 있는 걸까요? 아마도 자에데나르 안에 이 이상한 열쇠로 열 수 있는 무언가가 있을 것입니다.", progress = "과연 이 우리 속에서 제가 빠져나갈 수 있을까요?\n\n놈들이 섬기는 악마에게 산 제물로 희생되는 건 시간 문제일 뿐인 것 같군요. 짐승 같은 놈들!", completion = "아니, 열쇠를 찾으셨군요! 여기서 탈출할 수 있도록 제게 열쇠를 주세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5203] = {title = "자에데나르 탈출", objective = "아르코나린을 그녀의 방어구와 라이트포지가 있는 곳까지 호위해 간 후, 함께 어둠의 요새에서 빠져나가야 합니다. 그런 다음, 악령의 숲에 있는 제시 문보우를 찾아가 그녀의 친구들에게 무슨 일이 있었는지 알려 주어야 합니다.", description = "하지만 그 전에 꼭 하고 갈 일이 하나 있어요. 정말 괴로운 일이긴 하지만요. 트레이의 검, 라이트포지를 찾아 어둠의 요새에서 탈출한 뒤, 제 상관들에게 이곳 상황을 보고해야 해요. 절 좀 도와주시겠어요, <name>?\n\n그대는 벌써 저 위로 이르는 길까지 살아남을 수 있음을 증명해 보이셨잖아요. 제 방어구와 검은 여기서 멀지 않은 곳에 있어요.\n\n여기서 탈출하면 저는 다르나서스로 갈 테니 그대는 잿빛 골짜기 경계에 있는 제 친구 제시를 찾아가 주세요. 그 부근에 있는 에메랄드 의회 야영지에서 만나기로 했었거든요.\n\n어떠세요, <name>? 절 조금만 더 도와 주실 수 있겠어요?", progress = nil, completion = "아르코나린의 탈출을 도운 것이 바로 그대였다고요? 절 찾아 오셔서 정말 다행이로군요. 얼마 전 아르코나린이 다르나서스로 가는 길에 잠시 들렀어요. 힘겹게 라이트포지를 들고서 드루이드에게 치유를 받을 틈도 없이 서둘러 떠나더군요. 굉장히 급한 일이라면서 말이에요.\n\n그래도 트레이의 영혼과 만난 일은 얘기해 주었어요. 은빛성기사단의 훌륭한 기사가 그렇게 끔찍한 종말을 맞이하다니... 아르코나린은 내색을 하지 않았지만, 전 알아요. 그녀가 마음 속으로 너무나 아파하고 있다는 걸. 가장 가까운 친구를 하나 잃었으니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5204] = {title = "정의의 복수", objective = "자에데나르로 돌아가 서큐버스 라카이아를 처치한 후, 트레이 라이트포지의 유해를 찾아와야 합니다.", description = "그녀는 괜찮은 척하고 싶었을 거예요. 혼자서 모두 감내할 수 있다고 했죠. 하지만 전 알아요... 제가 걱정할까봐 그런 거란 걸. 트레이의 비참하고 고통스러운 죽음이 오랜 시간 그녀의 기억에 남아 가슴을 갈가리 찢겠지만, 우리가 해줄 일은 아무것도 없군요. 하지만 그 아픔을 조금이나마 달래 줄 방법이 있어요\n\n<name>, 어둠의 요새로 돌아가서 트레이를 고문해 죽인 자를 처치하고, 트레이의 유해를 찾아 오세요. 아르코나린이 홀로 애처롭게 울고 있는 동안 우리가 이 일을 마무리 짓도록 하죠.", progress = "유해를 조사해 보니 은빛성기사단의 트레이 라이트포지의 것이 틀림없습니다. 최근 어둠의 요새에 포로로 잡혀 있던 아르코나린이 탈출하도록 도와준 일이 떠오릅니다. 그 나이트 엘프가 트레이를 아꼈던 것처럼 나에게도 그런 친구가 있는지 잠시 떠올려 봅니다.\n\n잠시 생각을 정리해보니, 먼저 트레이를 고문한 자를 처치해 복수를 하고 나서 트레이의 시신을 수습해 제시에게 가져가는 것이 맞는 것 같습니다.", completion = "조심스럽게 이 성기사의 유해를 수습합니다. 이제 그의 영혼이나마 지난날의 고통과 아픔으로부터 해방되었을 것입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n트레이 라이트포지의 유해"},
[5206] = {title = "다로우샤이어의 약탈자들", objective = "동부 역병지대에 있는 카를린 레드패스에게 텅빈 해골 5개와 불가사의한 수정을 가져가야 합니다.", description = "크로미가 말하길 당신이 가져온 유물은 강력한 마법에 반응을 보이는데 한 가지가 더 필요하다고 하오. 바로 다로우샤이어 전투에 참전했던 스컬지의 해골이라는군.\n\n이 수정을 가지고 가서 스컬지 용사를 사냥해 해골을 가져 오시오. 이 수정에는 마법이 걸려 있어 전투에 참전한 용사의 해골 위에 비추면 소리가 울릴 것이니 소리가 울리는 텅 빈 해골을 나에게 가져오시오.\n\n자, 출발하시오. 북쪽의 맹독의 숲과 서쪽의 곰팡이 계곡에 가면 스컬지 용사 녀석들을 볼 수 있을 것이오.", progress = "해골을 가져 왔소? 크로미가 말하길 그녀의 마법에 이 해골이 꼭 필요하며 이 마법을 이용해 다로우샤이어를 구할 수 있다고 하오.", completion = "찾아냈군! 대단하오!\n\n난 이걸 어떻게 사용하는 건지는 모르겠으나 해골의 힘을 느낄 수가 있소. 이것들은 내 고향 다로우샤이어와 관련이 있는 것이 분명하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5210] = {title = "카를린 레드패스", objective = "동부 역병지대에 있는 카를린 레드패스에게 확장된 다로우샤이어 연대기를 가져가야 합니다.", description = "내 마법으로 다로우샤이어 연대기의 뒷장에 내용이 더 추가되어 이제는 전투 후의 역사까지 기록되어 있어요. 추가된 내용 중에 조셉이 배신하고 벌인 일들에서 살아남은 자인 카를린 레드패스에 대한 이야기가 있군요. 카를린은 지금 역병지대의 동쪽에 있는 희망의 빛 예배당에 있어요.\n\n책을 가져가서 그와 얘기해 보도록 하세요.", progress = "당신 서쪽에서 왔소? 로데론의 나머지 왕국들은 어떻소이까? 안돌할이 무너졌다는 것은 알고 있지만 설마 스컬지가 티리스팔 숲까지 내려온 건 아니겠지?", completion = "이 책은 뭐요? 다로우샤이어 연대기? 그곳은 전쟁 전에는 내 고향이었소... 그 전투에서 마을이 점령되어 파괴되기 전까지는 말이오! 왜 이 책을 내게 가지고 온 거요?\n\n음? 여기엔 전투 후의 이야기까지 적혀있지 않은가! 내 얘기도 있군! 또 죠셉 형에 관한 이야기도! 이 책에 쓰여있는 게 정말이오?\n\n사실인지 알아 봐야하오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5211] = {title = "다로우샤이어의 병사들", objective = "15명의 다로우샤이어 주민들의 원혼을 자유롭게 하고 카를린 레드패스에게 돌아가야 합니다.", description = "다로우샤이어의 전투에서 많은 다로우샤이어의 병사들이 죽었소. 그 중 상당수는 스컬지를 섬기는 자가 되어 다시 일어났지! 이 불쌍한 영혼들을 찾아서 그들의 고통에 종지부를 찍어주시오!\n\n식인 구울, 딸깍이 구울, 전염병 구울을 잡으시오. 그 중에도 많은 수는 이 다로우샤이어의 착한 주민들이었을 터이니, 지금 그들이 머물고 있는 육체를 파괴해버리면 그들의 영혼을 자유롭게 할 수 있소.\n\n역병의 숲과 코린 삼거리, 그리고 동부 역병지대에서 또 다른 스컬지의 요새를 발견할 수 있을 것이오.", progress = nil, completion = "당신이 나의 친구들의 영혼을 찾아서 그들을 해방시켰다니 정말 다행이오. 적어도 몇 명의 다로우샤이어의 병사들만이라도 스컬지의 가혹한 지배에서 벗어난 걸로 위안을 삼을 수 있겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5212] = {title = "거짓말하지 않는 육체", objective = "스트라솔름에서 20개의 역병걸린 살덩어리 견본을 베티나 비글징크에게 가져다주어야 합니다. 스트라솔름의 어떤 생물에서든 살덩어리 견본을 구할 수 있을 것 같습니다.", description = "이 세계에서 과학을 연구하는 집단은 포세이큰 연금술사뿐만이 아니랍니다.\n\n나도 역병지대를 몇 년간 연구했어요. 최근까지만 해도 우리는 역병의 원인이 사라지고 있다고 생각했는데, 나는 이곳 역병지대에서 놀라운 사실을 발견했어요! 역병이 점점 강력해지고 있다는 것이에요!\n\n더 많은 실험을 해 봐야겠어요! 역병의 가장 유력한 원인은 최근에 죽은 시체들의 썩은 육체에요. 스트라솔름으로 가서 견본을 좀 가져다주세요.", progress = "날 보고 '넌 너무 걱정이 많아!'라고 말하는 친구들에게 난 '넌 너무 태평해'라고 한답니다!", completion = "역병을 진행하는 인자의 화학구조가 뭔가 변한 것 같군요. 흠, 더 많은 정보가 필요해요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5213] = {title = "활성 역병 인자", objective = "스트라솔름으로 가서 지구라트를 조사해야 합니다. 스컬지 자료를 찾아 베티나 비글징크에게 돌아가야 합니다.", description = "흠, 당신이 스트라솔름에 좀 더 깊이 파고들어 가줘야겠어요.\n\n첫 번째 문을 지나가다 보면 지구라트들이 보일 거예요. 우리는 스컬지가 지구라트에서 많은 힘을 얻는다는 것을 알고 있어요. 그 지구라트를 조사하고 정보를 가지고 돌아오세요.", progress = "우리는 지금 이 새로운 역병 인자가 무엇인지 연구하고 있어요!", completion = "멋져요! 이것들을 해부하고 조사하는 데만도 몇 달은 걸릴 거예요. 은빛 여명회를 대신해서 당신의 노고에 감사 드리고 싶네요.\n\n은빛 여명회의 축복과 더불어, 이 여명의 문장이나 여명의 룬 중의 하나를 고르도록 하세요. 당신은 은빛 여명회의 편에 서서 스컬지석을 모으기 위해 위임봉 대신 이것 중 하나를 사용할 수 있습니다. 사용하던 것을 잃어버리면 내게 알려주세요. 다른 것으로 바꿔 드리도록 하죠.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n여명의 문장여명의 룬\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5214] = {title = "위대한 에즈라 그림", objective = "스트라솔름에서 에즈라 그림의 최고급 담배를 회수하여 스모키 라루에게 가져가야 합니다.", description = "에즈라에게 일어난 일은 정말 안됐어... 마을 전체가 약탈당했건만 에즈라는 그의 소중한 물건들을 두고 도망갈 수가 없었던 걸세. 그는 마지막으로 내게 이렇게 말했네. '그놈들의 저주받은 더러운 손길이 닿게 하느니 차라리 내가 불태워 버리는 게 나아!' 라고 말일세.\n\n나라고 해서 그 좋은 물건들이 아깝지 않았겠나만 나는 바보가 아니네. 나는 그 날 에즈라와 그의 가게를 보고서도 몸을 피했지. 그 친구는 그의 가게와 함께 불길 속에서 죽음을 맞이한 것 같지만, 그의 유명한 담배가 한 갑이라도 남아있을지도... \n\n어떻나? 이 스모키를 위해 담배를 찾아다 주겠나?", progress = "난 더 이상 참을 수 없네! 제발 날 도와주게! 오, 난 죽어가고 있어!", completion = "오오, 소중하고도 소중한 내 담배! 내가 얼마나 널 그리워했는지 아니...", rewards = "다음과 같은 것들을 받습니다:\n\n스모키의 라이터"},
[5215] = {title = "스컬지 가마솥", objective = "서부 역병지대의 서리바람 거점에 있는 대여사제 맥도널과 대화해야 합니다.", description = "옛 로데론 왕국에는 8개의 가마솥이 있었소. 그 중 4개는 이곳 서쪽에, 그리고 나머지 4개는 동쪽에 감춰져 있지. 이 가마솥들은 대기에 독을 뿌려 이 땅 전체에 역병을 퍼뜨리고 있소.\n\n켈투자드의 강령술은 너무 강력해서 이 가마솥들을 아예 멈추게 할 수는 없지만 우리에게 유리하도록 전복시킬 수는 있을 것 같소이다. 부사령관인 대여사제 맥도널이 이 임무를 관리할 테니 나머지 전황 요약은 그녀에게 듣도록 하시오.", progress = nil, completion = "이 수난의 시기에 성스러운 빛의 축복을 받으시기를, &lt;class&gt;|1이여;여;. 스컬지의 가마솥이 녀석들에게 불리하도록 전복시키는 이번 임무를 관리하게 되어 기쁩니다.\n\n우리 목표는 가마솥이 내뿜는 역병의 구조를 바꿔 반대로 스컬지를 공격하는 것입니다. 역병의 구조를 바꾸려면 이곳 서부 역병지대에 있는 네 개의 가마솥 각각에 접근할 수 있는 방법을 확보해야 합니다.\n\n비열한 스컬지와 맞설 영광스러운 전투를 준비하시기 바랍니다, 영웅이여!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5216] = {title = "목표: 펠스톤 농장", objective = "서부 역병지대의 펠스톤 농장으로 가서 그곳에 있는 가마솥군주를 찾아 물리치십시오. 가마솥군주가 가마솥으로 통하는 열쇠를 지니고 있을 수도 있습니다. 빈 펠스톤 농장 병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", description = "서부에 있는 네 개의 가마솥 중에서도 펠스톤 농장에 있는 가마솥은 접근 방법을 찾기가 가장 쉽답니다. 그곳에는 스컬지가 경험 없는 부대를 배치해 두었지만 얕잡아 보지는 마세요.\n\n안돌할의 북서쪽에 있는 펠스톤 농장으로 가서 그곳에 있는 가마솥군주와 맞서 싸우십시오. 가마솥군주에게 가마솥으로 통하는 열쇠가 있다고 알고 있습니다. 열쇠로 문을 열고 들어가 가마솥 안에 든 독의 견본을 이 병에 담아 오십시오. 반작용 물질 개발에 필요한 물질입니다.", progress = "가마솥으로 통하는 문이 굳게 잠겨 있습니다. 열려면 열쇠를 찾아야 합니다.", completion = "가마솥군주 창자아귀를 처치하고 얻은 열쇠가 꼭 들어맞습니다. 문을 열자 가마솥 안에 소용돌이치고 있는 알 수 없는 응축 조합물에서 지독한 악취가 납니다.\n\n아래 부분에 병이 들어맞는 작은 꼭지가 있어 서리바람 거점에 있는 대여&lt;class&gt; 맥도널에게 가져다줄 견본을 뽑을 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5217] = {title = "서리바람 야영지로의 귀환", objective = "서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 펠스톤 농장 병을 가져가야 합니다.", description = "조사할 견본이 될 가마솥의 유독성 혼합물을 빈 병에 충분히 채웁니다.\n\n독극물을 확보했으니 서리바람 야영지에 있는 대여사제 맥도널에게 돌아가 임무를 완수해야 합니다.", progress = "서리바람 야영지에 무사히 돌아와서 다행입니다. 가마솥 임무는 어떻게 진행되고 있나요?", completion = "수고했습니다. 연금술사 알빙턴이 이걸 분석하고 가마솥에 집어넣을 반작용 물질을 만드는 데는 그리 오래 걸리지 않을 겁니다. 이 반작용 물질을 대기에 충분히 퍼뜨리면 이곳에 주둔하고 있는 스컬지를 약화시킬 수 있을지도 모릅니다.\n\n분명 이 임무를 계속 수행해야 합니다. 우리는 지속적으로 가마솥을 공격해 반작용 물질을 섞어야만 합니다. 마찬가지로 우리가 계속 진행할 수 있다면 스컬지와 전투를 벌일 때 우리가 훨씬 유리해질 겁니다!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신의 권능: 인내\n\n다음과 같은 것들을 받습니다:\n\n"},
[5218] = {title = "펠스톤 농장 가마솥", objective = "앞에는 스컬지의 역병 가마솥이 공기 중에 엄청난 양의 독을 뿜어대고 있습니다. 가마솥의 거대한 단 아랫부분에는 작고 특별할 것 없어 보이는 입구가 있습니다.\n\n이미 가마솥군주를 처치하고 그 열쇠를 얻었으니 역병에 대한 반작용 물질을 만들기 위해 적절한 재료를 마음대로 가마솥에 넣을 수 있습니다.", description = nil, progress = "앞에는 스컬지의 역병 가마솥이 공기 중에 엄청난 양의 독을 뿜어대고 있습니다. 가마솥의 거대한 단 아랫부분에는 작고 특별할 것 없어 보이는 입구가 있습니다.\n\n이미 가마솥군주를 처치하고 그 열쇠를 얻었으니 역병에 대한 반작용 물질을 만들기 위해 적절한 재료를 마음대로 가마솥에 넣을 수 있습니다.", completion = "가마솥의 혼합물에 재료를 넣자 공기 중에 뿜어져 나오는 내용물의 색과 결이 변합니다. 주변에 새로운 요소가 투입되자 멀리 떨어져서나마 가마솥 근처에 있던 스컬지들이 움찔하며 물러나는 듯합니다.", rewards = nil},
[5219] = {title = "목표: 달슨의 눈물", objective = "서부 역병지대의 달슨의 눈물로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 지닌 열쇠를 사용해 가마솥에 접근하십시오. 반드시 달슨의 눈물 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", description = "지금은 달슨의 눈물이라고 불리는, 한때는 농장이었던 곳의 들판에 역병 가마솥 하나가 있어요. 이제 우리는 스컬지의 계획을 좌절시키고 그들로 하여금 자신들의 사악한 음모의 피해자가 되어 쓰러지도록 하려는 것인 만큼 눈물을 흘릴 이유가 전혀 없습니다!\n\n안돌할에서 거의 정북 쪽에 있는 달슨의 눈물로 가서 그곳에 있는 가마솥군주를 제거하세요. 지난 번에 제거했던 녀석과 마찬가지로 열쇠를 지니고 있을 것이니 그 열쇠로 가마솥에 다가갈 수 있을 겁니다. 각 가마솥에는 다르게 조제된 고유한 독이 있으니 이 병에 가마솥 안 내용물의 견본을 담아 오세요.", progress = "가마솥으로 통하는 입구가 굳게 잠겨 있습니다. 입구를 열려면 열쇠를 찾아야 합니다.", completion = "가마솥군주 말비니어스를 처치하고 얻은 소름 끼치게 생긴 열쇠가 열쇠 구멍에 쉽게 미끄러져 들어가더니 사라지고, 입구가 완전히 열립니다. 가마솥 받침대 안에서는 정제되지 않은 끈적끈적한 고름 같은 액체가 뒤틀린 관 속을 고동치며 흐르고 있습니다.\n\n아래쪽에 병이 잘 들어맞는 작은 꼭지가 있어 서리바람 거점에 있는 대여&lt;class&gt; 맥도널에게 가져갈 견본을 뽑아 낼 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5220] = {title = "서리바람 야영지로의 귀환", objective = "서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 달슨의 눈물 혼합물을 가져가야 합니다.", description = "조심스럽게 병에 가마솥의 고름 같은 액체를 충분하다고 생각되는 양만큼 채웁니다.\n\n독극물을 손에 넣었으니 이제 서리바람 야영지에 있는 대여사제 맥도널에게 돌아가 임무를 완수해야 합니다.", progress = "각 가마솥에서는 여러 가지 다른 종류의 재료가 섞여 역병을 뿜어내는 고유의 독이 제조되는 것으로 알고 있습니다. 마찬가지로, 우리는 각 가마솥별로 고유한 반작용 물질을 개발해야 하는 것입니다. 당신이 달슨의 눈물에서 가져온 견본은 그 가마솥 특유의 필요한 재료를 알아내는 열쇠가 될 겁니다.", completion = "아, 연구에 쓸 만큼 많이 가져왔군요. 수고했습니다!\n\n이제 다음 단계는 우리가 해결하겠습니다. 이미 가마솥에 들어 있는 내용물과 섞이면 해당 내용물에 대한 반작용 물질로 변하게 될 재료의 목록을 만들어야 합니다.\n\n이 반작용 물질을 사용하려면 가마솥에 직접 해당 재료를 넣어야만 하는데, 그에 대해서는 연금술사 알빙턴이 더 잘 알고 있을 테니 가능한 빨리 꼭 그와 얘기해 보세요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신의 권능: 인내\n\n다음과 같은 것들을 받습니다:\n\n"},
[5221] = {title = "달슨의 눈물 가마솥", objective = "앞에는 스컬지의 역병 가마솥이 공기 중에 엄청난 양의 독을 뿜어대고 있습니다. 가마솥의 거대한 단 아랫부분에는 작고 특별할 것 없어 보이는 입구가 있습니다.\n\n이미 가마솥군주를 처치하고 그 열쇠를 얻었으니 역병에 대한 반작용 물질을 만들기 위해 적절한 재료를 마음대로 가마솥에 넣을 수 있습니다.", description = nil, progress = "앞에는 스컬지의 역병 가마솥이 공기 중에 엄청난 양의 독을 뿜어대고 있습니다. 가마솥의 거대한 단 아랫부분에는 작고 특별할 것 없어 보이는 입구가 있습니다.\n\n이미 가마솥군주를 처치하고 그 열쇠를 얻었으니 역병에 대한 반작용 물질을 만들기 위해 적절한 재료를 마음대로 가마솥에 넣을 수 있습니다.", completion = "가마솥의 혼합물에 재료를 넣자 공기 중에 뿜어져 나오는 내용물의 색과 결이 변합니다. 주변에 새로운 요소가 투입되자 멀리 떨어져서나마 가마솥 근처에 있던 스컬지들이 움찔하며 물러나는 듯합니다.", rewards = nil},
[5222] = {title = "목표: 고통의 흉가", objective = "서부 역병지대의 고통의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 고통의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", description = "가마솥 두 개를 성공적으로 열었으니 이 두 가마솥은 앞으로 제한 없이 접근할 수 있겠지만 아직 나머지 가마솥 두 개도 마저 열어야 합니다. 이렇게 하면 우리 모두에게 반작용 물질 투입에 있어서 더 다양한 선택 가능성이 생기게 되는 겁니다!\n\n이번 목표는 고통의 흉가의 가마솥입니다. 그 가마솥은 안돌할에서 거의 정동쪽 방향에 있는데, 폐허가 된 도시 성벽에서 비교적 가까운 곳에 있어요. 이번에도 역시 그곳에 있는 가마솥군주를 처치하고 열쇠를 손에 넣은 다음 이 병에 그 가마솥의 내용물을 담아 오세요.\n\n즐거운 사냥이 되시길!", progress = "가마솥으로 통하는 입구가 굳게 잠겨 있습니다. 입구를 열려면 열쇠를 찾아야 합니다.", completion = "가마솥군주 라자르취의 열쇠는 이전에 찾았던 다른 두 가마솥의 열쇠들과 마찬가지로 이 가마솥으로 통하는 입구를 열고는 사라집니다. 썩은 냄새가 나는 물질이 가마솥의 단 아래에서 세차게 움직이고 있습니다.\n\n아래쪽에 병이 잘 들어맞는 작은 꼭지가 있어 서리바람 거점에 있는 대여사제 맥도널에게 가져갈 견본을 뽑아 낼 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5223] = {title = "서리바람 야영지로의 귀환", objective = "서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 고통의 흉가 혼합물을 가져가야 합니다.", description = "빈 병을 세심하게 가득 채웁니다. 가마솥 단 아래에서 세차게 움직이는 고약한 물질의 견본이 이제 이 깨지기 쉬운 유리 용기 안에서 왔다갔다하고 있습니다.\n\n독극물을 손에 넣었으니 이제 서리바람 야영지에 있는 대여사제 맥도널에게 돌아가 임무를 완수해야 합니다.", progress = "고통의 흉가의 가마솥에서 가져온 견본을 성공적으로 분석하게 되면, 스컬지에게 아주 치명적인 반작용 물질을 만들어 낼 세 번째 길이 열리는 거예요!", completion = "또다시 빈틈없이 해냈군요! 이것으로 스컬지에게 역이용할 가마솥이 세 개가 되었어요. 이 땅에 퍼진 켈투자드의 강령술이 지금만큼 강하지만 않았어도 가마솥을 아예 영원히 사용하지 못하도록 없애버리라고 했을 겁니다!\n\n역병에 대한 반작용 물질을 만들어 내기 위해 이 가마솥뿐 아니라 다른 가마솥들에도 필요한 재료가 무엇인지에 대해 연금술사 알빙턴이 알려줄 겁니다. 자, 그럼 이제 서쪽에 있는 마지막 가마솥을 우리가 장악할 때가 됐군요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신의 권능: 인내\n\n다음과 같은 것들을 받습니다:\n\n"},
[5224] = {title = "고통의 흉가 가마솥", objective = "앞에는 스컬지의 역병 가마솥이 공기 중에 엄청난 양의 독을 뿜어대고 있습니다. 가마솥의 거대한 단 아랫부분에는 작고 특별할 것 없어 보이는 입구가 있습니다.\n\n이미 가마솥군주를 처치하고 그 열쇠를 얻었으니 역병에 대한 반작용 물질을 만들기 위해 적절한 재료를 마음대로 가마솥에 넣을 수 있습니다.", description = nil, progress = "앞에는 스컬지의 역병 가마솥이 공기 중에 엄청난 양의 독을 뿜어대고 있습니다. 가마솥의 거대한 단 아랫부분에는 작고 특별할 것 없어 보이는 입구가 있습니다.\n\n이미 가마솥군주를 처치하고 그 열쇠를 얻었으니 역병에 대한 반작용 물질을 만들기 위해 적절한 재료를 마음대로 가마솥에 넣을 수 있습니다.", completion = "가마솥의 혼합물에 재료를 넣자 공기 중에 뿜어져 나오는 내용물의 색과 결이 변합니다. 주변에 새로운 요소가 투입되자 멀리 떨어져서나마 가마솥 근처에 있던 스컬지들이 움찔하며 물러나는 듯합니다.", rewards = nil},
[5225] = {title = "목표: 가론의 흉가", objective = "서부 역병지대의 가론의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 가론의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", description = "마지막 가마솥은 지금은 가론의 흉가라고 불리는 농장에 있어요. 이 가마솥은 스컬지 졸개들 중에서도 좀 더 센 녀석들이 지키고 있는데, 망령과 유령이 특히 강하기 때문에 섣불리 상대해서는 안 될 녀석들입니다.\n\n가론의 흉가는 여기서 정북동쪽, 동부 역병지대가 시작되는 곳 가까이에 있어요. 이번에도 역시 그곳에 있는 가마솥군주를 처치하고 열쇠를 빼앗아서 가마솥에 접근하여 여기 이 빈 병을 가득 채워 오도록 하세요. 이 위험한 임무를 수행하는 데 성스러운 빛의 가호가 있기를...", progress = "가마솥으로 통하는 입구가 굳게 잠겨 있습니다. 입구를 열려면 열쇠를 찾아야 합니다.", completion = "가마솥군주 성난망령의 열쇠를 가마솥 단 아래 부분에 있는 입구의 자물쇠에 가져가자 없어져 버립니다. 안에서 철컥하는 소리가 나며 입구가 열리자 가마솥 안에는 더욱 끈적끈적한 독이 들어 있습니다.\n\n아래쪽에 병이 잘 들어맞는 작은 꼭지가 있어 서리바람 거점에 있는 대여&lt;class&gt; 맥도널에게 가져갈 견본을 뽑아 낼 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5226] = {title = "서리바람 야영지로의 귀환", objective = "서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 가론의 흉가 혼합물을 가져가야 합니다.", description = "가마솥의 썩은 내 나는 고름 같은 물질이 빈 병에 한 방울씩 떨어지는 것을 보며 조심스럽게 꼭지를 잠급니다.\n\n독극물을 손에 넣었으니 이제 서리바람 야영지에 있는 대여사제 맥도널에게 돌아가 임무를 완수해야 합니다.", progress = "우리가 접근해야 할 마지막 가마솥은 이곳에서 서쪽에 있는 가론의 흉가에 있어요. 그 가마솥에서 뿜어져 나오는 역병의 견본을 채취하면 네 개의 각각의 용기에 담긴 반작용 물질을 주변에 투입할 수 있게 됩니다! 스컬지가 켈투자드의 마력의 지원을 받는다 해도 네 개의 가마솥 모두에서 우리를 떼어놓기는 어려울 겁니다.", completion = "축하해요, &lt;name&gt;. 마지막 가마솥으로 통하는 입구를 열었군요! 이 가마솥의 혼합물에 필요한 재료가 무엇인지 연금술사 알빙턴이 곧 알아 낼 겁니다.\n\n지금까지 도와 준 데 대해 발러피스트 사령관님께서 당신에게 직접 감사의 표시를 하고 싶어하실 겁니다. 당신이 없었다면 스컬지와의 투쟁에서 이겨 낼 수 없었을 거예요. 감사합니다, 영웅이여!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신의 권능: 인내\n\n다음과 같은 것들을 받습니다:\n\n"},
[5227] = {title = "가론의 흉가 가마솥", objective = "앞에는 스컬지의 역병 가마솥이 공기 중에 엄청난 양의 독을 뿜어대고 있습니다. 가마솥의 거대한 단 아랫부분에는 작고 특별할 것 없어 보이는 입구가 있습니다.\n\n이미 가마솥군주를 처치하고 그 열쇠를 얻었으니 역병에 대한 반작용 물질을 만들기 위해 적절한 재료를 마음대로 가마솥에 넣을 수 있습니다.", description = nil, progress = "앞에는 스컬지의 역병 가마솥이 공기 중에 엄청난 양의 독을 뿜어대고 있습니다. 가마솥의 거대한 단 아랫부분에는 작고 특별할 것 없어 보이는 입구가 있습니다.\n\n이미 가마솥군주를 처치하고 그 열쇠를 얻었으니 역병에 대한 반작용 물질을 만들기 위해 적절한 재료를 마음대로 가마솥에 넣을 수 있습니다.", completion = "가마솥의 혼합물에 재료를 넣자 공기 중에 뿜어져 나오는 내용물의 색과 결이 변합니다. 주변에 새로운 요소가 투입되자 멀리 떨어져서나마 가마솥 근처에 있던 스컬지들이 움찔하며 물러나는 듯합니다.", rewards = nil},
[5228] = {title = "스컬지 가마솥", objective = "서부 역병지대의 보루에 있는 어둠의여사제 반디스와 대화해야 합니다.", description = "옛 로데론 영토 내에는 8개의 가마솥이 있다네. 그 중 4개는 서부에, 그리고 다른 4개는 동부에 감춰져 있지. 이 가마솥들은 공기 중에 독을 뿜어 스컬지를 위해 이 땅 전체에 역병을 퍼뜨리고 있다네.\n\n켈투자드의 강령술 마력은 너무 강해서 이 가마솥들을 아예 폐쇄시켜 버릴 수는 없지만 우리에게 유리하도록 와해시킬 수는 있을 것 같네. 내 보좌관인 어둠의여사제 반디스가 이 임무를 관리할 텐데 나머지 상황 설명은 그녀에게서 듣도록 하게나.", progress = nil, completion = "&lt;race&gt; 형제여, 어둠의 가호를. 스컬지 가마솥 와해 계획을 위해 당신을 돕게 되어 기쁘군요.\n\n우리의 목표는 가마솥이 내뿜는 역병의 성분을 변경해 스컬지에게 유해한 영향을 미치는 것으로 바꾸는 것입니다. 역병의 성분을 변경하려면 이곳 서부 역병지대에 있는 4개의 가마솥 각각에 접근할 방법을 확보해야 합니다.\n\n이제 당신이 스컬지에 대한 공격을 이끌 때가 온 것입니다, 영웅이여.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5229] = {title = "목표: 펠스톤 농장", objective = "서부 역병지대의 펠스톤 농장으로 가서 그곳에 있는 가마솥군주를 찾아 물리치십시오. 가마솥군주가 가마솥으로 통하는 열쇠를 지니고 있을 수 있습니다. 반드시 빈 펠스톤 농장 병을 가지고 가서 가마솥 안에 있는 독의 견본을 확보해야 합니다.", description = "서부 역병지대에 있는 4개의 가마솥 중에서 펠스톤 농장에 있는 것이 접근하기 가장 쉬울 겁니다. 그곳에는 비교적 경험이 별로 없는 스컬지 부대가 배치되어 있지만 얕잡아봐서는 안 됩니다.\n\n여기서 정동쪽, 안돌할의 북서쪽에 있는 펠스톤 농장으로 가서 그곳에 있는 가마솥군주와 맞서 싸우세요. 가마솥군주는 가마솥으로 통하는 열쇠를 지니고 있습니다. 그 열쇠로 입구를 열고 들어가 이 병으로 가마솥 안에 든 독의 견본을 구해 오세요. 반작용 물질 개발을 위한 연구에 필요합니다.", progress = "가마솥으로 통하는 입구가 굳게 잠겨 있습니다. 입구를 열려면 열쇠를 찾아야 합니다.", completion = "가마솥군주 창자아귀로부터 얻은 열쇠가 입구 자물쇠에 꼭 들어맞습니다. 열쇠는 사용하자마자 사라져 버렸지만 이제는 열쇠 없이도 입구를 열 수 있을 것 같습니다. 입구를 열자 가마솥 안에 소용돌이치고 있는 알 수 없는, 농축된 물질들의 혼합물에서 지독한 악취가 뿜어져 나옵니다.\n\n아래쪽에 병이 잘 들어맞는 작은 꼭지가 있어 보루에 있는 어둠의여사제 반디스에게 가져갈 견본을 뽑아 낼 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5230] = {title = "보루로의 귀환", objective = "서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 펠스톤 농장 병을 가져가야 합니다.", description = "연구를 위한 적절한 견본으로 가마솥의 독성 있는 혼합물을 병에 채웁니다.\n\n독을 손에 넣었으니 이제 보루에 있는 어둠의여사제 반디스에게 돌아가 임무를 완료할 때입니다.", progress = "비교적 안전한 보루로 돌아오신 걸 환영합니다. 가마솥 임무는 어떻게 진행이 되고 있나요?", completion = "수고하셨습니다. 연금술사 디더스가 이것을 분석하고 가마솥에 넣을 반작용 물질을 고안해 내는 데는 그리 오래 걸리지 않을 겁니다. 그 반작용 물질을 공기 중에 충분히 퍼뜨릴 수 있다면 이곳에 있는 모든 스컬지를 약화시킬 수 있을지도 모릅니다.\n\n분명 이 임무는 계속해서 험난한 것이 될 겁니다. 우린 계속해서 이 가마솥들을 공격해 우리의 반작용 물질을 그 안에 섞어야 해요. 하지만 우리가 성공한다면 스컬지와 전투를 벌일 때 우리가 훨씬 유리해질 겁니다!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신의 권능: 인내\n\n다음과 같은 것들을 받습니다:\n\n"},
[5231] = {title = "목표: 달슨의 눈물", objective = "서부 역병지대의 달슨의 눈물로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 달슨의 눈물 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", description = "지금은 달슨의 눈물이라고 불리는, 한때는 농장이었던 곳의 들판에 역병 가마솥 중 하나가 있습니다. 이제 우리는 눈물을 흘리지 않을 겁니다. 반드시 이 가마솥을 공격해 접근할 방법을 찾아야 해요! \n\n안돌할에서 거의 정북쪽에 있는 달슨의 눈물로 가서 그곳에 있는 가마솥군주를 제거하세요. 지난 번에 제거했던 녀석과 마찬가지로 열쇠를 지니고 있을 것이고, 그 열쇠로 가마솥 내부에 접근할 수 있을 겁니다. 이 병에 가마솥 내용물의 견본을 담아 오도록 하세요. 각 가마솥에는 고유하게 조제된 독이 있습니다.", progress = "가마솥으로 통하는 입구가 굳게 잠겨 있습니다. 입구를 열려면 열쇠를 찾아야 합니다.", completion = "가마솥군주 말비니어스를 처치하고 얻은 해골 열쇠가 열쇠 구멍에 쉽게 미끄러져 들어가더니 사라지고, 입구가 완전히 열립니다. 가마솥 받침대 안에서는 정제되지 않은 끈적끈적한 고름 같은 액체가 뒤틀린 관 속을 고동치며 흐르고 있습니다.\n\n아래쪽에 병이 잘 들어맞는 작은 꼭지가 있어 보루에 있는 어둠의여사제 반디스에게 가져갈 견본을 뽑아 낼 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5232] = {title = "보루로의 귀환", objective = "서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 달슨의 눈물 혼합물을 가져가야 합니다.", description = "조심스럽게 병에 가마솥의 고름 같은 액체를 적절한 견본의 양이라고 생각될 만큼 충분히 채웁니다.\n\n독극물을 손에 넣었으니 이제 보루에 있는 어둠의여사제 반디스에게 돌아가 임무를 완료할 때입니다.", progress = "각 가마솥에서는 여러 가지 다른 종류의 재료가 섞여 역병을 뿜어내는 고유의 독이 만들어진다고 알고 있습니다. 마찬가지로, 우리는 각 가마솥별로 고유한 반작용 물질을 개발해야 하는 것입니다. 당신이 달슨의 눈물에서 가져온 견본은 그 가마솥 특유의 필요한 재료를 알아 내는 열쇠가 될 겁니다.", completion = "오, 연구에 쓸 만큼 많이 가져왔군요. 잘했습니다!\n\n이제 다음 단계는 우리가 해결하도록 하죠. 이미 가마솥에 들어 있는 내용물과 섞이면 해당 내용물에 대한 반작용 물질로 변하게 될 재료의 목록을 만들어야 합니다.\n\n이 반작용 물질을 사용하려면 가마솥에 직접 해당 재료를 넣어야만 하는데, 그에 대해서는 연금술사 디더스가 더 잘 알고 있을 테니 가능한 빨리 그와 얘기해 보도록 하세요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신의 권능: 인내\n\n다음과 같은 것들을 받습니다:\n\n"},
[5233] = {title = "목표: 고통의 흉가", objective = "서부 역병지대의 고통의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 고통의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", description = "가마솥 두 개는 성공적으로 열었어요. 이 두 가마솥은 앞으로 제한 없이 접근할 수 있겠지만 아직 나머지 가마솥 두 개도 마저 열어야 합니다. 이렇게 하면 우리 모두에게 반작용 물질 사용에 있어서 더 다양한 선택 가능성을 가지게 되는 것이죠!\n\n이번 목표는 고통의 흉가의 가마솥입니다. 그 가마솥은 안돌할에서 거의 정동쪽 방향에 있는데, 폐허가 된 도시 성벽에서 비교적 가까운 곳에 있어요. 이번에도 역시 그곳에 있는 가마솥군주를 처치하고 열쇠를 손에 넣은 다음 이 병에 그 가마솥의 내용물을 담아 오도록 하세요.\n\n즐거운 사냥이 되시길!", progress = "가마솥으로 통하는 입구가 굳게 잠겨 있습니다. 입구를 열려면 열쇠를 찾아야 합니다.", completion = "가마솥군주 라자르취의 열쇠는 이전에 찾았던 다른 가마솥의 열쇠들과 마찬가지로 이 가마솥으로 통하는 입구를 열고는 사라집니다. 썩은 냄새가 나는 물질이 가마솥의 단 아래에서 세차게 움직이고 있습니다.\n\n아래쪽에 병이 잘 들어맞는 작은 꼭지가 있어 보루에 있는 어둠의여사제 반디스에게 가져갈 견본을 뽑아 낼 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5234] = {title = "보루로의 귀환", objective = "서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 고통의 흉가 혼합물을 가져가야 합니다.", description = "빈 병을 세심하게 가득 채웁니다. 가마솥 단 아래에서 세차게 움직이는 고약한 물질의 견본이 이제 이 깨지기 쉬운 유리 용기 안에서 왔다갔다하고 있습니다.\n\n독극물을 손에 넣었으니 이제 보루에 있는 어둠의여사제 반디스에게 돌아가 임무를 완료할 때입니다.", progress = "고통의 흉가의 가마솥에서 가져온 견본의 분석을 성공적으로 끝내면 스컬지에게 아주 치명적인 반작용 물질을 만들어 낼 세 번째 길이 열리는 겁니다!", completion = "또다시 빈틈 없이 해 내셨군요! 이것으로 스컬지에게 역이용할 가마솥이 세 개가 되었습니다. 이 땅에 퍼진 켈투자드의 강령술이 지금만큼 강하지만 않았어도 가마솥을 아예 영원히 사용하지 못하도록 폐쇄해 버리라고 했을 거예요!\n\n역병에 대한 반작용 물질을 만들어 내기 위해 이 가마솥뿐 아니라 다른 가마솥들에도 필요한 재료가 무엇인지에 대해 연금술사 디더스가 보고를 할 겁니다. 자, 그럼 이제 서쪽에 있는 마지막 가마솥을 우리가 장악할 때가 됐군요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신의 권능: 인내\n\n다음과 같은 것들을 받습니다:\n\n"},
[5235] = {title = "목표: 가론의 흉가", objective = "서부 역병지대의 가론의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 가론의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", description = "마지막 가마솥은 지금은 가론의 흉가라고 불리는 농장에 있습니다. 이 가마솥은 스컬지 졸개들 중에서도 좀 더 센 녀석들이 지키고 있습니다. 그 중에서도 망령과 유령이 특히 강하니 섣불리 상대해서는 안 될 겁니다.\n\n가론의 흉가는 보루에서 동쪽으로 멀리, 동부 역병지대가 시작되는 곳 가까이에 있습니다. 이번에도 역시 그곳에 있는 가마솥군주를 제거하고 열쇠를 빼앗아야 합니다. 여기 이 빈 병을 가득 채워 오도록 하세요. 이 위험한 임무를 수행하는 데 어둠의 보호가 함께하시길.", progress = "가마솥으로 통하는 입구가 굳게 잠겨 있습니다. 입구를 열려면 열쇠를 찾아야 합니다.", completion = "가마솥군주 성난망령의 열쇠를 가마솥 단 아래쪽에 있는 입구의 자물쇠에 가져다 대자 분해되어 버립니다. 안에서 약하게 철컥하는 소리가 나며 입구가 열리고 가마솥 안에는 더욱 끈적끈적한 독이 들어 있습니다.\n\n아래쪽에 병이 잘 들어맞는 작은 꼭지가 있어 보루에 있는 어둠의여사제 반디스에게 가져갈 견본을 뽑아 낼 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5236] = {title = "보루로의 귀환", objective = "서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 가론의 흉가 혼합물을 가져가야 합니다.", description = "가마솥의 썩은 내 나는 고름 같은 물질이 빈 병에 한 방울씩 떨어지는 것을 보며 조심스럽게 제어판의 꼭지를 잠급니다.\n\n독극물을 손에 넣었으니 이제 보루에 있는 어둠의여사제 반디스에게 돌아가 임무를 완료할 때입니다.", progress = "우리가 이곳 서쪽에서 접근해야 할 마지막 가마솥은 가론의 흉가에 있습니다. 그 가마솥에서 뿜어져 나오는 역병의 견본을 채취하면 네 가지 각각의 용기를 통해 주변에 반작용 물질을 투입할 수 있게 되는 겁니다! 스컬지는 켈투자드의 마력의 지원을 받는다 해도 네 개의 가마솥 모두에서 우리를 떼어놓기는 어려울 거예요.", completion = "축하합니다. 마지막 가마솥으로 통하는 입구를 열었군요! 이 가마솥의 혼합물에 필요한 재료가 무엇인지 연금술사 디더스가 곧 알아 낼 겁니다.\n\n지금까지 도와 준 데 대해 고위집행관 델링턴님께서 당신에게 직접 감사의 표시를 하고 싶어하실 겁니다. 당신이 없었다면 스컬지와의 투쟁에서 이겨 낼 수 없었을 겁니다. 감사합니다, 강한 &lt;class&gt;|1이여;여;!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n신의 권능: 인내\n\n다음과 같은 것들을 받습니다:\n\n"},
[5237] = {title = "임무 완료!", objective = "자네가 가마솥 임무를 성공적으로 수행한 것은 우리에게 큰 수확이다!\n\n<목을 가다듬고는 큰 소리로 말하기 시작하는 사령관>\n\n이곳에 있는 모든 이들에게 고하노니, 압도적인 열세와 극한 위험 속에서도 단순한 의무감을 넘어 마음에서 우러나는 충심으로 스톰윈드 왕국과 얼라이언스에 봉사한 <name>에게 이 상을 수여하고, 이 얼라이언스의 진정한 영웅에게 우리의 영원한 감사의 뜻을 표하노라. 모두 만세!", description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n용기의 쇼트소드용맹의 쇼트소드\n\n다음과 같은 것들 또한 받습니다:\n\n영웅의 훈장"},
[5238] = {title = "임무 완료!", objective = "자네가 가마솥 임무를 성공적으로 수행한 것은 우리에게 큰 수확이다.\n\n<목을 가다듬고는 큰 소리로 말하기 시작하는 고위집행관>\n\n이곳에 있는 모든 이들에게 고하노니, 압도적인 열세와 극한 위험 속에서도 기대했던 것 이상으로 포세이큰과 호드 모두에 충심으로 봉사한 라솔<class>에게 이 상을 수여하고, 이 호드의 진정한 이 영웅에게 우리의 영원한 감사의 뜻을 표하노라. 만세!", description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n용기의 쇼트소드용맹의 쇼트소드\n\n다음과 같은 것들 또한 받습니다:\n\n영웅의 훈장"},
[5241] = {title = "카를린 삼촌", objective = "카를린 레드패스를 찾아야 합니다.", description = "가끔, 밤이 되면 우리 카를린 삼촌이 울고 있는 소리가 들려요. 멀리 동쪽에 있는 것 같아요.\n\n나 때문에 우는게 아니었으면 좋겠어요. 우리 삼촌을 찾아가서 전 괜찮다고 좀 얘기해 주실래요?\n\n삼촌을 찾으면 파멜라가 기다리고 있다고 전해 주세요. 삼촌이 얘기해 주던 재미있는 얘기를 듣고 싶다는 것도요... 토끼와 딸기잼 얘기 말이에요! 그 이야기는 정말 재미있어요!", progress = nil, completion = "파멜라를 봤단 말이오? 그 아이는 살아있소?\n\n죽었다고? 안 돼! 오, 파멜라! 왜 네 영혼이 이 세계에서 계속 괴로워해야 하는 거냐. 이 삼촌은 운 좋게 살아남았는데, 네가 먼저 가버리다니! 할 수만 있다면 차라리 내가 널 대신해서 폐허가 된 다로우샤이어를 배회하는 원혼이 되었다면 좋으련만!\n\n아, 그래도 이제는 달리 어쩔 수 없군... 고맙소. 이제 나의 사명인 복수를 향한 열망은 그 어느 때보다도 뜨겁게 타오르고 있소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5242] = {title = "마지막 일격", objective = "무라와 살리라, 그리고 어둠의 군주 펠단을 처치하십시오. 그리고 그 증거로 펠단의 머리카락을 악령의 숲에 있는 그레타 모스후프에게 가져가야 합니다.", description = "안타깝게도, 악령의 숲에 대한 위협을 저지하는 유일한 길은 전면 공격뿐인 듯하군요. 제가 어둠의 요새 안으로 순간이동을 시켜 드릴 수도 없고... 밑으로 뻗어내린 길이 유일한 통로랍니다. 당신이 누구를 찾아야 하는지 알고 있습니다. 펠단... 어둠의 군주라고 하는 작자가 모든 권력을 쥐고 있는 녀석입니다. 독사들의 우두머리죠. 펠단과 서큐버스 부하 둘을 해치우고 돌아오세요. 불타는 군단과 조약을 맺고 있는 펠단을 반드시 막아야 합니다.", progress = "펠단이 없어졌으니 이제 어둠의 의회는 방향을 잃고 내분이 일어나기 시작할 거예요. 바로 우리가 바라던 바죠. 빈 왕좌를 놓고 서로 아귀다툼을 벌이게 겁니다. 바로 그때가 어둠의 의회와 그 악마 노예를 해치울 좋은 기회입니다.", completion = "대지모신에게 찬미를! 감사합니다! 오늘은 참으로 위대한 날이로군요!\n\n어둠의 의회는 이번 타격으로 예전 같은 힘을 발휘하기는 어려울 거예요. 당신은 오늘 위대한 일을 하신 겁니다!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n옹이나무 장식띠황폐의 가죽 장갑강철톱니 벨트\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5243] = {title = "성스러운 집", objective = "북쪽에 있는 스트라솔름으로 가서 도시 어딘가에 흩어진 보급품 상자를 찾아 스트라솔름 성수 5병을 가져와야 합니다. 성수를 충분히 모으고 나면 존경받는 리어니드 바돌로매에게 돌아가야 합니다.", description = "난 내가 언데드로 살아난 걸 단지 질병으로 생각한다네. 치료하면 낫는 질병같은 것으로 생각하지만 이것은 은빛 여명회에 있어서도 커다란 축복이라고 할 수 있네. 스컬지의 이방인들을 처단할 수 있는 더 나은 수단이 있을 거라 생각하나?\n\n동지들은 내 희생을 보고 나를 경외하고 있지만, 내게 영예 따윈 아무 의미가 없네.\n\n은빛 여명회를 돕고 싶다면 내 일거리를 주도록 하지. 스트라솔름으로 가서 보급품 상자를 찾아 남은 성수를 가져다 주게나.", progress = "도시가 파괴되어 남아 있는 보급품들이 그다지 많지 않을 테니까 조심하게! 스컬지는 성수에 손 댈 수 없지만, 성수도 독으로부터 자네를 지킬 수는 없을 것일세.", completion = "수고했네, &lt;race&gt;|1이여;여;. 자네는 켈투자드의 졸개들을 모조리 처리하기 전까지는 쉬지 않겠다는 확고한 의지를 보여주었네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n참회의 관참회의 띠\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n최상급 치유 물약상급 마나 물약"},
[5244] = {title = "켈테릴의 폐허", objective = "별똥별 마을에 있는 야론 스톤셰이퍼와 대화하십시오.", description = "한 때 켈테릴에서는 저주의 의식이 행해졌소. 그 의식을 주도한 종족들이 오히려 저주를 받아 그곳에 속박되었소이다.\n\n그 엘프 귀족들은 성스러운 유물 하나를 훔쳤소. 강력한 유물의 힘을 흡수하려던 도중 큰 폭발이 일어났고 유물은 산산이 부서져서 얼어붙은 호수 밑으로 가라앉아 버렸소...\n\n더 자세히 알고 싶거든 야론 스톤셰이퍼와 대화하시오. 근래 그곳을 다녀왔으니 많은 얘기를 해줄 거요.", progress = nil, completion = "켈테릴에 대한 얘기야 물론 더 해줄 수 있지. 역사에 대해서는 잘 모르지만 최소한 내가 본 것에 대해서는 말해줄 수 있소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5245] = {title = "켈테릴의 고통받는 영혼", objective = "야론의 곡괭이를 사용해 귀족 유물 조각 4개를 찾아 동부 역병지대에 있는 아우로라 스카이콜러에 갖다주어야 합니다.", description = "명가의 원혼의 운명은 정말 비참하지. 아직 자신들을 켈테릴에 영원히 구속한 물건을 찾고 있소. 바로 훔친 그 유물 말이오.\n\n관심이 있거든 내 곡괭이를 들고 남쪽의 호수로 가보시오. 가서 얼음을 깨고 유물 조각을 모으시오.\n\n그 유물이 어떤 것인지는 난 모르겠소. 하지만, 잘 알 만한 이는 한 명 알지. 아우로라 스카이콜러라는 여자인데, 동부 역병지대 북쪽에 있는 북부관문 경비탑 근처에 살고 있소.", progress = "무슨 일로 오신 거죠?", completion = "하이 엘프들의 과거 얘기는 하고 싶지 않군요, &lt;name&gt;. 무슨 일이 일어났는지 생각하면 너무 가슴이 아파서... 그리고 이제 사태를 수습할 방법이 없다는 사실도 몹시 슬퍼요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5246] = {title = "과거의 조각들", objective = "아즈샤라에 있는 진말로의 신전에서 귀족의 성서를 찾아야 합니다. 동부 역병지대의 북부관문 경비탑 근처에 있는 아우로라 스카이콜러에게 가져가십시오.", description = "선조를 돕기 위해 오신 분인 줄 몰랐습니다. 제가 말이 지나쳤군요.\n\n선조의 잘못에 엮이고 싶지는 않지만 그대의 요청에 진정 거짓이 없다면 도와드리겠습니다.\n\n<유물 조각을 조사해보는 아우로라>\n\n이건 진말로의 수정인 것 같군요. 여기에 강력한 신비의 힘을 담아서 쓸 수 있어요. 선한 일에 사용하면 괜찮지만 이걸 훔친 자들은 사악한 의도로 쓰려고 했기 때문에 깨져버린 거예요.\n\n아즈샤라에 있는 진말로의 신전으로 가보세요. 그 책이 아직 그곳에 있었으면 좋겠군요.", progress = "귀족의 성서가 있어야 그대를 도와드릴지 알려드릴 수 있습니다.", completion = "아주 오랜 세월 어느 누구도 이 책에 손을 대지 않았군요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5247] = {title = "과거의 조각", objective = "마력 깃든 토륨 주괴 1개와 회복의 수정 5개, 그리고 혈투의 웅덩이 물병을 동부 역병지대의 북부관문 경비탑 근처에 있는 아우로라 스카이콜러에게 가져가야 합니다.", description = "그대가 진정 유물을 복구하고 싶다면 제가 돕겠습니다.\n\n깨진 유물 조각을 다시 합치려면 마력이 강한 재료가 필요합니다. 마력 깃든 토륨 주괴 1개와 회복의 수정 5개가 필요하지요. 그리고 물이 없을 것 같은 장소에 가서 물을 가져와야 합니다. 페랄라스 혈투의 전장의 엘드레스 관문을 따라 있는 혈투의 웅덩이를 찾아서 이 물병을 채우십시오.\n\n그대가 재료를 모으는 동안 저는 유물을 복구하는 데 필요한 정보를 조사하고 있겠습니다.", progress = "유물은 가장 신뢰할 만한 이의 손에 맡겨야 합니다. 또다시 도둑맞아서는 안 되니까요.", completion = "이 재료들을 사용해서 조각을 합칠 수 있습니다. 잘만 하면 원상태로 복구할 수 있습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5248] = {title = "인과응보", objective = "진말로의 수정을 여명의 설원에 있는 켈테릴 호수로 갖고 가서 당신과 대화를 하고자 하는 명가의 영혼을 찾아야 합니다.", description = "<name>, 과거에 일어난 일을 생각하면 아주 슬퍼집니다. 이 수정처럼 엘프라는 종족도 산산조각이 나버린 거죠. 언젠가 그 조각들이 다시 모여 하나를 이루게 될지는 모르겠지만, 그대가 이 작은 일이라도 도울 수 있다니 제 슬픔이 그나마 덜합니다.\n\n절대로 과거를 잊어서는 안 돼요...\n\n진말로의 수정을 다시 켈테릴 호수로 갖고 가십시오. 거기서 어느 엘프 귀족의 영혼을 찾아야 합니다. 그 영혼은 오래전에 저지른 짓이 그릇된 행위였다는 걸 깨달았지요. 그 영혼에게 우리가 다시 일을 바로 잡았다는 것을 보여주십시오.", progress = "여어엉원의... 저어주우우를 받았어...", completion = "나아아아아아를 내에에에 버어어어려 두우우우우시이이이이오오오오....", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5249] = {title = "여명의 설원으로!", objective = "여명의 설원에 있는 별똥별 마을에서 윈드 나이트체이서와 대화하십시오.", description = "여기서 북쪽으로 여명의 설원에 가면 고대 엘프 유적지가 여러 군데 있어요. 혹독한 땅이지만 여러 가지 비밀을 캐내기 위해 탐험을 해볼만한 곳이죠.\n\n저는 악령의 숲에서 할 일이 너무 많아 여명의 설원에 갈 기회가 없었지만... 그대가 가보는 건 어떨까요?\n\n그곳에 가면 윈드 나이트체이서를 찾으세요. 별똥별 마을에서 주로 시간을 보내는데, 그 지역에 대해서 아주 훤히 꿰고 있죠.", progress = nil, completion = "아이비 리프러너의 친구분이오? 만나서 반갑소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5250] = {title = "별똥별 마을", objective = "여명의 설원에서 별똥별 마을을 찾아 윈드 나이트체이서와 대화하십시오.", description = "여기서 북쪽으로 여명의 설원에 가면 고대 엘프 유적지가 여러 군데 있어요. 혹독한 땅이지만 여러 가지 비밀을 캐내기 위해 탐험을 해볼만한 곳이랍니다.\n\n저는 연구가 너무 바빠서 여명의 설원에 갈 기회가 없었지만... 그대가 가보는 건 어떨까요?\n\n그곳에 가면 윈드 나이트체이서를 찾으세요. 별똥별 마을에서 주로 시간을 보내는데, 그 지역에 대해서 아주 훤히 꿰고 있으니까요.\n\n가서 그대가 저의 제자라고 말하세요...", progress = nil, completion = "다린 라이트윈드의 제자라고 했소? 만나서 반갑소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5251] = {title = "기록관", objective = "스트라솔름으로 가서 붉은십자군의 기록관, 갈포드를 찾아서 그를 처치하고 붉은십자군 기록을 불태워 버려야 합니다.", description = "뭐든지 도를 넘은 것은 해로운 법이지. 붉은십자군 녀석들을 보게! 그들의 눈 먼 광신적인 행동들이 정의라고 생각하나? 그들이 말하는 정의의 이름으로 얼마나 많은 생명들이 스러져 갔던가? 그건 정의에 대한 모독이야!\n\n그렇지만 한 가지 신경쓰이는 게 있네. 스트라솔름의 기록관인 갈포드 말이야. 그는 십자군의 중요한 문서들을 관리하고 있다네. 그를 처치하고 그의 문서들을 모두 불태워버리게! 일을 성사시키고 내게 돌아오면 사례를 하도록 하지.", progress = nil, completion = "대단하군! 몇 년 동안 수집한 정보가 사라진 건 붉은십자군에게는 한 동안 뼈 아픈 타격일 걸세!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5252] = {title = "한 맺힌 명가의 원혼", objective = "별똥별 마을에 있는 윈드 나이트체이서와 대화해 진말로의 수정을 어디에 두어야 하는지 물어보십시오.", description = "그... 수정...\n\n이곳 엘프 귀족들은 비극에 휩싸여 살고 있소...\n\n나도 아주 슬프지만 과거에 저지른 일이 그릇된 행위였다는 것을 깨달았소. 과거를 바꿀 수 있는 방법은 없지만 그대가 진말로의 수정을 회수했다는 사실에 안심이 되오...\n\n되돌려주시오...\n\n되돌려주어야 하오...", progress = "오랜만에 다시 만나게 되는구려, <name>. 그동안 무사하셨소?", completion = "그건... 혹시?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5253] = {title = "진말로의 수정", objective = "다르나서스에 있는 대드루이드 판드랄 스테그헬름에게 진말로의 수정을 갖다주어야 합니다.", description = "아주 놀랍소, <name>.\n\n알다시피 진말로의 신전은 폐허가 되어버렸기 때문에 수정을 보관할 수 없소. 과거의 악행이 불러온 결과를 바로 잡으려는 당신의 노력은 반드시 그 결실을 보아야 한다고 생각하오.\n\n그리고 수정은 그 마력을 남용하지 않을 자에게 넘겨야 하오. 그렇게 강력한 마력을 조종할 수 있는 사람은 몇 안 되지... 다르나서스에 있는 대드루이드 판드랄 스테그헬름에게 이 수정을 갖다주시오.", progress = "어쩐 일인가, <race>?", completion = "진말로의 수정에 대해서 들어 본 적은 있네. 이 수정을 지니면 엄청난 마력을 갖게 되지만... 진정한 주인이 될 자의 손에서만 빛을 발한다지. 자네가 수정을 회수한 것도 놀랍지만, 자신의 한계를 깨닫고 수정에 욕심을 내지 않았다는 게 정말 놀랍고도 흐뭇하네.\n\n와줘서 고맙네, &lt;name&gt;! 우리가 안전한 곳에 보관하도록 하지. 산산조각난 이 수정을 지키던 저주받은 명가의 영혼들이 마침내 안식을 찾을 수 있기를...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n터키옥 장식띠큰곰나무 어깨갑옷에메랄드안개 건틀릿\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5261] = {title = "이건 펠트스키너", objective = "이건 펠트스키너와 얘기해야 합니다.", description = "이건 펠트스키너가 늑대를 사냥해 줄 사람을 찾고 있습니다. 최근에 노스샤이어 계곡에 늑대가 많이 출몰하고 있어서 우리도 골칫거리였는데 여간 반가운 소식이 아닙니다.\n\n생각이 있다면 이건을 만나 보시기 바랍니다. 아마 수도원 왼편 어딘가에 있을 겁니다.", progress = nil, completion = "그렇습니다. 늑대를 처치해 줄 사람을 찾고 있습니다. 한 번 해 보시겠습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5262] = {title = "밝혀지는 진실", objective = "동부 역병지대에 있는 공작 니콜라스 즈바른호프에게 발나자르의 혼을 가져가야 합니다.", description = "먼지가 내려앉은 방 안에서 골똘히 생각하고 있습니다. 방금 일어난 일들을 다시 떠올려 봐도 사태의 심각성을 파악하기 어렵습니다.\n\n붉은십자군의 십자군사령관이 악마? 그것도 평범한 악마가 아니라 언더시티의 대군주 바리마트라스의 형제?\n\n공포의 군주의 혼을 조심스럽게 갈무리합니다. 증거가 없이는 지금 일어난 일에 대해서 아무도 믿지 못할 겁니다.\n\n즉시 니콜라스 즈바른호프 공작에게 알려야 합니다!", progress = "자네 갖고 있는 게 뭔가?", completion = "붉은십자군에게 무슨 일이 있었던 거지? 이 악마의 지배를 받았다는 게 가능하단 말인가? 더 큰 악의 졸개로 살고 있었단 말인가?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5263] = {title = "뛰어난 존재", objective = "스트라솔름으로 가서 남작 리븐데어를 처치하고 그의 혼을 공작 니콜라스 즈바른호프에게 가져가야 합니다.", description = "자네는 파괴적인 성향을 보이면서도 명령을 충실히 수행하는군. 그 두 가지가 공존하는 사람은 많지 않은데 말이야. 자네야말로 신성한 정의의 사자가 될 수 있을 거라는 생각이 드네.\n\n<손뼉을 치는 즈바른호프 공작>\n\n켈투자드의 졸개가 스트라솔름을 지배하고 있네. 나의 용사여, 자네의 그 강인한 힘을 보여주게. 리븐데어 남작을 처치하고 그의 혼을 갈무리해 오게나.", progress = "리븐데어 남작은 자네가 여태껏 살아오면서 본 사람들보다도 더 많은 사람들을 죽였다네.", completion = "용사에게 작위를 내려본 것도 몇 년만인지 모르겠군. 자네는 맥스웰 경을 몇 년 만에 처음으로 알현하는 친구일세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5264] = {title = "맥스웰 티로서스 경", objective = "교회 안에 있는 맥스웰 티로서스 경과 대화해야 합니다.", description = "나는 지금 자네에게 크나큰 영광을 돌리려고 하네.\n\n맥스웰 경께서는 은빛 여명회를 위해 행한 자네의 공로를 치하하고 상을 내리고 싶어하시네!\n\n자네는 몇 년 만에 처음으로 맥스웰 경께서 알현을 허락한 외부인이야.", progress = nil, completion = "자네는 출중한 능력의 용사일세. 자네의 헌신적인 활약은 보상을 받아야 마땅해.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5265] = {title = "여명회의 궤", objective = "여명회의 궤를 열고 보상을 받아야 합니다.", description = "몇 년간 여명회의 궤는 잠겨 있었네. 오늘 이전에는 안으로 들어와서 은빛 여명회의 손에서 무엇이라도 가져올 수 있는 자가 아무도 없었다는 말일세.\n\n이제 여명회의 궤는 자네의 손길로만 열릴 것일세.", progress = nil, completion = "우와...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n은빛의 복수자은빛의 수호자은빛의 십자군\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5281] = {title = "잠 못드는 영혼", objective = "스트라솔름 주변에서 목격된다고 알려진 에간을 찾아야 합니다.", description = "스트라솔름이 점령당했을 당시에 많은 사람들이 비참하게 죽어갔습니다. 스컬지가 되느니 차라리 죽는 것이 낫다고 불타는 도시의 화염에 투신하는 자들이 부지기수였지요.\n\n그들은 지금 영혼이 되어 스트라솔름의 거리를 배회하고 있습니다. 우리가 그들을 도와줘야만 합니다\n\n내 친구 중에 에간이라고 영혼이나 원혼들을 위해 기적적인 일을 하고 있는 자가 있습니다. 그를 찾으시기 바랍니다. 그는 동부 역병지대의 스트라솔름 근처에서 수련하고 있습니다.", progress = nil, completion = "드디어 알렌이 당신 같은 용감한 사람을 찾아낸 것 같군요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5282] = {title = "잠 못드는 영혼", objective = "스트라솔름 시민의 영혼과 원혼들에게 에간의 제령포를 사용해야 합니다. 원혼들이 그들을 가두고 있던 감옥에서 풀려나면 다시 총을 사용하여 그들에게 자유를 선사하십시오!\n\n15명의 잠 못드는 영혼을 자유롭게 하고 에간에게 돌아가야 합니다.", description = "나는 살아 숨 쉬고자 하는 의지와 힘을 스컬지에 대한 끓어 오르는 증오에서 얻고 있습니다. 그렇다고는 해도 난 광신도는 아닙니다. 붉은십자군 같은 놈들은 죄 없는 언데드들의 딱한 사정을 동정하기는커녕 무참히 쓸어버리는 데만 급급한 놈들입니다.\n\n하지만 저에게는 특별한 총이 있습니다. 이 총은 스트라솔름에 묶여 고통받는 영혼들을 자유롭게 해 주는 물건입니다.\n\n약탈당한 거리를 배회하는 원혼들에게 이 무기를 사용하여 그들의 영혼을 자유롭게 해주시기 바랍니다.", progress = nil, completion = "&lt;눈물을 훔치는 에간&gt;\n\n나의 어머니를 보셨습니까? 그분을 구해드린겁니까?\n\n당신은 친절하기 그지없는 분이십니다...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n희망의 유언"},
[5283] = {title = "방어구제작자의 길", objective = "방어구제작자가 되려면 화려한 미스릴 투구 4개, 화려한 미스릴 장화 2켤레, 화려한 미스릴 흉갑 1벌을 만들어 그룸누스에게 가져가야 합니다.", description = "현명한 결정이오.\n\n뭐, 이 일로 나와 이로누스 사이가 소원해지는 일은 없을 테니 걱정하지 마쇼. 장난감에 불과한 조잡한 무기나 만드는 사람에게 누가 진짜 훌륭한 장인인지를 꼭 가르쳐줄 필요는 없지 않겠소?\n\n전쟁의 승리는 훌륭한 방어를 통해 얻어지는 법이오. 후퇴해 도망갈 때 공격이 무슨 소용이 있겠소?\n\n자, 그러니까 일이나 열심히 합시다. 어쨌든 내게 당신의 재능만 좀 확인시켜 주시오. 그러면 내가 그 재능을 갈고 닦아서 훌륭한 방어구제작자로 탈바꿈시켜 드리리다. 화려한 미스릴 방어구 만드는 방법 정도는 알고 있겠지?", progress = "아, 대장간에서 그을린 이 영광의 흔적 좀 봐주시오. 이보다 더 뿌듯한 건 없지... 작업복의 이 기름때만 봐도 누가 더 훌륭한 장인인지 알 수 있을 거야.", completion = "&lt;name&gt;, 다시 되돌릴 수 없는 선택이오. 장난감이나 만들고 싶다면... 그러니까 무기를 제작하고 싶다면 지금이라도 늦지 않았으니까 얘기하시오.\n\n당신이라면 현명한 결정을 내릴 거라고 믿소이다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n전문 방어구제작\n\n다음과 같은 것들을 받습니다:\n\n"},
[5284] = {title = "무기제작자의 길", objective = "무기제작자가 되려면 달의 강철 브로드소드 4자루, 큰 철제 도끼 4자루, 견고한 미스릴 도끼 2자루, 검은 대형 철퇴 2자루를 만들어 이로누스에게 가져가야 합니다.", description = "무기제작자에게 물건을 사러 오는 이들 중에는 영웅이나 모험가가 많지. 일이 많아서 힘들 때도 있지만 먼지를 마시며 등골이 휘게 일하는 만큼 수입도 짭짤하다오.\n\n정말! 무기제작자들은 다 알부자들이라오.\n\n무기제작자가 되고 싶다면 쓸만한 재능이 있는지를 내게 증명해 보여야 하오. 아, 내 말은 장인이 될 수 있는 가능성과 소질을 증명해 보이란 말이지. 좋은 무기를 사려면 바로 그에게 가야 한다고 많은 이들이 인정할 만한 장인 말이오. 알아들었으면 어서 일이나 시작하시오.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n전문 무기제작\n\n다음과 같은 것들을 받습니다:\n\n"},
[5301] = {title = "방어구제작자의 길", objective = "방어구제작자가 되려면 화려한 미스릴 투구 4개, 화려한 미스릴 장화 2켤레, 화려한 미스릴 흉갑 1벌을 만들어 오코토스에게 가져가야 합니다.", description = "이만하면 됐군. 난 망치와 모루로 이런 작품을 만들어내지. <name>, 내가 만든 방어구를 걸친 호드 전사를 볼 때면 삶의 보람을 느끼곤 하네. 이건 마치 중독과도 같아.\n\n이런 보람은 내가 가르쳐 줄 수 있는 게 아니야. 난 그저 길을 안내할 뿐이고... 그 길을 직접 가는 건 자네의 몫이지. 평생 끊임없이 노력해야 한다는 점에서 볼 때 방어구제작자의 길은 긴 여행이라고 할 수 있다네.\n\n아제로스에서 손꼽히는 방어구제작자가 되고 싶으면 말만 하게. 내가 제대로 훈련시켜 주겠어. 하지만 그 전에 먼저 해야 할 일이 있지.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n전문 방어구제작\n\n다음과 같은 것들을 받습니다:\n\n"},
[5302] = {title = "무기제작자의 길", objective = "무기제작자가 되려면 달의 강철 브로드소드 4자루, 큰 철제 도끼 2자루, 견고한 미스릴 도끼 2자루, 검은 대형 철퇴 2자루를 만들어 보르고쉬에게 가져가야 합니다.", description = "언젠가 대족장님의 명예에 걸맞은 전설의 망치를 만들고 말 거야.\n\n이건 내 일생일대의 목표이자 꿈이라네, <name>. 자네도 훌륭한 무기제작자가 될 자질이 엿보이는데, 어떤가? 내가 그 자질을 키우도록 도와줄 수도 있어.\n\n간단한 시험만 거치면 돼. 자네 정도면 식은 죽 먹기일 거야.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n전문 무기제작\n\n다음과 같은 것들을 받습니다:\n\n"},
[5305] = {title = "진홍십자군 작업복", objective = "스트라솔름으로 가서 진홍십자군 대장장이를 처치하고 진홍십자군 대장장이의 작업복을 가지고 릴리스에게 돌아가야 합니다.", description = "붉은십자군 성채 안에는 대장기술 도면이 있어요. 진홍십자군 대장장이가 그 도면을 사수하는데, 그를 물리치고 그의 작업복을 가져오면 망치 만드는 법을 가르쳐 드리죠.\n\n하지만, 잘 알아 두세요. 한번 망치 제작의 길에 들어서면 검이나 도끼 제작과는 영영 이별이라는 사실을...다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n망치 제작의 대가\n\n다음과 같은 것들을 받습니다:\n\n도면: 마력 깃든 전투망치"},
[5306] = {title = "어둠사냥꾼의 뱀돌", objective = "검은바위 첨탑으로 가서 어둠사냥꾼 보쉬가진을 처치하고 보쉬가진의 뱀돌을 킬램에게 갖다주어야 합니다.", description = "아름다운 겉모습에 속아 넘어가지 마시오. 어둠사냥꾼 보쉬가진은 치명적이고 광기에 들린 존재요.\n\n<킬램이 자신의 얼굴에 난 흉터를 가리킵니다.>\n\n그렇소. 바로 그녀에게서 얻은 흉터요. 자기 말로는 귀여워서 그냥 툭 친 거라고 하더군.\n\n이제 복수를 할 때가 온 거요.\n\n검은바위 첨탑으로 가면 보쉬가진을 찾을 수 있소. 그녀를 처치하고 뱀돌을 가져오시오. 그러면 도끼 제작자가 되는 법을 가르쳐 주겠소.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n도끼 제작의 대가\n\n다음과 같은 것들을 받습니다:\n\n도면: 여명의 도끼"},
[5307] = {title = "부패의 검", objective = "스트라솔름에서 검은호위대 검제작자를 찾아 그를 처치하고 검은호위대 휘장을 회수한 후, 세릴 스컬지베인에게 갖다주어야 합니다.", description = "지금 제 신경이 날카로운 데는 다 이유가 있습니다. 리븐데어 남작의 정예 해골 군단인 검은호위대가 부패의 검을 만드는 도면을 훔쳐가 버렸어요.\n\n그래요. 스트라솔름의 리븐데어 남작 말입니다.\n\n검은호위대 검제작자가 이제 그의 언데드 부하들과 함께 목숨을 걸고 그 도면을 지키고 있답니다.\n\n가서 그를 처치하고 그 증거를 보여주시면 검 제작자가 되는 법을 가르쳐 드리죠.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n검 제작의 대가\n\n다음과 같은 것들을 받습니다:\n\n도면: 불타는 레이피어"},
[5321] = {title = "잠에서 깨어난 드루이드", objective = "케를로니안 에버섀이드를 잿빛 골짜기의 마에스트라 주둔지에 있는 릴라드리스 문리버에게 호위해 가야 합니다.", description = "나는 릴라드리스 문리버를 만나러 마에스트라 주둔지로 가던 길에 여기서 잠시 낮잠을 자려고 했었소. 에메랄드의 꿈에서 깬 뒤로는 얼마나 졸리는지...\n\n<하품을 합니다.>\n\n당신이 날 좀 데려다 주지 않겠소? 마에스트라 주둔지는 여기서 남쪽, 잿빛 골짜기에서 길을 따라가다 보면 있는 것 같소. 위험할 수도 있으니 함께 갈 친구들이 더 있었으면 좋겠소이다.\n\n그리고 마지막으로, 내가 또다시 잠이 들면 내 뿔피리를 사용해 나를 깨워주시오. 여기 궤짝 안에 있소.", progress = "케를로니안이 도착한 거예요?", completion = "케를로니안이 무사히 도착해서 정말 다행이군! 분명 이 근처 어딘가에서 잠에 빠져 있을 테죠...\n\n그를 데려다 줘서 정말 고마워요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n올빼미눈 소총비취나무 막대강철도금 방패\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5341] = {title = "바로브 가의 유산", objective = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 재산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 임무를 완수한 후 알렉시 바로브에게 돌아가야 합니다.", description = "안녕하신가. 나, 알렉시 바로브는 바로브 가의 마지막 두 상속자 중 한 명이오. 다른 한 명은 바로 내 형인 웰던이지.\n\n스칼로맨스 내부에 바로브 가의 유산이 있지. 그 한심한 겁쟁이 웰던은 전쟁 중에 도망 쳐서 인간으로서 무가치한 목숨을 부지하고 있어.\n\n이제는 땅문서들을 찾아서 유산을 모두 차지하려 하고 있지. 형이 찾기 전에 먼저 땅문서들을 찾아 준다면 꿈도 꾸지 못할 만큼 막대한 보상을 해 주도록 하지!", progress = "내 앞에서는 고개를 숙이라고, <race>. 나는 고상한 신분이고 그쪽은 결국 땡전 한푼 없는 천한 신분 아닌가?", completion = "아주 잘했군. 이제 내 유산을 안전하게 보관해 둬야겠어...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5342] = {title = "최후의 상속자", objective = "얼라이언스 영토인 서리바람 야영지로 가서 웰던 바로브를 암살해야 합니다. 그 증거로 그의 머리카락을 가지고 알렉시 바로브에게 돌아가십시오.\n\n얼라이언스 쓰레기들이 웰던을 보호하고 있을 테니 조심해야 합니다.", description = "형이 살아 있는 한 당연히 가문의 상속자가 누가 될 것인가 하는 문제가 생기는데, 그래서는 안 되지.\n\n그쪽 같은 하층 계급에게 한 명 정도 처리하는 정도야 문제도 아닐 거야. 간단한 임무이고 분명 해낼 수 있을 거야. 또 보상을 받을 수 있을 테지.\n\n웰던은 동쪽의 서리바람 야영지에서 얼라이언스의 보호를 받으며 지내고 있소. 그를 처치하고 그 증거를 내게 가져오라고.\n\n<하품을 하는 알렉시>\n\n어서 가보게.", progress = "내가 재산을 차지하면 조금 나누어 주도록 하지.", completion = "옳거니! 이제 나만이 바로브 가의 권력과 재산을 차지하겠군!\n\n&lt;큰 자루를 던져주는 알렉시&gt;\n\n거스름돈은 필요 없다, 더러운 짐승 같으니라고.", rewards = "다음과 같은 것들을 받습니다:\n\n바로브의 종"},
[5343] = {title = "바로브 가의 유산", objective = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 유산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 이 임무를 완수한 후 웰던 바로브에게 돌아가야 합니다.", description = "내 사랑하는 동생 알렉시. 내가 녀석이 목숨을 부지하도록 놔두는 어리석은 짓을 저질렀다니... 언데드의 일원인 적과 얼굴을 정면으로 맞대고도 동생을 살려줘 버렸습니다.\n\n<투덜대는 웰던>\n\n녀석은 내 유산을 노리고 있는데, 절대 있을 수 없는 일입니다.\n\n저 사악한 녀석이 그 뼈밖에 남지 않은 손으로 유산을 가로채기 전에 내 가족의 땅문서를 찾아 준다면 내 아주 후하게 보상하도록 하겠습니다. 땅문서들은 스칼로맨스의 폐허에 있으니 서두르십시오!", progress = "그쪽이 내 미래를 보장해 준다면 나도 그쪽의 미래를 보장하겠습니다.", completion = "고맙습니다. 그런데 딱 한 가지만 더 부탁할 게 더 있습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5344] = {title = "최후의 바로브", objective = "호드의 영토인 보루로 가서 알렉시 바로브를 암살하십시오. 그 증거로 그의 머리카락을 가지고 웰던 바로브에게 돌아가십시오.\n\n더러운 호드가 알렉시를 보호하고 있을 테니 조심해야 합니다.", description = "땅문서를 다 회수했으니 이제 딱 한 가지, 알렉시를 제거하는 일만 남았군요. 녀석이 죽으면 다시는 비양심적인 용병 무리가 나를 노리는 것에 대해 걱정할 필요가 없게 되지요.\n\n아, 간단한 일입니다. 알렉시는 보루에서 호드의 보호 아래 숨어 있습니다.\n\n당장 녀석이 있는 곳으로 가서 처치하는 것까지 기대하진 않지만 아무튼 녀석의 머리카락을 가져와 주십시오! 뭐, 그걸 어떻게 가져올 수 있을지는 그쪽 판단에 맡기도록 하겠습니다. 그런 천한 행위는 나처럼 고귀하게 자란 이들이 상관할 일이 못 되니까 말입니다.", progress = "보수를 받고 싶지 않은 겁니까?", completion = "영광스러운 날이로군! 드디어 바로브 가의 오점을 영원히 제거했고 내 재산도 안전해졌군!\n\n이걸 줄 테니 어서 썩 사라져라, 천한 것!", rewards = "다음과 같은 것들을 받습니다:\n\n바로브의 종"},
[5361] = {title = "형제애", objective = "절벽파수꾼 롱혼의 보고서를 잊혀진 땅의 침묵의 초소에 있는 나타카 롱혼에게 가져가야 합니다.", description = "내 동생 나타카는 잊혀진 땅, 침묵의 초소에 있다네. 흠, 그러니까... 이 보고서를 나타카에게 전해주겠나? 마지막으로 소식을 전한지 벌써 일년이나 흘렀네. 그 이후, 켄타우로스족이 수상한 조짐을 보이고 있어. 반드시 이 사실을 알려야 하네.\n\n크로스로드의 북쪽에 있는 돌발톱 산맥으로 간 다음 서쪽으로 가면 잿더미 계곡이 나올 거야. 거기서 남쪽으로 내려가면 잊혀진 땅이 나오지. 일단 잊혀진 땅에 도착하면 침묵의 초소를 향해 남쪽으로 이어진 길을 쉽게 찾을 수 있을 걸세.", progress = "<class>, 무슨 소식이라도 가지고 온 것이오? 아! 형이 보낸 전갈이라고요? 당장 그 보고서 좀 봅시다!", completion = "&lt;class&gt;|1이여;여;, 당신이 형과 얼마나 친한지는 모르겠지만, 형 말이 당신을 믿으라는군.\n\n내 이름은 나타카 롱혼이라고 합니다. 침묵의 초소에 잘 오셨습니다. 마침 쓸만한 &lt;class&gt; 용병이 필요하던 참이었는데. 이곳에 있는 다른 이들과도 이야기를 나눠보십시오. 많은 곳에서 당신의 도움을 필요로 하고 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5381] = {title = "이룩소스의 손", objective = "천둥도끼 요새에서 악마의 상자를 찾아서 그늘수렵 마을에 있는 타이가 와이즈메인에게 가져가십시오. 악마의 곡괭이도 함께 돌려줘야 합니다.", description = "불타는칼날단의 악마의 상자 안에는 강한 힘을 지닌 이룩소스의 손이 들어 있습니다. 불타는칼날단은 이룩소스의 손으로 만노로크 소굴에 있는 악마의 차원문을 열려고 합니다. 우리 세계에 악마들이 밀려오는 것을 반드시 막아야만 합니다!\n\n천둥도끼 요새에 있는 붉은 수정에 이 악마의 곡괭이를 사용해서 악마의 상자를 열도록 하십시오.", progress = "악마의 상자는 가져왔습니까?", completion = "아, 악마의 상자로군. 이리 주십시오. 제가 열도록 하겠습니다, &lt;class&gt;. 드디어 이룩소스의 손의 비밀을 내 손으로 밝혀내는군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5382] = {title = "도살자, 테올렌 크라스티노브", objective = "스칼로맨스 내에서 학자 테올렌 크라스티노브를 찾아 처치한 후 에바 사크호프의 유해와 루시엔 사크호프의 유해를 불태우십시오. 임무를 완수하면 에바 사크호프에게 돌아가야 합니다.", description = "크라스티노브는 수천 명을 죽인 살인자예요. 벌 받아 마땅한 자이니 녀석에게 정의의 처단을 내려야만 해요.\n\n녀석을 찾아 수없이 많은 무고한 생명에게 가한 고통을 그대로 되돌려주세요. 녀석을 처치한 후 우리의 시체를 불태워 주세요. 잿더미로 만들어 버리는 겁니다.", progress = nil, completion = "제 영혼이 회복되는 것을 느낄 수 있어요. 저와 제 남편에게 아주 큰 도움을 주신 겁니다. 하지만 전 틀림없이 아직 더 해야 할 일이 있을 거예요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5384] = {title = "사자 키르토노스", objective = "순결한 피를 가지고 스칼로맨스로 돌아가야 합니다. 사자의 창을 찾아 사자의 화롯불에 순결한 피를 올려 놓으면 키르토노스가 영혼을 차지하기 위해 나타납니다.\n\n용맹하게 싸우고 단 한 발짝도 물러서지 마십시오! 키르토노스를 처치한 후 에바 사크호프에게 돌아가야 합니다.", description = "바로 이거예요.\n\n<에바가 가방 안에 있는 유리병을 가리킵니다.>\n\n무고한 이들의 피. 크라스티노브가 자기 주인을 기쁘게 하기 위해 사용하는 가장 순수한 피죠.\n\n키르토노스는 이 피로 소환할 수 있어요. 그리고 이 피로 키르토노스를 처치해야만 합니다.\n\n이 피를 전령의 창으로 가져가서 화로 위에 올려 놓으세요. 키르토노스가 나타날 거예요. 저항할 수 없죠. 그가 나타나면 1천 명의 무고한 죽음에 대한 분노와 화를 그에게 쏟아 놓으세요.\n\n성공하면 우리의 감사뿐 아니라 그 이상을 얻게 될 겁니다.", progress = nil, completion = "키르토노스의 죽음으로 스칼로맨스의 끔찍한 이야기의 한 장이 종결되었군요. 하지만 아직도 해야 할 일이 더 남아 있습니다. 이제 이곳에 있는 다른 이들이 당신의 용맹한 행동에 대해 알게 되었답니다. 자, 이걸 받으세요. 우리의 정수 중 일부예요. 이게 있으면 카엘 다로우의 다른 길 잃은 영혼들과 대화를 나눌 수 있을 겁니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n페넬로프의 장미미라의 노래\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n영혼의 정수"},
[5385] = {title = "트레이 라이트포지의 유해", objective = "트레이 라이트포지의 유해를 악령의 숲에 있는 제시 문보우에게 가져다주어야 합니다.", description = "유해를 담은 자루를 조심스럽게 메고 악령의 숲과 잿빛 골짜기의 경계에 있는 제시 문보우에게 돌아갈 준비를 합니다. 이 성기사의 친구들에게 유해를 건네주면 제대로 된 장례식을 치러 줄 수 있을 것입니다.", progress = "자에데나르에서의 일은 잘 됐습니까, <name>?", completion = "해내셨군요! 엘룬과 그대가 섬기는 분에게 찬미를! &lt;name&gt;, 오늘 숭고하고 명예로운 일을 하셨습니다. 그대가 목숨을 구해주신 아르코나린이 친구의 복수까지 대신 해주셨다는 걸 알면, 넘치는 기쁨과 감사에 눈물을 쏟고 말 거예요.\n\n이 은혜는 그 무엇으로도 갚을 수가 없겠지만 감사의 표시로 이것을 받아주세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n추적자 단검해일갈기 검\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5386] = {title = "낚시하는 날", objective = "그늘수렵 마을에 있는 지나르질렌과 대화한 후 나타카 롱혼에게 붉은복어 2마리를 가져가야 합니다.", description = "이곳 침묵의 초소에 있으면 생선 요리 냄새가 정말 그립답니다. 그늘수렵 마을의 트롤들이 고기를 낚는데는 최고지요... 그런데 안타깝게도 켄타우로스들이 여기 저기 활동하고 있어 트롤 마을로 여행할 시간이 거의 없습니다. 흠...\n\n제 부탁 좀 들어 주십시오. 그늘수렵 마을의 지나르질렌이라는 어부에게서 제가 좋아하는 붉은복어를 가져다주십시오. 여기서 남쪽 길을 따라가면 트롤 마을 서쪽에 도착할 수 있을 겁니다.", progress = "기름에 튀긴 붉은복어를 생각하면 발굽을 동동 구르게 되고 입에 침이 고이네요. 붉은복어를 가지고 오셨나요?", completion = "오, 그대는 구세주로군요! 붉은복어가 날로 먹어도 될 만큼 신선하군요.\n\n&lt;군침을 흘리는 나타카&gt;\n\n이 중에서 하나를 고르세요. 붉은복어를 가져다주신 데 대한 보답입니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n미스릴 광석두꺼운 가죽마법 옷감\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5401] = {title = "은빛 여명회 위임봉", objective = "은빛 여명회를 대신해 악과 싸우는 자들은 모두 우리의 위임봉을 착용해야 합니다. 이 위임봉을 착용함으로써 병참장교들이 반드시 제공해야 하는 보상을 받을 권리가 생기는 것입니다.\n\n이 위임봉을 착용하고 있는 동안 스컬지를 쓰러뜨리면 스컬지석을 얻을 수 있습니다. 스컬지와 전투 중에 가끔 녀석들이 소지하고 있는 표장인 스컬지석을 얻을 수 있을 테니 그걸 찾으면 나에게 가져오십시오. 한 세트씩 가져올 때마다 영웅적인 행위를 증명하는 은빛 여명회 명예 휘장을 드리도록 하겠습니다.\n\n오늘 전투에 참여하여 형제님의 운명을 이루십시오!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 위임봉"},
[5402] = {title = "앞잡이의 스컬지석", objective = "앞잡이의 스컬지석은 스컬지 사병들의 표장입니다. 이 표장은 역병지대에 배치된 부대들 중 좀 약한 무리들에게서 종종 찾을 수 있습니다. 하지만 \"좀 약하다\"고 해서 녀석들을 얕잡아봐서는 절대 안 됩니다. 스컬지는 어디에 있든지 결코 과소평가해서는 안 될 상대랍니다.\n\n현재 은빛 여명회에서는 이 표장 20개를 가져오는 이에게 명예 휘장 하나씩을 지급하고 있습니다. 스컬지석을 충분히 모아 오면 기꺼이 명예 휘장과 교환해 드리도록 하겠습니다.", description = nil, progress = "앞잡이의 스컬지석은 스컬지 사병들의 표장입니다. 이 표장은 역병지대에 배치된 부대들 중 좀 약한 무리들에게서 종종 찾을 수 있습니다. 하지만 \"좀 약하다\"고 해서 녀석들을 얕잡아봐서는 절대 안 됩니다. 스컬지는 어디에 있든지 결코 과소평가해서는 안 될 상대랍니다.\n\n현재 은빛 여명회에서는 이 표장 20개를 가져오는 이에게 명예 휘장 하나씩을 지급하고 있습니다. 스컬지석을 충분히 모아 오면 기꺼이 명예 휘장과 교환해 드리도록 하겠습니다.", completion = "축하합니다. 형제님께 은빛 여명회 명예 휘장을 지급하게 된 것을 기쁘게 생각합니다!\n\n이 휘장에는 두 가지 용도가 있어요. 첫째, 은빛 여명회 내에서의 지위를 높이는 데 쓰일 수 있습니다. 휘장을 사용하여 명예롭고 존경 받는 동지들에게만 주어지는 옵션과 보상을 얻을 수 있게 되는 것입니다. 둘째, 은빛 여명회에서 보유한 진귀한 물건 중 일부를 구입할 때 우리 병참장교들에게 지불하기 위한 수단으로 돈과 함께 사용할 수 있습니다.\n\n어떤 결정을 내리든 이 위임봉은 형제님께서 마땅히 받을 만한 일을 했기 때문에 지급되는 것임을 명심하시기 바랍니다. 수고하셨습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 명예 휘장"},
[5403] = {title = "침입자의 스컬지석", objective = "침입자의 스컬지석은 스컬지의 정예 군단이 지니는 표장이죠. 역병지대에 배치된 부대들 중에서도 좀 더 강한 녀석들에게서 종종 찾을 수 있습니다. 이러한 녀석을 처치하는 것이 사실 쉽지 않지만, 악의 처단이라는 임무를 마음에 새기며 즐겨야 할 임무라고 할 수 있습니다.\n\n은빛 여명회에서는 현재 이 표장 10개를 가져오는 이에게 명예 휘장 하나를 주고 있습니다. 내게 그 표장들을 가져오시면 형제님께서 마땅히 받아야 할 보상을 반드시 지급하도록 하겠습니다.", description = nil, progress = "침입자의 스컬지석은 스컬지의 정예 군단이 지니는 표장이죠. 역병지대에 배치된 부대들 중에서도 좀 더 강한 녀석들에게서 종종 찾을 수 있습니다. 이러한 녀석을 처치하는 것이 사실 쉽지 않지만, 악의 처단이라는 임무를 마음에 새기며 즐겨야 할 임무라고 할 수 있습니다.\n\n은빛 여명회에서는 현재 이 표장 10개를 가져오는 이에게 명예 휘장 하나를 주고 있습니다. 내게 그 표장들을 가져오시면 형제님께서 마땅히 받아야 할 보상을 반드시 지급하도록 하겠습니다.", completion = "대단하군요. 형제님께 은빛 여명회 명예 휘장을 드리게 된 것을 기쁘게 생각합니다!\n\n받을 자격이 주어지는 자에게 지급하는 각 명예 휘장은 스컬지와의 전쟁에서 전세를 역전시킨 것에 대한 증거를 나타냅니다. 더 많은 영웅들이 자신들의 땅에서 스컬지와 싸우고 있으니 스컬지라는 궁극적인 악과 전쟁을 벌일 때가 오면 틀림없이 은빛 여명회가 최전선에서 싸우게 될 겁니다. 오늘날 이 휘장을 받기까지 형제님께서 보여 준 그 용맹스러움이 그날에도 우리에게 승리를 안겨 주게 되길 바랍니다!", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 명예 휘장"},
[5404] = {title = "타락자의 스컬지석", objective = "타락자의 스컬지석은 스컬지 우두머리들의 표장입니다. 스컬지를 다스리는 직위를 가진 강력한 언데드라면 항상 하나씩 지니고 있지요. 그런 사악한 생물을 처치하는 것은 틀림없이 은빛 여명회의 대의와 모든 선한 대의의 실현을 앞당기게 될 겁니다!\n\n은빛 여명회를 대신해 형제님께 이 표장 하나를 명예 휘장 하나와 교환해 드리도록 하겠습니다. 그토록 강력한 존재들에 함부로 맞서서는 안 될 일이니 이 표장을 얻을 때는 조심하시기 바랍니다.", description = nil, progress = "타락자의 스컬지석은 스컬지 우두머리들의 표장입니다. 스컬지를 다스리는 직위를 가진 강력한 언데드라면 항상 하나씩 지니고 있지요. 그런 사악한 생물을 처치하는 것은 틀림없이 은빛 여명회의 대의와 모든 선한 대의의 실현을 앞당기게 될 겁니다!\n\n은빛 여명회를 대신해 형제님께 이 표장 하나를 명예 휘장 하나와 교환해 드리도록 하겠습니다. 그토록 강력한 존재들에 함부로 맞서서는 안 될 일이니 이 표장을 얻을 때는 조심하시기 바랍니다.", completion = "축하합니다. 형제님께 은빛 여명회 명예 휘장을 지급하게 된 것을 기쁘게 생각합니다!\n\n이러한 방법으로 명예 휘장을 얻는다는 것은 형제님께서 선한 대의를 추구하는 진정한 영웅이라는 것을 보여 주는 것이랍니다. 스컬지에 대항하는 모든 노력이 값지지만 놈들의 지도자 중 하나를 처치하는 것은 진정 녀석들에게 큰 타격을 입히는 것이 됩니다!\n\n은빛 여명회를 위하여, 형제여!", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 명예 휘장"},
[5405] = {title = "은빛 여명회 위임봉", objective = "은빛 여명회를 대신해 악과 싸우는 자들은 모두 우리의 위임봉을 착용해야 하네. 이 위임봉을 착용함으로써 병참장교들이 제공해야만 하는 보상을 받을 권리가 생기게 되는 것이지.\n\n이 위임봉을 착용하고 있는 동안 스컬지를 쓰러뜨리면 스컬지석을 얻을 수 있을 걸세. 스컬지와 전투 중에 가끔 녀석들이 소지하고 있는 표장인 스컬지석을 얻을 수 있을 테니 그걸 찾으면 나에게 가져오게나. 한 세트씩 가져올 때마다 자네의 영웅적인 행위를 증명하는 은빛 여명회 명예 휘장을 주도록 하지.\n\n오늘 전투에 참여하여 자네의 운명을 이루게!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 위임봉"},
[5406] = {title = "타락자의 스컬지석", objective = "타락자의 스컬지석은 스컬지 우두머리들의 표장이라네. 스컬지를 다스리는 직위를 가진 강력한 언데드라면 항상 하나씩 지니고 있지. 그런 사악한 생물을 처치하는 것은 틀림없이 은빛 여명회의 대의와 모든 선한 대의의 실현을 앞당기게 될 것이네!\n\n은빛 여명회를 대신해 자네에게 이 표장 하나를 명예 휘장 하나와 교환해 주도록 하지. 그토록 강력한 존재들에게 함부로 맞서서는 안 될 일이니까 이 표장을 얻을 때는 조심하도록 하게나.", description = nil, progress = "타락자의 스컬지석은 스컬지 우두머리들의 표장이라네. 스컬지를 다스리는 직위를 가진 강력한 언데드라면 항상 하나씩 지니고 있지. 그런 사악한 생물을 처치하는 것은 틀림없이 은빛 여명회의 대의와 모든 선한 대의의 실현을 앞당기게 될 것이네!\n\n은빛 여명회를 대신해 자네에게 이 표장 하나를 명예 휘장 하나와 교환해 주도록 하지. 그토록 강력한 존재들에게 함부로 맞서서는 안 될 일이니까 이 표장을 얻을 때는 조심하도록 하게나.", completion = "축하하네. 자네에게 은빛 여명회 명예 휘장을 지급하게 되어 기쁘게 생각하네!\n\n이런 방법으로 명예 휘장을 얻는다는 것은 자네가 선한 대의를 추구하는 진정한 영웅이라는 것을 보여 주는 것이지. 스컬지에 대항하는 모든 노력이 값지지만 놈들의 지도자 중 하나를 처치하는 것은 녀석들에게 큰 타격을 입히는 것이 된다네!\n\n은빛 여명회를 위하여!", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 명예 휘장"},
[5407] = {title = "침입자의 스컬지석", objective = "침입자의 스컬지석은 스컬지의 정예 군단이 지니는 표장일세. 역병지대에 배치된 부대들 중에서도 보다 강한 녀석들에게서 종종 찾을 수 있지. 사실 그러한 생물을 처치하는 것이 쉽지 않지만, 악의 처단이라는 임무를 마음에 새기며 즐겁게 전투에 임해야 할 것일세.\n\n은빛 여명회에서는 현재 이 표장 10개를 가져오는 이에게 명예 휘장 하나를 지급하고 있네. 이곳으로 내게 그 표장들을 가져오면 자네가 마땅히 받아야 할 보상을 반드시 지급하도록 하지.", description = nil, progress = "침입자의 스컬지석은 스컬지의 정예 군단이 지니는 표장일세. 역병지대에 배치된 부대들 중에서도 보다 강한 녀석들에게서 종종 찾을 수 있지. 사실 그러한 생물을 처치하는 것이 쉽지 않지만, 악의 처단이라는 임무를 마음에 새기며 즐겁게 전투에 임해야 할 것일세.\n\n은빛 여명회에서는 현재 이 표장 10개를 가져오는 이에게 명예 휘장 하나를 지급하고 있네. 이곳으로 내게 그 표장들을 가져오면 자네가 마땅히 받아야 할 보상을 반드시 지급하도록 하지.", completion = "대단하군. 자네에게 은빛 여명회 명예 휘장을 지급하게 되어 기쁘네!\n\n받을 자격을 갖춘 이에게 지급하는 명예 휘장은 스컬지와의 전쟁에서 전세를 역전시켰다는 증거지. 더욱 많은 영웅들이 자신들의 땅에서 싸우고 있으니 스컬지라는 궁극적인 악과 전쟁을 벌일 때가 오면 틀림없이 은빛 여명회가 최전선에서 싸우게 될 걸세. 오늘날 이 휘장을 받기까지 자네가 보여 준 그 용맹스러움이 그날에도 우리에게 승리를 안겨 주게 되길 바라네!", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 명예 휘장"},
[5408] = {title = "앞잡이의 스컬지석", objective = "앞잡이의 스컬지석은 스컬지 사병들의 표장일세. 이 표장은 역병지대에 배치된 부대들 중 좀 약한 무리들에게서 가끔 찾을 수 있지. 하지만 좀 약하다고 해서 녀석들을 얕잡아봐서는 절대 안 되네. 스컬지는 어디에 있든지 결코 과소평가해서는 안 될 상대라네.\n\n현재 은빛 여명회에서는 이 표장 20개를 가져오는 이에게 명예 휘장 하나를 지급하고 있네. 스컬지석을 충분히 모아 오면 기꺼이 명예 휘장과 교환해 주도록 하지.", description = nil, progress = "앞잡이의 스컬지석은 스컬지 사병들의 표장일세. 이 표장은 역병지대에 배치된 부대들 중 좀 약한 무리들에게서 가끔 찾을 수 있지. 하지만 좀 약하다고 해서 녀석들을 얕잡아봐서는 절대 안 되네. 스컬지는 어디에 있든지 결코 과소평가해서는 안 될 상대라네.\n\n현재 은빛 여명회에서는 이 표장 20개를 가져오는 이에게 명예 휘장 하나를 지급하고 있네. 스컬지석을 충분히 모아 오면 기꺼이 명예 휘장과 교환해 주도록 하지.", completion = "축하하네. 자네에게 은빛 여명회 명예 휘장을 지급하게 된 것을 기쁘게 생각하네!\n\n이 휘장에는 두 가지 용도가 있지. 첫째, 은빛 여명회 내에서의 지위를 높이는 데 쓰일 수 있네. 휘장을 사용하여 명예롭고 존경 받는 동지들에게만 주어지는 옵션과 보상을 얻을 수 있게 되는 것이지. 둘째, 은빛 여명회에서 보유한 귀한 물건들 중 일부를 구입할 때 돈과 함께 우리 병참장교들에게 지불하는 데 사용할 수 있네.\n\n어떤 결정을 내리든 이 위임봉은 자네가 마땅히 받을 만한 성과를 올렸기 때문에 받는 것임을 명심하기 바라네. 수고했네!", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 명예 휘장"},
[5421] = {title = "들통 속의 복어", objective = "난 내 생활을 좀 더 편하게 해주는 자에게 보답을 하지. 되도록이면 움직이지 않는 게 좋거든!\n\n이곳 그늘수렵 마을의 부두 아래에 가면 내가 설치한 가재 통발이 많이 있네. 가재를 모아서 나에게 가져다주면 보답으로 원하는 걸 주겠네. 알아들었겠지? 가재 5마리당 붉은복어 한 마리를 주지!", description = nil, progress = "난 내 생활을 좀 더 편하게 해주는 자에게 보답을 하지. 되도록이면 움직이지 않는 게 좋거든!\n\n이곳 그늘수렵 마을의 부두 아래에 가면 내가 설치한 가재 통발이 많이 있네. 가재를 모아서 나에게 가져다주면 보답으로 원하는 걸 주겠네. 알아들었겠지? 가재 5마리당 붉은복어 한 마리를 주지!", completion = "잘했어. 다른 누군가가 무언가를 해 주는 것처럼 좋은 일도 없지. 안 그런가?", rewards = "다음과 같은 것들을 받습니다:\n\n붉은복어"},
[5441] = {title = "게으른 일꾼들", objective = "작업반장의 몽둥이를 가지고 가서 자고 있는 게으른 일꾼에게 사용해야 합니다. 일꾼 5명을 깨운 다음 시험의 골짜기에 있는 작업반장 타즈릴에게 돌아가 몽둥이를 돌려줘야 합니다.", description = "망할 놈의 일꾼들! 이곳 주변 숲에서 땔감을 모아 오기는 하는데 허구한 날 잠을 잔단 말이야! 열심히 일하도록 누군가 감시를 해야 하는데...\n\n당신이 적임자로 보이는군. 자, 이 몽둥이를 받으시오. 혹 일하다 말고 농땡이를 부리며 조는 녀석이 있거든 쓰시오. 한 대 후려치면 정신 차리겠지! 일이 끝나면 몽둥이를 다시 가져오시오.\n\n휴... 빈둥대기만 하는 형편없는 일꾼 놈들!", progress = "아무짝에도 쓸모없는 게으름뱅이들...\n\n엉? 내 몽둥이는 가져왔소? 일하다 말고 자는 놈들은 전부 잡았겠지?", completion = "좋아, 좋아! 다음부터는 빈둥거리지 못하겠지! 정신이 번쩍 났을 거야. 도와줘서 고맙소이다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5461] = {title = "라스 프로스트위스퍼", objective = "아라시 고원에 있는 스트롬가드 폐허로 가십시오. 스트롬가드에서 추억의 유품을 찾아야 합니다. 그런 물건을 찾으면 집정관 마르듀크에게 돌아가야 합니다.", description = "산 자가 죽음을 두려워하듯 언데드는 삶을 두려워한다네. 언데드로 변한 자들 중 지각이 있는 자들이 자신의 전생과 관련해 남아 있는 모든 것을 완전히 파괴해 버리는 것이 흔한 일이지.\n\n안타깝게도 라스 프로스트위스퍼를 다시 산 자로 바꿔 놓을 수 있는 힘을 지닌 유물을 만들려면 그가 살아 생전에 가지고 있던 유품이 있어야 하네.\n\n폐허가 된 스트롬가드에 있는 프로스트위스퍼의 집으로 가서 그런 물건을 찾아보게. 행운을 빌겠네.", progress = "추억의 유품이란 찾기 쉬운 물건이 아니라네.", completion = "나는 그런 물건이 정말로 존재하는가에 대해 의심해 왔지. 이제 이것으로 결코 놓쳐서는 안 될 그런 엄청난 기회가 찾아온 걸세.\n\n단단히 각오를 하게. 이제 내가 자네에게 맡길 임무를 수행하려면 지옥의 한복판까지 가야 할 테니까 말이야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5462] = {title = "망자, 라스 프로스트위스퍼", objective = "동부 역병지대에 있는 희망의 빛 예배당으로 가서 존경받는 리어니드 바돌로매를 찾아서 추억의 유품을 보여 주고 알아낸 사실에 대해 모두 얘기해야 합니다.", description = "더럽혀진 땅에서 이 유품을 맞춰야 하네.\n\n프로스트위스퍼가 리치 왕에게 굴복한 것은 스트라솔름에서였다고들 하네. 그는 기꺼이 죽지 않는 자가 되기 위한 수작으로 그 피 묻은 땅에서 자신의 생명을 바쳤지.\n\n바로 그 곳을 찾아야만 하네.\n\n밴시 여왕에 의해 해방되었지만 은빛 여명회의 대의에 충성하는 언데드 스컬지 반대자가 하나 있지. 존경받는 리어니드 바돌로매라고 하는 자인데, 그가 더 자세히 알 테니 그를 찾아가 보게. 그는 희망의 빛 예배당에 있을 걸세.", progress = "답을 알고 싶지 않은 질문은 하지 말게나.", completion = "&lt;유품을 살펴보는 리니어드&gt;\n\n자네가 처한 진퇴양난의 상황을 보니 다시는 떠올리고 싶지 않았던 기억이 되살아나는군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5463] = {title = "메네실의 선물", objective = "스트라솔름으로 가서 메네실의 선물을 찾아서 그 부정한 땅 위에 추억의 유품을 두어야 합니다.", description = "난 라스 프로스트위스퍼라는 인간이 리치 왕에게 불멸의 영혼을 바치는 것을 봤다네. 미소를 띤 채 스스로 목숨을 끊었지. 그 마법사의 육체는 오각형 마법진 안에 쓰러졌고 그 위에 리치 왕이 우뚝 서더니 이상야릇한 동작을 취했지. 그리고 라스 프로스트위스퍼는 리치로 다시 태어났다네.\n\n<땅을 보다가 다시 고개를 들어 이쪽을 바라보는 리어니드>\n\n그래, 기억나는군. 자네가 찾는 것의 이름은 바로 메네실의 선물이지. 리치 왕이 축복한 땅이자 스컬지들의 성지라는 뜻일세.", progress = "이상하게도 메네실의 선물 주위만 엄청나게 춥습니다.", completion = "유품을 오염된 흙 위에 놓습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5464] = {title = "메네실의 선물", objective = "동부 역병지대에 있는 리어니드 바돌로매에게 영혼이 씌인 유품을 가져가야 합니다.", description = "망자의 영혼이 자신의 전생을 나타내는 이 물건에 붙어 영혼이 씌인 유품으로 변형시킵니다. 물건을 집어 소지품에 넣습니다.", progress = "<부르르 떠는 리어니드>", completion = "유품에 영혼이 달라붙었듯이 이 유품은 라스 프로스트위스퍼의 육체에 달라붙게 될 것일세.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5465] = {title = "영혼이 씌인 유품", objective = "카엘 다로우에 있는 집정관 마르듀크에게 돌아가십시오. 그에게 영혼이 씌인 유품을 보여줘야 합니다.", description = "유품을 가지고 마르듀크에게 돌아가게. 그가 사용법을 알려 줄 것일세.", progress = "불가능한 일을 해낸 것인가?", completion = "분명 자네도 나처럼 불운한 영혼이 되어 나와 함께하게 될 줄 알았다네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5466] = {title = "리치, 라스 프로스트위스퍼", objective = "스칼로맨스에서 라스 프로스트위스퍼를 찾아야 합니다. 영혼이 쓰인 유품을 언데드 상태인 라스의 얼굴에 사용하십시오. 그를 산 자로 되돌리는 데 성공하면 그를 쓰러뜨리고 사람이 된 라스 프로스트위스퍼의 머리카락을 가지고 집정관 마르듀크에게 가야 합니다.", description = "이제 딱 한 가지 임무만이 남았네. 리치인 라스 프로스트위스퍼의 소굴로 가서 그와 맞서게.\n\n망설이지 말고 유품의 힘을 사용하게! 그 괴물의 무자비한 공격에도 버텨내야 할 걸세. 고통에 무릎을 꿇어서는 안 되네!\n\n의식이 끝나면 라스는 다시 한번 산 자가 될 걸세. 바로 그때 그를 처치해야 하네. 그를 쓰러뜨리고 인간으로 변한 그의 머리카락을 가져오게.", progress = "<name>, 자네는 안식을 얻지 못한 일만 명의 영혼을 위해 이 일을 해야 하네.", completion = "일만 명의 영혼이 한목소리로 자네의 이름을 외치고 있네! 자네가 스컬지와 그 지도자들에게 크게 한 방 먹인 거야!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n카엘 다로우의 전투검카엘 다로우의 관다로우의 쐐기\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n다로우샤이어 수호방패"},
[5481] = {title = "고르도의 임무", objective = "어둠풀 3개를 채집해 브릴 공동묘지에 있는 초보연금술사 홀랜드에게 가져가야 합니다.", description = "주인님 잡초를 원하신다. 우리 손 커서 풀 잘 못 뽑는다. 우리 도와 주면 해치지 않는다. 우리 어둠풀 필요하다. 여기하고 길 근처에 잡초 많다.\n\n어둠풀 뽑았으면 브릴 공동묘지로 가서 홀랜드 주인님에게 가져가라.", progress = "이 아무짝에도 쓸모없는 누더기골렘 녀석은 어디로 간 거야? 내가 필요로 하는 걸 가져온 게 아니라면 어서 가서 찾아오는 게 좋을 거야.", completion = "이게 뭐지? 어둠풀이잖아? 어둠풀은 필요 없다니까! 저 멍청하고 덩치만 큰 고르도 녀석은 가서 데이지나 뽑아 대면서 자네 같은 얼간이들로 하여금 똑같은 짓을 하도록 하고 있군. 자네 기분을 상하게 하려는 건 아니네.\n\n좋아. 지금 자네는 여기 있고, 중요한 건 그뿐이지. 저 누더기골렘 녀석에게 설명해 줄 생각은 없으니 자네가 가서 내가 정말로 필요로 하는 걸 모아다 주는 게 어떻겠나? 죽음풀 말이야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5482] = {title = "죽음풀", objective = "초급연금술사 홀랜드에게 죽음풀 10개를 모아서 가져가야 합니다.", description = "내 어려움이 뭔지 알겠지? 저기 바깥에 있는 녀석이 엉뚱한 풀을 모으고 있단 말이야! 내가 필요한 것들을 모아 주게. 죽음풀을 충분히 가져다주면 적절한 보상을 하도록 하지.\n\n죽음풀은 큰 무덤가 근처의 식물계를 전염시키는 것으로 알고 있네. 죽음풀은 브릴 무덤의 북쪽에 있는 큰 무덤가에 있으니 서두르게. 그리고 그 지역의 놀을 조심하도록 하게나.", progress = "이게 좋겠군. 내가 필요로 하는 죽음풀을 모두 가져다주리라 믿어도 되겠지?", completion = "아, 내 죽음풀. 아주 훌륭해!\n\n&lt;탐욕스러운 모습으로 양손을 비비는 초보연금술사 홀랜드.&gt;\n\n많은 도움이 될 거야. 오늘 내 부탁을... 음... 어둠의 여왕님의 명을 잘 들어주었군. 내가 약속했던 보상일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5501] = {title = "뼈 수집가", objective = "코르메크의 오두막에 있는 비블리 푸츠버클에게 코도 무덤에서 코도 뼈 10개를 가져가야 합니다.", description = "우리가 깔고 앉은 건 노다지야, 노다지! 코도 뼈는 세상을 영원히 바꿀 거야. 나에겐 코도 뼈로 가구나 악기 심지어 폭약까지 만들어내는 고객들이 있지.\n\n짐마차가 와서 내 코도 뼈를 싣고 가서 그늘수렵 마을에 파는 거야. 여기서 남쪽에 있는 코도 무덤으로 가서 코도 뼈 10개를 가져다주면 보답을 하도록 하지. 거래하겠나?", progress = "뼈를 가지고 있나? 짐마차가 곧 도착할 거야. 코도 뼈 10개만 더 있으면 출세길은 보장되는거야. 출세길이란 말이야. 출세길!", completion = "오, 좋아! 내 코도 뼈들아!\n\n고향 친구들이 고블린 피플즈의 겉표지 앞장에서 내 얼굴을 보게 된다고 생각하니 정말 흥분되는군. 난 세상에서 제일 부자 고블린이 될 거라고. 내 고블린 학교 물리 선생님이 나보고 크게 성공할 거라고 했었단 말이지, 하하.", rewards = "다음과 같은 것들을 받습니다:\n\n코도 뼈목걸이"},
[5503] = {title = "은빛 여명회 위임봉", objective = "은빛 여명회를 대신해 악과 싸우는 자들은 모두 우리의 위임봉을 착용해야 하네. 이 위임봉을 착용함으로써 병참장교들이 반드시 제공해야 하는 보상을 받을 권리가 생기는 것이지.\n\n이 위임봉을 착용하고 있는 동안 스컬지를 쓰러뜨리면 스컬지석을 얻을 수 있을 것이네. 스컬지와 전투 중에 가끔 녀석들이 소지하고 있는 표장인 스컬지석을 얻을 수 있을 테니 그걸 찾으면 나에게 가져오게. 한 세트씩 가져올 때마다 영웅적인 행위를 증명하는 은빛 여명회 명예 휘장을 주겠네.\n\n오늘 싸움에 참여하여 자네의 운명을 개척하게!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 위임봉"},
[5504] = {title = "여명의 장막", objective = "서부 역병지대의 보루에 있는 병참장교 하사나에게 은빛 여명회 명예 휘장 10개를 가져가야 합니다.", description = "은빛 여명회를 위해 힘 써준 자네에게 찬사를 보내는 바이네. 우리는 모두 자네를 존경하고 있다네. 자네에게 우리 은빛 여명회에서 매우 값진 물건인 여명의 장막을 구입할 수 있도록 하라는 상부의 허가를 받았네.\n\n현재 착용하고 있는 어깨 방어구에 구입한 장막을 사용하면 각 장막에 담긴 잠재적인 마법 저항력을 강화할 수 있지. 은빛 여명회를 위해 지속적으로 힘써 준 데 대한 감사의 표시로, 명예 휘장을 10개 가지고 오면 이 장막을 구입할 수 있도록 하겠네.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5505] = {title = "스칼로맨스로 가는 열쇠", objective = "음, 완성된 해골 열쇠를 가지고 도착했군요. 이거라면 분명 스칼로맨서 안으로 들어갈 수 있을 거라고 확신합니다. 하지만 열쇠가 제대로 작동하는지 확인하려면 직접 해보는 수밖에 없습니다. 시간을 낭비하지 마시기 바랍니다.\n\n행운을 빕니다, 영웅이여. 어둠 속에서 한 줄기 빛이 되기를!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n해골 열쇠"},
[5507] = {title = "여명의 장막", objective = "서부 역병지대의 서리바람 야영지에 있는 병참장교 라이트스파크에게 은빛 여명회 명예 휘장 10개를 가져가야 합니다.", description = "은빛 여명회를 위해 힘 써주신 당신에게 찬사를 보내는 바입니다. 우리 모두 당신을 존경하고 있습니다. 당신이 우리 은빛 여명회에서 매우 값진 물건인 여명의 장막을 구입할 수 있도록 하라는 상부의 허가를 받았습니다.\n\n현재 착용하고 있는 어깨 방어구에 구입하신 장막을 사용하면 각 장막에 담긴 잠재적인 마법 저항력을 강화할 수 있습니다. 은빛 여명회를 위해 지속적으로 힘써 주신 데 대한 감사의 표시로, 명예 휘장을 10개 가지고 오시면 이 장막을 구입할 수 있도록 해 드리겠습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5508] = {title = "타락자의 스컬지석", objective = "타락자의 스컬지석은 스컬지 우두머리들의 표장이지. 스컬지를 다스리는 직위를 가진 강력한 언데드라면 항상 하나씩 지니고 있다네. 그런 사악한 생물을 처치하는 것은 틀림없이 은빛 여명회의 대의와 모든 선한 대의의 실현을 앞당기게 될 것이야!\n\n은빛 여명회를 대신해 자네에게 이 표장 중 하나를 명예 휘장 하나와 교환해 주도록 하겠네. 그토록 강력한 존재들에게 함부로 맞서는 게 쉽지는 않을 거야. 이 표장을 얻기 위해서는 더 주의를 기울여야 해.", description = nil, progress = "타락자의 스컬지석은 스컬지 우두머리들의 표장이지. 스컬지를 다스리는 직위를 가진 강력한 언데드라면 항상 하나씩 지니고 있다네. 그런 사악한 생물을 처치하는 것은 틀림없이 은빛 여명회의 대의와 모든 선한 대의의 실현을 앞당기게 될 것이야!\n\n은빛 여명회를 대신해 자네에게 이 표장 중 하나를 명예 휘장 하나와 교환해 주도록 하겠네. 그토록 강력한 존재들에게 함부로 맞서는 게 쉽지는 않을 거야. 이 표장을 얻기 위해서는 더 주의를 기울여야 해.", completion = "축하하네. 자네에게 은빛 여명회 명예 휘장을 지급하게 되어 기쁘게 생각하네!\n\n이런 방법으로 명예 휘장을 얻는다는 것은 자네가 선한 대의를 추구하는 진정한 영웅이라는 것을 보여 주는 것이네. 스컬지에 대항하는 모든 노력이 값지지만 놈들의 지도자 중 하나를 처치하는 것은 녀석들에게 큰 타격을 입히는 것이지!\n\n은빛 여명회를 위하여!", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 명예 휘장"},
[5509] = {title = "침입자의 스컬지석", objective = "침입자의 스컬지석은 스컬지의 정예 군단이 지니는 표장이네. 역병지대에 배치된 부대들 중에서도 보다 강한 녀석들에게서 종종 찾을 수 있다네. 사실 그러한 생물을 처치하는 것이 쉽지 않지만, 악의 처단이라는 임무를 마음에 새기며 즐겁게 전투에 임해야 하네.\n\n은빛 여명회에서는 현재 이 표장 10개를 가져오는 이에게 명예 휘장 하나를 지급하고 있지. 이곳으로 내게 그 표장들을 가져오면 자네가 마땅히 받아야 할 보상을 반드시 지급하도록 하겠네.", description = nil, progress = "침입자의 스컬지석은 스컬지의 정예 군단이 지니는 표장이네. 역병지대에 배치된 부대들 중에서도 보다 강한 녀석들에게서 종종 찾을 수 있다네. 사실 그러한 생물을 처치하는 것이 쉽지 않지만, 악의 처단이라는 임무를 마음에 새기며 즐겁게 전투에 임해야 하네.\n\n은빛 여명회에서는 현재 이 표장 10개를 가져오는 이에게 명예 휘장 하나를 지급하고 있지. 이곳으로 내게 그 표장들을 가져오면 자네가 마땅히 받아야 할 보상을 반드시 지급하도록 하겠네.", completion = "축하하네. 자네에게 은빛 여명회 명예 휘장을 지급하게 되어 기쁘네!\n\n받을 자격을 갖춘 이에게 지급하는 명예 휘장은 스컬지와의 전쟁에서 전세를 역전시켰다는 증거지. 더욱 많은 영웅들이 자신들의 땅에서 싸우고 있으니 스컬지라는 궁극적인 악과 전쟁을 벌일 때가 오면 틀림없이 은빛 여명회가 최전선에서 싸우게 될 거야. 오늘날 이 휘장을 받기까지 자네가 보여 준 그 용맹스러움이 그날에도 우리에게 승리를 안겨 주게 되길 바라겠네!", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 명예 휘장"},
[5510] = {title = "앞잡이의 스컬지석", objective = "앞잡이의 스컬지석은 스컬지 사병들의 표장이라네. 이 표장은 역병지대에 배치된 부대들 중 좀 더 약한 무리들에게서 가끔 찾을 수 있지. 하지만 좀 약하다고 해서 녀석들을 얕잡아봐서는 절대 안 되네. 스컬지는 어디에 있든지 결코 과소평가해서는 안 될 상대라네.\n\n현재 은빛 여명회에서는 이 표장 20개를 가져오는 이에게 명예 휘장 하나를 지급하고 있네. 스컬지석을 충분히 모아 오면 기꺼이 명예 휘장과 교환해 주도록 하겠네.", description = nil, progress = "앞잡이의 스컬지석은 스컬지 사병들의 표장이라네. 이 표장은 역병지대에 배치된 부대들 중 좀 더 약한 무리들에게서 가끔 찾을 수 있지. 하지만 좀 약하다고 해서 녀석들을 얕잡아봐서는 절대 안 되네. 스컬지는 어디에 있든지 결코 과소평가해서는 안 될 상대라네.\n\n현재 은빛 여명회에서는 이 표장 20개를 가져오는 이에게 명예 휘장 하나를 지급하고 있네. 스컬지석을 충분히 모아 오면 기꺼이 명예 휘장과 교환해 주도록 하겠네.", completion = "축하하네. 자네에게 은빛 여명회 명예 휘장을 지급하게 된 것을 기쁘게 생각하네!\n\n이 휘장에는 두 가지 용도가 있네. 첫째, 은빛 여명회 내에서의 지위를 높이는 데 쓰일 수 있네. 휘장을 사용하여 명예롭고 존경 받는 동지들에게만 주어지는 옵션과 보상을 얻을 수 있게 되는 것이지. 둘째, 은빛 여명회에서 보유한 귀한 물건들 중 일부를 구입할 때 돈과 함께 우리 병참장교들에게 지불하는 데 사용할 수 있네.\n\n어떤 결정을 내리든 이 위임봉은 자네가 마땅히 받을 만한 성과를 올렸기 때문에 받는 것임을 명심하기 바라네. 수고했네!", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 명예 휘장"},
[5511] = {title = "스칼로맨스로 가는 열쇠", objective = "음, 완성된 해골 열쇠를 가지고 도착했군. 이거라면 분명 스칼로맨서 안으로 들어갈 수 있을 거라고 확신하네. 하지만 열쇠가 제대로 작동하는지 확인하려면 직접 해보는 수밖에 없으니 시간을 낭비하지 말게.\n\n행운을 비네, 영웅이여. 명예와 용기의 힘으로 스칼로맨스에게 응징을!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n해골 열쇠"},
[5513] = {title = "여명의 장막", objective = "동부 역병지대의 희망의 빛 예배당에 있는 병참장교 미란다 브리치락에게 은빛 여명회 명예 휘장 10개를 가져가야 합니다.", description = "은빛 여명회를 위해 힘 써주신 당신에게 찬사를 보내는 바입니다. 우리 모두 당신을 존경하고 있습니다. 자네가 우리 은빛 여명회에서 매우 값진 물건인 여명의 장막을 구입할 수 있도록 하라는 상부의 허가를 받았습니다.\n\n현재 착용하고 있는 어깨 방어구에 구입하신 장막을 사용하면 각 장막에 담긴 잠재적인 마법 저항력을 강화할 수 있습니다. 은빛 여명회를 위해 지속적으로 힘써 주신 데 대한 감사의 표시로, 명예 휘장을 10개 가지고 오시면 이 장막을 구입할 수 있도록 해 드리겠습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5514] = {title = "거푸집과 뼈조각", objective = "가젯잔에 있는 크린클 굿스틸에게 15골드와 함께 마력 깃든 뼈조각을 가져가야 합니다.", description = "자네가 만나 봐야 하는 고블린의 이름은 크린클 굿스틸이라고 하네. 타나리스 사막의 가젯잔에서 자신의 기술을 이용해 돈많은 고객들과 거래를 하고 있는 친구지. 우리가 필요한 거푸집을 만들 수 있는 인물은 크린클 굿스틸 밖에 없을 걸세. 가격 또한 싸지는 않을 거야. 크린클 굿스틸이 자네에게 사례로 뭘 요청하던 우리가 부탁한 일을 발로 뛰어줘야 하네.\n\n난 연금술사지 은행원이 아니네. 만약 내가 금을 쌓아 놓고 산다면 여기 올 일이 없었겠지.\n\n이런, 또 주저리 주저리 늘어논 것 같군. 으음... 가젯잔으로 가게나! 행운을 비네!", progress = "그래, 당신이 누군지, 여기 왜 왔는지 알고 있지. 당신이 도착하기 전에 알빙턴에게 전갈을 받았다고. 자, 서론은 집어치우고 본론으로 들어가자고. 거래하겠나?\n\n나한테 해골 열쇠를 만드는 데 필요한 거푸집이 있는데 말이야. 가격은 선불로 15골드, 흥정은 없다고, 친구. 뼈조각을 거푸집에 넣어 주고 말이야. 그리고 대장기술에 대한 지식 없이 열쇠의 자루를 만드는 방법을 공짜로 가르쳐 주지.\n\n이 정도면 아주 훌륭한 조건이라고!", completion = "디더스가 당신이 물건을 배달해 갈 거라고 그러더군! 거래는 거래니까 당신을 위해 뼈조각을 거푸집에 넣어 주도록 하지.\n\n디더스가 경화제는 첨가했나? 음, 훌륭해... 그런데 보루로 돌아가려면 오래 걸리겠어.", rewards = nil},
[5515] = {title = "소름끼치는 크라스티노브의 가방", objective = "스칼로맨스에서 잔다이스 바로브를 찾아 처치해야 합니다. 그녀의 시체에서 소름끼치는 크라스티노브의 가방을 찾은 후 에바 사크호프에게 가져가야 합니다.", description = "우리 가슴 속의 한을 많이 풀긴 했지만 아직도 당신이 해 주셔야 할 임무가 완전히 끝난 것은 아니에요. 크라스티노브의 주인인 키르토노스가 아직 살아 있습니다.\n\n하지만 키르토노스와 맞서기 전에 먼저 그를 소환할 방법을 강구해야 합니다.\n\n크라스티노브가 키르토노스에게 전하는 무고한 이들의 피는 잔다이스 바로브가 지킨다고 하더군요.\n\n스칼로맨스의 가라앉은 지하 묘지에서 그녀를 찾아 쓰러뜨리고 단서를 찾는 대로 가져와 주세요.", progress = "<선명해졌다 흐릿해졌다 하는 에바의 모습>", completion = "소름끼치는 가방이로군요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5517] = {title = "여명의 오색 장막", objective = "동부 역병지대의 희망의 빛 예배당에 있는 병참장교 미란다 브리치락에게 은빛 여명회 명예 휘장 25개를 가져가야 합니다.", description = "<형제/자매>여, 은빛 여명회를 대신하여 당신이 쌓은 공로는 이루 헤아릴 수가 없을 정도입니다. 그에 보답하는 의미로 우리의 특수 여명의 오색 장막을 드리겠습니다. 이것을 착용하면 모든 계열의 마법 저항력을 지니게 되어 동시에 막아낼 수 있습니다. 여명의 오색 장막은 은빛 여명회 최강의 영웅에게만 수여되는 물건이라네!\n\n제게 명예 휘장 25개를 가지고 오시면 우리의 여명의 장막 중 가장 훌륭한 걸 드리겠습니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n여명의 오색 장막"},
[5518] = {title = "고르독 오우거 위장복", objective = "룬무늬 두루마리 4개, 튼튼한 가죽 8장, 룬문자 실타래 2개, 그리고 오우거 타닌을 노트 팀블잭에게 가져가야 합니다. 노트 팀블잭은 혈투의 전장에 있는 고르독일족 은신처 구석에 족쇄에 묶여 있습니다.", description = "아마도 당신이 이 쓰레기장의 왕이랑 겨루게 될 텐데, 그러려면 크롬크러쉬 대장을 피해가야 한다고. 물론 녀석을 죽여버리고 지나갈 수도 있겠지만 살려두는 게 좋을 테지...\n\n그러면 어떻게 지나가느냐고? 내가 여기 좀 있어봐서 저 얼간이들을 한동안 속일 수 있을만한 오우거 위장복을 만드는 법을 알고 있단 말이야. 단 한 가지 문제라면 안정성인데, 최고 10분 동안 속일 수 있다고. 내게 필요한 물건들을 가지고 오면 하나 만들어주지. 내가 어디로 달아날 수 있는 것도 아니니 말이야...", progress = "그 위장복을 만드는 데 필요한 것들 중 오우거 타닌이 제일 찾기 힘들 거요. 위층에 좀 있는 것 같던데? 잘 모르겠군. 이렇게 족쇄에 묶여 있어서야 돌아다닐 수가 없으니...\n\n어쨌든 내가 필요로 하는 걸 갖고 오면 멍청한 크롬크러쉬 대장이 당신을 보고 자기 부하들 중 하나라고 생각할 만큼 감쪽같은 오우거 위장복을 하나 만들어주지.", completion = "그래. 이거면 되겠군. 여기 이렇게 집어넣고 여기 이렇게 잡아당기고... 헤헤. 아주 잘 만들어지겠는걸! &lt;큰 미소를 지어 보이는 노트.&gt;\n\n자. 다 됐군. 이 위장복은 상당히 불안정한 거라는 걸 잘 기억해두시오. 10분이 지나면 옷이 조각조각 떨어진다는 것을. 옷이 떨어지고 나면 아무도 속지 않겠지! 크롬크러쉬 녀석에게 다가가지 바로 전에 입도록 하라고. 한 가지 더 당부할 게 있는데, 녀석은 당신만 동료라고 착각하지 당신 친구들도 동료라고 착각하지는 않을 거야!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n고르독 오우거 위장복"},
[5519] = {title = "고르독 오우거 위장복", objective = "또 위장복이 필요하다고? 뭐, 내가 어디로 금방 달아날 수 있는 것도 아니고, 가서 전에 구해달라고 했던 것과 같은 재료들을 모아오면 내가 오우거 위장복을 또 하나 만들어주지.", description = nil, progress = "또 위장복이 필요하다고? 뭐, 내가 어디로 금방 달아날 수 있는 것도 아니고, 가서 전에 구해달라고 했던 것과 같은 재료들을 모아오면 내가 오우거 위장복을 또 하나 만들어주지.", completion = "자, 됐군. 이걸 입으면 10분 동안은 괜찮을 거라고. 행운을 빌겠소!\n\n아, 참. 그리고 혹시 이 근처에서 날 풀어줄 수 있는 열쇠를 찾거든 제발, 꼭 좀 알려달라고!!!", rewards = "다음과 같은 것들을 받습니다:\n\n고르독 오우거 위장복"},
[5521] = {title = "여명의 오색 장막", objective = "서부 역병지대의 서리바람 거점에 있는 병참장교 라이트스파크에게 은빛 여명회 명예 휘장 25개를 가져가야 합니다.", description = "<형제/자매>여, 은빛 여명회를 대신하여 당신이 쌓은 공로는 이루 헤아릴 수가 없을 정도입니다. 그에 보답하는 의미로 우리의 특수 여명의 오색 장막을 드리겠습니다. 이것을 착용하면 모든 계열의 마법 저항력을 지니게 되어 동시에 막아낼 수 있습니다. 여명의 오색 장막은 은빛 여명회 최강의 영웅에게만 수여되는 물건이라네!\n\n제게 명예 휘장 25개를 가지고 오시면 우리의 여명의 장막 중 가장 훌륭한 걸 드리겠습니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n여명의 오색 장막"},
[5522] = {title = "리어니드 바돌로매", objective = "동부 역병지대에 있는 리어니드 바돌로매에게 얼어붙은 알을 가져가야 합니다.", description = "얼마전에 우리 주인님이신 벡투스님께 전갈을 받았어요. 그게, 벡투스님께서 직접 보내신 게 아니라... 리어니드 바돌로매라는 이가 보낸 전갈인데, 난 리어니드를 모르지만 리어니드는 벡투스님을 잘 알고 지냈던 모양이에요. 벡투스님은 자신이 허락하는 이가 아니면 알고 지내지 않으시거든요.\n\n리어니드 얘기로는 벡투스님께서 용의 알을 찾고 계신다고 하는군요. 그 용의 알을 당신이 동부 역병지대의 희망의 빛 예배당에 있는 그에게 가져다 주길 바라고 계세요.\n\n정말 섭섭해요! 어째서 당신이죠? 벡투스님께서 날 믿지 않으시는 걸까요? 뭐, 신경 쓰지 마세요. 그냥 알을 가져가서 리어니드에게 난 벡투스님이 명하신 대로 했다고 전해 주세요.", progress = "검은바위 첨탑에서 장난을 친 게 자네란 말인가? 내가 부탁한 건 가져왔나?", completion = "아, 아주 좋아. 자네가 땀 흘려 섬긴 악의 세력이 누구인지 모르겠지만 이제 곧 진실을 알게 될 걸세. 나는 그 주인의 종이 아니니 두려워하지는 말게나. 내 이름은 리어니드 바돌로매. 은빛 여명회 동지들 사이에서는 '존경받는 리어니드'로 통한다네.\n\n팅키를 속여 자네가 내게 용의 알을 가져오도록 한 것일세. 내 속임수가 먹혀 들어간 게 다행이군. 이 알이 정말로 벡투스의 손에 들어갔다면 적의 손에 엄청난 힘을 쥐어 주는 게 되었을 테니까 말이야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5524] = {title = "여명의 오색 장막", objective = "서부 역병지대의 보루에 있는 병참장교 하사나에게 은빛 여명회 명예 휘장 25개를 가져가야 합니다.", description = "<형제/자매>여, 은빛 여명회를 대신하여 자네가 쌓은 공로는 이루 헤아릴 수가 없을 정도로군. 그에 보답하는 의미로 우리의 특수 여명의 오색 장막을 주도록 하겠네. 이것을 착용하면 모든 계열의 마법 저항력을 지니게 되어 동시에 막아낼 수가 있지. 여명의 오색 장막은 은빛 여명회 최강의 영웅에게만 수여되는 물건이라네!\n\n내게 명예 휘장 25개를 가지고 오면 우리의 여명의 장막 중 가장 훌륭한 걸 주도록 하지.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n여명의 오색 장막"},
[5525] = {title = "노트 구출 대작전", objective = "그건 고르독 족쇄 열쇠라고 하는 물건이지. 이 오우거 얼간이들이 그렇게 부르더군. 이곳 오우거들이라면 누구나 지니고 있을 텐데, 어떤 오우거 녀석들이 지니고 있는지는 모르겠단 말이야. 경비병들이라면 갖고 있을 확률이 더 높겠지...\n\n아니, 내가 지금 뭔 소리 하는 거야. 당신 벌써 그 열쇠 갖고 있지?! 그게 바로 그 열쇠야?!", description = nil, progress = "그건 고르독 족쇄 열쇠라고 하는 물건이지. 이 오우거 얼간이들이 그렇게 부르더군. 이곳 오우거들이라면 누구나 지니고 있을 텐데, 어떤 오우거 녀석들이 지니고 있는지는 모르겠단 말이야. 경비병들이라면 갖고 있을 확률이 더 높겠지...\n\n아니, 내가 지금 뭔 소리 하는 거야. 당신 벌써 그 열쇠 갖고 있지?! 그게 바로 그 열쇠야?!", completion = "당신이 제일이로군! 다른 녀석들은 뭐, 떨거지일 뿐이지 암.... 아, 풀어줘서 정말로 고맙소!\n\n내 인생이 한낱 오우거따위의 간식으로 끝나지 않을 줄 알았다니까!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5526] = {title = "악령덩굴 조각", objective = "혈투의 전장에서 악령덩굴 조각을 채취하십시오. 칼날바람 알진을 물리쳐야만 얻을 수 있을 것입니다. 정화의 성물함에 단단히 봉인한 후, 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다.", description = "<name>, 이제 페랄라스에 있는 엘드레탈라스, 혈투의 전장에 대한 그대의 지식이 필요하오. 폐허가 된 그 도시의 동부에는 칼날바람 알진이 타락을 퍼뜨리고 있으니, 서둘러 그곳으로 가서 어떤 고난이 닥쳐오든 싸워 이겨내시오.\n\n알진 근처에 악령덩굴이 있을 거요. 사실 풍요의 열매가 오염되어 악령덩굴이 된 것이지... 녀석이 쓰러지면 악령덩굴의 정수를 모아 성물함에 봉인한 다음 내게 갖고 오도록 하시오.\n\n세나리온의 가호와 함께 그대에게 행운이 함께 하길 빌겠소.", progress = "봉인된 정화의 성물함을 손에 넣으면 이 세계에서 타락의 위협을 하나 제거할 수 있을 뿐만 아니라, 우리가 신중히 관리하면서 연구할 수도 있을 거요. 어쩌면 아제로스를 위협하는 타락한 존재에 맞설 방법을 알아낼 수 있을지도 모르지.\n\n밀리도 그걸 바라고 있었을 거요...", completion = "해냈군. &lt;class&gt;|1이여;여;, 세나리온 의회가 그대에게 큰 빚을 졌소이다. 전쟁의 시대가 끝나려면 아직 한참 멀었지만 승리는 언제나 운명에 도전하는 자들의 것이었소.\n\n자, 끝없는 감사의 표시로 주는 것이니 받으시오. 이렇게 위대한 업적을 이룬 그대를 세나리온 의회에서는 언제나 영웅으로 맞이할 것이라는 걸 항상 기억하시오. 고맙소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n밀리의 방패밀리의 고서\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5527] = {title = "정화의 성물함", objective = "실리더스로 가서 마파람 마을 부근 유적지에 있을 정화의 성물함을 찾아내야 합니다. 찾게 되면 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다.", description = "첫 단계는 아주 심하게 타락한 물질을 담고도 운반자에게 아무 영향도 주지 않을만한 용기를 찾는 것이오. 악령덩굴만큼 지독한 물질을 담을 수 있는 물건이라면 딱 하나 알고 있소. 바로 정화의 성물함이라 불리는 것이지...\n\n실리더스의 폐허로 깊숙이 들어가면 마파람 마을이라고 하는 나이트 엘프 촌락이 남아 있는데, 아주 오래전 그곳에 정화의 성물함이 하나 있었다고 알고 있소. 이번 일에 성공하려면 그대가 그 폐허를 샅샅이 뒤져서 찾아내기를 비는 수밖에...", progress = "정화의 성물함은 그 자체만으로도 유물의 가치를 지니고 있소. 원래 몇 개밖에 만들어지지 않았고, 그나마 대부분 시간이 흐르면서 분실된 것으로 알고 있소.\n\n그중 하나가 마파람 마을에 있었다는 것을 안지는 꽤 됐다는 건 인정하겠소. 사실 실리더스에서 혼란이 점점 커지기에 그대로 비밀로 간직하려고 했었지. 이리저리 기웃거리다 보면 분명 적들의 의심을 살 테니 말이오.\n\n안타깝게도 나 홀로 지켜온 평화의 시간은 이제 끝난 것 같소. 엘드레탈라스의 상황도 있고 하니 말이오.", completion = "과연 사람들 말대로 그대는 재주가 참 좋소이다. 그대 같은 이가 세나리온 의회를 위해 일해준다니 큰 축복이오.\n\n성물함이 다시 우리 손에 들어왔으니 이제 마음이 좀 편해지는군. 그대라면 내가 믿고 사악한 악마와 맞선 후에 위험한 물건까지 가지고 와달라는 부탁을 할 수 있겠소이다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5528] = {title = "고르독 술 맛보기", objective = "힉... 이제 당신 우리 대빵이니까 좀 괜찮은 술 하나 맛볼 수 있다! 힉... 이 술 마시면 기운 나고 기분도 아주 좋아진다! 힉... 이게 알짜배기 술이야, 왕... 한번 마시고 크리그에게 어떤지 말해줘... 힉!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n고르독 그린그로그주크리그의 스타우트 맥주"},
[5529] = {title = "역병 걸린 작은 새끼용", objective = "역병 걸린 작은 새끼용 20마리를 처치한 후 희망의 빛 예배당에 있는 베티나 비글징크에게 돌아가야 합니다.", description = "은빛 여명회에서는 최근에 스컬지가 역병 걸린 용군단을 만들고 있다는 사실을 알아 냈어요! 우린 반드시 그들을 저지해야 해요! 스컬지 녀석들이 용군단을 만들어내면 아제로스를 마음대로 휩쓸고 다니게 될 거예요!\n\n녀석들의 강령술사들이 다로미어 호수 한가운데에 있는 스칼로맨스에서 역병 걸린 용들을 기르고 있어요.\n\n스칼로맨스로 가서 새끼용들이 더 성장하기 전에 되도록 많은 새끼용을 처치해 주세요!", progress = nil, completion = "수고했어요! 스컬지가 또 다른 용 무리를 키울 수 있게 되려면 오랜 시간이 걸릴 거예요.\n\n그러니까, 적어도 그러길 바란다는 거예요!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5531] = {title = "베티나 비글징크", objective = "베티나 비글징크에게 얼어붙은 알을 가져가야 합니다.", description = "자네가 가져온 이 알들은 역병 걸린 용군단을 만들어내려는 스컬지 실험에 사용될 예정이었네. 이 얼어붙은 검은용 알은 녀석들의 연구에 아주 유용하게 쓰였을 테고 틀림없이 실험 일정도 단축할 수 있었을 걸세. 이제는 녀석들의 연구에 종지부를 찍을 때라네.\n\n이 얼어붙은 알을 밖에 있는 베티나 비글징크에게 가져가게. 베티나는 과학과 연금술에 능통한 친구인데, 우리가 스컬지에게 사용할 만한 무기를 하나 만들었다네. 자네의 도움으로 녀석들에게 큰 타격을 입히게 될 거야.", progress = "하이요! 용의 알을 가져왔다고요? 어디 한번 봐요!", completion = "정말로 가져왔군요! 그것도 아주 좋은 용기에 담아서 말이에요. 크기가 아주 딱 맞네요!\n\n나중에 연구를 할 수 있도록 안전한 곳에 보관해 두도록 하겠어요. 하지만 지금 당장은 당신이 알을 담아 온 용기가 필요해요.\n\n아주 특정한 목적에 사용할 장치를 하나 만들었어요. 스칼로맨스의 언데드 학자들을 처치할 목적 말이에요. 이들이 역병 걸린 용군단을 만들어 내기 위해 용을 연구하고 있으니 우린 이들의 연구가 진척되어 나가는 걸 막아야 해요.\n\n난 이 장치를 여명의 계략이라고 부르는데, 그 이유는... 제대로 작동할지 잘 모르기 때문이죠!\n\n우리 대신 한번 시도해 보겠어요?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5533] = {title = "스칼로맨스", objective = "서부 역병지대의 서리바람 거점에 있는 연금술사 알빙턴과 대화해야 합니다.", description = "카엘 다로우의 섬에는 비열한 스컬지 강령술과 악의 중심인 스칼로맨스가 있네. 우리의 적은 아무 것도 모르는 희생자들에게 차마 입에 담기도 힘든 타락한 짓을 저질렀다네. 그럴 것이라 예상은 했지만... 스칼로맨스의 문이 잠겨 열쇠가 없으면 들어갈 수 없을 것이네.\n\n연금술사 알빙턴은 스칼로맨스에 대해서도 잘 알고 열쇠를 얻는 방법도 알고 있네. 자네가 내게 자신의 가치를 증명했으니 이 일을 자네에게 맡기겠네. 알빙턴에게 가서 이 문제에 대해 대화를 나눠보게나.", progress = nil, completion = "만나서 반갑습니다. 나는 최근에 스칼로맨스에 대해 많은 연구를 했고 당신이 열쇠를 얻을 수 있는 방법도 알아낸 것 같습니다. 열쇠가 없으면 정문을 통과할 수가 없을 겁니다.\n\n내부로 들어가면 끔찍한 장면이 펼쳐질 것입니다. 당신 같은 영웅은 어떻게 대처할지 나도 모르겠군요..", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5534] = {title = "킴야엘의 \"잃어버린\" 물건", objective = "엘다라스 폐허에서 나가들이 가지고 있는 어떤 룬을 찾아 아즈샤라에 있는 킴야엘에게 가져가야 합니다.", description = "뭐? 뭐? 뭐라고?\n\n마음에 안 들더라 이거요? 그 폭탄이 얼마나 비싼 건지 알기나 하시오? 자그마치 가격이... 아이고, 그만둡시다. 그래, 푼돈이나 벌고 싶은 생각은 없단 말이지? 좋소, 그럼 이렇게 합시다. 먼저 당신이 쓸만한 일꾼이라는 걸 내게 증명해 보이는 의미로, 조그만 일을 해주면 그에 맞는 보상을 해주지.\n\n당신이 \"쓸만한\" 일꾼이라고 자부한다면 엘다라스 폐허로 가서 블러드 엘프들이 찾아다니던 어떤 룬을 구해 내게 가져오시오. 아마 나가들이 지니고 있는 모양이외다.", progress = "그래, 그 룬은 어디 있소? 당신은 일을 도우러 온 성실한 일꾼이지 않소?\n\n까딱 잘못했다간 우리가 합의한 보수에 대해 다시 생각해 보는 수가 있지. 뭐라고? 아무것도 합의 본 게 없었다고? 저런, 그렇게 생각한다면 느긋하게 찾아오도록 하시오. 대신, 시간을 오래 끌수록 보수가 줄어들 거라는 것만 잊지 말라고.", completion = "하하하! 좋았어!\n\n대체 이게 어디에 쓰이는 물건이기에 학자 림토리가 나까지 고용해 이걸 찾으려 했는지... 꼭 알아내고야 말겠소. 흥! 이제 모든 것이 내 손에 달려 있다! 이 블러드 엘프 놈들! 바로 이 킴야엘님의 손 말이다! 흥! 진짜 쥐새끼 같은 놈이 누군지 톡톡히 가르쳐 주지!\n\n잘해 줬소, &lt;name&gt;. 무지 고맙군. 자, 난 해결해야 할 다른 일이 있으니 이 돈이나 받고 어서 가 보슈.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5535] = {title = "영혼의 동요", objective = "명가의 유령 6명과 명가의 망령 6명을 처치한 후 아즈샤라에 있는 로아투에게 돌아가십시오.", description = "오래전, 나이트 엘프 사회에서 엘프 귀족들은 최강의 비전술을 습득하고 있었소. 하지만, 그들의 연구는 사악함에 물들어 나이트 엘프족은 물론이고 아제로스 전체에 큰 해를 끼쳤소, 당신도 잘 알고 있겠지만...\n\n나는 이제는 명가의 원혼이 돼버린 타락한 엘프 귀족들을 찾는 족족 죽음의 굴레로부터 풀어 주겠노라고 센티널에 약속했소. 당신도 나를 따른다면 내 반드시 그에 대한 보상을 해 줄 거요.\n\n그 영혼들은 여기서 북동쪽에 있는 섀도송 제단에 출몰하고 있소.", progress = nil, completion = "수고했소. 도와 줘서 고맙소이다. 영혼들은 평안을 찾았으니 비전술에 대한 욕망과, 그로 인해 초래되었을 위협 또한 줄어든 것이오.\n\n아제로스를 황폐하게 만들고 있는 양 진영의 충돌... 언젠가는 모두들 당신은 그런 것들을 초월해 있다는 사실을 깨닫게 될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5536] = {title = "증오로 가득 찬 땅", objective = "할다르 사티로스 6명, 할다르 요술사 2명, 할다르 악마추종자 2명을 처치한 후 잿빛 골짜기 경계에 있는 로아투에게 돌아가십시오.", description = "사티로스들이 세나리우스가 한때 활보하던 성지에 들끓고 있소. 아무리 그들이 나이트 엘프의 일그러진 악한 일면이라고 해도, 누구든 그 악마들이 저지른 온갖 악행을 보고나서도 그 생물을 옹호하지는 않을 거요. 나는 나이트 엘프들을 도와 이 땅에서 그 사악한 녀석들을 몰아내기로 대지모신에게 맹세했소.\n\n녀석들을 퇴치하는 것을 도와 준다면 자신의 능력이 당대 최고라는 것을 입증할 수 있을 거요.\n\n여기서 북동쪽으로 가면 할다르 부족이 있는데, 그들의 힘에 맞서 자신을 시험해 본 후 내게 돌아오시오.", progress = nil, completion = "수고했소. 당신은 솜씨만 좋은 것이 아니라 재치도 뛰어나군. 비록 당신이 대지모신을 섬기지는 않더라도, 그 생물들을 물리쳐 대지모신의 뜻을 받드는 자들에 대한 당신의 충성을 증명하였소. 대지모신은 이 세계와 그 너머에 있는 모든 것에 존재하시오. 빛이자 어둠인 그녀의 눈은 하늘을 가로질러 항상 우리를 내려다보고 계시지.\n\n자, 당신이 수고해 준 데 대한 감사의 표시이니, 이 작은 사례를 받아 주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5537] = {title = "뼈조각", objective = "서부 역병지대에 서리바람 거점에 있는 연금술사 알빙턴에게 뼈조각 15개를 가져가야 합니다.", description = "스칼로맨스로 가는 열쇠를 해골 열쇠라고 부릅니다. 해골 열쇠는 말 그대로 해골들로 만듭니다. 적당한 거푸집에 해골을 넣고 가장 강한 금속으로 경화시켜야 하며, 사실 해골이 여러 개 필요합니다. 스칼로맨스로 가는 차원의 문을 자연스럽게 열 수 있는 존재의 힘이 실린 인장이 있어야 열쇠를 완전히 작동시킬 수가 있습니다.\n\n생각나는 것부터 하기로 합시다. 우선 열쇠를 만들려면 뼈조각이 필요합니다. 안돌할 내에 있는 해골들에게 필요한 재료를 얻을 수 있을 겁니다. 뭐, 성벽 밖에 있는 해골들에게도 얻을 수 있을 테고 말입니다. 자, 어서 가서 재료를 구해오십시오.", progress = "참 끔찍하게 들리겠지만 열쇠의 바깥 부분을 만들려면 꽤 많은 수의 적합한 뼈조각이 필요합니다. 괜히 해골 열쇠라고 부르는 게 아니죠.", completion = "이거면 되겠어요! 이제 내 차례군요. 적당한 경화제를 첨가해서 앞으로 치를 격렬한 주조 과정을 견딜 수 있게 할 겁니다.\n\n다음 단계는 열쇠에 맞는 거푸집을 구하는 일입니다. 내가 과거에 해골 열쇠와 비슷한 으스스한 물건을 만들었던 타나리스에 있는 고블린 대장장이를 알고 있답니다. 그 역시 대부분의 고블린처럼 최고의 입찰자를 위해 일하고 있지요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5538] = {title = "거푸집과 뼈조각", objective = "가젯잔에 있는 크린클 굿스틸에게 15골드를 지급하고 마력 깃든 뼈조각을 가져가야 합니다.", description = "당신이 대화를 해야 하는 고블린의 이름은 크린클 굿스틸이라고 합니다. 그 친구는 타나리스 사막의 가젯잔에서 자신의 물건을 비싸게 사 주는 자들을 위해 물건을 만들어 팔지요. 우리가 필요한 거푸집을 만들 수 있는 인물은 크린클 굿스틸 밖에 없을 것이지만 가격 또한 싸지는 않을 겁니다. 크린클 굿스틸이 사례로 뭘 요청하던 우리가 부탁한 일을 발로 뛰어줘야 합니다.\n\n난 연금술사지 은행원이 아니니까 말입니다. 만약 내가 금을 쌓아 놓고 산다면 여기 올 일이 없었겠지요.\n\n이런, 또 주저리 주저리 늘어논 것 같군. 가젯잔으로 가십시오! 행운을 빕니다!", progress = "그래, 당신이 누군지, 여기 왜 왔는지 알고 있지. 당신이 도착하기 전에 알빙턴에게 전갈을 받았다고. 자, 서론은 집어치우고 본론으로 들어가자고. 거래하겠나?\n\n나한테 해골 열쇠를 만드는 데 필요한 거푸집이 있는데 말이야 가격은 선불로 15골드, 흥정은 없다고, 친구. 뼈조각을 거푸집에 넣어 주고 말이야. 그리고 대장기술에 대한 지식 없이 열쇠의 자루를 만드는 방법을 공짜로 가르쳐 주지.\n\n이 정도면 아주 훌륭한 조건이라고!", completion = "알빙턴이 당신이 물건을 배달해 갈 거라고 그러더군! 거래는 거래니까 당신을 위해 뼈조각을 거푸집에 넣어 주도록 하지.\n\n알빙턴이 경화제는 첨가했나? 음, 훌륭해... 그런데 서리바람 거점으로 돌아가려면 오래 걸리겠어.", rewards = nil},
[5541] = {title = "럼블샷의 탄환", objective = "던 모로에 있는 헤그너 럼블샷에게 럼블샷의 탄환을 가져가야 합니다.", description = "헤그너 럼블샷은 앤빌마에서 멀리 떨어진 길에 노점상을 열고 총과 탄환을 팔고 있습니다. 그 부근에서 소총병들과 박격포부대원들이 장기 훈련을 받고 있기 때문에 항상 새 탄환을 구비해 놓고 있어야 하죠.\n\n그런데... 최근에 제가 보낸 탄환 상자가 분실되었답니다. 심부름꾼 말로는 은빛 동굴 근처에서 야영을 하다가 성난 웬디고에게 쫓겨, 글쎄 럼블샷의 탄환을 놓고 왔다지 뭡니까?!\n\n그 탄환 상자를 찾아서 럼블샷에게 좀 전해 주시지 않으시렵니까? 아마 지금쯤 탄환이 다 떨어졌을 겁니다. 발을 동동 구르며 기다리고 있을 게 뻔해요.", progress = "탄환을 사러 온 게 아니라면 좋겠군요. 지금 재고도 다 떨어지고 없어서 말입니다.", completion = "탄환이 왔군! 정말 다행입니다! 늙은 로슬로의 보급품이 드디어 왔군요! 배달이 늦어져서 걱정하던 참이었어요. 하지만 할아버지께서 생전에 늘 하시던 '아주 안 오는 게 아니라면, 조금 늦어지는 건 괜찮다.'라는 말씀을 새기며 기다리고 있었죠.\n\n정말 고맙습니다! 벌써 손님들이 줄을 서서 탄환이 오기만을 기다리고 있었다니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5542] = {title = "지옥개", objective = "새끼 역병사냥개 20마리, 역병사냥개 5마리와 광포한 역병사냥개 5마리를 처치하십시오. 임무를 완수하면 티리온 폴드링에게 돌아가야 합니다.", description = "이곳에서 지낼 생각이라면 밥벌이 삼아 작은 일을 좀 해 주게나. 이곳에는 군기를 잡아 줘야 할 버르장머리 없는 것들이 많이 있다네. 역병사냥개와 그 새끼들부터 시작을 해 주게나.\n\n성공한다면 내 후한 보상까지는 못 해도 따뜻한 식사와 친근한 대화 상대가 되어 주는 것 정도는 반드시 해 줌세.", progress = nil, completion = "수고했네. 와서 푹 쉬게. 함께 먹고 마시며 옛 얘기나 해 보세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5543] = {title = "핏빛 하늘", objective = "역병박쥐 30마리를 처치한 후 티리온 폴드링에게 돌아가야 합니다.", description = "어리석게도 아무 것도 모른 채 역병지대에 들어온 자들은 참 불쌍하지. 이 숲에는 온갖 사악한 것들이 득실거리니까 말이야. 자신들의 징표를 지니고 있지 않은 자들은 누구라도 죽여 버리는 붉은십자군 광신도들부터, 더 많은 언데드를 끌어 모아 자신들의 수를 늘리는 데만 혈안이 되어 있는 살인마 스컬지들까지 있지.\n\n야생 동식물들도 탐욕스러운 식인 괴수들로 변해 버렸어. 이제 하늘에서 공격해 오는 역병박쥐를 처치해 주길 부탁하네.", progress = nil, completion = "자네는 고상함의 빛나는 모범이로군! 내 몸에서 영웅의 피가 고동치는 것을 느낀 것은 참으로 오랜만의 일이야. 자네의 용맹한 행동에 나까지 사기가 오르는군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5544] = {title = "청소부구더기", objective = "부근에서 청소부구더기와 걸신들린 청소부구더기를 찾아 처치하고 청소부구더기 고기덩어리 15개를 모은 후 티리온 폴드링에게 돌아가야 합니다.", description = "식량이 점점 떨어져 가고 있군. 부끄럽게도 자네와 함께 나눌 식량마저 없게 될지도 모르겠네.\n\n이 늙은이를 도와 간단한 일 하나만 해 주지 않겠나? 이 부근에서 역병의 영향을 전혀 받지 않은 짐승은 청소부구더기 하나뿐이라네. 맛은 별로 없지만 그 구더기 고기는 몇 달이고 보관을 하기가 쉬워서 말이지. 올 겨울을 나려면 몇백 킬로그램이 있어야 한다네!", progress = "그 고기 맛도 참을 만해지게 될 걸세, <race> 친구.", completion = "성스러운 빛의 가호가 있기를! 정말 고맙네, 젊은이.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5545] = {title = "골칫덩어리", objective = "동부 벌목지에 있는 랠렌에게 장작 더미 8개를 가져가야 합니다.", description = "안녕하세요, <class>님. 제게 큰 문제가 생겼는데 좀 도와주시겠어요? 목재 주문 이행 시한이 다가오고 있는데 시간이 부족하답니다. 북쪽에서 늑대와 곰들이 나타나 이미 다 잘라 놓은 나무 더미에서 우리 일꾼들을 쫓아내 버렸어요.\n\n제가 그 짐승들을 몰아내 달라고 레이너 부관님께 벌써 부탁은 해 두었지만 그 나무를 가져와 줄 이가 필요해요. 장작 더미 8개만 가져다 주실 수 있으시다면 시한을 맞출 수 있을 거예요.", progress = "이행 시한이 점점 다가오고 있어요, <class>님. 제발 서둘러 그 장작 더미를 가져와 주세요.", completion = "아주 잘 됐네요! 감사합니다. 이제 시한 내에 주문 물량을 맞출 수 있을 거예요. 감사의 마음과 함께 수고해 주신 데 대한 보상으로 돈을 좀 드리도록 할게요.\n\n감사합니다. 안녕히 가세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5561] = {title = "코도 길들이기", objective = "길들인 코도 5마리와 코도 유인기를 자신의 야영지에 있는 스미드 스크래블스크류에게 가져가야 합니다.", description = "비블리는 잊혀진 땅에서 돈을 벌 줄 아는 고블린이 자기뿐이라고 생각하지. 글쎄 그럴까? 이 근방을 운행하는 유일한 짐마차도 나한테 의지한다고. 늙고 죽어 가는 코도를 내 유인기를 이용해 다시 회복시키고 길들이는 방법을 배운 이후로 계속해서 짐마차 주인인 코르크, 리거와 난 협력 관계를 맺고 있지.\n\n이 유인기를 가져가서 고대의 코도, 늙은 코도나 임종의 코도에게 사용하면 자넬 따라오도록 길들일 수 있을 거야. 코도를 길들이면 나한테 데려오라고.", progress = "짐마차가 여기에 잠깐 머물 거야. 내가 요청한 새로 길들인 코도 5마리는 준비됐나?", completion = "&lt;숫자를 세기 시작하는 스미드 스크래블스크류&gt;\n\n넷, 다섯... 좋아. 내가 요청한 대로 길들인 코도 5마리를 가져왔군. 부자, 엄청난 부자가 될 수 있겠어! 내가 성공했다는 얘기를 들으면 비블리의 녹색 낯짝이 어떻게 변할지 궁금해지는군!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n코도 도둑 장화논쟁의 어깨갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5581] = {title = "악마의 차원문", objective = "만노로크 소굴에서 악마의 차원문 6개를 없애고 타이가 와이즈메인에게 돌아가야 합니다.", description = "조심하십시오. 이룩소스의 손은 정말 소름끼치는군요.\n\n지금 내가 부탁하려는 만노로크 소굴에 있는 악마의 차원문을 없애려면 반드시 이게 필요합니다. 이제 당신에게 그 임무를 맡기고자 합니다. 악마의 위협이 커지고 있으니 우리가 이 문을 닫아서 세상을 향한 악마의 접근을 막아야 합니다. 그리고 차원문의 수호병을 조심하십시오.", progress = "만노로크 소굴에 있는 악마의 차원문을 없앴습니까?", completion = "잘했습니다. 그대의 노력은 악마의 위협에 맞서 싸우는 데 큰 도움이 되었으며 아제로스의 모든 것이 좀 더 안전해질 것입니다!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n강철죔쇠 손목보호구모피매듭 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5582] = {title = "생기 있는 용비늘", objective = "동부 역병지대의 희망의 빛 예배당에 있는 베티나 비글징크에게 생기 있는 용비늘을 가져가야 합니다.", description = "이것은 역병 걸린 새끼 용에게서 떨어진 비늘입니다. 이 새끼 야수에게서 얻을 수 있는 다른 비늘들은 구멍이 패이고 진물이 흘러나오는데 반해 이 희귀한 비늘은 건강한 상태이고 손상되지 않았습니다.\n\n베티나 비글징크가 이 비늘의 견본을 조사하고 싶어할 것입니다.", progress = "음, 내게 뭔가 보여 줄 게 있나요?", completion = "대단해요! 이 비늘은 내가 그동안 계속 해 온 스컬지의 음모에 대한 조사에 아주 큰 도움이 될 거예요. 고마워요. 앞으로도 이런 비늘을 더 찾게 되거든 내게 가져와 주세요!", rewards = nil},
[5601] = {title = "여동생 파멜라", objective = "다로우샤이어에서 파멜라 레드패스를 찾아야 합니다.", description = "저는 대전쟁 중 로데론에서 도망쳐 나왔어요. 다행히 스컬지가 제 고향을 휩쓸고 지나가며 역병의 악몽 지대로 만들어 버리기 전에 탈출할 수 있었죠! 저는 운이 좋았지만, 제 가족은 저처럼 운이 따라 주질 않았답니다. 다로우샤이어 전투 중 모두 살해 당한 건 아닌지 걱정이에요.\n\n다로우샤이어는 동부 왕국에 있는 마을인데, 지금은 동부 역병지대의 남쪽 언덕에 위치해 있어요. 그곳으로 가서 제 가족을 찾아봐주시지 않겠어요? 너무 보고 싶어요. 특히 여동생 파멜라가 보고 싶어요.\n\n제발 파멜라를 찾아 주세요!", progress = nil, completion = "우리 제시카 언니는 어디 있어요? 언니는 아주 오래전, 제가 아주 어렸을 때 떠났는데, 떠날 때 많이 울었어요. 왜 울었는지 전 몰라요! 음... 넘어져서 발가락이 아파서 그랬을지도 몰라요.\n\n언니가 여기 있을 때는 같이 놀고, 춤도 추고, 집 근처에서 예쁜 꽃도 꺾고 그랬어요. 그리고 가끔은 아빠가 집에 오시는 게 보이면 언니랑 같이 숨어 있다가 갑자기 튀어나와서 아빠를 놀라게 해 드리기도 했어요.\n\n언니, 돌아와! 언니가 돌아오면 아빠도 돌아오실 거고 그럼 다시 다 같이 놀 수 있을 거란 말이야...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5621] = {title = "달빛 로브", objective = "파수꾼 샤야를 찾아 2레벨 하급 치유로 부상을 치유한 후, 신의 권능:인내를 부여하고 돌라나르에 있는 라우르나 모닝라이트에게 돌아가십시오.", description = "그대의 도움이 필요합니다, <name>. 저는 여기서 제자들을 가르쳐야 하니 그대가 돌라나르 남쪽의 부상당한 우리 파수꾼을 도와주십시오. 마을을 순찰하다가 불의의 사고를 당했는데 우리가 도움을 줄 수 있을 거예요. 그 파수꾼의 이름은 샤야라고 합니다.\n\n그녀를 찾거든 상처를 치유해 주고 그대의 마법으로 그녀의 체력을 회복시켜 주세요. 그러면 더 이상 상처를 입지 않을 테니까요. 엘룬님을 위한 그대의 의무를 마치거든 제게 다시 오십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n엘룬의 달빛 로브"},
[5622] = {title = "엘룬의 추종자", objective = "텔드랏실에 있는 라우르나 모닝라이트와 대화하십시오.", description = "<name>, 여기 그늘 협곡에서의 일을 마무리하면 돌라나르로 돌아가세요. 거기에 가면 라우르나 모닝라이트를 만나세요. 그대에게 엘룬께서 기뻐하시는 길이란 어떤 것인지 가르쳐 줄 거예요. 그녀를 도우면 나이트 엘프의 <사제/여사제>로서 그대를 빛내 줄 로브를 얻을 수 있을 거예요.\n\n조심해서 가도록 해요. 그대 가시는 길에 엘룬의 가호가 있기를 빌겠습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5623] = {title = "빛의 추종자", objective = "엘윈 숲에 있는 여사제 조세타와 대화해야 합니다.", description = "다시 만났군요, 젊은 <사제분/여사제분>. 우리 사제의 기술에 대해 좀 더 자세하게 배울 시간이 됐습니다. 여기 노스샤이어에서 하던 일을 마무리하고 골드샤이어에서 여사제 조세타님을 찾아가 보시기 바랍니다. 그분께서는 당신에게 가르쳐 줄 것이 많이 있고 당신이 빛의 길에서 강하게 성장하고 있다는 얘기도 들으셨다고 하더군요. 그분께선 당신을 훈련한다는 생각에 잔뜩 기대하고 계시니 어서 가보시기 바랍니다.", progress = nil, completion = "도착한 걸 보니 기쁘군요. 당신의 미래와 빛의 힘 내에서 당신이 가야할 길에 대해 많은 논의를 해야 합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5624] = {title = "성스러운 빛의 로브", objective = "경비병 로버트를 찾아 2레벨의 하급 치유를 사용해 부상을 치유한 후, 그에게 신의 권능: 인내를 부여하고 골드샤이어에 있는 여사제 조세타에게 돌아가야 합니다.", description = "보통 전 새로운 빛의 추종자들을 첫 로브를 입을 자격이 있는지 확인해 보기 위해 작은 과제를 낸답니다. 로브는 대성당에서 그 <사제/여사제>를 인정하고 후원한다는 것을 외부에 나타내는 표시지요.\n\n하지만 이번 시험은 기존 상황과 좀 다릅니다. 골드샤이어의 시민들 중 하나가 여기서 동쪽에 있는 호수 근처에서 부상당한 경비병을 봤다고 해요. 이름은 로버트라고 하는데, 그를 찾아서 치유를 한 다음, 몸을 강화시켜 주고 이곳으로 돌아오도록 하세요. 그렇게 하면 당신이 시험을 마친 것으로 간주하도록 하겠습니다.", progress = nil, completion = "잘하셨어요. 마을을 지킬 건장한 경비병이 한 명 더 있으니 우리는 그만큼 더 안전해진 거랍니다. 벌써 자신의 능력을 현명하게 사용할 줄 안다니 기쁘군요. 언제든지 훈련을 더 받을 준비가 되었다고 생각되면 절 찾아오세요.\n\n일단 이 로브를 드릴게요. 다른 이들이 이 로브를 보고 당신이 빛의 일원이라는 것을 알게 될 겁니다. 후에 더 많은 시험이 있을 테고 그 시험에 이 로브가 꼭 필요한 건 아니니 입고 싶지 않다고 해도 상관없답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n빛의 수사 로브"},
[5625] = {title = "성스러운 빛의 로브", objective = "산악경비대 돌프를 찾아 2레벨의 하급 치유를 사용해 부상을 치유한 후, 신의 권능:인내를 부여하고 카라노스에 있는 막산 앤볼에게 돌아가십시오.", description = "보통 당신 정도의 실력이 되면, 일정한 시험을 거쳐, 그 지위와 실력을 나타내는 로브를 입게 되지요. 하지만 솔직히 말해서 지금은 좀 더 시급한 용무들이 있어서 말입니다. 카라노스 시민들이 이곳으로 와서는 돌프라는 산악경비대원이 부상을 당한채 남쪽으로 마을 바로 바깥에 있다고 하더군요.\n\n돌프를 치유하고 그에게 인내를 부여해주면 당신의 실력을 증명해낸 것으로 간주하겠습니다. 어떻습니까?", progress = "<name>, 돌프는 아직 못 찾으셨습니까?\n\n이미 알고 계시겠지만 우리 <class>의 치유 능력은 아주 유용한 것이지요. 부상을 입은 자들을 치유해 줄 수 있는 것은 물론이고 장차 영웅이 되고자 하는 모든 이들의 생존에 있어서도 우리는 없어서는 안 될 존재입니다. 인내로써 신체의 방어력을 높이고 생명력을 유지시킬 수 있는 치유 실력을 갈고 닦는다면, 우리가 극복하지 못할 것이란 없을 겁니다!", completion = "수고하셨습니다, &lt;name&gt;. 성스러운 빛이 당신과 함께하시는 게 틀림없군요.\n\n자, 이 로브를 받으십시오. &lt;class&gt;로서 당신의 지위를 나타내는 의복이니, 앞으로 모든 이들이 당신이 &lt;class&gt;라는 걸 알아볼 겁니다. 원한다면 바로 입도록 하십시오.\n\n후에 더 많은 시험을 치르게 될 테니, 될 수 있는 한 준비를 철저히 해두세요. &lt;class&gt;로서의 능력을 배우고, 많은 경험을 하세요. 혼자서 싸움을 몇 번 해보는 것도 좋습니다만, 시간이 지나면 다른 여행자들과 힘을 합쳐 싸워 보세요.\n\n걱정은 마십시오. 당신도 충분히 그들만큼 강하니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n빛의 수사 로브"},
[5626] = {title = "빛의 추종자", objective = "던 모로에 있는 막산 앤볼과 대화하십시오.", description = "이봐요! 잠시만요! 시간 좀 내주십시오.\n\n당신 지금껏 빛을 찾아다니셨죠? 그렇다면 카라노스의 막산 앤볼을 만나보는 게 좋겠습니다. 당신에게 <class>의 길에 대해 자세히 알려줄 겁니다. 그리고 <사제/여사제>로서 당신을 빛내줄 로브를 줄 수도 있다고요. 단, 그럴만한 자격이 있을 때의 얘기입니다.\n\n이제 출발하십시오! 여기 일을 최대한 빨리 마치고 굴을 통과해 카라노스로 가세요. 막산 앤볼이 기다리고 있을 겁니다.", progress = nil, completion = "아, 브란스토크가 보냈군요. 그렇죠? 좋습니다, 좋아요! 브란스토크의 말이 옳습니다. 당신은 이제 빛의 세계로 더 큰 걸음을 내딛기 시작한 거예요. 제가 더욱 강하게 단련시켜 드리겠습니다. 지금 당신에게 가장 필요한 것은 바로 육체와 정신의 힘이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5627] = {title = "엘룬이 뿌린 별조각", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n별조각\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n별조각"},
[5628] = {title = "귀향길", objective = "다르나서스에 있는 여사제 알라시아와 대화하십시오.", description = "반갑습니다, <name>. 그대가 가던 길 잠시 멈추고 저와 대화할 시간을 내다니 참 고맙군요. 어린 나이에 고향을 떠나 이 먼 곳까지 오셨네요. 그 패기 칭찬해 드려야 마땅하겠죠. 나도 젊은 시절, 그대처럼 훌쩍 여행을 떠날 용기가 있었더라면 좋았을 텐데.\n\n얼마 전, 어느 여사제가 그대를 찾아 여기에 왔었어요. 급한 일이라며 다르나서스에 있는 달의 신전으로 가서 여사제 알라시아와 이야기를 해보라고 그대에게 전하랬어요. 그대의 훈련에 관한 일이라고 했으니, 제가 오래 붙잡아 둬서는 안 되겠죠.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n별조각\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n별조각\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5629] = {title = "귀향길", objective = "다르나서스에 있는 여사제 알라시아와 대화하십시오.", description = "<name>, 또 만났군요. 우리 일을 돕느라 바쁜 건 알지만 그대 자신을 위해서도 시간을 투자해야만 해요. 여사제 알라시아가 그대를 찾으러 여기로 누군가를 보냈어요. 장로들께서 그대에게 관심이 많은 것 같아요. 아마 큰 일을 할 분이라는 느낌이 들었나 봐요. 다르나서스에 있는 달의 신전으로 가서 알라시아를 찾아 보세요. 그대를 기다리고 있을 테니. 행운을 빕니다. 엘룬께서 함께하시길.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n별조각\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n별조각\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5630] = {title = "귀향길", objective = "다르나서스에 있는 여사제 알라시아와 대화하십시오.", description = "반가워요, 반가워. 이 넓은 곳을 바쁘게도 뛰어다니는 걸 보니 내 마음이 즐겁군. 비꼬려는 건 아니고 자네 <race>들은 대부분 이렇게 추운 날씨에 약하던데, 몸이 튼튼한 것 같아 다행이란 말입니다.\n\n얼마 전, 나이트 엘프 여사제 하나가 당신을 찾아 여기 왔었어요. 다르나서스에 있는 달의 신전으로 가서 여사제 알라시아를 찾으라고 하던데. 중요한 일이라고 빨리 오라고 했습니다.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n별조각\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n별조각\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5631] = {title = "귀향길", objective = "다르나서스에 있는 여사제 알라시아와 대화하십시오.", description = "젊은 <race>|1이여;여;, 어느 여사제 한 명이 우리 대성당에 당신을 찾으러 왔었답니다. 다르나서스에 있는 달의 신전으로 최대한 빨리 오라고 전해 달라더군요. 신전에 도착하면 여사제 알라시아를 찾으십시오. 자세한 얘기를 해줄 겁니다.\n\n<name>, 성스러운 빛이 언제나 함께하기를.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n별조각\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n별조각\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5632] = {title = "귀향길", objective = "다르나서스에 있는 여사제 알라시아와 대화하십시오.", description = "아, <name>. 안녕하세요. <race> 전령이 얼마 전 그대를 찾으러 왔었습니다. 다르나서스에서 중요한 볼일이 있으니 최대한 빨리 달의 신전으로 돌아오라더군요. 도착하면 여사제 알라시아와 이야기를 나눠보십시오. 그대의 훈련에 관한 일인 것 같습니다.\n\n시간이 날 때 반드시... 다르나서스로 돌아가 보시는 게 좋을 겁니다.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n별조각\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n별조각\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5633] = {title = "귀향길", objective = "다르나서스에 있는 여사제 알라시아와 대화하십시오.", description = "안녕하십니까? 위대한 신비의 전당에서 이렇게 만나게 되니 참으로 반갑군요. <race>에게 축복이 있기를.\n\n당신이 우리 땅을 여행하는 동안 달의 신전에서 온 어느 여사제가 당신을 찾으러 왔습니다. 최대한 빨리 달의 신전으로 돌아오라고 전해 달라더군요. 자세한 내용은 저도 모르겠지만 매우 중요한 일처럼 보였습니다. 달의 신전에 도착하면 여사제 알라시아를 찾아 가십시오.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n별조각\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n별조각\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5634] = {title = "구원의 기도", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n구원의 기도\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n구원의 기도"},
[5635] = {title = "구원의 기도", objective = "스톰윈드에 있는 대여사제 로레나와 대화해야 합니다.", description = "<형제/자매>가 우리 고위 사제분들의 관심을 끈 모양입니다. 그분들께서는 <형제/자매>가 스톰윈드의 빛의 대성당으로 최대한 빨리 와줬으면 하고 계십니다. 그분들께서는 <형제/자매>가 다음 훈련을 시작할 준비가 됐다고 생각하시는 게 분명합니다. 빛의 대성당에 도착하면 대여사제 로레나님을 찾아가세요. 로레나님께서 <형제/자매>를 더더욱 발전시켜 줄 것입니다. 행운을 빕니다. 성스러운 빛이 <형제/자매>와 함께하기를.", progress = nil, completion = "잘 오셨습니다. 의논할 일이 많지만 더 중요한 건 빛의 길에 대해 훈련하는 것입니다.\n\n빛의 추종자라면 반드시 배워야 하는 내용이지요. 자매가 준비가 되면 시작하도록 하겠습니다.", rewards = "다음과 같은 것들을 배웁니다:\n\n구원의 기도\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n구원의 기도\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5636] = {title = "구원의 기도", objective = "스톰윈드에 있는 대여사제 로레나와 대화해야 합니다.", description = "엘룬의 축복이 있기를. 그대의 빛이 그대를 잘 보호해 주길 바랍니다.\n\n그대와 같은 사제 한 명이 얼마 전에 여기 와서 그대를 찾았답니다. 그는 그대가 빛의 대성당으로 최대한 빨리 돌아와서 대여사제 로레나와 얘기해야 한다고 하더군요. 그렇게 관심을 갖는 걸 보니 지금까지 아주 잘 해 오신 것 같군요. 내가 여기서 너무 시간을 지체하게 할 순 없습니다. 자, 어서 떠나세요. 그대를 기다리는 사람들에게로...다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n구원의 기도\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n구원의 기도\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5637] = {title = "구원의 기도", objective = "스톰윈드에 있는 대여사제 로레나와 대화해야 합니다.", description = "스톰윈드로 갈 시간이 됐군요. 빛의 대성당에 계시는 대여사제 로레나님께서 <형제/자매>와 대화를 하고 싶어하십니다. 개인적으로 <형제/자매>를 보자고 하셨으니 아주 좋은 일이거나 아주 나쁜 일인데... 내 생각에는 <형제/자매>가 잘 해왔으니 대여사제님께서 좋은 일로 보자고 하시는 게 아닐까 생각됩니다.\n\n하지만 여기서 시간을 너무 지체하지 말도록 하십시오. 나도 <형제/자매>만큼 빨리 대성당으로 갈 테니까 말입니다.", progress = nil, completion = "잘 오셨습니다. 의논할 일이 많지만 더 중요한 건 빛의 길에 대해 훈련하는 것입니다.\n\n빛의 추종자라면 반드시 배워야 하는 내용이지요. 자매가 준비가 되면 시작하도록 하겠습니다.", rewards = "다음과 같은 것들을 배웁니다:\n\n구원의 기도\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n구원의 기도\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5638] = {title = "구원의 기도", objective = "스톰윈드에 있는 대여사제 로레나와 대화해야 합니다.", description = "좀 전에 그대와 같은 사제 한 명이 그대를 찾으러 여기 왔었습니다. 그는 그대를 만나게 되면 빛의 대성당으로 인도해 달라고 말했답니다. 굉장히 중요한 일이라고 말하기는 했지만 내가 그대라면 별로 걱정하지는 않겠어요. 그 사제의 태도로 봐서 좋은 소식인 거 같으니까요. 여기서 너무 오래 지체하지 않는 것이 좋겠습니다.\n\n어서 가세요. 엘룬이 함께하시길.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n구원의 기도\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n구원의 기도\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5639] = {title = "구원의 기도", objective = "스톰윈드에 있는 대여사제 로레나와 대화해야 합니다.", description = "스톰윈드에서 <형제/자매>를 찾고 있습니다. 스톰윈드의 대여사제 로레나님께서 말씀하시길 <형제/자매>가 다음 단계의 훈련을 받을 자격이 있는지 증명할 시간이 됐다고 하셨습니다. 지체하지 말고 스톰윈드로 가십시오. 도시 가운데에 있는 빛의 대성당에 가면 대여사제님을 만날 수 있을 겁니다. 대여사제님께 내 안부를 전해주고 <형제/자매>의 실력을 증명해 보이시기 바랍니다. 성스러운 빛이 <형제/자매>와 함께하기를 빌겠습니다.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n구원의 기도\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n구원의 기도"},
[5640] = {title = "구원의 기도", objective = "스톰윈드에 있는 대여사제 로레나와 대화해야 합니다.", description = "엘룬의 축복과 성스러운 빛이 그대와 함께하기를.\n\n이 시기쯤 되면 우리와 같은 계급에서 많은 이들이 엘룬님에 대한 믿음을 드러내는 방법을 배우게 되지요. 내가 알기에는 그대가 속한 계급에서도 마찬가지 방법으로 믿음을 표현할 수 있을 것입니다.\n\n그대가 다르나서스에서 할 일을 모두 마치면 그대에게 더 높은 수준의 훈련을 시켜줄 대여사제님을 찾아 보도록 하지요. 아, 스톰윈드에 계시는 우리의 동맹 대여사제 로레나님께 가 보도록 하세요.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n구원의 기도\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n구원의 기도\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5641] = {title = "두려움 없는 용기", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n공포의 수호물\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n공포의 수호물"},
[5642] = {title = "어둠의 수호", objective = "오그리마에 있는 우르쿄와 대화하십시오.", description = "오그리마에 뭔가 중요한 일이 벌어진 것 같소.\n\n전령이 여기까지 와서 트롤 사제를 찾는 일은 별로 없는데 말이오. 그 전령은 유달리 서두르는 것 같았소이다. 썬더 블러프에서 너무 오래 지체하지 마시오. 내가 당신이라면 가능한 한 빨리 정기의 골짜기로 돌아가서 무슨 일인지 알아보겠소이다.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n어둠의 수호\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n어둠의 수호\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5643] = {title = "어둠의 수호", objective = "오그리마에 있는 우르쿄와 대화하십시오.", description = "여러 종족의 수많은 사제처럼 자네도 <race>의 신실한 사제가 되려면 의식을 치러야 하네. 보통 이런 의식은 생존에 반드시 필요한 특별한 능력을 가르쳐 주지. 자네도 이제 의식을 치를 때가 됐어. 오그리마에 있는 정기의 골짜기로 가서 우르쿄와 대화를 해보게. 그가 가르쳐 주는 내용은 훗날 굉장히 유용하게 쓰일 거야.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n어둠의 수호\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n어둠의 수호\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5644] = {title = "파멸의 역병", objective = "언더시티에 있는 애살리스테와 대화해야 합니다.", description = "아, 당신에게는 멋진 날이로군. 훈련을 통해서 지켜본 결과 당신을 애살리스테에게 보낼 때가 됐소. 당신의 자격을 증명해 보인다면 애살리스테가 자신만이 가르칠 수 있는 것들을 당신에게 가르쳐 줄 거요.\n\n특별한 뜻으로 말하는 건 아니고 나에게도 진정한 힘, 신의 힘을 배우던 젊은 시절이 있었지. 그래, 그런 시절이 있었어.\n\n언더시티의 애살리스테에게로 돌아가시오. 그녀가 군사 지구에서 당신을 기다리고 있을 것이오.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n파멸의 역병\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n파멸의 역병\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5645] = {title = "두려움 없는 용기", objective = "아이언포지에 있는 대사제 로한과 대화하십시오.", description = "<name>, 대사제 로한께서 아이언포지에서 당신을 기다리고 계십니다. 서두르십시오. 어서 다음 시험을 치러야 합니다. 당신 종족만의 특별한 의식을 치르러 가는 길에 길동무가 되어 주고 싶지만 저는 여기 있어야 합니다. 하지만 가는 동안 성스러운 빛이 당신과 함께하기를 빌어 드리죠. 그 도시에 도착하면 마법 지구로 가서 로한을 만나 보십시오. 당신을 기다리고 있을 겁니다.", progress = nil, completion = "&lt;name&gt;, 잘 오셨습니다. 우리는 자부심과 힘, 용기가 넘치는 종족입니다. 이제 자기 몸 하나 지킬 때는 지났습니다. 나에게 배우는 것으로 당신은 이제 다른 이에게도 자부심과 자신감을 심어주어야 합니다. 준비됐습니까?", rewards = "다음과 같은 것들을 배웁니다:\n\n공포의 수호물\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n공포의 수호물\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5646] = {title = "파멸의 역병", objective = "언더시티에 있는 애살리스테와 대화해야 합니다.", description = "애살리스테는 그녀의 종족원들을 나에게 보내서 더 높은 수준의 훈련을 받을 수 있도록 많은 배려를 해주었네. 이제는 내가 애살리스테의 종족원들에게 그렇게 해줄 때이지.\n\n언더시티로 돌아가게. 그곳의 군사 지구로 가면 애살리스테가 자네의 종족과 종족의 방식에 대해 더 많은 것을 가르쳐 줄 것일세. 지체하지 말고 어서 가게나.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n파멸의 역병\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n파멸의 역병\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5647] = {title = "두려움 없는 용기", objective = "아이언포지에 있는 대사제 로한과 대화하십시오.", description = "<name>, 그대의 종족은 매우 강해요. 그대를 동지라고 부를 수 있다는 게 자랑스럽습니다. 하루하루 지날수록 그대는 자신의 진정한 근원을 찾게 될 뿐만 아니라, 이 험난한 세상에서 올바른 길을 가고 있다는 자신감도 얻어가고 계시겠죠. 분명 그대는 참된 승리라는 게 뭔지 스스로 느끼고 있을 줄로 압니다.\n\n최근 아이언포지에서 그대 앞으로 전갈이 왔습니다. 마법 지구에 있는 대사제 로한에게 돌아가서 대화를 해보십시오. 그분을 오래 기다리게 해서는 안 됩니다. 엘룬께서 그대를 인도하시길.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n공포의 수호물\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n공포의 수호물\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5648] = {title = "신비한 주술의 로브", objective = "그런트 코르자를 찾아 2레벨의 하급 치유를 사용해 부상을 치유한 후, 신의 권능:인내를 부여하고 칼바위 언덕에 있는 타이진에게 돌아가십시오.", description = "<name>, 자네는 이제 첫 번째 시험을 치를 준비가 됐다네. 칼바위 언덕의 남쪽, 마을 바로 바깥에 우리 그런트 하나가 부상을 입은 채 있네. 프라우드무어의 부하 몇과 싸우다가 꽤 심하게 다친 모양이야. 우리 중 하나가 가면 큰 도움을 줄 수 있을 거야. 그 그런트의 이름은 코르자라고 하네. 그녀를 찾아 부상을 치유해 주고 우리 선조의 축복을 내려 주게.\n\n그렇게 하면 자네가 사제의 길을 계속 걸어 나갈 준비가 됐다는 것을 충분히 입증했다고 생각하지.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n주술 부적 로브"},
[5649] = {title = "숭고한 정신의 추종자", objective = "듀로타에 있는 타이진과 대화하십시오.", description = "우리가 호드에 합류한 건 잘한 일이었어. 호드는 우리 트롤에게 충성과 명예가 무엇인지 가르쳐 주었으니까. 하지만 오랜 습관과 전통은 쉽게 버릴 수 있는 게 아니더군. 오크에서 트롤의 모든 전통을 좋아하는 건 아니지만, 그렇다고 해서 우리가 오크 몰래 은밀히 그 전통을 이어가지 말란 법은 없지 않나?\n\n내 말을 이해하리라 믿네. 이제 자네를 칼바위 언덕에 있는 타이진에게 보내야 할 때군. 타이진이라면 자네에게 우리 트롤의 역사와 트롤의 길에 대해 많은 것을 가르쳐 줄 걸세. 준비가 되면 타이진에게 가보게.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5650] = {title = "어둠의 로브", objective = "죽음의경비병 켈을 찾아 2레벨의 하급 치유를 사용해 부상을 치유한 후, 신의 권능: 인내를 부여하고 브릴에 있는 어둠의사제 베릴에게 돌아가야 합니다.", description = "우리의 힘은 어둠과 암흑에서 나오는 것일세. 하지만 자네의 역할은 그것만이 아니야. 자네가 치유 마법을 익혀두면 도움이 된다고 인정한 것은 현명한 일일세. 하지만 암흑을 알려면 먼저 빛을 알아야 하는 법. 그래서 내가 시험을 하나 준비했다네.\n\n묘지의 북쪽으로 가면 부상당한 죽음의경비병 한 명이 있을 텐데 이름이 켈이라고 하네. 그 친구는 한동안 놀로부터 우리를 보호해주었지. 자네가 가서 그를 치유해주고 다시 임무를 수행할 수 있도록 체력도 강화시켜주게나. 자네가 배운 마법을 이용하고 임무를 마치면 내게 다시 돌아오게.", progress = nil, completion = "시험을 아주 쉽게 치렀군. 좋아.\n\n머지 않아 자네는 더 많은 책임을 짊어지고 더 큰 암흑의 길을 걸어가게 될 것일세. 다른 종족의 &lt;class&gt;는 가질 수 없는 힘이지.\n\n자네의 지위를 상징하는 이 로브를 입게나. 이제 로브는 자네 것이니 입고 싶지 않다면 입지 않아도 괜찮으니 마음대로 하게. 그래도 나와 다른 &lt;class&gt;들은 자네가 이곳에서 성취해 낸 일을 언제까지나 인정해 줄 것이네.", rewards = "다음과 같은 것들을 받습니다:\n\n제물의 수행사제 로브"},
[5651] = {title = "어둠의 추종자", objective = "티리스팔 숲에 있는 어둠의사제 베릴과 대화해야 합니다.", description = "포세이큰은 경험을 통해서 많은 것들을 배웠네. 다른 종족들은 이제 겨우 연구하기 시작하는 것들 말이야. 비록 우리의 길이 어둠이라고 하지만 많은 것들이 빛과 어둠이 함께 있어야만 한다는 것을 알게 될 걸세. 자네는 빛과 어둠을 사용하는 법을 모두 배우게 될 거야. 물론 신중하게 사용해야지. 내 말을 잘 듣고 잊지 말게나. 우리는 오염된 곳에서 창조되어서 썩은 고기처럼 부패한 곳에 버려졌네. 어둠은 우리의 고향일세.\n\n더 많은 걸 배울 준비가 되면 어둠의사제 베릴을 찾아가게나.", progress = nil, completion = "마침내 도착했군. 자네의 신념만 가지고는 앞으로 다가올 시련들을 극복하기 힘들다네. 위기 의식과 약간의 야심이 많은 도움이 될 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5652] = {title = "약화의 주술", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 주술\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 주술"},
[5654] = {title = "약화의 주술", objective = "오그리마에 있는 우르쿄와 대화하십시오.", description = "<name>, 이제 우르쿄를 만날 시간이 왔네. 오크의 도시에 있는 정기의 골짜기로 가서 그와 이야기를 나눠보게. 우리 트롤 종족 대대로 내려오는 방식대로 훈련을 받을 때야. 잘 배워서 트롤의 진정한 사제가 돼야 하네.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 주술\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 주술\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5655] = {title = "약화의 주술", objective = "오그리마에 있는 우르쿄와 대화하십시오.", description = "<name>, 내가 이곳에 파견된 이유는 자네가 고향에서 너무 멀리 벗어나 정처없이 헤매지는 않나 확인하기 위해서지. 지금 바로 고향으로 돌아가게. 트롤 사제 중에서 단연 최고의 실력을 자랑하는 우르쿄가 자네를 기다리고 있을 거야. 그러니 어서 돌아가게. 오크의 도시에 있는 정기의 골짜기로 들어가게. 가서 우르쿄를 찾아. 아마 애타게 기다리고 있을 거야.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 주술\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 주술\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5656] = {title = "약화의 주술", objective = "오그리마에 있는 우르쿄와 대화하십시오.", description = "나와 같은 사제들이 온갖 역경을 헤치며, 이 세상을 돌아다니는 걸 보면 싸늘히 식어버린 내 가슴도 훈훈해지지. 주술이라는 것도 일단 알고 보면 그렇게 신비한 것도 아니지. 노력만 하면 쉽게 손에 넣을 수 있다오. 그래서 말인데, 이제 당신은 고향으로 돌아가는 게 좋겠소.\n\n위대한 트롤 사제, 우르쿄가 오그리마에서 당신을 기다리고 있소. 정기의 골짜기로 가면 그를 찾을 수 있을 거요.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 주술\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 주술\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5657] = {title = "약화의 주술", objective = "오그리마에 있는 우르쿄와 대화하십시오.", description = "돌아가게, <name>. 고향으로 돌아가.\n\n자네의 정신적 지주, 우르쿄가 앞으로 여정에 대해 이야기를 나누기를 원하고 있으니까.\n\n거대한 호드의 도시, 오그리마에 있는 정기의 골짜기로 가봐. 거기 가면 우르쿄를 찾을 수 있을 거야.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 주술\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 주술\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5658] = {title = "무력의 손길", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 손길\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 손길"},
[5660] = {title = "무력의 손길", objective = "언더시티에 있는 애살리스테와 대화해야 합니다.", description = "자넨 고향에서 멀리 왔군. 자네의 고향 언더시티로 돌아가야하네. 고위사제 애살리스테가 자네가 돌아오기 원하고 있어. 우리 종족도 그러하듯이 자네도 애살리스테에게서만 배울 수 있는 무엇인가 있지. 여기 너무 오래 머물지 말게. 비행선을 타고 최대한 빨리 언더시티의 군사 지구로 돌아가게.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 손길\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 손길\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5661] = {title = "무력의 손길", objective = "언더시티에 있는 애살리스테와 대화해야 합니다.", description = "자네는 고향에서 멀리 떨어진 여기 블러드후프 마을까지 왔군. 나는 우리 종족의 사제를 찾아서 지도자에게 보내라는 임무를 맡고 여기 왔네. 그렇지만 자네를 도와줄 수 없다는 건 아닐세.\n\n자네의 고위 여사제의 영혼이 모든 포세이큰이 자신에게 돌아오기를 원한다는 말이 들리네. 자네가 반드시 배워야 하는 것이 있어.\n\n자네의 도시에 있는 군사 지구로 가서 애살리스테를 만나게.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 손길\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 손길\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5662] = {title = "무력의 손길", objective = "언더시티에 있는 애살리스테와 대화해야 합니다.", description = "자네와 자네의 종족에게 경의를 표하네. 나는 보통 나와 같은 종족만 가르치지. 자네는 한 때 로데론이라고 불렀던 도시에 있는 애살리스테에게 사제의 기술을 배워야 하네.\n\n자네의 신념 외에도 다른 능력들을 배우려면 애살리스테에게 돌아가야 한다네.\n\n언더시티의 군사 지구로 가서 자네의 여사제를 찾게나.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 손길\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 손길\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5663] = {title = "무력의 손길", objective = "언더시티에 있는 애살리스테와 대화해야 합니다.", description = "애살리스테님께서는 모든 사제들에게 전갈을 보내셨소. 우리는 우리 계급의 젊은이들이 더 많은 훈련을 받을 수 있도록 언더시티로 안내하기로 되어 있소이다. 당신이 진심으로 우리의 신념을 믿는다면 언더시티로 돌아가시오. \n\n언더시티 깊숙한 곳의 군사 지구에서 애살리스테님을 찾을 수 있을 것이오.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n무력의 손길\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n무력의 손길\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5672] = {title = "엘룬의 은총", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n엘룬의 은총\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n엘룬의 은총"},
[5673] = {title = "엘룬의 은총", objective = "다르나서스에 있는 여사제 알라시아와 대화하십시오.", description = "당신도 알고 있겠지만, 언제든지 이곳에 오면 우리 사제들이 가르침을 줄 것입니다. 하지만 우리가 전수할 수 없는 게 있다면, 바로 여신 엘룬의 가르침입니다. 엘룬은 믿음이 있는 자에게는 특별한 능력을 준다고 합니다. 이제 당신은 달의 신전으로 돌아가서 시험을 치를 시간인 것 같군요.\n\n시간이 될 때 신전으로 돌아가서 여사제 알라시아와 이야기를 나눠 보십시오.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n엘룬의 은총\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n엘룬의 은총\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5674] = {title = "엘룬의 은총", objective = "다르나서스에 있는 여사제 알라시아와 대화하십시오.", description = "<name>, 오늘은 그대에게 눈부신 날이로군요. 나이트 엘프 <사제/여사제>만의 능력을 배울 때가 된 것이죠. 하지만 그대의 훈련은 제가 아닌 다른 분이 맡고 있습니다. 여기 일을 가능한 한 빨리 마치고 달의 신전으로 돌아가서 여사제 알라시아와 대화를 해보십시오. 그대가 진정으로 준비가 됐는지 알아보기 위한 시험을 치른 다음, 엘룬의 은총에 대해 알려줄 겁니다.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n엘룬의 은총\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n엘룬의 은총\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5675] = {title = "엘룬의 은총", objective = "다르나서스에 있는 여사제 알라시아와 대화하십시오.", description = "시간이 됐습니다. 다르나서스로 돌아갈 시간이... 여사제 알라시아께서 훈련을 위해 돌아오라는 전갈을 당신 앞으로 보내셨습니다. 빛을 섬기는 모든 이들처럼 당신도 이제 시험을 치를 준비가 됐다고 생각하시는 모양입니다. 준비가 되는 대로 출발하십시오. 알라시아께서는 달의 신전에서 기다리고 계실 겁니다. 행운을 빌어요.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n엘룬의 은총\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n엘룬의 은총\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5676] = {title = "비전 역순환", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n역순환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n역순환"},
[5677] = {title = "비전 역순환", objective = "스톰윈드에 있는 대여사제 로레나와 대화해야 합니다.", description = "우리만의 특별한 빛의 가르침에 대해서 보여 주고 싶지만 여기서는 불가능합니다. <형제/자매>가 스톰윈드로 가는데 아무런 방해도 받지 않을 것이니 날 믿고 지금 당장 스톰윈드로 돌아가십시오. 앞날을 위해 <형제/자매>의 종족은 <형제/자매>를 준비시키고 <형제/자매>와 비슷한 길을 가고 있는 이들과 구분 지어야 합니다. 빛의 대성당에 있는 로레나님께 돌아가면 내가 말하는 내용을 이해할 겁니다.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n역순환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n역순환\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5678] = {title = "비전 역순환", objective = "스톰윈드에 있는 대여사제 로레나와 대화해야 합니다.", description = "스톰윈드로 돌아갈 시간이 되었습니다, 젊은 사제님. 거기 있는 그대의 상관이 훈련을 위해 그대를 부르고 있습니다. 이런 것이 내게 좀 방해가 된다고 해도 그대의 종족과 내 종족은 동맹 관계이고 나도 동맹 관계의 방식을 따를 것입니다.\n\n난 그대에게 순진한 티를 내려는 것이 아닙니다. 나는 비전 마법이 신께서 영감을 주신 신성한 것이든지 아니든지 믿지 않습니다.\n\n빛의 대성당에 가면 내가 하는 말을 알게 될 겁니다. 그곳에서 대여사제 로레나와 얘기해 보도록 하세요.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n역순환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n역순환\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5679] = {title = "파멸의 역병", objective = "준비가 됐으면 파멸의 역병에 대해 가르쳐 주지. 이것은 가공할 힘을 지닌 주문으로 다가오는 전투에 도움이 될 것이네. 나중에 시험을 볼 것이니 연습하게나.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n파멸의 역병\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n파멸의 역병"},
[5680] = {title = "어둠의 수호", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n어둠의 수호\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n어둠의 수호"},
[5713] = {title = "백발백중", objective = "파수꾼 아이나샤를 보호한 다음 잿빛 골짜기의 마에스트라 주둔지에 있는 오나에야에게 사고 소식을 알려 주어야 합니다.", description = "중요한 전갈을 가지고 아우버다인을 여행하고 있을 때 펄볼그 마로쉬와 그의 추적자들의 공격을 받았습니다. 그러다가 온몸에 독이 퍼져서 똑바로 서 있을 수도 없게 되었습니다. 해독제를 만들 수는 있지만 준비가 되려면 꽤 오랜 시간이 걸릴 것입니다.\n\n해독제를 완성할 때까지 저를 지켜 주십시오. 제가 할 수 있는 한 이 활로 힘껏 도와 드리겠습니다.\n\n우리가 살아남는다면 저는 아우버다인에 전갈을 전하러 가겠습니다. 그대는 마에스트라 주둔지에 있는 오나에야에게 이 사고를 알려주세요.", progress = nil, completion = "정말 기쁜 소식입니다. 아이나샤가 그대 덕분에 살았다니 너무 감사합니다. 그대의 용맹에 대한 보답으로 사례를 하겠습니다. 엘룬께서 항상 그대를 살피시며 가시는 길을 밝혀 주시기를.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5721] = {title = "다로우샤이어 전투", objective = "다로우샤이어 마을 광장에 유물 더미를 가져다 놓아야 합니다.\n\n호르구스보다 다빌 라이트파이어가 먼저 죽지 않도록 다빌을 보호해야 합니다.\n\n레드패스는 오염되기 전까지 처치하면 안 됩니다.\n\n레드패스가 오염되면 처치해야 합니다.\n\n마을 광장에 조셉 레드패스의 영혼이 나타나면 대화를 나눈 후 집에 있는 파멜라와 대화를 나누십시오.", description = "이제 당신은 다로우샤이어 전투에 참전해서 조셉 레드패스를 구해야 합니다.\n\n이 유물 더미를 다로우샤이어 마을 광장에 놓으면 다로우샤이어의 영혼들이 깨어날 거예요. 그들의 전투에 참여하세요. 그리고 두 가지를 명심하세요. 다빌은 호르구스가 죽기 전까지 살아 남아 있어야 하고, 레드패스는 오염될 때까지 죽이지 말고 기다렸다가 오염되면 물리쳐야 되요.\n\n오염된 레드패스를 물리치면 레드패스의 영혼은 구원을 받을 거예요. 그런 다음 레드패스와 대화를 나누고 그의 딸 파멜라에게 돌아가세요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n달콤한 차"},
[5722] = {title = "잃어버린 가방 찾기", objective = "성난불길 협곡에서 마우리 그림토템의 시체를 찾아 도움이 될 만한 것들을 찾아야 합니다.", description = "마가타님께서 성난불길 협곡에 대해서 관심을 가지는 건 트로그뿐만이 아닙니다. 마가타님께서는 그분의 하인 중에 한 명인 마우르 그림토템이 협곡에 있는 동안 특별한 무엇인가를 발견했다는 소식을 들으셨는데 마우르는 어떤 물건인지 마가타님께 단 한 번도 보여주지 않았습니다. 마가타님께서는 마우르의 시체가 있다면 그걸 찾고 싶어하십니다. 그리고 마우르가 트로그와 대화를 시도하면서 발견한 어떤 흔적이든 찾고 싶어하십니다.\n\n마가타님께서 관심을 가질 만한 물건을 가져다 주면 분명 후하게 보상해 주시리라 믿습니다.\n\n다시 한번, 오그리마의 가장 어두운 지역으로 가서 협곡을 찾아보시기 바랍니다.", progress = nil, completion = "마우르 그림토템의 시체는 곤봉이나 장착 무기류에 심하게 손상됐지만 옷과 장비는 그대로 있는 것으로 보입니다. 트로그는 물질적인 욕심은 별로 없는 모양입니다.\n\n시체를 뒤져서 마가타에게 도움이 될 만한 것들을 찾아보기 시작합니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5723] = {title = "성난불길 협곡의 트로그", objective = "오그리마에 있는 성난불길 협곡을 찾아 성난불길 트로그 8마리와 성난불길일족 주술사 8마리를 처치하고 썬더 블러프에 있는 라하우로에게 돌아가야 합니다.", description = "오그리마 지하의 트로그라고 알려진 강인한 생물들이 용암이 지하도를 가득 매운 깊숙한 곳에서 지상으로 나오기 시작했습니다. 자비로우신 마가타님께서는 트로그와 평화를 유지하려고 하셨지만 트로그는 사신을 공격해서 죽이고 말았습니다. 마가타님께서는 트로그의 그런 행동을 용납하지 않으시며 이제는 트로그를 호드를 위협하는 생물로 간주하고 계십니다.\n\n마가타님께서는 트로그가 호드를 해치기 전에 트로그의 위협을 종식해줄 것을 원하십니다. 성난불길 협곡을 찾아서 트로그들을 모조리 해치워 주십시오.", progress = nil, completion = "마가타님께서 맡기신 일을 잘 처리해 주어서 기쁘군요. 감사합니다. 이젠 트로그의 수가 급격하게 줄어서 지상으로 나오기는 힘들 것입니다.\n\n아마도 추후에 이 트로그들이 어디서 왔는지, 뭘 원하는지 알아볼 시간이 있을 것입니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5724] = {title = "잃어버린 가방 돌려주기", objective = "썬더 블러프에 있는 라하우로에게 그림토템 가방을 가져가야 합니다.", description = "타우렌 시체 밑에 있는 가방을 발견했습니다. 트로그에게 공격을 당하는 와중에서도 지키려고 했는지 아직도 손에 가방이 꽉 쥐어져 있습니다.\n\n단단히 쥐어진 가방을 빼내서 장비에 넣고 지하도를 빠져나와서 썬더 블러프에 있는 라하우로에게 돌아갈 준비를 합니다.", progress = "발견한 것이라도 있습니까? 마가타님의 하인이 어떤 이유로 헛되이 죽었는지에 대한 단서가 될만한 것이라면 도움이 될 것입니다.", completion = "훌륭하군요. 고맙습니다.\n\n마가타님께서 그대가 그분의 하인을 찾는 데 성공하면 이걸 그대에게 전해주라고 하셨습니다. 자, 감사의 표시로 드리는 것이니 받아 주시기 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n깃털구슬 팔보호구열대초원 팔보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5725] = {title = "파괴해야 할 힘", objective = "언더시티에 있는 바리마트라스에게 어둠의 주문서와 황천의 마법서를 가져가야 합니다.", description = "자네도 당연히 알겠지만 불타는 군단이 그들의 추종자들에게 선물을 주었다. 실바나스 여왕님께서는 그 선물 중 일부는 앞을 멀리 내다볼 줄 모르는 우매한 이들의 손에 있는 것보다는 여왕님의 손에 있는 것이 좋다고 생각하신다.\n\n오그리마 아래의 동굴에 숨어 있는 이글거리는 칼날단으로 알려진 어둠의 의회의 한 종파가 대표적인 예라고 할 수 있지. 어둠의 여왕님께서 말씀하시기를 이글거리는 칼날단의 일원들이 두 권의 강력한 마법책을 지니게 되었고 그 책을 빌리고 싶다고 하셨다. 어둠의 여왕님을 위해 책을 가지고 와라.", progress = "처리할 일이 너무나 많다, <class>. 주문서는 가져왔나?", completion = "좋아. 어둠의 여왕님의 뜻을 충실히 수행했군. 자네의 지칠 줄 모르는 강인한 정신력과 패기는 어둠의 여왕님에게 큰 도움이 될 것이야. 훗날 나에게 다시 돌아와라. 어둠의 여왕님께서 리치 왕을 뛰어넘고 스컬지에게 진정한 자유를 안겨 주시려고 할 때 자네의 도움을 필요로 할 것이야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n유령 반바지진창늪 다리보호구가고일 다리보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5726] = {title = "내부의 배신자", objective = "오그리마에 있는 스랄에게 부관의 휘장을 가져가야 합니다.", description = "우리 중 배신자가 있다는 건 절대 참을 수 없는 일... 한 때, 난 너무 성급하게 실력을 행사했지. 바보 같이... 결국 이 땅의 타락을 막기는커녕 오히려 악화시키고 말았도다.\n\n하지만 그대와 같이 혈기왕성한 <class>|1이라면;라면; 나의 부관들이 갈 수 없는 곳까지 들어가서 진실을 밝혀내고 사나운 악마를 물리칠 수 있을 것이다.\n\n용기가 있다면 오그리마 동쪽의 해골 바위굴로 가서 불타는칼날단 부관의 휘장을 찾아오라.", progress = "<name>, 아직도 휘장을 찾지 못했나?\n\n호드에게 가장 위협이 되는 곳에 잠입하려면 반드시 그 휘장이 필요하다. 우리의 새로운 고향에 평화를 가져오기 위한 일이야.\n\n그대도 언젠가는 깨닫게 되리라. 탐욕과 권력이 원인이 되어 일어나는 일은 인간과 오크 모두를 거미줄처럼 얽히게 한다는 걸. 이제 숨겨진 계획과 타락, 그 모든 것들이 백일하에 드러날 것이다. 그리고 그대는 지금까지 진행되고 있는지조차 몰랐던 전쟁의 소용돌이, 그 한가운데 자신이 서 있다는 사실을 알게 되리라.", completion = "잘했도다! 그 용기는 칭송받아 마땅하리라. 나의 가장 큰 근심을 없애줄 주인공이 바로 그대일지도 모르겠군! 이렇게 용감한 젊은이가 등장해서 우리를 위해 일하리라고 누가 생각이나 했겠는가? 그대를 보면 나의 젊은 시절이 생각나는군. 폭풍과도 같이 다가올 전쟁의 소용돌이에서 우리 둘 다 살아남는다면 내 반드시 그대에게 큰 보상을 내리겠다.\n\n자세한 얘기는 나중에 더 나누도록 하자. 앞으로 부딪힐 일에 비교하면 지금 한 일은 아무것도 아니니까. 하지만, 썩 괜찮은 출발인 건 사실이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5727] = {title = "내부의 배신자", objective = "부관의 휘장을 네루 파이어블레이드에게 가져간 다음 대화를 해야 합니다. 네루 파이어블레이드가 당신을 불타는칼날단의 일원으로 믿고 있는지 확인한 다음 오그리마에 있는 스랄에게 돌아가야 합니다.", description = "이제 그대가 애써 찾은 이 휘장이 쓸모가 있는지 확인해 보자.\n\n이 도시에 나의 신뢰를 얻었다는 착각에 빠진 흑마법사가 하나 살고 있다. 하지만 난 그자의 정체를 훤히 알고 있다. 사실 그 흑마법사는 불타는칼날단의 지휘관이지. 하지만 섣부른 숙청은 오히려 화를 부를 수 있어. 분명 써먹을 데가 있을 거야.\n\n이 휘장을 오그리마, 어둠의 틈에 있는 그 흑마법사에게 가져다주면 그대를 불타는칼날단의 동지로 생각할 것이다. 그를 살짝 떠보아라. 그런 다음 여기로 나를 찾아오라.", progress = nil, completion = "훌륭하도다! 정말 멋지게 성공했군, &lt;class&gt;!\n\n오늘 그대는 어둠의 의회를 무너뜨리는 대업을 위한 첫 발을 내디딘 것이다.\n\n그 흑마법사가 한 말을 한마디도 빼지 말고 말해보아라. 생각보다 굉장히 중요한 내용을 담고 있을 수도 있으니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5728] = {title = "내부의 배신자", objective = "바잘란과 기원사 제로쉬를 제거한 다음 오그리마에 있는 스랄에게 돌아가야 합니다.", description = "음, 이글거리는 칼날단의 우두머리들이라... 가장 신경 쓰이는 부분이군. 그들이 네루에게 중요한 이들이라면 우리의 첫 번째 제거 대상이 돼야 한다. 음... 네루가 말한 사티로스 바잘란과 다른... 흑마법사... 둘을 제거해야 해.\n\n어둠의 틈으로 돌아가서 성난불길 협곡으로 들어가라. 이글거리는 칼날단의 우두머리 둘을 찾아서 제거하라. 단, 네루가 눈치채지 못하도록 주의해야 한다. 계속 네루의 동지인 척 속여야 하니까.", progress = nil, completion = "&lt;name&gt;, 무사히 돌아와서 다행이군. 내 충성스런 부하들로부터 그대의 승전 보고를 받았다. 오그리마 아래에 있는 동굴에서는 지금 우두머리가 살해돼서 우왕좌왕이라더군. 네루가 굉장히 흥분했다는 보고도 받았고. 한 방 먹여준 셈이지. 작은 승리지만 사뭇 넘치는 기쁨을 감출 수 없도다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5729] = {title = "내부의 배신자", objective = "오그리마에 있는 네루 파이어블레이드와 대화하십시오.", description = "그대가 다음으로 할 일은 네루에게 접근하는 것이다. 보고 받은대로 네루가 굉장히 흥분한 상태라면, 두 가지 정도는 쉽게 해낼 수 있을 것이다. 첫째로, 어둠의 의회나 불타는칼날단에 대한 정보를 더 많이 얻어내는 것! 둘째로, 네루가 그대에게 도움을 청하도록 그의 신뢰를 얻는 것이다. 자리가 비어 흔들리고 있는 상황에서 그대를 차세대 지도자 감으로 고려할 가능성은 매우 크다.\n\n어둠의 틈으로 돌아가서 네루와 다시 대화를 나눠라. 조심하라. 의심의 여지를 조금이라도 남겨서는 안 돼.", progress = nil, completion = "거기 뭐야? 아, 자네였군. 사과하리다. 우리 &lt;class&gt; 동지여... 지금 화가 머리끝까지 나서 열이 오를 지경이었거든. 하지만 다 내 잘못이지. 어중이떠중이들을 성난불길 협곡으로 보낼 때 위험할 수도 있다는 걸 예상했어야 하는데. 바잘란과 제로쉬 모두 스랄의 암살자에게 쥐도 새도 모르게 살해당했소. 시기가 참 좋지 않지. 게다가 지금으로서는 아무 대책도 없소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5730] = {title = "내부의 배신자", objective = "오그리마에 있는 스랄에게 알아낸 것을 보고해야 합니다.", description = "용감한 <class>|1이여;여;, 자네를 내 부관으로 임명하는 바이네! 곧 내 부름에 응할 준비를 하고 있게나.\n\n어쩌면 내가 이글거리는 칼날단에 쏟은 시간과 노력이 모두 허사가 될지도 모르겠군. 그렇다고 다른 지역에서 어둠의 의회의 계획과 활동에 차질이 생기는 건 아니지. 성난불길 협곡에서의 피해를 복구하기 위해 내가 할 수 있는 일은 죄다 할 거야. 참, 그건 그렇고 불모의 땅과 잿빛 골짜기에 있는 내 부하들에게 새로운 계획을 시작하라고 할 테니까, 자네도 빠른 시일 내에 내게 돌아와야 하네.", progress = nil, completion = "잿빛 골짜기? 흠, 잿빛 골짜기에 어둠의 의회나 불타는칼날단이 나타났다는 소리는 못 들었는데... 내 비밀 요원들에게 조사를 지시해야 겠군. 잘했다, &lt;name&gt;.\n\n지금은 좀 쉬도록 하여라. 조만간 그대를 다시 불러 다른 임무를 맡기도록 하겠노라.\n\n록 타 오그아르!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n오그리마의 크리스오그리마의 망치오그리마의 도끼오그리마의 지팡이\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5741] = {title = "빛의 홀", objective = "빛의 홀을 얻은 후 에텔 레소르의 탑에 있는 아조레 알다모트에게 돌아가야 합니다.", description = "동쪽의 천둥도끼 요새에 불타는칼날단이 나가에게서 빛의 홀을 얻었다는 소문이 있네. 전설에 의하면 이 홀은 도시 전체를 대해 아래로 침몰시킬 수 있을 정도로 강한 것이라고 하네. 그런 힘을 불타는칼날단이 지니고 있게 해서는 안 되네.\n\n이를 마치려면 자네 자신이 빛의 홀을 회수해야만 하네! 빛의 홀은 천둥도끼 요새 감시탑 중 하나의 꼭대기에 홀을 연구하는 불타는칼날단 현자가 지니고 있었으니 그리 가 보게나.", progress = "빛의 홀은 가져왔는가?", completion = "이것이 바로 그 손에 넣기 어려운 빛의 홀이로군! 자네가 이 홀을 가져옴으로써 이 세계에 대한 거대한 위협이 제거된 것일세. 잘 했네, &lt;class&gt; 친구. 아주 잘 했어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5742] = {title = "구원", objective = "티리온 폴드링이 하려고 하는 말이 무엇인지 들어야 합니다.", description = "친구, 자네 정말 열심히 일하지 않았나? 피곤에 지친 몸도 좀 쉬게 하고 내게도 기회를 줘야 하지 않겠어?", progress = "부탁이야, 친구. 앉아서 내 얘기를 좀 들으라고.", completion = "폴드링을 구원하는 일은 쉽지 않을 걸세. 준비는 됐나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5761] = {title = "야수 처단", objective = "성난불길 협곡으로 가서 욕망의 타라가만을 제거한 다음 그의 심장을 오그리마에 있는 네루 파이어블레이드에게 가져가야 합니다.", description = "위대한 대족장님께서 내게 맡기신 주요 임무는 우리 도시에 출몰해 사악한 마법으로 혼란을 일으키는 놈들을 모조리 처치하는 것이라네. 불타는칼날단도 위험하지만 성난불길 협곡에 자리 잡고서 은밀히 무고한 호드의 일원을 해치려는 이글거리는 칼날단 같은 조직도 위험하지.\n\n놈들을 저지하려면 그들의 우두머리인, 욕망의 타라가만이라는 지옥군단병을 없애야 해.\n\n놈을 죽이면 스랄님도 조금이나마 진정하실 거야.", progress = "놈을 해치웠나? 욕망의 타라가만이 성난불길 협곡에 본거지를 틀고 있는 이글거리는 칼날단의 우두머리가 분명해.", completion = "하하! 해냈군! 스랄님께서 매우 기뻐하시겠어.\n\n나는 스랄님께 가져갈 수 있도록 이 심장을 잘 처리해야겠어.\n\n지금은 승리의 기쁨을 만끽하도록 하게. 스랄님께 당신의 성공을 알리겠네.\n\n도와줘서 고마워.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5762] = {title = "헤멧 네싱워리", objective = "가시덤불 골짜기에 있는 헤멧 네싱워리에게 크레이블의 상자를 가져가야 합니다.", description = "헤멧 네싱워리라는 드워프는 내 오랜 단골인데, 그 앞으로 소포가 하나 왔지. 몇 주가 걸려서 겨우 도착한 소포인데, 하필이면 헤멧이 지금 멀리 떠나있지 뭐요. 가시덤불 골짜기로 사냥하러 간다고 했었어요. 그런데 떠날 때 내게 돈을 주면서 시간이 나면 자기 앞으로 올 물건을 배달해 달라고 하더군요.\n\n헤멧은 부자예요. 돈 많은 드워프와는 좋은 관계를 유지하는 게 좋지 않겠습니까? 그럼 날 위해 소포를 좀 전해줄 수 있겠지요?\n\n헤멧은 그롬골 북쪽에 있는 가시덤불 골짜기에 야영지를 하나 소유하고 있다고 들었습니다.", progress = "자네 목 둘레에 뿌옇게 묻어 있는 그게 사막의 모래 먼지인가?\n\n흠, 내 코가 고장난 게 아니라면 사막의 모래가 아니라 사막의 소금이로군! 자네, 소금 평원에서 오는 길이지?!", completion = "&lt;name&gt;, 정말 고맙네! 콜비어드가 보낸 소포로군! 이 상자 안에 든 탄환을 내 최고급 구경에 장착하면 밀림에서 진가를 톡톡히 발휘할 거야!\n\n자네 보수는 여기 있네. 아, 그리고 크레이블은 요즘 어떤가? 보나마나 경기가 별로 안 좋다고 했겠지만...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5763] = {title = "가시덤불 골짜기의 사냥꾼", objective = "가시덤불 골짜기에 있는 헤멧 네싱워리에게 룬의 코도 뿔을 가져가야 합니다.", description = "오래전 한 드워프가 이 땅으로 왔네. 그의 이름은 헤멧. 커다란 짐승을 잡고 싶어 했지. 헤멧의 사격 실력은 정말 대단했고 우리는 여러 날을 함께 사냥하면서 보냈네. 우리의 우정으로 헤멧이 우리 타우렌에게 품고 있던 적개심은 모두 사라졌지.\n\n헤멧이 잊혀진 땅을 떠나 가시덤불 골짜기로 돌아갈 때 다시 한 번 함께 사냥을 하러 돌아오겠다고 약속을 했지. 약속한 그 시간이 다가왔네.\n\n이 코도 뿔을 헤멧에게 가져다 줘. 보면 내가 보낸 걸 알 걸세. 그롬골 주둔지 북쪽에 있는 가시덤불 골짜기로 가면 헤멧을 찾을 수 있을 거야.", progress = "앉게나, <class>|1이여;여;. 함께 밀림으로 사냥을 떠나세.", completion = "아, 이 뿔은 내 타우렌 친구, 룬 와일드메인의 것이 아닌가! 한때 우리는 잊혀진 땅에서 멋지게 사냥을 했었지. 이 뿔을 보내다니, 그렇다면 룬이 날 사냥에 초대하는 건가?\n\n어쩌나, 이미 밀림에 깊숙이 들어온 상태라 발을 빼기가 힘든데. 좌우지간 고맙네. 다음 목적지는 켄타우로스의 본거지, 잊혀진 땅이 되겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5781] = {title = "잃어버린 기억들", objective = "동부 역병지대의 최남쪽에 있는 지하 납골당으로 가서 탤런의 망치를 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다.", description = "탤런이 잃어버린 것들을 되찾도록 도와주려면 탤런의 과거의 물건들을 모아야 한다네.\n\n첫 번째 물건은 내가 탤런의 7번째 생일 선물로 주었던 장난감이네. 내가 전투 망치를 본따 만든 아주 작은 모형이지. 탤런이 정말 아꼈었는데...\n\n내가 반역죄로 추방당한 후 탤런의 엄마는 탤런에게 내가 죽었다고 말했지. 탤런의 엄마는 탤런을 지하 납골당에 있는 내 가짜 무덤으로 데리고 갔고, 탤런은 망치와 함께 나에 대한 기억도 영원히 묻은 거지.\n\n자네가 지하 납골당으로 가서 탤런의 망치를 되찾아 오게.", progress = "탤런은 반드시 기억을 되찾을 걸세.", completion = "&lt;눈물을 참기 위해 눈을 깜박거리는 티리온&gt;\n\n우리가 만난 건 운명일세. 자네는 나에게 너무도 큰 친절을 베풀어 주었어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5801] = {title = "불기둥 용광로", objective = "운고로 분화구에 있는 불기둥 마루의 꼭대기로 해골 열쇠 거푸집과 토륨 주괴 2개를 가져가야 합니다. 용암의 강에서 해골 열쇠 거푸집을 이용해서 불완전한 해골 열쇠를 만들어야 합니다.\n\n불완전한 해골 열쇠를 서부 역병지대의 서리바람 거점에 있는 연금술사 알빙턴에게 가져가야 합니다.", description = "열쇠를 만들려면 토륨 주괴 2개와 굉장히 높은 열을 낼 수 있는 장소가 필요하지. 토륨은 알아서 찾아보라고. 그 장소에 대해서는 내가 힌트를 좀 줄 테니까.\n\n여기서 서쪽으로 가면 있는 운고로 분화구에는 불기둥 마루라고 하는 활화산이 있어. 그 꼭대기, 용암의 강에서 뿜어져 나오는 열기는 토륨은 물론이고, 해골을 녹일 만큼 뜨겁지. 자네가 구입한 거푸집을 그 용암의 강에 잠깐 담그기만 하면 나머지는 용암이 알아서 할 거야.\n\n자, 여기까지! 참, 열쇠를 완성하려면 알빙턴과 다시 얘기를 해봐야 할 걸.", progress = "해골 열쇠는 거의 다 완성하셨나요? 죄송합니다만, 거푸집의 가격은 더 이상 깎아드릴 수가 없군요. 우린 스컬지를 상대할 수 있도록, 맡은바 소임에 충실할 뿐이랍니다. 제게 불완전한 해골 열쇠를 가져오셨다면, 당신에게 마지막으로 남은 일을 알려드리죠. 열쇠를 완성하려면 그 물건이 반드시 있어야 합니다.\n\n쉽지는 않겠지만, 안돌할 공격이라는 어마어마한 작전을 준비하신 분이니, 그만한 대가는 치를 준비가 되셨겠죠?! 차차 알게 될 거예요.", completion = "&lt;name&gt;, 불완전한 해골 열쇠를 가지고 계시겠죠. 조그만 열쇠 하나에 돈 한번 겁나게 들지 않습니까? 아시겠지만, 아직 완전하지 않은 상태입니다. 하지만, 고지가 멀지 않습니다. 이제는 열쇠를 완성한 후의 일에도 신경을 써야 합니다. 안돌할 공격의 궁극적인 목표는 파괴된 도시를 장악하고 있는 사악한 적을 무찌르는 것입니다.\n\n자칭 가장 강력한 스컬지라고 하는, 사악한 리치 소환사 아라즈를 말하는 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5802] = {title = "불기둥 용광로", objective = "운고로 분화구에 있는 불기둥 마루 꼭대기로 해골 열쇠 거푸집과 토륨 주괴 2개를 가져가야 합니다. 용암의 강에서 해골 열쇠 거푸집으로 불완전한 해골 열쇠를 만들어야 합니다.\n\n불완전한 해골 열쇠를 서부 역병지대의 보루에 있는 연금술사 디더스에게 가져가야 합니다.", description = "열쇠를 만들려면 토륨 주괴 2개와 굉장히 높은 열을 낼 수 있는 장소가 필요하지. 토륨은 알아서 찾아보라고. 그 장소에 대해서는 내가 힌트를 좀 줄 테니까.\n\n여기서 서쪽으로 가면 있는 운고로 분화구에는 불기둥 마루라고 하는 활화산이 있어. 그 꼭대기, 용암의 강에서 뿜어져 나오는 열기는 토륨은 물론이고, 해골을 녹일 만큼 뜨겁지. 자네가 구입한 거푸집을 그 용암의 강에 잠깐 담그기만 하면 나머지는 용암이 알아서 할 거야.\n\n자, 여기까지! 참, 열쇠를 완성하려면 디더스와 다시 얘기를 해봐야 할 걸.", progress = "해골 열쇠는 거의 다 완성하셨나? 미안하지만, 그 거푸집의 가격은 더 이상 깎아드릴 수가 없네. 우린 스컬지를 상대할 수 있도록, 맡은바 소임에 충실할 뿐이지. 불완전한 해골 열쇠를 가져왔다면, 자네에게 마지막으로 남은 일을 알려주지. 열쇠를 완성하려면 그 물건이 반드시 있어야 해.\n\n쉽지는 않겠지만, 안돌할 공격이라는 어마어마한 작전을 준비한 장본인이니, 그만한 대가는 치를 준비가 되있겠지. 차차 알게 될 거야.", completion = "&lt;name&gt;, 불완전한 해골 열쇠를 가지고 왔겠지. 조그만 열쇠 하나에 돈 한번 겁나게 들지 않나? 자네도 알겠지만, 아직 완전하지 않은 상태야. 하지만, 고지가 멀지 않았네. 이제는 열쇠를 완성한 후의 일에도 신경을 써야 해. 안돌할 공격의 궁극적인 목표는 파괴된 도시를 장악하고 있는 사악한 적을 무찌르는 거야.\n\n자칭 가장 강력한 스컬지라고 하는, 사악한 리치 소환사 아라즈를 말일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5803] = {title = "아라즈의 스카라베", objective = "소환사 아라즈를 처치하고 아라즈의 스카라베를 서부 역병지대의 서리바람 거점에 있는 연금술사 알빙턴에게 돌아가야 합니다.", description = "소환사 아라즈는 파괴된 도시의 심장부에서 안돌할에 이르는 지역을 지배하고 있습니다. 아라즈는 도시를 차지하기 전에는 스칼로맨스의 지도자였지요. 열쇠를 완성하려면 열쇠의 머리 부분에 끼울 스카라베라고 부르는 아라즈의 인장이 필요합니다.\n\n안돌할의 심장부로 가서 그의 속박에서 도시를 해방시켜 주십시오. 그를 처치한 다음 떨어진 성물함에서 스카라베를 손에 넣도록 하십시오.\n\n스칼로맨스로 가는 열쇠가 당신을 기다리고 있을 겁니다!", progress = "지금까지 참 잘해주었습니다. 소환사 아라즈의 육체를 파괴해야만 열쇠를 완성할 수 있습니다. 무슨 수를 써서라도 열쇠의 머리에 붙일 수 있도록 아라즈의 스카라베를 내게 가져오십시오.", completion = "그래, 바로 이것입니다! 정말... 당신의 영리함과 용기에 놀라지 않을 수가 없군요. 어둠의 군대를 이렇게 빨리 물리치다니 믿을 수가 없습니다.\n\n이제 내 역할을 할 차례로군요. 스카라베를 열쇠의 머리에 안전하게 붙일 수 있는 특수한 용매를 준비했습니다. 스칼로맨스의 잠긴 문 뒤쪽까지 닿도록 힘을 줘서 부으면 된답니다.\n\n그렇게 오래 걸리지 않을 겁니다...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5804] = {title = "아라즈의 스카라베", objective = "소환사 아라즈를 처치하고 아라즈의 스카라베를 서부 역병지대에 보루에 있는 연금술사 디더스에게 돌아가야 합니다.", description = "소환사 아라즈는 파괴된 도시의 심장부에서 안돌할에 이르는 지역을 지배하고 있네. 아라즈는 도시를 차지하기 전에는 스칼로맨스의 지도자였지. 열쇠를 완성하려면 열쇠의 머리 부분에 끼울 스카라베라고 부르는 아라즈의 인장이 필요하네.\n\n안돌할의 심장부로 가서 그의 속박에서 도시를 해방시켜 주게. 그를 처치한 다음 떨어진 성물함에서 스카라베를 손에 넣게나.\n\n스칼로맨스로가는 열쇠가 자네를 기다리고 있을 걸세!", progress = "지금까지 참 잘해주었네. 소환사 아라즈의 육체를 파괴해야만 열쇠를 완성할 수 있다네. 무슨 수를 써서라도 열쇠의 머리에 붙일 수 있도록 아라즈의 스카라베를 내게 가져오게나.", completion = "그래, 바로 이것이로군! 정말... 자네의 영리함과 용기에 놀라지 않을 수가 없네. 어둠의 군대를 이렇게 빨리 물리치다니 믿을 수가 없군.\n\n이제 내 역할을 할 차례인가? 스카라베를 열쇠의 머리에 안전하게 붙일 수 있는 특수한 용매를 준비했네. 스칼로맨스의 잠긴 문 뒤쪽까지 닿도록 힘을 줘서 부으면 되지.\n\n그렇게 오래 걸리지 않을 것이야...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5805] = {title = "환영합니다!", objective = "메리사 스틸웰에게 노스샤이어 선물교환권을 가져가야 합니다.", description = "월드 오브 워크래프트의 세계에 오신 것을 환영합니다!\n\n월드 오브 워크래프트 컬렉터스 에디션을 구입해 주신 데 대한 감사의 표시로 작은 선물을 준비했습니다. 노스샤이어 계곡의 메리사 스틸웰에게 이 선물 교환권을 전해 주면 함께 퀘스트를 수행하고 모험을 떠날 작은 동반자를 선물로 받으시게 될 것입니다.\n\n다시 한 번 감사의 말씀을 드립니다. 그럼 즐거운 시간 되십시오!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n디아블로 소환석판다 목걸이저글링 목줄"},
[5821] = {title = "경호원 고용", objective = "콜카르 켄타우로스 마을을 지나가는 기젤톤 대상단을 호위하고 스크래블스크류의 야영지에 있는 스미드와 대화하여 보상을 받아야 합니다.", description = "보통 때 같으면 말이죠, 리거와 내가 우리 코도를 이끌고 콜카르 켄타우로스를 지나쳐 가겠지만요. 요즘은 이따금씩 켄타우로스 전쟁 북소리가 들려와서 말이에요. 그 소리를 들으면 우린 그냥 서 버린다니까요. 우리가 죽으면 사업이 무슨 소용이겠어요!\n\n이렇게 하는 게 어때요? 우리가 콜카르 마을을 지나갈 수 있도록 보호해 주시면 그에 대한 사례를 하도록 하죠.\n\n짧은 거리니까 짐마차만 안전하게 보호해 주시면 스미드 스크래블스크류에게서 보상을 받을 수 있을 거라니까요. 길을 따라 조금만 가다 보면 그 친구가 있거든요. 우리와 작은 사업을 같이 하고 있죠.", progress = nil, completion = "기젤톤 대상단을 호위하려고 경호원을 돈 주고 쓰는 건 돈벌이에 득이 안 될 텐데 말이야. 내 키가 조금만 더 컸어도 부업으로 내가 다룰 수 있는 총 중에서 제일 큰 총을 들고 코도 옆 안장에 앉아서 그 놈의 켄타우로스 녀석들에게 본때를 보여 줄 텐데...", rewards = "다음과 같은 것들을 받습니다:\n\n무역상의 반지"},
[5841] = {title = "환영합니다!", objective = "요리 크랙헬름에게 눈마루 골짜기 선물교환권을 가져가야 합니다.", description = "월드 오브 워크래프트의 세계에 오신 것을 환영합니다!\n\n월드 오브 워크래프트 컬렉터스 에디션을 구입해 주신 데 대한 감사의 표시로 작은 선물을 준비했습니다. 눈마루 골짜기의 요리 크랙헬름에게 이 선물 교환권을 전해 주면 함께 퀘스트를 수행하고 모험을 떠날 작은 동반자를 선물로 받으시게 될 것입니다.\n\n다시 한 번 감사의 말씀을 드립니다. 그럼 즐거운 시간 되십시오!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n디아블로 소환석판다 목걸이저글링 목줄"},
[5842] = {title = "환영합니다!", objective = "오렌실 위스퍼윈드에게 그늘 협곡 선물교환권을 가져가야 합니다.", description = "월드 오브 워크래프트의 세계에 오신 것을 환영합니다!\n\n월드 오브 워크래프트 컬렉터스 에디션을 구입해 주신 데 대한 감사의 표시로 작은 선물을 준비했습니다. 그늘 협곡의 오렌실 위스퍼윈드에게 이 선물 교환권을 전해 주면 함께 퀘스트를 수행하고 모험을 떠날 작은 동반자를 선물로 받으시게 될 것입니다.\n\n다시 한 번 감사의 말씀을 드립니다. 그럼 즐거운 시간 되십시오!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n디아블로 소환석판다 목걸이저글링 목줄"},
[5843] = {title = "환영합니다!", objective = "마가에게 시험의 골짜기 선물 교환권을 가져가야 합니다.", description = "월드 오브 워크래프트의 세계에 오신 것을 환영합니다!\n\n월드 오브 워크래프트 컬렉터스 에디션을 구입해 주신 데 대한 감사의 표시로 작은 선물을 준비했습니다. 시험의 골짜기의 마가에게 이 선물 교환권을 전해 주면 함께 퀘스트를 수행하고 모험을 떠날 작은 동반자를 선물로 받으시게 될 것입니다.\n\n다시 한 번 감사의 말씀을 드립니다. 그럼 즐거운 시간 되십시오!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n디아블로 소환석판다 목걸이저글링 목줄"},
[5844] = {title = "환영합니다!", objective = "보른 스카이시어에게 나라체 야영지 선물교환권을 가져가야 합니다.", description = "월드 오브 워크래프트의 세계에 오신 것을 환영합니다!\n\n월드 오브 워크래프트 컬렉터스 에디션을 구입해 주신 데 대한 감사의 표시로 작은 선물을 준비했습니다. 나라체 야영지의 보른 스카이시어에게 이 선물 교환권을 전해 주면 함께 퀘스트를 수행하고 모험을 떠날 작은 동반자를 선물로 받으시게 될 것입니다.\n\n다시 한 번 감사의 말씀을 드립니다. 그럼 즐거운 시간 되십시오!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n디아블로 소환석판다 목걸이저글링 목줄"},
[5845] = {title = "명예의 상징", objective = "동부 역병지대의 북동쪽에 있는 노스데일로 가서 실추된 명예의 상징을 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다.", description = "우서경께서 전사하셨을 때 은빛성기사단도 모두 전사했지. 탤런은 버틸 수 있을 때까지 버텼네.\n\n전쟁으로 피폐해진 노스데일의 작은 마을까지 떠밀려서 마지막까지 버텼던 거야. 탤런은 혹시 살아남은 자가 있을까 생각했었지만 그게 무슨 소용인가?\n\n탤런이 은빛성기사단의 규칙을 포기하고 알고 있던 모든 것들과의 관계를 끊은 것도 바로 이때였지. 탤런의 명예는 피와 함께 노스데일의 땅에 스며들었네.\n\n자네가 노스데일로 가서 실추된 명예의 상징을 되찾아 주게.", progress = "내 신념이 그대를 인도할 걸세. 무한한 빛의 기운이 함께 하길.", completion = "비록 상처투성이일지라도 이제는 내가 그리던, 동맹의 서약을 맺던 시절만큼이나 영광스럽군.\n\n탤런을 구원할 날도 그리 멀지 않은 것 같네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5846] = {title = "가족과 사랑", objective = "역병지대의 남쪽 중앙에 있는 카엘 다로우로 가서 초상화가 어디쯤 있는지에 대한 단서를 찾아야 합니다.", description = "탤런이 어렸을 때 우리는 카엘 다로우로 종종 소풍을 갔네. 마지막으로 소풍을 갔을 때 렌프레이라는 화가가 해변을 따라 늘어선 우리 초상화를 그려주었다네. 그게 탤런과 카란드라에 대한 가장 좋아하는 기억이네. 내 팔에 아내와 아들을 안고 있었기에 전에는 미처 깨닫지 못했던 사랑과 가족의 유대감을 느꼈다네.\n\n그 초상화가 아직도 있다면 꼭 찾아 주게.\n\n카엘 다로우의 폐허가 된 섬으로 가서 초상화나 그 화가가 아직도 있는지 확인해 주게.", progress = nil, completion = "내가 어떻게 잊을 수가 있겠어요? 이 섬의 많은 영혼들이 비참한 결말을 맞이하기 전에 행복했던 마지막 기억이라도 지키기 위해 저주를 선택했지요.\n\n저도 물론 저주를 받았지만 다른 이들과는 다르답니다. 저는 모든 것을 기억하는 몇 안 되는 이들 중 한 명이죠.\n\n이게 아마 당신이 저에게 물어본 이 폐허에 자주 나타나는 이유일 겁니다. 제가 당신에게 이런 일을 말해준 덕분에 당신이 절 자유롭게 해 줄지도 모르죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5847] = {title = "환영합니다!", objective = "클레어 윌로워에게 데스넬 선물교환권을 가져가야 합니다.", description = "월드 오브 워크래프트의 세계에 오신 것을 환영합니다!\n\n월드 오브 워크래프트 컬렉터스 에디션을 구입해 주신 데 대한 감사의 표시로 작은 선물을 준비했습니다. 데스넬의 클레어 윌로워에게 이 선물 교환권을 전해 주면 함께 퀘스트를 수행하고 모험을 떠날 작은 동반자를 선물로 받으시게 될 것입니다.\n\n다시 한 번 감사의 말씀을 드립니다. 그럼 즐거운 시간 되십시오!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n디아블로 소환석판다 목걸이저글링 목줄"},
[5848] = {title = "가족과 사랑", objective = "역병지대의 북쪽, 스트라솔름에 있는 붉은십자군 성채로 가서 쌍둥이 달 그림을 찾으십시오.\n\n그 뒤에 숨겨진 '가족과 사랑'이라는 그림을 찾아 티리온 폴드링에게 가져가야 합니다.", description = "초상화라... 기사단 병영 안의 내 작업장 벽에 몇 년 동안 걸려 있었죠.\n\n티리온이 훔치려고 시도한 이후 다시는 그림을 계속 걸어 놓을 수가 없었어요. 전 그림을 절대 찾을 수 없는 곳에 숨겼답니다.\n\n스트라솔름으로 가서 지금은 붉은십자군 성채가 된 곳 깊숙한 곳으로 가서 쌍둥이 달 그림을 찾으세요. 제 역작인 '가족과 사랑'이 드러날 때까지 그림을 조금씩 긁어보세요.\n\n성스러운 빛의 가호가 함께하기를.", progress = "그림은 어디 있나?", completion = "&lt;그림을 보고 쓰러지는 티리온&gt;\n\n&lt;제정신이 아닌듯 흐느끼기 시작하는 티리온&gt;", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5861] = {title = "미란다 찾기", objective = "역병지대의 남쪽에 위치한 우서 경의 무덤으로 가서 티리온의 선물을 노파 미란다에게 보여줘야 합니다.", description = "지금까지 내가 요청한 일을 모두 잘 해주었네. 자네의 구원 임무는 이제 한 단계만이 남아 있네.\n\n자네가 수집한 물건을 탤런에게 전해 주게. 불행하게도 탤런과 탤런의 붉은십자군이 자네를 보면 공격할 것이네. 내 말을 전하려면 모습을 바꾸는 수밖에 없네.\n\n남쪽에서 우서 경의 무덤을 찾을 수 있네. 내 오랜, 믿을 만한, 절친한 친구 미란다가 지금 거기에 살고 있으니 그녀를 찾게나. 미란다에게 이 물건을 보여 주면 자네를 도와줄 걸세.", progress = "내 이런 날이 올 줄 알았지.", completion = "나는 티리온이 마르덴홀드의 영주이었을 때 그가 가장 신뢰하던 조언자였지. 나는 은빛성기사단이 통과시킨 결정을 솔직하게 반대했고 무례하다는 죄로 추방당했다네.\n\n티리온의 일생에서 그때처럼 가슴 아파하고 좌절했던 시기도 많지 않았지. 폴드링가의 잘못을 바로 잡아줄 준비는 되었나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5862] = {title = "붉은십자군의 핑계", objective = "붉은십자군 환영을 얻어 노파 미란다와 대화해야 합니다. 붉은십자군 환영을 보유하고 있는 동안 하스글렌으로 가서 티리온의 선물을 대영주 탤런 폴드링에게 전해야 합니다.\n\n하스글렌은 북쪽에 있으며 탤런은 마르덴홀드 요새 내부에서 찾을 수 있을 겁니다.", description = "자네가 찾는 환영술사가 바로 나일세. 내가 환영을 만들어서 자네가 하스글렌에 들어가도록 해줄 수는 있지만 내 힘에도 한계가 있다는 걸 기억하게.\n\n여기에서 멀리 벗어나면 환영의 효과가 사라질 것이야... 마법을 유지하려면 엄청난 집중력과 힘이 소비되기 때문에 마법의 효과는 짧은 시간 동안만 유지되지.\n\n준비가 되면 다시 말하게.", progress = "자네 티르의 손 수도원의 증원군인가?", completion = "병사, 이건 뭐지?\n\n&lt;상자를 열고 내용물을 조사하는 탤런&gt;\n\n이...이럴 수가! 하지만 자네가 나에게 보여줬던 모든 것은...\n\n&lt;탤런은 한쪽 무릎을 꿇고 심장 박동이 빨라집니다. 이 도시에 격동의 시기가 시작되려고 합니다.&gt;", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[5863] = {title = "모래망치 주둔지", objective = "가젯잔에 있는 앤디 린이 모래망치일족 투사, 모래망치일족 집행자를 각각 10명씩 처치하고 파괴자 고르마로크를 처단하여 모래망치 주둔지를 없애 달라고 부탁했습니다.", description = "최근 대규모의 떠돌이 오우거들이 타나리스에 도착했어요. 여기서 남쪽에 있는 넓은 사막을 차지하고 주둔지를 세웠죠. 요새는 떠돌이 오우거 중 일부가 작은 무리를 지어서 사막을 돌아다니는데, 그들 중 일부가 폐허가 된 트롤의 유적지에 침입했습니다.\n\n모래망치 주둔지를 없애야만 해요! 이 오우거들이 세력을 키우도록 놔두면 안 됩니다.\n\n그들의 우두머리는 파괴자 고르마로크라고 하는데 제 생각에는 오우거들의 뿌리를 뽑으려면 이놈부터 죽여야 할 것 같아요.", progress = nil, completion = "&lt;name&gt;, 절 위해 이 일을 해주시다니 너무 기쁘군요! 도와주셔서 정말 감사합니다!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n마른열매 장갑융단나무 어깨보호대\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5881] = {title = "휴가 통지서", objective = "마그그랜이 불모의 땅 구름 승강장에 있는 그리쉬 롱러너에게 통지서를 전해달라고 부탁했습니다.", description = "위대한 호드의 군대는 아주 훌륭하게 유지되고 있네. 대전쟁 이후 우리는 다시 이곳 칼림도어에서 번영의 시기를 만들어 가고 있지.\n\n자네에게 부탁 하나 하겠네. 불모의 땅 남부에 있는 구름 승강장에서 경비 임무를 담당하고 있는 그리쉬 롱러너라는 친구가 있네. 그에게 이 통지서를 좀 갖다주게. 통지서의 내용은 그가 가족을 만날 수 있도록 그의 임무를 대신할 예비 전사를 보내겠다는 것일세. 휴가를 요청한 게 꽤 오래 전이니 이 소식을 들으면 무척 기뻐할 거야.", progress = "혹시 마그그랜 어스바인더님이 보내신 소식입니까?", completion = "정말 기쁜 소식이로군요. 정말 오랫동안 이 나무 기둥을 홀로 지키고 있었는데 이제 잠시나마 가족들과 시간을 보낼 수 있게 되었습니다. 야호!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5882] = {title = "사냥을 통한 고약 확보", objective = "이 세나리온 등불을 숲으로 지니고 가세요. 정의를 위해 타락한 짐승을 처치하고 오염된 영혼의 조각을 찾아오세요. 저는 그 조각을 갈아서 세나리온 식물 고약을 만드는 재료로 쓴답니다. 그 고약이면 오염된 식물들을 다시 건강하게 되살릴 수 있을 거예요.\n\n오염된 영혼의 조각을 가져다주면 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "이 세나리온 등불을 숲으로 지니고 가세요. 정의를 위해 타락한 짐승을 처치하고 오염된 영혼의 조각을 찾아오세요. 저는 그 조각을 갈아서 세나리온 식물 고약을 만드는 재료로 쓴답니다. 그 고약이면 오염된 식물들을 다시 건강하게 되살릴 수 있을 거예요.\n\n오염된 영혼의 조각을 가져다주면 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", completion = "훌륭해요. 여기 약속대로 세나리온 식물 고약을 드릴게요. 악령의 숲을 샅샅이 뒤져 오염된 식물들을 찾으세요! 발견하면 제가 드리는 고약을 사용해 정화해주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5883] = {title = "채광을 통한 고약 확보", objective = "악령의 숲에서 채광할 때 세나리온 등불을 들고 있으면 광맥을 오염시키는 황산을 볼 수 있어요. 저는 그 황산을 정화해 세나리온 식물 고약의 재료로 바꾸는 방법을 알고 있어요. 그 고약이면 숲의 오염된 식물을 정화할 수 있답니다.\n\n오염된 황산을 모아오면 그 대가로 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", description = nil, progress = "악령의 숲에서 채광할 때 세나리온 등불을 들고 있으면 광맥을 오염시키는 황산을 볼 수 있어요. 저는 그 황산을 정화해 세나리온 식물 고약의 재료로 바꾸는 방법을 알고 있어요. 그 고약이면 숲의 오염된 식물을 정화할 수 있답니다.\n\n오염된 황산을 모아오면 그 대가로 제가 미리 준비해둔 세나리온 식물 고약을 드리겠어요.", completion = "좋아요. 여기 약속대로 세나리온 식물 고약을 드릴게요. 악령의 숲에서 채광을 하시다가 황산을 더 찾게 되면 갖고 계시다가 꼭 가져오세요! 많이 찾아올수록 고약을 더 많이 만들 수 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5884] = {title = "약초채집을 통한 고약 확보", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5885] = {title = "무두질을 통한 고약 확보", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5886] = {title = "마력 추출을 통한 고약 확보", objective = "마력이 풀린 물건의 힘은 그 안에서 만들어지는 정수로 느낄 수 있지요. 저는 마법부여사들이 사용하는 천연 정수를 적절히 변형해 세나리온 식물 고약으로 만드는 방법을 알아냈어요. 이때는 세나리온 등불이 필요하지 않아요. 마력이 추출된 하급 황천의 정수가 흘러나오는 물건이면 되죠.\n\n그 하급 황천의 정수만 있으면 정말 좋을 텐데! 굉장히 강력해서 조금만 구해도 큰 일을 해낼 수가 있거든요. 가져오시면 그 보답으로 세나리온 식물 고약을 나눠드리죠.", description = nil, progress = "마력이 풀린 물건의 힘은 그 안에서 만들어지는 정수로 느낄 수 있지요. 저는 마법부여사들이 사용하는 천연 정수를 적절히 변형해 세나리온 식물 고약으로 만드는 방법을 알아냈어요. 이때는 세나리온 등불이 필요하지 않아요. 마력이 추출된 하급 황천의 정수가 흘러나오는 물건이면 되죠.\n\n그 하급 황천의 정수만 있으면 정말 좋을 텐데! 굉장히 강력해서 조금만 구해도 큰 일을 해낼 수가 있거든요. 가져오시면 그 보답으로 세나리온 식물 고약을 나눠드리죠.", completion = "여기 세나리온 식물 고약을 조금 드리죠. 하급 황천의 정수가 하나만 있어도 이 정도 분량은 충분히 만들고도 남아요. 날카로운 칼을 무딘 쟁기로 만들어 버리는 데 그 정수만큼 강력한 물건도 없지요. 세나리온 식물 고약이 더 필요하면 언제든지 다시 찾아오세요!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5887] = {title = "사냥을 통한 고약 확보", objective = "이 세나리온 등불을 들고 숲으로 가세요. 정의를 위해 타락한 짐승을 처치하고 오염된 영혼의 조각을 찾아오세요. 그 조각을 갈아서 세나리온 식물 고약을 만들 수 있답니다. 그 고약이면 오염된 식물을 다시 건강하게 정화할 수 있을 거예요.\n\n오염된 영혼의 조각을 가져다주면 제가 미리 준비해둔 세나리온 식물 고약을 나눠드리겠어요.", description = nil, progress = "이 세나리온 등불을 들고 숲으로 가세요. 정의를 위해 타락한 짐승을 처치하고 오염된 영혼의 조각을 찾아오세요. 그 조각을 갈아서 세나리온 식물 고약을 만들 수 있답니다. 그 고약이면 오염된 식물을 다시 건강하게 정화할 수 있을 거예요.\n\n오염된 영혼의 조각을 가져다주면 제가 미리 준비해둔 세나리온 식물 고약을 나눠드리겠어요.", completion = "훌륭해요. 여기 약속대로 세나리온 식물 고약을 드릴게요. &lt;name&gt;! 악령의 숲을 샅샅이 뒤져 오염된 식물을 찾으세요! 발견하는 즉시 제가 드린 고약을 사용해 정화해주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5888] = {title = "채광을 통한 고약 확보", objective = "악령의 숲에서 채광할 때 세나리온 등불을 들고 있으면 광맥을 오염시키는 황산을 볼 수 있어요. 저는 그 황산을 정화해 세나리온 식물 고약의 재료로 바꾸는 방법을 알고 있어요. 숲에서 오염된 식물을 찾으면 이 고약으로 정화할 수 있답니다.\n\n오염된 황산을 모아오면 그 대가로 제가 미리 준비해둔 세나리온 식물 고약을 나눠드리겠어요.", description = nil, progress = "악령의 숲에서 채광할 때 세나리온 등불을 들고 있으면 광맥을 오염시키는 황산을 볼 수 있어요. 저는 그 황산을 정화해 세나리온 식물 고약의 재료로 바꾸는 방법을 알고 있어요. 숲에서 오염된 식물을 찾으면 이 고약으로 정화할 수 있답니다.\n\n오염된 황산을 모아오면 그 대가로 제가 미리 준비해둔 세나리온 식물 고약을 나눠드리겠어요.", completion = "훌륭해요. 여기 약속대로 세나리온 식물 고약을 드릴게요. 악령의 숲에 있는 채광을 하다가 황산을 더 찾게 되면 가지고 계셨다가 제게 꼭 가져오세요! 많이 찾아올수록 고약을 더 많이 만들어드릴 수 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5889] = {title = "약초채집을 통한 고약 확보", objective = "숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있소. 그 식물은 악령의 숲이 타락해서 생긴 부산물이오. 난 이곳에서 일하다가 지옥덩굴을 정화용 시약으로 만드는 방법을 알게 되었소. 지금 그 약은 세나리온 식물 고약이라는 이름으로 불리고 있지.\n\n세나리온 등불을 들고 악령의 숲에서 약초를 모으다 보면, 지옥덩굴을 찾게 될 거요. 충분히 모아서 가지고 오면 미리 만들어둔 세나리온 식물 고약을 나눠드리겠소이다.", description = nil, progress = "숙련된 약초 채집사가 세나리온 등불을 지니고 있으면 지옥덩굴을 찾아낼 수 있소. 그 식물은 악령의 숲이 타락해서 생긴 부산물이오. 난 이곳에서 일하다가 지옥덩굴을 정화용 시약으로 만드는 방법을 알게 되었소. 지금 그 약은 세나리온 식물 고약이라는 이름으로 불리고 있지.\n\n세나리온 등불을 들고 악령의 숲에서 약초를 모으다 보면, 지옥덩굴을 찾게 될 거요. 충분히 모아서 가지고 오면 미리 만들어둔 세나리온 식물 고약을 나눠드리겠소이다.", completion = "&lt;name&gt;, 아주 잘하셨소. 당신이 모아 온 이 지옥덩굴을 정화시켜야겠군. 악령의 숲을 원래대로 되돌려 놓는데 조금이나마 도움이 될 거요. 자, 여기 약속대로 세나리온 식물 고약을 드리지... 어서 가지고 숲으로 가보시오. 타락의 위험에 처한 이 땅은 한 명이라도 많은 &lt;race&gt;의 도움을 절실히 기다리고 있으니까!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5890] = {title = "무두질을 통한 고약 확보", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5891] = {title = "마력 추출을 통한 고약 확보", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 식물 고약"},
[5892] = {title = "깊은무쇠 광산 보급품", objective = "던 발다르에 있는 얼라이언스 병참장교에게 깊은무쇠 광산 보급품 10개를 가져가야 합니다.", description = "우리는 싸움이 시작되기 전, 던 발다르에서 쓸 보급품을 깊은무쇠 광산에 비축해 두었소. 광산 경비를 설 만큼 병력에 여유가 있을 때는 광산에 트로그들이 출현해도 별 문제가 되지 않았지만, 지금은 호드와 싸우고 있다 보니 깊은무쇠 광산을 계속 관리할 수가 없소이다.\n\n깊은무쇠 광산에 있는 보급품이 필요하오. 광산에 들어가 보급품을 내게 가져다 주시오.", progress = "보급품은 가져왔소? 아무리 많아도 부족할 지경이라오!", completion = "수고했소! 이 보급품들은 유용하게 잘 쓰도록 하겠소이다. 고맙소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5893] = {title = "얼음이빨 광산 보급품", objective = "서리늑대 요새에 있는 서리늑대 병참장교에게 얼음이빨 광산 보급품 10개를 가져가야 합니다.", description = "여기서 북쪽에 있는 얼음이빨 광산은 한때 보급품 창고로 그만인 장소였소. 지금은 스톰파이크 놈들과의 싸움이 점점 더 치열해져 가다 보니 군대를 광산에 보내 보급품을 지킬 형편은 아니오. 그래서 광산이 종종 얼라이언스나 지하 생물들의 손아귀에 넘어가곤 하지.\n\n하지만 우린 여전히 그 보급품이 필요하오. <name>! 얼음이빨 광산으로 가서 보급품을 좀 가져와 주시오. 적들을 항상 조심하시오. 그곳에서는 전세가 갑자기 뒤집히곤 하니까...", progress = "얼음이빨 광산에는 다녀왔소, <name>? 내가 부탁한 보급품은 가져온 거요?", completion = "가져왔군. 잘했소, &lt;name&gt;! 그 어두컴컴한 광산 안에 오랫동안 내버려둬서 곰팡이가 좀 슬긴 했지만 그래도 쓸 수는 있을 거요.\n\n고맙소, &lt;name&gt;. 당신이 해 준 일은 우리 부대의 정비를 위해 꼭 필요한 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5901] = {title = "역병 퍼뜨리기", objective = "동부 역병지대의 흰개미집으로 가서 빈 흰개미 병을 사용하십시오. 역병지대 흰개미 100마리를 모아서 티리스팔 숲의 보루에 있는 미키 레빈에게 돌아가야 합니다.", description = "전 붉은십자군이 애지중지하는 벌목지를 빼앗아 고통과 분쟁을 안겨주고 싶습니다. 벌목지라는 자원을 잃으면 그들은 마을을 지키고 재건하느라 나름대로 엄청난 손해를 보게 되겠지요. 저를 도와주시겠습니까?\n\n먼저 이 병을 동부 역병지대에 있는 역병의 숲으로 가져가십시오. 숲속에서 흰개미집을 찾아서 흰개미를 이 병에 충분히 모아서 담아와 주시기 바랍니다.", progress = "벌써 흰개미를 모아오신 겁니까? 똑똑하신 <class>님께는 쉬운 일이었겠지요.\n\n흰개미도 충분하니 다시는 어느 누구도 절대 벌목지를 사용하지 못하게 할 수 있을 겁니다!", completion = "바로 이겁니다. 고맙습니다.\n\n준비가 끝났으면 다음 단계로 넘어가도록 하시지요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5902] = {title = "역병 퍼뜨리기", objective = "서부 역병지대의 북마루 벌목지 중앙에 적당한 장소를 찾아 역병지대 흰개미 통을 놓아야 합니다.\n\n제공된 아이템: \n", description = "이제 흰개미들을 확보했으니 이 흰개미 통을 하스글렌 남쪽의 북마루 벌목지로 가져가세요. 벌목지는 마을로 올라가는 길 서쪽에 있습니다.\n\n그곳에 도착하거든 이 통을 벌목지 중앙에 상자 위나 적당한 물건 위에 올려놓고 열도록 하십시오.\n\n통을 열고 나면 흰개미들이 알아서 할 것입니다. 일을 마치고 이곳으로 돌아오시면 저를 도와주신 대가로 보상을 해 드리도록 하겠습니다.", progress = nil, completion = "통을 상자 위에 놓자 흰개미들이 안절부절못하고 통 안을 돌아다닙니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5903] = {title = "역병 퍼뜨리기", objective = "동부 역병지대에 있는 흰개미집으로 가서 빈 흰개미 병을 사용해야 합니다. 역병지대 흰개미 100마리를 모아 서부 역병지대의 서리바람 야영지에 있는 너대니얼 두마에게 돌아가야 합니다.", description = "난 혼자 힘으로 붉은십자군을 몰아내려 했지만 역부족이었소. 그래서 차라리 그들을 혼내 주기로 결심했소.\n\n당신이 도와주면 그 벌목지에 전대미문의 가장 끔찍한 흰개미를 퍼뜨릴 생각이오.\n\n한때 번성했던 스트라솔름 근처 역병의 숲에 가면 역병과 스컬지에 감염된 채 살아 남은 흰개미가 있소. 그들의 집을 찾아 이 병에 담아 오면 붉은십자군들 사이에 풀어놓을 준비를 할 수 있을 것이오.", progress = "흰개미집을 찾았소? 역병의 숲에 흰개미집이 있다고 하더군.", completion = "바로 이거요. 고맙소. 어디 보자... 아주 우글우글하군. 붉은십자군에게 좀 미안하긴 하지만 그들이 벌목지를 차지해선 안 되는 거였소, 안 그렇소?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5904] = {title = "역병 퍼뜨리기", objective = "서부 역병지대의 북마루 벌목지 중앙에 적당한 장소를 찾아 역병지대 흰개미 통을 놓아야 합니다.\n\n제공된 아이템: \n", description = "이제 흰개미들을 확보했으니 이 흰개미 통을 하스글렌 남쪽의 북마루 벌목지로 가져가시오. 벌목지는 마을로 올라가는 길 서쪽에 있소이다.\n\n그곳에 도착하면 벌목지 중앙에 흰개미 통을 가져가서 상자나 적당한 물건 위에 올려놓고 열도록 하시오. 그 다음부터는 흰개미들이 알아서 붉은 십자군들의 벌목지를 망쳐 놓을 것이오.", progress = nil, completion = "통을 상자 위에 놓자 흰개미들이 안절부절못하고 통 안을 돌아다닙니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5921] = {title = "달숲", objective = "\"순간이동: 달숲\" 주문을 이용하여 달숲으로 이동하십시오. 도착하면 나이트헤이븐의 덴드리트 스타블레이즈와 대화해야 합니다.", description = "현재 대드루이드 스테그헬름과 달숲을 지키는 수호자 레물로스 사이에는 긴장감이 감돌고 있지만 신성한 달숲에 있는 모든 드루이드는 언제나 그대를 환영합니다. 발톱을 사용하는 법을 배웠으니 이제 그곳으로 이동할 수 있는 주문을 가르쳐 드리겠어요. 달숲으로부터 지식과 위안을 구하고자 할 때면 언제나 이 주문을 사용하시기 바랍니다.\n\n이제 시험 삼아 달숲으로 이동하여 나이트헤이븐의 덴드리트 스타블레이즈와 그대의 진로에 대해 얘기를 나눠보세요. 젊은 드루이드여! 행운이 있기를!", progress = nil, completion = "\"드디어, 드디어 시작이군요. 세나리우스... 아버지시여...\"\n\n덴드리트가 머리 위 허공에 대고 어떤 동작을 취합니다. 너무 빨라서 육안으로는 잘 보이지 않습니다. 잠시 후... 덴드리트의 머리 위로 힘의 오라가 희미하게 드리워집니다.\n\n그대는 자연의 통찰력을 얻어야 합니다. 그 중 가장 먼저 곰의 통찰력을 손에 얻어야 합니다. 그대에게 &lt;class&gt;가 반드시 가져야 할 힘에 대해 알려드리겠습니다. 그대는 앞으로 이러한 능력을 받아들이고 전파해야 합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5922] = {title = "달의 숲", objective = "\"순간이동: 달의 숲\" 주문을 이용하여 달의 숲으로 이동해야 합니다. 달의 숲에 도착하면 나이트헤이븐의 덴드리트 스타블레이즈와 대화해야 합니다.", description = "타우렌, 나이트 엘프와 마찬가지로 신성한 땅 달의 숲에 오는 모든 드루이드를 환영하네. 달의 숲을 지키는 수호자 로물로스가 그곳에 은둔한 모든 드루이드를 감독하지. 발톱을 사용하는 법을 배웠으니 이제 그곳으로 이동할 수 있는 주문을 가르쳐 주겠네. 달의 숲으로부터 지식과 위안을 구할 때마다 이 주문을 걸어 보게.\n\n처음에 배운 내용대로 달의 숲으로 이동하여 나이트헤이븐의 덴드리트 스타블레이즈와 자네의 진로에 대해 대화해 보게. 젊은 드루이드여! 행운을 비네!", progress = nil, completion = "\"드디어, 드디어 시작이군요. 내 아버지, 세나리우스시여.\"\n\n덴드리트가 머리 위 허공에 대고 보이지 않을 만큼 재빠른 동작을 취합니다. 덴드리트 머리 위로 힘의 오라가 약하게 드리워집니다.\n\n\"그대는 자연의 통찰력 중 먼저 곰의 통찰력을 지녀야 합니다. 그대에게 &lt;class&gt;가 가져야 할 통찰력에 대해 알려드릴테니 그대는 이제부터 영원히 이 능력을 보유하고 전파해야 합니다!\"", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5923] = {title = "부름에 응하기", objective = "다르나서스 세나리온 자치령에 있는 마스렌길 베어워커와 대화해야 합니다.", description = "잠시 그대의 갈 길을 막게 됨에 용서를 구합니다.\n\n마스렌길 베어워커가 그대와 이야기를 나누고자 합니다. 그대는 드루이드로서 새로운 훈련을 받아야 할 때인 것 같군요. 그가 개인적으로 그대를 가르칠 것입니다. 마스렌길은 대드루이드의 직속 보좌관으로서 텔드랏실에서 가장 현명하고 존경받는 드루이드 중 한 분이십니다.\n\n다르나서스의 세나리온 자치령에 있는 판드랄 스테그헬께서 거처하시는 나무 2층에 계시니 찾아가 보십시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5924] = {title = "부름에 응하기", objective = "다르나서스 세나리온 자치령에 있는 마스렌길 베어워커와 대화해야 합니다.", description = "실례합니다, 친구여...\n\n마스렌길 베어워커님께서 그대와 이야기를 나누고자 하십니다. 그대는 드루이드로서 이제 새로운 생물을 상대로 훈련을 받아야 할 때인 것 같군요. 그분께서 그대를 개인적으로 지도해 주실 겁니다. 마스렌길님은 대드루이드님의 직속 보좌관이시며 텔드랏실에서 가장 현명하고 존경받는 드루이드 중 한 분이십니다.\n\n그분은 다르나서스의 세나리온 자치령에 있는 판드랄 스테그헬름의 나무 2층에 계십니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5925] = {title = "부름에 응하기", objective = "다르나서스 세나리온 자치령에 있는 마스렌길 베어워커와 대화해야 합니다.", description = "잠시 그대의 가는 길을 멈추게 됨을 양해해 주시오.\n\n마스렌길 베어워커께서 그대에게 하실 말씀이 있다고 합니다. 이제 그대는 드루이드로서 새로운 생명체들의 힘을 얻는 것에 대해 훈련을 받아야 할 때인 것 같소이다. 그분께서 그대를 직접 가르치실 겁니다. 마스렌길은 대드루이드의 보좌관이며 텔드랏실에서 가장 현명하고 존경받는 드루이드 중 한 분이시오.\n\n다르나서스 세나리온 자치령으로 가보시오. 판드랄 스테그헬름께서 거처하시는 나무 2층에 계시니 찾아가서 조언을 구하시오.", progress = nil, completion = "젊은 &lt;class&gt;여! 자신의 길을 충실히 따르고 있는 그대를 만나니 기쁘기 그지없군요. 그대는 이제 더 큰 세상을 향해 한걸음 나아가야 할 때예요.\n\n우리 세나리온의 후예는 모두 가슴 속에 자연을 위해 봉사하라는 부름을 간직하고 있습니다. 자연의 동식물은 우리가 책임져야 할 친구들이에요. 우리는 그들을 위해 자연의 균형을 수호하는 데 목숨을 바칠 준비를 하고 있어야 합니다. 그것은 우리 자신을 위한 길이기도 하고요. 세상에 첫 발을 내딛는 그대는 우선 곰의 육체와 정신의 힘에 대해 배워야 해요.\n\n자, 마음의 준비를 하세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5926] = {title = "부름에 응하기", objective = "썬더 블러프의 장로의 봉우리에 있는 투락 룬토템과 대화해야 합니다.", description = "실례합니다, 손님.\n\n투락 룬토템님께서 당신과 이야기를 나누고자 하십니다. 당신은 드루이드로서 이제 새로운 생물을 상대로 훈련을 받아야 할 때인 것 같습니다. 투락님께서 당신을 개인적으로 지도해 주실 겁니다. 투락님은 대드루이드의 보좌관이시며 현명하고 존경받는 드루이드로 알려져 있답니다. 그분께서 당신을 잘 지도해 주실 겁니다.\n\n그분은 썬더 블러프 장로의 봉우리에 있는 세나리온 의회 주 천막에 계십니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5927] = {title = "부름에 응하기", objective = "썬더 블러프 장로의 봉우리에 있는 투락 룬토템과 대화해야 합니다.", description = "잠시 손님께 드릴 말씀이 있습니다...\n\n투락 룬토템께서 당신과 하실 얘기가 있다고 하셨어요. 이제 당신은 드루이드로서 새로운 생명체의 힘을 받아들이는 것에 관한 훈련을 받아야 할 때인 것 같아요. 투락은 대드루이드의 보좌관이며 현명하고 존경받는 드루이드로 알려져 있습니다. 그런 분이 직접 당신을 지도해줄 거예요.\n\n썬더 블러프 장로의 봉우리로 가십시오. 세나리온 의회가 모이는 커다란 천막에 계시니 찾아가 지혜를 구하십시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5928] = {title = "부름에 응하기", objective = "썬더 블러프의 장로의 봉우리에 있는 투락 룬토템과 대화해야 합니다.", description = "실례합니다...\n\n투락 룬토템님께서 당신과 이야기를 나누겠다고 하시는군요. 당신은 드루이드로서 이제 새로운 삶에 대한 훈련을 받아야 할 때인 것 같습니다. 그분께서 당신을 개인적으로 지도하실 것입니다. 투락님께서는 대드루이드의 보좌관이시며 현명하고 존경받는 드루이드로 알려져 있습니다. 그 분이 당신을 잘 지도해 주실겁니다.\n\n그는 썬더 블러프 장로의 봉우리에 있는 세나리온 의회의 주 천막에 계십니다.", progress = nil, completion = "젊은 &lt;class&gt;여! 오늘 자신의 길을 충실히 따르고 있는 자네를 만나 기쁘기 그지없네. 자네는 이제 더 큰 세상을 향해 한 걸음 나아가야 할 때야.\n\n세나리온의 후예들은 가슴 속에 자연을 위해 봉사하라는 부름을 간직하고 있지. 동물과 식물은 우리가 책임져야 할 친구들일세. 우리는 우리 자신과 그들을 위해 균형을 수호하는 데 목숨을 바칠 것일세. 세상에 첫 발을 내딛는 자네는 우선 곰의 기술을 배우고 육체와 마음의 힘에 대해 배워야 하네.\n\n준비하게!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5929] = {title = "거대한 곰의 혼", objective = "달숲 북서쪽에 사는 거대한 곰의 혼을 찾아가 드루이드라면 반드시 알아야 할 곰의 본성에 대해 배워야 합니다. 임무를 완수하면 달숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈에게 돌아가십시오.", description = "달숲에서 북서쪽으로 거대한 곰의 혼이라는 현명하고 고귀한 존재가 거처하고 있습니다. 그는 모든 드루이드의 스승으로서 최초로 곰에 대한 진실을 전파한 존재입니다. 그 지역의 모든 드루이드가 그로부터 지혜를 구한다고 해도 과언은 아닙니다. 그대도 예외는 아닙니다.\n\n이제 거대한 곰의 혼을 찾아가 가르침을 얻으십시오. 그런 다음 여기 나이트헤이븐으로 돌아오십시오. 그때 그대가 위대한 곰의 가르침을 진정으로 이해했는지 보지요.", progress = "거대한 곰의 혼이 그대를 보내줄 때 돌아오십시오. 그의 축복을 받지 못하면 훈련을 계속할 수가 없습니다.", completion = "당신이 다가가자 덴드리트는 다시 한 번 머리 위 허공에 대고 재빨리 동작을 취합니다. 그의 머리 위에 힘의 오라가 또다시 드리워지자 살짝 미소를 짓습니다.\n\n\"젊은이여, 우리가 처음 만났을 때는 보이지 않던 지혜가 그대 안에서 느껴집니다. 나를 바라보는 그대의 눈 속에 힘과 지혜에 대한 열정이 엿보입니다. 그러나 이 열정은 집중되어 있지 않습니다. 이제 힘을 집중하고 곰의 본성을 활용하는 방법을 배워야 합니다.\"", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5930] = {title = "거대한 곰의 혼", objective = "달숲 북서쪽에 사는 거대한 곰의 혼을 찾아가 드루이드라면 반드시 알아야 할 곰의 본성에 대해 배워야 합니다. 임무를 완수하면 달숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈에게 돌아가십시오.", description = "달숲에서 북서쪽으로 가면 거대한 곰의 혼이라는 현명하고 고귀한 존재가 거처하고 있습니다. 그는 모든 드루이드의 스승으로서 최초로 곰에 대한 진리를 얻게 해주었습니다. 그 지역의 모든 드루이드가 그로부터 지혜를 구하고 있다고 해도 과언은 아닙니다. 그대도 예외는 아니겠지요.\n\n이제 거대한 곰의 혼을 찾아가 가르침을 얻으십시오. 그런 다음 여기 나이트헤이븐으로 돌아오십시오. 그때 그대가 가르침을 진정으로 이해했는지 보지요.", progress = nil, completion = "당신이 다가가자 덴드리트가 다시 한 번 머리 위 허공에 대고 재빠른 동작을 취합니다. 그의 머리 위에 힘의 오라가 또다시 드리워지자 살짝 미소를 짓습니다.\n\n\"젊은이, 우리가 처음 만났을 때 보이지 않던 지혜가 그대 안에서 느껴지는군요. 나를 바라보는 그대의 눈 속에 힘과 지혜에 대한 열정이 엿보입니다. 그러나 이 열정은 집중되어 있지 않습니다. 이제 그 힘을 집중하고 곰의 본성을 활용하는 방법을 배워야 합니다.\"", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5931] = {title = "다르나서스로 돌아가기", objective = "다르나서스로 돌아가 세나리온 자치령에 있는 마스렌길 베어워커와 대화해야 합니다.", description = "이제 헤어질 시간이군요. 그대를 제게 보내신 분에게 돌아가 지금까지 배운 실력을 발휘하십시오. 마스렌길 베어워커는 자연과 조화가 사라진 위태로운 곳에서 살고 계시지만, 진정으로 자연과 조화를 이루고자 노력하시는 분입니다. 그의 가르침을 귀담아들으십시오. 첫 번째 수업을 마치면 자연의 수호자로서 그대의 임무를 본격적으로 시작할 수 있을 것입니다.\n\n어서 가보십시오! 우리는 다시 만나게 될 겁니다.", progress = nil, completion = "&lt;name&gt;, 다시 만나 반가워요. 그대와 거대한 곰의 혼의 첫 만남은 모든 &lt;class&gt;가 야수 전투를 배우기 시작할 때와 같다는 생각이 드는군요. 조금은 쩔쩔매기도 하지만, 아주 집중하게 되지요... 이제 제가 나서야 할 시간이로군요.\n\n아제로스가 천상에 존재한 때에도 거대한 곰의 혼은 아제로스의 일부였어요. 그의 지혜와 능력에 의지해 우리의 궁극적인 목표를 이루어야 해요. 이제 그것을 위한 첫 번째 시험을 시작할 시간이에요. 지금부터 제가 하는 말을 잘 들으세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5932] = {title = "썬더 블러프로 돌아가기", objective = "썬더 블러프로 돌아가 장로의 봉우리에 있는 투락 룬토템과 대화해야 합니다.", description = "이제 우리는 헤어질 시간입니다. 그대를 제게 보내신 분에게 돌아가 지금까지 배운 실력을 발휘하십시오. 흔히들 세나리우스의 가르침을 완전히 이해하기에 타우렌 종족은 좀 성숙하지 못하다고 하지만 투락 룬토템은 자연과 조화를 이루며 살아갑니다. 그의 가르침을 귀담아 들으면 첫 번째 수업이 끝나게 되지요. 그때부터 자연의 조화를 지키는 수호자로서 그대의 임무를 본격적으로 시작할 수 있을 것입니다.\n\n어서 가보십시오, 젊은이! 우리는 다시 만나게 될 겁니다.", progress = nil, completion = "다시 만나 반갑네, &lt;name&gt;. 거대한 곰의 혼과 첫 대면한 자네의 모습에서 모든 &lt;class&gt;가 야수 전투의 걸음마를 배우기 시작할 때가 느껴지는군. 약간 쩔쩔매면서도 아주 집중해서 배우지. 이제 내가 나서야 할 시간이야.\n\n아제로스가 천상에 존재한 때에도 거대한 곰의 혼은 아제로스의 일부였지. &lt;race&gt;은 그의 가르침을 경청하여 우리의 궁극적인 목적을 이루기 위해 노력하고 있네. 이제 그 목적을 이루기 위한 첫 번째 시험을 시작할 시간이야. 내 말을 잘 듣게.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5941] = {title = "크로미에게 돌아가기", objective = "안돌할의 크로미에게 유물 자루를 가져가야 합니다.", description = "다로우샤이어 전투의 유물을 많이 모았구려. 그대가 돌아올 때마다 유물은 늘어나고 내 마음은 고향에 대한 그리움과 그곳을 파멸에서 구해내겠다는 생각으로 걷잡을 수가 없소.\n\n나에게는 불가능한 일이지만 안돌할에 사는 놀라운 능력을 지닌 노움인 크로미는 그 일이 가능하다고 말했다오. 그리고 크로미가 말하길 당신이 다로우샤이어를 구할 수 있다고 했소이다!\n\n당신이 유물을 모아 그녀에게 갖다 주어야 하오. 안돌할의 폐허가 된 여관에서 그녀가 당신을 기다리고 있으니 어서 가 보시오.", progress = "나는 당신의 친구인 카를린과 서로 소식을 전하고 있답니다. 그는 자기 고향이 몰락해 버린 일을 무척이나 괴로워하고 있지만 당신을 높이 평가하며 당신이야말로 모든 것을 바로잡을 수 있는 능력이 있다고 하더군요.\n\n아, 이야기가 옆길로 빠졌군요. 부탁한 유물은 갖고 있나요?", completion = "아, 가져왔군요. 유물이 모이면 다로우샤이어의 영혼들을 되살릴 수 있는 강력한 마법을 쓸 수 있어요.\n\n이 마법과 약간의 행운만 있다면 우린 조셉 레드패스를 구할 수 있어요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5942] = {title = "숨겨진 보물", objective = "조셉의 상자가 있는 곳으로 조셉의 열쇠를 가져가야 합니다.", description = "아빠가 <name>님께 이 열쇠를 드리랬어요. 아빠 말씀으로는 집 뒤쪽에 있는 상자를 여는 열쇠래요.\n\n아, 그리고 고맙다는 말도 전해 드리래요. 아빠 부탁을 들어주셨어요? 제 인형을 찾아주셨다고 아빠한테 얘기하셨나요?\n\n아참, 열쇠 여기 있어요. 그리고 정말 정말 고맙습니다. <name>님은 정말 좋은 분이세요!", progress = "낡고 더러운 상자입니다.", completion = "열쇠가 자물쇠에 맞아 상자가 열립니다...", rewards = "다음과 같은 것들을 받습니다:\n\n보호의 반지광명의 부적법사사냥꾼의 후예"},
[5943] = {title = "기젤톤 대상단", objective = "만노로크 소굴을 지나가는 기젤톤 대상단을 호위하고 스크래블스크류의 야영지에 있는 스미드와 대화하여 보상을 받아야 합니다.", description = "당신은 꽤나 실력 있는 <race>인거 같군요. 혹시 돈 좀 벌어 볼 생각 없나요? 코르크와 나는 돈을 많이 벌려고 이 짐마차 일을 시작했는데, 돈 한푼 벌기가 이렇게 위험할 줄은 정말 몰랐어요!\n\n저기 앞에 만노로크 소굴이 있어요. 보통 때라면 악마들이 우릴 그냥 무시하는데, 이번에는 뭔가가 코도들을 놀라게 했나 봐요. 만노로크 소굴을 무사히 지나갈 수 있도록 호위를 해 주시면 사례를 하도록 하죠. 무사히 지나간 후에 스크래블스크류의 야영지에 있는 우리 동업자, 스미드에게서 보상을 받도록 하세요.", progress = nil, completion = "기젤톤 대상단을 보호하는 데 이렇게나 많은 돈을 투자하는 게 돈벌이에 득이 되는지 잘 모르겠단 말이야. 코르크와 리거는 일주일에 1골드 밖에 못 벌거든. 하지만 계속해서 내 코도를 빌린 돈을 지급한다면야 녀석들이 사업을 어떻게 운영하든 내 알 바 아니긴 해.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n쇼티 나팔총코도 낙인기징박힌 고리 방패\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5944] = {title = "탤런의 꿈", objective = "탤런 폴드링을 하스글렌 밖으로 호위해야 합니다.", description = "나는 오랫동안 십자군 사령관의 앞잡이 역할을 해왔네. 붉은십자군에 대항해서 싸워야 할 이유는 없었지. 하지만 수십년 동안 아버지에 대한 기억, 그 소중한 추억이 지금까지 나를 살아 있게 만든 원동력이었다네.\n\n나는 꿈 속에서 아버지와 함께하는 꿈을 꾼다네. 아버지는 기사단에 입단하는 내 곁에 자랑스럽게 서 계시고 우리는 함께 스컬지 군대에 맞서 싸우지. 얼라이언스와 로데론의 명예를 드높이는 일에 동참하는 거야.\n\n이제 더 이상 꿈으로만 끝날 수는 없네.\n\n나를 아버지께 데려다 주게.", progress = nil, completion = "내 아들이 이 괴물들의 손에 죽다니... 절대 그냥 넘어가지 않을 것이야. 기사단이 다시 살아났다는 걸로 아들의 죽음을 애도하게.\n\n나는 이제 새로운 은빛 기사단 대영주로 일할 것이네.\n\n내가 과거에 소유했던 것들을 자네에게 주지. 자네가 해 준 일에 보답할 수 있는 것이니 내 고마움의 표시로 생각하고 받아 주게. 이 물건들은 수년간 내게 큰 도움이 되었지.\n\n살기 좋은 세상이 와서 지난 날의 힘겨웠던 전투가 추억이 되고 꿈이 이루어지면 다시 만나세나.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n폴드링의 징표화려한 아다만티움 흉갑빛나는 백금 전투망치망명의 외투폴드링의 인장\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[5961] = {title = "밴시 여왕의 용사", objective = "동부 역병지대의 마리스 농장에 살고 있는 나타노스 블라이트콜러와 대화해야 합니다.", description = "우리의 목적을 달성하기 위한 전투에 임하게 되어 너무나 기쁘군. 우리 포세이큰의 규모와 힘은 나날이 커지고 있다. 그대의 용기를 시험할 준비는 되어 있겠지?\n\n지금은 블라이트콜러로 알려진 나타노스도 내 용사 중 하나였지. 그처럼 헌신적이고 활력있는 용사는 찾아보기 어렵지.\n\n나타노스는 마리스 농장에 살고 있는데 폐허를 돌아다니며 타락한 스컬지와 얼라이언스를 만나는 대로 처치하기도 하니 동부 역병지대에서 그를 찾도록 하라.", progress = nil, completion = "어둠의 여왕께서는 자네가 여왕님의 용사를 만날 자격이 있는 녀석이라고 믿지 않으실 걸세. 자네 같은 친구는 여기서 내 사냥개한테 먹이 주는 일이 딱 맞아, 안 그런가? 일을 이런 식으로 망친 데에는 다른 이유가 있을 수 없지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[5981] = {title = "광란의 거인", objective = "리베른 프로스트윈드의 지시대로 서리망치거인 4명과 서리망치거인 수호자 4명을 없애야 합니다.", description = "약 4000년 전, 티란데 위스퍼윈드가 미친 거인들의 손아귀에서 눈호랑이의 여왕을 살려냈다네. 그때부터 눈호랑이들은 나이트 엘프의 동맹군이 되었네.\n\n눈호랑이를 위협했던 그 거인들이 아직도 먼 곳에서 살고 있다네. 서리망치거인이라고 불리는 그들은 남쪽에 있는 거대한 계곡에 살고 있네.\n\n눈호랑이에게 자네의 충성심을 증명해 보이게. 눈호랑이의 여왕, 샤이로탐의 이름으로 그 거인들을 해치우게.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[6001] = {title = "육체와 정신", objective = "아우버다인의 달빛야수 비석에 세나리온 달가루를 뿌려서 초승달발톱을 불러내야 합니다. 그런 다음 초승달발톱과 대면하여 그가 가진 육체와 정신의 힘을 얻어야 합니다.\n\n모든 일을 마치면 다르나서스에 있는 마스렌길 베어워커와 대화하십시오.", description = "아우버다인에서 동쪽으로 곧장 가면 달빛야수의 동굴이 여러 개 있어요. 그중 아우버다인에서 가장 가까운 동굴 안에는 달빛야수 비석이 있답니다. 그 비석에 세나리온 달가루를 뿌리면 비석을 수호하는 초승달발톱이 나타날 거예요. 초승달발톱에게는 그대에게 반드시 필요한 힘과 기술이 있어요.\n\n<name>, 그대는 그동안의 노고로 이 세나리온 달가루를 이용할 수 있는 자격을 얻었어요. 이제는 드루이드에게 필요한 육체와 정신의 힘을 소유할 때입니다!", progress = nil, completion = "&lt;name&gt;, 마침내 그대는 더 넓은 세계를 향해 한걸음 더 전진했군요! 그대에게서 거대한 곰의 혼의 가르침과 함께, 초승달발톱의 영혼이 가진 힘이 느껴져요.\n\n그 어떤 것도 그대의 앞길을 막지는 못할 거예요. 이제 그대에게 발톱의 &lt;class&gt;가 된다는 것이 어떤 의미인지 알려 드릴 때가 왔군요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n곰 변신\n\n다음과 같은 것들을 받습니다:\n\n"},
[6002] = {title = "육체와 정신", objective = "초승달발톱을 불러내려면 멀고어와 불모의 땅 사이에 있는 달빛야수 비석에 세나리온 달가루를 사용해야 합니다. 거기에서 초승달발톱과 대적하여 그가 가진 육체와 마음의 힘을 얻으십시오.\n\n임무를 마치면 썬더 블러프에 있는 투락 룬토템과 대화해야 합니다.", description = "불모의 땅에 있는 타우라조 서쪽 지역, 멀고어로 들어가기 직전에 달빛야수 비석이 있네. 달빛야수는 자연의 일부가 아닌 아주 특별한 종족이지. 비석을 지키는 초승달발톱은 세나리온 달가루를 받으면 자네 앞에 나타난다네. 초승달발톱 안에는 자네가 발톱 중 하나로 사용해야 하는 힘이 들어 있네.\n\n자네는 이 세나리온 달가루를 이용할 수 있는 권한을 얻었으니 드루이드에게 필요한 육체의 힘과 마음의 힘을 소유할 수 있다는 것도 보여주게나.", progress = nil, completion = "마침내 더 넓은 세상을 향해 한 걸음 나아갔군! 자네 안에 있는 거대한 곰의 혼의 가르침이 느껴지네. 그리고 초승달발톱이 지녔던 힘도 얻었음을 알 수 있네.\n\n이제 아무것도 자네의 앞길을 가로막지 못할 것이네. 그러면 발톱의 &lt;class&gt;가 된다는 것이 어떤 의미인지 알려주겠네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n곰 변신\n\n다음과 같은 것들을 받습니다:\n\n"},
[6004] = {title = "끝나지 않은 임무", objective = "붉은십자군 의무병 2명, 붉은십자군 사냥꾼 2명, 붉은십자군 마법사 2명, 붉은십자군 기사 2명을 처치하고 서부 역병지대에 있는 키르스타 딥섀도에게 돌아가야 합니다.", description = "저는 하스글렌의 수비력을 파악하고 이를 저하시키기 위해 파견된 정찰병입니다. 얼라이언스에는 그 작은 마을에 역사적 중요성 이상의 무언가가 있다고 느끼는 이들도 있더군요. 뭐가 그렇게 중요한지 알아내는 건 제 일이 아니지요. 어쨌거나 좀 쉬어야 일을 계속할 수 있겠네요.\n\n저를 좀 도와주신다면 보상은 충분히 하겠습니다. 이 지역 남쪽에 그들이 마련한 작은 보루 근처에 야영지가 있는데 거기서부터 시작하세요. 당신이 힘을 증명해 보인다면 저의 진짜 목적을 수행할 때 당신에게 도움을 청할지도 모르겠군요.", progress = nil, completion = "잘하셨어요. 이렇게 빨리 처치하다니 놀랍군요. 고맙습니다.\n\n이제 붉은십자군과 그들의 방식에 찬성하는 사람을 만나봐야겠군요. 저도 스톰윈드의 누구 못지 않게 빛의 신성함을 믿지만 그들은 자기들에게 충성하지 않으면 죄없는 사람이라도 죽여버린 답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6021] = {title = "추방자 잴다르", objective = "잴다르를 처치하고 그 증거로 머리카락을 희망의 빛 예배당에 있는 관리인 알렌에게 가져가야 합니다.", description = "역병지대에서 온갖 고생을 다 하고 있는데 도둑 걱정까지 해야 한다니 말이 됩니까? 그냥 도둑도 아니고 트롤 도둑입니다.\n\n게다가 평범한 트롤 도둑도 아니란 말입니다. 죽은 트롤이란 말입니다!\n\n추방자 잴다르라는 거대한 죽은 트롤이 그들을 이끌고 있는데 밤이 되면 이곳으로 와서 저 아래 구덩이에서 시체를 훔쳐다가 사악한 죽은 트롤의 은신처로 데려갑니다. 그들의 은신처는 서쪽의 지하 납골당에 있습니다.\n\n그리로 가서 잴다르를 해치우세요! 놈의 못된 짓거리에 신물이 납니다!", progress = "은신처를 찾았습니까? 잴다르는 처치했습니까?", completion = "놈을 잡았군요! 잘하셨습니다! 이제 놈의 부하들도 섣불리 행동하지 못할 겁니다, 하하!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6022] = {title = "이유 있는 살육", objective = "동쪽의 코린 삼거리로 가서 마을에 사는 스컬지를 해치워 10분 안에 살아있는 부패물 7개를 모으십시오. 막자 사발을 사용해서 살아있는 부패물을 갈아 응고된 부패물로 만들어야 합니다.", description = "자네 말이야... 나를 대신해서 누굴 좀 죽여 줘야겠어.\n\n가장 먼저 할 일은 내 사냥개한테 먹이를 주는 거야.\n\n이 막자 사발을 가지고 코린 삼거리로 가면 강력한 스컬지를 만나게 될 거야. 녀석을 해치워버려. 난 놈들의 시체에서 나온 살아있는 부패물이 필요해. 그 살아있는 부패물을 가져다가 막자에 갈아서 굳히는 거야. 그런 다음 응고된 부패물을 다시 이리로 가져오면 되는 거야.\n\n그리고 언데드의 살아있는 부패물이 살아 있는 시간은 길지 않으니까 잽싸게 해치우라고!", progress = "자네 울고 있나? 이 일이 너무 '지루하다면' 어둠의 여왕님께 돌아가서 내가 농장에서 학대하더라고 일러바치던가!\n\n당장 꺼져!", completion = "실망스럽군. 대신 자네를 먹이로 주고 싶었는데...\n\n&lt;한숨 짓는 나타노스&gt;\n\n그래도 개 먹이는 줬군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6023] = {title = "끝나지 않은 임무", objective = "사냥꾼 래들리와 기병 드루겐을 처치하고 서부 역병지대에 키르스타 딥섀도에게 돌아가야 합니다.", description = "저의 진짜 임무는 붉은십자군의 외부 병력을 약화시키고 하스글렌에 침투해 병력 규모를 파악하는 것이랍니다. 그러나 전 여전히 혼자이고 도움이 필요하니 다시 당신의 도움을 청해도 되겠지요? 발각되기 전 제가 수집한 정보에 따르면 십자군은 마을 외부에 사냥꾼 래들리와 기병 드루겐이라는 핵심 병력을 두고 있다고 합니다. 그들을 처치하면 일이 쉬워질 겁니다. 그들은 마을 밖 하스글렌 통로 근방에 있으니 그들을 처치하고 돌아와 주십시오.", progress = "벌써 그들을 찾았나요? 그 둘을 처치하면 저는 하스글렌에 침입해 붉은십자군의 동태를 자세히 살필 수 있어요. 당신이 도와주지 않으면 불가능한 일이니 래들리와 드루겐을 꼭 찾아주세요.", completion = "고맙습니다. 기대 이상으로 도움이 되었군요. 이곳의 공기가 제 의욕을 떨어뜨리는 것 같아요. 후... 피곤하군요. 이곳에 오래 있다간 더 지치겠어요.\n\n어떻게 하스글렌에 침입해서 붉은십자군의 규모를 보고해야 할지 잘 모르겠어요.\n\n하지만 이곳을 떠나기 전에 도와주신 데 대한 보답으로 이것을 드릴게요. 정말 고마웠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6024] = {title = "하메야의 탄원서", objective = "첩보원 하메야를 처치해야 합니다. 지하 납골당 뒤의 흙무더기에서 그의 열쇠를 사용하십시오.", description = "너무 늦기 전에 나를 죽이기 바란다.\n\n나는 하메야라고 한다. 줄마샤르로 가는 동안 나와 내 동행은 상한 고기를 먹었다. 그랬더니 모습이 변해버렸다. 우리는 감염된 것이다.\n\n줄마샤르로 가서 내 동족을 감염시키라는 리치의 명령이 들린다. 난 거부할 수가 없으며 내 의지가 모두 사라지기 전에 이 글을 남긴다.\n\n납골당 뒤의 마차 옆에 있는 흙무더기에 상자를 하나 묻었는데 내 열쇠가 있어야만 열린다. 열쇠는 내가 가지고 있다. 내 보물을 갖고 싶다면 나를 찾아와라.\n\n너무 늦기 전에 나를 죽이기 바란다.", progress = "여기에 묻힌 상자는 단단히 잠겨 있습니다.", completion = "하메야의 상자가 열렸습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n하메야의 척살검하메야의 망토"},
[6025] = {title = "끝나지 않은 임무", objective = "하스글렌에 들어가 마을이 잘 보이는 높은 지대를 찾아 붉은십자군 병력 규모를 파악한 다음 서부 역병지대에 있는 키르스타 딥섀도에게 돌아가야 합니다.", description = "예? 정말인가요? 알고 싶은 게 더 있으시다고요? 하지만 이미 많은 일을 해주셨는걸요. 제 대신 하스글렌에 들어가 달라는 부탁을 어떻게 할 수 있겠어요...\n\n정말 그렇게 해주실 건가요? 하스글렌은 하스글렌으로 가는 통로보다 훨씬 위험한 곳이에요. 전 당신을 보호해 드릴 수도 없고 어떤 일이 닥칠 것인지 알려드릴 수도 없답니다.\n\n당신이 정 도와주시겠다면 마을로 들어가 마을이 잘 보이는 높은 장소를 찾으세요. 그곳에서 그들의 숫자를 파악하여 저에게 알려 주세요. 정말 조심하셔야 합니다.", progress = nil, completion = "해내셨군요! 고맙습니다!\n\n저는 엘링에게 돌아가야겠어요. 곧장 스톰윈드로 돌아간다는 얘기에요. 자, 이 돈을 받으세요. 당신께 드릴 수 있는 최소한의 성의에요. 당신은 동족의 자랑입니다. 감사 드리며 행운을 빌어요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6026] = {title = "여러 가지 부탁", objective = "토륨 주괴 2개, 금마법막대 1개, 고폭탄 8개, 유동성 제동장치 8개를 스모키 라루에게 가져가야 합니다.\n\n해당 물건을 모으려면 대장장이와 기계공학 기술자를 찾아야 합니다.", description = "여기 은빛 여명회에서 나 스모키에게 그들을 대신해 파괴를 수행할 수 있는 권한을 좀 주었지. 나 스모키는 허수아비가 아닐세. 돈이 있는 곳에 나 스모키가 있다. 그게 나의 좌우명이지!\n\n자네가 앞장서 준다면 기꺼이 임무를 나누고 싶네. 이렇게 하세나. 내가 역병의 숲으로 가서 파괴해야 할 건물에 표시를 할 테니 자네는 폭탄 재료를 모으게. 일이 끝나면 여기서 다시 만나세. 알겠나?", progress = "나, 스모키를 믿게나. 자네는 반드시 합당한 보상을 받을 걸세. 은빛 여명회는 반드시 대가를 지불한다네.", completion = "절반은 지금 지급하고 절반은 일이 끝나면 지급하겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6027] = {title = "고대의 책", objective = "고대의 책을 손에 넣은 다음 에텔 레소르의 탑에 있는 아조레 알다모트에게 가져가야 합니다.", description = "내 자네를 믿고 뱀의 보석을 맡기겠네. 이곳에서 북서쪽 작은 섬인 라나즈자르 섬에 있는 뱀 석상의 손에 이 보석을 올려놓게. 그러면 고대의 책을 수호하는 자가 나타날 것일세. 그 책에는 수백 년 동안 지켜져 온 나가의 비밀이 담겨 있지. 그 책을 내게 가져오면 비늘로 뒤덮인 우리 적들에 대해 많은 것을 알게 될 것이야!", progress = "아, 자네! 또 보게 돼서 반갑군. 그래, 고대의 책은 가져왔는가?", completion = "오래전에 잃어 버렸던 고대의 책이로군! 이 책을 반드시 상급 의회에 전달하도록 하겠네. 오늘 큰 일을 해 주었군. 그에 대한 감사의 표시를 해야지. 영웅은 감사를 받아 마땅하니까 말이야!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n비단결 소매장식철판 어깨보호구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6028] = {title = "눈망루 마을 보고서", objective = "서부 역병지대, 서리바람 야영지에 있는 은빛장교 퓨어하트에게 눈망루 마을 보고서를 전달해야 합니다.", description = "그다지 중요하지는 않은 일은 아니지만 책임지고 날 도와줄 자를 찾고 있소. 난 은빛 여명회를 대표하여 이곳에서 눈망루 마을에 투자를 하고 있소. 지금 그 보고서를 은빛장교 퓨어하트에게 보내야 하오. 서부 역병지대 남쪽 변방에 있는 서리바람 야영지로 가면 만날 수 있지...\n\n아, 내가 조금만 더 용감했더라도... 그래, 어쩌면 당신에게는 좋은 기회라고 할 수 있지! 우리 상관의 눈에도 띄고 일거리도 좀 얻을 수 있을 거요!", progress = "<class>|1이여;여;, 어서 오세요. 은빛 여명회를 대신해서 당신이 이곳 서리바람 야영지에 머무르는 동안 숙소를 제공하겠어요. 그리고 일거리도 좀 주고 싶은데...", completion = "그레고르는 아주 부유한 자예요. 얼마 전부터 스팀휘들 무역회사와 거래하면서 고블린 협상 기술의 전문가가 되었지요. 원래 고블린은 지갑이 두둑한 자에게 늘 호의적이지만 외교 또한 중요하게 생각한답니다. 그래서 그들에겐 단골이 끊이지 않는 것이지요.\n\n어쨌거나 저희 은빛 여명회는 당신의 노력에 감사 드립니다. 부디 이걸 받아주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6029] = {title = "눈망루 마을 보고서", objective = "서부 역병지대 보루에 있는 은빛장교 가루쉬에게 눈망루 마을 보고서를 전달해야 합니다.", description = "그다지 중요하지는 않은 일은 아니지만 책임지고 날 도와줄 자를 찾고 있소. 난 은빛 여명회를 대표하여 이곳에서 눈망루 마을에 투자를 하고 있소. 지금 그 보고서를 보루에 있는 은빛장교 가루쉬에게 보내야 하오. 티리스팔 숲 동쪽에 있는 서부 역병지대 서쪽 변방으로 가면 찾을 수 있을 거요.\n\n아, 내가 조금만 더 용감했더라도... 그래, 어쩌면 당신에게는 좋은 기회라고 할 수 있지! 우리 상관의 눈에도 띄고 일거리도 좀 얻을 수 있을 거요!", progress = "<class>|1이여;여;, 어서 오게나. 은빛 여명회를 대신해서 자네가 이곳 보루에 머무르는 동안 숙소를 제공하겠네. 그리고 가치 있는 일을 위해 싸울 기회도 마련해 주겠어.", completion = "그레고르는 부유하지. 얼마 전부터 스팀휘들 무역회사와 거래하며 고블린 협상 기술의 전문가가 되었지. 원래 고블린은 지갑이 두둑한 자에게 늘 호의적이지만 외교의 중요성 또한 존중한다네. 그래서 그들에겐 단골이 끊이지 않는 것이지.\n\n어쨌거나 우리 은빛 여명회는 자네의 노고를 치하하는 바이네. 이걸 받게나. 감사의 선물일세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6030] = {title = "공작 니콜라스 즈바른호프", objective = "동부 역병지대 희망의 빛 예배당에 있는 공작 니콜라스 즈바른호프에게 \"영적인 대화에 대한 논문\"이라는 책을 전해야 합니다.", description = "엄브런스라는 저자가 은빛 여명회에 은둔의 영매라는 대단한 문학 작품을 주었소. 뭔가 잔뜩 쓰여 있는 엄청난 분량이었는데. 그렇게 많은 양은 태어나서 처음 봤소이다. 그런데 당최 읽을 수가 있어야 말이지...\n\n은빛 여명회의 가장 존경받는 지도자인 니콜라스 즈바른호프 공작께서는 외국어에 능통하시다오. 이걸 공작께 전해 주시겠소? 물론 보상을 하겠소. 공작께서는 지금 동부 역병지대 동쪽 끄트머리에 있는 희망의 빛 예배당에 계신다오.", progress = "이 어려운 시절에 성스러운 빛이 자네를 인도하기를! 무엇이 자네를 여기로 인도했는가? 어둠과 절망 속에 빛나는 희망의 등불을 찾으러 왔는가?", completion = "이건... 아주 특별한 책이로군. 이럴 때 \"특별하다\"라는 말은 \"내용이 매우 독특하고 창의적이며 계몽적이다\"라는 뜻일세. 좀 더 살펴보세...\n\n\"아니 이런!\" 제대로 된 정신 상태로 누가 이런 생각을 한단 말인가?\n\n일전에 그레고르가 엄브런스에 대해 말한 적이 있지. 가치가 전혀 없는 책은 아니로군. 내 최선을 다해 이 책을 번역해 보겠네. 그리고 이걸... 받게. 은빛 여명회의 호의일세. 여기 머무르는 동안 자네의 도움을 받을 일이 또 있을 것 같아서 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6031] = {title = "룬매듭", objective = "나무구렁 요새에 있는 메일로쉬에게 룬매듭 30개를 가져가야 합니다.", description = "나무구렁에서 사는 우리는 낯선 자들을 별로 좋아하지 않소. 그게 유리하니까. 하지만 거래에는 도움이 안 되더군.\n\n얼마 전 어느 나이트 엘프 친구가 나무구렁에 찾아왔었는데 룬매듭 망토를 걸치고 있었소. 룬매듭도 희귀한데 망토는 어찌나 멋지던지... 그걸 보고 내 동족들이 룬매듭 옷을 만들어 달라고 했소.\n\n룬매듭을 갖다주시겠소? 충분히 가져오시면 뭔가를 드리리다.", progress = "룬매듭은 가져오셨소? 동족들이 룬매듭으로 만든 옷을 달라고 아우성이라서 말이오.", completion = "아, 가져왔군. 정말 고급스러워!\n\n&lt;name&gt;, 고맙소. 당신은 우리의 진정한 친구요. 이걸 받으시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n암흑가죽 어깨갑옷강철조각 건틀릿\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6032] = {title = "신성한 옷감", objective = "나무구렁 요새에 있는 메일로쉬에게 달빛매듭 2개를 갖다주어야 합니다.", description = "우리 나무구렁일족은 룬매듭의 촉감도 좋아하지만 그다지 신성한 느낌은 없다오. 달빛매듭이야말로 진정 신비한 옷감이지.\n\n내게 달빛매듭을 좀 갖다주면 우리 일족에게 비밀로 내려온 옷 만드는 기술을 알려드리겠소.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n달빛매듭 장화\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n달빛매듭 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6041] = {title = "짜증나는 스모키의 노래", objective = "희망의 빛 예배당 북서쪽에 있는 역병의 숲으로 가십시오. 스모키의 특수혼합물을 건물 안에 부착하여, 폭파 표시가 있는 스컬지 건물 8개를 파괴해야 합니다. 스모키가 지구라트와 도살장에 징표를 남겼습니다.\n\n폭탄을 부착한 후에는 건물에서 나와 폭발 광경을 지켜 보세요.\n\n그건 그렇고 스모키의 특수혼합물은 다소 불안정합니다.", description = "자네가 재료를 모으는 동안 나는 부하들을 보내 우리가 파괴해야 할 스컬지 건물에 표시를 했네.\n\n자, 이렇게 하세나. 자네에게 특수혼합물 10개를 주겠네. 그걸 가지고 역병의 숲으로 가서 폭파 표시가 되어 있는 스컬지 건물 안에 부착하게.\n\n<손가락 마디를 꺾는 스모키>\n\n꽝! 식은 죽 먹기라니까, 하하!", progress = nil, completion = "자네 전보다 많이 까맣게 되었군그래. 모양새를 보니 고폭탄 때문에 까맣게 탄 게로군.\n\n&lt;껄껄 웃는 스모키&gt;\n\n어쨌든 잘했네! 여기 자네 몫의 전리품일세. 나머지 일부는 위로하는 차원에서 불길 속에 던져 넣었다네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n스모키의 유탄포스모키의 화염마법봉\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n물수건스모키의 외투"},
[6042] = {title = "성가신 녀석들", objective = "맹독 역병박쥐 20마리와 기괴한 역병박쥐 10마리를 해치운 후 나타노스 블라이트 콜러에게 돌아가야 합니다.", description = "제길, 저 짜증나는 박쥐 틈바구니를 통과하지 않고는 이 농장을 단 두 발짝도 벗어날 수가 없어. 빌어먹을 박쥐랑 마주치지 않고 사냥개를 데리고 가서 스컬지를 해치우고 싶단 말이야. 내가 허구한 날 박쥐나 때려잡고 있을 만큼 한가한 건 아니잖아? 하지만 자넨 아니지.\n\n자넨 훈련 중이지, 안 그래? 이런 훈련도 한 번 해야지! 얼른 튀어나가서 저 날아다니는 악마들을 모조리 정리할 때까지 돌아오지 말라고! 날 실망시키지 말게!", progress = nil, completion = "참을성이 대단한걸. 화도 안 나나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6061] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 다자란 초원타조를 길들이고 기술을 연습한 후 블러드후프 마을에 있는 요 샤프메인에게 조련용 막대를 돌려줘야 합니다.", description = "타우렌으로서 우리 선조들의 전통을 따라 강한 짐승들과 싸워 나가는 것은 중요한 일이오. 이 짐승들을 물리침으로써 우리는 그들의 영혼을 받아들이고 대지모신께 더욱 가까워질 수 있는 것이지.\n\n그와 마찬가지로 야수를 길들여 우리 편에서 함께 싸우도록 하는 것도 우리를 둘러싼 자연과 하나가 되는 데 도움이 되는 일이외다. 언젠가 당신이 원하는 야수를 길들이는 법을 배우게 되겠지만 만사엔 연습이 필요한 법이고 당신은 아직 배울 게 많이 남아 있소. 먼저 이 조련용 막대를 가져가서 다자란 초원타조를 길들여 오시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6062] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 사나운 점박이멧돼지를 길들여야 합니다. 기술을 연습한 후 칼바위 언덕에 있는 소타르에게 조련용 막대를 돌려주어야 합니다.", description = "자연에 자신의 권한을 행사한다는 것은 경외할 만한 기술이오. 당신은 사냥꾼으로서 자신이 선택한 생물의 고유한 힘과 능력을 이용하는 법을 익히기 위해 노력해야 하오.\n\n짐승을 부린다는 건 결코 쉬운 일이 아니오. 굳은 결의를 가지고 임해야 하는 임무인 거요.\n\n당신의 첫 번째 임무로 이 조련용 막대를 들고 가서 사나운 점박이멧돼지를 길들이도록 하시오. 칼바위 언덕에서 꽤 가까운 곳에서 찾을 수 있을 거요. 전투에서 길들인 멧돼지와 함께 전투에서 당신의 기술은 연마한 후 내게 돌아오시오.", progress = "행운을 빌겠소, 젊은 <class>이여.", completion = "잘했소, &lt;name&gt;. 이제 다음 임무를 맡을 준비가 된 것 같군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6063] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 나무그물 늑대거미를 길들여야 합니다. 기술을 연습한 후 돌라나르에 있는 다잘라에게 조련용 막대를 돌려주어야 합니다.", description = "사냥꾼으로서 그대의 책임을 잊지 않는 것이 매우 중요하오. 자연이란 그대의 욕망에 굴복하도록 만들 대상이 아니라, 그대보다 더 강한 존재로 인정하고 존경해야 할 힘이오.\n\n짐승을 그대의 동료로 길들이는 능력을 얻으려면, 그대가 이 사실을 이해하고 있다는 것을 반드시 입증해야만 하오.\n\n그대의 첫 임무는 이 조련용 막대를 가지고 가서 나무그물 늑대거미를 길들이는 것이오. 거대한 늑대거미를 길들이면서 사냥꾼의 기술을 연마하도록 하시오.", progress = "차근차근 자연의 길을 배우다 보면, 언젠가 위대한 <class>이 될 수 있을 거요.", completion = "잘 했소, &lt;name&gt;! 그대는 배우는 속도가 아주 빠르군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6064] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 큰 멧돼지를 길들여야 합니다. 기술을 연습한 후 카라노스에 있는 그리프 와일드하트에게 조련용 막대를 돌려주어야 합니다.", description = "안녕하신가, 젊은 양반! 자신만의 야수를 얻을 수 있는 방법을 알고 싶은 게야?\n\n자, 그럼 시작해볼까. 사냥을 할 때 장비만큼 중요한 게 또 어디 있겠나? 내 멋진 유산탄총 얘기는 다음에 하기로 하고, 지금은 보아하니 자네가 상당히 관심을 보이는 게 있는 듯하니... 그 얘기나 하세. 바로 야수 말이야! 맞지?!\n\n음, 가장 좋은 방법은 몇 가지 동물을 시험 삼아 길들여 본 다음, 어느 게 가장 마음에 드는지 선택하는 거야. 그러니, 당장 큰 멧돼지를 하나 찾아서 이 조련용 막대로 한번 길들여 보게.", progress = "돼지가 내 야수가 되는 건 아닌가하고 걱정할 건 없네, 젊은이! 지금은 결정을 내리기 전에 몇 가지 다양한 짐승을 길들여 보는 게 좋으니까.", completion = "그럼, 자네 맘 아네. 다음은 어떤 짐승일까 궁금해 죽겠지?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6065] = {title = "사냥꾼의 길", objective = "블러드후프 마을에 있는 요 샤프메인과 대화해야 합니다.", description = "안녕하시오, 젊은 사냥꾼 친구. 보아하니 당신은 야수를 길들여 벗으로 삼을 수 있을 정도의 솜씨가 있는 것 같군.\n\n블러드후프 마을에 있는 요 샤프메인을 꼭 찾아가 보시오. 그가 당신만의 야수를 얻을 수 있는 방법을 알려 줄 것이오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6066] = {title = "사냥꾼의 길", objective = "블러드후프 마을에 있는 요 샤프메인과 대화해야 합니다.", description = "안녕하시오, 젊은 사냥꾼 친구. 보아하니 당신은 야수를 길들여 벗으로 삼을 수 있을 정도의 솜씨가 있는 것 같군.\n\n블러드후프 마을에 있는 요 샤프메인을 꼭 찾아가 보시오. 그가 당신만의 야수를 얻을 수 있는 방법을 알려 줄 것이오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
