[6068] = {title = "사냥꾼의 길", objective = "칼바위 언덕에 있는 소타르와 대화하십시오.", description = "안녕하세요, 젊은 사냥꾼님? 보아하니 당신은 야수를 길들여 벗으로 삼을 수 있을 정도로 솜씨가 좋은 분 같군요.\n\n칼바위 언덕에 있는 소타르를 꼭 찾아가 보세요. 그가 당신만의 야수를 얻을 수 있는 방법을 알려 줄 거예요.", progress = nil, completion = "그렇소, 나도 당신이 준비가 됐다고 생각하오...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6069] = {title = "사냥꾼의 길", objective = "칼바위 언덕에 있는 소타르와 대화하십시오.", description = "안녕하세요, 젊은 사냥꾼님? 보아하니 당신은 야수를 길들여 벗으로 삼을 수 있을 정도로 솜씨가 좋은 분 같군요.\n\n칼바위 언덕에 있는 소타르를 꼭 찾아가 보세요. 그가 당신만의 야수를 얻을 수 있는 방법을 알려 줄 거예요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6070] = {title = "사냥꾼의 길", objective = "칼바위 언덕에 있는 소타르와 대화하십시오.", description = "안녕하세요, 젊은 사냥꾼님? 보아하니 당신은 야수를 길들여 벗으로 삼을 수 있을 정도로 솜씨가 좋은 분 같군요.\n\n칼바위 언덕에 있는 소타르를 꼭 찾아가 보세요. 그가 당신만의 야수를 얻을 수 있는 방법을 알려 줄 거예요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6071] = {title = "사냥꾼의 길", objective = "돌라나르에 있는 다잘라와 대화하십시오.", description = "젊은 사냥꾼이여, 안녕하시오? 보아하니 그대는 야수를 길들여 벗으로 삼을 수 있을 정도의 솜씨가 좋은 분 같군요.\n\n돌라나르에 있는 다잘라를 꼭 찾아가 보세요. 그대만의 야수를 얻을 수 있는 방법을 알려줄 거예요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6072] = {title = "사냥꾼의 길", objective = "돌라나르에 있는 다잘라와 대화하십시오.", description = "안녕하신가, 젊은 사냥꾼 친구... 척 보아하니 그대는 야수를 길들여 벗으로 삼을 수 있는 정도의 솜씨가 좋은 것 같소.\n\n돌라나르에 있는 다잘라를 꼭 찾아가 보시오. 그대만의 야수를 얻을 수 있는 방법을 알려줄 거요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6073] = {title = "사냥꾼의 길", objective = "돌라나르에 있는 다잘라와 대화하십시오.", description = "젊은 사냥꾼이여, 안녕하세요? 보아하니 당신은 야수를 길들여 벗으로 삼을 수 있을 정도의 솜씨가 좋은 분 같군요.\n\n돌라나르에 있는 다잘라를 꼭 찾아가 보세요. 당신만의 야수를 얻을 수 있는 방법을 알려줄 거예요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6074] = {title = "사냥꾼의 길", objective = "카라노스에 있는 그리프 와일드하트와 대화하십시오.", description = "안녕하신가, 젊은 사냥꾼 양반? 보아하니 당신은 야수를 길들여 벗으로 삼을 수 있을 정도로 솜씨가 좋은 것 같군.\n\n카라노스에 있는 그리프 와일드하트를 꼭 찾아가 보게. 그가 당신만의 야수를 얻을 수 있는 방법을 알려 줄 테니.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6075] = {title = "사냥꾼의 길", objective = "카라노스에 있는 그리프 와일드하트와 대화하십시오.", description = "안녕하세요, 젊은 사냥꾼님? 보아하니 당신은 야수를 길들여 벗으로 삼을 수 있을 정도로 솜씨가 좋은 분 같군요.\n\n카라노스에 있는 그리프 와일드하트를 꼭 찾아가 보세요. 그가 당신만의 야수를 얻을 수 있는 방법을 알려 줄 거예요.", progress = nil, completion = "그래, 자네는 훈련을 받을 때가 된 것 같네...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6076] = {title = "사냥꾼의 길", objective = "카라노스에 있는 그리프 와일드하트와 대화하십시오.", description = "안녕하세요, 젊은 사냥꾼님? 보아하니 당신은 야수를 길들여 벗으로 삼을 수 있을 정도로 솜씨가 있는 분 같군요.\n\n카라노스에 있는 그리프 와일드하트를 꼭 찾아가 보세요. 그가 당신만의 야수를 얻을 수 있는 방법을 알려 줄 거예요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6081] = {title = "야수 길들이기", objective = "오그리마에 있는 오르막 그림샷과 대화하십시오.", description = "당신은 짐승을 길들여 야수로 삼는 능력을 얻었소. 이제는 그 야수를 조련하는 기술을 익혀야 할 때요.\n\n오그리마로 가도록 하시오. 그곳에서 가장 존경받는 사냥꾼 중 하나인 오르막 그림샷을 찾아가 보시오. 그분이 당신의 새로운 야수를 조련하는 기술을 전수해 주실 것이오. 그분은 용사의 전당 근처에 계시오.\n\n행운을 빌겠소, <name>.", progress = nil, completion = "젊은 &lt;class&gt; 친구로군. 그래, 내 자네에게 야수를 다스리는 데 필요한 기술을 전수해 주겠네. 이제 야수에게 새로운 기술을 가르칠 수 있고, 먹이를 주고, 전투에서 쓰러지면 부활시킬 수도 있게 될 걸세.\n\n자, 이제 가 보게. 훗날 다시 얘기를 나누도록 하지.", rewards = "다음과 같은 것들을 배웁니다:\n\n길들이기 훈련\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야수 조련\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6082] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 등껍질전갈을 길들여야 합니다. 기술을 연습한 후 칼바위 언덕에 있는 소타르에게 돌아가십시오.", description = "마지막으로 길들여야 할 짐승은 당신이 닮기 위해 노력해야 할 생물이라오. 바로 등껍질전갈인데, 빠르고 정확하게 공격을 하는 녀석이지. 이런 생물의 힘을 부리는 것이 바로 사냥꾼으로서 당신의 숙명이오.\n\n이번에 돌아오면 당신이 선택하는 생물을 길들이는 데 필요한 기술을 전수해 주겠소. 짐승을 마음대로 부리는 거지. 야수는 당신의 조종을 받으면서 함께 경험을 쌓게 되는 거지. 마음대로 야수를 소환하는 법과 해제하는 법도 가르쳐 주겠소.", progress = "전갈 길들이기에는 성공했소?", completion = "이제 당신에게 가르칠 수 있는 건 모두 가르쳤소, &lt;name&gt;. 이곳에서 배운 지식을 토대로 원하는 야수를 선택할 때가 왔소이다.\n\n자, 받으시오. 이제 야수를 길들일뿐만 아니라, 자유자재로 소환하고 소환을 해제할 수 있는 능력을 주겠소. 자부심을 가지고 이 기술을 사용하도록 하시오. 당신은 그럴 자격이 충분히 있소이다.", rewards = "다음과 같은 것들을 배웁니다:\n\n길들이기 훈련\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야수 길들이기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6083] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 붉은톱니게를 길들여야 합니다. 기술을 연습한 후 칼바위 언덕에 있는 소타르에게 조련용 막대를 돌려주어야 합니다.", description = "야수가 하나 있으면 적과의 싸움에서 당연히 유리한 입장이 되는 것이오. 다른 생물을 마음대로 부릴 수 있게 된다는 건 자신의 힘을 배가시키는 거지... 야수는 당신 자신의 손과 발이 되어야 하오.\n\n다음 임무를 수행하려면 땅을 벗어나야 하오. 해안의 물속을 샅샅이 찾아봐야 하외다. 센진 마을을 가로질러 메아리 섬 근처에서 붉은톱니게를 찾아보시오. 조련용 막대로 길들여서 당신의 기술을 연습하도록 하시오.", progress = "야수를 효과적으로 부리는 데 필요한 기술은 꾸준한 연습을 통해서만 얻을 수 있소. 붉은톱니게는 길들였소?", completion = "당신은 배우는 속도가 빠르군, &lt;name&gt;. 아주 잘했소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6084] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 눈표범을 길들여야 합니다. 기술을 연습한 후 카라노스에 있는 그리프 와일드하트에게 돌아가십시오.", description = "그 멧돼지들 꽤 우락부락하지? 흠, 좀 더 날렵한 짐승이 어떻겠나? 그렇다면 딱 맞는 짐승이 하나 있지. 여기서 남동쪽으로 가 보면 눈표범이라는 덩치 큰 흰 고양잇과 짐승이 있다네. 우아하게 다듬은 소총처럼 아름다운 외모 속에 엄청난 피해를 가할 수 있는 강력한 투지가 숨어 있지. 자네가 길들인 멧돼지보다 훨씬 더 빠르고 민첩하다는 걸 알게 될 거야.\n\n이 조련용 막대를 가져가서 눈표범이 맘에 드는지 한번 보고 오게.", progress = "눈표범은 어떻나, <name>?", completion = "자네가 충분히 배웠다고 판단되었을 때, 어떤 짐승이든 마음에 드는 야수를 고를 수 있는 능력을 갖게 해주겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6085] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 얼음발톱흰곰을 길들여야 합니다. 기술을 연습한 후 카라노스에 있는 그리프 와일드하트에게 조련용 막대를 돌려주어야 합니다.", description = "자네, 어쩌면 광포한 힘 외에는 가진 게 없는 짐승을 원할지도 모르겠군. 자네처럼 이제 막 사냥꾼의 길을 걷기 시작한 이에게는 얼음발톱흰곰이 아주 좋은 친구가 돼줄 수 있지. 카라노스 동쪽으로 가게. 이 조련용 막대로 얼음발톱흰곰을 길들여 마음에 드는지 한번 봐.\n\n이번에 돌아오면 자네가 원하는 짐승을 길들이는 데 필요한 기술을 전수해 주겠어. 야수로 길들이면, 자네가 직면하는 난관에 맞서 함께 경험을 쌓아 갈 걸세. 자유자재로 소환하고 소환을 해제하는 법도 가르쳐 주지.", progress = "얼음발톱흰곰은 길들여 보았나?", completion = "자, &lt;name&gt;. 그럼 이제 야수를 길들일 수 있는 능력과 함께 자네가 원하는 대로 야수를 소환하고 소환을 해제할 수 있는 능력을 전수해 주겠네.\n\n충성스러운 야수를 찾아 즐거운 사냥을 하길 바라네!", rewards = "다음과 같은 것들을 배웁니다:\n\n길들이기 훈련\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야수 길들이기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6086] = {title = "야수 길들이기", objective = "아이언포지에 있는 빌리아 썬더그래니트와 대화하십시오.", description = "<name>, 자네 짐승을 길들여 야수를 삼을 수 있는 능력이 있군. 이제 그 야수를 조련하는 기술도 반드시 익혀야 하네.\n\n아이언포지에 있는 전투의 전당으로 가게. 우리가 가장 존경하는 야수 조련사 중 하나인 빌리아 썬더그래니트를 만나보라고. 그녀가 자네의 새 야수를 조련하는 기술을 전수해 줄 테니, 어서 가보는 게 좋을 거야, 젊은이!\n\n빌리아는 친절한 성품을 지니고 있으니, 그녀의 허락을 받는 건 그리 어렵지 않을 거야. 행운을 빌겠네, <name>.", progress = nil, completion = "신참인가요? 훌륭한 &lt;class&gt;이 되기 위한 길을 걷고 있는 것 같군요.\n\n그래요, 당신의 야수를 조련하고 부리는 데 필요한 기술을 전수해 주겠어요. 야수에게 새로운 능력을 가르칠 수 있을 뿐만 아니라 먹이도 주고 전투에서 쓰러졌을 때 되살릴 수도 있을 거예요.\n\n새로운 야수를 가장 효과적으로 다스리기 위한 열쇠는 바로 야수를 존중하고 잘 대해 주는 것이라는 걸 명심하세요. 그렇게 하면 야수는 당신의 가장 충실한 벗이 되어 줄 겁니다.", rewards = "다음과 같은 것들을 배웁니다:\n\n길들이기 훈련\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야수 조련\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6087] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 긴발톱 초원늑대를 길들이고 기술을 연습한 후 블러드후프 마을에 있는 요 샤프메인에게 조련용 막대를 돌려줘야 합니다.", description = "사냥꾼이여, 당신은 불타는 영혼을 지니고 있어 다음 과제를 몹시도 바라고 있군그래.\n\n자, 다음 임무는 긴발톱 초원늑대라는 짐승을 친구로 만드는 것이오. 긴발톱 초원늑대는 민첩하고 두려움을 모르기 때문에 이 짐승을 당신의 야수로 길들이려면 당신도 그런 특성을 지녀야 하오.\n\n전투를 치르면서 당신과 당신의 야수가 한 조가 되는 법을 배우게 될 것이오. 결국에는 하나가 되어 직접 몸을 부딪치며 싸워 나가야 하니 말이지.\n\n여기 조련용 막대를 줄 테니 가서 긴발톱 초원늑대를 길들이고 기술을 연습하도록 하시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6088] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 검독수리를 길들이고 기술을 연습한 후 블러드후프 마을에 있는 요 샤프메인에게 조련용 막대를 돌려줘야 합니다.", description = "마지막 임무를 완료하려면 하늘에서 서식하는 짐승을 길들여야 하오. 검독수리는 까다로운 상대지만, 당신의 친구가 된다면 날카로운 공격과 위협적인 존재감을 얻게 될 것이오.\n\n대지모신의 뜻에 맹세코 당신이 임무를 마치고 돌아오면 원하는 짐승을 길들여 친구로 만드는 데 필요한 기술을 전수해 주겠소. 그리고 마음대로 야수를 소환하는 법과 소환을 해제하는 법도 가르쳐 주리다. 당신의 친구가 될 야수는 당신이 겪는 모든 난관을 함께하며 당신과 함께 경험을 쌓아 갈 것이오.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n길들이기 훈련\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야수 길들이기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6089] = {title = "야수 길들이기", objective = "썬더 블러프의 수렵의 봉우리에 있는 홀트 썬더혼과 대화해야 합니다.", description = "이제 당신은 짐승을 길들여 야수로 삼는 능력을 얻었소. 그 야수를 조련하는 기술도 반드시 익혀야 하오.\n\n썬더 블러프로 가서 우리가 가장 존경하는 사냥꾼인 홀트 썬더혼을 만나보시오. 당신이 기술을 익힐 가치가 있다고 판단되면 그가 야수를 조련하는 방법을 전수해줄 것이오.\n\n홀트는 아제로스에서 가장 강하고 두려운 짐승들을 물리쳤을 뿐 아니라 여러 힘센 짐승들을 부릴 줄도 알지. 그는 대지모신과의 유대가 아주 돈독하니 많은 것을 배울 수 있을 것이오. 행운을 빌겠소.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n길들이기 훈련\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야수 조련\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6101] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 긴발톱 흑호를 길들여야 합니다. 기술을 연습한 후 돌라나르에 있는 다잘라에게 조련용 막대를 돌려주어야 합니다.", description = "<name>, 자연은 항상 변하고 있소. 절대로 같은 상태로 머물지 않고 항상 변한다는 점만은 분명하지.\n\n앞으로 내가 주는 임무를 통해 그대는 장차 동료로 삼을 다양한 동물을 직접 보고 느낄 수 있을 거요.\n\n자, 이 조련용 막대를 들고 남쪽으로 가서 긴발톱 흑호를 길들이도록 하시오. 이제부터 사냥꾼의 기술을 연습하는 거요. 그대는 자신과 자연의 유사점과 차이점을 이해하기 시작할 것이오.", progress = "자연과의 균형을 이해하는 것은 모든 <race>가 공유하는 삶의 방식이오.", completion = "&lt;name&gt;, 그대는 굳은 결의를 가슴 속에 품고 있고 나의 가르침을 잘 이해하는 것 같군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6102] = {title = "야수 길들이기", objective = "조련용 막대를 사용해 비명소리 스트리기드 올빼미를 길들여야 합니다. 기술을 연습한 후 돌라나르에 있는 다잘라에게 조련용 막대를 돌려주어야 합니다.", description = "땅에 서식하는 짐승을 두 마리 길들여 보았으니, 이제는 하늘을 날아다니는 짐승을 길들일 차례요. 조련용 막대를 이용해 여기서 서쪽에 있는 비명소리 스트리기드 올빼미를 길들인 후, 그 사나운 올빼미를 곁에 두고 기술을 연마하시오.\n\n돌아오면 그대가 원하는 짐승을 길들일 수 있는 기술을 전수해 주겠소. 그 짐승은 그대 옆에서 함께 모든 난관을 겪으며 성장해 갈 것이오. 자유자재로 짐승을 소환하고 소환을 해제시키는 법도 가르쳐 주리다.", progress = "그대가 이뤄낸 성과를 보면 내 가슴이 다 뿌듯하오. 내가 준 마지막 임무는 끝냈소?", completion = "이제 더 이상 가르칠 게 없소. 내 한 가지만 충고하리다. 처음으로 야수를 선택할 짐승을 고를 때는 신중을 기해야 하오. 땅, 물, 그리고 하늘에서 사는 것들 중 잘 생각해서 선택하라는 말이오. 어떤 야수를 고르든 상당 기간 그대와 함께하리라는 것은 분명하니까.\n\n자, 이 기술을 이용하면 야수를 길들일 수 있을 뿐만 아니라, 원하는 대로 소환해서 곁에 두었다가 소환을 해제시킬 수 있을 거요. 긍지를 가지고 사용하도록 하시오. 그대는 그럴 자격이 충분히 있소.", rewards = "다음과 같은 것들을 배웁니다:\n\n길들이기 훈련\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야수 길들이기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6103] = {title = "야수 길들이기", objective = "다르나서스의 세나리온 자치령에서 조카스테와 대화하십시오.", description = "그대는 짐승을 길들여 야수로 얻을 수 있는 능력을 얻었소. 이제 그 야수를 조련하는 기술도 반드시 익혀야 하오.\n\n다르나서스로 가시오. 그곳에서 우리가 가장 존경하는 사냥꾼 중 하나인 조카스테를 찾아 얘기를 나눠보시오. 새로운 야수를 조련하는 기술을 전수해줄 테니 서둘러 가보시오.\n\n조카스테는 엄격해 보이긴 하지만 새로운 사냥꾼이 성장하는 것을 언제나 반기는 분이오. 존경하는 마음으로 그분을 대하면 친절하게 가르쳐주실 거요. 행운을 빕니다, <name>.", progress = nil, completion = "젊은 &lt;class&gt;이로군. 좋아, 내가 그대의 야수를 조련하고 다스리는 법을 전수해주겠소. 야수에게 새로운 기술을 가르칠 수 있을 뿐 아니라 먹이를 주고 전투에서 쓰러지면 되살릴 수도 있소.\n\n명심하시오, &lt;name&gt;. 언제나 자연의 균형을 존중하고 경외해야 합니다. 자, 이제 가보시오. 훗날 다시 만날 날을 기약하며...", rewards = "다음과 같은 것들을 배웁니다:\n\n길들이기 훈련\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야수 조련\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6121] = {title = "새로운 가르침", objective = "달숲으로 가서 나이트헤이븐 마을에 있는 덴드리트 스타블레이즈와 대화해야 합니다.", description = "<name>, 이제 그대는 우리 드루이드만의 능력인 독을 제어하는 방법에 대해 배울 준비가 되었소. 세나리우스께서 주신 능력으로 우리는 단순한 주문으로 아무리 치명적인 독이라도 정화할 수 있다오. 그러나 이러한 선물은 쉽게 받을 수 있는 것이 아니오. 열심히 노력해야 할 거요. 그러다 보면 전문가가 아닌 그대라도 독을 치유할 날이 있을 거요.\n\n달숲으로 가서 덴드리트 스타블레이즈와 대화하시오. 그대를 가르치기 위해 기다리고 있을 테니까.", progress = nil, completion = "안녕하십니까, 젊은 &lt;class&gt;여! 그대가 독을 정화하는 법을 익히기 위해 노력하는 것을 보니 반가울 따름입니다.\n\n예전에는 대부분의 &lt;class&gt;가 미리 계획을 세워 그런 기술을 배우고는 했지만, 그대의 경우는 좀 다를 것입니다. 현재 아우버다인의 많은 동물이 독 때문에 질병에 걸려 있지만, 마을에선 치료법조차 찾지 못하고 있습니다. 달숲에서 누군가를 보내 조치를 취해달라는 도움을 요청하였고, 그래서 그대를 보내려는 것입니다. 이것은 훈련이 아니라 실제 상황입니다. 이 점을 명심하십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6122] = {title = "오염된 수원", objective = "빈 절벽 폭포 견본병을 이용해 폭포 옆에 있는 동굴 입구에서 물을 채취해야 합니다.\n\n물을 다 채우면, 아우버다인, 어둠의 해안에 있는 알란다리안 나이트송에게 가득 찬 절벽 폭포 견본병을 갖다주어야 합니다.", description = "어둠의 해안에 사는 생명체들의 주된 수원은 절벽 폭포에서 떨어지는 물입니다. 그런데 그곳에 동물들... 특히 사슴에게 해를 입히는 독이 퍼진 것 같습니다. 자, 동굴 입구로 가서 이 견본병에다 물을 채취해 오십시오. 폭포 바로 옆에 있는 동굴에는 위험한 나가가 살고 있으니 조심해야 합니다.\n\n물을 다 채우면 아우버다인에 있는 알란다리안 나이트송에게 갖다주십시오. 그녀가 우리에게 도움을 청했으니 이 문제를 함께 해결해 보십시오.", progress = "그대는 달의 숲 세나리온 의회에서 보낸 분이로군요? 정말 잘됐습니다. 이제 불쌍한 사슴들에게 닥친 위기를 해결할 수 있겠습니다. 마침 도움이 필요했는데 이제 걱정 없게 되었으니 얼마나 기쁜지 모르겠습니다.B\n덴드리트 스타블레이즈가 말한 폭포수의 견본은 가져오셨습니까? 그대가 가져올 견본으로 치료제를 만들 수 있을 거라던데...", completion = "맙소사! 정말 역겨운 냄새가 나는군요! 사슴이 병든 것도 당연해요.\n\n폭포수가 뭔가에 오염되어 어둠의 해안에 흐르는 모든 물이 오염됐어요. 해안 근처의 사슴뿐 아니라 온 사방의 사슴들이 병들었어요. 이 폭포수야말로 병을 퍼지게 한 근원이 틀림없어요. 우리가 할 일이 생긴 것 같군요.\n\n이상하게 들리겠지만 이 물을 이용해 치료약을 만드는 거예요. 그런데 몇 가지 재료가 추가로 필요하답니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6123] = {title = "약재 모으기", objective = "아우버다인의 알란다리안 나이트송이 치료제를 만들 수 있도록 뱀뿌리 5개와 달버섯 12개를 가져다 주어야 합니다.", description = "저는 병든 사슴을 위해 치료제를 만들고 있습니다. 기본 재료는 물이고, 약효를 위해 뱀뿌리가 꼭 필요합니다. 뱀뿌리를 찾는 법은 약초채집가라면 알고 있을 테니, 혹시 모르겠다면 찾아서 도움을 받으십시오.\n\n마지막으로 약효를 최대로 높이기 위해서는 달버섯이 필요한데 아주 찾기 쉽답니다. 여기서 동쪽으로 조금만 가면 동굴이 하나 있는데 그 동굴 안에 지천으로 널려 있으니까요. 거기서 너무 머물다 보면 동굴에 사는 사나운 달빛야수가 달려들지도 모르니 조심하세요.", progress = "제가 병든 사슴을 치료할 연고를 만드는 데 필요한 재료는 가져오셨나요? 사슴의 차도가 전혀 나아질 기미가 보이지 않으니 서둘러야 합니다!", completion = "&lt;name&gt;, 수고했어요. 연고를 만들기에 충분한 양이로군요. 병든 사슴 몇 마리 치료하기에는 딱 맞겠어요.\n\n모든 질병을 유발하는 독마다 정화하는 치료제의 성분이 달라서 그걸 만드는 일이 무척 어려울 때가 있지요. 딱 맞는 재료가 도대체 뭘까 고민하지 않고 마음 편히 병을 치료할 수 있다면 얼마나 좋을까요!\n\n자, 이제 그대가 가져오신 이 재료들로 연고를 만들어야겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6124] = {title = "병든 사슴 치유", objective = "어둠의 해안에 퍼져 있는 병든 사슴 10 마리에게 잘 듣는 동물 연고를 발라 치료해야 합니다. 병든 사슴은 폭포수 강 남부에서 아우버다인 북부까지 퍼져 있으며 잿빛 골짜기가 시작되는 어둠의 해안 남부까지 넘나든다고 합니다.", description = "<name>, 그대가 재료를 충분히 가져오신 덕분에 치료약을 10회 분이나 만들 수 있었습니다. 저는 이 마을 주민들과 협력해서 약을 좀 더 만들려고 합니다. 우선은 그대가 좀 도와주셨으면 하는 일이 있어요. 어둠의 해안 전역에 사는 사슴들이 병을 앓고 있습니다. 연고를 사용해서 그들을 치료해야 해요.\n\n임무를 완수하면 달숲에 있는 덴드리트 스타블레이즈에게 가십시오. 그대와 이야기를 하고 싶어할 겁니다. 세나리온 의회에 아우버다인을 대표해 제가 고마움을 표한다고 전해주십시오. 그리고 그대의 도움에도 미리 감사를 표하고 싶군요.", progress = nil, completion = "그대는 어둠의 해안에 사는 사슴들에게 큰 도움을 주셨습니다. 그들은 해안 전역에 만연해 있는 병에 자신들도 모르게 감염된 희생양입니다. 다르나서스에는 이 불길한 징조를 깨닫는 이도 있으나, 나날이 불거지는 이 사악한 징조를 모른 체 하는 이도 있습니다. &lt;name&gt;, 부디 그대는 이런 일을 모르는 척하지 않길 바랍니다.\n\n어쨌거나 그대는 대자연과 세나리온 의회의 소중한 친구임이 입증되었으니 그 징표로 이것을 드립니다.", rewards = "다음과 같은 것들을 받습니다:\n\n먼지장막 약초주머니"},
[6125] = {title = "독을 다스리는 능력", objective = "다르나서스, 세나리온 자치령에 있는 마스렌길 베어워커에게 돌아가야 합니다.", description = "그대는 이제 영혼의 도움이 없이도 독을 정화하는 방법을 배우셨습니다. 그대가 독을 다스리는 능력을 익히기 애쓰는 지금 이 순간에도, 중독된 생명들이 고통과 싸우며 견디고 있다는 사실을 잊지 마십시오.\n\n<name>, 그대는 이제 다르나서스의 마스렌길 베어워커에게 돌아가야 합니다. 그라면 분명 그대에게 드루이드로서 반드시 알아야 할 마법을 가르쳐 줄 겁니다.\n\n평안히 가십시오, 젊은 드루이드여! 우리는 다시 만나게 될 겁니다.", progress = nil, completion = "어서 오세요. 그대가 떠난 후 많은 것을 배웠다는 소식은 익히 들어 알고 있습니다. 또한 아우버다인의 상황을 듣고 무척이나 놀랐어요. 그런 독이 퍼지면 자연의 균형이 무너지기 때문에 더 자세히 조사해야 하는 겁니다.\n\n다행히도 그대가 지금까지 잘해주었어요. 그러니 그대에게 독을 다스리는 해독 능력을 주어 보상하는 것이 가장 좋은 방법인 것 같군요. &lt;name&gt;, 이 능력을 유용하게 사용하길 바랍니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n해독\n\n다음과 같은 것들을 받습니다:\n\n"},
[6126] = {title = "새로운 가르침", objective = "달숲으로 가서 나이트헤이븐 마을에 있는 덴드리트 스타블레이즈와 대화해야 합니다.", description = "이제 자네는 우리 드루이드들이 가진 독약과 능력에 대해 배울 준비가 되었네. 세나리우스는 우리에게 단순한 주문으로 가장 사악한 독도 정화할 수 있는 능력을 주셨다네. 이 선물은 쉽게 받을 수 없으며 배우기 위해 노력해야 하네. 그러면 비전문가인 자네도 독을 치유할 수 있어.\n\n달숲으로 가서 자네를 가르치기 위해 기다리고 있는 덴드리트 스타블레이즈와 대화해 보게.", progress = nil, completion = "안녕하십니까, 젊은 &lt;class&gt;여! 그대가 해독하는 법을 배우기 위해 노력하시는 것을 보니 반가울 따름이군요.\n\n예전에 대다수의 &lt;class&gt;가 미리 계획을 세워 이 기술을 배웠지만 그대의 경우는 좀 다릅니다. 불모의 땅에 있는 크로스로드에서는 동물들이 독에 중독되어 발진에 시달리고 있지만 마을에선 이 문제를 해결할 수가 없습니다. 달숲에서 도움을 청해왔기에 그대를 보내려고 합니다. 이는 훈련이 아니라 실제 상황임을 명심하시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6127] = {title = "오염된 수원", objective = "빈 공포의 안개봉우리 견본병을 봉우리 정상까지 가지고 가서 꼭대기 물웅덩이의 물을 채취해야 합니다.\n\n가득 찬 공포의 안개봉우리 견본병을 불모의 땅, 크로스로드에 있는 통가 룬토템에게 갖다주어야 합니다.", description = "아무래도 크로스로드 북서쪽의 공포의 안개봉우리에 심각한 독을 퍼뜨리는 원천이 있는 것 같습니다. 우뚝 솟은 그 봉우리에는 날씨를 좌지우지하는 물웅덩이가 하나 있습니다. 악마를 숭배하는 불타는칼날단이 그 물을 오염시키고 있는 것 같습니다.\n\n이 견본병을 이용해 봉우리 정상에 있는 웅덩이에서 물을 채취해 오십시오. 물을 다 채우면 크로스로드의 통가 룬토템에게 갖다주십시오. 그가 우리에게 도움을 청했으니 이 문제를 함께 해결해 보십시오.", progress = "자네는 달의 숲에 있는 세나리온 의회에서 보낸 이로군? 정말 다행일세. 우리는 병든 몸으로 불모의 땅 북부를 돌아다니는 불쌍한 가젤들을 치유해주기 위해 애쓰고 있다네. 마침 도움이 필요했는데 제 발로 일손이 찾아와서 매우 기쁘군.\n\n덴드리트 스타블레이즈가 말한 물 견본은 가져왔나? 그 견본이면 치료약을 만들 수 있다더군.", completion = "이런! 역겹기 짝이 없군! 가젤들이 병든 것도 당연해.\n\n물이 오염되기 시작하면서 불모의 땅 북부의 생태계가 파괴되기 시작했네. 이곳 동서로 북쪽에는 온통 병든 가젤 천지라네. 이 물이 병을 퍼지게 한 근원이 확실해. 우리가 할 일이 있네.\n\n이상하게 들리겠지만 이 물을 이용해 치료약을 만들 수 있어. 하지만 몇 가지 재료가 더 필요하다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6128] = {title = "약재 모으기", objective = "크로스로드의 통가 룬토템이 치료제를 만들 수 있도록 뱀뿌리 5개와 코도 뿔 5개를 갖다주어야 합니다.", description = "나는 병든 가젤을 위해 치료제를 만들고 있는데, 기본 재료는 물이고 약효를 내는 재료는 바로 뱀뿌리지. 뱀뿌리 찾는 법은 약초채집가라면 분명 알고 있을 테니, 만약 모르겠다면 찾아서 도움을 받게.\n\n마지막으로 약효를 최대로 높이기 위해 코도 뿔이 필요한데 몇 조각으로는 턱도 없지. 불모의 땅 북부에 자네가 다룰 만한 코도가 흩어져 있으니, 몇 마리 죽여서 나에게 뿔을 가져다주게. <name>, 이것은 자연의 균형을 유지하는 데도 큰 도움이 되는 일이야.", progress = "가젤을 치료할 연고를 만드는 데 필요한 재료는 모두 가져왔나? 딱하게도 가젤이 전혀 호전될 기미가 보이지 않아. 우리가 서둘러 도와줘야 해.", completion = "&lt;name&gt;, 잘했네. 연고를 만들기에 충분한 양이로군. 병든 가젤 몇 마리를 치료하기에는 충분하겠어.\n\n질병을 일으키는 독마다 정화할 치료제의 성분이 다르기 때문에, 치료제를 만드는 일은 무척 어렵지. 딱 알맞은 재료가 도대체 뭘까 고민하지 않고 마음 편히 병을 치유해 줄 수 있다면 얼마나 좋겠나!\n\n자, 이제 자네가 가져온 이 재료를 사용해 치료제를 만들어 봐야겠군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6129] = {title = "병든 가젤 치유", objective = "불모의 땅 북부에 퍼져 있는 병든 가젤 10마리를 찾아 잘 듣는 동물 연고를 발라서 치료해야 합니다. 병든 가젤은 크로스로드를 동서로 가로지르는 길의 북쪽에 있다고 합니다.", description = "<name>, 자네가 재료를 충분히 가져와 준 덕분에, 치료약을 10회 분이나 만들수 있었네. 난 이 지역 관계자들과 함께 좋은 약을 만들기 위해 노력하고 있지. 우선적으로 자네가 도와줄 일이 좀 있네. 불모의 땅 북부 전역에 걸쳐서 가젤들이 병을 앓고 있지. 이 연고로 그들을 치료해주게.\n\n임무를 완수하면 달의 숲에 있는 덴드리트 스타블레이즈에게 가보게. 자네와 대화를 원할 거야. 세나리온 의회에 우리가 감사하고 있다고 전해주게. 그리고 자네의 도움에 대해서도 미리 감사를 표하고 싶군.", progress = nil, completion = "그대는 불모의 땅에 사는 병든 가젤에게 큰 도움을 주셨습니다. 그들은 불모의 땅 전체에 만연해 있는 병에 자신들도 모르게 감염된 희생양입니다. &lt;race&gt; 종족은 세나리우스의 가르침을 이해하고 따르고자 노력하지요. 그대는 이번 일로 종족 간의 장벽을 넘어 조화를 이루어야 한다는 점을 증명해 보였습니다. 썬더 블러프에 사는 그대의 장로들처럼 말입니다.\n\n그대는 이 세계의 자연과 세나리온 의회의 소중한 친구임이 입증하셨으므로 이것을 그 징표로 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n먼지장막 약초주머니"},
[6130] = {title = "독을 다스리는 능력", objective = "썬더 블러프 장로의 봉우리에 있는 투락 룬토템에게 돌아가야 합니다.", description = "그대는 영혼의 도움 없이도 독을 정화하는 방법을 배우셨습니다. 그대가 독을 다스리는 능력을 익히려고 애쓰는 지금 이 순간에도 중독된 생명들이 고통과 싸우며 견디고 있다는 사실을 잊지 마십시오.\n\n그대는 이제 썬더 블러프의 투락 룬토템에게 돌아가야 합니다. 그라면 분명 드루이드들이 반드시 알아야 할 마법을 그대에게 가르쳐 줄 것입니다.\n\n평안을 빕니다, 젊은 드루이드여! 우리는 다시 만나게 될 겁니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n해독\n\n다음과 같은 것들을 받습니다:\n\n"},
[6131] = {title = "나무구렁일족", objective = "그라즐이 마른가지일족 전사, 길잡이, 정원사를 각각 5마리씩 처치하여 자기 일족의 친구임을 입증해달라고 요청했습니다.", description = "나무구렁일족은 유일하게 타락을 피해간 펄볼그 부족이오. 하지만 많은 이들이 적인지 친구인지 알아보려 하지도 않고, 펄볼그다 싶으면 맹목적으로 죽이고 있소. 상황이 이러하니 우리 나무구렁일족은 남을 잘 믿지 않게 되었소.\n\n당신이 우리의 친구임을 증명하고 싶다면, 먼저 악령의 숲에서 타락한 마른가지일족을 몰아내 주시오. 그러면 언젠가 당신을 우리 동료로 인정하겠소. 먼저 서쪽으로 가면 마른가지일족 전사, 길잡이, 정원사를 찾을 수 있을 거요.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[6132] = {title = "멜릿자 브림버즐 구출 작전", objective = "멜릿자 브림버즐을 호위한 후, 잊혀진 땅의 코도 무덤에 있는 호르니즈 브림버즐과 대화해야 합니다.", description = "나 좀 꺼내주세요!\n\n나는 마라우딘일족과 할 얘기가 있어 뾰족바위 골짜기로 왔답니다. 그들과 거래를 좀 해볼 참이었는데... 말도 못 붙이게 하더라고요! 나를 잡아먹으려나 봐요.\n\n날 여기서 꺼내 주면 내 형제인 호르니즈가 섭섭치 않게 대가를 지급할 거예요. 호르니즈는 동쪽의 코도 무덤 옆에 있는 우리 야영지에 있어요.\n\n서둘러 주세요! 켄타우로스 몇 녀석들이 솥을 가지러 숲으로 간다고 한지 2분도 안 됐어요!", progress = nil, completion = "내 동생 멜릿자가 자네가 올 거라더군. 동생을 구해줘서 정말 고맙네. 동생이 다른 데 또 정신이 팔린 것 같아서 걱정되긴 하지만 말이야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6133] = {title = "순찰대장의 명령", objective = "동부 역병지대의 북쪽 경계로 이동하여 쿠엘탈라스 기록부를 찾아야 합니다. 기록부는 쿠엘리시엔 오두막 어딘가에 있습니다.\n\n순찰자 8명, 길잡이 8명, 수렵꾼 8명을 해치워야 합니다.", description = "쿠엘리시엔 오두막의 하이 엘프가 내 물건, 바로 내 물건을 지니고 있어. 내 일대기를 상세히 기록한 문서지.\n\n질문은 안 돼! 너무 많이 알려고 들지 마. 내가 말하는 대로만 해, 이 한심한 친구야! 기록부를 찾으라고.\n\n그리고 최대한 많은 분쟁과 재난을 일으켜서 고통을 줘야 해. 알겠지?", progress = "날 기다리게 하지 말라고, <class> 친구.", completion = "기록부를 읽진 않았겠지! 그런 짓을 할 정도로 머저리는 아닐 거야...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6134] = {title = "유령의 플라스마 모으기", objective = "잊혀진 땅의 호르니즈 브림버즐에게 유령의 플라스마 8개와 유령 유인기 상자를 가져가야 합니다.", description = "남동쪽으로 가면 마그람일족 유령들이 자주 출몰하는 뼈의 골짜기라는 계곡이 있다네. 듣기에도 으스스하지 않나? 그러니 마그람에 가면 얼마나 겁이 나겠어! 그 계곡의 유령의 힘을 흡수한다면 분명 같은 수의 켄타우로스만큼 가치가 있을 거야.\n\n자, 이 유령 유인기 상자를 가져 가라고. 골짜기에 있는 큼지막한 해골 사이에 유령 유인기 상자를 놓아두면 골리아스의 유령들이 나타날거야. 조금 떨어져서 주위를 살피다가 유령이 나타나면 처치하고 유령의 플라스마를 가져오게. 그걸 마그람일족에게 팔아치울 거야.", progress = "내 유령의 플라스마는 어디 있지?", completion = "거기 있군! 당신도 몇 개 챙긴 것 같은데? 좀 치사한 것 같지 않아?\n\n어쨌든 고생 많았네. 켄타우로스랑 거래하면 돈이 좀 되겠는걸!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n검독수리 팔보호구안정의 버클러\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6135] = {title = "혐오스런 그늘날개", objective = "마리스 농장 북부의 변두리를 배회하고 있는 그늘날개를 찾아 해치워야 합니다. 시체에서 그늘날개 모피 조각을 찾아 나타노스 브라이트콜러에게 가져가야 합니다.", description = "자넨 말이야... 시간을 딱딱 맞추진 못 했어도 지금까지 내가 준 임무를 잘 완수했어.\n\n다른 임무를 맡겨도 되겠지? 그래. 좋아, 얼간이 친구. 좀 더 복잡한 임무를 주지.\n\n여기서 북쪽의 변두리에 가면 희멀건 악마 같은 박쥐 그늘날개가 돌아다니고 있지. 녀석을 찾아 없애 버리고 녀석의 하얀 털을 가지고 돌아오면 보상을 주지.", progress = "이 일을 혼자 하는 건 좋지 않아, <class> 친구.", completion = "훌륭하군, 얼간이 친구! 이 모피로 자네가 사용할 수 있는 물건을 만들어볼까?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n그늘날개 장갑그늘날개 어깨보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6136] = {title = "뚱뚱보 괴물", objective = "동부 역병지대 북부 불모지에서 피고름구더기를 찾아 물리친 후 나타노스 블라이트콜러에게 돌아가야 합니다.", description = "희망의 빛 예배당에 있는 은빛 여명회의 야영지를 지나 노스데일 서쪽에 뚱뚱한 피고름구더기가 있지.\n\n나는 그 괴물에게 연대원 전체를 잃었어. 놈의 크기는 어마어마하지. 먹는 족족 몸뚱이가 커지는 놈이야.\n\n놈이 자네를 먹어치워도 난 눈 하나 깜짝하지 않겠지만 그래도 이기기 바라네. 이번 임무를 완수하려면 다른 사람의 도움을 받는 게 좋아. 피고름구더기한테 소규모로 덤비는 건 잡아먹어 달라고 부탁하는 것이나 다름없거든.", progress = nil, completion = "계속 그렇게 해 보라고. 자네를 멍청이에서 1급 저능아로 진급시켜 줄 테니까!.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n독고름 도끼해골바위 망치사라의 길잡이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6141] = {title = "수사 안톤", objective = "잊혀진 땅에 있는 수사 안톤과 대화해야 합니다.", description = "제 전우인 안톤 수사는 머나먼 칼림도어의 잊혀진 땅이라는 곳에서 언데드가 나타나고 있다는 소문을 듣고는 언데드의 위협을 찾아 물리치기 위해 즉시 그곳으로 떠났습니다!\n\n안톤 수사는 자신을 도와 줄 용기 있고 결의에 찬 이들을 찾고 있으니 혹시 진정으로 그럴 생각이 있다면 안톤을 찾아가 보십시오. 그는 잊혀진 땅의 얼라이언스 마을인 나이젤의 야영지에 있습니다.", progress = nil, completion = "동쪽에서 도움을 줄 이가 온다는 소식은 들었습니다. 그게 바로 형제신가요? 붉은십자군의 성전을 도우러 여기 오신 겁니까?\n\n그렇다면 잘 들으십시오...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6142] = {title = "조개 미끼", objective = "연갑 조갯살 10개를 찾은 후, 그늘수렵 마을에 있는 마이라힐에게 가져가야 합니다.", description = "당신은 낚시꾼 같아 보이는군요. 전 낚시를 무척 좋아한답니다. 평생 낚시를 하며 살았죠. 제일 쓸 만한 미끼는 연갑 조갯살이랍니다. 물고기들이 끌리지 않을 수가 없거든요. 무슨 말인지 아시죠?\n\n북쪽으로 가 보시면 해안에 난파선이 하나 있을 거예요. 그 부근에 연갑 조개가 널려 있는데, 연갑 조갯살 10개를 가져오시면 그 대가로 좋은 걸 드리도록 하죠.", progress = "어서 신선한 연갑 조갯살을 좀 가지고 낚시하러 가고 싶군요. 필요한 10개의 조갯살을 가져오셨나요?", completion = "딱 됐네요. 의술사님이 두통이 나거든 이렇게 하라고 하셨어요. \"마이라힐. 가서 낚시를 해. 두통이 나아질 게야.\" 이렇게 말씀하시죠.\n\n벌써 두통이 가신 것 같아요. 정말 고마워요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n파르독 장갑고리매듭 벨트강철죔쇠 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6143] = {title = "나가 퇴치", objective = "뱀갈퀴일족 미르미돈 7마리, 뱀갈퀴일족 나가 7마리, 뱀갈퀴일족 여마법사 5마리를 처치한 후, 잊혀진 땅의 그늘수렵 마을에 있는 드룰제가르와 대화해야 합니다.", description = "아는지도 모르겠지만, 나와 내 선원들은 북쪽 해안에 있는 난파선 북쪽, 라나즈자르 섬 근처로 낚시를 하러 갔답니다. 우린 전에도 늘 그곳에서 낚시를 하곤 했었는데, 이제 내가 하는 거라고는 쓰러져 간 내 동료들의 복수를 할 궁리뿐이군요.\n\n어느 날 아침 나가들이 우리를 공격했는데, 나만 빼고 나머지 선원들은 모두 죽임을 당했습니다.\n\n난 죄책감에 너무나 심하게 시달리고 있습니다. 당신이 가서 내 대신 나가 녀석들을 짓밟아 주고 와 주십시오. 사례는 충분히 할 생각이니, 도와 주지 않겠습니까?", progress = nil, completion = "나가들을 물리쳤다는 소식을 들으니 기쁘긴 하지만 그래도 아직 마음이 텅 비어 있는 것 같군요. 내 남은 평생을 나가들을 멸절시키는 데 헌신할 겁니다.\n\n자, 내가 약속했던 사례입니다. 나가 녀석들이 우리 선원들에게 저지른 끔찍한 일에 대한 대가를 치르게해준 데 대한 고마움에 비하면 아주 작은 선물이지만 말입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6144] = {title = "지휘 임무", objective = "언더시티로 가서 바리마트라스와 대화해야 합니다.", description = "난 명령을 받았네, <class> 친구. 바리마트라스님께서 언더시티로 보내 아주 민감한 전략 작전을 수행할 가장 '솜씨 있는' 요원을 보내라고 하셨지.\n\n유감스럽게도 가장 솜씨 있는 요원들은 벌써 3년 전에 다들 죽어 버렸고 지금 그들의 자리에는 아무 것도 모르는 애송이들만 있을 뿐이야.\n\n<차갑게 노려보는 나타노스>\n\n지금 당장 언더시티로 가서 바리마트라스님께 보고하게. 날 난처하게 만들지 말라고, <class> 친구!", progress = nil, completion = "십자군사령관은 자신의 군대가 그대의 땅에 쏟아져 들어가 그대의 건물과 기념비를 더럽히며 그대의 동족을 살해하는 동안 붉은십자군 성채에 안전하게 들어앉아 있지.\n\n어둠의 여왕께서는 이 벌레 같은 녀석을 영원히 처치해 버리라는 명령을 내리셨다. 바로 그대가 포세이큰이 내리는 징벌의 도구가 될 것이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6145] = {title = "진홍십자군 급사", objective = "동부 역병지대로 돌아가 진홍십자군 급사를 추적해야 합니다. 급사를 처치하고 십자군 사령관의 명령서를 회수해야 합니다.\n\n이 명령서를 나타노스 블라이트콜러에게 가져다주고 다음 지시를 받으십시오.", description = "머리 없이 몸만으론 살 수 없듯 머리 또한 몸 없이는 살 수 없는 법. 스트라솔름 내에 있는 붉은십자군 지도부의 방어는 거의 난공불락이지. 대신 우리는 머리 밑에서 몸을 절단해 버려야 해.\n\n내 죽음의추적자들이 스트라솔름 외부에서의 붉은십자군 동태에 대한 자료를 수집해 왔지. 녀석들은 매일 중앙 지도부에서 티르의 손 수도원으로 명령서를 보내고 있어. 바로 이 명령서가 열쇠야! 진홍십자군 급사를 찾아 그 명령서를 회수해서 나타노스에게 가져가도록 하라.", progress = "이번 일에 성공하면 자네는 나에게 존경을 받게 될 거야.", completion = "&lt;크게 웃는 나타노스&gt;\n\n아주 잘 했어! 드디어 붉은십자군 예언자를 쳐부술 기회가 왔군!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6146] = {title = "나타노스의 책략", objective = "마리스 농장 남동쪽에 있는 티르의 손 수도원으로 간 다음, 그곳에서 썩은 사과를 한 입 먹어야 합니다. 붉은십자군의 모습을 한 채로 십자군군주 발델마르에게 십자군 사령관의 명령서를 가져가야 합니다.", description = "내가 이 명령서를 조금 조작해 놓았네. 우리의 책략이 먹혀 든다면 녀석들이 붉은십자군 예언자를 노출시키게 될 거고 우리는 그 예언자를 치는 거야!\n\n자, 잘 들으라고, <class> 친구. 이 명령서를 십자군군주 발델마르에게 가져다 주게.\n\n어떻게 하냐고? 당연히 직접 전해 줘야지, 바보 같으니라고!\n\n명령서와 이 썩은 사과를 티르의 손 수도원으로 가져가게. 도시 안에 들어가거든 이 사과를 먹으라고. 그러면 인간들이... 좀 더 좋아하는 모습으로 변하게 될 거야. 이 명령서를 가져가서 십자군군주 발델마르에게 직접 건네주게.", progress = "이런 건 허용되지 않는다, 병사!", completion = "어디에 가 있었던 것인가? 스컬지에게 잡히기라도 한 줄 알았단 말이다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6147] = {title = "나타노스에게 돌아가기", objective = "이 새로운 정보를 가지고 나타노스 블라이트콜러에게 돌아가야 합니다.", description = "사령관께서 평소 같지 않은 요청을 하시는군. 흐음, 어쨌든... 명령이니 따를 수밖에. 붉은십자군 성채로 돌아가서 곧 예언자님을 호송하겠다고 전하게.\n\n예언자님께서 스트라솔름까지 무사히 도착하도록 만반의 준비를 하겠네.", progress = nil, completion = "바보들! 내 속임수에 그대로 걸려 들었구나! 준비하라고, &lt;class&gt; 친구. 우린 아주 서늘할 정도로 교묘하게 녀석들을 쳐야 하니까 말이야!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6148] = {title = "붉은십자군 예언자, 데메트리아", objective = "붉은십자군 예언가가 이동하고 있습니다. 티르의 손 수도원에서 스트라솔름으로 가는 길 어딘가에서 예언가인 데메트리아와 그녀의 호위병들을 찾을 수 있을 것입니다. 그녀를 추적해서 처치하고 성공하면 나타노스 블라이트콜러에게 돌아가야 합니다.", description = "데메트리아는 십자군사령관의 최고 조언가이지. 그녀는 그 초자연적인 감각 탓에 예언자라고 불린다네. 그녀는 스컬지와의 전투를 몇 번이나 승리로 이끄는 데 공헌을 세운 바가 있어.\n\n그녀를 노출시키는 책략은 먹혀 들었지만 정말로 그런 초자연적인 힘이 있는 여자라면 분명 어떤 문제가 일어나리란 걸 예상하고 있을 거야. 바로 그 '문제'를 자네가 일으키는 거지.\n\n예언자를 추적해서 처치하도록 하게. 우리가 얘기하고 있는 지금 티르의 손 수도원을 떠나고 있을 거야. 나를 뿌듯하게 해 달라고, 이 친구야.", progress = nil, completion = "하하, 녀석들이 앞으로 오랫동안 이번 타격에서 헤어나지 못하겠군! 잘 했네! 자네는 내 존경뿐 아니라 이 보상을 받을 자격도 얻은 거야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n피나무 활폭풍몰이 마법봉성스러운 수호방패\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6161] = {title = "랙모어의 보물을 찾아라!", objective = "랙모어의 은열쇠와 랙모어의 황금열쇠를 찾아 랙모어의 궤짝을 열어야 합니다.", description = "랙모어의 기록에는 페더문 요새를 향해 항해하던 그의 배가 바다 생물들에게 공격을 받았던 당시의 상황이 적혀 있습니다. 그는 자신의 보물이 적의 손에 넘어가지 않도록 하기 위해 라나즈자르 섬에 그의 궤짝을 숨겨 놓았습니다.\n\n그 궤짝을 열려면 은색과 금색의 두 열쇠가 필요합니다. 이 두 열쇠를 잃어 버렸지만 열쇠와 궤짝을 찾으면 보물을 손에 넣을 수 있습니다!", progress = "이 궤짝은 단단히 잠겨 있습니다.", completion = "궤짝이 열리며 랙모어의 보물이 모습을 드러냅니다!", rewards = "다음과 같은 것들을 받습니다:\n\n랙모어 선장의 키랙모어 선장의 손잡이"},
[6162] = {title = "남편의 마지막 전투", objective = "대군주 로르를 처치하고 그의 발톱을 악령의 숲, 피멍울 초소에 있는 드레카술에게 가져가야 합니다.", description = "우리 남편은 일족의 명예를 위해 악령의 숲으로 갔지. 어둠의 의회는 물론이고 숲에 있는 타락한 괴물들과 싸우러...\n\n어느 날 남편에게서 몇 번이나 죽을 고비를 넘겼다고 편지가 왔네. 그리고 어떤 드루이드를 도와 대군주 로르라는 타락한 펄볼그를 처치할 계획이라고 했어. 그런데 그 이후 아무 소식이 없다네.\n\n이 로르라는 녀석의 발톱을 가져다주게. 나를 과부로 만든 데 대한 대가를 치르게 하겠어! 그 녀석은 여기서 남쪽, 잿빛 골짜기 경계 근처에 있는 것 같네.", progress = "그 괴물은 처치했나? 녀석은 자기가 저지른 죄에 대한 대가를 치러야만 해. 녀석이 정말 타락한 본성을 지니고 태어났든, 단지 그런 암울한 숲에 사는 바람에 사나워진 것뿐이든 난 상관없어. 내 남편에게 그런 죄를 저지르고도 살아남을 펄볼그는 없으니까!", completion = "자네는 맡은 일을 끝까지 실행함으로써 내 남편의 명예를 되찾아 주었네. 사실 남편은 전투를 치르다 숨진 것이니 그 사실만으로도 스스로 자랑스럽게 여겼을 거야. 하지만 아직 한창 때인 날 한평생 독수공방 하도록 만든 그 짐승이 이 세상이 존재한다는 걸 생각하면 편히 잠도 잘 수 없더군.\n\n다시 한번 고맙네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6163] = {title = "람스타인", objective = "스트라솔름으로 가서 먹보 람스타인을 처치하고 그 증거로 그의 머리카락을 나타노스에게 가져가야 합니다.", description = "나는 완전히 압도당했어. 로데론 수호를 위해 바로 이 자리를 사수하고 있었을 때였어. 농장에 있던 모든 것이 거대한 스컬지 군단에게 습격을 당하고 말았지.\n\n그 쓰레기 같은 비열한 놈이 내 위에 우뚝 서 있었어. 그 모습이 너무 무시무시해서 난 그대로 눈을 감아버렸지.\n\n그리고 깨어났을 때 난 스컬지가 되어 있었지. 내 정신은 리치 왕의 정신에 압도되어 너무나도 오랜 세월 동안 아무 것도 할 수 없었지.\n\n그러던 어느 날 어디선가에서 그분이 날 찾아오셨어. 난 그분이 오실 줄 알고 있었지. 자유였어.\n\n그리고 이제 나는 복수를 해야만 해. 내 목숨을 앗아간 바로 그 녀석에게 말이야. 녀석을 처치해 주게.", progress = "실바나스 여왕님께서 날 해방해주신 후, 나는 그 괴물을 추적해 이 황무지를 몇 달 동안이나 돌아다녔지. 녀석은 안전한 스트라솔름으로 피신해 갔어. 더러운 녀석 같으니...", completion = "한 가지 궁금한 게... 자네가 녀석을 처치하려고 할 때 녀석이 자비를 베풀어 달라며 애걸하던가? 녀석이 자비가 뭔지 알기나 했을까 말이야.\n\n&lt;침을 뱉는 나타노스&gt;\n\n흥! 자네가 가져온 것을 내 벽에 걸어 놓겠어.\n\n이제 자네를 내 용사들 중 한 명으로 대접하도록 하지.\n\n&lt;경례하는 나타노스&gt;", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n알렉시스의 결혼반지정기의 고리\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6164] = {title = "아우구스투스의 회계장부", objective = "테러데일에 있는 정신나간 아우구스투스에게 아우구스투스의 회계장부를 가져가야 합니다.", description = "이제 장사를 시작할 준비가 됐소! 당신은 뭐야?\n\n앗, 잠깐... 내 회계장부가 없이는 가게를 열 수가 없지. 회계장부가 없으면 기록을 남길 수가 없잖아.\n\n이런... 마을 어딘가에 두고 온 모양이야. 여관에 방을 빌려놨는데, 아무래도 거기 있는 것 같군.\n\n내 회계장부를 가져다주게. 제발 부탁이니 좀 가져다 달라고! 내 회계장부를 가져오면 알게 될 거야! 내가 가게를 차리면 가격이 완전히 미친 듯이 날뛰고 있다는 걸 알 수 있을 거란 말이야!", progress = "내 회계장부는 가져왔소? 어서 장사를 다시 시작하고 싶단 말이야!", completion = "아, 여기 있군! 맙소사! 얼마나 빽빽하게 써 놨었는지 잊고 있었군!\n\n오늘은 아주 멋진 날이야! 황홀하고 좋아서 미칠 것만 같은 날이라고!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6181] = {title = "긴급 전갈", objective = "루이스의 쪽지를 가지고 그리핀 조련사 토르에게 가야 합니다.", description = "우린 스톰윈드에서 직접 도움을 받지는 않지만 장비 보급을 도와주는 연락책이 있기는 하오. 그의 이름은 오스릭 스트랑으로 가게를 하나 소유하고 있는 친구인데 가게의 이름은 품질보증 갑옷 상점으로 스톰윈드 구 시가지에 있소이다.\n\n우리의 갑옷 재고가 줄어 오스릭에게 연락해야 하니 그에게 이 쪽지를 전해 주겠소?\n\n우리의 그리핀 조련사 토르를 통하면 가장 빨리 스톰윈드로 갈 수 있을 것이오. 토르는 언덕 바로 밑에 있으니 이 쪽지를 가지고 그리핀을 타고 스톰윈드로 가도록 하시오.", progress = "꽤 바빠 보이시는군요. 그럼 제대로 찾아오신 겁니다!", completion = "이 쪽지를 스톰윈드로 가져가야 한다고요? 문제없습니다. 제 그리핀을 타세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6182] = {title = "처음이자 마지막 순찰대장", objective = "스톰윈드 구 시가지의 병영에 있는 단장 마티아스 쇼와 대화해야 합니다.", description = "나타노스 매리스는 인간으로는 처음이자 마지막으로 순찰대장이 되었던 자일세. 지금은 포세이큰의 밴시 여왕이 된 실바나스 윈드러너의 제자이지.\n\n우리는 나타노스가 5년 전 로데론을 방어하다 전사한 걸로 생각했었네. 그의 시체는 결국 못 찾았지만 동부 역병지대에서 살아나오지 못한 것으로 결론 내렸지.\n\n그동안 이 실종 사건에 대해 마티아스 쇼가 조사를 진행해 왔으니 새로운 정보를 알고 있을 것일세. 마티아스는 구 시가지의 병영에 있으니 당장 찾아가 보도록 하게.", progress = nil, completion = "동부 역병지대에서 포세이큰의 동태가 수상하다는 보고를 받고 SI:7 요원들을 보내 조사를 하도록 했지. 그런데 조사 결과가 아주 꺼림칙해.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6183] = {title = "망자에 대한 예의", objective = "이 임무를 수락하려면 마티아스 쇼와 다시 대화해야 합니다.", description = "가장 유능한 요원 다섯을 매리스 사건에 투입했지. 그 중 한 명만이 살아서 돌아왔는데 그마저도 사흘 후 자다가 숨졌다네.\n\n그에게서 간신히 알아낸 정보라고는 앞뒤가 맞지 않는 헛소리뿐이었어. \"나타노스\"와 \"블라이트콜러\"라는 딱 두 단어만 알아들었지.\n\n조사를 계속하기에는 인원이 모자라고 라벤홀트도 우리를 지원하지 않으려 하고 있네. 반드시 진상을 알아내야만 하는데 말이야. 적어도 매리스가 어떻게 죽었는지는 가족에게 알려줘야지... 자네가 도와주지 않겠나?", progress = nil, completion = "&lt;고개를 끄덕이는 마티아스&gt;\n\n난 볼바르님께서 믿을 만한 친구를 보내리라고 굳게 믿고 있었네. 얼라이언스에서 가장 헌신적인 병사를 말이야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6184] = {title = "플린트 섀도모어", objective = "서부 역병지대에 있는 서리바람 야영지로 가서 연락원인 플린트 섀도모어를 만나야 합니다.", description = "지금까지 알아낸 정보라고는 나타노스 매리스가 이 블라이트콜러라는 자에게 살해당했을지도 모른다는 것일세. 내 요원들을 처치한 것도 바로 이 블라이트콜러라는 악마일 것이라고 추정하고 있지.\n\nSI:7 요원인 플린트 섀도모어가 서부 역병지대의 얼라이언스 야영지인 서리바람 거점에 배치되었으니 그를 찾아가보게. 그 친구가 자네에게 역병지대의 현재 상황에 대해 알려주고 임무를 맡길 걸세.\n\n행운을 비네.", progress = nil, completion = "첫 임무는 간단하오. 살짝 들어갔다 나오는 정찰 임무지...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6185] = {title = "동부 역병지대 정찰", objective = "동부 역병지대에서 \"블라이트콜러\"와 실종된 SI:7 요원들에 대한 단서를 찾아야 합니다. SI:7 배지를 찾게 되면 서리바람 야영지에 있는 플린트 섀도모어에게 가져가야 합니다.", description = "이미 말했듯이 당신의 첫 임무는 정찰 임무요. 특별한 건 없고 그냥 동부 역병지대로 가서 이 블라이트콜러라고 하는 자에 대한 단서를 찾아오면 되는 거요.\n\n실종된 우리 요원들에 대한 정보도 놓치지 않도록 하시오. 일단은 죽었다고 가정하고 정말로 죽었다면 어딘가에... 시체가 있을 거요.\n\n<침을 꿀꺽 삼키는 플린트>\n\nSI:7 요원들은 모두 이런 표장을 달고 있소.\n\n<자신의 SI:7 표장을 보여주는 플린트>\n\n배지를 찾거든 모두 가지고 와주시오.", progress = "뭐... 뭐라도 찾았소??", completion = "루트거. 프레도. 투르옌. 모두들... 죽었군...\n\n&lt;배지를 꼭 거머쥐는 플린트&gt;\n\n어디들 있었소? 그 죽일 놈의 블라이트콜러에 대한 정보는 찾은 게 있소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6186] = {title = "블라이트콜러의 정체", objective = "스톰윈드로 대영주 볼바르 폴드라곤을 찾아가 나타노스 매리스의 운명에 대한 소식을 전해야 합니다.", description = "<얼굴에 핏기가 싹 가시는 플린트>\n\n나...나타노스가 이런 짓을 했단 말이오? 나타노스가 블라이트콜러란 말이오?\n\n어째서? 그... 그는 너무나도 고귀한, 모든 이의 존경을 받던 순찰대장이었는데... 하이 엘프 밑에서 훈련을 받을 수 있었던 유일한 인간이 이제는 포세이큰의 무자비한 요원이 되었단 말인가?\n\n이... 이런 부탁을 해서 미안하지만 이 일에 대해 폴드라곤 대영주님께 즉시 보고해야 하오. 부디 스톰윈드로 가서 이 소식을 전해주시오.", progress = nil, completion = "뭐... 그런... 말도 안 돼! 어째서? 포세이큰의 요원이라고? 밴시 여왕의 투사?\n\n&lt;크게 좌절하는 대영주 볼바르 폴드라곤&gt;", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6187] = {title = "질서 회복", objective = "군대를 동원해 동부 역병지대로 가서 나타노스 블라이트콜러 및 그를 보호하려는 호드와 전면전을 벌이십시오.\n\n호드는 죽을 힘을 다해 자신들의 순찰대장을 보호하려고 할 테니 정신을 바짝 차려야 합니다.", description = "이 세계에 순찰대장이 몇이나 되는지 아는가? 인간으로서 순찰대장 자리를 오른 사람이 몇이나 있었는지 아는가?\n\n나타노스는 전례 없이 훌륭한 업적을 이루었지. 십 년이나 계속된 전쟁 속에서 얼라이언스를 승리로 이끈 천재적인 전략가였어.\n\n하지만 지금은... 포세이큰의 투사가 되어버렸다니... 아니야. 이건 말도 안 돼. 질서를 회복해야 해.\n\n군대를 소집하게. 군대를 이끌고 역병지대로 돌아가 이 블라이트콜러라는 자를 처치하도록 하게.\n\n행운을 빌겠네. 이번 싸움에는 행운이 필요할 테니 말이야.", progress = nil, completion = "비극이야. 어쩌면... 우리 종족은 저주받은 것일지도 모르네. 가장 위대한 &lt;class&gt;, 가장 숭고한 영웅, 가장 뛰어난 학자를 잃어야 하는 저주 말일세.\n\n이번에 자네에게 큰 신세를 졌군. 나타노스 매리스가 지금 어디에 있든지 분명 자네에게 미소를 지어 보이고 있을 걸세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n피나무 활폭풍몰이 마법봉성스러운 수호방패\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6241] = {title = "눈사태일족의 동태", objective = "살파가 눈사태일족 토템술사, 보초, 길잡이를 각각 6마리씩 처치해달라고 요청했습니다.", description = "우리 나무구렁일족은 보통 남의 일에 잘 간섭하지 않소. 우리에게 신임을 얻은 자들은 무사히 지나가도록 해주고, 다른 펄볼그 부족과의 마찰은 가능한 한 피하려고 한다오.\n\n그런데, 최근 눈사태일족이 부쩍 우리를 공격적으로 대하고 있소이다. 공포와 증오에 완전히 휩싸여, 자신들이 이해하지 못하는 모든 것에 대해 광분해 있는 듯하오.\n\n당신이 놈들의 수를 줄일 수 있다면 우리에게 큰 도움이 될 거요, <name>.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[6261] = {title = "덩가 롱드링크", objective = "그리핀 조련사 덩가 롱드링크에게 오스릭의 상자를 가져가야 합니다.", description = "이 상자에 루이스가 부탁한 장비를 모두 넣었으니 루이스에게 전해주실 수 있으시겠습니까?\n\n서부 몰락지대에 있는 토르를 이미 만나 보셨다면 그리핀을 타고 다시 그리로 갈 수 있을 겁니다. 우리 그리핀 조련사인 덩가 롱드링크는 상업 지구에서 만날 수 있을 겁니다.\n\n덩가를 만난 후 이 상자를 최대한 빨리 루이스에게 전해 주십시오. 서부 몰락지대에 있는 전사들을 새 장비도 없이 전투에 내보낼 수는 없으니까요!", progress = "이마에 맺힌 게 땀인가요? 너무 뛰어다니셨군요. 다음부터는 그리핀을 타도록 하세요!", completion = "서부 몰락지대로 가져갈 상자라고 하셨습니까? 전에 그곳에 가 보신 적이 있으신가요? 그렇다면 문제없습니다. 그쪽으로 가도록 훈련한 그리핀이 많이 있으니까 말입니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6281] = {title = "스톰윈드로 이동", objective = "그리핀 조련사 토르에게 요금을 지급하고 그리핀을 탄 다음 루이스의 쪽지를 스톰윈드에 있는 오스릭 스트랑에게 가져가야 합니다. 오스릭은 스톰윈드의 구 시가지에 있는 품질보증 갑옷 상점에 있습니다.", description = "요금을 조금만 내시면 그리핀을 타고 스톰윈드로 가서 루이스의 쪽지를 오스릭에게 전할 수 있습니다. 다른 방법으론 이렇게 빨리 못 가실 겁니다.\n\n괜찮다 싶으면 준비를 끝내신 후 저에게 다시 오시기 바랍니다. 그리 비싸지 않은데다가 그만한 값어치는 될 겁니다!", progress = "여행하시는 분이시군요? 어디 흥미로운 곳이라도 있었습니까?", completion = "아, 병참장교 루이스가 보낸 쪽지로군요? 뭐, 장비가 더 필요하다는 건 그리 놀라운 일은 아니지요. 감시의 언덕은 스톰윈드에서 거의 잊혀진 머나먼 땅에 있으니 말입니다.\n\n어쨌든 고맙습니다. 수고해 주셨으니 여행 경비를 좀 드리도록 하지요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6282] = {title = "하피의 위협", objective = "해바위 야영지에 있는 마그그랜 어스바인더가 혈폭풍일족 하피, 복병, 암살자, 약탈자를 각각 7마리씩 처치해달라고 부탁했습니다.", description = "타우렌은 이 땅의 수호자 역할을 매우 자랑스러워하지. 그런 의미에서 자네는 내가 왜 돌발톱 산맥에 서식하는 하피의 숫자가 늘어나고 있는 것에 민감한지 이유를 알 수 있을 걸세.\n\n칼림도어에서 그 수가 늘고 있는 하피 중 가장 많은 것은 혈폭풍일족이지. 그들이 모든 생물들을 해치고 있는 형편이라 죄없는 생물들이 둥지에 숨어서 밖으로 나오지도 못할 지경이라네.\n\n자네가 이 골칫덩이들을 좀 처리해주지 않겠나?", progress = nil, completion = "정말 훌륭한 소식이군! 그 역겨운 하피들의 차가운 심장에 어떤 공포를 불어넣었는지 자세히 말해주게. 이번 일로 혈폭풍일족은 큰 타격을 받았을 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6283] = {title = "혈폭풍일족의 혈통", objective = "해바위 야영지에 있는 마그그랜 어스바인더가 혈폭풍일족 갈퀴발톱을 처치하고 그 증거로 그녀의 유해를 가져오라고 부탁했습니다.", description = "혈폭풍일족 하피의 수가 줄긴 했지만 그것만으론 충분하지 않네. 진정한 해결책은 그들의 우두머리인 혈폭풍일족 갈퀴발톱을 처치하는 거지!\n\n그녀는 그 더러운 떼거리의 여왕 노릇을 하고 있다네. 갈퀴발톱만 없앨 수 있다면 하피들의 숫자는 확실히 줄어들 거야.\n\n잿더미 계곡으로 돌아가게. 서쪽 언덕에 그녀가 있을 거야. 쉽지는 않겠지만 훌륭한 보상이 기다리고 있으니 보람이 있을 거야.", progress = "혈폭풍일족 갈퀴발톱은 정말이지 메스꺼운 존재야. 잿더미 계곡의 서쪽 언덕으로 가면 그녀를 찾을 수 있다네.\n\n그녀만 없앤다면 혈폭풍일족은 무력해질 테지. 자네가 그렇게만 해주면 그 무리를 영원히 제거하는 데 박차를 가할 수 있을 거야.", completion = "나에게서 그동안의 분노와 증오들이 점점 사그라져 가는 것이 느껴지는군. 우리의 땅에서 사악한 존재 하나가 사라졌으니 이젠 선한 일에만 집중하는 타우렌의 본분을 다할 수 있게 되었군.\n\n자, 수고에 대한 대가로 이걸 받아주게.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n마귀족 망토비명소리 허리띠\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6284] = {title = "거미의 공포", objective = "베스셀레스를 처치하고 그 증거로 베스셀레스의 송곳니를 들고 해바위 야영지의 마그그랜에게 가져가야 합니다.", description = "경고: 여기서 서쪽 방향에 있는 시쉬르 협곡은 매우 위험한 곳으로 여행자들의 주의가 요구된다. 베스셀레스와 발이 여덟 개 달린 그녀의 자식들이 그 협곡이 자기들만의 둥지라는 억지를 부리고 있다.\n\n해바위 야영지의 마그그랜 어스바인더는 이 흉포한 베스셀레스에게 현상금을 거는 바이다. 그녀를 처치하고 그 증거를 마그그랜에게 가져오는 자에게는 충분한 상을 내릴 것이다.", progress = "베스셀레스는 무자비한 포식자일세. 그래서 야밤에 그물누비 고개 쪽으로 가는 여행자들을 보면 무척 걱정이 돼. 베스셀레스와 그녀의 자식들이 무고한 여행자들을 덮치는 일이 잦기 때문이지. 나 역시 그녀에게 붙잡혀 먹이가 될 뻔했는데 운 좋게 도망칠 수 있었네. 그 괴물을 처치해만 준다면 무엇이라도 아끼지 않고 줄 수 있네.", completion = "&lt;name&gt;, 훌륭한 사냥이었어! 베스셀레스의 위협도 이제 지나간 역사의 한 페이지로 남겠군. 잘됐어... 그녀를 그리워하는 자는 아무도 없을 테고. 자네가 우리의 영웅이 되었음을 기념하는 물건으로 이 보상을 받아주게.\n\n\n\n이제 더욱 많은 이들이 어둠 속의 위협을 염려하지 않고 해바위 야영지로의 여행을 즐길 수 있겠군.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n구름돌 쇼트소드맑은수정 마법봉\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6285] = {title = "루이스에게 돌아가기", objective = "그리핀 조련사 덩가 롱드링크에게 요금을 지급하고 감시의 언덕으로 가는 그리핀을 탄 다음 오스릭의 상자를 감시의 언덕에 있는 루이스에게 가져가야 합니다.", description = "서부 몰락지대의 그리핀 조련사 토르를 만난 적이 있다면 제 그리핀을 타고 그곳으로 갈 수 있습니다.\n\n그리핀은 항상 수도로 날아갈 수 있도록 훈련이 되어 있지만 먼 곳에 있는 그리핀 조련사에게 가려면 그곳에 가 본 적이 있어야 한다는 건 반드시 기억해야 한답니다.\n\n당신은 이미 토르를 만나 보았으니 서부 몰락지대로 갈 준비가 되거든 다시 오시면 됩니다. 그곳에 도착하면 오스릭의 상자를 병참장교 루이스에게 가져갈 수 있을 겁니다.", progress = "스톰윈드에서 오는 길이오? 오스릭이 갑옷을 보냈소이까?", completion = "훌륭하오! 갑옷을 가져왔군! 갑옷이 필요한 이들에게 즉시 분배하겠소.\n\n고맙소. 당신의 노력이 큰 도움이 되었소. 이제 그리핀도 자유롭게 탈 수 있으니 자주 감시의 언덕으로 와서 우리를 도와주면 좋겠소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6301] = {title = "생태계의 순환", objective = "해바위 야영지에 있는 탐라 윈드필드가 가이아 씨앗 10개를 모아다 달라고 부탁했습니다.", description = "헛된 개발 야욕과 끊임없는 전쟁으로 돌발톱 산맥의 땅이 처참하게 파괴됐어요. 그 상처는 오직 대지모신의 축복만이 치유할 수 있답니다.\n\n<name>, 특별한 씨앗을 찾아 주세요. 이곳 돌발톱 산맥에서만 구할 수 있는 가이아 씨앗이라고 하는 물건인데, 해바위 야영지 북쪽의 땅거미 호수로 가서 물가를 찾아 보세요.\n\n그 씨앗들을 가져오면 주술의 힘을 부여해 바로 이 자리에서 싹을 틔우겠어요.", progress = "끊임없는 전쟁과 벌목으로 돈을 챙기려는 자들 때문에 생태계가 파괴되고 있어요. 가슴이 아프네요. 생태계의 순환을 돕고 대지에 생명체가 번성하려면 부탁드린 씨앗이 있어야 합니다. 가이아 씨앗은 가져오셨나요?", completion = "&lt;name&gt;, 가이아 씨앗을 가져오셨군요. 그럼 이제 조용히 지켜보시기 바랍니다. 어떻게 이 작은 씨앗에서 대지모신의 축복이 생명의 꽃을 피울 수 있는지 보여드릴 테니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6321] = {title = "공동묘지 장비 조달", objective = "포드리그의 주문서를 가지고 박쥐 조련사 카로스 라조크에게 가야 합니다.", description = "고위집행관 하드렉님께서 공동묘지로 무기를 운반하라고 하셨습니다. 스컬지와 스컬지보다 더 흉악한 놈들이 숲 속에 매복해 있는 상황에서 죽음의경비병들에게 필요한 장비가 없으면 안 된다고 하셨지요.\n\n뭐, 이 정도면 장비를 잘 갖추고 있기는 하지만 전쟁터에서 무기를 잃었을 때를 대비해서 예비 무기가 더 있어야 하는 것은 사실입니다.\n\n여기 언더시티의 무기 상인 고든 웬드헴에게 줄 명령서가 있습니다. 이 명령서를 가지고 박쥐 조련사인 카로스 라조크에게 가서 언더시티로 가는 방법을 알아보십시오.", progress = "당신 공적인 일로 찾아온 것 같군.", completion = "아, 물품 조달을 위한 주문서로군. 이걸 언더시티로 빨리 가져가고 싶은 거겠지? 공동묘지에 장비가 떨어지면 큰 일 나니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6322] = {title = "마이클 가레트", objective = "고든의 상자를 마이클 가레트에게 가져가야 합니다.", description = "공동묘지에서 사용할 장비를 이 상자에 넣어 두었습니다. 공동묘지에 있는 박쥐 조련사를 만나 봤다면 다시 그리로 갈 수 있을 것입니다.\n\n언더시티 박쥐 조련사인 마이클 가레트를 만나 보십시오. 그 친구가 공동묘지로 돌아갈 박쥐를 제공해 줄 것입니다.", progress = "먼 곳으로 가야 한다면 박쥐가 최상의 선택이지.", completion = "이 상자를 은빛소나무 숲에 있는 공동묘지로 가져가야 한단 말인가? 물론 가능하지. 내 박쥐는 매일 공동묘지로 날아간다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6323] = {title = "언더시티로 이동", objective = "박쥐 조련사 카로스 라조크에게 돈을 지급하고 언더시티로 가는 박쥐를 탄 다음 포드리그의 주문서를 언더시티에 있는 고든 웬드헴에게 가져가야 합니다.", description = "내 박쥐가 저렴한 가격으로 언더시티에 데려다 줄 것이니 준비가 되면 날 다시 찾아와서 어느 놈을 탈지 결정하도록 하지.\n\n고든 웬드헴은 언더시티 상업 지구에 있을 테니 내 박쥐가 거기에 내려 줄 거요.", progress = "전 최상의 상태로 무기를 보관하지요. 이 무기들은 모두 깨끗하게 손질이 되서 바로 사용할 수 있습니다.", completion = "공동묘지에서 사용할 장비라고요? 좋습니다. 어둠의 여왕님을 섬기는 자를 돕는 것은 언제든지 영광이지요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6324] = {title = "포드리그에게 돌아가기", objective = "박쥐 조련사 마이클 가레트에게 돈을 지급하고 공동묘지로 가는 박쥐를 탄 다음 고든의 상자를 공동묘지에 있는 죽음의경비병 포드리그에게 가져가야 합니다.", description = "공동묘지에 있는 박쥐 조련사는 카로스 라조크라네. 그를 만난 적이 있다면 내 박쥐를 타고 그리로 돌아갈 수 있다네.\n\n우리 박쥐는 언제든지 언더시티로 갈 수 있지만 더 먼 곳으로 가려면 타는 이가 전에 그곳을 방문해서 그곳의 박쥐 조련사를 만난 적이 있어야 하지.\n\n자네는 공동묘지에 있는 카로스를 만난 적이 있으니 박쥐를 타고 그곳으로 갈 수 있다네. 준비가 되면 다시 얘기하세나.", progress = "돌아 왔군요. 언더시티에서 장비를 가져왔습니까?", completion = "잘했습니다. 이 무기들이 우리 죽음의경비병들의 안전을 지켜 줄 것입니다.\n\n어둠의 여왕님을 위해 값진 일을 해주었군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6341] = {title = "텔드랏실의 물고기", objective = "네사의 수집물을 베스프리스투스에게 가져가야 합니다.", description = "루테란 마을의 물고기는 크기도 크고 수도 많기 때문에 낚시꾼들의 수입이 좋지요. 저는 이곳의 물고기를 다른 어종과 비교해보고 싶습니다.\n\n어둠의 해안에 있는 제 친구에게 보여주려고 여기 이렇게 물고기 뼈와 비늘을 모아 두었답니다. 제 친구의 이름은 레어드라고 하고 아우버다인 마을에서 생선 장사를 하고 있습니다.\n\n이것을 우리 마을 히포그리프 조련사 베스프리스투스에게 가져가서 아우버다인으로 가는 방법을 알아보세요.", progress = "무슨 일로 오셨습니까? 이동 수단이 필요하신 겁니까?", completion = "아, 이 물건을 아우버다인으로 가져가고 싶으시군요? 좋습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6342] = {title = "아우버다인으로의 비행", objective = "히포그리프 조련사 베스프리스투스를 통해 아우버다인까지 날아간 다음 네사의 수집물을 레어드에게 전해줘야 합니다.", description = "루테란 마을에서 아우버다인으로 가는 방법에는 두 가지가 있어요. 배를 탈 수도 있고, 히포그리프를 타고 하늘을 날아갈 수 있지요. 모두 빠르고 안전하지요. 하지만, 전에 히포그리프를 타보신 적이 없다면 꼭 권해드리고 싶군요.\n\n참, 여러 마을에 들르실 때마다 히포그리프 조련사들에게 인사를 해두시는 게 좋습니다. 그러면 다른 마을에서 다시 그곳으로 날아갈 수 있으니까요.\n\n자, 이 네사의 수집물을 레어드에게 전해주셔야죠? 아우버다인으로 날아갈 준비가 되면 다시 말씀하십시오.", progress = "텔드랏실에서 오신 분이로군요? 그쪽은 낚시하기가 좀 어떻습니까?", completion = "네사가 보낸 물건이로군요? &lt;name&gt;, 정말 감사합니다! 그녀가 제게 루테란 마을 근처에서 잡은 물고기 견본을 보내주겠다고 했었습니다. 이곳에서 잡히는 물고기와는 상당히 다를 것이라고 하더군요.\n\n세상에나! 이 근방 물고기보다 턱뼈가 두 배는 더 크군요! 게다가 이 비늘 좀 보십시오. 딱 제 주먹만 합니다! 정말 놀랍습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6343] = {title = "네사에게 돌아가기", objective = "레어드의 답장을 네사 섀도송에게 전달해야 합니다.", description = "네사에게 물고기를 비교한 소감을 전해줘야 합니다. 그녀가 텔드랏실 해안에서 잡는 물고기와 이곳 물고기가 얼마나 다른지 무척 궁금해 하고 있을 겁니다. 제 생각에 세계수가 그 주위의 생물에 영향을 미치고 있는 것 같기도 합니다.\n\n네사에게 제 말을 좀 전해 주시겠습니까? 히포그리프를 타고 루테란 마을로 되돌아가려면 히포그리프 조련사 케이레이 문피더에게 문의하십시오. 배를 이용하시려면 북서쪽에 있는 부두에서 정기적으로 출항하니 참고하십시오.", progress = "<name>, 벌써 아우버다인에서 돌아오시는 길인가요? 레어드는 만나보셨습니까?", completion = "매우 흥미롭군요. 이곳 물고기가 크긴 하지만 그렇게까지 다를 줄은 정말 몰랐습니다. 분명 어떤 이유가 있을 텐데...\n\n&lt;name&gt;, 정말 감사합니다. 그대가 가져온 소식을 마을 주민들과 의논해야겠습니다. 언젠가 이러한 현상의 원인을 반드시 발견할 겁니다. 잘만하면 이용해볼 수도 있겠죠. 그때까지는 뚜렷한 혜택을 볼 수 없을 테지만!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6344] = {title = "네사 섀도송", objective = "네사 섀도송을 만나야 합니다.", description = "제 친구 네사 섀도송은 루테란 마을의 낚시 상인입니다. 그녀가 지금 어둠의 해안으로 소포를 배달해줄 이를 찾고 있습니다.\n\n관심이 있으시면 다르나서스에서 루테란 마을로 가는 차원의 문을 통과하십시오. 그 문은 신전 정원 서쪽에 있습니다.", progress = nil, completion = "맞아요, 제가 어둠의 해안으로 소포를 배달할 급사를 찾았답니다. 그대가 도와주시겠습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6361] = {title = "가죽 묶음", objective = "크로스로드에 있는 와이번 조련사 데브락에게 가죽 묶음을 가져가야 합니다.", description = "내가 불모의 땅 짐승들에게서 벗긴 가죽 한 묶음을 썬더 블러프로 가져가야 하네. 거기서 아하누라는 동료가 가죽을 가공해 각종 용품을 만들 거든.\n\n이 가죽 묶음을 그에게 좀 가져다주겠나?\n\n썬더 블러프로 가장 빠르게 갈 수 있는 방법은 와이번을 타는 것이지. 와이번 조련사 데브락에게 가죽 묶음을 들고 가보게. 썬더 블러프로 가는 방법을 알려 줄 테니까.", progress = "와이번 때문에 왔다고? 배달 일이라도 맡은 모양이로군?", completion = "그 가죽 묶음을 썬더 블러프로 가져가려고 왔다면 제대로 찾아온 걸세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6362] = {title = "썬더 블러프로 날아가기", objective = "와이번 조련사 데브락에게 요금을 내고 썬더 블러프까지 날아간 다음 가죽 묶음을 아하누에게 전해줘야 합니다.", description = "저렴한 가격에 썬더 블러프로 가는 와이번을 태워주겠네. 그곳으로 가는 가장 빠른 방법이지!\n\n가격이 괜찮다 싶으면 떠날 준비를 하고 다시 말하게.\n\n그리고 말일세. 그 가죽 묶음을 아하누한테 가져가야 한다면 썬더 블러프 와이번 탑의 제일 아래층에 있는 헤와의 방어구점에 들러보게. 그를 찾을 수 있을 테니... 마침 우리 와이번이 도착할 장소도 바로 거기고 말이야!", progress = "당신 어깨에 묻어 있는 뿌연 먼지는 불모의 땅에서 온 것이 틀림없군. 혹시 내 친구 자안을 만났소?", completion = "오, 새 가죽 묶음이로군. 당장 작업에 들어가야겠어!\n\n고맙소. 이렇게 큰 일을 선뜻해주다니... 당신의 시간과 노고, 그리고 여행 경비에 대한 보상으로 사례금을 좀 드리겠소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6363] = {title = "와이번 조련사 탈", objective = "아하누의 가죽용품을 썬더 블러프에 있는 탈에게 가져가야 합니다.", description = "내가 만든 가죽 용품을 크로스로드의 자안이 팔겠다고 하는데 그에게 좀 가져다주시겠소?\n\n당신은 크로스로드에 가본 적 있고 그곳 와이번 조련사도 만났으니 썬더 블러프에서 와이번을 타고 그에게 갈 수 있을 거요.\n\n이 가죽 용품을 가지고 썬더 블러프 와이번 조련사 탈에게 가시오. 그에게 크로스로드로 가는 방법을 물어보면 알려줄 테니까 말이오.", progress = "안녕하시오? <class>|1이여;여;... 무얼 도와 드리면 되겠소?", completion = "이걸 크로스로드로 가져가야 한다는 말이오? 문제없소! 당신은 이미 그곳에 가본 적이 있고 데브락도 만났으니 내 와이번을 타고 그에게 돌아갈 수 있어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6364] = {title = "자안에게 돌아가기", objective = "와이번 조련사 탈에게 요금을 치르고 크로스로드까지 날아간 다음 아하누의 가죽용품을 자안 호크윙에게 가져가야 합니다.", description = "원하는 곳으로 날아가려면 예전에 그곳에 가본 적이 있어야 하고 거기 와이번 조련사와도 안면이 있어야 하오. 당신은 크로스로드에 가본 적이 있고 그곳 와이번 조련사 데브락도 만났으니 언제든지 요금만 내면 내 와이번을 타고 날아갈 수 있을 거요.\n\n크로스로드에 도착해 자안 호크윙에게 가죽용품을 전해줄 수 있을 테니까 준비가 되거든 말씀하시오.", progress = "<name>, 자네 썬더 블러프에서 오는 길인가? 가죽 묶음은 아하누에게 잘 배달해줬겠지?", completion = "아하누가 완성된 가죽용품을 들려 보냈다고? 정말 잘됐군. 요즘 크로스로드에는 사냥꾼과 모험가들이 구름처럼 몰리는 형편이라 장사가 아주 짭짤하게 된단 말이지. 이것도 내놓자마자 금세 팔릴 거야.\n\n내 부탁을 들어줘서 고맙네. &lt;name&gt;, 자네에게 신세를 졌군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6365] = {title = "오그리마로 고기 배달", objective = "자르그의 고기를 크로스로드에 있는 데브락에게 가져가야 합니다.", description = "내가 말이야, 최상급 부위를 몇 점 잘라 놓았는데 친구에게 좀 보내야겠어. 그리쉬카라고 하는데 오그리마에서 여관을 하나 운영하고 있다네. 이 고기를 배달 좀 해주겠나?\n\n가장 빠른 방법은 와이번을 타고 가는 거야. 크로스로드의 와이번 조련사 데브락에게 가서 오그리마로 가는 방법을 물어보면 되지.", progress = "목적지까지 최대한 빨리 가고 싶다고? 그렇다면 제대로 찾아왔군!", completion = "지금 이 고기를 오그리마로 배달해야 한다고 했나? 문제없지. 요금만 내면 내 와이번이 그곳까지 눈깜짝할 새에 데려다 줄 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6381] = {title = "새로운 생명", objective = "가이아 흙더미에 가이아 씨앗 10개를 심은 후, 마력 깃든 가이아 씨앗을 가지고 해바위 야영지에 있는 탐라에게 돌아가야 합니다.", description = "<class>|1이여;여;, 당신이 보신 것처럼 고통 받는 이 땅에서도 생태계의 힘은 아주 강력하게 순환하며 생명을 틔울 수 있답니다. 이러한 생명의 순환을 돕기 위해 우리는 맡은 소임을 다 해야 해요. 서쪽에 있는 파괴의 중심지, 잿더미 계곡에 이 씨앗들을 심어야만 합니다. 아직까지 상처를 받고 있는 그땅에는 하피와 성난 불의 정령들이 몰려 다니고 있을 테니 조심하세요.\n\n자, 제가 마법을 부여한 이 가이아 씨앗들을 가지고 가서 비옥한 가이아 흙더미에 심도록 하세요. 생명의 순환은 반드시 계속돼야만 해요!", progress = "그 씨앗들은 아주 튼튼해서 오염된 땅에 대한 저항력이 강하니 다른 식물들이 자라날 수 있는 기반이 되어 줄 거예요. 씨앗들이 자라나면 우선적으로 대지의 사악한 기운을 막고 상처받은 땅을 치유하겠죠. 그러면 언젠가 돌발톱 산맥도 다시 무성한 숲으로 되돌아 갈 수도 있을 거예요.\n\n가이아 씨앗은 모두 심으셨나요?", completion = "대지모신을 위해 큰 승리를 거두신 거예요. 시간이 흐르면 다른 좋은 일들도 일어나겠죠. 투자개발회사는 톱과 도끼를 모두 거두고, 불의 정령들은 분노를 삭혀 평온해지고, 하피들은 이 땅에서 물러나게 될 거예요.\n\n그렇게 되어야만 돌발톱 산맥에 진정한 평화가 깃들게 될 겁니다.\n\n수고하셨어요, &lt;class&gt;님! 오늘 이곳에 꽃피워 주신 새로운 생명에 대한 감사의 표시이니 이 물건들 중 하나를 골라 가지세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n바람나그네 장화모래탑 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6382] = {title = "잿빛 골짜기 사냥 대회", objective = "잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트를 만나야 합니다.", description = "<class>|1이여;여;, 그대의 강인함에 깊은 감동을 받았네. 사냥에 대한 열정을 보니 이제 더 큰 사냥감... 그러니까 더욱더 어려운 도전을 해도 되겠다는 확신이 드네.\n\n잿빛 골짜기의 숲에는 야생 동물들이 방대하게 서식하고 있는데 호드에서는 정치적, 영적 목적으로 그들을 조종하려고 하지. 아직 이렇다할 영웅이 배출되지 않은 곳에서 자신을 증명해 보이고 싶다면 토막나무 주둔지에 있는 세나니 썬더하트의 인도를 받게. 불모의 땅에서 나오는 길을 따라 똑바로 북쪽으로 가면 된다네.", progress = nil, completion = "새로운 개척지로 온 것을 환영합니다. &lt;name&gt;, 잿빛 골짜기는 당신 같은 젊은이들이 힘과 용기를 시험할 기회를 충분히 제공하고 있습니다. 일단 이 주둔지를 살펴본 다음 조람 해안으로 나가 보는 것도 잊지 마십시오. 거기에 또 다른 호드의 주둔지가 있습니다.\n\n그나저나 여기까지 온 것을 보니 사냥에 대해 더 많은 교훈을 배우러 온 것 같은데... 그렇다면 제 말을 경청해 주십시오. 원하는 바를 기꺼이 가르쳐 주겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6383] = {title = "잿빛 골짜기 사냥 대회", objective = "잿빛 골짜기 사냥 대회는 세 마리의 전설적인 야수들을 목표로 합니다. 그들의 노련함과 힘에 견주어 자신을 시험해 보십시오. 그렇게 강한 존재와 부딪쳐 나가다 보면 자기 자신에 대해서 무언가 배울 수 있을 겁니다. 그 야수들은 우르산고우스라는 이름의 곰, 샤둠브라라는 고양잇과 흑호, 뾰족발톱이라는 히포그리프입니다.\n\n잿빛 골짜기 사냥 대회의 목표물은 워낙 강력하기 때문에 친구들의 도움이 필요할 수도 있을 것입니다. 성공하면 그 증거를 가져오시기 바랍니다.", description = nil, progress = nil, completion = nil, rewards = nil},
[6384] = {title = "오그리마로 날아가기", objective = "와이번 조련사 데브락에게 요금을 치르고 오그리마까지 가서 자르그의 고기를 그리쉬카에게 배달해야 합니다.", description = "요금만 낸다면 내 와이번으로 오그리마까지 데려다 주겠어. 그곳에 도착하면 수월하게 자르그의 고기를 그리쉬카에게 갖다 줄 수 있을 걸세. 와이번이 그 근처 하늘탑에 내려 줄 테니까 힘의 골짜기에 있는 그리쉬카의 여관으로 쉽게 갈 수 있을 걸세.\n\n갈 준비가 되면 다시 얘기하게나.", progress = "당신에게서 맛있는 냄새가 나는군요! 혹시 고기를 가지고 오셨나요?", completion = "아, 맛있겠다! 최상급 부위잖아요! 자르그가 보낸 건가요? 그 오크는 어떻게 하면 여자의 마음을 얻는지 제대로 알고 있다니까요.\n\n얼른 요리해 먹고 싶어서 못 견디겠네요. 너무 오래 익히면 안 되겠죠! 고기는 설익어야 제맛이거든요. 그렇지 않나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6385] = {title = "와이번 조련사 도라스", objective = "그리쉬카의 편지를 오그리마에 있는 도라스에게 가져가야 합니다.", description = "제가 자르그에게 감사의 편지를 썼거든요. 당신이 좀 전달해 주시겠어요? 이미 크로스로드의 와이번 조련사를 만나 보셨다니 다시 와이번을 타고 그리로 가실 수도 있겠죠?!\n\n이 편지를 가지고 오그리마에 있는 와이번 조련사 도라스에게 가세요. 그에게 크로스로드로 가는 방법을 물어보면 될 거예요.", progress = "내 와이번이 필요하다고?", completion = "이걸 불모의 땅에 있는 크로스로드까지 가져가야 한다는 말이지? 그럼... 데려다 줄 수 있고말고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6386] = {title = "크로스로드로 돌아가기", objective = "와이번 조련사 도라스에게 요금을 치르고 크로스로드까지 간 다음 그리쉬카의 편지를 자르그에게 전달해야 합니다.", description = "내 와이번은 여러 장소로 날아갈 수 있도록 훈련이 되어 있지. 단, 자네가 이미 전에 한번쯤은 다녀온 적이 있고, 그곳 와이번 조련사와 얘기를 나눈 곳까지만 데려다 줄 수 있다네.\n\n자네는 크로스로드에 들렀고 그곳 와이번 조련사 데브락도 만났으니 여기서 바로 갈 수 있어... 크로스로드에 도착하면 그리쉬카의 편지를 자르그에게 전해 줄 수 있겠지.\n\n하늘에 오를 준비가 되면 다시 얘기하게나.", progress = "오그리마에서 오는 길인가? 내가 보낸 고기를 그리쉬카가 좋아하던가?", completion = "하하! 암, 내 그럴 줄 알았어! 촉촉한 육즙이 흐르는 큼직한 스테이크만큼 여인의 볼을 붉게 물들이는 것도 없지!\n\n고마워! 정말 큰 일을 해줬어. 그 보답으로 사례를 좀 하지. 나중에 청첩장을 받아보고 놀라지는 말게! 다 자네 덕이니까... 이거 근사한 옷이라도 한 벌 빼줘야 하나?!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6387] = {title = "명예의 곡괭이", objective = "브록의 목록을 텔사마에 있는 토르그룸 보렐손에게 가져가야 합니다.", description = "많은 드워프 젊은이들이 내게 채광을 배우러 찾아옵니다만 광부에게 진정 필요한 게 있다면 그건 훌륭한 곡괭이지요!\n\n저는 수제자 목록을 따로 만들어 훈련에서 높은 점수를 받은 자들에게 명예의 곡괭이를 수여합니다. 이 목록을 아이언포지에 있는 골니르 보울더토에게 갖다주십시오. 곡괭이를 준비해 줄 겁니다.\n\n참, 아이언포지로 가장 빠르게 이동하는 방법은 그리핀을 타는 것입니다. 목록을 가지고 그리핀 조련사 토르그룸 보렐손에게 가십시오. 아마 아이언포지로 갈 방법을 일러줄 겁니다.", progress = "텔사마를 실컷 둘러봤나? 벌써 다른 도시로 떠날 채비를 끝낸 건가?", completion = "그러니까 이걸 아이언포지로 가져가야 한다는 말인가? 요금만 좀 내면 내 그리핀에 태워서 그리로 보내 주지. 어때?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6388] = {title = "그리스 서든", objective = "명예의 곡괭이를 들고 아이언포지에 있는 그리스 서든에게 가야합니다.", description = "여기 있습니다. 브록의 수제자들에게 줄 명예의 곡괭이에요! 당신은 이미 텔사마에 가본 적이 있으니 이번에도 그리핀을 타고 다시 그리로 갈 수 있을 겁니다.\n\n자, 이 곡괭이를 들고 그리핀 조련사 그리스 서든에게 가세요. 텔사마로 갈 방법을 일러 줄 테니까요.", progress = "어디 꼭 가야할 데가 있는 것처럼 보이는군요. 내 그리핀이 필요합니까?", completion = "이걸 텔사마로 가져가야 한다는 말이로군요? 문제없죠. 당신은 이미 텔사마에 다녀오신 적이 있고 토르그룸 보렐손과도 안면이 있는 분이니, 제 그리핀을 타고 돌아가실 수 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6389] = {title = "역병 퍼뜨리기", objective = "북마루 벌목지에 역병지대 흰개미를 놓아준 다음 역병지대 흰개미 통을 가지고 서부 역병지대 서리바람 야영지에 있는 너대니얼 두마에게 돌아가야 합니다.", description = "벌목지를 둘러보며 통을 열 도구를 찾습니다. 그리고 적당한 쇠지렛대를 발견합니다.\n\n쇠지렛대에 발을 얹어 통을 열면서 마음 속으로는 흰개미들이 공격하기 전에 벌목지를 빠져나갈 수 있기를 기도합니다.", progress = "성공했소? 흰개미들을 풀어놓았소? 붉은십자군이 벌목지와 하스글렌을 모두 차지한다면 우리는 정말 성스러운 빛의 도움이 필요할 것이오. 그들에게 벌목지와 하스글렌을 내주어선 안 되오. 지난 전쟁의 희생자들을 이용하다니 광견병에 걸린 동물처럼 죽임을 당해도 싼 녀석들이오!", completion = "하하! 고맙소! 해냈군! 이제 아버님의 혼이 편히 쉴 수 있게 됐소. 나도 평화로이 살 수 있겠군.\n\n다시 한 번 감사 드리오. 내가 도울 일이 있다면 언제든지 얘기만 하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6390] = {title = "역병 퍼뜨리기", objective = "북마루 벌목지에 역병지대 흰개미를 놓아준 다음 역병지대 흰개미 통을 가지고 트리스팔 숲 보루에 있는 미키 레빈에게 돌아가야 합니다.", description = "벌목지를 둘러보며 통을 열 도구를 찾습니다. 그리고 적당한 쇠지렛대를 발견합니다.\n\n쇠지렛대에 발을 얹은 후 통을 열면서 흰개미들이 공격하기 전에 벌목지를 빠져나갈 수 있기를 기도합니다.", progress = "성공했습니까? 벌목지에 흰개미들을 풀어놓으셨습니까?\n\n우리 가족의 목숨을 잃은 것도 분한데 어린 시절을 보낸 곳을 소위 거룩하다는 자들이 점령하다니... 역겹기 그지없군요!!", completion = "고맙습니다. 이 돈을 받으십시오. 더 드리지 못해 죄송합니다만 붉은십자군이 일구어 놓은 성과를 망쳐 놓았다는 것에 위안을 얻으시면 되지 않겠습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6391] = {title = "아이언포지로 날아가기", objective = "그리핀 조련사 토르그룸 보랠손에게 요금을 내고 아이언포지까지 간 다음 브록의 목록을 골니르 보울더토에게 가져가야 합니다.", description = "내게 요금으로 몇 닢만 내면 그리핀에 태워 아이언포지에 보내주겠네. 그리로 가면 브록의 목록을 골니르 보울더토에게 전달할 수 있을 거야. 깊은산속 광부 조합으로 가면 그를 만날 수 있을 걸세. 아이언포지 대용광로 지구로 가면 되지. 어차피 내 그리핀이 거기 내려 줄 테니 찾기 쉬울 거야!\n\n떠날 채비가 끝나면 다시 말하게나.", progress = "무얼 도와 드릴까요?", completion = "오, 브록의 수제자 명단이 적혀있는 목록을 가져오셨군요. 자, 여기 명예의 곡괭이를 준비해두었습니다. 목록에 있는 이름들만 새겨 넣으면 끝나니... 바로 드리지요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6392] = {title = "브록에게 돌아가기", objective = "그리핀 조련사 그리스 서든에게 요금을 치르고 텔사마로 간 다음 명예의 곡괭이를 브록 스톤시커에게 배달해야 합니다.", description = "요금만 내시면 그리핀을 타고 텔사마로 갈 수 있습니다. 단, 이미 그곳에 가봤다면 말입니다. 그러니까 이미 가본 곳만 그리핀을 타고 갈 수 있다는 말이니 어떤 지역을 방문하게 되면 그곳 그리핀 조련사를 꼭 만나보세요. 그래야 나중에 그리로 다시 날아갈 수 있으니 말입니다.\n\n당신은 이미 텔사마의 그리핀 조련사 토르그룸을 만났으니 그리로 돌아갈 수 있겠군요. 텔사마로 가면 곡괭이를 브록 스톤시커에게 배달할 수 있을 거예요.\n\n갈 채비를 마치시면 다시 말씀해주세요.", progress = "오, <name>... 아이언포지에서 돌아오는 것입니까?", completion = "좋았어! 곡괭이를 가져왔군요. 나의 수제자들에게 줘야지. 얼른 이 곡괭이로 모단 호수의 알짜배기 광석을 캐고 싶어 잔뜩 기대하고 있답니다.\n\n도와줘서 고맙습니다, &lt;name&gt;. 당신에게 큰 빚을 졌군요. 이 돈이 당신의 여행에 조금이라도 보탬이 됐으면 좋겠군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6393] = {title = "정령들의 전쟁", objective = "해바위 야영지에 있는 츄나만에게 발화석 10개를 가져가야 합니다.", description = "해일의 심판장에서는 이곳 돌발톱 산맥에 벌어지고 있는 불의 정령들과의 대전쟁을 위해 저를 보냈어요. 우리 물의 정령들의 군주, 바다의 사냥꾼 넵튤론께서는 이 세계에서 모든 불의 정령들이 사라지는 그날을 기다리고 계시죠.\n\n<name>, 제가 해일의 심판장에서 인정을 받을 수 있도록 잿더미 계곡에 있는 불의 정령들을 파괴해 주셨으면 해요. 불의 정령들이 파괴되면서 남기는 발화석을 모아 주시면 마땅한 사례를 할게요.", progress = "해일의 심판장에서 매우 초조해 하고 있어요. 아제로스 물질계의 모든 차원을 아울러 맹위를 떨쳐온 이 전쟁을 끝내고 싶어 하죠. 우리 형제들이 그 혐오스러운 불의 정령들을 꺾었다는 영광의 소식을 애타게 기다리고 있어요. 제가 부탁드린 발화석은 모아 오셨나요?", completion = "제 속의 물의 영혼들이 흥분의 거품을 터뜨리며 기쁨을 감추지 못하는군요. 해일의 심판장에 영광스러운 승전의 소식을 전할 수 있게 해주셔서 정말 감사 드립니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6394] = {title = "타즈릴의 곡괭이", objective = "타즈릴의 곡괭이를 작업반장 타즈릴에게 돌려주어야 합니다.", description = "<name>, 당신은 이곳에서 믿을 만한 <race>|1으로;로; 정평이 나있소. 다른 임무도 좀 맡아 보시겠소?\n\n얼마 전 나는 광물을 찾기 위해 북쪽에 있는 동굴을 조사하다가 그만 제일 아끼는 곡괭이를 두고 왔소이다. 나중에 찾으러 갔더니만 글쎄 포악한 짐승들로 동굴이 꽉 차있지 뭐요?! 그 동굴은 불타는 칼날 소굴이라고 한다오. 거기 가서 내 곡괭이를 좀 가져다주시겠소?\n\n폭포가 있는 곳에 곡괭이를 두고 왔소이다. 그 곡괭이에는 마법이 걸려 있기 때문에 어둠 속에서도 볼 수 있을 거요. 당신이 장님만 아니라면 헛걸음할 걱정은 안 해도 된다는 얘기지. 단, 그걸 지키고 있는 짐승들은 걱정해야 할 거요!", progress = "불타는 칼날 소굴에는 들어가 봤소? 내 곡괭이는 찾아오셨소이까?", completion = "훌륭해! 찾았군! 고맙소, &lt;name&gt;. 그건 내가 제일 아끼는 곡괭이요! 휴, 한시름 덜었어... 이제 일꾼들이 저 거대한 나무만 다 베면 맘 놓고 채광할 만한 동굴을 찾을 수 있을지도 모르겠군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6395] = {title = "말라의 마지막 소원", objective = "사무엘 핍스를 처치하고 그의 유골을 말라의 묘로 옮긴 다음 수련사제 엘레스에게 돌아가야 합니다.", description = "제 친구 말라 핍스는 역병이 퍼지기 전에 남편 사무엘과 함께 살았답니다. 하지만 역병이 퍼지고 사무엘은 스컬지의 전사가 되고 말았지요.\n\n말라는 언데드가 되는 꼴은 면했지만 이성을 상실한 남편 손에 그만 죽고 말았답니다. 하지만 말라의 사랑이 너무 큰 나머지 사랑하는 남편과 함께 묻히고 싶다는 마지막 소원을 빌었어요.\n\n사무엘 핍스는 데스넬 북동쪽 길에 있는 버려진 야영지를 배회하고 있답니다. 그와 싸워 이겨 말라의 소원을 들어주세요. 우리 묘지의 첫 번째 줄에 있는 말라의 묘에 그를 묻으시면 됩니다.", progress = "죽은 자들을 존중해야 한답니다. 그게 우리가 스컬지와 다른 점이죠.", completion = "좋은 일을 해 주셨군요! 그렇다고 스컬지와의 싸움이 끝난 것은 아니지만 말라와 사무엘이 마지막 안식처에서 평화롭게 쉴 수 있기를 바랄 뿐이에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6401] = {title = "카야의 생존 소식", objective = "해바위 야영지에 있는 탐라 윈드필드에게 기쁜 소식을 전해야 합니다.", description = "해바위 야영지에 있는 카야의 숙모 탐라 윈드필드에게 그 아이가 살아 있다는 기쁜 소식을 전해 주게! 우리는 마을이 침략을 받은 후 카야가 실종된 걸로 생각하고 있었다네. 해바위 야영지는 서쪽으로 난 길을 곧장 따라가면 된다네.", progress = nil, completion = "오, 내 사랑하는 조카 카야가 살아 있었군요! 정말로 기쁜 소식이에요. 정말 고맙습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6402] = {title = "스톰윈드 회합", objective = "스톰윈드 도시 성문으로 가서, 수습기사 로우와 대화하면 그가 당신의 도착을 치안대장 윈저에게 알릴 것입니다.", description = "스톰윈드 성문에서 윈저님을 만나도록 하시오.\n\n윈저님이 밝힐 내용은 왕국의 기반을 흔들 것이오!\n\n혼자 가지 말고 군대를 모아서 가시오! 동료들을 모으시오. 전투를 준비하시오!", progress = nil, completion = "시작하기 전에 군대를 모아 오시오. 우리가 상대할 것은 용이니 말이오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6403] = {title = "대단한 가장무도회", objective = "레지널드 윈저를 따라 스톰윈드를 통과해 왕궁으로 가야합니다. 윈저를 보호하십시오!", description = "아주 대단한 모험이었소, 친구. 당신에게 아주 큰 신세를 졌소이다. 혹시 일이 모두 끝나면...\n\n당신도 이제는 확실히 알게 되었겠지만 여군주 프레스톨은 데스윙의 후예이자 검은바위 첨탑의 군주 네파리안의 쌍둥이인 오닉시아요.\n\n그녀는 너무도 오랫동안 그 매혹적인 눈매로 우리 왕국을 사로잡아 왔지. 대영주님마저도 오닉시아의 농간에 조종당하는 꼭두각시가 되어 버렸지만 그 모두가 오늘 끝나는 거요... 오늘이 사악한 용의 마법 주문을 깨어 버리는 영광스러운 날이 되는 거요.\n\n우리가 함께라면 반드시 승리할 테니 걱정하지 마시오!\n\n자, 준비는 됐소?", progress = "나... 나... 나는 무능했네.", completion = "&lt;산산조각난 메달을 집어드는 볼바르&gt;\n\n이 메달 조각에 들어 있는 마법을 되살려야 하네. 용의 눈을 조율해야 해.\n\n윈저의 희생으로 우리 왕국은 자유로워졌지만 오닉시아와 그 일당의 위협은 계속 다가오고 있다네.\n\n이 메달에 내 몸과 마음이 사로잡혀 있었지만 이 메달로 오닉시아의 마음도 들여다볼 수 있었다네. 그래, 오닉시아의 비밀 말이야. 지금은 그 환영이 흐려지긴 했지만 아직 기억하는 게 몇 가지 있다네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6421] = {title = "구릉바위 협곡", objective = "구릉바위 협곡에 있는 동굴을 탐사한 다음 해바위 야영지에 있는 모르로갈에게 리조나이트 수정 10개를 가져가야 합니다.", description = "이곳 돌발톱 산맥에 뭔가 수상한 일이 벌어지고 있는 것 같아. 바람에 실려 전해져 오는 이 긴장을 자네도 느낄 수 있나?\n\n여기서 남동쪽으로 구릉바위 협곡에는 깊은 동굴이 하나 있네. 그곳에선 코볼트들이 리조나이트라는 희귀한 수정을 미친 듯이 캐고 있지. 그 표본이 좀 필요하네. 그리고, 동굴 깊숙한 곳까지 들어가서 뭐가 있는지 좀 조사해 주게.\n\n어서 떠나게. 난 이 산맥 깊은 곳에 어떤 악의 무리가 숨어 있는지 반드시 알아내야만 해.", progress = "구릉바위 협곡에서 뭔가 발견했나? 사실 전에 리조나이트에 관한 전설을 들은 적이 있어서... 그 동굴에는 들어가기 꺼려지는군. 동굴 깊은 곳에 무엇이 있는지 알면 놈들의 계획을 짐작이라도 할 수 있을 텐데...", completion = "바로 이거야! 리조나이트 수정에 토석인의 흔적이 남아 있군. 코볼트들이 토석인을 발견하려고 동굴을 샅샅이 파헤친 게 분명해.\n\n전설에 따르면 티탄들이 토석인을 창조했다지. 토석인을 이용해 우리가 지금 밟고 서 있는 이 땅을 창조했어. 그래, 이건 분명 그냥 지나칠 수 없는 위협이야.\n\n&lt;고개를 끄덕이는 모르로갈&gt;\n\n이 광석 표본에 마력을 부여하면 코볼트의 계략에 대항할 수 있을 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6441] = {title = "사티로스의 뿔", objective = "사티로스의 뿔 16개를 모아 토막나무 주둔지에 있는 픽셀에게 가져가야 합니다.", description = "안녕하세요! 전 잿빛 골짜기를 지나 톱니항으로 가던 길에 이곳 토막나무 주둔지에 잠깐 들렀지요. 돈벌이가 될 만한 걸 늘 찾아보는데, 요즘 톱니항에서는 사티로스 뿔의 수요가 아주 큰가 봐요.\n\n이 주변에서 물어봤더니 어둠의 터, 사티르나르, 그리고 사비안의 사티로스들이 제가 찾고 있는 뿔을 갖고 있는 것 같더군요. 전 그런 사티로스들의 상대로는 어림도 없지만... 당신은 해볼만 할 것 같네요!\n\n제게 그 뿔을 모아주시면 후하게 사례를 하겠어요.", progress = "<name>, 뿔을 빨리 모아주셨으면 좋겠어요. 곧 톱니항으로 떠나야 하거든요!", completion = "품질이 더할 나위 없이 좋은 물건들이네요! &lt;name&gt;, 도와주셔서 고맙습니다!\n\n아, 그리고 이건 수고해 주신 데 대한 사례예요...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6442] = {title = "조람 해안의 나가", objective = "조람 해안에 있는 마루카이에게 성난지느러미일족의 머리 20개를 가져가야 합니다.", description = "해안가에 악마가 출몰하고 있습니다.\n\n오래전 멸망하여 바다 밑에 가라앉은 도시, 조람이 묻혀 있는 곳에 말입니다. 세인들의 기억에서 거의 잊혀진 잃어버린 도시이죠.\n\n최근 어떤 이유 때문인지는 모르지만 나가들이 다시 나타났어요. 이유야 어떻든 우리가 차지하기 위해 그렇게 열심히 애썼던 땅이니만큼 꼭 지켜내야 합니다.\n\n녀석들의 머리 20개를 가져오세요! 나가 녀석들을 다시 심연 속으로 처넣으세요!", progress = "나가들의 수가 늘어나고 있습니다. 부디 절 위해 이 임무를 완수해 주십시오.", completion = "이 근처에 당신 같은 분이 더 있었으면 좋겠군요. 도와 주셔서 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6461] = {title = "식탐꾼들", objective = "말라카진에 있는 젠질라가 동굴이끼 땅거미 10마리와 동굴이끼 독거미 7마리를 처치해달라고 부탁했습니다.", description = "이곳 말라카진에 사는 우리 트롤은 대지의 축복으로 번성해 왔습니다. 돌발톱 산맥은 자원을 넉넉히 공급해주는 거대한 사냥터였고요.\n\n그런데 최근 들어 저녁 식사 때쯤이면 어김없이 초대도 받지 않은 손님들이 나타난답니다. 돌발톱 산맥의 거미들이 어둑어둑해질 때만 되면 우리가 사냥해 놓은 음식을 노리고 공격하지 뭐예요.\n\n이 불쾌한 놈들을 좀 없애주신다면 우리 말라카진 트롤들이 충분한 보답을 하겠습니다. 돌발톱 산맥 어디를 가나 그 징글징글한 거미들을 쉽게 찾을 수 있답니다. 여기서 북쪽으로 조금만 가면 제 말이 사실이라는 걸 확인할 수 있을 거예요.", progress = nil, completion = "정말 기쁜 소식이로군요. 덕분에 오늘 밤 저녁 식사에는 초대도 하지 않은 손님들이 몰려올 일은 없겠습니다.\n\n당신에게 큰 빚을 졌습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6462] = {title = "트롤 부적", objective = "조람가르 전초기지에 있는 미쑤와에게 트롤 부적 8개를 가져가야 합니다.", description = "내 동족들이 신성한 트롤 부적을 지니고 이곳을 지나던 중에 엉겅퀴일족 펄볼그들에게 공격을 당해 몰살당했다네! 조람가르에 도착하기 전에 말일세. 망할 놈의 펄볼그들!\n\n죽임을 당한 내 피붙이들이 그립긴 하지만 다음 생에서 다시 만나게 될 테니 괜찮아... 하지만 그들이 가지고 있던 트롤 부적은 이 세계에서 아주 큰 가치가 있는 것이지. 펄볼그들이 그 부적들을 가지고 있다는 건 참을 수 없어!\n\n그 부적들을 꼭 찾아주게! 아스트라나르 북쪽에 있는 엉겅퀴 마을 끝에 가면 엉겅퀴 소굴이라는 동굴이 있는데, 거기 궤짝 안에 들어 있을 거야.", progress = "부적은 찾았나, <name>? 내 피가 분노로 끓고 있어! 펄볼그들이 그 성스러운 물건을 더럽히고 있다고 생각을 하면 참을 수가 없네.", completion = "찾았군! 고맙네! 정말로 고마워, &lt;name&gt;! 이게 얼마나 중요한 일인지 자네는 모를 거야.\n\n부적이 없는 트롤은 몸에 흉터가 하나도 없는 민숭민숭한 오크나 마찬가지야...\n\n그러니까... 아무짝에도 쓸모가 없단 얘기지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6481] = {title = "토석인이여 깨어나라", objective = "마력 깃든 리조나이트 수정으로 리조나이트 광석을 연 다음 고게로크를 처치해야 합니다. 그를 처치했다는 소식과 마력 깃든 리조나이트 수정을 들고 모르로갈에게 돌아가십시오.", description = "자네는 이 땅에 드리운 악의 위협 한 가지를 밝혀냈어. 자네가 그 동굴에서 발견한 리조나이트 광석에는 고게로크라는 이름의 토석인이 갇힌 채 잠들어 있다네.\n\n주술의 힘을 이용하여 자네가 가져온 리조나이트 수정의 원소 조합을 바꾸었네. 마력이 깃든 이 리조나이트 수정으로 토석인이 갇혀 있는 리조나이트 광석을 열게.\n\n광석을 열면 토석인이 깨어날 텐데, 막 깨어난 고게로크의 힘은 그리 세지 않을 테니 즉시 처치할 수 있을 거야.", progress = nil, completion = "정말 좋은 소식이로군! 그 토석인이 살아 있다면 칼림도어에 어떤 짓을 저질렀을지 상상만 해도 끔찍하다네.\n\n고게로크를 처치하는 일은 진정한 영웅만이 수행할 수 있는 힘든 과제였어. 정말 잘했네. 이로써 돌발톱 산맥과 칼림도어의 모든 이들이 자네에게 큰 빚을 진 것이네.\n\n고마움의 뜻으로 이걸 받아주게나. 가장 명예로운 이에게 주는 것일세.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n부엉이수염 팔보호구늑대갈기 손목보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6482] = {title = "루울에게 자유를", objective = "루울을 호위해 탈출한 후, 토막나무 주둔지에 있는 야마 스노우후프와 대화하십시오.", description = "어? 자네는 누구인가?\n\n<name>|1이라고;라고;? 휴, 펄볼그는 아니로군. 저주 받을 녀석들! 내가 곰인 줄 알고 잡아들이더니 이젠 쫄쫄 굶기고 있어! 점점 더 기운이 빠지는군...\n\n내가 탈출할 수 있게 도와줘. 그리고 동쪽에 있는 토막나무 주둔지에서 내 누이 야마를 만나보게.\n\n<name>! 나는 여기서 꼭 빠져나가야 해!", progress = nil, completion = "동생을 찾으셨군요! 엉겅퀴일족에게 잡혀 있었다고요? 정말 끔찍한 소식이네요. 펄볼그들은 원래 고귀한 짐승이었어요. 그런데 그 엉겅퀴일족만큼은 타락한 것이 확실해요.\n\n&lt;name&gt;, 동생을 구해주셔서 감사합니다. 우리 불쌍한 루울에게 녀석들이 무슨 짓을 했을지 상상만 해도 끔찍해요. 그런 고난에서 빠져나왔으니 이제 그 아이는 오랜 잠을 잘 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6501] = {title = "용의 눈", objective = "전 세계를 뒤져 용의눈 조각의 힘을 복원할 수 있는 자를 찾아야 합니다. 이와 관련해 알고 있는 유일한 정보는 그러한 자들이 존재한다는 것뿐입니다.", description = "내가 줄 수 있는 거라곤 부서진 메달의 조각 하나뿐이라네.\n\n자네는 새 열쇠를 만드는 걸 도와 줄 다른 용혈족을 찾아야만 해. 열쇠를 확보하면 먼지진흙 습지대에 있는 용의 둥지로 가야 하네. 그곳에서 여왕용의 둥지를 찾을 수 있을 거야.\n\n자네를 도와줄 다른 용군단은 어디서 찾느냐고? 안타깝게도 그건 나도 모르네... 다만 그들이 존재한다는 얘길 들었네. 심지어는 우리들 사이에서 일하며 함께 산다고도 하지. 인간형 종족으로 위장한 채 말이지. 행운을 빌겠네.", progress = "그대에게서 아주 사악한 기운이 뿜어져 나오는 게 느껴지는군요. 도대체 어떤 물건을 지니고 있기에 그런 기운이 뿜어져 나오는 것인가요?", completion = "그래, 바로 이거였군요. 검은 용군단의 여왕용인 오닉시아의 조각이었군요. 역겹기 그지없군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6502] = {title = "비룡불꽃 아뮬렛", objective = "사령관 드라키사스에게서 검은용 용사의 피를 가져와야 합니다. 드라키사스는 검은바위 첨탑의 승천의 전당 뒤에 있는 알현실에 있습니다.", description = "용의 일부, 바로 마법에 걸려 변형된 비늘이지요. 온전한 것이 있으면 그 괴물의 둥지로 들어갈 수 있지만 부서진 것으로는 아무 소용도 없습니다.\n\n고칠 수야 있겠지만 그렇게 하려면 검은용 용사의 피가 필요합니다. 한 명 있기는 하지요... 네파리안의 용혈족 군단을 이끄는 사령관 드라키사스. 이름은 들어 봤겠지요?\n\n그의 피를 가져오세요, <race>|1이여;여;. 그리하면 비늘 조각에 마법을 걸어 오닉시아의 둥지로 들어갈 수 있게 될 것입니다.", progress = "시간의 흐름이란 멈추지도, 늦추어지지도 않는 것입니다. 내 생은 영원하나, 그대의 생은 그렇지 못하니 주어진 시간을 낭비하지 않도록 하십시오...", completion = "이 아뮬렛을 이용해 원하는 바대로 먼지진흙 습지대에 있는 오닉시아의 둥지로 들어갈 수 있을 것입니다. 아뮬렛을 지니고 있는 한 오닉시아의 수호병들이 그대를 막을 수 없을 것입니다.\n\n푸른용군단의 일원으로서 그대에게 행운이 따르길 빕니다.", rewards = "다음과 같은 것들을 받습니다:\n\n비룡불꽃 아뮬렛"},
[6503] = {title = "잿빛골짜기 정찰꾼", objective = "잿빛골짜기 정찰꾼 9명을 처치한 후 토막나무 주둔지에 있는 쿠레이빈에게 돌아가십시오.", description = "얼마 전 은빛날개 전초기지를 떠난 잿빛골짜기 정찰꾼들이 이제는 우리 영토 부근 숲에 몰래 숨어있다는 보고를 받았네. 놈들이 우리 방어력에 대한 정보를 캐내서는 안 돼!\n\n이곳 주둔지로부터 남쪽, 그러니까 얼라이언스의 은빛날개 전초기지로부터 동쪽에 있는 숲으로 몰래 들어가도록. 거기서 정찰꾼들을 찾아내 처치한 다음 내게 돌아오게.", progress = nil, completion = "아주 잘했네, &lt;name&gt;. 자네 사냥 솜씨가 아주 일품이로군.\n\n정찰꾼들을 좀 처치했으니 얼라이언스의 정보력이 타격을 입었을 걸세. 정보가 부족하면 함부로 공격해 올 수도 없을 테고.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6504] = {title = "잃어버린 열 두쪽", objective = "잃어버린 벌목기 조작설명서 열 두쪽을 찾아서 1장, 2장, 그리고 3장으로 합쳐야 합니다. 그런 다음 토막나무 주둔지 근처에 있는 구르다 레이지스카에게 돌려 주어야 합니다.", description = "난 톱니항에서 이 벌목기를 사서 전쟁노래부족 벌목기지로 근무를 하러 돌아가던 길이었지. 벌목기 작동법이 적힌 조작설명서도 받았는데 바람이 워낙 심하게 불어서 그만 손에서 놓쳐 버렸지 뭐야. 책장들이 여기저기 날아가 버려서 남은 거라고는 표지뿐이더군.\n\n그 설명서가 없이는 이 벌목기를 어떻게 쓸 방도를 모르겠으니... 어디 있는지 모르겠지만 자네가 내 대신 좀 찾아 주지 않겠나?", progress = "<name>, 잃어버린 쪽을 빨리 찾아 줬으면 좋겠어! 빨리 근무를 시작해야 하거든!", completion = "내가 글을 잘 읽는 편은 아니지만... 그래도 이젠 다시 일을 할 수 있겠군! 고마워, &lt;name&gt;!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n벌목기 운전수 장갑기름걸레 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6521] = {title = "사악한 동맹", objective = "사절 말킨을 처치한 다음 언더시티에 있는 바리마트라스에게 그의 머리카락을 증거로 가져가야 합니다.", description = "말킨의 글에 의하면 지금쯤 가시덩굴 구릉 밖에 있겠군. 그 사절 놈을 해치워야 해. 리치 왕의 바로 코앞에서 임무에 실패했단 사실을 깨닫게 해주자고.\n\n그가 거기 있는 것을 보니 우리가 그 지역에서 발견한 사실도 설명이 되는군. 역병의 징후가 보이는 동안 일부 가시멧돼지들이 무서울 정도로 강력해지고 있다네. 그들 간에 모종의 계약이 있었을 것이 분명해.\n\n말킨을 찾아서 처치한 다음 그 증거를 가지고 다시 오도록 하게.", progress = "<name>, 사절은 찾았나? 처치했겠지?\n\n감히 스컬지 따위가 칼림도어에 뿌리를 내리도록 놔둘 수는 없지. 우리 국경을 위협하는 것도 분한데 마음대로 활개를 치도록 놔둘 수는 없어.\n\n자네 얘기 중에서 한 가지 희망이 있다면 그 할망구가 아직 완전히 타락하지는 않았다는 것이지. 스컬지의 힘을 빌리면 불모의 땅을 얻어도 실권은 장악할 수 없다는 것을 자기도 느끼고 있을 거야.", completion = "잘했다, &lt;class&gt;|1이여;여;...\n\n이제 말킨이 죽었으니 스컬지는 행진을 잠시 멈출 수밖에 없겠지. 어둠의 여왕님께서 자네의 노력을 치하하는 의미로 선물을 하사하고자 하시네.\n\n스컬지의 세력이 얼마만큼 가시덩굴 구릉을 뒤덮었는지는 모르지만 곧 그들의 음모를 밝혀내리라 확신하는 바이네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n검은해골 곤봉강철가시 소총광신도의 로브\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6522] = {title = "사악한 동맹", objective = "작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다.", description = "여왕님께\n\n저희의 제안에 대해 잘 알고 계시리라 생각합니다. 불모의 땅과 그 너머의 땅을 차지할 수 있는 큰 기회입니다. 저희는 여왕님의 도움을 바라고 있습니다. 그저 이 지역에서 저희가 행동을 취할 수 있게만 해주시면 됩니다.\n\n이 문제에 대해 좀 더 논의할 수 있게 해주십시오. 저희에게는 힘이 있습니다. 그리고 저희와 뜻을 같이하려는 현명한 자들이 있습니다. 당분간 가시덩굴 구릉 밖에 머무르겠습니다.\n\n옥체 보중하소서...\n사절 말킨", progress = "<name>, 무슨 일로 찾아왔나? 나를 귀찮게 하다니 꽤 중요한 일인가보군.", completion = "그래, 이 두루마리의 휘장은 전에 본 적이 있어... &lt;name&gt;, 가시덩굴 우리를 지배하는 그 할망구에게서 이걸 찾았단 말인가? 재미있군.\n\n스컬지가 대륙 하나로는 성이 안 차나 보군. 이 편지를 쓴 말킨이라는 사절은 역병에 걸린 스컬지의 졸개일세. 일이 터지기 전에는 로데론 왕국의 인간 사절이었고.\n\n스컬지가 칼림도어에 기반을 마련하려고 한단 말이로군. 이제 우리가 움직일 때가 된 거야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6523] = {title = "카야 구출", objective = "카야 플랫후프를 아파라제 야영지까지 호위한 다음 돌발톱 산맥 남동쪽 가장자리에 있는 마카바 플랫후프에게 소식을 전하러 가야 합니다.", description = "정말 고마워요! 당신 덕에 이젠 살았어요... 내가 자유의 몸이 된 걸 그들이 발견하기 전에 어서 이곳을 빠져나가야 해요. 아파라제 야영지까지만 지켜주시면, 거기서부터는 길을 아니까 저 혼자 갈 수 있어요.\n\n참, 제 아버지 마카바 플랫후프께 이 기쁜 소식을 좀 전해주시겠어요? 아마 제 소식을 애타게 기다리고 계실 거예요.", progress = nil, completion = "카야가 살아 있었군! 내 딸을 구해줘서 정말 고맙네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6541] = {title = "카드라크에게 보고", objective = "불모의 땅 북부의 감시탑에 있는 카드라크에게 보고하십시오.", description = "자네, 북쪽에 있는 잿빛 골짜기에 가 본 적이 있나? 호드에서는 최근 그곳 조람 해안에 전초기지를 세웠지. 우린 늘 새로운 전선을 지킬 신병들이 필요하다네.\n\n관심이 있거든 불모의 땅 북부에 있는 카드라크를 찾아가보게. 감시탑에 있을 걸세. 그가 잿빛 골짜기 공격을 주도하고 있으니 자네에게 자세한 내용을 알려 줄 수도 있지.", progress = nil, completion = "잿빛 골짜기는 세력이 나뉜 땅이긴 하지만, 우리의 최근 노력이 많은 성과를 이룩했다네. 조람 해안에 전초기지를 세웠을 뿐 아니라 여기서 바로 북쪽에도 토막나무라는 주둔지를 세웠지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6542] = {title = "카드라크에게 보고", objective = "불모의 땅 북부의 감시탑에 있는 카드라크에게 보고하십시오.", description = "자네, 북쪽에 있는 잿빛 골짜기에 가 본 적이 있나? 호드에서는 최근 그곳 조람 해안에 전초기지를 세웠지. 우린 늘 새로운 전선을 지킬 신병들이 필요하다네.\n\n관심이 있거든 불모의 땅 북부에 있는 카드라크를 찾아가보게. 감시탑에 있을 걸세. 그가 잿빛 골짜기 공격을 주도하고 있으니 자네에게 자세한 내용을 알려 줄 수도 있지.", progress = nil, completion = "잿빛 골짜기는 세력이 나뉜 땅이긴 하지만, 우리의 최근 노력이 많은 성과를 이룩했다네. 조람 해안에 전초기지를 세웠을 뿐 아니라 여기서 바로 북쪽에도 토막나무라는 주둔지를 세웠지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6543] = {title = "전쟁노래부족 보고서", objective = "먼저 보고서 뭉치를 여십시오. 전쟁노래부족 길잡이, 전쟁노래부족 정찰병, 그리고 전쟁노래부족 척후병에게 전쟁노래부족 보고서를 가져가야 합니다. 그들의 보고 내용을 담고 있는 최신정보 3개를 받아서 불모의 땅 북부 감시탑에 있는 카드라크에게 돌아가십시오.", description = "최근 잿빛 골짜기에 부하 몇을 보냈지... 그들에게 이 보고서를 전하고 정찰 내용에 대한 보고를 받아올 전령이 필요한데...\n\n먼저 서쪽 조람 해안가에 있는 조람가르 전초기지로 가도록. 그 다음 북쪽 토막나무 주둔지에 들리고, 다시 동쪽으로 길을 따라 아즈샤라 경계 가까이 가야 하네. 그곳에 각기 길잡이, 정찰병, 그리고 척후병이 대기하고 있을 걸세.\n\n그들에게 내가 주는 이 보고서를 전하고 최신 보고 내용을 받아 오도록.", progress = "서두르게, <name>. 급한 일이니 어서 보고서를 전해줘.", completion = "자네는 믿을 수 있는 일꾼이로군. 이 최신정보에 담긴 중요한 정보를 이용해 행동을 개시하면 우리 호드는 잿빛 골짜기에서 영향력을 한껏 확장할 수 있어. 자, 이제 다음 작전을 짤 때로군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6544] = {title = "토렉의 공격", objective = "은빛날개 전초기지와 두리엘 문파이어를 공격하는 토렉을 호위한 후, 토막나무 주둔지에 있는 에르톡 레이지터스크에게 보고하십시오.", description = "이 보게, <class> 친구! 이리 와봐!\n\n난 우리 대원들과 곧 서쪽에 있는 은빛날개 전초기지를 공격할 생각일세. 거기 지도자인 두리엘 문파이어가 바로 우리의 목표인데, 정찰병의 보고에 의하면 파수꾼과 전사들이 철통같이 방어를 하고 있다는군. 아주 영광스러운 전투가 될 거야!\n\n우리를 도와 그 영광을 함께 나누지 않겠나, <name>? 자네 임무는 일이 모두 끝났을 때 토막나무 주둔지에 있는 내 상관 에르톡 레이지터스크에게 임무의 성공을 보고해주면 되는 걸세.\n\n어쩌겠나? 우리와 함께하겠나?", progress = nil, completion = "토렉의 공격이 성공했군! 자네도 수고했네, &lt;name&gt;. 나이트 엘프들은 만만한 적은 아니지. 좀 야위긴 했어도 단단하고 사납거든! 분명 전투가 아주 장관이었을 거야...\n\n자네도 흉터 한두 개 정도는 생겼기를 바라네!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n광택나는 지팡이푸른강철 커틀라스\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6545] = {title = "전쟁노래부족 길잡이 최신정보", objective = "그러니까 명령을 전달하러 왔다는 말이오? 열의가 있고 군기가 바짝 든 신병을 보니 기분이 좋군.\n\n이곳 상황을 알고 싶단 말이지 빨리 말할 테니까 어서 듣고 가시오. 나가의 위협이 자꾸 커지고 있소이다. 내가 이곳에 배치된 이후로도 몇 번씩이나 공격했거든.\n\n더 자세히 듣고 싶다면 여기 전초기지의 다른 이들과도 얘기를 나눠보라고.", description = nil, progress = "그러니까 명령을 전달하러 왔다는 말이오? 열의가 있고 군기가 바짝 든 신병을 보니 기분이 좋군.\n\n이곳 상황을 알고 싶단 말이지 빨리 말할 테니까 어서 듣고 가시오. 나가의 위협이 자꾸 커지고 있소이다. 내가 이곳에 배치된 이후로도 몇 번씩이나 공격했거든.\n\n더 자세히 듣고 싶다면 여기 전초기지의 다른 이들과도 얘기를 나눠보라고.", completion = "자, 이 최신정보에는 이곳의 모든 상황이 설명되어 있소. 어서 카드라크에게 돌아가시오.", rewards = "다음과 같은 것들을 받습니다:\n\n전쟁노래부족 길잡이 최신정보"},
[6546] = {title = "전쟁노래부족 척후병 최신정보", objective = "<name>, 이쪽은 매우 위험한 지역이에요. 여기 머무르는 동안에는 이 사실을 잊지 마세요. 얼라이언스의 위협이 시시각각 다가오고 있으니까요.\n\n여긴 사방이 적이에요. 잿빛 골짜기 동부는 사티로스의 세력이 만만치 않고요. 그리고 아즈샤라의 많은 지역을 나가가 차지하고 있지요.\n\n그래도 이렇게 당신이 오는 걸 보니 우리의 병력 보강은 원활하게 이루어지고 있군요. 정말 다행이에요. 언제나 유비무환이 최고죠.", description = nil, progress = "<name>, 이쪽은 매우 위험한 지역이에요. 여기 머무르는 동안에는 이 사실을 잊지 마세요. 얼라이언스의 위협이 시시각각 다가오고 있으니까요.\n\n여긴 사방이 적이에요. 잿빛 골짜기 동부는 사티로스의 세력이 만만치 않고요. 그리고 아즈샤라의 많은 지역을 나가가 차지하고 있지요.\n\n그래도 이렇게 당신이 오는 걸 보니 우리의 병력 보강은 원활하게 이루어지고 있군요. 정말 다행이에요. 언제나 유비무환이 최고죠.", completion = "&lt;name&gt;, 이 최신정보를 가능한 한 빨리 카드라크에게 전해주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n전쟁노래부족 척후병 최신정보"},
[6547] = {title = "전쟁노래부족 정찰병 최신정보", objective = "<name>, 항상 주위를 잘 살피세요. 엘프들은 종종 밤의 그림자 속으로 숨어 버리거든요.\n\n늘 경계를 게을리해서는 안 돼요. 우리는 나이트 엘프들이 호시탐탐 노리고 있는 이 땅을 지키기 위해 최선을 다하고 있어요.\n\n참, 카드라크가 제게 어떤 명령을 내렸나요?", description = nil, progress = "<name>, 항상 주위를 잘 살피세요. 엘프들은 종종 밤의 그림자 속으로 숨어 버리거든요.\n\n늘 경계를 게을리해서는 안 돼요. 우리는 나이트 엘프들이 호시탐탐 노리고 있는 이 땅을 지키기 위해 최선을 다하고 있어요.\n\n참, 카드라크가 제게 어떤 명령을 내렸나요?", completion = "우리가 나이트 엘프를 상대로 거두고 있는 승전보를 카드라크에게 전해주세요. 계획대로 착착 잘 진행되고 있다고요.", rewards = "다음과 같은 것들을 받습니다:\n\n전쟁노래부족 정찰병 최신정보"},
[6548] = {title = "침략에 대한 복수", objective = "그림토템부족 약탈자 8명과 그림토템부족 용병 6명을 처치한 다음 돌발톱 산맥 동남쪽 가장자리에 있는 마카바 플랫후프에게 돌아가야 합니다.", description = "그림토템부족이 우리 마을에 쳐들어와 쑥대밭을 만들어놓고 갔네. 온 힘을 다해 저항하고 많은 적을 처치했지만 결국 역부족이었어. 겨우 아내와 함께 빠져나와 이 구차한 목숨밖에 건질 수가 없었네.\n\n<name>, 지금 내가 바라는 건 처절한 복수뿐일세. 그들은 여기서 서쪽으로 가면 찾을 수 있어.", progress = "처치했나?", completion = "&lt;name&gt;, 고맙네... 하지만, 그림토템부족이 우리 마을에 한 짓은 결코 잊지 못할 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6561] = {title = "검은심연의 음모", objective = "황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다.", description = "이제 난 아무 힘도 없소. 당신의 도움이 필요하오!\n\n아주 오래전 이곳은 위대한 엘룬의 신전이었소. 하지만 불행히도 어느 고대 신의 타락한 기운이 땅 밑에서 스며나와 성스러운 달샘을 오염시키면서 폐허가 되어 버렸지.\n\n고대 신의 시녀인 아쿠마이가 물 위로 올라왔소.\n\n황혼의망치단 이교도들은 이 땅을 점령하기 위해 나가와 동맹을 맺었소. 켈리스를 따르는 이 이교도 집단은 죄없는 자들을 아쿠마이에게 희생 제물로 바쳐 힘을 얻고 있소.\n\n<name>, 켈리스를 해치우고 그의 머리카락을 썬더 블러프에 있는 바샤나에게 가져다주시오!", progress = "<name>, 항상 대지모신께서 당신과 함께하시기를...\n\n우리의 목표는 이 땅에서 대지모신의 후손들이 언제까지나 평화롭게 지내는 것이랍니다. 대지모신께서는 자연을 위한 원대한 계획을 가지고 계십니다. 그리고 그 계획 안에서 우리는 모두 각자 역할이 있지요.", completion = "켈리스는 은빛 여명회를 교묘히 피해 왔습니다.\n\n한 동안 은빛 여명회에서는 켈리스가 죽었거나 실종되었다고 생각했습니다.\n\n&lt;name&gt;, 당신은 그의 폭정을 끝냄으로써 선량한 많은 이들의 목숨을 구한 것입니다.\n\n대지모신께 찬양을! 고대 신의 노예들이 사사로운 욕심으로 선량한 이들을 희생 제물로 바치다니... 정말 역겹기 그지없는 일입니다!\n\n오늘 정말 위대한 일을 해주셨습니다. 켈리스는 고대 신을 숭배함으로써 세계를 혼돈의 시대로 되돌리려 한 사악한 존재였습니다. &lt;name&gt;, 고맙습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n묘비의 홀북극의 버클러\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6562] = {title = "검은심연의 나락으로...", objective = "잿빛 골짜기에 있는 제네우 생크리와 대화하십시오.", description = "제네우 생크리가 도움의 손길을 필요로 하고 있어요. 잿빛 골짜기 조람가르 전초기지에 있어요. 그 나이트 엘프의 숲은 돌발톱 산맥의 북쪽에 있지요. 칼바람 바위산을 지나가거나 불모의 땅을 지나 북쪽으로 곧장 가면 도착할 수 있어요. 숲에서 서쪽 멀리 조람 해안이 있고요. 조심하세요, <name>. 그곳의 세력들이 결코 당신을 반기지는 않을 테니까요.", progress = nil, completion = "츄나만이 보냈나? 아주 잘 됐어. 자네와 할 얘기가 있네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6563] = {title = "아쿠마이의 정수", objective = "잿빛 골짜기에 있는 제네우 생크리에게 아쿠마이의 사파이어 20개를 가져가야 합니다.", description = "검은심연의 나락으로 들어가는 입구에는 동굴 벽을 따라 커다란 사파이어 덩어리들이 박혀있지. 최근 나가들이 그 사파이어를 모으고 있다는 것이 알려졌네. 녀석들의 목적을 밝혀낼 때까지는 우선 나가들을 막아야 할 것 같아... 그 사파이어에는 어떤 강력한 정령의 힘이 깃들어 있어 함부로 사용하면 무시무시한 마력을 발휘할 수도 있어.\n\n<name>, 날 도와 주지 않겠나? 검은심연의 나락은 이곳 전초기지 북쪽에 있는 조람 해안에서 찾을 수 있다네.", progress = "<name>, 사파이어 캐는 일은 어떻게 돼가고 있지? 나가들이 사파이어를 모으는 걸 목격했나? 난 어째서 녀석들이 그걸 모으고 있는지 알려달라고 선조님께 기도를 올리고 있다네.", completion = "&lt;name&gt;, 수고했어. 맞아! 바로 이게 내가 말한 사파이어야. 아주 재밌는 물건이지...\n\n이 안에 든 힘을 느낄 수 있군. 보라고! 물의 정령들이 달라붙어 있어. 나가들이 이걸 어디에 쓰려고 한 것이든... 녀석들의 수중에 이 사파이어가 없다는 사실이 정말 다행이야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6564] = {title = "고대 신들에 대한 충성", objective = "축축한 메모를 잿빛 골짜기의 제네우 생크리에게 가져가십시오.", description = "꼬깃꼬깃한 종이에 휘갈겨 쓴 글씨가 보입니다.\n\n\"모든 여사제에게 수정을 내게 가져오라고 알리시오. 수정 안에 들어 있는 물의 정기가 강력하여 우리 정령사의 소환을 도울 수 있을 거요.\n\n수정의 힘을 조절하면 아쿠마이를 달랠 수 있을 거요. 언젠가 우리는 아쿠마이를 다시 불러낼 수 있는 힘을 갖게 될 것이고 세계는 다시 위대한 시대로 돌아가게 될 것이오. 고대 신들이 지배하던 시대로!\"", progress = "뭐가 필요하다고? 난 아직 나가들이 현혹되는 수정에 대해 연구해야 하는데...", completion = "이거 흥미롭군. 가져다줘서 고맙네.\n\n문제의 인물을 알 것 같아. 바로 로구스 제트지.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6565] = {title = "고대 신들에 대한 충성", objective = "검은심연의 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오.", description = "황혼의망치단 추종자들이 목적을 달성하도록 내버려 둘 수는 없지. 황혼의망치단은 자연의 정령을 이해하지 못해. 그들은 오래전 사라져 버린 혼돈과 파괴의 피조물인 고대 신들을 믿고 있다네. 로구스의 계획이 성공하도록 내버려 둘 수는 없어. <name>, 가서 그를 막게. 나는 늙고 병들어 아무 힘도 없으니까.\n\n검은심연의 나락으로 가서 그를 찾아 처치하게. 그런 다음 여기 조람가르 전초기지로 다시 돌아오게나.", progress = nil, completion = "&lt;name&gt;, 수고했네. 황혼의망치단의 야욕을 완전히 저지한 것은 아니지만 적어도 고대 신들에게 다시 힘을 불어넣으려고 했던 계획만큼은 분쇄한 것 같군.\n\n그들이 무엇을 노리고 있는지 누가 알겠네만 당분간은 우리도 쉴 수 있겠어.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n완력의 고리밤나무 어깨보호대\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6566] = {title = "바람이 전해 온 소식", objective = "스랄의 이야기를 들어야 합니다.", description = "<name>, 다시 보게 되어 반갑도다. 바람이 동부 왕국으로부터 소식을 가져왔다.\n\n앉아서 내가 하는 이야기를 듣도록 하라.", progress = "<name>, 인내심을 가지고 집중해서 듣도록!", completion = "어떤가? 임무를 맡을 각오는 되었는가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6567] = {title = "호드의 용사", objective = "렉사르를 찾아야 합니다. 그의 행방은 대족장이 설명해 주었습니다. 돌발톱 산맥과 페랄라스 사이에 있는 잊혀진 땅의 길에서 찾아 보십시오.", description = "우리 용사 하나가 그 용의 둥지로 가는 길이 존재할지도 모른다는 소식을 전해 왔다. 우선 그 용사를 찾아라.\n\n렉사르는 돌발톱 산맥과 페랄라스 사이를 여행하며 잊혀진 땅의 황무지 사막을 배회하고 있다. 그대를 기다리고 있을 것이다.", progress = nil, completion = "&lt;race&gt;|1이여;여;, 그 용의 둥지로 가는 길은 하나뿐이지.\n\n검은용군단에서 가장 강한 자만이 여왕의 둥지로 들어갈 수 있다네. 많은 시험을 통과해 사령관 드라키사스가 직접 마법의 힘을 불어넣은 열쇠를 얻어야 해!\n\n자네는 검은 용군단의 일원이 아니니 길을 뚫는 데 많은 어려움이 있을 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6568] = {title = "렉사르의 유언", objective = "서부 역병지대에 있는 노파 미란다에게 렉사르의 유서를 전달해야 합니다.", description = "환영에 대해 알고 있나? 검은용군단의 수비를 피하기 위해서는 환영을 만들 수 있어야 하기 때문에 얘기하는 거야.\n\n속임수를 쓸 수 있는 인물을 하나 알지. 그녀는 과거에도 우리가 추구하는 대의가 합당한 이유가 있다고 판단하여 우리 종족을 도와준 적이 있네.\n\n서부 역병지대에서 환영술의 대가인 노파 미란다를 만날 수 있을 걸세. 미란다는 로데론 얼라이언스에서 추방당했지. 이 쪽지를 가지고 그리로 가 보시게.", progress = "로데론의 이 지역에서 호드의 일원을 보는 일은 드문데. 이 미란다에게 무슨 일인가?", completion = "&lt;유서를 들고 잠깐 생각하더니 미소를 짓는 미란다&gt;\n\n그 오크 양반은 잘 지내나? 렉사르 말이야. 저런, 그렇게 당황하지 마시게나. 이 유서는 고의적으로 비어 있는 것이라네. 하지만 여기엔 작성자의 의도와 생각이 들어 있다지. 내용으로 봐서 렉사르가 백지를 보낸 것도 놀라운 건 아니로군그래. 젊은이가 포로가 되었거나 살해당했는데 이 쪽지가 그 사실을 알려주는 것이라고 생각해 보게!\n\n뭐 아무튼 신경쓸 거 없네! 이 미란다가 도와주지. 대족장님께 갚아야 할 신세도 좀 있고 하니...\n\n&lt;미소 짓는 미란다&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6569] = {title = "눈동자의 환영", objective = "검은바위 첨탑으로 가서 검은 용혈족의 눈동자 20개를 모아서 노파 미란다에게 돌아가야 합니다.", description = "그래, 자네가 검은용군단의 일원으로 변신하고 싶다는 건가?\n\n자네가 원하는 환영을 만드는 건 아무것도 아니지만 필요한 재료를 구하기가 몹시 어렵다네. 렉사르와 대족장님께서 그 정도 능력도 없는 자에게 이 임무를 맡기지는 않았겠지만...\n\n검은바위 첨탑 요새 위층으로 가서 검은 용혈족의 눈동자로 자네 짐을 가득 채워서 오게.\n\n재료를 충분히 모은 후에 내게 돌아오게나.", progress = "우리가 흉내 내려 하는 그 눈동자가 모든 환영을 만들어내는데 가장 중요한 재료라네.\n\n<‘붉은십자군’이라는 이름표가 붙어 있는 눈알이 넘치는 가방을 가리키는 미란다>\n\n<크게 웃는 미란다>", completion = "어디 이 미란다가 한번 볼까?\n\n오, 그래. 아주 좋아.\n\n이 정도면 검은용군단 문지기 녀석을 속일 만한 환영을 만들 수 있는 아뮬렛을 만들 수 있을 것이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6570] = {title = "엠버스트라이프", objective = "먼지진흙 습지대에 있는 용의 둥지로 가서 엠버스트라이프의 굴을 찾아야 합니다. 안으로 들어가서 용족 파멸의 아뮬렛을 착용하고 엠버스트라이프와 대화해야 합니다.\n\n제공된 아이템: \n", description = "이 아뮬렛에 엠버스트라이프의 굴 안에서 환영을 만들고 유지할 수 있는 마법을 부여해 놓았네.\n\n고대 비룡 엠버스트라이프는 네파리안의 오랜 문지기로서 오닉시아의 경비병이 될 용혈족을 시험하는 임무를 맡고 있지.\n\n먼지진흙 습지대에 있는 용의 둥지로 가서 엠버스트라이프의 굴로 들어가게. 거기에 도착하면 아뮬렛을 착용하고 자네 운명이 이끄는 곳으로 가면 된다네!", progress = nil, completion = "뛰어난 병사들이 더 이상 없기 때문에 네파리안님께서 꼬맹이들만 보내는 것인가? 너는 절대 시험을 통과하지 못할 것이다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6571] = {title = "전쟁노래부족 보급품", objective = "토막나무 주둔지의 록케 오카르를 위해 전쟁노래부족 보급품을 모아 오십시오. 전쟁노래부족 톱날, 전쟁노래부족 도끼 상자, 전쟁노래부족 기름, 그리고 벌목용 밧줄을 가져와야 합니다.", description = "전쟁노래부족 벌목기지에 보급품이 떨어져 가고 있네.\n\n톱날은 토막나무 주둔지의 픽셀로부터 받을 수 있을 걸세. 도끼 상자는 무법항의 부두주임 로즈길로부터 받을 수 있고.\n\n기름과 밧줄은 구하기가 더 힘들 거야. 밧줄은 엉겅퀴일족과 썩은나무일족 펄볼그들이 훔쳐갔고... 기름은 운반하던 중에 사티로스가 가로채서는 어둠의 터와 사티르나르, 그리고 사비안에서 이상한 종교의식에 사용하고 있으니까.\n\n날 좀 도와주겠나?", progress = "보급품 좀 찾아주게. 그 물건들을 빠른 시일 내에 보급하지 않으면 큰 낭패라고.", completion = "&lt;name&gt;, 잘했네. 내 일을 정말 많이 덜어주었군.\n\n자네에게 진심으로 고마워하고 있다는 걸 알아주게.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n전쟁노래 장식띠전쟁노래 장화전쟁노래 건틀릿\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6581] = {title = "전쟁노래부족 톱날", objective = "네, 있어요. 톱니항에서 바로 공수해온 전쟁노래부족 톱날이라고요!\n\n그런데 맨입으로 가져갈 수는 없죠. 저도 일하느라 바쁜 몸이라고요! 대가로 뭘 줄 건가요?\n\n사실 쓸만한 총이 하나 필요해요. 여자는 스스로 자신을 지킬 줄 알아야 한다고요. 참, 갖고 싶은 총이 하나 있는데... 만들기도 그리 어렵지 않대요.\n\n정교한 나팔총을 가져오면 대신 전쟁노래부족 톱날을 드릴게요. 어때요?", description = nil, progress = "네, 있어요. 톱니항에서 바로 공수해온 전쟁노래부족 톱날이라고요!\n\n그런데 맨입으로 가져갈 수는 없죠. 저도 일하느라 바쁜 몸이라고요! 대가로 뭘 줄 건가요?\n\n사실 쓸만한 총이 하나 필요해요. 여자는 스스로 자신을 지킬 줄 알아야 한다고요. 참, 갖고 싶은 총이 하나 있는데... 만들기도 그리 어렵지 않대요.\n\n정교한 나팔총을 가져오면 대신 전쟁노래부족 톱날을 드릴게요. 어때요?", completion = "바로 이 총이에요! 자, 톱날 여기 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n전쟁노래부족 톱날"},
[6582] = {title = "해골 시험 - 스크라이어", objective = "여명의 설원에서 찾을 수 있는 푸른용군단의 용사 스크라이어를 찾아 처치해야 합니다. 그의 시체에서 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다.", description = "우리는 모두 데스윙의 자손들로 하등한 위상들에 대한 우리의 지배를 공고히 해야 한다.\n\n진정으로 네가 진급의 자격이 있다면 하등한 용군단들이 네 존재 앞에 무릎을 꿇을 것이야.\n\n그들의 우두머리들을 찾아내 우리의 대부 데스윙의 이름으로 처단하게!\n\n여명의 설원으로 가서 푸른 비룡 스크라이어를 찾아 그를 처단하고 네 앞을 가로막는 푸른용군단은 고하를 막론하고 처단하도록 하라. 그의 해골을 수습한 후 내게 돌아오도록 하게.", progress = "<쉬하는 소리를 내는 엠버스트라이프>", completion = "시험 중 하나는 무사히 통과했군. 그럼 다음 시험으로 넘어가도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6583] = {title = "해골 시험 - 솜누스", objective = "녹색용군단의 우두머리 솜누스를 처치한 후 그의 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다.", description = "우리의 대부께서 다른 위상들을 격파했듯 우리 역시 그들의 후손들을 파괴시켜 이 땅에서 몰아내야 하네.\n\n저 잠들지 않는 몽상가 군단, 녹색 용군단의 후손을 상대로 너의 용맹을 시험해 보도록 하지.\n\n슬픔의 늪으로 가서 녹색용군단의 우두머리 솜누스를 찾아라. 그의 무리들에게 증오의 힘을 보여주고 솜누스의 해골을 내게 가져오도록 하라.", progress = "적들의 피로 온몸을 물들이고 그들의 고통을 너의 심장에 담아오기 전까지는 돌아오지 마라.", completion = "또 하나 통과했군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6584] = {title = "해골 시험 - 크로날리스", objective = "노즈도르무의 자손인 크로날리스가 타나리스 사막에 있는 시간의 동굴을 지키고 있습니다. 그를 처치한 후 그의 해골을 엠버스트라이프에게 가져가야 합니다.", description = "시간의 지배자 노즈도르무의 후손들은 시간의 감시자라는 별명으로 불리고 있지...\n\n그들의 아성인 시간의 동굴을 지키고 있는 자들은 모두 셋인데, 그 중 하나는 검은용군단에서 권력의 핵심이 되는 자라네. 노르도르무가 아꼈던 그의 이름은 크로날리스로, 시간의 중재자라는 별명으로 알려져 있지.\n\n그를 처단하고 노즈도르무의 후손들에게 눈물 맛이 어떤 것인지 보여주고 반드시 그의 해골을 가지고 돌아오게.", progress = "반어적으로 들리겠지만, 시간이란 참으로 중요한 것이지.", completion = "가장 증오스러운 녀석이 아직 남아 있다네...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6585] = {title = "해골 시험 - 악트로즈", objective = "그림 바톨로 가서 붉은용군단의 우두머리 악트로즈를 찾아 그를 처치한 다음 그의 해골을 수습하여 엠버스트라이프에게 돌아가야 합니다.", description = "우리의 대부께서는 그림 바톨의 산에서 다른 위상들의 강력한 연합을 격파했네. 그런데 배신자 알렉스트라자의 비열한 행동으로 인해 다른 위상들은 대부의 분노를 피해 도망갈 수 있었지.\n\n그림 바톨을 지키고 있는 붉은용군단의 부관 악트로즈를 처단해야 하네. 악트로즈의 해골을 가지고 나에게 돌아오게. 대부를 위하여!", progress = "새끼용이여, 너의 마음 속에서 뭔가 갈등의 조짐이 느껴지는군. 이번 시험만 끝내면 그동안의 성과를 축하하는 일만 남아 있을 뿐이네.", completion = "사실 난 네가 얼마나 헌신할 수 있을지 의심했었다. 하지만 너는 우리의 적들을 격파하고 우리 용군단에 명예를 가져다주었네.\n\n이제 너의 진급을 기념하기 위해 해골들을 준비하도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6601] = {title = "진급", objective = "이제 가면놀이는 끝난 것 같습니다. 노파 미란다가 만든 용족 파멸의 아뮬렛이 검은바위 첨탐 안에서 원래 구실을 하지 않는 것을 알고 있습니다. 아마도 렉사르를 찾아가 곤경에 처한 상황을 설명하는 것이 좋겠습니다. 렉사르에게 흐릿한 비룡불꽃 아뮬렛을 보여주면 아마도 필요한 게 무엇인지 알 수 있을 겁니다.", description = "네가 가져온 적들의 해골을 이용해서 아뮬렛을 만들었네. 이 아뮬렛을 본 적이 있지? 분명 너의 선조 정도 되는 이들이 이 아뮬렛을 차고 있는 것을 본 적이 있을 거야.\n\n이걸 받거라, 새끼용이여. 첨탑으로 돌아가서 아뮬렛을 드라키사스 사령관께 건네도록 해라. 사령관께서는 마지막으로 아뮬렛을 너의 영혼과 조화시키는 마력을 부여하실 것이다.\n\n완성된 아뮬렛은 네가 우리 용군단의 가장 명예로운 경비 계급인 혈족의 수호자로 진급되었음을 세상에 알리게 되는 징표가 될 것이다.\n\n자, 떠나라!", progress = "너무 혼란스러워하지는 말게!", completion = "그건 용들의 얘기일 뿐이네. 한 마디로, 구름 잡는 소리지. 용들에게선 오만하고 공격적인 행동 밖에 기대할 게 없지 않은가?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6602] = {title = "검은용 용사의 피", objective = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치하고 사령관의 피를 모아 렉사르에게 가져가야 합니다.", description = "자네가 사령관 드라키사스를 혼내 주기는 해야겠지. 하지만 검은용군단으로서 방문하는 것은 아닐세.\n\n알다시피 검은용군단에게 의식은 단지 피를 보기 위한 구실일 뿐이라네.\n\n휴면상태에 있는 아뮬렛을 다시 활성화하기 위해서는 조잡한 안전장치 중 하나인 사령관의 피만 있으면 되네.\n\n검은바위 첨탑으로 돌아가서 사령관 드라키사스를 처치하게. 그의 피를 가져오면 오닉시아의 둥지를 여는 열쇠를 활성화하도록 하지.", progress = "드라키사스를 우습게 봐서는 안 되네. 그 자는 수 천명의 목숨을 앗아간 장본인이야.", completion = "&lt;씩 웃는 렉사르&gt;\n\n자네의 영웅담은 앞으로도 계속 남을 것일세. 비룡불꽃 아뮬렛은 오닉시아의 둥지를 여는 열쇠지. 힘을 모아 호드의 이름으로 적을 물리치게!", rewards = "다음과 같은 것들을 받습니다:\n\n비룡불꽃 아뮬렛"},
[6603] = {title = "여명의 설원에 생긴 문제!", objective = "여명의 설원 간헐천 부근에 있는 도노바 스노우덴을 찾아가야 합니다.", description = "여명의 설원에 문제가 생겼어요!\n\n야생에서 오래 지내다 보면 이런 것에 대해 당연히 알게 되지만... 전 야생에 대해 얘기할 때면 정말 뿌듯해요. 언덕에서 보내는 시간은 정말 황금만큼이나 귀중하다고요. 반사 신경도 빠르게 해주죠. 그리고 머리도 맑게 해주고, 눈까지 예리해진다니까요.\n\n야생을 제대로 만끽하려면 머리가 좋아야 함은 물론 성숙하기도 해야 한다고요. 바로 제가 그렇듯이 말이죠.\n\n아, 그런데 무슨 얘길 하고 있었죠?\n\n맞다. 문제가 있었어요. 간헐천 부근에 있는 도노바 스노우덴을 찾아가면 자세한 내막을 말해 줄 거예요.", progress = nil, completion = "안녕하세요! 메지가 여기 문제가 있다고 얘기하던가요? 맞아요... 제가 그 문제를 발견한 장본인이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6604] = {title = "성난 올빼미야수", objective = "별똥별 마을에 있는 야론 스톤셰이퍼를 만나야 합니다.", description = "여기서 남쪽에 있는 버려진 야영지에 가보았나? 올빼미야수들이 미쳐서 눈에 보이는 것은 모조리 부수는 것 같던데!\n\n소문에 의하면 올빼미야수의 공격에서 살아남은 자가 여기서 서쪽에 있는 별똥별 마을에서 쉬고 있다고 하더라고. 무슨 일이 일어났던 건지 정말 궁금한데... 자네는 궁금하지 않은가?", progress = nil, completion = "무얼 도와드릴까요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6605] = {title = "엽기적인 그녀와의 만남", objective = "악령의 숲에 있는 위나 해저드를 만나야 합니다.", description = "방금 악령의 숲에서 돌아오는 길인데 피멍울 초소에 들러서 정말 이상한 여인을 하나 만났네. 한 가지 일에 굉장히 집요한 관심을 보이던데, 내가 들은 대로 그냥 말해줄 수도 있지만 아무래도 그녀가 자네에게 직접 말하고 싶어할 것 같아.\n\n관심이 있다면 악령의 숲 서부에 있는 피멍울 초소로 가서 위나 해저드를 만나 보게.\n\n누가 알아? 혹시 자네 도움이 필요할지.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6606] = {title = "작은 행운", objective = "눈망루 마을에 있는 의술사 마우아리를 만나야 합니다.행운이 와준다면 좋지 않겠나? 작은 운만 따라도 모든 일을 자네에게 유리하게 만들 수 있다네.\n\n일전에 어느 별난 의술사를 하나 알게 됐는데 그녀가 행운의 펜던트를 만들어 줬지. 대신 수고비는 좀 치러야 했지만... 그럴 만한 가치가 충분했다고!\n\n자네도 하나 만들지그래? 눈망루 마을에서 의술사 마우아리를 찾아보게. 내건 절대로 줄 수 없으니까!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "행운이 와준다면 좋지 않겠나? 작은 운만 따라도 모든 일을 자네에게 유리하게 만들 수 있다네.\n\n일전에 어느 별난 의술사를 하나 알게 됐는데 그녀가 행운의 펜던트를 만들어 줬지. 대신 수고비는 좀 치러야 했지만... 그럴 만한 가치가 충분했다고!\n\n자네도 하나 만들지그래? 눈망루 마을에서 의술사 마우아리를 찾아보게. 내건 절대로 줄 수 없으니까!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6607] = {title = "낚시의 달인 내트 페이글", objective = "아래 물고기들을 모두 잡아 내트 페이글에게 돌아가야 합니다.\n\n슬픔의 늪의 안개갈대 해안에 사는 안개갈대 황새치\n\n잊혀진 땅의 살데리스 해안에 사는 살데리스 아귀\n\n페랄라스의 베르단티스 강에 사는 페랄라스 참치\n\n가시덤불 골짜기의 폭풍 해안에 사는 폭풍 해안 푸른도루묵\n\n위 물고기를 모두 얻은 후 내트 페이글에게 돌아가십시오.", description = "낚시는 내 인생이나 다름없다고. 이걸 해온 지도 벌써 30년이나 됐으니까.\n\n내 생각에 사람들이 낚시를 하는 데는 다양한 목표와 이유가 있는 것 같아.\n\n그러니까 꼭 나처럼 30년 동안 고기를 낚아야만 낚시의 달인이 되는 건 아니더란 말일세. 단, 의지는 있어야지. 한 번 자리에 앉으면 낚싯대만 쳐다보면서 몇 시간은 버틸만한 의지!\n\n우선 자네가 진귀한 물고기들을 좀 낚아온다면 한두 가지 기술을 가르쳐 주도록 하지. 자, 여기 자네가 건져 올려야 할 물고기 목록일세.", progress = "어이, 낚시는 잘되어가나?", completion = "이야, 그야말로 월척을 올렸군!\n\n자, 약속한 대로 몇 가지 낚시 기술을 가르쳐 주겠네.", rewards = "다음과 같은 것들을 배웁니다:\n\n낚시\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n전문 낚시\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6608] = {title = "청출어람", objective = "루막에 말에 의하면 그는 더 이상 당신의 낚시 실력 향상에 도움을 줄 수 없는 듯합니다. 아마 테라모어로 가라는 말인 것 같습니다. 남쪽에 있는 섬 어디엔가에서 낚시를 하고 있을 루막의 인간 친구 내트 페이글을 찾아 보십시오.", description = "<name>, 자네에게 이 루막은 더 이상 가르칠 게 없군. 자네의 실력이 나를 월등하게 앞섰지 않나! 내 친구 내트 페이글을 찾아가 보게. 인간 종족이지만 절대 잡아먹지는 말게! 이 루막의 친구니까 말일세! 내트가 낚시에 대해서 더 가르쳐 줄 거야.\n\n인간놈들의 마을 남쪽의 테라모 어쩌구에 있는 먼지진흙 습지대로 가면 내트가 기다리고 있을 걸세. 아마 낚시하고 있을 거야. 자, 어서 가보게!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6609] = {title = "빈털터리!", objective = "칼림도어로 가서 해안 도시인 테라모어로 가야 합니다. 그곳 마을에서 남쪽에 있는 섬을 찾아야 합니다. 내트 페이글이 당신을 기다리고 있습니다!", description = "빌어먹을... 난 드워프란 말이오! 낚시나 할 몸이 아니라고! 이 튼튼한 팔뚝 좀 보시오! 난 채광을 하려고 태어난 몸이란 말이오.\n\n이젠 남은 게 없소이다. 전부 다 당신한테 줬다는 말입니다. 이미 제가 아는 모든 걸 가르쳐 줬지 않습니까?!\n\n이해가 안 갑니까? 음, 좋습니다. 칼림도어에 당신을 도와줄 만한 친구가 있소이다. 내트 페이글이라고 아주 괜찮은 녀석입니다. 테라모어 남쪽에 있는 섬에서 찾아 보십시오. 어서 출발하지 않고 뭐 하십니까?!", progress = nil, completion = "난 언제나 이 섬을 방문하는 이들이 머물 곳을 준비해 놓고 있지. 아마 자네 방도 있을 거야...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6610] = {title = "조개 별미", objective = "더지 퀵클레이브가 다음 재료를 구해 오라고 합니다.\n\n거대한 알 12개... 타나리스에 떠돌고 있는 로크와 같은 커다란 새에게서 구할 수 있습니다.\n\n고소한 조갯살 10개... 조개를 열어서 찾을 수 있습니다.\n\n알터랙 스위스 치즈 20개... 아무 상인이나 붙잡고 알아보십시오.\n\n모든 재료를 모아서 더지에게 돌아가야 합니다.", description = "자네 조개 별미라고 들어 봤나? 분명 생전 처음 들어봤겠지! 내가 최근에 개발한 최고의 요리라고. 흠... 생각만 해도 군침이 도는군.\n\n그런데 문제는 재료가 없단 말이야! 나랑 거래 하나 할까? 조개 별미 재료를 구해다 주면 진귀한 요리 비법을 전수해 주지. 조개 별미도 몇 개 덤으로 주고 말이야! 어때? 꽤 구미가 당기지 않나?\n\n필요한 재료를 일러 줌세.", progress = "더 이상은 못 참겠어! <name>, 서둘러주게. 내 비상 음식 재료에는 손대기 싫거든.", completion = "이걸 바로 옆에서 보고 배울 수 있다니 운 좋은 줄 알게.\n\n&lt;더지가 조개 별미를 준비하기 시작합니다.&gt;", rewards = "다음과 같은 것들을 배웁니다:\n\n요리\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n전문 요리\n\n다음과 같은 것들 또한 받습니다:\n\n조개 별미"},
[6611] = {title = "가젯잔으로 출발!", objective = "타나리스 사막에 있는 가젯잔으로 가서 더지 퀵클레이브를 만나 당신의 요리 실력 향상에 대해 대화를 나누어야 합니다.", description = "이 잠자에게 뭘 더 가르쳐 달라는 거예요? 제 요리 비법을 죄다 뽑아냈으면서 더 알려줄 게 없느냐고요?\n\n이런 욕심쟁이 양반, 저는 더 이상 도와줄 수 없어요. 가젯잔으로 가세요. 거기 더지라는 조그만 고블린을 찾으세요. 그라면 도와줄 수 있을 거예요.\n\n당신이 거기서 대단한 요리사가 되면 다시 돌아와서 잠자에게 뭐라도 좀 가르쳐 줘요. 알았죠? 자, 이제 출발하세요!", progress = nil, completion = "&lt;더지가 가죽 조각을 뱉어냅니다.&gt;\n\n켁켁...\n\n&lt;더지가 크게 헛기침을 합니다.&gt;\n\n뭐 하는 짓이냐고? 그런 질문을 하기 전에 가죽은 단백질 함량이 너무 높고 탄수화물 함량은 너무 낮다는 걸 알아두기 바라네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6612] = {title = "내가 아는 고블린", objective = "타나리스 사막에 있는 가젯잔으로 가서 더지 퀵클레이브를 만나 당신의 요리 실력 향상에 대해 대화를 나누어야 합니다.", description = "당신이 들고 있는 요리용 칼을 보니 자질이 좀 있어 보이는군요? 불행하게도 전 아무것도 가르쳐 줄 수 없겠지만요.\n\n대신 제가 아는 고블린이 하나 있는데 칼림도어 최고의 요리사랍니다.\n\n먼 길을 가야 한다는 단점이 있긴 하지만... 지금 가젯잔으로 떠나십시오. 거기서 더지 퀵클레이브를 만나십시오. 제대로 가르쳐 줄 테니까요.", progress = nil, completion = "&lt;더지가 가죽을 뱉어냅니다.&gt;\n\n켁켁...\n\n&lt;더지가 크게 헛기침을 합니다.&gt;\n\n뭐 하는 짓이냐고? 그걸 묻기 전에 가죽은 단백질 함량이 너무 높고 탄수화물 함량은 너무 낮다는 걸 알아 두게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6621] = {title = "썩은나무일족의 왕", objective = "썩은나무일족 토템고분에 카랑의 깃발을 꽂은 다음 펄볼그들이 깃발을 부수지 못하도록 막아야 합니다. 족장 머구트가 나타나면 그를 물리치고 머구트의 토템을 조람가르 전초기지의 카랑 아마카르에게 가져가야 합니다.", description = "아스트라나르 남동쪽으로 가면 펄볼그일족의 한 갈래인 썩은나무일족이 살고 있소. 엉겅퀴일족만큼 많지는 않지만 그 포악함만은 장차 큰 위협이 되기에 충분하오. 수가 적을 때 아예 뿌리를 뽑아버리는 게 좋을 듯하오.\n\n자, 이 깃발을 받으시오. 썩은나무일족 마을로 가서 토템고분에 꽂으면 놈들이 당장 깃발을 없애려 들겠지. 하지만 일족을 구하기 위해 족장 머구트가 등장할 때까지 버텨야하오. 족장이 나타나면 그를 해치우고 그가 지니고 다니는 토템을 가져오시오.\n\n<name>, 친구들의 도움이 필요할 거요. <class> 혼자 해낼 수 있는 일은 아니니까.", progress = "<name>, 족장 머구트를 물리쳤소? 썩은나무일족 토템은 가져왔고?", completion = "잘했소. 썩은나무일족에게 선전포고를 하고 족장을 유인해 물리침으로써 당신은 강렬한 메시지를 전달한 거요.\n\n우리 호드가 그렇게 만만하지 않다는 경고 말이오.\n\n하지만 썩은나무일족에게 그 효과가 오래갈 거라고는 생각하지 않소. 또다시 소란을 일으키겠지...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n보살핌의 튜닉푸른미늘 다리보호대\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6622] = {title = "응급 치료", objective = "응급 붕대로 상처를 치료해서 환자를 구해야 합니다. 환자 6명이 죽기 전에 15명을 구해야 합니다.\n\n부상자 치료 우선 순위를 기억해야 합니다! 위독한 부상병이 가장 빨리 사망하고 그 다음으로 위태로운 부상병이 사망합니다. 부상병들이 제일 늦게 사망하므로 위독한 부상병과 위태로운 부상병을 먼저 구해야 합니다.", description = "안녕하시오, 의사 선생. 오늘 오후에는 부상자 치료 우선 순위를 적절히 선별할 수 있는 능력을 시험하도록 하겠소. 시험을 통과하면 명문 호드 응급의학회에 들어갈 특권이 주어질 것이오.\n\n부상자 치료 순서를 알려 줄 테니 주목하시오! 침상에 누워있는 환자 중에서 제일 먼저 위독한 부상병을 치료해야 하오. 그 다음에는 위태로운 부상병을 치료하고 마지막으로 가벼운 부상을 입은 부상병을 치료하면 되오. 시험에 통과하려면 15명의 환자를 구해야 하오. 분류하는 중 6명의 환자가 사망하면 탈락이니 신중해야 한다는 것을 명심하시오.\n\n행운을 비오.", progress = nil, completion = "환영하오! 호드 응급의학회에 가입한 것을 축하하오.", rewards = "다음과 같은 것들을 배웁니다:\n\n응급치료\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n전문 응급치료\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6623] = {title = "호드 응급의학회", objective = "아라시 고원에 있는 해머폴로 가서 호드 응급의학회의 일원이 되는 방법에 대해 의사 그레고리 빅터와 대화를 나누어야 합니다.", description = "<name>, 자네 의사로군?! 다시 만나 반갑네.\n\n그나저나 기가 막히게 기쁜 소식이 하나 있어! 호드 응급의학회의 수석 의사이신 그레고리 빅터께서 친히 자네에게 해머폴로 오라는 요청을 하셨다네. 이건 일생일대의 기회라고! 나라면 그레고리 빅터와 같이 위대한 의사 밑에서 공부할 수 있는 기회를 잡을 수만 있다면 무슨 짓이라도 하겠어! 그러니 이 기회를 놓치지 말라고, 의사 선생!", progress = nil, completion = "좋아, 손부터 씻고 바로 시작하도록 하세나!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6624] = {title = "응급 치료", objective = "응급 붕대로 상처를 치료해서 환자를 구해야 합니다. 환자 6명이 죽기 전에 15명을 구해야 합니다.\n\n부상자 치료 우선 순위를 기억해야 합니다! 위독한 부상병이 가장 빨리 사망하고 그 다음으로 위태로운 부상병이 사망합니다. 가벼운 부상을 입은 부상병이 제일 늦게 사망하므로 위독한 부상병과 위태로운 부상병을 먼저 구해야 합니다.", description = "안녕하십니까, 의사 선생. 오늘 오후에는 부상자 치료 우선 순위를 적절히 선별할 수 있는 능력을 시험하도록 하겠습니다. 시험을 통과하면 얼라이언스 응급의학회에 들어갈 특권이 주어질 것입니다.\n\n부상자 치료 순서를 알려 줄 테니 주목하시오! 침상에 누워있는 환자 중에서 제일 먼저 위독한 부상병을 치료해야 합니다. 그 다음에는 위태로운 부상병을 치료합니다. 마지막으로 가벼운 부상을 입은 부상병을 치료하면 됩니다. 시험에 통과하려면 15명의 환자를 구해야 합니다. 분류하는 중 6명의 환자가 사망하면 탈락이니 신중해야 합니다.\n\n행운을 빕니다.", progress = nil, completion = "환영합니다! 얼라이언스 응급의학회에 가입하게 된 것을 축하합니다.", rewards = "다음과 같은 것들을 배웁니다:\n\n응급치료\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n전문 응급치료\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6625] = {title = "얼라이언스 응급의학회", objective = "먼지진흙 습지대에 있는 테라모어로 가서 얼라이언스 응급의학회의 일원이 되는 방법에 대해 의사 구스타프 밴하우젠과 대화를 나누어야 합니다.", description = "<name>, 당신 의사 맞지요? 만나서 반가워요.\n\n기가 막히게 멋진 소식이 하나 있답니다! 얼라이언스 응급의학회의 수석 의사이신 구스타프 밴하우젠 선생께서 당신에게 테라모어로 오라고 하셨어요. 이건 일생일대의 기회라고요! 저 같으면 구스타프 밴하우젠 같은 위대한 의사 밑에서 공부할 수 있는 기회를 잡을 수만 있다면 무슨 짓이라도 하겠어요! 그러니까 이런 기회를 놓치지 말라고요, 의사 선생!", progress = nil, completion = "좋습니다! 손부터 씻고 바로 시작하도록 합시다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6626] = {title = "악의 무리", objective = "가시덩굴일족 전투호위병과 가시덩굴일족 가시마술사, 그리고 죽음의 머리교 신도를 각각 8마리씩 죽인 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다.", description = "제가 본 바에 의하면 포세이큰들은 다른 이에게 역병을 옮기지 않습니다. 어떤 사신이 추종자들을 언데드로 만들어 주는 것 같습니다. 문득 그가 스컬지의 일원이라는 생각이 드는군요.\n\n하지만 지금은 그게 문제가 아닙니다. 그의 주위에 몰려드는 무리들입니다. 매일 어둠에서 기어 나와 그에게 더 큰 힘을 청하고 있답니다.\n\n저 혼자서는 그들을 물리칠 수 없습니다. 그대의 생각은 어떻습니까? 사냥을 좀 해보시겠습니까?", progress = nil, completion = "&lt;name&gt;, 감사합니다! 그대가 하신 일은 분명 큰 도움이 될 것입니다.\n\n저는 그 사신과 이곳에 남아 있는 가시멧돼지 무리에 대해 더 알아봐야겠습니다. 더 큰 모험을 원하신다면 친구들을 모아서 바로 저기 있는 거대한 멧돼지 턱처럼 보이는 동굴로 들어가십시오. 발을 들여놓자마자 엄청난 도전이 그대를 기다리고 있을 것입니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6627] = {title = "지혜의 시험", objective = "브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다.", description = "책을 가져왔으니 이제 질문에 답할 시간이로군. 준비됐나?\n\n시간은 문제가 안 된다네. <class>|1이여;여;, 그러니 부담은 갖지 말게. 대답하기 전에 시간은 얼마든지 가져도 좋으니까.", progress = nil, completion = "잘했네. &lt;class&gt;|1이여;여;, 내가 말한 책을 공부했군. 이제 자네는 시험을 하나 더 통과한 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6628] = {title = "지혜의 시험", objective = "파쿠알 핀탈라스의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 파쿠알 핀탈라스는 언더시티에 있을 것입니다.", description = "또 만났군그래. 자네는 지혜를 추구하는 자로서 내가 맡긴 임무를 수행하며 대단한 끈기를 보여주었네.\n\n이제 문제를 하나 내도록 하겠네. 준비가 되면 다시 찾아와 얘기하도록. <name>, 시간은 얼마든지 갖게나. 서둘러 대답할 필요는 없으니까.", progress = nil, completion = "&lt;name&gt;, 잘했네. 내가 말한 책을 공부했는지 의심했었는데 정답을 잘 맞추었어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6629] = {title = "그룬디히 다크클라우드 처치", objective = "그룬디히 다크클라우드와 그림토템부족 투사 6명을 처치한 다음 돌발톱 산맥 남동쪽 끄트머리에 있는 마카바 플랫후프에게 돌아가야 합니다.", description = "자네 그림토템을 처치하는 임무를 훌륭하게 수행했군. 그보다 더한 자가 하나 있네. 졸개를 이끌고 우리 마을에 잔인한 침략을 감행한 자로서 그룬디히 다크클라우드라고 하네.\n\n그림토템 초소로 가면 찾을 수 있을 거야. 서쪽 길을 따라 조금만 올라가면 있지. 자네가 그를 처치해준다면 내가 영원한 빚을 지는 것이 될 게야.", progress = nil, completion = "그 사악한 그룬디히 다크클라우드가 이제 죽었군! 자네가 해준 일에 대해 눈을 감을 그 날까지 감사할 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6641] = {title = "채찍꼬리 보르샤", objective = "머그래쉬가 화로로 접근하는 동안 안전하게 보호하고, 그를 도와 화로를 꺼야 합니다. 그런 다음 나가와 맞서 싸우는 동안 그를 보호하십시오.\n\n성공하면 조람가르 전초기지로 돌아와 전쟁노래부족 길잡이에게 채찍꼬리 보르샤의 죽음을 보고하십시오.", description = "채찍꼬리 보르샤라... 바다를 배회하는 악마 같은 히드라지.\n\n우리 전초기지를 공격할 때마다 냉혹한 숨결로 눈앞에 보이는 모든 것을 파괴하지.\n\n난 준비가 됐어. 그 히드라를 처치할 최선의 방책을 준비하여 조람가르 전초기지에 대한 공격에 종지부를 찍게 해주겠어!\n\n그 사악한 괴수를 섬기는 나가들은 해안에서 약간 떨어진 어느 섬에 화로를 켜고 경의를 표한다네. 그 화로를 꺼버리면 보르샤가 화가 나서 나타날 걸세.\n\n도움이 필요할 테니 동료를 최대한 많이 불러모아야 할 거야.", progress = nil, completion = "여기 배치된 이후 나가의 공격을 여러 번 받았지... 하지만 이제 더 이상 보르샤가 날뛰지 못할 거라니 마음이 한결 가볍소이다.\n\n&lt;name&gt;, 당신에게 큰 빚을 졌소.", rewards = "다음과 같은 것들을 받습니다:\n\n뿔반지"},
[6642] = {title = "토륩 대장조합의 평판, 검은무쇠 광석", objective = "나락에 풍부하게 분포되어 있는 검은무쇠 광석은 여전히 우리 대장조합에겐 귀중한 자원이네. 라그나로스의 신성한 무기와 장비를 만들려면 검은무쇠 광석이 필요하지.\n\n검은무쇠 광석을 10개 바칠 때마다 토륨 대장조합의 평판이 올라갈걸세.", description = nil, progress = "나락에 풍부하게 분포되어 있는 검은무쇠 광석은 여전히 우리 대장조합에겐 귀중한 자원이네. 라그나로스의 신성한 무기와 장비를 만들려면 검은무쇠 광석이 필요하지.\n\n검은무쇠 광석을 10개 바칠 때마다 토륨 대장조합의 평판이 올라갈걸세.", completion = "자네의 헌납품이 바쳐졌네. 대장조합 내의 평판도 올라갔고 헌납을 계속하게 되면 고대의 거래에도 참여할 수 있게 될걸세.", rewards = nil},
[6643] = {title = "토륨 대장조합의 평판, 불꽃의 정수", objective = "화산 심장부에서 위험을 무릅쓰는 자들이여! 안타깝구나. 죽음은 갑작스레 찾아오지. 자비란 없단 말이야. 많은 결사단원이 불꽃의 정수를 찾다가 죽었네.\n\n불꽃의 정수 하나를 바치면 토륨 대장조합의 평판이 올라갈걸세.", description = nil, progress = "화산 심장부에서 위험을 무릅쓰는 자들이여! 안타깝구나. 죽음은 갑작스레 찾아오지. 자비란 없단 말이야. 많은 결사단원이 불꽃의 정수를 찾다가 죽었네.\n\n불꽃의 정수 하나를 바치면 토륨 대장조합의 평판이 올라갈걸세.", completion = "자네의 헌납품이 바쳐졌네. 대장조합 내의 평판도 올라갔고 헌납을 계속하게 되면 고대의 거래에도 참여할 수 있게 될걸세.", rewards = nil},
[6644] = {title = "토륩 대장조합의 평판, 화산의 정수", objective = "토륨 대장조합에서는 자네의 어려움을 외면하지 않네. 록토스가 번창할 수 있는 것도 이런 이유지.\n\n화산의 정수 하나를 바치면 토륩 대장조합의 평판이 올라갈걸세.", description = nil, progress = "토륨 대장조합에서는 자네의 어려움을 외면하지 않네. 록토스가 번창할 수 있는 것도 이런 이유지.\n\n화산의 정수 하나를 바치면 토륩 대장조합의 평판이 올라갈걸세.", completion = "자네의 헌납품이 바쳐졌네. 대장조합 내의 평판도 올라갔고 헌납을 계속하게 되면 고대의 거래에도 참여할 수 있게 될걸세.", rewards = nil},
[6645] = {title = "토륩 대장조합의 평판, 용암 가죽", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6646] = {title = "토륩 대장조합의 평판, 산의 피", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6661] = {title = "깊은굴 지하철 쥐떼 소탕", objective = "쥐잡는 사나이의 피리를 사용해 깊은굴쥐 5마리를 잡은 후 몬티에게로 데리고 가야 합니다. 다 끝난 후에는 피리를 몬티에게 되돌려줘야 합니다.", description = "안녕하세요? 일거리를 찾고 있나요? 아악... 이곳에는 쥐떼들이 심각한 골칫거리인데 해결해줄 만한 이가 아무도 없어요.\n\n당신이 한번 해보지 않겠어요? 그냥 이 쥐잡는 사나이의 피리를 들고 쥐들이 있는 곳으로 가서 불기만 하면 된답니다. 그러면 녀석들이 계속 쫓아올 거예요!\n\n내게 다섯 마리만 데려와 주세요. 살아있는 놈들로 좀 필요하거든요...\n\n으아악...", progress = "아악... 얼간이... 뭐가 이렇게 오래 걸리나요?", completion = "이 정도면 딱 되겠어요. 우리 형 말이 꼭 살아있어야 한다는군요. 아니면 너무 신맛이 나서 안 된다고... 한번 생각해보세요. 꼬치구이에서 신맛이 나면 입맛 버리죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6662] = {title = "우리 형 닙시", objective = "스톰윈드 깊은굴 지하철에 있는 닙시에게 이상한 고기 상자를 가져다 주어야 합니다.", description = "우리 형 닙시는 깊은굴 지하철의 반대쪽 승강장 부근에서 쥐 꼬치구이 장사를 하고 있어요. 여기 이 상자에 든 쥐가 상하기 전에 얼른 갖다줘야 해요. 빨리 서둘러요!\n\n지하철을 타본 적은 있겠지요? 간단하잖아요. 지하철이 오면 올라타서 몸을 맡기고 즐기기만 하면 되니까. 하지만 지하철이 이동하는 동안에는 팔다리를 밖으로 내밀지 않는 게 좋을 거예요. 그러다 평생 앉은뱅이 신세가 될지도 모르니까요.", progress = "<고기 상자 구멍에 손가락을 쑤셔 넣는 닙시>\n\n아직도 팔팔하게 살아 있군... 딱 때맞춰 오셨네요!", completion = "불쌍한 몬티 녀석... 놈리건 사태 이후 좀 이상해져 버렸어요. 평생 바다 근처라고는 가보지도 않은 녀석이 해적 흉내를 내고 있다니...\n\n&lt;한숨을 쉬는 닙시&gt;\n\n쥐는 계속 잡아서 보내니 그나마 다행이지요.", rewards = "다음과 같은 것들을 받습니다:\n\n깊은굴쥐 꼬치"},
[6681] = {title = "라벤홀트 장원", objective = "힐스브래드의 구릉지에 숨어 있는 라벤홀트 장원의 파라드에게 라벤홀트의 인장을 가져가야 합니다.\n\n라벤홀트 장원의 입구 근처에서 자신의 실력을 증명할 상자를 발견하게 될 것이며 어떤 기술을 사용하여 이를 증명해야 할지 준비해야 합니다.", description = "<name>에게,\n\n라벤홀트님께서 당신에게 관심을 보이고 있소, 젊은 도적이여. 우리가 그 동안 쭉 지켜보고 있었지. 당신 방식에 조금 어색한 부분도 없진 않지만 우리가 다 고칠 수 있는 것이라오.\n\n라벤홀트 영주의 제자이자 암살단의 일원으로 일생을 보낼 각오가 되었다면 이 편지에 함께 동봉된 라벤홀트의 인장을 라벤홀트 장원으로 가지고 오시오.\n\n당신의 첫 번째 임무는 힐스브래드의 구릉에 숨어 있는 이 장원을 찾아 자신의 실력을 증명하는 것이오.\n\n파라드", progress = "밀턴은 만났소?\n\n<소리 내어 웃는 파라드>", completion = "아주 잘 했소, 젊은 &lt;class&gt; 친구.\n\n좀 지친 것 같긴 하지만 쓰러질 것 같진 않군그래.\n\n길지만 보람 있는 여정이 당신을 기다리고 있소. 이제 라벤홀트의 대가들 사이에서 자신의 운명을 받아들일 준비는 되었소?\n\n밖에 있는 경비병들과 얘기해 보시오. 그러면 시작할 수 있을 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6701] = {title = "비밀결사대 문장", objective = "우리는 오랜 세월 동안 끈질기게 비밀결사대와 싸워왔소. 실력으로 안 될 때는 머릿수로 밀어붙이는 녀석들이지. 아무리 빨리 녀석들을 처치해도 도무지 숫자가 줄어드는 기미가 안 보인단 말이지!\n\n녀석들의 숫자를 줄일 수 있는 가장 좋은 방법은 녀석들의 문장을 훔쳐오는 거요. 문장을 도난 당하면 문장을 지키지 못한 단원은 내부적으로 처리되겠지.\n\n녀석들의 주머니에서 문장을 남김 없이 꺼내 나에게 아니면 다른 경비병에게 가져다 주시오.\n\n여기서 남쪽에 있는 던홀드에서 시작해 보시오.", description = nil, progress = "우리는 오랜 세월 동안 끈질기게 비밀결사대와 싸워왔소. 실력으로 안 될 때는 머릿수로 밀어붙이는 녀석들이지. 아무리 빨리 녀석들을 처치해도 도무지 숫자가 줄어드는 기미가 안 보인단 말이지!\n\n녀석들의 숫자를 줄일 수 있는 가장 좋은 방법은 녀석들의 문장을 훔쳐오는 거요. 문장을 도난 당하면 문장을 지키지 못한 단원은 내부적으로 처리되겠지.\n\n녀석들의 주머니에서 문장을 남김 없이 꺼내 나에게 아니면 다른 경비병에게 가져다 주시오.\n\n여기서 남쪽에 있는 던홀드에서 시작해 보시오.", completion = "오, 잘했소! 계속하시오. 그러면 다른 &lt;class&gt;들도 당신을 무시하지 못할 거요.", rewards = nil},
[6721] = {title = "사냥꾼의 길", objective = "돌라나르에 있는 다잘라와 대화하십시오.", description = "안녕하신가, 젊은 사냥꾼 친구... 보아하니 자네는 야수를 길들여 벗으로 삼을 수 있을 정도로 솜씨가 좋은 것 같군.\n\n돌라나르에 있는 다잘라를 꼭 찾아가 보게. 그가 자네만의 야수를 얻을 수 있는 방법을 알려줄 걸세.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6722] = {title = "사냥꾼의 길", objective = "돌라나르에 있는 다잘라와 대화하십시오.", description = "안녕하신가, 젊은 사냥꾼 친구... 보아하니 자네는 야수를 길들여 벗으로 삼을 수 있을 정도로 솜씨가 좋은 것 같군.\n\n돌라나르에 있는 다잘라를 꼭 찾아가 보게. 그가 자네만의 야수를 얻을 수 있는 방법을 알려줄 걸세.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6741] = {title = "추가 전리품!", objective = "방어구 조각이 더 필요해! 좀 더 없소이까?", description = nil, progress = "방어구 조각이 더 필요해! 좀 더 없소이까?", completion = "고맙소. 당신은 호드의 긍지를 느끼게 해 주는군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n광택낸 갑옷"},
[6761] = {title = "새로운 미개척지", objective = "다르나서스의 세나리온 자치령에 있는 마스렌길 베어워커와 대화하십시오.", description = "달숲에서 보낸 지원 요청을 처리하는 문제는 내 부관인 마스렌길 베어워커에게 맡겨놓았으니 그 문제라면 내가 아니라 마스렌길을 찾아가야 할거야.\n\n단, 친구로서... 그대에게 한 가지 충고를 해 주지. 우리 종족이 모든 것을 잃고 어둠 속에서 방황할 때 이끌어준 것은 바로 이 몸이지 달숲에 있는 세나리온 의회가 아닐세. 텔드랏실은 우리 모두에게 새로운 생명을 주지! 아마 세나리온 의회에서는 다른 얘기를 하겠지만 그들의 거짓된 주장을 믿는 것은 바보나 할 짓이야.\n\n그러니까, 그대가 바보인가 아닌가 하는 것은 바로 자기 자신에게 달려있다는 말일세.", progress = nil, completion = "&lt;class&gt;|1이여;여;, 이렇게 와주셔서 고맙습니다. 오해가 있었다면 죄송해요. 이곳 대드루이드님과 달숲에 있는 수호자 레물로스 간에 불신의 골이 워낙 깊어서 말이에요. 그 둘은 서로 발뺌하고 있다며 의심하고 있어요. 게다가 알 수 없는 타락이 수그러들 줄을 모르고 텔드랏실을 물들여가고 있다는 사실도 문제랍니다. 이러한 상황은 불신을 타파하는 데 아무런 도움이 되질 않지요.\n\n그래도 세나리온 의회를 위한 우리의 임무는 여전히 남아 있는 거예요... 아무리 의회를 이끄는 자들이 서로 믿지 못한다고 해도 말이지요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6762] = {title = "라빈 사투르나", objective = "달숲, 나이트헤이븐에 있는 라빈 사투르나와 대화하십시오. 달숲은 악령의 숲과 여명의 설원 사이에 있으며 나무구렁 요새에서 나가는 길을 따라가면 됩니다.", description = "이번 임무를 위해서 그대는 라빈 사투르나라는 자를 찾아가야 해요. 달숲에 있는 수호자 레물로스의 청지기지요. 그가 지금 타나리스에서 서쪽으로 멀리... 운고로 보다 훨씬 더 멀리 떨어진 광활한 황무지를 탐험할 일손을 구하고 있어요. 라빈 사투르나는 달숲에서 가장 큰 마을인 나이트헤이븐에 살고 있답니다.\n\n이번에 그대가 맡게 될 일은 분명 우리 모두에게 큰 도움이 될 거예요. 단, 신중하게 처신하도록 하세요. 다르나서스와 달숲 간의 팽팽한 긴장이 하루가 달리 팽팽해지고 있으니까요.", progress = nil, completion = "제가 바로 라빈 사투르나입니다. 이 신성한 숲의 수호자 레물로스와 모든 주민을 대신해 그대를 환영합니다.\n\n스스로 열의와 관심을 가지고 세나리온 의회를 돕고자 자청하니 그저 감사할 따름입니다. 그대가 우리를 도울 거라는 사실에 대해 다르나서스의 대드루이드가 언짢아한다는 것을 익히 들어 알고 있습니다. 그러나 대의를 위해서 하는 일이니만큼 어떤 사악한 자의 표적이 되더라도 우리가 그대를 지켜줄 거란 사실을 잊지 마십시오.\n\n여기 있는 이들은 모두 그대의 친구이니 안심하셔도 좋습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6781] = {title = "방어구 조각", objective = "우리 군을 지원할 방어구 조각이 좀 더 필요하네!", description = nil, progress = "우리 군을 지원할 방어구 조각이 좀 더 필요하네!", completion = "아주 괜찮은 조각들을 가져왔군. 이걸로 우리 부대를 위해 새로운 장비를 만들 수 있겠어.\n\n보급품이 충분히 확보되면 우리 노련한 전투 부대가 전장에 뛰어들게 될 걸세!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n광택낸 갑옷"},
[6801] = {title = "얼음군주 로크홀라", objective = "나는 썬더 블러프에서 왔소, <race>. 이 험난한 시기에 서리늑대부족을 도와주라면서 케른님이 몸소 보내셨지.\n\n하지만 시간 낭비는 그만두도록 하지. 당신은 우리 적을 물리치고 녀석들의 피를 가져와야 하오. 피를 충분히 모으면 소환 의식을 거행할 수 있소.\n\n정령의 군주를 소환해 스톰파이크 군대를 치면 반드시 승리할 거요.", description = nil, progress = "나는 썬더 블러프에서 왔소, <race>. 이 험난한 시기에 서리늑대부족을 도와주라면서 케른님이 몸소 보내셨지.\n\n하지만 시간 낭비는 그만두도록 하지. 당신은 우리 적을 물리치고 녀석들의 피를 가져와야 하오. 피를 충분히 모으면 소환 의식을 거행할 수 있소.\n\n정령의 군주를 소환해 스톰파이크 군대를 치면 반드시 승리할 거요.", completion = "적들의 피로 계곡이 물들었군. 이 피를 지금까지 모아둔 것들과 합쳐야 겠소. 제물이 완성되면 얼음 군주께서 저 스톰파이크의 버러지들에게 서리늑대부족의 강한 분노를 맛보여 주실 것이오!", rewards = nil},
[6804] = {title = "독이 든 물", objective = "동부 역병지대에 있는 역병에 걸린 정령들에게 넵튤론의 상을 사용하십시오. 아즈샤라에 있는 군주 히드락시스에게 불협의 팔보호구 12개와 넵튤론의 상을 가져가야 합니다.", description = "정령 정찰부대 하나를 로데론 동부 역병지대로 보냈는데, 그 지역의 역병에 감염되고 말았다. 물의 군주들은 우리의 순결함에 이런 모욕을 가해지는 것을 묵인할 수 없노라!\n\n이 유리병을 받으라. 그 안에는 넵튤론의 상이 많이 들어 있다. 역병에 걸린 정령들에게 사용하면 그 몸 속에 든 독과 싸워 말끔히 치유해 줄 것이다! 하지만 몸 속에서 일어나는 충돌로 인해 정령들이 갑자기 광폭해질 것이다.\n\n그 불협의 광기를 물리치고 결속의 팔보호구를 가져와다오.", progress = "팔보호구는 가져왔는가?", completion = "수고했다, &lt;class&gt;|1이여;여;. 네가 치유한 타락한 정령들은 모든 물에 대한 모욕이었다. 우리의 힘은 우리의 순결함에 있고, 우리가 적과의 전쟁에서 이기려면 계속 강한 상태를 유지해야만 한다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6805] = {title = "먼지 폭풍과 우레의 모래정령", objective = "먼지 폭풍 15마리와 우레의 모래정령 15마리를 처치하고 아즈샤라에 있는 군주 히드락시스에게 돌아가야 합니다.", description = "우리 물의 정령들은 하급 원소의 존재들과 전쟁을 치르고 있다. 네가 이 전쟁에서 진정으로 우리의 동지가 되겠다면 그 결의를 입증해 보여야 할 것이다!\n\n남쪽으로 멀리 떨어져 있는 실리더스라는 사막 지대에 바람과 대지의 종들이 수정 골짜기라는 바위 구석을 돌아다니고 있다. 이들은 강력한 물건들을 보다 하급 존재인 필멸의 생명체들이 손대지 못하도록 지키고 있는데, 녀석들이 왜 그러는지는 모르겠지만 녀석들의 계획을 수포로 만들어 버리고 싶다.\n\n실리더스에 있는 수정 골짜기로 가서 우리 적들을 물리치고 내게 돌아오도록 하라.", progress = nil, completion = "네 용기와 함께 너의 가치도 입증되었구나. 앞으로 네게 다른 임무를 맡기게 될지도 모르겠다. 물의 군주들의 소중한 동지에게 더 잘 어울리는 임무 말이지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6821] = {title = "엠버시어의 눈", objective = "아즈샤라에 있는 군주 히드락시스에게 엠버시어의 눈을 가져가야 합니다.", description = "너는 우리 적을 물리치고 물의 군주들의 대의를 높이기 위한 임무를 수행할 수 있다는 것을 보여 주었다. 하지만 지금까지 네가 싸워 온 상대는 비교적 쉬운 적들이었지... 강력한 적에 맞서서도 승리를 거둘 수 있을까?\n\n바로 그것이 너의 새 임무다.\n\n저 위 검은바위 첨탑의 오크들이 불의수호자 엠버시어라는 불의 종을 잡아 두고 있다. 엠버시어가 갇혀 있는 장소를 찾아내 그를 가둔 자들을 처치한 후 엠버시어도 처치하라. 네 가치를 입증할 수 있도록 엠버시어의 눈을 가져오도록 하라.", progress = "엠버시어의 눈을 가져왔느냐? 네게 검은바위 첨탑에 들어갈 만한 힘이 있더냐?", completion = "아, 네게 정말로 그런 힘이 있었군. 게다가 머리도 아주 뛰어나고 말이야. 검은바위 첨탑은 강한 힘만으로는 들어갈 수 없는 곳이니...\n\n너는 우리에게 진정으로 값진 동지가 될지도 모르겠구나...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6822] = {title = "화산 심장부", objective = "불의 군주 1마리, 용암거인 1마리, 고대의 심장부 사냥개 1마리, 굽이치는 용암 정령 1마리를 처치한 후 아즈샤라에 있는 군주 히드락시스에게 돌아가야 합니다.", description = "어쩌면 이제 너에게 진정한 시험을 치르게 할 때가 됐는지도 모르겠군. 준비됐느냐?\n\n검은바위 나락 맨 아래에는 화산 심장부로 통하는 길이 있다. 화산 심장부는 우리의 적, 이 세계에서 가장 강력한 불의 종들이 점령하고 있는 요새지.\n\n화산 심장부로 가라. 그곳에서 만나게 되는 모든 적을 물리칠 힘과 의지가 있다는 것을 보여다오.\n\n그리고 화산 심장부로 들어가서 살아남으려면 군대 정도는 되어야 하니까 네 동료들이 있다면 불러 모으도록 하라.", progress = nil, completion = "너는 네 종족의 대부분이 불가능하다고 생각할 일을 해냈다. 화산 심장부의 존재들을 상대해 승리를 거뒀다니 말이야!\n\n그렇게 작은 몸으로 아주 대단한 실력을 보여 주었구나.\n\n언젠가 너희 종족과 물의 군주들 간에 진정한 신뢰 관계를 맺게 될지도 모르겠다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6823] = {title = "히드락시스의 하수인", objective = "히드락시스 물의 군주들로부터 우호적인 평판을 얻은 후 아즈샤라에 있는 군주 히드락시스와 대화해야 합니다.", description = "진정으로 우리를 받들고자 한다면 우리의 적, 즉 바람과 대지, 그리고 불의 종들과 싸우도록 하라. 이들 각각을 물리칠 때마다 이곳에서 녀석들의 기반이 약화될 것이고 우리 대의에 대한 네 충성을 보다 잘 입증해 보이게 될 것이다.\n\n긴 싸움이 되겠지만 인내심을 가지고 극복해 낸다면 큰 영광과 명예를 얻게 될 것이다.", progress = nil, completion = "우리의 적을 상대로 세운 네 위업에 대한 소문이 물의 군주들 사이에 자자하구나. 어떤 이들은 우리 전쟁에서 싸우기에는 네 몸이 너무 작고 약하다고 생각했었지만 너는 아주 큰 일을 해 냈다. 이제 우리들 사이에서 존중을 받게 되었고. 정말 믿을 수 없을 만큼 대단한 일이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6824] = {title = "적의 손", objective = "아즈샤라에 있는 군주 히드락시스에게 루시프론, 설퍼론, 게헨나스, 샤즈라의 손을 가져가야 합니다.", description = "너는 우리에게 큰 도움이 되고 있기 때문에 이번 마지막 임무에 너를 보내기가 망설여지는구나. 너처럼 뛰어난 요원을 잃고 싶진 않으니까 말이다.\n\n하지만 성공할 경우 우리 전쟁에 아주 큰 도움이 될 테고... 그래서 위험을 무릅쓰고 너를 보낼 만한 가치가 있다고 판단했다.\n\n화산 심장부의 부대장들인 루시프론, 설퍼론, 게헨나스, 그리고 샤즈라를 처치해 주기 바란다. 놈들을 처치하고 그 손을 가져와라!\n\n이번 임무를 완수하기 위해서는 네 모든 능력을 총동원해야 할 테지만, 성공한다면 불의 군주들에게 엄청난 타격을 입히게 될 것이다.", progress = "루시프론과 다른 부대장들을 모두 처치했는가?", completion = "가져왔군! 드디어 불의 부대장들을 처치했어! 내가 너와 너의 실력을 몰랐더라면 절대 불가능한 일로 여겼을 것이다.\n\n너는 지금까지 무수한 위업을 세웠지만 이번 마지막 임무에 대한 얘기는 물의 군주들 사이에서도 큰 화젯거리가 될 것이다. 네 이름이 훗날 우리에게 전설로 남게 될지도 모르지.\n\n또 다른 임무를 맡기게 될지도 모르니 다음에 다시 나를 찾아오도록 하라...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6825] = {title = "바람의 부름 - 구스의 편대", objective = "우리는 새로운 전투 와이번 편대를 준비해야 한다! 내 편대는 전장의 중심부를 공격할 준비는 됐지만 그 전에 먼저 와이번의 식욕부터 돋구어줘야 해.\n\n편대 전체의 배를 채워줄 수 있는 스톰파이크 병사의 전투식량이 필요하다! 수백 개는 되어야 할 것이다! 그 정도는 문제 없겠지? 어서 가도록!", description = nil, progress = "우리는 새로운 전투 와이번 편대를 준비해야 한다! 내 편대는 전장의 중심부를 공격할 준비는 됐지만 그 전에 먼저 와이번의 식욕부터 돋구어줘야 해.\n\n편대 전체의 배를 채워줄 수 있는 스톰파이크 병사의 전투식량이 필요하다! 수백 개는 되어야 할 것이다! 그 정도는 문제 없겠지? 어서 가도록!", completion = "우리 와이번은 스톰파이크 병사가 지니고 다니는 전투식량을 아주 좋아한다. 적의 식량을 먹어 치우고 힘을 내는 것이지.\n\n자, 출격이 임박했다!", rewards = nil},
[6826] = {title = "바람의 부름 - 제즈톨의 편대", objective = "그대는 지금까지 열심히 해왔지만 우리는 이제 겨우 시작일뿐이다!\n\n내 와이번은 목표가 될 녀석들의 전투식량 맛을 봐야 한다. 그래야 힘을 내서 적에게 치명타를 입힐 수가 있거든!\n\n내 편대는 우리 공군 중에서도 두 번째로 강하고 따라서 적들 중에서도 가장 강한 놈들과 싸우게 될 것이다. 그런고로 우리 전투 와이번에게는 스톰파이크 부관의 전투식량이 필요하다.\n\n서두르도록!", description = nil, progress = "그대는 지금까지 열심히 해왔지만 우리는 이제 겨우 시작일뿐이다!\n\n내 와이번은 목표가 될 녀석들의 전투식량 맛을 봐야 한다. 그래야 힘을 내서 적에게 치명타를 입힐 수가 있거든!\n\n내 편대는 우리 공군 중에서도 두 번째로 강하고 따라서 적들 중에서도 가장 강한 놈들과 싸우게 될 것이다. 그런고로 우리 전투 와이번에게는 스톰파이크 부관의 전투식량이 필요하다.\n\n서두르도록!", completion = "더 많이! 더 많이! 곧 준비가 끝나니 더 많이 가져오도록!", rewards = nil},
[6827] = {title = "바람의 부름 - 멀베릭의 편대", objective = "드워프 소굴에 며칠 동안이나 갇혀 있었으니 그에 걸맞은 복수를 해줘야지!\n\n신중하게 계획을 세워야 한다.\n\n먼저 전투 와이번에게 목표를 정해줘야 한다. 가장 우선수위가 높은 목표들로 말이지. 따라서 와이번에게 먹일 스톰파이크 사령관의 전투식량이 필요하다. 유감스럽게도 녀석들은 적진 후방 깊숙한 곳에 숨어 있지! 아주 고된 일이 될 것이다, 병사.", description = nil, progress = "드워프 소굴에 며칠 동안이나 갇혀 있었으니 그에 걸맞은 복수를 해줘야지!\n\n신중하게 계획을 세워야 한다.\n\n먼저 전투 와이번에게 목표를 정해줘야 한다. 가장 우선수위가 높은 목표들로 말이지. 따라서 와이번에게 먹일 스톰파이크 사령관의 전투식량이 필요하다. 유감스럽게도 녀석들은 적진 후방 깊숙한 곳에 숨어 있지! 아주 고된 일이 될 것이다, 병사.", completion = "부족해! 신참 병사라면 이 정도라도 그냥 넘어가겠지만 자네가 이 정도 밖에 안 된다는 것인가? 제대로 해라, 병사! 전투식량이 더 필요하다!", rewards = nil},
[6844] = {title = "기록관 움버", objective = "달숲의 나이트헤이븐 마을에 있는 세나리온 의회의 기록관, 움버에게 딱딱한 실리시드 조각을 가져가야 합니다.", description = "여기서 해야 할 일들이 아직 많이 남아 있지만, 무엇보다 우선 분석을 위해 이걸 다시 세나리온 의회로 가져가야 할 것 같소. 이 일을 다 마치고 돌아와도 하던 일을 그대로 계속할 수 있을 테니까 안심하시오. 이 끈끈한 껍데기 안에 든 것이 일지라면 세나리온 의회에서 마침내 과거를 들여다볼 수 있게 되는 것이오!\n\n이걸 나이트헤이븐에 있는 세나리온 의회의 기록관에게 가져가시오. 그 친구의 이름은 움버라고 하는데, 머리가 아주 뛰어난 자요. 약간 실성하긴 했지만 그래도 아주 영리하오! 이보다 훨씬 더 안 좋은 상태의 책들도 복구해 냈으니까 말이오. 이 물건을 복구할 수 있는 사람이 있다면 그건 바로 움버요.", progress = "어이, 안녕하십니까! 허엄...\n\n솔직히 말하는 건데, 당신한테서는... 좀 노인네 냄새 같은 게 나는군요. 그러니까 불쾌한 냄새가 난단 말이죠. 뭐, 인신 공격을 하려는 건 아닙니다. 그저... 앞으로는 밖에서 들어올 때 좀 깨끗이 씻고 오라는 겁니다. 첫인상이 썩 괜찮아질 테니까 말이죠!\n\n그나저나... 무슨 일로 오셨죠?", completion = "이런 세상에! 이게 도대체 뭐죠? 뭐, 책 모양 비슷하게 생긴 것 같긴 한데... 내가 이 껍질을 한번 깨 보겠습니다.\n\n실리더스에서 라요가 보내서 왔다고요? 그곳에서 끔찍한 일이 일어나고 있다고 사람들이 비밀스럽게 속닥대는 걸 듣긴 했는데, 어떻게 보면 속닥거린 거라고 할 수 없을 것도 같고... 게다가 나는 벌레처럼 생긴 거라면 딱 질색인데, 당신이 별 희한한 걸 다 가져와서 나를 이곳에 머무르게 하는군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6845] = {title = "과거의 비밀 밝히기", objective = "달숲의 나이트헤이븐에 있는 라빈 사투르나와 대화해야 합니다.", description = "어쨌거나 조금 있다 다시 날 찾아오십시오... 그러니까 이 안에 뭐가 들었는지 알고 싶으면 말이지. 내가 알아내는 즉시, 그리고 이 안에 든 게 정말로 책이라면 기꺼이 당신한테 가르쳐 주겠습니다.\n\n그 동안 이 작은 야영지의 어미곰격인 라빈하고 얘기나 나눠 보십시오. 틀림없이 당신이 어떤 괴상한 장난을 치고 다녔는지 듣고 싶어할 겁니다. 어미 곰을 기다리게 하지 마십시오... 그러니까 내 말은, 꿀을 뒤집어쓰고 싶지 않다면 말입니다.\n\n진짜로 그런 적이 있다니까, 내 말을 믿으세요.", progress = nil, completion = "아, 그대로군. 마침 그대를 만나고 싶어하던 참이었소. 건강해 보여 다행이구려.\n\n그대가 올 거라는 소식을 듣고 지금까지 그대가 도와 준 데 대해 세나리온 의회를 대신해 직접 감사를 표하고 싶었소이다. 물론 실리더스로부터 밝혀내야 할 비밀이 아직 더 남아 있지만 움버에게 가져다 준 물건을 파헤치면 아주 흥미로운 발견을 하게 될 거요. 자, 우리를 도와 준 데 대해 계속해서 감사를 표하는 바이오. 이걸 받아 주시오.\n\n헌신적으로 도와 줘서 고맙소, &lt;class&gt; 친구.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n생명석 반지적열하는 수정 반지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6846] = {title = "공격 개시!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6847] = {title = "비밀결사대장 라이슨의 천리안", objective = "겨울도끼 동굴에서 천리안을 회수한 후, 비밀결사대장 라이슨에게 가져가야 합니다.\n\n비밀결사대장 라이슨의 천리안은 끔찍한 저주를 불러들인다고 전해지니 조심해야 합니다!", description = "자네들이 알터랙의 심장부에서 전쟁을 치른다 해도 비밀결사대는 아랑곳하지도 않네. 우리는 언제나 그래왔듯이 이 광기의 잿더미와 폐허 속에서 확실한 승자가 일어서길 기다렸다가 공격할 뿐이지.\n\n하지만 오늘 여기에 모인 이유는 그 때문이 아닐세. 이 지역의 겨울도끼 트롤들이 천리안을 빼앗아갔네.\n\n천리안을 가지고 오면 자네와 자네 동료에게 얼마의 시간이 남든 끝까지 도와주도록 하지.\n\n눈을 가지고 즉시 내게 돌아오면 자네가 임무를 완수했는지 확인할 수 있을 것일세.<씩 웃는 비밀결사대장 라이슨>퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[6848] = {title = "비밀결사대장 라이슨의 천리안", objective = "겨울도끼 동굴에서 천리안을 회수한 후, 비밀결사대장 라이슨에게 가져가야 합니다.\n\n비밀결사대장 라이슨의 천리안은 끔찍한 저주를 불러들인다고 전해지니 조심해야 합니다!", description = "자네들이 알터랙의 심장부에서 전쟁을 치른다 해도 비밀결사대는 아랑곳하지도 않네. 우리는 언제나 그래왔듯이 이 광기의 잿더미와 폐허 속에서 확실한 승자가 일어서길 기다렸다가 공격할 뿐이지.\n\n하지만 오늘 여기에 모인 이유는 그 때문이 아닐세. 이 지역의 겨울도끼 트롤들이 천리안을 빼앗아갔네.\n\n천리안을 가지고 오면 자네와 자네 동료에게 얼마의 시간이 남든 끝까지 도와주도록 하지.\n\n눈을 가지고 즉시 내게 돌아오면 자네가 임무를 완수했는지 확인할 수 있을 것일세.<씩 웃는 비밀결사대장 라이슨>퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[6861] = {title = "진피즐렉스의 휴대용 벌목기 장치", objective = "수석기술자 진피즐렉스가 다음의 물건을 가져다 달라고 부탁했습니다.\n\n*토륨 주괴 30개\n\n*미스릴 주괴 50개\n\n*철 주괴 75개\n\n*증기톱 1개", description = "나도 자네만큼이나 내 휴대용 벌목기 장치를 써 보고 싶어 죽겠다고, <race> 친구. 하지만 그 장치를 만들기 위해선 필요한 게 있거든. 그것도 아주 많이 말이야!\n\n정확히 말해, 토륨, 미스릴, 그리고 철이 산더미만큼 필요하지. 또 장치마다 벌목지에서 구할 수 있는 증기톱도 하나씩 필요하고 말이야.\n\n내가 여기서 이리저리 알아보러 다니다가 발견한 건데, 그러니까 내가 붙잡히기 전에 말이지, 스톰파이크 벌목지에 증기톱이 잔뜩 쌓여 있더라고.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n진피즐렉스의 휴대용 벌목기 장치"},
[6862] = {title = "진피즐렉스의 휴대용 벌목기 장치", objective = "수석기술자 진피즐렉스가 다음의 물건을 가져다 달라고 부탁했습니다.\n\n*토륨 주괴 30개\n\n*미스릴 주괴 50개\n\n*철 주괴 75개\n\n*증기톱 1개", description = "나도 자네만큼이나 내 휴대용 벌목기 장치를 써 보고 싶어 죽겠다고, <race> 친구. 하지만 그 장치를 만들기 위해선 필요한 게 있거든. 그것도 아주 많이 말이야!\n\n정확히 말해, 토륨, 미스릴, 그리고 철이 산더미만큼 필요하지. 또 장치마다 벌목지에서 구할 수 있는 증기톱도 하나씩 필요하고 말이야.\n\n내가 여기서 이리저리 알아보러 다니다가 발견한 건데, 그러니까 내가 붙잡히기 전에 말이지, 서리늑대 벌목지에 증기톱이 잔뜩 쌓여 있더라고.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n진피즐렉스의 휴대용 벌목기 장치"},
[6881] = {title = "숲군주 이부스", objective = "서리늑대부족은 오염된 원소의 힘에 의해 보호받고 있어요. 녀석들의 주술사가 그냥 내버려두었다가는 틀림없이 우리 모두를 파괴해 버리게 될 마력을 갖고 장난하고 있죠.\n\n세나리온 의회에서 진압하기에는 그 피해가 너무 커져 버렸어요! 이부스님의 도움을 받아야만 합니다.\n\n서리늑대부족 병사들은 폭풍 수정이라는 자연 원소 부적을 가지고 다니는데, 그 부적들을 사용해 이부스님을 소환할 수 있답니다. 가서 그 수정들을 빼앗아 오세요!", description = nil, progress = "서리늑대부족은 오염된 원소의 힘에 의해 보호받고 있어요. 녀석들의 주술사가 그냥 내버려두었다가는 틀림없이 우리 모두를 파괴해 버리게 될 마력을 갖고 장난하고 있죠.\n\n세나리온 의회에서 진압하기에는 그 피해가 너무 커져 버렸어요! 이부스님의 도움을 받아야만 합니다.\n\n서리늑대부족 병사들은 폭풍 수정이라는 자연 원소 부적을 가지고 다니는데, 그 부적들을 사용해 이부스님을 소환할 수 있답니다. 가서 그 수정들을 빼앗아 오세요!", completion = "수고했습니다. 나는 이 부적의 힘을 이미 모아 놓은 마법의 힘을 늘리는 데 사용할 것입니다. 마법의 힘이 충분히 모이면, 축적된 힘을 집중하여 우리의 목적을 이루는 데 도움을 주실 숲군주님을 소환할 것입니다.", rewards = nil},
[6901] = {title = "공격 개시!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6921] = {title = "폐허 사이로", objective = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다.", description = "황혼의망치단은 검은심연의 나락에 있는 달의 제단 폐허로 이동했네. 그곳에 머무르면서 그들은 자연의 원소들이 우리에게 불리하게 작용하도록 만들어 버릴 수 있을 거야. 그대로 내버려두었다가는 이 지역이 완전히 놈들의 손아귀에 넘어갈지도 모르는 일이지.\n\n<name>, 검은심연의 나락으로 가서 달의 제단 폐허에 있는 심연의 돌을 찾게. 아마 그 근방 물 속 어딘가에 있을 걸세. 그 돌 안에는 심연의 핵이 들어 있는데, 제대로 해석할 수만 있다면 모든 정령의 역사를 알아낼 수 있을지도 몰라. 그걸 내게 가져오면 속세의 고리회의 힘을 빌어 황혼의망치단을 저지할 수 있을거야!", progress = "심연의 핵은 찾았나? 그게 없으면 황혼의망치단이 대체 거기서 뭘 하려는 작정인지 알아낼 수 없단 말일세.", completion = "그래, 이게 바로 내가 찾던 거야! 이제 곧 이 심연의 핵에서 유용한 정보를 잔뜩 뽑아 낼 수 있을 걸세. 황혼의망치단이 거기서 무슨 짓을 꾀하고 있든 내가 동료들과 함께 전부 밝혀내고 말겠어. 틀림없이 사악하기 그지없는 음모를 꾸미고 있을 테지. 내 장담할 수 있어.\n\n참, 그리고 수고했네. 우리를 도와 준 일에 대해 속세의 고리회에서도 자네에게 감사해하고 있다는 것을 부디 알아주게. 그리고 이번 일은 분명 호드 전체에도 큰 도움이 되었어. 자네가 정말 자랑스럽네!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6922] = {title = "군주 아쿠아니스", objective = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다.", description = "물의 정령이 쓰러지면서 이상한 물구슬을 하나 남겼습니다. 이 구슬이 바로 괴력의 원천이었나 봅니다. 구슬 안에서 출렁거리는 물을 바라보자 묘하게도 어떤 끔찍한 느낌이 듭니다. 하지만 구슬 자체는 어떠한 외부의 힘에도 손상되지 않는 듯합니다.\n\n이 구슬에 대해 알고 있는 이가 있다면 그건 바로 속세의 고리회의 제네우 생크리일 것입니다. 그는 잿빛 골짜기의 조람가르 전초기지에 있습니다.", progress = "아, <name>. 또 보는군. 난 늘 그렇듯이 여기서 물결의 흐름을 보고 있었네. 그래... 전초기지에는 무슨 일로 왔나?", completion = "오... 이건 정말 대단한 발견일세.\n\n&lt;name&gt;, 이걸 검은심연의 나락에서 군주 아쿠아니스를 처치하고 얻었다고 했나? 오랜 세월동안 아쿠아니스는 아제로스의 정령들에게 사악한 기운을 불어넣는 장본인으로 알려져 왔네. 무엇이 그를 타락하게 했는지 이 구슬이 알려줄 것 같군. 그게 황혼의망치단으로 밝혀진다고 해도 그리 놀랄 일은 아니겠지만... 계속 연구를 하다 보면 정령들이 어떻게 해서 타락의 구렁텅이로 빠져들었는지 알아낼 수 있겠지.\n\n잘했네. 속세의 고리회를 대신하여 내리는 고마움의 표시이니 이것을 받게.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n무법자 사브르마녀의 손가락\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[6941] = {title = "바람의 부름 - 비포르의 편대", objective = "전선을 수비하고 있는 서리늑대부족 정예 부대를 쓰러뜨려야 하네! 그 야만족 무리의 숫자를 줄이는 임무를 그대에게 맡기겠네. 녀석들의 부관과 부대원의 견장을 가져오도록 하게. 그 쓰레기 같은 녀석들의 수가 충분히 줄어들었다고 판단될 때 공습을 개시하겠네.", description = nil, progress = "전선을 수비하고 있는 서리늑대부족 정예 부대를 쓰러뜨려야 하네! 그 야만족 무리의 숫자를 줄이는 임무를 그대에게 맡기겠네. 녀석들의 부관과 부대원의 견장을 가져오도록 하게. 그 쓰레기 같은 녀석들의 수가 충분히 줄어들었다고 판단될 때 공습을 개시하겠네.", completion = "곧 출격 준비가 완료될 것이니 계속 주어진 임무에 최선을 다하도록 하게!", rewards = nil},
[6942] = {title = "바람의 부름 - 실도르의 편대", objective = "우리 그리핀 부대가 최전방에 공습을 가할 준비가 됐는데, 적의 수가 줄어들기 전에는 출격할 수가 없다.\n\n최전방을 지키는 임무를 맡은 서리늑대부족 전사들은 가슴에 견장을 자랑스럽게 달고 다니는데, 녀석들을 쓰러뜨리고 견장을 빼앗아서 여기로 가져오도록 해라.\n\n최전방에서 녀석들의 수가 충분히 줄어들면 공습을 개시하겠다! 창공에서 죽음을 선사하리라!", description = nil, progress = "우리 그리핀 부대가 최전방에 공습을 가할 준비가 됐는데, 적의 수가 줄어들기 전에는 출격할 수가 없다.\n\n최전방을 지키는 임무를 맡은 서리늑대부족 전사들은 가슴에 견장을 자랑스럽게 달고 다니는데, 녀석들을 쓰러뜨리고 견장을 빼앗아서 여기로 가져오도록 해라.\n\n최전방에서 녀석들의 수가 충분히 줄어들면 공습을 개시하겠다! 창공에서 죽음을 선사하리라!", completion = "견장을 계속 가져오도록 하라, 병사! 이제 곧 맹금의 그리핀들의 출격 준비가 완료될 것이다!", rewards = nil},
[6943] = {title = "바람의 부름 - 이크만의 편대", objective = "그리핀들의 사기가 저하되어 있소. 호드에게 가했던 지난 번 공습이 실패한 후 비행을 거부하고 있소이다! 그들의 사기를 고무시키는 것이 귀관의 임무요.\n\n전투 지역으로 돌아가서 서리늑대부족 사령부의 심장부를 공격하도록 하시오. 놈들의 사령관과 수호병들을 쓰러뜨리고 귀관의 배낭 안에 넣을 수 있는 만큼 많은 견장을 가지고 돌아오도록 하시오! 분명히 우리 그리핀들이 그 견장들을 보고 적의 피 냄새를 맡게 되면 다시 날아오를 것이오! 즉시 임무를 수행하시오!", description = nil, progress = "그리핀들의 사기가 저하되어 있소. 호드에게 가했던 지난 번 공습이 실패한 후 비행을 거부하고 있소이다! 그들의 사기를 고무시키는 것이 귀관의 임무요.\n\n전투 지역으로 돌아가서 서리늑대부족 사령부의 심장부를 공격하도록 하시오. 놈들의 사령관과 수호병들을 쓰러뜨리고 귀관의 배낭 안에 넣을 수 있는 만큼 많은 견장을 가지고 돌아오도록 하시오! 분명히 우리 그리핀들이 그 견장들을 보고 적의 피 냄새를 맡게 되면 다시 날아오를 것이오! 즉시 임무를 수행하시오!", completion = "보이시오? 저 용맹한 모습의 그리핀들을 보시오! 사기를 되찾고 있어... 곧 이 이크만님의 편대가 다시 한번 계곡의 심장부를 공격할 것이야! 스톰파이크 경비대가 하늘을 다스리게 될 것이오!", rewards = nil},
[6961] = {title = "겨울 할아버지, 우리 마을에 오셨네!", objective = "오그리마에 있는 굴뚝나무 목장조합상인 근처에 있는 겨울 할아버지를 만나 대화해야 합니다.", description = "즐거운 겨울맞이 축제가 되라고! 겨울 할아버지에게 꼭 인사하는 것 잊지 말고! 올해 착한 일을 많이 했으면 겨울맞이 축제에 선물을 많이 받게 될 거야. 겨울 할아버지에게 올해 꼭 갖고 싶은 게 뭔지 꼭 얘기하라고!\n\n참, 올 한해 고마웠던 친구들에게 한 턱 내는 건 어때? 마침 내게 선물용으로 아주 괜찮은 물건이 있는데 말이지. 굴뚝나무 목장조합에서 직접 재배한 신선한 음식을 맛보라고! 맛도 그만이지만 몸에도 좋지!", progress = nil, completion = "안녕?! 꼬마 친구, 난 겨울 할아버지라고 해요. 어이쿠, 굴뚝나무 목장조합 친구들도 여러분들에게 인사를 전하고 싶다고 하는군요. 이 친구들은 직영 농장에서 직접 거둔 재료로 만든 신선도 100%의 건강식을 아제로스 전역에 제공하고 있지요. 맛있는 음식과 함께 즐거운 겨울맞이 축제 맞으세요! 호호호!\n\n올 한해 착한 일을 많이 했다면 굴뚝나무 목장조합에서 푸짐한 선물을 받을 수 있을 거예요. 겨울맞이엔 누구나 베푼 만큼 거두는 법이지요... 만세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6962] = {title = "겨울 할아버지 대접하기", objective = "오그리마의 겨울 할아버지에게 생강 과자빵 5개와 시원한 우유 한 잔을 갖다 주어야 합니다.", description = "젊은 <class>|1이여;여;, 이 겨울 할아버지가 조그만 부탁이 하나 있는데 들어줄래요?\n\n당신이 객관적으로 봐도 여기 하루종일 서 있는 게 그리 유쾌한 일은 아니겠지요? 달콤한 걸 좀 먹으면 기운이 날 것 같은데... 생강 과자빵이랑 시원한 우유만 있어도 참 좋겠어요. 이 할아버지랑 친구 하고 싶지요? 그렇다면 좀 갖다 줄래요?", progress = "간식 얘기를 꺼냈더니 더욱 허기가 지는군요. 흐음... 생강 과자빵에 시원한 우유라...", completion = "당신은 정말 멋진 친구로군요. 즐거운 겨울맞이 축제가 되기를 다시 한번 빌겠어요.\n\n자, 이걸 받으세요. 당신의 수고에 대해 고마움을 전하기 위한 제 작은 성의입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n굴뚝나무 목장조합 선물꾸러미"},
[6963] = {title = "도둑맞은 장난감", objective = "알터랙 산맥의 어딘가 눈 덮인 지역에서 실종된 굴뚝나무 목장조합의 수색 요원을 찾아야 합니다.", description = "내 얘기 좀 들어봐. 흥겨운 명절 분위기를 깨고 싶지는 않지만 굴뚝나무 목장조합에서는 뜻하지 않은 사고로 모험가의 도움을 필요로 하고 있어.\n\n축제에 없어서는 안 될 귀중한 장난감이 담긴 굴뚝나무 목장조합의 화물이 사라졌다니까. 그걸 찾으러 보낸 우리 요원도 실종된 상태고! 부탁이야... 마지막으로 그 화물의 흔적을 알터랙 산맥 부근에서 보았다는 제보를 받고 우리 요원도 그리로 갔어.\n\n화물을 찾으러 간 우리 요원이 무사한지 꼭 좀 확인해 줘!", progress = nil, completion = "날... 날 찾으러... 왔구나! 정말이지 고마워서 코끝까지 찡해지는군!\n\n진짜로 난 그냥 눈...사람이 아니야. 내 이름은 삭스야. 오... 오... 오그리마의 굴뚝나무 목장조합에서 일했지... 나... 나는 도둑맞은 물건 찾는 임무를 맡아 여기로 왔는데 난생 처... 처음 보는 괴물한테 당했지 뭐야!\n\n추... 추워... 너...무... 호오...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6964] = {title = "축제의 유래", objective = "오그리마의 지혜의 골짜기에 있는 사고른 크레스트스트라이더와 겨울맞이 축제에 대한 대화를 나누어야 합니다.", description = "선물이나 주고받고 흥청거리다니... 바보들!\n\n경박한 고블린들이 겨울맞이 축제의 진정한 의미를 퇴색시키고 있네. 겨울맞이는 곧 부활과 회복을 뜻하지. 대지는 겨울 할아버지께서 내리신 포근한 눈을 덮고 깊고 조용한 잠을 자는 거야. 저기 우스꽝스러운 빨간 옷을 입고 있는 멍청이가 진짜 겨울 할아버지일 리가 없잖아!\n\n축제의 진정한 의미를 알고 싶거든 사고른 크레스트스트라이더를 찾아가도록! 선물에 정신 팔린 놈들이 천지인 이 시기에 역사가 주는 진정한 교훈에 관심을 가진 자네 같은 이도 있다는 걸 알면 분명 놀랄 거야.", progress = nil, completion = "겨울맞이 축제라고요? 과거에 겨울맞이 축제는 우리 타우렌들에게 상당한 의미를 지녔었죠. 요즘은 어떤 약삭빠른 놈들이 겨울 할아버지의 전설을 이용해 사탕과 선물을 팔아먹고 있더군요. 정말 안타까운 일이지요.\n\n이렇게 변질된 현실에 푸르문드가 냉소를 보내는 것도 당연하죠. 푸르문드와 뜻을 같이하는 몇몇 타우렌들은 전투의 깃발과 같은 전통을 지키며 살고 있어요. 흥겨운 축제 분위기를 조금쯤 즐기는 것도 좋겠지만, 그 진정한 유래를 기억하는 일이 훨씬 중요하죠.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6981] = {title = "빛나는 조각", objective = "톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오.\n\n그에게 지시를 받아, 빛나는 조각을 전달해야 합니다.", description = "이 조각은 밝은 녹색을 띠고 있습니다. 겉은 단단해 보이지만 수정 안에는 연기 같은 것이 소용돌이치고 있습니다. 그 연기는 눈길을 끌며 뭔가 굉장히 불길한 예감이 듭니다.\n\n혹시 이 이상한 조각에 대한 얘기를 해줄 이가 있는지 톱니항에서 찾아보는 게 좋을 것 같습니다.", progress = "안녕하세요, <race>|1이여;여;. 무엇을 도와드릴까요?", completion = "어... 이런 건 태어나서 처음 보는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6982] = {title = "얼음이빨 광산 보급품", objective = "던 발다르에 있는 얼라이언스 병참장교에게 얼음이빨 광산 보급품 10개를 가져가야 합니다.", description = "얼음이빨 광산은 호드의 보급창고라오. 녀석들이 부대에 지급하는 식량은 소화가 안 되고 무기나 방어구 상태도 정말 형편없지! 하지만... 요즘처럼 보급품이 귀한 때에는 녀석들이 쓰는 것이라도 귀중한 자원이라오.\n\n얼음이빨 광산에 들어가서 녀석들의 보급품을 좀 가져오시오. 그렇게 하면 얼라이언스군이 계속 전투 태세를 유지하는 데 도움이 될 뿐 아니라, 호드 전사들에게서 녀석들이 꼭 필요로 하는 장비들을 빼앗게 되는 일거양득의 효과를 보게 될 것이오.\n\n얼음이빨 광산은 남쪽 멀리, 호드 진영 깊숙한 곳에 있소이다. 행운을 빌겠소.", progress = "호드 진영 내에 있는 얼음이빨 광산에는 들어가 봤소? 녀석들의 보급품을 빼앗아 온 거요?", completion = "가져왔군! 수고했소이다! 이 보급품을 꼼꼼히 살펴본 후 우리 부대가 쓸 수 있도록 준비하도록 하겠소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[6983] = {title = "고약한 녀석...", objective = "도둑맞은 장난감을 찾아 오그리마에 있는 케이말드 코퍼핀치에게 돌려주어야 합니다. 도둑맞은 장난감은 알터랙 산맥의 눈 덮인 지역 어딘가에서 목격된 썩은내 그린치가 마지막으로 가지고 있었던 것 같습니다.", description = "\"썩은내 그린치\"라는 녀... 녀석이 우...운송 중이던 우... 우리 음식과 장난감을 후... 훔쳐 갔어요. 하... 하지만 조... 심하세요! 저를 이 누... 눈 덩어리로 마... 만들어 버린 녀석이니까!\n\n그 녀석을 사... 상대하려면 도움이 피... 필요할 겁니다. 서... 설인들이 있는 곳에서 활개치며 도... 돌아다니는 걸 본 적이 있으니 부... 분명 여... 여기 어딘가에 있을 거예요! 그 음식과 장난감을 찾아 아... 아이언포지에 있는 굴뚝나무 목장조합에 도... 돌려주고 절 해... 해동시켜 달라고 전해... 주세요.", progress = "그걸 되찾아 쌓아 두지 못하면 겨울맞이 축제를 망치게 될 거야! 그라추마저도 올 한해 동안 착한 일을 한 모든 아이들에게 맛있는 고기 파이를 나눠 주지 못하게 된단 말이라고...", completion = "찾았군! 당신이 굴뚝나무 목장조합의 겨울맞이 축제를 구했군!\n\n불쌍한 삭스 녀석... 꼭 사람들을 보내 그를 해동시킬 방법을 알아보도록 하겠어. 축제 당일까지는 돌아올 수 있으면 좋으련만. 근무하지 못한 시간을 보충하긴 해야겠지만 말이지. 그래도 이번에 당신이 없었으면 정말 큰일날 뻔했어!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[6984] = {title = "굴뚝나무 목장조합의 선물!", objective = "오그리마의 겨울 할아버지와 대화해야 합니다.", description = "도둑맞은 장난감 찾는 일을 도와준 것에 대해 우리 굴뚝나무 목장조합을 대신해 진심으로 감사를 전하고 싶어. 뭔가 특별한 선물을 주고 싶군... 바로 겨울 할아버지가 직접 준다니까!\n\n저기 겨울 할아버지에게 가봐. 겨울맞이 축제를 맞아 굴뚝나무 목장조합에서 특별히 마련한 선물을 줄 거야. 굴뚝나무 목장조합에서는 직영 농장에서 금방 거둔 신선함을 식탁까지 전하지! 맛도 좋지만 몸에도 그만이라니까! 참, 정말 고마워!", progress = nil, completion = "안녕하세요, 모험가 양반!\n\n고블린들이 이번 축제 기간에 당신에게 특별한 선물을 주기로 했다고 하더군요. 이렇게 직접 선물을 전하게 되어 아주 기쁘군요. 자, 받아요. 앞으로도 매년 즐거운 겨울맞이 축제가 되기를 빌게요.", rewards = "다음과 같은 것들을 받습니다:\n\n굴뚝나무 목장조합 특별선물"},
[6985] = {title = "깊은무쇠 광산 보급품", objective = "서리늑대 요새에 있는 서리늑대 병참장교에게 깊은무쇠 광산 보급품 10개를 가져가야 합니다.", description = "스톰파이크 드워프들이 깊은무쇠 광산을 보급품 창고로 이용하고 있소. 그곳을 습격해 그 안에 있는 보급품을 가져오도록 하시오. 그렇게 하면 우린 알터랙 계곡에서 스톰파이크 경비대의 활동을 저지할 수 있을 뿐 아니라 필요한 물건들을 얻을 수도 있지!\n\n조심하시오, <name>. 깊은무쇠 광산은 얼라이언스 영토 깊숙한 곳에 있는데다, 그 광산의 지배자는 알터랙 산맥에 쌓인 무수한 눈송이만큼이나 자주 바뀌니까 말이오.", progress = "깊은무쇠 광산에는 들어가 봤소? 녀석들의 보급품을 빼앗아 왔느냔 말이오.", completion = "가져 왔군! 잘했소, &lt;name&gt;! 이왕 다녀오는 김에 서리늑대부족을 위해 드워프 놈들의 피를 눈 위에 뿌려주지 그랬소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7001] = {title = "빈 우리", objective = "알터랙 계곡에서 서리늑대를 찾아야 합니다. 발견한 서리늑대 근처에서 서리늑대 재갈을 사용하십시오. 그러면 서리늑대는 당신을 따라다니기 시작할 것입니다. 서리늑대부족 야수관리인에게 돌아가 서리늑대를 포획한 공로를 인정받으십시오.", description = "알터랙 계곡에서의 전투로 인해 우리 병사들 중 상당수가 희생되었습니다. 새롭게 전의를 북돋워줘야 할 때입니다!\n\n빈 우리를 가득 채울 수만 있다면 기병대가 다시 한번 전장에 나가 싸울 수 있을 겁니다!\n\n이 재갈을 가지고 가서 이 근방 숲에 살고 있는 서리늑대들을 찾아 길들이십시오. 길들인 서리늑대를 데리고 오면 제가 우리에 맡아 두겠습니다.\n\n우리에 서리늑대가 충분히 모이면 우리 기병대가 다시 한 번 출전하여 최전선에서 정찰을 돌고 있을 병력과 합류할 수 있을 겁니다.", progress = "당신 도움이 없다면 서리늑대부족 기병대는 타고 나갈 늑대가 없어 참전하지 못하는 불상사가 발생할 수도 있어요. 당신은 정말 큰일을 해주고 있는 것입니다!", completion = "산양 통가죽을 모으는 자들도 당신처럼 결의가 있다면 좋겠어요.\n\n이런 속도로만 서리늑대를 잡아들인다면 빈 우리를 삽시간에 가득 채울 수 있을 거예요!", rewards = nil},
[7002] = {title = "산양 통가죽 고삐", objective = "일부 병사들이 바쁘게 움직이며 야수 관리인에게 늑대를 잡아다 주는 동안 다른 병사들은 단순한 것이지만 기병들에게 꼭 필요한 물건을 공급해 주어야 하지. 바로 고삐를 말일세.\n\n이 지역 토종 산양을 잡아야 하네. 스톰파이크 기병대가 타고 다니는 것과 똑같은 산양으로...\n\n산양을 처치하고 그 통가죽을 가지고 오게나. 통가죽이 충분히 모이면 기병들이 사용할 고삐를 만들 것이라네. 서리늑대부족 기병대가 다시 한번 전장에 출격할 수 있도록!", description = nil, progress = "일부 병사들이 바쁘게 움직이며 야수 관리인에게 늑대를 잡아다 주는 동안 다른 병사들은 단순한 것이지만 기병들에게 꼭 필요한 물건을 공급해 주어야 하지. 바로 고삐를 말일세.\n\n이 지역 토종 산양을 잡아야 하네. 스톰파이크 기병대가 타고 다니는 것과 똑같은 산양으로...\n\n산양을 처치하고 그 통가죽을 가지고 오게나. 통가죽이 충분히 모이면 기병들이 사용할 고삐를 만들 것이라네. 서리늑대부족 기병대가 다시 한번 전장에 출격할 수 있도록!", completion = "수고했네. 통가죽이 충분히 모이면 알려주도록 하겠네.\n\n가서 통가죽을 더 모아서 가져오게나!", rewards = nil},
[7003] = {title = "변형된 거인", objective = "페랄라스에서 눈에 띄는 아무 거인에게나 조브린의 형상축소기를 사용해 좀 더 다루기 쉬운 형태로 변환하십시오. 페랄라스의 잊혀진 해안 부두에 있는 조브린 팬대즐에게 변형된 거인들에게서 얻을 수 있는 축소화 잔류물 15개를 가져가야 합니다.", description = "이렇게 밖에서 지내려면 저 거인들에게 손을 좀 써야겠어요! 녀석들은 절대 장사에 도움이 안 되니까요. 안 그래요?\n\n저는 더욱 뛰어난 고블린 과학 기술을 이용해서 노움 난쟁이 광선을 변형하는 작업을 하고 있답니다! 전 죽는 것과 같은 불편은 피하고 싶으니까 당신이 가져가서 페랄라스에 사는 아무 거인들한테나 시험 삼아 이걸 써 봤으면 좋겠군요. 거인이 작아진 후에 축소화 잔류물을 채취할 수 있을 테니 그걸 좀 가져다주세요!", progress = "축소화 잔류물은 기계공학에 있어 아주 귀중한 물건입니다! 뭐, 귀중하다는 건 그러니까, 축소기가 사용 중 폭발한다든가 하는 실망스러운 일이 발생하는 것을 막아 주기 때문이죠.\n\n아, 그게... 당신한테 준 것 말고 다른 축소기 얘깁니다, 정말이라니까요!", completion = "아주 잘하셨습니다! 잔류물을 가져왔을 뿐 아니라 사지도 아주 멀쩡하시군요! 뭐, 그게, 그러니까 형상축소기를 사용하는 게 위험한 일이었다든가 그런 건 아니지만요.\n\n제 대신 수고해 주셔서 고맙습니다. 정말로 당신은 모든 고블린들의 친구예요. 감사의 표시로 드리는 거니까 이걸 받아 주십시오!", rewards = "다음과 같은 것들을 받습니다:\n\n조브린의 슈퍼절단기"},
[7021] = {title = "겨울 할아버지, 우리 마을에 오셨네!", objective = "오그리마에 있는 굴뚝나무 목장조합상인 근처에 있는 겨울 할아버지를 만나 대화해야 합니다.", description = "즐거운 겨울맞이가 되길 바라오, 친구들! 지금 오그리마에 와 계신 겨울 할아버지에게 인사하는 것도 잊지 말라고! 올 한해 동안 착하게 살았다면 겨울맞이 축제 날 아주 맛있는 음식을 선물로 받게 될 거야. 올해엔 뭘 받고 싶은지 겨울 할아버지에게 꼭 이야기 하는 것도 잊지말고 말이야!\n\n그리고 올 한해 동안 착하게 지낸 사람들에게 줄 음식도 가득 준비해야겠지? 우리 가게에 농장에서 식탁 위 접시까지 신선하게 준비할 수 있는 아주 다양한 품목들이 있지. 굴뚝나무 목장조합의 영양 만점 요리를 맛보라고!", progress = nil, completion = "안녕?! 꼬마 친구, 난 겨울 할아버지라고 해요. 어이쿠, 굴뚝나무 목장조합 친구들도 여러분들에게 인사를 전하고 싶다고 하는군요. 이 친구들은 직영 농장에서 직접 거둔 재료로 만든 신선도 100%의 건강식을 아제로스 전역에 제공하고 있지요. 맛있는 음식과 함께 즐거운 겨울맞이 축제 맞으세요! 호호호!\n\n올 한해 착한 일을 많이 했다면 굴뚝나무 목장조합에서 푸짐한 선물을 받을 수 있을 거예요. 겨울맞이엔 누구나 베푼 만큼 거두는 법이지요... 만세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7022] = {title = "겨울 할아버지, 우리 마을에 오셨네!", objective = "아이언포지의 굴뚝나무 목장조합상인 근처에 있는 겨울 할아버지를 만나 대화해야 합니다.", description = "즐거운 겨울맞이 축제가 되길! 겨울 할아버지에게 꼭 인사하는 것 잊지 말고! 올해 착한 일을 많이 했으면 겨울맞이 축제에 선물을 받게 될 거야. 겨울 할아버지에게 올해 꼭 갖고 싶은 게 뭔지 꼭 얘기하라고!\n\n참, 올 한해 고마웠던 친구들에게 한 턱 내는 건 어때? 마침 내게 선물용으로 아주 괜찮은 물건이 있는데 말이야. 굴뚝나무 목장조합에서 직접 재배한 신선한 음식을 맛보게! 맛도 그만이지만 몸에도 아주 좋지!", progress = nil, completion = "안녕?! 꼬마 친구, 난 겨울 할아버지라고 해요. 어이쿠, 굴뚝나무 목장조합 친구들도 여러분들에게 인사를 전하고 싶다고 하는군요. 이 친구들은 직영 농장에서 직접 거둔 재료로 만든 신선도 100%의 건강식을 아제로스 전역에 제공하고 있지요. 맛있는 음식과 함께 즐거운 겨울맞이 축제 맞으세요! 호호호!\n\n올 한해 착한 일을 많이 했다면 굴뚝나무 목장조합에서 푸짐한 선물을 받을 수 있을 거예요. 겨울맞이엔 누구나 베푼 만큼 거두는 법이지요... 만세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7023] = {title = "겨울 할아버지, 우리 마을에 오셨네!", objective = "아이언포지 굴뚝나무 목장조합상인 근처에 있는 겨울 할아버지를 만나 대화해야 합니다.", description = "즐거운 겨울맞이가 되라고! 지금 아이언포지에 와 계신 겨울 할아버지에게 인사하는 것도 잊지 말아야해! 올 한해 동안 착하게 살았다면 겨울맞이 축제 날 아주 맛있는 음식을 선물로 받게 될 거야. 올해엔 뭘 받고 싶은지 겨울 할아버지에게 꼭 이야기하도록 하라고!\n\n그리고 올 한해 동안 착하게 지낸 사람들에게 줄 음식도 가득 준비해야겠지? 우리 가게에 아주 다양한 품목들이 있지. 농장에서 식탁 위 접시까지 신선하게! 굴뚝나무 목장조합의 영양 만점 요리를 맛보도록 해!", progress = nil, completion = "안녕?! 꼬마 친구, 난 겨울 할아버지라고 해요. 어이쿠, 굴뚝나무 목장조합 친구들도 여러분들에게 인사를 전하고 싶다고 하는군요. 이 친구들은 직영 농장에서 직접 거둔 재료로 만든 신선도 100%의 건강식을 아제로스 전역에 제공하고 있지요. 맛있는 음식과 함께 즐거운 겨울맞이 축제 맞으세요! 호호호!\n\n올 한해 착한 일을 많이 했다면 굴뚝나무 목장조합에서 푸짐한 선물을 받을 수 있을 거예요. 겨울맞이엔 누구나 베푼 만큼 거두는 법이지요... 만세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7024] = {title = "겨울 할아버지, 우리 마을에 오셨네!", objective = "오그리마에 있는 굴뚝나무 목장조합상인 근처에 있는 겨울 할아버지를 만나 대화해야 합니다.", description = "즐거운 겨울맞이가 되길! 지금 오그리마에 와 계신 겨울 할아버지에게 인사하는 것도 잊지 말라구! 올 한해 동안 착하게 살았다면 겨울맞이 축제 날 아주 맛있는 음식을 선물로 받게 될 거라고. 올해엔 뭘 받고 싶은지 겨울 할아버지에게 꼭 이야기하는 거 잊지마!\n\n그리고 올 한해 동안 착하게 지낸 사람들에게 줄 음식도 가득 준비하셔야겠지? 우리 가게에 아주 다양한 품목들이 있지. 농장에서 식탁 위 접시까지 신선하게. 굴뚝나무 목장조합의 영양 만점 요리를 맛보라고!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7025] = {title = "겨울 할아버지 대접하기", objective = "아이언포지에 있는 겨울 할아버지에게 생강 과자빵 5개와 시원한 우유 한 잔을 갖다 주어야 합니다.", description = "<class> 젊은이, 이 겨울 할아버지가 조그만 부탁이 하나 있는데 들어줄래요?\n\n객관적으로 봐도 여기 하루종일 서 있는 게 그리 유쾌한 일은 아니겠지요? 달콤한 걸 좀 먹으면 기운이 날 것 같은데... 생강 과자빵이랑 시원한 우유만 있어도 참 좋겠어요. 이 할아버지랑 친해지고 싶죠? 그렇다면 좀 갖다 줄래요?", progress = "간식 얘기를 꺼냈더니 더욱 허기가 지는군요. 흐음... 생강 과자빵에 시원한 우유라...", completion = "당신은 정말 멋진 친구로군요. 즐거운 겨울맞이 축제 보내기를 다시 한번 빌겠어요.\n\n자, 이걸 받으세요. 당신의 수고에 대해 고마움을 전하기 위한 제 작은 성의입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n굴뚝나무 목장조합 선물꾸러미"},
[7026] = {title = "산양 통가죽 고삐", objective = "스톰파이크 기병대가 안장도 없이 전투에 나설 수는 없지! 탈것에 쓸 고삐가 있어야 하오. 우리가 야만인은 아니지 않겠소.\n\n기지 근처에 돌아다니는 산양을 잡아 그 가죽으로 고삐를 만든다면야 일은 간단하겠지만 우리가 탈것으로 부리는 산양을 죽인다는 건 멍청한 짓이 아닐 수 없소.\n\n그러니 당신이 적의 기지를 쳐서 놈들이 탈것으로 쓰는 서리늑대를 잡아 그 통가죽을 가지고 오시오. 그 통가죽을 가지고 오면 우리 기병대가 쓸 고삐를 만들 수 있을 거요. 자, 어서 가시오!", description = nil, progress = "스톰파이크 기병대가 안장도 없이 전투에 나설 수는 없지! 탈것에 쓸 고삐가 있어야 하오. 우리가 야만인은 아니지 않겠소.\n\n기지 근처에 돌아다니는 산양을 잡아 그 가죽으로 고삐를 만든다면야 일은 간단하겠지만 우리가 탈것으로 부리는 산양을 죽인다는 건 멍청한 짓이 아닐 수 없소.\n\n그러니 당신이 적의 기지를 쳐서 놈들이 탈것으로 쓰는 서리늑대를 잡아 그 통가죽을 가지고 오시오. 그 통가죽을 가지고 오면 우리 기병대가 쓸 고삐를 만들 수 있을 거요. 자, 어서 가시오!", completion = "수고했소, 병사. 통가죽이 충분히 모이면 알려주도록 하겠소.\n\n통가죽을 더 가져오시오!", rewards = nil},
[7027] = {title = "빈 우리", objective = "알터랙 계곡에 돌아다니는 알터랙 산양을 찾아야 합니다. 알터랙 산양을 찾으면 그 근처에서 스톰파이크 조련용 목줄을 사용해 산양을 길들이십시오. 그러면 야수 관리인에게 돌아갈 때 따라올 것입니다. 알터랙 산양 포획을 인정받기 위해서는 야수 관리인과 대화해야 합니다.", description = "여기 마구간을 좀 보세요! 텅텅 비었어요! 스톰파이크 기병대는 탈 산양이 없어 기능을 완전히 상실한 상태입니다.\n\n우리를 도와주셔야 합니다, 얼라이언스의 병사여. 이 조련용 목줄을 가지고 계곡으로 들어가 그 일대를 돌아다니는 알터랙 산양을 찾으세요. 산양을 찾거든 이 목줄을 사용해 잡아서 내게 데리고 오세요. 그러면 내가 마구간에 넣어두겠습니다.\n\n산양이 충분히 모이면 산양기병대 지휘관님께 소식을 정식 통지할 겁니다. 당신이 도와준다면 우리 기병대는 다시 살아날 것입니다!", progress = "산양을 모아주지 않는다면 스톰파이크 기병대원들은 전투에 타고 나갈 것이 없을 거예요. 당신은 우리에게 큰 공헌을 해주고 있는 겁니다!", completion = "마구간이 금방 가득 차겠네요. 계속 수고해 주세요!", rewards = nil},
[7028] = {title = "뒤틀린 악마", objective = "트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다.", description = "테라모크의 수정 동굴은 서쪽으로 펼쳐져 마라우돈의 깊은 곳까지 이어진다오. 그곳은 많은 역사를 간직한 고대의 장소이며 난 그 역사를 차지하고 싶소, <class>. 거대한 문의 뒤에 고대 신의 유물이 감추어져 있소이다.\n\n마라우돈에서 발견된 뒤틀린 악마와 싸워 준다면 보답은 충분히 하도록하지. 트라드릭 수정 조각상을 찾아서 내게 가져오시오.\n\n그러면 나도 연구를 시작할 수 있겠지... 그 대단한 힘들은 너무 오랫동안 잠들어 있었소...", progress = "질문은 하지 마시오!\n\n당신은 이미 내 부탁을 받아들였소.", completion = "하하하! 돌아올 줄 알았지.\n\n&lt;중얼거리는 윌로우&gt;\n\n상대하기 쉬운 놈이지...\n\n적당한 가격을 치르는 게 맞겠지? 헤헤헤...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n총명의 로브가지뿌리 투구가혹의 사슬 갑옷기암석 어깨갑옷\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7029] = {title = "바일텅의 타락", objective = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.\n\n오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다.\n\n녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가야 합니다.", description = "바일텅으로 알려진 사티로스는 내부의 식물들의 성장을 방해하는 수법으로 마라우돈 동굴을 오염시키고 있네.\n\n이 약병을 받게. 동굴 안으로 가서 오염된 주황색 웅덩이의 물로 약병을 채우게. 약병 안에 칠한 것이 독을 제압해 치료제로 바꾸어 줄 것일세.\n\n동굴 안으로 들어간 다음 바일줄기 덩굴나무를 찾아서 정화된 액체를 그 위에 부어야 하네. 그러면 오염된 식물이 깨끗하게 치료될 것이네. 하지만 식물들은 여전히 바일텅의 지배 하에 있다는 걸 잊지 말게나. 바일텅이 그 식물을 이용해 자네를 공격할지도 몰라...", progress = "자네가 식물을 치료하면 다시 자라기 시작할 것이네. 우린 할 수 있는 일은 다 해봐야 하네...", completion = "이걸 돌려줘서 고맙네. 남은 걸로 연구를 계속할 수 있겠군.\n\n자네가 바일텅이 마라우돈에 퍼뜨린 오염을 치료하는 데 많은 도움을 주었지만 여전히 할 일이 많네. 이걸 받게나. 내 감사의 표시라네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n나무씨앗 고리산쑥 벨트가지갈퀴 건틀릿\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7041] = {title = "바일텅의 타락", objective = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.\n\n오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다.\n\n녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 나이젤의 야영지에 있는 탈렌드리아에게 돌아가야 합니다.", description = "바일텅으로 알려진 사티로스는 내부의 식물들의 성장을 방해하는 수법으로 마라우돈 동굴을 오염시키고 있습니다.\n\n이 약병을 받으세요. 동굴 안으로 가서 오염된 주황색 웅덩이에서 약병을 채우세요. 약병 안에 칠한 것이 독을 제압해 치료제로 바꾸어 줄 겁니다.\n\n동굴 안으로 들어간 다음 바일줄기 덩굴나무를 찾아서 정화된 액체를 그 위에 부으면 오염된 식물이 깨끗하게 치료될 겁니다. 하지만 식물들은 여전히 바일텅의 지배 하에 있다는 걸 알아 두세요. 바일텅이 그 식물을 이용해 그대를 공격할지도 모릅니다...", progress = "그대가 식물을 치료하면 다시 자라기 시작할 것입니다. 할 수 있는 일은 모두 해봐야만 합니다...", completion = "이걸 돌려주셔서 감사합니다. 남은 걸로 연구를 계속할 수 있겠군요.\n\n그대가 바일텅이 마라우돈에 퍼트린 오염을 치료하는 데 많은 도움을 주셨지만 여전히 할 일이 많습니다. 이걸 받으세요. 저의 감사의 마음에 대한 표시입니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n나무씨앗 고리산쑥 벨트가지갈퀴 건틀릿\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7042] = {title = "도둑맞은 장난감", objective = "알터랙 산맥의 어딘가 눈 덮인 지역에서 실종된 굴뚝나무 목장조합의 수색 요원을 찾아야 합니다.", description = "내 말 좀 들어보라고. 흥겨운 명절에 분위기 깨고 싶지는 않지만 굴뚝나무 목장조합에서는 뜻하지 않은 사고로 모험가의 도움을 필요로 하고 있네.\n\n축제에 없어서는 안 될 귀중한 장난감이 담긴 화물이 사라졌다고. 그걸 찾으러 보낸 굴뚝나무 목장조합의 요원도 실종된 상태고! 화물의 흔적을 마지막으로 알터랙 산맥 부근에서 보았다는 제보를 받고 우리 요원도 그리로 갔네.\n\n제발 부탁이야. 화물을 찾으러 간 우리 요원이 무사한지 꼭 좀 확인해 줘!", progress = nil, completion = "날... 날 찾으러... 왔구나! 정말이지 고마워서 코끝까지 찡해지는군!\n\n진짜로 난 그냥 눈...사람이 아니야. 내 이름은 삭스야. 오... 오... 오그리마의 굴뚝나무 목장조합에서 일했지... 나... 나는 도둑맞은 화물을 찾는 임무를 맡아 여기로 왔는데 난생 처... 처음 보는 괴물한테 당했지 뭐야!\n\n추... 추워... 너...무... 호오...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7043] = {title = "고약한 녀석...", objective = "도둑맞은 장난감을 찾아 아이언포지에 있는 훌몰트 징글포켓에게 돌려주어야 합니다. 도둑맞은 장난감은 알터랙 산맥의 눈 덮인 지역 어딘가에서 목격된 썩은내 그린치가 마지막으로 가지고 있었던 것 같습니다.", description = "\"썩은내 그린치\"라는 녀... 녀석이 우...운송 중이던 우... 우리 음식과 장난감을 후... 훔쳐 갔어요. 하... 하지만 조... 심하세요! 저를 이 누... 눈 덩어리로 마... 만들어 버린 녀석이니까!\n\n그 녀석을 사... 상대하려면 도움이 피... 필요할 겁니다. 서... 설인들이 있는 곳에서 활개치며 도... 돌아다니는 걸 본 적이 있으니 부... 분명 여... 여기 어딘가에 있을 거예요! 그 음식과 장난감을 찾아 아... 아이언포지에 있는 굴뚝나무 목장조합에 도... 돌려주고 절 해... 해동시켜 달라고 전해... 주세요.", progress = "그걸 되찾아 쌓아 두지 못하면 겨울맞이 축제를 망치게 될 거야! 그라추마저도 올 한해 동안 착한 일을 한 모든 아이들에게 맛있는 고기 파이를 나눠 주지 못하게 된단 말이라고...", completion = "찾았군! 당신이 굴뚝나무 목장조합의 겨울맞이 축제를 구했소!\n\n불쌍한 삭스 녀석... 꼭 사람들을 보내 그를 해동시킬 방법을 알아보도록 하겠소. 축제 당일까지는 돌아올 수 있으면 좋으련만. 근무하지 못한 시간을 보충하긴 해야겠지만 말이오. 그래도 이번에 당신이 없었으면 정말 큰일날 뻔했소이다!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7044] = {title = "마라우돈의 전설", objective = "셀레브라스의 홀 조각인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 찾아야 합니다.\n\n셀레브라스와 대화를 나눌 방법을 찾아야 합니다.", description = "바일텅이라 불리는 암흑의 사티로스는 이 뒤틀린 동굴 내부의 생물들의 마음을 타락시켜 악을 퍼뜨리고 있습니다. 그는 아직도 보라색 수정 건너편에 살고 있답니다.\n\n또한 그는 주황색 수정 건너에 살고 있는 녹시온이라고 부르는 오염된 생명을 창조했습니다. 그들이 힘을 합쳐서 제 형제의 홀을 훔쳐갔답니다. 제 형제 셀레브라스는 저주에 걸려 동굴 안에서 배회하고 있어요.\n\n제발 도와주세요! 홀 조각을 찾고 어떻게 해서든 제 형제에게 말을 전해주십시오.", progress = "결코 끝나지 않을 것 같은 악몽에서 깨어났군...", completion = "그대가 내 홀 조각 2개를 찾아 주었군. 언젠가 마라우돈에서 바일텅의 오염을 완전히 뿌리뽑았으면 좋겠네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7045] = {title = "굴뚝나무 목장조합의 선물!", objective = "아이언포지의 겨울 할아버지와 대화를 해야 합니다.", description = "도둑맞은 장난감 찾는 일을 도와준 것에 대해 우리 굴뚝나무 목장조합을 대신해 진심으로 감사를 전하고 싶군. 뭔가 특별한 선물을 주고 싶은데... 겨울 할아버지가 직접 줄 거야!\n\n겨울 할아버지에게 가보게. 겨울맞이 축제를 맞아 굴뚝나무 목장조합에서 특별히 마련한 선물을 줄 테니까. 굴뚝나무 목장조합에서는 직영 농장에서 금방 거둔 신선함을 식탁까지 전하지! 맛도 좋지만 몸에도 그만이라니까! 참, 정말 고맙네!", progress = nil, completion = "안녕하세요, 모험가 양반!\n\n고블린들이 이번 축제 기간에 당신에게 특별한 선물을 주기로 했다고 하더군요. 이렇게 직접 선물을 전하게 되어 아주 기쁘군요. 자, 받아요. 앞으로도 매년 즐거운 겨울맞이 축제가 되기를 빌게요.", rewards = "다음과 같은 것들을 받습니다:\n\n굴뚝나무 목장조합 특별선물"},
[7046] = {title = "셀레브라스의 홀", objective = "회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다.\n\n의식을 마친 후 그와 대화하십시오.", description = "내 홀은 나에게 희망을 주는 원동력이었지. 홀이 있었기에 이 동굴들을 마음대로 돌아다닐 수 있었다네. 난 내 숙부의 영혼에 안식을 주고 싶었지... 이제 그대가 할 일을 알려 주겠네.\n\n2개의 홀 조각을 다시 하나로 합치려면 그대의 도움을 받아 의식을 치러야 한다네. 마법봉과 다이아몬드를 다시 하나로 합치는 데 필요한 힘을 모으는 동안 내 지시를 잘 따라주길 바라네.\n\n우리가 힘을 합치면 다시 셀레브라스의 홀을 만들 수 있을 걸세!", progress = nil, completion = "이걸 받아 주게. 그 힘은 좋은 일에 쓰라고 주는 걸세. 희망을 가지고 동굴을 계속 탐험하도록 하면 내 숙부의 유골도 찾을 수 있을 걸세. 이제 더 큰 위험이 그대를 기다리고 있을 거야.\n\n도움이 필요하면 내게 다시 말하게나.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n셀레브라스의 홀"},
[7061] = {title = "겨울맞이 축제", objective = "겨울맞이 축제를 읽고 축제의 의미에 대해 좀 더 알아보십시오. 책을 다 읽은 후 썬더 블러프에 있는 케른 블러드후프에게 가져가야 합니다.", description = "자, 겨울맞이 축제에 대해 좀 더 배우고 싶다면 이 책을 읽어보시길 권해 드립니다. 다들 누군가에게 전설에 관해 듣는 정도로 충분하다고 생각하지만, 전 개인적으로 그 근본적인 유래에 관한 온갖 정보를 모아서 집대성할 생각이에요.\n\n이 책을 다 읽으면 썬더 블러프에 있는 케른 블러드후프님께 가져다 주세요. 아마 다른 타우렌들처럼 그 분께서도 전설에 대해 듣고 싶어할 테니까요.", progress = "멀고어의 이 누추한 마을, 썬더 블러프에 온 것을 진심으로 환영하네. 나는 우리의 왕국과 백성들 그리고 축제의 전설에 관심을 가지고 있는 이들을 항상 어여삐 여기지... 자네가 날 찾아온 이유가 바로 이 책인가?", completion = "겨울맞이를 둘러싼 전설과 지식은 시간이 지나면서 대중들 사이에서 잊혀져 갔네. 고블린들이 축제를 부활시키려 애쓴 것은 사사로운 이익을 챙기기 위해서라는 사실은 나도 알지만... 어쨌든 그런 축제를 통해서라도 백성들이 조금이나마 전통을 기억할 수 있다면 그리 나쁘진 않지.\n\n그나저나 선물 따위에 현혹되지 않고 우리 타우렌의 과거에 대해 배우려는 자네의 노력은 참 대단하군. &lt;class&gt;|1이여;여;, 그 지혜에 경의를 표하네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7062] = {title = "축제의 유래", objective = "아이언포지에 있는 탐험가 조합의 역사학자 카르닉과 겨울맞이 축제에 대한 대화를 나누어야 합니다.", description = "선물이나 주고받고 흥청거리다니... 바보들!\n\n경박한 고블린들이 겨울맞이 축제의 진정한 의미를 퇴색시키고 있네. 겨울맞이는 곧 부활과 회복을 뜻하지. 대지는 겨울 할아버지께서 내리신 포근한 눈을 덮고 깊고 조용한 잠을 자는 거야. 우스꽝스러운 빨간 옷을 입은 저 멍청이가 진짜 겨울 할아버지일 리가 없잖아!\n\n축제의 진정한 의미를 알고 싶거든 탐험가 연맹의 역사학자 카르닉을 찾아가도록! 선물에 정신 팔린 놈들이 천지인 이 시기에 역사가 주는 진정한 교훈에 관심을 가진 자네 같은 이도 있다는 걸 알면 분명 놀랄 거야.", progress = nil, completion = "겨울맞이 축제라고 했나? 과거 겨울맞이 축제는 우리 드워프들에게 상당한 의미를 지녔었지. 요즘은 어떤 약삭빠른 놈들이 겨울 할아버지의 전설을 이용해 사탕과 선물을 팔아먹고 있더군. 정말 안타까운 일이 아닐 수 없어.\n\n이렇게 변질된 현실에 골리가 냉소를 보내는 것도 당연해. 골리와 뜻을 같이하는 몇몇 드워프들은 전투의 깃발과 같은 전통을 지키며 살고 있다네. 흥겨운 축제 분위기를 조금쯤 즐기는 것도 좋겠지만, 그 진정한 유래를 기억하는 일이 훨씬 중요하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7063] = {title = "겨울맞이 축제", objective = "겨울맞이 축제를 읽고 그 유래와 의미에 대해 좀 더 알아보십시오. 책을 다 읽은 후 아이언포지에 있는 국왕 마그니 브론즈비어드에게 가져가야 합니다.", description = "자, 겨울맞이 축제의 전설과 유래에 대해 좀 더 알고 싶다면 이 책을 읽어보길 바라네. 다들 누군가에게 전해 듣는 정도로 충분하다고 생각하지만, 난 개인적으로 그 근본에 관한 온갖 정보를 모아서 집대성할 생각일세.\n\n이 책을 다 읽으면 국왕 마그니 브론즈비어드님께 가져다 드리게. 아마 다른 드워프 백성들처럼 그 분께서도 축제의 유래에 대해 알고 싶어하실 테니까.", progress = "아이언포지 왕국에 온 것을 진심으로 환영하네. 나는 우리 왕국과 백성들 그리고 전설에 관심을 가지고 있는 이들을 항상 어여삐 여기지... 그대가 날 찾아온 이유가 바로 이 책인가?", completion = "겨울맞이 축제를 둘러싼 전설과 지식은 시간이 지나면서 대중들 사이에서 잊혀져 갔네. 고블린들이 축제를 부활시키려 애쓴 것은 사사로운 이익을 챙기기 위해서라는 사실은 나도 알지만... 어쨌든 그런 축제를 통해서라도 백성들이 조금이나마 전통을 기억할 수 있다면 나쁘다곤 할 수 없지.\n\n그나저나 선물 따위에 현혹되지 않고 드워프의 역사에 대해 배우려는 그대의 노력은 참 가상하군. &lt;class&gt;|1이여;여;, 자네의 지혜에 짐이 경의를 표하노라.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7064] = {title = "대지와 씨앗의 오염", objective = "공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다.", description = "마라우돈 깊숙한 곳에 혼돈과 악의 생물들이 살고 있죠. 테라드라스 공주는 고대 신과 관련된 대지의 힘의 근원이라고 할 수 있습니다. 수년 전 그녀와 세나리우스의 첫째 아들 재타르의 만남이 시작되었답니다. 시간이 흘러 둘 사이에서 자식이 생겼으니 칼림도어의 백성들은 이들을 켄타우로스라고 합니다. 감사할 줄 아는 이 켄타우로스는 재타르를 살해하고 지금은 재타르의 유골을 가지고 있습니다. 내가 원하는 것은 테라드라스를 없앨 만큼 강력한 무언가를 찾아서 재타르의 유골이 돌발톱으로 돌아가기 전에 되찾는 것입니다.", progress = nil, completion = "정말 반가운 소식이군요! 고마워요!\n\n마란디스님께 재타르의 유골에 대해 여쭤봐야 겠군요. 정말 어려운 일을 해주셨습니다.\n\n계획이 성공한다면 도와주신 분에게 보상을 해도 된다는 허락을 받았습니다. 자, 우리 백성들에게 징표로 받은 이 물건들 중에서 한 가지를 고르도록 하세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n도리깨 검회생의 마법막대푸른 수호자의 활\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7065] = {title = "대지와 씨앗의 오염", objective = "공주 테라드라스를 해치우고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스를 찾아가야 합니다.", description = "마라우돈 깊숙한 곳에 혼돈과 악의 생물들이 살고 있네. 공주 테라드라스 공주는 고대 신과 관련된 대지의 힘의 근원이라고 할 수 있지. 수년 전 세나리우스의 첫째 아들 재타르가 그녀를 발견했고, 그 둘 사이에서 자식이 생겼으니 바로 켄타우로스라고 한다네. 배은망덕한 이 켄타우로스는 재타르를 살해하고 지금은 테라드라스가 재타르의 유골을 가지고 있네. 내가 원하는 것은 테라드라스를 없앨 만큼 강력한 무언가를 찾아서 재타르의 유골이 돌발톱으로 돌아가기 전에 되찾는 것이라네.", progress = nil, completion = "정말 반가운 소식이군! 고맙네!\n\n자네가 재타르의 유물을 가지고 올 수 있을까 걱정도 했었네. 세나리우스의 탄생이 무슨 의미를 가지고 있는지 물어보고 싶었네. 아마도 이제 세나리우스는 파괴하려고 할 것이고 첫 번째 대상을 통해 교훈을 줄 것이네. 그러기를 바래야지.\n\n계획이 성공해서 이 물건들을 얻게 되면 내 우리를 도와준 것에 대한 보답으로 주려고 했네. 감사의 표시이니 하나 고르게나.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n도리깨 검회생의 마법막대푸른 수호자의 활\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7066] = {title = "생명의 씨앗", objective = "달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다.", description = "불운하게 태어난 나의 아들과 딸 켄타우로스들에게는 아버지가 필요하단다.\n\n주위를 둘러보아라. 여기는 평화로운 곳이며 내 아버지 세나리우스께서 가르침을 전하신 곳이니라. 이곳은 나로부터 생겨난 곳이니라! 그들이 나에게 나쁜 짓을 저지른다고 해도 그들로부터 이곳을 빼앗을 수는 없다.\n\n하지만 내 형제들의 마음을 편하게 하기 위해 그대에게 부탁할 일이 있으니 이걸 받아라... 내 유골을 영양분 삼아 생긴 첫 번째 씨앗이니 내 영혼이 아직 여기에 살아 있다고 그에게 전해주도록 해라. 난 그가 분명 무슨 뜻인지 이해할 거라고 믿는다.", progress = "너에게서 요즘 설쳐대는 다른 모험가들처럼 타락한 냄새가 나는군. 약간 다르기는 하지만... 나에게 할 말이 있어서 찾아온 것인가? 네 몸 주변에서 친숙한 기운이 느껴지는군. 정확하게 어떤 기운인지 기억이 나지는 않지만 말이야.\n\n자, 이제 말해봐라. 나를 찾아온 이유가 뭐지?", completion = "내 형제가 결국 그곳을 발견했다는 건가? 내 삶에서 정말 영광스러운 날이로군. 건방지고 화만 내던 내 형제가 우리에게서 완전히 떠났다고 생각했는데. 이... 이 징표를 보면 그가 죽은 것이 아니고 다시 태어나는 것이군. 그의 원래 임무였던것과 마찬가지로 자연에서 자신의 위치를 찾았군.\n\n고맙다. 네가 이걸 갖다 준 덕분에 모두 잃었다고 생각했던 희망을 약간이나마 다시 찾을 수 있게 되었구나. 전쟁으로 폐허가 된 이 땅의 주민들에게 이 씨앗은 중요한 역할을 할 것이라 확신한다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7067] = {title = "추방자의 지시서", objective = "추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다.", description = "비록 이교도로 몰려 추방 당했지만 내 신념은 확고하며 앞으로도 내 신념을 따를 것이오. 그러나 내 운명을 완성하려면 켄타우로스 종족이 아닌 외부인의 도움이 필요하오.\n\n외부인인 네가 할 일은 마라우돈의 성스러운 묘지에 들어가는 것이오. 성스러운 묘지는 나의 백성들이 지키고 있으며 신앙심이 깊은 이들만 들어갈 수 있소.\n\n나를 도와줄 생각이면 고개를 끄덕이시오. 나의 지시 사항이 적힌 양피지를 줄테니 잘 읽고 내 말을 명심하도록 하시오.", progress = "결정했소? 날 도와줄 것이오? 나를 도와 성스러운 땅에 발을 딛고 위대한 켄타우로스 일족을 만드는 일을 도와주겠소?", completion = "그래! 바로 이거야! 이제 일족 통일이라는 위대한 일을 시작할 수 있겠군. 고맙소.\n\n이것은 내 고마움의 표시요. 다음에 만날 때는 나의 신분이 달라져 있을지도 모르겠군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n선택받은 자의 징표"},
[7068] = {title = "음영석 조각", objective = "마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다.", description = "켄타우로스의 성스러운 곳, 마라우돈의 성스러운 곳에서 강력한 마력이 발견됐습니다. 잊혀진 땅의 종족 켄타우로스가 목숨을 걸고 지키고 있지만 우리가 필요한 것들을 가져오는 걸 막지는 못합니다.\n\n당신이 할 일은 마라우돈으로 가서 음영석으로 이루어진 바위 생명체를 찾는 것입니다. 그 보라색 수정을 가져오면 보상을 하도록 하겠습니다.\n\n아주 위험한 곳이니 동료와 같이 가는 게 좋을 겁니다.", progress = "아직 수정을 발견하지 못했습니까? 마력의 의식, 강력한 마력은 모든 비전 마법에 대단히 큰 도움이 될 것입니다.", completion = "아, 완벽하군요. 이 장신구들 중에 하나를 고르십시오. 좋은 여행 되시기를... 저는 연구할 게 많아서...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n열정의 음영석 목걸이마력의 음영석 목걸이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7070] = {title = "음영석 조각", objective = "마라우돈에서 음영석 조각 10개를 모아서 먼지진흙 습지대의 해안에 위치한 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다.", description = "최근 난 다양한 수정과 수정의 신비한 성질에 대해 실험을 하고 있습니다. 프라우드무어님께서 내게 마라우돈을 찾기 위해 잊혀진 땅으로 가는 여행자들에게 부탁을 할 수 있는 권한을 주셨습니다. 폐허가 된 신전들 사이에 보라색 수정으로 만들어진 엄청난 정령이 있습니다. 난 이 수정을 음영석이라고 이름 지었습니다.\n\n그곳으로 가서 수정을 찾아주신다면 정말 고맙겠습니다. 원한다면 수정으로 장신구를 만들어 드릴 수도 있습니다.", progress = "아직 임무를 완수하지 못했습니까? 대단히 위험한 일이지만 성공한다면 정말 가치 있는 일을 하시는 겁니다.", completion = "완벽하군요. 사실 다른 모험가들도 그곳으로 보내서 이걸 얻을 수 있었습니다... 어려운 일을 해주신 보답으로 이 중에 하나를 드리도록 하지요. 연구할 견본을 가져오신 점 다시 한 번 고맙게 생각합니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n열정의 음영석 목걸이마력의 음영석 목걸이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7081] = {title = "알터랙 계곡의 무덤", objective = "호드의 무덤을 공격한 다음 알터랙 산맥에 있는 하사관 두르겐 스톰파이크에게 돌아가야 합니다.", description = "알터랙 계곡의 무덤은 아주 중요한 곳이네. 호드와 얼라이언스 양 진영이 이 성스러운 곳을 점령하려고 치열하게 싸우는 것도 그 때문이지. 전투에 합류할 준비는 됐나? 자네가 적의 무덤을 공격해 주었으면 하네.\n\n중앙에 호드의 깃발이 꽂혀 있는 무덤을 찾아서 그걸 뽑아버리게! 완료하면 자네의 임무는 끝나게 될 것이야... 그러고 나서 몇 분 동안 무덤을 점령하고 있게 되면, 우리 군이 곧 도착하여 자네를 구할 걸세.", progress = nil, completion = "수고했네! 무덤은 알터랙 계곡 점령에 있어 아주 중요한 거점이라네. 무덤을 하나 점령할 때마다 이곳의 얼라이언스 지배력은 더욱 확고해지는 것이지.\n\n자, 이제 가보게. 다시 싸움터로 돌아가 호드의 지배하에 있는 무덤을 보거든... 어떻게 해야 하는지 잘 알겠지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7082] = {title = "알터랙 계곡의 무덤", objective = "얼라이언스가 점령하고 있는 무덤을 공격한 다음 알터랙 산맥에 있는 하사관 티카 블러드스날에게 돌아가야 합니다.", description = "알터랙 계곡의 전선은 항상 움직이고 있어. 전투를 벌일 때마다 우리 영토가 늘었다 줄었다 하거든. 그 중에서도 가장 치열한 싸움이 벌어지는 곳이 바로 무덤일세.\n\n얼라이언스가 손에 넣은 무덤을 공격해! 가운데 얼라이언스 깃발이 꽂힌 무덤을 찾아 깃발을 뽑아내 버리면 돼.\n\n그렇게만 하면 그 무덤은 우리 것이 되고 자네 임무는 끝이야. 자네가 거기서 조금만 버티면 호드의 수호병들이 당도하여 구해줄 걸세.", progress = nil, completion = "수고했어! 우리가 무덤을 하나씩 점령해나갈 때마다 적들의 영혼은 쉴 곳을 잃고 정체 없이 떠돌게 될 거야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7101] = {title = "보초탑과 참호", objective = "적군의 보초탑을 점령한 다음 알터랙 산맥에 있는 하사관 티카 블러드스날에게 돌아가야 합니다.", description = "보초탑과 참호는 전술적으로 중요한 위치이기 때문에 전부 다 우리 손에 넣어야 해! 적군이 점령하고 있는 보초탑이나 참호를 공격하게.\n\n우선 얼라이언스 깃발이 내걸린 보초탑이나 참호로 가야 할 거야. 안으로 들어가면 또 다른 깃발이 있을 걸세. 그걸 찢어버리면 그 자리에 호드의 깃발이 나타날 거야!\n\n그러면 자네의 임무도 끝나지. 거기에다 일정 시간 동안 얼라이언스가 되찾지 못하도록 방어해준다면, 그곳은 완전히 파괴될 거야!", progress = nil, completion = "임무를 성공적으로 완수했다는 소식 들었네! 참으로 기쁘군...\n\n우리 부대가 전진하는데 걸림돌이 되는 곳이 파괴됐다니 이제부터 알터랙 계곡은 얼라이언스 따위가 들어올 곳이 아니라는 사실을 똑똑히 가르쳐 주겠어.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7102] = {title = "보초탑과 참호", objective = "적군의 보초탑이나 참호에 있는 깃발을 파괴한 후 알터랙 산맥에 있는 하사관 두르겐 스톰파이크에게 돌아가야 합니다.", description = "보초탑과 참호는 중요한 방어 진지이니 가능한 많이 점령해야 하네! 알터랙 계곡에 있는 보초탑이나 참호를 공격하게.\n\n그러려면 우선 보초탑 위에 호드 깃발이 있는 곳으로 진입해야 해. 내부로 진입하면 또 다른 적 깃발이 있을 것이네. 깃발을 뽑아버리면 그 자리에 흰색의 얼라이언스 깃발이 꼽히게 될 걸세! 그러면 임무를 완수한 것이야.\n\n하지만 호드가 다시 점령하지 못하도록 그곳을 방어해야 하네. 그러면 결국 보초탑이 파괴될 것이야!", progress = nil, completion = "자네가 적군의 깃발을 확보하는 데 공헌을 했다는 보고를 받았네. 수고했군! 녀석들의 궁병들이 없으니 우리는 전선으로 진격할 수 있게 됐군!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7121] = {title = "병참장교", objective = "스톰파이크 병참장교와 대화해야 합니다.", description = "우리 병참장교님께서 초임자들을 보내라고 하셨습니다. 알터랙 광산에 비축해둔 보급품이 필요하다는데 아마도 당신에게 보급품을 가져오는 일을 맡기실 겁니다.\n\n길을 따라가다 보면 서쪽에 병참장교님께서 계실 것입니다.", progress = nil, completion = "신입 병사를 보니 기분이 좋군. 하지만 운이 조금 따라서 전투에 몇 번 참가하다 보면 그 풋내기 티도 오래가지 않을 것이오!\n\n잠깐, 당신과 의논해야 할 임무가 있소이다...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7122] = {title = "광산 점령", objective = "스톰파이크 경비대가 점령하지 않은 광산을 점령한 후 알터랙 산맥에 있는 하사관 두르겐 스톰파이크에게 돌아가야 합니다.", description = "알터랙 계곡의 광산에는 광물만 있는 것이 아니네. 서리늑대부족과 스톰파이크 경비대 모두가 남은 보급품을 깊은무쇠 광산과 얼음이빨 광산에 숨겨두고 있네. 그것도 나쁜 생각은 아니지... 우리가 그 광산을 점령할 수 있다면 말이야.\n\n광산을 하나 점령한 뒤 내게 돌아오게. 광산을 점령하려면 우리가 점령하지 않은 광산에 들어가 그 지휘자를 처치하면 되네. 그러면 광산은 우리 차지가 되니까 경비대를 보내 방어하면 될 것이야!", progress = nil, completion = "해냈군! 수고했네!\n\n광산을 점령하고 군대를 보내 주둔시키면 광물을 캐고 보급 물자를 수송하는 일이 훨씬 수월해지지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7123] = {title = "병참장교와의 대화", objective = "서리늑대 병참장교와 대화하십시오.", description = "지금 서리늑대 병참장교가 알터랙 계곡의 광산과 관련된 임무가 있다며 신병을 찾고 있네. 더 자세한 얘기를 듣고 싶거든 가서 그와 얘기해 보게.\n\n서쪽으로 길을 따라가면 나오는 참호 안으로 들어가게. 바로 오른쪽 출구로 나가면 우리 병참장교를 만날 수 있을 걸세.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7124] = {title = "광산 점령", objective = "광산 하나를 점령한 후 알터랙 산맥에 있는 하사관 티카 블러드스날에게 돌아가야 합니다.", description = "알터랙 계곡 전체가 전쟁에 휩쓸리면서 얼음이빨 광산과 깊은무쇠 광산도 흔들리고 있네. 두 광산 모두 풍부한 광물의 산지일 뿐만 아니라 보급품 저장고로 쓰이고 있지. 그러니까 그 광산들을 그토록 높이 평가하는 건 당연한 일이지!\n\n우리를 도와 주게! 호드의 명예를 위해 전쟁에 참전하여 광산 중 하나를 점령하게! 아직 우리 것이 아닌 광산에 들어가 거기 지도자를 처치하라는 말이야. 그러면 그 광산은 우리 차지가 되는 것이니 부대를 보내 그곳을 방어하도록 하겠네!", progress = nil, completion = "광산을 점령했군! 이제 우리 부대가 광산을 지키고 있으니 광물이나 보급품 모으기가 훨씬 더 수월해질 걸세.\n\n수고했네, 자네는 큰 전적을 세운 것이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7141] = {title = "알터랙의 전투", objective = "알터랙 계곡으로 진입하여 호드 사령관인 드렉타르를 처치하고, 알터랙 산맥에 있는 발굴조사단장 스톤휴어에게 돌아가야 합니다.", description = "탐험가 연맹에서는 알터랙 계곡에 유물이 있다고 생각하고 있습니다만, 서리늑대 오크들이 우리 탐험을 막고 있습니다. 호드가 우리의 학문 연구를 가로막게 할 순 없어요! 서리늑대부족의 드렉타르 사령관을 처치하세요. 그가 죽으면 오크들의 사기가 수그러들 겁니다.\n\n드렉타르는 알터랙 계곡의 북쪽에 있는 서리늑대 요새에 있습니다. 녀석을 쓰러뜨린 다음에 내게 돌아오십시오.", progress = nil, completion = "수고했습니다! 사령관의 죽음으로 호드 녀석들의 기세가 많이 꺾였을 테니 이제 조금은 안심하고 탐험을 할 수 있겠군요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7142] = {title = "알터랙의 전투", objective = "알터랙 계곡으로 진입하여 얼라이언스 사령관인 반다르 스톰파이크를 처치하고, 알터랙 산맥에 있는 보그가 데스그립에게 돌아가야 합니다.", description = "스톰파이크 드워프들과 동맹을 맺은 종족들이 알터랙 계곡에 침입했는데, 반드시 녀석들을 몰아내야만 하네! 알터랙 전투에서 승리하려면, 스톰파이크 사령관인 반다르 스톰파이크를 제거해야만 하네!\n\n반다르는 알터랙 계곡 북쪽에 있는 던 발다르에서 찾을 수 있을 게야.\n\n그를 처치한 후 내게 돌아오도록!", progress = nil, completion = "수고했네! 스톰파이크 녀석들은 이제 이 어리석은 침략에 아무 희망도 없어.\n\n하핫! 지금까지 녀석들이 이룬 거라곤 자기 사령관을 죽음으로 내몬 것뿐이란 말이지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7161] = {title = "신병 계급장", objective = "알터랙 계곡의 서리늑대 요새 남동쪽에 위치한 자갈발 동굴로 가서 서리늑대부족 깃발을 찾아 전투대장 락그론드에게 가져가야 합니다.", description = "어서 오게. 전장의 부름에 응할 기회를 가져보는 게 실로 얼마 만인지 모르겠군. 하도 오래돼서 느낌을 되살리는 데 시간이 좀 걸리긴 하겠지만... 일단 불이 붙으면 피가 끓어오르지. 음, 전의가 되살아나군.\n\n알터랙 계곡에 처음으로 온 신병들은 먼저 전투의 의식을 치러야 하지.\n\n자갈발일족 놀의 동굴 깊숙한 곳에 서리늑대 깃발이 있네. 가서 그 깃발을 가져와! 그러면 내가 친히 서리늑대 1급 계급장을 달아주지.", progress = "정신 차리게, 정신을! 이건 꿈이 아니야. 지금 자네는 치열한 전투의 한복판에 서 있는 거란 말일세!", completion = "자네가 지금 느끼고 있을 그 타오르는 듯한 기분을 나도 알고 있네. 바로 자네의 영혼이 깨어나 전장의 부름에 응한 것이지.\n\n서리늑대부족의 일원이 된 것을 축하하네.\n\n이 계급장을 항상 달고 다니게나. 계급이 높아지면 더욱 강력한 계급장으로 바꿔주겠네.\n\n여기 지금 내 앞에 서 있는 자네가 어쩌면 훗날 서리늑대부족에서 아주 높은 지위에 오를지도 모르지. 그런 날이 오면 지휘의 눈을 받게 될 수도 있겠지.", rewards = "다음과 같은 것들을 받습니다:\n\n서리늑대 1급 계급장양파 껍질 벗기기"},
[7162] = {title = "신병 계급장", objective = "알터랙 계곡에 있는 던 발다르에서 남서쪽에 위치한 얼음날개 동굴로 가서 스톰파이크 깃발을 찾아 알터랙 산맥에 있는 부관 해거딘에게 돌아가야 합니다.", description = "아주 잘 왔소, <class> 친구. 이 서리늑대 야만인 녀석들은 도대체가 포기할 줄을 모른단 말이야! 녀석들에게 우리 스톰파이크의 힘을 보여주고 우리의 우월함에 머리를 조아리도록 만들어야 하오.\n\n하지만 싸움터에 나가기 전에 먼저 스톰파이크 경비대에 합류하는 게 좋을 것이오.\n\n던 발다르에서 남서쪽으로 가면 얼음날개 동굴이 있는데, 그 동굴 깊숙한 곳에 스톰파이크 깃발이 꽂혀 있소. 가서 그 깃발을 내게 가져오면 내가 스톰파이크 신병 계급장을 주겠소.", progress = "그곳 하피들을 조심하시오, <class> 친구. 인정사정 없이 달려들 테니까 말이야!", completion = "자, 스톰파이크의 긍지를 가지고 이 계급장을 착용하도록 하시오. 스톰파이크 경비대에서 계급이 올라가면 계급장도 같이 변경될 것이오. 스톰파이크에서 명예를 더 쌓게 되면 내게 돌아오시오. 당신의 계급장을 더욱 강력한 다른 계급장으로 바꿔주도록 하겠소.\n\n어쩌면 훗날 당신이 이 전장의 전설로 떠오르게 될지도 모르지. 그런 날이 오면 지휘의 눈을 받게 될지도 모르오.", rewards = "다음과 같은 것들을 받습니다:\n\n스톰파이크 1급 계급장서리늑대 엉겅퀴"},
[7163] = {title = "명예로운 계급 상승", objective = "<경례를 하는 전투대장 락그론드>\n\n이제 때가 되었네, <name>. 자네는 서리늑대부족을 위해 많은 일을 했고, 서리늑대부족의 병사이자 친구로서 지금의 자리에 오르게 되었어.\n\n수고했네! 처음 신병으로 받았던 계급장을 보이게.", description = nil, progress = "<경례를 하는 전투대장 락그론드>\n\n이제 때가 되었네, <name>. 자네는 서리늑대부족을 위해 많은 일을 했고, 서리늑대부족의 병사이자 친구로서 지금의 자리에 오르게 되었어.\n\n수고했네! 처음 신병으로 받았던 계급장을 보이게.", completion = "이 새 계급장은 서리늑대부족 내에서 자네의 계급을 말해주는 것이야. 그러니 항상 몸에 지니고 다니도록!\n\n그리고... 명예로운 죽음을 맞이하길 바라네!", rewards = "다음과 같은 것들을 받습니다:\n\n서리늑대 2급 계급장"},
[7164] = {title = "서리늑대부족의 존경", objective = "자네가 다시 날 찾으리란 생각은 하지 않았는데 이렇게 다시 보게 되니 정말 반갑군. 지금까지 자네는 용맹스럽고 명예로운 서리늑대부족의 병사임을 입증해 보였네.\n\n다시 계급이 상승할 때가 온 거지. 그리고 지위에 맞는 새 계급장을 받아 마땅하고...\n\n자네가 지금 달고 있는 계급장을 내보이게.", description = nil, progress = "자네가 다시 날 찾으리란 생각은 하지 않았는데 이렇게 다시 보게 되니 정말 반갑군. 지금까지 자네는 용맹스럽고 명예로운 서리늑대부족의 병사임을 입증해 보였네.\n\n다시 계급이 상승할 때가 온 거지. 그리고 지위에 맞는 새 계급장을 받아 마땅하고...\n\n자네가 지금 달고 있는 계급장을 내보이게.", completion = "&lt;경례를 하는 전투대장 락그론드&gt;\n\n자, 계속 우리 서리늑대부족을 지켜줘. 이 전쟁은 반드시 승리해야 해! 드렉타르님 만세! 대족장님 만세!", rewards = "다음과 같은 것들을 받습니다:\n\n서리늑대 3급 계급장"},
[7165] = {title = "경이로운 계급 상승", objective = "온 전장이 수많은 이들의 피로 물들었건만, 자네는... 그 치열한 전투 속에서도 살아남았군. 지금까지 여러 차례 우리 군이 승리하도록 도움을 주었으니 그 대가로 자네의 계급은 올라갈 거야.\n\n계급장을 내보이게나.", description = nil, progress = "온 전장이 수많은 이들의 피로 물들었건만, 자네는... 그 치열한 전투 속에서도 살아남았군. 지금까지 여러 차례 우리 군이 승리하도록 도움을 주었으니 그 대가로 자네의 계급은 올라갈 거야.\n\n계급장을 내보이게나.", completion = "&lt;느닷없이 함성을 지르는 전투대장 락그론드&gt;\n\n전장에 벌써 자네에 대한 얘기가 오가고 있네. 스톰파이크 병사들은 자네 이름만 들어도 두려움에 몸서리를 칠 정도지. 그럼 계속 수고!", rewards = "다음과 같은 것들을 받습니다:\n\n서리늑대 4급 계급장"},
[7166] = {title = "전설의 영웅", objective = "<class>|1이여;여;, 자네에게서 위엄과 권위가 느껴지는군. 이제 자네는 서리늑대부족에게는 고귀한 영웅이... 적에게는 이름만 들어도 두려운 존재가 되었어.\n\n일어서게... 서리늑대부족의 영웅이여... 일어나서 영예로운 상을 받게나!\n\n계급장을 내보이게.", description = nil, progress = "<class>|1이여;여;, 자네에게서 위엄과 권위가 느껴지는군. 이제 자네는 서리늑대부족에게는 고귀한 영웅이... 적에게는 이름만 들어도 두려운 존재가 되었어.\n\n일어서게... 서리늑대부족의 영웅이여... 일어나서 영예로운 상을 받게나!\n\n계급장을 내보이게.", completion = "머지않아 전장에 나간 모든 이들이 자네의 매서운 지도를 받게 될 것이야. 즉 알터랙 계곡에 주둔한 우리 군대의 지휘권은 자네가 손에 쥐게 되는 것이지!", rewards = "다음과 같은 것들을 받습니다:\n\n서리늑대 5급 계급장"},
[7167] = {title = "지휘의 눈", objective = "드렉타르는 자네를 칭송하는 노래를 부르고 칼림도어 전체가 자네의 영웅담으로 떠들썩해. 대족장님께서도 흔들림 없이 부족을 지켜준 자네의 용기에 크게 기뻐하고 계시네.\n\n자네는 호드를 지휘할 수 있는 능력을 기른 거야.\n\n계급장을 내보이게, <name> 사령관!", description = nil, progress = "드렉타르는 자네를 칭송하는 노래를 부르고 칼림도어 전체가 자네의 영웅담으로 떠들썩해. 대족장님께서도 흔들림 없이 부족을 지켜준 자네의 용기에 크게 기뻐하고 계시네.\n\n자네는 호드를 지휘할 수 있는 능력을 기른 거야.\n\n계급장을 내보이게, <name> 사령관!", completion = "계급장의 힘으로 적에게 자네의 우렁찬 목소리를 들려 주게. 호드의 힘은 의심의 여지가 없지!", rewards = "다음과 같은 것들을 받습니다:\n\n서리늑대 6급 계급장"},
[7168] = {title = "진급", objective = "대부분의 존재들이 자신들의 평범함에서 벗어나지 못하기 마련인데, 당신은 모범이 될 만한 훌륭한 얼라이언스의 일원임을 입증해 보였소, <class>. 이제 스톰파이크 2급 계급장을 받을 때가 되었소이다.\n\n당신의 계급장을 내보이시오.", description = nil, progress = "대부분의 존재들이 자신들의 평범함에서 벗어나지 못하기 마련인데, 당신은 모범이 될 만한 훌륭한 얼라이언스의 일원임을 입증해 보였소, <class>. 이제 스톰파이크 2급 계급장을 받을 때가 되었소이다.\n\n당신의 계급장을 내보이시오.", completion = "적들에게 그들을 쓰러뜨린 것이 누구인지 보여주시오! 스톰파이크의 영광을 위하여!", rewards = "다음과 같은 것들을 받습니다:\n\n스톰파이크 2급 계급장"},
[7169] = {title = "스톰파이크 경비대의 존경", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n스톰파이크 3급 계급장"},
[7170] = {title = "경이로운 계급 상승", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n스톰파이크 4급 계급장"},
[7171] = {title = "전설의 영웅", objective = "오, 내 앞에 얼라이언스의 고귀한 영웅이 서 있다니.\n\n<경례하는 부관 해거딘>\n\n스톰파이크에서 5급 계급장을 얻는 자는 몇 안 되지. 적들이 당신 앞에 쓰러지고 당신이 나타나기만 해도 전투 의지를 잃어가는 모습을 지켜보았소. 당신이 전선에 모습을 나타내면 우리 군은 마치 희망의 등불이라도 본 듯했지!\n\n당신의 계급장을 내보이시오.", description = nil, progress = "오, 내 앞에 얼라이언스의 고귀한 영웅이 서 있다니.\n\n<경례하는 부관 해거딘>\n\n스톰파이크에서 5급 계급장을 얻는 자는 몇 안 되지. 적들이 당신 앞에 쓰러지고 당신이 나타나기만 해도 전투 의지를 잃어가는 모습을 지켜보았소. 당신이 전선에 모습을 나타내면 우리 군은 마치 희망의 등불이라도 본 듯했지!\n\n당신의 계급장을 내보이시오.", completion = "분명 지휘의 눈을 얻는 자는 당신이 될 것이오!", rewards = "다음과 같은 것들을 받습니다:\n\n스톰파이크 5급 계급장"},
[7172] = {title = "지휘의 눈", objective = "적에게 당신의 목소리를 들려 주시오, 지휘관이여! 녀석들에게 진정한 공포가 무엇인지 가르쳐 주고, 6급 계급장을 지닌 스톰파이크 영웅들이 얼마나 훌륭한지 보여 주시오!\n\n당신의 계급장을 내보이시오.", description = nil, progress = "적에게 당신의 목소리를 들려 주시오, 지휘관이여! 녀석들에게 진정한 공포가 무엇인지 가르쳐 주고, 6급 계급장을 지닌 스톰파이크 영웅들이 얼마나 훌륭한지 보여 주시오!\n\n당신의 계급장을 내보이시오.", completion = "우리 군을 승리로 이끌 사람은 바로 당신이오, 지휘관이여! 병사들은 당신의 지휘 아래에서 명령을 따르게 될 것이오. 병사들을 이끌고 서리늑대부족을 격파하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n스톰파이크 6급 계급장"},
[7181] = {title = "콜라크의 전설", objective = "전설에 의하면 겨울도끼 트롤들의 막강한 지도자가 나타나면, 그것은 알터랙 계곡에 사는 모든 생명체들을 학살하기 위해서라고 합니다.\n\n콜라크가 나타나면 그를 처치한 후 전투대장 락그론드에게 돌아가야 합니다.", description = "이 지역의 위협은 스톰파이크만이 아니야. 알터랙 계곡에서 벌어지고 있는 전쟁에는 두 개의 전선이 형성되어 있거든. 동족을 잡아먹는다는 겨울도끼 트롤들도 권력을 차지하기 위해 싸우고 있어.\n\n놈들의 우두머리는 피의 광전사 콜라크라고 하는데, 아주 잔인하고 교활하기 짝이 없는 짐승같은 놈이지.\n\n콜라크를 처치하면 겨울도끼부족에게 큰 타격을 입힐 수 있으니 그 짐승을 처치하고 보상을 얻게나!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n피의 추적자얼음가시 창매서운 추위의 마법봉\n\n다음과 같은 것들 또한 받습니다:\n\n귀환의 룬"},
[7201] = {title = "마지막 원소", objective = "검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것도 기억이 납니다.", description = "나락을 탐험하는 이들에게는 일거리가 생기게 마련이랍니다.\n\n검은무쇠단 녀석들은 아주 강력한 골렘을 만들어 내는 방법에 통달했어요.\n\n우리 밀정들로부터 들어온 첫 보고 내용에 의하면 검은무쇠단 드워프들은 고유한 마력 원천을 사용해 자신들이 만들어 내는 골렘들에게 비할 데 없이 엄청난 살생력을 부여한다고 합니다.\n\n우리가 그 원소의 정수를 손에 넣게 될 경우 우리의 누더기골렘으로 어떤 일을 할 수 있을지 한번 상상해 보세요! 도시 전체를 뒤엎어야 한다면 그렇게라도 하세요. 대신 그 정수를 찾기 전에는 돌아와선 안 됩니다! 보상은 위험 부담에 걸맞을 정도로 하겠어요.", progress = "<양손을 비비는 비비안.>\n\n자, 어서 보여 주세요!", completion = "호호, 훌륭하군요! 즉시 언더시티로 보내도록 하죠!\n\n여기 약속한 보상입니다. 잔돈은 가지세요, 구역질 나는 짐승 같으니!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n라그레이브의 인장"},
[7202] = {title = "피의 광전사 콜라크", objective = "전설에 의하면 겨울도끼 트롤들의 막강한 지도자가 나타나면, 그것은 알터랙 계곡에 사는 모든 생명체들을 학살하기 위해서라고 합니다.\n\n콜라크가 나타나면 그를 처치한 후 알터랙 산맥에 있는 부관 해거딘에게 돌아가야 합니다.", description = "이 지역 토착 부족인 겨울도끼 트롤은 우리 뼈를 자기들 상에 오르는 고약한 스튜에 넣어 먹으려고 하는 잔인한 야만족이오.\n\n놈들에게 우리의 힘을 보여줘야 하오!\n\n놈들이 사는 동굴에서 놈들의 지도층 계급 구조에 대해 적은 책을 찾아냈소. 이 책에 의하면 녀석들의 우두머리인 피의 광전사 콜라크는 자기가 나타날 이유가 있을 때까지는 모습을 드러내지 않는다 하오이다.\n\n콜라크의 죽음은 곧 겨울도끼부족의 죽음을 뜻하는 것! 녀석을 처치하고 돌아오시오.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n피의 추적자얼음가시 창매서운 추위의 마법봉\n\n다음과 같은 것들 또한 받습니다:\n\n귀환의 룬"},
[7221] = {title = "발굴조사단장 스톤휴어와의 대화", objective = "던 발다르 주둔지에 있는 발굴조사단장 스톤휴어와 대화하십시오.아, <class>|1이;가; 임무를 받으러 오셨군요. 잘 됐습니다. 스톰파이크 경비대에 전투 병력이 부족한 상황입니다!\n\n던 발다르에 있는 발굴조사단장 스톤휴어가 적진에 들어가 중요한 임무를 수행할 병사를 모집하고 있습니다. 스톤휴어는 던 발다르 주둔지 제일 아래 있을 것이니 그녀와 얘기를 나눠보십시오.\n\n던 발다르로 가다 보면 험한 일도 마다하지 않는 근면한 <class>|1이;가; 할 수 있는 일이 많을 테니 잘 살펴보시기 바랍니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "아, <class>|1이;가; 임무를 받으러 오셨군요. 잘 됐습니다. 스톰파이크 경비대에 전투 병력이 부족한 상황입니다!\n\n던 발다르에 있는 발굴조사단장 스톤휴어가 적진에 들어가 중요한 임무를 수행할 병사를 모집하고 있습니다. 스톤휴어는 던 발다르 주둔지 제일 아래 있을 것이니 그녀와 얘기를 나눠보십시오.\n\n던 발다르로 가다 보면 험한 일도 마다하지 않는 근면한 <class>|1이;가; 할 수 있는 일이 많을 테니 잘 살펴보시기 바랍니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7222] = {title = "보그가 데스그립과의 대화", objective = "서리늑대 요새에 있는 보그가와 대화하십시오.<class>|1이라;라;... 잘됐군요! 알터랙에서 이렇게 만나게 돼서 기쁩니다. <name>! 현재 드워프와 얼라이언스들이 우리 계곡에 침입한 형세입니다. 그래서 정의로운 처단을 내리고자 하는 호드의 일원이라면 누구나 환영하고 있습니다!\n\n보그가 데스그립이 알터랙 계곡의 얼라이언스 거점을 칠 중요한 임무를 수행할 요원을 찾고 있으니 그와 얘기를 나눠보십시오!\n\n보그가는 서리늑대 요새에서 찾을 수 있을 겁니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "<class>|1이라;라;... 잘됐군요! 알터랙에서 이렇게 만나게 돼서 기쁩니다. <name>! 현재 드워프와 얼라이언스들이 우리 계곡에 침입한 형세입니다. 그래서 정의로운 처단을 내리고자 하는 호드의 일원이라면 누구나 환영하고 있습니다!\n\n보그가 데스그립이 알터랙 계곡의 얼라이언스 거점을 칠 중요한 임무를 수행할 요원을 찾고 있으니 그와 얘기를 나눠보십시오!\n\n보그가는 서리늑대 요새에서 찾을 수 있을 겁니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7223] = {title = "방어구 조각", objective = "던 발다르에 있는 멀고트 딥포지에게 방어구 조각 20개를 가져가야 합니다.", description = "알터랙 계곡에서는 언제나 전투가 한창이라서 아이언포지에서 오는 보급품만으로는 우리처럼 숙련된 부대의 장비를 개량하는 데 충분하지 않네.\n\n전장에서 방어구 조각을 찾거든 나한테 그 조각들을 가져와 주게나!", progress = "방어구 조각은 좀 가져왔나?", completion = "아주 괜찮은 조각들을 가져왔군. 이걸로 우리 부대를 위해 새로운 장비를 만들 수 있겠어.\n\n보급품이 충분히 확보되면 우리 노련한 전투 부대가 전장에 뛰어들게 될 걸세!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n광택낸 갑옷\n\n다음과 같은 것들을 받습니다:\n\n"},
[7224] = {title = "전리품", objective = "서리늑대 마을에 있는 대장장이 렉자르에게 방어구 조각 20개를 가져가야 합니다.", description = "적과 싸우게 되면 녀석들의 방어구 조각을 모아 내게 가져오시오. 그 조각들로 우리 부대를 위한 새 방어구를 만들려고 하니까!", progress = "<name>, 사냥은 어땠소? 방어구 조각은 좀 모아왔소?", completion = "이거면 딱 되겠군. 이걸 녹여서 잘 다듬기만 하면 감쪽같지! 스톰파이크 겁쟁이들이 쓰던 것인지는 아무도 모를 거요!\n\n&lt;name&gt;, 고맙소. 당신 방어구도 좀 다듬어줘야겠는데...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n광택낸 갑옷\n\n다음과 같은 것들을 받습니다:\n\n"},
[7241] = {title = "서리늑대부족 수호", objective = "알터랙 산맥에 있는 알터랙 계곡으로 가십시오. 입구 바깥에 서 있는 전투대장 락그론드를 찾아 서리늑대부족 병사로서의 경력을 쌓도록 하십시오. 알터랙 계곡은 타렌 밀농장 북쪽의 알터랙 산맥 기슭에 있습니다.", description = "머나먼 땅에서 전장의 북소리가 울리고 있네, <class> 친구! 대족장님께서 아끼시는 그대의 부족이 지금 아이언포지의 극악한 스톰파이크 경비대에게 공격을 받고 있어.\n\n보아하니 그대도 전투를 한두 번 치른 것 같지는 않은데 이제 서리늑대부족의 대의를 받아들일 준비가 된 것 같군.\n\n발전을 위해 다음 단계로 나아가는 건 바로 개개인의 의지에서 비롯되지.\n\n타렌 밀농장 북쪽에 가면 알터랙 계곡으로 통하는 입구를 찾을 수 있을 걸세. 거기서 전투대장 락그론드를 찾을 수 있을 게야! 어마어마한 전쟁의 회오리가 다가오고 있으니 서두르게나, <class> 친구!", progress = nil, completion = "서리늑대부족의 병사가 되려면 먼저 시험을 치러야 하지...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7261] = {title = "칙명", objective = "힐스브래드 구릉지에 있는 알터랙 계곡으로 가야 합니다. 알터렉 계곡으로 들어서는 입구 터널 밖에 있는 부관 해거딘을 찾아 대화하십시오.\n\n브론즈비어드의 영광을 위하여!", description = "우리는 현재 알터랙에서 혹독한 전쟁을 치르고 있습니다. 한쪽에서는 식인 부족인 겨울도끼 트롤이, 다른 쪽에서는 잔악한 서리늑대부족이 공격을 해오는 판국입니다. 마그니 브론즈비어드 폐하의 이름으로 두 부족을 모두 몰살해야 합니다! 그 땅을 점령한 후 쓸모 없는 놈들을 몰아내고 변화시키는 것이 영토 확보를 위한 아이언포지 왕국 최고의 칙명입니다.\n\n안타깝게도 병사들은 하늘에서 뚝 떨어지는 게 아니지요! 알터랙 계곡 외곽에 있는 해거딘 부관을 만나 보고하는 것을 시작으로 당신의 임무를 시작하도록 하십시오. 그리고 스톰파이크 병사들 사이에서 명예를 드높이도록 하십시오.", progress = nil, completion = "자, 마그니브론즈 폐하의 영광을 위한 전투를 시작하도록 합시다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7281] = {title = "우애", objective = "스톰파이크 영토로 쳐들어가 얼라이언스 사령관 칼 필립스를 처치해야 합니다. 임무를 완수하면 호드 사령관 루이스 필립스에게 돌아가십시오.", description = "비극이로군... 우리 형이 스톰파이크의 사령관이 되어 전장에서 나와 맞서게 되다니...\n\n형이 스톰파이크의 4대 사령관 중 가장 위험한 인물이라는 건 두말할 필요 없는 사실이오. 혹시 형이 전사하면 밴시 여왕님께서 형을 나처럼 바꿔 주실지도 모르오. 형의 인생이 잘못됐음을 보여주시는 것이지...\n\n적의 요새로 깊숙이 들어가면 우리 형을 찾을 수 있을 것이오. 형을 처치하고 내게 돌아오시오. 당신이라면 이 임무를 맡을 능력이 충분하리라 믿소.\n\n참, 절대 혼자서는 가지 마시오.", progress = nil, completion = "&lt;name&gt;, 그대의 영웅담은 모든 이들의 입에 오르내리게 될 것이오.\n\n형의 영혼까지 완전히 구원하려면 시간을 낭비해서는 안 되지... 난 실바나스 여왕님에게 연락을 취해야겠소!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7282] = {title = "우애", objective = "서리늑대부족 진영으로 들어가 사령관 루이스 필립스를 처치한 후 얼라이언스 지휘관 칼 필립스에게 돌아가야 합니다.", description = "내 아우의 비극을 끝내줘야만 하오! 내 아우는 지금 끔찍한 밴시 여왕의 노예가 되어 자신이 뭘 하고 있는지조차 알지 못하고 있소.\n\n투쟁의 벌판을 가로질러 서리늑대부족의 진영으로 깊숙이 들어가 내 아우를 찾아 처치하시오. 녀석의 고통을 이제 끝나야만 하오.", progress = nil, completion = "시신을 태우는 걸 잊지는 않았겠지?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7301] = {title = "추락한 편대사령관들", objective = "서리늑대 부족의 진영으로 가서 편대사령관 실도르, 편대사령관 비포르, 그리고 편대사령관 이크만을 찾아야 합니다. 임무를 완수하면 지휘관 더피에게 돌아가십시오.", description = "우린 호드 편대사령관 녀석들을 포로로 잡았네, <class> 친구. 창공에서 아주 치열한 싸움을 벌였지만 결국은 녀석들을 잡았지! 그런데 유감스럽게도 서리늑대 요새에 반격을 가하는 도중 우리 최정예 조종사들이 격추당했네.\n\n우리 편대사령관들이 마지막으로 목격된 장소는 서부 거점 보초탑과 서리늑대 요새일세. 그곳을 철저히 수색해서 우리 편대사령관들을 찾는 임무를 자네가 수행해 주게나.", progress = nil, completion = "믿을 수가 없군! 자네가 그들을 풀어줬단 말이지? 뭐, 최소한 어디에 포로로 잡혀 있었는지는 알았군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7302] = {title = "추락한 편대사령관들", objective = "호드 편대사령관 구스, 제즈톨, 그리고 멀베릭이 어떻게 되었는지 알아내야 합니다. 임무를 완수하면 지휘관 멀포트에게 돌아가십시오.", description = "우리 공중 지원군이 큰 타격을 받았습니다. 편대사령관들이 적진에서 격추당한 것이죠. 우선 그들을 찾아낸 다음 구출을 시도해 보십시오!\n\n구스는 얼음날개 참호 위를 날아가는 모습이 마지막으로 목격됐다고 하고, 제즈톨의 전투 와이번은 스톰파이크 벌목지 근처에서 발견됐다고 합니다. 멀베릭... 그 멍청한 녀석은 무모하게도 북부 던발다르 참호 부근에서 추락하는 걸 목격했다고 합니다.\n\n제가 들은 정보는 이게 전부입니다. 당장 출발하십시오! 가서 이 지역들을 샅샅이 뒤져 보십시오.", progress = nil, completion = "수고 많았습니다! 당신이 가져온 정보는 정말 중요한 것입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7321] = {title = "독특한 거북이 비스크", objective = "타렌 밀농장에 있는 크리스토프 제프코트에게 거북이 고기 10개와 독특한 양념을 가져가야 합니다.", description = "언데드는 요리를 할 줄 모른다고 누가 그러든가? 나만의 비법인 독특한 거북이 비스크 조리법 같은 경우는 말이지, 그거 한 그릇 먹으려고 죽었던 사람도 깨어날 정도라고! 헤헤...\n\n말이 나왔으니 말인데, 요즘에는 그 거북이 비스크를 만들 수가 없다네. 예전에는 로다미어 호수에 직접 가서 그 끔찍한 무쇠턱거북을 사냥하곤 했는데, 여기서 하는 일을 두고 갈 수가 없어서 말이야.\n\n무쇠턱거북의 거북이 고기와 독특한 양념을 가지고 오면 어떻게 만드는 건지 가르쳐주지!", progress = "재료는 좀 찾았나? 정말이지, 이제는 이 지역에도 얼라이언스 쓰레기들이 너무 설쳐대서 말이야... 내가 보기에는 녀석들이 벌써 너무 가까이 와 있다니까...", completion = "나의 독특한 거북이 비스크 한 그릇이면 추운 밤도 따뜻하게 지낼 수 있을 게야. 자네가 추위에 신경을 쓰기나 한다면 말이지.", rewards = "다음과 같은 것들을 받습니다:\n\n조리법: 독특한 거북 비스크독특한 거북이 비스크"},
[7341] = {title = "공정한 거래", objective = "훌륭하군! 나는 약속을 지킬 줄 아는 타우렌이외다, <race> 친구. 화살을 받으시오.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n토륨 화살"},
[7342] = {title = "화살 거래", objective = "아니, 이런 말도 안 되는 일이?! 마지막으로 카라노스에서 온 탄환들은 완전히 불량품이었지 뭐예요! 이제 남은 거라곤 아무짝에도 쓸모없는 이 화살뿐이라고요! 대체 토륨 화살 500,000개로 뭘 어쩌겠어요?\n\n흠... 이렇게 하면 어떨까요? 제게 토륨 탄환을 가져다주시면 토륨 화살로 교환해 드릴게요. 어때요?", description = nil, progress = "아니, 이런 말도 안 되는 일이?! 마지막으로 카라노스에서 온 탄환들은 완전히 불량품이었지 뭐예요! 이제 남은 거라곤 아무짝에도 쓸모없는 이 화살뿐이라고요! 대체 토륨 화살 500,000개로 뭘 어쩌겠어요?\n\n흠... 이렇게 하면 어떨까요? 제게 토륨 탄환을 가져다주시면 토륨 화살로 교환해 드릴게요. 어때요?", completion = "머리털 나고 지금까지 본 중에 제일 멋진 거래요! 이제 토륨 화살은 당신 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n토륨 화살"},
[7361] = {title = "검은창 부족의 호의", objective = "알터랙 계곡에 있는 얼라이언스 진영의 나이트 엘프 플레이어를 쓰러뜨리라는 임무를 받았습니다.\n\n나이트 엘프를 처치하고 서리늑대 요새에 있는 나자크 헥센에게 나이트 엘프 머리카락을 가져가야 합니다.", description = "<이빨을 갈며 분을 삭이는 나자크>\n\n우리 트롤은 나이트 엘프들이 이 세계에 존재하기 전부터 있었어. 사실 나이트 엘프들도 우리에게서 나온 종족이라고...\n\n그런데 우리에게 이런 반역적인 공격을 해오다니 용서할 수 없어! 스태그헬름 녀석은 우리 트롤의 뿌리를 뽑아버리려 하지. 자기 종족을 이 세상에 있게 해준 우리를 흔적까지 없애려 한단 말일세. 그건 절대로 있어서는 안 될 일이지 않은가?!\n\n나이트 엘프를 하나씩 처치할 때마다 우리 검은창 부족의 호의를 살 수 있도록 이 나자크가 도와주겠네. 자네의 업적에 대한 소문이 칼림도어, 아니 동부 왕국 전체에 퍼질 거야. 어서 가서 우리 검은창 부족을 도와 줘!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7362] = {title = "타우렌의 동지", objective = "알터랙 계곡에 있는 얼라이언스 진영의 노움 플레이어를 쓰러뜨리라는 임무를 받았습니다.\n\n노움을 처치하고 서리늑대 요새에 있는 라바크 그림토템에게 노움 머리카락 뭉치를 가져가야 합니다.", description = "대모 마가타님께서는 다른 종족을 연구하라면서 저를 이 전쟁터로 보내셨습니다. 더 정확히 말하자면 노움의 견본을 구하는 것이지요. 마가타님께서는 노움의 생존 능력에 관심이 많으십니다. 노움은 처량 맞을 정도로 작고 나약하지만 전투 중일 때나 아닐 때나 엄청난 회복력을 자랑하거든요.\n\n당신은 참 운이 좋으신 분이로군요. 제가 지금 마가타님의 명령을 수행할 분을 하나 찾던 중이거든요. 노움 머리카락 뭉치를 하나 가져 오면 우리 타우렌의 동지로 인정받게 될 겁니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7363] = {title = "인간의 본질", objective = "알터랙 계곡에 있는 얼라이언스 진영의 인간 플레이어를 쓰러뜨리라는 임무를 받았습니다.\n\n인간을 처치하고 지휘관 루이스 필립스에게 인간 뼛조각 하나를 가져가야 합니다. 지휘관 루이스 필립스는 최전선과 서리늑대 요새 사이를 거닐고 있을 것입니다.\n\n인간의 본질을 치유할 날이 얼마 남지 않았습니다!", description = "인간이란 참으로 가증스러운 것들이오.\n\n<인상을 찌푸리는 호드 사령관 필립스>\n\n내가 서리늑대 부족의 사령관이기는 하나 그 전에 실바나스 님의 미천한 종이라오.\n\n나는 여기 임무를 수행하면서 언더시티의 연금술 실험실에서 비밀리에 맡긴 일도 하고 있소.\n\n바로 인간 뼛조각을 수집하는 일 말이지... 그 뼛조각은 인간의 본질을 치유하는 데 쓰인다오.\n\n나는 이 임무를 부하에게 위임할 수 있도록 허가를 받았소.\n\n인간을 찾아 처치하고 그 뼛조각을 내게 가지고 오시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7364] = {title = "놈리건 현상금", objective = "알터랙 계곡에 있는 호드 진영의 타우렌 플레이어를 쓰러뜨리라는 임무를 받았습니다.\n\n타우렌을 처치하고 던 발다르에 있는 더크 스윈들에게 타우렌 발굽을 가져가야 합니다.", description = "땜장이왕께서 나를 몸소 이 전장으로 보내시어 내 노움 형제들과 자매들을 수호하라 하셨답니다. 타우렌이 노움만 골라서 처치하고 있다는 정보를 입수했기 때문이지요. 하지만 가장 모욕적인 것은 죽은 노움의 시신에서 멋진 우리 노움의 머리카락을 뽑아버린다는 거예요. 우리는 이런 극악무도한 짓을 막고 보복을 해야 합니다!\n\n녀석들의 발굽을 내게 가져오세요, <class>! 그래서 당신이 노움의 동지라는 것을 보여주시기 바랍니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7365] = {title = "스태그헬름의 진혼곡", objective = "알터랙 계곡에 있는 호드 진영의 트롤 플레이어를 쓰러뜨리라는 임무를 받았습니다.\n\n트롤을 처치하고 던 발다르에 있는 아스라마니스에게 검은창 트롤 모조를 가져가야 합니다.", description = "스태그헬름 님께서 싸움터에 있는 트롤 녀석들을 모조리 처치하라는 명령을 내리셨습니다. 트롤 녀석들이 나이트 엘프를 낳았다느니 하는 헛소리를 해대니 따끔한 맛을 보여줘야 합니다.\n\n녀석들을 처치하고 모조를 내게 가져오십시오. 다시 말하면 녀석들의 모조를 훔쳐오라는 겁니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7366] = {title = "대주교의 자비", objective = "알터랙 계곡에 있는 호드 진영의 언데드 플레이어를 쓰러뜨리라는 임무를 받았습니다.\n\n언데드를 처치하고 포세이큰 심장을 얼라이언스 지휘관 칼 필립스에게 가져가야 합니다. 얼라이언스 사령관 칼 필립스는 벌목지와 광산 사이를 정찰하고 있습니다.", description = "대주교님은 현명하신 만큼 인자하시기도 하시오. 그런 쓰레기 같은 녀셕들을 자비의 눈길로 바라보시다니...\n\n<믿지 못하겠다는 듯이 고개를 흔드는 지휘관 칼 필립스>\n\n너무 인자하셔... 정말이지 너무 인자하시단 말이야. 대주교님께서 우리에게 언데드를 불쌍히 여기고 신속하고도 영구적인 죽음을 베풀어주라 명하셨소. 이 위대한 자비의 표시로 우리는 검고 병에 찌든 심장이 필요하오.\n\n내게 포세이큰의 심장을 가져오면 빛의 대성당에서 의식에 따라 태우게 될 것이오. 자, 서둘러 가시오!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7367] = {title = "지뢰 제거", objective = "서리늑대 폭파전문가를 찾아 처치하고 임무를 완수하면 스톰파이크 폭파전문가에게 돌아가야 합니다.", description = "서리늑대부족 녀석들이 최전방과 기지 주위에 지뢰를 설치해 두었으니 적진에 침투할 때는 발 밑을 조심해야 할 걸세.\n\n귀관이 녀석들을 제대로 한방 먹이려면 대인 무기의 근원을 제거해야 할 거야. 바로 녀석들의 폭파전문가를 말하는 것일세. 그 녀석만 처치하면 안전하게 지뢰를 제거할 수 있고, 그 녀석이 쓰러지면 지뢰도 사라지는 것이지.\n\n얼음피 주둔지 근처에 있는 탑에서 그를 찾을 수 있을 걸세. 행운을 빌겠네!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7368] = {title = "지뢰 제거", objective = "스톰파이크 폭파전문가를 찾아서 처치해야 합니다. 임무를 완수하면 서리늑대 폭파전문가에게 돌아가십시오.", description = "지뢰라면 내가 잘 알지. 난 이곳 최전선에 지뢰를 설치하는 임무를 맡고 있거든.\n\n스톰파이크 놈들이 깔아놓은 지뢰밭을 없애고 싶으면 녀석들의 폭파전문가만 제거하면 돼. 그 겁쟁이 드워프 녀석, 보나 마나 투쟁의 벌판 참호 안에 숨어있겠지. 녀석을 처치한 후 지뢰를 제거하면 다시는 지뢰가 나타나지 않을 걸세.\n\n혹시라도 놈을 처치하게 되거든 내게 돌아와 알려주게나. 착한 일을 하면 보상을 받아야 하지 않겠나.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7381] = {title = "콜라크의 귀환", objective = "피의 광전사 콜라크가 투쟁의 벌판에 다시 나타나면 그를 찾아 처치하십시오.\n\n언덕마루 구릉지에 있는 전투대장 락그론드에게 콜라크의 해골을 가져가야 합니다.", description = "콜라크가 죽은 것은 확실하지만 한 가지 의문이 남는군. 과연 그가 완전히 죽었느냐는 것이지. 트롤 부족은 저승을 넘나드는 마술로 악명이 높아서 말이야. 죽은 지도자를 되살려 다시 자기 부족을 통치하게 한다 해도 그리 놀랄 일은 아닐 걸세.\n\n정말 그런 일이 발생한다면 어찌해야 하는지 알겠지.\n\n<손가락으로 목을 긋는 시늉을 하는 전투대장 락그론드>\n\n다시 녀석을 만나면 이번에는 놈의 해골을 가져 오게. 항상 경계를 늦추지 말도록...\n\n이만 해산!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n귀환의 룬"},
[7382] = {title = "영생의 콜라크", objective = "피의 광전사 콜라크가 투쟁의 벌판에 다시 나타나면 그를 찾아 처치하십시오.\n\n알터랙 산맥에 있는 부관 해거딘에게 콜라크의 해골을 가져가야 합니다.", description = "이런 일이 일어나다니 뭔가 잘못된 것 같군... 아무도 콜라크의 시체를 태울 생각을 하지 않은게요? 그 파란 피부의 이교도 트롤 녀석들의 습성이 그러하듯, 자신들의 지도자를 되살리기 위해 온갖 수단과 방법을 가리지 않을 것이오.\n\n경계를 늦추지 말고, 설사 콜라크가 갑자기 나타난다 해도 놀라지 마시오. 만약 녀석이 나타나거든 처치한 다음 시체도 태워버리도록 하시오.\n\n확실히 해두기 위해 시체를 태우기 전에 녀석의 머리를 수습하여 그 해골을 내게 가지고 오시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n귀환의 룬"},
[7383] = {title = "대지의 왕관", objective = "자수정 약병을 채운 다음 돌라나르에 있는 코리드라스 문레이지에게 가져가야 합니다.", description = "하지만 텔드랏실은 모든 면에서 문제가 많았소. 세계수에 대한 스테그헬름님의 신중한 계획은 그분이 바라는 대로 실행됐지만 작은 문제가 있었소. 그리고 그 문제로 인해 텔드랏실에 또 다른 문제들이 꼬리를 물고 발생하게 된 것이오.\n\n지금은 다른 문제들은 제쳐 두겠소. 우선 그대는 북서쪽 신탁의 숲에 위치한 마지막 달샘으로 가도록 하시오. 신탁의 나무 가지 아래 우리의 최초의 달샘이자 가장 강력한 샘이 하나 있소. 그 물을 이 약병에 담아 내게 가져오시오.", progress = "우리 드루이드들은 대드루이드님, 그리고 신탁의 나무와 함께 텔드랏실의 성장을 지켜봐 왔소. 하지만 새로운 고향에 둥지를 틀었음에도 아직 우리는 불사의 생명을 회복하지 못 하고 있소.", completion = "신탁의 나무는 마치 지혜가 형상화된 존재와 같이 느껴진다오. 자, 남은 이야기를 계속하자면...\n\n텔드랏실이 성장해가자 대드루이드께서는 고대에 놀드랏실에서 그랬던 것처럼 용의 축복을 얻기 위해 그들을 만났소. 하지만 시간의 지배자 노즈도르무께서는 드루이드의 오만함을 꾸짖으며 축복을 내리시길 거절하셨소. 알렉스트라자 역시 노즈도르무의 뜻에 동의해 스테그헬름님의 부탁을 거절했고, 그녀의 축복이 없는 텔드랏실은 금이 가고 불안정한 상태로 남게 되었다오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7385] = {title = "한 사발의 피", objective = "적에게서 더 많은 피를 제물로 바칠 수도 있습니다. 당신이 원한다면... <name>, 한 사발 정도라면 흡족하겠습니다.", description = nil, progress = "적에게서 더 많은 피를 제물로 바칠 수도 있습니다. 당신이 원한다면... <name>, 한 사발 정도라면 흡족하겠습니다.", completion = "적들의 목이 수없이 달아났겠군요. 이 피 한사발을 미리 모아둔 피와 섞을 것입니다. 피의 의식이 끝나면 얼음 군주가 나타나 스톰파이크의 개들에게 우리 서리늑대부족의 분노를 보여줄 것입니다!", rewards = nil},
[7386] = {title = "폭풍 수정 묶음", objective = "이 알터랙 계곡에선 때론 며칠이나 몇 주간 전투를 치러야 하는 경우도 있답니다. 그 기간 동안 서리늑대부족의 폭풍 수정을 잔뜩 모으게 될 수도 있지요.\n\n세나리온 의회에서는 그러한 폭풍 수정도 받고 있으니 가져다주시기 바랍니다.", description = nil, progress = "이 알터랙 계곡에선 때론 며칠이나 몇 주간 전투를 치러야 하는 경우도 있답니다. 그 기간 동안 서리늑대부족의 폭풍 수정을 잔뜩 모으게 될 수도 있지요.\n\n세나리온 의회에서는 그러한 폭풍 수정도 받고 있으니 가져다주시기 바랍니다.", completion = "수고했어요. 이 수정의 힘으로 모아둔 마력을 더욱 증강해야겠군요. 마력이 충분히 모이면 모아둔 힘을 이용하여 숲군주님을 소환해 도움을 요청할 것입니다.", rewards = nil},
[7401] = {title = "현상 수배: 드워프!", objective = "알터랙 계곡에서 얼라이언스 진영의 드워프 플레이어를 쓰러뜨리라는 임무를 받았습니다.\n\n드워프를 처치하고 서리늑대 요새에 있는 하사관 야즈라 블러드스날에게 드워프 해골을 가져가야 합니다.", description = "하사관 야즈라 블러드스날의 명령에 의해 전장에 있는 모든 드워프는 목격하는 즉시 사살하십시오.\n\n전투에서 드워프를 쓰러뜨리면 놈들의 해골만 챙기십시오. 냄새 나는 역겨운 시체는 썩도록 그냥 내버려두면 됩니다. 감히 서리늑대 부족에게 맞선 무모함이 어떤 종말을 가져오는지 모두에게 보여줘야 하니까 말입니다.\n\n임무를 완수하면 하사관 야즈라 블러드스날에게 가서 그 증거를 제출하십시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7402] = {title = "현상 수배: 오크!", objective = "알터랙 계곡에 있는 호드 진영의 오크 플레이어를 쓰러뜨리라는 임무를 받았습니다.\n\n오크를 처치하고 던 발다르에 있는 하사관 노레그 스톰파이크에게 오크 엄니를 가져가야 합니다.", description = "노레그 스톰파이크 하사관의 명으로 건장한 신체를 지닌 모든 스톰파이크 병사들은 전장에서 마주치는 오크를 모조리 처치하라.\n\n병사들은 적의 이빨을 가져와 임무를 완수한 증거로 제출하기 바란다.\n\n오크를 잡기 전에 보호용 장갑을 착용하도록 하라.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7429] = {title = "노트 구출 대작전", objective = "그건 고르독 족쇄 열쇠라고 하는 물건이지. 이 오우거 얼간이들이 그렇게 부르더군. 이곳 오우거들이라면 누구나 지니고 있을 텐데, 어떤 오우거 녀석들이 지니고 있는지는 모르겠단 말이야. 경비병들이라면 갖고 있을 확률이 더 높겠지...\n\n아니, 내가 지금 뭔 소리 하는 거야. 당신 벌써 그 열쇠 갖고 있지?! 그게 바로 그 열쇠야?!", description = nil, progress = "그건 고르독 족쇄 열쇠라고 하는 물건이지. 이 오우거 얼간이들이 그렇게 부르더군. 이곳 오우거들이라면 누구나 지니고 있을 텐데, 어떤 오우거 녀석들이 지니고 있는지는 모르겠단 말이야. 경비병들이라면 갖고 있을 확률이 더 높겠지...\n\n아니, 내가 지금 뭔 소리 하는 거야. 당신 벌써 그 열쇠 갖고 있지?! 그게 바로 그 열쇠야?!", completion = "당신이 제일이로군! 다른 녀석들은 뭐, 떨거지일 뿐이지 암.... 아, 풀어줘서 정말로 고맙소!\n\n내 인생이 한낱 오우거따위의 간식으로 끝나지 않을 줄 알았다니까!", rewards = nil},
[7441] = {title = "푸실린과 노쇠한 아즈토르딘", objective = "혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다.\n\n마법서를 회수하면 페랄라스의 라리스 정자에 있는 아즈토리딘에게 돌아가야 합니다.", description = "타락한 왕자의 손아귀에서 벗어나려고 서두르다가 잠깐 방심하여 그만 좀도둑을 만났다오, 이방인 친구. 사악하기 짝이 없는 푸실린이라는 임프가 내 마법서와 이제는 몰락해버린 엘드레탈라스의 전당으로 통하는 열쇠를 훔쳐가버렸소.\n\n내 불멸의 생명력은 자유와 바꿔버렸으니 그 열쇠는 어떻게 되든 상관없지만 마법서는 내게 꼭 필요한 것이오.\n\n혈투의 전당에 있는 굽이나무 지구에서 푸실린을 찾아내 책을 되찾아 주시오.", progress = "후회는 하지 않소, 이방인 친구. 여왕님께서 떠나신 지도 오래되었고 셴드랄라의 업적은 토르텔드린 왕자의 광기로 훼손돼버렸지. 이제 내가 바라는 것은 오직 자유... 탈출 뿐이라오...", completion = "찾았군! 괘씸한 임프 녀석 같으니... 유감스럽지만 내가 가진 게 변변치 못해서 말이오. 내가 줄 수 있는 것 중에서 한 번 골라보도록 하시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n생기의 장화전력의 검\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7461] = {title = "내면의 광기", objective = "이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다.\n\n이몰타르의 감옥에 들어가 그 심장부에 서 있는 사악한 이몰타르를 처치하고, 마지막으로 도서관에 있는 토르텔드린 왕자와 맞서 싸우십시오.\n\n이 임무를 완수하면 안마당에 있는 셴드랄라 고대인에게 돌아가야 합니다.", description = "충분히 들으셨나요? 그대는 말보다 실천을 중요하게 생각하는지요?\n\n이 광란은 끝나야 합니다. 불멸의 생명체가 지배하던 시대는 이미 오래전에 흘러가버렸습니다. 수정탑을 둘러싼 수호자들을 물리쳐 마법진의 힘을 약하게 하고 이몰타르를 처치하십시오. 토르텔드린 왕자의 힘이 많이 쇠약해져 있는 이 때에 녀석을 쳐서 없애야 합니다. 이 도시의 영혼들이 안식을 취할 수 있도록 도와주십시오.", progress = nil, completion = "우리 고대인들이 당신에게 고마움을 표하고 있습니다, 영웅이여.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7462] = {title = "셴드랄라의 보물", objective = "도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!도서관에 가면 계단 밑에 오래된 궤짝이 하나 있는데, 그 안에서 원하는 걸 골라가도록 하게.이 보상들 중 하나를 선택할 수 있습니다:\n\n", description = "도서관에 가면 계단 밑에 오래된 궤짝이 하나 있는데, 그 안에서 원하는 걸 골라가도록 하게.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n해골 파쇄기등나무 투구이삭 장화\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7463] = {title = "신비의 원기 회복 주문", objective = "혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다.", description = "<race> 마법사로군! 정말 신기해. 마법사를 본 지가... 500년은 된 것 같군! 그래, 요즘은 어떻게 지내시오?\n\n당신의 갈증을 해소해줄 만한 게 있긴 하오만 먼저 내 부탁을 하나 들어줘야겠소.\n\n<킬킬거리는 리드로스>\n\n엘드레탈라스에 이례적인 사건이 하나 발생했소. 물의 정령 하나가 도서관 동쪽 서고에 거처를 잡았지 뭐요. 녀석의 출현 사실을 기록해야 하오이다!\n\n굽이나무 지구로 가서 히드로스폰의 정수를 추출해 오시오. 그걸 내게 가지고 오면 아주 유용한 주문을 하나 가르쳐 주도록 하지.", progress = "어서 오시오. 음... 누구시더라?", completion = "훌륭해! 그런데 누구시더라? 뭐, 상관없지. 당신에게 뭘 줘야 한다고? 흠... 당신은 &lt;class&gt;니 이게 유용하게 쓰이겠군그래.", rewards = "다음과 같은 것들을 배웁니다:\n\n음료 창조\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n음료 창조\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7481] = {title = "엘프의 전설", objective = "혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다.", description = "몇 년 전, 텔미우스 드림시커라는 엘프 스승이 고대 엘프 유물 몇 개를 가지고 폐허가 된 고향을 피해 달아났소.\n\n이 사라진 엘프 스승을 쫓다 보니 쿠엘탈라스의 폐허에서 불타는 평원을 지나 망망대해를 건너 페랄라스에 도착하게 됐지.\n\n드림시커는 오늘날 혈투의 전장으로 알려진 엘드레탈라스의 전당에서 은신처를 찾은 것으로 추측하고 있소이다.\n\n그자를 찾아야 하오, 모험가여. 그자가 살았든 죽었든 그가 가지고 간 유물은 반드시 되찾아야 하오이다!", progress = nil, completion = "안타깝군... 비극이야. 카리엘의 자취도 없고 유물들이 사라졌다는 말이오?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7482] = {title = "엘프의 전설", objective = "혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 페더문 요새에 있는 학자 룬쏜에게 돌아가야 합니다.", description = "몇 년 전, 텔미우스 드림시커라는 엘프 스승이 고대 엘프 유물 몇 개를 가지고 폐허가 된 고향을 피해 달아났습니다.\n\n이 사라진 엘프 스승을 쫓다 보니 쿠엘탈라스의 폐허에서 불타는 평원을 지나 망망대해를 건너 페랄라스에 도착하게 됐답니다.\n\n드림시커는 오늘날 혈투의 전장으로 알려진 엘드레탈라스의 전당에서 은신처를 찾은 것으로 추측하고 있습니다.\n\n그자를 찾아야 합니다, 모험가여. 그자가 살았든 죽었든 그가 가지고 간 유물은 반드시 되찾아야 합니다!", progress = nil, completion = "안타깝군... 비극이 아닐 수 없군요. 카리엘의 자취도 없고 유물들이 사라졌다는 말이지요?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7483] = {title = "신속의 성서", objective = "신속의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 그리고 영웅의 피 2개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 신속의 영석을 받아야 합니다.", description = "텔미우스 드림시커님께서 동쪽 서고에 있던 신속의 성서를 잃어버리셨소. 그 고서를 지니고 있으면 하급 신속 주문의 영향을 받게 되는데, 해봐야 속임수일 뿐이야...\n\n어쨌든 영석을 얻을 생각이 있거든 그 고서를 다른 기본 재료들 몇 가지와 함께 내놓아야 할 것이오.\n\n보자... 영웅의 피, 온전한 검은 다이아몬드, 그리고 눈부신 큰 결정이 필요한 걸로 알고 있는데, 확실하게는 잘 모르겠소이다!\n\n<어깨를 으쓱해 보이는 리드로스>", progress = "뭐요? 기록할 것이 잔뜩 있단 말이오!", completion = "&lt;하품을 하는 리드로스&gt;\n\n약속한 대로 신속의 영석을 주도록 하겠소. 한번에 몽땅 써버리진 마시오.\n\n&lt;킬킬거리며 웃는 리드로스&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n신속의 영석"},
[7484] = {title = "집중의 성서", objective = "집중의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 4개, 그리고 어둠의 허물 2개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 집중의 영석을 받아야 합니다.", description = "이 고서는 젊은 현자들 중 한 명이 기르던 하수인 하나가 관심을 가질 뻔했었소. 불쌍한 것, 태어난 지 몇 주밖에 안 됐었는데...\n\n마법에 좀 소질이 있는 자라면 이 물건이 아주 흥미로워 보일 것이오.\n\n이 서고에 있던 집중의 성서가 분실됐는데, 아마도 귀족 엘프의 혼령이 가져가 버린 것이라 생각하오이다.\n\n그 고서와 눈부신 큰 결정 몇 개, 어둠의 허물, 그리고 온전한 검은 다이아몬드를 하나 가져오면 내가 그 영석을 만들어 주겠소.", progress = "또 당신이오? 이번엔 또 무슨 일이오?", completion = "당신 방어구에 마법을 부여하면서 다치지나 마시오, &lt;race&gt;.", rewards = "다음과 같은 것들을 받습니다:\n\n집중의 영석"},
[7485] = {title = "보호의 성서", objective = "보호의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 그리고 닳아해진 누더기골렘 조각 1개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 보호의 영석을 받아야 합니다.", description = "왕자께서 이 고서를 잃어버리더니 아주 어린애처럼 우시더군. 나도 책을 잃고 운 적이야 있소이다만... 지식과 역사를 잃는 것보다 더 큰 손실은 없으니까 말이오. 하지만 그런 쓸모 없고 말도 안 되는 고서를 잃고 운다니 무슨 터무니없는 일이란 말이오? 토르텔드린 왕자께서 자기 몸에 상처를 내는 걸 보면서 오히려 잘 됐다는 생각이 들더이다.\n\n보호의 성서와 온전한 검은 다이아몬드 하나, 눈부신 큰 결정 몇 개, 그리고 닳아해진 누더기골렘 조각을 하나 가져오면 내가 영석을 다시 만들어주지.\n\n아, 그리고 가려면 북쪽으로 가보시오.", progress = "내가 인내심이 있는 자이기에 당신에겐 다행이군그래.", completion = "그래, 그래... 진정하시오. 약속한 대로 영석을 줄 테니까.", rewards = "다음과 같은 것들을 받습니다:\n\n보호의 영석"},
[7486] = {title = "영웅의 보상", objective = "히드락시스의 궤짝에 든 보상을 차지하십시오.", description = "<name>, 군주들에 대한 너의 충성은 우리가 이 세계의 모든 생명체에게 기대했던 것을 초월했다.\n\n너희 종족들이 갖고 있는 감사 또는 선행에 대한 보상이란 개념을 잘 이해할 수는 없다만, 이런 경우라면 정말 상을 내려야 할 것 같다.\n\n이 섬의 남쪽 물 밑을 살펴보면 궤짝이 하나 있을 터인데, 그 안에 네게 내릴 상이 들어있다.\n\n가라, <name>. 가서 차지하라.", progress = nil, completion = "물 위에서 히드락시스의 목소리가 울려 퍼집니다...\n\n\"너에게 가장 잘 맞는 것을 고르도록 하여라, &lt;name&gt;. 그것이 물의 군주들의 적들로부터 너를 보호해 주기를 빈다.\"", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n대양의 바람해일의 고리\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7487] = {title = "심장부와의 조화", objective = "검은바위 나락에 있는 화산 심장부 입구의 차원의 문으로 가서 핵 조각을 찾아야 합니다. 핵 조각을 갖고 검은바위 산에 있는 로소스 리프트웨이커에게로 돌아가십시오.", description = "<race>|1이여;여;, 우리 주변의 모든 것들에는 균열이 생겨서 흔들리며 무너져 갑니다. 여기서 불과 두 발짝도 떨어지지 않은 곳에 검은바위 산의 심연으로 통하는 균열이 있다면 믿어지십니까? 바로 불의 군주의 입으로 통합니다.\n\n놀라셨나요? 애석한 일이로군요... 필멸의 생명체들은 자신들이 보고, 만지고 느낄 수 있는 것이 아니면 이해하지 못하니 말입니다.\n\n분명히 말해두는데, 차원의 문은 정말로 존재하며 그 안으로 들어갈 수도 있습니다.\n\n귀가 솔깃해지셨나요? 방법은 간단합니다. 검은바위 나락으로 가서 핵 조각을 갖고 오기만 하면 되니까요. 제게 돌아오시면 그대의 정기를 차원의 문과 조화시켜 드리겠습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n심장부와의 조화\n\n다음과 같은 것들을 받습니다:\n\n"},
[7488] = {title = "레스텐드리스의 그물", objective = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어에게 레스텐드리스의 그물을 가져가야 합니다.", description = "잔인함이 자신의 마법 중독만큼이나 지독한 레스텐드리스라는 이름의 타락한 블러드 엘프가 혈투의 전장으로 도망쳤습니다. 그녀는 그곳의 마법의 힘을 잡아들이는 그물 장치를 만들었는데, 그대로 내버려두면 우리 세계에 다시는 회복할 수 없는 피해가 생기게 될 것입니다!\n\n그녀를 멈춰주십시오. 그녀를 찾아 그 그물도 회수해주십시오. 아마도 혈투의 전장에서 굽이나무 지구의 사티로스 녀석들 근처에 있을 겁니다. 그물을 내게 가져오면 그 안에 갇힌 힘을 다시 무사히 자연으로 흘려보내겠습니다.", progress = "그물은 가져왔습니까? 그 안에 농축된 마법의 힘을 분산해야만 합니다!", completion = "그물을 되찾았군요! 수고했습니다! 레스텐드리스도 다른 블러드 엘프들과 마찬가지로 마법의 남용이 이 세계에 불러올 수 있는 위험에 대해서는 무지합니다. 그들은 마법의 달인들인 걸로 착각하며 자신들이 마법 중독의 노예인 것은 깨닫지 못하는 것이지요. 그녀가 죽어 안타깝지만 어쩔 수 없는 일이었습니다.\n\n고맙습니다. 이 그물에 든 힘을 넓은 지역에 걸쳐 안전하게 분산한 후, 이 그물을 파괴해 앞으로의 마법 남용을 막도록 하겠습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n지식의 단검"},
[7489] = {title = "레스텐드리스의 그물", objective = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다.", description = "레스텐드리스라는 블러드 엘프가 도를 넘었네. 마법의 힘을 모으는 데 치중한 나머지 자신의 동료들을 배반하고 아주 사악한 장치를 만들었지. 혈투의 전장에서 타락한 마법의 힘을 빨아들이는 그물을 만들어낸 걸세. 지금도 그 힘을 모으며 자신의 적들에게 언젠가 풀어놓을 계획을 꾸미고 있다네.\n\n레스텐드리스를 멈춰야만 하네. 혈투의 전장의 굽이나무 지구에서 그녀를 찾아 물리치고 그 그물을 가져오게. 좀 더 명석한 블러드 엘프들에게 보내 연구를 할 수 있도록 할 테니까 말이야.", progress = "레스텐드리스의 그물을 가져왔는가?", completion = "잘했네. 이 그물에는 혈투의 전장에서 빨아들인 마법의 힘이 가득 들어있어. 레스텐드리스처럼 무책임한 자가 이런 힘을 손에 넣는다면 어떤 재앙을 불러올지 걱정되는군. 그녀가 죽어 슬프긴 하지만 살아서는 이 그물을 넘기지 않았을 테니 어쩔 수 없군.\n\n고맙네. 레스텐드리스보다 더 책임감 있는 마법 학자들에게 이 그물을 보내도록 하지. 그들이 이 힘의 새로운 관리자가 될 게야.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n지식의 단검"},
[7490] = {title = "호드의 승리", objective = "오그리마에 있는 대족장 스랄에게 오닉시아의 머리를 보여줘야 합니다.", description = "당신은 불가능하게만 보였던 일을 해내고 호드의 승리를 이뤄냈습니다. 검은용군단의 여왕이 발 앞에 죽은 채로 쓰러져있다니... 오닉시아의 머리를 가지고 오그리마로 귀환하여 승리의 소식을 대족장에게 알려야 합니다.", progress = "<오닉시아의 거대한 머리를 보자 아주 잠깐 동안 엄숙했던 표정이 변하며 파멸의 망치를 뽑아들 태세를 보이는 스랄...>", completion = "오늘 호드는 커다란 승리를 거두었노라. &lt;name&gt;, 그대는 내게 수없이 경의를 표했었지만, 이제는 이 대족장이 그대에게 경의를 표할 차례로구나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7491] = {title = "승리의 축제", objective = "힘의 골짜기에서 대군주 룬탁을 찾으십시오.", description = "대군주 룬탁이 힘의 골짜기에서 그대가 오기를 기다리고 있노라.\n\n<경례를 하는 스랄>\n\n오그리마의 영웅이여, 주민들이 너무 오래 기다리게 하지는 말게.", progress = nil, completion = "자, 보상을 선택하게. 난 이 영광스러운 승리를 축하하는 의식을 시작하겠네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n오닉시아 피 부적용사냥꾼의 인장오닉시아 이빨 펜던트\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7492] = {title = "모자케 야영지", objective = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프와 대화하십시오.", description = "페랄라스의 타우렌 장로인 탈로 쏜후프께서 도움을 요청하고 계시오. 자세한 얘기는 별로 없으셨지만 아주 민감하면서도... 끔찍한 문제 때문에 요원이 한 명 필요하다고 하셨소.\n\n호드를 받들어 모자케 야영지로 가서 탈로님과 이야기를 나눠보도록 하시오.", progress = nil, completion = "아, &lt;class&gt;|1이;가; 내 부름에 응하다니 잘 됐군. 자네 도움이 필요하네. 유감스럽게도 아주 위험한 일이 될 거야...\n\n혈투의 전장으로 가야 하는 일이라네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7493] = {title = "모험은 이제부터", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n도안: 오닉시아 비늘 망토"},
[7494] = {title = "페더문 요새", objective = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어와 대화하십시오.", description = "페랄라스에서 당신의 도움을 필요로 하고 있습니다!\n\n레스텐드리스라는 사악한 마법사가 지금은 혈투의 전장이라 불리는 고대 엘프 유적지, 엘드레탈라스로 도망쳤습니다. 아주 위험한 마법의 힘이 깃든 물건을 갖고 있는 걸로 알고 있는데, 그 물건을 반드시 찾아야만 합니다.\n\n라트로니쿠스 문스피어님이 혈투의 전장으로 가서 레스텐드리스에게서 그 물건을 회수해올 요원을 요청하셨습니다.\n\n얼라이언스를 받들어 페랄라스에 있는 페더문 요새에서 라트로니쿠스님을 만나 보도록 하십시오!", progress = nil, completion = "어서 오십시오. 만나서 반갑습니다. 하지만 더 좋은 상황 속에서 만나지 못해 유감이군요.\n\n아주 중요한 임무가 있으니 잘 들으십시오...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7495] = {title = "얼라이언스의 승리", objective = "오닉시아의 머리를 스톰윈드로 갖고 가서 대영주 볼바르 폴드라곤에게 보여주어야 합니다.", description = "당신은 불가능하게만 보였던 일을 해냈습니다. 검은용군단의 여왕이 당신 발 앞에 죽은 채로 쓰러져있다니... 그녀의 머리를 갖고 가서 대영주님께 보여주도록 하십시오.", progress = "아니, 어떻게 이런 일이!", completion = "그 오랜 세월 동안 혼을 빼앗는듯한 여왕의 눈빛에 사로잡혀 굴복해 있었거늘, 이제야 정의가 실현되고 스톰윈드의 명예가 회복되었다! 오늘, 이 영광스러운 승리를 경축하리라!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7496] = {title = "대축제", objective = "영웅의 계곡에서 상사 매팅글리를 찾으십시오.", description = "영웅의 계곡으로 가서 상사 매팅글리를 찾도록 하게, <name>. 자네를 기다리고 있을 것이야...", progress = nil, completion = "이렇게 커다란 의식의 주인공이 될만한 영웅은 흔하게 나오지 않는 법이지요. 자, 축하의 의식을 시작할 수 있도록 보상을 골라보십시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n오닉시아 피 부적용사냥꾼의 인장오닉시아 이빨 펜던트\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7497] = {title = "모험은 이제부터", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n도안: 오닉시아 비늘 망토"},
[7498] = {title = "가로나: 은신과 기만에 대한 연구", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.", progress = "책을 찾았군!", completion = "잘 했소, &lt;race&gt; 친구. 이런 책을 더 찾게 되거든 주저하지 말고 우리에게 되돌려주시오.\n\n시간이 지나면서 분실된 책을 찾아주는 자에게 줄 보상을 바꾸거나 심지어는 새로운 보상을 추가하기도 하니 말이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n엘드레탈라스 옥새"},
