[7503] = {title = "사냥꾼의 위대한 혈통", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.", progress = "책을 찾았군!", completion = "잘 했소, &lt;race&gt; 친구. 이런 책을 더 찾게 되거든 주저하지 말고 우리에게 되돌려주시오.\n\n시간이 지나면서 분실된 책을 찾아주는 자에게 줄 보상을 바꾸거나 심지어는 새로운 보상을 추가하기도 하니 말이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n엘드레탈라스 옥새"},
[7504] = {title = "성스러운 볼로냐: 빛이 알려주지 않는 것들", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.", progress = "책을 찾았군!", completion = "잘 했소, &lt;race&gt; 친구. 이런 책을 더 찾게 되거든 주저하지 말고 우리에게 되돌려주시오.\n\n시간이 지나면서 분실된 책을 찾아주는 자에게 줄 보상을 바꾸거나 심지어는 새로운 보상을 추가하기도 하니 말이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n엘드레탈라스 옥새"},
[7505] = {title = "냉기 충격과 주술", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.", progress = "책을 찾았군!", completion = "잘 했소, &lt;race&gt; 친구. 이런 책을 더 찾게 되거든 주저하지 말고 우리에게 되돌려주시오.\n\n시간이 지나면서 분실된 책을 찾아주는 자에게 줄 보상을 바꾸거나 심지어는 새로운 보상을 추가하기도 하니 말이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n엘드레탈라스 옥새"},
[7506] = {title = "에메랄드의 꿈...", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.", progress = "책을 찾았군!", completion = "잘 했소, &lt;race&gt; 친구. 이런 책을 더 찾게 되거든 주저하지 말고 우리에게 되돌려주시오.\n\n시간이 지나면서 분실된 책을 찾아주는 자에게 줄 보상을 바꾸거나 심지어는 새로운 보상을 추가하기도 하니 말이오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n엘드레탈라스 옥새"},
[7507] = {title = "노스트로의 용사냥 개론", objective = "노스트로의 용사냥 개론을 도서관에 되돌려주어야 합니다.", description = "매우 중요한 무엇인가를 찾았습니다. 이 책은 지금까지 보아온 것들과는 다릅니다.\n\n누군가가 도서관의 인장을 깨는 데 성공한 듯하며, 책 안에 쓰인 글은 흐릿하고 거의 읽을 수 없을 정도입니다.", progress = "아, 우리가 편찬한 최고의 작품 중 하나로군. 아주 오랫동안 분실돼 있던 책이오.", completion = "이 책을 암시장에 팔면 돈 좀 꽤 받았을 텐데... 더군다나 보호 인장이 깨져 필요한 지식을 가진 자라면 누구나 이 성스러운 책 안에 든 용 퇴치법을 읽을 수 있게 되었으니 말이오.\n\n아주 큰 보상을 해줘야 마땅하겠지... 뭐, 얻으려면 아주 큰 고생을 해야만 하는 그런 보상 말이오.\n\n&lt;씩 웃는 리드로스&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7508] = {title = "쿠엘세라 검 만들기", objective = "납작하고 무딘 엘프 검을 현자 리드로스에게 주어야 합니다.", description = "이 임무를 맡으려면 현자 리드로스에게 무딘 칼을 보여주어야 합니다.", progress = "좋았소. 시작해볼까...", completion = "용의 둥지에 들어가는 데 성공하면 그 용의 화염 숨결로 날을 달구고, 마지막에는 그 용의 피에 담금질을 하시오. 그러면 그 칼을 당신에게 귀속하도록 하겠소.", rewards = nil},
[7509] = {title = "쿠엘세라 검 만들기", objective = "오닉시아가 달궈지지 않은 고대의 검에 화염 숨결을 내뿜도록 한 후, 달궈진 고대의 검을 뽑으십시오. 달궈진 고대의 검은 언제까지나 달구어져 있지 않으니 서둘러야 합니다.\n\n마지막 단계로 오닉시아의 시체에 달궈진 고대의 검을 꽂으십시오.\n\n이렇게 하면 쿠엘세라 검을 가질 수 있습니다.", description = "이 달궈지지 않은 고대의 검을 오닉시아의 동지로 가져가 오닉시아를 싸움에 끌어들이도록 하시오.\n\n이 칼을 달구려면 꾀를 써야 하는데, 전투 중에는 오닉시아가 반드시 당신을 불태워 죽이려 할 것이오. 이 달궈지지 않은 고대의 검을 근처에 꽂아 놓고 오닉시아의 화염 숨결로 달구어지기를 기대할 수밖에 없소이다. 그 후에도 살아남았다면 달궈진 고대의 검을 다시 뽑아든 후 그 용을 처치하시오.\n\n달궈진 고대의 검을 불타는 오닉시아의 시신에 꽂으면 가공된 고대의 검이 될 것이오.", progress = "언젠가 다른 사람이 그 찬란한 검을 지니게 되겠지.", completion = "&lt;뭐라고 알아들을 수 없는 말을 중얼거리는 리드로스&gt;\n\n약속한 대로 당신에게 쿠엘세라 검을 주겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n쿠엘세라"},
[7541] = {title = "호드를 위한 활약", objective = "자네가 가져온 펜던트를 우리 학자들이 살펴보는 데는 시간이 좀 걸릴 테지만, 호드를 위한 자네의 활약을 기리는 뜻에서 작은 선물을 주고 싶군.\n\n고맙네. 자네가 한 일이 자네 자신은 물론 우리의 명예도 드높인 걸세.", description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n충성의 고리홀로나무 고리\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7562] = {title = "모르줄 블러드브링어", objective = "불타는 평원에 있는 모르줄 블러드브링어와 대화하십시오.", description = "당신은 어둠의 기술을 깊이 탐구해왔습니다. 타계의 생물들에 대한 통제력이 아주 강해진 만큼 이제 그 악명 높은 공포마를 당신에게 결속시킬 준비가 되었을지도 모르겠군요.\n\n그 야수를 불러내 오는 의식을 치르려면 상당한 힘과 자원이 필요합니다. 그래도 이 대단한 탈것을 지배하고 싶다면 모르줄 블러드브링어와 얘기해 보십시오. 그는 불타는 평원에 있는 폭풍의 제단 근처에서 야영하고 있습니다.\n\n자, 어서 가십시오. 아주 위험한 임무가 되겠지만 당신 정도의 흑마법사라면 위험을 두려워하지 않는 법이니까요!", progress = nil, completion = "어서 오십시오. 그대도 나처럼 폭풍의 제단 근처에 수행을 하러 온 모양이군요. 어떤 숨겨진 목적을 위해 폭풍의 제단의 기를 취하러 온 거라든가... 아니면 나와 얘기를 나누러 온 것입니까? 그래요, 그런 것 같군요.\n\n공포마를 부리고 싶은 겁니까? 그건 결코 쉬운 일이 아니며 많은 피와 땀을 쏟아야 합니다... 그리고 물론 상당한 돈도 필요하지요. 하지만 소로스의 공포마는 그만한 가치가 충분히 있으니 관심이 있다면 이제부터 내가 하는 말을 잘 들으십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7563] = {title = "피의 광란", objective = "불타는 평원에 있는 모르줄 블러드브링어에게 흉포한 올빼미야수의 피 30병을 가져가야 합니다.", description = "공포마들은 다른 세계에 서식하는 생물로, 불이 이글거리는 소로스 평원에서 살고 있습니다. 이 야수를 결속시키려면 강력한 상형 문자 주문을 외워야 하는데, 내가 양피지에다 그 상형 문자를 적어줄 수는 있지만 먼저 특별한 잉크가 필요합니다.\n\n머나먼 여명의 설원에는 올빼미야수들이 서식하고 있지요. 그들은 한때 순결한 종족이었지만 이제는 검은속삭임 협곡에서 흘러나오는 마력에 미쳐 광란 상태로 설원을 떠돌고 있습니다.\n\n양피지에 쓸 잉크로 녀석들의 피가 필요하니 가서 그들의 피를 가져오십시오.", progress = "광란에 휩싸인 올빼미 야수를 본 적 있습니까? 그 생물들의 마법은 강력하고 그 마법은 녀석들의 고통 받는 육체를 흐르는 피에 응축되고 있지요.", completion = "아, 아주 좋습니다. 이 피를 정제해서 내가 약속했던, 양피지에 쓸 잉크를 만들도록 하지요. 그리고 나중에 내가 쓸 것도 조금 남겨 둬야 할 것 같군요. 그 맛이 아주 기막히다고 들었는데...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7564] = {title = "와일드아이즈", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 피가 담긴 상자를 가져가야 합니다.", description = "내 하수인인 고르지키라고 실력있는 연금술사가 저기 있습니다. 아마 그 친구가 양피지에 쓸 잉크를 준비해 줄 수 있을 겁니다. 그대가 수집한 피를 모아 두었으니 고르지키에게 가져가면 녀석이 작업을 시작할 수 있을 겁니다.", progress = "내게 뭘 가져온 거지? 혹시 크고 즙 많은 거미 아닌가? 아니면 바퀴벌레? 아직 살아 있다면 좋겠는데... 녀석들을 살아 있는 상태로 바로 요리할 때의 그 맛을 정말 끝내 주거든.", completion = "아, 피로군. 그럼 틀림없이 모르줄님이 보내신 거겠군. 저분은 피를 워낙 좋아하시고 피가 흘러내리는 걸 보는 걸 좋아하시지. 그렇지만 난 개인적으로 작은 쥐 종류의 생물 속에 흐르고 있는 피를 더 좋아하지. 그래야 피가 따뜻하니까...\n\n이건 아주 강력한 피로군. 모르줄님이 공포마를 소환해 낼 양피지를 또 만드실 건가 보군! 정말 재미있겠는걸!\n\n그게 사실이고 그 의식을 자네가 치를 거라면... 피 말고도 훨씬 더 많은 것들이 필요할 거야, 친구.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7581] = {title = "감옥벽의 재료", objective = "페랄라스에 있는 혈투의 전장으로 간 다음 굽이나무 지구에 서식하는 야생혈족 사티르로부터 사티르의 피 15개를 회수한 후 타락의 흉터에 있는 다이오에게 돌아가야 합니다.", description = "파멸의수호병을 가둘 감옥의 재료는 하급 악마들에게서 찾아야만 하오.\n\n아마 혈투의 전장을 차지한 야생혈족 사타르의 피가 좋을 거요. 응고된 피가 헤더린 조각들을 결합시키고 수정 감옥을 단단하게 만들어 줄 것이오.", progress = "야생혈족 사티로스의 피여야만 하오.", completion = "아, 모아 오느라 수고가 많았소이다. 이 피로 파멸의수호병의 마법 방어력을 무력화시킬 수 있을 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7582] = {title = "감옥의 외벽", objective = "여명의 설원에 있는 검은속삭임 협곡에서 서식하는 헤더린의 악마들로부터 헤더린의 눈물 5개를 빼앗아야 합니다. 임무를 완수하면 타락의 흉터에 있는 다이오에게 돌아가십시오.", description = "하이잘 산의 구릉을 점령한 헤더린 악마들은 강력한 마의 독을 분비하는데, 그 독은 시간이 지나면 딱딱해져서 마법에 내성을 갖는 수정이 된다오. 바로 이 수정을 헤더린의 눈물이라고 부르지.\n\n이 수정으로 감옥의 벽을 만들면 파멸의수호병이 아무리 용을 쓴다 해도 부서지지 않을 거요.\n\n여명의 설원에 있는 검은속삭임 협곡으로 가서 그 눈물을 구해 오시오.", progress = "헤더린들이 그 귀한 보석을 순순히 내주지는 않을 거요.", completion = "이제 야생혈족 사티로스의 피로 이 수정들을 붙이기만 하면 감옥은 모두 준비된 것이오이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7583] = {title = "감옥에 가두기", objective = "타락의 흉터에서 파멸의수호병을 찾아내십시오.\n\n빛나는 수정 감옥을 파멸의수호병에게 사용해야 합니다. 악마는 잡히지 않으려고 맹렬하게 공격할 테니 정신을 바짝 차리십시오.\n\n성공하면 사로잡은 파멸의수호병을 타락의 흉터에 있는 다이오에게 데려가야 합니다.", description = "감옥은 준비가 되었소. 이제 이 임무에서 가장 어려운 부분만 남았소이다.\n\n타락의 흉터 안에서 파멸의수호병을 찾아 이 수정 감옥에 가둬야 하오.\n\n조심하시오! 이 수호병은 교활하고 치명적인 적이라 가두려고 의식을 행하려는 즉시 당신을 죽이려고 덤벼들 거요. 사로잡히지 않으려고 아주 거칠게 저항하겠지.\n\n녀석은 당신만 처치하려고 덤벼들 테니 당신을 지켜줄 만한 동료를 데리고 가는 것이 좋을 것이오.", progress = "그래, 어찌 됐소?", completion = "내가 부탁한 대로 했으니 이제 당신에게 이 악마를 소환하고 지배하는 방법을 알려주어도 될 것 같군.", rewards = "다음과 같은 것들을 배웁니다:\n\n파멸의 의식\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n파멸의 의식\n\n다음과 같은 것들 또한 받습니다:\n\n희생의 고서"},
[7601] = {title = "나이비께서 명하사", objective = "악령의 숲에 있는 임프시와 대화하십시오.", description = "지옥불정령을 소환하는 비결을 알고 싶으면 먼저 크로쉬우스를 처치하고 불타버린 그의 잔해에서 지옥핵을 가져 와야 하지. 그게 말처럼 쉬운 일은 아니겠지만... 크로쉬우스는 완전히 타버렸을 테니 잔해에 다시 불을 지펴 잿더미가 그를 다시 살려야 하거든. 그렇게 하려면 다른 악마적 존재로부터 어떤 재료를 모아야 해.\n\n저기 내 부하 임프시가 더 자세히 가르쳐줄 거야.", progress = nil, completion = "맙소사! 또야?", rewards = nil},
[7602] = {title = "완전무결한 지옥의 정수", objective = "악령의 숲에 있는 임프시가 이 세계의 각기 다른 세 개의 지역에서 완전무결한 지옥의 정수 3개를 가져와 달라고 부탁했습니다.\n\n아즈샤라에는 레가쉬 사티로스들, 자에데나르에는 자에데나르 부대원들, 그리고 저주받은 땅에서는 지옥군단병 보초들이 각기 그 지역의 완전무결한 지옥의 정수를 갖고 있습니다.\n\n완전무결한 지옥의 정수 3개를 다 모은 다음에는 악령의 숲에 있는 임프시에게 돌아가야 합니다.", description = "크로쉬우스를 되살리려면 지옥의 불꽃이 필요해요. 제가 만들 수 있는데 재료가 좀 필요해요.\n\n이 세계에 있는 세 개의 지역을 여행하고 완전무결한 지옥의 정수를 갖고 오세요.\n\n아즈샤라의 레가쉬 사티로스들이 첫 번째 것을, 자에데나르에 있는 자에데나르 부대원들이 두 번째 것을, 마지막 것은 저주받은 땅의 지옥군단병 보초들이 갖고 있어요.\n\n이 세 가지 정수를 모아 오면 크로쉬우스를 되살릴 수 있는 지옥의 불꽃을 만들어 드리겠어요.", progress = "사실 나이비는 미치광이랍니다. 쉿! 아무한테도 말하지 마세요.", completion = "조금만 기다리세요. 금방 이 정수들을 결합해 지옥의 불꽃으로 만들어 드릴 테니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7603] = {title = "크로쉬우스의 지옥핵", objective = "악령의 숲에 있는 불벼락 골짜기를 수색해 크로쉬우스의 잔해를 찾아야 합니다. 찾으면 부근에서 지옥의 불꽃을 사용해 크로쉬우스를 되살리십시오. 크로쉬우스가 깨어나면 놈을 쓰러뜨린 후 크로쉬우스의 지옥핵을 꺼내야 합니다.\n\n크로쉬우스의 지옥핵을 악령의 숲에 있는 전지전능한 나이비에게 가져다주십시오.", description = "북동쪽에 있는 불벼락 골짜기로 가면 어딘가에 쓰러져 있는 크로쉬우스가 보일 거예요. 이 지옥의 불꽃을 가지고 가서 그의 잔해에 불씨를 지피세요. 그러면 지옥불정령이 되살아날 겁니다.\n\n분명 녀석은 일어나자마자 당신과 친구들을 모조리 죽이려 들 거예요. 그래서 말인데, 가능한 한 친구들을 많이 데리고 가는 게 좋을 거예요.\n\n그리고 만에 하나 기적이라도 일어나 당신이 크로쉬우스를 처치하게 되는 날에는 녀석의 지옥핵을 나이비에게 가져다주세요.", progress = "길이라도 잃었나?", completion = "그럼, 약속은 약속이지! 자, 내가 최고의 소환 마법을 가르쳐주도록 하겠네! 자, 얼른 받아 적으라고... 난 바쁜 몸이니까!", rewards = "다음과 같은 것들을 배웁니다:\n\n불지옥\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n불지옥\n\n다음과 같은 것들 또한 받습니다:\n\n푸른 불길의 결정"},
[7604] = {title = "대장조합 계약서", objective = "설퍼론 도면을 받으려면 설퍼론 주괴와 토륨 대장조합 계약서를 로크토스 다크바게이너에게 가져가야 합니다.", description = "이하 서명인은 이에 토륨 대장조합(이하 토대 조합)에 배달되는 설퍼론 주괴가 모조품이 아닌 진품임을 선언하고, 또한 설퍼라스의 제작, 제조, 주조, 수색, 판매, 식음을 시도하다 발생할 수 있는 모든 손해에 대해서 토대 조합의 책임 또는 잘못이 아님을 알립니다.\n\n본 계약에 서명하는 것은 여기 나열된 모든 조항에 동의한다는 것을 의미합니다.\n\n_________________\n\n서명다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n도면: 설퍼론 망치"},
[7621] = {title = "경고", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7622] = {title = "빛과 어둠의 균형", objective = "15명이 살해 당하기 전에 인부 50명을 구해야 합니다. 이 임무를 완수하면 에리스 헤븐파이어와 대화하십시오.\n\n살해 당한 농부의 수를 보려면 죽음의 말뚝을 보십시오.", description = "그대는 내가 해낼 수 없었던 일을 해내야 해요. 스트라솔름에서 탈출하려다 죽임을 당한 인부들을 구해야 합니다.\n\n모두들 빛을 향해 나아갈 것이니, 그대가 그들의 생존을 지켜야 해요. 너무 많은 이들이 쓰러지면 우리들의 저주 받은 존재는 지속되고, 그대는 실패한 것이 됩니다.\n\n그대가 터득한 모든 기술과 주문, 마법에 대한 시험을 받게 될 겁니다. 빛의 가호가 함께하기를.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n놀드랏실의 파편"},
[7623] = {title = "군주 베인할로우", objective = "불타는 평원에 있는 고르지키에게서 어둠의 물약을 구입해야 합니다.\n\n이 물약을 사용하여 자에데나르로 가서 군주 베인할로우와 대화하십시오.", description = "모르줄님이 자네가 소로스로 가는 차원의 문을 열고 싶어한다고 하시더군. 그곳으로 통하는 차원의 문을 열려면 소로시안 별가루가 필요할 거야. 그게 웬만해서는 아제로스에서 찾을 수 없는 물건이거든!\n\n그걸 갖고 있을 만한 이가 딱 한 명 있긴 한데, 바로 어둠의 의회가 있는 자에데나르의 베인할로우 군주라네!\n\n하지만 자에데나르로 가려면 어둠의 의회의 사악한 기운을 뒤집어써야 하는데, 그렇게 하려면 내 어둠의 물약이 필요하거든. 그건 돈을 내고 사야지...", progress = nil, completion = "비록 내 인내심이 수천 년에 걸친 것이라 하나 그렇다 하여 내가 네게 긴 시간을 내어줄 것이라 생각지는 말아라.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7624] = {title = "배신자 울라텍", objective = "울라텍과 맞서 싸운 후 자에데나르에 있는 베인할로우 군주에게 배신자의 증거를 가져가야 합니다.", description = "네게 은혜를 베풀어 주기를 원한다면 날 위해 처치해 줘야 할 녀석이 있다.\n\n내 하인 울라텍은 내 앞에서는 역겨울 정도로 굽실거리면서 뒷전에서는 소로스의 헬누라스 군주와 음모를 꾸미고 있느니라. 헬누라스는 이곳에서 내 권력을 뒤엎으려 하고 있고 울라텍이 바로 그 첩자인 것이지...\n\n네가 나의 경쟁 상대가 아니라 날 섬기는 자라는 것을 입증해 보이도록 하라. 서쪽에 있는 어둠의 요새로 가서 울라텍의 구역에서 그를 찾도록 해라. 내가 놈의 비밀을 알고 있음을 녀석에게 알리고 녀석이 공포에 떠는 것을 지켜본 후, 그 배신자를 처치하고 그 증거를 내게 가져와야 할 것이다!", progress = "배신의 맛이란 처음엔 아주 달콤하지만 결국엔 쓰디쓴 최후를 불러오지! 울라텍 녀석도 이 사실을 똑똑히 알고 저 세상으로 가길 바랄 뿐이다.", completion = "아, 아주 훌륭하군! 이 증거를 소중히 간직하도록 하겠다! 흠, 한 일주일 정도 보관할 수 있을까? 다른 배신자가 있다면 그 증거도 모두 모아서 옆에 두면 좋겠구나...\n\n&lt;class&gt;|1이여;여, 네가 날 섬겼으니 너에 대한 인내심이 조금 늘어났다. 아주 조금이지만!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7625] = {title = "소로시안 별가루", objective = "우르단에게서 소로시안 별가루를 구입한 후, 불타는 평원에 있는 고르지키 와일드아이즈에게 가져가야 합니다.", description = "그래, 소로시안 별가루 때문에 날 찾아온 것이란 말이지? 내 경쟁자 헬누라스의 영토 소로스로 통하는 차원의 문을 열고 싶다고? 녀석이 애지중지하는 공포마라도 한 마리 훔칠 생각인겐가?\n\n좋다. 내 신하 우르단이 소로시안 별가루를 갖고 있으니 녀석에게서 얻을 수 있을 것이다... 그 값을 치를 수 있다면 말이지.", progress = "자에데나르에는 다녀왔나? 베인할로우 군주에게서 별가루를 얻어 왔느냔 말이야.", completion = "가져왔군! 이걸 자네가 얻어 왔다니 믿기 힘든걸! 그 공포의 군주와 큰 거래를 했든가 아니면 아주 큰돈을 지불한 모양이군. 아니면 양쪽 다든가!\n\n곧 모르줄님께 잉크를 가져갈 수 있을 걸세. 그러면 마침내 상형 문자 양피지를 만들어 소로스로 통하는 차원의 문을 열고 그 유명한 공포마를 한 마리 끌어내 올 수 있겠지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7626] = {title = "데스무라의 종", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 암흑 강화의 비약 10개를 가져가야 합니다.", description = "이미 죽은 흑마법사인 데스무라 다크아이즈의 이름을 딴 데스무라의 종은 대소환진을 만드는데 필요한 세 가지 도구 중 하나입니다. 물레와 양초가 제대로 조화를 이루면 이 물건들에서 엄청난 양의 마법력이 뿜어져 나오게 되지요.\n\n내 하수인인 고르지키가 그런 종을 만들 줄 알지만, 그렇게 하려면 먼저 암흑 강화의 비약이 많이 필요합니다. 연금술을 배운 친구에게 그 비약을 구해 고르지키에게 가져가도록 하십시오.", progress = "비약은 가져왔나? 데스무라의 종이 필요하다고 모르줄님이 그러시던데, 그 종 하나를 만드는 데는 상당한 암흑의 힘이 필요하다고!", completion = "좋았어! 이 비약들을 구하는 게 꽤 힘들었지? 때로는 연금술사들이 자신이 만든 물건에 대해서 아주 인색할 때도 있거든...\n\n내가 종을 만들어 자네가 의식을 치를 준비가 끝날 때까지 보관하고 있도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7627] = {title = "어둠의 물레", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 눈부신 큰 결정 6개와 검은무쇠 광석 25개를 가져가야 합니다.", description = "어둠의 물레에는 대소환진에 필요한 극도의 힘이 깃들어 있어 물레가 그 힘을 조종합니다. 마법부여사 친구에게서 눈부신 큰 결정을, 그리고 전문 광부 친구에게서 검은무쇠 광석을 구하면 고르지키가 그 물레를 만들어줄 수 있을 겁니다.\n\n이 재료들을 모아 고르지키에게 가져가도록 하십시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7628] = {title = "심판의 양초", objective = "불타는 평원에 있는 고르지키 와일드아이즈에게 검은용 비늘 35개를 가져가야 합니다.", description = "심판의 양초는 불을 비축하고 있다가 의식을 방해하려는 자가 나타나면 그를 공격하게 되지요. 그대가 대소환진을 만들 때 양초가 켜져 있으면 의식을 방해하려는 악마들이 그 불길에 타 버리게 될 겁니다!\n\n그 불을 억제하는 건 쉬운 일이 아닐 뿐 아니라, 이를 위해서는 검은용 비늘에 깃든 정수도 필요합니다. 무두질이 가능한 친구에게 그 비늘들을 얻어서 고르지키 와일드아이즈에게 가져가도록 하십시오.", progress = "용 비늘은 가져 왔나? 그게 마련될 때까지는 양초를 만들지 않을 거야... 자칫하면 야영지 전체를 날려 버릴 수도 있거든!", completion = "아, 아주 좋아. 양초의 불을 억제하려면 이것들이 필요할 거야. 이제 비늘이 생겼으니 양초를 만들어 자네가 대소환진 의식을 시작할 준비가 될 때까지 내가 지니고 있도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7629] = {title = "임프 배달", objective = "단지 안에 든 임프를 스칼로맨스에 있는 연금술 실험대로 가져가야 합니다. 양피지가 완성되면 단지를 고르지키 와일드아이즈에게 되돌려 주십시오.", description = "모르줄님의 양피지를 만드는 데 필요한 한 가지 절차가 더 있네. 바로 종이와 소로시안 별가루를 섞는 일인데... 여기서는 장비가 없어서 할 수가 없단 말이야!\n\n하지만 필요한 장비를 모두 갖춘 연금술 실험대가 있긴 하지. 역병지대의 카엘 다로우의 섬에 위치한 스칼로맨스에 있다네.\n\n나는 거기까지 갈 수 없으니 이 단지를 받게. 이 안에는 머리가 꽤 좋은 임프가 한 마리 들어 있는데, 연금술 실험대에서 풀어 주면 알아서 양피지를 만들어 낼 거야.", progress = "스칼로맨스에는 갔다 왔나? 그 임프가 별가루로 양피지를 만들어 내던가?", completion = "아, 좋아. 지비가 양피지를 만들었군. 스칼로맨스는 어떻던가? 꽤 매력적인 곳이지 않아? 그리고 그곳에 있는 벌레들... 아주 맛깔스럽다고들 하더군!\n\n수고했고 단지를 돌려줘서 고맙네. 난 오랫동안 이 단지를 지니고 있었지... 게다가 절대로 파는 물건이 아니거든!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7630] = {title = "아케이나이트", objective = "불타는 평원에 있는 고르지키에게 아케이나이트 주괴 3개를 가져가야 합니다.", description = "종, 물레, 그리고 양초를 모두 만들었으니 검은 자철광을 만들어야겠군. 자네의 의식이 진행되는 동안, 의식이 실패하게 된다면 다음 의식을 진행할 물건들을 원상태로 유지하기 위해서 자철광이 필요하게 될 걸세.\n\n자철광을 만들려면 말이야, 아케이나이트가 필요하네. 자네 좀 가지고 있나? 만약 없다면... 연금술사 친구한테서 하나 얻어야 할 것이야.\n\n아케이나이트를 구하거든 내게 다시 오게. 그러면 검은 자철광을 만들어 주지.", progress = "아케이나이트는 가져왔나? 아케이나이트만 있으면 자네에게 검은 자철광을 만들어 줄 수 있지.", completion = "구했군! 잘했어! 이제 자철광을 만들 수 있겠군. 마침내 자네가 대소환진을 만들기 위한 의식 준비가 되면, 의식이 실패하지 않게 하기 위해서 자철광을 필요로 하게 될 거야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7631] = {title = "소로스의 공포마", objective = "모르줄의 지시서를 잘 읽으십시오. 소로시안 공포마를 소환해 물리친 후 그 영혼을 결속시켜야 합니다.\n\n제공된 아이템: \n", description = "준비는 모두 마쳤군요. 이제 그대가 대소환진을 만드는 의식을 치르고 난 후, 소로스로 통하는 차원의 문을 열기 위해서... 소로시안 별가루를 입힌 양피지를 사용하십시오.\n\n의식에 대한 지침은 두루마리에 적어 놓았습니다. 성공하길 바란다면 각 단계를 정확히 행해야 하니 자세히 읽도록 하십시오.\n\n행운을 빌겠습니다. 그대 적들의 영혼이 그대의 영혼의 주머니로 재빨리 빨려들어가기를...", progress = nil, completion = "소로시안 공포마의 영혼을 물리쳤습니다. 공포마의 영혼에 분노가 요동치고 있지만 그 영혼이 당신의 소유가 된 것을 알 수 있습니다.\n\n영혼이 당신의 머릿속에 암흑 마법을 속삭이며 공포마 소환에 대한 지식을 심어 줍니다.", rewards = "다음과 같은 것들을 배웁니다:\n\n공포마 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n공포마 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7632] = {title = "고대의 잎사귀", objective = "단단한 고대의 잎사귀의 주인을 찾아야 합니다. 행운을 빕니다, <name>. 세상은 아주 넓으니까요.", description = "이 잎사귀의 표피는 밝은 녹색 광채를 띠고 있습니다. 표면에는 주름이 매우 많고 잎맥이 몇 개 드러나 있습니다.\n\n이 잎사귀는 어떤 고대의 강력한 존재에게서 나온 것 같습니다.\n\n잎사귀의 원래 주인을 찾아가 보는 것이 좋지 않을까요?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7633] = {title = "고대의 잎사귀", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7634] = {title = "힘줄 감긴 고대의 잎주머니", objective = "고대정령 하스타트가 다 자란 푸른용 힘줄을 가져다 달라고 부탁했습니다. 이것을 찾으면 악령의 숲에 있는 하스타트에게 가져가십시오.", description = "어서 오라, <class>|1이여;여;. 나는 지식의 고대정령 하스타트... 아주 오래전에 사라진 지식을 갖고 있느니라.\n\n제대로 묶을 줄만 있으면 내 잎사귀로 1만 년에 한번이나 나올까 말까 한 훌륭한 화살통을 만들 수 있다. 고대정령의 활과 함께 사용하면 어마어마한 힘을 얻을 수 있지.\n\n다 성장한 푸른용의 힘줄을 가지고 이곳으로 돌아오면 화살통을 완성하여 그대에게 주리라.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n힘줄 감긴 고대의 잎주머니"},
[7635] = {title = "최고의 활시위", objective = "고대정령 스토마가 다 자란 검은용 힘줄을 가져다 달라고 부탁했습니다. 이것을 찾으면 악령의 숲에 있는 스토마에게 가져가십시오.", description = "고대정령의 활을 완성하는 데 필요한 지팡이는 바르투스가 줄 수 있지만 활시위에 마법을 부여할 수 있는 건 나뿐이니라.\n\n아주 간단한 일이다. 다 자란 검은용 한 마리를 처치하고 그 뼈에 붙어 있는 힘줄을 가져오기만 하면 되니까. 그 힘줄을 내게 가져오면 마법을 부여해 불멸에 가까운 활시위로 만들어 주리라.", progress = "검은용 한 마리를 찾아 처치하는 것쯤이야 그대에게는 식은 죽 먹기에 불과하겠지만, 잡담이나 늘어놓으며 시간을 낭비하지 말도록.", completion = "아주 사악하기 그지없는 용이었나 보군. 이 힘줄에서 지독하게 사악한 향기가 뿜어져 나오고 있어.\n\n내가 이 살에 묻은 때를 씻어내고 마법을 부여하는 동안 잠시 기다리도록 하라.", rewards = "다음과 같은 것들을 받습니다:\n\n마력 깃든 검은용 힘줄"},
[7636] = {title = "고대정령의 지팡이", objective = "타락한 악령의 4인조를 찾아 처치해야 합니다.\n\n매혹의 시몬\n\n광기의 클린프랑\n\n학살자 솔레노르\n\n파멸의 인도자 아토리우스\n\n위 넷의 혼을 갈무리하여 악령의 숲에 있는 고대정령 바르투스에게 돌아가십시오.\n\n이들의 위치에 대한 단서는 바르투스가 주는 돌껍질을 참조하십시오.\n\n이 임무는 반드시 혼자서 완수해야 합니다.", description = "아직도 이 세계에는 불타는 군단이 활동하고 있다. 놈들이 나타날 때 녀석들의 손에 닿는 것은 모두 부패하여 자연이 시들고 흐느끼느니라.\n\n<name>, 그 타락하고 부패한 놈들을 찾아 처치하도록! 미리 경고하겠다. 그대가 홀로 맞서지 않고 친구들과 힘을 합쳐 달려들면 녀석들이 도망칠 것이다. 그대가 홀로 맞선다면 녀석들이 단박에 달려들어 그대를 처치하려 들 것이다. 그 오만하고 비겁한 녀석들의 머릿속에 고통이 무엇인지 가르쳐 주어라.\n\n자, 나의 돌껍질 하나를 떼어내 주겠노라. 여기 새겨진 글이 그대를 적에게 인도할 것이다. 모두 처치하고 그 증거를 가지고 나에게 돌아오라.", progress = "그들의 겉모습에 속아서는 안 될 것이다!", completion = "&lt;name&gt;, 그대는 아주 큰일을 해 주었다! 자, 이 지팡이를 받아 스토마가 만들어 줄 수 있는 활시위와 결합하도록 하라. 그러면 온 세상을 호령할 최고의 무기가 탄생할 것이니라.", rewards = "다음과 같은 것들을 받습니다:\n\n고대 룬문자가 새겨진 지팡이"},
[7637] = {title = "희생의 중요성", objective = "아이언포지에 가서 대사제 로한의 퇴마 향로를 가져와야 합니다. 퇴마 향로를 얻으려면 150골드를 기부해야 합니다.", description = "이 일을 맡으려면 희생 정신과 판단력이 충분하다는 것을 증명해야 한다네. 특히 희생정신이 강조되지.\n\n대사제이신 로한님의 퇴마 향로를 가지고 온다면 일을 맡기겠네. 비록 정당하고 옳은 일에 퇴마 향로를 사용하려는 것이라 해도 충분한 보상을 치러야만 한다네.\n\n아이언포지로 가서 대사제님과 대화를 나누어 보게. 돈을 넉넉하게 지불한다면 자네의 희생정신을 충분히 증명할 수 있을 것이야.\n\n서두르게, <name>|1이여;여. 시간은 중요한 것이야.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[7638] = {title = "그레이슨 섀도브레이커 경", objective = "스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경과 대화해야 합니다.", description = "자네가 지금까지 무엇을 얻기 위해 기다려 왔는지 알고 있네, <class>|1이여;여;. 이제 어떻게 하면 그것을 얻을 수 있는지 알려 주겠네.\n\n여기 스톰윈드 빛의 대성당에 계시는 그레이슨 섀도브레이커 경과 대화를 나누어 보게. 성기사에게 가장 어울리는 최고의 군마는 어떤 녀석인지, 그 녀석을 얻으려면 어떻게 해야 하는지 알려주실 것일세.\n\n좋은 결과 있기를 빌겠네, 고귀한 <형제/자매여>. 정의를 위해!", progress = nil, completion = "만나서 반갑네. 자네가 군마를 얻기 위해 기다려 왔다는 사실을 알고 있네. 이제 때가 되었어.\n\n물론 여러 가지 방법으로 자네를 시험하게 될 것이네. 하지만 가장 중요한 것은 자네에게 닥쳐올 많은 난관을 극복하려는 적극적인 자세라네. 이번 시험은 훈련과는 차원이 다르네. 다행히 자네 실력으로 봐서 별다른 교육은 필요 없겠군. 자네는 지금까지 악마를 상대로 싸워오지 않았나? 그 악마의 손에서 자네의 동료가 될 친구를 구해오게.\n\n이제 자네 차례라네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7639] = {title = "희생과 심판", objective = "퇴마 향로를 가지고 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다.", description = "자, 이 향로를 받으십시오. 이것은 제가 악령 퇴치에 사용하던 것으로 <형제/자매>가 앞으로 겪게 될 험난한 여정에도 많은 도움이 될 것입니다. 축복을 빌겠습니다.\n\n이제 스톰윈드에 있는 그레이슨 섀도브레이커 경에게 돌아가십시오. <형제/자매>의 임무는 아직 끝나지 않았습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7640] = {title = "테러데일 퇴마", objective = "퇴마 향로를 사용하여 테러데일에 고통을 주는 영혼을 몰아내야 합니다. 25명의 테러데일 영혼을 해치운 다음 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다.", description = "동부 역병지대의 테러데일에 있는 오염된 땅에서 흙을 조금 떠서 향로에 넣었네. 이 향로를 사용하면 영적으로 동요하고 있는 지역을 찾을 수 있을 것이네. 녹색 오라를 찾아야 하네. 녹색 오라는 영혼의 세계가 이 세계를 침범하면서 고통으로 물들이는 지역이라네. 녹색 오라를 찾으면 향로를 사용해서 악마의 영혼을 몰아내도록 하게.\n\n충분한 숫자의 영혼을 몰아내게 되면 다음 단계를 진행할 수 있을 걸세.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7641] = {title = "그리만트 엘모어의 마갑", objective = "스톰윈드의 드워프 지구에 있는 그리만트 엘모어와 대화해야 합니다.", description = "적합한 마갑이 없다면 성기사의 군마라고 해도 단지 짐이나 나르는 동물일 뿐이라네. 자네의 군마에 사용할 마갑은 최고급 재료로 만들어야 할 뿐 아니라 주변 환경 때문에 영혼의 세계와 균형을 이루도록 세심한 배려가 필요하네.\n\n일단 마갑을 만들도록 하세나. 스톰윈드의 드워프 지구에 살고 있는 그리만트 엘모어야 말로 이 일에 딱 맞는 최고의 장인이지. 그의 작업비는 꽤 비싸겠지만 실력 하나는 최고라네. 드워프 지구로 가서 그와 대화를 나눠보게나.", progress = nil, completion = "만나서 반갑소! 당신이 찾아올 것이라고 그레이슨 섀도브레이커 경께서 전갈을 보내셨소. 필요하다는 마갑을 만들어 주는 거야 어렵지 않지만 가격도 그렇고 만드는 방법도 쉽지 않을 거요. 일단 먼저 흥정부터 합시다.\n\n나는 이 정도의 가격을 원하오. 그레이슨 섀도브레이커 경께서도 합리적인 가격이라 생각하실 것이오. 잘 알겠지만 아제로스에서 여기보다 마갑을 잘 만드는 곳은 없소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7642] = {title = "마갑 재료 수집", objective = "룬무늬 옷감 40개, 아케이나이트 주괴 6개, 아서스의 눈물 10개, 스트라솔름 성수 물병 5개 그리고 150골드를 스톰윈드의 드워프 지구에 있는 그리만트 엘모어에게 가져가야 합니다.", description = "마갑을 만들려면 안감에 사용할 룬무늬 옷감, 도금에 사용할 아케이나이트 주괴, 영적인 균형을 조절하기 위한 아서스의 눈물, 그리고 영혼을 불어넣기 위한 스트라솔름 성수 이렇게 네 종류의 재료가 필요하오. 정확하게 수고비까지 생각한다면 다섯 가지가 되나? 수고비는 손으로 직접 만든 안장, 등자 그리고 인건비까지 포함된 가격이오.\n\n재료와 수고비를 모두 가지고 오면 마갑을 만들어 주겠소. 지금부터 당신이 재료를 모아서 돌아올 때까지 당신에게 줄 선물을 준비하도록 하지.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[7643] = {title = "고대 준마의 영혼", objective = "사우스쇼어에 있는 메리데스 칼슨에게 말의 영혼에게 먹일 특별한 말 먹이를 얻어야 합니다.\n\n페랄라스에 있는 혈투의 전장 던전으로 가서 굽이나무 텐드리스를 무찔러야 합니다. 굽이나무 텐드리스를 무찌르고 고대 준마의 영혼이 풀려나면 특별한 말 먹이를 먹여 영혼을 진정시키십시오. 마지막으로 아케이나이트 마갑을 주면 영혼이 축복을 내릴 것입니다.", description = "자네의 마갑은 특별한 형태의 축복이 필요하다네. 특별한 영혼의 축복이 있어야 한다는 것일세. 혈투의 전장에 있는 고대 준마의 영혼이 바로 그러한 영혼이라 할 수 있지. 그 영혼은 지금 타락한 나무정령인 굽이나무 텐드리스에게 붙잡혀 있네. 이 사악한 악마를 해치우게나.\n\n단, 영혼을 풀어준다고 모두 해결되는 것은 아니라네. 축복을 받으려면 영혼을 진정시켜야만 하는데 그러기 위해서 특별한 말 먹이가 필요하네. 혈투의 전장으로 가기 전에 먼저 사우스쇼어에 있는 메리데스 칼슨을 찾아가 보게나... 그리고 더욱 투철한 희생정신이 필요할 것이네.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7644] = {title = "축복받은 아케이나이트 마갑", objective = "축복받은 아케이나이트 마갑을 가지고 스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다.", description = "마갑을 고대 준마의 영혼의 등에 올리자 마갑이 약간 커집니다. 짧은 순간 공기가 가득 차면서 강한 기운이 느껴집니다. 이때 말의 등에서 마갑이 사라지더니 소지품 속에 안전하게 보관됩니다.\n\n마갑이 축복받은 것 같습니다. 이제 그레이슨 섀도브레이커 경의 지시에 따라 마갑을 가지고 스톰윈드로 돌아가야 합니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7645] = {title = "맛좋은 만나 사료", objective = "맛좋은 만나빵 20개를 모아서 힐스브래드 구릉지의 사우스쇼어에 있는 메리데스 칼슨에게 가져가야 합니다. 맛좋은 만나빵은 맛좋은 만나 사료에 꼭 필요한 재료입니다. 맛좋은 만나빵은 은빛 여명회에서 독점적으로 파는 것으로 알려져 있습니다.\n\n메리데스 칼슨에게도 50골드를 주어야만 화가 난 마음을 진정시킬 수 있습니다.", description = "영혼에게 먹일 수 있는 특별한 말 먹이를 만들 수 있다고 은빛성기사단에게 말했더니 나를 미쳤다고 생각하더군요. 모두 내가 미쳤다고 생각하고 있어요! 모두에게 보여주겠어요!\n\n필요한 물건을 만들어 주겠어요. 성기사를 용사라고도 하던가요? 어쨌든 공짜는 아니에요. 내가 원하는 것은 특별한 빵이에요. 은빛 여명회에서만 파는 맛좋은 만나빵을 가지고 오세요. 그리고 한 가지 더 요구하자면 내가 겪은 정신적 피해에 대한 보상을 원해요!\n\n당신네 성기사들이 주절거리는 희생정신을 증명해 보세요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n맛좋은 만나 사료"},
[7646] = {title = "예언의 탐지기", objective = "스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져가야 합니다.", description = "이제 예언의 탐지기를 만들어야 하네. 이 일은 군마의 영혼을 되찾기 위한 출발점이기도 하지. 사실 자네의 탐지기가 거의 완성되었네. 테러데일에서 사용한 퇴마 향로가 예언의 탐지기의 촉매 역할을 하는 것일세. 장치에 필요한 틀은 내가 만들도록 함세.\n\n마지막으로 다이아몬드 두 개가 필요하네. 아제로스 다이아몬드와 온전한 검은 다이아몬드, 이 두 개의 다이아몬드를 나란히 놓아야 한다네. 이것들을 통해서 탐지기가 어둠을 뚫고 들어갈 수 있게 되는 것일세!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7647] = {title = "심판과 구원의 손길", objective = "스칼로맨스에 있는 대형 납골당 지하의 중심부로 가서 예언의 탐지기를 사용해야 합니다. 그러면 영혼들이 나타날 것이니 그들을 해치우십시오. 그들을 해치우면 죽음의 기사 다크리버가 나타날 것이니 그를 물리친 다음 군마의 영혼의 잃어버린 영혼을 되찾아야 합니다.\n\n구원된 군마의 영혼과 축복받은 아케이나이트 마갑을 다크리버 군마의 영혼에게 돌려줘야 합니다.", description = "이 가방을 받게. 그 안에는 임무를 위해 필요한 물건이 들어 있네.\n\n스칼로맨스의 대형 납골당 지하의 중심부로 가서 예언의 탐지기를 사용한 다음 저주받은 영혼들이 나타나면 해치우게. 자네의 문장을 잘 사용해서 임무를 완수하게. 그들은 자네 생각보다 강력한 힘을 가지고 있을 것이네. 영혼들을 해치우고 나면 죽음의 기사가 나타날 것이네. 그를 해치우고 군마의 영혼을 되찾아야 하네. 그래야만 말을 구해내고 자네의 새 말로 삼아 마갑을 입힐 수가 있네!\n\n행운을 빌겠네!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n군마 소환\n\n다음과 같은 것들을 받습니다:\n\n"},
[7648] = {title = "그리만트의 걸작품", objective = "스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아케이나이트 마갑을 가져가야 합니다.", description = "<자부심 가득한 얼굴로 이마의 땀을 닦는 그리만트 엘모어>\n\n자, 모두 완성됐소, 친구. 내 작품 중에서도 걸작에 속한다고 할 수 있지. 그레이슨 섀도브레이커 경께 만들어 드린 마갑과 비교해도 전혀 떨어지지 않는다오. 나를 믿고 최선을 다해 도와줘서 고맙소이다.\n\n그레이슨 섀도브레이커 경께서도 틀림없이 내 작품을 보고 싶어할 것이오. 내가 만들어 준 마갑을 그분께 가져가시오. 그분의 영예로운 일에 참여할 기회를 주셔서 고맙다는 말도 전해주시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7649] = {title = "마력깃든 토륨 갑옷 I", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n도면: 마력 깃든 토륨 흉갑"},
[7650] = {title = "마력깃든 토륨 갑옷 II", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n도면: 마력 깃든 토륨 다리보호구"},
[7651] = {title = "마력깃든 토륨 갑옷 III", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n도면: 마력 깃든 토륨 투구"},
[7652] = {title = "괜찮은 거래", objective = "잠깐만, 아주 괜찮은 거래가 하나 있는데 말이야.\n\n난 이 황제의 판금 갑옷 제작 기술을 원하는 사람들에게 처분할까 생각 중일세. 그 대가로 원하는 건 토륨 주괴뿐인데, 어떻게 생각하나?", description = nil, progress = nil, completion = nil, rewards = nil},
[7653] = {title = "황제의 판금 허리띠", objective = "허리띠 도면은 토륨 주괴 20개는 줘야 하네.", description = nil, progress = "허리띠 도면은 토륨 주괴 20개는 줘야 하네.", completion = "자네와 거래를 하게 되어 기쁘군.\n\n그런데 &lt;name&gt;, 그 아니꼽다는 듯한 표정은 짓지 않는 게 어떻겠나?", rewards = "다음과 같은 것들을 받습니다:\n\n도면: 황제의 판금 허리띠"},
[7654] = {title = "황제의 판금 장화", objective = "장화 도면은 토륨 주괴 40개만 줘. 그래, 40개! 아니 왜 눈물이 고였나... 손수건이라도 줘야하나?\n\n<소리 내어 웃는 데로타인>", description = nil, progress = "장화 도면은 토륨 주괴 40개만 줘. 그래, 40개! 아니 왜 눈물이 고였나... 손수건이라도 줘야하나?\n\n<소리 내어 웃는 데로타인>", completion = "자네와 거래를 하게 되어 기쁘군.\n\n그런데 &lt;name&gt;, 그 아니꼽다는 듯한 표정은 짓지 않는 게 어떻겠나?", rewards = "다음과 같은 것들을 받습니다:\n\n도면: 황제의 판금 장화"},
[7655] = {title = "황제의 판금 팔보호구", objective = "팔보호구 도면은 토륨 주괴 20개야.\n\n아니, 자네 어디 안 좋나? 얼굴이 온통 벌겋게 변했군.", description = nil, progress = "팔보호구 도면은 토륨 주괴 20개야.\n\n아니, 자네 어디 안 좋나? 얼굴이 온통 벌겋게 변했군.", completion = "자네와 거래를 하게 되어 기쁘군.\n\n그런데 &lt;name&gt;, 그 아니꼽다는 듯한 표정은 짓지 않는 게 어떻겠나?", rewards = "다음과 같은 것들을 받습니다:\n\n도면: 황제의 판금 팔보호구"},
