[7665] = {title = "붉은 랩터 교환", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n날쌘 푸른 랩터 호루라기날쌘 녹색 랩터 호루라기날쌘 주황색 랩터 호루라기"},
[7666] = {title = "다시 대형 납골당으로", objective = "자네 스칼로맨스로 다시 돌아가려는 것인가? 예언의 탐지기의 사용료는 이미 충분하게 치렀네. 자네 하나 더 가져가려는 것이 좋을 거야. 예언의 탐지기를 가지고 있으면 대형 납골당의 위험에 다시 한 번 도전할 수 있네.\n\n반드시 가지고 있게나. 자네는 자격이 충분하네.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n예언의 탐지기"},
[7667] = {title = "물질적인 부탁", objective = "오그리마, 지혜의 골짜기에 있는 사고른 크레스트스트라이더의 일을 도우려면 그에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져가야 합니다.", description = "급한 문제가 생겼소. 도와줄 거라 믿고 무슨 일인지 지금부터 설명하겠소이다.\n\n로데론의 스칼로맨스 깊은 곳에는 대형 납골당이라고 부르는 방이 있소. 난 그 등골까지 오싹해지는 방의 칠흑 같은 어둠을 뚫고 들어갈 예언의 탐지기를 완성해야 하오. 그러려면 두 개의 다이아몬드가 필요하지. 아제로스 다이아몬드와 온전한 검은 다이아몬드 말이오. 내가 알기로 그것들은 쉽게 구할 수 있는 물건이 절대 아니오. 내게 그렇게 귀한 걸 구할 뾰족한 방법이 있는 것도 아니고...\n\n<name>, 날 위해 다이아몬드를 좀 구해다주겠소?", progress = "대놓고 물질적인 부탁을 하려니 참 쑥스럽군. 하지만, 탐지기를 완성하려면 꼭 다이아몬드들이 필요하오. 행여 도와주지 못하겠다고 해도 괜찮소. 충분히 이해할 수 있으니까.", completion = "&lt;name&gt;, 당신의 호의는 절대 잊지 못할 거요. 정말 감사 드리오.\n\n이제 예언의 탐지기를 완성할 수 있겠군. 탐지기를 필요한 만큼 만들 수 있을 정도로 다이아몬드가 충분하오. 그러니... 이제부터는 이 탐지기 사용하는 것 좀 도와주겠소? 사실 이게 가장 중요한 과정이오. 확인 작업에 소홀했다가는 영혼의 세계에 돌이킬 수 없는 재앙을 불러일으킬 수도 있으니 말이오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7668] = {title = "다크리버의 위협", objective = "스칼로맨스에 있는 대형 납골당 지하의 중앙으로 가서 예언의 탐지기를 사용하십시오. 그러면 유령들이 나타날 것입니다. 그들을 해치우십시오. 그리고 곧이어 나타날 죽음의 기사 다크리버를 해치워야 합니다.\n\n그런 다음 그 증거로 오그리마, 지혜의 골짜기에 있는 사고른 크레스트스트라이더에게 다크리버의 머리카락을 가져가야 합니다.", description = "죽음의 기사 다크리버는 스칼로맨스에 있는 대형 납골당의 주인이오. 지금 그가 영혼의 세계를 넘보고 있소이다. 반드시 그를 막아야 해! 그러려면 탐지기가 꼭 필요할 거요.\n\n대형 납골당 지하의 중앙으로 가서 예언의 탐지기를 사용하면 다크리버의 부하들이 나올 거요. 그 유령들을 물리치면 다크리버 본인이 모습을 드러낼 테지. <name>, 그를 처치하고 그 증거를 가져다주시오! 그가 죽어야만 영혼의 세계가 입은 피해를 회복할 수 있소!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잠재력의 투구"},
[7669] = {title = "다시 대형 납골당으로...", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n예언의 탐지기"},
[7670] = {title = "그레이슨 섀도브레이커 경", objective = "스톰윈드의 대성당 광장에 있는 그레이슨 섀도브레이커 경과 대화해야 합니다.", description = "<name>, 당신이 지금까지 무엇을 얻기 위해 기다려 왔는지 알고 있소. 이제 어떻게 하면 그것을 얻을 수 있는지 알려 주겠소.\n\n스톰윈드의 대성당 광장에 있는 그레이슨 섀도브레이커 경과 대화를 나누어 보시오. 최고의 성기사에게 가장 어울리는 말이란 어떤 놈인지, 그놈을 얻으려면 어떻게 해야 하는지 알려줄 것이오.\n\n좋은 결과 있기를 빌겠소. 고귀한 빛을 수호하는 성기사의 이름으로!", progress = nil, completion = "만나서 반갑네, &lt;name&gt;. 말을 얻기 위해 기다려 왔다고 알고 있네. 이제 때가 되었어.\n\n하지만, 여러 가지 시험이 자네를 기다리고 있을 것이라네. 물론 가장 중요한 것은 수없이 닥쳐올 난관을 극복하려는 적극적인 자세지. 이것은 일반적인 훈련과는 차원이 달라. 다행히 자네 실력으로 봐서 별다른 교육은 필요 없겠군. 자네는 지금까지 악마를 상대로 싸워오지 않았나? 그 악마의 손에서 자네의 동료가 될 친구를 구해오게.\n\n이제 때가 됐군. 조심하게!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
