[7681] = {title = "Hunter test quest", objective = "Feed your pet, then talk to your questgiver.Cast feed pet on your pet.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "Cast feed pet on your pet.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7682] = {title = "Hunter test quest2", objective = "Feed your pet, then talk to your questgiver.Cast feed pet on your pet.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "Cast feed pet on your pet.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7701] = {title = "현상수배: 감독관 말토류스", objective = "이글거리는 협곡의 용광로에 있는 잿가루 채석장 깊은 곳에서 검은무쇠단 드워프 변절자인 감독관 말토류스를 찾아 처치하고, 이글거리는 협곡에 있는 감시대장 롤로 롱스트라이커에게 그의 머리카락을 증거로 가져가 보상을 받아야 합니다.", description = "고귀하신 감독관 오일피스트 님의 명에 따라, 토륨 대장조합의 요원이자 새로 고용된 용광로의 검은무쇠단 잿가루 채석장 일꾼들의 지휘관인 감독관 말토류스를 처치하고 그 증거를 가져오도록 하라.\n\n현상금에 대한 사항은 감시대장 롤로 롱스트라이커에게 문의하기 바란다.", progress = "바쁜 거 안 보이나? 무슨 *딸꾹* 일로 온 거지? *딸꾹*", completion = "이제 그 못난 얼굴을 또 볼 일은 절대 없겠군!\n\n그 더러운 놈이 이 세상에서 사라졌다니 속이 다 시원할 지경이야.\n\n자, 여기 현상금 받으라고 *딸꾹*, 친구!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n이글거리는 사슬 조끼그을린 가죽 튜닉\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7702] = {title = "수면 방해", objective = "용광로에 있는 잿가루 채석장 깊은 곳에 가면 검은무쇠 드워프들의 침소를 찾을 수 있습니다.\n\n이글거리는 협곡에 있는 에보니스 수트스모커에게 침소에서 훔친 검은무쇠 베개 20개를 가져가야 합니다.", description = "잿가루 채석장에서 작업하는 검은무쇠 녀석들에게 타격을 입히려면 가장 큰 피해를 줄 수 있는 곳을 찾아야겠죠.\n\n이건 잘 알려지지 않은 사실인데, 드워프들, 특히 검은무쇠 드워프들은 잠을 아주 많이 자야 한답니다!\n\n자, 그러면 하나 물어볼까요? 검은무쇠 드워프가 베개 없이 어떻게 잠을 잘 수 있을까요? 그렇죠, 못 자겠죠. 그렇기에 당신이 잿가루 채석장으로 몰래 들어가서 녀석들의 베개를 훔쳐 와야 하는 겁니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n적열의 로브"},
[7703] = {title = "고르독 일 마무리", objective = "권력의 고르독 건틀릿을 찾아 혈투의 전장에 있는 대장 크롬크러쉬에게 가져가야 합니다.\n\n크롬크러쉬의 \"옛날 얘기\"에 따르면 자칭 왕자라는 토르텔드린이라는 이름의 \"기분 나쁜\" 엘프가 고르독 왕에게서 빼앗아갔다고 합니다.", description = "이제 당신 새 왕이다, 토르텔드린이라고 하는 기분 나쁜 엘프에게서 소중한 고르독 유물 빼앗아줘! 이전 왕은 실패했고, 토르텔드린이 아주 오래 전 왕에게서 유물 훔쳐간 뒤로 다른 임금들 다 실패했다!\n\n그 유물은 권력의 고르독 건틀릿이라고 한다. 옛날 얘기에는 진짜 고르독 왕만이 갖고 올 수 있다고 한다. 옛날 얘기에는 기분 나쁜 엘프가 아직도 이 근처에 있다고 한다. 그 유물 찾으면 평생 왕이 끼고 있게 될 거다! 그래, 내가 보여준다!", progress = "하하. 못 찾았지, 왕? 옛날 얘기가 거짓말일지도 모른다... 기분 나쁜 엘프가 고르독 왕에게서 훔치다니 말도 안 돼!", completion = "우와... 당신 정말로 진짜 왕이다! 이 건틀릿은 평생 절대 못 볼 거라 생각했다! 음... 건틀릿에 모조가 남아있는 것 같지 않군... 기분 나쁜 엘프가 망치려고 했는지도 몰라. 그 녀석한테 실컷 비웃어주지!\n\n봐. 건틀릿에 새겨진 문장 옛날, 옛날, 예엣날 마법 문장이다. 고르독 일족보다 더 오래된 거라고 하던데. 고르독 왕으로서 딱 한 가지 계속해서 배우는 게 있다. 문장을 살려서 건틀릿에 힘을 되찾아주는 거지!\n\n내가 해줄게, 왕! 자, 이 건틀릿 중에 하나 가지고 영원히 우리의 왕 해!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n고르독의 손보호대고르독의 건틀릿고르독의 장갑고르독의 손장갑\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7704] = {title = "엄청나게 큰 베개!", objective = "이글거리는 협곡에 있는 에보니스 수트스모커에게 하녀 필라클렌처의 베개를 가져가야 합니다.", description = "이런, 이런, 이런... 이것 참 재미있는 일입니다. 하녀의 거대하고 화려한 베개가 이제 당신의 것이 되었습니다. 틀림없이 에보니스 수트스모커가 이 물건을 그 지저분한 작은 손에 넣고 싶어할 테니 이 베개를 가져가서 에보니스가 당신의 수고에 대해 어떤 제안을 하는지 봐야 할 거 같습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n에보니스의 낙하 방석"},
[7721] = {title = "변환을 위한 연료", objective = "페랄라스의 잊혀진 해안에 있는 바다 정령과 바다 물보라 정령에게서 물의 정령 핵 10개를 모아 부두 근처에 있는 조브린 팬대즐에게 가져가야 합니다.", description = "바보 같은 결정일지는 몰라도 잊혀진 해안에 머무르면서 기계공학 작업장을 운영한다 치면 저 성가신 정령들을 좀 손봐야 할 겁니다. 그놈들, 정령술을 남용한 대가를 치르게 될 겁니다!\n\n하지만 이 정령들은 제가 만든 형상축소기에 이상적인 천연 동력원이니 저나 제 밀정이라 할 수 있을 당신에게는 다행스러운 일이지요. 가서 녀석들을 처치하십시오! 하지만 녀석들을 처치하더라도 물의 정령 핵은 꼭 가져오셔야 해요!", progress = "정령 핵 사용에 대한 기술적인 세부 내용으로 당신을 지루하게 만들 수도 있겠지만, 그 대신 귀중한 돈과 상품을 제안하여 이 중요한 임무를 완수하는 데 흥미를 갖도록 해 보겠습니다. 근데, 정말 임무를 완수하긴 한 건가요?", completion = "훌륭하고도 훌륭하군요! 정령 핵이 이 정도 있으면 한동안 걱정 없겠습니다. 게다가 이제 해안에 출몰하는 정령의 수도 줄어들었고, 더 이상 세상에서 제일 안 좋은 장소에 작업장을 세웠다는 생각에 울며 잠들지 않아도 되겠군요.\n\n제 대신 수고해 주신 것 고맙습니다. 이렇게 크게 보상하면 제 주머니가 궁해지긴 합니다만, 당신이 이해하고 기뻐할 만한 감사의 표시를 해 드리죠. 바로 보상입니다!", rewards = "다음과 같은 것들을 받습니다:\n\n조브린의 방수모자"},
[7722] = {title = "불꽃 융해촉진제?", objective = "용광로의 잿가루 채석장 어딘가에 감독관 말토류스가 훔친 비밀조제법: 불꽃 융해촉진제가 있을 것입니다. 이 조제법을 찾아서 이글거리는 협곡에 있는 수석대장장이 버니네이트에게 가져가야 합니다.", description = "그 몹쓸 말토류스 녀석이 우리 일족을 떠나면서 온전한 신비한 수정보다 더 귀중한 걸 가져가 버렸네. 바로 우리 불꽃 융해촉진제 조제법이지! 녀석이 검은무쇠단에서 진급할 때 이루어진 거래의 일부로 그 제조법이 포함된 게 틀림없네.\n\n자네가 가서 우리의 비밀조제법을 가져오게. 분명히 잿가루 채석장 안 깊은 곳에 있는 말토류스 근처 어딘가에 그 제조법이 있을 거야.", progress = "조제법은 찾았나?", completion = "녀석의 얼굴이라도 걷어차 주지 그랬나. 라그나로스께서 다 아시는 일인데, 그 정도는 당해 마땅하지.\n\n이제 일을 제대로 할 수 있겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7723] = {title = "두꺼운 손가락의 슬픔", objective = "이글거리는 협곡의 용광로 주변을 돌아다니는 육중한 전투골렘 20마리를 처치하고 임무를 완수하면 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다.", description = "안타깝게도 바로 이 두꺼운 손가락 때문에 내 활약이 예전 같지 못하다네. 보다시피, 이곳의 기후에다 저기압까지 겹쳐서 내 손가락이 부어오르게 된 것이지. 꼭 무슨 거대한 텔사마 선지 소시지 같다니까...\n\n자네가 내가 하던 일을 대신 해 줘야겠는데 말이지... 먼저 해야 할 일은 이글거리는 협곡에 있는 육중한 전투골렘을 흠씬 두들겨 패주는 것일세. 자, 어서 가 보라고.", progress = nil, completion = "아주 괜찮은 젊은이로군그래. 수고를 해 줬으니 작은 선물을 하나 주도록 함세.", rewards = "다음과 같은 것들을 받습니다:\n\n잿가루 판금 건틀릿"},
[7724] = {title = "뒤꽁무니에서 불을 뿜는 거미", objective = "이글거리는 협곡의 고원과 용암 지대에서 서식하는 거대한 용암거미 20마리를 처치한 후, 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다.", description = "늘 이런 식이지. 이 늙은 한셀이 잠깐 쉬면서 내 인생을 회고해 보려고만 하면 위에서 다른 할 일이 떨어진단 말이지.\n\n이것 참! 이리 와 보게. 어서 이리 와 보라고...\n\n그러니까, 거대한 용암거미들이 무슨 소동을 벌이고 있다고 하는데, 오일피스트 말로는 녀석들이 뒤꽁무니 한 가운데에 있는... 뭐 어쨌든, 구멍에서 불을 뿜어 대며 어린 아이들을 놀래킨다는군.\n\n우리가 녀석들을 처치해야 할 모양이야. 아니지, 우리라기보다는 자네가 좀 처치해 주게.", progress = nil, completion = "&lt;재채기를 하는 한셀&gt;\n\n감기가 걸리려나 보군. 이놈의 날씨, 정말 추워 죽겠다니까!", rewards = "다음과 같은 것들을 받습니다:\n\n이글거리는 사슬 벨트"},
[7725] = {title = "잔류물 수집", objective = "페랄라스에서 눈에 띄는 아무 거인에게나 조브린의 형상축소기를 사용해 좀 더 다루기 쉬운 형태로 변환하십시오. 페랄라스의 잊혀진 해안 부두에 있는 조브린 팬대즐에게 이 변형된 거인들에게서 얻을 수 있는 축소화 잔류물 10개를 가져가야 합니다.", description = "이미 잔류물을 모아다 주긴 하셨지만... 저야 늘 잔류물이 더 필요하니, 이 재미있는 놀이를 한 번 더 해 보고 싶다면 얼마든지 그렇게 하십시오.\n\n보상금은 예전만큼 많이 드릴 수는 없지만, 제 말을 들을 수 있는 모든 고블린 친구들에게 당신이 해 주신 일에 대해 잘 얘기해 두도록 하겠습니다.\n\n제 고블린 친구들은 소문에 아주 민감하거든요.", progress = "아, 연구와 활용의 결실이 달콤하고 달콤한 잔류물의 형태로 맺어지는구나. 뭐, 그렇다고 연구 중에 제가 이 잔류물을 맛본다든가 하는 건 아니랍니다.\n\n그렇게 많이는 아니라고요.", completion = "또 다시 해내시다니... 상상 할 수 없을 만큼 대단하군요! 정말로 고맙습니다. 감사해요!\n\n평소보다 금액이 좀 적긴 할 테지만 고블린 왕국에서 당신이 세우신 공로에 대한 소문이 스팀휘들 무역회사 중심부 곳곳에 퍼지게 될 겁니다. 다른 일거리가 필요하면 언제든지 절 찾아오십시오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7726] = {title = "연료 재충전", objective = "페랄라스의 잊혀진 해안에 있는 바다 정령과 바다 물보라 정령에게서 물의 정령 핵 6개를 모아 부두 근처에 있는 조브린 팬대즐에게 가져가야 합니다.", description = "일거리가 더 필요하시다고요? 정령의 몸 안에 있는 찐득찐득한 물체를 채취하는 영웅적인 임무가 당신의 모험에 대한 갈증을 해소하기에는 부족했나 보군요. 어쩌면 같은 일을 반복하는 것은 당신의 그 밑도 끝도 없는 욕구를 채우려는 허망한 시도에 불과한 것이 아닐지...\n\n좋습니다. 감상적인 얘긴 이만하죠. 전 정말로 물의 정령 핵이 더 필요합니다. 여기에 작업장을 세우려고 안간힘을 쓰고 있는 형편이라 보상은 그리 크게 해 드리지 못하겠지만... 당신이 도와 주셨다는 소문을 반드시 널리 퍼뜨려 드리겠습니다. 제가 무역회사 친구들을 좀 아니까 믿으셔도 됩니다.", progress = "필요한 정령 핵은 다 모으셨나요?", completion = "최고로군요, 최고예요! 이런 일에 대한 보상으로 받는 금액치고는 좀 적을 테지만 스팀휘들 무역회사에 있는 제 동료들에게 확실히 얘기해 둘 테니 안심하십시오!\n\n다른 일거리가 필요하시면 절 찾아오세요. 전 항상 더 많은 정령 핵이나 그런 재료들을 필요로 하니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7727] = {title = "인센도사우루스라니 무슨...", objective = "용광로에 있는 잿가루 채석장 안의 용암 지대를 점령하고 있는 인센도사우루스 20마리를 처치한 후, 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다.", description = "발가락에 물집이 잡혔어, <class> 친구. 내 발 말이야. 발 꼴이 이래서야 어떻게 싸운단 말인가? 그러니 자네가 좀 도와 줘야겠네.\n\n잿가루 채석장 용암 지대로 원정대를 보내 탐험을 할 수 있도록 스크랜지와 버니네이트가 나에게 어떤 괴물을 처치하는 임무를 맡겼지. 무슨 인센도사우루스인가 하는 말도 안 되는 괴물들이 저 아래에서 온갖 문제를 일으키고 있다고 하는군. 어서 가서 인센도사우루스가 완전히 멸종될 때까지는 돌아오지 말게.", progress = nil, completion = "아이고, 발이야.\n\n수세미가 없으니 말이지...", rewards = "다음과 같은 것들을 받습니다:\n\n수세미"},
[7728] = {title = "도난품: 가열로 바람구멍 및 감시병의 망원경", objective = "이글거리는 협곡에 있는 작업반장 스크랜지에게 가열로 바람구멍과 감시병의 망원경을 찾아 가져가야 합니다.\n\n이 물건들에 대해 가지고 있는 유일한 정보는 다음과 같습니다.\n\n검은무쇠단 드워프들이 훔쳐간 것이 분명합니다.\n가열로 바람구멍은 대장장이들이 사용하는 대장 도구입니다.\n감시병의 망원경은 감시병들에게 값으로 따질 수 없을 만큼 중요한 감시 도구입니다.", description = "다음은 도난당한 물건이다.\n\n*가열로 바람구멍 1개\n*감시병의 망원경 1개\n\n이 도난당한 물건들을 찾아 되돌려 주는 자에게는 보상이 주어진다.\n\n토륨 대장조합은 이글거리는 협곡에 사는 비양심적이고 시기심이 가득한 검은무쇠단 드워프들이 이 물건들을 훔친 것이라 확신하고 있다.\n\n문제의 망원경은 감시병들에게 있어 아주 훌륭한 도구였고 바람구멍은 대체할 수 없을 만큼 뛰어난 대장 도구였다.\n\n분실된 물건을 찾으면 작업반장 스크랜지에게 가져와야 한다.", progress = "보상을 받으러 온 거라면 도난당한 물건들을 내게 주게나.", completion = "훌륭하군! 그럼 보상을 할 차례로군. 자, 여기 있네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n잿가루 판금 다리보호구적열의 장갑\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7729] = {title = "구인광고: 경쟁 선별", objective = "검은무쇠단 감독관 15명과 검은무쇠단 노예상인 15명을 처치하고 임무를 완수한 후, 이글거리는 협곡에 있는 작업반장 스크랜지에게 돌아가야 합니다.", description = "작업반장 스크랜지가 이글거리는 협곡에서 경쟁 선별하는 데 도움이 될 실력 있는 남녀 몇 명을 모집하고 있다.\n\n이 일에 관심이 있는 자들은 이글거리는 협곡으로 가서 눈에 띄는 검은무쇠단 감독관과 검은무쇠단 노예상인을 모조리 처치하도록 한다.\n\n검은무쇠단을 충분히 처치하고 그들의 피가 옷을 적시게 되면 작업반장 스크랜지에게 돌아가도록 한다. 피가 충분히 묻으면 자연히 알게 될 테니 얼마나 많이 묻어야 하는지 묻지 말 것.", progress = nil, completion = "7.2Kg! 옷에 묻은 피와 내장 무게 부문에서 신기록을 세운 것 같군. 축하하네, &lt;class&gt; 친구!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7730] = {title = "주크애쉬 출몰", objective = "페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 주크애쉬 등껍질 20개를 가져가야 합니다.", description = "우리가 간신히 수집한 정찰 보고에 의하면 놀들의 서식지 남쪽에 위치한 적은 곤충류인 듯하오. 솔직히 말해, 녀석들이 감정이 있는 놈들이냐 하는 것은 상관없소이다. 놀들이 우리에게 미친 듯이 달려들도록 만든다면 녀석들은 놀들만큼이나, 아니 어쩌면 그 이상으로 큰 위협이오.\n\n이 주크애쉬 곤충들이 서식하는 곳 깊숙이 쳐들어가시오. 고통의 구덩이라고 알려진 그곳에서 녀석들의 수를 줄이고 보고할 만한 게 있거든 내게 보고하도록 하시오. 녀석들을 처치한 증거로 주크애쉬 등껍질을 가져오면 되오.", progress = "사냥은 어떻게 돼가고 있소? 임무 성공을 보고하러 온 거요?", completion = "수고했소. 전면전을 벌이지 않고서는 주크애쉬의 광범위한 출몰을 막아낼 수 없겠지만, 제대로 된 전략을 생각해 낼 수 있도록 당신이 시간을 벌어 주었소이다.\n\n반드시 이 등껍질를 분석하도록 하겠소. 유감스럽게도 우리가 예상했던 것보다 훨씬 더 큰 문제가 되어 버린 이 주크애쉬 녀석들을 처치하기 전에 녀석들에 대해 속속들이 알아야 할 테니까 말이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7731] = {title = "채찍쐐기", objective = "고통의 구덩이에서 채찍쐐기를 물리치고 페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 분비선을 가져가야 합니다.", description = "우리 정찰병 중 한 명이 고통의 구덩이를 조사하다 그 뒤틀린 땅 위를 돌아다니는 거대한 곤충을 한 마리 목격했다는 보고가 있었소. 그 녀석은 다른 곤충들보다 훨씬 더 컸다고 하더군. 덩치만 더 큰 게 아니라 다른 곤충들이 가지고 있지 않은 어떤 오라를 분비하는 것 같소이다. 우린 녀석을 채찍쐐기라고 부르기로 했소.\n\n이 새로운 위협을 다루는 최선의 방법을 알아내기 위해서는 채찍쐐기의 내장 기관이 아주 귀중한 연구 재료가 될 거요. 녀석의 분비선을 잘라내 즉시 내게 가져와 주시오!", progress = "채찍쐐기를 처치하는 데 성공했소?", completion = "놀랍군, &lt;class&gt;... 아주 놀라워! 정말로 채찍쐐기가 녀석들 중 가장 강한 녀석 중 하나라면 이 녀석을 연구하는 것은 후에 아주 큰 도움이 될 거요. 그 연구의 혜택을 볼 수 있을 때까지 우리 모두가 살아남도록 하는 것은 이제 내 책임이외다.\n\n우리 야영지 전체가 감사의 표시로 주는 보상이니 부디 이걸 받아 두시오. 수고했소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7732] = {title = "주크애쉬 보고서", objective = "오그리마 골목길에 사는 질지빈 드럼로어에게 모자케 야영지 주크애쉬 보고서를 전달해야 합니다.", description = "주크애쉬 곤충들이 모자케 야영지에 가하는 위협에 아주 잘 대처해 주었소. 하지만 이 녀석들이 일으키고 있는 위협이 끝나려면 아직 멀었으니 호드를 대신해 당신에게 마지막 임무를 한 가지 더 맡기고 싶소.\n\n이 문서에는 그동안 우리가 이 주크애쉬 곤충들에 대해 수집해 온 모든 정보가 자세히 기록되어 있소. 이걸 오그리마 골목길에 있는 질지빈 드럼로어에게 전달해 주시오. 그는 이런 낯선 생물들에 대해서는 전문가이니 우리가 모아 온 정보로 뭔가 해낼 수 있기를 바라오이다.", progress = "어서 오게, 친구... 아주 급한 용무로 온 것 같은데. 내가 도와 줄 일이라도 있나?", completion = "아, 이게 오길 기다리고 있었지. 자네가 맞닥뜨린 이 생물들... 녀석들은 호드가 계속 무시하려고 하는 고대로부터의 위협이라네. 아도겐이 자네를 시켜 이걸 내게 전달하도록 한 건 아주 현명한 일이야.\n\n주크애쉬는 실리시드라고 하는 생물들과 매한가지일세. 어떤 이들은 녀석들을 그저 지각없는 성가신 존재 정도로 치부하겠지만, 내 확실히 말해두는데 녀석들은 얼라이언스가 소집할 수 있는 그 어느 것보다도 훨씬 더 심각한 위협이라네.\n\n자네가 생각이 있고 그만큼 강하다면, 이 위협을 알리는 데 자네 도움을 좀 받았으면 하네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n교묘의 반지에메랄드마루 어깨갑옷\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7733] = {title = "품질 향상", objective = "페랄라스의 페더문 요새에 있는 프랫 맥그루벤에게 무쇠설인 가죽 10개를 가져가야 합니다.", description = "믿어지지 않겠지만, 가죽을 모으기에 훨씬 더 나은 장소를 알고 있습니다! 페랄라스 북쪽 무쇠설인 소굴 깊숙한 곳에 또 다른 설인 무리가 살고 있지요. 이 녀석들은 당신이 예전에 상대했던 녀석들보다 훨씬 더 강한 녀석들입니다. 더 큰 도전을 원한다면 정신 바짝 차리는 게 좋을 겁니다!\n\n녀석들의 가죽 10개를 가져오면 아주 후하게 보상하도록 하죠. 가죽을 가지고 돌아오면 거래를 하도록 하겠습니다.", progress = "이 무쇠설인 가죽의 질이 원시설인 가죽 정도 된다면 토륨만큼이나 탄력이 좋을 겁니다!\n\n상상해 보십시오!", completion = "좋았어요, 좋았어! 아주 쓸 만하겠는 걸요. 척 보기만 해도 제대로 경화하기만 하면 훨씬 더 단단해질 거라는 걸 알겠군요.\n\n도와줘서 고맙습니다. 자, 받으세요. 제가 최근에 제작한 물건들 중에서 제일 좋은 놈으로 고른 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n프랫의 수제 튜닉"},
[7734] = {title = "품질 향상", objective = "페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 무쇠설인 가죽 10개를 가져가야 합니다.", description = "믿어지지 않겠지만, 가죽을 모으기에 더 나은 장소를 알고 있소! 페랄라스 북쪽 무쇠설인 소굴 깊숙한 곳에 또 다른 설인 무리가 살고 있소이다. 이 녀석들은 당신이 예전에 상대했던 녀석들보다 훨씬 더 강한 녀석들이오. 더 큰 도전이라면 빈틈없이 채비를 갖춰야 할 것이오!\n\n녀석들의 가죽 10개를 갖고 오면 아주 후하게 보상을 해 주겠소. 가죽을 가지고 돌아오면 거래를 하도록 하겠소.", progress = "이 무쇠설인 가죽의 질이 원시설인 것들 정도 된다면 토륨만큼이나 탄력이 좋을 거요!\n\n상상해 보시오!", completion = "좋았어, 좋았어! 아주 쓸 만하겠는 걸. 척 보기만 해도 제대로 경화하기만 하면 훨씬 더 단단해질 거라는 걸 알겠소.\n\n도와 줘서 다시 한번 감사하오. 자, 받으시오. 최근에 제작한 물건들 중에서 제일 좋은 놈으로 고른 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n장도르의 수제 튜닉"},
[7735] = {title = "온전한 설인 가죽", objective = "페랄라스의 페더문 요새에 있는 프랫 맥그루벤에게 온전한 설인 가죽을 가져가야 합니다.", description = "유별나게 두껍고 튼튼해 보이는 온전한 설인 가죽을 찾았습니다. 무쇠설인 소굴에 사는 설인들의 가죽보다도 더 두껍고 튼튼합니다.\n\n페더문 요새에 있는 프랫 맥그루벤이 설인 가죽을 취급하니 이 가죽에 상당히 관심을 가질 것 같습니다.", progress = "이건 뭡니까? 뭔가 특별한 걸 가져왔나 보군요.", completion = "정말 놀랍군요! 이거라면 모든 설인 가죽의 할아버지뻘 되는 가죽을 찾은 걸지도 모릅니다!\n\n당연히 내가 하겠습니다. 보통 가죽 하나에 이렇게 많은 돈을 지불하지는 않지만 분명 이걸로 아주 특별한 제품을 만들 수 있을 겁니다. 이 물건을 가져다줘서 고맙습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7736] = {title = "불꽃 융해촉진제 보급품", objective = "잡담이나 하면서 더 이상 귀한 시간 낭비하진 말자고, <class> 친구. 지금은 줄어들고 있는 불꽃 융해촉진제 재고를 보충하는 데 힘을 기울여야 할 때일세.\n\n자네가 가져와야 할 건 이렇다네.\n\n*인센도사우루스 비늘 2개\n*왕꽃잎풀 4개\n*석탄\n\n자네가 가져오는 건 모조리 다 받도록 하지! 토륨 대장조합에서 평판을 높이려면 빨리 가져오는 게 좋을 거야.", description = nil, progress = "잡담이나 하면서 더 이상 귀한 시간 낭비하진 말자고, <class> 친구. 지금은 줄어들고 있는 불꽃 융해촉진제 재고를 보충하는 데 힘을 기울여야 할 때일세.\n\n자네가 가져와야 할 건 이렇다네.\n\n*인센도사우루스 비늘 2개\n*왕꽃잎풀 4개\n*석탄\n\n자네가 가져오는 건 모조리 다 받도록 하지! 토륨 대장조합에서 평판을 높이려면 빨리 가져오는 게 좋을 거야.", completion = "불꽃 융해촉진제는 늘 부족한 물건이니 재료를 계속해서 가져오게나... 내가 그만하라고 할 때까지 말이야.", rewards = nil},
[7737] = {title = "인정받기", objective = "자네가 열심히 수고해 준 결과 토륨 대장조합에서 평판이 올라가고 있네. 이제 우리가 자네를 호의적으로 보기 시작한 것이야. 아주 대단한 일을 해낸 거라네!\n\n자네가 더 많은 일을 해서 우리에게 더욱 존중받고 싶다면 잘 듣게나. 혼합물에 검은바위 나락에서 찾을 수 있는 순수한 검은무쇠 잔류물을 섞으면 불꽃 융해촉진제를 정제할 수 있다네. 검은무쇠 잔류물을 찾는 대로 모두 내게 가져오게!", description = nil, progress = "자네가 열심히 수고해 준 결과 토륨 대장조합에서 평판이 올라가고 있네. 이제 우리가 자네를 호의적으로 보기 시작한 것이야. 아주 대단한 일을 해낸 거라네!\n\n자네가 더 많은 일을 해서 우리에게 더욱 존중받고 싶다면 잘 듣게나. 혼합물에 검은바위 나락에서 찾을 수 있는 순수한 검은무쇠 잔류물을 섞으면 불꽃 융해촉진제를 정제할 수 있다네. 검은무쇠 잔류물을 찾는 대로 모두 내게 가져오게!", completion = "계속해서 잔류물을 가져오게!", rewards = nil},
[7738] = {title = "완전한 설인 가죽", objective = "페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 완전한 설인 가죽을 가져가야 합니다.", description = "아주 완전해 보이는 설인 가죽을 찾았습니다. 심지어 무쇠설인 소굴에 사는 설인들의 가죽보다도 훨씬 더 두껍고 튼튼하다는 것을 쉽게 알아차릴 수 있습니다.\n\n모자케 야영지에 있는 장도르 스위프트스트라이더가 설인 가죽을 취급하니 이 가죽에 상당히 관심을 가질 것 같습니다.", progress = "이건 무엇이오? 뭔가 특별한 걸 가져왔나 보군.", completion = "아주 놀라운 걸 발견했군! 내가 본 것 중 가장 훌륭한 설인 가죽 견본인 것 같소!\n\n당연히, 이런 가죽은 제대로 값을 쳐 줘야지. 보통 가죽 하나에 이렇게 많은 돈을 지불하지는 않지만 분명 이 가죽으로 특별한 걸 만들 수 있을 거요. 이런 물건을 나한테 가져다줘서 고맙소이다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7761] = {title = "블랙핸드의 명령서", objective = "아주 멍청한 오크로군요. 지배의 보주를 사용하려면 드라키사스의 낙인을 찾아 드라키사스의 징표를 받아야 할 거 같습니다.\n\n이 편지에 따르면 드라키사스 사령관이 낙인을 지키고 있다고 하니 조사해 보는 것이 좋겠습니다.", description = "멍청이에게 고한다.\n\n외부인들이 주인님의 둥지에 접근하는 것을 네 녀석이 막을 수 있으리라 믿지는 않는다. 십중팔구 네가 죽을 경우에 대비해 이 보주 자체에는 외부인들이 바로 검은날개 둥지로 순간이동을 할 수 없도록 안전장치가 내장되어 있다.\n\n오직 손에 드라키사스의 징표가 있는 자들만이 이 보주를 사용할 수 있다. 다행히도 드라키사스는 너처럼 무능하지 않아서 자신이 직접 그 낙인을 지키고 있다!\n\n- 대족장 렌드 블랙핸드\n\n추신 - 이 편지는 파괴해라, 멍청이.", progress = nil, completion = "지글거리는 낙인을 살에 대고 눌러도 전혀 움찔하지 않다니 당신은 아주 강합니다!\n\n이제 당신에게 드라키사스의 징표가 찍혔습니다. 자, 이제 지배의 보주를 통해 검은날개 둥지로 돌진해 보십시오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7781] = {title = "검은바위부족의 군주", objective = "스톰윈드에 있는 대영주 볼바르 폴드라곤에게 네파리안의 머리를 가져가야 합니다.", description = "치열한 전투를 마친 후의 익숙한 느낌이 되살아나며 반갑기까지 한 승리의 고통이 온몸에 퍼집니다. 앞에는 전투로 인해 상처 입은 거대한 네파리안의 머리가 놓여 있습니다. 용사여, 이 머리를 대영주에게 가져가십시오.", progress = "오, 믿어지지 않는군!", completion = "자네가 해낸 일이 어떤 의미인지 설명해 주지 않아도 잘 알 테지. 이 날은 역사에 기록되어 길이 전해질 걸세. 이건 오랜 세월 동안 얼라이언스가 맛보지 못했던 승리야. 전에도 이런 적이 있었다면 말일세!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7782] = {title = "검은바위부족의 군주", objective = "스톰윈드에 있는 영웅의 계곡으로 가서 야전사령관 스톤브릿지와 대화하십시오.", description = "영웅의 계곡으로 가서 야전사령관인 스톤브릿지와 얘기하도록 하게.", progress = nil, completion = "&lt;예를 갖춰 인사하는 야전사령관 아프라샤비&gt;\n\n원하는 보상을 고르시오. 축하하오!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n용사냥꾼의 메달용사냥꾼의 수정구용사냥꾼의 반지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7783] = {title = "검은바위부족의 군주", objective = "오그리마에 있는 스랄에게 네파리안의 머리을 가져가야 합니다.", description = "치열한 전투를 마친 후의 익숙한 느낌이 되살아나며 반갑기까지 한 승리의 고통이 온몸에 퍼집니다. 지금 당신의 앞에 전투로 인해 상처 입은 거대한 네파리안의 머리가 놓여 있습니다. 용사여, 이 머리를 대족장에게 가져가십시오.", progress = "그대가 최후의 일격을 가할 때 놈의 표정을 직접 못 본 게 아쉽군.", completion = "&lt;name&gt;, 그대는 또 한 번 호드에 영광을 안겨 주었노라! 자기 아들이 쓰러졌으니 극악무도한 데스윙 놈도 분명 흔들리고 있을 것이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7784] = {title = "검은바위부족의 군주", objective = "오그리마에 있는 대군주 사울팽과 대화하십시오. 힘의 골짜기에서 당신을 기다리고 있습니다.", description = "이제 힘의 골짜기로 가서 대군주 사울팽을 만나보게나.", progress = nil, completion = "자네는 어서 원하는 보상을 골라 보게. 나는 만인이 볼 수 있도록 이 괴물의 머리를 높이 매달아야 하니까.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n용사냥꾼의 메달용사냥꾼의 수정구용사냥꾼의 반지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7785] = {title = "결정 조사", objective = "환생의 관을 조사한 후, 대영주 데미트리안에게 가져다주십시오.", description = "필멸의 생명체여, 환생의 관을 조사하십시오. 이 결정에서 바람추적자가 새로이 태어날 것입니다!", progress = nil, completion = nil, rewards = nil},
[7786] = {title = "바람추적자 썬더란", objective = "바람추적자 썬더란을 감옥에서 해방시키려면 실리더스에 있는 대영주 데미트리안에게 바람추적자의 족쇄의 오른쪽 조각과 왼쪽 조각, 엘레멘티움 주괴 10개, 그리고 불의 군주의 정수를 가져가야 합니다.", description = "제가 아는 건 모두 얘기해 드렸습니다, <name>. 엘레멘티움을 찾는 건 당신 몫입니다. 불의 군주의 육체를 파괴하는 것도 그렇고요.\n\n그러면 당신은 썬더란의 축복을 얻게 될 것입니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7787] = {title = "일어나라, 우레폭풍이여!", objective = "잠들어 있는 바람의 성검을 대영주 데미트리안 앞에 내 놓아야 합니다.", description = "바람추적자를 물리쳤습니다. 애처롭게 쓰러져 있는 데미트리안에게 잠들어 있는 성검을 주어 우레 폭풍을 깨운 그의 배신 행위를 일깨워 주도록 하십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n우레폭풍 - 바람추적자의 성검"},
[7788] = {title = "침략자 처단!", objective = "전쟁노래 협곡으로 들어가 호드를 무찌르고 전쟁노래 협곡 명예 훈장을 얻어 은빛날개 숲에 있는 파수꾼 파송에게 돌아가야 합니다.", description = "젊은 <class>|1이여;여;, 이 터널 너머에서 그대는 투쟁과 동요의 현장을 경험하게 될 것입니다. 호드는 신성한 숲을 더럽히고 울창한 푸른 나무들을 베어내며 자신들의 전쟁 기계를 가동시키는 동력으로 사용하고 있습니다.\n\n이 길을 따라 전쟁노래 협곡으로 가서 은빛날개 요새를 지켜 주십시오. 침략자인 호드 군대를 이 땅에서 몰아내 주십시오!\n\n호드를 몰아내고 무공 훈장을 얻으십시오. 훈장을 가져오시면 보상을 지급하겠습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7789] = {title = "은빛날개 분쟁 진압", objective = "전쟁노래 협곡으로 진입하여 얼라이언스 진영을 무찌르고 전쟁노래 협곡 명예 훈장을 얻으십시오. 몰샨 주둔지에 있는 부대장 쉐터스컬에게 가져가야 합니다.", description = "<race>|1이여;여;, 잿빛 골짜기는 호드의 힘 앞에 무릎을 꿇을 것이다. 은빛날개 파수대의 어떠한 행동도 우리의 절대 사명을 막을 수는 없다. 칼림도어는 원래 우리 호드의 것이다! 그런데 감히 누가 우리의 앞을 가로막는단 말인가?!\n\n가슴에 긍지와 용기를 불어넣어 우리를 가로막는 적들을 뿌리 뽑도록! 은빛날개 파수꾼들을 처치하고 전쟁노래 명예 훈장을 가져오라. 보상이 지급될 것이다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7790] = {title = "REUSE", objective = nil, description = "Defeat the Warsong Mill, then return to me.", progress = nil, completion = nil, rewards = nil},
[7791] = {title = "양모 옷감 기부", objective = "우린 현재 양모 옷감 기부를 받고 있습니다. 양모 옷감 60개를 기부하면 스톰윈드로부터 그 관대한 행위에 대해 높이 인정받게 될 겁니다. 우리 상점의 상황이라면 당신에게서 총 양모 옷감 60개만 받으면 될 겁니다. 나머지는 지역 내 다른 이들의 기부로 충분히 모을 수 있을 테니까요.\n\n지금 양모 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 지금 당장 받도록 하겠습니다.", description = nil, progress = "우린 현재 양모 옷감 기부를 받고 있습니다. 양모 옷감 60개를 기부하면 스톰윈드로부터 그 관대한 행위에 대해 높이 인정받게 될 겁니다. 우리 상점의 상황이라면 당신에게서 총 양모 옷감 60개만 받으면 될 겁니다. 나머지는 지역 내 다른 이들의 기부로 충분히 모을 수 있을 테니까요.\n\n지금 양모 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 지금 당장 받도록 하겠습니다.", completion = "훌륭하군요! 아낌없는 기부에 감사 드립니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7792] = {title = "양모 옷감 기부", objective = "현재 우린 양모 옷감 기부를 받고 있소. 양모 옷감 60개를 기부하는 선행을 하면 다르나서스로부터 높이 인정과 존경을 받게 될 거요. 지금 상황이라면 그대에게서 양모 옷감을 총 60개만 받으면 될 것이오. 나머지는 다른 이들로부터 충분히 모을 수 있을 테니까...\n\n지금 양모 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 내 당장 접수하겠소.", description = nil, progress = "현재 우린 양모 옷감 기부를 받고 있소. 양모 옷감 60개를 기부하는 선행을 하면 다르나서스로부터 높이 인정과 존경을 받게 될 거요. 지금 상황이라면 그대에게서 양모 옷감을 총 60개만 받으면 될 것이오. 나머지는 다른 이들로부터 충분히 모을 수 있을 테니까...\n\n지금 양모 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 내 당장 접수하겠소.", completion = "훌륭하오! &lt;name&gt;, 아낌없는 기부에 감사하오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7793] = {title = "비단 옷감 기부", objective = "대부분의 다른 직물과 마찬가지로 비단 재고량도 최저치입니다. 우리 상점의 상황으로는 당신에게서 총 비단 옷감 60개만 받으면 될 겁니다. 나머지는 다른 이들의 기부를 받아 목표를 달성할 수 있을 테니까요.\n\n게다가 비단 같은 좋은 선물을 기부하면 스톰윈드 내에서 당신의 평판도 틀림없이 높아질 겁니다! 지금 비단 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하겠습니다.", description = nil, progress = "대부분의 다른 직물과 마찬가지로 비단 재고량도 최저치입니다. 우리 상점의 상황으로는 당신에게서 총 비단 옷감 60개만 받으면 될 겁니다. 나머지는 다른 이들의 기부를 받아 목표를 달성할 수 있을 테니까요.\n\n게다가 비단 같은 좋은 선물을 기부하면 스톰윈드 내에서 당신의 평판도 틀림없이 높아질 겁니다! 지금 비단 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하겠습니다.", completion = "훌륭하군요! 아낌없는 기부에 감사 드립니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7794] = {title = "마법 옷감 기부", objective = "마법 옷감이 부족하니 당신이 옷감 재고를 보충하는 데 도움을 좀 줬으면 합니다! 전체 얼라이언스 연합을 기준으로 계산해 봤을 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같습니다. 그 정도의 관대함이라면 스톰윈드에서 몰라 주지 않을 거라는 걸 보장하지요!\n\n지금 마법 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하겠습니다.", description = nil, progress = "마법 옷감이 부족하니 당신이 옷감 재고를 보충하는 데 도움을 좀 줬으면 합니다! 전체 얼라이언스 연합을 기준으로 계산해 봤을 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같습니다. 그 정도의 관대함이라면 스톰윈드에서 몰라 주지 않을 거라는 걸 보장하지요!\n\n지금 마법 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하겠습니다.", completion = "훌륭하군요! 아낌없는 기부에 감사 드립니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7795] = {title = "룬무늬 옷감 기부", objective = "당신은 그동안 우리 옷감 수집에 상당히 많은 양을 기부해 주었습니다. 우린 재고량을 보충하기 위해 열심히 노력 중인 우리에게 천 재고 상태가 가장 낮은 것이 룬무늬 옷감입니다. 룬무늬 옷감이 절실히 필요한 이 상황에 당신이 예전처럼 우리를 다시 도와 줄 수 있었으면 합니다.\n\n생각이 있다면 룬무늬 옷감 여분을 내게 가져와 주십시오. 처음에는 한 번에 60개씩 기부받는 걸로 하고 그 후 차차 늘려 가기로 합시다.", description = nil, progress = "당신은 그동안 우리 옷감 수집에 상당히 많은 양을 기부해 주었습니다. 우린 재고량을 보충하기 위해 열심히 노력 중인 우리에게 천 재고 상태가 가장 낮은 것이 룬무늬 옷감입니다. 룬무늬 옷감이 절실히 필요한 이 상황에 당신이 예전처럼 우리를 다시 도와 줄 수 있었으면 합니다.\n\n생각이 있다면 룬무늬 옷감 여분을 내게 가져와 주십시오. 처음에는 한 번에 60개씩 기부받는 걸로 하고 그 후 차차 늘려 가기로 합시다.", completion = "훌륭하군요. 이 옷감들은 분명 바로 쓰이게 될 겁니다. 도와 줘서 다시 한번 감사 드립니다! 당신이 아니었으면 큰일날 뻔했습니다.\n\n당신은 지금까지 기부를 많이 해 왔지만 앞으로 룬무늬 옷감을 더 기부하고 싶다면 기꺼이 받도록 하겠습니다. 날 찾아오기만 하면 내 직접 반드시 당신의 공로가 인정되도록 힘쓰도록 하지요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7796] = {title = "룬무늬 옷감 추가 기부", objective = "다시 만나 반갑습니다! 룬무늬 옷감은 늘 부족한 형편이라 당신이 더 기부할 생각이 있다면 우린 언제든 추가로 받을 수 있습니다. 룬무늬 옷감을 추가로 20개 더 기부해 준다면 내 스톰윈드를 대신해 당신이 계속된 수고에 대해 확실히 인정을 받도록 해 주겠습니다.\n\n언제든 당신이 룬무늬 옷감을 추가로 기부할 준비가 되면 내가 받도록 하지요.", description = nil, progress = "다시 만나 반갑습니다! 룬무늬 옷감은 늘 부족한 형편이라 당신이 더 기부할 생각이 있다면 우린 언제든 추가로 받을 수 있습니다. 룬무늬 옷감을 추가로 20개 더 기부해 준다면 내 스톰윈드를 대신해 당신이 계속된 수고에 대해 확실히 인정을 받도록 해 주겠습니다.\n\n언제든 당신이 룬무늬 옷감을 추가로 기부할 준비가 되면 내가 받도록 하지요.", completion = "스톰윈드를 위해 수고해 주는 당신 같은 영웅들이 없었더라면 틀림없이 우린 고생을 면치 못했을 겁니다. 계속 수고해 줘서 고맙습니다!", rewards = nil},
[7798] = {title = "비단 옷감 기부", objective = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치요. 지금 상황으로 봐선 그대에게서 비단 옷감을 총 60개만 받으면 될 거요. 다른 이들에게 나머지를 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같은 좋은 물건을 기부하면 이 지역 공동체에서 그대의 명성도 틀림없이 높아질 거요! 지금 비단 옷감 60개를 가지고 있고 기부할 마음이 있다면 내 당장 접수하겠소.", description = nil, progress = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치요. 지금 상황으로 봐선 그대에게서 비단 옷감을 총 60개만 받으면 될 거요. 다른 이들에게 나머지를 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같은 좋은 물건을 기부하면 이 지역 공동체에서 그대의 명성도 틀림없이 높아질 거요! 지금 비단 옷감 60개를 가지고 있고 기부할 마음이 있다면 내 당장 접수하겠소.", completion = "훌륭하오! &lt;name&gt;, 아낌없는 기부에 감사하오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7799] = {title = "마법 옷감 기부", objective = "마법 옷감이 턱없이 부족하니 그대가 재고를 보충하는 데 도움을 좀 줬으면 하오! 얼라이언스 연합 전체를 기준으로 계산해 볼 때 그대가 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같소. 그 정도 선행을 베푼다면 다르나서스에서 그대의 공을 모른 척 하지는 않을 거요!\n\n지금 마법 옷감 60개를 가지고 있고 기부할 마음이 있다면 내 당장 접수하겠소.", description = nil, progress = "마법 옷감이 턱없이 부족하니 그대가 재고를 보충하는 데 도움을 좀 줬으면 하오! 얼라이언스 연합 전체를 기준으로 계산해 볼 때 그대가 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같소. 그 정도 선행을 베푼다면 다르나서스에서 그대의 공을 모른 척 하지는 않을 거요!\n\n지금 마법 옷감 60개를 가지고 있고 기부할 마음이 있다면 내 당장 접수하겠소.", completion = "훌륭하오! &lt;name&gt;, 아낌없는 기부에 감사하오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7800] = {title = "룬무늬 옷감 기부", objective = "<name>, 그동안 상당한 양의 옷감을 기부해 주었소. 우린 아직도 재고를 보충하기 위해 애쓰는 중인데, 제일 부족한 게 룬무늬 옷감이라오. 이러한 상황에서 전처럼 우리를 또 다시 도와 줄 수 있었으면 하오!\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주시오. 처음이니까 60개 받는 걸로 시작합시다.", description = nil, progress = "<name>, 그동안 상당한 양의 옷감을 기부해 주었소. 우린 아직도 재고를 보충하기 위해 애쓰는 중인데, 제일 부족한 게 룬무늬 옷감이라오. 이러한 상황에서 전처럼 우리를 또 다시 도와 줄 수 있었으면 하오!\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주시오. 처음이니까 60개 받는 걸로 시작합시다.", completion = "훌륭하오. 장담하건대 이 옷감들은 반드시 올바른 곳에 쓰일 거요. 다시 한번 감사하오! 그대가 아니었으면 큰일 날 뻔했소이다.\n\n지금까지 기부를 많이 해 왔지만 룬무늬 옷감을 더 기부하고 싶다면 기꺼이 받겠소. 날 찾아오기만 하시오. 내 반드시 그대의 선행이 모두에게 인정받도록 해 줄 테니까!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7801] = {title = "룬무늬 옷감 추가 기부", objective = "<name>, 다시 찾아주다니 고맙소! 룬무늬 옷감은 늘 부족한 형편이라 그대가 기부할 생각이 있다면 우린 언제든 추가로 받을 수 있소이다. 룬무늬 옷감을 20개 추가로 기부해 준다면 내 다르나서스를 대신해 그대의 계속된 노고가 확실히 인정받도록 해 주겠소.\n\n그대가 룬무늬 옷감을 추가로 기부할 준비가 되면 언제든지 받도록 하겠소.", description = nil, progress = "<name>, 다시 찾아주다니 고맙소! 룬무늬 옷감은 늘 부족한 형편이라 그대가 기부할 생각이 있다면 우린 언제든 추가로 받을 수 있소이다. 룬무늬 옷감을 20개 추가로 기부해 준다면 내 다르나서스를 대신해 그대의 계속된 노고가 확실히 인정받도록 해 주겠소.\n\n그대가 룬무늬 옷감을 추가로 기부할 준비가 되면 언제든지 받도록 하겠소.", completion = "&lt;name&gt;, 다르나서스를 위해 수고해 주는 그대 같은 영웅들이 없었더라면 우린 분명 고생을 면치 못했을 거요. 계속된 노고에 정말 감사 드리오!", rewards = nil},
[7802] = {title = "양모 옷감 기부", objective = "우린 현재 양모 옷감 기부를 받고 있습니다. 양모 옷감 60개를 기부하는 선행을 베풀면 아이언포지 전체로부터 드높은 존경과 인정을 받게 될 거예요. 지금 상황이라면 당신에게서 양모 옷감 총 60개만 받으면 될 것 같군요. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까요.\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠어요.", description = nil, progress = "우린 현재 양모 옷감 기부를 받고 있습니다. 양모 옷감 60개를 기부하는 선행을 베풀면 아이언포지 전체로부터 드높은 존경과 인정을 받게 될 거예요. 지금 상황이라면 당신에게서 양모 옷감 총 60개만 받으면 될 것 같군요. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까요.\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠어요.", completion = "훌륭해요! &lt;name&gt;, 아낌없는 기부에 감사해요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7803] = {title = "비단 옷감 기부", objective = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치예요. 지금 상황으로 봐선 그대에게서 비단 옷감을 총 60개만 받으면 될 거예요. 다른 이들에게 나머지를 받아도 충분히 목표를 달성할 수 있을 테니까요.\n\n게다가 비단 같은 좋은 물건을 기부하면 이 지역 공동체에서 그대의 명성도 틀림없이 높아질 겁니다! 지금 비단 옷감 60개를 가지고 있고 기부할 마음이 있다면 제가 당장 접수하죠.", description = nil, progress = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치예요. 지금 상황으로 봐선 그대에게서 비단 옷감을 총 60개만 받으면 될 거예요. 다른 이들에게 나머지를 받아도 충분히 목표를 달성할 수 있을 테니까요.\n\n게다가 비단 같은 좋은 물건을 기부하면 이 지역 공동체에서 그대의 명성도 틀림없이 높아질 겁니다! 지금 비단 옷감 60개를 가지고 있고 기부할 마음이 있다면 제가 당장 접수하죠.", completion = "훌륭해요. &lt;name&gt;, 아낌없는 기부에 감사 드립니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7804] = {title = "마법 옷감 기부", objective = "마법 옷감이 턱없이 부족하니 그대가 재고를 보충하는 데 도움을 좀 줬으면 해요! 얼라이언스 연합 전체를 기준으로 계산해 볼 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같군요. 그 정도 선행을 베푼다면 아이언포지에서도 당신의 공을 모른 척 하지는 않을 거예요!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠어요.", description = nil, progress = "마법 옷감이 턱없이 부족하니 그대가 재고를 보충하는 데 도움을 좀 줬으면 해요! 얼라이언스 연합 전체를 기준으로 계산해 볼 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같군요. 그 정도 선행을 베푼다면 아이언포지에서도 당신의 공을 모른 척 하지는 않을 거예요!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠어요.", completion = "훌륭해요! &lt;name&gt;, 아낌없는 기부에 정말 감사 드립니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7805] = {title = "룬무늬 옷감 기부", objective = "<name>, 그동안 상당한 양의 옷감을 기부해 주었죠. 아직도 우린 재고를 보충하기 위해 애쓰는 중인데, 제일 부족한 게 룬무늬 옷감이에요. 이러한 상황에서 우리를 다시 한번 도와 줄 수 있었으면 해요.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주세요. 60개 받는 걸로 시작하죠.", description = nil, progress = "<name>, 그동안 상당한 양의 옷감을 기부해 주었죠. 아직도 우린 재고를 보충하기 위해 애쓰는 중인데, 제일 부족한 게 룬무늬 옷감이에요. 이러한 상황에서 우리를 다시 한번 도와 줄 수 있었으면 해요.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주세요. 60개 받는 걸로 시작하죠.", completion = "훌륭해요. 제가 장담하건대 이 옷감들은 반드시 올바른 곳에 쓰일 거예요. 거듭 감사 드립니다! 당신이 아니었으면 정말 큰일 날 뻔했어요.\n\n지금까지 기부를 많이 해 왔지만 룬무늬 옷감을 더 기부하고 싶다면 기꺼이 받겠어요. 절 찾아오기만 하세요. 제가 반드시 당신의 선행이 모두에게 인정받도록 해 드릴 테니까요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7806] = {title = "룬무늬 옷감 추가 기부", objective = "<name>, 다시 찾아주다니 이렇게 고마울 데가! 룬무늬 옷감은 늘 부족한 형편이라 당신이 기부할 생각만 있다면 우린 언제든지 감사히 받겠어요. 룬무늬 옷감을 20개 추가로 기부해 준다면 제가 아이언포지를 대신해 당신의 계속된 노고가 확실히 인정받도록 하겠어요.\n\n당신이 룬무늬 옷감을 추가로 기부할 준비가 되면 언제든지 받도록 하죠.", description = nil, progress = "<name>, 다시 찾아주다니 이렇게 고마울 데가! 룬무늬 옷감은 늘 부족한 형편이라 당신이 기부할 생각만 있다면 우린 언제든지 감사히 받겠어요. 룬무늬 옷감을 20개 추가로 기부해 준다면 제가 아이언포지를 대신해 당신의 계속된 노고가 확실히 인정받도록 하겠어요.\n\n당신이 룬무늬 옷감을 추가로 기부할 준비가 되면 언제든지 받도록 하죠.", completion = "&lt;name&gt;, 아이언포지를 위해 수고해 주는 당신 같은 영웅들이 없었더라면 우린 분명 고생을 면치 못했을 거예요. 계속된 노고에 정말 감사 드려요!", rewards = nil},
[7807] = {title = "양모 옷감 기부", objective = "지금 우린 양모 옷감 기부를 받고 있어요. 양모 옷감 60개를 기부하는 선행을 베풀면 놈리건에서 추방당한 모든 노움들로부터 존경과 인정을 한 몸에 받게 될 거예요. 지금 상황이라면 양모 옷감 총 60개만 받으면 되겠군요. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까요.\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하죠.", description = nil, progress = "지금 우린 양모 옷감 기부를 받고 있어요. 양모 옷감 60개를 기부하는 선행을 베풀면 놈리건에서 추방당한 모든 노움들로부터 존경과 인정을 한 몸에 받게 될 거예요. 지금 상황이라면 양모 옷감 총 60개만 받으면 되겠군요. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까요.\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하죠.", completion = "훌륭해요! &lt;name&gt;, 아낌없는 기부에 정말 감사합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7808] = {title = "비단 옷감 기부", objective = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치예요. 지금 상황으로 봐선 당신에게서 비단 옷감을 총 60개만 받으면 되겠군요. 다른 이들에게 나머지를 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같은 좋은 물건을 기부하면 이 지역 공동체에서 당신의 명성도 틀림없이 높아질 거예요! 지금 비단 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하죠.", description = nil, progress = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치예요. 지금 상황으로 봐선 당신에게서 비단 옷감을 총 60개만 받으면 되겠군요. 다른 이들에게 나머지를 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같은 좋은 물건을 기부하면 이 지역 공동체에서 당신의 명성도 틀림없이 높아질 거예요! 지금 비단 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하죠.", completion = "훌륭해요! &lt;name&gt;, 아낌없는 기부에 정말 감사, 감사!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7809] = {title = "마법 옷감 기부", objective = "마법 옷감이 턱없이 부족하니 재고를 보충하는 데 도움을 좀 줬으면 해요! 얼라이언스 연합 전체를 기준으로 계산해 볼 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같아요. 그 정도 선행을 베푼다면 놈리건에서도 당신의 공을 모른 척 하지는 않을 거예요!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하죠.", description = nil, progress = "마법 옷감이 턱없이 부족하니 재고를 보충하는 데 도움을 좀 줬으면 해요! 얼라이언스 연합 전체를 기준으로 계산해 볼 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같아요. 그 정도 선행을 베푼다면 놈리건에서도 당신의 공을 모른 척 하지는 않을 거예요!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하죠.", completion = "훌륭해요! &lt;name&gt;, 아낌없는 기부에 정말 감사, 감사!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7810] = {title = "검투사", objective = "가시덤불 골짜기에 원형투기장에 있는 땅딸보 존 미스릴과 대화하십시오.\n\n제공된 아이템: \n", description = "검투사가 되는게 이렇게 간단할 리 없습니다! 구루바시에서 행사를 운영하는 해적단원이 더 알지도 모릅니다.", progress = nil, completion = "크아, 이봐! 장신구 하나 갖고는 검투사가 될 수 없어! 이제 네 힘을 제대로 보여 줘야 할 때라구.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7811] = {title = "룬무늬 옷감 기부", objective = "<name>, 그동안 상당한 양의 옷감을 기부해 주었죠. 아직도 우린 재고를 보충하기 위해 애쓰는 중인데, 제일 부족한 게 룬무늬 옷감이에요. 이러한 상황에서 우리를 다시 한 번 도와 줄 수 있었으면 해요.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주세요. 처음이니까 60개 받는 걸로 시작하죠.", description = nil, progress = "<name>, 그동안 상당한 양의 옷감을 기부해 주었죠. 아직도 우린 재고를 보충하기 위해 애쓰는 중인데, 제일 부족한 게 룬무늬 옷감이에요. 이러한 상황에서 우리를 다시 한 번 도와 줄 수 있었으면 해요.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주세요. 처음이니까 60개 받는 걸로 시작하죠.", completion = "훌륭해요. 장담하건대 이 옷감들은 반드시 올바른 곳에 쓰일 거예요. 거듭 감사, 또 감사합니다! 당신이 없었더라면 큰일 날 뻔했어요.\n\n지금까지 기부를 많이 해 왔지만 룬무늬 옷감을 더 기부하고 싶다면 기꺼이 받겠어요. 절 찾아오기만 하세요. 제가 반드시 당신의 선행이 모두에게 인정받도록 해 드릴 테니까요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7812] = {title = "룬무늬 옷감 추가 기부", objective = "<name>, 다시 찾아주다니 이렇게 고마울 데가! 룬무늬 옷감은 늘 부족한 형편이라 기부할 생각만 있다면 우린 언제든지 감사히 받겠어요. 룬무늬 옷감 20개를 추가로 기부해 준다면 제가 놈리건 대신해 당신의 계속된 노고가 확실히 인정받도록 애쓰겠어요.\n\n룬무늬 옷감을 추가로 기부할 준비가 되면 언제든지 받도록 하죠.", description = nil, progress = "<name>, 다시 찾아주다니 이렇게 고마울 데가! 룬무늬 옷감은 늘 부족한 형편이라 기부할 생각만 있다면 우린 언제든지 감사히 받겠어요. 룬무늬 옷감 20개를 추가로 기부해 준다면 제가 놈리건 대신해 당신의 계속된 노고가 확실히 인정받도록 애쓰겠어요.\n\n룬무늬 옷감을 추가로 기부할 준비가 되면 언제든지 받도록 하죠.", completion = "&lt;name&gt;, 우리 노움들을 위해 수고해 주는 당신 같은 영웅들이 없었더라면 우린 분명 고생을 면치 못했을 거예요. 계속된 노고에 정말 감사, 감사!", rewards = nil},
[7813] = {title = "양모 옷감 기부", objective = "우린 현재 양모 옷감 기부를 받고 있네. 양모 옷감 60개를 기부하면 언더시티로부터 그 관대한 행위에 대해 높이 인정받게 될 걸세. 우리 상점의 상황이라면 당신에게서 총 양모 옷감 60개만 받으면 될 것이야. 나머지는 지역 내 다른 이들의 기부로 충분히 모을 수 있을 테니까 말이지.\n\n지금 양모 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하지.", description = nil, progress = "우린 현재 양모 옷감 기부를 받고 있네. 양모 옷감 60개를 기부하면 언더시티로부터 그 관대한 행위에 대해 높이 인정받게 될 걸세. 우리 상점의 상황이라면 당신에게서 총 양모 옷감 60개만 받으면 될 것이야. 나머지는 지역 내 다른 이들의 기부로 충분히 모을 수 있을 테니까 말이지.\n\n지금 양모 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하지.", completion = "훌륭하군! 아낌없는 기부에 감사하네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7814] = {title = "비단 옷감 기부", objective = "대부분의 다른 옷감과 마찬가지로 비단 재고량도 최저치라네. 우리 상점의 상황으로는 자네에게 총 비단 옷감 60개만 받으면 될 걸세. 나머지는 다른 이들의 기부를 받아 목표를 달성할 수 있을 테니까 말이야.\n\n게다가 비단 같은 좋은 선물을 기부하면 호드 연합에서 자네의 명성도 틀림없이 높아질 걸세! 지금 비단 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하지.", description = nil, progress = "대부분의 다른 옷감과 마찬가지로 비단 재고량도 최저치라네. 우리 상점의 상황으로는 자네에게 총 비단 옷감 60개만 받으면 될 걸세. 나머지는 다른 이들의 기부를 받아 목표를 달성할 수 있을 테니까 말이야.\n\n게다가 비단 같은 좋은 선물을 기부하면 호드 연합에서 자네의 명성도 틀림없이 높아질 걸세! 지금 비단 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하지.", completion = "훌륭하군! 아낌없는 기부에 감사하네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7815] = {title = "무쇠턱바다거북 처치", objective = "무쇠턱바다거북 15마리를 처치하고 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다.", description = "녀석들의 커다란 눈망울에 속아넘어가지 말게! 저 무쇠턱바다거북 녀석들은 위협적인 놈들이야. 저 덩치만 큰 녀석들이 내 미끼를 계속 훔쳐가는 통에 적어도 5분마다 하나씩 낚싯줄을 끊어 먹고 있으니 말이야.\n\n나와 레반터스크 마을 주민들을 도와 주는 셈치고 녀석들을 처치해 주게. 녀석들의 무리 전체를 처치해 버리게나!", progress = nil, completion = "이야! 뭐라고 감사의 말을 해야 할지 모르겠군! 이 낚싯대로 충분한 보상이 됐으면 좋겠군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n내트 페이글의 다낚아 FC-5000"},
[7816] = {title = "감메리타 처치", objective = "감메리타를 처치하고 카툼의 최고급 미끼를 되찾아 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다.\n\n카툼이 감메리타는 해안에서 다른 거북들과 함께 있다고 얘기해 줬습니다.", description = "안녕하신가! 저 밖에 다른 녀석들과는 다른 특이한 거북이 한 마리가 있다네. 감메리타라고 하는 무쇠턱바다거북의 우두머리인데, 아주 더러운 좀도둑 파충류지.\n\n글쎄, 내가 가지고 있는 제일 좋은 미끼를 훔쳐 가지 않았겠나. 낚싯줄에서 바로 뚝 끊어 가 버리더군! 그때부터는 고기잡이가 영 예전만하지 못하다네.\n\n감메리타를 찾아서 그 뱃속에 있는 내 미끼를 되찾아 주게나.", progress = "아직 못 찾았나?", completion = "이야! 잘 됐군! 제일 좋은 미끼도 찾았고 무쇠턱바다거북의 수도 줄었으니 어획량이 크게 늘겠군그래.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7817] = {title = "마법 옷감 기부", objective = "마법 옷감이 부족하니 자네가 옷감 재고를 보충하는 데 도움을 좀 줬으면 하네! 호드 연합 전체를 기준으로 계산해 볼 때 자네가 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같네. 그 정도의 관대함이라면 언더시티에서 몰라 주지 않을 걸세, 내 보장하지!\n\n지금 마법 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하겠네.", description = nil, progress = "마법 옷감이 부족하니 자네가 옷감 재고를 보충하는 데 도움을 좀 줬으면 하네! 호드 연합 전체를 기준으로 계산해 볼 때 자네가 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같네. 그 정도의 관대함이라면 언더시티에서 몰라 주지 않을 걸세, 내 보장하지!\n\n지금 마법 옷감 60개를 가지고 있고 그걸 기부할 마음이 있다면 당장 받도록 하겠네.", completion = "훌륭하군! 아낌없는 기부에 감사하네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7818] = {title = "룬무늬 옷감 기부", objective = "자네는 그동안 우리 옷감 수집을 위해 상당히 많은 양을 기부해 주었네. 우린 재고량을 보충하기 위해 열심히 노력 중인 우리에게 천 재고 상태가 가장 낮은 것이 룬무늬 옷감이네. 룬무늬 옷감이 절실히 필요한 이 상황에 자네가 예전처럼 우리를 다시 도와 줄 수 있었으면 하네.\n\n생각이 있다면 룬무늬 옷감 여분을 내게 가져와 주게나. 처음이니까 60개 받는 걸로 하고 그 후 차차 늘려 가기로 하세나.", description = nil, progress = "자네는 그동안 우리 옷감 수집을 위해 상당히 많은 양을 기부해 주었네. 우린 재고량을 보충하기 위해 열심히 노력 중인 우리에게 천 재고 상태가 가장 낮은 것이 룬무늬 옷감이네. 룬무늬 옷감이 절실히 필요한 이 상황에 자네가 예전처럼 우리를 다시 도와 줄 수 있었으면 하네.\n\n생각이 있다면 룬무늬 옷감 여분을 내게 가져와 주게나. 처음이니까 60개 받는 걸로 하고 그 후 차차 늘려 가기로 하세나.", completion = "훌륭하군. 이 옷감들은 분명 바로 쓰이게 될 걸세. 도와줘서 다시 한번 감사하네! 자네가 아니었으면 큰일날 뻔했군.\n\n자네는 지금까지 기부를 많이 해 왔지만 앞으로 룬무늬 옷감을 더 기부하고 싶다면, 내 기꺼이 처리해 주겠네. 날 찾아오기만 하면 내 직접 반드시 자네의 공로가 인정되도록 해 주지!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7819] = {title = "룬무늬 옷감 추가 기부", objective = "다시 만나 반갑네! 룬무늬 옷감은 늘 부족한 형편이라 자네가 기부할 생각이 있다면 우린 언제든 추가로 받을 수 있다네. 룬무늬 옷감을 추가로 20개 더 기부해 준다면 내 언더시티를 대신해 자네의 계속된 수고에 대해 확실히 인정받도록 해 주겠네.\n\n언제든 자네가 룬무늬 옷감을 추가로 기부할 준비가 되면 내가 받도록 하지.", description = nil, progress = "다시 만나 반갑네! 룬무늬 옷감은 늘 부족한 형편이라 자네가 기부할 생각이 있다면 우린 언제든 추가로 받을 수 있다네. 룬무늬 옷감을 추가로 20개 더 기부해 준다면 내 언더시티를 대신해 자네의 계속된 수고에 대해 확실히 인정받도록 해 주겠네.\n\n언제든 자네가 룬무늬 옷감을 추가로 기부할 준비가 되면 내가 받도록 하지.", completion = "포세이큰을 위해 수고해 주는 자네 같은 영웅들이 없었더라면 우린 분명 고생을 면치 못했을 걸세. 계속 수고해 줘서 고맙네!", rewards = nil},
[7820] = {title = "양모 옷감 기부", objective = "지금 양모 옷감 기부를 받습니다. 양모 옷감 60개를 기부하는 선행을 베풀면 썬더 블러프로부터의 존경과 인정을 한 몸에 받게 될 겁니다. 지금 상황이라면 양모 옷감을 총 60개만 받으면 되겠군요. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까...\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠습니다.", description = nil, progress = "지금 양모 옷감 기부를 받습니다. 양모 옷감 60개를 기부하는 선행을 베풀면 썬더 블러프로부터의 존경과 인정을 한 몸에 받게 될 겁니다. 지금 상황이라면 양모 옷감을 총 60개만 받으면 되겠군요. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까...\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠습니다.", completion = "훌륭해요! &lt;name&gt;, 아낌없는 기부에 정말 감사합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7821] = {title = "비단 옷감 기부", objective = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치입니다. 지금 상황으로 봐서 당신에게서는 비단 옷감을 총 60개만 받으면 되겠군요. 나머지는 다른 이들에게 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같이 좋은 물건을 기부하면 이 지역 공동체에서 당신의 명성도 틀림없이 높아질 겁니다! 지금 비단 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠습니다.", description = nil, progress = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치입니다. 지금 상황으로 봐서 당신에게서는 비단 옷감을 총 60개만 받으면 되겠군요. 나머지는 다른 이들에게 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같이 좋은 물건을 기부하면 이 지역 공동체에서 당신의 명성도 틀림없이 높아질 겁니다! 지금 비단 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠습니다.", completion = "훌륭해요! &lt;name&gt;, 아낌없는 기부에 정말 감사합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7822] = {title = "마법 옷감 기부", objective = "마법 옷감이 턱없이 부족하니 재고를 보충하는 데 도움을 좀 줬으면 합니다! 호드 연합 전체를 기준으로 계산해 볼 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같군요. 그 정도 선행을 베푼다면 썬더 블러프에서도 당신의 공을 모른 척 하지는 않을 거예요!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠습니다.", description = nil, progress = "마법 옷감이 턱없이 부족하니 재고를 보충하는 데 도움을 좀 줬으면 합니다! 호드 연합 전체를 기준으로 계산해 볼 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같군요. 그 정도 선행을 베푼다면 썬더 블러프에서도 당신의 공을 모른 척 하지는 않을 거예요!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 제가 당장 접수하겠습니다.", completion = "훌륭해요! &lt;name&gt;, 아낌없는 기부에 정말 감사합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7823] = {title = "룬무늬 옷감 기부", objective = "<name>, 그동안 상당한 양의 옷감을 기부하신 걸로 압니다. 아직도 우린 재고를 보충하기 위해 애쓰는 중인데, 제일 부족한 게 룬무늬 옷감이에요. 이러한 상황에서 다시 한번 도움을 청합니다.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주세요. 처음이니까 60개 받는 걸로 시작하죠.", description = nil, progress = "<name>, 그동안 상당한 양의 옷감을 기부하신 걸로 압니다. 아직도 우린 재고를 보충하기 위해 애쓰는 중인데, 제일 부족한 게 룬무늬 옷감이에요. 이러한 상황에서 다시 한번 도움을 청합니다.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주세요. 처음이니까 60개 받는 걸로 시작하죠.", completion = "훌륭합니다. 장담하건대 이 옷감들은 반드시 올바른 곳에 쓰일 거예요. 거듭 감사합니다! 당신이 없었으면 큰일 날 뻔했군요.\n\n지금까지 기부를 많이 해 왔지만 룬무늬 옷감을 더 기부하고 싶다면 기꺼이 받겠습니다. 절 찾아오기만 하십시오. 제가 반드시 당신의 선행이 모두에게 인정받도록 해 드릴 테니까요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7824] = {title = "룬무늬 옷감 기부", objective = "<name>, 자네 그동안 상당한 양의 옷감을 기부하느라 수고 많았네. 하지만 아직도 우린 재고를 보충하기 위해 애쓰는 중이야. 제일 부족한 게 룬무늬 옷감일세. 이러한 상황에서 다시 한 번 자네의 도움을 요청하는 바일세.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주게나. 처음이니까 60개 받는 걸로 시작하지.", description = nil, progress = "<name>, 자네 그동안 상당한 양의 옷감을 기부하느라 수고 많았네. 하지만 아직도 우린 재고를 보충하기 위해 애쓰는 중이야. 제일 부족한 게 룬무늬 옷감일세. 이러한 상황에서 다시 한 번 자네의 도움을 요청하는 바일세.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주게나. 처음이니까 60개 받는 걸로 시작하지.", completion = "훌륭해. 장담하건대 이 옷감들은 반드시 올바른 곳에 쓰일 거야. 고마워! 자네가 없었더라면 큰일 날 뻔했군.\n\n지금까지 기부를 많이 해 왔지만 룬무늬 옷감을 더 기부하고 싶다면 기꺼이 받지. 날 찾아오기만 해. 반드시 자네 선행이 모두에게 인정받도록 해 줄 테니까!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7825] = {title = "룬무늬 옷감 추가 기부", objective = "<name>, 다시 찾아주다니 이렇게 고마울 데가! 룬무늬 옷감은 늘 부족한 형편이라 기부할 생각만 있다면 우린 언제든지 감사히 받겠습니다. 룬무늬 옷감 20개를 추가로 기부해 준다면 제가 썬더 블러프를 대신해 당신의 계속된 노고가 확실히 인정받도록 애쓰겠습니다.\n\n룬무늬 옷감을 추가로 기부할 준비가 되면 언제든지 받도록 하지요.", description = nil, progress = "<name>, 다시 찾아주다니 이렇게 고마울 데가! 룬무늬 옷감은 늘 부족한 형편이라 기부할 생각만 있다면 우린 언제든지 감사히 받겠습니다. 룬무늬 옷감 20개를 추가로 기부해 준다면 제가 썬더 블러프를 대신해 당신의 계속된 노고가 확실히 인정받도록 애쓰겠습니다.\n\n룬무늬 옷감을 추가로 기부할 준비가 되면 언제든지 받도록 하지요.", completion = "&lt;name&gt;, 썬더 블러프를 위해 수고해 주는 당신 같은 영웅들이 없었더라면 우린 분명 고생을 면치 못했을 거예요. 계속된 노고에 정말 감사합니다!", rewards = nil},
[7826] = {title = "양모 옷감 기부", objective = "지금 양모 옷감 기부를 받고 있네. 양모 옷감 60개를 기부하는 선행을 베풀면 오그리마 전체로부터 드높은 존경과 인정을 받게 될 거야. 지금 상황이라면 자네에게서 양모 옷감 총 60개만 받으면 될 것 같군. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까.\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하지.", description = nil, progress = "지금 양모 옷감 기부를 받고 있네. 양모 옷감 60개를 기부하는 선행을 베풀면 오그리마 전체로부터 드높은 존경과 인정을 받게 될 거야. 지금 상황이라면 자네에게서 양모 옷감 총 60개만 받으면 될 것 같군. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까.\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하지.", completion = "훌륭해! &lt;name&gt;, 아낌없는 기부 고맙네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7827] = {title = "비단 옷감 기부", objective = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치야. 지금 상황으로 봐서 자네에게서는 비단 옷감을 총 60개만 받으면 되겠군. 나머지는 다른 이들에게 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같이 좋은 물건을 기부하면 이 지역 공동체에서 자네의 명성도 틀림없이 높아질 거야! 지금 비단 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하지.", description = nil, progress = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치야. 지금 상황으로 봐서 자네에게서는 비단 옷감을 총 60개만 받으면 되겠군. 나머지는 다른 이들에게 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같이 좋은 물건을 기부하면 이 지역 공동체에서 자네의 명성도 틀림없이 높아질 거야! 지금 비단 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하지.", completion = "훌륭해! &lt;name&gt;, 아낌없는 기부 고맙네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7828] = {title = "은빛갈기늑대 추적", objective = "긴발톱 은빛갈기늑대 15마리와 긴울음 은빛갈기늑대 15마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다.\n\n마코르가 이 늑대들은 동부 내륙지의 황야에 숨어 있다고 얘기해 줬습니다.", description = "많은 용감한 트롤들이 동부 내륙지의 사나운 야생 동물들에게 목숨을 잃었소. 은빛갈기늑대들은 우리 사냥꾼들에게 가장 큰 위협 중 하나지. 녀석들은 덤불이나 지형을 이용해 숨어 기다리다가 기회가 생기면 습격하곤 한다오.\n\n이런 포악한 것들을 그냥 내버려둬서는 안 되오!\n\n은빛갈기늑대를 잡으려면 은빛갈기늑대처럼 생각해야 하오. 놈들을 추적하여 모두 처치해 버리시오!", progress = nil, completion = "잘 해 주었소, &lt;class&gt; 친구. 당신의 공로에 레반터스크에서 감사를 전하는 바이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7829] = {title = "포악한 올빼미야수 사냥", objective = "포악한 올빼미야수 20마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다.\n\n마코르가 포악한 올빼미야수는 동부 내륙지의 황야에 서식한다고 얘기해 줬습니다.", description = "동부 내륙지에서 아주 성미 고약한 편에 속하는 야생 동물로 포악한 올빼미야수를 꼽을 수 있소. 많은 우수한 레반터스크 전사들이 녀석들의 잔인한 발톱과 부리에 목숨을 잃었지.\n\n눈에 띄는 포악한 올빼미야수를 모조리 처치해 주시오, <class> 친구. 도저히 더 이상 살육을 참지 못하게 되었을 때 다시 날 찾아오시오. 그때 가서 당신의 공로를 재어 보고 평가해서 판단하겠소.", progress = nil, completion = "수고했소. 당신은 훌륭한 레반터스크의 동지임을 입증해 보였소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7830] = {title = "트롤의 복수", objective = "우두머리 뾰족부리그리핀 한 마리를 처치하고 그 우두머리 그리핀의 깃털을 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 가져가야 합니다.\n\n마코르의 얘기로는 우두머리 뾰족부리그리핀은 주로 동부 내륙지의 황야에 서식하는 희귀종이라고 합니다.", description = "자칭 와일드해머라는 쓰레기 같은 드워프 녀석들이 그리핀을 훈련해 트롤을 살해하고 있소. 분명 끔찍한 일이 아닐 수 없지만 걱정하지 마시오. 곧 정의가 실현될 테니까 말이야.\n\n일단 지금은 이 지역의 나이 든 그리핀들의 뿌리를 뽑아 버리는 데 집중하도록 하시오. 녀석들은 우두머리 뾰족부리그리핀이라는 이름으로 알려져 있소.\n\n한 마리를 처치한 후 그 깃털을 가지고 내게 돌아오시오.", progress = "우두머리 뾰족부리그리핀은 아주 희귀한 그리핀 종으로 살육을 일삼는 후손들을 번식시키고 있지.", completion = "&lt;깃털을 살펴보는 마코르&gt;\n\n당신이 정의의 처단을 내리기 전에 이 녀석이 우리 사냥꾼을 몇 명이나 잡아먹었을지 궁금하군그래.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7831] = {title = "마법 옷감 기부", objective = "마법 옷감이 턱없이 부족하니 자네가 재고를 보충하는 데 도움을 좀 줬으면 해! 호드 연합 전체를 기준으로 계산해 볼 때 자네가 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같군. 그 정도 선행을 베푼다면 오그리마에서도 자네 공을 모른 척 하지는 않을 걸세!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하지.", description = nil, progress = "마법 옷감이 턱없이 부족하니 자네가 재고를 보충하는 데 도움을 좀 줬으면 해! 호드 연합 전체를 기준으로 계산해 볼 때 자네가 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같군. 그 정도 선행을 베푼다면 오그리마에서도 자네 공을 모른 척 하지는 않을 걸세!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하지.", completion = "훌륭해! &lt;name&gt;, 아낌없는 기부 고맙네!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7832] = {title = "룬무늬 옷감 추가 기부", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7833] = {title = "양모 옷감 기부", objective = "지금 양모 옷감 기부를 받고 있습니다. 양모 옷감 60개를 기부하는 선행을 베풀면 검은창 트롤들로부터 드높은 존경과 인정을 받게 될 겁니다. 지금 상황이라면 당신에게서 양모 옷감을 총 60개만 받으면 될 것 같군요. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까요.\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하도록 하겠습니다.", description = nil, progress = "지금 양모 옷감 기부를 받고 있습니다. 양모 옷감 60개를 기부하는 선행을 베풀면 검은창 트롤들로부터 드높은 존경과 인정을 받게 될 겁니다. 지금 상황이라면 당신에게서 양모 옷감을 총 60개만 받으면 될 것 같군요. 나머지는 다른 이들의 기부로 충분히 모을 수 있을 테니까요.\n\n지금 양모 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하도록 하겠습니다.", completion = "훌륭해요! &lt;name&gt;, 아낌없는 기부 감사합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7834] = {title = "비단 옷감 기부", objective = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치입니다. 지금 상황으로 봐서 당신에게서는 비단 옷감을 총 60개만 받으면 되겠군요. 나머지는 다른 이들에게 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같이 좋은 물건을 기부하면 이 지역 공동체에서 당신의 명성도 틀림없이 높아질 거고요! 지금 비단 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하겠습니다.", description = nil, progress = "대부분의 다른 옷감과 마찬가지로 비단의 재고량도 최저치입니다. 지금 상황으로 봐서 당신에게서는 비단 옷감을 총 60개만 받으면 되겠군요. 나머지는 다른 이들에게 받아도 충분히 목표를 달성할 수 있을 테니까...\n\n게다가 비단 같이 좋은 물건을 기부하면 이 지역 공동체에서 당신의 명성도 틀림없이 높아질 거고요! 지금 비단 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하겠습니다.", completion = "훌륭합니다! &lt;name&gt;, 아낌없는 기부 정말 감사합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7835] = {title = "마법 옷감 기부", objective = "마법 옷감이 턱없이 부족하니 재고를 보충하기 위한 자비의 손길을 베풀어 주십시오! 호드 연합 전체를 기준으로 계산해 볼 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같군요. 그 정도 선행을 베푼다면 검은창 트롤 부족도 그 공을 모른 척 하지는 않을 겁니다!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하도록 하겠습니다.", description = nil, progress = "마법 옷감이 턱없이 부족하니 재고를 보충하기 위한 자비의 손길을 베풀어 주십시오! 호드 연합 전체를 기준으로 계산해 볼 때 당신이 마법 옷감 60개만 기부해 주면 목표를 달성할 수 있을 것 같군요. 그 정도 선행을 베푼다면 검은창 트롤 부족도 그 공을 모른 척 하지는 않을 겁니다!\n\n지금 마법 옷감 60개가 있고 기부할 마음이 있다면 당장 접수하도록 하겠습니다.", completion = "훌륭합니다! &lt;name&gt;, 아낌없는 기부 정말 감사합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7836] = {title = "룬무늬 옷감 기부", objective = "<name>, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많으셨습니다. 하지만 아직도 재고를 보충하기 위해 애쓰는 중이라서요. 제일 부족한 게 룬무늬 옷감입니다. 이 상황에서 우리를 다시 도와 줬으면 합니다.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주십시오. 처음이니까 60개 받는 걸로 시작하죠.", description = nil, progress = "<name>, 그동안 상당한 양의 옷감을 기부하느라 정말 수고 많으셨습니다. 하지만 아직도 재고를 보충하기 위해 애쓰는 중이라서요. 제일 부족한 게 룬무늬 옷감입니다. 이 상황에서 우리를 다시 도와 줬으면 합니다.\n\n생각이 있다면 남는 룬무늬 옷감을 기부해 주십시오. 처음이니까 60개 받는 걸로 시작하죠.", completion = "훌륭해요. 장담하건대 이 옷감들은 반드시 올바른 곳에 쓰일 겁니다. 거듭 감사합니다! 당신이 없었더라면 큰일 날 뻔했군요.\n\n지금까지 기부를 많이 해주셨지만 룬무늬 옷감을 더 기부하고 싶다면 기꺼이 받겠습니다. 절 찾아오기만 하십시오. 반드시 당신의 선행이 모두에게 인정받도록 할 테니까요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7837] = {title = "룬무늬 옷감 추가 기부", objective = "<name>, 다시 찾아주다니 이렇게 고마울 데가! 룬무늬 옷감은 늘 부족한 형편이라 기부할 생각만 있다면 언제든지 감사히 받겠어요. 룬무늬 옷감 20개를 추가로 기부해 준다면 제가 검은창 <race> 전체를 대신해 당신의 계속된 노고가 확실히 인정받도록 애쓰겠어요.\n\n룬무늬 옷감을 추가로 기부할 마음이 있으시다면 언제든지 받도록 하죠.", description = nil, progress = "<name>, 다시 찾아주다니 이렇게 고마울 데가! 룬무늬 옷감은 늘 부족한 형편이라 기부할 생각만 있다면 언제든지 감사히 받겠어요. 룬무늬 옷감 20개를 추가로 기부해 준다면 제가 검은창 <race> 전체를 대신해 당신의 계속된 노고가 확실히 인정받도록 애쓰겠어요.\n\n룬무늬 옷감을 추가로 기부할 마음이 있으시다면 언제든지 받도록 하죠.", completion = "&lt;name&gt;, 우리 검은창 &lt;race&gt;을 위해 수고해 주는 당신 같은 영웅들이 없었더라면 우린 분명 고생을 면치 못했을 거예요. 계속된 노고에 정말 감사 드립니다!", rewards = nil},
[7838] = {title = "최고검투사의 징표", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n최고검투사의 징표"},
[7839] = {title = "썩은가지부족 불량배", objective = "동부 내륙지의 레반터스크 마을에 있는 대장장이 슬래그트리에게 슬래그트리의 잃어버린 연장을 찾아 되찾아줘야 합니다.\n\n대장장이 슬래그트리의 말에 의하면 그 도구들은 동부 내륙지의 북동쪽 지역에 있는 썩은가지부족 신전들 중 하나에 있을 것이라고 얘기했으며 굼벵이 바위굴도 조사해 보는 것이 좋겠습니다.", description = "쓰레기 같은 썩은가지부족 녀석들이 우리 마을에 쳐들어와서는 내 도구들을 훔쳐가 버렸소! 예비 도구들이 있긴 하지만 녀석들이 훔쳐간 도구는 내가 어렸을 때 목숨을 구해 준 어떤 마음씨 착한 노움이 준 선물이란 말이오.\n\n내게 그 무엇보다 소중한 그 도구들을 되찾고 싶소이다.\n\n마코르의 보고에 의하면 그 도구들은 아골와타와 샤올와타 신전 근처에서 발견되었다고 하오. 그 신전들은 동부 내륙지의 북동부 지역에 있소. 내 도구들을 되찾아 주시오!", progress = "그 지역의 썩은가지부족 트롤들을 조심하시오. 녀석들은 무자비하고 흉악한 쓰레기들이오.", completion = "내 도구! 찾았군! 아, 이런 경사가...! 고맙소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7840] = {title = "잃어버린 라드의 점심", objective = "동부 내륙지의 레반터스크 마을에 있는 라드에게 라드의 점심을 가져가야 합니다.\n\n라드가 점심을 북쪽에 있는 섬에 두고왔다고 했습니다. 썩은가지부족 트롤을 조심하십시오.", description = "라드 비밀 장소에서 소풍하고 있는데 못생기고 나쁜 썩은가지부족 트롤이 커다란 막대기로 라드 때렸다. 라드 레반터스크로 도망쳐서 돌아왔는데 점심 두고 왔다. 라드 배고프다. 네가 특별한 비밀 장소로 가서 라드 점심 가져오지 않을래? 라드 무섭다. 북쪽으로 가라! 저기 북쪽에 있는 섬에 특별한 비밀 장소 있다.", progress = "<거대한 배를 문지르는 라드>\n\n라드 너무 배고프다.", completion = "&lt;커다란 다리 고기를 받아 얼굴을 묻고 게걸스럽게 먹어대는 라드&gt;\n\n아, 좋다! 고맙다, 꼬마.\n\n라드 도와 줬으니 특별한 소풍용 바구니 만들어 준다.", rewards = "다음과 같은 것들을 받습니다:\n\n라드의 특별한 소풍용 바구니"},
[7841] = {title = "첫 번째 통첩장", objective = "깊은골짜기 길잡이 15명, 깊은골짜기 정찰대 15명, 깊은골짜기 명사수 15명, 그리고 깊은골짜기 순찰대 15명을 처치한 후 동부 내륙지의 레반터스크 마을에 있는 오토 모지코에게 돌아가야 합니다.\n\n깊은골짜기 하이 엘프들은 동부 내륙지 북서쪽 지역에 있는 쿠엘다닐 오두막에 있습니다.", description = "와일드해머 드워프들이 우리 적들과 거래를 하고 새로운 동맹을 맺고 있네. 이번에는 하이 엘프들과 손을 잡은 모양이야.\n\n<침을 뱉는 오토>\n\n와일드해머 드워프 녀석들에게 우리 적들의 피로 통첩장을 보내야겠네. 깊은골짜기 하이 엘프를 만나는 대로 모조리 처치하고 경고 삼아 그 시체들을 내버려두게.\n\n감히 트롤들에게 덤벼서는 안 되지!", progress = nil, completion = "이제 우리 레반터스크도 새로운 동맹을 맺게 되는 모양이군! 잘 해 주었네.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7842] = {title = "또 다른 통첩장", objective = "동부 내륙지의 레반터스크 마을에 있는 오토 모지코에게 동부 내륙지에 서식하는 그리핀을 처치하고 길고 고운 깃털 10개를 가져가야 합니다.\n\n그리핀들은 동부 내륙지 전역에 서식하는 것으로 알려져 있습니다.", description = "와일드해머 드워프들과 그리핀은 트롤과 랩터가 친한만큼이나 가까운 관계라고 하지. 역겨운 일이긴 하지만 우리에게 유리하게 이용할 수 있다네. 또 다른 통첩장을 보내는 거지.\n\n동부 내륙지에서 눈에 띄는 그리핀을 모조리 처치하고 그 깃털을 모아 오게. 그걸로 최후 통첩장을 만들 것이야.", progress = "최후 통첩장을 보면 틀림없이 녀석들이 겁을 먹고 도망치겠지. 아니면 아주 엄청나게 분노하든가 말이야.", completion = "이야, 이거 괜찮겠는데. 이제 한 단계만 더 거치면 와일드해머 드워프들이 감히 트롤족에게 함부로 덤벼선 안 된다는 걸 깨닫게 될 거야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7843] = {title = "최후통첩장", objective = "동부 내륙지 서쪽 지역에 있는 맹금의 봉우리로 가서 마을 중앙에 있는 우물 옆에 와일드해머일족에게 보내는 최후통첩장을 전달한 후, 레반터스크 마을에 있는 오토 모지코에게 돌아가야 합니다.\n\n분노하는 와일드해머 드워프들과 난폭한 얼라이언스 일원들을 조심하십시오.", description = "<그리핀 깃털 몇 개가 감싸고 있는 피에 흠뻑 젖은 긴 창을 건네주는 오토>\n\n자, 받게. 맹금의 봉우리, 마을 정중앙 우물 옆으로 이걸 가져가서 꽂게. 땅에 콱 박아 버리라고! 저 드워프 녀석들에게 트롤들이 장난을 치고 있는 게 아니라는 걸 보여 주게! 이 일이 끝나거든 내게 돌아오게나. 살아서 돌아온다면 좋겠군.", progress = nil, completion = "내가 녀석들의 표정을 직접 볼 수 있었더라면 좋았을 텐데 아쉽군. 녀석들이 짐을 싸서 마을을 떠나고 있나?\n\n잘 해 줬네. 정말 잘 했어. 이 오토가 보상으로 왕모조를 주지.", rewards = "다음과 같은 것들을 받습니다:\n\n올빼미야수 가죽 장갑"},
[7844] = {title = "동족을 잡아먹는 사촌", objective = "썩은가지부족 무두장이 30명과 썩은가지부족 예언자 15명을 처치하고 동부 내륙지의 레반터스크 마을에 있는 비술사 야요진에게 돌아가야 합니다.\n\n야요진은 이 트롤들이 동부 내륙지의 북동부 지역에 있는 샤올와타 및 아골와타 신전 근처에 있다고 가르쳐 주었습니다.", description = "동부 내륙지에는 서로 다른 세 트롤 부족이 살고 있답니다. 이 세 부족 간의 닮은 점이라고는 모두 트롤이고 동부 내륙지에 산다는 것밖에 없죠.\n\n썩은가지부족이라 불리는 트롤들은 그 이름에 잘 드러나듯이 아주 타락한 집단입니다. 그들은 다른 트롤들과 인간형 생물들을 잡아먹고 살거든요.\n\n줄진님께서 여기 계셨더라면 손목 한번 까딱하는 것만으로도 녀석들을 모두 쓸어버렸을 텐데... 안타깝게도 줄진님께서 아직 돌아오시지 않았으니 우리가 어떻게든 알아서 해결할 수밖에 없답니다.\n\n이 지역의 쓰레기 같은 녀석들을 처리하는 것을 당신에게 맡기겠어요!", progress = nil, completion = "아주 잘 하셨어요. 줄진님께서도 이보다 더 잘 해내진 못하셨을 거예요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7845] = {title = "납치된 장로 쏜터스크!", objective = "동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크가 그녀의 남편인 장로 쏜터스크를 진타알로에서 구해 달라고 부탁했습니다.\n\n장로 쏜터스크는 동부 내륙지의 남쪽에 위치한 썩은가지부족의 수도인 진타알로의 꼭대기에 갇혀 있다고 합니다.", description = "무식한 썩은가지부족 녀석들이 대담하게도 한밤중에 우리 마을에 쳐들어 와서 내 남편을 납치했어요. 우리 첩자에 의하면 내 남편이 아직 죽지 않고 진타알로 꼭대기에 갇혀 있다고 합니다. 타락한 여사제 헥스가 내 남편을 실체 없는 혈신 학카르에게 제물로 바칠 거라고 합니다.\n\n내 남편을 꼭 구해 주십시오! 그는 우리 마을에 반드시 필요한 존재입니다.", progress = nil, completion = "자네가 나타났다는 걸 경비병들이 분명히 알고 있을 것이니 서둘러야 하네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7846] = {title = "열쇠를 찾아서", objective = "수호자 히타야를 죽이고 족쇄 열쇠를 찾아서 진타알로에 갇혀 있는 장로 쏜터스크에게 돌아가야 합니다.", description = "수호자 히타야가 가지고 있는 열쇠가 있어야만 족쇄를 풀 수가 있네. 그녀는 동굴 근처에 있네만 경비병이 호위하고 있으니 조심하는 게 좋아.\n\n내가 집에 돌아갈 수 있도록 그녀를 죽이고 열쇠를 가지고 와서 날 풀어 주게.", progress = "서두르게!", completion = "드디어 자유로군! 고맙네. 레반터스크에서도 자네의 용기에 감탄할 걸세!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[7847] = {title = "주술사 쏜터스크에게로", objective = "장로 쏜터스크가 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가서 자신이 진타알로에서 풀려났다는 사실을 전해 달라고 부탁했습니다.", description = "레반터스크 마을에 있는 내 아내 주술사 쏜터스크에게 돌아가게. 그리고 나도 곧 돌아갈 거라고 전해 주게! 물론 그녀가 자네에게 보상을 할 걸세.", progress = nil, completion = "레반터스크를 대표해서 감사 드립니다! 당신에게 정말 큰 빚을 졌습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n고원의 활숲 모조 물약\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7848] = {title = "심장부와의 조화", objective = "검은바위 나락의 화산 심장부 입구에 있는 차원의 문으로 가서 핵 조각을 하나 찾아야 합니다. 핵 조각을 가지고 검은바위 산에 있는 로소스 리프트웨이커에게로 돌아가십시오.", description = "<race>|1이여;여;, 우리 주변의 모든 것에는 균열이 생기고 흔들리며 무너져갑니다. 여기서 불과 두 발짝도 떨어지지 않은 곳에 검은바위 산의 심연으로 통하는 균열이 있다면 믿어지십니까? 바로 불의 군주의 입으로 통하지요.\n\n놀라셨나요? 애석한 일이로군요... 필멸의 생명체들은 자신이 보고, 만지고 느낄 수 있는 것이 아니면 전혀 이해하지 못하니 말입니다.\n\n분명히 말해두는데, 차원의 문은 정말로 존재하며 안으로 들어갈 수도 있습니다.\n\n귀가 솔깃해지셨나요? 방법은 간단합니다. 검은바위 나락으로 가서 핵 조각을 하나 가져오기만 하면 되죠. 제게 돌아오시면 그대의 정기를 차원의 문과 조화시켜 드리겠습니다.", progress = "화산 심장부와 당신의 영혼을 조화시켜야 합니다. 그래야 진입하실 수 있습니다.", completion = "이제 화산 심장부로 순간이동하실 수 있습니다. 준비되면 말씀만 하십시오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n심장부와의 조화\n\n다음과 같은 것들을 받습니다:\n\n"},
[7849] = {title = "동생의 유골", objective = "레반터스크 마을의 사냥꾼 마코르에게 쌍둥이 동생인 말코르의 해골을 찾아서 가져가야 합니다.\n\n마코르가 말하기를 썩은가지부족의 수액괴물과 늑대들이 동생의 유골을 훼손하고 있다고 합니다. 또한 진타알로의 신전 근처에는 수액괴물이 가득한 쓰레기 폐허와 늑대 우리가 있다고 합니다.", description = "우리 마을의 다른 이들처럼 나도 사랑하는 이를 그 야만인들에게 잃었소. 불쌍한 것! 내 쌍동이 동생 말코르도 주술사이신 쏜터스크님의 남편처럼 썩은가지부족이 습격했을 때 납치되었소. 그리고 불행히도 잔인한 방법으로 살해되었지. 지금은 썩은가지부족의 수액괴물과 늑대들이 동생의 유골을 훼손하고 있소이다.\n\n동생의 목숨은 구하지 못했지만 영혼은 아직 구할 수 있을 거요. 당신이 동생의 유골을 수습해 주시오.", progress = "동생의 유골을 찾으면 야요진에게 가져가서 좋은 묘지를 만들어 달라고 할 것이오.", completion = "사랑하는 동생아, 얼마나 보고 싶었는데...\n\n도와줘서 정말 고맙소. 당신은 진정한 영웅이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n칠목기 판금 다리갑옷푸른잎사귀 장갑\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7850] = {title = "어둠의 용기", objective = "진타알로에서 얼룩진 피가 담긴 용기 10개를 찾아 동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크에게 돌아가야 합니다.", description = "썩은가지부족이 그렇게 흉포한 건 바로 타락한 여사제 헥스가 만든 이상한 물건 때문입니다.\n\n진타알로를 잘 찾아보면 얼룩진 피가 담긴 용기를 찾을 수 있을 겁니다. 얼룩진 피가 담긴 용기는 실체 없는 혈신의 타락한 마법을 내뿜고 있는데 이 기운이 썩은가지부족에게 힘을 주고 이성을 상실하게 하는 것입니다.\n\n나쁜 기운을 정화하고 실체 없는 혈신의 음모를 막을 수 있도록 얼룩진 피가 담긴 용기를 가져오세요.", progress = "썩은가지부족과 싸울 때는 조심해야 합니다. 그들은 이성을 상실했기에 죽을 때까지 멈추지 않아요.", completion = "이제 썩은가지부족을 조종하던 어둠의 기운이 사라졌어요. 하지만 악의 세력과의 전쟁이 끝난 건 아니니 긴장을 늦추지 마십시오. 타락한 여사제를 죽인다고 해도 누군가 그녀의 자리를 대신할 테니까요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n자연의 숨결"},
[7861] = {title = "현상수배: 타락한 여사제 헥스와 그녀의 부하", objective = "타락한 여사제 헥스와 썩은가지부족 아만자시 경비병 20명을 해치운 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크와 대화해야 합니다.\n\n동부 내륙지의 진타알로 꼭대기에 가면 타락한 여사제 헥스와 아만자시 경비병을 찾을 수 있습니다.", description = "주술사 쏜터스크님의 명령으로 타락한 여사제 헥스와 그녀의 부하를 현상 수배한다!\n\n타락한 여사제 헥스와 그녀의 아만자시 정예 경비병을 모두 해치우는 자에게는 엄청난 상금이 지급될 것이다.", progress = nil, completion = "수고했습니다. 썩은가지부족에게 타격이 크겠군요. 자, 여기 보상을 받으세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n상아고리 목걸이깊은숲속 망토\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7862] = {title = "구인광고: 레반터스크 마을의 경비대장", objective = "썩은가지부족 광전사 20명, 썩은가지부족 어둠사냥꾼 20명, 썩은가지부족 혈투사 20명, 썩은가지부족 영혼사냥꾼 20명을 처치한 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가야 합니다.", description = "경비대장이었던 말코르의 죽음으로 현재 레반터스크의 경비대장 자리가 공석으로 남아있다. 레반터스크의 경비대장을 맡고 싶은 자는 다음 시험을 통과한 다음 주술사 쏜터스크님에게 신청서를 제출하도록 하라.\n\n썩은가지부족 광전사 처치\n썩은가지부족 어둠사냥꾼 처치\n썩은가지부족 혈투사 처치\n썩은가지부족 영혼사냥꾼 처치", progress = nil, completion = "당신은 새로운 경비대장이 될 자격이 충분하군요. 약소하지만 어려운 일을 해낸 것에 대한 보답입니다. 다른 신청서는 내년에 읽기로 하죠.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n수호대장의 룬"},
[7863] = {title = "기본 파수대 구급품", objective = "실력을 확실히 보여 주기 시작했군요. 자, 이 구급품을 받으세요! 안에 든 식료품과 붕대는 전쟁노래 협곡에서만 사용할 수 있답니다.\n\n전쟁노래 협곡에서 전투를 계속해서 우리의 신임을 얻다 보면 식료품과 붕대를 구입할 수도 있게 될 겁니다. 식료품은 약간 우호적인 평판을, 붕대는 우호적인 평판을 얻으면 살 수 있게 됩니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n기본 파수대 구급품"},
[7864] = {title = "일반 파수대 구급품", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n일반 파수대 구급품"},
[7865] = {title = "고급 파수대 구급품", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n고급 파수대 구급품"},
[7866] = {title = "기본 정찰대 구급품", objective = "<name>, 실력을 확실히 보여 주기 시작했군. 자, 이 구급품을 받게! 안에 든 식량과 붕대는 전쟁노래 협곡에서만 사용할 수 있다네.\n\n전쟁노래 협곡에서 전투를 계속해서 우리의 신임을 얻다 보면 식량과 붕대를 구입할 수도 있게 될 걸세. 식량은 약간 우호적인 평판을, 붕대는 우호적인 평판을 얻으면 살 수 있어.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n기본 정찰대 구급품"},
[7867] = {title = "일반 정찰대 구급품", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n일반 정찰대 구급품"},
[7868] = {title = "고급 정찰대 구급품", objective = "<name>, 실력을 확실히 보여 주기 시작했군. 자, 이 구급품을 받게! 안에 든 식량과 붕대는 전쟁노래 협곡에서만 사용할 수 있다네.\n\n전쟁노래 협곡에서 전투를 계속해서 우리의 신임을 얻다 보면 식량과 붕대를 구입할 수도 있게 될 걸세. 식량은 약간 우호적인 평판을, 붕대는 우호적인 평판을 얻으면 살 수 있어.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n고급 정찰대 구급품"},
[7871] = {title = "침략자 처단!", objective = "전쟁노래 협곡으로 들어가 호드를 무찌르고 전쟁노래 협곡 명예 훈장을 얻어 은빛날개 숲에 있는 파수꾼 파송에게 돌아가야 합니다.", description = "젊은 <class>|1이여;여;, 이 터널 너머에서 그대는 투쟁과 동요의 현장을 경험하게 될 것입니다. 호드는 신성한 숲을 더럽히고 울창한 푸른 나무들을 베어내며 자신들의 전쟁 기계를 가동시키는 동력으로 사용하고 있습니다.\n\n이 길을 따라 전쟁노래 협곡으로 가서 은빛날개 요새를 지켜 주십시오. 침략자인 호드 군대를 이 땅에서 몰아내 주십시오!\n\n호드를 몰아내고 무공 훈장을 얻으십시오. 훈장을 가져오시면 보상을 지급하겠습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7872] = {title = "침략자 처단!", objective = "전쟁노래 협곡으로 들어가 호드를 무찌르고 전쟁노래 협곡 명예 훈장을 얻어 은빛날개 숲에 있는 파수꾼 파송에게 돌아가야 합니다.", description = "젊은 <class>|1이여;여;, 이 터널 너머에서 그대는 투쟁과 동요의 현장을 경험하게 될 것입니다. 호드는 신성한 숲을 더럽히고 울창한 푸른 나무들을 베어내며 자신들의 전쟁 기계를 가동시키는 동력으로 사용하고 있습니다.\n\n이 길을 따라 전쟁노래 협곡으로 가서 은빛날개 요새를 지켜 주십시오. 침략자인 호드 군대를 이 땅에서 몰아내 주십시오!\n\n호드를 몰아내고 무공 훈장을 얻으십시오. 훈장을 가져오시면 보상을 지급하겠습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7873] = {title = "침략자 처단!", objective = "전쟁노래 협곡으로 들어가 호드를 무찌르고 전쟁노래 협곡 명예 훈장을 얻어 은빛날개 숲에 있는 파수꾼 파송에게 돌아가야 합니다.", description = "젊은 <class>|1이여;여;, 이 터널 너머에서 그대는 투쟁과 동요의 현장을 경험하게 될 것입니다. 호드는 신성한 숲을 더럽히고 울창한 푸른 나무들을 베어내며 자신들의 전쟁 기계를 가동시키는 동력으로 사용하고 있습니다.\n\n이 길을 따라 전쟁노래 협곡으로 가서 은빛날개 요새를 지켜 주십시오. 침략자인 호드 군대를 이 땅에서 몰아내 주십시오!\n\n호드를 몰아내고 무공 훈장을 얻으십시오. 훈장을 가져오시면 보상을 지급하겠습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7874] = {title = "은빛날개 분쟁 진압", objective = "전쟁노래 협곡으로 진입하여 얼라이언스 진영을 무찌르고 전쟁노래 협곡 명예 훈장을 얻어 몰샨 주둔지에 있는 부대장 쉐터스컬에게 가져가야 합니다.", description = "<race>|1이여;여;, 잿빛 골짜기는 호드의 힘 앞에 무릎을 꿇을 것이다. 은빛날개 파수대의 어떠한 행동도 우리의 절대 사명을 막을 수는 없다. 칼림도어는 원래 우리 호드의 것이다! 그런데 감히 누가 우리의 앞을 가로막는단 말인가?!\n\n가슴에 긍지와 용기를 불어넣어 우리를 가로막는 적들을 뿌리 뽑도록! 은빛날개 파수꾼들을 처치하고 전쟁노래 명예 훈장을 가져오라. 보상이 지급될 것이다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7875] = {title = "은빛날개 분쟁 진압", objective = "전쟁노래 협곡으로 진입하여 얼라이언스 진영을 무찌르고 전쟁노래 협곡 명예 훈장을 얻어 몰샨 주둔지에 있는 부대장 쉐터스컬에게 가져가야 합니다.", description = "<race>|1이여;여;, 잿빛 골짜기는 호드의 힘 앞에 무릎을 꿇을 것이다. 은빛날개 파수대의 어떠한 행동도 우리의 절대 사명을 막을 수는 없다. 칼림도어는 원래 우리 호드의 것이다! 그런데 감히 누가 우리의 앞을 가로막는단 말인가?!\n\n가슴에 긍지와 용기를 불어넣어 우리를 가로막는 적들을 뿌리 뽑도록! 은빛날개 파수꾼들을 처치하고 전쟁노래 명예 훈장을 가져오라. 보상이 지급될 것이다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7876] = {title = "은빛날개 분쟁 진압", objective = "전쟁노래 협곡으로 진입하여 얼라이언스 진영을 무찌르고 전쟁노래 협곡 명예 훈장을 얻어 몰샨 주둔지에 있는 부대장 쉐터스컬에게 가져가야 합니다.", description = "<race>|1이여;여;, 잿빛 골짜기는 호드의 힘 앞에 무릎을 꿇을 것이다. 은빛날개 파수대의 어떠한 행동도 우리의 절대 사명을 막을 수는 없다. 칼림도어는 원래 우리 호드의 것이다! 그런데 감히 누가 우리의 앞을 가로막는단 말인가?!\n\n가슴에 긍지와 용기를 불어넣어 우리를 가로막는 적들을 뿌리 뽑도록! 은빛날개 파수꾼들을 처치하고 전쟁노래 명예 훈장을 가져오라. 보상이 지급될 것이다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7877] = {title = "셴드랄라의 보물", objective = "도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!", description = "도서관에 가면 계단 밑에 오래된 궤짝이 하나 있는데, 그 안에서 원하는 걸 골라가도록 하게.", progress = nil, completion = "궤짝을 열어보니 안에 보물이 들어 있습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n해골 파쇄기등나무 투구이삭 장화\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[7881] = {title = "축제용 장화", objective = "다크문 유랑단에서 일하려면 많이 걸어야 하오. 이곳에서 저곳으로 계속 옮겨다녀야 하니까... 사실, 앉아서 일하는 경우가 전혀 없소! 그러니까 장화가 쉽게 닳아 버리는 것도 놀랄 일은 아니지! 그래서 우리는 질기면서도 멋진 장화가 필요하오. 새김무늬 가죽 장화가 바로 그런 괜찮은 장화지.\n\n참, 당신! 당신은 가죽세공사가 아니오? 새김무늬 가죽 장화를 만들어 주시오. 그러면 그 대가로 다크문 축제 상품권을 주겠소.", description = nil, progress = "다크문 유랑단에서 일하려면 많이 걸어야 하오. 이곳에서 저곳으로 계속 옮겨다녀야 하니까... 사실, 앉아서 일하는 경우가 전혀 없소! 그러니까 장화가 쉽게 닳아 버리는 것도 놀랄 일은 아니지! 그래서 우리는 질기면서도 멋진 장화가 필요하오. 새김무늬 가죽 장화가 바로 그런 괜찮은 장화지.\n\n참, 당신! 당신은 가죽세공사가 아니오? 새김무늬 가죽 장화를 만들어 주시오. 그러면 그 대가로 다크문 축제 상품권을 주겠소.", completion = "고맙소. 정말 잘 만들어진 장화로군. 솜씨가 정말 최고로구만! 자, 여기 다크문 축제 상품권을 받으시오. 재미있게 즐기시길...", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7882] = {title = "축제용 웃옷", objective = "우리 유랑단 일꾼들은 쓰레기 치우고 못을 박는 일 말고도 더 많은 일을 하고 있지! 축제가 이동할 때 경비병 역할을 담당하기 때문에 항상 튼튼하고 좋은 갑옷 웃옷이 필요하지.\n\n질긴 가죽 갑옷을 몇 벌 만들어 내게 가져오면 꼭 필요한 사람들에게 전해 주리다. 또 그 대가로 다크문 축제 상품권을 몇 장 주겠소.", description = nil, progress = "우리 유랑단 일꾼들은 쓰레기 치우고 못을 박는 일 말고도 더 많은 일을 하고 있지! 축제가 이동할 때 경비병 역할을 담당하기 때문에 항상 튼튼하고 좋은 갑옷 웃옷이 필요하지.\n\n질긴 가죽 갑옷을 몇 벌 만들어 내게 가져오면 꼭 필요한 사람들에게 전해 주리다. 또 그 대가로 다크문 축제 상품권을 몇 장 주겠소.", completion = "아, 가져왔구만! 혹시 어떤 동물의 가죽으로 만들었는지 물어 봐도 되겠소? 바느질도 아주 잘 되어 있고 가죽의 질감도 옹골차군. 당신, 솜씨가 정말 대단하군!\n\n고맙소. 자, 상품권을 받으시오.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7883] = {title = "세계에서 가장 큰 노움!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7884] = {title = "새끼 악어와 수염 난 멀록", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7885] = {title = "방어구 키트", objective = "아마 당신은 모르겠지만 다크문 축제를 순회하며 운영하는 데는 비용이 아주 많이 든다오! 모든 장비가 워낙 빨리 마모되다 보니 흑자를 낸다는 것 자체가 놀라울 정도지.\n\n이런 남모를 비용 때문에 우리는 늘 장비를 가능한 한 저렴한 비용으로 유지 관리할 수 있는 방법을 찾고 있소. 예를 들어, 천막은 자주 찢어지지만 가죽 방어구 키트를 사용하면 훌륭하게 수선할 수 있다오. 그래서 말인데, 방어구 키트를 좀 구해다 주지 않겠소? 그러면 엄청난 비용을 절약할 수 있다오! 도와 준다면 다크문 축제 상품권을 뭉치째 주도록 하지.", description = nil, progress = "아마 당신은 모르겠지만 다크문 축제를 순회하며 운영하는 데는 비용이 아주 많이 든다오! 모든 장비가 워낙 빨리 마모되다 보니 흑자를 낸다는 것 자체가 놀라울 정도지.\n\n이런 남모를 비용 때문에 우리는 늘 장비를 가능한 한 저렴한 비용으로 유지 관리할 수 있는 방법을 찾고 있소. 예를 들어, 천막은 자주 찢어지지만 가죽 방어구 키트를 사용하면 훌륭하게 수선할 수 있다오. 그래서 말인데, 방어구 키트를 좀 구해다 주지 않겠소? 그러면 엄청난 비용을 절약할 수 있다오! 도와 준다면 다크문 축제 상품권을 뭉치째 주도록 하지.", completion = "좋아! 이거면 훌륭해! 좀 전에 저쪽에서 천막이 찢어진 걸 봤는데 이 방어구 키트 중 하나만 있으면 충분히 수선할 수 있겠소!\n\n정말 고맙소. 이 방어구 키트 덕분에 수리비를 크게 절약할 수 있게 되었소이다. 자, 상품권을 받으시오. 당신은 이 정도 보상을 받을 자격이 충분하오!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
