[7898] = {title = "토륨 부품", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7899] = {title = "작은 앞발", objective = "신기한 물건과 장신구로 유혹하는 게 대중을 끌어 모으는 가장 기본적인 방법이죠! 좀 도와 주실 수 있나요?\n\n상품으로 사용할 작은 앞발이 필요해요. 불모의 땅이나 어둠의 해안에 사는 사자들에게서 구할 수 있지요...\n\n앞발을 좀 가져오면 다크문 축제 상품권으로 바꿔 드리죠.", description = nil, progress = "신기한 물건과 장신구로 유혹하는 게 대중을 끌어 모으는 가장 기본적인 방법이죠! 좀 도와 주실 수 있나요?\n\n상품으로 사용할 작은 앞발이 필요해요. 불모의 땅이나 어둠의 해안에 사는 사자들에게서 구할 수 있지요...\n\n앞발을 좀 가져오면 다크문 축제 상품권으로 바꿔 드리죠.", completion = "좋아요, 앞발을 가져왔군요! 이걸로 장난감과 인형을 만들어서 더 많은 사람을 축제에 모이게 할 수 있을 거예요!\n\n일을 해 주셨으니 보답으로 이 상품권을 받으세요!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7900] = {title = "찢어진 곰 모피", objective = "아이들은 장난감을 정말 좋아하죠! 종족이 어떻든 모든 아이들은 찢어진 곰 모피로 만든 털 많고 화려한 장난감을 좋아한다는 걸 알게 됐어요!\n\n잿빛 골짜기나 힐스브래드 구릉지에 사는 곰에게서 그 모피를 구할 수 있지요. 모피 뭉치를 가져오면 다크문 축제 상품권 뭉치로 교환해 드리죠!", description = nil, progress = "아이들은 장난감을 정말 좋아하죠! 종족이 어떻든 모든 아이들은 찢어진 곰 모피로 만든 털 많고 화려한 장난감을 좋아한다는 걸 알게 됐어요!\n\n잿빛 골짜기나 힐스브래드 구릉지에 사는 곰에게서 그 모피를 구할 수 있지요. 모피 뭉치를 가져오면 다크문 축제 상품권 뭉치로 교환해 드리죠!", completion = "멋진 모피군요! 누굴 시켜서 이 모피를 바느질해 화려한 장난감을 많이 만들도록 할 거예요. 약간의 장식과 색칠을 더하면 아제로스의 모든 아이들이 갖고 싶어하는 장난감이 될 거예요!\n\n상품권이요? 아 물론, 드려야죠. 자, 여기 있어요!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7901] = {title = "텁수룩한 꼬리", objective = "사람들이 무엇을 가치있게 여기는지를 보면 정말 놀라워요! 자, 예를 들어 나무 막대기에 텁수룩한 꼬리를 붙였다고 쳐요. 그럼, 당신이나 나 같으면 그런 건 별로 가치가 없다고 생각하겠죠? 하지만 그런 보잘것없는 물건에 \"천년 묵은 구미호 꼬리\"처럼 그럴 듯한 이름을 붙이고 예쁜 상자에 넣어 포장하면 사람들은 그걸 가치있게 여긴다고요. 쓰레기가 보물이 되는 거죠!\n\n잊혀진 땅과 황야의 땅에 사는 늑대에게서 텁수룩한 꼬리를 가져오세요. 그러면 그 대가로 다크문 축제 상품권을 드리도록 하죠.", description = nil, progress = "사람들이 무엇을 가치있게 여기는지를 보면 정말 놀라워요! 자, 예를 들어 나무 막대기에 텁수룩한 꼬리를 붙였다고 쳐요. 그럼, 당신이나 나 같으면 그런 건 별로 가치가 없다고 생각하겠죠? 하지만 그런 보잘것없는 물건에 \"천년 묵은 구미호 꼬리\"처럼 그럴 듯한 이름을 붙이고 예쁜 상자에 넣어 포장하면 사람들은 그걸 가치있게 여긴다고요. 쓰레기가 보물이 되는 거죠!\n\n잊혀진 땅과 황야의 땅에 사는 늑대에게서 텁수룩한 꼬리를 가져오세요. 그러면 그 대가로 다크문 축제 상품권을 드리도록 하죠.", completion = "잘했어요! 이 꼬리는 우리 방문객들을 위한 썩 괜찮은 상품이 될 거예요. 그걸 받으면 모두 기뻐하면서 친구들에게 자랑할 테고... 그러면 방문객이 더 늘어나겠죠!\n\n자, 이 상품권은 당신 거예요! 다크문 축제에서 즐거운 시간 보내길 바래요... 물론 친구들한테 우릴 홍보하는 것도 잊지 말고요!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7902] = {title = "흩날리는 솜깃털", objective = "사람의 상상력이란 정말 놀라워요. 상상 속에서는 아주 작은 언덕도 제일 큰 산처럼 만들 수도 있고, 아무것도 아닌 그림자가 끔찍한 악몽 속에 나오는 괴물처럼 보이게 할 수도 있으니까요!\n\n다크문 유랑단에서는 방문객이 상상의 나래를 펼칠 수 있도록 해 주죠! 하지만 상상력을 펼칠 수 있도록 하기 위해서는... 때때로 우리 나름의 작전이 필요하답니다.\n\n그래서 말인데, 흩날리는 솜깃털이 필요해요. 아제로스 대륙에서 좀 위험한 지역에 사는 새들에게서 구할 수 있어요. 솜깃털을 가져오면 상품권을 많이 드리도록 하죠!", description = nil, progress = "사람의 상상력이란 정말 놀라워요. 상상 속에서는 아주 작은 언덕도 제일 큰 산처럼 만들 수도 있고, 아무것도 아닌 그림자가 끔찍한 악몽 속에 나오는 괴물처럼 보이게 할 수도 있으니까요!\n\n다크문 유랑단에서는 방문객이 상상의 나래를 펼칠 수 있도록 해 주죠! 하지만 상상력을 펼칠 수 있도록 하기 위해서는... 때때로 우리 나름의 작전이 필요하답니다.\n\n그래서 말인데, 흩날리는 솜깃털이 필요해요. 아제로스 대륙에서 좀 위험한 지역에 사는 새들에게서 구할 수 있어요. 솜깃털을 가져오면 상품권을 많이 드리도록 하죠!", completion = "아, 솜깃털이로군요! 정말 멋지지 않나요? 이렇게 아름다운 솜깃털이라면 사람들의 상상력을 자극하는 데 큰 도움이 될 거예요!\n\n정말 좋은 일을 하신 거예요. 덕분에 쇼를 보러 온 방문객들의 얼굴에 미소가 피어날 수 있게 되었으니까요. 그건 정말 큰 보람이죠. 하지만 이 상품권도 함께 받으세요.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7903] = {title = "더러운 박쥐 눈", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7905] = {title = "다크문 축제", objective = "다크문 축제가 열리고 있는 장소로 가서 겔바스 그림게이트에게 무료 상품 교환권을 제출해야 합니다.", description = "다크문 축제가 열리고 있습니다! 놀랍고 신기한 구경거리들이 가득하니 하나도 놓치지 마십시오!\n\n자, 무료 상품 교환권을 받으십시오. 이 교환권을 다크문 축제의 겔바스 그림게이트에게 가져가면 됩니다.\n\n지금 유랑단이 엘윈 숲의 골드샤이어 외곽에 도착했으니 놓치지 마세요! 바로 오늘 가보십시오!", progress = "어서 오게. 도움이 필요한가? 혹시 교환권을 가져온 건가?", completion = "다크문 축제에 온 걸 환영하네! 이거면 축제 상품권을 다섯 개... 그래! 무려 다섯 개나 받을 수 있어!\n\n축제 상품권을 있는대로 모아서 가져오라고! 좋은 상품으로 교환해 줄 테니까. 많이 모아올수록 당연히 상품도 더 많이 받을 수 있지. 정말 신나지 않나?!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7907] = {title = "다크문 야수 카드", objective = "다크문 유랑단이 마을에 오면 야수 카드 한벌을 돌려줘야 합니다.", description = "이제 야수 카드를 모두 모아 한 벌이 완성되자 신기하게도 처음 여덟 개와 뒷면 모양이 똑같은 아홉 번째 카드가 나타납니다. 이 카드에는 \"이 카드들을 다크문 축제 상품 교환원에게 돌려주면 보상을 받을 것입니다.\"라고 적혀 있습니다. 다크문 유랑단은 몇 달에 한 번씩 멀고어와 골드샤이어를 번갈아 가며 들른다고 합니다. 다음에 유랑단이 이곳에 올 때까지 기다려야 합니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 카드: 푸른용"},
[7908] = {title = "검투사", objective = "가시덤불 골짜기에 원형투기장에 있는 땅딸보 존 미스릴과 대화하십시오.\n\n제공된 아이템: \n", description = "검투사가 되는게 이렇게 간단할 리 없습니다! 구루바시에서 행사를 운영하는 해적단원이 더 알지도 모릅니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[7926] = {title = "다크문 축제", objective = "다크문 축제가 열리고 있는 장소로 가서 겔바스 그림게이트에게 무료 상품 교환권을 제출해야 합니다.", description = "다크문 축제가 열린다오! 무척이나 놀랍고 신기한 구경거리가 가득하니 하나도 놓치지 마시오!\n\n자, 다크문 축제 상품권으로 교환할 수 있는 무료 상품 교환권을 드리겠소. 이걸 다크문 유랑단의 겔바스 그림게이트에게 가져가시오.\n\n지금 썬더 블러프 외곽 멀고어에서 열리고 있으니 기회를 놓치지 마시오! 바로 오늘 가보시오!", progress = "어서 오게. 내 도움이 필요한가? 혹시 무료 상품 교환권을 가져왔나?", completion = "다크문 축제에 온 걸 환영하네! 이 교환권이면 다크문 축제 상품권을 다섯 개... 그래! 무려 다섯 개나 받을 수 있어!\n\n축제 상품권을 있는대로 모아서 가져오라고! 좋은 상품으로 교환해 줄 테니까. 많이 모아올수록 당연히 상품도 더 많이 받을 수 있지. 정말 신나지 않나?!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7927] = {title = "다크문 차원문 카드", objective = "다크문 유랑단이 마을에 오면 차원문 카드 한벌을 돌려줘야 합니다.", description = "이제 차원문 카드를 모두 모아 한 벌이 완성되자 신기하게도 처음 여덟 개와 뒷면 모양이 똑같은 아홉 번째 카드가 나타납니다. 이 카드에는 \"이 카드들을 다크문 축제 상품 교환원에게 돌려주면 보상을 받을 것입니다.\"라고 적혀 있습니다. 다크문 유랑단은 몇 달에 한 번씩 멀고어와 골드샤이어를 번갈아 가며 들른다고 합니다. 다음에 유랑단이 이곳에 올 때까지 기다려야 합니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 카드: 뒤틀린 황천"},
[7928] = {title = "다크문 대장군 카드", objective = "다크문 유랑단이 마을에 오면 대장군 카드 한벌을 돌려줘야 합니다.", description = "이제 대장군 카드를 모두 모아 한벌이 완성되자 신기하게도 처음 여덟 개와 뒷면 모양이 똑같은 아홉 번째 카드가 나타납니다. 이 카드에는 \"이 카드들을 다크문 축제 상품 교환원에게 돌려주면 보상을 받을 것입니다.\"라고 적혀 있습니다. 다크문 유랑단은 몇 달에 한 번씩 멀고어와 골드샤이어를 번갈아 가며 들른다고 합니다. 다음에 유랑단이 이곳에 올 때까지 기다려야 합니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 카드: 영웅심"},
[7929] = {title = "다크문 정령 카드", objective = "다크문 유랑단이 마을에 오면 정령 카드 한벌을 돌려줘야 합니다.", description = "이제 정령 카드를 모두 모아 한 벌이 완성되자 신기하게도 처음 여덟 개와 뒷면 모양이 똑같은 아홉 번째 카드가 나타납니다. 이 카드에는 \"이 카드들을 다크문 축제 상품 교환원에게 돌려주면 보상을 받을 것입니다.\"라고 적혀 있습니다. 다크문 유랑단은 몇 달에 한 번씩 멀고어와 골드샤이어를 번갈아 가며 들른다고 합니다. 다음에 유랑단이 이곳에 올 때까지 기다려야 합니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 카드: 혼돈의 소용돌이"},
[7930] = {title = "상품권 5매 - 다크문 꽃", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 꽃"},
[7931] = {title = "상품권 5매 - 다크문 축제 동상", objective = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", description = nil, progress = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", completion = "자, 어서 받게! 임금에게도 어울릴 만한 큰 상품이지! 축하하네, 친구!\n\n교환하고 싶은 상품권이 더 있거든 알려주게! 다크문 축제가 열리는 동안에는 내가 교환해 줄 테니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 동상"},
[7932] = {title = "상품권 12매 - 다크문 축제 은상", objective = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", description = nil, progress = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", completion = "자, 어서 받게! 임금에게도 어울릴 만한 큰 상품이지! 축하하네, 친구!\n\n교환하고 싶은 상품권이 더 있거든 알려주게! 다크문 축제가 열리는 동안에는 내가 교환해 줄 테니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 은상"},
[7933] = {title = "상품권 40매 - 다크문 축제 금상", objective = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", description = nil, progress = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", completion = "자, 어서 받게! 임금에게도 어울릴 만한 큰 상품이지! 축하하네, 친구!\n\n교환하고 싶은 상품권이 더 있거든 알려주게! 다크문 축제가 열리는 동안에는 내가 교환해 줄 테니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 금상"},
[7934] = {title = "상품권 50매 - 다크문 보관함", objective = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", description = nil, progress = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", completion = "자, 어서 받게! 임금에게도 어울릴 만한 큰 상품이지! 축하하네, 친구!\n\n교환하고 싶은 상품권이 더 있거든 알려주게! 다크문 축제가 열리는 동안에는 내가 교환해 줄 테니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 보관함"},
