[7936] = {title = "상품권 50매 - 일년 묵은 양고기", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n일년 묵은 양고기"},
[7937] = {title = "당신을 기다리는 행운...", objective = "엘윈 숲의 동부 벌목지로 가서 당신의 행운을 찾아야 합니다.", description = "\"동부벌목지로 가서 당신의 행운을 맞이하라.\"\n\n세이지가 건네 준 점괘를 만지자 약간 따뜻한 기운이 느껴집니다. 점괘를 손에 꼭 쥐자 엘윈 숲에 있는 동부 벌목지의 환영이 나타납니다. 그 환영에 좀 더 집중하자 동물 우리 옆에 있는 신비의 건초더미가 보입니다.", progress = "이 신비의 건초더미는 환영 속에서 본 것과 똑같습니다.", completion = "급히 뒤져 보니 신비의 건초더미 속에 금고 하나가 있습니다! 행운을 발견한 것 같습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n신비의 금고"},
[7938] = {title = "당신을 기다리는 행운...", objective = "서부 몰락지대의 죽음의 폐광으로 가서 당신의 행운을 찾아야 합니다.", description = "\"죽음의 폐광으로 가서 당신의 행운을 맞이하라.\"\n\n세이지가 건네 준 점괘를 만지자 약간 따뜻한 기운이 느껴집니다. 점괘를 손에 꼭 쥐자 서부 몰락지대의 폐허가 된 작은 마을인 문브룩 내부에 있는 죽음의 폐광의 환영이 나타납니다. 그 환영에 좀 더 집중하자 구불구불한 통로를 지나 희미하게 빛나는 문 앞에 도달합니다... 이 차원의 문은 폐광의 중심부로 연결됩니다. 차원의 문을 통과하자 어디에선가 이상한 궤짝이 나타납니다.", progress = "이 궤짝은 환영 속에서 본 것과 똑같습니다.", completion = "급히 뒤져 보니 궤짝 안에 금고 하나가 있습니다! 행운을 발견한 것 같습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n신비의 금고"},
[7939] = {title = "더 많은 강도 높은 연마석", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7940] = {title = "상품권 1200매 - 다크문의 보주", objective = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", description = nil, progress = "어서 올라오게, 어서! 혹시 다크문 축제 상품권을 상품으로 바꾸고 싶다면 말만 하게! 상품권을 여러 종류의 멋진 상품과 교환할 수 있다고. 자, 주저하지 말고 한번 해 보게!", completion = "자, 어서 받게! 여왕에게도 어울릴 만한 큰 상품이지! 축하하네, 친구!\n\n교환하고 싶은 상품권이 더 있거든 알려주게! 다크문 축제가 열리는 동안에는 내가 교환해 줄 테니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문의 보주"},
[7941] = {title = "더 많은 방어구 키트", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7942] = {title = "더 많은 토륨 부품", objective = "그동안 불만 없이 계속 요구한 물건을 가져다줘서 정말 고맙네. 이 은혜는 영원히 잊지 않겠네!\n\n이제 토륨 부품이 예전만큼 절실히 필요한 것은 아니지만 그래도 계속 가져다 주면 다크문 축제 상품권으로 기꺼이 교환해 주도록 하지.", description = nil, progress = "그동안 불만 없이 계속 요구한 물건을 가져다줘서 정말 고맙네. 이 은혜는 영원히 잊지 않겠네!\n\n이제 토륨 부품이 예전만큼 절실히 필요한 것은 아니지만 그래도 계속 가져다 주면 다크문 축제 상품권으로 기꺼이 교환해 주도록 하지.", completion = "자, 이걸 받게나. 다크문 축제 상품권일세. 그걸로 즐거운 시간 되길 바라네. 절대로 한 곳에서 다 써 버리지는 말라고!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7943] = {title = "더 많은 박쥐 눈", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[7944] = {title = "당신을 기다리는 행운...", objective = "불모의 땅에 있는 통곡의 동굴로 가서 당신의 행운을 찾아야 합니다.", description = "\"통곡의 동굴로 가서 당신의 행운을 맞이하라.\"\n\n세이지가 건네 준 점괘를 만지자 약간 따뜻한 기운이 느껴집니다. 점괘를 손에 꼭 쥐자 불모의 땅의 크로스로드 남서쪽에 있는 동굴의 환영이 나타납니다. 그 환영에 좀 더 집중하자 구불구불한 통로를 지나 희미하게 빛나는 차원의 문 앞에 도달합니다... 이 차원의 문은 이 동굴의 중심부로 연결됩니다. 차원의 문을 통과하자 어디에선가 이상한 궤짝이 나타납니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n신비의 금고"},
[7945] = {title = "당신을 기다리는 행운...", objective = "멀고어의 잿빛 동굴로 가서 당신의 행운을 찾아야 합니다.", description = "\"회색갈기일족 바위굴로 가서 당신의 행운을 맞이하라.\"\n\n세이지가 건네 준 점괘를 만지자 약간 따뜻한 기운이 느껴집니다. 점괘를 손에 꼭 쥐자 멀고어에 있는 회색갈기일족 바위굴의 환영이 나타납니다. 그 환영에 좀 더 집중하자 동굴 입구 근처에 있는 나무 그루터기가 보입니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n신비의 금고"},
[7946] = {title = "줍줍의 알", objective = "줍줍이 돌아와서 다행스러워. 검은무쇠단 에일 맥주를 얼마나 좋아하는지 맥주가 다 떨어지니까 찾으러 훌쩍 떠나버렸지 뭐야!\n\n이제 줍줍이 돌아왔으니 가능한 한 맥주를 잔뜩 모아 둬야겠어! 줍줍이 또 도망가서는 안 될 일이니!\n\n혹시 검은무쇠단 에일 맥주 갖고 있는 거 없나? 갖고 있으면 한잔 당 줍줍의 개구리 알 한 개를 주기로 하지...", description = nil, progress = "줍줍이 돌아와서 다행스러워. 검은무쇠단 에일 맥주를 얼마나 좋아하는지 맥주가 다 떨어지니까 찾으러 훌쩍 떠나버렸지 뭐야!\n\n이제 줍줍이 돌아왔으니 가능한 한 맥주를 잔뜩 모아 둬야겠어! 줍줍이 또 도망가서는 안 될 일이니!\n\n혹시 검은무쇠단 에일 맥주 갖고 있는 거 없나? 갖고 있으면 한잔 당 줍줍의 개구리 알 한 개를 주기로 하지...", completion = "고맙네. 자, 알 여기 있네! 부화하려면 아직 좀 더 기다려야 하지만, 부화하면 멋진 애완동물이 생길 게야!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n쥬블링 대기시간\n\n다음과 같은 것들을 받습니다:\n\n부화되지 않은 쥬블링 알"},
[7961] = {title = "Waskily Wabbits!", objective = "Kill 5 rabbits and return to Jon LeCraft by the forge on Designer Island.", description = "These rabbits are breeding uncontrollably.  Something must be done!\n\nHelp us <name>, you're our only hope.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n토끼 앞발눈덧신토끼 상자"},
[7962] = {title = "토끼 가죽", objective = "존 리크래프트에게 리크래프트 토끼 가죽 세 개를 갖다 주어야 합니다.", description = "리크래프트 토끼 가죽이 필요합니다. 리크래프트 토끼를 잡아서 좀 구해 주십시오. \n\n이건 아주 중요합니다!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n야생의 징표\n\n다음과 같은 것들을 받습니다:\n\n12Kg 랍스터"},
