[8041] = {title = "무감바의 힘", objective = "반갑군, <class> 친구. 나는 무감바의 트롤, 파괴자 진로크라고 하네. 우리 잔달라 부족은 자네의 공적을 인정하고 있다네. 자네의 그 끈기와 의지력에 경의를 표하는 바이일세.\n\n이 부적을 목에 걸고 다니면 무감바 산의 힘이 자네 몸에 흐르게 될 것이야. 그리고 자네가 적을 쓰러뜨릴수록 부적의 힘은 더욱 강해질 것이네!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n무감바의 힘"},
[8042] = {title = "무감바의 힘", objective = "오, 무사한 걸 보니 다행이군. 지금까지 자네가 치러 온 이 위대한 전투들은 이 세계의 모든 생명에 영향을 미치고 있네. 학카르는 절대로 줄구룹의 경계를 벗어나서는 안 되네. 그렇게 되면 피에 굶주린 그로 인해 온 세상이 파멸하게 될 것이야.\n\n부적을 내게 건네주면 부적의 힘을 더욱 강하게 만들어 주지. 무감바 지주를 사용하여 적들을 물리치게!", description = nil, progress = "오, 무사한 걸 보니 다행이군. 지금까지 자네가 치러 온 이 위대한 전투들은 이 세계의 모든 생명에 영향을 미치고 있네. 학카르는 절대로 줄구룹의 경계를 벗어나서는 안 되네. 그렇게 되면 피에 굶주린 그로 인해 온 세상이 파멸하게 될 것이야.\n\n부적을 내게 건네주면 부적의 힘을 더욱 강하게 만들어 주지. 무감바 지주를 사용하여 적들을 물리치게!", completion = "우린 곧 다시 만나게 될 것일세, &lt;class&gt; 친구.", rewards = "다음과 같은 것들을 받습니다:\n\n무감바의 힘"},
[8043] = {title = "무감바의 힘", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n무감바의 힘"},
[8044] = {title = "무감바의 분노", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n무감바의 분노"},
[8045] = {title = "이교도의 징표", objective = "이교도여, 이걸 알아 둬라. 어쩔 수 없이 우리가 함께 일해야 하는 상황이 되었군. 너의 그 이단적인 태도는 잔달라 부족의 이해나 인정을 받을 수 없지만, 우리는 정정당당한 부족이므로 그걸 문제 삼지는 않겠네. 이 징표를 목에 걸면 적에게 경고가 될 뿐 아니라 잔달라부족의 친구임을 표시하게 될 것이야.\n\n우리 부족에게 계속 도움이 된다면 그 징표의 힘을 강화시켜 주도록 하지.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이교도의 징표"},
[8046] = {title = "이교도의 징표", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이교도의 징표"},
[8047] = {title = "이교도의 징표", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이교도의 징표"},
[8048] = {title = "영웅의 징표", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n영웅의 징표"},
[8049] = {title = "줄다자르의 눈", objective = "여<class>여, 이 부적을 우리의 감사의 표시로 받게나.\n\n줄다자르의 눈은 잔달라 부족 트롤과의 유대가 깊어질수록 더욱 강력한 힘을 갖게 될 것이네. 정기적으로 나를 찾아오면 이 보석에 마법을 불어넣어 주도록 하지.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n줄다자르의 눈"},
[8050] = {title = "줄다자르의 눈", objective = "여<class>여, 어서 오게. 줄다자르의 눈에 의한 힘의 힘찬 박동이 느껴지는군. 이제 다음 단계로 나아갈 준비가 되었군. 부적을 내게 건네주면 마법을 불어넣어 주겠네.", description = nil, progress = "여<class>여, 어서 오게. 줄다자르의 눈에 의한 힘의 힘찬 박동이 느껴지는군. 이제 다음 단계로 나아갈 준비가 되었군. 부적을 내게 건네주면 마법을 불어넣어 주겠네.", completion = "영혼약탈자 학카르와 그의 부하들과 계속 싸우게. 절대로 녀석이 줄구룹 경계를 벗어나도록 해서는 안 될 것이야.", rewards = "다음과 같은 것들을 받습니다:\n\n줄다자르의 눈"},
[8051] = {title = "줄다자르의 눈", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n줄다자르의 눈"},
[8052] = {title = "줄다자르의 천리안", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n줄다자르의 천리안"},
[8053] = {title = "마력의 보물: 자유사상가의 손목보호대", objective = "줄구룹에서 고대 학카리 팔보호구를 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "자네는 이교도로군. 이교도들은 우리 부족의 한 부분을 차지하지. 이교도들은 잔달라의 자유사상가들이야. 자유사상가는 억압을 두려워하지 않고, 자신의 신념을 위해 죽음도 감수하지. 자네도 자네의 믿음 때문에 죽음도 감수할 거라는 걸 알고 있네. 그건 우리 부족의 인정을 받을 만한 일이자, 자네 스스로 자신의 가치를 입증할 기회를 얻을 만한 일이지.\n\n우리에게는 마력의 보물이 반드시 필요하다네. 줄구룹으로 가서 학카르의 졸개들을 처치한 후, 내가 찾고 있는 물건인 잔달라 자유사상가의 전투 장비를 가져오게.\n\n어서 가 보게나.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 자유사상가의 손목보호대"},
[8054] = {title = "마력의 보물: 자유사상가의 허리띠", objective = "줄구룹에서 고대 학카리 어깨걸이를 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "자네가 믿는 바는 우리에겐 아주 낯선 것일세, 이교도여. 고대 잔달라 부족에게는 한때 이교도라는 낙인이 찍혔었지. 당시는 구루바시 제국이 강대했을 때였다네. 이교도들은 감히 학카르의 사제들에게 덤벼들었고, 그 때문에 마치 하찮은 벌레처럼 쫓겨 죽임을 당했다네. 하지만 그 이교도들은 혈신과 대적한 자신들의 싸움에서 결코 흔들리지 않았지. 우리는 바로 그 자유사상가들이 치른 대가를 명예롭게 여긴다네.\n\n줄구룹에서 학카르의 졸개들을 처치하고 내가 찾는 마력의 보물을 가져오게. 성공하면 큰 보상을 받게 될 것이야.\n\n자, 어서 가 보게.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 자유사상가의 허리띠"},
[8055] = {title = "마력의 보물: 자유사상가의 흉갑", objective = "줄구룹에서 고대 학카리 휘장을 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "전투를 위한 방어구가 있으면 부족 내에서 힘을 갖게 된다네. 광신도들인 자유사상가들은 이런 식으로 명예를 누렸지. 그들은 자신들의 흉갑에 강력한 모조를 부여했다네. 적과 맞섰을 때 자신들의 믿음은 흔들릴지언정 자신들의 흉갑은 흔들리지 않도록 말이야.\n\n그런 흉갑을 소유하려면 부족민들 사이에서 존경을 받아야만 하네. 줄구룹으로 가서 내가 필요로 하는 마력의 보물을 구해 오게. 줄구룹 내의 멍청이들에게 가장 큰 고통을 안기고 빼앗아서 내게 가져오게나. 자유사상가로서의 자네 가치를 아주 확고히 입증해 보여주게나.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 자유사상가의 흉갑"},
[8056] = {title = "마력의 보물: 점술가의 팔보호구", objective = "줄구룹에서 고대 학카리 어깨갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 줄다자르의 메이위키에게 가져가야 합니다.B\n또한 잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "우리 부족의 점술가들은 타고난 천상의 식견 덕분에 존경을 받지요. 그들은 의술사가 아니랍니다. 뼈를 던져 운을 점치고 나뭇잎을 읽으면서 식견을 얻는 데 힘쓰지, 타인에게 마법을 걸려고 들지 않거든요. 당신은 주술사이니 이미 점술의 위력에 대해 좀 알고 있겠죠. 우리 잔달라 부족은 그들이 우리에게 알려 주는 식견을 아주 소중히 여긴답니다.\n\n줄구룹 내에서 마력의 보물을 구해 와서 우리 부족에게 당신의 가치를 입증해 보이세요. 그러면 우리 점술가들이 그 무엇보다 아끼는 팔보호구를 주겠어요.", progress = "줄구룹에서 내가 필요로 하는 마력의 보물을 가져왔나요? 이 팔보호구라면 그 어떤 수고도 보람이 있을 거예요!", completion = "당신에게는 잔달라 점술가의 혼이 조금 있는 것 같군요. 당신이 우리 부족을 대신해 줄구룹에서 행한 일에 대해서 알고 있어요. 이 마력의 보물은 잔달라 부족에게 아주 큰 도움이 될 겁니다. 이제 우리 부족을 친구라 생각해도 좋아요. 이 팔보호구를 받으세요. 당신은 이걸 받을 만한 가치가 충분하고도 남으니까요!", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 점술가의 팔보호구"},
[8057] = {title = "마력의 보물: 제사장의 팔보호구", objective = "줄구룹에서 고대 학카리 손목갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 줄다자르의 메이위키에게 가져가야 합니다.\n\n잔달라 부족의 평판이 우호적 이상이어야만 합니다.", description = "제사장은 우리 부족의 핵심적인 일원이에요. 그들이 얘기하는 징후를 귀담아듣는 게 현명하죠. 동물들과의 교감하고, 필요한 경우 그 동물들을 영혼들에게 바치기도 하면서 우리에게 하늘의 뜻을 알려 주죠. 옛날에는 제사장의 통찰력과 지혜 덕에 우리 부족에서 분리된 구루바시 부족과의 전쟁에서 우리가 우세할 수 있었어요.\n\n줄구룹 내에서 마력의 보물을 구해 돌아와, 우리 부족에게 당신의 가치를 입증해 보이세요. 그러면 잔달라의 제사장이 갖고 싶어할 팔보호구를 주겠어요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 제사장의 팔보호구"},
[8058] = {title = "마력의 보물: 구원자의 손목보호대", objective = "줄구룹에서 고대 학카리 어깨갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "복수는 곧 힘이지. 잔달라 구원자가 바로 그 힘일세. 우리 부족에게는 많은 적들이 있는데, 구원자가 그들에게 정확한 복수를 행하지. 적이 우리에게 행한 죄를 응징하지 않고 넘어가는 일은 절대 없네. 구원자가 바로 그 응징을 맡는다네. 적들은 우리의 복수를 두려워하네. 당연히 그래야지. 영원히 그렇게 두려워할 거야.\n\n우리의 구원자가 되게나. 줄구룹 내에서 마력의 보물을 찾아오게. 부족의 이름으로 학카르의 졸개들을 처치하고 복수를 하면 자네에게 상을 내리겠네.", progress = "마력의 보물을 가져왔나? 잔달라 부족의 이름으로 복수는 했는가?", completion = "오늘 큰 복수를 행했군. 자네는 구원자의 모습을 취해 혈신의 졸개들을 무릎 꿇게 했어.\n\n자, 이걸 받게. 앞으로의 복수를 더욱 불타오르게 해 줄 걸세. 이제 자네는 잔달라 부족의 친구라네.", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 구원자의 손목보호대"},
[8059] = {title = "마력의 보물: 악령술사의 손목띠", objective = "줄구룹에서 고대 학카리 손목갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "악마들을 다룬다는 점에서 흑마법사들은 아주 위험한 길을 걷는 것이지만, 우리 부족의 악령술사들은 여기서 한 발 더 나아간다네. 고대 비전 의식을 통해 악마가 자신들의 존재 속에 들어가도록 하는 것이지. 악마들이 자신들을 완전히 지배하도록 놔두지 않고 내면에서 악마를 사로잡아 악마들의 힘을 흡수해 마음대로 부리는 것이야. 이를 통달할 수 있는 건 오직 아주 극소수뿐이지.\n\n자네가 악령술사의 힘을 배우겠다면 줄구룹에서 마력의 보물을 가져와야 하네.자, 어서 가 보게.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 악령술사의 손목띠"},
[8060] = {title = "마력의 보물: 환영술사의 손목띠", objective = "줄구룹에서 고대 학카리 팔보호구를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "우리 부족의 마법사들은 환영술사들로 알려져 있다네. 주문을 외울 때 강력한 모조를 사용하는데, 종종 부족의 적들을 현혹시키거나 혼란스럽게 만들지!\n\n<사악하게 웃는 알타빔>\n\n적들을 그들 스스로 자신의 광기로 인해 무릎 꿇게 만드는 강한 환영술사를 보면 그야말로 장관일세!\n\n환영술사의 도를 배우고 싶거든 줄구룹으로 가서 내가 원하는 마력의 보물을 가져오게. 그러면 우리 환영술사들이 마법 주문을 사용할 때 착용하는 손목띠를 주도록 하지.", progress = "벌써 돌아온 건가? 내가 부탁한 마력의 보물은 구해 왔나?", completion = "대단하군... 이 안에 흐르는 모조가 느껴지나? 마력의 보물은 옛날 구루바시 제국이 이 땅을 지배할 당시 일종의 통화로 사용됐었다네. 이제는 우리 잔달라 부족이 이 안에 잠재해 있는 모조를 이용해 혈신 학카르의 환생을 막으려고 하는 것이야!\n\n자네 아주 잘해 주었네. 우리 잔달라 부족을 친구로 생각해도 좋아. 수고를 해 줬으니 여기 내가 약속했던 환영술사의 손목띠를 주도록 하지!", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 환영술사의 손목띠"},
[8061] = {title = "마력의 보물: 성자의 손목띠", objective = "줄구룹에서 고대 학카리 손목갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "우리 잔달라 부족은 천상의 권한을 전하는 이들에게 힘을 실어 준다네. 우리 사제들은 단순히 치유사들이 아니라 성자들일세. 악이란 학카르처럼 외부에서, 부족 내부에서 나타나기도 하지만 내부에서 나타나기도 하는 것이지. 성자들은 부족민들 사이에서 재판관 역할을 하면서 구루바시를 내부에서 집어삼켰던 바로 그 악으로부터 우리를 보호한다네.\n\n줄구룹으로 가서 구루바시로부터 마력의 보물을 되찾아오게. 성자가 된다는 것이 어떤 것인지 배우고 우리를 악으로부터 보호해 주게나.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 성자의 손목띠"},
[8062] = {title = "마력의 보물: 수렵꾼의 팔보호구", objective = "줄구룹에서 다음의 마력의 보물을 가시덤불 골짜기의 요잠바 섬에 있는 장님 팔디르에게 가져가야 합니다: 고대 학카리 팔보호구 1개\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "구루바시 제국의 멸망 이후 찾아온 암흑기에는 잔달라 수렵꾼들이 자신들의 역량을 발휘해 부족의 생계를 유지했다고 합니다. 사냥꾼들은 우리 부족의 수렵꾼들과 매우 비슷하다고 하지요. 물론, 사냥감을 좇는 것이 수렵꾼의 본질을 구현하는 것이긴 하답니다. 하지만 줄구룹에서 사냥을 함으로써 우리 최정예 수렵꾼들 사이에서 진정한 당신의 수준이 드러나게 될 겁니다.\n\n줄구룹 내에서 마력의 보물을 몇 개 가져와 보십시오. 그러면 제2의 수렵꾼이 되기 위한 첫 걸음을 내딛는 것이 될 테니까요.", progress = "줄구룹에서 마력의 보물을 지니고 있는 자들을 뒤쫓도록 하십시오. 우리가 원하는 물건을 지니고 있으니 그들이 당신의 사냥감입니다.", completion = "그렇습니다... 마력의 보물의 존재를 느끼는 데는 특별한 능력이 필요 없지요. 줄구룹에서의 당신의 성공 소식에 많은 부족민들이 놀라워하고 있습니다. 우리는 당신을 잔달라 부족의 벗으로 여길 뿐 아니라, 수렵꾼의 팔보호구를 지닐 자격이 있다고 생각합니다. 수렵꾼의 팔보호구는 수렵꾼이 된다는 것이 어떤 것인지를 상징하는 아주 강력한 물건이지요. 수고하셨습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 수렵꾼의 팔보호구"},
[8063] = {title = "마력의 보물: 개혁가의 팔보호구", objective = "줄구룹에서 고대 학카리 어깨갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 장님 팔디르에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족의 개혁가들은 도적들과 유사하지만, 무엇보다 그들은 광기... 혼돈... 그리고 존재의 예측 불가능성을 기꺼이 받아들인답니다. 전장에서 아주 무서운 광경을 만들어 내는 그들은 우리 부족이 분열된 후 찾아온 잔인한 시기에 우리 적들 사이에 혼란과 파괴의 씨를 뿌렸답니다. 그들이 없었다면 우리 부족은 여기 이렇게 존재할 수 없었을 겁니다.\n\n줄구룹에서 내가 찾고 있는 마력의 보물을 가져오면 개혁가가 아끼는 방어구 중 첫 번째 것을 드리도록 하죠. 내면의 광기를 받아들이세요!", progress = "줄구룹 내에서 광기가 발휘되는 곳을 찾아 당신의 광기로 그 광기를 덮어 버리십시오! 그것은 바로 성공을 뜻하는 것이고, 성공은 바로 보상을 뜻하지요! 또다시 혈신이 최고 지배자의 자리에 오르게 해서는 안 됩니다!", completion = "잘하셨습니다... 당신이 줄구룹에서 세운 업적으로 인해 잔달라 부족을 벗이라 부를 수 있는 자격을 얻게 됐습니다. 보물을 처리하는 건 알아서 하겠습니다. 자, 수고한 데 대한 보상으로 이걸 받으세요.", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 개혁가의 팔보호구"},
[8064] = {title = "마력의 보물: 제사장의 허리띠", objective = "줄구룹에서 고대 학카리 장식띠를 구해 가시덤불 골짜기의 요잠바 섬에 있는 줄다자르의 메이위키에게 가져가야 합니다. 또한 잔달라 부족에게 우호적 이상의 평판을 얻어야 합니다.", description = "우리 잔달라 부족은 드루이드의 도를 알지 못해요. 자연은 우리가 필요에 의해 개척해 나가야 하는 것이지 그 반대가 되어서는 안 되죠. 그래도 자연의 법칙과 가장 잘 조화를 이루는 건 아마 제사장일 텐데, 거기에는 그럴 만한 이유가 있어요. 짐승의 영혼을 바침으로써 곧 그들 중 하나가 된다는 것이 어떠한 것인가를 알게 되죠. 바로 그것이 자연의 진정한 힘이랍니다.\n\n줄구룹 내에서 마력의 보물을 구해 와서 당신의 가치를 입증해 보이세요. 그러면 강력한 물건을 주겠어요. 바로 많은 잔달라부족 제사장들이 사용하는 허리띠예요. 그래요, 아주 강한 모조를 갖고 있죠! 야 몬!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 제사장의 허리띠"},
[8065] = {title = "마력의 보물: 제사장의 튜닉", objective = "줄구룹에서 고대 학카리 휘장을 구해 가시덤불 골짜기의 요잠바 섬에 있는 줄다자르의 메이위키에게 가져가야 합니다. 또한 잔달라 부족에게 매우 우호적 이상의 평판을 얻어야 합니다.", description = "제사장의 힘의 궁극적 상징은 그들이 무엇을 입느냐는 것이죠. 그 중에서도 튜닉은 그들 자신과 그들이 추구하는 천상의 지혜 사이의 연결을 상징한답니다. 흔히 제물로 바친 야수들의 여러 부위를 엮어 튜닉을 만들곤 하는데, 이로써 자신들이 가진 천부적 재능과의 연결을 기억하게 되죠.\n\n줄구룹 내에서 마력의 보물을 구해 와서 당신의 가치를 입증해 보이세요. 그러면 제사장의 진정한 힘을 발휘하는 튜닉이 당신 것이 될 것입니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 제사장의 튜닉"},
[8066] = {title = "마력의 보물: 수렵꾼의 허리띠", objective = "줄구룹에서 다음의 마력의 보물을 구해 가시덤불 골짜기의 요잠바 섬에 있는 장님 팔디르에게 가져가야 합니다: 고대 학카리 어깨걸이 1개\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "수렵꾼은 자신의 사냥감을 추적하는 법을 알지만, 성공한 수렵꾼은 거리를 좁히는 즉시 사냥감을 공격하는 법도 알고 있답니다. 줄구룹에서 성공할 가능성... 그리고 잔달라 수렵꾼처럼 될 가능성을 조금이라도 얻으려면 이 두 가지를 모두 통달해야 합니다.\n\n줄구룹에서 내가 원하는 마력의 보물을 가져오십시오. 나는 그 장신구에서 나오는 힘을 얻고, 당신은 잔달라 수렵꾼의 허리띠를 얻게 될 겁니다. 교환할 만한 가치가 충분히 있는 장비지요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 수렵꾼의 허리띠"},
[8067] = {title = "마력의 보물: 수렵꾼의 어깨보호대", objective = "줄구룹에서 다음의 마력의 보물을 구해 가시덤불 골짜기의 요잠바 섬에 있는 장님 팔디르에게 가져가야 합니다: 고대 학카리 아이기스 1개\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "우리 잔달라 부족은 업적 달성을 상징하기 위해 착용하는 물건을 아주 소중히 여긴답니다. 하지만 그 물건에서 뿜어져 나오는 힘을 감지하기 위해 착용하고 있는 물건을 꼭 눈으로 봐야 할 필요는 없지요. 힘은 눈에 보이는 것을 초월하니까요. 잔달라 수렵꾼의 장비가 그런 것인데, 그 중에서도 가장 소중히 여겨지는 것이 바로 어깨보호대입니다. 수렵꾼의 어깨보호대는 착용한 자가 눈에 띄지 않도록 해 주고... 원하는 경우 자신의 존재를 드러낼 수도 있답니다.\n\n줄구룹에서 마력의 보물이 당신을 기다리고 있습니다. 내가 찾는 물건을 가져오면 수렵꾼의 어깨보호대를 드리도록 하겠습니다.", progress = "줄구룹을 공격하는 건 성공했습니까? 내가 찾는 물건을 가져와 우리 부족에게 당신 자신의 가치를 완전히 입증해야만 잔달라 부족 최고의 어깨보호대를 얻을 수 있습니다.", completion = "성공했군요... 당신은 우리 부족의 존경을 받을 만합니다. 어깨보호대를 얻기 위해 필요한 마력의 보물을 구하는 것은 결코 쉬운 일이 아니었음에도, 당신은 우리 수렵꾼들 중 가장 완벽한 솜씨를 가진 자들에 맞먹는 솜씨로 일을 해냈습니다. 당신은 수렵꾼이라 불릴 만한 자격을 얻었을 뿐 아니라, 그들의 어깨보호대를 착용할 자격 또한 확실히 얻은 것입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 수렵꾼의 어깨보호대"},
[8068] = {title = "마력의 보물: 환영술사의 어깨보호대", objective = "줄구룹에서 고대 학카리 어깨걸이를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "마력은 충분한 힘을 지닌 자가 형상화할 수 있는 천연적이고 근본적인 힘일세. 모조는 우리가 이 힘을 확장한 것인데, 환영술은 그러한 강력한 마력 조작의 한 형태라네. 실제로 있지도 않은 적에게 어떻게 이길 수 있겠는가? 우리 잔달라 부족은 이 진리의 위력을 잘 알기에 환영술사들을 명예롭게 여긴다네.\n\n줄구룹에서 우리가 필요로 하는 마력의 보물을 가져오게. 그러면 부족의 존경을 얻을 뿐 아니라 우리 최정예 환영술사들이 착용하는 강력한 어깨보호대를 주도록 하지!", progress = "줄구룹 급습 작전은 어떻게 되었나? 환영술의 위력으로 적들이 미치게 했는가? 환영술을 사용했든 아니든 녀석들의 죽음과 그들에게서 빼앗아 온 마력의 보물은 학카르의 부활을 막아내는 데 도움이 될 걸세.", completion = "성공했군! 이제부터 자네는 우리 부족에서 존경을 받게 될 걸세! 자네 덕분에 오늘 줄구룹이 확실히 잔달라 부족의 위력을 맛보게 되었네.\n\n부족민들의 축복과 함께 잔달라 환영술사의 어깨보호대를 받게. 유용하게 쓰이기를 바라네.", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 환영술사의 어깨보호대"},
[8069] = {title = "마력의 보물: 환영술사의 로브", objective = "줄구룹에서 고대 학카리 조끼를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족은 장비로 지위와 권력을 인지한다네. 우리 겉옷은 최고급 재료로 만들고 우리가 사용하는 모조를 혼합해 우릴 아주 강하게 만들지. 그건 환영술사도 마찬가지일세. 그들의 로브는 자신들의 겉모습에 환영의 본질을 형상화한다고들 하지. 전설에 따르면, 그들의 고대 로브는 단 한 번도 그 모습이 똑같았던 적이 없었다고 하네.\n\n내가 자네에게 환영술사의 로브를 하나 주지... 하지만 먼저 부족민들 사이에서 노력을 통해 존경의 위치를 차지해야만 해. 줄구룹에서 마력의 보물을 가져오게!", progress = "우리가 필요로 하는 마력의 보물을 가져온 건가? 쉽지 않은 일이라는 건 아네... 하지만 난 오래전부터 학카르와의 싸움에서 이방인이 우리를 도와 주러 올 것이라 예견해 왔다네. 그게 바로 자네이기를 바라네!", completion = "드디어 환영술사의 로브를 입을 자격을 갖춘 자가 나타났군! 줄구룹에서 자네가 거둔 성공으로 자네의 명성이 부족에 길이 남을 걸세. 긍지를 갖고 입도록 하게!", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 환영술사의 로브"},
[8070] = {title = "마력의 보물: 성자의 허리띠", objective = "줄구룹에서 고대 학카리 장식띠를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "구루바시 제국이 멸망하고 난 후 오래지 않아, 우리 잔달라 부족도 부족 내부의 악에 의해 거의 최후의 패배를 맞을 뻔했지. 바로 그때 부족에서 성자들이 들고 일어나 동족을 파괴하려는 자들을 추방함으로써 부족의 존속을 지켰지. 그들은 우리가 영혼들과의 조화를 지속할 수 있도록 할 뿐 아니라 우리의 육체도 보호해 준다네.\n\n줄구룹으로 가서 학카르와 구루바시 부족의 타락을 직접 목격해 보게나. 우리가 원하는 마력의 보물을 그들에게서 빼앗아 오게. 성공하면 보상이 있을 것이야!", progress = "마력의 보물은... 가져왔나? 그것들이 있어야만 그 안에 잠재하는 힘을 사용할 수 있다네. 혈신의 졸개들과의 전쟁에서 형세를 완전히 반대로 뒤집어 놓는다면 속이 후련하겠군...", completion = "성공이군! 학카르의 환생을 막기 위해 필요한 힘을 모으는 데 이것들이 아주 큰 도움이 될 걸세. 자네의 도움 덕택에 혈신이 우리 모두를 말살하지 못할 것이라는 보증하게 되었군.\n\n오늘 자네는 우리 부족으로부터 존경을 얻었네. 감사의 표시로 주는 이 성자의 허리띠를 받게나.", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 성자의 허리띠"},
[8071] = {title = "마력의 보물: 성자의 어깨보호대", objective = "줄구룹에서 고대 학카리 아이기스를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족의 성자들은 모두 부족의 보호자라는 것을 증명하는 특유의 어깨보호대를 걸치고 있지. 그 어깨보호대에는 우리 부족을 위협하는 자들을 가려내는 데 도움이 되는 강력한 모조로 짜여 있다네. 사제인 자네도 가치가 있고 없는 자들을 판별해야 하니 그런 어깨보호대가 아주 유용할 것이야.\n\n줄구룹에서 학카르의 졸개들과 싸워 내가 찾는 마력의 보물을 가져오면 그 보답으로 우리 최정예 성자들이 걸치는 어깨보호대를 주기로 하겠네.", progress = "줄구룹에서 마력의 보물을 가져온 건가?", completion = "수고했네. 자네 덕분에 오늘날 학카르의 졸개들에게 잔달라 부족의 복수를 확실히 맛보게 되었구먼. 그 공로로 인해 자네는 우리 부족 내에서 영원히 존경을 받게 될 것일세. 우리의 축복과 함께 이 성자의 어깨보호대를 받게나!", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 성자의 어깨보호대"},
[8072] = {title = "마력의 보물: 개혁가의 어깨보호대", objective = "줄구룹에서 고대 학카리 벨트를 구해 가시덤불 골짜기의 요잠바 섬에 있는 장님 팔디르에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족 전설의 개혁가들 중에는 광기의 카르바살이라는 자가 있습니다. 전설에 의하면 카르바살이 처음으로 부족의 적들을 마주했을 때 특별히 \"광기의 옷감\"으로 짠 어깨보호대를 사용했다고 합니다. 어깨보호대는 물론 눈에 보이지 않을 정도로 빠르게 휘두르는 두 개의 단검 때문에 그의 모습이 가려졌다고도 합니다. 오늘날의 개혁가들은 자신들의 어깨보호대를 부족 내에서의 지위를 상징하는 물건으로서 아주 소중히 여긴답니다.\n\n내가 찾는 마력의 보물을 가져오시면 당신에게 그런 어깨보호대를 드릴 테니 적들에게 광기를 엮어 넣게 될 겁니다.", progress = "돌아왔군요. 내가 필요로 하는 마력의 보물은 가져왔나요?\n\n광기의 카르바살의 전설은 오늘날 우리에게 아무리 위협적인 존재라 하더라도 물리칠 수 없는 적은 없다는 교훈을 준답니다. 혼돈 앞에서는 누구라도 무릎을 꿇게 된다는 것만은 확실합니다... 혼돈 중에서 가장 비혼돈적인 요소도 무릎 꿇게 할 수 있을지도 모르지요.", completion = "당신이 우리 공동의 적에게 심은 광기 덕분에 승리를 손에 넣었군요! 당신은 우리 부족의 존경을 받아 마땅합니다. 당신의 공로에 대한 우리의 감사를 표하는 데 있어 개혁가의 어깨보호대를 선사하는 것보다 더 나은 방법이 어디 있겠습니까!", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 개혁가의 어깨보호대"},
[8073] = {title = "마력의 보물: 개혁가의 튜닉", objective = "줄구룹에서 고대 학카리 아이기스를 구해 가시덤불 골짜기의 요잠바 섬에 있는 장님 팔디르에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "시력을 잃은 지는 오래됐지만 조금도 아깝지 않답니다. 비록 우리 부족 내에서는 몸에 걸치는 장비들이 지위와 존재 이유를 나타낸다고 하지만, 아주 강력한 장비에서는 단순히 눈만으로는 볼 수 없는 힘이 뿜어져 나오지요. 귀하디 귀한 잔달라 개혁가의 튜닉도 예외는 아닌 것이, 그 자비가 집중할 수 있는 혼돈과 광기의 천연 마력이 뿜어져 나오기 때문이지요.\n\n내가 필요로 하는 마력의 보물은 줄구룹에 있습니다. 내가 찾는 것들을 가져오시면 그 전설의 튜닉을 하나 드리도록 하죠... 광기를 발휘하는 자에게는 어울리는 장비지요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 개혁가의 튜닉"},
[8074] = {title = "마력의 보물: 점술가의 허리띠", objective = "줄구룹에서 고대 학카리 벨트를 구해 가시덤불 골짜기의 요잠바 섬에 있는 줄다자르의 메이위키에게 가져가야 합니다.\n\n또한 잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "점술가들은 자연의 모조를 알고 있답니다. 그들은 그걸 이용해 우리 부족을 영광으로 이끌지요. 구루바시 제국이 자멸한 이후의 암흑기 동안 우리 점술가들은 남쪽 바다에 있는 안전한 곳으로 우리를 이끌어 주었죠. 게다가 악의 기운이 고개를 들고 있는 심장부인, 줄구룹이 있는 이곳 가시덤불 골짜기로도 이끌어 주었답니다.\n\n줄구룹 내에서 마력의 보물을 구해 와서 우리 부족에게 당신의 가치를 입증해 보이세요. 그러면 우리 점술가들이 사용하는 강력한 모조가 깃든 허리띠를 주도록 하죠!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 점술가의 허리띠"},
[8075] = {title = "마력의 보물: 점술가의 갑옷", objective = "줄구룹에서 고대 학카리 휘장을 구해 가시덤불 골짜기의 요잠바 섬에 있는 줄다자르의 메이위키에게 가져가야 합니다.\n\n또한 잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "잔달라 점술가들은 모두 점술가의 갑옷이라고 하는 특유의 흉갑을 착용합니다. 이 갑옷은 최고급 비단과 천으로 엮은 직물에 튼튼한 사슬을 혼합한 것이랍니다. 이는 그들의 신성함을 상징할 뿐만 아니라 권력 또한 상징하는 것입니다. 영혼들과 대화하는 자를 거스르는 것은 아주 현명하지 못한 일이에요...\n\n줄구룹 내에서 마력의 보물을 구해 와서 우리 부족에게 당신의 가치를 입증해 보이세요. 그러면 우리 점술가들도 입지 못하는 최고급 점술가의 갑옷을 주겠어요!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 점술가의 갑옷"},
[8076] = {title = "마력의 보물: 악령술사의 어깨보호대", objective = "줄구룹에서 고대 학카리 장식띠를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "악령술사는 마력을 소유하려고만 하지 않고 완전히 통합하려고 한다네. 악마와의 싸움에서 이기지 못한 자들도 꽤 있지. 하지만 적들, 특히 줄구룹에서 오는 녀석들의 위협을 고려해 보면 악령술사가 적에게 퍼부을 수 있는 힘은 그런 희생도 아깝지 않아. 우리를 없애려는 자들을 물리치지 못하면 우리는 살아남을 수 없네. 구루바시 제국의 멸망을 통해 깨닫게 된 것이지.\n\n줄구룹으로 가서 우리가 필요로 하는 마력의 보물을 가져오게나. 그리하면 아주 귀중한 악령술사 물건을 하나 주도록 하지.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 악령술사의 어깨보호대"},
[8077] = {title = "마력의 보물: 악령술사의 로브", objective = "줄구룹에서 고대 학카리 조끼를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족에서 권력의 궁극적 상징은 바로 전투 장비일세. 악령술사의 로브는 고급 룬무늬 옷감과 파괴적인 힘이 담긴 모조를 한 옷감을 융합시켜 만든 것으로, 이 로브의 외관을 보는 자들의 정신은 공포로 가득 찬다고 하네... 특히 악령술사가 마침내 제압하게 되는 악마들은 더욱 그렇지.\n\n줄구룹으로 가서 아주 특수한 마력의 보물을 가져와야 하네. 어려운 일이 되겠지만 성공하면 자네도 확실히 그런 로브를 얻게 될 것이야.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 악령술사의 로브"},
[8078] = {title = "마력의 보물: 구원자의 허리띠", objective = "줄구룹에서 고대 학카리 벨트를 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "줄구룹 내에 궁극의 복수가 기다리고 있네. 절대로 학카르가 다시 일어나서는 안 되네. 학카르는 구루바시 제국을 내부에서부터 파괴했고 어떤 제물에도 만족하지 않았지. 이제 트롤족에게 남은 것은 고대 영광의 그림자뿐이며, 그게 학카르 때문인 것을 알고 있네.\n\n자신의 숙명을 받들어 구원자가 되게. 악의 졸개들에게 재앙을 퍼붓게나. 줄구룹은 반드시 잔달라의 복수를 맛봐야만 하네. 복수의 증거로 마력의 보물을 가져오면 구원자의 허리띠를 받게 될 걸세. 진정한 힘을 얻게 되는 거야.\n\n자, 어서 가게나.", progress = "마력의 보물을 가져왔나? 잔달라 부족의 적들을 내리쳤는가? 학카르에게 구원자의 분노를 꼭 가르쳐줘야만 하네!", completion = "이제 자네는 구원자의 도를 깨달은 걸세. 자네는 잔달라 부족과 스스로에게 명예를 안겨 주었고, 적들에게는 고통을 안겨 주었네.\n\n자, 이제 이 구원자의 허리띠는 자네 걸세. 자네는 확실히 구원자의 도와 하나가 되어가고 있군.", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 구원자의 허리띠"},
[8079] = {title = "마력의 보물: 구원자의 흉갑", objective = "줄구룹에서 고대 학카리 조끼를 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n또한 잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "구원자 권력의 상징은 바로 흉갑이라네. 아주 강력한 모조로 제작된 그 흉갑은 우리가 존경하는 자들에게만 주어지지. 바로 잔달라 복수의 상징인 것일세.\n\n구원자가 되는 것은 복수 그 자체가 되는 것을 뜻한다네. 우리가 필요로 하는 마력의 보물을 줄구룹에서 가져오게. 그걸 가져오면 녀석들이 우리에게서 앗아간 모조를 되찾도록 하지. 학카르의 졸개들이 그 대가를 치르도록 만들면 구원자의 흉갑을 상으로 주겠네.\n\n어서 가게. 우리의 복수를 해 주게.", progress = "자네가 여기 온 것은 승리를 뜻하는 것인가? 마력의 보물을 가져왔나? 오늘 자네가 행한 복수에 대해 얘기해 주게!", completion = "자네는 자네가 한 일로 존경을 받아 마땅하네. 잔달라 부족은 부족의 영웅에게 보상을 하지. 줄구룹은 잔달라의 복수를 아주 뼈저리게 맛보았어.\n\n자네의 업적은 앞으로 다른 이들의 공적에 기폭제가 될 걸세. 그들은 자네를 진정한 힘의 상징, 그리고 복수의 화신으로 여기게 될 거야!", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 구원자의 흉갑"},
[8080] = {title = "아라시 분지 자원!", objective = "아라시 분지의 전투를 승리로 이끌고 아라시 보급품 상자를 구해 임시 주둔지에 있는 하사관 매클리어에게 가져가야 합니다.", description = "전쟁은 병사들의 힘으로 치르는 거라죠. 병사라면 다들 그렇게 얘기할 거예요! 하지만 장비가 형편없거나 제대로 먹지 못하고 전투에 임한다면 시작하기도 전에 벌써 진 거나 마찬가지랍니다!\n\n그래서 아라시 분지가 중요한 거예요. 이 분지는 자원의 보고예요. 광석, 무기, 식량, 목재... 이 주요 자원들을 모두 이곳에서 구할 수 있으니까요.\n\n<name>, 당신께 부탁할 일이 하나 있어요. 아라시 분지로 가서 적보다 더 많은 거점을 확보하여 전투를 승리로 이끌고 보급품 상자 하나를 가지고 돌아오세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8101] = {title = "카자로 자갈", objective = "이 부적 틀 안에 있는 자갈은 남쪽 바다의 카자로 산에서 온 걸세. 카자로 산은 격렬하고 종종 마법이 화산처럼 폭발하는 변덕스러운 곳이지.\n\n잔달라부족 트롤들과의 유대가 깊어질수록 이 자갈의 힘도 강해질 것일세. 자갈의 힘을 이용해 적들을 무찌르게. 카자로 산처럼 신속하고, 폭발하듯이, 치명적으로 말이야...", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n카자로 자갈"},
[8102] = {title = "카자로 자갈", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n카자로 자갈"},
[8103] = {title = "카자로 자갈", objective = "학카르부족은 자네를 두려워하고 있네. 놈들은 그들의 얼굴 없는 신만이 가할 수 있다고 믿었던 공포를 느꼈다. 자네가 카자로의 힘으로 녀석들을 불태워 버렸지. 이제 자네는 놈들이 두려워하는 두 가지 대상 중 하나가 된 것이야.\n\n자갈을 더 강하게 만들 때가 된 것 같군. 내게 잠깐 부적을 줘 보게나.", description = nil, progress = "학카르부족은 자네를 두려워하고 있네. 놈들은 그들의 얼굴 없는 신만이 가할 수 있다고 믿었던 공포를 느꼈다. 자네가 카자로의 힘으로 녀석들을 불태워 버렸지. 이제 자네는 놈들이 두려워하는 두 가지 대상 중 하나가 된 것이야.\n\n자갈을 더 강하게 만들 때가 된 것 같군. 내게 잠깐 부적을 줘 보게나.", completion = "줄구룹의 트롤들을 계속 제거하게. 학카르는 자신의 불굴의 의지로도 세계를 마음대로 조종할 수 없다는 것을 반드시 깨달아야 하네.", rewards = "다음과 같은 것들을 받습니다:\n\n카자로 자갈"},
[8104] = {title = "카자로 보석", objective = "보여줄 게 있으니 내게 잠깐 부적을 줘 보게.", description = nil, progress = "보여줄 게 있으니 내게 잠깐 부적을 줘 보게.", completion = "&lt;눈에 보이지 않는 강한 힘으로 자갈을 부수는 알타빔&gt;\n\n보이나? 이 자갈은 우리가 정동석이라고 부르는 것이네. 이 자갈 안에는 이 세계의 잠재된 힘을 빨아들여 온 강력한 수정들이 들어 있지. 이제 이 자갈을 이렇게 반으로 잘라서 마침내 모든 잠재력을 발휘할 수 있게 만들었네. 이 힘을 이용하여 적들을 물리치게.", rewards = "다음과 같은 것들을 받습니다:\n\n카자로 보석"},
[8105] = {title = "아라시 분지의 전투", objective = "금광, 제재소, 대장간, 그리고 농장을 공격한 후 임시 주둔지에 있는 야전사령관 오슬라이트에게 돌아가십시오.", description = "<name>, 아라시 분지에서는 자원과 영토를 놓고 전투를 벌이고 있소. 우리 부대에 필요한 보급품을 대려면 그곳 거점을 반드시 확보해야 하오. 아라시 분지 기지에서 멀리 떨어진 거점들을 공격하는 임무를 맡기겠소이다.\n\n적이 점령하고 있는 금광, 제재소, 대장간, 그리고 농장을 공격하시오. 적의 깃발을 찾아서 모두 뽑아 버리는 거요!\n\n네 곳의 깃발을 모두 뽑은 다음 돌아와 보고하시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8106] = {title = "케잔의 타락", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n케잔의 타락"},
[8107] = {title = "케잔의 타락", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n케잔의 타락"},
[8108] = {title = "케잔의 타락", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n케잔의 타락"},
[8109] = {title = "케잔의 멈출 수 없는 타락", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n케잔의 멈출 수 없는 타락"},
[8110] = {title = "마력 깃든 남쪽바다 해초", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n마력 깃든 남쪽바다 해초"},
[8111] = {title = "마력 깃든 남쪽바다 해초", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n마력 깃든 남쪽바다 해초"},
[8112] = {title = "마력 깃든 남쪽바다 해초", objective = "부적은 잘 있나요? 그 잎에 약간의 마법과 모조를 더 넣을 때가 된 것 같네요. 약간 시든 것 같은데 다시 활짝 피게 해야겠어요. 이 메이위키가 바로 고쳐 줄 테니까 이리 줘 봐요.", description = nil, progress = "부적은 잘 있나요? 그 잎에 약간의 마법과 모조를 더 넣을 때가 된 것 같네요. 약간 시든 것 같은데 다시 활짝 피게 해야겠어요. 이 메이위키가 바로 고쳐 줄 테니까 이리 줘 봐요.", completion = "이제 줄구룹의 사악한 트롤들에게 당신이 가진 자연의 힘이 얼마나 무서운 것인지 보여 줘요!", rewards = "다음과 같은 것들을 받습니다:\n\n마력 깃든 남쪽바다 해초"},
[8113] = {title = "마력 깃든 온전한 남쪽바다 해초", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n마력 깃든 온전한 남쪽바다 해초"},
[8114] = {title = "거점 네 곳 점령", objective = "아라시 분지로 가서 거점 네 곳을 점령한 후 임시 주둔지에 있는 야전사령관 오슬라이트에게 돌아가십시오.", description = "<name>, 아라시 분지의 전투에서 펼친 놀라운 위업으로 당신은 큰 명예를 얻었소. 스스로 훌륭한 <class>임을 입증해 보였고, 우리가 결코 무릎 꿇지 않을 거란 사실을 똑똑히 가르쳐 주었소!\n\n이번에는 좀 어려운 임무를 맡겼으면 하는데... 아라시 분지에 있는 거점을 적어도 네 곳 확보해 주시오. 그럴 수만 있다면 자원을 얻을 수 있을 뿐만 아니라 호드 놈들에게 우리 힘이 더 세다는 걸 보여줄 수 있을 것이오!\n\n어서 가시오, <name>. 행운이 함께하기를!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8115] = {title = "거점 다섯 곳 점령", objective = "아라시 분지에서 동시에 다섯 곳의 거점을 점령하는 임무를 완수한 다음 임시 주둔지에 있는 야전사령관 오슬라이트에게 돌아가십시오.", description = "<name>, 자원을 놓고 싸우는 아라시 분지의 전투는 진정 치열하지 않소? 아라소르 연맹은 당신의 눈부신 활약을 절실히 필요로 하고 있소.\n\n임무를 하나 더 맡아 주시오.\n\n우리는 아라시 분지에서 포세이큰 파멸단의 세력을 무력화하기 위한 맹공격을 계획하고 있소. 전장의 모든 전략적 요충지에서 놈들을 몰아내야만 하오!\n\n쉽진 않겠지만 이 일을 할 수 있는 자가 있다면 바로 당신일 거요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n아라소르 전투 휘장"},
[8116] = {title = "부드리스의 환영", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n부드리스의 환영"},
[8117] = {title = "부드리스의 환영", objective = "주수울사아! 하하, 이 메이위키가 농담한 거예요!\n\n<웃는 메이위키>\n\n줄구룹에서 영혼과 정령의 힘을 빌려 적들을 쓰러뜨렸죠? 영혼들에게 영광을!\n\n자, 이제 이 메이위키가 보주를 더 잘 보이게 만들어 줄게요. 이리 줘 봐요.", description = nil, progress = "주수울사아! 하하, 이 메이위키가 농담한 거예요!\n\n<웃는 메이위키>\n\n줄구룹에서 영혼과 정령의 힘을 빌려 적들을 쓰러뜨렸죠? 영혼들에게 영광을!\n\n자, 이제 이 메이위키가 보주를 더 잘 보이게 만들어 줄게요. 이리 줘 봐요.", completion = "이걸 한번 봐요. 부드리스가 더 잘 보이죠? 이제 더 강한 힘이 당신 몸에 흐를 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n부드리스의 환영"},
[8118] = {title = "부드리스의 환영", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n부드리스의 환영"},
[8119] = {title = "파괴되지 않은 부드리스의 환영", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n파괴되지 않은 부드리스의 환영"},
[8120] = {title = "아라시 분지의 전투", objective = "아라시 분지의 금광, 제재소, 대장간, 그리고 마구간을 공격한 다음 해머폴에 있는 죽음의경비대장 드와이어에게 돌아가십시오.", description = "자네도 들었겠지만, 아라소르 연맹이 아라시 분지에 대규모 병력을 파견하고 있다고 한다. 식량과 보급품이 필요한 얼라이언스 바보들이 그곳의 풍부한 자원을 확보하려는 것이지. 놈들에게 아라시 분지는 절대로 다시 인간의 손에 넘어가지 않을 것이라는 걸 가르쳐 줘야 한다!\n\n아라시 분지로 가서 금광, 제재소, 대장간, 마구간을 공격하라. 놈들의 깃발을 끌어내려 그곳이 호드의 것임을 천명하라.\n\n어서 가라, <name>... 임무를 완수한 후 돌아와서 보고하도록!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8121] = {title = "거점 네 곳 점령", objective = "아라시 분지로 가서 네 곳의 거점을 동시에 확보하는 임무를 완수한 다음 해머폴에 있는 죽음의경비대장 드와이어에게 돌아가십시오.", description = "<name>, 아라시 분지의 치열한 전투에서 펼친 자네의 활약상은 이미 많은 이의 귀에 들어갔다. 이번 임무도 훌륭히 완수할 것이라 믿네.\n\n이제 아라소르 연맹 놈들에게 본때를 보여 줄 때가 왔어. 아라시 분지에서 놈들의 세력은 미미하고 곧 모든 걸 잃게 되리란 사실을 똑똑히 가르쳐 줘야 해. 아라시 분지의 전략적 요충지 네 곳을 동시에 점령하는 임무를 맡아줘.\n\n<name>, 성공하면 파멸단으로부터 큰 인정과 존경을 받게 될 거야.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8123] = {title = "아라소르 보급선 끊기", objective = "아라시 분지 전투를 승리로 이끌고 아라시 보급품 상자를 구해 해머폴에 있는 죽음의추적자 몰티스에게 가져가야 합니다.", description = "아라소르 연맹은 아라시 분지를 되찾기 위해 전력을 기울이고 있네. 임시 주둔지로부터 영토를 확장하기 위해 얼라이언스의 모든 종족이 이 먼 곳까지 몰려들고 있어. 놈들을 막아야 해! 가장 좋은 방법은 놈들의 보급품을 빼앗는 거지.\n\n<name>, 자네 도움이 필요하네. 비옥한 토지와 금광, 그리고 실력 있는 대장장이들로 유명한 아라시 분지로 들어가게. 가능한 모든 거점을 점령하여 전투를 승리로 이끈 다음 보급품을 가지고 돌아오도록!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8141] = {title = "잔달라 그림자 부적", objective = "젊은 <class> 친구, 당신은 정말 하루가 다르게 발전하는군요. 아무래도 당신을 잔달라부족의 죽음의 살수, 쉐라 알리크로 받아들일 때가 된 것 같습니다. 수천 년 동안 우리는 잔달라 제국을 위해 암살자로 일해 왔습니다. 하지만 너무 오랫동안 한가하게 지내다 보니 결국 학카르부족이 강력해지도록 방치해 둔 꼴이 되었습니다. 이제 학카르를 다시 상대해야 합니다만 이번에는 트롤 연합군의 지원을 받지 못합니다. 당신과 당신의 동료들이 피의 신과 그의 부하들을 무찌르는 것을 도와야 합니다!\n\n이 부적을 착용하면 도움이 될 겁니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 그림자 부적"},
[8142] = {title = "잔달라 그림자 부적", objective = "음... 당신이 학카르부족에게 헤아릴 수 없이 많은 피해를 준 것이 느껴지는군요. 당신에게서 녀석들의 모조 냄새가 나네요.\n\n물론 그림자 부적이 도움이 되었겠지요? 부적의 힘을 강화시켜 드릴 테니 이리 줘 보십시오.", description = nil, progress = "음... 당신이 학카르부족에게 헤아릴 수 없이 많은 피해를 준 것이 느껴지는군요. 당신에게서 녀석들의 모조 냄새가 나네요.\n\n물론 그림자 부적이 도움이 되었겠지요? 부적의 힘을 강화시켜 드릴 테니 이리 줘 보십시오.", completion = "당신처럼 실력 좋은 암살자라면 무서워 벌벌 떨어 마땅하지. 당신의 적들은 존중하는 법을 배워야 합니다! 녀석들은 죽음의 살수가 휘두르는 칼날의 번뜩임을 보는 순간에야 깨닫게 되겠지요. 그때는 너무 늦었을 테지만 말입니다...", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 그림자 부적"},
[8143] = {title = "잔달라 그림자 부적", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 그림자 부적"},
[8144] = {title = "잔달라 밤그림자 부적", objective = "부적이 더 큰 힘을 원하고 있군요. 이 부적은 그동안 당신이 이루어 온 성과를 모두 흡수해 왔습니다. 줄구룹 곳곳에 쓰러진 수천 구의 트롤 시체들로부터 힘을 충전해 왔지요. 잠시 부적을 내게 건네주십시오. 내 이제 마지막 마법을 부여해 드리겠습니다.", description = nil, progress = "부적이 더 큰 힘을 원하고 있군요. 이 부적은 그동안 당신이 이루어 온 성과를 모두 흡수해 왔습니다. 줄구룹 곳곳에 쓰러진 수천 구의 트롤 시체들로부터 힘을 충전해 왔지요. 잠시 부적을 내게 건네주십시오. 내 이제 마지막 마법을 부여해 드리겠습니다.", completion = "이번이 우리가 쉐라 알리크의 보호 아래 대화할 수 있는 마지막 시간이군요. 당신은 알아야 할 모든 것을 알고 있습니다. 부적을 가지고 가서 놈들을 계속 처치하십시오. 절대로 학카르가 줄구룹을 벗어나서는 안 됩니다.", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 밤그림자 부적"},
[8145] = {title = "혼돈의 소용돌이 덩굴손", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n혼돈의 소용돌이 덩굴손"},
[8146] = {title = "혼돈의 소용돌이 덩굴손", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n혼돈의 소용돌이 덩굴손"},
[8147] = {title = "혼돈의 소용돌이 덩굴손", objective = "여기서도 당신에게 쓰러지는 적들의 비명 소리를 들을 수 있을 정도였습니다. 고통의 비명 소리가 천지에 진동하더군요.\n\n당신은 잔달라부족 트롤 사이에서 이미 꽤 유명해졌습니다. 지금까지 당신이 해 준 모든 일에 대해 고마워하고 있답니다.\n\n자, 한층 더 강하게 만들어 드릴테니 부적을 줘 보세요.", description = nil, progress = "여기서도 당신에게 쓰러지는 적들의 비명 소리를 들을 수 있을 정도였습니다. 고통의 비명 소리가 천지에 진동하더군요.\n\n당신은 잔달라부족 트롤 사이에서 이미 꽤 유명해졌습니다. 지금까지 당신이 해 준 모든 일에 대해 고마워하고 있답니다.\n\n자, 한층 더 강하게 만들어 드릴테니 부적을 줘 보세요.", completion = "이제 당신 부적에 단 한 번만 더 마법을 부여해 드릴 수 있겠군요.", rewards = "다음과 같은 것들을 받습니다:\n\n혼돈의 소용돌이 덩굴손"},
[8148] = {title = "혼돈의 소용돌이의 격노", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n혼돈의 소용돌이의 격노"},
[8149] = {title = "영웅 기념", objective = "서부 역병지대에 있는 우서 경의 무덤으로 가서 그의 석상에 우서의 공물을 사용한 후, 추수절이 끝나기 전에 아이언포지 외곽에 있는 와그너 해머스트라이크에게 돌아가야 합니다.\n\n제공된 아이템: \n", description = "우리는 아제로스의 추수절 기간 동안 우리를 대신해 희생을 감수한 영웅들에게 감사를 표하고 있습니다. 그러한 영웅 중엔 최후의 희생까지 마다하지 않은 경우도 있답니다. 얼라이언스에서 인정하는 영웅들은 많이 있지만, 빛의 수호자 우서 경의 일화만큼 비극적인 건 없지요.\n\n우서 경께 경의를 표할 수 있도록 우리를 도와 서부 역병지대에 있는 그분의 무덤으로 이 공물을 가져가 주십시오. 그분의 석상에 공물을 바친 다음 내게 돌아오십시오. 저는 추수절이 끝날 때까지만 이곳에 머무를 예정이니, 어서 우서 경께 공물을 바치고 돌아와 주시기 바랍니다.", progress = nil, completion = "우서 경께서는 영웅 중의 영웅이셨습니다. 그분의 가장 훌륭한 제자이자 자신의 친아들처럼 아꼈던 아서스가 인간 전체를 배신했을 때 우서 경께서 어떤 고통을 느꼈을지 상상도 할 수 없답니다. 그럼에도 그분은 아서스를 막기 위해 일어나 그를 저지하셨고, 바로 그러한 행동이 그분을 영원히 진정한 성기사로 추앙을 받게 할 원동력이지요. 우서 경께서는 자신이 구하게 될 이들의 목숨만을 생각하며 최후까지 싸우셨지요...\n\n고맙습니다. 당신은 오늘 위대한 영웅에게 공물을 바침으로써 그의 영혼과 추수절의 정신을 기렸습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n빛의 이름으로!"},
[8150] = {title = "영웅 기념", objective = "잿빛 골짜기의 악마벼락 협곡에 있는 그롬 헬스크림의 기념비로 가서 기념비 아래쪽에 그롬의 공물을 사용한 후, 추수절이 끝나기 전에 오그리마 바깥에 있는 야브니르 나샤크에게 돌아가야 합니다.\n\n제공된 아이템: \n", description = "우리는 아제로스의 추수절 기간 동안 우리를 대신해 희생을 감수한 영웅들에게 감사를 표하고 있소. 이러한 영웅 중엔 최후의 희생까지 마다하지 않은 경우도 있지. 호드에서 인정하는 영웅들은 많이 있지만, 그롬 헬스크림님만큼 힘과 희생의 모범을 보인 자는 없소이다.\n\n그롬님께 경의를 표할 수 있도록 잿빛 골짜기의 악마벼락 협곡에 있는 그분의 기념비로 이 공물을 가져가 주시오. 기념비 아래쪽에 이 공물을 바친 다음 내게 돌아오시오. 나는 추수절이 끝날 때까지만 이곳에 머무를 예정이니, 시간 낭비하지 말고 어서 그롬에게 공물을 바치고 오도록 하시오.", progress = nil, completion = "그롬님의 정식 이름인 그롬마쉬는 \"거인의 용기\"란 뜻이오. 홀로 만노로스와 맞서는 데는 그만한 용기로도 부족했지. 그분에 대해 대족장님께서 더할 나위 없이 적당한 말씀을 하셨는데, 오크족의 저주는 그롬과 함께 시작되어서 그롬과 함께 끝이 났다는 거요. 그롬님의 희생, 그리고 그분의 구원은 오늘날 호드가 번성하게 된 근원이라 할 수 있으니, 아주 딱 어울리는 말이 아닐 수 없지.\n\n고맙소. 당신은 오늘 위대한 영웅에게 공물을 바침으로써 그의 영혼과 추수절의 정신을 기렸소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n호드의 영웅 헬스크림"},
[8151] = {title = "사냥꾼의 부적", objective = "아즈샤라에 있는 오그틴크와 대화해야 합니다.", description = "아즈샤라의 오그틴크가 자네와 같은 숙련된 사냥꾼을 찾는다는 전갈을 보내왔네. 그는 자신의 부족을 떠나 세나라온 의회를 돕는 펄볼그 사냥꾼이라네. 그가 가르치는 교훈은 그의 기술을 나눈 다른 자의 지혜를 풍성하게 하고, 그들을 이끌어 정도를 유지시킨다네. 자네는 그와 대화가 잘 통할 거야.\n\n오그틴크는 엘다라스 폐허의 북동쪽에 있는 아즈샤라의 절벽 꼭대기에 살고 있네.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8152] = {title = "REUSE", objective = "아즈샤라의 오그틴크와 대화해야 합니다.준비가 다 되었다 생각되면 아즈샤라에 가서 오그틴크라는 이름을 가진 현명한 펄볼그 사냥꾼을 만나 보십시오. 당신에게 가르침을 주고 길을 안내해 줄 것입니다.\n\n오그틴크는 아즈샤라의 엘다라스 폐허 북동쪽에 있는 절벽 꼭대기에 있습니다.퀘스트 완료 시 보상:\n\n", description = "준비가 다 되었다 생각되면 아즈샤라에 가서 오그틴크라는 이름을 가진 현명한 펄볼그 사냥꾼을 만나 보십시오. 당신에게 가르침을 주고 길을 안내해 줄 것입니다.\n\n오그틴크는 아즈샤라의 엘다라스 폐허 북동쪽에 있는 절벽 꼭대기에 있습니다.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[8153] = {title = "순록 뿔", objective = "아즈샤라에 있는 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 완전한 순록 뿔 한 쌍을 가져가야 합니다.", description = "순록은 아제로스에서 가장 강력한 뿔을 가지고 있지. 이 뿔은 자신을 공격하는 자를 들이받거나 종종 상대방의 몸에 상처를 입히는 등 순록이 자기 방어를 위해 사용하곤 한다. 완전한 순록 뿔은 최고의 자신감을 지닌 짐승의 영혼을 나타내는 것이야.\n\n네가 그런 뿔을 지니고 있으면 그와 똑같은 자신감이 생길 것이다. 덩치큰 이끼발굽순록을 잡아 완전한 순록 뿔을 구해 내게 가져오게.", progress = "뿔은 찾았나?", completion = "이런 걸 구하다니 날카로운 눈과 상당한 인내력을 가진 게 틀림없군. 잘했다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8154] = {title = "아라시 분지 자원!", objective = "아라시 분지의 전투를 승리로 이끌고 아라시 보급품 상자를 구해 임시 주둔지에 있는 하사관 매클리어에게 가져가야 합니다.", description = "전쟁은 병사들의 힘으로 치르는 거라죠. 병사라면 다들 그렇게 얘기할 거예요! 하지만 장비가 형편없거나 제대로 먹지 못하고 전투에 임한다면 시작하기도 전에 벌써 진 거나 마찬가지랍니다!\n\n그래서 아라시 분지가 중요한 거예요. 이 분지는 자원의 보고예요. 광석, 무기, 식량, 목재... 이 주요 자원들을 모두 이곳에서 구할 수 있으니까요.\n\n<name>, 당신께 부탁할 일이 하나 있어요. 아라시 분지로 가서 적보다 더 많은 거점을 확보하여 전투를 승리로 이끌고 보급품 상자 하나를 가지고 돌아오세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8155] = {title = "아라시 분지 자원!", objective = "아라시 분지의 전투를 승리로 이끌고 아라시 보급품 상자를 가지고 임시 주둔지에 있는 하사관 매클리어에게 돌아가야 합니다.", description = "전쟁은 병사들의 힘으로 치르는 거라죠. 병사라면 다들 그렇게 얘기할 거예요! 하지만 장비가 형편없거나 제대로 먹지 못하고 전투에 임한다면 시작하기도 전에 벌써 진 거나 마찬가지랍니다!\n\n그래서 아라시 분지가 중요한 거예요. 이 분지는 자원의 보고예요. 광석, 무기, 식량, 목재... 이 주요 자원들을 모두 이곳에서 구할 수 있으니까요.\n\n<name>, 당신께 부탁할 일이 하나 있어요. 아라시 분지로 가서 적보다 더 많은 거점을 확보하여 전투를 승리로 이끌고 보급품 상자 하나를 가지고 돌아오세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8156] = {title = "아라시 분지 자원!", objective = "아라시 분지의 전투를 승리로 이끌고 아라시 보급품 상자를 구해 임시 주둔지에 있는 하사관 매클리어에게 가져가야 합니다.", description = "전쟁은 병사들의 힘으로 치르는 거라죠. 병사라면 다들 그렇게 얘기할 거예요! 하지만 장비가 형편없거나 제대로 먹지 못하고 전투에 임한다면 시작하기도 전에 벌써 진 거나 마찬가지랍니다!\n\n그래서 아라시 분지가 중요한 거예요. 이 분지는 자원의 보고예요. 광석, 무기, 식량, 목재... 이 주요 자원들을 모두 이곳에서 구할 수 있으니까요.\n\n<name>, 당신께 부탁할 일이 하나 있어요. 아라시 분지로 가서 적보다 더 많은 거점을 확보하여 전투를 승리로 이끌고 보급품 상자 하나를 가지고 돌아오세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8160] = {title = "아라소르 보급선 끊기", objective = "아라시 분지 전투를 승리로 이끌고 아라시 보급품 상자를 구해 해머폴에 있는 죽음의추적자 몰티스에게 가져가야 합니다.", description = "아라소르 연맹은 아라시 분지를 되찾기 위해 전력을 기울이고 있네. 임시 주둔지로부터 영토를 확장하기 위해 얼라이언스의 모든 종족이 이 먼 곳까지 몰려들고 있어. 놈들을 막아야 해! 가장 좋은 방법은 놈들의 보급품을 빼앗는 거지.\n\n<name>, 자네 도움이 필요하네. 비옥한 토지와 금광, 그리고 실력 있는 대장장이들로 유명한 아라시 분지로 들어가게. 가능한 모든 거점을 점령하여 전투를 승리로 이끈 다음 보급품을 가지고 돌아오도록!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
