[8162] = {title = "아라소르 보급선 끊기", objective = "아라시 분지 전투를 승리로 이끌고 아라시 보급품 상자를 구해 해머폴에 있는 죽음의추적자 몰티스에게 가져가야 합니다.", description = "아라소르 연맹은 아라시 분지를 되찾기 위해 전력을 기울이고 있네. 임시 주둔지로부터 영토를 확장하기 위해 얼라이언스의 모든 종족이 이 먼 곳까지 몰려들고 있어. 놈들을 막아야 해. 가장 좋은 방법은 놈들의 보급품을 빼앗는 거지.\n\n<name>, 자네 도움이 필요해. 비옥한 토지와 금광, 그리고 실력 있는 대장장이들로 유명한 아라시 분지로 들어가게. 가능한 모든 거점을 점령하여 전투를 승리로 이끈 다음 보급품을 가지고 돌아오도록!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8166] = {title = "아라시 분지의 전투", objective = "금광, 제재소, 대장간, 그리고 농장을 공격한 후 임시 주둔지에 있는 야전사령관 오슬라이트에게 돌아가십시오.", description = "<name>, 아라시 분지에서는 자원과 영토를 놓고 전투를 벌이고 있소. 우리 부대에 필요한 보급품을 대려면 그곳 거점을 반드시 확보해야 하오. 아라시 분지 기지에서 멀리 떨어진 거점들을 공격하는 임무를 맡기겠소이다.\n\n적이 점령하고 있는 금광, 제재소, 대장간, 그리고 농장을 공격하시오. 적의 깃발을 찾아서 모두 뽑아 버리는 거요!\n\n네 곳의 깃발을 모두 뽑은 다음 돌아와 보고하시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8167] = {title = "아라시 분지의 전투", objective = "금광, 제재소, 대장간, 그리고 농장을 공격한 후 임시 주둔지에 있는 야전사령관 오슬라이트에게 돌아가십시오.", description = "<name>, 아라시 분지에서는 자원과 영토를 놓고 전투를 벌이고 있소. 우리 부대에 필요한 보급품을 대려면 그곳 거점을 반드시 확보해야 하오. 아라시 분지 기지에서 멀리 떨어진 거점들을 공격하는 임무를 맡기겠소이다.\n\n적이 점령하고 있는 금광, 제재소, 대장간, 그리고 농장을 공격하시오. 적의 깃발을 찾아서 모두 뽑아 버리는 거요!\n\n네 곳의 깃발을 모두 뽑은 다음 돌아와 보고하시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8168] = {title = "아라시 분지의 전투", objective = "금광, 제재소, 대장간, 그리고 농장을 공격한 후 임시 주둔지에 있는 야전사령관 오슬라이트에게 돌아가십시오.", description = "<name>, 아라시 분지에서는 자원과 영토를 놓고 전투를 벌이고 있소. 우리 부대에 필요한 보급품을 대려면 그곳 거점을 반드시 확보해야 하오. 아라시 분지 기지에서 멀리 떨어진 거점들을 공격하는 임무를 맡기겠소이다.\n\n적이 점령하고 있는 금광, 제재소, 대장간, 그리고 농장을 공격하시오. 적의 깃발을 찾아서 모두 뽑아 버리는 거요!\n\n네 곳의 깃발을 모두 뽑은 다음 돌아와 보고하시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8169] = {title = "아라시 분지의 전투", objective = "아라시 분지의 금광, 제재소, 대장간, 그리고 마구간을 공격한 다음 해머폴에 있는 죽음의경비대장 드와이어에게 돌아가십시오.", description = "자네도 들었겠지만, 아라소르 연맹이 아라시 분지에 대규모 병력을 파견하고 있다고 한다. 식량과 보급품이 필요한 얼라이언스 바보들이 그곳의 풍부한 자원을 확보하려는 것이지. 놈들에게 아라시 분지는 절대로 다시 인간의 손에 넘어가지 않을 것이라는 걸 가르쳐 줘야 한다!\n\n아라시 분지로 가서 금광, 제재소, 대장간, 마구간을 공격하라. 놈들의 깃발을 끌어내려 그곳이 호드의 것임을 천명하라.\n\n어서 가라, <name>... 임무를 완수한 후 돌아와서 보고하도록!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8170] = {title = "아라시 분지의 전투", objective = "아라시 분지의 금광, 제재소, 대장간, 그리고 마구간을 공격한 다음 해머폴에 있는 죽음의경비대장 드와이어에게 돌아가십시오.", description = "자네도 들었겠지만, 아라소르 연맹이 아라시 분지에 대규모 병력을 파견하고 있다고 한다. 식량과 보급품이 필요한 얼라이언스 바보들이 그곳의 풍부한 자원을 확보하려는 것이지. 놈들에게 아라시 분지는 절대로 다시 인간의 손에 넘어가지 않을 것이라는 걸 가르쳐 줘야 한다!\n\n아라시 분지로 가서 금광, 제재소, 대장간, 마구간을 공격하라. 놈들의 깃발을 끌어내려 그곳이 호드의 것임을 천명하라.\n\n어서 가라, <name>... 임무를 완수한 후 돌아와서 보고하도록!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8171] = {title = "아라시 분지의 전투", objective = "아라시 분지의 금광, 제재소, 대장간, 그리고 마구간을 공격한 다음 해머폴에 있는 죽음의경비대장 드와이어에게 돌아가십시오.", description = "자네도 들었겠지만, 아라소르 연맹이 아라시 분지에 대규모 병력을 파견하고 있다고 한다. 식량과 보급품이 필요한 얼라이언스 바보들이 그곳의 풍부한 자원을 확보하려는 것이지. 놈들에게 아라시 분지는 절대로 다시 인간의 손에 넘어가지 않을 것이라는 걸 가르쳐 줘야 한다!\n\n아라시 분지로 가서 금광, 제재소, 대장간, 마구간을 공격하라. 놈들의 깃발을 끌어내려 그곳이 호드의 것임을 천명하라.\n\n어서 가라, <name>... 임무를 완수한 후 돌아와서 보고하도록!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8181] = {title = "예킨야와의 대면", objective = "예킨야와 대화해야 합니다.", description = "모쉬아루 서판을 철저히 조사해 봤는데, 나쁜 소식일세. 학카르는 자네가 녀석을 사로잡는 데 쓴 바로 그 알을 통해서 그의 진정한 모습, 즉 신의 모습으로 다시 태어날 수 있다네. 예킨야는 그 알이 학카르를 가두기 위한 것이라고 했지만, 그게 아니라 학카르를 환생시키기 위한 거였어! 그 트롤 녀석이 자네를 속인 걸세!\n\n예킨야를 찾아가 그 알을 달라고 하게나. 학카르의 환생을 막기에 너무 늦지 않았기를 빌라고!", progress = nil, completion = "그러니까, 그 늙은 드워프 아이언부트와 얘기를 하고 잃어버린 모쉬아루 서판을 찾은 모양이로군, 그런 거요? 성가신 발굴조사단장 녀석...\n\n뭐, 그렇더라도 상관없지. 이 세계를 구하기에는 이미 너무 늦었소. 학카르님은 이미 환생하셨고 지금도 그 힘이 점점 더 커지고 있으니까... 고대 트롤 왕국 줄구룹의 깊은 곳에서 말이지! 그분이 오셨소! 그분께서 피와 공포로 세계를 지배하실 것이오!\n\n당신에게 고맙다는 말을 꼭 전해야겠군그래. 당신의 도움 덕택에 영혼의 약탈자 학카르님의 환생을 앞당길 수 있었소이다!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n빛 바랜 학카리 망토너덜너덜한 학카리 단망토\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8182] = {title = "라스타칸의 대리인", objective = "가시덤불 골짜기에 있는 몰소르와 대화해야 합니다.", description = "음, 우리가 가장 염려하던 대로 되어 버렸네. 전설에 의하면 영혼의 약탈자는 절대 권력을 거머쥐고 악과 공포로 고대 트롤 사회를 지배했다고 하네. 지금 그를 멈추지 못하면 이번에는 아제로스 전역을 지배하게 될지도 모르네!\n\n이 어둠의 물결을 막는 데 도움을 줄 수 있을 만한 잔달라 부족 트롤 사절단이 있는데, 그들은 줄쿤다의 폐허 서쪽, 가시덤불 골짜기 해안에서 떨어져 있는 요잠바 섬에서 야영하고 있네. 그들의 지도자인 몰소르와 얘기해 보게. 그리고 그가 학카르를 물리칠 방법을 알고 있기를 빌어 보자고.", progress = nil, completion = "아이언부트라는 발굴조사단장이 보내서 왔나? 그 종족은 아주 현명한 자들이지. 자네를 나에게 보낸 건 더욱 현명한 일이 아닐 수 없군. 나와 잔달라 부족 트롤들이 학카르를 물리치는 방법을 하나 알고 있지.\n\n이 섬에 있는 트롤들과 얘기해 보고, 그들의 얘기에 귀 기울이면서 각오를 단단히 하게. 자네가 앞으로 해야 할 일은 아주 위험할테니까 말이야.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8183] = {title = "학카르의 심장", objective = "요잠바 섬에 있는 몰소르에게 학카르의 심장을 가져가야 합니다.", description = "학카르의 심장 안에서 타오르는 열기가 느껴집니다. 영혼의 약탈자 학카르를 물리치긴 했지만, 그 힘의 핵은 아직도 이 저주 받은 기관 속에 남아 있습니다.", progress = "자네 주변에 사악한 악취가 풍기는군. 학카르의 저주를 받은겐가?", completion = "아, 학카르의 심장이로군. 그렇다면 학카르를 쓰러뜨렸다는 얘기로군! 자네는 이 세계를 구원한 거야!\n\n자네의 이 큰 공로를 어찌 다 말로 표현할 수 있겠나. 자네는 진정 이 땅의 영웅일세!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n잔달라의 영웅 휘장잔달라의 영웅 부적잔달라의 영웅 메달\n\n다음과 같은 것들 또한 받습니다:\n\n"},
