[8192] = {title = "자연의 은총", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n자연의 은총"},
[8193] = {title = "낚시왕 선발 대회", objective = "아제로스의 모든 낚시꾼은 들으십시오! 오늘 오후 2시부터 4시까지 최고의 낚시왕을 선발하는 대회가 열립니다! 가시덤불 해안에 출몰하는 맛둥어 떼에서 낚아올린 맛둥어 40마리를 제일 먼저 가져오는 이에게 낚시왕이라는 영광스러운 칭호를 내리겠습니다!\n\n아쉽게 우승은 놓치더라도 여기 우리 견습생이 맛둥어 5마리마다 제값을 두둑이 쳐줄 겁니다.\n\n맛둥어는 금방 상하니까 어서 가져오세요!", description = nil, progress = "아제로스의 모든 낚시꾼은 들으십시오! 오늘 오후 2시부터 4시까지 최고의 낚시왕을 선발하는 대회가 열립니다! 가시덤불 해안에 출몰하는 맛둥어 떼에서 낚아올린 맛둥어 40마리를 제일 먼저 가져오는 이에게 낚시왕이라는 영광스러운 칭호를 내리겠습니다!\n\n아쉽게 우승은 놓치더라도 여기 우리 견습생이 맛둥어 5마리마다 제값을 두둑이 쳐줄 겁니다.\n\n맛둥어는 금방 상하니까 어서 가져오세요!", completion = "낚시왕으로 뽑히고 싶다면 서둘러 물고기를 잡아 제출해주십시오! 난 말이죠, 계속 아무것도 못 먹고 여기 이렇게 서 있단 말입니다! 어서 물고기를 이리 주세요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아케이나이트 낚싯대낚시대가의 낚싯바늘\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8194] = {title = "수습 낚시꾼", objective = "이미 대회에 우승자가 나왔다고 해도 관계없어요. 전 시세대로 계속 맛둥어를 살 거랍니다. 그 누가 뭐라고 하든지요!", description = nil, progress = "이미 대회에 우승자가 나왔다고 해도 관계없어요. 전 시세대로 계속 맛둥어를 살 거랍니다. 그 누가 뭐라고 하든지요!", completion = "이런 게 누이 좋고 매부 좋은 거죠!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8195] = {title = "줄리안, 래즈자쉬, 학카리부족 주화", objective = "나는 트롤 부족 주화라고 불리는 마력의 보물을 찾고 있다네. 줄구룹의 다양한 부족들이 사용하는 통화로, 각각 신비로우면서도 강력한 모조가 부여되어 있지.\n\n그 주화는 서로 다른 아홉 가지 종류가 있는데, 어떤 것은 내 동료들이 잔달라 영웅들에게 줄 다양한 보호구를 제작하는 데 쓰려고 찾고 있다네. 혹시 여분이 생기거든 세 개당 우리 부족의 잔달라 명예 징표 하나로 교환해 주겠네. 그 징표들은 우리 영웅들에게 특별한 물건들을 제공하는 상인 린워쇼에게 쓸 수 있을 걸세.", description = nil, progress = "나는 트롤 부족 주화라고 불리는 마력의 보물을 찾고 있다네. 줄구룹의 다양한 부족들이 사용하는 통화로, 각각 신비로우면서도 강력한 모조가 부여되어 있지.\n\n그 주화는 서로 다른 아홉 가지 종류가 있는데, 어떤 것은 내 동료들이 잔달라 영웅들에게 줄 다양한 보호구를 제작하는 데 쓰려고 찾고 있다네. 혹시 여분이 생기거든 세 개당 우리 부족의 잔달라 명예 징표 하나로 교환해 주겠네. 그 징표들은 우리 영웅들에게 특별한 물건들을 제공하는 상인 린워쇼에게 쓸 수 있을 걸세.", completion = "아주 훌륭하군. 이 주화들은 점점 커지는 우리 무기고에 큰 도움이 될 걸세... 바로 혈신의 현신에 대비해 우리 부족을 수호하는 데 사용하게 될 거야. 자네의 노고에 대한 우리 부족의 감사와 함께 이 잔달라 명예 징표를 받아 주게나!", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 명예 징표"},
[8196] = {title = "알짜 망고", objective = "남쪽 바다에 있는 섬들 중 많은 곳에서는 극히 강력한 알짜 망고가 자라지요. 그 망고 하나만 먹으면 육체와 정신이 모두 팔팔하게 되살아나게 된답니다. 한 번도 먹어 본 적이 없다면 손해 보고 있는 거예요!\n\n우리가 이 섬에 재고를 충분히 보유하고 있으니 잔달라 명예 징표 하나당 망고 몇 개를 주도록 하지요. 징표를 어떻게 얻는지 모른다면 빈차샤와 얘기해 보도록 하고, 그렇지 않다면 당장 거래를 합시다!", description = nil, progress = "남쪽 바다에 있는 섬들 중 많은 곳에서는 극히 강력한 알짜 망고가 자라지요. 그 망고 하나만 먹으면 육체와 정신이 모두 팔팔하게 되살아나게 된답니다. 한 번도 먹어 본 적이 없다면 손해 보고 있는 거예요!\n\n우리가 이 섬에 재고를 충분히 보유하고 있으니 잔달라 명예 징표 하나당 망고 몇 개를 주도록 하지요. 징표를 어떻게 얻는지 모른다면 빈차샤와 얘기해 보도록 하고, 그렇지 않다면 당장 거래를 합시다!", completion = "공정한 거래였습니다, 잔달라 부족의 친구여. 부족의 축복과 함께 남쪽 바다의 감미로운 과일을 마음껏 즐기시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n알짜 망고"},
[8201] = {title = "머리카락 수집", objective = "역술사의 머리카락 5개를 신성한 굴레에 묶은 후, 요잠바 섬에 있는 엑잘에게 구루바시 부족 머리카락으로된 전리품을 가져가야 합니다.", description = "사실일세. 학카르는 이제 줄구룹에 살면서 우리 신들의 힘을 뒤집어쓰고 있어. 이에 매혹된 대사제들이 우리가 섬기는 가장 신성한 신들의 힘을 학카르에게 쏟아붓고 있다네. 학카르는 곧 아제로스의 그 누구보다도 큰 힘을 지니게 될 걸세! 그를 멈추어야만 해!\n\n이 신성한 굴레를 가져가서 우리 신들의 힘을 학카르에게 집중시키고 있는 대사제들의 머리카락을 묶어 오게.\n\n이 일을 마치거든 다시 내게 오게나.", progress = "머리카락은 모아 왔나? 학카르가 더 큰 힘을 얻게 되는 것을 막아야만 하네!", completion = "모아 왔군! 자네는 우리 신들의 힘이 약탈당하는 것을 멈추고 학카르의 힘을 약화시켰네!\n\n자네의 행위는 실로 영웅적이야. 오랜 시간이 흘러 이 트롤의 머리카락의 색이 바랜 후에도 자네에게 자비를 구하게 되기를.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n쭈그러든 해골 허리띠주름진 해골 허리띠보존된 해골 허리띠작은 해골 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8221] = {title = "희귀한 키퍼의 천사돔", objective = "*위잉* *딸깍*\n\n낚시로봇 5000은 낚시의 대가이신 블루길님이 목록에 올릴 희귀한 물고기를 찾도록 설계되어 있습니다. 키퍼의 천사돔을 제출하시면 아주 훌륭한 보상을 드리도록 하겠습니다.\n\n *찌이익* *위잉*", description = nil, progress = "*위잉* *딸깍*\n\n낚시로봇 5000은 낚시의 대가이신 블루길님이 목록에 올릴 희귀한 물고기를 찾도록 설계되어 있습니다. 키퍼의 천사돔을 제출하시면 아주 훌륭한 보상을 드리도록 하겠습니다.\n\n *찌이익* *위잉*", completion = "*위잉* \n\n키퍼의 천사돔 식별 완료.\n\n 보상 제공 가능합니다.\n\n *딸깍 딸깍* *지지지직*", rewards = "다음과 같은 것들을 받습니다:\n\n행운의 낚시 모자"},
[8222] = {title = "붉은 전갈 피", objective = "다크문 축제에서 일하면서 고객들에 대해 많은 것을 배웠지요. 지혜가 담긴 조언 하나 해 드리죠. 고객들은 반짝반짝 빛나는 물건을 아주 좋아합니다! 뭐든 상관없어요. 부서진 의자 다리라도 반짝반짝 빛나게만 해 놓으면 아이들이 저마다 하나씩 사려고 먼 곳에서 찾아오곤 한답니다!\n\n그래서 말인데, 붉은 전갈 피가 필요합니다. 실리더스나 저주받은 땅, 불타는 평원 같은 곳에 서식하는 전갈들에게서 구할 수 있을 겁니다.", description = nil, progress = "다크문 축제에서 일하면서 고객들에 대해 많은 것을 배웠지요. 지혜가 담긴 조언 하나 해 드리죠. 고객들은 반짝반짝 빛나는 물건을 아주 좋아합니다! 뭐든 상관없어요. 부서진 의자 다리라도 반짝반짝 빛나게만 해 놓으면 아이들이 저마다 하나씩 사려고 먼 곳에서 찾아오곤 한답니다!\n\n그래서 말인데, 붉은 전갈 피가 필요합니다. 실리더스나 저주받은 땅, 불타는 평원 같은 곳에 서식하는 전갈들에게서 구할 수 있을 겁니다.", completion = "오, 가져오셨군요! 대단히 감사합니다! 이 피로 페인트를 만들어서 온갖 종류의 값싼 폐품들을 빛나는 보물로 탈바꿈시킬 거랍니다!\n\n자, 상품권 여기 있습니다. 다시 한번 감사 드려요!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[8223] = {title = "더 많은 붉은 전갈 피", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[8224] = {title = "희귀한 데지안 여왕물고기", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n고탄성 이터늄 낚싯줄"},
[8225] = {title = "희귀한 브로넬의 푸른줄무늬날치", objective = "*위잉* *딸깍*\n\n낚시로봇 5000은 낚시의 대가이신 블루길님이 목록에 올릴 희귀한 물고기를 찾도록 설계되어 있습니다. 브로넬의 푸른줄무늬날치를 제출하시면 아주 훌륭한 보상을 드리도록 하겠습니다.\n\n *찌이익* *위잉*", description = nil, progress = "*위잉* *딸깍*\n\n낚시로봇 5000은 낚시의 대가이신 블루길님이 목록에 올릴 희귀한 물고기를 찾도록 설계되어 있습니다. 브로넬의 푸른줄무늬날치를 제출하시면 아주 훌륭한 보상을 드리도록 하겠습니다.\n\n *찌이익* *위잉*", completion = "*위잉*\n$브로넬의 푸른줄무늬날치 식별 완료.\n\n 보상 제공 가능합니다.\n\n *딸깍 딸깍* *지지지직*", rewards = "다음과 같은 것들을 받습니다:\n\n내트 페이글의 최고급 낚시 장화"},
[8227] = {title = "내트의 줄자", objective = "먼지진흙 습지대에 있는 내트 페이글에게 내트의 줄자를 돌려줘야 합니다.", description = "이리저리 흩어져 있는 미끼와 낚시 도구들 사이에 돌돌 말아 놓은 비단 줄자가 있습니다. 줄자에 붙어 있는 꼬리표에 다음과 같이 쓰여 있습니다.\n\n\"내트 페이글, 먼지진흙 습지대.\"", progress = "어서 오세요. 낚시하러 오셨나요?", completion = "이런, 당신이 내가 제일 아끼는 줄자를 찾았군요! 내가 이 줄자를 굉장히 아낀답니다! 내가 잡은 물고기 중 제일 큰 것들의 크기를 이 줄자로 쟀었지요...\n\n하지만 줄구룹에서 잃어버렸는데... 당신, 줄구룹에 가봤나요? 그 전설적인 가즈란카는 봤나요?\n\n그런데 혹시... 가즈란카 잡아 볼 생각 없습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8228] = {title = "낚시왕 선발대회!", objective = "이번 일요일에 무법항에서 낚시왕 선발대회가 열린다네! 여기 선발대회 규칙을 꼭 읽어 보시고 대회에 참여하라고!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n낚시왕 선발대회!"},
[8229] = {title = "낚시왕 선발대회!", objective = "이번 일요일에 무법항에서 낚시왕 선발대회가 열립니다! 여기 선발대회 규칙을 꼭 읽어 보시고 대회에 참여하세요!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n낚시왕 선발대회!"},
[8231] = {title = "폭풍히드라 사냥", objective = "아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 폭풍히드라 비늘 6개를 가져가야 합니다.", description = "폭풍히드라는 이곳 아즈샤라에서만 서식하는 수륙 양생의 짐승으로, 강하고 회복력이 대단한 녀석이지.\n\n폭풍히드라의 단단하고 반짝이는 비늘은 바로 사냥꾼의 힘을 그대로 반영하는 것이다.\n\n아즈샤라의 해안을 따라 서식하는 폭풍히드라를 추적해 사냥하고 녀석들의 비늘을 내게 가져와라.", progress = "성공했나?", completion = "폭풍히드라는 물리치기가 쉽지 않지. 더구나 물이 많은 환경에서라면 더더욱 그렇다네.\n\n너는 더 강한 사냥감을 사냥할 준비가 됐음을 스스로 입증해 보였군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8232] = {title = "녹색 비룡 몰파즈", objective = "아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 몰파즈의 이빨을 가져가야 합니다.", description = "이제 나는 녹색 비룡인 몰파즈를 처치하고 그 이빨을 내게 가져오는 위험한 사냥을 부탁할 것이다. 몰파즈는 슬픔의 늪에 있는 아탈학카르 신전의 깊은 곳에서 살고 있다.\n\n그 비룡은 여럿이서 힘을 합쳐 상대해야 할 적이니, 녀석을 처치하고자 하는 다른 이들을 찾아보도록 해라.\n\n그 비룡의 이빨은 사냥꾼이 다른 동료들과 함께 노력하여 알아내게 되는 힘을 상징하는 것이다. 그걸 내개 가져오면 많은 것을 알게 될 것이야.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n사냥용 창데빌사우루스 눈데빌사우루스 이빨\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8233] = {title = "간단한 부탁", objective = "라벤홀트 장원에 있는 조라크 라벤홀트 경과 대화해야 합니다.", description = "조라크 라벤홀트 경이 자네가 와주기를 청하고 있소. 라벤홀트 경이 처한 문제는 비밀이어서 내가 더 이상 얘기해 줄 수가 없소이다.\n\n라벤홀트 장원은 힐스브래드 구릉지에 있는 던홀드 요새의 북서쪽 산에 있는 오솔길을 따라가면 찾을 수 있을 것이오. 자, 어서 가보시오.", progress = nil, completion = "어서 오시오. 아주 잘 오셨소이다! 대환영이고 말고! 자, 자리에 앉아 나와 함께 간단한 문제를 의논해 보도록 합시다.\n\n그게, 최근 내가 아주 소중한 물건을 잃어 버렸는데, 막말로 어떤 대가를 치르고서라도 반드시 되찾고 싶소. 당신한테도 돌아오는 게 있으니 그건 걱정하지 마시오! 아, 물론 아주 좋은 거고 말고.\n\n자, 그럼 어떻게 하겠소, 모험을 좀 해 볼 생각이 있소이까?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8234] = {title = "봉인된 하늘색 자루", objective = "아즈샤라에 있는 나무구렁일족 주술사에게서 봉인된 하늘색 자루를 되찾은 후, 그 가방을 아즈샤라에 있는 대마법사 실렘에게 가져가야 합니다.", description = "하지만 우선 해야 할 일이 있소. 내가 잃어버렸다는 물건은 작은 파란색 가방인데, 그 안에는 내 개인적인 물건들이 들어 있소이다.\n\n그 도적들은 이미 죽었으니 그 녀석들 뒤를 좇느라 애쓰진 않아도 되오. 우리가 알고 있는 건 그 바보 녀석들이 가방을 열지 못하자, 아즈샤라의 어떤 나무구렁일족 주술사에게 성스러운 유물이라며 팔아 버렸다는 것이라오.\n\n아즈샤라로 가서 교묘한 계략이나 무력을 이용해 그 주술사에게서 가방을 되찾아 오시오. 첫번째 방법을 권장하오. 가방을 손에 넣거든 아즈샤라에 있는 대마법사 실렘에게 가져가시오.", progress = "자네 날 아나?", completion = "라벤홀트 경의 가방을 지니고 있군그래. 애초에 그렇게 말하지 그랬나, 젊은이?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8235] = {title = "암호화된 페이지", objective = "아즈샤라에 있는 대마법사 실렘에게 암호화 된 페이지 10개를 가져가야 합니다.", description = "라벤홀트 경이 우리 둘 모두의 도움을 원하는군. 이 가방에 걸려 있는 마법을 제거하고 싶은 것이야.\n\n유감스럽게도, 최근에 마법 무효화에 관한 책 몇 권을 빼앗겼는데, 야만인들이 파괴해 버리고 말았다네. 그 책의 잔해들은 여전히 내게 아주 소중한 것일세.\n\n암호화된 페이지를 충분하게 가져오면 내가 다시 합칠 수 있다네. 숲수액괴물들은 뭐든 집어 먹는 습성이 있으니 그 녀석들을 처치하는 게 제일 나을 게야. 녀석들은 아즈샤라 북동부에 있을 테니 그리로 가 보게나.", progress = "내 작업을 계속할 수 있을 만큼 페이지를 충분히 구했나?", completion = "그 중에서도 좀 더 온전한 페이지들을 가져온 것 같군. 자네, 그래도 그렇게 아주 쓸모없지는 않은 것 같은데?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8236] = {title = "하늘색 열쇠", objective = "조라크 라벤홀트 경에게 하늘색 열쇠를 가져가야 합니다.", description = "페이지를 해독하고 마법을 제거하는 데 시간이 좀 걸릴 걸세. 다 끝나면 내가 직접 가방을 라벤홀트 경에게 전달하도록 하지.\n\n아직 열쇠를 찾는 일이 남아 있는데, 그건 몰파즈라고 하는 어떤 녹색 비룡이 지니고 있다고 하네. 그 비룡은 입구가 슬픔의 늪에 있는 아탈학카르 신전 깊은 곳에 살고 있지.\n\n동료들을 모아 그 녀석의 소굴로 쳐들어가게. 라벤홀트 경은 자네가 열쇠를 가지고 돌아오기를 기다리고 있을 것이야.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n흑단 복면침묵의 장화그늘박쥐 망토\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8237] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8238] = {title = "구루바시, 썩은가지, 마른나무껍질부족 주화", objective = "나는 트롤 부족 주화라고 불리는 마력의 보물을 찾고 있다네. 줄구룹의 다양한 부족들이 사용하는 통화로, 각각 신비로우면서도 강력한 모조가 부여되어 있지.\n\n그 주화는 서로 다른 아홉 가지 종류가 있는데, 어떤 것은 내 동료들이 잔달라 영웅들에게 줄 다양한 보호구를 제작하는 데 쓰려고 찾고 있다네. 혹시 여분이 생기거든 세 개당 우리 잔달라 명예 징표 하나로 교환해 주겠네. 그 징표는 우리 영웅들에게 특별한 물건들을 제공하는 상인 린워쇼에게 쓸 수 있을 걸세.", description = nil, progress = "나는 트롤 부족 주화라고 불리는 마력의 보물을 찾고 있다네. 줄구룹의 다양한 부족들이 사용하는 통화로, 각각 신비로우면서도 강력한 모조가 부여되어 있지.\n\n그 주화는 서로 다른 아홉 가지 종류가 있는데, 어떤 것은 내 동료들이 잔달라 영웅들에게 줄 다양한 보호구를 제작하는 데 쓰려고 찾고 있다네. 혹시 여분이 생기거든 세 개당 우리 잔달라 명예 징표 하나로 교환해 주겠네. 그 징표는 우리 영웅들에게 특별한 물건들을 제공하는 상인 린워쇼에게 쓸 수 있을 걸세.", completion = "아주 훌륭하군. 이 주화들은 점점 커지는 우리 무기고에 큰 도움이 될 걸세... 바로 혈신의 현신에 대비해 우리 부족을 수호하는 데 사용하게 될 거야. 자네의 노고에 대한 우리 부족의 감사와 함께 이 잔달라 명예 징표를 받아 주게나!", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 명예 징표"},
[8239] = {title = "성난모래, 백골가루, 붉은머리부족 주화", objective = "나는 트롤 부족 주화라고 불리는 마력의 보물을 찾고 있다네. 줄구룹의 다양한 부족들이 사용하는 통화로, 각각 신비로우면서도 강력한 모조가 부여되어 있지.\n\n그 주화는 서로 다른 아홉 가지 종류가 있는데, 어떤 것은 내 동료들이 잔달라 영웅들에게 줄 다양한 보호구를 제작하는 데 쓰려고 찾고 있다네. 혹시 여분이 생기거든 세 개당 우리 부족의 명예 징표 하나로 교환해 주겠네. 그 징표들은 우리 영웅들에게 특별한 물건들을 제공하는 상인 린워쇼에게 쓸 수 있을 걸세.", description = nil, progress = "나는 트롤 부족 주화라고 불리는 마력의 보물을 찾고 있다네. 줄구룹의 다양한 부족들이 사용하는 통화로, 각각 신비로우면서도 강력한 모조가 부여되어 있지.\n\n그 주화는 서로 다른 아홉 가지 종류가 있는데, 어떤 것은 내 동료들이 잔달라 영웅들에게 줄 다양한 보호구를 제작하는 데 쓰려고 찾고 있다네. 혹시 여분이 생기거든 세 개당 우리 부족의 명예 징표 하나로 교환해 주겠네. 그 징표들은 우리 영웅들에게 특별한 물건들을 제공하는 상인 린워쇼에게 쓸 수 있을 걸세.", completion = "아주 훌륭하군. 이 주화들은 점점 커지는 우리 무기고에 큰 도움이 될 걸세... 바로 혈신의 현신에 대비해 우리 부족을 수호하는 데 사용하게 될 거야. 자네의 노고에 대한 우리 부족의 감사와 함께 이 잔달라 명예 징표를 받아 주게나!", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 명예 징표"},
[8240] = {title = "잔자를 위한 장신구", objective = "줄구룹에서 찾은 학카리 장신구 중 아무거나 가져와 요잠바 섬에 있는 잔자의 제단에서 파괴한 후, 제단 근처에 있는 빈차샤와 대화해야 합니다.", description = "여러 가지 학카리 장신구를 파괴하는 것은 우리에게 대단히 중요한 일일세. 얼마나 중요한지 우리 부족이 아닌 외부인이 스스로 이 일을 해준다면 환영할 정도라네!\n\n줄구룹에서 찾은 장신구 중 아무것이나 잔자의 제단으로 가져가서 파괴하도록 하게. 이번만 우리 부족의 명예 징표 하나를 추가로 더 주도록 하지. 이건 자네가 평소에 받는 것보다 훨씬 더 많은 것일세.\n\n잔자의 축복을 직접 느껴 보게!", progress = "잔자의 제단에서 장신구를 파괴했나? 그리하면 잔자의 축복을 두 배로 받게 될 것일세!", completion = "아주 잘 했네... 혈신의 졸개들을 물리치고 장신구를 하나씩 빼앗아 올 때마다 마침내 그들을 영원히 물리치게 되는 데 우리 모두 한 발짝 더 가까이 가게 되는 것일세. 자네는 그 고귀한 행동으로 우리 물론 자네 자신에게도 명예를 안겨 주었네.\n\n기억하게나. 줄구룹에서 찾는 장신구는 언제든지 잔자의 제단에서 파괴해도 좋네. 하나를 파괴할 때마다 잔달라 명예 징표 하나와 신임을 얻게 될 것이야! 소지품에 공간을 충분히 비워둬야 명예 징표를 가질 수 있다는 걸 기억해 두라고.", rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 명예 징표"},
[8241] = {title = "불꽃 융해촉진제 재고 재비축 - 철", objective = "아까운 내 시간을 잡담이나 하면서 더 낭비하지는 마시게. 줄어들고 있는 불꽃 융해촉진제 재고를 다시 비축하는 데 주력해야 할 때니까 말이야.\n\n내가 자네에게 부탁할 물건은 다음과 같네.\n\n*인센도사우루스 비늘\n\n*철 주괴\n\n*석탄\n\n당신이 가져올 수 있는 건 모두 다 받지!\n\n대장조합의 눈에 들려면 서두르는 게 좋을 걸세.", description = nil, progress = "아까운 내 시간을 잡담이나 하면서 더 낭비하지는 마시게. 줄어들고 있는 불꽃 융해촉진제 재고를 다시 비축하는 데 주력해야 할 때니까 말이야.\n\n내가 자네에게 부탁할 물건은 다음과 같네.\n\n*인센도사우루스 비늘\n\n*철 주괴\n\n*석탄\n\n당신이 가져올 수 있는 건 모두 다 받지!\n\n대장조합의 눈에 들려면 서두르는 게 좋을 걸세.", completion = "불꽃 융해촉진제는 많을수록 좋은 물건이라네, 젊은이. 내가 됐다고 할 때까지 계속해서 가져오도록 하라고...", rewards = nil},
[8242] = {title = "불꽃 융해촉진제 재고 재비축 - 질긴 가죽", objective = "이보라고, 아까운 내 시간을 잡담이나 하면서 더 낭비하지는 마세나. 줄어들고 있는 불꽃 융해촉진제 재고를 다시 비축하는 데 주력해야 할 때니까 말이야.\n\n내게 자네에게 부탁할 물건은 다음고 같네.\n\n*인센도사우루스 비늘\n\n*질긴 가죽\n\n*석탄\n\n자네가 가져올 수 있는 건 모두 다 받도록 하지!\n\n우리 토륨 대장조합의 눈에 들려면 서두르는 게 좋을 거라고.", description = nil, progress = "이보라고, 아까운 내 시간을 잡담이나 하면서 더 낭비하지는 마세나. 줄어들고 있는 불꽃 융해촉진제 재고를 다시 비축하는 데 주력해야 할 때니까 말이야.\n\n내게 자네에게 부탁할 물건은 다음고 같네.\n\n*인센도사우루스 비늘\n\n*질긴 가죽\n\n*석탄\n\n자네가 가져올 수 있는 건 모두 다 받도록 하지!\n\n우리 토륨 대장조합의 눈에 들려면 서두르는 게 좋을 거라고.", completion = "불꽃 융해촉진제는 많을수록 좋은 물건이라네, 젊은이. 내가 됐다고 할 때까지 계속해서 가져오도록 하라고...", rewards = nil},
[8243] = {title = "잔자의 강력한 음료", objective = "부족에게 명성이 높아졌으니 당신은 이제 우리의 더 강력한 음료 몇 가지를 이용할 수 있게 됐습니다. 잘 보세요... 이것들에는 강한 모조가 깃들어 있답니다. 잔자께서 축복을 내리신 것으로, 모든 모험가들이 마실 수 있지요!\n\n세 가지 종류 중에서 하나를 고를 수 있도록 해 줄테니 그 대가로 잔달라 명예 징표 하나를 가져다 주세요. 참고로 동시에 이 중 하나의 효과만이 당신의 영혼에 흐를 수 있다는 사실을 명심하세요.\n\n자, 거래할 준비가 되거든 내게 알려 주십시오!", description = nil, progress = "부족에게 명성이 높아졌으니 당신은 이제 우리의 더 강력한 음료 몇 가지를 이용할 수 있게 됐습니다. 잘 보세요... 이것들에는 강한 모조가 깃들어 있답니다. 잔자께서 축복을 내리신 것으로, 모든 모험가들이 마실 수 있지요!\n\n세 가지 종류 중에서 하나를 고를 수 있도록 해 줄테니 그 대가로 잔달라 명예 징표 하나를 가져다 주세요. 참고로 동시에 이 중 하나의 효과만이 당신의 영혼에 흐를 수 있다는 사실을 명심하세요.\n\n자, 거래할 준비가 되거든 내게 알려 주십시오!", completion = "공정한 거래였습니다, 잔달라 부족의 친구여. 우리의 찬사와 함께 잔자의 축복을 마음껏 누리시기 바랍니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n잔자의 광휘잔자의 기백잔자의 신속"},
[8246] = {title = "잔달라 모조의 인장", objective = "당신처럼 잔달라 부족 사이에서 명성이 높은 이에게 필요한 아주 특별한 걸 내가 가지고 있지요. 바로 남쪽 바다에 있는 우리 고향에서 곧장 가져온... 잔달라 모조의 인장이랍니다! 이 인장은 당신이 소유한 어떤 어깨보호대라도 강하게 만들어 줄겁니다. 힘, 모조 그리고 평온 중 어떤 걸 찾고 있든지 당신에게 필요한 게 내게 있답니다!\n\n원하는 인장 하나 당 잔달라 명예 징표 15개를 받겠습니다. 징표가 준비되면 즉시 거래를 하도록 하죠!", description = nil, progress = "당신처럼 잔달라 부족 사이에서 명성이 높은 이에게 필요한 아주 특별한 걸 내가 가지고 있지요. 바로 남쪽 바다에 있는 우리 고향에서 곧장 가져온... 잔달라 모조의 인장이랍니다! 이 인장은 당신이 소유한 어떤 어깨보호대라도 강하게 만들어 줄겁니다. 힘, 모조 그리고 평온 중 어떤 걸 찾고 있든지 당신에게 필요한 게 내게 있답니다!\n\n원하는 인장 하나 당 잔달라 명예 징표 15개를 받겠습니다. 징표가 준비되면 즉시 거래를 하도록 하죠!", completion = "공정한 거래였습니다, 잔달라 부족의 친구여. 부족의 축복과 함께 인장을 받으세요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n잔달라 힘의 인장잔달라 모조의 인장잔달라 평온의 인장"},
[8249] = {title = "보관함 수집", objective = "내가 가르치는 <class>들이 자물쇠 따기 기술을 연마해야 해서 적당히 따기 힘든 자물쇠가 필요한데, 잰이 우리한테 만들어 주는 것들은 초보자용으로밖에 적합하지가 않다오.\n\n이렇게 합시다. 내게 견고한 보관함 5개를 가져오면 <class>들 세계에서 최고급으로 알려진 투척용 나이프 몇 개를 주겠소.\n\n상자를 열고 안에 든 걸 샅샅이 뒤져서 가져도 좋지만, 적어도 동전 몇 개 정도는 안에 남겨 두시오... 훈련 중인 <class>들에게도 동기 부여가 필요하니까 말이야.", description = nil, progress = "내가 가르치는 <class>들이 자물쇠 따기 기술을 연마해야 해서 적당히 따기 힘든 자물쇠가 필요한데, 잰이 우리한테 만들어 주는 것들은 초보자용으로밖에 적합하지가 않다오.\n\n이렇게 합시다. 내게 견고한 보관함 5개를 가져오면 <class>들 세계에서 최고급으로 알려진 투척용 나이프 몇 개를 주겠소.\n\n상자를 열고 안에 든 걸 샅샅이 뒤져서 가져도 좋지만, 적어도 동전 몇 개 정도는 안에 남겨 두시오... 훈련 중인 <class>들에게도 동기 부여가 필요하니까 말이야.", completion = "이 칼들이 적들의 품에서 안식을 찾기를... 반드시 그렇게 되기를.", rewards = "다음과 같은 것들을 받습니다:\n\n투척용 검은강철 나이프"},
[8250] = {title = "마법 공예", objective = "대마법사 실렘을 만나기 위한 허가를 얻기 위해 사나스 림요를 찾아야 합니다.", description = "대마법사 실렘이 최근 당신과 같이 경험이 풍부한 자를 찾고 있었소이다.\n\n그를 찾을 생각이라면 아즈샤라로 가면 될 것이오. 그의 탑은 절벽 꼭대기에 있고 그리로 올라갈 수 있는 방법은 대마법사의 거만한 하인이 시전하는 순간이동으로만 가능하오이다.\n\n사나스는 대마법사의 탑 아래 야영지를 꾸리고 있지. 그를 찾으려면 아즈샤라의 큰 길로 가서 엘다라스 폐허의 입구에 갈림길로 가면 되오. 그곳에서 절벽이 나올때까지 쭉 북쪽으로 가시오.", progress = nil, completion = "&lt;비웃는 사나스&gt;\n\n대&lt;class&gt; 실렘님께서 당신의 도착을 기다리고 계시오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n아즈샤라 탑으로 순간이동\n\n다음과 같은 것들을 받습니다:\n\n"},
[8251] = {title = "마법의 티끌", objective = "대마법사 실렘에게 반짝이는 가루 10개를 가져가야 합니다.", description = "아즈샤라의 블러드 엘프들은 자신들이 구한 마법 물건을 분쇄하는 방법을 고안해냈다네. 그들이 만드는 반짝이는 가루는 보통 마력 추출 주문으로 얻을 수 있는 재료와는 달라.\n\n그 티끌을 좀 사오라고 수습생을 보냈더니 녀석들이 그 아일 바로 죽여 버렸지 뭔가. 그 대가를 치르게 해야 하네.\n\n얘기는 이 정도만 하고, 이제 북부 아즈샤라에 있는 블러드 엘프들을 찾아가게. 좀 더 설득력 있는 방법을 써서 그 반짝이는 가루를 얻어 오게나.", progress = "가루는 갖고 왔는가?", completion = "잘 했네! 신비의 화살을 쏘는 것만큼 잘 통하는 방법도 없다니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8252] = {title = "세이렌의 산호", objective = "대마법사 실렘에게 마력 깃든 산호 6개를 가져가야 합니다.", description = "자네 주위를 둘러보게나. 원한의꼬리일족은 아즈샤라의 폐허와 해변을 무참히 침략했네. 최근에 이 비열한 녀석들은 지금까지 아즈샤라에서만 볼 수 있는 희귀한 재료를 알아볼 수 있을 만큼 주변 지리를 익혀왔지.\n\n그 희귀한 재료란 마력 깃든 산호를 말하는 걸세. 뭔가 알 수 없는 이유로 녀석들이 거기에 끌리고 있어. 이 산호가 만에 조금밖에 남아있지 않지만 내 연구에 아주 중요한 재료라네. 원한의꼬리일족 세이렌에게서 마력 깃든 산호를 빼앗아 오게나.", progress = "원한의꼬리일족 세이렌 녀석들은 꽤나 강한 <class>들이야. 허나 자네만큼 노련하지 않았으면 좋겠군...", completion = "아주 훌륭한 산호로군. 자네 솜씨는 아주 정확하고 훌륭해.\n\n이런 수고를 모른 체 넘어갈 수는 없지. 어쩌면 자네는 진정한 시험을 받을 자격이 있는지도 모르겠어...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8253] = {title = "몰파즈 처치", objective = "몰파즈에게서 신비의 결정을 되찾아 대마법사 실렘에게 가져가야 합니다.", description = "아탈라이의 가라앉은 사원 깊은 곳에는 몰파즈라는 이름을 가진 녹색 비룡이 산다네.\n\n오래 전, 녀석은 날 습격해서 내 수습생을 통째로 삼켜버렸다네. 수습생을 잃어본 적이야 전에도 있었지만 그 견습생은 특히나 크고 질 좋은 신비의 결정을 갖고 있었다네.\n\n자네의 강한 친구들을 이끌고 사원으로 쳐들어가게. 몰파즈를 쓰러뜨리고 그 영생의 뱃속에서 신비의 결정을 꺼내 오게나.", progress = "내 오랜 원수를 처치했는가?", completion = "놀랍군. 결정이 오랜 세월 동안 비룡의 마력을 흡수해 강해졌어.\n\n이제 더 부탁할 일은 없군그래. 이 결정만 있으면 내 힘으로 얼마든지 마법 물건을 제작할 수 있다네. 제일 처음 만드는 건 자네에게 주도록 하지. 자네는 고르기만 하면 되네.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n혹한의 쐐기신비의 수정 목걸이화염 루비\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8254] = {title = "세나리온 의회 지원", objective = "아즈샤라에서 오그틴크를 찾아야 합니다.", description = "하늘은 스스로 돕는 자를 돕는다고 하던가요... 방법은 중요하지 않아요. 이유가 더 중요한 법이지요.\n\n지금 세나리온 의회에서 도움의 손길을 절실하게 필요로 하고 있습니다. 오그틴크를 찾아가 보십시오. 아즈샤라의 엘다라스 폐허에서 북동쪽 있는 절벽 꼭대기로 가세요.", progress = nil, completion = "자네를 보니 나의 어깨가 좀 가벼워지는 느낌이로군. 할 일이 많다, &lt;name&gt;!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8255] = {title = "순록을 찾아서", objective = "건강한 순록의 분비샘 4개를 찾아 아즈샤라의 오그틴크에게 가져가야 합니다. 오그틴크는 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있습니다.", description = "아즈샤라에 사는 덩치큰 이끼발굽순록은 한때 악령의 숲에서 살았었지. 그 고결한 짐승은 선천적으로 질병이나 독에 대한 저항력이 강해서 그곳의 오염에도 영향 받지 않았지. 하지만 선조에게 대대로 물려 받은 분별력을 가지고 있던 이 짐승들은 오염된 그 지역을 떠나기로 선택했다네.\n\n슬픈 일이지만 부탁하네. 그 짐승들에게서 건강한 순록의 분비샘을 4개만 구해 오게. 악령의 숲을 치유하는 데 쓸 회복의 비약을 만들 거니까.", progress = "돌아왔군. 그래, 성공했나?", completion = "신께서 &lt;name&gt;, 자네를 우리에게 인도하셨군. 그러한 믿음과 결의가 있기에 우리도 비약을 제조할 수 있지...\n\n자네도 짐작하겠지만, 순록은 세나리온 의회에 있어 신성한 동물이야. 어떠한 이유에서든지... 그 동물을 죽이면 영혼의 힘은 약해지지. 아무리 반드시 누군가는 해야 하는 일이라 해도!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8256] = {title = "불사의 영액", objective = "아즈샤라의 오그틴크에게 불사의 영액을 가져다주어야 합니다. 오그틴크는 엘다라스 폐허 북동쪽 절벽 꼭대기에 있습니다.", description = "비약을 만드는 제조법은 아주 간단해. 독극물 하나에 회복제 둘! 회복제 하나는 이미 구했으니 이제 독극물을 찾아야 해.\n\n엘다라스 폐허를 떠돌고 있는 명가의 악령 중에는 종종 녹색 점액질로 융합된 악의 기운을 품고 있는 놈들이 있지. 아마 세상 사람들은 그걸 불사의 영액이라고 부른다지.\n\n그 사악한 물질은 효력이 대단하다네. 자, 내게 불사의 영액을 딱 하나만 가져오게.", progress = "어서 불사의 영액을 손에 넣어야 해. 찾았나?", completion = "이런 사악한 물질에 손을 대야 한다는 게 그리 기쁜 일이라고는 할 수 없지만, 이건 필요악이지. 고맙네, &lt;name&gt;!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8257] = {title = "몰파즈의 피", objective = "아탈학카르 신전에서 몰파즈를 처치하고 그의 피를 악령의 숲에 있는 그레타 모스후프에게 가져다주어야 합니다. 가라앉은 신전의 입구는 슬픔의 늪에 있습니다.", description = "이제 마지막 단계로 두 번째 회복제가 필요해.\n\n몰파즈라고 하는 녹색 비룡은 모든 독과 질병에 면역성을 지닌 것으로 알려져 있네. 이 정보를 우리에게 전하려 했던 수많은 드루이드들이 목숨을 잃었지. 난 몰파즈의 피가 꼭 필요해.\n\n자네가 그 마지막 재료를 구하는 동안 나는 미리 모아 둔 재료를 급사편으로 세나리온 의회에 보내겠어. 동료를 모아 가라앉은 아탈학카르 신전으로 가서 이 비룡의 은신처를 찾게. 몰파즈를 처치하여 피를 얻은 후 그 피를 가지고 악령의 숲에 있는 그레타 모스후프에게 돌아가게나.", progress = "몰파즈의 피를 가져왔나요?", completion = "몰파즈를 처치하고 그 피를 가져다주다니... 정말 믿을 수 없을 만큼 기쁘군요!\n\n당장 재료를 조합해서 악령의 숲에 있는 나무와 짐승들을 치료해야겠어요. 여기서 벌어진 참상을 완전히 회복하려면 제 평생이 걸릴 수도 있겠지만 당신이 제게 힘을 주시니 최선을 다하겠습니다, &lt;name&gt;.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n축복받은 기원의 묵주재앙의 마법봉희망의 고리\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n야생의 징표\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8258] = {title = "다크리버의 위협", objective = "스칼로맨스 대형 납골당 지하실 가운데에 예언의 탐지기를 놓으십시오. 그러면 영혼들이 나타날 것입니다. 모두 물리치면 죽음의 기사 다크리버가 나타납니다. 그를 쓰러뜨리십시오.\n\n오그리마 지혜의 골짜기에 있는 사고른 크레스트스트라이더에게 다크리버가 죽었다는 증거로 그의 머리카락을 가져가야 합니다.", description = "스칼로맨스 대형 납골당의 통치자는 죽음의 기사 다크리버요. 영혼의 세계를 뒤틀어 마음대로 부리려는 그 자를 막아야 하오! 드디어 당신 도움으로 만든 그 탐지기를 사용할 때가 온 거요.\n\n대형 납골당에 있는 지하실 가운데에 예언의 탐지기를 놓아서 다크리버의 부하들을 불러내시오. 그 유령들을 모두 처치하면 죽음의 기사가 몸소 나타나겠지. <name>, 그를 쓰러뜨려야만 영혼의 세계에 가해진 피해를 복구할 수 있소!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n성난하늘 투구"},
[8262] = {title = "고급 아라소르 구급품", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n고급 아라소르 구급품"},
[8265] = {title = "고급 파멸단 구급품", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n고급 파멸단 구급품"},
