[8381] = {title = "전쟁 장비", objective = "거대한 전쟁이... 알 수 없는 공포의 존재와의 전쟁이 다가오고 있어요. 부탁 드린 일을 모두 해내셨으니 보상을 드리도록 하죠.\n\n만약... 이 예언이 사실이라면...\n\n<얼굴이 창백해지는 지질학자 락스베인>\n\n우리 모두의 운명은 끝이 나겠죠.\n\n이 장비는 사막에서 당신의 전투에 꼭 필요할 것입니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 보충병 바지미늘벌레 가죽 장갑"},
