[8383] = {title = "잊지 말자, 알터랙 계곡!", objective = "알터랙 계곡 전장에서 전투가 치열하게 진행되고 있네! 자네는 자신의 역할을 다했는가?", description = nil, progress = "알터랙 계곡 전장에서 전투가 치열하게 진행되고 있네! 자네는 자신의 역할을 다했는가?", completion = "자네 덕분에 얼라이언스의 영광을 지킬 수 있었네. 계속 밀어붙이면 머지않아 호드를 섬멸할 수 있을 것이네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +398"},
[8385] = {title = "공동의 노력", objective = "이보게, 자네의 경험을 좀 빌릴 수 없겠나? 다른 전장에서 싸우고 있는 우리 동료들이 자네처럼 풍부한 경험을 가진 전문가를 손꼽아 기다리고 있네.", description = nil, progress = "이보게, 자네의 경험을 좀 빌릴 수 없겠나? 다른 전장에서 싸우고 있는 우리 동료들이 자네처럼 풍부한 경험을 가진 전문가를 손꼽아 기다리고 있네.", completion = "과연 명불허전이군. 자네와 같은 전사들이 없었다면 얼라이언스는 야만스러운 호드의 군대에게 무릎을 꿇었을 것이네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +2388"},
[8387] = {title = "알터랙 계곡의 침략자", objective = "알터랙 계곡에서는 아직도 치열한 전투가 벌어지고 있소! 다시 알터랙 계곡으로 돌아가 우리 서리늑대부족의 영토에서 침략자들을 몰아내시오!", description = nil, progress = "알터랙 계곡에서는 아직도 치열한 전투가 벌어지고 있소! 다시 알터랙 계곡으로 돌아가 우리 서리늑대부족의 영토에서 침략자들을 몰아내시오!", completion = "잘했소! 당신은 위대한 용사요. 겁도 없이 알터랙 계곡을 침략한 얼라이언스를 반드시 몰아내야 하오!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +398"},
[8388] = {title = "커다란 영광을 위하여", objective = "호드의 많은 용맹스러운 투사들이 당신을 우러러보고 있소. <name>, 얼라이언스와의 전투에서 계속 좋은 본보기가 되어 주시오. 혹시 새로운 소식이라도 가지고 온 거요?", description = nil, progress = "호드의 많은 용맹스러운 투사들이 당신을 우러러보고 있소. <name>, 얼라이언스와의 전투에서 계속 좋은 본보기가 되어 주시오. 혹시 새로운 소식이라도 가지고 온 거요?", completion = "여전히 강인한 모습을 보여주다니 무척 든든하군. 호드의 영광을 위하여 계속 나아가주시오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +2388\n\n다음과 같은 것들을 받습니다:\n\n"},
