[8396] = {title = "아라시 분지 공격", objective = "전장 밖에 있는 얼라이언스 준장에게 아라시 분지 명예 훈장 3개를 가져가야 합니다.", description = "전쟁에서 승리하는 것은 단순히 적을 무찌르는 것 이상의 의미가 있네. 승리는 적보다 많은 물자 확보라는 결과로 이어지는 경우가 많지.\n\n아라시 분지에는 상당한 규모의 자원이 있네. 어디든 먼저 움직이는 쪽이 차지할 수 있지.\n\n우리 얼라이언스가 승리하면 더 많은 무기를 제작하여 보급할 수 있다네. 호드가 이기면 우리의 심장을 겨눌 무기를 적의 손에 들려주는 꼴이 되는 거야!", progress = "전선에서 새로운 소식은 없나?", completion = "잘했네! 호드를 오그리마로 쫓아낼 때까지 이대로 계속 밀어붙이게나.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +398\n\n다음과 같은 것들을 받습니다:\n\n"},
[8398] = {title = "아라시 분지 공격", objective = "호드와의 오랜 전쟁으로 인해 물자가 급속도로 바닥나고 있네. 지속적인 자원 공급을 위해서는 아라시 분지를 우리 손에 넣는 것이 매우 중요하네! 얼라이언스를 위하여 아라시 분지에는 다녀온 건가?", description = nil, progress = "호드와의 오랜 전쟁으로 인해 물자가 급속도로 바닥나고 있네. 지속적인 자원 공급을 위해서는 아라시 분지를 우리 손에 넣는 것이 매우 중요하네! 얼라이언스를 위하여 아라시 분지에는 다녀온 건가?", completion = "정말 대단해! 자네 같은 훌륭한 &lt;class&gt; 덕분에 우리 얼라이언스에 필요한 자원을 공급할 수 있는 것이지.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +398"},
[8399] = {title = "전쟁노래 협곡 전투", objective = "전장 밖에 있는 얼라이언스 준장에게 전쟁노래 협곡 명예 훈장 3개를 가져가야 합니다.", description = "오크들이 숲을 파괴하는 것을 막기 위해 지금 은빛날개 파수대가 전쟁노래 정찰대와 교전 중에 있네. 은빛날개 파수대가 특별히 이 숲을 지키려는 이유는 그들이 자연을 사랑하기 때문만은 아니라네.\n\n이 숲은 대규모 공격으로부터 잿빛 골짜기를 방어할 수 있게 해 주는 전략적 장벽을 이루고 있네. 이 숲이 없다면 아스트라나르는 하루나 이틀 안에 불모의 땅으로 병합되게 될 수밖에 없네.\n\n전쟁노래 정찰대와의 전투에 참여해 최선을 다해 주게! 얼라이언스를 위해!", progress = "전선에서 새로운 소식이라도 가져왔나?", completion = "훌륭하네. 자네 덕분에 잿빛 골짜기에 있는 자연의 보호막은 당분간 안전할 것이네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +82\n\n다음과 같은 것들을 받습니다:\n\n"},
[8400] = {title = "전쟁노래 협곡 전투", objective = "전장 밖에 있는 얼라이언스 준장에게 전쟁노래 협곡 명예 훈장 3개를 가져가야 합니다.", description = "오크들이 숲을 파괴하는 것을 막기 위해 지금 은빛날개 파수대가 전쟁노래 정찰대와 교전 중에 있네. 은빛날개 파수대가 특별히 이 숲을 지키려는 이유는 그들이 자연을 사랑하기 때문만은 아니라네.\n\n이 숲은 대규모 공격으로부터 잿빛 골짜기를 방어할 수 있게 해 주는 전략적 장벽을 이루고 있네. 이 숲이 없다면 아스트라나르는 하루나 이틀 안에 불모의 땅으로 병합되게 될 수밖에 없네.\n\n전쟁노래 정찰대와의 전투에 참여해 최선을 다해 주게! 얼라이언스를 위해!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +138\n\n다음과 같은 것들을 받습니다:\n\n"},
