[8408] = {title = "전쟁노래 협곡 전투", objective = "전쟁노래 협곡에서 벌어지고 있는 전투는 단지 숲을 보호하기 위한 것만이 아니라 잿빛 골짜기와 불모의 땅 사이에 형성된 자연의 보호막을 지키기 위함이라는 것을 잊지 말게. 협곡에서 가지고 온 새로운 소식이라도 있나?", description = nil, progress = "전쟁노래 협곡에서 벌어지고 있는 전투는 단지 숲을 보호하기 위한 것만이 아니라 잿빛 골짜기와 불모의 땅 사이에 형성된 자연의 보호막을 지키기 위함이라는 것을 잊지 말게. 협곡에서 가지고 온 새로운 소식이라도 있나?", completion = "훌륭하네. 자네 덕분에 잿빛 골짜기에 있는 자연의 보호막은 당분간 안전할 것이네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +398"},
[8409] = {title = "엉망이 된 양조통", objective = "티리스팔 숲의 밀짚인형 축제에 있는 암흑의 소환사 얀카에게 돌아가야 합니다.", description = "썩은 달걀을 양조통 안에 제대로 넣었습니다. 앞으로 사우스쇼어 여관에서 만드는 맥주는 엉망이 될 것입니다!\n\n티리스팔 숲의 밀짚인형 축제에 있는 암흑의 소환사 얀카에게 가서 이 소식을 전하는 게 좋겠습니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n할로윈 축제 호박"},
[8410] = {title = "원소에 대한 깨달음", objective = "물, 불, 대지, 바람의 샘플을 수집하여 바람의감시자 바스라에게 가져가야 합니다.", description = "바람의감시자 바스라가 지혜로운 주술사를 찾고 있다는 전갈이 왔소. 그런데 원소들을 모아 가져가야 대화상대로 인정하겠다는군.\n\n타렌 밀농장 동쪽에 있는 강을 따라 북쪽으로 올라가다 보면 바스라를 찾을 수 있을 거요. 폐허가 나올 때까지 강을 거슬러 올라가야 하오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8411] = {title = "원소에 대한 깨달음", objective = "바람의감시자 바스라에게 바람, 불, 대지, 물의 원소를 가져가야 합니다.", description = "어서 오게. 일단 원소들을 가져오면 얘기를 시작하지.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8412] = {title = "정기의 토템", objective = "바람의감시자 바스라에게 정기의 토템을 만드는데 필요한 재료들을 가져가야 합니다.", description = "이제 이곳 정령들은 날 좋아하지 않아.\n\n날 보호해 줄 정기의 토템이 필요해. 자네 물론 토템이 뭔진 잘 알겠지? 정기의 토템을 만들 원소는 충분한데 재료가 좀 부족해. 자연에 가깝고 좀 원시적인 재료일세.\n\n서부 역병지대로 가서 곰과 거미를 죽이면 각각 발톱과 눈을 얻을 수 있네. 그리고 독수리란 놈들은 뭐든지 먹고 사니까 둘 중 뭐든지 나올 거야.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8413] = {title = "부두교 마법", objective = "바람의감시자 바스라에게 부두 깃털들을 가져가야 합니다.", description = "정기의 토템이 아직 완성되지 않았네. 제대로 작동하려면 부두교 마법이 필요해.\n\n가라앉은 사원의 트롤들이 지니고 다니는 깃털에는 강력한 부두교 마력이 들어있네. 그리로 가서 게이셔, 줄로, 마이잔, 후쿠, 졸로, 로로를 해치워. 그러면 정기의 토템에 넣을 마력을 충분히 모을 수 있을 거야.", progress = "깃털은 어디 있나?", completion = "이제 발 뻗고 편하게 잘 수 있겠군! 정기의 토템이 지켜줄 테니까!\n\n자, 여기 내가 오랜 세월 공들여 모은 소장품일세. 아무래도 자네에게 필요할 것 같군. 한 번 골라보겠나?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아주라이트 장갑사로잡힌 물의 정령광야의 지팡이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8414] = {title = "악마 퇴치", objective = "서부 역병지대에 있는 대사제 텔다니스에게 앞잡이의 스컬지석 20개를 모아 가져가야 합니다.", description = "반갑소, <class>|1이여;여;. 이렇게 음울한 곳에서 당신 같이 빛의 힘을 행하는 자는 언제든지 환영이라오.\n\n당신의 신성한 힘으로 이곳으로 끊임없이 몰려오는 언데드와 싸울 수 있도록 도와주시오. 그리고 스컬지석을 최대한 많이 모아서 대사제이신 텔다니스님께 가져다주시오. 텔다니스 대사제님께서는 여기서 그리 멀지 않은 슬픔의 언덕에서 우서 경의 무덤을 지키고 계시다오.\n\n은빛 여명회 위임봉이 있어야만 스컬지석을 찾을 수 있으니 은빛 여명회 위임봉을 가지고 있지 않다면 저쪽에 있는 은빛장교 퓨어하트와 얘기해 보시오.", progress = "내게 어떤 악의 세력의 물건을 가져온 것이오?", completion = "스컬지석은 아주 먼 거리에 있는 언데드까지 불러들이기 때문에 스컬지석에서 악마를 퇴치하는 일은 매우 위험하오. 하지만 그대는 신의 가호를 받는 분, 그대를 믿도록 하겠소...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8415] = {title = "서리바람 거점으로", objective = "서리바람 거점에 있는 사령관 아쉬람 발러피스트와 대화해야 합니다.", description = "사령관 아쉬람 발러피스트가 청정함과 용맹을 지닌 성기사가 필요하다고 요청해 왔소. 서부 역병지대의 남쪽에 있는 서리바람 거점으로 가면 그를 찾을 수 있을 것이오. 그를 찾아서 빛을 수호할 수 있도록 도와주시오!", progress = nil, completion = "좋소! 실력이 어느 정도인지 좀 봅시다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8416] = {title = "마력을 잃은 스컬지석", objective = "서리바람 거점에 있는 사령관 아쉬람 발러피스트에게 마력을 잃은 스컬지석을 가져가야 합니다.", description = "그대가 가져온 스컬지석에서 악마가 깨끗이 정화되었소.\n\n난 사령관인 아쉬람의 계획을 알고 있소이다. 그에게는 단 하나의 마력을 잃은 스컬지석이 반드시 필요할 겁니다. 스컬지를 물리칠 수 있도록 사령관 아쉬람에게 스컬지석을 가져다주시오.", progress = "텔다니스님께서 스컬지석의 마력을 없앨 수 있었소?", completion = "당신은 내가 부탁한 일을 아무 말 없이 들어주었소.\n\n당신은 신뢰할 만한 인물인 것 같으니 이제 우리 계획을 자세히 알려 주겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8417] = {title = "영혼이 된 영웅의 고통", objective = "저주받은 땅의 입구에 있는 호드 영웅의 넋과 대화해야 합니다.", description = "저주받은 땅에 가면 한때 호드의 위대한 영웅이었던 영혼이 있는데 문제가 있는 것 같소. 비록 그의 육체는 죽었지만 전사의 명예는 영원할 것이오. 그와 대화해보고 무슨 일인지 알아내 그를 돕도록 하시오.", progress = nil, completion = "그래서 내 고통을 덜어주러 왔다는 거요? 그게 간단한 방법이었으면 좋겠군. 날 소멸시키는 것처럼...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8418] = {title = "퇴마석 만들기", objective = "아쉬람 발러피스트에게 황색 부두 깃털, 청색 부두 깃털, 녹색 부두 깃털을 각 2개씩 가져가야 합니다.", description = "이제 우리는 언데드의 군대를 박살낼 수 있는 어떤 무기와 마력을 잃은 스컬지석을 결합해야만 하오. 가라앉은 신전에 있는 트롤들만이 그 자체에 대항해 무언가의 악마를 바꿀 수 있는 진귀한 마법과 같은 것을 지니고 있지.\n\n신전안에 트롤들은 게이셔, 마이잔, 졸로, 후쿠, 줄로 그리고 로로로 알려져 있소. 그들의 타락한 영혼을 없애는 것에 가책을 느끼지 마시오... 그들은 악의 영혼이오.", progress = "사악한 트롤들을 해치웠소?", completion = "대단하군. 놀랍지 않을 수 없소이다만 당신이 우리를 실망시킬 것이라고 의심하지 않았소이다.\n\n신성한 퇴마석을 당신에게 주게 되어 영광이오. 잘 사용하시기 바라오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n빛의 검축성의 보주기사단 인장\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n신성한 퇴마석"},
[8419] = {title = "임프의 부탁", objective = "악령의 숲에 있는 임프시에게 지옥 옷감을 한 장 가져가야 합니다.", description = "악령의 숲에 사는 임프시라는 임프가 당신에게 부탁이 있답니다. 좀 수상하긴 하지만 어쨌든 \"신뢰 관계\"의 증표로 지옥 옷감을 한 장 가져오라더군요. 흑마법사로서 당신의 능력을 보아하니, 악령의 숲에서 지옥 옷감을 갖고 다니는 사티로스에 대해서 잘 알고 있을 것 같군요.\n\n피멍울 폭포 바로 위쪽에서 임프시를 찾을 수 있을 겁니다. 그곳은 매년 이맘 때쯤이면 무척이나 아름다운 경치를 뽐내지요.", progress = "지옥 옷감은 가지고 왔나요?", completion = "정말 멋진 &lt;class&gt;님!\n\n\n\n아, 이 느낌 너무 좋아. 살갗을 천천히 태우고 마음속의 악마를 끄집어내는 듯한 느낌...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8420] = {title = "뜨거운 소유욕", objective = "악령의 숲에 있는 임프시에게 지옥 옷감을 한 장 가져가야 합니다.", description = "임프가 이런 말을 한다고 이상하게 생각하실지 모르지만 전 애완 동물이 갖고 싶어요. 정말로! 저 나이비에게는 제가 있는데 전 아무것도 없잖아요. 정말 불공평해요!\n\n꼭 살아있는 생명체가 아니라도 상관없어요. 지옥 옷감으로 직접 만들면 되니까요. 이곳 악령의 숲에 있는 사티로스들에게서 종종 지옥 옷감을 발견할 수 있지요. 놈들을 처치하다 보면 분명 발견할 수 있을 거예요. 어때요, 그리 어려운 일은 아니죠?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8421] = {title = "인형 재료", objective = "악령의 숲에 있는 임프시에게 썩은 나무 10개와 피멍울 정수 4개를 가져가야 합니다.", description = "이제 지옥 옷감이 있으니 *나만의* 인형을 만들 수 있게 되었어요.\n\n그런데 눈을 만들려면 다른 재료가 필요해요. 예쁜 눈을 만들 수 있게 강철나무를 가져다 주세요. 북쪽에 있는 강철나무 숲으로 가세요.\n\n참, 그리고 악마의 기운을 심어야 하니까 피멍울 정수도 있어야 돼요. 부패한 수액괴물이 그 정수를 가지고 있는데 보시다시피 저랑 나이비가 있는 바로 이곳 근처에서 찾을 수 있지요.", progress = "재료는 가지고 왔나요?", completion = "아주 질이 좋은 재료로군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8422] = {title = "트롤의 깃털", objective = "가라앉은 사원에 있는 트롤의 부두 깃털 6개를 가져가야 합니다.", description = "인형이 거의 완성됐어요. 이제 속을 채울 재료만 있으면 돼요.\n\n가라앉은 사원에 있는 트롤들에게 나오는 부두 깃털이 제일로 좋지요. 게이셔, 마이잔, 졸로, 후쿠, 줄로, 로로라는 트롤들을 모두 해치워 주세요.\n\n쉬운 일은 아닐 줄은 저도 아니까 그 답례로 나이비의 소장품 중에서 하나를 드리겠어요. 나이비에게는 더 이상 필요 없을 거예요.", progress = "깃털은 가지고 왔나요? 인형 뱃속이 텅텅 비었어요!", completion = "좋아요! 이제 인형을 완성할 수 있겠어요!\n\n&lt;재빨리 인형 속을 깃털로 채우고 악마의 기운을 불어넣는 임프시&gt;\n\n어라, 이 부두 깃털에는 이상한 부작용이 있네?!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n영혼 수확기나락의 조각예속의 로브\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8423] = {title = "전사의 일족", objective = "저주받은 땅에 있는 지옥멧돼지 7마리를 처치하고 호드 영웅의 넋에게 돌아가야 합니다.", description = "<위아래로 훑어보는 호드 영웅>\n\n당신은 <class>|1이;가; 확실하군. 당신에게 명예로운 일을 맡기려 하오. 그러나 당신의 실력을 확인해 봐야 하오.\n\n렉사르가 단 한칼의 재빠른 공격으로 지옥멧돼지를 죽여서 그의 검술의 날카로움을 확인했다고 하더군. 이제 지옷멧돼지를 죽여 당신의 실력을 확인해 보고자 하니 지옥멧돼지를 죽이고 돌아오시오.", progress = nil, completion = "증거는 필요 없소. 난 당신의 말 속에 담긴 진실을 읽을 수 있소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8424] = {title = "어둠의혈맹과의 전쟁", objective = "저주받은 땅에서 어둠의혈맹 숙련사제, 이교도, 암살단원을 각 20명씩 해치우고 호드 영웅의 넋에게 돌아가야 합니다.", description = "저주받은 땅에 연속된 어둠의혈맹의 출현은 나에게 큰 고통을 안겨 주고 있소. 그들의 어둠의 의식과 마법이 살아생전 내가 느꼈던 그 어떤 것과도 다른 고통이 되고 있소이다.\n\n난 당신을 통해 고통의 메시지를 전할 수 있으리라 생각하오. 녀석들에게 가서 내 분노를 그대로 전하시오.", progress = nil, completion = "당신은 이미 내 고통을 가라앉혀 주었소. 경의를 표하는 바이며 감사하게 생각하오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8425] = {title = "부두 깃털", objective = "호드 영웅의 넋에게 가라앉은 사원에 있는 트롤들에게서 황색 부두 깃털, 청색 부두 깃털, 녹색 부두 깃털을 빼앗아 각 2개씩 가져가야 합니다.", description = "당신 덕분에 안식을 취할 수 있게 되었소. 당신은 보상을 받아야 할 자격이 충분하오.\n\n살아생전 내가 사용하던 무기와 갑옷은 최고라고 자부하오. 나에게는 더 이상 쓸모가 없으니 당신이 사용하는 것이 좋겠소.\n\n슬픔의 늪에 있는 가라앉은 사원으로 가서 트롤 수호자인 게이셔, 마이잔, 졸로, 후쿠, 줄로, 로로를 해치우시오. 그들이 가지고 있는 마법의 깃털을 사용하면 잠시 동안 내 육체를 만들어 내 무기와 갑옷을 당신에게 건넬 수 있는 시간을 벌 수 있소.", progress = "당신에게는 긴 시간도 영혼이 된 나에게는 한순간에 불과할 수 있겠지만... 그래도 너무 일찍 온 것 아니오?", completion = "비록 잠깐이지만 차가운 금속의 느낌을 다시 느낄 수가 있다니...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n맹위의 면갑다이아몬드 물통서슬강철 어깨보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8426] = {title = "전쟁노래 협곡 전투", objective = "전장 밖에 있는 호드 돌격대장에게 전쟁노래 협곡 명예 훈장 3개를 가져가야 합니다.", description = "전쟁노래 협곡에서 벌어지는 은빛날개 파수대와의 전투는 대단히 중요하오. 얼라이언스는 자기들 소유도 아닌 숲을 보호한다는 구실로 우리 호드 최대의 목재 공급원을 빼앗고 오히려 본래 주인인 우리를 쫓아내려 하고 있소.\n\n절대로 내버려둬서는 안 되오! 당신이 위대한 호드의 용사라는 증거를 가지고 내게 돌아오시오!", progress = "전쟁노래 협곡에서 뭐 새로운 소식이라도 가져왔소?", completion = "훌륭하오! 당신은 전쟁노래 협곡에서 우리 호드의 전선을 방어하여 자신의 가치를 충분히 증명해 보였소! 그 명성이 호드의 영토 전역에 널리 퍼질 거요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +82\n\n다음과 같은 것들을 받습니다:\n\n"},
[8427] = {title = "전쟁노래 협곡 전투", objective = "전장 밖에 있는 호드 돌격대장에게 전쟁노래 협곡 명예 훈장 3개를 가져가야 합니다.", description = "전쟁노래 협곡에서 벌어지는 은빛날개 파수대와의 전투는 대단히 중요하오. 얼라이언스는 자기들 소유도 아닌 숲을 보호한다는 구실로 우리 호드 최대의 목재 공급원을 빼앗고 오히려 본래 주인인 우리를 쫓아내려 하고 있소.\n\n절대로 내버려둬서는 안 되오! 당신이 위대한 호드의 용사라는 증거를 가지고 내게 돌아오시오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +138\n\n다음과 같은 것들을 받습니다:\n\n"},
