[8431] = {title = "전쟁노래 협곡 전투", objective = "전쟁노래 협곡에서는 아직도 치열한 전투가 벌어지고 있소. 와인<class>, 최선을 다해 우리 땅에서 은빛날개 파수대를 몰아내 주시오!", description = nil, progress = "전쟁노래 협곡에서는 아직도 치열한 전투가 벌어지고 있소. 와인<class>, 최선을 다해 우리 땅에서 은빛날개 파수대를 몰아내 주시오!", completion = "훌륭하오! &lt;class&gt;|1이여;여;, 당신 덕분에 호드는 전쟁노래 협곡에 대한 통치권을 굳건히 할 수 있었소!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +82"},
