[8435] = {title = "전쟁노래 협곡 전투", objective = "전쟁노래 협곡에서는 아직도 치열한 전투가 벌어지고 있소. <name>, 최선을 다해 우리 땅에서 은빛날개 파수대를 몰아내 주시오!", description = nil, progress = "전쟁노래 협곡에서는 아직도 치열한 전투가 벌어지고 있소. <name>, 최선을 다해 우리 땅에서 은빛날개 파수대를 몰아내 주시오!", completion = "훌륭하오! &lt;class&gt;|1이여;여;, 당신 덕분에 호드는 전쟁노래 협곡에 대한 통치권을 굳건히 할 수 있게 되었소!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +398"},
[8436] = {title = "아라시 분지 정복", objective = "전장 밖에 있는 호드 돌격대장에게 아라시 분지 명예 훈장 3개를 가져가야 합니다.", description = "얼라이언스와의 충돌이 이제 전면전으로 발전했소. 어느 쪽도 더는 거짓 구실을 대서 전쟁을 도발하거나 상대편에서 싸움을 걸어오기만을 기다릴 필요는 없지.\n\n아라시 분지 전투의 목적은 단순하고 분명하오. 바로 자원 쟁탈전이지! 얼라이언스 놈들이 자원을 차지해서 우리를 공격하는 데 쓰기 전에 우리가 먼저 자원을 전쟁 물자로 공급해야 하오. 자원을 원활하게 보급할 수 있도록 우리 포세이큰 파멸단에 힘을 보태주시오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +138\n\n다음과 같은 것들을 받습니다:\n\n"},
[8437] = {title = "아라시 분지 정복", objective = "전장 밖에 있는 호드 돌격대장에게 아라시 분지 명예 훈장 3개를 가져가야 합니다.", description = "얼라이언스와의 충돌이 이제 전면전으로 발전했소. 어느 쪽도 더는 거짓 구실을 대서 전쟁을 도발하거나 상대편에서 싸움을 걸어오기만을 기다릴 필요는 없지.\n\n아라시 분지 전투의 목적은 단순하고 분명하오. 바로 자원 쟁탈전이지! 얼라이언스 놈들이 자원을 차지해서 우리를 공격하는 데 쓰기 전에 우리가 먼저 자원을 전쟁 물자로 공급해야 하오. 자원을 원활하게 보급할 수 있도록 우리 포세이큰 파멸단에 힘을 보태주시오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +228\n\n다음과 같은 것들을 받습니다:\n\n"},
[8438] = {title = "아라시 분지 정복", objective = "전장 밖에 있는 호드 돌격대장에게 아라시 분지 명예 훈장 3개를 가져가야 합니다.", description = "얼라이언스와의 충돌이 이제 전면전으로 발전했소. 어느 쪽도 더는 거짓 구실을 대서 전쟁을 도발하거나 상대편에서 싸움을 걸어오기만을 기다릴 필요는 없지.\n\n아라시 분지 전투의 목적은 단순하고 분명하오. 바로 자원 쟁탈전이지! 얼라이언스 놈들이 자원을 차지해서 우리를 공격하는 데 쓰기 전에 우리가 먼저 자원을 전쟁 물자로 공급해야 하오. 자원을 원활하게 보급할 수 있도록 우리 포세이큰 파멸단에 힘을 보태주시오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +378\n\n다음과 같은 것들을 받습니다:\n\n"},
[8439] = {title = "아라시 분지 정복", objective = "전장 밖에 있는 호드 돌격대장에게 아라시 분지 명예 훈장 3개를 가져가야 합니다.", description = "얼라이언스와의 충돌이 이제 전면전으로 발전했소. 어느 쪽도 더는 거짓 구실을 대서 전쟁을 도발하거나 상대편에서 싸움을 걸어오기만을 기다릴 필요는 없지.\n\n아라시 분지 전투의 목적은 단순하고 분명하오. 바로 자원 쟁탈전이지! 얼라이언스 놈들이 자원을 차지해서 우리를 공격하는 데 쓰기 전에 우리가 먼저 자원을 전쟁 물자로 공급해야 하오. 자원을 원활하게 보급할 수 있도록 우리 포세이큰 파멸단에 힘을 보태주시오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +398\n\n다음과 같은 것들을 받습니다:\n\n"},
[8442] = {title = "아라시 분지 정복", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +378"},
[8443] = {title = "아라시 분지 정복", objective = "얼라이언스 놈들과 전쟁을 치르려면 자원이 필요하오! 전투가 한창일 때 보급품 물량이 바닥나서는 절대 안 되오. 적에게 아라시 분지가 넘어가지 않도록 만전을 기하시오!", description = nil, progress = "얼라이언스 놈들과 전쟁을 치르려면 자원이 필요하오! 전투가 한창일 때 보급품 물량이 바닥나서는 절대 안 되오. 적에게 아라시 분지가 넘어가지 않도록 만전을 기하시오!", completion = "정말 대단하오! 아라시 분지가 우리 수중에 있는 한 보급품 걱정은 하지 않아도 될 거요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n명예 점수 +398"},
[8446] = {title = "악몽 속의 장막", objective = "악몽이 깃든 물건에 숨겨진 의미를 해석할 수 있는 이를 찾아야 합니다.\n\n강력한 힘을 가진 드루이드가 도움을 줄 수 있을 것입니다.", description = "이 물건 때문에 세상이 오염되는 것입니다.\n\n이 물건과 에메랄드의 꿈에서 나타난 4마리 용 사이에 어떤 관련이 있는 것 같습니다. 이 물건의 숨겨진 용도를 알 수 있는 인물을 찾아야만 합니다. 달숲이나 세나리온 요새에 있는 드루이드가 도움을 줄 수 있을 것입니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8447] = {title = "깨어나는 전설", objective = "달숲에 있는 수호자 레물로스가 악몽이 깃든 물건을 정화할 때까지 기다려야 합니다.", description = "엘룬아라 호수의 물이라면 이 물건과 관련된 악몽을 정화할 수 있을 것이다. 잠시만 기다리도록 해라.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n말퓨리온의 인장 반지"},
[8460] = {title = "나무구렁일족", objective = "그라즐이 자기 일족의 친구임을 입증하려면 마른가지일족 전사, 길잡이, 정원사를 각각 6마리씩 처치해달라고 부탁했습니다. 임무를 마치면 악령의 숲 남쪽, 에메랄드 성소 근처에 있는 그라즐에게 돌아가십시오.", description = "나무구렁일족은 유일하게 타락을 피해 간 펄볼그 부족이오. 하지만 많은 종족들은 적인지 친구인지 알아보려 하지도 않고 맹목적으로 펄볼그를 죽이고 있소. 상황이 이러하니 나무구렁일족은 남을 잘 믿지 않소.\n\n당신이 우리의 친구임을 증명하고 싶다면 악령의 숲에서 타락한 마른가지일족을 몰아내 주시오. 그러면 언젠가 당신을 동료로 인정하겠소. 서쪽으로 가면 마른가지일족의 전사, 길잡이, 정원사를 찾을 수 있을 거요.", progress = nil, completion = "우리는 과거에 일어났던 사건 때문에 너무나 많은 고통을 겪고 있소. 우리 나무구렁일족을 위해 힘써줘서 고맙소이다. 자, 보잘것없지만 점차 돈독해지는 우리 우정을 위한 선물이외다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n대지수호자의 조끼동굴보초의 허리띠\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8461] = {title = "북방의 마른가지일족", objective = "나피엔이 마른가지일족 보초, 복수자, 주술사를 각각 6마리씩 처치해 달라고 부탁했습니다. 일을 마치면 악령의 숲 북쪽, 나무구렁 요새 입구 근처에 있는 나피엔에게 돌아가십시오.", description = "여기서 곧장 남서쪽으로 가면 마른가지일족 펄볼그들의 야영지가 있소. 지금 사악한 기운이 야영지까지 침투했는데, 문제가 되기 전에 그들을 끝장내 버리고 싶소.\n\n마른가지일족이 사악하긴 해도 악마의 영향을 받아 영혼이 타락한 것뿐이오. 본성이 사나운 것은 아니지만 나도 이제 어찌할 도리가 없소. 동족과 싸워야 한다는 사실이 너무나 슬프기만 하지만...\n\n부디 이 일을 맡아주시오, <name>. 그리고 돌아오면 자세한 얘기는 들려주지 않아도 되오. 내 가슴만 무너질 테니까...", progress = nil, completion = "당신 눈에서 승리의 기쁨이 느껴지는군. 승리라... 동족을 해치운 것도 승리라고 할 수 있을지... 어쨌든, 당신은 신뢰해도 괜찮을 것 같소.\n\n요새 안의 나무구렁일족이 당신을 적대시하지 않고 환영하기까지는 시간이 조금 걸릴 거요. 형제들이 당신에 대한 의심을 지울 때까지 조금만 참으시오. 우리를 배신하거나 공격하지 않는 이상 좋은 친구가 될 수 있을 테니까.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n우르사의 다리보호구길잡이의 투구\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8462] = {title = "나피엔과 대화하기", objective = "악령의 숲에 있는 큰 길을 따라 북쪽으로 가서 나피엔이라는 펄볼그와 대화하십시오. 나피엔은 나무구렁 요새 입구에서 보초를 서고 있습니다.", description = "당신이라면 우리 나무구렁일족을 위협하는 더욱 큰 문제도 충분히 처리할 수 있을 것이라 믿소. 그만한 능력이 있다는 것을 여기서 충분히 증명해 보였으니 말이오.\n\n이 길을 따라 북쪽으로 쭉 가면 나무구렁 요새 입구가 나오는데, 그곳에 나피엔이라고 하는 우리 일족 한 명이 보초를 서고 있소. 그의 모습이 다소 야만적이고 흉포한 짐승처럼 보이겠지만 겁낼 필요는 없소. 그는 우리 마을을 위협하는 악의 무리에 맞서 싸울 조력자를 찾고 있는 것뿐이니까.", progress = nil, completion = "음... 여러 이방인들이 우리 나무구렁일족 펄볼그와 친구가 되고 싶어 한다는 얘기는 들었소. 일단 환영하오. 하지만 우리 일족이 외지인들에게 그리 친절하지만은 않다는 사실은 알아두시오.\n\n특히 요즘은 몹시 어려운 시기라, 우리는 이 세계가 타락하는 것을 막기 위해 함께 싸울 수 있는 자들만 신뢰하고 있소. 따라서 모든 이방인은 우리의 친구임을 몸소 증명해야 하지. 그렇지 못한 자들이 이 요새로 들어간다면... 그때는 대가를 톡톡히 치르게 될 거요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8463] = {title = "불안정한 마나 수정", objective = "매날개 광장에 있는 앨돈 선브랜드에게 불안정한 마나 수정 6개를 가져가야 합니다.", description = "최근에 버림받은 자들이 우리 비전 성소 중 한 곳에서 불안정한 마나 수정을 훔쳐갔습니다. 그 수정들을 잘못 다루면 도시를 둘러싼 벽을 뚫을 만큼 강력한 폭발이 일어날 수도 있습니다.\n\n사실 녀석들이 불안정한 비전 마력의 원천에 손을 댔다가 죽는다고 해도 별로 신경이 쓰이지는 않습니다만, 전체적인 영향을 고려하면 바람직한 일은 아니죠.\n\n그들이 훔쳐 간 불안정한 마나 수정 중 남아 있는 것을 가지고 오십시오. 원래 수정을 보관하던 상자 안에 그대로 있을 겁니다.", progress = "벌써 도난당한 물건을 찾았습니까?", completion = "정말 훌륭하게 일을 마쳤군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8464] = {title = "눈사태일족의 동태", objective = "살파가 눈사태일족 주술사, 보초, 펄볼그를 각각 8마리씩 처치해달라고 부탁했습니다. 살파는 여명의 설원에 있는 나무구렁 요새의 입구 바로 밖에 있습니다.", description = "우리 나무구렁일족은 보통 남의 일에 잘 간섭하지 않소. 우리에게 신임을 얻은 자들은 무사 통과시켜 주고 다른 펄볼그 부족과의 마찰도 가능한 한 피하려 한다오.\n\n그런데, 최근 눈사태일족이 부쩍 공격적으로 변했소이다. 자신들이 이해하지 못하는 어떤 것에 대한 공포와 증오에 휩싸여 완전히 광분한 상태인 것 같소.\n\n당신이 그들의 수를 줄일 수 있다면 우리에겐 큰 도움이 될 거요. 여기서 동쪽으로 멀리 있는 눈사태일족 마을로 가서 그들을 찾아보시오.", progress = nil, completion = "비록 슬픈 일이기는 하지만 도움을 줘서 고맙소. 감사의 표시로 이것을 주고 싶소.\n\n우릴 계속해서 도와주시오. 도움을 청할 곳이 너무 부족하오. 당신의 도움 없이 우리 일족의 힘만으로는 당면한 위협을 해결하기가 너무 벅차다오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n대지수호자의 장갑길잡이의 장갑동굴보초의 조끼우르사의 은총\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8465] = {title = "살파와 대화하기", objective = "나무구렁 요새를 통과하여 여명의 설원으로 가서 나무구렁 요새 입구를 지키고 서 있는 살파와 대화하십시오.", description = "타락의 위협은 남쪽의 마른가지일족 펄볼그뿐만 아니라 동쪽의 여명의 설원에 있는 눈사태일족 펄볼그로부터도 다가오고 있소. 우리를 계속 도와줄 마음이 있다면 요새의 반대편에 있는 여명의 설원 입구에 있는 살파와 얘기해 보시오. 길을 따라 왼쪽으로 곧장 가면 될 거요.\n\n그곳에 있는 우리 일족이 당신에게 적대감을 느끼고 공격할 수도 있으니 주의하시오. 충돌을 피하면서 가능한 한 빨리 이동하시오. 아무리 정당방위라고 해도 나무구렁일족을 살해한다면 우리 관계는 멀어질 수밖에 없소.", progress = nil, completion = "&lt;class&gt;|1이여;여;, 만나서 반갑소. 나는 나무구렁일족의 전령이자 일족을 지키는 파수꾼으로 이곳 여명의 설원에서 보초를 서고 있소.\n\n이 혹한의 땅에 사는 우리 동족인 눈사태일족이 악령의 숲 펄볼그들과 마찬가지로 타락의 위기에 처해 있소. 우리 나무구렁일족 펄볼그를 도우러 온 것이라면 감사히 받아들이겠소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8466] = {title = "그라즐을 위한 깃털", objective = "나는 당신을 믿지만 의심 많은 우리 일족에게도 당신이 친구라는 것을 계속 증명해야 할 것이오. 그러려면 앞으로도 내 도움이 필요할 것이오.\n\n마른가지일족 펄볼그 중 일부는 독특한 깃털로 머리를 장식하고 다닌다오. 놈들의 수를 줄이고 그 증거로 그 머리장식을 가져오시오. 어떤 놈들을 처치하든지 깃털 머리장식을 구하는 대로 내게 가져다주시오. 5개를 가지고 올 때마다 나무구렁일족의 신뢰를 얻게 될 거요.", description = nil, progress = "나는 당신을 믿지만 의심 많은 우리 일족에게도 당신이 친구라는 것을 계속 증명해야 할 것이오. 그러려면 앞으로도 내 도움이 필요할 것이오.\n\n마른가지일족 펄볼그 중 일부는 독특한 깃털로 머리를 장식하고 다닌다오. 놈들의 수를 줄이고 그 증거로 그 머리장식을 가져오시오. 어떤 놈들을 처치하든지 깃털 머리장식을 구하는 대로 내게 가져다주시오. 5개를 가지고 올 때마다 나무구렁일족의 신뢰를 얻게 될 거요.", completion = "&lt;name&gt;, 잘했소! 우리 일족에게 당신의 공로를 꼭 알리겠소.\n\n깃털 머리장식을 발견하면 잊지 말고 내게 가져다주시오. 깃털이 더는 필요하지 않을 때까지...", rewards = nil},
[8467] = {title = "나피엔을 위한 깃털", objective = "나는 당신을 믿지만 의심 많은 우리 일족에게도 당신이 친구라는 것을 계속 증명해야 할 것이오. 그러려면 앞으로도 내 도움이 필요할 것이오.\n\n마른가지일족 펄볼그 중 일부는 독특한 깃털로 머리를 장식하고 다니고 있소. 놈들의 수를 줄이고 그 증거로 깃털 머리장식을 가져오시오. 어떤 놈들을 처치하든지 머리장식을 구하는 대로 내게 가져다주시오. 5개를 가지고 올 때마다 나무구렁일족의 신뢰를 얻게 될 것이오.", description = nil, progress = "나는 당신을 믿지만 의심 많은 우리 일족에게도 당신이 친구라는 것을 계속 증명해야 할 것이오. 그러려면 앞으로도 내 도움이 필요할 것이오.\n\n마른가지일족 펄볼그 중 일부는 독특한 깃털로 머리를 장식하고 다니고 있소. 놈들의 수를 줄이고 그 증거로 깃털 머리장식을 가져오시오. 어떤 놈들을 처치하든지 머리장식을 구하는 대로 내게 가져다주시오. 5개를 가지고 올 때마다 나무구렁일족의 신뢰를 얻게 될 것이오.", completion = "&lt;name&gt;, 잘했소! 우리 일족에게 당신의 공로를 꼭 알리겠소.\n\n깃털 머리장식을 발견하면 잊지 말고 내게 가져다주시오. 깃털이 더는 필요하지 않을 때까지...", rewards = nil},
[8468] = {title = "현상 수배: 욕망의 탤리스", objective = "영원노래 숲의 매날개 광장에 있는 경비대장 칸렌에게 탤리스를 처치한 증거를 가져가야 합니다.", description = "실버문에서 악명 높은 버림받은 자들의 우두머리인 욕망의 탤리스를 현상 수배하는 바입니다. 그는 실버문의 선량한 시민들을 상대로 연쇄 범죄를 저질러 왔으며, 도시 경비병 두 명을 살해한 죄목이 있습니다.\n\n그를 처치하고 경비대장 칸렌에게 보고하는 이에게는 현상금이 있을 것입니다.", progress = "내게 보여 줄 거라도 있소?", completion = "탤리스, 그 악당이 마침내 천벌을 받았군. 잘하셨소이다. 한동안은 버림받은 자들이 잠잠해지겠어...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8469] = {title = "살파에게 정기의 구슬 가져다주기", objective = "<name>, 나는 당신을 신뢰하게 되었지만 아직 의심을 떨치지 못한 우리 일족들의 신뢰도 얻어야 하오. 그러려면 당신에게 할 일이 하나 있소이다.\n\n눈사태일족은 사악한 영혼으로부터 자신들을 보호하기 위해 정기의 구슬을 지니고 다닌다고 하오. 하지만 정작 눈사태일족 자신들이 타락을 퍼뜨리는 하수인이 된 것으로 보아 그 구슬은 아무런 효과도 없는 것이 분명하오. 타락한 눈사태일족 펄볼그들이 갖고 다니는 정기의 구슬을 내게 가져다주시오. 5개씩 가지고 올 때마다 나무구렁일족의 신뢰를 얻게 될 것이오.", description = nil, progress = "<name>, 나는 당신을 신뢰하게 되었지만 아직 의심을 떨치지 못한 우리 일족들의 신뢰도 얻어야 하오. 그러려면 당신에게 할 일이 하나 있소이다.\n\n눈사태일족은 사악한 영혼으로부터 자신들을 보호하기 위해 정기의 구슬을 지니고 다닌다고 하오. 하지만 정작 눈사태일족 자신들이 타락을 퍼뜨리는 하수인이 된 것으로 보아 그 구슬은 아무런 효과도 없는 것이 분명하오. 타락한 눈사태일족 펄볼그들이 갖고 다니는 정기의 구슬을 내게 가져다주시오. 5개씩 가지고 올 때마다 나무구렁일족의 신뢰를 얻게 될 것이오.", completion = "또다시 당신의 신망을 증명해 보였소! 우리 일족에게 당신의 공로를 꼭 알리겠소.\n\n눈사태일족 정기의 구슬을 발견하면 잊지 말고 내게 가져다주시오. 5개씩 가져올 때마다 우리 일족에게 당신 얘기를 잘 해주겠소.", rewards = nil},
[8470] = {title = "마른가지일족 의식의 토템", objective = "나무구렁 요새 안으로 마른가지일족 의식의 토템을 가지고 가서 그 용도를 알아낼 수 있는 펄볼그를 찾아야 합니다. 중립적 이상의 평판을 받아야만 나무구렁일족과 대화할 수 있습니다.", description = "당신이 발견한 것은 마른가지일족 펄볼그들이 사용하는 의식의 토템 중 하나입니다. 겉으론 특별할 것이 없어 보이지만 내부에서 뿜어져 나오는 절망감을 생생하게 느낄 수 있습니다. 마른가지일족 펄볼그가 겪고 있는 타락을 가장 잘 설명해 줄 수 있는 것이 있다면 틀림없이 바로 이 물건일 것입니다.\n\n나무구렁 요새 안에 있는 펄볼그 중 하나가 이 토템의 용도에 대해 알아낼 수 있을 것 같기는 한데... 그들이 당신과의 대화에 응할지는 그들의 신뢰를 얼마나 얻어내는가에 달렸습니다.", progress = "<class>|1이여;여;, 제가 도와드릴 일이라도 있소? 언뜻 보기에는 아무 일 없어 보이는데 뭔가 문제가 있는 것이 분명하군. 그래, 뭔가 느껴지고 있소. 재앙을 불러올 뭔가가...", completion = "이 토템... 이것은 마른가지일족 의식의 토템 중 하나인 것 같소. 그런데 부패했는지 두툼하고 악취가 심하게 나는군. 그들로 하여금 같은 동족인 우리를 적대시하도록 만든 어떤 사악한 기운이 지금 이 안에 들어있는 것이 틀림없소.\n\n이것을 우리에게 가져온 것은 아주 현명한 판단이었소, &lt;name&gt;. 잘 연구해서 의식을 치른다면 우리 동족의 정신을 오염시킨 것들의 정체를 밝혀낼 수 있을 거요. 친구여, 감사하오! 의식의 토템을 발견한 업적에 대한 보답으로 드리는 것이니 받아주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n일급 치유 물약일급 마나 물약"},
[8471] = {title = "눈사태일족 의식의 토템", objective = "나무구렁 요새 안으로 가서 눈사태일족 의식의 토템의 용도를 알아낼 수 있는 펄볼그를 찾아야 합니다. 중립적 이상의 평판을 받아야만 나무구렁일족과 대화할 수 있습니다.", description = "당신이 발견한 물건은 눈사태일족 의식의 토템 중 하나입니다. 겉보기에는 특별한 점이 없는 것 같지만 공포와 절망을 뿜어내고 있는 것이 생생하게 느껴집니다. 많은 눈사태일족 펄볼그들이 이런 물건을 지니고 다닌다는 사실은 그들의 상황을 파악하는 데 큰 도움이 될 것이 분명합니다.\n\n나무구렁 요새 안에 있는 펄볼그 중 하나가 이 토템의 용도에 대해 알 텐데... 당신과의 대화에 응할지는 그들의 신뢰를 얼마나 얻어내는가에 달렸습니다.", progress = "<class>|1이여;여;, 무슨 일이시오? 언뜻 보기에는 평안해 보이지만 뭔가 심상치 않은 일로 왔다는 게 느껴지는데... 우리 펄볼그들과 당신 같은 <race> 모두에게 말이오. 자, 무슨 일로 찾아온 거요?", completion = "이것은... 꼭 눈사태일족 의식의 토템처럼 생겼는데, 이해할 수 없는 어떤 힘에 의해 뒤틀려 있소. 눈사태일족으로 하여금 우리를 적대시하도록 만든 어떤 타락한 기운이 이 안에 있는 것이 분명하외다.\n\n성스러운 지혜가 이 토템과 &lt;name&gt;, 당신을 우리에게 인도하셨군. 이것을 철저히 연구하도록 하겠소. 그러면 언젠가 눈사태일족도 우리에 대한 적개심을 거둘 날이 오겠지.\n\n친구여, 고맙소. 이것은 선행에 대한 보답으로 드리는 것이니 받아주시오.", rewards = "다음과 같은 것들을 받습니다:\n\n일급 치유 물약일급 마나 물약"},
[8472] = {title = "치명적인 고장", objective = "실버문의 폐허를 배회하는 비전 순찰자들에게서 비전 핵 6개를 수집하여, 영원노래 숲의 매날개 광장에 있는 마법학자 자로니스에게 가져가야 합니다.", description = "우리 선조가 도시를 지키기 위해 만든 비전 순찰자들이 위험한 상태로 방치되어 있습니다. 그들은 주인인 우리를 알아보지도 못하고 눈에 띄는 즉시 공격하고 있습니다.\n\n순찰자들은 만든 지 수년이 지났지만 이들에게 동력을 공급하는 비전 핵은 아직도 쓸모가 많은 소중한 물건입니다. 비전 핵을 모아서 가져오시면 유용하게 재활용하겠습니다. 북서쪽에 실버문의 폐허 지역으로 가면 비전 순찰자를 발견하실 수 있습니다.", progress = "비전 핵을 벌써 다 모으셨나요?", completion = "아주 잘하셨습니다. 현재 우리 마력의 원천인 비전 성소들이 제 기능을 발휘하지 못하고 있는데, 이 강력한 비전 핵을 사용하면 우리에게 필요한 동력을 오랫동안 공급할 수 있습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #23367아이템 #24241아이템 #27552아이템 #131237\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8473] = {title = "괴로운 임무", objective = "불타버린 숲에서 시들어버린 숲지기 10마리를 처치한 후, 영원노래 숲에 불타버린 숲의 북서쪽 탑 안에 있는 라리아나 리버윈드에게 보고해야 합니다.", description = "요즘은 우리 모두에게 어려운 시기입니다. 스컬지의 진군을 저지하기 위해 유령의 땅 가장자리의 숲을 전부 태워버리기로 한 것은 정말 어려운 결정이었지요.\n\n수년간 우리의 친구였던 숲지기들은 현재 불타버린 숲을 따라 새로 조경을 조성하려 합니다.\n\n<class>님, 이런 부탁을 하는 것은 정말 괴로운 일이지만, 우리는 옛 동맹이 추진 중인 일을 중단하라고 설득하는 데 실패했어요. 우리에게 남은 마지막 방법으로 그대가 저들을 막아주십시오. 바로 힘으로 말이죠!", progress = nil, completion = "임무를 완료하셨군요. 이런 극단적인 방법을 사용해야 하는 현실이... 그리고 우리의 적 스컬지가 정말 원망스럽네요!\n\n제 말을 명심하세요. 어떤 대가를 치르더라도 우리 땅을 지켜야 합니다. 우리는 승리할 것입니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8474] = {title = "늙은 흰나무껍질의 목걸이", objective = "늙은 흰나무껍질의 목걸이를 만든 이를 찾아야 합니다. 이 물건을 알아보는 이라면 그 안에 담긴 의미를 바로 이해할 수 있을 것입니다.", description = "목걸이에는 '라리'라는 짧은 이름이 새겨져 있습니다. 이 글자들로 목걸이의 제작자를 찾을 수 있겠습니다.", progress = "보여줄 물건이라도 있으신가요?", completion = "이... 이 목걸이... 이 물건은 우리 마을을 재건하는 데 도움을 준 늙은 흰나무껍질에게 내가 선물로 주었지요.\n\n이 목걸이를 그대가 가져왔다는 건...\n\n&lt;평정을 찾기 위해 헛기침을 하는 블러드 엘프&gt;\n\n목걸이를 가져다주셔서 감사합니다. 그런데 &lt;name&gt;, 그대에게 한 가지 부탁이 있습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8475] = {title = "죽음의 흉터", objective = "역병해골 약탈자 8마리를 처치하고, 영원노래 숲의 죽음의 흉터 밖에 있는 순찰자 자엘라에게 보고해야 합니다.", description = "영원노래 숲을 가로지르는 검은 토양을 보고 있노라면, 스컬지를 이끌고 소중한 우리 도시를 침략한 아서스를 절대 잊을 수가 없답니다.\n\n이 땅은 손상되어 보기도 흉할 뿐만 아니라, 근래에는 유령의 땅부터 실버문까지 스컬지들을 끌어들이고 있습니다.\n\n가서 내 부하들을 도와 죽음의 흉터를 떠도는 넋이 나간 언데드들을 처치해 주십시오.", progress = nil, completion = "언제 스컬지가 공격을 포기할지는 예상할 수 없지만, 우리는 늘 죽음의 흉터를 지켜낼 도움의 손길을 기다리고 있습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #23375아이템 #23376아이템 #23377아이템 #131238\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8476] = {title = "아마니의 침략", objective = "영원노래 숲의 원정순찰대 산장에 있는 부관 돈러너가 아마니 광전사와 아마니 도끼 투척병을 각각 5마리씩 해치워 달라고 했습니다.", description = "우리 왕국은 인간이나 오크의 왕국처럼 넓지 않답니다. 아제로스에서 우리에게 허락된 땅은 지금 보고 있는 곳이 거의 전부입니다.\n\n아웃랜드에 다다를 때까지는, 무슨 일이 있어도 지금 우리가 살고 있는 이 작은 땅을 지켜야 합니다.\n\n여기서 남동쪽으로 이웃해 있는 미개한 아마니일족 트롤들은 이 땅의 소유권에 대해 우리와 다른 생각을 품고 있는 것 같습니다. 매일같이 반복되는 놈들의 침략을 더는 참을 수 없습니다. 녀석들의 근거지인 제브와타와 토르와타로 가서 따끔한 맛을 보여주십시오.", progress = nil, completion = "잘했습니다. 그대와 같은 분들을 더 만난다면, 머지않아 우리 고향을 예전의 영광스러웠던 모습으로 회복할 수 있을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8477] = {title = "창제작자의 망치", objective = "원정순찰대 산장의 남동쪽에 토르와타로 가서 창제작자 오템베를 찾은 후, 영원노래 숲의 원정순찰대 산장에 있는 아라텔 선포지에게 오템베의 망치를 가져가야 합니다.", description = "아마니와 신도레이가 서로 미워하는 데는 긴 사연이 있답니다. 하지만 장인의 솜씨를 평가할 때 이런 점은 문제가 되지 않지요.\n\n우연히 아마니의 무기 몇 점을 볼 기회가 있었는데 그 솜씨에 감탄하지 않을 수 없었습니다. 창제작자 오템베가 사용하는 마법의 망치는 아주 가볍고 균형이 잘 잡혀 있어서 신속하고도 효율적으로 무기를 제작할 수 있다는 소문이 있답니다.\n\n그 망치를 가져오시면 그걸로 그대에게 좋은 무기를 만들어 드리겠습니다.", progress = "오템베의 망치는 가져오셨나요?", completion = "소문이 사실이었군요. 이 망치는 가벼우면서도 정말 강력하네요. 이걸로 아직 끝내지 못한 작품들을 완성할 수 있겠네요. 물론 완성된 작품을 가장 먼저 고를 수 있는 분은 그대뿐입니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #22958아이템 #22959아이템 #22963\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8479] = {title = "줄마로쉬", objective = "토르와타에 포로로 잡혀 있는 트롤 벤자쉬가 족장 줄마로쉬를 처치하고 그 증거를 가져다 달라고 했습니다. 족장 줄마로쉬는 엘렌다르 호수 건너, 제브와타에서 찾을 수 있습니다.", description = "좀 더 가까이 오게. 벤자쉬는 자네를 해치지 않을 테니 겁낼 필요 없어.\n\n자네 종족과 마찬가지로 우리 검은창 부족과 아마니는 철천지원수 사이라고 할 수 있지. 놈들의 우두머리인 줄마로쉬는 아주 사악한 트롤이라네. 놈은 내게 독약을 먹인 다음 죽을 때까지 이 감옥에 가둬놓으려 했다고.\n\n죽음은 두렵지 않네. 나는 죽음을 목격했고 그녀를 향해 웃어주었지.\n\n이봐, 난 아직 편히 잠들 수 없어. 줄마로쉬가 죽기 전까지는. 제브와타의 호수를 건너면 녀석을 찾을 수 있을 거야. 자네가 추악한 그놈을 처치했다는 증거를 가져올 때까지 나는 이 독을 견디고 있겠네. 그때야 나도 편히 잠들 수 있을 것이야.", progress = "줄마로쉬를 처치한 증거는?", completion = "해냈군. 줄마로쉬는 죗값을 치렀어. 놈은 우리 마을에 불을 질렀네. 이 감옥에 갇히기 전에 나는 아마니 일족을 수없이 죽였지. 내가 모래 속에 감춰둔 물건이 있네. 자네에게 주는 선물이야.\n\n아... 슬슬 독이 퍼지는군. 이제 잠들 시간인가...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #22969아이템 #22971\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8480] = {title = "잃어버린 무기 수집", objective = "영원노래 숲에 있는 벨렌드리스 화이트몬에게 신도레이 무기 8개를 가져가야 합니다.", description = "버림받은 자들이 날이 갈수록 과감해지고 있소. 그들의 조직은 해돋이 부두를 공격할 수 있을 만큼 정비가 되었소.\n\n그 자체로도 어이가 없지만, 놈들로부터 공격을 받은 우리 편은 무기까지 전부 버리고 후퇴하고 말았소. 우리 무기를 되찾고 그 무뢰한들에게 누가 이 땅의 지배자인지 똑똑히 보여주시오.", progress = "잃어버린 무기는 아직 못 모았소?", completion = "정말 잘했소. 이제 우리가 누군지 버림받은 자들이 확실히 깨닫도록 해줍시다!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #22956아이템 #22957아이템 #133696\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8481] = {title = "모든 악의 근원", objective = "눈사태일족 펄볼그 마을에 있는 대족장 눈사태의 동굴 입구에 악마 소환의 횃불을 꽂은 후 악마를 해치우고 나무구렁 요새에 있는 외눈 고른에게 잔디비어스의 정수를 가져가야 합니다.", description = "고맙소, <name>. 덕분에 모든 악의 근원을 소환해 낼 방법을 알아냈소. 바로 눈사태일족을 지배하는 타락한 악마 말이오!\n\n이 횃불을 대족장 눈사태의 동굴로 가지고 가서 입구에 꽂으시오. 그러면 악마가 무슨 일인지 알아보려고 스스로 정체를 드러낼 것이오. 바로 이때 친구들과 함께 놈을 처치해야 하오! 악마를 쓰러뜨리고 그 정수를 얻어야만 눈사태일족의 치료를 시작할 수 있고... 나무구렁 요새도 구할 수 있소.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n나무구렁일족 수호자"},
[8482] = {title = "첩보 문서", objective = "영원노래 숲의 매날개 광장에 있는 앨돈 선브랜드에게 첩보 문서를 가져가야 합니다.", description = "이 문서에는 영원노래 숲에 있는 전략적으로 중요한 건물들의 위치가 자세히 기록된 지도가 들어있습니다. 비전 성소의 약도 역시 자세하게 그려져 있습니다. 또한 알아볼 수 없는 언어로 기록된 설명도 잔뜩 있습니다.\n\n다르나서스에서 온 첩자가 이 문서를 지니고 있었으니 앨돈 선브랜드 경비대장에게 보고하는 것이 좋겠습니다.", progress = "내게 가져온 물건이라도 있습니까? 어디 한번 봅시다.", completion = "나이트 엘프에게서 이 문서를 발견했다는 게 확실합니까? 여기 적혀 있는 글은 분명 드워프 언어인데... \n\n내가 이해한 내용대로라면, 이 글을 쓴 자가 고장을 일으킨 것이 아니라 그 결과를 확인하기 위해 여기 첩자로 파견된 것이 분명합니다. 우리의 노력은 헛되고 위험하다고 적혀있습니다... 도대체 누구지?\n\n불을 보듯 뻔하지! 아이언포지에서 사절이 온 것입니다! 예전에 우린 얼라이언스의 일원이라면 누구든지 믿는 멍청이었지요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8483] = {title = "드워프 첩자", objective = "조사단 앤빌워드를 제거한 다음 영원노래 숲의 매날개 광장에 있는 앨돈 선브랜드에게 그 증거를 가져가야 합니다.", description = "잘 들으십시오. 비록 첩자의 정체를 밝혀내기는 했지만 공개적으로 처치할 수 없는 미묘한 상황입니다. 놈이 달아날 가능성도 매우 크기 때문에 사로잡지 못할 수도 있습니다.\n\n북부 성소에 있는 조사단 앤빌워드를 찾아서 세상의 쓴맛을 보여 주십시오. 우리 도시에 첩자가 침투했다는 사실이 외부에 알려지는 일은 원치 않으니 조용히 처리해 주시기 바랍니다.\n\n그런 다음 놈이 죽었다는 증거를 가져오시기 바랍니다. 이번 일로 아이언포지에서도 신도레이의 일에 간섭하면 어떻게 되는지 분명히 깨닫게 될 겁니다.", progress = "침입자는 처리했습니까?", completion = "음... 임무를 완수했군요. 훌륭합니다.\n\n순찰대장님께도 이번 상황에 대해서 보고를 해 놓았습니다. 날 믿으십시오. 드워프 녀석들은 죗값을 단단히 치를 것입니다.\n\n오늘 그대는 동족을 위해 아주 큰일을 해낸 것입니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #23372아이템 #23373아이템 #133695\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8484] = {title = "평화 협정", objective = "아이언포지에 있는 국왕 마그니 브론즈비어드에게 평화의 나무구렁일족 공물을 가져가야 합니다.", description = "당신의 공적은 어느 영웅의 이야기보다 훨씬 위대한 것이오, <name>. 만약 당신이 종족의 대표자라면 우리는 기꺼이 당신네 종족들과 함께 평화를 지키기 위해 싸울 것이오.\n\n철로 된 산에 살고 있는 드워프 국왕에게 이 공물을 전해 주시소. 아마 당신들은 그곳을 아이언포지라고 부르지... 과거 드워프 국왕이 얼라이언스를 대표해 우리와 접촉을 시도한 적이 있었소. 그러나 지금 얼라이언스와 평화 협정을 맺는 일에 있어 가장 적임자는 바로 자신이라는 것을 당신도 인정하시오.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n얼라이언스 평판\n\n다음과 같은 것들을 받습니다:\n\n"},
[8485] = {title = "평화 협정", objective = "오그리마의 스랄에게 평화의 나무구렁일족 공물을 가져가야 합니다.", description = "당신의 공적은 어느 영웅의 이야기보다 훨씬 위대한 것이오, <name>. 만약 당신이 종족의 대표자라면 우리는 기꺼이 당신네 종족들과 함께 평화를 지키기 위해 싸울 것이오.\n\n듀로타의 성에 살고 있는 오크 대족장에게 이 공물을 전해 주면 좋겠소. 당신들은 그곳을 오그리마라고 부르던데... 과거 오크 대족장이 호드를 대표해 우리와 접촉을 시도한 적이 있었소. 그러나 지금 호드와 평화 협정을 맺는 일에 있어 가장 적임자는 바로 자신이라는 것을 당신도 인정하시오.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n호드 평판\n\n다음과 같은 것들을 받습니다:\n\n"},
[8486] = {title = "불안정한 성소", objective = "맥지기 벨라니아가 마나 망령과 마나 추적자를 각각 5마리씩 처치해 달라고 했습니다.", description = "멍청이 케이다니스가 이쪽으로 누군가를 보낼 때가 됐구나 싶었죠.\n\n서부 성소의 부하를 늘리면 위험하다고 경고했건만! 지금 동력 전환기 중 한 대가 파괴되어 서부 성소에서 비전 망령들이 쏟아져 나오고 있답니다!\n\n수리공을 보내기 전에 먼저 그대가 가서 그 망령들을 해치워 주십시오. 서두르시기 바랍니다!", progress = nil, completion = "고맙습니다. 망령들을 해치웠으니 성소가 어느 정도 피해를 보았는지 알아볼 수 있겠군요. 이 사태가 오래가지 않기만을 바랄 뿐입니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #23370아이템 #23371\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8487] = {title = "오염된 땅", objective = "영원노래 숲의 동부 성소에 있는 수습생 미르베다가 오염된 토양 견본 8개를 모아 달라고 했습니다.", description = "아서스가 스컬지 군대를 몰고 실버문으로 진군하기 전만 해도 이 비전 성소는 온전히 작동했습니다.\n\n하지만 이제는 죽음의 흉터의 다른 지역과 마찬가지로 아무짝에도 쓸모가 없지요. 대지는 오염되어 언데드들이 몰려들고 있으며, 지맥의 정기도 완전히 파손되었습니다.\n\n저는 오염된 땅을 원상태로 복구할 수 있을지 알고 싶습니다. 이 지역의 토양 견본을 모아다 주시면 제 연구에 많은 보탬이 될 것입니다. 시간만 충분하면 원상태로 되돌릴 수 있을 거예요.", progress = "부탁한 견본은 모두 모으셨나요?", completion = "훌륭하군요. 이 견본에 원소 증가 마법을 부여하면 토양을 오염시킨 물질을 좀 더 자세하게 분석할 수 있겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8488] = {title = "예상 밖의 결과", objective = "수습생 미르베다와 대화한 뒤, 스컬지의 습격으로부터 그녀를 보호해야 합니다.", description = "뭔가 잘못됐어요. 스컬지의 존재가 느껴집니다. 어서 싸울 준비를 하세요!", progress = nil, completion = "아무리 노력해도 희망이 보이지 않는군요. 토양의 근본 성질까지 변하다니... 오염된 토양을 되돌릴 수는 없겠어요. 지금까지 도와주셔서 감사합니다. 마지막으로 한 번만 더 도와주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8489] = {title = "온전한 변환기", objective = "맥지기 벨라니아에게 온전한 비전 변환기를 가져가야 합니다.이것은 맥지기 벨라니아가 말했던 비전 변환기 중 하나인 것 같습니다. 화염에 의한 어떤 손상도 입지 않은 것으로 보입니다. 벨라니아라면 이 물건을 어떻게 사용하는지 알지도 모릅니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "이것은 맥지기 벨라니아가 말했던 비전 변환기 중 하나인 것 같습니다. 화염에 의한 어떤 손상도 입지 않은 것으로 보입니다. 벨라니아라면 이 물건을 어떻게 사용하는지 알지도 모릅니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8490] = {title = "방어선에 동력 공급", objective = "동부 마법석에 마력 깃든 수정을 놓은 후 스컬지의 공격으로부터 1분 동안 보호해야 합니다. 영원노래 숲에 있는 마법석 파수꾼 데리안에게 마력 깃든 수정을 가지고 돌아가서 보상을 받으십시오.", description = "고대 마법석은 한때 영원노래 숲 경계를 둘러싸고 동력을 공급했습니다. 하지만, 수많은 마법석이 아서스의 공격에 파괴되거나 도난당했죠.\n\n온전한 모습을 유지하고 있는 세 개의 마법석 중에 힘을 유지하고 있는 것은 하나뿐입니다. 그런데 어쩌면 동쪽에 있는 마법석은 복구할 수 있을지도 모릅니다.\n\n이 수정을 가져가서 동부 마법석에 놓으십시오. 아마 몇 분 정도 걸릴 것입니다. 조심하십시오. 마법석은 주변의 스컬지를 빨아들일 것입니다. 스컬지가 마법석을 파괴하지 못하도록 하십시오!", progress = "벌써 마법석에 동력을 공급하셨나요?", completion = "잘하셨습니다. 이제 마법석이 스컬지를 상대로 좀 더 오래 버틸 수 있겠군요. &lt;name&gt;, 도와주셔서 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8491] = {title = "모피 수집", objective = "영원노래 숲의 산들바람 마을에 있는 벨란 브라이트오크가 갈기발 스라소니 모피 6개를 가져다 달라고 했습니다.", description = "이 지역에 서식하는 갈기발 스라소니는 품질이 매우 우수한 모피로 유명하오. 쓰레기 같은 나이트 엘프 놈들이 갈기발 스라소니를 밀렵하기 위해 이 지역을 서성대는 걸 본 적도 있으니까.\n\n아마니 트롤과 충돌이 자주 발생하다 보니 물자도 좀 부족하고, 우리 순찰자들은 모피를 수집할 시간도 별로 없소. 우리를 도와 갈기발 스라소니 모피를 좀 모아주면 손수 제작한 방어구를 보상으로 드리겠소. 이곳에서 북쪽에 있는 숲으로 가면 갈기발 스라소니가 쉽게 눈에 띌 것이오.", progress = "돌아왔군. 모피는 가져왔소?", completion = "더할 나위 없이 좋은 재료로군. 자, 손수 제작한 방어구 중 하나를 보상으로 가지도록 하시오. 그대가 가져온 모피로 더 많은 방어구를 만들 수 있을 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #22951아이템 #22952아이템 #22953아이템 #131239\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8492] = {title = "얼라이언스에 구리 주괴 조달!", objective = "아이언포지의 군사 지구에 있는 하사관 스톤브로우에게 구리 주괴 20개를 가져가야 합니다.", description = "안녕하십니까, <class>|1이여;여;, 보아하니 군수 물자를 확보하는 일에 딱 맞을 것 같군요! 우리는 지금 안퀴라즈 전쟁에 필요한 자원을 확보하기 위해 도움이 절실한 상황이며 당신에게 운이 좋은 날이로군요.\n\n난 구리 주괴 20개씩을 모으고 있습니다. 매우 의미 있는 일이 될 텐데... 어떻습니까, 얼라이언스 연합을 도와주겠습니까?", progress = "구리 주괴 20개를 모두 모았습니까?", completion = "해냈군요! 이 구리 주괴를 쌓아놓고 당장 전쟁 물자를 만드는 데 이용해야겠습니다. 당신과 같은 용사들이 있기에 얼라이언스를 위해 헌신하는 일에 긍지를 느낀답니다. 정말 잘했습니다!\n\n구리 주괴가 좀 더 생기게 되면, 내게 가져다줘야 한다는 것을 잊지 마십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8493] = {title = "얼라이언스에 구리 주괴 추가 조달!", objective = "아이언포지의 군사 지구에 있는 하사관 스톤브로우에게 구리 주괴 20개를 가져가야 합니다.", description = "다시 돌아왔군요? 좋습니다! 안퀴라즈 전쟁에 필요한 물자를 확보하려면 구리 주괴가 더 필요합니다. 우리를 도와주겠습니까?", progress = "다시 돌아왔군요? 좋습니다! 지금까지 당신이 제공한 구리 주괴는 전쟁 준비에 여러 바여러 방면으로 도움이 될 것입니다. 내가 알기엔 구리 주괴는 시간이 된다면 우리가 배치를 계획하고 있는 자이로콥터의 소규모 함대뿐 아니라, 증기 전차를 만드는데 부품으로 사용될 것입니다.\n\n여기 구리 주괴 더미에 손대지 마십시오. 우린 안퀴라즈 전쟁에 필요한 물자를 확보하려면 구리 주괴가 더 필요합니다. 우리를 도와주겠습니까?", completion = "정말 대단하군요! 여기 저기 땅을 파서 그 구리를 찾고 이를 녹이는 것이 얼마나 어려운 일인지 잘 알고 있습니다. 경매장에서 돈을 주고 샀다면 얘기가 조금 다르겠지만 말입니다... 어쨌든 내게는 큰 도움이 되었습니다. 전쟁 물자를 확보하는 일에 큰 공을 세웠으니 모두의 칭송을 받게 될 것입니다. 구리 주괴가 더 생기면 내게 지체없이 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8494] = {title = "얼라이언스에 철 주괴 조달!", objective = "아이언포지의 군사 지구에 있는 하사관 칸스에게 철 주괴 20개를 가져가야 합니다.", description = "이봐... 거기 멋쟁이 친구, 정말 반갑소. 당신이 모험을 떠나 있는 동안 소식을 못 들을 경우에 대비해 얼라이언스 연합에서는 안퀴라즈에서 벌어질 전쟁을 준비를 해왔소이다. 현재 철 주괴가 많이 필요한 상태인데 내게 철 주괴 20개를 가져다주시오. 당신만 믿겠소. 그래도 되겠지?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8495] = {title = "얼라이언스에 철 주괴 추가 조달!", objective = "아이언포지의 군사 지구에 있는 하사관 칸스에게 철 주괴 20개를 가져가야 합니다.", description = "이렇게 일찍 돌아오다니! 당신에 대한 내 판단이 또 빗나가는 순간이로군. 당신만 보면 늘 기분이 좋아진단 말이야... 그건 그렇고, 당신도 알다시피 무기, 갑옷, 증기 전차 그리고 곤충 사냥에 필요한 여러 가지를 만들려면 철 주괴가 더 있어야 하오. 당신이 줄구룹을 탐험할 때 들렀던 곳이나 요즘 여행 다니는 곳에 가면 철 주괴 20개를 더 가지고 올 수 있을 거라 생각하는데, 그렇지 않소?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8496] = {title = "전장에 붕대 공급", objective = "실리더스 세나리온 요새에 있는 바람소환사 프라우드혼에게 두꺼운 룬매듭 붕대, 두꺼운 마법 붕대, 두꺼운 비단 붕대를 각각 30개씩 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 X도 함께 가져가야 합니다.", description = "최근 발생한 부상자로 인해 전장에서 붕대가 많이 부족하다고 합니다. 응급 치료에 쓰는 붕대를 구해 세나리온 요새에 있는 바람소환사 프라우드혼에게 전달해 주십시오.", progress = "<name>, 제게 전달할 물건이 있지 않나요?", completion = "제때 와주셨군요. 이 붕대 덕분에 여러 목숨 살릴 수 있게 되었습니다. 도와주셔서 감사합니다, &lt;name&gt;. 자, 다음번에 맡아 주실 임무입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8497] = {title = "사막 긴급구호 물자", objective = "실리더스의 세나리온 요새 여관에 있는 캘랜드라스에게 물의 보주, 강력한 해독제, 훈제 사막 경단을 각각 4개씩 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 I도 함께 가져가야 합니다.", description = "세나리온 요새에 지금 신병들이 도착했는데 과연 사막에서 살아남을 수 있느냐가 문제입니다. 경험이 부족한 신병들에게는 맹독을 가진 다양한 생물뿐 아니라 탈수증도 심각한 위협이 될 수 있습니다. 사막 긴급구호 물자가 쓸만한 물건들을 모아서 세나리온 요새에 있는 캘랜드라스에게 가져가십시오.", progress = "제게 전달할 물건이 있지 않나요?", completion = "정말 잘됐군요! 때마침 이것들이 절실하게 필요하던 참이었는데... 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8498] = {title = "황혼의 전투명령서", objective = "황혼의 전투명령서를 찾아서 실리더스의 세나리온 요새에 있는 지휘관 마랄리스에게 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 X도 함께 가져가야 합니다.", description = "우리 정찰병들의 보고에 의하면 황혼의망치단 지휘관들이 새로운 전투명령서를 하달했다고 합니다. 황혼의 예언자들이 이 명령서를 배포하고 있는데 경비가 철통 같답니다. 황혼의 전투명령서를 가로채서 지휘관 마랄리스에게 전해 주십시오.", progress = "내게 전달할 물건이 있지 않소?", completion = "잘하셨소. 적보다 한발 앞서 행동하는 것이 무엇보다 중요한 것이오. 이 정보를 이용하면 황혼의망치단이 감행할 공격을 예상할 수 있을 것이외다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전술 휘장전술 임무"},
[8499] = {title = "얼라이언스에 토륨 주괴 조달!", objective = "아이언포지의 군사 지구에 있는 남작부인 트윈브레이드에게 토륨 주괴 20개를 가져가야 합니다.", description = "얼라이언스 연합에 필요한 게 무엇인지를 물어봐 주시다니 정말 친절한 분이시군요. 현재 다른 물자들도 모두 부족해 열심히 모으고 있는 중이지만, 특히 토륨 주괴가 많이 필요한 실정입니다. 제가 맡은 임무도 바로 그것이죠. 토륨은 전쟁에 필요한 여러 가지를 만드는 데 사용되지만, 현재 가장 시급한 것은 증기 전차를 만들어 완성되는 즉시 실리더스로 공수해야 하는 일입니다. 우리를 도와주시겠습니까?", progress = "전에 말씀 드린 토륨 주괴를 모두 모으셨길 진심으로 바랍니다.", completion = "감사합니다, &lt;class&gt;|1이여;여;! 정말 감사합니다! 이제 20개가 모였으니 앞으로 막대한 양을 더 모아야 되겠군요. 얼라이언스를 대신해 감사 드리는 바이며, 물론 보상도 받으실 거라는 걸 알려드려야겠군요. 토륨 주괴를 더 가져오시면 다시 얘기하도록 하죠.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8500] = {title = "얼라이언스에 토륨 주괴 추가 조달!", objective = "아이언포지의 군사 지구에 있는 남작부인 트윈브레이드에게 토륨 주괴 20개를 가져가야 합니다.", description = "다시 뵙게 돼서 정말 반갑습니다. 그동안 잘 지내셨죠? 실은 아직 토륨 주괴가 더 필요해요. 안퀴라즈 전쟁 물자를 충당하기 위해 토륨 주괴를 모으고 있는 중인데, 어떻게 좀 더 구할 수 없을까요?", progress = "다시 뵙게 돼서 정말 반갑습니다. 그동안 잘 지내셨죠? 실은 아직 토륨 주괴가 더 필요해요. 안퀴라즈 전쟁 물자를 충당하기 위해 토륨 주괴를 모으고 있는 중인데, 어떻게 좀 더 구할 수 없을까요?", completion = "대단하군요! 정말 잘하셨어요. 저는 우리 군대에 보급할 물자들을 생산하느라 여념이 없는 대장장이와 기술자들에게 토륨 주괴가 무사히 전달되고 있는지 확인하러 가야겠네요. 다시 한 번 감사 드립니다. 그리고 토륨 주괴를 더 발견하시면 꼭 다시 들러주시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8501] = {title = "목표: 독침 하이브아쉬", objective = "독침 하이브아쉬 30마리를 처치한 후 실리더스 세나리온 요새에 있는 지휘관 마랄리스에게 보고하십시오. 이 임무를 완료하려면 전투 임무 지령 XII를 가져가야 합니다.", description = "전쟁을 위한 준비가 한창인 지금, 실리더스 지역에 나타나는 실리시드의 존재는 우리 일에 커다란 위협으로 떠오르고 있습니다. 당신은 하이브아쉬 공격을 위한 지원군으로 선택되었습니다. 주요 목표는 날아다니는 독침 하이브아쉬입니다.\n\n임무를 마치면 지휘관 마랄리스에게 돌아가서 보고하십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8502] = {title = "목표: 일꾼 하이브아쉬", objective = "일꾼 하이브아쉬 30마리를 처치해야 한 다음 실리더스 세나리온 요새에 있는 지휘관 마랄리스에게 보고하십시오. 또한, 이 퀘스트를 완료하려면 전투 임무 지령 III도 함께 가져가야 합니다.", description = "전쟁 준비가 한창인 지금, 실리더스 지역에 출몰하는 실리시드 무리의 존재는 우리 일에 점점 더 커다란 위협으로 떠오르고 있습니다. 당신은 하이브아쉬 공격을 위한 지원군으로 선택되었습니다. 주요 목표는 일꾼 하이브아쉬입니다.\n\n임무를 마치면 지휘관 마랄리스에게 돌아가서 보고하십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8503] = {title = "얼라이언스에 갈래물풀 공급!", objective = "아이언포지의 군사 지구에 있는 병사 드랙슬게이지에게 갈래물풀 20개를 가져가야 합니다.", description = "갈래물풀이 얼마나 유용하게 쓰이는지 이미 말씀드리지 않았던가요? 아닌가요? 오, 이런... 어쨌든 우리는 갈래물풀이 많이 필요해요. 제가 많이라는 표현을 사용할 때는 정말 많이 필요하단 소리여요! 마아아않이요! 우리를 도와주실 수 있겠어요? 물론 갈래물풀을 우리에게 넘기시면 그것으로 만들 수 있는 멋진 물건들은 가질 수 없게 되겠지만 대신 좋은 일을 하시게 되는 겁니다!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8504] = {title = "얼라이언스에 갈래물풀 추가 공급!", objective = "아이언포지의 군사 지구에 있는 병사 드랙슬게이지에게 갈래물풀 20개를 가져가야 합니다.", description = "다시 오셨군요... 무슨 일로 오셨죠? 아, 갈래물풀이 더 필요한지 알아보러 오셨군요! 운이 좋으시네요. 아주 중요한 이 질문에 답을 하자면... 예, 아주 절실히 필요해요! 갈래물풀 20개를 더 모아 주실 수 있으시죠?", progress = "다시 오셨군요... 무슨 일로 오셨죠? 아, 갈래물풀이 더 필요한지 알아보러 오셨군요! 운이 좋으시네요. 아주 중요한 이 질문에 답을 하자면... 예, 아주 절실히 필요해요! 갈래물풀 20개를 더 모아 주실 수 있으시죠?", completion = "오, 이런. 거기 가지고 있는 것은 갈래물풀이로군요. 신선도가 유지되도록 서둘러서 상자에 넣도록 하죠. 당신은 갈래물풀을 가져다주셨기에 저, 아니... 우리 얼라이언스에게 큰 호의를 베풀어 주셨답니다. 갈래물풀을 공급해 안퀴라즈 전쟁 물자 확보에 큰 도움을 준 이가 &lt;name&gt;, 바로 당신이라는 사실을 모두에게 꼭 알리도록 하겠습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8505] = {title = "얼라이언스에 보라 연꽃 공급!", objective = "아이언포지의 군사 지구에 있는 수석 연금술사 나이트송에게 보라 연꽃 20개를 가져가야 합니다.", description = "보라 연꽃은 쓸모가 많은 꽃입니다. 난 보라 연꽃 전문가로서 얼라이언스 연합의 부탁으로 여기에서 일하고 있답니다. 채집한 약초를 잘 보관하고, 작전에 필요한 보라 연꽃을 충분히 확보하는 것이 내가 맡은 일입니다.\n\n아제로스 곳곳에 다니면서 보라 연꽃을 찾으면 내게 가져다주시기 바랍니다. 그래 주시겠습니까?", progress = "부탁한 보라 연꽃은 가지고 오셨습니까?", completion = "그대의 노고에 깊이 감사 드립니다. 무자비한 실리시드의 공격과 그들을 조종하는 세력을 물리치기 위해서는 모두가 단결하지 않는다면 안 될 것입니다. 호드 연합에서도 이를 위해 자체적으로 보라 연꽃을 모으고 있습니다. 보라 연꽃을 더 발견하시면 여기로 다시 가져오시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8506] = {title = "얼라이언스에 보라 연꽃 추가 공급!", objective = "아이언포지의 군사 지구에 있는 수석 연금술사 나이트송에게 보라 연꽃 20개를 가져가야 합니다.", description = "어서 오십시오, <class>|1이여;여;. 보라 연꽃이 조금씩 모이고 있기는 하지만 좀 더 많이 필요합니다. 보라 연꽃을 좀 더 모으실 수 있다면, 부탁이니 꼭 내게 가져와 주십시오.", progress = nil, completion = "얼라이언스를 대신해 기쁜 마음으로 받겠습니다. 노력해 주신 덕분에 전선에 나가 있는 우리 용사들을 위해 물약이나 오일을 만들 수 있게 되었습니다. 감사합니다, 그리고 더 얻으시면, 저에게 가져다주시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8507] = {title = "야전 임무", objective = "하이브조라 외곽에 있는 아이언포지 여단의 주둔지로 가십시오. 서명되지 않은 야전 임무 보고서를 연대장 블랙앤빌에게 제출하고 서명된 야전 임무 보고서를 받아야 합니다. 그런 다음 실리더스 세나리온 요새에 있는 바람소환사 칼돈에게 돌아가십시오.\n\n주의: 아이언포지 여단의 일원을 치유하거나 이로운 마법을 걸면 전투 상태가 됩니다.", description = "반갑소, <name>. 전쟁에서 중요한 역할을 맡으려면 우선 그대 몫의 야전 임무를 완수해야 하오.\n\n하이브조라 외곽으로 가면 블랙앤빌 연대장이 이끄는 아이언포지 여단이 있을 거요.\n\n연대장이나 부관인 자넬라 스타우트해머에게 보고한 후 돌아오시오. 더욱 중요한 임무를 준비해 놓고 기다리겠소.\n\n아, 한 가지 당부할 것은 오그리마 군단에 절대 가까이 가지 마시오. 양진영의 군대는 뿌리 깊은 적개심 때문에 적당히 떨어져 있을 수밖에 없는 상황이외다.", progress = "하이브조라 밖으로 가면 주둔 중인 블랙앤빌 연대장의 군대가 있을 것입니다. 연대장을 찾을 수 없으면 그의 부관인 자넬라 스타우트해머와 대화하십시오.", completion = "&lt;name&gt;, 정말 잘하셨소. 그동안 그대의 실력에 알맞은 몇 가지 임무를 준비해 두었소.\n\n그대 같은 이들이 계속 노력해 준다면 조만간 이 땅에서 적을 섬멸할 수 있을 것이오!\n\n새로운 임무를 받고 싶다면 블랙앤빌 연대장에게 가보시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n전투 임무병참 임무전술 임무"},
[8508] = {title = "야전 임무 보고서", objective = "이 보고서에 서명을 해달라는 말인가?", description = nil, progress = "이 보고서에 서명을 해달라는 말인가?", completion = "흠, 요즘은 요만한 전투를 벌이고도 야전 임무를 완수한 걸로 쳐주더군. 이것을 가지고 세나리온 요새로 돌아가게. 자네를 위해 뭔가 손쉬운 일을 분명히 준비해 놓고 기다리고들 있을 걸세.\n\n어서 가 보게!", rewards = "다음과 같은 것들을 받습니다:\n\n서명된 야전 임무 보고서"},
[8509] = {title = "얼라이언스에 아서스의 눈물 공급!", objective = "아이언포지의 군사 지구에 있는 선임하사 저메인에게 아서스의 눈물 20개를 가져가야 합니다.", description = "요점만 간단히 말하겠습니다, <class>|1이여;여;. 안퀴라즈 전쟁을 대비해 얼라이언스에 필요한 것은 아서스의 눈물입니다. 그것도 아주 많이 필요합니다. 전 명령에 따를 뿐이니 이유는 묻지 마십시오. 저도 별로 알고 싶지 않으니까요... 어쨌든 아서스의 눈물을 최대한 많이 모은 후 제게 가져다주시면 됩니다. 이 일을 맡으시겠습니까?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8510] = {title = "얼라이언스에 아서스의 눈물 추가 공급!", objective = "던 모로 비행장에 있는 선임하사 저메인에게 아서스의 눈물 20개를 가져가야 합니다.", description = "다 됐습니다. 확인해 보니 아서스의 눈물이 더 필요할 것 같군요. 지난번에 가셨던 장소에 가면 아서스의 눈물을 더 구할 수 있지 않을까 생각하는데... 아서스의 눈물을 빨리 모을수록 안퀴라즈에 있는 적들을 공격할 시기를 앞당길 수 있습니다.\n\n이번에도 도와주시겠죠?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8511] = {title = "얼라이언스에 얇은 가죽 공급!", objective = "아이언포지의 군사 지구에 있는 보니 스톤플레이어에게 얇은 가죽 10개를 가져가야 합니다.", description = "우리 스톤플레이어 가문은 아주 오래전부터 무두질을 가업으로 해 왔어요. 얼라이언스 연합에서 내 가족에게 안퀴라즈 전쟁에 필요한 얇은 가죽을 모으는 일을 도와 달라고 부탁한 것도 그러한 연유에서지요. 내가 여기서 하는 일은 가죽이 용도에 맞게 제대로 무두질 되었는지를 확인하는 것이랍니다. 하지만 당신의 도움이 필요합니다.\n\n나는 일 때문에 이곳을 떠날 수 없으니 당신이 대신 가서 가죽을 모아다 주면 좋겠는데... 어때요? 한번 해 보겠어요?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8512] = {title = "얼라이언스에 얇은 가죽 추가 공급!", objective = "아이언포지의 군사 지구에 있는 보니 스톤플레이어에게 얇은 가죽 10개를 가져가야 합니다.", description = "다시 만나 반가워요. 여러 가지 군수 물자를 만들려면 아무래도 얇은 가죽이 더 필요할 것 같군요. 10개만 더 가져다 주면 충분할 것 같은데...", progress = "다시 만나 반가워요. 여러 가지 군수 물자를 만들려면 아무래도 얇은 가죽이 더 필요할 것 같군요. 10개만 더 가져다 주면 충분할 것 같은데...", completion = "아낌없는 기부, 정말 고마워요. 바로 이것들을 얇은 가죽 더미에 가져다 놓을 것이고 그러면 즉시 가죽들은 좋은 방어구와 가죽 조각이나 우리의 전쟁 준비에 쓰일 다른 것으로 바뀌게 될 겁니다. 얇은 가죽은 항상 부족한 것 같으니, 더 구하게 되면 돌아와서 다시 와 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8513] = {title = "얼라이언스에 일반 가죽 공급!", objective = "아이언포지의 군사 지구에 있는 병사 포터에게 일반 가죽 10개를 가져가야 합니다.", description = "예, 그렇습니다. 저는 군수 물자에 필요한 일반 가죽을 찾아 수집하는 일을 담당하고 있습니다. 어떻게 구했는지는 상관없으니 일반 가죽을 구해서 제게 가져다주십시오. 바쁘지 않으시다면 도움의 손길을 보내주시면 정말 감사하겠습니다.", progress = "물론이죠, 누구신지 기억하고 있습니다. 혹시 지금 가지고 계신 그게 일반 가죽인가요?", completion = "우와! 마치 자원 봉사하러 여기 오신 분 같습니다. 가죽을 기부해 주셔서 정말 감사합니다. 잘 포장한 다음 개수를 확인해야겠습니다. 당신은 동료를 기쁘게 하는 방법을 잘 알고 있는 분이시로군요.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8514] = {title = "얼라이언스에 일반 가죽 추가 공급!", objective = "던 모로 비행장에 있는 병사 포터에게 일반 가죽 10개를 가져가야 합니다.", description = "네, 지금까지 모은 일반 가죽은 모두 $2063w개입니다. 너무 많은 부탁을 드리는 것 같아 죄송합니다만, 괜찮으시다면 제게 할당된 몫을 마저 채울 수 있도록 도와주셨으면 합니다.", progress = "그렇습니다, 많은 양의 일반 가죽을 모은 것 같습니다만 가죽이 더 필요합니다. 이 가죽들 모두 한 조각도 버리지 않고 잘 쓰이게 될 것이라 보장합니다. 너무 많은 부탁을 드리는 것 같아 죄송합니다만, 괜찮으시다면 제게 할당된 몫을 마저 채울 수 있도록 도와주셨으면 합니다.", completion = "대단하시군요! 일반 가죽을 이렇게나 많이 구해 주시다니! 가져다주신 보급품 바로 옆에 적합한 용도로 쓰이도록 가져다 놓도록 하겠습니다. 도와주신 덕분에 필요한 양의 일반 가죽을 금방 확보할 수 있을 것 같군요!\n\n감사합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8515] = {title = "얼라이언스에 두꺼운 가죽 공급!", objective = "아이언포지의 군사 지구에 있는 마사 파인스핀들에게 두꺼운 가죽 10개를 가져가야 합니다.", description = "오, 마침 잘 왔어요, <class>님. 여기도 할 일이 아주 많을 거예요! 안퀴라즈 전쟁 준비가 절정에 이르렀는데 저는 여기로 들어오는 두꺼운 가죽의 모든 기록을 관리해야 해요. 두꺼운 가죽으로는 아주 다양한 것들을 만들 수 있죠. 하지만 그러려면 우선 많은 양을 확보해야 한답니다. 제 말 이해하겠죠? 그게 바로 당신이 여기서 할 일이란 말이에요.\n\n어때요, 가서 질 좋은 두꺼운 가죽을 구해올 수 있겠어요? 네? 할 수 있겠죠?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8516] = {title = "얼라이언스에 두꺼운 가죽 추가 공급!", objective = "아이언포지의 군사 지구에 있는 마사 파인스핀들에게 두꺼운 가죽 10개를 가져가야 합니다.", description = "그래요, 이 정도로는 아직 충분하지 않아요. 우리 목표는 $2071w개예요. 그것으로 우리가 만들 수 있는 것들을 상상해 보세요! 온갖 종류의 갑옷과 무기, 증기 전차 안에 필요한 물건들, 거기에 라이플 조준경까지! 그리고 기계공학으로 고글도 만들 수 있어요. 만약 우리가 쓰고 남을 정도로 많은 양의 두꺼운 가죽을 모은다면 남는 것을 호드에게 제공해 비행선을 만드는 데 사용하도록 할 수도 있을 거예요!\n\n그러니 두꺼운 가죽을 좀 더 가져다주실래요?", progress = "그래요, 이 정도로는 아직 충분하지 않아요. 두꺼운 가죽 수집 목표치에 아직 도달하지 못했습니다. 그것으로 우리가 만들 수 있는 것들을 상상해 보세요! 온갖 종류의 갑옷과 무기, 증기 전차 안에 필요한 물건들, 거기에 라이플 조준경까지! 그리고 언제나 신나는 기계공학으로 고글도 만들 수 있어요!\n\n그러니 두꺼운 가죽을 좀 더 가져다주실래요?", completion = "또 해냈군요! 이 가죽을 어디서 어떻게 구해서 여기로 가지고 올 수 있었는지 정말 놀라울 따름이에요. 당신이 얼마나 많은 도움을 줬는지 알게 된다면 거리에서 만나는 이들마다 사인해 달라고 아마 난리가 날 거예요!\n\n두꺼운 가죽을 아낌없이 기부해 줘서 다시 한 번 고마워요.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8517] = {title = "얼라이언스에 리넨 붕대 조달!", objective = "아이언포지의 군사 지구에 있는 파수꾼 실버스카이에게 리넨 붕대 20개를 가져가야 합니다.", description = "안퀴라즈에서 벌어질 전쟁은 매우 치열하고 오래갈 것으로 예상됩니다. 따라서 얼라이언스가 무턱대고 전쟁을 시작하기보다는 사전에 그대와 같은 분들의 도움을 받아 필요한 물자를 확보해 두는 일이 매우 현명한 처사입니다.\n\n저는 전쟁에 필요한 리넨 붕대를 모으는 일을 맡아 달라는 부탁을 받았는데, 그대가 저를 도와 우리에게 필요한 리넨 붕대를 최대한 많이 모아주셨으면 합니다. 간단한 일은 아니지만 그래도 리넨 붕대를 구하는 일이 제일 쉬울 겁니다. 우리를 도와주시겠습니까?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8518] = {title = "얼라이언스에 리넨 붕대 추가 조달!", objective = "아이언포지의 군사 지구에 있는 파수꾼 실버스카이에게 리넨 붕대 20개를 가져가야 합니다.", description = "희생 정신이 정말 투철하신 분이군요! 여기에서 제 임무를 완수하려면 아직 리넨 붕대가 많이 모자랍니다. 리넨 붕대 모으는 일을 다시 한 번 도와주시겠습니까?", progress = "희생 정신이 정말 투철하신 분이군요! 여기서의 제 임무를 완수하려면 아직 리넨 붕대가 많이 모자랍니다. 리넨 붕대 모으는 일을 다시 한 번 도와주시겠습니까?", completion = "그대는 존경받아 마땅한 분입니다! 우리가 전시 상황이라는 것을 이용해 자기 호주머니나 채우려고 혈안이 된 작자들과는 다르게 그대는 얼라이언스, 아니 아제로스 전체에 희생 정신이 무엇인지 다시 한 번 보여 주셨습니다.\n\n엘룬의 가호가 늘 함께하기를!", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8519] = {title = "장기판 위의 졸", objective = "잊혀진 오랜 기억에 대해 가능한 모든 것을 확인한 후 타나리스의 시간의 동굴에 있는 아나크로노스와 대화하십시오.", description = "냉정을 되찾고 집중하니 수정 안에서 뭔가 꿈틀거리는 것을 느낄 수 있습니다. 그리곤 좀 더 자세히 들여다보니 지나간 과거를 보고 있다는 사실을 깨닫게 됩니다... 바로 잊혀진... 오랜 기억을.", progress = nil, completion = "스테그헬름이 배신한 후 나는 흩어진 흐르는 모래의 홀 파편을 모아 여기로 돌아왔다. 그리고 흐르는 모래의 홀을 이용해 이 세계를 어지럽히려는 무리로부터 홀을 지키겠노라고 굳게 다짐했지. 그리하여 용군단의 임무가 탄생하게 된 것이니라.\n\n이 세계를 혼란에 빠뜨리려는 무리들이 4개의 강력한 위상으로 분리된 흐르는 모래의 홀을 복원한다는 것은 거의 불가능한 일이었다... 적어도 나는 그렇게 생각했다만 내가 어리석었다. 지금은 오히려 그 괘씸한 용군단에게 쫓기는 신세가 됐으니...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8520] = {title = "얼라이언스에 비단 붕대 조달!", objective = "아이언포지의 군사 지구에 있는 간호사 스톤필드에게 비단 붕대 20개를 가져가야 합니다.", description = "안퀴라즈 전쟁이 임박함에 따라 우리 병사들에게 필요한 물자가 부족하지 않도록 모든 조치를 취해야 합니다. 우리는 여기서 바로 그런 일을 하고 있지요. 그 중에서 저는 비단 붕대를 모으는 일을 맡고 있습니다.\n\n저를 좀 도와주시겠어요?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8521] = {title = "얼라이언스에 비단 붕대 추가 조달!", objective = "아이언포지의 군사 지구에 있는 간호사 스톤필드에게 비단 붕대 20개를 가져가야 합니다.", description = "또다시 도움을 주시겠다니 정말 친절한 <class>님이시군요. 지금까지 모은 비단 붕대가 $2082w개니까 아직 조금 더 필요한 상황이에요.", progress = "또다시 도움을 주시겠다니 정말 친절한 분이시군요. 지금까지 모인 상당한 수의 비단 붕대를 모았습니다만 아직 더 필요합니다. 다른 비단 붕대 뭉치를 모을 수 있는 방법이 없을까요? 그리곤 붕대를 저에게 가져다주실 수 있는 방법 말입니다. 얼라이언스 연합과 제가 무척 감사하게 생각할 겁니다.", completion = "남을 배려하는 마음이 깊으신 분이군요. 군수 물자 확보에 도움을 주셔서 정말 감사합니다. 당신 같은 분들의 활약에 따라 안퀴라즈 전쟁의 승패가 결정될 겁니다. 이것으로 필요한 비단 붕대가 충분히 확보되었으면 좋겠군요.\n\n다시 한 번 감사 드립니다.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8522] = {title = "얼라이언스에 룬매듭 붕대 조달!", objective = "아이언포지의 군사 지구에 있는 수호자 문셰이드에게 룬매듭 붕대 20개를 가져가야 합니다.", description = "이 전쟁의 득실을 따져 보겠다면 그렇게 하시오, <class>|1이여;여;. 하지만 전쟁은 이미 시작되었소. 주위의 가족과 친구들을 둘러보시오. 그리고 피할 수 없는 전쟁이라면 그들이 전쟁에서 살아남을 수 있도록 그대가 도울 수 있는 최선의 길이 무엇인지 잘 생각해 보시기 바라오.\n\n난 그러기 위해 이곳에서 수단과 방법을 가리지 않고 룬매듭 붕대를 모으고 있소이다. 어떻소, 그대도 룬매듭 붕대를 기부해 주시겠소?", progress = "하루하루 시간만 가고 룬매듭 붕대는 아직도 모자란 실정이오, <class>|1이여;여;. 룬매듭 붕대는 가지고 왔소이까?", completion = "이번 임무에서 보여 준 인내심에 박수를 보내지 않을 수 없구려. 우선 이 붕대부터 정리해 놓고 룬매듭 붕대를 좀 더 모아 주실 수 있는지에 대해 얘기를 나눴으면 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8523] = {title = "얼라이언스에 룬매듭 붕대 추가 조달!", objective = "아이언포지의 군사 지구에 있는 수호자 문셰이드에게 룬매듭 붕대 20개를 가져가야 합니다.", description = "여전히 해결되지 않은 문제에 대해 이렇게 의논할 기회가 또다시 생겼소이다, <class>|1이여;여;. 지난번에 도와준 일에 대해서는 다시 한 번 감사 드리오. 사실, 그대처럼 헌신적으로 도와주는 자들이 그리 많지는 않소이다... 그나저나 아직도 할 일이 더 남아 있소.\n\n룬매듭 붕대를 좀 더 모아 내게 가져다줄 수 있겠소이까?", progress = "여전히 해결되지 않은 문제에 대해 이렇게 의논할 기회가 또다시 생겼소이다, <class>|1이여;여;. 지난번에 도와준 일에 대해서는 다시 한 번 감사 드리오. 사실, 그대처럼 헌신적으로 도와주는 자들이 그리 많지는 않소이다... 그나저나 아직도 할 일이 더 남아 있소.\n\n룬매듭 붕대를 좀 더 모아 내게 가져다줄 수 있겠소이까?", completion = "이번 일로 우리 모두에게 큰 도움이 되었소이다. 그대는 정말 훌륭한 동료가 아닐 수 없구려. 그대의 도움의 손길에 대해 얼라이언스 연합을 대표해서 다시 한 번 감사를 드리는 바입니다. 룬매듭 붕대를 가지고 다시 돌아와서 좀 더 얘기를 나눴으면 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8524] = {title = "얼라이언스에 무지개날개다랑어 구이 공급!", objective = "아이언포지의 군사 지구에 있는 슬리키 개스트로놈에게 무지개날개다랑어 구이 20마리를 가져가야 합니다.", description = "안녕하세요? 제가 만약 '병사들이라고 해서 먹지 않고 살 수 있을까요?'라고 묻는다면 물론 아니라고 대답하시겠죠? 네, 저도 110% 동의합니다! 그럼 우리는 의견이 같다고 할 수 있겠군요. 제가 부탁 드리고 싶은 것은 밖으로 나가 싱싱한 무지개날개다랑어를 낚은 다음 맛있게 요리를 해서 여기로 가져다 달라는 것입니다. 흠, 벌써 군침이 도는군요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8526] = {title = "얼라이언스에 랩터 숯불구이 공급!", objective = "아이언포지의 군사 지구에 있는 사라 새드휘슬에게 랩터 숯불구이 20개를 가져가야 합니다.", description = "잘 지내시나요, <class>님? 곧 벌어질 안퀴라즈 전쟁에 필요한 식량을 모으는 일에 관심이 있으실 걸로 아는데요... 제 아버지께서는 이곳을 돕는 일에 자원 봉사하는 것이 제게 아주 좋은 경험이 될 거라고 생각하셨답니다. 크게 실수하신 거죠. 저는 육식을 좋아하지 않거든요.\n\n어쨌든 괜찮으시다면 랩터 숯불구이를 많이 가져다주시면 좋겠어요. 틀림없이 모든 병사들이 좋아할 테니까요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8527] = {title = "얼라이언스에 랩터 숯불구이 추가 공급!", objective = "아이언포지의 군사 지구에 있는 사라 새드휘슬에게 랩터 숯불구이 20개를 가져가야 합니다.", description = "다시 만나서 반갑네요, <class>님. 이 일이 무척 재미있으신가 봐요. 그래서 드리는 말씀인데 랩터 숯불구이 20개를 더 가져다주실 수 있죠? 좋아요, 잘됐군요. 돌아오시면 그때 뵙기로 해요.", progress = nil, completion = "와! 정말 수완이 대단하시군요. 당신을 보니 저 자신이 한심스럽네요. 어쨌든 모든 얼라이언스를 대신해 감사 드려요. 이 고기들을 보급식량 더미에 가져다 놓도록 할게요. 나중에 다시 찾아오세요. 랩터 숯불구이가 더 필요한지 알아봐 드릴게요. 물론 그때쯤이면 이미 많은 양이 쌓여 냄세가 나기 시작하겠지만 말이죠.", rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8528] = {title = "얼라이언스에 점박이놀래기 공급!", objective = "아이언포지의 군사 지구에 있는 여사냥꾼 스위프트리버에게 점박이놀래기 20마리를 가져가야 합니다.", description = "생선 요리를 모으는 일이 대단치 않게 보일 수도 있겠지만, 유비무환이라고 준비의 중요성을 무시하면 안됩니다, 젊은 <class>님. 병사들도 남들처럼 먹어야 살 수 있으니까... 여기서 우리가 하는 일도 일단 안퀴라즈에서 전쟁이 발발했을 때 병사들에게 필요한 물자를 충분히 공급하기 위해 준비하는 거죠.\n\n그래서 저는 보관하기 쉽고 여러 가지 요리를 만들어 먹을 수 있는 점박이놀래기를 비축하고 있습니다. 점박이놀래기는 다른 바닷고기에서 나는 이상한 냄새도 나지 않죠. 어때요, 점박이놀래기 모으는 일을 도와주시겠어요?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8529] = {title = "얼라이언스에 점박이놀래기 추가 공급!", objective = "아이언포지의 군사 지구에 있는 여사냥꾼 스위프트리버에게 점박이놀래기 20마리를 가져가야 합니다.", description = "아직 도와줄 마음이 있으시다면 다시 한 번 가서 점박이놀래기를 가져다주시면 좋겠습니다. 제 생각에는 지난번 경험을 바탕으로 그때보다 훨씬 쉽고 빠르게 해낼 수 있을 거 같은데... 한번 해보시겠어요?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n얼라이언스 훈장안퀴라즈 전쟁 지원 보급품"},
[8530] = {title = "얼라이언스에 그을린 화산핵 조달!", objective = "던 모로 비행장에 있는 사령관 스트롱해머에게 그을린 화산핵 50개를 가져가야 합니다.", description = "자네의 도움이 필요하네. 화산 심장부에 가면 어떤 돌이 있지. 정확하게 말하면 그을린 화산핵이라는 것인데 안퀴라즈 전쟁을 위해 그 돌이 필요하네. 우리 대장장이와 기술자들 말로는 그 돌을 다양한 용도로 사용할 수 있다고 하는군. 바로 이것이 내가 부탁하려는 것일세. 화산 심장부로 가서 그을린 화산핵을 최대한 많이 모아다 주면 좋겠네. 그리고 원한다면 화산 심장부에 가장 가까운 친구들을 39명까지 데리고 갈 수 있을 것이네.", progress = nil, completion = nil, rewards = nil},
[8532] = {title = "호드에 구리 주괴 조달!", objective = "오그리마 정기의 골짜기에 있는 광부 크롬웰에게 구리 주괴 20개를 가져가야 합니다.", description = "여기 일을 돕겠다니 정말 기쁘기 그지없소. 당신 같은 자는 흔치 않은데... 우선 필요한 게 무엇인지부터 말하겠소. 바로 구리 주괴요! 구리 광석과는 다른 것이지... 직접 제련할 시간도 인력도 부족해서 부탁하는 거요. 우리를 도와주면 당신의 노고가 널리 알려질 거요. 그런데 <class> 당신, 이 일을 처리할 능력은 있는 거요?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n호드 훈장안퀴라즈 전쟁 지원 보급품"},
[8533] = {title = "호드에 구리 주괴 추가 조달!", objective = "듀로타에 있는 광부 크롬웰에게 구리 주괴 20개를 가져가야 합니다.", description = "이렇게 빨리 돌아올 줄이야! <class> 당신, 그러다 진짜 광부가 되는 거 아니오? 방법은 알고 있겠지... 그렇소, 구리 광석을 캐서 주괴로 제련한 다음 내게 가져 오면 되는 거요. 당신에겐 충분한 능력이 있다는 걸 알고 있소이다. 어떻소, 또 한 번 자원해 보겠소?", progress = "이렇게 빨리 돌아올 줄이야! <class> 당신, 그러다 진짜 광부가 되는 거 아니오? 방법은 알고 있겠지... 그렇소, 구리 광석을 캐서 주괴로 제련한 다음 내게 가져 오면 되는 거요. 당신에겐 충분한 능력이 있다는 걸 알고 있소이다. 어떻소, 또 한 번 자원해 보겠소?", completion = "&lt;class&gt;, 당신은 능력을 다시 한번 입증했소. 이 구리 주괴가 적시에 쓰일지 내가 지켜보도록 하겠소. 그런데 우선은 구리 주괴의 수량을 확인하고 정리해두는 것이 급선무로군. 계속 돕고 싶다면 구리 주괴를 더 많이 모아 오시오.", rewards = "다음과 같은 것들을 받습니다:\n\n호드 훈장안퀴라즈 전쟁 지원 보급품"},
[8534] = {title = "하이브조라 정찰 보고서", objective = "하이브조라 안에 있는 세나리온 정찰병 아제넬과 접선한 다음 세나리온 요새에 있는 바람소환사 프라우드혼에게 하이브조라 정찰 보고서를 가지고 돌아가십시오. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 VI를 함께 가져가야 합니다.", description = "우리는 최고의 정찰병들을 실리시드 곤충 집으로 침투시켰습니다. 그중 정찰병 아제넬이 지금까지 며칠 동안 하이브조라에서 실리시드의 동태를 감시해 왔습니다. 그녀를 찾아 그동안의 경과를 기록해 놓은 보고서를 입수해 오십시오. 우린 그 정보를 바탕으로 최대한 신속하게 행동을 취해야 합니다.", progress = "하이브조라 안으로 가면 정찰병 아제넬을 찾을 수 있을 것입니다. 서두르세요, <name>! 귀중한 시간을 낭비해서는 안 됩니다.", completion = "도와주셔서 진심으로 감사합니다. 저는 지금 당장 이 정찰 보고서를 읽어봐야겠군요. 당신은 다음 임무를 수행하러 가셔도 좋습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전술 휘장추가 전술 임무"},
[8535] = {title = "백색 기사단", objective = "백색 기사단을 소환하여 해치운 후 세나리온 요새에 있는 보르 와일드메인에게 보고하십시오. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 IV도 함께 가져가야 합니다.", description = "황혼의망치단과 이들이 숭배하는 고위 정령들이 실리더스에서 수행 중인 우리 작전에 큰 위협이 되고 있습니다. 우리는 안퀴라즈 내부의 새로운 적과 대치 중인 상황이기 때문에 외부의 적에게 병력을 돌릴 여력이 없습니다.\n\n백색 기사단을 소환하여 이들을 해치운 후 보르 와일드메인에게 보고하십시오.", progress = "맡은 임무를 벌써 마치셨습니까, <name>?", completion = "잘했습니다, &lt;name&gt;. 자, 여기 다음 임무를 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전술 휘장전술 임무"},
[8536] = {title = "황색 기사단", objective = "황색 기사단을 소환하여 해치운 후 세나리온 요새에 있는 보르 와일드메인에게 보고하십시오. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 III도 함께 가져가야 합니다.", description = "황혼의망치단과 이들이 숭배하는 고위 정령들이 실리더스에서 수행 중인 우리의 작전에 큰 위협이 되고 있습니다. 현재 안퀴라즈 내부의 새로운 적과 대치 중인 상황이기 때문에 외부의 적에게 병력을 돌릴 여력이 없습니다.\n\n황색 기사단을 소환하여 이들을 해치운 후 보르 와일드메인에게 보고하십시오.", progress = "맡은 임무를 벌써 마치셨습니까, <name>?", completion = "잘했습니다. 자, 여기 다음 임무를 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전술 휘장추가 전술 임무"},
[8537] = {title = "진홍 기사단", objective = "진홍 기사단을 소환하여 해치운 후 세나리온 요새에 있는 보르 와일드메인에게 보고하십시오. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 II도 함께 가져가야 합니다.", description = "황혼의망치단과 이들이 숭배하는 고위 정령들이 실리더스에서 수행 중인 우리 작전에 큰 위협이 되고 있습니다. 우리는 안퀴라즈 내부의 새로운 적과 대치 중인 상황이기 때문에 외부의 적에게 병력을 돌릴 여력이 없습니다.\n\n진홍 기사단을 소환하여 이들을 해치운 후 보르 와일드메인에게 보고하십시오.", progress = "맡은 임무를 벌써 마치셨습니까, <name>?", completion = "잘했습니다, &lt;name&gt;. 자, 여기 다음 임무를 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전술 휘장전술 임무"},
[8538] = {title = "네 명의 군주", objective = "불꽃의 군주, 나락의 군주, 서풍의 군주, 그리고 파편의 군주를 소환할 방법을 찾아 처치한 다음 세나리온 요새에 있는 지휘관 마랄리스에게 보고하십시오. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 V도 함께 가져가야 합니다.", description = "황혼의망치단과 심연의 의회를 연결해주는 매개자가 우리의 예상보다 훨씬 중요한 인물이라는 사실이 밝혀졌습니다.\n\n심연의 군주라는 고위 정령들이 황혼의망치단 이교도들을 조종하는 강력한 배후 세력으로 추정됩니다. 심연의 군주 네 명을 우리 세계로 유인할 방법을 모색하여 해치워야 합니다!\n\n과거에 당신이 보여준 헌신적인 노력과 용기로 이 특별한 임무의 적임자로 선택되었습니다. 이번 도전도 충분히 성공할 수 있으리라고 믿습니다.", progress = "맡은 임무는 모두 마치셨습니까, <name>?", completion = "&lt;name&gt;, 그대는 오늘 의회를 위해 정말 위대한 업적을 세웠소. 그대 덕분에 가장 강력한 적들이 사라졌소. 그런 이유에서 그대를 최고의 용사로 추천하는 바이오.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리우스의 문장"},
[8539] = {title = "목표: 어미 하이브조라", objective = "어미 하이브조라 30마리를 해치운 다음 실리더스 세나리온 요새에 있는 지휘관 마랄리스에게 돌아가서 보고하십시오. 또한, 이 퀘스트를 완료하려면 전투 임무 지령 V도 함께 가져가야 합니다.", description = "하이브조라를 공격하기 위한 지원군 요청이 있었습니다. 당신은 어미 하이브조라를 맡아주십시오. 임무를 마치면 지휘관 마랄리스에게 돌아가 보고하면 됩니다.", progress = "<class>|1이여;여;, 내게 보고할 사항이라도 있소?", completion = "정말 잘하셨소, &lt;name&gt;! 그대는 우리의 동료가 될 자격이 충분하오.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8540] = {title = "경비대에 장화 공급", objective = "실리더스의 세나리온 요새에 있는 경비대장 비쉬 코주스에게 화려한 미스릴 장화 3개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 II도 함께 가져가야 합니다.", description = "세나리온 요새를 수호하는 기병대에 화려한 미스릴 장화가 부족하다고 합니다. 화려한 미스릴 장화를 구하는 즉시 세나리온 요새의 경비대장 비쉬 코주스에게 전달해 주십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8541] = {title = "경비대에 연마석 공급", objective = "실리더스의 세나리온 요새에 있는 경비대장 비쉬 코주스에게 강도 높은 연마석, 견고한 연마석, 단단한 연마석을 각각 10개씩 모아서 가져가야 합니다. 이 임무를 완료하려면 병참 임무 지령 III도 함께 가져가야 합니다.", description = "세나리온 요새 경비대에 연마석이 부족하다고 합니다. 연마석을 구하는 즉시 세나리온 요새의 경비대장 비쉬 코주스에게 전달해 주십시오.", progress = "제게 전달할 물건이 있지 않습니까?", completion = "훌륭하군요. 마침 연마석이 정말 필요하던 상황이었습니다. 정말 수고하셨습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8542] = {title = "호드에 주석 주괴 조달!", objective = "오그리마, 정기의 골짜기에 있는 그런트 마우그에게 주석 주괴 20개를 가져가야 합니다.", description = "록타르! <race>. 당신도 알다시피 호드는 곧 안퀴라즈 전쟁에 참전해 벌레들과 싸우게 될 거요. 대족장님께서는 '준비'라는 것을 먼저 해야한다고 하셨지. 자랑스럽게도 난 여기서 주석 주괴 모으는 일에 뽑혔소. 사실 무기를 연마하고 망치로 방어구 모양을 잡는 일이 더 좋긴 하지만... 그런데 당신 도움이 없으면 제대로 이 일을 해낼 수 없을 것 같군.\n\n그러니까 내 말은 당신이 가서 주석 주괴를 모아 여기로 가지고 오란 말이오. 내가 셀 수 있을 만큼보다 더 많이 필요할 것 같소.", progress = "<class>, 주석 주괴를 얼마만큼 가져왔소? 전쟁이 끝나면 누구라도 붙잡고 셈 공부를 해야겠어...", completion = "흠, 내가 셀 수 있는 만큼의 주석 주괴만 가져온 것 같군. 그렇다고 바보 취급은 마시오! 난 숫자만 세면 머리가 깨질 것 같소. 자, 난 가서 이것들을 쌓아 올려야 하니, 당신은 가서 이번에 가져온 것과 똑같은 물건을 더 많이 가져오도록 하시오.", rewards = "다음과 같은 것들을 받습니다:\n\n호드 훈장안퀴라즈 전쟁 지원 보급품"},
[8543] = {title = "호드에 주석 주괴 추가 조달!", objective = "듀로타에 있는 그런트 마우그에게 주석 주괴 20개를 가져가야 합니다.", description = "좋소. 이제야 심각성을 깨달은 것 같군. 사실 난 전쟁이 시작되기를 기다리느라 좀 날카로워진 상태요. 그러니까, 좀 더 서두르지 않으면 성질을 부릴 수도 있다는 말이오. 연습 삼아 당신에게 화를 내 볼 수도 있겠지.\n\n하하하! 설마 진짜 그럴 리가 있겠소. 그러면 누가 주석 주괴를 조달하려 하겠소?", progress = nil, completion = "트롬카! &lt;name&gt;. 나와 호드를 위해 주석 주괴를 가져왔군. 잘 보관해두겠소. 곧 대장장이들이 와서 전쟁 물자로 만들 거요. 이러한 준비 작업이 모두 끝나면 드디어 우리는 전쟁을 시작하는 거지. 그날이 오면 얼라이언스 애송이 놈들에게 벌레 잡는 법이나 한 수 가르쳐 줍시다.\n\n자, 그럼 가서 주석 주괴를 더 모아 오시오!", rewards = "다음과 같은 것들을 받습니다:\n\n호드 훈장안퀴라즈 전쟁 지원 보급품"},
[8544] = {title = "정복자의 어깨갑옷", objective = "노즈도르무 혈족에게 중립적 평판을 얻고, 안퀴라즈에 있는 안도르고스에게 지휘의 퀴라지 팔보호구, 밤의 우상 2개, 돌 스카라베 5개, 찰흙 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 노즈도르무 혈족으로부터 중립적 이상의 평판을 얻어야 합니다.", description = "필멸의 종족들이 착용하고 있는 화려한 어깨갑옷이 용의 날개를 본뜨려고 한 시도에서 유래했다는 소문이 돌더군요.\n\n퀴라지 최고 지휘관들이 차고 있는 팔보호구를 가지고 오세요. 그럼 네파리안의 날개보다도 무시무시한 어깨갑옷으로 만들어 드릴게요!", progress = "부탁한 재료는 모으셨나요?", completion = "당신이 가져온 재료와 우리가 퀴라지를 해치우고 얻은 비늘로 이 어깨갑옷을 만들었어요. 필멸의 존재여, 이 어깨갑옷이 당신을 지켜주고 적에게는 공포를 안겨주기를...", rewards = "다음과 같은 것들을 받습니다:\n\n정복자의 어깨갑옷"},
[8545] = {title = "호드에 미스릴 주괴 조달!", objective = "오그리마의 정기의 골짜기에 있는 정예수호병 티키라에게 미스릴 주괴 20개를 가져가야 합니다.", description = "<class>|1이여;여;, 전쟁이 곧 시작될 텐데 우리가 할 수 있는 일은 준비뿐입니다. 그게 당신과 제가 서로 도울 수 있는 일이기도 하고요. 아시다시피 전 미스릴 주괴를 모아야 합니다. 호드에 필요한 전쟁 물자를 모두 만들 수 있을 만큼이 필요한데 아직 다 모으지 못했어요!\n\n그래서 말인데 당신이 좀 도와주셨으면 해요. 미스릴 광석을 구해 주괴로 제련하면 된답니다. 호드를 위해 그 정도 일은 해 줄 수 있겠지요?", progress = "안퀴라즈 전쟁에 필요한 미스릴 주괴를 모두 모은다면 정말 좋겠군. 당신... 그래서 돌아온 거지요? 제 미스릴 주괴는 어디 있나요?", completion = "이 정도면 당신이나 저나 꽤 괜찮은 출발이로군요. 미스릴 주괴 더미에 20개를 추가하고 목록을 확인해야겠어요. 모두 전쟁에 꼭 필요한 물자를 만드는 데 쓰일 겁니다.\n\n참, 눈치채셨을지도 모르지만 미스릴 주괴가 훨씬 더 많이 필요할 것 같습니다. 꼭 다시 절 찾아주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n호드 훈장안퀴라즈 전쟁 지원 보급품"},
[8546] = {title = "호드에 미스릴 주괴 추가 조달!", objective = "이렇게 다시 만나 반갑습니다. 예전 일도 고맙지만 절 또 한 번 도와주셔야겠습니다. 전쟁에 쓸 미스릴 주괴가 더 필요해요. 그래야 안퀴라즈에서 해충을 박멸하는 데 사용할 갑옷이며 무기 등을 충분히 만들 수 있을 테니까요.\n\n당신이 우리의 진정한 친구라면 미스릴 주괴를 좀 더 가져다주세요. 목표량을 채울 때까지는 얼마든지 더 받겠어요. 그런데 지금 가지고 있는 건 없나요?", description = nil, progress = "이렇게 다시 만나 반갑습니다. 예전 일도 고맙지만 절 또 한 번 도와주셔야겠습니다. 전쟁에 쓸 미스릴 주괴가 더 필요해요. 그래야 안퀴라즈에서 해충을 박멸하는 데 사용할 갑옷이며 무기 등을 충분히 만들 수 있을 테니까요.\n\n당신이 우리의 진정한 친구라면 미스릴 주괴를 좀 더 가져다주세요. 목표량을 채울 때까지는 얼마든지 더 받겠어요. 그런데 지금 가지고 있는 건 없나요?", completion = "정말 훌륭합니다, &lt;name&gt;! 20개가 또 모였으니 목표량에도 성큼 다가섰고, 전쟁 물자도 더 많이 만들 수 있겠어요. 호드에서 제대로 된 곳에 사용하는지 제가 꼭 지켜볼 겁니다. 미스릴 주괴를 더 구하거든 꼭 제게 가져오세요.", rewards = "다음과 같은 것들을 받습니다:\n\n호드 훈장안퀴라즈 전쟁 지원 보급품"},
[8547] = {title = "환영합니다!", objective = "매날개 광장에 있는 마르실라 돈스타에게 매날개 광장 선물교환권을 가져가야 합니다.", description = "월드 오브 워크래프트 세계에 오신 것을 환영합니다!\n\n월드 오브 워크래프트 소장판을 구입해 주신 데 대한 감사의 표시로 작은 선물을 준비했습니다. 매날개 광장에 있는 마르실라 돈스타에게 이 선물교환권을 전해 주면, 함께 퀘스트를 수행하고 모험을 떠날 작은 동반자를 선물로 받으실 수 있습니다.\n\n다시 한 번 감사의 말씀을 드리며 월드 오브 워크래프트에서 즐거운 모험을 하시기 바랍니다!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n저글링 목줄판다 목걸이디아블로 소환석"},
[8548] = {title = "지원자의 전투장비", objective = "실리더스의 세나리온 요새에 있는 바르구스에게 세나리온 전투 휘장 5개, 세나리온 병참 휘장 3개, 세나리온 전술 휘장 7개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에 대한 약간 우호적 이상의 평판을 얻어야 합니다.", description = "<name>, 그대가 세나리온 요새를 대신하여 전투, 병참, 전술 임무를 수행하고 받는 휘장은 단순한 장식용이 아닙니다.\n\n그 휘장을 계속 모으는 것이 좋을 겁니다. 그대가 휘장을 가져와 우리에 대한 충성심을 보인다면 세나리온 의회의 굳건한 동맹을 위해 아껴 두었던 전투 장비를 드리지요.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n대지력의 장갑대지 격노의 고리대지매듭 망토"},
[8549] = {title = "호드에 평온초 꽃잎 조달!", objective = "오그리마의 정기의 골짜기에 있는 약초채집사 프라우드페더에게 평온초 꽃잎 20개를 가져가야 합니다.", description = "모든 세대는 꼭 한 번씩은 큰 시련을 겪게 되어 있다는 말이 있습니다. 안퀴라즈 전쟁이 우리 세대의 용기를 시험하는 혹독한 시련이 될까 두렵답니다. 그러니 우리는 전쟁에 대비를 해야죠. 그리고 그런 과정 속에서 자신의 진정한 가치를 발견해야 합니다.\n\n전 호드가 전쟁에 쓸 물약을 만들 수 있도록 평온초 꽃잎을 최대한 많이 모으는 일을 하고 있습니다. 그대가 여기 온 이유가 절 돕기 위한 것이기를... 만약 그렇다면 평온초 꽃잎을 되도록 많이 가져다주십시오. 고귀한 <class>|1이여;여;, 절 도와주시겠습니까?", progress = "<class>|1이여;여;, 벌써 평온초 꽃잎을 구해 왔나요?", completion = "이것으로 전쟁 준비에 한층 더 박차를 가할 수 있겠어요. 정말 고맙습니다. 가져오신 평온초 꽃잎은 꼭 유용하게 쓰겠습니다. 그리고 고생해서 꽃잎을 조달해준 그대의 공로도 널리 알려야지요. &lt;name&gt;, 괜찮다면 평온초 꽃잎을 좀 더 구해다 주길 바랍니다. 우리가 다시 만날 때까지 대지모신의 가호가 함께하기를...", rewards = "다음과 같은 것들을 받습니다:\n\n호드 훈장안퀴라즈 전쟁 지원 보급품"},
[8550] = {title = "호드에 평온초 꽃잎 추가 조달!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n호드 훈장안퀴라즈 전쟁 지원 보급품"},
[8551] = {title = "선장의 상자", objective = "무법항에 있는 허클베리 스모츠에게 스모츠의 상자를 가져가야 합니다.", description = "난 여기에서 칼림도어의 톱니항까지 배로 항해하곤 했다네. 그래도 꽤 유명한 선장이었다고. 그런데...\n\n저주받은 바다 거인들이 내 인생을 망쳐 놓고 말았어! 거인들이 내 배를 박살내고 부하들을 모두 죽였지. 난 겨우 구명정에 몸을 맡기고 이 무법항까지 흘러 왔다네. 그 거인들 중 고를라쉬라는 놈이 내 상자를 훔쳐 가면서 그걸 코담뱃갑으로 쓸 거라더군. 뻔뻔한 놈 같으니!\n\n들리는 소문에 의하면 고를라쉬는 이곳에서 동쪽에 있는 해안을 어슬렁거린다고 하네. 놈을 찾아서 내 상자를 되찾아 주게! 그렇게 해 준다면 정말 고맙겠군그래.", progress = "이보게! 고를라쉬는 찾았나? 그 상자는 내가 가장 좋아하는 거였다네. 게다가 그 안에는 내가 가장 아끼는 보물들이 들어 있는 숨겨진 칸이 있다고!", completion = "찾았군! 오, 이 얼마나 기쁜 날인가! 고맙네. 상자를 찾으니 이제 화가 좀 가라앉는 것 같구먼.\n\n하지만 내 복수는 아직 끝나지 않았네...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n혈사단 팔보호구"},
[8552] = {title = "이니셜이 새겨진 머리띠", objective = "이니셜이 새겨진 머리띠를 주인에게 돌려줘야 합니다.", description = "이 멋진 머리띠에는 가장자리를 따라 \"HS\" 라는 머리글자가 수놓아져 있습니다.", progress = "반갑네. 내게 무슨 볼일이라도 있나?", completion = "내 머리띠를 찾았다고? 그럼... 바다 거인 모크라쉬를 죽였단 말인가? 만세!\n\n그 비열한 악당 녀석이 죽었다니 이보다 더 기쁠 수가 없군그래. 모크라쉬는 내 배를 박살내고 선원들을 죽인 바다 거인 셋 중 하나였네. 그것도 세 번이나 말이야.\n\n자네는 정말 뛰어난 &lt;class&gt;|1이로군;로군;.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8553] = {title = "선장의 커틀라스", objective = "스프로거와 대화해야 합니다.", description = "그 거인들에게 내 첫 번째 배를 잃은 후, 난 다른 배를 샀고 스모츠의 복수라는 이름을 붙였지. 그리고 선원을 모으고 식량을 싣고는 그 악당 놈들을 찾아 떠났다네. 결국 놈들을 찾긴 했지만 또다시 당하고 말았지. 놈은 스모츠의 복수호를 박살내고 내 두 번째 선원들을 모두 죽였다네. 그리고 난 또다시 구명정에 의지하는 신세가 되었지.\n\n이번에는 네골라쉬라는 거인 놈이 내 커틀라스를 훔쳐가 버렸네. 네골라쉬를 찾아 내 커틀라스를 되찾아 주게나.\n\n스프로거와 얘기해 보게. 저 친구는 스모츠의 복수호의 요리사였는데 마지막 공격에서 살아남았으니까 그가 거인 찾는 걸 도와줄 것이야.", progress = nil, completion = "안녕하세요, 안녕하세요! 당신이 네골라쉬를 찾으러 갈 거라고 선장님이 말씀하시던데요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8554] = {title = "네골라쉬와의 대적", objective = "선장 스모츠의 구명정에 대머리수리 날개 구이 10개와 밀림포도나무 와인 5병을 가져가야 합니다.\n\n네골라쉬를 처치하고 가시덤불 골짜기에 있는 선장 스모츠에게 스모츠의 커틀라스를 가져가십시오.", description = "네골라쉬는 늘 굶주려 있는 거인이에요.\n\n그 거인들이 우리 배를 파괴했을 때, 네골라쉬는 곧장 제 주방으로 쳐들어 왔었죠. 녀석은 다른 거인처럼 선원들로 배를 채우려 하지 않았어요. 네골라쉬는 와인과... 내가 만든 바베큐를 원하고 있었어요. 그건 제 특별 요리인 데다 재료를 구하려면 황야의 땅까지 가야 하는데 말이죠!\n\n그 거인을 유인하려면 와인과 대머리수리 날개가 많이 필요할 거예요. 여기에서 해안을 따라 남동쪽에 있는 낡은 구명정에 음식을 실어 놓으세요. 네골라쉬가 그 음식 냄새를 맡으면 반드시 나타날 거예요!", progress = "내 커틀라스는 찾아 왔나?", completion = "네골라쉬에게서 내 커틀라스를 찾아 오다니! 정말 믿을 수 없군그래! 자네를 만난 건 내게 더할 수 없는 행운일세. 어느 하나 실수라는 걸 모르는군!\n\n고맙네! 그리고 내가 새 배를 갖게 되면, 자네가 바다를 항해해야 할 일이 있으면 내 배로 정중히 모시도록 하지.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n스모츠의 나침반"},
[8555] = {title = "용군단의 임무", objective = "에라니쿠스, 밸라스트라즈, 아주어고스... 필멸의 존재여, 그대는 필시 이 용들에 대해 알고 있다. 그러니 이들이 우리 세계의 파수꾼으로서 중요한 역할을 해 왔다는 것은 결코 우연이 아니니라.\n\n불행히도 고대 신들의 추종자 아니면 그들을 친구라고 부르는 자들의 배신으로 인해 우리의 수호자들에게 비극이 일어났다. 물론 내 어리석음도 어느 정도 잘못이 있다는 것을 부인할 수는 없지만... 이 일로 그대의 종족에 대한 나의 불신은 그만큼 깊어졌느니라.\n\n그들을 찾아라... 그리고 최악의 상황에 대비하도록 하라.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8556] = {title = "굴하지 않는 힘의 인장", objective = "실리더스에 있는 바람소환사 예센드라에게 권위의 퀴라지 반지 1개, 미명석 우상 2개, 청동 스카라베 5개, 상아 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에 우호적 평판을 얻어야 합니다.", description = "퀴라지 부관들이 끼고 있는 반지가 그들에게 가공할 능력을 준다는 소문이 있어요. 이론상 그들이 끼고 있는 오염된 보석을 보다 순수한 재료로 바꾸면 오염되지 않은 반지를 만들 수 있을 겁니다.\n\n질이 좋아야 하니까, 음... 퀴라지 우상을 장식하고 있는 보석이 가장 적당할 것 같아요.\n\n제게 반지와 우상을 가져다주시면 그대에게 강력한 반지를 만들어 드리도록 하지요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n굴하지 않는 힘의 인장"},
[8557] = {title = "굴하지 않는 힘의 망토", objective = "실리더스에 있는 케일 스위프트클로에게 전쟁의 퀴라지 망토 1개, 마노 우상 2개, 은 스카라베 5개, 뼈 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에서 매우 우호적 이상의 평판도 얻어야 합니다.", description = "우리의 안퀴라즈 공격을 도와주고 있다니 정말 기쁘오. 당신에게 적의 공격을 방어하는 데 도움이 될 만한 물건을 주고 싶소.\n\n퀴라지 망토가 필요하오. 물론 당신에게 맞게 크기를 조절해 주리다. 그리고 그에 어울리는 걸쇠를 만드는 데 사용할 우상과 스카라베도 있어야 하오.\n\n절대 실망시키지 않겠다고 약속하겠소.", progress = "망토에 필요한 재료는 가지고 오셨소?", completion = "좋소... 이 망토는 아주 깨끗하군.\n\n받으시오. 퀴라지의 더러운 마법으로부터 당신을 보호해 줄 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n굴하지 않는 힘의 망토"},
[8558] = {title = "굴하지 않는 힘의 도끼", objective = "실리더스에 있는 감시자 하로에게 못박힌 퀴라지 자루 1개, 설화석 우상 2개, 수정 스카라베 5개, 돌 스카라베 5개를 가져가야 합니다. 또한 이 퀘스트를 완료하려면 세나리온 의회에서 확고한 동맹의 평판도 얻어야 합니다.", description = "퀴라지와 그들의 부하들은 매우 희귀하고 가장 우수한 재료들로 만든 무기를 사용합니다. 그 재료란 거대한 고대 생물의 뼈, 땅속 깊은 곳에서 채취한 보석, 순수하고 강한 금속이죠.\n\n퀴라지의 유물은 보기만 해도 그 부서지고 용해된 잔해들로 제 솜씨를 마음껏 발휘하고 싶은 충동이 느껴집니다. 세나리온 의회에 대한 당신의 충성을 증명해 보인다면 최고의 퀴라지 재료들로 강력한 무기를 만들어 드리겠습니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n굴하지 않는 힘의 도끼"},
[8559] = {title = "정복자의 경갑", objective = "안퀴라즈에 있는 칸드로스트라즈에게 지휘의 퀴라지 팔보호구, 전쟁의 우상 2개, 상아 스카라베 5개, 황금 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 노즈도르무 혈족으로부터 중립적 이상의 평판도 얻어야 합니다.", description = "퀴라지 마법은 고대로부터 전해오는 강력한 마법입니다. 그러한 마법이 걸린 퀴라지 무기 중에는 용조차 놀라게 할 만큼 강력한 것도 있지요.\n\n저에게 지휘의 퀴라지 팔보호구와 몇 가지 다른 재료를 가져다주시면 강력한 장화 한 켤레를 만들어 드리겠습니다.\n\n적과 싸울 때 아주 유용할 것입니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n정복자의 경갑"},
[8560] = {title = "정복자의 다리갑옷", objective = "안퀴라즈 안에 있는 칸드로스트라즈에게 온전한 아우로의 가죽, 죽음의 우상 2개, 청동 스카라베 5개, 상아 스카라베 5개를 가져가야 합니다. 또한, 이 임무를 완수하려면 노즈도르무 혈족으로부터 약간 우호적 이상의 평판을 얻어야 합니다.", description = "필멸의 존재여, 우리 혈족에게 당신의 가치를 증명해 보이고 싶습니까? 좋습니다. 우리는 서로 도움이 될 수도 있을 것 같군요.\n\n아우로라고 하는 고대의 미늘벌레는 전설적인 힘을 가진 존재입니다. 생명을 조롱하기 위해 고대 신이 직접 만든 존재라는 소문도 있습니다.\n\n아우로의 가죽은 정말 불가사의합니다... 거의 무적이라 할 만큼 두껍지만 유연하기도 해서 아주 작은 생물처럼 민첩하고 우아하게 움직일 수 있게 해주죠.\n\n제게 아우로의 가죽과 다른 재료 몇 가지를 가져다주시면 강력한 다리보호구를 만들어 드리겠습니다.", progress = "부탁한 재료는 가지고 오셨습니까?", completion = "바로 이겁니다... 미늘벌레의 가죽은 강력한 보호구를 만드는 데 이용할 수 있죠. 우리가 여기까지 진군하면서 해치운 퀴라지의 몸에서 가장 단단한 부분과 결합하면 아주 훌륭한 보호구가 탄생하는 것입니다. 부디 이 보호구가 저 안에서 기다리고 있는 끔찍한 공포와 맞서 싸울 당신에게 도움이 되기를 바랍니다!", rewards = "다음과 같은 것들을 받습니다:\n\n정복자의 다리갑옷"},
[8561] = {title = "정복자의 왕관", objective = "안퀴라즈에 있는 안도르고스에게 베크닐라쉬의 관, 태양의 우상 2개, 돌 스카라베 5개, 수정 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 노즈도르무 혈족으로부터 약간 우호적 이상의 평판도 얻어야 합니다.", description = "쌍둥이 제왕... 그들의 끝없는 속삭임이 저의 정신을 천천히 갉아먹고 있어요. 그들은 날 조롱하고 있죠. 자신들의 영역에 다가갈 수조차 없어 아리고스 오빠를 구해내지 못하는 비참한 날...\n\n제 눈에는 강력한 왕관을 쓰고 소름끼치는 웃음을 띤 그들의 얼굴이 보입니다. 반드시 복수하고 말 거예요... 전 퀴라지의 힘을 상징하는 물건들을 우리가 쓸 수 있도록 바꾸려고 합니다.\n\n제가 부탁하는 재료들을 가져다주세요. 그 무엇과도 비교할 수 없는 강력한 힘을 지닌 관으로 만들어 드리겠어요.", progress = "부탁한 재료는 가지고 오셨나요?", completion = "성공하셨군요! 쌍둥이 제왕의 속삭임이 멈췄어요.\n\n당신의 용맹과 헌신에 대한 보상으로 이걸 드릴게요. 퀴라지가 보기만 해도 무서워 벌벌 떨 겁니다... 이걸 보면 죽은 지휘관들과 그들을 해치운 어느 필멸의 존재에 대한 기억이 떠오를 테니까요.", rewards = "다음과 같은 것들을 받습니다:\n\n정복자의 왕관"},
[8562] = {title = "정복자의 흉갑", objective = "안퀴라즈 안에 있는 베스세라에게 고대신의 껍질, 전쟁의 우상 2개, 은 스카라베 5개, 뼈 스카라베 5개를 가져가야 합니다. 이 퀘스트를 완료하려면 노즈도르무 혈족에게 우호적 평판을 얻어야 합니다.", description = "안퀴라즈 지하에는 입에 담기조차 두려운 고대 신이 잠들어 있어요. 지금 그가 서서히 깨어나고 있습니다. 이제 아제로스를 기다리는 끔찍한 운명이 찾아올 겁니다. 며칠이 됐든 몇 년이 됐든 고대의 힘을 지닌 존재들에게 그 시간은 아무런 의미가 없습니다.\n\n별들의 항로가 고대 신의 운명과 함께하는 날, 그는 살아 있는 모든 존재를 향해 무시무시한 분노를 터뜨릴 겁니다. 그날이 오기 전에 그를 제거할 방법을 모색해야 합니다.\n\n고대 신을 없애고 그 껍질 한 조각을 제게 가져다주세요. 지금까지 그 어떤 필멸의 존재도 입어 보지 못한... 신을 처단한 이에게 걸맞은 그런 갑옷을 드리겠어요!", progress = "쑨은 안퀴라즈에 있는 자신의 거처에 잠을 자고 있어요.", completion = "그대가 다시 돌아올 수 있을 거라고 전혀 기대하지 않았습니다. 그대는 대부분의 불멸의 존재들의 숙명보다 더 큰 숙명을 완수해 냈군요.\n\n쑨을 해치웠으니 그대는 아제로스를 구했을 뿐만 아니라 그대가 이해할 수 없는 우주적 사건들에도 큰 영향을 끼친 셈입니다.\n\n그대의 업적에 따르는 영광과 기대에 대한 증표이니 이 흉갑을 받으세요.\n\n신을 처단한 영웅이여, 이 흉갑의 힘이 그대를 기다리는 새로운 도전에 도움이 되기를!", rewards = "다음과 같은 것들을 받습니다:\n\n정복자의 흉갑"},
[8563] = {title = "흑마법사 훈련", objective = "선스트라이더 섬의 태양 첨탑 안에 있는 상급 흑마법사인 소환사 텔리라리엔과 대화해야 합니다.자신의 직업에 맞게 실력을 쌓아 발전하다 보면 상급자로부터 훈련을 받고 싶을 때가 올 것입니다. 이곳 선스트라이더 섬에 있는 젊은 흑마법사라면 소환사 텔리라리엔이라는 상급 흑마법사에게 가서 수련을 받을 수 있습니다. 텔리라리엔에게 가서 어떤 훈련을 받을 수 있는지 알아보십시오. 공짜로 가르쳐주지는 않을 테니까 돈을 좀 챙겨서 가십시오.\n\n선스트라이더 섬의 다른 상급자들과 마찬가지로 소환사 텔리라리엔은 태양 첨탑 하층에 있습니다.퀘스트 완료 시 보상:\n\n", description = "자신의 직업에 맞게 실력을 쌓아 발전하다 보면 상급자로부터 훈련을 받고 싶을 때가 올 것입니다. 이곳 선스트라이더 섬에 있는 젊은 흑마법사라면 소환사 텔리라리엔이라는 상급 흑마법사에게 가서 수련을 받을 수 있습니다. 텔리라리엔에게 가서 어떤 훈련을 받을 수 있는지 알아보십시오. 공짜로 가르쳐주지는 않을 테니까 돈을 좀 챙겨서 가십시오.\n\n선스트라이더 섬의 다른 상급자들과 마찬가지로 소환사 텔리라리엔은 태양 첨탑 하층에 있습니다.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[8564] = {title = "사제 훈련", objective = "선스트라이더 섬의 태양 첨탑 안에 있는 상급 여사제 아레나와 대화해야 합니다.자신의 직업에 맞게 실력을 쌓아 발전하다 보면 상급자들의 훈련을 받고 싶을 때가 올 것입니다. 이곳 선스트라이더 섬에 있는 젊은 사제라면 여사제 아레나라는 상급 사제에게 수련을 받아야 합니다. 아레나에게 가서 어떤 훈련을 받을 수 있는지 알아보십시오. 공짜로 가르쳐주지는 않을 테니까 돈을 좀 챙겨서 가십시오.\n\n선스트라이더 섬의 다른 상급자들과 마찬가지로 여사제 아레나는 태양 첨탑 하층에 있습니다.퀘스트 완료 시 보상:\n\n", description = "자신의 직업에 맞게 실력을 쌓아 발전하다 보면 상급자들의 훈련을 받고 싶을 때가 올 것입니다. 이곳 선스트라이더 섬에 있는 젊은 사제라면 여사제 아레나라는 상급 사제에게 수련을 받아야 합니다. 아레나에게 가서 어떤 훈련을 받을 수 있는지 알아보십시오. 공짜로 가르쳐주지는 않을 테니까 돈을 좀 챙겨서 가십시오.\n\n선스트라이더 섬의 다른 상급자들과 마찬가지로 여사제 아레나는 태양 첨탑 하층에 있습니다.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
