[8687] = {title = "목표: 땅꾼 하이브조라", objective = "땅꾼 하이브조라 30마리를 해치운 다음 실리더스 세나리온 요새에 있는 지휘관 마랄리스에게 돌아가 보고하십시오. 또한, 이 퀘스트를 완료하려면 전투 임무 지령 VII도 함께 가져가야 합니다.", description = "하이브조라를 공격하기 위해 증원군을 요청했습니다. 당신은 땅꾼 하이브조라를 맡아 주십시오. 임무를 마치면 지휘관 마랄리스에게 돌아가서 보고하시면 됩니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8688] = {title = "장로 윈드런", objective = "하늘에 떠 있는 수많은 별들을 들여다보면 이 세상의 신비로운 일들에 대한 해답이 담겨있듯이, 자네는 힘과 지혜 그리고 행운에 이르는 진리를 발견하였는가 자네는 진리를 발견하였는가?", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n활 쏘기\n\n다음과 같은 것들을 받습니다:\n\n선조의 주화"},
[8689] = {title = "무한한 지혜의 외투", objective = "실리더스에 있는 케일 스위프트클로에게 전쟁의 퀴라지 망토 1개, 벽옥 우상 2개, 황금 스카라베 5개, 찰흙 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에서 매우 우호적 평판도 얻어야 합니다.", description = "우리의 안퀴라즈 공격을 도와주고 있다니 정말 기쁘오. 당신에게 적의 공격을 방어하는 데 도움이 될 만한 물건을 주고 싶소.\n\n퀴라지 망토가 필요하오. 물론 당신에게 맞게 크기를 조절해 주리다. 그리고 그에 어울리는 걸쇠를 만드는 데 사용할 우상과 스카라베도 있어야 하오.\n\n절대 실망시키지 않겠다고 약속하겠소.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n무한한 지혜의 외투"},
