[8696] = {title = "선도자의 망토", objective = "실리더스에 있는 케일 스위프트클로에게 제왕의 퀴라지 망토 1개, 미명석 우상 2개, 돌 스카라베 5개, 수정 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에서 매우 우호적 평판도 얻어야 합니다.", description = "우리의 안퀴라즈 공격을 도와주고 있다니 정말 기쁘오. 당신에게 적의 공격을 방어하는 데 도움이 될 만한 물건을 주고 싶소.\n\n퀴라지 망토가 필요하오. 물론 당신에게 맞게 크기를 조절해 주리다. 그리고 그에 어울리는 걸쇠를 만드는 데 사용할 우상과 스카라베도 있어야 하오.\n\n절대 실망시키지 않겠다고 약속하겠소.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n선도자의 망토"},
[8697] = {title = "무한한 지혜의 반지", objective = "실리더스에 있는 바람소환사 예센드라에게 의식의 퀴라지 반지 1개, 흑요석 우상 2개, 은 스카라베 5개, 뼈 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에 우호적 평판을 얻어야 합니다.", description = "퀴라지 부관들이 끼고 있는 반지가 그들에게 가공할 능력을 준다는 소문이 있어요. 이론상 그들이 끼고 있는 오염된 보석을 보다 순수한 재료로 바꾸면 오염되지 않은 반지를 만들 수 있을 겁니다.\n\n질이 좋아야 하니까, 음... 퀴라지 우상을 장식하고 있는 보석이 가장 적당할 것 같아요.\n\n제게 반지와 우상을 가져다주시면 그대에게 강력한 반지를 만들어 드리도록 하지요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n무한한 지혜의 반지"},
[8698] = {title = "휘몰아치는 폭풍의 반지", objective = "실리더스에 있는 바람소환사 예센드라에게 권위의 퀴라지 반지 1개, 단사 우상 2개, 은 스카라베 5개, 뼈 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에 우호적 평판을 얻어야 합니다.", description = "퀴라지 부관들이 끼고 있는 반지가 그들에게 가공할 능력을 준다는 소문이 있어요. 이론상 그들이 끼고 있는 오염된 보석을 보다 순수한 재료로 바꾸면 오염되지 않은 반지를 만들 수 있을 겁니다.\n\n질이 좋아야 하니까, 음... 퀴라지 우상을 장식하고 있는 보석이 가장 적당할 것 같아요.\n\n제게 반지와 우상을 가져다주시면 그대에게 강력한 반지를 만들어 드리도록 하지요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n휘몰아치는 폭풍의 반지"},
