[8704] = {title = "보이지 않는 길의 인장", objective = "실리더스에 있는 바람소환사 예센드라에게 의식의 퀴라지 반지 1개, 호박석 우상 2개, 황금 스카라베 5개, 찰흙 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에 우호적 이상의 평판을 얻어야 합니다.", description = "퀴라지 부관들의 반지가 가공할 능력을 준다는 소문이 있어요. 이론상 그들이 끼고 있는 오염된 보석을 더욱 순수한 재료로 바꾸면 오염되지 않은 반지를 만들 수 있을 겁니다.\n\n질이 좋아야 하니까, 음... 퀴라지 우상을 장식하고 있는 보석이 가장 적당할 것 같아요.\n\n제게 반지와 우상을 가져다주시면 그대에게 강력한 반지를 만들어 드리도록 하지요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n선도자의 인장"},
[8705] = {title = "무한한 지혜의 망치", objective = "실리더스에 있는 감시자 하로에게 화려한 퀴라지 자루 1개, 미명석 우상 2개, 청동 스카라베 5개, 상아 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회로부터 확고한 동맹의 평판을 얻어야 합니다.", description = "퀴라지와 그들의 부하들은 매우 희귀하고 가장 우수한 재료들로 만든 무기를 사용합니다. 그 재료란 거대한 고대 생물의 뼈, 땅속 깊은 곳에서 채취한 보석, 순수하고 강한 금속이죠.\n\n퀴라지의 유물은 보기만 해도 그 부서지고 용해된 잔해들을 이용해 제 솜씨를 마음껏 발휘하고 싶은 충동이 느껴집니다. 세나리온 의회에 대한 당신의 충성을 증명해 보인다면 최고의 퀴라지 재료들로 강력한 무기를 만들어 드리겠습니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n무한한 지혜의 망치"},
[8706] = {title = "휘몰아치는 폭풍의 망치", objective = "실리더스에 있는 감시자 하로에게 못박힌 퀴라지 자루 1개, 호박석 우상 2개, 상아 스카라베 5개, 청동 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에서 확고한 동맹의 평판을 얻어야 합니다.", description = "퀴라지와 그들의 부하들은 매우 희귀하고 가장 우수한 재료들로 만든 무기를 사용합니다. 그 재료란 거대한 고대 생물의 뼈, 땅속 깊은 곳에서 채취한 보석, 순수하고 강한 금속이죠.\n\n퀴라지의 유물은 보기만 해도 그 부서지고 용해된 잔해들로 제 솜씨를 마음껏 발휘하고 싶은 충동이 느껴집니다. 세나리온 의회에 대한 당신의 충성을 증명해 보인다면 최고의 퀴라지 재료들로 강력한 무기를 만들어 드리겠습니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n휘몰아치는 폭풍의 망치"},
[8707] = {title = "밝혀진 비밀의 칼날", objective = "실리더스에 있는 감시자 하로에게 화려한 퀴라지 자루 1개, 흑요석 우상 2개, 은 스카라베 5개, 뼈 스카라베 5개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 세나리온 의회에서 확고한 동맹의 평판을 얻어야 합니다.", description = "퀴라지와 그들의 부하들은 매우 희귀하고 가장 우수한 재료들로 만든 무기를 사용합니다. 그 재료란 거대한 고대 생물의 뼈, 땅속 깊은 곳에서 채취한 보석, 순수하고 강한 금속이죠.\n\n퀴라지의 유물은 보기만 해도 그 부서지고 용해된 잔해들로 제 솜씨를 마음껏 발휘하고 싶은 충동이 느껴집니다. 세나리온 의회에 대한 당신의 충성을 증명해 보인다면 최고의 퀴라지 재료들로 강력한 무기를 만들어 드리겠습니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n밝혀진 비밀의 칼날"},
