[8728] = {title = "좋은 소식과 나쁜 소식", objective = "타나리스에 있는 나라인 수스팬시가 아케이나이트 주괴 20개, 엘레멘티움 광석 10개, 아제로스 다이아몬드 10개, 푸른 사파이어 10개를 가져다 달라고 부탁했습니다.", description = "예상보다 좀 오래 걸렸군요. 이제 이 장부에 뭐라고 적혀 있는지 좀 볼까요?\n\n<조용히 장부를 읽으며 가끔씩 낮은 소리로 중얼거리는 나라인>\n\n음, 좋은 소식 하나와 나쁜 소식 하나가 있군요. 좋은 소식은 99% 확신하는데 당신에게 필요한 아케이나이트 부표를 내가 만들 수 있다는 것입니다. 물론 이 확신은 나쁜 소식에 따라 얼마든지 바뀔 수 있지만 말이죠.\n\n나쁜 소식은 부표를 만들려면 아케이나이트와 엘레멘티움 광석 그리고 희귀한 보석이 많이 필요하다는 것입니다.\n\n필요한 재료를 가지고 오면 부표를 만들어 드리도록 하죠.", progress = "아케이나이트 부표는 저절로 만들어지는 게 아니에요. 그리고 돈을 빌려서 어떻게 해 볼 생각은 아예 마세요.", completion = "약속을 했으니 만들어는 드리죠. 하지만 지금 어떤 일을 하려는 건지 분명히 알아야 해요. 작은 물고기들을 모으려다가 엄청난 화를 입을 수 있어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8729] = {title = "넵튤론의 분노", objective = "아즈샤라의 폭풍의 만에 있는 회오리치는 소용돌이에서 아케이나이트 부표를 사용해야 합니다.", description = "제가 한 가지 나쁜 소식에 대해 말했던가요? 녀석의 이름은 식인아귀라고 합니다. 크기가 30미터 정도이고 파괴력이 엄청나 닥치는 대로 죽이죠. 제가 이 얘기는 깜빡 잊었던 것 같군요.\n\n저의 뛰어난 통찰력에 의하면 당신은 이 부표를 던지기에 가장 좋은 장소가 아즈샤라 해안에 있는 폭풍의 만이라는 걸 알게 될 겁니다.\n\n난파선이 널려 있는 곳에서 회오리치는 소용돌이를 찾아보세요. 말이 나왔으니 말입니다만, 동료와 같이 가시는 게 좋을 겁니다.\n\n만약 기적적으로 성공한다면 파란색 홀 파편을 가지고 아나크로노스에게 가도록 하세요.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n얼음 심연의 고리암흑 냉기의 로브\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8730] = {title = "네파리우스의 타락", objective = "네파리안을 해치우고 붉은색 홀 파편을 되찾아 타나리스의 시간의 동굴에 있는 아나크로노스에게 돌아가십시오. 5시간 내에 임무를 완수해야 합니다.", description = "그대가 용사인가? 내가 파편을 맡은 지 천 년이라는 시간이 흘렀다. 그리고 지금 나는 내 일생에 있어서 가장 지독한 암흑 속에 빠져 있기에 누군가 나를 이 암흑에서 구해 주어야 한다... 하지만 고통 없는 비극은 비극이라고 할 수 없는 것이지.\n\n<병약한 모습으로 기침을 하는 밸라스트라즈>\n\n네... 네파리우스가 홀 파편을 가지고 있다.\n\n지금은 절대적으로 시간이 중요하다. 네파리우스는 지금 파편을 파괴할 작정이니 어서 서둘러라, 용사여!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n마노 장식 다리보호구그림자 보호의 아뮬렛\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8731] = {title = "야전 임무", objective = "하이브레갈 앞에 있는 오그리마 군단 주둔지로 가십시오. 서명되지 않은 야전 임무 보고서를 크루그 스컬스플릿에게 제출한 후 서명된 야전 임무 보고서를 받아야 합니다. 그런 다음 세나리온 요새에 있는 바람소환사 칼돈에게 돌아가십시오.\n\n주의: 오그리마 군단의 일원을 치유하거나 이로운 마법을 걸면 전투 상태가 됩니다.", description = "반갑소, <name>. 전쟁에서 중요한 역할을 맡으려면 우선 그대 몫의 야전 임무를 완수해야 하오.\n\n하이브레갈 외곽으로 가면 크루그 스컬스플릿이 이끄는 오그리마 군단이 있을 거요.\n\n크루그에게 보고한 후 임무를 완수했다는 증거를 가지고 이곳으로 돌아오시오. 더욱 중요한 임무를 준비해 놓고 기다리겠소.\n\n아, 한 가지 당부할 것은 절대 아이언포지 여단 가까이로는 가지 마시오. 롱스트라이드와 스타우트해머가 말다툼을 벌인 이후 우리 호드와 얼라이언스 사이에 팽팽한 긴장감이 흐르고 있으니까.", progress = "야전 임무는 완수하셨소, <name>? 스컬스플릿 연대장은 하이브레갈 외곽에서 찾을 수 있소이다.", completion = "크루그는 서류 작성하는 걸 아주 싫어하는 것으로 알고 있소. 참나, 여긴 실리시드의 피로 서명했군!\n\n아주 잘했소, &lt;name&gt;. 그대 같은 &lt;class&gt;|1이;가; 실력을 발휘하기에 딱 좋은 일을 몇 가지 준비해 두었소.\n\n계속 노력해 준다면 조만간 적을 섬멸할 수 있을 거요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n전투 임무병참 임무전술 임무"},
[8732] = {title = "야전 임무 보고서", objective = "야전 임무 보고서? 이 얼마나 쓸데없는 짓이란 말인가?", description = nil, progress = "야전 임무 보고서? 이 얼마나 쓸데없는 짓이란 말인가?", completion = "예전 같았으면 네 이마에 실리시드의 피로 임무를 완수했다고 표시해 주었을 텐데... 스랄님께서는 드루이드가 요구하는 대로 해주라고 하셨으니...\n\n자, 이 보고서를 가지고 세나리온 요새로 돌아가라. 그들이 자네에게 딱 맞는 일을 준비해 두었을 것이다.", rewards = "다음과 같은 것들을 받습니다:\n\n서명된 야전 임무 보고서"},
[8733] = {title = "꿈의 폭군 에라니쿠스", objective = "나이트 엘프의 땅 텔드랏실로 가 다르나서스 성벽 밖에서 말퓨리온의 대리인을 찾아야 합니다.", description = "이것은 구원을 위한 여행이다, 영웅이여. 만일 오늘 내가 죽는다 해도 난 정의를 위해 희생할 것이니... 그대는 녹색 홀 파편을 되찾아야 한다. 고대 신들에 의해 타락한 에라니쿠스를 정화해야 한다.\n\n다르나서스로 가거라. 도시 성벽 밖에서 나의 대리인이 기다리고 있을 것이니라. 그 대리인은 우리를 위해 행동을 개시하고 스테그헬름 몰래 우리의 계획을 티란데에게 알려 줄 것이다.\n\n<한숨을 쉬는 말퓨리온>\n\n천 년의 영광이 물거품이 되는 것인가...다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8734] = {title = "티란데와 레물로스", objective = "달의 숲으로 가서 수호자 레물로스와 대화하십시오.", description = "이 사실을 티란데님께 전해 드리도록 하겠습니다, 필멸의 존재여. 샨도 스톰레이지님께서 이런 일에 대비해 저를 준비시켜 놓으셨습니다.\n\n달의 숲으로 가서 레물로스님과 대화해 보십시오. 그분께서 에라니쿠스를 소환하는 일에 대해 더 자세한 내용을 알고 있을 것입니다.\n\n당신에게 행운이 있기를...다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8735] = {title = "에라니쿠스의 타락", objective = "아제로스에 있는 4개의 에메랄드의 꿈의 차원문으로 간 다음 각 에메랄드의 꿈의 차원문에서 오염된 악몽의 조각을 모은 후, 임무를 완수하면 달숲에 있는 수호자 레물로스에게 돌아가야 합니다.", description = "너는 아제로스에 있는 4개의 꿈의 차원문으로 가야 한다. 가서 각각의 꿈의 차원문에서 오염된 악몽의 조각을 찾아 모아야 한다. 꿈의 차원문 안에 있는 용혈족이 이 조각을 가지고 있을 것이니 조각을 모으면 내게 돌아오너라.", progress = "<깊은 생각에 빠진 레물로스>", completion = "준비됐느냐? 우리가 불러내려는 것에 대해 이 세계도 준비가 되었을까? 나는 잘 모르겠구나... 내게는 말퓨리온님을 받들 임무만 있을 뿐이니... 임무와 영광만이...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8736] = {title = "드러난 악몽", objective = "에라니쿠스로부터 나이트헤이븐을 지켜야 합니다. 수호자 레물로스가 죽지 않도록 지켜내고 에라니쿠스 또한 죽지 않아야 합니다. 자신을 지키며 티란데를 기다려야 합니다.", description = "우리는 에라니쿠스를 구속할 방법을 써야 한다. 그리하여 스스로 파멸하지 못하도록 막고 그를 구원해 내야 하는 것이니라.\n\n이미 티란데님께서 이번 일에 우리를 돕겠다고 나서셨다. 우리는 용의 공격을 견뎌내고 나이트헤이븐이 파괴되지 않도록 지켜내야 한다.\n\n경계를 늦추지 마라! 너와 너의 동료들이 우리의 유일한 희망이니라.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n비룡 이빨 목걸이고행의 장화\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8737] = {title = "청명 기사단", objective = "청명 기사단을 소환하여 해치운 후 세나리온 요새에 있는 보르 와일드메인에게 보고하십시오. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 I도 함께 가져가야 합니다.", description = "황혼의망치단과 이들이 숭배하는 고위 정령들이 실리더스에서 수행 중인 우리 작전에 큰 위협이 되고 있습니다. 우리는 안퀴라즈 내부의 새로운 적과 대치 중인 상황이기 때문에 외부의 적에게 병력을 돌릴 여력이 없습니다.\n\n청명 기사단을 소환하여 이들을 해치운 후 보르 와일드메인에게 보고하십시오.", progress = "맡은 임무를 벌써 마치셨습니까?", completion = "잘했습니다, &lt;name&gt;. 자, 여기 다음 임무를 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전술 휘장추가 전술 임무"},
[8738] = {title = "하이브레갈 정찰 보고서", objective = "하이브레갈 안에 있는 세나리온 정찰병 란디온과 접선한 후 세나리온 요새에 있는 바람소환사 프라우드혼에게 하이브레갈 정찰 보고서를 가지고 돌아가십시오. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 VII도 함께 가져가야 합니다.", description = "우리는 최고의 정찰병들을 실리시드 곤충 집으로 침투시켰습니다. 그중 정찰병 란디온은 지금까지 며칠 동안 하이브레갈에서 실리시드의 움직임을 감시해 왔습니다. 그를 찾아 그동안의 경과를 기록해 놓은 보고서를 받아오십시오. 그 보고서의 정보를 바탕으로 최대한 신속하게 행동을 취해야 합니다.", progress = "하이브레갈 안으로 가면 정찰병 란디온을 찾을 수 있을 것입니다. 서두르세요, <name>! 귀중한 시간을 낭비해서는 안 됩니다.", completion = "도와주셔서 진심으로 감사합니다. 지금 당장 이 정찰 보고서를 읽어봐야겠군요. 당신은 다음 임무를 수행하러 가셔도 좋습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전술 휘장추가 전술 임무"},
[8739] = {title = "하이브아쉬 정찰 보고서", objective = "하이브아쉬 안에 있는 세나리온 정찰병 잘리나와 접선한 다음 세나리온 요새에 있는 바람소환사 프라우드혼에게 하이브아쉬 정찰 보고서를 가지고 돌아가십시오. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 VIII도 함께 가져가야 합니다.", description = "우리는 최고의 정찰병들을 실리시드 곤충 집으로 침투시켰습니다. 그중 정찰병 잘리나는 지금까지 며칠 동안 하이브아쉬에서 실리시드의 동태를 감시해 왔습니다. 그녀를 찾아 그동안의 경과를 기록해 놓은 보고서를 입수해 오십시오. 우린 그 정보를 바탕으로 최대한 신속하게 행동을 취해야 합니다.", progress = "하이브아쉬 안으로 가면 정찰병 잘리나를 찾을 수 있을 것입니다. 서두르세요, <name>! 귀중한 시간을 낭비해서는 안 됩니다.", completion = "도와주셔서 진심으로 감사합니다. 저는 지금 당장 이 정찰 보고서를 읽어봐야겠군요. 당신은 다음 임무를 수행하러 가셔도 좋습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전술 휘장전술 임무"},
[8740] = {title = "황혼의 약탈자", objective = "황혼의 약탈자 5명과 황혼의 약탈자 모르나를 해치워야 합니다. 임무를 마치면 바람소환사 프라우드혼에게 보고하십시오. 또한, 이 퀘스트를 완료하려면 전술 임무 지령 IX도 함께 가져가야 합니다.", description = "말을 탄 황혼의망치단 이교도들이 우리 군대가 주둔하고 있는 세나리온 요새의 외곽 지역에 출몰해 소규모 순찰대와 짐마차를 습격하고 있습니다.\n\n황혼의 약탈자들과 놈들의 우두머리인 모르나라고 하는 무시무시한 전사를 찾아 처치해 주십시오. 일을 마친 후에는 바람소환사 프라우드혼에게 보고하시면 됩니다.", progress = "<name>, 맡은 임무를 벌써 마치셨습니까?", completion = "잘하셨습니다. 사실 그동안 황혼의 약탈자 놈들 때문에 우리 순찰대에 만만치 않은 사상자가 발생했었지요. 자, 이건 다음번에 해주실 임무입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전술 휘장추가 전술 임무"},
[8741] = {title = "용사의 귀환", objective = "타나리스의 시간의 동굴에 있는 아나크로노스에게 녹색 홀 파편을 가져가야 합니다.", description = "수호자가 너를 기다리는구나. 시간의 동굴에 있는 아나크로노스에게 이 녹색 홀 파편을 가지고 가거라.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8742] = {title = "칼림도어 연합군", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8743] = {title = "징을 울려라!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n공명의 검은 퀴라지 수정"},
[8744] = {title = "정성스럽게 포장된 선물꾸러미", objective = "선물에 다음과 같은 글귀가 적혀 있습니다.\n\n<name>, 따뜻한 겨울 맞이되세요.\n\n올해 겨울맞이 축제는 꼭 즐겁고 유쾌하게 보내세요!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n정성스럽게 포장된 선물꾸러미"},
[8745] = {title = "시간 지배자의 보물", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n코리알스트라즈의 송곳니섀도송의 비애혁명가의 룬문자 검레이븐크레스트의 유산\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8746] = {title = "멧젠 사슴코", objective = "순록 멧젠을 찾아야 합니다. 편지와 쪽지에서 어디로 잡혀갔는지 단서를 찾으십시오.\n\n멧젠을 발견하면, 순록 가루 주머니에 든 가루를 뿌리십시오. 감금된 멧젠을 풀어줄 수 있을 것입니다.\n\n순록 멧젠을 구출한 후, 오그리마에 있는 케이말드 코퍼핀치에게 순록 가루 주머니를 가져가십시오.", description = "오, 맙소사! 이런 변이 있나! 우리 순록 멧젠이 납치당했다고!\n\n멧젠은 겨울 할아버지의 여덟 마리 순록 중의 하나이자, 굴뚝나무 목장조합의 귀중한 자산이지. 멧젠을 납치해간 놈들에게서 몸값을 요구하는 편지를 한 장도 아니고 자그마치 두 장이나 받았네. 사실, 겨울맞이 축제 선물을 준비할 시기라 우리에겐 몸값으로 낼 돈이 없어! 자네가 우리 멧젠을 구해 주게!\n\n멧젠의 편지와 쪽지를 읽어보면 그의 행방에 대한 단서를 찾을 수 있을 거야! 그를 찾으면 이 순록 가루를 뿌리게나. 우리 멧젠을 어떤 구속에서라도 풀어줄 걸세!\n\n어서 서두르라고!", progress = "멧젠을 찾았나? 내가 준 가방 안에 있는 편지와 쪽지에 멧젠이 어디로 끌려갔는지에 대한 정보가 있던가? 아아, 그 흉악한 악당들이 우리 멧젠에게 무슨 짓을 저지를지 생각조차 하기 싫어. 하지만, 터무니없는 몸값을 구할 방법도 없지 않은가?!", completion = "오, 해냈군! 만세!\n\n얼마 전 하늘에서 날아온 멧젠은 겨울 할아버지의 우리로 돌아갔다네. 그래 맞아! 멧젠은 정말 날 수 있는 순록이야. 그리고 순록 가루에는 마법의 힘이 깃들어 있었지. 내 이럴 줄 알았다니까! &lt;name&gt;, 자네는 굴뚝나무 목장조합을 재앙에서 구했을 뿐만 아니라 겨울맞이 축제를 살렸어. 고맙네!\n\n자, 자네의 영웅적인 노고를 기리는 선물일세. 정말 특별한 것이지. 일단 탈것에 올라탄 다음 써봐! 후후, 아마 땅을 박차고 달려나가고 싶어 못 견딜걸. 그럼, 즐거운 겨울맞이 축제 되라고!", rewards = "다음과 같은 것들을 받습니다:\n\n보존된 호랑가시나무"},
[8747] = {title = "수호자의 길", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
