[8750] = {title = "수호자의 길", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8751] = {title = "칼림도어의 수호자", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8752] = {title = "정복자의 길", objective = "감동적이구나, 필멸의 존재여. 그대는 청동용군단의 인정을 받기 위해 많은 고난을 겪었다. 이제 그대의 헌신적인 노력을 인정하노라.\n\n정복자의 인장 반지는 그대의 물리 공격을 크게 향상시켜 줄 것이다.\n\n명심하라. 일단 그대의 길을 선택하게 되면 마음이 바뀌더라도 결정을 되돌릴 수 없음을...", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8753] = {title = "정복자의 길", objective = "그대가 계속해 칼림도어의 자손들을 지키고 있음이 인정되었다. 인장 반지를 이리 다오. 더 강한 힘을 불어넣어 주겠노라.", description = nil, progress = "그대가 계속해 칼림도어의 자손들을 지키고 있음이 인정되었다. 인장 반지를 이리 다오. 더 강한 힘을 불어넣어 주겠노라.", completion = "노즈도르무 혈족 사이에서 그대의 지위가 올랐다니 정말 멋진 일이로구나. 부디 끝까지 정복자의 길을 걷기를!", rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8754] = {title = "정복자의 길", objective = "그대는 내 일족의 자존심이다. 칼림도어의 적들을 쓰러뜨려라! 영원한 별빛의 땅을 더럽힌 대가가 무엇인지를 보여 주어라.\n\n그대는 다시 한 번 힘을 강화시킬 수 있게 되었다. 좀 더 강한 힘을 불어넣어 줄 테니 그대의 인장 반지를 이리 다오.", description = nil, progress = "그대는 내 일족의 자존심이다. 칼림도어의 적들을 쓰러뜨려라! 영원한 별빛의 땅을 더럽힌 대가가 무엇인지를 보여 주어라.\n\n그대는 다시 한 번 힘을 강화시킬 수 있게 되었다. 좀 더 강한 힘을 불어넣어 줄 테니 그대의 인장 반지를 이리 다오.", completion = "노즈도르무 혈족 사이에서 그대의 지위가 올랐다니 정말 멋진 일이로구나. 부디 끝까지 정복자의 길을 걷기를!", rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8755] = {title = "정복자의 길", objective = "이토록 숭고한 희생 정신을 가진 이가 또 있을까... 그대는 확고한 의지가 있음을 똑똑히 보여 주었다. 그대가 우리 세계를 철통같이 지켜낸 것에 대해 큰 보상을 내리겠노라.\n\n마법을 더욱 강화시켜 줄 테니 그대의 인장 반지를 이리 다오.", description = nil, progress = "이토록 숭고한 희생 정신을 가진 이가 또 있을까... 그대는 확고한 의지가 있음을 똑똑히 보여 주었다. 그대가 우리 세계를 철통같이 지켜낸 것에 대해 큰 보상을 내리겠노라.\n\n마법을 더욱 강화시켜 줄 테니 그대의 인장 반지를 이리 다오.", completion = "노즈도르무 혈족 사이에서 그대의 지위가 올랐다니 정말 멋진 일이로구나. 부디 끝까지 정복자의 길을 걷기를!", rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8756] = {title = "퀴라지 정복자", objective = "그대 같이 끈기 있는 자는 처음 보는구나! 청동용군단의 마지막 마법을 부여해 주겠노라. 이것은 시간의 지배자께서 직접 청하신 일이다!\n\n필요한 마법을 조정해 줄 테니 그대의 인장 반지를 이리 다오.", description = nil, progress = "그대 같이 끈기 있는 자는 처음 보는구나! 청동용군단의 마지막 마법을 부여해 주겠노라. 이것은 시간의 지배자께서 직접 청하신 일이다!\n\n필요한 마법을 조정해 줄 테니 그대의 인장 반지를 이리 다오.", completion = "일어나라, 퀴라지 정복자여! 당당히 일어나 모두의 인정을 받으라!", rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8757] = {title = "기원사의 길", objective = "감동적이구나, 필멸의 존재여. 그대는 청동용군단의 인정을 받기 위해 많은 고난을 겪었다. 이제 그대의 헌신적인 노력을 인정하노라.\n\n기원사의 인장 반지는 그대의 마법과 자연의 능력을 크게 향상시켜 줄 것이다.\n\n명심하라. 일단 그대의 길을 선택하게 되면 마음이 바뀌더라도 결정을 되돌릴 수 없음을...", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8758] = {title = "기원사의 길", objective = "그대가 계속해 칼림도어의 자손들을 지키고 있음이 인정되었다. 인장 반지를 이리 다오. 더 강한 힘을 불어넣어 주겠노라.", description = nil, progress = "그대가 계속해 칼림도어의 자손들을 지키고 있음이 인정되었다. 인장 반지를 이리 다오. 더 강한 힘을 불어넣어 주겠노라.", completion = "노즈도르무 혈족 사이에서 그대의 지위가 올랐다니 정말 멋진 일이로구나. 부디 끝까지 기원사의 길을 걷기를!", rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8759] = {title = "기원사의 길", objective = "그대는 내 일족의 자존심이다. 칼림도어의 적들을 쓰러뜨려라! 영원한 별빛의 땅을 더럽힌 대가가 무엇인지를 보여 주거라.\n\n그대는 다시 한 번 힘을 강화시킬 수 있게 되었다. 좀 더 강한 힘을 불어넣어 줄 테니 그대의 인장 반지를 이리 다오.", description = nil, progress = "그대는 내 일족의 자존심이다. 칼림도어의 적들을 쓰러뜨려라! 영원한 별빛의 땅을 더럽힌 대가가 무엇인지를 보여 주거라.\n\n그대는 다시 한 번 힘을 강화시킬 수 있게 되었다. 좀 더 강한 힘을 불어넣어 줄 테니 그대의 인장 반지를 이리 다오.", completion = "노즈도르무 혈족 사이에서 그대의 지위가 올랐다니 정말 멋진 일이로구나. 부디 끝까지 기원사의 길을 걷기를!", rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8760] = {title = "기원사의 길", objective = "이토록 숭고한 희생 정신을 가진 이가 또 있을까... 그대는 확고한 의지가 있음을 똑똑히 보여 주었다. 그대가 우리 세계를 철통같이 지켜낸 것에 대해 큰 보상을 내리겠노라.\n\n마법을 더욱 강화시켜 줄 테니 그대의 인장 반지를 이리 다오.", description = nil, progress = "이토록 숭고한 희생 정신을 가진 이가 또 있을까... 그대는 확고한 의지가 있음을 똑똑히 보여 주었다. 그대가 우리 세계를 철통같이 지켜낸 것에 대해 큰 보상을 내리겠노라.\n\n마법을 더욱 강화시켜 줄 테니 그대의 인장 반지를 이리 다오.", completion = "노즈도르무 혈족 사이에서 그대의 지위가 올랐다니 정말 멋진 일이로구나. 부디 끝까지 기원사의 길을 걷기를!", rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8761] = {title = "위대한 기원사", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n청동용군단의 인장 반지"},
[8762] = {title = "멧젠 사슴코", objective = "순록 멧젠을 찾아야 합니다. 편지와 쪽지에서 어디로 잡혀갔는지 단서를 얻을 수 있을 것입니다.\n\n멧젠을 발견하면, 순록 가루 주머니에 든 가루를 뿌리십시오. 멧젠을 감금 상태에서 풀어줄 수 있을 것입니다.\n\n순록 멧젠이 구출한 후, 아이언포지에 있는 훌몰트 징글포켓에게 순록 가루 주머니를 가져가십시오.", description = "오, 맙소사! 이런 변이 있나! 우리 순록 멧젠이 납치당했다고!\n\n멧젠은 겨울 할아버지의 여덟 마리 순록 중의 하나이자, 굴뚝나무 목장조합의 귀중한 자산이지. 멧젠을 납치해간 놈들에게서 몸값을 요구하는 편지를 한 장도 아니고 자그마치 두 장이나 받았네. 사실, 겨울맞이 축제 선물을 준비해야 할 시기라 우리에겐 몸값으로 낼 돈이 없어! 자네가 우리 멧젠을 구해 주게!\n\n멧젠의 편지와 쪽지를 읽어보면 그의 행방에 대한 단서를 찾을 수 있을 거야! 그를 찾으면 이 순록 가루를 뿌리게나. 우리 멧젠을 어떤 구속에서라도 풀어줄 걸세!\n\n어서 서두르라고!", progress = "멧젠을 찾았나? 내가 준 가방 안에 있는 편지와 쪽지에 멧젠이 어디에 있는지에 대한 정보가 있던가? 아아, 그 흉악한 악당들이 우리 멧젠에게 무슨 짓을 저지를지는 생각조차 하기 싫어. 하지만, 터무니없는 몸값을 마련할 방법도 없단 말이야!", completion = "오, 해냈군! 만세!\n\n얼마 전, 하늘에서 날아온 멧젠은 겨울 할아버지의 우리로 돌아갔다네. 맞아, 멧젠은 날 수 있는 순록이라고. 그리고 그 가루에는 마법의 힘이 깃들어 있었지. 내 이럴 줄 알았다니까! 자네는 재앙에서 굴뚝나무 목장조합을 구했을 뿐만 아니라 겨울맞이 축제를 살렸어. 고맙네!\n\n자, 자네의 영웅적인 노고를 기리는 선물일세. 정말 특별한 것이지. 일단 탈것에 올라탄 다음 써봐! 후후, 땅을 박차고 달려나가고 싶어 못 견딜 거야. 그럼, 즐거운 겨울맞이 축제 되라고!", rewards = "다음과 같은 것들을 받습니다:\n\n보존된 호랑가시나무"},
[8763] = {title = "오늘의 영웅", objective = "깊은바다 소금 1줌과 5골드를 호랑가시나무 보존기에 넣으면, 보존된 호랑가시나무를 받게 될 것입니다.", description = "흠, 내가 이런 비밀을 자네에게 밝히리라고는 생각지도 않았는데... 그래도 자네가 오늘의 영웅이니까!\n\n매년 이맘때쯤엔 어디서나 싱싱한 호랑가시나무를 볼 수 있지만 오래가지는 못하지. 굴뚝나무 목장조합에서는 호랑가시나무가 절대 상하지 않도록 보존하는 기계를 이용해서 겨울맞이 축제의 분위기를 살리고 여름내 돈벌이를 하지!\n\n자네가 요리의 대가라면 보존기를 쓸 수 있게 해 주지. 단, 깊은바다 소금이 필요할 거야. 그리고 사용료는 1, 2, 3... 5골드로 하지. 싱싱하게 보존된 호랑가시나무 한 묶음을 얻을 수 있을 걸세.", progress = "호랑가시나무 보존기는 처음에는 전혀 움직임이 없어 보이지만, 꼼꼼하게 확인해보니 고블린 양식으로 변경된 것 같습니다. 그러나, 당신의 요리 기술이라면 이 기계가 어떻게 동작하는지 알 수 있을 것 같습니다.\n\n보존기 안에는 이미 싱싱하게 보존된 호랑가시나무 한 묶음이 보입니다. 기계를 작동하려면 깊은바다 소금 한 줌과 5골드를 넣어야 합니다.", completion = "기계가 작동을 시작한 듯 덜컹덜컹 소리와 약간의 증기를 내뿜습니다. 조금 지나자 기계가 멈추더니 무언가를 예고하려는 듯이 또다시 증기가 몇 번 뿜어져 나옵니다. 보존기의 문이 열리고 보존된 호랑가시나무 한 묶음이 보입니다!", rewards = "다음과 같은 것들을 받습니다:\n\n보존된 호랑가시나무"},
[8764] = {title = "진로 변경 - 수호자의 길 포기", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n청동용군단의 인장 반지청동용군단의 인장 반지"},
[8765] = {title = "진로 변경 - 기원사의 길 포기", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n청동용군단의 인장 반지청동용군단의 인장 반지"},
[8766] = {title = "진로 변경 - 정복자의 길 포기", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n청동용군단의 인장 반지청동용군단의 인장 반지"},
[8767] = {title = "누가 살짝 흔들어 본 선물", objective = "이 선물은 누군가 살짝 흔들어 본 것 같습니다. 상자에 다음과 같은 글귀가 적혀 있는 것이 보입니다.\n\n아제로스에서 가장 특별한 <race> <class>님에게 바칩니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n누가 살짝 흔들어 본 선물"},
[8768] = {title = "화려하게 포장된 선물꾸러미", objective = "축제 분위기에 맞게 화려하게 포장된 상자에 당신의 이름이 적혀 있습니다.\n\n가만, 방금 상자 안에서 뭔가 움직이지 않았나요?", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n화려하게 포장된 선물꾸러미"},
[8769] = {title = "꿈틀거리는 선물상자", objective = "굴뚝나무 목장조합에서 당신의 친구가 보냅니다. 부디 흥겨운 콧노래가 절로 나는 겨울맞이 축제 보내세요!", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n들썩거리는 선물상자"},
[8770] = {title = "목표: 병정 하이브아쉬", objective = "병정 하이브아쉬 30마리를 처치한 후 실리더스에 있는 지휘관 마랄리스에게 전투 임무 지령 I을 가지고 돌아가야 합니다.", description = "전쟁 준비가 진행되면서 이 지역에 존재하는 실리시드가 우리의 작전에 아주 큰 위협이 되고 있습니다. 당신은 하이브아쉬 공격 작전에 선발되었으며 당신의 주요 목표는 병정 하이브아쉬입니다.\n\n임무를 완수하면 지휘관 마랄리스에게 보고하십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8771] = {title = "목표: 모래무지 하이브아쉬", objective = "모래무지 하이브아쉬 30마리를 처치한 후 실리더스에 있는 지휘관 마랄리스에게 전투 임무 지령 II을 가지고 돌아가야 합니다.", description = "전쟁 준비가 진행되면서 이 지역에 존재하는 실리시드가 우리의 작전에 아주 큰 위협이 되고 있습니다. 당신은 하이브아쉬 공격 작전에 선발되었으며 당신의 주요 목표는 모래무지 하이브아쉬입니다.\n\n임무를 완수하면 지휘관 마랄리스에게 보고하십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8772] = {title = "목표: 길잡이 하이브조라", objective = "길잡이 하이브조라 30마리를 처치한 후 실리더스에 있는 지휘관 마랄리스에게 전투 임무 지령 VI를 가지고 돌아가야 합니다.", description = "하이브조라를 공격하기 위해 증원군을 요청했습니다. 당신은 길잡이 하이브조라 공격 작전에 선발되었습니다. 임무를 마치면 지휘관 마랄리스에게 돌아가서 보고하십시오.", progress = "내게 할 말이라도 있소, <class>|1이여;여;?", completion = "정말 잘했소. 하이브아쉬 공격 작전에서 그대가 세운 공은 널리 기억될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8773] = {title = "목표: 모래무지 하이브조라", objective = "모래무지 하이브조라 30마리를 처치한 후 실리더스에 있는 지휘관 마랄리스에게 전투 임무 지령 IV를 가지고 돌아가야 합니다.", description = "하이브조라를 공격하기 위해 증원군을 요청했습니다. 당신은 모래무지 하이브조라 공격 작전에 선발되었습니다. 임무를 마치면 지휘관 마랄리스에게 돌아가서 보고하십시오.", progress = "내게 할 말이라도 있소, <class>|1이여;여;?", completion = "하이브조라 공격 작전에서 그대가 멋진 활약을 펼쳤다는 소식을 들었소. 계속 노력해 준다면 머지않아 우리가 승리를 거둘 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8774] = {title = "목표: 모래무지 하이브레갈", objective = "모래무지 하이브레갈 30마리를 처치한 후 실리더스에 있는 지휘관 마랄리스에게 전투 임무 지령 VIII을 가지고 돌아가야 합니다.", description = "전쟁 준비가 진행되면서 이 지역에 존재하는 실리시드가 우리의 작전에 아주 큰 위협이 되고 있습니다. 당신은 하이브레갈 공격 작전에 선발되었으며 당신의 주요 목표는 모래무지 하이브레갈입니다.\n\n임무를 완수하면 지휘관 마랄리스에게 보고하십시오.", progress = "내게 할 말이라도 있소, <class>|1이여;여;?", completion = "정말 잘했소. 하이브레갈 공격 작전에서 그대가 세운 공은 널리 기억될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8775] = {title = "목표: 독침 하이브레갈", objective = "독침 하이브레갈 30마리를 처치한 후 실리더스에 있는 지휘관 마랄리스에게 전투 임무 지령 IX를 가지고 돌아가야 합니다.", description = "전쟁 준비가 진행되면서 이 지역에 존재하는 실리시드가 우리의 작전에 아주 큰 위협이 되고 있습니다. 당신은 하이브레갈 공격 작전에 선발되었으며 당신의 주요 목표는 날아다니는 독침 하이브레갈입니다.\n\n임무를 완수하면 지휘관 마랄리스에게 보고하십시오.", progress = "내게 할 말이라도 있소, <class>|1이여;여;?", completion = "정말 잘했소. 하이브레갈 공격 작전에서 그대가 세운 공은 널리 기억될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8776] = {title = "목표: 암컷 하이브레갈", objective = "암컷 하이브레갈 30마리를 처치한 후 실리더스에 있는 지휘관 마랄리스에게 전투 임무 지령 X을 가지고 돌아가야 합니다.", description = "전쟁 준비가 진행되면서 이 지역에 존재하는 실리시드가 우리의 작전에 아주 큰 위협이 되고 있습니다. 당신은 하이브레갈 공격 작전에 선발되었으며 당신의 주요 목표는 일꾼인 암컷 하이브레갈입니다.\n\n임무를 완수하면 지휘관 마랄리스에게 보고하십시오.", progress = "내게 할 말이라도 있소, <class>|1이여;여;?", completion = "정말 잘했소. 하이브레갈 공격 작전에서 그대가 세운 공은 널리 기억될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8777] = {title = "목표: 땅꾼 하이브레갈", objective = "땅꾼 하이브레갈 30마리를 처치한 후 실리더스에 있는 지휘관 마랄리스에게 전투 임무 지령 XI을 가지고 돌아가야 합니다.", description = "전쟁 준비가 진행되면서 이 지역에 존재하는 실리시드가 우리의 작전에 아주 큰 위협이 되고 있습니다. 당신은 하이브레갈 공격 작전에 선발되었으며 당신의 주요 목표는 땅꾼 하이브레갈입니다.\n\n임무를 완수하면 지휘관 마랄리스에게 보고하십시오.", progress = "내게 할 말이라도 있소, <class>|1이여;여;?", completion = "정말 잘했소. 하이브레갈 공격 작전에서 그대가 세운 공은 널리 기억될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 전투 휘장"},
[8778] = {title = "아이언포지 여단에 폭탄 공급!", objective = "실리더스의 하이브조라 근처에 있는 비전술사 노즐스프링에게 제물의 오일 6개, 고블린 로켓 연료 5개, 강도 높은 화약 10개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 IV도 함께 가져가야 합니다.", description = "아이언포지 여단에서 폭발하기 아주 쉬운 재료를 보내 달라는 별난 요청을 해왔습니다. 재료서 모아서 아이언포지 여단에 있는 노즐스프링 씨에게 가져다주세요.", progress = "<name>, 제게 가져오신 물건이 있지 않나요?", completion = "바로 이거예요! 이거라면 큰 도움이 될 거예요! 정말 고맙습니다, &lt;name&gt;!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8779] = {title = "수정점 재료", objective = "실리더스의 세나리온 요새에 있는 지질학자 락스베인에게 눈부신 큰 결정, 찬란하게 빛나는 큰 결정, 거대한 에메랄드를 각각 1개씩 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 V도 함께 가져가야 합니다.", description = "지질학자 락스베인의 연구가 실리더스에서 우리가 수행하는 작전에 엄청난 도움이 된다는 것이 입증되었습니다. 최근에 그녀는 수정점 연구에 사용할 재료를 요청했습니다.\n\n그녀가 연구를 계속할 수 있도록 재료를 모으는 즉시 가져다주십시오.", progress = "제게 가져오신 물건이 있지 않나요, <name>?", completion = "그래요... 이거라면 굉장한 도움이 될 겁니다! 사막에서 정말 구하기 어려운 재료들이죠. &lt;name&gt;, 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8780] = {title = "전장에 방어구 키트 공급", objective = "실리더스의 하이브조라 근처 아이언포지 여단 주둔지에 있는 자넬라 스타우트해머에게 튼튼한 방어구 키트와 고급 방어구 키트를 각각 8개씩 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 VII도 함께 가져가야 합니다.", description = "전장에 있는 아이언포지 여단의 방어구 키트 보유량이 매우 부족한 상황입니다. 방어구 키트를 구해서 하이브조라 외곽의 아이언포지 여단 주둔지에 있는 자넬라 스타우트해머에게 전달해 주십시오.", progress = "제게 가져오신 물건이 있지 않나요, <name>?", completion = "고마워요. 이 방어구 키트를 병사들에게 나눠 주겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8781] = {title = "전장에 무기 공급", objective = "하이브조라 외곽의 아이언포지 여단 주둔지에 있는 자넬라 스타우트해머에게 달의 강철 브로드소드 2개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 VI도 함께 가져가야 합니다.", description = "아이언포지 여단은 우리의 실리더스 전투에서 든든한 동맹의 역할을 수행해 왔습니다. 그런데 유감스럽게도 아이언포지 여단이 이곳으로 이동하는 도중 보급품의 상당 부분을 분실했습니다. 브로드소드를 구해서 하이브조라 근처에 있는 자넬라 스타우트해머에게 전달해 주십시오.", progress = "제게 가져오신 물건이 있지 않나요, <name>?", completion = "와, 정말 멋지군요! 이제 무딘 칼로 인한 병사들의 불평을 듣지 않아도 되겠어요. 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8782] = {title = "제복 공급", objective = "실리더스 세나리온 요새에 있는 바람소환사 프라우드혼에게 달빛 옷감 1개, 룬무늬 두루마리 2개, 그리고 강철그물 거미줄 1개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 VIII도 함께 가져가야 합니다.", description = "최근에 들어온 지원자들에게 지급할 제복이 부족합니다. 제복 재료를 구해서 바람소환사 프라우드혼에게 가져다주십시오.", progress = "<name>, 제게 가져오신 물건이 있지 않습니까?", completion = "제때 와주셨군요. 이 재료들이 절실히 필요하던 상황이었습니다. 도와주셔서 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8783] = {title = "특별한 재료", objective = "실리더스의 세나리온 요새에 있는 바르구스에게 마력 깃든 토륨 주괴 2개, 마력 깃든 가죽 2개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 IX도 함께 가져가야 합니다.", description = "세나리온 요새의 대장장이 바르구스가 우리 군대가 쓸 강력한 무기에 마력을 부여할 재료를 요청했습니다. 세나리온 요새의 군대가 완전 무장할 수 있도록 이 재료들을 구하는 즉시 바르구스에게 가져다주십시오.", progress = "내게 가져온 물건이 있지 않소?", completion = "바로 이거요. 품질이 아주 우수한 재료들이군... 고맙소, &lt;name&gt;.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8784] = {title = "퀴라지의 비밀", objective = "신전 입구 근처에 숨어 있는 용족에게 고대 퀴라지 유물을 가져가야 합니다.", description = "당신이 발견한 것은 고대 퀴라지 유물입니다! 신전의 입구 근처에 있는 용들 중 하나가 이 유물의 사용법을 알고 있을 겁니다.", progress = "얼굴이 상기되었군요! 왜 그런지 압니다...", completion = "아주 중요한 것을 발견하셨군요. 정말 놀랍습니다! 이것만 있으면 적의 사악한 의도를 확실하게 꿰뚫어 볼 수 있을 것입니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n노즈도르무 혈족 평판 +1000"},
[8785] = {title = "오그리마 군단에 모조 공급!", objective = "실리더스의 하이브레갈 근처에 있는 어둠의여사제 샤이에게 제물의 오일 8개, 왕모조 물약 6개, 강력한 모조 6개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 IV도 함께 가져가야 합니다.", description = "오그리마 군단에서 몇 가지 특이한 재료를 요청했습니다. 현재 그들이 실리더스에서 수행하는 임무를 고려해 볼 때 최대한 신속하게 요청을 들어주는 것이 좋을 것 같습니다. 재료를 모아서 샤이라는 트롤에게 가져다주십시오.", progress = "재료는 가져오셨습니까, <name>?", completion = "아, 맞습니다. 바로 제가 필요로 하던 재료입니다! 이걸 사용해서 특수한 혼합물을 만들 것입니다. 실리시드라면 정말 몸서리칠만한 것을 말이지요!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8786] = {title = "전장에 무기 공급", objective = "하이브레갈 외곽 오그리마 군단 주둔지에 있는 메로크 롱스트라이드에게 큰 철제 도끼 3개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 VI도 함께 가져가야 합니다.", description = "오그리마 군단에서 무기를 추가로 공급해 달라고 요청했을 때는 우리가 그럴 수 있는 형편이 아니었습니다. 이제 그들이 요청한 무기를 구하여 하이브레갈 외곽에 있는 메로크 롱스트라이드에게 가져다주십시오.", progress = "제게 가져오신 물건이 있지 않습니까, <name>?", completion = "훌륭합니다. 마침 이 물건들의 공급이 떨어져서 절실하게 필요하던 상황이었습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8787] = {title = "전장에 방어구 키트 공급", objective = "하이브레갈 부근에 있는 메로크 롱스트라이드에게 튼튼한 방어구 키트와 고급 방어구 키트를 각각 8개씩 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 VII도 함께 가져가야 합니다.", description = "오그리마 군단의 용감한 지원자들이 우리를 도와 대업을 달성하기 위해 실리더스에 도착했습니다. 그런데 여행 중에 그만 방어구 키트를 분실했다고 합니다. 방어구 키트를 모아 오그리마 군단 주둔지에 있는 메로크 롱스트라이드에게 가져다주십시오.", progress = "절 위해 가져오신 물건이 있지 않습니까?", completion = "그래요, 바로 이겁니다. 이 방어구 키트를 병사들에게 골고루 배급하겠습니다. 그리고 &lt;name&gt;, 오그리마 군단을 대신하여 진심으로 감사를 전합니다!", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8788] = {title = "누가 살짝 흔들어 본 선물", objective = "이 선물은 누군가 살짝 흔들어 본 것 같습니다. 상자에 다음과 같은 글귀가 적혀 있는 것이 보입니다.\n\n아제로스에서 가장 특별한 <race> <class>님에게 바칩니다.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n누가 살짝 흔들어 본 선물"},
[8789] = {title = "제국의 퀴라지 무기", objective = "안퀴라즈 사원에 있는 아리고스에게 제국의 퀴라지 무기와 엘레멘티움 광석 3개를 가지고 가면 엘레멘티움을 주입한 무기를 만들어 줄 것입니다.", description = "우리가 천 년 동안 놀고만 있었던 건 아니라네.\n\n우린 이 짐승들은 쓸모가 없다면 자신의 종족까지 잡아먹는다는 것을 목격했다네. 또한 우리는 그들이 이 세계를 파괴하려는 음모를 꾸미는 것을 들었지. 그리고 그들의 내부에 배신이 있었다는 것도 알아냈다네.\n\n그들에게 무슨 약점이 있으며 그 약점을 우리에게 유리한 방향으로 이용하는 방법을 알고 있단 말일세.\n\n그들이 의식에 사용하는 도구를 가지고 오게. 그 도구를 그들이 섬기는 신이 벌인 전쟁으로 인해 만들어진 물질과 합친다면 그들을 심판하는 강력한 무기가 될 것이야.", progress = "내가 요청한 걸 찾아오게. 자네는 자네가 속한 단체의 모든 이를 합친 것보다도 더 강해질 걸세.", completion = "엘레멘티움이 들어간 이 무기는 퀴라지와 그들의 신을 가볍게 베어 버릴 것이야.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n축복받은 퀴라지 전투도끼축복받은 퀴라지 머스킷총축복받은 퀴라지 푸기오축복받은 퀴라지 보루방패"},
[8790] = {title = "제국의 퀴라지 표장", objective = "안퀴라즈 사원에 있는 꿈의 메리스라에게 제국의 퀴라지 표장과 엘레멘티움 광석 3개를 가지고 가면 엘레멘티움을 주입한 무기를 만들어 줄 것입니다.", description = "아리고스는 고대 신과 그들의 부하들 간에 벌어진 충돌에서 발생한 물질이 그들 자신에게도 매우 치명적일 것이라는 이론을 세웠습니다. 제가 말하는 것은 바로 엘레멘티움입니다, 필멸의 존재여.\n\n제국의 퀴라지 표장과 엘레멘티움을 찾아서 가져오십시오. 내 강력한 힘을 가진 무기를 만들어 주도록 하겠습니다.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n축복받은 퀴라지 시제 지팡이축복받은 퀴라지 예언자 지팡이축복받은 퀴라지 전투망치"},
[8791] = {title = "오시리안 처치", objective = "실리더스의 세나리온 요새에 있는 지휘관 마랄리스에게 무적의 오시리안의 머리를 가지고 가야 합니다.", description = "지독하게 위험했고 잔인했던 오시리안이 패하고 그의 영혼은 안식을 찾았습니다.\n\n칼림도어의 모든 이들이 이 승리의 소식을 듣는다면 안도의 한숨을 쉬게 될 것입니다. 세나리온 요새의 지휘관 마랄리스에게 오시리안의 머리를 가지고 가십시오.", progress = "오 <name>, 돌아왔구려! 한 가지 묻고 싶은 게 있는데 안퀴라즈에서 가지고 온 소식은 없소?", completion = "그대에게 내가 할 수 있는 최고의 찬사와 강력한 힘을 가진 물건을 선택할 수 있는 기회를 주겠소. 그대는 칼림도어의 백성들을 위해 엄청난 일을 해낸 것이오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n흐르는 모래의 부적흐르는 모래의 아뮬렛흐르는 모래의 목걸이흐르는 모래의 펜던트\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8792] = {title = "호드 지원!", objective = "오그리마, 정기의 골짜기에 있는 장군 고르척과 대화하십시오.", description = "안녕하십니까. 제 부탁을 들어주시겠다니 고맙군요. 호드에서는 안퀴라즈 전쟁을 준비하기 위해 단 한 명의 도움이라도 절실한 상황입니다. 그러니까 당신의 도움이 꼭 필요하다는 말입니다! 우리가 대화를 나누고 있는 지금 이 순간에도 공식적으로 수집 임무를 맡은 이들이 다가올 전쟁에 필요한 물자를 모으고 있답니다. 그러나 <name>, 당신의 도움이 없으면 우리는 목표를 달성할 수 없습니다!\n\n전쟁 물자 수집을 책임지고 있는 장군 고르척에게 가서 얘기를 나눠보십시오. 자, 어떻습니까? 호드의 생사가 걸린 전쟁 준비를 돕겠습니까?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8793] = {title = "호드 지원!", objective = "오그리마, 정기의 골짜기에 있는 장군 고르척과 대화하십시오.", description = "안녕하신가. 내 말에 귀를 기울여 주겠다니 고맙군. 호드는 안퀴라즈 전쟁을 준비하기 위해 단 한 명의 도움이라도 절실한 상황이네. 그러니까 자네가 꼭 필요하다는 거야! 우리가 대화를 나누고 있는 지금 이 순간에도 공식적으로 수집 임무를 맡은 이들이 다가올 전쟁에 필요한 물자를 모으고 있네. 그러나 <name>, 자네가 도와주지 않으면 우린 목표를 달성할 수 없어!\n\n전쟁 물자 수집을 책임지고 있는 장군 고르척에게 가서 얘기를 나눠보게. 자, <class>|1이여;여;, 어떻게 하겠나? 설마 호드의 생사가 걸린 전쟁 준비를 모른 척하지는 않겠지?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8794] = {title = "호드 지원!", objective = "오그리마, 정기의 골짜기에 있는 장군 고르척과 대화하십시오.", description = "안녕하십니까. 제 부탁을 들어주시겠다니 고맙군요. 호드에서는 안퀴라즈 전쟁을 준비하기 위해 단 한 명의 도움이라도 절실한 상황입니다. 그러니까 당신의 도움이 꼭 필요하다는 말입니다! 우리가 대화를 나누고 있는 지금 이 순간에도 공식적으로 수집 임무를 맡은 이들이 다가올 전쟁에 필요한 물자를 모으고 있답니다. 그러나 <name>, 당신의 도움이 없으면 우리는 목표를 달성할 수 없습니다!\n\n전쟁 물자 수집을 책임지고 있는 장군 고르척에게 가서 얘기를 나눠보십시오. 자, 어떻습니까? 호드의 생사가 걸린 전쟁 준비를 도와주시겠습니까?", progress = nil, completion = "트롬카! 자네와 같이 다가올 안퀴라즈 전쟁 준비를 지원하려는 호드가 이렇게 많은 것을 보니 실로 기분이 좋군. 이곳의 준비가 완벽할수록 안퀴라즈 안에 숨어 있는 실리시드 무리와 그들을 조종하는 사악한 놈들과의 싸움에서 우리의 승리가 보장되는 것이라네.\n\n자네, 호드를 돕기 위해 이곳에 왔으니 전쟁 물자 수집을 담당하고 있는 이들과 얘기해 보고 자네의 능력에 맞는 일을 골라 지원하도록!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8795] = {title = "얼라이언스 지원자 모집!", objective = "아이언포지의 군사 지구에 있는 야전사령관 스노우폴과 대화하십시오.", description = "안녕하십니까. 제 부탁을 들어주시겠다니 고맙습니다. 얼라이언스 연합에서는 안퀴라즈 전쟁을 준비하기 위해 단 한 명의 도움이라도 절실한 상황입니다. 그러니까 당신의 도움이 필요하다는 말입니다! 우리가 대화를 나누고 있는 지금 이 순간에도 정식으로 임무를 맡은 이들이 코앞에 닥친 전쟁에 필요한 물자를 모으고 있습니다. 그러나 당신의 도움이 없으면 우리의 목표를 달성할 수 없습니다!\n\n물자 보급을 책임지고 있는 야전사령관 스노우폴과 얘기해 보십시오. 어떻게 하시겠습니까? 아제로스의 모든 생명체의 생사가 걸린 전쟁 준비를 도와주시겠습니까?", progress = nil, completion = "만나서 반갑네! 자네와 같이 다가오는 안퀴라즈 전쟁을 준비하기 위해 도움을 주려는 얼라이언스의 일원이 이렇게 많은 것을 보니 기분이 좋군. 이곳의 준비가 완벽할수록 안퀴라즈에 숨어 있는 실리시드와 그들의 사악한 주인들과의 싸움에서 우리의 승리가 보장되는 것이네.\n\n자네도 도움을 주기 위해 이곳에 왔으니 물자 수집을 담당하고 있는 이들과 얘기해 보고 자네가 수집할 수 있는 적합한 물자를 모으는 일을 돕도록 하게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8796] = {title = "얼라이언스 지원자 모집!", objective = "아이언포지의 군사 지구에 있는 야전사령관 스노우폴과 대화하십시오.", description = "안녕하십니까. 제 부탁을 들어주시겠다니 고맙습니다. 얼라이언스 연합에서는 안퀴라즈 전쟁을 준비하기 위해 단 한 명의 도움이라도 절실한 상황입니다. 그러니까 당신의 도움이 필요하다는 말입니다! 우리가 대화를 나누고 있는 지금 이 순간에도 정식으로 임무를 맡은 이들이 코앞에 닥친 전쟁에 필요한 물자를 모으고 있습니다. 그러나 당신의 도움이 없으면 우리의 목표를 달성할 수 없습니다!\n\n물자 보급을 책임지고 있는 야전사령관 스노우폴과 얘기해 보십시오. 어떻게 하시겠습니까? 아제로스의 모든 생명체의 생사가 걸린 전쟁 준비를 도와주시겠습니까?", progress = nil, completion = "만나서 반갑네! 자네와 같이 다가오는 안퀴라즈 전쟁을 준비하기 위해 도움을 주려는 얼라이언스의 일원이 이렇게 많은 것을 보니 기분이 좋군. 이곳의 준비가 완벽할수록 안퀴라즈에 숨어 있는 실리시드와 그들의 사악한 주인들과의 싸움에서 우리의 승리가 보장되는 것이네.\n\n자네도 도움을 주기 위해 이곳에 왔으니 물자 수집을 담당하고 있는 이들과 얘기해 보고 자네가 수집할 수 있는 적합한 물자를 모으는 일을 돕도록 하게나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8797] = {title = "얼라이언스 지원자 모집!", objective = "아이언포지의 군사 지구에 있는 야전사령관 스노우폴과 대화하십시오.", description = "안녕하십니까. 제 부탁을 들어주시겠다니 고맙습니다. 얼라이언스 연합에서는 안퀴라즈 전쟁을 준비하기 위해 단 한 명의 도움이라도 절실한 상황입니다. 그러니까 그대의 도움이 필요하다는 말입니다! 우리가 대화를 나누고 있는 지금 이 순간에도 정식으로 임무를 맡은 이들이 코앞에 닥친 전쟁에 필요한 물자를 모으고 있습니다. 그러나 그대의 도움이 없으면 우리의 목표를 달성할 수 없습니다!\n\n물자 보급을 책임지고 있는 야전사령관 스노우폴과 얘기해 보십시오. 어떻게 하시겠습니까? 아제로스의 모든 생명체의 생사가 걸린 전쟁 준비를 도와주시겠습니까?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8798] = {title = "나만의 기계설인", objective = "이봐요! 그거 알아요?! 당신도 기술자죠! 친구들 골탕먹이는 일을 도와준 것도 고맙고 해서 당신만의 기계설인을 만드는 방법을 가르쳐 드릴게요! 이제 끝없는 재미를 만끽할 수 있을 거예요. 그러니까 저처럼 그 누구라도 겁먹게 할 수 있다는 거죠! 하지만, 그런 재미있는 물건을 만들려면 당연히 재료도 만만치 않게 들겠죠.\n\n<name>, 어때요? 기계설인 만드는 비법을 알고 싶죠?", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n온순한 기계설인"},
[8799] = {title = "오늘의 영웅", objective = "호랑가시나무 보존기에 깊은바다 소금 한 줌과 5골드를 넣으면 보존된 호랑가시나무를 받게 될 것입니다.", description = "흠, 내가 이런 비밀을 자네에게 밝히리라고는 생각지도 않았는데... 그래도 자네가 바로 오늘의 영웅이니까!\n\n매년 이맘때쯤엔 어디서나 싱싱한 호랑가시나무를 볼 수 있지만 오래가지는 못하지. 굴뚝나무 목장조합에서는 호랑가시나무가 절대 상하지 않도록 보존하는 기계를 이용해서 겨울맞이 축제의 분위기를 살리고 여름내 돈벌이를 한다네!\n\n자네가 요리의 대가라면 보존기를 쓸 수 있게 해주지. 단, 깊은바다 소금이 필요할 거야. 그리고 사용료는 1, 2, 3... 5골드로 하지. 아주 싱싱하게 보존된 호랑가시나무 한 묶음을 얻을 수 있을 걸세.", progress = "호랑가시나무 보존기는 처음에는 전혀 움직임이 없어 보이지만, 꼼꼼히 살펴보니 고블린 양식으로 변경된 것 같습니다. 당신의 요리 기술 정도면 이 기계가 어떻게 동작하는지 알 수 있을 것 같습니다.\n\n보존기 안에는 이미 싱싱하게 보존된 호랑가시나무 한 묶음이 보입니다. 기계를 작동하려면 깊은바다 소금 한 줌과 5골드를 넣으면 됩니다.", completion = "보존기가 작동을 시작한 듯 덜컹덜컹 소리와 약간의 증기를 내뿜습니다. 조금 지나자 움직임이 멈추더니 무언가를 예고하려는 듯이 또다시 증기가 몇 번 뿜어져 나옵니다. 마침내 보존기의 문이 열리고 보존된 호랑가시나무 한 묶음이 보입니다!", rewards = "다음과 같은 것들을 받습니다:\n\n보존된 호랑가시나무"},
[8800] = {title = "세나리온 전투장비", objective = "실리더스의 세나리온 요새에 있는 바르구스와 대화하십시오.", description = "전쟁 중에 그대에게 부여되는 임무를 완수하다 보면 대장장이 바르구스를 만나야 할 때가 올 것이오. 그때 임무를 완수하고 받은 휘장을 그에게 보여주시오. 이번 전쟁에 기여한 정도에 따라 그대에게 전투장비를 지급할 거요.", progress = nil, completion = "칼돈이 보냈소? 좋소, 그럼 당신에게 어떤 장비가 필요할지 한번 봅시다.", rewards = nil},
[8801] = {title = "쑨의 유물", objective = "안퀴라즈 사원에 있는 캘레스트라즈에게 쑨의 눈을 가져가야 합니다.", description = "안퀴라즈의 성벽이 흔들리고 있습니다. 이 세계가 생겨나기 전, 태초부터 존재했던 악의 세력이 축출되었습니다.\n\n저주 받을 악마가 남기고 간 흔적을 본다면 당신의 심장은 거의 얼어붙을 것이며, 쑨이 남긴 악의 기운은 죽어서도 느낄 수 있을 것입니다.\n\n당신은 불가능이라고 생각했던 일을 해냈으며, 악마의 눈이 담긴 자루를 잡아채 안전하게 가방에 넣었습니다.\n\n이제 옆 방에 있는 용족에게 그 쑨의 눈을 가지고 가십시오.", progress = "<무릎을 꿇는 캘레스트라즈>\n\n<name>, 그대는 악마의 손에서 우리를 구해냈도다.", completion = "우리는 악마가 완전히 사라졌다는 것이 확인되면 이곳을 빠져나가겠다, &lt;name&gt;. 전설 같은 그대의 여정도 이제 그 끝이 보이는구나.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8802] = {title = "칼림도어의 구세주", objective = "시간의 동굴에 있는 아나크로노스에게 쑨의 눈을 가져가야 합니다.", description = "시간의 동굴로 가라, 영웅이여. 아나크로노스가 그대가 돌아오기를 기다리고 있다. 틀림없이 자신의 주인에게 쑨의 눈을 바치고 싶어할 테니 그에게 쑨의 눈을 건네주도록 하라.", progress = "오, <name>! 드디어 끝났구나...", completion = "이것은 주인님께서 그대에게 남기신 것이다, 용사여. 수천 년에 걸쳐 유물을 모아 놓은 영원의 창고에서 그대가 원하는 것을 마음껏 고르도록 하라.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n죽은 신의 목걸이죽은 신의 망토죽은 신의 반지\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n노즈도르무 혈족 평판 +1000\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8803] = {title = "축제 선물", objective = "선물 상자에 다음과 같은 글귀가 적혀 있습니다.\n\n친애하는 <name>!\n\n온 아제로스에 따뜻한 겨울맞이 축제의 정신과 축하의 환호 소리가 널리 퍼지기를 바라며...\n\n겨울 할아버지", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n축제 선물"},
[8804] = {title = "사막 긴급구호 물자", objective = "실리더스의 세나리온 요새 여관에 있는 캘랜드라스에게 물의 보주, 강력한 해독제, 훈제 사막 경단을 각각 4개씩 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 I도 함께 가져가야 합니다.", description = "세나리온 요새에 지금 신병들이 도착했는데 과연 사막에서 살아남을 수 있느냐가 문제입니다. 경험이 부족한 신병들에게는 맹독을 가진 다양한 생물뿐 아니라 탈수증도 심각한 위협이 될 수 있습니다. 사막 긴급구호 물자로 쓸만한 물건들을 모아서 세나리온 요새에 있는 캘랜드라스에게 가져가십시오.", progress = "제게 전달할 물건이 있지 않나요?", completion = "정말 잘됐군요! 마침 이것들이 절실하게 필요하던 참이었는데... 감사합니다, &lt;name&gt;.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8805] = {title = "경비대에 장화 공급", objective = "실리더스의 세나리온 요새에 있는 경비대장 비쉬 코주스에게 화려한 미스릴 장화 3개와 병참 임무 지령 II를 가져가야 합니다.", description = "세나리온 요새를 수호하는 기병대에 화려한 미스릴 장화가 부족하다고 합니다. 화려한 미스릴 장화를 구하는 즉시 세나리온 요새의 경비대장 비쉬 코주스에게 전달해 주십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8806] = {title = "경비대에 연마석 공급", objective = "실리더스의 세나리온 요새에 있는 경비대장 비쉬 코주스에게 강도 높은 연마석, 견고한 연마석, 단단한 연마석을 각각 10개씩 모아서 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 III도 함께 가져가야 합니다.", description = "세나리온 요새 경비대에 연마석이 부족하다고 합니다. 연마석을 구하는 즉시 세나리온 요새의 경비대장 비쉬 코주스에게 전달해 주십시오.", progress = "제게 전달할 물건이 있지 않습니까?", completion = "훌륭하군요. 때마침 연마석이 정말 필요하던 상황이었습니다. &lt;name&gt;, 정말 수고하셨습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8807] = {title = "수정점 재료", objective = "실리더스의 세나리온 요새에 있는 지질학자 락스베인에게 눈부신 큰 결정, 찬란하게 빛나는 큰 결정, 거대한 에메랄드를 각각 1개씩 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 V도 함께 가져가야 합니다.", description = "지질학자 락스베인의 연구가 실리더스에서 우리가 수행하는 작전에 엄청난 도움이 된다는 것이 입증되었습니다. 최근에 그녀가 수정점 연구에 사용할 재료를 요청했습니다.\n\n이 재료를 모아서 즉시 그녀에게 가져다주십시오.", progress = "혹시 절 위해 가져오신 물건이 있지 않나요?", completion = "이거예요... 이거라면 굉장한 도움이 될 겁니다! 사막에서 정말 구하기 어려운 재료들이죠! &lt;name&gt;, 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8808] = {title = "제복 공급", objective = "바람소환사 프라우드혼에게 달빛 옷감 1개, 룬무늬 두루마리 2개, 강철그물 거미줄 1개를 가져가야 합니다. 또한, 이 임무를 완료하려면 병참 임무 지령 VIII도 함께 가져가야 합니다.", description = "최근에 들어온 지원자들에게 지급할 제복이 부족합니다. 제복을 만들 재료를 구해서 바람소환사 프라우드혼에게 가져다주십시오.", progress = "절 위해 가져오신 물건이 있지 않습니까?", completion = "제때 와주셨군요. 이 재료들이 절실하게 필요하던 상황이었습니다. &lt;name&gt;, 도와주셔서 감사합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8809] = {title = "특별한 재료", objective = "실리더스의 세나리온 요새에 있는 바르구스에게 마력 깃든 토륨 주괴 2개, 마력 깃든 가죽 2개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 IX도 함께 가져가야 합니다.", description = "세나리온 요새의 대장장이 바르구스가 우리 군대가 쓸 강력한 무기에 마력을 부여할 재료를 요청했습니다. 세나리온 요새의 군대가 완전 무장할 수 있도록 이 재료들을 구하는 즉시 바르구스에게 가져다주십시오.", progress = "내게 가져온 물건이 있지 않소?", completion = "바로 이거요. 품질이 아주 우수한 재료들이군... 고맙소, &lt;name&gt;.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장병참 임무"},
[8810] = {title = "전장에 붕대 공급", objective = "실리더스 세나리온 요새에 있는 바람소환사 프라우드혼에게 두꺼운 룬매듭 붕대, 두꺼운 마법 붕대, 두꺼운 비단 붕대를 각각 30개씩 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 X도 함께 가져가야 합니다.", description = "전장에서 최근 발생한 부상자로 인해 붕대가 많이 부족하다고 합니다. 응급 치료에 쓰는 붕대를 구해 세나리온 요새에 있는 바람소환사 프라우드혼에게 전달해 주십시오.", progress = "<name>, 제게 전달할 물건이 있지 않나요?", completion = "제때 와주셨군요. 이 붕대 덕분에 여러 목숨 살릴 수 있겠습니다. 감사합니다! 자, 다음번에 맡아 주실 임무입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8811] = {title = "무공 훈장 1개", objective = "무공 훈장이 하나뿐인 모험가들을 위해 저는 훈장 하나를 주면 다르나서스에서 약간의 인정을 받게 해 주고 있습니다.\n\n하지만 10개를 한꺼번에 건네는 것이 더 좋다는 것을 명심하십시오. 그렇게 하는 것이 훨씬 더 크게 인정을 받을 수 있는 길입니다. 우리는 훈장 10개를 모으지 못한 이들을 위해 봉사한다는 마음으로 훈장 1개씩도 교환해 주고 있는 것입니다.\n\n자, 지금까지의 얘기를 다 듣고도 하나뿐인 훈장을 교환하고 싶다면 말만 하십시오. 언제든 도와 드릴 준비가 되어 있습니다.", description = nil, progress = "무공 훈장이 하나뿐인 모험가들을 위해 저는 훈장 하나를 주면 다르나서스에서 약간의 인정을 받게 해 주고 있습니다.\n\n하지만 10개를 한꺼번에 건네는 것이 더 좋다는 것을 명심하십시오. 그렇게 하는 것이 훨씬 더 크게 인정을 받을 수 있는 길입니다. 우리는 훈장 10개를 모으지 못한 이들을 위해 봉사한다는 마음으로 훈장 1개씩도 교환해 주고 있는 것입니다.\n\n자, 지금까지의 얘기를 다 듣고도 하나뿐인 훈장을 교환하고 싶다면 말만 하십시오. 언제든 도와 드릴 준비가 되어 있습니다.", completion = "아주 잘하셨습니다. 그대가 세운 공을 기록했으니 노력한 만큼 정당한 인정을 받을 것입니다. 계속 분발해 주십시오.\n\n훈장을 더 구해 오시면 언제든 도와드리겠습니다.", rewards = nil},
[8812] = {title = "무공 훈장 1개", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8813] = {title = "무공 훈장 1개", objective = "무공 훈장이 하나뿐인 모험가들을 위해 저는 훈장 하나를 주면 아이언포지에서 약간의 인정을 받게 해 드리고 있습니다.\n\n하지만 10개를 한꺼번에 건네는 것이 더 좋다는 것을 잊지마세요. 그렇게 하는 것이 훨씬 더 크게 인정을 받을 수 있는 길입니다. 우리는 훈장 10개를 모으지 못한 이들을 위해 봉사한다는 마음으로 훈장 1개씩도 교환해 드리고 있습니다.\n\n자, 지금까지의 얘기를 다 듣고도 하나뿐인 훈장을 교환하고 싶다면 말만 하십시오. 언제든 도와 드릴 준비가 되어 있습니다.", description = nil, progress = "무공 훈장이 하나뿐인 모험가들을 위해 저는 훈장 하나를 주면 아이언포지에서 약간의 인정을 받게 해 드리고 있습니다.\n\n하지만 10개를 한꺼번에 건네는 것이 더 좋다는 것을 잊지마세요. 그렇게 하는 것이 훨씬 더 크게 인정을 받을 수 있는 길입니다. 우리는 훈장 10개를 모으지 못한 이들을 위해 봉사한다는 마음으로 훈장 1개씩도 교환해 드리고 있습니다.\n\n자, 지금까지의 얘기를 다 듣고도 하나뿐인 훈장을 교환하고 싶다면 말만 하십시오. 언제든 도와 드릴 준비가 되어 있습니다.", completion = "아주 잘하셨습니다. 당신이 세운 공을 기록했으니 노력한 만큼 정당한 인정을 받을 것입니다. 계속 분발해 주십시오.\n\n훈장을 더 구해 오시면 언제든 도와드리겠습니다.", rewards = nil},
[8814] = {title = "무공 훈장 1개", objective = "아주 잘하셨습니다. 당신이 세운 공을 기록했으니 노력한 만큼 정당한 인정을 받을 것입니다. 계속 분발해 주십시오.\n\n훈장을 더 구해 오시면 언제든 도와드리겠습니다.", description = nil, progress = nil, completion = nil, rewards = nil},
[8815] = {title = "무공 훈장 1개", objective = "전 무공 훈장이 하나뿐인 모험가들이라도 오그리마로부터 약간의 인정을 받도록 선처를 베풀고 있어요.\n\n하지만, 한꺼번에 10개를 주는 것이 더 좋다는 걸 명심하세요. 그러면 훨씬 더 큰 인정을 받을 수 있으니까요. 사실 무공 훈장 10개를 아직 모으지 못한 이들을 위해 관대한 마음으로 하나씩 받아주고 있는 거지요.\n\n자, 제 얘기를 다 듣고도 하나뿐인 무공 훈장을 바치고 싶다면 말씀만 하세요. 언제든 받아줄 준비는 되어 있으니까.", description = nil, progress = "전 무공 훈장이 하나뿐인 모험가들이라도 오그리마로부터 약간의 인정을 받도록 선처를 베풀고 있어요.\n\n하지만, 한꺼번에 10개를 주는 것이 더 좋다는 걸 명심하세요. 그러면 훨씬 더 큰 인정을 받을 수 있으니까요. 사실 무공 훈장 10개를 아직 모으지 못한 이들을 위해 관대한 마음으로 하나씩 받아주고 있는 거지요.\n\n자, 제 얘기를 다 듣고도 하나뿐인 무공 훈장을 바치고 싶다면 말씀만 하세요. 언제든 받아줄 준비는 되어 있으니까.", completion = "아주 좋아요. 당신이 세운 공적은 잘 기록해두었으니 노력한 만큼 정당한 인정을 받으실 거예요. &lt;class&gt;|1이여;여;, 계속 힘써 주세요.\n\n무공 훈장을 더 구해 온다면 언제든 받을게요.", rewards = nil},
[8816] = {title = "무공 훈장 1개", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8817] = {title = "무공 훈장 1개", objective = "나는 무공 훈장이 하나뿐인 모험가들이라도 언더시티로부터 약간의 인정을 받도록 선처를 베풀고 있네.\n\n하지만, 한꺼번에 10개를 주는 것이 더 좋다는 걸 명심하게. 그러면 훨씬 더 큰 인정을 받을 수 있으니까. 사실 무공 훈장 10개를 아직 모으지 못한 이들을 위해 관대한 마음으로 하나씩 받아주고 있는 것이지.\n\n자, 내 얘기를 다 듣고도 하나뿐인 무공 훈장을 바치고 싶다면 말만 하게. 언제든 받아줄 준비는 되어 있으니까.", description = nil, progress = "나는 무공 훈장이 하나뿐인 모험가들이라도 언더시티로부터 약간의 인정을 받도록 선처를 베풀고 있네.\n\n하지만, 한꺼번에 10개를 주는 것이 더 좋다는 걸 명심하게. 그러면 훨씬 더 큰 인정을 받을 수 있으니까. 사실 무공 훈장 10개를 아직 모으지 못한 이들을 위해 관대한 마음으로 하나씩 받아주고 있는 것이지.\n\n자, 내 얘기를 다 듣고도 하나뿐인 무공 훈장을 바치고 싶다면 말만 하게. 언제든 받아줄 준비는 되어 있으니까.", completion = "아주 잘했네. 자네가 세운 공적은 잘 기록해두었으니 노력한 만큼 정당한 인정을 받을 것이네. 계속 힘써 주게.\n\n무공 훈장을 더 구해 온다면 언제든 받아주겠네.", rewards = nil},
[8818] = {title = "무공 훈장 1개", objective = "전 무공 훈장이 하나뿐인 모험가들이라도 썬더 블러프로부터 약간의 인정을 받도록 선처를 베풀고 있습니다.\n\n하지만, 한꺼번에 10개를 주는 것이 더 좋다는 걸 명심하십시오. 그러면 훨씬 더 큰 인정을 받을 수 있으니까요. 사실 무공 훈장 10개를 아직 모으지 못한 이들을 위해 관대한 마음으로 하나씩 받아주고 있는 거지요.\n\n자, 제 얘기를 다 듣고도 하나뿐인 무공 훈장을 바치고 싶다면 말씀만 하십시오. 언제든 받아줄 준비는 되어 있으니까요.", description = nil, progress = "전 무공 훈장이 하나뿐인 모험가들이라도 썬더 블러프로부터 약간의 인정을 받도록 선처를 베풀고 있습니다.\n\n하지만, 한꺼번에 10개를 주는 것이 더 좋다는 걸 명심하십시오. 그러면 훨씬 더 큰 인정을 받을 수 있으니까요. 사실 무공 훈장 10개를 아직 모으지 못한 이들을 위해 관대한 마음으로 하나씩 받아주고 있는 거지요.\n\n자, 제 얘기를 다 듣고도 하나뿐인 무공 훈장을 바치고 싶다면 말씀만 하십시오. 언제든 받아줄 준비는 되어 있으니까요.", completion = "좋습니다. 당신이 세운 공적은 잘 기록해두었으니 노력한 만큼 정당한 인정을 받으실 겁니다. 계속 힘써 주십시오.\n\n무공 훈장을 더 구해 온다면 언제든 받도록 하겠습니다.", rewards = nil},
[8819] = {title = "무공 훈장 10개", objective = "저는 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있습니다. 제게 무공 훈장 10개를 줄 때마다 다르나서스에서는 그대가 세운 공적을 크게 인정하도록 해 드리겠습니다. 무공 훈장을 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못할 것입니다. 우리는 임무 수행에서 큰 공을 세운 이들일수록 더 많은 관심을 기울이고 있습니다. 공을 세우지 못한 자들은 무시당하게 될 것입니다.\n\n자, 지금까지 말한 걸 잘 새겨들으셨을 테니 훈장 10개를 가져오시면 기꺼운 마음으로 받겠습니다.", description = nil, progress = "저는 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있습니다. 제게 무공 훈장 10개를 줄 때마다 다르나서스에서는 그대가 세운 공적을 크게 인정하도록 해 드리겠습니다. 무공 훈장을 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못할 것입니다. 우리는 임무 수행에서 큰 공을 세운 이들일수록 더 많은 관심을 기울이고 있습니다. 공을 세우지 못한 자들은 무시당하게 될 것입니다.\n\n자, 지금까지 말한 걸 잘 새겨들으셨을 테니 훈장 10개를 가져오시면 기꺼운 마음으로 받겠습니다.", completion = "훌륭하군요! 이 훈장을 얻기 위해 얼마나 고생이 많으셨습니까? 그대의 공로에 대해 정당한 인정을 받게 될 것입니다. 진정으로 이 세계에 도움이 되는 것은 그대와 같은 모험가들이랍니다.\n\n훈장을 더 구하게 되거든 제게 알려 주십시오. 그대가 교환하려는 게 무엇이든 간에 기꺼이 도와드리겠습니다.", rewards = nil},
[8820] = {title = "무공 훈장 10개", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8821] = {title = "무공 훈장 10개", objective = "저는 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있습니다. 제게 무공 훈장 10개를 줄 때마다 아이언포지에서는 당신이 세운 공적을 크게 인정하도록 해 드리겠습니다. 무공 훈장을 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못할 겁니다. 우리는 임무 수행에서 큰 공을 세운 이들일수록 더 많은 관심을 기울이고 있으니까요. 공을 세우지 못한 자들은 무시당하게 될 겁니다.\n\n자, 지금까지 말한 걸 잘 새겨들으셨을 테니 훈장 10개를 가져오시면 기꺼운 마음으로 받도록 하지요.", description = nil, progress = "저는 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있습니다. 제게 무공 훈장 10개를 줄 때마다 아이언포지에서는 당신이 세운 공적을 크게 인정하도록 해 드리겠습니다. 무공 훈장을 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못할 겁니다. 우리는 임무 수행에서 큰 공을 세운 이들일수록 더 많은 관심을 기울이고 있으니까요. 공을 세우지 못한 자들은 무시당하게 될 겁니다.\n\n자, 지금까지 말한 걸 잘 새겨들으셨을 테니 훈장 10개를 가져오시면 기꺼운 마음으로 받도록 하지요.", completion = "훌륭하군요! 이 훈장을 얻기 위해 얼마나 고생이 많으셨습니까? 당신의 공로에 대해 정당한 인정을 받게 될 겁니다. 진정으로 이 세계에 도움이 되는 것은 당신과 같은 모험가들이랍니다.\n\n훈장을 더 구하게 되거든 제게 알려 주십시오. 당신이 교환하려는 게 무엇이든 간에 기꺼이 도와드리겠습니다.", rewards = nil},
[8822] = {title = "무공 훈장 10개", objective = "저는 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있습니다. 제게 무공 훈장 10개를 줄 때마다 스톰윈드에서는 당신이 세운 공적을 크게 인정하도록 해 드리겠습니다. 무공 훈장을 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못할 겁니다. 우리는 임무 수행에서 큰 공을 세운 이들일수록 더 많은 관심을 기울이고 있으니까요. 공을 세우지 못한 자들은 무시당하게 될 겁니다.\n\n자, 지금까지 말한 걸 잘 새겨들으셨을 테니 훈장 10개를 가져오시면 기꺼운 마음으로 받도록 하지요.", description = nil, progress = "저는 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있습니다. 제게 무공 훈장 10개를 줄 때마다 스톰윈드에서는 당신이 세운 공적을 크게 인정하도록 해 드리겠습니다. 무공 훈장을 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못할 겁니다. 우리는 임무 수행에서 큰 공을 세운 이들일수록 더 많은 관심을 기울이고 있으니까요. 공을 세우지 못한 자들은 무시당하게 될 겁니다.\n\n자, 지금까지 말한 걸 잘 새겨들으셨을 테니 훈장 10개를 가져오시면 기꺼운 마음으로 받도록 하지요.", completion = "훌륭하군요! 이 훈장을 얻기 위해 얼마나 고생이 많으셨습니까? 당신의 공로에 대해 정당한 인정을 받게 될 겁니다. 진정으로 이 세계에 도움이 되는 것은 당신과 같은 모험가들이랍니다.\n\n훈장을 더 구하게 되거든 제게 알려 주십시오. 당신이 교환하려는 게 무엇이든 간에 기꺼이 도와드리겠습니다.", rewards = nil},
