[8824] = {title = "무공 훈장 10개", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8825] = {title = "무공 훈장 10개", objective = "전 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있습니다. 제게 무공 훈장 10개를 줄 때마다 썬더 블러프에서는 당신을 크게 인정할 겁니다. 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못하지요. 우리는 큰 공을 세운 이들에게 더 관심이 있으니까요. 그래도 아무리 작은 공적이라도 무시하지는 않는답니다.\n\n자, 지금까지 제 말을 잘 알아들었을 테니 무공 훈장 10개를 가져온다면 기꺼운 마음으로 받겠습니다.", description = nil, progress = "전 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있습니다. 제게 무공 훈장 10개를 줄 때마다 썬더 블러프에서는 당신을 크게 인정할 겁니다. 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못하지요. 우리는 큰 공을 세운 이들에게 더 관심이 있으니까요. 그래도 아무리 작은 공적이라도 무시하지는 않는답니다.\n\n자, 지금까지 제 말을 잘 알아들었을 테니 무공 훈장 10개를 가져온다면 기꺼운 마음으로 받겠습니다.", completion = "훌륭해요! 이 무공 훈장을 얻기까지 얼마나 고생이 많으셨습니까? 당신은 공로에 대한 정당한 인정을 받게 될 겁니다. 진정으로 이 세계에 도움이 되는 것은 당신 같은 모험가들이지요, &lt;name&gt;.\n\n무공 훈장을 더 구하거든 제게 알려 주십시오. 당신이 얻고 싶은 게 무엇이든 간에 기꺼이 돕겠습니다.", rewards = nil},
[8826] = {title = "무공 훈장 10개", objective = "난 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있네. 내게 무공 훈장 10개를 줄 때마다 언더시티에서는 자네를 크게 인정할 거야. 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못할 걸세. 우리는 큰 공을 세운 이들에게 더 관심이 있으니까. 그래도 아무리 작은 공적이라도 무시하지는 않지.\n\n자, 지금까지 내 말을 잘 알아들었을 테니 무공 훈장 10개를 가져온다면 기꺼운 마음으로 받겠네.", description = nil, progress = "난 모험가들이 임무를 수행하면서 얻은 무공 훈장을 받고 있네. 내게 무공 훈장 10개를 줄 때마다 언더시티에서는 자네를 크게 인정할 거야. 1개도 받기는 하지만 그 정도로는 아주 작은 인정밖에 받지 못할 걸세. 우리는 큰 공을 세운 이들에게 더 관심이 있으니까. 그래도 아무리 작은 공적이라도 무시하지는 않지.\n\n자, 지금까지 내 말을 잘 알아들었을 테니 무공 훈장 10개를 가져온다면 기꺼운 마음으로 받겠네.", completion = "훌륭하군! 이 무공 훈장을 얻기까지 얼마나 고생이 많았나? 자네는 공로에 대한 정당한 인정을 받게 될 걸세. 진정으로 이 세계에 도움이 되는 것은 자네와 같은 모험가들이라네, &lt;name&gt;.\n\n무공 훈장을 더 구하게 되거든 알려 주게. 자네가 얻고 싶은 게 무엇이든 간에 내 기꺼이 도와줌세.", rewards = nil},
[8827] = {title = "겨울 할아버지의 선물", objective = "겨울 할아버지와 대화하십시오. 아이언포지의 굴뚝나무 목장조합 상인 근처로 가면 만날 수 있을 것입니다.", description = "겨울 할아버지가 우리 도시에 오셨습니다! 우리 모두를 위해 굴뚝나무 목장조합에서 공들여 만든 선물을 아이언포지의 커다란 나무 아래 놓아두었다고 합니다. 저도 어서 가보고 싶지만 PX-238 겨울 원더볼트를 돌봐야 해서요.\n\n하지만, 당신은 어서 가보셔야지요! 겨울 할아버지의 선물 중에는 분명 당신 이름이 적혀 있는 것도 있을 거예요!", progress = nil, completion = "호호호, 어서 와요! 분명 겨울맞이 축제 선물을 받고 싶어서 왔겠죠!\n\n걱정 마세요. 이 겨울 할아버지 나이가 아무리 많다고 아제로스에서 가장 아끼는 &lt;race&gt; &lt;class&gt;|1을;를; 잊겠어요? 나무 주위를 한 번 둘러보세요. 당신을 위한 선물이 있을 겁니다.\n\n참, 이 사랑과 나눔의 계절에 주위의 친구를 한 번 더 돌아보세요. 친구들도 아마 굴뚝나무 목장조합에서 나눠드리는 멋진 선물을 받고 싶어할 테니까요!", rewards = nil},
[8828] = {title = "겨울 할아버지의 선물", objective = "겨울 할아버지와 대화하십시오. 오그리마의 굴뚝나무 목장조합 상인 근처로 가면 만날 수 있을 것입니다.", description = "겨울 할아버지가 우리 도시에 오셨네! 우리 모두를 위해 굴뚝나무 목장조합에서 공들여 만든 선물을 오그리마의 커다란 나무 아래 놓아두었다는군. 나도 어서 가보고 싶지만 PX-238 겨울 원더볼트를 돌봐야 해.\n\n하지만, 자넨 어서 가봐야지! 겨울 할아버지의 선물 중에는 분명 자네 이름이 적혀 있는 것도 있을 거야!", progress = nil, completion = "호호호, 어서 와요! 분명 겨울맞이 축제 선물을 받고 싶어서 왔겠죠!\n\n걱정 마세요. 이 겨울 할아버지 나이가 아무리 많다고 아제로스에서 가장 아끼는 &lt;race&gt; &lt;class&gt;|1을;를; 잊겠어요? 나무 주위를 한 번 둘러보세요. 당신을 위한 선물이 있을 겁니다.\n\n참, 이 사랑과 나눔의 계절에 주위의 친구를 한 번 더 돌아보세요. 친구들도 아마 굴뚝나무 목장조합에서 나눠드리는 멋진 선물을 받고 싶어할 테니까요!", rewards = nil},
[8829] = {title = "완벽한 속임수", objective = "실리더스의 세나리온 요새에 있는 오렐 골드리프에게 어둠의 허물 1개, 닳아해진 누더기골렘 조각 3개, 황혼의 신도 로브 1개를 가져가야 합니다. 또한, 이 퀘스트를 완료하려면 병참 임무 지령 XI도 함께 가져가야 합니다.", description = "황혼의망치단은 수많은 비밀과 속임수를 통해 작전을 수행하고 있습니다. 그들은 우리 세계에서 활동하고 있지만 한편으로는 우리 손이 아직 미치지 못하는 곳에서 모종의 계획을 꾸미고 있습니다.\n\n우리는 황혼의망치단이 자신들의 우두머리를 소환하는 돌을 이용하면 양방향 이동이 가능하다고 믿고 있습니다. 하지만, 그 돌을 사용하려면 먼저 황혼의망치단 밀사의 로브를 세세한 부분까지 완벽하게 복제해야 합니다.\n\n<name>, 필요한 재료를 모아서 오렐 골드리프에게 가져다주십시오.", progress = "제게 가져오신 물건이 있지 않나요?", completion = "좋아요, 이 정도면 충분할 것 같군요. 이 재료들로 황혼의망치단 밀사가 입고 다니는 것과 똑같은 로브를 만들어 드리겠습니다. 제 솜씨를 빌려 다시 한 번 적들을 속일 수 있게 허락해달라고 엘룬께 기도를 올려야겠습니다.\n\n하지만, 그대는 이런 일에 신경 쓰지 않으셔도 됩니다. 맡은 일을 잘해 주셨으니 보답을 받게 될 것입니다. &lt;name&gt;, 그대는 충실하고 든든한 동맹입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n레물로스의 문장"},
