[8855] = {title = "전쟁 지원 보급품과 무공 훈장 30개 교환", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n안퀴라즈 전쟁 지원 보급품"},
[8856] = {title = "사막 긴급구호 물자", objective = "실리더스의 세나리온 요새 여관에 있는 캘랜드라스에게 물의 보주, 강력한 해독제, 훈제 연어를 각각 4개씩 가져가야 합니다.", description = "세나리온 요새에 지금 신병들이 도착했는데 과연 사막에서 살아남을 수 있느냐가 문제입니다. 경험이 부족한 신병들에게는 맹독을 가진 다양한 생물뿐 아니라 탈수증도 심각한 위협이 될 수 있습니다. 사막 긴급구호 물자로 쓸만한 물건들을 모아서 세나리온 요새에 있는 캘랜드라스에게 가져가십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n세나리온 병참 휘장추가 병참 임무"},
[8857] = {title = "거대괴수의 비밀 - 아쉬", objective = "무법항에 있는 오글소프 오브노티쿠스에게 아쉬 거대괴수의 껍질을 가져가야 합니다.", description = "저는 아쉬 거대괴수의 시체에서 채취한 신선한 껍질 표본을 무법항에 있는 오글소프에게 가져다줄 의지와 능력을 갖춘 전투에 강한 모험가들을 찾고 있습니다. 아니, 아니, 당신보고 그 시체에서 표본을 채취하라는 것이 아닙니다. 당신은 제 표본 중에 하나를 가지고 가시면 됩니다. 이것들이 썩어 버리면 소용없어지니까요!", progress = "뭘 가져온 거요?", completion = "오, 이 놀라운 껍질을 이용해 솜씨를 발휘해 봐야겠군! 수고했소, 친구!", rewards = "다음과 같은 것들을 받습니다:\n\n거대괴수의 전리품 가방"},
[8858] = {title = "거대괴수의 비밀 - 레갈", objective = "이글거리는 협곡에 있는 감독관 오일피스트에게 레갈 거대괴수의 껍질을 가져가야 합니다.", description = "오일피스트에게 이 벌레 껍질을 꼭 전달해야 합니다. 그것 말고는 더 바랄 게 없는데 말입니다. 저는 여기 있으면서 성장한 벌레의 표본을 수집해야 해서 직접 갈 수가 없습니다. 벌레가 그 정도로 성장하려면 이른 아침까지 여기서 기다려야 하거든요.\n\n제 대신 이 표본을 오일피스트에게 속히 전해 주시면 그가 큰 보상을 해 줄 것입니다!\n\n네, 맞습니다. 오일피스트는 이글거리는 협곡 안의 토륨 조합 거점에 있을 겁니다.", progress = "흠...", completion = "아주 좋아. 이 껍질을 이용해서 가공할 만한 갑옷을 만들 수 있겠군. 여기 약속한 보상이네.", rewards = "다음과 같은 것들을 받습니다:\n\n거대괴수의 전리품 가방"},
[8859] = {title = "거대괴수의 비밀 - 조라", objective = "동부 역병지대의 희망의 빛 예배당에 있는 맥스웰 티로서스 경에게 조라 거대괴수의 껍질을 가져가야 합니다.", description = "제 부하들이 이 표본을 구하느라 거의 죽을 뻔했습니다. 맥스웰 티로서스 경이 신선한 껍질 표본을 눈이 빠져라 기다리고 있으니 서둘러야 합니다! 그는 이 거대괴수의 비밀이 스컬지와의 전쟁에서 도움이 될 거라 믿고 있습니다!\n\n아직도 안 가고 뭐 하십니까!? 희망의 빛 예배당으로 가십시오! 예, 이 일만 잘해 주시면 후한 보상이 있을 겁니다...", progress = "이봐 친구, 뭔가를 가져온 것 같군.", completion = "정말 시기적절하게 와 줬군! 수고했네.", rewards = "다음과 같은 것들을 받습니다:\n\n거대괴수의 전리품 가방"},
[8860] = {title = "신년맞이 축하행사!", objective = "스톰윈드에 있는 여관주인 앨리슨에게 굴뚝나무 보급품을 가져가야 합니다.", description = "스톰윈드에서 신년맞이 축하행사가 열리고 있다네! 하루종일 공짜 술을 얻을 수 있고, 밤에는 불꽃놀이가 벌어질 거야! 무척 멋질거라고. 또 무법항에서는 오늘 잔치가 열릴 텐데... 정말 굉장할 거야. 내 장담하지!\n\n어쨋거나, 여기 스톰윈드 여관주인 앨리슨이 보급품을 필요로 하고 있어. 굴뚝나무 목장조합에서 벌이는 행사에 오는 모든 친구들을 대접하려고 말일세. 그걸 좀 배달해 주겠나?\n\n고맙다고, <class> 친구! 참, 앨리슨은 스톰윈드의 상업 지구에 있는 황금장미 여관에 있네.", progress = "어서 오세요! 잔치를 즐기러 오셨나요, 손님? 아니면 지친 몸을 쉬러 오신 건가요?", completion = "오, 굴뚝나무 보급품이로군요! 멋져요! 이 보급품은 행사를 축하하기 위해 오실 모든 분들을 대접하는 데 사용할 거랍니다!\n\n감사해요. 보상으로 이걸 받아주세요. 그리고 밖에서 벌어지는 떠들썩한 잔치에서는 춤과 술을 잊지 마세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8861] = {title = "신년맞이 축하행사!", objective = "썬더 블러프에 있는 여관주인 팔라에게 굴뚝나무 보급품을 가져가야 합니다.", description = "썬더 블러프에서 신년맞이 축하행사가 열리고 있다네! 하루종일 공짜 술을 얻을 수 있고, 밤에는 불꽃놀이가 벌어질 거야!\n\n무척 멋질거라고. 또 무법항에서는 오늘 잔치가 열릴 텐데... 정말 굉장할 거야. 내 장담하지!\n\n어쨋거나, 썬더 블러프의 여관주인 팔라가 보급품을 필요로 하고 있어. 굴뚝나무 목장조합에서 벌이는 행사에 모든 친구들을 초대하여 대접하려고 말일세. 그걸 좀 배달해 주겠나?\n\n고맙네, <class> 친구! 참, 팔라는 썬더 블러프 수렵의 봉우리로 가는 구름다리 밑 여관에 있을 걸세.", progress = "안녕하세요! 썬더 블러프에는 신년맞이 축하행사를 즐기러 오셨나요? 아니면 사냥에 지친 발굽을 쉬러 오신 건가요?", completion = "오, 좋아요! 이 보급품으로 새해를 축하하러 모인 친구들을 모두 배불리 먹일 수 있겠군요.\n\n정말 고맙습니다. 이 빚을 어떻게 갚아야 할지... 약소하지만 받아 주세요. 그리고 밖에서 벌어지는 떠들썩한 잔치에서는 흥겨운 춤을 잊지 마세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8862] = {title = "엘룬의 양초", objective = "엘룬의 양초는 달의 축제를 기리는 이들을 위해 숭고한 공경과 헌신의 의미로 제작된 귀한 유물입니다. 양초에는 진짜 달빛이 담겨있으며 눈부신 빛줄기를 뿜어낼 날만을 기다리고 있습니다!\n\n그 빛은 거의 모든 생명체에 아무런 해를 끼치지 않지만 오멘과 그의 수하들에게 비추면 시야를 어지럽게 하고 화상을 입힙니다.", description = nil, progress = "엘룬의 양초는 달의 축제를 기리는 이들을 위해 숭고한 공경과 헌신의 의미로 제작된 귀한 유물입니다. 양초에는 진짜 달빛이 담겨있으며 눈부신 빛줄기를 뿜어낼 날만을 기다리고 있습니다!\n\n그 빛은 거의 모든 생명체에 아무런 해를 끼치지 않지만 오멘과 그의 수하들에게 비추면 시야를 어지럽게 하고 화상을 입힙니다.", completion = "좋습니다. 그럼 전 이 선조의 주화를 받을 테니 그대는 엘룬의 축복이 담긴 이 양초를 가져가십시오. 그리고 이것은 덤으로 드리는 폭죽 세트입니다.\n\n그럼 &lt;name&gt;, 즐겁고 멋진 달의 축제를 맞이하시길 바랍니다.\n\n그리고 오멘과 그의 수하들에게 맞설 생각이라면 이 엘룬의 양초가 꽤 쓸모가 있을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n엘룬의 양초달의 축제 폭죽 세트"},
[8863] = {title = "달의 축제 만두", objective = "배가 고프시다면 제대로 찾아오셨습니다, 친구여!\n\n만두는 우리 달의 축제의 전통 음식으로, 먼 옛날 축제가 처음 개최되었을 때부터 즐겨 먹었지요. 이번에도 달의 축제 만두를 대접할 수 있게 되어 매우 기쁩니다. 선조의 주화 1개만 내면 지금까지 경험하지 못한 최고의 요리 중 하나를 맛볼 기회를 드리겠습니다!", description = nil, progress = "배가 고프시다면 제대로 찾아오셨습니다, 친구여!\n\n만두는 우리 달의 축제의 전통 음식으로, 먼 옛날 축제가 처음 개최되었을 때부터 즐겨 먹었지요. 이번에도 달의 축제 만두를 대접할 수 있게 되어 매우 기쁩니다. 선조의 주화 1개만 내면 지금까지 경험하지 못한 최고의 요리 중 하나를 맛볼 기회를 드리겠습니다!", completion = "달의 축제 만두 맛있게 드세요. 그대의 공적을 생각하면 감사의 표시로 다소 부족할지 모르지만 그래도 탁월한 맛은 충분히 즐기실 수 있을 거예요.\n\n그리고 혹시 선조의 주화가 더 있으면 교환해 드릴 수 있는 다양한 물건이 준비되어 있다는 사실을 기억하시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n달의 축제 만두"},
[8864] = {title = "달의 축제 드레스", objective = "달의 축제에 입고 가실 만한 드레스를 좀 골라 두었습니다. 지난 축제에서 눈여겨본 것 중 최고의 것들만 선택했지요. 모든 드레스는 아주 부드러운 최고급 소재만을 사용해서 손으로 직접 만든 것입니다.\n\n선조의 주화를 조금만 내시면 특별히 그대를 위해 마련해 둔 세 가지 스타일 중 하나를 고르실 수 있습니다. 하나 입어보시겠습니까?", description = nil, progress = "달의 축제에 입고 가실 만한 드레스를 좀 골라 두었습니다. 지난 축제에서 눈여겨본 것 중 최고의 것들만 선택했지요. 모든 드레스는 아주 부드러운 최고급 소재만을 사용해서 손으로 직접 만든 것입니다.\n\n선조의 주화를 조금만 내시면 특별히 그대를 위해 마련해 둔 세 가지 스타일 중 하나를 고르실 수 있습니다. 하나 입어보시겠습니까?", completion = "현명한 선택입니다. 그럼 전 선조의 주화를 받을 테니 그대는 드레스를 가져가십시오. 부디 엘룬의 축복이 함께하길 빕니다. 그리고 이것은 덤으로 드리는 폭죽 세트입니다.\n\n선조의 영광을 빛내는 그대와 같은 분이 저를 찾아주시다니 그것만으로도 큰 영광입니다. 감사합니다. 즐거운 달의 축제를 맞이하시길...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n녹색 축제 드레스분홍색 축제 드레스보라색 축제 드레스\n\n다음과 같은 것들 또한 받습니다:\n\n달의 축제 폭죽 세트"},
[8865] = {title = "달의 축제 의상", objective = "달의 축제에 입을 멋진 의상을 장만할 절호의 기회를 드립니다. 단, 공짜는 아니고 선조의 주화를 받고 있습니다. 유행을 조금이라도 아는 분이라면 바로 이런 옷을 찾고 계셨을 겁니다! 아제로스 어디를 가도 이렇게 멋진 의상은 없을 거라 장담합니다.\n\n선조의 주화를 조금만 내시면 소중한 그대를 위해 마련해 둔 세 가지 스타일 중 하나를 고를 수 있습니다. 자, 하나 입어보시겠습니까?", description = nil, progress = "달의 축제에 입을 멋진 의상을 장만할 절호의 기회를 드립니다. 단, 공짜는 아니고 선조의 주화를 받고 있습니다. 유행을 조금이라도 아는 분이라면 바로 이런 옷을 찾고 계셨을 겁니다! 아제로스 어디를 가도 이렇게 멋진 의상은 없을 거라 장담합니다.\n\n선조의 주화를 조금만 내시면 소중한 그대를 위해 마련해 둔 세 가지 스타일 중 하나를 고를 수 있습니다. 자, 하나 입어보시겠습니까?", completion = "현명한 선택입니다. 그럼, 전 선조의 주화를 받을 테니 그대는 축제 의상을 가져가십시오. 부디 엘룬의 축복이 함께하길 빕니다. 그리고 이것은 덤으로 드리는 폭죽 세트입니다.\n\n선조의 주화가 더 있으면 언제든 절 찾아주십시오. 달의 축제 동안 다양한 물건으로 교환하여 드리겠습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n검은색 축제 의상파란색 축제 의상암녹색 축제 의상\n\n다음과 같은 것들 또한 받습니다:\n\n달의 축제 폭죽 세트"},
[8866] = {title = "장로 브론즈비어드", objective = "이 땅의 백성들이 고대의 존재들에게 여전히 경의를 표한다는 사실을 알게 되어 기분이 좋군. 건투를 비네. 그리고 이 징표를 받게...", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n활 쏘기\n\n다음과 같은 것들을 받습니다:\n\n선조의 주화"},
[8867] = {title = "달의 축제 불꽃놀이", objective = "축제 폭죽 8개, 연발탄 폭죽 2개를 발사한 후 수도에 있는 달의 축제 사절에게 돌아가십시오.", description = "달숲에 사는 드루이드들은 우리 도시가 고대의 악마를 상대로 거둔 위대한 승리를 기념하는 축제를 매년 열고 있어요.\n\n우리는 선조들의 지혜를 찬양하고 멋진 만찬을 즐기죠. 그리고... 불꽃놀이도 한답니다!\n\n다채로운 폭죽을 상인에게 구입해서 이곳 주위에 있는 폭죽 발사대에서 사용해 보세요.", progress = "발사대는 찾으셨나요?", completion = "잘하셨어요.\n\n이제 흥이 좀 나셨을 테니 이 초대장을 가지고 달의 숲에서 열리고 있는 축제에 가 보시는 게 어때요?\n\n시간이 좀 있으시다면 정말 즐거운 축제가 될 거예요. 음식, 술, 재미있는 이야기는 물론이고... 다양한 불꽃놀이가 열릴 거예요!\n\n환한 달빛의 원안에 서 있으면 초대가 되어 달의 숲으로 이동될 것입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n달의 축제 초대장"},
[8868] = {title = "엘룬의 축복", objective = "오멘을 소환한 후 그를 처치하여 엘룬의 축복을 얻고 나이트헤이븐에 있는 발라다르 스타송에게 돌아가야 합니다.", description = "야수인 오멘은 한 때 이 세계의 영웅이었습니다. 대단한 힘과 행운을 지닌 늑대인 오멘은 악마의 마법에 굴복당하기 전까지 고대 전쟁의 영웅들의 곁에서 싸웠답니다. 악마의 마법에 의해 타락한 오멘은 그의 동지들에게 대항하게 되고, 아제로스에 대한 분노로 가득 차 죽음과 공포를 불러왔습니다.\n\n마침내 이곳 달숲에서 패배한 오멘은 지금 엘룬아라 호수 바닥에 잠들어 있습니다. 그러나 매 새해 축제 기간이 되면 그가 움직인답니다...\n\n동료들을 모아 야수 오멘을 소환하여 처치하십시오. 여신이신 엘룬님의 축복을 얻으십시오!", progress = nil, completion = "잘하셨습니다. 오멘을 처치하여 그의 영혼은 엘룬아라의 흐르는 물로 돌아갔습니다. 그 야수가 엘룬께 축복을 받아 죽을 수는 없지만 그의 분노는 해가 지나도 가라앉지 않을 것입니다.\n\n그대의 승리는 오멘과 그대와 그대의 동료들의 힘의 의식이자, 우리의 지난 비극적인 이 영웅에게 그대가 준 평화의 의식이랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n엘룬의 등불달의 축제 폭죽 세트견고한 암석"},
[8869] = {title = "진홍십자군 작업복", objective = "스트라솔름으로 가서 진홍십자군 대장장이를 처치하고 진홍십자군 대장장이의 작업복을 가지고 릴리스에게 돌아가야 합니다.", description = "붉은십자군 성채 안에는 대장기술 도면이 있어요. 진홍십자군 대장장이가 그 도면을 사수하는데, 그를 물리치고 그의 작업복을 가져오면 제가 망치 만드는 법을 가르쳐 드리죠.\n\n하지만, 잘 알아 두세요. 한번 망치 제작의 길에 들어서면 검이나 도끼 제작과는 영영 이별이라는 사실을...다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n망치 제작의 대가\n\n다음과 같은 것들을 받습니다:\n\n도면: 마력 깃든 전투망치"},
[8870] = {title = "달의 축제", objective = "아이언포지의 마법 지구에 있는 달의 축제 사절과 대화해야 합니다. 또한 다른 대도시에 있는 달의 축제 사절과 대화해도 무방합니다.", description = "한 해의 시작을 맞이하는 날이 돌아왔습니다! 세나리온 의회에서는 아제로스의 모든 친구들을 달의 축제에 초대한답니다. 그대는 이 도시 안에 달빛의 축복을 받은 원이 그려진 곳에서 달의 축제 사절을 만나게 될 겁니다. 그녀가 축제에 대해서 더 말해줄 수 있을 겁니다.", progress = nil, completion = "환영해요. 저희 축제에 참여하러 오신 거로군요?", rewards = nil},
[8871] = {title = "달의 축제", objective = "스톰윈드의 공원에 있는 달의 축제 사절과 대화해야 합니다. 또한 다른 대도시에 있는 달의 축제 사절과 대화해도 무방합니다.", description = "한 해의 시작을 맞이하는 날이 돌아왔습니다! 세나리온 의회에서는 아제로스의 모든 친구들을 달의 축제에 초대한답니다. 그대는 이 도시 안에 달빛의 축복을 받은 원이 그려진 곳에서 달의 축제 사절을 만나게 될 겁니다. 그녀가 축제에 대해서 더 말해줄 수 있을 겁니다.", progress = nil, completion = "환영해요. 저희 축제에 참여하러 오신 거로군요?", rewards = nil},
[8872] = {title = "달의 축제", objective = "다르나서스의 세나리온 자치령에 있는 달의 축제 사절과 대화해야 합니다. 또한 다른 대도시에 있는 달의 축제 사절과 대화해도 무방합니다.", description = "한 해의 시작을 맞이하는 날이 돌아왔습니다! 세나리온 의회에서는 아제로스의 모든 친구들을 달의 축제에 초대한답니다. 그대는 이 도시 안에 달빛의 축복을 받은 원이 그려진 곳에서 달의 축제 사절을 만나게 될 겁니다. 그녀가 축제에 대해서 더 말해줄 수 있을 겁니다.", progress = nil, completion = "환영해요. 저희 축제에 참여하러 오신 거로군요?", rewards = nil},
[8873] = {title = "달의 축제", objective = "오그리마의 지혜의 골짜기에 있는 달의 축제 사절과 대화해야 합니다. 또한 다른 대도시에 있는 달의 축제 사절과 대화해도 무방합니다.", description = "한 해의 시작을 맞이하는 날이 돌아왔습니다! 세나리온 의회에서는 아제로스의 모든 친구들을 달의 축제에 초대한답니다. 그대는 이 도시 안에 달빛의 축복을 받은 원이 그려진 곳에서 달의 축제 사절을 만나게 될 겁니다. 그녀가 축제에 대해서 더 말해줄 수 있을 겁니다.", progress = nil, completion = "환영해요. 저희 축제에 참여하러 오신 거로군요?", rewards = nil},
[8874] = {title = "달의 축제", objective = "언더시티의 입구에 있는 달의 축제 사절과 대화해야 합니다. 또한 다른 대도시에 있는 달의 축제 사절과 대화해도 무방합니다.", description = "한 해의 시작을 맞이하는 날이 돌아왔습니다! 세나리온 의회에서는 아제로스의 모든 친구들을 달의 축제에 초대한답니다. 그대는 이 도시 안에 달빛의 축복을 받은 원이 그려진 곳에서 달의 축제 사절을 만나게 될 겁니다. 그녀가 축제에 대해서 더 말해줄 수 있을 겁니다.", progress = nil, completion = "환영해요. 저희 축제에 참여하러 오신 거로군요?", rewards = nil},
[8875] = {title = "달의 축제", objective = "썬더 블러프 장로의 봉우리에 있는 달의 축제 사절과 대화해야 합니다. 또한, 다른 대도시에 있는 달의 축제 사절과 대화해도 무방합니다.", description = "한 해의 시작을 맞이하는 날이 돌아왔습니다! 세나리온 의회에서는 아제로스의 모든 친구를 달의 축제에 초대합니다. 그대는 이 도시 안에 달빛의 축복을 받은 원이 그려진 곳에서 달의 축제 사절을 만나게 될 겁니다. 그녀가 축제에 대해서 더 자세히 말해줄 수 있을 겁니다.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[8876] = {title = "작은 폭죽", objective = "저는 달의 축제에 쓸 폭죽을 만드는 비법을 알고 있습니다. 축제의 의미를 기릴 줄 아는 분이라면 그 귀한 지식을 함께 나누고 싶군요.\n\n선조의 주화를 가져오면 작은 폭죽을 만들 설계도를 드리겠습니다.", description = nil, progress = "저는 달의 축제에 쓸 폭죽을 만드는 비법을 알고 있습니다. 축제의 의미를 기릴 줄 아는 분이라면 그 귀한 지식을 함께 나누고 싶군요.\n\n선조의 주화를 가져오면 작은 폭죽을 만들 설계도를 드리겠습니다.", completion = "이 주화는 잘 받겠어요. 여기 설계도를 받으십시오. 부디 엘룬의 축복이 &lt;name&gt;, 그대와 함께하기를...", rewards = "다음과 같은 것들을 받습니다:\n\n작은 폭죽 설계도달의 축제 폭죽 세트"},
[8877] = {title = "폭죽 발사대", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n설계도: 폭죽 발사대달의 축제 폭죽 세트"},
[8878] = {title = "축제 의복 도안", objective = "드레스를 비롯한 축제 의상은 오랜 세월 전부터 내려온 우리의 전통 의상이지요. 우리는 달의 축제가 오면 전통과 선대를 기리기 위해 그런 특별한 옷을 입는답니다.\n\n선조의 주화를 가져오면 전통적인 빨간색 축제 드레스나 의상을 만들 도안으로 바꿔 드리겠습니다.", description = nil, progress = "드레스를 비롯한 축제 의상은 오랜 세월 전부터 내려온 우리의 전통 의상이지요. 우리는 달의 축제가 오면 전통과 선대를 기리기 위해 그런 특별한 옷을 입는답니다.\n\n선조의 주화를 가져오면 전통적인 빨간색 축제 드레스나 의상을 만들 도안으로 바꿔 드리겠습니다.", completion = "여기 도안을 받으십시오. 이 비법으로 만든 물건을 입으면 축제 인파 중에서도 꽤 돋보이리라 장담합니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n도안: 축제 드레스도안: 축제 의상\n\n다음과 같은 것들 또한 받습니다:\n\n달의 축제 폭죽 세트"},
[8879] = {title = "큰 폭죽", objective = "큰 폭죽은 새해가 밝아올 하늘을 찬란하게 물들일 겁니다. 그런 장관을 만들 수 있는 건 이 세계에 큰 폭죽과 연발탄 뿐이겠죠!\n\n선조의 주화를 가져오면 큰 폭죽을 만들 비법을 전수해 드리겠습니다.", description = nil, progress = "큰 폭죽은 새해가 밝아올 하늘을 찬란하게 물들일 겁니다. 그런 장관을 만들 수 있는 건 이 세계에 큰 폭죽과 연발탄 뿐이겠죠!\n\n선조의 주화를 가져오면 큰 폭죽을 만들 비법을 전수해 드리겠습니다.", completion = "좋아요. 이 선조의 주화는 잘 받겠습니다. 여기 큰 폭죽 설계도를 받으십시오. 부디 이 물건을 엘룬의 은총을 온 세계에 전파하는 데 사용해 주시기 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n큰 폭죽 설계도달의 축제 폭죽 세트"},
[8880] = {title = "연발탄", objective = "연발탄에는 작은 폭죽이 여러 개 들어가 있어서 그 아름다움은 이루 말할 수 없는 장관을 만듭니다. 선조의 주화를 가져오면 그런 멋진 물건을 만들 비법을 가르쳐 드리겠습니다.", description = nil, progress = "연발탄에는 작은 폭죽이 여러 개 들어가 있어서 그 아름다움은 이루 말할 수 없는 장관을 만듭니다. 선조의 주화를 가져오면 그런 멋진 물건을 만들 비법을 가르쳐 드리겠습니다.", completion = "여기 연발탄 설계도를 드립니다. 잘 보고 배우시길 바랍니다. 풍족한 새해를 맞이하시길 바랍니다. 그리고 세상을 놀라게할만한 물건을 제작하시기를 기원합니다.", rewards = "다음과 같은 것들을 받습니다:\n\n연발탄 설계도달의 축제 폭죽 세트"},
[8881] = {title = "큰 연발탄", objective = "큰 연발탄을 만들려면 재료도 많이 들고 높은 수준의 기술도 필요하지만 그 아름다운 광채 앞에서는 그러한 노고도 봄눈 녹듯 사라지지요. 선조의 주화를 가져오면 큰 연발탄 만드는 비법을 가르쳐 드리겠습니다.", description = nil, progress = "큰 연발탄을 만들려면 재료도 많이 들고 높은 수준의 기술도 필요하지만 그 아름다운 광채 앞에서는 그러한 노고도 봄눈 녹듯 사라지지요. 선조의 주화를 가져오면 큰 연발탄 만드는 비법을 가르쳐 드리겠습니다.", completion = "감사히 받겠습니다. 여기 큰 연발탄 설계도를 받으십시오. 큰 연발탄을 만들어 하늘에 쏘아 올릴 때 그 장관을 지켜본 모두의 눈동자에는 기쁨과 행운에 대한 기대감만이 가득할 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n큰 연발탄 설계도달의 축제 폭죽 세트"},
[8882] = {title = "연발탄 발사대", objective = "달의 축제를 밝힐 멋진 불꽃놀이에 연발탄이 빠질 수는 없지요. 그리고 연발탄을 쏘아 올릴 발사대는 물론이고요! 그대와 같이 현명한 분이라면 연발탄 발사대를 만드는 비법을 배워두는 것이 논리적인 처사라는 것을 아시겠지요? 선조의 주화를 가져오면 제가 그 비법을 알려드리겠습니다.", description = nil, progress = "달의 축제를 밝힐 멋진 불꽃놀이에 연발탄이 빠질 수는 없지요. 그리고 연발탄을 쏘아 올릴 발사대는 물론이고요! 그대와 같이 현명한 분이라면 연발탄 발사대를 만드는 비법을 배워두는 것이 논리적인 처사라는 것을 아시겠지요? 선조의 주화를 가져오면 제가 그 비법을 알려드리겠습니다.", completion = "여기 설계도를 받으십시오. 부디 꼼꼼히 살펴보시기 바랍니다.\n\n행운을 빕니다, &lt;name&gt;. 그대라면 달의 축제에서 최고의 불꽃놀이를 선보일 수 있을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n설계도: 연발탄 발사대달의 축제 폭죽 세트"},
[8883] = {title = "발라다르 스타송", objective = "달빛 안에서 달의 축제 초대장을 사용하여 달숲으로 이동하십시오. 도착하면 나이트헤이븐에 있는 발라다르 스타송과 대화하십시오.", description = "달의 축제 초대장도 받으셨으니 이제 달숲으로 여행을 떠나셔야죠! 거기서 축제를 즐기러 온 구경꾼들이나 다른 모험가 친구들도 만나고 특히 나이트헤이븐 마을로 가면 발라다르 스타송과 그의 누이 파리엘 스타송이 여러분을 진심으로 반길 겁니다.\n\n눈부시도록 환한 달빛의 인도를 받아서 어서 달숲으로 날아가세요. 발라다르 스타송을 만나 이번 달의 축제 기간에 어떤 상품을 받을 수 있나 한번 알아보시고요!", progress = nil, completion = "달의 축제 개최지인 이곳 나이트헤이븐에 오신 걸 환영합니다. 너무 외딴곳이기에 아제로스 백성들이 도통 발길을 들이지 않은 이곳이지만 축제의 계절이 오면 두 팔을 활짝 벌리고 따스한 마음으로 모두를 맞이한답니다.\n\n흥겹고도 상쾌한 이곳의 분위기를 한번 둘러보십시오. 그런 다음 저나 제 누이와도 대화를 나누는 것이 좋을 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8884] = {title = "멀록의 머리", objective = "성난비늘 멀록 머리 8개를 모아서 평온의 해변가 내려다보이는 절벽의 영원노래 숲에 있는 하스벨리온 선게이즈에게 가져가야 합니다.", description = "안녕하시오, <class>|1이여;여;. 저 해안을 한번 보시오. 뭐가 보이시오? 그렇소이다. 우리 해변... 우리의 평온의 해변에 멀록이라는 냄새 나는 놈들이 득실대고 있소.\n\n이 사태를 그냥 보고만 있을 수는 없소!\n\n괜찮다면 한 가지 부탁을 하고 싶소이다. 난 그 물고기 인간들의 수를 줄였으면 하오! 놈들의 수를 크게 줄이면 어떻게 나올지 확인해 보고 싶군. 놈들도 생각이라는 게 있다면 원래 그들의 고향인 깊은 심연으로 되돌아가지 않겠소?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8885] = {title = "아옳옳옳옳옳의 반지", objective = "성난비늘 족장을 처치하여 아옳옳옳옳옳의 반지를 되찾은 후, 평온의 해변이 내려다보이는 절벽의 영원노래 숲에 있는 하스벨리온 선게이즈에게 가져가야 합니다.", description = "그대의 노력에도 성난비늘 멀록들은 조금도 겁을 먹지 않았소. 녀석들을 쫓아내고 사적인 원한을 갚을 방법이 있을 것도 같소.\n\n녀석들에겐 아옳옳옳옳옳이라고 하는 멀록 대장이 있다오. 녀석은 강 후미의 황금 해안 남쪽 해변을 돌아다니고 있소. 그 짐승 같은 놈은 내 동료를 살해한 것도 모자라 조롱하는 의미로 그의 반지를 끼고 있소.\n\n아옳옳옳옳옳을 해치우고 친구의 반지를 되찾아 주시오. 단, 모든 일을 마친 후라도 멀록들이 물러갔는지 확인해 봐야 할 거요!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #23395아이템 #23396아이템 #23397아이템 #23398아이템 #133694\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8886] = {title = "성난비늘 멀록의 약탈!", objective = "선장 켈리센드라의 화물 상자 6개를 되찾은 후, 영원노래 숲에 해돋이 부두의 바로 동쪽, 방어 주둔지에 있는 선장 켈리센드라에게 가져가야 합니다.", description = "도와주신다니 정말 고맙습니다, <class>님! 저 더러운 성난비늘 멀록들이 내 화물을 약탈했지 뭡니까! 버림받은 자들이 내 마법 물품들을 훔쳐간 것으로도 모자라서 나머지는 멀록들이 쓸어가 버렸어요! 대체 세상이 어떻게 돌아가는 걸까요?\n\n내 화물을 되찾아 주실 수 있을까요? 그대가 모두 되찾으리라고는 기대하지 않지만, 지금 상황에서는 어떠한 도움이라도 기꺼이 받겠습니다. 황금 해안을 따라 이곳 부두로부터 남쪽과 서쪽에 있는 오두막에 거처하는 성난비늘 멀록 무리가 범인입니다. 분명하다니까요!", progress = "<name>, 그대와 같은 분이 저를 도와주시니 기뻐서 웃음이 절로 나네요. 하지만, 저 괴물들이 내 배에 무슨 짓을 저질렀는지, 그리고 쿠엘탈라스에 무슨 일이 일어나고 있는지 난 똑똑히 알고 있답니다.\n\n그런데 내 화물은 찾아오셨나요?", completion = "해냈군요! 그대가 날 위기에서 구했고 그 역겨운 녀석들에게 대신 복수를 선사했어요!\n\n이제 이 화물 운반을 도와줄 순찰자 몇 명만 부르면 마침내 여기서 벗어날 수 있습니다! 벨렌드리스가 조선소를 재건하면 돌아와야겠어요.\n\n자, 여기 돈을 좀 드립니다. 그대의 노력에 대한 보상으로 드리는 자그마한 선물이랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8887] = {title = "선장 켈리센드라의 잃어버린 항해도", objective = "선장 켈리센드라의 잃어버린 항해도를 가지고 영원노래 숲의 해돋이 부두의 바로 동쪽 기지로 선장 켈리센드라를 찾아가야 합니다.", description = "재미있게 생긴 물건입니다... 방금 여기서 방수 처리된 가죽으로 만든 통을 발견했습니다. 그 안에는 양피지 몇 장이 들어 있습니다. 양피지에 적힌 기호들을 보아하니 이것은 항해도이며, 각각 선장 켈리센드라의 서명이 적혀 있습니다.\n\n해돋이 부두 근처로 가면 바로 동쪽에 작은 기지가 있다고 합니다. 선장은 아마 그곳에 있지 않을까요?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8888] = {title = "마법학자의 수습생", objective = "영원노래 숲의 더스크위더 첨탑에 있는 수습생 로랄탈리스를 찾아서 대화해야 합니다.<class>|1이여;여;, 내 부탁 좀 들어주시겠소? 내가 들어갈 수 없어서, 가까운 연구소의 문을 닫기로 했다오. 이 일로 며칠 전에 제자 중 한 명인 수습생 로랄탈리스를 보냈는데 그 이후로 아무 소식이 없소.\n\n더스크위더 첨탑으로 가서 그녀가 무사한지 확인해 주겠소? 원정순찰대 산장의 북쪽 길을 따라가다가 갈림길이 나올 때 오른쪽으로 틀면 더스크위더 첨탑을 찾을 수 있을 것이오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "<class>|1이여;여;, 내 부탁 좀 들어주시겠소? 내가 들어갈 수 없어서, 가까운 연구소의 문을 닫기로 했다오. 이 일로 며칠 전에 제자 중 한 명인 수습생 로랄탈리스를 보냈는데 그 이후로 아무 소식이 없소.\n\n더스크위더 첨탑으로 가서 그녀가 무사한지 확인해 주겠소? 원정순찰대 산장의 북쪽 길을 따라가다가 갈림길이 나올 때 오른쪽으로 틀면 더스크위더 첨탑을 찾을 수 있을 것이오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8889] = {title = "첨탑 작동 중지", objective = "더스크위더 첨탑 안에 있는 3개의 더스크위더 첨탑 마력원천의 작동을 중지한 다음, 영원노래 숲에 있는 수습생 로랄탈리스에게 비활성 보석을 가져가야 합니다.", description = "아시다시피 마법학자 더스크위더께서 날 여기로 다시 보내면서 첨탑에 힘을 공급하는 마력원천을 차단하라고 지시하셨답니다. 마력원천은 모두 3개인데 첨탑 내부의 각기 다른 위치에 있습니다.\n\n안타깝게도 난 몸놀림이 아주 둔하답니다. 게다가 더스크위더 첨탑에는 이상한 마법을 쓰는 생물들이 득실거리니... 이 임무를 맡기에는 아무래도 난 부족하지만, 그대 같은 <class>에게는 아주 간단하겠죠?", progress = "멀리서는 확실한 결과를 알 수 없군요... 더스크위더 첨탑의 마력원천은 벌써 차단하셨나요?", completion = "도와주셔서 감사합니다. 하지만, 동료 수습생 몇 명이 미처 욕망에서 헤어나오지 못했다는 사실을 들으니 슬프군요.\n\n첨탑의 마력원천을 차단했으니 잠시 여기 머물렀다가 조용해지면 몰래 들어가서 그들이 남긴 물건을 가져와야겠어요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8890] = {title = "첨탑에서 온 전갈", objective = "영원노래 숲의 원정순찰대 산장에 있는 마법학자 더스크위더에게 가야 합니다.그대에게 마지막으로 부탁할 일이 있어요. 원정순찰대 산장으로 돌아가서 마법학자 더스크위더께 여기서 무슨 일이 벌어졌는지 전해 주시겠어요? 저는 잘 지낸다고 해주세요. 하지만, 수습생 몇 명이 버림받은 자로 전락했다는 사실만은 똑똑히 전해주십시오.\n\n도와주셔서 고맙습니다!이 보상들 중 하나를 선택할 수 있습니다:\n\n", description = "그대에게 마지막으로 부탁할 일이 있어요. 원정순찰대 산장으로 돌아가서 마법학자 더스크위더께 여기서 무슨 일이 벌어졌는지 전해 주시겠어요? 저는 잘 지낸다고 해주세요. 하지만, 수습생 몇 명이 버림받은 자로 전락했다는 사실만은 똑똑히 전해주십시오.\n\n도와주셔서 고맙습니다!이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아이템 #23399\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8891] = {title = "중단된 연구", objective = "마법학자 더스크위더의 일지를 가지고 영원노래 숲의 원정순찰대 산장에 있는 마법학자 더스크위더에게 가야 합니다.", description = "마법학자 더스크위더의 연구 일지를 발견했습니다. 대강 읽어 보니 오염된 마법 액체에서 불순물을 걸러내기 위해 아주 놀라운 실험을 진행한 것 같습니다. 일지를 읽어보니 여기 더스크위더 첨탑에서 벌어진 사태가 모두 이해가 갑니다. 마법학자는 자신의 연구 일지를 되찾고 싶어할 것입니다.", progress = "이게 뭐요? 낯익은 물건이군. 아, 이럴 수가! 내 일지... 내 연구... 모든 사태의 원인은 바로 이것이오.", completion = "여기 내가 저지른 범죄의 증거가 들어 있소, &lt;name&gt;. 이 일지에는 그릇된 내 연구에 대한 모두 것이 기록되어 있소.\n\n나는 경고를 무시했고 사태를 수습할 수 없게 될 때까지 연구를 계속했소. 잘못을 깨달았을 때 할 수 있는 모든 노력을 기울였지만 제자 중 몇 명은 이미 손쓸 수 없는 지경이었소. 제자들이 타락하는 것을 막기 위해 첨탑에서 모두 피난시켰지만 너무 서두른 나머지 마력원천을 차단하지 못했소.\n\n일지에 담긴 내용 때문에 또 다른 희생자가 발생하지 않도록 아예 태워 버리겠소. 난 단지 신도레이를 도우려 했을 뿐이라오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8892] = {title = "해돋이 부두의 상황", objective = "버림받은 엘프 암살자 5명과 버림받은 엘프 난동자 5명을 처치한 후, 영원노래 숲에 있는 순찰자 데골리엔에게 보고해야 합니다.", description = "해돋이 부두는 버림받은 자들에게 침입을 받아왔습니다. 지원 병력이 이곳으로 도착하는 즉시, 우린 그 흉악한 녀석에게 누가 이 땅의 지배자인지 보여줄 겁니다.\n\n그때까지 녀석들을 조금씩 손봐주는 일을 도와주십시오. 녀석들에게 우리가 장난이 아니라는 걸 보여주면 됩니다. 해돋이 부두는 산들바람 마을의 바로 서쪽에서 찾을 수 있습니다.", progress = nil, completion = "이번 일로 우리를 상대로 장난치면 혼난다는 사실을 배웠을 것입니다. 아주 잘하셨습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8893] = {title = "고성능 자동부화기", objective = "고성능 자동부화기는 커글 크랭크홉의 최신 발명품으로 상당히 멋진 기계입니다.\n\n제어판에 다가가자 거친 소리를 냅니다.", description = nil, progress = "고성능 자동부화기는 커글 크랭크홉의 최신 발명품으로 상당히 멋진 기계입니다.\n\n제어판에 다가가자 거친 소리를 냅니다.", completion = "히포그리프 알을 기계에 넣자 일련의 신호음과 함께 이상한 기계 소리가 들립니다.\n\n고성능 자동부화기가 알의 무게와 크기를 측정하고 포장을 한 것 같습니다. 정말 신속한 서비스로군요!", rewards = "다음과 같은 것들을 받습니다:\n\n알 상자"},
[8894] = {title = "토양 정화", objective = "마나 뱀과 에테르 마귀를 각각 6마리씩 해치운 후, 영원노래 숲의 더스크위더 정원에 있는 관리인 빌리덴에게 가야 합니다.", description = "끔찍한 일입니다! 첨탑에서 이상한 일이 벌어지고 있습니다. 마법학자와 그 제자들이 도망쳐 나오더니 그다음에는 세상에 맙소사, 마력을 지닌 야수들이 온 대지를 오염시키기 시작했습니다! 누가 알려주었느냐고요? 아무도 알려주지 않았어요!\n\n<class>님, 이것들을 제거하도록 절 좀 도와주셔야겠습니다... 이 '변종'들이 날뛰는 상황에서 제 힘만으로는 이 땅이 오염되는 것을 막을 수가 없거든요!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8895] = {title = "북부 성소에 물건 배달", objective = "영원노래 숲의 북부 성소에 있는 맥지기 케이다니스에게 표시가 없는 편지를 전달해야 합니다.", description = "그런대로 유능한 <class>|1을;를; 알게 되어 기쁘군요. 자신의 능력을 증명해 보이기를 원하는 것 같으니 다른 임무를 한번 맡아보십시오.\n\n여기 북부 성소의 관리를 맡고 있는 비전술사인 맥지기 케이다니스에게 전할 편지를 받으십시오. 매날개 광장에서 남서쪽으로 가면 그를 찾을 수 있습니다. 그는 아주 바쁜 몸이니 사소한 잡담으로 시간을 뺏지 않도록 주의하십시오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8897] = {title = "친애하는 콜라라", objective = "부관 조크린 헬드릭의 정성들여 쓴 쪽지를 스톰윈드 은행 밖에 있는 콜라라 딘에게 전해줘야 합니다.", description = "저는 항상 이곳을 지켜야 하는데, 제 애인 콜라라 때문에 늘 불안합니다. 그녀를 볼 수 있는 시간은 고작 몇 시간도 안 된답니다. 그것도 운이 좋으면 말이죠. 보시다시피 월급은 쥐꼬리만 하고 언제 최전선에 불려갈지 모르는 처지입니다.\n\n그녀가 절 잊으면 어쩌죠? 도시에는 돈 많은 남자들이 수두룩할 텐데...\n\n여하튼 뭘 좀 적은 게 있는데...별 건 아니고, 이걸 그녀에게 전해 주실 수 있습니까?", progress = "안녕하세요, 잘생긴 분. 무슨 일이시죠?", completion = "어머나, 정말 멋져요! 그 사람이 저에게 무얼 보내긴 이번이 처음이에요. 그 사람 심각해 보이던가요?\n\n콜라라 헬드릭? 이거 청혼하는 거 맞죠? 침착해야지, 너무 앞서 가는 건 아닌지 모르겠네. 이 쪽지를 전해주셔서 정말 고마워요.", rewards = nil},
[8898] = {title = "친애하는 콜라라", objective = "스톰윈드 은행 밖에 있는 콜라라 딘에게 반으로 접힌 편지를 전달해야 합니다.", description = "지난번 은행 업무 차 스톰윈드에 들렀다가 한 아가씨를 만났죠. 전 그녀에게 마음을 빼앗겨 버렸어요. 이젠 그녀 생각을 멈출 수가 없어요! 그녀에게 이 편지를 전해 주고 싶어요. 열두 번도 더 고친 정성들인 편지랍니다! 이젠 쓸 자리조차 없어요.\n\n그녀가 이 편지를 꼭 받아야 할 텐데, 그쪽으로 가는 길이면 절 좀 도와주시겠어요?", progress = "안녕하세요, 잘생긴 분. 무슨 일이시죠?", completion = "토르멕이라고요? 기억하고 말고요. 멋진 수염과 미소를 지는 분이셨죠.\n\n어머, 그분이 절 기억하고 있으리라곤 생각도 못했어요!", rewards = nil},
[8899] = {title = "친애하는 콜라라", objective = "스톰윈드 은행 밖에 있는 콜라라 딘에게 깔끔한 장식의 편지를 전해야 합니다.", description = "그녀의 아름다움을 어찌 말로 형용할 수 있으리오? 세상의 말로는 도무지 표현할 수가 없소.\n\n내 마음을 온통 뒤흔드는 그녀 앞에서 나는 말 더듬는 바보가 되어 버린다오.\n\n내 가슴속에 이 말들을 너무 오래 간직하고 있었소. 이보다 더 좋은 표현을 짜낼 수가 없소이다. 더 이상은 안 되겠소. 이제는 그녀에게 내 마음을 전해야 하오. 아니면 다른 누군가가 먼저 그녀의 마음을 가로챌지도 모르오. 날 좀 도와주시겠소?", progress = "이런! 무슨 일인가요?", completion = "이런 편지는 난생 처음이에요. 아름답기도 해라!", rewards = nil},
[8900] = {title = "친애하는 엘레니아에게", objective = "언더시티의 은행 근처에 있는 엘레니아 헤이돈에게 살짝 접힌 쪽지를 전해야 합니다.", description = "그녀의 눈망울은 정말 슬퍼 보였소. 그녀의 과거를 알았을 때 아픔이 있으리란 사실을 느낄 수 있었지...\n\n그녀와 이야기를 나누어 보니 우리에겐 뭔가 통하는 것이 있었소. 아무도 나를 이해하지 못할 거라 생각했는데 그녀는 달랐거든.\n\n다른 이들은 날 보고 비웃더군. 그래서 그녀와 다시 이야기를 나누지 못했소. 하지만, 그녀가 그리워... 이 편지를 좀 전해 주시겠소? 그녀의 가녀린 두 손에 꼭 쥐여주면 좋겠소이다.", progress = "무슨 일로 찾아 오셨죠?", completion = "사실 오크가 이렇게 글을 잘 쓸 줄은 몰랐어요. 물론 그들에 대해서 깊이 알 기회도 없었지만요. 이렇게 제게 쪽지를 전해주시다니 정말 감사해요.", rewards = nil},
[8901] = {title = "친애하는 엘레니아에게", objective = "언더시티의 은행 근처에 있는 엘레니아 헤이돈에게 정성들여 쓴 편지를 전해야 합니다.", description = "젊은 친구여, 사랑을 해본 적 있습니까? 엘레니아라는 언더시티의 한 소녀를 만나기 전까지 제게도 사랑은 낯선 말이었죠. 우리 같은 종족이 다른 종족에게 그런 감정을 느낀다는 것은 사실 굉장히 드문 일입니다. 포세이큰이라면 말할 것도 없고...\n\n하지만, 지금 제 머릿속은 밤이고 낮이고 온통 그녀 생각으로 가득 차있답니다.\n\n괜찮다면 이 편지를 그녀에게 전해 주시겠습니까? 그녀를 이곳 멀고어로 데려오고 싶거든요. 제발 이 애끓는 진심을 알아주기만을 바랄 뿐입니다.", progress = nil, completion = nil, rewards = nil},
[8902] = {title = "친애하는 엘레니아에게", objective = "언더시티의 은행 근처에 있는 엘레니아 헤이돈에게 사랑이 담긴 편지를 전해야 합니다.", description = "아주 오래전, 난 어릴 적부터 사랑했던 엘레니아와 약혼했지. 수년간 그녀를 잊지 않고 있었지만, 최근 들어 부쩍 그녀 생각이 자주 떠올라.\n\n숱하게 많은 일이 있었지만, 우리 사랑은 결코 지워지지 않을 숙명인듯 하네.\n\n그녀도 나처럼 많이 변했을 테지... 자네가 나를 위해 이 편지를 좀 전해주겠나? 너무 떨려서 내가 직접 가지는 못하겠어.", progress = nil, completion = nil, rewards = nil},
[8903] = {title = "위험한 사랑", objective = "스톰윈드 경비병의 카드를 스톰윈드에 있는 아리스탄 모탈에게 가져가야 합니다.", description = "이 전염병과 같은 사랑에는 정상적이지 않은 무엇이 있습니다. 바람직하지 않고, 나쁘게 말해서 눈에 거슬리며, 얼라이언스 연합 그 자체의 안전에 위협이 될 수 있습니다.\n\n생각해 보십시오. 경비병들이 이 요사스런 고통에 시달리게 되면 어떻게 되겠습니까? 뭔가 반드시 해야합니다.\n\n스톰윈드에 있는 경비병 중 한 친구를 만나서 그들이 이 어리석은 사랑에 걸려들진 않았는지 알아봐 주시기 바랍니다.", progress = "내가 걱정하는 바가 옳았습니까? 경비병들이 사랑의 번민에 휩싸여 있나요?", completion = "사실이로군요. 믿을 수가 없군요. 어떻게 이런 일이 일어난 것이죠? 잠시 생각할 시간을 주십시오. 이면에 뭔가 있을 겁니다.", rewards = nil},
[8904] = {title = "사랑이라는 위험한 병", objective = "언더시티 수호병의 곰팡이 슨 카드를 구해서 언더시티의 펜스타드 아가일에게 가져가야 합니다.", description = "지금 유행처럼 번지고 있는 사랑이란 병에 대한 나의 견해는 매우 부정적일세. 사실 아주 구역질이 나. 방어선을 취약하게 할 뿐만 아니라 우리 모두에게 위협이 될 수 있네.\n\n그 악영향이 너무 커서 많은 이들이 이상한 짓에 빠진 모양일세. 특히 그런 것에 무너지면 안 될 우리 경비대까지 말이야.\n\n자네에게 중요한 임무를 하나 맡기겠네. 우리 경비대 중에 그런 어리석은 감정에 빠진 녀석을 적발해주게나.", progress = "내 걱정이 현실로 드러났는가? 아니면 우리 바보같은 경비병들이 그 감정을 극복했나?", completion = "그래, 사실이었군. 믿을 수가 없어! 어떻게 이런 일이! 잠시 생각할 시간을 주게. 이 사태의 배후에는 뭔가 원인이 있을 게 분명해.", rewards = nil},
[8905] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 자연의정수 팔보호구를 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 겨울빙호와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야생의정수 팔보호구"},
[8906] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 야수추적자 손목띠를 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 겨울빙호와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야수왕의 손목띠"},
[8907] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 원소술사 손목띠를 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 겨울빙호와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요..다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n마술사의 손목띠"},
[8908] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 성전사 팔보호구를 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 겨울빙호와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n성령의 팔보호구"},
[8909] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 기원의 팔보호구를 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 겨울빙호와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n고결의 팔보호구"},
[8910] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 어둠추적자 팔보호구를 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 겨울빙호와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요.", progress = "부탁한 물건은 가지고 오셨나요?", completion = "훌륭해요! 이제 거래를 시작할까요? 이렇게 멋진 갑옷을 포기한다는 건 참 힘든 일이지만, 저에게는 더 이상 필요가 없을 것 같네요.\n\n제 일을 좀 더 도와주신다면 갑옷의 나머지 부분도 기꺼이 포기할 용의가 있답니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n검은장막의 팔보호구"},
[8911] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 공포의안개 팔보호구를 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 겨울빙호와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요..다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n죽음의안개 팔보호구"},
[8912] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 용맹의 팔보호구를 가지고 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 겨울빙호와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n무용의 팔보호구"},
[8913] = {title = "진지한 제안", objective = "오그리마에 있는 모크바르에게 실리시드 독 견본 15개와 20골드를 자연의정수 팔보호구 1개와 함께 가져가야 합니다.", description = "안녕하시오! 척 보아하니 세상 경험이 많은 <class>|1이라는;라는; 걸 알겠군. 하지만, 당신도 이런 방어구를 본 적은 없을 거요.\n\n날 위해 작은 부탁 하나만 들어주면 기꺼이 이중에서 팔보호구를 내어주겠소이다.\n\n난 실리더스에 서식하고 있는 거미와 전갈에게서 채취한 실리시드 독 견본이 많이 필요하오. 독 견본과 약간의 돈을 내면 더 좋은 팔보호구와 바꾸어 주겠소.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야생의정수 팔보호구"},
[8914] = {title = "진지한 제안", objective = "오그리마에 있는 모크바르에게 실리시드 독 견본 15개와 20골드를 야수추적자 손목띠 1개와 함께 가져가야 합니다.", description = "안녕하시오! 척 보아하니 세상 경험이 풍부한 <class>|1이라는;라는; 걸 알겠군. 하지만, 당신도 이런 방어구를 본 적은 없을 거요.\n\n날 위해 작은 부탁 하나만 들어주면 기꺼이 이중에서 손목띠를 내어주겠소이다.\n\n난 실리더스에 서식하고 있는 거미와 전갈에게서 채취한 독 견본이 많이 필요하오. 견본과 약간의 돈을 내면 더 좋은 손목띠와 바꾸어 주겠소.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야수왕의 손목띠"},
