[8920] = {title = "진지한 제안", objective = "오그리마에 있는 모크바르에게 실리시드 독 견본 15개와 20골드를 용맹의 팔보호구 1개와 함께 가져가야 합니다.", description = "안녕하시오! 척 보아하니 세상 경험이 많은 <class>|1이라는;라는; 걸 알겠군. 하지만, 당신도 이런 방어구를 본 적은 없을 거요.\n\n날 위해 작은 부탁 하나만 들어주면 이중에서 팔보호구를 내어주겠소.\n\n난 실리더스에 서식하고 있는 거미와 전갈에게서 채취한 실리시드 독 견본이 많이 필요하오. 독 견본과 약간의 돈을 내면 더 좋은 팔보호구와 바꾸어 주겠소.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n무용의 팔보호구"},
[8921] = {title = "심령체 추출기", objective = "정교한 아케이나이트 변환기 1개, 상급 영원의 정수 4개, 돌비늘 오일 10개, 화산재 25개와 40골드를 가지고 가젯잔에 있는 먹스 마나스크램블러에게 돌아가십시오.", description = "아, 자네에겐 내가 최근 연구하고 있는... 4차원 유령 탐색기가 필요하겠군! 그런데 유감스럽게도 지금 일손은 달리고 자금은 바닥났다네.\n\n날 돕겠다고? 좋아! 우리가 맨 먼저 할 일은 바로 죽은 자들로부터 원소를 수집하는 장치를 만드는 거야! <name>, 심령체 추출기 만드는 게 사실 그리 간단한 일이 아니라네.\n\n정교한 아케이나이트 변환기 하나와 상급 영원의 정수 약간, 그리고 돌비늘 오일이 필요해. 그리고 여과 장치를 만들 화산재도 필요하니 불타는 평원의 용암 지대로 가서 구해 오도록!", progress = "좀 비싼 재료라는 것은 나도 이해하네만... 그 중에 하나라도 빠져서는 절대 안 되네!", completion = "&lt;name&gt;, 필요한 재료들을 정확히 가져왔군. 시간도 아주 잘 맞췄어!\n\n조금 있으면 추출기가 준비될 것이네! 우선 이걸 받게나. 날 도와준 데 대한 보상일세.", rewards = "다음과 같은 것들을 받습니다:\n\n먹스의 고급 상품"},
[8922] = {title = "초자연적 장치", objective = "봉인된 혈액 용기를 타나리스 사막의 가젯잔에 있는 먹스 마나스크램블러에게 가져가야 합니다.", description = "안시온 하몬... 아니 좀더 정확하게 말해서 그의 영혼과 대화할 수 있는 방법을 찾아야만 합니다!\n\n제가 초자연적 현상에 별난 흥미를 가지고 있는 기술자를 한 명 알고 있습니다. 그는 죽은 자와 얘기할 수 있는 기계를 만들 수 있다고 주장하고 있습니다!\n\n당신이 모은 피는 그에게 가져다 주기 위한 것이랍니다. 가젯잔으로 가서 그의 도움을 받는 대가로 그 피를 건네주십시오!", progress = "내게 가져온 물건이 있지 않나?", completion = "훌륭하군! 마침 부족하던 재료야!\n\n델리아나가 보냈다고 했나?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8923] = {title = "초자연적 장치", objective = "가젯잔에 있는 먹스 마나스크램블러에게 봉인된 독액 용기를 가져가야 합니다.", description = "그런 일에도 개의치 않는다니 정말 용감한 자로군. 그게 아니라면 내가 준 방어구가 당신의 호기심을 자극한 건가? 날 계속 도와준다면 그 방어구 세트의 나머지 물건들도 줄 생각이오.\n\n당신이 모아온 독 견본은 내가 아는 기술자 먹스 마나스크램블러를 위한 것이었소. 그는 초자연적 현상에 관심이 많지. 최근에는 죽은 자와 대화할 수 있는 장치를 만들고 있더군. 내 마지막 바람은 안시온과 접촉하여 현재 나의 상황에 대한 정보를 얻는 것이오.", progress = "나와 대화를 나누고 싶다고?", completion = "좋았어! 마침 이게 부족하던 참이었는데!\n\n모크바르가 보냈다고?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8924] = {title = "심령체 수집", objective = "언데드 가까이에 심령체 추출기를 설치하여 실리더스에서 불타버린 심령체를, 여명의 설원에서 얼어붙은 심령체를, 동부 역병지대에서 안정적인 심령체를 각각 12개씩 수집해야 합니다. 심령체 추출기와 함께 가지고 가젯잔에 있는 먹스 마나스크램블러에게 돌아가십시오.", description = "예술이야! 내가 봐도 정말 잘 만들었단 말이야. 그런데 미안하지만 우리가 필요한 언데드 유령들을 찾으려면 자네가 고생 좀 해야 할 것 같네.\n\n자네도 알다시피 기후가 다르면 죽은 자들의 영적인 성분도 달라지지. 실리더스의 고통받는 나이트 엘프, 여명의 설원의 명가의 원혼, 동부 역병지대의 유령과 밴시들이 각각 서로 다른 종류의 심령체를 제공할 것이네. 단, 이것들을 수집하려면 근처에 추출기를 설치하고 싸워야 한다는 걸 명심하도록!", progress = "벌써 심령체를 다 모았나?", completion = "아주 잘 했네!\n\n이 물질들에 담긴 초자연적 힘을 이용하면 아직 이 세상을 떠나지 못한 영혼들과 접촉할 수 있을 거야!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8925] = {title = "휴대용 에너지원", objective = "불타는 평원에서 용암 군주 보크를 찾아서 용암 핵을 구한 후 가젯잔에 있는 먹스 마나스크램블러에게 가져가야 합니다.", description = "다음 단계로 심령체를 늘 활성 상태로 유지하려면 안정적이고 휴대할 수 있는 에너지원을 찾아야 하네. 용암 군주 보크라는 막강한 정령이 하나 있는데 이 정령의 심장에는 끊임없이 열을 내뿜는 강력한 용암 핵이 들어있다는 소문이 있어!\n\n검은바위 산 남쪽에 있는 불타는 평원에서 그 정령을 찾을 수 있다고 하네. 용암 핵을 가지고 오게. 그러면 4차원 유령 탐색기를 작동시킬 충분한 에너지를 얻을 수 있을 걸세!", progress = "<name>, 용암 군주는 찾았나?", completion = "해냈군! 이 정도면 틀림없이 4차원 유령 탐색기에 충분한 에너지를 공급할 수 있겠어!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8926] = {title = "정당한 보상", objective = "아이언포지에 있는 델리아나에게 자연의정수 허리띠 1개와 자연의정수 장갑 1개를 가져가야 합니다.", description = "약속한 대로 먹스가 만든 장치를 가지고 오셨군요. 당신이 저의 안전을 지키는 일에 계속 관심을 갖게 하려면 보상을 하는 것이 마땅하겠죠? 강화하고 싶은 허리띠와 장갑 1세트를 제게 가지고 오십시오. 그러면 더 상위의 방어구로 바꿔 드리겠습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야생의정수 허리띠야생의정수 장갑"},
[8927] = {title = "정당한 보상", objective = "오그리마에 있는 모크바르에게 자연의정수 허리띠 하나와 자연의정수 장갑 한 짝을 가져가야 합니다.", description = "<name>, 당신은 매우 믿을 만한 자라는 걸 몸소 증명해냈소. 당신의 노고에 대해 합당한 보답을 하는 것이 현명한 일이겠지. 내가 이 난관을 헤쳐나갈 수 있도록 도울 것이라 기대하는 만큼 말이오.\n\n당신의 허리띠와 장갑을 교환해 주겠소. 우리가 이 일에 성공한다면 나머지 방어구도 드리겠소이다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야생의정수 허리띠야생의정수 장갑"},
[8928] = {title = "별난 상인", objective = "여명의 설원 남부 검은속삭임 협곡 입구 옆에 있는 동굴 속에서 임프를 찾아야 합니다. 그에게서 악령의 제어봉을 구입한 후 가젯잔에 있는 먹스 마나스크램블러에게 돌아가십시오.", description = "그 용암 핵은 우리 장치에 충분한 에너지를 공급할 거야. 자, 이제 뜨거운 열기에 녹지 않고 그 힘을 전달할 수 있는 제어봉이 필요해!\n\n여명의 설원에서 온갖 별난 재료를 다 파는 임프를 만난 적이 있네. 방금 생각났는데 그 임프에게 우리 일에 딱 맞는 제어봉이 있었지. 어리석게도 그걸 안 사두었지 뭔가.\n\n그는 검은속삭임 협곡으로 가는 입구 옆 동굴 속에서 살고 있어. 살짝 들어가서 찾아보게!\n\n더도 덜도 말고 꼭 40골드에 사오도록. 전에 내게 제시했던 가격이니까.", progress = "운 좋게도 검은속삭임 협곡에서 그 임프를 찾을 수 있었나?", completion = "해냈군! 이 제어봉은 제 기능을 완벽하게 해줄 거야. 이제 모두 합치기만 하면...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8929] = {title = "안시온 찾기", objective = "스트라솔름 입구에서 4차원 유령 탐색기를 사용하여 안시온 하몬의 유령과 대화해야 합니다.\n\n제공된 아이템: \n", description = "우리가 할 수 있는 일이라고는 고블린의 발명품을 시험하는 것밖에 없습니다. 안시온이 스트라솔름의 문을 통과하려 했다는 이유로 스트라솔름의 언데드 군대에 의해 살해되었다고 합니다.\n\n거기 있는 장치를 사용해서 안시온이 무엇을 알고 있었는지 조사해 봐 주시겠습니까?", progress = nil, completion = "델리아나가 나와 접촉하라고 했단 말이오? 음, 최선을 다해 당신을 돕겠소. 하지만, 그전에 당신의 도움을 먼저 구해야겠군.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8930] = {title = "안시온을 찾아서", objective = "스트라솔름 입구에서 4차원 유령 탐색기를 사용하여 안시온 하몬의 유령과 대화하십시오.\n\n제공된 아이템: \n", description = "아주 좋아, <name>. 이제 이 고블린의 발명품을 시험하는 일만 남았군. 안시온은 스트라솔름의 문을 통과하려다가 그곳 언데드 군대에 의해 살해되었다는 소문이 있소.\n\n스트라솔름으로 가서 이 장치로 죽은 안시온과 진짜 대화를 나눌 수 있는지 확인해 보시오!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8933] = {title = "정당한 보상", objective = "아이언포지에 있는 델리아나에게 성전사 허리띠 1개와 성전사 건틀릿 1개를 가져가야 합니다.", description = "약속한 대로 먹스가 만든 장치를 가지고 오셨군요. 당신이 저의 안전을 지키는 일에 계속 관심을 갖게 하려면 보상을 하는 것이 마땅하겠죠? 강화하고 싶은 허리띠와 장갑 1세트를 제게 가지고 오십시오. 그러면 더 상위의 방어구로 바꿔 드리겠습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n성령의 허리띠성령의 건틀릿"},
[8935] = {title = "정당한 보상", objective = "아이언포지에 있는 델리아나에게 어둠추적자 허리띠 1개와 어둠추적자 장갑 1개를 가져가야 합니다.", description = "약속한 대로 먹스가 만든 장치를 가지고 오셨군요. 당신이 저의 안전을 지키는 일에 계속 관심을 갖게 하려면 보상을 하는 것이 마땅하겠죠? 강화하고 싶은 허리띠와 장갑 1세트를 제게 가지고 오십시오. 그러면 더 상위의 방어구로 바꿔 드리겠습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n검은장막의 허리띠검은장막의 장갑"},
[8938] = {title = "정당한 보상", objective = "오그리마에 있는 모크바르에게 야수추적자 허리띠와 야수추적자 장갑을 가져가야 합니다.", description = "<name>, 당신은 매우 믿을 만한 자라는 사실을 몸소 증명해냈소. 당신의 노고에 대해 합당한 보답을 하는 것이 현명한 일이겠지. 내가 이 난관을 헤쳐나갈 수 있도록 도울 것이라 기대하는 만큼 말이오.\n\n당신의 허리띠와 장갑을 교환해 주겠소. 우리가 이 일에 성공한다면 나머지 방어구도 드리겠소이다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야수왕의 허리띠야수왕의 장갑"},
[8941] = {title = "정당한 보상", objective = "오그리마에 있는 모크바르에게 어둠추적자 허리띠와 어둠추적자 장갑을 가져가야 합니다.", description = "<name>, 당신은 매우 믿을 만한 자라는 사실을 몸소 증명해냈소. 당신의 노고에 대해 합당한 보답을 하는 것이 현명한 일이겠지. 내가 이 난관을 헤쳐나갈 수 있도록 도울 것이라 기대하는 만큼 말이오.\n\n당신의 허리띠와 장갑을 교환해 주겠소. 우리가 이 일에 성공한다면 나머지 방어구도 드리겠소이다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n검은장막의 장갑검은장막의 허리띠"},
[8943] = {title = "정당한 보상", objective = "오그리마에 있는 모크바르에게 공포의안개 허리띠와 공포의안개 장갑을 가져가야 합니다.", description = "<name>, 당신은 매우 믿을 만한 자라는 사실을 몸소 증명해냈소. 당신의 노고에 대해 합당한 보답을 하는 것이 현명한 일이겠지. 내가 이 난관을 헤쳐나갈 수 있도록 도울 것이라 기대하는 만큼 말이오.\n\n당신의 허리띠와 장갑을 교환해 주겠소. 우리가 이 일에 성공한다면 나머지 방어구도 드리겠소이다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n죽음의안개 허리띠죽음의안개 장갑"},
[8944] = {title = "정당한 보상", objective = "오그리마에 있는 모크바르에게 용맹의 허리띠와 용맹의 건틀릿을 가져가야 합니다.", description = "<name>, 당신은 매우 믿을 만한 자라는 사실을 몸소 증명해냈소. 당신의 노고에 대해 합당한 보답을 하는 것이 현명한 일이겠지. 내가 이 난관을 헤쳐나갈 수 있도록 도울 것이라 기대하는 만큼 말이오.\n\n당신의 허리띠와 건틀릿을 교환해 주겠소. 우리가 이 일에 성공한다면 나머지 방어구도 드리겠소이다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n무용의 허리띠무용의 건틀릿"},
[8945] = {title = "죽은 자의 부탁", objective = "스트라솔름으로 가서 남작 리븐데어로부터 이시다 하몬을 구해야 합니다.", description = "당신이 원하는 정보를 알려주겠소만 더 급한 문제가 있소이다.\n\n사랑하는 내 아내가 리븐데어의 언데드 놈들에게 잡혀갔소.\n\n난 내 아내가 은빛 여명회의 멍청한 십자군에 들어가는 것을 강력하게 반대했었소. 이제 와서 말해봤자 아무 소용 없는 얘기겠지만... 내가 하려던 일을 당신이 마무리해 주시기 바라오. 남작의 손아귀에서 이시다를 구해 주시오!", progress = nil, completion = "구해주셔서 감사합니다... 정말 무서웠어요. 감사의 표시로 이걸 받아주세요.\n\n안시온은... 아녜요... 그럴 리가 없어요...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n평판 증가\n\n다음과 같은 것들을 받습니다:\n\n이시다의 가방"},
[8946] = {title = "생존의 증거", objective = "동부 역병지대에 있는 안시온 하몬에게 이시다의 펜던트를 가져가야 합니다.", description = "사랑하는 사람이 절 구하려다 목숨을 잃다니 이보다 더 잔인한 운명이 또 있을까요. 그런데 당신은 그이와 대화할 수 있는 능력이 있다고 하셨죠?\n\n그이에게 제가 무사하다는 증거로 이 펜던트를 전해주시겠어요? 그이는 분명 이 세계를 떠나지 못하고 있을 거예요. 아, 그 생각만 하면 제 가슴이 찢어지는 것 같아요.\n\n몸조심하세요. 항상 당신의 은혜를 잊지 않겠어요.", progress = "이시다... 그녀가 살아 있습니까?", completion = "그 펜던트는... 그녀를 찾았군! 이제야 비로소 안식을 찾아 떠날 수 있겠소이다.\n\n자, 그럼 어떤 질문이라도 대답해주겠소. 하지만 서두르시오. 내게 이 세계에서 허락된 시간이 그리 길지 않소이다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8947] = {title = "안시온의 이상한 부탁", objective = "동부 역병지대에 있는 안시온 하몬에게 검은무쇠 주괴 3개, 마력 깃든 가죽 20개, 달빛 옷감 3개, 거친 경화 가죽 4개를 가져가야 합니다.", description = "우리는 발타라스 군주의 메달이 가진 중요성을 전혀 몰랐기에 나머지 약탈품과 함께 메달을 나누었소. 첫 번째 조각은 텔드렌이라고 하는 드워프가 가지고 갔소이다. 난 그에게서 메달 조각을 되찾으려고 해봤지만 죽기 직전까지 매만 맞았지. 조각을 찾으려면 무력을 사용하는 수밖에 없을 것이오.\n\n텔드렌에 대해 마지막으로 들은 것은 검은무쇠단 드워프의 검투사가 되었다는 소식이었소. 그와 싸우려면 도전하려는 의지를 보여야 할 것이오.\n\n자, 이제 내가 말하는 재료를 가져와 주시오. 당신에게 그것들이 필요할 것이니 말이오.", progress = "부탁한 재료는 가져왔소?", completion = "아주 훌륭하오. 내 이 재료들을 우리 목적에 맞게 다른 것으로 바꾸도록 하지.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8948] = {title = "안시온의 오랜 친구", objective = "혈투의 전장의 도서관에 있는 팔린 트리셰이퍼에게 미완성된 도전의 깃발을 가져가야 합니다.", description = "텔드렌은 공정한 싸움을 싫어하는 그런 인물이오. 내가 그의 가문의 상징을 나타내는 깃발을 만들었소.\n\n약간의 마법을 추가하면 이 깃발은 그가 도저히 거부할 수 없는 방법으로 그를 자극할 것이오.\n\n내가 오래전부터 알고 지내는 팔린이라는 친구가 여기에 필요한 절차를 정확하게 알고 있소. 그에게는 남들의 약을 올리는... 특별한 방법이 있지. 혈투의 전장에 있는 도서관에 가면 그를 찾을 수 있을 것이오.", progress = "지금 내가 바쁜 게 안 보이시나요? 그러니 어서 말해 보십시오, 낯선분.", completion = "안시온이 보냈다고 하셨습니까? 죽은 줄로 알았는데... 살다 보니 별 이상한 얘기를 다 듣겠군.\n\n뭐, 좋습니다. 이 깃발로 내가 해 줬으면 하는 게 뭡니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8949] = {title = "팔린의 피의 복수", objective = "혈투의 전장이나 검은바위 첨탑의 오우거로부터 오우거 전투 목걸이 25개를 모은 후 도서관 안에 있는 팔린 트리셰이퍼에게 돌아가야 합니다.", description = "네, 사실입니다. 난 그대가 원하는 그 마법에 능숙하답니다, <class>|1이여;여;. 그러나 비록 내 오랜 친구가 그대를 보냈다고는 해도 난 아무에게나 호의를 베풀지 않습니다.\n\n우리와 이웃한 미개한 오우거들에 대해 내가 가지고 있는 감정은 증오와 멸시뿐입니다. 또한 그들뿐만 아니라 오모크의 추종자들을 왕 고르독의 추종자들만큼이나 증오합니다.\n\n그러니 그대가 그들을 해치워 주었으면 좋겠습니다. 최대한 많이! 놈들을 해치웠다는 증거로 그들이 목에 걸고 다니는 구슬을 내게 가져다주십시오. 이 일을 마치면 그대의 부탁에 대해 얘기를 시작할 수 있을 겁니다.", progress = "내가 부탁한 일은 끝냈습니까?", completion = "흐음... 내 형제를 살해한 그 야만스러운 놈들이 죽었는데도 기분이 전혀 좋아지지 않다니 참으로 이상한 일이군요.\n\n어쨌건 그대는 거래를 완수했습니다. 뭘 도와드리면 되겠습니까?", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n강력한 오우거의 부적목걸이오우거 주술 목걸이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8950] = {title = "주동자의 마법", objective = "혈투의 전장 안 도서관에 있는 팔린 트리셰이퍼에게 다음 재료를 가져가야 합니다: 도깨비 정수 1개, 암흑의 룬 4개, 눈부신 큰 결정 8개", description = "난 그대가 깃발에 걸기를 원하는 마법을 아주 부여할 수 있습니다만, 하지만 유감스럽게도 지금 이런 종류의 부적을 원하는 자가 아주 흔치 않기에 필요한 재료가 없습니다.\n\n이곳을 떠도는 엘드레스 영혼들 중에 한 명의 정수, 스칼로맨스 암흑의 룬 한 줌과 눈부신 큰 결정이 좀 필요합니다. 이 재료들을 구해오면 그대를 위해 이 일을 해 드리지요.", progress = "부탁한 재료는 모으셨습니까?", completion = "좋습니다, 이 정도면 충분하겠군요. 내가 작업을 마치면 이 세상의 어느 누구도 그대의 도전을 받아들이지 않을 수 없을 것입니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8951] = {title = "안시온의 작별 인사", objective = "자연의정수 장화, 자연의정수 킬트, 자연의정수 어깨갑옷을 가지고 아이언포지에 있는 델리아나에게 돌아가야 합니다.", description = "이 아뮬렛에는 군주 발타라크의 영혼이 담겨 있었소. 탐욕에 눈이 먼 우리는 어리석게도 우리를 기다리고 있는 저주에 대해 전혀 알지 못한 채 이 아뮬렛을 세 조각으로 나누었지.\n\n발타라크의 저주를 막을 수 있는 유일한 방법은 아뮬렛을 하나로 다시 합치는 것이오. 델리아나에게 돌아가서 보들리만이 나머지 조각을 찾을 수 있는 유일한 희망이라고 전하시오. 그리고 당신에게 필요한 보상이 있으면 그것도 함께 얘기하도록 하시오.\n\n아, 이제는 평화롭게 잠들 수 있었으면... 당신에게 행운이 끊이지 않기를 바라오. 아마도 운이 많이 따라야 할 것이오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야생의정수 장화야생의정수 킬트야생의정수 어깨갑옷"},
[8954] = {title = "안시온의 작별 인사", objective = "성전사 장화, 성전사 다리갑옷, 성전사 어깨갑옷을 가지고 아이언포지에 있는 델리아나에게 돌아가야 합니다.", description = "이 아뮬렛에는 군주 발타라크의 영혼이 담겨 있었소. 탐욕에 눈이 먼 우리는 어리석게도 우리를 기다리고 있는 저주에 대해 전혀 알지 못한 채 이 아뮬렛을 세 조각으로 나누었지.\n\n발타라크의 저주를 막을 수 있는 유일한 방법은 아뮬렛을 하나로 다시 합치는 것이오. 델리아나에게 돌아가서 보들리만이 나머지 조각을 찾을 수 있는 유일한 희망이라고 전하시오. 그리고 당신에게 필요한 보상이 있으면 그것도 함께 얘기하도록 하시오.\n\n아, 이제는 평화롭게 잠들 수 있었으면... 당신에게 행운이 끊이지 않기를 바라오. 아마도 운이 많이 따라야 할 것이오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n성령의 장화성령의 다리갑옷성령의 어깨갑옷"},
[8956] = {title = "안시온의 작별 인사", objective = "어둠추적자 장화, 어둠추적자 바지, 어둠추적자 어깨갑옷을 가지고 아이언포지에 있는 델리아나에게 돌아가야 합니다.", description = "이 아뮬렛에는 군주 발타라크의 영혼이 담겨 있었소. 탐욕에 눈이 먼 우리는 어리석게도 우리를 기다리고 있는 저주에 대해 전혀 알지 못한 채 이 아뮬렛을 세 조각으로 나누었지.\n\n발타라크의 저주를 막을 수 있는 유일한 방법은 아뮬렛을 하나로 다시 합치는 것이오. 델리아나에게 돌아가서 보들리만이 나머지 조각을 찾을 수 있는 유일한 희망이라고 전하시오. 그리고 당신에게 필요한 보상이 있으면 그것도 함께 얘기하도록 하시오.\n\n아, 이제는 평화롭게 잠들 수 있었으면... 당신에게 행운이 끊이지 않기를 바라오. 아마도 운이 많이 따라야 할 것이오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n검은장막의 장화검은장막의 바지검은장막의 어깨갑옷"},
[8957] = {title = "안시온의 작별 인사", objective = "정령의 장화, 정령의 킬트, 정령의 어깨갑옷을 가지고 오그리마에 있는 모크바르에게 돌아가십시오.", description = "이 아뮬렛에는 발타라크의 영혼이 담겨 있었소. 우리는 탐욕에 눈이 멀어 아뮬렛을 세 조각으로 나누는 어리석은 실수를 저질렀지. 우리를 기다리고 있는 저주에 대해서는 전혀 알지 못한 채...\n\n발타라크의 저주를 막을 수 있는 유일한 방법은 아뮬렛을 하나로 다시 합치는 것뿐이오. 모크바르에게 돌아가서 전하시오. 보들리만이 나머지 조각을 찾을 수 있는 유일한 희망이라고! 그리고 당신에게 필요한 보상이 있으면 그것도 함께 얘기하시오.\n\n이제는 평화롭게 잠들 수 있었으면... 당신에게 끝없는 행운이 있기를 빌겠소. 아마도 운이 많이 따라줘야 할 거요!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n우레의 장화우레의 킬트우레의 어깨갑옷"},
[8959] = {title = "안시온의 작별 인사", objective = "용맹의 장화, 용맹의 다리갑옷, 용맹의 어깨갑옷을 가지고 아이언포지에 있는 델리아나에게 돌아가야 합니다.", description = "이 아뮬렛에는 군주 발타라크의 영혼이 담겨 있었소. 탐욕에 눈이 먼 우리는 어리석게도 우리를 기다리고 있는 저주에 대해 전혀 알지 못한 채 이 아뮬렛을 세 조각으로 나누었지.\n\n발타라크의 저주를 막을 수 있는 유일한 방법은 아뮬렛을 하나로 다시 합치는 것이오. 델리아나에게 돌아가서 보들리만이 나머지 조각을 찾을 수 있는 유일한 희망이라고 전하시오. 그리고 당신에게 필요한 보상이 있으면 그것도 함께 얘기하도록 하시오.\n\n아, 이제는 평화롭게 잠들 수 있었으면... 당신에게 행운이 끊이지 않기를 바라오. 아마도 운이 많이 따라야 할 것이오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n무용의 장화무용의 다리갑옷무용의 어깨갑옷"},
[8960] = {title = "보들리의 불행한 운명", objective = "검은바위 산으로 가 검은바위 첨탑 근처에서 4차원 유령 탐색기를 사용하여 보들리를 찾아야 합니다.", description = "우리가 아뮬렛의 나머지 부분을 되찾아야 한다는 말이오? 보들리를 찾는 일은 골치가 좀 아플 것이오. 그는 검은바위 첨탑에 다시 들어가기 위해 검은바위 산으로 간 이후 돌아오지 못했소이다.\n\n고블린의 유령 탐지 기계를 가져 가시오. 최악의 상황이 벌어진 건 아닌가 걱정스럽군.", progress = nil, completion = "날 볼 수 있다니 정말 기쁘네요. 드디어 말동무가 생겼어요!\n\n우리를 좀 도와주시겠어요? 우리가 저지른 잘못을 원래대로 돌리고 상황을 바로잡을 수 있도록 도와주세요. 당신이 군주 발타라크의 아뮬렛 가운데 조각을 지니고 있다는 게 사실이라면, 내가 나머지 두 부분을 구해서 하나로 합친 후 이 모든 상황을 끝낼 수 있는 방법을 알려줄 수도 있을 것 같아요.\n\n아, 그건 그렇고 내 이름은 보들리라고 해요. 만나서 반가워요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8961] = {title = "세 고위 정령의 불꽃", objective = "인센디우스의 발연석, 불꽃 군주의 불꽃, 엠버시어의 불씨를 얻은 후, 성스러운 화로를 함께 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.", description = "군주 발타라크를 소환하려면 먼저 아뮬렛의 나머지 조각 두 개를 찾아야 해요. 그러려면 화로와 연료로 쓸 특별한 석탄이 필요하죠.\n\n검은바위 나락에 불의군주 인센디우스, 검은바위 첨탑에 불의수호자 엠버시어, 그리고 실리더스에 불꽃의 군주, 이 불의 고위 정령 셋이 우리가 필요한 것을 지니고 있어요. 각 정령에게서 영혼을 한 조각씩 얻은 후 성스러운 화로를 가지고 내게 돌아오세요. 아, 화로요? 성스러운 화로는 은빛 여명회에서 구입할 수 있답니다. 단 그들에게서 충분한 인정을 받아야 구입할 수 있을 거에요.", progress = "우리는 정말 어리석었어요... 우리가 맡은 마지막 임무가 우리를 불행의 나락으로 이끌었지요. 경솔하게 아뮬렛에 담겨 있던 군주 발타라크의 영혼 조각을 훔치지만 않았더라면, 아뮬렛을 나누어 가진 탐욕스러운 자들이 우리 용병단에 없었더라면, 난 지금도 살아서 맥주잔을 비우고 내 자식들에게 목말을 태워주고 있었겠죠?\n\n예전에 우리 용병단이 그랬던 것처럼 당신 또한 허황된 탐욕으로 불행을 자초하지 마세요.", completion = "감동했어요, &lt;class&gt;님. 하지만, 지체할 시간이 없어요. 계속 일을 진행하려면 몇 가지 중요한 것을 더 모아야 하니까 다음 일을 알려 드릴게요.\n\n다음 도전에 대한 준비가 되면 다시 날 찾아오세요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8962] = {title = "중요한 요소", objective = "드루이드의 유골을 구한 후 검은바위 산에 있는 보들리에게 가져가야 합니다.", description = "<class>님, 잘 들으세요. 우리가 화로와 화로를 지필 재료를 지니고 있긴 하지만 화로를 채울 다른 것, 즉 죽은 내 동료의 영혼을 유인할 수 있을 만큼 강력한 어떤 것이 필요하답니다.\n\n우리 중에 가장 뛰어난 드루이드였던 모르 그레이후프는 세나리온 의회에 가까운 친구가 많이 있었어요. 그 친구들 중 일부는 실리시드에게 희생되었죠. 실리더스 남동쪽 지역의 하이브레갈 근처에 사는 실리시드로부터 드루이드의 유골을 찾아다 주세요.", progress = "엥? 벌써 돌아왔어요, <class>님? 부탁한 것도 가지고 온 거예요?", completion = "일이 잘 마무리되었네요. 드루이드 유골의 정수를 화로에 불어넣도록 하겠어요.\n\n이제 검은바위 첨탑의 하층부, 타즈알라올에 있는 대장군 부네가 사는 방으로 가 화로를 사용해 내 옛 동료 모르 그레이후프의 타락한 영혼을 불러내는 일만 남았습니다. 그 친구에게서 아뮬렛 조각을 빼앗기 전엔 그가 쉴 곳은 없으니까요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8963] = {title = "중요한 요소", objective = "별바람 마을 유물을 구해서 검은바위 산에 있는 보들리에게 돌아가야 합니다.", description = "<class>님, 잘 들으세요. 우리가 화로와 화로를 지필 재료를 지니고 있긴 하지만 화로를 채울 다른 것, 즉 죽은 내 동료의 영혼을 유인할 수 있을 만큼 강력한 어떤 것이 필요하답니다.\n\n우리 여사제였던 이살리엔은 별바람 마을의 여명의 설원에서 어린 시절을 보냈답니다. 여명의 설원 남부 지역에 있는 서리속삭임 골짜기의 서리망치거인으로부터 별바람 마을 유물을 구해오세요. 그들은 골짜기 북쪽 지역을 종종 습격하는 것으로 알려져 있답니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8964] = {title = "중요한 요소", objective = "번쩍이는 열광의 검을 얻은 후 검은바위 산에 있는 보들리에게 돌아가야 합니다.", description = "<class>님, 잘 들으세요. 우리가 화로와 화로를 지필 재료를 지니고 있긴 하지만 화로를 채울 다른 것, 즉 죽은 내 동료의 영혼을 유인할 수 있을 만큼 강력한 어떤 것이 필요하답니다.\n\n자리엔과 소도스 형제는 붉은십자군의 길을 믿는 신봉자였답니다. 그들은 그 타락한 조직 속에서 기사도를 추구했었죠. 동부 역병지대에 있는 티르의 손 수도원으로 가서 그곳의 근위병으로부터 번쩍이는 열광의 검을 되찾아오세요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8965] = {title = "중요한 요소", objective = "추방된 자의 영혼재를 구한 후 검은바위 산에 있는 보들리에게 돌아가야 합니다.", description = "<class>님, 잘 들으세요. 우리가 화로와 화로를 지필 재료를 지니고 있긴 하지만 화로를 채울 다른 것, 즉 죽은 내 동료의 영혼을 유인할 수 있을 만큼 강력한 어떤 것이 필요하답니다.\n\n우리와 함께 여행을 했던 오우거 강령술사 코르모크는 힐스브래드 구릉지의 남부 해안 앞바다에 위치한 속죄의 섬에 있는 추방된 시체의 영혼을 즐겨 소환했었답니다. 그곳에 있는 영혼에게서 추방된 자의 영혼재를 구해서 돌아오세요.", progress = "엥? 벌써 돌아왔어요, <class>님? 부탁한 것도 가지고 온 거예요?", completion = "일이 잘 마무리 되었네요. 추방된 자의 영혼재의 정수를 화로에 불어넣도록 하겠어요. 이제 스칼로맨스에 있는 라스 프로스트위스퍼의 방으로 가 화로를 사용해 내 옛 동료 코르모크의 영혼을 불러내는 일만 남았군요.군주 발타라크의 영혼 안에 그 아뮬렛 조각이 그를 더욱더 타락시켰답니다. 그리고 그 조각을 그에게서 힘으로 빼앗기 전에 그는 쉬지 못할 겁니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8966] = {title = "군주 발타라크의 아뮬렛 왼쪽 조각", objective = "부름의 화로를 사용하여 모르 그레이후프의 영혼을 소환한 후 처치하십시오. 군주 발타라크의 아뮬렛 왼쪽 조각과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.", description = "내 친구 모르 그레이후프는 군주 발타라크의 아뮬렛과 그 안에 담긴 타락하는 영혼 조각의 손아귀에 희생된 첫 번째 희생자였답니다. 발타라크의 마법책과 아뮬렛을 훔친 후 우리는 살아남기 위해 검은바위 첨탑의 상층부에서 도망쳤어요. 그러던 중 모르는 첨탑의 하층부로 추락했지요.\n\n나중에 우리는 그가 추락했지만 목숨을 부지했고 단지 대장군 부네에게 사로잡혀 고문을 당했을 뿐이라는 사실을 알았답니다. 그러나 암살자 유령들이 숨어들어 바로 부네의 눈앞에서 그를 살해했답니다. 그의 영혼을 달래 주시겠어요?", progress = "임무는 마쳤나요? 군주 발타라크의 아뮬렛 왼쪽 조각을 회수하고 내 오랜 동료 모르 그레이후프의 영혼에게 안식을 찾아준 건가요?", completion = "정말 대단한 일을 해냈어요, &lt;class&gt;님. 한 영혼이 안식을 찾게 된 것이랍니다. 하지만 사태를 완전히 해결하려면 아직 할 일이 많이 남아 있어요.\n\n안타깝게도 나는 아뮬렛의 오른쪽 조각을 지니고 있던 이가 어디에서 죽었는지 몰라요. 그렇지만 너무 걱정할 필요 없어요. 살아 생전에 난 점치는 데 관심이 아주 많았거든요. 그래서 말인데 당신에게 다른 임무를 하나 드릴게요. 이 임무를 완수하면 마지막 조각을 찾을 수 있을 거에요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8967] = {title = "군주 발타라크의 아뮬렛 왼쪽 조각", objective = "부름의 화로를 사용하여 이살리엔의 영혼을 소환한 후 처치하십시오. 군주 발타라크의 아뮬렛 왼쪽 조각과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.", description = "그게 말이죠, 살아남기 위해 우리가 할 수 있는 일들을 하느라 얼마 전에서야 우리 동료였던 나이트 엘프 여사제 이살리엔이 지금 혈투의 전장으로 알려져 있는 나이트 엘프 선조들의 도시로 갔다는 사실을 알았어요. 우리가 알아본 사실에 의하면 이살리엔이 그곳으로 간 이유는 개인적인 이유도 있고 지니고 있는 아뮬렛 조각의 비밀을 풀기 위한 이유도 있답니다.\n\n하지만 그녀는 결국 목적을 달성하지 못했죠. 이살리엔이 엘드레사르 제단에서 칼날바람 알진과 그의 군대에 기습을 당했다는 소식을 들었어요. 그리로 가서 그녀의 영혼을 달래 주시겠어요?다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8968] = {title = "군주 발타라크의 아뮬렛 왼쪽 조각", objective = "부름의 화로를 사용하여 자리엔과 소노스의 영혼을 소환한 후 처치하십시오. 군주 발타라크의 아뮬렛 왼쪽 조각과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.", description = "자리엔과 소노스 형제는 우리 용병단의 해체와 동시에 붉은십자군에 들어가기로 결정했습니다. 두 형제는 군주 발타라크의 아뮬렛 왼쪽 조각을 가지고 갔지요. 골칫덩어리가 사라진 것이지만 어쨌든 우리는 그 조각을 되찾아야 합니다.\n\n우리가 모은 정보에 의하면 사실상 두 형제는 가입 의식을 통과하지 못했다는 이유로 붉은십자군 성채에 있는 십자군사령관 다스로한의 방 안에서 그의 손에 살해됐다고 해요.\n\n어떤 일이 있어도, 우리... 그러니까 당신이 그 아뮬렛 조각을 되찾아야 합니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8969] = {title = "군주 발타라크의 아뮬렛 왼쪽 조각", objective = "부름의 화로를 사용하여 코르모크의 영혼을 소환한 후 처치하십시오. 군주 발타라크의 아뮬렛 왼쪽 조각과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.", description = "이제 필요한 것을 갖추었으니 당신이 소환할 인물에 대해 알아볼 시간이 되었군요.\n\n코르모크는 강령술사가 되기 전까지만 해도 아주 괜찮은 오우거였어요. 하지만 그가 강령술사가 된 이후 용병단원 모두가 꺼림칙하게 생각하는 것은 어쩔 수가 없었죠. 그런 상황에서 그가 아뮬렛 조각을 가지고 그의 새로운 고향 스칼로맨스로 간 것은 전혀 놀랄 일이 아니었답니다.\n\n하지만 그는 그곳에서조차, 아니면 그곳이기 때문인지도 모르지만 어쨌든 그는 암살자 영혼들로부터 안전하지 못했답니다. 그는 암살자 영혼들에 의해 그의 주인 라스 프로스트위스퍼의 바로 눈앞에서 살해됐답니다. 그의 영혼을 달래 주시겠어요?", progress = "아뮬렛의 왼쪽 조각을 되찾아 온 것이라면 칭찬을 해 드려야겠네요. 하지만 그게 아니라면 임무에 전념하세요. 낭비할 시간이 없단 말이에요!", completion = "잘하셨어요! 코르모크는 그렇게 나쁜 오우거는 아니었어요. 적어도 그 친구가 살아있는 동안에는 말이죠. 그러니 그가 안식을 취할 수 있으면 좋겠군요. 하지만 아직 우리에게는 할 일이 많아요.\n\n안타깝게도 나는 아뮬렛의 오른쪽 조각을 지니고 있던 이가 어디에서 죽었는지 몰라요. 그렇지만 너무 걱정할 필요 없어요. 살아 생전에 난 점치는 데 관심이 아주 많았거든요. 그래서 말인데 당신에게 다른 임무를 하나 드릴게요. 이 임무를 완수하면 마지막 조각을 찾을 수 있을 거에요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8970] = {title = "예언 속의 알카즈 섬", objective = "붉은물풀 20개를 모은 후 검은바위 산에 있는 보들리에게 돌아가야 합니다.", description = "<class>님, 전에 말했듯이 나는 살아 있을 때 장난삼아 점쟁이가 돼 볼까 했었답니다. 그렇지만 실제로 점쟁이로 사는 것이 생각만큼 큰 득이 되지 않더군요. 무엇보다도 점이라는 것은 위험하고 재료 또한 귀하고 비싸기 짝이 없잖아요. 하지만 마지막 아뮬렛 조각과 그걸 지니고 있는 내 옛 동료의 영혼의 위치를 알아낼 만큼의 지식은 아직 있답니다.\n\n먼지진흙 습지대의 앞바다에 있는 알카즈 섬으로 가서 그곳에 살고 있는 스트라샤즈 나가로부터 붉은물풀을 수집해 오세요. 이게 당신이 할 일이에요.", progress = "붉은물풀, 그것도 아주 많은 붉은물풀이 필요해요. 그게 있어야만 내가 점을 칠 수가 있거든요. 그걸 모으려면 동료 몇 명 정도는 데리고 알카즈 섬에 가는 것이 좋을 듯한데... 그 스트라샤즈 녀석들이 만만치가 않거든요!", completion = "와, 붉은물풀을 가지고 무사히 돌아오다니 솔직히 좀 놀랍네요. 다시 한 번 알카즈 섬 따위는 당신에게 아무것도 아니라는 걸 깨닫게 되는군요.\n\n좋아요, 그럼 내게 시간을 좀 주세요... 점이라는 게 도깨비 방망이처럼 순식간에 뚝딱 하고 정확한 결과가 나오는 게 아니라서요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n천상의 무아지경\n\n다음과 같은 것들을 받습니다:\n\n"},
[8971] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n스톰윈드 선물세트"},
