[8976] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n아이언포지 선물세트"},
[8977] = {title = "델리아나에게 돌아가기", objective = "아이언포지에 있는 델리아나에게 4차원 유령 탐색기를 가져가야 합니다.", description = "자네와 함께할 수 있어서 정말 좋았다고, <class> 친구. 자, 여기 완성된 물건일세.\n\n자네가 하려는 일에 도움이 됐으면 좋겠군. 그리고 괜찮다면 소문을 좀 내줄 수 있을까? 손님이 더 많이 와서 이곳이 시끌벅적한 것이 좋을 거 같거든!", progress = "벌써 돌아오신 건가요?", completion = "훌륭합니다! 아주 잘 하셨군요. 고블린의 솜씨를 믿어도 되는 것인지 확신할 수는 없지만 다른 선택의 여지가 없네요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8978] = {title = "모크바르에게 돌아가기", objective = "4차원 유령 탐색기를 가지고 오그리마에 있는 모크바르에게 돌아가십시오.", description = "<name>, 자네와 함께 한 작업은 정말 대단했어. 여기 완성된 물건이 있네.\n\n지금부터 자네가 하려는 일에 도움이 됐으면 좋겠군. 참, 그리고 괜찮다면 소문을 좀 내줄 수 있을까? 손님이 좀 더 많이 왔으면 좋겠거든!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8979] = {title = "펜스타드의 육감", objective = "언더시티 연금술 실험실에 있는 연금술사 진게에게 은은한 향수와 매혹적인 향수를 한 병씩 가져가야 합니다.", description = "이런 사태가 벌어진 원인을 알 것 같아. 자네도 최근 바람에 실려 흐르는 새로운 향기를 맡아봤겠지. 혹시 용수로의 악취일까? 아니면 새로운 향수라도 유행하는 건가?\n\n그도 아니면 더러운 연금술로 우리의 사고력이 흐려지는 건 아닐까 하는 생각이 드는군.\n\n확실히 알 수 있는 방법은 하나뿐일세. 내 친구 연금술사 진게에게 은은한 향수와 매혹적인 향수를 한 병씩 가져가게. 왕립 연금술 학회에서 진실을 밝혀줄 거야.\n\n돌아오면 향수 구입 비용은 갚아주겠어.", progress = "어떻게 오셨습니까?", completion = "펜스타드가 또 망상에 사로잡힌 게 분명하군요. 왕립 연금술 학회가 그렇게 사소한 연구나 할 만큼 한가하겠습니까?\n\n좋아, 그를 또 한 번 놀려줄 좋은 기회로군요.", rewards = nil},
[8980] = {title = "진게가 준 임무", objective = "언더시티 은행 밖에 있는 펜스타드 아가일에게 돌아가십시오.", description = "예상치 못한 일이지만 펜스타드가 무언가에 집착하고 있단 사실은 분명하군요. 저는 정신을 지배할 수 있는 물약에 쓰이는 재료를 발견한 적이 있습니다.\n\n사실 그런 원료의 향수가 있다는 소리는 들어보지 못했지만 제가 발견한 성분은 분명... 전문 연금술 중에서도 최고 단계이며 왕립 연금술 학회의 일원의 능력에 필적하는 자가 다룰 만한 것이었습니다.", progress = nil, completion = "그러니까 내 예상이 맞았군. 자, 서둘러야겠어. 오염된 향기의 근원을 밝혀내야 해.\n\n참, 여기 향수 구입 비용은 갚아줌세.", rewards = "다음과 같은 것들을 받습니다:\n\n초콜릿 상자붉은 꽃잎 한줌"},
[8981] = {title = "선물 증정", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n붉은 꽃잎 한줌은 화살\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n이벤트 - 발렌타인 - 선물 받음\n\n다음과 같은 것들 또한 받습니다:\n\n초콜릿 상자"},
[8982] = {title = "향기의 근원 추적", objective = "언더시티의 여관주인 노먼과 대화하십시오.", description = "어떤 자가 그런 물건을 공급하는지 찾아내야 해. 전에 연금술사 카트리나가 가방에 향수병을 감추는 걸 보았네. 그녀에게 물어보니 여관주인 노먼에게서 샀다더군.", progress = nil, completion = "아, 맞습니다. 최근에 제가 은은한 향수와 매혹적인 향수 한 꾸러미를 받았지요. 여기 얼마나 더 오래 보관할 수 있을지는 모르지만 아무도 저만큼 많이 갖고 있을 수는 없을 거예요.\n\n제게 부탁하시는 거라면... 뭐 어려운 청도 아니로군요.", rewards = nil},
[8983] = {title = "향기의 근원 추적", objective = "언더시티 마법 지구에 있는 재봉 용품점으로 가서 마라 레닉과 대화해야 합니다.", description = "그런데 제 물건에 뭐 이상한 점이라도 있나요? 이렇게 많은 이들이 탐을 내는 물건은 사실 처음 봅니다.\n\n저도 마라 레닉이라는 상인에게서 구입했어요. 참, 이 도시에서는 처음 보는 여인이었습니다.\n\n그녀와 마지막으로 이야기를 나눴을 때 마법 지구의 재봉사에게 전해야 할 물건이 있다고 하더군요.", progress = nil, completion = "미안하지만 내가 갖고 있던 향수는 여관주인 노먼에게 다 팔았네. 갖고 싶다면 그에게 가서 청해보게. 남은 향수가 있을 거야.\n\n여기서 시간 낭비하지 말게. 자네도 절대로 저항할 수 없는 향기를 지닌 은은한 향수를 얻을 수 있을 거니까.", rewards = nil},
[8984] = {title = "밝혀진 향기의 근원", objective = "라벤홀트 장원을 지나 힐스브래드 산기슭에 있는 스태프론 리런트를 찾아가야 합니다.", description = "이봐, 그 연금술사가 도둑질을 했더라도 그게 내 소관은 아니지. 만일 그가 우리에게 해를 끼친다면 내 자네에게 일을 바로 잡아달라고 청함세.\n\n결백하다면 숨길 건 없겠지? 안 그래?\n\n그래, 사실 나도 연금술사 스태프론 리런트란 자에게서 물건을 구입한 거야. 그는 힐스브래드의 구릉에 있는 라벤홀트 장원을 조금 지난 외딴곳에서 일을 하고 있을 걸세. 솔직히 말해서 조금 기묘한 데가 있는 자였네.", progress = nil, completion = "그래, 내가 그 향기를 창조했네. 정말 굉장한 냄새 아닌가? 거부할 수 없는 유혹의 냄새...\n\n호드와 얼라이언스의 용사들이 모두 그 향기에 매료되어 사랑이란 감정에 빠지고 나면 어둠의 의회에 무릎을 꿇을 수밖에 없게 될 것일세.\n\n한 없이 약해지다가 자신도 모르는 사이 무장해제당하고 마는 거지. 누구나 사랑에 빠지면 긴장을 풀게 되어 있지 않나.\n\n참 간단한 방법이지. 정말 순식간에 떠오른 해결책이었네. 마음이 약해지면 모든 것이 무너지는 법... 그러면 자네든 누구든 절대 막을 수 없는 일이 벌이질 거야.", rewards = nil},
[8985] = {title = "또 다른 중요한 요소", objective = "별바람 마을 유물을 구한 후 검은바위 산에 있는 보들리에게 가져가야 합니다.", description = "<class>님, 잘 들으세요. 우리가 마지막 아뮬렛 조각의 위치를 알고 있기는 하지만 화로를 채울 다른 것, 즉 죽은 내 동료의 영혼을 유인할 수 있을 만큼 강력한 어떤 것이 필요하답니다.\n\n우리 여사제였던 이살리엔은 여명의 설원에 있는 별바람 마을에서 어린 시절을 보냈답니다. 여명의 설원 남부 지역에 있는 서리속삭임 골짜기의 서리망치거인에게서 별바람 마을 유물을 구해오세요. 그들은 골짜기 북쪽 지역을 종종 습격하는 것으로 알려져 있답니다.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n붉은물풀 회피의 비약붉은물풀 저항의 비약\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8986] = {title = "또 다른 중요한 요소", objective = "드루이드의 유골을 구한 후 검은바위 산에 있는 보들리에게 가져가야 합니다.", description = "<class>|1이여;여;, 잘 듣게. 우리가 마지막 아뮬렛 조각의 위치를 알고 있기는 하지만 화로를 채울 다른 것, 즉 죽은 내 동료의 영혼을 유인할 수 있을 만큼 강력한 어떤 것이 필요하답니다.\n\n우리 중에 가장 뛰어난 드루이드였던 모르 그레이후프는 세나리온 의회에 가까운 친구가 많이 있었지요. 그 친구들 중 일부가 실리시드에게 희생되었답니다. 실리더스 남동쪽 지역의 하이브레갈 근처에 사는 실리시드로부터 드루이드의 유골을 되찾아서 돌아오세요.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n붉은물풀 회피의 비약붉은물풀 저항의 비약\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8987] = {title = "또 다른 중요한 요소", objective = "번쩍이는 열광의 검을 구해 검은바위 산에 있는 보들리에게 가져가야 합니다.", description = "<class>님, 잘 들으세요. 우리가 마지막 아뮬렛 조각의 위치를 알고 있기는 하지만 화로를 채울 다른 것, 즉 죽은 내 동료의 영혼을 유인할 수 있을 만큼 강력한 어떤 것이 필요하답니다.\n\n자리엔과 소노스 형제는 붉은십자군의 길을 믿는 신봉자였답니다. 그들은 그 타락한 조직 속에서도 기사도를 추구했었지요. 동부 역병지대에 있는 티르의 손 수도원으로 가서 그곳의 근위병으로부터 번쩍이는 열광의 검을 되찾아오세요.", progress = "엥? 벌써 돌아왔어요, <class>님? 부탁한 것도 가지고 온 거예요?", completion = "일이 잘 마무리 되었네요.번쩍이는 열광의 검의 정수를 화로에 불어넣도록 할게요.\n\n이제 스트라솔름의 붉은십자군 성채 안에 있는 진홍십자군 사령실로 가 화로를 사용해 내 옛 동료 자리엔과 소노스의 영혼을 소환하는 일만 남았군요. 그들의 영혼은 발타라크 군주의 아뮬렛 조각과 그의 영혼 안의 힘을 얻고자하는 집착으로 뒤엉켰답니다.\n\n아, 그건 그렇고 지난번 당신이 알카즈 섬에서 가져다 준 붉은물풀이 남았기에 당신을 위해 물약을 좀 만들어 봤어요. 마음에 드는 것으로 골라 보세요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n붉은물풀 회피의 비약붉은물풀 저항의 비약\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8988] = {title = "또 다른 중요한 요소", objective = "추방된 자의 영혼재를 구한 후 검은바위 산에 있는 보들리에게 돌아가야 합니다.", description = "<class>님, 잘 들으세요. 우리가 마지막 아뮬렛 조각의 위치를 알고 있기는 하지만 화로를 채울 다른 것, 즉 죽은 내 동료의 영혼을 유인할 수 있을 만큼 강력한 어떤 것이 필요하답니다.\n\n우리와 함께 여행을 했던 오우거 강령술사 코르모크는 힐스브래드 구릉지의 남부 해안 앞바다에 위치한 속죄의 섬에 있는 추방된 시체의 영혼을 즐겨 소환했었어요. 그곳의 영혼으로부터 추방된 자의 영혼재를 구해 돌아오도록 하세요.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n붉은물풀 회피의 비약붉은물풀 저항의 비약\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[8989] = {title = "군주 발타라크의 아뮬렛 오른쪽 조각", objective = "부름의 화로를 사용하여 모그 그레이후프의 영혼을 소환한 후 처치하십시오. 완성된 군주 발타라크의 아뮬렛과 부름의 화로를 가지고 검은바위 산에 있는 보들리에게 돌아가야 합니다.", description = "내 친구 모르 그레이후프는 군주 발타라크의 아뮬렛과 그 안에 담긴 타락하는 영혼 조각의 손아귀에 희생된 첫 번째 희생자였답니다. 발타라크의 마법책과 아뮬렛을 훔친 후 우리는 살아남기 위해 검은바위 첨탑의 상층부에서 도망쳤어요. 그러던 중 모르는 첨탑의 하층부로 추락했지요.\n\n나중에 우리는 그가 추락했지만 목숨을 부지했고 단지 대장군 부네에게 사로잡혀 고문을 당했을 뿐이라는 사실을 알았답니다. 그러나 암살자 유령들이 숨어들어 바로 부네의 눈앞에서 그를 살해했답니다. 다시 한번 그의 영혼을 달래 주시겠어요?다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8990] = {title = "군주 발타라크의 아뮬렛 오른쪽 조각", objective = "부름의 화로를 사용하여 이살리엔의 영혼을 소환한 후 처치하십시오. 완성된 군주 발타라크의 아뮬렛과 부름의 화로를 가지고 검은바위 산에 있는 보들리에게 돌아가야 합니다.", description = "그게 말이죠, 살아남기 위해 우리가 할 수 있는 일들을 하느라 얼마 전에서야 우리 동료였던 나이트 엘프 여사제 이살리엔이 지금 혈투의 전장으로 알려져 있는 나이트 엘프 선조들의 도시로 갔다는 사실을 알았어요. 우리가 알아본 사실에 의하면 이살리엔이 그곳으로 간 이유는 개인적인 이유도 있고 지니고 있는 아뮬렛 조각의 비밀을 풀기 위한 이유도 있답니다.\n\n하지만 그녀는 결국 목적을 달성하지 못했죠. 이살리엔이 엘드레사르 제단에서 칼날바람 알진과 그의 군대에 기습을 당했다는 소식을 들었어요. 그리로 가서 다시 한번 그녀의 영혼을 달래 주시겠어요?다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8991] = {title = "군주 발타라크의 아뮬렛 오른쪽 조각", objective = "부름의 화로를 사용하여 자리엔과 소노스의 영혼을 소환한 후 처치하십시오. 완성된 군주 발타라크의 아뮬렛과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.", description = "자리엔과 소노스 형제는 우리 용병단의 해체와 동시에 붉은십자군에 들어가기로 결정했습니다. 두 형제는 군주 발타라크의 아뮬렛 오른쪽 조각을 가지고 갔지요. 골칫덩어리가 사라진 것이지만 어쨌든 우리는 그 조각을 되찾아야 합니다.\n\n우리가 모은 정보에 의하면 사실상 두 형제는 가입 의식을 통과하지 못했다는 이유로 붉은십자군 성채에 있는 십자군사령관 다스로한의 방 안에서 그의 손에 살해됐다고 해요.\n\n어떤 일이 있어도, 우리... 그러니까 당신이 그 아뮬렛 조각을 되찾아야 합니다.", progress = "오호, 돌아온 걸 보니 어리석은 두 형제의 영혼에 안식을 찾아주고 군주 발타라크의 아뮬렛을 완성했다는 것인가요?", completion = "두 형제의 영혼이 마침내 안식을 찾았다는 것은 참으로 잘된 일이군요. 그들이 살아 있을 때 별로 마음에 들지는 않았지만. 어쨌건 우리가 구하던 것을 찾았고 지금은 이렇게 아뮬렛이 완성되었으니 정말 잘된 일이죠! 하지만 아직 우리에게는 가장 힘든 시험이 남아 있습니다.\n\n군주 발타라크를 소환할 수 있도록 화로를 조절하려면 몇 가지 재료가 더 필요하니 그것들을 모아서 내게 가져오는 일이랍니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8992] = {title = "군주 발타라크의 아뮬렛 오른쪽 조각", objective = "부름의 화로를 사용하여 코르모크의 영혼을 소환한 후 처치하십시오. 완성된 군주 발타라크의 아뮬렛과 부름의 화로를 가지고 검은바위 산 안에 있는 보들리에게 돌아가야 합니다.", description = "이제 필요한 것을 갖추었으니 당신이 소환할 인물에 대해 알아볼 시간이 되었군요.\n\n코르모크는 강령술사가 되기 전까지만 해도 아주 괜찮은 오우거였어요. 하지만 그가 강령술사가 된 이후 용병단원 모두가 꺼림칙하게 생각하는 것은 어쩔 수가 없었죠. 그런 상황에서 그가 아뮬렛 조각을 가지고 그의 새로운 고향 스칼로맨스로 간 것은 전혀 놀랄 일이 아니었습니다.\n\n하지만 그는 그곳에서조차, 아니면 그곳이기 때문인지도 모르지만 어쨌든 그는 암살자 영혼들로부터 안전하지 못했답니다. 그는 암살자 영혼들에 의해 그의 주인 라스 프로스트위스퍼의 바로 눈앞에서 살해됐답니다. 다시 한번 그의 영혼을 달래 주시겠어요?다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[8993] = {title = "선물 증정", objective = "오호호, 안녕하세요! 당신이 제일 좋아하는 지도자에게 존경과 사랑을 담은 선물을 전달하러 오신 건가요?", description = nil, progress = "오호호, 안녕하세요! 당신이 제일 좋아하는 지도자에게 존경과 사랑을 담은 선물을 전달하러 오신 건가요?", completion = "굉장해요! 정말 멋지군요! 이걸 다른 선물 보따리에 올려놓을게요.\n\n이렇게 많으리라 예상하지 못했는데 정말 대단하네요! 당신은 진정 지도자들을 존경하는군요.\n\n이제 선물세트 합계에 하나 더 추가하도록 할게요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n붉은 꽃잎 한줌은 화살\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n이벤트 - 발렌타인 - 선물 받음\n\n다음과 같은 것들 또한 받습니다:\n\n초콜릿 상자"},
[8994] = {title = "마지막 준비", objective = "검은바위 팔보호구 40개와 강력한 마력의 영약을 구한 후, 검은바위 산에 있는 보들리에게 돌아가야 합니다.", description = "이제 막바지에 이르렀군요, <class>님. 남은 일은 내가 화로를 조절해서 군주 발타라크를 소환할 수 있도록 몇 가지 물건을 구해 오는 것뿐이랍니다.\n\n작업을 시작할 수 있도록 당신이 검은바위 첨탑으로 가서 오크들을 해치워 주셨으면 해요. 그곳의 오크들은 내가 필요로 하는 미량의 금속이 포함된 팔보호구를 착용하고 있는데, 충분한 양의 금속을 추출할 수 있을 만큼의 팔보호구가 있어야 하거든요. 그리고 화로에 힘을 불어넣는 작업을 끝마치려면, 강력한 마력의 영약이 필요하니 영약을 구해서 가지고 와 주세요.\n\n행운을 빌게요!", progress = "아주 오랜 준비 과정이었어요. 결과가 어떻든 간에 당신에게 고맙다는 말을 꼭 하고 싶네요. 정말 고마워요! 감춰진 칼날단이라는 이름으로 살아남은 우리의 용병단원을 위해 위험한 일을 도와주었으니, 당신은 이제 우리 식구나 마찬가지랍니다.", completion = "자, 과정은 이래요. 내가 팔보호구에서 금속을 추출한 후 이 마지막 재료들을 사용해서 화로에 힘을 불어넣을 거에요. 그러면 당신이 군주 발타라크를 소환할 준비가 완료되는 것이고, 마지막으로 그의 영혼 아뮬렛을 돌려주면 되는 것이랍니다.\n\n지금까지 먼 길을 걸어왔잖아요? 이제 그 끝이 보이니 주저하지 마세요!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8995] = {title = "군주 발타라크여, 내 탓이오.", objective = "부름의 화로를 사용하여 군주 발타라크를 소환하십시오. 군주 발타라크를 해치우고 그의 시체에 군주 발타라크의 아뮬렛을 사용한 후, 군주 발타라크의 영혼에게 군주 발타라크의 아뮬렛을 돌려줘야 합니다.", description = "이제 정말 모든 준비가 끝났네요. 살아생전 발타라크 군주는 괴수가 있는 우리에서 지냈었답니다. 그곳으로 가서 부름의 화로를 사용해서 발타라크 군주를 소환하세요. 부름의 화로가 그의 영혼을 다시 합체시킬 것이니 그를 다시 처치할 수 있을 겁니다. 먼저 괴수를 처리해야 하니, 검은바위 첩탑의 상층에서 살아남으려면 동료들을 충분히 데리고 가도록 하세요.\n\n발타라크를 해치운 후에는 그의 시체에 아뮬렛을 사용하면 돼요. 그의 영혼이 다시 하나로 합쳐지면 그가 아뮬렛을 돌려받길 원할 겁니다.\n\n정말 행운을 빌어요!", progress = "<class>, 네가 감히 내 휴식을 방해하다니!", completion = "내가 내게서 아뮬렛을 훔쳐간 녀석들의 일원이 아닌 것을 알고 있다는 사실이 얼마나 운이 좋은지 알겠지?\n\n필멸의 존재여, 내 것을 이제 다시 가져가도록 하겠다! 그 아뮬렛을 이리 다오!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8996] = {title = "보들리에게 돌아가기", objective = "검은바위 산 안에 있는 보들리에게 돌아가서 부름의 화로를 돌려줘야 합니다.", description = "<class>|1이여;여; 오늘 너는 도둑맞은 나의 영혼을 되돌려 주는 고귀한 일을 했으니 이번만큼은 이 정도의 무례 쯤이야 눈감아 주겠다. 너는 본질적으로 연약함에도 불구하고 나에게서 도둑질을 했던 자들이 보여주지 못한, 또한 앞으로도 결코 보여주지 못할 용기를 보여주었다!\n\n내 마음이 변해 너의 목숨을 거두기 전에 그들에게 돌아가라. 그리고 전해라. 이제부터는 안전할 것이라고...", progress = "<class>님, 살아서 돌아왔군요! 그렇다면 적어도 우리 중 한 명에게도 해당된다는 뜻이겠죠?\n\n어떻게 된 건지 남김없이 얘기해 주세요!", completion = "그가 정말 그렇게 말했단 말인가요? 오, 그는 분명 살아 있는 내 용병단원들에게 앞으로 더욱 큰 재앙이 닥칠 거라는 암시를 했었는데... 그랬던 그가 암살자와 추적자 영혼들을 거두어 들이기로 했다니 믿을 수가 없군요.\n\n내 생에 최고의 날이 아닐 수 없어요, &lt;class&gt;님! 당신은 그 누구도 하기 힘든 일을 해냈고, 당신 덕분에 우리가 저지른 죄를 어느 정도 용서받게 되었어요.\n\n정말 고마워요! 감사의 표시로 이걸 드리고 싶네요. 그걸 사용하면 당신이 이전에 가 본 적이 있는 유령이 출몰하는 장소에서 영혼과 그 밖의 다른 것들을 소환할 수 있을 거랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n기원의 화로기원의 화로: 설명서"},
[8997] = {title = "다시 출발점으로", objective = "아이언포지의 왕좌에 있는 델리아나와 대화해야 합니다.", description = "이것으로 작별인 듯싶네요, 내 소중한 친구님. 난 언제나 여기 있을 테니 말상대가 필요하다면 종종 들려주세요. 검은바위 첨탑 공격을 위해 동료들을 기다리는 사이에 들릴 수 있지 않겠어요?\n\n흑, 내가 눈물을 보이기 전에 어서 가세요. 아이언포지에 있는 델리아나에게 돌아가 무슨 일이 있었는지 말해주세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8998] = {title = "다시 출발점으로", objective = "오그리마 지혜의 골짜기의 그롬마쉬 요새로 가서 모크바르와 대화하십시오.", description = "친구여, 이것으로 작별인 듯싶네요. 하지만, 전 언제나 여기 있을 테니 말동무가 필요할 때면 종종 들러주세요. 검은바위 첨탑을 함께 공격할 동료를 기다리는 사이에 올 수 있지 않겠어요.\n\n자, 제가 눈물을 보이기 전에 어서 떠나세요. 그리고 오그리마에 있는 모크바르에게 가서 무슨 일이 있었는지 말해주시고요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[8999] = {title = "은혜의 보답", objective = "델리아나에게 자연의정수 두건과 자연의정수 조끼를 주십시오.", description = "정말 놀라운 얘기로군요! 저 그리고 관련된 모든 이들의 진심 어린 감사를 바칩니다. 이제야 비로소 두 눈 감고 편히 잘 수 있겠군요.\n\n당신에게 드릴 보상에 대해서 말인데 제가 가지고 있는 물건 중에 마음에 들 만한 게 분명히 있을 겁니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야생의정수 두건야생의정수 조끼"},
[9004] = {title = "은혜의 보답", objective = "델리아나에게 어둠추적자 모자와 어둠추적자 튜닉을 주십시오.", description = "정말 놀라운 얘기로군요! 저 그리고 관련된 모든 이들의 진심 어린 감사를 바칩니다. 이제야 비로소 두 눈 감고 편히 잘 수 있겠군요.\n\n당신에게 드릴 보상에 대해서 말인데 제가 가지고 있는 물건 중에 마음에 들만한 게 분명히 있을 겁니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n검은장막의 모자검은장막의 튜닉"},
[9007] = {title = "마지막 보은", objective = "모크바르에게 자연의정수 두건과 자연의정수 조끼를 주어야 합니다.", description = "정말 놀라운 얘기로군! 고맙소, <name>... 나뿐만 아니라 이 일과 관련된 모든 이들이 분명 진심으로 당신에게 감사할 거요. 덕분에 우리는 과거의 실수로부터 자유를 찾았으니까.\n\n당신에게 줄 보상에 대해서 말인데, 내가 아끼는 물건 중에 마음에 쏙 들만한 게 분명히 있을 거요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야생의정수 두건야생의정수 조끼"},
[9010] = {title = "마지막 보은", objective = "모크바르에게 어둠추적자 모자와 어둠추적자 튜닉을 주어야 합니다.", description = "정말 놀라운 얘기로군! 고맙소, <name>... 나뿐만 아니라 이 일과 관련된 모든 이들이 분명 진심으로 당신에게 감사할 거요. 덕분에 우리는 과거의 실수로부터 자유를 찾았으니까.\n\n당신에게 줄 보상에 대해서 말인데, 내가 아끼는 물건 중에 마음에 쏙 들만한 게 분명히 있을 거요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n검은장막의 모자검은장막의 튜닉"},
[9015] = {title = "도전", objective = "검은바위 나락의 법의 심판장으로 가서 대법관 그림스톤에 의해 선고받은대로 한가운데에 도전의 깃발을 설치해야 합니다. 텔드렌과 그의 검투사들을 해치운 후 군주 발타라크의 첫 번째 아뮬렛 조각을 가지고 동부 역병지대에 있는 안시온 하몬에게 돌아가야 합니다.", description = "자, 잘 들으세요. 깃발이 제대로 기능을 발휘하게 하려면 검은바위 나락의 법의 심판장에 들어가야 합니다. 대법관 그림스톤이 그대에게 선고를 내리도록 하고 깃발을 도전의 표시로 땅에 단단히 고정하십시오.\n\n그대의 희생자가 될 대상은 자신을 억제하지 못하고 그대와 싸우고 싶은 욕망으로 가득 차 싸움에 뛰어들 것입니다. 원하는 목적을 이룬 후에는 안시온에게 돌아가도록 하십시오. 그럼 엘룬의 축복이 함께하기를.", progress = "돌아왔군!", completion = "메달의 일부를 찾았소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[9016] = {title = "안시온의 작별 인사", objective = "자연의정수 장화, 자연의정수 킬트, 자연의정수 어깨갑옷을 하나씩 가지고 오그리마에 있는 모크바르에게 돌아가십시오.", description = "이 아뮬렛에는 발타라크의 영혼이 담겨 있었소. 우리는 탐욕에 눈이 멀어 아뮬렛을 세 조각으로 나누는 어리석은 실수를 저질렀지. 우리를 기다리고 있는 저주에 대해서는 전혀 알지 못한 채...\n\n발타라크의 저주를 막을 수 있는 유일한 방법은 아뮬렛을 하나로 다시 합치는 것뿐이오. 모크바르에게 돌아가서 전하시오. 보들리만이 나머지 조각을 찾을 수 있는 유일한 희망이라고! 그리고 당신에게 필요한 보상이 있으면 그것도 함께 얘기하시오.\n\n이제는 평화롭게 잠들 수 있었으면... 당신에게 끝없는 행운이 있기를 빌겠소. 아마도 운이 많이 따라줘야 할 거요!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n야생의정수 장화야생의정수 킬트야생의정수 어깨갑옷"},
[9018] = {title = "안시온의 작별 인사", objective = "원소술사 장화, 원소술사 다리보호구, 원소술사 어깨보호대를 하나씩 가지고 오그리마에 있는 모크바르에게 돌아가십시오.", description = "이 아뮬렛에는 발타라크의 영혼이 담겨 있었소. 우리는 탐욕에 눈이 멀어 아뮬렛을 세 조각으로 나누는 어리석은 실수를 저질렀지. 우리를 기다리고 있는 저주에 대해서는 전혀 알지 못한 채...\n\n발타라크의 저주를 막을 수 있는 유일한 방법은 아뮬렛을 하나로 다시 합치는 것뿐이오. 모크바르에게 돌아가서 전하시오. 보들리만이 나머지 조각을 찾을 수 있는 유일한 희망이라고! 그리고 당신에게 필요한 보상이 있으면 그것도 함께 얘기하시오.\n\n이제는 평화롭게 잠들 수 있었으면... 당신에게 끝없는 행운이 있기를 빌겠소. 아마도 운이 많이 따라줘야 할 거요!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n마술사의 장화마술사의 다리보호구마술사의 어깨보호대"},
[9020] = {title = "안시온의 작별 인사", objective = "어둠추적자 장화, 어둠추적자 바지, 어둠추적자 어깨갑옷을 가지고 오그리마에 있는 모크바르에게 돌아가십시오.", description = "이 아뮬렛에는 발타라크의 영혼이 담겨 있었소. 우리는 탐욕에 눈이 멀어 아뮬렛을 세 조각으로 나누는 어리석은 실수를 저질렀지. 우리를 기다리고 있는 저주에 대해서는 전혀 알지 못한 채...\n\n발타라크의 저주를 막을 수 있는 유일한 방법은 아뮬렛을 하나로 다시 합치는 것뿐이오. 모크바르에게 돌아가서 전하시오. 보들리만이 나머지 조각을 찾을 수 있는 유일한 희망이라고! 그리고 당신에게 필요한 보상이 있으면 그것도 함께 얘기하시오.\n\n이제는 평화롭게 잠들 수 있었으면... 당신에게 끝없는 행운이 있기를 빌겠소. 아마도 운이 많이 따라줘야 할 거요!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n검은장막의 장화검은장막의 바지검은장막의 어깨갑옷"},
[9021] = {title = "안시온의 작별 인사", objective = "공포의안개 신발, 공포의안개 다리보호구, 공포의안개 어깨보호대를 하나씩 가지고 오그리마에 있는 모크바르에게 돌아가십시오.", description = "이 아뮬렛에는 발타라크의 영혼이 담겨 있었소. 우리는 탐욕에 눈이 멀어 아뮬렛을 세 조각으로 나누는 어리석은 실수를 저질렀지. 우리를 기다리고 있는 저주에 대해서는 전혀 알지 못한 채...\n\n발타라크의 저주를 막을 수 있는 유일한 방법은 아뮬렛을 하나로 다시 합치는 것뿐이오. 모크바르에게 돌아가서 전하시오. 보들리만이 나머지 조각을 찾을 수 있는 유일한 희망이라고! 그리고 당신에게 필요한 보상이 있으면 그것도 함께 얘기하시오.\n\n이제는 평화롭게 잠들 수 있었으면... 당신에게 끝없는 행운이 있기를 빌겠소. 아마도 운이 많이 따라줘야 할 거요!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n죽음의안개 신발죽음의안개 다리보호구죽음의안개 어깨보호구"},
[9023] = {title = "완벽한 독", objective = "세나리온 요새에 있는 더크 썬더우드가 베녹시스의 독주머니와 쿠린낙스의 독주머니를 가져다달라고 부탁했습니다.", description = "우리 형제는 라벤홀트 장원에서 독을 다루는 일을 맡고 있지요.\n\n라벤홀트 경께서 저에게 새로운 독성 화합물을 찾으라는 지시를 하나 내리셨습니다. 줄구룹과 안퀴라즈 폐허에 사는 생명체에게서 추출한 독주머니로 만들 수 있지요.\n\n저주 받은 그곳의 두 짐승이 우리가 찾는 특별한 독을 지니고 있습니다. 쿠린낙스와 베녹시스의 독주머니를 가져다주시면 그 은혜 평생 잊지 않겠습니다.", progress = "<name>, 이번 임무는 결코 쉽지 않을 겁니다. 동료를 충분히 모아서 함께 가야할 겁니다.", completion = "라벤홀트 경께서 고마워하십니다. 영웅이여, 마음에 드는 것으로 골라 보세요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n라벤홀트 학살자쉬브스프로켓의 비수썬더우드 천둥검루날의 습기망치파라드의 연발 석궁시몬의 교화 망치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[9024] = {title = "아리스탄의 예감", objective = "스톰윈드 상업 지구에 있는 모건 페슬에게 은은한 향수과 매혹적인 향수을 각 한 병씩 가져가야 합니다.", description = "오, 알았습니다! 바람에 실려온 새 향수의 향기를 느껴본 적이 있지요? 요즘 유행하고 있는 새로운 은은한 향과 매혹적인 향수의 향기 말입니다. 우리 경비병들이 그리 쉽사리 그들의 임무를 등한시하진 않을 겁니다.\n\n그들의 생각이 어떤 바보 같은 연금술사에 의해 흐려지지 않는다면 말입니다.\n\n확실히 할 수 있는 한 가지 방법이 있긴 합니다. 모건 페슬에게 은은한 향수와 매혹적인 향수를 각 한 병을 가져가시면 그가 내 의심이 맞는지 확인해 줄 겁니다. 다시 돌아오시면 병을 구매하신데 사용된 돈을 변상해 드리도록 하겠습니다.", progress = "도와드릴 일이라도 있습니까?", completion = "아리스탄의 근심이 이해가 되지만 그가 너무 과잉반응한다는 생각이 드네요. 젊은 선남선녀들이 그들이 하고자 하는 것을 하게 놔두는 게 어떻겠습니까? 아리스탄이 젊은 시절에 사랑의 의미를 잊은 것 같군요.\n\n그러나 내가 방금 한 말을 그에겐 하지 않는 게 좋겠습니다. 우린 그 친구를 만족시키게 될 테니까요.", rewards = nil},
[9025] = {title = "모건의 발견", objective = "스톰윈드의 상업 지구의 은행 밖에 있는 아리스탄 모탈에게 돌아가야 합니다.", description = "자, 이제 확인해 보도록 하죠. 흠, 아리스탄이 뭔가 알아채고 있는 것 같군요. 사랑의 묘약에 사용된 물질과 모르는 사이에 심리적으로 행동을 변화시키는 약간의 약품의 자취를 미량 발견했습니다.\n\n향수에 그런 성분이 포함된다는 것은 들어본 적이 없는 일이지만 이번에 발견한 약간의 재료들엔 들어있군요. 흠, 냄새가 기묘합니다.", progress = nil, completion = "이게 문제가 된다고 생각하는 내내, 내 우려의 근원을 찾아내는 게 과연 옳은 것인지가 아직도 마음을 어지럽게 하는군요. 우린 신중하게 이후에 취할 행동에 대해 고려해야 합니다.\n\n자, 은은한 향과 매혹적인 향의 향수를 구입하는 데 든 비용을 변상해 드리도록 하겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n초콜릿 상자붉은 꽃잎 한줌"},
[9026] = {title = "향기의 근원 추적", objective = "스톰윈드의 상업 지구에 있는 황금장미 여관의 주인인 알리슨과 대화해야 합니다.", description = "우린 그 향수에 쓰인 원료를 찾아야 합니다. 요즘 들어 경비병들을 포함해서 평소보다 더 많은 사람들이 황금장미 여관을 드나드는 것을 보았습니다. 그녀가 그 향수를 팔고 있는지 여관주인인 알리슨과 얘기해 보십시오. 그녀가 그 향수를 어디서 들여왔는지 얘기해 줄 수 있을 겁니다.", progress = nil, completion = "아, 네. 최근에 매혹적인 향과 은은한 향의 향수를 재고로 구입했답니다. 아주 잘 팔려서 얼마나 오래 진열하고 있을 수 있을지 모르겠네요.\n\n굳이 물으신다면 따분할 거 같은데요... 모두에게 같은 냄새가 나죠? 제가 파는 향수 냄새가 무척 향기롭거든요.", rewards = nil},
[9027] = {title = "향기의 근원 추적", objective = "스톰윈드 운하 지구 근처에 최고급 실타래 상점에 있는 에버트 소리삼과 대화해야 합니다.", description = "은은한 향기에 대해 뭔가 기묘한 것이요? 있을 수 없어요. 향수를 사 가신 손님 중에서 기묘한 모습을 보인 분은 많이 보지 못했거든요.\n\n보세요, 향수에 뭔가 잘못된 것이 있다면 저도 알고 싶어요. 이 향수 재고품을 에버트 소리삼이라고 마을에 새로운 상인에게 구입했답니다.\n\n그는 최고급 실타래로 향수 재고를 배달하러 갈 거라고 했었어요.", progress = nil, completion = "예, 물론입니다. 그 향수들은 요즘에 대단히 인기가 좋은 품목입니다. 손님께서는 그 향수를 찾으시는 5번째나 6번째 손님이십니다.\n\n흠... 죄송합니다만 재고 물량이 모두 다 팔린 것 같군요. 원하신다면, 황금장미 여관의 주인인 알리슨 씨와 얘기해 보셔야겠습니다.\n\n손님이신데 시간을 허비하시면 아니 되지요. 손님께서도 이제 곧 은은한 향수의 저항할 수 없는 매력을 아시게 될 겁니다.", rewards = nil},
[9028] = {title = "밝혀진 향기의 근원", objective = "라벤홀트 장원을 지나 힐스브래드 산기슭에서 연금술사 스태프론 리런트를 찾아야 합니다.", description = "뭐라고요? 배신이라고요? 무슨 말씀이십니까, 아닙니다요. 제 의도는 진정 순수한 마음에서였습니다.\n\n쓰라린 구애의 의식에서 오는 아픔을 달래고자 하는 자들을 도운 것이 그리도 잘못된 건가요? 왜 이러십니까... 그건 범죄가 아닙니다.\n\n그리고 제가 말한 해가 되지 않는다는 것을 증명하기 위해 향수를 들여온 근원지에 대해 말씀드리겠습니다.\n\n그들이 연금술사의 일을 하고 있는 스태프론 리런트에게서 나에게 배송해주었습니다. 전 그와 얘기해 보지 못했습니다요, 손님.\n\n우리와 고블린 친구들을 중계하는 자의 말에 의하면 스태프론이 수수께끼의 라벤홀트 장원을 지나 힐스브래드 건너 산기슭의 구릉에서 일했다고 합니다. 산길이라 찾기 쉽지 않을테지만 그를 찾는 데 행운이 따르길 바랍니다.", progress = nil, completion = "그렇네, 내가 그 향수들을 만들었지. 놀라운 향기지 않나? 저항할 수 없지.\n\n얼라이언스와 호드의 용사들이 이 사랑의 느낌에 매료되면, 그들은 어둠의 의회의 부활을 막을 힘을 잃게 될 것이야.\n\n그들은 약해지고, 준비하지 못하고 당하게 될 것이야. 그들이 사랑했던 자들 때문에 아파하는 것처럼, 균형을 잃게 되겠지.\n\n실로 간단한 방법이지 않나? 왜 진작에 이 생각을 못했을까? 모든 약점은 마음에서 시작되지. 그리고 자네가 이 필연을 막을 수 있는 건 아무것도 없네.", rewards = nil},
[9029] = {title = "끓고 있는 가마솥", objective = "가마솥에서 향기로운 냄새가 솔솔 풍깁니다.", description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n푸른색 정찬복보라색 정찬복붉은색 정찬복아름다운 푸른색 드레스아름다운 보라색 드레스아름다운 붉은색 드레스"},
[9032] = {title = "보들리의 불행한 운명", objective = "검은바위 산으로 가십시오. 검은바위 첨탑 근처에서 4차원 유령 탐색기를 사용해 보들리를 찾아야 합니다.아뮬렛에 발타라크의 영혼이 담겨 있다는 말입니까? 그렇게 강력한 저주의 보호를 받고 있었다고 해도 그리 놀라운 일은 아니로군요.\n\n보들리의 위치를 알아내는 건 그다지 쉬운 일이 아닙니다. 마지막으로 듣기로는 그가 검은바위 첨탑으로 탐험을 하기 위해 준비 중이었다고 합니다. 그 뒤로는 그에 관한 소식을 듣지 못했습니다.\n\n검은바위 산에서 그를 찾아보십시오. 하지만, 이미 죽은 건 아닌지 걱정스럽군요. 고블린의 장치를 가지고 가십시오, 친구여.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", description = "아뮬렛에 발타라크의 영혼이 담겨 있다는 말입니까? 그렇게 강력한 저주의 보호를 받고 있었다고 해도 그리 놀라운 일은 아니로군요.\n\n보들리의 위치를 알아내는 건 그다지 쉬운 일이 아닙니다. 마지막으로 듣기로는 그가 검은바위 첨탑으로 탐험을 하기 위해 준비 중이었다고 합니다. 그 뒤로는 그에 관한 소식을 듣지 못했습니다.\n\n검은바위 산에서 그를 찾아보십시오. 하지만, 이미 죽은 건 아닌지 걱정스럽군요. 고블린의 장치를 가지고 가십시오, 친구여.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[9033] = {title = "전쟁의 메아리", objective = "동부 역병지대의 희망의 빛 예배당에 있는 사령관 엘리고르 돈브링어가 살아 움직이는 괴물 5마리, 돌가죽 가고일 5마리, 죽음의 기사단 대장 8명, 맹독 늑대거미 3마리를 처치해달라고 부탁했습니다.", description = "마지막 전쟁을 치른 후로 5년이 지났구려...\n\n수만 명이 목숨을 잃었소만 도대체 무엇을 위해 죽었어야 한 것이지? 위협은 결코 완전히 사라지지 않았소이다.\n\n리치 왕이 다시 움직이기 시작했소... 그의 충실한 종인 켈투자드가 다시 한 번 우리들의 땅을 침략하기 위해 군대를 모으고 있소.\n\n결코 이를 용납해서는 안 될 것이오! 당신의 충성심을 증명해 보이시오. 목숨을 잃거나 불구가 될지라도 그들의 광기를 막을 각오가 되어 있다는 것을 증명해 보이시오. 그러면 은빛 여명회와 붉은 십자군은 힘을 모아 당신을 지원하고 당신의 요청에 응하겠소이다.\n\n낙스라마스로 가서 그곳에 있는 스컬지를 해치우시오...", progress = nil, completion = "잘 처리했소! 이 일에 대한 보상으로 희망의 빛 예배당에 있는 우리 동료들이 당신을 위해 예배를 드릴 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[9034] = {title = "무쌍의 흉갑", objective = "동부 역병지대의 희망의 빛 예배당에 있는 코팩스에게 더럽혀진 흉갑 1개, 닳아해진 판금 조각 25개, 아케이나이트 주괴 4개, 마력의 결정체 2개를 가져가면 무쌍의 흉갑을 만들어 줄 것입니다.", description = "낙스라마스에서 스컬지와 전투를 치르는 동안 더럽혀진 전투장비와 닳아해진 판금 조각을 발견하게 되거든 내게 가져오시오. 그러면 당신에게 영웅들이 입던 갑옷을 만들어 주겠소.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n무쌍의 흉갑"},
