[9042] = {title = "무쌍의 팔보호구", objective = "동부 역병지대의 희망의 빛 예배당에 있는 코팩스에게 더럽혀진 팔보호구 1개, 닳아해진 판금 조각 6개, 아케이나이트 주괴 1개, 마력의 결정체 1개를 가져가면 무쌍의 팔보호구를 만들어 줄 것입니다.", description = "낙스라마스에서 스컬지와 전투를 치르는 동안 더럽혀진 전투장비와 닳아해진 판금 조각을 발견하게 되거든 내게 가져오시오. 그러면 당신에게 영웅들이 입던 갑옷을 만들어 주겠소.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n무쌍의 팔보호구"},
[9043] = {title = "구원의 튜닉", objective = "동부 역병지대의 희망의 빛 예배당에 있는 사령관 엘리고르 돈브링어에게 더럽혀진 튜닉 1개, 닳아해진 판금 조각 25개, 아케이나이트 주괴 4개, 거친 경화 가죽 3개를 가져가면 구원의 튜닉을 만들어 줄 것입니다.", description = "낙스라마스의 군주들의 시체에서 전사한 우리 영웅들의 유품을 찾을 수 있을 것이오. 닳아해진 판금 조각, 저주받은 갑옷을 다시 고칠 수 있는 재료와 함께 부정한 용도로 사용되고 있는 그들의 유품을 가지고 오시오. 그러면 당신에게 영웅들의 힘이 담긴 구원의 튜닉을 만들어 주겠소.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n구원의 튜닉"},
