[9049] = {title = "구원의 벨트", objective = "동부 역병지대의 희망의 빛 예배당에 있는 사령관 엘리고르 돈브링어에게 더럽혀진 벨트 1개, 닳아해진 판금 조각 8개, 아케이나이트 주괴 1개, 마력의 결정체 3개를 가져가면 구원의 벨트를 만들어 줄 것입니다.", description = "낙스라마스의 군주들의 시체에서 전사한 우리 영웅들의 유품을 찾을 수 있을 것이오. 닳아해진 판금 조각, 저주받은 갑옷을 다시 고칠 수 있는 재료와 함께 부정한 용도로 사용되고 있는 그들의 유품을 가지고 오시오. 그러면 당신에게 영웅들의 힘이 담긴 구원의 벨트를 만들어 주겠소.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n구원의 벨트"},
[9050] = {title = "구원의 손목보호구", objective = "동부 역병지대의 희망의 빛 예배당에 있는 사령관 엘리고르 돈브링어에게 더럽혀진 손목보호대 1개, 닳아해진 판금 조각 6개, 아케이나이트 주괴 1개, 거친 경화 가죽 2개를 가져가면 구원의 손목보호구를 만들어 줄 것입니다.", description = "낙스라마스의 군주들의 시체에서 전사한 우리 영웅들의 유품을 찾을 수 있을 것이오. 닳아해진 판금 조각, 저주받은 갑옷을 다시 고칠 수 있는 재료와 함께 부정한 용도로 사용되고 있는 그들의 유품을 가지고 오시오. 그러면 당신에게 영웅들의 힘이 담긴 구원의 손목보호구을 만들어 주겠소.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n구원의 손목보호구"},
[9051] = {title = "독성 테스트", objective = "데빌사우루스 가시로 데빌사우루스를 찔러야 합니다. 임무를 완수하면 운고로 분화구에 있는 토르와 패스파인더에게 돌아가야 합니다.", description = "당신 덕에 제조할 수 있었던 독에는 특별한 용도가 있소. 이곳 분화구에는 거대한 데빌사우루스가 살고 있소. 그 위험한 놈 때문에 사냥은커녕 살아가는 데도 지장이 많소이다. 내게 데빌사우루스를 해치울 수 힘이 없는 것은 아니지만 한 놈을 죽인다고 해도 또 다른 놈이 와서 영역 표시를 할 게 뻔하오.\n\n자, 독이 묻은 이 가시를 가지고 가서 살아 있는 데빌사우루스의 몸속 깊숙이 찌르시오. 독이 퍼지면 데빌사우루스가 얌전해질 거요. 얼마나 갈지는 알 수 없지만...", progress = nil, completion = "고맙소, &lt;name&gt;. 당신은 용감하고 현명한 분이오.\n\n자, 데빌사우루스가 독에 어떤 반응을 보였는지 말해주겠소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[9052] = {title = "붉은꽃잎 독", objective = "붉은갓버섯 8개와 고리쉬 독침 8개를 모아서 운고로 분화구에 있는 토르와 패스파인더에게 돌아가십시오.", description = "이곳 분화구에 사는 거대한 야수를 얌전하게 만들 수 있는 독 제조를 좀 도와주시오. 그다지 위험한 일은 아니지만 <class>의 날카로운 눈이 없으면 재료를 모을 수 없소이다.\n\n붉은갓버섯이 분화구 전 지역에 분포한 붉은꽃잎 씨앗 속에서 자라고 있소. 그리고 고리쉬 독침은 분화구 남쪽 갈래굽이 구렁 안팎을 날아다니는 거대한 병정 고리쉬에게서 얻을 수 있을 거요.", progress = "재료 수집에는 성공하셨소?", completion = "드디어 필요한 재료가 다 모였군!\n\n내가 수집한 운고로 토양에 첨가하면 간단하게 독을 제조할 수 있을 거요...", rewards = "다음과 같은 것들을 받습니다:\n\n일급 치유 물약"},
[9053] = {title = "더욱 강력한 재료", objective = "가라앉은 사원 하층부의 수호병으로부터 썩은 덩굴을 찾은 후 토르와 패스파인더에게 돌아가십시오.", description = "우려했던 대로 그 맹수에게 사용하기에는 독성이 너무 약했군.\n\n효과가 더 확실한 독이 필요하오. 아탈학카르 신전의 하층부로 가시오. 제단의 비밀을 푼 후 그곳을 지키는 수호병으로부터 썩은 덩굴을 찾아야 하오. 위험한 곳이니 동료들과 함께 가는 게 좋을 거요.\n\n일을 마치면 돌아오시오.", progress = "썩은 덩굴은 찾았소?", completion = "드디어 완벽한 독이 만들어질 거요. 이미 날 위해 너무 많은 일을 해주었으니 염치없이 그 괴물에게 독을 사용하는 일까지 부탁하지는 못하겠군.\n\n&lt;name&gt;, 정말 감사하오. 부디 편안한 여행되길...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n불곰 모피 조끼숲의 은총달그림자 지팡이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[9054] = {title = "지하추적자 튜닉", objective = "동부 역병지대의 희망의 빛 예배당에 있는 사냥꾼 레오폴드에게 더럽혀진 튜닉 1개, 닳아해진 사슬 조각 25개, 아케이나이트 주괴 4개, 거친 경화 가죽 3개를 가져가면 지하추적자 튜닉을 만들어 줄 것입니다.", description = "전 지하마귀의 껍질과 다양한 신체 부위를 활용할 방법을 발견했습니다. 지하마귀의 껍질을 낙스라마스에서 사라진 더럽혀진 마법의 방어구에 결합하면 아주 가벼우면서도 엄청난 힘을 지닌 갑옷 세트를 만들 수 있단 말입니다.\n\n필요한 재료를 가지고 오시면 아제로스 대륙에서 전혀 볼 수 없었던 갑옷을 만들어 드리겠습니다!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n지하추적자 튜닉"},
