[9060] = {title = "지하추적자 벨트", objective = "동부 역병지대의 희망의 빛 예배당에 있는 사냥꾼 레오폴드에게 더럽혀진 벨트 1개, 닳아해진 사슬 조각 8개, 아케이나이트 주괴 1개, 마력의 결정체 3개를 가져가면 지하추적자 벨트를 만들어 줄 것입니다.", description = "전 지하마귀의 껍질과 다양한 신체 부위를 활용할 방법을 발견했습니다. 지하마귀의 껍질을 낙스라마스에서 사라진 더럽혀진 마법의 방어구에 결합하면 아주 가벼우면서도 엄청난 힘을 지닌 갑옷 세트를 만들 수 있단 말입니다.\n\n필요한 재료를 가지고 오시면 아제로스 대륙에서 전혀 볼 수 없었던 갑옷을 만들어 드리겠습니다!", progress = "부탁한 재료를 가지고 돌아온 겁니까?", completion = "고귀한 분에게 딱 맞는 벨트로군! 당신을 위해 준비했습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n지하추적자 벨트"},
[9061] = {title = "지하추적자 손목보호대", objective = "동부 역병지대의 희망의 빛 예배당에 있는 사냥꾼 레오폴드에게 더럽혀진 손목보호대 1개, 닳아해진 사슬 조각 6개, 아케이나이트 주괴 1개, 거친 경화 가죽 2개를 가져가면 지하추적자 손목보호대를 만들어 줄 것입니다.", description = "전 지하마귀의 껍질과 다양한 신체 부위를 활용할 방법을 발견했습니다. 지하마귀의 껍질을 낙스라마스에서 사라진 더럽혀진 마법의 방어구에 결합하면 아주 가벼우면서도 엄청난 힘을 지닌 갑옷을 만들 수 있단 말입니다.\n\n필요한 재료를 가지고 오시면 아제로스 대륙에서 전혀 볼 수 없었던 갑옷을 만들어 드리겠습니다!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n지하추적자 손목보호대"},
[9063] = {title = "토르와 패스파인더", objective = "운고로 분화구에 있는 토르와 패스파인더와 대화하십시오.", description = "토르와 패스파인더라는 사냥꾼이 드루이드에게 도움을 요청했습니다. 자연을 아끼는 우리 드루이드만이 그를 도울 능력이 있다고 말하더군요.\n\n운고로 분화구와 타나리스 사막을 잇는 길이 하나 있습니다. 그 길을 따라 분화구로 들어가면 바로 토르와를 만날 수 있을 겁니다.", progress = nil, completion = "이 먼 곳까지 날 만나러 와주다니... &lt;class&gt;|1이여;여;, 제때 잘 오셨소.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[9065] = {title = "The \"Chow\" Quest (123)aa", objective = "Kill Kobold Vermin, 2 of em.$Tpunk;!  Kill Kobold Vermin, 2 of em.다음과 같은 것들을 배웁니다:\n\n", description = "$Tpunk;!  Kill Kobold Vermin, 2 of em.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n치유\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n닭\n\n다음과 같은 것들 또한 받습니다:\n\n맑은 샘물최하급 치유 물약"},
[9068] = {title = "지축이동의 튜닉", objective = "동부 역병지대의 희망의 빛 예배당에 있는 림블랫 어스쉐터에게 더럽혀진 튜닉 1개, 닳아해진 사슬 조각 25개, 아케이나이트 주괴 4개, 거친 경화 가죽 3개를 가져가면 지축이동의 튜닉을 만들어 줄 것입니다.", description = "이 땅을 지키다 전사한 이들의 갑옷을 되찾아 주겠소?\n\n그들의 갑옷은 더럽혀져 사악한 음모에 쓰이고 있는 것이 분명하오. 하지만 닳아해진 사슬 조각과 함께 부정한 용도로 사용되고 있는 갑옷을 새로 고치면 다시 한 번 전투에 사용할 수 있소이다.\n\n전사한 이들이 남긴 유품과 함께 정화에 필요한 재료를 가지고 오면 지축이동의 튜닉은 당신 것이 될 것이오.\n\n자, 어서 가서 낙스라마스를 조사해 보시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n지축이동의 튜닉"},
[9069] = {title = "지축이동의 다리갑옷", objective = "동부 역병지대의 희망의 빛 예배당에 있는 림블랫 어스쉐터에게 더럽혀진 다리보호대 1개, 닳아해진 사슬 조각 20개, 아케이나이트 주괴 3개, 거친 경화 가죽 5개를 가져가면 지축이동의 다리갑옷을 만들어 줄 것입니다.", description = "이 땅을 지키다 전사한 이들의 갑옷을 되찾아 주겠소?\n\n그들의 갑옷은 더럽혀져 사악한 음모에 쓰이고 있는 것이 분명하오. 하지만 닳아해진 사슬 조각과 함께 부정한 용도로 사용되고 있는 갑옷을 새로 고치면 다시 한 번 전투에 사용할 수 있소이다.\n\n전사한 이들이 남긴 유품과 함께 정화에 필요한 재료를 가지고 오면 지축이동의 다리갑옷은 당신 것이 될 것이오.\n\n자, 어서 가서 낙스라마스를 조사해 보시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n지축이동의 다리갑옷"},
