[9111] = {title = "신념의 로브", objective = "동부 역병지대의 희망의 빛 예배당에 있는 신부 이니고 몬토이에게 더럽혀진 로브 1개, 닳아해진 천 조각 25개, 달빛 옷감 4개, 마력의 결정체 2개를 가져가면 신념의 로브를 만들어 줄 것입니다.", description = "<당신 앞의 허공에 대고 이상한 몸짓을 취하는 몬토이 신부>\n\n축복받은 <형제/자매>여, 전사한 이들의 갑옷을 찾으셨습니까? 전장에서 마지막 숨을 거둔 가엾은 영혼들은 명예와 그들의 모든 것을 잃었습니다.\n\n부정한 용도로 사용되고 있는 그들의 유품과 함께 정화에 필요한 재료를 가지고 오십시오. 그러면 당신은 신뢰가 무엇인지 알게 될 것입니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n신념의 로브"},
[9112] = {title = "신념의 다리보호구", objective = "동부 역병지대의 희망의 빛 예배당에 있는 신부 이니고 몬토이에게 더럽혀진 다리보호구 1개, 닳아해진 천 조각 20개, 달빛 옷감 4개, 마력의 결정체 2개를 가져가면 신념의 다리보호구를 만들어 줄 것입니다.", description = "<당신 앞의 허공에 대고 이상한 몸짓을 취하는 몬토이 신부>\n\n축복받은 <형제/자매>여, 전사한 이들의 갑옷을 찾으셨습니까? 전장에서 마지막 숨을 거둔 가엾은 영혼들은 명예와 그들의 모든 것을 잃었습니다.\n\n부정한 용도로 사용되고 있는 그들의 유품과 함께 정화에 필요한 재료를 가지고 오십시오. 그러면 당신은 신뢰가 무엇인지 알게 될 것입니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n신념의 다리보호구"},
