[9272] = {title = "해적 복장 입기", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n해적 복장 꾸러미"},
[9273] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n북극곰 목줄"},
[9292] = {title = "부서진 죽음의 수정", objective = "스톰윈드 성문 외곽에 있는 부관 오린에게 부서진 죽음의 수정을 가져가야 합니다.", description = "혐오스러운 언데드의 시체에서 죽음의 기운을 희미하게 발산하는 수정을 발견했습니다.", progress = "내게 무슨 볼일이라도 있소?", completion = "음, 우리 스톰윈드를 침략한 혐오스러운 언데드의 시체에서 이걸 발견했단 말이오?\n\n그렇지 않아도 스컬지들이 소환한 죽음의 요새에 대한 전갈을 받은 적이 있소이다. 스톰윈드 안에도 그런 요새를 세우려는 모양이군. 놈들의 계획을 사전에 막았으니 참으로 다행스러운 일이구려.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n축복받은 마술사 오일신성한 숫돌"},
[9295] = {title = "전방에서 온 편지", objective = "동부 역병지대의 희망의 빛 예배당에 있는 기록 보관원에게 찢어진 편지를 가져가야 합니다.", description = "수많은 스컬지 앞잡이들의 시체 중 하나에서 편지를 발견했습니다. 편지의 상태나 냄새로 보아 언데드가 꽤 오랫동안 지니고 있었던 것 같습니다. 희망의 빛 예배당에는 이 편지를 좀 더 조사하려는 사람이 있을 것입니다.", progress = "무슨 일이십니까? 손에 들고 있는 그건 뭐죠?", completion = "이런 안타까운 일이... 이 편지는 한 병사가 사랑하는 이에게 보낸 건데 결국 전달되지 못했군요. 편지에 자세히 나와 있는 사건은 몇 년 전에 발생한 일이니, 받을 사람이 아직 살아 있을지 모르겠군요.\n\n그래도 어쨌든 희망은 가져봐야겠지요. 편지에 적혀 있는 이름과 내용을 단서로 추적하면 이 병사의 가족을 찾을 수 있을 겁니다. 조사하는 일이 쉽지는 않겠지만, 스톰윈드의 사서가 내게 빚진 것도 있고 하니 이 일에 도움이 되어 줄 겁니다.\n\n편지를 가져와 주셔서 감사합니다. 덕분에 뒤늦게나마 이 병사의 가족에게 마음의 위안을 줄 수 있게 되었군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[9296] = {title = "reuse", objective = "Deliver the Dim Necrotic Stone to SOMEONE.", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", progress = nil, completion = nil, rewards = nil},
