[9302] = {title = "전방에서 온 서한", objective = "동부 역병지대의 희망의 빛 예배당에 있는 기록 보관원에게 구겨진 서한을 가져가야 합니다.", description = "수많은 스컬지 앞잡이들의 시체 중 하나에서 편지를 발견했습니다. 편지의 상태나 냄새로 보아 언데드가 꽤 오랫동안 지니고 있었던 것 같습니다. 희망의 빛 예배당에는 이 편지를 좀 더 조사하려는 사람이 있을 것입니다.", progress = "무슨 일이십니까? 손에 들고 있는 그건 뭐죠?", completion = "이런 안타까운 일이... 이 편지는 한 병사가 사랑하는 이에게 보낸 건데 결국 전달되지 못했군요. 편지에 자세히 나와 있는 사건은 몇 년 전에 발생한 일이니, 받을 사람이 아직 살아 있을지 모르겠군요.\n\n그래도 어쨌든 희망은 가져봐야겠지요. 편지에 적혀 있는 이름과 내용을 단서로 추적하면 이 병사의 가족을 찾을 수 있을 겁니다. 조사하는 일이 쉽지는 않겠지만, 스톰윈드의 사서가 내게 빚진 것도 있고 하니 이 일에 도움이 되어 줄 겁니다.\n\n편지를 가져와 주셔서 감사합니다. 덕분에 뒤늦게나마 이 병사의 가족에게 마음의 위안을 줄 수 있게 되었군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[9304] = {title = "전방에서 온 문서", objective = "동부 역병지대의 희망의 빛 예배당에 있는 기록 보관원에게 흐릿해진 문서를 가져가야 합니다.", description = "수많은 스컬지 앞잡이들의 시체 중 하나에서 편지를 발견했습니다. 편지의 상태나 냄새로 보아 언데드가 꽤 오랫동안 지니고 있었던 것 같습니다. 희망의 빛 예배당에는 이 편지를 좀 더 조사하려는 사람이 있을 것입니다.", progress = "무슨 일이십니까? 손에 들고 있는 그건 뭐죠?", completion = "이런 안타까운 일이... 이 편지는 한 병사가 사랑하는 이에게 보낸 건데 결국 전달되지 못했군요. 편지에 자세히 나와 있는 사건은 몇 년 전에 발생한 일이니, 받을 사람이 아직 살아 있을지 모르겠군요.\n\n그래도 어쨌든 희망은 가져봐야겠지요. 편지에 적혀 있는 이름과 내용을 단서로 추적하면 이 병사의 가족을 찾을 수 있을 겁니다. 조사하는 일이 쉽지는 않겠지만, 스톰윈드의 사서가 내게 빚진 것도 있고 하니 이 일에 도움이 되어 줄 겁니다.\n\n편지를 가져와 주셔서 감사합니다. 덕분에 뒤늦게나마 이 병사의 가족에게 마음의 위안을 줄 수 있게 되었군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[9310] = {title = "희미한 죽음의 수정", objective = "언더시티의 안마당에 있는 부관 루카그에게 희미한 죽음의 수정을 가져가야 합니다.", description = "쓰러진 자의 몸에서 죽음의 기운을 희미하게 발산하는 수정을 발견했습니다.", progress = "무슨 일로 왔나?", completion = "언더시티를 공격한 괴이한 놈에게서 이걸 발견했단 말인가?\n\n그렇지 않아도 스컬지들이 소환한 죽음의 요새에 대한 전갈을 받았네. 아마 언더시티 안에도 그런 요새를 세우려는 모양이군. 앞으로 경계를 더 강화해야겠어...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n축복받은 마술사 오일신성한 숫돌"},
[9317] = {title = "신성한 숫돌", objective = "스컬지 침략자들에게서 죽음의 룬을 8개를 모아 오면 신성한 숫돌 1개를 주겠소. 신성한 숫돌은 전장에서 리치 왕의 부하들을 상대하는 데 큰 도움이 될 것이오.", description = nil, progress = "스컬지 침략자들에게서 죽음의 룬을 8개를 모아 오면 신성한 숫돌 1개를 주겠소. 신성한 숫돌은 전장에서 리치 왕의 부하들을 상대하는 데 큰 도움이 될 것이오.", completion = "고맙소이다. 여기 약속한 신성한 숫돌이니 잘 사용하시기 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n신성한 숫돌"},
[9318] = {title = "축복받은 마술사 오일", objective = "스컬지 침략자들에게서 얻은 죽음의 룬을 은빛 여명회에 가져다준다면 그 대가로 축복받은 마술사 오일 1병을 주도록 하겠소.", description = nil, progress = "스컬지 침략자들에게서 얻은 죽음의 룬을 은빛 여명회에 가져다준다면 그 대가로 축복받은 마술사 오일 1병을 주도록 하겠소.", completion = "앞으로의 전투에서 이 마술사 오일을 유용하게 사용하길 바라오.", rewards = "다음과 같은 것들을 받습니다:\n\n축복받은 마술사 오일"},
[9319] = {title = "어둠을 밝히는 한 줄기 빛", objective = "검은바위 첨탑, 혈투의 전장, 스칼로맨스, 스트라솔름에 있는 화톳불을 찾아서 만져 본 후, 한여름 축제 불꽃지기에게 돌아가야 합니다.", description = "우리만 이 축제를 여는 것은 아니랍니다. 모든 생명체와 모든 문화가 불꽃에 영향을 받고 있습니다. 아무리 어두운 곳에서도 불은 밝게 타오르는 법이지요.\n\n직접 보고 싶으시다면 깊은 곳으로 가십시오. 스칼로맨스, 스트라솔름, 혈투의 전장의 오우거들의 본거지 중 한 곳, 검은바위 첨탑에서 타오르고 있는 화톳불을 찾아보시기 바랍니다. 당신이 돌아올 때까지 전 불꽃을 지키며 이 자리에서 기다리겠습니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n갈무리한 불꽃불타는 꽃"},
[9320] = {title = "일급 마나 물약", objective = "다른 보급품은 물론이고 아주 유용한 일급 마나 물약도 많이 있답니다. 죽음의 룬 15개를 주시면 하나를 드리지요.", description = nil, progress = "다른 보급품은 물론이고 아주 유용한 일급 마나 물약도 많이 있답니다. 죽음의 룬 15개를 주시면 하나를 드리지요.", completion = "여기 있습니다! 부디 조심하세요. 우리 편의 수가 많지 않으므로 전쟁에서 많은 사상자가 발생할 수도 있을 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n일급 마나 물약"},
[9321] = {title = "일급 치유 물약", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n일급 치유 물약"},
[9322] = {title = "칼림도어의 거친 불꽃", objective = "아즈샤라, 실리더스, 운고로 분화구 및 여명의 설원에 있는 한여름 불꽃 축제 야영지를 방문하고 한여름 축제 불꽃지기에게 돌아오십시오.", description = "아제로스 전역에 한여름 불꽃축제가 한창입니다. 칼림도어의 여러 지역도 예외는 아니죠. 당신은 여행자 같군요. 이번 여행은 순조로울 것입니다.\n\n이 축제의 진정한 의미는 당신처럼 두발로 세계를 여행하는 분들이 곳곳에서 맹렬히 타오르는 푸른 불꽃을 두 눈으로 확인하는 데 있답니다. 쌀쌀한 여명의 설원 서부, 아즈샤라 북동부, 실리더스 황무지의 용사의 안식처 근처, 그리고 수풀이 무성한 운고로 입구까지 축제를 축하하는 이들이 환하게 불을 밝혔답니다. 그곳을 방문하십시오. 여행이 끝나면 다시 뵙도록 하죠.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n불꽃의 팔찌불타는 꽃"},
[9323] = {title = "동부 왕국의 거친 불꽃", objective = "저주받은 땅, 동부 역병지대, 동부 내륙지, 이글거리는 협곡에 있는 불꽃 축제 야영지를 방문한 다음 한여름 축제 불꽃지기에게 돌아오십시오.", description = "우리 불꽃 축제가 세계 각지로 퍼져 나가고 있습니다. 축제의 뜨거운 열기가 미치지 않은 곳이 없답니다. <class>|1이여;여;, 자고로 가장 뜨거운 불꽃은 새파랗게 타오르는 법이지요. 한번 찾아내 보십시오.\n\n검은바위 첨탑의 바로 북쪽에 하나 있을 것이고, 나머지는 동부 역병지대 깊숙한 곳의 오래된 마을 근처, 동부 내륙지 절벽으로 이어지는 길, 그리고 저주받은 땅의 어둠의 문으로 가는 길에 있을 것입니다.\n\n여행이 끝나면 제게 돌아오십시오.", progress = nil, completion = "다녀오셨군요. 조금은 지친 듯하고 옷도 더러워졌지만 얼굴만은 환하게 빛나고 있군요! 불꽃의 열기는 축제 기간 우리에게 큰 감동을 주어 하나로 묶어줍니다. 당신의 영혼도 불꽃의 힘으로 밝게 빛나고 있어요.\n\n참, 요즘에는 임무에 대한 보상으로 마법만 걸어주는 것을 인색하다고 하더군요. 자, 이걸 받으세요. 그럼 즐거운 축제 보내십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n불꽃축제 어깨보호대불타는 꽃"},
[9324] = {title = "오그리마의 불꽃 훔치기", objective = "한여름 축제 현자에게 오그리마의 불꽃을 돌려줘야 합니다.", description = "오그리마의 심장부에서 훔쳐낸 이 이 불꽃은 무한한 따뜻함을 줍니다. 당신에게는 이 자연의 힘이 낯설겠지만 한여름 축제 현자라면 이 불꽃에 대해 뭔가 알고 있을 겁니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n불타는 꽃"},
[9325] = {title = "썬더 블러프의 불꽃 훔치기", objective = "한여름 축제 현자에게 썬더 블러프의 불꽃을 가져가야 합니다.", description = "썬더 블러프의 주술사에게서 훔친 이 불꽃은 무한한 따뜻함을 줍니다. 당신에게는 이 자연의 힘이 낯설겠지만 한여름 축제 현자라면 이 불꽃에 대해 뭔가 알고 있을 겁니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n불타는 축제주불타는 꽃"},
[9326] = {title = "언더시티의 불꽃 훔치기", objective = "한여름 축제 현자에게 언더시티의 불꽃을 가져가야 합니다.", description = "언더시티 너머의 폐허에서 훔친 이 불꽃은 무한한 따뜻함을 줍니다. 당신에게는 이 자연의 힘이 낯설겠지만 한여름 축제 현자라면 이 불꽃에 대해 뭔가 알고 있을 겁니다.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n엘더베리 파이불에 구운 빵한여름 소시지불에 구운 스모크\n\n다음과 같은 것들 또한 받습니다:\n\n불타는 꽃"},
[9330] = {title = "스톰윈드의 불꽃 훔치기", objective = "한여름 축제 이야기꾼에게 스톰윈드의 불꽃을 가져가십시오.", description = "스톰윈드의 심장부에서 훔쳐낸 이 불꽃은 끝없는 따뜻함을 줍니다. 이 자연의 힘이 당신에게는 낯설겠지만 한여름 축제 이야기꾼이라면 이 불꽃에 대해 뭔가 알고 있을 것입니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n불타는 축제주불타는 꽃"},
[9331] = {title = "아이언포지의 불꽃 훔치기", objective = "한여름 축제 이야기꾼에게 아이언포지의 불꽃을 가지고 가십시오.", description = "아이언포지의 심장부에서 훔쳐낸 이 불꽃은 끝없는 따뜻함을 줍니다. 이 자연의 힘이 당신에게는 낯설겠지만 한여름 축제 이야기꾼이라면 이 불꽃에 대해 뭔가 알고 있을 것입니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n불타는 꽃"},
[9332] = {title = "다르나서스의 불꽃 훔치기", objective = "한여름 축제 이야기꾼에게 다르나서스의 불꽃을 돌려주십시오.", description = "텔드랏실의 해안에서 훔쳐낸 이 불꽃에서 나오는 온기로 가슴이 뜨거워집니다. 이 자연의 힘이 당신에게는 낯설겠지만 한여름 축제 이야기꾼이라면 이 불꽃에 대해 뭔가 알고 있을 겁니다.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n엘더베리 파이불에 구운 빵한여름 소시지불에 구운 스모크\n\n다음과 같은 것들 또한 받습니다:\n\n불타는 꽃"},
[9333] = {title = "은빛 여명회 장갑", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n언데드 정화의 장갑언데드 퇴치의 장갑언데드 퇴치의 손보호구언데드 퇴치의 건틀릿"},
