[9335] = {title = "신성한 숫돌", objective = "스컬지 침략자들에게서 죽음의 룬 8개를 모아 오면 신성한 숫돌을 1개 드리겠습니다. 리치 왕의 부하들에게 맞서 싸우는 데 큰 도움이 될 물건이지요.", description = nil, progress = "스컬지 침략자들에게서 죽음의 룬 8개를 모아 오면 신성한 숫돌을 1개 드리겠습니다. 리치 왕의 부하들에게 맞서 싸우는 데 큰 도움이 될 물건이지요.", completion = "고맙습니다! 여기 약속한 신성한 숫돌을 받으시지요. 잘 생각해서 사용하십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n신성한 숫돌"},
[9336] = {title = "일급 치유 물약", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n일급 치유 물약"},
[9337] = {title = "일급 마나 물약", objective = "다른 보급품은 물론이고 아주 유용한 일급 마나 물약도 많이 있소이다. 죽음의 룬 15개를 가져오면 이 중 하나를 드리도록 하겠소.", description = nil, progress = "다른 보급품은 물론이고 아주 유용한 일급 마나 물약도 많이 있소이다. 죽음의 룬 15개를 가져오면 이 중 하나를 드리도록 하겠소.", completion = "여기 있소이다. 부디 몸조심하시오. 우리 편의 수가 많지 않으므로 전장에서 희생자를 줄여야 하오.", rewards = "다음과 같은 것들을 받습니다:\n\n일급 마나 물약"},
[9338] = {title = "세나리온 의회에 대한 충성", objective = "물질적인 보상을 원치 않더라도 이 휘장은 우리의 상호 신뢰와 우정을 상징할 것이오.\n\n난 그대의 눈부신 활약이 계속될 것이라 믿어 의심치 않소. 자, 휘장을 가져오시오.", description = nil, progress = "물질적인 보상을 원치 않더라도 이 휘장은 우리의 상호 신뢰와 우정을 상징할 것이오.\n\n난 그대의 눈부신 활약이 계속될 것이라 믿어 의심치 않소. 자, 휘장을 가져오시오.", completion = "그대는 우리에게 영예를 안겨 주었소. 그대가 계속 도와준다면 우리는 모든 어려움을 극복할 수 있을 것이오이다.", rewards = nil},
[9341] = {title = "은빛 여명회 휘장", objective = "당신은 우리에게 큰 도움이 되었소. 원한다면 은빛 여명회의 휘장을 주도록 하지. 우리 동맹의 일원이 되어 주다니 뿌듯하오이다.", description = nil, progress = "당신은 우리에게 큰 도움이 되었소. 원한다면 은빛 여명회의 휘장을 주도록 하지. 우리 동맹의 일원이 되어 주다니 뿌듯하오이다.", completion = "이 휘장을 자랑스럽게 두르시오. 당신의 공로에 힘입어 다른 이들도 무기를 들고 스컬지에 대항하게 될 것이오.", rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 휘장"},
[9343] = {title = "은빛 여명회 휘장", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n은빛 여명회 휘장"},
[9353] = {title = "Redeem iCoke Gift Box Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\nSummer Gift Package"},
[9362] = {title = "크렐리안 장군", objective = "프리즘 껍질을 되찾아 아즈샤라 절벽 위 탑에 살고 있는 대마법사 실렘에게 돌려주어야 합니다.", description = "시간이 없네, <name>! 난 수정점 마법으로 강력한 마력의 원천을 밝혀냈네. 나는 이 탑을 떠날 수 없으니 자네가 가서 그 유물을 가지고 있는 사악한 놈을 해치워주게나.\n\n그 불쌍한 바보는 크렐리안 장군이라고 하는데 진말로의 신전에서 경비병의 보호를 받고 있다네. 놈을 잿더미로 만들어 버린 후에 놈이 그토록 탐내던 프리즘 껍질을 가져오게.", progress = "지체할 시간이 없네! 프리즘 껍질은 찾았나?", completion = "이 프리즘 껍질에는 이상한 기운이 감도는군. 프리즘 껍질을 찾아온 자네를 위한 보상으로는 껍질의 마력을 시험해 보는 것이 딱 맞겠군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[9364] = {title = "변이 마법", objective = "아즈샤라의 원한의꼬리일족을 변이시키고 몇 초 후 나타나는 변이된 복제생물 50마리를 해치워야 합니다. 모두 처치하고 나서 아즈샤라의 대마법사 실렘에게 가져다주십시오.", description = "지금까지 연구로 프리즘 껍질의 독특한 용도를 밝혀냈네.\n\n자, 이 껍질을 들고 아즈샤라의 원한의꼬리일족에게 변이 마법을 걸게. 조금 기다리면 프리즘 껍질안에 깃든 혼돈의 기운으로 인해 잠시 동안 작은 복제생물로 분열될 것일세. 그때 최대한 빨리 분열된 복제생물을 해치우게. 그러면 프리즘 껍질이 놈들의 정수를 빨아들일 거야.\n\n프리즘 껍질이 가득 차면 내게 가져오게.", progress = "마법은 충분히 모아왔는가?", completion = "정말 훌륭하네! 훌륭해!\n\n이제 이 마법을 변형하여 새로운 주문으로 만들 수 있겠어. 잘 보게나!", rewards = "다음과 같은 것들을 배웁니다:\n\n변이\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n변이: 돼지\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[9367] = {title = "불의 축제", objective = "스톰윈드, 아이언포지, 다르나서스에 있는 화톳불을 만져보고 대도시 안에 있는 한여름 축제 현자에게 돌아가십시오.", description = "한여름 축제가 다시 우리를 찾아왔어요!\n\n우리는 매년 관습에 따라 우리 수도의 화톳불을 지킬 불꽃지기를 선정한답니다. 아제로스 전역에서 불꽃이 타오르고 있지만 축제에 대한 예를 제대로 표하기 위해서는 우리의 불꽃이 가장 뜨겁고 가장 밝게 타올라야 한답니다.\n\n괜찮다면 당신에게 맡길 일이 하나 있습니다. 아직 얼라이언스 연합의 모든 수도에서 불꽃이 제대로 타고 있는지 소식을 듣지 못했어요. 직접 그곳으로 가서 불을 쬐고 충분히 뜨거운지 확인해 주시겠어요?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n불타는 꽃불타는 축제주"},
[9368] = {title = "한여름 불꽃축제", objective = "오그리마, 썬더 블러프, 언더시티에 화톳불을 만져보고 해당 대도시의 한여름 축제 현자에게 가십시오.", description = "한여름 불꽃축제가 돌아왔습니다!\n\n우리는 관습에 따라 매년 수도의 화톳불을 지킬 불꽃지기를 선정하지요. 아제로스 전역을 환하게 밝히고 있는 불꽃축제를 제대로 축하하려면 우리 불꽃이 가장 뜨겁고 밝게 타오르도록 정성을 다해야 해요.\n\n괜찮다면 당신에게 맡길 일이 하나 있습니다. 아직 얼라이언스 연합의 모든 수도에서 불꽃이 잘 타고 있는지 소식을 듣지 못했어요. 그곳으로 가서 직접 불을 쬐고 충분히 뜨거운지 확인해 주시겠어요?", progress = nil, completion = "훌륭해요! 당신 말대로 화톳불이 제대로 관리되고 있다면 올해는 성실한 불꽃지기를 뽑은 것 같군요. 조사해 주셔서 감사합니다. 여기, 작지만 제 작은 성의의 표시이니 받아 주세요.", rewards = "다음과 같은 것들을 받습니다:\n\n불타는 꽃불타는 축제주"},
[9386] = {title = "어둠을 밝히는 한 줄기 빛", objective = "검은바위 첨탑, 혈투의 전장, 스칼로맨스, 스트라솔름에 있는 화톳불을 찾아서 만져 본 후, 한여름 축제 불꽃지기에게 돌아가야 합니다.", description = "열정이 있으시군요. 만약 한번 더 탐험을 하시고 싶으시면 저는 기쁜 마음으로 당신에게 보답을 드릴 수 있답니다.\n\n스칼로맨스, 스트라솔름, 혈투의 전장, 검은바위 첨탑에서 타오르고 있는 화톳불을 찾아보시기 바랍니다. 당신이 돌아올 때까지 전 불꽃을 지키며 이 자리에서 기다리겠습니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n불타는 꽃"},
[9388] = {title = "칼림도어의 희미한 불꽃", objective = "잿빛 골짜기, 불모의 땅, 어둠의 해안, 돌발톱 산맥에 불꽃이 있는 장소를 방문한 다음 한여름 축제 불꽃지기를 찾아가 대화하십시오.", description = "지금 세계 곳곳에 많은 불꽃이 타오르고 있지만, 약한 불꽃은 녹색으로 타는 경향이 있지. 누군가 돌봐주지 않으면 오래가지 않아 꺼질 거야. 우리 불꽃지기를 위해 그 에메랄드빛 불꽃들이 칼림도어에서 계속 타오르는지 좀 봐주게.\n\n불모의 땅 톱니항 부근과 어둠의 해안에 있는 지배자의 무덤 근처, 잿빛 골짜기 숲속 은빛날개 전초기지 근처의 다리 옆, 그리고 돌발톱 산맥의 대로를 따라 있는 칼바람 바위산 길목에서 찾을 수 있을 걸세.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n엘더베리 파이불에 구운 빵한여름 소시지불에 구운 스모크\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[9389] = {title = "동부 왕국의 가물거리는 불꽃", objective = "힐스브래드 구릉지와 은빛소나무 숲, 서부 몰락지대와 저습지 내에 있는 화톳불을 찾은 후, 한여름 축제 불꽃지기와 대화해야 합니다.", description = "한여름 불꽃축제는 무수한 화톳불로 대지를 밝히는 것이 전통이지. 특유의 빛깔을 지니고 불꽃을 유지하기가 가장 어려운 만큼 축제를 위해서는 녹색 불꽃이 한층 좋다는 언쟁들이 좀 있다네.\n\n그래서 말인데 우리 축제의 불꽃지기를 위해 동부 왕국에 불꽃이 아직 타고 있는지 확인해 주게나. 그들은 저습지의 던 모드르 근처와 은빛소나무 숲 안에 장작나무 마을, 서부 몰락지대에 있는 등대자리가 내려다보이는 절벽 근처와 힐스브래드 구릉지에 폐허가 된 탑 근처에 자리 잡고 있네.", progress = nil, completion = "그래, 자네가 돌아온 것을 보니 전 대륙에 타오르는 에메랄드 불꽃을 본 모양이군. 어떻게 생각하나? 진정 희귀하고 멋진 장관이지 않던가? 그러나 실체가 있는 보상이 좀 더 감사의 마음을 전하는 데 더 좋다는 걸 알고 있다네... 그래서 말인데, 자네가 곤경에 처했을 때 이걸 사용하게나.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n엘더베리 파이불에 구운 빵한여름 소시지불에 구운 스모크\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[9415] = {title = "치안대장 블루월에게 보고", objective = "하이브조라 근처의 얼라이언스 야영지에 있는 치안대장 블루월과 대화해야 합니다.", description = "블루월 치안대장의 신병입니까? 물론 그렇겠죠.\n\n뭘 기다리죠? 훌륭한 병사들이 사막에서 죽어 가고 있습니다. 그들과 함께 싸울 생각을 하니 흥분되지 않습니까?\n\n가는 도중에 탈수증에 걸리지 않도록 조심하고 이제 치안대장에게로 가보십시오.", progress = nil, completion = "얼라이언스 연합에서는 능력 있는 영웅들의 지원이 최대한 많이 필요합니다. 호드는 대륙의 북부 지역에서 꾸준하게 지원 병력이 도착하고 있기 때문에 그들을 따라잡는 게 우선입니다.\n\n자, 상황을 설명해 드리도록 하죠.", rewards = nil},
[9416] = {title = "사령관 키리카에게 보고", objective = "하이브레갈 근처의 호드 야영지에 있는 사령관 키리카와 대화해야 합니다.", description = "사령관 키리카의 신병 중 하나가 틀림없군. 이맘때쯤 도착할 것이라고 생각했소. 사막에서는 시체가 금방 사라지지.\n\n드워프 지원군은 나날이 불어가는 상황에서 실리더스 자원 쟁탈전의 기반을 잃어버려서는 안 되오.\n\n사령관을 만나 지시사항을 알려달라고 하시오. 당신을 만나는 것으로 내 임무는 끝났소. 훈련은 딴 데 가서 받으시오.", progress = nil, completion = "여기까지 오다니 다행이군. 하지만, 잡담하느라 낭비할 시간이 없네. 지시사항을 줄 테니 그 이후엔 전투에 참여해야 하네.\n\n자, 잘 듣게나.", rewards = nil},
[9419] = {title = "사막 탐색", objective = "실리시스트를 찾아서 실리시스트 추출기로 가져간 후, 하이브조라 근처 얼라이언스 주둔지에 있는 치안대장 블루월과 대화해야 합니다.", description = "최근 호드 때문에 실리더스 사막의 자원이 고갈되고 있다는 사실을 발견했지만 크게 신경 쓰지는 않았습니다. 이 무더운 사막에 대규모 병력을 배치하는 것은 옳지 않다고 생각했거든요.\n\n하지만, 자원의 중요성이 강조되면서 우리는 호드를 따라잡기 위해 애쓰고 있습니다.\n\n저를 돕겠다면 사막으로 가서 실리시스트를 찾아오세요.", progress = "사막에서는 몸조심하십시오. 하지만, 일 처리는 빨리 하셔야 합니다. 시간을 낭비해서는 안 됩니다.", completion = "성스러운 빛이여, 감사합니다. 성공했군요!\n\n이 일을 좀 더 일찍 시작했더라면 문제가 이렇게 심각하게 번지지는 않았을 텐데... 귀한 사막의 자원이 호드의 손에 넘어가도록 보고만 있어서는 안 됩니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n일급 치유 물약일급 마나 물약\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[9422] = {title = "사막 탐색", objective = "실리시스트를 찾아서 실리시스트 추출기로 운반한 후, 하이브레갈 근처의 호드 야영지에 있는 사령관 키리카와 대화해야 합니다.", description = "우린 요즘 실리더스의 사막에서 수정 자원을 추출하고 있다네. 이 지역을 서식지로 삼아 버린 곤충들이나 숨막힐 듯한 더위와 먼지, 모래만 해도 충분히 위험한 상황이었네.\n\n그런데 이젠 얼라이언스 녀석들마저 우리가 이곳 실리더스에서 발견한 것들을 훔쳐가고 있는 것 같군그래. 이제 이곳의 천연자원은 누가 먼저 차지하고 지켜내느냐의 문제가 되었네. 그야말로 전쟁이지.\n\n가능한 모든 도움이 필요하니 자네가 나서줬으면 좋겠네.", progress = nil, completion = "정말 잘했네. 이 자원은 우리 보급창에 비축해 둘걸세. 모든 천연자원은 우리의 이익이자 우리 적의 손실이라는 걸 잊지 말게나.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n일급 치유 물약일급 마나 물약\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[9556] = {title = "승리의 길로...", objective = "자신의 진영이 동부 역병지대에서 승리하게 되면 스톰윈드나 언더시티 마법사 지구 내에 있는 로데론 마법사에게 스트라솔름 성수를 가져가야 합니다.", description = "자네가 이곳의 경비탑들 사이에서 고되고 오랜 싸움을 벌이고 있다는 것은 내 잘 알고 있네. 이 땅을 지켜내기 위한 자네의 노력에 보상이 될만한 무언가를 주고자 하네만, 그보다 앞서 이곳에서 펼쳐지고 있는 비극이 얼마나 처참한지를 이해하고 있는가를 증명해야만 하네.\n\n스트라솔름의 황폐해진 거리로 가서 성수 한 병을 찾게나. 자네가 얼라이언스의 일원이라면 스톰윈드로, 호드의 일원이라면 언더시티로 그 성수를 가져가게... 자네가 몸 담은 진영이 역병지대 내 전투에서 승리하면 자네를 돕고자 파견된 내 동료를 만날 수 있을 걸세.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[9664] = {title = "새로운 전초기지 건설", objective = "동부 역병지대에 있는 산마루 경비탑, 동부방벽 경비탑, 북부관문 경비탑, 그리고 역병의 숲 경비탑을 점령한 다음 희망의 빛 예배당에 있는 사절 화이트비어드에게 돌아가야 합니다.", description = "역병지대에 오신 것을 환영합니다. 알다시피 포세이큰 패거리가 이곳의 서쪽 지역을 점령하고 있습니다. 우리의 최전선인 셈이지요. 얼라이언스 지휘관들은 이곳 동쪽에 요새를 새로 구축하여 적을 옭아매기로 결정했습니다.\n\n로데론이 파괴된 이후로 주인을 잃은 탑들을 우리 손에 넣어서 고쳐야 합니다. 이 위험한 땅을 지키고 있는 우리를 제발 도와주세요.", progress = "그 탑들을 우리 손에 넣으면 머지않아 포세이큰 녀석들을 포위할 수 있습니다. 그러면 녀석들을 쓸어버리는 것도 시간문제일 뿐이죠.", completion = "잘하셨습니다. 저희는 앞으로 공격에 대비해 탑들을 잘 지키겠습니다. 그런데 이 지역을 방어할 지원군이 도착하기 전까지 당신의 도움이 좀 필요할 것 같군요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[9665] = {title = "방어선 강화", objective = "동부 역병지대에 있는 산마루 경비탑, 동부방벽 경비탑, 북부관문 경비탑, 그리고 역병의 숲 경비탑을 점령한 다음 희망의 빛 예배당에 있는 사절 고르목에게 돌아가십시오.", description = "포세이큰 비밀 요원이 이곳 동부 역병지대에 버려진 탑들을 점령해 새로운 요새를 구축하려는 얼라이언스의 계획을 밝혀냈소.\n\n우리 영토 동쪽에 그렇게 심각한 위협이 불거지도록 놔둘 수는 없소. 한시바삐 얼라이언스의 침입을 막아야 하오. 현재 전략은 얼라이언스가 점령하고 있는 탑을 공격해서 적들을 몰아낸 다음 앞으로 공격에 대비하여 방어선을 굳건히 하는 거요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[65593] = {title = "연인의 유품", objective = "저주의 사원에 있는 카렌딘 할가르에게 아벨리나 릴리의 유품과 이삭 피어슨의 유품을 가져가야 합니다.", description = "인큐버스는 연인의 유품에 이끌릴 거예요. 가슴이 저릴 만큼 절절한 사랑이라면 저항할 수 없는 유혹적인 미끼가 되겠죠.\n\n제 수정이 그에 아주 걸맞은 두 사람을 찾아냈어요.\n\n은빛소나무 숲에 아벨리나 릴리라는 사람이 있는데, 앰버밀의 타락한 마법사들을 위해 재단 일을 하고 있어요. 그리고 불모의 땅에서는 이삭 피어슨이란 사람이 톱니항의 바닷가 마을에서 성공을 위해 힘쓰고 있죠.\n\n둘은 세상의 끝과 끝에서 열심히 살고 있지만 마음은 그 누구보다 서로를 그리워하고 있어요. 두 마음을 카렌딘에게 가져다 주세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[65597] = {title = "결속", objective = "연인의 심장을 사용하여 인큐버스를 소환하여 제압한 다음, 언더시티에 있는 마법 지구에 있는 카렌딘 할가르에게 연인의 심장을 가져가야 합니다.", description = "드디어 때가 왔다. 아래 있는 마법진으로 유품을 가져가, 가운데에 잘 두고 인큐버스를 불러내는 거야.\n\n네가 꾀어낸 게 함정이란 걸 알면 악마가 썩 좋아하진 않을 테지. 놈의 속임수에 빠지면 안 돼, <name>. 완전히 제압해야 한다고.\n\n그래야만 악마를 네 의지에 결속하는 주문을 알려줄 수 있으니까.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n인큐버스 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n인큐버스 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n작은 영혼의 가방"},
[65601] = {title = "사랑은 아프다", objective = "오그리마에 있는 마가르와 대화하십시오.", description = "사람들은 남자 세이야드를 인큐버스라 부르지. 깊은 악으로 가득 차 있고 기이한 정신을 소유한 피조물이네.\n\n유혹적인 물건을 미끼로 사용한다면 우리 세계로 넘어오지 않고는 못 배길 거야. 커다란 사랑과 헌신을 나타내는 그런 물건 말일세.\n\n<name>|1이여;여;, 나 같은 눈 먼 자를 믿고 따를 수 있다면 들어보게. 어둠의 틈 동쪽, 오그리마의 큰길에 마가르란 자가 살고 있네. 그의 짝 크릴지가 돌아오기만을 간절히 바라고 있지.\n\n그를 찾아보게. 귀중한 무언가를 찾아달라고 부탁할 걸세. 그 물건을 간룰에게 가져가는 게 이번 일의 핵심이라네.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[65602] = {title = "사랑이란 무얼까?", objective = "목재 조각상을 찾아 스톰윈드의 마법사 지구에 있는 대흑마법사 게이킨에게 가져가야 합니다.", description = "인큐버스를 유혹하려면 강력한 재료가 필요할 거요. 크나큰 헌신과 사랑을 나타내는 그런 물건 말이오.\n\n내 점술로 당신의 의식에 걸맞을 작은 조각상의 위치를 알아냈다오.\n\n수천 년 전, 어느 젊은 연인들의 소유였던 조각상이지. 본래 주인은 더는 이 세상에 없지만 유품은 오늘날까지도 남아 있다오.\n\n북쪽으로 길을 따라 잿빛 골짜기로 가시오. 그런 뒤 서쪽으로 향해 마에스트라 주둔지를 지나면 나무들 사이에 자리한 집 하나가 보일 거요. 거기서 원하는 물건을 찾을 수 있을 것이오.", progress = "돌아왔군! 분명 성공했겠지?", completion = "&lt;목재 조각상을 손에 들고 뒤집어 보는 게이킨&gt;\n\n이 유물에 감정을 자극하는 힘이 흐르고 있군그래. 세월이 흘렀음에도 약해지지 않았어. 인큐버스는 꿀에 달려드는 벌처럼 이 물건에 이끌릴 거요.\n\n역시 타카르는 실망시키는 법이 없다니까.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[65603] = {title = "결속", objective = "목재 조각상을 사용하여 인큐버스를 소환해 제압한 후, 어둠의 희생양 선술집에 있는 대흑마법사 게이킨에게 목재 조각상을 가져가야 합니다.", description = "때가 되었군. 조각상을 가지고 아래 묘실로 내려가게나. 소환 마법진이 준비되어 있으니 그 가운데에 조각상을 놓으면 된다네.\n\n그러면 관문이 열리고 인큐버스가 우리 세계로 넘어올 게야.\n\n절대 세이야드를 얕잡아 봐서는 안되네. 자네가 술책을 부린 걸 알아챈 순간 주저하지 않고 공격을 퍼부을 테니. 그간 배운 모든 기술을 동원해야 놈을 물리칠 수 있을 걸세.\n\n성공하면 내게 돌아오게. 자네 의지에 악마를 결속시켜 주겠네. 만약 실패하면... 영혼을 빼앗기고 말 게야.", progress = "인큐버스는 갖은 속임수를 써 자네의 경계심을 풀려 할 걸세. 악마는 필멸자의 마음을 쉽사리 흔들 수 있는 존재들이니.\n\n놈들이 권하는 건 모두 거짓이라는 사실을 기억하게나. 악마들에게 자네는 한낱 먹잇감에 지나지 않다네.", completion = "나쁘지 않군, &lt;name&gt;. 마귀를 이겼으니 자네의 그 의지 역시 절대 꺾이지 않을 걸세.\n\n스스로가 세이야드를 결속할 만큼 강하다 여긴 &lt;class&gt;들이 외려 악마의 다음 끼니가 된 경우가 수도 없이 많았다네. 자네는 그렇게 멍청하지 않아 다행이구먼.\n\n새로 결속한 인큐버스를 불러내는 주문을 가르쳐줄 테니 잘 보게나.", rewards = "다음과 같은 것들을 배웁니다:\n\n인큐버스 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n인큐버스 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n작은 영혼의 가방"},
[65604] = {title = "결속", objective = "너덜너덜한 목도리를 사용해 인큐버스를 소환하여 처치한 다음 오그리마에 있는 간룰 블러드아이에게 너덜너덜한 목도리를 가지고 돌아가십시오.", description = "그래... 보인다. 이 실에 감정이 남아 있네. 한 땀 한 땀에 사랑이 담겨 있군. 인큐버스라면 저항할 수 없을 걸세.\n\n이 목도리를 네루의 막사에 있는 소환 마법진으로 가져가게. 사악한 인큐버스를 소환한 다음 처치해야 하네. 놈이 순순히 제압당할 거란 기대는 말게. 마법을 준비하고 다가올 전투에 대비하게나. 악마를 과소평가했던 흑마법사들이 수도 없이 목숨을 잃었다네.\n\n인큐버스를 물리친 다음 목도리를 내게 다시 가져오게. 그러면 내가 마가르에게 자네가 발견한 걸 알려주도록 하지.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n인큐버스 소환\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n인큐버스 소환 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n작은 영혼의 가방"},
[65610] = {title = "그대가 여기 있었으면", objective = "잿빛 골짜기에 있는 유성 호수를 조사한 후 오그리마에 있는 간룰 블러드아이에게 보고해야 합니다.", description = "나는 잿빛 골짜기에서 달빛매듭 방어구를 만들며 지내다 크릴지를 만났네. 그는 그곳에 주둔하며 시민들을 위험으로부터 지켜 주었지. 그러다 어느 날 사라져 버렸네...\n\n사람들은 그가 탈영했다 생각하고 수색도 그만두었네. 하지만 난 그리 생각하지 않아.\n\n유성 호수가 그 공격적인 늪지 짐승들에게 점령당하기 전에, 우린 그곳에서 종종 만나곤 했네.\n\n내가 원래 부탁은 잘 안하지만... 자네가 잿빛 골짜기로 가서 그의 흔적을 찾아봐 준다면 정말 고맙겠네.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[77568] = {title = "사냥꾼의 힘", objective = "그늘 거미굴에서 흉측한 기시이스를 처치하고 잃어버린 룬을 회수해야 합니다. 룬을 배운 다음 그늘 협곡에 있는 아얀나 에버스트라이드에게 보고해야 합니다.", description = "사냥꾼은 자신의 야수뿐만 아니라 모든 생명체와의 유대, 존중에서 힘을 얻어요. 앞으로 그대는 얼라이언스의 이름으로 수많은 짐승을 사냥하고 생명을 거두게 되겠죠. 하지만 전투에서도 적을 존중해야 해요.\n\n제 전 제자는 신비한 룬을 사용해 능력을 강화했지만, 어리석게도 북쪽 동굴에 사는 거미 중 가장 큰 녀석을 연습 상대로 삼고 말았어요. 흉측한 기시이스라는 존재죠. 제자의 불손함은 결국 죽음이란 화를 자초했어요.\n\n기시이스를 처치해 주세요. 그 힘을 얕봐선 안 될 거예요.", progress = "기시이스를 처치한 다음, 룬을 회수해 마법을 습득하세요.", completion = "훌륭해요, &lt;name&gt; 님. 장비에 룬을 부여하면 강력한 능력을 얻죠.\n\n아제로스에서는 그러한 룬이 수없이 많이 존재해요. 한번 찾아보세요. 용사님의 여정에 든든한 힘이 되어줄 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n갈라진 가죽 장갑"},
[77571] = {title = "칼도레이의 유물", objective = "그늘 협곡에 있는 그렐킨에게서 룬을 회수해야 합니다. 룬의 인도를 따라 새로운 능력을 배운 다음, 마르단트 스트롱오크에게 보고해야 합니다.", description = "칼도레이는 고대 종족으로, 아제로스 전역에서 우리의 잃어버린 유물을 찾아볼 수 있습니다. 이 유물을 매개체로 삼아 영혼에게 꿈과의 유대를 강화하는 방법을 배울 수 있지요.\n\n그렐킨이 그런 유물 하나를 훔쳐 갔습니다. 놈들을 처치하고 유물을 회수한 다음, 유물의 인도를 따라 새로운 전투 기술을 습득하십시오. 일을 마치는 대로 돌아오시면 됩니다.", progress = nil, completion = "훌륭합니다, &lt;name&gt; 님. 습득한 룬을 장비에 부여하면 강력한 능력을 얻습니다.\n\n여행 중에 비슷한 유물을 더 찾아보십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n갈라진 가죽 조끼"},
[77574] = {title = "엘룬에 관한 명상", objective = "달샘에서 무릎을 꿇고 엘룬에 관한 명상을 한 다음, 기억을 사용하여 새로운 능력을 배워야 합니다. 이후 그늘 협곡에 있는 샨다에게 가야 합니다.", description = "얼라이언스에 가입하면서 우리 종족은 강해졌지만, 근본은 칼도레이라는 사실을 잊지 말아야 해요. 엘룬과의 연결은 우리 존재의 핵심이죠.\n\n<name> 님, 마음을 비우고 제 목소리에 집중하세요. 우리 종족의 오래된 기억을 들려드릴게요. 북쪽의 달샘으로 가 성수 속에서 무릎을 꿇고 엘룬의 신비에 관해 명상하세요. 사색에 집중하면 기억을 이해하고 새로운 기술을 배울 수 있을 거예요. 일을 마치는 대로 돌아오세요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n누더기 헝겊 장갑"},
[77582] = {title = "육체의 시험", objective = "프랑의 뒤에 있는 절벽에서 숨겨진 보관함을 찾아야 합니다. 안에 담긴 룬을 배운 다음 시험의 골짜기에 있는 프랑에게 보고해야 합니다.", description = "자고로 호드의 전사라면 무엇보다도 튼튼한 육체를 가져야 하네. 앞으로 자네는 체력과 지구력이 시험에 들 때가 수없이 많을 걸세.\n\n그래서 내 뒤로 보이는 절벽 어딘가에 보관함을 숨겨두었네. 마을 중앙의 불꽃에 서 있으면 보이지. 보관함이 있는 장소까지 가기 쉽지 않을 걸세. 그 보관함에는 강대한 힘이 깃든 룬이 있네.\n\n그 룬을 확보하는 게 시험일세. 룬의 비밀을 알아낸 다음 돌아오게나.", progress = nil, completion = "훌륭하군, &lt;name&gt;. 장비에 룬을 부여하면 강력한 능력을 얻지.\n\n아제로스에서는 그러한 룬이 수없이 많이 존재하네. 한번 찾아보게나. 자네의 여정에 든든한 힘이 되어줄 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n빛바랜 사슬 장갑"},
[77586] = {title = "훔쳐낸 힘", objective = "불타는 칼날단 소굴 내부에서 도둑맞은 룬을 회수해야 합니다. 이후 룬의 힘을 배운 다음, 동굴 막사에 있는 나르톡에게 보고해야 합니다.", description = "나는 새로운 종류의 마법을 연구하고 있네. 지옥 마력을 집중해 막강한 주문의 원동력으로 삼을 수 있게 해주는 룬이지. 이 힘을 자네와 나누고 싶지만, 시건방진 불타는 칼날단 전령 놈들이 훔쳐 갔어. \n\n북쪽에 있는 놈들 소굴로 가서 숨겨놓은 은닉처에 내 룬은 없는지 찾아봐 주게. 내 경험상 전령은 약탈품을 찾기 어려운 곳에 숨기는 경향이 있어.\n\n룬을 찾으면 그 마법을 배워 돌아오게. 내 실험을 실전에 사용해 보고 싶거든요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n누더기 헝겊 장갑"},
[77587] = {title = "힘의 우상", objective = "시험의 골짜기에서 전갈을 처치하여 도둑맞은 우상을 찾아야 합니다. 이후 우상의 힘을 배운 다음 시크리크에게 가야 합니다.", description = "주술사는 유서 깊은 직업이라네, <name>. 그렇기에 정령의 마력이 가득한 유물을 아제로스 각지에서 수없이 찾아볼 수 있지. 내 얼마 전에 상당한 힘이 담긴 우상을 찾았네만, 성가신 전갈 놈들이 훔쳐 갔네.\n\n지금쯤 한 녀석이 반짝이는 골동품 같은 걸로 착각하고는 제 둥지 장식으로 쓰려고 하고 있겠지.\n\n우상을 찾거든 그 힘을 손에 넣고 돌아오게나.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n갈라진 가죽 조끼"},
[77616] = {title = "잃어버린 룬", objective = "메아리 광산에서 잃어버린 룬을 찾아야 합니다. 이후 룬을 사용하여 새로운 능력을 배운 다음, 노스샤이어에 있는 레인 비셰어에게 보고해야 합니다.", description = "얼라이언스의 전사들은 당신에게 많은 걸 가르쳐줄 수 있소. 하지만 그것과 별개로 새로운 기술을 찾아야 하오.\n\n얼마 전에 어느 젊은 전사가 메아리 광산으로 향했소. 장비에 신비한 룬을 각인해 전투력을 높이는 실험을 하고 있었지.\n\n코볼트가 광산을 장악했을 때 머릿수에 밀려서 당했을 거요. 지금은 코볼트가 그 룬을 손에 넣었을 테니, 찾아서 당신의 것으로 취하시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n빛바랜 사슬 장갑"},
[77618] = {title = "도둑만 세 번", objective = "데피아즈단 야영지에서 잃어버린 룬을 회수해야 합니다. 이후 룬을 사용하여 새로운 능력을 배운 다음, 노스샤이어에 있는 요리크 케리던에게 가야 합니다.", description = "<name>, 인정하기 창피하지만... 실은 데피아즈단 자식들에게 기습을 당했소. 내가, 어... 수도원 기록 보관소에서 '빌린' 마법의 룬을 훔쳐 갔다오. 그 룬으로 단숨에 이익을 볼 생각이었는데, 사용하는 방법을 알아내지 못했지.\n\n동부로 가서 다시 찾아와 줄 수 있겠소? 룬을 찾거든 당신이 사용하시오. 공부하고 그러는 거 좋아하는 부류 같거든. 놀리려고 한 말은 아니고.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n갈라진 가죽 장갑"},
[77619] = {title = "빛에 관한 명상", objective = "메아리 광산에서 코볼트를 처치하여 기억을 받아야 합니다. 이후 노스샤이어 수도원에서 무릎을 꿇고 빛에 대한 명상을 한 다음, 기억을 사용해 새로운 능력을 배워야 합니다. 그런 다음 여사제 아네타에게 가야 합니다.", description = "빛께서 당신의 미래를 보여주셨어요. 메아리 광산에서 코볼트와 싸우는 모습이었죠. 그 광산에서 빛은 당신에게 과거에 대한 기억을 내려주었답니다. 기억을 찾거든 수도원으로 돌아와 이 전당에서 무릎을 꿇고 빛의 신비에 관해 명상해 보세요.\n\n사색에 집중하면 기억을 이해하고 새로운 기술을 배울 수 있을 거예요. 일을 마치는 대로 돌아오세요.", progress = nil, completion = "빛이 보여주는 환영이 많아질수록 거룩한 장소에서 명상을 하여 생각을 정리하고, 불가사의를 숙고해야 해요.\n\n그리고 용사님의 길이 칼림도어의 엘프 동료와 교감을 나누는 방향으로 나 있는 것을 봤어요. 나이트 엘프 특유의 달 숭배 의식을 탐구하다 보면 언젠가 그 사람들을 빛의 품으로 인도하는 데 도움이 될 거예요.", rewards = "다음과 같은 것들을 받습니다:\n\n누더기 헝겊 장갑"},
[77620] = {title = "주문 연구", objective = "데피아즈단 도적에게서 연구 기록을 회수한 후, 연구 기록을 사용하여 새로운 주문을 배워야 합니다. 그런 다음 노스샤이어에 있는 켈덴 브레멘에게 가야 합니다.", description = "<name> 님, 제가 힘닿는 데까지 가르쳐 드리긴 하겠지만, 결국 경이로운 힘에 닿으려면 스스로의 힘으로 연구를 진행해야 합니다. 아제로스 최고의 대마법사들이 남긴 기록을 연구해 보십시오. 훌륭한 출발점이 될 겁니다. 수도원 기록 보관소에는 본래 무수히 많은 비전 연구 기록이 보관되어 있었지만, 데피아즈단 요원들이 훔쳐 갔습니다.\n\n동쪽의 도적에게서 주문 기록을 되찾은 다음, 지침서를 참고해 해석하십시오. 연구를 마치는 대로 돌아오시길.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적누더기 헝겊 장갑"},
[77621] = {title = "훔쳐낸 힘", objective = "동쪽에 있는 데피아즈단 야영지에서 룬을 회수해야 합니다. 이후 룬을 사용하여 새로운 능력을 배운 다음, 노스샤이어에 있는 드루실라 라 살르에게 가야 합니다.", description = "전 새로운 종류의 마법을 연구하고 있어요. 지옥 마력을 집중해 막강한 주문의 원동력으로 삼을 수 있게 해주는 룬이죠. 이 힘을 당신과 나누고 싶지만, 간밤에 연구 기록을 도둑맞았어요. '데피아즈단'을 자청하는 도적들 소행이겠죠.\n\n동쪽으로 가서 놈들이 숨겨놓은 은닉처에 제 룬은 없는지 찾아봐 주세요. 룬을 찾으면 그 마법을 배워 돌아오시고요. 제 실험을 실전에 사용해 보고 싶거든요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n누더기 헝겊 장갑"},
[77642] = {title = "로아의 지혜", objective = "센진 마을에 있는 로아 제단에서 무릎을 꿇어야 합니다. 로아의 영혼과 교감한 후 기억을 사용하여 새로운 능력을 배워야 합니다. 이후 시험의 골짜기에 있는 켄자이에게 가야 합니다.", description = "<name> 님, 호드에 가입하면서 우리 종족은 안전한 보금자리를 얻었지만, 근본은 우리를 굽어살피는 로아라는 걸 잊지 말아야 합니다.\n\n이제 마음을 비우십시오. 오래된 기억을 하나 나누어 드리겠습니다. 센진 마을에 있는 로아의 제단으로 가 무릎을 꿇고, 위대한 로아의 영혼과 교감하십시오. 로아의 지혜를 받고 나면 제가 드린 기억을 이해하고 새로운 힘을 발견할 수 있을 겁니다.\n\n일을 마치는 대로 돌아오시길.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n누더기 헝겊 장갑"},
[77652] = {title = "힘의 우상", objective = "칼날가시 협곡에 있는 뾰족털일족 주술사에게서 잃어버린 우상을 회수해야 합니다. 이후 우상에 담긴 힘을 배운 다음, 나라체 야영지에 있는 하루트 썬더혼에게 보고해야 합니다.", description = "주술사는 유서 깊은 직업입니다, <name> 님. 그렇기에 정령의 마력이 가득한 유물을 아제로스 각지에서 수없이 찾아볼 수 있지요. 제가 얼마 전에 상당한 힘이 담긴 우상을 찾았는데, 성가신 가시멧돼지 놈들이 훔쳐 가고 말았습니다.\n\n동쪽에 있는 놈들의 영토로 가서 찾아봐 주십시오. 지금쯤 가시멧돼지 주술사가 우상의 비밀을 이해하려고 애쓰고 있을 겁니다.\n\n우상을 찾거든 그 힘을 손에 넣고 돌아오십시오.", progress = nil, completion = "훌륭합니다, &lt;name&gt; 님. 장비에 룬을 부여하면 강력한 능력을 얻습니다.\n\n아제로스에서는 그러한 룬이 수없이 많이 존재합니다. 한번 찾아보십시오. 용사님의 여정에 든든한 힘이 되어줄 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n갈라진 가죽 조끼"},
[77655] = {title = "잃어버린 룬", objective = "눈마루 골짜기에 있는 서리갈기 트롤에게서 잃어버린 룬을 찾아야 합니다. 이후 룬을 사용하여 새로운 능력을 배운 다음, 앤빌마에 있는 스란 코르만에게 보고해야 합니다.", description = "<name> 님, 얼라이언스의 전사들은 용사님에게 많은 걸 가르쳐 드릴 수 있어요. 하지만 그것과 별개로 새로운 기술을 찾아야 합니다.\n\n이곳에서 남쪽으로 가면 서리갈기 트롤이 가득한 동굴이 나와요. 얼마 전에 어느 촉망받는 전사가 찾아갔는데, 다신 돌아오지 않았죠. 장비에 신비한 룬을 각인해 전투력을 높이는 실험을 하고 있었어요.\n\n지금은 트롤이 그 룬을 손에 넣었을 테니, 찾아서 당신의 것으로 취하세요. 일을 끝마치는 대로 돌아와 주세요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n빛바랜 사슬 장갑"},
[77660] = {title = "동굴 추적", objective = "눈마루 골짜기에 있는 서리갈기 트롤에게서 도둑맞은 룬을 회수해야 합니다. 이후 룬을 사용하여 새로운 능력을 배운 다음, 앤빌마에 있는 토르가스 그림슨에게 보고해야 합니다.", description = "사냥꾼은 강인한 족속입니다, <name> 님. 드워프 사이에서도 더한 수준이지요. 우린 아제로스의 미개척지를 누비며 온갖 위험하고 이색적인 사냥감을 쫓습니다. 앞으로 당신은 적진에서 홀로 움직이며 생존을 도모할 때가 많을 겁니다.\n\n서리갈기 트롤이 강력한 힘이 깃든 룬을 훔쳐 갔습니다. 남쪽에 있는 자기들 동굴에 숨겨뒀을 가능성이 큽니다. 룬을 회수한 다음, 그걸 사용해 새로운 전투 기술을 습득하십시오. 일을 마치는 대로 돌아오시길.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n갈라진 가죽 장갑"},
[77661] = {title = "빛에 관한 명상", objective = "앤빌마 근처에 있는 트로그 야영지 보관함에서 과거의 기억을 찾아야 합니다. 그런 다음 앤빌마에 있는 빛의 제단에서 무릎을 꿇고 빛에 관하여 명상한 다음, 기억을 사용해 새로운 능력을 배워야 합니다. 이후 브란스토크 칼더와 대화해야 합니다.", description = "빛께서 <name> 당신의 미래를 보여주셨습니다. 남서쪽에서 트로그와 싸우는 모습이었습니다. 당신은 보관함에서 과거에 대한 기억을 찾게 될 겁니다. 기억을 찾거든 이곳으로 돌아와 빛의 제단에서 무릎을 꿇고 빛의 신비에 관해 명상해 보십시오.\n\n사색에 집중하면 기억을 이해하고 새로운 기술을 배울 수 있을 것입니다. 일을 마치는 대로 돌아오시길.", progress = nil, completion = "빛이 보여주는 환영이 많아질수록 거룩한 장소에서 명상을 하여 생각을 정리하고, 불가사의를 숙고해야 합니다.\n\n그리고 용사님의 길이 칼림도어의 엘프 동료와 교감을 나누는 방향으로 나 있는 것을 보았습니다. 나이트 엘프 특유의 달 숭배 의식을 탐구하다 보면 언젠가 그 사람들을 빛의 품으로 인도하는 데 도움이 될 것입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n누더기 헝겊 장갑"},
[77666] = {title = "훔쳐낸 힘", objective = "앤빌마 남서쪽에 있는 트로그 무리로부터 룬을 회수해야 합니다. 이후 룬을 사용하여 새로운 능력을 배운 다음, 앤빌마에 있는 알라마 그림에게 가야 합니다.", description = "전 새로운 종류의 마법을 연구하고 있어요. 지옥 마력을 집중해 막강한 주문의 원동력으로 삼을 수 있게 해주는 룬이죠. 이 힘을 당신과 나누고 싶지만, 성가신 트로그 녀석들이 훔쳐 갔어요.\n\n남서쪽에 바위턱 벌레들 야영지가 있어요. 가서 놈들이 숨겨놓은 은닉처에 제 룬은 없는지 찾아봐 주세요. 아마 보관함 같은 데 넣어놨을 거예요. 룬을 찾으면 그 마법을 배워 돌아오시고요. 제 실험을 실전에 사용해 보고 싶거든요.", progress = nil, completion = "새로운 마법을 훌륭히 잘 받아들였군요, &lt;name&gt; 님. 이런 룬을 좀 더 찾아서 장비에 각인하면 적에게 맞설 새로운 능력을 얻을 수 있을 거예요.\n\n언젠가 용사님의 능력이 절 뛰어넘는 날이 올지도 모르죠.", rewards = "다음과 같은 것들을 받습니다:\n\n누더기 헝겊 장갑"},
[77667] = {title = "주문 연구", objective = "앤빌마 남서쪽 트로그 야영지에서 도둑맞은 주문 기록을 찾아내야 합니다. 이후 기록을 사용하여 새로운 능력을 배운 다음, 앤빌마에 있는 마릭 너리빗에게 가야 합니다.", description = "마법사는 비전 마법을 연구하여 경이로운 힘을 손에 넣을 수 있어요. 아제로스 최고의 대마법사들이 남긴 기록을 연구해 보세요. 훌륭한 출발점이 될 거예요. 얼마 전에 저도 그런 저작물을 하나 입수했는데, 남서쪽의 성가신 트로그 놈들이 훔쳐 갔어요.\n\n트로그 야영지에서 주문 기록을 회수한 다음, 지침서를 참고해 해석하십시오. 연구를 마치는 대로 돌아오시길.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적누더기 헝겊 장갑"},
[77669] = {title = "붉은십자군 룬", objective = "붉은십자군 순례자를 소매치기 또는 처치하여 룬을 찾아내야 합니다. 이후 룬을 사용하여 새로운 능력을 배운 다음, 데스넬에 있는 데이비드 트리아스에게 가야 합니다.", description = "<name>, 생전의 자네는 어떤 사람이었나? 첩자? 도둑? 칼 다루는 솜씨가 일품인 요리사? 과거야 어쨌든 이젠 새로운 전략을 구사해야 하네. 포세이큰의 도적은 굴러들어 오는 기회를 놓치는 법이 없지.\n\n동쪽에 있는 붉은십자군 순례자는 살면서 전투 한 번 치러본 적 없는 것처럼 싸우더군. 그런데 붉은십자군에서 역량을 강화해 줄 신비한 룬을 지급해 준 모양일세. 룬을 훔쳐 그 능력을 습득한 다음 돌아오게.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n갈라진 가죽 장갑"},
[77670] = {title = "언데드에 관한 명상", objective = "무덤에서 무릎을 꿇고 언데드에 관한 명상을 한 후, 룬을 사용하여 새로운 능력을 배워야 합니다. 이후 데스넬 예배당에 있는 어둠의 사제 듀스텐에게 가야 합니다.", description = "자네의 정신을 산 자의 기억으로 인도하겠네. 자네의 기억일 수도 있어. 예배당 옆에 붙은 묘지로 가서 죽음의 한기가 가장 강렬한 장소를 찾게. 그리고 무릎을 꿇고 사색에 집중하게나. 언데드의 신비를 집중해서 탐구하다 보면 기억이 명료해지고 새로운 기술을 습득하게 될 걸세. 일을 끝마치는 대로 돌아오게나.", progress = nil, completion = "산 자가 빛에 목매는 이유는 단 하나, 죽음의 망각을 두려워하기 때문이네. 포세이큰은 그런 공포에 얽매일 이유가 없지. 작금의 빛은 한때 누구보다 열렬했던 신자마저 거부하고 있지만, 우린 죽음의 그림자 너머에 있는 어둠의 힘을 지배하네.\n\n점점 강해질수록 호드의 트롤과 함께 시간을 보내도록 하게. 문화는 미개하기 짝이 없지만 트롤이 경배하는 '로아'는 &lt;race&gt;와 어느 정도 연관이 있어. 우리의 본질에 한층 더 가까워질 수 있을 걸세.", rewards = "다음과 같은 것들을 받습니다:\n\n누더기 헝겊 장갑"},
[77672] = {title = "잃어버린 룬", objective = "검은그물 거미굴에서 룬을 회수해야 합니다. 이후 룬을 사용하여 새로운 능력을 배운 다음, 데스넬에 있는 맥시밀리언에게 가야 합니다.", description = "나는 새로운 종류의 마법을 연구하고 있네. 지옥 마력을 집중해 막강한 주문의 원동력으로 삼을 수 있게 해주는 룬이지. 제자 하나를 북쪽 광산으로 보내 그곳 거미들에게 룬을 시험하려고 했네만, 돌아오지 않았어. 두 번 다시는 못 보겠지.\n\n자네라면 더 잘 버틸지도 모르겠군. 광산으로 가서 거미줄을 살펴 룬을 회수하게. 찾으면 그 마법을 배우고 돌아오도록.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n누더기 헝겊 장갑"},
[78088] = {title = "기묘한 유물", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[78114] = {title = "야생의 와이번 길들이기", objective = "최면의 수정과 옹이진 길들지 않은 마법의 마법봉을 돌발톱 산맥에 있는 지소 매드로켓에게 가져가야 합니다.", description = "이 주변을 날아다니는 사자날개 와이번을 본 적 있으신가요? 저 녀석을 타고 공중에서 재주넘기를 하는 모습을 보여줄 수 있다고 하면 웃돈을 주고서라도 구경하려는 사람들이 줄을 설 거예요.\n\n문제는 녀석들 성질이 고약하다는 사실이죠. 공중 곡예는 고사하고 한 마리 길들이기도 힘들어요.\n\n그런데 특별한 마법봉으로 녀석들을 차분하게 만들 수 있다더군요. 제가 직접 만드는 게 가능할 정도라고 해요. 최면의 수정하고 옹이진 길들지 않은 마법의 마법봉만 있으면 되거든요. \n\n어디서 구하는지는 잘 모르겠지만, 자세한 건 나중에 따져보자고요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
