[78144] = {title = "용학살자 알론소", objective = "알론소를 따라 용을 처단해야 합니다.", description = "때가 됐네, <name>. 진정한 용학살자에게 어울리는 방어구를 입었네! 자네가 큰 도움이 됐어.\n\n이제 명예 종자로서 나와 함께하세. 이 몸이 위대한 용을 무찌르는 광경을 지켜봐 주게나!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n분노의 강타의 룬"},
