[78146] = {title = "고아즈 두루마리", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
