[78150] = {title = "도서관의 친구", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n바지 각인술 - 얼음 핏줄\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n얼음 핏줄"},
[78194] = {title = "엘룬의 비밀", objective = "그늘숲의 늑대에게서 광포한 늑대 발 10개를 수집해야 합니다.", description = "엘룬께 관심을 보이는 <race>|1을;를; 만나다니, 신선한 경험을 다 해보네요. 엘룬께서 가장 아끼는 자손은 칼도레이가 맞지만, 실제로는 아제로스의 모든 존재를 아끼신답니다. 우린 엘룬 님의 축복을 받는 대신 그분의 이름으로 이 땅을 가꾸고 있지요.\n\n그런데 그늘숲에서 자연의 조화가 어그러진 모양이더군요. 광포한 늑대들이 나타나 날뛰는 모습이 목격되었다고 해요. 그 늑대들을 처리하여 엘룬 님이 추구하시는 조화에 경의를 표하고, 증거를 가지고 돌아오세요.", progress = nil, completion = nil, rewards = nil},
[78198] = {title = "로아의 비밀", objective = "힐스브래드 구릉지에서 힐스브래드 주민의 유골 14개를 모아 언더시티에 있는 바주라에게 가져가야 합니다.", description = "우리 선조들의 강대한 트롤 제국은 아제로스를 주름잡는 강력한 영혼, 로아의 힘을 바탕으로 세워졌네. 검은창 부족은 여러 로아를 숭배하지만 신앙의 공유라면 특히 타협해 볼 만한 존재가 있지.\n\n우선 공물을 준비해야 하네. 타렌 밀농장으로 가 호드의 영유권을 침탈하는 인간들을 공격하게. 적의 뼈를 모아 돌아오게나.", progress = nil, completion = nil, rewards = nil},
[78229] = {title = "올빼미의 시련", objective = "세 올빼미의 상징을 달숲에 있는 로가나르에게 가져가야 합니다.", description = "상징을 보여주십시오, <name> 님.\n\n올빼미의 시련을 시작하신 것 같군요. 드루이드로서의 여정에 중요한 순간을 맞이하신 겁니다.\n\n이와 비슷한 상징이 여럿 존재합니다. 아제로스 전역에 흩어져 있지요. 상징을 얻으려면 정신과 육체로 위대한 업적을 성취해야 합니다.\n\n동부 왕국의 거대한 나무 아래에 올빼미 한 마리가 앉아 있습니다. 또 한 마리는 이곳 칼림도어의 거대한 나무 아래에 있습니다. 다른 하나는 바다에 있는데, 힐스브래드 해안에서 떨어진 지점에 있습니다.\n\n올빼미를 찾으십시오, <name> 님. 그리고 상징을 모아 가져오시면 됩니다.", progress = "시련은 잘 되어가고 있습니까, <name> 님?", completion = "축하드립니다, &lt;name&gt; 님. 그대가 성취한 업적은 결코 사소한 일이 아닙니다.\n\n올빼미의 시련을 통과하려면 &lt;class&gt;의 소명에 따라 모든 면모와 동화를 이루어 내야 합니다.\n\n이 룬을 받으십시오. 그대의 성취를 보여주는 증거입니다. 에메랄드의 꿈을 지키는 자로서 도움이 되길 바랍니다.", rewards = "다음과 같은 것들을 받습니다:\n\n급속 성장의 룬"},
[78261] = {title = "젤토스의 뿔", objective = "그림자송곳니 성채에서 젤토스의 뿔을 찾아야 합니다. 그런 다음 장작나무 마을 주변에 있는 C의 비밀 점선 지점에 반환해야 합니다. 이 일은 혼자서 완료해야 합니다.", description = "<상자 안에 웬 쪽지가 들어 있습니다.>\n\n반갑습니다, <name> 님.\n\n이번에는 젤토스의 뿔이라는 보물을 갖고 싶습니다. 그림자송곳니 성채 어딘가에 보관되어 있죠.\n\n보통 성채 깊숙이 들어가려면 지원이 필요합니다. 하지만 이번 일은 무엇보다도 잠입이 생명입니다.\n\n즉 혼자 가야 합니다.\n\n돌발톱 산맥에 비닉스라는 접선책이 있습니다. 안뜰 관문 통과를 도와줄 겁니다. 나머지는 당신 하기에 달렸습니다. \n\n뿔을 이곳에 넣어 놓으면 조만간 보수를 받을 수 있을 겁니다.\n\n- C", progress = "<상자가 텅 비어 있습니다.>", completion = "&lt;젤토스의 뿔을 상자에 넣습니다.&gt;", rewards = nil},
[78265] = {title = "물고기 기름", objective = "어유가 필요합니다. 그것도 대량으로!", description = nil, progress = "어유가 필요합니다. 그것도 대량으로!", completion = "정말 고맙습니다, &lt;name&gt; 님. 이 물건은 좋은 일에 쓰겠습니다.", rewards = nil},
[78266] = {title = "검은무쇠 군수품", objective = "검은무쇠 군수품이 필요합니다. 검은무쇠 드워프를 어디서 찾냐고요? 그건 알아서 해결해야죠!", description = nil, progress = "검은무쇠 군수품이 필요합니다. 검은무쇠 드워프를 어디서 찾냐고요? 그건 알아서 해결해야죠!", completion = "정말 고맙습니다, &lt;name&gt; 님. 이 물건은 좋은 일에 쓰겠습니다.", rewards = nil},
[78267] = {title = "벌목기 초충전 장치", objective = "투자개발회사의 벌목기 초충전 장치가 필요합니다. 벌목기에 견고하게 연결되어 있죠. 뽑아내려면 특별한 장비가 필요할 겁니다.\n\n참고로 저한테는 그런 거 없어요.", description = nil, progress = "투자개발회사의 벌목기 초충전 장치가 필요합니다. 벌목기에 견고하게 연결되어 있죠. 뽑아내려면 특별한 장비가 필요할 겁니다.\n\n참고로 저한테는 그런 거 없어요.", completion = "정말 고맙습니다, &lt;name&gt; 님. 이 물건은 좋은 일에 쓰겠습니다.", rewards = nil},
[78270] = {title = "고블린 자물쇠따개", objective = "그림자송곳니 성채에서 젤토스의 뿔을 찾아야 합니다. 그런 다음 장작나무 마을 주변에 있는 C의 비밀 점선 지점에 반환해야 합니다.", description = "<상자 안에 웬 쪽지가 들어 있습니다.>\n\n다시 만나 반갑습니다, <name> 님.\n\n이번에는 젤토스의 뿔이라는 보물을 갖고 싶습니다. 그림자송곳니 성채 어딘가에 보관되어 있죠.\n\n보통 성채 깊숙이 들어가려면 지원이 필요합니다. 하지만 이번 일은 무엇보다도 잠입이 생명입니다.\n\n즉 혼자 가야 합니다.\n\n돌발톱 산맥에 비닉스라는 접선책이 있습니다. 안뜰 관문 통과를 도와줄 겁니다. 나머지는 당신 하기에 달렸습니다. \n\n뿔을 이곳에 넣어 놓으면 조만간 보수를 받을 수 있을 겁니다.\n\n- C", progress = "그림자송곳니 성채에... 단독으로 침투해야 한다고요? 배짱 한번 두둑하군요!\n\n관문 돌파에 필요한 폭탄은 챙겨드릴 수 있습니다. 그런데 장부에 흔적을 남겨야 해서, 주문 의뢰를 받아야 해요. 이 근처 직원 중에 의뢰서를 가진 자가 있을 겁니다. 땜질이나 제작을 많이 하는 사람이 좋겠군요.", completion = "잘하셨습니다, &lt;name&gt; 님. 역시 당신에겐 식은 죽 먹기일 줄 알았습니다.\n\n약속한 물건입니다.", rewards = "다음과 같은 것들을 받습니다:\n\n돌파용 폭탄"},
[78277] = {title = "감사의 징표", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n장갑 각인술 - 살아있는 폭탄\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n살아있는 폭탄 배우기\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[78287] = {title = "거절할 수 없는 제안", objective = "무기 화물을 스톰윈드에 있는 스승 우드에게 전달해야 합니다.", description = "첫 번째 꾸러미가 준비됐습니다, <name> 님. 이 물건을 스톰윈드로 가져간 뒤 높으신 분에게 보여주세요. 오늘 바로 서명해 줄 수 있는 사람으로!", progress = "톱니항에서 온 배달품이라고요? 거기서 뭐 주문한 기억이 없는데.", completion = "톱니항 무기 공급업자? 흠... 얼라이언스에 물자 하나하나가 아쉬운 상황이긴 합니다. 호드가 계약을 체결하게 둘 순 없지요. 빨리 움직여야겠군요.", rewards = nil},
[78288] = {title = "거절할 수 없는 제안", objective = "무기 화물을 오그리마에 있는 젤막에게 전달해야 합니다.", description = "첫 번째 꾸러미가 준비됐습니다, <name> 님. 이 물건을 오그리마로 가져간 뒤 높으신 분에게 보여주세요. 오늘 바로 서명해 줄 수 있는 사람으로!", progress = "톱니항에서 온 배달품이라고요? 거기서 뭐 주문한 기억이 없는데.", completion = "톱니항 무기 공급업자? 흠... 안 그래도 호드에서 고블린 상인을 이쪽으로 포섭하려고 했지. 얼라이언스와 손을 잡게 둘 순 없는 노릇이니까. 이 새로운 기회를 놓치지 않으려면 서둘러야겠군.", rewards = nil},
[78297] = {title = "거래 성사", objective = "서명한 조달 계약서를 톱니항에 있는 그리즈비에게 전달해야 합니다.", description = "<name> 님, 필요한 서명은 다 해뒀습니다. 톱니항 공급업자에게 전해주십시오. 얼라이언스는 기꺼이 거래에 응할 의사가 있다고 말입니다.", progress = "거래는 성사하고 왔나요?", completion = "협상도 하지 않고 계약서에 서명했다고요? 하! 이 그리즈비 인생에 볕들 날이 오는구나! \n\n&lt;name&gt;, 당신 의리는 확실히 알았습니다. 받으세요. 소소한 감사의 표시입니다.\n\n공식적으로 사업을 시작했으니 언제든 장비를 둘러보셔도 좋습니다. 마음에 드는 게 있으면 말씀하세요. 직원 할인가로 드리죠!", rewards = "다음과 같은 것들을 받습니다:\n\n그리즈 방위 산업 설립자 증서"},
[78304] = {title = "거래 성사", objective = "서명한 조달 계약서를 톱니항에 있는 그리즈비에게 전달해야 합니다.", description = "<name>, 필요한 서명은 다 해뒀네. 가서 그 고블린에게 앞으로는 호드하고만 거래하라고 전하게.", progress = "거래는 성사하고 왔나요?", completion = "협상도 하지 않고 계약서에 서명했다고요? 하! 이 그리즈비 인생에 볕들 날이 오는구나! \n\n&lt;name&gt;, 당신 의리는 확실히 알았습니다. 받으세요. 소소한 감사의 표시입니다.\n\n공식적으로 사업을 시작했으니 언제든 장비를 둘러보셔도 좋습니다. 마음에 드는 게 있으면 말씀하세요. 직원 할인가로 드리죠!", rewards = "다음과 같은 것들을 받습니다:\n\n그리즈 방위 산업 설립자 증서"},
[78307] = {title = "젤토스의 뿔", objective = "기록", description = "내용", progress = nil, completion = "&lt;상자에 쪽지가 놓여 있습니다.&gt;\n\n&lt;name&gt; 님을 위한 겁니다. 다음에 또 봅시다.\n\n- C", rewards = "다음과 같은 것들을 받습니다:\n\n맹독 조합의 룬"},
[78506] = {title = "정령의 괴로움", objective = "정기의 분노 티끌을 수집해 잿빛 골짜기 조람가르 전초기지에 있는 제네우 생크리에게 전달해야 합니다.", description = "잘 듣게, <name>. 이 타락은 군주 아쿠아니스를 넘어서는 문제일세. 얼마 전부터 정령계에서 불길한 기운이 느껴졌지. 무언가 심각한 문제가 생긴 것 같네. 군주 아쿠아니스의 타락을 보니 내 의심이 사실인 것 같군.\n\n이곳 잿빛 골짜기와 돌발톱 산맥에서 고통받는 정령을 좀 더 찾아보게. 정수의 티끌을 가져오는 것도 괜찮겠군. 분석해 보면 분노의 원인을 알 수 있을지도 모르지.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[78537] = {title = "통찰의 비약", objective = "수중 호흡의 비약과 지혜의 비약을 잿빛 골짜기 조람가르 전초기지에 있는 제네우 생크리에게 가져가야 합니다.", description = "<name> 자네가 모아온 티끌은 중요한 단서일세. 하지만 상황을 온전히 파악하려면 정령의 인도가 필요하네.\n\n내가 애용하는 의식이 있네. 다만 통찰의 비약이 필요해. 의식을 통해 환영을 확인하면 다음으로 할 일을 알 수 있을 걸세.\n\n재료가 되는 비약만 있으면 내가 직접 만들 수 있네. 육체를 해방할 수중 호흡의 비약과 정신을 개방할 지혜의 비약이지.\n\n재료 비약을 가져오게. 의식을 거행해 보세나.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[78561] = {title = "통찰의 비약", objective = "조람가르 전초기지 근처 화톳불에서 통찰의 비약을 마신 후 환영을 목격해야 합니다.\n\n제공된 아이템: \n", description = "비약은 준비됐네, <name>. 해변에 있는 화톳불로 가서 들이켜게나. 영혼이 선사하는 환영에 호응한 다음 정보를 캐오게.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[78575] = {title = "히르제크", objective = "불모의 땅에 있는 검은가시 마루에서 히르제크를 처치하고 그 지팡이를 잿빛 골짜기 조람가르 전초기지에 있는 제네우 생크리에게 전달해야 합니다.", description = "자네가 환영에서 본 가시멧돼지는 히르제크일 걸세. \n\n가시멧돼지가 자체적으로 조잡한 주술을 부리는 건 대지고리회에서도 전부터 알고는 있었네. 그런데 요즘 들어 불길하게도 성취가 늘고 있다는 소식이 전해지더군. 히르제크가 딱 그렇지. \n\n아무래도 히르제크는 나나 자네와 달리 정령과 협력하는 대신 노예로 만드는 것 같네. 정령계에도 큰 문제가 되고 있겠지.\n\n<name> 자네가 막아주게. 주술사와 정령을 위해.", progress = "히르제크의 행동은 주술과 정기 그 자체에 대한 모욕일세. 반드시 막아야 해.", completion = "&lt;지팡이를 받는 제네우&gt;\n\n큰일을 해냈군, &lt;name&gt;. 히르제크의 고문이 끝났다니 다행일세. 하지만 놈이 더 심각한 질병의 징조는 아닐지 걱정되는군. 아제로스의 수많은 정령이 고통 어린 신음을 내지르고 있네.\n\n아직 풀리지 않은 의문이 많아. 오히려 이 일을 시작했을 때부터 의문이 늘어난 것 같기도 해. 어쨌든 대지고리회를 도와줘서 고맙네.", rewards = "다음과 같은 것들을 받습니다:\n\n대지의 보호막의 룬"},
[78611] = {title = "잘못 놓인 화물", objective = "몇 가지 물품이 사라지긴 했지만... 그래도 쓸모는 있네요. 감사합니다, <name> 님.", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n일부 보급품 사용\n\n다음과 같은 것들을 받습니다:\n\n"},
[78612] = {title = "온전한 화물", objective = "뭘 가져오셨습니까?", description = nil, progress = "뭘 가져오셨습니까?", completion = "물건이 다 들어 있군요! 감사합니다, &lt;name&gt; 님. 이 보급품은 최전방에서 중요하게 쓰일 거예요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\nReputation - Merchant Faction\n\n다음과 같은 것들을 받습니다:\n\n"},
[78681] = {title = "소환", objective = "군단의 피 10개를 수집한 후 데스알텍을 소환하는 의식을 거행하여 다시 영혼을 잡아들여야 합니다.", description = "악마 데스알텍은 감옥에서 도망쳤을 뿐, 죄수답게 여전히 감옥에 속박되어 있다오. 요컨대 악마를 불러내 영혼을 다시 잡아들여야 한다는 소리요.\n\n북쪽 잿빛 골짜기는 위대한 악마가 쓰러진 장소요. 그리고 군단이 제물을 바칠 때 사용했던 언덕이 있지. 극악무도한 만행으로 그 땅에는 영원히 씻지 못할 상흔이 남았소. 이 땅에 들끓는 악마에게서 군단의 피를 모은다면... 그게 열쇠가 되겠지.", progress = "피의 공물을 바쳐야 합니다.", completion = "암흑 의식용 돌을 사용해 암흑의 의식을 시작합니다. 이젠 돌아올 수 없는 강을 건넜습니다...", rewards = nil},
[78684] = {title = "수수께끼의 여행자", objective = "불모의 땅에서 도안 카르한과 수수께끼의 여행자를 만나야 합니다.", description = "뭐야? 여긴 어디지? 내가... 어떻게 여기까지 온 거지?\n\n<눈앞의 사내가 뱃멀미라도 하듯 휘청거립니다. 손을 떠는 사내는 눈이 휘둥그레지더니, 당혹감에 당신과 시선을 한참 교환합니다.>\n\n아... 같은 흑마법사였군요. 어쩌다 이렇게 됐는지, 뭐가 잘못됐는지 상의해 보는 건 어떨까요?\n\n<막막한 당신은 도안 카르한을 찾아가 얘기를 나누어 볼 것을 제안합니다.>", progress = nil, completion = "정말 흥미롭군... 악마를 처단하러 보냈더니 친구를 데리고 올 줄은 꿈에도 몰랐는데.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n라스젤 앤더"},
[78702] = {title = "라스젤 앤더", objective = "라스젤은 내 친구였소... 오래전에... 지금과는 시대가 다를 때 잃어버린 친구였지... 당시 우린 어린 수습생이었고... 많은 게 달라졌지.\n\n의식 결과로 차질이 좀 생기긴 했지만, 무기를 복원하는 것은 가능하오.\n\n라스젤과 상의할 게 많구려. 함께 계획을 세워보리다. 가닥이 잡히는 대로 연락하겠소.\n\n일단 이걸 받아 주시오. 당신이라면 관심을 보일 것 같거든.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n탈태의 룬"},
[78872] = {title = "온전한 화물", objective = "뭘 가져오셨습니까?", description = nil, progress = "뭘 가져오셨습니까?", completion = "물건이 다 들어 있군요! 감사합니다, &lt;name&gt; 님. 이 보급품은 최전방에서 중요하게 쓰일 거예요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\nReputation - Merchant Faction\n\n다음과 같은 것들을 받습니다:\n\n"},
[78909] = {title = "변화무쌍한 비늘 부적", objective = "노라 애니하트에게 한 줌의 변화무쌍한 비늘과 더불어 부적 제작에 필요한 다른 재료를 전달해야 합니다. 이상한 가루 주머니, 상급 마법의 정수 5개, 희미하게 빛나는 작은 결정 2개, 5골드를 가져가야 합니다.", description = "부적 재료가... 그렇게 많이 필요한 건 아니에요.\n\n<멋쩍게 미소를 짓는 노라>", progress = "어디 가서 마법부여사라고 명함을 내밀기엔 부끄러운 실력이지만... 그래도 이번 건 제대로 만들어진 것 같아요. 이론상으로는 말이죠.", completion = "모험에 행운이 함께하길 빌게요. 혹시 이번처럼 놀라운 생명체를 찾거든 또 찾아주세요!", rewards = "다음과 같은 것들을 받습니다:\n\n변화무쌍한 비늘 부적"},
[78916] = {title = "공허의 심장", objective = "다르나서스에 있는 새벽감시자 셀고름에게 검은심연 진주를 가져가야 합니다.", description = "<무시무시한 야수 아쿠마이의 사체가 널브러져 있습니다. 부풀어 오른 사체의 내장과 선혈 사이로 큼지막한 오색 빛깔 진주가 보입니다. 순수한 공허의 마력이 넘칠 듯이 가득합니다.>", progress = "<name>, 검은심연에서 어떤 소식을 가져오셨소?", completion = "고대 신의 시종 아쿠마이를 처단했다니. 진정한 영웅에 걸맞은 업적을 세웠구려. \n\n이 물건은 공허의 본질은 무엇이며, 우리 세상에는 어떤 영향을 주는지 깊이 이해하는 열쇠가 될지도 모르오. 당장 연구에 착수해야겠군. 고맙소, &lt;name&gt;.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n수행사제의 공허 진주기원사의 공허 진주복수자의 공허 진주"},
[78917] = {title = "공허의 심장", objective = "썬더 블러프에 있는 바샤나 룬토템에게 검은심연 진주를 가져가야 합니다.", description = "<무시무시한 야수 아쿠마이의 사체가 널브러져 있습니다. 부풀어 오른 사체의 내장과 선혈 사이로 큼지막한 오색 빛깔 진주가 보입니다. 순수한 공허의 마력이 넘칠 듯이 가득합니다.>", progress = "<name>, 검은심연에서 어떤 소식을 가져오셨습니까?", completion = "고대 신의 시종 아쿠마이를 처단하셨다니. 오늘 칼림도어 주민들이 그대에게 크나큰 은혜를 입었습니다.\n\n이 진주가 공허의 본질은 무엇이며, 우리 세상에는 어떤 영향을 주는지 깊이 이해하는 열쇠가 될지도 모릅니다. 당장 연구에 착수하겠습니다. 대지모신이 함께하길 빕니다, &lt;name&gt; 님.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n수행사제의 공허 진주기원사의 공허 진주복수자의 공허 진주"},
[78920] = {title = "군주 아쿠아니스", objective = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다.", description = "물의 정령이 쓰러지면서 이상한 물구슬을 하나 남겼습니다. 이 구슬이 바로 괴력의 원천이었나 봅니다. 구슬 안에서 출렁거리는 물을 바라보자 묘하게도 어떤 끔찍한 느낌이 듭니다. 하지만 구슬 자체는 어떠한 외부의 힘에도 손상되지 않는 듯합니다.\n\n이 구슬에 대해 알고 있는 이가 있다면 그건 바로 속세의 고리회의 제네우 생크리일 것입니다. 그는 잿빛 골짜기의 조람가르 전초기지에 있습니다.", progress = "아, <name>. 또 보는군. 난 늘 그렇듯이 여기서 물결의 흐름을 보고 있었네. 이곳 전초기지에는 무슨 일로 왔나?", completion = "오... 이건 정말 대단한 발견일세.\n\n&lt;name&gt;, 이걸 검은심연의 나락에서 군주 아쿠아니스를 처치하고 얻었다고 했나? 아쿠아니스는 오랫동안 타락한 정령에게 힘을 주는 존재로 여겨져 왔네. 무엇이 그를 타락하게 만들었는지 이 구슬이 알려줄 것 같군. 그게 황혼의 망치단일지라도 그리 놀라운 일은 아니겠지... 연구를 계속 해보면 어떻게 해서 타락하게 만들었는지도 알 수 있게 되겠지.\n\n잘했네. 속세의 고리회를 대신하여 내리는 호의와 감사의 표시이니 이것을 받게.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n무법자 사브르마녀의 손가락\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[78921] = {title = "검은심연의 음모", objective = "황혼의 군주 켈리스를 처치하고 그 증거로 머리카락을 다르나서스에 있는 새벽감시자 셀고름에게 가져가야 합니다.", description = "이제 난 아무 힘이 없소. 당신의 도움이 필요하오!\n\n아주 오래전 이곳은 위대한 엘룬의 신전이었소. 하지만 불행히도 한 타락한 고대 신의 기운이 땅 밑에서 솟아 나와 성스러운 달샘을 오염시키면서 폐허가 되어 버렸다오.\n\n고대 신의 시녀인 아쿠마이가 물 위로 올라왔소.\n\n황혼의 망치단 이교도들은 이 땅을 점령하기 위해 나가와 동맹을 맺었는데, 켈리스를 따르는 이 이교도 집단은 죄 없는 자들을 아쿠마이에게 희생 제물로 바쳐 힘을 얻고 있소.\n\n<name>, 켈리스를 해치우고 그의 머리카락을 다르나서스의 셀고름에게 가져다주시오!", progress = "<class> 친구, 시간은 소중한 것이오!\n\n이곳 다르나서스에서 내 임무는 우리 은빛 여명회의 번성을 위해 칼림도어를 침략하는 악의 무리를 막는 것이오.\n\n어서 용건을 이야기하든지 아니면 가 보시오.", completion = "켈리스 녀석은 꽤 오랫동안 우리의 추적을 피해 왔소.\n\n이 부근에 모습을 드러내던 사악한 세력들은 모두 켈리스와 끈이 닿아 있었던 모양이오. 한동안 우리는 그가 죽었거나 실종된 줄로만 알았소이다.\n\n이것으로 모든 게 해결되었소. 그의 권세가 끝났으니 무고한 자들의 목숨을 구하게 된 것이오.\n\n한 개인의 이익을 위해 고대 신의 시녀에게 희생 제물을 바치다니, 정말 말도 안 되는 일이지!\n\n아주 훌륭한 일을 해주셨소, &lt;name&gt;. 은빛 여명회를 대신해 진심으로 감사하오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n각인된 묘비의 홀고대 북극의 버클러\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[78922] = {title = "검은심연의 음모", objective = "황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다.", description = "이제 난 아무 힘도 없소. 당신의 도움이 필요하오!\n\n아주 오래전 이곳은 위대한 엘룬의 신전이었소. 하지만 불행히도 어느 고대 신의 타락한 기운이 땅 밑에서 스며 나와 성스러운 달샘을 오염시키면서 폐허가 되어 버렸지.\n\n고대 신의 시녀인 아쿠마이가 물 위로 올라왔소.\n\n황혼의 망치단 이교도들은 이 땅을 점령하기 위해 나가와 동맹을 맺었소. 켈리스를 따르는 이 이교도 집단은 죄 없는 자들을 아쿠마이에게 희생 제물로 바쳐 힘을 얻고 있소.\n\n<name>, 켈리스를 해치우고 그의 머리카락을 썬더 블러프에 있는 바샤나에게 가져다주시오!", progress = "<name>, 항상 대지모신께서 당신과 함께하시기를...\n\n우리의 목표는 이 땅에서 대지모신의 후손들이 언제까지나 평화롭게 지내는 것이랍니다. 대지모신께서는 자연을 위한 원대한 계획을 세우고 계십니다. 그리고 그 계획 안에서 우리는 모두 각자 역할이 있지요.", completion = "켈리스는 은빛 여명회를 교묘히 피해 왔습니다.\n\n한 동안 은빛 여명회에서는 켈리스가 죽었거나 실종되었다고 생각했습니다.\n\n&lt;name&gt;, 당신은 그의 폭정을 끝냄으로써 선량한 많은 이들의 목숨을 구한 것입니다.\n\n대지모신께 찬양을! 고대 신의 노예들이 사사로운 욕심으로 선량한 이들을 희생 제물로 바치다니... 정말 역겹기 그지없는 일입니다!\n\n오늘 정말 위대한 일을 해주셨습니다. 켈리스는 고대 신을 숭배함으로써 세계를 혼돈의 시대로 되돌리려 한 사악한 존재였습니다. &lt;name&gt;, 고맙습니다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n각인된 묘비의 홀고대 북극의 버클러\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[78923] = {title = "심연의 지식", objective = "아이언포지, 쓸쓸한 뒷골목에 있는 게릭 본그립에게 로르갈리스 초본을 가져가야 합니다.", description = "이미 알고 있을지 모르겠지만, 난 고대 지식이나 강력한 힘을 지닌 정보, 새로운 차원의 문을 여는 지식, 그리고 잠든 자들을 깨우는 지식을 모은다네.\n\n소문에 의하면 잿빛 골짜기에 있는 검은심연의 나락 깊숙한 곳에 로르갈리스 초본이라는 오래된 지식서가 있다고 하던데... 그곳은 이미 오래전에 죽은 엘프들이 점령해 거처로 삼고 있지. 도시가 파멸되기 전에는 위대한 지식을 가졌던 귀족들이라네.\n\n검은심연의 나락에서 그 초본을 찾아오면 은혜는 잊지 않겠네. 이 세상을 떠나더라도... 잊지 않을 거야.", progress = "<name>, 잿빛 골짜기로 가는 길은 험난하고 이번 임무는 쉽지 않겠지만 초본을 가져와 주기 바라네. 그러면 그에 합당한 사례가 있을 것이네.", completion = "초본을 찾았군! 이렇게 기쁜 날이 또 있을까! 우리 형제자매들에게 로르갈리스의 고대 지식을 전할 수 있게 된다니! 어서 사본을 만들어 배포해야겠네.\n\n&lt;name&gt; 자네가 한 일이 얼마나 큰 의미가 있는지 모를 거야. 이 선물이 우리가 전하는 감사의 마음을 제대로 표현해 줬으면 좋겠군.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n영원한 존속의 반지"},
[78925] = {title = "황혼의 망치단의 몰락", objective = "다르나서스에 있는 은빛경비병 마나도스에게 황혼의 펜던트 10개를 가져가야 합니다.", description = "혼돈의 고대 신을 위한 고대 의식으로 힘을 얻은 황혼의 망치단 단원들이 사악한 후원자들을 환생시켜 전 세계에 죽음과 공포를 퍼뜨리려 하고 있소.\n\n이들은 나가와 동맹을 맺고 잿빛 골짜기 해안에 있는 검은심연의 나락에 집결하고 있다고 하오.\n\n그들이 그 오래된 신전 깊은 곳에서 어떤 사악한 음모를 꾸미고 있든지 이를 반드시 좌절시켜야 하오.\n\n황혼의 망치단과 결전을 벌이고 승리의 증거물을 가지고 돌아오시오. 수고에 대한 보상은 후하게 해 드리리다.", progress = "검은심연의 나락은 한때 나이트 엘프의 고대 신전이었소. 가장 강력한 힘을 지닌 달샘이 안치되어 있던 곳이었지. 그런데 이제 황혼의 망치단의 손아귀에 떨어졌으니 그곳에서 어떤 사악한 음모가 꾸며지고 있을지 알 길이 없소이다.\n\n그들을 제거하는 일은 진전이 있었소?", completion = "&lt;name&gt; 당신은 용맹스럽고 고귀한 혈통을 타고 태어난 것이 틀림없소. 은빛 여명회는 악을 물리친 당신의 노고를 칭송하고 있소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n통찰의 빛구름 장화뜰지기의 심재 요대\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[78926] = {title = "타락에 대한 연구", objective = "아우버다인에 있는 게르샬라 나이트위스퍼가 변이된 뇌간 8개를 가져다 달라고 부탁했습니다.", description = "바보 같은 블러드 엘프들이 악마의 마법을 써 대다니... 칼림도어에서 사티로스와 나가들에게 어떤 일이 일어났는지 보지 못했단 말인가?\n\n블러드 엘프들도 그처럼 기형으로 변해 버릴까 걱정스럽소. 아제로스에 더는 사악한 종족이 태어나선 안 되오.\n\n블러드 엘프들의 운명이 앞으로 어떻게 될지 추론해 볼 수 있도록 사티로스와 나가의 뇌간을 연구해 보고 싶소. 잿빛 골짜기 해안에 있는 검은심연의 나락에서 사티로스와 나가를 모두 찾을 수 있을 거요.\n\n아주 먼 길이 될 것이오, <name>.", progress = "일단 표본을 충분히 확보하면 연구를 시작할 수 있을 것이오. 검은심연의 나락에 있는 사티로스와 나가의 변이된 뇌간을 손에 넣으면 돌연변이 간의 상호 관계에 대한 결론을 내려 볼 셈이오.\n\n새롭게 얻은 그 지식으로 어쩌면 블러드 엘프들이 기형과 악의 길에 더 깊이 빠지는 것을 막을 수 있을지도 모르겠소.", completion = "멀리까지 가서 분명 큰 위험에도 처했을 거요.\n\n당신의 행동은 아주 헌신적이었소. 내 연구를 도와주는 것은 아제로스 전체의 이익을 위한 일이오. 많은 수고를 해주어서 고맙소, &lt;name&gt;.\n\n자, 이제 나는 해야 할 일이 많이 있으니 이만 실례하겠소이다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n재잘거리는 딱정벌레 팔보호구해진 고위성직자의 단망토\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[78927] = {title = "고대 신들에 대한 충성", objective = "검은심연의 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오.", description = "황혼의 망치단 추종자들이 목적을 달성하도록 내버려 둘 수는 없지. 황혼의 망치단은 자연의 정령을 이해하지 못해. 그들은 오래전 사라져 버린 혼돈과 파괴의 피조물인 고대 신들을 믿고 있다네. 로구스의 계획이 성공하도록 내버려 둘 수는 없어. <name>, 가서 그를 막게. 나는 늙고 병들어 아무 힘도 없으니까.\n\n검은심연의 나락으로 가서 그를 찾아 처치하게. 그런 다음 여기 조람가르 전초기지로 다시 돌아오게나.", progress = nil, completion = "&lt;name&gt;, 수고했네. 황혼의 망치단의 야욕을 완전히 저지한 것은 아니지만 적어도 고대 신들에게 다시 힘을 불어넣으려고 했던 계획만큼은 분쇄한 것 같군.\n\n그들이 무엇을 노리고 있는지 누가 알겠네만 당분간은 우리도 쉴 수 있겠어.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n무쇠 주먹의 고리너덜거리는 밤나무 어깨보호대\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[78994] = {title = "견고한 기반", objective = "아제로스에는 에메랄드의 꿈으로 통하는 차원문이 여러 군데 있는데, 에메랄드 용들이 지키고 있습니다. 그중 한 곳에서 필요한 준비물을 확보할 수 있을 겁니다.\n\n어둠의 가지를 찾는 대로 곧장 돌아오세요.", description = "아시겠지만 무기를 다시 만들어 내는 건 쉽지 않아요. 게다가 의식이 어쩌다 실패했는지도 불분명하고요. 대신 제가 대안을 하나 고안하긴 했어요.\n\n우선 견고한 기반이 필요해요. 어둠의 가지가 필요하단 얘기죠.\n\n어둠의 가지는 에메랄드의 악몽에서 자란 사악한 성장물이 우리 세계로 스며든 결과예요. 주변 사람들의 의지를 약하게 만드는 효과가 있다더군요. 그런 마법적 성질이라면 무기의 본바탕으로 사용할 수 있을 거예요.\n\n이 물약을 받으세요. 에메랄드 용의 하수인들로부터 모습을 감춰주는 효능이 있어요. 탐색에 요긴할걸요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79007] = {title = "...그때 찾은 그 기록", objective = "길잡이로 삼을 만한 물건이라곤 불타버린 쪽지의 잔해뿐입니다.", description = "<불씨의 희미한 빛이 어두워집니다. 얼마 전 불을 지핀 흔적을 발견했습니다.\n사방에 흩어진 보급품 사이로 불에 탄 듯한 쪽지가 보입니다.\n\"불탔다고 해서 모두 사라지는 건 아니다. 쌍둥이 땅에서 알맞은 장소를 찾아라.\">", progress = nil, completion = "&lt;또 다른 불탄 시체의 잔해를 발견했습니다. 나무판자에 고정된 전언으로 시선이 옮겨갑니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n신속의 물약강한 재생의 물약"},
[79008] = {title = "...그때 찾은 그 기록", objective = "길잡이로 삼을 만한 물건이라곤 불타버린 쪽지의 잔해뿐입니다.", description = "<불씨의 희미한 빛이 어두워집니다. 얼마 전 불을 지핀 흔적을 발견했습니다.\n사방에 흩어진 보급품 사이로 불에 탄 듯한 쪽지가 보입니다.\n\"불탔다고 해서 모두 사라지는 건 아니다. 쌍둥이 땅에서 알맞은 장소를 찾아라.\">", progress = nil, completion = "&lt;또 다른 불탄 시체의 잔해를 발견했습니다. 나무판자에 고정된 전언으로 시선이 옮겨갑니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n신속의 물약강한 재생의 물약"},
[79077] = {title = "신앙의 공유", objective = "빛에 관하여 명상한 후, 무릎을 꿇은 엘프와 함께 기도를 올려 명상으로 얻은 깨달음을 나누어야 합니다.", description = "빛은 우리를 정의와 보호뿐만 아니라, 연민을 베풀도록 이끕니다. 우리의 동맹은 이 땅에서 낯선 이방인이니, 우리의 방식을 가르쳐 주어야 합니다.\n이 나이트 엘프는 빛을 추구하지만 명상에 어려움을 겪고 있습니다. 도와주실 수 있을는지요?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79080] = {title = "신앙의 공유", objective = "언데드에 관하여 명상한 후, 무릎을 꿇은 트롤과 함께 기도를 올려 명상으로 얻은 깨달음을 나누어야 합니다.", description = "이 트롤은 죽음에 관하여 사색하고 있지만... 죽음이란 화두 자체가 익숙하지 않다는 문제점이 있습니다. 명료하게 이해할 수 있도록 도와줘야 합니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79090] = {title = "침략자 격퇴", objective = "전쟁노래 척후병 징표를 잿빛 골짜기 달샘 기지에 있는 달의 여사제 팔로어 문레이에게 전달해야 합니다.", description = "전쟁노래 척후병 몇몇이 전사했지만, 전투의 열기는 식을 줄 모르고 계속됩니다...", progress = "<name> 님, 전방에서 어떤 소식을 가져오셨습니까?", completion = "호드 침략자들이 우리 땅을 더럽히고, 신성한 자연을 수확하고 있습니다. 지금껏 해온 대로 몰아내야 합니다!\n\n이 성스러운 전투의 찬가가 흔들리지 않는 전의를 북돋워 줄 것입니다. 감사합니다, &lt;name&gt; 님.", rewards = "다음과 같은 것들을 받습니다:\n\n은빛날개 전투의 찬가"},
[79091] = {title = "대마법사 안토니다스: 자서전 원본", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79092] = {title = "대마법사 테오크리투스의 연구 일지", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
