[79095] = {title = "연금술사의 형이상학적 지침서", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79096] = {title = "아테릭: 비전의 신비에 관하여", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79097] = {title = "박스탄: 파괴 마법에 관하여", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79098] = {title = "숲 정리", objective = "은빛날개 파수꾼 부적을 잿빛 골짜기 화톳불 기지에 있는 선견자 카즈라고어에게 전달해야 합니다.", description = "하나는 치웠군. 근데 얼라이언스 놈들이 계속 저항하니 성가시기 짝이 없단 말이야. 이건 또 무슨 부적이지?", progress = "<name>, 전방에서 어떤 소식을 가져왔나?", completion = "얼라이언스의 주구들이 계속해서 자원 채집을 방해하고 있네. 지금껏 해온 대로 쫓아내도록!\n\n이 전쟁노래 전쟁북이 흔들리지 않는 전의를 북돋워 줄 걸세. 록타르 오가르, &lt;name&gt;!", rewards = "다음과 같은 것들을 받습니다:\n\n전쟁노래 전쟁북"},
[79099] = {title = "군주 아쿠아니스", objective = "이상한 물구슬을 어둠의 해안 아우버다인에 있는 다비두스 보이드스타에게 전달해야 합니다.", description = "반갑습니다, <class>님. 어쩌다 굉장히 특이한 이야기를 들었습니다. 군주 아쿠아니스라는 타락한 물의 정령이 검은심연 나락이란 나이트 엘프 폐허로 들어가는 입구를 지키고 있다고 말이지요. 그래서 이렇게 군주 아쿠아니스의 핵... 다시 말해 타락한 물의 구슬을 가져올 용감한 모험가들을 구인하고 있습니다. 물건을 가져다주시면 조람 해안으로 직통하는 차원문을 이용할 수 있게 해드리겠습니다. 폐허 주변 환경을 연구할 때 사용하던 겁니다. 물론... 안전거리는 확보되어 있습니다.", progress = "아. 오셨습니까, <name> 님? 구슬은 찾으셨나요?", completion = "흐으음. 정말 특이하군요. 이런 건... 예상 밖인데. 아무튼 감사합니다. 약속한 대로 조람 해안으로 통하는 차원문을 사용하게 해드리겠습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[79100] = {title = "잘못 놓인 화물", objective = "몇 가지 물품이 사라지긴 했지만... 그래도 쓸모는 있네요. 감사합니다, <name> 님.", description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n일부 보급품 사용\n\n다음과 같은 것들을 받습니다:\n\n"},
[79101] = {title = "온전한 화물", objective = "뭘 가져오셨습니까?", description = nil, progress = "뭘 가져오셨습니까?", completion = "물건이 다 들어 있군요! 감사합니다, &lt;name&gt; 님. 이 보급품은 최전방에서 중요하게 쓰일 거예요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\nReputation - Merchant Faction\n\n다음과 같은 것들을 받습니다:\n\n"},
[79102] = {title = "온전한 화물", objective = "뭘 가져오셨습니까?", description = nil, progress = "뭘 가져오셨습니까?", completion = "물건이 다 들어 있군요! 감사합니다, &lt;name&gt; 님. 이 보급품은 최전방에서 중요하게 쓰일 거예요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\nReputation - Merchant Faction\n\n다음과 같은 것들을 받습니다:\n\n"},
[79103] = {title = "온전한 화물", objective = "뭘 가져오셨습니까?", description = nil, progress = "뭘 가져오셨습니까?", completion = "물건이 다 들어 있군요! 감사합니다, &lt;name&gt; 님. 이 보급품은 최전방에서 중요하게 쓰일 거예요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\nReputation - Merchant Faction\n\n다음과 같은 것들을 받습니다:\n\n"},
[79192] = {title = "디딤돌", objective = "<판자에서 쪽지를 뜯어내 휘갈긴 글귀를 읽습니다.>", description = "<기록의 초반부는 다음과 같습니다. \"임무 내용에 따르면 둘 다 신종 역병의 일종을 전달 중이었다고 한다. 내가 보기엔 단순한 연금술 사고인데 말이지. 안전하게 대화를 나누고 싶거든 불모의 땅과 잊혀진 땅 사이 산맥에 있는 내 피난처로 와라.\">", progress = nil, completion = "&lt;오지 모험가나 용병이 만든 야영지가 분명합니다. 그때 산들바람에 모서리 부분이 퍼덕이는 쪽지가 시선을 잡아끕니다.&gt;", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n채광용 곡괭이농부의 삽\n\n다음과 같은 것들 또한 받습니다:\n\n튼튼한 도시락장작나무부싯돌과 불쏘시개튼튼한 도시락"},
[79229] = {title = "노상강도", objective = "잊혀진 땅에서 약탈당한 야영지에 관해 아는 인물을 찾아야 합니다.", description = "<눈앞의 야영지는 참혹하기 이를 데 없습니다. 유해로 미루어 보건대 희생자는 두 인간과 한 명의 드워프로 추정됩니다. 뼈에 난 흔적을 보면 매서운 공격에 당한 듯한데, 보급품을 약탈당했으니 동물의 소행은 아닐 것입니다. 또, 부상의 형태가 켄타우로스 무기가 남기는 흔적과 일치하지 않습니다.\n\n이 땅을 훤히 꿰고 있는 노련한 수집가라면 좀 더 자세한 정보를 파악해 낼 수 있을지도 모릅니다.>", progress = nil, completion = "아, 또 다른 기록을 찾았나 보군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79235] = {title = "도망자", objective = "잊혀진 땅 약탈자를 찾아야 합니다.", description = "나도 <name> 자네의 설명과 비슷한 현장을 몇 군데 찾은 적 있어. 인간과 드워프가 있는 야영지만 골라서 건드렸더라고. 상단들 사이에서는 호드 약탈자들 짓이라고 소문이 돌아. 피해자들도 그렇고, 공격 수위도 잔혹하기 짝이 없으니까.\n\n강도 놈들은 얼라이언스 야전사령관이 추적에 나선 이후 잊혀진 땅으로 도망친 모양이야.\n\n뒤쫓을 생각이라면 항구를 둘러보라고. 별의별 수상한 놈들이 하루가 멀다고 꼬이는 동네잖아? 어디 다른 데로 갈 배편을 찾는 놈을 마주칠 수 있을지도 모르지.", progress = nil, completion = "무슨 용건이지? 빨리 말해.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79236] = {title = "술과 정보", objective = "무법항에 있는 토칼에게 체리 그로그주를 가져간 후 이야기를 마저 들어야 합니다.", description = "야전사령관하고 한패인가? 겉모습을 보면 그건 아닌 것 같군.\n\n소문은 반만 사실이야. 우리가 인간과 드워프 야영지를 약탈한 건 맞지만, 호드를 위해서 움직인 건 아니라고. 따로 고용주가 있다 이 말이지.\n\n그로그주를 사주면 처음부터 끝까지 다 알려줄게.", progress = "술은 언제 가져올 거야?", completion = "아. 이 맛이지. 그래, 어디까지 얘기했더라?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79242] = {title = "도둑의 명예 따윈 없다", objective = "아라시 고원 근처에서 일라리 더스크페더를 찾아 도난당한 전리품 은닉처를 알아내야 합니다.", description = "얘기를 계속하자면...\n\n우리 대장은 호드 소속이 아니야. 일라리 더스크페더라는 나이트 엘프지. 야영지에 관한 정보를 귀띔해 주고, 전리품 대부분의 소유권을 넘겨주기까지 했지. 희귀한 물건 몇 개만 가져가더라고.\n\n그런데 야전사령관이 추적에 나서면서 우리를 버리고 갔어. 왜 그랬는지는 모르겠어. 우리를 미끼로 삼으려 한 것 같기도 해.\n\n난 복수심이 많은 부류는 아니야. 그렇다고 그 여자를 추적하는 걸 막을 생각도 없어. 아라시 어딘가에 은신처를 두고 있다고 한 것 같은데, 한번 거기로 가보든지.", progress = "<일라리의 열쇠를 사용해 보관함을 엽니다.>", completion = "&lt;은닉처에는 작은 상자와 동전 몇 개가 들어 있습니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n[Jewel-Encrusted Box]"},
[79348] = {title = "사라진 고대정령", objective = "썩은 고대정령 씨앗에 관해 자세히 알려줄 수 있는 인물을 찾아야 합니다.", description = "<방랑하는 고대정령은 악취가 진동하는 씨앗만을 남긴 채 사라졌습니다. 겉은 잘 부스러지는 데다, 안에서는 고약한 냄새가 뿜어져 나옵니다.\n\n크기를 보건대 이 씨앗에서 태어난 고대정령은 제법 어렸던 것 같습니다. 고대정령의 기준에서 말이지요. 어쨌든 고대정령 같은 존재가 어쩌다 먼지 수렁을 헤매고 있었는지 궁금증이 생겨날 따름입니다. \n\n고대정령의 역사에 해박한 인물에게 이 씨앗을 가져가면 해답을 얻을 수 있을 것입니다.>", progress = nil, completion = "아, 어린 개체가 또 세상을 떠나고 말았군...", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79358] = {title = "너덜너덜한 쪽지", objective = "버섯구름 봉우리 주민들에게 경고해야 합니다.", description = "<찢긴 양피지 조각을 펼치자 다음과 같은 내용이 이어집니다.>\n\n땅굴이 버섯구름 봉우리 위쪽 절벽에 도달했고, 들키지 않고 준비 작업을 마쳤다. 하지만 서둘러야 해. 주술사를 보내도록. 히르제크의 성과 덕분에 시작할 준비는 다 끝났으니까.\n\n폭풍이 분노를 토하고, 대지는 요동칠 것이며, 해일이 솟아나 시체만을 남기리라. 이들 시체는 되살아날 것이며, 저들의 뼈가 길을 이룰지니...\n\n<조각 하단부에 이르자 글귀가 갑자기 끊깁니다.>", progress = nil, completion = "&lt;양피지를 읽어 내려가면서 \"흠\" 콧방귀를 끼는 거구의 &lt;race&gt;&gt;\n\n하나는 확실하군... 들키지 않고 준비를 완료했다는 내용만큼은 사실이오. 켄타우로스와 하피를 상대하는 데 와이번 기수를 투입하다 보니 협곡하고 절벽을 순찰할 겨를이 없었거든.\n\n위협의 존재를 알려줘서 고맙소. 그런데 손을 좀 더 빌려야 할 것 같구려.", rewards = nil},
[79361] = {title = "바람의 힘", objective = "잊혀진 땅에 있는 소용돌이 정령에게서 휘몰아치는 정수 5개를 획득한 후 알터랙 산맥에 있는 바람감시자 바스라에게 가져가야 합니다.", description = "이만한 폭풍을 일으키려면 땅을 휩쓸고도 남을 바람의 힘이 필요할 걸세. 무슨 의식인지는 몰라도 자네를 정기로부터 보호할 필요는 있겠군.\n\n소용돌이 정령들은 잊혀진 땅을 엉망으로 만들었지. 지금 거기서 살 수 있는 유일한 정령 중 하나이기도 하고. 소용돌이 정령의 정수를 가져오게.", progress = "아, 돌아다니느라 좀 고생이겠어?", completion = "그래, 그래. 바로 이거지.", rewards = nil},
[79362] = {title = "대지의 힘", objective = "황야의 땅에 있는 바위 정령에게서 지축을 울리는 정수 5개를 획득한 후 알터랙 산맥에 있는 바람감시자 바스라에게 가져가야 합니다.", description = "대지를 요동치게 만들려면 그만큼 대지와 강력한 유대를 맺어야 하네. 황야의 땅은 세월의 풍파 속에서 단련된 돌과 바위로 가득하지. 대지 그 자체가 실체화된 존재들의 요람이기도 하고.", progress = "이 친구 다리 후들거리는 것 좀 보게. 땅이 떨리고 있나?", completion = "한바탕 할 준비는 됐나?", rewards = nil},
[79363] = {title = "물의 힘", objective = "먼지진흙 습지대에 있는 가뭄의 정령에게서 세찬 정수 5개를 획득한 후 알터랙 산맥에 있는 바람감시자 바스라에게 가져가야 합니다.", description = "홍수가 가장 끔찍한 부분일세. 협곡은 건조한 지역이야. 갈라진 땅이나 분지에 며칠 물이 흐른다고 한들 순식간에 사라져 버리지.\n\n내가 알기로 홍수의 힘을 품은 정령이 많지는 않아. 하지만...\n\n<음험한 미소를 짓는 바스라>\n\n자네는 나만 믿게.\n\n먼지진흙 습지대로 가게나. 가뭄의 정령이 순수한 물의 정령은 아니지만, 나름대로 비밀이 있는 법이지.", progress = "위험 요소는 발견했나?", completion = "거기 묻은 오물 좀 털어내게. 거의 다 왔어.", rewards = nil},
[79364] = {title = "평범한 용기", objective = "내가 무슨 정신 나간 무기라도 만드는 줄 알았나? 아니야. 천만에. 아니고말고. 보호의 물약을 만드는 걸세.\n\n매사 불을 불로 다스리는 건 정답이 아니야.\n\n수정 약병을 알터랙 산맥에 있는 바람감시자 바스라에게 가져가야 합니다.", description = "수고 많았네. 버섯구름 봉우리에서 무엇을 마주하게 될지는 모르지만, 땅을 위협하는 정기를 막아내는 데는 확실히 효과가 있을 걸세.\n\n<바스라가 소지품을 뒤적거립니다. 짐을 살피는 손짓이 점점 빨라지는 걸 보니 바스라의 답답함이 전해지는 듯합니다. 이내 그가 멋쩍은 표정을 짓습니다.>\n\n아무래도 자네에게 부탁을 한 번 더 해야겠구먼.\n\n<환하게 미소를 짓더니 입을 여는 바스라>\n\n물약 병을 어디 잘못 둔 모양이야...", progress = "더 큰 병이 필요하네. 정기를 담아야 하니 수정처럼 투명해야 하고 말이야.", completion = "역시 자네를 믿길 잘했어.", rewards = nil},
[79365] = {title = "날개를 밀어주는 바람", objective = "버섯구름 봉우리의 높새바람 봉우리에 있는 라우 클리프러너에게 가야 합니다.\n\n제공된 아이템: \n", description = "자, 받게. 돌풍 인도자의 물약일세. 이걸 마시면 폭풍의 정기를 막아낼 수 있네. 하지만 지속시간이 짧다는 걸 명심하게나.\n\n자, 그만 가보게. 위기에 처한 친구들을 도우러 가야지. 내가 더 해줄 수 있는 건 없네.", progress = nil, completion = "와이번 기수들이 뭘 찾았다고 하네. 문제는 가까이 접근할 수 없어 상황 파악이 안 된다는군. 자네는 도움이 될 만한 정보를 알아냈나?", rewards = nil},
[79366] = {title = "폭풍전야", objective = "폭풍의 눈으로 들어가 가시멧돼지를 대면해야 합니다.", description = "가시덩굴 북동쪽에 외딴 절벽이 있는데, 거기서 폭풍이 비정상적으로 심하게 발생하고 있소.\n\n바람이 너무 강해 기수들은 접근이 불가능할 지경이고, 빗줄기도 심해 폭풍의 눈 안에 무엇이 도사리고 있을지 분간이 불가능하다오. 하지만 그 물약이라면 폭풍을 돌파할 수 있겠군.\n\n준비되는 대로 와이번 조련사 니세와 얘기해 보시오. 와이번을 내어줄 테니, 그걸 타고 폭풍으로 진입하면 될 거요.", progress = "뭔가 알아낸 게 있나?", completion = "요동치던 땅이 잠잠해졌소. 그대가 우릴 구한 거겠지. 고맙소, &lt;name&gt;.\n\n이 선물은 감사의 표시니 받아주시오.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n폭풍추격자의 손목띠번개부름이의 손목띠파도소환사의 손목띠\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n폭풍 종료"},
[79377] = {title = "잃어버린 묘목", objective = "동부 왕국에서 길 잃은 묘목 네 그루를 찾은 다음, 엘룬아라의 물을 나누어 주어야 합니다. 이후 달숲에 있는 오로카이에게 가야 합니다.", description = "혼란의 시대에는 씨앗이 척박한 토양에 뿌리를 내리기도 한다. 이렇게 탄생한 고대정령은 타락에 물들기 쉽지. 영영 평화를 찾지 못하고 적개심이 강한 땅을 거닐어야 하니까.\n\n바로 그런 운명에 처한 묘목 네 그루의 존재가 느껴지는구나. 동부 왕국에서 길을 잃었어. 각자가 한 계열을 상징하는 잎사귀를 입고 있지.\n\n부디 이 물을 그 아이들에게 전해 나을 수 있게 해다오.\n\n하지만 물의 마법은 섬세하니 조심하려무나. 순간이동은 물론이요, 전투에서 쓰러지기라도 했다간 파괴되고 말 것이야. 게다가 시간이 흐르면 효용성이 희미해지지.", progress = "서둘러라, <name>. 나의 동족을 구해다오.", completion = "&lt;name&gt; 네 행동이 수백 년은 이어질 생명을 구했다. 이루 말할 수 없이 고맙구나. 앞으로도 이 땅의 상처를 봉합해 다오.", rewards = "다음과 같은 것들을 받습니다:\n\n육성의 룬"},
[79442] = {title = "그간 있었던 일", objective = "알터랙 산맥에 있는 바람감시자 바스라에게 가 폭풍우의 눈을 활용할 방안이 있는지 알아봐야 합니다.", description = "이거 참 우리가 평생 갚지 못할 은혜를 입었군. 하지만 이 눈은 내게 별다른 쓸모가 없어. 바람감시자 그 영감이라면 몰라도 말이야.", progress = "아! 다친 데 없이 몸 성히 돌아왔구먼. 말해보게, 물약은 효과가 있었나?\n\n역시 자네를 믿길 잘했어. 왜냐하면 그 물약은 사실 맛있는 음료에 지나지 않거든. 사실 폭풍을 막아주는 효과보단 맛에 훨씬 더 치중한 물건이지.\n\n자, 자... 화내지 말게. 자네에게 필요한 건 한 줌의 용기였을 뿐이야. 결과적으로 이렇게 될 운명이었다, 이 얘기지.\n\n그건 그렇고 자네... 아주 강한 힘이 담긴 눈을 갖고 왔군.", completion = "이렇게 하세. 더 이상 속임수도, 장난도 치지 않겠네. 구미가 당길 만한 제안을 하지.\n\n그 눈알을 이 강력한 룬과 교환하세나. 새로운 재주를 배울 수 있을 걸세.\n\n어떤가?", rewards = "다음과 같은 것들을 받습니다:\n\n폭풍의 룬"},
[79482] = {title = "도둑맞은 장난감", objective = "알터랙 산맥의 어딘가 눈 덮인 지역에서 실종된 굴뚝나무 목장조합의 수색 요원을 찾아야 합니다.", description = "내 말 좀 들어보라고. 흥겨운 명절에 분위기 깨고 싶지는 않지만 굴뚝나무 목장조합에서는 뜻하지 않은 사고로 모험가의 도움을 필요로 하고 있네.\n\n축제에 없어서는 안 될 귀중한 장난감이 담긴 화물이 사라졌다고. 그걸 찾으러 보낸 굴뚝나무 목장조합의 요원도 실종된 상태고! 화물의 흔적을 마지막으로 알터랙 산맥 부근에서 보았다는 제보를 받고 우리 요원도 그리로 갔네.\n\n제발 부탁이야. 화물을 찾으러 간 우리 요원이 무사한지 꼭 좀 확인해 줘!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79483] = {title = "도둑맞은 장난감", objective = "알터랙 산맥의 어딘가 눈 덮인 지역에서 실종된 굴뚝나무 목장조합의 수색 요원을 찾아야 합니다.", description = "내 얘기 좀 들어봐. 흥겨운 명절 분위기를 깨고 싶지는 않지만 굴뚝나무 목장조합에서는 뜻하지 않은 사고로 모험가의 도움을 필요로 하고 있어.\n\n축제에 없어서는 안 될 귀중한 장난감이 담긴 굴뚝나무 목장조합의 화물이 사라졌다니까. 그걸 찾으러 보낸 우리 요원도 실종된 상태고! 부탁이야... 마지막으로 그 화물의 흔적을 알터랙 산맥 부근에서 보았다는 제보를 받고 우리 요원도 그리로 갔어.\n\n화물을 찾으러 간 우리 요원이 무사한지 꼭 좀 확인해 줘!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79492] = {title = "순록 멧젠", objective = "편지와 쪽지를 확인하여 잡혀간 순록 멧젠을 찾아야 합니다.\n\n멧젠을 발견하면, 순록 가루 주머니에 든 가루를 뿌려 멧젠을 감금 상태에서 풀어 주십시오.\n\n순록 멧젠이 구출한 후, 아이언포지에 있는 훌몰트 징글포켓에게 순록 가루 주머니를 가져가야 합니다.", description = "오, 맙소사! 이런 변이 있나! 우리 순록 멧젠이 납치당했다고!\n\n멧젠은 겨울 할아버지의 여덟 마리 순록 중의 하나이자, 굴뚝나무 목장조합의 귀중한 자산이지. 멧젠을 납치해 간 녀석들에게서 몸값을 요구하는 편지를 한 장도 아니고 자그마치 두 장이나 받았네. 사실, 겨울맞이 축제 선물을 준비해야 할 시기라 우리에겐 몸값으로 낼 돈이 없어! 자네가 우리 멧젠을 구해 주게!\n\n멧젠의 편지와 쪽지를 읽어보면 그의 행방에 대한 단서를 찾을 수 있을 거야! 그를 찾으면 이 순록 가루를 뿌리게나. 우리 멧젠을 어떤 구속에서라도 풀어줄 걸세!\n\n어서 서두르라고!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n보존된 호랑가시나무"},
[79495] = {title = "순록 멧젠", objective = "순록 멧젠을 찾아야 합니다. 편지와 쪽지에서 어디로 잡혀갔는지 단서를 찾으십시오.\n\n멧젠을 발견하면, 순록 가루 주머니에 든 가루를 뿌리십시오. 감금된 멧젠을 풀어줄 수 있을 것입니다.\n\n순록 멧젠을 구출한 후, 오그리마에 있는 케이말드 코퍼핀치에게 순록 가루 주머니를 가져가십시오.", description = "오, 맙소사! 이런 변이 있나! 우리 순록 멧젠이 납치당했다고!\n\n멧젠은 겨울 할아버지의 여덟 마리 순록 중의 하나이자, 굴뚝나무 목장조합의 귀중한 자산이지. 멧젠을 납치해 간 놈들에게서 몸값을 요구하는 편지를 한 장도 아니고 자그마치 두 장이나 받았네. 사실, 겨울맞이 축제 선물을 준비할 시기라 우리에겐 몸값으로 낼 돈이 없어! 자네가 우리 멧젠을 구해 주게!\n\n멧젠의 편지와 쪽지를 읽어보면 그의 행방에 대한 단서를 찾을 수 있을 거야! 그를 찾으면 이 순록 가루를 뿌리게나. 우리 멧젠을 어떤 구속에서라도 풀어줄 걸세!\n\n어서 서두르라고!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n보존된 호랑가시나무"},
[79535] = {title = "바실리스크: 과연 석화를 두려워해야 하는가?", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79536] = {title = "훌륭한 도서관의 친구", objective = "기증 감사합니다. 도서관이 한층 더 풍성해졌습니다.\n\n이걸 받아 주시길.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n장화 각인술 - 주문 강화\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n주문 강화"},
[79588] = {title = "작은 앞발", objective = "신기한 물건과 장신구로 유혹하는 게 대중을 모으는 가장 기본적인 방법이죠! 좀 도와주실 수 있나요?\n\n상품으로 사용할 작은 앞발이 필요해요. 불모의 땅이나 어둠의 해안에 사는 사자들에게서 구할 수 있지요...\n\n앞발을 좀 가져오면 다크문 축제 상품권으로 바꿔 드리죠.", description = nil, progress = "신기한 물건과 장신구로 유혹하는 게 대중을 모으는 가장 기본적인 방법이죠! 좀 도와주실 수 있나요?\n\n상품으로 사용할 작은 앞발이 필요해요. 불모의 땅이나 어둠의 해안에 사는 사자들에게서 구할 수 있지요...\n\n앞발을 좀 가져오면 다크문 축제 상품권으로 바꿔 드리죠.", completion = "좋아요, 앞발을 가져왔군요! 이걸로 장난감과 인형을 만들어서 더 많은 사람을 축제에 모을 수 있을 거예요!\n\n일을 해 주셨으니 보답으로 이 상품권을 받으세요, &lt;name&gt; 님!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[79589] = {title = "찢어진 곰 모피", objective = "아이들은 장난감을 정말 좋아하죠! 종족이 어떻든 모든 아이들은 찢어진 곰 모피로 만든 털 많고 화려한 장난감을 좋아한다는 걸 알게 됐어요!\n\n잿빛 골짜기나 힐스브래드 구릉지에 사는 곰에게서 그 모피를 구할 수 있지요. 모피 뭉치를 가져오면 다크문 축제 상품권 뭉치로 교환해 드리죠!", description = nil, progress = "아이들은 장난감을 정말 좋아하죠! 종족이 어떻든 모든 아이들은 찢어진 곰 모피로 만든 털 많고 화려한 장난감을 좋아한다는 걸 알게 됐어요!\n\n잿빛 골짜기나 힐스브래드 구릉지에 사는 곰에게서 그 모피를 구할 수 있지요. 모피 뭉치를 가져오면 다크문 축제 상품권 뭉치로 교환해 드리죠!", completion = "멋진 모피군요! 누굴 시켜서 이 모피를 바느질해 화려한 장난감을 많이 만들도록 할 거예요. 약간의 장식과 색칠을 더하면 아제로스의 모든 아이들이 갖고 싶어하는 장난감이 될 거예요!\n\n상품권이요? 아 물론, 드려야죠. 자, 여기 있어요!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[79590] = {title = "단단한 연마석", objective = "근육 단련을 위해서 단단한 연마석을 막대 양쪽에 끼운 다음 머리 위로 들어 올리는 역도를 할 생각이에요. 쉽지는 않지만 나처럼 세상에서 가장 강한 여자가 되는 건 가만히 앉아 있어서 될 일이 아니거든요!\n\n좀 도와주시겠어요? 연마석을 좀 가져오시면 다크문 축제 상품권과 바꿔 드릴게요.", description = nil, progress = "근육 단련을 위해서 단단한 연마석을 막대 양쪽에 끼운 다음 머리 위로 들어 올리는 역도를 할 생각이에요. 쉽지는 않지만 나처럼 세상에서 가장 강한 여자가 되는 건 가만히 앉아 있어서 될 일이 아니거든요!\n\n좀 도와주시겠어요? 연마석을 좀 가져오시면 다크문 축제 상품권과 바꿔 드릴게요.", completion = "연마석을 가져오셨군요! 게다가 아주 단단하네요! 보기만 해도 근육에 힘이 불끈 솟는 것 같군요. 고마워요, &lt;name&gt; 님!\n\n자, 이 상품권을 받으세요. 하지만 유랑단을 둘러보시다가 단 음식을 너무 많이 먹지 않도록 하세요. 당신처럼 크고 강한 &lt;class&gt;|1이라면;라면; 스스로 언제든지 싸울 수 있는 몸 상태를 유지해야 한다고요!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[79591] = {title = "청동 회전 장치", objective = "이번에 새로 꾸밀 내 전시장은 정말 볼 만할 걸세! 몇몇 운 좋은 사람들은 눈으로 보는 것뿐 아니라... 직접 만져 볼 수도 있지!\n\n손님들이 내 전시장에 들어와서 실력을 테스트해 볼 때 청동 회전 장치가 기계적인 환희의 노래를 부르게 된다네. 아, 벌써 그 소리가 들리는 듯하군!\n\n아 그런데... 이제 내가 구상한 대로 꾸미려면 바로 그 청동 회전 장치가 필요하다네. <name>, 제발 청동 회전 장치 좀 구해다 주게. 그러면 다크문 축제 상품권을 주겠네!", description = nil, progress = "이번에 새로 꾸밀 내 전시장은 정말 볼 만할 걸세! 몇몇 운 좋은 사람들은 눈으로 보는 것뿐 아니라... 직접 만져 볼 수도 있지!\n\n손님들이 내 전시장에 들어와서 실력을 테스트해 볼 때 청동 회전 장치가 기계적인 환희의 노래를 부르게 된다네. 아, 벌써 그 소리가 들리는 듯하군!\n\n아 그런데... 이제 내가 구상한 대로 꾸미려면 바로 그 청동 회전 장치가 필요하다네. <name>, 제발 청동 회전 장치 좀 구해다 주게. 그러면 다크문 축제 상품권을 주겠네!", completion = "장치를 가져왔군! 대단해! 벌써 내 마음에는 회전 장치가 내는 합창 소리가 들리는 것 같군! 아, 이 전시장이 완성되면 세계에서 가장 놀랍고 멋진 것이 될 거야. 두고 보라고!\n\n여기 상품권을 받게나, &lt;name&gt;. 그리고 우리 유랑단이 벌이는 축제에서 즐거운 시간 보내게!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[79592] = {title = "축제용 웃옷", objective = "우리 유랑단 일꾼들은 쓰레기 치우고 못을 박는 일 말고도 더 많은 일을 하고 있지! 축제가 이동할 때 경비병 역할을 담당하기 때문에 항상 튼튼하고 좋은 갑옷 웃옷이 필요하지.\n\n질긴 가죽 갑옷을 몇 벌 만들어 내게 가져오면 꼭 필요한 사람들에게 전해 주리다. 또 그 대가로 다크문 축제 상품권을 몇 장 주겠소.", description = nil, progress = "우리 유랑단 일꾼들은 쓰레기 치우고 못을 박는 일 말고도 더 많은 일을 하고 있지! 축제가 이동할 때 경비병 역할을 담당하기 때문에 항상 튼튼하고 좋은 갑옷 웃옷이 필요하지.\n\n질긴 가죽 갑옷을 몇 벌 만들어 내게 가져오면 꼭 필요한 사람들에게 전해 주리다. 또 그 대가로 다크문 축제 상품권을 몇 장 주겠소.", completion = "아, 가져왔구만! 혹시 어떤 동물의 가죽으로 만들었는지 물어봐도 되겠소? 바느질도 아주 잘되어 있고 가죽의 질감도 옹골차군. 당신, 솜씨가 정말 대단하군!\n\n고맙소, &lt;name&gt;. 자, 상품권을 받으시오.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[79593] = {title = "일반 무게추", objective = "이 세상에서 가장 힘센 여자가 되려면 부단한 노력을 기울여야 해요! 요즘 제 운동기구들이 너무 가벼워지고 있는데 적합한 상태를 유지하려면 무게를 좀 더 늘려야 되겠어요!\n\n혹시 무게 추를 좀 구해다 주실 수 있겠어요? 그래 주시면 다크문 축제 상품권을 하나 드릴게요.", description = nil, progress = "이 세상에서 가장 힘센 여자가 되려면 부단한 노력을 기울여야 해요! 요즘 제 운동기구들이 너무 가벼워지고 있는데 적합한 상태를 유지하려면 무게를 좀 더 늘려야 되겠어요!\n\n혹시 무게 추를 좀 구해다 주실 수 있겠어요? 그래 주시면 다크문 축제 상품권을 하나 드릴게요.", completion = "좋아요! 이거면 딱 좋네요! 너무 무겁지도 않고, 그렇다고 너무 가볍지도 않고, 근육을 단련하는 데는 최고군요!\n\n정말 고마워요, &lt;name&gt; 님. 자, 다크문 축제 상품권을 받으세요!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[79594] = {title = "구리 변조기", objective = "예브는 별난 동물원에 손님들을 끌어모을 무언가를 만들고 있지. 무언가 신기하고 마음을 즐겁게 만들어 줄 새로운 볼거리를 말이지! 하지만 그러려면 많은 수고와 다양한 재료가 필요하지...\n\n필요한 것 중 하나가 구리 변조기야. 새로 개발 중인 것의 기계적인 부분을 처리하기 위해서는 변조기가 많이 필요하지. 구리 변조기를 가져오면 다크문 축제 상품권과 바꿔 주도록 함세.", description = nil, progress = "예브는 별난 동물원에 손님들을 끌어모을 무언가를 만들고 있지. 무언가 신기하고 마음을 즐겁게 만들어 줄 새로운 볼거리를 말이지! 하지만 그러려면 많은 수고와 다양한 재료가 필요하지...\n\n필요한 것 중 하나가 구리 변조기야. 새로 개발 중인 것의 기계적인 부분을 처리하기 위해서는 변조기가 많이 필요하지. 구리 변조기를 가져오면 다크문 축제 상품권과 바꿔 주도록 함세.", completion = "하하! 변조기를 가져왔군! 아주 좋아!\n\n지금 우리가 무엇을 만들고 있는지 정확히 말해 줄 수는 없지만 어쨌든 이 구리 변조기는 꼭 필요한 물건일세. &lt;name&gt; 자네에게 신세를 졌군. 이 다크문 축제 상품권을 내 감사의 표시로 받아 주게.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[79595] = {title = "축제용 장화", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[79626] = {title = "자동 수습기 9000", objective = "자동 수습기 9000에 꼬질꼬질한 인양품을 넣어야 합니다. 30실버를 투입하면 작동할 것입니다.", description = "<이 장치는 아슬아슬하게 동력을 공급받는 상태로 보입니다. 부착된 작은 명판에는 \"자동 수습기 9000\"이라고 새겨져 있고, 그 옆에도 글귀가 들어가 있으나 오물이 두껍게 쌓여 알아볼 수 없습니다. 기계에는 커다란 투입구와 동전을 넣는 구멍이 나 있습니다.>", progress = "<수리 상태가 심히 좋지 않은 기계입니다. 그래도 꼬질꼬질한 인양품을 넣을 수 있을 것 같긴 합니다만, 넣었을 때 무슨 일이 일어날지 짐작조차 가질 않습니다.>", completion = "&lt;당신은 자동 수습기 9000에 꼬질꼬질한 인양품과 30실버를 넣었습니다. 순간 기계가 불이 들어오더니, 덜덜 흔들리다 여전히 꼬질꼬질한 인양품을 내뱉고는 침묵에 빠집니다. 망가진 것 같습니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n꼬질꼬질한 인양품"},
[79637] = {title = "들썩거리는 선물상자", objective = "굴뚝나무 목장조합에서 당신의 친구가 보냅니다. 부디 흥겨운 콧노래가 절로 나는 겨울맞이 축제 보내세요!다음과 같은 것들을 받습니다:\n\n", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n들썩거리는 선물상자"},
[79677] = {title = "빠른 장보기", objective = "스콩크의 요리에 필요한 재료를 모은 뒤, 아라시 고원에 있는 스콩크에게 가져가야 합니다.", description = "다른 오우거들 스콩크 작다고 비웃는다. 작은 오우거 약하다고 해서 스콩크 싸움 대신 요리 배웠다. 하지만 놀림만 더 받았다. 스콩크 꿈 좇으려고 도망쳐 나왔다.\n\n스콩크 요리 만들 줄 안다. 하지만 재료가 없다. 어디서 구할 수 있는지도 모른다. 스콩크는 요리 기술에 집중했지 재료 구하고 그런 건 신경 안 썼다.", progress = "재료 구해왔나? 곧 저녁 시간이다.", completion = "수고 많았다, &lt;race&gt; 친구. 우리 이제 요리할 수 있다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79678] = {title = "시식회", objective = "스콩크와 함께 조리법으로 만든 요리를 시식해야 합니다.", description = "자, <race> 친구. 스콩크가 가장 좋아하는 시간이다. 스콩크가 불 뜨겁게 피워놨다. 새로 사귄 친구에게 새로운 요리를 선보이고 싶다. 스콩크 큰 은혜 입었다. 그러니까 네가 받는 게 맞다!\n\n시식할 준비가 끝나면 스콩크한테 말해라.", progress = nil, completion = "으음! 이 요리 맛있다!\n\n스콩크 중간에 열정에 취했는데, 네가 잘 도와줬다! \n\n자, 이거 친구 몫이다. 수고비로 조금 더 챙겨 넣었다.", rewards = "다음과 같은 것들을 받습니다:\n\n쇼마겟돈피 분출의 룬"},
[79704] = {title = "자동 수습기 9000", objective = "자동 수습기 9000에 꼬질꼬질한 인양품을 넣어야 합니다. 3실버를 투입하면 작동할 것입니다.", description = "인양품을 기계에 넣고 환상적인 보상을 받으세요! 아마... 뭐가 나오긴 할걸요?", progress = "<기계가 덜컹거리며 떨리기 시작하더니, 곧이어 재활용 부품 더미를 뱉어냅니다.>", completion = "꼬질꼬질한 물건과 3실버를 삐까뻔쩍세척기 5200에 넣습니다. 장치가 요동치기 시작하면서 중심부에서 요란하고 시끄러운 소리가 들려옵니다. 물건에서 찌꺼기를 닦아내는 것 같습니다. 장치가 좌우로 흔들리면서 내부의 금속 구조물들이 서로 부딪히며 삐걱거리는 소리가 납니다.", rewards = "다음과 같은 것들을 받습니다:\n\n놈리건 인양품 상자"},
[79705] = {title = "수습기를 수습하는 방법", objective = "\"스패너\" 지리에게 미스릴 주괴 10개, 상급 신비의 정수 5개, GG12-082 카트리지 퓨즈 3개, 온전한 G-7 핵.심. 연산 장치를 전달하면 자동 수습기 9000을 고쳐줄 것입니다. 아마도요. 가능은 할 겁니다.", description = "수명이 다 된 것 같네요. 고치려면 고칠 수 있겠지만, 쉽진 않을 거예요. 저렴하지도... 않을 거고요. 이렇게 하죠. 미스릴 주괴 10개, 상급 신비의 정수 5개, GG12-082 카트리지 퓨즈 3개, 온전한 G-7 핵.심. 연산 장치를 구해다 주시면 고쳐드릴게요. 카트리지 퓨즈는 놈리건에 차고 넘치는데, 연산 핵 이건 보통 구하기 힘든 물건이 아니에요. 뭐, 재주는 많은 분 같으니 어찌어찌 찾아오실 것 같기도 하지만요. 행운을 빌어요!", progress = "와, 그 많은 물건을 진짜 다 구해왔어요? 그냥 한번 질러본 건데... 뭐, 그래도 제가 약속은 무조건 지키는 노움이거든요. 귀한 재료를 낭비할 생각도 없고요. 그거 몇 개 이리 줘보세요. 이 녀석을 순식간에 고쳐드리죠!", completion = "약속한 대로 자동 수습기 9000 수리를 끝냈어요. 혹시 좋은 물건이라도 나오면 저한테 가져오세요. 적당한 값에 이런저런 재주를 가르쳐드릴 테니까!\n\n&lt;활짝 웃으며 뒷주머니에 무언가를 찔러 넣는 지리&gt;", rewards = nil},
[79731] = {title = "트롤 두루마리", objective = "두루마리의 수수께끼를 풀어야 합니다. 수수께끼를 푼 다음에는 헤멧 네싱워리에게 이야기를 들려줘야 합니다.", description = "<당신의 눈 앞에서 글을 이루는 고대의 형상문자>\n\n줄쿤다 분수대에 신성한 샘물이 흐를 때면 신들이 축복을 내려주곤 했습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79947] = {title = "흙점술: 냉혹한 진실", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79948] = {title = "방어 마법의 기초", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79949] = {title = "거짓의 그물: 신화와 전설의 실체", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79950] = {title = "악마와 나", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79951] = {title = "미라: 불쾌한 언데드 안내서", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79952] = {title = "옳옳옳옳!", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79953] = {title = "루디트의 악마 소환수 관리법", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
[79974] = {title = "손 더럽히는 일", objective = "땅에 떨어져 있던 배낭에 묻은 흙을 털어낸 뒤 내부를 살펴보자, 여러 보급품과 양피지가 들어 있습니다.", description = "언제 급히 도망칠 일이 생길지 모르니 근처에 은닉처를 마련해 두면 쓸 만하죠.\n\n이쪽 산맥은 참 아름답습니다. 세월의 폭포를 깎아서 만든 조각 작품 같다고나 할까요. \n저게 당신이 찾던 독수리 둥지입니다.", progress = nil, completion = "&lt;드워프 기계공학은 언제 봐도 놀랍습니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n히코리 담뱃대럼지 럼주 라이트"},
[79975] = {title = "독수리의 주먹", objective = "<분사되는 물이 공기를 습하게 만들자 장관이 펼쳐집니다.>", description = "<연장통 안에 고이 접은 편지가 들어 있습니다. 당신은 목소리를 상상하며 편지를 읽어 내려갑니다. \"이제부터는 알맞은 도구를 갖고 직접 판단해야 한다. 낙하산 활공기를 사용하기에 딱 좋은 장소잖아?\n\n내가 독수리와 주먹을 제대로 섬기려면 어느 정도 거리를 두는 게 최선이었다. 이 방벽은 저 옛날 왕국처럼 낡을 대로 낡았지만, 그래도 절대 버리지 않을 거다.\">", progress = nil, completion = "&lt;땔감을 넣은 지 얼마 안 된 모닥불입니다. 흔적을 보니 황급히 짐을 챙겨 떠난 것 같습니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[79976] = {title = "여기가 분명해", objective = "<누군지 몰라도 간발의 차로 놓친 듯합니다.>", description = "<\"그래서 연구를 지하에서 이어 나가기로 했다. 악인의 손에 들어가게 둘 순 없으니까.\"\n\n딱 전언을 써넣을 수 있을 정도의 크기로 뜯어낸 종이입니다. 이게 이 글을 쓴 사람의 유언일지, 아니면 다음 은신처로 이어지는 단서일지는 좀처럼 확신이 서지 않습니다. 이때 제대로 포개지 않은 침낭이 당신의 발치에 부딪혀 펼쳐집니다...>", progress = nil, completion = "&lt;각종 장비가 방수포에 돌돌 말려 있습니다. 당신은 꾸러미를 살핍니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n아늑한 침낭학생 간식"},
[79980] = {title = "허겁지겁", objective = "무엇이 기다리는지 알아내야 합니다.", description = "<제법 괜찮지? 이 글을 읽고 있다면 내 은닉처는 아직 멀쩡하단 뜻이야. 북쪽으로 백 걸음만 가봐. 가파른 절벽이니 발목 접질리지 않게 조심하고. 당분간 쓸 정도는 들어 있을 거다.>", progress = nil, completion = "&lt;당신은 땅에 떨어진 배낭을 들어 올립니다. 배낭에 온갖 보급품과 지저분한 양피지가 들어 있습니다.&gt;", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n은색 표창달빛 라이플백발백중 활\n\n다음과 같은 것들 또한 받습니다:\n\n깃 달린 화살폭발 탄환학생 간식"},
[79981] = {title = "부식된 핵", objective = "부식된 G-7 핵.심. 연산 장치를 수리할 수 있는 사람을 찾아야 합니다.", description = "<지리에게 들은 설명과 완벽하게 일치하는 핵.심. 장치입니다. 문제는 손상이 심각한 데다 오물로 뒤덮여 있다는 점이지요. 빛바랜 표를 보니 일종의 품질 보증 관련 정보임을 알 수 있습니다. 알아볼 수 있는 글자는 몇 개가 전부입니다. \n\n\"보증... 제한... 위... 르...\">", progress = "누가 인적이 드문 첨탑 꼭대기에 탑하고 작업장을 마련해 놨으면 그게 무슨 의미겠어요? 뜻밖의 불청객은 사절한다는 의미죠. 이게 그렇게 알기 어렵나?", completion = "&lt;위르달의 확대 고글이 낮은 기계음을 내면서 당신의 손에 놓인 부식된 G-7 핵.심. 처리 장치를 유심히 살핍니다.&gt; 확실히 제 작품은 맞네요. \n\n그거 그냥 바다에 던지고 두 번 다시는 떠올리지 마세요.", rewards = nil},
[79982] = {title = "품질 보증", objective = "위르달 원더기어에게 충전된 공허핵을 가져가야 합니다.", description = "처리 장치를 고쳐드릴 순 있는데, 구하기 어려운 재료가 필요해요. 충전된 공허핵이라고. 나가 마술사들이 갖고 다닌다는데 정작 그 나가들이 어떻게 공허핵을 만드는지, 어디서 구해오는지는 모릅니다. 마법이나 의식에 강력한 집중 장치로 사용하는 듯하더군요. G-7 핵.심. 처리 장치의 중심이 되는 부품이에요. 흔하진 않으니 찾기까지 좀 시간이 걸릴 겁니다.", progress = "이거 찾겠다고 얼마나 많은 나가를 잡았을지 생각해 보면 소름이 돋네요.", completion = "어디 봅시다. \n\n미리 고지하겠는데, 이 처리 장치 설치 및 사용으로 인한 전기 화재나 전자기 파동 방출, 악마 현신, 다차원 소용돌이가 발생할 경우 저는 어떠한 책임도 지지 않으니 그리 알아두세요.", rewards = "다음과 같은 것들을 받습니다:\n\n온전한 G-7 핵.심. 처리 장치"},
[79984] = {title = "사각 측량", objective = "위르달 원더기어의 사각 측량 신호기를 찾아 조율해야 합니다. 총 네 개의 신호기가 칼림도어 어딘가에 흩어져 있습니다.", description = "위르달? 들어본 적 있지. 노움인데 같은 순간이동의 세계를 탐구하는 연구자로서 악감정을 같은 게 있진 않아. 몇 달 전쯤인가 칼림도어로 돌아갔다고. 어쩌다 한 번씩 순간이동으로 넘어와서 보급품을 챙겨 가긴 하지만 말이야. 내가 순간이동 장치로 보내줄 순 있는데, 위르달이 어딨는지 좌표를 모르면 웬 산이나 이상한 데 처박히고 말 거야. 칼림도어에 있는 그 친구 사각 측량 신호기를 찾아서 조율하면 되겠다!", progress = nil, completion = "우와, 그걸 다 찾았네. 잠깐만 기다려 봐. 좌표를 입력한 다음에 응답기를 조정하고...\n\n...다 됐다! 이거면 될 거야.", rewards = nil},
[79985] = {title = "곤경에 빠진 케르노비", objective = "태엽장치 통로 입구까지 케르노비를 호위한 후 무법항에 있는 스쿠티에게 가서 보고해야 합니다.", description = "<신음하는 케르노비> 어... 어떻게 된 거죠?\n\n마지막으로 기억나는 건 검은무쇠단 드워프들에게 붙잡혀 거의 죽을 만큼 얻어맞고, 여기 이 더러운 트로그놈들 무리에 내동댕이쳐진 것뿐인데...\n\n제발 여기서 빠져나가게 도와주세요!\n\n이렇게 하죠. 출구로 절 데려다 주세요. 그리고 출구까지 살아나가면 무법항으로 가세요. 거기서 스쿠티를 만나 제가 톱니항의 팅커위즈에게 가더라고 전해주세요. 그 거대한 장치를 만드는 데 검은무쇠단 드워프가 관련됐다는 사실을 알려야 하거든요.\n\n어서 가죠!", progress = nil, completion = "케르노비를 무사히 구출해 준 공로에 대해 보답을 해야겠군. 놈리건으로 돌아갈 때 이걸 가져가면 그 배신자 기계박사 텔마플러그 놈을 물리치는 데 도움이 될 거요.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n용접 팔보호구요정날개 어깨보호대\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[79986] = {title = "꼬질꼬질한 반지", objective = "꼬질꼬질한 반지에서 찌꺼기를 제거할 방법을 찾아야 합니다.", description = "검은무쇠단 드워프 한 놈의 시체에서 반지처럼 보이는 것을 찾았습니다. 하지만 흙과 단단하게 굳은 찌꺼기가 완전히 뒤덮고 있어 어떤 종류의 반지인지 알아보기 어렵고 끼어 볼 수도 없습니다. 찌꺼기 밑에서 무언가 귀한 금속의 광택이 살짝 보이며 보석이 반짝이는 것 같기도 합니다.\n\n이 반지를 사용하려면 단단하게 굳은 찌꺼기를 제거해야 합니다.", progress = "앞에 있는 노움 장치에는 '빤질빤질세척기 5200'이라고 쓰인 명판이 붙어 있습니다. 그 아래 적힌 사용법을 읽어 보니 어떤 물건에 묻은 찌꺼기를 세척하는 데 쓰는 기계인 것 같습니다. 기계 안에 물건을 넣고 앞에 있는 동전 투입구에 3실버를 집어넣으니 작동하기 시작합니다.\n\n방금 전에 찾은 꼬질꼬질한 반지를 넣으면 깨끗해질 것 같습니다!", completion = "빤질빤질세척기 5200 안에 반지를 넣고 동전 투입구에 3실버를 넣습니다.\n\n심하게 흔들거리기 시작하며 삐걱거리는 소리가 새어 나와 듣기가 거북할 지경입니다. 속에 든 반지에 무슨 일이 일어나고 있을지는 아무도 모르는 일입니다.\n\n갑자기 기계가 멈추고 \"띵!\"하는 소리를 내며 종료를 알립니다. 반지를 넣었던 곳이 열리면서 깨끗이 포장되어 빨간 나비 리본까지 달린 작은 상자가 나옵니다. 빤질빤질세척기 5200은 선물 포장도 해주는가 봅니다!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치"},
[79987] = {title = "반지의 귀환", objective = "반지를 그냥 가지거나, 반지 안쪽 부분에 새겨진 인장 자국의 주인을 찾아야 합니다.", description = "빤질빤질세척기 5200에서 나온 상자를 열자 생각했던 대로 반짝이는 반지가 들어 있습니다! 반지를 끼자 마법의 힘이 몸 전체를 휩쓰는 것이 느껴집니다.\n\n반지 안쪽 면에는 아이언포지의 봉인 자국이 작지만 읽을 수 있을 정도로 깨끗이 새겨져 있습니다. 그 옆에는 '탈바쉬'라는 세 글자가 조그맣게 새겨져 있습니다. 아마 예전 주인이나 이 반지를 만든 사람의 이름인 듯합니다. 반지를 간직하거나... 이 사람에게 돌려주어야 합니다. 또다시 결정의 시간이 돌아왔습니다.", progress = "좀 진정하시라니까. 난 신용 있는 사업가란 말이오! 임대료를 부친 게 좀 지연이 되고 있을 뿐이... 잠깐, 당신은 우리 집주인이 아닌데...\n\n이런, 정말로 아니군. 내가 바보 같은 소릴 했군! 저주받은 물건 따위는 절대로 만들지 않는 아이언포지 최고의 보석 세공인을 찾아온 손님이시군그래!\n\n음... 무엇이 필요하신 게요?", completion = "반지라고 했소? 어디 봅시다... 그래, 내가 그 반지를 만들었소.\n\n놈리건이 오염되기 전에, 난 그곳에서 작은 상점을 하나 운영했었소. 아마도 그 반지는 내가 놈리건에서 도망치다가 두고 나온 것일 거요. 단순한 디자인의 반지인데 똑같은 것을 여러 개 만들었소. 이건 놈리건을 미처 탈출하지 못한 노움의 것일 거요.\n\n검은무쇠단 &lt;race&gt;의 주머니에서 찾았다고? 흐음, 그렇다면 이 음모를 둘러싸고 있는 9개의 단서에 새로운 단서가 추가겠군. 아마도 당국에선 관심 있어 할 것이오. 이런 얘길 해 봤자 시간 낭비일 뿐이겠지.\n\n자, 그럼 반지 얘기로 돌아가서...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[79990] = {title = "가시덤불 골짜기 목재", objective = "하사관 매클리어에게 가시덤불 골짜기 목재 화물을 전달해야 합니다.", description = "아라시 분지에서 목표를 달성하기 위해서는 추가 자원과 지원이 절실한 상황이에요. 특히 쓸 만한 목재를 조달하지 못한 바람에 가시덤불 골짜기까지 가서 부족분을 충당하는 상황이죠. 가시덤불 골짜기 목재 화물을 가져다주면 이 빚은 절대 잊지 않을게요.", progress = "새로운 물자를 가져오셨나요?", completion = "고맙습니다, &lt;class&gt;님. 이 정도면 아라시 분지의 전세를 뒤집는 데 도움이 될 겁니다.", rewards = nil},
[79991] = {title = "가시덤불 골짜기 목재", objective = "죽음추적자 몰티스에게 가시덤불 골짜기 목재 화물을 전달해야 합니다.", description = "아라시 분지에서 목표를 달성하기 위해서는 추가 자원과 지원이 절실한 상황이네. 특히 쓸 만한 목재를 조달하지 못한 바람에 가시덤불 골짜기까지 가서 부족분을 충당하고 있지. 가시덤불 골짜기 목재 화물을 가져다주면 이 빚은 절대 잊지 않겠네.", progress = "새로운 물자를 가져왔나?", completion = "고맙네, &lt;class&gt; 친구. 이 정도면 아라시 분지의 전세를 뒤집는 데 도움이 될 걸세.", rewards = nil},
[80001] = {title = "재점화", objective = "<다 꺼진 화덕입니다. 나무가 잘 말라 있어 다시 불을 지필 수 있을 듯합니다.>", description = nil, progress = "<다 꺼진 화덕입니다. 나무가 잘 말라 있어 다시 불을 지필 수 있을 듯합니다.>", completion = "&lt;그간 쌓은 생존 기술을 발휘합니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n부싯돌과 불쏘시개"},
[80098] = {title = "희한한 달라란 유물", objective = "도둑맞은 유물을 회수하셨습니까?", description = nil, progress = "도둑맞은 유물을 회수하셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 이 물건은 제가 책임지고 달라란에 반환하겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[80120] = {title = "달라란 지원", objective = "달라란과 아제로스가 모험가님께 큰 은혜를 입었습니다.\n\n달라란의 비밀을 외부인에게 알리는 건 불법이라 말씀드릴 수 없지만, 그래도 규칙을 살짝 우회해서 보상을 드리는 건 가능합니다. 부디 받아주시길.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n보급품 자루"},
[80131] = {title = "노움의 실력 향상", objective = "아이언포지에 있는 탈바쉬 델 키젤에게 은괴 1개, 태마노 1개와 반짝이는 금반지와 30실버를 주어야 합니다.", description = "내 말 좀 들어 보시오. 그 반지야 당연히 당신 게 맞겠지만, 내가 훨씬 더 멋지게 만들어 줄 수 있다오! 디자인이 너무 단순하지 않소? 이젠 나도 솜씨가 많이 늘었으니까... 30실버만 주면 반지를 더 멋지게 만들어주겠소! 솔직히... 30실버면 너무 싸지.\n\n그런데 요즘 사정이 좋질 않아서 재고가 모두 바닥나 버렸다오. 내게 은괴 1개와 태마노 1개만 가져다주면 반지에 격자 모양의 은과 태마노를 붙여서 세공을 좀 더 화려하게 해주겠소!\n\n한번 믿어보시오!", progress = "내가 말한 재료는 가져왔소? 내 주머니 사정이 조금만 나았어도 당신에게 그런 부탁을 하지는 않았을 텐데...", completion = "아, 필요한 재료를 모두 찾아왔군! 억울한 이 난관을 벗어나면 언젠가 당신과 세상 모든 이들을 위해 아제로스에서 가장 훌륭한 장신구를 만들어 주겠소! 아무튼 고맙소. 이 정도 반지라면 당신에게 부른 것보다 열 배는 비싸야 제 값이지만...\n\n아, 반지 말인데, 여기 새 걸로 만들었소!", rewards = "다음과 같은 것들을 받습니다:\n\n탈바쉬의 반짝이는 금반지"},
[80132] = {title = "기술 전쟁", objective = "놈리건에서 장치 설계도와 텔마플러그의 금고 암호를 찾아서 오그리마에 있는 노그에게 가져다주어야 합니다.", description = "노움의 기술이라... 2년 전만 해도 농담으로나 하던 소리였는데... 시대가 많이 변했죠. 이제 노움은 우리 벌목기를 다 모은 것보다 더 좋은 장비를 가지고 있어요. 녀석들의 설계도가 필요해요!\n\n유감스럽게 그 설계도는 금고에 보관되어 있는데 기계박사 텔마플러그가 항상 근처를 지키고 있어요. 게다가 그만이 금고 암호를 알고 있답니다.\n\n무슨 수를 써서라도 금고 번호를 알아내세요. 번호를 알아내면 금고를 열고 설계도를 가져오세요!", progress = "설계도는 안 보이는데? 몸에다 숨긴 건가요, 아니면 날 짜증 나게 하려고 꾸물거리는 건가요?", completion = "&lt;name&gt;, 당신이라면 해낼 줄 알았어요! 소빅은 미심쩍어 했지만 말이죠.\n\n\n\n이제 설계도를 손에 넣었으니 장치 제작에 사용된 노움의 기술을 알아내는 건 시간문제예요. 그걸 우리 고블린 기술에 접목하면 혁신적인 벌목기를 만들 수 있겠죠!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n온전한 선민의 로브민첩한 출장용 작업복삼중 강화 다리보호구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[80133] = {title = "선임기술자 스쿠티", objective = "무법항에 있는 스쿠티와 대화해야 합니다.", description = "케르노비에게서 새 노움 장치에 대한 소식을 듣자마자 스쿠티와 나는 순간이동기 6000을 만들기 시작했습니다. 순간이동기 6000은 가장 빠르고 안전하게 놈리건에 가는 방법이랍니다.\n\n드디어 승객들을 태울 준비가 됐군요. 한번 타보고 싶으시다면 무법항으로 가서 와이번 횃대에 있는 스쿠티와 얘기를 나눠보시기 바랍니다. 무법항으로 가려면 톱니항에서 배를 타야 한답니다.\n\n물론 드워프가 득실거리는 던 모로의 산맥을 지나서 놈리건까지 뛰어가도 상관없지만요!", progress = nil, completion = "아주 멋진 장치지 않소? 아직 열두 번밖에 폭발한 적이 없는 고블린 순간이동 기술의 최고봉이라오.\n\n내가 다 고쳐놓았으니까 걱정 마시오. 당신이 탔을 때는 폭발하진 않을 거요. 혹시 폭발하더라도 순식간에 고통 없이 끝날 거라오.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[80134] = {title = "놈리거어어어언!", objective = "스쿠티가 고블린 응답장치를 조절하는 동안 기다려야 합니다.", description = "응답장치를 갖고 발판에 올라서는 즉시 놈리건으로 이동하게 될 거요.\n\n부작용이 좀 생기겠지만 영구적인 것은 아니오.\n\n아, 제일 중요한 걸 잊을 뻔했군. 귀환 말인데 돌아오려면 놈리건에 있는 순간이동기 발판에 올라서면 되지.\n\n이제 응답장치를 당신의 키와 체중에 맞게 조절하겠소.", progress = nil, completion = "모두 끝났소! 떠날 준비가 되거든 발판 위에 올라서시오.", rewards = "다음과 같은 것들을 받습니다:\n\n고블린 응답장치"},
[80135] = {title = "클락몰트에게 꼭 필요한 것", objective = "아이언포지에 있는 클락몰트 스패너스판과 대화해야 합니다.", description = "내 노움 친구, 클락몰트 스패너스판이 아이언포지에서 소식을 전해 왔소. 극히 중요한 임무를 수행하기 위해 놈리건으로 위험을 무릎 쓰고 떠나는데 도움이 필요하다는 거요. 놈리건은 한때 위대한 노움 도시였지만 지금은 오염되어 버렸고 제정신이 아닌 노움들과 여러 가지 기괴한 장치들로 가득 차 있소.\n\n나는 이곳을 떠날 수 없지만 내 친구를 꼭 도와 주고 싶소. 당신이 나 대신 가 준다면 정말로 고맙겠소.\n\n클락몰트는 아이언포지의 땜장이 마을에 있소.", progress = nil, completion = "그래요! 중대한 임무를 수행하기 위해 놈리건으로 떠나는데 도움이 필요해요! 당신 같은 &lt;class&gt;|1이라면;라면; 아주 딱이죠!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[80136] = {title = "필수 인공장치", objective = "아이언포지에 있는 클락몰트 스패너스판에게 필수 인공장치 12개를 가져가야 합니다.", description = "필수 인공장치라는 부품은 다양한 곳에 두루 사용되기 때문에 놈리건 땜장이와 대장장이들에게는 없어서는 안 될 물건이죠. 그런데 고향에서 정신 없이 탈출해 나올 때 모두 깜박 잊고 그 장치들을 놓고 나온 거예요! 곧 착수해야 하는 일에 그 장치가 많이 필요하답니다.\n\n제발 부탁이에요. 놈리건으로 가서 필수 인공장치를 좀 가져다주세요. 깊숙이 들어가면 인공장치 검출기라는 것에서 꺼낼 수 있을 거예요.\n\n부디 서둘러 주세요. 도움을 주시면 감사하겠어요!", progress = "필수 인공장치를 가져왔나요?", completion = "가져왔군요! 이제 새로운 실험을 시작할 수 있게 됐어요!\n\n뭐라고 감사의 말을 해야 할지 모르겠네요! 예부터 당신과 같이 용감한 분의 도움이 있었기에 노움의 연구도 이만큼 진척된 것이랍니다!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[80137] = {title = "고장난 첨단로봇 수리", objective = "아이언포지에 있는 수석땜장이 오버스파크에게 첨단로봇의 기억회로를 가져가야 합니다.", description = "우리가 사랑했던 도시 놈리건이 무너졌을 때, 불행하게도 내가 만든 첨단로봇이 전기 불꽃에 맞아 충격을 입은 모양이오. 한때 수많은 장치와 무제한의 저장 공간으로 우리를 도왔는데 지금은 녀석의 양전자 두뇌가 분극화된 모양이오. 이제는 음전자 성질을 띠어... 첨단로봇의 행동이 완전히 거꾸로 바뀌어 버린 거요. 녀석은 놈리건에서 광포한 행동을 일삼으며 돌아다니고 있소이다!\n\n하지만 녀석을 구할 수 있을지도 모르오. 당신이 첨단로봇의 기억회로를 내게 가져오면 그 분극 작용의 원인을 알아내서 불쌍한 첨단로봇을 고칠 수 있을지도 모르오.\n\n", progress = "첨단로봇은 찾았소? 기억회로는 어떻게 됐소??", completion = "아, 아주 잘 됐군! 고맙소! 곧바로 작업을 시작하겠소이다!!\n\n저런, 불쌍한 첨단로봇... 조금만 참거라. 우리가 고쳐 줄 테니까 말이야.\n\n어디 보자, 유압잭 회전 고리 스패너 플러그를 어디에 뒀더라...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[80138] = {title = "수석땜장이 오버스파크", objective = "아이언포지에 있는 수석땜장이 오버스파크와 대화해야 합니다.", description = "수석땜장이 오버스파크가 자신이 만든 첨단로봇 때문에 매우 속상해 하고 있소. 내가 기억하기로 첨단로봇은 노움들에게 아주 쓸모 있는 도구였던 것 같은데 오버스파크 얘기로는 그 로봇이 완전히 고장났다고 하더구먼.\n\n아주 슬픈 일이야. 하지만 재수가 좋으면 고칠 수 있을지도 모르지!\n\n아이언포지의 땜장이 마을에 있는 수석땜장이 오버스파크와 얘기해 보시오. 당신을 아주 반길 거요.", progress = nil, completion = "사실이오. 첨단로봇이 말썽을 부리고 있다니까! 나 좀 도와 주지 않겠소?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[80139] = {title = "폐기물 수집", objective = "빈 가연채집병에 오염된 침략꾼이나 오염된 약탈자에게서 얻은 방사성 폐기물을 담아야 합니다. 채집병이 가득 차면 카라노스에 있는 오지 토글볼트에게 가지고 가야 합니다.", description = "그 사고가 난 뒤부터 노아른은 놈리건에 남아 있는 트로그 녀석들을 쫓아내고 그곳에 퍼진 질병을 치료할 방법을 찾는 데만 온 신경이 쏠려 있소.\n\n다행히도 라즐과 내가 치료약 비슷한 걸 만들어 냈지. 잘 되면 치료약이 될 테고 못해도 독한 럼주가 되는 액체인데 실험을 해보기 전까지는 아무것도 알 수 없소! 따라서 우리 가설을 확인해보려면 몇 가지 물건이 필요하오. 우선 놈리건에 있는 오염된 트로그들에게서 녹색 방사성 폐기물을 채취해 이 병에 채워다 주시오!", progress = "노움족 전체를 치료할 비약을 만들고 있는 게 안 보이는 거요?? 그 녹색 폐기물이 꼭 필요하단 말이오!", completion = "잘했소! 새 약품을 시험해볼 때가 되었군. 성공하기만 하면 여기 사로잡힌 오염된 노움을 치료할 수 있을 뿐만 아니라 내 대머리 증세도 치료할 수 있소! 물러서 있으시오!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[80140] = {title = "반지의 귀환", objective = "반지를 그냥 가지거나, 반지 안쪽 부분에 새겨진 인장 자국의 주인을 찾아야 합니다.", description = "빤질빤질세척기 5200에서 나온 상자를 열자, 생각했던 대로 반짝이는 반지가 들어 있습니다! 반지를 끼자 마법의 힘이 온몸을 휩쓸고 내려가는 게 느껴집니다.\n\n반지 안쪽에는 오그리마의 봉인 자국이 새겨져 있습니다. 작지만 읽을 수 있을 정도로 깨끗합니다. 그 옆에 새겨진 내용에서는 '노...'라는 맨 앞글자만 알아볼 수 있습니다.\n\n아마 예전 주인이나 이 반지를 만든 사람의 이름인 듯합니다. 반지를 간직하거나... 이름이 '노'로 시작하는 이에게 돌려주어야 합니다. 또다시 결정의 시간이 돌아왔습니다.", progress = "당신 생각은 어때요? 우리가 저 더럽고 조그만 노움들의 코를 납작하게 눌러 줄 방법을 스스로 찾을 수 있을까요? 애초에 우리에게서 그 장치를 훔쳐간 게 분명해. 틀림없다고요! 쳇! 기름투성이에 때묻은... 네? 도와드릴 일이라도 있나요?", completion = "놈리건에서 반지를요? 어디 볼까요... 아니오. 내 것은 아니지만 흥미로운 물건이군요.\n\n놈리건 말이 나왔으니 말인데, 바보 같은 노움 녀석들에게는 과분했죠. 오랫동안 장난감만 만들어대던 놈들이 갑작스레 우리보다 더 발달한 장치를 만들다니!\n\n그런데, 검은무쇠단 드워프들이 갖고 있었다고요? 흠... 점점 더 흥미가 당기는군! 어쩌면 노움 녀석들이 골렘 도안을 훔쳐서 개조를 했는지도 몰라요. 검은무쇠단 드워프들은 분명 복수를 하고 싶어할 겁니다. 음, 조사를 해 볼 만하군요.\n\n아, 물론 그... 반지에 대한 조사 말이죠.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[80141] = {title = "노그의 반지 수리", objective = "오그리마에 있는 노그에게 반짝이는 금반지, 은괴 1개, 태마노 1개, 30실버를 가져다주어야 합니다.", description = "아니, 아니, 아니, 그 반지가 내 거라고 하는 게 아니고... 보통 이런 일은 잘 하지 않지만 당신이 주신 검은무쇠단 드워프에 대한 정보가 아주 유용해서 그 보답으로 반지를 더 멋지게 만들어주려는 겁니다. 이 작고 단순한 모양의 반지를 누가 만들었는지는 모르지만 훨씬 멋지게 만들어 줄게요. 아마 노움이 만든 게 아닐까 싶지만...\n\n은괴 1개, 태마노 1개, 그리고 수고비로 30실버를 가져오면 반지에 격자 모양으로 은을 붙여 마법을 더 강화시켜 주도록 하죠. 어때요... 해보고 싶으시죠?다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n노그의 반짝이는 금반지"},
[80142] = {title = "캐스트파이프의 임무", objective = "아이언포지에 있는 수석수리공 캐스트파이프와 대화해야 합니다.아이언포지에 있는 수석수리공 캐스트파이프가 일손을 필요로 하고 있소! 극비 임무로 자료를 회수하기 위해 놈리건으로 다시 들어갈 모험가들을 모집하고 있다고 하더군.\n\n캐스트파이프는 나처럼 비전술, 연금술을 비롯해 기계공학 연구회의 회원은 아니지만, 아주 영리한 노움이라서 그가 중요하다고 하면 정말로 중요한 일일 가능성이 내 계산으로는 84%요!\n\n아주 높은 확률 아니겠소?다음 주문들이 당신에게 시전될 것입니다:\n\n", description = "아이언포지에 있는 수석수리공 캐스트파이프가 일손을 필요로 하고 있소! 극비 임무로 자료를 회수하기 위해 놈리건으로 다시 들어갈 모험가들을 모집하고 있다고 하더군.\n\n캐스트파이프는 나처럼 비전술, 연금술을 비롯해 기계공학 연구회의 회원은 아니지만, 아주 영리한 노움이라서 그가 중요하다고 하면 정말로 중요한 일일 가능성이 내 계산으로는 84%요!\n\n아주 높은 확률 아니겠소?다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[80143] = {title = "자료 회수", objective = "아이언포지에 있는 수석수리공 캐스트파이프에게 오색 천공 카드를 가져가야 합니다.", description = "놈리건에서 도망쳐 나올 때 대량의 자료를 두고 나왔다네! 굉장히 중요한 자료인데 말이야!\n\n놈리건 깊숙이 있는 행렬 천공기록기 3005-D의 고급 보안 터미널을 통해 자료를 오색 천공 카드에 담아 와야 해. 터미널에 접근하려면 보안 허가가 필요한데... 보안 허가를 받으려면 하급 보안 터미널인 모델 A, B, C에 먼저 접근해야 하지. 그리고 그 하급 터미널에 접근하려면 보안 천공 카드가 필요하고. 그 카드는 흰색인데 말이야... 놈리건에서 찾을 수 있다네.\n\n어떤가, 정말 철통 같은 보안 아닌가? 도와 줄 수 있겠나?", progress = "오색 천공 카드는 가져온 건가?", completion = "해냈군! 오색 천공 카드를 찾아서 잃어버린 자료를 회수했어! 우리 노움의 사활이 걸린 정도로 필수적이고, 중요하고, 방대한 자료를 말이야!\n\n자네가 해준 이번 일은 우리 노움의 역사에 길이 남을 것이네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n수리공의 단망토수리공의 파이프망치"},
[80147] = {title = "희한한 달라란 유물", objective = "도둑맞은 유물을 회수하셨습니까?", description = nil, progress = "도둑맞은 유물을 회수하셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 이 물건은 제가 책임지고 달라란에 반환하겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
