[81774] = {title = "잿빛 골짜기 임무 VII: 꿈의 동력장치 회수", objective = "전쟁노래부족 벌목기지에 있는 잿빛 골짜기 악몽 침공지의 가열로에서 꿈의 동력장치를 회수한 후, 야전 지휘관 한날라에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 어둠의 나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 전쟁노래부족 벌목기지에 있는 악몽 침공지에 진입하십시오. 그곳에서 꿈의 동력장치란 강력한 유물을 찾아 가져오시면 됩니다.", progress = "꿈의 동력장치는 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n임무 개요: 잿빛 골짜기"},
[81775] = {title = "잿빛 골짜기 임무 VIII: 아즈샤라의 예언 회수", objective = "사티르나르에 있는 잿빛 골짜기 악몽 침공지의 작은 천막에서 아즈샤라의 예언을 회수한 후, 야전 지휘관 한날라에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 어둠의 나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 사티르나르에 있는 악몽 침공지에 진입하십시오. 그곳에서 아즈샤라의 예언이란 잃어버린 두루마리를 찾아 가져오시면 됩니다.", progress = "아즈샤라의 예언은 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n임무 개요: 잿빛 골짜기"},
[81776] = {title = "잿빛 골짜기 임무 IX: 꿈에 물든 용의 알 회수", objective = "숲의 노래에 있는 잿빛 골짜기 악몽 침공지 중앙 폐허에서 꿈에 물든 용의 알을 회수한 후, 야전 지휘관 한날라에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 어둠의 나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 숲의 노래에 있는 악몽 침공지에 진입하십시오. 그곳에서 꿈에 물든 용의 알을 찾아 가져오시면 됩니다.", progress = "알은 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n임무 개요: 잿빛 골짜기"},
[81777] = {title = "잿빛 골짜기 임무 X: 꿈뿌리", objective = "잿빛 골짜기 악몽 침공지에서 꿈뿌리 10개를 수집한 후, 야전 지휘관 한날라에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 어둠의 나무로 향하십시오. 속히 에메랄드 꿈의 관문을 지나 악몽 침공지에서 꿈뿌리를 수집해 주시면 됩니다. 그 물건의 마력을 피해 복구에 이용할 계획입니다. 참, 약초채집사의 도움이 필요할 겁니다.", progress = "꿈뿌리는 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n임무 개요: 잿빛 골짜기"},
