[81782] = {title = "잿빛 골짜기 임무 XV: 벌목기 9000 처치", objective = "전쟁노래부족 벌목기지에 있는 잿빛 골짜기 악몽 침공지 목재 기중기에서 벌목기 9000을 처치한 후, 야전 지휘관 한날라에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 어둠의 나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 전쟁노래부족 벌목기지에 있는 악몽 침공지에 진입한 뒤, 벌목기 9000을 처치하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n임무 개요: 잿빛 골짜기"},
[81783] = {title = "잿빛 골짜기 임무 XVI: 알리시안 윈드콜러 구출", objective = "전쟁노래부족 벌목기지에 있는 잿빛 골짜기 악몽 침공지의 감시탑 밑에서 알리시안 윈드콜러를 구출한 후, 야전 지휘관 한날라에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 어둠의 나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 전쟁노래부족 벌목기지에 있는 악몽 침공지에 진입하십시오. 잠자는 발톱의 드루이드 알리시안 윈드콜러를 찾아 안전한 곳으로 호위해야 합니다. 임무를 완수하는 대로 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n임무 개요: 잿빛 골짜기"},
[81784] = {title = "잿빛 골짜기 임무 XVII: 도란 드림바우 구출", objective = "숲의 노래에 있는 잿빛 골짜기 악몽 침공지의 달빛 별채에서 도란 드림바우를 구출한 후, 야전 지휘관 한날라에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 어둠의 나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 숲의 노래에 있는 악몽 침공지에 진입하십시오. 잠자는 발톱의 드루이드 도란 드림바우를 찾아 안전한 곳으로 호위해야 합니다. 임무를 완수하는 대로 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n임무 개요: 잿빛 골짜기"},
[81785] = {title = "잿빛 골짜기 임무 XVIII: 마세라 어텀문 구출", objective = "사티르나르에 있는 잿빛 골짜기 악몽 침공지 남동쪽 천막촌에서 마세라 어텀문을 구출한 후 야전 지휘관 한날라에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 어둠의 나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 사티르나르에 있는 악몽 침공지에 진입하십시오. 잠자는 발톱의 드루이드 마세라 어텀문을 찾아 안전한 곳으로 호위해야 합니다. 임무를 완수하는 대로 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음과 같은 것들을 받습니다:\n\n임무 개요: 잿빛 골짜기"},
[81786] = {title = "동부 내륙지 임무 I: 달빛야수 처치", objective = "굼벵이 바위굴에 있는 동부 내륙지 악몽 침공지에서 타락한 달빛야수 20마리를 처치한 후 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 굼벵이 바위굴에 있는 악몽 침공지에 진입한 뒤, 달빛야수를 소탕하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81787] = {title = "동부 내륙지 임무 II: 거대 거북이 처치", objective = "샤올와타에 있는 동부 내륙지 악몽 침공지에서 꿈결물 무쇠턱 20마리를 처치한 후 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 샤올와타에 있는 악몽 침공지에 진입한 뒤, 거대 거북이를 소탕하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81788] = {title = "동부 내륙지 임무 III: 용족 처치", objective = "아골와타에 있는 동부 내륙지 악몽 침공지에서 분노의 새끼용 10마리와 고룡족 별사냥꾼 3마리를 처치한 후 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 아골와타에 있는 악몽 침공지에 진입한 뒤, 용족을 소탕하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81789] = {title = "동부 내륙지 임무 IV: 용 첩보", objective = "아골와타에 있는 동부 내륙지 악몽 침공지의 홍예길에서 꿈지기 라니나르를 만나 첩보를 받은 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 아골와타에 있는 악몽 침공지에 진입하십시오. 그곳에 있는 꿈지기 라니나르에게서 첩보 보고서를 받아 돌아오시면 됩니다.", progress = "보고서를 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81790] = {title = "중요한 재료", objective = "그레고리의 쪽지에 적힌 재료를 입수한 후 악령의 숲의 피멍울 폭포 수원지에 있는 그레고리에게 전달해야 합니다.", description = "메아리의 보주는 그 주인의 여러 양상에 맞춰 동화되어 있습니다. 다시 말해 잿빛 골짜기에서 알살락스의 보주를 파괴할 때 사용한 방법은 이번 보주에 통하지 않을 거란 뜻입니다. 보주를 파괴할 수 있도록 불안정한 상태로 만드는 의식을 알긴 합니다만, 특별한 마법의 힘을 지닌 재료가 필요합니다. 준비물 중 일부는 이미 보유 중입니다만, 나머지는 구해주셔야 할 것 같습니다. 받으세요. 물건을 찾는 데 도움이 될 겁니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[81801] = {title = "투기장 복귀전", objective = "타나리스 가젯잔에 있는 피즈버즈 미스릴에게 가야 합니다.", description = "난 한 입으로 두말하지 않소. 내 복수를 이루어주었으니 은혜를 갚으리다. 가젯잔으로 가서 피즈버즈에게 내가 돌아올 거라고 전하시오. \n\n경기장에서 만날 때를 고대하지.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[81817] = {title = "동부 내륙지 임무 V: 거북이 첩보", objective = "샤올와타에 있는 동부 내륙지 악몽 침공지의 북 뒤쪽에서 꿈지기 사나텔을 만나 첩보를 받은 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 샤올와타에 있는 악몽 침공지에 진입하십시오. 그곳에 있는 꿈지기 사나텔에게서 첩보 보고서를 받아 돌아오시면 됩니다.", progress = "보고서를 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81820] = {title = "동부 내륙지 임무 VI: 달빛야수 첩보", objective = "굼벵이 바위굴에 있는 동부 내륙지 악몽 침공지의 지하 호수에서 꿈지기 발로리를 만나 첩보를 받은 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 굼벵이 바위굴에 있는 악몽 침공지에 진입하십시오. 그곳에 있는 꿈지기 발로리에게서 첩보 보고서를 받아 돌아오시면 됩니다.", progress = "보고서를 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81826] = {title = "동부 내륙지 임무 VII: 별에 물든 용의 알 회수", objective = "아골와타에 있는 동부 내륙지 악몽 침공지의 중앙 오두막에서 별에 물든 용의 알을 회수한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 아골와타에 있는 악몽 침공지에 진입하십시오. 별에 물든 용의 알을 찾아 가져오시면 됩니다.", progress = "알은 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81830] = {title = "동부 내륙지 임무 VIII: 엘루나르 유물 회수", objective = "굼벵이 바위굴에 있는 동부 내륙지 악몽 침공지의 높은 절벽에서 엘루나르 유물을 회수한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 굼벵이 바위굴에 있는 악몽 침공지에 진입하십시오. 달빛야수들이 숨긴 엘루나르 유물을 찾아 가져오시면 됩니다.", progress = "유물은 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81832] = {title = "동부 내륙지 임무 IX: 꿈진주 회수", objective = "샤올와타에 있는 동부 내륙지 악몽 침공지의 뱀 분수대에서 꿈진주를 회수한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 샤올와타에 있는 악몽 침공지에 진입하십시오. 거북이들이 숨긴 꿈진주를 찾아 가져오시면 됩니다.", progress = "진주는 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81833] = {title = "동부 내륙지 임무 X: 별빛연꽃", objective = "동부 내륙지 악몽 침공지에서 별빛연꽃 10개를 수집한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 속히 에메랄드 꿈의 관문을 지나 악몽 침공지에서 별빛연꽃을 수집해 주시면 됩니다. 그 물건의 마력을 피해 복구에 이용할 계획입니다. 참, 약초채집사의 도움이 필요할 겁니다.", progress = "별빛연꽃은 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81834] = {title = "동부 내륙지 임무 XI: 별빛은 광석", objective = "동부 내륙지 악몽 침공지에서 별빛은 광석 10개를 수집한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 속히 에메랄드 꿈의 관문을 지나 악몽 침공지에서 별빛은 광석을 수집해 주시면 됩니다. 그 물건의 마력을 피해 복구에 이용할 계획입니다. 참, 광부의 도움이 필요할 겁니다.", progress = "별빛은 광석은 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81835] = {title = "동부 내륙지 임무 XII: 별빛껍질", objective = "동부 내륙지 악몽 침공지에서 별빛껍질 10개를 수집한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 속히 에메랄드 꿈의 관문을 지나 악몽 침공지에 있는 거대 거북이에게서 별빛껍질을 수집해 주시면 됩니다. 그 물건의 마력을 피해 복구에 이용할 계획입니다. 참, 무두장이의 도움이 필요할 겁니다.", progress = "별빛껍질은 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81837] = {title = "동부 내륙지 임무 XIII: 플로리우스 처치", objective = "아골와타에 있는 동부 내륙지 악몽 침공지의 중앙 안뜰에서 플로리우스를 처치한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 아골와타에 있는 악몽 침공지에 진입한 뒤, 용 플로리우스를 처치하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81838] = {title = "동부 내륙지 임무 XIV: 파멸의 자손 처치", objective = "굼벵이 바위굴에 있는 동부 내륙지 악몽 침공지의 깊은 절벽에서 파멸의 자손을 처치한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 굼벵이 바위굴에 있는 악몽 침공지에 진입한 뒤, 거대 달빛야수 파멸의 자손을 처치하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81839] = {title = "동부 내륙지 임무 XV: 가무라자 처치", objective = "샤올와타에 있는 동부 내륙지 악몽 침공지의 안뜰에서 가무라자를 처치한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 샤올와타에 있는 악몽 침공지에 진입한 뒤, 거북이 \"왕\" 가무라자를 처치하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81850] = {title = "동부 내륙지 임무 XVI: 엘리아나르 섀도드링커 구출", objective = "아골와타에 있는 동부 내륙지 악몽 침공지의 트롤 요새에서 엘리아나르 섀도드링커를 구출한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 아골와타에 있는 악몽 침공지에 진입하십시오. 잠자는 발톱의 드루이드 엘리아나르 섀도드링커를 찾아 안전한 곳으로 호위해야 합니다. 임무를 완수하는 대로 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81851] = {title = "동부 내륙지 임무 XVII: 세를리나 스타브라이트 구출", objective = "샤올와타에 있는 동부 내륙지 악몽 침공지의 트롤 요새에서 세를리나 스타브라이트를 구출한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 샤올와타에 있는 악몽 침공지에 진입하십시오. 잠자는 발톱의 드루이드 세를리나 스타브라이트를 찾아 안전한 곳으로 호위해야 합니다. 임무를 완수하는 대로 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81852] = {title = "동부 내륙지 임무 XVIII: 베아나 클라우드슬리퍼 구출", objective = "굼벵이 바위굴에 있는 동부 내륙지 악몽 침공지의 높은 그물 침대에서 베아나 클라우드슬리퍼를 구출한 후, 야전 지휘관 코를리안에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 세라데인으로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 굼벵이 바위굴에 있는 악몽 침공지에 진입하십시오. 잠자는 발톱의 드루이드 베아나 클라우드슬리퍼를 찾아 안전한 곳으로 호위해야 합니다. 임무를 완수하는 대로 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 동부 내륙지"},
[81855] = {title = "페랄라스 임무 I: 세나리우스의 자손 처치", objective = "쌍둥이 바위산에 있는 페랄라스 악몽 침공지에서 방황하는 딸 10명과 복수심에 불타는 아들 10명을 처치한 후 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 쌍둥이 바위산에 있는 악몽 침공지에 진입한 뒤, 광기에 사로잡힌 세나리우스의 아들과 딸들을 소탕하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
