[81865] = {title = "페랄라스 임무 X: 달뿌리", objective = "페랄라스 악몽 침공지에서 달뿌리 10개를 수집한 후, 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 속히 에메랄드 꿈의 관문을 지나 악몽 침공지에서 달뿌리를 수집해 주시면 됩니다. 그 물건의 마력을 피해 복구에 이용할 계획입니다. 참, 약초채집사의 도움이 필요할 겁니다.", progress = "달뿌리는 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
[81866] = {title = "페랄라스 임무 XI: 상급 월장석", objective = "페랄라스 악몽 침공지에서 상급 월장석 10개를 수집한 후, 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 속히 에메랄드 꿈의 관문을 지나 악몽 침공지에서 상급 월장석을 수집해 주시면 됩니다. 그 물건의 마력을 피해 복구에 이용할 계획입니다. 참, 광부의 도움이 필요할 겁니다.", progress = "상급 월장석은 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
[81867] = {title = "페랄라스 임무 XII: 상급 달의 용비늘", objective = "페랄라스 악몽 침공지에서 달의 용비늘 10개를 수집한 후, 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 속히 에메랄드 꿈의 관문을 지나 악몽 침공지에 있는 용족에게서 달의 용비늘을 수집해 주시면 됩니다. 그 물건의 마력을 피해 복구에 이용할 계획입니다. 참, 무두장이의 도움이 필요할 겁니다.", progress = "용비늘은 가져오셨습니까?", completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
[81868] = {title = "페랄라스 임무 XIII: 티라니쿠스 처치", objective = "오네이로스에 있는 페랄라스 악몽 침공지의 파괴된 사원에서 티라니쿠스를 처치한 후, 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 오네이로스에 있는 악몽 침공지에 진입한 뒤, 용 티라니쿠스를 처치하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
[81870] = {title = "페랄라스 임무 XIV: 알론드리우스 처치", objective = "쌍둥이 바위산에 있는 페랄라스 악몽 침공지의 도로에서 순찰 중인 알론드리우스를 처치한 후, 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 쌍둥이 바위산에 있는 악몽 침공지에 진입한 뒤, 숲의 수호자 알론드리우스를 처치하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
[81871] = {title = "페랄라스 임무 XV: 슬리레나 처치", objective = "까마귀바람 폐허에 있는 페랄라스 악몽 침공지의 지구라트 주변에서 슬리레나를 처치한 후, 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 까마귀바람 폐허에 있는 악몽 침공지에 진입한 뒤, 하피 \"여왕\" 슬리레나를 처치하고 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
[81872] = {title = "페랄라스 임무 XVI: 멜리아스 어스텐더 구출", objective = "오네이로스에 있는 페랄라스 악몽 침공지의 비취비늘 호수 근처 계단에서 멜리아스 어스텐더를 구출한 후, 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 오네이로스에 있는 악몽 침공지에 진입하십시오. 잠자는 발톱의 드루이드 멜리아스 어스텐더를 찾아 안전한 곳으로 호위해야 합니다. 임무를 완수하는 대로 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
[81873] = {title = "페랄라스 임무 XVII: 네렌 브룩싱어 구출", objective = "쌍둥이 바위산에 있는 페랄라스 악몽 침공지의 모닥불에서 네렌 브룩싱어를 구출한 후, 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 쌍둥이 바위산에 있는 악몽 침공지에 진입하십시오. 잠자는 발톱의 드루이드 네렌 브룩싱어를 찾아 안전한 곳으로 호위해야 합니다. 임무를 완수하는 대로 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
[81874] = {title = "페랄라스 임무 XVIII: 잼니스 트리멘더 구출", objective = "까마귀바람 폐허에 있는 페랄라스 악몽 침공지의 북쪽 경계에서 잼니스 트리멘더를 구출한 후, 야전 지휘관 아루넬에게 가야 합니다.", description = "악마들 때문에 여기 발이 묶여 있는 동안 에메랄드의 꿈은 악몽의 힘에 타락해 가고 있습니다. 서둘러 꿈나무로 향하십시오. 그대로 에메랄드 꿈의 관문을 지나 까마귀바람 폐허에 있는 악몽 침공지에 진입하십시오. 잠자는 발톱의 드루이드 잼니스 트리멘더를 찾아 안전한 곳으로 호위해야 합니다. 임무를 완수하는 대로 돌아오십시오.", progress = nil, completion = "잘하셨습니다. 공로를 세웠으면 보상을 받아 마땅하지요. 다음 임무는 어떻습니까?", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n임무 완료\n\n다음과 같은 것들을 받습니다:\n\n에메랄드 파편임무 개요: 페랄라스"},
[81877] = {title = "경기 당일", objective = "가젯잔 투기장에서 우승해야 합니다.", description = "가젯잔 투기장 재개장 준비가 다 끝났다고!\n\n규칙은 간단해. 세 번의 경기를 통해 우승자를 가려낼 거야. 경기 막간에 짧은 휴식 시간이 주어지는데, 투기장 밖으로 나가는 건 금지야. 이탈하면 실격이라고.\n\n준비되면 말해. 싸움을 시작할 시간이야!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n검투사의 룬검귀의 격노"},
[81885] = {title = "의식", objective = "그레고리와 대화하여 의식을 시작해야 합니다.", description = "<name> 님의 노고에 감사드립니다. 모험가님이 없었다면 전 지금쯤 죽어 있었을 거고, 군단의 종복들이 이 위험한 유물을 갖고 있었겠지요. 리치 왕의 하수인을 믿기 어려운 건 압니다만... 그래도 이 일이 끝나고 친구를 빛의 품으로 다시 데려오고 싶습니다. 제가 아꼈던 사람이 아직 그 안에 남아 있다는 건 분명히 알았으니까요. 단지 알껍데기를 깨고 나올 계기가 필요할 뿐입니다.\n\n가시지요. 그레고리가 의식을 끝낼 수 있도록 도와야 합니다. 얘기는 끝난 다음에 하시죠.다음과 같은 것들을 배웁니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n팔보호구 각인술 - 정의의 망치\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n정의의 망치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[81900] = {title = "불타는 야수", objective = "저주받은 땅의 야수에 관해 박식한 전문가를 찾아야 합니다.", description = "<눈앞의 조각품에는 어둠의 문을 헤치고 나오는 머리 두 개 달린 야수의 모습이 표현되어 있습니다. 야수의 입에서는 지옥불이 뿜어져 나옵니다. 아래 명판에 \"해방된 칼레팩투스\"라고 새겨져 있습니다.\n\n황혼의 망치단이 이 야수의 파괴적인 힘을 손에 넣을 꿍꿍이인 게 분명하다고 직감이 외칩니다.\n\n저주받은 땅에서 추적을 이어나가는 게 좋을 듯합니다. 그곳이라면 이 지옥의 야수에 관해 아는 사람이 있을지도 모릅니다.>퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[81917] = {title = "속박의 사슬", objective = "불지옥 사슬 5개를 저주받은 땅에 있는 혈법사 린노어에게 가져가야 합니다.", description = "현장 연구 중에 그대가 말한 \"칼레팩투스\"란 생명체를 자주 본 기억이 납니다. 지옥 마력으로 만들어진 심장부 사냥개처럼 생겼더군요. 겉모습만 놓고 보면 천하무적이 따로 없었습니다.\n\n하지만 그대의 말이 사실이고, 황혼의 망치단이 이 야수를 복속시킬 계획을 꾸미고 있다면... 제압할 방법이 있을지도 모르겠군요.\n\n이곳 남동쪽에 있는 어둠의 혈맹은 암흑 의식을 거행하는 걸로 유명합니다. 그 조직 구성원 중에 칼레팩투스를 약화시킬 방법을 아는 자가 있을지도 모릅니다.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[81919] = {title = "복종", objective = "해방된 칼레팩투스의 지옥 마력 혈액을 저주받은 땅에 있는 혈법사 린노어에게 가져가야 합니다.", description = "그대가 찾아온 사슬로 도구를 만들었습니다. 그대와 같은 사냥꾼들이 흔히 사용하는 \"올가미\"의 일종입니다. \n \n이 사슬에 담긴 마력은 악마를 속박하는 데 최적화되어 있습니다. 칼레팩투스 역시 어둠의 문 저편에서 왔으니, 놈에게도 효과가 있을 거라고 봅니다.\n\n칼레팩투스를 처치하거든 지옥 마력이 깃든 혈액 표본을 채취해 주십시오. 굉장히 이질적인 생명체인 만큼 반드시 연구해 봐야 합니다.\n\n칼레팩투스가 지금 황무지 어디에 있는지는 모릅니다. 하지만 <class>님이라면 찾아내실 수 있겠지요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n불지옥 올가미굶주림의 룬"},
[81924] = {title = "수호자의 지혜", objective = "페랄라스, 아즈샤라, 동부 내륙지의 수호자 영혼에게 스스로를 증명한 후 페랄라스에 있는 티리시우스에게 가야 합니다.", description = "<class>님, 이 폐허에 당신이 찾는 칼도레이의 지식은 없습니다. 사라진 지 오래죠.\n\n다만 물리적인 형태가 바스러졌을 뿐, 영혼은 남아 있습니다.\n\n아즈샤라와 동부 내륙지, 페랄라스에서 수호자의 영혼을 찾으십시오. 사당을 찾으면 됩니다. 영혼들에게 스스로의 가치를 증명하고 말에 귀를 기울이십시오. 영혼들의 지혜를 내려받아, 이곳에 있던 무수한 지식들처럼 명맥이 끊기지 않게 해주셨으면 합니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n꽃피우기의 룬소생의 씨앗"},
[81944] = {title = "새로운 목적의 발견...", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n신앙의 상징"},
[81947] = {title = "핏빛 마술", objective = "수집품에 추가할 만한 물건을 가져오셨습니까?", description = nil, progress = "수집품에 추가할 만한 물건을 가져오셨습니까?", completion = "감사합니다, &lt;name&gt; 님. 덕분에 지식의 지평이 한 단계 더 넓어졌습니다.\n\n도서관에 어울리는 마법 저작을 더 찾거든 가져다주십시오.", rewards = "다음과 같은 것들을 받습니다:\n\n이해의 부적"},
