[81960] = {title = "공기의 정화", objective = "오염된 정기 바위를 찾아 탁한 바람의 정기를 마셔야 합니다.", description = "<알아볼 수 없는 쪽지가 정기에 감싸여 있습니다. 기억보다 더 탁하지만, 같은 마법과 융합된 것으로 보입니다. 무언가 좋지 않은 영향력에 오염된 듯 불길한 기분이 듭니다. 이 주변에 성지가 있는지는 잘 모르지만, 정기 바위라면 있을 것입니다. 정기 바위에서 이 낯선 마력의 정체를 알 수 있을지도 모릅니다.>다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[81967] = {title = "이계의 보물", objective = "여기 받으세요!다음과 같은 것들을 받습니다:\n\n", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n이계의 보물"},
[81968] = {title = "바람의 부름에 응하다", objective = "페랄라스 살도르 섬의 잊혀진 해안에 있는 물의 정령에게서 정기의 정수 3개를 입수한 후, 바람의 파편과 결합해 타락의 사당에서 도와줄 존재를 소환해야 합니다.", description = "넌 충분히 강하다. 알 것도 같군... 그래... 네가 타락을 막아다오.\n\n<심기가 불편한 듯 몸을 움직이는 정령>\n\n페랄라스에 정기가 있다. 정수를 사용해 사당을 찾아라.\n\n파편을 가져가라. 타락에 대처하는 데 도움이 될 거다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[81974] = {title = "지리에게 더 많은 잡동사니를", objective = "놈리건에서 지리 \"스패너\" 리틀스프로켓과 대화해야 합니다.", description = "<또 다른 G-7 핵.심. 처리 장치를 발견했습니다. 다만 저번에 찾은 물건보다 상태가 훨씬 안 좋은 데다, 부식성이 굉장히 강해 보이는 먹물 같은 액체가 새어 나오고 있습니다. 고물이나 다름없어 보이지만, 지리라면 어딘가 쓸 데가 있을지도 모릅니다.>", progress = "거기 가져온 게 뭐죠, <name> 님?", completion = "우와! G-7 핵.심. 처리 장치네요. 실제로 보기는 처음이에요. 그건 그냥 버리세요. 정말 위험하다고 들었거든요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[81975] = {title = "불길한 교환", objective = "지리와 대화해야 합니다.", description = "아니, 뭐라고요? 어디에 머리라도 부딪혔어요? 저 쇳덩어리 고치는 일인데 제가 뭐 하러 이런 걸 가져와 달라고 하겠냐고요? 저 자동 수습기를 수리하는 데는 카트리지 퓨즈, 미스릴 주괴, 마법부여 정수 몇 개면 충분해요. 출력을 최대치까지 낼 수 있는 G-7 장치를 넣었다간... 무슨 일이 일어날지 저도 모르겠네요. 좋은 일은 절대 아니겠죠. 폭발이나 화재가 일어난다든지, 차원 사이에 사는 괴물이 튀어나온다든지. 공포도 그런 공포가 없을 거라고요.", progress = nil, completion = "자동 수습기에 G-7을 넣는 상상을 해보세요! 전 죽고 싶지 않다고요.\n\n&lt;혼자 키득거리며 다시 일에 집중하는 지리&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[81986] = {title = "깨어나는 악몽", objective = "악몽의 융합체를 파괴하고 정체불명의 인물에게 전리품을 가져가야 합니다.", description = "지리의 도구를 얻었으니, 악몽의 융합체를 상대하는 데 필요한 준비물은 모두 모였군요. 동료를 최대한 많이 모아 잿빛 골짜기에 있는 어둠의 나무 차원문을 통해 악몽에 진입하세요. 악몽의 융합체를 찾아내 처단하면 돼요. \n\n아, 한 가지 더... 제가 각별한 관심을 두고 있는 물건을 그 야수가 갖고 있어요. 놈의 시체에서 찾아다 주시면 보상을 드리도록 하지요.", progress = "사냥은 잘 되어가고 있나요?", completion = "아주 잘했어요, &lt;name&gt; 님. 이제 보상을 드릴게요!\n\n사실 제가 원한 건 이 껍질 속에 숨어 있는 아주 작은 꿈의 조각이었거든요. 근데 껍질도 그 자체로 보물이에요. 당신에게 드리죠. 그 껍질에는 고유한 속성이 있어요. 적절한 기술을 갖추고 다시 찾아오시면 활용법을 알려드릴게요.", rewards = "다음과 같은 것들을 받습니다:\n\n마력을 잃은 악몽의 어깨덧옷"},
[81987] = {title = "고블린식 해결법", objective = "고블린 지뢰 5개를 소금 평원에 있는 정비공 맥시밀리언에게 가져가야 합니다.", description = "어이. 이리 와봐. 얼굴 좀 보자. 역시 그럴 줄 알았어. 고블린 기술의 추종자는 멀리서도 알아볼 수 있다고. 주먹에 묻은 검댕만 봐도 그래. 우리 다 비슷하거든. 잘 들어. 나 좀 도와줘. \n\n난 여기서 동료 고블린들이 우위를 점할 수 있게 자문을 제공하는 일을 맡았어. 근데 노움들이 전문가를 데려오더니 천천히 앞서나가기 시작했다고. 나도 좋은 생각은 몇 개 있는데, 일단 고블린 지뢰를 몇 개 가져와. 만들 줄 알지?다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82001] = {title = "필수 노움 문제", objective = "정비공 맥시밀리언에게 천둥발굽 스테고돈 뿔을 가져가야 합니다.", description = "나쁜 소식이야. 노움 조언가가 나보다 한발 앞섰어. 그놈들 경주차는 땅에 붙어 다니지도 않더라고!\n\n경주로에 \"자석\"이라는 물건을 깔고 있는데, 경주차가 땅 위를 활공해서 폭발 같은 건 일어나지도 않을 거야! 지뢰를 밟지 않는다면 지뢰를 갖다주면 그만이지!\n\n전류만 충분히 흐르게 하면 문제를 해결할 수 있어. 운고로 남서부로 가서 천둥발굽 스테고돈 뿔을 가져오라고!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82002] = {title = "색이 붉고 냄새나는 것은?", objective = "하스글렌으로 가 붉은 염료 상자를 찾아야 합니다.", description = "신형 지뢰가 훌륭하게 작동하긴 하는데, 단순한 파괴 공작원 노릇만 할 순 없지. 부정행위자 소리를 안 들으면 우리 차량도 손을 좀 봐야 한다고. \n\n가장 확실한 개량은 바로 멋진 색깔로 도색하는 거야. 어떤 색으로 갈지는 이미 정해져 있지! 화끈한 붉은색 아니겠냐고! 가장 빠른 색이잖아!\n\n가장 완벽한 붉은색을 누가 가졌는지 알아? 바로 붉은십자군 나부랭이들이야 . 하스글렌에 몰래 들어가서 멋들어진 진홍색 염료를 구해오라고.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82003] = {title = "고블린의 약진", objective = "보수와 관련해 피즈비즈 코퍼코일과 대화해야 합니다.", description = "하! 역시 나야! 아니... 어, 우리가 해냈네!\n\n저기 얼뜨기 조언가 녀석이 백기를 들었다고! 돈을 줄 테니 여길 떠나달라고 애걸복걸하더라! 이 영광은 너한테 양보할게. 그럴 자격 있으니까.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82004] = {title = "입막음 돈", objective = "피즈비즈 코퍼코일의 뇌물을 받아야 합니다.", description = "당신이랑 고블린 친구 때문에 평판도, 금전적 손실도 감당할 수 없을 지경까지 와버렸어요. 그러니 이렇게 하죠. 노움 기계공학자의 방법론에 관한 내부자 정보를 줄게요. 그 대신 제발 좀 사라져요! 더는 이 근처에서 보고 싶지도 않으니까!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n기계공학 교환 상품권"},
[82008] = {title = "노움식 해결법", objective = "피즈비즈 코퍼코일에게 노움 전투 방어 허리띠 2개를 가져가야 합니다.", description = "안녕하세요! 딱 보니 아주 뛰어난 지성인이시군요. 절 도와주셨으면 하는 일이 있어요. 일단 경주로에서 막 폭발이 일어나는 게 보이죠? 범인이 누군지 좀 뻔하지 않나요? 아무튼 최우선사항은 운전사의 안전이에요. 그러니 노움 전투 방어 허리띠 좀 몇 개 구해다 주세요. 네, 이걸로 일단 단기적인 문제부터 해결해 보는 거죠.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82009] = {title = "필수 고블린 문제", objective = "피즈비즈 코퍼코일에게 천둥발굽 스테고돈 뿔을 가져가야 합니다.", description = "혹시 아직도 경주로에서 폭발음이 들리나요? 안 들리는 거 맞죠? 그렇죠? 제가 청력을 거의 다 상실해서. 아무튼...\n\n자석! 경주로를 따라 자석을 꼼꼼하게 설치하고, 차량 바닥에 반대되는 극성의 자석을 달면 지뢰 위를 떠다닐 수 있을 거예요! 고블린 녀석들이 기절초풍하겠죠! \n\n마지막 준비물로 복잡한 전기 배선의 전류를 감당할 수 있는 물건이 필요해요. \n\n운고로 남서부로 가서 천둥발굽 스테고돈 뿔을 가져와 주세요!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82010] = {title = "경쟁자 말리기", objective = "하스글렌으로 가 붉은 염료 상자를 찾아야 합니다.", description = "방어에만 급급하던 때는 다 지나갔어요! 경쟁 상대를 방해하지 않으면 이길 수 없다고요! 저들의 연료를 노리죠! 어디 보자. 화염초랑 럼주란 말이야? 천재적인 노움이 이런 거에 지고 있었던 거야? 고작 독한 술에? \n\n적들이 눈치채지 못하게 연료를 파괴할 방법을 찾아야 해요. 놀라울 정도로 붉은 꽃이 있는데, 그 꽃잎으로 만든 혼합물은 미열에도 폭발을 일으킬 정도로 불안정하죠. \n\n붉은십자군이 이 꽃을 염료로 사용하기도 해요. 하스글렌으로 가서 꽃을 구해오세요.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82011] = {title = "노움의 결승선 경쟁", objective = "정비공 맥시밀리언과 대화해야 합니다.", description = "우리가 해냈어요, 친구! 고블린이 항복했어요. 아닌 게 아니라 고블린이 고용한 조언가가 당신과 개인적으로 이야기를 나누고 싶대요! 너무 또 과시하진 마세요. 저러다 터지면 어쩌려고요!다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82013] = {title = "입막음 돈", objective = "정비공 맥시밀리언의 뇌물을 받아야 합니다.", description = "이렇게 하자고. 더 이상 자네를 감당할 여력이 없으니 이렇게 하자. 당장 이곳을 떠나. 대신 넓은 마음으로 떠나주는 것인 만큼 일주일에 한 번 돌아오는 건 허락할게.\n\n그때 이곳에 오면 왠지 챙겨가고 싶은 그런 물건이 바닥에 덩그러니 놓여 있을 거야. 나는 자네의 결정에 너무 감동해서 어떤 식으로든 보상을 제공할지도 모르고 말이지.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n기계공학 교환 상품권"},
[82016] = {title = "아탈라이의 신비한 물약", objective = "제가 좋은 제안을 하나 하죠! 아탈라이 부족민에게서 입수한 모조를 가져오면 상상을 초월하는 힘을 드리겠습니다. 하지만 이 힘은 발견지인 늪지에서만 사용할 수 있다는 걸 명심하세요. 아탈라이는 금단의 사술을 연마한다고 합니다. 제가 얄팍하게나마 아는 게 있죠.\n\n어떤가요? 거래에 응하시렵니까?", description = nil, progress = "제가 좋은 제안을 하나 하죠! 아탈라이 부족민에게서 입수한 모조를 가져오면 상상을 초월하는 힘을 드리겠습니다. 하지만 이 힘은 발견지인 늪지에서만 사용할 수 있다는 걸 명심하세요. 아탈라이는 금단의 사술을 연마한다고 합니다. 제가 얄팍하게나마 아는 게 있죠.\n\n어떤가요? 거래에 응하시렵니까?", completion = "후회하지 않을 겁니다!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n생명의 아탈라이 모조아탈라이 전쟁 모조아탈라이 금지된 마법 모조"},
[82017] = {title = "악몽의 융합체", objective = "달의 숲에서 로가나르를 찾아야 합니다.", description = "당신이 경험한 공포의 오라는 장소가 아니라 한 생명체가 발산한 겁니다. 무척이나 치명적인 어둠의 생명체가, 우리네 세상의 끔찍한 양상을 반영하는 뒤틀린 그림자가 하나로 모여 순수한 악몽의 융합체로 완성된 것이죠. 그걸 어떻게 아냐고 물으신다면 설명하기 어려운데... 그게, 꿈을 꿨습니다. 아니다. 보여졌다고나 할까요. 설명하기 어렵습니다. 부디 달의 숲으로 가서 드루이드 로가나르와 얘기해 보십시오. 지금이라면 놈이 더 강해지기 전에 막을 수 있을지도 모릅니다.", progress = nil, completion = "끔찍한 소식이군요. 한날라 님 말씀대로면 지금 꿈이 당면한 위기가 더 심각해질 겁니다.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82018] = {title = "이타리우스", objective = "슬픔의 늪 어딘가에서 이타리우스를 찾아야 합니다.", description = "아탈학카르 신전을 잘 아십니까? 여기선 말하기 어렵지만 유구한 역사를 지닌 곳인데, 지금은 강력한 녹색용들이 지키고 있습니다. 사원의 수호자 중에서도 대장이 바로 위대한 용 에라니쿠스란 분인데, 꿈과 상당히 동화되어 있는 것으로 유명합니다. 그분이 우릴 도와주실 수 있을 겁니다. 슬픔의 늪으로 가서 그곳의 순찰자 이타리우스를 만나보십시오. 그분이라면 에라니쿠스 님에게 도움을 청하는 방법을 알지도 모릅니다.", progress = nil, completion = "에라니쿠스 님을 찾으십니까? 시기를 잘못 고르셨습니다, &lt;class&gt;님. 아탈학카르 신전에 무슨 문제가 생긴 듯합니다. 자세한 얘기는 가서 하시지요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82019] = {title = "잠입", objective = "아탈학카르 신전에서 무슨 일이 벌어지는지 알아내야 합니다.", description = "가라앉은 사원은 과거 피의 신 영혼약탈자 학카르의 부활을 위해 헌신하는 트롤 종파의 본거지였습니다. 아탈라이가 음침한 야욕을 실현하기 전에 이세라 님의 분노가 사원을 수렁에 빠뜨렸고, 용 에라니쿠스 님과 무리를 수호자로 남겨 두셨습니다. 최근 트롤들이 다시 사원에서 암약한다는 소문이 들리는데, 수호자 용들이 어떻게 된 건지 걱정됩니다.\n\n사원 안으로 들어가 상황을 파악해 주십시오.", progress = nil, completion = "설명만 들었을 뿐인데도 간담이 서늘해지는군요. 걱정했던 것보다 훨씬 심각한 상황 같습니다. 아직 숨이 붙어 있는 용들이라도 규합할 수 있기를 비는 수밖에요.", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82020] = {title = "달숲으로", objective = "달숲에 있는 로가나르에게 가야 합니다.", description = "로가나르에게 가서 우리가 알아낸 정보를 전달해 주십시오. 전 가서 사원을 둘러보고, 용과 접촉할 수 있는지 보겠습니다. 하다못해 정보라도 캐봐야지 않겠습니까.", progress = nil, completion = "&lt;깊은 한숨을 내쉬는 로가나르&gt;\n\n더 나쁜 소식이라. 알겠습니다. 목숨을 걸고 사원에 들어와서 정보를 알아내 주셔서 감사합니다. 다른 드루이드들에게 알려 앞으로의 방침을 결정해야 할 것 같습니다. \n\n아무튼 감사합니다. 나중에 다시 연락하겠습니다.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\nDNT SF Phase\n\n다음과 같은 것들을 받습니다:\n\n"},
[82021] = {title = "행운의 반전", objective = "정체불명의 인물이 하는 말을 들어야 합니다.", description = "반가워요, <name> 님! 이곳 경치를 구경하던 중에 본의 아니게 사연을 엿듣고 말았지 뭐예요. 다행히 \"악을 잡아먹는 악몽 괴물\" 문제를 해결하는 데 도움을 드릴 수 있을 것 같군요.", progress = nil, completion = "그래도 저 같은 사람이 딱 필요할 때 주변에서 필요한 물건을 제공해 주니까 기운이 샘솟지 않나요?", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82022] = {title = "슬픈 소식...", objective = "정체불명의 인물이 설명한 모험가를 찾아 공허 동력 완갑을 회수해야 합니다.", description = "좋은 소식은 해결책이 존재한다는 거예요. 나쁜 소식은 공포로부터 살아남는 데 필요한 것을 얻으려면 약간의 노력이 필요하다는 사실이죠. 그러니까요. 요즘은 편하게 도움 받기가 어려워서 좀 그렇단 말이에요. 전에 만난 어느 모험가가 처음에 부탁한 일만 제대로 해줬어도 어디 여관에서 따뜻한 식사와 시원한 맥주를 즐기고 있었을 텐데요. 이런 건 신경 쓸 필요도 없이 말이죠.", progress = "탐색은 잘 되어가고 있나요?", completion = "꼭 동력을 잃은 것 같군요. 안타까운 일이지만, 뭐, 쉽게 고칠 수 있어요. 이 물건을 재충전하려면 나가 주문술사가 많은 곳을 찾아 살육을 벌이세요. 드물게 \"공허핵\"이란 물건을 찾을 수 있을 테니, 시체들을 샅샅이 뒤져서 하나 구해오면... 하! 농담이에요! 모험가님 표정이 아주 예술이네요... \n\n잠시만요. 물건에 같은 힘을 주입해 볼게요... 자, 다 됐습니다! 이제 악몽을 처치할 준비가 됐네요.", rewards = "다음과 같은 것들을 받습니다:\n\n공허 동력 완갑"},
[82043] = {title = "야생 신", objective = "동부 내륙지에 있는 진타알로에게서 야생의 속삭임 비약을 입수한 후, 가시덩굴 구릉 꼭대기에서 사용해 아감마간의 혼과 대화해야 합니다.", description = "하이잘의 로아에게 무슨 문제가 생겼네. 자연에서 가장 강한 정령들이 지난 수천 년 동안 하이잘 산을 지켜왔지. 그런 그들이 하나둘 사라지기 시작했네.\n\n고대 로아 중 가장 위대한 존재였던 아감마간은 오래전에 세상을 떠났네. 하지만 아마니 트롤은 죽은 자와 대화하는 법을 알아. 아마니 트롤이 사용하는 부두를 찾아 가시덩굴로 가져가게. 아감마간과 대화를 시도해 그 동족에게 무슨 일이 생겼는지 알아내도록 해.", progress = nil, completion = "죽음의 장막 저 너머에서도 하이잘과 동족을 삼키는 어둠의 기운이 느껴지더구나.\n\n받아라, 필멸자여. 앞으로의 미래에 꼭 필요할 것이니.", rewards = "다음과 같은 것들을 받습니다:\n\n아감마간의 포효"},
[82044] = {title = "야생 신", objective = "야생의 공물을 악령의 숲에 있는 어둠이빨 사절에게 가져가야 합니다. 이성을 상실한 고대정령에게 아감마간의 포효를 사용한 후 처치하여 야생의 공물을 획득해야 합니다.", description = "어둠이 에메랄드의 꿈에 뿌리를 내렸다. 하이잘의 고대정령들이 어둠이 퍼뜨린 혼란과 공포에 빠져 그늘을 헤어 나오지 못하고 있어.\n\n이성을 잃은 고대정령들을 찾아라, 필멸자여. 나의 포효를 이용해 싸움을 유도해야 한다.\n\n타락한 형상을 파괴하면 영혼이 정화되어 새롭게 태어날 것이니.", progress = "산에서 변화가 느껴지더군, <name>. 무슨 일인가?", completion = "&lt;name&gt; 자네는 로아께 큰 도움이 되었네. 공물은 로아를 하이잘로 다시 인도하는 데 사용하지.\n\n공물을 더 가져오면 부족의 보물을 좀 더 나누어 주겠네.", rewards = "다음과 같은 것들을 받습니다:\n\n하이잘의 지혜"},
[82055] = {title = "다크문 사막 카드 한 벌", objective = "다크문 유랑단이 마을에 오면 사막 카드 한 벌을 돌려줘야 합니다.", description = "이제 사막 카드를 모두 모아 한 벌이 완성되자 신기하게도 처음 여덟 개와 뒷면 모양이 똑같은 아홉 번째 카드가 나타납니다. 이 카드에는 \"이 카드들을 다크문 축제 상품 교환원에게 돌려주면 보상을 받을 것입니다.\"라고 적혀 있습니다. 다크문 유랑단은 몇 주에 한 번씩 멀고어와 골드샤이어를 번갈아 가며 들른다고 합니다. 다음에 유랑단이 이곳에 올 때까지 기다려야 합니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 카드: 모래폭풍"},
[82056] = {title = "다크문 악몽 카드 한 벌", objective = "다크문 유랑단이 마을에 오면 악몽 카드 한 벌을 돌려줘야 합니다.", description = "이제 악몽 카드를 모두 모아 한 벌이 완성되자 신기하게도 처음 여덟 개와 뒷면 모양이 똑같은 아홉 번째 카드가 나타납니다. 이 카드에는 \"이 카드들을 다크문 축제 상품 교환원에게 돌려주면 보상을 받을 것입니다.\"라고 적혀 있습니다. 다크문 유랑단은 몇 주에 한 번씩 멀고어와 골드샤이어를 번갈아 가며 들른다고 합니다. 다음에 유랑단이 이곳에 올 때까지 기다려야 합니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 카드: 고문"},
[82057] = {title = "다크문 역병 카드 한 벌", objective = "다크문 유랑단이 마을에 오면 역병 카드 한 벌을 돌려줘야 합니다.", description = "이제 역병 카드를 모두 모아 한 벌이 완성되자 신기하게도 처음 여덟 개와 뒷면 모양이 똑같은 아홉 번째 카드가 나타납니다. 이 카드에는 \"이 카드들을 다크문 축제 상품 교환원에게 돌려주면 보상을 받을 것입니다.\"라고 적혀 있습니다. 다크문 유랑단은 몇 주에 한 번씩 멀고어와 골드샤이어를 번갈아 가며 들른다고 합니다. 다음에 유랑단이 이곳에 올 때까지 기다려야 합니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 카드: 부패"},
[82058] = {title = "다크문 야생 카드 한 벌", objective = "다크문 유랑단이 마을에 오면 야생 카드 한 벌을 돌려줘야 합니다.", description = "이제 야생 카드를 모두 모아 한 벌이 완성되자 신기하게도 처음 여덟 개와 뒷면 모양이 똑같은 아홉 번째 카드가 나타납니다. 이 카드에는 \"이 카드들을 다크문 축제 상품 교환원에게 돌려주면 보상을 받을 것입니다.\"라고 적혀 있습니다. 다크문 유랑단은 몇 주에 한 번씩 멀고어와 골드샤이어를 번갈아 가며 들른다고 합니다. 다음에 유랑단이 이곳에 올 때까지 기다려야 합니다.", progress = "야생 카드 한 벌을 완성하셨군요! 축하합니다!", completion = "드디어 야생 카드를 다 모으셨군요. 당신이 이것을 우리에게 돌려줌으로써 당신과 다크문 유랑단 간에 오랫동안 잊히지 않을 인연이 맺어지게 될 겁니다. 작은 감사의 표시로 상급 다크문 카드 중 하나를 드리겠습니다.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 카드: 과성장"},
[82062] = {title = "그 뒤로 오래오래", objective = "<셔츠를 단정하게 접어 포갠 작은 꾸러미를 받았습니다.>", description = "당신이 믿을 만한 사람인지 확인해야 했습니다. 이런 상황에서 동료란 구하기 어려운 법이니까요. \n\n아제로스에 종양과도 같은 제3의 진영이 성장하고 있습니다. 호드와 얼라이언스 모두 본인들도 모르게 그자들의 꼭두각시가 되어 이용당하고 있지요. 우리가 보유한 자원으로는 놈들의 발목을 붙잡고 정보망을 구축하는 게 한계입니다.\n\n받으십시오. 기상을 드높이고 좋았던 시절을 떠올리십시오. 조만간 머릿수를 늘려 무력시위를 벌여야 할 날이 올 겁니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n프레모의 균형 강요 제복학생 간식무지개 생성기"},
[82068] = {title = "악몽 침공 저항", objective = "페랄라스 또는 동부 내륙지에서 악몽 침공지 임무를 완료한 후 야전 지휘관 코를리안 또는 야전 지휘관 아루넬에게 보고해야 합니다.", description = "오늘 페랄라스 또는 동부 내륙지에서 악몽 침공지 임무를 완료하면 추가 보상을 얻을 수 있습니다.", progress = nil, completion = "잘하셨습니다, &lt;name&gt; 님!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82071] = {title = "불의 정화", objective = "오염된 정기 바위를 찾아 탁한 불의 정기를 마셔야 합니다.", description = "<까맣게 탄 쪽지가 무언가를 감싸고 있습니다. 일종의 정기로 보입니다. 이런 형태나 냄새 모두 생소하지만 그것만 제외하면 다른 부분은 똑같아 보입니다. 그런데 어딘가 이상합니다. 꼭 다른 마법으로 오염된 것 같습니다. 당신의 기억에는 없지만, 아무래도 이 근처에 정기 바위가 있는 듯합니다. 어쨌든 바위를 찾으면 이 이상한 상황의 실체를 파악할 수 있을 것입니다.>다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82072] = {title = "대지의 정화", objective = "오염된 정기 바위를 찾아 탁한 대지의 정기를 마셔야 합니다.", description = "<익숙한 정기 병이 얼룩진 쪽지로 감싸여 있습니다. 이상할 정도로 탁한데, 마법의 기운은 대체로 친숙합니다. 희미하지만 혼합물을 오염시키는 외부 마법의 존재가 느껴집니다. 이 근처에 정기 바위가 있다고 본능이 말하고 있습니다. 정작 기억은 안 나지만 말입니다. 바위를 찾으면 이 불가사의를 파헤치는 데 도움이 될 것입니다.>다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82073] = {title = "물의 정화", objective = "오염된 정기 바위를 찾아 탁한 물의 정기를 마셔야 합니다.", description = "<질척거리는 빛바랜 쪽지가 탁한 병을 감싸고 있습니다. 정기입니다. 이런 걸 본 기억은 없지만 그래도 낯이 익습니다. 오염됐는지 이상한 냄새가 납니다. 버려진 지 오래겠지만, 이 근처에 정기 바위가 있을 것입니다. 바위가 이 기묘한 수수께끼의 사라진 조각일지도 모릅니다.>다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82074] = {title = "불의 부름에 응하다", objective = "페랄라스 살도르 섬의 잊혀진 해안에 있는 물의 정령에게서 정기의 정수 3개를 입수한 후, 불의 파편과 결합해 타락의 사당에서 도와줄 존재를 소환해야 합니다.", description = "강하군. 그 정도면 충분하겠어.\n\n<불꽃을 튀기며 깜빡이는 정령>\n\n페랄라스의 정기. 정수. 사당을 찾아라.\n\n파편을 가져가라. 도움이 될 거다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82075] = {title = "대지의 부름에 응하다", objective = "페랄라스 살도르 섬의 잊혀진 해안에 있는 물의 정령에게서 정기의 정수 3개를 입수한 후, 대지의 파편과 결합해 타락의 사당에서 도와줄 존재를 소환해야 합니다.", description = "생명이 자란다. 부족해. 타락을 막아야 한다.\n\n<정령이 몸을 움직이자 바위가 서로 긁히는 소리가 납니다.>\n\n페랄라스. 정기. 정수와 사당.\n\n찾아라. 파편을 이용해 찾을 수 있다. 생명의 성장을 도와다오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82076] = {title = "물의 부름에 응하다", objective = "페랄라스 살도르 섬의 잊혀진 해안에 있는 물의 정령에게서 정기의 정수 3개를 입수한 후, 물의 파편과 결합해 타락의 사당에서 도와줄 존재를 소환해야 합니다.", description = "강한 영혼이로다. 타락을 막는 걸 도와다오.\n\n<정령 주위로 물이 맹렬하게 솟구칩니다.>\n\n형제. 페랄라스의 정기를 도와다오. 정수로 사당을 찾을 수 있다.\n\n파편도 도움이 될 거다. 타락을 정화해다오.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[82081] = {title = "중단된 의식", objective = "몰락한 화신의 어깨뼈를 요잠바 섬에 있는 몰소르에게 가져가야 합니다.", description = "<기억 속에 선명히 남아 있는 온전한 어깨뼈입니다. 이것으로 학카르가 물질 세계에 소환되었고, 이후 퇴치되었습니다. 요잠바 섬에 있는 트롤들에게 가라앉은 사원에서 있었던 일을 알려야 합니다.>", progress = "<name>, 아탈학카르 신전에서 무슨 소식을 가져왔나?", completion = "말도 안 돼... 아탈학카르 신전에 관한 소문이 사실이었단 말인가? \n\n자네가 가라앉은 사원에서 거둔 승리는 오랫동안 잔달라의 기억에 남을 걸세. 이 뼈는... 여기로 가져오다니, 좀 특이한 결정이긴 한데... 학카르를 물질 세계로 소환하는 데 사용됐겠지. 걱정 말게나, &lt;name&gt;. 자네 덕분에 이제 학카르가 돌아올 걱정은 하지 않아도 괜찮게 됐으니...", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n전령의 비룡발톱 고리핏빛 선지자의 비룡발톱 고리광전사의 비룡발톱 고리무력의 비룡발톱 고리추적자의 비룡발톱 고리"},
[82083] = {title = "중단된 의식", objective = "몰락한 화신의 어깨뼈를 요잠바 섬에 있는 몰소르에게 가져가야 합니다.", description = "<기억 속에 선명히 남아 있는 온전한 어깨뼈입니다. 이것으로 학카르가 물질 세계에 소환되었고, 이후 퇴치되었습니다. 요잠바 섬에 있는 트롤들에게 가라앉은 사원에서 있었던 일을 알려야 합니다.>이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n전령의 비룡발톱 고리핏빛 선지자의 비룡발톱 고리광전사의 비룡발톱 고리무력의 비룡발톱 고리추적자의 비룡발톱 고리"},
[82084] = {title = "글의 교훈", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n[DNT] Temporal Anomaly\n\n다음과 같은 것들을 받습니다:\n\n전용 마법책"},
[82086] = {title = "글의 교훈", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n전용 마법책"},
[82089] = {title = "변환의 대가", objective = "크리메온 라블레이드에게 아케이나이트 주괴 3개를 가져가야 합니다.", description = "변환식은 재능을 가진 연금술사라면 누구나 응용할 수 있는 독특한 기술입니다. 그렇지만 누구보다 헌신적인 이들만이 진정한 대가의 반열에 오를 수 있지요. 보아하니 자질은 갖춘 듯한데, 이 길에 들어 고차원적인 지식과 이해를 추구하는 데 진심임을 증명해 보여야 합니다.\n\n헌신의 징표로 아케이나이트 주괴 세 개를 가져오십시오.", progress = nil, completion = nil, rewards = nil},
[82090] = {title = "즐겁고 쏠쏠한 혼합술", objective = "혼합의 달인 블릭스에게 투명 물약 10개, 악마 사냥 전문화의 비약 10개, 현인의 비약 5개를 가져가야 합니다.", description = "한 사람 몫을 하는 연금술사라면 누구나 연금술은 이익을 극대화하는 기술이라고 말할 테지요. 저렴한 값에 재료를 조달하고, 대량으로 조제하고, 하늘을 찌를 듯한 가격에 처분할 수 있으니까요. 자, 그런데 재료를 더, 훨씬 더 잘 활용할 방법이 있다면 어떻겠습니까? 자칭 \"혼합술의 거장\"으로서 비약과 물약 조제 실력을 한 차원 더 높은 곳으로 끌어올려 드리겠습니다. 투명 물약 10개와 악마 사냥 전문화의 비약 10개, 현인의 비약 5개를 가져오면 가르쳐 드리지요.", progress = nil, completion = nil, rewards = nil},
[82093] = {title = "밀림 두리안", objective = "과일의 대담하고 톡 쏘는 냄새가 슬픔의 늪을 지나 아탈학카르 신전을 탐험할 동안 정신을 바짝 차리게 해줄 겁니다. 악취에 속지 마세요. 이건 저희 종족이 아주 귀하게 여기는 과일입니다!\n\n흥미로운 물건을 가지고 생환하면 섭섭하지 않게 챙겨드리지요. 최고급 두리안을 묶음으로 내어드리겠습니다! 어떤가요?", description = nil, progress = "과일의 대담하고 톡 쏘는 냄새가 슬픔의 늪을 지나 아탈학카르 신전을 탐험할 동안 정신을 바짝 차리게 해줄 겁니다. 악취에 속지 마세요. 이건 저희 종족이 아주 귀하게 여기는 과일입니다!\n\n흥미로운 물건을 가지고 생환하면 섭섭하지 않게 챙겨드리지요. 최고급 두리안을 묶음으로 내어드리겠습니다! 어떤가요?", completion = "타즈딩고! 맛있고 달콤한 두리안을 즐기시길. 참고로... 환불은 안 됩니다.", rewards = "다음과 같은 것들을 받습니다:\n\n밀림 두리안"},
[82094] = {title = "잊힌 신전의 인장", objective = "누구보다 강한 모험가에겐 최고의 제안을 해야겠죠. 어깨보호구를 강화하는 물건이 있습니다. 아탈라이의 힘이 담겼죠. <name> 님, 신전에 있는 가장 강한 아탈라이에게서 모조를 입수해 오면 후회하지 않게 해드리겠습니다. \n\n너무 성급히 생각하진 마세요. 전 공정한 거래만 하는 사람이니...", description = nil, progress = "누구보다 강한 모험가에겐 최고의 제안을 해야겠죠. 어깨보호구를 강화하는 물건이 있습니다. 아탈라이의 힘이 담겼죠. <name> 님, 신전에 있는 가장 강한 아탈라이에게서 모조를 입수해 오면 후회하지 않게 해드리겠습니다. \n\n너무 성급히 생각하진 마세요. 전 공정한 거래만 하는 사람이니...", completion = "이제 그만 가보세요. 혹시 상품이 더 필요하면 찾아오시고요!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아탈라이 힘의 인장아탈라이 모조의 인장아탈라이 평온의 인장"},
[82095] = {title = "학카르의 화신", objective = "타나리스에 있는 예킨야에게 충만한 학카르의 알을 가져가야 합니다.", description = "이제 학카르 화신의 정수를 모을 차례요.\n\n이 학카르의 알을 동부 왕국의 가라앉은 사원에 있는 죽은 신의 성소로 가지고 가시오. 그리고 알의 힘으로 죽은 신을 깨우시오.\n\n알아두시오. 이런 원초적인 모습이라곤 하나 그자는 상상을 초월하는 힘을 지니고 있소. 분노란 분노는 모조리 토하며 저항할 테지.\n\n그를 물리치고 학카르의 알에 그의 정수를 담아오시오.", progress = "학카르의 화신은 물리쳤소, <name>? 내가 준 알에 그의 정수를 담아온 거요?", completion = "학카르의 정수를 모아왔군! 지금 이 순간에도 충만한 알이 살아 움직이는 게 느껴져! 학카르의 전설이 사실인 것 같소?\n\n전설은 이야기일 뿐일 터... 하지만 사실이라면 학카르가 환생하여 무슨 일이라도 저지를까 두렵소. 내 이 알을 잘 간직해 사악한 무리의 손에 들어가지 않도록 하겠소.\n\n이제 끝났소, &lt;name&gt;. 이번 일로 당신은 전설에 손을 댄 거요. 그 용감한 행동이 언젠가 아제로스의 모습을 바꾸어놓으리라 믿소.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n아방가드 투구생명력의 단검금은보석 머리장식\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[82096] = {title = "심연의 늪", objective = "슬픔의 늪에 있는 가라앉은 사원에서 학카르 제단을 찾아야 합니다.", description = "사원 안에서 난 발코니가 여섯 개 있는 원형 방을 찾았소. 발코니마다 가장자리에 뱀 석상이 하나씩 있었지. 난 호기심에 그중 하나를 밀어보았는데, 그게 함정이었던 것이오! 난 폭발로 떨어져서 죽을 뻔했소이다. 발코니 끄트머리에 쓰러진 채 아래를 내려다보니 방바닥에 다른 석상이 있었소. 일종의 제단 같은 것이었는데, 이름이 학카르였던 것 같군.\n\n그 제단에 비밀이 숨겨져 있는 것 같으니 이 돌무리를 가라앉은 사원의 제단으로 가져가도록 하시오.", progress = "석상을 살펴보니 옆면에 움푹 들어간 곳이 있습니다. 마본이 준 돌의 크기랑 꼭 맞습니다...", completion = "돌무리를 움푹 들어간 자리에 집어넣자 딸각하는 소리가 나며 들어갑니다.\n\n이제 돌을 집어넣었으니 그다음에는 무엇을 해야 할까요?\n\n이 제단을 좀 더 살펴보아야 할 것 같습니다...", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[82097] = {title = "돌무리의 비밀", objective = "가라앉은 사원으로 가서 원 모양으로 서 있는 석상들에 감춰진 비밀을 알아내야 합니다.", description = "자세히 기억이 나진 않지만 아는 대로 말해주겠소. 가라앉은 사원에 원 모양으로 서 있는 석상들은 위험하기는 하지만 더 큰 보물로 통하는 비밀을 간직하고 있소.\n\n중심 제단에서는 불을 켤 수 있었는데 이 불의 의미가 무엇인지 알아내면 그 방에 숨겨진 비밀도 알아낼 수 있을지 모르오.\n\n하지만 그 사원에는 엄청난 악이 도사리고 있으니 조심하도록 하시오. 아마도 귀중한 보물이 철통같은 보안 속에 숨겨져 있을 거야...", progress = nil, completion = "&lt;파괴된 잔해 위 신상의 눈이 밝게 빛납니다. 투명한 눈 뒤에 뭔가 반짝이는 것이 있습니다. 당신은 큼지막한 잔해 덩어리 몇 개를 옆으로 밀어내고 눈 뒤에 숨겨진 것을 꺼냅니다.\n\n아탈라이 보물은 이제 당신 것입니다.&gt;", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n학카르의 단지"},
[82098] = {title = "아탈학카르 신전으로", objective = "스톰윈드에 있는 브로한 캐스크벨리에게 아탈라이 서판 10개를 가져가야 합니다.", description = "전설에 의하면 아탈학카르 신전은 고대 신, 학카르를 모시는 신성한 제단이라고 하네. 소문에 듣기로 이 신전은 아탈라이라는 사나운 트롤 부족이 지키는 난공불락의 요새라고 하더군.\n\n이제는 슬픔의 늪 아래로 가라앉아 버렸으니 신전에서 유물을 되찾는 일은 더욱 힘들어졌어. 그러나, 바로 이것이 자네가 해줘야 할 일이야.\n\n나를 도와 손상되지 않은 아탈라이 서판을 가져와 주게. 그걸 가져오면 나는 영웅이 되어 탐험가 연맹으로 돌아갈 수 있을 거라고. 나와 자네가 함께 그 영광을 누릴 수 있을 걸세.", progress = "이제 일을 계속해 나갈 희망이 점점 사라져 가는군. 탐험가 연맹에서의 마지막 임무를 마치려면 자네의 도움이 필요하네. 늙은 몸이지만 슬픔의 늪과 가라앉은 사원을 용기 있게 헤쳐 나갈 힘만 있다면 자네 바로 옆에서 함께 싸울 텐데...\n\n자존심 때문에 아탈라이 서판을 모아 달라고 도움을 청하는 게 쉽지는 않지만 나이가 들어 어쩔 수가 없군.\n\n제발 날 도와주게. 마지막 임무를 마친 후 연맹에서 은퇴했으면 하네.", completion = "아탈라이 서판이군! 고맙네!\n\n이것들을 탐험가 연맹에 가져다준다면 우리의 이름과 함께 역사에 남게 될 거야. 이 늙은 &lt;race&gt;가 생의 마지막 임무를 완수하는 것을 도와주었으니 영원히 자네에게 감사하는 마음을 간직하도록 하겠네.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n수호 부적"},
[82099] = {title = "악의 아지랑이", objective = "아탈라이 아지랑이 5개를 모은 후 운고로 분화구에 있는 무이긴에게 돌아가야 합니다.", description = "솔직히 말하면 여행을 다니면서 이런 식물을 본 건 처음이오. 아무래도 운고로 분화구에 한번 가봐야겠군...\n\n어쨌든, 무이긴이 뭘 찾는지 알 것 같소. 아탈라이 아지랑이라는 건데, 아주 고약한 물질이지. 모으기가 쉽진 않지만 그 조그만 괴물들을 조종하려면 꼭 필요한 것이라오.\n\n슬픔의 늪에 있는 아탈학카르 신전으로 가시오. 그곳에서 지하껍질괴물, 진흙구렁이, 진흙괴물을 처치하면 아탈라이 아지랑이를 구할 수 있을 거요. 행운을 빌겠소!", progress = "라리온이 아직도 나랑 얘기하지 않으려고 하는군! 그 친구 원한을 품는 방법 하난 확실히 아는군.", completion = "맞소. 그 물건들에 손을 대기가 좀 꺼려지긴 하는군! 하지만 그레간이 된다고 하니 시도는 해보고 싶소!", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[82100] = {title = "아탈학카르 신전", objective = "스토나드에 있는 펠제룰에게 학카르의 우상 20개를 가져가야 합니다.", description = "잠말란의 예언에 대해 얘기했다고?\n\n아탈라이 부족의 영적 지도자는 학카르가 황천에서 아제로스로 다시 돌아오면 아탈라이 부족에게 불멸의 생을 선사해 줄 것이라 믿고 있는 모양이군.\n\n내가 보기에는 멸망의 지름길일 뿐이야.\n\n그런데 그 유배자가 마법의 우상에 대해 얘기했다고? 흠, 매우 걱정스럽군. 이것이 정말로 이 난장판을 만든 아탈라이 의식에 대한 해답이라면 내재한 힘을 알아야만 하오.\n\n신전으로 가서 그 우상들을 가져오시오!다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n수호 부적"},
[82101] = {title = "구제장치 연료", objective = "마샬의 야영지에 있는 라리온에게 충전 안된 구제장치와 아탈라이 아지랑이 5개를 가져가야 합니다.", description = "운이 좋으시군요! 마본님이 안 계신 동안 저도 나름대로 실험을 하고 있었거든요. 그중 하나가 수동 잡초 구제장치인데요, 약간만 조정하면 그 붉은꽃잎덩굴손 잡초 녀석들을 제거할 수 있을 거예요.\n\n제가 구제장치 원형을 하나 드릴 수는 있지만 연료를 좀 모으셔야 할 거예요. 구제장치 연료로 쓸 아탈라이 아지랑이는 아탈학카르 신전으로 가면 찾을 수 있죠. 아탈라이 아지랑이는 지하껍질괴물이나 진흙구렁이, 아니면 진흙괴물에게서 얻을 수 있을 거예요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n"},
[82102] = {title = "에라니쿠스의 정수", objective = "가라앉은 사원의 안식처에 있는 정수의 샘에 에라니쿠스의 정수를 놓아야 합니다.", description = "보석을 만지자 굵은 목소리가 마음속까지 울려 퍼집니다.\n\n\"필멸의 생명이여, 내 청을 들어다오. 나는 녹색용군단의 에라니쿠스라하며 이 저주받은 사원의 감시인이다. 내 임무는 두 번 다시 트롤이 그들의 흉측한 신을 이곳에 모시지 못하도록 하는 것이었는데 실패하고 말았다. 내 정수를 이 보석에 부여하니 꿈을 지배하는 나의 힘이 혼돈으로 뒤틀리는구나. 부탁이니 이 보석을 내 안식처에 있는 정수의 샘에 넣어주었으면 한다. 그곳의 마력이 내 영혼에서 악을 씻어내 내가 편히 쉴 수 있도록 해다오.\"", progress = "에라니쿠스가 말한 정수의 샘에 다가가자 그의 목소리가 다시 한번 울립니다.\n\n\"그래. 이 정수의 샘이 이 보석에 깃들어 있는 오염되지 않은 내 영혼을 회복시켜 줄 것이다. 녹색용군단의 마력이 내 존재에서 타락과 오염을 씻어낼 수 있도록 샘에 그 보석을 담가 다오. 그렇게 해야만 내가 진정한 해방을 누릴 수 있고, 그렇게 해야만 용군단이 다시 아탈라이를 다스릴 수 있느니라.\"", completion = "보석을 정수의 샘에 담급니다.\n\n\"필멸의 생명이여, 고맙구나. 덕분에... 아냐. 이... 이럴 리가 없어! 안 돼! 저주받은 신의 타락이 녹색용군단 정수의 샘의 신성함까지 더럽히는구나! 제발, 안 돼. 내게서 정기가 찢겨 나가고 있어! 고통스럽구나!!! 끝없는 악몽이 나를 휘어잡고 있어...\"\n\n\"필멸의 생명이여, 간청하니 녹색용군단의 일원을 찾아 이를 멈추도록 해다오... 나를 도와다오... 그렇지 않으면 암흑에 갇혀... 영원히 고통받게 될 것이다... 제발 이 고통을... 멈추어...\"", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n속박된 에라니쿠스의 정수"},
[82104] = {title = "예언자 잠말란", objective = "잠말란을 처치하고 그 증거로 그의 머리카락을 동부 내륙지에 있는 추방된 아탈라이트롤에게 가져가야 합니다.", description = "우리 마른나무껍질부족은 자기 집에 이방인이 들락거리는 걸 싫어한다.\n\n나? 난 이제 고향이 없어. 난 우리 부족인 슬픔의 늪의 위대한 아탈라이 부족으로부터 추방당했다.\n\n우리 부족의 영적 지도자 잠말란이 자칭 예언이란 걸 받았다고 주장했는데, 학카르를 소환해 아탈라이 부족을 불사의 존재로 만들 수 있다고 하더군.\n\n하지만 나는 부족 주민들에게 경고했다. 혹시 그 예언이 조작된 것이라면...\n\n내가 왜 추방당해야 했지? 난 복수를 하고 싶다. 잠말란을 처치하고 그의 머리카락을 가져와. 그렇게만 하면 우리 부족은 그의 압제에서 해방될 거야.", progress = "잠말란만 죽어 없어진다면 난 우리 동족들에게 돌아갈 수 있을 거야.\n\n잠말란이 영적 지도자로 남아 있는 한 아탈라이 부족은 멸망을 벗어날 수 없다.", completion = "잠말란은 무모하게 헛된 선견지명을 좇아 우리 부족을 영원한 멸망으로 이끌려고 했다.\n\n복수를 해줘서 고맙다, &lt;class&gt; 친구. 나는 우리 동족에 대해 애통하게 생각해. 이제 난... 돌아갈 고향이 없다.", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n폭우의 다리보호구추방자의 투구\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들 또한 받습니다:\n\n"},
[82108] = {title = "녹색 비룡 몰파즈", objective = "아즈샤라에 엘다라스 폐허의 북동쪽 절벽 꼭대기에 있는 오그틴크에게 몰파즈의 이빨을 가져가야 합니다.", description = "이제 나는 녹색 비룡인 몰파즈를 처치하고 그 이빨을 내게 가져오는 위험한 사냥을 부탁할 것이다. 몰파즈는 슬픔의 늪에 있는 아탈학카르 신전의 깊은 곳에서 살고 있다.\n\n그 비룡은 여럿이서 힘을 합쳐 상대해야 할 적이니, 녀석을 처치하고자 하는 다른 이들을 찾아보도록 해라.\n\n그 비룡의 이빨은 사냥꾼이 다른 동료와 함께 노력하여 알아내게 되는 힘을 상징하는 것이다. 그걸 내게 가져오면 많은 것을 알게 될 것이야.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n사냥용 창데빌사우루스 눈데빌사우루스 이빨"},
[82110] = {title = "하늘색 열쇠", objective = "조라크 라벤홀트 경에게 하늘색 열쇠를 가져가야 합니다.", description = "페이지를 해독하고 마법을 제거하는 데 시간이 좀 걸릴 걸세. 다 끝나면 내가 직접 가방을 라벤홀트 경에게 전달하도록 하지.\n\n아직 열쇠를 찾는 일이 남아 있는데, 그건 몰파즈라고 하는 어떤 녹색 비룡이 지니고 있다고 하네. 그 비룡은 입구가 슬픔의 늪에 있는 아탈학카르 신전 깊은 곳에 살고 있지.\n\n동료를 모아 그 녀석의 소굴로 쳐들어가게. 라벤홀트 경은 자네가 열쇠를 가지고 돌아오기를 기다리고 있을 것이야.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n흑단 복면침묵의 장화그늘박쥐 망토"},
[82112] = {title = "더욱 강력한 재료", objective = "가라앉은 사원 하층부의 수호병으로부터 썩은 덩굴을 찾은 후 토르와 패스파인더에게 돌아가야 합니다.", description = "우려했던 대로 그 맹수에게 사용하기에는 독성이 너무 약했군.\n\n효과가 더 확실한 독이 필요하오. 아탈학카르 신전의 하층부로 가시오. 제단의 비밀을 푼 후 그곳을 지키는 수호병으로부터 썩은 덩굴을 찾아야 하오. 위험한 곳이니 동료와 함께 가는 게 좋을 거요.\n\n일을 마치면 돌아오시오.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n불곰 모피 조끼숲의 은총달그림자 지팡이"},
[82113] = {title = "부두교 마법", objective = "바람의감시자 바스라에게 부두 깃털들을 가져가야 합니다.", description = "정기의 토템이 아직 완성되지 않았네. 제대로 작동하려면 부두교 마법이 필요해.\n\n가라앉은 사원의 트롤들이 지니고 다니는 깃털에는 강력한 부두교 마력이 들어있네. 그리로 가서 게이셔, 줄로, 마이잔, 후쿠, 졸로, 로로를 해치워. 그러면 정기의 토템에 넣을 마력을 충분히 모을 수 있을 거야.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n아주라이트 장갑사로잡힌 물의 정령광야의 지팡이"},
[82114] = {title = "몰파즈 처치", objective = "몰파즈에게서 신비의 결정을 되찾아 대마법사 실렘에게 가져가야 합니다.", description = "아탈라이의 가라앉은 사원 깊은 곳에는 몰파즈라는 이름을 가진 녹색 비룡이 산다네.\n\n오래전, 녀석은 날 습격해서 내 수습생을 통째로 삼켜버렸다네. 수습생을 잃어본 적이야 전에도 있었지만 그 수습생은 특히나 크고 질 좋은 신비의 결정을 갖고 있었다네.\n\n자네의 강한 친구들을 이끌고 사원으로 쳐들어가게. 몰파즈를 쓰러뜨리고 그 영생의 뱃속에서 신비의 결정을 꺼내 오게나.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n혹한의 쐐기신비의 수정 목걸이화염 루비"},
[82115] = {title = "트롤의 깃털", objective = "가라앉은 사원에 있는 트롤의 부두 깃털 6개를 가져가야 합니다.", description = "인형이 거의 완성됐어요. 이제 속을 채울 재료만 있으면 돼요.\n\n가라앉은 사원에 있는 트롤들에게 나오는 부두 깃털이 제일로 좋지요. 게이셔, 마이잔, 졸로, 후쿠, 줄로, 로로라는 트롤들을 모두 해치워 주세요.\n\n쉬운 일은 아닐 줄은 저도 아니까 그 답례로 나이비의 소장품 중에서 하나를 드리겠어요. 나이비에게는 더 이상 필요 없을 거예요.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n영혼 수확기나락의 조각예속의 로브"},
[82135] = {title = "희망의 대가", objective = "만노로크 메아리의 보주를 스톰윈드에 있는 성기사 캐서린에게 가져가야 합니다.", description = "<아이오나스는 그저 묵묵하게 보주를 건네고는 돌아섭니다.>다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n휘파람"},
[82208] = {title = "훌륭한 도서관의 친구", objective = "기증 감사합니다. 도서관이 한층 더 풍성해졌습니다.\n\n이걸 받아 주시길.", description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 배웁니다:\n\n투구 각인술 - 동결\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n[DNT] Deep Freeze"},
[82209] = {title = "물주머니 현상금", objective = "부지런한 <name> 양반, 또 오셨군. 사막유랑단 물주머니 5개를 더 가져왔다면 선물세트를 주겠소! 이름도 큼직하게 새겨서 말이오.", description = nil, progress = "부지런한 <name> 양반, 또 오셨군. 사막유랑단 물주머니 5개를 더 가져왔다면 선물세트를 주겠소! 이름도 큼직하게 새겨서 말이오.", completion = "아주 잘했소. 물주머니를 더 많이 찾을수록 우리는 끔찍한 갈증 걱정을 안 해도 되지! 계속 더 가져오면 고맙겠소. 물주머니 5개마다 반드시 보상이 따를 테니까.", rewards = "다음과 같은 것들을 받습니다:\n\n가젯잔 수자원개발회사 선물세트"},
[82210] = {title = "트롤 목걸이 현상금", objective = "트롤 전통 목걸이를 더 찾아서 가지고 온다면 계속해서 받아주겠네. 목걸이를 가져온다면 자네는 와일드해머에서 명성을 쌓을 수 있을 걸세. 계속해서 우리를 위해서 싸울 의지를 보여준다면 언젠가 우리도 자네를 도울 날이 있을 걸세!\n\n트롤 전통 목걸이는 적어도 5개씩 가져와야 하네.", description = nil, progress = "트롤 전통 목걸이를 더 찾아서 가지고 온다면 계속해서 받아주겠네. 목걸이를 가져온다면 자네는 와일드해머에서 명성을 쌓을 수 있을 걸세. 계속해서 우리를 위해서 싸울 의지를 보여준다면 언젠가 우리도 자네를 도울 날이 있을 걸세!\n\n트롤 전통 목걸이는 적어도 5개씩 가져와야 하네.", completion = "목걸이를 또 가져왔다는 건 동부 내륙지에서 성가신 트롤의 수가 그만큼 줄었다는 뜻이지! 또 해냈군, &lt;name&gt;. 계속 수고해주면 고맙겠네!", rewards = nil},
[82271] = {title = "더 많은 붉은 전갈 피", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82272] = {title = "붉은 전갈 피", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82273] = {title = "더 많은 박쥐 눈", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82274] = {title = "더러운 박쥐 눈", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82275] = {title = "검은 대형 철퇴", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82276] = {title = "힘의 의식", objective = "전 이 세상에 가장 힘센 여자가 되기 위해 전 세계를 여행하면서 외딴곳에 사는 몸 만들기 전문가와 몸짱 선생님, 고대 비전서를 찾아다니며 근육을 단련하는 여러 가지 비전을 익혔어요. 그래서 이제 약자의 목숨을 빼앗고 초보자를 불구로 만들 수 있을 정도로 위험한, 금지된 의식을 알게 되었죠!\n\n힘과 조절 능력이 필요한 이 의식을 실행하려면 가장 강도 높은 연마석이 있어야 해요. 연마석을 몇 개 만들거나 구해서 제게 가져다주시겠어요? 그럼 다크문 축제 상품권을 드리도록 하죠.", description = nil, progress = "전 이 세상에 가장 힘센 여자가 되기 위해 전 세계를 여행하면서 외딴곳에 사는 몸 만들기 전문가와 몸짱 선생님, 고대 비전서를 찾아다니며 근육을 단련하는 여러 가지 비전을 익혔어요. 그래서 이제 약자의 목숨을 빼앗고 초보자를 불구로 만들 수 있을 정도로 위험한, 금지된 의식을 알게 되었죠!\n\n힘과 조절 능력이 필요한 이 의식을 실행하려면 가장 강도 높은 연마석이 있어야 해요. 연마석을 몇 개 만들거나 구해서 제게 가져다주시겠어요? 그럼 다크문 축제 상품권을 드리도록 하죠.", completion = "고마워요. 가시덤불 골짜기의 가장 깊은 정글에서 발견된 고대 서판으로부터 배운, 힘을 얻기 위한 의식에 이 연마석들을 사용할 거예요.\n\n이 신성한 의식을 제대로 수행하는 여자는 타우렌 10명을 견딜 인내력과 힘을 갖게 된대요!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82277] = {title = "더 많은 강도 높은 연마석", objective = "그동안 많이 도와주셔서 감사해요. 정말 어떻게 감사해야 할지 모르겠네요!\n\n이젠 더 이상 그렇게 꼭 필요한 건 아니지만... 제게 강도 높은 연마석을 더 가져오시면 다크문 축제 상품권으로 더 바꿔 드릴 수 있답니다.", description = nil, progress = "그동안 많이 도와주셔서 감사해요. 정말 어떻게 감사해야 할지 모르겠네요!\n\n이젠 더 이상 그렇게 꼭 필요한 건 아니지만... 제게 강도 높은 연마석을 더 가져오시면 다크문 축제 상품권으로 더 바꿔 드릴 수 있답니다.", completion = "이번에도 다시 한번 감사드려요. 자, 이 상품권으로 즐거운 시간 되세요. 친구들에게 우리 다크문 축제에 대해 얘기해 주는 것도 잊지 마시고요!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82278] = {title = "더 많은 토륨 부품", objective = nil, description = nil, progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82279] = {title = "토륨 부품", objective = "예브 네블기어는 나처럼 앞으로 쓸 새로운 볼거리를 만들고 있다네. 예브는 그 새로운 볼거리가 워낙 놀라운 것이라 전 세계 사람들이 구경하러 오게 될 거라고 장담하고 있지... 그래서 우리 모두 아주 어마어마한 부자가 될 거라고 말이야!\n\n하지만 건축을 위해 토륨 부품이 필요하다면서 나더러 자기 대신 구해 놓으라고 하더군. 자네 생각은 어떤가? 자네 토륨 부품을 어디서 구하는지 아나? 자네가 기계공학을 배운 자라면 그걸 만들 수 있나? 토륨 부품을 다크문 축제 상품권과 교환할 생각이 있느냐는 말일세.", description = nil, progress = "예브 네블기어는 나처럼 앞으로 쓸 새로운 볼거리를 만들고 있다네. 예브는 그 새로운 볼거리가 워낙 놀라운 것이라 전 세계 사람들이 구경하러 오게 될 거라고 장담하고 있지... 그래서 우리 모두 아주 어마어마한 부자가 될 거라고 말이야!\n\n하지만 건축을 위해 토륨 부품이 필요하다면서 나더러 자기 대신 구해 놓으라고 하더군. 자네 생각은 어떤가? 자네 토륨 부품을 어디서 구하는지 아나? 자네가 기계공학을 배운 자라면 그걸 만들 수 있나? 토륨 부품을 다크문 축제 상품권과 교환할 생각이 있느냐는 말일세.", completion = "고맙네! 예브가 이 부품을 보면 아주 좋아하겠군. 나야 이걸 어떻게 사용할 계획인지 모르지만 예브는 영리한 &lt;race&gt;이니까 알아서 잘하겠지. 영리한 데다가 어쩌면 약간은 사악한 면도 있고...\n\n그가 인간처럼 생긴 고기 맛만 좋아한다면... 훌륭한 트롤이 될 수 있을 텐데 말이야!\n\n자, 이 상품권을 받게. 거래는 확실하게 해야지.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82280] = {title = "기계 수리 장비", objective = "내가 전시장을 개설할 수 없는 가장 큰 이유는... 모든 게 다 부서졌기 때문이야! 이 모든 걸 다 수리하려면 기계 수리 장비가 필요하네.\n\n장비를 좀 구해다 주지 않겠나? 장비를 가져오면... 다크문 축제 상품권과 바꿔 주겠네. 어떤가?", description = nil, progress = "내가 전시장을 개설할 수 없는 가장 큰 이유는... 모든 게 다 부서졌기 때문이야! 이 모든 걸 다 수리하려면 기계 수리 장비가 필요하네.\n\n장비를 좀 구해다 주지 않겠나? 장비를 가져오면... 다크문 축제 상품권과 바꿔 주겠네. 어떤가?", completion = "고맙네! 이제 수리를 시작할 수 있겠어.\n\n모든 걸 정상적으로 돌려놓으려면 많은 수리 장비가 필요하고 밤늦게까지 일하는 날이 많을 테지만 말이야. 때로는 모두 다 그만두고 고향으로 돌아가서 인간사냥꾼 일이나 다시 시작하는 게 낫지 않을까 하는 생각도 들지만... 유랑단에서 그동안 나한테 잘해 줘서 그럴 수도 없다네.\n\n어쨌거나... &lt;class&gt; 친구, 이 상품권을 받고 즐거운 시간 보내게!", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
