[82307] = {title = "온전한 화물", objective = "뭘 가져오셨습니까?", description = nil, progress = "뭘 가져오셨습니까?", completion = "물건이 다 들어 있군요! 감사합니다, &lt;name&gt; 님. 이 보급품은 최전방에서 중요하게 쓰일 거예요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n평판 - 상인 진영\n\n다음과 같은 것들을 받습니다:\n\n"},
[82308] = {title = "온전한 화물", objective = "뭘 가져오셨습니까?", description = nil, progress = "뭘 가져오셨습니까?", completion = "물건이 다 들어 있군요! 감사합니다, &lt;name&gt; 님. 이 보급품은 최전방에서 중요하게 쓰일 거예요.", rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n평판 - 상인 진영\n\n다음과 같은 것들을 받습니다:\n\n"},
