[82316] = {title = "일곱 가지 눈을 찾고 있으니...", objective = "일곱 가지 숨겨진 눈을 찾고 있으니... 내게로 가져오면 눈이 뜨이리라.", description = nil, progress = "일곱 가지 숨겨진 눈을 찾고 있으니... 내게로 가져오면 눈이 뜨이리라.", completion = "눈이 뜨였도다...", rewards = "다음과 같은 것들을 배웁니다:\n\n투구 각인술 - 공허의 눈\n\n다음 주문들이 당신에게 시전될 것입니다:\n\nDNT Teach EoV"},
[82323] = {title = "흩날리는 솜깃털", objective = "사람의 상상력이란 정말 놀라워요. 상상 속에서는 아주 작은 언덕도 제일 큰 산처럼 만들 수도 있고, 아무것도 아닌 그림자가 끔찍한 악몽 속에 나오는 괴물처럼 보이게 할 수도 있으니까요!\n\n다크문 유랑단은 방문객이 상상의 나래를 펼칠 수 있도록 해 주죠! 하지만 상상력을 펼칠 수 있도록 하기 위해서는... 때때로 우리 나름의 작전이 필요하답니다.\n\n그래서 말인데, 흩날리는 솜깃털이 필요해요. 아제로스 대륙에서 좀 위험한 지역에 사는 새들에게서 구할 수 있어요. 솜깃털을 가져오면 상품권을 많이 드리도록 하죠!", description = nil, progress = "사람의 상상력이란 정말 놀라워요. 상상 속에서는 아주 작은 언덕도 제일 큰 산처럼 만들 수도 있고, 아무것도 아닌 그림자가 끔찍한 악몽 속에 나오는 괴물처럼 보이게 할 수도 있으니까요!\n\n다크문 유랑단은 방문객이 상상의 나래를 펼칠 수 있도록 해 주죠! 하지만 상상력을 펼칠 수 있도록 하기 위해서는... 때때로 우리 나름의 작전이 필요하답니다.\n\n그래서 말인데, 흩날리는 솜깃털이 필요해요. 아제로스 대륙에서 좀 위험한 지역에 사는 새들에게서 구할 수 있어요. 솜깃털을 가져오면 상품권을 많이 드리도록 하죠!", completion = "아, 솜깃털이로군요! 정말 멋지지 않나요? 이렇게 아름다운 솜깃털이라면 사람들의 상상력을 자극하는 데 큰 도움이 될 거예요!\n\n정말 좋은 일을 하신 거예요. 덕분에 쇼를 보러 온 방문객들의 얼굴에 미소가 피어날 수 있게 되었으니까요. 그건 정말 큰 보람이죠. 하지만 이 상품권도 함께 받으세요.", rewards = "다음과 같은 것들을 받습니다:\n\n다크문 축제 상품권"},
[82656] = {title = "야생 가죽 조끼", objective = "모자케 야영지에 있는 장도르 스위프트스트라이더에게 거북 껍질 흉갑 2개, 거북 껍질 장갑 2개, 야생덩굴 1개를 가져가야 합니다.", description = "야생 가죽 조끼는 모든 야생 가죽 방어구 세트의 기본이지. 조끼의 틀과 야생덩굴이 한데 잘 엮여 조끼 전체에 강력한 마법이 흐르게 되기 때문에 몸통을 최대한으로 보호할 수 있소이다.\n\n이 도안을 얻으려면 거북 껍질 흉갑 2개와 거북 껍질 장갑 2개, 그리고 야생덩굴 1개가 필요하오. 쉬운 수업은 아니지만 당신 실력이라면 이 정도는 틀림없이 해낼 수 있을 것이오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 조끼"},
[82657] = {title = "야생 가죽 조끼", objective = "페더문 요새에 있는 프랫 맥그루벤에게 거북 껍질 흉갑 2개, 거북 껍질 장갑 2개, 야생덩굴 1개를 가져가야 합니다.", description = "야생 가죽 조끼는 모든 야생 가죽 방어구 세트의 기본입니다. 조끼의 틀이 야생덩굴과 잘 섞여 조끼 전체에 강력한 마법이 흐르게 되기 때문에 몸통을 최대한으로 보호할 수 있답니다.\n\n이 도안을 얻으려면 거북 껍질 흉갑 2개와 거북 껍질 장갑 2개, 그리고 야생덩굴 1개가 필요합니다. 단순한 임무는 아니지만 그리 어렵진 않을 겁니다.", progress = "내가 지시한 거북 껍질 흉갑과 장갑을 2개씩 가져왔습니까? 아, 야생덩굴도 잊지 마시기 바랍니다!\n\n최초의 도안들만 봐도 기본적인 형태의 틀이 고급 방어구에도 모두 적용된다는 것을 알 수 있습니다. 서로 다른 물건이긴 하지만 거북 껍질 흉갑의 형태는 야생 가죽 조끼를 만드는 데 필요한 세부 작업을 위한 준비가 될 겁니다.\n\n그리고 장갑은... 그게, 장갑은 그냥 내가 좀 필요해서 말입니다. 당신은 나를 위해 일하고 있다는 걸 잊으면 안 됩니다!", completion = "아주 쓸 만한 것들을 가져왔군요. 이것들을 만드는 데 들어간 장인 정신과 정성만으로도 보통의 방어구보다 돈을 더 많이 받을 수 있겠군요.\n\n내가 지시한 것들을 다 가져왔으니 보상을 해야겠군요. 야생 가죽 조끼 제작 기술은 이제 당신 겁니다!", rewards = "다음과 같은 것들을 받습니다:\n\n도안: 야생 가죽 조끼"},
[82662] = {title = "무기제작자의 길", objective = "무기제작자가 되려면 달의 강철 브로드소드 4자루, 큰 철제 도끼 4자루, 견고한 미스릴 도끼 2자루, 검은 대형 철퇴 2자루를 만들어 이로누스에게 가져가야 합니다.", description = "무기제작자에게 물건을 사러 오는 이들 중에는 영웅이나 모험가가 많지. 일이 많아서 힘들 때도 있지만 먼지를 마시며 등골이 휘게 일하는 만큼 수입도 짭짤하다오.\n\n정말! 무기제작자들은 다 알부자들이라오.\n\n무기제작자가 되고 싶다면 쓸만한 재능이 있는지를 내게 증명해 보여야 하오. 아, 내 말은 장인이 될 수 있는 가능성과 소질을 증명해 보이란 말이지. 좋은 무기를 사려면 바로 그에게 가야 한다고 많은 이들이 인정할 만한 장인 말이오. 알아들었으면 어서 일이나 시작하시오.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n전문 무기제작\n\n다음과 같은 것들을 받습니다:\n\n"},
[82665] = {title = "무기제작자의 길", objective = "무기제작자가 되려면 달의 강철 브로드소드 4자루, 큰 철제 도끼 2자루, 견고한 미스릴 도끼 2자루, 검은 대형 철퇴 2자루를 만들어 보르고쉬에게 가져가야 합니다.", description = "언젠가 대족장님의 명예에 걸맞은 전설의 망치를 만들고 말 거야.\n\n이건 내 일생일대의 목표이자 꿈이라네, <name>. 자네도 훌륭한 무기제작자가 될 자질이 엿보이는데, 어떤가? 내가 그 자질을 키우도록 도와줄 수도 있어.\n\n간단한 시험만 거치면 돼. 자네 정도면 식은 죽 먹기일 거야.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n전문 무기제작\n\n다음과 같은 것들을 받습니다:\n\n"},
