[83808] = {title = "어려운 상황", objective = "남쪽 들판에서 종자 쿠스베르트의 검을 회수한 후 돌려줘야 합니다.", description = "놀라서 죽을 뻔했습니다! 인기척이 들리기에 아, 결국 시체들이 내 냄새를 맡았구나 확신했죠! 아무튼 정말 반갑습니다. 이곳을 벗어나 제 주군이신 돌턴 경을 찾아야 합니다. 제 무기를 찾아주시겠습니까? 저 밖에서 놓치는 바람에 이 헛간으로 도망칠 수밖에 없었습니다.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[83934] = {title = "돈 가져와, 돈!", objective = "빛바랜 언더마인화를 무법항에 있는 픽스 시직스에게 가져가야 합니다.", description = "이봐요! 보니까 '재주 좋은 모험가' 같은데, 저 좀 도와줘요. 그게 말이죠. 우리 형제가 잃어버린 섬 출신인데, 새로운 사업을 시작하려고 왔단 말이죠. 근데 해적 놈들이 창업 자금을 훔쳐 갔어요. 우리 사업에 자금을 대준 고향 사람들은 이해심 많은 부류가 아니라... 돈을 되찾아 주시면 사례는 아쉽지 않게 할게요. 평범한 골드는 아니지만 보면 알 수 있을 거예요.", progress = "뭘 가져왔나요, <race> 친구?", completion = "잘됐네요! \n\n혹시 돈을 더 찾으면 가져오세요. 다양한 상품이 있으니 기꺼이 교환해 드릴게요!", rewards = nil},
[84011] = {title = "더 많은 별빛연꽃", objective = "동부 내륙지 악몽 침공지에서 별빛연꽃 10개를 모아 야전 지휘관 코를리안에게 가야 합니다.", description = "악몽 침공지를 되돌리려면 별빛연꽃이 좀 더 필요합니다. 세라데인에 있는 에메랄드 차원문에 들어가 물건을 구해오십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n에메랄드 파편"},
[84012] = {title = "더 많은 별빛은 광석", objective = "동부 내륙지 악몽 침공지에서 별빛은 광석 10개를 모아 야전 지휘관 코를리안에게 가야 합니다.", description = "악몽 침공지를 되돌리려면 별빛은 광석이 좀 더 필요합니다. 세라데인에 있는 에메랄드 차원문에 들어가 물건을 구해오십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n에메랄드 파편"},
[84013] = {title = "더 많은 별빛껍질", objective = "동부 내륙지 악몽 침공지에서 별빛껍질 10개를 모아 야전 지휘관 코를리안에게 가야 합니다.", description = "악몽 침공지를 되돌리려면 별빛껍질이 좀 더 필요합니다. 세라데인에 있는 에메랄드 차원문에 들어가 물건을 구해오십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n에메랄드 파편"},
[84014] = {title = "더 많은 달뿌리", objective = "페랄라스 악몽 침공지에서 달뿌리 10개를 모아 야전 지휘관 코를리안에게 가야 합니다.", description = "악몽 침공지를 되돌리려면 달뿌리가 좀 더 필요합니다. 꿈나무에 있는 에메랄드 차원문에 들어가 물건을 구해오십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n에메랄드 파편"},
[84015] = {title = "더 많은 상급 월장석", objective = "페랄라스 악몽 침공지에서 상급 월장석 10개를 모아 야전 지휘관 코를리안에게 가야 합니다.", description = "악몽 침공지를 되돌리려면 상급 월장석이 좀 더 필요합니다. 꿈나무에 있는 에메랄드 차원문에 들어가 물건을 구해오십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n에메랄드 파편"},
[84016] = {title = "더 많은 달빛용 비늘", objective = "페랄라스 악몽 침공지에서 달빛용 비늘 10개를 모아 야전 지휘관 코를리안에게 가야 합니다.", description = "악몽 침공지를 되돌리려면 달빛용 비늘이 좀 더 필요합니다. 꿈나무에 있는 에메랄드 차원문에 들어가 물건을 구해오십시오.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n에메랄드 파편"},
[84124] = {title = "용맹의 유산", objective = "경외의 제단으로 돌아가야 합니다.", description = "<유령 용사가 굴복하고는 제단을 가리킵니다.>", progress = nil, completion = "&lt;경의를 표한 제단에는 검은색과 금색이 섞인 위엄 넘치는 양손 도끼와 전장의 전설을 기록한 고서가 놓여 있습니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n첫 번째 전사의 룬오래된 경비병 응징도끼"},
[84135] = {title = "해변의 로봇", objective = "돌멩이와 같은 물건을 사용해 기계 부품을 꺼내야 합니다.", description = "<이상한 금속 장치가 해안에 반쯤 파묻혀 있습니다. 일종의 기계로 보이는데, 처음 보는 형태입니다. 측면에는 \"심탐액기연: 심해 탐사 및 액화 기술 연합 재산\"이라고 적힌 꼬리표가 붙어 있습니다. 또한 여닫을 수 있는 듯한 작은 수납공간이 눈에 들어옵니다.>", progress = nil, completion = "&lt;무기로 요령껏 수납공간을 뜯어내자 빛나는 액체가 든 병이 나타납니다.&gt;", rewards = "다음과 같은 것들을 받습니다:\n\n부력 인도 촉진제"},
[84147] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 자연의정수 팔보호구를 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 눈호랑이와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n야생의정수 손목보호구야생의정수 손목매듭야생의정수 손목띠야생의정수 손목싸개\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치"},
[84148] = {title = "진지한 제안", objective = "여명의 설원 혈액 견본 15개와 20골드, 야수추적자 손목띠를 아이언포지에 있는 델리아나에게 가져가야 합니다.", description = "만나서 반가워요, <class>님. 당신이 관심을 가질 만한 일이 있어요.\n\n저에게는 당신 같은 직업을 가진 전문가들이 입는 갑옷 한 세트가 있답니다. 물론 품질은 훨씬 더 좋지요. 작은 부탁 하나만 들어주시면 당신이 가진 평범한 팔보호구를 제가 가지고 있는 팔보호구와 교환해 드리겠어요.\n\n여명의 설원에 살고 있는 눈호랑이와 곰의 혈액에는 제가 지금 필요로 하는 성분이 들어 있어요. 혈액 견본을 많이 구해서 팔보호구와 약간의 돈과 함께 가지고 오시면 그에 합당한 보상을 드리도록 하지요.이 보상들 중 하나를 선택할 수 있습니다:\n\n", progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n야수왕의 팔보호구야수왕의 손목띠\n\n다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치"},
