[84548] = {title = "가로나: 은신과 기만에 대한 연구", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n엘드레탈라스 옥새"},
[84549] = {title = "신비술사의 요리책", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n엘드레탈라스 옥새"},
[84550] = {title = "방어의 고서", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n엘드레탈라스 옥새"},
[84551] = {title = "빛과 정의에 관하여", objective = "주인에게 책을 되돌려주십시오.", description = "이 책에는 도서관의 인장이 찍혀있습니다.다음 주문들이 당신에게 시전될 것입니다:\n\n", progress = nil, completion = nil, rewards = "다음 주문들이 당신에게 시전될 것입니다:\n\n넘치는 경험치\n\n다음과 같은 것들을 받습니다:\n\n엘드레탈라스 옥새"},
[84590] = {title = "빛과 어둠의 균형", objective = "15명이 살해당하기 전에 인부 50명을 구해야 합니다. 이 임무를 완수하면 에리스 헤븐파이어와 대화하십시오.\n\n살해당한 농부의 수를 보려면 죽음의 말뚝을 보십시오.", description = "내가 할 수 없었던 일을 당신이 해 주셔야 합니다. 스트라솔름에서 탈출하려다 살해당한 인부들을 구해야 해요.\n\n그들은 빛을 향해 나아갈 겁니다. 그대는 그들이 살아남을 수 있도록 지켜줘야 해요. 너무 많은 이들이 쓰러진다면 우리의 저주받은 삶은 계속될 겁니다. 그런 일이 벌어지면 그대는 실패하게 될 겁니다.\n\n그대가 지금까지 터득한 모든 기술과 주문, 마법을 시험받을 거예요. 빛의 가호가 있기를 빌겠어요, <name>.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n놀드랏실의 파편"},
[84777] = {title = "나피엔을 위한 깃털", objective = "나는 당신을 믿지만 의심 많은 우리 일족에게도 당신이 친구라는 것을 계속 증명해야 할 것이오. 그러려면 앞으로도 내 도움이 필요할 것이오.\n\n마른가지일족 펄볼그 중 일부는 독특한 깃털로 머리를 장식하고 다니고 있소. 놈들의 수를 줄이고 그 증거로 깃털 머리장식을 가져오시오. 어떤 놈들을 처치하든지 머리장식을 구하는 대로 내게 가져다주시오. 5개를 가지고 올 때마다 나무구렁일족의 신뢰를 얻게 될 것이오.", description = nil, progress = "나는 당신을 믿지만 의심 많은 우리 일족에게도 당신이 친구라는 것을 계속 증명해야 할 것이오. 그러려면 앞으로도 내 도움이 필요할 것이오.\n\n마른가지일족 펄볼그 중 일부는 독특한 깃털로 머리를 장식하고 다니고 있소. 놈들의 수를 줄이고 그 증거로 깃털 머리장식을 가져오시오. 어떤 놈들을 처치하든지 머리장식을 구하는 대로 내게 가져다주시오. 5개를 가지고 올 때마다 나무구렁일족의 신뢰를 얻게 될 것이오.", completion = "&lt;name&gt;, 잘했소! 우리 일족에게 당신의 공로를 꼭 알리겠소.\n\n깃털 머리장식을 발견하면 잊지 말고 내게 가져다주시오. 깃털이 더는 필요하지 않을 때까지...", rewards = nil},
[84870] = {title = "어둠의 창고", objective = "검은바위 첨탑 창고에 침입해 귀중한 물건을 훔쳐야 합니다. 혼자서 완수해야 합니다.", description = "이 문서는 서슬송곳니의 부하가 쓴 보고서입니다. 검은바위 오크 일부가 창고에 불법 마법 유물을 숨기고 있다는 소문이 있습니다. 단순한 밀수인지, 아니면 더 깊은 음모가 있는지는 불확실합니다.\n\n어쨌든, 이것은 쏠쏠한 일이 될 것 같습니다. 들키지 않도록 혼자 가는 것이 좋겠군요. 전리품을 나눌 필요도 없겠죠.다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[85112] = {title = "소진된 낫", objective = "지팡이를 불모의 땅에 있는 도안 카르한에게 가져가야 합니다.", description = "<이 낫은 뒤틀려 있고, 이상한 악마의 기운을 뿜어냅니다. 그럼에도 손으로 만지면 부서질 것처럼 취약해 보이며, 사용하기에도 걱정이 듭니다. 이 낫을 떠올릴 때마다 무언가가 당신의 마력을 끌어당기는 듯하며, 마음 한구석에 굶주린 욕망이 숨어 있는 듯한 기분이 듭니다. 악마 유물에 대해 잘 아는 사람 중에 이 낫을 잘 아는 사람이 있을지도 모릅니다.>", progress = nil, completion = nil, rewards = nil},
[85304] = {title = "불의 정수", objective = "독특한 두루마리의 용도를 알아낸 뒤 스톰윈드 또는 언더시티에 있는 사서에게 보고해야 합니다.", description = "<이 두루마리는 당신이 찾은 다른 두루마리와는 달리 불타는 마력을 발산합니다. 불타는 평원 드라코다르에 있는 마법석이 용도를 밝히는 데 도움이 될지도 모릅니다. 두루마리를 해석해 그 목적을 알아낸 후, 스톰윈드나 언더시티에 있는 사서들에게 결과를 알려야 합니다.>다음과 같은 것들을 받습니다:\n\n퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n"},
[85401] = {title = "혹한의 굴", objective = "여명의 설원 별똥별 마을 근처 지하굴에서 난디에브를 찾은 뒤 지팡이를 회수해야 합니다. 혼자서 수행해야 합니다.", description = "썩은 것에서 생명이 피어나듯, 비자연적인 것도 자연을 섬길 수 있지.\n\n이 심장으로 변화하는 지팡이를 만들 수 있지만, 그 힘을 담아낼 강한 그릇이 필요하다.\n\n여명의 설원 별똥별 마을 근처에 지하굴이 있다. 혼자 가야지만 진정한 입구가 모습을 드러낼 것이야.\n\n그 안에는 오래전에 길을 잃은 수호자 난디에브가 있지. 그의 지팡이라면 심장을 담아낼 수 있다. 이런 제안을 하려니 마음이 아프지만, 지금의 난디에브는 내가 알던 위대한 수호자가 아니야.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n글라시르"},
[85445] = {title = "황금 원반", objective = "일렁이는 황금빛 원반에 관해 자세히 알려줄 수 있는 인물을 찾아야 합니다.", description = "이 물건이 무엇인지 전혀 알 수 없지만, 상당한 힘을 지닌 유물임은 확실합니다. 이 유물에 대해 더 많은 정보를 알려줄 수 있는 사람을 찾아 진정한 용도를 알아내야 합니다.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[85455] = {title = "빛의 수호자의 피", objective = "빛의 수호자의 피에 대해 알려줄 수 있는 인물을 찾아야 합니다.\n\n(사전에 \"역병지대 합류\" 퀘스트를 완료한 상태여야 이 퀘스트를 완료할 수 있습니다.)", description = "<피가 든 작은 병을 쥐자 손이 살짝 떨립니다. 꼬리표에는 글자가 쓰여 있으며, 그뿐만 아니라 표본에서 발산되는 온기와 마력이 느껴집니다. 이게 정말로 전설의 영웅, 빛의 수호자 우서의 피인 걸까요? 표본의 진위를 확인할 수 있는 사람을 찾아야 합니다.>퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[85507] = {title = "탈선한 친구", objective = "서부 역병지대의 슬픔의 언덕에서 아이오나스를 찾아야 합니다.", description = "와주셔서 기쁩니다, <name> 님. 우리의 친구 아이오나스의 모습과 일치하는 여행자가 서리바람 야영지 근처에서 슬픔의 언덕 방향으로 향하는 걸 목격했다는 소식이 들어왔습니다.\n\n악령의 숲에서 있었던 사건 이후로 여유를 주고 싶었지만, 여전히 아이오나스를 불신하는 자들이 남아 있습니다. 언젠가는 돌아와서 오래전부터 리치 왕의 대리인으로 알려진 자와의 관계를 설명하긴 해야 합니다. 가서 아이오나스를 찾아 돌아오게끔 설득해 주세요.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[85596] = {title = "죽음의 은총", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n죽음의 진군죽음의 은총"},
[85598] = {title = "예언의 기운", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n예언의 기운예언의 저주"},
[85599] = {title = "어둠의 마력", objective = nil, description = nil, progress = nil, completion = nil, rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n어둠의 마력후두 저주"},
[85600] = {title = "총명의 기운", objective = "이 잔자는 적절한 재료만 있으면 고대 트롤 주술을 사용할 수 있소.\n\n첫 번째 재료는 학카르 부관 중에서 가장 강력한 자인 진도와 혈군주 만도키르에게서 가져온 고대 학카리 우상이오.\n\n두 번째는 구멍 난 부두 인형인데, 이 사악한 장소 곳곳에 버려져 있는 쓰레기 더미와 불길한 흑마술 더미 안을 뒤져 보면 찾을 수 있소.\n\n이것들을 모두 가져다주면 당신에게 강력한 마법을 주겠소!", description = nil, progress = "이 잔자는 적절한 재료만 있으면 고대 트롤 주술을 사용할 수 있소.\n\n첫 번째 재료는 학카르 부관 중에서 가장 강력한 자인 진도와 혈군주 만도키르에게서 가져온 고대 학카리 우상이오.\n\n두 번째는 구멍 난 부두 인형인데, 이 사악한 장소 곳곳에 버려져 있는 쓰레기 더미와 불길한 흑마술 더미 안을 뒤져 보면 찾을 수 있소.\n\n이것들을 모두 가져다주면 당신에게 강력한 마법을 주겠소!", completion = "잘 사용하도록 하시오, &lt;class&gt;|1이여;여;. 그리고 절대로 학카르 녀석들에게 자비를 베풀지 마시오!", rewards = "다음과 같은 것들을 받습니다:\n\n총명의 기운"},
[85602] = {title = "정령술사의 은총", objective = "이 잔자는 적절한 재료만 있으면 고대 트롤 주술을 사용할 수 있소.\n\n첫 번째 재료는 학카르 부관 중에서 가장 강력한 자인 진도와 혈군주 만도키르에게서 가져온 고대 학카리 우상이오.\n\n두 번째는 구멍 난 부두 인형인데, 이 사악한 장소 곳곳에 버려져 있는 쓰레기 더미와 불길한 흑마술 더미 안을 뒤져 보면 찾을 수 있소.\n\n이것들을 모두 가져다주면 당신에게 강력한 마법을 주겠소!", description = nil, progress = "이 잔자는 적절한 재료만 있으면 고대 트롤 주술을 사용할 수 있소.\n\n첫 번째 재료는 학카르 부관 중에서 가장 강력한 자인 진도와 혈군주 만도키르에게서 가져온 고대 학카리 우상이오.\n\n두 번째는 구멍 난 부두 인형인데, 이 사악한 장소 곳곳에 버려져 있는 쓰레기 더미와 불길한 흑마술 더미 안을 뒤져 보면 찾을 수 있소.\n\n이것들을 모두 가져다주면 당신에게 강력한 마법을 주겠소!", completion = "잘 사용하도록 하시오, &lt;class&gt;|1이여;여;. 그리고 절대로 학카르 녀석들에게 자비를 베풀지 마시오!", rewards = "이 보상들 중 하나를 선택할 수 있습니다:\n\n자연술사의 격노자연술사의 포효자연술사의 균형정령술사의 은총"},
[85613] = {title = "마력의 보물: 구원자의 손목보호대", objective = "줄구룹에서 고대 학카리 어깨갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "복수는 곧 힘이지. 잔달라 구원자가 바로 그 힘일세. 우리 부족에게는 많은 적들이 있는데, 구원자가 그들에게 정확한 복수를 행하지. 적이 우리에게 행한 죄를 응징하지 않고 넘어가는 일은 절대 없네. 구원자가 바로 그 응징을 맡는다네. 적들은 우리의 복수를 두려워하네. 당연히 그래야지. 영원히 그렇게 두려워할 거야.\n\n우리의 구원자가 되게나. 줄구룹 내에서 마력의 보물을 찾아오게. 부족의 이름으로 학카르의 졸개들을 처치하고 복수를 하면 자네에게 상을 내리겠네.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 구원자의 손목보호대"},
[85614] = {title = "마력의 보물: 구원자의 허리띠", objective = "줄구룹에서 고대 학카리 벨트를 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "줄구룹 내에 궁극의 복수가 기다리고 있네. 절대로 학카르가 다시 일어나서는 안 되네. 학카르는 구루바시 제국을 내부에서부터 파괴했고 어떤 제물에도 만족하지 않았지. 이제 트롤족에게 남은 것은 고대 영광의 그림자뿐이며, 그게 학카르 때문인 것을 알고 있네.\n\n자신의 숙명을 받들어 구원자가 되게. 악의 졸개들에게 재앙을 퍼붓게나. 줄구룹은 반드시 잔달라의 복수를 맛봐야만 하네. 복수의 증거로 마력의 보물을 가져오면 구원자의 허리띠를 받게 될 걸세. 진정한 힘을 얻게 되는 거야.\n\n자, 어서 가게나.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 구원자의 허리띠"},
[85615] = {title = "마력의 보물: 구원자의 흉갑", objective = "줄구룹에서 고대 학카리 조끼를 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n또한 잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "구원자 권력의 상징은 바로 흉갑이라네. 아주 강력한 모조로 제작된 그 흉갑은 우리가 존경하는 자들에게만 주어지지. 바로 잔달라 복수의 상징인 것일세.\n\n구원자가 되는 것은 복수 그 자체가 되는 것을 뜻한다네. 우리가 필요로 하는 마력의 보물을 줄구룹에서 가져오게. 그걸 가져오면 녀석들이 우리에게서 앗아간 모조를 되찾도록 하지. 학카르의 졸개들이 그 대가를 치르도록 만들면 구원자의 흉갑을 상으로 주겠네.\n\n어서 가게. 우리의 복수를 해 주게.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 구원자의 흉갑"},
[85618] = {title = "마력의 보물: 자유사상가의 손목보호대", objective = "줄구룹에서 고대 학카리 팔보호구를 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "자네는 이교도로군. 이교도들은 우리 부족의 한 부분을 차지하지. 이교도들은 잔달라의 자유사상가들이야. 자유사상가는 억압을 두려워하지 않고, 자신의 신념을 위해 죽음도 감수하지. 자네도 자네의 믿음 때문에 죽음도 감수할 거라는 걸 알고 있네. 그건 우리 부족의 인정을 받을 만한 일이자, 자네 스스로 자신의 가치를 입증할 기회를 얻을 만한 일이지.\n\n우리에게는 마력의 보물이 반드시 필요하다네. 줄구룹으로 가서 학카르의 졸개들을 처치한 후, 내가 찾고 있는 물건인 잔달라 자유사상가의 전투 장비를 가져오게.\n\n어서 가 보게나.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 자유사상가의 손목보호대"},
[85619] = {title = "마력의 보물: 자유사상가의 허리띠", objective = "줄구룹에서 고대 학카리 어깨걸이를 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "자네가 믿는 바는 우리에겐 아주 낯선 것일세, 이교도여. 고대 잔달라 부족에게는 한때 이교도라는 낙인이 찍혔었지. 당시는 구루바시 제국이 강대했을 때였다네. 이교도들은 감히 학카르의 사제들에게 덤벼들었고, 그 때문에 마치 하찮은 벌레처럼 쫓겨 죽임을 당했다네. 하지만 그 이교도들은 혈신과 대적한 자신들의 싸움에서 결코 흔들리지 않았지. 우리는 바로 그 자유사상가들이 치른 대가를 명예롭게 여긴다네.\n\n줄구룹에서 학카르의 졸개들을 처치하고 내가 찾는 마력의 보물을 가져오게. 성공하면 큰 보상을 받게 될 것이야.\n\n자, 어서 가 보게.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 자유사상가의 허리띠"},
[85620] = {title = "마력의 보물: 자유사상가의 흉갑", objective = "줄구룹에서 고대 학카리 휘장을 구해 가시덤불 골짜기의 요잠바 섬에 있는 파괴자 진로크에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "전투를 위한 방어구가 있으면 부족 내에서 힘을 갖게 된다네. 광신도들인 자유사상가들은 이런 식으로 명예를 누렸지. 그들은 자신들의 흉갑에 강력한 모조를 부여했다네. 적과 맞섰을 때 자신들의 믿음은 흔들릴지언정 자신들의 흉갑은 흔들리지 않도록 말이야.\n\n그런 흉갑을 소유하려면 부족민들 사이에서 존경을 받아야만 하네. 줄구룹으로 가서 내가 필요로 하는 마력의 보물을 구해 오게. 줄구룹 내의 멍청이들에게 가장 큰 고통을 안기고 빼앗아서 내게 가져오게나. 자유사상가로서의 자네 가치를 아주 확고히 입증해 보여주게나.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 자유사상가의 흉갑"},
[85622] = {title = "마력의 보물: 성자의 손목띠", objective = "줄구룹에서 고대 학카리 손목갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "우리 잔달라 부족은 천상의 권한을 전하는 이들에게 힘을 실어 준다네. 우리 사제들은 단순히 치유사가 아니라 성자일세. 악이란 학카르처럼 외부에서, 부족 내부에서 나타나기도 하지만 내부에서 나타나기도 하는 것이지. 성자들은 부족민 사이에서 재판관 역할을 하면서 구루바시를 내부에서 집어삼켰던 바로 그 악으로부터 우리를 보호한다네.\n\n줄구룹으로 가서 구루바시로부터 마력의 보물을 되찾아오게. 성자가 된다는 것이 어떤 것인지 배우고 우리를 악으로부터 보호해 주게나.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 성자의 손목띠"},
[85623] = {title = "마력의 보물: 성자의 허리띠", objective = "줄구룹에서 고대 학카리 장식띠를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "구루바시 제국이 멸망하고 난 후 오래지 않아, 우리 잔달라 부족도 부족 내부의 악에 의해 거의 최후의 패배를 맞을 뻔했지. 바로 그때 부족에서 성자들이 들고 일어나 동족을 파괴하려는 자들을 추방함으로써 부족의 존속을 지켰지. 그들은 우리가 영혼들과의 조화를 지속할 수 있도록 할 뿐 아니라 우리의 육체도 보호해 준다네.\n\n줄구룹으로 가서 학카르와 구루바시 부족의 타락을 직접 목격해 보게나. 우리가 원하는 마력의 보물을 그들에게서 빼앗아 오게. 성공하면 보상이 있을 것이야!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 성자의 허리띠"},
[85624] = {title = "마력의 보물: 성자의 어깨보호대", objective = "줄구룹에서 고대 학카리 아이기스를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족의 성자들은 모두 부족의 보호자라는 것을 증명하는 특유의 어깨보호대를 걸치고 있지. 그 어깨보호대에는 우리 부족을 위협하는 자들을 가려내는 데 도움이 되는 강력한 모조로 짜여 있다네. 사제인 자네도 가치가 있고 없는 자들을 판별해야 하니 그런 어깨보호대가 아주 유용할 것이야.\n\n줄구룹에서 학카르의 졸개들과 싸워 내가 찾는 마력의 보물을 가져오면 그 보답으로 우리 최정예 성자들이 걸치는 어깨보호대를 주기로 하겠네.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 성자의 어깨보호대"},
[85626] = {title = "마력의 보물: 악령술사의 손목띠", objective = "줄구룹에서 고대 학카리 손목갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "악마들을 다룬다는 점에서 흑마법사들은 아주 위험한 길을 걷는 것이지만, 우리 부족의 악령술사들은 여기서 한 발 더 나아간다네. 고대 비전 의식을 통해 악마가 자신에게 들어가도록 하는 것이지. 악마들이 자신들을 완전히 지배하도록 놔두지 않고 내면에서 악마를 사로잡아 악마들의 힘을 흡수해 마음대로 부린다네. 이를 통달할 수 있는 건 오직 아주 극소수뿐이지.\n\n자네가 악령술사의 힘을 배우겠다면 줄구룹에서 마력의 보물을 가져와야 하네. 자, 어서 가 보게.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 악령술사의 손목띠"},
[85627] = {title = "마력의 보물: 악령술사의 어깨보호대", objective = "줄구룹에서 고대 학카리 장식띠를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "악령술사는 마력을 소유하려고만 하지 않고 완전히 통합하려고 한다네. 악마와의 싸움에서 이기지 못한 자들도 꽤 있지. 하지만 적들, 특히 줄구룹에서 오는 녀석들의 위협을 고려해 보면 악령술사가 적에게 퍼부을 수 있는 힘은 그런 희생도 아깝지 않아. 우리를 없애려는 자들을 물리치지 못하면 우리는 살아남을 수 없네. 구루바시 제국의 멸망을 통해 깨닫게 된 것이지.\n\n줄구룹으로 가서 우리가 필요로 하는 마력의 보물을 가져오게나. 그리하면 아주 귀중한 악령술사 물건을 하나 주도록 하지.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 악령술사의 어깨보호대"},
[85628] = {title = "마력의 보물: 악령술사의 로브", objective = "줄구룹에서 고대 학카리 조끼를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족에서 권력의 궁극적 상징은 바로 전투 장비일세. 악령술사의 로브는 고급 룬무늬 옷감과 파괴적인 힘이 담긴 모조를 한 옷감에 융합시켜 만든 것으로, 이 로브의 외관을 보는 자들의 정신은 공포로 가득 찬다고 하네... 특히 악령술사가 마침내 제압하게 되는 악마들은 더욱 그렇지.\n\n줄구룹으로 가서 아주 특수한 마력의 보물을 가져와야 하네. 어려운 일이 되겠지만 성공하면 자네도 확실히 그런 로브를 얻게 될 거야.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 악령술사의 로브"},
[85630] = {title = "마력의 보물: 환영술사의 손목띠", objective = "줄구룹에서 고대 학카리 팔보호구를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "우리 부족의 마법사들은 환영술사들로 알려져 있다네. 주문을 외울 때 강력한 모조를 사용하는데, 종종 부족의 적들을 현혹시키거나 혼란스럽게 만들지!\n\n<사악하게 웃는 알타빔>\n\n적들을 그들 스스로 자신의 광기로 인해 무릎 꿇게 만드는 강한 환영술사를 보면 그야말로 장관일세!\n\n환영술사의 도를 배우고 싶거든 줄구룹으로 가서 내가 원하는 마력의 보물을 가져오게. 그러면 우리 환영술사들이 마법 주문을 사용할 때 착용하는 손목띠를 주도록 하지.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 환영술사의 손목띠"},
[85631] = {title = "마력의 보물: 환영술사의 어깨보호대", objective = "줄구룹에서 고대 학카리 어깨걸이를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "마력은 충분한 힘을 지닌 자가 형상화할 수 있는 천연적이고 근본적인 힘일세. 모조는 우리가 이 힘을 확장한 것인데, 환영술은 그러한 강력한 마력 조작의 한 형태라네. 실제로 있지도 않은 적을 어떻게 이길 수 있겠는가? 우리 잔달라 부족은 이 진리의 위력을 잘 알기에 환영술사를 명예롭게 여긴다네.\n\n줄구룹에서 우리가 필요로 하는 마력의 보물을 가져오게. 그러면 부족의 존경을 얻을 뿐 아니라 우리 최정예 환영술사들이 착용하는 강력한 어깨보호대를 주도록 하지!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 환영술사의 어깨보호대"},
[85632] = {title = "마력의 보물: 환영술사의 로브", objective = "줄구룹에서 고대 학카리 조끼를 구해 가시덤불 골짜기의 요잠바 섬에 있는 천리안 알타빔에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족은 장비로 지위와 권력을 인지한다네. 우리 겉옷은 최고급 재료로 만들고 우리가 사용하는 모조를 혼합해 우릴 아주 강하게 만들지. 그건 환영술사도 마찬가지일세. 그들의 로브는 자신들의 겉모습에 환영의 본질을 형상화한다고들 하지. 전설에 따르면, 그들의 고대 로브는 단 한 번도 그 모습이 똑같았던 적이 없었다고 하네.\n\n내가 자네에게 환영술사의 로브를 하나 주지... 하지만 먼저 부족민들 사이에서 노력을 통해 존경의 위치를 차지해야만 해. 줄구룹에서 마력의 보물을 가져오게!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 환영술사의 로브"},
[85634] = {title = "마력의 보물: 개혁가의 팔보호구", objective = "줄구룹에서 고대 학카리 어깨갑옷을 구해 가시덤불 골짜기의 요잠바 섬에 있는 장님 팔디르에게 가져가야 합니다.\n\n잔달라 부족에게 약간 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족의 개혁가들은 도적들과 유사하지만, 무엇보다 그들은 광기... 혼돈... 그리고 존재의 예측 불가능성을 기꺼이 받아들인답니다. 전장에서 아주 무서운 광경을 만들어 내는 그들은 우리 부족이 분열된 후 찾아온 잔인한 시기에 우리 적들 사이에 혼란과 파괴의 씨를 뿌렸답니다. 그들이 없었다면 우리 부족은 여기 이렇게 존재할 수 없었을 겁니다.\n\n줄구룹에서 내가 찾고 있는 마력의 보물을 가져오면 개혁가가 아끼는 방어구 중 첫 번째 것을 드리도록 하죠. 내면의 광기를 받아들이세요!다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 개혁가의 팔보호구"},
[85635] = {title = "마력의 보물: 개혁가의 어깨보호대", objective = "줄구룹에서 고대 학카리 벨트를 구해 가시덤불 골짜기의 요잠바 섬에 있는 장님 팔디르에게 가져가야 합니다.\n\n잔달라 부족에게 우호적 이상의 평판이어야 합니다.", description = "잔달라 부족 전설의 개혁가들 중에는 광기의 카르바살이라는 자가 있습니다. 전설에 의하면 카르바살이 처음으로 부족의 적들을 마주했을 때 특별히 \"광기의 옷감\"으로 짠 어깨보호대를 사용했다고 합니다. 어깨보호대는 물론 눈에 보이지 않을 정도로 빠르게 휘두르는 두 개의 단검 때문에 그의 모습이 가려졌다고도 합니다. 오늘날의 개혁가들은 자신들의 어깨보호대를 부족 내에서의 지위를 상징하는 물건으로서 아주 소중히 여긴답니다.\n\n내가 찾는 마력의 보물을 가져오시면 당신에게 그런 어깨보호대를 드릴 테니 적들에게 광기를 엮어 넣게 될 겁니다.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 개혁가의 어깨보호대"},
[85636] = {title = "마력의 보물: 개혁가의 튜닉", objective = "줄구룹에서 고대 학카리 아이기스를 구해 가시덤불 골짜기의 요잠바 섬에 있는 장님 팔디르에게 가져가야 합니다.\n\n잔달라 부족에게 매우 우호적 이상의 평판이어야 합니다.", description = "시력을 잃은 지는 오래됐지만 조금도 아깝지 않답니다. 비록 우리 부족 내에서는 몸에 걸치는 장비들이 지위와 존재 이유를 나타낸다고 하지만, 아주 강력한 장비에서는 단순히 눈만으로는 볼 수 없는 힘이 뿜어져 나오지요. 귀하디 귀한 잔달라 개혁가의 튜닉도 예외는 아닌 것이, 그 자비가 집중할 수 있는 혼돈과 광기의 천연 마력이 뿜어져 나오기 때문이지요.\n\n내가 필요로 하는 마력의 보물은 줄구룹에 있습니다. 내가 찾는 것들을 가져오시면 그 전설의 튜닉을 하나 드리도록 하죠... 광기를 발휘하는 자에게는 어울리는 장비지요.다음과 같은 것들을 받습니다:\n\n", progress = nil, completion = nil, rewards = "다음과 같은 것들을 받습니다:\n\n잔달라 개혁가의 튜닉"},
[85658] = {title = "승리의 축제", objective = "힘의 골짜기에서 대군주 룬탁을 찾으십시오.", description = "대군주 룬탁이 힘의 골짜기에서 그대가 오기를 기다리고 있노라.\n\n<경례를 하는 스랄>\n\n오그리마의 영웅이여, 주민들이 너무 오래 기다리게 하지는 말게.퀘스트 완료 시 보상:\n\n", progress = nil, completion = nil, rewards = nil},
[85659] = {title = "대축제", objective = "영웅의 계곡에서 상사 매팅글리를 찾으십시오.", description = "영웅의 계곡으로 가서 상사 매팅글리를 찾도록 하게, <name>. 자네를 기다리고 있을 것이야...", progress = nil, completion = "이렇게 커다란 의식의 주인공이 될 만한 영웅은 흔하게 나오지 않는 법이지요. 자, 축하의 의식을 시작할 수 있도록 보상을 골라보십시오.", rewards = nil},
[85882] = {title = "암흑 호드의 종말", objective = "렌드 블랙핸드의 머리카락을 스톰윈드에 있는 단장 마티아스 쇼에게 가져가야 합니다.", description = "<임무를 완수했습니다. 암흑 호드의 대족장 달렌드 블랙핸드가 당신의 발 앞에 쓰러졌습니다. 머리카락을 챙겨 쇼 단장에게 가져가야 합니다.>", progress = nil, completion = "잘하셨습니다, 용사님. 암흑 호드의 대족장은 죽었고, 공포의 시대는 막을 내렸습니다. 스톰윈드 전체에 당신의 승리를 알리겠습니다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[85883] = {title = "호드를 위하여!", objective = "검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다.", description = "렌드가 감히 검은용군단의 힘만 믿고 엄청난 짓을 꾸미고 있군.\n\n가서 승천의 전당에 이르는 길을 찾도록 하라. 그리고 호드의 이름으로 대족장 렌드 블랙핸드를 찾아내 처치하도록!\n\n<주먹으로 왕좌를 내리치는 스랄>\n\n이곳으로 돌아올 때는 반드시 내게 놈을 처치한 증거를 가져와야 한다. 그대는 호드의 영웅이 되리라.", progress = nil, completion = "그대는 검은바위부족의 군대에 치명적인 피해를 주었다. 대족장을 처치했으니 검은바위부족 군대는 다시 혼란에 빠질 것이다.\n\n그대는 영웅적인 공훈을 세워 칼림도어의 백성에게 큰 영광을 안겨주었다!", rewards = "다음과 같은 것들을 받습니다:\n\n"},
[85964] = {title = "무공 훈장 10개", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[85965] = {title = "무공 훈장 1개", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[85966] = {title = "무공 훈장 10개", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
